INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1, 1, 1, 'بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّح۪يمِ', 'Bismillahir rahmanir rahim.', 'Rəhim, rəhman olan Allahın adı ilədir.', 'بسم الله الرحمن الرحيم'),
(2, 1, 2, 'اَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَۙ', 'El hamdu lillahi rabbil alemin .', 'O həmd Aləmlərin rəbbi olan Allah üçündür.', 'الحمد لله رب العلمين'),
(3, 1, 3, 'اَلرَّحْمٰنِ الرَّح۪يمِۙ', 'Er rahmanir rahim.', 'Rəhim olan Rəhmana', 'الرحمن الرحيم'),
(4, 1, 4, 'مَالِكِ يَوْمِ الدّ۪ينِۜ', 'Maliki yevmid din.', 'Din gününün sahibinə', 'ملك يوم الدين'),
(5, 1, 5, 'اِيَّاكَ نَعْبُدُ وَاِيَّاكَ نَسْتَع۪ينُۜ', 'İyyake na\'budu ve iyyake nestain.', 'Yalnız sənə qul oluruq Yalnız sənə müavin oluruq', 'اياك نعبد واياك نستعين'),
(6, 1, 6, 'اِهْدِنَا الصِّرَاطَ الْمُسْتَق۪يمَۙ', 'İhdinas sıratel mustakim.', 'Bizi hudən et istiqamətçi olan o yola;', 'اهدنا الصرط المستقيم'),
(7, 1, 7, 'صِرَاطَ الَّذ۪ينَ اَنْعَمْتَ عَلَيْهِمْۙ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّٓالّ۪ينَ', 'Sıratallezine en\'amte aleyhim gayril magdubi aleyhim ve lad dallin.', 'Üzərlərində qəzəb edilmişlərin qeyrisi olan və zəlalətçi olmayan o kəslərin yoluna ki, üzərlərində ənam etdin.', 'صرط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين'),
(8, 2, 1, 'الٓمٓ ۚ', 'Elif, lam, mim.', 'Elif. Lam. Mim.', 'الم'),
(9, 2, 2, 'ذٰلِكَ الْكِتَابُ لَا رَيْبَۚۛ ف۪يهِۚۛ هُدًى لِلْمُتَّق۪ينَۙ', 'Zalikel kitabu la reybe fih, huden lil muttekin.', 'Bu Kitap,  mutlak gerçeğin ta kendisidir. O,  muttakiler[1] için hidayettir.[2]', 'ذلك الكتب لا ريب فيه هدي للمتقين'),
(10, 2, 3, 'اَلَّذ۪ينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُق۪يمُونَ الصَّلٰوةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَۙ', 'Ellezine yu\'minune bil gaybi ve yukimunes salate ve mimma razaknahum yunfikun.', 'Onlar; gayba[1] inanırlar,  salatı ikame ederler[2] ve verdiğimiz rızıktan infak[3] ederler.', 'الذين يومنون بالغيب ويقيمون الصلوة ومما رزقنهم ينفقون'),
(11, 2, 4, 'وَالَّذ۪ينَ يُؤْمِنُونَ بِمَٓا اُنْزِلَ اِلَيْكَ وَمَٓا اُنْزِلَ مِنْ قَبْلِكَۚ وَبِالْاٰخِرَةِ هُمْ يُوقِنُونَۜ', 'Vellezine yu\'minune bi ma unzile ileyke ve ma unzile min kablik ve bil ahireti hum yukınun.', 'Onlar,  sana indirilene ve senden önce indirilmiş olanlara inanırlar. Ve onlar,  ahirete de kesin olarak inanırlar.', 'والذين يومنون بما انزل اليك وما انزل من قبلك وبالاخرة هم يوقنون'),
(12, 2, 5, 'اُو۬لٰٓئِكَ عَلٰى هُدًى مِنْ رَبِّهِمْ وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Ulaike ala huden min rabbihim ve ulaike humul muflihun.', 'Onlar,  Rabb\'lerinden bir hidayet üzerindedirler. Kurtuluşa erenler onlardır.', 'اوليك علي هدي من ربهم واوليك هم المفلحون'),
(13, 2, 6, 'اِنَّ الَّذ۪ينَ كَفَرُوا سَوَٓاءٌ عَلَيْهِمْ ءَاَنْذَرْتَهُمْ اَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ', 'İnnellezine keferu sevaun aleyhim e enzertehum em lem tunzirhum la yu\'minun.', 'Şu bir gerçektir ki: Kafirleri[1] uyarsan da uyarmasan da onlar için birdir; inanmazlar.', 'ان الذين كفروا سوا عليهم انذرتهم ام لم تنذرهم لا يومنون'),
(14, 2, 7, 'خَتَمَ اللّٰهُ عَلٰى قُلُوبِهِمْ وَعَلٰى سَمْعِهِمْۜ وَعَلٰٓى اَبْصَارِهِمْ غِشَاوَةٌۘ وَلَهُمْ عَذَابٌ عَظ۪يمٌ۟', 'Hatemallahu ala kulubihim ve ala sem\'ıhim, ve ala ebsarihim gışaveh, ve lehum azabun azim.', 'Allah,  onların[1] kalplerini[2] ve kulaklarını mühürlemiştir. Onların gözlerinde perde vardır. Onları büyük bir azap beklemektedir.', 'ختم الله علي قلوبهم وعلي سمعهم وعلي ابصرهم غشوة ولهم عذاب عظيم'),
(15, 2, 8, 'وَمِنَ النَّاسِ مَنْ يَقُولُ اٰمَنَّا بِاللّٰهِ وَبِالْيَوْمِ الْاٰخِرِ وَمَا هُمْ بِمُؤْمِن۪ينَۢ', 'Ve minen nasi men yekulu amenna billahi ve bil yevmil ahıri ve ma hum bi mu\'minin.', 'Kimi insanlar,  inanmadıkları halde,  Allah\'a ve Ahiret Günü\'ne inandıklarını söylerler.', 'ومن الناس من يقول امنا بالله وباليوم الاخر وما هم بمومنين'),
(16, 2, 9, 'يُخَادِعُونَ اللّٰهَ وَالَّذ۪ينَ اٰمَنُواۚ وَمَا يَخْدَعُونَ اِلَّٓا اَنْفُسَهُمْ وَمَا يَشْعُرُونَۜ', 'Yuhadiunallahe vellezine amenu, ve ma yahdeune illa enfusehum ve ma yeş\'urun.', 'Onlar[1],  Allah\'ı ve inananları aldatmaya çalışıyorlar. Oysa sadece kendilerini aldatıyorlar da bunun ayırdında değiller.', 'يخدعون الله والذين امنوا وما يخدعون الا انفسهم وما يشعرون'),
(17, 2, 10, 'ف۪ي قُلُوبِهِمْ مَرَضٌۙ فَزَادَهُمُ اللّٰهُ مَرَضاًۚ وَلَهُمْ عَذَابٌ اَل۪يمٌۙ بِمَا كَانُوا يَكْذِبُونَ', 'Fi kulubihim maradun, fe zadehumullahu marada ve lehum azabun elimun bi ma kanu yekzibun.', 'Onların[1] kalplerinde hastalık[2] vardır. Allah da bu hastalıklarını arttırmıştır. Bu yalancılıklarından dolayı onlara can yakıcı bir azap vardır.', 'في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون'),
(18, 2, 11, 'وَاِذَا ق۪يلَ لَهُمْ لَا تُفْسِدُوا فِي الْاَرْضِۙ  قَالُٓوا اِنَّمَا نَحْنُ مُصْلِحُونَ', 'Ve iza kile lehum la tufsidu fil ardı, kalu innema nahnu muslihun.', 'Onlara[1],  \"Yeryüzünde bozgunculuk yapmayın.\" denildiğinde,  \"Biz ancak düzelticileriz.\" derler.', 'واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون'),
(19, 2, 12, 'اَلَٓا اِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلٰكِنْ لَا يَشْعُرُونَ', 'E la innehum humul mufsidune ve lakin la yeş\'urun.', 'İyi bilin ki,  onlar bozguncuların ta kendileridir. Fakat bunun ayırdında değiller.', 'الا انهم هم المفسدون ولكن لا يشعرون'),
(20, 2, 13, 'وَاِذَا ق۪يلَ لَهُمْ اٰمِنُوا كَمَٓا اٰمَنَ النَّاسُ قَالُٓوا اَنُؤْمِنُ كَمَٓا اٰمَنَ السُّفَـهَٓاءُۜ  اَلَٓا اِنَّهُمْ هُمُ السُّفَـهَٓاءُ وَلٰكِنْ لَا يَعْلَمُونَ', 'Ve iza kile lehum aminu kema amenen nasu kalu e nu\'minu kema amenes sufehau, e la innehum humus sufehau ve lakin la ya\'lemun.', 'Ne zaman onlara[1],  \"İnanan kimseler gibi inanın.\" dense,  \"Biz,  hiç aklı ermeyenler gibi inanır mıyız?\" derler. İyi bilin ki asıl aklı ermeyenler onlardır; fakat bunun ayırdında değiller.', 'واذا قيل لهم امنوا كما امن الناس قالوا انومن كما امن السفها الا انهم هم السفها ولكن لا يعلمون'),
(21, 2, 14, 'وَاِذَا لَقُوا الَّذٖينَ اٰمَنُوا قَالُٓوا اٰمَنَّاۚ وَاِذَا خَلَوْا اِلٰى شَيَاطٖينِهِمْۙ قَالُٓوا اِنَّا مَعَكُمْۙ اِنَّمَا نَحْنُ مُسْتَهْزِؤُ۫نَ', 'Ve iza lekullezine amenu kalu amenna, ve iza halev ila şeyatinihim, kalu inna meakum, innema nahnu mustehziun.', 'İman edenlerle karşılaştıkları zaman: \"İnandık.\" derler.[1] Şeytanları[2] ile baş başa kaldıkları zaman,  \"Biz,  sizinle beraberiz; onlarla sadece alay ediyoruz.\" derler.', 'واذا لقوا الذين امنوا قالوا امنا واذا خلوا الي شيطينهم قالوا انا معكم انما نحن مستهزون'),
(22, 2, 15, 'اَللّٰهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ ف۪ي طُغْيَانِهِمْ يَعْمَهُونَ', 'Allahu yestehziu bihim ve yemudduhum fi tugyanihim ya\'mehun.', 'Allah da onları[1] alay konusu yapar. Azgınlıkları içinde bocalayıp durmalarına zaman tanır.', 'الله يستهزي بهم ويمدهم في طغينهم يعمهون'),
(23, 2, 16, 'اُو۬لٰٓئِكَ الَّذ۪ينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدٰىۖ فَمَا رَبِحَتْ تِجَارَتُهُمْ وَمَا كَانُوا مُهْتَد۪ينَ', 'Ulaikellezineşterevud dalalete bil huda, fe ma rabihat ticaretuhum ve ma kanu muhtedin.', 'Onlar[1],  doğru yola karşılık sapkınlığı satın almışlardır. Bu ticaretlerinde bir kazanç yoktur. Ve doğru yolu bulamamışlardır.', 'اوليك الذين اشتروا الضللة بالهدي فما ربحت تجرتهم وما كانوا مهتدين'),
(24, 2, 17, 'مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ نَاراًۚ فَلَمَّٓا اَضَٓاءَتْ مَا حَوْلَهُ ذَهَبَ اللّٰهُ بِنُورِهِمْ وَتَرَكَهُمْ ف۪ي ظُلُمَاتٍ لَا يُبْصِرُونَ', 'Meseluhum ke meselillezistevkade nara, fe lemma edaet ma havlehu zeheballahu bi nurihim ve terekehum fi zulumatin la yubsirun.', 'Onların[1] durumu karanlıkta ateş yakan kimselerin durumu gibidir. Ateş,  etraflarını aydınlatır aydınlatmaz,  Allah onların ışığını yok eder ve onları karanlıklar içinde görmez halde bırakır.', 'مثلهم كمثل الذي استوقد نارا فلما اضات ما حوله ذهب الله بنورهم وتركهم في ظلمت لا يبصرون'),
(25, 2, 18, 'صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَرْجِعُونَۙ', 'Summun bukmun umyun fe hum la yerciun.', 'Sağır,  dilsiz ve kördürler[1]. Artık doğru yola dönmezler.', 'صم بكم عمي فهم لا يرجعون'),
(26, 2, 19, 'اَوْ كَصَيِّبٍ مِنَ السَّمَٓاءِ ف۪يهِ ظُلُمَاتٌ وَرَعْدٌ وَبَرْقٌۚ يَجْعَلُونَ اَصَابِعَهُمْ ف۪ٓي اٰذَانِهِمْ مِنَ الصَّوَاعِقِ حَذَرَ الْمَوْتِۜ وَاللّٰهُ مُح۪يطٌ بِالْكَافِر۪ينَ', 'Ev ke sayyibin mines semai fihi zulumatun ve ra\'dun ve berk, yec\'alune esabiahum fi azanihim mines savaiki hazaral mevt, vallahu muhitun bil kafirin.', 'Ya da onların[1] durumu; içinde karanlıklar,  gök gürültüsü ve şimşekler bulunan,  sağanak bir yağmurda; ölüm korkusuyla,  yıldırım sesinden kulaklarını parmaklarıyla tıkayan kimselerin durumuna benzer. Oysaki Allah,  kafirleri[2] her yönden kuşatmıştır.', 'او كصيب من السما فيه ظلمت ورعد وبرق يجعلون اصبعهم في اذانهم من الصوعق حذر الموت والله محيط بالكفرين'),
(27, 2, 20, 'يَكَادُ الْبَرْقُ يَخْطَفُ اَبْصَارَهُمْۜ  كُلَّمَٓا اَضَٓاءَ لَهُمْ مَشَوْا ف۪يهِۙ وَاِذَٓا اَظْلَمَ عَلَيْهِمْ قَامُواۜ وَلَوْ شَٓاءَ اللّٰهُ لَذَهَبَ بِسَمْعِهِمْ وَاَبْصَارِهِمْۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ۟', 'Yekadul berku yahtafu ebsarehum kullema edae lehum meşev fihi, ve iza azleme aleyhim kamu ve lev şaellahu le zehebe bi sem\'ihim ve ebsarihim innallahe ala kulli şey\'in kadir.', 'Şimşek,  neredeyse görmelerini yok edecekti. Şimşek,  aydınlık verince ışığında yürürler; üzerlerine karanlık çökünce de oldukları yerde kalakalırlar. Allah dileseydi onların işitme ve görme yeteneklerini tamamen yok ederdi. Kuşkusuz,  Allah\'ın gücü her şeye yeter.', 'يكاد البرق يخطف ابصرهم كلما اضا لهم مشوا فيه واذا اظلم عليهم قاموا ولو شا الله لذهب بسمعهم وابصرهم ان الله علي كل شي قدير'),
(28, 2, 21, 'يَٓا اَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذ۪ي خَلَقَكُمْ وَالَّذ۪ينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَۙ', 'Ya eyyuhen nasu\'budu rabbekumullezi halakakum vellezine min kablikum leallekum tettekun.', 'Ey insanlar! Sizi ve sizden öncekileri yaratan Rabb\'inize kulluk edin ki takva[1] sahibi olasınız.', 'يايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون'),
(29, 2, 22, 'اَلَّذ۪ي جَعَلَ لَكُمُ الْاَرْضَ فِرَاشاً وَالسَّمَٓاءَ بِنَٓاءًۖ وَاَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً فَاَخْرَجَ بِه۪ مِنَ الثَّمَرَاتِ رِزْقاً لَكُمْۚ فَلَا تَجْعَلُوا لِلّٰهِ اَنْدَاداً وَاَنْتُمْ تَعْلَمُونَ', 'Ellezi ceale lekumul arda firaşen ves semae binaa, ve enzele mines semai maen fe ahrece bihi mines semarati rızkan lekum, fe la tec\'alu lillahi endaden ve entum ta\'lemun.', 'O ki sizin için yeri bir döşek,  göğü de bir bina yaptı ve gökten su indirip onunla size rızık olarak çeşitli ürünler çıkardı. O halde,  Allah\'a bile bile denkler koşmayın.', 'الذي جعل لكم الارض فرشا والسما بنا وانزل من السما ما فاخرج به من الثمرت رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون'),
(30, 2, 23, 'وَاِنْ كُنْتُمْ ف۪ي رَيْبٍ مِمَّا نَزَّلْنَا عَلٰى عَبْدِنَا فَأْتُوا بِسُورَةٍ مِنْ مِثْلِه۪ۖ وَادْعُوا شُهَدَٓاءَكُمْ مِنْ دُونِ اللّٰهِ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve in kuntum fi reybin mimma nezzelna ala abdina fe\'tu bi suretin min mislihi, ved\'u şuhedaekum min dunillahi in kuntum sadıkin.', 'Eğer kulumuza indirdiğimizden kuşku duyuyorsanız,  o zaman ona denk bir sure getirin. Allah\'tan başka bütün tanıklarınızı da çağırın. Eğer doğru söyleyen kimselerseniz!', 'وان كنتم في ريب مما نزلنا علي عبدنا فاتوا بسورة من مثله وادعوا شهداكم من دون الله ان كنتم صدقين'),
(31, 2, 24, 'فَاِنْ لَمْ تَفْعَلُوا وَلَنْ تَفْعَلُوا فَاتَّقُوا النَّارَ الَّت۪ي وَقُودُهَا النَّاسُ وَالْحِجَارَةُۚ اُعِدَّتْ لِلْكَافِر۪ينَ', 'Fe in lem tef\'alu ve len tef\'alu fettekun narelleti vakuduhan nasu vel hicaratu, uiddet lil kafirin.', 'Eğer bunu yapamazsanız -ki asla yapamayacaksınız- o halde Kafirler[1] için hazırlanmış,  yakıtı insanlar ve taşlar olan ateşten korunun.', 'فان لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجارة اعدت للكفرين'),
(32, 2, 25, 'وَبَشِّرِ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ اَنَّ لَهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ كُلَّمَا رُزِقُوا مِنْهَا مِنْ ثَمَرَةٍ رِزْقاًۙ قَالُوا هٰذَا الَّذ۪ي رُزِقْنَا مِنْ قَبْلُ وَاُتُوا بِه۪ مُتَشَابِهاًۜ وَلَهُمْ ف۪يهَٓا اَزْوَاجٌ مُطَهَّرَةٌ وَهُمْ ف۪يهَا خَالِدُونَ', 'Ve beşşirillezine amenu ve amilus salihati enne lehum cennatin tecri min tahtihel enhar, kullema ruziku minha min semeretin rızkan kalu hazellezi ruzıkna min kabl ve utu bihi muteşabiha, ve lehum fiha ezvacun mutahharatun ve hum fiha halidun.', 'İman edip,  salihatı[1] yapanları; içlerinde ırmaklar akan cennetler[2] ile müjdele. Onlara ne zaman yiyecek bir şey sunulsa: \"Bu daha önce rızıklandığımız şeydir.\" derler. Oysa bu onlara benzer olarak verilmiştir. Onlar[3] için arındırılmış eşler vardır. Ve onlar,  orada kalıcıdırlar.', 'وبشر الذين امنوا وعملوا الصلحت ان لهم جنت تجري من تحتها الانهر كلما رزقوا منها من ثمرة رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشبها ولهم فيها ازوج مطهرة وهم فيها خلدون'),
(33, 2, 26, 'اِنَّ اللّٰهَ لَا يَسْتَحْـي۪ٓ اَنْ يَضْرِبَ مَثَلاً مَا بَعُوضَةً فَمَا فَوْقَهَاۜ  فَاَمَّا الَّذ۪ينَ اٰمَنُوا فَيَعْلَمُونَ اَنَّهُ الْحَقُّ مِنْ رَبِّهِمْۚ  وَاَمَّا الَّذ۪ينَ كَفَرُوا فَيَقُولُونَ مَاذَٓا اَرَادَ اللّٰهُ بِهٰذَا مَثَلاًۢ يُضِلُّ بِه۪ كَث۪يراً وَيَهْد۪ي بِه۪ كَث۪يراًۜ وَمَا يُضِلُّ بِه۪ٓ اِلَّا الْفَاسِق۪ينَۙ', 'İnnallahe la yestahyi en yadribe meselen ma beudaten fe ma fevkaha fe emmellezine amenu fe ya\'lemune ennehul hakku min rabbihim, ve emmellezine keferu fe yekulune maza eradallahu bi haza mesela, yudıllu bihi kesiran ve yehdi bihi kesira ve ma yudıllu bihi illel fasıkin.', 'Doğrusu Allah,  bir sivrisineği veya ondan daha küçüğünü örnek olarak vermekten çekinmez. İman edenler,  bunun,  Rabb\'lerinden bir gerçek olduğunu bilirler. Kafirler[1] ise: \"Allah,  bu örnekle neyi amaçlamıştır?\" derler. Allah,  bu örnekle birçok kimseyi saptırır,  birçok kimseyi de doğru yola iletir. Bununla,  ancak fasıkları[2] saptırır.', 'ان الله لا يستحي ان يضرب مثلا ما بعوضة فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفسقين'),
(34, 2, 27, 'اَلَّذ۪ينَ يَنْقُضُونَ عَهْدَ اللّٰهِ مِنْ بَعْدِ م۪يثَاقِه۪ۖ وَيَقْطَعُونَ مَٓا اَمَرَ اللّٰهُ بِه۪ٓ اَنْ يُوصَلَ وَيُفْسِدُونَ فِي الْاَرْضِۜ اُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ', 'Ellezine yenkudune ahdallahi min ba\'di misakıh, ve yaktaune ma emerallahu bihi en yusale ve yufsidune fil ard ulaike humul hasirun.', 'Misaklerinden [1] sonra Allah\'ın ahdini [2] bozanlar; Allah\'ın bağlı kalınmasını istediği şeyle bağlarını koparanlar ve yeryüzünde bozgunculuk yapan kimselerdir. İşte onlar,  hüsrana uğrayacaklardır.', 'الذين ينقضون عهد الله من بعد ميثقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اوليك هم الخسرون'),
(35, 2, 28, 'كَيْفَ تَكْفُرُونَ بِاللّٰهِ وَكُنْتُمْ اَمْوَاتاً فَاَحْيَاكُمْۚ ثُمَّ يُم۪يتُكُمْ ثُمَّ يُحْي۪يكُمْ ثُمَّ اِلَيْهِ تُرْجَعُونَ', 'Keyfe tekfurune billahi ve kuntum emvaten fe ahyakum, summe yumitukum summe yuhyikum summe ileyhi turceun.', 'Allah\'a,  nasıl gerçeğin üzerini örterek nankörlük edersiniz? Sizi ölüler[1] iken var etti,  sonra sizi öldürecek,  sonra tekrar dirilterek kendisine döndürecektir.', 'كيف تكفرون بالله وكنتم اموتا فاحيكم ثم يميتكم ثم يحييكم ثم اليه ترجعون'),
(36, 2, 29, 'هُوَ الَّذ۪ي خَلَقَ لَكُمْ مَا فِي الْاَرْضِ جَم۪يعاً ثُمَّ اسْتَوٰٓى اِلَى السَّمَٓاءِ فَسَوّٰيهُنَّ سَبْعَ سَمٰوَاتٍۜ وَهُوَ بِكُلِّ شَيْءٍ عَل۪يمٌ۟', 'Huvellezi halaka lekum ma fil ardı cemian summesteva iles semai fe sevvahunne seb\'a semavat, ve huve bi kulli şey\'in alim.', 'O ki yeryüzündekilerin tamamını sizin için yarattı. Sonra O,  göğe istiva[1] etti; onları yedi gök halinde düzenledi. O,  Her Şeyi Bilen\'dir.', 'هو الذي خلق لكم ما في الارض جميعا ثم استوي الي السما فسويهن سبع سموت وهو بكل شي عليم'),
(37, 2, 30, 'وَاِذْ قَالَ رَبُّكَ لِلْمَلٰٓئِكَةِ اِنّ۪ي جَاعِلٌ فِي الْاَرْضِ خَل۪يفَةًۜ  قَالُٓوا اَتَجْعَلُ ف۪يهَا مَنْ يُفْسِدُ ف۪يهَا وَيَسْفِكُ الدِّمَٓاءَۚ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَۜ قَالَ اِنّ۪ٓي اَعْلَمُ مَا لَا تَعْلَمُونَ', 'Ve iz kale rabbuke lil melaiketi inni cailun fil ardı halifeh, kalu e tec\'alu fiha men yufsidu fiha ve yesfikud dima, ve nahnu nusebbihu bi hamdike ve nukaddisu lek, kale inni a\'lemu ma la ta\'lemun.', 'Hani! Bir zamanlar Rabb\'in,  meleklere: \"Ben yeryüzünde bir[1] halife[2] tayin[3] edeceğim.\" demişti. Melekler: orada bozgunculuk yapacak,  kan dökecek birisini mi halife[2] yapacaksın? Oysa biz Seni övgü ile yüceltip kutsuyoruz.\" dediler. Allah: \"Ben sizin bilmediklerinizi bilirim.\" dedi.', 'واذ قال ربك للمليكة اني جاعل في الارض خليفة قالوا اتجعل فيها من يفسد فيها ويسفك الدما ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون'),
(38, 2, 31, 'وَعَلَّمَ اٰدَمَ الْاَسْمَٓاءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى الْمَلٰٓئِكَةِ فَقَالَ اَنْبِؤُ۫ن۪ي بِاَسْمَٓاءِ هٰٓؤُ۬لَٓاءِ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve alleme ademel esmae kulleha summe aradahum alel melaiketi fe kale enbiuni bi esmai haulai in kuntum sadikin.', 'Allah,  Âdem\'e bütün isimleri[1] öğretti. Sonra onları meleklere sunup: \"Eğer doğru söyleyenlerden iseniz bunların isimlerini bana bildirin.\" dedi.[2]', 'وعلم ادم الاسما كلها ثم عرضهم علي المليكة فقال انبوني باسما هولا ان كنتم صدقين'),
(39, 2, 32, 'قَالُوا سُبْحَانَكَ لَا عِلْمَ لَنَٓا اِلَّا مَا عَلَّمْتَنَاۜ اِنَّكَ اَنْتَ الْعَل۪يمُ الْحَك۪يمُ', 'Kalu subhaneke la ilme lena illa ma allemtena inneke entel alimul hakim.', 'Melekler de: \"Sen subhansın.[1] Bize öğrettiklerinden başka bizim hiçbir bilgimiz yoktur. Şüphesiz Sen her şeyi gerçeği ile bilensin.\" dediler.', 'قالوا سبحنك لا علم لنا الا ما علمتنا انك انت العليم الحكيم'),
(40, 2, 33, 'قَالَ يَٓا اٰدَمُ اَنْبِئْهُمْ بِاَسْمَٓائِهِمْۚ فَلَمَّٓا اَنْبَاَهُمْ بِاَسْمَٓائِهِمْۙ قَالَ اَلَمْ اَقُلْ لَكُمْ اِنّ۪ٓي اَعْلَمُ غَيْبَ السَّمٰوَاتِ وَالْاَرْضِ وَاَعْلَمُ مَا تُبْدُونَ وَمَا كُنْتُمْ تَكْتُمُونَ', 'Kale ya ademu enbi\'hum bi esmaihim, fe lemma enbeehum bi esmaihim, kale e lem ekul lekum inni a\'lemu gaybes semavati vel ardı ve a\'lemu ma tubdune ve ma kuntum tektumun.', 'Allah: \"Ey Âdem! Bunların isimlerini onlara bildir.\" dedi. Âdem isimleri onlara bildirince,  Allah meleklere: \"Göklerin ve yerin gaybını[1] Ben bilirim; Ben,  sizin açıkladıklarınızı da içinizde gizlediklerinizi de bilirim,  dememiş miydim?\" dedi.', 'قال يادم انبيهم باسمايهم فلما انباهم باسمايهم قال الم اقل لكم اني اعلم غيب السموت والارض واعلم ما تبدون وما كنتم تكتمون'),
(41, 2, 34, 'وَاِذْ قُلْنَا لِلْمَلٰٓئِكَةِ اسْجُدُوا لِاٰدَمَ فَسَجَدُٓوا اِلَّٓا اِبْل۪يسَۜ اَبٰى وَاسْتَكْبَرَ وَكَانَ مِنَ الْكَافِر۪ينَ', 'Ve iz kulna lil melaiketiscudu li ademe fe secedu illa iblis, eba vestekbere ve kane minel kafirin.', 'Sonra meleklere: \"Âdem için secde edin.\"[1] dedik. İblis[2] hariç hemen secde ettiler. O,  yüz çevirip büyüklük tasladı. O kafirlerdendi.[3]', 'واذ قلنا للمليكة اسجدوا لادم فسجدوا الا ابليس ابي واستكبر وكان من الكفرين'),
(42, 2, 35, 'وَقُلْنَا يَٓا اٰدَمُ اسْكُنْ اَنْتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَداً حَيْثُ شِئْتُمَاۖ وَلَا تَقْرَبَا هٰذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِم۪ينَ', 'Ve kulna ya ademuskun ente ve zevcukel cennete ve kula minha ragaden haysu şi\'tuma ve la takraba hazihiş şecerete fe tekuna minez zalimin.', 'Dedik ki: \"Ey Âdem! Eşinle birlikte cennette[1] oturun. Orada dilediğiniz her şeyden bol bol yiyin. Fakat şu şecereye[2] yaklaşmayın; yoksa haksızlık yapmış olursunuz.', 'وقلنا يادم اسكن انت وزوجك الجنة وكلا منها رغدا حيث شيتما ولا تقربا هذه الشجرة فتكونا من الظلمين'),
(43, 2, 36, 'فَاَزَلَّهُمَا الشَّيْطَانُ عَنْهَا فَاَخْرَجَهُمَا مِمَّا كَانَا ف۪يهِۖ وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۚ وَلَكُمْ فِي الْاَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ اِلٰى ح۪ينٍ', 'Fe ezellehumaş şeytanu anha fe ahrecehuma mimma kana fih, ve kulnahbitu ba\'dukum li ba\'din aduvv, ve lekum fil ardı mustekarrun ve metaun ila hin.', 'Fakat şeytan onları,  oradan kaydırdı. Böylece ikisini de içinde bulundukları durumdan çıkardı. Biz de: \"Birbirinize düşman olarak inin.[1] Yeryüzü,  belli bir süreye kadar size barınak ve geçinme yeri olacak.\" dedik.', 'فازلهما الشيطن عنها فاخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتع الي حين'),
(44, 2, 37, 'فَتَلَقّٰٓى اٰدَمُ مِنْ رَبِّه۪ كَلِمَاتٍ فَتَابَ عَلَيْهِۜ اِنَّهُ هُوَ التَّوَّابُ الرَّح۪يمُ', 'Fe telekka ademu min rabbihi kelimatin fe tabe aleyh, innehu huvet tevvabur rahim.', 'Derken Âdem,  Rabb\'inden kelimeler[1] aldı. Böylece,  Âdem\'in tevbesini kabul etti. Kuşkusuz O,  Tevbeleri Kabul Eden\'dir,  Rahmeti Kesintisiz\'dir.', 'فتلقي ادم من ربه كلمت فتاب عليه انه هو التواب الرحيم'),
(45, 2, 38, 'قُلْنَا اهْبِطُوا مِنْهَا جَم۪يعاًۚ فَاِمَّا يَأْتِيَنَّكُمْ مِنّ۪ي هُدًى فَمَنْ تَبِعَ هُدَايَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Kulnahbitu minha cemia, fe imma ye\'tiyennekum minni hudenfe men tebia hudaye fe la havfun aleyhim ve la hum yahzenun.', '\"Hepiniz oradan inin[1] dedik. Ben\'den bir hidayet[2] geldiğinde kim hidayetime uyarsa,  artık onlara korku yoktur ve onlar üzülmeyeceklerdir.', 'قلنا اهبطوا منها جميعا فاما ياتينكم مني هدي فمن تبع هداي فلا خوف عليهم ولا هم يحزنون'),
(46, 2, 39, 'وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَٓا اُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ۟', 'Vellezine keferu ve kezzebu bi ayatina ulaike ashabun nar, hum fiha halidun.', 'Ayetlerimizi küfredip[1] yalanlayanlar,  Cehennemliktirler. Ve onlar,  orada sürekli kalacaklardır.', 'والذين كفروا وكذبوا بايتنا اوليك اصحب النار هم فيها خلدون'),
(47, 2, 40, 'يَا بَن۪ٓي اِسْرَٓائ۪لَ اذْكُرُوا نِعْمَتِيَ الَّت۪ٓي اَنْعَمْتُ عَلَيْكُمْ وَاَوْفُوا بِعَهْد۪ٓي اُو۫فِ بِعَهْدِكُمْ وَاِيَّايَ فَارْهَبُونِ', 'Ya beni israilezkuru ni\'metiyelleti en\'amtu aleykum ve evfu bi ahdi ufi bi ahdikum ve iyyaye ferhebun.', 'Ey İsrailoğulları! Size bağışladığım nimetimi anımsayın. Bana verdiğiniz sözü tutun ki Ben de size verdiğim sözü yerine getireyim. Ve yalnızca,  Bana karşı gelmekten sakının.', 'يبني اسريل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم وايي فارهبون'),
(48, 2, 41, 'وَاٰمِنُوا بِمَٓا اَنْزَلْتُ مُصَدِّقاً لِمَا مَعَكُمْ وَلَا تَكُونُٓوا اَوَّلَ  كَافِرٍ بِه۪ۖ وَلَا تَشْتَرُوا بِاٰيَات۪ي ثَمَناً قَل۪يلاًۘ وَاِيَّايَ فَاتَّقُونِ', 'Ve aminu bi ma enzeltu musaddikan li ma meakum ve la tekunu evvele kafirin bih, ve la teşteru bi ayati semenen kalilen ve iyyaye fettekuni.', 'Yanınızdakini \"tasdik edici\" olarak gönderdiğimize inanın. Onu Küfr edenlerin ilki siz olmayın. Ayetlerimi az bir değere değişmeyin. Ve Bana karşı takvalı olun.', 'وامنوا بما انزلت مصدقا لما معكم ولا تكونوا اول كافر به ولا تشتروا بايتي ثمنا قليلا وايي فاتقون'),
(49, 2, 42, 'وَلَا تَلْبِسُوا الْحَقَّ بِالْبَاطِلِ وَتَكْتُمُوا الْحَقَّ وَاَنْتُمْ تَعْلَمُونَ', 'Ve la telbisul hakka bil batılı ve tektumul hakka ve entum ta\'lemun.', '\"Hakk\'ı Batıl\'la\"[1] karıştırıp,  bile bile \"Hakk\'ı\" gizlemeyin.', 'ولا تلبسوا الحق بالبطل وتكتموا الحق وانتم تعلمون'),
(50, 2, 43, 'وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَارْكَعُوا مَعَ الرَّاكِع۪ينَ', 'Ve ekimus salate ve atuz zekate verkeu mear rakiin.', 'Salatı ikame edin,  zekatı yapın.[1] Ve ruku edenlerle birlikte ruku edin.[2]', 'واقيموا الصلوة واتوا الزكوة واركعوا مع الركعين'),
(51, 2, 44, 'اَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ اَنْفُسَكُمْ وَاَنْتُمْ تَتْلُونَ الْكِتَابَۜ اَفَلَا تَعْقِلُونَ', 'E te\'murunen nase bil birri ve tensevne enfusekum ve entum tetlunel kitab e fe la ta\'kılun.', 'İnsanlara birr[1] olmalarını buyuruyorsunuz da kendinizi unutuyor musunuz? Oysa Kitap\'ı da okuyorsunuz. Hala aklınızı kullanmayacak mısınız?', 'اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتب افلا تعقلون'),
(52, 2, 45, 'وَاسْتَع۪ينُوا بِالصَّبْرِ وَالصَّلٰوةِۜ وَاِنَّهَا لَكَب۪يرَةٌ اِلَّا عَلَى الْخَاشِع۪ينَۙ', 'Vesteinu bis sabri ves salat, ve inneha le kebiretun illa alel haşiin.', 'Sabır[1] ve salatla[2] yardım isteyin. Kuşkusuz bu içtenlikle itaat edenlerden başkasına ağır gelir.', 'واستعينوا بالصبر والصلوة وانها لكبيرة الا علي الخشعين'),
(53, 2, 46, 'اَلَّذ۪ينَ يَظُنُّونَ اَنَّهُمْ مُلَاقُوا رَبِّهِمْ وَاَنَّهُمْ اِلَيْهِ رَاجِعُونَ۟', 'Ellezine yezunnune ennehum mulaku rabbihim ve ennehum ileyhi raciun.', 'Onlar ki: Rabb\'lerine kavuşacaklarını ve kesinlikle O\'na döneceklerini bilirler.', 'الذين يظنون انهم ملقوا ربهم وانهم اليه رجعون'),
(54, 2, 47, 'يَا بَن۪ٓي اِسْرَٓائ۪لَ اذْكُرُوا نِعْمَتِيَ الَّت۪ٓي اَنْعَمْتُ عَلَيْكُمْ وَاَنّ۪ي فَضَّلْتُكُمْ عَلَى الْعَالَم۪ينَ', 'Ya beni israilezkuru ni\'metiyelleti en\'amtu aleykum ve enni faddaltukum alel alemin.', 'Ey İsrailoğulları! Size verdiğim nimetimi ve size alemler[1] üzerinde lütufta bulunduğumu hatırlayın.', 'يبني اسريل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين'),
(55, 2, 48, 'وَاتَّقُوا يَوْماً لَا تَجْز۪ي نَفْسٌ عَنْ نَفْسٍ شَيْـٔاً وَلَا يُقْبَلُ مِنْهَا شَفَاعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنْصَرُونَ', 'Vetteku yevmen la teczi nefsun an nefsin şey\'en ve la yukbelu minha şefaatun ve la yu\'hazu minha adlun ve la hum yunsarun.', 'Öyle bir günden korunup sakının ki: Hiç kimse bir başkasına yardım edemez. Kimseden şefaat[1] kabul edilmez. Kimseden fideye de alınmaz. Kimseye yardım da edilmez.', 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها شفعة ولا يوخذ منها عدل ولا هم ينصرون'),
(56, 2, 49, 'وَاِذْ نَجَّيْنَاكُمْ مِنْ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُٓوءَ الْعَذَابِ يُذَبِّحُونَ اَبْنَٓاءَكُمْ وَيَسْتَحْيُونَ نِسَٓاءَكُمْۜ وَف۪ي ذٰلِكُمْ بَلَٓاءٌ مِنْ رَبِّكُمْ عَظ۪يمٌ', 'Ve iz necceynakum min ali fir\'avne yesumunekum suel azabi yuzebbihune ebnaekum ve yestahyune nisaekum ve fi zalikum belaun min rabbikum azim.', 'Hatırlayın! Sizi,  kadınlarınızı sağ bırakıp,  oğullarınızı boğazlayarak,  azabın en kötüsüne uğratan Firavun \'un adamlarından kurtarmıştık. Bunda,  sizin için Rabb\'inizden büyük bir sınav vardı.', 'واذ نجينكم من ال فرعون يسومونكم سو العذاب يذبحون ابناكم ويستحيون نساكم وفي ذلكم بلا من ربكم عظيم'),
(57, 2, 50, 'وَاِذْ فَرَقْنَا بِكُمُ الْبَحْرَ فَاَنْجَيْنَاكُمْ وَاَغْرَقْـنَٓا اٰلَ فِرْعَوْنَ وَاَنْتُمْ تَنْظُرُونَ', 'Ve iz farakna bikumul bahre fe enceynakum ve agrakna ale fir\'avne ve entum tenzurun.', 'Hatırlayın! Denizi yararak sizi kurtarmış,  gözlerinizin önünde Firavun taraftarlarını denizde boğmuştuk.', 'واذ فرقنا بكم البحر فانجينكم واغرقنا ال فرعون وانتم تنظرون'),
(58, 2, 51, 'وَاِذْ وٰعَدْنَا مُوسٰٓى اَرْبَع۪ينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِه۪ وَاَنْتُمْ ظَالِمُونَ', 'Ve iz vaadna musa erbaine leyleten summettehaztumul icle min ba\'dihi ve entum zalimun.', 'Hatırlayın! Musa ile kırk gece için sözleşmiştik. Sonra siz,  onun arkasından buzağı yaparak[1] zalimleştiniz.', 'واذ وعدنا موسي اربعين ليلة ثم اتخذتم العجل من بعده وانتم ظلمون'),
(59, 2, 52, 'ثُمَّ عَفَوْنَا عَنْكُمْ مِنْ بَعْدِ ذٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'Summe afevna ankum min ba\'di zalike leallekum teşkurun.', 'Sonra,  bunun ardından,  belki şükredersiniz diye sizi affettik.', 'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون'),
(60, 2, 53, 'وَاِذْ اٰتَيْنَا مُوسَى الْكِتَابَ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', 'Ve iz ateyna musal kitabe vel furkane leallekum tehtedun.', 'Doğru yolu bulasınız diye,  Musa\'ya Kitap\'ı ve Furkan\'ı[1] verdik.', 'واذ اتينا موسي الكتب والفرقان لعلكم تهتدون'),
(61, 2, 54, 'وَاِذْ قَالَ مُوسٰى لِقَوْمِه۪ يَا قَوْمِ اِنَّكُمْ ظَلَمْتُمْ اَنْفُسَكُمْ بِاتِّخَاذِكُمُ الْعِجْلَ فَتُوبُٓوا اِلٰى بَارِئِكُمْ فَاقْتُلُٓوا اَنْفُسَكُمْۜ  ذٰلِكُمْ خَيْرٌ لَكُمْ عِنْدَ بَارِئِكُمْۜ  فَتَابَ عَلَيْكُمْۜ  اِنَّهُ هُوَ التَّوَّابُ الرَّح۪يمُ', 'Ve iz kale musa li kavmihi ya kavmi innekum zalemtum enfusekum bittihazikumul icle fe tubu ila bariikum faktulu enfusekum zalikum hayrun lekum inde bariikum fe tabe aleykum innehu huvet tevvabur rahim.', 'Hatırlayın! Musa,  halkına: \"Ey halkım! Siz buzağıyı edinmekle[1] kuşkusuz kendinize zulmettiniz. Hemen tevbe edin ve böylece nefislerinizi öldürün.[2] Bu Bari\'nizin[3] yanında sizin için hayırlı olandır.\" demişti. Sonra da O,  tevbenizi kabul etmişti. Kuşkusuz O,  Tevbeleri Kabul Eden\'dir,  Rahmeti Kesintisiz\'dir.', 'واذ قال موسي لقومه يقوم انكم ظلمتم انفسكم باتخاذكم العجل فتوبوا الي باريكم فاقتلوا انفسكم ذلكم خير لكم عند باريكم فتاب عليكم انه هو التواب الرحيم'),
(62, 2, 55, 'وَاِذْ قُلْتُمْ يَا مُوسٰى لَنْ نُؤْمِنَ لَكَ حَتّٰى نَرَى اللّٰهَ جَهْرَةً فَاَخَذَتْكُمُ الصَّاعِقَةُ وَاَنْتُمْ تَنْظُرُونَ', 'Ve iz kultum ya musa len nu\'mine leke hatta nerallahe cehreten fe ehazetkumus saikatu ve entum tenzurun.', 'Hani siz: \"Ey Musa! Allah\'ı açıkça görmedikçe sana asla inanmayız.\" demiştiniz de o an,  bakıp dururken,  sizi yıldırım gürültüsü yakalamıştı.', 'واذ قلتم يموسي لن نومن لك حتي نري الله جهرة فاخذتكم الصعقة وانتم تنظرون'),
(63, 2, 56, 'ثُمَّ بَعَثْنَاكُمْ مِنْ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'Summe beasnakum min ba\'di mevtikum leallekum teşkurun.', 'Sonra,  şükredesiniz diye ölümünüzün[1] ardından sizi dirilttik[2].', 'ثم بعثنكم من بعد موتكم لعلكم تشكرون'),
(64, 2, 57, 'وَظَلَّلْنَا عَلَيْكُمُ الْغَمَامَ وَاَنْزَلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوٰىۜ   كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْۜ وَمَا ظَلَمُونَا وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'Ve zallelna aleykumul gamame ve enzelna aleykumul menne ves selva kulu min tayyibati ma razaknakum ve ma zalemuna ve lakin kanu enfusehum yazlimun.', 'Ve bulutları üzerinize gölge yaptık. Size menn[1] ve bıldırcın bağışladık.[2] \"Size rızık olarak verdiklerimizin temiz olanlarından yiyin.\" dedik. Onlar,  Bize[3] zulmetmediler,  fakat kendilerine zulmediyorlardı.', 'وظللنا عليكم الغمام وانزلنا عليكم المن والسلوي كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوا انفسهم يظلمون'),
(65, 2, 58, 'وَاِذْ قُلْنَا ادْخُلُوا هٰذِهِ الْقَرْيَةَ فَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ رَغَداً وَادْخُلُوا الْبَابَ سُجَّداً وَقُولُوا حِطَّةٌ نَغْفِرْ لَكُمْ خَطَايَاكُمْۜ وَسَنَز۪يدُ الْمُحْسِن۪ينَ', 'Ve iz kulnadhulu hazihil karyete fe kulu minha haysu şi\'tum ragaden vedhulul babe succeden ve kulu hıttatun nagfir lekum hatayakum ve senezidul muhsinin.', 'Hani: \"Şu şehre girin,  orada dilediğinizden bol bol yiyin. O kapıdan secde[1] ederek girin. Ve \"bizi bağışla\" deyin ki Biz de yanlışlarınızı bağışlayalım. İyilik yapanlara daha fazlasını vereceğiz.\" demiştik.', 'واذ قلنا ادخلوا هذه القرية فكلوا منها حيث شيتم رغدا وادخلوا الباب سجدا وقولوا حطة نغفر لكم خطيكم وسنزيد المحسنين'),
(66, 2, 59, 'فَبَدَّلَ الَّذ۪ينَ ظَلَمُوا قَوْلاً غَيْرَ الَّذ۪ي ق۪يلَ لَهُمْ فَاَنْزَلْنَا عَلَى الَّذ۪ينَ ظَلَمُوا رِجْزاً مِنَ السَّمَٓاءِ بِمَا كَانُوا يَفْسُقُونَ۟', 'Fe beddelellezine zalemu kavlen gayrellezi kile lehum fe enzelna alellezine zalemu riczen mines semai bima kanu yefsukun.', 'Fakat zalimler,  sözü,  söylenenden başka bir şekle soktular. O zalimlere,  doğru yoldan sapmalarına karşılık gökten bir azap indirdik.', 'فبدل الذين ظلموا قولا غير الذي قيل لهم فانزلنا علي الذين ظلموا رجزا من السما بما كانوا يفسقون'),
(67, 2, 60, 'وَاِذِ اسْتَسْقٰى مُوسٰى لِقَوْمِه۪ فَقُلْنَا اضْرِبْ بِعَصَاكَ الْحَجَرَۜ فَانْفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْناًۜ قَدْ عَلِمَ كُلُّ اُنَاسٍ مَشْرَبَهُمْۜ كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللّٰهِ وَلَا تَعْثَوْا فِي الْاَرْضِ مُفْسِد۪ينَ', 'Ve izisteska musa li kavmihi fe kulnadrib bi asakel hacer fenfeceret minhusneta aşrete ayna, kad alime kullu unasin meşrebehum kulu veşrebu min rızkıllahi ve la ta\'sev fil ardı mufsidin.', 'Hani! Musa,  halkı için su istemişti. Biz de demiştik ki: \"Asanla kayaya vur.\" Bunun üzerine kayadan on iki göz su fışkırmıştı. Her grup hangi kaynaktan içeceğini bilmişti. Allah\'ın verdiği rızıktan yiyin,  için fakat asilik yaparak yeryüzünde bozgunculuk çıkarmayın.', 'واذ استسقي موسي لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشرة عينا قد علم كل اناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الارض مفسدين'),
(68, 2, 61, 'وَاِذْ قُلْتُمْ يَا مُوسٰى لَنْ نَصْبِرَ عَلٰى طَعَامٍ وَاحِدٍ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنْبِتُ الْاَرْضُ مِنْ بَقْلِهَا وَقِثَّٓائِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۜ قَالَ اَتَسْتَبْدِلُونَ الَّذ۪ي هُوَ اَدْنٰى بِالَّذ۪ي هُوَ خَيْرٌۜ اِهْبِطُوا مِصْراً فَاِنَّ لَكُمْ مَا سَاَلْتُمْۜ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَبَٓاؤُ۫ بِغَضَبٍ مِنَ اللّٰهِۜ ذٰلِكَ بِاَنَّهُمْ كَانُوا يَكْفُرُونَ بِاٰيَاتِ اللّٰهِ وَيَقْتُلُونَ النَّبِيّ۪نَ بِغَيْرِ الْحَقِّۜ ذٰلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ۟', 'Ve iz kultum ya musa len nasbira ala taamin vahidin fed\'u lena rabbeke yuhric lena mimma tunbitulardu min bakliha ve kıssaiha ve fumiha ve adesiha ve basaliha, kale e testebdilunellezi huve edna billezi huve hayr, ihbitu mısran fe inne lekum ma seeltum ve duribet aleyhimuz zilletu vel meskenetu ve bau bi gadabin minallah, zalike bi ennehum kanu yekfurune bi ayatillahi ve yaktulunen nebiyyine bi gayril hak, zalike bi ma asav ve kanu ya\'tedun.', 'Hani! Musa\'ya: \"Ey Musa,  asla tek çeşit yiyeceğe dayanamayız. Rabb\'inden bizim için yerden çıkan ürünlerden; sebzesinden,  acurundan,  sarımsağından,  mercimeğinden,  soğanından çıkarmasını iste.\" demiştiniz. Musa da: \"Daha değerli olanı[1] daha değersiz olanla[2] değiştirmek mi istiyorsunuz? O halde şehre inin; sizin istedikleriniz orada var.\" dedi. Böylece,  onların üzerine alçaklık ve yoksulluk damgası vuruldu. Ve Allah\'ın gazabına uğradılar. Bu,  Allah\'ın ayetlerine inanmadıklarından ve nebilerini haksız yere öldürmelerindendi. Bütün bunlar,  onların asileşip haddi aşmalarındandır.', 'واذ قلتم يموسي لن نصبر علي طعام وحد فادع لنا ربك يخرج لنا مما تنبت الارض من بقلها وقثايها وفومها وعدسها وبصلها قال اتستبدلون الذي هو ادني بالذي هو خير اهبطوا مصرا فان لكم ما سالتم وضربت عليهم الذلة والمسكنة وباو بغضب من الله ذلك بانهم كانوا يكفرون بايت الله ويقتلون النبين بغير الحق ذلك بما عصوا وكانوا يعتدون'),
(69, 2, 62, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَالَّذ۪ينَ هَادُوا وَالنَّصَارٰى وَالصَّابِـ۪ٔينَ مَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَعَمِلَ صَالِحاً فَلَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۖ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'İnnellezine amenu vellezine hadu ven nasara ves sabiine men amene billahi vel yevmil ahiri ve amile salihan fe lehum ecruhum inde rabbihim, ve la havfun aleyhim ve la hum yahzenun.', 'İman edenler,  Yahudiler,  Nasraniler[1] ve Sabiiler; kim Allah\'a ve Ahiret Günü\'ne iman edip[2] salihatı yaptı ise[3]ödüllerini Rabb\'leri verecektir. Ve onlar için korku yoktur ve onlar üzülmeyeceklerdir.', 'ان الذين امنوا والذين هادوا والنصري والصبين من امن بالله واليوم الاخر وعمل صلحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون'),
(70, 2, 63, 'وَاِذْ اَخَذْنَا م۪يثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَۜ خُذُوا مَٓا اٰتَيْنَاكُمْ بِقُوَّةٍ وَاذْكُرُوا مَا ف۪يهِ لَعَلَّكُمْ تَتَّقُونَ', 'Ve iz ehazna misakakum ve refa\'na fevkakumut tur huzu ma ateynakum bi kuvvetin vezkuru ma fihi leallekum tettekun.', 'Hani bir zamanlar,  takva sahibi[1] olmanız için,  size verdiğimiz şeylere kuvvetle sarılıp kendinize mal etmek ve içindekilerini sürekli aklınızda tutmanız konusunda sizden söz almıştık. Ve Tur\'u[2] üzerinize kaldırmıştık.', 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما اتينكم بقوة واذكروا ما فيه لعلكم تتقون'),
(71, 2, 64, 'ثُمَّ تَوَلَّيْتُمْ مِنْ بَعْدِ ذٰلِكَۚ فَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ لَكُنْتُمْ مِنَ الْخَاسِر۪ينَ', 'Summe tevelleytum min ba\'di zalik, fe lev la fadlullahi aleykum ve rahmetuhu le kuntum minel hasirin.', 'Yine de yüz çevirdiniz. Eğer Allah\'ın iyilikseverliği ve bağışlayıcılığı olmasaydı elbette kaybedenlerden olurdunuz.', 'ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخسرين'),
(72, 2, 65, 'وَلَقَدْ عَلِمْتُمُ الَّذ۪ينَ اعْتَدَوْا مِنْكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِـ۪ٔينَۚ', 'Ve lekad alimtumullezine\'tedev minkum fis sebti fe kulna lehum kunu kıradeten hasiin.', 'Elbette siz,  cumartesi yasağını çiğnemekle hadlerini aşanları biliyorsunuz. Bu nedenle onlara,  \"Düşkün maymunlar olun[1].\" dedik.', 'ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قردة خسين'),
(73, 2, 66, 'فَجَعَلْنَاهَا نَكَالاً لِمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِلْمُتَّق۪ينَ', 'Fe cealnaha nekalen li ma beyne yedeyha ve ma halfeha ve mev\'ızaten lil muttakin.', 'Biz bunu,  yanında onlara ve onlardan sonra gelecek kuşaklara ibret; muttakilere[1] de bir öğüt olarak yaptık.', 'فجعلنها نكلا لما بين يديها وما خلفها وموعظة للمتقين'),
(74, 2, 67, 'وَاِذْ قَالَ مُوسٰى لِقَوْمِه۪ٓ اِنَّ اللّٰهَ يَأْمُرُكُمْ اَنْ تَذْبَحُوا بَقَرَةًۜ قَالُٓوا اَتَتَّخِذُنَا هُزُواًۜ قَالَ اَعُوذُ بِاللّٰهِ اَنْ اَكُونَ مِنَ الْجَاهِل۪ينَ', 'Ve iz kale musa li kavmihi innallahe ye\'murukum en tezbehu bakarah, kalu e tettehızuna huzuva, kale euzu billahi en ekune minel cahilin.', 'Hani,  Musa halkına: \"Allah,  sizden bir sığır kesmenizi istiyor.\" demişti. Onlar da: \"Sen bizimle alay mı ediyorsun.\" dediler. Musa; \"Cahillerden olmaktan,  Allah\'a sığınırım.\" dedi.', 'واذ قال موسي لقومه ان الله يامركم ان تذبحوا بقرة قالوا اتتخذنا هزوا قال اعوذ بالله ان اكون من الجهلين'),
(75, 2, 68, 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا هِيَۜ قَالَ اِنَّهُ يَقُولُ اِنَّهَا بَقَرَةٌ لَا فَارِضٌ وَلَا بِكْرٌۜ عَوَانٌ بَيْنَ ذٰلِكَۜ فَافْعَلُوا مَا تُؤْمَرُونَ', 'Kalud\'u lena rabbeke yubeyyin lena ma hiy, kale innehu yekulu inneha bakaratun la faridun ve la bikr, avanun beyne zalik fef\'alu ma tu\'merun.', 'Onlar: \"Bizim için Rabb\'ine söyle,  onun nasıl bir sığır olduğunu açıklasın.\" dediler. Musa,  \"Allah,  onun ne tam yaşlı ne de yavru; ikisinin arasında bir yaşta olduğunu söylüyor; öyleyse sizden isteneni yapın.\" dedi.', 'قالوا ادع لنا ربك يبين لنا ما هي قال انه يقول انها بقرة لا فارض ولا بكر عوان بين ذلك فافعلوا ما تومرون'),
(76, 2, 69, 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا لَوْنُهَاۜ قَالَ اِنَّهُ يَقُولُ اِنَّهَا بَقَرَةٌ صَفْرَٓاءُۙ فَاقِعٌ لَوْنُهَا تَسُرُّ النَّاظِر۪ينَ', 'Kalud\'u lena rabbeke yubeyyin lena ma levnuha, kale innehu yekulu inneha bakaratun safrau, fakiun levnuha tesurrun nazırin.', 'Onlar: \"Bizim için Rabb\'ine söyle,  onun rengi nedir; bize bildirsin.\" dediler. Musa: \"Allah; onun parlak sarı renkte,  bakanlara keyif veren bir sığır olduğunu söylüyor.\" dedi.', 'قالوا ادع لنا ربك يبين لنا ما لونها قال انه يقول انها بقرة صفرا فاقع لونها تسر النظرين'),
(77, 2, 70, 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا هِيَۙ اِنَّ الْبَقَرَ تَشَابَهَ عَلَيْنَاۜ وَاِنَّٓا اِنْ شَٓاءَ اللّٰهُ لَمُهْتَدُونَ', 'Kalud\'u lena rabbeke yubeyyin lena ma hiye, innel bakara teşabehe aleyna, ve inna in şaallahu le muhtedun.', 'Yine onlar: \"Bizim için Rabb\'ine sor; onun niteliğini açıklasın. Zira bizce sığırların hepsi birbirine benziyorlar; eğer Allah dilerse biz doğru olanı bulmuş oluruz.\" dediler.', 'قالوا ادع لنا ربك يبين لنا ما هي ان البقر تشبه علينا وانا ان شا الله لمهتدون'),
(78, 2, 71, 'قَالَ اِنَّهُ يَقُولُ اِنَّهَا بَقَرَةٌ لَا ذَلُولٌ تُث۪يرُ الْاَرْضَ وَلَا تَسْقِي الْحَرْثَۚ مُسَلَّمَةٌ لَا شِيَةَ ف۪يهَاۜ قَالُوا الْـٰٔنَ جِئْتَ بِالْحَقِّۜ فَذَبَحُوهَا وَمَا كَادُوا يَفْعَلُونَ۟', 'Kale innehu yekulu inneha bakaratun la zelulun tusirul arda ve la teskıl hars, musellemetun la şiyete fiha kalul\'ane ci\'te bil hakk, fe zebehuha ve ma kadu yef\'alun.', 'Musa: \"Allah,  onun ekin sulayarak,  çifte koşularak yıpranmamış; alacası olmayan,  kusursuz bir sığır olduğunu söylüyor.\" dedi. Onlar: \"İşte şimdi gerçeği bildirdin.\" dediler. Ve nihayet sığırı boğazladılar. Neredeyse bunu yapmayacaklardı.*', 'قال انه يقول انها بقرة لا ذلول تثير الارض ولا تسقي الحرث مسلمة لا شية فيها قالوا الن جيت بالحق فذبحوها وما كادوا يفعلون'),
(79, 2, 72, 'وَاِذْ قَتَلْتُمْ نَفْساً فَادّٰرَءْتُمْ ف۪يهَاۜ وَاللّٰهُ مُخْرِجٌ مَا كُنْتُمْ تَكْتُمُونَۚ', 'Ve iz kateltum nefsen feddare\'tum fiha vallahu muhricun ma kuntum tektumun.', 'Hani! Siz,  bir kimseyi öldürmüştünüz de birbirinizle atışmıştınız. Oysa Allah,  gizlediğiniz şeyi ortaya çıkarandır.', 'واذ قتلتم نفسا فادرتم فيها والله مخرج ما كنتم تكتمون'),
(80, 2, 73, 'فَقُلْنَا اضْرِبُوهُ بِبَعْضِهَاۜ   كَذٰلِكَ يُحْـيِ اللّٰهُ الْمَوْتٰى وَيُر۪يكُمْ اٰيَاتِه۪ لَعَلَّكُمْ تَعْقِلُونَ', 'Fe kulnadribuhu bi ba\'dıha kezalike yuhyillahul mevta ve yurikum ayatihi leallekum ta\'kılun.', '\"Onun bir kısmı ile ona vurun\" dedik.[1] İşte Allah,  böylece ölüleri dirilterek ayetlerini[2] size gösterir. Umulur ki gerçeği kavrarsınız.', 'فقلنا اضربوه ببعضها كذلك يحي الله الموتي ويريكم ايته لعلكم تعقلون'),
(81, 2, 74, 'ثُمَّ قَسَتْ قُلُوبُكُمْ مِنْ بَعْدِ ذٰلِكَ فَهِيَ كَالْحِجَارَةِ اَوْ اَشَدُّ قَسْوَةًۜ وَاِنَّ مِنَ الْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ الْاَنْهَارُۜ وَاِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْمَٓاءُۜ وَاِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اللّٰهِۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Summe kaset kulubukum min ba\'di zalike fe hiye kel hıcareti ev eşeddu kasveh, ve inne minel hıcareti lema yetefecceru minhul enhar, ve inne minha lema yeşşakkaku fe yahrucu minhul mau, ve inne minha lemayehbitu min haşyetillah, ve mallahu bi gafilin amma ta\'melun.', 'Sonra kalpleriniz yine katılaştı; kaya gibi,  hatta kayadan da katı. Zira öyle kayalar var ki içinden nehirler fışkırır,  yine öyle kayalar vardır ki yarılıp bağrından su çıkar. Yine öyleleri vardır ki Allah\'a duyduğu içtenlikli saygıdan harekete geçerler. Allah,  yaptıklarınızdan habersiz değildir.', 'ثم قست قلوبكم من بعد ذلك فهي كالحجارة او اشد قسوة وان من الحجارة لما يتفجر منه الانهر وان منها لما يشقق فيخرج منه الما وان منها لما يهبط من خشية الله وما الله بغفل عما تعملون'),
(82, 2, 75, 'اَفَتَطْمَعُونَ اَنْ يُؤْمِنُوا لَكُمْ وَقَدْ كَانَ فَر۪يقٌ مِنْهُمْ يَسْمَعُونَ كَلَامَ اللّٰهِ ثُمَّ يُحَرِّفُونَهُ مِنْ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', 'E fe tatmeune en yu\'minu lekum ve kad kane ferikun minhum yesmeune kelamallahi summe yuharrifunehu min ba\'di ma akaluhu ve hum ya\'lemun.', 'Şimdi onların size inanacaklarını mı umuyorsunuz? Onlardan bir grup,  Allah\'ın kelamını dinleyip iyice anladıktan sonra,  onu bile bile çarpıtırlar.', 'افتطمعون ان يومنوا لكم وقد كان فريق منهم يسمعون كلم الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون'),
(83, 2, 76, 'وَاِذَا لَقُوا الَّذ۪ينَ اٰمَنُوا قَالُٓوا اٰمَنَّاۚ وَاِذَا خَلَا بَعْضُهُمْ اِلٰى بَعْضٍ قَالُٓوا اَتُحَدِّثُونَهُمْ بِمَا فَتَحَ اللّٰهُ عَلَيْكُمْ لِيُحَٓاجُّوكُمْ بِه۪ عِنْدَ رَبِّكُمْۜ اَفَلَا تَعْقِلُونَ', 'Ve iza lekullezine amenu kalu amenna, ve iza hala ba\'duhum ila ba\'din kalu e tuhaddisunehum bi ma fetehallahu aleykum li yuhaccukum bihi inde rabbikum e fe la ta\'kılun.', 'Onlar,  iman edenlerle karşılaştıkları zaman,  \"Biz de iman ettik.\" derler. Baş başa kaldıklarında: \"Rabb\'inizin size açıkladığını[1],  size karşı delil olarak kullansınlar diye mi onlara söylüyorsunuz! Neden aklınızı kullanmıyorsunuz?\" derler.', 'واذا لقوا الذين امنوا قالوا امنا واذا خلا بعضهم الي بعض قالوا اتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم افلا تعقلون'),
(84, 2, 77, 'اَوَلَا يَعْلَمُونَ اَنَّ اللّٰهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'E ve la ya\'lemune ennallahe ya\'lemu ma yusirrune ve ma yu\'linun.', 'Allah\'ın,  onların gizlediklerini de açıkladıklarını da bildiğini bilmiyorlar mı?', 'اولا يعلمون ان الله يعلم ما يسرون وما يعلنون'),
(85, 2, 78, 'وَمِنْهُمْ اُمِّيُّونَ لَا يَعْلَمُونَ الْكِتَابَ اِلَّٓا اَمَانِيَّ وَاِنْ هُمْ اِلَّا يَظُنُّونَ', 'Ve minhum ummiyyune la ya\'lemunel kitabe illa emaniyye ve in hum illa yezunnun.', 'İçlerinde ummiler vardır.[1] Kitabı bilmezler. Kuruntularından[2] başka bir şey bilmezler. Ancak zanda bulunuyorlar.', 'ومنهم اميون لا يعلمون الكتب الا اماني وان هم الا يظنون'),
(86, 2, 79, 'فَوَيْلٌ لِلَّذ۪ينَ يَكْتُبُونَ الْكِتَابَ بِاَيْد۪يهِمْ ثُمَّ يَقُولُونَ هٰذَا مِنْ عِنْدِ اللّٰهِ لِيَشْتَرُوا بِه۪ ثَمَناً قَل۪يلاًۜ فَوَيْلٌ لَهُمْ مِمَّا كَتَبَتْ اَيْد۪يهِمْ وَوَيْلٌ لَهُمْ مِمَّا يَكْسِبُونَ', 'Fe veylun lillezine yektubunel kitabe bi eydihim summe yekulune haza min indillahi li yeşteru bihi semenen kalila, fe veylun lehum mimma ketebet eydihim ve veylun lehum mimma yeksibun.', 'Yazıklar olsun o kimselere ki: Kitabı elleriyle yazıyorlar,  sonra da az bir kazanç elde etmek için \"Bu Allah\'ın katındandır.\" diyorlar. Yazıklar olsun onlara,  elleriyle yazdıklarından dolayı. Yazıklar olsun onlara,  kazandıklarından dolayı.', 'فويل للذين يكتبون الكتب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون'),
(87, 2, 80, 'وَقَالُوا لَنْ تَمَسَّنَا النَّارُ اِلَّٓا اَيَّاماً مَعْدُودَةًۜ قُلْ اَتَّخَذْتُمْ عِنْدَ اللّٰهِ عَهْداً فَلَنْ يُخْلِفَ اللّٰهُ عَهْدَهُٓ اَمْ تَقُولُونَ عَلَى اللّٰهِ مَا لَا تَعْلَمُونَ', 'Ve kalu len temessenen naru illa eyyamen ma\'dudeh, kul ettehaztum indallahi ahden fe len yuhlifallahu ahdehu em tekulune alallahi ma la ta\'lemun.', '\"Sayılı günlerin dışında ateş bize dokunmaz.\" dediler. De ki: \"Allah\'tan buna dair bir söz mü aldınız? Eğer böyle ise Allah,  kesinlikle verdiği sözden dönmez. Yoksa Allah\'a karşı bilmediğiniz şey mi söylüyorsunuz?\".', 'وقالوا لن تمسنا النار الا اياما معدودة قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون علي الله ما لا تعلمون'),
(88, 2, 81, 'بَلٰى مَنْ كَسَبَ سَيِّئَةً وَاَحَاطَتْ بِه۪ خَط۪ٓيـَٔتُهُ فَاُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Bela men kesebe seyyieten ve ehatat bihi hatietuhu fe ulaike ashabun nar, hum fiha halidun.', 'Hayır! Kim bir kötülük kazanır da yanlışları kendisini kuşatırsa,  onlar Cehennem ehlidir ve onlar,  orada kalıcıdırlar.', 'بلي من كسب سيية واحطت به خطيته فاوليك اصحب النار هم فيها خلدون'),
(89, 2, 82, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ اُو۬لٰٓئِكَ اَصْحَابُ الْجَنَّةِۚ هُمْ ف۪يهَا خَالِدُونَ۟', 'Vellezine amenu ve amilus salihati ulaike ashabul cenneh, hum fiha halidun.', 'İman edip,  salihatı yapanlar[1] Cennet ehlidirler. Ve onlar orada kalıcıdırlar.', 'والذين امنوا وعملوا الصلحت اوليك اصحب الجنة هم فيها خلدون'),
(90, 2, 83, 'وَاِذْ اَخَذْنَا م۪يثَاقَ بَن۪ٓي اِسْرَٓائ۪لَ لَا تَعْبُدُونَ اِلَّا اللّٰهَ وَبِالْوَالِدَيْنِ اِحْسَاناً وَذِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينِ وَقُولُوا لِلنَّاسِ حُسْناً وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَۜ ثُمَّ تَوَلَّيْتُمْ اِلَّا قَل۪يلاً مِنْكُمْ وَاَنْتُمْ مُعْرِضُونَ', 'Ve iz ehazna misaka beni israile la ta\'budune illallahe ve bil valideyni ihsanen ve zil kurbavel yetama vel mesakini ve kulu lin nasi husnen ve ekimus salate ve atuz zekat, summe tevelleytum illa kalilen minkum ve entum mu\'ridun.', 'Hani! Bir zaman İsrailoğulları\'ndan,  Allah\'tan başkasına kulluk etmeyin; anne ve babaya,  öksüzlere,  düşkünlere iyilik yapın; insanlara iyi söz söyleyin,  \"salatı ikame edin,  zekatı yapın[1]\",  diye kesin söz almıştık. Sonra,  içinizden pek azınız hariç sözünüzden döndünüz. Ve sizler,  döneklik yapanlarsınız.', 'واذ اخذنا ميثق بني اسريل لا تعبدون الا الله وبالولدين احسانا وذي القربي واليتمي والمسكين وقولوا للناس حسنا واقيموا الصلوة واتوا الزكوة ثم توليتم الا قليلا منكم وانتم معرضون'),
(91, 2, 84, 'وَاِذْ اَخَذْنَا م۪يثَاقَكُمْ لَا تَسْفِكُونَ دِمَٓاءَكُمْ وَلَا تُخْرِجُونَ اَنْفُسَكُمْ مِنْ دِيَارِكُمْ ثُمَّ اَقْرَرْتُمْ وَاَنْتُمْ تَشْهَدُونَ', 'Ve iz ehazna misakakum la tesfikune dimaekum ve la tuhricune enfusekum min diyarikum summe ekrartum ve entum teşhedun.', 'Hani! Bir zamanlar sizden,  birbirinizin kanlarını dökmeyeceğinize ve birbirinizi yurtlarınızdan çıkarmayacağınıza dair kesin söz almıştık. Bu sözümüzü kabul ettiğinizin tanıkları sizlersiniz.', 'واذ اخذنا ميثقكم لا تسفكون دماكم ولا تخرجون انفسكم من ديركم ثم اقررتم وانتم تشهدون'),
(92, 2, 85, 'ثُمَّ اَنْتُمْ هٰٓؤُ۬لَٓاءِ تَقْتُلُونَ اَنْفُسَكُمْ وَتُخْرِجُونَ فَر۪يقاً مِنْكُمْ مِنْ دِيَارِهِمْۘ تَظَاهَرُونَ عَلَيْهِمْ بِالْاِثْمِ وَالْعُدْوَانِۜ وَاِنْ يَأْتُوكُمْ اُسَارٰى تُفَادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ اِخْرَاجُهُمْۜ اَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍۚ فَمَا جَزَٓاءُ مَنْ يَفْعَلُ ذٰلِكَ مِنْكُمْ اِلَّا خِزْيٌ فِي الْحَيٰوةِ الدُّنْيَاۚ وَيَوْمَ الْقِيٰمَةِ يُرَدُّونَ اِلٰٓى اَشَدِّ الْعَذَابِۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Summe entum haulai taktulune enfusekum ve tuhricune ferikan minkummin diyarihim, tezaharune aleyhim bil ismi vel udvan, ve in ye\'tukum usara tufaduhum ve huve muharremun aleykum ihracuhum e fe tu\'minune bi ba\'dil kitabive tekfurune bi ba\'d, fe ma cezau men yef\'alu zalike minkum illa hızyun fil hayatid dunya, ve yevmel kıyameti yureddune ila eşeddil azab, ve mallahu bi gafilin amma ta\'melun.', 'Sonra siz o kimselersiniz ki; birbirinizi öldüren,  bir kısmınızı yurtlarından çıkarıp,  onlara karşı günahta ve düşmanlıkta iş birliği yapanlarsınız. Bir de esir olarak size gelirlerse,  onlarla fidyeleşiyorsunuz.[1] Oysa onları yurtlarından çıkarmak,  üzerinize haram kılınmıştı. Yoksa böyle yapmakla Kitap\'ın bir kısmına inanıp bir kısmını inkar mı ediyorsunuz. Sizden böyle yapanların cezası dünya hayatında aşağılanma,  Kıyamet Günü\'nde de en şiddetli azaba uğramaktır. Zira Allah,  yaptıklarınızdan habersiz değildir.', 'ثم انتم هولا تقتلون انفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالاثم والعدون وان ياتوكم اسري تفدوهم وهو محرم عليكم اخراجهم افتومنون ببعض الكتب وتكفرون ببعض فما جزا من يفعل ذلك منكم الا خزي في الحيوة الدنيا ويوم القيمة يردون الي اشد العذاب وما الله بغفل عما تعملون'),
(93, 2, 86, 'اُو۬لٰٓئِكَ الَّذ۪ينَ اشْتَرَوُا الْحَيٰوةَ الدُّنْيَا بِالْاٰخِرَةِۘ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْصَرُونَ۟', 'Ulaikellezineşteravul hayated dunya bil ahireti, fe la yuhaffefu anhumul azabu ve la hum yunsarun.', 'Onlar,  dünya hayatına karşılık ahiret hayatını satan kimselerdir. Bundan dolayı onlardan azap hafifletilmeyecek ve onlara yardım da edilmeyecektir.', 'اوليك الذين اشتروا الحيوة الدنيا بالاخرة فلا يخفف عنهم العذاب ولا هم ينصرون'),
(94, 2, 87, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ وَقَفَّيْنَا مِنْ بَعْدِه۪ بِالرُّسُلِ وَاٰتَيْنَا ع۪يسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَاَيَّدْنَاهُ بِرُوحِ الْقُدُسِۜ اَفَكُلَّمَا جَٓاءَكُمْ رَسُولٌ بِمَا لَا تَهْوٰٓى اَنْفُسُكُمُ اسْتَكْبَرْتُمْۚ فَفَر۪يقاً كَذَّبْتُمْۘ وَفَر۪يقاً تَقْتُلُونَ', 'Ve lekad ateyna musal kitabe ve kaffeyna min ba\'dihi bir rusuli ve ateyna isabne meryemel beyyinati ve eyyednahu bi ruhil kudus, e fe kullema caekum resulun bima la tehva enfusukumustekbertum, fe ferikan kezzebtum ve ferikan taktulun.', 'Ant olsun ki Musa\'ya Kitap\'ı verdik. Ardı sıra resuller gönderdik. Meryem oğlu İsa\'ya da Beyyinat\'ı[1] verdik ve O\'nu Kudus\'un Ruhu[2] ile destekledik. Ne zaman bir elçi hoşunuza gitmeyen bir şey getirdiyse,  büyüklük taslayarak kimini yalanlayıp,  kimini de öldürmediniz mi?', 'ولقد اتينا موسي الكتب وقفينا من بعده بالرسل واتينا عيسي ابن مريم البينت وايدنه بروح القدس افكلما جاكم رسول بما لا تهوي انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون'),
(95, 2, 88, 'وَقَالُوا قُلُوبُنَا غُلْفٌۜ بَلْ لَعَنَهُمُ اللّٰهُ بِكُفْرِهِمْ فَقَل۪يلاً مَا يُؤْمِنُونَ', 'Ve kalu kulubuna gulf, bel leanehumullahu bi kufrihim fe kalilen ma yu\'minun.', 'Ve onlar,  \"Kalplerimiz örtülüdür.\" dediler. Hayır,  öyle değil,  Allah; onları,  Küfr\'lerinden[1] dolayı lanetlemiştir.[2] Bu yüzden çok azı inanır.', 'وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يومنون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(96, 2, 89, 'وَلَمَّا جَٓاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللّٰهِ مُصَدِّقٌ لِمَا مَعَهُمْۙ وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذ۪ينَ كَفَرُواۚ فَلَمَّا جَٓاءَهُمْ مَا عَرَفُوا كَفَرُوا بِه۪ۘ فَلَعْنَةُ اللّٰهِ عَلَى الْكَافِر۪ينَ', 'Ve lemma caehum kitabun min indillahi musaddikun lima meahum, ve kanu min kablu yesteftihune alellezine keferu, fe lemma caehum ma arafu keferu bihi, fe la\'netullahi alel kafirin.', 'Onlara,  Allah katından yanlarındakini[1] tasdik edici bir kitap[2] gelince; daha önce Allah\'tan kafirlere karşı üstünlük kazanmak için böyle bir şey istedikleri halde,  onlara bildikleri şey[3] gelince bu kez onu inkar ettiler. Allah\'ın laneti,  gerçeği yalanlayan nankörlerin üzerinedir.', 'ولما جاهم كتب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون علي الذين كفروا فلما جاهم ما عرفوا كفروا به فلعنة الله علي الكفرين'),
(97, 2, 90, 'بِئْسَمَا اشْتَرَوْا بِه۪ٓ اَنْفُسَهُمْ اَنْ يَكْفُرُوا بِمَٓا اَنْزَلَ اللّٰهُ بَغْياً اَنْ يُنَزِّلَ اللّٰهُ مِنْ فَضْلِه۪ عَلٰى مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ۚ فَبَٓاؤُ۫ بِغَضَبٍ عَلٰى غَضَبٍۜ وَلِلْكَافِر۪ينَ عَذَابٌ مُه۪ينٌ', 'Bi\'semeşterav bihi enfusehum en yekfuru bi ma enzelallahu bagyen en yunezzilallahu min fadlihi ala men yeşau min ibadih, fe bau bi gadabin ala gadab, ve lil kafirine azabun muhin.', 'Allah\'ın,  dilediği kimseye kendi lütfundan indirmesini çekemeyerek; Allah\'ın indirdiğini küfretmekle[1] kendilerini ne kötü bir şeye karşılık sattılar. Bundan dolayı art arda gelen gazabı hak ettiler. Gerçeği yalanlayan nankörler için alçaltıcı bir azap vardır.', 'بيسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله علي من يشا من عباده فباو بغضب علي غضب وللكفرين عذاب مهين'),
(98, 2, 91, 'وَاِذَا ق۪يلَ لَهُمْ اٰمِنُوا بِمَٓا اَنْزَلَ اللّٰهُ قَالُوا نُؤْمِنُ بِمَٓا اُنْزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَٓاءَهُ وَهُوَ الْحَقُّ مُصَدِّقاً لِمَا مَعَهُمْۜ قُلْ فَلِمَ تَقْتُلُونَ اَنْبِيَٓاءَ اللّٰهِ مِنْ قَبْلُ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ve iza kile lehum aminu bi ma enzelallahu kalu nu\'minu bi ma unzile aleyna ve yekfurune bi ma veraehu ve huvel hakku musaddikan lima meahum kul fe lime taktulune enbiyaallahi min kablu in kuntum mu\'minin.', 'Onlara,  \"Allah\'ın indirdiklerine iman edin.\" denildiğinde,  \"Biz,  ancak bize indirilene[1] iman ederiz.\" dediler. Ve ondan[2] başkasını kabul etmezler. Oysa O,  yanlarındakini tasdik eden,  hak bir kitaptır. Onlara de ki: \"Madem inanıyordunuz,  ne diye daha önce Allah\'ın nebilerini öldürüyordunuz?\"', 'واذا قيل لهم امنوا بما انزل الله قالوا نومن بما انزل علينا ويكفرون بما وراه وهو الحق مصدقا لما معهم قل فلم تقتلون انبيا الله من قبل ان كنتم مومنين'),
(99, 2, 92, 'وَلَقَدْ جَٓاءَكُمْ مُوسٰى بِالْبَيِّنَاتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِه۪ وَاَنْتُمْ ظَالِمُونَ', 'Ve lekad caekum musa bil beyyinati summettehaztumul icle min ba\'dihi ve entum zalimun.', 'Gerçekten Musa size beyyinat[1] ile geldi. Sonra siz onun arkasından buzağı figürünü yaptınız.[2] İşte siz,  o zalimlersiniz.', 'ولقد جاكم موسي بالبينت ثم اتخذتم العجل من بعده وانتم ظلمون'),
(100, 2, 93, 'وَاِذْ اَخَذْنَا م۪يثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَۜ خُذُوا مَٓا اٰتَيْنَاكُمْ بِقُوَّةٍ وَاسْمَعُواۜ قَالُوا سَمِعْنَا وَعَصَيْنَا وَاُشْرِبُوا ف۪ي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْۜ  قُلْ بِئْسَمَا يَأْمُرُكُمْ بِه۪ٓ ا۪يمَانُكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ve iz ehazna misakakum ve refa\'na fevkakumut tur, huzu ma ateynakum bi kuvvetin vesmeu kalu semi\'na ve aseyna ve uşribu fi kulubihimul icle bi kufrihim kul bi\'se ma ye\'murukum bihi imanukum in kuntum mu\'minin.', 'Hani sizden,  \"Size verdiğimizi kuvvetlice alın ve dinleyin.\" diye kesin söz almış ve Tur\'u üzerinize kaldırmıştık[1]. Demişlerdi ki: \"Dinledik ama itaat etmiyoruz.\" Küfr\'leri yüzünden kalplerine buzağı sevgisi içirildi. De ki: \"Eğer gerçekten inanıyorsanız,  inancınız sizden ne kötü şey istiyor!\"', 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما اتينكم بقوة واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بيسما يامركم به ايمنكم ان كنتم مومنين'),
(101, 2, 94, 'قُلْ اِنْ كَانَتْ لَكُمُ الدَّارُ الْاٰخِرَةُ عِنْدَ اللّٰهِ خَالِصَةً مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kul in kanet lekumud darul ahiretu indallahi halisaten min dunin nasi fe temennevul mevte in kuntum sadikin.', 'De ki: \"Eğer Allah katında; ahiret yurdunun,  diğer insanların değil de yalnızca size ait olduğunu iddia eden sözünüzde samimi iseniz,  o zaman ölümü istesenize!\"', 'قل ان كانت لكم الدار الاخرة عند الله خالصة من دون الناس فتمنوا الموت ان كنتم صدقين'),
(102, 2, 95, 'وَلَنْ يَتَمَنَّوْهُ اَبَداً بِمَا قَدَّمَتْ اَيْد۪يهِمْۜ وَاللّٰهُ عَل۪يمٌ بِالظَّالِم۪ينَ', 'Ve len yetemennevhu ebeden bima kaddemet eydihim vallahu alimun biz zalimin.', 'Ama elleriyle yaptıkları şeylerden dolayı,  ölümü asla istemezler. Allah,  zalimleri en iyi bilendir.', 'ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظلمين'),
(103, 2, 96, 'وَلَتَجِدَنَّهُمْ اَحْرَصَ النَّاسِ عَلٰى حَيٰوةٍۚ وَمِنَ الَّذ۪ينَ اَشْرَكُوا يَوَدُّ اَحَدُهُمْ لَوْ يُعَمَّرُ اَلْفَ سَنَةٍۚ وَمَا هُوَ بِمُزَحْزِحِه۪ مِنَ الْعَذَابِ اَنْ يُعَمَّرَۜ وَاللّٰهُ بَص۪يرٌ بِمَا يَعْمَلُونَ۟', 'Ve le tecidennehum ahrasan nasi ala hayatin, ve minellezine eşraku yeveddu ehaduhum lev yuammeru elfe seneh, ve ma huve bi muzahzihıhi minel azabi en yuammer, vallahu basirun bima ya\'melun.', 'Ve sen,  onları,  yaşamaya karşı insanların en ihtiraslısı,  hatta Allah\'a ortak koşanlardan bile daha çok ihtiraslı bulacaksın. Her biri bin yıl yaşamak ister. Oysaki uzun ömürlü olmak,  böyle birini azaptan kurtarmaz. Zira Allah,  yaptıkları her şeyi görmektedir.', 'ولتجدنهم احرص الناس علي حيوة ومن الذين اشركوا يود احدهم لو يعمر الف سنة وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون'),
(104, 2, 97, 'قُلْ مَنْ كَانَ عَدُواًّ لِجِبْر۪يلَ فَاِنَّهُ نَزَّلَهُ عَلٰى قَلْبِكَ بِاِذْنِ اللّٰهِ مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرٰى لِلْمُؤْمِن۪ينَ', 'Kul men kane aduvven li cibrile fe innehu nezzelehu ala kalbike bi iznillahi musaddikan lima beyne yedeyhi ve huden ve buşra lil mu\'minin.', 'De ki kim Cibril\'e[1] düşmansa,  Bilsin ki O[2],  onu[3] iki eli arasındakileri[4] tasdik edici olarak Allah\'ın izni ile[5] senin kalbine çokça indirdi. Müminler için bir hidayet ve müjde olarak.', 'قل من كان عدوا لجبريل فانه نزله علي قلبك باذن الله مصدقا لما بين يديه وهدي وبشري للمومنين'),
(105, 2, 98, 'مَنْ كَانَ عَدُواًّ لِلّٰهِ وَمَلٰٓئِكَتِه۪ وَرُسُلِه۪ وَجِبْر۪يلَ وَم۪يكَالَ فَاِنَّ اللّٰهَ عَدُوٌّ لِلْكَافِر۪ينَ', 'Men kane aduvven lillahi ve melaiketihi ve rusulihi ve cibrile ve mikale fe innallahe aduvvun lil kafirin.', 'Kim Allah\'a ve O\'nun meleklerine,  resullerine,  Cibril\'e[1],  Mikal\'e[2] düşman olursa; iyi bilsin ki Allah da Kafirlere düşmandır.', 'من كان عدوا لله ومليكته ورسله وجبريل وميكيل فان الله عدو للكفرين'),
(106, 2, 99, 'وَلَقَدْ اَنْزَلْـنَٓا اِلَيْكَ اٰيَاتٍ بَيِّنَاتٍۚ وَمَا يَكْفُرُ بِهَٓا اِلَّا الْفَاسِقُونَ', 'Ve lekad enzelna ileyke ayatin beyyinat, ve ma yekfuru biha illel fasikun.', 'Ant olsun Biz,  sana apaçık ayetler indirdik. Ancak,  onları,  fasık[1] olanlar Küfr[2] eder.', 'ولقد انزلنا اليك ايت بينت وما يكفر بها الا الفسقون'),
(107, 2, 100, 'اَوَكُلَّمَا عَاهَدُوا عَهْداً نَبَذَهُ فَر۪يقٌ مِنْهُمْۜ بَلْ اَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'E ve kullema ahedu ahden nebezehu ferikun minhum bel ekseruhum la yu\'minun.', 'Onlar,  ne zaman bir söz verdilerse,  içlerinden bir grup onu bozmadı mı? Zaten onların çoğu iman etmiyorlar.', 'اوكلما عهدوا عهدا نبذه فريق منهم بل اكثرهم لا يومنون'),
(108, 2, 101, 'وَلَمَّا جَٓاءَهُمْ رَسُولٌ مِنْ عِنْدِ اللّٰهِ مُصَدِّقٌ لِمَا مَعَهُمْ نَبَذَ فَر۪يقٌ مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَۗ كِتَابَ اللّٰهِ وَرَٓاءَ ظُهُورِهِمْ كَاَنَّهُمْ لَا يَعْلَمُونَ', 'Ve lemma caehum resulun min indillahi musaddikun lima meahum nebeze ferikun minellezine utul kitab, kitaballahi verae zuhurihim ke ennehum la ya\'lemun.', 'Ne zaman onlara,  Allah\'tan,  yanlarındakini tasdik edici bir elçi gelse,  Kitap Ehli\'nden bir grup,  sanki hiç haberleri yokmuş gibi,  elçinin getirdiğine sırt çevirirler.', 'ولما جاهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتب كتب الله ورا ظهورهم كانهم لا يعلمون'),
(109, 2, 102, 'وَاتَّـبَعُوا مَا تَتْلُوا الشَّيَاط۪ينُ عَلٰى مُلْكِ سُلَيْمٰنَۚ وَمَا كَفَرَ سُلَيْمٰنُ وَلٰكِنَّ الشَّيَاط۪ينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَۗ وَمَٓا اُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَۜ وَمَا يُعَلِّمَانِ مِنْ اَحَدٍ حَتّٰى يَقُولَٓا اِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْۜ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِه۪ بَيْنَ الْمَرْءِ وَزَوْجِه۪ۜ وَمَا هُمْ بِضَٓارّ۪ينَ بِه۪ مِنْ اَحَدٍ اِلَّا بِاِذْنِ اللّٰهِۜ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْۜ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرٰيهُ مَا لَهُ فِي الْاٰخِرَةِ مِنْ خَلَاقٍ۠ وَلَبِئْسَ مَا شَرَوْا بِه۪ٓ اَنْفُسَهُمْۜ  لَوْ كَانُوا يَعْلَمُونَ', 'Vettebeu ma tetluş şeyatinu ala mulki suleyman ve ma kefere suleymanu ve lakinneş şeyatine keferu yuallimunen nases sihra, ve ma unzile alel melekeyni bi babile harute ve marut, ve ma yuallimani min ehadin hatta yekula innema nahnu fitnetun fe la tekfur fe yeteallemune minhuma ma yuferrikune bihi beynel mer\'i ve zevcih, ve ma hum bi darrine bihi min ehadin illa bi iznillah, ve yeteallemune ma yadurruhum ve la yenfeuhum ve lekad alimu le menişterahu ma lehu fil ahireti min halakın, ve le bi\'se ma şerev bihi enfusehum lev kanu ya\'lemun.', 'Ve onlar,  Süleyman\'ın sahip olduğu güç konusunda şeytanların[1] uydurdukları şeylere uydular. Oysa Süleyman gerçeğe aykırı bir şey[2] yapmadı. Ancak insanlara büyü yapmayı öğreten şeytanlar[3] gerçeği gizliyordu; Babil\'deki iki meleğe/krala[4]; Harut ve Marut\'a bir şey indirilmiş değildi. Hatta bu iki melek/kral: \"Biz fitneyiz,  sakın kafir olma!\" demedikçe,  hiç kimseye bir şey öğretmiyorlardı. Fakat onlar,  o ikisinden karı ile kocanın arasını açacak şeyler öğrenmeye çalışıyorlardı. Ancak,  Allah\'ın izni olmadıkça bu şeyle hiç kimseye zarar veremezler. Onlar,  kendilerine bir faydası olmayan,  sadece zarar verecek şeyleri öğreniyorlardı. Halbuki onlar,  büyü ile uğraşanların ahirette bir nasiplerinin olmayacağını biliyorlardı. Kendilerini karşılığında sattıkları şey ne kötüdür. Keşke bilselerdi.', 'واتبعوا ما تتلوا الشيطين علي ملك سليمن وما كفر سليمن ولكن الشيطين كفروا يعلمون الناس السحر وما انزل علي الملكين ببابل هروت ومروت وما يعلمان من احد حتي يقولا انما نحن فتنة فلا تكفر فيتعلمون منهما ما يفرقون به بين المر وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتريه ما له في الاخرة من خلق ولبيس ما شروا به انفسهم لو كانوا يعلمون'),
(110, 2, 103, 'وَلَوْ اَنَّهُمْ اٰمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللّٰهِ خَيْرٌۜ لَوْ كَانُوا يَعْلَمُونَ۟', 'Ve lev ennehum amenu vettekav le mesubetun min indillahi hayr, lev kanu ya\'lemun.', 'Eğer onlar iman edip takva sahibi[1] olsalardı,  Allah katında kazanacakları sevap hayırlı olurdu. Keşke bilselerdi.', 'ولو انهم امنوا واتقوا لمثوبة من عند الله خير لو كانوا يعلمون'),
(111, 2, 104, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَقُولُوا رَاعِنَا وَقُولُوا انْظُرْنَا وَاسْمَعُواۜ وَلِلْكَافِر۪ينَ عَذَابٌ اَل۪يمٌ', 'Ya eyyuhellezine amenu la tekulu raina ve kulunzurna vesmeu ve lil kafirine azabun elim.', 'Ey iman edenler! \"raina[1]\" demeyin,  \"unzurna[2].\" deyin ve dinleyin. Gerçeği yalanlayan nankörler için can yakıcı bir azap vardır.', 'يايها الذين امنوا لا تقولوا رعنا وقولوا انظرنا واسمعوا وللكفرين عذاب اليم'),
(112, 2, 105, 'مَا يَوَدُّ الَّذ۪ينَ كَفَرُوا مِنْ اَهْلِ الْكِتَابِ وَلَا الْمُشْرِك۪ينَ اَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ رَبِّكُمْۜ وَاللّٰهُ يَخْتَصُّ بِرَحْمَتِه۪ مَنْ يَشَٓاءُۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Ma yeveddullezine keferu min ehlil kitabi ve lel muşrikine en yunezzele aleykum min hayrin min rabbikum vallahu yahtassu bi rahmetihi men yeşau, vallahu zul fadlil azim.', 'Kitap Ehli\'nin ve Müşriklerin kafirleri[1] Rabb\'inizden,  size bir hayrın indirilmesini istemezler. Oysa Allah,  rahmetini dilediği kimseye ayırır. Allah,  Büyük Lütuf Sahibi\'dir.', 'ما يود الذين كفروا من اهل الكتب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشا والله ذو الفضل العظيم'),
(113, 2, 106, 'مَا نَنْسَخْ مِنْ اٰيَةٍ اَوْ نُنْسِهَا نَأْتِ بِخَيْرٍ مِنْهَٓا اَوْ مِثْلِهَاۜ اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ma nensah min ayetin ev nunsiha ne\'ti bi hayrin minha ev misliha e lem ta\'lem ennallahe ala kulli şey\'in kadir.', 'Biz,  bir ayeti yürürlükten kaldırır veya unutturursak ya onun dengini ya da ondan daha iyisini getiririz. Sen,  Allah\'ın her şeye gücü yeten olduğunu bilmez misin?[1]', 'ما ننسخ من اية او ننسها نات بخير منها او مثلها الم تعلم ان الله علي كل شي قدير'),
(114, 2, 107, 'اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'E lem ta\'lem ennellahe lehu mulkus semavati vel ard, ve ma lekum min dunillahi min veliyyin ve la nasir.', 'Yerlerin ve göklerin egemenliğinin Allah\'a ait olduğunu bilmez misin? Sizin için Allah\'ın yanı sıra ne bir veli[1] ne de bir yardımcı vardır.', 'الم تعلم ان الله له ملك السموت والارض وما لكم من دون الله من ولي ولا نصير'),
(115, 2, 108, 'اَمْ تُر۪يدُونَ اَنْ تَسْـَٔلُوا رَسُولَكُمْ كَمَا سُئِلَ مُوسٰى مِنْ قَبْلُۜ  وَمَنْ يَتَبَدَّلِ الْكُفْرَ بِالْا۪يمَانِ فَقَدْ ضَلَّ سَوَٓاءَ السَّب۪يلِ', 'Em turidune en tes\'elu resulekum kema suile musa min kabl, ve men yetebeddelil kufra bil imani fe kad dalle sevaes sebil.', 'Yoksa siz de daha önce Musa\'yı sorguya çekenler gibi,  elçinizi sorguya çekmek mi istiyorsunuz? Her kim,  iman yerine küfrü tercih ederse o dosdoğru yoldan sapmış olur.', 'ام تريدون ان تسلوا رسولكم كما سيل موسي من قبل ومن يتبدل الكفر بالايمن فقد ضل سوا السبيل'),
(116, 2, 109, 'وَدَّ كَث۪يرٌ مِنْ اَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُمْ مِنْ بَعْدِ ا۪يمَانِكُمْ كُفَّاراًۚ حَسَداً مِنْ عِنْدِ اَنْفُسِهِمْ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّۚ فَاعْفُوا وَاصْفَحُوا حَتّٰى يَأْتِيَ اللّٰهُ بِاَمْرِه۪ۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Vedde kesirun min ehlil kitabi lev yeruddunekum min ba\'di imanikum kuffara, haseden min indi enfusihim min ba\'di ma tebeyyene lehumul hakk, fa\'fu vasfehu hatta ye\'tiyallahu bi emrih, innallahe ala kulli şey\'in kadir.', 'Kitap Ehli\'nin çoğu,  Hakk kendilerine bildirildiği halde,  benliklerindeki kıskançlıktan dolayı,  imanınızdan sonra sizi küfre döndürmek isterler. Allah\'ın emri gelinceye kadar onlara aldırış etmeyin. Onları affedin ve onlarla iyi geçinin. Kuşkusuz Allah,  Her Şeye Güç Yetiren\'dir.', 'ود كثير من اهل الكتب لو يردونكم من بعد ايمنكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتي ياتي الله بامره ان الله علي كل شي قدير'),
(117, 2, 110, 'وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَۜ وَمَا تُقَدِّمُوا لِاَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللّٰهِۜ اِنَّ اللّٰهَ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Ve ekimus salate ve atuz zekat, ve ma tukaddimu li enfusikum min hayrin teciduhu indallah innallahe bi ma ta\'melune basir.', 'Salatı ikame edin ve zekatı yapın.[1] Kendiniz için her ne iyilik yaparsanız onu Allah katında bulacaksınız. Kuşkusuz Allah,  bütün yaptıklarınızı görmektedir.', 'واقيموا الصلوة واتوا الزكوة وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير'),
(118, 2, 111, 'وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ اِلَّا مَنْ كَانَ هُوداً اَوْ نَصَارٰىۜ تِلْكَ اَمَانِيُّهُمْۜ قُلْ هَاتُوا بُرْهَانَكُمْ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve kalu len yedhulel cennete illa men kane huden ev nasar, tilke emaniyyuhum kul hatu burhanekum in kuntum sadikin.', 'Onlar,  \"Yahudi ve Hıristiyanlardan başkası Cennet\'e giremeyecek.\" derler. Bu,  onların kuruntusudur. De ki: \"Eğer doğru söylüyorsanız iddianızı kanıtlayın.\"', 'وقالوا لن يدخل الجنة الا من كان هودا او نصري تلك امانيهم قل هاتوا برهنكم ان كنتم صدقين'),
(119, 2, 112, 'بَلٰى مَنْ اَسْلَمَ وَجْهَهُ لِلّٰهِ وَهُوَ مُحْسِنٌ فَلَهُٓ اَجْرُهُ عِنْدَ رَبِّه۪ۖ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ۟', 'Bela men esleme vechehu lillahi ve huve muhsinun fe lehu ecruhu inde rabbihi, ve la havfun aleyhim ve la hum yahzenun.', 'Bilakis,  gerçekten kim iyi bir kimse olarak benliğini Allah\'a teslim etmişse,  onun ödülü Rabb\'inin yanındadır. Onlar için hiçbir korku yoktur ve onlar üzülmeyeceklerdir.', 'بلي من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون'),
(120, 2, 113, 'وَقَالَتِ الْيَهُودُ لَيْسَتِ النَّصَارٰى عَلٰى شَيْءٍۖ وَقَالَتِ النَّصَارٰى لَيْسَتِ الْيَهُودُ عَلٰى شَيْءٍۙ وَهُمْ يَتْلُونَ الْكِتَابَۜ كَذٰلِكَ قَالَ الَّذ۪ينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْۚ فَاللّٰهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'Ve kaletil yahudu leysetin nasara ala şey\' ve kaletin nasara leysetil yahudu ala şey\'in ve hum yetlunel kitab, kezalike kalellezine la ya\'lemune misle kavlihim, fallahu yahkumu beynehum yevmel kıyameti fima kanu fihi yahtelifun.', 'Kitap\'ı okuyup durdukları halde,  Yahudiler: \"Hıristiyanlar geçerli bir inanç üzerinde değildirler.\" derler. Hıristiyanlar da: \"Yahudiler geçerli bir inanca sahip değildirler.\" derler. Oysa Kitap\'ı okuyorlar. Kitap\'tan habersiz olanlar da onların sözlerinin aynısını söylediler. Allah,  onların anlaşmazlığa düştükleri konuda Kıyamet Günü hüküm verecektir.', 'وقالت اليهود ليست النصري علي شي وقالت النصري ليست اليهود علي شي وهم يتلون الكتب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيمة فيما كانوا فيه يختلفون'),
(121, 2, 114, 'وَمَنْ اَظْلَمُ مِمَّنْ مَنَعَ مَسَاجِدَ اللّٰهِ اَنْ يُذْكَرَ ف۪يهَا اسْمُهُ وَسَعٰى ف۪ي خَرَابِهَاۜ اُو۬لٰٓئِكَ مَا كَانَ لَهُمْ اَنْ يَدْخُلُوهَٓا اِلَّا خَٓائِف۪ينَۜ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْاٰخِرَةِ عَذَابٌ عَظ۪يمٌ', 'Ve men azlemu mimmen menea mesacidallahi en yuzkere fihesmuhu ve sea fi harabiha ulaike ma kane lehum en yedhuluha illa haifin lehum fid dunya hızyun ve lehum fil ahireti azabun azim.', 'Allah\'ın mescitlerinde,  O\'nun adının anılmasını engelleyen ve onların harap olmasına çalışan kimseden daha zalim kim olabilir? Buralara,  ancak Allah\'a karşı gelmekten korkularak girilebilir. Onlar için dünyada aşağılanma,  ahirette de büyük bir azap vardır.', 'ومن اظلم ممن منع مسجد الله ان يذكر فيها اسمه وسعي في خرابها اوليك ما كان لهم ان يدخلوها الا خايفين لهم في الدنيا خزي ولهم في الاخرة عذاب عظيم'),
(122, 2, 115, 'وَلِلّٰهِ الْمَشْرِقُ وَالْمَغْرِبُ فَاَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللّٰهِۜ اِنَّ اللّٰهَ وَاسِعٌ عَل۪يمٌ', 'Ve lillahil meşriku vel magribu fe eynema tuvellu fe semme vechullah innallahe vasiun alim.', 'Doğu da Allah\'ındır,  batı da. Nereye yönelirseniz yönelin,  Allah\'ın yönü orasıdır. Kuşkusuz,  Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Her Şeyi Bilen\'dir.', 'ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم'),
(123, 2, 116, 'وَقَالُوا اتَّخَذَ اللّٰهُ وَلَداًۙ سُبْحَانَهُۜ بَلْ لَهُ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ كُلٌّ لَهُ قَانِتُونَ', 'Ve kaluttehazellahu veleden, subhaneh, bel lehu ma fis semavati vel ard, kullun lehu kanitun.', '\"Allah,  çocuk edindi!\" dediler. Haşa! O,  bundan münezzehtir[1].Bilakis,  gökte ve yerde ne varsa her şey O\'nundur. Ve her şey O\'na gönülden boyun eğmektedir.', 'وقالوا اتخذ الله ولدا سبحنه بل له ما في السموت والارض كل له قنتون'),
(124, 2, 117, 'بَد۪يعُ السَّمٰوَاتِ وَالْاَرْضِۜ وَاِذَا قَضٰٓى اَمْراً فَاِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ', 'Bedius semavati vel ard, ve iza kada emren fe innema yekulu lehu kun fe yekun.', 'O,  göklerin ve yerin Bedi\'sidir[1]. Bir şeyin olmasını istediğinde,  ona sadece \"Ol.\" der,  o da oluverir.', 'بديع السموت والارض واذا قضي امرا فانما يقول له كن فيكون'),
(125, 2, 118, 'وَقَالَ الَّذ۪ينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا اللّٰهُ اَوْ تَأْت۪ينَٓا اٰيَةٌۜ  كَذٰلِكَ قَالَ الَّذ۪ينَ مِنْ قَبْلِهِمْ مِثْلَ قَوْلِهِمْۜ تَشَابَهَتْ قُلُوبُهُمْۜ قَدْ بَيَّنَّا الْاٰيَاتِ لِقَوْمٍ يُوقِنُونَ', 'Ve kalellezine la ya\'lemune lev la yukellimunallahu ev te\'tina ayeh, kezalike kalellezine min kablihim misle kavlihim, teşabehet kulubuhum, kad beyyennal ayati li kavmin yukınun.', 'Bilmeyen kimseler: \"Allah\'ın bizimle konuşması veya bize bir ayet[1] göndermesi gerekmez mi?\" dediler. Onlardan öncekiler de onların sözlerine benzer sözler söylemişlerdi. Kalpleri birbirlerine benziyor. Bilmek isteyen kimseler için ayetleri iyice açıkladık.', 'وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا اية كذلك قال الذين من قبلهم مثل قولهم تشبهت قلوبهم قد بينا الايت لقوم يوقنون'),
(126, 2, 119, 'اِنَّٓا اَرْسَلْنَاكَ بِالْحَقِّ بَش۪يراً وَنَذ۪يراًۙ وَلَا تُسْـَٔلُ عَنْ اَصْحَابِ الْجَح۪يمِ', 'İnna erselnake bil hakkı beşiren ve neziren, ve la tus\'elu an ashabil cahim.', 'Doğrusu Biz,  seni,  Hakk ile müjdeleyici ve uyarıcı olarak gönderdik. Cehennem ehlinden sorumlu tutulacak değilsin.', 'انا ارسلنك بالحق بشيرا ونذيرا ولا تسل عن اصحب الجحيم'),
(127, 2, 120, 'وَلَنْ تَرْضٰى عَنْكَ الْيَهُودُ وَلَا النَّصَارٰى حَتّٰى تَتَّبِعَ مِلَّتَهُمْۜ قُلْ اِنَّ هُدَى اللّٰهِ هُوَ الْهُدٰىۜ وَلَئِنِ اتَّبَعْتَ اَهْوَٓاءَهُمْ بَعْدَ الَّذ۪ي جَٓاءَكَ مِنَ الْعِلْمِۙ مَا لَكَ مِنَ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'Ve len terda ankel yahudu ve len nasara hatta tettebia milletehum kul inne hudallahi huvel huda ve leinitteba\'te ehvaehum ba\'dellezi caeke minel ilmi, ma leke minallahi min veliyyin ve la nasir.', 'Yahudiler ve Hıristiyanlar,  sen onların milletlerine[1] uymadıkça senden asla razı olmazlar. De ki: \"Gerçek şu ki; doğru yol Allah\'ın yoludur.\" Ve sana gelen ilimden[2] sonra onların arzularına uyarsan; Allah\'tan,  sana ne bir veli[3] ne bir yardımcı bulabilirsin.', 'ولن ترضي عنك اليهود ولا النصري حتي تتبع ملتهم قل ان هدي الله هو الهدي ولين اتبعت اهواهم بعد الذي جاك من العلم ما لك من الله من ولي ولا نصير'),
(128, 2, 121, 'اَلَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يَتْلُونَهُ حَقَّ تِلَاوَتِه۪ۜ  اُو۬لٰٓئِكَ يُؤْمِنُونَ بِه۪ۜ وَمَنْ يَكْفُرْ بِه۪ فَاُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ۟', 'Ellezine ateynahumul kitabe yetlunehu hakka tilavetih ulaike yu\'minune bih, ve men yekfur bihi fe ulaike humul hasirun.', 'Kendilerine Kitap verdiğimiz kimseler,  ona uymak için gereği gibi okurlar. İşte bunlar ona inananlardır. İnanmayanlar ise,  işte onlar kaybedenlerdir.', 'الذين اتينهم الكتب يتلونه حق تلاوته اوليك يومنون به ومن يكفر به فاوليك هم الخسرون'),
(129, 2, 122, 'يَا بَن۪ٓي اِسْرَٓائ۪لَ اذْكُرُوا نِعْمَتِيَ الَّت۪ٓي اَنْعَمْتُ عَلَيْكُمْ وَاَنّ۪ي فَضَّلْتُكُمْ عَلَى الْعَالَم۪ينَ', 'Ya beni israilezkuru ni\'metiyelleti en\'amtu aleykum ve enni faddaltukum alel alemin.', 'Ey İsrailoğulları! Size verdiğim nimetimi ve lütufta bulunarak sizi alemlerde[1] nimetlendirdiğimi hatırlayın.', 'يبني اسريل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين'),
(130, 2, 123, 'وَاتَّقُوا يَوْماً لَا تَجْز۪ي نَفْسٌ عَنْ نَفْسٍ شَيْـٔاً وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنْفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنْصَرُونَ', 'Vetteku yevmen la teczi nefsun an nefsin şey\'en ve la yukbelu minha adlun ve la tenfeuha şefaatun ve la hum yunsarun.', 'Hiç kimsenin bir başkasının yerine bir şey ödeyemeyeceği,  hiç kimseden fidye kabul edilmeyeceği ve hiç kimseye şefaatin[1] fayda vermeyeceği ve hiç kimseye yardım edilmeyeceği günden korunup sakının.', 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها عدل ولا تنفعها شفعة ولا هم ينصرون'),
(131, 2, 124, 'وَاِذِ ابْتَلٰٓى اِبْرٰه۪يمَ رَبُّهُ بِكَلِمَاتٍ فَاَتَمَّهُنَّۜ قَالَ اِنّ۪ي جَاعِلُكَ لِلنَّاسِ اِمَاماًۜ قَالَ وَمِنْ ذُرِّيَّت۪يۜ قَالَ لَا يَنَالُ عَهْدِي الظَّالِم۪ينَ', 'Ve izibtela ibrahime rabbuhu bi kelimatin fe etemmehun, kale inni cailuke lin nasi imama, kale ve min zurriyyeti kale la yenalu ahdiz zalimin.', 'Hani! Rabb\'i,  İbrahim\'i birtakım kelimeler[1] ile sınamış; o da onları yerine getirmişti. Allah,  \"Ben seni insanlara önder yapacağım.\" dedi. İbrahim,  \"Soyumdan olanları da.\" deyince; Allah,  \"Benim ahdim zalimlere ulaşmaz!\" dedi.', 'واذ ابتلي ابرهم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظلمين'),
(132, 2, 125, 'وَاِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِلنَّاسِ وَاَمْناًۜ وَاتَّخِذُوا مِنْ مَقَامِ اِبْرٰه۪يمَ مُصَلًّىۜ  وَعَهِدْنَٓا اِلٰٓى اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ اَنْ طَهِّرَا بَيْتِيَ لِلطَّٓائِف۪ينَ وَالْعَاكِف۪ينَ وَالرُّكَّعِ السُّجُودِ', 'Ve iz cealnal beyte mesabeten lin nasi ve emna, vettehizu min makamı ibrahime musalla ve ahidna ila ibrahime ve ismaile en tahhira beytiye lit taifine vel akifine ver rukkais sucud.', 'Hani Biz,  Beyt\'i[1] insanlar için toplanma yeri ve güvenli bir yer kıldık. \"İbrahim\'in makamından kendinize bir salat[2] yeri edinin.\" dedik. İbrahim ve İsmail\'den,  \"Evimi tavaf edenler,  kendilerini adamak amacıyla orda toplananlar,  \"rüku ve secde edenler\"[3] için temiz tutun.\" diye söz aldık.', 'واذ جعلنا البيت مثابة للناس وامنا واتخذوا من مقام ابرهم مصلي وعهدنا الي ابرهم واسمعيل ان طهرا بيتي للطايفين والعكفين والركع السجود'),
(133, 2, 126, 'وَاِذْ قَالَ اِبْرٰه۪يمُ رَبِّ اجْعَلْ هٰذَا بَلَداً اٰمِناً وَارْزُقْ اَهْلَهُ مِنَ الثَّمَرَاتِ مَنْ اٰمَنَ مِنْهُمْ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ قَالَ وَمَنْ كَفَرَ فَاُمَتِّعُهُ قَل۪يلاً ثُمَّ اَضْطَرُّهُٓ اِلٰى عَذَابِ النَّارِۜ وَبِئْسَ الْمَص۪يرُ', 'Ve iz kale ibrahimu rabbic\'al haza beleden aminen verzuk ehlehu mines semerati men amene minhum billahi vel yevmil ahir, kale ve men kefere fe umettiuhu kalilen summe adtarruhu ila azabin nar, ve bi\'sel masir.', 'Hani İbrahim: \"Ey Rabb\'im! Bu beldeyi güvenli bir yer kıl,  halkından,  Allah\'a ve Ahiret Günü\'ne inananları,  çeşitli ürünlerle rızıklandır.\" dedi. O da: \"Kafir[1] olanı dahi az bir süre geçindiririm; sonra onu ateşin azabına uğratırım. Orası,  varacaklar için ne kötü bir yerdir.\" dedi.', 'واذ قال ابرهم رب اجعل هذا بلدا امنا وارزق اهله من الثمرت من امن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الي عذاب النار وبيس المصير'),
(134, 2, 127, 'وَاِذْ يَرْفَعُ اِبْرٰه۪يمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَاِسْمٰع۪يلُۜ رَبَّنَا تَقَبَّلْ مِنَّاۜ اِنَّكَ اَنْتَ السَّم۪يعُ الْعَل۪يمُ', 'Ve iz yerfeu ibrahimul kavaide minel beyti veismail rabbena tekabbel minna inneke entes semiul alim.', 'Hani bir zamanlar İbrahim,  İsmail ile birlikte Beyt\'in[1] temellerini yükseltirken: \"Ey Rabb\'imiz! Bunu bizden kabul et; kuşkusuz Sen,  Her Şeyi İşiten ve Her Şeyi Bilen\'sin.\"', 'واذ يرفع ابرهم القواعد من البيت واسمعيل ربنا تقبل منا انك انت السميع العليم'),
(135, 2, 128, 'رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنَٓا اُمَّةً مُسْلِمَةً لَكَۖ وَاَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَاۚ اِنَّكَ اَنْتَ التَّوَّابُ الرَّح۪يمُ', 'Rabbena vec\'alna muslimeyni leke ve min zurriyyetina ummeten muslimeten leke ve erina menasikena ve tub aleyna, inneke entet tevvabur rahim.', '\"Ey Rabb\'imiz! Bizi,  Sana teslim olanlardan kıl. Bizim soyumuzdan da Sana teslim olan bir toplum yap. Bize,  menasikimizi[1] göster. Tevbelerimizi kabul et. Kuşkusuz Tevbeleri Kabul Eden,  Rahmeti Kesintisiz Olan yalnızca Sen\'sin.', 'ربنا واجعلنا مسلمين لك ومن ذريتنا امة مسلمة لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم'),
(136, 2, 129, 'رَبَّنَا وَابْعَثْ ف۪يهِمْ رَسُولاً مِنْهُمْ يَتْلُوا عَلَيْهِمْ اٰيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكّ۪يهِمْۜ اِنَّكَ اَنْتَ الْعَز۪يزُ الْحَك۪يمُ۟', 'Rabbena veb\'as fihim resulen minhum yetlu aleyhim ayatike ve yuallimuhumul kitabe vel hikmete ve yuzekkihim inneke entel azizul hakim.', 'Ey Rabb\'imiz! İçlerinden onlara Sen\'in ayetlerini okuyacak,  Kitap\'ı ve Hikmeti[1] öğretecek ve onları arındıracak bir elçi gönder. Kuşkusuz Sen,  Mutlak Üstün Olan\'sın,  En İyi Hüküm Veren\'sin.', 'ربنا وابعث فيهم رسولا منهم يتلوا عليهم ايتك ويعلمهم الكتب والحكمة ويزكيهم انك انت العزيز الحكيم'),
(137, 2, 130, 'وَمَنْ يَرْغَبُ عَنْ مِلَّةِ اِبْرٰه۪يمَ اِلَّا مَنْ سَفِهَ نَفْسَهُۜ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَاۚ وَاِنَّهُ فِي الْاٰخِرَةِ لَمِنَ الصَّالِح۪ينَ', 'Ve men yergabu an milleti ibrahime illa men sefihe nefseh, ve lekadistafeynahufid dunya, ve innehu filahireti le mines salihin.', 'İbrahim\'in milletinden[1],  kendini bilmezlerden başka kim yüz çevirir? Ant olsun onu dünyada Biz seçtik; o,  ahirette de iyiler arasında yer alacaktır.', 'ومن يرغب عن ملة ابرهم الا من سفه نفسه ولقد اصطفينه في الدنيا وانه في الاخرة لمن الصلحين'),
(138, 2, 131, 'اِذْ قَالَ لَهُ رَبُّهُٓ اَسْلِمْۙ قَالَ اَسْلَمْتُ لِرَبِّ الْعَالَم۪ينَ', 'İz kale lehu rabbuhu eslim kale eslemtu li rabbil alemin.', 'Hani Rabb\'i ona: \"Müslim[1] ol\" dediğinde; o da: \"Âlemlerin Rabbi için müslim oldum.\" demişti.', 'اذ قال له ربه اسلم قال اسلمت لرب العلمين'),
(139, 2, 132, 'وَوَصّٰى بِهَٓا اِبْرٰه۪يمُ بَن۪يهِ وَيَعْقُوبُۜ يَا بَنِيَّ اِنَّ اللّٰهَ اصْطَفٰى لَكُمُ الدّ۪ينَ فَلَا تَمُوتُنَّ اِلَّا وَاَنْتُمْ مُسْلِمُونَۜ', 'Ve vassa biha ibrahimu benihi ve ya\'kub, ya beniyye innallahestafa lekumud dine fe la temutunne illa ve entum muslimun.', 'İbrahim,  bunu[1],  çocuklarına vasiyet etmişti. Yakup da[2]: \"Ey oğullarım! Şüphesiz Allah,  bu dini sizin için seçti. O halde Müslimler[3] olarak ölmenin dışında başka bir şekilde ölmeyin!\" demişti.', 'ووصي بها ابرهم بنيه ويعقوب يبني ان الله اصطفي لكم الدين فلا تموتن الا وانتم مسلمون'),
(140, 2, 133, 'اَمْ كُنْتُمْ شُهَدَٓاءَ اِذْ حَضَرَ يَعْقُوبَ الْمَوْتُۙ اِذْ قَالَ لِبَن۪يهِ مَا تَعْبُدُونَ مِنْ بَعْد۪يۜ قَالُوا نَعْبُدُ اِلٰهَكَ وَاِلٰهَ اٰبَٓائِكَ اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ وَاِسْحٰقَ اِلٰهاً وَاحِداًۚ وَنَحْنُ لَهُ مُسْلِمُونَ', 'Em kuntum şuhedae iz hadara ya\'kubel mevtu, iz kale li benihi ma ta\'budune min ba\'di kalu na\'budu ilaheke ve ilahe abaike ibrahime ve ismaile ve ishaka ilahen vahida ve nahnu lehu muslimun.', 'Yoksa siz,  Yakup\'un ölümü anında onun yanında mıydınız? Hani oğullarına: \"Benden sonra neye kulluk edeceksiniz?\" demişti. Onlar da: \"Senin ilahına ve ataların İbrahim,  İsmail ve İshak\'ın ilahı olan tek ilaha kulluk edeceğiz. Biz,  O\'na teslim olanlardanız.\" demişlerdi.', 'ام كنتم شهدا اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ابايك ابرهم واسمعيل واسحق الها وحدا ونحن له مسلمون'),
(141, 2, 134, 'تِلْكَ اُمَّةٌ قَدْ خَلَتْۚ لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْۚ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا يَعْمَلُونَ', 'Tilke ummetun kad halet, leha ma kesebet ve lekum ma kesebtum, ve la tus\'elune amma kanu ya\'melun.', 'O gelip geçen bir ümmetti[1]. Onların kazandıkları onlara; sizin kazandıklarınız sizedir. Siz,  onların yaptıklarından sorumlu değilsiniz.', 'تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون'),
(142, 2, 135, 'وَقَالُوا كُونُوا هُوداً اَوْ نَصَارٰى تَهْتَدُواۜ قُلْ بَلْ مِلَّةَ اِبْرٰه۪يمَ حَن۪يفاًۜ وَمَا كَانَ مِنَ الْمُشْرِك۪ينَ', 'Ve kalu kunu huden ev nasara tehtedu kul bel millete ibrahime hanifa, ve ma kane minel muşrikin.', 'Onlar,  \"Yahudi veya Hıristiyan olun ki,  doğru yolu bulasınız.\" dediler. De ki: \"Hayır; biz,  hiçbir zaman müşrik olmayan,  hanif[1] olan İbrahim\'in milletindeniz.[2]', 'وقالوا كونوا هودا او نصري تهتدوا قل بل ملة ابرهم حنيفا وما كان من المشركين'),
(143, 2, 136, 'قُولُٓوا اٰمَنَّا بِاللّٰهِ وَمَٓا اُنْزِلَ اِلَيْنَا وَمَٓا اُنْزِلَ اِلٰٓى اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ وَاِسْحٰقَ وَيَعْقُوبَ وَالْاَسْبَاطِ وَمَٓا اُو۫تِيَ مُوسٰى وَع۪يسٰى وَمَٓا اُو۫تِيَ النَّبِيُّونَ مِنْ رَبِّهِمْۚ لَا نُفَرِّقُ بَيْنَ اَحَدٍ مِنْهُمْۘ وَنَحْنُ لَهُ مُسْلِمُونَ', 'Kulu amenna billahi ve ma unzile ileyna ve ma unzile ila ibrahime ve ismaile ve ishaka ve ya\'kube vel esbatı ve ma utiye musa ve isa ve ma utiyen nebiyyune min rabbihim, la nuferriku beyne ehadin minhum ve nahnu lehu muslimun.', 'Deyin ki: \"Biz; Allah\'a,  bize indirilene,  İbrahim\'e,  İsmail\'e,  İshak\'a,  Yakup\'a ve onların soyundan gelenlere indirilene; Musa\'ya,  İsa\'ya ve diğer nebilere Rabb\'lerinden verilenlere,  iman ettik. Onları birbirinden ayırt etmeyiz. Ve biz O\'na teslim olanlardanız.\"', 'قولوا امنا بالله وما انزل الينا وما انزل الي ابرهم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون'),
(144, 2, 137, 'فَاِنْ اٰمَنُوا بِمِثْلِ مَٓا اٰمَنْتُمْ بِه۪ فَقَدِ اهْتَدَوْاۚ وَاِنْ تَوَلَّوْا فَاِنَّمَا هُمْ ف۪ي شِقَاقٍۚ فَسَيَكْف۪يكَهُمُ اللّٰهُۚ وَهُوَ السَّم۪يعُ الْعَل۪يمُۜ', 'Fe in amenu bi misli ma amentum bihi fe kadihtedev ve in tevellev fe innema hum fi şikak fe se yekfike humullah, ve huves semiul alim.', 'Eğer onlar da sizin iman ettiğiniz gibi iman ederlerse,  kuşkusuz doğru yolu bulmuş olurlar. Eğer yüz çevirirlerse,  derin bir ayrılık ve çıkmaza düşmüş olurlar. Onlara karşı Allah sana yeter. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'فان امنوا بمثل ما امنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم'),
(145, 2, 138, 'صِبْغَةَ اللّٰهِۚ وَمَنْ اَحْسَنُ مِنَ اللّٰهِ صِبْغَةًۘ وَنَحْنُ لَهُ عَابِدُونَ', 'Sıbgatallah ve men ahsenu minallahi sıbgaten, ve nahnu lehu abidun.', 'Allah\'ın boyası![1] Allah\'tan daha iyi boyası olan kim? Biz,  yalnızca O\'na kulluk edenlerdeniz.', 'صبغة الله ومن احسن من الله صبغة ونحن له عبدون'),
(146, 2, 139, 'قُلْ اَتُحَٓاجُّونَنَا فِي اللّٰهِ وَهُوَ رَبُّنَا وَرَبُّكُمْۚ وَلَـنَٓا اَعْمَالُنَا وَلَكُمْ اَعْمَالُكُمْۚ وَنَحْنُ لَهُ مُخْلِصُونَۙ', 'Kul e tuhaccunena fillahi ve huve rabbuna ve rabbukum, ve lena a\'maluna ve lekum a\'malukum ve nahnu lehu muhlisun.', 'De ki: \"Bizimle Allah hakkında mı tartışıyorsunuz? Oysa O,  bizim de Rabb\'imiz sizin de Rabb\'inizdir. Bizim yaptıklarımız bize,  sizin yaptıklarınız sizedir. Biz ona içtenlikle bağlananlarız.\"', 'قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعملنا ولكم اعملكم ونحن له مخلصون'),
(147, 2, 140, 'اَمْ تَقُولُونَ اِنَّ اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ وَاِسْحٰقَ وَيَعْقُوبَ وَالْاَسْبَاطَ كَانُوا هُوداً اَوْ نَصَارٰىۜ قُلْ ءَاَنْتُمْ اَعْلَمُ اَمِ اللّٰهُۜ وَمَنْ اَظْلَمُ مِمَّنْ كَتَمَ شَهَادَةً عِنْدَهُ مِنَ اللّٰهِۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Em tekulune inne ibrahime ve ismaile ve ishaka ve ya\'kube vel esbata kanu huden ev nasara kul e entum a\'lemu emillah, ve men azlemu mimmen keteme şehadeten indehu minallah, ve mallahu bi gafilin amma ta\'melun.', 'İbrahim\'in,  İsmail\'in,  İshak\'ın,  Yakup\'un ve onların soyundan gelenlerin Yahudi veya Hıristiyan olduklarını mı iddia ediyorsunuz? De ki: \"Siz mi daha iyi biliyorsunuz,  yoksa Allah mı?\" Allah\'tan gelen bir gerçeği kendi yanında gizleyen kimseden daha zalim kim olabilir? Allah,  yaptıklarınızdan habersiz değildir.', 'ام تقولون ان ابرهم واسمعيل واسحق ويعقوب والاسباط كانوا هودا او نصري قل انتم اعلم ام الله ومن اظلم ممن كتم شهدة عنده من الله وما الله بغفل عما تعملون'),
(148, 2, 141, 'تِلْكَ اُمَّةٌ قَدْ خَلَتْۚ لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْۚ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا يَعْمَلُونَ۟', 'Tilke ummetun kad halet leha ma kesebet ve lekum ma kesebtum ve la tus\'elune amma kanu ya\'melun.', 'Onlar,  gelip geçen bir ümmetti[1]. Onların kazandıkları onlara; sizin kazandıklarınız sizedir. Siz,  onların yaptıklarından sorumlu değilsiniz.', 'تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون'),
(149, 2, 142, 'سَيَقُولُ السُّفَـهَٓاءُ مِنَ النَّاسِ مَا وَلّٰيهُمْ عَنْ قِبْلَتِهِمُ الَّت۪ي كَانُوا عَلَيْهَاۜ قُلْ لِلّٰهِ الْمَشْرِقُ وَالْمَغْرِبُۜ يَهْد۪ي مَنْ يَشَٓاءُ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Se yekulus sufehau minen nasi ma vellahum an kıbletihimulleti kanu aleyha kul lillahil meşrıku vel magrıb, yehdi men yeşau ila sıratın mustakim.', 'İnsanlardan,  birtakım beyinsizler: \"Daha önce yöneldiğiniz kıbleden sizi çeviren nedir?\" diyecekler. De ki: \"Doğu da Batı da Allah\'ındır. O,  Hak eden kimseyi doğru yola iletir.\"', 'سيقول السفها من الناس ما وليهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشا الي صرط مستقيم'),
(150, 2, 143, 'وَكَذٰلِكَ جَعَلْنَاكُمْ اُمَّةً وَسَطاً لِتَكُونُوا شُهَدَٓاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَه۪يداًۜ وَمَا جَعَلْنَا الْقِبْلَةَ الَّت۪ي كُنْتَ عَلَيْهَٓا اِلَّا لِنَعْلَمَ مَنْ يَتَّبِـعُ الرَّسُولَ مِمَّنْ يَنْقَلِبُ عَلٰى عَقِبَيْهِۜ  وَاِنْ كَانَتْ لَكَب۪يرَةً اِلَّا عَلَى الَّذ۪ينَ هَدَى اللّٰهُۜ وَمَا كَانَ اللّٰهُ لِيُض۪يعَ ا۪يمَانَكُمْۜ اِنَّ اللّٰهَ بِالنَّاسِ لَرَؤُ۫فٌ رَح۪يمٌ', 'Ve kezalike cealnakum ummeten vasatan li tekunu şuhedae alen nasi ve yekuner resulu aleykum şehida, ve ma cealnal kıbletelleti kunte aleyha illa li na\'leme men yettebiur resule mimmen yenkalibu ala akibeyh, ve in kanet le kebireten illa alellezine hedallah ve ma kanallahu li yudia imanekum innallahe bin nasi le raufun rahim.', 'Ve böylece,  sizi vasat[1] bir toplum yaptık ki insanlara karşı gerçeğin tanıkları olasınız; elçi de sizin üzerinizde tanık olsun. Senin arzulayıp da yönelemediğin[2] Kıble\'yi[3],  Resul\'e uyanları ökçeleri üzerinde geri dönenlerden ayırt etmek için kıble yaptık. Doğrusu,  bu,  Allah\'ın hidayet ettiği[4] kimselerden başkasına ağır gelir. Allah,  imanınızı boşa çıkaracak değildir. Kuşkusuz Allah,  insanlara karşı Çok Şefkatli ve Çok Bağışlayıcı\'dır.', 'وكذلك جعلنكم امة وسطا لتكونوا شهدا علي الناس ويكون الرسول عليكم شهيدا وما جعلنا القبلة التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب علي عقبيه وان كانت لكبيرة الا علي الذين هدي الله وما كان الله ليضيع ايمنكم ان الله بالناس لروف رحيم'),
(151, 2, 144, 'قَدْ نَرٰى تَقَلُّبَ وَجْهِكَ فِي السَّمَٓاءِۚ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضٰيهَاۖ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِۜ وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُۜ وَاِنَّ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ لَيَعْلَمُونَ اَنَّهُ الْحَقُّ مِنْ رَبِّهِمْۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ', 'Kad nera tekallube vechike fis semai, fe le nuvelliyenneke kıbleten terdaha, fe velli vecheke şatral mescidil haram, ve haysu ma kuntum fe vellu vucuhekum şatrah, ve innellezine utul kitabe le ya\'lemune ennehul hakku min rabbihim ve mallahu bi gafilin amma ya\'melun.', 'Senin,  yüzünü göğe doğru çevirip durduğunu görüyoruz. Seni,  razı olacağın bir kıbleye çevireceğiz. Bundan böyle yüzünü,  Mescid-i Haram tarafına çevir. Ve siz de nerede olursanız olun,  yüzlerinizi o tarafa çevirin. Kitap verilenler,  onun Rabb\'lerinden gelen bir gerçek olduğunu bilirler. Allah,  onların yaptıklarından habersiz değildir.', 'قد نري تقلب وجهك في السما فلنولينك قبلة ترضيها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتب ليعلمون انه الحق من ربهم وما الله بغفل عما يعملون'),
(152, 2, 145, 'وَلَئِنْ اَتَيْتَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ بِكُلِّ اٰيَةٍ مَا تَبِعُوا قِبْلَتَكَۚ وَمَٓا اَنْتَ بِتَابِـعٍ قِبْلَتَهُمْۚ وَمَا بَعْضُهُمْ بِتَابِـعٍ قِبْلَةَ بَعْضٍۜ وَلَئِنِ اتَّبَعْتَ اَهْوَٓاءَهُمْ مِنْ بَعْدِ مَا جَٓاءَكَ مِنَ الْعِلْمِۙ اِنَّكَ اِذاً لَمِنَ الظَّالِم۪ينَۢ', 'Ve le in eteytellezine utul kitabe bi kulli ayetin ma tebiu kıbletek ve ma ente bi tabiın kıbletehum, ve ma ba\'duhum bi tabiın kıblete ba\'d, ve le initteba\'te ehvaehum min ba\'di ma caeke minel ilmi inneke izen le minez zalimin.', 'Ant olsun ki Kitap verilenlere hangi ayeti[1] getirirsen getir,  yine de onlar senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Onlar,  birbirlerinin kıblesine de uymazlar. Eğer,  sana verilen bunca ilimden[2] sonra,  onların arzularına uyarsan,  o zaman zalimlerden olursun.', 'ولين اتيت الذين اوتوا الكتب بكل اية ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبلة بعض ولين اتبعت اهواهم من بعد ما جاك من العلم انك اذا لمن الظلمين'),
(153, 2, 146, 'اَلَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ اَبْنَٓاءَهُمْۜ وَاِنَّ فَر۪يقاً مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ', 'Ellezine ateynahumul kitabe ya\'rifunehu kema ya\'rifune ebnaehum ve inne ferikan minhum le yektumunel hakka ve hum ya\'lemun.', 'Kendilerine Kitap verdiğimiz kimseler,  O\'nu[1] öz oğullarını bildikleri gibi bilirler. Buna rağmen içlerinden bir zümre,  bile bile gerçeği gizlemektedir.', 'الذين اتينهم الكتب يعرفونه كما يعرفون ابناهم وان فريقا منهم ليكتمون الحق وهم يعلمون'),
(154, 2, 147, 'اَلْحَقُّ مِنْ رَبِّكَ فَلَا تَكُونَنَّ مِنَ الْمُمْتَر۪ينَ۟', 'El hakku min rabbike fe la tekunenne minel mumterin.', 'Gerçek,  Rabb\'inden gelendir. Sakın kuşku duyanlardan olma.', 'الحق من ربك فلا تكونن من الممترين'),
(155, 2, 148, 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلّ۪يهَا فَاسْتَبِقُوا الْخَيْرَاتِۜ اَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللّٰهُ جَم۪يعاًۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ve li kullin vichetun huve muvelliha festebikul hayrat, eyne ma tekunu ye\'ti bikumullahu cemia, innallahe ala kulli şey\'in kadir.', 'Herkesin yöneldiği bir yönü vardır. Öyleyse siz de yararlı işler yapmada birbirinizle yarışın. Nerede olursanız olun Allah hepinizi bir araya getirir. Kuşkusuz,  Allah Her Şeye Güç Yetiren\'dir.', 'ولكل وجهة هو موليها فاستبقوا الخيرت اين ما تكونوا يات بكم الله جميعا ان الله علي كل شي قدير'),
(156, 2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِۜ وَاِنَّهُ لَلْحَقُّ مِنْ رَبِّكَۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Ve min haysu harecte fe velli vecheke şatral mescidil haram, ve innehu lel hakku min rabbik, ve mallahu bi gafilin amma ta\'melun.', 'Her nereden çıkarsan çık[1],  yüzünü Mescid-i Haram tarafına çevir. Çünkü bu Rabb\'inden gelen Hakk\'tır. Allah,  yaptıklarınızdan habersiz değildir.', 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغفل عما تعملون'),
(157, 2, 150, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِۜ وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُۙ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌۗ  اِلَّا الَّذ۪ينَ  ظَلَمُوا مِنْهُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْن۪ي وَلِاُتِمَّ نِعْمَت۪ي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَۙ', 'Ve min haysu harecte fe velli vecheke şatral mescidil haram, ve haysu ma kuntum fe velluvucuhekum şatrahu li ella yekune lin nasi aleykum hucceh, illellezine zalemu minhum fe la tahşevhum vahşevni ve li utimme ni\'meti aleykum ve leallekum tehtedun.', 'Her nereden çıkarsan çık,  yüzünü Mescid-i Haram tarafına çevir. Siz de nerede olursanız olun,  yüzünüzü o tarafa çevirin. Zalimler hariç,  insanların size karşı bir kanıtları olmasın. Siz,  onlara saygı duymayın,  Bana duyun ki size olan nimetimi tamamlayayım; böylece doğru yolu bulasınız.', 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره ليلا يكون للناس عليكم حجة الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون'),
(158, 2, 151, 'كَمَٓا اَرْسَلْنَا ف۪يكُمْ رَسُولاً مِنْكُمْ يَتْلُوا عَلَيْكُمْ اٰيَاتِنَا وَيُزَكّ۪يكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُعَلِّمُكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَۜ', 'Kema erselna fikum resulen minkum yetlu aleykum ayatina ve yuzekkikum ve yuallimukumul kitabe vel hikmete ve yuallimukum ma lem tekunu ta\'lemun.', 'Nitekim içinizden,  size ayetlerimizi okuyan,  sizi arındıran,  size Kitap\'ı ve Hikmet\'i[1] öğreten,  size bilmediğiniz şeyleri öğreten bir Resul gönderdik.', 'كما ارسلنا فيكم رسولا منكم يتلوا عليكم ايتنا ويزكيكم ويعلمكم الكتب والحكمة ويعلمكم ما لم تكونوا تعلمون'),
(159, 2, 152, 'فَاذْكُرُون۪ٓي اَذْكُرْكُمْ وَاشْكُرُوا ل۪ي وَلَا تَكْفُرُونِ۟', 'Fezkuruni ezkurkum veşkuru li ve la tekfurun.', 'Öyleyse Beni zikredin[1] ki Ben de sizi zikredeyim.[2] Bana şükredin,  sakın nankörlük etmeyin.', 'فاذكروني اذكركم واشكروا لي ولا تكفرون'),
(160, 2, 153, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اسْتَع۪ينُوا بِالصَّبْرِ وَالصَّلٰوةِۜ اِنَّ اللّٰهَ مَعَ الصَّابِر۪ينَ', 'Ya eyyuhellezine amenustainu bis sabri ves salat, innallahe meas sabirin.', 'Ey iman edenler! Sabır ve salatla[1] yardım dileyin. Kuşkusuz,  Allah,  sabredenlerle beraberdir.', 'يايها الذين امنوا استعينوا بالصبر والصلوة ان الله مع الصبرين'),
(161, 2, 154, 'وَلَا تَقُولُوا لِمَنْ يُقْتَلُ ف۪ي سَب۪يلِ اللّٰهِ اَمْوَاتٌۜ بَلْ اَحْيَٓاءٌ وَلٰكِنْ لَا تَشْعُرُونَ', 'Ve la tekulu li men yuktelu fi sebilillahi emvat, bel ehyaun ve lakin la teş\'urun.', 'Allah yolunda öldürülenler için,  \"ölüler\" demeyin. Bilakis,  onlar \"diri\"dirler, [1] ancak siz,  bunu kavrayamazsınız.', 'ولا تقولوا لمن يقتل في سبيل الله اموت بل احيا ولكن لا تشعرون'),
(162, 2, 155, 'وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْاَمْوَالِ وَالْاَنْفُسِ وَالثَّمَرَاتِۜ وَبَشِّرِ الصَّابِر۪ينَۙ', 'Ve le nebluvennekum bi şey\'in minel havfi vel cui ve naksın minel emvali vel enfusi ves semerat, ve beşşiris sabirin.', 'Kesinlikle sizi belalandıracağız:[1] Korku ve açlıkla; mallarınızı,  canlarınızı ve ürünlerinizi kayba uğratarak. Sabredenleri müjdele.', 'ولنبلونكم بشي من الخوف والجوع ونقص من الامول والانفس والثمرت وبشر الصبرين'),
(163, 2, 156, 'اَلَّذ۪ينَ اِذَٓا اَصَابَتْهُمْ مُص۪يبَةٌۙ قَالُٓوا اِنَّا لِلّٰهِ وَاِنَّٓا اِلَيْهِ رَاجِعُونَۜ', 'Ellezine iza esabethum musibetun, kalu inna lillahi ve inna ileyhi raciun.', 'Onlar,  bir musibetle karşılaştıkları zaman,  \"Bizler,  Allah için varız ve muhakkak O\'na döneceğiz.\" derler.', 'الذين اذا اصبتهم مصيبة قالوا انا لله وانا اليه رجعون'),
(164, 2, 157, 'اُو۬لٰٓئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَاُو۬لٰٓئِكَ هُمُ الْمُهْتَدُونَ', 'Ulaike aleyhim salavatun min rabbihim ve rahmetun ve ulaike humul muhtedun.', 'İşte Rabb\'lerinden,  onlara salatlar[1] ve rahmet vardır. İşte onlar,  doğru yolu bulanlardır.', 'اوليك عليهم صلوت من ربهم ورحمة واوليك هم المهتدون'),
(165, 2, 158, 'اِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَٓائِرِ اللّٰهِۚ فَمَنْ حَجَّ الْبَيْتَ اَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ اَنْ يَطَّوَّفَ بِهِمَاۜ وَمَنْ تَطَوَّعَ خَيْراًۙ فَاِنَّ اللّٰهَ شَاكِرٌ عَل۪يمٌ', 'İnnes safa vel mervete min şeairillah, fe men haccel beyte evı\'temera fe la cunaha aleyhi en yettavvefe bi hima ve men tetavvaa hayran, fe innallahe şakirun alim.', 'Kuşkusuz Safa ile Merve Allah\'ın belirlediği nişanelerdir.[1] Kim hacc ya da umre amacıyla Beyt\'i ziyaret ederse,  ikisini de tavaf etmesinde bir sakınca yoktur. Ve yine kim gönülden bir iyilik yaparsa; kuşkusuz,  Allah Karşılık Veren\'dir,  Her Şeyi Bilen\'dir.', 'ان الصفا والمروة من شعاير الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم'),
(166, 2, 159, 'اِنَّ الَّذ۪ينَ يَكْتُمُونَ مَٓا اَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدٰى مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِۙ اُو۬لٰٓئِكَ يَلْعَنُهُمُ اللّٰهُ وَيَلْعَنُهُمُ اللَّاعِنُونَۙ', 'İnnellezine yektumune ma enzelna min el beyyinati vel huda min ba\'di ma beyyennahu lin nasi fil kitabi, ulaike yel\'anuhumullahu ve yel\'anuhumul lainun.', 'Bizim indirdiğimiz apaçık kanıtları ve hidayeti;[1] insanlara Kitap\'ta açıkça gösterdikten sonra,  onları gizleyenler var ya! Onlara hem Allah lanet eder hem de bütün lanet edebilenler lanet ederler.', 'ان الذين يكتمون ما انزلنا من البينت والهدي من بعد ما بينه للناس في الكتب اوليك يلعنهم الله ويلعنهم اللعنون'),
(167, 2, 160, 'اِلَّا الَّذ۪ينَ تَابُوا وَاَصْلَحُوا وَبَيَّنُوا فَاُو۬لٰٓئِكَ اَتُوبُ عَلَيْهِمْۚ وَاَنَا التَّوَّابُ الرَّح۪يمُ', 'İllellezine tabu ve aslahu ve beyyenu fe ulaike etubu aleyhim, ve enet tevvabur rahim.', 'Ancak tevbe edip,  kendisini düzelten ve gerçeği gizlemeyenlerin tevbelerini kabul ederim. Zira Ben,  Tevbeleri Kabul Eden\'im,  Rahmetim Kesintisiz\'dir.', 'الا الذين تابوا واصلحوا وبينوا فاوليك اتوب عليهم وانا التواب الرحيم'),
(168, 2, 161, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ اُو۬لٰٓئِكَ عَلَيْهِمْ لَعْنَةُ اللّٰهِ وَالْمَلٰٓئِكَةِ وَالنَّاسِ اَجْمَع۪ينَۙ', 'İnnellezine keferu ve matu ve hum kuffarun ulaike aleyhim la\'netullahi vel melaiketi ven nasi ecmain.', 'Kafir[1] olup da Kafir olarak ölen kimselere gelince; işte,  Allah\'ın,  meleklerin ve bütün insanların laneti onların üzerinedir.', 'ان الذين كفروا وماتوا وهم كفار اوليك عليهم لعنة الله والمليكة والناس اجمعين'),
(169, 2, 162, 'خَالِد۪ينَ ف۪يهَاۚ لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ', 'Halidine fiha, la yuhaffefu anhumul azabu ve la hum yunzarun.', 'Onlar,  bu halde sürekli kalacaklardır. Onlardan ne azap hafifletilecek ve ne de onların yüzlerine bakılacak.', 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون'),
(170, 2, 163, 'وَاِلٰهُكُمْ اِلٰهٌ وَاحِدٌۚ  لَٓا اِلٰهَ اِلَّا هُوَ الرَّحْمٰنُ الرَّح۪يمُ۟', 'Ve ilahukum ilahun vahid, la ilahe illa huver rahmanur rahim.', 'Sizin ilahınız bir tek ilahtır. O\'ndan başka ilah yoktur. O,  Rahmeti Bol ve Kesintisiz Olan\'dır.', 'والهكم اله وحد لا اله الا هو الرحمن الرحيم'),
(171, 2, 164, 'اِنَّ ف۪ي خَلْقِ السَّمٰوَاتِ وَالْاَرْضِ وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّت۪ي تَجْر۪ي فِي الْبَحْرِ بِمَا يَنْفَعُ النَّاسَ وَمَٓا اَنْزَلَ اللّٰهُ مِنَ السَّمَٓاءِ مِنْ مَٓاءٍ فَاَحْيَا بِهِ الْاَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ ف۪يهَا مِنْ كُلِّ دَٓابَّةٍۖ وَتَصْر۪يفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَٓاءِ وَالْاَرْضِ لَاٰيَاتٍ لِقَوْمٍ يَعْقِلُونَ', 'İnne fi halkıs semavati vel ardı vahtilafil leyli ven nehari vel fulkilleti tecri fil bahri bima yenfeun nase ve ma enzelallahu mines semai min main fe ahya bihil arda ba\'de mevtiha ve besse fiha min kulli dabbe, ve tasrifir riyahı ves sehabil musahhari beynes semai vel ardı le ayatin li kavmin ya\'kılun.', 'Göklerin ve yerin yaradılışında,  gece ile gündüzün birbirlerini ardı sıra takip etmesinde; insanların yararlanmaları için denizde yüzen gemilerde,  Allah\'ın gökten indirip,  onunla ölü toprağa hayat vererek,  orada her türlü canlının yaşamasını sağladığı suda,  rüzgarın yönlendirilmesinde,  emre hazır bulutların yer ile gök arasında hareket ettirilmesinde aklını kullanan bir halk için birçok kanıt vardır.', 'ان في خلق السموت والارض واختلف اليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السما من ما فاحيا به الارض بعد موتها وبث فيها من كل دابة وتصريف الريح والسحاب المسخر بين السما والارض لايت لقوم يعقلون'),
(172, 2, 165, 'وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللّٰهِ اَنْدَاداً يُحِبُّونَهُمْ كَحُبِّ اللّٰهِۜ وَالَّذ۪ينَ اٰمَنُٓوا اَشَدُّ حُباًّ لِلّٰهِۜ وَلَوْ يَرَى الَّذ۪ينَ ظَلَمُٓوا اِذْ يَرَوْنَ الْعَذَابَۙ اَنَّ الْقُوَّةَ لِلّٰهِ جَم۪يعاًۙ وَاَنَّ اللّٰهَ شَد۪يدُ الْعَذَابِ', 'Ve minen nasi men yettehızu min dunillahi endaden yuhıbbunehum ke hubbillah, vellezine amenu eşeddu hubben lillah, ve lev yerallezine zalemu iz yeravnel azabe, ennel kuvvete lillahi cemian, ve ennellahe şedidul azab.', 'İnsanlardan,  Allah\'ın yanı sıra başka varlıkları O\'na denk tutan ve onları Allah\'ı sevdiği gibi sevenler vardır. İman edenlerin Allah\'ı sevmeleri ise her türlü sevgiden daha üstündür. Keşke zulmedenler,  azabı gördükleri zaman bütün kuvvetin Allah\'a ait olduğunu ve Allah\'ın azabının çok şiddetli olduğunu daha önceden anlayabilselerdi!', 'ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين امنوا اشد حبا لله ولو يري الذين ظلموا اذ يرون العذاب ان القوة لله جميعا وان الله شديد العذاب');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(173, 2, 166, 'اِذْ تَبَرَّاَ الَّذ۪ينَ اتُّبِعُوا مِنَ الَّذ۪ينَ اتَّبَعُوا وَرَاَوُا الْعَذَابَ وَتَقَطَّعَتْ بِهِمُ الْاَسْبَابُ', 'İz teberreellezinettubiu minellezinettebeu ve reavul azabe ve takattaat bihimul esbab.', 'Kendilerine tabi olunanlar,  azabı gördükleri zaman,  tabi olanlardan uzaklaşacak ve aralarındaki bütün bağlar kopacaktır.', 'اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب'),
(174, 2, 167, 'وَقَالَ الَّذ۪ينَ اتَّبَعُوا لَوْ اَنَّ لَنَا كَرَّةً فَنَتَبَرَّاَ مِنْهُمْ كَمَا تَبَرَّؤُ۫ا مِنَّاۜ كَذٰلِكَ يُر۪يهِمُ اللّٰهُ اَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْۜ وَمَا هُمْ بِخَارِج۪ينَ مِنَ النَّارِ۟', 'Ve kalellezinettebeu lev enne lena kerreten fe neteberree minhum kema teberreu minna kezalike yurihimullahu a\'malehum haseratin aleyhim ve ma hum bi haricine minen nar.', 'Tabi olanlar,  diyecekler ki: \"Keşke bize,  tekrar dünyaya dönüş olsaydı da onların şimdi bizden uzaklaştıkları gibi biz de onlardan uzak dursaydık.\" Böylece,  Allah,  pişmanlıklarına sebep olan bütün bu yaptıklarının sonucunu onlara gösterir. Ve onlar ateşten çıkacak da değillerdir.', 'وقال الذين اتبعوا لو ان لنا كرة فنتبرا منهم كما تبروا منا كذلك يريهم الله اعملهم حسرت عليهم وما هم بخرجين من النار'),
(175, 2, 168, 'يَٓا اَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْاَرْضِ حَـلَالاً طَـيِّباًۘ وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِۜ اِنَّهُ لَكُمْ عَدُوٌّ مُب۪ينٌ', 'Ya eyyuhen nasu kulu mimma fil ardı halalen tayyiben, ve la tettebiu hutuvatiş şeytan, innehu lekum aduvvun mubin.', 'Ey insanlar! Yeryüzünde bulunan şeylerin helal ve tayyib[1] olanlarından yiyin. Şeytanın izinden gitmeyin,  çünkü o sizin apaçık düşmanınızdır.', 'يايها الناس كلوا مما في الارض حللا طيبا ولا تتبعوا خطوت الشيطن انه لكم عدو مبين'),
(176, 2, 169, 'اِنَّمَا يَأْمُرُكُمْ بِالسُّٓوءِ وَالْفَحْشَٓاءِ وَاَنْ تَقُولُوا عَلَى اللّٰهِ مَا لَا تَعْلَمُونَ', 'İnnema ye\'murukum bis sui vel fahşai ve en tekulu alallahi ma la ta\'lemun.', 'O[1],  size,  ancak kötülüğü,  fahşayı[2] ve Allah\'a karşı bilmediğiniz şeyleri söylemeyi telkin eder.', 'انما يامركم بالسو والفحشا وان تقولوا علي الله ما لا تعلمون'),
(177, 2, 170, 'وَاِذَا ق۪يلَ لَهُمُ اتَّبِعُوا مَٓا اَنْزَلَ اللّٰهُ قَالُوا بَلْ نَـتَّبِـعُ مَٓا اَلْفَيْنَا عَلَيْهِ اٰبَٓاءَنَاۜ اَوَلَوْ كَانَ اٰبَٓاؤُ۬هُمْ لَا يَعْقِلُونَ شَيْـٔاً وَلَا يَهْتَدُونَ', 'Ve iza kile lehumuttebiu ma enzelallahu kalu bel nettebiu ma elfeyna aleyhi abaena e ve lev kane abauhum la ya\'kılune şey\'en ve la yehtedun.', 'Onlara,  \"Allah\'ın indirdiğine uyun.\" denildiği zaman,  onlar: \"Hayır! Biz,  atalarımızdan gördüğümüz şeylere uyarız.\" derler. Ya ataları akıllarını kullanmayan ve doğru yolu bulamamış kimselerse?', 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه ابانا اولو كان اباوهم لا يعقلون شيا ولا يهتدون'),
(178, 2, 171, 'وَمَثَلُ الَّذ۪ينَ كَفَرُوا كَمَثَلِ الَّذ۪ي يَنْعِقُ بِمَا لَا يَسْمَعُ اِلَّا دُعَٓاءً وَنِدَٓاءًۜ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ', 'Ve meselullezine keferu ke meselillezi yen\'ıku bi ma la yesmeu illa duaen ve nidaa, summun bukmun umyun fe hum la ya\'kılun.', 'Kafirlerin durumu,  çağırmaktan,  seslenmekten başka bir şey duymayan haykıran kimsenin durumu gibidir.[1] Onlar; sağırdırlar,  dilsizdirler,  kördürler. Bu nedenle,  akıllarını da kullanmazlar.', 'ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعا وندا صم بكم عمي فهم لا يعقلون'),
(179, 2, 172, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلّٰهِ اِنْ كُنْتُمْ اِيَّاهُ تَعْبُدُونَ', 'Ya eyyuhellezine amenu kulu min tayyibati ma razaknakum veşkuru lillahi in kuntum iyyahu ta\'budun.', 'Ey iman edenler! Eğer,  sadece O\'na kulluk ediyorsanız,  size rızık olarak verdiğimiz şeylerin sağlıklı,  temiz,  ve iyi olanlarından yiyin ve Allah\'a şükredin.', 'يايها الذين امنوا كلوا من طيبت ما رزقنكم واشكروا لله ان كنتم اياه تعبدون'),
(180, 2, 173, 'اِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنْز۪يرِ وَمَٓا اُهِلَّ بِه۪ لِغَيْرِ اللّٰهِۚ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَٓا اِثْمَ عَلَيْهِۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İnnema harrame aleykumul meytete ved deme ve lahmel hınziri ve ma uhille bihi li gayrillah, fe menidturra gayra bagin ve la adin fe la isme aleyh, innallahe gafurun rahim.', 'O; size,  sadece ölü hayvan etini,  kanı,  domuz etini ve Allah\'tan başkası adına kesilenleri haram kıldı. Mecbur kalan bir kimsenin,  haddi aşmamak ve istismar etmemek koşuluyla,  bunları yemesinde bir günah yoktur. Kuşkusuz,  Allah\'ın Rahmeti Bol ve Kesintisiz\'dir.', 'انما حرم عليكم الميتة والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم'),
(181, 2, 174, 'اِنَّ الَّذ۪ينَ يَكْتُمُونَ مَٓا اَنْزَلَ اللّٰهُ مِنَ الْكِتَابِ وَيَشْتَرُونَ بِه۪ ثَمَناً قَل۪يلاًۙ اُو۬لٰٓئِكَ مَا يَأْكُلُونَ ف۪ي بُطُونِهِمْ اِلَّا النَّارَ وَلَا يُكَلِّمُهُمُ اللّٰهُ يَوْمَ الْقِيٰمَةِ وَلَا يُزَكّ۪يهِمْۚ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnellezine yektumune ma enzelallahu minel kitabi ve yeşterune bihi semenen kalilen, ulaike ma ye\'kulune fi butunihim illen nare ve la yukellimuhumullahu yevmel kıyameti ve la yuzekkihim, ve lehum azabun elim.', 'Allah\'ın indirdiği Kitap\'tan bir kısmını gizleyip,  onu az bir değer karşılığında değiştirenler var ya,  işte onlar,  bununla karınlarına ateşten başka bir şey doldurmuyorlar. Allah,  onlarla Kıyamet Günü\'nde ne konuşacak ne de onları temize çıkaracaktır. Ve onlar için can yakıcı bir azap vardır.', 'ان الذين يكتمون ما انزل الله من الكتب ويشترون به ثمنا قليلا اوليك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيمة ولا يزكيهم ولهم عذاب اليم'),
(182, 2, 175, 'اُو۬لٰٓئِكَ الَّذ۪ينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدٰى وَالْعَذَابَ بِالْمَغْفِرَةِۚ فَمَٓا اَصْبَرَهُمْ عَلَى النَّارِ', 'Ulaikellezineşteravud dalalete bil huda vel azabe bil magfireh, fe ma asberehum alen nar.', 'İşte onlar,  hidayete[1] karşılık sapkınlığı satın alanlardır; bağışlanmaya karşılık azabı. Ateşe ne kadar dayanıklıdırlar!', 'اوليك الذين اشتروا الضللة بالهدي والعذاب بالمغفرة فما اصبرهم علي النار'),
(183, 2, 176, 'ذٰلِكَ بِاَنَّ اللّٰهَ نَزَّلَ الْكِتَابَ بِالْحَقِّۜ وَاِنَّ الَّذ۪ينَ اخْتَلَفُوا فِي الْكِتَابِ لَف۪ي شِقَاقٍ بَع۪يدٍ۟', 'Zalike bi ennellahe nezzelel kitabe bil hakk, ve innellezinahtelefu fil kitabi le fi şikakin baid.', 'İşte bu,  Allah\'ın Hakk olarak indirdiği Kitap hakkında,  onların anlaşmazlığa düşmeleri ve derin bir ayrılık içinde olmalarındandır.', 'ذلك بان الله نزل الكتب بالحق وان الذين اختلفوا في الكتب لفي شقاق بعيد'),
(184, 2, 177, 'لَيْسَ الْبِرَّ اَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلٰكِنَّ الْبِرَّ مَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَالْمَلٰٓئِكَةِ وَالْكِتَابِ وَالنَّبِيّ۪نَۚ وَاٰتَى الْمَالَ عَلٰى حُبِّه۪ ذَوِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينَ وَابْنَ السَّب۪يلِ وَالسَّٓائِل۪ينَ وَفِي الرِّقَابِۚ وَاَقَامَ الصَّلٰوةَ وَاٰتَى الزَّكٰوةَۚ وَالْمُوفُونَ بِعَهْدِهِمْ اِذَا عَاهَدُواۚ وَالصَّابِر۪ينَ فِي الْبَأْسَٓاءِ وَالضَّرَّٓاءِ وَح۪ينَ الْبَأْسِۜ اُو۬لٰٓئِكَ الَّذ۪ينَ صَدَقُواۜ وَاُو۬لٰٓئِكَ هُمُ الْمُتَّقُونَ', 'Leysel birre en tuvellu vucuhekum kıbelel maşrıkı vel magrıbi ve lakinnel birre men amene billahi vel yevmil ahırı vel melaiketi vel kitabi ven nebiyyin, ve atel male ala hubbihi zevil kurba vel yetama vel mesakine vebnes sebili, ves sailine ve fir rıkab, ve ekames salate ve atez zekat, vel mufune bi ahdihim iza ahed, ves sabirine fil be\'sai ved darrai ve hinel be\'s ulaikellezine sadaku, ve ulaike humul muttekun.', 'Yüzünüzü doğu ve batı tarafına çevirmeniz birr[1] değildir. Ama birr: Allah\'a,  Ahiret Günü\'ne,  meleklere,  kitaplara ve nebilere iman etmek; malını sevdiği halde onu yakınlarına,  yetimlere,  yoksullara,  yol oğluna[2],  yardım isteyenlere,  rikab olanlara[3] vermek; \"salatı ikame etmek,  zekat yapmak[4]\",  söz verdiği zaman sözünü yerine getirmek,  sıkıntıda,  zorlukta ve felakete uğrama durumunda sabretmektir. İşte bunlar,  sadık olanlardır. Ve işte bunlar,  takva sahibi olanlardır.', 'ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من امن بالله واليوم الاخر والمليكة والكتب والنبين واتي المال علي حبه ذوي القربي واليتمي والمسكين وابن السبيل والسايلين وفي الرقاب واقام الصلوة واتي الزكوة والموفون بعهدهم اذا عهدوا والصبرين في الباسا والضرا وحين الباس اوليك الذين صدقوا واوليك هم المتقون'),
(185, 2, 178, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلٰىۜ اَلْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْاُنْثٰى بِالْاُنْثٰىۜ فَمَنْ عُفِيَ لَهُ مِنْ اَخ۪يهِ شَيْءٌ فَاتِّبَاعٌ بِالْمَعْرُوفِ وَاَدَٓاءٌ اِلَيْهِ بِاِحْسَانٍۜ ذٰلِكَ تَخْف۪يفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌۜ فَمَنِ اعْتَدٰى بَعْدَ ذٰلِكَ فَلَهُ عَذَابٌ اَل۪يمٌ', 'Ya eyyuhellezine amenu kutibe aleykumul kısasu fil katla el hurru bil hurri vel abdu bil abdi vel unsa bil unsa fe men ufiye lehu min ahihi şey\'un fettibaun bil ma\'rufi ve edaun ileyhi bi ihsan, zalike tahfifun min rabbikum ve rahmeh, fe meni\'teda ba\'de zalike fe lehu azabun elim.', 'Ey iman edenler! Öldürülmelerde size kısas yazıldı;[1] hüre hür,  abde abd[2],  kadına kadın.[3] Ancak öldüren,  öldürülenin kardeşi[4] tarafından bağışlanırsa; örfe uygun şekilde,  diyeti iyilikle ödemelidir. Bu Rabb\'inizden bir hafifletme ve rahmettir. Bundan sonra kim haddi aşarsa,  onun için can yakıcı bir azap vardır.', 'يايها الذين امنوا كتب عليكم القصاص في القتلي الحر بالحر والعبد بالعبد والانثي بالانثي فمن عفي له من اخيه شي فاتباع بالمعروف وادا اليه باحسن ذلك تخفيف من ربكم ورحمة فمن اعتدي بعد ذلك فله عذاب اليم'),
(186, 2, 179, 'وَلَكُمْ فِي الْقِصَاصِ حَيٰوةٌ يَٓا اُو۬لِي الْاَلْبَابِ لَعَلَّكُمْ تَتَّقُونَ', 'Ve lekum fil kısası hayatun ya ulil elbabi leallekum tettekun.', 'Ey sağlıklı düşünen,  sağduyu sahipleri! Kısasta sizin için hayat vardır.[1] Umulur ki takva[2] sahibi olursunuz.', 'ولكم في القصاص حيوة ياولي الالبب لعلكم تتقون'),
(187, 2, 180, 'كُتِبَ عَلَيْكُمْ اِذَا حَضَرَ اَحَدَكُمُ الْمَوْتُ اِنْ تَرَكَ خَيْراًۚ اَلْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْاَقْرَب۪ينَ بِالْمَعْرُوفِۚ حَقاًّ عَلَى الْمُتَّق۪ينَۜ', 'Kutibe aleykum iza hadara ehadekumul mevtu in tereke hayra, el vasiyyetu lil valideyni vel akrabine bil ma\'ruf, hakkan alel muttekin.', 'Birinize ölüm geldiği zaman; eğer geride bir hayır[1] bırakıyorsa,  anneye,  babaya,  yakın akrabaya örfe uygun bir şekilde vasiyette bulunmak,  takva sahibi olanların üzerine bir hak olarak yazıldı.[2]', 'كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصية للولدين والاقربين بالمعروف حقا علي المتقين'),
(188, 2, 181, 'فَمَنْ بَدَّلَهُ بَعْدَ مَا سَمِعَهُ فَاِنَّمَٓا اِثْمُهُ عَلَى الَّذ۪ينَ يُبَدِّلُونَهُۜ اِنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌۜ', 'Fe men beddelehu ba\'de ma semiahu fe innema ismuhu alellezine yubeddiluneh, innallahe semiun alim.', 'Her kim,  bu vasiyeti duyduktan sonra onu değiştirirse,  doğrusu onun günahı değiştirenin üzerinedir. Kuşkusuz Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'فمن بدله بعدما سمعه فانما اثمه علي الذين يبدلونه ان الله سميع عليم'),
(189, 2, 182, 'فَمَنْ خَافَ مِنْ مُوصٍ جَنَفاً اَوْ اِثْماً فَاَصْلَحَ بَيْنَهُمْ فَلَٓا اِثْمَ عَلَيْهِۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ۟', 'Fe men hafe min musın cenefen ev ismen fe aslaha beynehum fe la isme aleyh, innallahe gafurun rahim.', 'Kim,  vasiyet edenin yanılacağından veya günaha gireceğinden endişe ederse,  taraflar arasında uzlaşma sağlamasında,  ona bir günah yoktur. Kuşkusuz Allah Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم'),
(190, 2, 183, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذ۪ينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَۙ', 'Ya eyyuhellezine amenu kutibe aleykumus sıyamu kema kutibe alellezine min kablikum leallekum tettekun.', 'Ey iman edenler! Sizden öncekilere yazıldığı[1] gibi,  siyam[2] size de yazıldı. Umulur ki takva sahibi olursunuz.', 'يايها الذين امنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون'),
(191, 2, 184, 'اَيَّاماً مَعْدُودَاتٍۜ فَمَنْ كَانَ مِنْكُمْ مَر۪يضاً اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِنْ اَيَّامٍ اُخَرَۜ وَعَلَى الَّذ۪ينَ يُط۪يقُونَهُ فِدْيَةٌ طَعَامُ مِسْك۪ينٍۜ فَمَنْ تَطَوَّعَ خَيْراً فَهُوَ خَيْرٌ لَهُۜ وَاَنْ تَصُومُوا خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Eyyamen ma\'dudat, fe men kane minkum maridan ev ala seferin fe iddetun min eyyamin uhar ve alellezine yutikunehu fidyetun taamu miskin, fe men tatavvaa hayran fe huve hayrun leh, ve en tesumu hayrun lekum in kuntum ta\'lemun.', 'Sayılı günlerdir.[1] Artık sizden kim hastalanır veya seferde olursa tutamadığı günler sayısınca başka günlerde tutsun. Onu tutmaya gücü yetenlerin[2],  bir yoksulu doyuracak kadar fidye vermesi gerekir. Böyle olmakla birlikte,  kim gönlünden gelerek daha fazlasını yaparsa,  bu,  onun için daha hayırlıdır. Eğer bilirseniz,  siyam yapmanız [3] sizin için hayırlı olandır.', 'اياما معدودت فمن كان منكم مريضا او علي سفر فعدة من ايام اخر وعلي الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون'),
(192, 2, 185, 'شَهْرُ رَمَضَانَ الَّذ۪ٓي اُنْزِلَ ف۪يهِ الْقُرْاٰنُ هُدًى لِلنَّاسِ وَبَيِّنَاتٍ مِنَ الْهُدٰى وَالْفُرْقَانِۚ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُۜ وَمَنْ كَانَ مَر۪يضاً اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِنْ اَيَّامٍ اُخَرَۜ يُر۪يدُ اللّٰهُ بِكُمُ الْيُسْرَ وَلَا يُر۪يدُ بِكُمُ الْعُسْرَۘ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللّٰهَ عَلٰى مَا هَدٰيكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Şehru ramadanellezi unzile fihil kur\'anu huden lin nasi ve beyyinatin minel huda vel furkan, fe men şehide minkumuş şehra fel yesumh, ve men kane maridan ev ala seferin fe iddetun min eyyamin uhar yuridullahu bikumul yusra ve la yuridu bikumul usra, ve li tukmilul iddete ve li tukebbirullahe ala ma hedakum ve leallekum teşkurun.', 'Ramazan ayı ki: İnsanlar için hidayet rehberi olan,  doğru yola ileten,  doğru ile yanlışı birbirinden ayıran; apaçık kanıtları içeren Kur\'an o ayda indirildi. Sizden,  kim bu aya erişirse savm/siyam yapsın.[1] Kim de hasta veya yolcu olursa,  tutamadığı günler sayısınca başka günlerde tutsun. Allah,  sizin için zorluk değil kolaylık diler. Allah,  belirlenen günlerin sayısını tamamlamanızı ve size doğru yolu gösterdiğinden,  Kendisini yüceltmenizi ister ki böylece şükretmiş olursunuz.', 'شهر رمضان الذي انزل فيه القران هدي للناس وبينت من الهدي والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او علي سفر فعدة من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العدة ولتكبروا الله علي ما هديكم ولعلكم تشكرون'),
(193, 2, 186, 'وَاِذَا سَاَلَكَ عِبَاد۪ي عَنّ۪ي فَاِنّ۪ي قَر۪يبٌۜ اُج۪يبُ دَعْوَةَ الدَّاعِ اِذَا دَعَانِۙ فَلْيَسْتَج۪يبُوا ل۪ي وَلْيُؤْمِنُوا ب۪ي لَعَلَّهُمْ يَرْشُدُونَ', 'Ve iza seeleke ıbadi anni fe inni karib ucibu da\'veted dai iza deani, fel yestecibu li vel yu\'minu bi leallehum yerşudun.', 'Kullarım,  sana,  Ben\'i sorarlarsa bilsinler ki Ben,  yakınım. Bana dua edenin,  duasına karşılık veririm. O halde onlar da Benim çağrıma uysunlar ve Bana gerçek anlamda iman etsinler. Böylece irşad[1] olurlar.[2]', 'واذا سالك عبادي عني فاني قريب اجيب دعوة الداع اذا دعان فليستجيبوا لي وليومنوا بي لعلهم يرشدون'),
(194, 2, 187, 'اُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ اِلٰى نِسَٓائِكُمْۜ هُنَّ لِبَاسٌ لَكُمْ وَاَنْتُمْ لِبَاسٌ لَهُنَّۜ عَلِمَ اللّٰهُ اَنَّكُمْ كُنْتُمْ تَخْتَانُونَ اَنْفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْۚ فَالْـٰٔنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللّٰهُ لَكُمْۖ وَكُلُوا وَاشْرَبُوا حَتّٰى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْاَبْيَضُ مِنَ الْخَيْطِ الْاَسْوَدِ مِنَ الْفَجْرِۖ ثُمَّ اَتِمُّوا الصِّيَامَ اِلَى الَّيْلِۚ وَلَا تُبَاشِرُوهُنَّ وَاَنْتُمْ عَاكِفُونَۙ فِي الْمَسَاجِدِۜ تِلْكَ حُدُودُ اللّٰهِ فَلَا تَقْرَبُوهَاۜ  كَذٰلِكَ يُبَيِّنُ اللّٰهُ اٰيَاتِه۪ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', 'Uhılle lekum leyletes sıyamir refesu ila nisaikum hunne libasun lekum ve entum libasun lehun alimallahu ennekum kuntum tahtanune enfusekum fe tabe aleykum ve afa ankum, fel ane başiruhunne vebtegu ma keteballahu lekum, ve kulu veşrabu hatta yetebeyyene lekumul haytul ebyadu minel haytıl esvedi minel fecri, summe etimmus sıyame ilel leyli, ve la tubaşiruhunne ve entum akifune fil mesacid, tilke hududullahi fe la takrabuha kezalike yubeyyinullahu ayatihi lin nasi leallehum yettekun.', 'Siyam[1] gecesinde kadınlarınıza yaklaşmanız sizin için helal kılındı. Onlar,  sizin için örtüdür; siz de onlar için örtüsünüz. Allah,  nefsinize sahip olmadığınızı bildi ve tevbenizi kabul edip sizi bağışladı. Artık onlara yaklaşın,  Allah\'ın sizin için yazdığı[2] şeyi isteyin. Şafak vaktinin siyah ipliği,  beyaz ipliğinden[3] ayırt edilme anına kadar,  yiyin için. Sonra da geceye dek siyamı tamamlayın. Eğer mescitlerde itikaftaysanız[4] onlara yaklaşmayın. Bunlar,  Allah\'ın koyduğu sınırlardır. Bu sınırlara yaklaşmayın. İşte böylece Allah,  insanlara ayetlerini açıklar. Umulur ki takva sahibi olursunuz.', 'احل لكم ليلة الصيام الرفث الي نسايكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالن بشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتي يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الي اليل ولا تبشروهن وانتم عكفون في المسجد تلك حدود الله فلا تقربوها كذلك يبين الله ايته للناس لعلهم يتقون'),
(195, 2, 188, 'وَلَا تَأْكُلُٓوا اَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ وَتُدْلُوا بِهَٓا اِلَى الْحُكَّامِ لِتَأْكُلُوا فَر۪يقاً مِنْ اَمْوَالِ النَّاسِ بِالْاِثْمِ وَاَنْتُمْ تَعْلَمُونَ۟', 'Ve la te\'kulu emvalekum beynekum bil batılı ve tudlu biha ilel hukkami li te\'kulu ferikan min emvalin nasi bil ismi ve entum ta\'lemun.', 'Birbirinizin mallarını haksız şekilde yemeyin. Günah olduğunu[1] bildiğiniz halde,  başkasının bir kısım mallarına haksız yere sahip olabilmek için hukuki hileye başvurmayın.', 'ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الي الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون'),
(196, 2, 189, 'يَسْـَٔلُونَكَ عَنِ الْاَهِلَّةِۜ قُلْ هِيَ مَوَاق۪يتُ لِلنَّاسِ وَالْحَجِّۜ وَلَيْسَ الْبِرُّ بِاَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا وَلٰكِنَّ الْبِرَّ مَنِ اتَّقٰىۚ وَأْتُوا الْبُيُوتَ مِنْ اَبْوَابِهَاۖ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُونَ', 'Yes\'eluneke anil ehilleh, kul hiye mevakitu lin nasi vel hacc, ve leysel birru bi en te\'tul buyute min zuhuriha ve lakinnel birre menitteka, ve\'tul buyute min ebvabiha, vettekullahe leallekum tuflihun.', 'Sana,  ayın evrelerini soruyorlar. De ki: \"O,  insanlar ve hacc için bir zaman ölçüsüdür.\" Evlerinize arkalarından girmeniz birr[1] değildir; birr,  takvalı davranmaktır. Öyleyse evlerinize kapılarından girin.[2] Allah\'a karşı takvalı olun ki kurtuluşa erebilesiniz.', 'يسلونك عن الاهلة قل هي موقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقي واتوا البيوت من ابوبها واتقوا الله لعلكم تفلحون'),
(197, 2, 190, 'وَقَاتِلُوا ف۪ي سَب۪يلِ اللّٰهِ الَّذ۪ينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُواۜ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُعْتَد۪ينَ', 'Ve katilu fi sebilillahillezine yukatilunekum ve la ta\'tedu innallahe la yuhıbbul mu\'tedin.', 'Sizinle savaşanlara karşı siz de Allah yolunda onlarla savaşın. Ama haddi aşmayın. Kuşkusuz Allah,  haddi aşanları sevmez.', 'وقتلوا في سبيل الله الذين يقتلونكم ولا تعتدوا ان الله لا يحب المعتدين'),
(198, 2, 191, 'وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَاَخْرِجُوهُمْ مِنْ حَيْثُ اَخْرَجُوكُمْ وَالْفِتْنَةُ اَشَدُّ مِنَ الْقَتْلِۚ وَلَا تُقَاتِلُوهُمْ عِنْدَ الْمَسْجِدِ الْحَرَامِ حَتّٰى يُقَاتِلُوكُمْ ف۪يهِۚ فَاِنْ قَاتَلُوكُمْ فَاقْتُلُوهُمْۜ  كَذٰلِكَ جَزَٓاءُ الْكَافِر۪ينَ', 'Vaktuluhum haysu sekıftumuhum ve ahricuhum min haysu ahracukum vel fitnetu eşeddu minel katli, ve la tukatiluhum indel mescidil harami hatta yukatilukum fih, fe in katelukum faktuluhum kezalike cezaul kafirin.', 'Onları yakaladığınız yerde öldürün.[1] Sizi çıkardıkları yerden siz de onları çıkartın. Zaten,  fitne[2] öldürmekten daha kötüdür. Onlar,  Mescid-i Haram çevresinde sizinle savaşmadıkça siz de onlarla savaşmayın. Eğer savaşırlarsa,  siz de savaşın. İşte Kafirlere verilecek karşılık böyledir.', 'واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنة اشد من القتل ولا تقتلوهم عند المسجد الحرام حتي يقتلوكم فيه فان قتلوكم فاقتلوهم كذلك جزا الكفرين'),
(199, 2, 192, 'فَاِنِ انْتَهَوْا فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Fe inintehev fe innallahe gafurun rahim.', 'Eğer vazgeçerlerse,  kuşkusuz,  Allah,  Bağışlayıcı,  Rahmeti Kesintisiz Olan\'dır.', 'فان انتهوا فان الله غفور رحيم'),
(200, 2, 193, 'وَقَاتِلُوهُمْ حَتّٰى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدّ۪ينُ لِلّٰهِۜ  فَاِنِ انْتَهَوْا فَلَا عُدْوَانَ اِلَّا عَلَى الظَّالِم۪ينَ', 'Ve katiluhum hatta la tekune fitnetun ve yekuned dinu lillah, fe inintehev fe la udvane illa alez zalimin.', 'Fitne[1] kalmayıp,  din[2] tamamıyla Allah\'ın oluncaya kadar onlarla savaşın. Eğer vazgeçerlerse zalimlerden başkasına düşmanlık yoktur.', 'وقتلوهم حتي لا تكون فتنة ويكون الدين لله فان انتهوا فلا عدون الا علي الظلمين'),
(201, 2, 194, 'اَلشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ وَالْحُرُمَاتُ قِصَاصٌۜ فَمَنِ اعْتَدٰى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدٰى عَلَيْكُمْۖ وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّ اللّٰهَ مَعَ الْمُتَّق۪ينَ', 'Eş şehrul haramu biş şehril harami vel hurumatu kısas, fe meni\'teda aleykum fa\'tedu aleyhi bi misli ma\'teda aleykum, vettekullahe va\'lemu ennellahe meal muttekin.', 'Haram ay[1],  haram aya karşılıktır. Hürmetler de karşılıklıdır. Kim,  size saldırırsa siz de onlara aynı şekilde karşılık verin. Allah\'a karşı takvalı olun. Ve iyi bilin ki Allah,  takvalı olanlarla beraberdir.', 'الشهر الحرام بالشهر الحرام والحرمت قصاص فمن اعتدي عليكم فاعتدوا عليه بمثل ما اعتدي عليكم واتقوا الله واعلموا ان الله مع المتقين'),
(202, 2, 195, 'وَاَنْفِقُوا ف۪ي سَب۪يلِ اللّٰهِ وَلَا تُلْقُوا بِاَيْد۪يكُمْ اِلَى التَّهْلُكَةِۚۛ وَاَحْسِنُواۚۛ اِنَّ اللّٰهَ يُحِبُّ الْمُحْسِن۪ينَ', 'Ve enfiku fi sebilillahi ve la tulku bi eydikum ilet tehluketi, ve ahsinu, innallahe yuhıbbul muhsinin.', 'Allah yolunda malınızı infak[1] edin. Kendi ellerinizle kendinizi tehlikeye atmayın. İyilik yapın. Kuşkusuz,  Allah,  iyilik yapanları sever.', 'وانفقوا في سبيل الله ولا تلقوا بايديكم الي التهلكة واحسنوا ان الله يحب المحسنين'),
(203, 2, 196, 'وَاَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلّٰهِۜ فَاِنْ اُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِۚ وَلَا تَحْلِقُوا رُؤُ۫سَكُمْ حَتّٰى يَبْلُغَ الْهَدْيُ مَحِلَّهُۜ   فَمَنْ كَانَ مِنْكُمْ مَر۪يضاً اَوْ بِه۪ٓ  اَذًى مِنْ رَأْسِه۪ فَفِدْيَةٌ مِنْ صِيَامٍ اَوْ صَدَقَةٍ اَوْ نُسُكٍۚ فَاِذَٓا اَمِنْتُمْ۠  فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ اِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِۚ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلٰثَةِ اَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ اِذَا رَجَعْتُمْۜ  تِلْكَ عَشَرَةٌ   كَامِلَةٌۜ  ذٰلِكَ لِمَنْ لَمْ يَكُنْ اَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِۜ  وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ۟', 'Ve etimmul hacce vel umrete lillah, fe in uhsirtum fe mesteysera minel hedyi ve la tahliku ruusekum hatta yeblugal hedyu mahilleh, fe men kane minkum maridan ev bihi ezen min ra\'sihi fe fidyetun min sıyamin ev sadakatin ev nusuk fe iza emintum, fe men temettea bil umreti ilel haccı fe mesteysera minel hedyi, fe men lem yecid fe sıyamu selaseti eyyamin fil haccı ve seb\'atin iza reca\'tum tilke aşaratun kamileh, zalike li men lem yekun ehluhu hadırıl mescidil haram, vettekullahe va\'lemu ennellahe şedidul ikab.', 'Allah için Haccı ve Umreyi tam yapın. Eğer engellenirseniz,  o zaman hediyeden[1] kolayınıza gelen şeyi gönderin! Ancak hediye yerine ulaşıncaya kadar başınızı tıraş etmeyin.[2] Sizden hasta olan veya başından bir rahatsızlığı bulunan; oruç tutmalı veya sadaka vermeli ya da nusuktan[3] sayılacak bir fidye[4] vermeli! Emin olduğunuz vakitte; kim,  hac vaktine kadar umre ile faydalanmak isterse,  hediyeden kolayına geleni göndermeli! Fakat kim bulamazsa,  hac günlerinde üç,  döndükten sonra da yedi gün olmak üzere toplam on gün oruç tutsun. Bu,  ailesi Mescid-i Haram çevresinde oturmayanlar içindir. Allah\'a karşı takvalı davranın. Ve bilin ki Allah\'ın cezası çok şiddetlidir.', 'واتموا الحج والعمرة لله فان احصرتم فما استيسر من الهدي ولا تحلقوا روسكم حتي يبلغ الهدي محله فمن كان منكم مريضا او به اذي من راسه ففدية من صيام او صدقة او نسك فاذا امنتم فمن تمتع بالعمرة الي الحج فما استيسر من الهدي فمن لم يجد فصيام ثلثة ايام في الحج وسبعة اذا رجعتم تلك عشرة كاملة ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب'),
(204, 2, 197, 'اَلْحَجُّ اَشْهُرٌ مَعْلُومَاتٌۚ فَمَنْ فَرَضَ ف۪يهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّۜ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللّٰهُۜ وَتَزَوَّدُوا فَاِنَّ خَيْرَ الزَّادِ التَّقْوٰىۘ وَاتَّقُونِ يَٓا اُو۬لِي الْاَلْبَابِ', 'El haccu eşhurun ma\'lumat, fe men farada fihinnel hacca fe la refese ve la fusuka ve la cidale fil hacc, ve ma tef\'alu min hayrın ya\'lemhullah, ve tezevvedu fe inne hayraz zadit takva, vettekuni ya ulil elbab.', 'Hacc,  bilinen aylardır. Kim haccı farz edinirse;[1] o esnada,  uygunsuz davranmak,  fasıklık[2] yapmak ve kavga etmek yoktur. Ne hayır işlerseniz Allah onu bilir. Azık edinin. Kuşkusuz azığın en hayırlısı takvadır.[3] Ey selim akıl sahipleri! Bana karşı takvalı olun!', 'الحج اشهر معلومت فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوي واتقون ياولي الالبب'),
(205, 2, 198, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْۜ فَاِذَٓا اَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللّٰهَ عِنْدَ الْمَشْعَرِ الْحَرَامِۖ وَاذْكُرُوهُ كَمَا هَدٰيكُمْۚ وَاِنْ كُنْتُمْ مِنْ قَبْلِه۪ لَمِنَ الضَّٓالّ۪ينَ', 'Leyse aleykum cunahun en tebtegu fadlan min rabbikum fe iza efadtum min arafatin fezkurullahe indel meş\'aril haram, vezkuruhu kema hedakum, ve in kuntum min kablihi le mined dallin.', 'Rabb\'inizden lütuf[1] istemenizde bir sakınca yoktur. Artık Arafat\'tan ayrılıp,  akın ettiğinizde Meş\'ar-i Haram\'da Allah\'ı anın. O,  size nasıl doğru yolu gösterdiyse,  siz de O\'nu öyle anın.[2] Kuşkusuz,  O,  doğru yolu göstermeden önce siz sapkınlardandınız.', 'ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفت فاذكروا الله عند المشعر الحرام واذكروه كما هديكم وان كنتم من قبله لمن الضالين'),
(206, 2, 199, 'ثُمَّ اَف۪يضُوا مِنْ حَيْثُ اَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللّٰهَۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Summe efidu min haysu efadan nasu vestagfirullah, innallahe gafurun rahim.', 'Sonra,  insanların dağıldığı yerden siz de dağılın. Allah\'tan bağışlanma dileyin. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم'),
(207, 2, 200, 'فَاِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللّٰهَ كَذِكْرِكُمْ اٰبَٓاءَكُمْ اَوْ اَشَدَّ ذِكْراًۜ فَمِنَ النَّاسِ مَنْ يَقُولُ رَبَّنَٓا اٰتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الْاٰخِرَةِ مِنْ خَلَاقٍ', 'Fe iza kadaytum menasikekum fezkurullahe ke zikrikum abaekum ev eşedde zikra, fe minen nasi men yekulu rabbena atina fid dunya ve ma lehu fil ahirati min halak.', 'Hacc menasiklerinizi[1] bitirince,  atalarınızı andığınız gibi; hatta daha güçlü bir şekilde Allah\'ı anın. Kimi insanlar; \"Ey Rabb\'imiz,  bize dünyada ver.\" derler. Bu kimselerin ahirette bir payı yoktur.', 'فاذا قضيتم منسككم فاذكروا الله كذكركم اباكم او اشد ذكرا فمن الناس من يقول ربنا اتنا في الدنيا وما له في الاخرة من خلق'),
(208, 2, 201, 'وَمِنْهُمْ مَنْ يَقُولُ رَبَّنَٓا اٰتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْاٰخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Ve minhum men yekulu rabbena atina fid dunya haseneten ve fil ahirati haseneten ve kına azaben nar.', 'Kimileri de: \"Rabb\'imiz,  bize dünyada da iyilik,  ahirette de iyilik ver ve bizi ateşin azabından koru.\" derler.', 'ومنهم من يقول ربنا اتنا في الدنيا حسنة وفي الاخرة حسنة وقنا عذاب النار'),
(209, 2, 202, 'اُو۬لٰٓئِكَ لَهُمْ نَص۪يبٌ مِمَّا كَسَبُواۜ وَاللّٰهُ سَر۪يعُ الْحِسَابِ', 'Ulaike lehum nasibun mimma kesebu vallahu seriul hısab.', 'İşte bunların,  kazandıklarına karşılık payları vardır. Allah,  hesabı çabuk görendir.', 'اوليك لهم نصيب مما كسبوا والله سريع الحساب'),
(210, 2, 203, 'وَاذْكُرُوا اللّٰهَ ف۪ٓي اَيَّامٍ مَعْدُودَاتٍۜ فَمَنْ تَعَجَّلَ ف۪ي يَوْمَيْنِ فَلَٓا اِثْمَ عَلَيْهِۚ وَمَنْ تَاَخَّرَ فَلَٓا اِثْمَ عَلَيْهِۙ لِمَنِ اتَّقٰىۜ وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّكُمْ اِلَيْهِ تُحْشَرُونَ', 'Vezkurullahe fi eyyamin ma\'dudat, fe men teaccele fi yevmeyni fe la isme aleyh, ve men teahhara fe la isme aleyhi, li menitteka vettekullahe va\'lemu ennekum ileyhi tuhşerun.', 'Sayılı günlerde Allah\'ı anın. Kim acele edip,  iki gün içinde dönerse ona günah yoktur. Kim geri kalırsa takvalı olduğu takdirde ona da günah yoktur. Allah\'a karşı takvalı olun ve bilin ki O\'nun huzurunda toplanacaksınız.', 'واذكروا الله في ايام معدودت فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقي واتقوا الله واعلموا انكم اليه تحشرون'),
(211, 2, 204, 'وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ فِي الْحَيٰوةِ الدُّنْيَا وَيُشْهِدُ اللّٰهَ عَلٰى مَا ف۪ي قَلْبِه۪ۙ وَهُوَ اَلَدُّ الْخِصَامِ', 'Ve minen nasi men yu\'cibuke kavluhu fil hayatid dunya ve yuşhidullahe ala ma fi kalbihi, ve huve eleddul hısam.', 'Kimi insanın,  dünya hayatı ile ilgili sözü senin hoşuna gider. Kalbindekine[1] Allah\'ı şahit tutar. Oysaki o düşmanların en azılısıdır.', 'ومن الناس من يعجبك قوله في الحيوة الدنيا ويشهد الله علي ما في قلبه وهو الد الخصام'),
(212, 2, 205, 'وَاِذَا تَوَلّٰى سَعٰى فِي الْاَرْضِ لِيُفْسِدَ ف۪يهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَۜ وَاللّٰهُ لَا يُحِبُّ الْفَسَادَ', 'Ve iza tevella sea fil ardı li yufside fiha ve yuhlikel harse ven nesl, vallahu la yuhıbbul fesad.', 'Senden ayrılınca[1],  yeryüzünde bozgunculuk yapmaya,  ürünü ve nesli yok etmeye çalışır. Allah ise bozgunculuğu sevmez.', 'واذا تولي سعي في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد'),
(213, 2, 206, 'وَاِذَا ق۪يلَ لَهُ اتَّقِ اللّٰهَ اَخَذَتْهُ الْعِزَّةُ بِالْاِثْمِ فَحَسْبُهُ جَهَنَّمُۜ وَلَبِئْسَ الْمِهَادُ', 'Ve iza kile lehuttekıllahe ehazethul izzetu bil ismi fe hasbuhu cehennem, ve le bi\'sel mihad.', 'Ona,  \"Allah\'a karşı takvalı ol.\" dendiği zaman,  kendisini üstün görmesi onu günaha sevk eder. İşte böylesine Cehennem yeter. O,  ne kötü bir döşektir!', 'واذا قيل له اتق الله اخذته العزة بالاثم فحسبه جهنم ولبيس المهاد'),
(214, 2, 207, 'وَمِنَ النَّاسِ مَنْ يَشْر۪ي نَفْسَهُ ابْتِغَٓاءَ مَرْضَاتِ اللّٰهِۜ وَاللّٰهُ رَؤُ۫فٌ بِالْعِبَادِ', 'Ve minen nasi men yeşri nefsehubtigae mardatillah, vallahu raufun bil ıbad.', 'Kimi insanlar da kendisini Allah\'ın rızasını kazanmaya adar. Allah,  kullarına karşı Çok Şefkatli\'dir.', 'ومن الناس من يشري نفسه ابتغا مرضات الله والله روف بالعباد'),
(215, 2, 208, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا ادْخُلُوا فِي السِّلْمِ كَٓافَّةًۖ وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِۜ اِنَّهُ لَكُمْ عَدُوٌّ مُب۪ينٌ', 'Ya eyyuhellezine amenudhulu fis silmi kaffeh, ve la tettebiu hutuvatiş şeytan, innehu lekum aduvvun mubin.', 'Ey iman edenler! Bir bütün olarak[1] Silm\'e[2] girin. Şeytanın izinden gitmeyin. Kuşkusuz o,  sizin apaçık düşmanınızdır.', 'يايها الذين امنوا ادخلوا في السلم كافة ولا تتبعوا خطوت الشيطن انه لكم عدو مبين'),
(216, 2, 209, 'فَاِنْ زَلَلْتُمْ مِنْ بَعْدِ مَا جَٓاءَتْكُمُ الْبَيِّنَاتُ فَاعْلَمُٓوا اَنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ', 'Fe in zeleltum min ba\'di ma caetkumul beyyinatu fa\'lemu ennallahe azizun hakim.', 'Size gelen açık kanıtlara rağmen yine de ayağınız kayarsa[1],  şunu iyi bilin ki Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'فان زللتم من بعد ما جاتكم البينت فاعلموا ان الله عزيز حكيم'),
(217, 2, 210, 'هَلْ يَنْظُرُونَ اِلَّٓا اَنْ يَأْتِيَهُمُ اللّٰهُ ف۪ي ظُلَلٍ مِنَ الْغَمَامِ وَالْمَلٰٓئِكَةُ وَقُضِيَ الْاَمْرُۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ۟', 'Hel yenzurune illa en ye\'tiyehumullahu fi zulelin minel gamami vel melaiketu ve kudiyel emr, ve ilallahi turceul umur.', 'Yoksa onlar,  Allah\'ın ve meleklerin bulut gölgeleri içinden çıkıp gelmesini ve işlerini bitirmesini mi bekliyorlar? Oysa bütün işler,  yalnızca Allah\'a döndürülür.', 'هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والمليكة وقضي الامر والي الله ترجع الامور'),
(218, 2, 211, 'سَلْ بَن۪ٓي اِسْرَٓائ۪لَ كَمْ اٰتَيْنَاهُمْ مِنْ اٰيَةٍ بَيِّنَةٍۜ وَمَنْ يُبَدِّلْ نِعْمَةَ اللّٰهِ مِنْ بَعْدِ مَا جَٓاءَتْهُ فَاِنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ', 'Sel beni israile kem ateynahum min ayetin beyyineh, ve men yubeddil ni\'metallahi min ba\'di ma caethu fe innallahe şedidul ikab.', 'İsrailoğulları\'na sor; Biz,  onlara nice açık ayetler verdik. Kim,  Allah\'ın nimeti[1] kendisine geldikten sonra onu değiştirirse; artık kuşkusuz Allah,  Azabı Çok Şiddetli Olan\'dır.', 'سل بني اسريل كم اتينهم من اية بينة ومن يبدل نعمة الله من بعد ما جاته فان الله شديد العقاب'),
(219, 2, 212, 'زُيِّنَ لِلَّذ۪ينَ كَفَرُوا الْحَيٰوةُ الدُّنْيَا وَيَسْخَرُونَ مِنَ الَّذ۪ينَ اٰمَنُواۢ وَالَّذ۪ينَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيٰمَةِۜ وَاللّٰهُ يَرْزُقُ مَنْ يَشَٓاءُ بِغَيْرِ حِسَابٍ', 'Zuyyine lillezine keferul hayatud dunya ve yesharune minellezine amenu, vellezinettekav fevkahum yevmel kıyameh, vallahu yerzuku men yeşau bi gayrihisab.', 'Kafirlere dünya hayatı süslü gösterildi. Onlar,  iman edenlerle alay ederler. Oysa takva sahibi olan kimseler,  Kıyamet Günü\'nde onlardan üstün durumdadırlar. Allah,  dilediğine hesapsız rızık verir.', 'زين للذين كفروا الحيوة الدنيا ويسخرون من الذين امنوا والذين اتقوا فوقهم يوم القيمة والله يرزق من يشا بغير حساب'),
(220, 2, 213, 'كَانَ النَّاسُ اُمَّةً وَاحِدَةً فَبَعَثَ اللّٰهُ النَّبِيّ۪نَ مُبَشِّر۪ينَ وَمُنْذِر۪ينَۖ وَاَنْزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ ف۪يمَا اخْتَلَفُوا ف۪يهِۜ وَمَا اخْتَلَفَ ف۪يهِ اِلَّا الَّذ۪ينَ اُو۫تُوهُ مِنْ بَعْدِ مَا جَٓاءَتْهُمُ الْبَيِّنَاتُ بَغْياً بَيْنَهُمْۚ فَهَدَى اللّٰهُ الَّذ۪ينَ اٰمَنُوا لِمَا اخْتَلَفُوا ف۪يهِ مِنَ الْحَقِّ بِاِذْنِه۪ۜ وَاللّٰهُ يَهْد۪ي مَنْ يَشَٓاءُ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Kanen nasu ummeten vahıdeten fe beasallahun nebiyyine mubeşşirine ve munzirine, ve enzele meahumul kitabe bil hakkı li yahkume beynen nasi fi mahtelefu fih, ve mahtelefe fihi illellezine utuhu min ba\'di ma caethumul beyyinatu bagyen beynehum, fe hedallahullezine amenu li mahtelefu fihi minel hakkı bi iznih, vallahu yehdi men yeşau ila sıratın mustakim.', 'İnsanlar bir tek ümmetti. Allah; onlara,  haber verici ve uyarıcı nebiler gönderdi. Anlaşmazlığa düştükleri konularda aralarında Hakk ile hükmetmeleri için onlarla beraber Kitap indirdi. Kitap verilenler,  kendilerine apaçık kanıtlar gelmesine rağmen,  aralarındaki ihtiras nedeniyle onda anlaşmazlığa düştüler. Bunun üzerine Allah,  iman edenleri Kendi izni ile[1] onların üzerinde ayrılığa düştükleri gerçeğe iletti. Zira Allah,  hak edeni[2] doğru yola iletir.', 'كان الناس امة وحدة فبعث الله النبين مبشرين ومنذرين وانزل معهم الكتب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاتهم البينت بغيا بينهم فهدي الله الذين امنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشا الي صرط مستقيم'),
(221, 2, 214, 'اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذ۪ينَ خَلَوْا مِنْ قَبْلِكُمْۜ مَسَّتْهُمُ الْبَأْسَٓاءُ وَالضَّرَّٓاءُ وَزُلْزِلُوا حَتّٰى يَقُولَ الرَّسُولُ وَالَّذ۪ينَ اٰمَنُوا مَعَهُ مَتٰى نَصْرُ اللّٰهِۜ اَلَٓا اِنَّ نَصْرَ اللّٰهِ قَر۪يبٌ', 'Em hasibtum en tedhulul cennete ve lemma ye\'tikum meselullezine halev min kablikum messethumul be\'sau ved darrau ve zulzilu hatta yekuler resulu vellezine amenu meahu meta nasrullah, e la inne nasrallahi karib.', 'Sizden öncekiler gibi sıkıntı ve zorluklar çekmeden Cennet\'e gireceğinizi mi sandınız? Onlara dokunan sıkıntı ve zorluklarla öylesine sarsıldılar ki Resul ve onunla birlikte olan Müminler,  \"Allah\'ın yardımı ne zaman?\" dediler. İyi bilin ki Allah\'ın yardımı yakındır.', 'ام حسبتم ان تدخلوا الجنة ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباسا والضرا وزلزلوا حتي يقول الرسول والذين امنوا معه متي نصر الله الا ان نصر الله قريب'),
(222, 2, 215, 'يَسْـَٔلُونَكَ مَاذَا يُنْفِقُونَۜ قُلْ مَٓا اَنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالْاَقْرَب۪ينَ وَالْيَتَامٰى وَالْمَسَاك۪ينِ وَابْنِ السَّب۪يلِۜ وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَاِنَّ اللّٰهَ بِه۪ عَل۪يمٌ', 'Yes\'eluneke maza yunfikun, kul ma enfaktum min hayrin fe lil valideyni vel akrabine vel yetama vel mesakini vebnis sebil, ve ma tef\'alu min hayrin fe innallahe bihi alim.', 'Sana neyi infak[1] edeceklerini soruyorlar. De ki: \"Hayır[2] adına ne harcayabilirseniz; o,  anne ve babaya,  akrabalara,  yetimlere,  yoksullara ve yol oğlunadır.[3] Hayır adına her ne yaparsanız kuşkusuz Allah,  Her Şeyi Bilir.\"', 'يسلونك ماذا ينفقون قل ما انفقتم من خير فللولدين والاقربين واليتمي والمسكين وابن السبيل وما تفعلوا من خير فان الله به عليم'),
(223, 2, 216, 'كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْۚ وَعَسٰٓى اَنْ تَكْرَهُوا شَيْـٔاً وَهُوَ خَيْرٌ لَكُمْۚ وَعَسٰٓى اَنْ تُحِبُّوا شَيْـٔاً وَهُوَ شَرٌّ لَكُمْۜ وَاللّٰهُ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُونَ۟', 'Kutibe aleykumul kitalu ve huve kurhun lekum, ve asa en tekrehu şey\'en ve huve hayrun lekum, ve asa en tuhıbbu şey\'en ve huve şerrun lekum vallahu ya\'lemu ve entum la ta\'lemun.', 'Hoşunuza gitmese de savaş üzerinize yazıldı[1]. Olur ki,  hoşunuza gitmeyen bir şeyde sizin için hayır,  yine olur ki hoşunuza giden bir şeyde de sizin için şer vardır. Allah bilir,  siz bilmezsiniz.', 'كتب عليكم القتال وهو كره لكم وعسي ان تكرهوا شيا وهو خير لكم وعسي ان تحبوا شيا وهو شر لكم والله يعلم وانتم لا تعلمون'),
(224, 2, 217, 'يَسْـَٔلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ ف۪يهِۜ قُلْ قِتَالٌ ف۪يهِ كَب۪يرٌۜ وَصَدٌّ عَنْ سَب۪يلِ اللّٰهِ وَكُفْرٌ بِه۪ وَالْمَسْجِدِ الْحَرَامِ وَاِخْرَاجُ اَهْلِه۪ مِنْهُ اَكْبَرُ عِنْدَ اللّٰهِۚ   وَالْفِتْنَةُ اَكْبَرُ مِنَ الْقَتْلِۜ  وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ حَتّٰى يَرُدُّوكُمْ عَنْ د۪ينِكُمْ اِنِ اسْتَطَاعُواۜ وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ د۪ينِه۪ فَيَمُتْ وَهُوَ كَافِرٌ فَاُو۬لٰٓئِكَ حَبِطَتْ اَعْمَالُهُمْ فِي الدُّنْيَا وَالْاٰخِرَةِۚ وَاُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَـالِدُونَ', 'Yes\'eluneke aniş şehril harami kıtalin fih, kul kıtalun fihi kebir, ve saddun an sebilillahi ve kufrun bihi vel mescidil harami ve ihracu ehlihi minhu ekberu indallah, vel fitnetu ekberu minel katl, ve la yezalune yukatilunekum hatta yeruddukum an dinikum inistetau ve men yertedid minkum an dinihi fe yemut ve huve kafirun fe ulaike habitat a\'maluhum fid dunya vel ahireh, ve ulaike ashabun nar, hum fiha halidun.', 'Sana,  haram ayını[1] ve onda savaşmanın durumunu soruyorlar. De ki: \"O ayda savaşmak,  büyük (günahtır.) \" Ancak,  Allah\'ın yolundan alıkoymak,  onu ve Mescid-i Haram\'ı küfretmek[2] onun halkını oradan çıkarmak,  Allah katında daha büyük (günahtır.) Zira fitne[3],  öldürmekten daha kötüdür. Onlar,  eğer güç yetirebilseler,  sizi dininizden döndürünceye kadar,  sizinle savaşmaktan vazgeçmezler. Sizden kim,  dininden döner ve kafir olarak ölürse işte onların dünyada da ahirette de yaptıkları boşa gitmiş olur. İşte onlar,  ateşin ehlidir. Ve orada sürekli kalacaklardır.', 'يسلونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنة اكبر من القتل ولا يزالون يقتلونكم حتي يردوكم عن دينكم ان استطعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاوليك حبطت اعملهم في الدنيا والاخرة واوليك اصحب النار هم فيها خلدون'),
(225, 2, 218, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَالَّذ۪ينَ هَاجَرُوا وَجَاهَدُوا ف۪ي سَب۪يلِ اللّٰهِۙ اُو۬لٰٓئِكَ يَرْجُونَ رَحْمَتَ اللّٰهِۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'İnnellezine amenu vellezine haceru ve cahedu fi sebilillahi, ulaike yercune rahmetallah, vallahu gafurun rahim.', 'İman edenler,  hicret edenler ve Allah yolunda cihad[1] edenler; ancak bunlar,  Allah\'ın rahmetini umabilirler. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ان الذين امنوا والذين هاجروا وجهدوا في سبيل الله اوليك يرجون رحمت الله والله غفور رحيم'),
(226, 2, 219, 'يَسْـَٔلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِۜ قُلْ ف۪يهِمَٓا اِثْمٌ  كَب۪يرٌ وَمَنَافِـعُ لِلنَّاسِۘ وَاِثْمُهُمَٓا اَكْبَرُ مِنْ نَفْعِهِمَاۜ وَيَسْـَٔلُونَكَ مَاذَا يُنْفِقُونَۜ قُلِ الْعَفْوَۜ كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمُ الْاٰيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَۙ', 'Yes\'eluneke anil hamri vel meysir, kul fihima ismun kebirun ve menafiu lin nasi, ve ismuhuma ekberu min nef\'ihima ve yes\'eluneke maza yunfikun kulil afve, kezalike yubeyyinullahu lekumul ayati leallekum tetefekkerun.', 'Sana hamrın[1] ve şans oyunlarının[2] hükmünü soruyorlar. De ki: \"Her ikisinde de büyük günah vardır. İnsanlar için yararları[3] olsa da. Günahları yararlarından daha büyüktür.\" Sana neyi infak[4] edeceklerini soruyorlar. De ki: \"Afvı[5].\" Allah size ayetlerini böylece açıklamaktadır. Umulur ki düşünürsünüz.', 'يسلونك عن الخمر والميسر قل فيهما اثم كبير ومنفع للناس واثمهما اكبر من نفعهما ويسلونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايت لعلكم تتفكرون'),
(227, 2, 220, 'فِي الدُّنْيَا وَالْاٰخِرَةِۜ وَيَسْـَٔلُونَكَ عَنِ الْيَتَامٰىۜ قُلْ اِصْلَاحٌ لَهُمْ خَيْرٌۜ وَاِنْ تُخَالِطُوهُمْ فَاِخْوَانُكُمْۜ وَاللّٰهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِۜ وَلَوْ شَٓاءَ اللّٰهُ لَاَعْنَتَكُمْۜ اِنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ', 'Fid dunya vel ahirah ve yes\'eluneke anil yetama kul ıslahun lehum hayr ve in tuhalituhum fe ıhvanukum vallahu ya\'lemul mufside minel muslih ve lev şaallahu le a\'netekum innallahe azizun hakim.', 'Dünya ve ahiret hakkında... Bir de sana öksüzleri soruyorlar. De ki: \"Onların hayatlarını düzene sokmak,  sahipsiz bırakmaya göe hayırlı olandır.\" Eğer birlikte yaşayacak olursanız,  onlar sizin kardeşlerinizdir. Allah,  bozguncu olanla yapıcı olanı ayırt etmesini bilir. Eğer,  Allah dileseydi,  sizi zora koşardı. Zira Allah,  Çok Güçlü ve Her Şeye Egemen\'dir.', 'في الدنيا والاخرة ويسلونك عن اليتمي قل اصلاح لهم خير وان تخالطوهم فاخونكم والله يعلم المفسد من المصلح ولو شا الله لاعنتكم ان الله عزيز حكيم'),
(228, 2, 221, 'وَلَا تَنْكِحُوا الْمُشْرِكَاتِ حَتّٰى يُؤْمِنَّۜ وَلَاَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ اَعْجَبَتْكُمْۚ وَلَا تُنْكِحُوا الْمُشْرِك۪ينَ حَتّٰى يُؤْمِنُواۜ وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ اَعْجَبَكُمْۜ اُو۬لٰٓئِكَ يَدْعُونَ اِلَى النَّارِۚ وَاللّٰهُ يَدْعُٓوا اِلَى الْجَنَّةِ وَالْمَغْفِرَةِ بِاِذْنِه۪ۚ وَيُبَيِّنُ اٰيَاتِه۪ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ۟', 'Ve la tenkihul muşrikati hatta yu\'minn, ve le emetun mu\'minetun hayrun min muşriketin ve lev a\'cebetkum, ve la tunkihul muşrikine hatta yu\'minu ve le abdun mu\'minun hayrun min muşrikin ve lev a\'cebekum, ulaike yed\'une ilen nar, vallahu yed\'u ilel cenneti vel magfireti bi iznih, ve yubeyyinu ayatihi lin nasi leallehum yetezekkerun.', 'İman etmedikçe müşrik kadınlarla evlenmeyin. Beğenseniz de mü\'min bir emet[1],  müşrik bir kadına göre hayırlı olandır. İman etmedikçe,  müşrik erkeklerle evlenmeyin. Beğenseniz de abd[2] olan bir Mü\'min,  Müşrik bir erkeğe göre hayırlı olandır. Zira onlar ateşe çağırırlar. Allah ise izni ile[3] Cennet\'e ve bağışlanmaya çağırır. İnsanlara ayetlerini böyle açıklar. Umulur ki öğüt alıp düşünürler.', 'ولا تنكحوا المشركت حتي يومن ولامة مومنة خير من مشركة ولو اعجبتكم ولا تنكحوا المشركين حتي يومنوا ولعبد مومن خير من مشرك ولو اعجبكم اوليك يدعون الي النار والله يدعوا الي الجنة والمغفرة باذنه ويبين ايته للناس لعلهم يتذكرون'),
(229, 2, 222, 'وَيَسْـَٔلُونَكَ عَنِ الْمَح۪يضِۜ قُلْ هُوَ اَذًىۙ فَاعْتَزِلُوا النِّسَٓاءَ فِي الْمَح۪يضِۙ وَلَا تَقْرَبُوهُنَّ حَتّٰى يَطْهُرْنَۚ فَاِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ اَمَرَكُمُ اللّٰهُۜ اِنَّ اللّٰهَ يُحِبُّ التَّوَّاب۪ينَ وَيُحِبُّ الْمُتَطَهِّر۪ينَ', 'Ve yes\'eluneke anil mahid, kul huve ezen, fa\'tezilun nisae fil mahidi, ve la takrabuhunne hatta yathurn fe iza tetahherne fe\'tuhunne min haysu emerekumullah innallahe yuhıbbut tevvabine ve yuhibbul mutetahhirin.', 'Sana \"adet görme durumundan\" soruyorlar. De ki: \"O bir rahatsızlıktır.\" Kadınlar adet hali durumundayken onlardan uzak durun. Adet görme bitinceye kadar onlara yaklaşmayın. Adet hali bitince,  onlara Allah\'ın buyruğuna uygun şekilde yaklaşın. Kuşkusuz,  Allah,  tevbe edenleri sever. Ve temizlenenleri de sever.[1]', 'ويسلونك عن المحيض قل هو اذي فاعتزلوا النسا في المحيض ولا تقربوهن حتي يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوبين ويحب المتطهرين'),
(230, 2, 223, 'نِسَٓاؤُ۬كُمْ حَرْثٌ لَكُمْۖ فَأْتُوا حَرْثَكُمْ اَنّٰى شِئْتُمْۘ وَقَدِّمُوا لِاَنْفُسِكُمْۜ وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّكُمْ مُلَاقُوهُۜ وَبَشِّرِ الْمُؤْمِن۪ينَ', 'Nisaukum harsun lekum, fe\'tu harsekum enna şi\'tum ve kaddimu li enfusikum vettekullahe va\'lemu ennekum mulakuh, ve beşşiril mu\'minin.', 'Kadınlarınız sizin için ürün veren kimselerdir.[1] O halde,  ürün vereninize[2] istediğiniz gibi varın.[3] Kendiniz için önceden hazırlık yapın. Allah\'a karşı takvalı olun. Bilin ki muhakkak O\'na kavuşacaksınız. Ve müminleri müjdele.', 'نساوكم حرث لكم فاتوا حرثكم اني شيتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملقوه وبشر المومنين'),
(231, 2, 224, 'وَلَا تَجْعَلُوا اللّٰهَ عُرْضَةً لِاَيْمَانِكُمْ اَنْ تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِۜ  وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'Ve la tec\'alullahe urdaten li eymanikum en teberru ve tetteku ve tuslihu beynen nas, vallahu semiun alim.', 'Sakın,  Allah adına ettiğiniz yeminleri; iyilik yapmanıza,  takva sahibi olmanıza ve insanların arasını düzeltmenize engel kılmayın. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'ولا تجعلوا الله عرضة لايمنكم ان تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم'),
(232, 2, 225, 'لَا يُؤَاخِذُكُمُ اللّٰهُ بِاللَّغْوِ ف۪ٓي اَيْمَانِكُمْ وَلٰكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْۜ وَاللّٰهُ غَفُورٌ حَل۪يمٌ', 'La yuahızukumullahu bil lagvi fi eymanikum ve lakin yuahızukum bi ma kesebet kulubukum vallahu gafurun halim.', 'Allah,  kasıtsız olarak yaptığınız yeminlerden sizi sorumlu tutmaz. Ancak,  kasıtlı yaptığınız yeminlerden sizi sorumlu tutar. Allah; Çok Bağışlayan\'dır,  Çok Hoşgörülü\'dür.', 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما كسبت قلوبكم والله غفور حليم'),
(233, 2, 226, 'لِلَّذ۪ينَ يُؤْلُونَ مِنْ نِسَٓائِهِمْ تَرَبُّصُ اَرْبَعَةِ اَشْهُرٍۚ فَاِنْ فَٓاؤُ۫ فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Lillezine yu\'lune min nisaihim terabbusu erbaati eşhur, fe in fau fe innallahe gafurun rahim.', 'Kadınlarına yaklaşmamaya yemin eden kimseler için,  dört ay bekleme süresi vardır. Eğer bu yeminlerinden dönerlerse; doğrusu Allah,  Çok Bağışlayan\'dır,  Rahmeti Kesintisiz\'dir.', 'للذين يولون من نسايهم تربص اربعة اشهر فان فاو فان الله غفور رحيم'),
(234, 2, 227, 'وَاِنْ عَزَمُوا الطَّـلَاقَ فَاِنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌ', 'Ve in azemut talaka fe innallahe semiun alim.', 'Eğer boşamaya kesin karar verirlerse; kuşkusuz,  Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'وان عزموا الطلق فان الله سميع عليم'),
(235, 2, 228, 'وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِاَنْفُسِهِنَّ ثَلٰثَةَ قُرُٓوءٍۜ وَلَا يَحِلُّ لَهُنَّ اَنْ يَكْتُمْنَ مَا خَلَقَ اللّٰهُ ف۪ٓي اَرْحَامِهِنَّ اِنْ كُنَّ يُؤْمِنَّ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ وَبُعُولَتُهُنَّ اَحَقُّ بِرَدِّهِنَّ ف۪ي ذٰلِكَ اِنْ اَرَادُٓوا اِصْلَاحاًۜ وَلَهُنَّ مِثْلُ الَّذ۪ي عَلَيْهِنَّ بِالْمَعْرُوفِۖ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌۜ وَاللّٰهُ عَز۪يزٌ حَك۪يمٌ۟', 'Vel mutallakatu yeterabbasne bi enfusihinne selasete kuruin, ve la yahıllu lehunne en yektumne ma halakallahu fi erhamihinne in kunne yu\'minne billahi vel yevmil ahır, ve buuletuhunne ehakku bi reddihinne fi zalike in eradu ıslaha, ve lehunne mislullezi aleyhinne bil ma\'ruf, ve lir ricali aleyhinne dereceh, vallahu azizun hakim.', 'Boşanan kadınlar,  evlenmeksizin üç adet dönemi beklerler. Eğer Allah\'a ve ahiret gününe inanıyorlarsa,  Allah\'ın rahimlerinde yarattığını gizlemeleri onlara helal değildir. Eğer bu dönemde kocaları barışmak isterlerse,  onlarla yeniden evlenmede daha fazla hak sahibidirler. Erkeklerin,  kadınlar üzerindeki haklarına denk,  kadınların da erkekler üzerinde meşru hakları vardır. Ancak erkekler,  onlar[1] üzerinde[2] öncelik sahibidirler. Kuşkusuz,  Allah; Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'والمطلقت يتربصن بانفسهن ثلثة قرو ولا يحل لهن ان يكتمن ما خلق الله في ارحامهن ان كن يومن بالله واليوم الاخر وبعولتهن احق بردهن في ذلك ان ارادوا اصلحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجة والله عزيز حكيم'),
(236, 2, 229, 'اَلطَّـلَاقُ مَرَّتَانِۖ فَاِمْسَاكٌ بِمَعْرُوفٍ اَوْ تَسْر۪يحٌ بِاِحْسَانٍۜ وَلَا يَحِلُّ لَكُمْ اَنْ تَأْخُذُوا مِمَّٓا اٰتَيْتُمُوهُنَّ شَيْـٔاً اِلَّٓا اَنْ يَخَافَٓا اَلَّا يُق۪يمَا حُدُودَ اللّٰهِۜ فَاِنْ خِفْتُمْ اَلَّا يُق۪يمَا حُدُودَ اللّٰهِۙ فَلَا جُنَاحَ عَلَيْهِمَا ف۪يمَا افْتَدَتْ بِه۪ۜ تِلْكَ حُدُودُ اللّٰهِ فَلَا تَعْتَدُوهَاۚ وَمَنْ يَتَعَدَّ حُدُودَ اللّٰهِ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'Et talaku merratan, fe imsakun bi ma\'rufin ev tesrihun bi ihsan, ve la yahıllu lekum en te\'huzu mimma ateytumuhunne şey\'en illa en yehafa ella yukima hududallah, fe in hıftum ella yukima hududallahi, fe la cunaha aleyhima fi meftedet bih, tilke hududullahi fe la ta\'teduha, ve men yeteadde hududallahi fe ulaike humuz zalimun.', 'Boşanma iki defadır. Bundan sonra evliliğinizi ya meşru bir şekilde sürdürün ya da iyilikle ayrılın. Kadınlara verdiklerinizden bir şeyi; kadın ve erkek,  Allah\'ın koyduğu yasaları ihlal etmedikçe geri almanız size helal olmaz. Fakat Allah\'ın yasalarını çiğnemelerinden korkarsanız o zaman kadının boşanmak için fidye[1] vermesinde her iki taraf için de sakınca yoktur. Bunlar,  Allah\'ın koyduğu yasalardır. Sakın bunları çiğnemeyin. Kim Allah\'ın koyduğu yasaları çiğnerse işte onlar zalimlerin ta kendileridir.', 'الطلق مرتان فامساك بمعروف او تسريح باحسن ولا يحل لكم ان تاخذوا مما اتيتموهن شيا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فاوليك هم الظلمون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(237, 2, 230, 'فَاِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتّٰى تَنْكِحَ زَوْجاً غَيْرَهُۜ  فَاِنْ طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَٓا اَنْ يَتَرَاجَعَٓا اِنْ ظَـنَّٓا اَنْ يُق۪يمَا حُدُودَ اللّٰهِۜ وَتِلْكَ حُدُودُ اللّٰهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', 'Fe in tallakaha fe la tahıllu lehu min ba\'du hatta tenkiha zevcen gayrah, fe in tallakaha fe la cunaha aleyhima en yeteracea in zanna en yukima hududallah, ve tilke hududullahi yubeyyinuha li kavmin ya\'lemun.', 'Yine de karısını boşarsa,  karısı başka biriyle evlenmedikçe artık kendisine helal olmaz. Şayet ikinci koca da onu boşarsa ve her ikisi de Allah\'ın koyduğu yasalara uyacaklarını umut ederlerse,  birbirlerine dönmelerinde bir sakınca yoktur. Bunlar,  Allah\'ın,  anlayan bir topluma iyice açıkladığı yasalarıdır.', 'فان طلقها فلا تحل له من بعد حتي تنكح زوجا غيره فان طلقها فلا جناح عليهما ان يتراجعا ان ظنا ان يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون'),
(238, 2, 231, 'وَاِذَا طَلَّقْتُمُ النِّسَٓاءَ فَبَلَغْنَ اَجَلَهُنَّ فَاَمْسِكُوهُنَّ بِمَعْرُوفٍ اَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍۖ وَلَا تُمْسِكُوهُنَّ ضِرَاراً لِتَعْتَدُواۚ وَمَنْ يَفْعَلْ ذٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۜ وَلَا تَتَّخِذُٓوا اٰيَاتِ اللّٰهِ هُزُواًۘ وَاذْكُرُوا نِعْمَتَ اللّٰهِ عَلَيْكُمْ وَمَٓا اَنْزَلَ عَلَيْكُمْ مِنَ الْكِتَابِ وَالْحِكْمَةِ يَعِظُـكُمْ بِه۪ۜ وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ۟', 'Ve iza tallaktumun nisae fe belagne ecelehunne fe emsikuhunne bi ma\'rufin ev serrihuhunne bi ma\'ruf, ve la tumsikuhunne dıraran li ta\'tedu, ve men yef\'al zalike fe kad zaleme nefseh, ve la tettehızu ayatillahi huzuva, vezkuru ni\'metallahi aleykum ve ma enzele aleykum minel kitabi vel hikmeti yeızukum bih, vettekullahe va\'lemu ennallahe bi kulli şey\'in alim.', 'Boşadığınız kadınlar,  iddetlerini[1] tamamlayınca,  onları ya meşru bir şekilde tutun ya da meşru bir şekilde bırakın. Haklarını çiğneyip,  zarar verecek şekilde onları tutmayın. Kim böyle davranırsa,  kendisine zulmetmiş olur. Allah\'ın ayetlerini hafife almayın. Allah\'ın üzerinizdeki nimetini; size öğüt vermek için indirdiği Kitap\'ı ve Hikmet\'i[2] aklınızdan çıkarmayın. Allah\'a karşı gelmekten sakının. Ve bilin ki Allah,  Her Şeyi Gerçeğiyle Bilen\'dir.', 'واذا طلقتم النسا فبلغن اجلهن فامسكوهن بمعروف او سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا ايت الله هزوا واذكروا نعمت الله عليكم وما انزل عليكم من الكتب والحكمة يعظكم به واتقوا الله واعلموا ان الله بكل شي عليم'),
(239, 2, 232, 'وَاِذَا طَلَّقْتُمُ النِّسَٓاءَ فَبَلَغْنَ اَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ اَنْ يَنْكِحْنَ اَزْوَاجَهُنَّ اِذَا تَرَاضَوْا بَيْنَهُمْ بِالْمَعْرُوفِۜ ذٰلِكَ يُوعَظُ بِه۪ مَنْ كَانَ مِنْكُمْ يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ ذٰلِكُمْ اَزْكٰى لَكُمْ وَاَطْهَرُۜ وَاللّٰهُ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُونَ', 'Ve iza tallaktumun nisae fe belagne ecelehunne fe la ta\'duluhunne en yenkıhne ezvacehunne iza teradav beynehum bil ma\'ruf, zalike yuazu bihi men kane minkum yu\'minu billahi vel yevmil ahır, zalikum ezka lekum ve ather, vallahu ya\'lemu ve entum la ta\'lemun.', 'Boşadığınız kadınlar,  bekleme sürelerini tamamlayınca; aralarında meşru bir şekilde anlaştıkları takdirde,  onların eşleriyle[1] evlenmelerine engel olmayın. Bu,  içinizden Allah\'a ve Ahiret Günü\'ne iman edenlere yapılan bir öğüttür. Bu sizin için daha iffetli,  daha temiz bir yoldur. Allah bilir,  siz bilmezsiniz.', 'واذا طلقتم النسا فبلغن اجلهن فلا تعضلوهن ان ينكحن ازوجهن اذا ترضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يومن بالله واليوم الاخر ذلكم ازكي لكم واطهر والله يعلم وانتم لا تعلمون'),
(240, 2, 233, 'وَالْوَالِدَاتُ يُرْضِعْنَ اَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ اَرَادَ اَنْ يُـتِمَّ الرَّضَاعَةَۜ وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِۜ لَا تُكَلَّفُ نَفْسٌ اِلَّا وُسْعَهَاۚ لَا تُضَٓارَّ وَالِدَةٌ بِوَلَدِهَا وَلَا مَوْلُودٌ لَهُ بِوَلَدِه۪ وَعَلَى الْوَارِثِ مِثْلُ ذٰلِكَۚ فَاِنْ اَرَادَا فِصَالاً عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَاۜ وَاِنْ اَرَدْتُمْ اَنْ تَسْتَرْضِعُٓوا اَوْلَادَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ اِذَا سَلَّمْتُمْ مَٓا اٰتَيْتُمْ بِالْمَعْرُوفِۜ وَاتَّقُوا اللّٰهَ وَاعْلَمُٓوا اَنَّ اللّٰهَ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Vel validatu yurdı\'ne evladehunne havleyni kamileyni li men erade en yutimmer radaah, ve alel mevludi lehu rızkuhunne ve kisvetuhunne bil ma\'ruf, la tukellefu nefsun illa vus\'aha, la tudarra validetun bi velediha ve la mevludun lehu bi veledihi ve alel varisi mislu zalik, fe in erada fısalen an teradın min huma ve teşavurin fe la cunaha aleyhima ve in eradtum en testerdıu evladekum fe la cunaha aleykum iza sellemtum ma ateytum bil ma\'ruf, vettekullahe va\'lemu ennellahe bi ma ta\'melune basir.', 'Emzirme süresini tamamlamak isteyenler için; annelerin çocuklarını emzirme süresi tam iki yıldır. Onların yiyeceklerini ve giyeceklerini meşru bir şekilde temin etmek babaya aittir. Hiç kimse,  gücünün yeteceğinden daha fazlasıyla sorumlu değildir. Hiçbir anne,  çocuğu nedeniyle sıkıntıya sokulmasın; hiçbir baba,  çocuğu nedeniyle sıkıntıya sokulmasın. Ve mirasçı da aynı şekilde sorumludur. Eğer anne ve baba anlaşarak kendi rızaları ile çocuklarını sütten kesmek isterlerse,  ikisi için de bir sakınca yoktur. Eğer çocuklarınızı emzirtmek isterseniz,  meşru bir ücret ödediğiniz takdirde emzirtmenizde bir sakınca yoktur. Allah\'a karşı takvalı olun. Ve bilin ki Allah,  yaptığınız her şeyi görür.', 'والولدت يرضعن اولدهن حولين كاملين لمن اراد ان يتم الرضاعة وعلي المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس الا وسعها لا تضار ولدة بولدها ولا مولود له بولده وعلي الوارث مثل ذلك فان ارادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وان اردتم ان تسترضعوا اولدكم فلا جناح عليكم اذا سلمتم ما اتيتم بالمعروف واتقوا الله واعلموا ان الله بما تعملون بصير'),
(241, 2, 234, 'وَالَّذ۪ينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ اَزْوَاجاً يَتَرَبَّصْنَ بِاَنْفُسِهِنَّ اَرْبَعَةَ اَشْهُرٍ وَعَشْراًۚ فَاِذَا بَلَغْنَ اَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ ف۪يمَا فَعَلْنَ ف۪ٓي اَنْفُسِهِنَّ بِالْمَعْرُوفِۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'Vellezine yuteveffevne minkum ve yezerune ezvacen yeterabbasne bi enfusihinne erbeate eşhurin ve aşra, fe iza belagne ecelehunne fe la cunahe aleykum fi ma fealne fi enfusihinne bil ma\'ruf, vallahu bi ma ta\'melune habir.', 'Sizden ölenlerin geride bıraktıkları eşleri,  kendi kendilerine dört ay on gün beklerler. Bu süreyi tamamlayınca,  kendi haklarında verecekleri meşru kararlarda sizin için bir sorumluluk yoktur. Allah yaptığınız her şeyden haberdardır.', 'والذين يتوفون منكم ويذرون ازوجا يتربصن بانفسهن اربعة اشهر وعشرا فاذا بلغن اجلهن فلا جناح عليكم فيما فعلن في انفسهن بالمعروف والله بما تعملون خبير'),
(242, 2, 235, 'وَلَا جُنَاحَ عَلَيْكُمْ ف۪يمَا عَرَّضْتُمْ بِه۪ مِنْ خِطْبَةِ النِّسَٓاءِ اَوْ اَكْنَنْتُمْ ف۪ٓي اَنْفُسِكُمْۜ عَلِمَ اللّٰهُ اَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلٰكِنْ لَا تُوَاعِدُوهُنَّ سِراًّ اِلَّٓا اَنْ تَقُولُوا قَوْلاً مَعْرُوفاًۜ وَلَا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتّٰى يَبْلُغَ الْكِتَابُ اَجَلَهُۜ وَاعْلَمُٓوا اَنَّ اللّٰهَ يَعْلَمُ مَا ف۪ٓي اَنْفُسِكُمْ فَاحْذَرُوهُۚ وَاعْلَمُٓوا اَنَّ اللّٰهَ غَفُورٌ حَل۪يمٌ۟', 'Ve la cunahe aleykum fima arradtum bihi min hitbetin nisai ev eknentum fi enfusikum, alimallahu ennekum se tezkurunehunne ve lakin la tuvaıduhunne sirran illa en tekulu kavlen ma\'rufa, ve la ta\'zimu ukdeten nikahı hatta yeblugal kitabu eceleh, va\'lemu ennallahe ya\'lemu ma fi enfusikum fahzeruh, va\'lemu ennallahe gafurun halim.', 'Bekleme süresini tamamlamamış kadınlara evlenme isteğinizi sezdirmeniz veya bunu içinizden geçirmenizde bir sakınca yoktur. Allah,  sizin onlara karşı olan duygularınızı bilir. Ancak onlara meşru olmayan bir istekte bulunmayın. Kitaptaki emredilen bekleme süresi sona ermeden onlarla nikah akdi yapmaya kalkışmayın. Bilin ki Allah içinizden ne geçirdiğinizi bilir,  O\'na karşı gelmekten sakının. Bilin ki Allah,  Çok Affedici,  Çok Hoşgörülüdür.', 'ولا جناح عليكم فيما عرضتم به من خطبة النسا او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقدة النكاح حتي يبلغ الكتب اجله واعلموا ان الله يعلم ما في انفسكم فاحذروه واعلموا ان الله غفور حليم'),
(243, 2, 236, 'لَا جُنَاحَ عَلَيْكُمْ اِنْ طَلَّقْتُمُ النِّسَٓاءَ مَا لَمْ تَمَسُّوهُنَّ اَوْ تَفْرِضُوا لَهُنَّ فَر۪يضَةًۚ وَمَتِّعُوهُنَّۚ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُۚ مَتَـاعاً بِالْمَعْرُوفِۚ حَقاًّ عَلَى الْمُحْسِن۪ينَ', 'La cunaha aleykum in tallaktumun nisae ma lem temessuhunne ev tefridu lehunne faridah ve mettiuhunne alel musiı kaderuhu ve alel muktiri kaderuh metaan bil ma\'ruf, hakkan alel muhsinin.', 'Dokunmadığınız veya onlar için farz kılınanı[1] henüz farz kılmadığınız[2] kadınları boşamanızda bir sorumluluk yoktur. Ancak onları faydalandırın. Maddi durumu iyi olan kendi imkanına göre,  iyi olmayan da kendi imkanına göre onları meşru bir şekilde yararlandırsın. Bu,  iyi kimselerin üzerinde bir haktır.', 'لا جناح عليكم ان طلقتم النسا ما لم تمسوهن او تفرضوا لهن فريضة ومتعوهن علي الموسع قدره وعلي المقتر قدره متعا بالمعروف حقا علي المحسنين'),
(244, 2, 237, 'وَاِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ اَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَر۪يضَةً فَنِصْفُ مَا فَرَضْتُمْ اِلَّٓا اَنْ يَعْفُونَ اَوْ يَعْفُوَا الَّذ۪ي بِيَدِه۪ عُقْدَةُ النِّكَاحِۜ وَاَنْ تَعْفُٓوا اَقْرَبُ لِلتَّقْوٰىۜ وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْۜ اِنَّ اللّٰهَ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Ve in tallaktumuhunne min kabli en temessuhunne ve kadfaradtum lehunne faridaten fe nısfu ma faradtum illaen ya\'fune ev ya\'fuvellezi bi yedihi ukdetun nikah, ve en ta\'fu akrabu lit takva ve la tensevul fadla beynekum innallahe bi ma ta\'melune basir.', 'Farz kılıp ta[1] kendilerine dokunmadığınız kadınları boşarsanız,  farz kılınanın[2] yarısı onlarındır. Ancak kendisinin veya nikah akdini elinde tutanın,  bundan vazgeçmesi hariç. Bununla birlikte,  mehirin tamamının verilmesi takvaya daha uygundur. Aranızda birbirinize iyilik yapmayı ihmal etmeyin. Kuşkusuz,  Allah,  yaptığınız her şeyi görür.', 'وان طلقتموهن من قبل ان تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم الا ان يعفون او يعفوا الذي بيده عقدة النكاح وان تعفوا اقرب للتقوي ولا تنسوا الفضل بينكم ان الله بما تعملون بصير'),
(245, 2, 238, 'حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلٰوةِ الْوُسْطٰى وَقُومُوا لِلّٰهِ قَانِت۪ينَ', 'Hafizu alas salavati ves salatil vusta ve kumu lillahi kanitin.', 'Salatları[1] ve salatı vustayı[2] koruyucu olun. Allah için içtenlikli olmaya özen gösterin.', 'حفظوا علي الصلوت والصلوة الوسطي وقوموا لله قنتين'),
(246, 2, 239, 'فَاِنْ خِفْتُمْ فَرِجَـالاً اَوْ رُكْبَـاناًۚ فَاِذَٓا اَمِنْتُمْ فَاذْكُرُوا اللّٰهَ كَمَا عَلَّمَكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَ', 'Fe in hıftum fe ricalen ev rukbana, fe iza emintum, fezkurullahe kema allemekum ma lem tekunu ta\'lemun.', 'Eğer korkarsanız[1] yaya veya binek üzerinde bulunduğunuzda da güvenlikte olduğunuz zamanda da bilmediğiniz şeyleri size öğrettiği şekilde Allah\'ı anın.', 'فان خفتم فرجالا او ركبانا فاذا امنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون'),
(247, 2, 240, 'وَالَّذ۪ينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ اَزْوَاجاًۚ وَصِيَّةً لِاَزْوَاجِهِمْ مَتَاعاً اِلَى الْحَوْلِ غَيْرَ اِخْرَاجٍۚ فَاِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ ف۪ي مَا فَعَلْنَ ف۪ٓي اَنْفُسِهِنَّ مِنْ مَعْرُوفٍۜ وَاللّٰهُ عَز۪يزٌ حَك۪يمٌ', 'Vellezine yuteveffevne minkum ve yezerune ezvaca, vasıyyeten li ezvacihim metaan ilel havli gayre ıhrac, fe in harecne fe la cunaha aleykum fi ma fealne fi enfusihinne min ma\'ruf, vallahu azizun hakim.', 'Sizden,  ölüp de geride eşler bırakacak olan erkekler; eşlerinin evlerinden çıkarılmaksızın bir yıla kadar geçimlerinin teminini vasiyet etsinler. Eğer,  kendileri çıkmak isterlerse,  kendi haklarında uygun olanı yapmalarında sizin için bir sorumluluk yoktur. Allah,  Mutlak Üstün Olan\'dır ve En Doğru Hüküm Veren\'dir.', 'والذين يتوفون منكم ويذرون ازوجا وصية لازوجهم متعا الي الحول غير اخراج فان خرجن فلا جناح عليكم في ما فعلن في انفسهن من معروف والله عزيز حكيم'),
(248, 2, 241, 'وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِۜ حَقاًّ عَلَى الْمُتَّق۪ينَ', 'Ve lil mutallakati metaun bil ma\'ruf hakkan alel muttekin.', 'Boşanmış kadınların geçimlerini meşru bir şekilde sağlamak,  takva sahipleri için bir yükümlülüktür.', 'وللمطلقت متع بالمعروف حقا علي المتقين'),
(249, 2, 242, 'كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمْ اٰيَاتِه۪ لَعَلَّكُمْ تَعْقِلُونَ۟', 'Kezalike yubeyyinullahu lekum ayatihi leallekum ta\'kılun.', 'İşte Allah,  size ayetlerini böyle açıklar. Umulur ki aklınızı kullanırsınız.', 'كذلك يبين الله لكم ايته لعلكم تعقلون'),
(250, 2, 243, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ خَرَجُوا مِنْ دِيَارِهِمْ وَهُمْ اُلُوفٌ حَذَرَ الْمَوْتِۖ فَقَالَ لَهُمُ اللّٰهُ مُوتُوا ثُمَّ اَحْيَاهُمْۜ اِنَّ اللّٰهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', 'E lem tera ilellezine haracu min diyarihim ve hum ulufun hazaral mevti, fe kale lehumullahu mutu summe ahyahum innallahe le zu fadlin alen nasi ve lakinne ekseren nasi la yeşkurun.', 'Binlerce kişi oldukları halde,  ölüm korkusuyla yurtlarından çıkanları görmedin mi? Allah onlara \"Ölün.\" dedi; sonra,  onlara hayat verdi.[1] Allah,  insanlara karşı lütuf sahibidir. Ancak insanların çoğu şükretmezler.', 'الم تر الي الذين خرجوا من ديرهم وهم الوف حذر الموت فقال لهم الله موتوا ثم احيهم ان الله لذو فضل علي الناس ولكن اكثر الناس لا يشكرون'),
(251, 2, 244, 'وَقَاتِلُوا ف۪ي سَب۪يلِ اللّٰهِ وَاعْلَمُٓوا اَنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌ', 'Ve katilu fi sebilillahi va\'lemu ennallahe semiun alim.', 'O halde Allah yolunda savaşın. Ve bilin ki: Allah,  Her Şeyi İşiten ve Her Şeyi Bilen\'dir.', 'وقتلوا في سبيل الله واعلموا ان الله سميع عليم'),
(252, 2, 245, 'مَنْ ذَا الَّذ۪ي يُقْرِضُ اللّٰهَ قَرْضاً حَسَناً فَيُضَاعِفَهُ لَهُٓ اَضْعَافاً كَـث۪يرَةًۜ وَاللّٰهُ يَقْبِضُ وَيَبْصُۣطُۖ وَاِلَيْهِ تُرْجَعُونَ', 'Menzellezi yukridullahe kardan hasenen fe yudaifehu lehu ed\'afen kesirah, vallahu yakbidu ve yebsut ve ileyhi turceun.', 'Kim Allah\'a,  Allah\'ın karşılığını kat kat vereceği,  karşılıksız bir borç vermek[1] ister? Daraltan da genişleten de Allah\'tır. Ve dönüşünüz yalnızca O\'nadır.', 'من ذا الذي يقرض الله قرضا حسنا فيضعفه له اضعافا كثيرة والله يقبض ويبصط واليه ترجعون'),
(253, 2, 246, 'اَلَمْ تَرَ اِلَى الْمَلَأِ مِنْ بَن۪ٓي اِسْرَٓائ۪لَ مِنْ بَعْدِ مُوسٰىۢ اِذْ قَالُوا لِنَبِيٍّ لَهُمُ ابْعَثْ لَنَا مَلِكاً نُقَاتِلْ ف۪ي سَب۪يلِ اللّٰهِۜ قَالَ هَلْ عَسَيْتُمْ اِنْ كُتِبَ عَلَيْكُمُ الْقِتَالُ اَلَّا تُقَاتِلُواۜ قَالُوا وَمَا لَـنَٓا اَلَّا نُقَاتِلَ ف۪ي سَب۪يلِ اللّٰهِ وَقَدْ اُخْرِجْنَا مِنْ دِيَارِنَا وَاَبْنَٓائِنَاۜ فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ تَوَلَّوْا اِلَّا قَل۪يلاً مِنْهُمْۜ وَاللّٰهُ عَل۪يمٌ بِالظَّالِم۪ينَ', 'E lem tera ilel melei min beni israile min ba\'di musa, iz kalu li nebiyyin lehumub\'as lena meliken nukatil fi sebilillah, kale hel aseytum in kutibe aleykumul kıtalu ella tukatil, kalu ve ma lena ella nukatile fi sebilillahi ve kad uhricna min diyarina ve ebnaina fe lemma kutibe aleyhimul kıtalu tevellev illa kalilen minhum vallahu alimun biz zalimin.', 'Musa\'dan sonra İsrailoğulları\'nın meleleri[1],  nebilerine: \"Bize bir komutan tayin et de Allah yolunda savaşalım\" demişlerdi. O: \"Ya savaş üzerinize yazılır[2] da savaşmazsanız.\" dedi. Onlar: \"Yurdumuzdan çıkarılıp çocuklarımızdan koparılmışken,  niçin Allah yolunda savaşmayalım?\" dediler. Fakat üzerlerine savaş yazılınca[3] da içlerinden pek azı hariç,  yüz çevirdiler. Allah,  zalimleri çok iyi bilir.', 'الم تر الي الملا من بني اسريل من بعد موسي اذ قالوا لنبي لهم ابعث لنا ملكا نقتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقتلوا قالوا وما لنا الا نقتل في سبيل الله وقد اخرجنا من ديرنا وابناينا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظلمين'),
(254, 2, 247, 'وَقَالَ لَهُمْ نَبِيُّهُمْ اِنَّ اللّٰهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكاًۜ قَالُٓوا اَنّٰى يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا وَنَحْنُ اَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمَالِۜ قَالَ اِنَّ اللّٰهَ اصْطَفٰيهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِۜ وَاللّٰهُ يُؤْت۪ي مُلْكَهُ مَنْ يَشَٓاءُۜ وَاللّٰهُ وَاسِعٌ عَل۪يمٌ', 'Ve kale lehum nebiyyuhum innallahe kad bease lekum talutemelika, kalu enna yekunu lehul mulku aleyna ve nahnu ehakku bil mulki minhu ve lem yu\'te seaten minel mal, kale innallahestafahu aleykum ve zadehu bestaten fil ilmi vel cism, vallahu yu\'ti mulkehu men yeşau, vallahu vasiun alim.', 'Nebileri onlara: \"Allah size Talut\'u komutan olarak tayin etti.\" dedi. Onlar: \"Biz komutanlığa ondan daha layık olduğumuz ve o fazla bir servete de sahip değilken,  bize nasıl komutan olabilir?\" dediler. O da: \"Allah,  onu üzerinize seçti,  ona geniş bir bilgi ve üstün bir güç verdi.\" dedi. Zira Allah,  gücü hak edene verir. Allah,  Her Şeyi Kuşatan ve Her Şeyi Bilen\'dir.', 'وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا اني يكون له الملك علينا ونحن احق بالملك منه ولم يوت سعة من المال قال ان الله اصطفيه عليكم وزاده بسطة في العلم والجسم والله يوتي ملكه من يشا والله وسع عليم'),
(255, 2, 248, 'وَقَالَ لَهُمْ نَبِيُّهُمْ اِنَّ اٰيَةَ مُلْكِه۪ٓ اَنْ يَأْتِيَكُمُ التَّابُوتُ ف۪يهِ سَك۪ينَةٌ مِنْ رَبِّكُمْ وَبَقِيَّةٌ مِمَّا تَرَكَ اٰلُ مُوسٰى وَاٰلُ هٰرُونَ تَحْمِلُهُ الْمَلٰٓئِكَةُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لَكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَ۟', 'Ve kale lehum nebiyyuhum inne ayete mulkihi en ye\'tiyekumut tabutu fihi sekinetun min rabbikum ve bakiyyetun mimma terake alu musa ve alu harune tahmiluhul melaikeh, inne fi zalike le ayeten lekum in kuntum mu\'minin.', 'Nebileri onlara: \"Onun komutanlık kanıtı,  içinde Rabb\'inizden bir sekine[1] ve Musa ile Harun soyundan bakiye kalanların bulunduğu ve meleklerin[1] taşıdığı,  yüklendiği bir sandığın size gelmesidir. Eğer inanmış kimselerseniz,  kuşkusuz bunda sizin için kesin bir ayet[3] vardır.\" dedi.', 'وقال لهم نبيهم ان اية ملكه ان ياتيكم التابوت فيه سكينة من ربكم وبقية مما ترك ال موسي وال هرون تحمله المليكة ان في ذلك لاية لكم ان كنتم مومنين'),
(256, 2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِۙ قَالَ اِنَّ اللّٰهَ مُبْتَل۪يكُمْ بِنَهَرٍۚ فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنّ۪يۚ وَمَنْ لَمْ يَطْعَمْهُ فَاِنَّهُ مِنّ۪ٓي اِلَّا مَنِ اغْتَرَفَ غُرْفَةً بِيَدِه۪ۚ فَشَرِبُوا مِنْهُ اِلَّا قَل۪يلاً مِنْهُمْۜ فَلَمَّا جَاوَزَهُ هُوَ وَالَّذ۪ينَ اٰمَنُوا مَعَهُۙ قَالُوا لَا طَاقَةَ لَنَا الْيَوْمَ بِجَالُوتَ وَجُنُودِه۪ۜ قَالَ الَّذ۪ينَ يَظُنُّونَ اَنَّهُمْ مُلَاقُوا اللّٰهِۙ  كَمْ مِنْ فِئَةٍ قَل۪يلَةٍ غَلَبَتْ فِئَةً كَث۪يرَةً بِاِذْنِ اللّٰهِۜ وَاللّٰهُ مَعَ الصَّابِر۪ينَ', 'Fe lemma fesale talutu bil cunudi, kale innallahe mubtelikum bi neher, fe men şeribe minhu fe leyse minni, ve men lem yat\'amhu fe innehu minni illa menigterafe gurfeten bi yedih, fe şeribu minhu illa kalilen minhum fe lemma cavezehu huve vellezine amenu meahu, kalu la takate lenal yevme bi calute ve cunudih, kalellezine yezunnune ennehum mulakullahi, kem min fietin kaliletin galebet fieten kesiraten bi iznillah, vallahu meas sabirin.', 'Talut,  askerleriyle yola çıkınca onlara: \"Allah,  sizi bir nehirle imtihan edecek. Kim ondan içerse benden değildir. Bir avuç kadar tatmakla yetinirse o bendendir.\" dedi. Çok azı hariç,  ondan doyasıya içtiler. O ve yanında yer alan inananlar,  nehri geçince: \"Bugün Calut\'a ve askerlerine karşı savaşacak gücümüz kalmadı.\" dediler. Allah\'a kavuşacaklarına inananlar[1] ise: \"Nice az topluluklar,  Allah\'ın izni ile[2] nice çok topluluklara galip gelmiştir. Allah,  sabredenlerle beraberdir.\" dediler.', 'فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفة بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين امنوا معه قالوا لا طاقة لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملقوا الله كم من فية قليلة غلبت فية كثيرة باذن الله والله مع الصبرين'),
(257, 2, 250, 'وَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِه۪ قَالُوا رَبَّنَٓا اَفْرِغْ عَلَيْنَا صَبْراً وَثَبِّتْ اَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِر۪ينَۜ', 'Ve lemma berazu li calute ve cunudihi kalu rabbena efrig aleyna sabren ve sebbit ekdamena vensurna alel kavmil kafirin.', 'Onlar,  Calut ve askerleriyle karşı karşıya geldikleri zaman: \"Ey Rabbimiz! Üzerimize sabır yağdır ve ayaklarımızı sabit kıl,  kafir kavme karşı bize yardım et.\" dediler.', 'ولما برزوا لجالوت وجنوده قالوا ربنا افرغ علينا صبرا وثبت اقدامنا وانصرنا علي القوم الكفرين'),
(258, 2, 251, 'فَهَزَمُوهُمْ بِاِذْنِ اللّٰهِۙ وَقَتَلَ دَاوُ۫دُ جَالُوتَ وَاٰتٰيهُ اللّٰهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشَٓاءُۜ وَلَوْلَا دَفْعُ اللّٰهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَفَسَدَتِ الْاَرْضُ وَلٰكِنَّ اللّٰهَ ذُوفَضْلٍ عَلَى الْعَالَم۪ينَ', 'Fe hezemuhum bi iznillahi, ve katele davudu calute ve atahullahul mulke vel hikmete ve allemehu mimma yeşau, ve lev la def\'ullahin nase, ba\'dahum bi ba\'din le fesedetil ardu ve lakinnallahe zu fadlin alel alemin.', 'Allah\'ın izniyle[1] onları yenilgiye uğrattılar. Davud,  Calut\'u öldürdü. Allah,  O\'na güç ve hikmet[2] verdi. O\'na dilediğinden öğretti. Eğer,  Allah,  insanların bir kısmını bir kısmıyla savmasaydı,  yeryüzü bozguna uğrardı. Ancak,  Allah,  bütün alemlere karşı sınırsız lütuf sahibidir.', 'فهزموهم باذن الله وقتل داود جالوت واتيه الله الملك والحكمة وعلمه مما يشا ولولا دفع الله الناس بعضهم ببعض لفسدت الارض ولكن الله ذو فضل علي العلمين'),
(259, 2, 252, 'تِلْكَ اٰيَاتُ اللّٰهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّۜ وَاِنَّكَ لَمِنَ الْمُرْسَل۪ينَ', 'Tilke ayatullahi netluha aleyke bil hakk, ve inneke le minel murselin.', 'İşte bunlar Allah\'ın ayetleridir. Biz onları sana gerçek olarak okuyoruz.[1] Kuşkusuz sen gönderilenlerdensin.[2]', 'تلك ايت الله نتلوها عليك بالحق وانك لمن المرسلين'),
(260, 2, 253, 'تِلْكَ الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلٰى بَعْضٍۢ مِنْهُمْ مَنْ كَلَّمَ اللّٰهُ وَرَفَعَ بَعْضَهُمْ دَرَجَاتٍۜ وَاٰتَيْنَا ع۪يسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَاَيَّدْنَاهُ بِرُوحِ الْقُدُسِۜ وَلَوْ شَٓاءَ اللّٰهُ مَا اقْتَتَلَ الَّذ۪ينَ مِنْ بَعْدِهِمْ مِنْ بَعْدِ مَا جَٓاءَتْهُمُ الْبَيِّنَاتُ وَلٰكِنِ اخْتَلَفُوا فَمِنْهُمْ مَنْ اٰمَنَ وَمِنْهُمْ مَنْ كَفَرَۜ وَلَوْ شَٓاءَ اللّٰهُ مَا اقْتَتَلُوا وَلٰكِنَّ اللّٰهَ يَفْعَلُ مَا يُر۪يدُ۟', 'Tilker rusulu faddalna ba\'dahum ala ba\'d, minhum men kellemallahu ve rafea ba\'dahum derecat, ve ateyna isabne meryemel beyyinati ve eyyednahu bi ruhıl kudus, ve lev şaallahu maktetelellezine min ba\'dihim min ba\'di ma caethumul beyyinatu ve lakinihtelefu fe minhum men amene ve minhum men kefer, ve lev şaallahu maktetelu ve lakinnallahe yef\'alu ma yurid.', 'İşte o elçiler ki her birine farklı lütuflarda bulunduk. Allah,  onların kimisi ile konuşmuş,  kimisinin de derecelerini yükseltmiştir. Meryem oğlu İsa\'ya beyyineler[1] verdik ve onu Kudus\'un Ruhu[2] ile destekledik. Allah dileseydi,  onlardan sonra gelenler,  bunca açık kanıttan sonra birbirleriyle savaşmazlardı. Yalnız onlar ihtilafa düştüler; onlardan kimisi iman etti,  yine onlardan kimisi de inkar etti. Eğer Allah dileseydi birbirleriyle savaşmazlardı. Ancak,  Allah neyi dilerse onu yapar.', 'تلك الرسل فضلنا بعضهم علي بعض منهم من كلم الله ورفع بعضهم درجت واتينا عيسي ابن مريم البينت وايدنه بروح القدس ولو شا الله ما اقتتل الذين من بعدهم من بعد ما جاتهم البينت ولكن اختلفوا فمنهم من امن ومنهم من كفر ولو شا الله ما اقتتلوا ولكن الله يفعل ما يريد'),
(261, 2, 254, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَنْفِقُوا مِمَّا رَزَقْنَاكُمْ مِنْ قَبْلِ اَنْ يَأْتِيَ يَوْمٌ لَا بَيْعٌ ف۪يهِ وَلَا خُلَّةٌ وَلَا شَفَاعَةٌۜ وَالْكَافِرُونَ هُمُ الظَّالِمُونَ', 'Ya eyyuhellezine amenu enfiku mimma razaknakum min kabli en ye\'tiye yevmun la bey\'un fihi ve la hulletun ve la şefaah, vel kafirune humuz zalimun.', 'Ey iman edenler! Size rızık olarak verdiklerimizden infak[1] edin; İçinde hiçbir alışverişin,  hiçbir dostluğun ve hiçbir şefaatin olmadığı gün gelmeden önce. Gerçeği yalanlayan nankörler,  zalimlerin ta kendileridir.', 'يايها الذين امنوا انفقوا مما رزقنكم من قبل ان ياتي يوم لا بيع فيه ولا خلة ولا شفعة والكفرون هم الظلمون'),
(262, 2, 255, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۚ اَلْحَيُّ الْقَيُّومُۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌۜ لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ مَنْ ذَا الَّذ۪ي يَشْفَعُ عِنْدَهُٓ اِلَّا بِاِذْنِه۪ۜ يَعْلَمُ مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْۚ وَلَا يُح۪يطُونَ بِشَيْءٍ مِنْ عِلْمِه۪ٓ اِلَّا بِمَا شَٓاءَۚ وَسِعَ كُرْسِيُّهُ السَّمٰوَاتِ وَالْاَرْضَۚ وَلَا يَؤُ۫دُهُ حِفْظُهُمَاۚ وَهُوَ الْعَلِيُّ الْعَظ۪يمُ', 'Allahu la ilahe illa huvel hayyul kayyum, la te\'huzuhu sinetun ve la nevm, lehu ma fis semavati ve ma fil ard, menzellezi yeşfeu indehu illa bi iznih ya\'lemu ma beyne eydihim ve ma halfehum, ve la yuhitune bi şey\'in min ilmihi illa bi ma şae, vesia kursiyyuhus semavati vel ard, ve la yeuduhu hıfzuhuma ve huvel aliyyul azim.', 'Allah: O\'ndan başka ilah yoktur. O,  sürekli diridir,  koruyup gözetendir. O\'nda ne bir dalgınlık olur ne de O\'nu bir uyku tutar. Göklerde ve yerde olan her şey O\'nundur. İzni olmaksızın[1] O\'nun katında şefaatte bulunabilecek kimmiş? Onların[2] önlerinde ve arkalarında[3] olan her şeyi bilir. Onlar,  O\'nun ilminden ancak dilediği kadarını kavrayabilirler. O\'nun egemenliği yeri ve göğü kuşatmıştır. Bunları korumak O\'na ağır gelmez. O,  Çok Yüce ve Çok Güçlü\'dür.', 'الله لا اله الا هو الحي القيوم لا تاخذه سنة ولا نوم له ما في السموت وما في الارض من ذا الذي يشفع عنده الا باذنه يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشي من علمه الا بما شا وسع كرسيه السموت والارض ولا يوده حفظهما وهو العلي العظيم'),
(263, 2, 256, 'لَٓا اِكْرَاهَ فِي الدّ۪ينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّۚ فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللّٰهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقٰىۗ لَا انْفِصَامَ لَهَاۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'La ikrahe fid dini kad tebeyyener ruşdu minel gayy, fe men yekfur bit taguti ve yu\'min billahi fe kadistemseke bil urvetil vuska, lenfisame leha, vallahu semiun alim.', 'Dinde zorlama yoktur. Artık,  doğru olan yanlış olandan kesin olarak ayrılmıştır. Kim tağutu[1] reddedip,  Allah\'a inanırsa,  kuşkusuz ki kopması mümkün olmayan en sağlam kulpa tutunmuş olur. Allah,  Her Şeyi İşiten ve Her Şeyi Bilen\'dir.', 'لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطغوت ويومن باالله فقد استمسك بالعروة الوثقي لا انفصام لها والله سميع عليم'),
(264, 2, 257, 'اَللّٰهُ وَلِيُّ الَّذ۪ينَ اٰمَنُواۙ يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ اِلَى النُّورِۜ وَالَّذ۪ينَ كَفَرُٓوا اَوْلِيَٓاؤُ۬هُمُ الطَّاغُوتُۙ يُخْرِجُونَهُمْ مِنَ النُّورِ اِلَى الظُّلُمَاتِۜ اُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ۟', 'Allahu veliyyullezine amenu, yuhricuhum minez zulumati ilen nur, vellezine keferu evliyauhumut tagutu yuhricunehum minen nuri ilaz zulumat, ulaike ashabun nar, hum fiha halidun.', 'Allah,  iman edenlerin velisidir.[1] Onları karanlıklardan aydınlığa çıkarır. Küfredenlerin velileri ise tağutlardır[2]; onları aydınlıktan çıkarıp karanlıklara sokar. İşte onlar ateş ehlidir ve orada sürekli kalacaklardır.', 'الله ولي الذين امنوا يخرجهم من الظلمت الي النور والذين كفروا اولياوهم الطغوت يخرجونهم من النور الي الظلمت اوليك اصحب النار هم فيها خالدون'),
(265, 2, 258, 'اَلَمْ تَرَ اِلَى الَّذ۪ي حَٓاجَّ اِبْرٰه۪يمَ ف۪ي رَبِّه۪ٓ اَنْ اٰتٰيهُ اللّٰهُ الْمُلْكَۢ اِذْ قَالَ اِبْرٰه۪يمُ رَبِّيَ الَّذ۪ي يُحْـي۪ وَيُم۪يتُۙ قَالَ اَنَا۬ اُحْـي۪ وَاُم۪يتُۜ قَالَ اِبْرٰه۪يمُ فَاِنَّ اللّٰهَ يَأْت۪ي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ فَبُهِتَ الَّذ۪ي كَفَرَۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَۚ', 'E lem tera ilellezi hacce ibrahime fi rabbihi en atahullahul mulk, iz kale ibrahimu rabbiyellezi yuhyi ve yumitu, kale ene uhyi ve umit, kale ibrahimu fe innallahe ye\'ti biş şemsi minel maşrıkı fe\'ti biha minel magribi fe buhitellezi kefer, vallahu la yehdil kavmez zalimin.', 'Allah,  kendisine mülk[1] verdi diye İbrahim\'le Rabb\'i hakkında tartışanı görmedin mi? Hani İbrahim: \"Benim Rabb\'im diriltir ve öldürür.\" demişti. O da: \"Ben de diriltir ve öldürürüm.\" demişti. İbrahim: \"Öyleyse,  Allah Güneş\'i doğudan çıkarıyor,  sen de batıdan çıkar.\" deyince,  küfreden[2] şaşırıp kaldı. Allah,  zalim olan halka doğru yolu göstermez.', 'الم تر الي الذي حاج ابرهم في ربه ان اتيه الله الملك اذ قال ابرهم ربي الذي يحي ويميت قال انا احي واميت قال ابرهم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظلمين'),
(266, 2, 259, 'اَوْ كَالَّذ۪ي مَرَّ عَلٰى قَرْيَةٍ وَهِيَ خَاوِيَةٌ عَلٰى عُرُوشِهَاۚ قَالَ اَنّٰى يُحْـي۪ هٰذِهِ اللّٰهُ بَعْدَ مَوْتِهَاۚ فَاَمَاتَهُ اللّٰهُ مِائَةَ عَامٍ ثُمَّ بَعَثَهُۜ قَالَ كَمْ لَبِثْتَۜ قَالَ لَبِثْتُ يَوْماً اَوْ بَعْضَ يَوْمٍۜ قَالَ بَلْ لَبِثْتَ مِائَةَ عَامٍ فَانْظُرْ اِلٰى طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْۚ وَانْظُرْ اِلٰى حِمَارِكَ وَلِنَجْعَلَكَ اٰيَةً لِلنَّاسِ وَانْظُرْ اِلَى الْعِظَامِ كَيْفَ نُنْشِزُهَا ثُمَّ نَكْسُوهَا لَحْماًۜ فَلَمَّا تَبَيَّنَ لَهُۙ قَالَ اَعْلَمُ اَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ev kellezi merra ala karyetin ve hiye haviyetun ala uruşiha, kale enna yuhyi hazihillahu ba\'de mevtiha, fe ematehullahu miete amin summe beaseh, kale kem lebist, kale lebistu yevme ev ba\'da yevm, kale bel lebiste miete amin fenzur ila taamike ve şerabike lem yetesenneh, venzur ila hımarike ve li nec\'aleke ayeten lin nasi venzur ilal izami keyfe nunşizuha summe neksuha lahma, fe lemma tebeyyene lehu, kale a\'lemu ennallahe ala kulli şey\'in kadir.', 'Veya temelleri üzerine yıkılıp,  harap olmuş beldeye uğrayan kimse gibi: \"Ölümünden sonra Allah bunu nasıl diriltecek? Demişti. Bunun üzerine Allah,  onu öldürüp yüz yıl ölü bıraktıktan sonra diriltti. Ona: \"Ne kadar süre ölü kaldın?\" dendi. O da: \"Bir gün veya bir günden daha az.\" dedi. Allah,  \"Hayır yüz yıl kaldın.\" dedi. Buna rağmen yiyeceğine ve içeceğine bak,  henüz bozulmamış. Ve eşeğine de bak. Bu,  insanlara ayet[1] olman içindir. Şu kemiklere bir bak,  onları nasıl düzenleyip sonra et giydiriyoruz.\" Ona bu detaylı açıklama yapıldıktan sonra: \"Artık anladım ki,  kuşkusuz Allah,  Her Şeye Güç Yetiren\'dir.\" dedi.', 'او كالذي مر علي قرية وهي خاوية علي عروشها قال اني يحي هذه الله بعد موتها فاماته الله ماية عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت ماية عام فانظر الي طعامك وشرابك لم يتسنه وانظر الي حمارك ولنجعلك اية للناس وانظر الي العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله علي كل شي قدير'),
(267, 2, 260, 'وَاِذْ قَالَ اِبْرٰه۪يمُ رَبِّ اَرِن۪ي كَيْفَ تُحْـيِ الْمَوْتٰىۜ قَالَ اَوَلَمْ تُؤْمِنْۜ قَالَ بَلٰى وَلٰكِنْ لِيَطْمَئِنَّ قَلْب۪يۜ قَالَ فَخُذْ اَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ اِلَيْكَ ثُمَّ اجْعَلْ عَلٰى كُلِّ جَبَلٍ مِنْهُنَّ جُزْءاً ثُمَّ ادْعُهُنَّ يَأْت۪ينَكَ سَعْياًۜ وَاعْلَمْ اَنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ۟', 'Ve iz kale ibrahimu rabbi erini keyfe tuhyil mevta kale e ve lem tu\'min kale bela ve lakin li yatmainne kalbi kale fe huz erbeaten minet tayri fe surhunne ileyke summec\'al ala kulli cebelin minhunne cuz\'en summed\'uhunne ye\'tineke sa\'ya, va\'lem ennallahe azizun hakim.', 'Hani bir zamanlar İbrahim: \"Ey Rabbim! Bana ölüleri nasıl dirilttiğini göster.\" demişti. Allah: \"İnanmıyor musun?\" deyince; İbrahim: \"Hayır,  inanıyorum; ancak kalbimin yatışmasını istiyorum.\" dedi. Allah: \"Kuşlardan dört tane tut,  onları iyice tanı,  sonra her dağın başına onlardan bir parça koy,  sonra onları kendine çağır,  koşarak sana gelecekler.\" dedi. Allah,  Mutlak Üstün Olan ve En Doğru Hüküm Veren\'dir.', 'واذ قال ابرهم رب ارني كيف تحي الموتي قال اولم تومن قال بلي ولكن ليطمين قلبي قال فخذ اربعة من الطير فصرهن اليك ثم اجعل علي كل جبل منهن جزا ثم ادعهن ياتينك سعيا واعلم ان الله عزيز حكيم'),
(268, 2, 261, 'مَثَلُ الَّذ۪ينَ يُنْفِقُونَ اَمْوَالَهُمْ ف۪ي سَب۪يلِ اللّٰهِ كَمَثَلِ حَبَّةٍ اَنْبَتَتْ سَبْعَ سَنَابِلَ ف۪ي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍۜ وَاللّٰهُ يُضَاعِفُ لِمَنْ يَشَٓاءُۜ وَاللّٰهُ وَاسِعٌ عَل۪يمٌ', 'Meselullezine yunfikune emvalehum fi sebilillahi ke meseli habbetin enbetet seb\'a senabile fi kulli sunbuletin mietu habbeh, vallahu yudaifu li men yeşau, vallahu vasiun alim.', 'Mallarını Allah yolunda infak[1] edenlerin durumu,  yedi başak bitiren ve her bir başakta yüz dane olan bir tohum tanesi gibidir. Allah hak edene[2] kat kat verir. Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Her Şeyi Bilen\'dir.', 'مثل الذين ينفقون امولهم في سبيل الله كمثل حبة انبتت سبع سنابل في كل سنبلة ماية حبة والله يضعف لمن يشا والله وسع عليم'),
(269, 2, 262, 'اَلَّذ۪ينَ يُنْفِقُونَ اَمْوَالَهُمْ ف۪ي سَب۪يلِ اللّٰهِ ثُمَّ لَا يُتْبِعُونَ مَٓا اَنْفَقُوا مَناًّ وَلَٓا اَذًۙى لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۚ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Ellezine yunfikune emvalehum fi sebilillahi summe la yutbiune ma enfeku mennen ve la ezen lehum ecruhum inde rabbihim, ve la havfun aleyhim ve la hum yahzenun.', 'Mallarını Allah yolunda infak[1] edip de ardından yaptığı iyiliği başa kakmayarak[2] yardımcı oldukları kimseleri incitmeyenlerin ödülleri Rabb\'leri katındadır. Onlara korku yoktur,  onlar üzülmeyeceklerdir.', 'الذين ينفقون امولهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذي لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون'),
(270, 2, 263, 'قَوْلٌ مَعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُهَٓا اَذًىۜ وَاللّٰهُ غَنِيٌّ حَل۪يمٌ', 'Kavlun ma\'rufun ve magfiretun, hayrun min sadakatin yetbeuha eza, vallahu ganiyyun halim.', 'Ma\'ruf[1] bir söz ve bağışlayıcı olmak,  ardından başa kakılarak eziyete dönüşen bir sadakadan daha hayırlıdır. Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Çok Şefkatli\'dir.', 'قول معروف ومغفرة خير من صدقة يتبعها اذي والله غني حليم'),
(271, 2, 264, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالْاَذٰىۙ كَالَّذ۪ي يُنْفِقُ مَالَهُ رِئَٓاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ فَمَثَلُهُ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَاَصَابَهُ وَابِلٌ فَتَرَكَهُ صَلْداًۜ لَا يَقْدِرُونَ عَلٰى شَيْءٍ مِمَّا كَسَبُواۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْكَافِر۪ينَ', 'Ya eyyuhellezine amenu la tubtılu sadakatikum bil menni vel eza, kellezi yunfiku malehu riaen nasi ve la yu\'minu billahi vel yevmil ahır, fe meseluhu ke meseli safvanin aleyhi turabun fe esabehu vabilun fe terakehu salda, la yakdirune ala şey\'in mimma kesebu vallahu la yehdil kavmel kafirin.', 'Ey iman edenler! Allah\'a ve Ahiret Günü\'ne inanmadığı halde,  insanlara malını gösteriş yapmak için harcayan kimse gibi; sadakalarınızı başa kakarak[1] ve inciterek boşa çıkarmayın. Böylelerinin durumu üzeri toprakla örtülü kaygan bir kayaya benzer. Sağanak bir yağmur yağınca,  kaya çırılçıplak ortaya çıkar. Onlar,  yaptıklarından hiçbir şey elde edemezler. Allah,  Kafir halka doğru yolu göstermez.', 'يايها الذين امنوا لا تبطلوا صدقتكم بالمن والاذي كالذي ينفق ماله ريا الناس ولا يومن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا لا يقدرون علي شي مما كسبوا والله لا يهدي القوم الكفرين'),
(272, 2, 265, 'وَمَثَلُ الَّذ۪ينَ يُنْفِقُونَ اَمْوَالَهُمُ ابْتِغَٓاءَ مَرْضَاتِ اللّٰهِ وَتَثْب۪يتاً مِنْ اَنْفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ اَصَابَهَا وَابِلٌ فَاٰتَتْ اُكُلَهَا ضِعْفَيْنِۚ فَاِنْ لَمْ يُصِبْهَا وَابِلٌ فَطَلٌّۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Ve meselullezine yunfikune emvalehumubtigae mardatillahi ve tesbiten min enfusihim ke meseli cennetin bi rabvetin esabeha vabilun fe atet ukuleha dı\'feyn, fe in lem yusıbha vabilun fe tall, vallahu bima ta\'melune basir.', 'Allah\'ın rızasına kavuşmak için,  içten gelerek malını harcayan kimsenin durumu; kuvvetli yağmur yağdığında kat kat ürün veren,  kuvvetli yağmur olmasa da çisentisinin yeteceği yüksek bir yerdeki cennete[1] benzer. Allah,  yaptığınız her şeyi görendir.', 'ومثل الذين ينفقون امولهم ابتغا مرضات الله وتثبيتا من انفسهم كمثل جنة بربوة اصابها وابل فاتت اكلها ضعفين فان لم يصبها وابل فطل والله بما تعملون بصير'),
(273, 2, 266, 'اَيَوَدُّ اَحَدُكُمْ اَنْ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخ۪يلٍ وَاَعْنَابٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۙ لَهُ ف۪يهَا مِنْ كُلِّ الثَّمَرَاتِۙ وَاَصَابَهُ الْكِبَرُ وَلَهُ ذُرِّيَّةٌ ضُعَفَٓاءُۖ فَاَصَابَهَٓا اِعْصَارٌ ف۪يهِ نَارٌ فَاحْتَرَقَتْۜ كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمُ الْاٰيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ۟', 'E yeveddu ehadukum en tekune lehu cennetun min nahilin ve a\'nabin tecri min tahtihel enharu, lehu fiha min kullis semarati ve esabehul kiberu ve lehu zurriyyetun duafau fe esabeha ı\'sarun fihi narun fahterakat kezalike yubeyyinullahu lekumul ayati leallekum tetefekkerun.', 'Sizden biriniz ister mi ki: Kendisi yaşlanmış ve bakıma muhtaç çocukları da varken,  içinde nehirler akan,  her türlü meyvesi olan,  hurma ve üzüm ağaçları bulunan bahçesini ateşten bir kasırga gelip yaksın. İşte,  Allah,  düşünesiniz diye ayetlerini böyle açıklıyor.', 'ايود احدكم ان تكون له جنة من نخيل واعناب تجري من تحتها الانهر له فيها من كل الثمرت واصابه الكبر وله ذرية ضعفا فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايت لعلكم تتفكرون'),
(274, 2, 267, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّٓا اَخْرَجْنَا لَكُمْ مِنَ الْاَرْضِۖ وَلَا تَيَمَّمُوا الْخَب۪يثَ مِنْهُ تُنْفِقُونَ وَلَسْتُمْ بِاٰخِذ۪يهِ اِلَّٓا اَنْ تُغْمِضُوا ف۪يهِۜ وَاعْلَمُٓوا اَنَّ اللّٰهَ غَنِيٌّ حَم۪يدٌ', 'Ya eyyuhellezine amenu enfiku min tayyibati ma kesebtum ve mimma ahracna lekum minel ard, ve la teyemmemul habise minhu tunfikune ve lestum bi ahızihı illa en tugmidu fih, va\'lemu ennallahe ganiyyun hamid.', 'Ey iman edenler! Kazandığınız şeylerin temiz ve iyi olanlarından ve sizin için yerden çıkardıklarımızdan infak edin[1]. Gözünüz kapalı kendinize almayacağınız,  uygun görmediğiniz[2] kötü şeyleri infak etmeyin. Bilin ki: Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'يايها الذين امنوا انفقوا من طيبت ما كسبتم ومما اخرجنا لكم من الارض ولا تيمموا الخبيث منه تنفقون ولستم باخذيه الا ان تغمضوا فيه واعلموا ان الله غني حميد'),
(275, 2, 268, 'اَلشَّيْطَانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُمْ بِالْفَحْشَٓاءِۚ وَاللّٰهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ وَفَضْلاًۜ وَاللّٰهُ وَاسِعٌ عَل۪يمٌۚ', 'Eş şeytanu yeidukumul fakra ve ye\'murukumbil fahşai vallahu yeidukum magfireten minhuve fadla, vallahu vasiun alim.', 'Şeytan,  yoksullukla[1] size fahşayı[2] telkin eder. Allah ise sizi bağışlama ve bol nimet söz veriyor. Allah,  Yardımı Çok Kapsyıcı Olan\'dır,  Her Şeyi Bilen\'dir.', 'الشيطن يعدكم الفقر ويامركم بالفحشا والله يعدكم مغفرة منه وفضلا والله وسع عليم'),
(276, 2, 269, 'يُؤْتِي الْحِكْمَةَ مَنْ يَشَٓاءُۚ وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ اُو۫تِيَ خَيْراً كَث۪يراًۜ وَمَا يَذَّكَّرُ اِلَّٓا اُو۬لُوا الْاَلْبَابِ', 'Yu\'til hikmete men yeşau, ve men yu\'tel hikmete fe kad utiye hayran kesira, ve ma yezzekkeru illa ulul elbab.', 'O hikmeti[1] dilediğine[2] verir. Kime hikmet verilmişse ona pek büyük bir hayır verilmiş demektir. Bunu ancak sağlıklı düşünen akıl sahipleri anlar.', 'يوتي الحكمة من يشا ومن يوت الحكمة فقد اوتي خيرا كثيرا وما يذكر الا اولوا الالبب'),
(277, 2, 270, 'وَمَٓا اَنْفَقْتُمْ مِنْ نَفَقَةٍ اَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَاِنَّ اللّٰهَ يَعْلَمُهُۜ وَمَا لِلظَّالِم۪ينَ مِنْ اَنْصَارٍ', 'Ve ma enfaktum min nafakatin ev nezertum min nezrin fe innallahe ya\'lemuh, ve ma liz zalimine min ensar.', 'Nafaka[1] olarak neyi infak[2] eder veya adak olarak neyi adarsanız,  Allah onu bilir. Zulmedenlerin hiçbir yardımcısı yoktur.', 'وما انفقتم من نفقة او نذرتم من نذر فان الله يعلمه وما للظلمين من انصار'),
(278, 2, 271, 'اِنْ تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَۚ وَاِنْ تُخْفُوهَا وَتُؤْتُوهَا الْفُقَـرَٓاءَ فَهُوَ خَيْرٌ لَكُمْۜ وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّـَٔاتِكُمْۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'İn tubdus sadakati fe niimma hiy, ve in tuhfuha ve tu\'tuhal fukarae fe huve hayrun lekum ve yukeffiru ankum min seyyiatikum vallahu bi ma ta\'melune habir.', 'Sadakaları[1] açıktan vermeniz güzeldir. Ancak fakirlere yapacağınız yardımı gizliden yaparsanız bu sizin için daha hayırlıdır. Bu,  kötülüklerinizin bir kısmının kapanmasını sağlar. Allah yaptığınız her şeyden haberdardır.', 'ان تبدوا الصدقت فنعما هي وان تخفوها وتوتوها الفقرا فهو خير لكم ويكفر عنكم من سياتكم والله بما تعملون خبير'),
(279, 2, 272, 'لَيْسَ عَلَيْكَ هُدٰيهُمْ وَلٰكِنَّ اللّٰهَ يَهْد۪ي مَنْ يَشَٓاءُۜ وَمَا تُنْفِقُوا مِنْ خَيْرٍ فَلِاَنْفُسِكُمْۜ وَمَا تُنْفِقُونَ اِلَّا ابْتِغَٓاءَ وَجْهِ اللّٰهِۜ وَمَا تُنْفِقُوا مِنْ خَيْرٍ يُوَفَّ اِلَيْكُمْ وَاَنْتُمْ لَا تُظْلَمُونَ', 'Leyse aleyke hudahum ve lakinnallahe yehdi men yeşau, ve ma tunfiku min hayrin fe li enfusikum, ve ma tunfikune illebtigae vechillah, ve ma tunfiku min hayrin yuveffe ileykum ve entum la tuzlemun.', 'Onları hidayete iletmek sana düşmez. Allah,  hak edeni[1] doğru yola iletir. Hayır olarak her ne infak[2] ederseniz,  kendiniz içindir. Zaten siz,  ancak Allah\'ı hoşnut etmek için infak yaparsınız. Yapacağınız her hayrın karşılığı size tam olarak verilir ve size asla haksızlık yapılmaz.', 'ليس عليك هديهم ولكن الله يهدي من يشا وما تنفقوا من خير فلانفسكم وما تنفقون الا ابتغا وجه الله وما تنفقوا من خير يوف اليكم وانتم لا تظلمون'),
(280, 2, 273, 'لِلْفُقَـرَٓاءِ الَّذ۪ينَ اُحْصِرُوا ف۪ي سَب۪يلِ اللّٰهِ لَا يَسْتَط۪يعُونَ ضَـرْباً فِي الْاَرْضِۘ يَحْسَبُهُمُ الْجَاهِلُ اَغْنِيَٓاءَ مِنَ التَّعَفُّفِۚ تَعْرِفُهُمْ بِس۪يمٰيهُمْۚ لَا يَسْـَٔلُونَ النَّاسَ اِلْحَافاًۜ وَمَا تُنْفِقُوا مِنْ خَيْرٍ فَاِنَّ اللّٰهَ بِه۪ عَل۪يمٌ۟', 'Lil fukaraillezine uhsiru fi sebilillahi la yestatiune darben fil ardı, yahsebuhumul cahilu agniyae minet teaffuf, ta\'rifuhum bi simahum, la yes\'elunen nase ilhafa, ve ma tunfiku min hayrin fe innallahe bihi alim.', 'Yardımlar Allah yolunda mahsur[1] olan,  çalışmaya güç yetiremeyen yoksullar içindir. Bilmeyenler,  utangaçlıklarından dolayı onları zengin sanır. Sen,  onları yüzlerinden tanırsın. Yüzsüzlük ederek kimseyi rahatsız etmezler. Hayır olarak ne infak[2] ederseniz muhakkak Allah,  onu bilir.', 'للفقرا الذين احصروا في سبيل الله لا يستطيعون ضربا في الارض يحسبهم الجاهل اغنيا من التعفف تعرفهم بسيمهم لا يسلون الناس الحافا وما تنفقوا من خير فان الله به عليم'),
(281, 2, 274, 'اَلَّذ۪ينَ يُنْفِقُونَ اَمْوَالَهُمْ بِالَّيْلِ وَالنَّهَارِ سِراًّ وَعَلَانِيَةً فَلَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۚ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Ellezine yunfikune emvalehum bil leyli ven nehari sirran ve alaniyeten fe lehum ecruhum inde rabbihim, ve la havfun aleyhim ve la hum yahzenun.', 'Mallarını gece ve gündüz,  gizli ve açık infak edenlerin ödüllerini Rabb\'leri verecektir. Ve onlar için korku yoktur ve onlar üzülmeyeceklerdir.', 'الذين ينفقون امولهم باليل والنهار سرا وعلانية فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون'),
(282, 2, 275, 'اَلَّذ۪ينَ يَأْكُلُونَ الرِّبٰوا لَا يَقُومُونَ اِلَّا كَمَا يَقُومُ الَّذ۪ي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّۜ ذٰلِكَ بِاَنَّهُمْ قَالُٓوا اِنَّمَا الْبَيْعُ مِثْلُ الرِّبٰواۢ وَاَحَلَّ اللّٰهُ الْبَيْعَ وَحَرَّمَ الرِّبٰواۜ فَمَنْ جَٓاءَهُ مَوْعِظَةٌ مِنْ رَبِّه۪ فَانْتَهٰى فَلَهُ مَا سَلَفَۜ وَاَمْرُهُٓ اِلَى اللّٰهِۜ وَمَنْ عَادَ فَاُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Ellezine ye\'kuluner riba la yekumune illa kema yekumullezi yetehabbetuhuş şeytanu minel mess, zalike bi ennehum kalu innemal bey\'u mislur riba, ve ehallallahul bey\'a ve harramer riba fe men caehu mev\'izatun min rabbihi fenteha fe lehu ma selef, ve emruhu ilallah, ve men ade fe ulaike ashabun nar, hum fiha halidun.', 'Riba[1] yiyenler,  ancak şeytanın dokunuşuyla çarptığı kimselerin kalktığı gibi kalkarlar. Bu,  onların,  \"Alışveriş de riba gibidir.\" demelerindendir. Oysa Allah,  alışverişi helal,  ribayı haram kılmıştır. Kim Rabb\'inden gelen öğüde uyarak,  ribadan vazgeçerse,  geçmişte aldığı onundur. Onun kararı Allah\'a kalmıştır. Kim tekrar ribaya dönerse,  işte onlar ateş ehlidirler ve orada sürekli kalacaklardır.', 'الذين ياكلون الربوا لا يقومون الا كما يقوم الذي يتخبطه الشيطن من المس ذلك بانهم قالوا انما البيع مثل الربوا واحل الله البيع وحرم الربوا فمن جاه موعظة من ربه فانتهي فله ما سلف وامره الي الله ومن عاد فاوليك اصحب النار هم فيها خلدون'),
(283, 2, 276, 'يَمْحَقُ اللّٰهُ الرِّبٰوا وَيُرْبِي الصَّدَقَاتِۜ وَاللّٰهُ لَا يُحِبُّ كُلَّ كَفَّارٍ اَث۪يمٍ', 'Yemhakullahur riba ve yurbis sadakat, vallahu la yuhıbbu kulle keffarin esim.', 'Allah,  ribayı eksiltir,  sadakaları da artırır. Allah,  nankörlük ederek günahta ısrar edenleri sevmez.', 'يمحق الله الربوا ويربي الصدقت والله لا يحب كل كفار اثيم'),
(284, 2, 277, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَاَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۚ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'İnnellezine amenu ve amilus salihati ve ekamus salate ve atevuz zekate lehum ecruhum inde rabbihim, ve la havfun aleyhim ve la hum yahzenun.', 'İman edip,  salihatı yapanların[1],  salatı ikame edenlerin ve zekatı yapanların[2] ödülleri kuşkusuz Rabb\'lerinin yanındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir.', 'ان الذين امنوا وعملوا الصلحت واقاموا الصلوة واتوا الزكوة لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون'),
(285, 2, 278, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَذَرُوا مَا بَـقِيَ مِنَ الرِّبٰٓوا اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ya eyyuhellezine amenuttekullahe ve zeru ma bakiye miner riba in kuntum mu\'minin.', 'Ey iman edenler! Allah\'a karşı takvalı olun. Eğer Mümin\'seniz,  ribadan geriye kalanı almayın.', 'يايها الذين امنوا اتقوا الله وذروا ما بقي من الربوا ان كنتم مومنين'),
(286, 2, 279, 'فَاِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللّٰهِ وَرَسُولِه۪ۚ وَاِنْ تُبْتُمْ فَلَكُمْ رُؤُ۫سُ اَمْوَالِكُمْۚ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', 'Fe in lem tef\'alu fe\'zenu bi harbin minallahi ve resulih, ve in tubtum fe lekum ruusu emvalikum, la tazlimune ve la tuzlemun.', 'Eğer bırakmazsanız,  o zaman Allah ve Resul\'ünün size savaş açacağını bilin. Eğer tevbe ederseniz,  ana malınız sizindir. Böylece ne haksızlık etmiş ne de haksızlığa uğramış olursunuz.', 'فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم روس امولكم لا تظلمون ولا تظلمون'),
(287, 2, 280, 'وَاِنْ كَانَ ذُوعُسْرَةٍ فَنَظِرَةٌ اِلٰى مَيْسَرَةٍۜ وَاَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Ve in kane zu usratin fe naziratun ila meysereh ve en tesaddeku hayrun lekum in kuntum ta\'lemun.', 'Eğer borçlu dardaysa ona ödemede kolaylık sağlayın,  eğer alacağınızı bağışlarsanız,  bunun sizin için daha hayırlı olduğunu bilin.', 'وان كان ذو عسرة فنظرة الي ميسرة وان تصدقوا خير لكم ان كنتم تعلمون'),
(288, 2, 281, 'وَاتَّقُوا يَوْماً تُرْجَعُونَ ف۪يهِ اِلَى اللّٰهِ ثُمَّ تُوَفّٰى كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ۟', 'Vetteku yevmen turceune fihi ilallahi summe tuveffa kullu nefsin ma kesebet ve hum la yuzlemun.', 'Allah\'a döndürüleceğiniz gün için takvalı olun. O gün,  hiç kimseye haksızlık yapılmaksızın,  yaptıklarının karşılığı tam olarak verilecektir.', 'واتقوا يوما ترجعون فيه الي الله ثم توفي كل نفس ما كسبت وهم لا يظلمون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(289, 2, 282, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا تَدَايَنْتُمْ بِدَيْنٍ اِلٰٓى اَجَلٍ مُسَمًّى فَاكْتُبُوهُۜ وَلْيَكْتُبْ بَيْنَكُمْ كَاتِبٌ بِالْعَدْلِۖ وَلَا يَأْبَ كَاتِبٌ اَنْ يَكْتُبَ كَمَا عَلَّمَهُ اللّٰهُ فَلْيَكْتُبْۚ وَلْيُمْلِلِ الَّذ۪ي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللّٰهَ رَبَّهُ وَلَا يَبْخَسْ مِنْهُ شَيْـٔاًۜ فَاِنْ كَانَ الَّذ۪ي عَلَيْهِ الْحَقُّ سَف۪يهاً اَوْ ضَع۪يفاً اَوْ لَا يَسْتَط۪يعُ اَنْ يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِۜ وَاسْتَشْهِدُوا شَه۪يدَيْنِ مِنْ رِجَالِكُمْۚ فَاِنْ لَمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَاَتَانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَٓاءِ اَنْ تَضِلَّ اِحْدٰيهُمَا فَتُذَكِّرَ اِحْدٰيهُمَا الْاُخْرٰىۜ وَلَا يَأْبَ الشُّهَدَٓاءُ اِذَا مَا دُعُواۜ وَلَا تَسْـَٔمُٓوا اَنْ تَكْتُبُوهُ صَغ۪يراً اَوْ كَب۪يراً اِلٰٓى اَجَلِه۪ۜ ذٰلِكُمْ اَقْسَطُ عِنْدَ اللّٰهِ وَاَقْوَمُ لِلشَّهَادَةِ وَاَدْنٰٓى اَلَّا تَرْتَابُٓوا اِلَّٓا اَنْ تَكُونَ تِجَارَةً حَاضِرَةً تُد۪يرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَلَّا تَكْتُبُوهَاۜ وَاَشْهِدُٓوا اِذَا تَبَايَعْتُمْۖ وَلَا يُضَٓارَّ  كَاتِبٌ وَلَا شَه۪يدٌۜ وَاِنْ تَفْعَلُوا فَاِنَّهُ فُسُوقٌ بِكُمْۜ وَاتَّقُوا اللّٰهَۜ وَيُعَلِّمُكُمُ اللّٰهُۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Ya eyyuhellezine amenu iza tedayentum bi deynin ila ecelin musemmen fektubuh, velyektub beynekum katibun bil adl, ve la ye\'be katibun en yektube kema allemehullahu felyektub, velyumlilillezi aleyhil hakku velyettekıllahe rabbehu ve la yebhas minhu şey\'a, fe in kanellezi aleyhil hakku sefihan ev daifen ev la yestatiu en yumille huve felyumlil veliyyuhu bil adl, vesteşhidu şehideyni min ricalikum, fe in lem yekuna raculeyni fe raculun vemraetani mimmen terdavne mineş şuhedai en tedılle ıhdahuma fe tuzekkire ıhdahumal uhra ve la ye\'beş şuhedau iza ma duu, ve la tes\'emu en tektubuhu sagiran ev kebiran ila ecelih, zalikum aksatu indallahi ve akvemu liş şehadeti ve edna ella tertabu illa en tekune ticareten hadıraten tudiruneha beynekum fe leyse aleykum cunahun ella tektubuha ve eşhidu iza tebaya\'tum, ve la yudarra katibun ve la şehid, ve in tef\'alu fe innehu fusukun bikum, vettekullah, ve yuallimukumullah, vallahu bi kulli şey\'in alim.', 'Ey iman edenler! Belli bir süre için birbirinize borç verdiğiniz zaman onu yazın. Yazan her kimse,  onu adaletle yazsın. Allah\'ın kendisine öğrettiği şekilde[1] yazmaktan kaçınmasın,  yazsın. Borçlu olan da yazdırsın. Rabb\'i olan Allah\'a karşı takvalı olsun,  ondan hiçbir şeyi eksik bırakmasın. Eğer borçlu aklı ermez,  aciz veya kendi söyleyip yazdıramayacak durumda birisi ise,  velisi,  onu adaletli bir şekilde yazdırsın. Erkeklerinizden de iki tanık tutun. Eğer iki erkek bulunmazsa,  o zaman razı olacağınız tanıklardan bir erkek ve biri şaşırdığında diğeri ona hatırlatacak iki kadın[2] tanık tutun. Tanıklar,  çağrıldıkları zaman kaçınmasınlar. Az olsun çok olsun onu vadesiyle birlikte yazmaktan üşenmeyin. Bu,  Allah katında en adil,  tanıklık için daha sağlam ve şüphe etmemeniz için daha uygundur. Ancak,  aranızda hemen devredip durduğunuz ve peşin olarak yaptığınız ticaret başka,  bunu yazmamanızda sizin için bir sakınca yoktur. Alışveriş yaptığınız zaman tanık bulundurun. Tanık olana da yazana da zarar verilmesin. Eğer bunu yaparsanız kendinize kötülük yapmış olursunuz. Allah\'a takvalı olun. Allah,  size gerekli olanı öğretiyor. Ve Allah,  Her Şeyi Bilen\'dir.', 'يايها الذين امنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه وليكتب بينكم كاتب بالعدل ولا ياب كاتب ان يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيا فان كان الذي عليه الحق سفيها او ضعيفا او لا يستطيع ان يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهدا ان تضل احديهما فتذكر احديهما الاخري ولا ياب الشهدا اذا ما دعوا ولا تسموا ان تكتبوه صغيرا او كبيرا الي اجله ذلكم اقسط عند الله واقوم للشهدة وادني الا ترتابوا الا ان تكون تجرة حاضرة تديرونها بينكم فليس عليكم جناح الا تكتبوها واشهدوا اذا تبايعتم ولا يضار كاتب ولا شهيد وان تفعلوا فانه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شي عليم'),
(290, 2, 283, 'وَاِنْ كُنْتُمْ عَلٰى سَفَرٍ وَلَمْ تَجِدُوا كَاتِباً فَرِهَانٌ مَقْبُوضَةٌۜ فَاِنْ اَمِنَ بَعْضُكُمْ بَعْضاً فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ اَمَانَتَهُ وَلْيَتَّقِ اللّٰهَ رَبَّهُۜ وَلَا تَكْتُمُوا الشَّهَادَةَۜ وَمَنْ يَكْتُمْهَا فَاِنَّهُٓ اٰثِمٌ قَلْبُهُۜ وَاللّٰهُ بِمَا تَعْمَلُونَ عَل۪يمٌ۟', 'Ve in kuntum ala seferin ve lem tecidu katiben fe rihanun makbudah, fe in emine ba\'dukum ba\'dan felyueddillezi\'tumine emanetehu velyettekıllahe rabbeh, ve la tektumuş şehadeh, ve men yektumha fe innehu asimun kalbuh, vallahu bi ma ta\'melune alim.', 'Eğer yolculukta olup da yazıcı bulamazsanız,  alınan rehinler yeterlidir. Eğer,  birbirinize güveniyorsanız,  güvenilen kimse,  üzerindeki emaneti ödesin. Rabb\'i olan Allah\'a takvalı olsun. Ve tanık olduğunuz şeyi gizlemeyin. Kim onu gizlerse kalben günah işlemiş olur. Allah,  yaptığınız her şeyi bilir.', 'وان كنتم علي سفر ولم تجدوا كاتبا فرهن مقبوضة فان امن بعضكم بعضا فليود الذي اوتمن امنته وليتق الله ربه ولا تكتموا الشهدة ومن يكتمها فانه اثم قلبه والله بما تعملون عليم'),
(291, 2, 284, 'لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَاِنْ تُبْدُوا مَا ف۪ٓي اَنْفُسِكُمْ اَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللّٰهُۜ فَيَغْفِرُ لِمَنْ يَشَٓاءُ وَيُعَذِّبُ مَنْ يَشَٓاءُۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Lillahi ma fis semavati ve ma fil ard, ve in tubdu ma fi enfusikum ev tuhfuhu yuhasibkum bihillah, fe yagfiru limen yeşau ve yuazzibu men yeşau, vallahu ala kulli şey\'in kadir.', 'Gökte ve yerde olan her şey,  Allah\'ındır. İçinizde olanı[1] açıklasanız da gizleseniz de Allah,  sizi onunla hesaba çeker. Allah hak eden[2] kimseyi bağışlar,  hak eden kimseye de azap eder. Allah,  Her Şeye Güç Yetiren\'dir.', 'لله ما في السموت وما في الارض وان تبدوا ما في انفسكم او تخفوه يحاسبكم به الله فيغفر لمن يشا ويعذب من يشا والله علي كل شي قدير'),
(292, 2, 285, 'اٰمَنَ الرَّسُولُ بِمَٓا اُنْزِلَ اِلَيْهِ مِنْ رَبِّه۪ وَالْمُؤْمِنُونَۜ كُلٌّ اٰمَنَ بِاللّٰهِ وَمَلٰٓئِكَتِه۪ وَكُتُبِه۪ وَرُسُلِه۪ۜ لَا نُفَرِّقُ بَيْنَ اَحَدٍ مِنْ رُسُلِه۪۠ وَقَالُوا سَمِعْنَا وَاَطَعْنَا غُفْرَانَكَ رَبَّنَا وَاِلَيْكَ الْمَص۪يرُ', 'Amener resulu bima unzile ileyhi min rabbihi vel mu\'minun, kullun amene billahi ve melaiketihi ve kutubihi ve rusulih, la nuferriku beyne ehadin min rusulih, ve kalu semi\'na ve ata\'na gufraneke rabbena ve ileykel masir.', 'Resul,  Rabb\'inden kendisine indirilene iman etti,  Mü\'minler de. Hepsi; Allah\'a,  meleklerine,  kitaplarına ve resullerine iman ettiler: \"Biz,  O\'nun resullerinden hiçbirini diğerinden ayırt etmeyiz. İşittik ve itaat ettik. Rabb\'imiz! Bizi bağışla,  dönüşümüz ancak Sana\'dır.\" dediler.', 'امن الرسول بما انزل اليه من ربه والمومنون كل امن بالله ومليكته وكتبه ورسله لا نفرق بين احد من رسله وقالوا سمعنا واطعنا غفرانك ربنا واليك المصير'),
(293, 2, 286, 'لَا يُكَلِّفُ اللّٰهُ نَفْساً اِلَّا وُسْعَهَاۜ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْۜ رَبَّنَا لَا تُؤَاخِذْنَٓا اِنْ نَس۪ينَٓا اَوْ اَخْطَأْنَاۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَٓا اِصْراً كَمَا حَمَلْتَهُ عَلَى الَّذ۪ينَ مِنْ قَبْلِنَاۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِه۪ۚ وَاعْفُ عَنَّا۠ وَاغْفِرْ لَنَا۠ وَارْحَمْنَا۠ اَنْتَ مَوْلٰينَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِر۪ينَ', 'La yukellifullahu nefsen illa vus\'aha leha ma kesebet ve aleyha mektesebet rabbena la tuahızna in nesina ev ahta\'na, rabbena ve la tahmil aleyna ısran kema hameltehu alellezine min kablina, rabbena ve la tuhammilna ma la takate lena bih, va\'fu anna, vagfir lena, verhamna, ente mevlana fensurna alel kavmil kafirin.', 'Allah,  hiç kimseye gücünün yeteceğinden fazla yük yüklemez. Herkesin yaptığı iyilik lehine,  kötülük de aleyhinedir. \"Rabb\'imiz! Unutur veya yanlış yaparsak,  bizi sorumlu tutma. Rabb\'imiz! Bize daha öncekilere yüklediğin gibi zor şeyler yükleme.[1] Rabb\'imiz! Bize gücümüzün üzerinde bir sorumluluk yükleme. Bizi affet,  bizi bağışla,  bize merhamet et. Sen,  Mevlamız\'sın. Gerçeği yalanlayan nankörler toplumuna karşı bize yardım et.', 'لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تواخذنا ان نسينا او اخطانا ربنا ولا تحمل علينا اصرا كما حملته علي الذين من قبلنا ربنا ولا تحملنا ما لا طاقة لنا به واعف عنا واغفر لنا وارحمنا انت مولينا فانصرنا علي القوم الكفرين'),
(294, 3, 1, 'الٓمٓۚ', 'Elif lam mim.', 'Elif. Lam. Mim.', 'الم'),
(295, 3, 2, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۙ الْحَيُّ الْقَيُّومُۜ', 'Allahu la ilahe illa huvel hayyul kayyum.', 'Allah,  kendisinden başka ilah olmayandır. O,  Mutlak Diri\'dir,  Varlığı Koruyup Yöneten\'dir.', 'الله لا اله الا هو الحي القيوم'),
(296, 3, 3, 'نَزَّلَ عَلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ وَاَنْزَلَ التَّوْرٰيةَ وَالْاِنْج۪يلَۙ', 'Nezzele aleykel kitabe bil hakkı musaddikan lima beyne yedeyhi ve enzelet tevrate vel incil.', 'Kendinden öncekilerini onaylayan Kitap\'ı Hakk olarak sana indiren O\'dur. Tevrat\'ı ve İncil\'i de O indirmişti.', 'نزل عليك الكتب بالحق مصدقا لما بين يديه وانزل التورية والانجيل'),
(297, 3, 4, 'مِنْ قَبْلُ هُدًى لِلنَّاسِ وَاَنْزَلَ الْفُرْقَانَۜ اِنَّ الَّذ۪ينَ كَفَرُوا بِاٰيَاتِ اللّٰهِ لَهُمْ عَذَابٌ شَد۪يدٌۜ وَاللّٰهُ عَز۪يزٌ ذُوانْتِقَامٍ', 'Min kablu huden lin nasi ve enzelel furkan, innellezine keferu bi ayatillahi lehum azabun şedid, vallahu azizun zuntikam.', 'Daha önce insanlara doğru yolu göstermek için Furkan\'ı[1] indirdi. Kuşkusuz,  Allah\'ın ayetlerini küfredenler[2] için şiddetli bir azap vardır. Allah,  Mutlak Üstün Olan\'dır,  Suçlulara Hak Ettikleri Cezayı Veren\'dir.', 'من قبل هدي للناس وانزل الفرقان ان الذين كفروا بايت الله لهم عذاب شديد والله عزيز ذو انتقام'),
(298, 3, 5, 'اِنَّ اللّٰهَ لَا يَخْفٰى عَلَيْهِ شَيْءٌ فِي الْاَرْضِ وَلَا فِي السَّمَٓاءِۜ', 'İnnallahe la yahfa aleyhi şey\'un fil ardı ve la fis sema\'.', 'Kuşkusuz,  yerde ve gökte Allah\'a hiçbir şey gizli kalmaz.', 'ان الله لا يخفي عليه شي في الارض ولا في السما'),
(299, 3, 6, 'هُوَ الَّذ۪ي يُصَوِّرُكُمْ فِي الْاَرْحَامِ كَيْفَ يَشَٓاءُۜ   لَٓا اِلٰهَ اِلَّا هُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Huvellezi yusavvirukum fil erhami keyfe yeşa\', la ilahe illa huvel azizul hakim.', 'Sizi,  rahimlerde dilediği gibi şekillendiren O\'dur. O\'ndan başka ilah yoktur. Mutlak Üstün Olandır,  En Doğru Hüküm Veren\'dir.', 'هو الذي يصوركم في الارحام كيف يشا لا اله الا هو العزيز الحكيم'),
(300, 3, 7, 'هُوَ الَّـذ۪ٓي اَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ اٰيَاتٌ مُحْكَمَاتٌ هُنَّ اُمُّ الْكِتَابِ وَاُخَرُ مُتَشَابِهَاتٌۜ فَاَمَّا الَّذ۪ينَ ف۪ي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَٓاءَ الْفِتْنَةِ وَابْتِغَٓاءَ تَأْو۪يلِه۪ۚ وَمَا يَعْلَمُ تَأْو۪يلَهُٓ اِلَّا اللّٰهُۢ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ اٰمَنَّا بِه۪ۙ   كُلٌّ مِنْ عِنْدِ رَبِّنَاۚ وَمَا يَذَّكَّرُ اِلَّٓا اُو۬لُوا الْاَلْبَابِ', 'Huvellezi enzele aleykel kitabe minhu ayatun muhkematun hunne ummul kitabi ve uharu muteşabihat, fe emmellezine fi kulubihim zeygun fe yettebiune ma teşabehe minhubtigael fitneti vebtigae te\'vilih, ve ma ya\'lemu te\'vilehu illallah, ver rasihune fil ilmi yekulune amenna bihi, kullun min indi rabbina, ve ma yezzekkeru illa ulul elbab.', 'Bu Kitap\'ı sana indiren O\'dur. O\'nun bir kısım ayetleri muhkemdir[1] ki bunlar Kitap\'ın anasıdır. Diğer ayetler de muteşabihtir.[2] Böyleyken kalbinde eğrilik bulunanlar,  fitne çıkarmak ve kendi anlayışlarına uydurmak için muteşabih ayetlere yönelirler. Oysa onun en doğru te\'vilini[3] ancak Allah bilir. İlimde derinleşmiş olanlar:[4] \"Biz O\'na iman ettik,  bütün ayetler Rabb\'imizdendir.\" derler. Bunu ancak selim akıl[5] sahibi olanlar düşünüp öğüt alır.', 'هو الذي انزل عليك الكتب منه ايت محكمت هن ام الكتب واخر متشبهت فاما الذين في قلوبهم زيغ فيتبعون ما تشبه منه ابتغا الفتنة وابتغا تاويله وما يعلم تاويله الا الله والرسخون في العلم يقولون امنا به كل من عند ربنا وما يذكر الا اولوا الالبب'),
(301, 3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ اِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةًۚ اِنَّكَ اَنْتَ الْوَهَّابُ', 'Rabbena la tuziğ kulubena ba\'de iz hedeytena veheb lena min ledunke rahmeh, inneke entel vehhab.', 'Onlar derler ki: \"Rabb\'imiz! Bizi doğru yola ilettikten sonra kalplerimizi saptırma. Bize katından rahmet bağışla. Çünkü bağışlayıcı olan yalnız Sen\'sin.\"', 'ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمة انك انت الوهاب'),
(302, 3, 9, 'رَبَّنَٓا اِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَا رَيْبَ ف۪يهِۜ  اِنَّ اللّٰهَ لَا يُخْلِفُ الْم۪يعَادَ۟', 'Rabbena inneke camiun nasi li yevmin la raybe fih, innallahe la yuhliful miad.', '\"Rabb\'imiz! Sen,  geleceği kesin olan günde,  insanları toplayacaksın. Mutlak gerçek şudur ki Allah sözünden dönmez.', 'ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد'),
(303, 3, 10, 'اِنَّ الَّذ۪ينَ كَفَرُوا لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَٓا اَوْلَادُهُمْ مِنَ اللّٰهِ شَيْـٔاًۜ وَاُو۬لٰٓئِكَ هُمْ وَقُودُ النَّارِۙ', 'İnnellezine keferu len tuğniye anhum emvaluhum ve la evladuhum minallahi şey\'a, ve ulaike hum vekudun nar.', 'Kuşkusuz Kafirlerin ne mallarının ne de evlatlarının Allah\'ın yanında bir yararı olacaktır. Onlar ateşin yakıtıdırlar.', 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واوليك هم وقود النار'),
(304, 3, 11, 'كَدَأْبِ اٰلِ فِرْعَوْنَۙ وَالَّذ۪ينَ مِنْ قَبْلِهِمْۜ كَذَّبُوا بِاٰيَاتِنَاۚ فَاَخَذَهُمُ اللّٰهُ بِذُنُوبِهِمْۜ وَاللّٰهُ شَد۪يدُ الْعِقَابِ', 'Ke de\'bi ali fir\'avne, vellezine min kablihim kezzebu bi ayatina, fe ehazehumullahu bi zunubihim vallahu şedidul ıkab.', 'Onların durumu,  tıpkı Firavuncuların ve onlardan önceki kimselerin durumu gibidir. Ayetlerimizi yalanladılar; Allah da onları suçları nedeniyle yakaladı. Allah\'ın cezası çok çetindir.', 'كداب ال فرعون والذين من قبلهم كذبوا بايتنا فاخذهم الله بذنوبهم والله شديد العقاب'),
(305, 3, 12, 'قُلْ لِلَّذ۪ينَ كَفَرُوا سَتُغْلَبُونَ وَتُحْشَرُونَ اِلٰى جَهَنَّمَۜ وَبِئْسَ الْمِهَادُ', 'Kul lillezine keferu se tuglebune ve tuhşerune ila cehennem, ve bi\'sel mihad.', 'Kafirlere de ki: \"Yakında yenileceksiniz ve Cehennem\'e sürüleceksiniz. Orası ne kötü bir yerdir.\"', 'قل للذين كفروا ستغلبون وتحشرون الي جهنم وبيس المهاد'),
(306, 3, 13, 'قَدْ كَانَ لَكُمْ اٰيَةٌ ف۪ي فِئَتَيْنِ الْتَقَتَاۜ فِئَةٌ تُقَاتِلُ ف۪ي سَب۪يلِ اللّٰهِ وَاُخْرٰى كَافِرَةٌ يَرَوْنَهُمْ مِثْلَيْهِمْ رَأْيَ الْعَيْنِۜ وَاللّٰهُ يُؤَيِّدُ بِنَصْرِه۪ مَنْ يَشَٓاءُۜ اِنَّ ف۪ي ذٰلِكَ لَعِبْرَةً لِاُو۬لِي الْاَبْصَارِ', 'Kad kane lekum ayetun fi fieteynil tekata fietun tukatilu fi sebilillahi ve uhra kafiratun yeravnehum misleyhim ra\'yel ayn, vallahu yueyyidu bi nasrihi men yeşa\' inne fi zalike le ibreten li ulil ebsar.', 'İki topluluğun karşılaşmasında kesinlikle sizin için bir gösterge vardır: Topluluğun birisi Allah yolunda savaşanlardan,  diğeri de Kafirdi[1]. Kafirler,  onları[2] kendilerinin iki katı olarak görüyorlardı. Allah,  dilediğini yardımı ile destekler. Kuşkusuz,  basiret[3] sahipleri için bunda bir ders vardır.', 'قد كان لكم اية في فيتين التقتا فية تقتل في سبيل الله واخري كافرة يرونهم مثليهم راي العين والله يويد بنصره من يشا ان في ذلك لعبرة لاولي الابصر'),
(307, 3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ مِنَ النِّسَٓاءِ وَالْبَن۪ينَ وَالْقَنَاط۪يرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْاَنْعَامِ وَالْحَرْثِۜ ذٰلِكَ مَتَاعُ الْحَيٰوةِ الدُّنْيَاۚ وَاللّٰهُ عِنْدَهُ حُسْنُ الْمَاٰبِ', 'Zuyyine lin nasi hubbuş şehevati minen nisai vel benine vel kanatiril mukantarati minez zehebi vel fıddati vel haylil musevvemeti vel en\'ami vel hars, zalike metaul hayatid dunya, vallahu indehu HUSNUL MEAB.', 'Kadınlara,  çocuklara,  yığınlarla altın ve gümüşe,  soylu atlara,  davarlara ve ekinlere karşı tutkulu sevgi insanlara cazip gösterilmiştir. Bunlar,  dünya hayatının geçimlikleridir. Oysa asıl iyi olan sonuç Allah\'ın yanındadır.', 'زين للناس حب الشهوت من النسا والبنين والقنطير المقنطرة من الذهب والفضة والخيل المسومة والانعم والحرث ذلك متع الحيوة الدنيا والله عنده حسن الماب'),
(308, 3, 15, 'قُلْ اَؤُ۬نَبِّئُكُمْ بِخَيْرٍ مِنْ ذٰلِكُمْۜ لِلَّذ۪ينَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَا وَاَزْوَاجٌ مُطَهَّرَةٌ وَرِضْوَانٌ مِنَ اللّٰهِۜ وَاللّٰهُ بَص۪يرٌ بِالْعِبَادِۚ', 'Kul e unebbiukum bi hayrın min zalikum, lillezinettekav inde rabbihim cennatun tecri min tahtıhel enharu halidine fiha ve ezvacun mutahharatun ve rıdvanun minallah, vallahu basirun bil ıbad.', 'De ki: \"Size bundan daha hayırlısını haber vereyim mi? Takva[1] sahipleri için,  Rabb\'lerinin katında,  içinde sürekli kalacakları,  içinden nehirlerin aktığı Cennetler,  arındırılmış eşler ve Allah\'ın rızası vardır.\" Kuşkusuz,  Allah,  kullarını Hakkıyla Gören\'dir.', 'قل اونبيكم بخير من ذلكم للذين اتقوا عند ربهم جنت تجري من تحتها الانهر خلدين فيها وازوج مطهرة ورضون من الله والله بصير بالعباد'),
(309, 3, 16, 'اَلَّذ۪ينَ يَقُولُونَ رَبَّنَٓا اِنَّـنَٓا اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِۚ', 'Ellezine yekulune rabbena innena amenna fagfir lena zunubena ve kına azaben nar.', 'Bu kimseler: \"Rabb\'imiz! Biz,  Sana iman ettik. Suçlarımızı bağışla,  ateşin azabından bizi koru.\" derler;', 'الذين يقولون ربنا اننا امنا فاغفر لنا ذنوبنا وقنا عذاب النار'),
(310, 3, 17, 'اَلصَّابِر۪ينَ وَالصَّادِق۪ينَ وَالْقَانِت۪ينَ وَالْمُنْفِق۪ينَ وَالْمُسْتَغْفِر۪ينَ بِالْاَسْحَارِ', 'Es sabirine ves sadıkine vel kanitine vel munfikine vel mustagfirine bil eshar.', 'Bunlar: Sabreden,  dürüst olan,  gönülden bağlı olan,  infak eden ve seher vaktinde bağışlanma dileyenlerdir.', 'الصبرين والصدقين والقنتين والمنفقين والمستغفرين بالاسحار'),
(311, 3, 18, 'شَهِدَ اللّٰهُ اَنَّهُ لَٓا اِلٰهَ اِلَّا هُوَۙ وَالْمَلٰٓئِكَةُ وَاُو۬لُوا الْعِلْمِ قَٓائِماً بِالْقِسْطِۜ لَٓا اِلٰهَ اِلَّا هُوَ الْعَز۪يزُ الْحَك۪يمُۜ', 'Şehidallahu ennehu la ilahe illa huve, vel melaiketu ve ulul ilmi kaimen bil kıst, la ilahe illa huvel azizul hakim.', 'Kendisinden başka ilah olmadığına Allah tanıktır. Melekler ve hakkaniyeti gözeten ilim sahipleri[1] de tanıktırlar ki: O\'ndan başka ilah yoktur. O,  Mutlak Üstün Olan ve En Doğru Hüküm Veren\'dir.', 'شهد الله انه لا اله الا هو والمليكة واولوا العلم قايما بالقسط لا اله الا هو العزيز الحكيم'),
(312, 3, 19, 'اِنَّ الدّ۪ينَ عِنْدَ اللّٰهِ الْاِسْلَامُ۠ وَمَا اخْتَلَفَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ اِلَّا مِنْ بَعْدِ مَا جَٓاءَهُمُ الْعِلْمُ بَغْياً بَيْنَهُمْۜ وَمَنْ يَكْفُرْ بِاٰيَاتِ اللّٰهِ فَاِنَّ اللّٰهَ سَر۪يعُ الْحِسَابِ', 'İnned dine indallahil islam, ve mahtelefellezine utul kitabe illa min ba\'di ma caehumulılmu bagyen beynehum, ve men yekfur bi ayatillahi fe innallahe seriul hısab.', 'Kuşkusuz,  Allah katında din,  İslam\'dır. Kitap verilenler,  kendilerine bilgi geldikten sonra ihtirasları nedeniyle ihtilafa düştüler. Kim,  Allah\'ın ayetlerini kabul etmezse bilsin ki,  kuşkusuz Allah,  Hesabı Çabuk Gören\'dir.', 'ان الدين عند الله الاسلم وما اختلف الذين اوتوا الكتب الا من بعد ما جاهم العلم بغيا بينهم ومن يكفر بايت الله فان الله سريع الحساب'),
(313, 3, 20, 'فَاِنْ حَٓاجُّوكَ فَقُلْ اَسْلَمْتُ وَجْهِيَ لِلّٰهِ وَمَنِ اتَّـبَعَنِۜ وَقُلْ لِلَّذ۪ينَ اُو۫تُوا الْكِتَابَ وَالْاُمِّيّ۪نَ ءَاَسْلَمْتُمْۜ فَاِنْ اَسْلَمُوا فَقَدِ اهْتَدَوْاۚ وَاِنْ تَوَلَّوْا فَاِنَّمَا عَلَيْكَ الْبَلَاغُۜ وَاللّٰهُ بَص۪يرٌ بِالْعِبَادِ۟', 'Fe in haccuke fe kul eslemtu vechiye lillahi ve menittebean, ve kul lillezine utul kitabe vel ummiyyine e eslemtum, fe in eslemu fe kadihtedev, ve in tevellev fe innema aleykel belag, vallahu basirun bil ibad.', 'Eğer,  seninle tartışırlarsa de ki: \"Ben,  bütün benliğimle Allah\'a teslim oldum,  bana tabi olanlar da.\" Kendilerine Kitap verilenlere ve Kitap verilmeyenlere: \"Siz de teslim oldunuz mu?\" de. Eğer teslim olmuşlarsa,  kuşkusuz doğru yolu bulmuşlardır. Eğer yüz çevirirlerse,  sana düşen,  yalnızca duyurmaktır. Allah,  Kullarını Hakkıyla Görendir.', 'فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتب والامين اسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلغ والله بصير بالعباد'),
(314, 3, 21, 'اِنَّ الَّذ۪ينَ يَكْفُرُونَ بِاٰيَاتِ اللّٰهِ وَيَقْتُلُونَ النَّبِيّ۪نَ بِغَيْرِ حَقٍّۙ وَيَقْتُلُونَ الَّذ۪ينَ يَأْمُرُونَ بِالْقِسْطِ مِنَ النَّاسِۙ فَبَشِّرْهُمْ بِعَذَابٍ اَل۪يمٍ', 'İnnellezine yekfurune bi ayatillahi ve yaktulunen nebiyyine bi gayri hakkın ve yaktulunellezine ye\'murune bil kıstı minen nasi, fe beşşirhum bi azabin elim.', 'Allah\'ın ayetlerini küfredenler,  haksız yere nebilerini öldürenler,  insanlardan hakkaniyetli[1] olmayı isteyenleri öldürenler var ya,  onlara can yakıcı bir azabı haber ver.', 'ان الذين يكفرون بايت الله ويقتلون النبين بغير حق ويقتلون الذين يامرون بالقسط من الناس فبشرهم بعذاب اليم'),
(315, 3, 22, 'اُو۬لٰٓئِكَ الَّذ۪ينَ حَبِطَتْ اَعْمَالُهُمْ فِي الدُّنْيَا وَالْاٰخِرَةِۘ وَمَا لَهُمْ مِنْ نَاصِر۪ينَ', 'Ulaikellezine habitat a\'maluhum fid dunya vel ahirah, ve ma lehum min nasırin.', 'İşte o kimselerin,  dünyada da ahirette de yaptıkları boşa gitmiştir. Ve onların hiçbir yardımcıları da yoktur.', 'اوليك الذين حبطت اعملهم في الدنيا والاخرة وما لهم من نصرين'),
(316, 3, 23, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ اُو۫تُوا نَص۪يباً مِنَ الْكِتَابِ يُدْعَوْنَ اِلٰى كِتَابِ اللّٰهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلّٰى فَر۪يقٌ مِنْهُمْ وَهُمْ مُعْرِضُونَ', 'E lem tera ilellezine utu nasiben minel kitabi yud\'avne ila kitabillahi li yahkume beynehum summe yetevella ferikun minhum ve hum mu\'ridun.', 'Kitap\'tan nasiplenmiş[1] olanları görüyorsun değil mi? Bunlar,  aralarında hükmetmesi için Kitap\'a[2] çağrıldıklarında bir kısmı,  döneklik ederek ondan yüz çeviriyor.', 'الم تر الي الذين اوتوا نصيبا من الكتب يدعون الي كتب الله ليحكم بينهم ثم يتولي فريق منهم وهم معرضون'),
(317, 3, 24, 'ذٰلِكَ بِاَنَّهُمْ قَالُوا لَنْ تَمَسَّنَا النَّارُ اِلَّٓا اَيَّاماً مَعْدُودَاتٍۖ وَغَرَّهُمْ ف۪ي د۪ينِهِمْ مَا كَانُوا يَفْتَرُونَ', 'Zalike bi ennehum kalu len temessenen naru illa eyyamen ma\'dudat, ve garrahum fi dinihim ma kanu yefterun.', 'Bu dönekliklerinin nedeni,  onların: \"Ateş bize sayılı birkaç günün dışında dokunmayacak.\" şeklindeki inançlarıdır. Uydurup dinlerine yakıştırdıkları bu tür şeyler onları yanıltmaktadır.', 'ذلك بانهم قالوا لن تمسنا النار الا اياما معدودت وغرهم في دينهم ما كانوا يفترون'),
(318, 3, 25, 'فَكَيْفَ اِذَا جَمَعْنَاهُمْ لِيَوْمٍ لَا رَيْبَ ف۪يهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'Fe keyfe iza cema\'nahum li yevmin la raybe fihi ve vuffiyet kullu nefsin ma kesebet ve hum la yuzlemun.', 'Gelmesi kesin olan günde onları topladığımız zaman halleri nasıl olacak? Onlara haksızlık yapılmadan yaptıklarının karşılığı tam olarak verilecek.', 'فكيف اذا جمعنهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون'),
(319, 3, 26, 'قُلِ اللّٰهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَٓاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَٓاءُۘ وَتُعِزُّ مَنْ تَشَٓاءُ وَتُذِلُّ مَنْ تَشَٓاءُۜ بِيَدِكَ الْخَيْرُۜ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Kulillahumme malikel mulki tu\'til mulke men teşau ve tenziul mulke mimmen teşa\', ve tuizzu men teşau ve tuzillu men teşa\', bi yedikel hayr, inneke ala kulli şey\'in kadir.', 'De ki: \"Ey mülkün[1] sahibi Allah\'ım! Sen mülkü hak edene[2] verirsin,  mülkü hak edenden[2] çekip alırsın. Hak edeni[2] aziz,  hak edeni[2] zelil edersin. Hayır, [3] senin elindedir. Kuşkusuz Sen Her Şeye Güç Yetiren\'sin.\"', 'قل اللهم ملك الملك توتي الملك من تشا وتنزع الملك ممن تشا وتعز من تشا وتذل من تشا بيدك الخير انك علي كل شي قدير'),
(320, 3, 27, 'تُولِجُ الَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي الَّيْلِۘ وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّۘ وَتَرْزُقُ مَنْ تَشَٓاءُ بِغَيْرِ حِسَابٍ', 'Tulicul leyle fin nehari ve tulicun nehara fil leyl, ve tuhricul hayya minel meyyiti ve tuhricul meyyite minel hayy, ve terzuku men teşau bi gayri hısab.', '\"Geceyi gündüze dönüştürür,  gündüzü de geceye dönüştürürsün. Diriyi,  ölüden çıkarırsın,  ölüyü de diriden çıkarırsın. Hak edene hesapsız rızık verirsin.\"', 'تولج اليل في النهار وتولج النهار في اليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشا بغير حساب'),
(321, 3, 28, 'لَا يَتَّخِذِ الْمُؤْمِنُونَ الْكَافِر۪ينَ اَوْلِيَٓاءَ مِنْ دُونِ الْمُؤْمِن۪ينَۚ وَمَنْ يَفْعَلْ ذٰلِكَ فَلَيْسَ مِنَ اللّٰهِ ف۪ي شَيْءٍ اِلَّٓا اَنْ تَتَّقُوا مِنْهُمْ تُقٰيةًۜ وَيُحَذِّرُكُمُ اللّٰهُ نَفْسَهُۜ وَاِلَى اللّٰهِ الْمَص۪يرُ', 'La yettehizil mu\'minunel kafirine evliyae min dunil mu\'minin, ve men yef\'al zalike fe leyse minallahi fi şey\'in illa en tetteku minhum tukata, ve yuhazzirukumullahu nefseh, ve ilallahil masir.', 'Mü\'minler,  Mü\'minleri bırakıp da Kafirleri evliya[1] edinmesinler. Kafirleri evliya edinenin,  Allah\'la bir bağı kalmaz. Ancak onlardan korunmanız başka. Allah,  sizi,  kendisine karşı gelmekten sakındırır. Dönüşünüz yalnızca Allah\'adır.', 'لا يتخذ المومنون الكفرين اوليا من دون المومنين ومن يفعل ذلك فليس من الله في شي الا ان تتقوا منهم تقية ويحذركم الله نفسه والي الله المصير'),
(322, 3, 29, 'قُلْ اِنْ تُخْفُوا مَا ف۪ي صُدُورِكُمْ اَوْ تُبْدُوهُ يَعْلَمْهُ اللّٰهُۜ وَيَعْلَمُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Kul in tuhfu ma fi sudurikum ev tubduhu ya\'lemhullah, ve ya\'lemu ma fis semavati ve ma fil ard, vallahu ala kulli şey\'in kadir.', 'De ki: \"İçinizdekini gizleseniz de açığa vursanız da Allah onu bilir. O,  yerde ve gökte olan her şeyi bilir. Kuşkusuz,  Allah Her Şeye Güç Yetiren\'dir.\"', 'قل ان تخفوا ما في صدوركم او تبدوه يعلمه الله ويعلم ما في السموت وما في الارض والله علي كل شي قدير'),
(323, 3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَا عَمِلَتْ مِنْ خَيْرٍ مُحْضَراًۚۛ وَمَا عَمِلَتْ مِنْ سُٓوءٍۚۛ تَوَدُّ لَوْ اَنَّ بَيْنَهَا وَبَيْنَهُٓ اَمَداً بَع۪يداًۜ وَيُحَذِّرُكُمُ اللّٰهُ نَفْسَهُۜ وَاللّٰهُ رَؤُ۫فٌ بِالْعِبَادِ۟', 'Yevme tecidu kullu nefsin ma amilet min hayrin muhdaran, ve ma amilet min su\', teveddu lev enne beyneha ve beynehu emeden baida, ve yuhazzirukumullahu nefseh, vallahu raufun bil ıbad.', 'O gün herkes,  iyilik ve kötülük olarak ne yaptıysa onu karşısında bulur. Yaptığı kötülükle kendi arasında uzak bir mesafe bulunmasını ister. Allah,  sizin kendisine karşı gelmekten sakınmanızı ister. Allah,  kullarına karşı Çok Şefkatli\'dir.', 'يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سو تود لو ان بينها وبينه امدا بعيدا ويحذركم الله نفسه والله روف بالعباد'),
(324, 3, 31, 'قُلْ اِنْ كُنْتُمْ تُحِبُّونَ اللّٰهَ فَاتَّبِعُون۪ي يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْۜ  وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Kul in kuntum tuhibbunallahe fettebiuni yuhbibkumullahu ve yagfir lekum zunubekum, vallahu gafurun rahim.', 'De ki: \"Eğer Allah\'ı seviyorsanız,  bana uyun ki Allah da sizi sevsin ve suçlarınızı bağışlasın. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم'),
(325, 3, 32, 'قُلْ اَط۪يعُوا اللّٰهَ وَالرَّسُولَۚ فَاِنْ تَوَلَّوْا فَاِنَّ اللّٰهَ لَا يُحِبُّ الْكَافِر۪ينَ', 'Kul etiullahe ver resul, fe in tevellev fe innallahe la yuhibbul kafirin.', 'De ki: \"Allah\'a ve Resul\'e itaat edin.\"[1] Eğer yüz çevirirlerse,  kuşkusuz,  Allah,  Kafirleri sevmez.', 'قل اطيعوا الله والرسول فان تولوا فان الله لا يحب الكفرين'),
(326, 3, 33, 'اِنَّ اللّٰهَ اصْطَفٰٓى اٰدَمَ وَنُوحاً وَاٰلَ اِبْرٰه۪يمَ وَاٰلَ عِمْرٰنَ عَلَى الْعَالَم۪ينَۙ', 'İnnallahestafa ademe ve nuhan ve ale ibrahime ve ale imrane alel alemin.', 'Allah,  Âdem\'i,  Nuh\'u,  İbrahim Soyunu ve İmran Soyunu insanların üzerine seçti.', 'ان الله اصطفي ادم ونوحا وال ابرهيم وال عمرن علي العلمين'),
(327, 3, 34, 'ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌۚ', 'Zurriyyeten ba\'duha min ba\'d, vallahu semiun alim.', 'Onlar,  birbirlerinden türemiş bir soydur. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'ذرية بعضها من بعض والله سميع عليم'),
(328, 3, 35, 'اِذْ قَالَتِ امْرَاَتُ عِمْرٰنَ رَبِّ اِنّ۪ي نَذَرْتُ لَكَ مَا ف۪ي بَطْن۪ي مُحَرَّراً فَتَقَبَّلْ مِنّ۪يۚ اِنَّكَ اَنْتَ السَّم۪يعُ الْعَل۪يمُ', 'İz kalet imraetu ımrane rabbi inni nezertu leke ma fi batni muharraran fe tekabbel minni, inneke entes semiul alim.', 'Hani,  bir zaman İmran\'ın hanımı: \"Rabbim! Karnımdaki hür bırakılmış olanı sana adadım. Benden kabul et. Kuşkusuz,  Sen Her Şeyi Duyan\'sın,  Her Şeyi Bilen\'sin.\" demişti.', 'اذ قالت امرات عمرن رب اني نذرت لك ما في بطني محررا فتقبل مني انك انت السميع العليم'),
(329, 3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ اِنّ۪ي وَضَعْتُهَٓا اُنْثٰىۜ وَاللّٰهُ اَعْلَمُ بِمَا وَضَعَتْۜ وَلَيْسَ الذَّكَرُ كَالْاُنْثٰىۚ وَاِنّ۪ي سَمَّيْتُهَا مَرْيَمَ وَاِنّ۪ٓي اُع۪يذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ الشَّيْطَانِ الرَّج۪يمِ', 'Fe lemma vadaatha kalet rabbi inni vada\'tuha unsa vallahu a\'lemu bi ma vadaat ve leysez zekeru kel unsa, ve inni semmeytuha meryeme ve inni uizuha bike ve zurriyyeteha mineş şeytanir racim.', 'Onu doğurunca: \"Rabbim! Ben onu kız olarak doğurdum.\" Zaten Allah onun ne doğurduğunu daha iyi biliyordu. Erkek kız gibi değildir. İsmini,  Meryem koydum. Onu ve soyunu,  kovulmuş şeytana[1] karşı Sen\'in himayene bırakıyorum.\" dedi.', 'فلما وضعتها قالت رب اني وضعتها انثي والله اعلم بما وضعت وليس الذكر كالانثي واني سميتها مريم واني اعيذها بك وذريتها من الشيطن الرجيم'),
(330, 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَاَنْبَتَهَا نَبَاتاً حَسَناًۙ وَكَفَّلَهَا زَكَرِيَّاۜ  كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا الْمِحْرَابَۙ وَجَدَ عِنْدَهَا رِزْقاًۚ قَالَ يَا مَرْيَمُ اَنّٰى لَكِ هٰذَاۜ قَالَتْ هُوَ مِنْ عِنْدِ اللّٰهِۜ اِنَّ اللّٰهَ يَرْزُقُ مَنْ يَشَٓاءُ بِغَيْرِ حِسَابٍ', 'Fe tekabbeleha rabbuha bi kabulin hasenin ve enbeteha nebaten hasenen, ve keffeleha zekeriyya kullema dehale aleyha zekeriyyal mihrabe, vecede indeha rızka, kale ya meryemu enna leki haza kalet huve min indillah, innallahe yerzuku men yeşau bi gayri hısab.', 'Bunun üzerine Rabb\'i onu iyi bir şekilde kabul etti. Ve onu iyi bir şekilde yetiştirdi. Onu,  Zekeriya\'nın korumasına verdi. Zekeriya ne zaman mihraba[1] girse,  onun yanında yiyecek bir şey bulurdu. \"Ey Meryem! Bunlar sana nereden geldi?\" derdi. O da \"Bunlar,  Allah\'tandır.\"[2] derdi. Kuşkusuz,  Allah,  hak edeni, [3] hesapsız olarak rızıklandırır.', 'فتقبلها ربها بقبول حسن وانبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يمريم اني لك هذا قالت هو من عند الله ان الله يرزق من يشا بغير حساب'),
(331, 3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۚ قَالَ رَبِّ هَبْ ل۪ي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةًۚ اِنَّكَ سَم۪يعُ الدُّعَٓاءِ', 'Hunalike dea zekeriyya rabbeh, kale rabbi hebli min ledunke zurriyyeten tayyibeh, inneke semiud dua\'.', 'Orada Zekeriya,  Rabb\'ine dua etti: \"Rabb\'im! Bana katından iyi bir nesil bağışla. Kuşkusuz,  Sen duayı işitensin.\"', 'هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة انك سميع الدعا'),
(332, 3, 39, 'فَنَادَتْهُ الْمَلٰٓئِكَةُ وَهُوَ قَٓائِمٌ يُصَلّ۪ي فِي الْمِحْرَابِۙ اَنَّ اللّٰهَ يُبَشِّرُكَ بِيَحْيٰى مُصَدِّقاً بِكَلِمَةٍ مِنَ اللّٰهِ وَسَيِّداً وَحَصُوراً وَنَبِياًّ مِنَ الصَّالِح۪ينَ', 'Fe nadethul melaiketu ve huve kaimun yusalli fil mihrabi, ennallahe yubeşşiruke bi yahya musaddikan bi kelimetin minallahi ve seyyiden ve hasuran ve nebiyyen mines salihin.', 'O[1],  mihrapta salat[2] ederken,  melekler: \" Kuşkusuz Allah,  seni Yahya ile müjdeliyor. O,  Allah\'tan gelen kelimeyi tasdik eden,  toplumuna öncülük yapan,  kendisine sahip olan,  iyilerden bir nebi olacak.\" diye seslendiler.', 'فنادته المليكة وهو قايم يصلي في المحراب ان الله يبشرك بيحيي مصدقا بكلمة من الله وسيدا وحصورا ونبيا من الصلحين'),
(333, 3, 40, 'قَالَ رَبِّ اَنّٰى يَكُونُ ل۪ي غُلَامٌ وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَاَت۪ي عَاقِرٌۜ قَالَ كَذٰلِكَ اللّٰهُ يَفْعَلُ مَا يَشَٓاءُ', 'Kale rabbi enna yekunu li gulamun ve kad beleganiyel kiberu vemraeti akir, kale kezalikellahu yef\'alu ma yeşa\'.', '\"Ey Rabb\'im! Ben iyice yaşlanmışken,  hanımım da çocuktan kesilmişken,  benim nasıl çocuğum olabilir!\" dedi. O da: \"Pek ala olur,  Allah dilediğini yapar.\" dedi.', 'قال رب اني يكون لي غلم وقد بلغني الكبر وامراتي عاقر قال كذلك الله يفعل ما يشا'),
(334, 3, 41, 'قَالَ رَبِّ اجْعَلْ ل۪ٓي اٰيَةًۜ قَالَ اٰيَتُكَ اَلَّا تُكَلِّمَ النَّاسَ ثَلٰثَةَ اَيَّامٍ اِلَّا رَمْزاًۜ وَاذْكُرْ رَبَّكَ كَث۪يراً وَسَبِّـحْ بِالْعَشِيِّ وَالْاِبْكَارِ۟', 'Kale rabbic\'al li ayeh, kale ayetuke ella tukellimen nase selasete eyyamin illa remza, vezkur rabbeke kesiran ve sebbih bil aşiyyi vel ibkar.', 'Ey Rabb\'im! Bana,  bir ayet yap[1],  dedi. O da: \"Bunun ayeti,  işaret dili dışında insanlarla üç gün konuşmayacak olmandır.[2] Rabb\'ini çokça an,  O\'nu sabah akşam[3] tesbih[4] et.\" dedi.', 'قال رب اجعل لي اية قال ايتك الا تكلم الناس ثلثة ايام الا رمزا واذكر ربك كثيرا وسبح بالعشي والابكر'),
(335, 3, 42, 'وَاِذْ قَالَتِ الْمَلٰٓئِكَةُ يَا مَرْيَمُ اِنَّ اللّٰهَ اصْطَفٰيكِ وَطَهَّرَكِ وَاصْطَفٰيكِ عَلٰى نِسَٓاءِ الْعَالَم۪ينَ', 'Ve iz kaletil melaiketu ya meryemu innallahastafaki ve tahhareki vestafaki ala nisail alemin.', 'Hani melekler: \"Ey Meryem! Allah,  seni seçti,  arındırdı ve seni bütün dünya kadınlarına tercih etti.\" demişti.', 'واذ قالت المليكة يمريم ان الله اصطفيك وطهرك واصطفيك علي نسا العلمين'),
(336, 3, 43, 'يَا مَرْيَمُ اقْنُت۪ي لِرَبِّكِ وَاسْجُد۪ي وَارْكَع۪ي مَعَ الرَّاكِع۪ينَ', 'Ya meryemuknuti li rabbiki vescudi verkai mear rakiin.', '\"Ey Meryem! Rabb\'ine içtenlikle bağlan,  secde et[1] ve ruku[2] edenlerle birlikte ruku et.\"', 'يمريم اقنتي لربك واسجدي واركعي مع الركعين'),
(337, 3, 44, 'ذٰلِكَ مِنْ اَنْـبَٓاءِ الْغَيْبِ نُوح۪يهِ اِلَيْكَۜ وَمَا كُنْتَ لَدَيْهِمْ اِذْ يُلْقُونَ اَقْلَامَهُمْ اَيُّهُمْ يَكْفُلُ مَرْيَمَۖ وَمَا كُنْتَ لَدَيْهِمْ اِذْ يَخْتَصِمُونَ', 'Zalike min enbail gaybi nuhihi ileyk, ve ma kunte ledeyhim iz yulkune eklamehum eyyuhum yekfulu meryeme, ve ma kunte ledeyhim iz yahtesımun.', 'İşte bunlar,  sana vahiy ile bildirdiğimiz gayba ait bilgilerdir. Meryem\'i kim himaye edecek diye kalemlerini attıkları[1] zaman da çekiştikleri zaman da sen yanlarında değildin.', 'ذلك من انبا الغيب نوحيه اليك وما كنت لديهم اذ يلقون اقلمهم ايهم يكفل مريم وما كنت لديهم اذ يختصمون'),
(338, 3, 45, 'اِذْ قَالَتِ الْمَلٰٓئِكَةُ يَا مَرْيَمُ اِنَّ اللّٰهَ يُبَشِّرُكِ بِكَلِمَةٍ مِنْهُۗ اِسْمُهُ الْمَس۪يحُ ع۪يسَى ابْنُ مَرْيَمَ وَج۪يهاً فِي الدُّنْيَا وَالْاٰخِرَةِ وَمِنَ الْمُقَرَّب۪ينَۙ', 'İz kaletil melaiketu ya meryemu innallahe yubeşşiruki bi kelimetin minh, ismuhul mesihu isebnu meryeme vecihan fid dunya vel ahıreti ve minel mukarrebin.', 'Hani melekler: \"Ey Meryem! Allah,  Kendi tarafından bir kelime[1] ile seni müjdeliyor: İsmi Mesih,  Meryem Oğlu İsa\'dır. Dünyada da ahirette de şeref sahibi,  Allah\'a çok yakın olanlardandır.\" dediler.', 'اذ قالت المليكة يمريم ان الله يبشرك بكلمة منه اسمه المسيح عيسي ابن مريم وجيها في الدنيا والاخرة ومن المقربين'),
(339, 3, 46, 'وَيُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلاً وَمِنَ الصَّالِح۪ينَ', 'Ve yukellimun nase fil mehdi ve kehlen ve mines salihin.', '\"O,  beşikte de[1] yetişkinliğinde de insanlarla konuşacak. O,  salihlerden[2] olacaktır.\"', 'ويكلم الناس في المهد وكهلا ومن الصلحين'),
(340, 3, 47, 'قَالَتْ رَبِّ اَنّٰى يَكُونُ ل۪ي وَلَدٌ وَلَمْ يَمْسَسْن۪ي بَشَرٌۜ قَالَ كَذٰلِكِ اللّٰهُ يَخْلُقُ مَا يَشَٓاءُۜ اِذَا قَضٰٓى اَمْراً فَاِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ', 'Kalet rabbi enna yekunu li veledun ve lem yemsesni beşer, kale kezalikillahu yahluku ma yeşa\' iza kada emren fe innema yekulu lehu kun fe yekun.', '\"Rabb\'im! Bana hiçbir beşer dokunmamışken,  benim nasıl bir çocuğum olabilir?\" dedi. Allah: \"Öyle de olsa,  Allah neyi dilerse onu yaratır.\" dedi. O,  bir şeyin olmasına karar verdiği zaman ona sadece \"ol\" der,  o da oluverir.', 'قالت رب اني يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشا اذا قضي امرا فانما يقول له كن فيكون'),
(341, 3, 48, 'وَيُعَلِّمُهُ الْكِتَابَ وَالْحِكْمَةَ وَالتَّوْرٰيةَ وَالْاِنْج۪يلَۚ', 'Ve yuallimuhul kitabe vel hikmete vet tevrate vel incil.', 'Allah,  Ona Kitap\'ı,  Hikmet\'i,  Tevrat\'ı ve İncil\'i öğretecek;', 'ويعلمه الكتب والحكمة والتورية والانجيل'),
(342, 3, 49, 'وَرَسُولاً اِلٰى بَن۪ٓي اِسْرَٓائ۪لَ اَنّ۪ي قَدْ جِئْتُكُمْ بِاٰيَةٍ مِنْ رَبِّكُمْۙ اَنّ۪ٓي اَخْلُقُ لَكُمْ مِنَ الطّ۪ينِ كَهَيْـَٔةِ الطَّيْرِ فَاَنْفُخُ ف۪يهِ فَيَكُونُ طَيْراً بِاِذْنِ اللّٰهِۚ وَاُبْرِئُ الْاَكْمَهَ وَالْاَبْرَصَ وَاُحْـيِ الْمَوْتٰى بِاِذْنِ اللّٰهِۚ وَاُنَبِّئُكُمْ بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَۙ ف۪ي بُيُوتِكُمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لَكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَۚ', 'Ve resulen ila beni israile enni kad ci\'tukum bi ayetin min rabbikum, enni ehluku lekum minet tini ke heyetit tayri fe enfuhu fihi fe yekunu tayran bi iznillah, ve ubriul ekmehe vel ebrasa ve uhyil mevta bi iznillah, ve unebbiukum bi ma te\'kulune ve ma teddehırune, fi buyutikum inne fi zalike le ayeten lekum in kuntum mu\'minin.', 'Bir resul[1] olarak İsrailoğulları\'na: \"Doğrusu size Rabb\'inizden bir ayetle[2] geldim. Sizin için çamurdan kuş şeklinde bir şey yaratırım. Ona üflerim,  Allah\'ın izniyle[3] hemen kuş oluverir. Körü ve alacalıyı iyileştiririm. Allah\'ın izni[4] ile ölüleri diriltirim. Evlerinizde ne yediğinizi ne biriktirdiğinizi size haber veririm. Eğer mümin iseniz kuşkusuz bunda sizin için bir ayet[2] vardır.\"', 'ورسولا الي بني اسريل اني قد جيتكم باية من ربكم اني اخلق لكم من الطين كهية الطير فانفخ فيه فيكون طيرا باذن الله وابري الاكمه والابرص واحي الموتي باذن الله وانبيكم بما تاكلون وما تدخرون في بيوتكم ان في ذلك لاية لكم ان كنتم مومنين'),
(343, 3, 50, 'وَمُصَدِّقاً لِمَا بَيْنَ يَدَيَّ مِنَ التَّوْرٰيةِ وَلِاُحِلَّ لَكُمْ بَعْضَ الَّذ۪ي حُرِّمَ عَلَيْكُمْ وَجِئْتُكُمْ بِاٰيَةٍ مِنْ رَبِّكُمْ فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِ', 'Ve musaddikan lima beyne yedeyye minet tevrati ve li uhılle lekum ba\'dallezi hurrime aleykum ve ci\'tukum bi ayetin min rabbikum fettekullahe ve etiun.', '\"Ben,  size Rabb\'inizden,  elinizin altında bulunan Tevrat\'ı tasdik edici olarak ve daha önce size haram kılınmış bazı şeyleri helal kılmak için bir ayetle[1] geldim. Allah\'a karşı takvalı[2] olun ve bana itaat edin.\"', 'ومصدقا لما بين يدي من التورية ولاحل لكم بعض الذي حرم عليكم وجيتكم باية من ربكم فاتقوا الله واطيعون'),
(344, 3, 51, 'اِنَّ اللّٰهَ رَبّ۪ي وَرَبُّكُمْ فَاعْبُدُوهُۜ هٰذَا صِرَاطٌ مُسْتَق۪يمٌ', 'İnnallahe rabbi ve rabbikum fa\'buduh, haza sıratun mustakim.', '\"Allah,  benim de Rabb\'im,  sizin de Rabb\'inizdir. O halde O\'na kulluk edin. Doğru yol budur.\"', 'ان الله ربي وربكم فاعبدوه هذا صرط مستقيم'),
(345, 3, 52, 'فَلَمَّٓا اَحَسَّ ع۪يسٰى مِنْهُمُ الْكُفْرَ قَالَ مَنْ اَنْصَار۪ٓي اِلَى اللّٰهِۜ قَالَ الْحَوَارِيُّونَ نَحْنُ اَنْصَارُ اللّٰهِۚ اٰمَنَّا بِاللّٰهِۚ وَاشْهَدْ بِاَنَّا مُسْلِمُونَ', 'Fe lemma ehassa isa min humul kufre kale men ensari ilallah, kalel havariyyune nahnu ensarullah, amenna billah, veşhed bi enna muslimun.', 'İsa,  onların küfrünü sezince: \"Bana,  Allah yolunda kim yardımcı olacak?\" dedi. Havariler: \"Biz Allah\'ın yardımcılarıyız,  Allah\'a iman ettik,  bizim Müslümanlığımıza şahit ol.\" dediler.', 'فلما احس عيسي منهم الكفر قال من انصاري الي الله قال الحواريون نحن انصار الله امنا بالله واشهد بانا مسلمون'),
(346, 3, 53, 'رَبَّنَٓا اٰمَنَّا بِمَٓا اَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِد۪ينَ', 'Rabbena amenna bi ma enzelte vetteba\'nar resule fektubna meaş şahidin.', '\"Ey Rabb\'imiz! İndirdiğine iman ettik,  resulüne tabi olduk. Öyleyse bizi tanıklarla birlikte yaz.\"', 'ربنا امنا بما انزلت واتبعنا الرسول فاكتبنا مع الشهدين'),
(347, 3, 54, 'وَمَكَرُوا وَمَكَرَ اللّٰهُۜ وَاللّٰهُ خَيْرُ الْمَاكِر۪ينَ۟', 'Ve mekeru ve mekarallah, vallahu hayrul makirin.', 'Onlar,  plan yaptılar. Allah da plan yaptı. Allah,  en iyi plan yapandır.', 'ومكروا ومكر الله والله خير المكرين'),
(348, 3, 55, 'اِذْ قَالَ اللّٰهُ يَا ع۪يسٰٓى اِنّ۪ي مُتَوَفّ۪يكَ وَرَافِعُكَ اِلَيَّ وَمُطَهِّرُكَ مِنَ الَّذ۪ينَ كَفَرُوا وَجَاعِلُ الَّذ۪ينَ اتَّبَعُوكَ فَوْقَ الَّذ۪ينَ كَفَرُٓوا اِلٰى يَوْمِ الْقِيٰمَةِۚ ثُمَّ اِلَيَّ مَرْجِعُكُمْ فَاَحْكُمُ بَيْنَكُمْ ف۪يمَا كُنْتُمْ ف۪يهِ تَخْتَلِفُونَ', 'İz kalellahu ya isa inni muteveffike ve rafiuke ileyye ve mutahhiruke minellezine keferu ve cailullezinettebeuke fevkallezine keferu ila yevmil kıyameh, summe ileyye merciukum fe ahkumu beynekum fima kuntum fihi tahtelifun.', 'Hani,  Allah,  İsa\'ya: \"Ey İsa! Seni öldürecek olan Ben\'im. Seni Bana yükselteceğim. Seni Kafirlerden[1] arındıracağım. Sana tabi olanları da Kıyamet Günü\'ne kadar küfredenlerden[1] üstün tutacağım. Sonra dönüşünüz yalnız Bana olacak; anlaşmazlığa düştüğünüz konular hakkında hükmü Ben vereceğim.\" dedi.', 'اذ قال الله يعيسي اني متوفيك ورافعك الي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا الي يوم القيمة ثم الي مرجعكم فاحكم بينكم فيما كنتم فيه تختلفون'),
(349, 3, 56, 'فَاَمَّا الَّذ۪ينَ كَفَرُوا فَاُعَذِّبُهُمْ عَذَاباً شَد۪يداً فِي الدُّنْيَا وَالْاٰخِرَةِۘ وَمَا لَهُمْ مِنْ نَاصِر۪ينَ', 'Fe emmellezine keferu fe uazzibuhum azaben şediden fid dunya vel ahıreti, ve ma lehum min nasirin.', '\"Kafirlere gelince: Onları dünyada da ahirette de şiddetli bir azaba çarptıracağım. Ve onların yardımcıları da olmayacaktır.\"', 'فاما الذين كفروا فاعذبهم عذابا شديدا في الدنيا والاخرة وما لهم من نصرين'),
(350, 3, 57, 'وَاَمَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفّ۪يهِمْ اُجُورَهُمْۜ  وَاللّٰهُ لَا يُحِبُّ الظَّالِم۪ينَ', 'Ve emmellezine amenu ve amilus salihati fe yuveffihim ucurehum vallahu la yuhibbuz zalimin.', 'İman edip salihatı[1] yapanlara gelince: Allah,  yaptıklarının karşılığını eksiksiz verecektir. Allah,  haksızlık yapanları sevmez.', 'واما الذين امنوا وعملوا الصلحت فيوفيهم اجورهم والله لا يحب الظلمين'),
(351, 3, 58, 'ذٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ الْاٰيَاتِ وَالذِّكْرِ الْحَك۪يمِ', 'Zalike netluhu aleyke minel ayati vez zikril hakim hakimi).', 'Bu sana anlattıklarımız,  ayetlerden ve hakim[1] olan Zikir\'dendir[2].', 'ذلك نتلوه عليك من الايت والذكر الحكيم'),
(352, 3, 59, 'اِنَّ مَثَلَ ع۪يسٰى عِنْدَ اللّٰهِ كَمَثَلِ اٰدَمَۜ خَلَقَهُ مِنْ تُرَابٍ ثُمَّ قَالَ لَهُ كُنْ فَيَكُونُ', 'İnne mesele isa indallahi ke meseli adem, halakahu min turabin summe kale lehu kun fe yekun.', 'İsa\'nın durumu[1] Allah\'ın yanında Âdem\'in durumu gibidir. Onu topraktan yarattı,  sonra ona \"Ol!\" dedi o da oluverdi.', 'ان مثل عيسي عند الله كمثل ادم خلقه من تراب ثم قال له كن فيكون'),
(353, 3, 60, 'اَلْحَقُّ مِنْ رَبِّكَ فَلَا تَكُنْ مِنَ الْمُمْتَر۪ينَ', 'El hakku min rabbike fe la tekun minel mumterin.', 'Hakk,  Rabb\'indendir. Sakın kuşku duyanlardan olma.', 'الحق من ربك فلا تكن من الممترين'),
(354, 3, 61, 'فَمَنْ حَٓاجَّكَ ف۪يهِ مِنْ بَعْدِ مَا جَٓاءَكَ مِنَ الْعِلْمِ فَقُلْ تَعَالَوْا نَدْعُ اَبْنَٓاءَنَا وَاَبْنَٓاءَكُمْ وَنِسَٓاءَنَا وَنِسَٓاءَكُمْ وَاَنْفُسَنَا وَاَنْفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَلْ لَعْنَتَ اللّٰهِ عَلَى الْكَاذِب۪ينَ', 'Fe men hacceke fihi min ba\'di ma caeke minel ilmi fe kul tealev ned\'u ebnaena ve ebnaekum ve nisaena ve nisaekum ve enfusena ve enfusekum summe nebtehil fe nec\'al la\'netallahi alel kazibin.', 'Sana gelen ilimden[1] sonra,  her kim seninle tartışmaya girerse,  onlara de ki: \"Gelin çocuklarımızı ve çocuklarınızı,  kadınlarımızı ve kadınlarınızı,  kendimizi ve kendinizi[2] çağıralım; sonra da içtenlikle Allah\'ın lanetinin yalancıların üzerine olmasını dileyelim.', 'فمن حاجك فيه من بعد ما جاك من العلم فقل تعالوا ندع ابنانا وابناكم ونسانا ونساكم وانفسنا وانفسكم ثم نبتهل فنجعل لعنت الله علي الكذبين'),
(355, 3, 62, 'اِنَّ هٰذَا لَهُوَ الْقَصَصُ الْحَقُّۚ وَمَا مِنْ اِلٰهٍ اِلَّا اللّٰهُۜ وَاِنَّ اللّٰهَ لَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'İnne haza le huvel kasasul hakk, ve ma min ilahin illallah, ve innellahe le huvel azizul hakim.', 'Bunlar,  gerçeğin haberleridir. Allah\'tan başka ilah yoktur. Kuşkusuz,  Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ان هذا لهو القصص الحق وما من اله الا الله وان الله لهو العزيز الحكيم'),
(356, 3, 63, 'فَاِنْ تَوَلَّوْا فَاِنَّ اللّٰهَ عَل۪يمٌ بِالْمُفْسِد۪ينَ۟', 'Fe in tevellev fe innallahe alimun bil mufsidin.', 'Eğer yüz çevirirlerse,  Allah,  kimlerin bozguncu olduğunu bilir.', 'فان تولوا فان الله عليم بالمفسدين'),
(357, 3, 64, 'قُلْ يَٓا اَهْلَ الْكِتَابِ تَعَالَوْا اِلٰى كَلِمَةٍ سَوَٓاءٍ بَيْنَنَا وَبَيْنَكُمْ اَلَّا نَعْبُدَ اِلَّا اللّٰهَ وَلَا نُشْرِكَ بِه۪ شَيْـٔاً وَلَا يَتَّخِذَ بَعْضُنَا بَعْضاً اَرْبَاباً مِنْ دُونِ اللّٰهِۜ فَاِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِاَنَّا مُسْلِمُونَ', 'Kul ya ehlel kitabi tealev ila kelimetin sevain beynena ve beynekum ella na\'bude illallahe ve la nuşrike bihi şey\'en ve la yettehize ba\'duna ba\'den erbaben min dunillah, fe in tevellev fe kuluşhedu bi enna muslimun.', 'De ki: \"Ey Kitap Ehli! Gelin aramızda ortak olan bir kelimede anlaşalım: Allah\'tan başka hiçbir şeye kulluk etmeyelim,  O\'na hiçbir şeyi şirk koşmayalım ve Allah\'ın yanı sıra kimimiz kimimizi rabler edinmeyelim.\" Eğer yüz çevirirlerse deyin ki: \"Tanık olun,  biz gerçek Müslim olanlarız.\"', 'قل ياهل الكتب تعالوا الي كلمة سوا بيننا وبينكم الا نعبد الا الله ولا نشرك به شيا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون'),
(358, 3, 65, 'يَٓا اَهْلَ الْكِتَابِ لِمَ تُحَٓاجُّونَ ف۪ٓي اِبْرٰه۪يمَ وَمَٓا اُنْزِلَتِ التَّوْرٰيةُ وَالْاِنْج۪يلُ اِلَّا مِنْ بَعْدِه۪ۜ اَفَلَا تَعْقِلُونَ', 'Ya ehlel kitabi lime tuhaccune fi ibrahime ve ma unziletit tevratu vel incilu illa min ba\'dih, e fe la ta\'kılun.', 'Ey Kitap Ehli! İbrahim hakkında niçin tartışıyorsunuz? Oysaki Tevrat da İncil de ondan sonra indirildi. Hala akletmiyor musunuz?', 'ياهل الكتب لم تحاجون في ابرهيم وما انزلت التورية والانجيل الا من بعده افلا تعقلون'),
(359, 3, 66, 'هَٓا اَنْتُمْ هٰٓؤُ۬لَٓاءِ حَاجَجْتُمْ ف۪يمَا لَكُمْ بِه۪ عِلْمٌ فَلِمَ تُحَٓاجُّونَ ف۪يمَا لَيْسَ لَكُمْ بِه۪ عِلْمٌۜ وَاللّٰهُ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُونَ', 'Ha entum haulai hacectum fi ma lekum bihi ilmun fe lime tuhaccune fi ma leyse lekum bihi ilm, vallahu ya\'lemu ve entum la ta\'lemun.', 'Diyelim ki bildiğiniz şeyler hakkında tartıştınız. Peki,  hiçbir bilginiz olmayan konularda ne diye tartışıyorsunuz? Allah bilir,  siz bilmezsiniz.', 'هانتم هولا حججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وانتم لا تعلمون'),
(360, 3, 67, 'مَا كَانَ اِبْرٰه۪يمُ يَهُودِياًّ وَلَا نَصْرَانِياًّ وَلٰكِنْ كَانَ حَن۪يفاً مُسْلِماًۜ وَمَا كَانَ مِنَ الْمُشْرِك۪ينَ', 'Ma kane ibrahimu yahudiyyen ve la nasraniyyen ve lakin kane hanifen muslima, ve ma kane minel muşrikin.', 'İbrahim ne Yahudi ne de Hıristiyan\'dı. O,  Allah\'ı birleyen ve O\'na teslim olandı. O,  müşriklerden değildi.', 'ما كان ابرهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين'),
(361, 3, 68, 'اِنَّ اَوْلَى النَّاسِ بِاِبْرٰه۪يمَ لَلَّذ۪ينَ اتَّبَعُوهُ وَهٰذَا النَّبِيُّ وَالَّذ۪ينَ اٰمَنُواۜ وَاللّٰهُ وَلِيُّ الْمُؤْمِن۪ينَ', 'İnne evlen nasi bi ibrahime lellezinettebeuhu ve hazan nebiyyu vellezine amenu vallahu veliyyul mu\'minin.', 'İnsanların İbrahim\'e en yakın olanları ona tabi olanlar,  bu Nebi[1] ve iman edenlerdir. Allah,  Mü\'minlerin velisidir.[2]', 'ان اولي الناس بابرهيم للذين اتبعوه وهذا النبي والذين امنوا والله ولي المومنين'),
(362, 3, 69, 'وَدَّتْ طَٓائِفَةٌ مِنْ اَهْلِ الْكِتَابِ لَوْ يُضِلُّونَكُمْۜ وَمَا يُضِلُّونَ اِلَّٓا اَنْفُسَهُمْ وَمَا يَشْعُرُونَ', 'Veddet taifetun min ehlil kitabi lev yudillunekum ve ma yudıllune illa enfusehum ve ma yeş\'urun.', 'Ehli Kitap\'tan bazı kimseler,  sizi yolunuzdan saptırmak ister. Onlar,  ancak kendilerini saptırıyorlar. Fakat bunu idrak edemiyorlar.', 'ودت طايفة من اهل الكتب لو يضلونكم وما يضلون الا انفسهم وما يشعرون'),
(363, 3, 70, 'يَٓا اَهْلَ الْكِتَابِ لِمَ تَكْفُرُونَ بِاٰيَاتِ اللّٰهِ وَاَنْتُمْ تَشْهَدُونَ', 'Ya ehlel kitabi lime tekfurune bi ayatillahi ve entum teşhedun.', 'Ey Kitap Ehli! Gerçeği bildiğiniz halde,  niçin Allah\'ın ayetlerini küfrediyorsunuz?', 'ياهل الكتب لم تكفرون بايت الله وانتم تشهدون'),
(364, 3, 71, 'يَٓا اَهْلَ الْكِتَابِ لِمَ تَلْبِسُونَ الْحَقَّ بِالْبَاطِلِ وَتَكْتُمُونَ الْحَقَّ وَاَنْتُمْ تَعْلَمُونَ۟', 'Ya ehlel kitabi lime telbisunel hakka bil batılı ve tektumunel hakka ve entum ta\'lemun.', 'Ey Kitap Ehli! Niçin Hakkı Batılla karıştırıyor ve bildiğiniz halde gerçeği gizliyorsunuz?', 'ياهل الكتب لم تلبسون الحق بالبطل وتكتمون الحق وانتم تعلمون'),
(365, 3, 72, 'وَقَالَتْ طَٓائِفَةٌ مِنْ اَهْلِ الْكِتَابِ اٰمِنُوا بِالَّـذ۪ٓي اُنْزِلَ عَلَى الَّذ۪ينَ اٰمَنُوا وَجْهَ النَّهَارِ وَاكْفُرُٓوا اٰخِرَهُ لَعَلَّهُمْ يَرْجِعُونَۚ', 'Ve kalet taifetun min ehlil kitabi aminu billezi unzile alellezine amenu vechen nehari vekfuru ahirahu leallehum yerciun.', 'Ehli Kitap\'tan bir grup dedi ki: \"İnananlara indirilene günün başında iman edin,  günün sonunda da küfredin.[1] Belki dinlerinden dönerler.\"', 'وقالت طايفة من اهل الكتب امنوا بالذي انزل علي الذين امنوا وجه النهار واكفروا اخره لعلهم يرجعون'),
(366, 3, 73, 'وَلَا تُؤْمِنُٓوا اِلَّا لِمَنْ تَبِـعَ د۪ينَكُمْۜ قُلْ اِنَّ الْهُدٰى هُدَى اللّٰهِۙ اَنْ يُؤْتٰٓى اَحَدٌ مِثْلَ مَٓا اُو۫ت۪يتُمْ اَوْ يُحَٓاجُّوكُمْ عِنْدَ رَبِّكُمْۜ قُلْ اِنَّ الْفَضْلَ بِيَدِ اللّٰهِۚ يُؤْت۪يهِ مَنْ يَشَٓاءُۜ وَاللّٰهُ وَاسِعٌ عَل۪يمٌۚ', 'Ve la tu\'minu illa li men tebia dinekum, kul innel huda hudallahi en yu\'ta ehadun misle ma utitum ev yuhaccukum inde rabbikum, kul innel fadla bi yedillah, yu\'tihi men yeşa\', vallahu vasiun alim.', '\"Kendi dininize tabi olanlardan başkasına inanmayın.\" dediler. De ki: \"Hidayet[1],  Allah\'ın hidayetidir. Birine,  size verilmiş olanın benzerinin verilmesinden veya Rabb\'inizin katından aleyhinize kanıt getirebileceklerinden ötürü mü böyle söylüyorsunuz.\" De ki: \"Lütuf,  Allah\'ın elindedir,  onu hak edene verir.\" Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Her Şeyi Bilen\'dir.', 'ولا تومنوا الا لمن تبع دينكم قل ان الهدي هدي الله ان يوتي احد مثل ما اوتيتم او يحاجوكم عند ربكم قل ان الفضل بيد الله يوتيه من يشا والله وسع عليم'),
(367, 3, 74, 'يَخْتَصُّ بِرَحْمَتِه۪ مَنْ يَشَٓاءُۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Yahtassu bi rahmetihi men yeşa\', vallahu zul fadlil azim.', 'Allah,  rahmetini hak edene[1] has kılar. Allah,  Büyük Lütuf Sahibi\'dir.', 'يختص برحمته من يشا والله ذو الفضل العظيم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(368, 3, 75, 'وَمِنْ اَهْلِ الْكِتَابِ مَنْ اِنْ تَأْمَنْهُ بِقِنْطَارٍ يُؤَدِّه۪ٓ اِلَيْكَۚ وَمِنْهُمْ مَنْ اِنْ تَأْمَنْهُ بِد۪ينَارٍ لَا يُؤَدِّه۪ٓ اِلَيْكَ اِلَّا مَا دُمْتَ عَلَيْهِ قَٓائِماًۜ ذٰلِكَ بِاَنَّهُمْ قَالُوا لَيْسَ عَلَيْنَا فِي الْاُمِّيّ۪نَ سَب۪يلٌۚ وَيَقُولُونَ عَلَى اللّٰهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ', 'Ve min ehlil kitabi men in te\'menhu bi kıntarin yueddihi ileyk, ve minhum men in te\'menhu bi dinarin la yueddihi ileyke illa ma dumte aleyhi kaima, zalike bi ennehum kalu leyse aleyna fil ummiyyine sebil, ve yekulune alallahil kezibe ve hum ya\'lemun.', 'Ehl-i Kitap\'tan öylesi vardır ki,  kendisine yüklerle mal emanet etsen,  onu sana eksiksiz iade eder. Öylesi de var ki bir dinar emanet etsen,  başına dikilmedikçe onu sana iade etmez. Bunun sebebi: \"Ümmilerin[1] malını yemede vebal yoktur.\" diye düşünmelerindendir. Onlar,  bile bile,  Allah adına yalan söylerler.', 'ومن اهل الكتب من ان تامنه بقنطار يوده اليك ومنهم من ان تامنه بدينار لا يوده اليك الا ما دمت عليه قايما ذلك بانهم قالوا ليس علينا في الامين سبيل ويقولون علي الله الكذب وهم يعلمون'),
(369, 3, 76, 'بَلٰى مَنْ اَوْفٰى بِعَهْدِه۪ وَاتَّقٰى فَاِنَّ اللّٰهَ يُحِبُّ الْمُتَّق۪ينَ', 'Bela men evfa bi ahdihi vetteka fe innallahe yuhibbul muttekin.', 'Hayır![1] Kim sözünü yerine getirir ve takvalı[2] olursa,  kuşkusuz Allah,  takvalı olanları sever.', 'بلي من اوفي بعهده واتقي فان الله يحب المتقين'),
(370, 3, 77, 'اِنَّ الَّذ۪ينَ يَشْتَرُونَ بِعَهْدِ اللّٰهِ وَاَيْمَانِهِمْ ثَمَناً قَل۪يلاً اُو۬لٰٓئِكَ لَا خَلَاقَ لَهُمْ فِي الْاٰخِرَةِ وَلَا يُكَلِّمُهُمُ اللّٰهُ وَلَا يَنْظُرُ اِلَيْهِمْ يَوْمَ الْقِيٰمَةِ وَلَا يُزَكّ۪يهِمْۖ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnellezine yeşterune bi ahdillahi ve eymanihim semenen kalilen ulaike la halaka lehum fil ahırati ve la yukellimuhumullahu ve la yenzuru ileyhim yevmel kıyameti ve la yuzekkihim ve lehum azabun elim.', 'Allah\'a verdikleri sözü ve yeminlerini az bir değere değiştirenler var ya; işte onlara ahirette bir pay yoktur. Allah,  onlarla Kıyamet Günü konuşmayacak,  onlara bakmayacak ve onları temize çıkarmayacaktır. Onlar için can yakıcı bir azap vardır.', 'ان الذين يشترون بعهد الله وايمنهم ثمنا قليلا اوليك لا خلق لهم في الاخرة ولا يكلمهم الله ولا ينظر اليهم يوم القيمة ولا يزكيهم ولهم عذاب اليم'),
(371, 3, 78, 'وَاِنَّ مِنْهُمْ لَفَر۪يقاً يَلْوُ۫نَ اَلْسِنَتَهُمْ بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِۚ وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللّٰهِ وَمَا هُوَ مِنْ عِنْدِ اللّٰهِۚ وَيَقُولُونَ عَلَى اللّٰهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ', 'Ve inne minhum le ferikan yelvune elsinetehum bil kitabi li tahsebuhu minel kitabi ve ma huve minel kitab, ve yekulune huve min indillahi ve ma huve min indillah, ve yekulune alallahil kezibe ve hum ya\'lemun.', 'Onlardan[1] bir kısım kimseler de Kitap\'ta olmadığı halde,  Kitap\'tan sanasınız diye Kitap\'ı dillerini eğip bükerek okurlar. Oysa o Kitap\'tan değildir. \"Bu Allah katındandır.\" diyorlar,  oysa o,  Allah\'tan değildir. Allah adına bile bile yalan söylüyorlar.', 'وان منهم لفريقا يلون السنتهم بالكتب لتحسبوه من الكتب وما هو من الكتب ويقولون هو من عند الله وما هو من عند الله ويقولون علي الله الكذب وهم يعلمون'),
(372, 3, 79, 'مَا كَانَ لِبَشَرٍ اَنْ يُؤْتِيَهُ اللّٰهُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا عِبَاداً ل۪ي مِنْ دُونِ اللّٰهِ وَلٰكِنْ كُونُوا رَبَّانِيّ۪نَ بِمَا كُنْتُمْ تُعَلِّمُونَ الْكِتَابَ وَبِمَا كُنْتُمْ تَدْرُسُونَۙ', 'Ma kane li beşerin en yu\'tiyehullahul kitabe vel hukme ven nubuvvete summe yekule lin nasi kunu ıbaden li min dunillahi ve lakin kunu rabbaniyyine bi ma kuntum tuallimunel kitabe ve bima kuntum tedrusun.', 'Allah\'ın kendisine Kitap,  Hüküm ve Nebi\'lik verdiği bir beşerin,  insanlara \"Allah\'ın yanı sıra bana da kulluk edin demesi yakışmaz. Ancak,  okuyup öğrendiğiniz Kitap\'ın gereği olarak,  \"Kulluğunuz yalnızca Rabb\'inize ait olsun.\"[1] demesi gerekir.', 'ما كان لبشر ان يوتيه الله الكتب والحكم والنبوة ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربنين بما كنتم تعلمون الكتب وبما كنتم تدرسون'),
(373, 3, 80, 'وَلَا يَأْمُرَكُمْ اَنْ تَتَّخِذُوا الْمَلٰٓئِكَةَ وَالنَّبِيّ۪نَ اَرْبَاباًۜ اَيَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ اِذْ اَنْتُمْ مُسْلِمُونَ۟', 'Ve la ye\'murekum en tettehizul melaikete ven nebiyyine erbaba, e ye\'murukum bil kufri ba\'de iz entum muslimun.', 'O,  sizden melekleri ve nebileri Rabb\'ler edinmenizi istemez. Siz,  Müslim olduktan sonra,  sizden Kafir olmanızı mı isteyecek?', 'ولا يامركم ان تتخذوا المليكة والنبين اربابا ايامركم بالكفر بعد اذ انتم مسلمون'),
(374, 3, 81, 'وَاِذْ اَخَذَ اللّٰهُ م۪يثَاقَ النَّبِيّ۪نَ لَـمَٓا اٰتَيْتُكُمْ مِنْ كِتَابٍ وَحِكْمَةٍ ثُمَّ جَٓاءَكُمْ رَسُولٌ مُصَدِّقٌ لِمَا مَعَكُمْ لَتُؤْمِنُنَّ بِه۪ وَلَتَنْصُرُنَّهُۜ قَالَ ءَاَقْرَرْتُمْ وَاَخَذْتُمْ عَلٰى ذٰلِكُمْ اِصْر۪يۜ قَالُٓوا اَقْرَرْنَاۜ قَالَ فَاشْهَدُوا وَاَنَا۬ مَعَكُمْ مِنَ الشَّاهِد۪ينَ', 'Ve iz ehazallahu misakan nebiyyine lema ateytukum min kitabin ve hikmetin summe caekum resulun musaddikun lima meakum le tu\'minunne bihi ve le tensurunneh, kale e akrartum ve ehaztum ala zalikum ısri, kalu akrarna, kale feşhedu ve ene meakum mineş şahidin.', 'Hani Allah,  Nebilerden söz almıştı:[1] \"Size,  kitap ve hikmet verdim; şimdi yanınızdakini[2] tasdik eden bir resul geldiğinde,  ona kesinlikle inanacak ve yardım edeceksiniz.\" \"Bunu kabul ettiniz mi? Bu önemli görevi üstlendiniz mi?\" demişti. \"Kabul ettik.\" dediler. Allah: \"Öyleyse tanık olun,  Ben de sizinle birlikte tanık olanlardanım.\" dedi.', 'واذ اخذ الله ميثق النبين لما اتيتكم من كتب وحكمة ثم جاكم رسول مصدق لما معكم لتومنن به ولتنصرنه قال اقررتم واخذتم علي ذلكم اصري قالوا اقررنا قال فاشهدوا وانا معكم من الشهدين'),
(375, 3, 82, 'فَمَنْ تَوَلّٰى بَعْدَ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الْفَاسِقُونَ', 'Fe men tevella ba\'de zalike fe ulaike humul fasikun.', 'Bundan sonra kim yüz çevirirse,  işte onlar fasıklardır.[1]', 'فمن تولي بعد ذلك فاوليك هم الفسقون'),
(376, 3, 83, 'اَفَغَيْرَ د۪ينِ اللّٰهِ يَبْغُونَ وَلَهُٓ اَسْلَمَ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِ طَوْعاً وَكَرْهاً وَاِلَيْهِ يُرْجَعُونَ', 'E fe gayre dinillahi yebgune ve lehu esleme men fis semavati vel ardı tav\'an ve kerhen ve ileyhi yurceun.', 'Yoksa onlar,  Allah\'ın dininden başka bir din mi arıyorlar. Oysa yerde ve gökte bulunanların tamamı isteyerek veya istemeyerek,  O\'na teslim olmuşlardır. Ve hepsi O\'na döndürüleceklerdir.', 'افغير دين الله يبغون وله اسلم من في السموت والارض طوعا وكرها واليه يرجعون'),
(377, 3, 84, 'قُلْ اٰمَنَّا بِاللّٰهِ وَمَٓا اُنْزِلَ عَلَيْنَا وَمَٓا اُنْزِلَ عَلٰٓى اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ وَاِسْحٰقَ وَيَعْقُوبَ وَالْاَسْبَاطِ وَمَٓا اُو۫تِيَ مُوسٰى وَع۪يسٰى وَالنَّبِيُّونَ مِنْ رَبِّهِمْۖ لَا نُفَرِّقُ بَيْنَ اَحَدٍ مِنْهُمْۘ وَنَحْنُ لَهُ مُسْلِمُونَ', 'Kul amenna billahi ve ma unzile aleyna ve ma unzile ala ibrahime ve ismaile ve ishaka ve ya\'kube vel esbatı ve ma utiye musa ve isa ven nebiyyune min rabbihim, la nuferriku beyne ehadin minhum, ve nahnu lehu muslimun.', 'De ki: \"Biz; Allah\'a,  bize indirilene,  İbrahim\'e,  İsmail\'e,  İshak\'a,  Yakub\'a ve onun soyundan gelenlere indirilene; Musa\'ya,  Îsa\'ya,  nebilere Rabb\'lerinden verilene iman ettik. Onları,  birbirinden ayırt etmeyiz. Biz,  O\'na teslim olanlardanız.\"', 'قل امنا بالله وما انزل علينا وما انزل علي ابرهيم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي والنبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون'),
(378, 3, 85, 'وَمَنْ يَبْتَغِ غَيْرَ الْاِسْلَامِ د۪يناً فَلَنْ يُقْبَلَ مِنْهُۚ وَهُوَ فِي الْاٰخِرَةِ مِنَ الْخَاسِر۪ينَ', 'Ve men yebtegi gayrel islami dinen fe len yukbele minh, ve huve fil ahireti minel hasirin.', 'Kim İslam\'dan başka bir din seçerse,  bilsin ki o din ondan asla kabul edilmeyecektir ve o ahirette hüsrana uğrayacaktır.', 'ومن يبتغ غير الاسلم دينا فلن يقبل منه وهو في الاخرة من الخسرين'),
(379, 3, 86, 'كَيْفَ يَهْدِي اللّٰهُ قَوْماً كَفَرُوا بَعْدَ ا۪يمَانِهِمْ وَشَهِدُٓوا اَنَّ الرَّسُولَ حَقٌّ وَجَٓاءَهُمُ الْبَيِّنَاتُۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'Keyfe yehdillahu kavmen keferu ba\'de imanihim ve şehidu enner resule hakkun ve caehumul beyyinat vallahu la yehdil kavmez zalimin.', 'İman ettikten,  Resul\'ün Hakk olduğuna tanıklık ettikten ve kendilerine apaçık kanıtlar geldikten sonra,  Kafir olan bir halka Allah nasıl doğru yolu gösterir? Allah,  zalim olan bir halka doğru yolu göstermez.', 'كيف يهدي الله قوما كفروا بعد ايمنهم وشهدوا ان الرسول حق وجاهم البينت والله لا يهدي القوم الظلمين'),
(380, 3, 87, 'اُو۬لٰٓئِكَ جَزَٓاؤُ۬هُمْ اَنَّ عَلَيْهِمْ لَعْنَةَ اللّٰهِ وَالْمَلٰٓئِكَةِ وَالنَّاسِ اَجْمَع۪ينَۙ', 'Ulaike cezauhum enne aleyhim la\'netallahi vel melaiketi ven nasi ecmain.', 'Böylelerinin cezası,  Allah\'ın,  meleklerin ve tüm insanların lanetine[1] uğramalarıdır.', 'اوليك جزاوهم ان عليهم لعنة الله والمليكة والناس اجمعين'),
(381, 3, 88, 'خَالِد۪ينَ ف۪يهَاۚ لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَۙ', 'Halidine fiha, la yuhaffefu anhumul azabu ve la hum yunzarun.', 'Onlar,  bu halde sürekli kalacaklardır. Onlardan ne azap hafifletilecek ve ne de onların yüzlerine bakılacak.', 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون'),
(382, 3, 89, 'اِلَّا الَّذ۪ينَ تَابُوا مِنْ بَعْدِ ذٰلِكَ وَاَصْلَحُوا فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İllellezine tabu min ba\'di zalike ve aslehu fe innallahe gafurun rahim.', 'Ancak,  bundan sonra tevbe[1] edip kendilerini düzeltenler hariç. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم'),
(383, 3, 90, 'اِنَّ الَّذ۪ينَ كَفَرُوا بَعْدَ ا۪يمَانِهِمْ ثُمَّ ازْدَادُوا كُفْراً لَنْ تُقْبَلَ تَوْبَتُهُمْۚ وَاُو۬لٰٓئِكَ هُمُ الضَّٓالُّونَ', 'İnnellezine keferu ba\'de imanihim summezdadu kufran len tukbele tevbetuhum, ve ulaike humud dallun.', 'İman ettikten sonra[1] kafir[2] olup ve küfürlerinde[2] ısrarcı olanların tevbeleri asla kabul edilmeyecektir. İşte onlar sapkın olanlardır.', 'ان الذين كفروا بعد ايمنهم ثم ازدادوا كفرا لن تقبل توبتهم واوليك هم الضالون'),
(384, 3, 91, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ فَلَنْ يُقْبَلَ مِنْ اَحَدِهِمْ مِلْءُ الْاَرْضِ ذَهَباً وَلَوِ افْتَدٰى بِه۪ۜ اُو۬لٰٓئِكَ لَهُمْ عَذَابٌ اَل۪يمٌ وَمَا لَهُمْ مِنْ نَاصِر۪ينَ۟', 'İnnellezine keferu ve matu ve hum kuffarun fe len yukbele min ehadihim mil\'ul ardı zeheben ve levifteda bih, ulaike lehum azabun elimun ve ma lehum min nasırin.', 'Kuşkusuz Kafir olup,  Kafir olarak ölenler; kurtulmak için yeryüzü dolusu altını fidye olarak verseler de onlardan kabul edilmeyecektir. Onlar için can yakıcı bir azap vardır. Ve onların hiçbir yardımcıları da yoktur.', 'ان الذين كفروا وماتوا وهم كفار فلن يقبل من احدهم مل الارض ذهبا ولو افتدي به اوليك لهم عذاب اليم وما لهم من نصرين'),
(385, 3, 92, 'لَنْ تَنَالُوا الْبِرَّ حَتّٰى تُنْفِقُوا مِمَّا تُحِبُّونَۜ وَمَا تُنْفِقُوا مِنْ شَيْءٍ فَاِنَّ اللّٰهَ بِه۪ عَل۪يمٌ', 'Len tenalul birre hatta tunfiku mimma tuhibbun, ve ma tunfiku min şey\'in fe innallahe bihi alim.', 'Sevdiğiniz şeylerden infak[1] etmedikçe asla birr\'e[1] erişemezsiniz. Ne infak ederseniz,  Allah,  onu bilir.', 'لن تنالوا البر حتي تنفقوا مما تحبون وما تنفقوا من شي فان الله به عليم'),
(386, 3, 93, 'كُلُّ الطَّعَامِ كَانَ حِلاًّ لِبَن۪ٓي اِسْرَٓائ۪لَ اِلَّا مَا حَرَّمَ اِسْرَٓائ۪لُ عَلٰى نَفْسِه۪ مِنْ قَبْلِ اَنْ تُنَزَّلَ التَّوْرٰيةُۜ قُلْ فَأْتُوا بِالتَّوْرٰيةِ فَاتْلُوهَٓا اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kullut taami kane hillen li beni israile illa ma harrame israilu ala nefsihi min kabli en tunezzelet tevrat, kul fe\'tu bit tevrati fetluha in kuntum sadıkin.', 'Tevrat indirilmeden önce,  İsrail\'in kendisine haram kıldıkları hariç bütün yiyecekler İsrailoğulları\'na helaldi. De ki: \"Eğer doğru söylüyorsanız,  haydi Tevrat\'ı getirip okuyun.\"', 'كل الطعام كان حلا لبني اسريل الا ما حرم اسريل علي نفسه من قبل ان تنزل التورية قل فاتوا بالتورية فاتلوها ان كنتم صدقين'),
(387, 3, 94, 'فَمَنِ افْتَرٰى عَلَى اللّٰهِ الْكَذِبَ مِنْ بَعْدِ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'Fe meniftera alallahil kezibe min ba\'di zalike fe ulaike humuz zalimun.', 'Artık bundan sonra kim Allah adına yalan uydurursa,  işte onlar zalimlerin ta kendileridir.', 'فمن افتري علي الله الكذب من بعد ذلك فاوليك هم الظلمون'),
(388, 3, 95, 'قُلْ صَدَقَ اللّٰهُ فَاتَّبِعُوا مِلَّةَ اِبْرٰه۪يمَ حَن۪يفاًۜ وَمَا كَانَ مِنَ الْمُشْرِك۪ينَ', 'Kul sadakallahu fettebiu millete ibrahime hanifa, ve ma kane minel muşrikin.', 'De ki: \"Allah doğru söyledi. Öyle ise hanif[1] olarak İbrahim\'in milletine[2] tabi olun. O müşriklerden değildi.\"', 'قل صدق الله فاتبعوا ملة ابرهيم حنيفا وما كان من المشركين'),
(389, 3, 96, 'اِنَّ اَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذ۪ي بِبَكَّةَ مُبَارَكاً وَهُدًى لِلْعَالَم۪ينَۚ', 'İnne evvele beytin vudia lin nasi lellezi bi bekkete mubareken ve huden lil alemin.', 'İnsanlar için kurulan ilk ev,  Bekke\'deki, [1] kutlu ve bütün insanlığa yol gösteren[2] (Kabe) dir.', 'ان اول بيت وضع للناس للذي ببكة مباركا وهدي للعلمين'),
(390, 3, 97, 'ف۪يهِ اٰيَاتٌ بَيِّنَاتٌ مَقَامُ اِبْرٰه۪يمَۚ وَمَنْ دَخَلَهُ  كَانَ اٰمِناًۜ وَلِلّٰهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ اِلَيْهِ سَب۪يلاًۜ وَمَنْ كَفَرَ فَاِنَّ اللّٰهَ غَنِيٌّ عَنِ الْعَالَم۪ينَ', 'Fihi ayatun beyyinatun makamu ibrahim, ve men dahalehu kane amina, ve lillahi alen nasi hiccul beyti menistetaa ileyhi sebila, ve men kefere fe innallahe ganiyyun anil alemin.', 'Orada apaçık ayetler vardır.[1] İbrahim\'in makamı oradadır. Kim oraya girerse güvende olur. Yoluna gücü yetenin,  Beyt\'i haccetmesi insanlar üzerinde Allah\'ın bir hakkıdır. Her kim kefere[2] olursa,  bilsin ki Allah\'ın hiçbir şeye ihtiyacı yoktur.', 'فيه ايت بينت مقام ابرهيم ومن دخله كان امنا ولله علي الناس حج البيت من استطاع اليه سبيلا ومن كفر فان الله غني عن العلمين'),
(391, 3, 98, 'قُلْ يَٓا اَهْلَ الْكِتَابِ لِمَ تَكْفُرُونَ بِاٰيَاتِ اللّٰهِۗ وَاللّٰهُ شَه۪يدٌ عَلٰى مَا تَعْمَلُونَ', 'Kul ya ehlel kitabi lime tekfurune bi ayatillahi, vallahu şehidun ala ma ta\'melun.', 'De ki: \"Ey Kitap Ehli! Neden Allah\'ın ayetlerini küfrediyorsunuz?[1] Allah,  yaptıklarınıza tanıktır.\"', 'قل ياهل الكتب لم تكفرون بايت الله والله شهيد علي ما تعملون'),
(392, 3, 99, 'قُلْ يَٓا اَهْلَ الْكِتَابِ لِمَ تَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ مَنْ اٰمَنَ تَبْغُونَهَا عِوَجاً وَاَنْتُمْ شُهَدَٓاءُۜ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Kul ya ehlel kitabi lime tesuddune an sebilillahi men amene tebguneha ivecen ve entum şuhedau ve mallahu bi gafilin amma ta\'melun.', 'De ki: \"Ey Kitap Ehli! Gerçeği görüp bildiğiniz halde,  niçin Allah\'ın yolunu eğri göstermeye yeltenerek,  inanmak isteyenleri O\'nun yolundan döndürmeye çalışıyorsunuz! Allah,  yaptıklarınızdan habersiz değildir.\"', 'قل ياهل الكتب لم تصدون عن سبيل الله من امن تبغونها عوجا وانتم شهدا وما الله بغفل عما تعملون'),
(393, 3, 100, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنْ تُط۪يعُوا فَر۪يقاً مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ يَرُدُّوكُمْ بَعْدَ ا۪يمَانِكُمْ كَافِر۪ينَ', 'Ya eyyuhellezine amenu in tutiu ferikan minellezine utul kitabe yeruddukum ba\'de imanikum kafirin.', 'Ey iman edenler! Kitap verilenlerden herhangi bir gruba uyarsanız,  sizi,  imanınızdan sonra tekrar Kafir yaparlar.', 'يايها الذين امنوا ان تطيعوا فريقا من الذين اوتوا الكتب يردوكم بعد ايمنكم كفرين'),
(394, 3, 101, 'وَكَيْفَ تَكْفُرُونَ وَاَنْتُمْ تُتْلٰى عَلَيْكُمْ اٰيَاتُ اللّٰهِ وَف۪يكُمْ رَسُولُهُۜ وَمَنْ يَعْتَصِمْ بِاللّٰهِ فَقَدْ هُدِيَ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ۟', 'Ve keyfe tekfurune ve entum tutla aleykum ayatullahi ve fikum resuluh, ve men ya\'tesim billahi fe kad hudiye ila sıratın mustakim.', 'Allah\'ın ayetleri size okunmaktayken,  elçisi de aranızda yaşarken,  nasıl Küfre saparsınız? Kim Allah\'a sımsıkı sarılırsa o doğru yola iletilmiştir.', 'وكيف تكفرون وانتم تتلي عليكم ايت الله وفيكم رسوله ومن يعتصم بالله فقد هدي الي صرط مستقيم'),
(395, 3, 102, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ حَقَّ تُقَاتِه۪ وَلَا تَمُوتُنَّ اِلَّا وَاَنْتُمْ مُسْلِمُونَ', 'Ya eyyuhellezine amenuttekullahe hakka tukatihi ve la temutunne illa ve entum muslimun.', 'Ey iman edenler! Allah için nasıl takvalı[1] olmanız gerekiyorsa öyle takvalı olun. Ve Müslim olmanın dışında başka bir şekilde ölmeyin.', 'يايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون'),
(396, 3, 103, 'وَاعْتَصِمُوا بِحَبْلِ اللّٰهِ جَم۪يعاً وَلَا تَفَرَّقُواۖ وَاذْكُرُوا نِعْمَتَ اللّٰهِ عَلَيْكُمْ اِذْ  كُنْتُمْ اَعْدَٓاءً فَاَلَّفَ بَيْنَ قُلُوبِكُمْ فَاَصْبَحْتُمْ بِنِعْمَتِه۪ٓ اِخْوَاناًۚ وَكُنْتُمْ عَلٰى شَفَا حُفْرَةٍ مِنَ النَّارِ فَاَنْقَذَكُمْ مِنْهَاۜ   كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمْ اٰيَاتِه۪ لَعَلَّكُمْ تَهْتَدُونَ', 'Va\'tasımu bihablillahi cemian ve la teferreku, vezkuru ni\'metallahi aleykum iz kuntum a\'daen fe ellefe beyne kulubikum fe asbahtum bi ni\'metihi ihvana, ve kuntum ala şefa hufretin minen nari fe enkazekum minha, kezalike yubeyyinullahu lekum ayatihi leallekum tehtedun.', 'Hep birlikte Allah\'ın ipine sımsıkı tutunun ve ayrılığa düşmeyin. Allah\'ın üzerinizdeki nimetini hatırlayın. Hani bir zamanlar,  birbirinize düşmandınız da O\'nun kalplerinizi kaynaştırması sayesinde kardeş oldunuz. Ve yine ateş çukurunun tam kıyısında bulunuyorken,  sizi ona düşmekten O korudu. İşte Allah ayetlerini böyle açıklıyor ki doğru yolu bulasınız.', 'واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمت الله عليكم اذ كنتم اعدا فالف بين قلوبكم فاصبحتم بنعمته اخونا وكنتم علي شفا حفرة من النار فانقذكم منها كذلك يبين الله لكم ايته لعلكم تهتدون'),
(397, 3, 104, 'وَلْتَكُنْ مِنْكُمْ اُمَّةٌ يَدْعُونَ اِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِۜ  وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Veltekun minkum ummetun yed\'une ilel hayri ve ye\'murune bil ma\'rufi ve yenhevne anil munker, ve ulaike humul muflihun.', 'Siz,  hayra çağıran,  ma\'rufu[1] yapıp telkin eden,  munkeri[1] engelleyen bir topluluk olun. İşte onlar kurtuluşa erenlerdir.', 'ولتكن منكم امة يدعون الي الخير ويامرون بالمعروف وينهون عن المنكر واوليك هم المفلحون'),
(398, 3, 105, 'وَلَا تَكُونُوا كَالَّذ۪ينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَٓاءَهُمُ الْبَيِّنَاتُۜ وَاُو۬لٰٓئِكَ لَهُمْ عَذَابٌ عَظ۪يمٌۙ', 'Ve la tekunu kellezine teferraku vahtelefu min ba\'di ma caehumul beyyinat, ve ulaike lehum azabun azim.', 'Kendilerine apaçık belgeler geldikten sonra,  ayrılığa düşüp parçalanan kimseler gibi olmayın. Onlar için büyük bir azap vardır.', 'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاهم البينت واوليك لهم عذاب عظيم'),
(399, 3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌۚ فَاَمَّا الَّذ۪ينَ اسْوَدَّتْ وُجُوهُهُمْ۠  اَكَفَرْتُمْ بَعْدَ ا۪يمَانِكُمْ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ', 'Yevme tebyaddu vucuhun ve tesveddu vucuh, fe emmellezinesveddet vucuhuhum e kefertum ba\'de imanikum fe zukul azabe bima kuntum tekfurun.', 'O gün,  kimi yüzler ağaracak,  kimi yüzler kararacak. Yüzleri kararanlara: \"İmanınızdan sonra kafir mi oldunuz? Öyle ise kafir olmanız nedeniyle azabı tadın.\" denilecek.', 'يوم تبيض وجوه وتسود وجوه فاما الذين اسودت وجوههم اكفرتم بعد ايمنكم فذوقوا العذاب بما كنتم تكفرون'),
(400, 3, 107, 'وَاَمَّا الَّذ۪ينَ ابْيَضَّتْ وُجُوهُهُمْ فَف۪ي رَحْمَةِ اللّٰهِۜ هُمْ ف۪يهَا خَالِدُونَ', 'Ve emmellezinebyaddat vucuhuhum fe fi rahmetillah, hum fiha halidun.', 'Yüzleri ağaranlara gelince,  onlar Allah\'ın rahmetinin içindedirler ve orada sürekli kalacaklardır.', 'واما الذين ابيضت وجوههم ففي رحمة الله هم فيها خلدون'),
(401, 3, 108, 'تِلْكَ اٰيَاتُ اللّٰهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّۜ وَمَا اللّٰهُ يُر۪يدُ ظُلْماً لِلْعَالَم۪ينَ', 'Tilke ayatullahi netluha aleyke bil hakk, ve mallahu yuridu zulmen lil alemin.', 'Bunlar,  sana gerçek olarak okuduğumuz Allah\'ın ayetleridir. Allah,  alemlere haksızlık yapmak istemez.', 'تلك ايت الله نتلوها عليك بالحق وما الله يريد ظلما للعلمين'),
(402, 3, 109, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ۟', 'Ve lillahi ma fis semavati ve ma fil ard, ve ilallahi turceul umur.', 'Göklerde ve yerde olanlar Allah\'ındır. Ve bütün işler Allah\'a döndürülür.', 'ولله ما في السموت وما في الارض والي الله ترجع الامور'),
(403, 3, 110, 'كُنْتُمْ خَيْرَ اُمَّةٍ اُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللّٰهِۜ وَلَوْ اٰمَنَ اَهْلُ الْكِتَابِ لَكَانَ خَيْراً لَهُمْۜ مِنْهُمُ الْمُؤْمِنُونَ وَاَكْثَرُهُمُ الْفَاسِقُونَ', 'Kuntum hayra ummetin uhricet lin nasi te\'murune bil ma\'rufi ve tenhevne anil munkeri ve tu\'minune billah, ve lev amene ehlul kitabi le kane hayran lehum, minhumul mu\'minune ve ekseruhumul fasikun.', 'Siz,  insanlar için çıkarılmış hayırlı bir ümmetsiniz.[1] Ma\'rufu yapıp telkin eder,  munkere engel olursunuz.[2] Ve Allah\'a iman edersiniz. Eğer Ehl-i Kitap da iman etseydi,  bu onlar için daha hayırlı olurdu. İçlerinde iman edenler varsa da çoğunluğu sapkındır.', 'كنتم خير امة اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله ولو امن اهل الكتب لكان خيرا لهم منهم المومنون واكثرهم الفسقون'),
(404, 3, 111, 'لَنْ يَضُرُّوكُمْ اِلَّٓا اَذًىۜ وَاِنْ يُقَاتِلُوكُمْ يُوَلُّوكُمُ الْاَدْبَارَ۠  ثُمَّ لَا يُنْصَرُونَ', 'Len yedurrukum illa eza, ve in yukatilukum yuvellukumul edbar, summe la yunsarun.', 'Onlar,  eziyetten başka size bir zarar veremezler. Sizinle savaşsalar bile geri dönüp kaçarlar. Sonra onlara yardım da edilmez.', 'لن يضروكم الا اذي وان يقتلوكم يولوكم الادبار ثم لا ينصرون'),
(405, 3, 112, 'ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ اَيْنَ مَا ثُقِفُٓوا اِلَّا بِحَبْلٍ مِنَ اللّٰهِ وَحَبْلٍ مِنَ النَّاسِ وَبَٓاؤُ۫ بِغَضَبٍ مِنَ اللّٰهِ وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُۜ ذٰلِكَ بِاَنَّهُمْ كَانُوا يَكْفُرُونَ بِاٰيَاتِ اللّٰهِ وَيَقْتُلُونَ الْاَنْبِيَٓاءَ بِغَيْرِ حَقٍّۜ ذٰلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ۠', 'Duribet aleyhimuz zilletu eyne ma sukıfu illa bi hablin minallahi ve hablin minen nasi ve bau bi gadabin minallahi ve duribet aleyhimul meskeneh, zalike bi ennehum kanu yekfurune bi ayatillahi ve yaktulunel enbiyae bi gayri hakk, zalike bima asav ve kanu ya\'tedun.', 'Onlar[1],  nerede bulunurlarsa bulunsunlar,  Allah\'ın ve insanların ipine tutunmadıkları[2] sürece zillet içinde olurlar. Onlar,  Allah\'ın gazabına uğradılar. Yoksunluğa tutsak oldular. Bunun nedeni,  onların asileşip hadlerini aşarak,  Allah\'ın ayetlerini yalanlamaları ve haksız yere nebilerini öldürmeleridir. Bu ceza,  onların isyan etmelerinden ve haddi aşmış olmalarındandır.', 'ضربت عليهم الذلة اين ما ثقفوا الا بحبل من الله وحبل من الناس وباو بغضب من الله وضربت عليهم المسكنة ذلك بانهم كانوا يكفرون بايت الله ويقتلون الانبيا بغير حق ذلك بما عصوا وكانوا يعتدون'),
(406, 3, 113, 'لَيْسُوا سَوَٓاءًۜ مِنْ اَهْلِ الْكِتَابِ اُمَّةٌ قَٓائِمَةٌ يَتْلُونَ اٰيَاتِ اللّٰهِ اٰنَٓاءَ الَّيْلِ وَهُمْ يَسْجُدُونَ۠', 'Leysu seva\', min ehlil kitabi ummetun kaimetun yetlune ayatillahi anael leyli ve hum yescudun.', 'Ama hepsi aynı değildir. Kitap ehlinden,  Allah\'ın ayetlerini okuyan ve gece saatlerinde secde eden bir topluluk da vardır.', 'ليسوا سوا من اهل الكتب امة قايمة يتلون ايت الله انا اليل وهم يسجدون'),
(407, 3, 114, 'يُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُسَارِعُونَ فِي الْخَيْرَاتِۜ وَاُو۬لٰٓئِكَ مِنَ الصَّالِح۪ينَ', 'Yu\'minune billahi vel yevmil ahiri ve ye\'murune bil ma\'rufi ve yenhevne anil munkeri ve yusariune fil hayrat, ve ulaike mines salihin.', 'Bunlar,  Allah\'a ve Ahiret Günü\'ne inanırlar,  ma\'rufu yapıp telkin ederler,  münkere engel olurlar;[1] hayırda birbirleriyle yarışırlar,  işte bunlar salihlerdendir.[2]', 'يومنون بالله واليوم الاخر ويامرون بالمعروف وينهون عن المنكر ويسرعون في الخيرت واوليك من الصلحين'),
(408, 3, 115, 'وَمَا يَفْعَلُوا مِنْ خَيْرٍ فَلَنْ يُكْفَرُوهُۜ وَاللّٰهُ عَل۪يمٌ بِالْمُتَّق۪ينَ', 'Ve ma yef\'alu min hayrin fe len yukferuh, vallahu alimun bil muttekin.', 'Yaptığınız hiçbir iyilik karşılıksız bırakılmayacaktır. Allah,  kendisine karşı takvalı davrananları en iyi bilendir.', 'وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين'),
(409, 3, 116, 'اِنَّ الَّذ۪ينَ كَفَرُوا لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَٓا اَوْلَادُهُمْ مِنَ اللّٰهِ شَيْـٔاًۜ وَاُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'İnnellezine keferu len tugniye anhum emvaluhum ve la evladuhum minallahi şey\'a, ve ulaike ashabun nar, hum fiha halidun.', 'Kuşkusuz Kafirlerin ne malları ne de evlatları Allah\'ın yanında bir yarar sağlamayacaktır. İşte onlar,  ateş ehlidir. Onlar,  orada sürekli kalacaklardır.', 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واوليك اصحب النار هم فيها خلدون'),
(410, 3, 117, 'مَثَلُ مَا يُنْفِقُونَ ف۪ي هٰذِهِ الْحَيٰوةِ الدُّنْيَا كَمَثَلِ ر۪يحٍ ف۪يهَا صِرٌّ اَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُٓوا اَنْفُسَهُمْ فَاَهْلَكَتْهُۜ وَمَا ظَلَمَهُمُ اللّٰهُ وَلٰكِنْ اَنْفُسَهُمْ يَظْلِمُونَ', 'Meselu ma yunfikune fi hazihil hayatid dunya ke meseli rihin fiha sırrun esabet harse kavmin zalemu enfusehum fe ehlekethu ve ma zalemehumullahu ve lakin enfusehum yazlımun.', 'Onların,  bu dünya hayatında,  infak[1] ettikleri şeylerin durumu,  kendilerine haksızlık etmiş[2] bir halkın ekinine isabet ederek onu mahveden kavurucu bir rüzgara benzer. Allah onlara haksızlık yapmadı,  fakat onlar,  kendi kendilerine haksızlık etmektedirler.', 'مثل ما ينفقون في هذه الحيوة الدنيا كمثل ريح فيها صر اصابت حرث قوم ظلموا انفسهم فاهلكته وما ظلمهم الله ولكن انفسهم يظلمون'),
(411, 3, 118, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُوا بِطَانَةً مِنْ دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالاًۜ وَدُّوا مَا عَنِتُّمْۚ قَدْ بَدَتِ الْبَغْضَٓاءُ مِنْ اَفْوَاهِهِمْۚ وَمَا تُخْف۪ي صُدُورُهُمْ اَكْـبَرُۜ قَدْ بَيَّنَّا لَكُمُ الْاٰيَاتِ اِنْ كُنْتُمْ تَعْقِلُونَ', 'Ya eyyuhellezine amenu la tettehızu bitaneten min dunikum la ye\'lunekum habala, veddu ma anittum, kad bedetil bagdau min efvahihim, ve ma tuhfi suduruhum ekber, kad beyyenna lekumul ayati in kuntum ta\'kılun.', 'Ey iman edenler! Birbirinizden başkasını,  kendinize sırdaş edinmeyin. Onlar,  size zarar vermekten geri durmazlar,  sizin sıkıntıya düşmenizi isterler. Gerçi,  kinlerini ağızları ile dışa vuruyorlar,  ancak kalplerinde gizledikleri kin daha büyüktür. Eğer aklınızı kullanırsanız,  ayetlerimizi size açık açık bildirdik.', 'يايها الذين امنوا لا تتخذوا بطانة من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضا من افوههم وما تخفي صدورهم اكبر قد بينا لكم الايت ان كنتم تعقلون'),
(412, 3, 119, 'هَٓا اَنْتُمْ اُو۬لَٓاءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِالْكِتَابِ كُلِّه۪ۚ وَاِذَا لَقُوكُمْ قَالُٓوا اٰمَنَّاۗ وَاِذَا خَلَوْا عَضُّوا عَلَيْكُمُ الْاَنَامِلَ مِنَ الْغَيْظِۜ قُلْ مُوتُوا بِغَيْظِكُمْۜ اِنَّ اللّٰهَ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Ha entum ulai tuhıbbunehum ve la yuhıbbunekum ve tu\'minune bil kitabi kullih, ve iza lekukum kalu amenna, ve iza halev addu aleykumul enamile minel gayz, kul mutu bi gayzikum, innallahe alimun bi zatis sudur.', 'İşte siz öyle kimselersiniz ki,  onları seversiniz. Siz,  bütün kitaplara inandığınız halde onlar sizi sevmezler. Sizinle karşılaştıkları zaman; inandık derler,  yalnız kaldıkları zaman ise size olan öfkelerinden parmaklarını ısırırlar. De ki: \"Öfkenizden ölün!\" Kuşkusuz,  Allah,  kalplerin gizlediklerini bilir.', 'هانتم اولا تحبونهم ولا يحبونكم وتومنون بالكتب كله واذا لقوكم قالوا امنا واذا خلوا عضوا عليكم الانامل من الغيظ قل موتوا بغيظكم ان الله عليم بذات الصدور'),
(413, 3, 120, 'اِنْ تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْۘ وَاِنْ تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا بِهَاۜ وَاِنْ تَصْبِرُوا وَتَتَّقُوا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـٔاًۜ اِنَّ اللّٰهَ بِمَا يَعْمَلُونَ مُح۪يطٌ۟', 'İn temseskum hasenetun tesu\'hum, ve in tusibkum seyyietun yefrahu biha ve in tasbiru ve tetteku la yadurrukum keyduhum şey\'a, innallahe bi ma ya\'melune muhit.', 'Eğer size bir iyilik dokunursa bu onları üzer. Eğer size bir kötülük isabet ederse bu onları sevindirir. Eğer sabreder ve takvalı olursanız,  onların hileleri size bir zarar vermez. Kuşkusuz,  Allah,  ilmiyle onların yaptıkları her şeyi kuşatmıştır.', 'ان تمسسكم حسنة تسوهم وان تصبكم سيية يفرحوا بها وان تصبروا وتتقوا لا يضركم كيدهم شيا ان الله بما يعملون محيط'),
(414, 3, 121, 'وَاِذْ غَدَوْتَ مِنْ اَهْلِكَ تُبَوِّئُ الْمُؤْمِن۪ينَ مَقَاعِدَ لِلْقِتَالِۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌۙ', 'Ve iz gadavte min ehlike tubevviul mu\'minine makaide lil kıtal, vallahu semiun alim.', 'Hani! Sen,  Mü\'minleri savaş düzenine sokmak için,  sabah erkenden ailenden ayrılmıştın. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'واذ غدوت من اهلك تبوي المومنين مقعد للقتال والله سميع عليم'),
(415, 3, 122, 'اِذْ هَمَّتْ طَٓائِفَتَانِ مِنْكُمْ اَنْ تَفْشَلَاۙ وَاللّٰهُ وَلِيُّهُمَاۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'İz hemmet taifetani minkum en tefşela vallahu veliyyuhuma ve alallahi fel yetevekkelil mu\'minun.', 'Hani! İçinizden iki grup korkuya kapılıp,  geri çekilmeye yeltenmişti. Halbuki Allah,  onların velisiydi[1]. Mü\'minler yalnız Allah\'a tevekkül[2] etsinler.', 'اذ همت طايفتان منكم ان تفشلا والله وليهما وعلي الله فليتوكل المومنون'),
(416, 3, 123, 'وَلَقَدْ نَصَرَكُمُ اللّٰهُ بِبَدْرٍ وَاَنْتُمْ اَذِلَّةٌۚ فَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تَشْكُرُونَ', 'Ve lekad nasarakumullahu bi bedrin ve entum ezilleh, fettekullahe leallekum teşkurun.', 'Ant olsun! Çok zayıf olduğunuz Bedir\'de de Allah size yardım etmişti. O halde,  Allah\'a karşı takvalı[1] olun ki şükretmiş[2] olasınız.', 'ولقد نصركم الله ببدر وانتم اذلة فاتقوا الله لعلكم تشكرون'),
(417, 3, 124, 'اِذْ تَقُولُ لِلْمُؤْمِن۪ينَ اَلَنْ يَكْفِيَكُمْ اَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلٰثَةِ اٰلَافٍ مِنَ الْمَلٰٓئِكَةِ مُنْزَل۪ينَۜ', 'İz tekulu lil mu\'minine e len yekfiyekum en yumiddekum rabbukum bi selaseti alafin minel melaiketi munzelin.', 'Hani! Sen Mü\'minlere: \"Rabb\'inizin,  indirilmiş üç bin melekle yardım etmesi size yetmez mi?\" diyordun.', 'اذ تقول للمومنين الن يكفيكم ان يمدكم ربكم بثلثة الف من المليكة منزلين'),
(418, 3, 125, 'بَلٰٓىۙ اِنْ تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُمْ مِنْ فَوْرِهِمْ هٰذَا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ اٰلَافٍ مِنَ الْمَلٰٓئِكَةِ مُسَوِّم۪ينَ', 'Bela in tasbiru ve tetteku ve ye\'tukum min fevrihim haza yumdidkum rabbukum bi hamseti alafin minel melaiketi musevvimin.', 'Evet! Sabreder ve takvalı davranırsanız,  düşman size hemen saldırsa bile,  Rabb\'iniz,  size,  seçilmiş beş bin melekle yardım eder.', 'بلي ان تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسة الف من المليكة مسومين'),
(419, 3, 126, 'وَمَا جَعَلَهُ اللّٰهُ اِلَّا بُشْرٰى لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُمْ بِه۪ۜ وَمَا النَّصْرُ اِلَّا مِنْ عِنْدِ اللّٰهِ الْعَز۪يزِ الْحَك۪يمِۙ', 'Ve ma cealehullahu illa buşra lekum ve li tatmeinne kulubukum bih, ve men nasru illa min indillahil azizil hakim.', 'Allah,  bununla sevinmenizi ve kalplerinizin yatışmasını dilemiştir. Çünkü yardım ancak Mutlak Üstün Olan ve En İyi Hüküm Veren Allah\'ın yanındadır.', 'وما جعله الله الا بشري لكم ولتطمين قلوبكم به وما النصر الا من عند الله العزيز الحكيم'),
(420, 3, 127, 'لِيَقْطَعَ طَرَفاً مِنَ الَّذ۪ينَ كَفَرُٓوا اَوْ يَكْبِتَهُمْ فَيَنْقَلِبُوا خَٓائِب۪ينَ', 'Li yaktaa tarafen minellezine keferu ev yekbitehum fe yenkalibu haibin.', 'Bu yardım,  Kafirlerin bir kısmının imha edilmesi veya bozguna uğrayarak umutsuzca geri dönüp gitmeleri için yapıldı.', 'ليقطع طرفا من الذين كفروا او يكبتهم فينقلبوا خايبين'),
(421, 3, 128, 'لَيْسَ لَكَ مِنَ الْاَمْرِ شَيْءٌ اَوْ يَتُوبَ عَلَيْهِمْ اَوْ يُعَذِّبَهُمْ فَاِنَّهُمْ ظَالِمُونَ', 'Leyse leke minel emri şey\'un ev yetube aleyhim ev yuazzibehum fe innehum zalimun.', 'Bu konuda senin yapabileceğin bir şey yoktur. O ya onların tevbelerini kabul edecek ya da onlara azap edecek. Çünkü onlar,  zalim kimselerdir.', 'ليس لك من الامر شي او يتوب عليهم او يعذبهم فانهم ظلمون'),
(422, 3, 129, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ يَغْفِرُ لِمَنْ يَشَٓاءُ وَيُعَذِّبُ مَنْ يَشَٓاءُۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ۟', 'Ve lillahi ma fis semavati ve ma fil ard, yagfiru li men yeşau ve yuazzibu men yeşa\', vallahu gafurun rahim.', 'Göklerde ve yerde olan her şey Allah\'ındır. O hak edeni[1] bağışlar,  hak edene[1] azap eder. Allah Çok Affedici ve Çok Bağışlayıcı\'dır.', 'ولله ما في السموت وما في الارض يغفر لمن يشا ويعذب من يشا والله غفور رحيم'),
(423, 3, 130, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَأْكُلُوا الرِّبٰٓوا اَضْعَافاً مُضَاعَفَةًۖ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُونَۚ', 'Ya eyyuhellezine amenu la te\'kulur riba ad\'afen mudaafeh, vettekullahe leallekum tuflihun.', 'Ey iman edenler! Kat kat artırarak riba[1] yemeyin. Allah\'a karşı takva sahibi olun. Umulur ki kurtuluşa erersiniz.', 'يايها الذين امنوا لا تاكلوا الربوا اضعفا مضعفة واتقوا الله لعلكم تفلحون'),
(424, 3, 131, 'وَاتَّقُوا النَّارَ الَّت۪ٓي اُعِدَّتْ لِلْكَافِر۪ينَۚ', 'Vettekun narelleti uiddet lil kafirin.', 'Kafirler için hazırlanmış ateşten korunmak için takva sahibi olun.', 'واتقوا النار التي اعدت للكفرين'),
(425, 3, 132, 'وَاَط۪يعُوا اللّٰهَ وَالرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَۚ', 'Ve atiullahe ver resule leallekum turhamun.', 'Allah\'a ve Resul\'e itaat edin ki size merhamet edilsin.[1]', 'واطيعوا الله والرسول لعلكم ترحمون'),
(426, 3, 133, 'وَسَارِعُٓوا اِلٰى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمٰوَاتُ وَالْاَرْضُۙ اُعِدَّتْ لِلْمُتَّق۪ينَۙ', 'Ve sariu ila magfiretin min rabbikum ve cennetin arduhas semavatu vel ardu, uiddet lil muttekin.', 'Rabb\'inizin bağışlamasına ve muttakiler için hazırlanmış,  yer ile gök arası kadar geniş olan Cennet için yarışın.', 'وسارعوا الي مغفرة من ربكم وجنة عرضها السموت والارض اعدت للمتقين'),
(427, 3, 134, 'اَلَّذ۪ينَ يُنْفِقُونَ فِي السَّرَّٓاءِ وَالضَّرَّٓاءِ وَالْكَاظِم۪ينَ الْغَيْظَ وَالْعَاف۪ينَ عَنِ النَّاسِۜ وَاللّٰهُ يُحِبُّ الْمُحْسِن۪ينَۚ', 'Ellezine yunfikune fis serrai ved darrai vel kazıminel gayza vel afine anin nas, vallahu yuhibbul muhsinin.', 'Onlar[1],  bollukta da darlıkta da infak[2] ederler. Öfkelerini yenerler,  insanların kusurlarını bağışlarlar. Allah muhsin[3] olanları sever.', 'الذين ينفقون في السرا والضرا والكظمين الغيظ والعافين عن الناس والله يحب المحسنين'),
(428, 3, 135, 'وَالَّذ۪ينَ اِذَا فَعَلُوا فَاحِشَةً اَوْ ظَلَمُٓوا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْۖ وَمَنْ يَغْفِرُ الذُّنُوبَ اِلَّا اللّٰهُۖ وَلَمْ يُصِرُّوا عَلٰى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ', 'Vellezine iza fealu fahişeten ev zalemu enfusehum zekerullahe festagferu li zunubihim, ve men yagfiruz zunube illallahu ve lem yusırru ala ma fealu ve hum ya\'lemun .', 'Ve onlar,  kötü bir şey yaptıkları veya kendilerine zulmettikleri[1] zaman,  Allah\'ı hatırlayıp,  suçlarının bağışlanması için O\'na yalvarırlar. Zaten Allah\'ın dışında kim suçları bağışlayabilir ki? Onlar,  yaptıkları kötülüklerde bile bile ısrar etmezler.', 'والذين اذا فعلوا فحشة او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا علي ما فعلوا وهم يعلمون'),
(429, 3, 136, 'اُو۬لٰٓئِكَ جَزَٓاؤُ۬هُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ وَنِعْمَ اَجْرُ الْعَامِل۪ينَۜ', 'Ulaike cezauhum magfiretun min rabbihim ve cennatun tecri min tahtihal enharu halidine fiha, ve ni\'me ecrul amilin.', 'İşte onların yaptıklarının karşılığı,  Rabb\'lerinin bağışlaması ve içinden ırmaklar akan ve içinde sürekli kalacakları Cennetlerdir. Böyle yapanlara verilen karşılık,  ne güzeldir.', 'اوليك جزاوهم مغفرة من ربهم وجنت تجري من تحتها الانهر خلدين فيها ونعم اجر العملين'),
(430, 3, 137, 'قَدْ خَلَتْ مِنْ قَبْلِكُمْ سُنَنٌۙ فَس۪يرُوا فِي الْاَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّب۪ينَ', 'Kad halet min kablikum sunenun, fe siru fil ardı fenzuru keyfe kane akıbetul mukezzibin.', 'Sizden önce de yasalar uygulandı.[1] Yeryüzünü dolaşın[2] da yalanlayanların sonları nasıl oldu görün.', 'قد خلت من قبلكم سنن فسيروا في الارض فانظروا كيف كان عقبة المكذبين'),
(431, 3, 138, 'هٰذَا بَيَانٌ لِلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِلْمُتَّق۪ينَ', 'Haza beyanun lin nasi ve huden ve mev\'ızatun lil muttekin.', 'Bu; insanlar için bir açıklama,  tahva sahipleri[1] için bir hidayet[2] ve öğüttür.', 'هذا بيان للناس وهدي وموعظة للمتقين'),
(432, 3, 139, 'وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَاَنْتُمُ الْاَعْلَوْنَ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ve la tehinu ve la tahzenu ve entumul a\'levne in kuntum mu\'minin.', 'Gevşemeyin,  üzülmeyin! Eğer,  gerçekten inanmışsanız,  üstün olan sizsiniz.', 'ولا تهنوا ولا تحزنوا وانتم الاعلون ان كنتم مومنين'),
(433, 3, 140, 'اِنْ يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِثْلُهُۜ وَتِلْكَ الْاَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِۚ وَلِيَعْلَمَ اللّٰهُ الَّذ۪ينَ اٰمَنُوا وَيَتَّخِذَ مِنْكُمْ شُهَدَٓاءَۜ وَاللّٰهُ لَا يُحِبُّ الظَّالِم۪ينَۙ', 'İn yemseskum karhun fe kad messel kavme karhun misluh, ve tilkel eyyamu nudaviluha beynen nas, ve li ya\'lemallahullezine amenu ve yettehize minkum şuhedae vallahu la yuhibbuz zalimin.', 'Eğer size bir sıkıntı isabet ederse,  başka halklara da benzeri sıkıntı isabet etmiştir. Bu günleri,  insanlar arasında döndürüp dururuz. Bu,  Allah\'ın içinizdeki gerçek inananları ayırt etmesi ve gerçeğin tanıklarını belli etmesi içindir. Allah,  zalimleri sevmez.', 'ان يمسسكم قرح فقد مس القوم قرح مثله وتلك الايام نداولها بين الناس وليعلم الله الذين امنوا ويتخذ منكم شهدا والله لا يحب الظلمين'),
(434, 3, 141, 'وَلِيُمَحِّصَ اللّٰهُ الَّذ۪ينَ اٰمَنُوا وَيَمْحَقَ الْكَافِر۪ينَ', 'Ve liyumahhisallahullezine amenu ve yemhakal kafirin.', 'Bu,  Allah\'ın,  iman edenleri arındırması ve Kafirleri mahvetmesi içindir.', 'وليمحص الله الذين امنوا ويمحق الكفرين'),
(435, 3, 142, 'اَمْ حَسِبْتُمْ اَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللّٰهُ الَّذ۪ينَ جَاهَدُوا مِنْكُمْ وَيَعْلَمَ الصَّابِر۪ينَ', 'Em hasibtum en tedhulul cennete ve lemma ya\'lemillahullezine cahedu minkum ve ya\'lemes sabirin.', 'Yoksa siz; Allah,  içinizdeki cihad[1] edenleri ve sabredenleri[2] ortaya çıkarmadan Cennet\'e gireceğinizi mi sanıyorsunuz?', 'ام حسبتم ان تدخلوا الجنة ولما يعلم الله الذين جهدوا منكم ويعلم الصبرين'),
(436, 3, 143, 'وَلَقَدْ كُنْتُمْ تَمَنَّوْنَ الْمَوْتَ مِنْ قَبْلِ اَنْ تَلْقَوْهُۖ فَقَدْ رَاَيْتُمُوهُ وَاَنْتُمْ تَنْظُرُونَ۟', 'Ve lekad kuntum temennevnel mevte min kabli en telkavhu, fe kad raeytumuhu ve entum tenzurun.', 'Siz,  ölümle yüz yüze gelmeden önce,  ölmeyi temenni ediyordunuz; ama onu görünce de bakakaldınız.', 'ولقد كنتم تمنون الموت من قبل ان تلقوه فقد رايتموه وانتم تنظرون'),
(437, 3, 144, 'وَمَا مُحَمَّدٌ اِلَّا رَسُولٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُۜ اَفَا۬ئِنْ مَاتَ اَوْ قُتِلَ انْقَلَبْتُمْ عَلٰٓى اَعْقَابِكُمْۜ وَمَنْ يَنْقَلِبْ عَلٰى عَقِبَيْهِ فَلَنْ يَضُرَّ اللّٰهَ شَيْـٔاًۜ وَسَيَجْزِي اللّٰهُ الشَّاكِر۪ينَ', 'Ve ma muhammedun illa resul, kad halet min kablihir rusul, e fein mate ev kutilenkalebtum ala a\'kabikum, ve men yenkalib ala akıbeyhi fe len yadurrallahe şey\'a, ve se yeczillahuş şakirin.', 'Muhammed,  ancak bir resuldür. Ondan önce de resuller gelip geçti. Eğer o ölür ya da öldürülürse,  siz topuklarınız üzerinde gerisin geri mi döneceksiniz. Kim topukları üzerinde gerisin geri dönerse,  Allah\'a hiçbir zarar veremez. Allah,  şükredenleri ödüllendirecektir.', 'وما محمد الا رسول قد خلت من قبله الرسل افاين مات او قتل انقلبتم علي اعقبكم ومن ينقلب علي عقبيه فلن يضر الله شيا وسيجزي الله الشكرين'),
(438, 3, 145, 'وَمَا كَانَ لِنَفْسٍ اَنْ تَمُوتَ اِلَّا بِاِذْنِ اللّٰهِ كِتَاباً مُؤَجَّلاًۜ وَمَنْ يُرِدْ ثَوَابَ الدُّنْيَا نُؤْتِه۪ مِنْهَاۚ وَمَنْ يُرِدْ ثَوَابَ الْاٰخِرَةِ نُؤْتِه۪ مِنْهَاۜ وَسَنَجْزِي الشَّاكِر۪ينَ', 'Ve ma kane li nefsin en temute illa bi iznillahi kitaben mueccela, ve men yurid sevabed dunya nu\'tihi minha, ve men yurid sevabel ahirati nu\'tihi minha, ve se necziş şakirin.', 'Allah\'ın izni[1] dışında,  hiç kimse ölmez. Ölüm,  vakti belirlenmiş bir süreye göre yazılmıştır.[2] Kim dünya kazancını isterse; ona,  onu veririz,  kim de ahiret kazancını isterse,  ona da onu veririz. Şükredenleri ödüllendireceğiz.', 'وما كان لنفس ان تموت الا باذن الله كتبا موجلا ومن يرد ثواب الدنيا نوته منها ومن يرد ثواب الاخرة نوته منها وسنجزي الشكرين'),
(439, 3, 146, 'وَكَاَيِّنْ مِنْ نَبِيٍّ قَاتَلَۙ مَعَهُ رِبِّيُّونَ كَث۪يرٌۚ فَمَا وَهَنُوا لِمَٓا اَصَابَهُمْ ف۪ي سَب۪يلِ اللّٰهِ وَمَا ضَعُفُوا وَمَا اسْتَكَانُواۜ وَاللّٰهُ يُحِبُّ الصَّابِر۪ينَ', 'Ve keeyyin min nebiyyin katele, meahu rıbbiyyune kesir, fe ma vehenu li ma asabehum fi sebilillahi ve ma daufu ve mestekanu vallahu yuhibbus sabirin.', 'Nice nebilerle,  rabbani[1] olanlar birlikte savaştı. Bunlar,  Allah yolunda başlarına gelenlerden dolayı yılmadılar,  zayıflık göstermediler ve boyun eğmediler. Allah sabredenleri sever.', 'وكاين من نبي قتل معه ربيون كثير فما وهنوا لما اصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصبرين'),
(440, 3, 147, 'وَمَا كَانَ قَوْلَهُمْ اِلَّٓا اَنْ قَالُوا رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَاِسْرَافَنَا ف۪ٓي اَمْرِنَا وَثَبِّتْ اَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِر۪ينَ', 'Ve ma kane kavlehum illa en kalu rabbenagfir lena zunubena ve israfena fi emrina ve sebbit akdamena vensurna alel kavmil kafirin.', 'Onların sözleri ancak şuydu: \"Ey Rabbimiz! Suçlarımızı ve yaptığımız taşkınlıkları bağışla,  ayaklarımızı sabit kıl,  gerçeği yalanlayan nankörlere karşı bize yardım et.\"', 'وما كان قولهم الا ان قالوا ربنا اغفر لنا ذنوبنا واسرافنا في امرنا وثبت اقدامنا وانصرنا علي القوم الكفرين'),
(441, 3, 148, 'فَاٰتٰيهُمُ اللّٰهُ ثَوَابَ الدُّنْيَا وَحُسْنَ ثَوَابِ الْاٰخِرَةِۜ وَاللّٰهُ يُحِبُّ الْمُحْسِن۪ينَ۟', 'Fe atahumullahu sevabed dunya ve husne sevabil ahireh, vallahu yuhibbul muhsinin.', 'Bunun üzerine,  Allah da onlara hem dünya kazancını hem de ahiretin en iyi kazancını verdi. Allah,  muhsin[1] olanları sever.', 'فاتيهم الله ثواب الدنيا وحسن ثواب الاخرة والله يحب المحسنين'),
(442, 3, 149, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنْ تُط۪يعُوا الَّذ۪ينَ كَفَرُوا يَرُدُّوكُمْ عَلٰٓى اَعْقَابِكُمْ فَتَنْقَلِبُوا خَاسِر۪ينَ', 'Ya eyyuhellezine amenu in tutiullezine keferu yeruddukum ala a\'kabikum fe tenkalibu hasirin.', 'Ey iman edenler! Eğer Kafirlere[1] uyarsanız,  sizi,  topuklarınız üzerinde gerisin geriye döndürürler de hüsrana uğrayanlardan olursunuz.', 'يايها الذين امنوا ان تطيعوا الذين كفروا يردوكم علي اعقبكم فتنقلبوا خسرين'),
(443, 3, 150, 'بَلِ اللّٰهُ مَوْلٰيكُمْۚ وَهُوَ خَيْرُ النَّاصِر۪ينَ', 'Belillahu mevlakum, ve huve hayrun nasırin.', 'Hayır! Sizin Mevla\'nız[1] Allah\'tır. O,  yardım edenlerin en hayırlısıdır.', 'بل الله موليكم وهو خير النصرين'),
(444, 3, 151, 'سَنُلْق۪ي ف۪ي قُلُوبِ الَّذ۪ينَ كَفَرُوا الرُّعْبَ بِمَٓا اَشْرَكُوا بِاللّٰهِ مَا لَمْ يُنَزِّلْ بِه۪ سُلْطَاناًۚ وَمَأْوٰيهُمُ النَّارُۜ وَبِئْسَ مَثْوَى الظَّالِم۪ينَ', 'Se nulki fi kulubillezine keferur ru\'be bima eşraku billahi ma lem yunezzil bihi sultana, ve me\'vahumun nar, ve bi\'se mesvez zalimin.', 'Yetki verdiğine dair,  hakkında hiçbir kanıt indirmediği varlıklara,  ilahlık yakıştırmalarından dolayı,  Kafirlerin kalplerine korku salacağız. Onların sığınakları ateştir. Zalimlerin varacağı yer ne kötüdür.', 'سنلقي في قلوب الذين كفروا الرعب بما اشركوا بالله ما لم ينزل به سلطنا وماويهم النار وبيس مثوي الظلمين'),
(445, 3, 152, 'وَلَقَدْ صَدَقَكُمُ اللّٰهُ وَعْدَهُٓ اِذْ تَحُسُّونَهُمْ بِاِذْنِه۪ۚ حَتّٰٓى اِذَا فَشِلْتُمْ وَتَنَازَعْتُمْ فِي الْاَمْرِ وَعَصَيْتُمْ مِنْ بَعْدِ مَٓا اَرٰيكُمْ مَا تُحِبُّونَۜ مِنْكُمْ مَنْ يُر۪يدُ الدُّنْيَا وَمِنْكُمْ مَنْ يُر۪يدُ الْاٰخِرَةَۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْۚ وَلَقَدْ عَفَا عَنْكُمْۜ وَاللّٰهُ ذُوفَضْلٍ عَلَى الْمُؤْمِن۪ينَ', 'Ve lekad sadakakumullahu va\'dehu iz tehussunehum bi iznih, hatta iza feşiltum ve tenaza\'tum fil emri ve asaytum min ba\'di ma erakum ma tuhıbbun, minkum men yuridud dunya ve minkum men yuridul ahireh, summe sarafekum anhum li yebteliyekum, ve lekad afa ankum, vallahu zu fadlin alel mu\'minin.', 'Elbette Allah,  size verdiği sözü tuttu; O\'nun izni[1] ile onları kırıp geçiriyordunuz. Ne var ki arzuladığınız zafere kavuştuktan sonra,  gevşediniz. Verilen emre uymayarak,  itaatsizlik ettiniz. Kiminiz dünyayı isterken,  kiminiz de ahireti istiyordu. Bundan dolayı Allah sınamak için,  size olan desteğini kesti. Ancak yine de sizi affetti. Allah,  müminlere karşı gerçekten lütuf[2] sahibidir.', 'ولقد صدقكم الله وعده اذ تحسونهم باذنه حتي اذا فشلتم وتنزعتم في الامر وعصيتم من بعد ما اريكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الاخرة ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل علي المومنين'),
(446, 3, 153, 'اِذْ تُصْعِدُونَ وَلَا تَلْوُ۫نَ عَلٰٓى اَحَدٍ وَالرَّسُولُ يَدْعُوكُمْ ف۪ٓي اُخْرٰيكُمْ فَاَثَابَكُمْ غَماًّ بِغَمٍّ  لِكَيْلَا  تَحْزَنُوا عَلٰى مَا فَاتَكُمْ وَلَا مَٓا اَصَابَكُمْۜ  وَاللّٰهُ خَب۪يرٌ بِمَا تَعْمَلُونَ', 'İz tus\'idune ve la telvune ala ehadin ver resulu yed\'ukum fi uhrakum fe esabekum gammen bi gammin li keyla tahzenu ala ma fatekum ve la ma asabekum, vallahu habirun bima ta\'melun.', 'Hani,  Resul sizi çağırdığı halde; siz,  kimseye dönüp bakmadan uzaklaştınız. Bunun üzerine,  Allah,  sizi üzüntü üstüne üzüntüyle cezalandırdı. Allah\'ın sizi affetmesi,  elinizden kaçırdığınıza ve başınıza gelene üzülmeyesiniz diyedir. Allah,  yaptığınız her şeyden haberdardır.', 'اذ تصعدون ولا تلون علي احد والرسول يدعوكم في اخريكم فاثبكم غما بغم لكيلا تحزنوا علي ما فاتكم ولا ما اصبكم والله خبير بما تعملون'),
(447, 3, 154, 'ثُمَّ اَنْزَلَ عَلَيْكُمْ مِنْ بَعْدِ الْغَمِّ اَمَنَةً نُعَاساً يَغْشٰى طَٓائِفَةً مِنْكُمْۙ وَطَٓائِفَةٌ قَدْ اَهَمَّتْهُمْ اَنْفُسُهُمْ يَظُنُّونَ بِاللّٰهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِۜ يَقُولُونَ هَلْ لَنَا مِنَ الْاَمْرِ مِنْ شَيْءٍۜ قُلْ اِنَّ الْاَمْرَ كُلَّهُ لِلّٰهِۜ يُخْفُونَ ف۪ٓي اَنْفُسِهِمْ مَا لَا يُبْدُونَ لَكَۜ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ الْاَمْرِ شَيْءٌ مَا قُتِلْنَا هٰهُنَاۜ قُلْ لَوْ كُنْتُمْ ف۪ي بُيُوتِكُمْ لَبَرَزَ الَّذ۪ينَ كُتِبَ عَلَيْهِمُ الْقَتْلُ اِلٰى مَضَاجِعِهِمْۚ وَلِيَبْتَلِيَ اللّٰهُ مَا ف۪ي صُدُورِكُمْ وَلِيُمَحِّصَ مَا ف۪ي قُلُوبِكُمْۜ وَاللّٰهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Summe enzele aleykum min ba\'dil gammi emeneten nuasen yagşa taifeten minkum, ve taifetun kad ehemmethum enfusuhum yezunnune billahi gayrel hakkı zannel cahiliyyeh, yekulune hel lena minel emri min şey\', kul innel emre kullehu lillah, yuhfune fi enfusihim ma la yubdune lek, yekulune lev kane lena minel emri şey\'un ma kutilna hahuna, kul lev kuntum fi buyutikum le berezellezine kutibe aleyhimul katlu ila medaciihim, ve li yebteliyallahu ma fi sudurikum ve li yumahhısa ma fi kulubikum, vallahu alimun bi zatis sudur.', 'Sonra O,  üzüntünün ardından,  sizden bir kısmınıza,  güven duygusu,  sarıp kuşatan bir iç dinginlik indirdi. Bir kısmınız da can kaygısına düşmüştü. Allah hakkında,  tıpkı cahiliye[1] dönemindekine benzer biçimde gerçeğe aykırı bir sanı besliyorlardı. \"Bu işten bize ne?\" diyorlardı. De ki: \"Her şeyin takdiri yalnız Allah\'ındır.\" Sana,  açıklamadıkları şeyleri içlerinde gizliyorlar. \"Elimizden bir şey gelseydi buralarda öldürülmezdik.\" diyorlar. De ki: \"Evlerinizde kalmış olsaydınız bile,  üzerlerine öldürülme yazılmış[2] olanlar düşüp ölecekleri yere kendiliğinden çıkıp gelirlerdi. Allah,  bunu,  göğüslerinizde olanı sınamak ve kalplerinizdekilerini arındırmak için yaptı. Allah,  göğüslerin özünü bilir.', 'ثم انزل عليكم من بعد الغم امنة نعاسا يغشي طايفة منكم وطايفة قد اهمتهم انفسهم يظنون بالله غير الحق ظن الجهلية يقولون هل لنا من الامر من شي قل ان الامر كله لله يخفون في انفسهم ما لا يبدون لك يقولون لو كان لنا من الامر شي ما قتلنا ههنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل الي مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور'),
(448, 3, 155, 'اِنَّ الَّذ۪ينَ تَوَلَّوْا مِنْكُمْ يَوْمَ الْتَقَى الْجَمْعَانِۙ اِنَّمَا اسْتَزَلَّهُمُ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُواۚ وَلَقَدْ عَفَا اللّٰهُ عَنْهُمْۜ اِنَّ اللّٰهَ غَفُورٌ حَل۪يمٌ۟', 'İnnellezine tevellev minkum yevmel tekal cem\'ani, inne mestezellehumuş şeytanu bi ba\'di ma kesebu, ve lekad afallahu anhum innallahe gafurun halim.', 'İki toplumun,  savaş alanında karşılaştıkları gün,  içinizden geri dönenlere gelince! Bu yaptıklarından dolayı,  şeytan onların ayaklarını kaydırmak istedi. Doğrusu,  Allah,  yine de onları affetti. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Çok Hoş Görülü\'dür.', 'ان الذين تولوا منكم يوم التقي الجمعان انما استزلهم الشيطن ببعض ما كسبوا ولقد عفا الله عنهم ان الله غفور حليم'),
(449, 3, 156, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَكُونُوا كَالَّذ۪ينَ كَفَرُوا وَقَالُوا لِاِخْوَانِهِمْ اِذَا ضَرَبُوا فِي الْاَرْضِ اَوْ كَانُوا غُزًّى لَوْ كَانُوا عِنْدَنَا مَا مَاتُوا وَمَا قُتِلُواۚ لِيَجْعَلَ اللّٰهُ ذٰلِكَ حَسْرَةً ف۪ي قُلُوبِهِمْۜ وَاللّٰهُ يُحْـي۪ وَيُم۪يتُۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Ya eyyuhellezine amenu la tekunu kellezine keferu ve kalu li ıhvanihim iza darabu fil ardı ev kanu guzzen lev kanu indena ma matu ve ma kutilu, li yec\'alallahu zalike hasreten fi kulubihim vallahu yuhyi ve yumit, vallahu bi ma ta\'melune basir.', 'Ey iman edenler! Yolculuğa çıkan ya da savaşa katılan kardeşleri hakkında,  \"Eğer bizim yanımızda olsalardı ölmez ve öldürülmezlerdi.\" diyen,  Kafirler gibi olmayın. Allah,  bunu,  kalplerinde bir hasret[1] olsun diye yaptı. Allah,  yaşatan ve öldürendir. Kuşkusuz,  Allah,  bütün yaptıklarınızı görmektedir.', 'يايها الذين امنوا لا تكونوا كالذين كفروا وقالوا لاخونهم اذا ضربوا في الارض او كانوا غزي لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسرة في قلوبهم والله يحي ويميت والله بما تعملون بصير'),
(450, 3, 157, 'وَلَئِنْ قُتِلْتُمْ ف۪ي سَب۪يلِ اللّٰهِ اَوْ مُتُّمْ لَمَغْفِرَةٌ مِنَ اللّٰهِ وَرَحْمَةٌ خَيْرٌ مِمَّا يَجْمَعُونَ', 'Ve lein kutiltum fi sebilillahi ev muttum le magfiretun minallahi ve rahmetun hayrun mimma yecmeun.', 'Eğer Allah yolunda ölür veya öldürülürseniz,  Allah\'tan size bir bağışlama ve bir rahmet vardır. Bilin ki bu,  insanların toplayacakları her şeyden daha hayırlıdır.', 'ولين قتلتم في سبيل الله او متم لمغفرة من الله ورحمة خير مما يجمعون'),
(451, 3, 158, 'وَلَئِنْ مُتُّمْ اَوْ قُتِلْتُمْ لَاِلَى اللّٰهِ تُحْشَرُونَ', 'Ve lein muttum ev kutiltum le ilallahi tuhşerun.', 'Elbette ölseniz de öldürülseniz de muhakkak sonunda Allah\'ın huzurunda toplanacaksınız.', 'ولين متم او قتلتم لالي الله تحشرون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(452, 3, 159, 'فَبِمَا رَحْمَةٍ مِنَ اللّٰهِ لِنْتَ لَهُمْۚ وَلَوْ كُنْتَ فَظًّا غَل۪يظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَۖ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِي الْاَمْرِۚ فَاِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللّٰهِۜ اِنَّ اللّٰهَ يُحِبُّ الْمُتَوَكِّل۪ينَ', 'Fe bima rahmetin minallahi linte lehum, ve lev kunte fazzan galizal kalbi lenfaddu min havlik, fa\'fu anhum vestagfir lehum ve şavirhum fil emr, fe iza azamte fe tevekkel alallah, innallahe yuhibbul mutevekkilin.', 'Allah\'tan gelen rahmet sayesinde onlara[1] yumuşak davrandın. Eğer kaba ve katı kalpli biri olsaydın etrafından dağılıp giderlerdi. Artık onları affet. Onlar için bağışlanma dile. Yapacağın işlerde onlara danış. Karar verdikten sonra da artık Allah\'a tevekkül[2] et. Kuşkusuz Allah,  kendisine tevekkül edenleri sever.', 'فبما رحمة من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الامر فاذا عزمت فتوكل علي الله ان الله يحب المتوكلين'),
(453, 3, 160, 'اِنْ يَنْصُرْكُمُ اللّٰهُ فَلَا غَالِبَ لَكُمْۚ وَاِنْ يَخْذُلْكُمْ فَمَنْ ذَا الَّذ۪ي يَنْصُرُكُمْ مِنْ بَعْدِه۪ۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'İn yansurkumullahu fe la galibe lekum, ve in yahzulkum fe menzellezi yansurukum min ba\'dih, ve alallahi fel yetevekkelil mu\'minun.', 'Eğer Allah,  size yardım ederse hiç kimse size güç yetiremez. Eğer sizi yardımsız bırakırsa,  ondan sonra size kim yardım edebilir? Mü\'minler,  yalnızca Allah\'a tevekkül etsinler.', 'ان ينصركم الله فلا غالب لكم وان يخذلكم فمن ذا الذي ينصركم من بعده وعلي الله فليتوكل المومنون'),
(454, 3, 161, 'وَمَا كَانَ لِنَبِيٍّ اَنْ يَغُلَّۜ وَمَنْ يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيٰمَةِۚ ثُمَّ تُوَفّٰى كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'Ve ma kane li nebiyyin en yagull, ve men yaglul ye\'ti bima galle yevmel kıyameh, summe tuveffa kullu nefsin ma kesebet ve hum la yuzlemun.', 'Bir nebinin,  emanete ihanet etmesi olur şey değildir![1] Kim ihanet ederse,  Kıyamet Günü,  ihanet ettiğiyle gelecektir. Sonra hiçbir haksızlık olmaksızın herkesin kazandığı tastamam verilecektir.', 'وما كان لنبي ان يغل ومن يغلل يات بما غل يوم القيمة ثم توفي كل نفس ما كسبت وهم لا يظلمون'),
(455, 3, 162, 'اَفَمَنِ اتَّبَعَ رِضْوَانَ اللّٰهِ كَمَنْ بَٓاءَ بِسَخَطٍ مِنَ اللّٰهِ وَمَأْوٰيهُ جَهَنَّمُۜ وَبِئْسَ الْمَص۪يرُ', 'E femenittebea rıdvanallahi ke men bae bi sehatin minallahi ve me\'vahu cehennem, ve bi\'sel masir.', 'Allah\'ın rızasını kazanan kimse,  Allah\'ın gazabına uğrayan ve varacağı yer Cehennem olan kimse ile bir olur mu? Orası ne kötü bir sonuçtur.', 'افمن اتبع رضون الله كمن با بسخط من الله وماويه جهنم وبيس المصير'),
(456, 3, 163, 'هُمْ دَرَجَاتٌ عِنْدَ اللّٰهِۜ وَاللّٰهُ بَص۪يرٌ بِمَا يَعْمَلُونَ۟', 'Hum derecatun indallah, vallahu basirun bi ma ya\'melun.', 'Onların,  Allah katındaki dereceleri farklıdır. Allah,  yaptıkları her şeyi görendir.', 'هم درجت عند الله والله بصير بما يعملون'),
(457, 3, 164, 'لَقَدْ مَنَّ اللّٰهُ عَلَى الْمُؤْمِن۪ينَ اِذْ بَعَثَ ف۪يهِمْ رَسُولاً مِنْ اَنْفُسِهِمْ يَتْلُوا عَلَيْهِمْ اٰيَاتِه۪ وَيُزَكّ۪يهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَۚ وَاِنْ كَانُوا مِنْ قَبْلُ لَف۪ي ضَلَالٍ مُب۪ينٍ', 'Le kad mennallahu alel mu\'minine iz bease fihim resulen min enfusihim yetlu aleyhim ayatihi ve yuzekkihim ve yuallimuhumul kitabe vel hikmeh, ve in kanu min kablu le fi dalalin mubin.', 'Ant olsun ki,  Allah,  içlerinden,  onlara ayetlerini okuyan,  onları arındıran,  onlara Kitap\'ı ve Hikmet\'i[1] öğreten bir resul göndermekle,  Mü\'minlere iyilikte bulundu Oysa onlar daha önce açık bir sapkınlık içindeydiler.', 'لقد من الله علي المومنين اذ بعث فيهم رسولا من انفسهم يتلوا عليهم ايته ويزكيهم ويعلمهم الكتب والحكمة وان كانوا من قبل لفي ضلل مبين'),
(458, 3, 165, 'اَوَلَمَّٓا اَصَابَتْكُمْ مُص۪يبَةٌ قَدْ اَصَبْتُمْ مِثْلَيْهَاۙ قُلْتُمْ اَنّٰى هٰذَاۜ قُلْ هُوَ مِنْ عِنْدِ اَنْفُسِكُمْۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'E ve lemma asabetkum musibetun kad asabtum misleyha, kultum enna haza, kul huve min indi enfusikum innallahe ala kulli şey\'in kadir.', 'İki katını tattırdığınız musibet,  kendinize isabet edince,  \"Bu nereden geldi\" mi diyorsunuz? De ki: \"Bu kendi nefsinizdendir.\" Kuşkusuz Allah Her Şeye Güç Yetiren\'dir.', 'اولما اصبتكم مصيبة قد اصبتم مثليها قلتم اني هذا قل هو من عند انفسكم ان الله علي كل شي قدير'),
(459, 3, 166, 'وَمَٓا اَصَابَكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ فَبِاِذْنِ اللّٰهِ وَلِيَعْلَمَ الْمُؤْمِن۪ينَۙ', 'Ve ma asabekum yevmel tekal cem\'ani fe bi iznillahi ve li ya\'lemel mu\'minin.', 'İki toplumun karşılaştığı gün,  başınıza gelen musibet,  Allah\'ın izniyleydi.[1] Bu Mü\'minlerin belirlenmesi içindi.', 'وما اصبكم يوم التقي الجمعان فباذن الله وليعلم المومنين'),
(460, 3, 167, 'وَلِيَعْلَمَ الَّذ۪ينَ نَافَقُواۚ وَق۪يلَ لَهُمْ تَعَالَوْا قَاتِلُوا ف۪ي سَب۪يلِ اللّٰهِ اَوِ ادْفَعُواۜ قَالُوا لَوْ نَعْلَمُ قِتَالاً لَاتَّبَعْنَاكُمْۜ هُمْ لِلْكُفْرِ يَوْمَئِذٍ اَقْرَبُ مِنْهُمْ لِلْا۪يمَانِۚ يَقُولُونَ بِاَفْوَاهِهِمْ مَا لَيْسَ ف۪ي قُلُوبِهِمْۜ وَاللّٰهُ اَعْلَمُ بِمَا يَكْتُمُونَۚ', 'Ve li ya\'lemellezine nafeku, ve kile lehum tealev katilu fi sebilillahi evidfeu kalu lev na\'lemu kıtalen letteba\'nakum, hum lil kufri yevmeizin akrabu minhum lil iman, yekulune bi efvahihim ma leyse fi kulubihim, vallahu a\'lemu bi ma yektumun.', 'Bir de münafık[1] olanların belirlenmesi içindi. Onlara: \"Gelin bizimle birlikte Allah yolunda savaşın veya savunmada bulunun.\" denildiğinde; onlar: \"Savaşı bilseydik[2] elbette size uyardık.\" dediler. Onlar,  İzin Günü,  imandan çok küfre yakındılar. Kalplerinde olmayan şeyi ağızlarıyla söylüyorlardı. Oysa Allah,  onların içlerinde sakladıklarını çok iyi bilmektedir.', 'وليعلم الذين نافقوا وقيل لهم تعالوا قتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالا لاتبعنكم هم للكفر يوميذ اقرب منهم للايمن يقولون بافوههم ما ليس في قلوبهم والله اعلم بما يكتمون'),
(461, 3, 168, 'اَلَّذ۪ينَ قَالُوا لِاِخْوَانِهِمْ وَقَعَدُوا لَوْ اَطَاعُونَا مَا قُتِلُواۜ قُلْ فَادْرَؤُ۫ا عَنْ اَنْفُسِكُمُ الْمَوْتَ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ellezine kalu li ihvanihim ve kaadu lev atauna ma kutil, kul fedreu an enfusikumul mevte in kuntum sadıkin.', 'Savaşa katılmayanlar,  kardeşleri için: \"Eğer onlar bize uysalardı öldürülmezlerdi.\" dediler. De ki: \"Eğer doğru söylüyorsanız,  o zaman ölümü kendinizden savın.\"', 'الذين قالوا لاخونهم وقعدوا لو اطاعونا ما قتلوا قل فادروا عن انفسكم الموت ان كنتم صدقين'),
(462, 3, 169, 'وَلَا تَحْسَبَنَّ الَّذ۪ينَ قُتِلُوا ف۪ي سَب۪يلِ اللّٰهِ اَمْوَاتاًۜ بَلْ اَحْيَٓاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَۙ', 'Ve la tahsebennellezine kutilu fi sebilillahi emvata, bel ahyaun inde rabbihim yurzekun.', 'Allah yolunda öldürülenleri ölü sanma.[1] Bilakis onlar diridirler,  Rabb\'leri katında rızıklanmaktadırlar.', 'ولا تحسبن الذين قتلوا في سبيل الله اموتا بل احيا عند ربهم يرزقون'),
(463, 3, 170, 'فَرِح۪ينَ بِمَٓا اٰتٰيهُمُ اللّٰهُ مِنْ فَضْلِه۪ۙ وَيَسْتَبْشِرُونَ بِالَّذ۪ينَ لَمْ يَلْحَقُوا بِهِمْ مِنْ خَلْفِهِمْۙ اَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۢ', 'Ferihine bi ma atahumullahu min fadlıhi, ve yestebşirune billezine lem yelhaku bihim min halfihim, ella havfun aleyhim ve la hum yahzenun.', 'Allah\'ın,  lütfundan,  kendilerine verdiklerine sevinirler. Arkalarından gelecek olanlara,  bir korkunun olmadığını ve üzülmeyeceklerini müjdelemek isterler.', 'فرحين بما اتيهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم الا خوف عليهم ولا هم يحزنون'),
(464, 3, 171, 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِنَ اللّٰهِ وَفَضْلٍۙ وَاَنَّ اللّٰهَ لَا يُض۪يعُ اَجْرَ الْمُؤْمِن۪ينَۚۛ ۟', 'Yestebşirune bi ni\'metin minallahi ve fadlin, ve ennallahe la yudiu ecrel mu\'minin.', 'Onlar; Allah\'ın nimetini,  lütfunu ve Allah\'ın mü\'minlerin ecirlerini[1] zayi etmeyeceğini müjdelemek isterler.', 'يستبشرون بنعمة من الله وفضل وان الله لا يضيع اجر المومنين'),
(465, 3, 172, 'اَلَّذ۪ينَ اسْتَجَابُوا لِلّٰهِ وَالرَّسُولِ مِنْ بَعْدِ مَٓا اَصَابَهُمُ الْقَرْحُۜۛ لِلَّذ۪ينَ اَحْسَنُوا مِنْهُمْ وَاتَّقَوْا اَجْرٌ عَظ۪يمٌۚ', 'Ellezinestecabu lillahi ver resuli min ba\'di ma asabehumul karh, lillezine ahsenu minhum vettekav ecrun azim.', 'Yaralanmalarına rağmen,  Allah ve Resul\'ünün davetine uyanlar,  iyilik yapanlar ve Allah için takvalı olanlar için çok değerli bir karşılık vardır.', 'الذين استجابوا لله والرسول من بعد ما اصابهم القرح للذين احسنوا منهم واتقوا اجر عظيم'),
(466, 3, 173, 'اَلَّذ۪ينَ قَالَ لَهُمُ النَّاسُ اِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ ا۪يمَاناًۗ وَقَالُوا حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَك۪يلُ', 'Ellezine kale lehumun nasu innen nase kad cemeu lekum fahşevhum fe zadehum imana, ve kalu hasbunallahu ve ni\'mel vekil.', '\"İnsanlar size karşı toplandılar,  onlara derin saygı duyun.\" diyenlerin sözleri,  onların imanlarını daha da artırdı: \"Allah bize yeter,  O ne güzel vekildir.[1]\" dediler.', 'الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمنا وقالوا حسبنا الله ونعم الوكيل'),
(467, 3, 174, 'فَانْقَلَبُوا بِنِعْمَةٍ مِنَ اللّٰهِ وَفَضْلٍ لَمْ يَمْسَسْهُمْ سُٓوءٌۙ وَاتَّبَعُوا رِضْوَانَ اللّٰهِۜ وَاللّٰهُ ذُوفَضْلٍ عَظ۪يمٍ', 'Fenkalebu bi ni\'metin minallahi ve fadlin lem yemseshum suun, vettebeu rıdvanallah, vallahu zu fadlin azim.', 'Ve Allah\'tan gelen nimet ve lütufla kendilerine bir kötülük dokunmadan geri döndüler. Allah\'ın rızasını kazandılar. Allah,  Büyük Lütuf Sahibi\'dir.', 'فانقلبوا بنعمة من الله وفضل لم يمسسهم سو واتبعوا رضون الله والله ذو فضل عظيم'),
(468, 3, 175, 'اِنَّمَا ذٰلِكُمُ الشَّيْطَانُ يُخَوِّفُ اَوْلِيَٓاءَهُۖ فَلَا تَخَافُوهُمْ وَخَافُونِ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'İnnema zalikumuş şeytanu yuhavvifu evliya\'eh, fe la tehafuhum ve hafuni in kuntum mu\'minin.', 'Şeytan,  ancak kendi velilerini[1] korkutur.[2] Eğer Mü\'minseniz,  onlardan korkmayın,  yalnızca Bana karşı gelmekten sakının.', 'انما ذلكم الشيطن يخوف اولياه فلا تخافوهم وخافون ان كنتم مومنين'),
(469, 3, 176, 'وَلَا يَحْزُنْكَ الَّذ۪ينَ يُسَارِعُونَ فِي الْكُفْرِۚ اِنَّهُمْ لَنْ يَضُرُّوا اللّٰهَ شَيْـٔاًۜ يُر۪يدُ اللّٰهُ اَلَّا يَجْعَلَ لَهُمْ حَظًّا فِي الْاٰخِرَةِۚ وَلَهُمْ عَذَابٌ عَظ۪يمٌ', 'Ve la yahzunkellezine yusariune fil kufr, innehum len yadurrullahe şey\'a, yuridullahu ella yec\'ale lehum hazzan fil ahireh, ve lehum azabun azim.', 'Küfrde yarışanlar,  seni üzmesin. Çünkü onlar,  Allah\'a hiçbir zarar veremezler. Allah,  onları ahirette nasipsiz bırakmak istiyor. Onlar için çok büyük bir azap vardır.', 'ولا يحزنك الذين يسرعون في الكفر انهم لن يضروا الله شيا يريد الله الا يجعل لهم حظا في الاخرة ولهم عذاب عظيم'),
(470, 3, 177, 'اِنَّ الَّذ۪ينَ اشْتَرَوُا الْكُفْرَ بِالْا۪يمَانِ لَنْ يَضُرُّوا اللّٰهَ شَيْـٔاًۚ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnellezineşteravul kufra bil imani len yedurrullahe şey\'a, ve lehum azabun elim.', 'İmana karşılık Küfrü[1] satın alanlar,  Allah\'a kesinlikle zarar veremezler. Onlar için can yakıcı bir azap vardır.', 'ان الذين اشتروا الكفر بالايمن لن يضروا الله شيا ولهم عذاب اليم'),
(471, 3, 178, 'وَلَا يَحْسَبَنَّ الَّذ۪ينَ كَفَرُٓوا اَنَّمَا نُمْل۪ي لَهُمْ خَيْرٌ لِاَنْفُسِهِمْۜ اِنَّمَا نُمْل۪ي لَهُمْ لِيَزْدَادُٓوا اِثْماًۚ وَلَهُمْ عَذَابٌ مُه۪ينٌ', 'Ve la yahsebennellezine keferu ennema numli lehum hayrun li enfusihim, innema numli lehum li yezdadu isma, ve lehum azabun muhin.', 'Kafirler,  kendilerine süre tanımamızın,  yararlarına olduğunu sanmasınlar. Onlara süre tanıyoruz,  onlar ise günahlarını artırıyorlar. Onlar için,  alçaltıcı bir azap vardır.', 'ولا يحسبن الذين كفروا انما نملي لهم خير لانفسهم انما نملي لهم ليزدادوا اثما ولهم عذاب مهين'),
(472, 3, 179, 'مَا كَانَ اللّٰهُ لِيَذَرَ الْمُؤْمِن۪ينَ عَلٰى مَٓا اَنْتُمْ عَلَيْهِ حَتّٰى يَم۪يزَ الْخَب۪يثَ مِنَ الطَّيِّبِۜ وَمَا كَانَ اللّٰهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ وَلٰكِنَّ اللّٰهَ يَجْتَب۪ي مِنْ رُسُلِه۪ مَنْ يَشَٓاءُ فَاٰمِنُوا بِاللّٰهِ وَرُسُلِه۪ۚ وَاِنْ تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ اَجْرٌ عَظ۪يمٌ', 'Ma kanallahu li yezerel mu\'minine ala ma entum aleyhi hatta yemizel habise minet tayyib, ve ma kanallahu li yutliakum alel gaybi ve lakinnallahe yectebi min rusulihi men yeşau fe aminu billahi ve rusulih, ve in tu\'minu ve tetteku fe lekum ecrun azim.', 'Allah,  tayyib[1] olanı habis[2] olandan ayırmadan; Mü\'minleri içinde bulunduğunuz şu durumda bırakacak değildir. Allah,  sizi gaipten[3] haberdar edecek de değildir. Ancak Allah,  resullerinden dilediğini seçer. O halde,  Allah\'a ve resullerine iman edin. Eğer iman edip,  takvalı davranırsanız,  sizin için büyük bir ödül vardır.', 'ما كان الله ليذر المومنين علي ما انتم عليه حتي يميز الخبيث من الطيب وما كان الله ليطلعكم علي الغيب ولكن الله يجتبي من رسله من يشا فامنوا بالله ورسله وان تومنوا وتتقوا فلكم اجر عظيم'),
(473, 3, 180, 'وَلَا يَحْسَبَنَّ الَّذ۪ينَ يَبْخَلُونَ بِمَٓا اٰتٰيهُمُ اللّٰهُ مِنْ فَضْلِه۪ هُوَ خَيْراً لَهُمْۜ بَلْ هُوَ شَرٌّ لَهُمْۜ سَيُطَوَّقُونَ مَا بَخِلُوا بِه۪ يَوْمَ الْقِيٰمَةِۜ وَلِلّٰهِ م۪يرَاثُ السَّمٰوَاتِ وَالْاَرْضِۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ۟', 'Ve la yahsebennellezine yebhalune bi ma atahumullahu min fadlıhi huve hayran lehum, bel huve şerrun lehum se yutavvekune ma bahilu bihi yevmel kıyameh, ve lillahi mirasus semavati vel ard, vallahu bi ma ta\'melune habir.', 'Allah\'ın,  lütuf olarak verdiği şeylerden cimrilik eden kimseler,  bu tutumlarının kendi yararına olacağını sanmasınlar. Bu,  onlar için sadece bir kötülüktür. Cimrilikle yanlarında tuttukları mal,  Kıyamet Günü boyunlarına dolanacaktır. Göklerin ve yeryüzünün mirası yalnızca Allah\'a aittir. Allah,  yaptığınız her şeyden haberdardır.', 'ولا يحسبن الذين يبخلون بما اتيهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيمة ولله ميرث السموت والارض والله بما تعملون خبير'),
(474, 3, 181, 'لَقَدْ سَمِـعَ اللّٰهُ قَوْلَ الَّذ۪ينَ قَالُٓوا اِنَّ اللّٰهَ فَق۪يرٌ وَنَحْنُ اَغْنِيَٓاءُۢ سَنَكْتُبُ مَا قَالُوا وَقَتْلَهُمُ الْاَنْبِيَٓاءَ بِغَيْرِ حَقٍّۙ وَنَقُولُ ذُوقُوا عَذَابَ الْحَر۪يقِ', 'Lekad semiallahu kavlellezine kalu innallahe fakirun ve nahnu agniyau se nektubu ma kalu ve katlehumul enbiyae bi gayri hakkın, ve nekulu zuku azabel harik.', '\"Allah fakirdir,  biz zenginiz.\" diyenlerin sözünü,  Allah elbette işitmiştir. Hem bu söylediklerini hem de haksız yere nebileri öldürmelerini yazacağız. Ve onlara,  \"Yakıcı azabı tadın.\" diyeceğiz.', 'لقد سمع الله قول الذين قالوا ان الله فقير ونحن اغنيا سنكتب ما قالوا وقتلهم الانبيا بغير حق ونقول ذوقوا عذاب الحريق'),
(475, 3, 182, 'ذٰلِكَ بِمَا قَدَّمَتْ اَيْد۪يكُمْ وَاَنَّ اللّٰهَ لَيْسَ بِظَلَّامٍ لِلْعَب۪يدِۚ', 'Zalike bima kaddemet eydikum ve ennallahe leyse bi zallamin lil abid.', 'Bu,  ellerinizle yaptığınız şeyin karşılığıdır. Yoksa Allah,  kullarına,  haksızlık edici değildir.', 'ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد'),
(476, 3, 183, 'اَلَّذ۪ينَ قَالُٓوا اِنَّ اللّٰهَ عَهِدَ اِلَيْنَٓا اَلَّا نُؤْمِنَ لِرَسُولٍ حَتّٰى يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ النَّارُۜ قُلْ قَدْ جَٓاءَكُمْ رُسُلٌ مِنْ قَبْل۪ي بِالْبَيِّنَاتِ وَبِالَّذ۪ي قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ellezine kalu innallahe ahide ileyna ella nu\'mine li resulin hatta ye\'tiyena bi kurbanin te\'kuluhun nar, kul kad caekum rusulun min kabli bil beyyinati ve billezi kultum fe lime kateltumuhum in kuntum sadıkin.', 'Onlar dediler ki: Allah,  \"Ateş tarafından yenen bir kurban[1] getirmedikçe,  hiçbir resule inanmamamız konusunda bizden söz aldı.\" De ki: \"Kuşkusuz,  benden önce nice resuller açık kanıtlarla ve sizin istediğiniz şeyi getirmişti. Eğer doğru söyleyenlerdenseniz,  onları niçin öldürdünüz?\"', 'الذين قالوا ان الله عهد الينا الا نومن لرسول حتي ياتينا بقربان تاكله النار قل قد جاكم رسل من قبلي بالبينت وبالذي قلتم فلم قتلتموهم ان كنتم صدقين'),
(477, 3, 184, 'فَاِنْ كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِنْ قَبْلِكَ جَٓاؤُ۫ بِالْبَيِّنَاتِ وَالزُّبُرِ وَالْكِتَابِ الْمُن۪يرِ', 'Fe in kezzebuke fe kad kuzzibe rusulun min kablike cau bil beyyinati vez zuburi vel kitabil munir.', 'Şimdi seni yalanlayanlar; senden önce açık kanıtlarla,  zeburlar[1] ve aydınlatıcı kitaplarla gelen resulleri de yalanlamışlardı.', 'فان كذبوك فقد كذب رسل من قبلك جاو بالبينت والزبر والكتب المنير'),
(478, 3, 185, 'كُلُّ نَفْسٍ ذَٓائِقَةُ الْمَوْتِۜ وَاِنَّمَا تُوَفَّوْنَ اُجُورَكُمْ يَوْمَ الْقِيٰمَةِۜ فَمَنْ زُحْزِحَ عَنِ النَّارِ وَاُدْخِلَ الْجَنَّةَ فَقَدْ فَازَۜ وَمَا الْحَيٰوةُ الدُّنْيَٓا اِلَّا مَتَاعُ الْغُرُورِ', 'Kullu nefsin zaikatul mevt, ve innema tuveffevne ucurekum yevmel kıyameh, fe men zuhziha anin nari ve udhılel cennete fe kad faz, ve mal hayatud dunya illa metaul gurur.', 'Her nefis ölümü tadıcıdır. Kıyamet Günü\'nde yaptıklarınızın karşılığı,  tam olarak verilecektir. Her kim Cehennem\'den uzaklaştırılıp Cennet\'e konursa,  kuşkusuz o kurtulmuştur. Zaten dünya hayatı,  aldatıcı geçimlikten başka bir şey değildir.', 'كل نفس ذايقة الموت وانما توفون اجوركم يوم القيمة فمن زحزح عن النار وادخل الجنة فقد فاز وما الحيوة الدنيا الا متع الغرور'),
(479, 3, 186, 'لَتُبْلَوُنَّ ف۪ٓي اَمْوَالِكُمْ وَاَنْفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذ۪ينَ اَشْرَكُٓوا اَذًى كَث۪يراًۜ وَاِنْ تَصْبِرُوا وَتَتَّقُوا فَاِنَّ ذٰلِكَ مِنْ عَزْمِ الْاُمُورِ', 'Le tublevunne fi emvalikum ve enfusikum ve le tesmeunne minellezine utul kitabe min kablikum ve minellezine eşraku ezen kesira, ve in tasbiru ve tetteku fe inne zalike min azmil umur.', 'Mallarınızla ve canlarınızla deneneceksiniz. Sizden önce kendilerine kitap verilenlerden ve şirk koşanlardan çok üzücü sözler işiteceksiniz. Eğer sabreder ve takvalı olursanız,  bilin ki bu,  kesin kararlılık gösterilmesi gereken işlerdendir.', 'لتبلون في امولكم وانفسكم ولتسمعن من الذين اوتوا الكتب من قبلكم ومن الذين اشركوا اذي كثيرا وان تصبروا وتتقوا فان ذلك من عزم الامور'),
(480, 3, 187, 'وَاِذْ اَخَذَ اللّٰهُ م۪يثَاقَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُۘ فَنَبَذُوهُ وَرَٓاءَ ظُهُورِهِمْ وَاشْتَرَوْا بِه۪ ثَمَناً قَل۪يلاًۜ فَبِئْسَ مَا يَشْتَرُونَ', 'Ve iz ehazallahu misakallezine utul kitabe le tubeyyinunnehu lin nasi ve la tektumuneh, fe nebezuhu verae zuhurihim veşterav bihi semenen kalila, fe bi\'se ma yeşterun.', 'Hani Allah,  Kitap Ehli\'nden,  onu insanlara açıklayacaklarına ve asla gizlemeyeceklerine dair kesin bir söz almıştı. Fakat onlar,  az bir çıkar karşılığı,  bu sözlerine sırt çevirdiler. Bu ne kötü bir alışveriştir!', 'واذ اخذ الله ميثق الذين اوتوا الكتب لتبيننه للناس ولا تكتمونه فنبذوه ورا ظهورهم واشتروا به ثمنا قليلا فبيس ما يشترون'),
(481, 3, 188, 'لَا تَحْسَبَنَّ الَّذ۪ينَ يَفْرَحُونَ بِمَٓا اَتَوْا وَيُحِبُّونَ اَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا فَلَا تَحْسَبَنَّهُمْ بِمَفَازَةٍ مِنَ الْعَذَابِۚ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'La tahsebennellezine yefrahune bi ma etev ve yuhıbbune en yuhmedu bi ma lem yef\'alu fe la tahsebennehum bi mefazetin minel azab, ve lehum azabun elim.', 'Yaptıklarıyla sevinen,  yapmadıkları şeylerle övülmeyi seven kimselerin,  azaptan kurtulacaklarını sanma. Onlar için can yakıcı bir azap vardır.', 'لا تحسبن الذين يفرحون بما اتوا ويحبون ان يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من العذاب ولهم عذاب اليم'),
(482, 3, 189, 'وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ۟', 'Ve lillahi mulkus semavati vel ard, vallahu ala kulli şey\'in kadir.', 'Göklerin ve yerin mülkü[1] Allah\'a aittir. Allah,  Her Şeye Güç Yetiren\'dir.', 'ولله ملك السموت والارض والله علي كل شي قدير'),
(483, 3, 190, 'اِنَّ ف۪ي خَلْقِ السَّمٰوَاتِ وَالْاَرْضِ وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ لَاٰيَاتٍ لِاُو۬لِي الْاَلْبَابِۚ', 'İnne fi halkıs semavati vel ardı vahtilafil leyli ven nehari le ayatin li ulil elbab.', 'Kuşkusuz,  göklerin ve yerin yaradılışında,  gece ile gündüzün art arda gelişinde,  sağlıklı düşünenler için kesin kanıtlar vardır.', 'ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب'),
(484, 3, 191, 'اَلَّذ۪ينَ يَذْكُرُونَ اللّٰهَ قِيَاماً وَقُعُوداً وَعَلٰى جُنُوبِهِمْ وَيَتَفَكَّرُونَ ف۪ي خَلْقِ السَّمٰوَاتِ وَالْاَرْضِۚ رَبَّنَا مَا خَلَقْتَ هٰذَا بَاطِلاًۚ سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ', 'Ellezine yezkurunallahe kıyamen ve kuuden ve ala cunubihim ve yetefekkerune fi halkıs semavati vel ard, rabbena ma halakte haza batıla, subhaneke fekına azaben nar.', 'Onlar; ayaktayken,  otururken ve yanları üzerine iken Allah\'ı anarlar.[1] Göklerin ve yerin yaradılışı hakkında düşünürler: \"Rabb\'imiz! Sen,  bunu boşuna yaratmadın,  Seni her türlü noksanlıktan tenzih ederiz. Bizi ateşin azabından koru.\"', 'الذين يذكرون الله قيما وقعودا وعلي جنوبهم ويتفكرون في خلق السموت والارض ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار'),
(485, 3, 192, 'رَبَّنَٓا اِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ اَخْزَيْتَهُۜ وَمَا لِلظَّالِم۪ينَ مِنْ اَنْصَارٍ', 'Rabbena inneke men tudhılin nare fe kad ahzeyteh, ve ma liz zalimine min ensar.', '\"Ey Rabb\'imiz! Kuşkusuz,  kimi ateşe sokarsan,  onu perişan edersin. Zalimlerin yardımcıları yoktur.\"', 'ربنا انك من تدخل النار فقد اخزيته وما للظلمين من انصار'),
(486, 3, 193, 'رَبَّنَٓا اِنَّـنَا سَمِعْنَا مُنَادِياً يُنَاد۪ي لِلْا۪يمَانِ اَنْ اٰمِنُوا بِرَبِّكُمْ فَاٰمَنَّاۗ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّـنَا مَعَ الْاَبْرَارِۚ', 'Rabbena innena semi\'na munadiyen yunadi lil imani en aminu bi rabbikum fe amenna, rabbena fagfir lena zunubena ve keffir anna seyyiatina ve teveffena meal ebrar.', '\"Ey Rabb\'imiz! Biz,  \"Rabb\'inize iman edin.\" diye,  iman etmeye çağıran bir davetçiyi işittik ve hemen iman ettik. Rabb\'imiz! Suçlarımızı bağışla,  kötülüklerimizi ört ve canımızı iyilikle al.\"', 'ربنا اننا سمعنا مناديا ينادي للايمن ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سياتنا وتوفنا مع الابرار'),
(487, 3, 194, 'رَبَّنَا وَاٰتِنَا مَا وَعَدْتَنَا عَلٰى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيٰمَةِۜ اِنَّكَ لَا تُخْلِفُ الْم۪يعَادَ', 'Rabbena ve atina ma vaadtena ala rusulike ve la tuhzina yevmel kıyameh, inneke la tuhliful miad.', '\"Rabb\'imiz! Resullerinin diliyle vadettiklerini bize ver,  Kıyamet Günü\'nde bizi alçaltma; kuşkusuz,  Sen,  verdiğin sözden dönmezsin.\"', 'ربنا واتنا ما وعدتنا علي رسلك ولا تخزنا يوم القيمة انك لا تخلف الميعاد'),
(488, 3, 195, 'فَاسْتَجَابَ لَهُمْ رَبُّهُمْ اَنّ۪ي لَٓا اُض۪يعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ اَوْ اُنْثٰىۚ بَعْضُكُمْ مِنْ بَعْضٍۚ فَالَّذ۪ينَ هَاجَرُوا وَاُخْرِجُوا مِنْ دِيَارِهِمْ وَاُو۫ذُوا ف۪ي سَب۪يل۪ي وَقَاتَلُوا وَقُتِلُوا لَاُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَاُدْخِلَنَّهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۚ ثَوَاباً مِنْ عِنْدِ اللّٰهِۜ وَاللّٰهُ عِنْدَهُ حُسْنُ الثَّوَابِ', 'Festecabe lehum rabbuhum enni la udiu amele amilin minkum min zekerin ev unsa, ba\'dukum min ba\'d, fellezine haceru ve uhricu min diyarihim ve uzu fi sebili ve katelu ve kutilu le ukeffirenne anhum seyyiatihim ve le udhılennehum cennatin tecri min tahtihal enhar, sevaben min indillah vallahu indehu husnus sevab.', 'Ve Rabb\'leri,  onlara cevap verdi: \"Ben,  sizden; erkek olsun,  kadın olsun -ki hepiniz birbirinizdensiniz- iyi şeyler yapanların yaptıklarının karşılığını boşa çıkarmam. Onlar ki benim yolumda hicret edenler,  yurtlarından çıkarılanlar,  yolumda eziyet görenler,  savaşanlar ve öldürülenlerdir. İşte bunların kötülüklerini örterim. Onların yaptıklarının karşılığı Allah\'ın yanındadır. Kuşkusuz,  onları içinden nehirler akan Cennetlere koyacağım. Karşılıkların en iyisi,  Allah katındadır.\"', 'فاستجاب لهم ربهم اني لا اضيع عمل عمل منكم من ذكر او انثي بعضكم من بعض فالذين هاجروا واخرجوا من ديرهم واوذوا في سبيلي وقتلوا وقتلوا لاكفرن عنهم سياتهم ولادخلنهم جنت تجري من تحتها الانهر ثوابا من عند الله والله عنده حسن الثواب'),
(489, 3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذ۪ينَ كَفَرُوا فِي الْبِلَادِۜ', 'La yegurranneke tekallubelluzine keferu fil bilad.', 'Kafirlerin[1] diyar diyar gezip dolaşmaları sakın seni aldatmasın.', 'لا يغرنك تقلب الذين كفروا في البلد'),
(490, 3, 197, 'مَتَاعٌ قَل۪يلٌ ثُمَّ مَأْوٰيهُمْ جَهَنَّمُۜ وَبِئْسَ الْمِهَادُ', 'Metaun kalilun summe me\'vahum cehennem, ve bi\'sel mihad.', 'Bu,  az bir yararlanmadır. Sonra varacakları yer Cehennem\'dir. Orası ne kötü bir yerdir!', 'متع قليل ثم ماويهم جهنم وبيس المهاد'),
(491, 3, 198, 'لٰكِنِ الَّذ۪ينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَا نُزُلاً مِنْ عِنْدِ اللّٰهِۜ وَمَا عِنْدَ اللّٰهِ خَيْرٌ لِلْاَبْرَارِ', 'Lakinillezinettekav rabbehum lehum cennatun tecri min tahtihal enharu halidine fiha nuzulen min indillah, ve ma indallahi hayrun lil ebrar.', 'Fakat Rabb\'lerine karşı gelmekten sakınan kimseler için,  içinden ırmaklar akan Cennetler vardır. Onlar,  orada sürekli kalıcıdırlar. Bu,  Allah katından bir konaklamadır. İyi kimseler için,  Allah katında olan daha hayırlıdır.', 'لكن الذين اتقوا ربهم لهم جنت تجري من تحتها الانهر خلدين فيها نزلا من عند الله وما عند الله خير للابرار'),
(492, 3, 199, 'وَاِنَّ مِنْ اَهْلِ الْكِتَابِ لَمَنْ يُؤْمِنُ بِاللّٰهِ وَمَٓا اُنْزِلَ اِلَيْكُمْ وَمَٓا اُنْزِلَ اِلَيْهِمْ خَاشِع۪ينَ لِلّٰهِۙ لَا يَشْتَرُونَ بِاٰيَاتِ اللّٰهِ ثَمَناً قَل۪يلاًۜ اُو۬لٰٓئِكَ لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۜ اِنَّ اللّٰهَ سَر۪يعُ الْحِسَابِ', 'Ve inne min ehlil kitabi le men yu\'minu billahi ve ma unzile ileykum ve ma unzile ileyhim haşiine lillahi, la yeşterune bi ayatillahi semenen kalila, ulaike lehum ecruhum inde rabbihim innallahe seriul hısab.', 'Kitap Ehli\'nden öyle kimseler var ki,  Allah\'a,  size indirilene,  kendilerine indirilene tam bir samimiyetle iman ederler. Allah\'ın ayetlerini az bir değer karşılığında satmazlar. İşte onların hak ettikleri şey Rabb\'lerinin yanındadır. Kuşkusuz,  Allah,  hesabı çabuk görendir.', 'وان من اهل الكتب لمن يومن بالله وما انزل اليكم وما انزل اليهم خشعين لله لا يشترون بايت الله ثمنا قليلا اوليك لهم اجرهم عند ربهم ان الله سريع الحساب'),
(493, 3, 200, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُونَ', 'Ya eyyuhellezine amenusbiru ve sabiru ve rabitu vettekullahe leallekum tuflihun.', 'Ey iman edenler! Sabredin ve zorluklara karşı dirençli olun. Sürekli duyarlı olun. Allah\'a karşı takva sahibi olun. Umulur ki kurtuluşa erenlerden olursunuz.', 'يايها الذين امنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون'),
(494, 4, 1, 'يَٓا اَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذ۪ي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالاً كَث۪يراً وَنِسَٓاءًۚ وَاتَّقُوا اللّٰهَ الَّذ۪ي تَسَٓاءَلُونَ بِه۪ وَالْاَرْحَامَۜ اِنَّ اللّٰهَ كَانَ عَلَيْكُمْ رَق۪يباً', 'Ya eyyuhan nasutteku rabbekumullezi halakakum min nefsin vahidetin ve halaka minha zevceha ve besse minhuma ricalen kesiran ve nisaa, vettekullahellezi tesaelune bihi vel erham. İnnallahe kane aleykum rakiba.', 'Ey insanlar! Sizi,  tek bir nefisten[1] yaratan,  ondan[2] eşini yaratan ve o ikisinden birçok erkek ve kadını üreten Rabb\'inize karşı takvalı[3] olun. Birbirinizden yararlanasınız diye akrabalık bağını kuran Allah\'a karşı takvalı[2] olun. Kuşkusuz,  Allah,  sizi gözetmektedir.', 'يايها الناس اتقوا ربكم الذي خلقكم من نفس وحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونسا واتقوا الله الذي تسالون به والارحام ان الله كان عليكم رقيبا'),
(495, 4, 2, 'وَاٰتُوا الْيَتَامٰٓى اَمْوَالَهُمْ وَلَا تَتَبَدَّلُوا الْخَب۪يثَ بِالطَّيِّبِۖ وَلَا تَأْكُلُٓوا اَمْوَالَهُمْ اِلٰٓى اَمْوَالِكُمْۜ  اِنَّهُ كَانَ حُوباً كَب۪يراً', 'Ve atul yetama emvalehum ve la tetebeddelul habise bit tayyib, ve la te\'kulu emvalehum ila emvalikum. İnnehu kane huben kebira.', 'Yetimlere,  mallarını verin; onların iyi mallarını kötü mallarınızla değiştirmeyin. Onların mallarını,  kendi mallarınıza karıştırarak yemeyin. Kuşkusuz,  bu büyük bir vebaldir!', 'واتوا اليتمي امولهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا اموالهم الي امولكم انه كان حوبا كبيرا'),
(496, 4, 3, 'وَاِنْ خِفْتُمْ اَلَّا تُـقْسِطُوا فِي الْيَتَامٰى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَٓاءِ مَثْنٰى وَثُلٰثَ وَرُبَاعَۚ فَاِنْ خِفْتُمْ اَلَّا تَعْدِلُوا فَوَاحِدَةً اَوْ مَا مَلَكَتْ اَيْمَانُكُمْۜ ذٰلِكَ اَدْنٰٓى اَلَّا تَعُولُواۜ', 'Ve in hıftum ella tuksitu fil yetama fenkihu ma tabe lekum minen nisai mesna ve sulase ve rubaa, fe in hıftum ella ta\'dilu fe vahideten ev ma meleket eymanukum. Zalike edna ella teulu.', 'Eğer yetimler[1] konusunda hakkaniyetli olamayacağınızdan korktuysanız,  o zaman uygun olan[2] o kadınlardan[3] ikişer,  üçer,  dörder nikahlayın. Eğer o takdirde de adaleti gözetemeyeceğinizden korktuysanız,  o zaman bir tanesini ya da Yeminle[4] hak sahibi olduğunuzu[5] nikahlayın. Haksızlık etmemek için en uygun olan budur.', 'وان خفتم الا تقسطوا في اليتمي فانكحوا ما طاب لكم من النسا مثني وثلث وربع فان خفتم الا تعدلوا فوحدة او ما ملكت ايمنكم ذلك ادني الا تعولوا'),
(497, 4, 4, 'وَاٰتُوا النِّسَٓاءَ صَدُقَاتِهِنَّ نِحْلَةًۜ  فَاِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْساً فَكُلُوهُ هَن۪ٓيـٔاً مَر۪ٓيـٔاً', 'Ve atun nisae sadukatihinne nıhleh. Fe in tıbne lekum an şey\'in minhu nefsen fe kuluhu henien meria.', 'O kadınlara,  vadettiklerinizi bir hak olarak verin. Eğer gönül rızası ile ondan bir kısmını size verirlerse,  o zaman onu dilediğiniz gibi yiyin.', 'واتوا النسا صدقتهن نحلة فان طبن لكم عن شي منه نفسا فكلوه هنيا مريا'),
(498, 4, 5, 'وَلَا تُؤْتُوا السُّفَـهَٓاءَ اَمْوَالَكُمُ الَّت۪ي جَعَلَ اللّٰهُ لَكُمْ قِيَاماً وَارْزُقُوهُمْ ف۪يهَا وَاكْسُوهُمْ وَقُولُوا لَهُمْ قَوْلاً مَعْرُوفاً', 'Ve la tu\'tus sufehae emvalekumulleti cealallahu lekum kıyamen verzukuhum fiha veksuhum ve kulu lehum kavlen ma\'rufa.', 'Allah\'ın,  sizi kaim kıldığı[1] malların idaresini aklı ermezlere[2] bırakmayın. O mallarla onların geçimlerini temin edin ve onları giydirin. Onlara uygun şekilde davranın.', 'ولا توتوا السفها امولكم التي جعل الله لكم قيما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا'),
(499, 4, 6, 'وَابْتَلُوا الْيَتَامٰى حَتّٰٓى اِذَا بَلَغُوا النِّكَاحَۚ فَاِنْ اٰنَسْتُمْ مِنْهُمْ رُشْداً فَادْفَعُٓوا اِلَيْهِمْ اَمْوَالَهُمْۚ وَلَا تَأْكُلُوهَٓا اِسْرَافاً وَبِدَاراً اَنْ يَكْـبَرُواۜ وَمَنْ كَانَ غَنِياًّ فَلْيَسْتَعْفِفْۚ وَمَنْ كَانَ فَق۪يراً فَلْيَأْكُلْ بِالْمَعْرُوفِۜ فَاِذَا دَفَعْتُمْ اِلَيْهِمْ اَمْوَالَهُمْ فَاَشْهِدُوا عَلَيْهِمْۜ وَكَفٰى بِاللّٰهِ حَس۪يباً', 'Vebtelul yetama hatta iza belagun nikah, fe in anestum minhum ruşden fedfeu ileyhim emvalehum, ve la te\'kuluha israfen ve bidaren en yekberu. Ve men kane ganiyyen felyesta\'fif, ve men kane fakiran felye\'kul bil ma\'ruf. Fe iza defa\'tum ileyhim emvalehum fe eşhidu aleyhim. Ve kefa billahi hasiba.', 'Yetimlerinizi,  nikah çağına erişinceye kadar gözetleyin. Olgunluk yaşına[1] geldiklerinde mallarını kendilerine verin. Büyüyünce onlara kalacak düşüncesiyle,  mallarını acelece ve haddi aşarak yemeyin. Durumu iyi olan malı yemeye tenezzül etmesin. Durumu iyi olmayan da maldan uygun bir şekilde yararlansın. Onlara mallarını teslim ettiğinizde,  onlar adına tanıklar bulundurun. Hesap görücü olarak Allah yeter.', 'وابتلوا اليتمي حتي اذا بلغوا النكاح فان انستم منهم رشدا فادفعوا اليهم امولهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم امولهم فاشهدوا عليهم وكفي بالله حسيبا'),
(500, 4, 7, 'لِلرِّجَالِ نَص۪يبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالْاَقْرَبُونَۖ وَلِلنِّسَٓاءِ نَص۪يبٌ مِمَّا تَرَكَ الْوَالِدَانِ وَالْاَقْرَبُونَ مِمَّا قَلَّ مِنْهُ اَوْ كَثُرَۜ نَص۪يباً مَفْرُوضاً', 'Lir ricali nasibun mimma terakel validani vel akrabune, ve lin nisai nasibun mimma terakel validani vel akrabune mimma kalle minhu ev kesur. Nasiben mefruda.', 'Anne,  baba ve yakın akrabanın bıraktıklarından; erkeklere,  anne ve baba ile yakın akrabanın bıraktıklarından; kadınlara,  az olsun çok olsun farz olarak[1] bir pay vardır.[2]', 'للرجال نصيب مما ترك الولدان والاقربون وللنسا نصيب مما ترك الولدان والاقربون مما قل منه او كثر نصيبا مفروضا'),
(501, 4, 8, 'وَاِذَا حَضَرَ الْقِسْمَةَ اُو۬لُوا الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينُ فَارْزُقُوهُمْ مِنْهُ وَقُولُوا لَهُمْ قَوْلاً مَعْرُوفاً', 'Ve iza hadaral kısmete ulul kurba vel yetama vel mesakinu ferzukuhum minhu ve kulu lehum kavlen ma\'rufa.', 'Mirasın paylaşılması esnasında,  orada bulunan yakınları,  yetimleri ve yoksulları da yararlandırın ve onları incitmeyecek bir üslup kullanın.', 'واذا حضر القسمة اولوا القربي واليتمي والمسكين فارزقوهم منه وقولوا لهم قولا معروفا'),
(502, 4, 9, 'وَلْيَخْشَ الَّذ۪ينَ لَوْ تَرَكُوا مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَافاً خَافُوا عَلَيْهِمْۖ فَلْيَتَّقُوا اللّٰهَ وَلْيَقُولُوا قَوْلاً سَد۪يداً', 'Velyahşellezine lev teraku min halfihim zurriyeten dıafen hafu aleyhim, felyettekullahe velyekulu kavlen sedida.', 'Arkalarında küçük ve aciz evlat bırakanlar,  onlara karşı nasıl endişe duyuyorlarsa,  aynı endişeyi onlar[1] hakkında da duysunlar. Allah\'a karşı takva[2] ehli olsunlar ve doğru olan şey neyse onu söylesinler.', 'وليخش الذين لو تركوا من خلفهم ذرية ضعفا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا'),
(503, 4, 10, 'اِنَّ الَّذ۪ينَ يَأْكُلُونَ اَمْوَالَ الْيَتَامٰى ظُلْماً اِنَّمَا يَأْكُلُونَ ف۪ي بُطُونِهِمْ نَاراًۜ وَسَيَصْلَوْنَ سَع۪يراً۟', 'İnnellezine ye\'kulune emvalel yetama zulmen innema ye\'kulune fi butunihim nara. Ve se yaslevne seira.', 'Haksız şekilde yetimlerin mallarını yiyen kimseler,  ancak karınlarına ateş doldurmuş olurlar. İşte onlar,  yakında kızgın alevli ateşe atılacaklardır.', 'ان الذين ياكلون امول اليتمي ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا'),
(504, 4, 11, 'يُوص۪يكُمُ اللّٰهُ ف۪ٓي اَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْاُنْثَيَيْنِۚ فَاِنْ كُنَّ نِسَٓاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۚ وَاِنْ كَانَتْ وَاحِدَةً فَلَهَا النِّصْفُۜ وَلِاَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ اِنْ كَانَ لَهُ وَلَدٌۚ فَاِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُٓ اَبَوَاهُ فَلِاُمِّهِ الثُّلُثُۚ فَاِنْ كَانَ لَهُٓ اِخْوَةٌ فَلِاُمِّهِ السُّدُسُ مِنْ بَعْدِ وَصِيَّةٍ يُوص۪ي بِهَٓا اَوْ دَيْنٍۜ اٰبَٓاؤُ۬كُمْ وَاَبْنَٓاؤُ۬كُمْۚ لَا تَدْرُونَ اَيُّهُمْ اَقْرَبُ لَكُمْ نَفْعاًۚ فَر۪يضَةً مِنَ اللّٰهِۜ  اِنَّ اللّٰهَ كَانَ عَل۪يماً حَك۪يماً', 'Yusikumullahu fi evladikum liz zekeri mislu hazzıl unseyeyn, fe in kunne nisaen fevkasneteyni fe lehunne sulusa ma terak, ve in kanet vahideten fe lehan nısf. Ve li ebeveyhi li kulli vahidin min humas sudusu mimma terake in kane lehu veled, fe in lem yekun lehu veledun ve varisehu ebevahu fe li ummihis sulus, fe in kane lehu ıhvetun fe li ummihis sudusu, min ba\'di vasiyyetin yusi biha ev deyn. Abaukum ve ebnaukum, la tedrune eyyuhum akrabu lekum nef\'a, faridaten minallah. İnnallahe kane alimen hakima.', 'Allah size çocuklarınız hakkında tavsiye eder: Erkek çocuğun payı kız çocuğunun iki katıdır.[1] Eğer ikiden fazla kadın iseler miras üçte iki onlarındır. Eğer bir kadın ise mirasın yarısı onundur. Eğer ölenin çocuğu varsa,  anne ve babanın her birine mirastan altıda bir pay vardır. Eğer ölenin çocuğu yok da anne ve baba mirasçı olmuşsa,  anneye üçte bir pay vardır. Eğer ölenin kardeşleri varsa,  anneye altıda bir pay düşer. Bu paylaşma,  ölenin yaptığı vasiyetten ve borçlarının ödenmesinden sonradır. Babalarınız ve oğullarınızdan hangisinin size fayda bakımından daha yakın olduğunu bilemezsiniz. Bu,  Allah\'ın farz kıldığı[2] hükümdür. Kuşkusuz,  Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يوصيكم الله في اولدكم للذكر مثل حظ الانثيين فان كن نسا فوق اثنتين فلهن ثلثا ما ترك وان كانت وحدة فلها النصف ولابويه لكل وحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوة فلامه السدس من بعد وصية يوصي بها او دين اباوكم وابناوكم لا تدرون ايهم اقرب لكم نفعا فريضة من الله ان الله كان عليما حكيما'),
(505, 4, 12, 'وَلَكُمْ نِصْفُ مَا تَرَكَ اَزْوَاجُكُمْ اِنْ لَمْ يَكُنْ لَهُنَّ وَلَدٌۚ فَاِنْ كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ مِمَّا تَرَكْنَ مِنْ بَعْدِ وَصِيَّةٍ يُوص۪ينَ بِهَٓا اَوْ دَيْنٍۜ وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ اِنْ لَمْ يَكُنْ لَكُمْ وَلَدٌۚ فَاِنْ كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ الثُّمُنُ مِمَّا تَرَكْتُمْ مِنْ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَٓا اَوْ دَيْنٍۜ وَاِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً اَوِ امْرَاَةٌ وَلَهُٓ اَخٌ اَوْ اُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُۚ فَاِنْ كَانُٓوا اَكْثَرَ مِنْ ذٰلِكَ فَهُمْ شُرَكَٓاءُ فِي الثُّلُثِ مِنْ بَعْدِ وَصِيَّةٍ يُوصٰى بِهَٓا اَوْ دَيْنٍۙ غَيْرَ مُضَٓارٍّۚ وَصِيَّةً مِنَ اللّٰهِۜ وَاللّٰهُ عَل۪يمٌ حَل۪يمٌۜ', 'Ve lekum nısfu ma terake ezvacukum in lem yekun lehunne veled, fe in kane lehunne veledun fe lekumur rubuu mimma terakne min ba\'di vasıyyetin yusine biha ev deyn. Ve lehunner rubuu mimma teraktum in lem yekun lekum veled, fe in kane lekum veledun fe lehunnes sumunu mimma teraktum min ba\'di vasıyyetin tusune biha ev deyn. Ve in kane raculun yurasu kelaleten ev imraetun ve lehu ahun ev uhtun fe li kulli vahidin min humas sudus, fe in kanu eksera min zalike fe hum şurakau fis sulusi min ba\'di vasiyyetin yusa biha ev deynin gayra mudarr, vasıyyeten minallah. Vallahu alimun halim.', 'Eğer,  hanımlarınızın çocukları yoksa bıraktıklarının yarısı sizindir. Eğer,  çocukları varsa,  bıraktıklarının dörtte biri sizindir. Bu,  yaptığı vasiyetten ve borçlarının ödenmesinden sonradır. Eğer çocuğunuz yoksa bıraktığınızın dörtte biri hanımlarınızındır. Eğer çocuğunuz varsa bıraktığınızın sekizde biri onlarındır. Bu,  yaptığınız vasiyetten ve borçlarınızın ödenmesinden sonradır.[1] Kocanın veya hanımın anne,  baba ve çocukları bulunmadığı takdirde miras bırakır ve kendisinin bir erkek veya bir kız kardeşi varsa her birine altıda bir düşer. Bundan daha fazla iseler mirasın üçte birine ortaktırlar. Bu paylaşma,  kimse zarara uğratılmaksızın yapılacaktır. Bu,  vasiyetten ve borçların ödenmesinden sonradır. Bu,  Allah\'tan bir tavsiyedir. Allah,  Her Şeyi Bilen\'dir,  Çok Şefkatli\'dir.', 'ولكم نصف ما ترك ازوجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها او دين وان كان رجل يورث كللة او امراة وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركا في الثلث من بعد وصية يوصي بها او دين غير مضار وصية من الله والله عليم حليم'),
(506, 4, 13, 'تِلْكَ حُدُودُ اللّٰهِۜ وَمَنْ يُطِـعِ اللّٰهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ وَذٰلِكَ الْفَوْزُ الْعَظ۪يمُ', 'Tilke hududullah. Ve men yutııllahe ve resulehu yudhılhu cennatin tecri min tahtihal enharu halidine fiha. Ve zalikel fevzul azim.', 'İşte bunlar,  Allah\'ın yasalarıdır. Kim Allah\'a ve Resul\'üne[1] itaat ederse,  onu içinden ırmaklar akan Cennetlere koyacak,  orada sürekli olarak kalacaktır. İşte büyük başarı budur.', 'تلك حدود الله ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر خلدين فيها وذلك الفوز العظيم'),
(507, 4, 14, 'وَمَنْ يَعْصِ اللّٰهَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَاراً خَالِداً ف۪يهَاۖ وَلَهُ عَذَابٌ مُه۪ينٌ۟', 'Ve men ya\'sıllahe ve resulehu ve yeteadde hududehu yudhılhu naran haliden fiha.Ve lehu azabun muhin.', 'Kim de Allah\'a ve Resul\'üne[1] karşı asilik edip O\'nun yasalarını çiğnerse,  sürekli kalmak üzere ateşe konacaktır. Ve onun için alçaltıcı bir azap vardır.', 'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خلدا فيها وله عذاب مهين'),
(508, 4, 15, 'وَالّٰت۪ي يَأْت۪ينَ الْفَاحِشَةَ مِنْ نِسَٓائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ اَرْبَعَةً مِنْكُمْۚ فَاِنْ شَهِدُوا فَاَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتّٰى يَتَوَفّٰيهُنَّ الْمَوْتُ اَوْ يَجْعَلَ اللّٰهُ لَهُنَّ سَب۪يلاً', 'Vellati ye\'tinel fahişete min nisaikum festeşhidu aleyhinne erbaaten minkum, fe in şehidu fe emsikuhunne fil buyuti hatta yeteveffahunnel mevtu ev yec\'alallahu lehunne sebila.', 'Kadınlarınızdan fahişelik[1] yapanlara gelince; onların fahişelik yaptıklarına dair aranızdan dört kişinin tanıklık yapması halinde; onları,  ölüm alıp götürünceye veya Allah onlara bir yol gösterinceye kadar evlerinde gözetim altında tutun.', 'والتي ياتين الفحشة من نسايكم فاستشهدوا عليهن اربعة منكم فان شهدوا فامسكوهن في البيوت حتي يتوفيهن الموت او يجعل الله لهن سبيلا'),
(509, 4, 16, 'وَالَّذَانِ يَأْتِيَانِهَا مِنْكُمْ فَاٰذُوهُمَاۚ فَاِنْ تَابَا وَاَصْلَحَا فَاَعْرِضُوا عَنْهُمَاۜ اِنَّ اللّٰهَ كَانَ تَـوَّاباً رَح۪يماً', 'Vellezani ye\'tiyaniha minkum fe azuhuma, fe in taba ve asleha fe a\'rıdu anhuma. İnnallahe kane tevvaben rahima.', 'Sizden onu[1] yapan iki er kişiye de eziyet edin[2]. Eğer tevbe eder,  kendilerini düzeltirlerse onları rahat bırakın.[3] Allah,  Tevbeleri Kabul Eden\'dir ve Rahmeti Kesintisiz Olan\'dır.', 'والذان ياتينها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما'),
(510, 4, 17, 'اِنَّمَا التَّوْبَةُ عَلَى اللّٰهِ لِلَّذ۪ينَ يَعْمَلُونَ السُّٓوءَ بِجَهَالَةٍ ثُمَّ يَتُوبُونَ مِنْ قَر۪يبٍ فَاُو۬لٰٓئِكَ يَتُوبُ اللّٰهُ عَلَيْهِمْۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماً', 'İnnemat tevbetu alallahi lillezine ya\'melunes sue bi cehaletin summe yetubune min karibin fe ulaike yetubullahu aleyhim. Ve kanallahu alimen hakima.', 'Allah katında tevbe;[1] cahillikle[2] bir kötülük yapıp hemen ardından o kötülüğü terk edenlerin tevbesidir. Allah,  ancak bu gibilerin tevbelerini kabul eder. Zira Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'انما التوبة علي الله للذين يعملون السو بجهلة ثم يتوبون من قريب فاوليك يتوب الله عليهم وكان الله عليما حكيما'),
(511, 4, 18, 'وَلَيْسَتِ التَّوْبَةُ لِلَّذ۪ينَ يَعْمَلُونَ السَّيِّـَٔاتِۚ حَتّٰٓى اِذَا حَضَرَ اَحَدَهُمُ الْمَوْتُ قَالَ اِنّ۪ي تُبْتُ الْـٰٔنَ وَلَا الَّذ۪ينَ يَمُوتُونَ وَهُمْ كُفَّارٌۜ اُو۬لٰٓئِكَ اَعْتَدْنَا لَهُمْ عَذَاباً اَل۪يماً', 'Ve leysetit tevbetu lillezine ya\'melunes seyyiat, hatta iza hadara ehadehumul mevtu kale inni tubtul\'ane ve lallezine yemutune ve hum kuffar. Ulaike a\'tedna lehum azaben elima.', 'Kötülük yapıp da kendilerine ölüm gelip çatınca,  \"Ben şimdi tevbe ettim.\" diyenlerin ve Kafir[1] olarak ölenlerin tevbeleri geçersizdir. İşte onlara can yakıcı bir azap vardır.', 'وليست التوبة للذين يعملون السيات حتي اذا حضر احدهم الموت قال اني تبت الن ولا الذين يموتون وهم كفار اوليك اعتدنا لهم عذابا اليما'),
(512, 4, 19, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا يَحِلُّ لَكُمْ اَنْ تَرِثُوا النِّسَٓاءَ كَرْهاًۜ  وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا بِبَعْضِ مَٓا اٰتَيْتُمُوهُنَّ اِلَّٓا اَنْ يَأْت۪ينَ بِفَاحِشَةٍ مُبَيِّنَةٍۚ وَعَاشِرُوهُنَّ بِالْمَعْرُوفِۚ فَاِنْ كَرِهْتُمُوهُنَّ فَعَسٰٓى اَنْ تَكْرَهُوا شَيْـٔاً وَيَجْعَلَ اللّٰهُ ف۪يهِ خَيْراً كَث۪يراً', 'Ya eyyuhallezine amenu la yahıllu lekum en terisun nisae kerha. Ve la ta\'duluhunne li tezhebu bi ba\'dı ma ateytumuhunne illa en ye\'tine bi fahışetin mubeyyineh, ve aşiruhunne bil ma\'ruf, fe in kerihtumuhunne fe asa en tekrahu şey\'en ve yec\'alallahu fihi hayran kesira.', 'Ey iman edenler! Kadınlara istemedikleri halde mirasçı olmanız[1],  size helal değildir. Apaçık bir fuhuş işlemedikçe,  onlara vermiş olduğunuz şeylerin bir kısmını almak için baskı yapmayın. Onlarla iyi geçinin. Şayet onlardan hoşlanmıyorsanız,  bilin ki hoşlanmadığınız bir şeyde Allah birçok hayır kılmış olabilir.', 'يايها الذين امنوا لا يحل لكم ان ترثوا النسا كرها ولا تعضلوهن لتذهبوا ببعض ما اتيتموهن الا ان ياتين بفحشة مبينة وعاشروهن بالمعروف فان كرهتموهن فعسي ان تكرهوا شيا ويجعل الله فيه خيرا كثيرا'),
(513, 4, 20, 'وَاِنْ اَرَدْتُمُ اسْتِبْدَالَ زَوْجٍ مَكَانَ زَوْجٍۙ وَاٰتَيْتُمْ اِحْدٰيهُنَّ قِنْطَاراً فَلَا تَأْخُذُوا مِنْهُ شَيْـٔاًۜ اَتَأْخُذُونَهُ بُهْتَاناً وَاِثْماً مُب۪يناً', 'Ve in eradtumustibdale zevcin mekane zevcin, ve ateytum ihdahunne kıntaren fe la te\'huzu minhu şey\'a. E te\'huzunehu buhtanen ve ismen mubina.', 'Eğer eşinizden boşanıp,  başka biriyle evlenecek olursanız,  boşadığınız eşinize yığınla mal vermiş olsanız bile,  verdiğinizden hiçbir şeyi geri almayın. Ona verdiğinizi,  iftira ederek ve apaçık günah işleyerek mi geri alacaksınız?', 'وان اردتم استبدال زوج مكان زوج واتيتم احديهن قنطارا فلا تاخذوا منه شيا اتاخذونه بهتنا واثما مبينا'),
(514, 4, 21, 'وَكَيْفَ تَأْخُذُونَهُ وَقَدْ اَفْضٰى بَعْضُكُمْ اِلٰى بَعْضٍ وَاَخَذْنَ مِنْكُمْ م۪يثَاقاً غَل۪يظاً', 'Ve keyfe te\'huzunehu ve kad efda ba\'dukum ila ba\'dın ve ehazne minkum misakan galiza.', 'Hem onu nasıl geri alacaksınız ki? Birbirinizle içli dışlı olmuştunuz ve sizden kesin bir söz almışlardı.', 'وكيف تاخذونه وقد افضي بعضكم الي بعض واخذن منكم ميثقا غليظا'),
(515, 4, 22, 'وَلَا تَنْكِحُوا مَا نَكَحَ اٰبَٓاؤُ۬كُمْ مِنَ النِّسَٓاءِ اِلَّا مَا قَدْ سَلَفَۜ اِنَّهُ كَانَ فَاحِشَةً وَمَقْتاًۜ وَسَٓاءَ سَب۪يلاً۟', 'Ve la tenkihu ma nekaha abaukum minen nisai, illa ma kad selef. İnnehu kane fahışeten ve makta. Ve sae sebila.', 'Babalarınızın daha önce evlenmiş oldukları kadınlarla evlenmeyin. Ancak geçmişte olanlar istisna. Bu utanç verici,  çirkin ve kötü bir yoldur.', 'ولا تنكحوا ما نكح اباوكم من النسا الا ما قد سلف انه كان فحشة ومقتا وسا سبيلا'),
(516, 4, 23, 'حُرِّمَتْ عَلَيْكُمْ اُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَاَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْاَخِ وَبَنَاتُ الْاُخْتِ وَاُمَّهَاتُكُمُ الّٰت۪ٓي اَرْضَعْنَكُمْ وَاَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَاُمَّهَاتُ نِسَٓائِكُمْ وَرَبَٓائِبُكُمُ الّٰت۪ي ف۪ي حُجُورِكُمْ مِنْ نِسَٓائِكُمُ الّٰت۪ي دَخَلْتُمْ بِهِنَّۘ فَاِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْۘ وَحَلَٓائِلُ اَبْنَٓائِكُمُ الَّذ۪ينَ مِنْ اَصْلَابِكُمْۙ وَاَنْ تَجْمَعُوا بَيْنَ الْاُخْتَيْنِ اِلَّا مَا قَدْ سَلَفَۜ اِنَّ اللّٰهَ كَانَ غَفُوراً رَح۪يماًۙ', 'Hurrimet aleykum ummehatukum ve benatukum ve ehavatukum ve ammatukum ve halatukum ve benatul ahi ve benatul uhti ve ummehatukumullati erda\'nekum ve ehavatukum miner radaati ve ummehatu nisaikum ve rabaibukumullati fi hucurikum min nisaikumullati dehaltum bihinn, fe in lem tekunu dehaltum bihinne fe la cunaha aleykum, ve halailu ebnaikumullezine min aslabikum, ve en tecmeu beynel uhteyni illa ma kad selef. İnnallahe kane gafuran rahima.', 'Analarınız,  kızlarınız,  kız kardeşleriniz,  halalarınız,  teyzeleriniz,  erkek kardeşlerinizin kızları,  kız kardeşlerinizin kızları,  sizi emziren sütanneleriniz,  süt kız kardeşleriniz,  hanımlarınızın anneleri,  kendileriyle ilişkiye girdiğiniz hanımlarınızın himayeniz altında bulunan kızları[1],  öz oğullarınızın hanımları ve aynı anda iki kız kardeşi birlikte almanız size haram kılındı. Evlenip de ilişkide bulunmadığınız hanımlarınızın kızlarını almanızda bir sakınca yoktur. Geçmişte olan geçmişte kalmıştır. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'حرمت عليكم امهتكم وبناتكم واخوتكم وعمتكم وخلتكم وبنات الاخ وبنات الاخت وامهتكم التي ارضعنكم واخوتكم من الرضعة وامهت نسايكم وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحليل ابنايكم الذين من اصلبكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما'),
(517, 4, 24, 'وَالْمُحْصَنَاتُ مِنَ النِّسَٓاءِ اِلَّا مَا مَلَكَتْ اَيْمَانُكُمْۚ كِتَابَ اللّٰهِ عَلَيْكُمْۘ وَاُحِلَّ لَكُمْ مَا وَرَٓاءَ ذٰلِكُمْ اَنْ تَبْتَغُوا بِاَمْوَالِكُمْ مُحْصِن۪ينَ غَيْرَ مُسَافِح۪ينَۜ فَمَا اسْتَمْتَعْتُمْ بِه۪ مِنْهُنَّ فَاٰتُوهُنَّ اُجُورَهُنَّ فَر۪يضَةًۜ وَلَا جُنَاحَ عَلَيْكُمْ ف۪يمَا تَرَاضَيْتُمْ بِه۪ مِنْ بَعْدِ الْفَر۪يضَةِۜ اِنَّ اللّٰهَ كَانَ عَل۪يماً حَك۪يماً', 'Vel muhsanatu minen nisai illa ma meleket eymanukum, kitaballahi aleykum, ve uhille lekum ma varae zalikum en tebtegu bi emvalikum muhsinine gayra musafihin. Fe mastemta\'tum bihi minhunne fe atuhunne ucurehunne faridah. Ve la cunaha aleykum fima teradaytum bihi min ba\'dil faridah. İnnallahe kane alimen hakima.', 'Antlaşma ile sahip olduğunuz kimseler[1] hariç Muhsenat[2] kadınlar Allah\'ın üzerinize yasasıdır. Bunların dışında kalanlar ise; muhsin olanlar[3],  musafihin[4] olmayanları,  mallarınızla almanız size helal kılındı. O halde,  onlardan hangisiyle yararlandıysanız[5],  ücretlerini farz[6] kıldığınız şekilde verin. Anlaşma yaptığınız miktar üzerinde,  karşılıklı olarak değişiklik yapmanızda bir sakınca yoktur. Allah,  Her Şeyi Bilen\'dir ve En İyi Hüküm Veren\'dir.', 'والمحصنت من النسا الا ما ملكت ايمنكم كتب الله عليكم واحل لكم ما ورا ذلكم ان تبتغوا بامولكم محصنين غير مسفحين فما استمتعتم به منهن فاتوهن اجورهن فريضة ولا جناح عليكم فيما تراضيتم به من بعد الفريضة ان الله كان عليما حكيما'),
(518, 4, 25, 'وَمَنْ لَمْ يَسْتَطِـعْ مِنْكُمْ طَوْلاً اَنْ يَنْكِـحَ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ فَمِنْ مَا مَلَكَتْ اَيْمَانُكُمْ مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِۜ وَاللّٰهُ اَعْلَمُ بِا۪يمَانِكُمْۜ بَعْضُكُمْ مِنْ بَعْضٍۚ فَانْكِحُوهُنَّ بِاِذْنِ اَهْلِهِنَّ وَاٰتُوهُنَّ اُجُورَهُنَّ بِالْمَعْرُوفِ مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلَا مُتَّخِذَاتِ اَخْدَانٍۚ فَاِذَٓا اُحْصِنَّ فَاِنْ اَتَيْنَ بِفَاحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى الْمُحْصَنَاتِ مِنَ الْعَذَابِۜ ذٰلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْۜ وَاَنْ تَصْبِرُوا خَيْرٌ لَكُمْۜ  وَاللّٰهُ غَفُورٌ رَح۪يمٌ۟', 'Ve men lem yestetı\' minkum tavlen en yenkıhal muhsanatil mu\'minati fe min ma meleket eymanukum min feteyatikumul mu\'minat. Vallahu a\'lemu bi imanikum. Ba\'dukum min ba\'d, fenkihuhunne bi izni ehlihinne ve atuhunne ucurehunne bil ma\'rufi muhsanatin gayra musafihatin ve la muttehızati ahdan, fe iza uhsinne fe in eteyne bi fahışetin fe aleyhinne nısfu ma alal muhsanati minel azab. Zalike li men haşiyel anete minkum. Ve en tasbiru hayrun lekum. Vallahu gafurun rahim.', 'Sizden kim muhsenat[1] mü\'min kadınlarla evlenecek güce sahip değilse,  yeminle sahip olduğunuz[2] mümin esir kızlarla evlensin. Allah,  imanınızı en iyi bilendir.[3] Sizler,  birbirinizdensiniz. O halde iffetli,  edepli,  hayasızlık etmeyen ve gizli dost edinmemiş olanlarla; sorumlularının izni ve ücretlerini meşru bir şekilde vererek evlenin. Evlendikten sonra bir fuhuş yaparlarsa,  onlara hür kadınlara verilen cezanın yarısı verilir. Bu içinizden günaha girme korkusu taşıyanlar içindir. Ancak sabretmeniz sizin için daha hayırlıdır. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ومن لم يستطع منكم طولا ان ينكح المحصنت المومنت فمن ما ملكت ايمنكم من فتيتكم المومنت والله اعلم بايمنكم بعضكم من بعض فانكحوهن باذن اهلهن واتوهن اجورهن بالمعروف محصنت غير مسفحت ولا متخذت اخدان فاذا احصن فان اتين بفحشة فعليهن نصف ما علي المحصنت من العذاب ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم'),
(519, 4, 26, 'يُر۪يدُ اللّٰهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذ۪ينَ مِنْ قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Yuridullahu li yubeyyine lekum ve yehdiyekum sunenellezine min kablikum ve yetube aleykum. Vallahu alimun hakim.', 'Allah,  size açıklamak; sizi,  sizden öncekilerin yasalarına iletmek ve tevbenizi[1] kabul etmek ister. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(520, 4, 27, 'وَاللّٰهُ يُر۪يدُ اَنْ يَتُوبَ عَلَيْكُمْ وَيُر۪يدُ الَّذ۪ينَ يَتَّبِعُونَ الشَّهَوَاتِ اَنْ تَم۪يلُوا مَيْلاً عَظ۪يماً', 'Vallahu yuridu en yetube aleykum ve yuridullezine yettebiuneş şehevati en temilu meylen azima.', 'Allah,  tevbelerinizi kabul etmek ister. Şehvetlerine tabi olanlar ise,  sizin derin bir sapkınlığa düşmenizi isterler.', 'والله يريد ان يتوب عليكم ويريد الذين يتبعون الشهوت ان تميلوا ميلا عظيما'),
(521, 4, 28, 'يُر۪يدُ اللّٰهُ اَنْ يُخَفِّفَ عَنْكُمْۚ وَخُلِقَ الْاِنْسَانُ ضَع۪يفاً', 'Yuridullahu en yuhaffife ankum, ve hulikal insanu daifa.', 'Allah,  sorumluluğunuzu hafifletmek ister. Çünkü insan zayıf yaratılmıştır.', 'يريد الله ان يخفف عنكم وخلق الانسن ضعيفا'),
(522, 4, 29, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَأْكُلُٓوا اَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ اِلَّٓا اَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلَا تَقْتُلُٓوا اَنْفُسَكُمْۜ اِنَّ اللّٰهَ كَانَ بِكُمْ رَح۪يماً', 'Ya eyyuhallezine amenu la te\'kulu emvalekum beynekum bil batılı, illa en tekune ticaraten an teradın minkum, ve la taktulu enfusekum. İnnallahe kane bikum rahima.', 'Ey iman edenler! Birbirinizin mallarını karşılıklı rızaya dayanan ticaret yoluyla da olsa,  haksız şekilde yemeyin. Ve kendinizi öldürmeyin. Kuşkusuz,  Allah,  size karşı çok merhametlidir.', 'يايها الذين امنوا لا تاكلوا امولكم بينكم بالبطل الا ان تكون تجرة عن تراض منكم ولا تقتلوا انفسكم ان الله كان بكم رحيما'),
(523, 4, 30, 'وَمَنْ يَفْعَلْ ذٰلِكَ عُدْوَاناً وَظُلْماً فَسَوْفَ نُصْل۪يهِ نَاراًۜ وَكَانَ ذٰلِكَ عَلَى اللّٰهِ يَس۪يراً', 'Ve men yef\'al zalike udvanen ve zulmen fe sevfe nuslihi nara. Ve kane zalike alallahi yesira.', 'Kim,  düşmanlıkla ve haksızlıkla bunu yaparsa,  onu yakında ateşe atacağız. Bu,  Allah için pek kolaydır.', 'ومن يفعل ذلك عدونا وظلما فسوف نصليه نارا وكان ذلك علي الله يسيرا'),
(524, 4, 31, 'اِنْ تَجْتَنِبُوا كَـبَٓائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلاً كَر۪يماً', 'İn tectenibu kebaira ma tunhevne anhu nukeffir ankum seyyiatikum ve nudhılkum mudhalen kerima.', 'Eğer siz,  yasaklananların büyüklerinden sakınırsanız,  kötülüklerinizi küfrederiz.[1] Ve sizi şerefli bir meskene yerleştiririz.', 'ان تجتنبوا كباير ما تنهون عنه نكفر عنكم سياتكم وندخلكم مدخلا كريما'),
(525, 4, 32, 'وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللّٰهُ بِه۪ بَعْضَكُمْ عَلٰى بَعْضٍۜ لِلرِّجَالِ نَص۪يبٌ مِمَّا اكْتَسَبُوا وَلِلنِّسَٓاءِ نَص۪يبٌ مِمَّا اكْتَسَبْنَۜ وَسْـَٔلُوا اللّٰهَ مِنْ فَضْلِه۪ۜ اِنَّ اللّٰهَ كَانَ بِكُلِّ شَيْءٍ عَل۪يماً', 'Ve la tetemennev ma faddalallahu bihi ba\'dakum ala ba\'d. Lir ricali nasibun mimmaktesebu ve lin nisai nasibun mimmaktesebn,  ves\'elullahe min fadlih innallahe kane bi kulli şey\'in alima.', 'Allah\'ın; bazınıza,  bazınıza göre verdiği fazla şeyleri arzu etmeyin. Erkeklerin,  kendi kazançlarından bir pay; kadınların da kendi kazançlarından bir pay vardır. Allah\'tan,  O\'nun lütfunu isteyin. Kuşkusuz,  Allah,  Her Şeyi Bilen\'dir.', 'ولا تتمنوا ما فضل الله به بعضكم علي بعض للرجال نصيب مما اكتسبوا وللنسا نصيب مما اكتسبن وسلوا الله من فضله ان الله كان بكل شي عليما'),
(526, 4, 33, 'وَلِكُلٍّ جَعَلْنَا مَوَالِيَ مِمَّا تَرَكَ الْوَالِدَانِ وَالْاَقْرَبُونَۜ وَالَّذ۪ينَ عَقَدَتْ اَيْمَانُكُمْ فَاٰتُوهُمْ نَص۪يبَهُمْۜ اِنَّ اللّٰهَ كَانَ عَلٰى كُلِّ شَيْءٍ شَه۪يداً۟', 'Ve li kullin cealna mevaliye mimma terakel validani vel akrabun. Vellezine akadet eymanukum fe atuhum nasibehum. İnnallahe kane ala kulli şey\'in şehida.', 'Anne,  baba ve akrabaların bıraktıklarına varisler belirledik. Yeminlerinizin bağladığı[1] kimselere paylarını verin. Kuşkusuz,  Allah her şeye tanıktır.', 'ولكل جعلنا مولي مما ترك الولدان والاقربون والذين عقدت ايمنكم فاتوهم نصيبهم ان الله كان علي كل شي شهيدا'),
(527, 4, 34, 'اَلرِّجَالُ قَوَّامُونَ عَلَى النِّسَٓاءِ بِمَا فَضَّلَ اللّٰهُ بَعْضَهُمْ عَلٰى بَعْضٍ وَبِمَٓا اَنْفَقُوا مِنْ اَمْوَالِهِمْۜ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِلْغَيْبِ بِمَا حَفِظَ اللّٰهُۜ وَالّٰت۪ي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّۚ فَاِنْ اَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَب۪يلاًۜ اِنَّ اللّٰهَ كَانَ عَلِياًّ كَب۪يراً', 'Er ricalu kavvamune alan nisai bi ma faddalallahu ba\'dahum ala ba\'dın ve bi ma enfeku min emvalihim. Fes salihatu kanitatun hafizatun lil gaybi bi ma hafizallah. Vellati tehafune nuşuzehunne fe ızuhunne vahcuruhunn  fil medacıı vadrıbuhunne, fe in ata\'nekum fe la tebgu aleyhinne sebila. İnnallahe kane aliyyen kebira.', 'Erkekler,  kadınlar üzerinde kavvamdırlar.[1] Kendi mallarından infak[2] etmelerinden dolayı Allah bazınızı bazınıza göre faddale[3] yapmıştır. İyi düzeltici kadınlar; bağlılık gösteren ve Allah\'ın korumasını istediğini,  kocalarının bulunmadığı zamanlarda da koruyanlardır. Nuşuzundan[4] endişe ettiğiniz kadınlara önce öğüt verin,  sonra yataklarında yalnız bırakın,  sonra bir süre ayrılın.[5] Eğer size uyarlarsa onların aleyhine bir yol aramayın. Kuşkusuz Allah Çok Yüce\'dir ve Çok Büyük\'tür.', 'الرجال قومون علي النسا بما فضل الله بعضهم علي بعض وبما انفقوا من امولهم فالصلحت قنتت حفظت للغيب بما حفظ الله والتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا'),
(528, 4, 35, 'وَاِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَماً مِنْ اَهْلِه۪ وَحَكَماً مِنْ اَهْلِهَاۚ اِنْ يُر۪يدَٓا اِصْلَاحاً يُوَفِّقِ اللّٰهُ بَيْنَهُمَاۜ اِنَّ اللّٰهَ كَانَ عَل۪يماً خَب۪يراً', 'Ve in hıftum şıkaka beynihima feb\'asu hakemen min ehlihi ve hakemen min ehliha, in yurida ıslahan yuveffikıllahu beynehuma. İnnallahe kane alimen habira.', 'Eğer,  her ikisinin arasının bozulmasından endişe ederseniz,  erkeğin ailesinden bir hakem,  kadının ailesinden bir hakem belirleyin,  eğer uzlaşmak isterlerse,  Allah onların aralarını bulur. Kuşkusuz,  Allah,  Her Şeyi Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلحا يوفق الله بينهما ان الله كان عليما خبيرا'),
(529, 4, 36, 'وَاعْبُدُوا اللّٰهَ وَلَا تُشْرِكُوا بِه۪ شَيْـٔاً وَبِالْوَالِدَيْنِ اِحْسَاناً وَبِذِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينِ وَالْجَارِ ذِي الْقُرْبٰى وَالْجَارِ الْجُنُبِ وَالصَّاحِبِ بِالْجَنْبِ وَابْنِ السَّب۪يلِۙ وَمَا مَلَكَتْ اَيْمَانُكُمْۜ اِنَّ اللّٰهَ لَا يُحِبُّ مَنْ كَانَ مُخْتَالاً فَخُوراًۙ', 'Va\'budullahe ve la tuşriku bihi şeyen ve bil valideyni ihsanen ve bizil kurba vel yetama vel mesakini vel cari zil kurba vel caril cunubi ves sahıbi bil cenbi vebnis sebili, ve ma meleket eymanukum. İnnallahe la yuhıbbu men kane muhtalen fehura.', 'Allah\'a kulluk edin. Hiçbir şeyi O\'na ortak koşmayın. Anne ve babaya,  yakın akrabaya,  yetimlere,  yoksullara,  yakın komşuya,  uzak komşuya,  yakın arkadaşa,  yol oğluna[1],  Yeminle hak sahibi olduğunuz kimselere[2] iyilik edin. Kuşkusuz Allah,  kibirli ve kendini övenleri sevmez.', 'واعبدوا الله ولا تشركوا به شيا وبالولدين احسنا وبذي القربي واليتمي والمسكين والجار ذي القربي والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت ايمنكم ان الله لا يحب من كان مختالا فخورا'),
(530, 4, 37, 'اَلَّذ۪ينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ وَيَكْتُمُونَ مَٓا اٰتٰيهُمُ اللّٰهُ مِنْ فَضْلِه۪ۜ وَاَعْتَدْنَا لِلْكَافِر۪ينَ عَذَاباً مُه۪يناًۚ', 'Ellezine yebhalune ve ye\'murunen nase bil buhli ve yektumune ma atahumullahu min fadlıhi. Ve a\'tedna lil kafirine azaben muhina.', 'Cimrilik edenler,  insanları da cimri olmaya teşvik ederler; Allah\'ın kendi lütfundan verdiklerini gizlerler. Biz,  o Kafirler[1] için alçaltıcı bir azap hazırladık.', 'الذين يبخلون ويامرون الناس بالبخل ويكتمون ما اتيهم الله من فضله واعتدنا للكفرين عذابا مهينا'),
(531, 4, 38, 'وَالَّذ۪ينَ يُنْفِقُونَ اَمْوَالَهُمْ رِئَٓاءَ النَّاسِ وَلَا يُؤْمِنُونَ بِاللّٰهِ وَلَا بِالْيَوْمِ الْاٰخِرِۜ وَمَنْ يَكُنِ الشَّيْطَانُ لَهُ قَر۪يناً فَسَٓاءَ قَر۪يناً', 'Vellezine yunfıkune emvalehum riaen nasi ve la yu\'minune billahi ve la bil yevmil ahir. Ve men yekuniş şeytanu lehu karinen fe sae karina.', 'Bunlar,  mallarını insanlara gösteriş olsun diye infak eden,  Allah\'a ve ahiret gününe de inanmayan kimselerdir. Şeytan,  kime arkadaşsa,  o çok kötü arkadaş edinmiştir.', 'والذين ينفقون امولهم ريا الناس ولا يومنون بالله ولا باليوم الاخر ومن يكن الشيطن له قرينا فسا قرينا'),
(532, 4, 39, 'وَمَاذَا عَلَيْهِمْ لَوْ اٰمَنُوا بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَاَنْفَقُوا مِمَّا رَزَقَهُمُ اللّٰهُۜ وَكَانَ اللّٰهُ بِهِمْ عَل۪يماً', 'Ve maza aleyhim lev amenu billahi vel yevmil ahıri ve enfeku mimma razakahumullah. Ve kanallahu bihim alima.', 'Onlara ne olurdu sanki,  Allah\'a ve ahiret gününe inansalardı; Allah\'ın verdiği rızıktan infak etselerdi. Allah,  onları en iyi bilendir.', 'وماذا عليهم لو امنوا بالله واليوم الاخر وانفقوا مما رزقهم الله وكان الله بهم عليما'),
(533, 4, 40, 'اِنَّ اللّٰهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍۚ وَاِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ اَجْراً عَظ۪يماً', 'İnnallahe la yazlimu miskale zerreh, ve in teku haseneten yudaıfha ve yu\'ti min ledunhu ecran azima.', 'Allah,  zerre kadar haksızlık yapmaz. Yaptığınız iyiliği kat kat arttırır ve kendinden büyük bir ödül verir.', 'ان الله لا يظلم مثقال ذرة وان تك حسنة يضعفها ويوت من لدنه اجرا عظيما'),
(534, 4, 41, 'فَكَيْفَ اِذَا جِئْنَا مِنْ كُلِّ اُمَّةٍ بِشَه۪يدٍ وَجِئْنَا بِكَ عَلٰى هٰٓؤُ۬لَٓاءِ شَه۪يداًۜ', 'Fe keyfe iza ci\'na min kulli ummetin bi şehidin ve ci\'na bike ala haulai şehida.', 'Her ümmetten bir tanık getirdiğimiz ve seni de onların üzerine tanık yaptığımız zaman,  halleri nice olacak!', 'فكيف اذا جينا من كل امة بشهيد وجينا بك علي هولا شهيدا'),
(535, 4, 42, 'يَوْمَئِذٍ يَوَدُّ الَّذ۪ينَ كَفَرُوا وَعَصَوُا الرَّسُولَ لَوْ تُسَوّٰى بِهِمُ الْاَرْضُۜ وَلَا يَكْتُمُونَ اللّٰهَ حَد۪يثاً۟', 'Yevme izin yeveddullezine keferu ve asavur resule lev tusevva bihimul ard. Ve la yektumunallahe hadisa.', 'Nankörlük edip resule karşı çıkanlar,  izin günü[1] yerle bir olmayı isterler ve Allah\'tan hiçbir sözü gizleyemezler.', 'يوميذ يود الذين كفروا وعصوا الرسول لو تسوي بهم الارض ولا يكتمون الله حديثا'),
(536, 4, 43, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَقْرَبُوا الصَّلٰوةَ وَاَنْتُمْ سُكَارٰى حَتّٰى تَعْلَمُوا مَا تَقُولُونَ وَلَا جُنُباً اِلَّا عَابِر۪ي سَب۪يلٍ حَتّٰى تَغْتَسِلُواۜ وَاِنْ كُنْتُمْ مَرْضٰٓى اَوْ عَلٰى سَفَرٍ اَوْ جَٓاءَ اَحَدٌ مِنْكُمْ مِنَ الْغَٓائِطِ اَوْ لٰمَسْتُمُ النِّسَٓاءَ فَلَمْ تَجِدُوا مَٓاءً فَتَيَمَّمُوا صَع۪يداً طَيِّباً فَامْسَحُوا بِوُجُوهِكُمْ وَاَيْد۪يكُمْۜ اِنَّ اللّٰهَ كَانَ عَفُواًّ غَفُوراً', 'Ya eyyuhallezine amenu la takrabus salate ve entum sukara hatta ta\'lemu ma tekulune ve la cunuben illa abiri sebilin hatta tagtesilu. Ve in kuntum marda ev ala seferin ev cae ehadun minkum minel gaiti ev lamestumun nisae fe lem tecidu maen fe teyemmemu saiden tayyiben femsehu bi vucuhikum ve eydikum. İnnallahe kane afuvven gafura.', 'Ey iman edenler! Sarhoşken ne dediğinizi bilinceye kadar; cünüpken -yolculukta olmanız hariç- yıkanıncaya kadar salata[1] yaklaşmayın. Eğer hasta veya yolcuyken sizden biriniz tuvaletten geldiyse veya kadınlarınızla ilişkiye girdiyseniz; o anda su bulamadıysanız,  temiz kumla teyemmüm edin; onunla ellerinizi ve yüzlerinizi mesh edin. Kuşkusuz Allah,  Çok Affedici\'dir ve Çok Bağışlayıcı\'dır.', 'يايها الذين امنوا لا تقربوا الصلوة وانتم سكري حتي تعلموا ما تقولون ولا جنبا الا عابري سبيل حتي تغتسلوا وان كنتم مرضي او علي سفر او جا احد منكم من الغايط او لمستم النسا فلم تجدوا ما فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم ان الله كان عفوا غفورا'),
(537, 4, 44, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ اُو۫تُوا نَص۪يباً مِنَ الْكِتَابِ يَشْتَرُونَ الضَّلَالَةَ وَيُر۪يدُونَ اَنْ تَضِلُّوا السَّب۪يلَۜ', 'E lem tera ilallezine utu nasiben minel kitabi yeşteruned dalalete ve yuridune en tedıllus sebil.', 'Kendilerine Kitap\'tan bir pay verilenleri görmüyor musun? Sapkınlığı satın alıyorlar. Sizi de saptırmak istiyorlar!', 'الم تر الي الذين اوتوا نصيبا من الكتب يشترون الضللة ويريدون ان تضلوا السبيل'),
(538, 4, 45, 'وَاللّٰهُ اَعْلَمُ بِاَعْدَٓائِكُمْۜ وَكَفٰى بِاللّٰهِ وَلِياًّۗ وَكَفٰى بِاللّٰهِ نَص۪يراً', 'Vallahu a\'lemu bi a\'daikum. Ve kefa billahi veliyyen, ve kefa billahi nasira.', 'Allah,  düşmanlarınızı daha iyi bilendir. Veli[1] olarak Allah yeter ve yardımcı olarak Allah yeter.', 'والله اعلم باعدايكم وكفي بالله وليا وكفي بالله نصيرا'),
(539, 4, 46, 'مِنَ الَّذ۪ينَ هَادُوا يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِه۪ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَاسْمَعْ غَيْرَ مُسْمَعٍ وَرَاعِنَا لَياًّ بِاَلْسِنَتِهِمْ وَطَعْناً فِي الدّ۪ينِۜ وَلَوْ اَنَّهُمْ قَالُوا سَمِعْنَا وَاَطَعْنَا وَاسْمَعْ وَانْظُرْنَا لَكَانَ خَيْراً لَهُمْ وَاَقْوَمَۙ وَلٰكِنْ لَعَنَهُمُ اللّٰهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ اِلَّا قَل۪يلاً', 'Minellezine hadu yuharrifunel kelime an mevadııhi ve yekulune semi\'na ve asayna vesma\' gayra musmeın ve raına leyyen bi elsinetihim ve ta\'nan fid din. Ve lev ennehum kalu semi\'na ve ata\'na vesma\'  venzurna le kane hayran lehum ve akvem, ve lakin leanehumullahu bi kufrihim fe la yu\'minune illa kalila.', 'Yahudilerin bir kısmı,  kelimelerin aslını değiştirerek: \"İşittik ve reddettik.\",  \"Kulak vermeden dinleyin.\",  \"Bizi güt.\" derler; dillerini eğip bükerek dinle alay ederler. Eğer onlar: \"İşittik,  itaat ettik.\",  \"Bizi gözet.\" deselerdi bu onlar için daha hayırlı ve daha doğru olurdu. Ancak Allah,  Kafir oldukları için onları lanetlemiştir. Artık pek azı hariç iman etmezler.', 'من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع ورعنا ليا بالسنتهم وطعنا في الدين ولو انهم قالوا سمعنا واطعنا واسمع وانظرنا لكان خيرا لهم واقوم ولكن لعنهم الله بكفرهم فلا يومنون الا قليلا'),
(540, 4, 47, 'يَٓا اَيُّهَا الَّذ۪ينَ اُو۫تُوا الْكِتَابَ اٰمِنُوا بِمَا نَزَّلْنَا مُصَدِّقاً لِمَا مَعَكُمْ مِنْ قَبْلِ اَنْ نَطْمِسَ وُجُوهاً فَنَرُدَّهَا عَلٰٓى اَدْبَارِهَٓا اَوْ نَلْعَنَهُمْ كَمَا لَعَنَّٓا اَصْحَابَ السَّبْتِۜ وَكَانَ اَمْرُ اللّٰهِ مَفْعُولاً', 'Ya eyyuhallezine utul kitabe aminu bi ma nezzelna musaddikan li ma meakum min kabli en natmise vucuhen fe neruddeha ala edbariha ev nel\'anehum kema leanna ashabes sebt. Ve kane emrullahi mef\'ula.', 'Ey kendilerine kitap verilenler! Bazı yüzlerin azalarını silip,  arkaları gibi dümdüz yapmadan veya Cumartesi yasağını çiğneyenleri lanetlediğimiz[1] gibi sizi de lanetlemeden önce yanınızda bulunanı,  doğrulayıcı olarak indirdiğimize iman edin. Zira Allah\'ın hükmü mutlaka gerçekleşir.', 'يايها الذين اوتوا الكتب امنوا بما نزلنا مصدقا لما معكم من قبل ان نطمس وجوها فنردها علي ادبارها او نلعنهم كما لعنا اصحب السبت وكان امر الله مفعولا'),
(541, 4, 48, 'اِنَّ اللّٰهَ لَا يَغْفِرُ اَنْ يُشْرَكَ بِه۪ وَيَغْفِرُ مَا دُونَ ذٰلِكَ لِمَنْ يَشَٓاءُۚ وَمَنْ يُشْرِكْ بِاللّٰهِ فَقَدِ افْتَرٰٓى اِثْماً عَظ۪يماً', 'İnnallahe la yagfiru en yuşrake bihi ve yagfiru ma dune zalike li men yeşau ve men yuşrik billahi fe kadiftera ismen azima.', 'Allah,  kendisine şirk koşanları bağışlamaz. Bunun dışında hak edeni[1] bağışlar. Kim Allah\'a ortak koşarsa,  büyük bir günahla iftirada bulunmuş olur.', 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشا ومن يشرك بالله فقد افتري اثما عظيما'),
(542, 4, 49, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ يُزَكُّونَ اَنْفُسَهُمْۜ بَلِ اللّٰهُ يُزَكّ۪ي مَنْ يَشَٓاءُ وَلَا يُظْلَمُونَ فَت۪يلاً', 'E lem tera ilallezine yuzekkune enfusehum. Belillahu yuzekki men yeşau ve la yuzlemune fetila.', 'Kendilerini temize çıkaranları görmüyor musun? Hayır! Allah,  hak edeni[1] temize çıkarır. Hiç kimseye hurma çekirdeğinin lifi kadar haksızlık edilmez.', 'الم تر الي الذين يزكون انفسهم بل الله يزكي من يشا ولا يظلمون فتيلا'),
(543, 4, 50, 'اُنْظُرْ كَيْفَ يَفْتَرُونَ عَلَى اللّٰهِ الْكَذِبَۜ وَكَفٰى بِه۪ٓ اِثْماً مُب۪يناً۟', 'Unzur keyfe yefterune alallahil kezib. Ve kefa bihi ismen mubina.', 'Bak! Nasıl Allah adına yalan uyduruyorlar.[1] Apaçık bir günah olarak bu yeter.', 'انظر كيف يفترون علي الله الكذب وكفي به اثما مبينا'),
(544, 4, 51, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ اُو۫تُوا نَص۪يباً مِنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذ۪ينَ كَفَرُوا هٰٓؤُ۬لَٓاءِ اَهْدٰى مِنَ الَّذ۪ينَ اٰمَنُوا سَب۪يلاً', 'E lem tera ilallezine utu nasiben minel kitabi yu\'minune bil cibti vet taguti ve yekulune lillezine keferu haulai ehda minellezine amenu sebila.', 'Kendilerine kitaptan bir pay verilenleri görmüyor musun? Cipte[1] ve Tağuta[2] inanıyorlar ve Kafirler için: \"Bunlar,  iman edenlerden daha doğru yoldadırlar.\" diyorlar.', 'الم تر الي الذين اوتوا نصيبا من الكتب يومنون بالجبت والطغوت ويقولون للذين كفروا هولا اهدي من الذين امنوا سبيلا'),
(545, 4, 52, 'اُو۬لٰٓئِكَ الَّذ۪ينَ لَعَنَهُمُ اللّٰهُۜ وَمَنْ يَلْعَنِ اللّٰهُ فَلَنْ تَجِدَ لَهُ نَص۪يراًۜ', 'Ulaikellezine leanehumullah. Ve men yel\'anillahu fe len tecide lehu nasira.', 'Bunlar Allah\'ın lanetlediği kimselerdir. Allah\'ın lanetine uğramış kimse için hiçbir yardımcı bulamazsın.', 'اوليك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا'),
(546, 4, 53, 'اَمْ لَهُمْ نَص۪يبٌ مِنَ الْمُلْكِ فَاِذاً لَا يُؤْتُونَ النَّاسَ نَق۪يراًۙ', 'Em lehum nasibun minel mulki fe izen la yu\'tunen nase nakira.', 'Yoksa onların mülkten[1] bir payları mı var? Öyle olsa,  insanlara hurma çekirdeğinin bir parçasını bile vermezlerdi.', 'ام لهم نصيب من الملك فاذا لا يوتون الناس نقيرا'),
(547, 4, 54, 'اَمْ يَحْسُدُونَ النَّاسَ عَلٰى مَٓا اٰتٰيهُمُ اللّٰهُ مِنْ فَضْلِه۪ۚ فَقَدْ اٰتَيْنَٓا اٰلَ اِبْرٰه۪يمَ الْكِتَابَ وَالْحِكْمَةَ وَاٰتَيْنَاهُمْ مُلْكاً عَظ۪يماً', 'Em yahsudunen nase ala ma atahumullahu min fadlıhi, fe kad ateyna ale ibrahimel kitabe vel hikmete ve ateynahum mulken azima.', 'Yoksa onlar,  Allah\'ın kendi lütfundan insanlara bağışladığı şeyleri mi kıskanıyor? İbrahim soyuna da Kitap\'ı ve Hikmeti[1] bağışladık ve onlara büyük bir mülk[2] verdik.', 'ام يحسدون الناس علي ما اتيهم الله من فضله فقد اتينا ال ابرهيم الكتب والحكمة واتينهم ملكا عظيما'),
(548, 4, 55, 'فَمِنْهُمْ مَنْ اٰمَنَ بِه۪ وَمِنْهُمْ مَنْ صَدَّ عَنْهُۜ وَكَفٰى بِجَهَنَّمَ سَع۪يراً', 'Fe minhum men amene bihi ve minhum men sadde anhu. Ve kefa bi cehenneme saira.', 'Onların bir kısmı O\'na inandı,  bir kısmı da O\'ndan kaçındı. Böylelerine kızgın alevli Cehennem yeter.', 'فمنهم من امن به ومنهم من صد عنه وكفي بجهنم سعيرا'),
(549, 4, 56, 'اِنَّ الَّذ۪ينَ كَفَرُوا بِاٰيَاتِنَا سَوْفَ نُصْل۪يهِمْ نَاراًۜ  كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُوداً غَيْرَهَا لِيَذُوقُوا الْعَذَابَۜ اِنَّ اللّٰهَ  كَانَ عَز۪يزاً حَك۪يماً', 'İnnellezine keferu bi ayatina sevfe nuslihim nara. Kullema nadicet culuduhum beddelnahum culuden gayraha li yezukul azab. İnnallahe kane azizen hakima.', 'Ayetlerimizi küfredenleri[1],  yakında ateşe atacağız. Derileri piştikçe,  azabı iyice tatsınlar diye onlara yeni deriler giydireceğiz. Kuşkusuz,  Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ان الذين كفروا بايتنا سوف نصليهم نارا كلما نضجت جلودهم بدلنهم جلودا غيرها ليذوقوا العذاب ان الله كان عزيزا حكيما'),
(550, 4, 57, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ  لَهُمْ ف۪يهَٓا اَزْوَاجٌ مُطَهَّرَةٌۘ وَنُدْخِلُهُمْ ظِلاًّ ظَل۪يلاً', 'Vellezine amenu ve amilus salihati se nudhıluhum cennatin tecri min tahtihal enharu halidine fiha ebeda. Lehum fiha ezvacun mutahharatun, ve nudhıluhum zıllen zalila.', 'İman edip salihatı[1] yapanları da altlarından ırmaklar akan Cennetlere koyacağız. Onlar,  orada kesintisiz olarak sürekli kalıcıdırlar. Orada,  kendileri için arındırılmış eşler vardır. Ve onları serin bir gölgeye yerleştireceğiz.', 'والذين امنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا لهم فيها ازوج مطهرة وندخلهم ظلا ظليلا'),
(551, 4, 58, 'اِنَّ اللّٰهَ يَأْمُرُكُمْ اَنْ تُؤَدُّوا الْاَمَانَاتِ اِلٰٓى اَهْلِهَاۙ وَاِذَا حَكَمْتُمْ بَيْنَ النَّاسِ اَنْ تَحْكُمُوا بِالْعَدْلِۜ اِنَّ اللّٰهَ نِعِمَّا يَعِظُـكُمْ بِه۪ۜ اِنَّ اللّٰهَ  كَانَ سَم۪يعاً بَص۪يراً', 'İnnallahe ye\'murukum en tueddul emanati ila ehliha ve iza hakemtum beynen nasi en tahkumu bil adl. İnnallahe niımma yeızukum bihi. İnnallahe kane semian basira.', 'Allah,  emanetleri[1] ehline vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi buyurmaktadır. Allah,  bununla size ne güzel öğüt veriyor. Kuşkusuz,  Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Gören\'dir.', 'ان الله يامركم ان تودوا الامنت الي اهلها واذا حكمتم بين الناس ان تحكموا بالعدل ان الله نعما يعظكم به ان الله كان سميعا بصيرا'),
(552, 4, 59, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَط۪يعُوا اللّٰهَ وَاَط۪يعُوا الرَّسُولَ وَاُو۬لِي الْاَمْرِ مِنْكُمْۚ فَاِنْ تَنَازَعْتُمْ ف۪ي شَيْءٍ فَرُدُّوهُ اِلَى اللّٰهِ وَالرَّسُولِ اِنْ كُنْتُمْ تُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ ذٰلِكَ خَيْرٌ وَاَحْسَنُ تَأْو۪يلاً۟', 'Ya eyyuhallezine amenu atiullahe ve atiur resule ve ulil emri minkum, fe in tenaza\'tum fi şey\'in fe rudduhu ilallahi ver resuli in kuntum tu\'minune billahi vel yevmil ahir. Zalike hayrun ve ahsenu te\'vila.', 'Ey iman edenler! Allah\'a itaat edin; Resul\'e itaat edin ve sizden olan ulu\'l-emre[1] itaat edin. Herhangi bir konuda anlaşmazlığa düşerseniz onu Allah\'a ve Resule götürün; eğer Allah\'a ve Ahiret Günü\'ne inanıyorsanız. Hayırlı olan budur. Ve sonuç bakımından iyi olandır.', 'يايها الذين امنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم فان تنزعتم في شي فردوه الي الله والرسول ان كنتم تومنون بالله واليوم الاخر ذلك خير واحسن تاويلا'),
(553, 4, 60, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ يَزْعُمُونَ اَنَّهُمْ اٰمَنُوا بِمَٓا اُنْزِلَ اِلَيْكَ وَمَٓا اُنْزِلَ مِنْ قَبْلِكَ يُر۪يدُونَ اَنْ يَتَحَاكَمُٓوا اِلَى الطَّاغُوتِ وَقَدْ اُمِرُٓوا اَنْ يَكْفُرُوا بِه۪ۜ وَيُر۪يدُ الشَّيْطَانُ اَنْ يُضِلَّهُمْ ضَلَالاً بَع۪يداً', 'E lem tera ilallezine yez\'umune ennehum amenu bima unzile ileyke ve ma unzile min kablike yuridune en yetehakemu ilat taguti ve kad umiru en yekfuru bihi. Ve yuriduş şeytanu en yudıllehum dalalen baida.', 'Görüyor musun? Sana indirilene ve senden önce indirilene inandıklarını ileri sürenleri! Tağuti[1] yasalarla yargılanmak istiyorlar. Oysa onlara,  onu küfretmeleri[2] emredilmişti. Zaten şeytan onları derin bir sapkınlıkla saptırmak istiyor.', 'الم تر الي الذين يزعمون انهم امنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الي الطغوت وقد امروا ان يكفروا به ويريد الشيطن ان يضلهم ضللا بعيدا'),
(554, 4, 61, 'وَاِذَا ق۪يلَ لَهُمْ تَعَالَوْا اِلٰى مَٓا اَنْزَلَ اللّٰهُ وَاِلَى الرَّسُولِ رَاَيْتَ الْمُنَافِق۪ينَ يَصُدُّونَ عَنْكَ صُدُوداًۚ', 'Ve iza kile lehum tealev ila ma enzelallahu ve ilar resuli raeytel munafıkine yesuddune anke sududa.', 'Onlardan,  ne zaman Allah\'ın indirdiğine ve Resul\'üne gelmeleri istense,  o münafıkların,  senden tam bir uzaklaşma ile uazaklaştıklarını görürsün.', 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول رايت المنفقين يصدون عنك صدودا'),
(555, 4, 62, 'فَكَيْفَ اِذَٓا اَصَابَتْهُمْ مُص۪يبَةٌ بِمَا قَدَّمَتْ اَيْد۪يهِمْ ثُمَّ جَٓاؤُ۫كَ يَحْلِفُونَ بِاللّٰهِ اِنْ اَرَدْنَٓا اِلَّٓا اِحْسَاناً وَتَوْف۪يقاً', 'Ve keyfe iza esabethum musibetun bima kaddemet eydihim summe cauke yahlıfune billahi in eradna illa ihsanen ve tevfika.', 'Kendi elleriyle yaptıklarından dolayı,  onlara bir musibet isabet edince,  sana gelerek: \"Biz yalnızca iyilik etmek ve arayı bulmaktan başka bir şey istemedik.\" diye nasıl da Allah\'a yemin ediyorlar.', 'فكيف اذا اصبتهم مصيبة بما قدمت ايديهم ثم جاوك يحلفون بالله ان اردنا الا احسنا وتوفيقا'),
(556, 4, 63, 'اُو۬لٰٓئِكَ الَّذ۪ينَ يَعْلَمُ اللّٰهُ مَا ف۪ي قُلُوبِهِمْ فَاَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُلْ لَهُمْ ف۪ٓي اَنْفُسِهِمْ قَوْلاً بَل۪يغاً', 'Ulaikellezine ya\'lemullahu ma fi kulubihim fe a\'rıd anhum vaızhum ve kul lehum fi enfusihim kavlen beliga.', 'Allah,  bu kimselerin kalplerinde olanı biliyor. Onlara aldırma,  onlara öğüt ver ve onlara kendilerini etkileyici söz söyle.', 'اوليك الذين يعلم الله ما في قلوبهم فاعرض عنهم وعظهم وقل لهم في انفسهم قولا بليغا'),
(557, 4, 64, 'وَمَٓا اَرْسَلْنَا مِنْ رَسُولٍ اِلَّا لِيُطَاعَ بِاِذْنِ اللّٰهِۜ وَلَوْ اَنَّهُمْ اِذْ ظَلَمُٓوا اَنْفُسَهُمْ جَٓاؤُ۫كَ فَاسْتَغْفَرُوا اللّٰهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللّٰهَ تَـوَّاباً رَح۪يماً', 'Ve ma erselna min resulin illa li yutaa bi iznillah. Ve lev ennehum iz zalemu enfusehum cauke festagferullahe vestagfera lehumur resulu le vecedullahe tevvaben rahima.', 'Biz,  hiçbir resulü Allah\'ın izni ile[1] yalnızca kendisine itaat edilmesinden başka bir amaçla göndermedik. Eğer onlar,  kendi kendilerine haksızlık yaptıklarında,  sana gelip,  Allah\'tan bağışlanmalarını dileselerdi ve sen de Resul olarak onların bağışlanmasını dileseydin; Allah\'ın tevbeleri kabul edici ve çok merhamet edici olduğunu göreceklerdi.', 'وما ارسلنا من رسول الا ليطاع باذن الله ولو انهم اذ ظلموا انفسهم جاوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما'),
(558, 4, 65, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتّٰى يُحَكِّمُوكَ ف۪يمَا شَجَرَ بَيْنَهُمْۙ ثُمَّ لَا يَجِدُوا ف۪ٓي اَنْفُسِهِمْ حَرَجاً مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْل۪يماً', 'Fe la ve rabbike la yu\'minune hatta yuhakkimuke fima şecera beynehum, summe la yecidu fi enfusihim haracen mimma kadayte ve yusellimu teslima.', 'Hayır! Rabb\'ine ant olsun ki,  aralarında anlaşmazlığa düştükleri işlerde seni hakem tayin edip,  sonra da verdiğin hükme tam bir teslimiyetle teslim olmadıkça iman etmiş olmazlar.', 'فلا وربك لا يومنون حتي يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما'),
(559, 4, 66, 'وَلَوْ اَنَّا كَتَبْنَا عَلَيْهِمْ اَنِ اقْتُلُٓوا اَنْفُسَكُمْ اَوِ اخْرُجُوا مِنْ دِيَارِكُمْ مَا فَعَلُوهُ اِلَّا قَل۪يلٌ مِنْهُمْۜ وَلَوْ اَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِه۪ لَكَانَ خَيْراً لَهُمْ وَاَشَدَّ تَثْب۪يتاًۙ', 'Ve lev enna ketebna aleyhim enıktulu enfusekum evihrucu min diyarikum ma fealuhu illa kalilun minhum. Ve lev ennehum fealu ma yuazune bihi le kane hayran lehum ve eşedde tesbita.', 'Eğer biz onlara: \"Kendinizi öldürün[1] veya yurtlarınızdan[2] çıkın\" diye yazsaydık, [3] çok azı hariç bunu yapmazlardı. Eğer kendilerine verilen öğüde uysalardı,  elbette bu onlar için hem daha hayırlı hem kalıcı olarak daha sağlam olurdu.', 'ولو انا كتبنا عليهم ان اقتلوا انفسكم او اخرجوا من ديركم ما فعلوه الا قليل منهم ولو انهم فعلوا ما يوعظون به لكان خيرا لهم واشد تثبيتا'),
(560, 4, 67, 'وَاِذاً لَاٰتَيْنَاهُمْ مِنْ لَدُنَّٓا اَجْراً عَظ۪يـماًۙ', 'Ve izen le ateynahum min ledunna ecran azima.', 'O zaman onlara kendi katımızdan büyük bir ecir[1] verirdik.', 'واذا لاتينهم من لدنا اجرا عظيما'),
(561, 4, 68, 'وَلَهَدَيْنَاهُمْ صِرَاطاً مُسْتَق۪يماً', 'Ve le hedeynahum sıratan mustekima.', 'Onları dosdoğru bir yola iletirdik.', 'ولهدينهم صرطا مستقيما'),
(562, 4, 69, 'وَمَنْ يُطِـعِ اللّٰهَ وَالرَّسُولَ فَاُو۬لٰٓئِكَ مَعَ الَّذ۪ينَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِنَ النَّبِيّ۪نَ وَالصِّدّ۪يق۪ينَ وَالشُّهَدَٓاءِ وَالصَّالِح۪ينَۚ وَحَسُنَ اُو۬لٰٓئِكَ رَف۪يقاًۜ', 'Ve men yutiıllahe ver resule fe ulaike meallezine en\'amellahu aleyhim minen nebiyyine ves sıddikine veş şuhedai ves salihin, ve hasune ulaike rafika.', 'Kim Allah\'a ve Resul\'e itaat ederse,  işte onlar,  Allah\'ın kendilerine nimet verdiği,  nebiler,  sıddıklar[1],  şahitler[2] ve salihlerle[3] beraberdirler. Onlar ne iyi arkadaştırlar!', 'ومن يطع الله والرسول فاوليك مع الذين انعم الله عليهم من النبين والصديقين والشهدا والصلحين وحسن اوليك رفيقا'),
(563, 4, 70, 'ذٰلِكَ الْفَضْلُ مِنَ اللّٰهِۜ وَكَفٰى بِاللّٰهِ عَل۪يماً۟', 'Zalikel fadlu minallah. Ve kefa billahi alima.', 'Bu,  Allah\'tan bir bağıştır. Her şeyi bilen olarak Allah yeter.', 'ذلك الفضل من الله وكفي بالله عليما'),
(564, 4, 71, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا خُذُوا حِذْرَكُمْ فَانْفِرُوا ثُبَاتٍ اَوِ انْفِرُوا جَم۪يعاً', 'Ya eyyuhallezine amenu huzu hızrakum fenfiru subatin evinfiru cemia.', 'Ey iman edenler! Önleminizi alın. Savaşa,  küçük birlikler halinde veya topyekun olarak çıkın.', 'يايها الذين امنوا خذوا حذركم فانفروا ثبات او انفروا جميعا'),
(565, 4, 72, 'وَاِنَّ مِنْكُمْ لَمَنْ لَيُبَطِّئَنَّۚ فَاِنْ اَصَابَتْكُمْ مُص۪يبَةٌ قَالَ قَدْ اَنْعَمَ اللّٰهُ عَلَيَّ اِذْ لَمْ اَكُنْ مَعَهُمْ شَه۪يداً', 'Ve inne minkum le men le yubattienn, fe in esabetkum musibetun kale kad en\'amallahu aleyye iz lem ekun meahum şehida.', 'İçinizden ağır davranan bazı kimseler,  size bir musibet isabet ederse,  \"Allah bana nimet verdi[1] de onlarla beraber bulunmadım.\" der.', 'وان منكم لمن ليبطين فان اصبتكم مصيبة قال قد انعم الله علي اذ لم اكن معهم شهيدا'),
(566, 4, 73, 'وَلَئِنْ اَصَابَكُمْ فَضْلٌ مِنَ اللّٰهِ لَيَقُولَنَّ كَاَنْ لَمْ تَكُنْ بَيْنَكُمْ وَبَيْنَهُ مَوَدَّةٌ يَا لَيْتَن۪ي كُنْتُ مَعَهُمْ فَاَفُوزَ فَوْزاً عَظ۪يماً', 'Ve le in esabekum fadlun minallahi le yekulenne ke en lem tekun beynekum ve beynehu meveddetun ya leyteni kuntu meahum fe efuze fevzen azima.', 'Eğer size Allah\'tan bir lütuf erişse,  bu sefer de sanki sizinle onun arasında bir bağlılık/yakınlık[1] yokmuş gibi: \"Keşke ben de onlarla beraber olsaydım da büyük bir başarı elde etseydim.\" der.', 'ولين اصبكم فضل من الله ليقولن كان لم تكن بينكم وبينه مودة يليتني كنت معهم فافوز فوزا عظيما'),
(567, 4, 74, 'فَلْيُقَاتِلْ ف۪ي سَب۪يلِ اللّٰهِ الَّذ۪ينَ يَشْرُونَ الْحَيٰوةَ الدُّنْيَا بِالْاٰخِرَةِۜ وَمَنْ يُقَاتِلْ ف۪ي سَب۪يلِ اللّٰهِ فَيُقْتَلْ اَوْ يَغْلِبْ فَسَوْفَ نُؤْت۪يهِ اَجْراً عَظ۪يماً', 'Felyukatil fi sebilillahillezine yeşrunel hayated dunya bil ahirah. Ve men yukatil fi sebilillahi fe yuktel ev yaglib fe sevfe nu\'tihi ecran azima.', 'Öyleyse,  ahiret hayatını dünya hayatına tercih edenler,  Allah yolunda savaşsınlar. Kim,  Allah yolunda savaşır da öldürülür veya galip gelirse,  Biz,  ona ileride büyük bir karşılık vereceğiz.', 'فليقتل في سبيل الله الذين يشرون الحيوة الدنيا بالاخرة ومن يقتل في سبيل الله فيقتل او يغلب فسوف نوتيه اجرا عظيما'),
(568, 4, 75, 'وَمَا لَكُمْ لَا تُقَاتِلُونَ ف۪ي سَب۪يلِ اللّٰهِ وَالْمُسْتَضْعَف۪ينَ مِنَ الرِّجَالِ وَالنِّسَٓاءِ وَالْوِلْدَانِ الَّذ۪ينَ يَقُولُونَ رَبَّنَٓا اَخْرِجْنَا مِنْ هٰذِهِ الْقَرْيَةِ الظَّالِمِ اَهْلُهَاۚ وَاجْعَلْ لَنَا مِنْ لَدُنْكَ وَلِياًّۚ وَاجْعَلْ لَنَا مِنْ لَدُنْكَ نَص۪يراًۜ', 'Ve ma lekum la tukatilune fi sebilillahi vel mustad\'afine miner ricali ven nisai vel vildanillezine yekulune rabbena ahricna min hazihil karyetiz zalimi ehluha, vec\'al lena min ledunke veliyya, vec\'al lena min ledunke nasira.', 'Size ne oluyor da Allah yolunda ve: \"Ey Rabb\'imiz! Bizi halkı zalim olan bu beldeden çıkar,  katından bize bir veli[1] ver,  bize katından yardım edecek kimseler ver\" diyen mustaz\'af[2] erkekler,  kadınlar ve çocuklar için savaşmıyorsunuz?', 'وما لكم لا تقتلون في سبيل الله والمستضعفين من الرجال والنسا والولدن الذين يقولون ربنا اخرجنا من هذه القرية الظالم اهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا'),
(569, 4, 76, 'اَلَّذ۪ينَ اٰمَنُوا يُقَاتِلُونَ ف۪ي سَب۪يلِ اللّٰهِۚ وَالَّذ۪ينَ كَفَرُوا يُقَاتِلُونَ ف۪ي سَب۪يلِ الطَّاغُوتِ فَقَاتِلُٓوا اَوْلِيَٓاءَ الشَّيْطَانِۚ اِنَّ  كَيْدَ الشَّيْطَانِ كَانَ ضَع۪يفاً۟', 'Ellezine amenu yukatilune fi sebilillah, vellezine keferu yukatilune fi sebilit taguti fe katilu evliyaeş şeytan, inne keydeş şeytani kane daifa.', 'İman edenler Allah yolunda savaşırlar,  Kafirler de tağutun[1] yolunda savaşırlar. O halde şeytanı evliya[2] edinenlerle savaşın. Kuşkusuz,  şeytanın hilesi/düzeni zayıftır.', 'الذين امنوا يقتلون في سبيل الله والذين كفروا يقتلون في سبيل الطغوت فقتلوا اوليا الشيطن ان كيد الشيطن كان ضعيفا'),
(570, 4, 77, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ ق۪يلَ لَهُمْ كُفُّٓوا اَيْدِيَكُمْ وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَۚ  فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ اِذَا فَر۪يقٌ مِنْهُمْ يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللّٰهِ اَوْ اَشَدَّ خَشْيَةًۚ وَقَالُوا رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا الْقِتَالَۚ  لَوْلَٓا اَخَّرْتَنَٓا اِلٰٓى اَجَلٍ قَر۪يبٍۜ  قُلْ مَتَاعُ الدُّنْيَا قَل۪يلٌۚ وَالْاٰخِرَةُ خَيْرٌ لِمَنِ اتَّقٰى وَلَا تُظْلَمُونَ فَت۪يلاً', 'E lem tera ilallezine kile lehum kuffu eydiyekum, ve ekimus salate ve atuz zekat, fe lemma kutibe aleyhimul kıtalu iza ferikun minhum yahşevnen nase ke haşyetillahi ev eşedde haşyeh, ve kalu rabbena lime ketebte aleynal kıtal, lev la ahhartena ila ecelin karib. Kul metaud dunya kalil, vel ahıratu hayrun li menitteka ve la tuzlemune fetila.', 'Kendilerine,  ellerinizi çekin[1],  salatı ikame edin,  zekatı yapın[2] denilen kimseleri görmedin mi? Üzerlerine savaş yazılınca[3],  içlerinden bir kısmı Allah\'ın haşyeti gibi,  hatta daha fazla insanlara haşyet[4] duyarlar. Ve \"Ey Rabb\'imiz! Neden üzerimize savaş yazdın,  bizi yakın bir zamana kadar erteleseydin ya?\" dediler. De ki: \"Dünya geçimliği önemsizdir. Ahiret,  takva sahibi kimseler için daha hayırlıdır.\" Ve hurma çekirdeğinin içindeki lif kadar size haksızlık edilmez.', 'الم تر الي الذين قيل لهم كفوا ايديكم واقيموا الصلوة واتوا الزكوة فلما كتب عليهم القتال اذا فريق منهم يخشون الناس كخشية الله او اشد خشية وقالوا ربنا لم كتبت علينا القتال لولا اخرتنا الي اجل قريب قل متع الدنيا قليل والاخرة خير لمن اتقي ولا تظلمون فتيلا'),
(571, 4, 78, 'اَيْنَ مَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ وَلَوْ كُنْتُمْ ف۪ي بُرُوجٍ مُشَيَّدَةٍۜ وَاِنْ تُصِبْهُمْ حَسَنَةٌ يَقُولُوا هٰذِه۪ مِنْ عِنْدِ اللّٰهِۚ وَاِنْ تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا هٰذِه۪ مِنْ عِنْدِكَۜ قُلْ كُلٌّ مِنْ عِنْدِ اللّٰهِۜ فَمَالِ هٰٓؤُ۬لَٓاءِ الْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَد۪يثاً', 'Eyne ma tekunu yudrikkumul mevtu ve lev kuntum fi burucin muşeyyedeh. Ve in tusıbhum hasenetun yekulu hazihi min indillah, ve in tusıbhum seyyietun yekulu hazihi min indike. Kul kullun min indillah. Fe mali haulail kavmi la yekadune yefkahune hadisa.', 'Nerede olursanız olun,  sağlam kalelerde de olsanız,  ölüm gelir sizi bulur. Onlara,  bir iyilik isabet etse,  \"Bu Allah\'tandır.\" derler. Onlara,  bir kötülük isabet etse,  bu \"senin yüzündendir.\" derler. De ki: \"Hepsi Allah\'tandır.\"[1] Bu halka ne oluyor ki söylenen sözü anlamaya yanaşmıyorlar!', 'اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة وان تصبهم حسنة يقولوا هذه من عند الله وان تصبهم سيية يقولوا هذه من عندك قل كل من عند الله فمال هولا القوم لا يكادون يفقهون حديثا'),
(572, 4, 79, 'مَٓا اَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللّٰهِۘ وَمَٓا اَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَۜ وَاَرْسَلْنَاكَ لِلنَّاسِ رَسُولاًۜ  وَكَفٰى بِاللّٰهِ شَه۪يداً', 'Ma esabeke min hasenetin fe minallah, ve ma esabeke min seyyietin fe min nefsike. Ve erselnake lin nasi resula. Ve kefa billahi şehida.', 'Sana isabet eden iyilik Allah\'tandır. Sana isabet eden kötülük kendindendir.[1] Biz,  seni,  insanlara resul olarak gönderdik. Tanık olarak Allah yeter.', 'ما اصابك من حسنة فمن الله وما اصابك من سيية فمن نفسك وارسلنك للناس رسولا وكفي بالله شهيدا'),
(573, 4, 80, 'مَنْ يُطِـعِ الرَّسُولَ فَقَدْ اَطَاعَ اللّٰهَۚ وَمَنْ تَوَلّٰى فَمَٓا اَرْسَلْنَاكَ عَلَيْهِمْ حَف۪يظاًۜ', 'Men yutiır resule fe kad ataallah, ve men tevella fe ma erselnake aleyhim hafiza.', 'Kim Resul\'e itaat ederse,  Allah\'a itaat etmiş olur[1]. Kim de yüz çevirirse çevirsin; biz seni onlara bekçi olarak göndermedik.', 'من يطع الرسول فقد اطاع الله ومن تولي فما ارسلنك عليهم حفيظا'),
(574, 4, 81, 'وَيَقُولُونَ طَاعَةٌۘ فَاِذَا بَرَزُوا مِنْ عِنْدِكَ بَيَّتَ طَٓائِفَةٌ مِنْهُمْ غَيْرَ الَّذ۪ي تَقُولُۜ وَاللّٰهُ يَكْتُبُ مَا يُبَيِّتُونَۚ فَاَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى اللّٰهِۜ وَكَفٰى بِاللّٰهِ وَك۪يلاً', 'Ve yekulune taatun, fe iza berazu min indike beyyete taifetun minhum gayrallezi tekul. Vallahu yektubu ma yubeyyitun, fe a\'rıd anhum ve tevekkel alallah. Ve kefa billahi vekila.', 'Sana,  \"itaat ettiklerini\" söylüyorlar. Senin yanından ayrılıp,  yalnız kaldıkları zaman,  onlardan bir grup,  arkandan[1],  senin yanında söylediklerinden farklı şeyler tasarlıyorlar. Allah,  onların,  arkandan gizlice tasarladıkları şeylerin hepsini kaydediyor. Onlara aldırma,  yalnız Allah\'a dayan,  vekil[2] olarak Allah sana yeter.', 'ويقولون طاعة فاذا برزوا من عندك بيت طايفة منهم غير الذي تقول والله يكتب ما يبيتون فاعرض عنهم وتوكل علي الله وكفي بالله وكيلا'),
(575, 4, 82, 'اَفَلَا يَتَدَبَّرُونَ الْقُرْاٰنَۜ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللّٰهِ لَوَجَدُوا ف۪يهِ اخْتِلَافاً كَث۪يراً', 'E fe la yetedebberunel kur\'an.Ve lev kane min indi gayrillahi le vecedu fihihtilafen kesira.', 'Onlar,  Kur\'an üzerinde,  gereği gibi düşünmezler mi? Eğer,  Allah\'tan başkası tarafından gönderilmiş olsaydı,  onda birçok çelişki bulurlardı.', 'افلا يتدبرون القران ولو كان من عند غير الله لوجدوا فيه اختلفا كثيرا'),
(576, 4, 83, 'وَاِذَا جَٓاءَهُمْ اَمْرٌ مِنَ الْاَمْنِ اَوِ الْخَوْفِ اَذَاعُوا بِه۪ۜ وَلَوْ رَدُّوهُ اِلَى الرَّسُولِ وَاِلٰٓى اُو۬لِي الْاَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذ۪ينَ يَسْتَنْبِطُونَهُ مِنْهُمْۜ وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ لَاتَّبَعْتُمُ الشَّيْطَانَ اِلَّا قَل۪يلاً', 'Ve iza caehum emrun minel emni evil havfi ezau bihi.Ve lev redduhu ilar resuli ve ila ulil emri minhum le alimehullezine yestenbitunehu minhum. Ve lev la fadlullahi aleykum ve rahmetuhu letteba\'tumuş şeytane illa kalila.', 'Onlara,  güven veya korkuyla ilgili bir haber geldiği zaman,  onu hemen yayarlar. Oysaki onu Resul\'e ve kendilerinden olan ulu\'l-emre[1] bildirselerdi; işin iç yüzünü bilenler,  ne olup bittiğini,  bilirlerdi. Eğer Allah\'ın lütfu ve rahmeti üzerinizde olmasaydı,  pek azınız hariç hepiniz şeytana uyardınız.', 'واذا جاهم امر من الامن او الخوف اذاعوا به ولو ردوه الي الرسول والي اولي الامر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطن الا قليلا'),
(577, 4, 84, 'فَقَاتِلْ ف۪ي سَب۪يلِ اللّٰهِۚ لَا تُكَلَّفُ اِلَّا نَفْسَكَ وَحَرِّضِ الْمُؤْمِن۪ينَۚ عَسَى اللّٰهُ اَنْ يَكُفَّ بَأْسَ الَّذ۪ينَ كَفَرُواۜ وَاللّٰهُ اَشَدُّ بَأْساً وَاَشَدُّ تَنْك۪يلاً', 'Fe katil fi sebilillah, la tukellefu illa nefseke ve harrıdıl mu\'minin, asallahu en yekuffe be\'sellezine keferu. Vallahu eşeddu be\'sen ve eşeddu tenkila.', 'O halde,  sen,  Allah yolunda savaş. Çünkü sen,  ancak kendinden sorumlusun. İnananları da teşvik et. Umulur ki Allah Kafirlerin baskısını kırar. Çünkü Allah\'ın baskısı daha güçlüdür. Cezalandırması daha şiddetlidir', 'فقتل في سبيل الله لا تكلف الا نفسك وحرض المومنين عسي الله ان يكف باس الذين كفروا والله اشد باسا واشد تنكيلا'),
(578, 4, 85, 'مَنْ يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُنْ لَهُ نَص۪يبٌ مِنْهَاۚ وَمَنْ يَشْفَعْ شَفَاعَةً سَيِّئَةً يَكُنْ لَهُ كِفْلٌ مِنْهَاۜ وَكَانَ اللّٰهُ عَلٰى كُلِّ شَيْءٍ مُق۪يتاً', 'Men yeşfa\' şefaaten haseneten yekun lehu nasibun minha, ve men yeşfa\' şefaaten seyyieten yekun lehu kiflun minha. Ve kanallahu ala kulli şey\'in mukita.', 'Her kim,  iyi bir işte şefaat[1] ederse,  ona o işten bir pay vardır. Her kim de kötü bir işte şefaat ederse,  ondan da ona bir pay vardır. Allah Her Şeyi Gözeten\'dir.', 'من يشفع شفعة حسنة يكن له نصيب منها ومن يشفع شفعة سيية يكن له كفل منها وكان الله علي كل شي مقيتا'),
(579, 4, 86, 'وَاِذَا حُيّ۪يتُمْ بِتَحِيَّةٍ فَحَيُّوا بِاَحْسَنَ مِنْهَٓا اَوْ رُدُّوهَاۜ اِنَّ اللّٰهَ كَانَ عَلٰى كُلِّ شَيْءٍ حَس۪يباً', 'Ve iza huyyitum bi tahıyyetin fe hayyu bi ahsene minha ev rudduha. İnnallahe kane ala kulli şey\'in hasiba.', 'Size,  selam[1] verildiği zaman,  ondan daha iyisiyle veya aynısıyla karşılık verin. Kuşkusuz ki Allah,  Her Şeyi Hesaplayan\'dır.', 'واذا حييتم بتحية فحيوا باحسن منها او ردوها ان الله كان علي كل شي حسيبا'),
(580, 4, 87, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۜ  لَيَجْمَعَنَّكُمْ اِلٰى يَوْمِ الْقِيٰمَةِ لَا رَيْبَ ف۪يهِۜ وَمَنْ اَصْدَقُ مِنَ اللّٰهِ حَد۪يثاً۟', 'Allahu la ilahe illa huve. Le yecmeannekum ila yevmil kıyameti la raybe fihi. Ve men asdeku minallahi hadisa.', 'Kendisinden başka ilah olmayan Allah,  gerçekleşeceği kesin olan Kıyamet Günü\'nde,  sizi kesin olarak toplayacaktır. Allah\'tan daha doğru sözlü kim olabilir?', 'الله لا اله الا هو ليجمعنكم الي يوم القيمة لا ريب فيه ومن اصدق من الله حديثا'),
(581, 4, 88, 'فَمَا لَكُمْ فِي الْمُنَافِق۪ينَ فِئَتَيْنِ وَاللّٰهُ اَرْكَسَهُمْ بِمَا كَسَبُواۜ اَتُر۪يدُونَ اَنْ تَهْدُوا مَنْ اَضَلَّ اللّٰهُۜ وَمَنْ يُضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهُ سَب۪يلاً', 'Fe ma lekum fil munafikine fieteyni vallahu erkesehum bi ma kesebu. E turidune en tehdu men edallallah. Ve men yudlilillahu fe len tecide lehu sebila.', 'Size ne oluyor ki; yaptıklarından dolayı,  Allah onları ters yüz ettiği halde,  münafıklar hakkında iki gruba ayrıldınız! Allah\'ın saptırdığı kimseyi,  doğru yola erdirmek mi istiyorsunuz? Allah\'ın saptırdığı kimse için asla bir çıkış yolu bulamazsın.', 'فما لكم في المنفقين فيتين والله اركسهم بما كسبوا اتريدون ان تهدوا من اضل الله ومن يضلل الله فلن تجد له سبيلا'),
(582, 4, 89, 'وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا فَتَكُونُونَ سَوَٓاءً فَلَا تَتَّخِذُوا مِنْهُمْ اَوْلِيَٓاءَ حَتّٰى يُهَاجِرُوا ف۪ي سَب۪يلِ اللّٰهِۜ فَاِنْ تَوَلَّوْا فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ وَجَدْتُمُوهُمْۖ وَلَا تَتَّخِذُوا مِنْهُمْ وَلِياًّ وَلَا نَص۪يراًۙ', 'Veddu lev tekfurune kema keferu fe tekunune sevaen fe la tettehızu minhum evliyae hatta yuhaciru fi sebilillah. Fe in tevellev fe huzuhum vaktuluhum haysu vecedtumuhum, ve la tettehızu minhum veliyyen ve la nasira.', 'Onlar,  sizin kendileri gibi küfre dönmenizi isterler,  ki onlar gibi olasınız. O halde,  Allah yolunda hicret edinceye kadar onları evliya edinmeyin. Eğer yüz çevirirlerse[1] onları yakalayın,  bulduğunuz yerde öldürün. Onlardan hiç kimseyi veli de yardımcı da edinmeyin.', 'ودوا لو تكفرون كما كفروا فتكونون سوا فلا تتخذوا منهم اوليا حتي يهاجروا في سبيل الله فان تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا'),
(583, 4, 90, 'اِلَّا الَّذ۪ينَ يَصِلُونَ اِلٰى قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ م۪يثَاقٌ اَوْ جَٓاؤُ۫كُمْ حَصِرَتْ صُدُورُهُمْ اَنْ يُقَاتِلُوكُمْ اَوْ يُقَاتِلُوا قَوْمَهُمْۜ وَلَوْ شَٓاءَ اللّٰهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَاتَلُوكُمْۚ فَاِنِ اعْتَزَلُوكُمْ فَلَمْ يُقَاتِلُوكُمْ وَاَلْقَوْا اِلَيْكُمُ السَّلَمَۙ فَمَا جَعَلَ اللّٰهُ لَكُمْ عَلَيْهِمْ سَب۪يلاً', 'İllallezine yasılune ila kavmin beynekum ve beynehum misakun ev caukum hasırat suduruhum en yukatilukum ev yukatilu kavmehum. Ve lev şaallahu le selletahum aleykum fe le katelukum, fe inı\'tezelukum fe lem yukatilukum ve elkav ileykumus seleme, fe ma cealallahu lekum aleyhim sebila.', 'Ancak,  aranızda antlaşma olan halka sığınanlar veya ne sizinle ne de kendi halkıyla savaşmayı içine sindiremeyip size gelenler hariç. Eğer Allah dileseydi,  onları başınıza musallat ederdi de sizinle savaşırlardı. Eğer tarafsız kalarak ve sizinle savaşmayıp barış isterlerse,  Allah onların aleyhinde size bir yol vermemiştir.', 'الا الذين يصلون الي قوم بينكم وبينهم ميثق او جاوكم حصرت صدورهم ان يقتلوكم او يقتلوا قومهم ولو شا الله لسلطهم عليكم فلقتلوكم فان اعتزلوكم فلم يقتلوكم والقوا اليكم السلم فما جعل الله لكم عليهم سبيلا'),
(584, 4, 91, 'سَتَجِدُونَ اٰخَر۪ينَ يُر۪يدُونَ اَنْ يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْۜ كُلَّمَا رُدُّٓوا اِلَى الْفِتْنَةِ اُرْكِسُوا ف۪يهَاۚ فَاِنْ لَمْ يَعْتَزِلُوكُمْ وَيُلْقُٓوا اِلَيْكُمُ السَّلَمَ وَيَكُفُّٓوا اَيْدِيَهُمْ فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْۜ وَاُو۬لٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَاناً مُب۪يناً۟', 'Se tecidune aharine yuridune en ye\'menukum ve ye\'menu kavmehum. Kullema ruddu ilal fitneti urkisu fiha, fe in lem ya\'tezilukum ve yulku ileykumus seleme ve yekuffu eydiyehum fe huzuhum vaktuluhum haysu sekıftumuhum. Ve ulaikum cealna lekum aleyhim sultanen mubina.', 'Başkalarını[1] da bulacaksınız hem sizden hem de kendi halklarından güvende olmak isteyen. Fitne ortamı[2] bulduklarında,  hemen onun içine baş aşağı dalarlar. Eğer bunlar,  sizden uzak durmazlar,  sizinle barış yapmaya yanaşmazlarsa,  sizden ellerini çekmezlerse onları yakaladığınız yerde,  her nerede bulursanız öldürün.[3] İşte bu kimseler hakkında size apaçık bir yetki verdik.', 'ستجدون اخرين يريدون ان يامنوكم ويامنوا قومهم كل ما ردوا الي الفتنة اركسوا فيها فان لم يعتزلوكم ويلقوا اليكم السلم ويكفوا ايديهم فخذوهم واقتلوهم حيث ثقفتموهم واوليكم جعلنا لكم عليهم سلطنا مبينا'),
(585, 4, 92, 'وَمَا كَانَ لِمُؤْمِنٍ اَنْ يَقْتُلَ مُؤْمِناً اِلَّا خَطَـٔاًۚ وَمَنْ قَتَلَ مُـؤْمِناً خَطَــٔاً فَـتَـحْر۪يرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ اِلٰٓى اَهْلِه۪ٓ اِلَّٓا اَنْ يَصَّدَّقُواۜ فَاِنْ كَانَ مِنْ قَوْمٍ عَدُوٍّ لَكُمْ وَهُوَ مُؤْمِنٌ فَتَحْر۪يرُ رَقَبَةٍ مُؤْمِنَةٍۜ وَاِنْ كَانَ مِنْ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ م۪يثَاقٌ فَدِيَةٌ مُسَلَّمَةٌ اِلٰٓى اَهْلِه۪ وَتَحْر۪يرُ رَقَبَةٍ مُؤْمِنَةٍۚ فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِۘ تَوْبَةً مِنَ اللّٰهِۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماً', 'Ve ma kane li mu\'minin en yaktule mu\'minen illa hataa, ve men katele mu\'minen hataen fe tahriru rakabetin mu\'minetin ve diyetun musellemetun ila ehlihi illa en yessaddaku. Fe in kane min kavmin aduvvin lekum ve huve mu\'minun fe tahriru rakabetin mu\'mineh. Ve in kane min kavmin beynekum ve beynehum misakun fe diyetun musellemetun ila ehlihi ve tahriru rakabetin mu\'mineh, fe men lem yecid fe sıyamu şehreyni mutetabiayni tevbeten minallah. Ve kanallahu alimen hakima.', 'Hata ile olması dışında,  bir Mü\'min\'in bir Mü\'min\'i öldürmesi olacak şey değildir. Kim,  hata ile bir Mü\'min\'i öldürürse,  Mü\'min bir rekabeyi[1] özgürlüğüne kavuştursun,  ailesi bağışlamadığı takdirde,  ölenin ailesine diyet ödesin. Eğer,  öldürülen mü\'min; düşmanınız olan bir halka mensupsa,  Mü\'min bir rekabeyi özgürlüğüne kavuştursun. Eğer,  aranızda anlaşma bulunan bir halktansa,  ailesine diyet vermek ve mü\'min bir rekabeyi özgürlüğüne kavuşturmak gerekir. Kim bunları bulamazsa,  Allah\'tan tevbesini kabul etmesi için ardı ardına iki ay siyam[2] yapmalıdır. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'وما كان لمومن ان يقتل مومنا الا خطا ومن قتل مومنا خطا فتحرير رقبة مومنة ودية مسلمة الي اهله الا ان يصدقوا فان كان من قوم عدو لكم وهو مومن فتحرير رقبة مومنة وان كان من قوم بينكم وبينهم ميثق فدية مسلمة الي اهله وتحرير رقبة مومنة فمن لم يجد فصيام شهرين متتابعين توبة من الله وكان الله عليما حكيما'),
(586, 4, 93, 'وَمَنْ يَقْتُلْ مُؤْمِناً مُتَعَمِّداً فَجَزَٓاؤُ۬هُ جَهَنَّمُ خَالِداً ف۪يهَا وَغَضِبَ اللّٰهُ عَلَيْهِ وَلَعَنَهُ وَاَعَدَّ لَهُ عَذَاباً عَظ۪يماً', 'Ve men yaktul mu\'minen muteammiden fe cezauhu cehennemu haliden fiha ve gadıballahu aleyhi ve leanehu ve eadde lehu azaben azima.', 'Kim,  bir Mü\'min\'i isteyerek öldürürse,  onun karşılığı,  içinde sürekli kalmak üzere Cehennem\'dir. Allah ona gazap etmiş,  lanetlemiş ve büyük bir azap hazırlamıştır.', 'ومن يقتل مومنا متعمدا فجزاوه جهنم خلدا فيها وغضب الله عليه ولعنه واعد له عذابا عظيما'),
(587, 4, 94, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا ضَرَبْتُمْ ف۪ي سَب۪يلِ اللّٰهِ فَتَبَيَّنُوا وَلَا تَقُولُوا لِمَنْ اَلْقٰٓى اِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِناًۚ تَبْتَغُونَ عَرَضَ الْحَيٰوةِ الدُّنْيَاۘ فَعِنْدَ اللّٰهِ مَغَانِمُ كَث۪يرَةٌۜ كَذٰلِكَ كُنْتُمْ مِنْ قَبْلُ فَمَنَّ اللّٰهُ عَلَيْكُمْ فَتَبَيَّنُواۜ اِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُونَ خَب۪يراً', 'Ya eyyuhallezine amenu iza darabtum fi sebilillahi fe tebeyyenu ve la tekulu li men elka ileykumus selame leste mu\'mina, tebtegune aradal hayatid dunya, fe indallahi meganimu kesirah. Kezalike kuntum min kablu fe mennallahu aleykum fe tebeyyenu. İnnallahe kane bima ta\'melune habira.', 'Ey iman edenler! Allah yolunda sefere çıktığınız zaman[1],  iyice araştırın[2]; size selam veren kimseye[3]; dünya hayatının geçici menfaatine göz dikerek: \"Sen Mü\'min değilsin.\" demeyin. Allah\'ın yanında sayısız ganimetler vardır. Daha önce siz de öyleydiniz de Allah size iyilik yaptı. Öyleyse,  iyice araştırın. Kuşkusuz,  Allah,  yaptığınız her şeyden haberdardır.', 'يايها الذين امنوا اذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن القي اليكم السلم لست مومنا تبتغون عرض الحيوة الدنيا فعند الله مغانم كثيرة كذلك كنتم من قبل فمن الله عليكم فتبينوا ان الله كان بما تعملون خبيرا'),
(588, 4, 95, 'لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِن۪ينَ غَيْرُ اُو۬لِي الضَّرَرِ وَالْمُجَاهِدُونَ ف۪ي سَب۪يلِ اللّٰهِ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْۜ فَضَّلَ اللّٰهُ الْمُجَاهِد۪ينَ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ عَلَى الْقَاعِد۪ينَ دَرَجَةًۜ وَكُلاًّ وَعَدَ اللّٰهُ الْحُسْنٰىۜ وَفَضَّلَ اللّٰهُ الْمُجَاهِد۪ينَ عَلَى الْقَاعِد۪ينَ اَجْراً عَظ۪يـماًۙ', 'La yestevil kaıdune minel mu\'minine gayru ulid darari vel mucahidune fi sebilillahi bi emvalihim ve enfusihim. Faddalallahul mucahidine bi emvalihim ve enfusihim alal kaidine dereceh. Ve kullen vaadallahul husna. Ve faddalallahul mucahidine alal kaıdine ecran azima.', 'Mü\'minlerden,  bir özrü olmaksızın,  Allah yolunda cihad[1] etmekten geri kalanlarla; mallarıyla ve canlarıyla Allah yolunda cihad edenler,  bir değildir. Allah,  malları ve canları ile cihad edenleri,  derece bakımından,  geri kalanlardan üstün kıldı. Her ne kadar Allah,  her ikisine de iyilikle muamele etmeyi söz vermiş ise de cihad edenleri,  geri kalanlara karşı çok daha büyük bir ecirle üstün kılmıştır;', 'لا يستوي القعدون من المومنين غير اولي الضرر والمجهدون في سبيل الله بامولهم وانفسهم فضل الله المجهدين بامولهم وانفسهم علي القعدين درجة وكلا وعد الله الحسني وفضل الله المجهدين علي القعدين اجرا عظيما'),
(589, 4, 96, 'دَرَجَاتٍ مِنْهُ وَمَغْفِرَةً وَرَحْمَةًۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً۟', 'Deracatin minhu ve magfiraten ve rahmet. Ve kanallahu gafuran rahima.', 'Kendinden derecelerle,  bağışlama ve rahmetle. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'درجت منه ومغفرة ورحمة وكان الله غفورا رحيما'),
(590, 4, 97, 'اِنَّ الَّذ۪ينَ تَوَفّٰيهُمُ الْمَلٰٓئِكَةُ ظَالِم۪ٓي اَنْفُسِهِمْ قَالُوا ف۪يمَ كُنْتُمْۜ  قَالُوا كُنَّا مُسْتَضْعَف۪ينَ فِي الْاَرْضِۜ قَالُٓوا اَلَمْ تَكُنْ اَرْضُ اللّٰهِ وَاسِعَةً فَتُهَاجِرُوا ف۪يهَاۜ فَاُو۬لٰٓئِكَ مَأْوٰيهُمْ جَهَنَّمُۜ وَسَٓاءَتْ مَص۪يراًۙ', 'İnnellezine teveffahumul melaiketu zalimi enfusihim kalu fime kuntum. Kalu kunna mustad\'afine fil ard. Kalu e lem tekun ardullahi vasiaten fe tuhaciru fiha. Fe ulaike me\'vahum cehennem ve saet masira.', 'Doğrusu,  kendilerine haksızlık eden kimselere[1],  melekler canlarını alırken: \"Neden bu durumdaydınız?\"[2] derler. Onlar: \"Biz yeryüzünde mus\'tezaf[3] kimselerdik\" derler. Melekler: \"Allah\'ın arzı geniş değil miydi,  hicret etseydiniz ya!\" derler. İşte bunların yeri Cehennem\'dir. Orası ne kötü bir yerdir.', 'ان الذين توفيهم المليكة ظالمي انفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الارض قالوا الم تكن ارض الله وسعة فتهاجروا فيها فاوليك ماويهم جهنم وسات مصيرا'),
(591, 4, 98, 'اِلَّا الْمُسْتَضْعَف۪ينَ مِنَ الرِّجَالِ وَالنِّسَٓاءِ وَالْوِلْدَانِ لَا يَسْتَط۪يعُونَ ح۪يلَةً وَلَا يَهْتَدُونَ سَب۪يلاً', 'İllal mustad\'afine miner ricali ven nisai vel vildani la yestatiune hileten ve la yehtedune sebila.', 'Ancak,  çaresiz kalan,  gücü yetmeyen,  bir çıkış yolu bulamayan mus\'tezaf[1] erkek,  kadın ve çocuklar hariç.', 'الا المستضعفين من الرجال والنسا والولدن لا يستطيعون حيلة ولا يهتدون سبيلا');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(592, 4, 99, 'فَاُو۬لٰٓئِكَ عَسَى اللّٰهُ اَنْ يَعْفُوَ عَنْهُمْۜ وَكَانَ اللّٰهُ عَفُواًّ غَفُوراً', 'Fe ulaike asallahu en ya\'fuve anhum. Ve kanallahu afuvven gafura.', 'Umulur ki Allah,  bunları affeder. Kuşkusuz Allah,  Çok Affedici\'dir,  Çok Bağışlayıcı\'dır.', 'فاوليك عسي الله ان يعفو عنهم وكان الله عفوا غفورا'),
(593, 4, 100, 'وَمَنْ يُهَاجِرْ ف۪ي سَب۪يلِ اللّٰهِ يَجِدْ فِي الْاَرْضِ مُرَاغَماً كَث۪يراً وَسَعَةًۜ وَمَنْ يَخْرُجْ مِنْ بَيْتِه۪ مُهَاجِراً اِلَى اللّٰهِ وَرَسُولِه۪ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ اَجْرُهُ عَلَى اللّٰهِۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً۟', 'Ve men yuhacir fi sebilillahi yecid fil ardı muragamen kesiran veseah. Ve men yahruc min beytihi muhaciran ilallahi ve resulihi summe yudrikhul mevtu fe kad vakaa ecruhu alallah. Ve kanallahu gafuran rahima.', 'Kim,  Allah yolunda hicret ederse,  yeryüzünde gidecek pek çok yer ve genişlik bulur. Kim,  Allah ve Resul\'ü için hicret edip,  yurdundan ayrılır da sonra onu ölüm yakalarsa,  onun ecri,  kesinlikle Allah\'a aittir. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ومن يهاجر في سبيل الله يجد في الارض مرغما كثيرا وسعة ومن يخرج من بيته مهاجرا الي الله ورسوله ثم يدركه الموت فقد وقع اجره علي الله وكان الله غفورا رحيما'),
(594, 4, 101, 'وَاِذَا ضَرَبْتُمْ فِي الْاَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَقْصُرُوا مِنَ الصَّلٰوةِۗ اِنْ خِفْتُمْ اَنْ يَفْتِنَكُمُ الَّذ۪ينَ كَفَرُواۜ اِنَّ الْكَافِر۪ينَ كَانُوا لَكُمْ عَدُواًّ مُب۪يناً', 'Ve iza darabtum fil ardı fe leyse aleykum cunahun en taksuru mines salati, in hıftum en yeftinekumullezine keferu. İnnel kafirine kanu lekum aduvven mubina.', 'Yeryüzünde sefere çıktığınız zaman,  eğer Kafirlerin[1] size kötülük yapmalarından korkarsanız,  salatı[2] kısaltmanızda[3] bir sakınca yoktur. Kuşkusuz,  gerçeği yalanlayan nankörler sizin apaçık düşmanınızdır.', 'واذا ضربتم في الارض فليس عليكم جناح ان تقصروا من الصلوة ان خفتم ان يفتنكم الذين كفروا ان الكفرين كانوا لكم عدوا مبينا'),
(595, 4, 102, 'وَاِذَا كُنْتَ ف۪يهِمْ فَاَقَمْتَ لَهُمُ الصَّلٰوةَ فَلْتَقُمْ طَٓائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُٓوا اَسْلِحَتَهُمْ۠ فَاِذَا سَجَدُوا فَلْيَكُونُوا مِنْ وَرَٓائِكُمْۖ وَلْتَأْتِ طَٓائِفَةٌ اُخْرٰى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَاَسْلِحَتَهُمْۚ وَدَّ الَّذ۪ينَ كَفَرُوا لَوْ تَغْفُلُونَ عَنْ اَسْلِحَتِكُمْ وَاَمْتِعَتِكُمْ فَيَم۪يلُونَ عَلَيْكُمْ مَيْلَةً وَاحِدَةًۜ وَلَا جُنَاحَ عَلَيْكُمْ اِنْ كَانَ بِكُمْ اَذًى مِنْ مَطَرٍ اَوْ كُنْتُمْ مَرْضٰٓى اَنْ تَضَعُٓوا اَسْلِحَتَكُمْۚ وَخُذُوا حِذْرَكُمْۜ اِنَّ اللّٰهَ اَعَدَّ لِلْكَافِر۪ينَ عَذَاباً مُه۪يناً', 'Ve iza kunte fihim fe ekamte lehumus salate fel tekum taifetun minhum meake vel ye\'huzu eslihatehum fe iza secedu fel yekunu min varaikum, vel te\'ti taifetun uhra lem yusallu fel yusallu meake vel ye\'huzu hızrahum ve eslihatehum, veddellezine keferu lev tagfulune an eslihatikum ve emtiatikum fe yemilune aleykum meyleten vahıdeh. Ve la cunaha aleykum in kane bikum ezen min matarin ev kuntum marda en tedau eslihatekum, ve huzu hızrakum. İnnallahe eadde lil kafirine azaben muhina.', 'Sen de içlerinde bulunup; onlara salatı ikame[1] ettirdiğin zaman,  onların bir kısmı seninle beraber salata[2] dursun ve silahlarını da yanlarına alsınlar. Bunlar,  secde edince,  arkanıza geçsinler. Sonra,  salat etmemiş olan diğer kısım gelsin,  seninle beraber salatı ikame etsin. Önlemlerini ve silahlarını da alsınlar. Kafirler,  silahlarınızdan ve eşyalarınızdan uzak kalmanızı arzu ederler ki,  size aniden baskın düzenlesinler.[3] Eğer yağmurdan dolayı bir eziyet görürseniz veya hasta olursanız,  önlemlerinizi alarak silahlarınızı bırakmanızda sizin için bir sakınca yoktur. Kuşkusuz,  Allah Kafirler için alçaltıcı bir azap hazırlamıştır.[4]', 'واذا كنت فيهم فاقمت لهم الصلوة فلتقم طايفة منهم معك ولياخذوا اسلحتهم فاذا سجدوا فليكونوا من ورايكم ولتات طايفة اخري لم يصلوا فليصلوا معك ولياخذوا حذرهم واسلحتهم ود الذين كفروا لو تغفلون عن اسلحتكم وامتعتكم فيميلون عليكم ميلة وحدة ولا جناح عليكم ان كان بكم اذي من مطر او كنتم مرضي ان تضعوا اسلحتكم وخذوا حذركم ان الله اعد للكفرين عذابا مهينا'),
(596, 4, 103, 'فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيَاماً وَقُعُوداً وَعَلٰى جُنُوبِكُمْۚ فَاِذَا اطْمَأْنَنْتُمْ فَاَق۪يمُوا الصَّلٰوةَۚ اِنَّ الصَّلٰوةَ كَانَتْ عَلَى الْمُؤْمِن۪ينَ كِتَاباً مَوْقُوتاً', 'Fe iza kadaytumus salate fezkurullahe kıyamen ve kuuden ve ala cunubikum, fe izatma\'nentum fe ekimus salat, innes salate kanet alal mu\'minine kitaben mevkuta.', 'Salatı ikame ettikten[1] sonra ayakta,  oturarak ve yanlarınız üzerinde Allah\'ı anın. Güvene kavuştuğunuz zaman,  salatı gereği gibi ikame edin. Kuşkusuz salat,  belirlenmiş vakitlerde[2] Mü\'minler üzerine yazılmıştır.[3]', 'فاذا قضيتم الصلوة فاذكروا الله قيما وقعودا وعلي جنوبكم فاذا اطماننتم فاقيموا الصلوة ان الصلوة كانت علي المومنين كتبا موقوتا'),
(597, 4, 104, 'وَلَا تَهِنُوا فِي ابْتِغَٓاءِ الْقَوْمِۜ اِنْ تَكُونُوا تَأْلَمُونَ فَاِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَۚ وَتَرْجُونَ مِنَ اللّٰهِ مَا لَا يَرْجُونَۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماً۟', 'Ve la tehinu fibtigail kavm. İn tekunu te\'lemune fe innehum ye\'lemune kema te\'lemun, ve tercune minallahi ma la yercun. Ve kanallahu alimen hakima.', 'Düşman halkı takip etmekte gevşeklik göstermeyin. Eğer siz acı çekiyorsanız,  onlar da sizin acı çektiğiniz gibi acı çekiyorlar. Üstelik siz,  Allah\'tan onların ummadıkları şeyleri umuyorsunuz. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'ولا تهنوا في ابتغا القوم ان تكونوا تالمون فانهم يالمون كما تالمون وترجون من الله ما لا يرجون وكان الله عليما حكيما'),
(598, 4, 105, 'اِنَّٓا اَنْزَلْـنَٓا اِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَٓا اَرٰيكَ اللّٰهُۜ وَلَا تَكُنْ لِلْخَٓائِن۪ينَ خَص۪يماًۙ', 'İnna enzelna ileykel kitabe bil hakkı li tahkume beynen nasi bima erakallah. Ve la tekun lil hainine hasima.', 'Biz,  insanlar arasında,  Allah\'ın sana gösterdiği gibi hükmedesin diye,  Kitap\'ı hakikat[1] olarak indirdik. Hainlerin savunucusu olma.', 'انا انزلنا اليك الكتب بالحق لتحكم بين الناس بما اريك الله ولا تكن للخاينين خصيما'),
(599, 4, 106, 'وَاسْتَغْفِرِ اللّٰهَۜ اِنَّ اللّٰهَ كَانَ غَفُوراً رَح۪يماًۚ', 'Vestagfirillah. İnnallahe kane gafuran rahima.', 'Allah\'tan bağışlanma dile. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'واستغفر الله ان الله كان غفورا رحيما'),
(600, 4, 107, 'وَلَا تُجَادِلْ عَنِ الَّذ۪ينَ يَخْتَانُونَ اَنْفُسَهُمْۜ اِنَّ اللّٰهَ لَا يُحِبُّ مَنْ كَانَ خَوَّاناً اَث۪يماًۚ', 'Ve la tucadil anillezine yahtanune enfusehum innallahe la yuhıbbu men kane havvanen esima.', 'Kendilerine ihanet eden[1] kimselerden yana savunma yapma. Kuşkusuz Allah,  ihanette ısrar eden günahkarları sevmez.', 'ولا تجدل عن الذين يختانون انفسهم ان الله لا يحب من كان خوانا اثيما'),
(601, 4, 108, 'يَسْتَخْفُونَ مِنَ النَّاسِ وَلَا يَسْتَخْفُونَ مِنَ اللّٰهِ وَهُوَ مَعَهُمْ اِذْ يُبَيِّتُونَ مَا لَا يَرْضٰى مِنَ الْقَوْلِۜ وَكَانَ اللّٰهُ بِمَا يَعْمَلُونَ مُح۪يـطاً', 'Yestahfune minen nasi ve la yestahfune minallahi ve huve meahum iz yubeyyitune ma la yarda minel kavl. Ve kanallahu bi ma ya\'melune muhita.', 'İnsanlardan gizliyorlar da Allah\'tan gizleyemezler. Oysa Allah,  razı olmayacağı sözü geceleyin[1] düzüp kurarlarken[2] onlarla beraberdi. Kuşkusuz,  Allah,  onların yaptığı her şeyi kuşatandır.', 'يستخفون من الناس ولا يستخفون من الله وهو معهم اذ يبيتون ما لا يرضي من القول وكان الله بما يعملون محيطا'),
(602, 4, 109, 'هَٓا اَنْتُمْ هٰٓؤُ۬لَٓاءِ جَادَلْتُمْ عَنْهُمْ فِي الْحَيٰوةِ الدُّنْيَا فَمَنْ يُجَادِلُ اللّٰهَ عَنْهُمْ يَوْمَ الْقِيٰمَةِ اَمْ مَنْ يَكُونُ عَلَيْهِمْ وَك۪يلاً', 'Ha entum haulai cadeltum anhum fil hayatid dunya fe men yucadilullahe anhum yevmel kıyameti em men yekunu aleyhim vekila.', 'Diyelim ki bu dünya hayatında onları savundunuz,  peki ya Kıyamet Günü,  Allah\'a karşı onları kim savunacak veya onlara kim vekil[1] olacak?', 'هانتم هولا جدلتم عنهم في الحيوة الدنيا فمن يجدل الله عنهم يوم القيمة ام من يكون عليهم وكيلا'),
(603, 4, 110, 'وَمَنْ يَعْمَلْ سُٓوءاً اَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوراً رَح۪يماً', 'Ve men ya\'mel suen ev yazlim nefsehu summe yestagfirillahe yecidillahe gafuran rahima.', 'Kim bir kötülük yapar veya kendisine haksızlık eder[1] de,  sonra Allah\'tan bağışlanma dilerse; Allah\'ı,  Çok Bağışlayıcı ve Kesintisiz Rahmet edici bulur.', 'ومن يعمل سوا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما'),
(604, 4, 111, 'وَمَنْ يَكْسِبْ اِثْماً فَاِنَّمَا يَكْسِبُهُ عَلٰى نَفْسِه۪ۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماً', 'Ve men yeksib ismen fe innema yeksibuhu ala nefsihi. Ve kanallahu alimen hakima.', 'Kim bir günah işlerse,  onu ancak kendi aleyhine işlemiş olur. Kuşkusuz,  Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'ومن يكسب اثما فانما يكسبه علي نفسه وكان الله عليما حكيما'),
(605, 4, 112, 'وَمَنْ يَكْسِبْ خَط۪ٓيـَٔةً اَوْ اِثْماً ثُمَّ يَرْمِ بِه۪ بَر۪ٓيـٔاً فَقَدِ احْتَمَلَ بُهْتَـاناً وَاِثْماً مُب۪يناً۟', 'Ve men yeksib hatieten ev ismen summe yermi bihi berien fe kadihtemele buhtanen ve ismen mubina.', 'Kim bir yanlış yapar veya günah işler,  sonra da onu suçsuz birinin üzerine atarsa,  muhakkak ki büyük bir iftira ve apaçık bir günah yüklenmiş olur.', 'ومن يكسب خطية او اثما ثم يرم به بريا فقد احتمل بهتنا واثما مبينا'),
(606, 4, 113, 'وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكَ وَرَحْمَتُهُ لَهَمَّتْ طَٓائِفَةٌ مِنْهُمْ اَنْ يُضِلُّوكَۜ وَمَا يُضِلُّونَ اِلَّٓا اَنْفُسَهُمْ وَمَا يَضُرُّونَكَ مِنْ شَيْءٍۜ وَاَنْزَلَ اللّٰهُ عَلَيْكَ الْكِتَابَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُۜ وَكَانَ فَضْلُ اللّٰهِ عَلَيْكَ عَظ۪يماً', 'Ve lev la fadlullahi aleyke ve rahmetuhu le hemmet taifetun minhum en yudılluke. Ve ma yudıllune illa enfusehum ve ma yadurruneke min şey\'. Ve enzelallahu aleykel kitabe vel hikmete ve allemeke ma lem tekun ta\'lem. Ve kane fadlullahi aleyke azima.', 'Allah\'ın,  sana lütfu ve rahmeti olmasaydı,  onlardan[1] bazıları seni saptırmaya yeltenmişti. Oysa onlar,  kendilerinden başkasını saptıramazlar. Sana hiçbir zarar veremezler. Allah,  sana Kitap\'ı ve Hikmet\'i[2] indirdi ve sana bilmediklerini öğretti. Kuşkusuz,  Allah\'ın sana lütfu çok büyüktür.', 'ولولا فضل الله عليك ورحمته لهمت طايفة منهم ان يضلوك وما يضلون الا انفسهم وما يضرونك من شي وانزل الله عليك الكتب والحكمة وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما'),
(607, 4, 114, 'لَا خَيْرَ ف۪ي كَث۪يرٍ مِنْ نَجْوٰيهُمْ اِلَّا مَنْ اَمَرَ بِصَدَقَةٍ اَوْ مَعْرُوفٍ اَوْ اِصْلَاحٍ بَيْنَ النَّاسِۜ وَمَنْ يَفْعَلْ ذٰلِكَ ابْتِغَٓاءَ مَرْضَاتِ اللّٰهِ فَسَوْفَ نُؤْت۪يهِ اَجْراً عَظ۪يماً', 'La hayra fi kesirin min necvahum illa men emera bi sadakatin ev ma\'rufin ev ıslahın beynen nas. Ve men yef\'al zalikebtigae mardatillahi fe sevfe nu\'tihi ecran azima.', 'Hak gözetmeyi,  iyi şeyler yapmayı ve,  insanların arasını düzeltmeyi isteyenlerin görüşmeleri hariç,  onların gizli görüşmelerinde bir hayır yoktur. Kim bunları yalnızca Allah\'ın rızasını kazanmak için yaparsa,  ileride ona büyük bir ödül vereceğiz.', 'لا خير في كثير من نجويهم الا من امر بصدقة او معروف او اصلح بين الناس ومن يفعل ذلك ابتغا مرضات الله فسوف نوتيه اجرا عظيما'),
(608, 4, 115, 'وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدٰى وَيَتَّبِـعْ غَيْرَ سَب۪يلِ الْمُؤْمِن۪ينَ نُوَلِّه۪ مَا تَوَلّٰى وَنُصْلِه۪ جَهَنَّمَۜ وَسَٓاءَتْ مَص۪يراً۟', 'Ve men yuşakıkır resule min ba\'di ma tebeyyene lehul huda ve yettebi\' gayra sebilil mu\'minine nuvellıhi ma tevella ve nuslihi cehennem. Ve saet masira.', 'Kendisine doğru yol belli olduktan sonra,  her kim Resul\'e karşı gelir,  Mü\'minlerin yolundan başkasına yönelirse,  onu saptığı yolda bırakırız. Onu Cehennem\'e atarız. Orası ne kötü bir dönüş yeridir.', 'ومن يشاقق الرسول من بعد ما تبين له الهدي ويتبع غير سبيل المومنين نوله ما تولي ونصله جهنم وسات مصيرا'),
(609, 4, 116, 'اِنَّ اللّٰهَ لَا يَغْفِرُ اَنْ يُشْرَكَ بِه۪ وَيَغْفِرُ مَا دُونَ ذٰلِكَ لِمَنْ يَشَٓاءُۜ وَمَنْ يُشْرِكْ بِاللّٰهِ فَقَدْ ضَلَّ ضَلَالاً بَع۪يداً', 'İnnallahe la yagfiru en yuşrake bihi ve yagfiru ma dune zalike li men yeşau. Ve men yuşrik billahi fe kad dalle dalalen baida.', 'Allah,  kendisine şirk koşanları bağışlamaz. Bunun dışında hak edeni[1] bağışlar. Kim Allah\'a şirk koşarsa,  derin bir sapkınlıkla sapmış olur.', 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشا ومن يشرك بالله فقد ضل ضللا بعيدا'),
(610, 4, 117, 'اِنْ يَدْعُونَ مِنْ دُونِه۪ٓ اِلَّٓا اِنَاثاًۚ وَاِنْ يَدْعُونَ اِلَّا شَيْطَاناً مَر۪يداًۙ', 'İn yed\'une min dunihi illa inasa, ve in yed\'une illa şeytanen merida.', 'Onlar,  O\'nu bırakıp,  birtakım dişilere[1] yalvarıyorlar,  oysa onların yalvardıkları azgın şeytandan başkası değildir.', 'ان يدعون من دونه الا انثا وان يدعون الا شيطنا مريدا'),
(611, 4, 118, 'لَعَنَهُ اللّٰهُۢ وَقَالَ لَاَتَّخِذَنَّ مِنْ عِبَادِكَ نَص۪يباً مَفْرُوضاًۙ', 'Leanehullah, ve kale le ettehizenne min ibadike nasiben mefruda.', 'Allah onu lanetledi[1] ve o da: \"Ant olsun ki senin kullarından farz olarak[2] alacağım[3].\" dedi.', 'لعنه الله وقال لاتخذن من عبادك نصيبا مفروضا'),
(612, 4, 119, 'وَلَاُضِلَّنَّهُمْ وَلَاُمَنِّيَنَّهُمْ وَلَاٰمُرَنَّهُمْ فَلَيُبَتِّكُنَّ اٰذَانَ الْاَنْعَامِ وَلَاٰمُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ اللّٰهِۜ وَمَنْ يَتَّخِذِ الشَّيْطَانَ وَلِياًّ مِنْ دُونِ اللّٰهِ فَقَدْ خَسِرَ خُسْرَاناً مُب۪يناًۜ', 'Ve le udillennehum ve le umenniyennehum ve le amurannehum fe le yubettikunne azanel en\'ami, ve le amurannehum fe le yugayyirunne halkallah.', 'Mutlaka onları saptırıp,  asılsız kuruntulara daldıracağım; onlara buyuracağım,  davarların kulaklarını yaracaklar;[1] onlara buyuracağım,  Allah\'ın yarattığını bozacaklar[2]. Kim,  Allah\'ın yanı sıra şeytanı veli[3] edinirse,  apaçık bir zarara uğramış olur.', 'ولاضلنهم ولامنينهم ولامرنهم فليبتكن اذان الانعم ولامرنهم فليغيرن خلق الله ومن يتخذ الشيطن وليا من دون الله فقد خسر خسرانا مبينا'),
(613, 4, 120, 'يَعِدُهُمْ وَيُمَنّ۪يهِمْۜ وَمَا يَعِدُهُمُ الشَّيْطَانُ اِلَّا غُرُوراً', 'Yeıduhum, ve yumennihim. Ve ma yeıduhumuş şeytanu illa gurura.', 'Şeytan,  onlara vaatlerde bulunup,  onları kuruntulara sürükler. Şeytan,  ancak aldatmak için vaatte bulunur.', 'يعدهم ويمنيهم وما يعدهم الشيطن الا غرورا'),
(614, 4, 121, 'اُو۬لٰٓئِكَ مَأْوٰيهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَح۪يصاً', 'Ulaike me\'vahum cehennemu ve la yecidune anha mahisa.', 'Onların varacakları yer Cehennem\'dir ve oradan kurtulmak için hiçbir yol bulamayacaklar.', 'اوليك ماويهم جهنم ولا يجدون عنها محيصا'),
(615, 4, 122, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ وَعْدَ اللّٰهِ حَقاًّۜ وَمَنْ اَصْدَقُ مِنَ اللّٰهِ ق۪يلاً', 'Vellezine amenu ve amilus salihati se nudhiluhum cennatin tecri min tahtihal enharu halidine fiha ebeda. Va\'dallahi hakka.  Ve men asdaku minallahi kila.', 'İman edip,  salihatı[1] yapanları,  içinde kesintisiz ve ebedi olarak kalacakları,  altlarından ırmaklar akan Cennetlere koyacağız. Allah\'ın verdiği söz hakikattir. Allah\'tan daha doğru sözlü kim olabilir?', 'والذين امنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا وعد الله حقا ومن اصدق من الله قيلا'),
(616, 4, 123, 'لَيْسَ بِاَمَانِيِّكُمْ وَلَٓا اَمَانِيِّ اَهْلِ الْكِتَابِۜ مَنْ يَعْمَلْ سُٓوءاً يُجْزَ بِه۪ۙ وَلَا يَجِدْ لَهُ مِنْ دُونِ اللّٰهِ وَلِياًّ وَلَا نَص۪يراً', 'Leyse bi emaniyyikum ve la emaniyyi ehlil kitab. Men ya\'mel suen yucze bihi, ve la yecid lehu min dunillahi veliyyen ve la nasira.', 'Ne sizin kuruntularınız ne de Ehli Kitap\'ın kuruntularına göre değil; kim bir kötülük yaparsa,  onun karşılığını bulur. O,  kendisine Allah\'tan başka ne bir veli ne de bir yardımcı bulabilir.', 'ليس بامانيكم ولا اماني اهل الكتب من يعمل سوا يجز به ولا يجد له من دون الله وليا ولا نصيرا'),
(617, 4, 124, 'وَمَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ مِنْ ذَكَرٍ اَوْ اُنْثٰى وَهُوَ مُؤْمِنٌ فَاُو۬لٰٓئِكَ يَدْخُلُونَ الْجَنَّةَ وَلَا يُظْلَمُونَ نَق۪يراً', 'Ve men ya\'mel mines salihati min zekerin ev unsa ve huve mu\'minun fe ulaike yedhulunel cennete ve la yuzlemune nakira.', 'Erkek ve kadın; her kim Mü\'min olarak salihatı[1] yaparsa,  işte onlar Cennet\'e gireceklerdir. Ve onlara zerre kadar haksızlık edilmeyecektir.', 'ومن يعمل من الصلحت من ذكر او انثي وهو مومن فاوليك يدخلون الجنة ولا يظلمون نقيرا'),
(618, 4, 125, 'وَمَنْ اَحْسَنُ د۪يناً مِمَّنْ اَسْلَمَ وَجْهَهُ لِلّٰهِ وَهُوَ مُحْسِنٌ وَاتَّبَعَ مِلَّةَ اِبْرٰه۪يمَ حَن۪يفاًۜ وَاتَّخَذَ اللّٰهُ اِبْرٰه۪يمَ خَل۪يلاً', 'Ve men ahsenu dinen mimmen esleme vechehu lillahi ve huve muhsinun vettebea millete ibrahime hanifa. Vettehazallahu ibrahime halila.', 'Kimin dini,  kendisini muhsin[1] olarak Allah\'a teslim etmiş; hanif[2] olan İbrahim\'in milletine[3] tabi olandan daha iyi olabilir? Allah,  İbrahim\'i \"halil\"[4] edinmişti.', 'ومن احسن دينا ممن اسلم وجهه لله وهو محسن واتبع ملة ابرهيم حنيفا واتخذ الله ابرهيم خليلا'),
(619, 4, 126, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَكَانَ اللّٰهُ بِكُلِّ شَيْءٍ مُح۪يطاً۟', 'Ve lillahi ma fis semavati ve ma fil ard. Ve kanallahu bi kulli şey\'in muhita.', 'Göklerde ve yerde olan her şey Allah\'a aittir. Ve Allah,  Her Şeyi Kuşatmıştır.', 'ولله ما في السموت وما في الارض وكان الله بكل شي محيطا'),
(620, 4, 127, 'وَيَسْتَفْتُونَكَ فِي النِّسَٓاءِۜ قُلِ اللّٰهُ يُفْت۪يكُمْ ف۪يهِنَّۙ وَمَا يُتْلٰى عَلَيْكُمْ فِي الْكِتَابِ ف۪ي يَتَامَى النِّسَٓاءِ الّٰت۪ي لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ اَنْ تَنْكِحُوهُنَّ وَالْمُسْتَضْعَف۪ينَ مِنَ الْوِلْدَانِۙ وَاَنْ تَقُومُوا لِلْيَتَامٰى بِالْقِسْطِۜ وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَاِنَّ اللّٰهَ كَانَ بِه۪ عَل۪يماً', 'Ve yesteftuneke fin nisai. Kulillahu yuftikum fihinne, ve ma yutla aleykum fil kitabi fi yetamen nisaillati la tu\'tunehunne ma kutibe lehunne ve tergabune en tenkihuhunne vel mustad\'afine minel vildani, ve en tekumu lil yetama bil kıst. Ve ma tef\'alu min hayrin fe innallahe kane bihi alima.', 'Senden,  o kadınlar[1] hakkında fetva istiyorlar.[2] De ki: \"Onlar hakkında size fetvayı Allah vermektedir: Yazılmış olanı[3] vermediğiniz halde kendileri ile evlenmek istediğiniz yetim[4] kadınlarla zayıf,  çaresiz çocukların ve yetimlerin haklarını hakkaniyetle vermeniz konusundaki hükümler size bu kitapta okunuyor. Hayır adına ne yaparsanız Allah onu bilir.', 'ويستفتونك في النسا قل الله يفتيكم فيهن وما يتلي عليكم في الكتب في يتمي النسا التي لا توتونهن ما كتب لهن وترغبون ان تنكحوهن والمستضعفين من الولدن وان تقوموا لليتمي بالقسط وما تفعلوا من خير فان الله كان به عليما'),
(621, 4, 128, 'وَاِنِ امْرَاَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزاً اَوْ اِعْرَاضاً فَلَا جُنَاحَ عَلَيْهِمَٓا اَنْ يُصْلِحَا بَيْنَهُمَا صُلْحاًۜ وَالصُّلْحُ خَيْرٌۜ وَاُحْضِرَتِ الْاَنْفُسُ الشُّحَّۜ وَاِنْ تُحْسِنُوا وَتَتَّقُوا فَاِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُونَ خَب۪يراً', 'Ve in imraetun hafet min ba\'liha nuşuzen ev ı\'radan fe la cunaha aleyhima en yuslıha beynehuma sulha. Ves sulhu hayr. Ve uhdıratil enfusuş şuhh. Ve in tuhsinu ve tetteku fe innallahe kane bi ma ta\'melune habira.', 'Eğer bir kadın,  kocasının nuşuzundan[1] veya kendisinden yüz çevirmesinden endişe ederse,  uzlaşmaya çalışmalarında bir sakınca yoktur. Uzlaşmak,  daha hayırlıdır. Zira benlikler bencilliğe[2] eğimlidir. Eğer arayı düzeltmek ister ve takvalı davranırsanız; Allah,  Yaptığınız Her Şeyden Haberdar\'dır.', 'وان امراة خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير واحضرت الانفس الشح وان تحسنوا وتتقوا فان الله كان بما تعملون خبيرا'),
(622, 4, 129, 'وَلَنْ تَسْتَط۪يعُٓوا اَنْ تَعْدِلُوا بَيْنَ النِّسَٓاءِ وَلَوْ حَرَصْتُمْ فَلَا تَم۪يلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِۜ وَاِنْ تُصْلِحُوا وَتَتَّقُوا فَاِنَّ اللّٰهَ كَانَ غَفُوراً رَح۪يماً', 'Ve len testatiu en ta\'dilu beynen nisai ve lev harastum fe la temilu kullel meyli fe tezeruha kel muallakah. Ve in tuslihu ve tetteku fe innallahe kane gafuran rahima.', 'Ne kadar isteseniz de kadınlar arasında[1] tam anlamı ile adaletli olmaya kesinlikle güç yetiremezsiniz. O halde,  anlaşmazlığı çözümsüz hale getirip,  onları yüzüstü bırakmayın. Eğer,  arayı düzelterek,  takvalı davranırsanız kuşkusuz ki Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ولن تستطيعوا ان تعدلوا بين النسا ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقة وان تصلحوا وتتقوا فان الله كان غفورا رحيما'),
(623, 4, 130, 'وَاِنْ يَتَفَرَّقَا يُغْنِ اللّٰهُ كُلاًّ مِنْ سَعَتِه۪ۜ وَكَانَ اللّٰهُ وَاسِعاً حَك۪يماً', 'Ve in yeteferreka yugnillahu kullen min seatihi. Ve kanallahu vasian hakima.', 'Eğer karı-koca ayrılırlarsa,  Allah,  kudretiyle her birini kendi kendilerine yeterli kılar. Kuşkusuz Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Egemenlik Sahibi\'dir.', 'وان يتفرقا يغن الله كلا من سعته وكان الله وسعا حكيما'),
(624, 4, 131, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَلَقَدْ وَصَّيْنَا الَّذ۪ينَ اُو۫تُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَاِيَّاكُمْ اَنِ اتَّقُوا اللّٰهَۜ وَاِنْ تَكْفُرُوا فَاِنَّ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَكَانَ اللّٰهُ غَنِياًّ حَم۪يداً', 'Ve lillahi ma fis semavati ve ma fil ard. Ve lekad vassaynallezine utul kitabe min kablikum ve iyyakum enittekullah. Ve in tekfuru fe inne lillahi ma fis semavati ve ma fil ard. Ve kanallahu ganiyyen hamida.', 'Göklerde ve yerde olan her şey yalnızca Allah\'ındır. Ant olsun,  sizden önce kitap verilenlere ve size Allah\'a karşı takvalı olun diye tavsiyede bulunduk. Eğer gerçeği yalanlayarak nankörlük ederseniz,  göklerde ve yerde olan her şey yalnızca Allah\'ındır. Hiçbir Şeye Muhtaç Olmayan,  Övgüye Değer Yegane Varlık yalnızca Allah\'tır.', 'ولله ما في السموت وما في الارض ولقد وصينا الذين اوتوا الكتب من قبلكم واياكم ان اتقوا الله وان تكفروا فان لله ما في السموت وما في الارض وكان الله غنيا حميدا'),
(625, 4, 132, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَكَفٰى بِاللّٰهِ وَك۪يلاً', 'Ve lillahi ma fis semavati ve ma fil ard. Ve kefa billahi vekila.', 'Göklerde ve yerde olan her şey,  yalnızca Allah\'ındır. Vekil[1] olarak Allah yeter.', 'ولله ما في السموت وما في الارض وكفي بالله وكيلا'),
(626, 4, 133, 'اِنْ يَشَأْ يُذْهِبْكُمْ اَيُّهَا النَّاسُ وَيَأْتِ بِاٰخَر۪ينَۜ وَكَانَ اللّٰهُ عَلٰى ذٰلِكَ قَد۪يراً', 'İn yeşa\' yuzhibkum eyyuhan nasu ve ye\'ti bi aharin. Ve kanallahu ala zalike kadira.', 'Ey insanlar! Eğer Allah dilerse sizi yok edip,  yerinize başkalarını getirir. Kuşkusuz,  Allah\'ın bunu yapmaya gücü yeter.', 'ان يشا يذهبكم ايها الناس ويات باخرين وكان الله علي ذلك قديرا'),
(627, 4, 134, 'مَنْ كَانَ يُر۪يدُ ثَوَابَ الدُّنْيَا فَعِنْدَ اللّٰهِ ثَوَابُ الدُّنْيَا وَالْاٰخِرَةِۜ وَكَانَ اللّٰهُ سَم۪يعاً بَص۪يراً۟', 'Men kane yuridu sevabed dunya fe indallahi sevabud dunya vel ahırah. Ve kanallahu semian basira.', 'Kim dünya sevabını[1] isterse; bilsin ki dünyanın da ahiretin de sevabı yalnızca Allah katındadır. Allah,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والاخرة وكان الله سميعا بصيرا'),
(628, 4, 135, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُونُوا قَوَّام۪ينَ بِالْقِسْطِ شُهَدَٓاءَ لِلّٰهِ وَلَوْ عَلٰٓى اَنْفُسِكُمْ اَوِ الْوَالِدَيْنِ وَالْاَقْرَب۪ينَۚ اِنْ يَكُنْ غَنِياًّ اَوْ فَق۪يراً فَاللّٰهُ اَوْلٰى بِهِمَا فَلَا تَتَّبِعُوا الْهَوٰٓى اَنْ تَعْدِلُواۚ وَاِنْ تَلْـوُٓ۫ا اَوْ تُعْرِضُوا فَاِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُونَ خَب۪يراً', 'Ya eyyuhallezine amenu kunu kavvamine bil kıstı şuhedae lillahi ve lev ala enfusıkum evil valideyni vel akrabin, in yekun ganiyyen ev fakiran fallahu evla bihima fe la tettebiul heva en ta\'dilu, ve in telvu ev tu\'rıdu fe innallahe kane bi ma ta\'melune habira.', 'Ey iman edenler! Kendinizin,  anne ve babanızın ve akrabalarınızın aleyhine bile olsa; tanıklık ettiğiniz kimseler,  zengin de olsa,  fakir de olsa,  Allah için hakkaniyetli tanıklar olarak adaleti gerçek anlamıyla yerine getirin. Allah,  onlara sizden daha yakındır. Haddi aşarak,  tutkunuza tabi olmayın. Eğer gerçeği çarpıtıp,  yüz çevirirseniz,  Allah,  bütün yaptıklarınızdan haberdardır.', 'يايها الذين امنوا كونوا قومين بالقسط شهدا لله ولو علي انفسكم او الولدين والاقربين ان يكن غنيا او فقيرا فالله اولي بهما فلا تتبعوا الهوي ان تعدلوا وان تلوا او تعرضوا فان الله كان بما تعملون خبيرا'),
(629, 4, 136, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اٰمِنُوا بِاللّٰهِ وَرَسُولِه۪ وَالْكِتَابِ الَّذ۪ي نَزَّلَ عَلٰى رَسُولِه۪ وَالْكِتَابِ الَّـذ۪ٓي اَنْزَلَ مِنْ قَبْلُۜ  وَمَنْ يَكْفُرْ بِاللّٰهِ وَمَلٰٓئِكَتِه۪ وَكُتُبِه۪ وَرُسُلِه۪ وَالْيَوْمِ الْاٰخِرِ فَقَدْ ضَلَّ ضَلَالاً بَع۪يداً', 'Ya eyyuhallezine amenu, aminu billahi ve resulihi vel kitabillezi nezzele ala resulihi vel kitabillezi enzele min kabl. Ve men yekfur billahi ve melaiketihi ve kutubihi ve rusulihi vel yevmil ahıri fe kad dalle dalalen baida.', 'Ey iman edenler! Allah\'a,  Resul\'üne ve Resul\'üne indirdiği Kitap\'a ve daha önce indirilmiş kitaplara iman edin[1]. Kim,  Allah\'ı,  meleklerini,  kitaplarını,  resullerini ve Ahiret Günü\'nü küfrederse; o,  çok derin bir sapkınlığa düşmüştür.', 'يايها الذين امنوا امنوا بالله ورسوله والكتب الذي نزل علي رسوله والكتب الذي انزل من قبل ومن يكفر بالله ومليكته وكتبه ورسله واليوم الاخر فقد ضل ضللا بعيدا'),
(630, 4, 137, 'اِنَّ الَّذ۪ينَ اٰمَنُوا ثُمَّ   كَفَرُوا ثُمَّ اٰمَنُوا ثُمَّ   كَفَرُوا ثُمَّ ازْدَادُوا كُفْراً لَمْ يَكُنِ اللّٰهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَب۪يلاًۜ', 'İnnellezine amenu, summe keferu, summe amenu, summe keferu, summezdadu kufran lem yekunillahu li yagfira lehum ve la li yehdiyehum sebila.', 'İman edip sonra küfreden[1],  sonra iman edip,  tekrar küfreden; sonra küfründe ileri gidenleri[2],  Allah ne affedecek ne de doğru yola iletecektir.', 'ان الذين امنوا ثم كفروا ثم امنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا'),
(631, 4, 138, 'بَشِّرِ الْمُنَافِق۪ينَ بِاَنَّ لَهُمْ عَذَاباً اَل۪يماًۙ', 'Beşşiril munafikine bi enne lehum azaben elima.', 'Münafıklara duyur! Onlar için can yakıcı bir azap vardır.', 'بشر المنفقين بان لهم عذابا اليما'),
(632, 4, 139, 'اَلَّذ۪ينَ يَتَّخِذُونَ الْكَافِر۪ينَ اَوْلِيَٓاءَ مِنْ دُونِ الْمُؤْمِن۪ينَۜ اَيَبْتَغُونَ عِنْدَهُمُ الْعِزَّةَ فَاِنَّ الْعِزَّةَ لِلّٰهِ جَم۪يعاًۜ', 'Ellezine yettehızunel kafirine evliyae min dunil mu\'minin, e yebtegune indehumul izzete fe innel izzete lillahi cemia.', 'Çünkü onlar Mü\'minlerin yanı sıra Kafirleri evliya[1] ediniyorlar. İzzeti[2] onların yanında mı arıyorlar! Kuşkusuz,  izzet,  tamamıyla Allah\'ın yanındadır.', 'الذين يتخذون الكفرين اوليا من دون المومنين ايبتغون عندهم العزة فان العزة لله جميعا'),
(633, 4, 140, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِي الْكِتَابِ اَنْ اِذَا سَمِعْتُمْ اٰيَاتِ اللّٰهِ يُكْفَرُ بِهَا وَيُسْتَهْزَاُ بِهَا فَلَا تَقْعُدُوا مَعَهُمْ حَتّٰى يَخُوضُوا ف۪ي حَد۪يثٍ غَيْرِه۪ۘ اِنَّكُمْ اِذاً مِثْلُهُمْۜ اِنَّ اللّٰهَ جَامِـعُ الْمُنَافِق۪ينَ وَالْكَافِر۪ينَ ف۪ي جَهَنَّمَ جَم۪يعاًۙ', 'Ve kad nezzele aleykum fil kitabi en iza semi\'tum ayatillahi yukferu biha ve yustehzeu biha fe la tak\'udu meahum hatta yehudu fi hadisin gayrihi, innekum izen misluhum. İnnallahe camiul munafikine vel kafirine fi cehenneme cemia.', 'Ve O,  size indirdiği Kitap\'ta: \"Ayetlerinin küfredildiğini ve alaya alındığını duyduğunuz zaman başka bir söze geçinceye kadar onlarla beraber bulunmayın,  yoksa onlar gibi olursunuz.\" diye bildirdi. Kuşkusuz,  Allah,  bütün münafıkları ve Kafirleri Cehennem\'de toplayacaktır.', 'وقد نزل عليكم في الكتب ان اذا سمعتم ايت الله يكفر بها ويستهزا بها فلا تقعدوا معهم حتي يخوضوا في حديث غيره انكم اذا مثلهم ان الله جامع المنفقين والكفرين في جهنم جميعا'),
(634, 4, 141, 'اَلَّذ۪ينَ يَتَرَبَّصُونَ بِكُمْۚ فَاِنْ كَانَ لَكُمْ فَتْحٌ مِنَ اللّٰهِ قَالُٓوا اَلَمْ نَكُنْ مَعَكُمْۘ وَاِنْ كَانَ لِلْكَافِر۪ينَ نَص۪يبٌۙ قَالُٓوا اَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُمْ مِنَ الْمُؤْمِن۪ينَۜ فَاللّٰهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيٰمَةِۜ وَلَنْ يَجْعَلَ اللّٰهُ لِلْكَافِر۪ينَ عَلَى الْمُؤْمِن۪ينَ سَب۪يلاً۟', 'Ellezine yeterabbesune bikum, fe in kane lekum fethun minallahi kalu e lem nekun meakum, ve in kane lil kafirine nasibun, kalu e lem nestahviz aleykum ve nemna\'kum minel mu\'minin. Ve len yec\'alallahu lil kafirine alal mu\'minine sebila.', 'Onlar,  sürekli sizi gözetliyorlar,  eğer Allah size bir zafer verirse: \"Biz de sizinle beraber değil miydik?\" derler. Eğer,  Kafirler üstünlük sağlarlarsa: \"Biz sizin üstün gelmenizi sağlamadık mı,  Mü\'minlerden korumadık mı?\" derler. Kuşkusuz,  Allah,  Kıyamet Günü aranızda hükmünü verecektir. Allah,  Mü\'minlere karşı,  Kafirlere asla bir yol vermeyecektir.', 'الذين يتربصون بكم فان كان لكم فتح من الله قالوا الم نكن معكم وان كان للكفرين نصيب قالوا الم نستحوذ عليكم ونمنعكم من المومنين فالله يحكم بينكم يوم القيمة ولن يجعل الله للكفرين علي المومنين سبيلا'),
(635, 4, 142, 'اِنَّ الْمُنَافِق۪ينَ يُخَادِعُونَ اللّٰهَ وَهُوَ خَادِعُهُمْۚ وَاِذَا قَامُٓوا اِلَى الصَّلٰوةِ قَامُوا كُسَالٰىۙ يُرَٓاؤُ۫نَ النَّاسَ وَلَا يَذْكُرُونَ اللّٰهَ اِلَّا قَل۪يلاًۘ', 'İnnel munafikine yuhadiunallahe ve huve hadiuhum, ve iza kamu ilas salati kamu kusala yuraunen nase ve la yezkurunallahe illa kalila.', 'Münafıklar,  Allah\'ı aldatmaya çalışırlar. Oysa O,  onların planlarını boşa çıkarandır. Onlar,  \"salatı ikame ettikleri\"[1] zaman üşene üşene yaparlar\" İnsanlara gösteriş yaparlar. Allah\'ı da pek az zikrederler.[2]', 'ان المنفقين يخدعون الله وهو خدعهم واذا قاموا الي الصلوة قاموا كسالي يراون الناس ولا يذكرون الله الا قليلا'),
(636, 4, 143, 'مُذَبْذَب۪ينَ بَيْنَ ذٰلِكَۗ لَٓا اِلٰى هٰٓؤُ۬لَٓاءِ وَلَٓا اِلٰى هٰٓؤُ۬لَٓاءِۜ وَمَنْ يُضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهُ سَب۪يلاً', 'Muzebzebine beyne zalike, la ila haulai ve la ila haulai. Ve men yudlilillahu fe len tecide lehu sebila.', 'Ne onlara ne bunlara,  arada bocalayıp dururlar[1]. Allah,  kimi doğru yoldan yoksun bırakırsa[2],  sen ona asla bir yol bulamazsın.', 'مذبذبين بين ذلك لا الي هولا ولا الي هولا ومن يضلل الله فلن تجد له سبيلا'),
(637, 4, 144, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُوا الْكَافِر۪ينَ اَوْلِيَٓاءَ مِنْ دُونِ الْمُؤْمِن۪ينَۜ اَتُر۪يدُونَ اَنْ تَجْعَلُوا لِلّٰهِ عَلَيْكُمْ سُلْطَاناً مُب۪يناً', 'Ya eyyuhallezine amenu la tettehızul kafirine evliyae min dunil mu\'minin. E turidune en tec\'alu lillahi aleykum sultanen mubina.', 'Ey iman edenler! Mü\'minlerin yanı sıra Kafirleri evliya edinmeyin. Allah\'a,  aleyhinize olacak apaçık bir sultan[1] mı vermek istiyorsunuz?', 'يايها الذين امنوا لا تتخذوا الكفرين اوليا من دون المومنين اتريدون ان تجعلوا لله عليكم سلطنا مبينا'),
(638, 4, 145, 'اِنَّ الْمُنَافِق۪ينَ فِي الدَّرْكِ الْاَسْفَلِ مِنَ النَّارِۚ وَلَنْ تَجِدَ لَهُمْ نَص۪يراًۙ', 'İnnel munafikine fid derkil esfeli minen nar, ve len tecide lehum nasira.', 'Münafıklar,  ateşin en alt tabakasında olacaklar. Ve onlara asla bir yardımcı bulamazsın.', 'ان المنفقين في الدرك الاسفل من النار ولن تجد لهم نصيرا'),
(639, 4, 146, 'اِلَّا الَّذ۪ينَ تَابُوا وَاَصْلَحُوا وَاعْتَصَمُوا بِاللّٰهِ وَاَخْلَصُوا د۪ينَهُمْ لِلّٰهِ فَاُو۬لٰٓئِكَ مَعَ الْمُؤْمِن۪ينَۜ وَسَوْفَ يُؤْتِ اللّٰهُ الْمُؤْمِن۪ينَ اَجْراً عَظ۪يماً', 'İllallezine tabu ve aslehu va\'tesamu billahi ve ahlesu dinehum lillahi fe ulaike meal mu\'minin. Ve sevfe yu\'tillahul mu\'minine ecran azima.', 'Ancak tevbe edip,  kendilerini düzeltenler,  Allah\'ın buyruklarına sımsıkı sarılanlar,  dinlerini yalnızca Allah\'a has kılanlar hariç. İşte bunlar,  Mü\'minlerle beraberdirler. Allah,  zamanı geldiğinde,  Mü\'minlere büyük bir ödül verecektir.', 'الا الذين تابوا واصلحوا واعتصموا بالله واخلصوا دينهم لله فاوليك مع المومنين وسوف يوت الله المومنين اجرا عظيما'),
(640, 4, 147, 'مَا يَفْعَلُ اللّٰهُ بِعَذَابِكُمْ اِنْ شَكَرْتُمْ وَاٰمَنْتُمْۜ وَكَانَ اللّٰهُ شَاكِراً عَل۪يماً', 'Ma yef\'alullahu bi azabikum in şekertum ve amentum. Ve kanallahu şakiran alima.', 'Eğer şükreder[1] ve iman ederseniz,  Allah size neden azap etsin? Allah Şakir\'dir.[2] Her Şeyi Bilen\'dir.', 'ما يفعل الله بعذابكم ان شكرتم وامنتم وكان الله شاكرا عليما'),
(641, 4, 148, 'لَا يُحِبُّ اللّٰهُ الْجَهْرَ بِالسُّٓوءِ مِنَ الْقَوْلِ اِلَّا مَنْ ظُلِمَۜ وَكَانَ اللّٰهُ سَم۪يعاً عَل۪يماً', 'La yuhibbullahul cehra bis sui minel kavli illa men zulim. Ve kanallahu semian alima.', 'Allah,  kendisine haksızlık yapılan kişinin dışında,  kötü sözün açıkça dillendirilmesini sevmez. Kuşkusuz,  Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'لا يحب الله الجهر بالسو من القول الا من ظلم وكان الله سميعا عليما'),
(642, 4, 149, 'اِنْ تُبْدُوا خَيْراً اَوْ تُخْفُوهُ اَوْ تَعْفُوا عَنْ سُٓوءٍ فَاِنَّ اللّٰهَ كَانَ عَفُواًّ قَد۪يراً', 'İn tubdu hayran ev tuhfuhu ev ta\'fu an suin fe innallahe kane afuvven kadira.', 'Eğer bir iyiliği açıklar veya gizlerseniz veya bir kötülüğü bağışlarsanız bilin ki,  Allah da Çok Affedici\'dir,  Her Şeye Güç Yetiren\'dir.', 'ان تبدوا خيرا او تخفوه او تعفوا عن سو فان الله كان عفوا قديرا'),
(643, 4, 150, 'اِنَّ الَّذ۪ينَ يَكْفُرُونَ بِاللّٰهِ وَرُسُلِه۪ وَيُر۪يدُونَ اَنْ يُفَرِّقُوا بَيْنَ اللّٰهِ وَرُسُلِه۪ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍۙ وَيُر۪يدُونَ اَنْ يَتَّخِذُوا بَيْنَ ذٰلِكَ سَب۪يلاًۙ', 'İnnellezine yekfurune billahi ve rusulihi ve yuridune en yuferriku beynallahi ve rusulihi ve yekulune nu\'minu bi ba\'din ve nekfuru bi ba\'dın, ve yuridune en yettehızu beyne zalike sebila.', 'Allah\'ı ve resullerini küfredenler[1],  Allah ile resullerinin arasını ayırmak isterler: \"Bir kısmına inanır bir kısmına inanmayız.[2]\" derler. Böylece,  arada bir yol tutmak isterler.', 'ان الذين يكفرون بالله ورسله ويريدون ان يفرقوا بين الله ورسله ويقولون نومن ببعض ونكفر ببعض ويريدون ان يتخذوا بين ذلك سبيلا'),
(644, 4, 151, 'اُو۬لٰٓئِكَ هُمُ الْكَافِرُونَ حَقاًّۚ وَاَعْتَدْنَا لِلْكَافِر۪ينَ عَذَاباً مُه۪يناً', 'Ulaike humul kafirune hakka, ve a\'tedna lil kafirine azaben muhina.', 'İşte onlar gerçekten,  Kafirlerdir[1]. Biz de Kafirlere alçaltıcı bir azap hazırladık.', 'اوليك هم الكفرون حقا واعتدنا للكفرين عذابا مهينا'),
(645, 4, 152, 'وَالَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَرُسُلِه۪ وَلَمْ يُفَرِّقُوا بَيْنَ اَحَدٍ مِنْهُمْ اُو۬لٰٓئِكَ سَوْفَ يُؤْت۪يهِمْ اُجُورَهُمْۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً۟', 'Vellezine amenu billahi ve rusulihi ve lem yuferriku beyne ehadin minhum ulaike sevfe yu\'tihim ucurahum. Ve kanallahu gafuran rahima.', 'O kimseler ki Allah\'a ve resullerine iman edip,  resuller arasında hiçbir ayırım yapmazlar. İşte onlara,  gelecekte ödülleri verilecektir. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'والذين امنوا بالله ورسله ولم يفرقوا بين احد منهم اوليك سوف يوتيهم اجورهم وكان الله غفورا رحيما'),
(646, 4, 153, 'يَسْـَٔلُكَ اَهْلُ الْكِتَابِ اَنْ تُنَزِّلَ عَلَيْهِمْ كِتَاباً مِنَ السَّمَٓاءِ فَقَدْ سَاَلُوا مُوسٰٓى اَكْبَرَ مِنْ ذٰلِكَ فَقَالُٓوا اَرِنَا اللّٰهَ جَهْرَةً فَاَخَذَتْهُمُ الصَّاعِقَةُ بِظُلْمِهِمْۚ ثُمَّ اتَّخَذُوا الْعِجْلَ مِنْ بَعْدِ مَا جَٓاءَتْهُمُ الْبَيِّنَاتُ فَعَفَوْنَا عَنْ ذٰلِكَۚ وَاٰتَيْنَا مُوسٰى سُلْطَاناً مُب۪يناً', 'Yes\'eluke ehlul kitabi en tunezzile aleyhim kitaben mines semai fe kad seelu musa ekbera min zalike fe kalu erinallahe cehraten fe ehazethumus saikatu bi zulmihim, summettehazul ıcle min ba\'di ma caethumul beyyinatu fe afevna an zalik, ve ateyna musa sultanen mubina.', 'Ehli Kitap,  senden,  kendilerine gökten bir kitap indirmeni istiyorlar. Daha önce Musa\'dan bundan daha büyüğünü istemişlerdi: \"Bize Allah\'ı açıkça göster.\" demişlerdi. Bu haksızlıklarından dolayı,  onları yıldırım çarpmıştı. Sonra kendilerine apaçık kanıtlar içeren bilgiler geldiği halde yine de buzağıyı ilah edindiler. Biz onları bağışladık ve Musa\'ya apaçık bir yetki verdik.', 'يسلك اهل الكتب ان تنزل عليهم كتبا من السما فقد سالوا موسي اكبر من ذلك فقالوا ارنا الله جهرة فاخذتهم الصعقة بظلمهم ثم اتخذوا العجل من بعد ما جاتهم البينت فعفونا عن ذلك واتينا موسي سلطنا مبينا'),
(647, 4, 154, 'وَرَفَعْنَا فَوْقَهُمُ الطُّورَ بِم۪يثَاقِهِمْ وَقُلْنَا لَهُمُ ادْخُلُوا الْبَابَ سُجَّداً وَقُلْنَا لَهُمْ لَا تَعْدُوا فِي السَّبْتِ وَاَخَذْنَا مِنْهُمْ م۪يثَاقاً غَل۪يظاً', 'Ve rafa\'na fevkahumut tura bi misakıhim ve kulna lehumudhulul babe succeden ve kulna lehum la ta\'du fis sebti ve ehazna minhum misakan galiza.', 'Kesin söz vermelerinden dolayı Tur\'u üzerlerine yükseltmiştik. Onlara,  \"Kapıdan secde ederek[1] girin.\" dedik. Yine onlara,  \"Cumartesi\'nde haddi aşmayın.\" dedik. Biz,  onlardan kesin söz aldık.', 'ورفعنا فوقهم الطور بميثقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت واخذنا منهم ميثقا غليظا'),
(648, 4, 155, 'فَبِمَا نَقْضِهِمْ م۪يثَاقَهُمْ وَكُفْرِهِمْ بِاٰيَاتِ اللّٰهِ وَقَتْلِهِمُ الْاَنْبِيَٓاءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۜ بَلْ طَبَعَ اللّٰهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ اِلَّا قَل۪يلاًۖ', 'Fe bima nakdıhim misakahum ve kufrihim bi ayatillahi ve katlihimul enbiyae bi gayrı hakkın ve kavlihim kulubuna gulf. Bel tabaallahu aleyha bi kufrihim fe la yu\'minune illa kalila.', 'Verdikleri sözü bozdukları,  Allah\'ın ayetlerini küfrettikleri,  nebileri haksız yere öldürdükleri ve \"Bizim kalplerimiz örtülüdür.\" dedikleri için; evet Allah,  Küfürlerinden dolayı,  onların kalplerini mühürlemiştir. Bu nedenle pek azı hariç,  iman etmezler.', 'فبما نقضهم ميثقهم وكفرهم بايت الله وقتلهم الانبيا بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يومنون الا قليلا'),
(649, 4, 156, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلٰى مَرْيَمَ بُهْتَاناً عَظ۪يماًۙ', 'Ve bi kufrihim ve kavlihim ala meryeme buhtanen azima.', 'Küfretmeleri ve Meryem\'e büyük bir iftira atmaları;', 'وبكفرهم وقولهم علي مريم بهتنا عظيما'),
(650, 4, 157, 'وَقَوْلِهِمْ اِنَّا قَتَلْنَا الْمَس۪يحَ ع۪يسَى ابْنَ مَرْيَمَ رَسُولَ اللّٰهِۚ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلٰكِنْ شُبِّهَ لَهُمْۜ وَاِنَّ الَّذ۪ينَ اخْتَلَفُوا ف۪يهِ لَف۪ي شَكٍّ مِنْهُۜ مَا لَهُمْ بِه۪ مِنْ عِلْمٍ اِلَّا اتِّبَاعَ الظَّنِّۚ وَمَا قَتَلُوهُ يَق۪يناًۙ', 'Ve kavlihim inna katelnal mesiha isabne meryeme resulallah, ve ma kateluhu ve ma salebuhu ve lakin şubbihe lehum. Ve innellezinahtelefu fihi le fi şekkin minhu. Ma lehum bihi min ilmin illattibaaz zann, ve ma kateluhu yakina.', 'Ve yine Allah\'ın Resulü Meryem oğlu İsa Mesih\'i,  \"Kesinlikle biz öldürdük.\" demeleri nedeniyle. Aslında onu öldürmediler ve onu asmadılar da. Fakat kendilerine öyle göründü. Onlar,  herhangi bir bilgi sahibi olmadıklarından,  ayrılığa düştükleri bu konuda kesin olarak şüphe içindedirler. Onlar,  sadece zanna uyuyorlar. Kesin olan şu ki,  onu öldürmediler.', 'وقولهم انا قتلنا المسيح عيسي ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وان الذين اختلفوا فيه لفي شك منه ما لهم به من علم الا اتباع الظن وما قتلوه يقينا'),
(651, 4, 158, 'بَلْ رَفَعَهُ اللّٰهُ اِلَيْهِۜ وَكَانَ اللّٰهُ عَز۪يزاً حَك۪يماً', 'Bel rafaahullahu ileyh. Ve kanallahu azizen hakima.', 'Aksine Allah,  onu kendisine yükseltti.[1] Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'بل رفعه الله اليه وكان الله عزيزا حكيما'),
(652, 4, 159, 'وَاِنْ مِنْ اَهْلِ الْكِتَابِ اِلَّا لَيُؤْمِنَنَّ بِه۪ قَبْلَ مَوْتِه۪ۚ وَيَوْمَ الْقِيٰمَةِ يَكُونُ عَلَيْهِمْ شَه۪يداًۚ', 'Ve in min ehlil kitabi illa le yu\'minenne bihi kable mevtihi, ve yevmel kıyameti yekunu aleyhim şehida.', 'Kitap Ehli\'nden her biri ölümünden önce ona inanmak zorundadır. Kıyamet günü O onlar hakkında tanık olur.', 'وان من اهل الكتب الا ليومنن به قبل موته ويوم القيمة يكون عليهم شهيدا'),
(653, 4, 160, 'فَبِظُلْمٍ مِنَ الَّذ۪ينَ هَادُوا حَرَّمْنَا عَلَيْهِمْ طَيِّبَاتٍ اُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَنْ سَب۪يلِ اللّٰهِ كَث۪يراًۙ', 'Fe bi zulmin minellezine hadu harramna aleyhim tayyibatin uhıllet lehum ve bi saddihim an sebilillahi kesira.', 'Böylece,  zulümleri ve Allah yolundan çokça alıkoymaları nedeniyle daha önce helal olan temiz birçok şeyi Yahudilere haram kıldık.', 'فبظلم من الذين هادوا حرمنا عليهم طيبت احلت لهم وبصدهم عن سبيل الله كثيرا'),
(654, 4, 161, 'وَاَخْذِهِمُ الرِّبٰوا وَقَدْ نُهُوا عَنْهُ وَاَكْلِهِمْ اَمْوَالَ النَّاسِ بِالْبَاطِلِۜ وَاَعْتَدْنَا لِلْكَافِر۪ينَ مِنْهُمْ عَذَاباً اَل۪يماً', 'Ve ahzihimur riba ve kad nuhu anhu ve eklihim emvalen nasi bil batıl. Ve a\'tedna lil kafirine minhum azaben elima.', 'Yine,  yasaklandığı halde,  onlardan riba[1] alan ve haksız yoldan insanların mallarını yiyen Kafirlere[2]; çok acı bir azap hazırladık.', 'واخذهم الربوا وقد نهوا عنه واكلهم امول الناس بالبطل واعتدنا للكفرين منهم عذابا اليما'),
(655, 4, 162, 'لٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَٓا اُنْزِلَ اِلَيْكَ وَمَٓا اُنْزِلَ مِنْ قَبْلِكَ وَالْمُق۪يم۪ينَ الصَّلٰوةَ وَالْمُؤْتُونَ الزَّكٰوةَ وَالْمُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ اُو۬لٰٓئِكَ سَنُؤْت۪يهِمْ اَجْراً عَظ۪يماً۟', 'Lakinir rasihune fil ilmi minhum vel mu\'minune yu\'minune bi ma unzile ileyke ve ma unzile min kablike vel mukimines salate vel mu\'tunez zekate vel mu\'minune billahi vel yevmil ahir. Ulaike se nu\'tihim ecran azima.', 'Ancak,  onlardan ilimde derinleşmiş[1] olanlar ve Mü\'minler,  sana ve senden önce indirilene inanırlar. Salatı ikame edenler,  zekatı yapanlar[2],  Allah\'a ve Ahiret Günü\'ne iman edenler; işte onlara büyük bir ödül vereceğiz.', 'لكن الرسخون في العلم منهم والمومنون يومنون بما انزل اليك وما انزل من قبلك والمقيمين الصلوة والموتون الزكوة والمومنون بالله واليوم الاخر اوليك سنوتيهم اجرا عظيما'),
(656, 4, 163, 'اِنَّٓا اَوْحَيْنَٓا اِلَيْكَ كَمَٓا اَوْحَيْنَٓا اِلٰى نُوحٍ وَالنَّبِيّ۪نَ مِنْ بَعْدِه۪ۚ وَاَوْحَيْنَٓا اِلٰٓى اِبْرٰه۪يمَ وَاِسْمٰع۪يلَ وَاِسْحٰقَ وَيَعْقُوبَ وَالْاَسْبَاطِ وَع۪يسٰى وَاَيُّوبَ وَيُونُسَ وَهٰرُونَ وَسُلَيْمٰنَۚ وَاٰتَيْنَا دَاوُ۫دَ زَبُوراًۚ', 'İnna evhayna ileyke kema evhayna ila nuhin ven nebiyyine min ba\'dihi, ve evhayna ila ibrahime ve ismaile ve ishaka ve ya\'kube vel esbati ve isa ve eyyube ve yunuse ve harune ve suleyman, ve ateyna davude zebura.', 'Biz,  Nuh\'a ve ondan sonraki bütün nebilere vahyettiğimiz gibi,  sana da vahyettik. Ve biz İbrahim\'e,  İsmail\'e,  İshak\'a,  Yakup\'a,  torunlarına,  İsa\'ya,  Eyyub\'a,  Yunus\'a,  Harun\'a ve Süleyman\'a vahyettik. Ve Davud\'a da Zebur\'u verdik.', 'انا اوحينا اليك كما اوحينا الي نوح والنبين من بعده واوحينا الي ابرهيم واسمعيل واسحق ويعقوب والاسباط وعيسي وايوب ويونس وهرون وسليمن واتينا داود زبورا'),
(657, 4, 164, 'وَرُسُلاً قَدْ قَصَصْنَاهُمْ عَلَيْكَ مِنْ قَبْلُ وَرُسُلاً لَمْ نَقْصُصْهُمْ عَلَيْكَۜ وَكَلَّمَ اللّٰهُ مُوسٰى تَكْل۪يماًۚ', 'Ve rusulen kad kasasnahum aleyke min kablu ve rusulen lem naksushum aleyk. Ve kellemallahu musa teklima.', 'Senden önce gönderdiğimiz resullerden birçoğunu sana anlattık,  birçoğunu da anlatmadık. Ve Allah,  Musa\'yla kelimelerle[1] konuştu.', 'ورسلا قد قصصنهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسي تكليما'),
(658, 4, 165, 'رُسُلاً مُبَشِّر۪ينَ وَمُنْذِر۪ينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللّٰهِ حُجَّةٌ بَعْدَ الرُّسُلِۜ وَكَانَ اللّٰهُ عَز۪يزاً حَك۪يماً', 'Rusulen mubeşşirine ve munzirine li ella yekune lin nasi alallahi huccetun ba\'der rusul. Ve kanallahu azizen hakima.', 'Haber verici ve uyarıcı olarak resuller gönderdik ki,  resullerden sonra insanların Allah\'a karşı bir bahaneleri olmasın. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'رسلا مبشرين ومنذرين ليلا يكون للناس علي الله حجة بعد الرسل وكان الله عزيزا حكيما'),
(659, 4, 166, 'لٰكِنِ اللّٰهُ يَشْهَدُ بِمَٓا اَنْزَلَ اِلَيْكَ اَنْزَلَهُ بِعِلْمِه۪ۚ وَالْمَلٰٓئِكَةُ يَشْهَدُونَۜ وَكَفٰى بِاللّٰهِ شَه۪يداً', 'Lakinillahu yeşhedu bi ma enzele ileyke enzelehu bi ılmihi, vel melaiketu yeşhedun. Ve kefa billahi şehida.', 'Allah,  sana indirdiği şeyi,  kendi ilmi ile indirdiğine tanıklık eder. Melekler de tanıklık ederler. Ve tabii ki tanık olarak Allah yeter.', 'لكن الله يشهد بما انزل اليك انزله بعلمه والمليكة يشهدون وكفي بالله شهيدا'),
(660, 4, 167, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ قَدْ ضَلُّوا ضَلَالاً بَع۪يداً', 'İnnellezine keferu ve saddu an sebilillahi kad dallu dalalen baida.', 'Kuşkusuz Kafir olanlar ve Allah\'ın yolundan alıkoyanlar,  gerçekten derin bir sapkınlıktadırlar.', 'ان الذين كفروا وصدوا عن سبيل الله قد ضلوا ضللا بعيدا'),
(661, 4, 168, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَظَلَمُوا لَمْ يَكُنِ اللّٰهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَر۪يقاًۙ', 'İnnellezine keferu ve zalemu lem yekunillahu li yagfira lehum ve la li yehdiyehum tarika.', 'Kuşkusuz Allah Kafir olanları ve zulmedenleri bağışlayacak değildir. Onları bir yola iletecek de değildir;', 'ان الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا'),
(662, 4, 169, 'اِلَّا طَر۪يقَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ وَكَانَ ذٰلِكَ عَلَى اللّٰهِ يَس۪يراً', 'İlla tarika cehenneme halidine fiha ebeda. Ve kane zalike alallahi yesira.', 'Ancak Cehennem yolundan başka. Orada,  kesintisiz ve ebedi olarak kalıcıdırlar. Bu,  Allah için çok kolaydır.', 'الا طريق جهنم خلدين فيها ابدا وكان ذلك علي الله يسيرا'),
(663, 4, 170, 'يَٓا اَيُّهَا النَّاسُ قَدْ جَٓاءَكُمُ الرَّسُولُ بِالْحَقِّ مِنْ رَبِّكُمْ فَاٰمِنُوا خَيْراً لَكُمْۜ وَاِنْ تَكْفُرُوا فَاِنَّ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماً', 'Ya eyyuhan nasu kad caekumur resulu bil hakkı min rabbikum fe aminu hayran lekum. Ve in tekfuru fe inne lillahi ma fis semavati vel ard. Ve kanallahu alimen hakima.', 'Ey insanlar! Resul size Rabb\'inizden gerçeği getirdi. Öyleyse kendi iyiliğiniz için ona iman edin. Eğer Kafirlik[1] ederseniz,  bilin ki gökte ve yerde olan her şey Allah\'a aittir. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يايها الناس قد جاكم الرسول بالحق من ربكم فامنوا خيرا لكم وان تكفروا فان لله ما في السموت والارض وكان الله عليما حكيما'),
(664, 4, 171, 'يَٓا اَهْلَ الْكِتَابِ لَا تَغْلُوا ف۪ي د۪ينِكُمْ وَلَا تَقُولُوا عَلَى اللّٰهِ اِلَّا الْحَقَّۜ اِنَّمَا الْمَس۪يحُ ع۪يسَى ابْنُ مَرْيَمَ رَسُولُ اللّٰهِ وَكَلِمَتُهُۚ اَلْقٰيهَٓا اِلٰى مَرْيَمَ وَرُوحٌ مِنْهُۘ فَاٰمِنُوا بِاللّٰهِ وَرُسُلِه۪ۚ وَلَا تَقُولُوا ثَلٰثَةٌۜ اِنْتَهُوا خَيْراً لَكُمْۜ اِنَّمَا اللّٰهُ اِلٰهٌ وَاحِدٌۜ سُبْحَانَهُٓ اَنْ يَكُونَ لَهُ وَلَدٌۢ لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَكَفٰى بِاللّٰهِ وَك۪يلاً۟', 'Ya ehlel kitabi la taglu fi dinikum ve la tekulu alallahi illal hakk. İnnemal mesihu isabnu meryeme resulullahi ve kelimetuhu.  Elkaha ila meryeme ve ruhun minhu, fe aminu billahi ve rusulihi, ve la tekulu selaseh. İntehu hayran lekum. İnnemallahu ilahun vahid. Subhanehu en yekune lehu veled, lehu ma fis semavati ve ma fil ard. Ve kefa billahi vekila.', 'Ey Kitap Ehli! Dininiz hakkında haddi aşmayın. Allah hakkında,  gerçek olandan başka bir şey söylemeyin. Allah\'ın Resulü İsa Mesih,  Meryem\'in oğludur. Ve o,  Allah\'ın Meryem\'e attığı Kelime[1] ve Kendisinden bir ruhtur. O halde Allah\'a ve resullerine iman edin. Ve \"Üçtür.\" demeyin. Buna son verin. Bu,  sizin için hayırlı olandır. Kuşkusuz Allah,  tek bir ilahtır. O,  çocuk sahibi olmaktan münezzehtir. Göklerde ve yerde ne varsa O\'nundur. Vekil olarak Allah yeter.', 'ياهل الكتب لا تغلوا في دينكم ولا تقولوا علي الله الا الحق انما المسيح عيسي ابن مريم رسول الله وكلمته القيها الي مريم وروح منه فامنوا بالله ورسله ولا تقولوا ثلثة انتهوا خيرا لكم انما الله اله وحد سبحنه ان يكون له ولد له ما في السموت وما في الارض وكفي بالله وكيلا'),
(665, 4, 172, 'لَنْ يَسْتَنْكِفَ الْمَس۪يحُ اَنْ يَكُونَ عَبْداً لِلّٰهِ وَلَا الْمَلٰٓئِكَةُ الْمُقَرَّبُونَۜ وَمَنْ يَسْتَنْكِفْ عَنْ عِبَادَتِه۪ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ اِلَيْهِ جَم۪يعاً', 'Len yestenkifel mesihu en yekune abden lillahi ve lal melaiketul mukarrabun. Ve men yestenkif an ibadetihi ve yestekbir fe se yahşuruhum ileyhi cemia.', 'Ne Mesih ne de mukarrabin[1] melekler Allah\'a kul olmaktan kaçınmazlar. Kim büyüklenerek O\'na kulluk etmekten kaçınırsa,  bilsin ki O,  yakında onların tamamını huzuruna toplayacaktır.', 'لن يستنكف المسيح ان يكون عبدا لله ولا المليكة المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم اليه جميعا'),
(666, 4, 173, 'فَاَمَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفّ۪يهِمْ اُجُورَهُمْ وَيَز۪يدُهُمْ مِنْ فَضْلِه۪ۚ وَاَمَّا الَّذ۪ينَ اسْتَنْكَفُوا وَاسْتَكْبَرُوا فَيُعَذِّبُهُمْ عَذَاباً اَل۪يماًۙ وَلَا يَجِدُونَ لَهُمْ مِنْ دُونِ اللّٰهِ وَلِياًّ وَلَا نَص۪يراً', 'Fe emmallezine amenu ve amilus salihati fe yuveffihim ucurahum ve yeziduhum min fadlihi, ve emmallezinestenkefu vestekberu fe yuazzibuhum azaben elimen, ve la yecidune lehum min dunillahi veliyyen ve la nasira.', 'Ama iman edip,  salihatı[1] yapan kimselerin,  yaptıklarının karşılığı eksiksiz verilecektir. Ve Kendi fazlından daha da artıracaktır. Ama büyüklük taslayan ve kibirlenen kimselere gelince,  onlara can yakıcı bir azap ile azap edecek. Ve onlar,  Allah\'tan başka ne bir yardımcı ne de bir veli[2] bulabilirler.', 'فاما الذين امنوا وعملوا الصلحت فيوفيهم اجورهم ويزيدهم من فضله واما الذين استنكفوا واستكبروا فيعذبهم عذابا اليما ولا يجدون لهم من دون الله وليا ولا نصيرا'),
(667, 4, 174, 'يَٓا اَيُّهَا النَّاسُ قَدْ جَٓاءَكُمْ بُرْهَانٌ مِنْ رَبِّكُمْ وَاَنْزَلْـنَٓا اِلَيْكُمْ نُوراً مُب۪يناً', 'Ya eyyuhan nasu kad caekum burhanun min rabbikum ve enzelna ileykum nuran mubin.', 'Ey insanlar! Kesinlikle Rabb\'inizden size bir \"burhan\"[1] geldi. Ve size apaçık bir nur[2] indirdik.', 'يايها الناس قد جاكم برهن من ربكم وانزلنا اليكم نورا مبينا'),
(668, 4, 175, 'فَاَمَّا الَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَاعْتَصَمُوا بِه۪ فَسَيُدْخِلُهُمْ ف۪ي رَحْمَةٍ مِنْهُ وَفَضْلٍۙ وَيَهْد۪يهِمْ اِلَيْهِ صِرَاطاً مُسْتَق۪يماًۜ', 'Fe emmallezine amenu billahi va\'tesamu bihi fe se yudhıluhum fi rahmetin minhu ve faldın, ve yehdihim ileyhi sıratan mustekima .', 'Ama Allah\'a inanıp ona sımsıkı tutunanlara gelince,  onları,  yakında Kendi lütfundan,  rahmetinin içine koyacak ve onları kendisine varan dosdoğru yola iletecektir.', 'فاما الذين امنوا بالله واعتصموا به فسيدخلهم في رحمة منه وفضل ويهديهم اليه صرطا مستقيما');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(669, 4, 176, 'يَسْتَفْتُونَكَۜ قُلِ اللّٰهُ يُفْت۪يكُمْ فِي الْكَلَالَةِۜ اِنِ امْرُؤٌا هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُٓ اُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَۚ وَهُوَ يَرِثُـهَٓا اِنْ لَمْ يَكُنْ لَهَا وَلَدٌۜ فَاِنْ كَانَتَا اثْنَتَيْنِ فَلَهُمَا الثُّلُثَانِ مِمَّا تَرَكَۜ وَاِنْ كَانُٓوا اِخْوَةً رِجَالاً وَنِسَٓاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الْاُنْثَيَيْنِۜ يُبَيِّنُ اللّٰهُ لَكُمْ اَنْ تَضِلُّواۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Yesteftuneke. Kulillahu yuftikum fil kelaleh. İnimruun heleke leyse lehu veled, ve lehu uhtun fe leha nısfu ma terak, ve huve yerisuha in lem yekun leha veled. Fe in kanetesneteyni fe lehumas sulusani mimma terak. Ve in kanu ıhveten ricalen ve nisaen fe liz zekeri mislu hazzıl unseyeyn. Yubeyyinullahu lekum en tadıllu vallahu bi kulli şey\'in alim.', 'Sana soruyorlar. De ki: \"Allah kelale[1] hakkında size hükmünü veriyor: Ölen herhangi bir kimsenin çocuğu yoksa yalnızca bir kız kardeşi varsa,  mirasın yarısı onundur. Kız kardeşi ölür de çocuğu da yoksa erkek kardeşi onun malına varis olur. Kız kardeş,  iki taneyse mirasın üçte ikisi onlarındır. Eğer erkek ve kadın çok kardeşlerse,  o zaman erkeğe iki kadın payı vardır. Şaşırıp sapıtmamanız için,  Allah,  size açıklıyor. Ve Allah Her Şeyi En İyi Bilen\'dir.\"', 'يستفتونك قل الله يفتيكم في الكللة ان امروا هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد فان كانتا اثنتين فلهما الثلثان مما ترك وان كانوا اخوة رجالا ونسا فللذكر مثل حظ الانثيين يبين الله لكم ان تضلوا والله بكل شي عليم'),
(670, 5, 1, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَوْفُوا بِالْعُقُودِۜ  اُحِلَّتْ لَكُمْ بَه۪يمَةُ الْاَنْعَامِ اِلَّا مَا يُتْلٰى عَلَيْكُمْ غَيْرَ مُحِلِّي الصَّيْدِ وَاَنْتُمْ حُرُمٌۜ اِنَّ اللّٰهَ يَحْكُمُ مَا يُر۪يدُ', 'Ya eyyuhellezine amenu evfu bil ukud uhıllet lekum behimetul en\'ami illa ma yutla aleykum gayre muhillis saydi ve entum hurum innallahe yahkumu ma yurid.', 'Ey iman edenler! Sözlerinizi yerine getirin. İhramlı iken helal saymamanız[1] şartı ile okunacak olanların dışında kalan[2] en\'am[3] size helal kılındı Kuşkusuz,  Allah,  dilediği hükmü verir.[4]', 'يايها الذين امنوا اوفوا بالعقود احلت لكم بهيمة الانعم الا ما يتلي عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد'),
(671, 5, 2, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تُحِلُّوا شَعَٓائِرَ اللّٰهِ وَلَا الشَّهْرَ الْحَرَامَ وَلَا الْهَدْيَ وَلَا الْقَلَٓائِدَ وَلَٓا آٰمّ۪ينَ الْبَيْتَ الْحَرَامَ يَبْتَغُونَ فَضْلاً مِنْ رَبِّهِمْ وَرِضْوَاناًۜ وَاِذَا حَلَلْتُمْ فَاصْطَادُواۜ وَلَا يَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ اَنْ صَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ اَنْ تَعْتَدُواۢ وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوٰىۖ وَلَا تَعَاوَنُوا عَلَى الْاِثْمِ وَالْعُدْوَانِۖ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ', 'Ya eyyuhellezine amenu la tuhıllu şe\'airallahi veleş şehral harame ve lal hedye ve lal kalaide ve la amminel beytel harame yebtegune fadlan min rabbihim ve rıdvana ve iza haleltum fastadu ve la yecrimennekum şeneanu kavmin en saddukum anil mescidil harami en ta\'tedu, ve teavenu alel birri vet takva ve la teavenu alel ismi vel udvani vettekullah innallahe şedidul ıkab.', 'Ey iman edenler! Allah\'ın işaretlerine[1],  haram aya,  kurbana,  gerdanlıklara;[2] Rabb\'lerinin lütuf ve rızasını dileyerek Beyt-i Haram\'a gelenlere saygısızlık etmeyin. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi,  Mescid-i Haram\'dan alıkoymalarından dolayı bir halka olan kızgınlığınız,  aşırı gitmenize neden olmasın. Günah ve düşmanlık üzerinde değil,  iyilik ve takva üzerinde yardımlaşın. Allah\'a karşı takvalı olun. Kuşkusuz Allah\'ın azabı çok şiddetlidir.', 'يايها الذين امنوا لا تحلوا شعير الله ولا الشهر الحرام ولا الهدي ولا القليد ولا امين البيت الحرام يبتغون فضلا من ربهم ورضونا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا علي البر والتقوي ولا تعاونوا علي الاثم والعدون واتقوا الله ان الله شديد العقاب'),
(672, 5, 3, 'حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْز۪يرِ وَمَٓا اُهِلَّ لِغَيْرِ اللّٰهِ بِه۪ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّط۪يحَةُ وَمَٓا اَكَلَ السَّبُعُ اِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَاَنْ تَسْتَقْسِمُوا بِالْاَزْلَامِۜ ذٰلِكُمْ فِسْقٌۜ  اَلْيَوْمَ يَـئِسَ الَّذ۪ينَ كَفَرُوا مِنْ د۪ينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِۜ اَلْيَوْمَ اَكْمَلْتُ لَكُمْ د۪ينَكُمْ وَاَتْمَمْتُ عَلَيْكُمْ نِعْمَت۪ي وَرَض۪يتُ لَكُمُ الْاِسْلَامَ د۪يناًۜ فَمَنِ اضْطُرَّ ف۪ي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِاِثْمٍۙ فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Hurrimet aleykumul meytetu veddemu ve lahmul hınziri ve ma uhılle li gayrillahi bihi vel munhanikatu vel mevkuzetu vel mutereddiyetu ven natihatu ve ma ekeles sebuu illa ma zekkeytum ve ma zubiha alen nusubi ve en testaksimu bil ezlam, zalikum fisk, elyevme yeisellezine keferu min dinikum fe la tahşevhum vahşevn el yevme ekmeltu lekum dinekum ve etmemtu aleykum ni\'meti ve raditu lekumul islame dina fe menidturra fi mahmasatin gayra mutecanifin li ismin fe innallahe gafurun rahim.', 'Ölü,  kan,  domuz eti,  Allah\'tan başkasının adı anılarak[1] kesilen ve boğularak ölmüş,  vurularak ölmüş,  yüksekten düşerek ölmüş,  boynuzlanarak ölmüş; yırtıcı hayvan tarafından yenmiş -canı çıkmadan kesilmiş olanlar hariç- ve putlar adına kesilenler haram kılındı. Fal okları[2] ile kısmet aramanız size haram kılındı. Bunlar fısktır.[3] Artık,  Kafirler,  dininize bir şey yapmaktan umutlarını kesmişlerdir. Öyleyse,  onlara huşu[4] duymayın. Bana huşu duyun. Bugün,  sizin için dininizi kemale erdirdim/ikmal ettim ve sizin üzerinize nimetimi[5] tamamladım. Sizin için din olarak İslam\'ı seçtim/ beğendim. Kim açlıktan dolayı mecbur kalırsa,  istekli olmaksızın bunlardan yiyebilir. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'حرمت عليكم الميتة والدم ولحم الخنزير وما اهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما اكل السبع الا ما ذكيتم وما ذبح علي النصب وان تستقسموا بالازلم ذلكم فسق اليوم ييس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلم دينا فمن اضطر في مخمصة غير متجانف لاثم فان الله غفور رحيم'),
(673, 5, 4, 'يَسْـَٔلُونَكَ مَاذَٓا اُحِلَّ لَهُمْۜ قُلْ اُحِلَّ لَكُمُ الطَّيِّبَاتُۙ وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّب۪ينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللّٰهُۘ فَكُلُوا مِمَّٓا اَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللّٰهِ عَلَيْهِۖ وَاتَّقُوا اللّٰهَۜ  اِنَّ اللّٰهَ سَر۪يعُ الْحِسَابِ', 'Yes\'eluneke ma za uhılle lehum kul uhılle lekumut tayyibatu ve ma allemtum minel cevarihi mukellibine tuallimunehunne mimma allemekumullahu fe kulu mimma emsekne aleykum vezkurusmellahi aleyhi vettekullah innallahe seriul hısab.', 'Sana,  kendilerine neyin helal olduğunu soruyorlar. De ki: \"Temiz ve iyi olanlar,  size helal kılındı. Ve Allah\'ın size verdiği bilgi ile eğittiğiniz eğitimli av hayvanlarının yakaladıklarını yiyin. Ve Allah\'ın adını onun[1] üzerine anın. Allah\'a karşı takvalı[2] olun. Kuşkusuz,  Allah,  hesabı çok çabuk görendir.\"', 'يسلونك ماذا احل لهم قل احل لكم الطيبت وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب'),
(674, 5, 5, 'اَلْيَوْمَ اُحِلَّ لَكُمُ الطَّيِّبَاتُۜ وَطَعَامُ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ حِلٌّ لَكُمْۖ وَطَعَامُكُمْ حِلٌّ لَهُمْۘ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ مِنْ قَبْلِكُمْ اِذَٓا اٰتَيْتُمُوهُنَّ اُجُورَهُنَّ مُحْصِن۪ينَ غَيْرَ مُسَافِح۪ينَ وَلَا مُتَّخِذ۪ٓي اَخْدَانٍۜ وَمَنْ يَكْفُرْ بِالْا۪يمَانِ فَقَدْ حَبِطَ عَمَلُهُۘ وَهُوَ فِي الْاٰخِرَةِ مِنَ الْخَاسِر۪ينَ۟', 'El yevme uhılle lekumut tayyibat ve taamullezine utul kitabe hıllun lekum ve taamukum hıllun lehum vel muhsanatu minel mu\'minati vel muhsanatu min ellezine utul kitabe min kablikum iza ateytumuhunne ucurehunne muhsınine gayra musafihine ve la muttehızi ehdan ve men yekfur bil imani fe kad habita ameluhu ve huve fil ahıreti minel hasirin.', 'Bugün size,  temiz şeyler helal kılındı. Ve Kitap verilenlerin yiyecekleri size,  sizin yiyecekleriniz de onlara helaldir. İnanan muhsenat[1] kadınlar ve sizden önce kendilerine kitap verilenlerin muhsenat kadınları; karşılıklarını[2] vermeniz,  iffetli olmanız,  iffetsiz olmamanız ve gizli dost tutmamanız koşuluyla size helaldir. Kim imanı küfrederse[3] yaptığı işler boşa gider ve o,  ahirette hüsrana uğrayanlardan olur.', 'اليوم احل لكم الطيبت وطعام الذين اوتوا الكتب حل لكم وطعامكم حل لهم والمحصنت من المومنت والمحصنت من الذين اوتوا الكتب من قبلكم اذا اتيتموهن اجورهن محصنين غير مسفحين ولا متخذي اخدان ومن يكفر بالايمن فقد حبط عمله وهو في الاخرة من الخسرين'),
(675, 5, 6, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا قُمْتُمْ اِلَى الصَّلٰوةِ فَاغْسِلُوا وُجُوهَكُمْ وَاَيْدِيَكُمْ اِلَى الْمَرَافِقِ وَامْسَحُوا بِرُؤُ۫سِكُمْ وَاَرْجُلَكُمْ اِلَى الْكَعْبَيْنِۜ وَاِنْ كُنْتُمْ جُنُباً فَاطَّهَّرُواۜ وَاِنْ كُنْتُمْ مَرْضٰٓى اَوْ عَلٰى سَفَرٍ اَوْ جَٓاءَ اَحَدٌ مِنْكُمْ مِنَ الْغَٓائِطِ اَوْ لٰمَسْتُمُ النِّسَٓاءَ فَلَمْ تَجِدُوا مَٓاءً فَتَيَمَّمُوا صَع۪يداً طَيِّباً فَامْسَحُوا بِوُجُوهِكُمْ وَاَيْد۪يكُمْ مِنْهُۜ مَا يُر۪يدُ اللّٰهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلٰكِنْ يُر۪يدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'Ya eyyuhellezine amenu iza kumtum iles salati fagsilu vucuhekum ve eydiyekum ilel merafikı vemsehu bi ruusikum ve erculekum ilal ka\'beyn ve in kuntum cunuben fattahheru ve in kuntum marda ev ala seferin ev cae ehadun minkum minel gaitı ev lamestumun nisae fe lem tecidu maen fe teyemmemu saiden tayyiben femsehu bi vucuhikum ve eydikum minh ma yuridullahu li yec\'ale aleykum min haracin ve lakin yuridu li yutahhirekum ve li yutimme ni\'metehu aleykum leallekum teşkurun.', 'Ey iman edenler! Salata[1] durduğunuz zaman,  yüzlerinizi ve ellerinizi -dirseklerinizle beraber- yıkayın. Başlarınızı ve -aşık kemiklerinizle beraber- ayaklarınızı mesh edin.[2] Eğer cünüpseniz; tam olarak temizlenin.[3] Eğer hasta veya yolcukta iseniz veya tuvaletten[4] gelmişseniz veya kadınlarınızla ilişkiye girdiyseniz ve o anda su bulamadıysanız,  temiz kumla[5] teyemmüm edin; onunla ellerinizi ve yüzlerinizi mesh edin. Allah size herhangi bir zorluk dilemiyor. Ancak sizi tertemiz etmek ve üzerinize nimetini tamamlamak istiyor. Umulur ki şükredersiniz.', 'يايها الذين امنوا اذا قمتم الي الصلوة فاغسلوا وجوهكم وايديكم الي المرافق وامسحوا بروسكم وارجلكم الي الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضي او علي سفر او جا احد منكم من الغايط او لمستم النسا فلم تجدوا ما فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون'),
(676, 5, 7, 'وَاذْكُرُوا نِعْمَةَ اللّٰهِ عَلَيْكُمْ وَم۪يثَاقَهُ الَّذ۪ي وَاثَقَكُمْ بِه۪ٓۙ اِذْ قُلْتُمْ سَمِعْنَا وَاَطَعْنَاۘ وَاتَّقُوا اللّٰهَۜ  اِنَّ اللّٰهَ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Vezkuru ni\'metellahi aleykum ve misakahullezi vasekakum bihi iz kultum semi\'na ve ata\'na vettekullah innallahe alimun bizatis sudur.', 'Allah\'ın,  size olan nimetini ve \"İşittik ve itaat ettik.\" dediğinizde,  onunla sizi bağladığı sözünüzü hatırlayın. Allah\'a karşı takvalı[1] olun. Kuşkusuz,  Allah göğüslerde olanı gerçeğiyle bilendir.', 'واذكروا نعمة الله عليكم وميثقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور'),
(677, 5, 8, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُونُوا قَوَّام۪ينَ لِلّٰهِ شُهَدَٓاءَ بِالْقِسْطِۘ وَلَا يَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ عَلٰٓى اَلَّا تَعْدِلُواۜ اِعْدِلُوا۠ هُوَ اَقْرَبُ لِلتَّقْوٰىۘ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ خَب۪يرٌ بِمَا تَعْمَلُونَ', 'Ya eyyuhellezine amenu kunu kavvamine lillahi şuhedae bil kıstı ve la yecrimennekum şeneanu kavmin ala ella ta\'dilu. I\'dilu, huve akrabu lit takva vettekullah innallahe habirun bima ta\'melun.', 'Ey iman edenler! Allah için gerçeğe bağlı kalmada kararlı olun! Hakkaniyetli tanıklar olun! Bir halka olan düşmanlığınız sizi adaletsizliğe yöneltmesin. Adil olun,  bu,  takvalı olmaya en uygun olandır. Allah\'a karşı takvalı olun. Allah,  yaptığınız her şeyden haberdardır.', 'يايها الذين امنوا كونوا قومين لله شهدا بالقسط ولا يجرمنكم شنان قوم علي الا تعدلوا اعدلوا هو اقرب للتقوي واتقوا الله ان الله خبير بما تعملون'),
(678, 5, 9, 'وَعَدَ اللّٰهُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِۙ لَهُمْ مَغْفِرَةٌ وَاَجْرٌ عَظ۪يمٌ', 'Veadellahullezine amenu ve amilus salihati lehum magfiretun ve ecrun azim.', 'Allah,  iman edip salihatı[1] yapanlara söz verdi,  onlar için bağışlanma ve büyük bir karşılık vardır.', 'وعد الله الذين امنوا وعملوا الصلحت لهم مغفرة واجر عظيم'),
(679, 5, 10, 'وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَٓا اُو۬لٰٓئِكَ اَصْحَابُ الْجَح۪يمِ', 'Vellezine keferu ve kezzebu bi ayatina ulaike ashabul cehim.', 'Küfreden ve ayetlerimizi yalanlayan kimselere gelince,  işte onlar Cehennemlik kimselerdir.', 'والذين كفروا وكذبوا بايتنا اوليك اصحب الجحيم'),
(680, 5, 11, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اذْكُرُوا نِعْمَتَ اللّٰهِ عَلَيْكُمْ اِذْ هَمَّ قَوْمٌ اَنْ يَبْسُطُٓوا اِلَيْكُمْ اَيْدِيَهُمْ فَكَفَّ اَيْدِيَهُمْ عَنْكُمْۚ وَاتَّقُوا اللّٰهَۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ۟', 'Ya eyyuhellezine amenuzkuru ni\'metallahi aleykum iz hemme kavmun en yebsutu ileykum eydiyehum fe keffe eydiyehum ankum, vettekullah ve alallahi fel yetevekkelil mu\'minun.', 'Ey iman edenler! Allah\'ın üzerinizdeki nimetini hatırlayın. Hani bir topluluk size saldırmayı tasarlamıştı da Allah,  onları,  size saldırmaktan vazgeçirmişti. Allah\'a karşı takvalı olun. Mü\'minler,  yalnızca Allah\'a güvenip yönelsinler.', 'يايها الذين امنوا اذكروا نعمت الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلي الله فليتوكل المومنون'),
(681, 5, 12, 'وَلَقَدْ اَخَذَ اللّٰهُ م۪يثَاقَ بَن۪ٓي اِسْرَٓائ۪لَۚ وَبَعَثْنَا مِنْهُمُ اثْنَيْ عَشَرَ نَق۪يباًۜ وَقَالَ اللّٰهُ اِنّ۪ي مَعَكُمْۜ لَئِنْ اَقَمْتُمُ الصَّلٰوةَ وَاٰتَيْتُمُ الزَّكٰوةَ وَاٰمَنْتُمْ بِرُسُل۪ي وَعَزَّرْتُمُوهُمْ وَاَقْرَضْتُمُ اللّٰهَ قَرْضاً حَسَناً لَاُكَفِّرَنَّ عَنْكُمْ سَيِّـَٔاتِكُمْ وَلَاُدْخِلَنَّكُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۚ فَمَنْ كَفَرَ بَعْدَ ذٰلِكَ مِنْكُمْ فَقَدْ ضَلَّ سَوَٓاءَ السَّب۪يلِ', 'Ve lekad ehazallahu misaka beni israil, ve beasna minhumusney aşera nakiba ve kalellahu inni meakum lein ekamtumus salate ve ateytumuz zekate ve amentum bi rusuli ve azzertumuhum ve akradtumullahe kardan hasenen le ukeffirenne ankum seyyiatikum ve le udhılennekum cennatin tecri min tahtıhel enhar, fe men kefere ba\'de zalike minkum fe kad dalle sevaes sebil.', 'Doğrusu Allah İsrailoğulları\'ndan kesin söz aldı. Onlardan on iki temsilci gönderdik. Ve Allah,  \"Sizinle beraberim.\" dedi. Ant olsun eğer salatı ikame eder,  zekatı yapar[1],  resullerime iman eder ve onlara yardımcı olur,  böylece Allah\'a iyi bir ödünç verirseniz,  o zaman elbette kötülüklerinizi örterim,  muhakkak içinden ırmaklar akan Cennetlere koyarım. Bundan sonra,  sizden kim küfrederse[2] düz yoldan sapmış olur.', 'ولقد اخذ الله ميثق بني اسريل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لين اقمتم الصلوة واتيتم الزكوة وامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سياتكم ولادخلنكم جنت تجري من تحتها الانهر فمن كفر بعد ذلك منكم فقد ضل سوا السبيل'),
(682, 5, 13, 'فَبِمَا نَقْضِهِمْ م۪يثَاقَهُمْ لَعَنَّاهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَاسِيَةًۚ يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِه۪ۙ وَنَسُوا حَظاًّ مِمَّا ذُكِّرُوا بِه۪ۚ وَلَا تَزَالُ تَطَّلِعُ عَلٰى خَٓائِنَةٍ مِنْهُمْ اِلَّا قَل۪يلاً مِنْهُمْ فَاعْفُ عَنْهُمْ وَاصْفَحْۜ اِنَّ اللّٰهَ يُحِبُّ الْمُحْسِن۪ينَ', 'Fe bima nakdihim misakahum leannahum ve cealna kulubehum kasiyet, yuharrifunel kelime an mevadııhi ve nesu hazzan mimma zukkiru bih, ve la tezalu tettaliu ala haınetin minhum illa kalilen minhum fa\'fu anhum vasfah innallahe yuhıbbul muhsinin.', 'Anlaşmalarını bozmalarından dolayı onlara lanet[1] ettik ve kalplerini katılaştırdık. Kelimeleri bağlamlarından kopararak çarpıtıyorlar,  öğütlendikleri şeyden nasiplenmeyi unuturlar,  içlerinden çok azı hariç,  daima onların hainlik ettiklerini görürsün. Yine de vazgeç ve yaptıklarına aldırma. Kuşkusuz Allah,  iyi davrananları sever.', 'فبما نقضهم ميثقهم لعنهم وجعلنا قلوبهم قسية يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع علي خاينة منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين'),
(683, 5, 14, 'وَمِنَ الَّذ۪ينَ قَالُٓوا اِنَّا نَصَارٰٓى اَخَذْنَا م۪يثَاقَهُمْ فَنَسُوا حَظاًّ مِمَّا ذُكِّرُوا بِه۪ۖ فَاَغْرَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَٓاءَ اِلٰى يَوْمِ الْقِيٰمَةِۜ وَسَوْفَ يُنَبِّئُهُمُ اللّٰهُ بِمَا كَانُوا يَصْنَعُونَ', 'Ve minellezine kalu inna nasara ehazna misakahum fe nesu hazzan mimma zukkiru bihi fe agrayna beynehumul adavete vel bagdae ila yevmil kıyameh ve sevfe yunebbiuhumullahu bima kanu yasnaun.', 'Ve \"Biz Nasarayız.[1]\" diyenlerden de söz aldık. Öğütlendikleri şeyden nasiplenmeyi unuttular. Biz de kıyamet gününe kadar aralarına düşmanlık ve kin yerleştirdik. Ve Allah,  ne iş yaptıklarını yakında haber verecektir.', 'ومن الذين قالوا انا نصري اخذنا ميثقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوة والبغضا الي يوم القيمة وسوف ينبيهم الله بما كانوا يصنعون'),
(684, 5, 15, 'يَٓا اَهْلَ الْكِتَابِ قَدْ جَٓاءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَث۪يراً مِمَّا كُنْتُمْ تُخْفُونَ مِنَ الْكِتَابِ وَيَعْفُوا عَنْ كَث۪يرٍۜ قَدْ جَٓاءَكُمْ مِنَ اللّٰهِ نُورٌ وَكِتَابٌ مُب۪ينٌۙ', 'Ya ehlel kitabi kad caekum resuluna yubeyyinu lekum kesiran mimma kuntum tuhfune minel kitabi ve ya\'fu an kesir kad caekum minallahi nurun ve kitabun mubin.', 'Ey kitap Ehli! Doğrusu,  Kitap\'tan gizlediğiniz birçok şeyi size açıklayan ve bir kısmından da söz etmeyen resulümüz geldi. Doğrusu size Allah\'tan bir nur ve apaçık bir kitap geldi.', 'ياهل الكتب قد جاكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتب ويعفوا عن كثير قد جاكم من الله نور وكتب مبين'),
(685, 5, 16, 'يَهْد۪ي بِهِ اللّٰهُ مَنِ اتَّبَعَ رِضْوَانَهُ سُبُلَ السَّلَامِ وَيُخْرِجُهُمْ مِنَ الظُّلُمَاتِ اِلَى النُّورِ بِاِذْنِه۪ وَيَهْد۪يهِمْ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Yehdi bihillahu menittebea rıdvanehu subules selami ve yuhricuhum minez zulumati ilen nuri bi iznihi ve yehdihim ila sıratın mustakim.', 'Allah,  onunla[1],  rızasına bilerek tabi olanları esenlik yollarına iletir. Onları,  izniyle[2] karanlıklardan aydınlığa çıkartır. Ve onları dosdoğru olan yola iletir.', 'يهدي به الله من اتبع رضونه سبل السلم ويخرجهم من الظلمت الي النور باذنه ويهديهم الي صرط مستقيم'),
(686, 5, 17, 'لَقَدْ كَفَرَ الَّذ۪ينَ قَالُٓوا اِنَّ اللّٰهَ هُوَ الْمَس۪يحُ ابْنُ مَرْيَمَۜ قُلْ فَمَنْ يَمْلِكُ مِنَ اللّٰهِ شَيْـٔاً اِنْ اَرَادَ اَنْ يُهْلِكَ الْمَس۪يحَ ابْنَ مَرْيَمَ وَاُمَّهُ وَمَنْ فِي الْاَرْضِ جَم۪يعاًۜ وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۜ يَخْلُقُ مَا يَشَٓاءُۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Lekad keferellezine kalu innallahe huvel mesihubnu meryem kul fe men yemliku minallahi şey\'en in erade en yuhlikel mesihabne meryeme ve ummehu ve men fil ardı cemia ve lillahi mulkus semavati vel ardı ve ma beynehuma. Yahluku ma yeşa vallahu ala kulli şey\'in kadir.', 'Ant olsun ki,  Meryem oğlu Mesih için,  \"O Allah\'tır.\" diyenler kuşkusuz Kafir oldu. De ki: \"Allah,  Meryem oğlu Mesih\'i,  annesini ve yeryüzündekilerin tamamını yok etmek isterse,  O\'na kim engel olabilir?\" Göklerin,  yeryüzünün ve ikisinin arasındakilerin tamamı,  Allah\'a aittir. Dilediğini yaratır. Ve Allah,  Her Şeye Gücü Yeten\'dir.', 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السموت والارض وما بينهما يخلق ما يشا والله علي كل شي قدير'),
(687, 5, 18, 'وَقَالَتِ الْيَهُودُ وَالنَّصَارٰى نَحْنُ اَبْنَٓاءُ اللّٰهِ وَاَحِبَّٓاؤُ۬هُۜ قُلْ فَلِمَ يُعَذِّبُكُمْ بِذُنُوبِكُمْۜ بَلْ اَنْتُمْ بَشَرٌ مِمَّنْ خَلَقَۜ يَغْفِرُ لِمَنْ يَشَٓاءُ وَيُعَذِّبُ مَنْ يَشَٓاءُۜ وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۘ وَاِلَيْهِ الْمَص۪يرُ', 'Ve kaletil yahudu ven nasara nahnu ebnaullahi ve ehıbbauh kul fe lime yuazzibukum bi zunubikul bel entum beşerun mimmen halak yagfiru limen yeşau ve yuazzibu men yeşa ve lillahi mulkus semavati vel ardı ve ma beynehuma ve ileyhil masir.', 'Yahudiler ve Hristiyanlar,  \"Bizler Allah\'ın oğulları ve O\'nun sevgilileriyiz.\" dediler. De ki: \"O halde suçlarınızdan dolayı,  size niçin azap ediyor? Doğrusu,  siz de yarattıklarından bir beşersiniz.[1] Dilediğini bağışlar,  dilediğine[2] azap eder. Göklerin,  yerin ve ikisi arasındakilerin mülkü Allah\'a aittir. Son varış O\'nadır.', 'وقالت اليهود والنصري نحن ابنوا الله واحبوه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشا ويعذب من يشا ولله ملك السموت والارض وما بينهما واليه المصير'),
(688, 5, 19, 'يَٓا اَهْلَ الْكِتَابِ قَدْ جَٓاءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلٰى فَتْرَةٍ مِنَ الرُّسُلِ اَنْ تَقُولُوا مَا جَٓاءَنَا مِنْ بَش۪يرٍ وَلَا نَذ۪يرٍۘ فَقَدْ جَٓاءَكُمْ بَش۪يرٌ وَنَذ۪يرٌۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ۟', 'Ya ehlel kitabi kad caekum resuluna yubeyyinu lekum ala fetretin min er rusuli en tekulu ma caena min beşirin ve la nezirin fe kad caekum beşirun ve nezir vallahu ala kulli şey\'in kadir.', 'Ey Kitap Ehli! Resullerin arasının kesildiği bir dönemde size gerçekleri açıklayan resulümüz geldi. \"Bize herhangi bir müjdeleyici ve uyarıcı gelmedi.\" demeyesiniz diye,  müjdeleyici ve uyarıcı olarak. Allah,  Her Şeye Gücü Yeten\'dir.', 'ياهل الكتب قد جاكم رسولنا يبين لكم علي فترة من الرسل ان تقولوا ما جانا من بشير ولا نذير فقد جاكم بشير ونذير والله علي كل شي قدير'),
(689, 5, 20, 'وَاِذْ قَالَ مُوسٰى لِقَوْمِه۪ يَا قَوْمِ اذْكُرُوا نِعْمَةَ اللّٰهِ عَلَيْكُمْ اِذْ جَعَلَ ف۪يكُمْ اَنْبِيَٓاءَ وَجَعَلَكُمْ مُلُوكاًۗ وَاٰتٰيكُمْ مَا لَمْ يُؤْتِ اَحَداً مِنَ الْعَالَم۪ينَ', 'Ve iz kale musa li kavmihi ya kavmizkuru ni\'metallahi aleykum iz ceale fikum enbiyae ve cealekum muluk, ve atakum ma lem yu\'ti ehaden minel alemin.', 'Hani Musa,  halkına: \"Ey halkım! Allah\'ın size verdiği nimetleri hatırlayın. Hani O,  içinizden nebiler seçti; sizi melikler[1] yaptı ve alemlerden hiç kimseye vermediği birçok şeyi size verdi.\" dedi.', 'واذ قال موسي لقومه يقوم اذكروا نعمة الله عليكم اذ جعل فيكم انبيا وجعلكم ملوكا واتيكم ما لم يوت احدا من العلمين'),
(690, 5, 21, 'يَا قَوْمِ ادْخُلُوا الْاَرْضَ الْمُقَدَّسَةَ الَّت۪ي كَتَبَ اللّٰهُ لَكُمْ وَلَا تَرْتَدُّوا عَلٰٓى اَدْبَارِكُمْ فَتَنْقَلِبُوا خَاسِر۪ينَ', 'Ya kavmidhulul ardal mukaddesetelleti keteballahu lekum ve la terteddu ala edbarikum fe tenkalibu hasirin.', 'Ey kavmim! Allah\'ın,  sizin için yazdığı,  kutsal topraklara girin. Gerisin geri dönmeyin. Yoksa ters yüz olarak hüsrana uğrarsınız.', 'يقوم ادخلوا الارض المقدسة التي كتب الله لكم ولا ترتدوا علي ادباركم فتنقلبوا خسرين'),
(691, 5, 22, 'قَالُوا يَا مُوسٰٓى اِنَّ ف۪يهَا قَوْماً جَبَّار۪ينَۗ وَاِنَّا لَنْ نَدْخُلَهَا حَتّٰى يَخْرُجُوا مِنْهَاۚ فَاِنْ يَخْرُجُوا مِنْهَا فَاِنَّا دَاخِلُونَ', 'Kalu ya musa inne fiha kavmen cebbarin, ve inna len nedhuleha hatta yahrucu minha, fe in yahrucu minha fe inna dahılun.', '\"Ey Musa! Kuşkusuz,  orada çok zorlu bir halk var. Onlar,  oradan çıkmadıkça,  biz oraya asla girmeyiz. Eğer çıkarlarsa,  o zaman gireriz.\" dediler.', 'قالوا يموسي ان فيها قوما جبارين وانا لن ندخلها حتي يخرجوا منها فان يخرجوا منها فانا دخلون'),
(692, 5, 23, 'قَالَ رَجُلَانِ مِنَ الَّذ۪ينَ يَخَافُونَ اَنْعَمَ اللّٰهُ عَلَيْهِمَا ادْخُلُوا عَلَيْهِمُ الْبَابَۚ فَاِذَا دَخَلْتُمُوهُ فَاِنَّكُمْ غَالِبُونَ وَعَلَى اللّٰهِ فَتَوَكَّلُٓوا اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Kale raculani minellezine yehafune en\'amallahu aleyhim edhulu aleyhimul bab, fe iza dehaltumuhu fe innekum galibune ve alallahi fe tevekkelu in kuntum mu\'minin.', 'Korkanların içinden,  Allah\'ın kendilerine nimet verdiği iki kişi,  şöyle dedi: \"Onların üzerine bildik kapıdan girin. Eğer oraya girerseniz,  o zaman galip gelirsiniz. Eğer iman edenlerseniz,  Allah\'a tevekkül[1] edin.\"', 'قال رجلان من الذين يخافون انعم الله عليهما ادخلوا عليهم الباب فاذا دخلتموه فانكم غلبون وعلي الله فتوكلوا ان كنتم مومنين'),
(693, 5, 24, 'قَالُوا يَا مُوسٰٓى اِنَّا لَنْ نَدْخُلَـهَٓا اَبَداً مَا دَامُوا ف۪يهَا فَاذْهَبْ اَنْتَ وَرَبُّكَ فَقَاتِلَٓا اِنَّا هٰهُنَا قَاعِدُونَ', 'Kalu ya musa inna len nedhuleha ebeden ma damu fiha fezheb ente ve rabbuke fe katila inna hahuna kaıdun.', 'Ey Musa! \"Onlar,  orada oldukları sürece biz oraya asla girmeyiz; haydi sen git,  sen ve Rabb\'in birlikte savaşın. Kuşkusuz,  işte biz buradan öteye gitmeyiz.\" dediler.', 'قالوا يموسي انا لن ندخلها ابدا ما داموا فيها فاذهب انت وربك فقتلا انا ههنا قعدون'),
(694, 5, 25, 'قَالَ رَبِّ اِنّ۪ي لَٓا اَمْلِكُ اِلَّا نَفْس۪ي وَاَخ۪ي فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِق۪ينَ', 'Kale rabbi inni la emliku illa nefsi ve ahi fefruk beynena ve beynel kavmil fasikin.', 'Dedi: \"Ey Rabb\'im! Kendimden ve kardeşimden başkasına söz geçiremiyorum. O halde bizimle fasık[1] halkın arasını ayır.\"', 'قال رب اني لا املك الا نفسي واخي فافرق بيننا وبين القوم الفسقين'),
(695, 5, 26, 'قَالَ فَاِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ اَرْبَع۪ينَ سَنَةًۚ يَت۪يهُونَ فِي الْاَرْضِ فَلَا تَأْسَ عَلَى الْقَوْمِ الْفَاسِق۪ينَ۟', 'Kale fe inneha muharremetun aleyhim erbaine senet, yetihune fil ardı fe la te\'se alel kavmil fasikin.', '\"Onlar,  oradan kırk yıl[1] yoksun kalacaklar.\" dedi. Onlar,  o yerde şaşkınlık içinde dolaşacaklar. Artık fasık olan halkın durumuna üzülme.', 'قال فانها محرمة عليهم اربعين سنة يتيهون في الارض فلا تاس علي القوم الفسقين'),
(696, 5, 27, 'وَاتْلُ عَلَيْهِمْ نَبَاَ ابْنَيْ اٰدَمَ بِالْحَقِّۢ اِذْ قَرَّبَا قُرْبَاناً فَتُقُبِّلَ مِنْ اَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ الْاٰخَرِۜ قَالَ لَاَقْتُلَنَّكَۜ قَالَ اِنَّمَا يَتَقَبَّلُ اللّٰهُ مِنَ الْمُتَّق۪ينَ', 'Vetlu aleyhim nebeebney ademe bil hakkı iz karreba kurbanen fe tukubbile min ehadihima ve lem yutekabbel minel ahar kale le aktulennek kale innema yetekabbelullahu minel muttekin.', 'Onlara,  iki adem oğlunun[1] gerçek öyküsünü anlat: İkisi de birer sunu[2] sundular. Birisininki kabul olundu,  diğerininki ise kabul olunmadı. Dedi ki: \"Yemin olsun seni öldüreceğim.\" Dedi ki: \"Allah,  yalnız takva sahiplerinden[3] kabul eder.\"', 'واتل عليهم نبا ابني ادم بالحق اذ قربا قربانا فتقبل من احدهما ولم يتقبل من الاخر قال لاقتلنك قال انما يتقبل الله من المتقين'),
(697, 5, 28, 'لَئِنْ بَسَطْتَ اِلَيَّ يَدَكَ لِتَقْتُلَن۪ي مَٓا اَنَا۬ بِبَاسِطٍ يَدِيَ اِلَيْكَ لِاَقْتُلَكَۚ اِنّ۪ٓي اَخَافُ اللّٰهَ رَبَّ الْعَالَم۪ينَ', 'Lein besadte ileyye yedeke li taktuleni ma ene bi basitın yediye ileyke li aktulek, inni ehafullahe rabbel alemin.', '\"Yemin olsun ki! Beni öldürmek istesen de ben sana elimi kaldırmayacağım. Ben alemlerin Rabb\'i olan Allah\'a karşı gelmekten korkarım.\"', 'لين بسطت الي يدك لتقتلني ما انا بباسط يدي اليك لاقتلك اني اخاف الله رب العلمين'),
(698, 5, 29, 'اِنّ۪ٓي اُر۪يدُ اَنْ تَبُٓوأَ بِاِثْم۪ي وَاِثْمِكَ فَتَكُونَ مِنْ اَصْحَابِ النَّارِۚ وَذٰلِكَ جَزٰٓؤُا الظَّالِم۪ينَۚ', 'İnni uridu en tebue bi ismi ve ismike fe tekune min ashabin nar, ve zalike cezauz zalimin.', '\"Dilerim ki,  benim günahımla[1] birlikte kendi günahını da yüklenerek Ateş\'e gidenlerden olursun. Çünkü zalimlerin cezası budur.\"', 'اني اريد ان تبوا باثمي واثمك فتكون من اصحب النار وذلك جزوا الظلمين'),
(699, 5, 30, 'فَطَوَّعَتْ لَهُ نَفْسُهُ قَتْلَ اَخ۪يهِ فَقَتَلَهُ فَاَصْبَحَ مِنَ الْخَاسِر۪ينَ', 'Fe tavveat lehu nefsuhu katle ahihi fe katelehu fe asbaha minel hasirin.', 'Nefsi[1] kardeşini isteyerek öldürmesini kolaylaştırdı. O da onu öldürdü. Böylece hüsrana uğrayanlardan oldu.', 'فطوعت له نفسه قتل اخيه فقتله فاصبح من الخسرين'),
(700, 5, 31, 'فَبَعَثَ اللّٰهُ غُرَاباً يَبْحَثُ فِي الْاَرْضِ لِيُرِيَهُ كَيْفَ يُوَار۪ي سَوْاَةَ اَخ۪يهِۜ قَالَ يَا وَيْلَتٰٓى اَعَجَزْتُ اَنْ اَكُونَ مِثْلَ هٰذَا الْغُرَابِ فَاُوَارِيَ سَوْاَةَ اَخ۪يۚ فَاَصْبَحَ مِنَ النَّادِم۪ينَۚۛ', 'Fe beasallahu guraben yebhasu fil ardı li yuriyehu keyfe yuvari sev\'ete ahih kale ya veyleta e aceztu en ekune misle hazel gurabi fe uvariye sev\'ete ahi, fe asbaha minen nadimin.', 'Allah,  bir karga gönderdi. Kardeşinin cesedini nasıl örteceğini ona göstermek için yeri eşeliyordu.[1] \"Eyvah! Bana yazıklar olsun,  kardeşimin cesedini örtmekte karga kadar bile olamayacak kadar aciz miyim!\" dedi. Pişman olanlardan oldu.', 'فبعث الله غرابا يبحث في الارض ليريه كيف يوري سوة اخيه قال يويلتي اعجزت ان اكون مثل هذا الغراب فاوري سوة اخي فاصبح من الندمين'),
(701, 5, 32, 'مِنْ اَجْلِ ذٰلِكَۚۛ  كَتَبْنَا عَلٰى بَن۪ٓي اِسْرَٓائ۪لَ اَنَّهُ مَنْ قَتَلَ نَفْساً بِغَيْرِ نَفْسٍ اَوْ فَسَادٍ فِي الْاَرْضِ فَكَاَنَّمَا قَتَلَ النَّاسَ جَم۪يـعاًۜ وَمَنْ اَحْيَاهَا فَكَاَنَّمَٓا اَحْيَا النَّاسَ جَم۪يعاًۜ وَلَقَدْ جَٓاءَتْهُمْ رُسُلُنَا بِالْبَيِّنَاتِۘ ثُمَّ اِنَّ كَث۪يراً مِنْهُمْ بَعْدَ ذٰلِكَ فِي الْاَرْضِ لَمُسْرِفُونَ', 'Min ecli zalik, ketebna ala beni israile ennehu men katele nefsen bi gayri nefsin ev fesadin fil ardı fe ke ennema katelen nase cemia ve men ahyaha fe ke ennema ahyen nase cemia ve lekad caethum rusuluna bil beyyinati summe inne kesiran minhum ba\'de zalike fil ardı le musrifun.', 'Bundan dolayı[1] İsrailoğulları\'na yazdık: \"Kim,  bir cana karşılık olmaksızın veya yeryüzünde bozgunculuk yapmamış birini öldürürse,  sanki bütün insanları öldürmüş gibidir. Kim de onu yaşatırsa,  sanki bütün insanları yaşatmış gibi olur.\" Resullerimiz onlara kanıtlayıcı açık bilgilerle geldiği halde onların çoğu bundan sonra da yeryüzünde israf[2] etmektedirler.', 'من اجل ذلك كتبنا علي بني اسريل انه من قتل نفسا بغير نفس او فساد في الارض فكانما قتل الناس جميعا ومن احياها فكانما احيا الناس جميعا ولقد جاتهم رسلنا بالبينت ثم ان كثيرا منهم بعد ذلك في الارض لمسرفون'),
(702, 5, 33, 'اِنَّمَا جَزٰٓؤُا الَّذ۪ينَ يُحَارِبُونَ اللّٰهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْاَرْضِ فَسَاداً اَنْ يُقَتَّلُٓوا اَوْ يُصَلَّـبُٓوا اَوْ تُقَطَّعَ اَيْد۪يهِمْ وَاَرْجُلُهُمْ مِنْ خِلَافٍ اَوْ يُنْفَوْا مِنَ الْاَرْضِۜ ذٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْاٰخِرَةِ عَذَابٌ عَظ۪يمٌۙ', 'İnnema cezaullezine yuharibunallahe ve resulehu ve yes\'avne fil ardı fesaden en yukattelu ev yusallebu ev tukattaa eydihim ve erculuhum min hılafin ev yunfev minel ard, zalike lehum hızyun fid dunya ve lehum fil ahırati azabun azim.', 'Allah ve Resul\'üyle savaşanların ve yeryüzünde bozgunculuk[1] yapmaya çalışanların cezası öldürülmeleri veya asılmaları veya ellerinin ve ayaklarının çapraz kesilmesi veya yerlerinden sürgün edilmeleridir.[2] İşte bu durum,  onlar için dünyada bir rezilliktir. Ahirette ise onlar için büyük bir azap vardır.', 'انما جزوا الذين يحاربون الله ورسوله ويسعون في الارض فسادا ان يقتلوا او يصلبوا او تقطع ايديهم وارجلهم من خلف او ينفوا من الارض ذلك لهم خزي في الدنيا ولهم في الاخرة عذاب عظيم'),
(703, 5, 34, 'اِلَّا الَّذ۪ينَ تَابُوا مِنْ قَبْلِ اَنْ تَقْدِرُوا عَلَيْهِمْۚ فَاعْلَمُٓوا اَنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ۟', 'İllellezine tabu min kabli en takdiru aleyhim, fa\'lemu ennallahe gafurun rahim.', 'Ancak onlar üzerinde bir karara[1] varmanızdan önce tevbe[2] edenler hariç. İyi bilin ki Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'الا الذين تابوا من قبل ان تقدروا عليهم فاعلموا ان الله غفور رحيم'),
(704, 5, 35, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُٓوا اِلَيْهِ الْوَس۪يلَةَ وَجَاهِدُوا ف۪ي سَب۪يلِه۪ لَعَلَّكُمْ تُفْلِحُونَ', 'Ya eyyuhellezine amenuttekullahe vebtegu ileyhil vesilete ve cahidu fi sebilihi leallekum tuflihun.', 'Ey iman edenler! Allah\'a karşı takva sahibi olun ve O\'na yakınlaşmak için vesile[1] arayın. O\'nun yolunda gayret gösterin ki Kurtuluşa eresiniz.', 'يايها الذين امنوا اتقوا الله وابتغوا اليه الوسيلة وجهدوا في سبيله لعلكم تفلحون'),
(705, 5, 36, 'اِنَّ الَّذ۪ينَ كَفَرُوا لَوْ اَنَّ لَهُمْ مَا فِي الْاَرْضِ جَم۪يعاً وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِه۪ مِنْ عَذَابِ يَوْمِ الْقِيٰمَةِ مَا تُقُبِّلَ مِنْهُمْۚ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnellezine keferu lev enne lehum ma fil ardı cemian ve mislehu meahu li yeftedu bihi min azabi yevmil kıyameti ma tukubbile minhum, ve lehum azabun elim.', 'Yeryüzünde olanların tamamı ve bir o kadarı daha,  Kafirlerin olsa ve Kıyamet Günü\'nün azabından kurtulmak için bunları karşılık olarak verseler,  bu onlardan asla kabul edilmeyecektir. Onlar için elem verici bir azap vardır.', 'ان الذين كفروا لو ان لهم ما في الارض جميعا ومثله معه ليفتدوا به من عذاب يوم القيمة ما تقبل منهم ولهم عذاب اليم'),
(706, 5, 37, 'يُر۪يدُونَ اَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِج۪ينَ مِنْهَاۘ وَلَهُمْ عَذَابٌ مُق۪يمٌ', 'Yuridune en yahrucu minen nari ve ma hum bi haricine minha, ve lehum azabun mukim.', 'Ateşten çıkmak isterler. Onlar,  o ateşten asla çıkamayacaklar. Onlar için kalıcı bir azap vardır.', 'يريدون ان يخرجوا من النار وما هم بخرجين منها ولهم عذاب مقيم'),
(707, 5, 38, 'وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُٓوا اَيْدِيَهُمَا جَزَٓاءً بِمَا كَسَبَا نَكَالاً مِنَ اللّٰهِۜ وَاللّٰهُ عَز۪يزٌ حَك۪يمٌ', 'Ves sariku ves sarikatu faktau eydiyehuma cezaen bima keseba nekalen minallah vallahu azizun hakim.', 'Hırsızlık yapan erkeğin ve kadının,  her ikisinin de ellerini,  Allah\'tan caydırıcı bir karşılık olarak kesin.[1] Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'والسارق والسارقة فاقطعوا ايديهما جزا بما كسبا نكلا من الله والله عزيز حكيم'),
(708, 5, 39, 'فَمَنْ تَابَ مِنْ بَعْدِ ظُلْمِه۪ وَاَصْلَحَ فَاِنَّ اللّٰهَ يَتُوبُ عَلَيْهِۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Fe men tabe min ba\'di zulmihi ve aslaha fe innallahe yetubu aleyh innallahe gafurun rahim.', 'Kim yaptığı haksızlıktan[1] sonra tevbe eder ve uslanırsa,  kuşkusuz Allah onun tevbesini kabul eder. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'فمن تاب من بعد ظلمه واصلح فان الله يتوب عليه ان الله غفور رحيم'),
(709, 5, 40, 'اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ يُعَذِّبُ مَنْ يَشَٓاءُ وَيَغْفِرُ لِمَنْ يَشَٓاءُۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'E lem ta\'lem ennallahe lehu mulkus semavati vel ardı yuazzibu men yeşau ve yagfiru limen yeşa vallahu ala kulli şey\'in kadir.', 'Bilmez misin? Kuşkusuz ki göklerin ve yerin mülkü Allah\'a aittir. Hak edene azap eder,  Hak edeni bağışlar. Allah Her Şeye Güç Yetiren\'dir.', 'الم تعلم ان الله له ملك السموت والارض يعذب من يشا ويغفر لمن يشا والله علي كل شي قدير'),
(710, 5, 41, 'يَٓا اَيُّهَا الرَّسُولُ لَا يَحْزُنْكَ الَّذ۪ينَ يُسَارِعُونَ فِي الْكُفْرِ مِنَ الَّذ۪ينَ قَالُٓوا اٰمَنَّا بِاَفْوَاهِهِمْ وَلَمْ تُؤْمِنْ قُلُوبُهُمْۚ وَمِنَ الَّذ۪ينَ هَادُوا سَمَّاعُونَ لِلْكَذِبِ سَمَّاعُونَ لِقَوْمٍ اٰخَر۪ينَۙ لَمْ يَأْتُوكَۜ يُحَرِّفُونَ الْكَلِمَ مِنْ بَعْدِ مَوَاضِعِه۪ۚ يَقُولُونَ اِنْ اُو۫ت۪يتُمْ هٰذَا فَخُذُوهُ وَاِنْ لَمْ تُؤْتَوْهُ فَاحْذَرُواۜ وَمَنْ يُرِدِ اللّٰهُ فِتْنَتَهُ فَلَنْ تَمْلِكَ لَهُ مِنَ اللّٰهِ شَيْـٔاًۜ اُو۬لٰٓئِكَ الَّذ۪ينَ لَمْ يُرِدِ اللّٰهُ اَنْ يُطَهِّرَ قُلُوبَهُمْۜ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْاٰخِرَةِ عَذَابٌ عَظ۪يمٌ', 'Ya eyyuher resulu la yahzunkellezine yusariune fil kufri minellezine kalu amenna bi efvahihim ve lem tu\'min kulubuhum, ve minellezine hadu semmaune lil kezibi semmaune li kavmin aharine lem ye\'tuk yuharrifunel kelime min ba\'di mevadııh, yekulune in utitum haza fe huzuhu ve in lem tu\'tevhu fahzeru ve men yuridillahu fitnetehu fe len temlike lehu minallahi şey\'a ulaikellezine lem yuridillahu en yutahhire kulubehum lehum fid dunya hızyun ve lehum fil ahıreti azabun azim.', 'Ey Resul! Küfre koşuşanlar seni üzmesin. O kimseler ki ağızlarıyla inandık dedikleri halde,  kalben inanmadılar. Ve bir de yalan uydurmak amacıyla kasıtlı dinleyen Yahudiler,  sana gelmeyen başka bir halk adına casusluk yapmak için dinlerler. Sözleri bağlamlarından kopararak değiştiriyorlar: \"Eğer bu size verilirse onu alın,  eğer bu verilmezse sakının!\" diyorlar. Allah,  kimin fitneye düşmesini isterse,  onun için Allah\'a karşı elinden hiçbir şey gelmez. İşte onlar,  Allah\'ın kalplerini arındırmak istemediği kimselerdir.[1] Onlar için dünyada aşağılanma,  ahirette de büyük bir azap vardır.', 'يايها الرسول لا يحزنك الذين يسرعون في الكفر من الذين قالوا امنا بافوههم ولم تومن قلوبهم ومن الذين هادوا سمعون للكذب سمعون لقوم اخرين لم ياتوك يحرفون الكلم من بعد مواضعه يقولون ان اوتيتم هذا فخذوه وان لم توتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيا اوليك الذين لم يرد الله ان يطهر قلوبهم لهم في الدنيا خزي ولهم في الاخرة عذاب عظيم'),
(711, 5, 42, 'سَمَّاعُونَ لِلْكَذِبِ اَكَّالُونَ لِلسُّحْتِۜ فَاِنْ جَٓاؤُ۫كَ فَاحْكُمْ بَيْنَهُمْ اَوْ اَعْرِضْ عَنْهُمْۚ وَاِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَضُرُّوكَ شَيْـٔاًۜ وَاِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِۜ اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِط۪ينَ', 'Semmaune lil kezibi ekkalune lis suht fe in cauke fahkum beynehum ev a\'rıd anhum, ve in tu\'rıd anhum fe len yedurruke şey\'a ve in hakemte fahkum beynehum bil kıst innallahe yuhıbbul muksıtin.', 'Yalan uydurmak için can kulağı ile dinlerler ve sürekli suhtla[1] geçinirler. Eğer hüküm vermen için sana gelirlerse,  aralarında hüküm ver veya onlardan yüz çevir. Eğer onlardan yüz çevirirsen sana hiçbir zarar veremezler. Ve eğer hüküm verirsen,  aralarında hakkaniyetle hüküm ver. Kuşkusuz,  Allah,  hakkaniyetli olanları sever.', 'سمعون للكذب اكلون للسحت فان جاوك فاحكم بينهم او اعرض عنهم وان تعرض عنهم فلن يضروك شيا وان حكمت فاحكم بينهم بالقسط ان الله يحب المقسطين'),
(712, 5, 43, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِنْدَهُمُ التَّوْرٰيةُ ف۪يهَا حُكْمُ اللّٰهِ ثُمَّ يَتَوَلَّوْنَ مِنْ بَعْدِ ذٰلِكَۜ وَمَٓا اُو۬لٰٓئِكَ بِالْمُؤْمِن۪ينَ۟', 'Ve keyfe yuhakkimuneke ve indehumut tevratu fiha hukmullahi summe yetevellevne min ba\'di zalik ve ma ulaike bil mu\'minin.', 'İçinde,  Allah\'ın hükmünün[1] bulunduğu Tevrat yanlarında olduğu halde,  nasıl olur da sana hüküm verdiriyorlar? Sonra da o hükümden döneklik ediyorlar. Onlar,  aslında inanmış değiller.', 'وكيف يحكمونك وعندهم التورية فيها حكم الله ثم يتولون من بعد ذلك وما اوليك بالمومنين'),
(713, 5, 44, 'اِنَّٓا اَنْزَلْنَا التَّوْرٰيةَ ف۪يهَا هُدًى وَنُورٌۚ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذ۪ينَ اَسْلَمُوا لِلَّذ۪ينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْاَحْبَارُ بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللّٰهِ وَكَانُوا عَلَيْهِ شُهَدَٓاءَۚ فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ وَلَا تَشْتَرُوا بِاٰيَات۪ي ثَمَناً قَل۪يلاًۜ وَمَنْ لَمْ يَحْكُمْ بِمَٓا اَنْزَلَ اللّٰهُ فَاُو۬لٰٓئِكَ هُمُ الْكَافِرُونَ', 'İnna enzelnet tevrate fiha huden ve nur, yahkumu bihen nebiyyunellezine eslemu lillezine hadu ver rabbaniyyune vel ahbaru bimestuhfizu min kitabillahi ve kanu aleyhi şuhedae, fe la tahşevun nase vahşevni ve la teşteru bi ayati semenen kalila ve men lem yahkum bima enzelallahu fe ulaike humul kafirun.', 'Kuşkusuz,  Biz,  doğru yola iletici ve aydınlatıcı olan Tevrat\'ı indirdik. Nebiler,  onunla teslim olan Yahudiler için hüküm veriyorlardı. Rabbaniler[1] ve ahbar[2] olanlar da Allah\'ın kitabından ezberletilmiş olmasından dolayı,  ona tanıklık ediyorlardı. Öyleyse siz insanlardan değil,  Bana karşı gelmekten sakının. Benim ayetlerimi az bir bedele değişmeyin! Allah\'ın indirdiği ile hükmetmeyenler,  Kafirlerin[3] ta kendileridir.', 'انا انزلنا التورية فيها هدي ونور يحكم بها النبيون الذين اسلموا للذين هادوا والربنيون والاحبار بما استحفظوا من كتب الله وكانوا عليه شهدا فلا تخشوا الناس واخشون ولا تشتروا بايتي ثمنا قليلا ومن لم يحكم بما انزل الله فاوليك هم الكفرون'),
(714, 5, 45, 'وَكَتَبْنَا عَلَيْهِمْ ف۪يهَٓا اَنَّ النَّفْسَ بِالنَّفْسِۙ وَالْعَيْنَ بِالْعَيْنِ وَالْاَنْفَ بِالْاَنْفِ وَالْاُذُنَ بِالْاُذُنِ وَالسِّنَّ بِالسِّنِّۙ وَالْجُرُوحَ قِصَاصٌۜ فَمَنْ تَصَدَّقَ بِه۪ فَهُوَ كَفَّارَةٌ لَهُۜ وَمَنْ لَمْ يَحْكُمْ بِمَٓا اَنْزَلَ اللّٰهُ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'Ve ketebna aleyhim fiha ennen nefse bin nefsi vel ayne bil ayni vel enfe bil enfi vel uzune bil uzuni ves sinne bis sinni vel curuha kısas fe men tesaddeka bihi fe huve keffaretun leh ve men lem yahkum bima enzelallahu fe ulaike humuz zalimun.', 'Ve Biz,  onda,  onların üzerine yazdık: \"Cana can,  göze göz,  buruna burun,  kulağa kulak,  dişe diş ve yaralamalarda kısas[1] vardır.\" Artık kim onunla tasadduk[2] ederse o,  onun için bir kefarettir.[3] Allah\'ın indirdiği ile hükmetmeyenler,  zalimlerin ta kendileridirler.', 'وكتبنا عليهم فيها ان النفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفارة له ومن لم يحكم بما انزل الله فاوليك هم الظلمون'),
(715, 5, 46, 'وَقَفَّيْنَا عَلٰٓى اٰثَارِهِمْ بِع۪يسَى ابْنِ مَرْيَمَ مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرٰيةِۖ وَاٰتَيْنَاهُ الْاِنْج۪يلَ ف۪يهِ هُدًى وَنُورٌۙ وَمُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرٰيةِ وَهُدًى وَمَوْعِظَةً لِلْمُتَّق۪ينَ', 'Ve kaffeyna ala asarihim bi isebni meryeme musaddıkan lima beyne yedeyhi minet tevrati ve ateynahul incile fihi huden ve nurun ve musaddıkan lima beyne yedeyhi minet tevrati ve huden ve mev\'ızeten muttekin.', 'Onların ardından,  Tevrat\'ı tasdik edici olarak,  Meryem oğlu İsa\'yı gönderdik. Biz ona,  içinde hidayet ve nur bulunan,  Tevrat\'ı tasdik eden,  takva sahipleri için hidayet ve öğüt olan İncil\'i verdik.', 'وقفينا علي اثرهم بعيسي ابن مريم مصدقا لما بين يديه من التورية واتينه الانجيل فيه هدي ونور ومصدقا لما بين يديه من التورية وهدي وموعظة للمتقين'),
(716, 5, 47, 'وَلْيَحْكُمْ اَهْلُ الْاِنْج۪يلِ بِمَٓا اَنْزَلَ اللّٰهُ ف۪يهِۜ وَمَنْ لَمْ يَحْكُمْ بِمَٓا اَنْزَلَ اللّٰهُ فَاُو۬لٰٓئِكَ هُمُ الْفَاسِقُونَ', 'Vel yahkum ehlul incili bima enzelallahu fih ve men lem yahkum bima enzelallahu fe ulaike humul fasıkun.', 'İncil ehli,  Allah\'ın onda indirdiği ile hükmetsinler. Ve kim Allah\'ın indirdiği ile hükmetmezse işte onlar fasıklardır.[1]', 'وليحكم اهل الانجيل بما انزل الله فيه ومن لم يحكم بما انزل الله فاوليك هم الفسقون'),
(717, 5, 48, 'وَاَنْزَلْـنَٓا اِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِناً عَلَيْهِ فَاحْكُمْ بَيْنَهُمْ بِمَٓا اَنْزَلَ اللّٰهُ وَلَا تَتَّبِعْ اَهْوَٓاءَهُمْ عَمَّا جَٓاءَكَ مِنَ الْحَقِّۜ لِكُلٍّ جَعَلْنَا مِنْكُمْ شِرْعَةً وَمِنْهَاجاًۜ وَلَوْ شَٓاءَ اللّٰهُ لَجَعَلَكُمْ اُمَّةً وَاحِدَةً وَلٰكِنْ لِيَبْلُوَكُمْ ف۪ي مَٓا اٰتٰيكُمْ فَاسْتَبِقُوا الْخَيْرَاتِۜ اِلَى اللّٰهِ مَرْجِعُكُمْ جَم۪يعاً فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ ف۪يهِ تَخْتَلِفُونَۙ', 'Ve enzelna ileykel kitabe bil hakkı musaddıkan lima beyne yedeyhi minel kitabi ve muheyminen aleyhi fahkum beynehum bima enzelallahu ve la tettebi\' ehvaehum amma caeke minel hakk li kullin cealna minkum şir\'aten ve minhaca ve lev şaallahu le cealekum ummeten vahıdeten ve lakin li yebluvekum fi ma atakum festebikul hayrat ilallahi merciukum cemian fe yunebbiukum bima kuntum fihi tahtelifun.', 'Biz sana,  kendinden önceki Kitap\'ı tasdik eden,  onu düzenleyen[1] bu Kitap\'ı hakk[2] olarak indirdik. O halde,  aralarında Allah\'ın indirdiği ile hükmet. Ve sakın sana gelen hakkı bırakıp onların hevalarına[3] uyma. Ve Biz,  sizin her biriniz için,  bir şeriat[4] ve yöntem belirledik. Allah dileseydi,  sizi tek tip bir topluluk yapardı. Ancak sizlere verdiği ile sizi sınıyor.[5] O halde hayırlarda yarışın. Hepinizin dönüşü Allah\'adır. Allah,  üzerinde ayrılığa düştüğünüz şeyleri bildirecektir.', 'وانزلنا اليك الكتب بالحق مصدقا لما بين يديه من الكتب ومهيمنا عليه فاحكم بينهم بما انزل الله ولا تتبع اهواهم عما جاك من الحق لكل جعلنا منكم شرعة ومنهاجا ولو شا الله لجعلكم امة وحدة ولكن ليبلوكم في ما اتيكم فاستبقوا الخيرت الي الله مرجعكم جميعا فينبيكم بما كنتم فيه تختلفون'),
(718, 5, 49, 'وَاَنِ احْكُمْ بَيْنَهُمْ بِمَٓا اَنْزَلَ اللّٰهُ وَلَا تَتَّبِـعْ اَهْوَٓاءَهُمْ وَاحْذَرْهُمْ اَنْ يَفْتِنُوكَ عَنْ بَعْضِ مَٓا اَنْزَلَ اللّٰهُ اِلَيْكَۜ فَاِنْ تَوَلَّوْا فَاعْلَمْ اَنَّمَا يُر۪يدُ اللّٰهُ اَنْ يُص۪يبَهُمْ بِبَعْضِ ذُنُوبِهِمْۜ وَاِنَّ  كَث۪يراً مِنَ النَّاسِ لَفَاسِقُونَ', 'Ve enıhkum beynehum bima enzelallahu ve la tettebi\' ehvaehum vahzerhum en yeftinuke an ba\'dı ma enzelallahu ileyk fe in tevellev fa\'lem ennema yuridullahu en yusibehum bi ba\'dı zunubihim ve inne kesiran minen nasi le fasıkun.', 'Ve aralarında,  Allah\'ın sana indirdiğiyle hükmet. Onların hevalarına uyma. Allah\'ın sana indirdiğinin bir kısmından seni şaşırtmalarından ve onlardan sakın. Eğer verdiğin kararlara uymazlarsa,  bilesin ki Allah,  bazı günahları nedeniyle onlara musibet isabet ettirmeyi istiyor. İnsanların pek çoğu elbette fasıktır.', 'وان احكم بينهم بما انزل الله ولا تتبع اهواهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك فان تولوا فاعلم انما يريد الله ان يصيبهم ببعض ذنوبهم وان كثيرا من الناس لفسقون'),
(719, 5, 50, 'اَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَۜ وَمَنْ اَحْسَنُ مِنَ اللّٰهِ حُكْماً لِقَوْمٍ يُوقِنُونَ۟', 'E fe hukmel cahiliyyeti yebgun ve men ahsenu minallahi hukmen li kavmin yukınun.', 'Cahiliye[1] hükmünü mü istiyorlar? Gerçeği kavramış bir toplum için,  Allah\'tan daha iyi hüküm veren kim olabilir?', 'افحكم الجهلية يبغون ومن احسن من الله حكما لقوم يوقنون'),
(720, 5, 51, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُوا الْيَهُودَ وَالنَّصَارٰٓى اَوْلِيَٓاءَۢ  بَعْضُهُمْ اَوْلِيَٓاءُ بَعْضٍۜ وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَاِنَّهُ مِنْهُمْۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'Ya eyyuhellezine amenu la tettehızul yehude ven nasara evliyae ba\'duhum evliyau ba\'d ve men yetevellehum minkum fe innehu minhum innallahe la yehdil kavmez zalimin.', 'Ey iman edenler! Yahudileri ve Hıristiyanları veliler[1] edinmeyin. Onlar,  birbirlerinin velileridir.[1] Sizden kim onları mütevelli[1] edinirse,  kuşkusuz o,  onlardandır. Kuşkusuz,  Allah,  zalim topluma hidayet etmez.', 'يايها الذين امنوا لا تتخذوا اليهود والنصري اوليا بعضهم اوليا بعض ومن يتولهم منكم فانه منهم ان الله لا يهدي القوم الظلمين'),
(721, 5, 52, 'فَتَرَى الَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ يُسَارِعُونَ ف۪يهِمْ يَقُولُونَ نَخْشٰٓى اَنْ تُص۪يبَنَا دَٓائِرَةٌۜ  فَعَسَى اللّٰهُ اَنْ يَأْتِيَ بِالْفَتْحِ اَوْ اَمْرٍ مِنْ عِنْدِه۪ فَيُصْبِحُوا عَلٰى مَٓا اَسَرُّوا ف۪ٓي اَنْفُسِهِمْ نَادِم۪ينَۜ', 'Fe terallezine fi kulubihim maradun yusariune fihim yekulune nahşa en tusibena daireh fe asallahu en ye\'tiye bil fethi ev emrin min indihi fe yusbihu ala ma eserru fi enfusihim nadimin.', 'Kalplerinde hastalık bulunanların,  \"Başımıza bir bela gelmesinden korkuyoruz.\" diyerek,  onların aralarında koşuştuklarını görürsün. Olur ki,  Allah bir fetih veya kendi katından bir emir getirir ve böylece onlar içlerinde gizledikleri şeyden pişman olurlar!', 'فتري الذين في قلوبهم مرض يسرعون فيهم يقولون نخشي ان تصيبنا دايرة فعسي الله ان ياتي بالفتح او امر من عنده فيصبحوا علي ما اسروا في انفسهم ندمين'),
(722, 5, 53, 'وَيَقُولُ الَّذ۪ينَ اٰمَنُٓوا اَهٰٓؤُ۬لَٓاءِ الَّذ۪ينَ اَقْسَمُوا بِاللّٰهِ جَهْدَ اَيْمَانِهِمْۙ اِنَّهُمْ لَمَعَكُمْۜ حَبِطَتْ اَعْمَالُهُمْ فَاَصْبَحُوا خَاسِر۪ينَ', 'Ve yekulullezine amenu e haulaillezine aksemu billahi cehde eymanihim innehum le meakum habitat a\'maluhum fe asbahu hasirin.', 'İman edenler şöyle derler: \"Bütün yeminleri[1] ile senin yanında olacaklarına dair Allah\'a yemin edenler bunlar mı?\" İşte onların yaptığı bütün işler boşa gitti. Ve hüsrana uğrayanlar oldular.', 'ويقول الذين امنوا اهولا الذين اقسموا بالله جهد ايمنهم انهم لمعكم حبطت اعملهم فاصبحوا خسرين'),
(723, 5, 54, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا مَنْ يَرْتَدَّ مِنْكُمْ عَنْ د۪ينِه۪ فَسَوْفَ يَأْتِي اللّٰهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُٓ  اَذِلَّةٍ عَلَى الْمُؤْمِن۪ينَ اَعِزَّةٍ عَلَى الْكَافِر۪ينَۘ يُجَاهِدُونَ ف۪ي سَب۪يلِ اللّٰهِ وَلَا يَخَافُونَ لَوْمَةَ لَٓائِمٍۜ ذٰلِكَ فَضْلُ اللّٰهِ يُؤْت۪يهِ مَنْ يَشَٓاءُۜ وَاللّٰهُ وَاسِعٌ عَل۪يمٌ', 'Ya eyyuhellezine amenu men yertedde minkum an dinihi fe sevfe ye\'tillahu bi kavmin yuhıbbuhum ve yuhıbbunehu ezilletin alal mu\'minine eizzetin alal kafirin, yucahidune fi sebilillahi ve la yehafune levmete laim zalike fadlullahi yu\'tihi men yeşa vallahu vasiun alim.', 'Ey iman edenler! Sizden kim dininden dönerse[1] bilsin ki Allah,  Kendisinin onları sevdiği ve onların da O\'nu sevdiği; Müminlere karşı alçak gönüllü,  Kafirlere karşı izzetli, [2] Allah yolunda cihad eden,  kınayıcının kınamasından korkmayan bir halk getirir. İşte bu Allah\'ın fazlıdır[3] ki o fazlı dilediğine verir. Ve Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Her Şeyi Bilen\'dir.', 'يايها الذين امنوا من يرتد منكم عن دينه فسوف ياتي الله بقوم يحبهم ويحبونه اذلة علي المومنين اعزة علي الكفرين يجهدون في سبيل الله ولا يخافون لومة لايم ذلك فضل الله يوتيه من يشا والله وسع عليم'),
(724, 5, 55, 'اِنَّمَا وَلِيُّكُمُ اللّٰهُ وَرَسُولُهُ وَالَّذ۪ينَ اٰمَنُوا الَّذ۪ينَ يُق۪يمُونَ الصَّلٰوةَ وَيُؤْتُونَ الزَّكٰوةَ وَهُمْ رَاكِعُونَ', 'İnnema veliyyukumullahu ve resuluhu vellezine amenullezine yukimunes salate ve yu\'tunez zekate ve hum rakıun.', 'Sizin veliniz; ancak Allah,  O\'nun Resulü ve \"salatı ikame edip ruku halinde zekat yapan\"[1] mü\'minlerdir.', 'انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلوة ويوتون الزكوة وهم ركعون'),
(725, 5, 56, 'وَمَنْ يَتَوَلَّ اللّٰهَ وَرَسُولَهُ وَالَّذ۪ينَ اٰمَنُوا فَاِنَّ حِزْبَ اللّٰهِ هُمُ الْغَالِبُونَ۟', 'Ve men yetevellallahe ve resulehu vellezine amenu fe inne hızbellahi humul galibun.', 'Ve kim Allah\'ı ve O\'nun Resul\'ünü ve mü\'minleri veli edinirse,  Allah\'ın taraftarları onlardır. Galip gelecek olanlar da onlardır.', 'ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغلبون'),
(726, 5, 57, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُوا الَّذ۪ينَ اتَّخَذُوا د۪ينَكُمْ هُزُواً وَلَعِباً مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَالْكُفَّارَ اَوْلِيَٓاءَۚ وَاتَّقُوا اللّٰهَ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ya eyyuhellezine amenu la tettehızullezinettehazu dinekum huzuven ve leiben min ellezine utul kitabe min kablikum vel kuffara evliya, vettekullahe in kuntum mu\'minin.', 'Ey iman edenler! Sizden önce kendilerine kitap verilenlerden ve Kafirlerden[1],  dininizi alay ve eğlenceye alan kimseleri veliler[2] edinmeyin. Eğer iman etmiş kimselerseniz,  Allah\'a karşı takvalı olun.', 'يايها الذين امنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين اوتوا الكتب من قبلكم والكفار اوليا واتقوا الله ان كنتم مومنين'),
(727, 5, 58, 'وَاِذَا نَادَيْتُمْ اِلَى الصَّلٰوةِ اتَّخَذُوهَا هُزُواً وَلَعِباًۜ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَا يَعْقِلُونَ', 'Ve iza nadeytum iles salatittehazuha huzuven ve leıba zalike bi ennehum kavmun la ya\'kılun.', 'Salata[1] çağrıldığınız zaman,  onu alay ve eğlence konusu yaparlar. Bu,  onların kesinlikle aklını kullanmayan bir topluluk olmalarındandır.', 'واذا ناديتم الي الصلوة اتخذوها هزوا ولعبا ذلك بانهم قوم لا يعقلون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(728, 5, 59, 'قُلْ يَٓا اَهْلَ الْكِتَابِ هَلْ تَنْقِمُونَ مِنَّٓا اِلَّٓا اَنْ اٰمَنَّا بِاللّٰهِ وَمَٓا اُنْزِلَ اِلَيْنَا وَمَٓا اُنْزِلَ مِنْ قَبْلُۙ وَاَنَّ اَكْثَرَكُمْ فَاسِقُونَ', 'Kul ya ehlel kitabi hel tenkımune minna illa en amenna billahi ve ma unzile ileyna ve ma unzile min kablu ve enne ekserekum fasıkun.', 'De ki: \"Ey Kitap Ehli! Allah\'a,  bize indirilene ve bizden önce indirilene inandığımız için mi bizden nefret ediyorsunuz? Kuşkusuz,  çoğunuz fasıksınız.[1]\"', 'قل ياهل الكتب هل تنقمون منا الا ان امنا بالله وما انزل الينا وما انزل من قبل وان اكثركم فسقون'),
(729, 5, 60, 'قُلْ هَلْ اُنَبِّئُكُمْ بِشَرٍّ مِنْ ذٰلِكَ مَثُوبَةً عِنْدَ اللّٰهِۜ مَنْ لَعَنَهُ اللّٰهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ الْقِرَدَةَ وَالْخَنَاز۪يرَ وَعَبَدَ الطَّاغُوتَۜ اُو۬لٰٓئِكَ شَرٌّ مَكَاناً وَاَضَلُّ عَنْ سَوَٓاءِ السَّب۪يلِ', 'Kul hel unebbiukum bi şerrin min zalike mesubeten ındallah men leanehullahu ve gadıbe aleyhi ve ceale min humul kıredete vel hanazire ve abedet tagut ulaike şerrun mekanen ve edallu an sevais sebil.', 'De ki: Allah\'ın katında ceza olarak bunlardan daha kötüsünü size haber vereyim mi? Allah\'ın lanet[1] ettiği,  gazabına uğrattığı ve onlardan maymunlar[2],  domuzlar[2] ve tağuta[3] kulluk eden kimseler yapmışsa,  işte bunlar,  durumları bakımından en kötü olan ve doğru yoldan sapmış olanlardır.', 'قل هل انبيكم بشر من ذلك مثوبة عند الله من لعنه الله وغضب عليه وجعل منهم القردة والخنازير وعبد الطغوت اوليك شر مكانا واضل عن سوا السبيل'),
(730, 5, 61, 'وَاِذَا جَٓاؤُ۫كُمْ قَالُٓوا اٰمَنَّا وَقَدْ دَخَلُوا بِالْـكُفْرِ وَهُمْ قَدْ خَرَجُوا بِه۪ۜ وَاللّٰهُ اَعْلَمُ بِمَا كَانُوا يَكْتُمُونَ', 'Ve iza caukum kalu amenna ve kad dehalu bil kufri ve hum kad haracu bih vallahu a\'lemu bima kanu yektumun.', 'Onlar,  size geldiklerinde,  \"İman ettik.\" dediler. Oysaki onlar,  yanınıza küfürle girdiler,  küfürle çıktılar. Allah,  gizledikleri şeyi en iyi bilendir.', 'واذا جاوكم قالوا امنا وقد دخلوا بالكفر وهم قد خرجوا به والله اعلم بما كانوا يكتمون'),
(731, 5, 62, 'وَتَرٰى كَث۪يراً مِنْهُمْ يُسَارِعُونَ فِي الْاِثْمِ وَالْعُدْوَانِ وَاَكْلِهِمُ السُّحْتَۜ لَبِئْسَ مَا كَانُوا يَعْمَلُونَ', 'Ve tera kesiran minhum yusariune fil ismi vel udvani ve eklihimus suht lebi\'se ma kanu ya\'melun.', 'Ve onlardan pek çoğunun,  günah işlemede,  düşmanlık yapmada ve suht[1] yemede birbirleriyle yarıştıklarını görürsün. Yapmakta oldukları şey ne kadar kötüdür!', 'وتري كثيرا منهم يسرعون في الاثم والعدون واكلهم السحت لبيس ما كانوا يعملون'),
(732, 5, 63, 'لَوْلَا يَنْهٰيهُمُ الرَّبَّانِيُّونَ وَالْاَحْبَارُ عَنْ قَوْلِهِمُ الْاِثْمَ وَاَكْلِهِمُ السُّحْتَۜ لَبِئْسَ مَا كَانُوا يَصْنَعُونَ', 'Lev la yenhahumur rabbaniyyune vel ahbaru an kavlihimul isme ve eklihimus suht lebi\'se ma kanu yasneun.', 'Rabbanilerin[1] ve ahbarın[2]; günah söz söylemekten ve suht[3] yemekten sakındırmaları gerekmez miydi? Yaltaklanmaları ne kötüdür.', 'لولا ينهيهم الربنيون والاحبار عن قولهم الاثم واكلهم السحت لبيس ما كانوا يصنعون'),
(733, 5, 64, 'وَقَالَتِ الْيَهُودُ يَدُ اللّٰهِ مَغْلُولَةٌۜ غُلَّتْ اَيْد۪يهِمْ وَلُعِنُوا بِمَا قَالُواۢ بَلْ يَدَاهُ مَبْسُوطَتَانِۙ يُنْفِقُ كَيْفَ يَشَٓاءُۜ وَلَيَز۪يدَنَّ كَث۪يراً مِنْهُمْ مَٓا اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَ طُغْيَاناً وَكُفْراًۜ وَاَلْقَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَٓاءَ اِلٰى يَوْمِ الْقِيٰمَةِۜ   كُلَّمَٓا اَوْقَدُوا نَاراً لِلْحَرْبِ اَطْفَاَهَا اللّٰهُۙ وَيَسْعَوْنَ فِي الْاَرْضِ فَسَاداًۜ وَاللّٰهُ لَا يُحِبُّ الْمُفْسِد۪ينَ', 'Ve kaletil yehudu yedullahi magluleh gullet eydihim ve luınu bima kalu bel yedahu mebsutatani yunfıku keyfe yeşa ve leyezidenne kesiran minhum ma unzile ileyke min rabbike tugyanen ve kufra ve elkayna beynehumul adavete vel bagdae ila yevmil kıyameh kullema evkadu naran lil harbi etfeehallahu ve yes\'avne fil ardı fesada vallahu la yuhıbbul mufsidin.', 'O Yahudiler[1],  \"Allah\'ın eli bağlıdır.[2]\" dediler. Böyle söylemelerinden dolayı elleri bağlandı ve söyledikleri yüzünden lanetlendiler. Oysaki O\'nun iki eli de açıktır.[3] Nasıl dilerse öyle infak[4] eder. Yemin olsun ki sana Rabb\'inden indirilen şey onların çoğunun azgınlığını ve küfrünü arttıracaktır. Biz de aralarına Kıyamet Günü\'ne kadar düşmanlık ve nefret yerleştirdik. Savaş için ateş yaktıkları her seferinde Allah onu söndürdü. Yeryüzünde bozgunculuk için koşuşuyorlar. Ve Allah bozguncuları sevmez.', 'وقالت اليهود يد الله مغلولة غلت ايديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشا وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا والقينا بينهم العدوة والبغضا الي يوم القيمة كلما اوقدوا نارا للحرب اطفاها الله ويسعون في الارض فسادا والله لا يحب المفسدين'),
(734, 5, 65, 'وَلَوْ اَنَّ اَهْلَ الْكِتَابِ اٰمَنُوا وَاتَّقَوْا لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَاَدْخَلْنَاهُمْ جَنَّاتِ النَّع۪يمِ', 'Ve lev enne ehlel kitabi amenu vettekav le kefferna anhum seyyiatihim ve le edhalnahum cennatin naim.', 'Eğer Kitap Ehli de inanıp takva sahibi olsaydı,  kötülüklerini örter[1],  nimet dolu Cennetlere koyardık.', 'ولو ان اهل الكتب امنوا واتقوا لكفرنا عنهم سياتهم ولادخلنهم جنت النعيم'),
(735, 5, 66, 'وَلَوْ اَنَّهُمْ اَقَامُوا التَّوْرٰيةَ وَالْاِنْج۪يلَ وَمَٓا اُنْزِلَ اِلَيْهِمْ مِنْ رَبِّهِمْ لَاَكَلُوا مِنْ فَوْقِهِمْ وَمِنْ تَحْتِ اَرْجُلِهِمْۜ مِنْهُمْ اُمَّةٌ مُقْتَصِدَةٌۜ وَكَث۪يرٌ مِنْهُمْ سَٓاءَ مَا يَعْمَلُونَ۟', 'Ve lev ennehum ekamut tevrate vel incile ve ma unzile ileyhim min rabbihim le ekelu min fevkıhim ve min tahti erculihim. Minhum ummetun muktesıdeh ve kesirun minhum sae ma ya\'melun.', 'Eğer onlar,  Tevrat\'ı,  İncil\'i ve Rabb\'lerinden kendilerine indirileni gereğince uygulasalardı hem üstlerinden hem de ayaklarının altından[1] yiyeceklerdi. İçlerinde muktesid[2] bir topluluk var. Ve onlardan çoğu da kötü işler yapıyorlar.', 'ولو انهم اقاموا التورية والانجيل وما انزل اليهم من ربهم لاكلوا من فوقهم ومن تحت ارجلهم منهم امة مقتصدة وكثير منهم سا ما يعملون'),
(736, 5, 67, 'يَٓا اَيُّهَا الرَّسُولُ بَلِّـغْ مَٓا اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَۜ وَاِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۜ وَاللّٰهُ يَعْصِمُكَ مِنَ النَّاسِۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الْكَافِر۪ينَ', 'Ya eyyuherresulu bellıg ma unzile ileyke min rabbik ve in lem tef\'al fema bellagte risaleteh vallahu ya\'sımuke minen nas innallahe la yehdil kavmel kafirin.', 'Ey Resul! Rabb\'inden sana her indirileni tebliğ et. Eğer yapmazsan,  O\'nun mesajını tebliğ etmemiş sayılırsın. Allah,  seni insanlardan koruyor. Kuşkusuz,  Allah,  Kafirleri doğru yola iletmez.', 'يايها الرسول بلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته والله يعصمك من الناس ان الله لا يهدي القوم الكفرين'),
(737, 5, 68, 'قُلْ يَٓا اَهْلَ الْكِتَابِ لَسْتُمْ عَلٰى شَيْءٍ حَتّٰى تُق۪يمُوا التَّوْرٰيةَ وَالْاِنْج۪يلَ وَمَٓا اُنْزِلَ اِلَيْكُمْ مِنْ رَبِّكُمْۜ وَلَيَز۪يدَنَّ كَث۪يراً مِنْهُمْ مَٓا اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَ طُغْيَاناً وَكُفْراًۚ فَلَا تَأْسَ عَلَى الْقَوْمِ الْكَافِر۪ينَ', 'Kul ya ehlel kitabi! lestum ala şey\'in hatta tukimut Tevrate vel İncile ve ma unzile ileykum min rabbikum ve le yezidenne kesiren minhum ma unzile ileyke min rabbike tugyanen ve kufr, fe la te\'se alal kavmil kafirin.', 'De ki: \"Ey Kitap ehli! Tevrat\'ı ve İncil\'i ve Rabb\'inizden size indirileni gereğince uygulamadığınız sürece inancınızı sağlam bir temele oturtmuş olmazsınız.\" Elbette Rabb\'inden sana indirilmekte olan şey,  onlardan çoğunun azgınlığını ve küfrünü artırır. O halde gerçeği yalanlayan nankör halka üzülme.', 'قل ياهل الكتب لستم علي شي حتي تقيموا التورية والانجيل وما انزل اليكم من ربكم وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا فلا تاس علي القوم الكفرين'),
(738, 5, 69, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَالَّذ۪ينَ هَادُوا وَالصَّابِـؤُ۫نَ وَالنَّصَارٰى مَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَعَمِلَ صَالِحاً فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'İnnellezine amenu vellezine hadu ves sabiune ven nasara men amene billahi vel yevmil ahıri ve amile salihan fe la havfun aleyhim ve la hum yahzenun.', 'İman edenler,  Yahudiler,  Sabiiler ve Nasraniler; kim Allah\'a ve Âhiret Günü\'ne iman etti[1] ve salihatı[2] yaptı ise onlara korku yoktur ve üzülmeyeceklerdir de.', 'ان الذين امنوا والذين هادوا والصبون والنصري من امن بالله واليوم الاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون'),
(739, 5, 70, 'لَقَدْ اَخَذْنَا م۪يثَاقَ بَن۪ٓي اِسْرَٓائ۪لَ وَاَرْسَلْـنَٓا اِلَيْهِمْ رُسُلاًۜ  كُلَّمَا جَٓاءَهُمْ رَسُولٌ بِمَا لَا تَهْوٰٓى اَنْفُسُهُمْۙ فَر۪يقاً كَذَّبُوا وَفَر۪يقاً يَقْتُلُونَ', 'Lekad ehazna misaka beni israile ve erselna ileyhim rusula kullema caehum resulun bima la tehva enfusuhum ferikan kezzebu ve ferikan yaktulun.', 'Elbette İsrailoğulları\'ndan söz aldık ve onlara resuller gönderdik. Ne zaman kendi hevalarına[1] uymayan bir resul geldiyse,  bir kısmını yalanlıyor ve bir kısmını da öldürüyorlardı.', 'لقد اخذنا ميثق بني اسريل وارسلنا اليهم رسلا كلما جاهم رسول بما لا تهوي انفسهم فريقا كذبوا وفريقا يقتلون'),
(740, 5, 71, 'وَحَسِبُٓوا اَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا وَصَمُّوا ثُمَّ تَابَ اللّٰهُ عَلَيْهِمْ ثُمَّ عَمُوا وَصَمُّوا كَث۪يرٌ مِنْهُمْۜ وَاللّٰهُ بَص۪يرٌ بِمَا يَعْمَلُونَ', 'Ve hasibu ella tekune fitnetun fe amu ve sammu summe taballahu aleyhim summe amu ve sammu kesirun minhum vallahu basirun bima ya\'melun.', 'Bir fitne[1] olmayacağını sandılar da kör ve sağır kesildiler.[2] Sonra Allah,  onların üzerine tevbe[3] etti. Daha sonra onlardan birçoğu yine kör ve sağır kesildiler. Allah ne yaptıklarını gerçeğiyle görmektedir.', 'وحسبوا الا تكون فتنة فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون'),
(741, 5, 72, 'لَقَدْ كَفَرَ الَّذ۪ينَ قَالُٓوا اِنَّ اللّٰهَ هُوَ الْمَس۪يحُ ابْنُ مَرْيَمَۜ وَقَالَ الْمَس۪يحُ يَا بَن۪ٓي اِسْرَٓائ۪لَ اعْبُدُوا اللّٰهَ رَبّ۪ي وَرَبَّكُمْۜ اِنَّهُ مَنْ يُشْرِكْ بِاللّٰهِ فَقَدْ حَرَّمَ اللّٰهُ عَلَيْهِ الْجَنَّةَ وَمَأْوٰيهُ النَّارُۜ وَمَا لِلظَّالِم۪ينَ مِنْ اَنْصَارٍ', 'Lekad keferallezine kalu innallahe huvel mesihubnu meryem ve kalel mesihu ya beni israila\'budullahe rabbi ve rabbekum innehu men yuşrik billahi fekad harremallahu aleyhil cennete ve me\'vahun nar ve ma liz zalimine min ensar.', 'Ant olsun Meryem oğlu Mesih\'e,  \"O Allah\'tır.\" diyenler Kafir oldular. Oysaki Mesih: \"Ey İsrailoğulları! Benim de sizin de Rabb\'iniz olan Allah\'a kulluk edin. Kim Allah\'a şirk koşarsa,  Allah ona Cenneti haram etmiştir. Ve onun varacağı yer ateştir. Zalimler için hiçbir yardımcı yoktur.\" dedi.', 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم وقال المسيح يبني اسريل اعبدوا الله ربي وربكم انه من يشرك بالله فقد حرم الله عليه الجنة وماويه النار وما للظلمين من انصار'),
(742, 5, 73, 'لَقَدْ كَفَرَ الَّذ۪ينَ قَالُٓوا اِنَّ اللّٰهَ ثَالِثُ ثَلٰثَةٍۢ وَمَا مِنْ اِلٰهٍ اِلَّٓا اِلٰهٌ وَاحِدٌۜ وَاِنْ لَمْ يَنْتَهُوا عَمَّا يَقُولُونَ لَيَمَسَّنَّ الَّذ۪ينَ كَفَرُوا مِنْهُمْ عَذَابٌ اَل۪يمٌ', 'Lekad keferellezine kalu innallahe salisu selasetin ve ma min ilahin illa ilahun vahid ve in lem yentehu amma yekulune le yemessennellezine keferu minhum azabun elim.', 'Ant olsun \"Allah,  üçün üçüncüsüdür.\" diyenler Kafir oldular. Oysaki bir tek ilahtan başka ilah yoktur. Ve eğer bu söylediklerinden vazgeçmezlerse,  onlardan gerçeği yalanlayarak nankörlük edenlere elbette elem verici bir azap dokunacaktır.', 'لقد كفر الذين قالوا ان الله ثالث ثلثة وما من اله الا اله وحد وان لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب اليم'),
(743, 5, 74, 'اَفَلَا يَتُوبُونَ اِلَى اللّٰهِ وَيَسْتَغْفِرُونَهُۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'E fe la yetubune ilallahi ve yestagfiruneh vallahu gafurun rahim.', 'Hala Allah\'a tevbe edip mağfiret[1] dilemiyorlar mı? Oysaki Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'افلا يتوبون الي الله ويستغفرونه والله غفور رحيم'),
(744, 5, 75, 'مَا الْمَس۪يحُ ابْنُ مَرْيَمَ اِلَّا رَسُولٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُۜ وَاُمُّهُ صِدّ۪يقَةٌۜ كَانَا يَأْكُلَانِ الطَّعَامَۜ اُنْظُرْ كَيْفَ نُبَيِّنُ لَهُمُ الْاٰيَاتِ ثُمَّ انْظُرْ اَنّٰى يُؤْفَكُونَ', 'Melmesihubnu meryeme illa resul, kad halet min kablihir rusul ve ummuhu sıddikah kana ye\'kulanit taam unzur keyfe nubeyyinu lehumul ayati summenzur enna yu\'fekun.', 'İyi bilin ki,  Meryem oğlu Mesih,  yalnızca bir resuldür. Ondan önce de resuller gelip geçti. O\'nun annesi çok dürüsttür. İkisi de diğer insanlar gibi yer,  içerlerdi.[1] Onlar için ayetleri[2] nasıl açıkladığımıza bak ve sonra nasıl döndürüldüklerini[3] gör.', 'ما المسيح ابن مريم الا رسول قد خلت من قبله الرسل وامه صديقة كانا ياكلان الطعام انظر كيف نبين لهم الايت ثم انظر اني يوفكون'),
(745, 5, 76, 'قُلْ اَتَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَا يَمْلِكُ لَكُمْ ضَراًّ وَلَا نَفْعاًۜ وَاللّٰهُ هُوَ السَّم۪يعُ الْعَل۪يمُ', 'Kul e ta\'budune min dunillahi ma la yemliku lekum darran ve la nef\'a vallahu huves semiul alim.', 'De ki: \"Allah\'ı bırakıp,  size bir yarar sağlamaya da bir zarar vermeye de gücü yetmeyen şeylere mi kulluk yapıyorsunuz? Allah,  Her Şeyi Duyan,  Her Şeyi Bilen\'dir.\"', 'قل اتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم'),
(746, 5, 77, 'قُلْ يَٓا اَهْلَ الْكِتَابِ لَا تَغْلُوا ف۪ي د۪ينِكُمْ غَيْرَ الْحَقِّ وَلَا تَتَّبِعُٓوا اَهْوَٓاءَ قَوْمٍ قَدْ ضَلُّوا مِنْ قَبْلُ وَاَضَلُّوا كَث۪يراً وَضَلُّوا عَنْ سَوَٓاءِ السَّب۪يلِ۟', 'Kul ya ehlel kitabi, la taglu fi dinikum gayral hakkı ve la tettebi\'u ehvae kavmin kad dallu min kablu ve edallu kesiran ve dallu an sevais sebil.', 'De ki: \"Ey Kitap Ehli! Gerçeğin dışına çıkarak,  dininizin sınırlarını ihlal etmeyin. Daha önce sapan ve birçoğunu saptıran ve düzgün yoldan sapmış olan bir halkın hevasına uymayın.', 'قل ياهل الكتب لا تغلوا في دينكم غير الحق ولا تتبعوا اهوا قوم قد ضلوا من قبل واضلوا كثيرا وضلوا عن سوا السبيل'),
(747, 5, 78, 'لُعِنَ الَّذ۪ينَ كَفَرُوا مِنْ بَن۪ٓي اِسْرَٓائ۪لَ عَلٰى لِسَانِ دَاوُ۫دَ وَع۪يسَى ابْنِ مَرْيَمَۜ ذٰلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ', 'Luinellezine keferu min beni israile ala lisani davude ve isebni meryem zalike bima asav ve kanu ya\'tedun.', 'İsrailoğulları\'ndan Kafir olan kimseler,  asi olmaları ve haddi aşmaları nedeniyle,  Davud\'un ve Meryem oğlu İsa\'nın diliyle lanetlendiler.', 'لعن الذين كفروا من بني اسريل علي لسان داود وعيسي ابن مريم ذلك بما عصوا وكانوا يعتدون'),
(748, 5, 79, 'كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُۜ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ', 'Kanu la yetenahevne an munkerin fealuh lebi\'se ma kanu yef\'alun.', 'Yaptıkları kötü şeylerde,  birbirlerini uyarmıyorlardı. Gerçekten yapmakta oldukları şey ne kadar çirkindi.', 'كانوا لا يتناهون عن منكر فعلوه لبيس ما كانوا يفعلون'),
(749, 5, 80, 'تَرٰى كَث۪يراً مِنْهُمْ يَتَوَلَّوْنَ الَّذ۪ينَ كَفَرُواۜ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ اَنْفُسُهُمْ اَنْ سَخِطَ اللّٰهُ عَلَيْهِمْ وَفِي الْعَذَابِ هُمْ خَالِدُونَ', 'Tera kesiran minhum yetevellevnellezine keferu lebi\'se ma kaddemet lehum enfusuhum en sehıtallahu aleyhim ve fil azabi hum halidun.', 'Onlardan çoğunun,  Kafirleri veli edindiklerini görürsün. Nefislerinin kendileri için sunduğu şey ne kötüdür. Allah,  onlara gazap etmiştir ve onlar sürekli azapta kalacaklardır.', 'تري كثيرا منهم يتولون الذين كفروا لبيس ما قدمت لهم انفسهم ان سخط الله عليهم وفي العذاب هم خلدون'),
(750, 5, 81, 'وَلَوْ كَانُوا يُؤْمِنُونَ بِاللّٰهِ وَالنَّبِيِّ وَمَٓا اُنْزِلَ اِلَيْهِ مَا اتَّخَذُوهُمْ اَوْلِيَٓاءَ وَلٰكِنَّ كَث۪يراً مِنْهُمْ فَاسِقُونَ', 'Ve lev kanu yu\'minune billahi ven nebiyyi ve ma unzile ileyhi mettehazuhum evliyae ve lakinne kesiren minhum fasikun.', 'Eğer onlar,  Allah\'a,  Nebi\'ye ve ona indirilene iman etselerdi,  onları evliya edinmezlerdi. Fakat onlardan pek çoğu fasıktır.', 'ولو كانوا يومنون بالله والنبي وما انزل اليه ما اتخذوهم اوليا ولكن كثيرا منهم فسقون'),
(751, 5, 82, 'لَتَجِدَنَّ اَشَدَّ النَّاسِ عَدَاوَةً لِلَّذ۪ينَ اٰمَنُوا الْيَهُودَ وَالَّذ۪ينَ اَشْرَكُواۚ وَلَتَجِدَنَّ اَقْرَبَهُمْ مَوَدَّةً لِلَّذ۪ينَ اٰمَنُوا الَّذ۪ينَ قَالُٓوا اِنَّا نَصَارٰىۜ ذٰلِكَ بِاَنَّ مِنْهُمْ قِسّ۪يس۪ينَ وَرُهْبَاناً وَاَنَّهُمْ لَا يَسْتَكْبِرُونَ', 'Le tecidenne eşedden nasi adaveten lillezine amenul yehude vellezine eşraku, ve le tecidenne akrabehum meveddeten lillezine amenullezine kalu inna nasara zalike bi enne minhum kıssisine ve ruhbanen ve ennehum la yestekbirun.', 'İman eden kimselere düşmanlık yönünden insanların en çetininin Yahudiler[1] ve müşrikler olduğunu görürsün. Ve yine iman eden kimseler için sevgice daha yakın olanların da biz Nasarayiz[2] diyenler olduğunu göreceksin. Bunun nedeni,  kuşkusuz bunların içinde gerçekten büyüklük taslamayan keşişler[3] ve rahipler olmasıdır.', 'لتجدن اشد الناس عدوة للذين امنوا اليهود والذين اشركوا ولتجدن اقربهم مودة للذين امنوا الذين قالوا انا نصري ذلك بان منهم قسيسين ورهبانا وانهم لا يستكبرون'),
(752, 5, 83, 'وَاِذَا سَمِعُوا مَٓا اُنْزِلَ اِلَى الرَّسُولِ تَرٰٓى اَعْيُنَهُمْ تَف۪يضُ مِنَ الدَّمْعِ مِمَّا عَرَفُوا مِنَ الْحَقِّۚ يَقُولُونَ رَبَّنَٓا اٰمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِد۪ينَ', 'Ve iza semiu ma unzile ilerresuli tera a\'yunehum tefidu mined dem\'ı mimma arefu minel hakk, yekulune rabbena amenna fektubna meaş şahidin.', 'Resul\'e indirileni duydukları zaman,  gerçeği anlamalarından dolayı onların gözlerinin yaşla dolup taştığını görürsün. Derler ki: \"Ey Rabb\'imiz! İman ettik,  öyleyse bizi şahitlerle beraber yaz.\"', 'واذا سمعوا ما انزل الي الرسول تري اعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا امنا فاكتبنا مع الشهدين'),
(753, 5, 84, 'وَمَا لَنَا لَا نُؤْمِنُ بِاللّٰهِ وَمَا جَٓاءَنَا مِنَ الْحَقِّۙ وَنَطْمَعُ اَنْ يُدْخِلَنَا رَبُّنَا مَعَ الْقَوْمِ الصَّالِح۪ينَ', 'Ve ma lena la nu\'minu billahi ve ma caena minel hakkı ve natmeu en yudhılena rabbuna meal kavmis salihin.', '\"Ve bize ne oluyor ki,  Allah\'a ve bize gelen gerçeğe iman etmeyelim: Rabb\'imizin bizi iyi kimseler topluluğuna dahil etmesi umut ve beklentisi içinde iken.\"', 'وما لنا لا نومن بالله وما جانا من الحق ونطمع ان يدخلنا ربنا مع القوم الصلحين'),
(754, 5, 85, 'فَاَثَابَهُمُ اللّٰهُ بِمَا قَالُوا جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ وَذٰلِكَ جَزَٓاءُ الْمُحْسِن۪ينَ', 'Fe esabehumullahu bima kalu cennatin tecri min tahtihel enharu halidine fiha ve zalike cezaul muhsinin.', 'Böyle söylemelerinden dolayı Allah da karşılık olarak içinden ırmaklar akan Cennetlerle ödüllendirdi. Onlar,  orada sürekli kalacaklardır. İşte muhsinlere[1] verilen karşılık budur.', 'فاثبهم الله بما قالوا جنت تجري من تحتها الانهر خلدين فيها وذلك جزا المحسنين'),
(755, 5, 86, 'وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَٓا اُو۬لٰٓئِكَ اَصْحَابُ الْجَح۪يمِ۟', 'Vellezine keferu ve kezzebu bi ayatina ulaike ashabul cahim.', 'Kafir olup ayetlerimizi yalanlayan kimseler,  işte onlar Cehennem halkıdırlar.', 'والذين كفروا وكذبوا بايتنا اوليك اصحب الجحيم'),
(756, 5, 87, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَٓا اَحَلَّ اللّٰهُ لَكُمْ وَلَا تَعْتَدُواۜ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُعْتَد۪ينَ', 'Ya eyyuhellezine amenu la tuharrimu tayyibati ma ehallallahu lekum ve la ta\'tedu innallahe la yuhibbul mu\'tedin.', 'Ey iman edenler! Allah\'ın size helal kıldığı tayyibat[1] olan şeyleri haram saymayın. Haddi aşmayın.[2] Allah,  haddi aşanları sevmez.', 'يايها الذين امنوا لا تحرموا طيبت ما احل الله لكم ولا تعتدوا ان الله لا يحب المعتدين'),
(757, 5, 88, 'وَكُلُوا مِمَّا رَزَقَكُمُ اللّٰهُ حَلَالاً طَيِّباًۖ وَاتَّقُوا اللّٰهَ الَّـذ۪ٓي اَنْتُمْ بِه۪ مُؤْمِنُونَ', 'Ve kulu mimma razakakumullahu halalen tayyiben vettekullahellezi entum bihi mu\'minun.', 'Allah\'ın sizi rızıklandırdığı şeylerin helal ve tayyib olanlarından yiyin. İman ettiğiniz Allah\'a karşı takvalı olun.', 'وكلوا مما رزقكم الله حللا طيبا واتقوا الله الذي انتم به مومنون'),
(758, 5, 89, 'لَا يُؤَاخِذُكُمُ اللّٰهُ بِاللَّغْوِ ف۪ٓي اَيْمَانِكُمْ وَلٰكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْاَيْمَانَۚ فَكَفَّارَتُهُٓ اِطْعَامُ عَشَرَةِ مَسَاك۪ينَ مِنْ اَوْسَطِ مَا تُطْعِمُونَ اَهْل۪يكُمْ اَوْ كِسْوَتُهُمْ اَوْ تَحْر۪يرُ رَقَبَةٍۜ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلٰثَةِ اَيَّامٍۜ ذٰلِكَ كَفَّارَةُ اَيْمَانِكُمْ اِذَا حَلَفْتُمْۜ وَاحْفَظُٓوا اَيْمَانَكُمْۜ كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمْ اٰيَاتِه۪ لَعَلَّكُمْ تَشْكُرُونَ', 'La yuahizukumullahu bil lagvi fi eymanikum ve lakin yuahizukum bima akkadtumul eyman, fe keffaretuhu it\'amu aşereti mesakine min evsatı ma tut\'ımune ehlikum ev kisvetuhum ev tahriru rakabeh fe men lem yecid fe sıyamu selaseti eyyam zalike keffaretu eymanikum iza haleftum vahfezu eymanekum kezalike yubeyyinullahu lekum ayatihi leallekum teşkurun.', 'Allah,  kasıtsız[1] yeminlerinizden dolayı sizi sorumlu tutmaz,  ancak bilinçli olarak ettiğiniz yeminlerden dolayı sorumlu tutar. Bunun[2] bedeli ailenize yedirdiğinizin ortalaması üzerinden on yoksulu yedirmek veya onları giydirmek veya bir rekabeyi[3] özgürlüğüne kavuşturmaktır. Fakat bunlara gücü yetmeyene üç gün siyam[4] vardır. Bozduğunuz yeminlerinizin bedeli budur. Yeminlerinizi bozmayın. Allah,  size ayetlerini[5] böyle açıklıyor. Umulur ki şükredersiniz.[6]', 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشرة مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبة فمن لم يجد فصيام ثلثة ايام ذلك كفرة ايمنكم اذا حلفتم واحفظوا ايمنكم كذلك يبين الله لكم ايته لعلكم تشكرون'),
(759, 5, 90, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْاَنْصَابُ وَالْاَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'Ya eyyuhellezine amenu innemel hamru vel meysiru vel ensabu vel ezlamu ricsun min ameliş şeytani fectenibuhu leallekum tuflihun.', 'Ey iman edenler! Hamr[1],  kumar,  dikili taşlar[2] ve şans oyunları[3] şeytan işi birer pisliktir. Bunlardan kaçının ki kurtuluşa eresiniz.', 'يايها الذين امنوا انما الخمر والميسر والانصاب والازلم رجس من عمل الشيطن فاجتنبوه لعلكم تفلحون'),
(760, 5, 91, 'اِنَّمَا يُر۪يدُ الشَّيْطَانُ اَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَٓاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللّٰهِ وَعَنِ الصَّلٰوةِۚ فَهَلْ اَنْتُمْ مُنْتَهُونَ', 'İnnema yuriduş şeytanu en yukia beynekumul adavete vel bagdae fil hamri vel meysiri ve yasuddekum an zikrillahi ve anis salah, fe hel entum muntehun.', 'Şeytan,  hamr ve kumarla aranıza düşmanlık ve kin sokmak; sizi Allah\'ın öğütlerini dinlemekten ve salattan[1] uzaklaştırmak ister. O halde bunlardan vazgeçmeyecek misiniz?', 'انما يريد الشيطن ان يوقع بينكم العدوة والبغضا في الخمر والميسر ويصدكم عن ذكر الله وعن الصلوة فهل انتم منتهون'),
(761, 5, 92, 'وَاَط۪يعُوا اللّٰهَ وَاَط۪يعُوا الرَّسُولَ وَاحْذَرُواۚ فَاِنْ تَوَلَّيْتُمْ فَاعْلَمُٓوا اَنَّمَا عَلٰى رَسُولِنَا الْبَلَاغُ الْمُب۪ينُ', 'Ve etiullahe ve etiur resule vahzeru, fe in tevelleytum fa\'lemu ennema ala resulinel belagul mubin.', 'Ve Allah\'a itaat edin ve Resul\'e itaat edin[1]. Sakının.[2] Eğer bu buyrukları dinlemezseniz,  bilin ki resulümüze düşen açıkça duyurmaktır.', 'واطيعوا الله واطيعوا الرسول واحذروا فان توليتم فاعلموا انما علي رسولنا البلغ المبين'),
(762, 5, 93, 'لَيْسَ عَلَى الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ ف۪يمَا طَعِمُٓوا اِذَا مَا اتَّقَوْا وَاٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ ثُمَّ اتَّقَوْا وَاٰمَنُوا ثُمَّ اتَّقَوْا وَاَحْسَنُواۜ وَاللّٰهُ يُحِبُّ الْمُحْسِن۪ينَ۟', 'Leyse alellezine amenu ve amilus salihati cunahun fima taimu iza mettekav ve amenu ve amilus salihati summettekav ve amenu summettekav ve ahsenu vallahu yuhibbul muhsinin.', 'İman eden ve salihatı yapan[1] kimselere; İman edip salihatı yaptıkları sürece takva[2] sahipleri değilken yiyip içtiklerinden dolayı bir sorumluluk yoktur. Sonra takvalı olup,  iman ettikleri,  sonra takvalı olup iyilik yaptıkları takdirde,  bilin ki Allah,  muhsin[3] olanları sever.', 'ليس علي الذين امنوا وعملوا الصلحت جناح فيما طعموا اذا ما اتقوا وامنوا وعملوا الصلحت ثم اتقوا وامنوا ثم اتقوا واحسنوا والله يحب المحسنين'),
(763, 5, 94, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَيَبْلُوَنَّكُمُ اللّٰهُ بِشَيْءٍ مِنَ الصَّيْدِ تَنَالُهُٓ  اَيْد۪يكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ اللّٰهُ مَنْ يَخَافُهُ بِالْغَيْبِۚ فَمَنِ اعْتَدٰى بَعْدَ ذٰلِكَ فَلَهُ عَذَابٌ اَل۪يمٌ', 'Ya eyyuhellezine amenu le yebluvennekumullahu bi şey\'in mines saydı tenaluhu eydikum ve rimahukum li ya\'lemallahu men yahafuhu bil gayb, fe meni\'teda ba\'de zalike fe lehu azabun elim.', 'Ey iman edenler! Allah,  ellerinizin ve oklarınızın ulaşabildiği bir kısım avla sizi dener. Ki görünmeyen yerde kendisine karşı gelmekten sakınanların kimler olduğunu bilmek için. Bundan sonra kim haddi aşarsa onun için elem verici bir azap vardır.', 'يايها الذين امنوا ليبلونكم الله بشي من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدي بعد ذلك فله عذاب اليم'),
(764, 5, 95, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَقْتُلُوا الصَّيْدَ وَاَنْتُمْ حُرُمٌۜ وَمَنْ قَتَلَهُ مِنْكُمْ مُتَعَمِّداً فَجَزَٓاءٌ مِثْلُ مَا قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِه۪ ذَوَا عَدْلٍ مِنْكُمْ هَدْياً بَالِغَ الْكَعْبَةِ اَوْ كَفَّارَةٌ طَعَامُ مَسَاك۪ينَ اَوْ عَدْلُ ذٰلِكَ صِيَاماً لِيَذُوقَ وَبَالَ اَمْرِه۪ۜ عَفَا اللّٰهُ عَمَّا سَلَفَۜ وَمَنْ عَادَ فَيَنْتَقِمُ اللّٰهُ مِنْهُۜ وَاللّٰهُ عَز۪يزٌ ذُوانْتِقَامٍ', 'Ya eyyuhellezine amenu la taktulus sayde ve entum hurum ve men katelehu minkum muteammiden fe cezaun mislu ma katele min en neami yahkumu bihi zeva adlin minkum hedyen baligal ka\'beti ev keffaratun taamu mesakine ev adlu zalike siyamen li yezuka vebale emrih afallahu amma selef ve men ade fe yentakimullahu minh vallahu azizun zuntikam.', 'Ey iman edenler! İhramlıyken[1] av hayvanı öldürmeyin. Sizden kim bile bile öldürürse,  karşılık olarak yapacağı şey,  sizden adil iki kişinin kararıyla,  avlanılan şeye denk Kabe\'ye ulaşacak hediye[2] göndermek veya yoksulları doyurmak veya buna denk siyamdır[3] ki bu yaptığı işin vebalini tatması içindir. Allah geçmiştekini affetti. Kim aynı suçu tekrar ederse,  Allah onun hesabını sorar. Ve Allah,  Mutlak Üstün Olan\'dır,  Hesap Sorucu\'dur.', 'يايها الذين امنوا لا تقتلوا الصيد وانتم حرم ومن قتله منكم متعمدا فجزا مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بلغ الكعبة او كفرة طعام مسكين او عدل ذلك صياما ليذوق وبال امره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام'),
(765, 5, 96, 'اُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعاً لَكُمْ وَلِلسَّيَّارَةِۚ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُماًۜ وَاتَّقُوا اللّٰهَ الَّـذ۪ٓي اِلَيْهِ تُحْشَرُونَ', 'Uhille lekum saydul bahri ve taamuhu metaan lekum ve lis seyyarah, ve hurrime aleykum saydul berri ma dumtum huruma vettekullahellezi ileyhi tuhşerun.', 'Deniz avı ve onu yemek ve ondan geçim temin etmek size ve yolculukta olanlara helal kılındı. Ve ihramlı olduğunuz süre içinde kara avı size haram kılındı. Huzuruna toplanacağınız Allah\'a karşı takva sahibi olun.', 'احل لكم صيد البحر وطعامه متعا لكم وللسيارة وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي اليه تحشرون'),
(766, 5, 97, 'جَعَلَ اللّٰهُ الْكَعْبَةَ الْبَيْتَ الْحَرَامَ قِيَاماً لِلنَّاسِ وَالشَّهْرَ الْحَرَامَ وَالْهَدْيَ وَالْقَلَٓائِدَۜ ذٰلِكَ لِتَعْلَمُٓوا اَنَّ اللّٰهَ يَعْلَمُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ وَاَنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Cealallahul ka\'betel beytel harame kıyamen lin nasi veş şehral harame vel hedye vel kalaid zalike li ta\'lemu ennellahe ya\'lemu ma fis semavati ve ma fil ardı ve ennellahe bikulli şey\'in alim.', 'Allah,  Beyt-i Haram[1] olan Kabe\'yi ve o haram olan ayı[2] ve hediye kurbanlığı[3] ve gerdanlıkları[4] insanlar için kıyam[5] yaptı. Bilesiniz ki Allah,  göklerdekini ve yerdekini bilmektedir. Kuşkusuz,  Allah,  Her Şeyi Bilen\'dir.', 'جعل الله الكعبة البيت الحرام قيما للناس والشهر الحرام والهدي والقليد ذلك لتعلموا ان الله يعلم ما في السموت وما في الارض وان الله بكل شي عليم'),
(767, 5, 98, 'اِعْلَمُٓوا اَنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ وَاَنَّ اللّٰهَ غَفُورٌ رَح۪يمٌۜ', 'I\'lemu ennellahe şedidul ikabi ve ennellahe gafurun rahim.', 'İyi bilin ki; Allah,  Cezası Çok Şiddetli Olan\'dır ve kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'اعلموا ان الله شديد العقاب وان الله غفور رحيم'),
(768, 5, 99, 'مَا عَلَى الرَّسُولِ اِلَّا الْبَلَاغُۜ وَاللّٰهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'Ma aler resuli illel belag vallahu ya\'lemu ma tubdune ve ma tektumun.', 'Resule düşen,  yalnızca çağrıda bulunmaktır. Açığa vurduğunuzu da gizlediğinizi de Allah bilir.', 'ما علي الرسول الا البلغ والله يعلم ما تبدون وما تكتمون'),
(769, 5, 100, 'قُلْ لَا يَسْتَوِي الْخَب۪يثُ وَالطَّيِّبُ وَلَوْ اَعْجَبَكَ كَـثْرَةُ الْخَب۪يثِۚ فَاتَّقُوا اللّٰهَ يَٓا اُو۬لِي الْاَلْبَابِ لَعَلَّكُمْ تُفْلِحُونَ۟', 'Kul la yestevil habisu vet tayyibu ve lev a\'cebeke kesretul habis, fettekullahe ya ulil elbabi leallekum tuflihun.', '\"De ki:\" Habis[1] olanla tayyib[2] olan bir değildir. Velev ki habis olanın çokluğu[3] hoşuna gitse de. Ey selim akıl[4] sahipleri! Allah\'a karşı takvalı olun ki kurtuluşa eresiniz.', 'قل لا يستوي الخبيث والطيب ولو اعجبك كثرة الخبيث فاتقوا الله ياولي الالبب لعلكم تفلحون'),
(770, 5, 101, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَسْـَٔلُوا عَنْ اَشْيَٓاءَ اِنْ تُبْدَ لَكُمْ تَسُؤْكُمْۚ وَاِنْ تَسْـَٔلُوا عَنْهَا ح۪ينَ يُنَزَّلُ الْقُرْاٰنُ تُبْدَ لَكُمْۜ عَفَا اللّٰهُ عَنْهَاۜ وَاللّٰهُ غَفُورٌ حَل۪يمٌ', 'Ya eyyuhellezine amenu la tes\'elu an eşyae in tubde lekum tesu\'kum, ve in tes\'elu anha hine yunezzelul kur\'anu tubde lekum afallahu anha vallahu gafurun halim.', 'Ey iman edenler! Her şeyi sormayın! Açıklandığında sizi zor duruma düşürecek şeyler vardır. Oysaki Kur\'an indirildiği anda o şeyleri sorarsanız size açıklanır. Allah,  onlardan vazgeçmiştir[1]. Allah,  Çok Bağışlayıcı\'dır,  Çok Hoş Görülü\'dür.', 'يايها الذين امنوا لا تسلوا عن اشيا ان تبد لكم تسوكم وان تسلوا عنها حين ينزل القران تبد لكم عفا الله عنها والله غفور حليم'),
(771, 5, 102, 'قَدْ سَاَلَهَا قَوْمٌ مِنْ قَبْلِكُمْ ثُمَّ اَصْبَحُوا بِهَا كَافِر۪ينَ', 'Kad seeleha kavmun min kablikum summe asbahu biha kafirin.', 'Gerçekten,  sizden önce de onları bir halk sormuştu da sonra onları inkar edenler olmuşlardı.', 'قد سالها قوم من قبلكم ثم اصبحوا بها كفرين'),
(772, 5, 103, 'مَا جَعَلَ اللّٰهُ مِنْ بَح۪يرَةٍ وَلَا سَٓائِبَةٍ وَلَا وَص۪يلَةٍ وَلَا حَامٍۙ وَلٰكِنَّ الَّذ۪ينَ كَفَرُوا يَفْتَرُونَ عَلَى اللّٰهِ الْكَذِبَۜ وَاَكْثَرُهُمْ لَا يَعْقِلُونَ', 'Ma cealallahu min bahiretin ve la saibetin ve la vasiletin ve la hamin ve lakinnellezine keferu yefterune alallahi kezib ve ekseruhum la ya\'kılun.', 'Allah,  ne \"Bahire\" ne \"Saibe\" ne \"Vasile\" ne de \"Ham\"[1] diye bir şeyi meşru kıldı. Fakat Kafirler yalan söyleyerek Allah\'a iftira ediyorlar. Ve onların çoğu akıllarını kullanmıyorlar.[2]', 'ما جعل الله من بحيرة ولا سايبة ولا وصيلة ولا حام ولكن الذين كفروا يفترون علي الله الكذب واكثرهم لا يعقلون'),
(773, 5, 104, 'وَاِذَا ق۪يلَ لَهُمْ تَعَالَوْا اِلٰى مَٓا اَنْزَلَ اللّٰهُ وَاِلَى الرَّسُولِ قَالُوا حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ اٰبَٓاءَنَاۜ اَوَلَوْ كَانَ اٰبَٓاؤُ۬هُمْ لَا يَعْلَمُونَ شَيْـٔاً وَلَا يَهْتَدُونَ', 'Ve iza kile lehum tealev ila ma enzelallahu ve iler resuli kalu hasbuna ma vecedna aleyhi abaena e ve lev kane abauhum la ya\'lemune şey\'en ve la yehtedun.', 'Onlara,  Allah\'ın indirdiğine ve resule gelin dendiği zaman,  \"Atalarımızı üzerinde bulduğumuz şey bize yeter.\" dediler. Peki ya ataları bir şey bilmeyen ve doğru yolda olmayan kimselerse?', 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول قالوا حسبنا ما وجدنا عليه ابانا اولو كان اباوهم لا يعلمون شيا ولا يهتدون'),
(774, 5, 105, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا عَلَيْكُمْ اَنْفُسَكُمْۚ لَا يَضُرُّكُمْ مَنْ ضَلَّ اِذَا اهْتَدَيْتُمْۜ اِلَى اللّٰهِ مَرْجِعُكُمْ جَم۪يعاً فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ya eyyuhellezine amenu aleykum enfusekum, la yadurrukum men dalle izehtedeytum ilallahi merciukum cemian fe yunebbiukum bima kuntum ta\'melun.', 'Ey iman edenler! Siz,  kendinizden sorumlusunuz. Eğer siz doğru yol üzerindeyseniz,  sapan kimseler size zarar veremez. Dönüşünüz Allah\'adır. Yaptığınız şeyleri size haber verecektir.', 'يايها الذين امنوا عليكم انفسكم لا يضركم من ضل اذا اهتديتم الي الله مرجعكم جميعا فينبيكم بما كنتم تعملون'),
(775, 5, 106, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا شَهَادَةُ بَيْنِكُمْ اِذَا حَضَرَ اَحَدَكُمُ الْمَوْتُ ح۪ينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ اَوْ اٰخَرَانِ مِنْ غَيْرِكُمْ اِنْ اَنْتُمْ ضَرَبْتُمْ فِي الْاَرْضِ فَاَصَابَتْكُمْ مُص۪يبَةُ الْمَوْتِۜ تَحْبِسُونَهُمَا مِنْ بَعْدِ الصَّلٰوةِ فَيُقْسِمَانِ بِاللّٰهِ اِنِ ارْتَبْتُمْ لَا نَشْتَر۪ي بِه۪ ثَمَناً وَلَوْ كَانَ ذَا قُرْبٰىۙ وَلَا نَكْتُمُ شَهَادَةَ اللّٰهِ اِنَّٓا اِذاً لَمِنَ الْاٰثِم۪ينَ', 'Ya eyyuhellezine amenu şehadetu beynikum iza hadara ehadekumul mevtu hinel vasiyyetisnani zeva adlin minkum ev aharani min gayrikum in entum darabtum fil ardı fe esabetkum musibetul mevt tahbisunehuma min ba\'dis salati fe yuksimani billahi in irtebtum la neşteri bihi semenen ve lev kane za kurba ve la nektumu şehadetallahi inna izen le minel asimin.', 'Ey iman edenler! Eğer birinizde ölüm belirtileri ortaya çıkarsa,  vasiyet anında içinizden adalet sahibi iki kişi aranızda tanıklık etsin. Veya yeryüzünde yolculuk ederken[1] ölüm size isabet ederse,  sizden olmayan iki kişi tanıklık etsin. Eğer kuşku duyarsanız o iki kişiyi salattan[2] sonra alıkoyun. \"Yakınımız da olsa tanıklığımızı hiçbir bedele satmadık ve Allah\'ın tanıklığını gizlemedik. Yoksa öyle yaparsak,  günahkarlardan oluruz.\" diye Allah\'a yemin etsinler.', 'يايها الذين امنوا شهدة بينكم اذا حضر احدكم الموت حين الوصية اثنان ذوا عدل منكم او اخران من غيركم ان انتم ضربتم في الارض فاصبتكم مصيبة الموت تحبسونهما من بعد الصلوة فيقسمان بالله ان ارتبتم لا نشتري به ثمنا ولو كان ذا قربي ولا نكتم شهدة الله انا اذا لمن الاثمين'),
(776, 5, 107, 'فَاِنْ عُثِرَ عَلٰٓى اَنَّهُمَا اسْتَحَقَّٓا اِثْماً فَاٰخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ الَّذ۪ينَ اسْتَحَقَّ عَلَيْهِمُ الْاَوْلَيَانِ فَيُقْسِمَانِ بِاللّٰهِ لَشَهَادَتُـنَٓا اَحَقُّ مِنْ شَهَادَتِهِمَا وَمَا اعْتَدَيْنَاۘ اِنَّٓا اِذاً لَمِنَ الظَّالِم۪ينَ', 'Fe in usire ala ennehumastehakka ismen fe aharani yekumani makamehuma minellezinestehakka aleyhimul evleyani fe yuksimani billahi le şehadetuna ehakku min şehadetihima ve ma\'tedeyna, inna izen le minez zalimin.', 'Eğer o ikisinin günah işledikleri anlaşılırsa,  onların yerine mirasa hak sahibi olanlardan iki kişi geçer: \"Bizim tanıklığımız o ikisinin tanıklığından daha doğrudur ve biz haddi aşmadık,  öyle olsaydı kuşkusuz biz elbette zalimlerden oluruz.\" diye Allah\'a yemin ederler.', 'فان عثر علي انهما استحقا اثما فاخران يقومان مقامهما من الذين استحق عليهم الاولين فيقسمان بالله لشهدتنا احق من شهدتهما وما اعتدينا انا اذا لمن الظلمين'),
(777, 5, 108, 'ذٰلِكَ اَدْنٰٓى اَنْ يَأْتُوا بِالشَّهَادَةِ عَلٰى وَجْهِهَٓا اَوْ يَخَافُٓوا اَنْ تُرَدَّ اَيْمَانٌ بَعْدَ اَيْمَانِهِمْۜ وَاتَّقُوا اللّٰهَ وَاسْمَعُواۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْفَاسِق۪ينَ۟', 'Zalike edna en ye\'tu biş şehadeti ala vechiha ev yehafuen turadde eymanun ba\'de eymanihim vettekullahe vesmeu vallahu la yehdil kavmel fasikin.', 'İşte bu,  tanıklığın tam anlamıyla yerine getirilmesi; yoksa yeminden sonra yeminlerinin başkalarının yeminleriyle geri çevrilmesinden korkulması bakımından daha uygundur. Allah için takvalı olun ve dinleyin. Allah,  fasık olan toplumu doğru yola iletmez.', 'ذلك ادني ان ياتوا بالشهدة علي وجهها او يخافوا ان ترد ايمن بعد ايمنهم واتقوا الله واسمعوا والله لا يهدي القوم الفسقين'),
(778, 5, 109, 'يَوْمَ يَجْمَعُ اللّٰهُ الرُّسُلَ فَيَقُولُ مَاذَٓا اُجِبْتُمْۜ قَالُوا لَا عِلْمَ لَنَاۜ اِنَّكَ اَنْتَ عَلَّامُ الْغُيُوبِ', 'Yevme yecmeullahur rusule fe yekulu maza ucibtum kalu la ilme lena inneke ente allamul guyub.', 'Allah,  resulleri topladığı gün,  \"Nasıl karşılandınız der?\" \"Bizim bir bilgimiz yok,  doğrusu gaybleri[1] bilen ancak Sen\'sin.\" derler.', 'يوم يجمع الله الرسل فيقول ماذا اجبتم قالوا لا علم لنا انك انت علم الغيوب'),
(779, 5, 110, 'اِذْ قَالَ اللّٰهُ يَا ع۪يسَى ابْنَ مَرْيَمَ اذْكُرْ نِعْمَت۪ي عَلَيْكَ وَعَلٰى وَالِدَتِكَۢ اِذْ اَيَّدْتُكَ بِرُوحِ الْقُدُسِ تُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلاًۚ وَاِذْ عَلَّمْتُكَ الْكِتَابَ وَالْحِكْمَةَ وَالتَّوْرٰيةَ وَالْاِنْج۪يلَۚ وَاِذْ تَخْلُقُ مِنَ الطّ۪ينِ كَـهَيْـَٔةِ الطَّيْرِ بِاِذْن۪ي فَتَنْفُخُ ف۪يهَا فَتَكُونُ طَيْراً بِاِذْن۪ي وَتُبْرِئُ الْاَكْمَهَ وَالْاَبْرَصَ بِاِذْن۪يۚ وَاِذْ تُخْرِجُ الْمَوْتٰى بِاِذْن۪يۚ وَاِذْ كَفَفْتُ بَن۪ٓي اِسْرَٓائ۪لَ عَنْكَ اِذْ جِئْتَهُمْ بِالْبَيِّنَاتِ فَقَالَ الَّذ۪ينَ كَفَرُوا مِنْهُمْ اِنْ هٰذَٓا اِلَّا سِحْرٌ مُب۪ينٌ', 'İz kalellahu ya isebne meryemezkur ni\'meti aleyke ve ala validetike iz eyyedtuke bi ruhil kudusi tukellimun nase fil mehdi ve kehl, ve iz allemtukel kitabe vel hikmete vet tevrate vel incil, ve iz tahluku minet tini ke hey\'etit tayri bi izni fe tenfuhu fiha fe tekunu tayran bi izni ve tubriul ekmehe vel ebrasa bi izni, ve iz tuhricul mevta bi izni, ve iz kefeftu beni israile anke iz ci\'tehum bil beyyinati fe kalellezine keferu minhum in haza illa sihrun mubin.', 'Allah,  \"Ey Meryem oğlu İsa! Senin ve annenin üzerinde olan nimetimi hatırla.\" Hani seni Kudus\'un Ruhu[1] ile desteklemiştim,  insanlarla beşikte[2] ve yetişkinlikte konuşuyordun. Ve hani sana Kitap\'ı,  Hikmet\'i,  Tevrat\'ı ve İncil\'i öğrettim. Ve hani Ben\'im iznimle[3] çamurdan kuş şeklinde bir şey tasarlıyordun ve ona üflüyordun,  Ben\'im iznimle hemen kuş oluyordu; kör olarak doğanı ve abrası[4] Ben\'im iznimle iyileştiriyordun. Hani Ben\'im iznimle ölüleri[5] çıkarıyordun. Hani İsrailoğulları\'nı senden uzaklaştırdım. Hani onlara apaçık beyyinelerle[6] geldiğinde,  onlardan Kafir olanlar,  \"Bu apaçık bir sihirden başka bir şey değildir.\" dediler.', 'اذ قال الله يعيسي ابن مريم اذكر نعمتي عليك وعلي ولدتك اذ ايدتك بروح القدس تكلم الناس في المهد وكهلا واذ علمتك الكتب والحكمة والتورية والانجيل واذ تخلق من الطين كهية الطير باذني فتنفخ فيها فتكون طيرا باذني وتبري الاكمه والابرص باذني واذ تخرج الموتي باذني واذ كففت بني اسريل عنك اذ جيتهم بالبينت فقال الذين كفروا منهم ان هذا الا سحر مبين'),
(780, 5, 111, 'وَاِذْ اَوْحَيْتُ اِلَى الْحَوَارِيّ۪نَ اَنْ اٰمِنُوا ب۪ي وَبِرَسُول۪يۚ قَالُٓوا اٰمَنَّا وَاشْهَدْ بِاَنَّـنَا مُسْلِمُونَ', 'Ve iz evhaytu ilel havariyyine en aminu bi ve bi resuli, kalu amenna veşhed bi ennena muslimun.', 'Havarilere,  Bana ve Ben\'im resulüme iman etmelerini vahyettim. \"İman ettik.\" dediler. Ve tanık ol ki kuşkusuz,  biz muslimleriz.[1]', 'واذ اوحيت الي الحوارين ان امنوا بي وبرسولي قالوا امنا واشهد باننا مسلمون'),
(781, 5, 112, 'اِذْ قَالَ الْحَوَارِيُّونَ يَا ع۪يسَى ابْنَ مَرْيَمَ هَلْ يَسْتَط۪يعُ رَبُّكَ اَنْ يُنَزِّلَ عَلَيْنَا مَٓائِدَةً مِنَ السَّمَٓاءِۜ قَالَ اتَّقُوا اللّٰهَ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'İz kalel havariyyune ya isebne meryeme hel yestetiu rabbuke en yunezzile aleyna maideten mines sema kalettekullahe in kuntum mu\'minin.', 'Hani havariler dedi: \"Ey Meryem oğlu İsa,  senin Rabb\'inin üzerimize gökten bir sofra indirmeye gücü yeter mi?\" \"Eğer inanıyorsanız Allah\'a karşı takvalı[1] olun\" dedi.', 'اذ قال الحواريون يعيسي ابن مريم هل يستطيع ربك ان ينزل علينا مايدة من السما قال اتقوا الله ان كنتم مومنين'),
(782, 5, 113, 'قَالُوا نُر۪يدُ اَنْ نَأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ اَنْ قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ الشَّاهِد۪ينَ', 'Kalu nuridu en ne\'kule minha ve tetmainne kulubuna ve na\'leme en kad sadaktena ve nekune aleyha mineş şahidin.', '\"Ondan yemeyi ve kalplerimizin iyice yatışmasını; senin bize doğru söylediğini bilmeyi ve buna doğrudan tanık olmayı istiyoruz.\" dediler.', 'قالوا نريد ان ناكل منها وتطمين قلوبنا ونعلم ان قد صدقتنا ونكون عليها من الشهدين'),
(783, 5, 114, 'قَالَ ع۪يسَى ابْنُ مَرْيَمَ اللّٰهُمَّ رَبَّنَٓا اَنْزِلْ عَلَيْنَا مَٓائِدَةً مِنَ السَّمَٓاءِ تَكُونُ لَنَا ع۪يداً لِاَوَّلِنَا وَاٰخِرِنَا وَاٰيَةً مِنْكَۚ وَارْزُقْنَا وَاَنْتَ خَيْرُ الرَّازِق۪ينَ', 'Kale isebnu meryemellahumme rabbena enzil aleyna maideten mines semai tekunu lena iden li evvelina ve ahirina ve ayeten mink, verzukna ve ente hayrur razikin.', 'Meryem oğlu İsa: \"Ey Allah\'ım,  Rabb\'imiz,  gökten üzerimize bir sofra indir. Ki o sofra bizim için; öncemiz ve sonramız için bir bayram olur ve Sen\'den de bir ayet.[1] Bizi rızıklandır ve Sen rızıklandıranların en hayırlısısın.\" dedi.', 'قال عيسي ابن مريم اللهم ربنا انزل علينا مايدة من السما تكون لنا عيدا لاولنا واخرنا واية منك وارزقنا وانت خير الرزقين'),
(784, 5, 115, 'قَالَ اللّٰهُ اِنّ۪ي مُنَزِّلُهَا عَلَيْكُمْۚ فَمَنْ يَكْفُرْ بَعْدُ مِنْكُمْ فَاِنّ۪ٓي اُعَذِّبُهُ عَذَاباً لَٓا اُعَذِّبُهُٓ  اَحَداً مِنَ الْعَالَم۪ينَ۟', 'Kalellahu inni munezziluha aleykum, fe men yekfur ba\'du minkum fe inni uazzibuhu azaben la uazzibuhu ehaden minel alemin.', 'Allah: \"Ben,  üzerinize onu indireceğim. Ama ondan sonra sizden kim Kafirlik ederse,  alemlerden hiç kimseyi azaplandırmadığım şekilde ona azap ederim.\" dedi.', 'قال الله اني منزلها عليكم فمن يكفر بعد منكم فاني اعذبه عذابا لا اعذبه احدا من العلمين'),
(785, 5, 116, 'وَاِذْ قَالَ اللّٰهُ يَا ع۪يسَى ابْنَ مَرْيَمَ ءَاَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُون۪ي وَاُمِّيَ اِلٰهَيْنِ مِنْ دُونِ اللّٰهِۜ قَالَ سُبْحَانَكَ مَا يَكُونُ ل۪ٓي اَنْ اَقُولَ مَا لَيْسَ ل۪ي بِحَقٍّۜ اِنْ كُنْتُ قُلْتُهُ فَقَدْ عَلِمْتَهُۜ تَعْلَمُ مَا ف۪ي نَفْس۪ي وَلَٓا اَعْلَمُ مَا ف۪ي نَفْسِكَۜ اِنَّكَ اَنْتَ عَلَّامُ الْغُيُوبِ', 'Ve iz kalellahu ya isebne meryeme e ente kulte lin nasittehizuni ve ummiye ilaheyni min dunillah kale subhaneke ma yekunu li en ekule ma leyse li bi hakk in kuntu kultuhu fe kad alimteh ta\'lemu ma fi nefsi ve la a\'lemu ma fi nefsik inneke ente allemul guyub.', 'Allah: \"Ey Meryem oğlu İsa! İnsanlara,  Allah\'tan başka beni ve annemi iki ilah edinin diye sen mi söyledin?\" buyurduğunda,  \"Sen yücesin.\" dedi. \"Gerçek olmayan bir şeyi söylemek haddim değil. Ben onu söyleseydim,  Sen onu bilirdin. Nefsimde olanı bilirsin,  ben ise Sen\'in zatında olanı bilmem. Sen,  gaipleri eksiksiz bilensin.\"', 'واذ قال الله يعيسي ابن مريم انت قلت للناس اتخذوني وامي الهين من دون الله قال سبحنك ما يكون لي ان اقول ما ليس لي بحق ان كنت قلته فقد علمته تعلم ما في نفسي ولا اعلم ما في نفسك انك انت علم الغيوب'),
(786, 5, 117, 'مَا قُلْتُ لَهُمْ اِلَّا مَٓا اَمَرْتَن۪ي بِه۪ٓ  اَنِ اعْبُدُوا اللّٰهَ رَبّ۪ي وَرَبَّكُمْۚ وَكُنْتُ عَلَيْهِمْ شَه۪يداً مَا دُمْتُ ف۪يهِمْۚ فَلَمَّا تَوَفَّيْتَن۪ي كُنْتَ اَنْتَ الرَّق۪يبَ عَلَيْهِمْۜ وَاَنْتَ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌ', 'Ma kultu lehum illa ma emerteni bihi eni\'budullahe rabbi ve rabbekum, ve kuntu aleyhim şehiden ma dumtu fihim, fe lemma teveffeyteni kunte enter rakibe aleyhim ve ente ala kulli şey\'in şehid.', '\"Onlara,  bana emrettiklerinden başkasını söylemedim. Benim ve sizin Rabb\'iniz olan Allah\'a kulluk edin dedim. Ben içlerinde olduğum sürece onlara gözetleyiciydim. Fakat beni vefat ettirince[1] onların üzerinde gözetleyici yalnızca Sen oldun. Ve Sen,  Her Şeye Tanıksın.\"', 'ما قلت لهم الا ما امرتني به ان اعبدوا الله ربي وربكم وكنت عليهم شهيدا ما دمت فيهم فلما توفيتني كنت انت الرقيب عليهم وانت علي كل شي شهيد'),
(787, 5, 118, 'اِنْ تُعَذِّبْهُمْ فَاِنَّهُمْ عِبَادُكَۚ وَاِنْ تَغْفِرْ لَهُمْ فَاِنَّكَ اَنْتَ الْعَز۪يزُ الْحَك۪يمُ', 'İn tuazzibhum fe innehum ibaduk, ve in tagfir lehum fe inneke entel azizul hakim.', '\"Eğer onlara azap edersen onlar Sen\'in kullarındır. Ve eğer onları bağışlarsan,  Mutlak Üstün Olan ve En İyi Hüküm Veren Sen\'sin.\"', 'ان تعذبهم فانهم عبادك وان تغفر لهم فانك انت العزيز الحكيم'),
(788, 5, 119, 'قَالَ اللّٰهُ هٰذَا يَوْمُ يَنْفَعُ الصَّادِق۪ينَ صِدْقُهُمْۜ لَهُمْ جَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوا عَنْهُۜ ذٰلِكَ الْفَوْزُ الْعَظ۪يمُ', 'Kalellahu haza yevmu yenfeus sadikine sıdkuhum, lehum cennatun tecri min tahtihel enharu halidine fiha ebeda radiyallahu anhum ve radu anh zalikel fevzul azim.', 'Allah: \"Bugün,  doğruluklarının doğrulara fayda sağlayacağı gündür.\" dedi. Onlar için,  içinden nehirlerin aktığı Cennetler vardır. Orada süresiz kalacaklar. Allah onlardan,  onlar da O\'ndan razı olmuşlardır. İşte büyük başarı budur.', 'قال الله هذا يوم ينفع الصدقين صدقهم لهم جنت تجري من تحتها الانهر خلدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك الفوز العظيم'),
(789, 5, 120, 'لِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا ف۪يهِنَّۜ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Lillahi mulkus semavati vel ardı ve ma fihin ve huve ala kulli şey\'in kadir.', 'Göklerin,  yerin ve bunların içindekilerin mülkü[1] Allah\'ındır. Ve O,  Her Şeye Gücü Yeten\'dir.', 'لله ملك السموت والارض وما فيهن وهو علي كل شي قدير'),
(790, 6, 1, 'اَلْحَمْدُ لِلّٰهِ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَۜ  ثُمَّ الَّذ۪ينَ كَفَرُوا بِرَبِّهِمْ يَعْدِلُونَ', 'Elhamdu lillahillezi halakas semavati vel arda ve cealez zulumati ven nur, summellezine keferu bi rabbihim ya\'dilun.', 'Hamd[1],  gökleri ve yeri yaratan,  karanlıkları ve aydınlığı var eden Allah\'a özgüdür. Yine de Kafirler[2] ilahlarını Rabb\'leriyle denk tutuyorlar.', 'الحمد لله الذي خلق السموت والارض وجعل الظلمت والنور ثم الذين كفروا بربهم يعدلون'),
(791, 6, 2, 'هُوَ الَّذ۪ي خَلَقَكُمْ مِنْ ط۪ينٍ ثُمَّ قَضٰٓى اَجَلاًۜ وَاَجَلٌ مُسَمًّى عِنْدَهُ ثُمَّ اَنْتُمْ تَمْتَرُونَ', 'Huvellezi halakakum min tinin summe kada ecela, ve ecelun musemmen ındehu summe entum temterun.', 'O,  sizi çamurdan yarattı. Sonra eceli[1] tayin etti. Ve adı belirlenmiş ecel O\'nun yanındadır.[2] Sonra da sizler hala kuşkulanıyorsunuz.', 'هو الذي خلقكم من طين ثم قضي اجلا واجل مسمي عنده ثم انتم تمترون'),
(792, 6, 3, 'وَهُوَ اللّٰهُ فِي السَّمٰوَاتِ وَفِي الْاَرْضِۜ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', 'Ve huvellahu fis semavati ve fil ard, ya\'lemu sirrakum ve cehrekum ve ya\'lemu ma teksibun.', 'Göklerde ve yerde Allah O\'dur. Gizlinizi de açığınızı da bilir. Ve ne kazandığınızı da bilir.', 'وهو الله في السموت وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون'),
(793, 6, 4, 'وَمَا تَأْت۪يهِمْ مِنْ اٰيَةٍ مِنْ اٰيَاتِ رَبِّهِمْ اِلَّا كَانُوا عَنْهَا مُعْرِض۪ينَ', 'Ve ma te\'tihim min ayetin min ayati rabbihim illa kanu anha mu\'rıdin.', 'Onlara,  ne zaman Rabb\'lerinin ayetlerinden bir ayet gelse illaki ondan yüz çevirirler.', 'وما تاتيهم من اية من ايت ربهم الا كانوا عنها معرضين'),
(794, 6, 5, 'فَقَدْ كَذَّبُوا بِالْحَقِّ لَمَّا جَٓاءَهُمْۜ فَسَوْفَ يَأْت۪يهِمْ اَنْبٰٓـؤُ۬ا مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Fe kad kezzebu bil hakkı lemma caehum, fe sevfe ye\'tihim enbau ma kanubihi yestehziun.', 'Fakat kendilerine gelen hakkı yalanladılar. Onlara,  yakında kendisi ile alay ettikleri şeyin haberleri gelecek.', 'فقد كذبوا بالحق لما جاهم فسوف ياتيهم انبوا ما كانوا به يستهزون'),
(795, 6, 6, 'اَلَمْ يَرَوْا كَمْ اَهْلَكْنَا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ مَكَّنَّاهُمْ فِي الْاَرْضِ مَا لَمْ نُمَكِّنْ لَكُمْ وَاَرْسَلْنَا السَّمَٓاءَ عَلَيْهِمْ مِدْرَاراًۖ وَجَعَلْنَا الْاَنْهَارَ تَجْر۪ي مِنْ تَحْتِهِمْ فَاَهْلَكْنَاهُمْ بِذُنُوبِهِمْ وَاَنْشَأْنَا مِنْ بَعْدِهِمْ قَرْناً اٰخَر۪ينَ', 'E lem yerev kem ehlekna min kablihim min karnin mekkennahum fil ardı ma lem numekkin lekum ve erselnes semae aleyhim midraren ve cealnal enhare tecri min tahtihim fe ehleknahum bi zunubihim ve enşe\'na min ba\'dihim karnen aharin.', 'Kendilerinden önce nice nesilleri yok ettiğimizi idrak[1] etmiyorlar mı? Yeryüzünde size vermediğimiz imkanları onlara vermiştik. Üzerlerine bol bol yağmur göndermiş ve yerlerde ırmaklar akıtmıştık. İşledikleri suçları nedeniyle kendilerini yok ettik. Onlardan sonra başka nesiller meydana getirdik.', 'الم يروا كم اهلكنا من قبلهم من قرن مكنهم في الارض ما لم نمكن لكم وارسلنا السما عليهم مدرارا وجعلنا الانهر تجري من تحتهم فاهلكنهم بذنوبهم وانشانا من بعدهم قرنا اخرين'),
(796, 6, 7, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَاباً ف۪ي قِرْطَاسٍ فَلَمَسُوهُ بِاَيْد۪يهِمْ لَقَالَ الَّذ۪ينَ كَفَرُٓوا اِنْ هٰذَٓا اِلَّا سِحْرٌ مُب۪ينٌ', 'Ve lev nezzelna aleyke kitaben fi kırtasin fe le mesuhu bi eydihim le kalelezine keferu in haza illa sihrun mubin.', 'Biz,  sana kağıt üzerine yazılı bir metin indirmiş olsaydık da onlar da ona elleriyle dokunsalardı yine de Kafirler \"Bu,  ancak apaçık bir sihirdir.\" derlerdi.[1]', 'ولو نزلنا عليك كتبا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين'),
(797, 6, 8, 'وَقَالُوا لَوْلَٓا اُنْزِلَ عَلَيْهِ مَلَكٌۜ وَلَوْ اَنْزَلْنَا مَلَكاً لَقُضِيَ الْاَمْرُ ثُمَّ لَا يُنْظَرُونَ', 'Ve kalu lev la unzile aleyhi melek, ve lev enzelna meleken, le kudıyel emru summe la yunzarun.', '\"Ona bir melek indirilmeli değil miydi?\" dediler. Eğer bir melek indirmiş olsaydık iş bitirilmiş olurdu. Sonra onlara göz açtırılmazdı.', 'وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون'),
(798, 6, 9, 'وَلَوْ جَعَلْنَاهُ مَلَكاً لَجَعَلْنَاهُ رَجُلاً وَلَلَبَسْنَا عَلَيْهِمْ مَا يَلْبِسُونَ', 'Ve lev cealnahu meleken le cealnahu raculen ve le lebesna aleyhim ma yelbisun.', 'Ve Biz,  bir melek görevlendirseydik,  onu da insan şeklinde gönderirdik ve onları düştükleri kuşkuya yine düşürürdük.[1]', 'ولو جعلنه ملكا لجعلنه رجلا وللبسنا عليهم ما يلبسون'),
(799, 6, 10, 'وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَحَاقَ بِالَّذ۪ينَ سَخِرُوا مِنْهُمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ۟', 'Ve lekadistuhzie bi rusulin min kablike fe haka billezine sehıru minhum ma kanu bihi yestehziun.', 'Ant olsun,  senden önce de resullerle alay edildi. Onlarla alay edenleri,  alaya aldıkları şey çepeçevre kuşatıverdi.', 'ولقد استهزي برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزون'),
(800, 6, 11, 'قُلْ س۪يرُوا فِي الْاَرْضِ ثُمَّ انْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّب۪ينَ', 'Kul siru fil ardı summenzuru keyfe kane akıbetul mukezzibin.', 'De ki: \"Yeryüzünü dolaşın da yalanlayanların sonunun nasıl olduğunu görün!\"', 'قل سيروا في الارض ثم انظروا كيف كان عقبة المكذبين'),
(801, 6, 12, 'قُلْ لِمَنْ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ قُلْ لِلّٰهِۜ  كَتَبَ عَلٰى نَفْسِهِ الرَّحْمَةَۜ  لَيَجْمَعَنَّكُمْ اِلٰى يَوْمِ الْقِيٰمَةِ لَا رَيْبَ ف۪يهِۜ اَلَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'Kul li men ma fis semavati vel ard, kul lillah, ketebe ala nefsihir rahmeh, le yecmeannekum ila yevmil kıyameti la reybe fih, ellezine hasiru enfusehum fe hum la yu\'minun.', 'De ki: \"Gökte ve yerde olan şeyler kimindir?\" De ki: \"Rahmeti Kendi üzerine yazan[1] Allah\'ındır.\" O,  gerçekleşeceği kesin olan Kıyamet Günü\'nde sizi mutlaka toplayacaktır. O kimseler ki kendi nefislerine hüsran[2] ettiler,  işte onlar iman etmezler.[3]', 'قل لمن ما في السموت والارض قل لله كتب علي نفسه الرحمة ليجمعنكم الي يوم القيمة لا ريب فيه الذين خسروا انفسهم فهم لا يومنون'),
(802, 6, 13, 'وَلَهُ مَا سَكَنَ فِي الَّيْلِ وَالنَّهَارِۜ وَهُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve lehu ma sekene fil leyli ven nehar, ve huves semiul alim.', 'Gece ve gündüzde barınıp yaşayan her şey O\'nundur. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'وله ما سكن في اليل والنهار وهو السميع العليم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(803, 6, 14, 'قُلْ اَغَيْرَ اللّٰهِ اَتَّخِذُ وَلِياًّ فَاطِرِ السَّمٰوَاتِ وَالْاَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُۜ قُلْ اِنّ۪ٓي اُمِرْتُ اَنْ اَكُونَ اَوَّلَ مَنْ اَسْلَمَ وَلَا تَكُونَنَّ مِنَ الْمُشْرِك۪ينَ', 'Kul e gayrallahi ettehızu veliyyen fatırıs semavati vel ardı ve huve yut\'ımu ve la yut\'am, kul inni umirtu en ekune evvele men esleme ve la tekunenne minel muşrikin.', 'De ki: \"Göklerin ve yerin fıtratını[1] belirleyen; herkesi yedirip içiren,  fakat kendisinin yeme ve içmeye ihtiyacı olmayan Allah\'tan başkasını mı veli[2] edineceğim?\" De ki: \"Bana,  teslim olanların ilki olmam emredildi.\" Ve sakın müşriklerden olma!', 'قل اغير الله اتخذ وليا فاطر السموت والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين'),
(804, 6, 15, 'قُلْ اِنّ۪ٓي اَخَافُ اِنْ عَصَيْتُ رَبّ۪ي عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Kul inni ehafu in asaytu rabbi azabe yevmin azim.', 'Eğer Rabb\'ime isyan edersem; büyük günün azabından korkarım.', 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم'),
(805, 6, 16, 'مَنْ يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۜ وَذٰلِكَ الْفَوْزُ الْمُب۪ينُ', 'Men yusraf anhu yevme izin fe kad rahımeh, ve zalikel fevzul mubin.', 'İzin Günü[1] kim kurtarılırsa,  ona rahmet edilmiştir. İşte apaçık kurtuluş da budur.', 'من يصرف عنه يوميذ فقد رحمه وذلك الفوز المبين'),
(806, 6, 17, 'وَاِنْ يَمْسَسْكَ اللّٰهُ بِضُرٍّ فَلَا كَاشِفَ لَهُٓ اِلَّا هُوَۜ وَاِنْ يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ve in yemseskellahu bi durrin fe la kaşife lehu illa huve, ve in yemseske bi hayrın fe huve ala kulli şey\'in kadir.', 'Eğer Allah,  sana bir sıkıntı verirse onu Kendisinden başka giderecek yoktur. Ve eğer sana bir iyilik verirse kuşkusuz Her Şeye Kadir Olan O\'dur.', 'وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو علي كل شي قدير'),
(807, 6, 18, 'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِه۪ۜ وَهُوَ الْحَك۪يمُ الْخَب۪يرُ', 'Ve huvel kahiru fevka ıbadih, ve huvel hakimul habir.', 'O,  kullarının üzerinde mutlak egemenlik sahibidir. En İyi Hüküm Veren\'dir,  Her Şeyden Haberdar\'dır.', 'وهو القاهر فوق عباده وهو الحكيم الخبير'),
(808, 6, 19, 'قُلْ اَيُّ شَيْءٍ اَكْبَرُ شَهَادَةًۜ  قُلِ اللّٰهُ شَه۪يدٌ بَيْن۪ي وَبَيْنَكُمْ وَاُو۫حِيَ اِلَيَّ هٰذَا الْقُرْاٰنُ لِاُنْذِرَكُمْ بِه۪ وَمَنْ بَلَغَۜ  اَئِنَّكُمْ لَتَشْهَدُونَ اَنَّ مَعَ اللّٰهِ اٰلِهَةً اُخْرٰىۜ قُلْ لَٓا اَشْهَدُۚ قُلْ اِنَّمَا هُوَ اِلٰهٌ وَاحِدٌ وَاِنَّن۪ي بَر۪ٓيءٌ مِمَّا تُشْرِكُونَۢ', 'Kul eyyu şey\'in ekberu şehadeh, kulillahu şehidun, beyni ve beynekum ve uhiye ileyye hazal kur\'anu li unzirekum bihi ve men belag, e innekum le teşhedune enne meallahi aliheten uhra, kul la eşhed, kul innema huve ilahun vahidun ve inneni beriun mimma tuşrikun.', 'De ki: \"Tanıklık yönünden hangi şey daha güvenilirdir?\" De ki: \"Aramızda tanık Allah\'tır. Bu Kur\'an; bana,  sizi ve ulaştığı herkesi uyarmam için vahyedildi. Yoksa Allah ile beraber başka ilahlar olduğuna tanıklık mı ediyorsunuz? De ki: \"Ben tanıklık etmem.\" De ki: \"O ancak tek ilahtır. Kuşkusuz ben,  sizin şirk koştuğunuz şeylerden uzağım.\"', 'قل اي شي اكبر شهدة قل الله شهيد بيني وبينكم واوحي الي هذا القران لانذركم به ومن بلغ اينكم لتشهدون ان مع الله الهة اخري قل لا اشهد قل انما هو اله وحد وانني بري مما تشركون'),
(809, 6, 20, 'اَلَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ اَبْنَٓاءَهُمْۢ اَلَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ۟', 'Ellezine ateynahumul kitabe ya\'rifunehu kema ya\'rifune ebnaehum ellezine hasiru enfusehum fe hum la yu\'minun.', 'Kendilerine kitap verdiklerimiz,  onu çocuklarını tanır gibi tanırlar. O kimseler,  kendi nefislerine hüsran[1] ettiler,  işte onlar iman etmezler.', 'الذين اتينهم الكتب يعرفونه كما يعرفون ابناهم الذين خسروا انفسهم فهم لا يومنون'),
(810, 6, 21, 'وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً اَوْ كَذَّبَ بِاٰيَاتِه۪ۜ اِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', 'Ve men azlemu mimmeniftera alallahi keziben ev kezzebe bi ayatih, innehu la yuflihuz zalimun.', 'Uydurduğu yalanı Allah\'a dayandıran veya O\'nun ayetlerini yalan sayandan daha zalim kim olabilir? Kuşkusuz O,  zalimleri kurtuluşa erdirmez.', 'ومن اظلم ممن افتري علي الله كذبا او كذب بايته انه لا يفلح الظلمون'),
(811, 6, 22, 'وَيَوْمَ نَحْشُرُهُمْ جَم۪يعاً ثُمَّ نَقُولُ لِلَّذ۪ينَ اَشْرَكُٓوا اَيْنَ شُرَكَٓاؤُ۬كُمُ الَّذ۪ينَ كُنْتُمْ تَزْعُمُونَ', 'Ve yevme nahşuruhum cemian summe nekulu lillezine eşraku eyne şurekaukumullezine kuntum tez\'umun.', 'O gün hepsini toplayacağız. Sonra şirk koşanlara,  \"Hani nerede boş yere davasını güttüğünüz ortaklar?\" diye soracağız.', 'ويوم نحشرهم جميعا ثم نقول للذين اشركوا اين شركاوكم الذين كنتم تزعمون'),
(812, 6, 23, 'ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ اِلَّٓا اَنْ قَالُوا وَاللّٰهِ رَبِّنَا مَا كُنَّا مُشْرِك۪ينَ', 'Summe lem tekun fitnetuhum illa en kalu vallahi rabbina ma kunna muşrikin.', 'Sonra başvurdukları fitne[1] \"Rabb\'imiz Allah\'a ant olsun ki,  biz müşriklerden değildik.\" demelerinden başka bir şey olmadı.', 'ثم لم تكن فتنتهم الا ان قالوا والله ربنا ما كنا مشركين'),
(813, 6, 24, 'اُنْظُرْ كَيْفَ كَذَبُوا عَلٰٓى اَنْفُسِهِمْ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ', 'Unzur keyfe kezebu ala enfusihim ve dalle anhum, ma kanu yefterun.', 'Bak! Kendi aleyhlerine nasıl yalan söylediler. Ve uydurdukları şeyler onlardan ayrılıp yok oldu.', 'انظر كيف كذبوا علي انفسهم وضل عنهم ما كانوا يفترون'),
(814, 6, 25, 'وَمِنْهُمْ مَنْ يَسْتَمِعُ اِلَيْكَۚ وَجَعَلْنَا عَلٰى قُلُوبِهِمْ اَكِنَّةً اَنْ يَفْقَهُوهُ وَف۪ٓي اٰذَانِهِمْ وَقْراًۜ وَاِنْ يَرَوْا كُلَّ اٰيَةٍ لَا يُؤْمِنُوا بِهَاۜ حَتّٰٓى اِذَا جَٓاؤُ۫كَ يُجَادِلُونَكَ يَقُولُ الَّذ۪ينَ كَفَرُٓوا اِنْ هٰذَٓا اِلَّٓا اَسَاط۪يرُ الْاَوَّل۪ينَ', 'Ve minhum men yestemiu ileyk, ve cealna ala kulubihim ekinneten en yefkahuhu ve fi azanihim vakra, ve in yerev kulle ayetin la yu\'minu biha, hatta iza cauke yucadiluneke yekulullezine keferu in haza illa esatirul evvelin.', 'Onlardan seni dinleyenler[1] vardır; oysa onu anlamalarına engel olmak için kalplerine perde,  kulaklarına ağırlık koyduk.[2] Onlar her türlü ayeti[3] görseler de yine de ona iman etmezler. Kafirler sana geldiklerinde,  \"Bunlar ancak geçmişin masallarıdır.\" diye seninle tartışırlar.', 'ومنهم من يستمع اليك وجعلنا علي قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا وان يروا كل اية لا يومنوا بها حتي اذا جاوك يجدلونك يقول الذين كفروا ان هذا الا اسطير الاولين'),
(815, 6, 26, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُۚ وَاِنْ يُهْلِكُونَ اِلَّٓا اَنْفُسَهُمْ وَمَا يَشْعُرُونَ', 'Ve hum yenhevne anhu ve yen\'evne anh, ve in yuhlikune illa enfusehumve ma yeş\'urun.', 'Onlar,  başkalarını ondan vazgeçirmeye çalışırlar,  kendileri de ondan uzaklaşırlar. Ve onlar,  ancak kendilerini mahvederler,  ama bunu idrak etmezler.', 'وهم ينهون عنه وينون عنه وان يهلكون الا انفسهم وما يشعرون'),
(816, 6, 27, 'وَلَوْ تَرٰٓى اِذْ وُقِفُوا عَلَى النَّارِ فَقَالُوا يَا لَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِاٰيَاتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِن۪ينَ', 'Ve lev tera iz vukıfu alen nari fe kalu ya leytena nureddu ve la nukezzibe bi ayati rabbina ve nekune minel mu\'minin.', 'Onların,  ateşin karşısında durdurulduklarında: \"Keşke geri döndürülsek de Rabb\'imizin ayetlerini yalanlamasak ve Mü\'minlerden olsak.\" dediklerini bir görsen.', 'ولو تري اذ وقفوا علي النار فقالوا يليتنا نرد ولا نكذب بايت ربنا ونكون من المومنين'),
(817, 6, 28, 'بَلْ بَدَا لَهُمْ مَا كَانُوا يُخْفُونَ مِنْ قَبْلُۜ وَلَوْ رُدُّوا لَعَادُوا لِمَا نُهُوا عَنْهُ وَاِنَّهُمْ لَكَاذِبُونَ', 'Bel beda lehum ma kanu yuhfune min kabl,ve lev ruddu le adu li ma nuhu anhuve innehum le kazibun.', 'Hayır! Daha önce gizledikleri şeyler açığa çıktı. Eğer onlar,  geri döndürülseler yasaklanan kötülüklere tekrar dönerler. Onlar kesinlikle yalancıdırlar.', 'بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وانهم لكذبون'),
(818, 6, 29, 'وَقَالُٓوا اِنْ هِيَ اِلَّا حَيَاتُنَا الدُّنْيَا وَمَا نَحْنُ بِمَبْعُوث۪ينَ', 'Ve kalu in hiye illa hayatuned dunya ve ma nahnu bi meb\'usin.', '\"Dünya hayatımızdan başka hayat yoktur,  öldükten sonra diriltilecek de değiliz.\" dediler.', 'وقالوا ان هي الا حياتنا الدنيا وما نحن بمبعوثين'),
(819, 6, 30, 'وَلَوْ تَرٰٓى اِذْ وُقِفُوا عَلٰى رَبِّهِمْۜ  قَالَ اَلَيْسَ هٰذَا بِالْحَقِّۜ قَالُوا بَلٰى وَرَبِّنَاۜ قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ۟', 'Ve lev tera iz vukıfu ala rabbihim, kale e leyse haza bil hakk, kalu bela ve rabbina, kale fe zukul azabe bima kuntum tekfurun.', 'Rabb\'lerinin huzurunda durdurulduklarında,  onları bir görsen! Allah,  \"Bu,  gerçek değil miymiş?\" dedi. Onlar: \"Rabbimize ant olsun ki gerçekmiş.\" dediler. \" O halde kafirliğinizden[1] dolayı azabı tadın.\" dedi.', 'ولو تري اذ وقفوا علي ربهم قال اليس هذا بالحق قالوا بلي وربنا قال فذوقوا العذاب بما كنتم تكفرون'),
(820, 6, 31, 'قَدْ خَسِرَ الَّذ۪ينَ كَذَّبُوا بِلِقَٓاءِ اللّٰهِۜ حَتّٰٓى اِذَا جَٓاءَتْهُمُ السَّاعَةُ بَغْتَةً قَالُوا يَا حَسْرَتَنَا عَلٰى مَا فَرَّطْنَا ف۪يهَاۙ وَهُمْ يَحْمِلُونَ اَوْزَارَهُمْ عَلٰى ظُهُورِهِمْۜ  اَلَا سَٓاءَ مَا يَزِرُونَ', 'Kad hasirellezine kezzebu bi likaillah hatta iza caethumus saatu bagteten kalu ya hasretena ala ma farratna fiha ve hum yahmilune evzarehum ala zuhurihim, e la sae ma yezirun.', 'Allah ile karşılaşmayı yalan sayanlar,  gerçekten hüsrana uğramışlardır. Nihayet o saat ansızın gelip çatınca,  günahlarını sırtlarına yüklenerek: \"Dünyada iyi şeyleri yapmamaktan dolayı yazıklar olsun bize.\" diyecekler. Dikkat edin yüklendikleri şey ne kötüdür!', 'قد خسر الذين كذبوا بلقا الله حتي اذا جاتهم الساعة بغتة قالوا يحسرتنا علي ما فرطنا فيها وهم يحملون اوزارهم علي ظهورهم الا سا ما يزرون'),
(821, 6, 32, 'وَمَا الْحَيٰوةُ الدُّنْيَٓا اِلَّا لَعِبٌ وَلَهْوٌۜ وَلَلدَّارُ الْاٰخِرَةُ خَيْرٌ لِلَّذ۪ينَ يَتَّقُونَۜ  اَفَلَا تَعْقِلُونَ', 'Ve mal hayatud dunya illa leibun ve lehv, ve led darul ahiretu hayrun lillezine yettekun, e fe la ta\'kılun.', 'Dünya hayatı,  bir oyun ve oyalanmadan başka bir şey değildir. Ahiret yurdu ise,  takva ehli olanlar için daha hayırlıdır. Hala aklınızı kullanmayacak mısınız?', 'وما الحيوة الدنيا الا لعب ولهو وللدار الاخرة خير للذين يتقون افلا تعقلون'),
(822, 6, 33, 'قَدْ نَعْلَمُ اِنَّهُ لَيَحْزُنُكَ الَّذ۪ي يَقُولُونَ فَاِنَّهُمْ لَا يُكَذِّبُونَكَ وَلٰكِنَّ الظَّالِم۪ينَ بِاٰيَاتِ اللّٰهِ يَجْحَدُونَ', 'Kad na\'lemu, innehu le yahzunukellezi yekulune fe innehum la yukezzibuneke ve lakinnez zaliminebi ayatillahi yechadun.', 'Doğrusu,  onların söyledikleri sözlerin seni üzdüğünü biliyoruz. Aslında onlar seni yalanlamıyorlar; o zalimler açıkça Allah\'ın ayetlerini reddediyorlar.', 'قد نعلم انه ليحزنك الذي يقولون فانهم لا يكذبونك ولكن الظلمين بايت الله يجحدون'),
(823, 6, 34, 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ فَصَبَرُوا عَلٰى مَا كُذِّبُوا وَاُو۫ذُوا حَتّٰٓى اَتٰيهُمْ نَصْرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَاتِ اللّٰهِۚ وَلَقَدْ جَٓاءَكَ مِنْ نَبَا۬ئِ الْمُرْسَل۪ينَ', 'Ve lekad kuzzibet rusulun min kablike fe saberu ala ma kuzzibu ve uzu hatta etahum nasruna, ve la mubeddile li kelimatillah, ve lekad caeke min nebeil murselin.', 'Ant olsun,  senden önce de resuller yalanlanmıştı. Yalanlanmalarına ve eziyet edilmelerine karşı Bizim yardımımız ulaşıncaya kadar sabrettiler. Allah\'ın kelimelerini[1] değiştirebilecek bir güç yoktur. Nitekim senden önce gönderilmiş elçilerin bir kısım haberleri sana gelmiştir.', 'ولقد كذبت رسل من قبلك فصبروا علي ما كذبوا واوذوا حتي اتيهم نصرنا ولا مبدل لكلمت الله ولقد جاك من نباي المرسلين'),
(824, 6, 35, 'وَاِنْ كَانَ كَبُرَ عَلَيْكَ اِعْرَاضُهُمْ فَاِنِ اسْتَطَعْتَ اَنْ تَبْتَغِيَ نَفَقاً فِي الْاَرْضِ اَوْ سُلَّماً فِي السَّمَٓاءِ فَتَأْتِيَهُمْ بِاٰيَةٍۜ وَلَوْ شَٓاءَ اللّٰهُ لَجَمَعَهُمْ عَلَى الْهُدٰى فَلَا تَكُونَنَّ مِنَ الْجَاهِل۪ينَ', 'Ve in kane kebure aleyke i\'raduhum fe inisteta\'te en tebtegıye nefekan fil ardı ev sullemen fis semai fe te\'tiyehum bi ayeh, ve lev şaallahu le cemeahum alel huda fe la tekunenne minel cahilin.', 'Eğer yüz çevirmeleri sana ağır geldiyse,  yapabilirsen bir tünelle yerden veya bir merdivenle gökten onlara bir ayet[1] getir! Eğer Allah dileseydi[2],  elbette onları doğru yol üzerinde toplardı. O halde sakın cahillerden olma!', 'وان كان كبر عليك اعراضهم فان استطعت ان تبتغي نفقا في الارض او سلما في السما فتاتيهم باية ولو شا الله لجمعهم علي الهدي فلا تكونن من الجهلين'),
(825, 6, 36, 'اِنَّمَا يَسْتَج۪يبُ الَّذ۪ينَ يَسْمَعُونَۜ وَالْمَوْتٰى يَبْعَثُهُمُ اللّٰهُ ثُمَّ اِلَيْهِ يُرْجَعُونَ', 'İnnema yestecibullezine yesmeun, vel mevta yeb\'asuhumullahu summe ileyhi yurceun.', 'Ancak kulak veren kimseler[1] bu daveti kabul eder. Ölülere[2] gelince onları ancak Allah diriltir. Sonra O\'na döndürülürler.', 'انما يستجيب الذين يسمعون والموتي يبعثهم الله ثم اليه يرجعون'),
(826, 6, 37, 'وَقَالُوا لَوْلَا نُزِّلَ عَلَيْهِ اٰيَةٌ مِنْ رَبِّه۪ۜ قُلْ اِنَّ اللّٰهَ قَادِرٌ عَلٰٓى اَنْ يُنَزِّلَ اٰيَةً وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Ve kalu lev la nuzzile aleyhi ayetun min rabbih, kul innallahe kadirun ala en yunezzile ayeten ve lakinne ekserehum la ya\'lemun.', 'Ona,  \"Rabb\'inden bir ayet[1] indirilmeli değil miydi?\" dediler. De ki: \"Elbette ki Allah,  bir ayet[1] indirmeye kadirdir. Ancak onların çoğu bunu bilmezler.\"', 'وقالوا لولا نزل عليه اية من ربه قل ان الله قادر علي ان ينزل اية ولكن اكثرهم لا يعلمون'),
(827, 6, 38, 'وَمَا مِنْ دَٓابَّةٍ فِي الْاَرْضِ وَلَا طَٓائِرٍ يَط۪يرُ بِجَنَاحَيْهِ اِلَّٓا اُمَمٌ اَمْثَالُكُمْۜ مَا فَرَّطْنَا فِي الْكِتَابِ مِنْ شَيْءٍ ثُمَّ اِلٰى رَبِّهِمْ يُحْشَرُونَ', 'Ve ma min dabbetin fil ardı ve la tairin yatiru bi cenahayhi illa umemun emsalukum, ma farratna fil kitabi min şey\'in summe ila rabbihim yuhşerun.', 'Yeryüzünde hareket eden hiçbir dabbeh[1] ve iki kanadıyla uçan hiçbir kuş yoktur ki,  sizin gibi ümmetler[2] olmasın. Biz,  Kitapta hiçbir şeyi eksik bırakmadık.[3] Sonunda hepsi de Rabb\'lerinin huzurunda toplanacaklardır.', 'وما من دابة في الارض ولا طير يطير بجناحيه الا امم امثالكم ما فرطنا في الكتب من شي ثم الي ربهم يحشرون'),
(828, 6, 39, 'وَالَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا صُمٌّ وَبُكْمٌ فِي الظُّلُمَاتِۜ مَنْ يَشَأِ اللّٰهُ يُضْلِلْهُۜ وَمَنْ يَشَأْ يَجْعَلْهُ عَلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Vellezine kezzebu bi ayatina summun ve bukmun fiz zulumat, men yeşaillahu yudlilhu, ve men yeşe\' yec\'alhu ala sıratın mustakim.', 'Âyetlerimizi yalanlayan kimseler,  karanlıklar[1] içinde kalmış,  sağırlar ve dilsizlerdir. Allah hak edeni saptırır[2] hak edeni[2] de dosdoğru yola iletir.', 'والذين كذبوا بايتنا صم وبكم في الظلمت من يشا الله يضلله ومن يشا يجعله علي صرط مستقيم'),
(829, 6, 40, 'قُلْ اَرَاَيْتَكُمْ اِنْ اَتٰيكُمْ عَذَابُ اللّٰهِ اَوْ اَتَتْكُمُ السَّاعَةُ اَغَيْرَ اللّٰهِ تَدْعُونَۚ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kul e reeytekum in etakum azabullahi ev etetkumus saatu e gayrallahi ted\'un, in kuntum sadıkin.', 'De ki: \"Eğer doğru söyleyen kimselerseniz söyleyin bakalım. Size Allah\'ın azabı gelse veya son saat[1] gelse,  Allah\'tan başkasına mı yalvarırsınız?\"', 'قل اريتكم ان اتيكم عذاب الله او اتتكم الساعة اغير الله تدعون ان كنتم صدقين'),
(830, 6, 41, 'بَلْ اِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ اِلَيْهِ اِنْ شَٓاءَ وَتَنْسَوْنَ مَا تُشْرِكُونَ۟', 'Bel iyyahu ted\'une fe yekşifu ma ted\'une ileyhi in şae ve tensevne ma tuşrikun.', '\"Hayır! Yalnız O\'na yalvarırsınız,  O da dilerse yalvarmanıza konu olan sıkıntıyı kaldırır ve siz de ortak koştuklarınızı anmazsınız.\"', 'بل اياه تدعون فيكشف ما تدعون اليه ان شا وتنسون ما تشركون'),
(831, 6, 42, 'وَلَقَدْ اَرْسَلْـنَٓا اِلٰٓى اُمَمٍ مِنْ قَبْلِكَ فَاَخَذْنَاهُمْ بِالْبَأْسَٓاءِ وَالضَّرَّٓاءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', 'Ve lekad erselna ila umemin min kablike fe ehaznahum bil be\'sai ved darrai leallehum yetedarraun.', 'Ant olsun ki Biz,  senden önceki ümmetlere de gönderdik.[1] Belki tederruda[2] bulunurlar diye onları darlık ve sıkıntı ile yakaladık.[3]', 'ولقد ارسلنا الي امم من قبلك فاخذنهم بالباسا والضرا لعلهم يتضرعون'),
(832, 6, 43, 'فَلَوْلَٓا اِذْ جَٓاءَهُمْ بَأْسُنَا تَضَرَّعُوا وَلٰكِنْ قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ الشَّيْطَانُ مَا كَانُوا يَعْمَلُونَ', 'Fe lev la iz caehum be\'suna tedarrau ve lakin kaset kulubuhum ve zeyyene lehumuş şeytanu ma kanu ya\'melun.', 'Hiç olmazsa onlara sıkıntılarımız dokunduğu vakit tederru etselerdi! Fakat kalpleri katılaştı ve şeytan da onlara yaptıklarını çekici gösterdi.', 'فلولا اذ جاهم باسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطن ما كانوا يعملون'),
(833, 6, 44, 'فَلَمَّا نَسُوا مَا ذُكِّرُوا بِه۪ فَتَحْنَا عَلَيْهِمْ اَبْوَابَ كُلِّ شَيْءٍۜ حَتّٰٓى اِذَا فَرِحُوا بِمَٓا اُو۫تُٓوا اَخَذْنَاهُمْ بَغْتَةً فَاِذَا هُمْ مُبْلِسُونَ', 'Fe lemma nesu ma zukkiru bihi fetahna aleyhim ebvabe kulli şey\', hatta iza ferihu bima utu ehaznahum bagteten fe izahum mublisun.', 'Onlar,  verilen öğüdü unutunca,  onlara her şeyin kapılarını açtık; kendilerine verilen şeylerle sevince daldıkları sırada onları ansızın yakalayıverdik. O zaman bütün ümitleri boşa çıktı.', 'فلما نسوا ما ذكروا به فتحنا عليهم ابواب كل شي حتي اذا فرحوا بما اوتوا اخذنهم بغتة فاذا هم مبلسون'),
(834, 6, 45, 'فَقُطِـعَ دَابِرُ الْقَوْمِ الَّذ۪ينَ ظَلَمُواۜ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَ', 'Fe kutia dabirul kavmillezine zalemu, vel hamdu lillahi rabbil alemin.', 'Böylece zulmeden halkın kökü kurudu. Âlemlerin Rabb\'i olan Allah\'a hamdolsun.', 'فقطع دابر القوم الذين ظلموا والحمد لله رب العلمين'),
(835, 6, 46, 'قُلْ اَرَاَيْتُمْ اِنْ اَخَذَ اللّٰهُ سَمْعَكُمْ وَاَبْصَارَكُمْ وَخَتَمَ عَلٰى قُلُوبِكُمْ مَنْ اِلٰهٌ غَيْرُ اللّٰهِ يَأْت۪يكُمْ بِهِۜ اُنْظُرْ كَيْفَ نُصَرِّفُ الْاٰيَاتِ ثُمَّ هُمْ يَصْدِفُونَ', 'Kul e reeytum in ehazallahu sem\'akum ve ebsarekum ve hateme ala kulubikum men ilahun gayrullahi ye\'tikum bih, unzur keyfe nusarriful ayati summe hum yasdifun .', 'De ki: \"Söyleyin bana! Eğer Allah; işitmenizi,  görmenizi ve kalbinizin[1] idrak etmesini yok etse,  Allah\'tan başka hangi ilah onları size geri verebilir?\" Bak,  ayetlerimizi nasıl çok yönlü açıklıyoruz. Buna rağmen yine de yüz çeviriyorlar.', 'قل اريتم ان اخذ الله سمعكم وابصركم وختم علي قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايت ثم هم يصدفون'),
(836, 6, 47, 'قُلْ اَرَاَيْتَكُمْ اِنْ اَتٰيكُمْ عَذَابُ اللّٰهِ بَغْتَةً اَوْ جَهْرَةً هَلْ يُهْلَكُ اِلَّا الْقَوْمُ الظَّالِمُونَ', 'Kul e reeytekum in etakum azabullahi bagteten ev cehreten hel yuhleku illel kavmuz zalimun.', 'De ki: \"Söyleyin bana! Eğer size Allah\'ın azabı ansızın veya göz göre göre gelse,  zalimlerden başkası mı yok edilir?\"[1]', 'قل اريتكم ان اتيكم عذاب الله بغتة او جهرة هل يهلك الا القوم الظلمون'),
(837, 6, 48, 'وَمَا نُرْسِلُ الْمُرْسَل۪ينَ اِلَّا مُبَشِّر۪ينَ وَمُنْذِر۪ينَۚ فَمَنْ اٰمَنَ وَاَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Ve ma nursilul murseline illa mubeşşirine ve munzirin, fe men amene ve asleha fe la havfun aleyhim ve la hum yahzenun.', 'Biz elçileri ancak haberdar edici ve uyarıcı olarak gönderdik. Kim iman eder kendisini düzeltirse,  onlara korku yoktur,  onlar üzülmeyecekler de.', 'وما نرسل المرسلين الا مبشرين ومنذرين فمن امن واصلح فلا خوف عليهم ولا هم يحزنون'),
(838, 6, 49, 'وَالَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا يَمَسُّهُمُ الْعَذَابُ بِمَا كَانُوا يَفْسُقُونَ', 'Vellezine kezzebu bi ayatina yemessuhumul azabu bima kanu yefsukun.', 'Ayetlerimizi yalanlayanlara da yaptıkları fasıklık[1] yüzünden azabımız dokunacaktır.', 'والذين كذبوا بايتنا يمسهم العذاب بما كانوا يفسقون'),
(839, 6, 50, 'قُلْ لَٓا اَقُولُ لَكُمْ عِنْد۪ي خَزَٓائِنُ اللّٰهِ وَلَٓا اَعْلَمُ الْغَيْبَ وَلَٓا اَقُولُ لَكُمْ اِنّ۪ي مَلَكٌۚ اِنْ اَتَّبِعُ اِلَّا مَا يُوحٰٓى اِلَيَّۜ قُلْ هَلْ يَسْتَوِي الْاَعْمٰى وَالْبَص۪يرُۜ اَفَلَا تَتَفَكَّرُونَ۟', 'Kul la ekulu lekum indi hazainullahi ve la a\'lemul gaybe ve la ekulu lekum inni melek, in ettebiu illa ma yuha ileyy, kul hel yestevil a\'ma vel basir,e fe la tetefekkerun.', 'De ki: \"Ben size,  Allah\'ın hazineleri yanımdadır demiyorum. Gaybı da bilmem. Size,  ben bir meleğim de demiyorum. Ben,  sadece bana vahyolunana uyuyorum.\" De ki: \"Kör ile gören bir olur mu? Niçin düşünmüyorsunuz?\"', 'قل لا اقول لكم عندي خزاين الله ولا اعلم الغيب ولا اقول لكم اني ملك ان اتبع الا ما يوحي الي قل هل يستوي الاعمي والبصير افلا تتفكرون'),
(840, 6, 51, 'وَاَنْذِرْ بِهِ الَّذ۪ينَ يَخَافُونَ اَنْ يُحْشَرُٓوا اِلٰى رَبِّهِمْ لَيْسَ لَهُمْ مِنْ دُونِه۪ وَلِيٌّ وَلَا شَف۪يعٌ لَعَلَّهُمْ يَتَّقُونَ', 'Ve enzir bihillezine yehafune en yuhşeru ila rabbihimleyse lehum min dunihi veliyyun ve la şefiun leallehum yettekun.', 'Rabb\'lerinin huzurunda hesaba çekilme korkusu olanları,  onunla[1] uyar. Kendileri için O\'ndan başka ne bir şefaatçi ne de bir veli[2] yoktur. Umulur ki takva sahibi olurlar.', 'وانذر به الذين يخافون ان يحشروا الي ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون'),
(841, 6, 52, 'وَلَا تَطْرُدِ الَّذ۪ينَ يَدْعُونَ رَبَّهُمْ بِالْغَدٰوةِ وَالْعَشِيِّ يُر۪يدُونَ وَجْهَهُۜ مَا عَلَيْكَ مِنْ حِسَابِهِمْ مِنْ شَيْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِمْ مِنْ شَيْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ الظَّالِم۪ينَ', 'Ve la tatrudillezine yed\'une rabbehum bil gadati vel aşiyyi yuridune vecheh, ma aleyke min hısabihim min şey\'in ve ma min hısabike aleyhim min şey\'in fe tatrudehum fe tekune minez zalimin.', 'Rabb\'lerinin vechini[1] dileyerek sabah akşam[2] O\'na yönelenleri uzaklaştırma.[3] Onların hesabından sen,  senin hesabından da onlar sorumlu değil. Eğer onları kendinden uzaklaştırırsan zalimlerden[4] olursun!', 'ولا تطرد الذين يدعون ربهم بالغدوة والعشي يريدون وجهه ما عليك من حسابهم من شي وما من حسابك عليهم من شي فتطردهم فتكون من الظلمين'),
(842, 6, 53, 'وَكَذٰلِكَ فَتَنَّا بَعْضَهُمْ بِبَعْضٍ لِيَقُولُٓوا اَهٰٓؤُ۬لَٓاءِ مَنَّ اللّٰهُ عَلَيْهِمْ مِنْ بَيْنِنَاۜ اَلَيْسَ اللّٰهُ بِاَعْلَمَ بِالشَّاكِر۪ينَ', 'Ve kezalike fetenna ba\'dahum bi ba\'din li yekulu e haulai mennallahu aleyhim min beynina, e leysallahu bi a\'leme biş şakirin.', 'Biz,  böylece onların bir kısmını,  bir kısmı ile fitnelendirdik[1] ki: \"Allah\'ın,  aramızdan lütfuna[2] layık gördüğü kimseler bunlar mıdır?\" desinler diye. Allah,  şükredenleri daha iyi bilen değil midir?', 'وكذلك فتنا بعضهم ببعض ليقولوا اهولا من الله عليهم من بيننا اليس الله باعلم بالشكرين'),
(843, 6, 54, 'وَاِذَا جَٓاءَكَ الَّذ۪ينَ يُؤْمِنُونَ بِاٰيَاتِنَا فَقُلْ سَلَامٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلٰى نَفْسِهِ الرَّحْمَةَۙ اَنَّهُ مَنْ عَمِلَ مِنْكُمْ سُٓوءاً بِجَهَالَةٍ ثُمَّ تَابَ مِنْ بَعْدِه۪ وَاَصْلَحَ فَاَنَّهُ غَفُورٌ رَح۪يمٌ', 'Ve iza caekellezine yu\'minune bi ayatina fe kul selamun aleykum ketebe rabbukum ala nefsihir rahmete ennehu men amile minkum suen bi cehaletin summe tabe min ba\'dihi ve asleha fe ennehu gafurun rahim.', 'Âyetlerimize iman etmiş kimseler[1] sana geldiklerinde,  \"Size selam olsun.\"de.[2] Rabb\'iniz rahmet etmeyi Kendi üzerine yazdı.[3] Sizden kim cehaletle[4] kötü bir şey yapar da ardından tevbe edip kendini düzeltirse,  bilsin ki O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'واذا جاك الذين يومنون بايتنا فقل سلم عليكم كتب ربكم علي نفسه الرحمة انه من عمل منكم سوا بجهلة ثم تاب من بعده واصلح فانه غفور رحيم'),
(844, 6, 55, 'وَكَذٰلِكَ نُفَصِّلُ الْاٰيَاتِ وَلِتَسْتَب۪ينَ سَب۪يلُ الْمُجْرِم۪ينَ۟', 'Ve kezalike nufassılul ayati ve li testebine sebilul mucrimin.', 'Mücrimlerin[1] yolu besbelli olsun diye ayetleri ayrıntılı biçimde açıklıyoruz.', 'وكذلك نفصل الايت ولتستبين سبيل المجرمين'),
(845, 6, 56, 'قُلْ اِنّ۪ي نُه۪يتُ اَنْ اَعْبُدَ الَّذ۪ينَ تَدْعُونَ مِنْ دُونِ اللّٰهِۜ قُلْ لَٓا اَتَّبِـعُ اَهْوَٓاءَكُمْۙ قَدْ ضَلَلْتُ اِذاً وَمَٓا اَنَا۬ مِنَ الْمُهْتَد۪ينَ', 'Kul inni nuhitu en a\'budellezine ted\'une min dunillah, kul la ettebiu ehvaekum kad dalaltu izen ve ma ene minel muhtedin.', 'De ki: \"Ben,  Allah\'ın yanı sıra yalvardıklarınıza kulluk etmekten men olundum.\" De ki: \"Hevanıza[1] tabi olmam,  yoksa kesinlikle sapmış olurum da o zaman hidayete erenlerden olmamış olurum.\"', 'قل اني نهيت ان اعبد الذين تدعون من دون الله قل لا اتبع اهواكم قد ضللت اذا وما انا من المهتدين'),
(846, 6, 57, 'قُلْ اِنّ۪ي عَلٰى بَيِّنَةٍ مِنْ رَبّ۪ي وَكَذَّبْتُمْ بِه۪ۜ مَا عِنْد۪ي مَا تَسْتَعْجِلُونَ بِه۪ۜ اِنِ الْحُكْمُ اِلَّا لِلّٰهِۜ يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِل۪ينَ', 'Kul inni ala beyyinetin min rabbi, ve kezzebtum bih, ma indi ma testa\'cilune bih, inil hukmu illa lillah, yakussul hakka ve huve hayrul fasılin.', 'De ki: \"Ben,  Rabb\'imden açık bir kanıt üzerindeyim. Siz onu yalanladınız. Acelece istediğiniz şey benim yanımda değil. Hüküm ancak Allah\'a aittir. Zira O,  hakkı anlatır. Ve O,  ayırt edenlerin en hayırlısıdır.\"', 'قل اني علي بينة من ربي وكذبتم به ما عندي ما تستعجلون به ان الحكم الا لله يقص الحق وهو خير الفصلين'),
(847, 6, 58, 'قُلْ لَوْ اَنَّ عِنْد۪ي مَا تَسْتَعْجِلُونَ بِه۪ لَقُضِيَ الْاَمْرُ بَيْن۪ي وَبَيْنَكُمْۜ وَاللّٰهُ اَعْلَمُ بِالظَّالِم۪ينَ', 'Kul lev enne indi ma testa\'cilune bihi le kudıyel emru beyni ve beynekum, vallahu a\'lemu biz zalimin.', 'De ki: \"Eğer acelece istediğiniz o şey benim yanımda olsaydı,  benimle sizin aranızdaki iş çoktan olup biterdi.\" Allah,  zalimleri en iyi bilendir.', 'قل لو ان عندي ما تستعجلون به لقضي الامر بيني وبينكم والله اعلم بالظلمين'),
(848, 6, 59, 'وَعِنْدَهُ مَفَاتِـحُ الْغَيْبِ لَا يَعْلَمُهَٓا اِلَّا هُوَۜ وَيَعْلَمُ مَا فِي الْبَرِّ وَالْبَحْرِۜ وَمَا تَسْقُطُ مِنْ وَرَقَةٍ اِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ ف۪ي ظُلُمَاتِ الْاَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ اِلَّا ف۪ي كِتَابٍ مُب۪ينٍ', 'Ve indehu mefatihul gaybi la ya\'lemuha illa huve, ve ya\'lemu ma fil berri vel bahr, ve ma teskutu min varakatin illa ya\'lemuha ve la habbetin fi zulumatil ardı ve la ratbin ve la yabisin illa fi kitabin mubin.', 'Gaybın[1] anahtarı yalnızca O\'nun yanındadır. O\'ndan başka hiç kimse onları bilemez. Karada ve denizde olan her şeyi bilir. Bir yaprak düşse mutlaka onu bilir. Yerin karanlığında tek bir dane,  canlı ve cansız yoktur ki apaçık bir kitapta olmasın.', 'وعنده مفاتح الغيب لا يعلمها الا هو ويعلم ما في البر والبحر وما تسقط من ورقة الا يعلمها ولا حبة في ظلمت الارض ولا رطب ولا يابس الا في كتب مبين'),
(849, 6, 60, 'وَهُوَ الَّذ۪ي يَتَوَفّٰيكُمْ بِالَّيْلِ وَيَعْلَمُ مَا جَرَحْتُمْ بِالنَّهَارِ ثُمَّ يَبْعَثُـكُمْ ف۪يهِ لِيُقْضٰٓى اَجَلٌ مُسَمًّىۚ ثُمَّ اِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ۟', 'Ve huvellezi yeteveffakum bil leyli ve ya\'lemu ma cerahtum bin nehari summe yeb\'asukum fihi li yukda ecelun musemma, summe ileyhi merci\'ukum summe yunebbiukum bima kuntum ta\'melun.', 'O\'dur geceleyin sizi öldüren[1],  gündüz elde ettiğiniz şeyleri bilen. Sonra,  bilinen ecelin gerçekleşmesi için diriltendir.[2] Sonunda O\'nadır dönüşünüz. Sonra da her ne yaptıysanız onu size haber verecektir.', 'وهو الذي يتوفيكم باليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضي اجل مسمي ثم اليه مرجعكم ثم ينبيكم بما كنتم تعملون'),
(850, 6, 61, 'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِه۪ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةًۜ حَتّٰٓى اِذَا جَٓاءَ اَحَدَكُمُ الْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'Ve huvel kahiru fevka ibadihi ve yursilu aleykum hafazah, hatta iza cae ehadekumul mevtu teveffethu rusuluna ve hum la yuferritun.', 'O\'dur kulları üzerinde kahir[1] olan. Üzerinize gözeticiler gönderir. Sonra da sizden birine ölüm vakti geldiği zaman,  resullerimiz[2] hiç zaman geçirmeden onun canını alırlar.', 'وهو القاهر فوق عباده ويرسل عليكم حفظة حتي اذا جا احدكم الموت توفته رسلنا وهم لا يفرطون'),
(851, 6, 62, 'ثُمَّ رُدُّٓوا اِلَى اللّٰهِ مَوْلٰيهُمُ الْحَقِّۜ  اَلَا لَهُ الْحُكْمُ وَهُوَ اَسْرَعُ الْحَاسِب۪ينَ', 'Summe ruddu ilallahi mevlahumul hakk, e la lehul hukmu ve huve esraul hasibin.', 'Sonra onlar,  gerçek mevlaları[1] olan Allah\'a döndürülürler. Dikkat edin,  hüküm yalnız O\'nundur ve O,  hesabı çabuk görendir.', 'ثم ردوا الي الله موليهم الحق الا له الحكم وهو اسرع الحسبين'),
(852, 6, 63, 'قُلْ مَنْ يُنَجّ۪يكُمْ مِنْ ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ تَدْعُونَهُ تَضَرُّعاً وَخُفْيَةًۚ  لَئِنْ اَنْجٰينَا مِنْ هٰذِه۪ لَنَكُونَنَّ مِنَ الشَّاكِر۪ينَ', 'Kul men yuneccikum min zulumatil berri vel bahri ted\'unehu tedarruan ve hufyeh, le in encana min hazihi le nekunenne mineş şakirin.', 'De ki: \"Yerin ve denizin karanlıklarından sizi kim kurtarır?\" \"Eğer bundan bizi kurtarırsa kuşkusuz şükredenlerden oluruz.\" diye O\'na açık ve tezarruan[1] yakarırsınız.', 'قل من ينجيكم من ظلمت البر والبحر تدعونه تضرعا وخفية لين انجينا من هذه لنكونن من الشكرين'),
(853, 6, 64, 'قُلِ اللّٰهُ يُنَجّ۪يكُمْ مِنْهَا وَمِنْ كُلِّ كَرْبٍ ثُمَّ اَنْتُمْ تُشْرِكُونَ', 'Kulillahu yuneccikum minha ve min kulli kerbin summe entum tuşrikun.', 'De ki: \"Sizi ondan ve bütün sıkıntılardan Allah kurtarır da sonra siz yine O\'na şirk koşarsınız.\"', 'قل الله ينجيكم منها ومن كل كرب ثم انتم تشركون'),
(854, 6, 65, 'قُلْ هُوَ الْقَادِرُ عَلٰٓى اَنْ يَبْعَثَ عَلَيْكُمْ عَذَاباً مِنْ فَوْقِكُمْ اَوْ مِنْ تَحْتِ اَرْجُلِكُمْ اَوْ يَلْبِسَكُمْ شِيَعاً وَيُذ۪يقَ بَعْضَكُمْ بَأْسَ بَعْضٍۜ اُنْظُرْ كَيْفَ نُصَرِّفُ الْاٰيَاتِ لَعَلَّهُمْ يَفْقَهُونَ', 'Kul huvel kadiru ala en yeb\'ase aleykum azaben min fevkıkum ev min tahti erculikum ev yelbisekum şiyean ve yuzika ba\'dakum be\'se ba\'d, unzur keyfe nusarrıful ayati leallehum yefkahun.', 'De ki: \"Sizin üstünüzden ve ayaklarınızın altından azap göndermeye,  sizi topluluklar halinde ayırıp kiminizin hıncını kiminize tattırmaya kadir olan O\'dur.\" Bak,  iyice anlasınlar diye ayetlerimizi nasıl her yönüyle açıklıyoruz.', 'قل هو القادر علي ان يبعث عليكم عذابا من فوقكم او من تحت ارجلكم او يلبسكم شيعا ويذيق بعضكم باس بعض انظر كيف نصرف الايت لعلهم يفقهون'),
(855, 6, 66, 'وَكَذَّبَ بِه۪ قَوْمُكَ وَهُوَ الْحَقُّۜ قُلْ لَسْتُ عَلَيْكُمْ بِوَك۪يلٍۜ', 'Ve kezzebe bihi kavmuke ve huvel hakk,kul lestu aleykum bi vekil.', 'O hakikat olduğu halde halkın onu yalanladı. \"Ben üzerinize vekil değilim.\" de.', 'وكذب به قومك وهو الحق قل لست عليكم بوكيل'),
(856, 6, 67, 'لِكُلِّ نَبَأٍ مُسْتَقَرٌّۘ وَسَوْفَ تَعْلَمُونَ', 'Likulli nebein mustekar, ve sevfe ta\'lemun.', 'Her haberin[1] kararlaştırılmış bir zamanı vardır. Yakında bileceksiniz.', 'لكل نبا مستقر وسوف تعلمون'),
(857, 6, 68, 'وَاِذَا رَاَيْتَ الَّذ۪ينَ يَخُوضُونَ ف۪ٓي اٰيَاتِنَا فَاَعْرِضْ عَنْهُمْ حَتّٰى يَخُوضُوا ف۪ي حَد۪يثٍ غَيْرِه۪ۜ وَاِمَّا يُنْسِيَنَّكَ الشَّيْطَانُ فَلَا تَقْعُدْ بَعْدَ الذِّكْرٰى مَعَ الْقَوْمِ الظَّالِم۪ينَ', 'Ve iza reeytellezine yahudune fi ayatina fe a\'rıd anhum hatta yahudu fi hadisin gayrih, ve imma yunsiyennekeş şeytanu fe la tak\'ud ba\'dez zikra meal kavmiz zalimin.', 'Âyetlerimiz hakkında dalanlarla[1] karşılaştığın zaman,  onlar başka bir konuya geçinceye kadar,  onlardan yüz çevir. Eğer şeytan sana unutturursa,  hatırlar hatırlamaz zalim halkla beraber oturma.', 'واذا رايت الذين يخوضون في ايتنا فاعرض عنهم حتي يخوضوا في حديث غيره واما ينسينك الشيطن فلا تقعد بعد الذكري مع القوم الظلمين'),
(858, 6, 69, 'وَمَا عَلَى الَّذ۪ينَ يَتَّقُونَ مِنْ حِسَابِهِمْ مِنْ شَيْءٍ وَلٰكِنْ ذِكْرٰى لَعَلَّهُمْ يَتَّقُونَ', 'Ve ma alellezine yettekune min hısabihim min şey\'in ve lakin zikra leallehum yettekun.', 'Takva sahibi kimselere,  onların hesaplarından bir sorumluluk yoktur. Fakat bu bir hatırlatmadır,  belki korunurlar.', 'وما علي الذين يتقون من حسابهم من شي ولكن ذكري لعلهم يتقون'),
(859, 6, 70, 'وَذَرِ الَّذ۪ينَ اتَّخَذُوا د۪ينَهُمْ لَعِباً وَلَهْواً وَغَرَّتْهُمُ الْحَيٰوةُ الدُّنْيَا وَذَكِّرْ بِه۪ٓ اَنْ تُبْسَلَ نَفْسٌ بِمَا كَسَبَتْۗ لَيْسَ لَهَا مِنْ دُونِ اللّٰهِ وَلِيٌّ وَلَا شَف۪يعٌۚ وَاِنْ تَعْدِلْ كُلَّ عَدْلٍ لَا يُؤْخَذْ مِنْهَاۜ اُو۬لٰٓئِكَ الَّذ۪ينَ اُبْسِلُوا بِمَا كَسَبُواۚ لَهُمْ شَرَابٌ مِنْ حَم۪يمٍ وَعَذَابٌ اَل۪يمٌ بِمَا كَانُوا يَكْفُرُونَ۟', 'Ve zerillezinettehazu dinehum leiben ve lehven ve garrethumul hayatud dunya ve zekkir bihi en tubsele nefsun bima kesebet, leyse leha min dunillahi veliyyun ve la şefi\', ve in ta\'dil kulle adlin la yu\'haz minha, ulaikellezine ubsilu bima kesebu, lehum şarabun min hamimin ve azabun elimun bima kanu yekfurun.', 'Dinlerini oyun ve eğlence edinen,  dünya hayatının aldattığı kimseleri bırak. Hiç kimsenin kazandığı şeyle bir felaket yaşamaması için Kur\'an ile uyar. O kimse için Allah\'tan başka ne bir veli[1] ne de bir şefaatçi[2] vardır. O,  bütün varlığını fidye olarak verse de ondan kabul edilmez. Onlar,  kazandıklarından dolayı mahvolan kimselerdir. Onlar için kaynar sudan bir içecek ve can yakıcı bir azap vardır.', 'وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحيوة الدنيا وذكر به ان تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وان تعدل كل عدل لا يوخذ منها اوليك الذين ابسلوا بما كسبوا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون'),
(860, 6, 71, 'قُلْ اَنَدْعُوا مِنْ دُونِ اللّٰهِ مَا لَا يَنْفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلٰٓى اَعْقَابِنَا بَعْدَ اِذْ هَدٰينَا اللّٰهُ كَالَّذِي اسْتَهْوَتْهُ الشَّيَاط۪ينُ فِي الْاَرْضِ حَيْرَانَۖ لَهُٓ اَصْحَابٌ يَدْعُونَهُٓ اِلَى الْهُدَى ائْتِنَاۜ قُلْ اِنَّ هُدَى اللّٰهِ هُوَ الْهُدٰىۜ وَاُمِرْنَا لِنُسْلِمَ لِرَبِّ الْعَالَم۪ينَۙ', 'Kul e ned\'u min dunillahi ma la yenfeuna ve la yadurruna ve nureddu ala a\'kabina ba\'de iz hedanallahu kellezistehvethuş şeyatinu fil ardı hayrane lehu ashabun yed\'unehu ilel hude\'tina, kul inne hudallahi huvel huda, ve umirna li nuslime li rabbil alemin.', 'De ki: \"Allah\'ı bırakıp da bize faydası da zararı da olmayan şeylere mi yalvaralım? Allah,  bizi doğru yola ilettikten sonra,  ökçelerimiz üzerinde gerisin geri mi dönelim? Arkadaşlarının \"Bize gel\" diye doğru yola çağırdıkları; şeytanların[1] ise ayartıp şaşırttığı kimse gibi mi olalım? De ki: \"Doğru yol ancak Allah\'ın gösterdiği yoldur. Ve biz Âlemlerin Rabb\'ine teslim olmakla emrolunduk.\"', 'قل اندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد علي اعقابنا بعد اذ هدينا الله كالذي استهوته الشيطين في الارض حيران له اصحب يدعونه الي الهدي ايتنا قل ان هدي الله هو الهدي وامرنا لنسلم لرب العلمين'),
(861, 6, 72, 'وَاَنْ اَق۪يمُوا الصَّلٰوةَ وَاتَّقُوهُۜ وَهُوَ الَّـذ۪ٓي اِلَيْهِ تُحْشَرُونَ', 'Ve en ekimus salate vettekuh, ve huvellezi ileyhi tuhşerun.', '\"Bir de salatı ikame edin[1] ve O\'na karşı takvalı[2] olun. O\'dur huzuruna varıp toplanacağınız.\"', 'وان اقيموا الصلوة واتقوه وهو الذي اليه تحشرون'),
(862, 6, 73, 'وَهُوَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّۜ وَيَوْمَ يَقُولُ كُنْ فَيَكُونُۜ قَوْلُهُ الْحَقُّۜ وَلَهُ الْمُلْكُ يَوْمَ يُنْفَخُ فِي الصُّورِۜ عَالِمُ الْغَيْبِ وَالشَّهَادَةِۜ وَهُوَ الْحَك۪يمُ الْخَب۪يرُ', 'Ve huvellezi halakas semavati vel arda bil hakk, ve yevme yekulu kun fe yekun, kavluhul hakk, ve lehul mulku yevme yunfehu fis sur, alimul gaybi veş şehadeh, ve huvel hakimul habir.', 'Gökleri ve yeri hakikat[1] ile yaratan O\'dur. O gün,  \"Ol!\" der o da oluverir. O\'nun sözü haktır. Sura üfleneceği gün mülk[2] O\'nundur. Gaybı da görüneni de bilendir. O,  En İyi Hüküm Veren\'dir,  Her Şeyden Haberdar\'dır.', 'وهو الذي خلق السموت والارض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور علم الغيب والشهدة وهو الحكيم الخبير'),
(863, 6, 74, 'وَاِذْ قَالَ اِبْرٰه۪يمُ لِاَب۪يهِ اٰزَرَ اَتَـتَّخِذُ اَصْنَاماً اٰلِهَةًۚ اِنّ۪ٓي اَرٰيكَ وَقَوْمَكَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Ve iz kale ibrahimu li ebihi azere, e tettehizu esnamen aliheh, inni erake ve kavmeke fi dalalin mubin.', 'Hani İbrahim,  babası Azer\'e: \"Sen,  putları ilahlar mı ediniyorsun? Doğrusu ben seni ve halkını apaçık bir sapkınlık içinde görüyorum.\" demişti.', 'واذ قال ابرهيم لابيه ازر اتتخذ اصناما الهة اني اريك وقومك في ضلل مبين'),
(864, 6, 75, 'وَكَذٰلِكَ نُر۪ٓي اِبْرٰه۪يمَ مَلَكُوتَ السَّمٰوَاتِ وَالْاَرْضِ وَلِيَكُونَ مِنَ الْمُوقِن۪ينَ', 'Ve kezalike nuri ibrahime melekutes semavati vel ardı ve li yekune minel mukınin.', 'Böylece,  göklerin ve yerin melekutunu[1] İbrahim\'e gösteriyorduk ki kesin inananlardan olsun.', 'وكذلك نري ابرهيم ملكوت السموت والارض وليكون من الموقنين'),
(865, 6, 76, 'فَلَمَّا جَنَّ عَلَيْهِ الَّيْلُ رَاٰ كَوْكَباًۚ قَالَ هٰذَا رَبّ۪يۚ فَلَمَّٓا اَفَلَ قَالَ لَٓا اُحِبُّ الْاٰفِل۪ينَ', 'Fe lemma cenne aleyhil leylu rea kevkeba, kale haza rabbi, fe lemma efele kale la uhıbbul afilin.', 'Gece karanlığı basınca,  bir yıldız gördü. \"Rabb\'im budur.\" dedi. O,  batınca da \"Ben batanları sevmem!\" dedi.', 'فلما جن عليه اليل را كوكبا قال هذا ربي فلما افل قال لا احب الافلين'),
(866, 6, 77, 'فَلَمَّا رَاَ الْقَمَرَ بَازِغاً قَالَ هٰذَا رَبّ۪يۚ فَلَمَّٓا اَفَلَ قَالَ لَئِنْ لَمْ يَهْدِن۪ي رَبّ۪ي لَاَكُونَنَّ مِنَ الْقَوْمِ الضَّٓالّ۪ينَ', 'Fe lemma reel kamere bazigan kale haza rabbi, fe lemma efele kale le in lem yehdini rabbi le ekunenne minel kavmid dallin.', 'Sonra Ay\'ın ortaya çıkışını görünce,  \"Rabb\'im budur.\" dedi. Ay kaybolunca,  \"Eğer Rabb\'im bana doğru yolu göstermemiş olsaydı sapkın olan halktan olurdum!\" dedi.', 'فلما را القمر بازغا قال هذا ربي فلما افل قال لين لم يهدني ربي لاكونن من القوم الضالين'),
(867, 6, 78, 'فَلَمَّا رَاَ الشَّمْسَ بَازِغَةً قَالَ هٰذَا رَبّ۪ي هٰذَٓا اَكْبَرُۚ  فَلَمَّٓا اَفَلَتْ قَالَ يَا قَوْمِ اِنّ۪ي بَر۪ٓيءٌ مِمَّا تُشْرِكُونَ', 'Fe lemma reeş şemse bazigaten kale haza rabbi,haza ekber, fe lemma efelet kale ya kavmi inni beriun mimma tuşrikun.', 'Sonra Güneş\'i doğarken görünce,  \"Bu daha büyük,  Rabb\'im budur.\" dedi. Ama o batınca,  \"Ey halkım,  ben sizin şirk koştuğunuz şeylerden uzağım!\" dedi.[1]', 'فلما را الشمس بازغة قال هذا ربي هذا اكبر فلما افلت قال يقوم اني بري مما تشركون'),
(868, 6, 79, 'اِنّ۪ي وَجَّهْتُ وَجْهِيَ لِلَّذ۪ي فَطَرَ السَّمٰوَاتِ وَالْاَرْضَ حَن۪يفاً وَمَٓا اَنَا۬ مِنَ الْمُشْرِك۪ينَۚ', 'İnni veccehtu vechiye lillezi fatares semavati vel arda hanifen ve ma ene minel muşrikin.', '\"Ben hanif[1] olarak yüzümü göklere ve yere varlık özelliklerini koyana yönelttim; ben müşriklerden değilim.\"', 'اني وجهت وجهي للذي فطر السموت والارض حنيفا وما انا من المشركين'),
(869, 6, 80, 'وَحَٓاجَّهُ قَوْمُهُۜ قَالَ اَتُحَٓاجُّٓونّ۪ي فِي اللّٰهِ وَقَدْ هَدٰينِۜ وَلَٓا اَخَافُ مَا تُشْرِكُونَ بِه۪ٓ اِلَّٓا اَنْ يَشَٓاءَ رَبّ۪ي شَيْـٔاًۜ وَسِعَ رَبّ۪ي كُلَّ شَيْءٍ عِلْماًۜ اَفَلَا تَتَذَكَّرُونَ', 'Ve haccehu kavmuh, kale e tuhaccunni fillahi ve kad hedan, ve la ehafu ma tuşrıkune bihi illa en yeşae rabbi şey\'a, vesia rabbi kulle şey\'in ilma, e fe la tetezekkerun.', 'Halkı onunla tartıştı. \"Bana doğru yolu gösteren Allah hakkında benimle niçin tartışıyorsunuz? Ben,  O\'na eş koştuğunuz şeylerden korkmam. Ancak Rabb\'imin dilediği olur. Rabb\'imin İlmi Her Şeyi Kuşatmıştır. Hala düşünmeyecek misiniz?\"', 'وحاجه قومه قال اتحجوني في الله وقد هدين ولا اخاف ما تشركون به الا ان يشا ربي شيا وسع ربي كل شي علما افلا تتذكرون'),
(870, 6, 81, 'وَكَيْفَ اَخَافُ مَٓا اَشْرَكْتُمْ وَلَا تَخَافُونَ اَنَّكُمْ اَشْرَكْتُمْ بِاللّٰهِ مَا لَمْ يُنَزِّلْ بِه۪ عَلَيْكُمْ سُلْطَاناًۜ فَاَيُّ الْفَر۪يقَيْنِ اَحَقُّ بِالْاَمْنِۚ اِنْ كُنْتُمْ تَعْلَمُونَۢ', 'Ve keyfe ehafu ma eşrektum ve la tehafune ennekum eşrektum billahi ma lem yunezzıl bihi aleykum sultana, fe eyyul ferikayni ehakku bil emn, in kuntum ta\'melun.', '\"Siz,  Allah\'ın size,  hakkında hiçbir yetki[1] vermediği şeyleri O\'na ortak koşmaktan korkmazken,  ben nasıl olur da sizin ortak koştuklarınızdan korkarım?\" Bu iki taraftan hangisi emin olmaya daha layıktır? Keşke bilseydiniz!', 'وكيف اخاف ما اشركتم ولا تخافون انكم اشركتم بالله ما لم ينزل به عليكم سلطنا فاي الفريقين احق بالامن ان كنتم تعلمون'),
(871, 6, 82, 'اَلَّذ۪ينَ اٰمَنُوا وَلَمْ يَلْبِسُٓوا ا۪يمَانَهُمْ بِظُلْمٍ اُو۬لٰٓئِكَ لَهُمُ الْاَمْنُ وَهُمْ مُهْتَدُونَ۟', 'Ellezine amenu ve lem yelbisu imanehumbi zulmin ulaike lehumul emnu ve hum muhtedun.', 'İman etmiş ve imanlarına zulmü[1] bulaştırmamış olanlar var ya işte emniyet içinde olanlar da hidayete ermiş olanlar[2] da onlardır.', 'الذين امنوا ولم يلبسوا ايمنهم بظلم اوليك لهم الامن وهم مهتدون'),
(872, 6, 83, 'وَتِلْكَ حُجَّتُنَٓا اٰتَيْنَاهَٓا اِبْرٰه۪يمَ عَلٰى قَوْمِه۪ۜ نَرْفَعُ دَرَجَاتٍ مَنْ نَشَٓاءُۜ اِنَّ رَبَّكَ حَك۪يمٌ عَل۪يمٌ', 'Ve tilke huccetuna ateynaha ibrahime ala kavmih, nerfeu derecatin men neşa\', inne rabbeke hakimun alim.', 'İşte bunlar,  halkına karşı İbrahim\'e verdiğimiz huccetlerimizdir.[1] Dilediğimiz kimselerin derecelerini yükseltiriz. Kuşkusuz Rabb\'in,  En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'وتلك حجتنا اتينها ابرهيم علي قومه نرفع درجت من نشا ان ربك حكيم عليم'),
(873, 6, 84, 'وَوَهَبْنَا لَهُٓ اِسْحٰقَ وَيَعْقُوبَۜ كُلاًّ هَدَيْنَاۚ وَنُوحاً هَدَيْنَا مِنْ قَبْلُ وَمِنْ ذُرِّيَّتِه۪ دَاوُ۫دَ وَسُلَيْمٰنَ وَاَيُّوبَ وَيُوسُفَ وَمُوسٰى وَهٰرُونَۜ وَكَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَۙ', 'Ve vehebna lehu ishaka ve ya\'kub, kullen hedeyna ve nuha hedeyna min kablu ve min zurriyyetihi davude ve suleymane ve eyyube ve yusufe ve musa ve harun ve kezalike neczil muhsinin.', 'Biz ona İshak\'ı ve Ya\'kub\'u bağışladık. Her birine de hidayet[1] verdik. Daha önce Nuh\'a da hidayet verdik. O[2]\'nun soyundan Davud\'a,  Süleyman\'a,  Eyyub\'a,  Yusuf\'a,  Musa\'ya ve Harun\'a da. İşte muhsin[3] olanları böylece ödüllendiririz.', 'ووهبنا له اسحق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمن وايوب ويوسف وموسي وهرون وكذلك نجزي المحسنين'),
(874, 6, 85, 'وَزَكَرِيَّا وَيَحْيٰى وَع۪يسٰى وَاِلْيَاسَۜ كُلٌّ مِنَ الصَّالِح۪ينَۙ', 'Ve zekeriyya ve yahya ve isa ve ilyas, kullun mines salihin.', 'Zekeriyayı,  Yahyayı,  Îsa\'yı ve İlyası da. Hepsi de salihlerdendi.[1]', 'وزكريا ويحيي وعيسي والياس كل من الصلحين'),
(875, 6, 86, 'وَاِسْمٰع۪يلَ وَالْيَسَعَ وَيُونُسَ وَلُوطاًۜ وَكُلاًّ فَضَّلْنَا عَلَى الْعَالَم۪ينَۙ', 'Ve ismaile velyesea ve yunuse ve luta, ve kullen faddalna alel alemin.', 'İsmaili,  Elyesayı,  Yunusu ve Lutu da. Hepsini alemlere öncü kıldık.', 'واسمعيل واليسع ويونس ولوطا وكلا فضلنا علي العلمين'),
(876, 6, 87, 'وَمِنْ اٰبَٓائِهِمْ وَذُرِّيَّاتِهِمْ وَاِخْوَانِهِمْۚ وَاجْتَبَيْنَاهُمْ وَهَدَيْنَاهُمْ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Ve min abaihim ve zurriyyatihim ve ihvanihim, vectebeynahum ve hedeynahum ila sıratın mustekim.', 'Onların; atalarından,  soylarından ve kardeşlerinden bir kısmını da. Onları seçtik ve dosdoğru yola ilettik.', 'ومن ابايهم وذريتهم واخونهم واجتبينهم وهدينهم الي صرط مستقيم'),
(877, 6, 88, 'ذٰلِكَ هُدَى اللّٰهِ يَهْد۪ي بِه۪ مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ۜ وَلَوْ اَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ', 'Zalike hudallahi yehdi bihi men yeşau min ıbadih, ve lev eşreku le habita anhum ma kanu ya\'melun.', 'İşte bu,  Allah\'ın hidayetidir.[1] Kullarından dilediğini bununla hidayet eder. Eğer şirk koşsalardı,  yaptıkları boşa giderdi.', 'ذلك هدي الله يهدي به من يشا من عباده ولو اشركوا لحبط عنهم ما كانوا يعملون'),
(878, 6, 89, 'اُو۬لٰٓئِكَ الَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَۚ فَاِنْ يَكْفُرْ بِهَا هٰٓؤُ۬لَٓاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْماً لَيْسُوا بِهَا بِكَافِر۪ينَ', 'Ulaikellezine ateynahumul kitabe vel hukme ven nubuvveh, fe in yekfur biha haulai fe kad vekkelna biha kavmen leysu biha bi kafirin.', 'İşte bunlar,  kendilerine Kitap,  Hüküm ve Nubuvvet[1] verdiğimiz kimselerdir. Eğer onlar,  bunları küfrederse[2] ederlerse,  yerlerine bunları küfretmeyecek[2] bir halkı vekil etmişizdir.', 'اوليك الذين اتينهم الكتب والحكم والنبوة فان يكفر بها هولا فقد وكلنا بها قوما ليسوا بها بكفرين'),
(879, 6, 90, 'اُو۬لٰٓئِكَ الَّذ۪ينَ هَدَى اللّٰهُ فَبِهُدٰيهُمُ اقْتَدِهْۜ قُلْ لَٓا اَسْـَٔلُكُمْ عَلَيْهِ اَجْراًۜ اِنْ هُوَ اِلَّا ذِكْرٰى لِلْعَالَم۪ينَ۟', 'Ulaikellezine hedallahu, fe bi hudayuhumuktedih, kul la es\'elukum aleyhi ecra, in huve illa zikra lil alemin.', 'İşte bunlar,  Allah\'ın hidayet[1] ettikleridir. Onların yoluna uy. De ki: \"Ben,  buna karşılık sizden bir ücret istemiyorum. Bu ancak,  alemler için bir öğüttür.\"', 'اوليك الذين هدي الله فبهديهم اقتده قل لا اسلكم عليه اجرا ان هو الا ذكري للعلمين'),
(880, 6, 91, 'وَمَا قَدَرُوا اللّٰهَ حَقَّ قَدْرِه۪ٓ اِذْ قَالُوا مَٓا اَنْزَلَ اللّٰهُ عَلٰى بَشَرٍ مِنْ شَيْءٍۜ قُلْ مَنْ اَنْزَلَ الْكِتَابَ الَّذ۪ي جَٓاءَ بِه۪ مُوسٰى نُوراً وَهُدًى لِلنَّاسِ تَجْعَلُونَهُ قَرَاط۪يسَ تُبْدُونَهَا وَتُخْفُونَ كَث۪يراًۚ وَعُلِّمْتُمْ مَا لَمْ تَعْلَمُٓوا اَنْتُمْ وَلَٓا اٰبَٓاؤُ۬كُمْۜ قُلِ اللّٰهُۙ ثُمَّ ذَرْهُمْ ف۪ي خَوْضِهِمْ يَلْعَبُونَ', 'Ve ma kaderullahe hakka kadrihi iz kalu ma enzelallahuala beşerin min şey, kul men enzelel kitabellezi cae bihi musa nuren ve huden lin nasi tec\'alunehu karatise tubduneha ve tuhfune kesira, ve ullimtum ma lem ta\'lemu entum ve la abaukum, kulillahu summe zerhum fi havdıhim yel\'abun.', 'Allah\'ı gereği gibi takdir etmediler. \"Allah,  beşere[1] hiçbir şey indirmedi.\" dediler. De ki: \"Musa\'nın insanlar için bir nur[2] ve hidayet olarak getirdiği; sizin yazılı sayfalar haline getirip bir kısmını açıklayıp ama çoğunu da gizlediğiniz; sizin de atalarınızın da bilmediğiniz şeyler,  kendisiyle size öğretilen Kitap\'ı kim indirdi?\" Sen,  \"Allah\" de. Ve sonra bırak onları,  daldıkları bataklıkta oynaya dursunlar!', 'وما قدروا الله حق قدره اذ قالوا ما انزل الله علي بشر من شي قل من انزل الكتب الذي جا به موسي نورا وهدي للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا انتم ولا اباوكم قل الله ثم ذرهم في خوضهم يلعبون'),
(881, 6, 92, 'وَهٰذَا كِتَابٌ اَنْزَلْنَاهُ مُبَارَكٌ مُصَدِّقُ الَّذ۪ي بَيْنَ يَدَيْهِ وَلِتُنْذِرَ اُمَّ الْقُرٰى وَمَنْ حَوْلَهَاۜ وَالَّذ۪ينَ يُؤْمِنُونَ بِالْاٰخِرَةِ يُؤْمِنُونَ بِه۪ وَهُمْ عَلٰى صَلَاتِهِمْ يُحَافِظُونَ', 'Ve haza kitabun enzelnahu mubarekun musaddıkullezi beyne yedeyhi ve li tunzire ummel kura ve men havleha, vellezine yu\'minune bil ahireti yu\'minune bihi ve hum ala salatihim yuhafizun.', 'Bu,  şehirlerin anası ve çevresindekileri uyarman için sana indirdiğimiz ve kendisinden öncekileri doğrulayan kutlu bir Kitap\'tır. Ahirete iman edenler,  buna da iman ederler. Ve onlar salatlarını[1] korurlar.', 'وهذا كتب انزلنه مبارك مصدق الذي بين يديه ولتنذر ام القري ومن حولها والذين يومنون بالاخرة يومنون به وهم علي صلاتهم يحافظون'),
(882, 6, 93, 'وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً اَوْ قَالَ اُو۫حِيَ اِلَيَّ وَلَمْ يُوحَ اِلَيْهِ شَيْءٌ وَمَنْ قَالَ سَاُنْزِلُ مِثْلَ مَٓا اَنْزَلَ اللّٰهُۜ وَلَوْ تَرٰٓى اِذِ الظَّالِمُونَ ف۪ي غَمَرَاتِ الْمَوْتِ وَالْمَلٰٓئِكَةُ بَاسِطُٓوا اَيْد۪يهِمْۚ اَخْرِجُٓوا اَنْفُسَكُمْۜ اَلْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنْتُمْ تَقُولُونَ عَلَى اللّٰهِ غَيْرَ الْحَقِّ وَكُنْتُمْ عَنْ اٰيَاتِه۪ تَسْتَكْبِرُونَ', 'Ve men azlemu mimmeniftera alallahi keziben ev kale uhıye ileyye ve lem yuha ileyhi şey\'un ve men kale seunzilu misle ma enzelallah, ve lev tera iziz zalimune fi gameratil mevti vel melaiketu basitu eydihim, ahricu enfusekum, el yevme tuczevne azabel huni bima kuntum tekulune alallahi gayrel hakkı ve kuntum an ayatihi testekbirun.', 'Allah\'a karşı yalan uydurandan veya kendisine hiçbir şey vahyedilmemiş iken,  \"Bana da vahyolundu.\" diyenden ya da \"Ben de Allah\'ın indirdiği ayetlerin benzerini indireceğim.\" diyenden daha haksız kim olabilir? Melekler,  canlarını almak için ellerini uzatıp,  \"Canlarınızı verin; Allah\'a karşı gerçek olmayanı söylemenizden ve onun ayetlerine karşı büyüklük taslamanızdan dolayı bugün alçaltıcı azabı tadın.\" dediklerinde,  can çekişirlerken bu zalimleri bir görsen!', 'ومن اظلم ممن افتري علي الله كذبا او قال اوحي الي ولم يوح اليه شي ومن قال سانزل مثل ما انزل الله ولو تري اذ الظلمون في غمرت الموت والمليكة باسطوا ايديهم اخرجوا انفسكم اليوم تجزون عذاب الهون بما كنتم تقولون علي الله غير الحق وكنتم عن ايته تستكبرون'),
(883, 6, 94, 'وَلَقَدْ جِئْتُمُونَا فُرَادٰى كَمَا خَلَقْنَاكُمْ اَوَّلَ مَرَّةٍ وَتَرَكْتُمْ مَا خَوَّلْنَاكُمْ وَرَٓاءَ ظُهُورِكُمْۚ وَمَا نَرٰى مَعَكُمْ شُفَعَٓاءَكُمُ الَّذ۪ينَ زَعَمْتُمْ اَنَّهُمْ ف۪يكُمْ شُرَكٰٓؤُ۬اۜ لَقَدْ تَقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنْكُمْ مَا كُنْتُمْ تَزْعُمُونَ۟', 'Ve lekad ci\'timuna furada kema halaknakum evvele merretin ve terektum ma havvelnakum verae zuhurikum, ve ma nera meakum şufeaekumullezine zeamtum ennehum fikum şureka\', lekad tekattaa beynekum ve dalle ankum ma kuntum tez\'umun.', 'Ant olsun,  sizi ilk yarattığımız gibi yine tek başınıza Bize geldiniz. Sizi hayaline daldırdığımız şeyleri arkanızda bıraktınız. Hani! Ortaklarımız sandığınız şefaatçılarınızı yanınızda görmüyoruz. Ant olsun ki,  aranızdaki bağlar artık kopmuştur. Umduklarınızın tamamı sizden kaybolup gitmiştir.', 'ولقد جيتمونا فردي كما خلقنكم اول مرة وتركتم ما خولنكم ورا ظهوركم وما نري معكم شفعاكم الذين زعمتم انهم فيكم شركوا لقد تقطع بينكم وضل عنكم ما كنتم تزعمون'),
(884, 6, 95, 'اِنَّ اللّٰهَ فَالِقُ الْحَبِّ وَالنَّوٰىۜ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَمُخْرِجُ الْمَيِّتِ مِنَ الْحَيِّۜ ذٰلِكُمُ اللّٰهُ فَاَنّٰى تُؤْفَكُونَ', 'İnnallahe falikul habbi ven neva, yuhrıcul hayye minel meyyiti ve muhricul meyyiti minel hayy, zalikumullahu fe enna tu\'fekun.', 'Evet; Allah,  tohumu ve çekirdeği yarandır: Ölüden diriyi,  diriden de ölüyü çıkarandır. İşte budur Allah! O halde nasıl çevriliyorsunuz?', 'ان الله فالق الحب والنوي يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فاني توفكون'),
(885, 6, 96, 'فَالِقُ الْاِصْبَاحِۚ وَجَعَلَ الَّيْلَ سَكَناً وَالشَّمْسَ وَالْقَمَرَ حُسْبَاناًۜ ذٰلِكَ تَقْد۪يرُ الْعَز۪يزِ الْعَل۪يمِ', 'Falikul ısbah, ve cealel leyle sekenen veş şemse vel kamere husbana, zalike takdirul azizil alim.', 'O karanlığı yarıp sabahı çıkarandır. Geceyi bir sükunet,  Güneş\'i ve Ay\'ı bir hesap ölçüsü kılandır. İşte bunlar,  Mutlak Üstün Olan\'ın,  Her Şeyi Bilen\'in takdiridir.', 'فالق الاصباح وجعل اليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم'),
(886, 6, 97, 'وَهُوَ الَّذ۪ي جَعَلَ لَكُمُ النُّجُومَ لِتَهْتَدُوا بِهَا ف۪ي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِۜ قَدْ فَصَّلْنَا الْاٰيَاتِ لِقَوْمٍ يَعْلَمُونَ', 'Ve huvellezi ceale lekumun nucume li tehtedu biha fi zulumatil berri vel bahr, kad fassalnal ayati li kavmin ya\'lemun.', 'Karanın ve denizin karanlıklarında yönünüzü bulasınız diye yıldızları size kılavuz yapan O\'dur. Kuşkusuz akleden bir halk için ayetleri böylece ayrıntılı şekilde açıkladık.', 'وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمت البر والبحر قد فصلنا الايت لقوم يعلمون'),
(887, 6, 98, 'وَهُوَ الَّـذ۪ٓي اَنْشَاَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌۜ قَدْ فَصَّلْنَا الْاٰيَاتِ لِقَوْمٍ يَفْقَـهُونَ', 'Ve huvellezi enşeekum min nefsin vahıdetin fe mustekarrun ve mustevda\', kad fassalnal ayati li kavmin yefkahun.', 'Sizi tek bir nefisten inşa eden O\'dur. Sizin için bir kalış ve emanet olarak konuluş yeri vardır. Akleden bir halk için ayetlerimizi böylece ayrıntılı bir şekilde açıkladık.', 'وهو الذي انشاكم من نفس وحدة فمستقر ومستودع قد فصلنا الايت لقوم يفقهون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(888, 6, 99, 'وَهُوَ الَّـذ۪ٓي اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءًۚ فَاَخْرَجْنَا بِه۪ نَبَاتَ كُلِّ شَيْءٍ فَاَخْرَجْنَا مِنْهُ خَضِراً نُخْرِجُ مِنْهُ حَباًّ مُتَرَاكِباًۚ وَمِنَ النَّخْلِ مِنْ طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّاتٍ مِنْ اَعْنَابٍ وَالزَّيْتُونَ وَالرُّمَّانَ مُشْتَبِهاً وَغَيْرَ مُتَشَابِهٍۜ اُنْظُـرُٓوا اِلٰى ثَمَرِه۪ٓ اِذَٓا اَثْمَرَ وَيَنْعِه۪ۜ اِنَّ ف۪ي ذٰلِكُمْ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ', 'Ve huvellezi enzele mines semai ma\', fe ahrecna bihi nebate kulli şey\'in fe ahrecna minhu hadıran nuhricu minhu habben muterakiba, ve minen nahli min tal\'ıha kınvanun daniyetun ve cennatin min a\'nabin vez zeytune ver rummane muştebihen ve gayre muteşabih, unzuru ila semerihi iza esmere ve yen\'ıh, inne fi zalikum le ayatin li kavmin yu\'minun.', 'O,  gökten su indirendir. Onunla her türlü bitkiyi bitirdik. Ondan her çeşit bitkiyi çıkardık. Onlardan yığın yığın taneler,  hurmaların tomurcuklarından sarkan salkımlar,  birbirine hem benzeyen hem benzemeyen; üzüm bağları,  zeytin ve nar bahçeleri meydana getirdik. Meyve verirken ve meyvesi olgunlaştığında her birine bir bakın! Bunlarda iman eden bir kavim için ayetler[1] vardır.', 'وهو الذي انزل من السما ما فاخرجنا به نبات كل شي فاخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنت من اعناب والزيتون والرمان مشتبها وغير متشبه انظروا الي ثمره اذا اثمر وينعه ان في ذلكم لايت لقوم يومنون'),
(889, 6, 100, 'وَجَعَلُوا لِلّٰهِ شُرَكَٓاءَ الْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا لَهُ بَن۪ينَ وَبَنَاتٍ بِغَيْرِ عِلْمٍۜ سُبْحَانَهُ وَتَعَالٰى عَمَّا يَصِفُونَ۟', 'Ve cealu lillahi şurekael cinne ve halakahum ve haraku lehu benine ve benatin bi gayri ilm, subhanehu ve teala amma yasifun.', 'Cinleri[1] Allah\'a ortak koştular. Oysa onları da O yaratmıştır. Bir bilgiye dayanmadan O\'na oğullar ve kızlar isnat ettiler! O,  onların niteledikleri şeylerden uzaktır ve yücedir.', 'وجعلوا لله شركا الجن وخلقهم وخرقوا له بنين وبنت بغير علم سبحنه وتعلي عما يصفون'),
(890, 6, 101, 'بَد۪يعُ السَّمٰوَاتِ وَالْاَرْضِۜ اَنّٰى يَكُونُ لَهُ وَلَدٌ وَلَمْ تَكُنْ لَهُ صَاحِبَةٌۜ وَخَلَقَ كُلَّ شَيْءٍۚ وَهُوَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Bedius semavati vel ard, enna yekunu lehu veledun ve lem tekun lehu sahıbeh, ve halaka kulle şey\', ve huve bikulli şey\'in alim.', 'Bir örnek olmaksızın[1] gökleri ve yeri yaratandır. Eşi benzeri olmayanın nasıl olur da çocuğu olabilir? O,  Her Şeyi Yaratan\'dır. Ve Her Şeyi Hakkıyla Bilen\'dir.', 'بديع السموت والارض اني يكون له ولد ولم تكن له صحبة وخلق كل شي وهو بكل شي عليم'),
(891, 6, 102, 'ذٰلِكُمُ اللّٰهُ رَبُّكُمْۚ لَٓا اِلٰهَ اِلَّا هُوَۚ خَالِقُ كُلِّ شَيْءٍ فَاعْبُدُوهُۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ وَك۪يلٌ', 'Zalikumullahu rabbukum, la ilahe illa huve, haliku kulli şey\'in fa\'buduh,ve huve ala kulli şey\'in vekil.', 'İşte Rabb\'iniz Allah budur; O\'ndan başka ilah yoktur. O,  her şeyi yaratandır. O halde O\'na kulluk edin. O,  Her Şeye Vekil\'dir.', 'ذلكم الله ربكم لا اله الا هو خلق كل شي فاعبدوه وهو علي كل شي وكيل'),
(892, 6, 103, 'لَا تُدْرِكُهُ الْاَبْصَارُۘ وَهُوَ يُدْرِكُ الْاَبْصَارَۚ وَهُوَ اللَّط۪يفُ الْخَب۪يرُ', 'La tudrikuhul ebsaru ve huve yudrikul ebsar ve huvel latiful habir.', 'Gözler O\'nu idrak edemez; O,  gözleri idrak eder. O,  Bütün Ayrıntıları Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'لا تدركه الابصر وهو يدرك الابصر وهو اللطيف الخبير'),
(893, 6, 104, 'قَدْ جَٓاءَكُمْ بَصَٓائِرُ مِنْ رَبِّكُمْۚ فَمَنْ اَبْصَرَ فَلِنَفْسِه۪ۚ وَمَنْ عَمِيَ فَعَلَيْهَاۜ وَمَٓا اَنَا۬ عَلَيْكُمْ بِحَف۪يظٍ', 'Kad caekum basairu min rabbikum fe men ebsara fe li nefsih ve men amiye fe aleyha, ve ma ene aleykum bi hafiz.', 'Rabb\'inizden size basiret[1] verilmiştir. Kim gerçeği görürse[2] kendi yararınadır,  kim de gerçeği görmezse[3] kendi aleyhinedir. Ben üzerinize bekçi değilim.', 'قد جاكم بصاير من ربكم فمن ابصر فلنفسه ومن عمي فعليها وما انا عليكم بحفيظ'),
(894, 6, 105, 'وَكَذٰلِكَ نُصَرِّفُ الْاٰيَاتِ وَلِيَقُولُوا دَرَسْتَ وَلِنُبَيِّنَهُ لِقَوْمٍ يَعْلَمُونَ', 'Ve kezalike nusarriful ayati ve li yekulu dereste ve li nubeyyinehu li kavmin ya\'lemun.', 'İşte böylece Biz,  ayetleri döne döne açıklıyoruz. Varsın \"Sen ders almışsın.\" desinler. Oysa bilen[2] bir halk için onu[3] ayrıntılı bir şekilde açıklıyoruz.', 'وكذلك نصرف الايت وليقولوا درست ولنبينه لقوم يعلمون'),
(895, 6, 106, 'اِتَّبِعْ مَٓا اُو۫حِيَ اِلَيْكَ مِنْ رَبِّكَۚ لَٓا اِلٰهَ اِلَّا هُوَۚ وَاَعْرِضْ عَنِ الْمُشْرِك۪ينَ', 'İttebi\' ma uhıye ileyke min rabbik, la ilahe illa huve, ve a\'rıd anil muşrikin.', 'Rabb\'inden sana vahyolunana uy,  O\'ndan başka ilah yoktur. Ortak koşanlara aldırma.', 'اتبع ما اوحي اليك من ربك لا اله الا هو واعرض عن المشركين'),
(896, 6, 107, 'وَلَوْ شَٓاءَ اللّٰهُ مَٓا اَشْرَكُواۜ وَمَا جَعَلْنَاكَ عَلَيْهِمْ حَف۪يظاًۚ وَمَٓا اَنْتَ عَلَيْهِمْ بِوَك۪يلٍ', 'Ve lev şaallahu ma eşreku, ve ma cealnake aleyhim hafiza, ve ma ente aleyhim bi vekil.', 'Eğer Allah dileseydi[1],  onlar müşrik olmazlardı. Seni onların üzerine koruyucu yapmadık. Ve Sen onların vekili de değilsin.', 'ولو شا الله ما اشركوا وما جعلنك عليهم حفيظا وما انت عليهم بوكيل'),
(897, 6, 108, 'وَلَا تَسُبُّوا الَّذ۪ينَ يَدْعُونَ مِنْ دُونِ اللّٰهِ فَيَسُبُّوا اللّٰهَ عَدْواً بِغَيْرِ عِلْمٍۜ   كَذٰلِكَ زَيَّنَّا لِكُلِّ اُمَّةٍ عَمَلَهُمْ ثُمَّ اِلٰى رَبِّهِمْ مَرْجِعُهُمْ فَيُنَبِّئُهُمْ بِمَا كَانُوا يَعْمَلُونَ', 'Ve la tesubbullezine yed\'une min dunillahi fe yesubbullahe adven bi gayri ilm, kezalike zeyyenna li kulli ummetin amelehum summe ila rabbihim merciuhum fe yunebbiuhum bima kanu ya\'melun.', 'Allah\'ın yanı sıra yöneldiklerine hakaret etmeyin ki onlar da hadlerini aşarak cahillikle Allah\'a hakaret etmesinler. Her ümmetin yaptıklarını,  kendilerine süslü gösterdik. Sonra Rabb\'lerine döneceklerdir. O,  onlara yaptıklarını haber verecektir.[1]', 'ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل امة عملهم ثم الي ربهم مرجعهم فينبيهم بما كانوا يعملون'),
(898, 6, 109, 'وَاَقْسَمُوا بِاللّٰهِ جَهْدَ اَيْمَانِهِمْ لَئِنْ جَٓاءَتْهُمْ اٰيَةٌ لَيُؤْمِنُنَّ بِهَاۜ قُلْ اِنَّمَا الْاٰيَاتُ عِنْدَ اللّٰهِ وَمَا يُشْعِرُكُمْۙ اَنَّـهَٓا اِذَا جَٓاءَتْ لَا يُؤْمِنُونَ', 'Ve aksemu billahi cehde eymanihim le in caethum ayetun le yu\'minunne bih, kul innemel ayatu indallahi ve ma yuş\'irukum enneha iza caet la yu\'minun.', 'Eğer kendilerine bir ayet[1] gelirse,  ona[2] inanacaklarına dair kesin bir yeminle[3] Allah\'a yemin ettiler. De ki: \"Âyetler[4] ancak Allah\'ın yanındadır.\" O mucize gelmiş olsa da onların yine de inanmayacaklarının bilincinde değil misiniz?', 'واقسموا بالله جهد ايمنهم لين جاتهم اية ليومنن بها قل انما الايت عند الله وما يشعركم انها اذا جات لا يومنون'),
(899, 6, 110, 'وَنُقَلِّبُ اَفْـِٔدَتَهُمْ وَاَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِه۪ٓ اَوَّلَ مَرَّةٍ وَنَذَرُهُمْ ف۪ي طُغْيَانِهِمْ يَعْمَهُونَ۟', 'Ve nukallibu ef\'idetehum ve ebsarehum kema lem yu\'minu bihi evvele merretin ve nezeruhum fi tugyanihim ya\'mehun.', 'İlkin ona iman etmedikleri gibi[1],  onların gönüllerini ve basiretlerini[2] tersyüz ederiz ve onları azgınlıkları içinde bocalar halde bırakırız.', 'ونقلب افدتهم وابصرهم كما لم يومنوا به اول مرة ونذرهم في طغينهم يعمهون'),
(900, 6, 111, 'وَلَوْ اَنَّـنَا نَزَّلْـنَٓا اِلَيْهِمُ الْمَلٰٓئِكَةَ وَكَلَّمَهُمُ الْمَوْتٰى وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَيْءٍ قُبُلاً مَا كَانُوا لِيُؤْمِنُٓوا اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُ وَلٰكِنَّ اَكْثَرَهُمْ يَجْهَلُونَ', 'Ve lev ennena nezzelna ileyhimul melaikete ve kellemehumulmevta ve haşerna aleyhim kulle şey\'in kubulen ma kanu li yu\'minu illa en yeşaallahu ve lakinne ekserehum yechelun.', 'Eğer onlara gerçekten melekleri indirmiş olsaydık,  ölüler onlarla konuşsaydı,  her şeyi karşılarında toplasaydık,  Allah dilemedikçe[1],  yine de iman etmezlerdi. Fakat onların çoğu cahillik[2] ederler.', 'ولو اننا نزلنا اليهم المليكة وكلمهم الموتي وحشرنا عليهم كل شي قبلا ما كانوا ليومنوا الا ان يشا الله ولكن اكثرهم يجهلون'),
(901, 6, 112, 'وَكَذٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُواًّ شَيَاط۪ينَ الْاِنْسِ وَالْجِنِّ يُوح۪ي بَعْضُهُمْ اِلٰى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُوراًۜ وَلَوْ شَٓاءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'Ve kezalike cealna li kulli nebiyyin aduvven şeyatinel insi vel cinni, yuhi ba\'duhum ila ba\'dın zuhrufel kavli gurura, ve lev şae rabbuke ma fealuhu fe zerhum ve ma yefterun.', 'Böylece her nebiye ins[1] ve cinn şeytanları düşman yaptık. Onların kimileri kimilerine aldatıcı yaldızlı sözler vahyederler.[2] Eğer Rabb\'in dileseydi bunu yapamazlardı. Onları iftiralarıyla baş başa bırak.', 'وكذلك جعلنا لكل نبي عدوا شيطين الانس والجن يوحي بعضهم الي بعض زخرف القول غرورا ولو شا ربك ما فعلوه فذرهم وما يفترون'),
(902, 6, 113, 'وَلِتَصْغٰٓى اِلَيْهِ اَفْـِٔدَةُ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا مَا هُمْ مُقْتَرِفُونَ', 'Ve li tesga ileyhi ef\'idetullezine la yu\'minune bil ahıreti ve li yerdavhu ve li yakterifu ma hum mukterifun.', 'Böylece ahirete inanmayanların gönülleri ona[1] yönelsin,  ondan hoşlansınlar: yaptıkları şeyleri yapmaya devam etsinler.[2]', 'ولتصغي اليه افدة الذين لا يومنون بالاخرة وليرضوه وليقترفوا ما هم مقترفون'),
(903, 6, 114, 'اَفَغَيْرَ اللّٰهِ اَبْتَغ۪ي حَكَماً وَهُوَ الَّـذ۪ٓي اَنْزَلَ اِلَيْكُمُ الْكِتَابَ مُفَصَّلاًۜ وَالَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يَعْلَمُونَ اَنَّهُ مُنَزَّلٌ مِنْ رَبِّكَ بِالْحَقِّ فَلَا تَكُونَنَّ مِنَ الْمُمْتَر۪ينَ', 'E fe gayrallahi ebtegi hakemen ve huvellezi enzele ileykumul kitabe mufassala, vellezine ateynahumul kitabe ya\'lemune ennehu munezzelun min rabbike bil hakkı fe la tekunenne minel mumterin.', '\"O,  size Kitap\'ı ayrıntılı olarak indirmişken,  Allah\'tan başka bir hakem mi arayayım?\" Kendilerine Kitap verdiklerimiz,  bilirler ki bu Rabb\'inden Hakk[1] olarak indirilmiştir. O halde,  sakın kuşku duyanlardan olma!', 'افغير الله ابتغي حكما وهو الذي انزل اليكم الكتب مفصلا والذين اتينهم الكتب يعلمون انه منزل من ربك بالحق فلا تكونن من الممترين'),
(904, 6, 115, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقاً وَعَدْلاًۜ لَا مُبَدِّلَ لِكَلِمَاتِه۪ۚ وَهُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve temmet kelimetu rabbike sıdkan ve adla, la mubeddile li kelimatih, ve huves semiul alim.', 'Rabb\'inin kelimesi[1] doğruluk ve adaletçe tamdır. O\'nun kelimelerini değiştirebilecek yoktur. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'وتمت كلمت ربك صدقا وعدلا لا مبدل لكلمته وهو السميع العليم'),
(905, 6, 116, 'وَاِنْ تُطِـعْ اَكْثَرَ مَنْ فِي الْاَرْضِ يُضِلُّوكَ عَنْ سَب۪يلِ اللّٰهِۜ اِنْ يَتَّبِعُونَ اِلَّا الظَّنَّ وَاِنْ هُمْ اِلَّا يَخْرُصُونَ', 'Ve in tutı\' eksere men fil ardı yudılluke an sebilillah, in yettebiune illez zanne ve in hum illa yahrusun.', 'Eğer yeryüzündekilerin çoğunluğuna[1] uyarsan,  seni Allah\'ın yolundan saptırırlar. Onlar ancak zanna uyarlar ve onlar yalnız var sayıyorlar.', 'وان تطع اكثر من في الارض يضلوك عن سبيل الله ان يتبعون الا الظن وان هم الا يخرصون'),
(906, 6, 117, 'اِنَّ رَبَّكَ هُوَ اَعْلَمُ مَنْ يَضِلُّ عَنْ سَب۪يلِه۪ۚ وَهُوَ اَعْلَمُ بِالْمُهْتَد۪ينَ', 'İnne rabbeke huve a\'lemu men yadıllu an sebilih, ve huve a\'lemu bil muhtedin.', 'Rabb\'in,  yolundan sapanları en iyi bilendir. Ve O,  doğru yolda olanları da en iyi bilendir.', 'ان ربك هو اعلم من يضل عن سبيله وهو اعلم بالمهتدين'),
(907, 6, 118, 'فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللّٰهِ عَلَيْهِ اِنْ كُنْتُمْ بِاٰيَاتِه۪ مُؤْمِن۪ينَ', 'Fe kulu mimma zukiresmullahi aleyhi in kuntum bi ayatihi mu\'minin.', 'Eğer Allah\'ın ayetlerine inanıyorsanız,  üzerine Allah\'ın adı anılanlardan yiyin.', 'فكلوا مما ذكر اسم الله عليه ان كنتم بايته مومنين'),
(908, 6, 119, 'وَمَا لَكُمْ اَلَّا تَأْكُلُوا مِمَّا ذُكِرَ اسْمُ اللّٰهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ اِلَّا مَا اضْطُرِرْتُمْ اِلَيْهِۜ وَاِنَّ كَث۪يراً لَيُضِلُّونَ بِاَهْوَٓائِهِمْ بِغَيْرِ عِلْمٍۜ اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِالْمُعْتَد۪ينَ', 'Ve ma lekum ella te\'kulu mimma zukiresmullahi aleyhi ve kad fassale lekum ma harreme aleykum illa madturirtum ileyh, ve inne kesiren le yudıllune bi ehvaihim bi gayri ilm, inne rabbeke huve a\'lemu bil mu\'tedin.', 'Size ne oluyor ki,  üzerine Allah\'ın adı anılmış olanlardan yemiyorsunuz? Oysaki O,  mecbur yemek zorunda kaldıklarınız dışında[1],  haram kıldığı şeyleri size ayrıntılı olarak açıklamıştır. Doğrusu birçokları bir bilgiye dayanmaksızın hevasına[2] uyarak saptırıyorlar. Kuşkusuz Rabb\'in haddi aşanları en iyi bilendir.', 'وما لكم الا تاكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم الا ما اضطررتم اليه وان كثيرا ليضلون باهوايهم بغير علم ان ربك هو اعلم بالمعتدين'),
(909, 6, 120, 'وَذَرُوا ظَاهِرَ الْاِثْمِ وَبَاطِنَهُۜ اِنَّ الَّذ۪ينَ يَكْسِبُونَ الْاِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا يَقْتَرِفُونَ', 'Ve zeru zahirel ismi ve batıneh, innellezine yeksibunel isme seyuczevne bima kanu yakterifun.', 'Günahın açığını da gizlisini de bırakın. Günah işleyenler,  işledikleri günahın karşılığını göreceklerdir.', 'وذروا ظهر الاثم وباطنه ان الذين يكسبون الاثم سيجزون بما كانوا يقترفون'),
(910, 6, 121, 'وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللّٰهِ عَلَيْهِ وَاِنَّهُ لَفِسْقٌۜ وَاِنَّ الشَّيَاط۪ينَ لَيُوحُونَ اِلٰٓى اَوْلِيَٓائِهِمْ لِيُجَادِلُوكُمْۚ وَاِنْ اَطَعْتُمُوهُمْ اِنَّكُمْ لَمُشْرِكُونَ۟', 'Ve la te\'kulu mimma lem yuzkerismullahi aleyhi ve innehu le fısk, ve inneş şeyatine le yuhune ila evliyaihim li yucadilukum ve in eta\'tumuhum innekum le muşrikun.', 'Üzerine Allah\'ın adı anılmayanlardan yemeyin. Çünkü o fısktır.[1] Şeytanlar kendi evliyasına[2] sizinle mücadele etmelerini vahyederler[3],  eğer onlara uyarsanız kuşkusuz siz de müşriklerden olursunuz.', 'ولا تاكلوا مما لم يذكر اسم الله عليه وانه لفسق وان الشيطين ليوحون الي اوليايهم ليجدلوكم وان اطعتموهم انكم لمشركون'),
(911, 6, 122, 'اَوَمَنْ كَانَ مَيْتاً فَاَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُوراً يَمْش۪ي بِه۪ فِي النَّاسِ كَمَنْ مَثَلُهُ فِي الظُّلُمَاتِ لَيْسَ بِخَارِجٍ مِنْهَاۜ   كَذٰلِكَ زُيِّنَ لِلْكَافِر۪ينَ مَا كَانُوا يَعْمَلُونَ', 'E ve men kane meyten fe ahyeynahu ve cealna lehu nuren yemşi bihi fin nasi ke men meseluhu fiz zulumati leyse bi haricin minha, kezalike zuyyine lil kafirine ma kanu ya\'melun.', 'Ölü iken[1] dirilttiğimiz;[1] ona,  insanlar arasında,  onunla yürüyeceği bir nur[2] verdiğimiz bir kimse; karanlıklar içinde kalıp bir türlü çıkamayan kimse gibi olur mu? Kafirlerin yaptıkları,  kendilerine sevimli gösterildi.', 'اومن كان ميتا فاحيينه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمت ليس بخارج منها كذلك زين للكفرين ما كانوا يعملون'),
(912, 6, 123, 'وَكَذٰلِكَ جَعَلْنَا ف۪ي كُلِّ قَرْيَةٍ اَكَابِرَ مُجْرِم۪يهَا لِيَمْكُرُوا ف۪يهَاۜ وَمَا يَمْكُرُونَ اِلَّا بِاَنْفُسِهِمْ وَمَا يَشْعُرُونَ', 'Ve kezalike cealna fi kulli karyetin ekabire mucrimiha li yemkuru fiha, ve ma yemkurune illa bi enfusihim ve ma yeş\'urun.', 'Böylece her kentin ileri gelenlerini,  aldatmalarından ötürü oranın suçluları yaptık. Onlar kendilerinden başkasını aldatmıyorlar ama bunun bilincinde değiller.', 'وكذلك جعلنا في كل قرية اكبر مجرميها ليمكروا فيها وما يمكرون الا بانفسهم وما يشعرون'),
(913, 6, 124, 'وَاِذَا جَٓاءَتْهُمْ اٰيَةٌ قَالُوا لَنْ نُؤْمِنَ حَتّٰى نُؤْتٰى مِثْلَ مَٓا اُو۫تِيَ رُسُلُ اللّٰهِۜ اَللّٰهُ اَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۜ سَيُص۪يبُ الَّذ۪ينَ اَجْرَمُوا صَغَارٌ عِنْدَ اللّٰهِ وَعَذَابٌ شَد۪يدٌ بِمَا كَانُوا يَمْكُرُونَ', 'Ve iza caethum ayetun kalu len nu\'mine hatta nu\'ta misle ma utiye rusulullah, allahu a\'lemu haysu yec\'alu risaleteh, seyusibullezine ecremu sagarun indallahi ve azabun şedidun bima kanu yemkurun.', 'Onlara bir ayet geldiği[1] zaman,  \"Allah\'ın resulüne verilenin benzeri bize de verilmedikçe asla iman etmeyiz.\" derler. Allah,  resullük görevini kime vereceğini en iyi bilendir. Suç işleyenlere,  yaptıkları aldatmalar yüzünden,  Allah katında bir aşağılanma ve şiddetli bir azap vardır.', 'واذا جاتهم اية قالوا لن نومن حتي نوتي مثل ما اوتي رسل الله الله اعلم حيث يجعل رسالته سيصيب الذين اجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون'),
(914, 6, 125, 'فَمَنْ يُرِدِ اللّٰهُ اَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْاِسْلَامِۚ وَمَنْ يُرِدْ اَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقاً حَرَجاً كَاَنَّمَا يَصَّعَّدُ فِي السَّمَٓاءِۜ   كَذٰلِكَ يَجْعَلُ اللّٰهُ الرِّجْسَ عَلَى الَّذ۪ينَ لَا يُؤْمِنُونَ', 'Fe men yuridillahu en yehdiyehu yeşrah sadrehu lil islam, ve men yurid en yudıllehu yec\'al sadrehu dayyikan haracen, ke ennema yassa\'adu fis semai, kezalike yec\'alullahur ricse alallezine la yu\'minun.', 'Allah,  kime hidayeti hak ederse[1] onun kalbini İslam\'a açar; kime de sapkınlğı hak ederse[1] göğe çıkmaya çalışıyormuşçasına kalbini daraltır,  sıkar. Allah,  inanmayanları işte böyle sıkıntı içinde bırakır.', 'فمن يرد الله ان يهديه يشرح صدره للاسلم ومن يرد ان يضله يجعل صدره ضيقا حرجا كانما يصعد في السما كذلك يجعل الله الرجس علي الذين لا يومنون'),
(915, 6, 126, 'وَهٰذَا صِرَاطُ رَبِّكَ مُسْتَق۪يماًۜ قَدْ فَصَّلْنَا الْاٰيَاتِ لِقَوْمٍ يَذَّكَّرُونَ', 'Ve haza sıratu rabbike mustekim, kad fassalnal ayati li kavmin yezzekkerun.', 'Rabb\'inin dosdoğru yolu işte budur. Gerçekten öğüt alan bir halk için ayetleri ayrıntılı olarak açıkladık.', 'وهذا صرط ربك مستقيما قد فصلنا الايت لقوم يذكرون'),
(916, 6, 127, 'لَهُمْ دَارُ السَّلَامِ عِنْدَ رَبِّهِمْ وَهُوَ وَلِيُّهُمْ بِمَا كَانُوا يَعْمَلُونَ', 'Lehum darus selami inde rabbihim ve huve veliyyuhum bima kanu ya\'melun.', 'Onlar için Rabb\'leri yanında bir selam[1] yurdu vardır. O,  yaptıklarından dolayı onların velisidir.[2]', 'لهم دار السلم عند ربهم وهو وليهم بما كانوا يعملون'),
(917, 6, 128, 'وَيَوْمَ يَحْشُرُهُمْ جَم۪يعاًۚ يَا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُمْ مِنَ الْاِنْسِۚ وَقَالَ اَوْلِيَٓاؤُ۬هُمْ مِنَ الْاِنْسِ رَبَّـنَا اسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَٓا اَجَلَنَا الَّـذ۪ٓي اَجَّلْتَ لَنَاۜ قَالَ النَّارُ مَثْوٰيكُمْ خَالِد۪ينَ ف۪يهَٓا اِلَّا مَا شَٓاءَ اللّٰهُۜ اِنَّ رَبَّكَ حَك۪يمٌ عَل۪يمٌ', 'Ve yevme yahşuruhum cemia, ya ma\'şerel cinni kadisteksertum minel ins ve kale evliyauhum minel insi rabbenestemtea ba\'duna biba\'dın ve belagna ecelenellezi eccelte lena, kalen naru mesvakum halidine fiha illa ma şaallahu, inne rabbeke hakimun alim.', 'Hepsini bir araya topladığı gün: \"Ey cinn[1] topluluğu! İnsten[1] çoğaldınız![2] Onların insten evliyası[3] da \"Ey Rabb\'imiz! Biz,  birbirimiz den yararlandık. Ve bizim için belirlediğin ecele ulaştık.\" derler. Ateş,  varacağınız yerdir. Allah\'ın dilemesi hariç orada devamlı kalacaksınız.\" der. Kuşkusuz Rabb\'in En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'ويوم يحشرهم جميعا يمعشر الجن قد استكثرتم من الانس وقال اولياوهم من الانس ربنا استمتع بعضنا ببعض وبلغنا اجلنا الذي اجلت لنا قال النار مثويكم خلدين فيها الا ما شا الله ان ربك حكيم عليم'),
(918, 6, 129, 'وَكَذٰلِكَ نُوَلّ۪ي بَعْضَ الظَّالِم۪ينَ بَعْضاً بِمَا كَانُوا يَكْسِبُونَ۟', 'Ve kezalike nuvelli ba\'daz zalimine ba\'dan bima kanu yeksibun.', 'İşte böylece kazandıklarından dolayı,  zalimlerin bir kısmını diğerlerinin peşine takarız.[1]', 'وكذلك نولي بعض الظلمين بعضا بما كانوا يكسبون'),
(919, 6, 130, 'يَا مَعْشَرَ الْجِنِّ وَالْاِنْسِ اَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ اٰيَات۪ي وَيُنْذِرُونَكُمْ لِقَٓاءَ يَوْمِكُمْ هٰذَاۜ قَالُوا شَهِدْنَا عَلٰٓى اَنْفُسِنَا وَغَرَّتْهُمُ الْحَيٰوةُ الدُّنْيَا وَشَهِدُوا عَلٰٓى اَنْفُسِهِمْ اَنَّهُمْ كَانُوا كَافِر۪ينَ', 'Ya ma\'şerel cinni vel insi e lem ye\'tikum rusulun minkum yakussune aleykum ayati ve yunzirunekum likae yevmikum haza, kalu şehidna ala enfusina ve garrethumul hayatud dunya ve şehidu ala enfusihim ennehum kanu kafirin.', '\"Ey cinn ve ins[1] topluluğu! İçinizden,  size ayetlerimi aktaran ve bugünle karşılaşacağınıza dair sizi uyaran resuller gelmedi mi?\" \"Kendi aleyhimize tanığız\" derler. Dünya hayatı onları aldattı,  kendilerinin Kafirler[2] olduklarına tanıklık ettiler.', 'يمعشر الجن والانس الم ياتكم رسل منكم يقصون عليكم ايتي وينذرونكم لقا يومكم هذا قالوا شهدنا علي انفسنا وغرتهم الحيوة الدنيا وشهدوا علي انفسهم انهم كانوا كفرين'),
(920, 6, 131, 'ذٰلِكَ اَنْ لَمْ يَكُنْ رَبُّكَ مُهْلِكَ الْقُرٰى بِظُلْمٍ وَاَهْلُهَا غَافِلُونَ', 'Zalike en lem yekun rabbuke muhlikel kura bi zulmin ve ehluha gafilun.', 'Gerçek şu ki: Rabb\'in,  gerçeklerden habersiz bir beldenin halkını haksız yere asla yok etmez.', 'ذلك ان لم يكن ربك مهلك القري بظلم واهلها غفلون'),
(921, 6, 132, 'وَلِكُلٍّ دَرَجَاتٌ مِمَّا عَمِلُواۜ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا يَعْمَلُونَ', 'Ve li kullin derecatun mimma amilu, ve ma rabbukebi gafilin amma ya\'melun.', 'Herkesin yaptığı işe göre derecesi vardır. Rabb\'in onların yaptıklarından habersiz değildir.', 'ولكل درجت مما عملوا وما ربك بغفل عما يعملون'),
(922, 6, 133, 'وَرَبُّكَ الْغَنِيُّ ذُوالرَّحْمَةِۜ اِنْ يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنْ بَعْدِكُمْ مَا يَشَٓاءُ كَمَٓا اَنْشَاَكُمْ مِنْ ذُرِّيَّةِ قَوْمٍ اٰخَر۪ينَۜ', 'Ve rabbukel ganiyyu zur rahmeh, in yeşe\' yuzhibkum ve yestahlif min ba\'dikum ma yeşau kema enşeekum min zurriyyeti kavmin aharin.', 'Rabb\'in Hiçbir Şeye Muhtaç Olmayan\'dır,  Rahmeti Bol Olan\'dır. Eğer dilerse sizi yok edip,  yerinize dilediğini getirir. Tıpkı sizi başka toplumların soyundan var ettiği gibi.', 'وربك الغني ذو الرحمة ان يشا يذهبكم ويستخلف من بعدكم ما يشا كما انشاكم من ذرية قوم اخرين'),
(923, 6, 134, 'اِنَّ مَا تُوعَدُونَ لَاٰتٍۙ وَمَٓا اَنْتُمْ بِمُعْجِز۪ينَ', 'İnne ma tuadune le atin ve ma entum bi mu\'cizin.', 'Size yapılan uyarı kesinlikle yerine gelecektir. Siz bunu önleyemezsiniz.', 'ان ما توعدون لات وما انتم بمعجزين'),
(924, 6, 135, 'قُلْ يَا قَوْمِ اعْمَلُوا عَلٰى مَكَانَتِكُمْ اِنّ۪ي عَامِلٌۚ فَسَوْفَ تَعْلَمُونَۙ مَنْ تَكُونُ لَهُ عَاقِبَةُ الدَّارِۜ اِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', 'Kul ya kavmi\'melu ala ma kanetikum inni amil, fe sevfe ta\'lemune men tekunu lehu akıbetud dar, innehu la yuflihuz zalimun.', 'De ki: \"Ey halkım! Elinizden geleni yapın. Ben de yapacağım. İleride göreceksiniz! Son yurt kimin olacak? Kuşkusuz zalimler kurtuluşa eremezler.', 'قل يقوم اعملوا علي مكانتكم اني عامل فسوف تعلمون من تكون له عقبة الدار انه لا يفلح الظلمون'),
(925, 6, 136, 'وَجَعَلُوا لِلّٰهِ مِمَّا ذَرَاَ مِنَ الْحَرْثِ وَالْاَنْعَامِ نَص۪يباً فَقَالُوا هٰذَا لِلّٰهِ بِزَعْمِهِمْ وَهٰذَا لِشُرَكَٓائِنَاۚ فَمَا كَانَ لِشُرَكَٓائِهِمْ فَلَا يَصِلُ اِلَى اللّٰهِۚ وَمَا كَانَ لِلّٰهِ فَهُوَ يَصِلُ اِلٰى شُرَكَٓائِهِمْۜ سَٓاءَ مَا يَحْكُمُونَ', 'Ve cealu lillahi mimma zeree minel harsi vel en\'ami nasibenfe kalu haza lillahi bi za\'mihim ve haza li şurekaina, fe ma kane li şurekaihim fe la yasılu ilallahi ve ma kane lillahi fe huve yasilu ila şurekaihim, sae ma yahkumun.', 'Allah\'ın var ettiği ziraat ürünlerinden ve hayvanlardan,  O\'na bir pay ayırıp,  zanlarınca: \"Bu Allah\'a,  bu da ortaklarımızadır.\" dediler. Ortakları için ayrılan,  Allah\'a ulaşmıyor,  Allah için ayrılan,  ortaklarına ulaşıyor.[1] Ne kötü hüküm veriyorlar.', 'وجعلوا لله مما ذرا من الحرث والانعم نصيبا فقالوا هذا لله بزعمهم وهذا لشركاينا فما كان لشركايهم فلا يصل الي الله وما كان لله فهو يصل الي شركايهم سا ما يحكمون'),
(926, 6, 137, 'وَكَذٰلِكَ زَيَّنَ لِكَث۪يرٍ مِنَ الْمُشْرِك۪ينَ قَتْلَ اَوْلَادِهِمْ شُرَكَٓاؤُ۬هُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ د۪ينَهُمْۜ وَلَوْ شَٓاءَ اللّٰهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'Ve kezalike zeyyene li kesirin minel muşrikine katle evladihim şurekauhum li yurduhum ve li yelbisu aleyhim dinehum, ve lev şaellahu ma fealuhu fe zerhum ve ma yefterun.', 'Böylece ortakları[1],  müşriklerden çoğuna evlatlarını öldürmeyi[2] hoş gösterdiler.[3] Hem onları mahvetmek hem de dinlerini karmakarışık etmek için. Eğer Allah dileseydi bunu yapamazlardı. Öyleyse onları uydurduklarıyla baş başa bırak.', 'وكذلك زين لكثير من المشركين قتل اولدهم شركاوهم ليردوهم وليلبسوا عليهم دينهم ولو شا الله ما فعلوه فذرهم وما يفترون'),
(927, 6, 138, 'وَقَالُوا هٰذِه۪ٓ اَنْعَامٌ وَحَرْثٌ حِجْرٌۘ لَا يَطْعَمُهَٓا اِلَّا مَنْ نَشَٓاءُ بِزَعْمِهِمْ وَاَنْعَامٌ حُرِّمَتْ ظُهُورُهَا وَاَنْعَامٌ لَا يَذْكُرُونَ اسْمَ اللّٰهِ عَلَيْهَا افْتِرَٓاءً عَلَيْهِۜ سَيَجْز۪يهِمْ بِمَا كَانُوا يَفْتَرُونَ', 'Ve kalu hazihi en\'amun ve harsun hicrun la yat\'amuha illa men neşau bi za\'mihim ve en\'amun hurrimet zuhuruha ve en\'amun la yezkurunesmallahi aleyhaftiraen aleyh se yeczihim bima kanu yefterun.', 'Kendi zanlarınca: \"Bu davarlar ve ekinler dokunulmazdır. Onları dilediklerimizden[1] başkası yiyemez. Şu davarların da sırtları haram edilmiştir.\"[2] derler. O\'na karşı iftira ederek bir kısım davarların da üzerine Allah\'ın adını anmazlar. O,  iftiraları yüzünden Allah onları iftiraları ile cezalandıracaktır.', 'وقالوا هذه انعم وحرث حجر لا يطعمها الا من نشا بزعمهم وانعم حرمت ظهورها وانعم لا يذكرون اسم الله عليها افترا عليه سيجزيهم بما كانوا يفترون'),
(928, 6, 139, 'وَقَالُوا مَا ف۪ي بُطُونِ هٰذِهِ الْاَنْعَامِ خَالِصَةٌ لِذُكُورِنَا وَمُحَرَّمٌ عَلٰٓى اَزْوَاجِنَاۚ وَاِنْ يَكُنْ مَيْتَةً فَهُمْ ف۪يهِ شُرَكَٓاءُۜ سَيَجْز۪يهِمْ وَصْفَهُمْۜ اِنَّهُ حَك۪يمٌ عَل۪يمٌ', 'Ve kalu ma fi butuni hazihil en\'ami halisatun li zukurina ve muharremun ala ezvacina, ve in yekun meyteten fe hum fihi şurekau, se yeczihim vasfehum, innehu hakimun alim.', '\"Bu davarların karınlarında bulunanlar yalnızca erkeklerimize ait olup,  kadınlarımıza haram kılınmıştır. Eğer ölü doğarsa o zaman herkes onda ortaktır.\" dediler. Bu nitelendirmelerinin cezasını görecekler. O,  En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'وقالوا ما في بطون هذه الانعم خالصة لذكورنا ومحرم علي ازوجنا وان يكن ميتة فهم فيه شركا سيجزيهم وصفهم انه حكيم عليم'),
(929, 6, 140, 'قَدْ خَسِرَ الَّذ۪ينَ قَتَلُٓوا اَوْلَادَهُمْ سَفَهاً بِغَيْرِ  عِلْمٍ  وَحَرَّمُوا مَا رَزَقَهُمُ اللّٰهُ افْتِرَٓاءً عَلَى اللّٰهِۜ قَدْ ضَلُّوا وَمَا كَانُوا مُهْتَد۪ينَ۟', 'Kad hasirellezine katelu evladehum sefehan bi gayri ilmin ve harremu ma rezekahumullahuftiraen alallah, kad dallu ve ma kanu muhtedin.', 'Bir bilgiye dayanmadan,  akılsızca çocuklarını öldürenler ve Allah\'ın rızık olarak verdiklerini,  Allah adına iftira ederek haram sayanlar,  gerçekten hüsrana uğramışlardır. Gerçekten onlar sapkınlaşmışlar ve doğru yolu bulamamışlardır.', 'قد خسر الذين قتلوا اولدهم سفها بغير علم وحرموا ما رزقهم الله افترا علي الله قد ضلوا وما كانوا مهتدين'),
(930, 6, 141, 'وَهُوَ الَّـذ۪ٓي اَنْشَاَ جَنَّاتٍ مَعْرُوشَاتٍ وَغَيْرَ مَعْرُوشَاتٍ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفاً اُكُلُهُ وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشَابِهاً وَغَيْرَ مُتَشَابِهٍۜ  كُلُوا مِنْ ثَمَرِه۪ٓ اِذَٓا اَثْمَرَ وَاٰتُوا حَقَّهُ يَوْمَ حَصَادِه۪ۘ وَلَا تُسْرِفُواۜ اِنَّهُ لَا يُحِبُّ الْمُسْرِف۪ينَۙ', 'Ve huvellezi enşee cennatin ma\'ruşatin ve gayre ma\'ruşatin ven nahle vez zer\'a muhtelifen ukuluhu vez zeytune ver rummane muteşabihen ve gayre muteşabih, kulu min semerihi iza esmere ve atu hakkahu yevme hasadihi ve la tusrifu, innehu la yuhibbul musrifin.', 'Asmalı ve asmasız bahçeleri,  çeşit çeşit hurmaları; zirai ürünleri,  birbirine benzeyen ve benzemeyen zeytin ve narları yetiştiren O\'dur. Her biri meyve verdiği zaman,  meyvesinden yiyin. Hasat zamanı da onun hakkını[1] verin. İsraf[2] etmeyin,  kuşkusuz O,  israf edenleri sevmez.', 'وهو الذي انشا جنت معروشت وغير معروشت والنخل والزرع مختلفا اكله والزيتون والرمان متشبها وغير متشبه كلوا من ثمره اذا اثمر واتوا حقه يوم حصاده ولا تسرفوا انه لا يحب المسرفين'),
(931, 6, 142, 'وَمِنَ الْاَنْعَامِ حَمُولَةً وَفَرْشاًۜ كُلُوا مِمَّا رَزَقَكُمُ اللّٰهُ وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِۜ اِنَّهُ لَكُمْ عَدُوٌّ مُب۪ينٌۙ', 'Ve minel en\'ami hamuleten ve ferşa, kulu mimma rezekakumullahu ve la tettebiu hutuvatiş şeytan,innehu lekum aduvvun mubin.', 'Ve hayvanlardan yük taşıyanlar ve serilecek olanlar/döşek yapılanlar var. Allah\'ın rızık olarak verdiklerinden yiyin. Şeytanın adımlarını izlemeyin. O sizin için apaçık bir düşmandır.', 'ومن الانعم حمولة وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوت الشيطن انه لكم عدو مبين'),
(932, 6, 143, 'ثَمَانِيَةَ اَزْوَاجٍۚ مِنَ الضَّأْنِ اثْنَيْنِ وَمِنَ الْمَعْزِ اثْنَيْنِۜ قُلْ آٰلذَّكَرَيْنِ حَرَّمَ اَمِ الْاُنْثَيَيْنِ اَمَّا اشْتَمَلَتْ عَلَيْهِ اَرْحَامُ الْاُنْثَيَيْنِۜ نَبِّؤُ۫ن۪ي بِعِلْمٍ اِنْ كُنْتُمْ صَادِق۪ينَۙ', 'Semaniyete ezvac, minad da\'nisneyni ve minel ma\'zisneyn, kul az zekereyni harreme emil unseyeyni emmeştemelet aleyhi erhamul unseyeyn, nebbiuni bi ilmin in kuntum sadıkin.', 'Sekiz çift; koyundan iki,  keçiden iki. De ki: \"İki erkeği mi,  yoksa iki dişiyi mi veya iki dişinin rahminde bulunanı mı haram etti? Eğer doğru söyleyenler iseniz bana bir bilgiye dayanarak haber verin.\"', 'ثمنية ازوج من الضان اثنين ومن المعز اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين نبوني بعلم ان كنتم صدقين'),
(933, 6, 144, 'وَمِنَ الْاِبِلِ اثْنَيْنِ وَمِنَ الْبَقَرِ اثْنَيْنِۜ قُلْ آٰلذَّكَرَيْنِ حَرَّمَ اَمِ الْاُنْثَيَيْنِ اَمَّا اشْتَمَلَتْ عَلَيْهِ اَرْحَامُ الْاُنْثَيَيْنِۜ اَمْ كُنْتُمْ شُهَدَٓاءَ اِذْ وَصّٰيكُمُ اللّٰهُ بِهٰذَاۚ فَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً لِيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ۟', 'Ve minel ibilisneyni ve minel bakarisneyn, kul az zekereyni harreme emil unseyeyni emmeştemelet aleyhi erhamul unseyeyn, em kuntum şuhedae iz vassakumullahu bi haza, fe men azlemu mimmeniftera alallahi keziben li yudillen nase bi gayri ilm, innallahe la yehdil kavmez zalimin.', 'Deveden iki,  sığırdan iki. De ki: \"İki erkeği mi,  yoksa iki dişiyi mi veya iki dişinin rahminde bulunanı mı haram etti? Yoksa Allah,  size bunları tavsiye ettiği zaman siz orada mıydınız? Bir bilgiye dayanmadan,  insanları saptırmak için Allah adına yalan uydurandan daha zalim kim olabilir? Allah,  zalim olan bir halkı doğru yola iletmez.\"', 'ومن الابل اثنين ومن البقر اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين ام كنتم شهدا اذ وصيكم الله بهذا فمن اظلم ممن افتري علي الله كذبا ليضل الناس بغير علم ان الله لا يهدي القوم الظلمين'),
(934, 6, 145, 'قُلْ لَٓا اَجِدُ ف۪ي مَٓا اُو۫حِيَ اِلَيَّ مُحَرَّماً عَلٰى طَاعِمٍ يَطْعَمُهُٓ اِلَّٓا اَنْ يَكُونَ مَيْتَةً اَوْ دَماً مَسْفُوحاً اَوْ لَحْمَ خِنْز۪يرٍ فَاِنَّهُ رِجْسٌ اَوْ فِسْقاً اُهِلَّ لِغَيْرِ اللّٰهِ بِه۪ۚ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَاِنَّ رَبَّكَ غَفُورٌ رَح۪يمٌ', 'Kul la ecidu fi ma uhiye ileyye muharremen ala taimin yat\'amuhu illa en yekune meyteten ev demen mesfuhan ev lahme hinzirin fe innehu ricsun ev fıskan uhille li gayrillahi bih, fe menidturra gayre bagın ve la adin fe inne rabbeke gafurun rahim.', 'De ki: \"Bana vahyolunanda; leş,  akıtılmış kan,  pis olan domuz eti veya bir sapkınlık olarak Allah\'tan başkası adına kesilmiş olanlar hariç,  yiyecek kimse için haram kılınmış bir şey bulamıyorum. Kim mecbur kalırsa haddi aşmadan,  zaruri ihtiyacı kadar bunlardan yiyebilir.\" Kuşkusuz Rabb\'in Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'قل لا اجد في ما اوحي الي محرما علي طاعم يطعمه الا ان يكون ميتة او دما مسفوحا او لحم خنزير فانه رجس او فسقا اهل لغير الله به فمن اضطر غير باغ ولا عاد فان ربك غفور رحيم'),
(935, 6, 146, 'وَعَلَى الَّذ۪ينَ هَادُوا حَرَّمْنَا كُلَّ ذ۪ي ظُفُرٍۚ وَمِنَ الْبَقَرِ وَالْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَٓا اِلَّا مَا حَمَلَتْ ظُهُورُهُمَٓا اَوِ الْحَوَايَٓا اَوْ مَا اخْتَلَطَ بِعَظْمٍۜ ذٰلِكَ جَزَيْنَاهُمْ بِبَغْيِهِمْۘ وَاِنَّا لَصَادِقُونَ', 'Ve alellezine hadu harremna kulle zi zufur, ve minel bakari vel ganemi harremna aleyhim şuhumehuma illa ma hamelet zuhuruhuma evil havaya ev mahteleta bi azm, zalike cezeynahum bi bagyihim ve inna le sadikun.', 'Yahudilere bütün tırnaklı[1] hayvanları haram ettik; onlara,  sığır ve koyunun iç yağlarını da haram ettik. Sırtlarında taşıdıkları,  bağırsaklarına ve kemiklerine karışan yağlar hariç. Bu,  azgınlıkları nedeniyle onlara verdiğimiz cezadır. Kuşkusuz Biz,  doğru olanlarız.', 'وعلي الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما الا ما حملت ظهورهما او الحوايا او ما اختلط بعظم ذلك جزينهم ببغيهم وانا لصدقون'),
(936, 6, 147, 'فَاِنْ كَذَّبُوكَ فَقُلْ رَبُّكُمْ ذُورَحْمَةٍ وَاسِعَةٍۚ وَلَا يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِم۪ينَ', 'Fe in kezzebuke fe kul rabbukum zu rahmetin vasi\'ah, ve la yureddu be\'suhu anil kavmil mucrimin.', 'Eğer seni yalanlarlarsa,  de ki: \"Rabb\'iniz geniş rahmet sahibidir,  ne var ki O\'nun azabı mücrim[1] halktan geri çevrilemez.\"', 'فان كذبوك فقل ربكم ذو رحمة واسعة ولا يرد باسه عن القوم المجرمين'),
(937, 6, 148, 'سَيَقُولُ الَّذ۪ينَ اَشْرَكُوا لَوْ شَٓاءَ اللّٰهُ مَٓا اَشْرَكْنَا وَلَٓا اٰبَٓاؤُ۬نَا وَلَا حَرَّمْنَا مِنْ شَيْءٍۜ كَذٰلِكَ كَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْ حَتّٰى ذَاقُوا بَأْسَنَاۜ قُلْ هَلْ عِنْدَكُمْ مِنْ عِلْمٍ فَتُخْرِجُوهُ لَنَاۜ اِنْ تَتَّبِعُونَ اِلَّا الظَّنَّ وَاِنْ اَنْتُمْ اِلَّا تَخْرُصُونَ', 'Seyekulullezine eşreku lev şaallahu ma eşrekna ve la abauna ve la harremna min şey\', kezalike kezzebellezine min kablihim hatta zaku be\'sena, kul hel indekum min ilmin fe tuhricuhu lena, in tettebiune illez zanne ve in entumilla tahrusun.', 'Müşrik olanlar diyecekler ki: \"Eğer Allah dileseydi biz de müşrik olmazdık,  babalarımız da. Ve hiçbir şeyi de haram kılmazdık.\" Onlardan öncekiler de aynı şekilde yalanladılar da sonunda azabımızı tattılar. De ki: \"Yanınızda bir bilgi varsa onu bize gösterin. Siz,  zandan başka bir şeye uymuyorsunuz ve ancak yalan yanlış atıp tutuyorsunuz.\"', 'سيقول الذين اشركوا لو شا الله ما اشركنا ولا اباونا ولا حرمنا من شي كذلك كذب الذين من قبلهم حتي ذاقوا باسنا قل هل عندكم من علم فتخرجوه لنا ان تتبعون الا الظن وان انتم الا تخرصون'),
(938, 6, 149, 'قُلْ فَلِلّٰهِ الْحُجَّةُ الْبَالِغَةُۚ فَلَوْ شَٓاءَ لَهَدٰيكُمْ اَجْمَع۪ينَ', 'Kul fe lillahil huccetul baligah, fe lev şae le hedakum ecmain.', 'De ki: \"Üstün hüccet[1] Allah\'ındır. Eğer Allah dileseydi[2] elbette hepinizi doğru yola iletirdi.\"', 'قل فلله الحجة البلغة فلو شا لهديكم اجمعين'),
(939, 6, 150, 'قُلْ هَلُمَّ شُهَدَٓاءَكُمُ الَّذ۪ينَ يَشْهَدُونَ اَنَّ اللّٰهَ حَرَّمَ هٰذَاۚ فَاِنْ شَهِدُوا فَلَا تَشْهَدْ مَعَهُمْۚ وَلَا تَتَّبِعْ اَهْوَٓاءَ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَالَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ وَهُمْ بِرَبِّهِمْ يَعْدِلُونَ۟', 'Kul helumme şuhedaekumullezine yeşhedune ennallahe harreme haza, fe in şehidu fe la teşhed meahum, ve la tettebi\' ehvaellezine kezzebu bi ayatina vellezine la yu\'minune bil ahireti ve hum bi rabbihim ya\'dilun.', 'De ki: \"Allah\'ın bunu haram ettiğine dair tanıklık edecek tanıklarınızı getirin.\" Eğer onlar tanıklık ederlerse sen onlarla beraber tanıklık etme. Âyetlerimizi yalanlayanların ve ahirete iman etmeyenlerin tutku ve kuruntularına uyma. Onlar,  Rabb\'lerine eş koşuyorlar.', 'قل هلم شهداكم الذين يشهدون ان الله حرم هذا فان شهدوا فلا تشهد معهم ولا تتبع اهوا الذين كذبوا بايتنا والذين لا يومنون بالاخرة وهم بربهم يعدلون'),
(940, 6, 151, 'قُلْ تَعَالَوْا اَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ اَلَّا تُشْرِكُوا بِه۪ شَيْـٔاًۜ وَبِالْوَالِدَيْنِ اِحْسَاناًۚ وَلَا تَقْتُلُٓوا اَوْلَادَكُمْ مِنْ اِمْلَاقٍۜ نَحْنُ نَرْزُقُكُمْ وَاِيَّاهُمْۚ وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَۚ وَلَا تَقْتُلُوا النَّفْسَ الَّت۪ي حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّۜ ذٰلِكُمْ وَصّٰيكُمْ بِه۪ لَعَلَّكُمْ تَعْقِلُونَ', 'Kul tealev etlu ma harreme rabbukum aleykum ella tuşriku bihi şey\'a, ve bil valideyni ihsana, ve la taktulu evladekum min imlak, nahnu nerzukukum ve iyyahum, ve la takrebul fevahışe ma zahere minha ve ma batan, ve la taktulun nefselleti harremallahu illa bil hakk, zalikum vassakum bihi leallekum ta\'kılun.', 'De ki: \"Gelin,  Rabb\'inizin size haram kıldığı şeyleri bildireyim: O\'na şirk koşmayın. Anaya babaya iyilik edin. Yoksulluk endişesi ile çocuklarınızı öldürmeyin.\" Ssizin de onların da rızıklarını veren Allah\'tır. \"Fuhşiyatın[1] açığına da gizlisine de yaklaşmayın. Haklı bir gerekçe olmadıkça Allah\'ın dokunulmaz kıldığı cana kıymayın. İşte O,  size bunları öğütledi,  umulur ki aklınızı kullanırsınız.\"', 'قل تعالوا اتل ما حرم ربكم عليكم الا تشركوا به شيا وبالولدين احسنا ولا تقتلوا اولدكم من املق نحن نرزقكم واياهم ولا تقربوا الفوحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله الا بالحق ذلكم وصيكم به لعلكم تعقلون'),
(941, 6, 152, 'وَلَا تَقْرَبُوا مَالَ الْيَت۪يمِ اِلَّا بِالَّت۪ي هِيَ اَحْسَنُ حَتّٰى يَبْلُغَ اَشُدَّهُۚ وَاَوْفُوا الْكَيْلَ وَالْم۪يزَانَ بِالْقِسْطِۚ لَا نُكَلِّفُ نَفْساً اِلَّا وُسْعَهَا وَاِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبٰىۚ وَبِعَهْدِ اللّٰهِ اَوْفُواۜ ذٰلِكُمْ وَصّٰيكُمْ بِه۪ لَعَلَّكُمْ تَذَكَّرُونَۙ', 'Ve la takrebu malel yetimi illa billeti hiye ahsenu hatta yebluga eşuddeh, ve evful keyle vel mizane bil kıst, la nukellifu nefsen illa vus\'aha ve iza kultum fa\'dilu ve lev kane za kurba, ve bi ahdillahi evfu, zalikum vassakum bihi leallekum tezekkerun.', 'Olgunluk çağına erişinceye kadar,  iyiliği için olmadıkça yetimin malına dokunmayın. Ölçü ve tartıyı hakkaniyetle yapın. Biz,  gücünün yettiğinden fazlasını kişiye teklif etmeyiz. Yakın akrabanız da olsa konuştuğunuz zaman adaleti gözetin. Allah\'a verdiğiniz sözü tutun. O,  size bunları böylece öğütte bulundu,  umulur ki öğüt alırsınız.', 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا الكيل والميزان بالقسط لا نكلف نفسا الا وسعها واذا قلتم فاعدلوا ولو كان ذا قربي وبعهد الله اوفوا ذلكم وصيكم به لعلكم تذكرون'),
(942, 6, 153, 'وَاَنَّ هٰذَا صِرَاط۪ي مُسْتَق۪يماً فَاتَّبِعُوهُۚ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَب۪يلِه۪ۜ ذٰلِكُمْ وَصّٰيكُمْ بِه۪ لَعَلَّكُمْ تَتَّقُونَ', 'Ve enne haza sırati mustekimen fettebiuh, ve la tettebius subule fe teferreka bikum an sebilih, zalikum vassakum bihi leallekum tettekun.', 'Gerçekten bu,  Ben\'im dosdoğru yolumdur. Ona uyun. Başka yollara uymayın. Zira o yollar sizi,  O\'nun yolundan uzaklaştırır. O,  size bunları öğütledi,  umulur ki takvalı[1] olursunuz.', 'وان هذا صرطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصيكم به لعلكم تتقون'),
(943, 6, 154, 'ثُمَّ اٰتَيْنَا مُوسَى الْكِتَابَ تَمَاماً عَلَى الَّـذ۪ٓي اَحْسَنَ وَتَفْص۪يلاً لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً لَعَلَّهُمْ بِلِقَٓاءِ رَبِّهِمْ يُؤْمِنُونَ۟', 'Summe ateyna musel kitabe tamamen alellezi ahsene ve tafsilen li kulli şey\'in ve huden ve rahmeten leallehum bi likai rabbihim yu\'minun.', 'Sonra Musa\'ya,  iyi olanlara tamamlayıcı olarak her şeyi açıklayan,  rahmet olan ve doğru yolu gösteren Kitap\'ı verdik. Umulur ki Rabb\'lerine kavuşacaklarına inanırlar.', 'ثم اتينا موسي الكتب تماما علي الذي احسن وتفصيلا لكل شي وهدي ورحمة لعلهم بلقا ربهم يومنون'),
(944, 6, 155, 'وَهٰذَا كِتَابٌ اَنْزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَۙ', 'Ve haza kitabun enzelnahu mubarekun fettebiuhu vetteku leallekum turhamun.', 'İşte bu,  indirdiğimiz kutsal bir Kitap\'tır. Ona uyun. Takvalı olun. Umulur ki bağışlanırsınız.', 'وهذا كتب انزلنه مبارك فاتبعوه واتقوا لعلكم ترحمون'),
(945, 6, 156, 'اَنْ تَقُولُٓوا اِنَّـمَٓا اُنْزِلَ الْكِتَابُ عَلٰى طَٓائِفَتَيْنِ مِنْ قَبْلِنَاۖ وَاِنْ كُنَّا عَنْ دِرَاسَتِهِمْ لَغَافِل۪ينَۙ', 'En tekulu innema unzilel kitabu ala taifeteyni min kablina ve in kunna an dirasetihim le gafilin.', '\"Kitap,  bizden önce yalnızca iki topluluğa[1] indirildi,  biz onların edindikleri bilgiden habersizdik.\" dememeniz için;', 'ان تقولوا انما انزل الكتب علي طايفتين من قبلنا وان كنا عن دراستهم لغفلين'),
(946, 6, 157, 'اَوْ تَقُولُوا لَوْ اَنَّٓا اُنْزِلَ عَلَيْنَا الْكِتَابُ لَكُنَّٓا اَهْدٰى مِنْهُمْۚ فَقَدْ جَٓاءَكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ وَهُدًى وَرَحْمَةٌۚ فَمَنْ اَظْلَمُ مِمَّنْ كَذَّبَ بِاٰيَاتِ اللّٰهِ وَصَدَفَ عَنْهَاۜ سَنَجْزِي الَّذ۪ينَ يَصْدِفُونَ عَنْ اٰيَاتِنَا سُٓوءَ الْعَذَابِ بِمَا كَانُوا يَصْدِفُونَ', 'Ev tekulu lev enna unzile aleynel kitabu le kunna ehda minhum, fe kad caekum beyyinetun min rabbikum ve huden ve rahmeh, fe men azlemu mimmen kezzebe bi ayatillahi ve sadefe anha, se neczillezine yasdifune an ayatina suel azabi bima kanu yasdifun.', 'Veya \"Eğer bize kitap indirilseydi,  biz onlardan daha iyi doğru yolda olurduk.\" dememeniz için,  Rabb\'inizden size apaçık bir beyyinat[1],  bir hidayet ve bir rahmet geldi. Allah\'ın ayetlerini yalanlayıp,  ondan yüz çevirenden daha zalim kim olabilir? Âyetlerimizden yüz çevirenleri,  yüz çevirmelerinden dolayı azabın en kötüsü ile cezalandıracağız.', 'او تقولوا لو انا انزل علينا الكتب لكنا اهدي منهم فقد جاكم بينة من ربكم وهدي ورحمة فمن اظلم ممن كذب بايت الله وصدف عنها سنجزي الذين يصدفون عن ايتنا سو العذاب بما كانوا يصدفون'),
(947, 6, 158, 'هَلْ يَنْظُرُونَ اِلَّٓا اَنْ تَأْتِيَهُمُ الْمَلٰٓئِكَةُ اَوْ يَأْتِيَ رَبُّكَ اَوْ يَأْتِيَ بَعْضُ اٰيَاتِ رَبِّكَۜ يَوْمَ يَأْت۪ي بَعْضُ اٰيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْساً ا۪يمَانُهَا لَمْ تَكُنْ اٰمَنَتْ مِنْ قَبْلُ اَوْ كَسَبَتْ ف۪ٓي ا۪يمَانِهَا خَيْراًۜ قُلِ انْتَظِرُٓوا اِنَّا مُنْتَظِرُونَ', 'Hel yanzurune illa en te\'tiyehumul melaiketu ev ye\'tiye rabbuke ev ye\'tiye ba\'du ayati rabbik, yevme ye\'ti ba\'du ayati rabbike la yenfeu nefsen imanuha lem tekun amenet min kablu ev kesebet fi imaniha hayra, kul intezıru inna muntezırun.', 'Onlar,  kendilerine; meleklerin gelmesini,  Rabb\'inin gelmesini veya Rabb\'inin bazı ayetlerinin[1] gelmesini mi bekliyorlar? Rabb\'inin ayetlerinden biri geldiği gün,  daha önce iman etmemiş veya imanında bir hayır kazanmamış[2] kimseye,  imanı fayda sağlamaz. De ki: \"Bekleyin,  kuşkusuz biz de beklemekteyiz.\"', 'هل ينظرون الا ان تاتيهم المليكة او ياتي ربك او ياتي بعض ايت ربك يوم ياتي بعض ايت ربك لا ينفع نفسا ايمنها لم تكن امنت من قبل او كسبت في ايمنها خيرا قل انتظروا انا منتظرون'),
(948, 6, 159, 'اِنَّ الَّذ۪ينَ فَرَّقُوا د۪ينَهُمْ وَكَانُوا شِيَعاً لَسْتَ مِنْهُمْ ف۪ي شَيْءٍۜ اِنَّـمَٓا اَمْرُهُمْ اِلَى اللّٰهِ ثُمَّ يُنَبِّئُهُمْ بِمَا كَانُوا يَفْعَلُونَ', 'İnnellezine ferreku dinehum ve kanu şiyean leste minhum fi şey\', innema emruhum ilallahi summe yunebbiuhum bima kanu yef\'alun.', 'Dinlerini parça parça edip,  grup grup olanlar var ya,  senin onlarla hiçbir ilişkin yoktur. Onların işi ancak Allah\'a kalmıştır. Sonra O,  onlara yaptıklarını bildirecektir.', 'ان الذين فرقوا دينهم وكانوا شيعا لست منهم في شي انما امرهم الي الله ثم ينبيهم بما كانوا يفعلون'),
(949, 6, 160, 'مَنْ جَٓاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ اَمْثَالِهَاۚ وَمَنْ جَٓاءَ بِالسَّيِّئَةِ فَلَا يُجْزٰٓى اِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', 'Men cae bil haseneti fe lehu aşru emsaliha, ve men cae bis seyyieti fe la yucza illa misleha ve hum la yuzlemun.', 'Kim bir iyilik ile gelirse ona on katı vardır,  kim bir kötülük ile gelirse kötülüğü oranında karşılık bulur. Onların hiçbirine haksızlık yapılmaz.', 'من جا بالحسنة فله عشر امثالها ومن جا بالسيية فلا يجزي الا مثلها وهم لا يظلمون'),
(950, 6, 161, 'قُلْ اِنَّن۪ي هَدٰين۪ي رَبّ۪ٓي اِلٰى صِرَاطٍ مُسْتَق۪يمٍۚ د۪يناً قِيَماً مِلَّةَ اِبْرٰه۪يمَ حَن۪يفاًۚ وَمَا كَانَ مِنَ الْمُشْرِك۪ينَ', 'Kul inneni hedani rabbi ila sıratın mustekim dinen kıyamen millete ibrahime hanifa, ve ma kane minel muşrikin.', 'De ki: \"Rabb\'im,  beni dosdoğru bir yola iletti: Dimdik ayakta duran bir dine,  Hanif[1] olan İbrahim\'in inanç sistemine. O müşriklerden değildi.\"', 'قل انني هديني ربي الي صرط مستقيم دينا قيما ملة ابرهيم حنيفا وما كان من المشركين'),
(951, 6, 162, 'قُلْ اِنَّ صَلَات۪ي وَنُسُك۪ي وَمَحْيَايَ وَمَمَات۪ي لِلّٰهِ رَبِّ الْعَالَم۪ينَۙ', 'Kul inne salati ve nusuki ve mahyaye ve memati lillahi rabbil alemin.', 'De ki: \"Benim salatım[1],  nusukum[2],  hayatım ve ölümüm alemlerin Rabb\'i olan Allah içindir.\"', 'قل ان صلاتي ونسكي ومحياي ومماتي لله رب العلمين'),
(952, 6, 163, 'لَا شَر۪يكَ لَهُۚ وَبِذٰلِكَ اُمِرْتُ وَاَنَا۬ اَوَّلُ الْمُسْلِم۪ينَ', 'La şerike leh, ve bi zalike umirtu ve ene evvelul muslimin.', '\"O\'nun hiçbir ortağı yoktur. Bana böyle buyruldu. Ben teslim olanların öncüsüyüm.\"', 'لا شريك له وبذلك امرت وانا اول المسلمين'),
(953, 6, 164, 'قُلْ اَغَيْرَ اللّٰهِ اَبْغ۪ي رَباًّ وَهُوَ رَبُّ كُلِّ شَيْءٍۜ وَلَا تَكْسِبُ كُلُّ نَفْسٍ اِلَّا عَلَيْهَاۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ اُخْرٰىۚ ثُمَّ اِلٰى رَبِّكُمْ مَرْجِعُكُمْ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ ف۪يهِ تَخْتَلِفُونَ', 'Kul e gayrallahi ebgi rabben ve huve rabbu kulli şey\', ve la teksibu kullu nefsin illa aleyh, ve la teziru vaziretun vizre uhra, summe ila rabbikum merciukum fe yunebbiukum bima kuntum fihi tahtelifun.', 'De ki: \"Allah,  her şeyin Rabb\'iyken,  ben O\'ndan başka bir Rabb mı arayayım?\" Herkesin kazandığı yalnız kendisine aittir. Hiç kimse bir başkasının yükünü yüklenmez. Sonunda dönüşünüz Rabb\'inizedir. O,  size ayrılığa düştüğünüz şeyleri haber verecektir.', 'قل اغير الله ابغي ربا وهو رب كل شي ولا تكسب كل نفس الا عليها ولا تزر وازرة وزر اخري ثم الي ربكم مرجعكم فينبيكم بما كنتم فيه تختلفون'),
(954, 6, 165, 'وَهُوَ الَّذ۪ي جَعَلَكُمْ خَلَٓائِفَ الْاَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ لِيَبْلُوَكُمْ ف۪ي مَٓا اٰتٰيكُمْۜ اِنَّ رَبَّكَ سَر۪يعُ الْعِقَابِۘ وَاِنَّهُ لَغَفُورٌ رَح۪يمٌ', 'Ve huvellezi cealekum halaifelardı ve refea ba\'dakum fevka ba\'dın derecatin li yebluvekum fi ma atakum, inne rabbeke seriul ikabi ve innehu le gafurun rahim.', 'Sizi,  yeryüzünün halifeleri yapan,  size verdiği şeylerle denemek için bazınızı bazınıza derecelerle üstün kılan,  O\'dur. Kuşkusuz Rabb\'in,  cezası pek çabuk olandır. Ve gerçekten O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'وهو الذي جعلكم خليف الارض ورفع بعضكم فوق بعض درجت ليبلوكم في ما اتيكم ان ربك سريع العقاب وانه لغفور رحيم'),
(955, 7, 1, 'الٓمٓصٓۜ', 'Elif, lam, mim, sad', 'Elif,  Lam,  Mim,  Sad.', 'المص'),
(956, 7, 2, 'كِتَابٌ اُنْزِلَ اِلَيْكَ فَلَا يَكُنْ ف۪ي صَدْرِكَ حَرَجٌ مِنْهُ لِتُنْذِرَ بِه۪ وَذِكْرٰى لِلْمُؤْمِن۪ينَ', 'Kitabun unzile ileyke fe la yekun fi sadrike haracun minhu litunzire bihi ve zikra lil mu\'minin.', 'Bu,  sana indirilen bir Kitap\'tır. Onunla uyarıda bulunman ve mü\'minlere öğüt vermen konusunda göğsünde bir sıkıntı olmasın.', 'كتب انزل اليك فلا يكن في صدرك حرج منه لتنذر به وذكري للمومنين'),
(957, 7, 3, 'اِتَّبِعُوا مَٓا اُنْزِلَ اِلَيْكُمْ مِنْ رَبِّكُمْ وَلَا تَتَّبِعُوا مِنْ دُونِه۪ٓ اَوْلِيَٓاءَۜ  قَل۪يلاً مَا تَذَكَّرُونَ', 'Ittebiu ma unzile ileykum min rabbikum ve la tettebiu min dunihi evliya, kalilen ma tezekkerun.', 'Rabb\'inizden size indirilene uyun. O\'nun yanı sıra başka velilere[1] uymayın. Ne kadar az öğüt tutuyorsunuz!', 'اتبعوا ما انزل اليكم من ربكم ولا تتبعوا من دونه اوليا قليلا ما تذكرون'),
(958, 7, 4, 'وَكَمْ مِنْ قَرْيَةٍ اَهْلَكْنَاهَا فَجَٓاءَهَا بَأْسُنَا بَيَاتاً اَوْ هُمْ قَٓائِلُونَ', 'Ve kem min karyetin ehleknaha fe caeha be\'suna beyaten ev hum kailun.', 'Biz,  nice kentleri yok ettik. Gece uyurlarken veya gündüz uykusundayken[1] onlara azabımız gelip çattı.', 'وكم من قرية اهلكنها فجاها باسنا بيتا او هم قايلون'),
(959, 7, 5, 'فَمَا كَانَ دَعْوٰيهُمْ اِذْ جَٓاءَهُمْ بَأْسُنَٓا اِلَّٓا اَنْ قَالُٓوا اِنَّا كُنَّا ظَالِم۪ينَ', 'Fe ma kane da\'vahum iz caehum be\'suna illa en kalu inna kunna zalimin.', 'Azabımız onlara geldiğinde tek feryatları,  \"Biz gerçekten zalimlermişiz.\" demelerinden başka bir şey olmadı.', 'فما كان دعويهم اذ جاهم باسنا الا ان قالوا انا كنا ظلمين'),
(960, 7, 6, 'فَلَنَسْـَٔلَنَّ الَّذ۪ينَ اُرْسِلَ اِلَيْهِمْ وَلَنَسْـَٔلَنَّ الْمُرْسَل۪ينَۙ', 'Fe le nes\'elennellezine ursile ileyhim ve le nes\'elennel murselin.', 'Kendilerine elçi gönderilenlere de gönderilen elçilere de mutlaka soracağız.', 'فلنسلن الذين ارسل اليهم ولنسلن المرسلين'),
(961, 7, 7, 'فَلَنَقُصَّنَّ عَلَيْهِمْ بِعِلْمٍ وَمَا كُنَّا غَٓائِب۪ينَ', 'Fe le nekussanne aleyhim bi ilmin ve ma kunna gaibin.', 'Kesin bir bilgi ile onlara yaptıklarını anlatacağız. Zira Biz yaptıkları hiçbir şeyden habersiz değiliz.', 'فلنقصن عليهم بعلم وما كنا غايبين'),
(962, 7, 8, 'وَالْوَزْنُ يَوْمَئِذٍۨ الْحَقُّۚ فَمَنْ ثَقُلَتْ مَوَاز۪ينُهُ فَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Vel veznu yevme izinil hakk, fe men sekulet mevazinuhu fe ulaike humul muflihun.', 'İzin Günü[1] tartı tam doğrudur. Kimin tartısı ağır gelirse,  işte onlar kurtuluşa erenlerdir.', 'والوزن يوميذ الحق فمن ثقلت موزينه فاوليك هم المفلحون'),
(963, 7, 9, 'وَمَنْ خَفَّتْ مَوَاز۪ينُهُ فَاُو۬لٰٓئِكَ الَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ بِمَا كَانُوا بِاٰيَاتِنَا يَظْلِمُونَ', 'Ve men haffet mevazinuhu fe ulaikellezine hasiru enfusehum bima kanu biayatina yazlimun.', 'Kimin de tartısı hafif gelirse,  işte onlar,  ayetlerimize haksızlık etmelerinden[1] dolayı kendilerine yazık edenlerdir.[2]', 'ومن خفت موزينه فاوليك الذين خسروا انفسهم بما كانوا بايتنا يظلمون'),
(964, 7, 10, 'وَلَقَدْ مَكَّنَّاكُمْ فِي الْاَرْضِ وَجَعَلْنَا لَكُمْ ف۪يهَا مَعَايِشَۜ قَل۪يلاً مَا تَشْكُرُونَ۟', 'Ve lekad mekkennakum fil ardı ve cealna lekum fiha maayiş\', kalilen ma teşkurun.', 'Doğrusu Biz,  sizi yeryüzüne yerleştirdik ve orada size geçimlik verdik. Ne kadar da az şükrediyorsunuz.', 'ولقد مكنكم في الارض وجعلنا لكم فيها معيش قليلا ما تشكرون'),
(965, 7, 11, 'وَلَقَدْ خَلَقْنَاكُمْ ثُمَّ صَوَّرْنَاكُمْ ثُمَّ قُلْنَا لِلْمَلٰٓئِكَةِ اسْجُدُوا لِاٰدَمَۗ فَسَجَدُٓوا اِلَّٓا اِبْل۪يسَۜ لَمْ يَكُنْ مِنَ السَّاجِد۪ينَ', 'Ve lekad halaknakum summe savvernakum summe kulna lil melaiketiscudu li ademe fe secedu illa iblis, lem yekun mines sacidin.', 'Ant olsun ki sizi Biz yarattık. Sonra size şekil verdik. Sonra meleklere,  \"Âdem\'e secde[1] edin.\" dedik. İblis hariç hepsi secde ettiler. O,  secde edenlerden olmadı.', 'ولقد خلقنكم ثم صورنكم ثم قلنا للمليكة اسجدوا لادم فسجدوا الا ابليس لم يكن من السجدين'),
(966, 7, 12, 'قَالَ مَا مَنَعَكَ اَلَّا تَسْجُدَ اِذْ اَمَرْتُكَۜ قَالَ اَنَا۬ خَيْرٌ مِنْهُۚ خَلَقْتَن۪ي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ ط۪ينٍ', 'Kale ma meneake ella tescude iz emertuk, kale ene hayrun minh, halakteni min narin ve halaktehu min tin.', '\"Sana buyurduğum halde,  seni secde etmekten alıkoyan nedir?\" dedi. \"Ben ondan hayırlıyım,  beni ateşten onu çamurdan yarattın.\" dedi.', 'قال ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين'),
(967, 7, 13, 'قَالَ فَاهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ اَنْ تَتَكَبَّرَ ف۪يهَا فَاخْرُجْ اِنَّكَ مِنَ الصَّاغِر۪ينَ', 'Kale fehbit minha fe ma yekunu leke en tetekebbere fiha fahruc inneke mines sagirin.', '\"Hemen oradan in; orada büyüklük taslamak haddin değil. Hemen oradan çık. Sen aşağılanmışlardansın!\" dedi.', 'قال فاهبط منها فما يكون لك ان تتكبر فيها فاخرج انك من الصغرين'),
(968, 7, 14, 'قَالَ اَنْظِرْن۪ٓي اِلٰى يَوْمِ يُبْعَثُونَ', 'Kale enzırni ila yevmi yub\'asun.', '\"Tekrar diriltilecekleri güne kadar beni gözle[1]\" dedi.', 'قال انظرني الي يوم يبعثون'),
(969, 7, 15, 'قَالَ اِنَّكَ مِنَ الْمُنْظَر۪ينَ', 'Kale inneke minel munzarin.', '\"Sen gözlenenlerdensin.\"[1] dedi.', 'قال انك من المنظرين'),
(970, 7, 16, 'قَالَ فَبِمَٓا اَغْوَيْتَن۪ي لَاَقْعُدَنَّ لَهُمْ صِرَاطَكَ الْمُسْتَق۪يمَۙ', 'Kale fe bima agveyteni le ak\'udenne lehum sıratekel mustekim.', '\"Azdırmandan dolayı,  onlar için[1] senin dosdoğru yolunun üzerine oturacağım.\" dedi.', 'قال فبما اغويتني لاقعدن لهم صرطك المستقيم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(971, 7, 17, 'ثُمَّ لَاٰتِيَنَّهُمْ مِنْ بَيْنِ اَيْد۪يهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ اَيْمَانِهِمْ وَعَنْ شَمَٓائِلِهِمْۜ وَلَا تَجِدُ اَكْثَرَهُمْ شَاكِر۪ينَ', 'Summe le atiyennehum min beyni eydihim ve min halfihim ve an eymanihim ve an şemailihim, ve la tecidu ekserehum şakirin.', '\"Sonra,  ant olsun ki onlara önlerinden,  arkalarından,  sağlarından ve sollarından sokulacağım ve Sen onların çoğunu şükrediciler olarak bulamayacaksın.\"', 'ثم لاتينهم من بين ايديهم ومن خلفهم وعن ايمنهم وعن شمايلهم ولا تجد اكثرهم شكرين'),
(972, 7, 18, 'قَالَ اخْرُجْ مِنْهَا مَذْؤُ۫ماً مَدْحُوراًۜ لَمَنْ تَبِعَكَ مِنْهُمْ لَاَمْلَـَٔنَّ جَهَنَّمَ مِنْكُمْ اَجْمَع۪ينَ', 'Kalehruc minha mez\'umen medhura, le men tebiake minhum leemleenne cehenneme minkum ecmain.', '\"Kovulmuş ve kınanmış olarak oradan çık. Onlardan kim sana uyarsa,  Cehennem\'i onlarla dolduracağım.\" dedi.', 'قال اخرج منها مذوما مدحورا لمن تبعك منهم لاملان جهنم منكم اجمعين'),
(973, 7, 19, 'وَيَٓا اٰدَمُ اسْكُنْ اَنْتَ وَزَوْجُكَ الْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هٰذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِم۪ينَ', 'Ve ya ademuskun ente ve zevcukel cennete fe kula min haysu şi\'tuma ve la takreba hazihiş şecerete fe tekuna minez zalimin.', 'Ey Âdem! \"Sen ve eşin cennete yerleşin,  dilediğiniz yerden yiyin,  fakat şu ağaca[1] yaklaşmayın. Yoksa zalimlerden olursunuz.\"', 'ويادم اسكن انت وزوجك الجنة فكلا من حيث شيتما ولا تقربا هذه الشجرة فتكونا من الظلمين'),
(974, 7, 20, 'فَوَسْوَسَ لَهُمَا الشَّيْطَانُ لِيُبْدِيَ لَهُمَا مَا وُ۫رِيَ عَنْهُمَا مِنْ سَوْاٰتِهِمَا وَقَالَ مَا نَهٰيكُمَا رَبُّكُمَا عَنْ هٰذِهِ الشَّجَرَةِ اِلَّٓا اَنْ تَكُونَا مَلَكَيْنِ اَوْ تَكُونَا مِنَ الْخَالِد۪ينَ', 'Fe vesvese lehumuş şeytanu li yubdiye lehuma ma vuriye anhuma min sev\'atihima ve kale ma nehakuma rabbukuma an hazihiş şecereti illa en tekuna melekeyni ev tekuna minel halidin.', 'Derken şeytan,  kötülüklerini[1] kendilerine göstermek için onlara fısıldadı. Rabb\'iniz size bu ağacı melek/melik olmayasınız veya ölümsüz olmayasınız diye yasakladı.\" dedi.', 'فوسوس لهما الشيطن ليبدي لهما ما وري عنهما من سوتهما وقال ما نهيكما ربكما عن هذه الشجرة الا ان تكونا ملكين او تكونا من الخلدين'),
(975, 7, 21, 'وَقَاسَمَـهُمَٓا اِنّ۪ي لَكُمَا لَمِنَ النَّاصِح۪ينَۙ', 'Ve kasemehuma inni lekuma le minen nasıhin.', 'Ve ikisine: \"Ben gerçekten ikinizin de iyiliğini istemekteyim.\" diye yemin etti.', 'وقاسمهما اني لكما لمن النصحين'),
(976, 7, 22, 'فَدَلّٰيهُمَا بِغُرُورٍۚ فَلَمَّا ذَاقَا الشَّجَرَةَ بَدَتْ لَهُمَا سَوْاٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِنْ وَرَقِ الْجَنَّةِۜ وَنَادٰيهُمَا رَبُّهُمَٓا اَلَمْ اَنْهَكُمَا عَنْ تِلْكُمَا الشَّجَرَةِ وَاَقُلْ لَكُمَٓا اِنَّ الشَّيْطَانَ لَكُمَا عَدُوٌّ مُب۪ينٌ', 'Fedellahuma bi gurur, fe lemma zakaş şecerete bedet lehuma sev\'atuhuma ve tafika yahsıfani aleyhima min varakıl cenneh, ve nadahuma rabbuhuma e lem enhekuma an tilkumeş şecereti ve ekul lekuma inneş şeytane lekuma aduvvun mubin.', 'Böylece ikisini aldatıp baştan çıkardı. O ağaçtan tadınca[1],  çirkinlikleri açığa çıktı.[2] Cennet yapraklarını[3] üst üste koyup örtünmeye başladılar.[4] Rabb\'leri onlara: \"Ben sizi o ağaçtan men etmedim mi? Bu şeytan size apaçık bir düşmandır demedim mi?\" diye seslendi.', 'فدليهما بغرور فلما ذاقا الشجرة بدت لهما سوتهما وطفقا يخصفان عليهما من ورق الجنة وناديهما ربهما الم انهكما عن تلكما الشجرة واقل لكما ان الشيطن لكما عدو مبين'),
(977, 7, 23, 'قَالَا رَبَّـنَا ظَلَمْنَٓا اَنْفُسَنَا وَاِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِر۪ينَ', 'Kala rabbena zalemna enfusena ve in lem tagfirlena ve terhamna le nekunenne minel hasirin.', '\"Ey Rabb\'imiz! Biz,  kendimize zulmettik. Eğer bizi bağışlamaz ve merhamet etmezsen hüsrana uğrayanlardan oluruz.\" dediler.', 'قالا ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخسرين'),
(978, 7, 24, 'قَالَ اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۚ وَلَكُمْ فِي الْاَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ اِلٰى ح۪ينٍ', 'Kalehbitu ba\'dukum li ba\'dın aduvv, ve lekum fil\'ardı mustekarrun ve metaun ila hin.', '\"Bir kısmınız bir kısmınıza düşman olarak inin.\" dedi. Yeryüzünde,  size belli bir süreye kadar yerleşme ve yararlanma imkanı vardır.\" dedi.', 'قال اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتع الي حين'),
(979, 7, 25, 'قَالَ ف۪يهَا تَحْيَوْنَ وَف۪يهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ۟', 'Kale fiha tahyevne ve fiha temutune ve minha tuhrecun.', 'De ki: \"Orada yaşayacaksınız,  orada öleceksiniz ve oradan çıkarılacaksınız.\"', 'قال فيها تحيون وفيها تموتون ومنها تخرجون'),
(980, 7, 26, 'يَا بَن۪ٓي اٰدَمَ قَدْ اَنْزَلْنَا عَلَيْكُمْ لِبَاساً يُوَار۪ي سَوْاٰتِكُمْ وَر۪يشاً۠ وَلِبَاسُ التَّقْوٰى ذٰلِكَ خَيْرٌۜ ذٰلِكَ مِنْ اٰيَاتِ اللّٰهِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'Ya beni ademe kad enzelna aleykum libasen yuvari sev\'atikum ve rişa ve libasut takva zalike hayr, zalike min ayatillahi leallehum yezzekkerun.', 'Ey ademoğulları! Cesetlerinizi[1] örtecek ve sizi süsleyecek libas[2] indirdik.[3] Takva libası[4] ise daha hayırlıdır. İşte bu Allah\'ın ayetlerindendir. Umulur ki düşünüp öğüt alırlar.', 'يبني ادم قد انزلنا عليكم لباسا يوري سوتكم وريشا ولباس التقوي ذلك خير ذلك من ايت الله لعلهم يذكرون'),
(981, 7, 27, 'يَا بَن۪ٓي اٰدَمَ لَا يَفْتِنَنَّكُمُ الشَّيْطَانُ كَمَٓا اَخْرَجَ اَبَوَيْكُمْ مِنَ الْجَنَّةِ يَنْزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْاٰتِهِمَاۜ اِنَّهُ يَرٰيكُمْ هُوَ وَقَب۪يلُهُ مِنْ حَيْثُ لَا تَرَوْنَهُمْۜ اِنَّا جَعَلْنَا الشَّيَاط۪ينَ اَوْلِيَٓاءَ لِلَّذ۪ينَ لَا يُؤْمِنُونَ', 'Ya beni ademe la yeftinennekumuş şeytanu kema ahrece ebeveykum minel cenneti yenziu anhuma libasehuma li yuriyehuma sev\'atihima innehu yerakum huve ve kabiluhu min haysu la terevnehum inna cealneş şeyatine evliyae lillezine la yu\'minun.', 'Ey ademoğulları![1] Şeytan kötülüklerini onlara göstermek için,  elbilselerini[2] soyarak[2],  ana babanızı cennetten[3] çıkardığı gibi sizi de bir fitneye düşürmesin. O ve taraftarları,  sizin onları göremeyeceğiniz yerden sizi görürler. Biz,  şeytanları iman etmeyenlere evliya[4] kıldık.', 'يبني ادم لا يفتننكم الشيطن كما اخرج ابويكم من الجنة ينزع عنهما لباسهما ليريهما سوتهما انه يريكم هو وقبيله من حيث لا ترونهم انا جعلنا الشيطين اوليا للذين لا يومنون'),
(982, 7, 28, 'وَاِذَا فَعَلُوا فَاحِشَةً قَالُوا وَجَدْنَا عَلَيْهَٓا اٰبَٓاءَنَا وَاللّٰهُ اَمَرَنَا بِهَاۜ قُلْ اِنَّ اللّٰهَ لَا يَأْمُرُ بِالْفَحْشَٓاءِۜ اَتَقُولُونَ عَلَى اللّٰهِ مَا لَا تَعْلَمُونَ', 'Ve iza faalu fahişeten kalu vecedna aleyha abaena vallahu emerena biha kul innallahe la ye\'muru bil fahşa, e tekulune alallahi ma la ta\'lemun.', 'Onlar bir fuhuş[1] yaptıkları zaman,  \"Atalarımızdan böyle gördük ve Allah bize böyle emretti.\" derler. De ki: \"Allah fuhşu emretmez. Hakkında bilginiz olmayan şeyleri mi Allah\'a yakıştırıyorsunuz?\"', 'واذا فعلوا فحشة قالوا وجدنا عليها ابانا والله امرنا بها قل ان الله لا يامر بالفحشا اتقولون علي الله ما لا تعلمون'),
(983, 7, 29, 'قُلْ اَمَرَ رَبّ۪ي بِالْقِسْطِ۠ وَاَق۪يمُوا وُجُوهَكُمْ عِنْدَ كُلِّ مَسْجِدٍ وَادْعُوهُ مُخْلِص۪ينَ لَهُ الدّ۪ينَۜ   كَمَا بَدَاَكُمْ تَعُودُونَۜ', 'Kul emere rabbi bil kıst ve ekimu vucuhekum inde kulli mescidin ved\'uhu muhlisine lehud din, kema bedeekum teudun.', 'De ki: \"Rabb\'im bana haktan yana olmayı emretti.\" Her mescitte yüzlerinizi[1] O\'na doğrultun ve dini yalnızca O\'na has kılarak[2] dua edin. Sizi ilk yarattığı gibi yine O\'na döneceksiniz.', 'قل امر ربي بالقسط واقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين كما بداكم تعودون'),
(984, 7, 30, 'فَر۪يقاً هَدٰى وَفَر۪يقاً حَقَّ عَلَيْهِمُ الضَّلَالَةُۜ اِنَّهُمُ اتَّخَذُوا الشَّيَاط۪ينَ اَوْلِيَٓاءَ مِنْ دُونِ اللّٰهِ وَيَحْسَبُونَ اَنَّهُمْ مُهْتَدُونَ', 'Ferikan hada ve ferikan hakka aleyhimud dalaletu, innehumuttehazuş şeyatine evliyae min dunillahi ve yahsebune ennehum muhtedun.', 'Bir kısmını[1] doğru yola iletti. Bir kısmı da sapkın yolu hak etti. Zira onlar,  Allah\'ın yanı sıra şeytanları evliya[2] edindiler. Ve kendilerini de doğru yolda olduklarını sanıyorlar!', 'فريقا هدي وفريقا حق عليهم الضللة انهم اتخذوا الشيطين اوليا من دون الله ويحسبون انهم مهتدون'),
(985, 7, 31, 'يَا بَن۪ٓي اٰدَمَ خُذُوا ز۪ينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُواۚ اِنَّهُ لَا يُحِبُّ الْمُسْرِف۪ينَ۟', 'Ya beni ademe huzu zinetekum inde kulli mescidin ve kulu veşrebu ve la tusrifu, innehu la yuhıbbul musrifin.', 'Ey Âdemoğulları! Her secde edilen yerde[1] ziynetlerinizi[2] alın. Yiyin,  için fakat israf[3] etmeyin. Zira O,  israf edenleri sevmez.', 'يبني ادم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا انه لا يحب المسرفين'),
(986, 7, 32, 'قُلْ مَنْ حَرَّمَ ز۪ينَةَ اللّٰهِ الَّت۪ٓي اَخْرَجَ لِعِبَادِه۪ وَالطَّيِّبَاتِ مِنَ الرِّزْقِۜ قُلْ هِيَ لِلَّذ۪ينَ اٰمَنُوا فِي الْحَيٰوةِ الدُّنْيَا خَالِصَةً يَوْمَ الْقِيٰمَةِۜ  كَذٰلِكَ نُفَصِّلُ الْاٰيَاتِ لِقَوْمٍ يَعْلَمُونَ', 'Kul men harreme zinetallahilleti ahrece li ibadihi vet tayyibati miner rızk, kul hiye lillezine amenu fil hayatid dunya halisaten yevmel kıyameh, kezalike nufassılul ayati li kavmin ya\'lemun.', 'De ki: \"Allah\'ın kulları için çıkardığı ziyneti[1] ve temiz rızıkları kim haram etmiş?\" De ki: \"Bunlar dünya hayatında iman edenlerindir; Kıyamet Günü ise yalnız onlara aittir.\" Bilen bir topluma ayetleri böyle detaylı olarak açıklıyoruz.', 'قل من حرم زينة الله التي اخرج لعباده والطيبت من الرزق قل هي للذين امنوا في الحيوة الدنيا خالصة يوم القيمة كذلك نفصل الايت لقوم يعلمون'),
(987, 7, 33, 'قُلْ اِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْاِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَاَنْ تُشْرِكُوا بِاللّٰهِ مَا لَمْ يُنَزِّلْ بِه۪ سُلْطَاناً وَاَنْ تَقُولُوا عَلَى اللّٰهِ مَا لَا تَعْلَمُونَ', 'Kul innema harreme rabbiyel fevahişe ma zahere minha ve ma batane vel isme vel bagye bi gayril hakkı ve en tuşriku billahi ma lem yunezzil bihi sultanen ve en tekulu alallahi ma la ta\'lemun.', 'De ki: \"Rabb\'im şunları kesinlikle haram kılmıştır: Fuhuşların[1] açık olanını ve gizli olanını,  günahları,  haksız yere saldırmayı,  hakkında hiçbir belge indirmediği herhangi bir şeyi Allah\'a ortak koşmayı ve Allah\'a,  bilmediğiniz şeyleri yakıştırmanızı.', 'قل انما حرم ربي الفوحش ما ظهر منها وما بطن والاثم والبغي بغير الحق وان تشركوا بالله ما لم ينزل به سلطنا وان تقولوا علي الله ما لا تعلمون'),
(988, 7, 34, 'وَلِكُلِّ اُمَّةٍ اَجَلٌۚ فَاِذَا جَٓاءَ اَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'Ve li kulli ummetin ecel, fe iza cae eceluhum la yeste\'hırune saaten ve la yestakdimun.', 'Her ümmetin[1] bir eceli[2] vardır. Ecelleri gelince ne bir an ertelenir ne de bir an öne alınır.', 'ولكل امة اجل فاذا جا اجلهم لا يستاخرون ساعة ولا يستقدمون'),
(989, 7, 35, 'يَا بَن۪ٓي اٰدَمَ اِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ اٰيَات۪يۙ فَمَنِ اتَّقٰى وَاَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Ya beni ademe imma ye\'tiyennekum rusulun minkum yekussune aleykum ayati fe menitteka ve asleha fe la havfun aleyhim ve la hum yahzenun.', 'Ey Âdemoğulları! Size,  içinizden ayetlerimi anlatan elçiler geldiğinde,  her kim takvalı davranır ve kendisini düzeltirse,  onlara kaygı yoktur ve onlar üzülmeyecekler de.', 'يبني ادم اما ياتينكم رسل منكم يقصون عليكم ايتي فمن اتقي واصلح فلا خوف عليهم ولا هم يحزنون'),
(990, 7, 36, 'وَالَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَاسْتَكْبَرُوا عَنْهَٓا اُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Vellezine kezzebu bi ayatina vestekberu anha ulaike ashabun nar, hum fiha halidun.', 'Büyüklük taslayarak,  ayetlerimizi yalanlayanlar,  işte onlar ateş halkıdırlar. Onlar,  orada sürekli kalıcıdırlar.', 'والذين كذبوا بايتنا واستكبروا عنها اوليك اصحب النار هم فيها خلدون'),
(991, 7, 37, 'فَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً اَوْ كَذَّبَ بِاٰيَاتِه۪ۜ  اُو۬لٰٓئِكَ يَنَالُهُمْ نَص۪يبُهُمْ مِنَ الْكِتَابِۜ حَتّٰٓى اِذَا جَٓاءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْۙ قَالُٓوا اَيْنَ مَا كُنْتُمْ تَدْعُونَ مِنْ دُونِ اللّٰهِۜ قَالُوا ضَلُّوا عَنَّا وَشَهِدُوا عَلٰٓى اَنْفُسِهِمْ اَنَّهُمْ كَانُوا كَافِر۪ينَ', 'Fe men azlemu mimmeniftera alallahi keziben ev kezzebe bi ayatih ulaike yenaluhum nasibuhum minel kitab, hatta iza caethum rusuluna yeteveffevnehum kalu eyne ma kuntum ted\'une min dunillah kalu dallu anna ve şehidu ala enfusihim ennehum kanu kafirin.', 'Allah\'a iftira eden veya O\'nun ayetlerini yalanlayandan daha haksız kim olabilir? Kitaptaki nasipleri onlara erişecektir.[1] Nihayet resullerimiz[2],  canlarını almak için onlara geldiğinde,  \"Allah\'tan başka yakardığınız ilahlar nerede?\" ediklerinde; onlar da: \"Onlar bizden uzaklaşıp gittiler.\" dediler. Kafir[3] olduklarına dair kendi aleyhlerinde tanıklık ettiler.', 'فمن اظلم ممن افتري علي الله كذبا او كذب بايته اوليك ينالهم نصيبهم من الكتب حتي اذا جاتهم رسلنا يتوفونهم قالوا اين ما كنتم تدعون من دون الله قالوا ضلوا عنا وشهدوا علي انفسهم انهم كانوا كفرين'),
(992, 7, 38, 'قَالَ ادْخُلُوا ف۪ٓي اُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِكُمْ مِنَ الْجِنِّ وَالْاِنْسِ فِي النَّارِۜ   كُلَّمَا دَخَلَتْ اُمَّةٌ لَعَنَتْ اُخْتَهَاۜ  حَتّٰٓى اِذَا ادَّارَكُوا ف۪يهَا جَم۪يعاًۙ قَالَتْ اُخْرٰيهُمْ لِاُو۫لٰيهُمْ رَبَّنَا هٰٓؤُ۬لَٓاءِ اَضَلُّونَا فَاٰتِهِمْ عَذَاباً ضِعْفاً مِنَ النَّارِۜ قَالَ لِكُلٍّ ضِعْفٌ وَلٰكِنْ لَا تَعْلَمُونَ', 'Kaledhulu fi umemin kad halet min kablikum minel cinni vel insi fin nar, kullema dehalet ummetun leanet uhteha, hatta izeddareku fiha cemian kalet uhrahum li ulahum rabbena haulai edalluna fe atihim azaben di\'fen minen nar kale li kullin di\'fun ve lakin la ta\'lemun.', 'Buyurdu ki: \"Sizden önceki cinn[1] ve insten[1] ümmetler[2] arasında siz de ateşe girin. Her ümmet girdikçe,  yoldaşlarına lanet etti. Birbiri ardına hepsi orada toplandığı zaman; sonrakiler öncekiler için: \"Ey Rabb\'imiz! Bunlar bizi saptırdılar,  bunlara ateşten bir kat daha azap ver.\" \"Hepsi için bir kat fazla vardır,  ama siz bilmezsiniz.\"[3] dedi.', 'قال ادخلوا في امم قد خلت من قبلكم من الجن والانس في النار كلما دخلت امة لعنت اختها حتي اذا اداركوا فيها جميعا قالت اخريهم لاوليهم ربنا هولا اضلونا فاتهم عذابا ضعفا من النار قال لكل ضعف ولكن لا تعلمون'),
(993, 7, 39, 'وَقَالَتْ اُو۫لٰيهُمْ لِاُخْرٰيهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِنْ فَضْلٍ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْسِبُونَ۟', 'Ve kalet ulahum li uhrahum fe ma kane lekum aleyna min fadlin fe zukul azabe bima kuntum teksibun.', 'Öncekiler de sonrakilere: \"Sizin,  bizden iyi bir tarafınız yoktu. O halde kazandıklarınıza karşılık azabı tadın.\" dediler.', 'وقالت اوليهم لاخريهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون'),
(994, 7, 40, 'اِنَّ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا لَا تُفَتَّحُ لَهُمْ اَبْوَابُ السَّمَٓاءِ وَلَا يَدْخُلُونَ الْجَنَّةَ حَتّٰى يَلِجَ الْجَمَلُ ف۪ي سَمِّ الْخِيَاطِۜ وَكَذٰلِكَ نَجْزِي الْمُجْرِم۪ينَ', 'İnnellezine kezzebu bi ayatina vestekberu anha la tufettehu lehum ebvabus semai ve la yedhulunel cennete hatta yelicel cemelu fi semmil hiyat ve kezalike neczil mucrimin.', 'Ayetlerimizi yalanlayan ve büyüklenenler var ya,  onlara gök kapıları açılmayacak ve onlar deve[1] iğnenin deliğinden geçmedikçe,  Cennet\'e giremeyeceklerdir. Mücrimleri[2] böyle cezalandırırız.', 'ان الذين كذبوا بايتنا واستكبروا عنها لا تفتح لهم ابواب السما ولا يدخلون الجنة حتي يلج الجمل في سم الخياط وكذلك نجزي المجرمين'),
(995, 7, 41, 'لَهُمْ مِنْ جَهَنَّمَ مِهَادٌ وَمِنْ فَوْقِهِمْ غَوَاشٍۜ وَكَذٰلِكَ نَجْزِي الظَّالِم۪ينَ', 'Lehum min cehenneme mihadun ve min fevkıhim gavaş ve kezalike necziz zalimin.', 'Onlar için cehennemden döşek ve örtüler vardır. İşte zalimleri böyle cezalandırırız.', 'لهم من جهنم مهاد ومن فوقهم غواش وكذلك نجزي الظلمين'),
(996, 7, 42, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَا نُكَلِّفُ نَفْساً اِلَّا وُسْعَهَاۘ اُو۬لٰٓئِكَ اَصْحَابُ الْجَنَّةِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Vellezine amenu ve amilus salihati la nukellifu nefsen illa vus\'aha ulaike ashabul cenneh, hum fiha halidun.', 'İman edip salihatı[1] yapanlar- ki hiç kimseye gücünün yettiğinden başkasını yüklemeyiz- Onlar,  orada sürekli kalacaklardır.', 'والذين امنوا وعملوا الصلحت لا نكلف نفسا الا وسعها اوليك اصحب الجنة هم فيها خلدون'),
(997, 7, 43, 'وَنَزَعْنَا مَا ف۪ي صُدُورِهِمْ مِنْ غِلٍّ تَجْر۪ي مِنْ تَحْتِهِمُ الْاَنْهَارُۚ وَقَالُوا الْحَمْدُ لِلّٰهِ الَّذ۪ي هَدٰينَا لِهٰذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَٓا اَنْ هَدٰينَا اللّٰهُۚ  لَقَدْ جَٓاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّۜ وَنُودُٓوا اَنْ تِلْكُمُ الْجَنَّةُ اُو۫رِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ve neza\'na ma fi sudurihim min gıllin tecri min tahtihimul enhar, ve kalul hamdu lillahillezi hedana li haza ve ma kunna li nehtediye levla en hedanallah, lekad caet rusulu rabbina bil hakk, ve nudu en tilkumul cennetu uristumuha bima kuntum ta\'melun.', 'Göğüslerinde tasadan ne varsa çıkarıp almışız. Yanı başlarında ırmaklar akmaktadır. Derler ki: \"Bizi buna ulaştıran Allah\'a hamdolsun. Eğer Allah bizi doğru yola iletmeseydi biz kendiliğimizden doğru yolu bulamazdık. Ant olsun ki Rabb\'imizin resulleri gerçeği getirmişlerdir.\" Onlara: \"İşte yaptığınız işlere karşılık,  hak ettiğiniz Cennet budur.\" diye seslenilir.', 'ونزعنا ما في صدورهم من غل تجري من تحتهم الانهر وقالوا الحمد لله الذي هدينا لهذا وما كنا لنهتدي لولا ان هدينا الله لقد جات رسل ربنا بالحق ونودوا ان تلكم الجنة اورثتموها بما كنتم تعملون'),
(998, 7, 44, 'وَنَادٰٓى اَصْحَابُ الْجَنَّةِ اَصْحَابَ النَّارِ اَنْ قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقاًّ فَهَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقاًّۜ  قَالُوا نَعَمْۚ فَاَذَّنَ مُؤَذِّنٌ بَيْنَهُمْ اَنْ لَعْنَةُ اللّٰهِ عَلَى الظَّالِم۪ينَۙ', 'Ve nada ashabul cenneti ashaben nari en kad vecedna ma vaadena rabbuna hakka fe hel vecedtum ma vaade rabbukum hakka kalu neam fe ezzene muezzinun beynehum en la\'netullahi alez zalimin.', 'Cennet halkı,  Cehennem halkına,  \"Rabb\'imizin bize söz verdiklerinin gerçek olduğunu gördük; siz de Rabb\'inizin size söylediklerinin gerçek olduğunu gördünüz mü?\" diye seslenirler. \"Evet.\" derler. Aralarından bir çağırıcı,  \"Allah\'ın laneti zalimlerin üzerine olsun.\" diye bağırır.', 'ونادي اصحب الجنة اصحب النار ان قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا قالوا نعم فاذن موذن بينهم ان لعنة الله علي الظلمين'),
(999, 7, 45, 'اَلَّذ۪ينَ يَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ وَيَبْغُونَهَا عِوَجاًۚ وَهُمْ بِالْاٰخِرَةِ كَافِرُونَۜ', 'Ellezine yasuddune an sebilillahi ve yebguneha iveca ve hum bil ahireti kafirun.', 'Onlar,  Allah\'ın yolundan alıkoyan ve onu eğri göstermek isteyen ve Ahireti de inkar eden kimselerdi.', 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخرة كفرون'),
(1000, 7, 46, 'وَبَيْنَـهُمَا حِجَابٌۚ وَعَلَى الْاَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلاًّ بِس۪يمٰيهُمْۚ وَنَادَوْا اَصْحَابَ الْجَنَّةِ اَنْ سَلَامٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', 'Ve beynehuma hicab ve alel a\'rafi ricalun ya\'rifune kullen bi simahum ve nadev ashabel cenneti en selamun aleykum lem yedhuluha ve hum yatmeun.', 'İki taraf arasında bir hicap[1] vardır. Ve A\'raf\'[2] üzerinde de hepsini simalarından tanıyan kimseler vardır. Henüz Cennet\'e girmemiş olan,  fakat girmeyi uman Cennet halkına: \"Size selam olsun.\" diye seslendiler.', 'وبينهما حجاب وعلي الاعراف رجال يعرفون كلا بسيميهم ونادوا اصحب الجنة ان سلم عليكم لم يدخلوها وهم يطمعون'),
(1001, 7, 47, 'وَاِذَا صُرِفَتْ اَبْصَارُهُمْ تِلْقَٓاءَ اَصْحَابِ النَّارِۙ قَالُوا رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِم۪ينَ۟', 'Ve iza surifet ebsaruhum tilkae ashabin nari kalu rabbena la tec\'alna mealkavmiz zalimin.', 'Bakışları ateş halkı tarafına döndürülünce de \"Ey Rabb\'imiz! Bizi zalim halkla beraber bulundurma.\" derler.', 'واذا صرفت ابصرهم تلقا اصحب النار قالوا ربنا لا تجعلنا مع القوم الظلمين'),
(1002, 7, 48, 'وَنَادٰٓى اَصْحَابُ الْاَعْرَافِ رِجَالاً يَعْرِفُونَهُمْ بِس۪يمٰيهُمْ قَالُوا مَٓا اَغْنٰى عَنْكُمْ جَمْعُكُمْ وَمَا كُنْتُمْ تَسْتَكْبِرُونَ', 'Ve nada ashabul\'a\'rafi ricalen ya\'rifunehum bi simahum kalu ma agna ankum cem\'ukum ve ma kuntum testekbirun.', 'A\'raf halkı,  yüzlerinden tanıdıkları kimselere de: \"Çokluğunuz da,  tasladığınız büyüklük de size bir yarar sağlamadı.\" dediler.', 'ونادي اصحب الاعراف رجالا يعرفونهم بسيميهم قالوا ما اغني عنكم جمعكم وما كنتم تستكبرون'),
(1003, 7, 49, 'اَهٰٓؤُ۬لَٓاءِ الَّذ۪ينَ اَقْسَمْتُمْ لَا يَنَالُهُمُ اللّٰهُ بِرَحْمَةٍۜ اُدْخُلُوا الْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَٓا اَنْتُمْ تَحْزَنُونَ', 'E haulaillezine aksemtum la yenaluhumullahu bi rahmeh udhulul cennete la havfun aleykum ve la entum tahzenun.', 'Cehennemliklere; \"Allah,  hiçbir rahmete erdirmeyecek diye yemin ettiğiniz kimseler bunlar mıydı?\" Onlara:[1] \"Girin Cennet\'e,  artık size korku yoktur. Üzülecek de değilsiniz.\" denir.', 'اهولا الذين اقسمتم لا ينالهم الله برحمة ادخلوا الجنة لا خوف عليكم ولا انتم تحزنون'),
(1004, 7, 50, 'وَنَادٰٓى اَصْحَابُ النَّارِ اَصْحَابَ الْجَنَّةِ اَنْ اَف۪يضُوا عَلَيْنَا مِنَ الْمَٓاءِ اَوْ مِمَّا رَزَقَكُمُ اللّٰهُۜ قَالُٓوا اِنَّ اللّٰهَ حَرَّمَهُمَا عَلَى الْكَافِر۪ينَۙ', 'Ve nada ashabun nari ashabel cenneti en efidu aleyna minel mai ev mimma rezekakumullah, kalu innallahe harremehuma alel kafirin.', 'Ateş halkı,  Cennet halkına,  \"Suyunuzdan veya Allah\'ın rızık olarak verdiği şeylerden biraz da bize verin.\" diye feryat ederler. Onlar,  \"Allah,  bu ikisini Kafirlere haram kılmıştır.\" derler.', 'ونادي اصحب النار اصحب الجنة ان افيضوا علينا من الما او مما رزقكم الله قالوا ان الله حرمهما علي الكفرين'),
(1005, 7, 51, 'اَلَّذ۪ينَ اتَّخَذُوا د۪ينَهُمْ لَهْواً وَلَعِباً وَغَرَّتْهُمُ الْحَيٰوةُ الدُّنْيَاۚ فَالْيَوْمَ نَنْسٰيهُمْ كَمَا نَسُوا لِقَٓاءَ يَوْمِهِمْ هٰذَاۙ وَمَا كَانُوا بِاٰيَاتِنَا يَجْحَدُونَ', 'Ellezinettehazu dinehum lehven ve leiben ve garrethumul hayatud dunya, felyevme nensahum kema nesu likae yevmihim haza ve ma kanu bi ayatina yechadun.', 'Onlar ki,  dinlerini bir oyun ve eğlence yerine koydular. Dünya hayatı onları aldattı. Onlar,  karşılaşacakları bugünü unuttukları ve ayetlerimizi bile bile inkar ettikleri gibi,  biz de onları unuturuz.', 'الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحيوة الدنيا فاليوم ننسيهم كما نسوا لقا يومهم هذا وما كانوا بايتنا يجحدون'),
(1006, 7, 52, 'وَلَقَدْ جِئْنَاهُمْ بِكِتَابٍ فَصَّلْنَاهُ عَلٰى عِلْمٍ هُدًى وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ', 'Ve lekad ci\'nahum bi kitabin fassalnahu ala ilmin huden ve rahmeten li kavmin yu\'minun.', 'Gerçekten Biz,  onlara,  iman etmek isteyen bir halk için,  bilgiye göre açıkladığımız; yol gösterici ve rahmet olan bir Kitap getirdik.', 'ولقد جينهم بكتب فصلنه علي علم هدي ورحمة لقوم يومنون'),
(1007, 7, 53, 'هَلْ يَنْظُرُونَ اِلَّا تَأْو۪يلَهُۜ يَوْمَ يَأْت۪ي تَأْو۪يلُهُ يَقُولُ الَّذ۪ينَ نَسُوهُ مِنْ قَبْلُ قَدْ جَٓاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّۚ فَهَلْ لَنَا مِنْ شُفَعَٓاءَ فَيَشْفَعُوا لَـنَٓا اَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذ۪ي كُنَّا نَعْمَلُۜ قَدْ خَسِرُٓوا اَنْفُسَهُمْ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ۟', 'Hel yanzurune illa te\'vileh, yevme ye\'ti te\'viluhu yekulullezine nesuhu min kablu kad caet rusulu rabbina bil hakk, fe hel lena min şufeae fe yeşfeu lena ev nureddu fe na\'mele gayrellezi kunna na\'mel, kad hasiru enfusehum ve dalle anhum ma kanu yefterun.', 'Onun verdiği haberin gerçekleşmesini mi bekliyorlar? Onun haberinin gerçekleştiği gün,  daha önce onu unutmuş olanlar diyecekler ki: \"Gerçekten Rabb\'imizin resulleri gerçeği getirmişler. Acaba bir şefaatçi[1] var mıdır ki bize şefaatte bulunsun veya geri döndürülsek de yaptıklarımızdan başkasını yapsak?\" Gerçekten onlar kendilerine yazık etmişlerdir. Uydurdukları şeyler kendilerinden uzaklaşıp kaybolmuştur.', 'هل ينظرون الا تاويله يوم ياتي تاويله يقول الذين نسوه من قبل قد جات رسل ربنا بالحق فهل لنا من شفعا فيشفعوا لنا او نرد فنعمل غير الذي كنا نعمل قد خسروا انفسهم وضل عنهم ما كانوا يفترون'),
(1008, 7, 54, 'اِنَّ رَبَّكُمُ اللّٰهُ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ ف۪ي سِتَّةِ اَيَّامٍ ثُمَّ اسْتَوٰى عَلَى الْعَرْشِ يُغْشِي الَّيْلَ النَّهَارَ يَطْلُبُهُ حَث۪يثاًۙ وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِاَمْرِه۪ۜ اَلَا لَهُ الْخَلْقُ وَالْاَمْرُۜ تَبَارَكَ اللّٰهُ رَبُّ الْعَالَم۪ينَ', 'İnne rabbekumullahullezi halakas semavati vel arda fi sitteti eyyamin summesteva alel arşı, yugşil leylen nehare yatlubuhu hasisen veş şemse vel kamere ven nucume musahharatin bi emrih, e la lehul halku vel emr, tebarekallahu rabbulalemin.', 'Rabb\'iniz; gökleri ve yeri altı günde[1] yaratan,  sonra arş üstüne isteva eden;[2] geceyi,  durmadan takip eden gündüze katan; Güneş\'i,  Ay\'ı ve yıldızları emrine tabi kılan Allah\'tır. Dikkat edin! Yaratmak da emretmek de yalnız O\'na özgüdür. Âlemlerin Rabb\'i olan Allah,  Şanı Çok Yücedir.', 'ان ربكم الله الذي خلق السموت والارض في ستة ايام ثم استوي علي العرش يغشي اليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرت بامره الا له الخلق والامر تبارك الله رب العلمين'),
(1009, 7, 55, 'اُدْعُوا رَبَّكُمْ تَضَرُّعاً وَخُفْيَةًۜ اِنَّهُ لَا يُحِبُّ الْمُعْتَد۪ينَۚ', 'Ud\'u rabbekum tedarruan ve hufyeh, innehu la yuhıbbul mu\'tedin.', 'Rabb\'inize \"tederruan\"[1] ve \"hufyeten\"[2] dua edin. Kuşkusuz O,  haddi aşanları sevmez.', 'ادعوا ربكم تضرعا وخفية انه لا يحب المعتدين'),
(1010, 7, 56, 'وَلَا تُفْسِدُوا فِي الْاَرْضِ بَعْدَ اِصْلَاحِهَا وَادْعُوهُ خَوْفاً وَطَمَعاًۜ اِنَّ رَحْمَتَ اللّٰهِ قَر۪يبٌ مِنَ الْمُحْسِن۪ينَ', 'Ve la tufsidu fil ardı ba\'de ıslahıha ved\'uhu havfen ve tamaa inne rahmetallahi karibun minel muhsinin.', 'Ve düzeltildikten sonra,  yeryüzünde bozgunculuk yapmayın. O\'na endişe ve ümit ile dua edin. Kuşkusuz Allah\'ın rahmeti muhsin[1] olanlara yakındır.', 'ولا تفسدوا في الارض بعد اصلحها وادعوه خوفا وطمعا ان رحمت الله قريب من المحسنين'),
(1011, 7, 57, 'وَهُوَ الَّذ۪ي يُرْسِلُ الرِّيَاحَ بُشْراً بَيْنَ يَدَيْ رَحْمَتِه۪ۜ حَتّٰٓى اِذَٓا اَقَلَّتْ سَحَاباً ثِقَالاً سُقْنَاهُ لِبَلَدٍ مَيِّتٍ فَاَنْزَلْنَا بِهِ الْمَٓاءَ فَاَخْرَجْنَا بِه۪ مِنْ كُلِّ الثَّمَرَاتِۜ   كَذٰلِكَ نُخْرِجُ الْمَوْتٰى لَعَلَّكُمْ تَذَكَّرُونَ', 'Ve huvellezi yursilur riyaha buşren beyne yedey rahmetih, hatta iza ekallet sehaben sikale suknahu li beledin meyyitin fe enzelna bihil mae fe ahrecna bihimin kullissemerat, kezalikenuhricul mevta leallekum tezekkerun.', 'Rahmetinin önünde rüzgarları müjdeci olarak gönderen O\'dur. Rüzgarlar,  ağır bulutları yüklenince,  onları ölü bir beldeye sevk ederiz. Böylece onunla indirdiğimiz suyla,  orada her türlü ürünü çıkarırız. İşte Biz ölüleri de böyle diriltip çıkarırız. Umulur ki düşünüp öğüt alırsınız.', 'وهو الذي يرسل الريح بشرا بين يدي رحمته حتي اذا اقلت سحابا ثقالا سقنه لبلد ميت فانزلنا به الما فاخرجنا به من كل الثمرت كذلك نخرج الموتي لعلكم تذكرون'),
(1012, 7, 58, 'وَالْبَلَدُ الطَّيِّبُ يَخْرُجُ نَبَاتُهُ بِاِذْنِ رَبِّه۪ۚ وَالَّذ۪ي خَبُثَ لَا يَخْرُجُ اِلَّا نَكِداًۜ  كَذٰلِكَ نُصَرِّفُ الْاٰيَاتِ لِقَوْمٍ يَشْكُرُونَ۟', 'Vel beledut tayyibu yahrucu nebatuhu bi izni rabbih, vellezi habuse la yahrucu illa nekida, kezalike nusarriful ayati li kavmin yeşkurun.', 'Toprağı iyi olan beldenin bitkisi,  Rabb\'inin izni ile[1] verimli olur. Toprağı kötü olan beldenin ürünü verimsiz olur. Şükreden bir kavim için ayetleri böyle ayrıntılı olarak açıklıyoruz.', 'والبلد الطيب يخرج نباته باذن ربه والذي خبث لا يخرج الا نكدا كذلك نصرف الايت لقوم يشكرون'),
(1013, 7, 59, 'لَقَدْ اَرْسَلْنَا نُوحاً اِلٰى قَوْمِه۪ فَقَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ اِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Lekad erselna nuhan ila kavmihi fe kale ya kavmi\'budullahe ma lekum min ilahin gayruh, inni ehafu aleykum azabe yevmin azim.', 'Ant olsun ki Biz,  Nuh\'u halkına gönderdik. \"Ey halkım! Allah\'a kulluk edin. Sizin için O\'ndan başka ilah yoktur; kuşkusuz ben,  sizin için o büyük günün azabından korkuyorum.\" dedi.', 'لقد ارسلنا نوحا الي قومه فقال يقوم اعبدوا الله ما لكم من اله غيره اني اخاف عليكم عذاب يوم عظيم'),
(1014, 7, 60, 'قَالَ الْمَلَأُ مِنْ قَوْمِه۪ٓ اِنَّا لَنَرٰيكَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Kalel meleu min kavmihi inna le nerake fi dalalin mubin.', 'Halkının meleleri:[1] \"Biz,  seni kesin bir sapkınlık içinde görüyoruz.\" dediler.', 'قال الملا من قومه انا لنريك في ضلل مبين'),
(1015, 7, 61, 'قَالَ يَا قَوْمِ لَيْسَ ب۪ي ضَلَالَةٌ وَلٰكِنّ۪ي رَسُولٌ مِنْ رَبِّ الْعَالَم۪ينَ', 'Kale ya kavmi leyse bi dalaletun ve lakinni resulun min rabbil alemin.', '\"Ey halkım,  bende bir sapkınlık yok. Ben ancak alemlerin Rabb\'inden bir elçiyim.\"', 'قال يقوم ليس بي ضللة ولكني رسول من رب العلمين'),
(1016, 7, 62, 'اُبَلِّغُكُمْ رِسَالَاتِ رَبّ۪ي وَاَنْصَحُ لَكُمْ وَاَعْلَمُ مِنَ اللّٰهِ مَا لَا تَعْلَمُونَ', 'Ubelligukum risalati rabbi ve ensahu lekum ve a\'lemu minallahi ma la ta\'lemun.', '\"Rabb\'imin gönderdiklerini size tebliğ ediyorum. Ve size öğüt veriyorum. Allah tarafından,  sizin bilmediklerinizi biliyorum.\"', 'ابلغكم رسلت ربي وانصح لكم واعلم من الله ما لا تعلمون'),
(1017, 7, 63, 'اَوَعَجِبْتُمْ اَنْ جَٓاءَكُمْ ذِكْرٌ مِنْ رَبِّكُمْ عَلٰى رَجُلٍ مِنْكُمْ لِيُنْذِرَكُمْ وَلِتَتَّقُوا وَلَعَلَّكُمْ تُرْحَمُونَ', 'E ve acibtum en caekum zikrun min rabbikum ala raculin minkum li yunzirekum ve li tetteku ve leallekum turhamun.', '\"Takvalı[1] olmanızı sağlamak ve böylece merhamet olunmanız için; içinizden sizi uyaracak bir adama Rabb\'inizden size bir zikir[2] gelmesine mi şaştınız?\"', 'اوعجبتم ان جاكم ذكر من ربكم علي رجل منكم لينذركم ولتتقوا ولعلكم ترحمون'),
(1018, 7, 64, 'فَكَذَّبُوهُ فَاَنْجَيْنَاهُ وَالَّذ۪ينَ مَعَهُ فِي الْفُلْكِ وَاَغْرَقْنَا الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَاۜ اِنَّهُمْ كَانُوا قَوْماً عَم۪ينَ۟', 'Fe kezzebuhu fe enceynahu vellezine meahu fil fulki ve agraknellezine kezzebu bi ayatina, innehum kanu kavmen amin.', 'Derken,  halkı onu yalanladı. Biz de onu ve onunla beraber gemide bulunanları kurtardık. Âyetlerimizi yalanlayanları da boğduk. Onlar gerçeği görmeyen bir kavimdi.', 'فكذبوه فانجينه والذين معه في الفلك واغرقنا الذين كذبوا بايتنا انهم كانوا قوما عمين'),
(1019, 7, 65, 'وَاِلٰى عَادٍ اَخَاهُمْ هُوداًۜ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ اَفَلَا تَتَّقُونَ', 'Ve ila adin ehahum huda, kale ya kavmi\'budullahe ma lekum min ilahin gayruh, e fe la tettekun.', 'Ad halkına da kardeşleri Hud\'u gönderdik. \"Ey halkım! Allah\'a kulluk edin ve sizin için O\'ndan başka ilah yoktur. Yine de takva sahibi olmayacak mısınız?\" dedi.', 'والي عاد اخاهم هودا قال يقوم اعبدوا الله ما لكم من اله غيره افلا تتقون'),
(1020, 7, 66, 'قَالَ الْمَلَأُ الَّذ۪ينَ كَفَرُوا مِنْ قَوْمِه۪ٓ اِنَّا لَنَرٰيكَ ف۪ي سَفَاهَةٍ وَاِنَّا لَنَظُنُّكَ مِنَ الْكَاذِب۪ينَ', 'Kalelmeleullezine keferu min kavmihi inna le nerake fi sefahetin ve inna le nezunnuke minel kazibin.', 'Halkının Kafir[1] meleleri:[2] \"Gerçekten biz seni beyinsizlerden görüyoruz ve gerçekten seni yalancılardan sanıyoruz.\" dediler.[3]', 'قال الملا الذين كفروا من قومه انا لنريك في سفاهة وانا لنظنك من الكذبين'),
(1021, 7, 67, 'قَالَ يَا قَوْمِ لَيْسَ ب۪ي سَفَاهَةٌ وَلٰكِنّ۪ي رَسُولٌ مِنْ رَبِّ الْعَالَم۪ينَ', 'Kale ya kavmi leyse bi sefahetun ve lakinni resulun min rabbil alemin.', '\"Ey halkım! Ben beyinsizlerden değilim. Ben ancak alemlerin Rabb\'inden bir elçiyim.\" dedi.', 'قال يقوم ليس بي سفاهة ولكني رسول من رب العلمين'),
(1022, 7, 68, 'اُبَلِّغُكُمْ رِسَالَاتِ رَبّ۪ي وَاَنَا۬ لَكُمْ نَاصِحٌ اَم۪ينٌ', 'Ubelligukum risalati rabbi ve ene lekum nasıhun emin.', '\"Ben,  size Rabb\'imin mesajlarını iletiyorum. Ben,  sizin için güvenilir bir öğütçüyüm.\"', 'ابلغكم رسلت ربي وانا لكم ناصح امين'),
(1023, 7, 69, 'اَوَعَجِبْتُمْ اَنْ جَٓاءَكُمْ ذِكْرٌ مِنْ رَبِّكُمْ عَلٰى رَجُلٍ مِنْكُمْ لِيُنْذِرَكُمْۜ  وَاذْكُرُٓوا اِذْ جَعَلَكُمْ خُلَـفَٓاءَ مِنْ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِي الْخَلْقِ بَصْۣـطَةًۚ فَاذْكُرُٓوا اٰلَٓاءَ اللّٰهِ لَعَلَّكُمْ تُفْلِحُونَ', 'E ve acibtum en caekum zikrun min rabbikum ala raculin minkum li yunzirekum, vezkuru iz cealekum hulefae min ba\'di kavmi nuhın ve zadekum fil halkı bastaten, fezkuru alaallahi leallekum tuflihun.', '\"Sizi uyarması için,  içinizden bir kimse aracılığıyla Rabb\'inizden size bir zikir[1] gelmesine hayret mi ettiniz? Nuh toplumundan sonra sizi onların yerine geçirdiğini hatırlayın. Ve yaradılışça sizi onlardan güçlü kıldı. O halde Allah\'ın nimetlerini hatırlayın. Umulur ki kurtuluşa erersiniz.\"', 'اوعجبتم ان جاكم ذكر من ربكم علي رجل منكم لينذركم واذكروا اذ جعلكم خلفا من بعد قوم نوح وزادكم في الخلق بصطة فاذكروا الا الله لعلكم تفلحون'),
(1024, 7, 70, 'قَالُٓوا اَجِئْتَنَا لِنَعْبُدَ اللّٰهَ وَحْدَهُ وَنَذَرَ مَا كَانَ يَعْبُدُ اٰبَٓاؤُ۬نَاۚ فَأْتِنَا بِمَا تَعِدُنَٓا اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Kalu e ci\'tena li na\'budallahe vahdehu ve nezere ma kane ya\'budu abauna, fe\'tina bi ma teiduna in kunte mines sadıkin.', '\"Sen,  bize,  tek olan Allah\'a kulluk etmemiz ve atalarımızın kulluk ettiklerini bırakmamız için mi geldin? Eğer doğru sözlülerdensen,  haydi bizi tehdit ettiğin şeyi getir!\" dediler.', 'قالوا اجيتنا لنعبد الله وحده ونذر ما كان يعبد اباونا فاتنا بما تعدنا ان كنت من الصدقين'),
(1025, 7, 71, 'قَالَ قَدْ وَقَعَ عَلَيْكُمْ مِنْ رَبِّكُمْ رِجْسٌ وَغَضَبٌۜ اَتُجَادِلُونَن۪ي ف۪ٓي اَسْمَٓاءٍ سَمَّيْتُمُوهَٓا اَنْتُمْ وَاٰبَٓاؤُ۬كُمْ مَا نَزَّلَ اللّٰهُ بِهَا مِنْ سُلْطَانٍۜ فَانْتَظِرُٓوا اِنّ۪ي مَعَكُمْ مِنَ الْمُنْتَظِر۪ينَ', 'Kale kad vakaa aleykum min rabbikum ricsun ve gadabun, e tucadiluneni fi esmain semmeytumuha entum ve abaukum ma nezzelallahu biha min sultanin, fentezıru inni meakum minel muntezırin.', '\"Rabb\'inizin azabı ve öfkesi,  hakkınızda kesinleşti. Haklarında Allah\'ın hiçbir yetki belgesi indirmediği,  sizin ve atalarınızın taktığı isimler hakkında benimle tartışıyor musunuz? Bekleyin öyleyse! Kuşkusuz ben de sizinle beraber bekleyenlerdenim.\" dedi.', 'قال قد وقع عليكم من ربكم رجس وغضب اتجدلونني في اسما سميتموها انتم واباوكم ما نزل الله بها من سلطن فانتظروا اني معكم من المنتظرين'),
(1026, 7, 72, 'فَاَنْجَيْنَاهُ وَالَّذ۪ينَ مَعَهُ بِرَحْمَةٍ مِنَّا وَقَطَعْنَا دَابِرَ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَمَا كَانُوا مُؤْمِن۪ينَ۟', 'Fe enceynahu vellezine meahu bi rahmetin minna ve kata\'na dabirellezine kezzebu bi ayatina ve ma kanu mu\'minin.', 'Onu ve beraberinde olanları bizden bir rahmetle kurtardık. Ayetlerimizi yalanlayıp iman etmeyenlerin ise kökünü kestik.', 'فانجينه والذين معه برحمة منا وقطعنا دابر الذين كذبوا بايتنا وما كانوا مومنين'),
(1027, 7, 73, 'وَاِلٰى ثَمُودَ اَخَاهُمْ صَـالِـحاًۢ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ قَدْ جَٓاءَتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْۜ هٰذِه۪ نَاقَةُ اللّٰهِ لَكُمْ اٰيَةً فَذَرُوهَا تَأْكُلْ ف۪ٓي اَرْضِ اللّٰهِ وَلَا تَمَسُّوهَا بِسُٓوءٍ فَيَأْخُذَكُمْ عَذَابٌ اَل۪يمٌ', 'Ve ila semude ehahum salihan kale ya kavmi\'budullahe ma lekum min ilahin gayruhu, kad caetkum beyyinetun min rabbikum hazihi nakatullahi lekum ayeten fe zeruha te\'kul fi ardıllahi ve la temessuha bi suin fe ye\'huzekum azabun elim.', 'Semud halkına da kardeşleri Salih\'i gönderdik: \"Ey halkım: Allah\'a kulluk edin. Sizin için O\'ndan başka ilah yoktur. Rabb\'inizden size bir beyyinat[1] gelmiştir. İşte şu Allah\'ın dişi devesi[2],  sizin için bir ayettir.[3] Bırakın onu,  Allah\'ın arzında otlasın. Kötü bir amaçla ona yaklaşmayın. Yoksa sizi yakın bir azap yakalar.\" dedi.', 'والي ثمود اخاهم صلحا قال يقوم اعبدوا الله ما لكم من اله غيره قد جاتكم بينة من ربكم هذه ناقة الله لكم اية فذروها تاكل في ارض الله ولا تمسوها بسو فياخذكم عذاب اليم'),
(1028, 7, 74, 'وَاذْ‌كُرُٓوا اِذْ جَعَلَكُمْ خُلَـفَٓاءَ مِنْ بَعْدِ عَادٍ وَبَوَّاَكُمْ فِي الْاَرْضِ تَتَّخِذُونَ مِنْ سُهُولِهَا قُصُوراً وَتَنْحِتُونَ الْجِبَالَ بُيُوتاًۚ  فَاذْكُـرُٓوا اٰلَٓاءَ اللّٰهِ وَلَا تَعْثَوْا فِي الْاَرْضِ مُفْسِد۪ينَ', 'Vezkuru iz cealekum hulefae min ba\'di adin ve bevveekum fil ardı tettehızune min suhuliha kusuren ve tenhitunel cibale buyuten fezkuru alaallahi ve la ta\'sev fil ardı mufsidin.', '\"Hatırlayın! Âd\'dan sonra sizi halifeler yapıp yeryüzüne yerleştirdi. O\'nun ovalarında köşkler yapıyor,  dağlarını yontup evler yapıyorsunuz. Allah\'ın nimetlerini düşünün de yeryüzünde bozgunculuk yapıp karışıklık çıkarmayın.\"', 'واذكروا اذ جعلكم خلفا من بعد عاد وبواكم في الارض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا الا الله ولا تعثوا في الارض مفسدين'),
(1029, 7, 75, 'قَالَ الْمَلَأُ الَّذ۪ينَ اسْتَكْبَرُوا مِنْ قَوْمِه۪ لِلَّذ۪ينَ اسْتُضْعِفُوا لِمَنْ اٰمَنَ مِنْهُمْ اَتَعْلَمُونَ اَنَّ صَالِحاً مُرْسَلٌ مِنْ رَبِّه۪ۜ قَالُٓوا اِنَّا بِمَٓا اُرْسِلَ بِه۪ مُؤْمِنُونَ', 'Kalel meleullezinestekberu min kavmihi lillezinestud\'ıfu li men amene minhum e ta\'lemune enne salihan murselun min rabbihi kalu inna bima ursile bihi mu\'minun.', 'Halkının büyüklük taslayan meleleri[1],  içlerinden iman eden mustezaf\'lara[2]: \"Siz,  Salih\'in,  Rabb\'i tarafından gönderilmiş olduğundan emin misiniz?\" dediler. Onlar da: \"Biz,  onunla gönderilen her şeye iman edenlerdeniz.\" dediler.', 'قال الملا الذين استكبروا من قومه للذين استضعفوا لمن امن منهم اتعلمون ان صلحا مرسل من ربه قالوا انا بما ارسل به مومنون'),
(1030, 7, 76, 'قَالَ الَّذ۪ينَ اسْتَكْبَرُٓوا اِنَّا بِالَّـذ۪ٓي اٰمَنْتُمْ بِه۪ كَافِرُونَ', 'Kalellezinestekberu inna billezi amentum bihi kafirun.', 'Büyüklük taslayan kimseler de dediler ki: \"Biz de sizin iman ettiğiniz şeyi kesin olarak inkar edenleriz.\"', 'قال الذين استكبروا انا بالذي امنتم به كفرون'),
(1031, 7, 77, 'فَعَقَرُوا النَّاقَةَ وَعَتَوْا عَنْ اَمْرِ رَبِّهِمْ وَقَالُوا يَا صَالِحُ ائْتِنَا بِمَا تَعِدُنَٓا اِنْ كُنْتَ مِنَ الْمُرْسَل۪ينَ', 'Fe akarun nakate ve atev an emri rabbihim ve kalu ya salihu\'tina bima teiduna in kunte minel murselin.', 'Derken dişi deveyi kestiler ve böylece Rabb\'inin emrine karşı geldiler ve \"Ey Salih! Sen gerçekten gönderilenlerdensen,  haydi bizi tehdit ettiğin şeyleri getir.\" dediler.', 'فعقروا الناقة وعتوا عن امر ربهم وقالوا يصلح ايتنا بما تعدنا ان كنت من المرسلين'),
(1032, 7, 78, 'فَاَخَذَتْهُمُ الرَّجْفَةُ فَاَصْبَحُوا ف۪ي دَارِهِمْ جَاثِم۪ينَ', 'Fe ehazethumur recfetu fe asbahu fi darihim casimin.', 'Bunun üzerine şiddetli bir sarsıntı onları yakaladı ve yurtlarında dizüstü çöke kaldılar.', 'فاخذتهم الرجفة فاصبحوا في دارهم جثمين'),
(1033, 7, 79, 'فَتَوَلّٰى عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ اَبْلَغْتُكُمْ رِسَالَةَ رَبّ۪ي وَنَصَحْتُ لَـكُمْ وَلٰكِنْ لَا تُحِبُّونَ النَّاصِح۪ينَ', 'Fe tevella anhum ve kale ya kavmi lekad eblagtukum risalete rabbi ve nesahtu lekum ve lakin la tuhıbbunen nasıhin.', 'O da onlardan yüz çevirip: \"Ey halkım,  ben size Rabb\'imin mesajını ilettim ve size öğüt verdim,  ancak siz öğüt verenleri sevmiyorsunuz.\" dedi.', 'فتولي عنهم وقال يقوم لقد ابلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون النصحين'),
(1034, 7, 80, 'وَلُوطاً اِذْ قَالَ لِقَوْمِه۪ٓ اَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ اَحَدٍ مِنَ الْعَالَم۪ينَ', 'Ve lutan iz kale li kavmihi e te\'tunel fahışete ma sebekakum biha min ehadin minel alemin.', 'Hani Lut da halkına şöyle demişti: \"Ey halkım! Sizden önce alemlerden hiç kimsenin yapmadığı bir fahişeliği[1] mi yapıyorsunuz?\"', 'ولوطا اذ قال لقومه اتاتون الفحشة ما سبقكم بها من احد من العلمين'),
(1035, 7, 81, 'اِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِنْ دُونِ النِّسَٓاءِۜ بَلْ اَنْتُمْ قَوْمٌ مُسْرِفُونَ', 'İnnekum le te\'tuner ricale şehveten min dunin nisai, bel entum kavmun musrifun.', '\"Kadınları bırakıp şehvetle erkeklere yaklaşıyorsunuz. Hayır! Siz gerçekten müsrif[1] bir halksınız.\"', 'انكم لتاتون الرجال شهوة من دون النسا بل انتم قوم مسرفون'),
(1036, 7, 82, 'وَمَا كَانَ جَوَابَ قَوْمِه۪ٓ اِلَّٓا اَنْ قَالُٓوا اَخْرِجُوهُمْ مِنْ قَرْيَتِكُمْۚ اِنَّهُمْ اُنَاسٌ يَتَطَهَّرُونَ', 'Ve ma kane cevabe kavmihi illa en kalu ahricuhum min karyetikum, innehum unasun yetetahherun.', 'Halkının cevabı yalnızca şu oldu: \"Çıkarın onları yurtlarınızdan,  zira o insanlar,  kendilerini çok temiz görüyorlar.\"', 'وما كان جواب قومه الا ان قالوا اخرجوهم من قريتكم انهم اناس يتطهرون'),
(1037, 7, 83, 'فَاَنْجَيْنَاهُ وَاَهْلَهُٓ اِلَّا امْرَاَتَهُۘ  كَانَتْ مِنَ الْغَابِر۪ينَ', 'Fe enceynahu ve ehlehu illemreetehu kanet minel gabirin.', 'Bunun üzerine onu ve yanında yer alanları kurtardık. Karısı hariç; o,  geride kalanlardan oldu.', 'فانجينه واهله الا امراته كانت من الغبرين'),
(1038, 7, 84, 'وَاَمْطَرْنَا عَلَيْهِمْ مَطَراًۜ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِم۪ينَ۟', 'Ve emtarna aleyhim matara, fenzur keyfe kane akıbetul mucrimin.', 'Üzerlerine bir yağmur yağdırdık. Bak,  mücrimlerin[1] sonu nasıl oldu!', 'وامطرنا عليهم مطرا فانظر كيف كان عقبة المجرمين'),
(1039, 7, 85, 'وَاِلٰى مَدْيَنَ اَخَاهُمْ شُعَيْباًۜ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ قَدْ جَٓاءَتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ فَاَوْفُوا الْكَيْلَ وَالْم۪يزَانَ وَلَا تَبْخَسُوا النَّاسَ اَشْيَٓاءَهُمْ وَلَا تُفْسِدُوا فِي الْاَرْضِ بَعْدَ اِصْلَاحِهَاۜ ذٰلِكُمْ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَۚ', 'Ve ila medyene ehahum şuayba kale ya kavmi\'budullahe ma lekum min ilahin gayruhu kad caetkum beyyinetun min rabbikum fe evful keyle vel mizane ve la tebhasun nase eşyaehum ve la tufsidu fil ardı ba\'de ıslahıha zalikum hayrun lekum in kuntum mu\'minin.', 'Medyen\'e de kardeşleri Şuayb\'ı. Dedi ki: \"Ey halkım! Allah\'a kulluk edin. Sizin için O\'ndan başka ilah yoktur. Rabb\'inizden size bir beyyinat[1] gelmiştir. Ölçüyü ve tartıyı tam yapın. İnsanlara mallarını eksik vermeyin. Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın;[2] eğer mü\'minler iseniz bu,  sizin için hayırlı olandır.\"', 'والي مدين اخاهم شعيبا قال يقوم اعبدوا الله ما لكم من اله غيره قد جاتكم بينة من ربكم فاوفوا الكيل والميزان ولا تبخسوا الناس اشياهم ولا تفسدوا في الارض بعد اصلحها ذلكم خير لكم ان كنتم مومنين'),
(1040, 7, 86, 'وَلَا تَقْعُدُوا بِكُلِّ صِرَاطٍ تُوعِدُونَ وَتَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ مَنْ اٰمَنَ بِه۪ وَتَبْغُونَهَا عِوَجاًۚ وَاذْكُرُٓوا اِذْ كُنْتُمْ قَل۪يلاً فَكَثَّرَكُمْۖ وَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِد۪ينَ', 'Ve la tak\'udu bikulli sıratın tu\'ıdune ve tasuddune an sebilillahi men amene bihi ve tebguneha ivecen vezkuru iz kuntum kalilen fe kesserekum vanzuru keyfe kane akıbetul mufsidin.', '\"İman edenleri tehdit ederek Allah\'ın yolundan çevirmek ve o yolu eğri göstermeye çalışmak için her yolun başına oturmayın.[1] Azken sizi nasıl çoğalttığımızı bir düşünün. Bakın! Bozgunculuk yapanların sonu nasıl oldu!\"', 'ولا تقعدوا بكل صرط توعدون وتصدون عن سبيل الله من امن به وتبغونها عوجا واذكروا اذ كنتم قليلا فكثركم وانظروا كيف كان عقبة المفسدين'),
(1041, 7, 87, 'وَاِنْ كَانَ طَٓائِفَةٌ مِنْكُمْ اٰمَنُوا بِالَّـذ۪ٓي اُرْسِلْتُ بِه۪ وَطَٓائِفَةٌ لَمْ يُؤْمِنُوا فَاصْبِرُوا حَتّٰى يَحْكُمَ اللّٰهُ بَيْنَنَاۚ وَهُوَ خَيْرُ الْحَاكِم۪ينَ', 'Ve in kane taifetun minkum amenu billezi ursiltu bihi ve taifetun lem yu\'minu fasbiru hatta yahkumallahu beynena, ve huve hayrul hakimin.', 'Mademki sizin bir kısmınız benimle gönderilene iman etmiş,  bir kısmınız da iman etmemişse; o halde Allah aramızda hükmünü verinceye kadar sabredin. O,  hüküm verenlerin en hayırlısıdır.', 'وان كان طايفة منكم امنوا بالذي ارسلت به وطايفة لم يومنوا فاصبروا حتي يحكم الله بيننا وهو خير الحكمين'),
(1042, 7, 88, 'قَالَ الْمَلَأُ الَّذ۪ينَ اسْتَكْبَرُوا مِنْ قَوْمِه۪ لَنُخْرِجَنَّكَ يَا شُعَيْبُ وَالَّذ۪ينَ اٰمَنُوا مَعَكَ مِنْ قَرْيَتِنَٓا اَوْ لَتَعُودُنَّ ف۪ي مِلَّتِنَاۜ قَالَ اَوَلَوْ كُنَّا كَارِه۪ينَ', 'Kalel meleullezinestekberu min kavmihi le nuhricenneke ya şuaybu vellezine amenu meake min karyetina ev le teudunne fi milletina, kale e ve lev kunna karihin.', 'Halkının büyüklük taslayan meleleri[1] dediler ki: \"Ey Şu\'ayb! Seni ve seninle birlikte iman edenleri ya yurdumuzdan çıkaracağız ya da bizim milletimize[2] döneceksiniz.\" O da: \"Kerih[3] görsek de mi?\" dedi.', 'قال الملا الذين استكبروا من قومه لنخرجنك يشعيب والذين امنوا معك من قريتنا او لتعودن في ملتنا قال اولو كنا كرهين'),
(1043, 7, 89, 'قَدِ افْتَرَيْنَا عَلَى اللّٰهِ كَذِباً اِنْ عُدْنَا ف۪ي مِلَّتِكُمْ بَعْدَ اِذْ نَجّٰينَا اللّٰهُ مِنْهَاۜ وَمَا يَكُونُ لَـنَٓا اَنْ نَعُودَ ف۪يهَٓا اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُ رَبُّنَاۜ وَسِعَ رَبُّنَا كُلَّ شَيْءٍ عِلْماًۜ عَلَى اللّٰهِ تَوَكَّلْنَاۜ رَبَّـنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَاَنْتَ خَيْرُ الْفَاتِح۪ينَ', 'Kadiftereyna alallahi keziben in udna fi milletikum ba\'de iz necceynallahu minha, ve ma yekunu lena en neude fiha illa en yeşaallahu rabbuna, vesia rabbuna kulle şey\'in ilmen, alallahi tevekkelna, rabbeneftah beynena ve beyne kavmina bil hakkı ve ente hayrul fatihin.', '\"O,  bizi ondan kurtardıktan sonra,  eğer tekrar sizin milletinize dönersek,  Allah\'a karşı yalan yere iftira etmiş oluruz. Rabb\'imiz Allah dilemedikçe[1] bizim ona dönmemiz olacak şey değildir. Rabb\'imizin bilgisi her şeyi kuşatmıştır. Biz,  yalnızca Allah\'a tevekkül[3] ettik. Ey Rabb\'imiz! Bizimle halkımız arasında gerçeği ortaya çıkar. Sen,  gerçeği ortaya çıkaranların en hayırlısısın.\"', 'قد افترينا علي الله كذبا ان عدنا في ملتكم بعد اذ نجينا الله منها وما يكون لنا ان نعود فيها الا ان يشا الله ربنا وسع ربنا كل شي علما علي الله توكلنا ربنا افتح بيننا وبين قومنا بالحق وانت خير الفتحين'),
(1044, 7, 90, 'وَقَالَ الْمَلَأُ الَّذ۪ينَ كَفَرُوا مِنْ قَوْمِه۪ لَئِنِ اتَّبَعْتُمْ شُعَيْباً اِنَّكُمْ اِذاً لَخَاسِرُونَ', 'Ve kalel meleullezine keferu min kavmihi le initteba\'tum şuayben innekum izen le hasirun.', 'Halkından Kafir[1] meleler:[2] \"Eğer Şu\'ayb\'e uyarsanız kaybedenlerden olursunuz.\" dediler.', 'وقال الملا الذين كفروا من قومه لين اتبعتم شعيبا انكم اذا لخسرون'),
(1045, 7, 91, 'فَاَخَذَتْهُمُ الرَّجْفَةُ فَاَصْبَحُوا ف۪ي دَارِهِمْ جَاثِم۪ينَۚۛ', 'Fe ehazethumur recfetu fe asbehu fi darihim casimin.', 'Derken şiddetli bir sarsıntı onları yakaladı ve yurtlarında dizüstü çöke kaldılar.', 'فاخذتهم الرجفة فاصبحوا في دارهم جثمين'),
(1046, 7, 92, 'اَلَّذ۪ينَ كَذَّبُوا شُعَيْباً كَاَنْ لَمْ يَغْنَوْا ف۪يهَاۚۛ اَلَّذ۪ينَ كَذَّبُوا شُعَيْباً كَانُوا هُمُ الْخَاسِر۪ينَ', 'Ellezine kezzebu şuayben ke en lem yagnev fiha, ellezine kezzebu şuayben kanu humul hasirin.', 'Şu\'ayb\'ı yalanlayanlar,  sanki orada hiç yaşamamışlar gibi yok oldular. Asıl kaybedenler Şu\'ayb\'ı yalanlayanlar oldu.', 'الذين كذبوا شعيبا كان لم يغنوا فيها الذين كذبوا شعيبا كانوا هم الخسرين'),
(1047, 7, 93, 'فَتَوَلّٰى عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ اَبْلَغْتُكُمْ رِسَالَاتِ رَبّ۪ي وَنَصَحْتُ لَكُمْۚ فَكَيْفَ اٰسٰى عَلٰى قَوْمٍ كَافِر۪ينَ۟', 'Fe tevella anhum ve kale ya kavmi lekad eblagtukum risalati rabbi ve nesahtu lekum, fe keyfe asa ala kavmin kafirin.', 'Onlardan yüz çevirdi ve \"Ey halkım.\" dedi: \"Ben,  size Rabb\'imin mesajını tebliğ ettim ve size öğüt verdim. Artık Kafir bir topluma nasıl olur da üzülebilirim?\"', 'فتولي عنهم وقال يقوم لقد ابلغتكم رسلت ربي ونصحت لكم فكيف اسي علي قوم كفرين'),
(1048, 7, 94, 'وَمَٓا اَرْسَلْنَا ف۪ي قَرْيَةٍ مِنْ نَبِيٍّ اِلَّٓا اَخَذْنَٓا اَهْلَهَا بِالْبَأْسَٓاءِ وَالضَّرَّٓاءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 'Ve ma erselna fi karyetin min nebiyyin illa ehazna ehleha bil be\'sai ved darrai leallehum yaddarraun.', 'Hangi beldeye bir nebi gönderdiysek,  o beldenin halkını tezarru[1] etsin diye sıkıntı ve zorlukla yakaladık.', 'وما ارسلنا في قرية من نبي الا اخذنا اهلها بالباسا والضرا لعلهم يضرعون'),
(1049, 7, 95, 'ثُمَّ بَدَّلْنَا مَكَانَ السَّيِّئَةِ الْحَسَنَةَ حَتّٰى عَفَوْا وَقَالُوا قَدْ مَسَّ اٰبَٓاءَنَا الضَّرَّٓاءُ وَالسَّرَّٓاءُ فَاَخَذْنَاهُمْ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'Summe beddelna mekanes seyyietil hasenete hatta afev ve kalu kad messe abaenad darrau ves serrau fe ehaznahum bagteten ve hum la yeş\'urun.', 'Sonra kötülüğü iyiliğe çevirdik. Nihayet imkanları artınca: \"Atalarımızın da sıkıntılı ve bolluk günleri olmuştu.\" dediler. Bu yüzden,  Biz de onları ansızın yakalayıverdik.', 'ثم بدلنا مكان السيية الحسنة حتي عفوا وقالوا قد مس ابانا الضرا والسرا فاخذنهم بغتة وهم لا يشعرون'),
(1050, 7, 96, 'وَلَوْ اَنَّ اَهْلَ الْقُرٰٓى اٰمَنُوا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِمْ بَرَكَاتٍ مِنَ السَّمَٓاءِ وَالْاَرْضِ وَلٰكِنْ كَذَّبُوا فَاَخَذْنَاهُمْ بِمَا كَانُوا يَكْسِبُونَ', 'Ve lev enne ehlel kura amenu vettekav le fetahna aleyhim berekatin mines semai vel ardı ve lakin kezzebu fe ehaznahum bima kanu yeksibun.', 'Eğer beldelerin halkı iman edip,  takva sahibi olsalardı,  muhakkak üzerlerine göğün ve yerin bereketini açardık. Ancak onlar yalanladılar,  Biz de yaptıklarına karşılık onları kıskıvrak yakaladık.', 'ولو ان اهل القري امنوا واتقوا لفتحنا عليهم بركت من السما والارض ولكن كذبوا فاخذنهم بما كانوا يكسبون'),
(1051, 7, 97, 'اَفَاَمِنَ اَهْلُ الْقُرٰٓى اَنْ يَأْتِيَهُمْ بَأْسُنَا بَيَاتاً وَهُمْ نَٓائِمُونَۜ', 'E fe emine ehlul kura en ye\'tiyehum be\'suna beyaten ve hum naimun.', 'O beldelerin halkı,  geceleyin uyurlarken kendilerine azabımızın gelmeyeceğinden emin mi oldular?', 'افامن اهل القري ان ياتيهم باسنا بيتا وهم نايمون'),
(1052, 7, 98, 'اَوَاَمِنَ اَهْلُ الْقُرٰٓى اَنْ يَأْتِيَهُمْ بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', 'E ve emine ehlul kura en ye\'tiyehum be\'suna duhan ve hum yel\'abun .', 'Ya da o beldelerin halkı,  gündüzün serin vaktinde dünya işleriyle oyalanırlarken azabımızın onlara gelmeyeceğinden emin mi oldular?', 'اوامن اهل القري ان ياتيهم باسنا ضحي وهم يلعبون'),
(1053, 7, 99, 'اَفَاَمِنُوا مَكْرَ اللّٰهِۚ فَلَا يَأْمَنُ مَكْرَ اللّٰهِ اِلَّا الْقَوْمُ الْخَاسِرُونَ۟', 'E fe eminu mekrallahi, fe la ye\'menu mekrallahi illel kavmul hasirun.', 'Allah\'ın planından emin mi oldular? Kaybedenlerden başkası Allah\'ın planından emin olamaz.', 'افامنوا مكر الله فلا يامن مكر الله الا القوم الخسرون'),
(1054, 7, 100, 'اَوَلَمْ يَهْدِ لِلَّذ۪ينَ يَرِثُونَ الْاَرْضَ مِنْ بَعْدِ اَهْلِهَٓا اَنْ لَوْ نَشَٓاءُ اَصَبْنَاهُمْ بِذُنُوبِهِمْۚ وَنَطْبَعُ عَلٰى قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', 'E ve lem yehdi lillezine yerisunel arda min ba\'di ehliha en lev neşau esabnahum bi zunubihim, ve natbeu ala kulubihim fe hum la yesme\'un.', 'Önceki halklardan sonra yeryüzüne mirasçı olanların,  doğru yolu bulmaları gerekmez miydi? Eğer biz dileseydik onları da suçlarından dolayı cezalandırırdık. Kalplerini mühürlerdik de duymaz olurlardı.', 'اولم يهد للذين يرثون الارض من بعد اهلها ان لو نشا اصبنهم بذنوبهم ونطبع علي قلوبهم فهم لا يسمعون'),
(1055, 7, 101, 'تِلْكَ الْقُرٰى نَقُصُّ عَلَيْكَ مِنْ اَنْـبَٓائِهَاۚ وَلَقَدْ جَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِۚ فَمَا كَانُوا لِيُؤْمِنُوا بِمَا كَذَّبُوا مِنْ قَبْلُۜ كَذٰلِكَ يَطْبَعُ اللّٰهُ عَلٰى قُلُوبِ الْكَافِر۪ينَ', 'Tilkel kura nakussu aleyke min enbaiha ve lekad caethum rusuluhum bil beyyinati fe ma kanu liyu\'minu bi ma kezzebu min kablu kezalike yatbaullahu ala kulubil kafirin .', 'İşte o beldeler ki sana bazı haberlerini anlatıyoruz. Resulleri onlara beyyinat[1] getirmişlerdi. Ancak onlar,  daha önce yalanlamış oldukları şeye inanmak istemediler. Allah Kafirlerin[2] kalplerini işte böyle mühürler.[3]', 'تلك القري نقص عليك من انبايها ولقد جاتهم رسلهم بالبينت فما كانوا ليومنوا بما كذبوا من قبل كذلك يطبع الله علي قلوب الكفرين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1056, 7, 102, 'وَمَا وَجَدْنَا لِاَكْثَرِهِمْ مِنْ عَهْدٍۚ وَاِنْ وَجَدْنَٓا اَكْثَرَهُمْ لَفَاسِق۪ينَ', 'Ve ma vecedna li ekserihim min ahdin, ve in vecedna ekserehum le fasikin.', 'Onların çoğunda,  sözlerine bağlılık bulmadık. Ama onların çoğunu fasık[1] olarak bulduk.', 'وما وجدنا لاكثرهم من عهد وان وجدنا اكثرهم لفسقين'),
(1057, 7, 103, 'ثُمَّ بَعَثْنَا مِنْ بَعْدِهِمْ مُوسٰى بِاٰيَاتِنَٓا اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ فَظَلَمُوا بِهَاۚ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِد۪ينَ', 'Summe beasna min ba\'dihim musa bi ayatina ila fir\'avne ve melaihi fe zalemu biha, fanzur keyfe kane akıbetul mufsidin.', 'Sonra onların ardından Musa\'yı ayetlerimizle Firavun\'a ve onun melelerine gönderdik. Onlar,  ona zulmettiler. Bak bozguncuların sonu nasıl oldu!', 'ثم بعثنا من بعدهم موسي بايتنا الي فرعون وملايه فظلموا بها فانظر كيف كان عقبة المفسدين'),
(1058, 7, 104, 'وَقَالَ مُوسٰى يَا فِرْعَوْنُ اِنّ۪ي رَسُولٌ مِنْ رَبِّ الْعَالَم۪ينَۚ', 'Ve kale musa ya fir\'avnu inni resulun min rabbil alemin.', 'Musa dedi ki: \"Ey Firavun! Ben gerçekten alemlerin Rabb\'i tarafından gönderilmiş bir resulüm.\"', 'وقال موسي يفرعون اني رسول من رب العلمين'),
(1059, 7, 105, 'حَق۪يقٌ عَلٰٓى اَنْ لَٓا اَقُولَ عَلَى اللّٰهِ اِلَّا الْحَقَّۜ قَدْ جِئْتُكُمْ بِبَيِّنَةٍ مِنْ رَبِّكُمْ فَاَرْسِلْ مَعِيَ بَن۪ٓي اِسْرَٓائ۪لَۜ', 'Hakikun ala en la ekule alallahi illel hakk, kad ci\'tukum bi beyyinetin min rabbikum fe ersil maiye beni israil.', '\"Allah adına,  hakikatten başkasını söylememek benim üzerime borçtur. Size,  Rabb\'inizden açık beyyinelerle[1] geldim. Öyleyse İsrailoğulları\'nı benimle gönder.\"', 'حقيق علي ان لا اقول علي الله الا الحق قد جيتكم ببينة من ربكم فارسل معي بني اسريل'),
(1060, 7, 106, 'قَالَ اِنْ كُنْتَ جِئْتَ بِاٰيَةٍ فَأْتِ بِهَٓا اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Kale in kunte ci\'te bi ayetin fe\'ti biha in kunte mines sadikin.', 'Firavun: \"Eğer gerçekten bir ayet[1] getirdiysen ve doğru söyleyenlerdensen onu göster bakalım.\" dedi.', 'قال ان كنت جيت باية فات بها ان كنت من الصدقين'),
(1061, 7, 107, 'فَاَلْقٰى عَصَاهُ فَاِذَا هِيَ ثُعْبَانٌ مُب۪ينٌۚ', 'Fe elka asahu fe iza hiye su\'banun mubin.', 'Bunun üzerine,  Musa asasını yere bıraktı,  asa sahici büyük bir yılan[1] oldu.', 'فالقي عصاه فاذا هي ثعبان مبين'),
(1062, 7, 108, 'وَنَزَعَ يَدَهُ فَاِذَا هِيَ بَيْضَٓاءُ لِلنَّاظِر۪ينَ۟', 'Ve neze\'a yedehu fe iza hiye beydau lin nazırin.', 'Ve elini çıkardığı zaman,  eli bakanlar için bembeyaz parlayıverdi.', 'ونزع يده فاذا هي بيضا للنظرين'),
(1063, 7, 109, 'قَالَ الْمَلَأُ مِنْ قَوْمِ فِرْعَوْنَ اِنَّ هٰذَا لَسَاحِرٌ عَل۪يمٌۙ', 'Kalel meleu min kavmi fir\'avne inne haza le sahırun alim.', 'Firavun halkının meleleri: \"Bu gerçekten bilgin bir büyücüdür.\" dediler.', 'قال الملا من قوم فرعون ان هذا لسحر عليم'),
(1064, 7, 110, 'يُر۪يدُ اَنْ يُخْرِجَكُمْ مِنْ اَرْضِكُمْۚ فَمَاذَا تَأْمُرُونَ', 'Yuridu en yuhricekum min ardıkum, fe maza te\'murun.', '\"Sizi yurdunuzdan çıkarmak istiyor. Ne buyuruyorsunuz?\"', 'يريد ان يخرجكم من ارضكم فماذا تامرون'),
(1065, 7, 111, 'قَالُٓوا اَرْجِهْ وَاَخَاهُ وَاَرْسِلْ فِي الْمَدَٓائِنِ حَاشِر۪ينَۙ', 'Kalu ercih ve ehahu ve ersil fil medaini haşirin.', '\"Onu ve kardeşini alıkoy. Şehirlere de toplayıcılar gönder.\" dediler.', 'قالوا ارجه واخاه وارسل في المداين حشرين'),
(1066, 7, 112, 'يَأْتُوكَ بِكُلِّ سَاحِرٍ عَل۪يمٍ', 'Ye\'tuke bi kulli sahırin alim.', '\"Bütün bilgin sihirbazları sana getirsinler.\"', 'ياتوك بكل سحر عليم'),
(1067, 7, 113, 'وَجَٓاءَ السَّحَرَةُ فِرْعَوْنَ قَالُٓوا اِنَّ لَنَا لَاَجْراً اِنْ كُنَّا نَحْنُ الْغَالِب۪ينَ', 'Ve caes seharatu fir\'avne kalu inne lena le ecren in kunna nahnul galibin.', 'Sihirbazlar,  Firavun\'a geldiler: \"Eğer galip gelirsek bize bir ödül var değil mi?\" dediler.', 'وجا السحرة فرعون قالوا ان لنا لاجرا ان كنا نحن الغلبين'),
(1068, 7, 114, 'قَالَ نَعَمْ وَاِنَّكُمْ لَمِنَ الْمُقَرَّب۪ينَ', 'Kale ne\'am ve innekum le minel mukarrebin.', 'Evet,  \"Sizler yakınlaştırılanlardan[1] olacaksınız.\" dedi.', 'قال نعم وانكم لمن المقربين'),
(1069, 7, 115, 'قَالُوا يَا مُوسٰٓى اِمَّٓا اَنْ تُلْقِيَ وَاِمَّٓا اَنْ نَكُونَ نَحْنُ الْمُلْق۪ينَ', 'Kalu ya musa imma en tulkiye ve imma en nekune nahnul mulkin.', '\"Ey Musa! Önce sen mi atacaksın,  yoksa atanlar biz mi olalım?\" dediler.', 'قالوا يموسي اما ان تلقي واما ان نكون نحن الملقين'),
(1070, 7, 116, 'قَالَ اَلْقُواۚ فَلَمَّٓا اَلْقَوْا سَحَرُٓوا اَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَٓاؤُ۫ بِسِحْرٍ عَظ۪يمٍ', 'Kale elku fe lemma elkav seharu a\'yunen nasi vesterhebuhum ve cau bi sihrin azim.', '\"Siz atın\" dedi. Attıkları zaman,  büyük bir büyü yaparak insanların gözlerini büyüleyip,  onlara korku verdiler.', 'قال القوا فلما القوا سحروا اعين الناس واسترهبوهم وجاو بسحر عظيم'),
(1071, 7, 117, 'وَاَوْحَيْنَٓا اِلٰى مُوسٰٓى اَنْ اَلْقِ عَصَاكَۚ فَاِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَۚ', 'Ve evhayna ila musa en elkı asake, fe iza hiye telkafu ma ye\'fikun.', 'Biz de Musa\'ya: \"Asanı at.\" diye vahyettik. O,  onların uydurdukları şeyleri yutuverdi.', 'واوحينا الي موسي ان الق عصاك فاذا هي تلقف ما يافكون'),
(1072, 7, 118, 'فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَۚ', 'Fe vakaal hakku ve batale ma kanu ya\'melun.', 'Böylece,  hakikat[1] ortaya çıktı ve onların bütün yaptıkları batıl[2] oldu.', 'فوقع الحق وبطل ما كانوا يعملون'),
(1073, 7, 119, 'فَغُلِبُوا هُنَالِكَ وَانْقَلَبُوا صَاغِر۪ينَۚ', 'Fe gulibu hunalike venkalebu sagırin.', 'Orada yenik düştüler. Küçük düşüp,  iddialarından vazgeçtiler.', 'فغلبوا هنالك وانقلبوا صغرين'),
(1074, 7, 120, 'وَاُلْقِيَ السَّحَرَةُ سَاجِد۪ينَۚ', 'Ve ulkıyes seharatu sacidin.', 'Ve sihirbazlar secdeye kapandılar.', 'والقي السحرة سجدين'),
(1075, 7, 121, 'قَالُٓوا اٰمَنَّا بِرَبِّ الْعَالَم۪ينَۙ', 'Kalu amenna bi rabbil alemin.', '\"Âlemlerin Rabb\'ine iman ettik.\" dediler.', 'قالوا امنا برب العلمين'),
(1076, 7, 122, 'رَبِّ مُوسٰى وَهٰرُونَ', 'Rabbi musa ve harun.', '\"Musa ve Harun\'un Rabbine.\"', 'رب موسي وهرون'),
(1077, 7, 123, 'قَالَ فِرْعَوْنُ اٰمَنْتُمْ بِه۪ قَبْلَ اَنْ اٰذَنَ لَكُمْۚ اِنَّ هٰذَا لَمَكْرٌ مَكَرْتُمُوهُ فِي الْمَد۪ينَةِ لِتُخْرِجُوا مِنْهَٓا اَهْلَهَاۚ فَسَوْفَ تَعْلَمُونَ', 'Kale fir\'avnu amentum bihi kable en azene lekum, inne haza le mekrun mekertumuhu fil medineti li tuhricu minha ehleha, fe sevfe ta\'lemun.', 'Firavun: \"Ben size izin vermeden mi ona inandınız?\" dedi. \"Doğrusu bu,  halkı şehirden çıkarmak için kurduğunuz bir tuzaktır. Ama yakında göreceksiniz!\"', 'قال فرعون امنتم به قبل ان اذن لكم ان هذا لمكر مكرتموه في المدينة لتخرجوا منها اهلها فسوف تعلمون'),
(1078, 7, 124, 'لَاُقَطِّعَنَّ اَيْدِيَكُمْ وَاَرْجُلَكُمْ مِنْ خِلَافٍ ثُمَّ لَاُصَلِّبَنَّكُمْ اَجْمَع۪ينَ', 'Le ukattıanne eydiyekum ve erculekum min hilafin summe le usallibennekum ecmain.', '\"Mutlaka ellerinizi ve ayaklarınızı çaprazlama keseceğim ve sonra da hepinizi asacağım.\"', 'لاقطعن ايديكم وارجلكم من خلف ثم لاصلبنكم اجمعين'),
(1079, 7, 125, 'قَالُٓوا اِنَّٓا اِلٰى رَبِّنَا مُنْقَلِبُونَۚ', 'Kalu inna ila rabbina munkalibun.', '\"Biz zaten Rabb\'imize döneceğiz.\" dediler.', 'قالوا انا الي ربنا منقلبون'),
(1080, 7, 126, 'وَمَا تَنْقِمُ مِنَّٓا اِلَّٓا اَنْ اٰمَنَّا بِاٰيَاتِ رَبِّنَا لَمَّا جَٓاءَتْنَاۜ رَبَّـنَٓا اَفْرِغْ عَلَيْنَا صَبْراً وَتَوَفَّـنَا مُسْلِم۪ينَ۟', 'Ve ma tenkımu minna illa en amenna bi ayati rabbina lemma caetna, rabbena efrıg aleyna sabren ve teveffena muslimin.', '\"Rabb\'imizin bize gelen ayetlerine iman etmemizden dolayı,  bizden intikam almak istiyorsun. Ey Rabbimiz! Bizi sabırlı kıl ve canımızı teslim olanlar olarak al.\"', 'وما تنقم منا الا ان امنا بايت ربنا لما جاتنا ربنا افرغ علينا صبرا وتوفنا مسلمين'),
(1081, 7, 127, 'وَقَالَ الْمَلَأُ مِنْ قَوْمِ فِرْعَوْنَ اَتَذَرُ مُوسٰى وَقَوْمَهُ لِيُفْسِدُوا فِي الْاَرْضِ وَيَذَرَكَ وَاٰلِهَتَكَۜ قَالَ سَنُقَتِّلُ اَبْنَٓاءَهُمْ وَنَسْتَحْـي۪ نِسَٓاءَهُمْۚ وَاِنَّا فَوْقَهُمْ قَاهِرُونَ', 'Ve kalel meleu min kavmi fir\'avne e tezeru musa ve kavmehu li yufsidu fìl ardı ve yezereke ve aliheteke, kale senukattilu ebnaehum ve nestahyi nisaehum ve inna fevkahum kahirun.', 'Firavun halkının meleleri[1]: \"Musa\'yı ve yanında yer alanları,  yeryüzünde bozgunculuk yapsınlar,  seni ve ilahlarını terk etsinler diye mi bırakacaksın?\" dediler. O da: \"Oğullarını öldürüp,  kadınlarını sağ bırakacağız. Kuşkusuz,  biz onların üzerinde kahredicileriz.\" dedi.', 'وقال الملا من قوم فرعون اتذر موسي وقومه ليفسدوا في الارض ويذرك والهتك قال سنقتل ابناهم ونستحي نساهم وانا فوقهم قهرون'),
(1082, 7, 128, 'قَالَ مُوسٰى لِقَوْمِهِ اسْتَع۪ينُوا بِاللّٰهِ وَاصْبِرُواۚ اِنَّ الْاَرْضَ لِلّٰهِۚ يُورِثُهَا مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ۜ وَالْعَاقِبَةُ لِلْمُتَّق۪ينَ', 'Kale musa li kavmihisteinu billahi vasbiru, innel arda lillahi yurisuha men yeşau min ibadih, vel akıbetu lil muttekin.', 'Musa,  halkına: \"Allah\'tan yardım dileyin ve sabredin. Kuşkusuz yeryüzü Allah\'ındır. Dilediği kulunu ona mirasçı kılar. Mutlu son takva sahibi olanlar içindir.\" dedi.', 'قال موسي لقومه استعينوا بالله واصبروا ان الارض لله يورثها من يشا من عباده والعقبة للمتقين'),
(1083, 7, 129, 'قَالُٓوا اُو۫ذ۪ينَا مِنْ قَبْلِ اَنْ تَأْتِيَنَا وَمِنْ بَعْدِ مَا جِئْتَنَاۜ قَالَ عَسٰى رَبُّكُمْ اَنْ يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِي الْاَرْضِ فَيَنْظُرَ كَيْفَ تَعْمَلُونَ۟', 'Kalu uzina min kabli en te\'tiyena ve min ba\'di ma ci\'tena, kale asa rabbukum en yuhlike aduvvekum ve yestahlifekum fil ardı fe yanzure keyfe ta\'melun.', '\"Sen bize gelmeden önce de,  bize geldikten sonra da bize eziyet edildi.\" dediler. O da: \"Umulur ki Rabb\'iniz düşmanlarınızı yok eder ve sizi yeryüzüne halifeler[1] kılar da nasıl davranacağınıza bakar.\" dedi.', 'قالوا اوذينا من قبل ان تاتينا ومن بعد ما جيتنا قال عسي ربكم ان يهلك عدوكم ويستخلفكم في الارض فينظر كيف تعملون'),
(1084, 7, 130, 'وَلَقَدْ اَخَذْنَٓا اٰلَ فِرْعَوْنَ بِالسِّن۪ينَ وَنَقْصٍ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'Ve lekad ehazna ale fir\'avne bis sinine ve naksın mines semerati leallehum yezzekkerun.', 'Ant olsun ki belki ders alırlar diye,  Firavuncuları [1]yıllarca kuraklık ve ürün kıtlığıyla cezalandırdık.', 'ولقد اخذنا ال فرعون بالسنين ونقص من الثمرت لعلهم يذكرون'),
(1085, 7, 131, 'فَاِذَا جَٓاءَتْهُمُ الْحَسَنَةُ قَالُوا لَنَا هٰذِه۪ۚ وَاِنْ تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا بِمُوسٰى وَمَنْ مَعَهُۜ اَلَٓا اِنَّمَا طَٓائِرُهُمْ عِنْدَ اللّٰهِ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Fe iza caethumul hasenetu kalu lena hazih, ve in tusibhum seyyietun yettayyeru bi musa ve men meah, e la innema tairuhum indallahi ve lakinne ekserehum la ya\'lemun.', 'Onlara bir iyilik geldiği zaman,  \"Bu bizdendir.\" derler. Bir kötülük isabet ettiği zaman da Musa ve onunla birlikte olanları uğursuz sayarlardı. İyi bilin ki onların uğursuzluğu ancak Allah katındadır.[1] Ancak çokları bunu bilmez.', 'فاذا جاتهم الحسنة قالوا لنا هذه وان تصبهم سيية يطيروا بموسي ومن معه الا انما طيرهم عند الله ولكن اكثرهم لا يعلمون'),
(1086, 7, 132, 'وَقَالُوا مَهْمَا تَأْتِنَا بِه۪ مِنْ اٰيَةٍ لِتَسْحَرَنَا بِهَاۙ فَمَا نَحْنُ لَكَ بِمُؤْمِن۪ينَ', 'Ve kalu mehma te\'tina bihi min ayetin li tesharena biha fe ma nahnu leke bi mu\'minin.', '\"Bizi büyülemek için ne kadar ayet[1] getirirsen getir,  biz sana asla inanacak değiliz.\" dediler.', 'وقالوا مهما تاتنا به من اية لتسحرنا بها فما نحن لك بمومنين'),
(1087, 7, 133, 'فَاَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ اٰيَاتٍ مُفَصَّلَاتٍ فَاسْتَكْبَرُوا وَكَانُوا قَوْماً مُجْرِم۪ينَ', 'Fe erselna aleyhimut tufane vel cerade vel kummele ved dafadia ved deme ayatin mufassalatin festekberu ve kanu kavmen mucrimin.', 'Bunun üzerine,  Biz de ayrı ayrı ayetler[1] olarak onlara tufan,  çekirge,  haşarat,  kurbağa ve kan gönderdik. Yine de büyüklük taslayıp mücrim[2] bir toplum olmaya devam ettiler.', 'فارسلنا عليهم الطوفان والجراد والقمل والضفادع والدم ايت مفصلت فاستكبروا وكانوا قوما مجرمين'),
(1088, 7, 134, 'وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِنْدَكَۚ لَئِنْ كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَن۪ٓي اِسْرَٓائ۪لَۚ', 'Ve lemma vakaa aleyhimur riczu kalu ya mused\'u lena rabbeke bi ma ahide indek, le in keşefte anner ricze le nu\'minenne leke ve le nursilenne meake beni israil.', 'Başlarına azap gelince: \"Ey Musa! Sana verilen söze dayanarak Rabb\'ine dua et,  eğer bizden bu azabı uzaklaştırırsan sana inanacağız ve İsrailoğulları\'nın seninle birlikte gitmesine izin vereceğiz.\" dediler.', 'ولما وقع عليهم الرجز قالوا يموسي ادع لنا ربك بما عهد عندك لين كشفت عنا الرجز لنومنن لك ولنرسلن معك بني اسريل'),
(1089, 7, 135, 'فَلَمَّا كَشَفْنَا عَنْهُمُ الرِّجْزَ اِلٰٓى اَجَلٍ هُمْ بَالِغُوهُ اِذَا هُمْ يَنْكُثُونَ', 'Fe lemma keşefna anhumur ricze ila ecelin hum baliguhu iza hum yenkusun.', 'Biz onlardan geçirecekleri bir süreye kadar azabı kaldırınca da hemen sözlerinden dönüverdiler.', 'فلما كشفنا عنهم الرجز الي اجل هم بلغوه اذا هم ينكثون'),
(1090, 7, 136, 'فَانْتَقَمْنَا مِنْهُمْ فَاَغْرَقْنَاهُمْ فِي الْيَمِّ بِاَنَّهُمْ كَذَّبُوا بِاٰيَاتِنَا وَكَانُوا عَنْهَا غَافِل۪ينَ', 'Fentekamna minhum fe agraknahum fil yemmi biennehum kezzebu bi ayatina ve kanu anha gafilin.', 'Bu yüzden,  Biz de onlara hak ettikleri cezayı verdik,  onları denizde boğduk. Çünkü onlar ayetlerimizi yalanladılar. Onları umursamaz olmuşlardı.', 'فانتقمنا منهم فاغرقنهم في اليم بانهم كذبوا بايتنا وكانوا عنها غفلين'),
(1091, 7, 137, 'وَاَوْرَثْنَا الْقَوْمَ الَّذ۪ينَ كَانُوا يُسْتَضْعَفُونَ مَشَارِقَ الْاَرْضِ وَمَغَارِبَهَا الَّت۪ي بَارَكْنَا ف۪يهَاۜ وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنٰى عَلٰى بَن۪ٓي اِسْرَٓائ۪لَ بِمَا صَبَرُواۜ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُ وَمَا كَانُوا يَعْرِشُونَ', 'Ve evresnel kavmellezine kanu yustad\'afune meşarikal ardı ve megaribehelleti barekna fiha, ve temmet kelimetu rabbikel husna ala beni israile bi ma saberu, ve demmerna ma kane yasnau fir\'avnu ve kavmuhu ve ma kanu ya\'rişun.', 'Mus\'tezaf[1] olan halkı da bereketlendirdiğimiz arzın doğusuna ve batısına mirasçı kıldık. Sabretmelerine karşılık Rabb\'inin İsrailoğulları\'na takdir ettiği hüküm gerçekleşti. Firavun ve halkının yapıp yükselttikleri yapıları harap ettik.', 'واورثنا القوم الذين كانوا يستضعفون مشرق الارض ومغربها التي بركنا فيها وتمت كلمت ربك الحسني علي بني اسريل بما صبروا ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون'),
(1092, 7, 138, 'وَجَاوَزْنَا بِبَن۪ٓي اِسْرَٓائ۪لَ الْبَحْرَ فَاَتَوْا عَلٰى قَوْمٍ يَعْكُفُونَ عَلٰٓى اَصْنَامٍ لَهُمْۚ قَالُوا يَا مُوسَى اجْعَلْ لَـنَٓا اِلٰهاً كَمَا لَهُمْ اٰلِهَةٌۜ قَالَ اِنَّكُمْ قَوْمٌ تَجْهَلُونَ', 'Ve cavezna bi beni israilel bahre fe etev ala kavmin ya\'kufune ala asnamin lehum, kalu ya musac\'al lena ilahen ke ma lehum alihetun, kale innekum kavmun techelun.', 'İsrailoğulları\'nı denizden geçirdik. Kendilerine özgü putlara tapan bir halka rastladılar. Ey Musa! \"Bize de bunların ilahları gibi bir ilah yap.\" dediler. \"Siz gerçekten cahil bir kavimsiniz.\" dedi.', 'وجوزنا ببني اسريل البحر فاتوا علي قوم يعكفون علي اصنام لهم قالوا يموسي اجعل لنا الها كما لهم الهة قال انكم قوم تجهلون'),
(1093, 7, 139, 'اِنَّ هٰٓؤُ۬لَٓاءِ مُتَبَّرٌ مَا هُمْ ف۪يهِ وَبَاطِلٌ مَا كَانُوا يَعْمَلُونَ', 'İnne haulai mutebberun ma hum fihi ve batılun ma kanu ya\'melun.', '\"Bunların içinde bulundukları[1] yok olacaktır ve yaptıkları şey[2] de batıldır.\"', 'ان هولا متبر ما هم فيه وبطل ما كانوا يعملون'),
(1094, 7, 140, 'قَالَ اَغَيْرَ اللّٰهِ اَبْغ۪يكُمْ اِلٰهاً وَهُوَ فَضَّلَكُمْ عَلَى الْعَالَم۪ينَ', 'Kale e gayrallahi ebgikum ilahen ve huve faddalekum alel alemin.', '\"Sizi alemlere üstün[1] kıldığı halde,  size Allah\'tan başka bir ilah mı arayayım?\" dedi.', 'قال اغير الله ابغيكم الها وهو فضلكم علي العلمين'),
(1095, 7, 141, 'وَاِذْ اَنْجَيْنَاكُمْ مِنْ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُٓوءَ الْعَذَابِۚ يُقَتِّلُونَ اَبْنَٓاءَكُمْ وَيَسْتَحْيُونَ نِسَٓاءَكُمْۜ وَف۪ي ذٰلِكُمْ بَلَٓاءٌ مِنْ رَبِّكُمْ عَظ۪يمٌ۟', 'Ve iz enceynakum min ali fir\'avne yesumunekum suel azab, yukattilune ebnaekum ve yestahyune nisaekum ve fi zalikum belaun min rabbikum azim.', '\"Hani Biz,  size azapların en kötüsünü yapan; oğullarınızı öldürüp,  kadınlarınızı sağ bırakan Firavun toplumundan sizi kurtarmıştık. Bunda,  sizin için Rabb\'inizden büyük bir sınav vardı.\"', 'واذ انجينكم من ال فرعون يسومونكم سو العذاب يقتلون ابناكم ويستحيون نساكم وفي ذلكم بلا من ربكم عظيم'),
(1096, 7, 142, 'وَوٰعَدْنَا مُوسٰى ثَلٰث۪ينَ لَيْلَةً وَاَتْمَمْنَاهَا بِعَشْرٍ فَتَمَّ م۪يقَاتُ رَبِّه۪ٓ اَرْبَع۪ينَ لَيْلَةًۚ وَقَالَ مُوسٰى لِاَخ۪يهِ هٰرُونَ اخْلُفْن۪ي ف۪ي قَوْم۪ي وَاَصْلِحْ وَلَا تَتَّبِـعْ سَب۪يلَ الْمُفْسِد۪ينَ', 'Ve vaadna musa selasine leyleten ve etmemnaha bi aşrin fe temme mikatu rabbihi erbaine leyleh, ve kale musa li ahihi harunahlufni fi kavmi ve aslıh ve la tettebi\' sebilel mufsidin.', 'Musa\'ya,  otuz gece süre verdik,  sonra buna on gece daha ekledik. Böylece Rabb\'inin belirlediği vakit kırk geceye tamamlandı. Musa,  kardeşi Harun\'a,  \"Benim halkım içinde benim yerime geç,  onları ıslah et ve bozguncuların yoluna uyma!\" dedi.', 'ووعدنا موسي ثلثين ليلة واتممنها بعشر فتم ميقت ربه اربعين ليلة وقال موسي لاخيه هرون اخلفني في قومي واصلح ولا تتبع سبيل المفسدين'),
(1097, 7, 143, 'وَلَمَّا جَٓاءَ مُوسٰى لِم۪يقَاتِنَا وَكَلَّمَهُ رَبُّهُۙ قَالَ رَبِّ اَرِن۪ٓي اَنْظُرْ اِلَيْكَۜ قَالَ لَنْ تَرٰين۪ي وَلٰكِنِ انْظُرْ اِلَى الْجَبَلِ فَاِنِ اسْتَقَرَّ مَكَانَهُ فَسَوْفَ تَرٰين۪يۚ فَلَمَّا تَجَلّٰى رَبُّهُ لِلْجَبَلِ جَعَلَهُ دَكاًّ وَخَرَّ مُوسٰى صَعِقاًۚ فَلَمَّٓا اَفَاقَ قَالَ سُبْحَانَكَ تُبْتُ اِلَيْكَ وَاَنَا۬ اَوَّلُ الْمُؤْمِن۪ينَ', 'Ve lemma cae musa li mikatina ve kellemehu rabbuhu kale rabbi erini enzur ileyk, kale len terani ve lakininzur ilel cebeli fe inistekarre mekanehu fe sevfe terani fe lemma tecella rabbuhu lil cebeli cealehu dekkan ve harra musa saıkan, fe lemma efaka kale subhaneke tubtu ileyke ve ene evvelul mu\'minin.', 'Ve Musa,  belirlediğimiz yere gelip de Rabb\'i onunla konuşunca: \"Bana görün de Sana bakayım!\"[1] dedi. \"Sen Beni göremezsin,  fakat şu dağa bak,  eğer o yerinde durursa sen de Beni göreceksin.\" buyurdu. Rabb\'i dağa tecelli edince onu darmadağın etti ve Musa baygın düştü. Kendine gelince: \"Sen münezzehsin.[2] Tevbe ettim Sana. Ben Mü\'minlerin[3] ilkiyim.\" dedi.', 'ولما جا موسي لميقتنا وكلمه ربه قال رب ارني انظر اليك قال لن تريني ولكن انظر الي الجبل فان استقر مكانه فسوف تريني فلما تجلي ربه للجبل جعله دكا وخر موسي صعقا فلما افاق قال سبحنك تبت اليك وانا اول المومنين'),
(1098, 7, 144, 'قَالَ يَا مُوسٰٓى اِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسَالَات۪ي وَبِكَلَام۪يۘ فَخُذْ مَٓا اٰتَيْتُكَ وَكُنْ مِنَ الشَّاكِر۪ينَ', 'Kale ya musa innistafeytuke alen nasi bi risalati ve bi kelami fe huz ma ateytuke ve kun mineş şakirin.', '\"Ey Musa! Gönderdiklerimle ve Kelamımla seni insanlar arasında üstün kıldım[1]. Sana verdiğimi al ve şükredenlerden ol!\" dedi.', 'قال يموسي اني اصطفيتك علي الناس برسلتي وبكلمي فخذ ما اتيتك وكن من الشكرين'),
(1099, 7, 145, 'وَكَتَبْنَا لَهُ فِي الْاَلْوَاحِ مِنْ كُلِّ شَيْءٍ مَوْعِظَةً وَتَفْص۪يلاً لِكُلِّ شَيْءٍۚ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِاَحْسَنِهَاۜ سَاُر۪يكُمْ دَارَ الْفَاسِق۪ينَ', 'Ve ketebna lehu fil elvahı min kulli şey\'in mev\'ızaten ve tafsilen li kulli şey\'in fe huzha bi kuvvetin ve\'mur kavmeke ye\'huzu bi ahseniha seurikum darel fasikin.', 'Ona verdiğimiz levhalarda öğüt olmak üzere her şeyi açık bir şekilde yazdık. \"Onu kuvvetle tut ve halkına da onu en iyi şekilde tutmalarını buyur. Yakında size fasıkların[1] yurdunu göstereceğim.\"', 'وكتبنا له في الالواح من كل شي موعظة وتفصيلا لكل شي فخذها بقوة وامر قومك ياخذوا باحسنها ساوريكم دار الفسقين'),
(1100, 7, 146, 'سَاَصْرِفُ عَنْ اٰيَاتِيَ الَّذ۪ينَ يَتَكَبَّرُونَ فِي الْاَرْضِ بِغَيْرِ الْحَقِّۜ وَاِنْ يَرَوْا كُلَّ اٰيَةٍ لَا يُؤْمِنُوا بِهَاۚ وَاِنْ يَرَوْا سَب۪يلَ الرُّشْدِ لَا يَتَّخِذُوهُ سَب۪يلاًۚ وَاِنْ يَرَوْا سَب۪يلَ الْغَيِّ يَتَّخِذُوهُ سَب۪يلاًۜ ذٰلِكَ بِاَنَّهُمْ كَذَّبُوا بِاٰيَاتِنَا وَكَانُوا عَنْهَا غَافِل۪ينَ', 'Seasrifu an ayatiyellezine yetekebberune fil ardı bi gayril hakkı ve in yerev kulle ayetin la yu\'minu biha ve in yerev sebiler ruşdi la yettehızuhu sebilen ve in yerev sebilel gayyi yettehızuhu sebil, zalike bi ennehum kezzebu bi ayatina ve kanu anha gafilin.', 'Yeryüzünde,  haksız yere büyüklük taslayanları,  ayetlerimden[1] uzaklaştıracağım. Onlar,  bütün ayetleri[2] görseler de yine ona inanmazlar. Rüşd[3] yolunu görseler de onu yol tutmazlar; ama azgınlık[4] yolunu görseler onu kendilerine yol tutarlar. Bu,  ayetlerimizi yalanlamalarından ve ondan gafil[5] bulunmalarındandır.', 'ساصرف عن ايتي الذين يتكبرون في الارض بغير الحق وان يروا كل اية لا يومنوا بها وان يروا سبيل الرشد لا يتخذوه سبيلا وان يروا سبيل الغي يتخذوه سبيلا ذلك بانهم كذبوا بايتنا وكانوا عنها غفلين'),
(1101, 7, 147, 'وَالَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَلِقَٓاءِ الْاٰخِرَةِ حَبِطَتْ اَعْمَالُهُمْۜ هَلْ يُجْزَوْنَ اِلَّا مَا كَانُوا يَعْمَلُونَ۟', 'Vellezine kezzebu bi ayatina ve likail ahireti habitat a\'maluhum, hel yuczevne illa ma kanu ya\'melun.', 'Ayetlerimizi ve ahiretteki karşılaşmayı yalanlayan kimselerin amelleri boşa gitmiştir. Onlar,  başkasıyla değil,  ancak kendi yaptıkları ile cezalandırılacaklardır.', 'والذين كذبوا يتنا ولقا الاخرة حبطت اعملهم هل يجزون الا ما كانوا يعملون'),
(1102, 7, 148, 'وَاتَّخَذَ قَوْمُ مُوسٰى مِنْ بَعْدِه۪ مِنْ حُلِيِّهِمْ عِجْلاً جَسَداً لَهُ خُوَارٌۜ  اَلَمْ يَرَوْا اَنَّهُ لَا يُكَلِّمُهُمْ وَلَا يَهْد۪يهِمْ سَب۪يلاًۢ اِتَّخَذُوهُ وَكَانُوا ظَالِم۪ينَ', 'Vettehaze kavmu musa min ba\'dihi min huliyyihim iclen ceseden lehu huvar, e lem yerev ennehu la yukellimuhum ve la yehdihim sebilen ittehazuhu ve kanu zalimin.', 'Musa\'nın halkı,  onun arkasından,  böğürmesi olan,  süs eşyalarından yapılmış bir buzağı heykelini benimsediler. Onun kendileriyle konuşamadığını ve yol gösteremediğini görmediler mi ki onu benimsediler? Onu benimsemekle zalimlerden oldular.', 'واتخذ قوم موسي من بعده من حليهم عجلا جسدا له خوار الم يروا انه لا يكلمهم ولا يهديهم سبيلا اتخذوه وكانوا ظلمين'),
(1103, 7, 149, 'وَلَمَّا سُقِطَ ف۪ٓي اَيْد۪يهِمْ وَرَاَوْا اَنَّهُمْ قَدْ ضَلُّواۙ قَالُوا لَئِنْ لَمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ الْخَاسِر۪ينَ', 'Ve lemma sukıta fi eydihim ve reev ennehum kad dallu kalu le in lem yerhamna rabbuna ve yağfir lena le nekunenne minel hasirin.', 'Ne zaman ki akılları başlarına gelip gerçekten sapmış olduklarını görünce: \"Eğer Rabb\'imiz bize acımaz ve bizi bağışlamazsa mutlaka hüsrana uğrayanlardan oluruz.\" dediler.', 'ولما سقط في ايديهم وراوا انهم قد ضلوا قالوا لين لم يرحمنا ربنا ويغفر لنا لنكونن من الخسرين'),
(1104, 7, 150, 'وَلَمَّا رَجَعَ مُوسٰٓى اِلٰى قَوْمِه۪ غَضْبَانَ اَسِفاًۙ قَالَ بِئْسَمَا خَلَفْتُمُون۪ي مِنْ بَعْد۪يۚ اَعَجِلْتُمْ اَمْرَ رَبِّكُمْۚ وَاَلْقَى الْاَلْوَاحَ وَاَخَذَ بِرَأْسِ اَخ۪يهِ يَجُرُّهُٓ اِلَيْهِۜ قَالَ ابْنَ اُمَّ اِنَّ الْقَوْمَ اسْتَضْعَفُون۪ي وَكَادُوا يَقْتُلُونَن۪يۘ فَلَا تُشْمِتْ بِيَ الْاَعْدَٓاءَ وَلَا تَجْعَلْن۪ي مَعَ الْقَوْمِ الظَّالِم۪ينَ', 'Ve lemma recea musa ila kavmihi gadbane esifen kale bi\'sema haleftumuni min ba\'di, e aciltum emre rabbikum, ve elkal elvaha ve ehaze bi re\'si ahihi yecurruhu ileyh, kalebne umme innel kavmestad\'afuni ve kadu yaktuluneni fe la tuşmit biyel a\'dae ve la tec\'alni meal kavmiz zalimin.', 'Musa,  halkına döndüğünde,  öfke ve üzüntü içinde onlara: \"Benim yokluğumda ne kötü işler yapmışsınız! Rabb\'inizin emrini[1] çabuklaştırdınız mı?\" dedi. Levhaları bırakıp,  kardeşinin başını tutup kendine çekti. \"Ey annemin oğlu! Gerçekten bu halk beni zayıf buldu,  neredeyse beni öldüreceklerdi; sen de düşmanları benimle sevindirme,  beni bu zalim kimselerle bir tutma.\" dedi.', 'ولما رجع موسي الي قومه غضبن اسفا قال بيسما خلفتموني من بعدي اعجلتم امر ربكم والقي الالواح واخذ براس اخيه يجره اليه قال ابن ام ان القوم استضعفوني وكادوا يقتلونني فلا تشمت بي الاعدا ولا تجعلني مع القوم الظلمين'),
(1105, 7, 151, 'قَالَ رَبِّ اغْفِرْ ل۪ي وَلِاَخ۪ي وَاَدْخِلْنَا ف۪ي رَحْمَتِكَۘ وَاَنْتَ اَرْحَمُ الرَّاحِم۪ينَ۟', 'Kale rabbıgfirli ve li ahi ve edhilna fi rahmetike ve ente erhamur rahımin.', '\"Rabb\'im! Beni ve kardeşimi bağışla! Bizi rahmetine dahil et. Sen merhametlilerin en merhametlisisin.\" dedi.', 'قال رب اغفر لي ولاخي وادخلنا في رحمتك وانت ارحم الرحمين'),
(1106, 7, 152, 'اِنَّ الَّذ۪ينَ اتَّخَذُوا الْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِنْ رَبِّهِمْ وَذِلَّةٌ فِي الْحَيٰوةِ الدُّنْيَاۜ وَكَذٰلِكَ نَجْزِي الْمُفْتَر۪ينَ', 'İnnellezinettehazul ıcle seyenaluhum gadabun min rabbihim ve zilletun fil hayatid dunya, ve kezalike neczil mufterin.', 'Buzağıyı benimseyenlere Rabb\'lerinden bir öfke erişecektir ve dünya hayatında da zillete uğrayacaklardır. İşte iftiracıları böyle cezalandırırız.', 'ان الذين اتخذوا العجل سينالهم غضب من ربهم وذلة في الحيوة الدنيا وكذلك نجزي المفترين'),
(1107, 7, 153, 'وَالَّذ۪ينَ عَمِلُوا السَّيِّـَٔاتِ ثُمَّ تَابُوا مِنْ بَعْدِهَا وَاٰمَنُواۘ اِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَح۪يمٌ', 'Vellezine amilus seyyiati summe tabu min ba\'diha ve amenu inne rabbeke min ba\'diha le gafurun rahim.', 'Kötülük[1] yapıp,  arkasından tevbe edip,  iman edenler için kuşkusuz Rabb\'in bundan sonra Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'والذين عملوا السيات ثم تابوا من بعدها وامنوا ان ربك من بعدها لغفور رحيم'),
(1108, 7, 154, 'وَلَمَّا سَكَتَ عَنْ مُوسَى الْغَضَبُ اَخَذَ الْاَلْوَاحَۚ وَف۪ي نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِلَّذ۪ينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'Ve lemma sekete an musel gadabu ehazel elvah, ve fi nushatiha huden ve rahmetun lillezine hum li rabbihim yerhebun.', 'Öfkesi geçince Musa levhaları aldı,  onlardaki yazıda Rabb\'leri için korkanlara[1] bir yol gösterme ve bir rahmet vardı.', 'ولما سكت عن موسي الغضب اخذ الالواح وفي نسختها هدي ورحمة للذين هم لربهم يرهبون'),
(1109, 7, 155, 'وَاخْتَارَ مُوسٰى قَوْمَهُ سَبْع۪ينَ رَجُلاً لِم۪يقَاتِنَاۚ فَلَمَّٓا اَخَذَتْهُمُ الرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ اَهْلَكْتَهُمْ مِنْ قَبْلُ وَاِيَّايَۜ اَتُهْلِكُنَا بِمَا فَعَلَ السُّفَـهَٓاءُ مِنَّاۚ اِنْ هِيَ اِلَّا فِتْنَتُكَۜ تُضِلُّ بِهَا مَنْ تَشَٓاءُ وَتَهْد۪ي مَنْ تَشَٓاءُۜ  اَنْتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَاَنْتَ خَيْرُ الْغَافِر۪ينَ', 'Vahtara musa kavmehu seb\'ine raculen li mikatina, fe lemma ehazet humur recfetu kale rabbi lev şi\'te ehlektehum min kablu ve iyyaye, e tuhlikuna bi ma feales sufehau minna, in hiye illa fitnetuk, tudıllu biha men teşau ve tehdi men teşau ente veliyyuna fagfirlena verhamna ve ente hayrul gafirin.', 'Musa,  belirlediğimiz buluşma için adamlarından yetmiş kişi seçti. Kendilerini sarsıntı tutunca: \"Ey Rabb\'im! Dileseydin bunları da beni de daha önce yok ederdin. İçimizdeki birtakım beyinsizler yüzünden bizi yok mu edeceksin? Bu,  ancak senin bir fitnendir.[1] Onunla hak edeni[2] sapkınlıkta bırakırsın hak edene[2] de doğru yolu gösterirsin. Sen bizim velimizsin.[3] Bizi bağışla. Bize merhamet et. Sen bağışlayanların en hayırlısısın.\" dedi.', 'واختار موسي قومه سبعين رجلا لميقتنا فلما اخذتهم الرجفة قال رب لو شيت اهلكتهم من قبل وايي اتهلكنا بما فعل السفها منا ان هي الا فتنتك تضل بها من تشا وتهدي من تشا انت ولينا فاغفر لنا وارحمنا وانت خير الغفرين'),
(1110, 7, 156, 'وَاكْتُبْ لَنَا ف۪ي هٰذِهِ الدُّنْيَا حَسَنَةً وَفِي الْاٰخِرَةِ اِنَّا هُدْنَٓا اِلَيْكَۜ قَالَ عَذَاب۪ٓي اُص۪يبُ بِه۪ مَنْ اَشَٓاءُۚ وَرَحْمَت۪ي وَسِعَتْ كُلَّ شَيْءٍۜ فَسَاَكْتُبُهَا لِلَّذ۪ينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكٰوةَ وَالَّذ۪ينَ هُمْ بِاٰيَاتِنَا يُؤْمِنُونَۚ', 'Vektub lena fi hazihid dunya haseneten ve fil ahıreti inna hudna ileyk, kale azabi usibu bihi men eşau ve rahmeti vesiat kulle şey\', fe se ektubuha lillezine yettekune ve yu\'tunez zekate vellezine hum bi ayatina yu\'minun.', 'Bize,  bu dünyada da ahirette de iyilik yaz. Biz Sana yöneldik. Allah: \"Azabıma hak edeni[1] uğratırım,  rahmetim ise her şeyi kuşatmıştır. Onu,  takva[2] sahibi olanlara,  zekatı yapanlara[3] ve ayetlerimize inananlara yazacağım.\" buyurdu.', 'واكتب لنا في هذه الدنيا حسنة وفي الاخرة انا هدنا اليك قال عذابي اصيب به من اشا ورحمتي وسعت كل شي فساكتبها للذين يتقون ويوتون الزكوة والذين هم بايتنا يومنون'),
(1111, 7, 157, 'اَلَّذ۪ينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْاُمِّيَّ الَّذ۪ي يَجِدُونَهُ مَكْتُوباً عِنْدَهُمْ فِي التَّوْرٰيةِ وَالْاِنْج۪يلِۘ يَأْمُرُهُمْ بِالْمَعْرُوفِ وَيَنْهٰيهُمْ عَنِ الْمُنْكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَٓائِثَ وَيَضَعُ عَنْهُمْ اِصْرَهُمْ وَالْاَغْلَالَ الَّت۪ي كَانَتْ عَلَيْهِمْۜ فَالَّذ۪ينَ اٰمَنُوا بِه۪ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّـذ۪ٓي اُنْزِلَ مَعَهُٓۙ اُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ۟', 'Ellezine yettebiuner resulen nebiyyel ummiyyellezi yecidunehu mektuben indehum fit tevrati vel incili ye\'muruhum bil ma\'rufi ve yenhahum anil munkeri ve yuhıllu lehumut tayyibati ve yuharrimu aleyhimul habaise ve yedau anhum ısrahum vel aglalelleti kanet aleyhim, fellezine amenu bihi ve azzeruhu ve nasaruhu vettebeun nurellezi unzile meahu ulaike humul muflihun.', 'Onlar ki,  yanlarındaki Tevrat ve İncil\'de yazılı buldukları ummi[1] nebi resule,  tabi olurlar. O ki,  onlara ma\'ruf olanı yapar ve tavsiye eder ve onları münker olandan alıkoyar[2] ve temiz şeyleri helal,  pis şeyleri haram kılar,  zahmet ve sıkıntı veren şeyleri[3] onlardan kaldırır,  onlardan bağları çözer,  ona iman eden,  ona saygı gösterenler ve ona yardım edenler ve ona indirilen nura[4] tabi olanlar işte kurtuluşa erenler bunlardır.', 'الذين يتبعون الرسول النبي الامي الذي يجدونه مكتوبا عندهم في التورية والانجيل يامرهم بالمعروف وينهيهم عن المنكر ويحل لهم الطيبت ويحرم عليهم الخبيث ويضع عنهم اصرهم والاغلل التي كانت عليهم فالذين امنوا به وعزروه ونصروه واتبعوا النور الذي انزل معه اوليك هم المفلحون'),
(1112, 7, 158, 'قُلْ يَٓا اَيُّهَا النَّاسُ اِنّ۪ي رَسُولُ اللّٰهِ اِلَيْكُمْ جَم۪يعاًۨ الَّذ۪ي لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۚ لَٓا اِلٰهَ اِلَّا هُوَ يُحْـي۪ وَيُم۪يتُۖ فَاٰمِنُوا بِاللّٰهِ وَرَسُولِهِ النَّبِيِّ الْاُمِّيِّ الَّذ۪ي يُؤْمِنُ بِاللّٰهِ وَكَلِمَاتِه۪ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', 'Kul ya eyyuhen nasu inni resulullahi ileykum cemianillezi lehu mulkus semavati vel ard, la ilahe illa huve yuhyi ve yumit, fe aminu billahi ve resulihin nebiyyil ummiyyillezi yu\'minu billahi ve kelimatihi vettebiuhu leallekum tehtedun.', 'De ki: \"Ey insanlar! Ben,  göklerin ve yerin sahibi olan,  kendisinden başka ilah olmayan,  yaşatan ve öldüren Allah\'ın,  size,  hepinize gönderdiği bir resulüm. Gelin,  Allah\'a ve O\'nun sözlerine iman eden ümmi nebi resulüne iman edin ve ona uyun ki böylece doğru yolu bulasınız.\"', 'قل يايها الناس اني رسول الله اليكم جميعا الذي له ملك السموت والارض لا اله الا هو يحي ويميت فامنوا بالله ورسوله النبي الامي الذي يومن بالله وكلمته واتبعوه لعلكم تهتدون'),
(1113, 7, 159, 'وَمِنْ قَوْمِ مُوسٰٓى اُمَّةٌ يَهْدُونَ بِالْحَقِّ وَبِه۪ يَعْدِلُونَ', 'Ve min kavmi musa ummetun yehdune bil hakkı ve bihi ya\'dilun.', 'Musa\'nın halkından da hakka ileten ve onunla adaletli davranan bir topluluk vardı.', 'ومن قوم موسي امة يهدون بالحق وبه يعدلون'),
(1114, 7, 160, 'وَقَطَّعْنَاهُمُ اثْنَتَيْ عَشْرَةَ اَسْبَاطاً اُمَماًۜ وَاَوْحَيْنَٓا اِلٰى مُوسٰٓى اِذِ اسْتَسْقٰيهُ قَوْمُهُٓ اَنِ اضْرِبْ بِعَصَاكَ الْحَجَرَۚ فَانْبَجَسَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْناًۜ قَدْ عَلِمَ كُلُّ اُنَاسٍ مَشْرَبَهُمْۜ وَظَلَّلْنَا عَلَيْهِمُ الْغَمَامَ وَاَنْزَلْنَا عَلَيْهِمُ الْمَنَّ وَالسَّلْوٰىۜ  كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْۜ وَمَا ظَلَمُونَا وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'Ve katta\'nahumusnetey aşrete esbatan umema, ve evhayna ila musa izisteskahu kavmuhu enıdrıb bi asakel hacer, fenbeceset minhusneta aşrete ayna, kad alime kullu unasin meşrebehum, ve zallelna aleyhimul gamame ve enzelna aleyhimul menne ves selva, kulu min tayyibati ma rezaknakum, ve ma zalemuna ve lakin kanu enfusehum yazlimun.', 'Biz,  onları oymaklar halinde on iki topluluğa ayırdık. Halkı ondan su isteyince,  Musa\'ya,  \"Asanı taşa vur!\" diye vahyettik. Ondan on iki pınar fışkırdı. Her topluluk su alacağı kaynağı bildi. Üzerlerine buluttan gölgelik yaptık,  onlara menn[1] ve bıldırcın bağışladık[2]. Size rızık olarak verdiklerimizin temiz olanlarından yiyin. Onlar,  bize zulmetmediler,  fakat kendilerine zulmediyorlardı.', 'وقطعنهم اثنتي عشرة اسباطا امما واوحينا الي موسي اذ استسقيه قومه ان اضرب بعصاك الحجر فانبجست منه اثنتا عشرة عينا قد علم كل اناس مشربهم وظللنا عليهم الغمم وانزلنا عليهم المن والسلوي كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوا انفسهم يظلمون'),
(1115, 7, 161, 'وَاِذْ ق۪يلَ لَهُمُ اسْكُنُوا هٰذِهِ الْقَرْيَةَ وَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا حِطَّةٌ وَادْخُلُوا الْبَابَ سُجَّداً نَغْفِرْ لَكُمْ خَط۪ٓيـَٔاتِكُمْۜ سَنَز۪يدُ الْمُحْسِن۪ينَ', 'Ve iz kile lehumuskunu hazihil karyete ve kulu minha haysu şi\'tum ve kulu hıttatun vedhulul babe succeden nagfir lekum hatiatikum, senezidul muhsinin.', 'Onlara,  \"Şu beldeye yerleşin ve orada dilediğiniz şeylerden yiyin. Af dilediğinizi söyleyin ve teslim olmuş/kabullenmiş olarak kapısından girin\" denilmişti. Biz,  \"Yanlışlarınızı bağışlayalım ve iyilik edenlere fazlasıyla verelim.\"', 'واذ قيل لهم اسكنوا هذه القرية وكلوا منها حيث شيتم وقولوا حطة وادخلوا الباب سجدا نغفر لكم خطيتكم سنزيد المحسنين'),
(1116, 7, 162, 'فَبَدَّلَ الَّذ۪ينَ ظَلَمُوا مِنْهُمْ قَوْلاً غَيْرَ الَّذ۪ي ق۪يلَ لَهُمْ فَاَرْسَلْنَا عَلَيْهِمْ رِجْزاً مِنَ السَّمَٓاءِ بِمَا كَانُوا يَظْلِمُونَ۟', 'Fe beddelellezine zalemu minhum kavlen gayrellezi kile lehum fe erselna aleyhim riczen mines semai bi ma kanu yazlimun.', 'Ancak onlardan haksızlık yapanlar,  kendilerine söylenen sözü başka bir söze çevirdiler. Biz de haksızlık yapmaları yüzünden,  üzerlerine gökten bir azap gönderdik.', 'فبدل الذين ظلموا منهم قولا غير الذي قيل لهم فارسلنا عليهم رجزا من السما بما كانوا يظلمون'),
(1117, 7, 163, 'وَسْـَٔلْهُمْ عَنِ الْقَرْيَةِ الَّت۪ي كَانَتْ حَاضِرَةَ الْبَحْرِۢ اِذْ يَعْدُونَ فِي السَّبْتِ اِذْ تَأْت۪يهِمْ ح۪يتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعاً وَيَوْمَ لَا يَسْبِتُونَۙ لَا تَأْت۪يهِمْۚ كَذٰلِكَ نَبْلُوهُمْ بِمَا كَانُوا يَفْسُقُونَ', 'Ves\'elhum anil karyetilleti kanet hadıratel bahri iz ya\'dune fis sebti iz te\'tihim hitanuhum yevme sebtihim şurre\'an ve yevme la yesbitune la te\'tihim, kezalike nebluhum bi ma kanu yefsukun.', 'Onlara,  deniz kıyısındaki kasabanın durumunu sor. Hani onlar Cumartesi Günü Yasasını çiğneyerek haddi aşıyorlardı. Balıklar cumartesi günü ortaya çıkıyor,  diğer günler ise gelmiyorlardı. Fasıklıkları[1] nedeniyle kendilerini bu şekilde sınıyorduk.', 'وسلهم عن القرية التي كانت حاضرة البحر اذ يعدون في السبت اذ تاتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون لا تاتيهم كذلك نبلوهم بما كانوا يفسقون'),
(1118, 7, 164, 'وَاِذْ قَالَتْ اُمَّةٌ مِنْهُمْ لِمَ تَعِظُونَ قَوْماًۙۨ اللّٰهُ مُهْلِكُهُمْ اَوْ مُعَذِّبُهُمْ عَذَاباً شَد۪يداًۜ قَالُوا مَعْذِرَةً اِلٰى رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', 'Ve iz kalet ummetun minhum lime teizune kavmenillahu muhlikuhum ev muazzibuhum azaben şedida, kalu ma\'zireten ila rabbikum ve leallehum yettekun.', 'Onlardan bir topluluk dedi ki: \"Allah\'ın yok edeceği veya şiddetli bir azap ile cezalandıracağı bir halka ne diye öğüt veriyorsunuz?\" Dediler ki: \"Rabb\'inize mazeret[1] beyan etmek için ve bir de belki takva[2] sahibi olurlar.\"', 'واذ قالت امة منهم لم تعظون قوما الله مهلكهم او معذبهم عذابا شديدا قالوا معذرة الي ربكم ولعلهم يتقون'),
(1119, 7, 165, 'فَلَمَّا نَسُوا مَا ذُكِّرُوا بِه۪ٓ اَنْجَيْنَا الَّذ۪ينَ يَنْهَوْنَ عَنِ السُّٓوءِ وَاَخَذْنَا الَّذ۪ينَ ظَلَمُوا بِعَذَابٍ بَـ۪ٔيسٍ بِمَا كَانُوا يَفْسُقُونَ', 'Fe lemma nesu ma zukkiru bihi enceynellezine yenhevne anis sui ve ahaznellezine zalemu bi azabin beisin bi ma kanu yefsukun.', 'Ne zaman ki onlar,  yapılan öğüdü umursamadılar,  Biz de kötülükten alıkoymaya çalışanları kurtardık,  zulmedenleri,  fasıklık yapmaları nedeniyle çetin bir azapla cezalandırdık.', 'فلما نسوا ما ذكروا به انجينا الذين ينهون عن السو واخذنا الذين ظلموا بعذاب بيس بما كانوا يفسقون'),
(1120, 7, 166, 'فَلَمَّا عَتَوْا عَنْ مَا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِـ۪ٔينَ', 'Fe lemma atev an ma nuhu anhu kulna lehum kunu kıredeten hasiin.', 'Yasaklandıkları şeyleri yapmakta ısrar edince,  onlara: \"Düşkün maymunlar[1] olun.\" dedik.', 'فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قردة خسين'),
(1121, 7, 167, 'وَاِذْ تَاَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ اِلٰى يَوْمِ الْقِيٰمَةِ مَنْ يَسُومُهُمْ سُٓوءَ الْعَذَابِۜ اِنَّ رَبَّكَ لَسَر۪يعُ الْعِقَابِۚ وَاِنَّهُ لَغَفُورٌ رَح۪يمٌ', 'Ve iz teezzene rabbuke le yeb\'asenne aleyhim ila yevmil kıyameti men yesumuhum suel azab, inne rabbeke le seriul ıkabi ve innehu le gafurun rahim.', 'Hani Rabb\'in; onların[1],  üzerine Kıyamet Günü\'ne kadar kötü azaba uğratacak kimseleri mutlaka göndereceğini bildirmişti. Rabb\'in çabuk ceza verendir. Kuşkusuz O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'واذ تاذن ربك ليبعثن عليهم الي يوم القيمة من يسومهم سو العذاب ان ربك لسريع العقاب وانه لغفور رحيم'),
(1122, 7, 168, 'وَقَطَّعْنَاهُمْ فِي الْاَرْضِ اُمَماًۚ مِنْهُمُ الصَّالِحُونَ وَمِنْهُمْ دُونَ ذٰلِكَۘ وَبَلَوْنَاهُمْ بِالْحَسَنَاتِ وَالسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve katta\'nahum fil ardı umema, minhumus salihune ve minhum dune zalike ve belevnahum bil hasenati ves seyyiati leallehum yerciun.', 'Onları,  yeryüzünde topluluklara ayırdık. Onlardan,  salih[1] olanlar da vardı olmayanlar da. Belki dönerler diye onları iyiliklerle ve kötülüklerle sınadık.', 'وقطعنهم في الارض امما منهم الصلحون ومنهم دون ذلك وبلونهم بالحسنت والسيات لعلهم يرجعون'),
(1123, 7, 169, 'فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ وَرِثُوا الْكِتَابَ يَأْخُذُونَ عَرَضَ هٰذَا الْاَدْنٰى وَيَقُولُونَ سَيُغْفَرُ لَنَاۚ وَاِنْ يَأْتِهِمْ عَرَضٌ مِثْلُهُ يَأْخُذُوهُۜ اَلَمْ يُؤْخَذْ عَلَيْهِمْ م۪يثَاقُ الْكِتَابِ اَنْ لَا يَقُولُوا عَلَى اللّٰهِ اِلَّا الْحَقَّ وَدَرَسُوا مَا ف۪يهِۜ وَالدَّارُ الْاٰخِرَةُ خَيْرٌ لِلَّذ۪ينَ يَتَّقُونَۜ اَفَلَا تَعْقِلُونَ', 'Fe halefe min ba\'dihim halfun verisul kitabe ye\'huzune arada hazel edna ve yekulune se yugferu lena ve in ye\'tihim aradun misluhu ye\'huzuh, e lem yu\'haz aleyhim misakul kitabi en la yekulu alallahi illel hakka ve deresu ma fih, ved darul ahıretu hayrun lillezine yettekun, e fe la ta\'kılun.', 'Onların yerine Kitap\'a mirasçı olanlar,  nasıl olsa bağışlanacağız diyerek dünyanın geçici menfaatlerini tercih ettiler; kendilerine buna benzer şeyler gelse,  onu da tercih ederler. Onlardan,  Kitap\'a bağlı kalacaklarına ve Allah hakkında ancak hakkı söyleyeceklerine dair söz alınmamış mıydı? Oysaki onlar,  o Kitap\'ta olanı okumuşlardı. Ahiret yurdu takva sahibi olanlar için daha hayırlıdır. Hala akletmeyecek misiniz?', 'فخلف من بعدهم خلف ورثوا الكتب ياخذون عرض هذا الادني ويقولون سيغفر لنا وان ياتهم عرض مثله ياخذوه الم يوخذ عليهم ميثق الكتب ان لا يقولوا علي الله الا الحق ودرسوا ما فيه والدار الاخرة خير للذين يتقون افلا تعقلون'),
(1124, 7, 170, 'وَالَّذ۪ينَ يُمَسِّكُونَ بِالْكِتَابِ وَاَقَامُوا الصَّلٰوةَۜ اِنَّا لَا نُض۪يعُ اَجْرَ الْمُصْلِح۪ينَ', 'Vellezine yumessikune bil kitabi ve ekamus salate inna la nudiu ecrel muslihin.', 'Kitap\'a sımsıkı sarılıp,  salatı ikame edenlere[1] gelince; kuşkusuz Biz salih olanların emeklerini zayi etmeyiz.', 'والذين يمسكون بالكتب واقاموا الصلوة انا لا نضيع اجر المصلحين'),
(1125, 7, 171, 'وَاِذْ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَاَنَّهُ ظُلَّةٌ وَظَنُّٓوا اَنَّهُ وَاقِعٌ بِهِمْۚ خُذُوا مَٓا اٰتَيْنَاكُمْ بِقُوَّةٍ وَاذْكُرُوا مَا ف۪يهِ لَعَلَّكُمْ تَتَّقُونَ۟', 'Ve iz netaknel cebele fevkahum ke ennehu zulletun ve zannu ennehu vakıun bihim, huzu ma ateynakum bi kuvvetin vezkuru ma fihi leallekum tettekun.', 'Hani! Biz,  dağı gölgelik gibi üzerlerine kaldırmıştık da onlar da üzerlerine düşecek sanmışlardı. \"Size verdiğimize sımsıkı sarılın,  içindeki öğüdü tutun ki takva sahibi olabilesiniz.\"', 'واذ نتقنا الجبل فوقهم كانه ظلة وظنوا انه واقع بهم خذوا ما اتينكم بقوة واذكروا ما فيه لعلكم تتقون'),
(1126, 7, 172, 'وَاِذْ اَخَذَ رَبُّكَ مِنْ بَن۪ٓي اٰدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَاَشْهَدَهُمْ عَلٰٓى اَنْفُسِهِمْۚ اَلَسْتُ بِرَبِّكُمْۜ  قَالُوا بَلٰىۚۛ شَهِدْنَاۚۛ اَنْ تَقُولُوا يَوْمَ الْقِيٰمَةِ اِنَّا كُنَّا عَنْ هٰذَا غَافِل۪ينَۙ', 'Ve iz ehaze rabbuke min beni ademe min zuhurihim zurriyyetehum ve eşhedehum ala enfusihim, e lestu birabbikum, kalu bela, şehidna, en tekulu yevmel kıyameti inna kunna an haza gafilin.', 'Kıyamet günü,  \"Biz bundan habersizdik.\" demeyesiniz diye. Rabb\'in,  ademoğullarının sırtlarından soylarını çıkardı. Ve onları kendilerine tanık yaptı. \"Ben sizin Rabb\'iniz değil miyim?\" dedi. \"Evet,  Rabb\'imizsin,  Tanıklık ediyoruz.[1]\" dediler.', 'واذ اخذ ربك من بني ادم من ظهورهم ذريتهم واشهدهم علي انفسهم الست بربكم قالوا بلي شهدنا ان تقولوا يوم القيمة انا كنا عن هذا غفلين'),
(1127, 7, 173, 'اَوْ تَقُولُٓوا اِنَّـمَٓا اَشْرَكَ اٰبَٓاؤُ۬نَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْۚ اَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ', 'Ev tekulu innema eşreke abauna min kablu ve kunna zurriyyeten min ba\'dihim, e fe tuhlikuna bima fealel mubtilun.', 'Veya \"Biz,  bizden önce şirk koşan atalarımızın ardından gelen bir nesiliz,  batılla amel edenlerin yaptıkları yüzünden bizi mi yok edeceksin?\" demeyesiniz diye.', 'او تقولوا انما اشرك اباونا من قبل وكنا ذرية من بعدهم افتهلكنا بما فعل المبطلون'),
(1128, 7, 174, 'وَكَذٰلِكَ نُفَصِّلُ الْاٰيَاتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'Ve kezalike nufassılul ayati ve leallehum yerci\'un.', 'İşte,  doğruyu bulsunlar diye ayetlerimizi böyle ayrıntılı olarak açıklıyoruz.', 'وكذلك نفصل الايت ولعلهم يرجعون'),
(1129, 7, 175, 'وَاتْلُ عَلَيْهِمْ نَبَاَ الَّـذ۪ٓي اٰتَيْنَاهُ اٰيَاتِنَا فَانْسَلَخَ مِنْهَا فَاَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاو۪ينَ', 'Vetlu aleyhim nebeellezi ateynahu ayatina fenseleha minha fe etbeahuş şeytanu fe kane minel gavin.', 'Onlara,  o kimsenin[1] haberini de oku,  ki ona ayetlerimizi vermiştik de onlardan sıyrılıp ayrıldı. Şeytan da onu kendine tabi kıldı. Böylece azgınlardan oldu.', 'واتل عليهم نبا الذي اتينه ايتنا فانسلخ منها فاتبعه الشيطن فكان من الغاوين'),
(1130, 7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَاهُ بِهَا وَلٰكِنَّهُٓ  اَخْلَدَ اِلَى الْاَرْضِ وَاتَّـبَعَ هَوٰيهُۚ فَمَثَلُهُ  كَمَثَلِ الْكَلْبِۚ اِنْ تَحْمِلْ عَلَيْهِ يَلْهَثْ اَوْ تَتْرُكْهُ يَلْهَثْۜ ذٰلِكَ مَثَلُ الْقَوْمِ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَاۚ فَاقْصُصِ الْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'Ve lev şi\'na le refa\'nahu biha ve lakinnehu ahlede ilel ardı vettebea hevah, fe meseluhu ke meselil kelb, in tahmil aleyhi yelhes ev tetrukhu yelhes, zalike meselul kavmillezine kezzebu bi ayatina, faksusil kasasa leallehum yetefekkerun.', 'Dileseydik[1] onu bununla[2] yükseltirdik. Fakat o yere saplandı,  hevasına[3] uydu. Onun durumu,  üzerine varsan da dilini sarkıtıp soluyan,  varmasan da dilini sarkıtıp soluyan köpeğin durumu gibidir. İşte ayetlerimizi yalanlayan halkın durumu böyledir. Sen bu kıssayı anlat,  belki öğüt alırlar.', 'ولو شينا لرفعنه بها ولكنه اخلد الي الارض واتبع هويه فمثله كمثل الكلب ان تحمل عليه يلهث او تتركه يلهث ذلك مثل القوم الذين كذبوا بايتنا فاقصص القصص لعلهم يتفكرون'),
(1131, 7, 177, 'سَٓاءَ مَثَلاًۨ الْقَوْمُ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا وَاَنْفُسَهُمْ كَانُوا يَظْلِمُونَ', 'Sae meselennil kavmullezine kezzebu bi ayatina ve enfusehum kanu yazlimun.', 'Âyetlerimizi yalanlayan ve böylece kendilerine haksızlık eden halkın durumu ne kötüdür.', 'سا مثلا القوم الذين كذبوا بايتنا وانفسهم كانوا يظلمون'),
(1132, 7, 178, 'مَنْ يَهْدِ اللّٰهُ فَهُوَ الْمُهْتَد۪يۚ وَمَنْ يُضْلِلْ فَاُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ', 'Men yehdillahu fehuvel muhtedi ve men yudlil fe ulaike humul hasirun.', 'Allah,  kime yol gösterirse[1],  odur yolu bulan. Kimi de saptırırsa[1],  işte onlar hüsrana uğrayanlardır.', 'من يهد الله فهو المهتدي ومن يضلل فاوليك هم الخسرون'),
(1133, 7, 179, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَث۪يراً مِنَ الْجِنِّ وَالْاِنْسِۘ  لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَاۘ وَلَهُمْ اَعْيُنٌ لَا يُبْصِرُونَ بِهَاۘ وَلَهُمْ اٰذَانٌ لَا يَسْمَعُونَ بِهَاۜ  اُو۬لٰٓئِكَ كَالْاَنْعَامِ بَلْ هُمْ اَضَلُّۜ اُو۬لٰٓئِكَ هُمُ الْغَافِلُونَ', 'Ve lekad zere\'na li cehenneme kesiren minel cinni vel insi lehum kulubun la yefkahune biha ve lehum a\'yunun la yubsırune biha ve lehum azanun la yesmeune biha, ulaike kel en\'ami bel hum edallu, ulaike humul gafilun.', 'Gerçek şu ki,  cinnden[1] ve insten[1] çoğalttıklarımızın[2] çoğu Cehennemliktir.[3] Ki onların kalpleri[4] vardır onunla kavramazlar,  gözleri vardır onunla görmezler,  kulakları vardır onunla işitmezler. İşte bunlar hayvanlar gibidirler,  hatta daha da bilinçsizdirler. İşte gafil olanlar bunlardır.', 'ولقد ذرانا لجهنم كثيرا من الجن والانس لهم قلوب لا يفقهون بها ولهم اعين لا يبصرون بها ولهم اذان لا يسمعون بها اوليك كالانعم بل هم اضل اوليك هم الغفلون'),
(1134, 7, 180, 'وَلِلّٰهِ الْاَسْمَٓاءُ الْحُسْنٰى فَادْعُوهُ بِهَاۖ وَذَرُوا الَّذ۪ينَ يُلْحِدُونَ ف۪ٓي اَسْمَٓائِه۪ۜ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ', 'Ve lillahil esmaul husna fed\'uhu biha ve zerullezine yulhıdune fi esmaih, se yuczevne ma kanu ya\'melun.', 'En iyi isimler[1] Allah\'ındır. Öyleyse O\'nu,  onlarla çağırın. Ona yakışmayan isimlerle çağıran kimseleri bırakın. Onlar,  yaptıklarının cezasını görecekler.', 'ولله الاسما الحسني فادعوه بها وذروا الذين يلحدون في اسميه سيجزون ما كانوا يعملون'),
(1135, 7, 181, 'وَمِمَّنْ خَلَقْنَٓا اُمَّةٌ يَهْدُونَ بِالْحَقِّ وَبِه۪ يَعْدِلُونَ۟', 'Ve mimmen halakna ummetun yehdune bil hakkı ve bihi ya\'dilun.', 'Yarattıklarımız arasında öyle bir topluluk da var ki,  hakka iletirler ve onunla adil olurlar.', 'وممن خلقنا امة يهدون بالحق وبه يعدلون'),
(1136, 7, 182, 'وَالَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَا سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَۚ', 'Vellezine kezzebu bi ayatina se nestedricuhum min haysu la ya\'lemun.', 'Âyetlerimizi yalanlayanları,  hiç bilemeyecekleri bir şekilde adım adım yok olmaya yaklaştırırız.', 'والذين كذبوا بايتنا سنستدرجهم من حيث لا يعلمون'),
(1137, 7, 183, 'وَاُمْل۪ي لَهُمْۜ اِنَّ كَيْد۪ي مَت۪ينٌ', 'Ve umli lehum, inne keydi metin', 'Onlara süre veriyorum,  ancak planım çok sağlamdır.', 'واملي لهم ان كيدي متين'),
(1138, 7, 184, 'اَوَلَمْ يَتَفَكَّرُوا مَا بِصَاحِبِهِمْ مِنْ جِنَّةٍۜ اِنْ هُوَ اِلَّا نَذ۪يرٌ مُب۪ينٌ', 'E ve lem yetefekkeru ma bi sahıbihim min cinneh, in huve illa nezirun mubin.', 'Arkadaşlarında,  hiçbir delilik olmadığını düşünmüyorlar mı? O,  ancak apaçık bir uyarıcıdır.', 'اولم يتفكروا ما بصاحبهم من جنة ان هو الا نذير مبين'),
(1139, 7, 185, 'اَوَلَمْ يَنْظُرُوا ف۪ي مَلَكُوتِ السَّمٰوَاتِ وَالْاَرْضِ وَمَا خَلَقَ اللّٰهُ مِنْ شَيْءٍۙ وَاَنْ عَسٰٓى اَنْ يَكُونَ قَدِ اقْتَرَبَ اَجَلُهُمْۚ فَبِاَيِّ حَد۪يثٍ بَعْدَهُ يُؤْمِنُونَ', 'E ve lem yanzuru fi melekutis semavati vel ardı ve ma halakallahu min şey\'in ve en asa en yekune kadıkterebe eceluhum, fe bi eyyi hadisin ba\'dehu yu\'minun.', 'Göklerin ve yerin melekutuna[1],  Allah\'ın yaratmış olduğu şeylere,  sürelerinin yaklaşmış olabileceği ihtimaline hiç bakmazlar mı? Bundan sonra artık hangi hadise[2] inanacaklar?', 'اولم ينظروا في ملكوت السموت والارض وما خلق الله من شي وان عسي ان يكون قد اقترب اجلهم فباي حديث بعده يومنون'),
(1140, 7, 186, 'مَنْ يُضْلِلِ اللّٰهُ فَلَا هَادِيَ لَهُۜ وَيَذَرُهُمْ ف۪ي طُغْيَانِهِمْ يَعْمَهُونَ', 'Men yudlilillahu fe la hadiye leh, ve yezeruhum fi tugyanihim ya\'mehun.', 'Allah,  kimi saptırırsa[1] ona doğru yolu gösterecek yoktur. Onları,  azgınlıkları içinde bocalar durumda bırakır.', 'من يضلل الله فلا هادي له ويذرهم في طغينهم يعمهون'),
(1141, 7, 187, 'يَسْـَٔلُونَكَ عَنِ السَّاعَةِ اَيَّانَ مُرْسٰيهَاۜ قُلْ اِنَّمَا عِلْمُهَا عِنْدَ رَبّ۪يۚ لَا يُجَلّ۪يهَا لِوَقْتِهَٓا اِلَّا هُوَۜ ثَقُلَتْ فِي السَّمٰوَاتِ وَالْاَرْضِۜ لَا تَأْت۪يكُمْ اِلَّا بَغْتَةًۜ يَسْـَٔلُونَكَ كَاَنَّكَ حَفِيٌّ عَنْهَاۜ قُلْ اِنَّمَا عِلْمُهَا عِنْدَ اللّٰهِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', 'Yes\'eluneke anis sa\'ati eyyane mursaha, kul innema ilmuha inde rabbi, la yucelliha li vaktiha illa huv, sekulet fis semavati vel ard, la te\'tikum illa bagtete, yes\'eluneke ke enneke hafiyyun anha, kul innema ilmuha indallahi ve lakinne ekseren nasi la ya\'lemun.', 'Sana Saat\'ten soruyorlar. Ne zaman gerçekleşecek diye. De ki: \"Onun bilgisi sadece Rabb\'imin yanındadır. Onun vaktini O\'ndan başkası açıklayamaz. O göklere de,  yere de ağır gelecektir. O size ansızın gelecek.\" Sanki sen biliyormuşsun gibi onu sana soruyorlar. De ki: \"Onun bilgisi sadece Allah\'ın yanındadır.\" Ancak insanların çoğu bu gerçeği bilmez.[1]', 'يسلونك عن الساعة ايان مرسيها قل انما علمها عند ربي لا يجليها لوقتها الا هو ثقلت في السموت والارض لا تاتيكم الا بغتة يسلونك كانك حفي عنها قل انما علمها عند الله ولكن اكثر الناس لا يعلمون'),
(1142, 7, 188, 'قُلْ لَٓا اَمْلِكُ لِنَفْس۪ي نَفْعاً وَلَا ضَراًّ اِلَّا مَا شَٓاءَ اللّٰهُۜ وَلَوْ كُنْتُ اَعْلَمُ الْغَيْبَ لَاسْتَكْثَرْتُ مِنَ الْخَيْرِۚ وَمَا مَسَّنِيَ السُّٓوءُ اِنْ اَنَا۬ اِلَّا نَذ۪يرٌ وَبَش۪يرٌ لِقَوْمٍ يُؤْمِنُونَ۟', 'Kul la emliku li nefsi nef\'an ve la darran illa maşaallah, ve lev kuntu a\'lemul gaybe lesteksertu minel hayri ve ma messeniyes suu in ene illa nezirun ve beşirun li kavmin yu\'minun.', 'De ki: \"Allah dilemedikçe,  kendime bir yarar sağlamak ya da kendimden bir zararı uzaklaştırmak benim elimde değil. Eğer gaybı[1] bilseydim,  elbette daha çok yararıma olan şeyi yapardım ve bana bir kötülük de dokunmazdı.[2] Ben,  inanan bir halk için sadece bir uyarıcı ve haber verenim.\"', 'قل لا املك لنفسي نفعا ولا ضرا الا ما شا الله ولو كنت اعلم الغيب لاستكثرت من الخير وما مسني السو ان انا الا نذير وبشير لقوم يومنون'),
(1143, 7, 189, 'هُوَ الَّذ۪ي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ اِلَيْهَاۚ فَلَمَّا تَغَشّٰيهَا حَمَلَتْ حَمْلاً خَف۪يفاً فَمَرَّتْ بِه۪ۚ فَلَمَّٓا اَثْقَلَتْ دَعَوَا اللّٰهَ رَبَّهُمَا لَئِنْ اٰتَيْتَنَا صَالِحاً لَنَكُونَنَّ مِنَ الشَّاكِر۪ينَ', 'Huvellezi halakakum min nefsin vahıdetin ve ceale minha zevceha li yeskune ileyha, fe lemma tegaşşaha hamelet hamlen hafifen fe merret bihi, fe lemma eskalet deavallahe rabbehuma lein ateytena salihan le nekunenne mineş şakirin.', 'O,  sizi bir tek nefisten[1] yarattı ve kendisi ile sükunet bulsun diye ondan[1] eşini var etti. Eşini sarıp örtünce,  eşi hafif bir yük yüklendi. Bir müddet böyle geçti. Yükü ağırlaşınca her ikisi de Rabb\'leri olan Allah\'a: \"Eğer bize salih[3] bir evlat verirsen elbette Sana şükredenlerden olacağız.\" diye dua ettiler.', 'هو الذي خلقكم من نفس وحدة وجعل منها زوجها ليسكن اليها فلما تغشيها حملت حملا خفيفا فمرت به فلما اثقلت دعوا الله ربهما لين اتيتنا صلحا لنكونن من الشكرين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1144, 7, 190, 'فَلَمَّٓا اٰتٰيهُمَا صَالِحاً جَعَلَا لَهُ شُرَكَٓاءَ ف۪يمَٓا اٰتٰيهُمَاۚ فَتَعَالَى اللّٰهُ عَمَّا يُشْرِكُونَ', 'Fe lemma atahuma salihan ceala lehu şurakae fima atahuma, fe tealallahu amma yuşrikun.', 'Fakat onlara,  salih bir evlat verince; kendilerine verilen şeyde ona ortaklar koşmaya başladılar. Allah,  onların ortak koştukları şeyden yücedir.', 'فلما اتيهما صلحا جعلا له شركا فيما اتيهما فتعلي الله عما يشركون'),
(1145, 7, 191, 'اَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـٔاً وَهُمْ يُخْلَقُونَۘ', 'E yuşrikune ma la yahluku şey\'en ve hum yuhlekun.', 'Hiçbir şey yaratamayan,  aksine kendisi de yaratılmış olan şeyleri mi ortak koşuyorlar?', 'ايشركون ما لا يخلق شيا وهم يخلقون'),
(1146, 7, 192, 'وَلَا يَسْتَط۪يعُونَ لَهُمْ نَصْراً وَلَٓا اَنْفُسَهُمْ يَنْصُرُونَ', 'Ve la yestetiune lehum nasran ve la enfusehum yansurun.', 'Oysa onlar,  ne onlara yardım edebilirler ne de kendilerine yardım edebilirler.', 'ولا يستطيعون لهم نصرا ولا انفسهم ينصرون'),
(1147, 7, 193, 'وَاِنْ تَدْعُوهُمْ اِلَى الْهُدٰى لَا يَتَّبِعُوكُمْۜ سَوَٓاءٌ عَلَيْكُمْ اَدَعَوْتُمُوهُمْ اَمْ اَنْتُمْ صَامِتُونَ', 'Ve in ted\'uhum ilel huda la yettebiukum, sevaun aleykum e deavtumuhum em entum samitun.', 'Onları gerçeği kabul etmeye davet etseniz,  size tabi olmazlar. Onları davet etseniz de etmeseniz de size karşı tutumları değişmez.', 'وان تدعوهم الي الهدي لا يتبعوكم سوا عليكم ادعوتموهم ام انتم صمتون'),
(1148, 7, 194, 'اِنَّ الَّذ۪ينَ تَدْعُونَ مِنْ دُونِ اللّٰهِ عِبَادٌ اَمْثَالُكُمْ فَادْعُوهُمْ فَلْيَسْتَج۪يبُوا لَكُمْ اِنْ كُنْتُمْ صَادِق۪ينَ', 'İnnellezine ted\'une min dunillahi ıbadun emsalukum fed\'uhum felyestecibu lekum in kuntum sadıkin.', 'Allah\'tan başka dua ettikleriniz,  sizin gibi kullardır. Eğer doğru sözlü kimselerseniz,  haydi onlara dua edin de size karşılık versinler.', 'ان الذين تدعون من دون الله عباد امثالكم فادعوهم فليستجيبوا لكم ان كنتم صدقين'),
(1149, 7, 195, 'اَلَهُمْ اَرْجُلٌ يَمْشُونَ بِهَاۘ اَمْ لَهُمْ اَيْدٍ يَبْطِشُونَ بِهَاۘ اَمْ لَهُمْ اَعْيُنٌ يُبْصِرُونَ بِهَاۘ اَمْ لَهُمْ اٰذَانٌ يَسْمَعُونَ بِهَاۜ قُلِ ادْعُوا شُرَكَٓاءَكُمْ ثُمَّ ك۪يدُونِ فَلَا تُنْظِرُونِ', 'E lehum erculun yemşune biha, em lehum eydin yabtışune biha, em lehum a\'yunun yubsırune biha, em lehum azanun yesmeune biha, kulid\'u şurekaekum summe kiduni fe la tunzırun.', 'Onların,  kendileriyle yürüyecek ayakları mı var? Veya tutacak elleri mi var? Veya görecek gözleri mi var? Ya da işitecek kulakları mı var? De ki: \"Haydi çağırın ortaklarınızı,  sonra göz açtırmaksızın bana tuzak kurun.\"', 'الهم ارجل يمشون بها ام لهم ايد يبطشون بها ام لهم اعين يبصرون بها ام لهم اذان يسمعون بها قل ادعوا شركاكم ثم كيدون فلا تنظرون'),
(1150, 7, 196, 'اِنَّ وَلِـِّيَ اللّٰهُ الَّذ۪ي نَزَّلَ الْكِتَابَۘ وَهُوَ يَتَوَلَّى الصَّالِح۪ينَ', 'İnne veliyyiyallahullezi nezzelel kitabe ve huve yetevelles salihin.', '\"Kuşkusuz benim velim[1],  Kitap\'ı indiren Allah\'tır. O,  salih[2] olanları koruyup gözetir.\"', 'ان ولي الله الذي نزل الكتب وهو يتولي الصلحين'),
(1151, 7, 197, 'وَالَّذ۪ينَ تَدْعُونَ مِنْ دُونِه۪ لَا يَسْتَط۪يعُونَ نَصْرَكُمْ وَلَٓا اَنْفُسَهُمْ يَنْصُرُونَ', 'Vellezine ted\'une min dunihi la yestetiune nasrakum ve la enfusehum yensurun.', '\"O\'ndan başka dua ettiklerinizin,  ne size yardım etmeye güçleri yeter,  ne de kendilerine yardım etmeye.\"', 'والذين تدعون من دونه لا يستطيعون نصركم ولا انفسهم ينصرون'),
(1152, 7, 198, 'وَاِنْ تَدْعُوهُمْ اِلَى الْهُدٰى لَا يَسْمَعُواۜ وَتَرٰيهُمْ يَنْظُرُونَ اِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', 'Ve in ted\'uhum ilel huda la yesme\'u, ve terahum yenzurune ileyke ve hum la yubsırun.', 'Eğer onları doğru yola çağırsanız sizi duymazlar. Onların,  sana baktıklarını sanırsın,  oysa onlar görmezler.', 'وان تدعوهم الي الهدي لا يسمعوا وتريهم ينظرون اليك وهم لا يبصرون'),
(1153, 7, 199, 'خُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَاَعْرِضْ عَنِ الْجَاهِل۪ينَ', 'Huzil afve ve\'mur bil urfi ve a\'rıd anil cahilin.', 'Affedici ol,  urf[1] ile buyur,  cahillerden[2] yüz çevir.', 'خذ العفو وامر بالعرف واعرض عن الجهلين'),
(1154, 7, 200, 'وَاِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللّٰهِۜ اِنَّهُ سَم۪يعٌ عَل۪يمٌ', 'Ve imma yenzeganneke mineş şeytani nezgun festeiz billah, innehu semiun alim.', 'Ne zaman şeytan seni dürtecek olursa[1] hemen Allah\'a sığın. Kuşkusuz O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'واما ينزغنك من الشيطن نزغ فاستعذ بالله انه سميع عليم'),
(1155, 7, 201, 'اِنَّ الَّذ۪ينَ اتَّقَوْا اِذَا مَسَّهُمْ طَٓائِفٌ مِنَ الشَّيْطَانِ تَذَكَّرُوا فَاِذَا هُمْ مُبْصِرُونَۚ', 'İnnellezinettekav iza messehum taifun mineş şeytani tezekkeru fe izahum mubsırun.', 'Takva sahipleri,  şeytandan bir dürtü olduğu zaman,  düşünüp hemen gerçeği kavrarlar.', 'ان الذين اتقوا اذا مسهم طيف من الشيطن تذكروا فاذا هم مبصرون'),
(1156, 7, 202, 'وَاِخْوَانُهُمْ يَمُدُّونَهُمْ فِي الْغَيِّ ثُمَّ لَا يُقْصِرُونَ', 'Ve ihvanuhum yemuddunehum fil gayyi summe la yuksirun.', 'Şeytanlar,  kendilerine kardeş olanları azgınlığa sürüklerler,  sonra da yakalarını bırakmazlar.', 'واخونهم يمدونهم في الغي ثم لا يقصرون'),
(1157, 7, 203, 'وَاِذَا لَمْ تَأْتِهِمْ بِاٰيَةٍ قَالُوا لَوْلَا اجْتَبَيْتَهَاۜ قُلْ اِنَّـمَٓا اَتَّبِـعُ مَا يُوحٰٓى اِلَيَّ مِنْ رَبّ۪يۚ هٰذَا بَصَٓائِرُ مِنْ رَبِّكُمْ وَهُدًى وَرَحْمَةٌ لِقَوْمٍ يُؤْمِنُونَ', 'Ve iza lem te\'tihim biayetin kalu lev lectebeyteha, kul innema ettebiu ma yuha ileyye min rabbi haza besairu min rabbikum ve huden ve rahmetun li kavmin yu\'minun .', 'Onlara bir ayet getirmediğin zaman,  \"Derleyip uydursaydın ya.\" derler. De ki: \"Ben ancak Rabb\'imden bana vahyedilene uyuyorum. Bu,  inanan bir halk için Rabb\'inizden gelen bir basiret[1],  bir yol gösterici ve bir rahmettir.\"', 'واذا لم تاتهم باية قالوا لولا اجتبيتها قل انما اتبع ما يوحي الي من ربي هذا بصاير من ربكم وهدي ورحمة لقوم يومنون'),
(1158, 7, 204, 'وَاِذَا قُرِئَ الْقُرْاٰنُ فَاسْتَمِعُوا لَهُ وَاَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ', 'Ve iza kuriel kur\'anu festemiu lehu ve ensıtu leallekum turhamun.', 'Kur\'an okunduğu zaman hemen susup onu dinleyin[1] ki size rahmet edilsin.[2]', 'واذا قري القران فاستمعوا له وانصتوا لعلكم ترحمون'),
(1159, 7, 205, 'وَاذْكُرْ رَبَّكَ ف۪ي نَفْسِكَ تَضَرُّعاً وَخ۪يفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْاٰصَالِ وَلَا تَكُنْ مِنَ الْغَافِل۪ينَ', 'Vezkur rabbeke fi nefsike tedarruan ve hifeten ve dunel cehri minel kavli bil guduvvi vel asali ve la tekun minel gafilin.', 'Nefsinde[1] tezarruan[2] ve çekinerek,  yüksek olmayan bir sesle sabah akşam[3] Rabb\'ini an. Umursamazlardan olma!', 'واذكر ربك في نفسك تضرعا وخيفة ودون الجهر من القول بالغدو والاصال ولا تكن من الغفلين'),
(1160, 7, 206, 'اِنَّ الَّذ۪ينَ عِنْدَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِه۪ وَيُسَبِّحُونَهُ وَلَهُ يَسْجُدُونَ', 'İnnellezine inde rabbike la yestekbirune an ibadetihi ve yusebbihunehu ve lehu yescudun.', 'Rabb\'ine yakın olanlar,  O\'na kulluk etmekten asla kibirlenmezler; O\'nu tesbih[1] ederler ve O\'na secde[2] ederler.', 'ان الذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون'),
(1161, 8, 1, 'يَسْـَٔلُونَكَ عَنِ الْاَنْفَالِۜ قُلِ الْاَنْفَالُ لِلّٰهِ وَالرَّسُولِۚ فَاتَّقُوا اللّٰهَ وَاَصْلِحُوا ذَاتَ بَيْنِكُمْۖ وَاَط۪يعُوا اللّٰهَ وَرَسُولَهُٓ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Yes\'eluneke anil enfal, kulil enfalu lillahi ver resul, fettekullahe ve aslihu zate beynikum ve etiullahe ve resulehu in kuntum mu\'minin.', 'Sana enfalı[1] soruyorlar. De ki: \"Enfal,  Allah ve Resulü içindir. Eğer mü\'min iseniz Allah\'a karşı takva[2] sahibi olun,  birbirinizin arasını düzeltin,  Allah\'a ve Resul\'üne itaat edin.', 'يسلونك عن الانفال قل الانفال لله والرسول فاتقوا الله واصلحوا ذات بينكم واطيعوا الله ورسوله ان كنتم مومنين'),
(1162, 8, 2, 'اِنَّمَا الْمُؤْمِنُونَ الَّذ۪ينَ اِذَا ذُكِرَ اللّٰهُ وَجِلَتْ قُلُوبُهُمْ وَاِذَا تُلِيَتْ عَلَيْهِمْ اٰيَاتُهُ زَادَتْهُمْ ا۪يمَاناً وَعَلٰى رَبِّهِمْ يَتَوَكَّلُونَۚ', 'İnnemel mu\'minunellezine iza zukirallahu vecilet kulubuhum ve iza tuliyet aleyhim ayatuhu zadethum imanen ve ala rabbihim yetevekkelun.', 'Gerçekten Mü\'minler o kimselerdir ki: Allah anıldığı zaman kalpleri ürperir,  onlara Allah\'ın ayetleri okunduğunda bu imanlarını artırır ve yalnızca Rabb\'lerine tevekkül[1] ederler.', 'انما المومنون الذين اذا ذكر الله وجلت قلوبهم واذا تليت عليهم ايته زادتهم ايمنا وعلي ربهم يتوكلون'),
(1163, 8, 3, 'اَلَّذ۪ينَ يُق۪يمُونَ الصَّلٰوةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَۜ', 'Ellezine yukimunes salate ve mimma razaknahum yunfikun.', 'Onlar,  salatı[1] ikame eden[2] ve kendilerine rızık olarak verdiğimiz şeylerden infak[3] edenlerdir.', 'الذين يقيمون الصلوة ومما رزقنهم ينفقون'),
(1164, 8, 4, 'اُو۬لٰٓئِكَ هُمُ الْمُؤْمِنُونَ حَـقاًّۜ لَهُمْ دَرَجَاتٌ عِنْدَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَر۪يمٌۚ', 'Ulaike humul mu\'minune hakka, lehum derecatun inde rabbihim ve magfiretun ve rızkun kerim.', 'İşte onlar gerçek mü\'minlerdir. Onlar için Rabb\'leri katında dereceler,  bağışlanma ve kerim[1] bir rızık vardır.', 'اوليك هم المومنون حقا لهم درجت عند ربهم ومغفرة ورزق كريم'),
(1165, 8, 5, 'كَمَٓا اَخْرَجَكَ رَبُّكَ مِنْ بَيْتِكَ بِالْحَقِّۖ وَاِنَّ فَر۪يقاً مِنَ الْمُؤْمِن۪ينَ لَكَارِهُونَۙ', 'Kema ahreceke rabbuke min beytike bil hakkı ve inne ferikan minel mu\'minine le karihun.', 'Keza,  Rabb\'in hakk uğruna seni evinden çıkardı. Oysa Mü\'minlerden bir kısmı bundan hoşlanmamıştı.', 'كما اخرجك ربك من بيتك بالحق وان فريقا من المومنين لكرهون'),
(1166, 8, 6, 'يُجَادِلُونَكَ فِي الْحَقِّ بَعْدَ مَا تَبَيَّنَ كَاَنَّمَا يُسَاقُونَ اِلَى الْمَوْتِ وَهُمْ يَنْظُرُونَۜ', 'Yucadiluneke fil hakkı ba\'de ma tebeyyene ke ennema yusakune ilel mevti ve hum yanzurun.', 'Hakk açığa çıktıktan sonra bile,  sanki göz göre göre ölüme sürükleniyorlarmış gibi,  seninle tartışıyorlardı.', 'يجدلونك في الحق بعدما تبين كانما يساقون الي الموت وهم ينظرون'),
(1167, 8, 7, 'وَاِذْ يَعِدُكُمُ اللّٰهُ اِحْدَى الطَّٓائِفَتَيْنِ اَنَّهَا لَكُمْ وَتَوَدُّونَ اَنَّ غَيْرَ ذَاتِ الشَّوْكَةِ تَكُونُ لَكُمْ وَيُر۪يدُ اللّٰهُ اَنْ يُحِقَّ الْحَقَّ بِكَلِمَاتِه۪ وَيَقْطَعَ دَابِرَ الْكَافِر۪ينَۙ', 'Ve iz yaıdukumullahu ihdet taifeteyni enneha lekum, ve teveddune enne gayre zatiş şevketi tekunu lekum, ve yuridullahu en yuhıkkal hakka bi kelimatihi ve yaktaa dabirel kafirin.', 'Allah,  iki topluluktan birinin sizin olacağını vaat ediyordu. Siz ise kuvveti bulunmayanı istiyordunuz. Oysa Allah da kelimeleriyle[1] Hakk\'ı gerçekleştirmek ve Kafirlerin[2] kökünün kesilmesini istiyordu.', 'واذ يعدكم الله احدي الطايفتين انها لكم وتودون ان غير ذات الشوكة تكون لكم ويريد الله ان يحق الحق بكلمته ويقطع دابر الكفرين'),
(1168, 8, 8, 'لِيُحِقَّ الْحَقَّ وَيُبْطِلَ الْبَاطِلَ وَلَوْ كَرِهَ الْمُجْرِمُونَۚ', 'Li yuhıkkal hakka ve yubtılel batıle ve lev kerihel mucrimun.', 'Bu,  suçluların hoşuna gitmese de Hakk\'ın ortaya çıkarılması ve Batıl\'ın yok olması içindi.', 'ليحق الحق ويبطل البطل ولو كره المجرمون'),
(1169, 8, 9, 'اِذْ تَسْتَغ۪يثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ اَنّ۪ي مُمِدُّكُمْ بِاَلْفٍ مِنَ الْمَلٰٓئِكَةِ مُرْدِف۪ينَ', 'İz testegisune rabbekum festecabe lekum enni mumiddukum bi elfin minel melaiketi murdifin.', 'Hani siz,  Rabb\'inizden yardım istiyordunuz. O da ardı ardına bin melekle yardım edeceğim diye,  isteğinize karşılık vermişti.', 'اذ تستغيثون ربكم فاستجاب لكم اني ممدكم بالف من المليكة مردفين'),
(1170, 8, 10, 'وَمَا جَعَلَهُ اللّٰهُ اِلَّا بُشْرٰى وَلِتَطْمَئِنَّ بِه۪ قُلُوبُكُمْۚ وَمَا النَّصْرُ اِلَّا مِنْ عِنْدِ اللّٰهِۜ اِنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ۟', 'Ve ma cealehullahu illa buşra ve li tatmainne bihi kulubukum ve men nasru illa min indillah, innallahe azizun hakim.', 'Allah bunu,  ancak bir müjde olsun ve onunla kalpleriniz yatışsın[1] diye yaptı. Yardım,  ancak Allah\'tandır. Kuşkusuz Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'وما جعله الله الا بشري ولتطمين به قلوبكم وما النصر الا من عند الله ان الله عزيز حكيم'),
(1171, 8, 11, 'اِذْ يُغَشّ۪يكُمُ النُّعَاسَ اَمَنَةً مِنْهُ وَيُنَزِّلُ عَلَيْكُمْ مِنَ السَّمَٓاءِ مَٓاءً لِيُطَهِّرَكُمْ بِه۪ وَيُذْهِبَ عَنْكُمْ رِجْزَ الشَّيْطَانِ وَلِيَرْبِطَ عَلٰى قُلُوبِكُمْ وَيُثَبِّتَ بِهِ الْاَقْدَامَۜ', 'İz yugaşşikumun nuase emeneten minhu ve yunezzilu aleykum mines semai maen li yutahhirekum bihi ve yuzhibe ankum riczeş şeytani ve li yerbıta ala kulubikum ve yusebbite bihil akdam.', 'Hani O,  size Kendi katından bir emniyet olmak üzere bir uyku sardırıyordu. Sizi arındırmak,  sizden şeytanın pisliğini[1] gidermek,  kalplerinizi yatıştırmak ve ayaklarınızı yere sabit kılmak için gökten üzerinize bir su indiriyordu.', 'اذ يغشيكم النعاس امنة منه وينزل عليكم من السما ما ليطهركم به ويذهب عنكم رجز الشيطن وليربط علي قلوبكم ويثبت به الاقدام'),
(1172, 8, 12, 'اِذْ يُوح۪ي رَبُّكَ اِلَى الْمَلٰٓئِكَةِ اَنّ۪ي مَعَكُمْ فَثَبِّتُوا الَّذ۪ينَ اٰمَنُواۜ سَاُلْق۪ي ف۪ي قُلُوبِ الَّذ۪ينَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْاَعْنَاقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍۜ', 'İz yuhi rabbuke ilel melaiketi enni meakum fe sebbitullezine amenu, seulki fi kulubillezine keferur ru\'be fadribu fevkal a\'nakı vadribu minhum kulle benan.', 'Hani,  Rabb\'in meleklere,  sizinle beraberim,  diye vahyediyordu; \"İman edenleri pekiştirin.\" Kafirlerin kalplerine korku salacağım. Haydi! Vurun onların boyunlarına,  vurun onların parmaklarına.', 'اذ يوحي ربك الي المليكة اني معكم فثبتوا الذين امنوا سالقي في قلوب الذين كفروا الرعب فاضربوا فوق الاعناق واضربوا منهم كل بنان'),
(1173, 8, 13, 'ذٰلِكَ بِاَنَّهُمْ شَٓاقُّوا اللّٰهَ وَرَسُولَهُۚ وَمَنْ يُشَاقِقِ اللّٰهَ وَرَسُولَهُ فَاِنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ', 'Zalike bi ennehum şakkullahe ve resuluh, ve men yuşakıkıllahe ve resulehu fe innallahe şedidul ikab.', 'Böyle! Çünkü onlar,  Allah\'a ve Resul\'üne karşı geldiler. Kim Allah\'a ve Resul\'üne karşı gelirse,  bilsin ki,  Allah\'ın Azabı Çok Çetindir.', 'ذلك بانهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فان الله شديد العقاب'),
(1174, 8, 14, 'ذٰلِكُمْ فَذُوقُوهُ وَاَنَّ لِلْكَافِر۪ينَ عَذَابَ النَّارِ', 'Zalikum fe zukuhu ve enne lil kafirine azaben nar.', 'Şimdi onu tadın. Kafirler için yalnızca ateşin azabı vardır.', 'ذلكم فذوقوه وان للكفرين عذاب النار'),
(1175, 8, 15, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا لَق۪يتُمُ الَّذ۪ينَ كَفَرُوا زَحْفاً فَلَا تُوَلُّوهُمُ الْاَدْبَارَۚ', 'Ya eyyuhellezine amenu iza lekitumullezine keferu zahfen fe la tuvelluhumul edbar.', 'Ey iman edenler! Kafirlerin[1] orduları ile karşılaştığınız zaman,  onlara arkanızı dönmeyin.', 'يايها الذين امنوا اذا لقيتم الذين كفروا زحفا فلا تولوهم الادبار'),
(1176, 8, 16, 'وَمَنْ يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُٓ اِلَّا مُتَحَرِّفاً لِقِتَالٍ اَوْ مُتَحَيِّزاً اِلٰى فِئَةٍ فَقَدْ بَٓاءَ بِغَضَبٍ مِنَ اللّٰهِ وَمَأْوٰيهُ جَهَنَّمُۜ وَبِئْسَ الْمَص۪يرُ', 'Ve men yuvellihim yevmeizin duburehu illa muteharrifen li kıtalin ev mutehayyizen ila fietin fe kad bae bi gadabin minallahi ve me\'vahu cehennem, ve bi\'sel masir.', 'Kim böyle bir günde,  savaşmak için bir cepheye çekilmek amacıyla veya başka bir birliğe katılmanın dışında,  düşmana arkasını dönerse,  Allah\'ın gazabına uğramış olur. Onun varacağı yer Cehennem\'dir. O,  ne kötü bir dönüş yeridir.', 'ومن يولهم يوميذ دبره الا متحرفا لقتال او متحيزا الي فية فقد با بغضب من الله وماويه جهنم وبيس المصير'),
(1177, 8, 17, 'فَلَمْ تَقْتُلُوهُمْ وَلٰكِنَّ اللّٰهَ قَتَلَهُمْۖ وَمَا رَمَيْتَ اِذْ رَمَيْتَ وَلٰكِنَّ اللّٰهَ رَمٰىۚ وَلِيُبْلِيَ الْمُؤْمِن۪ينَ مِنْهُ بَلَٓاءً حَسَناًۜ اِنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌ', 'Fe lem taktuluhum ve lakinnallahe katelehum, ve ma remeyte iz remeyte ve lakinnallahe rema, ve li yubliyel mu\'minine minhu belaen hasena, innallahe semiun alim.', 'Onları siz öldürmediniz,  fakat Allah öldürdü. Attığın zaman da sen atmadın,  fakat Allah attı.[1] Allah,  bunu mü\'minleri iyi bir sınavla sınava tabi tutmak için yaptı. Kuşkusuz Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'فلم تقتلوهم ولكن الله قتلهم وما رميت اذ رميت ولكن الله رمي وليبلي المومنين منه بلا حسنا ان الله سميع عليم'),
(1178, 8, 18, 'ذٰلِكُمْ وَاَنَّ اللّٰهَ مُوهِنُ كَيْدِ الْكَافِر۪ينَ', 'Zalikum ve ennallahe muhinu keydil kafirin.', 'İşte size böyle yardım etti. Allah,  Kafirlerin planlarını bozandır.', 'ذلكم وان الله موهن كيد الكفرين'),
(1179, 8, 19, 'اِنْ تَسْتَفْتِحُوا فَقَدْ جَٓاءَكُمُ الْفَتْحُۚ وَاِنْ تَنْتَهُوا فَهُوَ خَيْرٌ لَكُمْۚ وَاِنْ تَعُودُوا نَعُدْۚ وَلَنْ تُغْنِيَ عَنْكُمْ فِئَتُكُمْ شَيْـٔاً وَلَوْ كَـثُرَتْۙ وَاَنَّ اللّٰهَ مَعَ الْمُؤْمِن۪ينَ۟', 'İn testeftihu fe kad caekumul feth, ve in tentehu fe huve hayrun lekum, ve in teudu naud, ve len tugniye ankum fietukum şey\'en ve lev kesuret ve ennallahe meal mu\'minin.', 'Eğer fetih istiyorsanız,  işte size fetih geldi. Eğer son verirseniz,  o sizin için daha hayırlıdır. Eğer dönerseniz,  Biz de döneriz. Topluluğunuz çok olsa da kesinlikle size bir fayda vermez. Kuşkusuz Allah,  Mü\'minlerle beraberdir.', 'ان تستفتحوا فقد جاكم الفتح وان تنتهوا فهو خير لكم وان تعودوا نعد ولن تغني عنكم فيتكم شيا ولو كثرت وان الله مع المومنين'),
(1180, 8, 20, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَط۪يعُوا اللّٰهَ وَرَسُولَهُ وَلَا تَوَلَّوْا عَنْهُ وَاَنْتُمْ تَسْمَعُونَۚ', 'Ya eyyuhellezine amenu etiullahe ve resulehu ve la tevellev anhu ve entum tesmeun.', 'Ey iman edenler! Allah\'a ve Resul\'üne itaat edin.[1] İşitip dururken ondan yüz çevirmeyin!', 'يايها الذين امنوا اطيعوا الله ورسوله ولا تولوا عنه وانتم تسمعون'),
(1181, 8, 21, 'وَلَا تَكُونُوا كَالَّذ۪ينَ قَالُوا سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', 'Ve la tekunu kellezine kalu semi\'na ve hum la yesmeun.', 'İşitmedikleri halde[1],  işittik diyen[2] kimseler gibi olmayın!', 'ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون'),
(1182, 8, 22, 'اِنَّ شَرَّ الدَّوَٓابِّ عِنْدَ اللّٰهِ الصُّمُّ الْبُكْمُ الَّذ۪ينَ لَا يَعْقِلُونَ', 'İnne şerred devabbi indallahis summul bukmullezine la ya\'kılun.', 'Allah katında,  yeryüzündeki canlıların en değersizi,  aklını kullanmayan sağırlar ve dilsizlerdir.[1]', 'ان شر الدواب عند الله الصم البكم الذين لا يعقلون'),
(1183, 8, 23, 'وَلَوْ عَلِمَ اللّٰهُ ف۪يهِمْ خَيْراً لَاَسْمَعَهُمْۜ وَلَوْ اَسْمَعَهُمْ لَتَوَلَّوْا وَهُمْ مُعْرِضُونَ', 'Ve lev alimallahu fi him hayren le esmeahum, ve lev esmeahum le tevellev ve hum mu\'ridune.', 'Eğer Allah,  onlarda bir hayır olduğunu görseydi onlara işittirirdi. Onlara işittirseydi de aldırmayarak yine dönerlerdi.', 'ولو علم الله فيهم خيرا لاسمعهم ولو اسمعهم لتولوا وهم معرضون'),
(1184, 8, 24, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اسْتَج۪يبُوا لِلّٰهِ وَلِلرَّسُولِ اِذَا دَعَاكُمْ لِمَا يُحْي۪يكُمْۚ وَاعْلَمُٓوا اَنَّ اللّٰهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِه۪ وَاَنَّـهُٓ اِلَيْهِ تُحْشَرُونَ', 'Ya eyyuhellezine amenustecibu lillahi ve lir resuli iza deakum lima yuhyikum, va\'lemu ennallahe yehulu beynel mer\'i ve kalbihi ve ennehu ileyhi tuhşerun.', 'Ey iman edenler! Sizi,  size hayat verecek şeylere çağırdığı zaman,  Allah\'a ve Resul\'üne icabet edin. Bilin ki Allah,  kişi ile kalbinin arasına girer[1]. Kuşkusuz hepiniz O\'na dönüp toplanacaksınız.', 'يايها الذين امنوا استجيبوا لله وللرسول اذا دعاكم لما يحييكم واعلموا ان الله يحول بين المر وقلبه وانه اليه تحشرون'),
(1185, 8, 25, 'وَاتَّقُوا فِتْنَةً لَا تُص۪يبَنَّ الَّذ۪ينَ ظَلَمُوا مِنْكُمْ خَٓاصَّةًۚ وَاعْلَمُٓوا اَنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ', 'Vetteku fitneten la tusibennellezine zalemu minkum hassah, va\'lemu ennallahe şedidul ikab.', 'Yalnızca aranızdaki haksızlık edenlerin başlarına gelmekle sınırlı kalmayacak fitneye[1] karşı takva sahibi olun. Unutmayın ki Allah\'ın azabı çok çetindir.', 'واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة واعلموا ان الله شديد العقاب'),
(1186, 8, 26, 'وَاذْكُـرُٓوا اِذْ اَنْتُمْ قَل۪يلٌ مُسْتَضْعَفُونَ فِي الْاَرْضِ تَخَافُونَ اَنْ يَتَخَطَّفَكُمُ النَّاسُ فَاٰوٰيكُمْ وَاَيَّدَكُمْ بِنَصْرِه۪ وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِ لَعَلَّكُمْ تَشْكُرُونَ', 'Vezkuru iz entum kalilun mustad\'afune fil ardı tehafune en yetehattafekumun nasu fe avakum ve eyyedekum bi nasrihi ve rezekakum minet tayyibati leallekum teşkurun.', 'Ve hatırlayın; bir zamanlar yeryüzünde sayıca azdınız ve mus\'tezaf[1] kimselerdiniz. İnsanların sizi alıp götürmesinden korkuyordunuz. O,  sizi barındırdı ve yardımıyla kuvvetlendirdi. Temiz şeylerden size rızık verdi. O halde şükretmelisiniz.', 'واذكروا اذ انتم قليل مستضعفون في الارض تخافون ان يتخطفكم الناس فاويكم وايدكم بنصره ورزقكم من الطيبت لعلكم تشكرون'),
(1187, 8, 27, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَخُونُوا اللّٰهَ وَالرَّسُولَ وَتَخُونُٓوا اَمَانَاتِكُمْ وَاَنْتُمْ تَعْلَمُونَ', 'Ya eyyuhellezine amenu la tehunullahe ver resule ve tehunu emanatikum ve entum ta\'lemun.', 'Ey iman edenler! Allah\'a ve Resulüne ihanet etmeyin. Yoksa bile bile emanetlerinize ihanet etmiş olursunuz.', 'يايها الذين امنوا لا تخونوا الله والرسول وتخونوا امنتكم وانتم تعلمون'),
(1188, 8, 28, 'وَاعْلَمُٓوا اَنَّـمَٓا اَمْوَالُكُمْ وَاَوْلَادُكُمْ فِتْنَةٌۙ وَاَنَّ اللّٰهَ عِنْدَهُٓ اَجْرٌ عَظ۪يمٌ۟', 'Va\'lemu ennema emvalukum ve evladukum fitnetun ve ennallahe indehu ecrun azim.', 'Bilin ki mallarınız ve evlatlarınız ancak birer fitnedir.[1] Kuşkusuz Allah\'ın yanında çok büyük ödül vardır.', 'واعلموا انما امولكم واولدكم فتنة وان الله عنده اجر عظيم'),
(1189, 8, 29, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنْ تَتَّقُوا اللّٰهَ يَجْعَلْ لَكُمْ فُرْقَاناً وَيُكَفِّرْ عَنْكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Ya eyyuhellezine amenu in tettekullahe yec\'al lekum furkanen ve yukeffir ankum seyyiatikum ve yagfir lekum, vallahu zul fadlil azim.', 'Ey iman edenler! Eğer Allah için takvalı olursanız; O,  size bir Furkan[1] verir,  kötülüklerinize kafirlik eder[2] ve sizi bağışlar. Allah,  Büyük Fazl[3] Sahibidir.', 'يايها الذين امنوا ان تتقوا الله يجعل لكم فرقانا ويكفر عنكم سياتكم ويغفر لكم والله ذو الفضل العظيم'),
(1190, 8, 30, 'وَاِذْ يَمْكُرُ بِكَ الَّذ۪ينَ كَفَرُوا لِيُثْبِتُوكَ اَوْ يَقْتُلُوكَ اَوْ يُخْرِجُوكَۜ وَيَمْكُرُونَ وَيَمْكُرُ اللّٰهُۜ وَاللّٰهُ خَيْرُ الْمَاكِر۪ينَ', 'Ve iz yemkuru bikellezine keferu li yusbituke ev yaktuluke ev yuhricuk ve yemkurune ve yemkurullah, vallahu hayrul makirin.', 'Kafirler seni tutuklamak,  öldürmek veya sürgün etmek için plan yapıyorlardı. Onlar plan yaparlarken,  Allah da plan yapıyordu. Allah,  plan yapanların en hayırlısıdır.', 'واذ يمكر بك الذين كفروا ليثبتوك او يقتلوك او يخرجوك ويمكرون ويمكر الله والله خير المكرين'),
(1191, 8, 31, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا قَالُوا قَدْ سَمِعْنَا لَوْ نَشَٓاءُ لَقُلْنَا مِثْلَ هٰذَٓاۙ اِنْ هٰذَٓا اِلَّٓا اَسَاط۪يرُ الْاَوَّل۪ينَ', 'Ve iza tutla aleyhim ayatuna kalu kad semi\'na lev neşau le kulna misle haza in haza illa esatirul evvelin.', 'Onlara,  ayetlerimiz okunduğu zaman,  \"Evet,  biz bunu duyduk,  dilersek biz de onun benzerini söyleriz; bu,  evvelkilerin masallarından başka bir şey değildir.\" dediler.', 'واذا تتلي عليهم ايتنا قالوا قد سمعنا لو نشا لقلنا مثل هذا ان هذا الا اسطير الاولين'),
(1192, 8, 32, 'وَاِذْ قَالُوا اللّٰهُمَّ اِنْ كَانَ هٰذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَاَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَٓاءِ اَوِ ائْتِنَا بِعَذَابٍ اَل۪يمٍ', 'Ve iz kalullahumme in kane haza huvel hakka min indike fe emtir aleyna hıcareten mines semai evi\'tina bi azabin elim.', 'Bir de dediler ki: \"Allah\'ım! Eğer bu Senin tarafından gelen bir gerçekse[1],  gökten üzerimize taş yağdır veya bize can yakıcı bir azap ver.\"', 'واذ قالوا اللهم ان كان هذا هو الحق من عندك فامطر علينا حجارة من السما او ايتنا بعذاب اليم'),
(1193, 8, 33, 'وَمَا كَانَ اللّٰهُ لِيُعَذِّبَهُمْ وَاَنْتَ ف۪يهِمْۜ وَمَا كَانَ اللّٰهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', 'Ve ma kanallahu li yuazzibehum ve ente fihim, ve ma kanallahu muazzibehum ve hum yestagfirun.', 'Sen onların içindeyken,  Allah,  onlara azap etmez. Onlar,  bağışlanma diledikleri sürece de Allah onlara azap edecek değildir.', 'وما كان الله ليعذبهم وانت فيهم وما كان الله معذبهم وهم يستغفرون'),
(1194, 8, 34, 'وَمَا لَهُمْ اَلَّا يُعَذِّبَهُمُ اللّٰهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ وَمَا كَانُٓوا اَوْلِيَٓاءَهُۜ اِنْ اَوْلِيَٓاؤُ۬هُٓ اِلَّا الْمُتَّقُونَ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Ve ma lehum ella yuazzibehumullahu ve hum yasuddune anil mescidil harami ve ma kanu evliyaehu, in evliyauhu illel muttekune ve lakinne ekserehum la ya\'lemun.', 'Onlar,  Mescid-i Haram\'a girmeye engel oldukları halde ve onun velileri olmadıkları halde Allah neden onlara azap etmesin? Oysa oranın evliyası[1] muttakilerdir[2]. Fakat onların çoğu bilmezler.', 'وما لهم الا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا اولياه ان اولياوه الا المتقون ولكن اكثرهم لا يعلمون'),
(1195, 8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِنْدَ الْبَيْتِ اِلَّا مُكَٓاءً وَتَصْدِيَةًۜ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ', 'Ve ma kane salatuhum indel beyti illa mukaen ve tasdiyeh, fe zukul azabe bima kuntum tekfurun.', 'Onların,  Beyt\'in[1] yanındaki salatları[2],  ıslık çalmaktan ve el çırpmaktan başka bir şey değildir. Öyleyse küfrünüzden dolayı azabı tadın.', 'وما كان صلاتهم عند البيت الا مكا وتصدية فذوقوا العذاب بما كنتم تكفرون'),
(1196, 8, 36, 'اِنَّ الَّذ۪ينَ كَفَرُوا يُنْفِقُونَ اَمْوَالَهُمْ لِيَصُدُّوا عَنْ سَب۪يلِ اللّٰهِۜ فَسَيُنْفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَۜ وَالَّذ۪ينَ كَفَرُٓوا اِلٰى جَهَنَّمَ يُحْشَرُونَۙ', 'İnnellezine keferu yunfikune emvalehum li yesuddu an sebilillah, fe seyunfikuneha summe tekunu aleyhim hasreten summe yuglebun, vellezine keferu ila cehenneme yuhşerun.', 'Gerçeği yalanlayan nankörler,  Allah yolundan alıkoymak için mallarını harcarlar ve harcayacaklar da. Sonra,  bu kendilerine pişmanlık olacak ve sonra mağlup olacaklar. Kafirler Cehennem\'de toplanacaklardır.', 'ان الذين كفروا ينفقون امولهم ليصدوا عن سبيل الله فسينفقونها ثم تكون عليهم حسرة ثم يغلبون والذين كفروا الي جهنم يحشرون'),
(1197, 8, 37, 'لِيَم۪يزَ اللّٰهُ الْخَب۪يثَ مِنَ الطَّيِّبِ وَيَجْعَلَ الْخَب۪يثَ بَعْضَهُ عَلٰى بَعْضٍ فَيَرْكُمَهُ جَم۪يعاً فَيَجْعَلَهُ ف۪ي جَهَنَّمَۜ اُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ۟', 'Li yemizallahul habise minet tayyibi ve yec\'alel habise ba\'dahu ala ba\'dın fe yerkumehu cemian fe yec\'alehu fi cehennem, ulaike humul hasirun.', 'Ki Allah,  pis olanı temiz olandan ayırsın,  pis olanları birbirinin üzerine koyup,  hepsini bir araya getirsin,  sonra hepsini Cehennem\'e doldursun. İşte onlar hüsrana uğrayanlardır.', 'ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه علي بعض فيركمه جميعا فيجعله في جهنم اوليك هم الخسرون'),
(1198, 8, 38, 'قُلْ لِلَّذ۪ينَ كَفَرُٓوا اِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَۚ وَاِنْ يَعُودُوا فَقَدْ مَضَتْ سُنَّتُ الْاَوَّل۪ينَ', 'Kul lillezine keferu in yentehu yugfer lehum ma kad selef, ve in yeudu fe kad madat sunnetul evvelin.', 'Kafirlere de ki: Eğer vazgeçerlerse geçmişte yaptıkları bağışlanır. Eğer tekrar dönerlerse,  evvelkilerin başına gelenler ortadadır.', 'قل للذين كفروا ان ينتهوا يغفر لهم ما قد سلف وان يعودوا فقد مضت سنت الاولين'),
(1199, 8, 39, 'وَقَاتِلُوهُمْ حَتّٰى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدّ۪ينُ كُلُّهُ لِلّٰهِۚ فَاِنِ انْتَهَوْا فَاِنَّ اللّٰهَ بِمَا يَعْمَلُونَ بَص۪يرٌ', 'Ve katiluhum hatta la tekune fitnetun ve yekuned dinu kulluhu lillahi, fe inintehev fe innallahe bima ya\'melune basir.', 'Fitne[1] kalmayıp,  din[2] tamamıyla Allah\'ın oluncaya kadar onlarla savaşın. Eğer vazgeçerlerse kuşkusuz Allah onların ne yaptığını görmektedir.', 'وقتلوهم حتي لا تكون فتنة ويكون الدين كله لله فان انتهوا فان الله بما يعملون بصير'),
(1200, 8, 40, 'وَاِنْ تَوَلَّوْا فَاعْلَمُٓوا اَنَّ اللّٰهَ مَوْلٰيكُمْۜ نِعْمَ الْمَوْلٰى وَنِعْمَ النَّص۪يرُ', 'Ve in tevellev fa\'lemu ennallahe mevlakum, ni\'mel mevla ve ni\'men nasir.', 'Eğer yüz çevirirlerse,  artık bilin ki Allah sizin mevlanızdır.[1] O,  ne güzel mevla,  ne güzel yardımcıdır.', 'وان تولوا فاعلموا ان الله موليكم نعم المولي ونعم النصير'),
(1201, 8, 41, 'وَاعْلَمُٓوا اَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَاَنَّ لِلّٰهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينِ وَابْنِ السَّب۪يلِۙ اِنْ كُنْتُمْ اٰمَنْتُمْ بِاللّٰهِ وَمَٓا اَنْزَلْنَا عَلٰى عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Va\'lemu ennema ganimtum min şey\'in fe enne lillahi humusehu ve lir resuli ve li zil kurba vel yetama vel mesakini vebnis sebili in kuntum amentum billahi ve ma enzelna ala abdina yevmel furkani yevmettekal cem\'an, vallahu ala kulli şey\'in kadir.', 'Eğer Allah\'a,  Hakk ile Batıl\'ın birbirinden ayrıldığı gün; iki ordunun karşı karşıya geldiği günde,  kulumuza indirdiğimize inanıyorsanız,  bilin ki: Ganimet olarak ele geçirdiklerinizin beşte biri Allah\'ın ve Resulü\'nün,  yakınların[1],  yetimlerin,  düşkünlerin,  yol oğlunundur[2]. Allah,  Her Şeye Güç Yetirendir.', 'واعلموا انما غنمتم من شي فان لله خمسه وللرسول ولذي القربي واليتمي والمسكين وابن السبيل ان كنتم امنتم بالله وما انزلنا علي عبدنا يوم الفرقان يوم التقي الجمعان والله علي كل شي قدير'),
(1202, 8, 42, 'اِذْ اَنْتُمْ بِالْعُدْوَةِ الدُّنْيَا وَهُمْ بِالْعُدْوَةِ الْقُصْوٰى وَالرَّكْبُ اَسْفَلَ مِنْكُمْۜ وَلَوْ تَوَاعَدْتُمْ لَاخْتَلَفْتُمْ فِي الْم۪يعَادِۙ وَلٰكِنْ لِيَقْضِيَ اللّٰهُ اَمْراً كَانَ مَفْعُولاًۙ لِيَهْلِكَ مَنْ هَلَكَ عَنْ بَيِّنَةٍ وَيَحْيٰى مَنْ حَيَّ عَنْ بَيِّنَةٍۜ وَاِنَّ اللّٰهَ لَسَم۪يعٌ عَل۪يمٌۙ', 'İz entum bil udvetid dunya ve hum bil udvetil kusva verrekbu esfele minkum, ve lev tevaadtum lahteleftum fil miadi ve lakin li yakdiyallahu emren kane mef\'ulen li yehlike men heleke an beyyinetin ve yahya men hayye an beyyineh, ve innallahe le semi\'un alim.', 'Sizin vadinin bir ucunda,  onların da öteki ucunda ve kervanın da sizden aşağıda olduğu o gün,  eğer bilinen bir yerde buluşmak hususunda sözleşmiş olsaydınız dahi,  anlaşmazlığa düşerdiniz. Ama Allah,  gerçekleştirilmesi gereken bir işi yaptı; yok olan,  apaçık bir kanıtla yok olsun,  yaşayan da apaçık bir kanıtla yaşasın diye. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'اذ انتم بالعدوة الدنيا وهم بالعدوة القصوي والركب اسفل منكم ولو تواعدتم لاختلفتم في الميعد ولكن ليقضي الله امرا كان مفعولا ليهلك من هلك عن بينة ويحيي من حي عن بينة وان الله لسميع عليم'),
(1203, 8, 43, 'اِذْ يُر۪يكَهُمُ اللّٰهُ ف۪ي مَنَامِكَ قَل۪يلاًۜ وَلَوْ اَرٰيكَهُمْ كَث۪يراً لَفَشِلْتُمْ وَلَتَنَازَعْتُمْ فِي الْاَمْرِ وَلٰكِنَّ اللّٰهَ سَلَّمَۜ اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'İz yurikehumullahu fi menamike kalilen, ve lev erakehum kesiren le feşiltum ve le tenaza\'tum fil emri ve lakinnallahe sellem, innehu alimun bi zatis sudur.', 'Hani Allah,  onları sana uykunda az göstermişti. Eğer O,  onları sana çok gösterseydi,  tedirgin olup ne yapacağınız hususunda anlaşmazlığa düşerdiniz. Fakat Allah,  sizi bu tehlikeden korudu. Zira O,  göğüslerde olanları en iyi bilendir.', 'اذ يريكهم الله في منامك قليلا ولو اريكهم كثيرا لفشلتم ولتنزعتم في الامر ولكن الله سلم انه عليم بذات الصدور'),
(1204, 8, 44, 'وَاِذْ يُر۪يكُمُوهُمْ اِذِ الْتَقَيْتُمْ ف۪ٓي اَعْيُنِكُمْ قَل۪يلاً وَيُقَلِّلُكُمْ ف۪ٓي اَعْيُنِهِمْ لِيَقْضِيَ اللّٰهُ اَمْراً كَانَ مَفْعُولاًۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ۟', 'Ve iz yurikumuhum iziltekaytum fi a\'yunikum kalilen ve yukallilukum fi a\'yunihim li yakdıyallahu emren kane mef\'ula, ve ilallahi turceul umur.', 'Karşı karşıya geldiğinizde,  Allah onları sizin gözünüzde,  sizi de onların gözünde sayıca azmış gibi gösteriyordu ki takdir edilen işi yerine getirsin. Bütün işler yalnızca Allah\'a döndürülür.', 'واذ يريكموهم اذ التقيتم في اعينكم قليلا ويقللكم في اعينهم ليقضي الله امرا كان مفعولا والي الله ترجع الامور'),
(1205, 8, 45, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا لَق۪يتُمْ فِئَةً فَاثْبُتُوا وَاذْكُرُوا اللّٰهَ كَث۪يراً لَعَلَّكُمْ تُفْلِحُونَۚ', 'Ya eyyuhellezine amenu iza lekitum fieten fesbutu vezkurullahe kesiren leallekum tuflihun.', 'Ey iman edenler! Bir toplulukla karşılaştığınız zaman,  kararlı ve dirençli olun ve Allah\'ı çok anın ki kurtuluşa eresiniz.', 'يايها الذين امنوا اذا لقيتم فية فاثبتوا واذكروا الله كثيرا لعلكم تفلحون'),
(1206, 8, 46, 'وَاَط۪يعُوا اللّٰهَ وَرَسُولَهُ وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ ر۪يحُكُمْ وَاصْبِرُواۜ اِنَّ اللّٰهَ مَعَ الصَّابِر۪ينَۚ', 'Ve etiullahe ve resulehu ve la tenazeu fe tefşelu ve tezhebe rihukum vasbiru, innallahe meas sabirin.', 'Allah\'a ve Resulüne itaat edin.[1] Birbirinizle çekişmeyin. Sonra zaafa düşüp zayıflarsınız. Sabredin. Kuşkusuz Allah,  sabredenlerle beraberdir.', 'واطيعوا الله ورسوله ولا تنزعوا فتفشلوا وتذهب ريحكم واصبروا ان الله مع الصبرين'),
(1207, 8, 47, 'وَلَا تَكُونُوا كَالَّذ۪ينَ خَرَجُوا مِنْ دِيَارِهِمْ بَطَراً وَرِئَٓاءَ النَّاسِ وَيَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِۜ وَاللّٰهُ بِمَا يَعْمَلُونَ مُح۪يطٌ', 'Ve la tekunu kellezine harecu min diyarihim bataran ve riaen nasi ve yasuddune an sebilillah, vallahu bima ya\'melune muhit.', 'Çalım satarak,  insanlara gösteriş yaparak ve Allah\'ın yolundan alıkoyarak yurtlarından çıkanlar gibi olmayın. Allah,  onların yaptıklarını çepeçevre kuşatmıştır.', 'ولا تكونوا كالذين خرجوا من ديرهم بطرا وريا الناس ويصدون عن سبيل الله والله بما يعملون محيط'),
(1208, 8, 48, 'وَاِذْ زَيَّنَ لَهُمُ الشَّيْطَانُ اَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَاِنّ۪ي جَارٌ لَكُمْۚ فَلَمَّا تَرَٓاءَتِ الْفِئَتَانِ نَكَصَ عَلٰى عَقِبَيْهِ وَقَالَ اِنّ۪ي بَر۪ٓيءٌ  مِنْكُمْ اِنّ۪ٓي اَرٰى مَا لَا تَرَوْنَ اِنّ۪ٓي اَخَافُ اللّٰهَۜ وَاللّٰهُ شَد۪يدُ الْعِقَابِ۟', 'Ve iz zeyyene lehumuş şeytanu a\'malehum ve kale la galibe lekumul yevme minen nasi ve inni carun lekum, fe lemma teraetil fietani nekesa ala akıbeyhi ve kale inni beriun minkum inni era ma la terevne inni ehafullah, vallahu şedidul ıkab.', 'Hani,  şeytan[1] onlara yaptıkları işi süslü gösterip: \"Bugün,  sizi hiçbir insan topluluğu yenemez,  ben de muhakkak sizin yardımcınızım.\" dedi. Fakat iki ordu karşılaşınca geri döndü ve \"Ben sizden uzağım,  ben sizin görmediğinizi görmekteyim,  ben Allah\'tan korkarım. Zira Allah\'ın azabı çok çetindir.\" dedi.', 'واذ زين لهم الشيطن اعملهم وقال لا غالب لكم اليوم من الناس واني جار لكم فلما ترات الفيتان نكص علي عقبيه وقال اني بري منكم اني اري ما لا ترون اني اخاف الله والله شديد العقاب'),
(1209, 8, 49, 'اِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ غَرَّ هٰٓؤُ۬لَٓاءِ د۪ينُهُمْۜ وَمَنْ يَتَوَكَّلْ عَلَى اللّٰهِ فَاِنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ', 'İz yekulul munafikune vellezine fi kulubihim maradun garrehaulai dinuhum, ve men yetevekkel alallahi fe innallahe azizun hakim.', 'Münafıklar,  o kalplerinde hastalık bulunanlar: \"Bunları,  dinleri aldatmış.\" diyorlardı. Oysa kim Allah\'a tevekkül[1] ederse Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'اذ يقول المنفقون والذين في قلوبهم مرض غر هولا دينهم ومن يتوكل علي الله فان الله عزيز حكيم'),
(1210, 8, 50, 'وَلَوْ تَرٰٓى اِذْ يَتَوَفَّى الَّذ۪ينَ كَفَرُواۙ الْمَلٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَاَدْبَارَهُمْۚ وَذُوقُوا عَذَابَ الْحَر۪يقِ', 'Ve lev tera iz yeteveffellezine keferul melaiketu yadrıbune vucuhehum ve edbarehum, ve zuku azabel harik.', 'Şayet görüp tanıklık etseydin[1] eğer! Melekler,  Kafirlerin canlarını alırken,  yüzlerine ve sırtlarına vuruyorlar[2] ve \"Kavurucu azabı tadın.\" diyorlar.', 'ولو تري اذ يتوفي الذين كفروا المليكة يضربون وجوههم وادبرهم وذوقوا عذاب الحريق'),
(1211, 8, 51, 'ذٰلِكَ بِمَا قَدَّمَتْ اَيْد۪يكُمْ وَاَنَّ اللّٰهَ لَيْسَ بِظَلَّامٍ لِلْعَب۪يدِۙ', 'Zalike bima kaddemet eydikum ve ennallahe leyse bi zallamin lil abid.', 'İşte bu,  kendi ellerinizle yaptıklarınızın karşılığıdır,  yoksa Allah kullarına asla haksızlık etmez.', 'ذلك بما قدمت ايديكم وان الله ليس بظلم للعبيد'),
(1212, 8, 52, 'كَدَأْبِ اٰلِ فِرْعَوْنَۙ وَالَّذ۪ينَ مِنْ قَبْلِهِمْۜ كَفَرُوا بِاٰيَاتِ اللّٰهِ فَاَخَذَهُمُ اللّٰهُ بِذُنُوبِهِمْۜ اِنَّ اللّٰهَ قَوِيٌّ شَد۪يدُ الْعِقَابِ', 'Ke de\'bi ali fir\'avne vellezine min kablihim, keferu bi ayatillahi fe ehazehumullahu bi zunubihim, innallahe kaviyyun şedidul ıkab.', 'Tıpkı Firavuncuların ve onlardan öncekilerin durumu gibi. Allah\'ın ayetlerini yalanlamışlardı. Allah da onları,  suçları yüzünden yakalamıştı. Allah,  Mutlak Güç Sahibi\'dir,  Cezalandırması Çok Şiddetli Olan\'dır.', 'كداب ال فرعون والذين من قبلهم كفروا بايت الله فاخذهم الله بذنوبهم ان الله قوي شديد العقاب'),
(1213, 8, 53, 'ذٰلِكَ بِاَنَّ اللّٰهَ لَمْ يَكُ مُغَيِّراً نِعْمَةً اَنْعَمَهَا عَلٰى قَوْمٍ حَتّٰى يُغَيِّرُوا مَا بِاَنْفُسِهِمْۙ وَاَنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌۙ', 'Zalike biennallahe lem yeku mugayyiren ni\'meten en\'ameha ala kavmin hatta yugayyiru ma bi enfusihim ve ennallahe semiun alim.', 'Çünkü bir halk kendisini değiştirmedikçe,  Allah onlara verdiği nimeti[1] değiştirecek değildir. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'ذلك بان الله لم يك مغيرا نعمة انعمها علي قوم حتي يغيروا ما بانفسهم وان الله سميع عليم'),
(1214, 8, 54, 'كَدَأْبِ اٰلِ فِرْعَوْنَۙ وَالَّذ۪ينَ مِنْ قَبْلِهِمْۜ كَذَّبُوا بِاٰيَاتِ رَبِّهِمْۚ فَاَهْلَكْنَاهُمْ بِذُنُوبِهِمْ وَاَغْرَقْـنَٓا اٰلَ فِرْعَوْنَۚ وَكُلٌّ كَانُوا ظَالِم۪ينَ', 'Ke de\'bi ali fir\'avne vellezine min kablihim, kezzebu biayati rabbihim, fe ehleknahum bi zunubihim ve agrakna ale fir\'avn, ve kullun kanu zalimin.', 'Tıpkı Firavuncuların ve onlardan öncekilerin durumu gibi. Rabb\'lerinin ayetlerini yalanlamışlardı da Biz de suçlarından dolayı onları mahvetmiş ve Firavuncuları suda boğmuştuk. Hepsi de zalim kimselerdi.', 'كداب ال فرعون والذين من قبلهم كذبوا بايت ربهم فاهلكنهم بذنوبهم واغرقنا ال فرعون وكل كانوا ظلمين'),
(1215, 8, 55, 'اِنَّ شَرَّ الدَّوَٓابِّ عِنْدَ اللّٰهِ الَّذ۪ينَ كَفَرُوا فَهُمْ لَا يُؤْمِنُونَۚ', 'İnne şerred devabbi indallahillezine keferu fe hum la yu\'minun.', 'Allah katında canlıların en şerlisi[1],  Kafirlerdir[2]. Artık onlar inanmazlar;', 'ان شر الدواب عند الله الذين كفروا فهم لا يومنون'),
(1216, 8, 56, 'اَلَّذ۪ينَ عَاهَدْتَ مِنْهُمْ ثُمَّ يَنْقُضُونَ عَهْدَهُمْ ف۪ي كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', 'Ellezine ahedte minhum summe yenkudune ahdehum fi kulli merretin ve hum la yettekun.', 'Onlar,  kendileriyle antlaşma yaptığın halde,  her defasında hiç çekinmeden antlaşmalarını bozan kimselerdir.', 'الذين عهدت منهم ثم ينقضون عهدهم في كل مرة وهم لا يتقون'),
(1217, 8, 57, 'فَاِمَّا تَثْقَفَنَّهُمْ فِي الْحَرْبِ فَشَرِّدْ بِهِمْ مَنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', 'Fe imma teskafennehum fil harbi feşerrid bihim men halfehum leallehum yezzekkerun.', 'Eğer savaşta onları yakalarsan,  geride kalanlara ders olacak şekilde onları darmadağın et. Belki akıllarını başlarına alırlar.', 'فاما تثقفنهم في الحرب فشرد بهم من خلفهم لعلهم يذكرون'),
(1218, 8, 58, 'وَاِمَّا تَخَافَنَّ مِنْ قَوْمٍ خِيَانَةً فَانْبِذْ اِلَيْهِمْ عَلٰى سَوَٓاءٍۜ اِنَّ اللّٰهَ لَا يُحِبُّ الْخَٓائِن۪ينَ۟', 'Ve imma tehafenne min kavmin hiyaneten fenbiz ileyhim ala sevain, innallahe la yuhıbbul hainin.', 'Eğer bir halkın ihanetinden endişe edersen,  onlarla aynı şekilde[1] anlaşmayı boz. Kuşkusuz Allah,  hainlik yapanları sevmez.', 'واما تخافن من قوم خيانة فانبذ اليهم علي سوا ان الله لا يحب الخاينين'),
(1219, 8, 59, 'وَلَا يَحْسَبَنَّ الَّذ۪ينَ كَفَرُوا سَبَقُواۜ اِنَّهُمْ لَا يُعْجِزُونَ', 'Ve la yahsebennellezine keferu sebeku, innehum la yu\'cizun.', 'Kafirler kendilerinden vazgeçildiğini sanmasınlar. Onlar,  Bizi aciz bırakamazlar.', 'ولا يحسبن الذين كفروا سبقوا انهم لا يعجزون'),
(1220, 8, 60, 'وَاَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ تُرْهِبُونَ بِه۪ عَدُوَّ اللّٰهِ وَعَدُوَّكُمْ وَاٰخَر۪ينَ مِنْ دُونِهِمْۚ لَا تَعْلَمُونَهُمْۚ اَللّٰهُ يَعْلَمُهُمْۜ وَمَا تُنْفِقُوا مِنْ شَيْءٍ ف۪ي سَب۪يلِ اللّٰهِ يُوَفَّ اِلَيْكُمْ وَاَنْتُمْ لَا تُظْلَمُونَ', 'Ve eıddu lehum mesteta\'tum min kuvvetin ve min rıbatil hayli turhibune bihi aduvvallahi ve aduvvekum ve aharine min dunihim, la ta\'lemunehum, allahu ya\'lemuhum, ve ma tunfiku min şey\'in fi sebilillahi yuveffe ileykum ve entum la tuzlemun.', 'Siz de onlara karşı gücünüzün yettiği kadar güç ve savaş atları[1] hazırlayın ki,  bununla Allah\'ın ve sizin düşmanınızı ve onların dışındaki sizin bilmeyip,  Allah\'ın bildiği düşmanları korkutasınız. Allah yolunda her ne harcarsanız,  size tam olarak ödenir. Ve hiçbir haksızlığa uğratılmazsınız.', 'واعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم واخرين من دونهم لا تعلمونهم الله يعلمهم وما تنفقوا من شي في سبيل الله يوف اليكم وانتم لا تظلمون'),
(1221, 8, 61, 'وَاِنْ جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى اللّٰهِۜ اِنَّهُ هُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve in cenehu lis selmi fecnah leha ve tevekkel alallah, innehu huves semiul alim.', 'Eğer onlar barışa yanaşırlarsa,  sen de yanaş ve Allah\'a tevekkül[1] et. Kuşkusuz O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'وان جنحوا للسلم فاجنح لها وتوكل علي الله انه هو السميع العليم'),
(1222, 8, 62, 'وَاِنْ يُر۪يدُٓوا اَنْ يَخْدَعُوكَ فَاِنَّ حَسْبَكَ اللّٰهُۜ هُوَ الَّـذ۪ٓي اَيَّدَكَ بِنَصْرِه۪ وَبِالْمُؤْمِن۪ينَۙ', 'Ve in yuridu en yahdeuke feinne hasbekallah, huvellezi eyyedeke bi nasrihi ve bilmu\'minin.', 'Eğer sana hile yapmak isterlerse,  şunu bil ki Allah sana yeter. O,  seni yardımı ile ve Mü\'minlerle destekledi.', 'وان يريدوا ان يخدعوك فان حسبك الله هو الذي ايدك بنصره وبالمومنين'),
(1223, 8, 63, 'وَاَلَّفَ بَيْنَ قُلُوبِهِمْۜ لَوْ اَنْفَقْتَ مَا فِي الْاَرْضِ جَم۪يعاً مَٓا اَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلٰكِنَّ اللّٰهَ اَلَّفَ بَيْنَهُمْۜ اِنَّهُ عَز۪يزٌ حَك۪يمٌ', 'Ve ellefe beyne kulubihim, lev enfakte ma fil ardı cemian ma ellefte beyne kulubihim ve lakinnallahe ellefe beynehum, innehu azizun hakim.', 'Ve onların kalplerini uzlaştırdı. Eğer yeryüzündeki her şeyi infak[1] etseydin yine de onların kalplerini kaynaştıramazdın. Fakat Allah,  onları kaynaştırdı. Kuşkusuz O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'والف بين قلوبهم لو انفقت ما في الارض جميعا ما الفت بين قلوبهم ولكن الله الف بينهم انه عزيز حكيم'),
(1224, 8, 64, 'يَٓا اَيُّهَا النَّبِيُّ حَسْبُكَ اللّٰهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِن۪ينَ۟', 'Ya eyyuhennebiyyu hasbukallahu ve menittebeake minel mu\'minin.', 'Ey Nebi! Allah,  sana ve sana uyan mü\'minlere yeter.', 'يايها النبي حسبك الله ومن اتبعك من المومنين'),
(1225, 8, 65, 'يَٓا اَيُّهَا النَّبِيُّ حَرِّضِ الْمُؤْمِن۪ينَ عَلَى الْقِتَالِۜ اِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِۚ وَاِنْ يَكُنْ مِنْكُمْ مِائَةٌ يَغْلِبُٓوا اَلْفاً مِنَ الَّذ۪ينَ كَفَرُوا بِاَنَّهُمْ قَوْمٌ لَا يَفْقَهُونَ', 'Ya eyyuhen nebiyyu harridıl mu\'minine alel kıtal, in yekun minkum işrune sabirune yaglibu mieteyn, ve in yekun minkum mietun yaglibu elfen minellezine keferu bi ennehum kavmun la yefkahun.', 'Ey Nebi! Mü\'minleri savaşmaya cesaretlendir. Eğer sizden sabreden[1] yirmi kişi bulunursa,  iki yüz kişiye galip gelir. Eğer sizden yüz kişi bulunursa,  Kafirlerden bin kişiye galip gelir. Çünkü onlar gerçekten anlamaz[2] bir halktır.', 'يايها النبي حرض المومنين علي القتال ان يكن منكم عشرون صبرون يغلبوا مايتين وان يكن منكم ماية يغلبوا الفا من الذين كفروا بانهم قوم لا يفقهون'),
(1226, 8, 66, 'اَلْـٰٔنَ خَفَّفَ اللّٰهُ عَنْكُمْ وَعَلِمَ اَنَّ ف۪يكُمْ ضَعْفاًۜ فَاِنْ يَكُنْ مِنْكُمْ مِائَةٌ صَابِرَةٌ يَغْلِبُوا مِائَتَيْنِۚ وَاِنْ يَكُنْ مِنْكُمْ اَلْفٌ يَغْلِبُٓوا اَلْفَيْنِ بِاِذْنِ اللّٰهِۜ وَاللّٰهُ مَعَ الصَّابِر۪ينَ', 'El\'ane haffefallahu ankum ve alime enne fikum da\'fa, fe in yekun minkum mietun sabiretun yaglibu mieteyn, ve in yekun minkum elfun yaglibu elfeyni bi iznillah, vallahu meas sabirin.', 'Şimdi Allah,  yükünüzü hafifletti. Çünkü sizde bir zayıflık olduğunu bilmektedir. Yine de,  eğer sizden sabırlı yüz kişi bulunursa iki yüz kişiye galip gelir. Eğer sizden bin kişi olursa Allah\'ın izni ile[1] iki bin kişiye galip gelir. Allah,  sabredenlerle beraberdir.', 'الن خفف الله عنكم وعلم ان فيكم ضعفا فان يكن منكم ماية صابرة يغلبوا مايتين وان يكن منكم الف يغلبوا الفين باذن الله والله مع الصبرين'),
(1227, 8, 67, 'مَا كَانَ لِنَبِيٍّ اَنْ يَكُونَ لَـهُٓ اَسْرٰى حَتّٰى يُثْخِنَ فِي الْاَرْضِۜ تُر۪يدُونَ عَرَضَ الدُّنْيَاۗ وَاللّٰهُ يُر۪يدُ الْاٰخِرَةَۜ وَاللّٰهُ عَز۪يزٌ حَك۪يمٌ', 'Ma kane li nebiyyin en yekune lehu esra hatta yushıne fil ard, turidune aradad dunya, vallahu yuridul ahıreh, vallahu azizun hakim.', 'Hiçbir nebiye,  yeryüzünde düşmana üstünlük sağlayıncaya kadar,  esir almak[1] yaraşmaz. Siz geçici dünya malını istiyorsunuz,  oysa Allah ahireti istiyor. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ما كان لنبي ان يكون له اسري حتي يثخن في الارض تريدون عرض الدنيا والله يريد الاخرة والله عزيز حكيم'),
(1228, 8, 68, 'لَوْلَا كِتَابٌ مِنَ اللّٰهِ سَبَقَ لَمَسَّكُمْ ف۪يمَٓا اَخَذْتُمْ عَذَابٌ عَظ۪يمٌ', 'Lev la kitabun minallahi sebeka le messekum fima ehaztum azabun azim.', 'Eğer Allah tarafından önceden bir kitap[1] olmasaydı,  aldığınız şeyden dolayı size mutlaka büyük bir azap dokunurdu.', 'لولا كتب من الله سبق لمسكم فيما اخذتم عذاب عظيم'),
(1229, 8, 69, 'فَكُلُوا مِمَّا غَنِمْتُمْ حَلَالاً طَيِّباًۘ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ۟', 'Fe kulu mimma ganimtum halalen tayyiben vettekullah, innallahe gafurun rahim.', 'Artık elde ettiğiniz ganimetten,  helal ve temiz olarak yiyin ve Allah için takvalı olun. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'فكلوا مما غنمتم حللا طيبا واتقوا الله ان الله غفور رحيم'),
(1230, 8, 70, 'يَٓا اَيُّهَا النَّبِيُّ قُلْ لِمَنْ ف۪ٓي اَيْد۪يكُمْ مِنَ الْاَسْرٰٓىۙ اِنْ يَعْلَمِ اللّٰهُ ف۪ي قُلُوبِكُمْ خَيْراً يُؤْتِكُمْ خَيْراً مِمَّٓا اُخِذَ مِنْكُمْ وَيَغْفِرْ لَكُمْۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Ya eyyuhen nebiyyu kul li men fi eydikum minel esra in ya\'lemillahu fi kulubikum hayren yu\'tikum hayren mimma uhıze minkum ve yagfirlekum, vallahu gafurun rahim.', 'Ey Nebi! Elinizdeki esirlere de ki: \"Eğer Allah kalplerinizde bir hayır olduğunu bilirse[1],  size,  sizden alınandan daha hayırlısını verir ve sizi bağışlar.\" Allah\'ın Rahmeti Bol\'dur,  Kesintisiz\'dir.', 'يايها النبي قل لمن في ايديكم من الاسري ان يعلم الله في قلوبكم خيرا يوتكم خيرا مما اخذ منكم ويغفر لكم والله غفور رحيم'),
(1231, 8, 71, 'وَاِنْ يُر۪يدُوا خِيَانَتَكَ فَقَدْ خَانُوا اللّٰهَ مِنْ قَبْلُ فَاَمْكَنَ مِنْهُمْۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ve in yuridu hıyaneteke fe kad hanullahe min kablu fe emkene minhum, vallahu alimun hakim.', 'Eğer sana ihanet etmek isterlerse; daha önce Allah\'a da ihanet etmişlerdi. Allah,  onlara karşı sana imkan verdi. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'وان يريدوا خيانتك فقد خانوا الله من قبل فامكن منهم والله عليم حكيم'),
(1232, 8, 72, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ ف۪ي سَب۪يلِ اللّٰهِ وَالَّذ۪ينَ اٰوَوْا وَنَصَرُٓوا اُو۬لٰٓئِكَ بَعْضُهُمْ اَوْلِيَٓاءُ بَعْضٍۜ وَالَّذ۪ينَ اٰمَنُوا وَلَمْ يُهَاجِرُوا مَا لَكُمْ مِنْ وَلَايَتِهِمْ مِنْ شَيْءٍ حَتّٰى يُهَاجِرُواۚ وَاِنِ اسْتَنْصَرُوكُمْ فِي الدّ۪ينِ فَعَلَيْكُمُ النَّصْرُ اِلَّا عَلٰى قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ م۪يثَاقٌۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'İnnellezine amenu ve haceru ve cahedu bi emvalihim ve enfusihim fi sebilillahi vellezine avev ve nasaru ulaike ba\'duhum evliyau ba\'d, vellezine amenu ve lem yuhaciru ma lekum min velayetihim min şey\'in hatta yuhaciru, ve inistensarukum fid dini fe aleykumun nasru illa ala kavmin beynekum ve beynehum misak, vallahu bima ta\'melune basir.', 'İman edip,  hicret edenler,  malları ve canları ile Allah yolunda cihat edenler,  barındırıp yardım edenler; işte onlar birbirlerinin velileridirler. İman edip de hicret etmeyenlere gelince,  hicret edinceye kadar onların velayetinden[1] size bir şey yoktur. Eğer onlar din hususunda sizden yardım isterlerse,  onlara yardım etmek üzerinize borçtur. Ancak aranızda anlaşma bulunan bir halkın aleyhine olursa,  o bu hükmün dışındadır. Allah,  yaptığınız her şeyi görmektedir.', 'ان الذين امنوا وهاجروا وجهدوا بامولهم وانفسهم في سبيل الله والذين اووا ونصروا اوليك بعضهم اوليا بعض والذين امنوا ولم يهاجروا ما لكم من وليتهم من شي حتي يهاجروا وان استنصروكم في الدين فعليكم النصر الا علي قوم بينكم وبينهم ميثق والله بما تعملون بصير'),
(1233, 8, 73, 'وَالَّذ۪ينَ كَفَرُوا بَعْضُهُمْ اَوْلِيَٓاءُ بَعْضٍۜ اِلَّا تَفْعَلُوهُ تَكُنْ فِتْنَةٌ فِي الْاَرْضِ وَفَسَادٌ كَب۪يرٌۜ', 'Vellezine keferu ba\'duhum evliyau ba\'d, illa tef\'aluhu tekun fitnetun fil ardı ve fesadun kebir.', 'Kafirler birbirlerinin evliyasıdır.[1] Eğer siz de bunu yapmazsanız[2],  yeryüzünde fitne[3] ve büyük kargaşa olur.', 'والذين كفروا بعضهم اوليا بعض الا تفعلوه تكن فتنة في الارض وفساد كبير'),
(1234, 8, 74, 'وَالَّذ۪ينَ اٰمَنُوا وَهَاجَرُوا وَجَاهَدُوا ف۪ي سَب۪يلِ اللّٰهِ وَالَّذ۪ينَ اٰوَوْا وَنَصَرُٓوا اُو۬لٰٓئِكَ هُمُ الْمُؤْمِنُونَ حَقاًّۜ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَر۪يمٌ', 'Vellezine amenu ve haceru ve cahedu fi sebilillahi vellezine avev ve nasaru ulaike humul mu\'minune hakka, lehum magfiretun ve rizkun kerim.', 'İman edip hicret edenler,  Allah yolunda cihat edenler; barındıran ve yardım edenler işte onlar gerçek Mü\'minlerdir. Onlar için bağışlanma ve kerim[1] bir rızık vardır.', 'والذين امنوا وهاجروا وجهدوا في سبيل الله والذين اووا ونصروا اوليك هم المومنون حقا لهم مغفرة ورزق كريم'),
(1235, 8, 75, 'وَالَّذ۪ينَ اٰمَنُوا مِنْ بَعْدُ وَهَاجَرُوا وَجَاهَدُوا مَعَكُمْ فَاُو۬لٰٓئِكَ مِنْكُمْۜ وَاُو۬لُوا الْاَرْحَامِ بَعْضُهُمْ اَوْلٰى بِبَعْضٍ ف۪ي كِتَابِ اللّٰهِۜ اِنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Vellezine amenu min ba\'du ve haceru ve cahedu meakum fe ulaike minkum, ve ulul erhami ba\'duhum evla biba\'dın fi kitabillah, innallahe bi kulli şey\'in alim.', 'Sonradan iman edip de hicret edenler ve sizinle birlikte cihat edenler sizdendir. Allah\'ın Kitap\'ına göre rahim sahipleri[1] önceliklidir. Kuşkusuz Allah,  Her Şeyi Bilen\'dir.', 'والذين امنوا من بعد وهاجروا وجهدوا معكم فاوليك منكم واولوا الارحام بعضهم اولي ببعض في كتب الله ان الله بكل شي عليم'),
(1236, 9, 1, 'بَرَٓاءَةٌ مِنَ اللّٰهِ وَرَسُولِه۪ٓ اِلَى الَّذ۪ينَ عَاهَدْتُمْ مِنَ الْمُشْرِك۪ينَۜ', 'Beraetun minallahi ve resulihi ilellezine ahedtum minel muşrikin .', 'Antlaşma yapılan müşrik[1] kimselere Allah ve Resulünden bir beraettir:[2]', 'براة من الله ورسوله الي الذين عهدتم من المشركين'),
(1237, 9, 2, 'فَس۪يحُوا فِي الْاَرْضِ اَرْبَعَةَ اَشْهُرٍ وَاعْلَمُٓوا اَنَّكُمْ غَيْرُ مُعْجِزِي اللّٰهِۙ وَاَنَّ اللّٰهَ مُخْزِي الْكَافِر۪ينَ', 'Fesihu fil ardı erbeate eşhurin va\'lemu ennekum gayru mu\'cizillahi ve ennallahe muhzil kafirin.', 'Yeryüzünde dört ay[1] daha dolaşın ve bilin ki Allah\'ı aciz bırakamazsınız. Allah,  gerçeği yalanlayan nankörleri rezil edecektir.', 'فسيحوا في الارض اربعة اشهر واعلموا انكم غير معجزي الله وان الله مخزي الكفرين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1238, 9, 3, 'وَاَذَانٌ مِنَ اللّٰهِ وَرَسُولِه۪ٓ اِلَى النَّاسِ يَوْمَ الْحَجِّ الْاَكْبَرِ اَنَّ اللّٰهَ بَر۪ٓيءٌ مِنَ الْمُشْرِك۪ينَۙ وَرَسُولُهُۜ  فَاِنْ تُبْتُمْ فَهُوَ خَيْرٌ لَكُمْۚ وَاِنْ تَوَلَّيْتُمْ فَاعْلَمُٓوا اَنَّكُمْ غَيْرُ مُعْجِزِي اللّٰهِۜ وَبَشِّرِ الَّذ۪ينَ كَفَرُوا بِعَذَابٍ اَل۪يمٍۙ', 'Ve ezanun minallahi ve resulihi ilen nasi yevmel haccıl ekberi ennallahe beriun minel muşrikine ve resuluh , fe in tubtum fe huve hayrun lekum, ve in tevelleytum fa\'lemu ennekum gayru mu\'cizillah , ve beşşirillezine keferu bi azabin elim.', 'Bu Allah ve Resul\'ünden; Hacc-ı Ekber[1] gününde,  insanlara bir duyurudur. Allah ve Resul\'ü müşriklerden uzaktır. Ey müşrikler! Eğer tevbe ederseniz,  bu sizin için hayırlı olandır. Eğer yüz çevirirseniz,  iyi bilin ki Allah\'ı aciz bırakacak değilsiniz. Kafirleri[2] can yakıcı bir azaptan haberdar et.', 'واذن من الله ورسوله الي الناس يوم الحج الاكبر ان الله بري من المشركين ورسوله فان تبتم فهو خير لكم وان توليتم فاعلموا انكم غير معجزي الله وبشر الذين كفروا بعذاب اليم'),
(1239, 9, 4, 'اِلَّا الَّذ۪ينَ عَاهَدْتُمْ مِنَ الْمُشْرِك۪ينَ ثُمَّ لَمْ يَنْقُصُوكُمْ شَيْـٔاً وَلَمْ يُظَاهِرُوا عَلَيْكُمْ اَحَداً فَاَتِمُّٓوا اِلَيْهِمْ عَهْدَهُمْ اِلٰى مُدَّتِهِمْۜ اِنَّ اللّٰهَ يُحِبُّ الْمُتَّق۪ينَ', 'İllellezine ahedtum minel muşrikine summe lem yankusukum şey\'en ve lem yuzahiru aleykum ehaden fe etimmu ileyhim ahdehum ila muddetihim, innallahe yuhıbbul muttekin .', 'Ancak,  kendileriyle yaptığınız antlaşmanın hükümlerine eksiksiz uyan ve size karşı başkalarıyla iş birliğinde bulunmayan müşrikler müstesna. Onlarla antlaşmanın süresini tamamlayın. Allah,  takva[1] sahiplerini sever.', 'الا الذين عهدتم من المشركين ثم لم ينقصوكم شيا ولم يظهروا عليكم احدا فاتموا اليهم عهدهم الي مدتهم ان الله يحب المتقين'),
(1240, 9, 5, 'فَاِذَا انْسَلَخَ الْاَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِك۪ينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍۚ فَاِنْ تَابُوا وَاَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ فَخَلُّوا سَب۪يلَهُمْۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Fe izenselehal eşhurul hurumu faktulul muşrikine haysu vecedtumuhum ve huzuhum vahsuruhum vak\'udu lehum kulle marsad , fe in tabu ve ekamus salate ve atuz zekate fe hallu sebilehum, innallahe gafurun rahim.', 'Haram aylar[1] çıktığı zaman,  artık \"o müşrikleri\" nerede bulursanız öldürün[2],  onları yakalayıp hapsedin,  bütün geçit yerlerinde onları gözetleyin. Eğer tevbe edip[3],  salatı ikame eder[4],  zekatı yaparlarsa[5] diledikleri yolu seçsinler. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'فاذا انسلخ الاشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فان تابوا واقاموا الصلوة واتوا الزكوة فخلوا سبيلهم ان الله غفور رحيم'),
(1241, 9, 6, 'وَاِنْ اَحَدٌ مِنَ الْمُشْرِك۪ينَ اسْتَجَارَكَ فَاَجِرْهُ حَتّٰى يَسْمَعَ كَلَامَ اللّٰهِ ثُمَّ اَبْلِغْهُ مَأْمَنَهُۜ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَا يَعْلَمُونَ۟', 'Ve in ehadun minel muşrikinestecareke fe ecirhu hatta yesmea kelamallahi summe eblighu me\'meneh, zalike bi ennehum kavmun la ya\'lemun.', 'Eğer müşriklerden biri senden korunma isterse,  ona bu korumayı sağla ki Allah\'ın sözlerini öğrenip anlama imkanı bulabilsin. Sonra da onu güven içinde olacağı yere ulaştır. Zira bunlar,  gerçeği bilmeyen bir halktır.', 'وان احد من المشركين استجارك فاجره حتي يسمع كلم الله ثم ابلغه مامنه ذلك بانهم قوم لا يعلمون'),
(1242, 9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِك۪ينَ عَهْدٌ عِنْدَ اللّٰهِ وَعِنْدَ رَسُولِه۪ٓ اِلَّا الَّذ۪ينَ عَاهَدْتُمْ عِنْدَ الْمَسْجِدِ الْحَرَامِۚ فَمَا اسْتَقَامُوا لَكُمْ فَاسْتَق۪يمُوا لَهُمْۜ اِنَّ اللّٰهَ يُحِبُّ الْمُتَّق۪ينَ', 'Keyfe yekunu lil muşrikine ahdun ındallahi ve ınde resulihi illellezine ahedtum ındel mescidil haram, fe mestekamu lekum festekimu lehum, innallahe yuhıbbul muttekin.', 'Yaptıkları antlaşmayı bozan müşriklerin,  Allah ve Resul\'ünün yanında nasıl itibarları olabilir ki? Kendileriyle Mescid-i Haram yanında sözleşme yaptıklarınızın durumu başkadır. Onlar,  size karşı sözlerinde durdukları sürece siz de sözünüzde durun. Allah,  takva sahibi olanları sever.', 'كيف يكون للمشركين عهد عند الله وعند رسوله الا الذين عهدتم عند المسجد الحرام فما استقموا لكم فاستقيموا لهم ان الله يحب المتقين'),
(1243, 9, 8, 'كَيْفَ وَاِنْ يَظْهَرُوا عَلَيْكُمْ لَا يَرْقُبُوا ف۪يكُمْ اِلاًّ وَلَا ذِمَّةًۜ يُرْضُونَكُمْ بِاَفْوَاهِهِمْ وَتَأْبٰى قُلُوبُهُمْۚ وَاَكْثَرُهُمْ فَاسِقُونَۚ', 'Keyfe ve in yazheru aleykum la yerkubu fikum illen ve la zimmeh , yurdunekum bi efvahihim ve te\'ba kulubuhum, ve ekseruhum fasikun.', 'Nasıl olabilir ki? Onlar,  size galip gelmiş olsalar,  hakkınızda ne bir antlaşma ne de bir yükümlülük gözetmezler. Kalben istemedikleri halde,  dilleriyle sizi hoşnut etmeye çalışırlar. Onların çoğu fasıktırlar.[1]', 'كيف وان يظهروا عليكم لا يرقبوا فيكم الا ولا ذمة يرضونكم بافوههم وتابي قلوبهم واكثرهم فسقون'),
(1244, 9, 9, 'اِشْتَرَوْا بِاٰيَاتِ اللّٰهِ ثَمَناً قَل۪يلاً فَصَدُّوا عَنْ سَب۪يلِه۪ۜ اِنَّهُمْ سَٓاءَ مَا كَانُوا يَعْمَلُونَ', 'İşterev bi ayatillahi semenen kalilen fe saddu an sebilih,innehum sae ma kanu ya\'melun.', 'Allah\'ın ayetlerini az bir bedel karşılığında satıp,  O\'nun yolundan alıkoydular. Gerçekten onların yaptıkları çok kötüdür!', 'اشتروا بايت الله ثمنا قليلا فصدوا عن سبيله انهم سا ما كانوا يعملون'),
(1245, 9, 10, 'لَا يَرْقُبُونَ ف۪ي مُؤْمِنٍ اِلاًّ وَلَا ذِمَّةًۜ  وَاُو۬لٰٓئِكَ هُمُ الْمُعْتَدُونَ', 'La yerkubune fi mu\'minin illen ve la zimmeh, ve ulaike humul mu\'tedun.', 'Onlar,  bir mü\'min hakkında ne bir antlaşma ne de bir yükümlülük gözetirler. İşte saldırganlar,  onlardır.', 'لا يرقبون في مومن الا ولا ذمة واوليك هم المعتدون'),
(1246, 9, 11, 'فَاِنْ تَابُوا وَاَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ فَاِخْوَانُكُمْ فِي الدّ۪ينِۜ وَنُفَصِّلُ الْاٰيَاتِ لِقَوْمٍ يَعْلَمُونَ', 'Fe in tabu ve ekamus salate ve atuz zekate fe ıhvanukum fid din , ve nufassılul ayati li kavmin ya\'lemun.', 'Eğer tevbe eder,  \"salatı ikame eder[1] ve zekatı yaparlarsa\"[1],  onlar artık dinde sizin kardeşlerinizdir. Biz,  ayetleri,  bilen bir kavim için böyle ayrıntılı bir şekilde açıklıyoruz.', 'فان تابوا واقاموا الصلوة واتوا الزكوة فاخونكم في الدين ونفصل الايت لقوم يعلمون'),
(1247, 9, 12, 'وَاِنْ نَكَثُٓوا اَيْمَانَهُمْ مِنْ بَعْدِ عَهْدِهِمْ وَطَعَنُوا ف۪ي د۪ينِكُمْ فَقَاتِلُٓوا اَئِمَّةَ الْكُفْرِۙ اِنَّهُمْ لَٓا اَيْمَانَ لَهُمْ لَعَلَّهُمْ يَنْتَهُونَ', 'Ve in nekesu eymanehum min ba\'di ahdihim ve ta\'anu fi dinikum fe katilu eimmetel kufri innehum la eymane lehum leallehum yentehun.', 'Eğer onlar,  antlaşmalarından sonra yeminlerini bozup dininize dil uzatırlarsa[1],  küfrün öncüleri ile savaşın. Çünkü onların yeminleri yok hükmündedir. Umulur ki yaptıklarından vazgeçerler.', 'وان نكثوا ايمنهم من بعد عهدهم وطعنوا في دينكم فقتلوا ايمة الكفر انهم لا ايمن لهم لعلهم ينتهون'),
(1248, 9, 13, 'اَلَا تُقَاتِلُونَ قَوْماً نَكَثُٓوا اَيْمَانَهُمْ وَهَمُّوا بِاِخْرَاجِ الرَّسُولِ وَهُمْ بَدَؤُ۫كُمْ اَوَّلَ مَرَّةٍۜ اَتَخْشَوْنَهُمْۚ فَاللّٰهُ اَحَقُّ اَنْ تَخْشَوْهُ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'E la tukatilune kavmen nekesu eymanehum ve hemmu bi ihracir resuli ve hum bedeukum evvele merreh, e tahşevnehum, fallahu ehakku en tahşevhu in kuntum mu\'minin.', 'Antlarını bozup,  Resul\'ü yurdundan çıkarmaya karar veren ve size karşı saldırıya ilk geçen[1] bir halkla savaşmaz mısınız? Yoksa onlara huşu[2] mu duyuyorsunuz? Eğer gerçekten inananlar iseniz,  Allah\'a daha çok huşu duymanız gerektiğini bilmelisiniz.', 'الا تقتلون قوما نكثوا ايمنهم وهموا باخراج الرسول وهم بدوكم اول مرة اتخشونهم فالله احق ان تخشوه ان كنتم مومنين'),
(1249, 9, 14, 'قَاتِلُوهُمْ يُعَذِّبْهُمُ اللّٰهُ بِاَيْد۪يكُمْ وَيُخْزِهِمْ وَيَنْصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُؤْمِن۪ينَۙ', 'Katiluhum yuazzibhumullahu bi eydikum ve yuhzihim ve yansurkum aleyhim ve yeşfi sudure kavmin mu\'minin.', 'Onlarla savaşın ki Allah sizin ellerinizle onlara azap etsin,  onları rezil etsin,  onlara karşı size yardım etsin. İnanan halkın göğüslerine şifa[1] versin.', 'قتلوهم يعذبهم الله بايديكم ويخزهم وينصركم عليهم ويشف صدور قوم مومنين'),
(1250, 9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْۜ وَيَتُوبُ اللّٰهُ عَلٰى مَنْ يَشَٓاءُۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ve yuzhib gayza kulubihim, ve yetubullahu ala men yeşa\'u, vallahu alimun hakim.', 'Ve onların kalplerindeki öfkeyi gidersin. Allah,  hak edene[1] tevbe nasip eder. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'ويذهب غيظ قلوبهم ويتوب الله علي من يشا والله عليم حكيم'),
(1251, 9, 16, 'اَمْ حَسِبْتُمْ اَنْ تُتْرَكُوا وَلَمَّا يَعْلَمِ اللّٰهُ الَّذ۪ينَ جَاهَدُوا مِنْكُمْ وَلَمْ يَتَّخِذُوا مِنْ دُونِ اللّٰهِ وَلَا رَسُولِه۪ وَلَا الْمُؤْمِن۪ينَ وَل۪يجَةًۜ وَاللّٰهُ خَب۪يرٌ بِمَا تَعْمَلُونَ۟', 'Em hasibtum en tutreku ve lemma ya\'lemillahullezine cahedu minkum ve lem yettehızu min dunillahi ve la resulihi ve lel mu\'minine ve liceh, vallahu habirun bi ma ta\'melun.', 'Yoksa siz,  Allah\'ın içinizden cihat[1] edip,  Allah\'tan,  Resul\'ünden ve Mü\'minlerden başkasını sırdaş edinmeyenleri ortaya çıkarmadan,  kendi halinize bırakılacağınızı mı sandınız? Allah,  yaptığınız her şeyden haberdardır.', 'ام حسبتم ان تتركوا ولما يعلم الله الذين جهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المومنين وليجة والله خبير بما تعملون'),
(1252, 9, 17, 'مَا كَانَ لِلْمُشْرِك۪ينَ اَنْ يَعْمُرُوا مَسَاجِدَ اللّٰهِ شَاهِد۪ينَ عَلٰٓى اَنْفُسِهِمْ بِالْكُفْرِۜ اُو۬لٰٓئِكَ حَبِطَتْ اَعْمَالُهُمْۚ وَفِي النَّارِ هُمْ خَالِدُونَ', 'Ma kane lil muşrikine en ya\'muru mesacidallahi şahidine ala enfusihim bil kufr, ulaike habitat a\'maluhum ve fin nari hum halidun .', 'Kafir olduklarını bildikleri halde,  müşriklerin[1],  Allah\'ın mescitlerini imar etmeye hakları yoktur. Onların bütün yaptıkları boşa gitmiştir. Onlar,  ateşte sürekli kalacaklardır.', 'ما كان للمشركين ان يعمروا مسجد الله شهدين علي انفسهم بالكفر اوليك حبطت اعملهم وفي النار هم خلدون'),
(1253, 9, 18, 'اِنَّمَا يَعْمُرُ مَسَاجِدَ اللّٰهِ مَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَاَقَامَ الصَّلٰوةَ وَاٰتَى الزَّكٰوةَ وَلَمْ يَخْشَ اِلَّا اللّٰهَ فَعَسٰٓى اُو۬لٰٓئِكَ اَنْ يَكُونُوا مِنَ الْمُهْتَد۪ينَ', 'İnnema ya\'muru mesacidallahi men amene billahi vel yevmil ahıri ve ekames salate ve atez zekate ve lem yahşe illallahe fe asa ulaike en yekunu minel muhtedin.', 'Allah\'ın mescitlerini,  ancak Allah \'a ve Ahiret Günü\'ne iman edip,  salatı ikame eden,  zekatı yapan[1] ve Allah\'tan başkasından korkmayan kimseler imar edebilirler. Onların doğru yolu bulanlardan olmaları umulur.', 'انما يعمر مسجد الله من امن بالله واليوم الاخر واقام الصلوة واتي الزكوة ولم يخش الا الله فعسي اوليك ان يكونوا من المهتدين'),
(1254, 9, 19, 'اَجَعَلْتُمْ سِقَايَةَ الْحَٓاجِّ وَعِمَارَةَ الْمَسْجِدِ الْحَرَامِ كَمَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَجَاهَدَ ف۪ي سَب۪يلِ اللّٰهِۜ لَا يَسْتَوُ۫نَ عِنْدَ اللّٰهِۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَۢ', 'E cealtum sikayetel hacci ve ımaretel mescidil harami ke men amene billahi vel yevmil ahıri ve cahede fi sebilillah, la yestevune ındallah, vallahu la yehdil kavmez zalimin.', 'Siz,  hacılara su dağıtmayı ve Mescid-i Haram\'ı imar etmeyi; Allah\'a ve Ahiret Günü\'ne iman edip,  Allah yolunda cihat edenlerle bir mi tuttunuz? Bunlar,  Allah\'ın yanında bir değildir. Allah,  zalim olan halkı doğru yola iletmez.', 'اجعلتم سقاية الحاج وعمارة المسجد الحرام كمن امن بالله واليوم الاخر وجهد في سبيل الله لا يستون عند الله والله لا يهدي القوم الظلمين'),
(1255, 9, 20, 'اَلَّذ۪ينَ اٰمَنُوا وَهَاجَرُوا وَجَاهَدُوا ف۪ي سَب۪يلِ اللّٰهِ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْۙ اَعْظَمُ دَرَجَةً عِنْدَ اللّٰهِۜ وَاُو۬لٰٓئِكَ هُمُ الْفَٓائِزُونَ', 'Ellezine amenu ve haceru ve cahedu fi sebilillahi bi emvalihim ve enfusihim a\'zamu dereceten ındallah ve ulaike humul faizun .', 'İman edip,  hicret eden ve Allah yolunda mallarıyla canlarıyla cihat edenlerin,  Allah katında dereceleri daha üstündür. İşte onlar kazançlı olanlardır.', 'الذين امنوا وهاجروا وجهدوا في سبيل الله بامولهم وانفسهم اعظم درجة عند الله واوليك هم الفايزون'),
(1256, 9, 21, 'يُبَشِّرُهُمْ رَبُّهُمْ بِرَحْمَةٍ مِنْهُ وَرِضْوَانٍ وَجَنَّاتٍ لَهُمْ ف۪يهَا نَع۪يمٌ مُق۪يمٌۙ', 'Yubeşşiruhum rabbuhum bi rahmetin minhu ve rıdvanin ve cennatin lehum fiha naimun mukim.', 'Rabb\'leri,  onları,  Kendi rahmeti,  hoşnutluğu ve içinde tükenmeyen nimetler bulunan Cennetleri ile müjdeliyor.', 'يبشرهم ربهم برحمة منه ورضون وجنت لهم فيها نعيم مقيم'),
(1257, 9, 22, 'خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ اِنَّ اللّٰهَ عِنْدَهُٓ اَجْرٌ عَظ۪يمٌ', 'Halidine fiha ebeda, innallahe indehu ecrun azim .', 'Onlar,  orada sürekli kalıcıdırlar. Kuşkusuz büyük ödül Allah katındadır.', 'خلدين فيها ابدا ان الله عنده اجر عظيم'),
(1258, 9, 23, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُٓوا اٰبَٓاءَكُمْ وَاِخْوَانَكُمْ اَوْلِيَٓاءَ اِنِ اسْتَحَبُّوا الْكُفْرَ عَلَى الْا۪يمَانِۜ وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'Ya eyyuhellezine amenu la tettehızu abaekum ve ihvanekum evliyae inistehabbul kufre alel imani, ve men yetevellehum minkum fe ulaike humuz zalimun.', 'Ey iman edenler! Eğer küfrü[1] imana tercih ediyorlarsa,  babalarınızı ve kardeşlerinizi evliya[2] edinmeyin. Sizden kim onlara dönerse[3],  işte onlar zalimlerin ta kendileridir.', 'يايها الذين امنوا لا تتخذوا اباكم واخونكم اوليا ان استحبوا الكفر علي الايمن ومن يتولهم منكم فاوليك هم الظلمون'),
(1259, 9, 24, 'قُلْ اِنْ كَانَ اٰبَٓاؤُ۬كُمْ وَاَبْنَٓاؤُ۬كُمْ وَاِخْوَانُكُمْ وَاَزْوَاجُكُمْ وَعَش۪يرَتُكُمْ وَاَمْوَالٌۨ اقْتَرَفْتُمُوهَا وَتِجَارَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَـهَٓا اَحَبَّ اِلَيْكُمْ مِنَ اللّٰهِ وَرَسُولِه۪ وَجِهَادٍ ف۪ي سَب۪يلِه۪ فَتَرَبَّصُوا حَتّٰى يَأْتِيَ اللّٰهُ بِاَمْرِه۪ۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْفَاسِق۪ينَ۟', 'Kul in kane abaukum ve ebnaukum ve ıhvanukum ve ezvacukum ve aşiretukum ve emvalunıktereftumuha ve ticaretun tahşevne kesadeha ve mesakinu terdavneha ehabbe ileykum minallahi ve resulihi ve cihadin fi sebilihi fe terabbesu hatta ye\' tiyallahu bi emrih, vallahu la yehdil kavmel fasikin.', 'De ki: \"Eğer babalarınız,  çocuklarınız,  kardeşleriniz,  eşleriniz,  sülaleniz; kazandığınız mallarınız,  kötüye gitmesinden korktuğunuz ticaretiniz,  hoşunuza giden evleriniz,  size; Allah\'tan,  O\'nun Resulü\'nden ve O\'nun yolunda cihad[1] etmekten daha sevimli geliyorsa,  o halde Allah\'ın hükmünün gerçekleşmesini bekleyin.\" Allah,  fasık olan halkı hidayete iletmez.', 'قل ان كان اباوكم وابناوكم واخونكم وازوجكم وعشيرتكم وامول اقترفتموها وتجرة تخشون كسادها ومسكن ترضونها احب اليكم من الله ورسوله وجهاد في سبيله فتربصوا حتي ياتي الله بامره والله لا يهدي القوم الفسقين'),
(1260, 9, 25, 'لَقَدْ نَصَرَكُمُ اللّٰهُ ف۪ي مَوَاطِنَ كَث۪يرَةٍۙ وَيَوْمَ حُنَيْنٍۙ اِذْ اَعْجَبَتْكُمْ كَـثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْـٔاً وَضَاقَتْ عَلَيْكُمُ الْاَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُمْ مُدْبِر۪ينَۚ', 'Lekad nasarakumullahu fi mevatıne kesiretin ve yevme huneynin iz a\'cebetkum kesretukum fe lem tugni ankum şey\'en ve dakat aleykumul ardu bi ma rehubet summe velleytum mudbirine.', 'Ant olsun ki Allah,  size birçok yerde ve Huneyn[1] gününde yardım etmişti. Hani çokluğunuz sizi böbürlendirmişti de size bir faydası olmamıştı. Yeryüzü bütün genişliğine rağmen size dar gelmişti. Sonra da gerisin geri dönüp gitmiştiniz.', 'لقد نصركم الله في مواطن كثيرة ويوم حنين اذ اعجبتكم كثرتكم فلم تغن عنكم شيا وضاقت عليكم الارض بما رحبت ثم وليتم مدبرين'),
(1261, 9, 26, 'ثُمَّ اَنْزَلَ اللّٰهُ سَك۪ينَتَهُ عَلٰى رَسُولِه۪ وَعَلَى الْمُؤْمِن۪ينَ وَاَنْزَلَ جُنُوداً لَمْ تَرَوْهَا وَعَذَّبَ الَّذ۪ينَ كَفَرُواۜ وَذٰلِكَ جَزَٓاءُ الْكَافِر۪ينَ', 'Summe enzelallahu sekinetehu ala resuli-hi ve alel mu\'minine ve enzele cunuden lem terev-ha ve azzebellezine keferu ve zalike cezaul kafirin.', 'Sonra Allah,  Resul\'ünün ve inananların üzerine dinginlik ve güven indirdi. Görmediğiniz ordular indirdi ve gerçeği Kafirlere azap verdi. İşte budur Kafirlerin cezası.', 'ثم انزل الله سكينته علي رسوله وعلي المومنين وانزل جنودا لم تروها وعذب الذين كفروا وذلك جزا الكفرين'),
(1262, 9, 27, 'ثُمَّ يَتُوبُ اللّٰهُ مِنْ بَعْدِ ذٰلِكَ عَلٰى مَنْ يَشَٓاءُۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Summe yetubullahu min ba\'di zalike ala men yeşa\'u, vallahu gafurun rahim.', 'Sonra Allah,  bunun ardından hak edenin[1] tevbesini kabul eder. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ثم يتوب الله من بعد ذلك علي من يشا والله غفور رحيم'),
(1263, 9, 28, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هٰذَاۚ وَاِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْن۪يكُمُ اللّٰهُ مِنْ فَضْلِه۪ٓ اِنْ شَٓاءَۜ اِنَّ اللّٰهَ عَل۪يمٌ حَك۪يمٌ', 'Ya eyyuhellezine amenu innemal muşrikune necesun fe la yakrebul mescidel harame ba\'de amihim haza ve in hıftum ayleten fe sevfe yugnikumullahu min fadlihi in şae, innallahe alimun hakim.', 'Ey iman edenler! Bu Müşrikler ancak necistir[1]. Öyleyse bu yıldan sonra Mescid-i Haram\'a yaklaşmasınlar. Eğer yoksulluktan korkarsanız,  Allah dilerse sizi kendi lütfu ile yakında zengin yapar. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يايها الذين امنوا انما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا وان خفتم عيلة فسوف يغنيكم الله من فضله ان شا ان الله عليم حكيم'),
(1264, 9, 29, 'قَاتِلُوا الَّذ۪ينَ لَا يُؤْمِنُونَ بِاللّٰهِ وَلَا بِالْيَوْمِ الْاٰخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللّٰهُ وَرَسُولُهُ وَلَا يَد۪ينُونَ د۪ينَ الْحَقِّ مِنَ الَّذ۪ينَ اُو۫تُوا الْكِتَابَ حَتّٰى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صَاغِرُونَ۟', 'Katilullezine la yu\'minune billahi ve la bil yevmil ahıri ve la yuharrimune ma harremallahu ve resuluhu ve la yedinune dinel hakkı minellezine utul kitabe hatta yu\'tul cizyete an yedin ve hum sagirun.', 'Kendilerine Kitap verilenlerden,  Allah\'a ve Ahiret Günü\'ne inanmayan; Allah\'ın ve Resulünün haram kıldığını haram saymayan ve Hak Din\'i,  din edinmeyen kimselerle,  üstünlüğünüzü kabul ettirinceye,  kendi elleriyle size belli bir cizye[1] verinceye kadar savaşın.[2]', 'قتلوا الذين لا يومنون بالله ولا باليوم الاخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين اوتوا الكتب حتي يعطوا الجزية عن يد وهم صغرون'),
(1265, 9, 30, 'وَقَالَتِ الْيَهُودُ عُزَيْرٌۨ ابْنُ اللّٰهِ وَقَالَتِ النَّصَارَى الْمَس۪يحُ ابْنُ اللّٰهِۜ ذٰلِكَ قَوْلُهُمْ بِاَفْوَاهِهِمْۚ يُضَاهِؤُ۫نَ قَوْلَ الَّذ۪ينَ كَفَرُوا مِنْ قَبْلُۜ قَاتَلَهُمُ اللّٰهُۘ اَنّٰى يُؤْفَكُونَ', 'Ve kaletil yahudu uzeyrunibnullahi ve kaletin nasarel mesihubnullah zalike kavluhum bi efvahihim yudahiune kavlellezine keferu min kabl katelehumullah enna yu\'fekun.', 'Yahudiler: \"Uzeyr Allah\'ın oğludur.\" dediler; Hıristiyanlar da: \"Mesih Allah\'ın oğludur.\" dediler. Bu,  onların dillerine doladıkları sözlerdir ki daha önce küfredenlerin sözlerine benzetiyorlar. Allah,  kahretsin onları! Nasıl da saptırıyorlar.', 'وقالت اليهود عزير ابن الله وقالت النصري المسيح ابن الله ذلك قولهم بافوههم يضهون قول الذين كفروا من قبل قتلهم الله اني يوفكون'),
(1266, 9, 31, 'اِتَّخَذُٓوا اَحْبَارَهُمْ وَرُهْبَانَهُمْ اَرْبَاباً مِنْ دُونِ اللّٰهِ وَالْمَس۪يحَ ابْنَ مَرْيَمَۚ وَمَٓا اُمِرُٓوا اِلَّا لِيَعْبُدُٓوا اِلٰهاً وَاحِداًۚ لَٓا اِلٰهَ اِلَّا هُوَۜ سُبْحَانَهُ عَمَّا يُشْرِكُونَ', 'İttehazu ahbarehum ve ruhbanehum erbaben min dunillahi vel mesihabne meryem, ve ma umiru illa li ya\'budu ilahen vahida ,la ilahe illa huve, subhanehu amma yuşrikun.', 'Onlar,  Allah\'ın yanı sıra hahamlarını[1],  rahiplerini[2] ve Meryem oğlu Mesih\'i[3] Rabb\'ler edindiler.[4] Oysa bunlar,  bir tek olan İlah\'a kulluk etmekle emrolunmuşlardı. Ondan başka hiçbir ilah yoktur. O,  bunların ortak koştuklarından münezzehtir.[5]', 'اتخذوا احبارهم ورهبنهم اربابا من دون الله والمسيح ابن مريم وما امروا الا ليعبدوا الها وحدا لا اله الا هو سبحنه عما يشركون'),
(1267, 9, 32, 'يُر۪يدُونَ اَنْ يُطْفِؤُ۫ا نُورَ اللّٰهِ بِاَفْوَاهِهِمْ وَيَأْبَى اللّٰهُ اِلَّٓا اَنْ يُتِمَّ نُورَهُ وَلَوْ كَرِهَ الْكَافِرُونَ', 'Yuridune en yutfiu nurallahi bi efvahihim ve ye\'ballahu illa en yutimme nurehu ve lev kerihel kafirun.', 'Allah\'ın nurunu[1] ağızlarıyla söndürmek[2] istiyorlar. Ancak,  Kafirler hoşlanmasalar da Allah kesinlikle nurunu tamamlamaktan başka bir şey istemez.', 'يريدون ان يطفوا نور الله بافوههم ويابي الله الا ان يتم نوره ولو كره الكفرون'),
(1268, 9, 33, 'هُوَ الَّـذ۪ٓي اَرْسَلَ رَسُولَهُ بِالْهُدٰى وَد۪ينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدّ۪ينِ كُلِّه۪ۙ وَلَوْ كَرِهَ الْمُشْرِكُونَ', 'Huvellezi ersele resulehu bil huda ve dinil hakkı li yuzhirehu aled dini kullihi ve lev kerihel muşrikun.', 'Müşrikler hoşlanmasalar da dinini her dinin üstünde açık olarak ortaya koymak üzere Resulünü doğru yol ve gerçek din ile gönderdi.', 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله ولو كره المشركون'),
(1269, 9, 34, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنَّ كَث۪يراً مِنَ الْاَحْبَارِ وَالرُّهْبَانِ لَيَأْكُلُونَ اَمْوَالَ النَّاسِ بِالْبَاطِلِ وَيَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِۜ وَالَّذ۪ينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا ف۪ي سَب۪يلِ اللّٰهِۙ فَبَشِّرْهُمْ بِعَذَابٍ اَل۪يمٍۙ', 'Ya eyyuhellezine amenu inne kesiren minel ahbari ver ruhbani le ye\'kulune emvalen nasi bil batıli ve yasuddune an sebilillah, vellezine yeknizunez zehebe vel fıddate ve la yunfikuneha fi sebilillahi fe beşşirhum bi azabin elim.', 'Ey iman edenler! Doğrusu,  ahbar[1] ve ruhban[1] kimselerin çoğu,  insanların mallarını haksız şekilde yerler. İnsanları Allah\'ın yolundan çevirirler. Altın ve gümüşü biriktirip de onları Allah yolunda harcamayanlar var ya işte onları can yakıcı bir azaptan haberdar et.', 'يايها الذين امنوا ان كثيرا من الاحبار والرهبان لياكلون امول الناس بالبطل ويصدون عن سبيل الله والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله فبشرهم بعذاب اليم'),
(1270, 9, 35, 'يَوْمَ يُحْمٰى عَلَيْهَا ف۪ي نَارِ جَهَنَّمَ فَتُكْوٰى بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْۜ هٰذَا مَا كَنَزْتُمْ لِاَنْفُسِكُمْ فَذُوقُوا مَا كُنْتُمْ تَكْنِزُونَ', 'Yevme yuhma aleyha fi nari cehenneme fe tukva biha cibahuhum ve cunubuhum ve zuhuruhum, haza ma keneztum li enfusikum fe zuku ma kuntum teknizun.', 'O gün,  cehennem ateşinde kızdırılıp; onlarla[1] alınları,  yanları ve sırtları dağlanacak,  \"İşte bunlardır,  kendiniz için biriktirdiğiniz şeyler,  tadın,  biriktirdiğiniz şeylerin azabını.\" denecek.', 'يوم يحمي عليها في نار جهنم فتكوي بها جباههم وجنوبهم وظهورهم هذا ما كنزتم لانفسكم فذوقوا ما كنتم تكنزون'),
(1271, 9, 36, 'اِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللّٰهِ اثْنَا عَشَرَ شَهْراً ف۪ي كِتَابِ اللّٰهِ يَوْمَ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ مِنْهَٓا اَرْبَعَةٌ حُرُمٌۜ ذٰلِكَ الدّ۪ينُ الْقَيِّمُ فَلَا تَظْلِمُوا ف۪يهِنَّ اَنْفُسَكُمْ وَقَاتِلُوا الْمُشْرِك۪ينَ كَٓافَّةً كَمَا يُقَاتِلُونَكُمْ كَٓافَّةًۜ وَاعْلَمُٓوا اَنَّ اللّٰهَ مَعَ الْمُتَّق۪ينَ', 'İnne iddeteş şuhuri indallahisna aşere şehren fi kitabillahi yevme halakas semavati vel arda minha erbeatun huruma zaliked dinul kayyimu fe la tazlimu fihinne enfusekum ve katilul muşrikine kaffeten kema yukatilunekum kaffeh, va\'lemu ennallahe meal muttekin.', 'Gökleri ve yeri yarattığı zaman koyduğu yasasında,  Allah\'ın yanında ayların sayısı on ikidir. Bunların dördü haram aylardır. İşte kayyum[1] olan budur. Bu aylarda,  kendinize haksızlık yapmayın. Ve müşrikler nasıl sizinle topyekun savaşıyorlarsa siz de onlarla topyekun savaşın. Biliniz ki,  Allah,  muttakilerle[2] beraberdir.', 'ان عدة الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض منها اربعة حرم ذلك الدين القيم فلا تظلموا فيهن انفسكم وقتلوا المشركين كافة كما يقتلونكم كافة واعلموا ان الله مع المتقين'),
(1272, 9, 37, 'اِنَّمَا النَّس۪ٓيءُ زِيَادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذ۪ينَ كَفَرُوا يُحِلُّونَهُ عَاماً وَيُحَرِّمُونَهُ عَاماً لِيُوَاطِؤُ۫ا عِدَّةَ مَا حَرَّمَ اللّٰهُ فَيُحِلُّوا مَا حَرَّمَ اللّٰهُۜ زُيِّنَ لَهُمْ سُٓوءُ اَعْمَالِهِمْۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْكَافِر۪ينَ۟', 'İnnemen nesiu ziyadetun fil kufri yudallu bihillezine keferu yuhillunehu amen ve yuharrimunehu amen li yuvatiu iddete ma harremallahu fe yuhillu ma harremallah, zuyyine lehum suu a\'malihim, vallahu la yehdil kavmel kafirin.', 'Haram ayların yerlerini değiştirip ertelemek,  küfürde ileri gitmektir ki Kafirler onunla saptırılır. Onlar,  Allah\'ın haram kıldığı aylara denk getirmek için bu ertelemeyi bir yıl helal sayarlarken bir yıl sonra haram sayarlar. Böylece Allah\'ın haram kıldığını helal saymış oluyorlar. Böylece yaptıkları kötü şeyler,  onlara güzel gösterildi. Allah Kafir halkı doğru yola iletmez.', 'انما النسي زيادة في الكفر يضل به الذين كفروا يحلونه عاما ويحرمونه عاما ليواطوا عدة ما حرم الله فيحلوا ما حرم الله زين لهم سو اعملهم والله لا يهدي القوم الكفرين'),
(1273, 9, 38, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا مَا لَكُمْ اِذَا ق۪يلَ لَكُمُ انْفِرُوا ف۪ي سَب۪يلِ اللّٰهِ اثَّاقَلْتُمْ اِلَى الْاَرْضِۜ اَرَض۪يتُمْ بِالْحَيٰوةِ الدُّنْيَا مِنَ الْاٰخِرَةِۚ فَمَا مَتَاعُ الْحَيٰوةِ الدُّنْيَا فِي الْاٰخِرَةِ اِلَّا قَل۪يلٌ', 'Ya eyyuhellezine amenu ma lekum iza kile lekumunfiru fi sebilillahissakaltum ilel ard, e raditum bil hayatid dunya minel ahireh, fe ma metaul hayatid dunya fil ahireti illa kalil.', 'Ey iman edenler! Size ne oluyor ki,  Allah yolunda seferber olun[1] denildiği zaman,  işi ağırdan aldınız. Yoksa ahiret hayatı yerine dünya hayatını mı tercih etiniz. Ama ahiret hayatının yanında dünya hayatının değeri pek azdır.', 'يايها الذين امنوا ما لكم اذا قيل لكم انفروا في سبيل الله اثاقلتم الي الارض ارضيتم بالحيوة الدنيا من الاخرة فما متع الحيوة الدنيا في الاخرة الا قليل'),
(1274, 9, 39, 'اِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَاباً اَل۪يماً وَيَسْتَبْدِلْ قَوْماً غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـٔاًۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'İlla tenfiru yuazzibkum azaben elimen ve yestebdil kavmen gayrekum ve la tedurruhu şey\'a , vallahu ala kulli şey\'in kadir.', 'Eğer seferber olmazsanız,  sizi can yakıcı bir azapla cezalandırır ve yerinize başka bir halkı getirir. Siz O\'na hiçbir şeyle zarar veremezsiniz. Allah,  Her Şeye Güç Yetiren\'dir.', 'الا تنفروا يعذبكم عذابا اليما ويستبدل قوما غيركم ولا تضروه شيا والله علي كل شي قدير'),
(1275, 9, 40, 'اِلَّا تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللّٰهُ اِذْ اَخْرَجَهُ الَّذ۪ينَ كَفَرُوا ثَانِيَ اثْنَيْنِ اِذْ هُمَا فِي الْغَارِ اِذْ يَقُولُ لِصَاحِبِه۪ لَا تَحْزَنْ اِنَّ اللّٰهَ مَعَنَاۚ فَاَنْزَلَ اللّٰهُ سَك۪ينَتَهُ عَلَيْهِ وَاَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ الَّذ۪ينَ كَفَرُوا السُّفْلٰىۜ وَكَلِمَةُ اللّٰهِ هِيَ الْعُلْيَاۜ وَاللّٰهُ عَز۪يزٌ حَك۪يمٌ', 'İlla tensuruhu fe kad nasarahullahu iz ahrecehullezine keferu saniyesneyni iz huma fil gari iz yekulu li sahibihi la tahzen innallahe meana, fe enzelallahu sekinetehu aleyhi ve eyyedehu bicunudin lem terevha ve ceale kelimetellezine keferus sufla, ve kelimetullahi hiyel ulya vallahu azizun hakim .', 'Eğer siz ona yardım etmezseniz,  iyi bilin ki Allah ona yardım etmişti. Hani Kafirler[1] onu çıkardıklarında[2] iki kişiden ikincisiydi. İkisi mağaradayken,  o,  arkadaşına: \"Üzülme,  kuşkusuz Allah bizimle beraberdir.\" demişti.[3] Bunun üzerine Allah,  üzerlerine dinginlik ve güven indirmişti. Onu,  sizin görmediğiniz güçlerle desteklemişti. Ve küfredenlerin sözünü alçaltmıştı. Allah\'ın sözü ise en yüce olandır. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'الا تنصروه فقد نصره الله اذ اخرجه الذين كفروا ثاني اثنين اذ هما في الغار اذ يقول لصحبه لا تحزن ان الله معنا فانزل الله سكينته عليه وايده بجنود لم تروها وجعل كلمة الذين كفروا السفلي وكلمة الله هي العليا والله عزيز حكيم'),
(1276, 9, 41, 'اِنْفِرُوا خِفَافاً وَثِقَالاً وَجَاهِدُوا بِاَمْوَالِكُمْ وَاَنْفُسِكُمْ ف۪ي سَب۪يلِ اللّٰهِۜ ذٰلِكُمْ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'İnfiru hıfafen ve sikalen ve cahidu bi emvalikum ve enfusikum fi sebilillah, zalikum hayrun lekum in kuntum ta\'lemun.', 'Ağır ve hafif her türlü savaş araç gereçleriyle seferber olun. Mallarınızla ve canlarınızla Allah yolunda cihad[1] edin. Eğer bilirseniz,  bu sizin için daha hayırlıdır.', 'انفروا خفافا وثقالا وجهدوا بامولكم وانفسكم في سبيل الله ذلكم خير لكم ان كنتم تعلمون'),
(1277, 9, 42, 'لَوْ كَانَ عَرَضاً قَر۪يباً وَسَفَراً قَاصِداً لَاتَّـبَعُوكَ وَلٰكِنْ بَعُدَتْ عَلَيْهِمُ الشُّقَّةُۜ وَسَيَحْلِفُونَ بِاللّٰهِ لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْۚ يُهْلِكُونَ اَنْفُسَهُمْۚ وَاللّٰهُ يَعْلَمُ اِنَّهُمْ لَكَاذِبُونَ۟', 'Lev kane aradan kariben ve seferen kasıden lettebeuke ve lakin beudet aleyhimuş şukkah, ve seyahlifune billahi levisteta\'na leharecna meakum, yuhlikune enfusehum, vallahu ya\'lemu innehum le kazibun.', 'Eğer kolay bir kazanç ve sıradan bir \"sefer\" olsaydı,  arkandan gelirlerdi. Ancak bu zorlu yolculuk,  onlara uzak geldi. \"Eğer gücümüz yetseydi,  biz de sizinle çıkardık.\" diye Allah\'a yemin edecekler. Kendilerini yok olmaya sürüklüyorlar. Kuşkusuz Allah,  onların yalancı olduklarını en iyi bilendir.', 'لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم الشقة وسيحلفون بالله لو استطعنا لخرجنا معكم يهلكون انفسهم والله يعلم انهم لكذبون'),
(1278, 9, 43, 'عَفَا اللّٰهُ عَنْكَۚ لِمَ اَذِنْتَ لَهُمْ حَتّٰى يَتَبَيَّنَ لَكَ الَّذ۪ينَ صَدَقُوا وَتَعْلَمَ الْكَاذِب۪ينَ', 'Afallahu ank, lime ezinte lehum hatta yetebeyyene lekellezine sadaku ve ta\'lemel kazibin.', 'Allah seni affetsin! Doğru söyleyenler belli olmadan,  yalancılar bilinmeden,  onlara niçin izin verdin?', 'عفا الله عنك لم اذنت لهم حتي يتبين لك الذين صدقوا وتعلم الكذبين'),
(1279, 9, 44, 'لَا يَسْتَأْذِنُكَ الَّذ۪ينَ يُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ اَنْ يُجَاهِدُوا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْۜ وَاللّٰهُ عَل۪يمٌ بِالْمُتَّق۪ينَ', 'La yeste\'zinukellezine yu\'minune billahi vel yevmil ahiri en yucahidu bi emvalihim ve enfusihim,vallahu alimun bil muttekin.', 'Allah\'a ve Ahiret Günü\'ne iman edenler,  mallarıyla ve canlarıyla cihad etmemek için senden izin istemezler. Allah,  muttakileri[1] en iyi bilendir.', 'لا يستذنك الذين يومنون بالله واليوم الاخر ان يجهدوا بامولهم وانفسهم والله عليم بالمتقين'),
(1280, 9, 45, 'اِنَّمَا يَسْتَأْذِنُكَ الَّذ۪ينَ لَا يُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَارْتَابَتْ قُلُوبُهُمْ فَهُمْ ف۪ي رَيْبِهِمْ يَتَرَدَّدُونَ', 'İnnema yeste\'zinulkellezine la yu\'minune billahi vel yevmil ahiri vertabet kulubuhum fe hum fi reybihim yetereddedun.', 'Doğrusu,  senden,  ancak Allah\'a ve Ahiret Günü\'ne inanmayanlar ve kalpleri kuşkuya düşüp,  kuşku içinde bocalayanlar sefere çıkmamak için izin isterler.', 'انما يستذنك الذين لا يومنون بالله واليوم الاخر وارتابت قلوبهم فهم في ريبهم يترددون'),
(1281, 9, 46, 'وَلَوْ اَرَادُوا الْخُرُوجَ لَاَعَدُّوا لَهُ عُدَّةً وَلٰكِنْ كَرِهَ اللّٰهُ انْبِعَاثَهُمْ فَثَبَّطَهُمْ وَق۪يلَ اقْعُدُوا مَعَ الْقَاعِد۪ينَ', 'Ve lev eradul huruce le eaddu lehu uddeten ve lakin kerihallahunbiasehum fe sebbetahum ve kilak\'udu meal kaidin .', 'Eğer çıkmak isteselerdi,  elbette bunun için hazırlık yaparlardı. Ancak Allah,  onların davranışlarını kötü gördü de kendilerini alıkoydu ve onlara: \"Oturanlarla beraber siz de oturun.\" denildi.', 'ولو ارادوا الخروج لاعدوا له عدة ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القعدين'),
(1282, 9, 47, 'لَوْ خَرَجُوا ف۪يكُمْ مَا زَادُوكُمْ اِلَّا خَبَالاً وَلَا۬اَوْضَعُوا خِلَالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَۚ وَف۪يكُمْ سَمَّاعُونَ لَهُمْۜ وَاللّٰهُ عَل۪يمٌ بِالظَّالِم۪ينَ', 'Lev harecu fikum ma zadukum illa habalen ve la evdau hılalekum yebgunekumul fitneh, ve fikum semmaune lehum, vallahu alimun biz zalimin.', 'Eğer sizinle çıksalardı,  bozgunculuktan başka bir şey yapmazlardı; sizi fitneye düşürmek için koşuştururlardı. İçinizde,  onlara kulak verecekler de olurdu. Kuşkusuz Allah,  zalimleri en iyi bilendir.', 'لو خرجوا فيكم ما زادوكم الا خبالا ولاوضعوا خللكم يبغونكم الفتنة وفيكم سمعون لهم والله عليم بالظلمين'),
(1283, 9, 48, 'لَقَدِ ابْتَغَوُا الْفِتْنَةَ مِنْ قَبْلُ وَقَلَّبُوا لَكَ الْاُمُورَ حَتّٰى جَٓاءَ الْحَقُّ وَظَهَرَ اَمْرُ اللّٰهِ وَهُمْ كَارِهُونَ', 'Lekadibtegul fitnete min kablu ve kallebu lekel umure hatta cael hakku ve zahere emrullahi ve hum karihun.', 'Daha önce de fitne çıkarmak istemişler ve sana karşı türlü işler çevirmişlerdi. Nihayet,  hakk geldi ve onlar istemedikleri halde,  Allah\'ın emri gerçekleşti.', 'لقد ابتغوا الفتنة من قبل وقلبوا لك الامور حتي جا الحق وظهر امر الله وهم كرهون'),
(1284, 9, 49, 'وَمِنْهُمْ مَنْ يَقُولُ ائْذَنْ ل۪ي وَلَا تَفْتِنّ۪يۜ اَلَا فِي الْفِتْنَةِ سَقَطُواۜ وَاِنَّ جَهَنَّمَ لَمُح۪يطَةٌ بِالْكَافِر۪ينَ', 'Ve minhum men yekulu\'zen li ve la teftinni, e la fil fitneti sekatu, ve inne cehenneme le muhitatun bil kafirin.', 'Onlardan kimi de: \"Bana izin ver,  beni fitneye düşürme.[1]\" der. İyi bilmiş ol ki,  onlar,  fitneye düşmüşlerdir. Cehennem onları kuşatacaktır.', 'ومنهم من يقول ايذن لي ولا تفتني الا في الفتنة سقطوا وان جهنم لمحيطة بالكفرين'),
(1285, 9, 50, 'اِنْ تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْۚ وَاِنْ تُصِبْكَ مُص۪يبَةٌ يَقُولُوا قَدْ اَخَذْنَٓا اَمْرَنَا مِنْ قَبْلُ وَيَتَوَلَّوْا وَهُمْ فَرِحُونَ', 'İn tusıbke hasenetun tesu\'hum, ve in tusıbke musibetun yekulu kad ehazna emrena min kablu ve yetevellev ve hum ferihun.', 'Eğer sana bir iyilik isabet ederse,  bu onları üzer. Fakat sana bir kötülük dokunursa,  \"Biz daha önceden önlemimizi almıştık.[1]\" derler ve sevinç içinde arkalarına dönüp giderler.', 'ان تصبك حسنة تسوهم وان تصبك مصيبة يقولوا قد اخذنا امرنا من قبل ويتولوا وهم فرحون'),
(1286, 9, 51, 'قُلْ لَنْ يُص۪يبَنَٓا اِلَّا مَا كَتَبَ اللّٰهُ لَنَاۚ هُوَ مَوْلٰينَاۚ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'Kul len yusibena illa ma keteballahu lena, huve mevlana, ve alallahi fel yetevekkelil mu\'minun.', 'De ki: \"Allah\'ın bizim için yazdığından[1] başkası bize erişmez. O,  bizim mevlamızdır.[2] Öyleyse,  mü\'minler,  yalnız Allah\'a tevekkül[3] etsinler.', 'قل لن يصيبنا الا ما كتب الله لنا هو مولينا وعلي الله فليتوكل المومنون'),
(1287, 9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَٓا اِلَّٓا اِحْدَى الْحُسْنَيَيْنِۜ وَنَحْنُ نَتَرَبَّصُ بِكُمْ اَنْ يُص۪يبَكُمُ اللّٰهُ بِعَذَابٍ مِنْ عِنْدِه۪ٓ اَوْ بِاَيْد۪ينَاۘ فَتَرَبَّصُٓوا اِنَّا مَعَكُمْ مُتَرَبِّصُونَ', 'Kul hel terabbesune bina illa ıhdel husneyeyn ve nahnu neterabbesu bikum en yusibekumullahu bi azabin min indihi ev bi eydina, fe terabbasu inna meakum muterabbisun.', 'De ki: \"Bize iki güzellikten[1] birinin dışında başka bir şeyin gelmesini mi bekliyorsunuz? Oysa biz,  Allah\'ın kendi katından veya bizim elimizle size bir azap gelmesini bekliyoruz. Öyleyse bekleyin. Doğrusu biz de sizinle beraber bekleyenlerdeniz.\"', 'قل هل تربصون بنا الا احدي الحسنيين ونحن نتربص بكم ان يصيبكم الله بعذاب من عنده او بايدينا فتربصوا انا معكم متربصون'),
(1288, 9, 53, 'قُلْ اَنْفِقُوا طَوْعاً اَوْ كَرْهاً لَنْ يُتَقَبَّلَ مِنْكُمْۜ اِنَّكُمْ كُنْتُمْ قَوْماً فَاسِق۪ينَ', 'Kul enfiku tav\'an ev kerhen len yutekabbele minkum, innekum kuntum kavmen fasikin.', 'De ki: \"İster istekli,  ister isteksiz infak[1] edin; sizden asla kabul edilmeyecektir. Çünkü siz fasık[2] bir toplum oldunuz.\"', 'قل انفقوا طوعا او كرها لن يتقبل منكم انكم كنتم قوما فسقين'),
(1289, 9, 54, 'وَمَا مَنَعَهُمْ اَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ اِلَّٓا اَنَّهُمْ كَفَرُوا بِاللّٰهِ وَبِرَسُولِه۪ وَلَا يَأْتُونَ الصَّلٰوةَ اِلَّا وَهُمْ كُسَالٰى وَلَا يُنْفِقُونَ اِلَّا وَهُمْ كَارِهُونَ', 'Ve ma meneahum en tukbele minhum nefekatuhum illa ennehum keferu billahi ve bi resulihi ve la ye\'tunes salate illa ve humkusala ve la yunfikune illa ve hum karihun.', 'İnfaklarının[1] kabul edilmesine engel şey,  onların,  Allah\'a ve Resul\'üne karşı küfretmeleri[2],  salata[3] üşene üşene gelmeleri[4] ve istemeyerek infak etmeleridir.', 'وما منعهم ان تقبل منهم نفقتهم الا انهم كفروا بالله وبرسوله ولا ياتون الصلوة الا وهم كسالي ولا ينفقون الا وهم كرهون'),
(1290, 9, 55, 'فَلَا تُعْجِبْكَ اَمْوَالُهُمْ وَلَٓا اَوْلَادُهُمْۜ اِنَّمَا يُر۪يدُ اللّٰهُ لِيُعَذِّبَهُمْ بِهَا فِي الْحَيٰوةِ الدُّنْيَا وَتَزْهَقَ اَنْفُسُهُمْ وَهُمْ كَافِرُونَ', 'Fe la tu\'cibke emvaluhum ve la evladuhum, innema yuridullahu li yuazzibehum biha fil hayatid dunya ve tezheka enfusuhum ve hum kafirun.', 'Öyleyse,  onların malları ve çocukları seni imrendirmesin. Doğrusu,  Allah,  bunlarla,  onlara dünya hayatında azap etmeyi ve canlarının Kafir olarak çıkmasını istiyor.', 'فلا تعجبك امولهم ولا اولدهم انما يريد الله ليعذبهم بها في الحيوة الدنيا وتزهق انفسهم وهم كفرون'),
(1291, 9, 56, 'وَيَحْلِفُونَ بِاللّٰهِ اِنَّهُمْ لَمِنْكُمْۜ وَمَا هُمْ مِنْكُمْ وَلٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', 'Ve yahlifune billahi innehum le minkum, ve ma hum minkum ve lakinnehum kavmun yefrekun.', 'Sizden olduklarına dair Allah\'a yemin ederler. Oysa onlar,  sizden değiller. Onlar,  ayrılık çıkaran bir topluluktur.', 'ويحلفون بالله انهم لمنكم وما هم منكم ولكنهم قوم يفرقون'),
(1292, 9, 57, 'لَوْ يَجِدُونَ مَلْجَـٔاً اَوْ مَغَارَاتٍ اَوْ مُدَّخَلاً لَوَلَّوْا اِلَيْهِ وَهُمْ يَجْمَحُونَ', 'Lev yecidune melce\'en ev magaratin ev muddehalen le vellev ileyhi ve hum yecmehun.', 'Eğer sığınılacak bir yer veya bir mağara veya girilecek bir delik bulsalardı,  panik içinde oraya koşarlardı.', 'لو يجدون ملجا او مغرت او مدخلا لولوا اليه وهم يجمحون'),
(1293, 9, 58, 'وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي الصَّدَقَاتِۚ فَاِنْ اُعْطُوا مِنْهَا رَضُوا وَاِنْ لَمْ يُعْطَوْا مِنْهَٓا اِذَا هُمْ يَسْخَطُونَ', 'Ve minhum men yelmizuke fis sadakat, fe in u\'tu minha radu ve in lem yu\'tav minha iza hum yeshatun.', 'İçlerinden kimileri de sadakalar hakkında sana dil uzatır. Eğer kendilerine pay verilirse hoşlanırlar,  verilmeyince de hemen kızarlar.', 'ومنهم من يلمزك في الصدقت فان اعطوا منها رضوا وان لم يعطوا منها اذا هم يسخطون'),
(1294, 9, 59, 'وَلَوْ اَنَّهُمْ رَضُوا مَٓا اٰتٰيهُمُ اللّٰهُ وَرَسُولُهُ وَقَالُوا حَسْبُنَا اللّٰهُ سَيُؤْت۪ينَا اللّٰهُ مِنْ فَضْلِه۪ وَرَسُولُهُٓۙ اِنَّٓا اِلَى اللّٰهِ رَاغِبُونَ۟', 'Ve lev ennehum radu ma atahumullahu ve resuluhu ve kalu hasbunallahu se yu\'tinallahu min fadlihi ve resuluhu inna ilallahi ragıbun.', 'Ne olurdu! Onlar,  Allah\'ın ve Resulünün verdiklerine razı olsalar ve: \"Allah\'ın lütfu[1] bize yeter,  Allah bize lütfundan yine verir,  Resulü de. Bizim isteğimiz yalnızca Allah\'ın rızasıdır.\" deselerdi.', 'ولو انهم رضوا ما اتيهم الله ورسوله وقالوا حسبنا الله سيوتينا الله من فضله ورسوله انا الي الله رغبون'),
(1295, 9, 60, 'اِنَّمَا الصَّدَقَاتُ لِلْفُقَـرَٓاءِ وَالْمَسَاك۪ينِ وَالْعَامِل۪ينَ عَلَيْهَا وَالْمُؤَ۬لَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِم۪ينَ وَف۪ي سَب۪يلِ اللّٰهِ وَابْنِ السَّب۪يلِۜ فَر۪يضَةً مِنَ اللّٰهِۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'İnnemas sadakatu lil fukarai vel mesakini vel amiline aleyha vel muellefeti kulubuhum ve fir rikabi vel garimine ve fi sebilillahi vebnissebil, faridaten minallah, vallahu alimun hakim.', 'Sadakalar[1],  Allah\'tan bir farz olarak[2]; ancak yoksullara,  düşkünlere,  bununla ilgili görevlilere[3],  kalpleri kazanılacak kimselere[4],  rikab olanlara[5],  borçlulara,  Allah yoluna ve yol oğluna[6] aittir. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'انما الصدقت للفقرا والمسكين والعملين عليها والمولفة قلوبهم وفي الرقاب والغرمين وفي سبيل الله وابن السبيل فريضة من الله والله عليم حكيم'),
(1296, 9, 61, 'وَمِنْهُمُ الَّذ۪ينَ يُؤْذُونَ النَّبِيَّ وَيَقُولُونَ هُوَ اُذُنٌۜ قُلْ اُذُنُ خَيْرٍ لَكُمْ يُؤْمِنُ بِاللّٰهِ وَيُؤْمِنُ لِلْمُؤْمِن۪ينَ وَرَحْمَةٌ لِلَّذ۪ينَ اٰمَنُوا مِنْكُمْۜ وَالَّذ۪ينَ يُؤْذُونَ رَسُولَ اللّٰهِ لَهُمْ عَذَابٌ اَل۪يمٌ', 'Ve minhumullezine yu\'zunen nebiyye ve yekulune huve uzun, kul uzunu hayrin lekum yu\'minu billahi ve yu\'minu lil mu\'minine ve rahmetun lillezine amenu minkum, vellezine yu\'zune resulallahi lehum azabun elim.', 'Onlardan bir kısmı,  \"O,  bir kulaktır.\"[1] diyerek,  nebiyi incitiyorlar. De ki: \"O,  sizin için hayır kulağıdır.\" O,  Allah\'a inanır ve mü\'minlere inanır. İman edenler için bir rahmettir. Allah\'ın Resulünü incitenler için can yakıcı bir azap vardır.', 'ومنهم الذين يوذون النبي ويقولون هو اذن قل اذن خير لكم يومن بالله ويومن للمومنين ورحمة للذين امنوا منكم والذين يوذون رسول الله لهم عذاب اليم'),
(1297, 9, 62, 'يَحْلِفُونَ بِاللّٰهِ لَكُمْ لِيُرْضُوكُمْۚ وَاللّٰهُ وَرَسُولُـهُٓ اَحَقُّ اَنْ يُرْضُوهُ اِنْ كَانُوا مُؤْمِن۪ينَ', 'Yahlifune billahi lekum li yurdukum, vallahu ve resuluhu ehakku en yurduhu in kanu mu\'minin.', 'Sizi hoşnut etmek için,  Allah\'a yemin ediyorlar. Oysaki gerçekten inanıyorlarsa,  Allah ve Resulü hoşnut edilmeye daha layıktır.', 'يحلفون بالله لكم ليرضوكم والله ورسوله احق ان يرضوه ان كانوا مومنين'),
(1298, 9, 63, 'اَلَمْ يَعْلَمُٓوا اَنَّهُ مَنْ يُحَادِدِ اللّٰهَ وَرَسُولَهُ فَاَنَّ لَهُ نَارَ جَهَنَّمَ خَالِداً ف۪يهَاۜ ذٰلِكَ الْخِزْيُ الْعَظ۪يمُ', 'E lem ya\'lemu ennehu men yuhadidillahe ve resulehu fe enne lehu nare cehenneme haliden fiha, zalikel hızyul azim.', 'Bilmediler mi ki: Kim Allah\'a ve Resulüne karşı haddi aşarsa,  onun için,  içinde sürekli kalacağı Cehennem ateşi vardır. İşte bu,  büyük rezilliktir.[1]', 'الم يعلموا انه من يحادد الله ورسوله فان له نار جهنم خلدا فيها ذلك الخزي العظيم'),
(1299, 9, 64, 'يَحْذَرُ الْمُنَافِقُونَ اَنْ تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُمْ بِمَا ف۪ي قُلُوبِهِمْۜ قُلِ اسْتَهْزِؤُ۫اۚ اِنَّ اللّٰهَ مُخْرِجٌ مَا تَحْذَرُونَ', 'Yahzerul munafikune en tunezzele aleyhim suretun tunebbiuhum bi ma fi kulubihim, kulistehziu, innallahe muhricun ma tahzerun.', 'Münafıklar,  kendileri hakkında kalplerinde olanı haber verecek bir surenin indirilmesinden çekiniyorlar. De ki: \"Alay edin bakalım! Kuşkusuz Allah,  çekindiğiniz şeyi açığa çıkaracaktır.\"', 'يحذر المنفقون ان تنزل عليهم سورة تنبيهم بما في قلوبهم قل استهزوا ان الله مخرج ما تحذرون'),
(1300, 9, 65, 'وَلَئِنْ سَاَلْتَهُمْ لَيَقُولُنَّ اِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُۜ قُلْ اَبِاللّٰهِ وَاٰيَاتِه۪ وَرَسُولِه۪ كُنْتُمْ تَسْتَهْزِؤُ۫نَ', 'Ve lein se\'eltehum le yekulunne innema kunna nahudu ve nel\'ab, kul e billahi ve ayatihi ve resulihi kuntum testehziun .', 'Eğer onlara soracak olsan,  \"Biz sadece lafa dalmış şakalaşıyorduk.\" derler. De ki: \"Allah ile mi,  O\'nun ayetleri ve Resulü ile mi alay ediyordunuz?\"', 'ولين سالتهم ليقولن انما كنا نخوض ونلعب قل ابالله وايته ورسوله كنتم تستهزون'),
(1301, 9, 66, 'لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ ا۪يمَانِكُمْۜ اِنْ نَعْفُ عَنْ طَٓائِفَةٍ مِنْكُمْ نُعَذِّبْ طَٓائِفَةً بِاَنَّهُمْ كَانُوا مُجْرِم۪ينَ۟', 'La ta\'teziru kad kefertum ba\'de imanikum, in na\'fu an taifetin minkum nuazzib taifeten bi ennehum kanu mucrimin.', 'Hiç özür dilemeyin! Ant olsun siz inandıktan sonra Kafirlik ettiniz. Sizden bir kısmınızı affetsek bile,  suç işlemelerinden dolayı bir kısmınıza da azap edeceğiz.', 'لا تعتذروا قد كفرتم بعد ايمنكم ان نعف عن طايفة منكم نعذب طايفة بانهم كانوا مجرمين'),
(1302, 9, 67, 'اَلْمُنَافِقُونَ وَالْمُنَافِقَاتُ بَعْضُهُمْ مِنْ بَعْضٍۢ يَأْمُرُونَ بِالْمُنْكَرِ وَيَنْهَوْنَ عَنِ الْمَعْرُوفِ وَيَقْبِضُونَ اَيْدِيَهُمْۜ نَسُوا اللّٰهَ فَنَسِيَهُمْۜ اِنَّ الْمُنَافِق۪ينَ هُمُ الْفَاسِقُونَ', 'El munafikune vel munafikatu ba\'duhum min ba\'d, ye\'murune bil munkeri ve yenhevne anil ma\'rufi ve yakbidune eydiyehum nesullahe fe nesiyehum innel munafıkine humul fasikun.', 'Münafık[1] erkekler ve münafık kadınlar birbirlerindendirler; kötülüğü buyururlar,  iyilikten alıkoyarlar. Ellerini sıkı tutarlar.[2] Onlar,  Allah\'ı unuttular,  Allah da onları unuttu.[3] Münafıklar,  fasıkların[4] ta kendileridir.', 'المنفقون والمنفقت بعضهم من بعض يامرون بالمنكر وينهون عن المعروف ويقبضون ايديهم نسوا الله فنسيهم ان المنفقين هم الفسقون'),
(1303, 9, 68, 'وَعَدَ اللّٰهُ الْمُنَافِق۪ينَ وَالْمُنَافِقَاتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَاۜ هِيَ حَسْبُهُمْۚ وَلَعَنَهُمُ اللّٰهُۚ وَلَهُمْ عَذَابٌ مُق۪يمٌۙ', 'Vaadallahul munafikine vel munafikati vel kuffare nare cehenneme halidine fiha hiye hasbuhum, ve leanehumullah ve lehum azabun mukim .', 'Allah,  münafık erkeklere ve münafık kadınlara ve Kafirlere,  cehennem ateşini vadetmiştir. Orada sürekli kalıcıdırlar. Bu,  onlara yeter. Allah,  onları lanetlemiştir ve onlar için kalıcı bir azap vardır.', 'وعد الله المنفقين والمنفقت والكفار نار جهنم خلدين فيها هي حسبهم ولعنهم الله ولهم عذاب مقيم'),
(1304, 9, 69, 'كَالَّذ۪ينَ مِنْ قَبْلِكُمْ كَانُٓوا اَشَدَّ مِنْكُمْ قُوَّةً وَاَكْثَرَ اَمْوَالاً وَاَوْلَاداًۜ فَاسْتَمْتَعُوا بِخَلَاقِهِمْ فَاسْتَمْتَعْتُمْ بِخَلَاقِكُمْ كَمَا اسْتَمْتَعَ الَّذ۪ينَ مِنْ قَبْلِكُمْ بِخَلَاقِهِمْ وَخُضْتُمْ كَالَّذ۪ي خَاضُواۜ اُو۬لٰٓئِكَ حَبِطَتْ اَعْمَالُهُمْ فِي الدُّنْيَا وَالْاٰخِرَةِۚ وَاُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ', 'Kellezine min kablikum kanu eşedde minkum kuvveten ve eksere emvalen ve evlada, festemteu bi halakihim, festemta\'tum bi halakikum kemastemteallezine min kablikum bi halakihim ve hudtum kellezi hadu, ulaike habitat a\'maluhum fid dunya vel ahıreh, ve ulaike humul hasirun .', 'Tıpkı sizden öncekiler gibisiniz. Onlar; kuvvetçe sizden daha güçlü,  mal ve evlat bakımından sizden daha çoktular. Onlar,  payları kadar bundan yararlandılar. Sizden öncekilerin paylarınca yararlandıkları gibi siz de payınızca yararlandınız. Ve onların daldığı[1] gibi siz de daldınız. İşte onların yaptıkları dünyada da ahirette de boşa gitmiştir. Onlar hüsrana uğrayanlardır.', 'كالذين من قبلكم كانوا اشد منكم قوة واكثر امولا واولدا فاستمتعوا بخلقهم فاستمتعتم بخلقكم كما استمتع الذين من قبلكم بخلقهم وخضتم كالذي خاضوا اوليك حبطت اعملهم في الدنيا والاخرة واوليك هم الخسرون'),
(1305, 9, 70, 'اَلَمْ يَأْتِهِمْ نَبَاُ الَّذ۪ينَ مِنْ قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ اِبْرٰه۪يمَ وَاَصْحَابِ مَدْيَنَ وَالْمُؤْتَفِكَاتِۜ اَتَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِۚ فَمَا كَانَ اللّٰهُ لِيَظْلِمَهُمْ وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'E lem ye\'tihim nebeullezine min kablihim kavmi nuhin ve adn ve semude ve kavmi ibrahime ve ashabi medyene vel mu\'tefikat, etethum rusuluhum bil beyyinat, fe ma kanallahu li yazlimehum ve lakin kanu enfusehum yazlimun.', 'Onlara,  kendilerinden öncekilerin; Nuh,  Âd ve Semud halklarının,  İbrahim halkının ve Medyen sahiplerinin ve mutefikelerin[1] haberi gelmedi mi? Resulleri onlara açık kanıtlar getirmişti. Allah,  onlara haksızlık etmiş değildi. Fakat onlar kendi kendilerine haksızlık yapıyorlardı.', 'الم ياتهم نبا الذين من قبلهم قوم نوح وعاد وثمود وقوم ابرهيم واصحب مدين والموتفكت اتتهم رسلهم بالبينت فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون'),
(1306, 9, 71, 'وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ اَوْلِيَٓاءُ بَعْضٍۢ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُق۪يمُونَ الصَّلٰوةَ وَيُؤْتُونَ الزَّكٰوةَ وَيُط۪يعُونَ اللّٰهَ وَرَسُولَهُۜ اُو۬لٰٓئِكَ سَيَرْحَمُهُمُ اللّٰهُۜ اِنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ', 'Vel mu\'minune vel mu\'minatu ba\'duhum evliyau ba\'d, ye\'murune bil ma\'rufi ve yenhevne anil munkeri ve yukimunas salate ve yu\'tunez zekate ve yutiunallahe ve resuleh, ulaike se yerhamuhumullah, innallahe azizun hakim.', 'Mü\'min erkekler ve mü\'min kadınlar birbirlerinin velileridirler.[1] Ma\'ruf olanı yaparlar,  munkerden sakındırırlar.[2] Salatı ikame ederler,  zekatı yaparlar.[3] Allah\'a ve Resulüne itaat ederler. İşte bunlara,  Allah rahmet edecektir. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'والمومنون والمومنت بعضهم اوليا بعض يامرون بالمعروف وينهون عن المنكر ويقيمون الصلوة ويوتون الزكوة ويطيعون الله ورسوله اوليك سيرحمهم الله ان الله عزيز حكيم'),
(1307, 9, 72, 'وَعَدَ اللّٰهُ الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَا وَمَسَاكِنَ طَيِّبَةً ف۪ي جَنَّاتِ عَدْنٍۜ وَرِضْوَانٌ مِنَ اللّٰهِ اَكْبَرُۜ ذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُ۟', 'Vaadallahul mu\'minine vel mu\'minati cennatin tecri min tahtihel enharu halidine fiha ve mesakine tayyibeten fi cennati adn, ve rıdvanun minallahi ekber, zalike huvel fevzul azim.', 'Allah,  mü\'min erkeklere ve mü\'min kadınlara,  içinden ırmaklar akan,  içinde sürekli kalacakları Cennetler ve Adn Cennetlerinde temiz yerleşim yerleri söz verdi. Allah\'ın razı olması ise daha büyüktür.[1] İşte büyük başarı budur.', 'وعد الله المومنين والمومنت جنت تجري من تحتها الانهر خلدين فيها ومسكن طيبة في جنت عدن ورضون من الله اكبر ذلك هو الفوز العظيم'),
(1308, 9, 73, 'يَٓا اَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِق۪ينَ وَاغْلُظْ عَلَيْهِمْۜ وَمَأْوٰيهُمْ جَهَنَّمُۜ وَبِئْسَ الْمَص۪يرُ', 'Ya eyyuhen nebiyyu cahidil kuffare vel munafikine vagluz aleyhim, ve me\'vahum cehennem, ve bi\'sel masir.', 'Ey Nebi! Kafirlerle ve münafıklarla cihat et. Onlara karşı kararlılıkla mücadele et. Onların varacakları yer Cehennem\'dir. O,  ne kötü varış yeridir.', 'يايها النبي جهد الكفار والمنفقين واغلظ عليهم وماويهم جهنم وبيس المصير'),
(1309, 9, 74, 'يَحْلِفُونَ بِاللّٰهِ مَا قَالُواۜ وَلَقَدْ قَالُوا كَلِمَةَ الْكُفْرِ وَكَفَرُوا بَعْدَ اِسْلَامِهِمْ وَهَمُّوا بِمَا لَمْ يَنَالُواۚ وَمَا نَقَمُٓوا اِلَّٓا اَنْ اَغْنٰيهُمُ اللّٰهُ وَرَسُولُهُ مِنْ فَضْلِه۪ۚ فَاِنْ يَتُوبُوا يَكُ خَيْراً لَهُمْۚ وَاِنْ يَتَوَلَّوْا يُعَذِّبْهُمُ اللّٰهُ عَذَاباً اَل۪يماً فِي الدُّنْيَا وَالْاٰخِرَةِۚ وَمَا لَهُمْ فِي الْاَرْضِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'Yahlifune billahi ma kalu, ve lekad kalu kelimetel kufri ve keferu ba\'de islamihim ve hemmu bi ma lem yenalu, ve ma nekamu illa en egnahumullahu ve resuluhu min fadlih, fe in yetubu yeku hayren lehum, ve in yetevellev yuazzibhumullahu azaben elimen fid dunya vel ahıreh, ve ma lehum fil ardı min veliyyin ve la nasir.', 'Münafıklar söylemediklerine[1] dair Allah\'a yemin ediyorlar. Ant olsun küfür sözünü[2] söylediler. İslam olduktan sonra Kafir oldular. Elde edemeyecekleri bir şeye yöneldiler. Öç almaya kalkışmaları da ancak Allah ve Resulünün kendi fazlından onları[3] zengin etmiş olmasındandır. Eğer tevbe ederlerse,  haklarında hayırlı olur. Şayet yüz çevirirlerse,  Allah onları dünyada ve ahirette can yakıcı azaba uğratır. Ve onlar için yeryüzünde ne bir veli ne bir yardımcı vardır.', 'يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر وكفروا بعد اسلمهم وهموا بما لم ينالوا وما نقموا الا ان اغنيهم الله ورسوله من فضله فان يتوبوا يك خيرا لهم وان يتولوا يعذبهم الله عذابا اليما في الدنيا والاخرة وما لهم في الارض من ولي ولا نصير'),
(1310, 9, 75, 'وَمِنْهُمْ مَنْ عَاهَدَ اللّٰهَ لَئِنْ اٰتٰينَا مِنْ فَضْلِه۪ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ الصَّالِح۪ينَ', 'Ve minhum men ahedallahe le in atana min fadlihi Le nessaddekanne ve le nekunenne mines salihin.', 'Onlardan kimi de \"Eğer lütfundan bize verirse,  ant olsun sadaka vereceğiz ve ant olsun salihlerden[1] olacağız.\" diye Allah\'a söz vermişlerdi.', 'ومنهم من عهد الله لين اتينا من فضله لنصدقن ولنكونن من الصلحين'),
(1311, 9, 76, 'فَلَمَّٓا اٰتٰيهُمْ مِنْ فَضْلِه۪ بَخِلُوا بِه۪ وَتَوَلَّوْا وَهُمْ مُعْرِضُونَ', 'Fe lemma atahum min fadlihi bahılu bihi ve tevellev ve hum mu\'ridun.', 'Allah,  onlara[1] lütfundan verince,  onlar cimrilik edip yüz çevirdiler. Zaten onlar dönektirler.', 'فلما اتيهم من فضله بخلوا به وتولوا وهم معرضون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1312, 9, 77, 'فَاَعْقَبَهُمْ نِفَاقاً ف۪ي قُلُوبِهِمْ اِلٰى يَوْمِ يَلْقَوْنَهُ بِمَٓا اَخْلَفُوا اللّٰهَ مَا وَعَدُوهُ وَبِمَا كَانُوا يَكْذِبُونَ', 'Fe a\'kabehum nifakan fi kulubihim ila yevmi yelkavnehu bi ma ahlefullahe ma vaaduhu ve bi ma kanu yekzibun.', 'Allah\'a verdikleri sözü tutmamaları ve yalan söylemeleri nedeniyle,  Kendisi ile karşılaşacakları güne kadar onların kalplerine nifak[1] soktu.', 'فاعقبهم نفاقا في قلوبهم الي يوم يلقونه بما اخلفوا الله ما وعدوه وبما كانوا يكذبون'),
(1313, 9, 78, 'اَلَمْ يَعْلَمُٓوا اَنَّ اللّٰهَ يَعْلَمُ سِرَّهُمْ وَنَجْوٰيهُمْ وَاَنَّ اللّٰهَ عَلَّامُ الْغُيُوبِۚ', 'E lem ya\'lemu ennallahe ya\'lemu sırrehum ve necvahum ve ennallahe allamul guyub.', 'Bilmiyorlar mı ki,  Allah onların sırlarını da fısıldaşmalarını da bilmektedir. Allah,  gaybı bilendir.', 'الم يعلموا ان الله يعلم سرهم ونجويهم وان الله علم الغيوب'),
(1314, 9, 79, 'اَلَّذ۪ينَ يَلْمِزُونَ الْمُطَّوِّع۪ينَ مِنَ الْمُؤْمِن۪ينَ فِي الصَّدَقَاتِ وَالَّذ۪ينَ لَا يَجِدُونَ اِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْۜ سَخِرَ اللّٰهُ مِنْهُمْۘ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'Ellezine yelmizunel muttavviine minel mu\'minine fis sadakati vellezine la yecidune illa cuhdehum fe yesharune minhum sehirallahu minhum, ve lehum azabun elim.', 'Sadakalar[1] konusunda gönülden davranan Mü\'minlere dil uzatanlar ve güçleri oranında verebilenleri alaya alanlar var ya,  Allah da onları alaya alacaktır. Onlar için can yakıcı bir azap vardır.', 'الذين يلمزون المطوعين من المومنين في الصدقت والذين لا يجدون الا جهدهم فيسخرون منهم سخر الله منهم ولهم عذاب اليم'),
(1315, 9, 80, 'اِسْتَغْفِرْ لَهُمْ اَوْ لَا تَسْتَغْفِرْ لَهُمْۜ اِنْ تَسْتَغْفِرْ لَهُمْ سَبْع۪ينَ مَرَّةً فَلَنْ يَغْفِرَ اللّٰهُ لَهُمْۜ ذٰلِكَ بِاَنَّهُمْ كَفَرُوا بِاللّٰهِ وَرَسُولِه۪ۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْفَاسِق۪ينَ۟', 'İstagfir lehum ev la testagfir lehum, in testagfir lehum seb\'ine merreten fe len yagfirallahu lehum, zalike bi ennehum keferu billahi ve resulih, vallahu la yehdil kavmel fasikin.', 'Onlar için ister bağışlanma dile,  ister dileme. Onlar için yetmiş defa[1] bağışlanma dilesen de yine Allah onları bağışlamayacaktır. Bu,  onların Allah\'ı ve Resulü\'nü inkar etmelerindendir. Allah,  fasık olan halkı doğru yola iletmez.', 'استغفر لهم او لا تستغفر لهم ان تستغفر لهم سبعين مرة فلن يغفر الله لهم ذلك بانهم كفروا بالله ورسوله والله لا يهدي القوم الفسقين'),
(1316, 9, 81, 'فَرِحَ الْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَافَ رَسُولِ اللّٰهِ وَكَرِهُٓوا اَنْ يُجَاهِدُوا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ ف۪ي سَب۪يلِ اللّٰهِ وَقَالُوا لَا تَنْفِرُوا فِي الْحَرِّۜ قُلْ نَارُ جَهَنَّمَ اَشَدُّ حَراًّۜ لَوْ كَانُوا يَفْقَهُونَ', 'Ferihal muhallefune bi mak\'adihim hılafe resulillahi ve kerihuen yucahidu bi emvalihim ve enfusihim fi sebilillahi ve kalu la tenfiru fil harr, kul naru cehennemeeşeddu harra, lev kanu yefkahun.', 'Allah\'ın Resulüne muhalefet ederek geride kalanlar,  oturup kalmalarına sevindiler. Mallarıyla,  canlarıyla cihad etmekten hoşlanmadılar. Bir de,  \"Bu sıcakta savaşa çıkmayın.\" dediler. De ki: \"Cehennem ateşi daha sıcaktır.\" Keşke anlasalardı!', 'فرح المخلفون بمقعدهم خلف رسول الله وكرهوا ان يجهدوا بامولهم وانفسهم في سبيل الله وقالوا لا تنفروا في الحر قل نار جهنم اشد حرا لو كانوا يفقهون'),
(1317, 9, 82, 'فَلْيَضْحَكُوا قَل۪يلاً وَلْيَبْكُوا كَث۪يراًۚ جَزَٓاءً بِمَا كَانُوا يَكْسِبُونَ', 'Fel yadhaku kalilen vel yebku kesira, cezaen bi ma kanu yeksibun.', 'Öyleyse yaptıklarına karşılık,  az gülüp,  çok ağlasınlar.', 'فليضحكوا قليلا وليبكوا كثيرا جزا بما كانوا يكسبون'),
(1318, 9, 83, 'فَاِنْ رَجَعَكَ اللّٰهُ اِلٰى طَٓائِفَةٍ مِنْهُمْ فَاسْتَأْذَنُوكَ لِلْخُرُوجِ فَقُلْ لَنْ تَخْرُجُوا مَعِيَ اَبَداً وَلَنْ تُقَاتِلُوا مَعِيَ عَدُواًّۜ اِنَّكُمْ رَض۪يتُمْ بِالْقُعُودِ اَوَّلَ مَرَّةٍ فَاقْعُدُوا مَعَ الْخَالِف۪ينَ', 'Fe in receakallahu ila taifetin minhum feste\'zenuke lil huruci fe kul len tahrucu maiye ebeden ve len tukatilu maiye aduvv, innekumraditum bil ku\'udi evvele merretin fak\'udu meal halifin.', 'Eğer Allah,  seni onlardan bir grupla karşılaştırırsa,  onlar da seninle savaşa çıkmak için izin isterlerse; de ki: \"Benimle asla çıkamayacaksınız. Artık benimle hiçbir düşmanla savaşamayacaksınız. Çünkü siz daha önce oturup kalmayı tercih ettiniz. Artık,  geride kalanlarla oturun!\"', 'فان رجعك الله الي طايفة منهم فاستذنوك للخروج فقل لن تخرجوا معي ابدا ولن تقتلوا معي عدوا انكم رضيتم بالقعود اول مرة فاقعدوا مع الخلفين'),
(1319, 9, 84, 'وَلَا تُصَلِّ عَلٰٓى اَحَدٍ مِنْهُمْ مَاتَ اَبَداً وَلَا تَقُمْ عَلٰى قَبْرِه۪ۜ اِنَّهُمْ كَفَرُوا بِاللّٰهِ وَرَسُولِه۪ وَمَاتُوا وَهُمْ فَاسِقُونَ', 'Ve la tusalli ala ehadin minhum mate ebeden ve la tekum ala kabrih, innehum keferu billahi ve resulihi ve matu ve hum fasikun .', 'Onlardan ölen hiçbir kimseye,  asla salat[1] etme ve kabirlerinin başında da durma. Çünkü onlar,  Allah ve Resul\'ünü Küfrettiler.[2] Ve onlar fasık[3] olarak öldüler.', 'ولا تصل علي احد منهم مات ابدا ولا تقم علي قبره انهم كفروا بالله ورسوله وماتوا وهم فسقون'),
(1320, 9, 85, 'وَلَا تُعْجِبْكَ اَمْوَالُهُمْ وَاَوْلَادُهُمْۜ اِنَّمَا يُر۪يدُ اللّٰهُ اَنْ يُعَذِّبَهُمْ بِهَا فِي الدُّنْيَا وَتَزْهَقَ اَنْفُسُهُمْ وَهُمْ كَافِرُونَ', 'Ve La tu\'cibke emvaluhum ve evladuhum, innema yuridullahu en yuazzibehum biha fid dunya ve tezheka enfusuhum ve hum kafirun.', 'Öyleyse,  onların[1] malları ve çocukları seni imrendirmesin. Doğrusu,  Allah,  bunlarla,  onlara dünya hayatında azap etmeyi ve canlarının Kafir olarak çıkmasını istiyor.', 'ولا تعجبك امولهم واولدهم انما يريد الله ان يعذبهم بها في الدنيا وتزهق انفسهم وهم كفرون'),
(1321, 9, 86, 'وَاِذَٓا اُنْزِلَتْ سُورَةٌ اَنْ اٰمِنُوا بِاللّٰهِ وَجَاهِدُوا مَعَ رَسُولِهِ اسْتَأْذَنَكَ اُو۬لُوا الطَّوْلِ مِنْهُمْ وَقَالُوا ذَرْنَا نَكُنْ مَعَ الْقَاعِد۪ينَ', 'Ve iza unzilet suretun en aminu billahi ve cahidu mearesulihiste\'zeneke ulut tavli minhum ve kaluzerna nekun meal ka\'ıdin.', '\"Allah\'a iman edin,  Resulü ile birlikte cihad edin.\" diye bir sure indirildiği zaman,  onlardan servet sahibi olanlar,  senden izin istediler: \"Bırak bizi oturanlarla beraber oturalım.\" dediler.', 'واذا انزلت سورة ان امنوا بالله وجهدوا مع رسوله استذنك اولوا الطول منهم وقالوا ذرنا نكن مع القعدين'),
(1322, 9, 87, 'رَضُوا بِاَنْ يَكُونُوا مَعَ الْخَوَالِفِ وَطُبِـعَ عَلٰى قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'Radu bi en yekunu meal havalifi ve tubia ala kulubihim fe hum la yefkahun.', 'Onlar,  geride kalanlarla[1] beraber olmayı tercih ettiler. Kalpleri[2] mühürlendi,  artık onlar anlamazlar.', 'رضوا بان يكونوا مع الخوالف وطبع علي قلوبهم فهم لا يفقهون'),
(1323, 9, 88, 'لٰكِنِ الرَّسُولُ وَالَّذ۪ينَ اٰمَنُوا مَعَهُ جَاهَدُوا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْۜ وَاُو۬لٰٓئِكَ لَهُمُ الْخَيْرَاتُۘ وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Lakinir resulu vellezine amenu meahu cahedu bi emvalihim ve enfusihim, ve ulaike lehumul hayratu ve ulaike humul muflihun.', 'Fakat Resul ve onunla birlikte iman edenler,  mallarıyla,  canlarıyla cihad ettiler. İşte onlar,  bütün hayırlar onlarındır. İşte kurtuluşa erenler onlardır.', 'لكن الرسول والذين امنوا معه جهدوا بامولهم وانفسهم واوليك لهم الخيرات واوليك هم المفلحون'),
(1324, 9, 89, 'اَعَدَّ اللّٰهُ لَهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ ذٰلِكَ الْفَوْزُ الْعَظ۪يمُ۟', 'Eaddallahu lehum cennatin tecri min tahtihel enharu halidine fiha, zalikel fevzul azim.', 'Allah,  onlar için içinden ırmaklar akan,  içinde süresiz kalacakları Cennetler hazırlamıştır. İşte büyük başarı budur.', 'اعد الله لهم جنت تجري من تحتها الانهر خلدين فيها ذلك الفوز العظيم'),
(1325, 9, 90, 'وَجَٓاءَ الْمُعَذِّرُونَ مِنَ الْاَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ الَّذ۪ينَ كَذَبُوا اللّٰهَ وَرَسُولَهُۜ سَيُص۪يبُ الَّذ۪ينَ كَفَرُوا مِنْهُمْ عَذَابٌ اَل۪يمٌ', 'Ve cael muazzirune minel a\'rabi li yu\'zene lehum ve ka\'adellezine kezebullahe ve resuleh, se yusibullezine keferu minhum azabun elim.', 'Özür beyan eden Bedevi Araplar,  kendilerine izin verilmesi için geldiler. Allah\'a ve Resul\'üne yalan söyleyenler ise oturup kaldılar. Onlardan Kafir olanlara yakında can yakıcı bir azap dokunacaktır.', 'وجا المعذرون من الاعراب ليوذن لهم وقعد الذين كذبوا الله ورسوله سيصيب الذين كفروا منهم عذاب اليم'),
(1326, 9, 91, 'لَيْسَ عَلَى الضُّعَفَٓاءِ وَلَا عَلَى الْمَرْضٰى وَلَا عَلَى الَّذ۪ينَ لَا يَجِدُونَ مَا يُنْفِقُونَ حَرَجٌ اِذَا نَصَحُوا لِلّٰهِ وَرَسُولِه۪ۜ مَا عَلَى الْمُحْسِن۪ينَ مِنْ سَب۪يلٍۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌۙ', 'Leyse alad duafai ve la alel merda ve la alellezine la yecidune ma yunfikune haracun iza nasahu lillahi ve resulih, ma alel muhsinine min sebil, vallahu gafurun rahim.', 'Zayıflara,  hastalara ve harcayacakları bir şeyi olmayanlara,  Allah ve Resul\'üne bağlı kaldıkları sürece bir sorumluluk yoktur. İyilik edenlerin aleyhine de bir yol yoktur. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ليس علي الضعفا ولا علي المرضي ولا علي الذين لا يجدون ما ينفقون حرج اذا نصحوا لله ورسوله ما علي المحسنين من سبيل والله غفور رحيم'),
(1327, 9, 92, 'وَلَا عَلَى الَّذ۪ينَ اِذَا مَٓا اَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَٓا اَجِدُ مَٓا اَحْمِلُكُمْ عَلَيْهِۖ تَوَلَّوْا وَاَعْيُنُهُمْ تَف۪يضُ مِنَ الدَّمْعِ حَزَناً اَلَّا يَجِدُوا مَا يُنْفِقُونَۜ', 'Ve la alellezine iza ma etevke li tahmilehum kulte la ecidu maahmilukum aleyhi tevellev ve a\'yunuhum tefidu mined dem\'i hazenen ella yecidu ma yunfikun.', 'Bir de; sana,  kendilerine binek sağlaman için başvurduklarında,  \"Sizi bindirecek bir şey bulamıyorum.\" dediğin zaman,  harcayacakları bir şeyleri olmadığı için üzüntüden gözlerinden yaşlar akıtarak geri dönüp gidenlere de bir sorumluluk yoktur.', 'ولا علي الذين اذا ما اتوك لتحملهم قلت لا اجد ما احملكم عليه تولوا واعينهم تفيض من الدمع حزنا الا يجدوا ما ينفقون'),
(1328, 9, 93, 'اِنَّمَا السَّب۪يلُ عَلَى الَّذ۪ينَ يَسْتَأْذِنُونَكَ وَهُمْ اَغْنِيَٓاءُۚ رَضُوا بِاَنْ يَكُونُوا مَعَ الْخَوَالِفِۙ وَطَبَعَ اللّٰهُ عَلٰى قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', 'İnnemes sebilu alellezine yeste\'zinuneke ve hum agniya\', radu bi en yekunu meal havalifi ve tabeallahu ala kulubihim fe hum la ya\'lemun.', 'Ancak imkanları olduğu halde senden izin isteyenler kınanmalıdır. Onlar,  geride kalanlarla beraber olmayı istediler. Allah da onların kalplerini mühürledi. Bu yüzden artık onlar yaptıkları yanlışı idrak etmezler.', 'انما السبيل علي الذين يستذنونك وهم اغنيا رضوا بان يكونوا مع الخوالف وطبع الله علي قلوبهم فهم لا يعلمون'),
(1329, 9, 94, 'يَعْتَذِرُونَ اِلَيْكُمْ اِذَا رَجَعْتُمْ اِلَيْهِمْۜ قُلْ لَا تَعْتَذِرُوا لَنْ نُؤْمِنَ لَكُمْ قَدْ نَبَّاَنَا اللّٰهُ مِنْ اَخْبَارِكُمْۜ وَسَيَرَى اللّٰهُ عَمَلَكُمْ وَرَسُولُهُ ثُمَّ تُرَدُّونَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ya\'tezirune ileykum iza reca\'tum ileyhim, kul la ta\'teziru len nu\'mine lekum kad nebbe enallahu min ahbarikum, ve se yerallahu amelekum ve resuluhu summe tureddune ila alimil gaybi veş şehadeti fe yunebbiukum bi ma kuntum ta\'melun.', 'Onlara döndüğünüz zaman size mazeret ileri sürerler. De ki: \"Mazeret ileri sürmeyin,  size asla inanmayacağız. Allah,  durumunuzdan bizi haberdar etti. Allah ve Resulü yapacaklarınızı görecektir. Sonra,  görüneni ve görünmeyeni bilene döndürüleceksiniz. O,  bütün yaptıklarınızı size bildirecektir.\"', 'يعتذرون اليكم اذا رجعتم اليهم قل لا تعتذروا لن نومن لكم قد نبانا الله من اخباركم وسيري الله عملكم ورسوله ثم تردون الي علم الغيب والشهدة فينبيكم بما كنتم تعملون'),
(1330, 9, 95, 'سَيَحْلِفُونَ بِاللّٰهِ لَكُمْ اِذَا انْقَلَبْتُمْ اِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْۜ فَاَعْرِضُوا عَنْهُمْۜ اِنَّهُمْ رِجْسٌۘ وَمَأْوٰيهُمْ جَهَنَّمُۚ جَزَٓاءً بِمَا كَانُوا يَكْسِبُونَ', 'Se yahlifune billahi lekum izenkalebtum ileyhim li tu\'ridu anhum, fe a\'rıdu anhum, innehum ricsun ve me\'vahum cehennem , cezaen bi ma kanu yeksibun.', 'Onlara döndüğünüz zaman,  kendilerinden vazgeçmeniz için[1] Allah\'a yemin edecekler. Onlardan yüz çevirin. Çünkü onlar murdardır[2]. Yaptıklarının karşılığı olarak varacakları yer Cehennem\'dir.', 'سيحلفون بالله لكم اذا انقلبتم اليهم لتعرضوا عنهم فاعرضوا عنهم انهم رجس وماويهم جهنم جزا بما كانوا يكسبون'),
(1331, 9, 96, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْۚ فَاِنْ تَرْضَوْا عَنْهُمْ فَاِنَّ اللّٰهَ لَا يَرْضٰى عَنِ الْقَوْمِ الْفَاسِق۪ينَ', 'Yahlifune lekum li terdav anhum, fe in terdav anhum fe innallahe la yerda anil kavmil fasikin.', 'Kendilerini hoş göresiniz diye,  size yemin ederler. Siz,  onlardan razı olsanız da bilesiniz ki Allah fasık olan toplumdan asla razı olmaz.', 'يحلفون لكم لترضوا عنهم فان ترضوا عنهم فان الله لا يرضي عن القوم الفسقين'),
(1332, 9, 97, 'اَلْاَعْرَابُ اَشَدُّ كُفْراً وَنِفَاقاً وَاَجْدَرُ اَلَّا يَعْلَمُوا حُدُودَ مَٓا اَنْزَلَ اللّٰهُ عَلٰى رَسُولِه۪ۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'El a\'rabu eşeddu kufren ve nifakan ve ecderu ella ya\'lemu hududema enzelallahu ala resulih, vallahu alimun hakim.', 'Bedevi Araplar,  küfür[1] ve nifakta[2] daha katıdırlar. Allah\'ın Resulüne indirdiği sınırları tanımamaya daha yatkındırlar. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'الاعراب اشد كفرا ونفاقا واجدر الا يعلموا حدود ما انزل الله علي رسوله والله عليم حكيم'),
(1333, 9, 98, 'وَمِنَ الْاَعْرَابِ مَنْ يَتَّخِذُ مَا يُنْفِقُ مَغْرَماً وَيَتَرَبَّصُ بِكُمُ الدَّوَٓائِرَۜ عَلَيْهِمْ دَٓائِرَةُ السَّوْءِۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'Ve minel a\'rabi men yettehızu ma yunfiku magremen ve yeterabbesu bi kumud devair, aleyhim dairetussev\' , vallahu semiun alim.', 'Bedevi Araplardan kimisi de yaptığı infakı[1] zarar sayar ve devrin değişmesini ve sizin başınıza kötü devirlerin[2] gelmesini beklerler. Kötü devirler kendi başlarına gelsin. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'ومن الاعراب من يتخذ ما ينفق مغرما ويتربص بكم الدواير عليهم دايرة السو والله سميع عليم'),
(1334, 9, 99, 'وَمِنَ الْاَعْرَابِ مَنْ يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَيَتَّخِذُ مَا يُنْفِقُ قُرُبَاتٍ عِنْدَ اللّٰهِ وَصَلَوَاتِ الرَّسُولِۜ اَلَٓا اِنَّهَا قُرْبَةٌ لَهُمْۜ سَيُدْخِلُهُمُ اللّٰهُ ف۪ي رَحْمَتِه۪ۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ۟', 'Ve minel a\'rabi men yu\'minu billahi vel yevmil ahıri ve yettehızu ma yunfiku kurubatin indallahi ve salavatir resul, e la inneha kurbetunlehum, se yudhıluhumullahu fi rahmetih, innallahe gafurun rahim.', 'Bedevi Araplardan kimisi de Allah\'a ve Ahiret Günü\'ne inanır. İnfak ettiğini Allah katında yakınlığa ve Resul\'ün selavatına[1] vesile sayar. Gerçekten o,  kendileri için yakınlık vesilesidir. Allah,  onları rahmetine alacak. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ومن الاعراب من يومن بالله واليوم الاخر ويتخذ ما ينفق قربت عند الله وصلوت الرسول الا انها قربة لهم سيدخلهم الله في رحمته ان الله غفور رحيم'),
(1335, 9, 100, 'وَالسَّابِقُونَ الْاَوَّلُونَ مِنَ الْمُهَاجِر۪ينَ وَالْاَنْصَارِ وَالَّذ۪ينَ اتَّبَعُوهُمْ بِاِحْسَانٍۙ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوا عَنْهُ وَاَعَدَّ لَهُمْ جَنَّاتٍ تَجْر۪ي تَحْتَهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ ذٰلِكَ الْفَوْزُ الْعَظ۪يمُ', 'Ves sabikunel evvelune minel muhacirine vel ensari vellezinettebeuhum bi ıhsanin radıyallahu anhum ve radu anhu ve eadde lehum cennatin tecri tahtehel enharu halidine fiha ebeda, zalikel fevzul azim.', 'Muhacir[1] ve Ensar\'dan[2],  öne geçenlerden ve iyilikte onları izleyenlerden Allah razı olmuştur. Onlar da O\'ndan razı olmuştur. Onlara,  içinde aralıksız ve sürekli kalacakları,  içinden ırmaklar akan Cennetler hazırlamıştır. İşte büyük başarı budur.', 'والسبقون الاولون من المهجرين والانصار والذين اتبعوهم باحسن رضي الله عنهم ورضوا عنه واعد لهم جنت تجري تحتها الانهر خلدين فيها ابدا ذلك الفوز العظيم'),
(1336, 9, 101, 'وَمِمَّنْ حَوْلَكُمْ مِنَ الْاَعْرَابِ مُنَافِقُونَۜ وَمِنْ اَهْلِ الْمَد۪ينَةِ مَرَدُوا عَلَى النِّفَاقِ لَا تَعْلَمُهُمْۜ نَحْنُ نَعْلَمُهُمْۜ سَنُعَذِّبُهُمْ مَرَّتَيْنِ ثُمَّ يُرَدُّونَ اِلٰى عَذَابٍ عَظ۪يمٍۚ', 'Ve mimmen havlekum minel a\'rabi munafikun, ve min ehlil medineti meredu alen nifakı la ta\'lemuhum, nahnu na\'lemuhum, se nuazzibuhum merreteyni summe yureddune ila azabin azim.', 'Çevrenizdeki Bedevi Araplardan münafık olanlar vardır. Ve Medine halkından da nifakta ileri gidenler vardır. Sen onları bilemezsin. Biz onları biliriz. Onlara iki defa[1] azap edeceğiz. Sonra onlar,  daha büyük azaba uğratılacaklardır.', 'وممن حولكم من الاعراب منفقون ومن اهل المدينة مردوا علي النفاق لا تعلمهم نحن نعلمهم سنعذبهم مرتين ثم يردون الي عذاب عظيم'),
(1337, 9, 102, 'وَاٰخَرُونَ اعْتَرَفُوا بِذُنُوبِهِمْ خَلَطُوا عَمَلاً صَالِحاً وَاٰخَرَ سَيِّئاًۜ عَسَى اللّٰهُ اَنْ يَتُوبَ عَلَيْهِمْۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Ve aharuna\'terefu bi zunubihim haletu amelen salihan ve ahare seyyia, asallahu en yetube aleyhim, innallahe gafurun rahim.', 'Diğer bir kısmı da suçlarını itiraf ettiler. Onlar,  iyi bir ameli kötü bir amelle karıştırmışlardı. Belki Allah,  onların tevbesini[1] kabul eder. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'واخرون اعترفوا بذنوبهم خلطوا عملا صلحا واخر سييا عسي الله ان يتوب عليهم ان الله غفور رحيم'),
(1338, 9, 103, 'خُذْ مِنْ اَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكّ۪يهِمْ بِهَا وَصَلِّ عَلَيْهِمْۜ اِنَّ صَلٰوتَكَ سَكَنٌ لَهُمْۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'Huz min emvalihim sadakaten tutahhiruhum ve tuzekkihim biha ve salli aleyhim, inne salateke sekenun lehum, vallahu semiun alim.', 'Onların mallarından sadaka al; bununla onları temizleyip arındırırsın. Ve onlara salli[1] ol,  kuşkusuz senin salatın[1] onlara dinginlik verir. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'خذ من امولهم صدقة تطهرهم وتزكيهم بها وصل عليهم ان صلوتك سكن لهم والله سميع عليم'),
(1339, 9, 104, 'اَلَمْ يَعْلَمُٓوا اَنَّ اللّٰهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِه۪ وَيَأْخُذُ الصَّدَقَاتِ وَاَنَّ اللّٰهَ هُوَ التَّوَّابُ الرَّح۪يمُ', 'E lem ya\'lemu ennallahe huve yakbelut tevbete an ibadihi ve ye\'huzus sadakati ve ennallahe huvet tevvabur rahim.', 'Bilmediler mi ki kullarından tevbeyi[1] kabul eden ve sadakaları alan Allah\'tır. Kuşkusuz Allah,  Tevbeleri Kabul Eden\'dir,  Rahmeti Kesintisiz\'dir.', 'الم يعلموا ان الله هو يقبل التوبة عن عباده وياخذ الصدقت وان الله هو التواب الرحيم'),
(1340, 9, 105, 'وَقُلِ اعْمَلُوا فَسَيَرَى اللّٰهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَۜ وَسَتُرَدُّونَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَۚ', 'Ve kuli\'melu fe se yerallahu amelekum ve resuluhu vel mu\'minun, ve se tureddune ila alimil gaybi veş şehadeti fe yunebbiukum bi ma kuntum ta\'melun.', 'De ki: \"Ne yaparsanız yapın. Yaptıklarınızı Allah,  O\'nun Resulü ve Mü\'minler görecekler. Sonra,  görüneni de görünmeyeni de Bilen\'e döndürüleceksiniz. O,  size yaptıklarınızı haber verecektir.\"', 'وقل اعملوا فسيري الله عملكم ورسوله والمومنون وستردون الي علم الغيب والشهدة فينبيكم بما كنتم تعملون'),
(1341, 9, 106, 'وَاٰخَرُونَ مُرْجَوْنَ لِاَمْرِ اللّٰهِ اِمَّا يُعَذِّبُهُمْ وَاِمَّا يَتُوبُ عَلَيْهِمْۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ve aharune murcevne li emrillahi imma yuazzibuhum ve imma yetubu aleyhim, vallahu alimun hakim.', 'Geri kalan bir bölümün işi de Allah\'ın yargısına kalmıştır; onlara ya azap eder veya tevbelerini kabul eder. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'واخرون مرجون لامر الله اما يعذبهم واما يتوب عليهم والله عليم حكيم'),
(1342, 9, 107, 'وَالَّذ۪ينَ اتَّخَذُوا مَسْجِداً ضِرَاراً وَكُفْراً وَتَفْر۪يقاً بَيْنَ الْمُؤْمِن۪ينَ وَاِرْصَاداً لِمَنْ حَارَبَ اللّٰهَ وَرَسُولَهُ مِنْ قَبْلُۜ وَلَيَحْلِفُنَّ اِنْ اَرَدْنَٓا اِلَّا الْحُسْنٰىۜ وَاللّٰهُ يَشْهَدُ اِنَّهُمْ لَكَاذِبُونَ', 'Vellezinettehazu mesciden dıraren ve kufren ve tefrikan beynel mu\'minine ve irsaden li men hareballahe ve resulehu min kabl, ve le yahlifunne in eredna illelhusna, vallahu yeşhedu innehum le kazibun.', 'Zarar vermek,  inkar etmek,  nifak[1] çıkarmak,  Allah ve Resul\'üne karşı daha önce savaşanlara gözcülük yapmak[2] üzere bir mescit yapan kimseler: \"Biz yalnızca iyilik yapmak istedik.\" diye yemin ederler. Oysaki Allah,  onların yalan söylediklerine tanıktır.', 'والذين اتخذوا مسجدا ضرارا وكفرا وتفريقا بين المومنين وارصادا لمن حارب الله ورسوله من قبل وليحلفن ان اردنا الا الحسني والله يشهد انهم لكذبون'),
(1343, 9, 108, 'لَا تَقُمْ ف۪يهِ اَبَداًۜ لَمَسْجِدٌ اُسِّسَ عَلَى التَّقْوٰى مِنْ اَوَّلِ يَوْمٍ اَحَقُّ اَنْ تَقُومَ ف۪يهِۜ ف۪يهِ رِجَالٌ يُحِبُّونَ اَنْ يَتَطَهَّرُواۜ وَاللّٰهُ يُحِبُّ الْمُطَّهِّر۪ينَ', 'La tekum fihi ebeda, le mescidun ussise alet takva min evveli yevmin ehakku en tekume fih, fihi ricalun yuhıbbune en yetetahheru, vallahu yuhıbbul muttahhirin.', 'Orada asla durma[1],  ilk yapıldığında takva üzere yapılan mescit,  içinde bulunmaya daha layıktır. Orada arınmayı seven kişiler vardır. Allah,  arınmak isteyenleri sever.', 'لا تقم فيه ابدا لمسجد اسس علي التقوي من اول يوم احق ان تقوم فيه فيه رجال يحبون ان يتطهروا والله يحب المطهرين'),
(1344, 9, 109, 'اَفَمَنْ اَسَّسَ بُنْيَانَهُ عَلٰى تَقْوٰى مِنَ اللّٰهِ وَرِضْوَانٍ خَيْرٌ اَمْ مَنْ اَسَّسَ بُنْيَانَهُ عَلٰى شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِه۪ ف۪ي نَارِ جَهَنَّمَۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'E fe men essese bunyanehu ala takva minallahi ve rıdvanin hayrun em men essese bunyanehu ala şefa curufin harin fenhare bihi fi nari cehennem, vallahu la yehdil kavmez zalimin.', 'Binasını takva üzere,  Allah rızası için kuran kimse mi,  yoksa binasını uçurumun kenarına kurup da onunla birlikte Cehennem ateşinin içine yuvarlanan kimse mi hayırlı olandır? Allah,  zalim halkı doğru yola iletmez.', 'افمن اسس بنينه علي تقوي من الله ورضون خير ام من اسس بنينه علي شفا جرف هار فانهار به في نار جهنم والله لا يهدي القوم الظلمين'),
(1345, 9, 110, 'لَا يَزَالُ بُنْيَانُهُمُ الَّذ۪ي بَنَوْا ر۪يبَةً ف۪ي قُلُوبِهِمْ اِلَّٓا اَنْ تَقَطَّعَ قُلُوبُهُمْۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ۟', 'La yezalu bunyanuhumullezi benev ribeten fi kulubihim illa en tekattaa kulubuhum, vallahu alimun hakim.', 'Onların kalpleri parçalanmadıkça,  kurdukları yapı,  kalplerinde bir kuşku olarak sürüp gidecektir. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'لا يزال بنينهم الذي بنوا ريبة في قلوبهم الا ان تقطع قلوبهم والله عليم حكيم'),
(1346, 9, 111, 'اِنَّ اللّٰهَ اشْتَرٰى مِنَ الْمُؤْمِن۪ينَ اَنْفُسَهُمْ وَاَمْوَالَهُمْ بِاَنَّ لَهُمُ الْجَنَّةَۜ يُقَاتِلُونَ ف۪ي سَب۪يلِ اللّٰهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْداً عَلَيْهِ حَقاًّ فِي التَّوْرٰيةِ وَالْاِنْج۪يلِ وَالْقُرْاٰنِۜ وَمَنْ اَوْفٰى بِعَهْدِه۪ مِنَ اللّٰهِ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذ۪ي بَايَعْتُمْ بِه۪ۜ وَذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُ', 'İnnallaheştera minel mu\'minine enfusehum ve emvalehum bi enne lehumul cenneh, yukatilune fi sebilillahi fe yaktulune ve yuktelune va\'den aleyhi hakkan fit tevrati vel incili vel kur\'an, ve men evfa bi ahdihi minallahi, festebşiru bi bey\'ıkumullezi baya\'tum bih , ve zalike huvel fevzul azim.', 'Allah,  kendi yolunda savaşarak ölen ve öldüren mü\'minlerin; canlarını ve mallarını Cennet karşılığında satın almıştır. Bu,  Tevrat\'ta,  İncil\'de ve Kur\'an\'da gerçek olan bir söz vermedir. Allah\'tan daha iyi sözünde duran kim olabilir? O halde,  O\'nunla yapmış olduğunuz bu alışverişten dolayı sevinin. İşte büyük başarı budur.', 'ان الله اشتري من المومنين انفسهم وامولهم بان لهم الجنة يقتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التورية والانجيل والقران ومن اوفي بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم'),
(1347, 9, 112, 'اَلتَّٓائِبُونَ الْعَابِدُونَ الْحَامِدُونَ السَّٓائِحُونَ الرَّاكِعُونَ السَّاجِدُونَ الْاٰمِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ الْمُنْكَرِ وَالْحَافِظُونَ لِحُدُودِ اللّٰهِۜ  وَبَشِّرِ الْمُؤْمِن۪ينَ', 'Ettaibunel abidunel hamidunes saihuner rakiunes sacidunel amirune bil ma\'rufi ven nahune anil munkeri vel hafizune li hududillah , ve beşşiril mu\'minin .', 'Tevbe edenler,  kulluk edenler,  hamd edenler[1],  seyahat edenler[2],  ruku edenler[3],  secde edenler[4],  mar\'uf olanı yapıp,  münker olana engel olanlar;[5] Allah\'ın hudutlarını koruyanlardır. Mü\'minleri müjdele.', 'التيبون العبدون الحمدون السيحون الركعون السجدون الامرون بالمعروف والناهون عن المنكر والحفظون لحدود الله وبشر المومنين'),
(1348, 9, 113, 'مَا كَانَ لِلنَّبِيِّ وَالَّذ۪ينَ اٰمَنُٓوا اَنْ يَسْتَغْفِرُوا لِلْمُشْرِك۪ينَ وَلَوْ كَانُٓوا اُو۬ل۪ي قُرْبٰى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ اَنَّهُمْ اَصْحَابُ الْجَح۪يمِ', 'Ma kane lin nebiyyi vellezine amenu en yestagfiru lil muşrikine ve lev kanu uli kurba min ba\'di ma tebeyyene lehum ennehum ashabul cahim.', 'Nebi ve mü\'minlere; Cehennemlik oldukları açıkça belli olduktan sonra,  yakınları da olsa,  müşriklere bağışlanma dilemeleri yaraşmaz.', 'ما كان للنبي والذين امنوا ان يستغفروا للمشركين ولو كانوا اولي قربي من بعد ما تبين لهم انهم اصحب الجحيم'),
(1349, 9, 114, 'وَمَا كَانَ اسْتِغْفَارُ اِبْرٰه۪يمَ لِاَب۪يهِ اِلَّا عَنْ مَوْعِدَةٍ وَعَدَهَٓا اِيَّاهُۚ فَلَمَّا تَبَيَّنَ لَـهُٓ اَنَّهُ عَدُوٌّ لِلّٰهِ تَبَرَّاَ مِنْهُۜ اِنَّ اِبْرٰه۪يمَ لَاَوَّاهٌ حَل۪يمٌ', 'Ve ma kanestigfaru ibrahime li ebihi illa an mev\'ıdetin vaadeha iyyah, fe lemma tebeyyene lehu ennehuaduvvun lillahi teberre\'e minh, inne ibrahime le evvahun halim.', 'İbrahim\'in babası için bağışlanma dilemesinin sebebi,  ona söz vermiş olmasıydı. Ama onun,  Allah\'a düşman olduğu kendisine açıkça belli olunca,  ondan uzaklaştı. Kuşkusuz İbrahim,  çok ince ruhlu ve yumuşak huylu biriydi.', 'وما كان استغفار ابرهيم لابيه الا عن موعدة وعدها اياه فلما تبين له انه عدو لله تبرا منه ان ابرهيم لاوه حليم'),
(1350, 9, 115, 'وَمَا كَانَ اللّٰهُ لِيُضِلَّ قَوْماً بَعْدَ اِذْ هَدٰيهُمْ حَتّٰى يُبَيِّنَ لَهُمْ مَا يَتَّقُونَۜ اِنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Ve ma kanallahu li yudılle kavmen ba\'de iz hedahum hatta yubeyyine lehum ma yettekun, innallahe bi kulli şey\'in alim.', 'Allah,  bir halkı doğru yola ilettikten sonra,  sakınıp korunacakları şeyleri kendilerine açıklamadıkça onları sapıtmış saymaz.[1] Allah,  Her Şeyi En İyi Bilendir.', 'وما كان الله ليضل قوما بعد اذ هديهم حتي يبين لهم ما يتقون ان الله بكل شي عليم'),
(1351, 9, 116, 'اِنَّ اللّٰهَ لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ يُحْـي۪ وَيُم۪يتُۜ وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'İnnallahe lehu mulkus semavati vel ard, yuhyi ve yumit, ve ma lekum min dunillahi min veliyyin ve la nasir.', 'Göklerin ve yerin mülkü[1] Allah\'ındır. Yaşatan ve öldüren O\'dur. Sizin,  Allah\'tan başka bir veli[2] ve bir yardımcınız yoktur.', 'ان الله له ملك السموت والارض يحي ويميت وما لكم من دون الله من ولي ولا نصير'),
(1352, 9, 117, 'لَقَدْ تَابَ اللّٰهُ عَلَى النَّبِيِّ وَالْمُهَاجِر۪ينَ وَالْاَنْصَارِ الَّذ۪ينَ اتَّبَعُوهُ ف۪ي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَز۪يغُ قُلُوبُ فَر۪يقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْۜ اِنَّهُ بِهِمْ رَؤُ۫فٌ رَح۪يمٌۙ', 'Lekad taballahu alen nebiyyi vel muhacirine vel ensarillezinet tebeuhu fi saatil usreti min ba\'di ma kade yezigu kulubu ferikın minhum summe tabe aleyhim, innehu bihim raufun rahim.', 'Ant olsun ki,  Allah,  Nebi\'nin ve zor şartlarda ona destek olan muhacir ve ensarın tevbelerini[1] kabul etti. İçlerinden bir kısmının kalpleri kaymak üzereyken yine de onların tevbelerini kabul etti. Çünkü O,  onlara karşı Çok Şefkatli\'dir,  Rahmeti Kesintisiz\'dir.', 'لقد تاب الله علي النبي والمهجرين والانصار الذين اتبعوه في ساعة العسرة من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم انه بهم روف رحيم'),
(1353, 9, 118, 'وَعَلَى الثَّلٰثَةِ الَّذ۪ينَ خُلِّفُواۜ حَتّٰٓى اِذَا ضَاقَتْ عَلَيْهِمُ الْاَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ اَنْفُسُهُمْ وَظَنُّٓوا اَنْ لَا مَلْجَأَ مِنَ اللّٰهِ اِلَّٓا اِلَيْهِۜ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُواۜ اِنَّ اللّٰهَ هُوَ التَّوَّابُ الرَّح۪يمُ۟', 'Ve ales selasetillezine hullifu, hatta iza dakat aleyhimul ardu bima rehubet ve dakat aleyhim enfusuhum ve zannu en la melcee minallahi illa ileyh, summe tabe aleyhim li yetubu, innallahe huvet tevvabur rahim.', 'Ve geri bırakılan üç kişinin tevbesini de kabul etti. Öyle ki,  bütün genişliğine rağmen,  yeryüzü onlara dar gelmişti. Canları sıkıldıkça sıkılmıştı. Ve Allah\'tan başka sığınılacak kimse olmadığını anladılar. Sonra Allah,  tevbeye yöneldikleri için[1],  tevbelerini kabul etti. Kuşkusuz Allah,  Tevbeleri Kabul Eden\'dir,  Rahmeti Kesintisiz\'dir.', 'وعلي الثلثة الذين خلفوا حتي اذا ضاقت عليهم الارض بما رحبت وضاقت عليهم انفسهم وظنوا ان لا ملجا من الله الا اليه ثم تاب عليهم ليتوبوا ان الله هو التواب الرحيم'),
(1354, 9, 119, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَكُونُوا مَعَ الصَّادِق۪ينَ', 'Ya eyyuhellezine amenuttekullahe ve kunu meas sadikin .', 'Ey iman edenler! Allah\'a karşı takva sahibi olun ve sadıklarla[1] birlikte olun.', 'يايها الذين امنوا اتقوا الله وكونوا مع الصدقين'),
(1355, 9, 120, 'مَا كَانَ لِاَهْلِ الْمَد۪ينَةِ وَمَنْ حَوْلَهُمْ مِنَ الْاَعْرَابِ اَنْ يَتَخَلَّفُوا عَنْ رَسُولِ اللّٰهِ وَلَا يَرْغَبُوا بِاَنْفُسِهِمْ عَنْ نَفْسِه۪ۜ ذٰلِكَ بِاَنَّهُمْ لَا يُص۪يبُهُمْ ظَمَاٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ ف۪ي سَب۪يلِ اللّٰهِ وَلَا يَطَؤُ۫نَ مَوْطِئاً يَغ۪يظُ الْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَيْلاً اِلَّا كُتِبَ لَهُمْ بِه۪ عَمَلٌ صَالِحٌۜ اِنَّ اللّٰهَ لَا يُض۪يعُ اَجْرَ الْمُحْسِن۪ينَۙ', 'Ma kane li ehlil medineti ve men havlehum minel a\'rabi en yetehallefu an resulillahi ve la yergabu bi enfusihim an nefsih, zalike bi ennehum la yusibuhum zameun ve la nasabun ve la mahmesatun fi sebilillahi ve la yetaune mevtıan yagizul kuffare ve la yenalune min aduvvin neylen illa kutibe lehum bihi amelun salih, innallahe la yudiu ecrel muhsinin.', 'Ne Medine halkının ne de etrafındaki Bedevi Arapların,  Allah\'ın Resul\'ünden geri kalmaları ve onun canından önce kendi canlarının kaygısına düşmeleri olacak şeydir. Çünkü Allah yolunda katlanacakları susuzluk,  yorgunluk,  açlık ve Kafirleri kızdıracak bir yeri zapt etmeleri ve düşmana karşı elde ettikleri başarı,  kendilerine salih bir amel olarak yazılacaktır. Zira Allah,  muhsin[1] olanların kazanımlarını yok etmez.', 'ما كان لاهل المدينة ومن حولهم من الاعراب ان يتخلفوا عن رسول الله ولا يرغبوا بانفسهم عن نفسه ذلك بانهم لا يصيبهم ظما ولا نصب ولا مخمصة في سبيل الله ولا يطون موطيا يغيظ الكفار ولا ينالون من عدو نيلا الا كتب لهم به عمل صلح ان الله لا يضيع اجر المحسنين'),
(1356, 9, 121, 'وَلَا يُنْفِقُونَ نَفَقَةً صَغ۪يرَةً وَلَا كَب۪يرَةً وَلَا يَقْطَعُونَ وَادِياً اِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ اللّٰهُ اَحْسَنَ مَا كَانُوا يَعْمَلُونَ', 'Ve la yunfikune nefakaten sagireten ve la kebireten ve la yaktaune vadien illa kutibe lehum li yecziyehumullahu ahsene ma kanu ya\'melun.', 'Büyük veya küçük,  yaptıkları her yardım ve güçlük içinde aştıkları her vadi,  kendilerine yazılacaktır. Allah,  yaptıklarından daha iyisiyle kendilerini ödüllendirecektir.', 'ولا ينفقون نفقة صغيرة ولا كبيرة ولا يقطعون واديا الا كتب لهم ليجزيهم الله احسن ما كانوا يعملون'),
(1357, 9, 122, 'وَمَا كَانَ الْمُؤْمِنُونَ لِيَنْفِرُوا كَٓافَّةًۜ فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَٓائِفَةٌ لِيَتَفَقَّهُوا فِي الدّ۪ينِ وَلِيُنْذِرُوا قَوْمَهُمْ اِذَا رَجَعُٓوا اِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ۟', 'Ve ma kanel mu\'minune li yenfiru kaffeh, fe lev la nefere min kulli firkatin minhum taifetun li yetefekkahu fid dini ve li yunziru kavmehum iza receu ileyhim leallehum yahzerun.', 'Mü\'minlerin toptan seferber olmaları uygun değildir. Dinde bilgi edinmek için her grubun içinden bir takım kimseler gitmeli ve döndüklerinde halklarını bilgilendirmelidirler. Umulur ki onlar sakınırlar.[1]', 'وما كان المومنون لينفروا كافة فلولا نفر من كل فرقة منهم طايفة ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون'),
(1358, 9, 123, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا قَاتِلُوا الَّذ۪ينَ يَلُونَكُمْ مِنَ الْكُفَّارِ وَلْيَجِدُوا ف۪يكُمْ غِلْظَةًۜ وَاعْلَمُٓوا اَنَّ اللّٰهَ مَعَ الْمُتَّق۪ينَ', 'Ya eyyuhellezine amenu katilullezine yelunekum minel kuffari vel yecidu fikum gilzah, va\'lemu ennallahe meal muttekin.', 'Ey iman edenler! Size yakın olan[1] Kafirlerle savaşın. Ve onlar,  sizde kararlılık görsünler. Bilin ki Allah,  takva sahibi olanlarla beraberdir.', 'يايها الذين امنوا قتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظة واعلموا ان الله مع المتقين'),
(1359, 9, 124, 'وَاِذَا مَٓا اُنْزِلَتْ سُورَةٌ فَمِنْهُمْ مَنْ يَقُولُ اَيُّـكُمْ زَادَتْهُ هٰذِه۪ٓ ا۪يمَاناًۚ فَاَمَّا الَّذ۪ينَ اٰمَنُوا فَزَادَتْهُمْ ا۪يمَاناً وَهُمْ يَسْتَبْشِرُونَ', 'Ve iza ma unzilet suretun fe minhum men yekulu eyyukum zadethu hazihi imana, fe emmellezine amenu fe zadethum imanen ve hum yestebşirun.', 'Ne zaman bir sure indirilse,  onlardan bazıları:[1] \"Bu hanginizin imanını arttırdı?\" derler. Bu,  iman edenlerin imanını arttırdı. Onlar,  müjdelenmelerine sevinirler.', 'واذا ما انزلت سورة فمنهم من يقول ايكم زادته هذه ايمنا فاما الذين امنوا فزادتهم ايمنا وهم يستبشرون'),
(1360, 9, 125, 'وَاَمَّا الَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ فَزَادَتْهُمْ رِجْساً اِلٰى رِجْسِهِمْ وَمَاتُوا وَهُمْ كَافِرُونَ', 'Ve emmellezine fi kulubihim maradun fe zadethum ricsen ila ricsihim ve matu ve hum kafirun.', 'Kalplerinde[1] hastalık olanlara gelince,  bu onların kötülüklerine kötülük katmıştır. Ve onlar Kafir olarak ölürler.', 'واما الذين في قلوبهم مرض فزادتهم رجسا الي رجسهم وماتوا وهم كفرون'),
(1361, 9, 126, 'اَوَلَا يَرَوْنَ اَنَّهُمْ يُفْتَنُونَ ف۪ي كُلِّ عَامٍ مَرَّةً اَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', 'E ve la yerevne ennehum yuftenune fi kulli amin merreten ev merreteyni summe la yetubune ve la hum yezzekkerun.', 'Kendilerinin yılda bir iki defa sınandıklarını görmüyorlar mı? Yine de tevbe edip öğüt almıyorlar!', 'اولا يرون انهم يفتنون في كل عام مرة او مرتين ثم لا يتوبون ولا هم يذكرون'),
(1362, 9, 127, 'وَاِذَا مَٓا اُنْزِلَتْ سُورَةٌ نَظَرَ بَعْضُهُمْ اِلٰى بَعْضٍۜ هَلْ يَرٰيكُمْ مِنْ اَحَدٍ ثُمَّ انْصَرَفُواۜ صَرَفَ اللّٰهُ قُلُوبَهُمْ بِاَنَّهُمْ قَوْمٌ لَا يَفْقَهُونَ', 'Ve iza ma unzilet suretun nazara ba\'duhum ila ba\'d, hel yerakum min ehadin summensarafu, sarafallahu kulubehum bi ennehum kavmun la yefkahun.', 'Bir sure indirildiği zaman: \"Sizi gören var mı?\" diye birbirlerine bakar,  sonra da dönüp giderler. Allah,  onların kalplerini çevirmiştir. Çünkü onlar,  düşünmeyen bir halktır.', 'واذا ما انزلت سورة نظر بعضهم الي بعض هل يريكم من احد ثم انصرفوا صرف الله قلوبهم بانهم قوم لا يفقهون'),
(1363, 9, 128, 'لَقَدْ جَٓاءَكُمْ رَسُولٌ مِنْ اَنْفُسِكُمْ عَز۪يزٌۘ عَلَيْهِ مَا عَنِتُّمْ حَر۪يصٌ عَلَيْكُمْ بِالْمُؤْمِن۪ينَ رَؤُ۫فٌ رَح۪يمٌ', 'Lekad caekum resulun min enfusikum aziz, aleyhi ma anittum harisun aleykum bil mu\'minine raufun rahim.', 'Ant olsun ki,  size kendinizden bir Resul geldi. Sıkıntıya düşmeniz ona ağır gelir; o,  size düşkün,  Mü\'minlere şefkatli ve merhametlidir.', 'لقد جاكم رسول من انفسكم عزيز عليه ما عنتم حريص عليكم بالمومنين روف رحيم'),
(1364, 9, 129, 'فَاِنْ تَوَلَّوْا فَقُلْ حَسْبِيَ اللّٰهُۘ  لَٓا اِلٰهَ اِلَّا هُوَۜ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظ۪يمِ', 'Fe in tevellev fe kul hasbiyallah, la ilahe illa huv, aleyhi tevekkeltu ve huve rabbul arşil azim.', 'Eğer yüz çevirirlerse de ki: \"Allah bana yeter. O\'ndan başka ilah yoktur. Ben O\'na tevekkül[1] ettim. O,  Büyük Arş\'ın Rabb\'idir.\"', 'فان تولوا فقل حسبي الله لا اله الا هو عليه توكلت وهو رب العرش العظيم'),
(1365, 10, 1, 'الٓـرٰ۠ تِلْكَ اٰيَاتُ الْكِتَابِ الْحَك۪يمِ', 'Elif lam ra, tilke ayatul kitabil hakim.', 'Elif,  Lam,  Ra. İşte bunlar Hakim[1] Kitap\'ın ayetleridir.', 'الر تلك ايت الكتب الحكيم'),
(1366, 10, 2, 'اَكَانَ لِلنَّاسِ عَجَباً اَنْ اَوْحَيْنَٓا اِلٰى رَجُلٍ مِنْهُمْ اَنْ اَنْذِرِ النَّاسَ وَبَشِّرِ الَّذ۪ينَ اٰمَنُٓوا اَنَّ لَهُمْ قَدَمَ صِدْقٍ عِنْدَ رَبِّهِمْۜ قَالَ الْكَافِرُونَ اِنَّ هٰذَا لَسَاحِرٌ مُب۪ينٌ', 'E kane linnasi aceben en evhayna ila reculin minhum en enzirin nase ve beşşirillezine amenu enne lehum kademe sıdkın inde rabbihim, kalel kafirune inne haza le sahırun mubin.', 'İçlerinden birine: \"İnsanları uyar ve iman edenlere Rabb\'leri katında gerçek üstünlük makamı olduğunu haber ver!\" diye vahyetmemiz,  şaşılacak bir şey mi ki Kafirler[1]: \"Bu apaçık bir büyücüdür.\" dediler.', 'اكان للناس عجبا ان اوحينا الي رجل منهم ان انذر الناس وبشر الذين امنوا ان لهم قدم صدق عند ربهم قال الكفرون ان هذا لسحر مبين'),
(1367, 10, 3, 'اِنَّ رَبَّكُمُ اللّٰهُ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ ف۪ي سِتَّةِ اَيَّامٍ ثُمَّ اسْتَوٰى عَلَى الْعَرْشِ يُدَبِّرُ الْاَمْرَۜ مَا مِنْ شَف۪يعٍ اِلَّا مِنْ بَعْدِ اِذْنِه۪ۜ ذٰلِكُمُ اللّٰهُ رَبُّكُمْ فَاعْبُدُوهُۜ اَفَلَا تَذَكَّرُونَ', 'İnne rabbekumullahullezi halakas semavati vel arda fi sitteti eyyamin summesteva alel arşi yudebbirul emr, ma min şefiin illa min ba\'di iznih, zalikumullahu rabbukum fa\'buduh, e fe la tezekkerun.', 'Rabb\'iniz,  o Allah\'tır ki,  gökleri ve yeri altı günde[1] yarattı; sonra arşa isteva[2] etti. Bütün işlere yasalarını koydu. O\'nun izni[3] olmadan hiçbir şefaatçi olamaz.[4] İşte bu Rabb\'iniz olan Allah\'tır. Öyleyse O\'na kulluk edin. Hala düşünüp öğüt almaz mısınız?', 'ان ربكم الله الذي خلق السموت والارض في ستة ايام ثم استوي علي العرش يدبر الامر ما من شفيع الا من بعد اذنه ذلكم الله ربكم فاعبدوه افلا تذكرون'),
(1368, 10, 4, 'اِلَيْهِ مَرْجِعُكُمْ جَم۪يعاًۜ وَعْدَ اللّٰهِ حَقاًّۜ اِنَّهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُ لِيَجْزِيَ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ بِالْقِسْطِۜ وَالَّذ۪ينَ كَفَرُوا لَهُمْ شَرَابٌ مِنْ حَم۪يمٍ وَعَذَابٌ اَل۪يمٌ بِمَا كَانُوا يَكْفُرُونَ', 'İleyhi merciukum cemia, va\'dallahi hakka, innehu yebdeul halka summe yuiduhu li yecziyellezine amenu ve amilus salihati bil kıst, vellezine keferu lehum şerabun min hamimin ve azabun elimun bima kanu yekfurun.', 'Hepinizin dönüşü O\'nadır. Allah\'ın sözü haktır. O,  mahlukatı[1] önce yaratır,  sonra iman edip salihatı yapanlara[2] adaletle karşılık vermek için tekrar yaratır. Kafirler[3] ise küfürlerinden dolayı,  kaynar sudan içecek ve onlara can yakıcı bir azap vardır.', 'اليه مرجعكم جميعا وعد الله حقا انه يبدوا الخلق ثم يعيده ليجزي الذين امنوا وعملوا الصلحت بالقسط والذين كفروا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون'),
(1369, 10, 5, 'هُوَ الَّذ۪ي جَعَلَ الشَّمْسَ ضِيَٓاءً وَالْقَمَرَ نُوراً وَقَدَّرَهُ مَنَازِلَ لِتَعْلَمُوا عَدَدَ السِّن۪ينَ وَالْحِسَابَۜ مَا خَلَقَ اللّٰهُ ذٰلِكَ اِلَّا بِالْحَقِّۜ يُفَصِّلُ الْاٰيَاتِ لِقَوْمٍ يَعْلَمُونَ', 'Huvellezi cealeş şemse dıyaen vel kamere nuren ve kadderehu menazile li ta\'lemu adedes sinine vel hisab, ma halakallahu zalike illa bil hakk, yufassılul ayati li kavmin ya\'lemun.', 'Güneş\'i bir ziya[1],  Ay\'ı bir nur[2] yapan ve yılların sayısını ve hesabını bilmeniz için menziller[3] belirleyen O\'dur. Allah,  bunları ancak hakk ile yaratmıştır. O,  bilen bir halk için ayetlerini ayrıntılı olarak açıklamaktadır.', 'هو الذي جعل الشمس ضيا والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك الا بالحق يفصل الايت لقوم يعلمون'),
(1370, 10, 6, 'اِنَّ فِي اخْتِلَافِ الَّيْلِ وَالنَّهَارِ وَمَا خَلَقَ اللّٰهُ فِي السَّمٰوَاتِ وَالْاَرْضِ لَاٰيَاتٍ لِقَوْمٍ يَتَّقُونَ', 'İnne fihtilafil leyli ven nehari ve ma halakallahu fis semavati vel ardı le ayatin li kavmin yettekun.', 'Gece ile gündüzün birbiri ardınca gelmesinde,  Allah\'ın yarattığı göklerde ve yerde,  takva[1] sahibi bir halk için nice ayetler[2] vardır.', 'ان في اختلف اليل والنهار وما خلق الله في السموت والارض لايت لقوم يتقون'),
(1371, 10, 7, 'اِنَّ الَّذ۪ينَ لَا يَرْجُونَ لِقَٓاءَنَا وَرَضُوا بِالْحَيٰوةِ الدُّنْيَا وَاطْمَاَنُّوا بِهَا وَالَّذ۪ينَ هُمْ عَنْ اٰيَاتِنَا غَافِلُونَۙ', 'İnnellezine la yercune likaena ve radu bil hayatid dunya vatme\'ennu biha vellezine hum an ayatina gafilun.', 'Bizimle karşılaşacaklarını ummayanlar ve dünya hayatından hoşnut olup onunla tatmin olanlar ve ayetlerimizi görmezden gelenler...', 'ان الذين لا يرجون لقانا ورضوا بالحيوة الدنيا واطمانوا بها والذين هم عن ايتنا غفلون'),
(1372, 10, 8, 'اُو۬لٰٓئِكَ مَأْوٰيهُمُ النَّارُ بِمَا كَانُوا يَكْسِبُونَ', 'Ulaike me\'vahumun naru bima kanu yeksibun.', 'İşte onların,  yaptıklarına karşılık olarak,  varacakları yer ateştir.', 'اوليك ماويهم النار بما كانوا يكسبون'),
(1373, 10, 9, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ يَهْد۪يهِمْ رَبُّهُمْ بِا۪يمَانِهِمْۚ تَجْر۪ي مِنْ تَحْتِهِمُ الْاَنْهَارُ ف۪ي جَنَّاتِ النَّع۪يمِ', 'İnnellezine amenu ve amilus salihati yehdihim rabbuhum bi imanihim, tecri min tahtihimul enharu fi cennatin naim.', 'İman edip,  salihatı yapanlara[1] gelince,  imanlarından dolayı Rabb\'leri onları doğru yola iletir ve içlerinden ırmaklar akan Na\'im Cennetlerine koyar.', 'ان الذين امنوا وعملوا الصلحت يهديهم ربهم بايمنهم تجري من تحتهم الانهر في جنت النعيم'),
(1374, 10, 10, 'دَعْوٰيهُمْ ف۪يهَا سُبْحَانَكَ اللّٰهُمَّ وَتَحِيَّتُهُمْ ف۪يهَا سَلَامٌۚ وَاٰخِرُ دَعْوٰيهُمْ اَنِ الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَ۟', 'Da\'vahum fiha subhanekellahumme ve tehiyyetuhum fiha selam, ve ahıru da\'vahum enil hamdulillahi rabbil alemin.', 'Onların,  oradaki duası: \"Ey Allah\'ım! Seni tesbih[1] ederiz.\" Onların temennileri,  \"Selam\"dır.[2] Dualarının sonu ise: \"Âlemlerin Rabbi olan Allah\'a hamdolsun.\" dur.', 'دعويهم فيها سبحنك اللهم وتحيتهم فيها سلم واخر دعويهم ان الحمد لله رب العلمين'),
(1375, 10, 11, 'وَلَوْ يُعَجِّلُ اللّٰهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُمْ بِالْخَيْرِ لَقُضِيَ اِلَيْهِمْ اَجَلُهُمْۜ فَنَذَرُ الَّذ۪ينَ لَا يَرْجُونَ لِقَٓاءَنَا ف۪ي طُغْيَانِهِمْ يَعْمَهُونَ', 'Ve lev yuaccilullahu lin nasiş şerresti\'calehum bil hayri le kudiye ileyhim eceluhum, fe nezerullezine la yercune likaena fi tugyanihim ya\'mehun.', 'İnsanların,  hayrı acele istedikleri gibi,  Allah da şerri onlara acele verseydi,  muhakkak süreleri bitirilirdi. Ama Biz,  Bizimle karşılaşmayı ummayanları,  kendi hallerine bırakırız. Azgınlıkları içinde bocalar dururlar.', 'ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقانا في طغينهم يعمهون'),
(1376, 10, 12, 'وَاِذَا مَسَّ الْاِنْسَانَ الضُّرُّ دَعَانَا لِجَنْبِه۪ٓ اَوْ قَاعِداً اَوْ قَٓائِماًۚ فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُ مَرَّ كَاَنْ لَمْ يَدْعُنَٓا اِلٰى ضُرٍّ مَسَّهُۜ كَذٰلِكَ زُيِّنَ لِلْمُسْرِف۪ينَ مَا كَانُوا يَعْمَلُونَ', 'Ve iza messel insaned durru deana li cenbihi ev kaiden ev kaima, fe lemma keşefna anhu durrehu merre ke\'en lem yed\'una ila durrin messeh, kezalike zuyyine lil musrifine ma kanu ya\'melun.', 'İnsana bir sıkıntı dokununca,  yatarken,  otururken veya ayaktayken bize dua eder; fakat Biz onun sıkıntısını giderince de karşılaştığı sıkıntıdan ötürü sanki Bize hiç dua etmemiş gibi davranmaya devam eder. İşte Müsriflere[1],  yaptıkları şey böyle cazip gösterilmiştir.', 'واذا مس الانسن الضر دعانا لجنبه او قاعدا او قايما فلما كشفنا عنه ضره مر كان لم يدعنا الي ضر مسه كذلك زين للمسرفين ما كانوا يعملون'),
(1377, 10, 13, 'وَلَقَدْ اَهْلَكْنَا الْقُرُونَ مِنْ قَبْلِكُمْ لَمَّا ظَلَمُواۙ وَجَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ وَمَا كَانُوا لِيُؤْمِنُواۜ كَذٰلِكَ نَجْزِي الْقَوْمَ الْمُجْرِم۪ينَ', 'Ve lekad ehleknel kurune min kablikum lemma zalemu ve caethum rusuluhum bil beyyinati ve ma kanu li yu\'minu, kezalike neczil kavmel mucrimin.', 'Ant olsun Biz,  sizden önce nice nesilleri,  resulleri kendilerine kanıt içeren; açıklayıcı,  açığa çıkarıcı bilgi getirdiği halde iman etmeyip,  haksızlık yaptıkları için yok ettik. İşte suçlu halkları böyle cezalandırırız.', 'ولقد اهلكنا القرون من قبلكم لما ظلموا وجاتهم رسلهم بالبينت وما كانوا ليومنوا كذلك نجزي القوم المجرمين'),
(1378, 10, 14, 'ثُمَّ جَعَلْنَاكُمْ خَلَٓائِفَ فِي الْاَرْضِ مِنْ بَعْدِهِمْ لِنَنْظُرَ كَيْفَ تَعْمَلُونَ', 'Summe cealnakum halaife fil ardı min ba\'dihim li nanzure keyfe ta\'melun.', 'Sonra,  onların arkasından,  yeryüzünde sizi halifeler[1] yaptık ki bakalım nasıl davranacaksınız.', 'ثم جعلنكم خليف في الارض من بعدهم لننظر كيف تعملون'),
(1379, 10, 15, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍۙ قَالَ الَّذ۪ينَ لَا يَرْجُونَ لِقَٓاءَنَا ائْتِ بِقُرْاٰنٍ غَيْرِ هٰذَٓا اَوْ بَدِّلْهُۜ قُلْ مَا يَكُونُ ل۪ٓي اَنْ اُبَدِّلَهُ مِنْ تِلْقَٓائِ۬ نَفْس۪يۚ اِنْ اَتَّبِعُ اِلَّا مَا يُوحٰٓى اِلَيَّۚ اِنّ۪ٓي اَخَافُ اِنْ عَصَيْتُ رَبّ۪ي عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Ve iza tutla aleyhim ayatuna beyyinatin kalellezine la yercune likaena\'ti bi kur\'anin gayri haza ev beddilh, kul ma yekunu li en ubeddilehu min tilkai nefsi, in ettebiu illa ma yuha ileyy, inni ehafu in asaytu rabbi azabe yevmin azim.', 'Bizimle karşılaşmayı ummayanlara,  ayetlerimiz açık açık okunduğu zaman,  onlar: \"Ya bundan başka bir Kur\'an getir veya onu değiştir.\" dediler. De ki: \"Onu kendiliğimden değiştirmem olacak şey değildir. Ben,  ancak bana vahyolunana uyarım. Eğer Rabb\'ime karşı gelirsem,  büyük günün azabından korkarım.\"', 'واذا تتلي عليهم ايتنا بينت قال الذين لا يرجون لقانا ايت بقران غير هذا او بدله قل ما يكون لي ان ابدله من تلقاي نفسي ان اتبع الا ما يوحي الي اني اخاف ان عصيت ربي عذاب يوم عظيم'),
(1380, 10, 16, 'قُلْ لَوْ شَٓاءَ اللّٰهُ مَا تَلَوْتُهُ عَلَيْكُمْ وَلَٓا اَدْرٰيكُمْ بِه۪ۘ فَقَدْ لَبِثْتُ ف۪يكُمْ عُمُراً مِنْ قَبْلِه۪ۜ اَفَلَا تَعْقِلُونَ', 'Kul lev saallahu ma televtuhu aleykum ve la edrakum bihi, fe kad lebistu fikum umuren min kablih, e fe la ta\'kilun.', 'De ki: \"Eğer Allah dileseydi onu size okumazdım. Onu size hiç bildirmezdim. İçinizde bir ömür kaldım. Hala aklınızı kullanmayacak mısınız?\"', 'قل لو شا الله ما تلوته عليكم ولا ادريكم به فقد لبثت فيكم عمرا من قبله افلا تعقلون'),
(1381, 10, 17, 'فَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً اَوْ كَذَّبَ بِاٰيَاتِه۪ۜ اِنَّهُ لَا يُفْلِحُ الْمُجْرِمُونَ', 'Fe men azlemu mimmeniftera alallahi keziben ev kezzebe bi ayatih, innehu la yuflihul mucrimun.', 'Uydurduğu yalanı Allah\'a dayandıran veya O\'nun ayetlerini yalan sayandan daha zalim kim olabilir? O,  mücrimleri[1] kurtuluşa erdirmez.[2]', 'فمن اظلم ممن افتري علي الله كذبا او كذب بايته انه لا يفلح المجرمون'),
(1382, 10, 18, 'وَيَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ وَيَقُولُونَ هٰٓؤُ۬لَٓاءِ شُفَعَٓاؤُ۬نَا عِنْدَ اللّٰهِۜ قُلْ اَتُنَبِّؤُ۫نَ اللّٰهَ بِمَا لَا يَعْلَمُ فِي السَّمٰوَاتِ وَلَا فِي الْاَرْضِۜ سُبْحَانَهُ وَتَعَالٰى عَمَّا يُشْرِكُونَ', 'Ve ya\'budune min dunillahi ma la yedurruhum ve la yenfeuhum ve yekulune haulai şufeauna indallah, kul e tunebbiunallahe bima la ya\'lemu fis semavati ve la fil ard, subhanehu ve teala amma yuşrikun.', 'Onlar,  Allah\'ın yanı sıra bir de kendilerine,  ne bir zarar,  ne bir yarar sağlamayan şeylere kulluk ediyorlar ve \"Bunlar,  Allah\'ın katında bizim şefaatçilerimizdir.[1]\" diyorlar. De ki: \"Allah\'a,  göklerde ve yerde kendisinin bilmediği bir şeyi mi haber veriyorsunuz?\" Allah,  onların ortak koştuklarından Münezzeh\'tir[2] ve Çok Yüce\'dir.', 'ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هولا شفعونا عند الله قل اتنبون الله بما لا يعلم في السموت ولا في الارض سبحنه وتعلي عما يشركون'),
(1383, 10, 19, 'وَمَا كَانَ النَّاسُ اِلَّٓا اُمَّةً وَاحِدَةً فَاخْتَلَفُواۜ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْ ف۪يمَا ف۪يهِ يَخْتَلِفُونَ', 'Ve ma kanen nasu illa ummeten vahideten fahtelefu, ve lev la kelimetun sebekat min rabbike le kudiye beynehum fima fihi yahtelifun.', 'İnsanlar,  sadece tek bir ümmetti. Sonra anlaşmazlığa düştüler. Şayet Rabb\'inin katında önceden verilmiş bir hüküm olmasaydı,  anlaşmazlığa düştükleri konularda hemen karar verilirdi.', 'وما كان الناس الا امة وحدة فاختلفوا ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون'),
(1384, 10, 20, 'وَيَقُولُونَ لَوْلَٓا اُنْزِلَ عَلَيْهِ اٰيَةٌ مِنْ رَبِّه۪ۚ فَقُلْ اِنَّمَا الْغَيْبُ لِلّٰهِ فَانْتَظِرُواۚ اِنّ۪ي مَعَكُمْ مِنَ الْمُنْتَظِر۪ينَ۟', 'Ve yekulune lev la unzile aleyhi ayetun min rabbih, fe kul innemel gaybu lillahi fenteziru, inni meakum minel muntazirin.', '\"Ona Rabb\'inden bir ayet[1] indirilmeli değil mi!\" diyorlar. De ki: \"Gayb yalnızca Allah\'a aittir. Artık bekleyin,  ben de sizinle beraber bekleyenlerdenim.\"', 'ويقولون لولا انزل عليه اية من ربه فقل انما الغيب لله فانتظروا اني معكم من المنتظرين'),
(1385, 10, 21, 'وَاِذَٓا اَذَقْنَا النَّاسَ رَحْمَةً مِنْ بَعْدِ ضَرَّٓاءَ مَسَّتْهُمْ اِذَا لَهُمْ مَكْرٌ ف۪ٓي اٰيَاتِنَاۜ قُلِ اللّٰهُ اَسْرَعُ مَكْراًۜ اِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', 'Ve iza ezaknen nase rahmeten min ba\'di darrae messethum iza lehum mekrun fi ayatina, kulillahu esrau mekra, inne rusulena yektubune ma temkurun.', 'İnsanlara dokunan bir sıkıntıdan sonra,  bir rahmet tattırdığımız zaman,  ayetlerimize karşı hemen plan yapmaya kalkışırlar. De ki: \"Plan yapmada Allah daha seridir.\" Elçilerimiz,  yaptığınız tüm planları kaydetmektedirler.', 'واذا اذقنا الناس رحمة من بعد ضرا مستهم اذا لهم مكر في اياتنا قل الله اسرع مكرا ان رسلنا يكتبون ما تمكرون'),
(1386, 10, 22, 'هُوَ الَّذ۪ي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِۜ حَتّٰٓى اِذَا كُنْتُمْ فِي الْفُلْكِۚ وَجَرَيْنَ بِهِمْ بِر۪يحٍ طَيِّبَةٍ وَفَرِحُوا بِهَا جَٓاءَتْهَا ر۪يحٌ عَاصِفٌ وَجَٓاءَهُمُ الْمَوْجُ مِنْ كُلِّ مَكَانٍ وَظَنُّٓوا اَنَّهُمْ اُح۪يطَ بِهِمْۙ دَعَوُا اللّٰهَ مُخْلِص۪ينَ لَهُ الدّ۪ينَۚ لَئِنْ اَنْجَيْتَنَا مِنْ هٰذِه۪ لَنَكُونَنَّ مِنَ الشَّاكِر۪ينَ', 'Huvellezi yuseyyirukum fil berri vel bahr, hatta iza kuntum fil fulk, ve cereyne bihim bi rihin tayyibetin ve ferihu biha caetha rihun asifun ve caehumul mevcu min kulli mekanin ve zannu ennehum uhita bihim deavullahe muhlisine lehud din, le in enceytena min hazihi le nekunenne mineş şakirin.', 'Sizi karada ve denizde yürüten O\'dur. Öyle ki siz gemide iken ve güzel bir rüzgarla akıp giderken,  yolcuların da bununla sevindikleri bir sırada,  birden şiddetli bir kasırga gelip çatar ve her yönden dalgaların onları sarıp kuşattığı anda,  dini Allah\'a has kılarak: \"Ant olsun,  eğer bizi kurtarırsan mutlaka şükredenlerden olacağız.\" diye dua ederler.', 'هو الذي يسيركم في البر والبحر حتي اذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها جاتها ريح عاصف وجاهم الموج من كل مكان وظنوا انهم احيط بهم دعوا الله مخلصين له الدين لين انجيتنا من هذه لنكونن من الشكرين'),
(1387, 10, 23, 'فَلَمَّٓا اَنْجٰيهُمْ اِذَا هُمْ يَبْغُونَ فِي الْاَرْضِ بِغَيْرِ الْحَقِّۜ  يَٓا اَيُّهَا النَّاسُ اِنَّمَا بَغْيُكُمْ عَلٰٓى اَنْفُسِكُمْۙ مَتَاعَ الْحَيٰوةِ الدُّنْيَا ثُمَّ اِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Fe lemma encahum iza hum yebgune fil ardı bi gayril hakk, ya eyyuhen nasu innema bagyukum ala enfusikum metaal hayatid dunya summe ileyna merciukum fe nunebbiukum bima kuntum ta\'melun.', 'Ama onları kurtarınca,  yeryüzünde haksız yere taşkınlık yaparlar. Ey insanlar! Sizin azgınlığınız ancak kendiniz içindir. Dünya hayatı bir geçimliktir. Sonunda bize döneceksiniz. Yaptıklarınızı size haber veririz.', 'فلما انجيهم اذا هم يبغون في الارض بغير الحق يايها الناس انما بغيكم علي انفسكم متع الحيوة الدنيا ثم الينا مرجعكم فننبيكم بما كنتم تعملون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1388, 10, 24, 'اِنَّمَا مَثَلُ الْحَيٰوةِ الدُّنْيَا كَمَٓاءٍ اَنْزَلْنَاهُ مِنَ السَّمَٓاءِ فَاخْتَلَطَ بِه۪ نَبَاتُ الْاَرْضِ مِمَّا يَأْكُلُ النَّاسُ وَالْاَنْعَامُۜ حَتّٰٓى اِذَٓا اَخَذَتِ الْاَرْضُ زُخْرُفَهَا وَازَّيَّـنَتْ وَظَنَّ اَهْلُهَٓا اَنَّهُمْ قَادِرُونَ عَلَيْهَٓاۙ اَتٰيهَٓا اَمْرُنَا لَيْلاً اَوْ نَهَاراً فَجَعَلْنَاهَا حَص۪يداً كَاَنْ لَمْ تَغْنَ بِالْاَمْسِۜ  كَذٰلِكَ نُفَصِّلُ الْاٰيَاتِ لِقَوْمٍ يَتَفَكَّرُونَ', 'İnnema meselul hayatid dunya ke main enzelnahu mines semai fahteleta bihi nebatul ardı mimma ye\'kulun nasu vel en\'am, hatta iza ehazetil ardu zuhrufeha vezzeyyenet ve zanne ehluha ennehum kadirune aleyha etaha emruna leylen ev neharen fe cealnaha hasiden ke en lem tagne bil ems, kezalike nufassilul ayati li kavmin yetefekkerun.', 'Dünya hayatı,  gökten indirdiğimiz yağmurla hayat bulup yeşeren,  insanların ve hayvanların yararlandıkları yeryüzü bitkileri gibidir. Öyle ki yeryüzü bütün süslerini ve güzelliğini kuşandığı ve sahipleri de onu elde edecek güce sahip olduklarını sandıkları bir sırada; geceleyin veya güpegündüz ona emrimiz geliverir de bunları sanki dün yerinde hiç yokmuş gibi kökünden yolunmuş bir hale getiririz. İşte düşünen bir halk için ayetlerimizi böyle detaylı olarak açıklıyoruz.', 'انما مثل الحيوة الدنيا كما انزلنه من السما فاختلط به نبات الارض مما ياكل الناس والانعم حتي اذا اخذت الارض زخرفها وازينت وظن اهلها انهم قدرون عليها اتيها امرنا ليلا او نهارا فجعلنها حصيدا كان لم تغن بالامس كذلك نفصل الايت لقوم يتفكرون'),
(1389, 10, 25, 'وَاللّٰهُ يَدْعُٓوا اِلٰى دَارِ السَّلَامِۜ وَيَهْد۪ي مَنْ يَشَٓاءُ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Vallahu yed\'u ila daris selam, ve yehdi men yeşau ila sıratin mustekim.', 'Allah,  selam[1] diyarına çağırır. Hak edeni[2] dosdoğru yola iletir.', 'والله يدعوا الي دار السلم ويهدي من يشا الي صرط مستقيم'),
(1390, 10, 26, 'لِلَّذ۪ينَ اَحْسَنُوا الْحُسْنٰى وَزِيَادَةٌۜ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌۜ اُو۬لٰٓئِكَ اَصْحَابُ الْجَنَّةِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Lillezine ahsenul husna ve ziyadeh, ve la yerheku vucuhehum katerun ve la zilleh, ulaike ashabul cenneh, hum fiha halidun.', 'İyi ve güzel davrananlar için daha güzeli ve fazlası var. Onların,  yüzleri ne kararır ne de hor görülmekten kızarır. Onlar,  Cennet halkıdır. Orada sürekli kalıcıdırlar.', 'للذين احسنوا الحسني وزيادة ولا يرهق وجوههم قتر ولا ذلة اوليك اصحب الجنة هم فيها خلدون'),
(1391, 10, 27, 'وَالَّذ۪ينَ كَسَبُوا السَّيِّـَٔاتِ جَزَٓاءُ سَيِّئَةٍ بِمِثْلِهَاۙ وَتَرْهَقُهُمْ ذِلَّةٌۜ مَا لَهُمْ مِنَ اللّٰهِ مِنْ عَاصِمٍۚ  كَاَنَّـمَٓا اُغْشِيَتْ وُجُوهُهُمْ قِطَعاً مِنَ الَّيْلِ مُظْلِماًۜ اُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Vellezine kesebus seyyiati cezau seyyietin bi misliha ve terhekuhum zilleh, ma lehum minallahi min asim, ke ennema ugsiyet vucuhuhum kita\'an minel leyli muzlima, ulaike ashabun nar, hum fiha halidun.', 'Kötülük yapanların cezaları,  yaptıkları kötülük kadardır. Onları her yönden zillet kaplayacaktır. Onları Allah\'ın cezasından kurtaracak hiç kimse yoktur. Yüzleri geceden daha kara bir parçayla örtülmüş gibidir. İşte onlar ateş halkıdır. Orada sürekli kalacaklardır.', 'والذين كسبوا السيات جزا سيية بمثلها وترهقهم ذلة ما لهم من الله من عاصم كانما اغشيت وجوههم قطعا من اليل مظلما اوليك اصحب النار هم فيها خلدون'),
(1392, 10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَم۪يعاً ثُمَّ نَقُولُ لِلَّذ۪ينَ اَشْرَكُوا مَكَانَكُمْ اَنْتُمْ وَشُرَكَٓاؤُ۬كُمْۚ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَٓاؤُ۬هُمْ مَا كُنْتُمْ اِيَّانَا تَعْبُدُونَ', 'Ve yevme nahsuruhum cemian summe nekulu lillezine eşreku mekanekum entum ve şurekaukum, fe zeyyelna beynehum, ve kale şurekauhum ma kuntum iyyana ta\'budun.', 'O gün,  onların hepsini toplarız. Sonra şirk[1] koşanlara,  \"Siz ve şirk koştuklarınız,  olduğunuz yerde durun.\" diyeceğiz. Artık onları birbirinden ayıracağız. Şirk koşulanlar,  şöyle diyecekler: \"Siz,  bize kulluk etmiyordunuz.\"', 'ويوم نحشرهم جميعا ثم نقول للذين اشركوا مكانكم انتم وشركاوكم فزيلنا بينهم وقال شركاوهم ما كنتم ايانا تعبدون'),
(1393, 10, 29, 'فَكَفٰى بِاللّٰهِ شَه۪يداً بَيْنَنَا وَبَيْنَكُمْ اِنْ كُنَّا عَنْ عِبَادَتِكُمْ لَغَافِل۪ينَ', 'Fe kefa billahi şehiden beynena ve beynekum in kunna an ibadetikum le gafilin.', 'Sizinle bizim aramızda tanık olarak Allah yeter. Doğrusu,  sizin bize kulluğunuzdan haberimiz yoktu.', 'فكفي بالله شهيدا بيننا وبينكم ان كنا عن عبادتكم لغفلين'),
(1394, 10, 30, 'هُنَالِكَ تَبْلُوا كُلُّ نَفْسٍ مَٓا اَسْلَفَتْ وَرُدُّٓوا اِلَى اللّٰهِ مَوْلٰيهُمُ الْحَقِّ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ۟', 'Hunalike teblu kullu nefsin ma eslefet ve ruddu ilallahi mevlahumul hakkı ve dalle anhum ma kanu yefterun.', 'İşte orada,  herkes ne yapmışsa onu bulur. Gerçek mevlaları[1] olan Allah\'a döndürülmüş olarak. Uydurdukları şeyler ise kendilerinden uzaklaşıp kaybolurlar.', 'هنالك تبلوا كل نفس ما اسلفت وردوا الي الله موليهم الحق وضل عنهم ما كانوا يفترون'),
(1395, 10, 31, 'قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّمَٓاءِ وَالْاَرْضِ اَمَّنْ يَمْلِكُ السَّمْعَ وَالْاَبْصَارَ وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الْاَمْرَۜ فَسَيَقُولُونَ اللّٰهُۚ فَقُلْ اَفَلَا تَتَّقُونَ', 'Kul men yerzukukum mines semai vel ardı emmen yemlikus sem\'a vel ebsare ve men yuhricul hayye minel meyyiti ve yuhricul meyyite minel hayyi ve men yudebbirul emr, fe se yekulunallah, fe kul e fe la tettekun.', 'De ki: \"Sizleri gökten ve yerden rızıklandıran kimdir? İşitme ve görme gücünü veren kimdir? Ölüden diriyi,  diriden ölüyü çıkaran kimdir? Bütün işleri düzenleyen kimdir?\"[1] Diyecekler ki: \"Allah\'tır.\" O halde,  \"O\'na karşı takvalı[2] olmayacak mısınız?\" de.', 'قل من يرزقكم من السما والارض امن يملك السمع والابصر ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الامر فسيقولون الله فقل افلا تتقون'),
(1396, 10, 32, 'فَذٰلِكُمُ اللّٰهُ رَبُّكُمُ الْحَقُّۚ فَمَاذَا بَعْدَ الْحَقِّ اِلَّا الضَّلَالُۚ فَاَنّٰى تُصْرَفُونَ', 'Fe zalikumullahu rabbukumul hakk, fe maza ba\'del hakkı illed dalal, fe enna tusrafun.', 'İşte bu gerçek Rabb\'iniz Allah\'tır. Hakikatten sonra sapkınlıktan başka ne vardır? Öyleyse nasıl çevriliyorsunuz?', 'فذلكم الله ربكم الحق فماذا بعد الحق الا الضلل فاني تصرفون'),
(1397, 10, 33, 'كَذٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذ۪ينَ فَسَقُٓوا اَنَّهُمْ لَا يُؤْمِنُونَ', 'Kezalike hakkat kelimetu rabbike alellezine feseku ennehum la yu\'minun.', 'Böylece,  Rabb\'inin fasıklar[1] hakkındaki kelimesi[2] gerçekleşmiş oldu. Onlar iman etmezler.', 'كذلك حقت كلمت ربك علي الذين فسقوا انهم لا يومنون'),
(1398, 10, 34, 'قُلْ هَلْ مِنْ شُرَكَٓائِكُمْ مَنْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُۜ قُلِ اللّٰهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُ فَاَنّٰى تُؤْفَكُونَ', 'Kul hel min şurekaikum men yebdeul halka summe yu\'iduh, kulillahu yebdeul halka summe yu\'iduhu fe enna tu\'fekun.', 'De ki: \"Ortak koştuklarınızdan ilk kez yaratıp sonra tekrar diriltecek var mıdır?\" De ki: \"Allah,  ilk olarak yaratır,  sonra diriltir. Nasıl da çevriliyorsunuz?\"', 'قل هل من شركايكم من يبدوا الخلق ثم يعيده قل الله يبدوا الخلق ثم يعيده فاني توفكون'),
(1399, 10, 35, 'قُلْ هَلْ مِنْ شُرَكَٓائِكُمْ مَنْ يَهْد۪ٓي اِلَى الْحَقِّۜ قُلِ اللّٰهُ يَهْد۪ي لِلْحَقِّۜ اَفَمَنْ يَهْد۪ٓي اِلَى الْحَقِّ اَحَقُّ اَنْ يُتَّبَعَ اَمَّنْ لَا يَهِدّ۪ٓي اِلَّٓا اَنْ يُهْدٰىۚ فَمَا لَكُمْ۠    كَيْفَ تَحْكُمُونَ', 'Kul hel min şurekaikum men yehdi ilel hakk, kulillahu yehdi lil hakk, e fe men yehdi ilel hakkı ehakku en yuttebea em men la yehiddi illa en yuhda, fe ma lekum, keyfe tahkumun.', 'De ki: \"Ortak koştuklarınızdan,  gerçeğe iletebilecek kimse var mı?\" De ki: \"Allah gerçeğe iletir. Gerçeğe ileten mi,  yoksa kendisi iletilmedikçe doğru yolu bulamayan mı uyulmaya daha layıktır. Ne oluyor size,  nasıl karar veriyorsunuz?\"', 'قل هل من شركايكم من يهدي الي الحق قل الله يهدي للحق افمن يهدي الي الحق احق ان يتبع امن لا يهدي الا ان يهدي فما لكم كيف تحكمون'),
(1400, 10, 36, 'وَمَا يَتَّبِعُ اَكْثَرُهُمْ اِلَّا ظَناًّۜ اِنَّ الظَّنَّ لَا يُغْن۪ي مِنَ الْحَقِّ شَيْـٔاًۜ اِنَّ اللّٰهَ عَل۪يمٌ بِمَا يَفْعَلُونَ', 'Ve ma yettebiu ekseruhum illa zanna, innez zanne la yugni minel hakkı şey\'a, innallahe alimun bima yef\'alun.', 'Onların çoğu,  ancak zanna[1] uyarlar. Kuşkusuz zan hakikatin yerini tutamaz. Allah,  onların ne yaptıklarını çok iyi bilendir.', 'وما يتبع اكثرهم الا ظنا ان الظن لا يغني من الحق شيا ان الله عليم بما يفعلون'),
(1401, 10, 37, 'وَمَا كَانَ هٰذَا الْقُرْاٰنُ اَنْ يُفْتَرٰى مِنْ دُونِ اللّٰهِ وَلٰكِنْ تَصْد۪يقَ الَّذ۪ي بَيْنَ يَدَيْهِ وَتَفْص۪يلَ الْكِتَابِ لَا رَيْبَ ف۪يهِ مِنْ رَبِّ الْعَالَم۪ينَ۠', 'Ve ma kane hazel kur\'anu en yuftera min dunillahi ve lakin tasdikallezi beyne yedeyhi ve tafsilel kitabi la reybe fihi min rabbil alemin.', 'Bu Kur\'an,  Allah\'tandır; başkası tarafından uydurulmuş değildir. Aynı zamanda kendinden önceki kitapları tasdik eder ve Kitap\'ı[1] ayrıntılı olarak açıklar. Âlemlerin Rabb\'inden olduğu mutlak bir gerçektir.', 'وما كان هذا القران ان يفتري من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتب لا ريب فيه من رب العلمين'),
(1402, 10, 38, 'اَمْ يَقُولُونَ افْتَرٰيهُۜ قُلْ فَأْتُوا بِسُورَةٍ مِثْلِه۪ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللّٰهِ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Em yekulunefterah, kul fe\'tu bi suretin mislihi ved\'u menisteta\'tum min dunillahi in kuntum sadikin.', 'Yoksa \"Onu uydurdu.\" mu diyorlar? De ki: \"Allah\'tan başka kim varsa çağırın da ona benzer bir sure[1] meydana getirin; eğer doğru söyleyenlerdenseniz.\"', 'ام يقولون افتريه قل فاتوا بسورة مثله وادعوا من استطعتم من دون الله ان كنتم صدقين'),
(1403, 10, 39, 'بَلْ كَذَّبُوا بِمَا لَمْ يُح۪يطُوا بِعِلْمِه۪ وَلَمَّا يَأْتِهِمْ تَأْو۪يلُهُۜ كَذٰلِكَ كَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الظَّالِم۪ينَ', 'Bel kezzebu bima lem yuhitu bi ilmihi ve lemma ye\'tihim te\'viluh, kezalike kezzebellezine min kablihim fanzur keyfe kane akibetuz zalimin.', 'Hayır! Onlar,  bilgisini kavrayamadıkları ve kendilerine asıl anlamı açıklanmamış bir şeyi yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Zalimlerin sonunun nasıl olduğuna bak!', 'بل كذبوا بما لم يحيطوا بعلمه ولما ياتهم تاويله كذلك كذب الذين من قبلهم فانظر كيف كان عقبة الظلمين'),
(1404, 10, 40, 'وَمِنْهُمْ مَنْ يُؤْمِنُ بِه۪ وَمِنْهُمْ مَنْ لَا يُؤْمِنُ بِه۪ۜ وَرَبُّكَ اَعْلَمُ بِالْمُفْسِد۪ينَ۟', 'Ve minhum men yu\'minu bihi ve minhum men la yu\'minu bih, ve rabbuke a\'lemu bil mufsidin.', 'Onlardan kimi ona inanır,  kimi de ona inanmaz. Rabb\'in bozgunculuk edenleri en iyi bilendir.', 'ومنهم من يومن به ومنهم من لا يومن به وربك اعلم بالمفسدين'),
(1405, 10, 41, 'وَاِنْ كَذَّبُوكَ فَقُلْ ل۪ي عَمَل۪ي وَلَكُمْ عَمَلُكُمْۚ اَنْتُمْ بَر۪ٓيؤُ۫نَ مِمَّٓا اَعْمَلُ وَاَنَا۬ بَر۪ٓيءٌ مِمَّا تَعْمَلُونَ', 'Ve in kezzebuke fe kul li ameli ve lekum amelukum, entum beriune mimma a\'melu ve ene beriun mimma ta\'melun.', 'Eğer seni yalanlarlarsa de ki: \"Benim yaptıklarım bana,  sizin yaptıklarınız da sizedir. Siz benim yaptıklarımdan sorumlu değilsiniz ben de sizin yaptıklarınızdan sorumlu değilim.\"', 'وان كذبوك فقل لي عملي ولكم عملكم انتم بريون مما اعمل وانا بري مما تعملون'),
(1406, 10, 42, 'وَمِنْهُمْ مَنْ يَسْتَمِعُونَ اِلَيْكَۜ اَفَاَنْتَ تُسْمِـعُ الصُّمَّ وَلَوْ كَانُوا لَا يَعْقِلُونَ', 'Ve minhum men yestemiune ileyk, e fe ente tusmius summe ve lev kanu la ya\'kilun.', 'Onlardan seni dinleyenler de var. Ancak sağırlara duyurabilir misin? Üstelik akıllarını da kullanmıyorlarsa!', 'ومنهم من يستمعون اليك افانت تسمع الصم ولو كانوا لا يعقلون'),
(1407, 10, 43, 'وَمِنْهُمْ مَنْ يَنْظُرُ اِلَيْكَۜ اَفَاَنْتَ تَهْدِي الْعُمْيَ وَلَوْ كَانُوا لَا يُبْصِرُونَ', 'Ve minhum men yanzuru ileyk, e fe ente tehdil umye ve lev kanu la yubsırun.', 'Onlardan sana bakanlar da var. Fakat körlere[1] sen mi doğru yolu göstereceksin? Eğer basiretli[1] değillerse!', 'ومنهم من ينظر اليك افانت تهدي العمي ولو كانوا لا يبصرون'),
(1408, 10, 44, 'اِنَّ اللّٰهَ لَا يَظْلِمُ النَّاسَ شَيْـٔاً وَلٰكِنَّ النَّاسَ اَنْفُسَهُمْ يَظْلِمُونَ', 'İnnallahe la yazlimun nase şey\'en ve lakinnen nase enfusehum yazlimun.', 'Allah,  insanlara haksızlık yapmaz. Ancak insanlar kendi kendilerine haksızlık yaparlar.', 'ان الله لا يظلم الناس شيا ولكن الناس انفسهم يظلمون'),
(1409, 10, 45, 'وَيَوْمَ يَحْشُرُهُمْ كَاَنْ لَمْ يَلْبَثُٓوا اِلَّا سَاعَةً مِنَ النَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْۜ قَدْ خَسِرَ الَّذ۪ينَ كَذَّبُوا بِلِقَٓاءِ اللّٰهِ وَمَا كَانُوا مُهْتَد۪ينَ', 'Ve yevme yahşuruhum keen lem yelbesu illa saaten minen nehari yete arefune beynehum, kad hasirellezine kezzebu bi likaillahi ve ma kanu muhtedin.', 'Onları toplayacağımız gün; dünyada,  ancak birbirleri ile tanışabilecekleri kadar kısa olan,  gündüzün bir saati kadar yaşamış gibi gelecek kendilerine. Allah\'a kavuşmayı yalanlayıp,  doğru yola yönelmemiş olanlar,  gerçekten hüsrana uğramışlardır.[1]', 'ويوم يحشرهم كان لم يلبثوا الا ساعة من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقا الله وما كانوا مهتدين'),
(1410, 10, 46, 'وَاِمَّا نُرِيَنَّكَ بَعْضَ الَّذ۪ي نَعِدُهُمْ اَوْ نَتَوَفَّـيَنَّكَ فَاِلَيْنَا مَرْجِعُهُمْ ثُمَّ اللّٰهُ شَه۪يدٌ عَلٰى مَا يَفْعَلُونَ', 'Ve imma nuriyenneke ba\'dellezi naıduhum ev neteveffeyenneke fe ileyna merciuhum summallahu şehidun ala ma yef\'alun.', 'Onlara yaptığımız uyarının[1] bir kısmını sana göstersek de göstermeden vefat ettirsek de onların dönüşü Bizedir. Allah,  onların ne yaptıklarına tanıktır.', 'واما نرينك بعض الذي نعدهم او نتوفينك فالينا مرجعهم ثم الله شهيد علي ما يفعلون'),
(1411, 10, 47, 'وَلِكُلِّ اُمَّةٍ رَسُولٌۚ فَاِذَا جَٓاءَ رَسُولُهُمْ قُضِيَ بَيْنَهُمْ بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'Ve likulli ummetin resul, feiza cae resuluhum kudıye beynehum bil kıstı ve hum la yuzlamun.', 'Her ümmetin[1] bir resulü[2] vardır. Resulleri geldiği zaman aralarında hakkaniyetle hükmedilir. Asla haksızlığa uğratılmazlar.', 'ولكل امة رسول فاذا جا رسولهم قضي بينهم بالقسط وهم لا يظلمون'),
(1412, 10, 48, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadıkin.', '\"Eğer doğru söylüyorsanız,  yaptığınız bu uyarı ne zaman gerçekleşecek?\" diyorlar.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(1413, 10, 49, 'قُلْ لَٓا اَمْلِكُ لِنَفْس۪ي ضَراًّ وَلَا نَفْعاً اِلَّا مَا شَٓاءَ اللّٰهُۜ لِكُلِّ اُمَّةٍ اَجَلٌۜ اِذَا جَٓاءَ اَجَلُهُمْ فَلَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'Kul la emliku li nefsi darran ve la nef\'an illa ma şaallah, li kulli ummetin ecel, iza cae eceluhum fe la yeste\'hırune saaten ve la yestakdimun.', 'De ki: \"Ben,  kendime dahi Allah\'ın dilediğinden başka ne bir yarar sağlama ne de bir zarar verme gücüne sahibim.\" Her ümmetin bir süresi vardır. Süreleri gelince ne bir saat öne alınırlar ne de geriye bırakılırlar.', 'قل لا املك لنفسي ضرا ولا نفعا الا ما شا الله لكل امة اجل اذا جا اجلهم فلا يستخرون ساعة ولا يستقدمون'),
(1414, 10, 50, 'قُلْ اَرَاَيْتُمْ اِنْ اَتٰيكُمْ عَذَابُهُ بَيَاتاً اَوْ نَهَاراً مَاذَا يَسْتَعْجِلُ مِنْهُ الْمُجْرِمُونَ', 'Kul ereeytum in etakum azabuhu beyaten ev neharen maza yesta\'cilu minhul mucrimun.', 'De ki: \"Söyleyin bakalım! O\'nun azabı ister gece uykuda,  ister gündüz gelsin. Suçlular neden bunu acele istiyorlar?\"', 'قل اريتم ان اتيكم عذابه بيتا او نهارا ماذا يستعجل منه المجرمون'),
(1415, 10, 51, 'اَثُمَّ اِذَا مَا وَقَعَ اٰمَنْتُمْ بِه۪ۜ آٰلْـٰٔنَ وَقَدْ كُنْتُمْ بِه۪ تَسْتَعْجِلُونَ', 'E summe iza ma vakaa amentum bih, al\'ane ve kad kuntum bihi testa\'cilun.', '\"Gerçekleşmesi için acele istediğiniz azaba gerçekleşince mi inanacaksınız yoksa şimdi mi?\"', 'اثم اذا ما وقع امنتم به الن وقد كنتم به تستعجلون'),
(1416, 10, 52, 'ثُمَّ ق۪يلَ لِلَّذ۪ينَ ظَلَمُوا ذُوقُوا عَذَابَ الْخُلْدِۚ هَلْ تُجْزَوْنَ اِلَّا بِمَا كُنْتُمْ تَكْسِبُونَ', 'Summe kile lillezine zalemu zuku azabel huld, hel tuczevne illa bima kuntum teksibun.', 'Sonra zulmedenlere,  \"Süresiz azabı tadın.\" denir. \"Kazandığınızdan başka bir karşılık mı bekliyordunuz?\"', 'ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون الا بما كنتم تكسبون'),
(1417, 10, 53, 'وَيَسْتَنْبِـؤُ۫نَكَ اَحَقٌّ هُوَۜ قُلْ ا۪ي وَرَبّ۪ٓي اِنَّهُ لَحَقٌّ وَمَٓا اَنْتُمْ بِمُعْجِز۪ينَ۟', 'Ve yestenbiuneke ehakkun hu, kul i ve rabbi innehu le hakkun ve ma entum bi mu\'cizin.', 'Sana \"Bu gerçek midir?\" diye soruyorlar. De ki: \"Rabb\'ime yemin ederim ki o gerçektir. Ve siz onu engelleyemezsiniz.\"', 'ويستنبونك احق هو قل اي وربي انه لحق وما انتم بمعجزين'),
(1418, 10, 54, 'وَلَوْ اَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِي الْاَرْضِ لَافْتَدَتْ بِه۪ۜ وَاَسَرُّوا النَّدَامَةَ لَمَّا رَاَوُا الْعَذَابَۚ وَقُضِيَ بَيْنَهُمْ بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'Ve lev enne li kulli nefsin zalemet ma fil ardı leftedet bih, ve eserrun nedamete lemma reevul azab, ve kudıye beynehum bil kıstı ve hum la yuzlemun.', 'Zulmedenler,  yeryüzündekilerin tamamı kendilerinin olsaydı,  kurtulmak için onları fidye olarak verirlerdi. Azabı gördükleri zaman içten bir pişmanlık duyarlar. Ancak aralarında hakkaniyetle[1] hüküm verilir ve haksızlığa uğratılmazlar.', 'ولو ان لكل نفس ظلمت ما في الارض لافتدت به واسروا الندامة لما راوا العذاب وقضي بينهم بالقسط وهم لا يظلمون'),
(1419, 10, 55, 'اَلَٓا اِنَّ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ اَلَٓا اِنَّ وَعْدَ اللّٰهِ حَقٌّ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'E la inne lillahi ma fis semavati vel ard, e la inne va\'dallahi hakkun ve lakinne ekserehum la ya\'lemun.', 'İyi bilin ki,  göklerde ve yerde ne varsa hepsi Allah\'ındır. Yine iyi bilin ki,  Allah\'ın uyarısı gerçektir. Fakat onların çoğu bu gerçeği anlamıyor.', 'الا ان لله ما في السموت والارض الا ان وعد الله حق ولكن اكثرهم لا يعلمون'),
(1420, 10, 56, 'هُوَ يُحْـي۪ وَيُم۪يتُ وَاِلَيْهِ تُرْجَعُونَ', 'Huve yuhyi ve yumitu ve ileyhi turceun.', 'Dirilten de öldüren de O\'dur. Ve O\'na döndürüleceksiniz.', 'هو يحي ويميت واليه ترجعون'),
(1421, 10, 57, 'يَٓا اَيُّهَا النَّاسُ قَدْ جَٓاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَٓاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِن۪ينَ', 'Ya eyyuhen nasu kad caetkum mev\'ızatun min rabbikum ve şifaun lima fis suduri ve huden ve rahmetun lil mu\'minin.', 'Ey insanlar! Rabb\'inizden size bir öğüt; göğüslerde olana bir şifa,  Müminler için bir hidayet ve rahmet gelmiştir.', 'يايها الناس قد جاتكم موعظة من ربكم وشفا لما في الصدور وهدي ورحمة للمومنين'),
(1422, 10, 58, 'قُلْ بِفَضْلِ اللّٰهِ وَبِرَحْمَتِه۪ فَبِذٰلِكَ فَلْيَفْرَحُواۜ هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ', 'Kul bi fadlillahi ve bi rahmetihi fe bi zalike felyefrehu, huve hayrun mimma yecmeun.', 'De ki: \"Allah\'ın fazlı[1] ve rahmetiyle gönül huzuruna kavuşsunlar. Bu onların toplayıp biriktirdiklerinden daha hayırlıdır.\"', 'قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون'),
(1423, 10, 59, 'قُلْ اَرَاَيْتُمْ مَٓا اَنْزَلَ اللّٰهُ لَكُمْ مِنْ رِزْقٍ فَجَعَلْتُمْ مِنْهُ حَرَاماً وَحَلَالاًۜ قُلْ آٰللّٰهُ اَذِنَ لَكُمْ اَمْ عَلَى اللّٰهِ تَفْتَرُونَ', 'Kul e reeytum ma enzelallahu lekum min rızkın fe cealtum minhu haramen ve halala, kul allahu ezine lekum em alallahi tefterun.', 'De ki: \"Allah\'ın size rızık olarak indirdiklerinin bir kısmını helal,  bir kısmını haram yaptığınızı görmüyor musunuz?\" De ki: \"Allah mı size izin verdi,  yoksa Allah\'a iftira mı ediyorsunuz?\"[1]', 'قل اريتم ما انزل الله لكم من رزق فجعلتم منه حراما وحللا قل الله اذن لكم ام علي الله تفترون'),
(1424, 10, 60, 'وَمَا ظَنُّ الَّذ۪ينَ يَفْتَرُونَ عَلَى اللّٰهِ الْكَذِبَ يَوْمَ الْقِيٰمَةِۜ اِنَّ اللّٰهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَشْكُرُونَ۟', 'Ve ma zannullezine yefterune alallahil kezibe yevmel kıyameh, innallahe le zu fadlın alen nasi ve lakinne ekserehum la yeşkurun.', 'Allah\'a karşı yalan uyduranlar,  kıyamet gününü ne sanıyorlar? Doğrusu Allah,  insanlara karşı bol bağış sahibidir. Ancak onların çoğu yine de şükretmezler.', 'وما ظن الذين يفترون علي الله الكذب يوم القيمة ان الله لذو فضل علي الناس ولكن اكثرهم لا يشكرون'),
(1425, 10, 61, 'وَمَا تَكُونُ ف۪ي شَأْنٍ وَمَا تَتْلُوا مِنْهُ مِنْ قُرْاٰنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ اِلَّا كُنَّا عَلَيْكُمْ شُهُوداً اِذْ تُف۪يضُونَ ف۪يهِۜ وَمَا يَعْزُبُ عَنْ رَبِّكَ مِنْ مِثْقَالِ ذَرَّةٍ فِي الْاَرْضِ وَلَا فِي السَّمَٓاءِ وَلَٓا اَصْغَرَ مِنْ ذٰلِكَ وَلَٓا اَكْبَرَ اِلَّا ف۪ي كِتَابٍ مُب۪ينٍ', 'Ve ma tekunu fi şe\'nin ve ma tetlu minhu min kur\'anin ve la ta\'melune min amelin illa kunna aleykum şuhuden iz tufidune, fih ve ma ya\'zubu an rabbike min miskali zerretin fil ardı ve la fis semai ve la asgare min zalike ve la ekbere illa fi kitabin mubin.', 'Ne durumda olursanız olun ve Kur\'an\'dan onun hakkında ne okursanız okuyun; hangi işle uğraşıyorsanız uğraşın,  unutmayın ki Biz mutlaka yaptıklarınıza tanığız. Göklerde ve yerde zerre ağırlığınca hiçbir şey Rabb\'inizden gizli kalamaz. Ne bundan daha küçüğü ne de daha büyüğü yoktur ki,  hepsi apaçık bir Kitap\'ta[1] olmasın.', 'وما تكون في شان وما تتلوا منه من قران ولا تعملون من عمل الا كنا عليكم شهودا اذ تفيضون فيه وما يعزب عن ربك من مثقال ذرة في الارض ولا في السما ولا اصغر من ذلك ولا اكبر الا في كتب مبين'),
(1426, 10, 62, 'اَلَٓا اِنَّ اَوْلِيَٓاءَ اللّٰهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۚ', 'E la inne evliya allahi la havfun aleyhim ve la hum yahzenun.', 'İyi bilin ki,  Allah\'ın velileri[1] için bir korku yoktur,  onlar asla üzülmeyeceklerdir.', 'الا ان اوليا الله لا خوف عليهم ولا هم يحزنون'),
(1427, 10, 63, 'اَلَّذ۪ينَ اٰمَنُوا وَكَانُوا يَتَّقُونَۜ', 'Ellezine amenu ve kanu yettekun.', 'Onlar,  iman eden ve takva sahibi olan kimselerdir.', 'الذين امنوا وكانوا يتقون'),
(1428, 10, 64, 'لَهُمُ الْبُشْرٰى فِي الْحَيٰوةِ الدُّنْيَا وَفِي الْاٰخِرَةِۜ لَا تَبْد۪يلَ لِكَلِمَاتِ اللّٰهِۜ ذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُۜ', 'Lehumul buşra fil hayatid dunya ve fil ahıreh, la tebdile li kelimatillah, zalike huvel fevzul azim.', 'Onlar için dünya hayatında da ahirette de müjdeler vardır. Allah\'ın kelimelerinde[1] asla bir değişiklik olmaz. İşte en büyük başarı budur.', 'لهم البشري في الحيوة الدنيا وفي الاخرة لا تبديل لكلمت الله ذلك هو الفوز العظيم'),
(1429, 10, 65, 'وَلَا يَحْزُنْكَ قَوْلُهُمْۢ اِنَّ الْعِزَّةَ لِلّٰهِ جَم۪يعاًۜ  هُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve la yahzunke kavluhum, innel izzete lillahi cemia, huves semiul alim.', 'Onların sözleri seni üzmesin. İzzet[1] bütünüyle Allah\'a aittir. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'ولا يحزنك قولهم ان العزة لله جميعا هو السميع العليم'),
(1430, 10, 66, 'اَلَٓا اِنَّ لِلّٰهِ مَنْ فِي السَّمٰوَاتِ وَمَنْ فِي الْاَرْضِۜ وَمَا يَتَّبِعُ الَّذ۪ينَ يَدْعُونَ مِنْ دُونِ اللّٰهِ شُرَكَٓاءَۜ اِنْ يَتَّبِعُونَ اِلَّا الظَّنَّ وَاِنْ هُمْ اِلَّا يَخْرُصُونَ', 'E la inne lillahi men fis semavati ve men fil ard, ve ma yettebiullezine yed\'une min dunillahi şureka, in yettebiune illez zanne ve in hum illa yahrusun.', 'İyi bilin ki göklerde ve yerde kim[1] varsa Allah\'ındır. Oysaki Allah\'ın yanı sıra başkasına tabi olanlar neye tabi oluyorlar?  Onlar,  ancak zanna tabi olmuş oluyorlar. Ve onlar ancak saçmalıyorlar.', 'الا ان لله من في السموت ومن في الارض وما يتبع الذين يدعون من دون الله شركا ان يتبعون الا الظن وان هم الا يخرصون'),
(1431, 10, 67, 'هُوَ الَّذ۪ي جَعَلَ لَـكُمُ الَّيْلَ لِتَسْكُنُوا ف۪يهِ وَالنَّهَارَ مُبْصِراًۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَسْمَعُونَ', 'Huvellezi ceale lekumul leyle li teskunu fihi ven nehare mubsıra, inne fi zalike leayatin li kavmin yesmeun.', 'Sükunet bulasınız diye geceyi karanlık ve gündüzü de aydınlık yapan O\'dur. Bunda dinleyen bir halk için ayetler[1] vardır.', 'هو الذي جعل لكم اليل لتسكنوا فيه والنهار مبصرا ان في ذلك لايت لقوم يسمعون'),
(1432, 10, 68, 'قَالُوا اتَّخَذَ اللّٰهُ وَلَداً سُبْحَانَهُۜ هُوَ الْغَنِيُّۜ لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ اِنْ عِنْدَ‌كُمْ مِنْ سُلْطَانٍ بِهٰذَاۜ  اَتَقُولُونَ عَلَى اللّٰهِ مَا لَا تَعْلَمُونَ', 'Kaluttehazallahu veleden subhaneh, huvel ganiy, lehu ma fis semavati ve ma fil ard, in indekum min sultanin bi haza, e tekulune alallahi ma la ta\'lemun.', '\"Allah çocuk edindi.\" dediler. O,  bundan münezzehtir.[1] O\'nun hiçbir şeye ihtiyacı yoktur. Göklerde ve yerde ne varsa O\'nundur. Sizin bu konuda hiçbir sultanınız[2] yoktur. Allah hakkında bilmediğiniz şeyi söylüyorsunuz!', 'قالوا اتخذ الله ولدا سبحنه هو الغني له ما في السموت وما في الارض ان عندكم من سلطن بهذا اتقولون علي الله ما لا تعلمون'),
(1433, 10, 69, 'قُلْ اِنَّ الَّذ۪ينَ يَفْتَرُونَ عَلَى اللّٰهِ الْكَذِبَ لَا يُفْلِحُونَۜ', 'Kul innellezine yefterune alallahil kezibe la yuflihun.', 'De ki: \"Allah hakkında yalan uyduranlar kurtuluşa eremezler.\"', 'قل ان الذين يفترون علي الله الكذب لا يفلحون'),
(1434, 10, 70, 'مَتَاعٌ فِي الدُّنْيَا ثُمَّ اِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذ۪يقُهُمُ الْعَذَابَ الشَّد۪يدَ بِمَا كَانُوا يَكْفُرُونَ۟', 'Metaun fid dunya summe ileyna merciuhum summe nuzikuhumul azabeş şedide bima kanu yekfurun.', 'Dünyada geçici bir yararlanma vardır. Sonra dönüşleri Bizedir. Sonra da inkar etmelerinden dolayı onlara şiddetli azabı tattırırız.', 'متع في الدنيا ثم الينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون'),
(1435, 10, 71, 'وَاتْلُ عَلَيْهِمْ نَبَاَ نُوحٍۢ اِذْ قَالَ لِقَوْمِه۪ يَا قَوْمِ اِنْ كَانَ كَبُرَ عَلَيْكُمْ مَقَام۪ي وَتَذْك۪ير۪ي بِاٰيَاتِ اللّٰهِ فَعَلَى اللّٰهِ تَوَكَّلْتُ فَاَجْمِعُٓوا اَمْرَكُمْ وَشُرَكَٓاءَكُمْ ثُمَّ لَا يَكُنْ اَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ اقْضُٓوا اِلَيَّ وَلَا تُنْظِرُونِ', 'Vetlu aleyhim nebe\'e nuh, iz kale li kavmihi ya kavmi in kane kebure aleykum makami ve tezkiri bi ayatillahi fe alallahi tevekkeltu fe ecmiu emrekum ve şurekaekum summe la yekun emrukum aleykum gummeten summakdu ileyye ve la tunzirun.', 'Onlara,  Nuh\'un haberini anlat. Hani o halkına: \"Ey halkım! Eğer aranızda durmam ve Allah\'ın ayetlerini hatırlatmam size ağır geliyorsa,  bilin ki ben yalnızca Allah\'a güveniyorum. Öyleyse yapacağınızı yapmak için şirk koştuklarınızla toplanıp karar verin. Sonra ne yapacaksanız yapın. Sonra bana fırsat vermeden aldığınız kararı hemen uygulayın!\" demişti.', 'واتل عليهم نبا نوح اذ قال لقومه يقوم ان كان كبر عليكم مقامي وتذكيري بايت الله فعلي الله توكلت فاجمعوا امركم وشركاكم ثم لا يكن امركم عليكم غمة ثم اقضوا الي ولا تنظرون'),
(1436, 10, 72, 'فَاِنْ تَوَلَّيْتُمْ فَمَا سَاَلْتُكُمْ مِنْ اَجْرٍۜ اِنْ اَجْرِيَ اِلَّا عَلَى اللّٰهِۙ وَاُمِرْتُ اَنْ اَكُونَ مِنَ الْمُسْلِم۪ينَ', 'Fe in tevelleytum fe ma se\'eltukum min ecr, in ecriye illa alallahi ve umirtu en ekune minel muslimin.', '\"Eğer yüz çevirirseniz,  siz bilirsiniz. Yaptığım işe karşılık sizden bir ücret istemiş değilim. Benim ücretim ancak Allah\'a aittir. Ben,  Müslümanlardan[1] olmakla emrolundum.\"', 'فان توليتم فما سالتكم من اجر ان اجري الا علي الله وامرت ان اكون من المسلمين'),
(1437, 10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَاهُ وَمَنْ مَعَهُ فِي الْفُلْكِ وَجَعَلْنَاهُمْ خَلَٓائِفَ وَاَغْرَقْنَا الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَاۚ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنْذَر۪ينَ', 'Fe kezzebuhu fe necceynahu ve men meahu fil fulki ve cealnahum halaife ve agraknellezine kezzebu bi ayatina, fanzur keyfe kane akıbetul munzerin.', 'Onu yalanladılar. Biz de onu ve onunla beraber gemide bulunanları kurtardık. Ve onları yeryüzünün halifeleri[1] yaptık. Ayetlerimizi yalanlayanları da boğduk. Bak! Uyarılanların sonu nice oldu!', 'فكذبوه فنجينه ومن معه في الفلك وجعلنهم خليف واغرقنا الذين كذبوا بايتنا فانظر كيف كان عقبة المنذرين'),
(1438, 10, 74, 'ثُمَّ بَعَثْنَا مِنْ بَعْدِه۪ رُسُلاً اِلٰى قَوْمِهِمْ فَجَٓاؤُ۫هُمْ بِالْبَيِّنَاتِ فَمَا كَانُوا لِيُؤْمِنُوا بِمَا كَذَّبُوا بِه۪ مِنْ قَبْلُۜ كَذٰلِكَ نَطْبَعُ عَلٰى قُلُوبِ الْمُعْتَد۪ينَ', 'Summe beasna min ba\'dihi rusulen ila kavmihim fe cauhum bil beyyinati fe ma kanu li yu\'minu bima kezzebu bihi min kabl, kezalike natbeu ala kulubil mugtedin.', 'Sonra onun arkasından,  resulleri halklarına gönderdik. Onlar,  halklarına kanıt içeren açık belgelerle geldiler. Daha önce yalanladıkları şeylere inanmak istemediler. İşte haddi aşanların kalplerini mühürleriz.', 'ثم بعثنا من بعده رسلا الي قومهم فجاوهم بالبينت فما كانوا ليومنوا بما كذبوا به من قبل كذلك نطبع علي قلوب المعتدين'),
(1439, 10, 75, 'ثُمَّ بَعَثْنَا مِنْ بَعْدِهِمْ مُوسٰى وَهٰرُونَ اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ بِاٰيَاتِنَا فَاسْتَكْبَرُوا وَكَانُوا قَوْماً مُجْرِم۪ينَ', 'Summe beasna min ba\'dihim musa ve harune ila fir\'avne ve melaihi bi ayatina festekberu ve kanu kavmen mucrimin.', 'Sonra onların arkasından Musa ve Harun\'u ayetlerimizle Firavun ve melelerine[1] gönderdik. Ancak onlar büyüklendiler,  suçlu bir halk oldular.', 'ثم بعثنا من بعدهم موسي وهرون الي فرعون وملايه بايتنا فاستكبروا وكانوا قوما مجرمين'),
(1440, 10, 76, 'فَلَمَّا جَٓاءَهُمُ الْحَقُّ مِنْ عِنْدِنَا قَالُٓوا اِنَّ هٰذَا لَسِحْرٌ مُب۪ينٌ', 'Fe lemma caehumul hakku min indina kalu inne haza le sıhrun mubin.', 'Onlara,  Tarafımızdan hakikat[1] geldiği zaman,  \" Kuşkusuz bu apaçık bir sihirdir.\" dediler.', 'فلما جاهم الحق من عندنا قالوا ان هذا لسحر مبين'),
(1441, 10, 77, 'قَالَ مُوسٰٓى اَتَقُولُونَ لِلْحَقِّ لَمَّا جَٓاءَكُمْۜ اَسِحْرٌ هٰذَاۜ وَلَا يُفْلِحُ السَّاحِرُونَ', 'Kale musa e tekulune lil hakkı lemma caekum, e sıhrun haza, ve la yuflihus sahırun.', 'Musa: \" Size gelen Hakikat için,   \"bu sihirdir\" mi diyorsunuz? Oysa sihirbazlar iflah olmazlar.\" dedi.', 'قال موسي اتقولون للحق لما جاكم اسحر هذا ولا يفلح السحرون'),
(1442, 10, 78, 'قَالُٓوا اَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ اٰبَٓاءَنَا وَتَكُونَ لَكُمَا الْكِبْرِيَٓاءُ فِي الْاَرْضِۜ وَمَا نَحْنُ لَكُمَا بِمُؤْمِن۪ينَ', 'Kalu e ci\'tena li telfitena amma vecedna aleyhi abaena ve tekune lekumel kibriyau fil ard, ve ma nahnu lekuma bi mu\'minin.', 'Dediler ki: \"Sen; bizi,  atalarımızı üzerinde bulduğumuz yoldan çevirmek ve yeryüzünde gücün ikinizin eline geçmesini sağlamak için mi geldin? Biz,  size mü\'min[1] olacak değiliz.', 'قالوا اجيتنا لتلفتنا عما وجدنا عليه ابانا وتكون لكما الكبريا في الارض وما نحن لكما بمومنين'),
(1443, 10, 79, 'وَقَالَ فِرْعَوْنُ ائْتُون۪ي بِكُلِّ سَاحِرٍ عَل۪يمٍ', 'Ve kale fir\'avnu\'tuni bi kulli sahırin alim.', 'Firavun: \"Bütün bilgin sihirbazları bana getirin!\" dedi.', 'وقال فرعون ايتوني بكل سحر عليم'),
(1444, 10, 80, 'فَلَمَّا جَٓاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسٰٓى اَلْقُوا مَٓا اَنْتُمْ مُلْقُونَ', 'Fe lemma caes seharetu kale lehum musa elku ma entum mulkun.', 'Sihirbazlar gelince,  Musa onlara: \"Atacaklarınızı atın.\" dedi.', 'فلما جا السحرة قال لهم موسي القوا ما انتم ملقون'),
(1445, 10, 81, 'فَلَمَّٓا اَلْقَوْا قَالَ مُوسٰى مَا جِئْتُمْ بِهِ السِّحْرُۜ اِنَّ اللّٰهَ سَيُبْطِلُهُۜ اِنَّ اللّٰهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِد۪ينَ', 'Fe lemma elkav kale musa ma ci\'tum bihis sihr, innallahe se yubtiluh, innallahe la yuslihu amelel mufsidin.', 'Onlar,  atacaklarını atınca Musa: \"Sizin bu yaptığınız sihirdir. Allah onu boşa çıkaracaktır. Allah,  bozguncuların işini düzeltmez.\" dedi.', 'فلما القوا قال موسي ما جيتم به السحر ان الله سيبطله ان الله لا يصلح عمل المفسدين'),
(1446, 10, 82, 'وَيُحِقُّ اللّٰهُ الْحَقَّ بِكَلِمَاتِه۪ وَلَوْ كَرِهَ الْمُجْرِمُونَ۟', 'Ve yuhikkullahul hakka bi kelimatihi ve lev kerihel mucrimun.', 'Suçlular hoşlanmasalar da Allah,  kelimeleriyle[1] gerçeği ortaya çıkaracaktır.', 'ويحق الله الحق بكلمته ولو كره المجرمون'),
(1447, 10, 83, 'فَمَٓا اٰمَنَ لِمُوسٰٓى اِلَّا ذُرِّيَّةٌ مِنْ قَوْمِه۪ عَلٰى خَوْفٍ مِنْ فِرْعَوْنَ وَمَلَا۬ئِهِمْ اَنْ يَفْتِنَهُمْۜ وَاِنَّ فِرْعَوْنَ لَعَالٍ فِي الْاَرْضِۚ وَاِنَّهُ لَمِنَ الْمُسْرِف۪ينَ', 'Fe ma amene li musa illa zurriyyetun min kavmihi ala havfin min fir\'avne ve melaihim en yeftinehum, ve inne fir\'avne lealin fil ard ve innehu le minel musrifin.', 'Firavun ve melelerin[1],  kendilerine kötülük yapacaklarından korktukları için,  Musa\'ya halkından az sayıda gençten başka inanan olmadı. Zira Firavun,  o yerde çok büyüklenmişti. O,  çok aşırı gidenlerdendi.', 'فما امن لموسي الا ذرية من قومه علي خوف من فرعون وملايهم ان يفتنهم وان فرعون لعال في الارض وانه لمن المسرفين'),
(1448, 10, 84, 'وَقَالَ مُوسٰى يَا قَوْمِ اِنْ كُنْتُمْ اٰمَنْتُمْ بِاللّٰهِ فَعَلَيْهِ تَوَكَّلُٓوا اِنْ كُنْتُمْ مُسْلِم۪ينَ', 'Ve kale musa ya kavmi in kuntum amentum billahi fe aleyhi tevekkelu in kuntum muslimin.', 'Musa dedi ki: \"Ey halkım! Eğer Allah\'a iman etmişseniz ve O\'na teslim olmuşsanız,  o halde O\'na tevekkül[1] edin.\"', 'وقال موسي يقوم ان كنتم امنتم بالله فعليه توكلوا ان كنتم مسلمين'),
(1449, 10, 85, 'فَقَالُوا عَلَى اللّٰهِ تَوَكَّلْنَاۚ رَبَّـنَا لَا تَجْعَلْنَا فِتْنَةً لِلْقَوْمِ الظَّالِم۪ينَۙ', 'Fe kalu alallahi tevekkelna, rabbena la tec\'alna fitneten lil kavmiz zalimin.', 'Dediler ki: \"Biz,  Allah\'a tevekkül ettik. Ey Rabbimiz! Bizi zalim halk için bir fitne[1] yapma.\"', 'فقالوا علي الله توكلنا ربنا لا تجعلنا فتنة للقوم الظلمين'),
(1450, 10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِر۪ينَ', 'Ve neccina bi rahmetike minel kavmil kafirin.', 'Rahmetinle bizi Kafir[1] halktan kurtar.', 'ونجنا برحمتك من القوم الكفرين'),
(1451, 10, 87, 'وَاَوْحَيْنَٓا اِلٰى مُوسٰى وَاَخ۪يهِ اَنْ تَبَوَّاٰ لِقَوْمِكُمَا بِمِصْرَ بُيُوتاً وَاجْعَلُوا بُيُوتَكُمْ قِبْلَةً وَاَق۪يمُوا الصَّلٰوةَۜ وَبَشِّرِ الْمُؤْمِن۪ينَ', 'Ve evhayna ila musa ve ahihi en tebevvea li kavmikuma bi mısra buyuten vec\'alu buyutekum kıbleten ve akimus salah, ve beşşiril mu\'minin.', 'Musa ve kardeşine vahyettik: \"Halkınız için Mısır\'da evler hazırlayın. Evlerinizi kıble[1] yapın ve salatı ikame edin.[2] Mü\'minleri müjdele.\"', 'واوحينا الي موسي واخيه ان تبوا لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة واقيموا الصلوة وبشر المومنين'),
(1452, 10, 88, 'وَقَالَ مُوسٰى رَبَّـنَٓا اِنَّكَ اٰتَيْتَ فِرْعَوْنَ وَمَلَاَهُ ز۪ينَةً وَاَمْوَالاً فِي الْحَيٰوةِ الدُّنْيَاۙ رَبَّـنَا لِيُضِلُّوا عَنْ سَب۪يلِكَۚ رَبَّـنَا اطْمِسْ عَلٰٓى اَمْوَالِهِمْ وَاشْدُدْ عَلٰى قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتّٰى يَرَوُا الْعَذَابَ الْاَل۪يمَ', 'Ve kale musa rabbena inneke ateyte fir\'avne ve melahu zineten ve emvalen fil hayatid dunya rabbena li yudıllu an sebilik, rabbenatmis ala emvalihim veşdud ala kulubihim fe la yu\'minu hatta yerevul azabel elim.', 'Musa: \"Ey Rabb\'imiz! Firavun ve melelerine dünya hayatında ziynet[1] ve mallar verdin. Ey Rabb\'imiz! Onlar ise bunu Senin yolundan saptırmak için kullanıyorlar. Rabb\'imiz! Mallarını yok et,  kalplerine sıkıntı ver. Zira onlar can yakıcı azabı görmedikçe iman etmezler.\" dedi.', 'وقال موسي ربنا انك اتيت فرعون وملاه زينة وامولا في الحيوة الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس علي امولهم واشدد علي قلوبهم فلا يومنوا حتي يروا العذاب الاليم'),
(1453, 10, 89, 'قَالَ قَدْ اُج۪يبَتْ دَعْوَتُكُمَا فَاسْتَق۪يمَا وَلَا تَتَّبِعَٓانِّ سَب۪يلَ الَّذ۪ينَ لَا يَعْلَمُونَ', 'Kale kad ucibet da\'vetukuma festekima ve la tettebi anni sebilellezine la ya\'lemun.', 'Allah: \"İkinizin duası kabul olunmuştur. Siz,  doğru yolunuza devam edin. Bilmeyenlerin yoluna uymayın.\" dedi.', 'قال قد اجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون'),
(1454, 10, 90, 'وَجَاوَزْنَا بِبَن۪ٓي اِسْرَٓائ۪لَ الْبَحْرَ فَاَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ بَغْياً وَعَدْواًۜ حَتّٰٓى اِذَٓا اَدْرَكَهُ الْغَرَقُۙ قَالَ اٰمَنْتُ اَنَّهُ لَٓا اِلٰهَ اِلَّا الَّـذ۪ٓي اٰمَنَتْ بِه۪ بَنُٓوا اِسْرَٓائ۪لَ وَاَنَا۬ مِنَ الْمُسْلِم۪ينَ', 'Ve cavezna bi beni israilel bahre fe etbeahum fir\'avnu ve cunuduhu bagyen ve adva, hatta iza edrekehul gareku kale amentu ennehu la ilahe illellezi amenet bihi benu israile ve ene minel muslimin.', 'İsrailoğulları\'nı denizden geçirdik. Firavun ve ordusu,  azgınlık ve düşmanlıkla onların peşlerine düştüler. Boğulmak üzereyken: \"İsrailoğulları\'nın iman ettiği ilahtan başka ilah olmadığına iman ettim ve ben de Müslümanlardanım.\"[1] dedi.', 'وجوزنا ببني اسريل البحر فاتبعهم فرعون وجنوده بغيا وعدوا حتي اذا ادركه الغرق قال امنت انه لا اله الا الذي امنت به بنوا اسريل وانا من المسلمين'),
(1455, 10, 91, 'آٰلْـٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنْتَ مِنَ الْمُفْسِد۪ينَ', 'Al\'ane ve kad asayte kablu ve kunte minel mufsidin.', '\"Şimdi mi? Oysa daha önce isyan etmiş ve bozgunculardan olmuştun.\"', 'الن وقد عصيت قبل وكنت من المفسدين'),
(1456, 10, 92, 'فَالْيَوْمَ نُنَجّ۪يكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ اٰيَةًۜ وَاِنَّ كَث۪يراً مِنَ النَّاسِ عَنْ اٰيَاتِنَا لَغَافِلُونَ۟', 'Fel yevme nuneccike bi bedenike li tekune limen halfeke ayeh, ve inne kesiren minen nasi an ayatina le gafilun.', '\"Kendinden sonrakilere bir ayet[1] olman için,  bugün senin cansız bedenini[2] kurtaracağız.\" Gerçekte ise insanların çoğu ayetlerimizi umursamıyorlar.', 'فاليوم ننجيك ببدنك لتكون لمن خلفك اية وان كثيرا من الناس عن ايتنا لغفلون'),
(1457, 10, 93, 'وَلَقَدْ بَوَّأْنَا بَن۪ٓي اِسْرَٓائ۪لَ مُبَوَّاَ صِدْقٍ وَرَزَقْنَاهُمْ مِنَ الطَّيِّبَاتِۚ فَمَا اخْتَلَفُوا حَتّٰى جَٓاءَهُمُ الْعِلْمُۜ اِنَّ رَبَّكَ يَقْض۪ي بَيْنَهُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'Ve lekad bevve\'na beni israile mubevvee sıdkın ve razaknahum minet tayyibat, femahtelefu hatta caehumul ilm, inne rabbeke yakdi beynehum yevmel kıyameti fi ma kanu fihi yahtelifun.', 'Gerçekten Biz,  İsrailoğulları\'nı güvenli bir yere yerleştirdik. Onları temiz ve hoş nimetlerle rızıklandırdık. Kendilerine ilim[1] gelinceye dek ihtilafa düşmediler. Rabb\'in,  aralarında ihtilaf ettikleri şeyler hakkında Kıyamet Günü hükmünü verecektir.', 'ولقد بوانا بني اسريل مبوا صدق ورزقنهم من الطيبت فما اختلفوا حتي جاهم العلم ان ربك يقضي بينهم يوم القيمة فيما كانوا فيه يختلفون'),
(1458, 10, 94, 'فَاِنْ كُنْتَ ف۪ي شَكٍّ مِمَّٓا اَنْزَلْـنَٓا اِلَيْكَ فَسْـَٔلِ الَّذ۪ينَ يَقْرَؤُ۫نَ الْكِتَابَ مِنْ قَبْلِكَۚ لَقَدْ جَٓاءَكَ الْحَقُّ مِنْ رَبِّكَ فَلَا تَكُونَنَّ مِنَ الْمُمْتَر۪ينَۙ', 'Fe in kunte fi şekkin mimma enzelna ileyke fes\'elillezine yakreunel kitabe min kablik, lekad caekel hakku min rabbike fe la tekunenne minel mumterin.', 'Eğer sana indirdiğimizden şüphe ediyorsan,  senden önce Kitap\'ı duyuranlara sor! Ant olsun ki Rabb\'inden sana gelen hakikattir. Sakın kuşku duyanlardan olma.', 'فان كنت في شك مما انزلنا اليك فسل الذين يقرون الكتب من قبلك لقد جاك الحق من ربك فلا تكونن من الممترين'),
(1459, 10, 95, 'وَلَا تَكُونَنَّ مِنَ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِ اللّٰهِ فَتَكُونَ مِنَ الْخَاسِر۪ينَ', 'Ve la tekunenne minellezine kezzebu bi ayatillahi fe tekune minel hasirin.', 'Allah\'ın ayetlerini yalanlayanlardan olma. Yoksa hüsrana uğrayanlardan olursun.', 'ولا تكونن من الذين كذبوا بايت الله فتكون من الخسرين'),
(1460, 10, 96, 'اِنَّ الَّذ۪ينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَۙ', 'İnnellezine hakkat aleyhim kelimetu rabbike la yu\'minun.', 'Rabb\'inin haklarında kelimeleri[1] gerçekleşecek olanlar,  iman etmezler.', 'ان الذين حقت عليهم كلمت ربك لا يومنون'),
(1461, 10, 97, 'وَلَوْ جَٓاءَتْهُمْ  كُلُّ اٰيَةٍ حَتّٰى يَرَوُا الْعَذَابَ الْاَل۪يمَ', 'Ve lev caethum kullu ayetin hatta yerevul azabel elim.', 'Onlara,  her türlü ayet[1] gelse bile yine de can yakıcı azabı görmedikçe inanmazlar.', 'ولو جاتهم كل اية حتي يروا العذاب الاليم'),
(1462, 10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ اٰمَنَتْ فَنَفَعَهَٓا ا۪يمَانُهَٓا اِلَّا قَوْمَ يُونُسَۜ لَمَّٓا اٰمَنُوا كَشَفْنَا عَنْهُمْ عَذَابَ الْخِزْيِ فِي الْحَيٰوةِ الدُّنْيَا وَمَتَّعْنَاهُمْ اِلٰى ح۪ينٍ', 'Fe lev la kanet karyetun amenet fe nefeaha imanuha, illa kavme yunus, lemma amenu keşefna anhum azabel hızyi fil hayatid dunya ve metta\'nahum ila hin.', 'Keşke azap gelmeden önce iman edip de imanları kendilerine fayda vermiş bir kent olsaydı. Yalnız Yunus\'un halkı iman edince,  dünya hayatında onlardan rezillik azabını kaldırdık. Ve onları belli bir süre daha yararlandırdık.', 'فلولا كانت قرية امنت فنفعها ايمنها الا قوم يونس لما امنوا كشفنا عنهم عذاب الخزي في الحيوة الدنيا ومتعنهم الي حين'),
(1463, 10, 99, 'وَلَوْ شَٓاءَ رَبُّكَ لَاٰمَنَ مَنْ فِي الْاَرْضِ كُلُّهُمْ جَم۪يعاًۜ اَفَاَنْتَ تُكْرِهُ النَّاسَ حَتّٰى يَكُونُوا مُؤْمِن۪ينَ', 'Ve lev şae rabbuke le amene men fil ardı kulluhum cemia, e fe ente tukrihun nase hatta yekunu mu\'minin.', 'Oysa Rabb\'in dileseydi,  yeryüzündekilerin tamamı iman ederdi! Bunu bildiğin halde,  insanları zorla mı mü\'min yapacaksın?', 'ولو شا ربك لامن من في الارض كلهم جميعا افانت تكره الناس حتي يكونوا مومنين'),
(1464, 10, 100, 'وَمَا كَانَ لِنَفْسٍ اَنْ تُؤْمِنَ اِلَّا بِاِذْنِ اللّٰهِۜ وَيَجْعَلُ الرِّجْسَ عَلَى الَّذ۪ينَ لَا يَعْقِلُونَ', 'Ve ma kane li nefsin en tu\'mine illa bi iznillah, ve yec\'alur ricse alellezine la ya\'kılun.', 'Allah\'ın bilgisi[1] dışında hiç kimsenin iman etmesi mümkün değildir.[2] Ve aklını kullanmayanları rics[3] ile karşı karşıya bırakır.', 'وما كان لنفس ان تومن الا باذن الله ويجعل الرجس علي الذين لا يعقلون'),
(1465, 10, 101, 'قُلِ انْظُرُوا مَاذَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ وَمَا تُغْنِي الْاٰيَاتُ وَالنُّذُرُ عَنْ قَوْمٍ لَا يُؤْمِنُونَ', 'Kulinzuru maza fis semavati vel ard, ve ma tugnil ayatu ven nuzuru an kavmin la yu\'minun.', 'De ki: \"Göklerde ve yerde olanlara bir bakın!\" Ancak o apaçık ayetler[1] ve uyarılar iman etmeyecek bir halka yarar sağlamaz.', 'قل انظروا ماذا في السموت والارض وما تغني الايت والنذر عن قوم لا يومنون'),
(1466, 10, 102, 'فَهَلْ يَنْتَظِرُونَ اِلَّا مِثْلَ اَيَّامِ الَّذ۪ينَ خَلَوْا مِنْ قَبْلِهِمْۜ قُلْ فَانْتَظِرُٓوا اِنّ۪ي مَعَكُمْ مِنَ الْمُنْتَظِر۪ينَ', 'Fe hel yentezırune illa misle eyyamillezine halev min kablihim, kul fentezıru inni meakum minel muntezirin.', 'Kendilerinden öncekilerin başından geçen felaketlerin bir benzerini mi bekliyorlar? De ki: \"Bekleyin,  ben de sizinle beraber bekliyorum.\"', 'فهل ينتظرون الا مثل ايام الذين خلوا من قبلهم قل فانتظروا اني معكم من المنتظرين'),
(1467, 10, 103, 'ثُمَّ نُنَجّ۪ي رُسُلَنَا وَالَّذ۪ينَ اٰمَنُوا كَذٰلِكَۚ حَقاًّ عَلَيْنَا نُنْجِ الْمُؤْمِن۪ينَ۟', 'Summe nunecci rusulena vellezine amenu kezalik, hakkan aleyna nuncil mu\'minin.', 'Sonra resullerimizi ve iman edenleri kurtarırız. İman edenleri kurtarmak üzerimize bir haktır.', 'ثم ننجي رسلنا والذين امنوا كذلك حقا علينا ننج المومنين'),
(1468, 10, 104, 'قُلْ يَٓا اَيُّهَا النَّاسُ اِنْ كُنْتُمْ ف۪ي شَكٍّ مِنْ د۪ين۪ي فَلَٓا اَعْبُدُ الَّذ۪ينَ تَعْبُدُونَ مِنْ دُونِ اللّٰهِ وَلٰكِنْ اَعْبُدُ اللّٰهَ الَّذ۪ي يَتَوَفّٰيكُمْۚ وَاُمِرْتُ اَنْ اَكُونَ مِنَ الْمُؤْمِن۪ينَۙ', 'Kul ya eyyuhen nasu in kuntum fi şekkin min dini,fe la a\'budullezine ta\'budune min dunillahi, ve lakin a\'budullahellezi yeteveffakum, ve umirtu en ekune minel mu\'minin.', 'De ki: \"Ey insanlar! Eğer benim dinimden kuşku duyuyorsanız,  ben,  sizin Allah\'ın yanı sıra kulluk ettiklerinize kulluk etmem. Ben,  ancak sizin canınızı alacak olan Allah\'a kulluk ederim. Ve bana inananlardan olmam buyruldu.\"', 'قل يايها الناس ان كنتم في شك من ديني فلا اعبد الذين تعبدون من دون الله ولكن اعبد الله الذي يتوفيكم وامرت ان اكون من المومنين'),
(1469, 10, 105, 'وَاَنْ اَقِمْ وَجْهَكَ لِلدّ۪ينِ حَن۪يفاًۚ وَلَا تَكُونَنَّ مِنَ الْمُشْرِك۪ينَ', 'Ve en ekim vecheke lid dini hanifa, ve la tekunenne minel muşrikin.', 'Allah\'ı birleyici[1] olarak dine yönel. Sakın müşriklerden[2] olma.', 'وان اقم وجهك للدين حنيفا ولا تكونن من المشركين'),
(1470, 10, 106, 'وَلَا تَدْعُ مِنْ دُونِ اللّٰهِ مَا لَا يَنْفَعُكَ وَلَا يَضُرُّكَۚ فَاِنْ فَعَلْتَ فَاِنَّكَ اِذاً مِنَ الظَّالِم۪ينَ', 'Ve la ted\'u min dunillahi ma la yenfeuke ve la yadurruk, fe in fealte fe inneke izen minez zalimin.', 'Allah\'ı bırakıp da sana fayda da zarar da veremeyecek olanlara yönelme. Böyle yaparsan zalimlerden olursun.', 'ولا تدع من دون الله ما لا ينفعك ولا يضرك فان فعلت فانك اذا من الظلمين'),
(1471, 10, 107, 'وَاِنْ يَمْسَسْكَ اللّٰهُ بِضُرٍّ فَلَا كَاشِفَ لَهُٓ اِلَّا هُوَۚ وَاِنْ يُرِدْكَ بِخَيْرٍ فَلَا رَٓادَّ لِفَضْلِه۪ۜ يُص۪يبُ بِه۪ مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ۜ وَهُوَ الْغَفُورُ الرَّح۪يمُ', 'Ve in yemseskallahu bidurrin fe la kaşife lehu illa hu, ve in yuridke bi hayrin fe la radde li fadlih, yusibu bihi men yeşau min ibadih, ve huvel gafurur rahim.', 'Eğer Allah,  sana bir sıkıntı verirse onu Kendisinden başka giderebilecek yoktur. Eğer senin için bir hayır dilerse,  O\'nun fazlını[1] geri çevirebilecek yoktur. O,  onu kullarından hak edene nasip eder. O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'وان يمسسك الله بضر فلا كاشف له الا هو وان يردك بخير فلا راد لفضله يصيب به من يشا من عباده وهو الغفور الرحيم'),
(1472, 10, 108, 'قُلْ يَٓا اَيُّهَا النَّاسُ قَدْ جَٓاءَكُمُ الْحَقُّ مِنْ رَبِّكُمْۚ  فَمَنِ اهْتَدٰى فَاِنَّمَا يَهْتَد۪ي لِنَفْسِه۪ۚ وَمَنْ ضَلَّ فَاِنَّمَا يَضِلُّ عَلَيْهَاۚ وَمَٓا اَنَا۬ عَلَيْكُمْ بِوَك۪يلٍۜ', 'Kul ya eyyuhen nasu kad caekumul hakku min rabbikum, fe men ihteda fe innema yehtedi li nefsih, ve men dalle fe innema yadıllu aleyha, ve ma ene aleykum bi vekil.', 'De ki: \"Ey insanlar,  işte Rabb\'inizden size Hakk[1] geldi. Doğru yolu kabul eden,  kendisi için kabul etmiş olur. Sapkınlık eden de kendi aleyhine sapmış olur. Ve ben sizin vekiliniz[2] değilim.', 'قل يايها الناس قد جاكم الحق من ربكم فمن اهتدي فانما يهتدي لنفسه ومن ضل فانما يضل عليها وما انا عليكم بوكيل'),
(1473, 10, 109, 'وَاتَّبِعْ مَا يُوحٰٓى اِلَيْكَ وَاصْبِرْ حَتّٰى يَحْكُمَ اللّٰهُۚ وَهُوَ خَيْرُ الْحَاكِم۪ينَ', 'Vettebi\' ma yuha ileyke vasbir hatta yahkumallah, ve huve hayrul hakimin.', 'Ve sana vahyolunana uy. Allah,  hükmünü verene kadar sabret. Ve O,  Hüküm Verenlerin En Hayırlısıdır.', 'واتبع ما يوحي اليك واصبر حتي يحكم الله وهو خير الحكمين'),
(1474, 11, 1, 'الٓـرٰ۠   كِتَابٌ اُحْكِمَتْ اٰيَاتُهُ ثُمَّ فُصِّلَتْ مِنْ لَدُنْ حَك۪يمٍ خَب۪يرٍۙ', 'Elif lam ra kitabun uhkimet ayatuhu summe fussılet min ledun hakimin habir.', 'Elif,  Lam,  Ra. Bu,  Yasa Sahibi,  Her Şeyden Haberdar Olan tarafından,  ayetleri sağlamlaştırılmış ve ayrıntılı olarak açıklanmış bir Kitap\'tır.', 'الر كتب احكمت ايته ثم فصلت من لدن حكيم خبير'),
(1475, 11, 2, 'اَلَّا تَعْبُدُٓوا اِلَّا اللّٰهَۜ اِنَّن۪ي لَكُمْ مِنْهُ نَذ۪يرٌ وَبَش۪يرٌۙ', 'Ella ta\'budu illallah, inneni lekum minhu nezirun ve beşir.', 'Allah\'tan başkasına kulluk[1] yapmayın. Kuşkusuz ben,  O\'nun tarafından size gönderilmiş bir uyarıcı ve haber vericiyim.', 'الا تعبدوا الا الله انني لكم منه نذير وبشير'),
(1476, 11, 3, 'وَاَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُٓوا اِلَيْهِ يُمَتِّعْكُمْ مَتَاعاً حَسَناً اِلٰٓى اَجَلٍ مُسَمًّى وَيُؤْتِ كُلَّ ذ۪ي فَضْلٍ فَضْلَهُۜ وَاِنْ تَوَلَّوْا فَاِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَب۪يرٍ', 'Ve enistagfiru rabbekum summe tubu ileyhi yumetti\'kum metaan hasenen ila ecelin musemmen ve yu\'ti kulle zi fadlin fadleh, ve in tevellev fe inni ehafu aleykum azabe yevmin kebir.', 'Ve Rabb\'inizden bağışlanma dileyin,  sonra O\'na tevbe[1] edin ki belirli bir süreye kadar sizi iyi nimetlerden yararlandırsın. Fazilet[2] sahibine,  faziletinin karşılığını versin. Eğer yüz çevirirseniz,  ben sizin için büyük günün azabından korkarım.', 'وان استغفروا ربكم ثم توبوا اليه يمتعكم متعا حسنا الي اجل مسمي ويوت كل ذي فضل فضله وان تولوا فاني اخاف عليكم عذاب يوم كبير'),
(1477, 11, 4, 'اِلَى اللّٰهِ مَرْجِعُكُمْۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'İlallahi merciukum, ve huve ala kulli şey\'in kadir.', 'Dönüşünüz yalnızca Allah\'adır. O\'nun Gücü Her Şeye Yeter.', 'الي الله مرجعكم وهو علي كل شي قدير'),
(1478, 11, 5, 'اَلَٓا اِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا مِنْهُۜ  اَلَا ح۪ينَ يَسْتَغْشُونَ ثِيَابَهُمْۙ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَۚ اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'E la innehum yesnune sudurehum li yestahfu minh, e la hine yestagşune siyabehum ya\'lemu ma yusirrune ve ma yu\'linun, innehu alimun bi zatis sudur.', 'İyi bilin ki! Onlar,  O\'ndan düşmanlıklarını gizlemek için iki büklüm olurlar. Yine iyi bilin ki! Onlar,  örtülerine büründükleri[1] zaman,  neyi gizleyip neyi açığa çıkardıklarını bilir. O,  göğüslerde olanı en iyi bilendir.', 'الا انهم يثنون صدورهم ليستخفوا منه الا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون انه عليم بذات الصدور'),
(1479, 11, 6, 'وَمَا مِنْ دَٓابَّةٍ فِي الْاَرْضِ اِلَّا عَلَى اللّٰهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَاۜ كُلٌّ ف۪ي كِتَابٍ مُب۪ينٍ', 'Ve ma min dabbetin fil ardı illa alallahi rızkuha ve ya\'lemu mustekarreha ve mustevdeaha, kullun fi kitabin mubin.', 'Yeryüzünde yaşayan hiçbir canlı yoktur ki,  rızkı Allah\'a ait olmasın. O,  onun karar kıldığı yeri ve geçici durduğu yeri bilir.[1] Bunların tamamı apaçık bir Kitap\'tadır.[2]', 'وما من دابة في الارض الا علي الله رزقها ويعلم مستقرها ومستودعها كل في كتب مبين'),
(1480, 11, 7, 'وَهُوَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ ف۪ي سِتَّةِ اَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَٓاءِ لِيَبْلُوَكُمْ اَيُّكُمْ اَحْسَنُ عَمَلاًۜ وَلَئِنْ قُلْتَ اِنَّكُمْ مَبْعُوثُونَ مِنْ بَعْدِ الْمَوْتِ لَيَقُولَنَّ الَّذ۪ينَ كَفَرُٓوا اِنْ هٰذَٓا اِلَّا سِحْرٌ مُب۪ينٌ', 'Ve huvellezi halakas semavati vel arda fi sitteti eyyamin ve kane arşuhu alel mai li yebluvekum eyyukum ahsenu amela, ve le in kulte innekum meb\'usune min ba\'dil mevti le yekulennellezine keferu in haza illa sihrun mubin.', 'Gökleri ve yeri altı günde[1] yaratan O\'dur. Daha önce arşı[2] su üzerindeydi. Sizi yaratması,  hanginizin iyi şeyler yapacağını sınav yapmak içindir. Eğer Kafirlere: \"Gerçekten siz,  öldükten sonra diriltilecekseniz.\" desen,  \"Bu ancak apaçık bir büyüdür.\" diyecekler.', 'وهو الذي خلق السموت والارض في ستة ايام وكان عرشه علي الما ليبلوكم ايكم احسن عملا ولين قلت انكم مبعوثون من بعد الموت ليقولن الذين كفروا ان هذا الا سحر مبين'),
(1481, 11, 8, 'وَلَئِنْ اَخَّرْنَا عَنْهُمُ الْعَذَابَ اِلٰٓى اُمَّةٍ مَعْدُودَةٍ لَيَقُولُنَّ مَا يَحْبِسُهُۜ اَلَا يَوْمَ يَأْت۪يهِمْ لَيْسَ مَصْرُوفاً عَنْهُمْ وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ۟', 'Ve le in ahharna anhumul azabe ila ummetin ma\'dudetin le yekulunne ma yahbisuh, e la yevme ye\'tihim leyse masrufen anhum ve haka bi him ma kanu bihi yestehziun.', 'Eğer,  bir ümmet[1] için azabı onlardan belli bir süreye kadar erteleyecek olursak,  \"Bunu engelleyen şey nedir ki?\" derler. Bilesiniz ki,  onlara azap geldiği gün,  artık geri çevrilmez. Alaya aldıkları azap onları kuşatır.', 'ولين اخرنا عنهم العذاب الي امة معدودة ليقولن ما يحبسه الا يوم ياتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزون'),
(1482, 11, 9, 'وَلَئِنْ اَذَقْنَا الْاِنْسَانَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَاهَا مِنْهُۚ اِنَّهُ لَيَؤُ۫سٌ كَفُورٌ', 'Ve le in ezaknal insane minna rahmeten summe neza\'naha minh, innehu le yeusun kefur.', 'Eğer insana,  tarafımızdan bir rahmet tattırsak,  sonra da onu geri alsak,  ümitsizliğe kapılır ve küfreder.[1]', 'ولين اذقنا الانسن منا رحمة ثم نزعنها منه انه ليوس كفور'),
(1483, 11, 10, 'وَلَئِنْ اَذَقْنَاهُ نَعْمَٓاءَ بَعْدَ ضَرَّٓاءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ السَّيِّـَٔاتُ عَنّ۪يۜ  اِنَّهُ لَفَرِحٌ فَخُورٌۙ', 'Ve le in ezaknahu na\'mae ba\'de darrae messethu le yekulenne zehebes seyyiatu anni, innehu le ferihun fahur.', 'Eğer,  kendisine dokunan bir zarardan sonra,  ona bir nimet tattırsak,  \"Kötülüklerden kurtuldum.\" diye[1] böbürlenir ve şımarmaya başlar.', 'ولين اذقنه نعما بعد ضرا مسته ليقولن ذهب السيات عني انه لفرح فخور');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1484, 11, 11, 'اِلَّا الَّذ۪ينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِۜ  اُو۬لٰٓئِكَ لَهُمْ مَغْفِرَةٌ وَاَجْرٌ كَب۪يرٌ', 'İllellezine saberu ve amilus salihat, ulaike lehum magfiretun ve ecrun kebir.', 'Ancak sabredenler ve salihatı[1] yapanlar hariç. İşte onlar için bağışlanma ve büyük bir ödül vardır.', 'الا الذين صبروا وعملوا الصلحت اوليك لهم مغفرة واجر كبير'),
(1485, 11, 12, 'فَلَعَلَّكَ تَارِكٌ بَعْضَ مَا يُوحٰٓى اِلَيْكَ وَضَٓائِقٌ بِه۪ صَدْرُكَ اَنْ يَقُولُوا لَوْلَٓا اُنْزِلَ عَلَيْهِ كَنْزٌ اَوْ جَٓاءَ مَعَهُ مَلَكٌۜ اِنَّـمَٓا اَنْتَ نَذ۪يرٌۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ وَك۪يلٌۜ', 'Fe lealleke tarikun ba\'da ma yuha ileyke ve daikun bihi sadruke en yekulu lev la unzile aleyhi kenzun ev cae meahu melek, innema ente nezir, vallahu ala kulli şey\'in vekil.', 'O halde sen,  \"Ona bir hazine indirilmeli veya onunla bir melek gelmeli değil miydi?\" dedikleri için göğsün daralıp; sana vahyolunanın bir kısmını tebliğ etmekten vaz mı geçeceksin? Sen yalnızca bir uyarıcısın.[1] Allah ise her şeye vekildir.[2]', 'فلعلك تارك بعض ما يوحي اليك وضايق به صدرك ان يقولوا لولا انزل عليه كنز او جا معه ملك انما انت نذير والله علي كل شي وكيل'),
(1486, 11, 13, 'اَمْ يَقُولُونَ افْتَرٰيهُۜ  قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِه۪ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللّٰهِ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Em yekulunefterah, kul fe\'tu bi aşri suverin mislihi muftereyatin ved\'u menisteta\'tum min dunillahi in kuntum sadikin.', 'Yoksa \"Onu uydurdu.\" mu diyorlar? De ki: \"Eğer,  doğru söylüyorsanız haydi ona benzer on sure[1] getirin. Allah\'tan başka çağırabileceklerinizi de çağırın.\"', 'ام يقولون افتريه قل فاتوا بعشر سور مثله مفتريت وادعوا من استطعتم من دون الله ان كنتم صدقين'),
(1487, 11, 14, 'فَاِلَّمْ يَسْتَج۪يبُوا لَكُمْ فَاعْلَمُٓوا اَنَّـمَٓا اُنْزِلَ بِعِلْمِ اللّٰهِ وَاَنْ لَٓا اِلٰهَ اِلَّا هُوَۚ فَهَلْ اَنْتُمْ مُسْلِمُونَ', 'Fe illem yestecibu lekum fa\'lemu ennema unzile bi ilmillahi ve en la ilahe illa hu, fe hel entum muslimun.', 'Eğer,  size cevap veremezlerse; iyi bilin ki,  bu ancak Allah\'ın ilmiyle indirilmiştir. O\'ndan başka ilah yoktur. Hala müslüman[1] olmayacak mısınız?', 'فالم يستجيبوا لكم فاعلموا انما انزل بعلم الله وان لا اله الا هو فهل انتم مسلمون'),
(1488, 11, 15, 'مَنْ كَانَ يُر۪يدُ الْحَيٰوةَ الدُّنْيَا وَز۪ينَتَهَا نُوَفِّ اِلَيْهِمْ اَعْمَالَهُمْ ف۪يهَا وَهُمْ ف۪يهَا لَا يُبْخَسُونَ', 'Men kane yuridul hayated dunya ve zineteha nuveffi ileyhim a\'malehum fiha ve hum fiha la yubhasun.', 'Kim sadece dünya hayatını ve onun ziynetini[1] isterse,  onlara yaptıklarının karşılığını eksiksiz veririz. Bu hususta onlara hiçbir haksızlık yapılmaz.', 'من كان يريد الحيوة الدنيا وزينتها نوف اليهم اعملهم فيها وهم فيها لا يبخسون'),
(1489, 11, 16, 'اُو۬لٰٓئِكَ الَّذ۪ينَ لَيْسَ لَهُمْ فِي الْاٰخِرَةِ اِلَّا النَّارُۘ وَحَبِطَ مَا صَنَعُوا ف۪يهَا وَبَاطِلٌ مَا كَانُوا يَعْمَلُونَ', 'Ulaikellezine leyse lehum fil ahıreti illen nar ve habita ma sanau fiha ve batılun ma kanu ya\'melun.', 'İşte bu kimselere,  ahirette ateşten başka bir şey yoktur. Burada yaptıkları şeyler boşa gitmiştir. Zaten yaptıkları bütün işleri geçersizdir.', 'اوليك الذين ليس لهم في الاخرة الا النار وحبط ما صنعوا فيها وبطل ما كانوا يعملون'),
(1490, 11, 17, 'اَفَمَنْ كَانَ عَلٰى بَيِّنَةٍ مِنْ رَبِّه۪ وَيَتْلُوهُ شَاهِدٌ مِنْهُ وَمِنْ قَبْلِه۪ كِتَابُ مُوسٰٓى اِمَاماً وَرَحْمَةًۜ  اُو۬لٰٓئِكَ يُؤْمِنُونَ بِه۪ۜ وَمَنْ يَكْفُرْ بِه۪ مِنَ الْاَحْزَابِ فَالنَّارُ مَوْعِدُهُۚ فَلَا تَكُ ف۪ي مِرْيَةٍ مِنْهُ اِنَّهُ الْحَقُّ مِنْ رَبِّكَ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ', 'E fe men kane ala beyyinetin min rabbihi ve yetluhu şahidun minhu ve min kablihi kitabu musa imamen ve rahmeh, ulaike yu\'minune bih, ve men yekfur bihi minel ahzabi fen naru mev\'ıduh, fe la teku fi miryetin minhu innehul hakku min rabbike ve lakinne ekseren nasi la yu\'minun.', 'Rabb\'inden,  kanıt içeren bir bilgi üzerinde olan kimse ile böyle olmayan kimse bir olur mu? Bunu Rabb\'inden bir tanık ve bir de ondan önce rehber ve rahmet olarak Musa\'nın kitabı desteklemektedir. İşte bunlar,  ona iman ederler. Hangi grup onu inkar ederse,  varacağı yer ateştir. Ondan kuşkun olmasın. Kuşkusuz o Rabb\'inden bir gerçektir. Fakat insanların çoğu iman etmezler.', 'افمن كان علي بينة من ربه ويتلوه شاهد منه ومن قبله كتب موسي اماما ورحمة اوليك يومنون به ومن يكفر به من الاحزاب فالنار موعده فلا تك في مرية منه انه الحق من ربك ولكن اكثر الناس لا يومنون'),
(1491, 11, 18, 'وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباًۜ اُو۬لٰٓئِكَ يُعْرَضُونَ عَلٰى رَبِّهِمْ وَيَقُولُ الْاَشْهَادُ هٰٓؤُ۬لَٓاءِ الَّذ۪ينَ كَذَبُوا عَلٰى رَبِّهِمْۚ اَلَا لَعْنَةُ اللّٰهِ عَلَى الظَّالِم۪ينَۙ', 'Ve men ezlemu mimmeniftera alallahi keziba, ulaike yu\'radune ala rabbihim ve yekulul eşhadu haulaillezine kezebu ala rabbihim, e la la\'netullahi alaz zalimin.', 'Uydurduğu yalanı Allah\'a dayandırandan daha zalim kim olabilir? Onlar,  Rabb\'lerinin huzuruna çıkarılacaklar ve tanıklar da: \"Rabb\'lerine karşı yalan uyduranlar işte bunlardır.\" diyeceklerdir. İyi bilin ki Allah\'ın laneti zalimlerin[1] üzerinedir.[2]', 'ومن اظلم ممن افتري علي الله كذبا اوليك يعرضون علي ربهم ويقول الاشهد هولا الذين كذبوا علي ربهم الا لعنة الله علي الظلمين'),
(1492, 11, 19, 'اَلَّذ۪ينَ يَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ وَيَبْغُونَهَا عِوَجاًۜ وَهُمْ بِالْاٰخِرَةِ هُمْ كَافِرُونَ', 'Ellezine yasuddune an sebilillahi ve yebguneha iveca, ve hum bil ahıreti hum kafirun.', 'O kimseler,  Allah\'ın yolundan alıkoyarlar. Ve o yolu eğri göstermeye çalışırlar. Ve onlar,  ahiret hayatını yok sayarlar.', 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخرة هم كفرون'),
(1493, 11, 20, 'اُو۬لٰٓئِكَ لَمْ يَكُونُوا مُعْجِز۪ينَ فِي الْاَرْضِ وَمَا كَانَ لَهُمْ مِنْ دُونِ اللّٰهِ مِنْ اَوْلِيَٓاءَۢ يُضَاعَفُ لَهُمُ الْعَذَابُۜ مَا كَانُوا يَسْتَط۪يعُونَ السَّمْعَ وَمَا كَانُوا يُبْصِرُونَ', 'Ulaike lem yekunu mu\'cizine fil ardı ve ma kane lehum min dunillahi min evliya, yudaafu lehumul azab, ma kanu yestetiunes sem\'a ve ma kanu yubsirun.', 'Onlar,  yeryüzünde Allah\'ı aciz bırakabilecek değillerdir. Kendilerini,  Allah\'a karşı koruyacak bir yardımcı da bulamayacaklardır. Onların azapları kat kat olacaktır. Onlar,  gerçeği duymaya ve görmeye tahammül edemiyorlardı.', 'اوليك لم يكونوا معجزين في الارض وما كان لهم من دون الله من اوليا يضعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون'),
(1494, 11, 21, 'اُو۬لٰٓئِكَ الَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ', 'Ulaikellezine hasiru enfusehum ve dalle anhum ma kanu yefterun.', 'İşte onlar,  kendilerine yazık eden kimselerdir. Uydurdukları şeyler de kendilerini terk edip kaybolmuştur.', 'اوليك الذين خسروا انفسهم وضل عنهم ما كانوا يفترون'),
(1495, 11, 22, 'لَا جَرَمَ اَنَّهُمْ فِي الْاٰخِرَةِ هُمُ الْاَخْسَرُونَ', 'La cereme ennehum fil ahıreti humul ahserun.', 'Onlar ahirette en büyük kayba uğrayanlardır.', 'لا جرم انهم في الاخرة هم الاخسرون'),
(1496, 11, 23, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَاَخْبَتُٓوا اِلٰى رَبِّهِمْۙ اُو۬لٰٓئِكَ اَصْحَابُ الْجَنَّةِۚ هُمْ ف۪يهَا خَالِدُونَ', 'İnnellezine amenu ve amilus salihati ve ahbetu ila rabbihim ulaike ashabul cenneh, hum fiha halidun.', 'İman edip,  salihatı[1] yapanlar,  Rabb\'lerine içtenlikle bağlı olanlar; Cennet ehlidirler. Onlar,  orada sürekli kalacaklardır.', 'ان الذين امنوا وعملوا الصلحت واخبتوا الي ربهم اوليك اصحب الجنة هم فيها خلدون'),
(1497, 11, 24, 'مَثَلُ الْفَر۪يقَيْنِ كَالْاَعْمٰى وَالْاَصَمِّ وَالْبَص۪يرِ وَالسَّم۪يعِۜ هَلْ يَسْتَوِيَانِ مَثَلاًۜ اَفَلَا تَذَكَّرُونَ۟', 'Meselul ferikayni kel a\'ma vel esammi vel basiri ves semi\' hel yesteviyani mesela e fe la tezekkerun.', 'Bu iki grubun durumu; kör ve sağır ile gören ve duyanın durumu gibidir. Bunlar hiç bir olur mu? Niçin düşünüp öğüt almıyorsunuz?', 'مثل الفريقين كالاعمي والاصم والبصير والسميع هل يستويان مثلا افلا تذكرون'),
(1498, 11, 25, 'وَلَقَدْ اَرْسَلْنَا نُوحاً اِلٰى قَوْمِه۪ۘ اِنّ۪ي لَكُمْ نَذ۪يرٌ مُب۪ينٌۙ', 'Ve lekad erselna nuhan ila kavmihi inni lekum nezirun mubin.', 'Ant olsun ki! Biz,  Nuh\'u kendi halkına göndermiştik. \"Ben sizin için apaçık bir uyarıcıyım;\"', 'ولقد ارسلنا نوحا الي قومه اني لكم نذير مبين'),
(1499, 11, 26, 'اَنْ لَا تَعْبُدُٓوا اِلَّا اللّٰهَۜ اِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ اَل۪يمٍ', 'En la ta\'budu illallah, inni ehafu aleykum azabe yevmin elim.', '\"Allah\'tan başkasına kulluk[1] etmeyin. Ben,  sizin için can yakıcı bir günün azabından korkuyorum.\"', 'ان لا تعبدوا الا الله اني اخاف عليكم عذاب يوم اليم'),
(1500, 11, 27, 'فَقَالَ الْمَلَأُ الَّذ۪ينَ كَفَرُوا مِنْ قَوْمِه۪ مَا نَرٰيكَ اِلَّا بَشَراً مِثْلَنَا وَمَا نَرٰيكَ اتَّبَعَكَ اِلَّا الَّذ۪ينَ هُمْ اَرَاذِلُنَا بَادِيَ الرَّأْيِۚ وَمَا نَرٰى لَكُمْ عَلَيْنَا مِنْ فَضْلٍ بَلْ نَظُنُّكُمْ كَاذِب۪ينَ', 'Fe kalel meleullezine keferu min kavmihi ma nerake illa beşeren mislena ve ma nerakettebeake illellezine hum eraziluna badiyer re\'y, ve ma nera lekum aleyna min fadlin bel nezunnukum kazibin.', 'Bunun üzerine halkının Kafir meleleri[1]: \"Biz,  seni kendimiz gibi bir beşer[2] olarak görüyoruz. Görüyoruz ki,  sana tabi olanlar,  bizim toplumun en zayıf ve sefil olanlarıdır. Sizin,  bize karşı bir üstünlüğünüzü görmüyoruz. Bilakis sizin yalancılardan olduğunuzu düşünüyoruz.\" dediler.', 'فقال الملا الذين كفروا من قومه ما نريك الا بشرا مثلنا وما نريك اتبعك الا الذين هم اراذلنا بادي الراي وما نري لكم علينا من فضل بل نظنكم كذبين'),
(1501, 11, 28, 'قَالَ يَا قَوْمِ اَرَاَيْتُمْ اِنْ كُنْتُ عَلٰى بَيِّنَةٍ مِنْ رَبّ۪ي وَاٰتٰين۪ي رَحْمَةً مِنْ عِنْدِه۪ فَعُمِّيَتْ عَلَيْكُمْۜ اَنُلْزِمُكُمُوهَا وَاَنْتُمْ لَهَا كَارِهُونَ', 'Kale ya kavmi e reeytum in kuntu ala beyyinetin min rabbi ve atani rahmeten min indihi fe ummiyet aleykum, e nulzimukumuha ve entum leha karihun.', 'Dedi ki: \"Ey halkım! Bakın! Ya ben Rabb\'imden açık bir kanıt üzerinde isem ve O\'nun katından bana bir rahmet verilmişse ve siz de bunu görmüyorsanız; istemediğiniz halde,  onu size zorla kabul ettirebilir miyim?\"', 'قال يقوم اريتم ان كنت علي بينة من ربي واتيني رحمة من عنده فعميت عليكم انلزمكموها وانتم لها كرهون'),
(1502, 11, 29, 'وَيَا قَوْمِ لَٓا اَسْـَٔلُكُمْ عَلَيْهِ مَالاًۜ اِنْ اَجْرِيَ اِلَّا عَلَى اللّٰهِ وَمَٓا اَنَا۬ بِطَارِدِ الَّذ۪ينَ اٰمَنُواۜ اِنَّهُمْ مُلَاقُوا رَبِّهِمْ وَلٰكِنّ۪ٓي اَرٰيكُمْ قَوْماً تَجْهَلُونَ', 'Ve ya kavmi la es\'elukum aleyhi mala, in ecriye illa alallahi ve ma ene bi taridillezine amenu, innehum mulaku rabbihim ve lakinni erakum kavmen techelun.', '\"Ey halkım! Buna karşı sizden herhangi bir ücret istemiyorum. Benim ücretim,  yalnızca Allah\'a aittir. Siz,  hor görüyorsunuz diye,  iman edenleri yanımdan kovacak değilim. Onlar,  Rabb\'lerine kavuşacaklardır. Fakat ben,  sizi cahillik eden bir halk olarak görüyorum.\"', 'ويقوم لا اسلكم عليه مالا ان اجري الا علي الله وما انا بطارد الذين امنوا انهم ملقوا ربهم ولكني اريكم قوما تجهلون'),
(1503, 11, 30, 'وَيَا قَوْمِ مَنْ يَنْصُرُن۪ي مِنَ اللّٰهِ اِنْ طَرَدْتُهُمْۜ اَفَلَا تَذَكَّرُونَ', 'Ve ya kavmi men yansuruni minallahi in taredtuhum, e fe la tezekkerun.', '\"Ey halkım! Eğer onları yanımdan kovacak olursam,  Allah\'a karşı bana kim yardımcı olacak? Hiç düşünmüyor musunuz?\"', 'ويقوم من ينصرني من الله ان طردتهم افلا تذكرون'),
(1504, 11, 31, 'وَلَٓا اَقُولُ لَكُمْ عِنْد۪ي خَزَٓائِنُ اللّٰهِ وَلَٓا اَعْلَمُ الْغَيْبَ وَلَٓا اَقُولُ اِنّ۪ي مَلَكٌ وَلَٓا اَقُولُ لِلَّذ۪ينَ تَزْدَر۪ٓي اَعْيُنُكُمْ لَنْ يُؤْتِيَهُمُ اللّٰهُ خَيْراًۜ اَللّٰهُ اَعْلَمُ بِمَا ف۪ٓي اَنْفُسِهِمْۚ اِنّ۪ٓي اِذاً لَمِنَ الظَّالِم۪ينَ', 'Ve la ekulu lekum indi hazainullahi ve la a\'lemul gaybe ve la ekulu inni melekun ve la ekulu lillezine tezderi a\'yunukum len yu\'tiyehumullahu hayra, allahu a\'lemu bima fi enfusihim, inni izen le minez zalimin.', '\"Ben size,  \"Allah\'ın hazineleri benim yanımdadır.\" demiyorum. Ben[1] gaybı da bilmem. Yine \"Ben meleğim.\" de demiyorum. Hor gördüğünüz kimseler için,  \"Allah,  onlara hiçbir hayır vermeyecektir.\" de demiyorum. İçlerinde olanı Allah daha iyi bilir. Böyle bir şey yaptığım takdirde zalimlerden olurum.\"', 'ولا اقول لكم عندي خزاين الله ولا اعلم الغيب ولا اقول اني ملك ولا اقول للذين تزدري اعينكم لن يوتيهم الله خيرا الله اعلم بما في انفسهم اني اذا لمن الظلمين'),
(1505, 11, 32, 'قَالُوا يَا نُوحُ قَدْ جَادَلْتَنَا فَاَكْثَرْتَ جِدَالَنَا فَأْتِنَا بِمَا تَعِدُنَٓا اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Kalu ya nuhu kad cadeltena fe ekserte cidalena fe\'tina bi ma teiduna in kunte mines sadikin.', 'Dediler ki: \"Ey Nuh! Bizimle mücadele ettin. Üstelik bu mücadelede çok ileri gittin. Eğer doğru söyleyenlerden isen,  bizi tehdit ettiğin şeyi getir de görelim!\"', 'قالوا ينوح قد جدلتنا فاكثرت جدلنا فاتنا بما تعدنا ان كنت من الصدقين'),
(1506, 11, 33, 'قَالَ اِنَّمَا يَأْت۪يكُمْ بِهِ اللّٰهُ اِنْ شَٓاءَ وَمَٓا اَنْتُمْ بِمُعْجِز۪ينَ', 'Kale innema ye\'tikum bihillahu in şae ve ma entum bi mu\'cizin.', 'Dedi ki: \"Onu size dilediği takdirde ancak Allah getirir. Ve siz,  O\'nu asla aciz bırakamazsınız.\"', 'قال انما ياتيكم به الله ان شا وما انتم بمعجزين'),
(1507, 11, 34, 'وَلَا يَنْفَعُكُمْ نُصْح۪ٓي اِنْ اَرَدْتُ اَنْ اَنْصَحَ لَكُمْ اِنْ كَانَ اللّٰهُ يُر۪يدُ اَنْ يُغْوِيَكُمْۜ هُوَ رَبُّكُمْ وَاِلَيْهِ تُرْجَعُونَۜ', 'Ve la yenfeukum nushi in eredtu en ensaha lekum in kanallahu yuridu en yugviyekum, huve rabbukum ve ileyhi turceun.', '\"Eğer Allah sizi azdırmayı dilerse[1],  size öğüt versem de öğüdüm yarar sağlamaz. Rabb\'iniz O\'dur,  O\'na döndürüleceksiniz.\"', 'ولا ينفعكم نصحي ان اردت ان انصح لكم ان كان الله يريد ان يغويكم هو ربكم واليه ترجعون'),
(1508, 11, 35, 'اَمْ يَقُولُونَ افْتَرٰيهُۜ قُلْ اِنِ افْتَرَيْتُهُ فَعَلَيَّ اِجْرَام۪ي وَاَنَا۬ بَر۪ٓيءٌ مِمَّا تُجْرِمُونَ۟', 'Em yekulunefterah, kul iniftereytuhu fe aleyye icrami ve ene beriun mimma tucrimun.', 'Yoksa \"Onu kendisi uydurdu\" mu diyorlar? De ki: \"Eğer uydurduysam,  suçu bana aittir. Ben de sizin işlediğiniz suçlardan uzağım.\"', 'ام يقولون افتريه قل ان افتريته فعلي اجرامي وانا بري مما تجرمون'),
(1509, 11, 36, 'وَاُو۫حِيَ اِلٰى نُوحٍ اَنَّهُ لَنْ يُؤْمِنَ مِنْ قَوْمِكَ اِلَّا مَنْ قَدْ اٰمَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَفْعَلُونَۚ', 'Ve uhiye ila nuhın ennehu len yu\'mine min kavmike illa men kad amene fe la tebteis bi ma kanu yef\'alun.', 'Nuh\'a vahyedildi: \"Şu ana kadar inanmış olanların dışında,  senin halkından kesinlikle kimse inanmayacak. Onların yaptıklarından dolayı tasalanma;\"', 'واوحي الي نوح انه لن يومن من قومك الا من قد امن فلا تبتيس بما كانوا يفعلون'),
(1510, 11, 37, 'وَاصْنَعِ الْفُلْكَ بِاَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَاطِبْن۪ي فِي الَّذ۪ينَ ظَلَمُواۚ اِنَّهُمْ مُغْرَقُونَ', 'Vasnaıl fulke bi a\'yunina ve vahyina ve la tuhatıbni fillezine zalemu, innehum mugrekun.', '\"Bizim gözetimimiz altında ve vahyimizle gemiyi yap. Zalimler hakkında benden bir istekte bulunma. Onlar boğulacaklardır.\"', 'واصنع الفلك باعيننا ووحينا ولا تخطبني في الذين ظلموا انهم مغرقون'),
(1511, 11, 38, 'وَيَصْنَعُ الْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَاٌ مِنْ قَوْمِه۪ سَخِرُوا مِنْهُۜ قَالَ اِنْ تَسْخَرُوا مِنَّا فَاِنَّا نَسْخَرُ مِنْكُمْ كَمَا تَسْخَرُونَۜ', 'Ve yasneul fulke ve kullema merre aleyhi meleun min kavmihi sehıru minh, kale in tesharu minna fe inna nesharu minkum kema tesharun.', 'Gemiyi yapıyordu. Halkının meleleri[1],  onun yanından ne zaman geçseler,  onunla alay ediyorlardı. Dedi ki: \"Alay edin bakalım! Görürsünüz,  sizin bizimle alay ettiğiniz gibi biz de sizinle alay edeceğiz.\"', 'ويصنع الفلك وكلما مر عليه ملا من قومه سخروا منه قال ان تسخروا منا فانا نسخر منكم كما تسخرون'),
(1512, 11, 39, 'فَسَوْفَ تَعْلَمُونَۙ مَنْ يَأْت۪يهِ عَذَابٌ يُخْز۪يهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُق۪يمٌ', 'Fe sevfe ta\'lemune men ye\'tihi azabun yuhzihi ve yehıllu aleyhi azabun mukim.', '\"Alçaltıcı azabın kime geleceğini ve kalıcı azaba kimin uğrayacağını yakında bileceksiniz.\"', 'فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم'),
(1513, 11, 40, 'حَتّٰٓى اِذَا جَٓاءَ اَمْرُنَا وَفَارَ التَّنُّورُۙ قُلْنَا احْمِلْ ف۪يهَا مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَاَهْلَكَ اِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ وَمَنْ اٰمَنَۜ وَمَٓا اٰمَنَ مَعَهُٓ اِلَّا قَل۪يلٌ', 'Hatta iza cae emruna ve faret tennuru kulnahmil fiha min kullin zevceynisneyni ve ehleke illa men sebeka aleyhil kavlu ve men amen, ve ma amene meahu illa kalil.', 'Buyruğumuz gelip tandır kaynamağa[1] başladığı zaman,  Biz dedik ki: \"Her cinsten birer çift[2] ve aleyhlerinde hüküm verilmiş olanlar hariç aileni ve iman edenleri ona yükle.\" Zaten onunla birlikte çok az kimse iman etmişti.', 'حتي اذا جا امرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين واهلك الا من سبق عليه القول ومن امن وما امن معه الا قليل'),
(1514, 11, 41, 'وَقَالَ ارْكَبُوا ف۪يهَا بِسْمِ اللّٰهِ مَجْرٰۭۙيهَا وَمُرْسٰيهَاۜ اِنَّ رَبّ۪ي لَغَفُورٌ رَح۪يمٌ', 'Ve kalerkebu fiha bismillahi mecraha ve mursaha, inne rabbi le gafurun rahim.', '\"Haydi,  binin.\" dedi. Onun gitmesi de durması da Allah\'ın adıyladır. Elbette Rabb\'im Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'وقال اركبوا فيها بسم الله مجريها ومرسها ان ربي لغفور رحيم'),
(1515, 11, 42, 'وَهِيَ تَجْر۪ي بِهِمْ ف۪ي مَوْجٍ كَالْجِبَالِ وَنَادٰى نُوحٌۨ ابْنَهُ وَكَانَ ف۪ي مَعْزِلٍ يَا بُنَيَّ ارْكَبْۭۗ مَعَنَا وَلَا تَكُنْ مَعَ الْكَافِر۪ينَ', 'Ve hiye tecri bihim fi mevcin kel cibali ve nada nuhunibnehu ve kane fi ma\'zilin ya buneyyerkeb meana ve la tekun meal kafirin.', 'Gemi dağlar gibi dalgalar arasında akıp gidiyordu. Nuh,  bir kenarda bekleyen oğluna:\" Yavrum bizimle beraber sen de bin; Kafirlerle[1] beraber kalma.\" diye seslendi.', 'وهي تجري بهم في موج كالجبال ونادي نوح ابنه وكان في معزل يبني اركب معنا ولا تكن مع الكفرين'),
(1516, 11, 43, 'قَالَ سَاٰو۪ٓي اِلٰى جَبَلٍ يَعْصِمُن۪ي مِنَ الْمَٓاءِۜ قَالَ لَا عَاصِمَ الْيَوْمَ مِنْ اَمْرِ اللّٰهِ اِلَّا مَنْ رَحِمَۚ وَحَالَ بَيْنَهُمَا الْمَوْجُ فَكَانَ مِنَ الْمُغْرَق۪ينَ', 'Kale seavi ila cebelin ya\'sımuni minel ma\' kale la asımel yevme min emrillahi illa men rahim, ve hale beynehumal mevcu fe kane minel mugrakin.', 'O: \"Dağa sığınırım,  beni sudan kurtarır.\" deyince; \"Bugün Allah\'ın rahmetine erişenden başkasını,  Allah\'ın emrinden koruyacak hiçbir şey yoktur.\" dedi. Aralarına dalga girdi ve o da boğulanlardan oldu.', 'قال ساوي الي جبل يعصمني من الما قال لا عاصم اليوم من امر الله الا من رحم وحال بينهما الموج فكان من المغرقين'),
(1517, 11, 44, 'وَق۪يلَ يَٓا اَرْضُ ابْلَع۪ي مَٓاءَكِ وَيَا سَمَٓاءُ اَقْلِع۪ي وَغ۪يضَ الْمَٓاءُ وَقُضِيَ الْاَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ وَق۪يلَ بُعْداً لِلْقَوْمِ الظَّالِم۪ينَ', 'Ve kile ya ardublei maeki ve ya semau aklii ve gidal mau ve kudıyel emru vestevet alal cudiyyi ve kile bu\'den lil kavmiz zalimin.', '\"Ey yer,  suyunu çek ve ey gök,  suyunu kes.\" denildi. Su çekildi,  iş bitirildi. Gemi Cudi\'ye oturdu. \"Zalimler topluluğu Allah\'ın rahmetinden uzak olsun.\" denildi.[1]', 'وقيل يارض ابلعي ماك ويسما اقلعي وغيض الما وقضي الامر واستوت علي الجودي وقيل بعدا للقوم الظلمين'),
(1518, 11, 45, 'وَنَادٰى نُوحٌ رَبَّهُ فَقَالَ رَبِّ اِنَّ ابْن۪ي مِنْ اَهْل۪ي وَاِنَّ وَعْدَكَ الْحَقُّ وَاَنْتَ اَحْكَمُ الْحَاكِم۪ينَ', 'Ve nada nuhun rabbehu fe kale rabbi innebni min ehli ve inne va\'dekel hakku ve ente ahkemul hakimin.', 'Nuh,  Rabb\'ine seslendi: \"Ey Rabb\'im! Oğlum benim ehlimdendir. Senin uyarın elbette gerçektir. Sen,  hakimlerin hakimisin.\"[1] dedi.', 'ونادي نوح ربه فقال رب ان ابني من اهلي وان وعدك الحق وانت احكم الحكمين'),
(1519, 11, 46, 'قَالَ يَا نُوحُ اِنَّهُ لَيْسَ مِنْ اَهْلِكَۚ اِنَّهُ عَمَلٌ غَيْرُ صَالِحٍۗ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِه۪ عِلْمٌۜ اِنّ۪ٓي اَعِظُكَ اَنْ تَكُونَ مِنَ الْجَاهِل۪ينَ', 'Kale ya nuhu innehu leyse min ehlik, innehu amelun gayru salih, fe la tes\'elni ma leyse leke bihi ilm, inni eızuke en tekune minel cahilin.', 'Dedi ki: \"Ey Nuh! O senin ehlinden değildir. Zira onun yaptığı doğru olmayan bir işti. Öyleyse hakkında bilgin olmayan[1] şeyi Benden isteme. Cahillerden[2] olmaktan seni sakındırıyorum.\"', 'قال ينوح انه ليس من اهلك انه عمل غير صلح فلا تسلن ما ليس لك به علم اني اعظك ان تكون من الجهلين'),
(1520, 11, 47, 'قَالَ رَبِّ اِنّ۪ٓي اَعُوذُ بِكَ اَنْ اَسْـَٔلَكَ مَا لَيْسَ ل۪ي بِه۪ عِلْمٌۜ وَاِلَّا تَغْفِرْ ل۪ي وَتَرْحَمْن۪ٓي اَكُنْ مِنَ الْخَاسِر۪ينَ', 'Kale rabbi inni euzu bike en es\'eleke ma leyse li bihi ilm, ve illa tagfirli ve terhamni ekun minel hasirin.', '\"Rabb\'im! Bilmediğim bir şeyi Sen\'den istemekten Sana sığınırım. Eğer beni bağışlamaz ve merhamet etmezsen hüsrana uğrayanlardan olurum.\" dedi.', 'قال رب اني اعوذ بك ان اسلك ما ليس لي به علم والا تغفر لي وترحمني اكن من الخسرين'),
(1521, 11, 48, 'ق۪يلَ يَا نُوحُ اهْبِطْ بِسَلَامٍ مِنَّا وَبَرَكَاتٍ عَلَيْكَ وَعَلٰٓى اُمَمٍ مِمَّنْ مَعَكَۜ وَاُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُمْ مِنَّا عَذَابٌ اَل۪يمٌ', 'Kile ya nuhuhbıt bi selamin minna ve berekatin aleyke ve ala umemin mimmen meak, ve umemun se numettiuhum summe yemessuhum minna azabun elim.', 'Dendi ki: \"Ey Nuh! Katımızdan esenlikle in. Sana ve sana tabi olan topluluklara bereketler olsun. Ama öyle toplumlar da olacak ki,  onları dünya nimetlerinden yararlandıracağız,  sonra onlara Bizden can yakıcı bir azap dokunacaktır.\"', 'قيل ينوح اهبط بسلم منا وبركت عليك وعلي امم ممن معك وامم سنمتعهم ثم يمسهم منا عذاب اليم'),
(1522, 11, 49, 'تِلْكَ مِنْ اَنْـبَٓاءِ الْغَيْبِ نُوح۪يهَٓا اِلَيْكَۚ مَا كُنْتَ تَعْلَمُهَٓا اَنْتَ وَلَا قَوْمُكَ مِنْ قَبْلِ هٰذَاۜۛ فَاصْبِرْۜۛ اِنَّ الْعَاقِبَةَ لِلْمُتَّق۪ينَ۟', 'Tilke min enbail gaybi nuhiha ileyk, ma kunte ta\'lemuha ente ve la kavmuke min kabli haza, fasbır, innel akıbete lil muttekin.', '\"İşte bunlar,  sana vahyettiğimiz gayb haberlerindendir. Bunları ne sen ne de halkın daha önce bilmiyordunuz. O halde sabret. Sonuç,  takva sahiplerinindir.\"', 'تلك من انبا الغيب نوحيها اليك ما كنت تعلمها انت ولا قومك من قبل هذا فاصبر ان العقبة للمتقين'),
(1523, 11, 50, 'وَاِلٰى عَادٍ اَخَاهُمْ هُوداًۜ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ اِنْ اَنْتُمْ اِلَّا مُفْتَرُونَ', 'Ve ila adin ehahum huda, kale ya kavmi\'budullahe ma lekum min ilahin gayruh, in entum illa mufterun.', 'Âd halkına kardeşleri Hud\'u gönderdik. Dedi ki: \"Ey halkım! Yalnızca Allah\'a kulluk edin. Sizin ondan başka bir ilahınız yoktur; siz bu tutumunuzla iftira etmekten başka bir şey yapmıyorsunuz.', 'والي عاد اخاهم هودا قال يقوم اعبدوا الله ما لكم من اله غيره ان انتم الا مفترون'),
(1524, 11, 51, 'يَا قَوْمِ لَٓا اَسْـَٔلُكُمْ عَلَيْهِ اَجْراًۜ اِنْ اَجْرِيَ اِلَّا عَلَى الَّذ۪ي فَطَرَن۪يۜ اَفَلَا تَعْقِلُونَ', 'Ya kavmi la es\'elukum aleyhi ecra, in ecriye illa alellezi fetarani, e fe la ta\'kılun.', '\"Ey halkım! Bunun için sizden bir ücret istemiyorum. Benim ücretim,  yalnızca bana bu benliği verene aittir. Aklınızı kullanmayacak mısınız?\"[1]', 'يقوم لا اسلكم عليه اجرا ان اجري الا علي الذي فطرني افلا تعقلون'),
(1525, 11, 52, 'وَيَا قَوْمِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُٓوا اِلَيْهِ يُرْسِلِ السَّمَٓاءَ عَلَيْكُمْ مِدْرَاراً وَيَزِدْكُمْ قُوَّةً اِلٰى قُوَّتِكُمْ وَلَا تَتَوَلَّوْا مُجْرِم۪ينَ', 'Ve ya kavmistagfiru rabbekum summe tubu ileyhi yursilis semae aleykum midraran ve yezidkum kuvveten ila kuvvetikum ve la tetevellev mucrimin.', '\"Ey halkım! Rabb\'inizden bağışlanma dileyin. Sonra O\'na tevbe[1] edin,  gökten üzerinize bol bol rahmet göndersin,  gücünüze güç katsın. Mücrimler[2] olarak yüz çevirmeyin.\"', 'ويقوم استغفروا ربكم ثم توبوا اليه يرسل السما عليكم مدرارا ويزدكم قوة الي قوتكم ولا تتولوا مجرمين'),
(1526, 11, 53, 'قَالُوا يَا هُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِك۪ٓي اٰلِهَتِنَا عَنْ قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِن۪ينَ', 'Kalu ya hudu ma ci\'tena bibeyyinetin ve ma nahnu bi tariki alihetina an kavlike ve ma nahnu leke bi muminin.', 'Dediler ki: \"Ey Hud! Bize kanıt içeren bir bilgi getirmedin; biz,  senin sözünle ilahlarımızı terk edecek değiliz. Ve biz sana inanacak da değiliz.\"', 'قالوا يهود ما جيتنا ببينة وما نحن بتاركي الهتنا عن قولك وما نحن لك بمومنين'),
(1527, 11, 54, 'اِنْ نَقُولُ اِلَّا اعْتَرٰيكَ بَعْضُ اٰلِهَتِنَا بِسُٓوءٍۜ قَالَ اِنّ۪ٓي اُشْهِدُ اللّٰهَ وَاشْهَدُٓوا اَنّ۪ي بَر۪ٓيءٌ مِمَّا تُشْرِكُونَۙ', 'İn nekulu illa\'terake ba\'du alihetina bi su\', kale inni uşhidullahe veşhedu enni beriun mimma tuşrikune.', '\"İlahlarımızdan biri seni fena çarpmış,  demekten başka bir sözümüz yok.\" dediler. Hud da: \"Ben Allah\'ı tanık tutuyorum. Siz de tanık olun ki ben müşriklerden değilim.\" dedi.', 'ان نقول الا اعتريك بعض الهتنا بسو قال اني اشهد الله واشهدوا اني بري مما تشركون'),
(1528, 11, 55, 'مِنْ دُونِه۪ فَك۪يدُون۪ي جَم۪يعاً ثُمَّ لَا تُنْظِرُونِ', 'Min dunihi fe kiduni cemian summe la tunzırun.', '\"Haydi,  hiç zaman kaybetmeden bana istediğiniz tuzağı kurun.\"', 'من دونه فكيدوني جميعا ثم لا تنظرون'),
(1529, 11, 56, 'اِنّ۪ي تَوَكَّلْتُ عَلَى اللّٰهِ رَبّ۪ي وَرَبِّكُمْۜ مَا مِنْ دَٓابَّةٍ اِلَّا هُوَ اٰخِذٌ بِنَاصِيَتِهَاۜ اِنَّ رَبّ۪ي عَلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'İnni tevekkeltu alallahi rabbi ve rabbikum, ma min dabbetin illa huve ahızun bi nasıyetiha, inne rabbi ala sıratın mustekim.', '\"Ben,  benim de Rabb\'im sizin de Rabb\'iniz olan Allah\'a tevekkül[1] ettim. Hiçbir canlı yoktur ki O\'nun buyruğunda/kontrolünde olmasın. Kuşkusuz Rabb\'im dosdoğru bir yol üzerindedir.\"', 'اني توكلت علي الله ربي وربكم ما من دابة الا هو اخذ بناصيتها ان ربي علي صرط مستقيم'),
(1530, 11, 57, 'فَاِنْ تَوَلَّوْا فَقَدْ اَبْلَغْتُكُمْ مَٓا اُرْسِلْتُ بِه۪ٓ اِلَيْكُمْۜ وَيَسْتَخْلِفُ رَبّ۪ي قَوْماً غَيْرَكُمْۚ وَلَا تَضُرُّونَهُ شَيْـٔاًۜ اِنَّ رَبّ۪ي عَلٰى كُلِّ شَيْءٍ حَف۪يظٌ', 'Fe in tevellev fe kad eblagtukum ma ursiltu bihi ileykum, ve yestahlifu rabbi kavmen gayrekum, ve la tedurrunehu şey\'a, inne rabbi ala kulli şey\'in hafiz.', '\"Eğer yüz çevirirseniz,  bilin ki size iletmek üzere gönderildiğim mesajı size ilettim. Rabb\'im,  yerinize sizden başka bir halk getirebilir ve siz O\'na hiçbir şekilde engel olamazsınız. Rabb\'im,  her şeyi koruyup gözetendir.\"', 'فان تولوا فقد ابلغتكم ما ارسلت به اليكم ويستخلف ربي قوما غيركم ولا تضرونه شيا ان ربي علي كل شي حفيظ'),
(1531, 11, 58, 'وَلَمَّا جَٓاءَ اَمْرُنَا نَجَّيْنَا هُوداً وَالَّذ۪ينَ اٰمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّاۚ وَنَجَّيْنَاهُمْ مِنْ عَذَابٍ غَل۪يظٍ', 'Ve lemma cae emruna necceyna huden vellezine amenu meahu bi rahmetin minna, ve necceynahum min azabin galiz.', 'Buyruğumuz gerçekleşince,  Hud\'u ve beraberindeki iman edenleri Bizden bir rahmetle kurtardık. Onları şiddeti çok ağır bir azaptan kurtardık.', 'ولما جا امرنا نجينا هودا والذين امنوا معه برحمة منا ونجينهم من عذاب غليظ'),
(1532, 11, 59, 'وَتِلْكَ عَادٌ جَحَدُوا بِاٰيَاتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُٓوا اَمْرَ كُلِّ جَبَّارٍ عَن۪يدٍ', 'Ve tilke adun cehadu bi ayati rabbihim ve asav rusulehu vettebeu emre kulli cebbarin anid.', 'İşte Âd halkı Rabb\'lerinin ayetlerini inkar ettiler ve resullerine isyan ettiler. İnatçı zorbanın her buyruğuna uydular.', 'وتلك عاد جحدوا بايت ربهم وعصوا رسله واتبعوا امر كل جبار عنيد'),
(1533, 11, 60, 'وَاُتْبِعُوا ف۪ي هٰذِهِ الدُّنْيَا لَعْنَةً وَيَوْمَ الْقِيٰمَةِۜ  اَلَٓا اِنَّ عَاداً كَفَرُوا رَبَّهُمْۜ اَلَا بُعْداً لِعَادٍ قَوْمِ هُودٍ۟', 'Ve utbiu fi hazihid dunya la\'neten ve yevmel kıyameh, e la inne aden keferu rabbehum, e la bu\'den li adin kavmi hud.', 'Bu dünyada da Kıyamet Günü\'nde de lanete tabi tutuldular. İyi bilin ki gerçekten Âd halkı Rabb\'lerine nankörlük ettiler. İşte böyle yok olup gitti Hud halkı Âd.', 'واتبعوا في هذه الدنيا لعنة ويوم القيمة الا ان عادا كفروا ربهم الا بعدا لعاد قوم هود'),
(1534, 11, 61, 'وَاِلٰى ثَمُودَ اَخَاهُمْ صَالِحاًۢ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ هُوَ اَنْشَاَكُمْ مِنَ الْاَرْضِ وَاسْتَعْمَرَكُمْ ف۪يهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُٓوا اِلَيْهِۜ اِنَّ رَبّ۪ي قَر۪يبٌ مُج۪يبٌ', 'Ve ila semude ehahum saliha, kale ya kavmi\'budullahe ma lekum min ilahin gayruh, huve enşeekum minel ardı vesta\'merekum fiha festagfiruhu summe tubu ileyh, inne rabbi karibun mucib.', 'Semud halkına da kardeşleri Salih\'i gönderdik. Ey halkım: \"Allah\'a kulluk edin. Sizin O\'ndan başka ilahınız yoktur.\" dedi. \"Sizi yer yüzünde meydana getiren ve sizi orayı imar etmekle görevli kılan O\'dur. Öyleyse O\'ndan bağışlanma dileyin. Sonra O\'na tevbe ile yönelin. Rabb\'im,  Çok Yakın\'dır,  İsteklere Cevap Veren\'dir.\"', 'والي ثمود اخاهم صلحا قال يقوم اعبدوا الله ما لكم من اله غيره هو انشاكم من الارض واستعمركم فيها فاستغفروه ثم توبوا اليه ان ربي قريب مجيب'),
(1535, 11, 62, 'قَالُوا يَا صَالِحُ قَدْ كُنْتَ ف۪ينَا مَرْجُواًّ قَبْلَ هٰذَٓا اَتَنْهٰينَٓا اَنْ نَعْبُدَ مَا يَعْبُدُ اٰبَٓاؤُ۬نَا وَاِنَّنَا لَف۪ي شَكٍّ مِمَّا تَدْعُونَٓا اِلَيْهِ مُر۪يبٍ', 'Kalu ya salihu kad kunte fina mercuvven kable haza e tenhana en na\'bude ma ya\'budu abauna ve innena le fi şekkin mimma ted\'una ileyhi murib.', '\"Ey Salih! Sen,  bundan önce aramızda ümit beslenen biriydin. Şimdi atalarımızın kulluk ettiklerine kulluk etmekten bizi vazgeçirmek mi istiyorsun? Ve biz,  gerçekten de senin bizi çağırdığın şey hakkında ikilem içindeyiz,  kaygılanıyoruz.\" dediler.', 'قالوا يصلح قد كنت فينا مرجوا قبل هذا اتنهينا ان نعبد ما يعبد اباونا واننا لفي شك مما تدعونا اليه مريب'),
(1536, 11, 63, 'قَالَ يَا قَوْمِ اَرَاَيْتُمْ اِنْ كُنْتُ عَلٰى بَيِّنَةٍ مِنْ رَبّ۪ي وَاٰتٰين۪ي مِنْهُ رَحْمَةً فَمَنْ يَنْصُرُن۪ي مِنَ اللّٰهِ اِنْ عَصَيْتُهُ فَمَا تَز۪يدُونَن۪ي غَيْرَ تَخْس۪يرٍ', 'Kale ya kavmi e reeytum in kuntu ala beyyinetin min rabbi ve atani minhu rahmeten fe men yansuruni minallahi in asaytuhu fe ma teziduneni gayre tahsir.', '\"Ey halkım,  söyleyin bakalım,  ya Rabb\'imin Kendinden verdiği bir rahmetle,  kanıt içeren açık bir bilgi üzerindeysem! Ona asi olduğum takdirde,  Allah\'ın vereceği cezaya karşı bana kim yardım edebilir? Bana zarar vermiş olmaktan başka bir şey yapmış olmazsınız.\" dedi.', 'قال يقوم اريتم ان كنت علي بينة من ربي واتيني منه رحمة فمن ينصرني من الله ان عصيته فما تزيدونني غير تخسير'),
(1537, 11, 64, 'وَيَا قَوْمِ هٰذِه۪ نَاقَةُ اللّٰهِ لَكُمْ اٰيَةً فَذَرُوهَا تَأْكُلْ ف۪ٓي اَرْضِ اللّٰهِ وَلَا تَمَسُّوهَا بِسُٓوءٍ فَيَأْخُذَكُمْ عَذَابٌ قَر۪يبٌ', 'Ve ya kavmi hazihi nakatullahi lekum ayeten fe zeruha te\'kul fi ardıllahi ve la temessuha bi suin fe ye\'huzekum azabun karib.', '\"Ey halkım! İşte şu Allah\'ın dişi devesi[1],  sizin için bir ayettir.[2] Bırakın onu,  Allah\'ın arzında otlasın. Kötü bir amaçla ona yaklaşmayın. Yoksa sizi yakın bir azap yakalar.\"', 'ويقوم هذه ناقة الله لكم اية فذروها تاكل في ارض الله ولا تمسوها بسو فياخذكم عذاب قريب'),
(1538, 11, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا ف۪ي دَارِكُمْ ثَلٰثَةَ اَيَّامٍۜ ذٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', 'Fe akaruha fe kale temetteu fi darikum selasete eyyam, zalike va\'dun gayru mekzub.', 'Yine de onu kestiler.[1] \"Yurdunuzda üç gün yaşayın.[2] Bu yalan olmayan bir uyarıdır.\" dedi.', 'فعقروها فقال تمتعوا في داركم ثلثة ايام ذلك وعد غير مكذوب'),
(1539, 11, 66, 'فَلَمَّا جَٓاءَ اَمْرُنَا نَجَّيْنَا صَالِحاً وَالَّذ۪ينَ اٰمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَمِنْ خِزْيِ يَوْمِئِذٍۜ اِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَز۪يزُ', 'Fe lemma cae emruna necceyna salihan vellezine amenu meahu bi rahmetin minna ve min hizyi yevmi iz, inne rabbeke huvel kaviyyul aziz.', 'Nihayet haklarındaki yargımız gerçekleşerek,  Salih\'i ve beraberinde iman etmiş olanları tarafımızdan bir rahmetle izin gününün[1] zilletinden kurtardık. Rabb\'in,  Çok Güçlü\'dür,  Mutlak Üstün Olan\'dır.', 'فلما جا امرنا نجينا صلحا والذين امنوا معه برحمة منا ومن خزي يوميذ ان ربك هو القوي العزيز'),
(1540, 11, 67, 'وَاَخَذَ الَّذ۪ينَ ظَلَمُوا الصَّيْحَةُ فَاَصْبَحُوا ف۪ي دِيَارِهِمْ جَاثِم۪ينَۙ', 'Ve ehazellezine zalemus sayhatu fe asbahu fi diyarihim casimin.', 'Zulmedenleri bir çığlık yakaladı. Yurtlarında dizüstü çökmüş olarak sabahladılar.', 'واخذ الذين ظلموا الصيحة فاصبحوا في ديرهم جثمين'),
(1541, 11, 68, 'كَاَنْ لَمْ يَغْنَوْا ف۪يهَاۜ اَلَٓا اِنَّ ثَمُودَا۬ كَفَرُوا رَبَّهُمْۜ اَلَا بُعْداً لِثَمُودَ۟', 'Ke en lem yagnev fiha, e la inne semude keferu rabbehum, e la bu\'den li semud.', 'Sanki orada hiç yaşamamışlardı. İyi bilin ki Semud halkı Rabb\'lerine nankörlük ettiler. İyi bilin ki Semud halkı yok olup gitti.', 'كان لم يغنوا فيها الا ان ثمودا كفروا ربهم الا بعدا لثمود'),
(1542, 11, 69, 'وَلَقَدْ جَٓاءَتْ رُسُلُنَٓا اِبْرٰه۪يمَ بِالْبُشْرٰى قَالُوا سَلَاماًۜ قَالَ سَلَامٌۚ فَمَا لَبِثَ اَنْ جَٓاءَ بِعِجْلٍ حَن۪يذٍ', 'Ve lekad caet rusuluna ibrahime bil buşra kalu selama, kale selamun fe ma lebise en cae bi iclin haniz.', 'Ant olsun elçilerimiz İbrahim\'e haber vermek için gelip,  \"Selam!\" dediler.[1] \"Selam!\" dedi ve hemen gidip kızarmış buzağı eti getirdi.', 'ولقد جات رسلنا ابرهيم بالبشري قالوا سلما قال سلم فما لبث ان جا بعجل حنيذ'),
(1543, 11, 70, 'فَلَمَّا رَآٰ اَيْدِيَهُمْ لَا تَصِلُ اِلَيْهِ نَكِرَهُمْ وَاَوْجَسَ مِنْهُمْ خ۪يفَةًۜ قَالُوا لَا تَخَفْ اِنَّٓا اُرْسِلْـنَٓا اِلٰى قَوْمِ لُوطٍۜ', 'Fe lemma rea eydiyehum la tesilu ileyhi nekirehum ve evcese minhum hifeh, kalu la tehaf inna ursilna ila kavmi lut.', 'Ona ellerini uzatmadıklarını görünce,  onlardan kuşkulanıp korkuya kapıldı. \"Korkma! Biz Lut halkına gönderildik.\" dediler.', 'فلما را ايديهم لا تصل اليه نكرهم واوجس منهم خيفة قالوا لا تخف انا ارسلنا الي قوم لوط'),
(1544, 11, 71, 'وَامْرَاَتُهُ قَٓائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَاهَا بِاِسْحٰقَۙ وَمِنْ وَرَٓاءِ اِسْحٰقَ يَعْقُوبَ', 'Vemreetuhu kaimetun fe dahıket fe beşşernaha bi ishaka ve min verai ishaka ya\'kub.', 'Ayakta duran hanımı bunun üzerine gülümsedi.[1] Biz de ona İshak\'ı müjdeledik ve İshak\'ın arkasından da Yakub\'u.', 'وامراته قايمة فضحكت فبشرنها باسحق ومن ورا اسحق يعقوب'),
(1545, 11, 72, 'قَالَتْ يَا وَيْلَتٰٓى ءَاَلِدُ وَاَنَا۬ عَجُوزٌ وَهٰذَا بَعْل۪ي شَيْخاًۜ اِنَّ هٰذَا لَشَيْءٌ عَج۪يبٌ', 'Kalet ya veyleta e elidu ve ene ecuzun ve haza ba\'li şeyha, inne haza le şey\'un acib.', '\"Vay başıma gelene! Ben bir koca karı,  kocam da bir ihtiyar olduğumuz halde,  doğuracak mıyım? Doğrusu bu çok hayret edilecek bir şey!\" dedi.', 'قالت يويلتي الد وانا عجوز وهذا بعلي شيخا ان هذا لشي عجيب'),
(1546, 11, 73, 'قَالُٓوا اَتَعْجَب۪ينَ مِنْ اَمْرِ اللّٰهِ رَحْمَتُ اللّٰهِ وَبَرَكَاتُهُ عَلَيْكُمْ اَهْلَ الْبَيْتِۜ اِنَّهُ حَم۪يدٌ مَج۪يدٌ', 'Kalu e ta\'cebine min emrillahi rahmetullahi ve berekatuhu aleykum ehlel beyt, innehu hamidun mecid.', '\"Allah\'ın takdirine hayret mi ediyorsun!\" dediler. Allah\'ın rahmeti ve bereketleri sizin üzerinizedir ey ev halkı. O,  Övgüye Değer Yegane Varlık\'tır,  İyiliği Bol Olan\'dır.', 'قالوا اتعجبين من امر الله رحمت الله وبركته عليكم اهل البيت انه حميد مجيد'),
(1547, 11, 74, 'فَلَمَّا ذَهَبَ عَنْ اِبْرٰه۪يمَ الرَّوْعُ وَجَٓاءَتْهُ الْبُشْرٰى يُجَادِلُنَا ف۪ي قَوْمِ لُوطٍۜ', 'Fe lemma zehebe an ibrahimer rev\'u ve caethul buşra yucadiluna fi kavmi lut.', 'İbrahim\'in korkusu geçip,  bu müjde kendisine verilince,  Lut\'un halkı hakkında bizimle[1] tartışmaya başladı.[2]', 'فلما ذهب عن ابرهيم الروع وجاته البشري يجدلنا في قوم لوط'),
(1548, 11, 75, 'اِنَّ اِبْرٰه۪يمَ لَحَل۪يمٌ اَوَّاهٌ مُن۪يبٌ', 'İnne ibrahime le halimun evvahun munib.', 'Çünkü İbrahim,  çok yumuşak huylu,  yufka yürekli ve Allah\'a gönülden yönelen bir kimseydi.', 'ان ابرهيم لحليم اوه منيب'),
(1549, 11, 76, 'يَٓا اِبْرٰه۪يمُ اَعْرِضْ عَنْ هٰذَاۚ اِنَّهُ قَدْ جَٓاءَ اَمْرُ رَبِّكَۚ وَاِنَّهُمْ اٰت۪يهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', 'Ya ibrahimu a\'rid an haza, innehu kad cae emru rabbik, ve innehum atihim azabun gayru merdud.', '\"Ey İbrahim! Bundan vazgeç. Çünkü Rabb\'inin takdiri kesindir. Onlara gelecek azap engellenemez.\"', 'يابرهيم اعرض عن هذا انه قد جا امر ربك وانهم اتيهم عذاب غير مردود'),
(1550, 11, 77, 'وَلَمَّا جَٓاءَتْ رُسُلُنَا لُوطاً س۪ٓيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعاً وَقَالَ هٰذَا يَوْمٌ عَص۪يبٌ', 'Ve lemma caet resuluna lutan sie bihim ve daka bihim zer\'an ve kale haza yevmun asib.', 'Elçilerimiz Lut\'a vardıklarında,  onlar yüzünden fenalaştı. Onlara karşı eli ayağı birbirine dolaştı. \"Bu çok zorlu bir gün.\" dedi.', 'ولما جات رسلنا لوطا سي بهم وضاق بهم ذرعا وقال هذا يوم عصيب'),
(1551, 11, 78, 'وَجَٓاءَهُ قَوْمُهُ يُهْرَعُونَ اِلَيْهِ وَمِنْ قَبْلُ كَانُوا يَعْمَلُونَ السَّيِّـَٔاتِۜ قَالَ يَا قَوْمِ هٰٓؤُ۬لَٓاءِ بَنَات۪ي هُنَّ اَطْهَرُ لَكُمْ فَاتَّقُوا اللّٰهَ وَلَا تُخْزُونِ ف۪ي ضَيْف۪يۜ اَلَيْسَ مِنْكُمْ رَجُلٌ رَش۪يدٌ', 'Ve caehu kavmuhu yuhreune ileyhi ve min kablu kanu ya\'melunes seyyiat, kale ya kavmi haulai benati hunne etharu lekum, fettekullahe ve la tuhzuni fi dayfi, e leyse minkum raculun reşid.', 'Halkı koşa koşa ona geldiler. Onlar,  önceden de kötü işler yapıyorlardı. \"Ey halkım! İşte şunlar kızlarımdır[1],  onlar sizin için temiz olandır. Allah için takvalı olun,  misafirlerime karşı beni rezil etmeyin,  içinizde hiç aklı başında kimse yok mu?\" dedi.', 'وجاه قومه يهرعون اليه ومن قبل كانوا يعملون السيات قال يقوم هولا بناتي هن اطهر لكم فاتقوا الله ولا تخزون في ضيفي اليس منكم رجل رشيد'),
(1552, 11, 79, 'قَالُوا لَقَدْ عَلِمْتَ مَا لَنَا ف۪ي بَنَاتِكَ مِنْ حَقٍّۚ وَاِنَّكَ لَتَعْلَمُ مَا نُر۪يدُ', 'Kalu lekad alimte ma lena fi benatike min hakk, ve inneke le ta\'lemu ma nurid.', '\"Senin kızlarında bizim hakkımızın olmadığını biliyorsun. Ant olsun ki ne istediğimizi çok iyi biliyorsun.\" dediler.', 'قالوا لقد علمت ما لنا في بناتك من حق وانك لتعلم ما نريد'),
(1553, 11, 80, 'قَالَ لَوْ اَنَّ ل۪ي بِكُمْ قُوَّةً اَوْ اٰو۪ٓي اِلٰى رُكْنٍ شَد۪يدٍ', 'Kale lev enne li bikum kuvveten ev avi ila ruknin şedid.', '\"Keşke size karşı bir gücüm olsaydı veya sağlam bir kaleye sığınabilseydim.\" dedi.', 'قال لو ان لي بكم قوة او اوي الي ركن شديد'),
(1554, 11, 81, 'قَالُوا يَا لُوطُ اِنَّا رُسُلُ رَبِّكَ لَنْ يَصِلُٓوا اِلَيْكَ فَاَسْرِ بِاَهْلِكَ بِقِطْعٍ مِنَ الَّيْلِ وَلَا يَلْتَفِتْ مِنْكُمْ اَحَدٌ اِلَّا امْرَاَتَكَۜ اِنَّهُ مُص۪يبُهَا مَٓا اَصَابَهُمْۜ اِنَّ مَوْعِدَهُمُ الصُّبْحُۜ اَلَيْسَ الصُّبْحُ بِقَر۪يبٍ', 'Kalu ya lutu inna rusulu rabbike len yasilu ileyke fe esri bi ehlike bi kıt\'ın minel leyli ve la yeltefit minkum ehadun illemreetek, innehu musibuha ma esabehum, inne mev\'ıdehumus subh, e leyses subhu bi karib.', '\"Ey Lut! Biz,  Rabb\'inin elçileriyiz.\" dediler. \"Onlar,  sana dokunamazlar. Ailenle[1] birlikte gecenin bir bölümünde hemen yola çık. Hanımın hariç,  hiç kimse arkada kalmasın. Doğrusu onların başına gelecek olan musibet onun da başına gelecektir. Onlara belirlenen vakit sabahtır. Sabah da yakın değil mi?\"', 'قالوا يلوط انا رسل ربك لن يصلوا اليك فاسر باهلك بقطع من اليل ولا يلتفت منكم احد الا امراتك انه مصيبها ما اصابهم ان موعدهم الصبح اليس الصبح بقريب'),
(1555, 11, 82, 'فَلَمَّا جَٓاءَ اَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَاَمْطَرْنَا عَلَيْهَا حِجَارَةً مِنْ سِجّ۪يلٍۙ مَنْضُودٍۙ', 'Fe lemma cae emruna cealna aliyeha safileha ve emtarna aleyha hicareten min siccilin mendud.', 'Takdirimizle yaşadıkları yeri alt üst ettik. Üzerlerine pişmiş çamurdan yığınlarca taş yağdırdık.', 'فلما جا امرنا جعلنا عليها سافلها وامطرنا عليها حجارة من سجيل منضود'),
(1556, 11, 83, 'مُسَوَّمَةً عِنْدَ رَبِّكَۜ وَمَا هِيَ مِنَ الظَّالِم۪ينَ بِبَع۪يدٍ۟', 'Musevvemeten inde rabbik, ve ma hiye minez zalimine bi baid.', 'Bu taşlar,  Rabb\'inin katında işaretlenmiştir.[1] Bunlar,  zalimlerden uzak değildir.', 'مسومة عند ربك وما هي من الظلمين ببعيد'),
(1557, 11, 84, 'وَاِلٰى مَدْيَنَ اَخَاهُمْ شُعَيْباًۜ قَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ  وَلَا تَنْقُصُوا الْمِكْيَالَ وَالْم۪يزَانَ اِنّ۪ٓي اَرٰيكُمْ بِخَيْرٍ وَاِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُح۪يطٍ', 'Ve ila medyene ehahum şuayba, kale ya kavmi\'budullahe ma lekum min ilahin gayruh, ve la tenkusul mikyale vel mizane inni erakum bi hayrin ve inni ehafu aleykum azabe yevmin muhit.', 'Medyen halkına da kardeşleri Şuayb\'ı gönderdik. \"Ey halkım! Allah\'a kulluk edin. Sizin için O\'ndan başka ilah yoktur. Ölçüyü ve tartıyı eksik yapmayın. Ben,  sizi bir hayır[1] içinde görüyorum. Ve sizin için kuşatıcı bir günün azabından korkuyorum.\" dedi.', 'والي مدين اخاهم شعيبا قال يقوم اعبدوا الله ما لكم من اله غيره ولا تنقصوا المكيال والميزان اني اريكم بخير واني اخاف عليكم عذاب يوم محيط'),
(1558, 11, 85, 'وَيَا قَوْمِ اَوْفُوا الْمِكْيَالَ وَالْم۪يزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ اَشْيَٓاءَهُمْ وَلَا تَعْثَوْا فِي الْاَرْضِ مُفْسِد۪ينَ', 'Ve ya kavmi evful mikyale vel mizane bil kıstı ve la tebhasun nase eşyaehum ve la ta\'sev fil ardı mufsidin.', '\"Ey kavmim! Ölçüyü ve tartıyı hakkaniyetle yapın. Kimsenin malını eksik vermeyin. Bozguncular olarak yeryüzünde fesat çıkarmayın.', 'ويقوم اوفوا المكيال والميزان بالقسط ولا تبخسوا الناس اشياهم ولا تعثوا في الارض مفسدين'),
(1559, 11, 86, 'بَقِيَّتُ اللّٰهِ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَۚ وَمَٓا اَنَا۬ عَلَيْكُمْ بِحَف۪يظٍ', 'Bakıyyetullahi hayrun lekum in kuntum mu\'minin, ve ma ene aleykum bi hafiz.', 'Eğer mü\'minler iseniz,  Allah\'ın bıraktığı[1] sizin için hayırlı olandır. Yoksa ben,  gözetleyiciniz değilim.\"', 'بقيت الله خير لكم ان كنتم مومنين وما انا عليكم بحفيظ'),
(1560, 11, 87, 'قَالُوا يَا شُعَيْبُ اَصَلٰوتُكَ تَأْمُرُكَ اَنْ نَتْرُكَ مَا يَعْبُدُ اٰبَٓاؤُ۬نَٓا اَوْ اَنْ نَفْعَلَ ف۪ٓي اَمْوَالِنَا مَا نَشٰٓؤُ۬اۜ اِنَّكَ لَاَنْتَ الْحَل۪يمُ الرَّش۪يدُ', 'Kalu ya şuaybu e salatuke te\'muruke en netruke ma ya\'budu abauna ev en nef\'ale fi emvalina ma neşa\', inneke le entel halimur reşid.', 'Dediler ki: \"Ey Şu\'ayb! Atalarımızın kulluk ettiklerini bırakmamızı; mallarımızı,  istediğimiz gibi kullanmaktan vazgeçmemizi senin salatın[1] mı buyuruyor? Oysaki sen yumuşak huylu,  aklı başında bir adamsın.\"', 'قالوا يشعيب اصلوتك تامرك ان نترك ما يعبد اباونا او ان نفعل في امولنا ما نشوا انك لانت الحليم الرشيد'),
(1561, 11, 88, 'قَالَ يَا قَوْمِ اَرَاَيْتُمْ اِنْ كُنْتُ عَلٰى بَيِّنَةٍ مِنْ رَبّ۪ي وَرَزَقَن۪ي مِنْهُ رِزْقاً حَسَناًۜ وَمَٓا اُر۪يدُ اَنْ اُخَالِفَكُمْ اِلٰى مَٓا اَنْهٰيكُمْ عَنْهُۜ اِنْ اُر۪يدُ اِلَّا الْاِصْلَاحَ مَا اسْتَطَعْتُۜ وَمَا تَوْف۪يق۪ٓي اِلَّا بِاللّٰهِۜ  عَلَيْهِ تَوَكَّلْتُ وَاِلَيْهِ اُن۪يبُ', 'Kale ya kavmi e reeytum in kuntu ala beyyinetin min rabbi ve rezekani minhu rızkan hasena, ve ma uridu en uhalifekum ila ma enhakum anh, in uridu illel ıslaha mesteta\'tu, ve ma tevfiki illa billah, aleyhi tevekkeltu ve ileyhi unib.', '\"Ey halkım! Bana söyleyin! \"Ya ben Rabb\'imden kanıt içeren apaçık bir bilgiye sahipsem; kendinden bana iyi bir rızık vermişse! Vazgeçmenizi istediğim şeyleri,  kendim yapmak istemiyorum. Sadece gücümün yettiği kadarıyla düzeltmek istiyorum. Başarım ancak Allah\'tandır. Yalnız O\'na tevekkül[1] ettim ve yalnız O\'na yöneldim.\" dedi.', 'قال يقوم اريتم ان كنت علي بينة من ربي ورزقني منه رزقا حسنا وما اريد ان اخالفكم الي ما انهيكم عنه ان اريد الا الاصلح ما استطعت وما توفيقي الا بالله عليه توكلت واليه انيب'),
(1562, 11, 89, 'وَيَا قَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاق۪ٓي اَنْ يُص۪يبَكُمْ مِثْلُ مَٓا اَصَابَ قَوْمَ نُوحٍ اَوْ قَوْمَ هُودٍ اَوْ قَوْمَ صَالِحٍۜ وَمَا قَوْمُ لُوطٍ مِنْكُمْ بِبَع۪يدٍ', 'Ve ya kavmi la yecrimennekum şikaki en yusibekum mislu ma esabe kavme nuhin ev kavme hudin ev kavme salih, ve ma kavmu lutin minkum bi baid.', '\"Ey halkım! Bana karşı gelmeniz; Nuh halkının,  Hud halkının,  Salih halkının başına gelen şeyleri sizin başınıza da getirmesin? Üstelik Lut halkı sizden pek uzak da değil.\"', 'ويقوم لا يجرمنكم شقاقي ان يصيبكم مثل ما اصاب قوم نوح او قوم هود او قوم صلح وما قوم لوط منكم ببعيد'),
(1563, 11, 90, 'وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُٓوا اِلَيْهِۜ اِنَّ رَبّ۪ي رَح۪يمٌ وَدُودٌ', 'Vestagfiru rabbekum summe tubu ileyh, inne rabbi rahimun vedud.', 'Rabb\'inizden bağışlanma dileyin. Sonra O\'na tevbe[1] edin! Rabb\'imin,  Rahmeti Kesintisiz\'dir,  Çok Seven\'dir.', 'واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود'),
(1564, 11, 91, 'قَالُوا يَا شُعَيْبُ مَا نَفْقَهُ۬ كَث۪يراً مِمَّا تَقُولُ وَاِنَّا لَنَرٰيكَ ف۪ينَا ضَع۪يفاًۚ وَلَوْلَا رَهْطُكَ لَرَجَمْنَاكَۘ وَمَٓا اَنْتَ عَلَيْنَا بِعَز۪يزٍ', 'Kalu ya Şuaybu ma nefkahu kesiren mimma tekulu ve inna le nerake fina daifa, ve lev la rehtuke le recemnake ve ma ente aleyna bi aziz.', '\"Ey Şu\'ayb! Dediklerinin çoğunu anlamıyoruz,  biz,  seni içimizde güçsüz görüyoruz. Kabilen olmasaydı seni taşlardık. Esasen sen değerli biri de değilsin.\" dediler.', 'قالوا يشعيب ما نفقه كثيرا مما تقول وانا لنريك فينا ضعيفا ولولا رهطك لرجمنك وما انت علينا بعزيز'),
(1565, 11, 92, 'قَالَ يَا قَوْمِ اَرَهْط۪ٓي اَعَزُّ عَلَيْكُمْ مِنَ اللّٰهِۜ وَاتَّخَذْتُمُوهُ وَرَٓاءَكُمْ ظِهْرِياًّۜ اِنَّ رَبّ۪ي بِمَا تَعْمَلُونَ مُح۪يطٌ', 'Kale ya kavmi e rahti eazzu aleykum minallah, vettehaztumuhu veraekum zıhriyya, inne rabbi bi ma ta\'melune muhit.', '\"Ey halkım! Size göre kabilem Allah\'tan daha mı değerli ki O\'na sırt çevirdiniz. Kuşkusuz Rabb\'im yaptıklarınızı kuşatmıştır.\"', 'قال يقوم ارهطي اعز عليكم من الله واتخذتموه وراكم ظهريا ان ربي بما تعملون محيط'),
(1566, 11, 93, 'وَيَا قَوْمِ اعْمَلُوا عَلٰى مَكَانَتِكُمْ اِنّ۪ي عَامِلٌۜ سَوْفَ تَعْلَمُونَۙ مَنْ يَأْت۪يهِ عَذَابٌ يُخْز۪يهِ وَمَنْ هُوَ كَاذِبٌۜ وَارْتَقِبُٓوا اِنّ۪ي مَعَكُمْ رَق۪يبٌ', 'Ve ya kavmi\'melu ala mekanetikum inni amil, sevfe ta\'lemune men ye\'tihi azabun yuhzihi ve men huve kazib, vertekibu inni meakum rakib.', '\"Ey halkım! Elinizden geleni yapın. Doğrusu ben de yapacağım. Yakında bileceksiniz,  alçaltıcı azabın kime geleceğini ve kimin yalancı olduğunu. Gözetleyin,  doğrusu ben de sizinle birlikte gözetliyorum.\"', 'ويقوم اعملوا علي مكانتكم اني عمل سوف تعلمون من ياتيه عذاب يخزيه ومن هو كذب وارتقبوا اني معكم رقيب'),
(1567, 11, 94, 'وَلَمَّا جَٓاءَ اَمْرُنَا نَجَّيْنَا شُعَيْباً وَالَّذ۪ينَ اٰمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَاَخَذَتِ الَّذ۪ينَ ظَلَمُوا الصَّيْحَةُ فَاَصْبَحُوا ف۪ي دِيَارِهِمْ جَاثِم۪ينَۙ', 'Ve lemma cae emruna necceyna ?uayben vellezine amenu meahu bi rahmetin minna ve ehazetillezine zalemussayhatu fe asbahu fi diyarihim casimin.', 'Hükmümüz gerçekleşince Şu\'ayb\'ı ve onunla birlikte iman etmiş olanları,  Tarafımızdan bir rahmetle kurtardık. Zulmedenleri de dehşete düşürücü bir ses yakaladı. Yurtlarında dizüstü çökmüş olarak sabahladılar.', 'ولما جا امرنا نجينا شعيبا والذين امنوا معه برحمة منا واخذت الذين ظلموا الصيحة فاصبحوا في ديرهم جثمين'),
(1568, 11, 95, 'كَاَنْ لَمْ يَغْنَوْا ف۪يهَاۜ اَلَا بُعْداً لِمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ۟', 'Ke\'en lem yagnev fiha, e la bu\'den li medyene kema baıdet semud.', 'Sanki orada hiç yaşamamışlardı. Tıpkı Semud gibi,  Medyen de yok olup gitti.', 'كان لم يغنوا فيها الا بعدا لمدين كما بعدت ثمود'),
(1569, 11, 96, 'وَلَقَدْ اَرْسَلْنَا مُوسٰى بِاٰيَاتِنَا وَسُلْطَانٍ مُب۪ينٍۙ', 'Ve le kad erselna musa bi ayatina ve sultanin mubin.', 'Ant olsun Musa\'yı ayetlerimizle ve apaçık bir yetkiyle gönderdik;', 'ولقد ارسلنا موسي بايتنا وسلطن مبين'),
(1570, 11, 97, 'اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ فَاتَّـبَعُٓوا اَمْرَ فِرْعَوْنَۚ وَمَٓا اَمْرُ فِرْعَوْنَ بِرَش۪يدٍ', 'İla fir\'avne ve melaihi fettebeu emre fir\'avn, ve ma emru fir\'avne bi reşid.', 'Firavun ve melelerine.[1] Firavun\'un buyruklarına uydular. Oysa Firavun\'un buyrukları hiç de akıllıca değildi;', 'الي فرعون وملايه فاتبعوا امر فرعون وما امر فرعون برشيد'),
(1571, 11, 98, 'يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيٰمَةِ فَاَوْرَدَهُمُ النَّارَۜ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ', 'Yakdumu kavmehu yevmel kıyameti fe evredehumun nar, ve bi\'sel virdul mevrud.', 'Kıyamet günü,  halkının önüne düşecek ve onları ateşe götürecektir. Varacakları yer,  ne kötü bir yerdir.', 'يقدم قومه يوم القيمة فاوردهم النار وبيس الورد المورود'),
(1572, 11, 99, 'وَاُتْبِعُوا ف۪ي هٰذِه۪ لَعْنَةً وَيَوْمَ الْقِيٰمَةِۜ بِئْسَ الرِّفْدُ الْمَرْفُودُ', 'Ve utbiu fi hazihi la\'neten ve yevmel kıyameh, bi\'ser rifdul merfud.', 'Bu dünyada da Kıyamet Günü\'nde de lanete[1] uğratıldılar. Paylarına düşen ne kötü bir paydır.', 'واتبعوا في هذه لعنة ويوم القيمة بيس الرفد المرفود'),
(1573, 11, 100, 'ذٰلِكَ مِنْ اَنْـبَٓاءِ الْقُرٰى نَقُصُّهُ عَلَيْكَ مِنْهَا قَٓائِمٌ وَحَص۪يدٌ', 'Zalike min enbail kura nekussuhu aleyke minha kaimun ve hasid.', 'Bunlar,  o kentlere ait sana bildirdiğimiz haberlerdir. O kentlerden,  yerinde duran da var,  biçilmiş ekin gibi olan da.', 'ذلك من انبا القري نقصه عليك منها قايم وحصيد'),
(1574, 11, 101, 'وَمَا ظَلَمْنَاهُمْ وَلٰكِنْ ظَلَمُٓوا اَنْفُسَهُمْ فَـمَٓا اَغْنَتْ عَنْهُمْ اٰلِهَتُهُمُ الَّت۪ي يَدْعُونَ مِنْ دُونِ اللّٰهِ مِنْ شَيْءٍ لَمَّا جَٓاءَ اَمْرُ رَبِّكَۜ وَمَا زَادُوهُمْ غَيْرَ تَتْب۪يبٍ', 'Ve ma zalemnahum ve lakin zalemu enfusehum fe ma agnet anhum alihetuhumulleti yed\'une min dunillahi min şey\'in lemma cae emru rabbik, ve ma zaduhum gayre tetbib.', 'Biz onlara haksızlık yapmadık; onlar kendi kendilerine haksızlık yaptılar. Rabb\'inin buyruğu gerçekleşince,  Allah\'ı bırakıp da kulluk[1] ettikleri ilahları kendilerine hiçbir yarar sağlamadı. Yalnızca kayıplarını artırdılar.', 'وما ظلمنهم ولكن ظلموا انفسهم فما اغنت عنهم الهتهم التي يدعون من دون الله من شي لما جا امر ربك وما زادوهم غير تتبيب'),
(1575, 11, 102, 'وَكَذٰلِكَ اَخْذُ رَبِّكَ اِذَٓا اَخَذَ الْقُرٰى وَهِيَ ظَالِمَةٌۜ اِنَّ اَخْذَهُٓ اَل۪يمٌ شَد۪يدٌ', 'Ve kezalike ahzu rabbike iza ehazel kura ve hiye zalimeh, inne ahzehu elimun şedid.', 'İşte Rabb\'in,  zulmeden kentleri cezalandırdığı zaman,  böyle cezalandırır. O\'nun cezası çok acı verici ve çok şiddetlidir.', 'وكذلك اخذ ربك اذا اخذ القري وهي ظلمة ان اخذه اليم شديد'),
(1576, 11, 103, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِمَنْ خَافَ عَذَابَ الْاٰخِرَةِۜ ذٰلِكَ يَوْمٌ مَجْمُوعٌۙ لَهُ النَّاسُ وَذٰلِكَ يَوْمٌ مَشْهُودٌ', 'İnne fi zalike le ayeten li men hafe azabel ahıreh, zalike yevmun mecmuun lehun nasu ve zalike yevmun meşhud.', 'Ahiret azabından korkanlar için,  bunda bir ayet[1] vardır. O gün,  bütün insanların toplanacağı gündür. O mutlaka görülecek bir gündür.', 'ان في ذلك لاية لمن خاف عذاب الاخرة ذلك يوم مجموع له الناس وذلك يوم مشهود'),
(1577, 11, 104, 'وَمَا نُؤَخِّرُهُٓ اِلَّا لِاَجَلٍ مَعْدُودٍۜ', 'Ve ma nuahhıruhu illa li ecelin ma\'dud.', 'Onu geciktirmemiz belli bir süreye kadardır.', 'وما نوخره الا لاجل معدود'),
(1578, 11, 105, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ اِلَّا بِـاِذْنِه۪ۚ فَمِنْهُمْ شَقِيٌّ وَسَع۪يدٌ', 'Yevme ye\'ti la tekellemu nefsun illa bi iznih, fe minhum şakıyyun ve said.', 'O gün gelince,  O\'nun izni olmadan hiç kimse konuşamaz. Onlardan kimi mutsuz,  kimi de mutludur.', 'يوم يات لا تكلم نفس الا باذنه فمنهم شقي وسعيد'),
(1579, 11, 106, 'فَاَمَّا الَّذ۪ينَ شَقُوا فَفِي النَّارِ لَهُمْ ف۪يهَا زَف۪يرٌ وَشَه۪يقٌۙ', 'Fe emmellezine şeku fe fin nari lehum fiha zefirun ve şehik.', 'Mutsuz olanlar ateştedir. Onlar,  orada hıçkırırlar,  inleyip dururlar.', 'فاما الذين شقوا ففي النار لهم فيها زفير وشهيق'),
(1580, 11, 107, 'خَالِد۪ينَ ف۪يهَا مَا دَامَتِ السَّمٰوَاتُ وَالْاَرْضُ اِلَّا مَا شَٓاءَ رَبُّكَۜ اِنَّ رَبَّكَ فَعَّالٌ لِمَا يُر۪يدُ', 'Halidine fiha ma dametis semavatu vel\'ardu illa ma şae rabbuk, inne rabbeke fe\'alun lima yurid.', 'Rabb\'in,  aksini dilemedikçe[1],  gökler ve yer durdukça[2],  orada sürekli kalacaklardır. Kuşkusuz Rabb\'in,  dilediğini yapandır.', 'خلدين فيها ما دامت السموت والارض الا ما شا ربك ان ربك فعال لما يريد');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1581, 11, 108, 'وَاَمَّا الَّذ۪ينَ سُعِدُوا فَفِي الْجَنَّةِ خَالِد۪ينَ ف۪يهَا مَا دَامَتِ السَّمٰوَاتُ وَالْاَرْضُ اِلَّا مَا شَٓاءَ رَبُّكَۜ عَطَٓاءً غَيْرَ مَجْذُوذٍ', 'Ve emmellezine suidu fe fil cenneti halidine fiha ma dametis semavatu vel ardu illa ma şae rabbuk, ataen gayre meczuz.', 'Mutlu olanlar ise,  Cennet\'tedirler. Rabb\'in aksini dilemedikçe,  gökler ve yer durdukça,  orada sürekli kalacaklardır. Bu kesintisiz bir iyiliktir.', 'واما الذين سعدوا ففي الجنة خلدين فيها ما دامت السموت والارض الا ما شا ربك عطا غير مجذوذ'),
(1582, 11, 109, 'فَلَا تَكُ ف۪ي مِرْيَةٍ مِمَّا يَعْبُدُ هٰٓؤُ۬لَٓاءِۜ مَا يَعْبُدُونَ اِلَّا كَمَا يَعْبُدُ اٰبَٓاؤُ۬هُمْ مِنْ قَبْلُۜ وَاِنَّا لَمُوَفُّوهُمْ نَص۪يبَهُمْ غَيْرَ مَنْقُوصٍ۟', 'Fe la teku fi miryetin mimma ya\'budu haula\', ma ya\'budune illa kema ya\'budu abauhum min kabl, ve inna le muveffuhum nasibehum gayre menkus.', 'Onların kulluk[1] ettikleri hakkında[2] hiç kuşkun olmasın. Daha önce atalarının kulluk ettikleri gibi kulluk ediyorlar. Elbette paylarına düşeni eksiksiz olarak vereceğiz.', 'فلا تك في مرية مما يعبد هولا ما يعبدون الا كما يعبد اباوهم من قبل وانا لموفوهم نصيبهم غير منقوص'),
(1583, 11, 110, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ ف۪يهِۜ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْۜ وَاِنَّهُمْ لَف۪ي شَكٍّ مِنْهُ مُر۪يبٍ', 'Ve lekad ateyna musel kitabe fahtulife fih, ve lev la kelimetun sebekat min rabbike le kudiye beynehum, ve innehum le fi şekkin minhu murib.', 'Ant olsun! Musa\'ya Kitap\'ı verdik de onda anlaşmazlığa düştüler. Rabb\'in tarafından önceden takdir edilmiş bir karar olmasaydı,  aralarında hemen hüküm verilirdi. Onlar[1] da bunun hakkında ikilem ve güvensizlik içindedirler.[2]', 'ولقد اتينا موسي الكتب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب'),
(1584, 11, 111, 'وَاِنَّ كُلاًّ لَمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ اَعْمَالَهُمْۜ اِنَّهُ بِمَا يَعْمَلُونَ خَب۪يرٌ', 'Ve inne kullen lemma le yuveffiyennehum rabbuke a\'malehum, innehu bima ya\'melune habir.', 'Rabb\'in onların yaptığı her şeyin karşılığını tam olarak verecektir. O,  onların yaptıklarından haberdardır.', 'وان كلا لما ليوفينهم ربك اعملهم انه بما يعملون خبير'),
(1585, 11, 112, 'فَاسْتَقِمْ كَمَٓا اُمِرْتَ وَمَنْ تَابَ مَعَكَ وَلَا تَطْغَوْاۜ اِنَّهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Festekim kema umirte ve men tabe meake ve la tatgav, innehu bi ma ta\'melune basir.', 'Sen ve tevbe edip[1] seninle birlikte olanlar,  emrolunduğunuz gibi dosdoğru olun. Aşırı gitmeyin.[2] O,  yaptığınız her şeyi görmektedir.', 'فاستقم كما امرت ومن تاب معك ولا تطغوا انه بما تعملون بصير'),
(1586, 11, 113, 'وَلَا تَرْكَـنُٓوا اِلَى الَّذ۪ينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُۙ وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ اَوْلِيَٓاءَ ثُمَّ لَا تُنْصَرُونَ', 'Ve la terkenu ilellezine zalemu fe temessekumun naru ve ma lekum min dunillahi min evliyae summe la tunsarun.', 'Zulmedenlere eğilim göstermeyin. Sonra size de ateş dokunur. Allah\'ın yanı sıra başka evliyanız[1] da yoktur. Sonra yardım da göremezsiniz.', 'ولا تركنوا الي الذين ظلموا فتمسكم النار وما لكم من دون الله من اوليا ثم لا تنصرون'),
(1587, 11, 114, 'وَاَقِمِ الصَّلٰوةَ طَرَفَيِ النَّهَارِ وَزُلَفاً مِنَ الَّيْلِۜ اِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّـَٔاتِۜ ذٰلِكَ ذِكْرٰى لِلذَّاكِر۪ينَۚ', 'Ve ekımis salate tarafeyin nehari ve zulefen minel leyl, innel hasenati yuzhibnes seyyiat, zalike zikra liz zakirin.', 'Gündüzün iki tarafında[1] ve gecenin yakınlarında[2] salatı ikame et[3]. Çünkü iyilikler kötülükleri giderir. Bu,  öğüt alanlar için bir öğüttür.', 'واقم الصلوة طرفي النهار وزلفا من اليل ان الحسنت يذهبن السيات ذلك ذكري للذكرين'),
(1588, 11, 115, 'وَاصْبِرْ فَاِنَّ اللّٰهَ لَا يُض۪يعُ اَجْرَ الْمُحْسِن۪ينَ', 'Vasbir fe innallahe la yudiu ecrel muhsinin.', 'Sabret! Kuşkusuz Allah,  iyilerin iyiliklerini asla karşılıksız bırakmaz.', 'واصبر فان الله لا يضيع اجر المحسنين'),
(1589, 11, 116, 'فَلَوْلَا كَانَ مِنَ الْقُرُونِ مِنْ قَبْلِكُمْ اُو۬لُوا بَقِيَّةٍ يَنْهَوْنَ عَنِ الْفَسَادِ فِي الْاَرْضِ اِلَّا قَل۪يلاً مِمَّنْ اَنْجَيْنَا مِنْهُمْۚ  وَاتَّبَعَ الَّذ۪ينَ ظَلَمُوا مَٓا اُتْرِفُوا ف۪يهِ وَكَانُوا مُجْرِم۪ينَ', 'Fe lev la kane minel kuruni min kablikum ulu bakıyyetin yenhevne anil fesadi fil ardı illa kalilen mimmen enceyna minhum, vettebeallezine zalemu ma utrifu fihi ve kanu mucrimin.', 'Keşke sizden önceki nesillerde yeryüzünde fesatlığa karşı çıkan faziletli kimseler olmuş olsaydı. Onlardan ancak çok azını kurtuluşa erdirdik. Zulmedenler ise içinde bulundukları refaha dalıp böylece mücrim[1] kimseler oldular.', 'فلولا كان من القرون من قبلكم اولوا بقية ينهون عن الفساد في الارض الا قليلا ممن انجينا منهم واتبع الذين ظلموا ما اترفوا فيه وكانوا مجرمين'),
(1590, 11, 117, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرٰى بِظُلْمٍ وَاَهْلُهَا مُصْلِحُونَ', 'Ve ma kane rabbuke li yuhlikel kura bi zulmin ve ehluha muslihun.', 'Yoksa senin Rabb\'in,  o memleketleri,  halkı düzelticiler oldukları halde,  haksızlıkla yok edecek değildi!', 'وما كان ربك ليهلك القري بظلم واهلها مصلحون'),
(1591, 11, 118, 'وَلَوْ شَٓاءَ رَبُّكَ لَجَعَلَ النَّاسَ اُمَّةً وَاحِدَةً وَلَا يَزَالُونَ مُخْتَلِف۪ينَۙ', 'Ve lev şae rabbuke le cealen nase ummeten vahideten ve la yezalune muhtelifin.', 'Rabb\'in dileseydi[1],  bütün insanları tek bir ümmet yapardı. İhtilaf edenler[2] olarak sürüp gitmezlerdi.', 'ولو شا ربك لجعل الناس امة وحدة ولا يزالون مختلفين'),
(1592, 11, 119, 'اِلَّا مَنْ رَحِمَ رَبُّكَۜ وَلِذٰلِكَ خَلَقَهُمْۜ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَاَمْلَـَٔنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ اَجْمَع۪ينَ', 'İlla men rahime rabbuk, ve li zalike halakahum, ve temmet kelimetu rabbike le emleenne cehenneme minel cinneti ven nasi ecmain.', 'Ancak Rabb\'inin rahmet ettikleri hariç.[1] Bunun için yarattı onları.[2] Kesinlikle Rabb\'inin takdir ettiği,  \"Cehennem\'i cinlerden ve insanlardan[3] dolduracağım\" hükmü gerçekleşecektir.[4]', 'الا من رحم ربك ولذلك خلقهم وتمت كلمة ربك لاملان جهنم من الجنة والناس اجمعين'),
(1593, 11, 120, 'وَكُلاًّ نَقُصُّ عَلَيْكَ مِنْ اَنْبَٓاءِ الرُّسُلِ مَا نُثَبِّتُ بِه۪ فُؤٰادَكَۚ وَجَٓاءَكَ ف۪ي هٰذِهِ الْحَقُّ وَمَوْعِظَةٌ وَذِكْرٰى لِلْمُؤْمِن۪ينَ', 'Ve kullen nakussu aleyke min enbair rusuli ma nusebbitu bihi fuadek ve caeke fi hazihil hakku ve mev\'ızatun ve zikra lil muminin.', 'Elçilerin haberlerinden,  kalbini kuvvetlendirecek her şeyi sana anlatıyoruz. Bu hususta sana Hakk,  müminlere de öğüt ve hatırlatma geldi.', 'وكلا نقص عليك من انبا الرسل ما نثبت به فوادك وجاك في هذه الحق وموعظة وذكري للمومنين'),
(1594, 11, 121, 'وَقُلْ لِلَّذ۪ينَ لَا يُؤْمِنُونَ اعْمَلُوا عَلٰى مَكَانَتِكُمْۜ اِنَّا عَامِلُونَۙ', 'Ve kul lillezine la yu\'minuna\'melu ala mekanetikum, inna amilun.', 'İnanmayanlara de ki: \"Elinizden ne geliyorsa yapın. Biz de yapmaktayız.\"', 'وقل للذين لا يومنون اعملوا علي مكانتكم انا عملون'),
(1595, 11, 122, 'وَانْتَظِرُواۚ اِنَّا مُنْتَظِرُونَ', 'Ventazır, inna muntazırun.', '\"Bekleyin! Biz de bekliyoruz.\"', 'وانتظروا انا منتظرون'),
(1596, 11, 123, 'وَلِلّٰهِ غَيْبُ السَّمٰوَاتِ وَالْاَرْضِ وَاِلَيْهِ يُرْجَعُ الْاَمْرُ كُلُّهُ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِۜ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Ve lillahi gaybus semavati vel ardı ve ileyhi yurceul emru kulluhu fa\'budhu ve tevekkel aleyh, ve ma rabbuke bi gafilin amma ta\'melun.', 'Göklerin ve yerin gaybı Allah\'a aittir. Bütün işler O\'na döndürülür. Öyleyse yalnızca O\'na kulluk et ve yalnızca O\'na tevekkül et. Rabb\'in,  yaptıklarınızdan habersiz değildir.', 'ولله غيب السموت والارض واليه يرجع الامر كله فاعبده وتوكل عليه وما ربك بغفل عما تعملون'),
(1597, 12, 1, 'الٓـرٰ۠ تِلْكَ اٰيَاتُ الْـكِتَابِ الْمُب۪ينِ۠', 'Elif lam ra tilke ayatul kitabil mubin.', 'Elif. Lam. Ra. Bunlar açık ve anlaşılır Kitap\'ın ayetleridir.', 'الر تلك ايت الكتب المبين'),
(1598, 12, 2, 'اِنَّٓا اَنْزَلْنَاهُ قُرْءٰناً عَرَبِياًّ لَعَلَّـكُمْ تَعْقِلُونَ', 'İnna enzelnahu kur\'anen arabiyyen le allekum ta\'kılun.', 'Akledip anlamanız için onu Arapça bir kuran[1] olarak gönderdik.', 'انا انزلنه قرنا عربيا لعلكم تعقلون'),
(1599, 12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ اَحْسَنَ الْقَصَصِ بِمَٓا اَوْحَيْنَٓا اِلَيْكَ هٰذَا الْقُرْاٰنَۗ وَاِنْ كُنْتَ مِنْ قَبْلِه۪ لَمِنَ الْغَافِل۪ينَ', 'Nahnu nakussu aleyke ahsenel kasası bima evhayna ileyke hazel kur\'ane ve in kunte min kablihi le minel gafilin.', 'Biz,  Sana bu Kur\'an\'ı iletmekle,  daha önce hakkında bilgi sahibi olmadığın kıssaları en doğru şekilde bildirmiş oluyoruz.', 'نحن نقص عليك احسن القصص بما اوحينا اليك هذا القران وان كنت من قبله لمن الغفلين'),
(1600, 12, 4, 'اِذْ قَالَ يُوسُفُ لِاَب۪يهِ يَٓا اَبَتِ اِنّ۪ي رَاَيْتُ اَحَدَ عَشَرَ كَوْكَباً وَالشَّمْسَ وَالْقَمَرَ رَاَيْتُهُمْ ل۪ي سَاجِد۪ينَ', 'İz kale yusufu li ebihi ya ebeti inni re eytu ehade aşere kevkeben veş şemse vel kamere re eytuhum li sacidin.', 'Hani bir zamanlar Yusuf,  babasına: \"Ey babacığım! Ben[1] on bir yıldızla,  Güneş\'in ve Ay\'ın bana secde[2] ettiklerini gördüm.\" demişti.', 'اذ قال يوسف لابيه يابت اني رايت احد عشر كوكبا والشمس والقمر رايتهم لي سجدين'),
(1601, 12, 5, 'قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُءْيَاكَ عَلٰٓى اِخْوَتِكَ فَيَك۪يدُوا لَكَ كَيْداًۜ اِنَّ الشَّيْطَانَ لِلْاِنْسَانِ عَدُوٌّ مُب۪ينٌ', 'Kale ya buneyye la taksus ru\'yake ala ihvetike fe yekidu leke keyda, inneş şeytane lil insani aduvvun mubin.', 'Dedi ki: \"Ey yavrum! Rüyanı kardeşlerine anlatma; sonra sana tuzak kurarlar. Şeytan[1],  insanın açık bir düşmanıdır.\"', 'قال يبني لا تقصص رياك علي اخوتك فيكيدوا لك كيدا ان الشيطن للانسن عدو مبين'),
(1602, 12, 6, 'وَكَذٰلِكَ يَجْتَب۪يكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْو۪يلِ الْاَحَاد۪يثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلٰٓى اٰلِ يَعْقُوبَ كَمَٓا اَتَمَّهَا عَلٰٓى اَبَوَيْكَ مِنْ قَبْلُ اِبْرٰه۪يمَ وَاِسْحٰقَۜ اِنَّ رَبَّكَ عَل۪يمٌ حَك۪يمٌ۟', 'Ve kezalike yectebike rabbuke ve yu allimuke min te\'vilil ehadisi, ve yutimmu ni\'metehu aleyke ve ala ali ya\'kube kema etemmeha ala ebeveyke min kablu ibrahime ve ishak, inne rabbeke alimun hakim.', 'Böylece Rabb\'in seni seçecek ve sana olayların yorumlanmasının bilgisini verecek. Tıpkı daha önce ataların İbrahim ve İshak\'a nimetlerini tamamladığı gibi sana ve Yakub soyuna da tamamlayacaktır. Rabb\'in Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث ويتم نعمته عليك وعلي ال يعقوب كما اتمها علي ابويك من قبل ابرهيم واسحق ان ربك عليم حكيم'),
(1603, 12, 7, 'لَقَدْ كَانَ ف۪ي يُوسُفَ وَاِخْوَتِه۪ٓ اٰيَاتٌ لِلسَّٓائِل۪ينَ', 'Le kad kane fi yusufe ve ihvetihi ayatun lis sailin.', 'Doğrusu,  Yusuf ve kardeşlerinin olayında ders almak isteyenler için nice ayetler[1] vardır.', 'لقد كان في يوسف واخوته ايت للسايلين'),
(1604, 12, 8, 'اِذْ قَالُوا لَيُوسُفُ وَاَخُوهُ اَحَبُّ اِلٰٓى اَب۪ينَا مِنَّا وَنَحْنُ عُصْبَةٌۜ اِنَّ اَبَانَا لَف۪ي ضَلَالٍ مُب۪ينٍۚ', 'İz kalu le yusufu ve ehuhu ehabbu ila ebina minna ve nahnu usbeh, inne ebana le fi dalalin mubin.', 'Hani: \"Çok sayıda kardeş olduğumuz halde,  babamız,  Yusuf ve kardeşini[1] bizden daha çok seviyor. Doğrusu babamız apaçık bir yanılgı içindedir.\" demişlerdi.', 'اذ قالوا ليوسف واخوه احب الي ابينا منا ونحن عصبة ان ابانا لفي ضلل مبين'),
(1605, 12, 9, 'اُقْتُلُوا يُوسُفَ اَوِ اطْرَحُوهُ اَرْضاً يَخْلُ لَكُمْ وَجْهُ اَب۪يكُمْ وَتَكُونُوا مِنْ بَعْدِه۪ قَوْماً صَالِح۪ينَ', 'Uktulu yusufe evitrahuhu ardan yahlu lekum vechu ebikum ve tekunu min ba\'dihi kavmen salihin.', 'Yusuf\'u öldürün veya onu bilinmez bir yere atın ki babanızın ilgisi yalnızca size yönelsin. Ve bunun ardından iyi bir topluluk olursunuz.', 'اقتلوا يوسف او اطرحوه ارضا يخل لكم وجه ابيكم وتكونوا من بعده قوما صلحين'),
(1606, 12, 10, 'قَالَ قَٓائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَاَلْقُوهُ ف۪ي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ اِنْ كُنْتُمْ فَاعِل۪ينَ', 'Kale kailun minhum la taktulu yusufe ve elkuhu fi gayabetil cubbi yel-tekithu ba\'dus seyyareti in kuntum failin.', 'İçlerinden,  sözü geçerli olanı: \"Yusuf\'u öldürmeyin,  eğer bir şey yapacaksanız onu bir kuyunun dibine bırakın,  kervanlardan biri onu alsın.\"', 'قال قايل منهم لا تقتلوا يوسف والقوه في غيبت الجب يلتقطه بعض السيارة ان كنتم فعلين'),
(1607, 12, 11, 'قَالُوا يَٓا اَبَانَا مَا لَكَ لَا تَأْمَنَّۭۖا عَلٰى يُوسُفَ وَاِنَّا لَهُ لَنَاصِحُونَ', 'Kalu ya ebana ma leke la te\'menna ala yusufe ve inna lehu lenasıhun.', '\"Ey babamız! Yusuf hakkında neden bize güvenmiyorsun? Oysaki biz onun iyiliğini isteyenleriz.\" dediler.', 'قالوا يابانا ما لك لا تامنا علي يوسف وانا له لنصحون'),
(1608, 12, 12, 'اَرْسِلْهُ مَعَنَا غَداً يَرْتَعْ وَيَلْعَبْ وَاِنَّا لَهُ لَحَافِظُونَ', 'Ersilhu ma ana gaden yerta\' ve yel\'ab ve inna lehu lehafizun.', '\"Onu,  yarın bizimle beraber gönder. Dilediğince gezip eğlensin. Biz ona sahip çıkarız.\"', 'ارسله معنا غدا يرتع ويلعب وانا له لحفظون'),
(1609, 12, 13, 'قَالَ اِنّ۪ي لَيَحْزُنُن۪ٓي اَنْ تَذْهَبُوا بِه۪ وَاَخَافُ اَنْ يَأْكُلَهُ الذِّئْبُ وَاَنْتُمْ عَنْهُ غَافِلُونَ', 'Kale inni le yahzununi en tezhebu bihi ve ehafu en ye\'kulehuz zi\'bu ve entum anhu gafilun.', '\"Onu götürmeniz beni tasalandırır.\" dedi. \"Sizin ondan habersiz olduğunuz bir sırada kurdun onu yemesinden korkarım.\"', 'قال اني ليحزنني ان تذهبوا به واخاف ان ياكله الذيب وانتم عنه غفلون'),
(1610, 12, 14, 'قَالُوا لَئِنْ اَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ اِنَّٓا اِذاً لَخَاسِرُونَ', 'Kalu le in ekelehuz zi\'bu ve nahnu usbetun inna izen lehasirun.', '\"Ant olsun ki,  biz bu kadar kişiyken yine de kurt onu yerse,  o takdirde bize yazıklar olsun.\" dediler.', 'قالوا لين اكله الذيب ونحن عصبة انا اذا لخسرون'),
(1611, 12, 15, 'فَلَمَّا ذَهَبُوا بِه۪ وَاَجْمَعُٓوا اَنْ يَجْعَلُوهُ ف۪ي غَيَابَتِ الْجُبِّۚ وَاَوْحَيْنَٓا اِلَيْهِ لَتُنَبِّئَنَّهُمْ بِاَمْرِهِمْ هٰذَا وَهُمْ لَا يَشْعُرُونَ', 'Fe lemma zehebu bihi ve ecmeu en yec\'aluhu fi gayabetil cubb, ve evhayna ileyhi le tunebbiennehum bi emrihim haza ve hum la yeş\'urun.', 'O\'nu alıp götürdüler. Hep birlikte onu kuyunun dibine bırakmaya karar verdiler. O sırada Yusuf\'a: \"Ant olsun onların bu yaptıklarını,  bir gün gelecek yüzlerine vuracaksın.\" diye vahyettik.', 'فلما ذهبوا به واجمعوا ان يجعلوه في غيبت الجب واوحينا اليه لتنبينهم بامرهم هذا وهم لا يشعرون'),
(1612, 12, 16, 'وَجَٓاؤُٓ۫ اَبَاهُمْ عِشَٓاءً يَبْكُونَۜ', 'Ve cau ebahum işaen yebkun.', 'Ve akşam olunca,  ağlayarak babalarına geldiler.', 'وجاو اباهم عشا يبكون'),
(1613, 12, 17, 'قَالُوا يَٓا اَبَانَٓا اِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَاَكَلَهُ الذِّئْبُۚ وَمَٓا اَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِق۪ينَ', 'Kalu ya ebana inna zehebna nestebiku ve terekna yusufe inde metaına fe ekelehuz zi\'bu, ve ma ente bi mu\'minin lena ve lev kunna sadikin.', '\"Ey babamız! Yarışmaya gittik. Yusuf\'u da eşyamızın yanına bırakmıştık. Kurt onu yemiş. Sen bize inanmayacaksın ama doğru söylüyoruz.\" dediler.', 'قالوا يابانا انا ذهبنا نستبق وتركنا يوسف عند متعنا فاكله الذيب وما انت بمومن لنا ولو كنا صدقين'),
(1614, 12, 18, 'وَجَٓاؤُ۫ عَلٰى قَم۪يصِه۪ بِدَمٍ كَذِبٍۜ قَالَ بَلْ سَوَّلَتْ لَكُمْ اَنْفُسُكُمْ اَمْراًۜ فَصَبْرٌ جَم۪يلٌۜ وَاللّٰهُ الْمُسْتَعَانُ عَلٰى مَا تَصِفُونَ', 'Ve cau ala kamisıhi bi demin kezib, kale bel sevvelet lekum enfusukum emra, fe sabrun cemil, vallahul musteanu ala ma tesıfun.', 'Yalandan kan sürülmüş gömleğini getirdiler. Dedi ki: \"Nefisleriniz[1] size bir iş yaptırdı. Anlattığınız şeye karşı yapabileceğim şey,  güzelce sabredip,  Allah\'tan yardım istemektir.\"', 'وجاو علي قميصه بدم كذب قال بل سولت لكم انفسكم امرا فصبر جميل والله المستعان علي ما تصفون'),
(1615, 12, 19, 'وَجَٓاءَتْ سَيَّارَةٌ فَاَرْسَلُوا وَارِدَهُمْ فَاَدْلٰى دَلْوَهُۜ قَالَ يَا بُشْرٰى هٰذَا غُلَامٌۜ وَاَسَرُّوهُ بِضَاعَةًۜ وَاللّٰهُ عَل۪يمٌ بِمَا يَعْمَلُونَ', 'Ve caet seyyaretun fe erselu varidehum fe adla delveh, kale ya buşra haza gulam, ve eserruhu bidaah, vallahu alimun bi ma ya\'melun.', 'Ve bir kervan geldi. Sucularını gönderdiler. Kovasını sarkıtan,  \"Müjde! Burada bir çocuk var\" dedi. Satmak için onu yanlarına aldılar. Allah,  yapmak istedikleri şeyi çok iyi biliyordu.', 'وجات سيارة فارسلوا واردهم فادلي دلوه قال يبشري هذا غلم واسروه بضعة والله عليم بما يعملون'),
(1616, 12, 20, 'وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍۚ وَكَانُوا ف۪يهِ مِنَ الزَّاهِد۪ينَ۟', 'Ve şerevhu bi semenin bahsin derahime ma\'dudeh, ve kanu fihi minez zahidin.', 'Onu ucuz bir fiyata,  birkaç dirheme sattılar. Ona önem vermemişlerdi.', 'وشروه بثمن بخس درهم معدودة وكانوا فيه من الزهدين'),
(1617, 12, 21, 'وَقَالَ الَّذِي اشْتَرٰيهُ مِنْ مِصْرَ لِامْرَاَتِه۪ٓ اَكْرِم۪ي مَثْوٰيهُ عَسٰٓى اَنْ يَنْفَعَنَٓا اَوْ نَتَّخِذَهُ وَلَداًۜ وَكَذٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْاَرْضِۘ وَلِنُعَلِّمَهُ مِنْ تَأْو۪يلِ الْاَحَاد۪يثِۜ وَاللّٰهُ غَالِبٌ عَلٰٓى اَمْرِه۪ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', 'Ve kalellezişterahu min mısra limre\'etihi ekrimi mesvahu asa en yenfeana ev nettehizehu veleda, ve kezalike mekkenna li yusufe fil ardı ve li nuallimehu min te\'vilil ehadis, vallahu galibun ala emrihi ve lakinne ekseren nasi la ya\'lemun.', 'Onu satın alan Mısırlı,  hanımına: \"Ona iyi bak,  bize faydası olabilir,  belki de onu evlat ediniriz.\" dedi. Böylece Yusuf\'u oraya yerleştirdik ki ona kimi hadislerin[1] yorumunu öğretelim. Allah,  takdir ettiğini yapandır. Ancak insanların çoğu bunu bilmezler.', 'وقال الذي اشتريه من مصر لامراته اكرمي مثويه عسي ان ينفعنا او نتخذه ولدا وكذلك مكنا ليوسف في الارض ولنعلمه من تاويل الاحاديث والله غالب علي امره ولكن اكثر الناس لا يعلمون'),
(1618, 12, 22, 'وَلَمَّا بَلَغَ اَشُدَّهُٓ اٰتَيْنَاهُ حُكْماً وَعِلْماًۜ وَكَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'Ve lemma belega eşuddehu ateynahu hukmen ve ilma, ve kezalike neczil muhsinin.', 'Olgunluk çağına erişince ona hükmetme yeteneği ve bilgi verdik. İşte Biz,  iyi davrananları böyle ödüllendiririz.', 'ولما بلغ اشده اتينه حكما وعلما وكذلك نجزي المحسنين'),
(1619, 12, 23, 'وَرَاوَدَتْهُ الَّت۪ي هُوَ ف۪ي بَيْتِهَا عَنْ نَفْسِه۪ وَغَلَّقَتِ الْاَبْوَابَ وَقَالَتْ هَيْتَ لَكَۜ قَالَ مَعَاذَ اللّٰهِ اِنَّهُ رَبّ۪ٓي اَحْسَنَ مَثْوَايَۜ اِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', 'Ve ravedethulleti huve fi beytiha an nefsihi ve ğallekatil ebvabe ve kalet heyte lek, kale ma azallahi innehu rabbi ahsene mesvay, innehu la yuflihuz zalimun.', 'Evinde kaldığı kadın,  ona sahip olmak istedi. Ve kapıları sıkıca kapatıp onu yanına çağırdı. Yusuf: \"Allah\'a sığınırım. Rabbim[1] bana çok iyi davrandı.[2] Beni çok güzel bir konuma sahip kıldı. Haksızlık yapanlar kurtuluşa ermezler.\" dedi.', 'ورودته التي هو في بيتها عن نفسه وغلقت الابوب وقالت هيت لك قال معاذ الله انه ربي احسن مثواي انه لا يفلح الظلمون'),
(1620, 12, 24, 'وَلَقَدْ هَمَّتْ بِه۪ۗ وَهَمَّ بِهَاۚ لَوْلَٓا اَنْ رَاٰ بُرْهَانَ رَبِّه۪ۜ  كَذٰلِكَ لِنَصْرِفَ عَنْهُ السُّٓوءَ وَالْفَحْشَٓاءَۜ اِنَّهُ مِنْ عِبَادِنَا الْمُخْلَص۪ينَ', 'Ve le kad hemmet bihi ve hemme biha, levla en rea burhane rabbih, kezalike li nasrife anhus sue vel fahşa, innehu min ibadinel muhlesin.', 'Gerçekten kadın Yusuf\'a ilgi duydu. Yusuf da kadına ilgi duydu. Ne var ki Rabb\'inin burhanı[1] sayesinde[2] kadına uymadı. Böylece ondan kötülüğü ve fuhşu[3] çevirdik. Kuşkusuz o Bizim muhles[4] kullarımızdandı.', 'ولقد همت به وهم بها لولا ان را برهن ربه كذلك لنصرف عنه السو والفحشا انه من عبادنا المخلصين'),
(1621, 12, 25, 'وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَم۪يصَهُ مِنْ دُبُرٍ وَاَلْفَيَا سَيِّدَهَا لَدَا الْبَابِۜ قَالَتْ مَا جَزَٓاءُ مَنْ اَرَادَ بِاَهْلِكَ سُٓوءاً اِلَّٓا اَنْ يُسْجَنَ اَوْ عَذَابٌ اَل۪يمٌ', 'Vestebekal babe ve kaddet kamisahu min duburin ve elfeya seyyideha ledel bab, kalet ma cezau men erade bi ehlike suen illa en yuscene ev azabun elim.', 'İkisi de kapıya doğru koştu. Kadın Yusuf\'un gömleğini arka tarafından yırttı. Kapıda kadının kocası ile karşılaştılar. Kadın: \"Ailene kötülük yapmak isteyen kimsenin zindana atılması veya acı bir azapla cezalandırılması gerekmez mi?\" dedi.', 'واستبقا الباب وقدت قميصه من دبر والفيا سيدها لدا الباب قالت ما جزا من اراد باهلك سوا الا ان يسجن او عذاب اليم'),
(1622, 12, 26, 'قَالَ هِيَ رَاوَدَتْن۪ي عَنْ نَفْس۪ي وَشَهِدَ شَاهِدٌ مِنْ اَهْلِهَاۚ اِنْ كَانَ قَم۪يصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِب۪ينَ', 'Kale hiye ravedetni an nefsi ve şehide şahidun min ehliha, in kane kamisuhu kudde min kubulin fe sadekat ve huve minel kazibin.', 'Yusuf: \"Kendisi bana sahip olmak istedi.\" dedi. Kadının ailesinden bir tanık durumu açığa çıkarmak için şöyle öneride bulundu: \" Eğer gömleği ön taraftan yırtılmışsa,  kadın doğru,  Yusuf yalan söylemektedir.\"', 'قال هي رودتني عن نفسي وشهد شاهد من اهلها ان كان قميصه قد من قبل فصدقت وهو من الكذبين'),
(1623, 12, 27, 'وَاِنْ كَانَ قَم۪يصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِق۪ينَ', 'Ve in kane kamisuhu kudde min duburin fe kezebet ve huve mines sadikin.', '\"Eğer gömlek arkadan yırtılmışsa,  kadın yalan,  O doğru söylemektedir.\"', 'وان كان قميصه قد من دبر فكذبت وهو من الصدقين'),
(1624, 12, 28, 'فَلَمَّا رَاٰ قَم۪يصَهُ قُدَّ مِنْ دُبُرٍ قَالَ اِنَّهُ مِنْ كَيْدِكُنَّۜ اِنَّ كَيْدَكُنَّ عَظ۪يمٌ', 'Fe lemma rea kamisahu kudde min duburin kale innehu min keydikun, inne keydekunne azim.', 'Gömleğin arkadan yırtılmış olduğunu görünce: \"Bu sizin oyununuzdur; gerçekten bu çok büyük bir oyundur.\" dedi.', 'فلما را قميصه قد من دبر قال انه من كيدكن ان كيدكن عظيم'),
(1625, 12, 29, 'يُوسُفُ اَعْرِضْ عَنْ هٰذَا وَاسْتَغْفِر۪ي لِذَنْبِكِۚ اِنَّكِ كُنْتِ مِنَ الْخَاطِـ۪ٔينَ۟', 'Yusufu a\'rıd an haza vestagfiri li zenbik, inneki kunti minel hatıin.', '\"Yusuf![1] Bundan kimseye söz etme. Sen[2] de suçundan dolayı bağışlanma dile. Yanlış yapan sensin!\" dedi.', 'يوسف اعرض عن هذا واستغفري لذنبك انك كنت من الخاطين'),
(1626, 12, 30, 'وَقَالَ نِسْوَةٌ فِي الْمَد۪ينَةِ امْرَاَتُ الْعَز۪يزِ تُرَاوِدُ فَتٰيهَا عَنْ نَفْسِه۪ۚ قَدْ شَغَفَهَا حُباًّۜ اِنَّا لَنَرٰيهَا ف۪ي ضَلَالٍ مُب۪ينٍ', 'Ve kale nisvetun fil medinetimre\'etul azizi turavidu fetaha an nefsih, kad şegafeha hubba, inna le neraha fi dalalin mubin.', 'Ve şehirdeki bir takım kadınlar: \"Azizin hanımı,  genç hizmetlisiyle birlikte olmak istemiş; delikanlının sevgisi yüreğine işlemiş. Onu açıkça sapıtmış görüyoruz.\" diye dedikodu yaptılar.', 'وقال نسوة في المدينة امرات العزيز ترود فتيها عن نفسه قد شغفها حبا انا لنريها في ضلل مبين'),
(1627, 12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ اَرْسَلَتْ اِلَيْهِنَّ وَاَعْتَدَتْ لَهُنَّ مُتَّكَـٔاً وَاٰتَتْ كُلَّ وَاحِدَةٍ مِنْهُنَّ سِكّ۪يناً وَقَالَتِ اخْرُجْ عَلَيْهِنَّۚ فَلَمَّا رَاَيْنَهُٓ اَكْبَرْنَهُ وَقَطَّعْنَ اَيْدِيَهُنَّ وَقُلْنَ حَاشَ لِلّٰهِ مَا هٰذَا بَشَراًۜ اِنْ هٰذَٓا اِلَّا مَلَكٌ كَر۪يمٌ', 'Fe lemma semiat bi mekrihinne erselet ileyhinne ve a\'tedet lehunne mutteke\'en ve atet kulle vahidetin minhunne sikkinen ve kaletihruc aleyhinn, fe lemma re\'eynehu ekbernehu ve katta\'ne eydiyehunne ve kulne haşe lillahi ma haza beşera,in haza illa melekun kerim.', 'Kadın dedikoduları işitince,  onları davet etti,  onlar için güzel bir ortam ve ziyafet hazırlayarak her birine birer bıçak verdi. Yusuf\'a \"Kadınların karşılarına çık.\" dedi. Kadınlar,  gördükleri karşısında adeta büyülendiler; şaşkınlıkla ellerini kestiler. \"Aman Allah\'ım! Bu bir beşer[1] değil,  bu ancak şerefli bir melektir.\" dediler.', 'فلما سمعت بمكرهن ارسلت اليهن واعتدت لهن متكا واتت كل واحدة منهن سكينا وقالت اخرج عليهن فلما راينه اكبرنه وقطعن ايديهن وقلن حش لله ما هذا بشرا ان هذا الا ملك كريم'),
(1628, 12, 32, 'قَالَتْ فَذٰلِكُنَّ الَّذ۪ي لُمْتُنَّن۪ي ف۪يهِۜ وَلَقَدْ رَاوَدْتُهُ عَنْ نَفْسِه۪ فَاسْتَعْصَمَۜ وَلَئِنْ لَمْ يَفْعَلْ مَٓا اٰمُرُهُ لَيُسْجَنَنَّ وَلَيَكُوناً مِنَ الصَّاغِر۪ينَ', 'Kalet fe zalikunnellezi lumtunneni fih, ve lekad ravedtuhu an nefsihi festa\'sam, ve lein lem yef\'al ma amuruhu le yuscenenne ve leyekunen mines sagırin.', 'Kadın: \"İşte! Bu gördüğünüz,  beni,  kendisi hakkında kınadığınız kimsedir. Ant olsun ki,  onun benim olmasını istedim,  ancak o reddetti. Ama ondan istediğim şeyi yapmazsa,  zindana atılacak ve kesinlikle burnu yere sürtülenlerden olacaktır.\" dedi.', 'قالت فذلكن الذي لمتنني فيه ولقد رودته عن نفسه فاستعصم ولين لم يفعل ما امره ليسجنن وليكونا من الصغرين'),
(1629, 12, 33, 'قَالَ رَبِّ السِّجْنُ اَحَبُّ اِلَيَّ مِمَّا يَدْعُونَن۪ٓي اِلَيْهِۚ وَاِلَّا تَصْرِفْ عَنّ۪ي كَيْدَهُنَّ اَصْبُ اِلَيْهِنَّ وَاَكُنْ مِنَ الْجَاهِل۪ينَ', 'Kale rabbis sicnu ehabbu ileyye mimma yed\'uneni ileyh, ve illa tasrif anni keydehunne asbu ileyhinne ve ekun minel cahilin.', '\"Ey Rabbim! Zindan bana,  bunların istedikleri şeyi yapmaktan daha sevimlidir. Eğer onların tuzaklarını benden savmazsan,  onlara kanıp cahillerden olurum.\" dedi.', 'قال رب السجن احب الي مما يدعونني اليه والا تصرف عني كيدهن اصب اليهن واكن من الجهلين'),
(1630, 12, 34, 'فَاسْتَجَابَ لَهُ رَبُّهُ فَصَرَفَ عَنْهُ كَيْدَهُنَّۜ اِنَّهُ هُوَ السَّم۪يعُ الْعَل۪يمُ', 'Festecabe lehu rabbuhu fe sarefe anhu keydehunn, innehu huves semiul alim.', 'Bunun üzerine Rabb\'i dileğini kabul etti ve tuzaklarını ondan savdı. O\' Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'فاستجاب له ربه فصرف عنه كيدهن انه هو السميع العليم'),
(1631, 12, 35, 'ثُمَّ بَدَا لَهُمْ مِنْ بَعْدِ مَا رَاَوُا الْاٰيَاتِ لَيَسْجُنُنَّهُ حَتّٰى ح۪ينٍ۟', 'Summe bedalehum min ba\'di ma raevul ayati le yescununnehu hatta hin.', 'Suçsuzluğuna dair kanıtlara rağmen yine de onu belli bir süre zindana atmaya karar verdiler.', 'ثم بدا لهم من بعد ما راوا الايت ليسجننه حتي حين'),
(1632, 12, 36, 'وَدَخَلَ مَعَهُ السِّجْنَ فَتَيَانِۜ قَالَ اَحَدُهُمَٓا اِنّ۪ٓي اَرٰين۪ٓي اَعْصِرُ خَمْراًۚ وَقَالَ الْاٰخَرُ اِنّ۪ٓي اَرٰين۪ٓي اَحْمِلُ فَوْقَ رَأْس۪ي خُبْزاً تَأْكُلُ الطَّيْرُ مِنْهُۜ نَبِّئْنَا بِتَأْو۪يلِه۪ۚ اِنَّا نَرٰيكَ مِنَ الْمُحْسِن۪ينَ', 'Ve dehale meahus sicne feteyan, kale ehaduhuma inni erani a\'sıru hamra, ve kalel aharu inni erani ahmilu fevka re\'si hubzen te\'kulut tayru minh, nebbi\'na bi te\'vilih, inna nerake minel muhsinin.', 'Onunla birlikte iki genç daha zindana atıldı. Onlardan biri: \"Ben,  rüyamda kendimi sarhoş edici şey yaparken gördüm.\" dedi. Diğeri: \"Ben de başımın üstünde ekmek taşıyordum,  kuşların da onu yediklerini gördüm. Bize bunu yorumla. Doğrusu senin iyilik eden kimselerden olduğunu görüyoruz.\" dedi.', 'ودخل معه السجن فتيان قال احدهما اني اريني اعصر خمرا وقال الاخر اني اريني احمل فوق راسي خبزا تاكل الطير منه نبينا بتاويله انا نريك من المحسنين'),
(1633, 12, 37, 'قَالَ لَا يَأْت۪يكُمَا طَعَامٌ تُرْزَقَانِه۪ٓ اِلَّا نَبَّأْتُكُمَا بِتَأْو۪يلِه۪ قَبْلَ اَنْ يَأْتِيَكُمَاۜ ذٰلِكُمَا مِمَّا عَلَّمَن۪ي رَبّ۪يۜ اِنّ۪ي تَرَكْتُ مِلَّةَ قَوْمٍ لَا يُؤْمِنُونَ بِاللّٰهِ وَهُمْ بِالْاٰخِرَةِ هُمْ كَافِرُونَۙ', 'Kale la ye\'tikuma taamun turzekanihi illa nebbe\'tukuma bi te\'vilihi kable en ye\'tiyekuma, zalikuma mimma allemeni rabbi, inni terektu millete kavmin la yu\'minune billahi ve hum bil ahiretihum kafirun.', '\"Yiyeceğiniz yemek daha gelmeden,  ikinizin de rüyasını yorumlayacağım. Rüya yorumu yapmak Rabb\'imin bana öğrettiği şeylerdendir. Doğrusu ben,  Allah\'a iman etmeyen ve Ahiret Günü\'nü yalanlayan bir halkın milletini[1] terk ettim.\" dedi.', 'قال لا ياتيكما طعام ترزقانه الا نباتكما بتاويله قبل ان ياتيكما ذلكما مما علمني ربي اني تركت ملة قوم لا يومنون بالله وهم بالاخرة هم كفرون'),
(1634, 12, 38, 'وَاتَّبَعْتُ مِلَّةَ اٰبَٓاء۪ٓي اِبْرٰه۪يمَ وَاِسْحٰقَ وَيَعْقُوبَۜ مَا كَانَ لَـنَٓا اَنْ نُشْرِكَ بِاللّٰهِ مِنْ شَيْءٍۜ ذٰلِكَ مِنْ فَضْلِ اللّٰهِ عَلَيْنَا وَعَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', 'Vetteba\'tu millete abai ibrahime ve ishaka ve ya\'kub, ma kane lena en nuşrike billahi min şey, zalike min fadlillahi aleyna ve alen nasi ve lakinne ekseren nasi la yeşkurun.', '\"Atalarım İbrahim,  İshak ve Yakub\'un milletini seçtim. Allah\'a,  herhangi bir şeyi ortak koşmak bize yakışmaz. Bu,  Allah\'ın bize ve insanlara olan lütfudur. Ne var ki,  insanların çoğu yine de şükretmiyorlar!\"', 'واتبعت ملة اباي ابرهيم واسحق ويعقوب ما كان لنا ان نشرك بالله من شي ذلك من فضل الله علينا وعلي الناس ولكن اكثر الناس لا يشكرون'),
(1635, 12, 39, 'يَا صَاحِبَيِ السِّجْنِ ءَاَرْبَابٌ مُتَفَرِّقُونَ خَيْرٌ اَمِ اللّٰهُ الْوَاحِدُ الْقَهَّارُۜ', 'Ya sahibeyis sicni e erbabun muteferrikune hayrun emillahul vahıdul kahhar.', '\"Ey zindan arkadaşlarım! Ayrı ayrı rabler mi daha hayırlıdır,  yoksa Kahhar[1] olan tek Allah mı?\"', 'يصحبي السجن ارباب متفرقون خير ام الله الوحد القهار'),
(1636, 12, 40, 'مَا تَعْبُدُونَ مِنْ دُونِه۪ٓ اِلَّٓا اَسْمَٓاءً سَمَّيْتُمُوهَٓا اَنْتُمْ وَاٰبَٓاؤُ۬كُمْ مَٓا اَنْزَلَ اللّٰهُ بِهَا مِنْ سُلْطَانٍۜ اِنِ الْحُكْمُ اِلَّا لِلّٰهِۜ اَمَرَ اَلَّا تَعْبُدُٓوا اِلَّٓا اِيَّاهُۜ ذٰلِكَ الدّ۪ينُ الْقَيِّمُ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', 'Ma ta\'budune min dunihi illa esmaen semmeytumuha entum ve abaukum ma enzelallahu biha min sultan, inil hukmu illa lillah, emere ella ta\'budu illa iyyah, zaliked dinul kayyimu ve lakinne ekseren nasi la ya\'lemun.', '\"Sizin,  O\'nun yanı sıra kulluk[1] ettiğiniz şeyler,  ancak sizin ve atalarınızın onlara yakıştırdığı isimlerden başka bir şey değildir. Allah,  onlar için hiçbir yetkilendirmede bulunmadı. Hüküm yalnızca Allah\'ındır; kendisinden başkasına kulluk etmemenizi emretmiştir. Dosdoğru din yalnızca budur. Ancak insanların çoğu bu gerçeği bilmezler.\"', 'ما تعبدون من دونه الا اسما سميتموها انتم واباوكم ما انزل الله بها من سلطن ان الحكم الا لله امر الا تعبدوا الا اياه ذلك الدين القيم ولكن اكثر الناس لا يعلمون'),
(1637, 12, 41, 'يَا صَاحِبَيِ السِّجْنِ اَمَّٓا اَحَدُكُمَا فَيَسْق۪ي رَبَّهُ خَمْراًۚ وَاَمَّا الْاٰخَرُ فَيُصْلَبُ فَتَأْكُلُ الطَّيْرُ مِنْ رَأْسِه۪ۜ قُضِيَ الْاَمْرُ الَّذ۪ي ف۪يهِ تَسْتَفْتِيَانِۜ', 'Ya sahıbeyis sicni emma ehadukuma fe yeski rabbehu hamra, ve emmel aharu fe yuslebu fe te\'kulut tayru min re\'sih, kudiyel emrullezi fihi testeftiyan.', '\"Ey zindan arkadaşlarım! Biriniz rabbine[1] yine içki sunacak,  biriniz ise asılacak ve kuşlar onun başından yiyecek. Bana sorduğunuz rüyanın gerçekleşecek yorumu budur.\"', 'يصحبي السجن اما احدكما فيسقي ربه خمرا واما الاخر فيصلب فتاكل الطير من راسه قضي الامر الذي فيه تستفتيان'),
(1638, 12, 42, 'وَقَالَ لِلَّذ۪ي ظَنَّ اَنَّهُ نَاجٍ مِنْهُمَا اذْكُرْن۪ي عِنْدَ رَبِّكَۘ فَاَنْسٰيهُ الشَّيْطَانُ ذِكْرَ رَبِّه۪ فَلَبِثَ فِي السِّجْنِ بِضْعَ سِن۪ينَۜ ۟', 'Ve kale lillezi zanne ennehu nacin minhumazkurni inde rabbike fe ensahuş şeytanu zikre rabbihi fe lebise fis sicni bid\'a sinin.', 'O ikisinden,  kurtulacağını umduğu kimseye dedi ki: \"Rabbinin[1] yanında beni an.\"[2] Ne var ki şeytan,  ona rabbine[3] Yusuf\'tan söz etmeyi unutturdu. O da nice yıllar zindanda kaldı.', 'وقال للذي ظن انه ناج منهما اذكرني عند ربك فانسيه الشيطن ذكر ربه فلبث في السجن بضع سنين'),
(1639, 12, 43, 'وَقَالَ الْمَلِكُ اِنّ۪ٓي اَرٰى سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنْبُلَاتٍ خُضْرٍ وَاُخَرَ يَابِسَاتٍۜ يَٓا اَيُّهَا الْمَلَأُ اَفْتُون۪ي ف۪ي رُءْيَايَ اِنْ كُنْتُمْ لِلرُّءْيَا تَعْبُرُونَ', 'Ve kalel meliku inni era seb\'a bakaratin simanin ye\'kuluhunne seb\'un icafun ve seb\'a sunbulatin hudrin ve uhara yabisat , ya eyyuhel meleu eftuni fi ru\'yaye in kuntum lir ru\'ya ta\'burun.', 'Derken Hükümdar dedi ki: \"Doğrusu ben rüyamda yedi besili sığırı görüyorum; bunları yedi zayıf sığır yiyor. Ve yedi yeşil ve kuru başak görüyorum. Ey meleler![1] Eğer rüya tabir etmeyi biliyorsanız rüyamı yorumlayın.\"', 'وقال الملك اني اري سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر واخر يابست يايها الملا افتوني في ريي ان كنتم للريا تعبرون'),
(1640, 12, 44, 'قَالُٓوا اَضْغَاثُ اَحْلَامٍۚ وَمَا نَحْنُ بِتَأْو۪يلِ الْاَحْلَامِ بِعَالِم۪ينَ', 'Kalu adgasu ahlam, ve ma nahnu bi te\'vilil ahlami bi alimin.', '\"Bunlar,  karışık rüyalardır. Biz böyle rüyaların yorumunu bilenlerden değiliz.\" dediler.', 'قالوا اضغث احلم وما نحن بتاويل الاحلم بعلمين'),
(1641, 12, 45, 'وَقَالَ الَّذ۪ي نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ اُمَّةٍ اَنَا۬ اُنَبِّئُكُمْ بِتَأْو۪يلِه۪ فَاَرْسِلُونِ', 'Ve kalellezi neca minhuma veddekere ba\'de ummetin ene unebbiukum bi te\'vilihi fe ersilun.', 'Ancak o zaman o iki kişiden kurtulmuş olanı,  aradan geçen bunca zamandan sonra hatırladı. \"Beni hemen gönderin,  rüyanın yorumunu ben size söyleyeceğim.\"', 'وقال الذي نجا منهما وادكر بعد امة انا انبيكم بتاويله فارسلون'),
(1642, 12, 46, 'يُوسُفُ اَيُّهَا الصِّدّ۪يقُ اَفْتِنَا ف۪ي سَبْعِ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنْبُلَاتٍ خُضْرٍ وَاُخَرَ يَابِسَاتٍۙ لَعَلّ۪ٓي اَرْجِعُ اِلَى النَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'Yusufu eyyuhes sıddiku eftina fi seb\'ı bakaratin simanin ye\'kuluhunne seb\'un icafun ve seb\'ı sunbulatin hudrin ve uhare yabisatin, lealli erciu ilen nasi leallehum ya\'lemun.', '\"Ey doğru sözlü Yusuf! Yedi besili sığırı yiyen,  yedi zayıf sığır ile yedi yeşil başak ve kuru başağın ne anlama geldiğini bize açıkla. Döndüğümde insanlara anlatayım da böylece onlar senin değerini öğrenmiş olurlar.\"', 'يوسف ايها الصديق افتنا في سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر واخر يابست لعلي ارجع الي الناس لعلهم يعلمون'),
(1643, 12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِن۪ينَ دَاَباًۚ فَمَا حَصَدْتُمْ فَذَرُوهُ ف۪ي سُنْبُلِه۪ٓ اِلَّا قَل۪يلاً مِمَّا تَأْكُلُونَ', 'Kale tezreune seb\'a sinine de\'eba, fe ma hasadtum fe zeruhu fi sunbulihi illa kalilen mimma te\'kulun.', 'Dedi ki: \"Yedi yıl bildik şekilde ekip biçin. Ancak biçtiğinizden,  yiyeceğiniz kadarını ayırdıktan sonra kalanı biriktirin.\"', 'قال تزرعون سبع سنين دابا فما حصدتم فذروه في سنبله الا قليلا مما تاكلون'),
(1644, 12, 48, 'ثُمَّ يَأْت۪ي مِنْ بَعْدِ ذٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ اِلَّا قَل۪يلاً مِمَّا تُحْصِنُونَ', 'Summe ye\'ti min ba\'di zalike seb\'un şidadun ye\'kulne ma kaddemtum lehunne illa kalilen mimma tuhsinun.', 'Sonra yedi yıllık bir kıtlık dönemi gelecek,  önceden biriktirdiğinizin az bir miktarı hariç tamamı yenip bitirilecek.', 'ثم ياتي من بعد ذلك سبع شداد ياكلن ما قدمتم لهن الا قليلا مما تحصنون'),
(1645, 12, 49, 'ثُمَّ يَأْت۪ي مِنْ بَعْدِ ذٰلِكَ عَامٌ ف۪يهِ يُغَاثُ النَّاسُ وَف۪يهِ يَعْصِرُونَ۟', 'Summe ye\'ti min ba\'di zalike amun fihi yugasun nasu ve fihi ya\'sırun.', 'Bu sıkıntının ardından,  bol yağmurlu bir yıl gelecek. Ve insanlar onda sıkıp sağacaklar.[1]', 'ثم ياتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون'),
(1646, 12, 50, 'وَقَالَ الْمَلِكُ ائْتُون۪ي بِه۪ۚ فَلَمَّا جَٓاءَهُ الرَّسُولُ قَالَ ارْجِعْ اِلٰى رَبِّكَ فَسْـَٔلْهُ مَا بَالُ النِّسْوَةِ الّٰت۪ي قَطَّعْنَ اَيْدِيَهُنَّۜ اِنَّ رَبّ۪ي بِكَيْدِهِنَّ عَل۪يمٌ', 'Ve kalel meliku\'tuni bih, fe lemma caehur resulu kalerci\' ila rabbike fes\'elhu ma balun nisvetillati katta\'ne eydiyehunn, inne rabbi bi keydihinne alim.', 'Hükümdar: \"Onu bana getirin.\" dedi. Hükümdarın elçisi ona gelince,  rabbine[1] dön ve ona,  ellerini kesen kadınların durumunu sor.[2] Kuşkusuz Rabb\'im onların hilesini bilendir.', 'وقال الملك ايتوني به فلما جاه الرسول قال ارجع الي ربك فسله ما بال النسوة التي قطعن ايديهن ان ربي بكيدهن عليم'),
(1647, 12, 51, 'قَالَ مَا خَطْبُكُنَّ اِذْ رَاوَدْتُنَّ يُوسُفَ عَنْ نَفْسِه۪ۜ قُلْنَ حَاشَ لِلّٰهِ مَا عَلِمْنَا عَلَيْهِ مِنْ سُٓوءٍۜ قَالَتِ امْرَاَتُ الْعَز۪يزِ الْـٰٔنَ حَصْحَصَ الْحَقُّۘ اَنَا۬ رَاوَدْتُهُ عَنْ نَفْسِه۪ وَاِنَّهُ لَمِنَ الصَّادِق۪ينَ', 'Kale ma hatbukunne iz ravedtunne yusufe an nefsih, kulne haşe lillahi ma alimna aleyhi min su\', kaletimre\'etul azizil ane hashasal hakku ene ravedtuhu an nefsihi ve innehu le mines sadikin.', 'Hükümdar: \"Yusuf\'tan murat almak istediğinizde ondan nasıl bir karşılık aldınız?\" dedi. Kadınlar: \"Haşa! Allah için onun bir kötülüğünü bilmiyoruz.\" dediler. Aziz\'in hanımı: \"Şimdi gerçek ortaya çıktı,  ona ben sahip olmaya kalkıştım,  o kesinlikle doğru söyleyenlerdendir.\" dedi.', 'قال ما خطبكن اذ رودتن يوسف عن نفسه قلن حش لله ما علمنا عليه من سو قالت امرات العزيز الن حصحص الحق انا رودته عن نفسه وانه لمن الصدقين'),
(1648, 12, 52, 'ذٰلِكَ لِيَعْلَمَ اَنّ۪ي لَمْ اَخُنْهُ بِالْغَيْبِ وَاَنَّ اللّٰهَ لَا يَهْد۪ي كَيْدَ الْخَٓائِن۪ينَ', 'Zalike li ya\'leme enni lem ehunhu bil gaybi ve ennallahe la yehdi keydel hainin.', '\"Bu,  gıyabında ona ihanet etmediğimi[1] ve Allah\'ın hainlerin planlarını başarılı kılmadığını bilmesi içindir.\"', 'ذلك ليعلم اني لم اخنه بالغيب وان الله لا يهدي كيد الخاينين'),
(1649, 12, 53, 'وَمَٓا اُبَرِّئُ نَفْس۪يۚ اِنَّ النَّفْسَ لَاَمَّارَةٌ بِالسُّٓوءِ اِلَّا مَا رَحِمَ رَبّ۪يۜ اِنَّ رَبّ۪ي غَفُورٌ رَح۪يمٌ', 'Ve ma uberriu nefsi, innen nefse le emmaretun bis suı illa ma rahime rabbi, inne rabbi gafurun rahim.', '\"Ben[1] kendimi temize çıkarmam. Rabb\'imin rahmet ettiği kimse hariç nefis her zaman kötülüğü ister. Rabb\'im Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.\"', 'وما ابري نفسي ان النفس لامارة بالسو الا ما رحم ربي ان ربي غفور رحيم'),
(1650, 12, 54, 'وَقَالَ الْمَلِكُ ائْتُون۪ي بِه۪ٓ اَسْتَخْلِصْهُ لِنَفْس۪يۚ فَلَمَّا كَلَّمَهُ قَالَ اِنَّكَ الْيَوْمَ لَدَيْنَا مَك۪ينٌ اَم۪ينٌ', 'Ve kalel meliku\'tuni bihi estahlishu li nefsi, fe lemma kellemehu kale innekel yevme ledeyna mekinun emin.', 'Ve Hükümdar: \"Onu bana getirin. Onu,  yanımda seçkin bir kimse yapayım.\" dedi. Onunla görüştüğünde de: \"Sen bundan böyle yanımızda itibarlısın ve güvendesin.\" dedi.', 'وقال الملك ايتوني به استخلصه لنفسي فلما كلمه قال انك اليوم لدينا مكين امين'),
(1651, 12, 55, 'قَالَ اجْعَلْن۪ي عَلٰى خَزَٓائِنِ الْاَرْضِۚ اِنّ۪ي حَف۪يظٌ عَل۪يمٌ', 'Kalec\'alni ala hazainil ard, inni hafizun alim.', 'Yusuf: \"Beni ülkenin hazinelerinin başına tayin et. Zira ben onları korurum ve iyi bilirim.\" dedi.', 'قال اجعلني علي خزاين الارض اني حفيظ عليم'),
(1652, 12, 56, 'وَكَذٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْاَرْضِۚ يَتَبَوَّاُ مِنْهَا حَيْثُ يَشَٓاءُۜ نُص۪يبُ بِرَحْمَتِنَا مَنْ نَشَٓاءُ وَلَا نُض۪يعُ اَجْرَ الْمُحْسِن۪ينَ', 'Ve kezalike mekkenna li yusufe fil ard, yetebevveu minha haysu yeşa\', nusibu bi rahmetina men neşau ve la nudiu ecrel muhsinin.', 'Ve böylece Yusuf\'u yetki sahibi yaptık,  istediği yerde mekan tutma imkanı verdik. Rahmetimizi istediğimize veririz. İyilik edenlerin yaptıklarını karşılıksız bırakmayız.', 'وكذلك مكنا ليوسف في الارض يتبوا منها حيث يشا نصيب برحمتنا من نشا ولا نضيع اجر المحسنين'),
(1653, 12, 57, 'وَلَاَجْرُ الْاٰخِرَةِ خَيْرٌ لِلَّذ۪ينَ اٰمَنُوا وَكَانُوا يَتَّقُونَ۟', 'Ve le ecrul ahıreti hayrun lillezine amenu ve kanu yettekun.', 'Ancak iman eden ve takva[1] sahibi olan kimseler için ahiretteki ödül hayırlı olandır.', 'ولاجر الاخرة خير للذين امنوا وكانوا يتقون'),
(1654, 12, 58, 'وَجَٓاءَ اِخْوَةُ يُوسُفَ فَدَخَلُوا عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُ مُنْكِرُونَ', 'Ve cae ihvetu yusufe fe dehalu aleyhi fe arefehum ve hum lehu munkirun.', 'Nihayet Yusuf\'un kardeşleri geldi ve onun huzuruna çıktılar. Yusuf onları hemen tanıdı. Ama onlar onu tanıyamadılar.', 'وجا اخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون'),
(1655, 12, 59, 'وَلَمَّا جَهَّزَهُمْ بِجَهَازِهِمْ قَالَ ائْتُون۪ي بِاَخٍ لَكُمْ مِنْ اَب۪يكُمْۚ اَلَا تَرَوْنَ اَنّ۪ٓي اُو۫فِي الْكَيْلَ وَاَنَا۬ خَيْرُ الْمُنْزِل۪ينَ', 'Ve lemma cehhezehum bi cehazihim kale\'tuni bi ahin lekum min ebikum, e la terevne enni ufil keyle ve ene hayrul munzilin.', 'Yüklerini yüklettikten sonra,  kendilerine: \"Baba bir kardeşinizi de bana getirin. Görüyorsunuz ki ihtiyacınızı fazlasıyla veriyorum ve ben iyi bir misafirperverim.\" dedi', 'ولما جهزهم بجهازهم قال ايتوني باخ لكم من ابيكم الا ترون اني اوفي الكيل وانا خير المنزلين'),
(1656, 12, 60, 'فَاِنْ لَمْ تَأْتُون۪ي بِه۪ فَلَا كَيْلَ لَكُمْ عِنْد۪ي وَلَا تَقْرَبُونِ', 'Fe in lem te\'tuni bihi fe la keyle lekum indi ve la takrebun.', '\"Buna rağmen eğer o kardeşinizi bana getirmezseniz,  size hiçbir şey vermem ve asla yanıma da yaklaşmayın.\"', 'فان لم تاتوني به فلا كيل لكم عندي ولا تقربون'),
(1657, 12, 61, 'قَالُوا سَنُرَاوِدُ عَنْهُ اَبَاهُ وَاِنَّا لَفَاعِلُونَ', 'Kalu senuravidu anhu ebahu ve inna le fa\'ilun.', '\"Babasını ikna etmeye çalışacağız. Bunu mutlaka yapacağız.\" dediler.', 'قالوا سنرود عنه اباه وانا لفعلون'),
(1658, 12, 62, 'وَقَالَ لِفِتْيَانِهِ اجْعَلُوا بِضَاعَتَهُمْ ف۪ي رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَـهَٓا اِذَا انْقَلَـبُٓوا اِلٰٓى اَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve kale li fityanihic\'alu bidaatehum fi rihalihim leallehum ya\'rifuneha izenkalebu ila ehlihim leallehum yerci\'un.', 'Yusuf adamlarına: \"Verdiklerini,  yüklerinin içine koyun. Umulur ki ailelerine döndüklerinde bunu görür ve geri gelirler.\" dedi.', 'وقال لفتينه اجعلوا بضعتهم في رحالهم لعلهم يعرفونها اذا انقلبوا الي اهلهم لعلهم يرجعون'),
(1659, 12, 63, 'فَلَمَّا رَجَعُٓوا اِلٰٓى اَب۪يهِمْ قَالُوا يَٓا اَبَانَا مُنِـعَ مِنَّا الْكَيْلُ فَاَرْسِلْ مَعَنَٓا اَخَانَا نَكْتَلْ وَاِنَّا لَهُ لَحَافِظُونَ', 'Fe lemma receu ila ebihim kalu ya ebana munia minnel keylu fe ersil meana ehana nektel ve inna lehu le hafizun.', 'Babalarının yanına vardıklarında: \"Ey babamız! Kardeşimizi bizimle birlikte gönder ki tahıl alalım. Yoksa bize tahıl verilmeyecek. Onu mutlaka koruruz.\" dediler.', 'فلما رجعوا الي ابيهم قالوا يابانا منع منا الكيل فارسل معنا اخانا نكتل وانا له لحفظون'),
(1660, 12, 64, 'قَالَ هَلْ اٰمَنُكُمْ عَلَيْهِ اِلَّا كَمَٓا اَمِنْتُكُمْ عَلٰٓى اَخ۪يهِ مِنْ قَبْلُۜ فَاللّٰهُ خَيْرٌ حَافِظاًۖ وَهُوَ اَرْحَمُ الرَّاحِم۪ينَ', 'Kale hel amenukum aleyhi illa kema emintukum ala ahihi min kabl, fallahu hayrun hafiza ve huve erhamur rahimin.', '\"Size güvenir miyim hiç? Bundan önce kardeşiniz hakkında da size güvenmiştim! Ama en iyi koruyucu Allah\'tır ve O,  merhamet edenlerin en merhametlisidir.\" dedi.', 'قال هل امنكم عليه الا كما امنتكم علي اخيه من قبل فالله خير حفظا وهو ارحم الرحمين'),
(1661, 12, 65, 'وَلَمَّا فَتَحُوا مَتَاعَهُمْ وَجَدُوا بِضَاعَتَهُمْ رُدَّتْ اِلَيْهِمْۜ قَالُوا يَٓا اَبَانَا مَا نَبْغ۪يۜ هٰذِه۪ بِضَاعَتُنَا رُدَّتْ اِلَيْنَاۚ وَنَم۪يرُ اَهْلَنَا وَنَحْفَظُ اَخَانَا وَنَزْدَادُ كَيْلَ بَع۪يرٍۜ ذٰلِكَ كَيْلٌ يَس۪يرٌ', 'Ve lemma fetehu metaahum vecedu bidaatehum ruddet ileyhim, kalu ya ebana ma nebgi, hazihi bidaatuna ruddet ileyna, ve nemiru ehlena ve nahfazu ehana ve nezdadu keyle beir , zalike keylun yesir.', 'Tahıl yüklerini açtıklarında verdikleri bedelin kendilerine geri verilmiş olduğunu gördüler. \"Ey babamız! Bak sermayemiz bize geri verilmiş. Daha ne istiyoruz! Onunla da kendimize tahıl getiririz. Kardeşimizi de koruruz. Fazladan bir deve yükü daha alırız. Zaten bu bize yetmez.\" dediler.', 'ولما فتحوا متعهم وجدوا بضعتهم ردت اليهم قالوا يابانا ما نبغي هذه بضعتنا ردت الينا ونمير اهلنا ونحفظ اخانا ونزداد كيل بعير ذلك كيل يسير'),
(1662, 12, 66, 'قَالَ لَنْ اُرْسِلَهُ مَعَكُمْ حَتّٰى تُؤْتُونِ مَوْثِقاً مِنَ اللّٰهِ لَتَأْتُنَّن۪ي بِه۪ٓ اِلَّٓا اَنْ يُحَاطَ بِكُمْۚ فَلَمَّٓا اٰتَوْهُ مَوْثِقَهُمْ قَالَ اللّٰهُ عَلٰى مَا نَقُولُ وَك۪يلٌ', 'Kale len ursilehu meakum hatta tu\'tuni mevsikan minallahi le te\'tunneni bihi illa en yuhata bikum, fe lemma atevhu mevsikahum kalallahu ala ma nekulu vekil.', '\"Saldırıya uğrayıp çaresiz kalmadıkça,  kesinlikle onu bana getireceğinize dair Allah adına sağlam bir söz vermedikçe,  onu sizinle asla göndermem.\" dedi. Onlar,  söz verince: \"Allah söylediklerimize vekildir.\" dedi.', 'قال لن ارسله معكم حتي توتون موثقا من الله لتاتنني به الا ان يحاط بكم فلما اتوه موثقهم قال الله علي ما نقول وكيل'),
(1663, 12, 67, 'وَقَالَ يَا بَنِيَّ لَا تَدْخُلُوا مِنْ بَابٍ وَاحِدٍ وَادْخُلُوا مِنْ اَبْوَابٍ مُتَفَرِّقَةٍۜ وَمَٓا اُغْن۪ي عَنْكُمْ مِنَ اللّٰهِ مِنْ شَيْءٍۜ اِنِ الْحُكْمُ اِلَّا لِلّٰهِۜ عَلَيْهِ تَوَكَّلْتُۚ وَعَلَيْهِ فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ', 'Ve kale ya beniyye la tedhulu min babin vahidin vedhulu min ebvabin muteferrikah, ve ma ugni ankum minallahi min şey inil hukmu illa lillah, aleyhi tevekkeltu ve aleyhi fel yetevekkelil mutevekkilun.', 'Ve \"Ey oğullarım! Aynı kapıdan girmeyin,  her biriniz ayrı bir kapıdan girin. Allah\'ın takdirine karşı size bir faydam olmaz. Hüküm yalnızca Allah\'ındır. Ben O\'na tevekkül[1] ettim. Tevekkül edecek olanlar O\'na tevekkül etsinler.\" dedi.', 'وقال يبني لا تدخلوا من باب وحد وادخلوا من ابوب متفرقة وما اغني عنكم من الله من شي ان الحكم الا لله عليه توكلت وعليه فليتوكل المتوكلون'),
(1664, 12, 68, 'وَلَمَّا دَخَلُوا مِنْ حَيْثُ اَمَرَهُمْ اَبُوهُمْۜ مَا كَانَ يُغْن۪ي عَنْهُمْ مِنَ اللّٰهِ مِنْ شَيْءٍ اِلَّا حَاجَةً ف۪ي نَفْسِ يَعْقُوبَ قَضٰيهَاۜ وَاِنَّهُ لَذُو عِلْمٍ لِمَا عَلَّمْنَاهُ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ۟', 'Ve lemma dehalu min haysu emerehum ebuhum, ma kane yugni anhum minallahi min şey\'in illa haceten fi nefsi ya\'kube kadaha, ve innehu le zu ilmin lima allemnahu ve lakinne ekseren nasi la ya\'lemun.', 'Babalarının istediği şekilde girdiler. Yakub,  eğer Allah,  haklarında bir şey takdir etmiş olsaydı,  içinden gelen bu dileğin onlara fayda vermeyeceğini bilmekteydi. O,  kendisine öğrettiğimiz için ilim sahibiydi. Ancak insanların çoğu bilmezler.', 'ولما دخلوا من حيث امرهم ابوهم ما كان يغني عنهم من الله من شي الا حاجة في نفس يعقوب قضيها وانه لذو علم لما علمنه ولكن اكثر الناس لا يعلمون'),
(1665, 12, 69, 'وَلَمَّا دَخَلُوا عَلٰى يُوسُفَ اٰوٰٓى اِلَيْهِ اَخَاهُ قَالَ اِنّ۪ٓي اَنَا۬ اَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَعْمَلُونَ', 'Ve lemma dehalu ala yusufe ava ileyhi ehahu, kale inni ene ehuke fe la tebteis bima kanu ya\'melun.', 'Kardeşleri Yusuf\'un yanına girince,  o,  öz kardeşini yanına alarak,  \"Ben senin öz kardeşinim,  onların yapmış oldukları şeylerden dolayı artık üzülme.\" dedi.', 'ولما دخلوا علي يوسف اوي اليه اخاه قال اني انا اخوك فلا تبتيس بما كانوا يعملون'),
(1666, 12, 70, 'فَلَمَّا جَهَّزَهُمْ بِجَهَازِهِمْ جَعَلَ السِّقَايَةَ ف۪ي رَحْلِ اَخ۪يهِ ثُمَّ اَذَّنَ مُؤَذِّنٌ اَيَّتُهَا الْع۪يرُ اِنَّكُمْ لَسَارِقُونَ', 'Fe lemma cehhezehum bi cehazihim ceales sikayete fi rahli ahihi, summe ezzene muezzinun eyyetuhel iru innekum le sarikun.', 'Yüklerini yükletirken su kabını öz kardeşinin yükü içine koydurttu. Sonra bir çağırıcı: \"Ey kervancılar! Siz hırsız kimselersiniz.\" diye seslendi.', 'فلما جهزهم بجهازهم جعل السقاية في رحل اخيه ثم اذن موذن ايتها العير انكم لسرقون'),
(1667, 12, 71, 'قَالُوا وَاَقْبَلُوا عَلَيْهِمْ مَاذَا تَفْقِدُونَ', 'Kalu ve akbelu aleyhim maza tefkidun.', 'Döndüler ve çağırıcıya,  \"Ne kaybettiniz?\" dediler.', 'قالوا واقبلوا عليهم ماذا تفقدون'),
(1668, 12, 72, 'قَالُوا نَفْقِدُ صُوَاعَ الْمَلِكِ وَلِمَنْ جَٓاءَ بِه۪ حِمْلُ بَع۪يرٍ وَاَنَا۬ بِه۪ زَع۪يمٌ', 'Kalu nefkıdu suvaalmeliki ve li men cae bihi hımlu beirin ve ene bihi za\'im.', '\"Hükümdarın su kabını arıyoruz. Onu bulana bir deve yükü ödül var.\" dediler. Çağırıcı: \"Ben buna garanti veriyorum.\" dedi.', 'قالوا نفقد صواع الملك ولمن جا به حمل بعير وانا به زعيم'),
(1669, 12, 73, 'قَالُوا تَاللّٰهِ لَقَدْ عَلِمْتُمْ مَا جِئْنَا لِنُفْسِدَ فِي الْاَرْضِ وَمَا كُنَّا سَارِق۪ينَ', 'Kalu tallahi lekad alimtum ma ci\'na li nufside fil ardı ve ma kunna sarikin.', 'Yusuf\'un kardeşleri: \"Vallahi buraya bozgunculuk yapmaya gelmedik; hırsız olmadığımızı da kesin olarak biliyorsunuz.\" dediler.', 'قالوا تالله لقد علمتم ما جينا لنفسد في الارض وما كنا سرقين'),
(1670, 12, 74, 'قَالُوا فَمَا جَزَٓاؤُ۬هُٓ اِنْ كُنْتُمْ كَاذِب۪ينَ', 'Kalu fe ma cezauhu in kuntum kazibin.', '\"Peki! Eğer yalan söylüyorsanız bunun cezasının ne olduğunu biliyor musunuz?\" dediler.', 'قالوا فما جزوه ان كنتم كذبين'),
(1671, 12, 75, 'قَالُوا جَزَٓاؤُ۬هُ مَنْ وُجِدَ ف۪ي رَحْلِه۪ فَهُوَ جَزَٓاؤُ۬هُۜ  كَذٰلِكَ نَجْزِي الظَّالِم۪ينَ', 'Kalu cezauhu men vucide fi rahlihi fe huve cezauh, kezalike necziz zalimin.', '\"Su kabı kimin yükünde bulunursa,  bunun cezası,  yük sahibinin kendisidir.[1] Biz haksızları böyle cezalandırırız.\" dediler.', 'قالوا جزوه من وجد في رحله فهو جزوه كذلك نجزي الظلمين'),
(1672, 12, 76, 'فَبَدَاَ بِاَوْعِيَتِهِمْ قَبْلَ وِعَٓاءِ اَخ۪يهِ ثُمَّ اسْتَخْرَجَهَا مِنْ وِعَٓاءِ اَخ۪يهِۜ كَذٰلِكَ كِدْنَا لِيُوسُفَۜ مَا كَانَ لِيَأْخُذَ اَخَاهُ ف۪ي د۪ينِ الْمَلِكِ اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُۜ نَرْفَعُ دَرَجَاتٍ مَنْ نَشَٓاءُۜ وَفَوْقَ كُلِّ ذ۪ي عِلْمٍ عَل۪يمٌ', 'Fe bedee bi ev\'ıyetihim kable viai ahihi, summestahreceha min viai ahih, kezalike kidna li yusuf, ma kane li ye\'huze ehahu fi dinil meliki, illa en yeşaallah, nerfeu derecatin men neşa\', ve fevka kulli zi ilmin alim.', 'Bunun üzerine,  kardeşinin yükünden önce diğerlerinin yükünü aramaya başladı. Sonra su kabını öz kardeşinin yükünden bulup çıkardı. İşte Yusuf için böyle bir tedbir aldık. Allah,  böyle dilemeseydi hükümdarın dinine[1] göre kardeşini alıkoyamayacaktı. Dilediğimizi derecelerle yükseltiriz. Her bilenin üstünde bir bilen vardır.', 'فبدا باوعيتهم قبل وعا اخيه ثم استخرجها من وعا اخيه كذلك كدنا ليوسف ما كان لياخذ اخاه في دين الملك الا ان يشا الله نرفع درجت من نشا وفوق كل ذي علم عليم'),
(1673, 12, 77, 'قَالُٓوا اِنْ يَسْرِقْ فَقَدْ سَرَقَ اَخٌ لَهُ مِنْ قَبْلُۚ فَاَسَرَّهَا يُوسُفُ ف۪ي نَفْسِه۪ وَلَمْ يُبْدِهَا لَهُمْ قَالَ اَنْتُمْ شَرٌّ مَكَاناًۚ وَاللّٰهُ اَعْلَمُ بِمَا تَصِفُونَ', 'Kalu in yesrık fe kad sereka ehun lehu min kabl, fe eserreha yusufu fi nefsihi ve lem yubdiha lehum kale entum şerrun mekana, vallahu a\'lemu bima tesifun.', '\"Eğer o çalmışsa,  zaten daha önce kardeşi de çalmıştı.\" dediler. Yusuf,  içinden geçeni onlara açmadı. Kendi kendine,  \"Asıl kötü olan sizlersiniz ve anlattığınız şeyin iç yüzünü Allah biliyor.\" dedi.', 'قالوا ان يسرق فقد سرق اخ له من قبل فاسرها يوسف في نفسه ولم يبدها لهم قال انتم شر مكانا والله اعلم بما تصفون'),
(1674, 12, 78, 'قَالُوا يَٓا اَيُّهَا الْعَز۪يزُ اِنَّ لَـهُٓ اَباً شَيْخاً كَب۪يراً فَخُذْ اَحَدَنَا مَكَانَهُۚ اِنَّا نَرٰيكَ مِنَ الْمُحْسِن۪ينَ', 'Kalu ya eyyuhel azizu inne lehu eben şeyhan kebiren fe huz ehadena mekaneh, inna nerake minel muhsinin.', 'Kardeşleri: \"Ey soylu Aziz! Emin ol ki,  bunun çok yaşlı bir babası var. Onun yerine bizden birini alıkoy. Senin iyilik edenlerden olduğunu görüyoruz.\" dediler.', 'قالوا يايها العزيز ان له ابا شيخا كبيرا فخذ احدنا مكانه انا نريك من المحسنين'),
(1675, 12, 79, 'قَالَ مَعَاذَ اللّٰهِ اَنْ نَأْخُذَ اِلَّا مَنْ وَجَدْنَا مَتَاعَنَا عِنْدَهُٓۙ اِنَّٓا اِذاً لَظَالِمُونَ۟', 'Kale maazallahi en ne\'huze illa men vecedna metaana indehu inna izen le zalimun.', '\"Eşyamızı yanında bulduğumuz kimseden başkasını alıkoymaktan Allah\'a sığınırız. Yoksa haksızlık etmiş oluruz.\" dedi.', 'قال معاذ الله ان ناخذ الا من وجدنا متعنا عنده انا اذا لظلمون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1676, 12, 80, 'فَلَمَّا اسْتَيْـَٔسُوا مِنْهُ خَلَصُوا نَجِياًّۜ قَالَ كَب۪يرُهُمْ اَلَمْ تَعْلَمُٓوا اَنَّ اَبَاكُمْ قَدْ اَخَذَ عَلَيْكُمْ مَوْثِقاً مِنَ اللّٰهِ وَمِنْ قَبْلُ مَا فَرَّطْتُمْ ف۪ي يُوسُفَۚ فَلَنْ اَبْرَحَ الْاَرْضَ حَتّٰى يَأْذَنَ ل۪ٓي اَب۪ٓي اَوْ يَحْكُمَ اللّٰهُ ل۪يۚ وَهُوَ خَيْرُ الْحَاكِم۪ينَ', 'Fe lemmestey\'esu minhu halesu neciyya, kale kebiruhum e lem ta\'lemu enne ebakum kad ehaze aleykum mevsikan minallahi ve min kablu ma ferrattum fi yusuf, fe len ebrahal arda hatta ye\'zene li ebi ev yahkumallahu li ve huve hayrul hakimin.', 'Ondan ümitlerini kesince,  kendi aralarında konuşmaya başladılar. Büyükleri: \"Babanızın Allah adına sizden söz aldığını ve daha önce Yusuf konusunda da sınırı aşmış olduğunuzu bilmez misiniz? Babam izin verinceye veya Allah hakkımda hüküm verinceye kadar buradan ayrılmam. O,  hüküm verenlerin en iyisidir.\" dedi.', 'فلما استيسوا منه خلصوا نجيا قال كبيرهم الم تعلموا ان اباكم قد اخذ عليكم موثقا من الله ومن قبل ما فرطتم في يوسف فلن ابرح الارض حتي ياذن لي ابي او يحكم الله لي وهو خير الحكمين'),
(1677, 12, 81, 'اِرْجِعُٓوا اِلٰٓى اَب۪يكُمْ فَقُولُوا يَٓا اَبَانَٓا اِنَّ ابْنَكَ سَرَقَۚ وَمَا شَهِدْنَٓا اِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَافِظ۪ينَ', 'Irciu ila ebikum fe kulu ya ebana innebneke serak, ve ma şehidna illa bima alimna ve ma kunna lil gaybi hafizin.', '\"Siz dönün! Babanıza deyin ki: Ey babamız! İnan ki oğlun hırsızlık yaptı. Biz bildiğimizden başka bir şeye tanıklık etmedik; işin iç yüzünü de bilmiyoruz.\"', 'ارجعوا الي ابيكم فقولوا يابانا ان ابنك سرق وما شهدنا الا بما علمنا وما كنا للغيب حفظين'),
(1678, 12, 82, 'وَسْـَٔلِ الْقَرْيَةَ الَّت۪ي كُنَّا ف۪يهَا وَالْع۪يرَ الَّت۪ٓي اَقْبَلْنَا ف۪يهَاۜ وَاِنَّا لَصَادِقُونَ', 'Ves\'elil karyetelleti kunna fiha vel irelleti akbelna fiha, ve inna le sadikun.', '\"Gittiğimiz kasabanın halkına ve beraberinde olduğumuz kervana da sor. Kuşkusuz biz doğru söylüyoruz.\"', 'وسل القرية التي كنا فيها والعير التي اقبلنا فيها وانا لصدقون'),
(1679, 12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ اَنْفُسُكُمْ اَمْراًۜ فَصَبْرٌ جَم۪يلٌۜ عَسَى اللّٰهُ اَنْ يَأْتِيَن۪ي بِهِمْ جَم۪يعاًۜ اِنَّهُ هُوَ الْعَل۪يمُ الْحَك۪يمُ', 'Kale bel sevvelet lekum enfusukum emra, fe sabrun cemil, asallahu en ye\'tiyeni bihim cemi\'a, innehu huvel alimul hakim.', '\"Hayır! Nefsiniz bu işte sizi aldatmış.[1] Artık bana düşen güzelce sabretmektir. Umarım ki Allah hepsini birden bana kavuşturur. Gerçek şu ki O,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.\"', 'قال بل سولت لكم انفسكم امرا فصبر جميل عسي الله ان ياتيني بهم جميعا انه هو العليم الحكيم'),
(1680, 12, 84, 'وَتَوَلّٰى عَنْهُمْ وَقَالَ يَٓا اَسَفٰى عَلٰى يُوسُفَ وَابْيَضَّتْ عَيْنَاهُ مِنَ الْحُزْنِ فَهُوَ كَظ۪يمٌ', 'Ve tevella anhum ve kale ya esefa ala yusufe vebyaddat aynahu minel huzni fe huve kezim.', 'Onlardan yüz çevirdi. Ve \"Vah! Vah! Yusuf\'um!\" dedi. Üzüntüden gözleri ağardı. Yutkundukça yutkunuyordu.', 'وتولي عنهم وقال ياسفي علي يوسف وابيضت عيناه من الحزن فهو كظيم'),
(1681, 12, 85, 'قَالُوا تَاللّٰهِ تَفْتَؤُ۬ا تَذْكُرُ يُوسُفَ حَتّٰى تَكُونَ حَرَضاً اَوْ تَكُونَ مِنَ الْهَالِك۪ينَ', 'Kalu tallahi tefteu tezkuru yusufe hatta tekune haradan ev tekune minel halikin.', '\"Yusuf\'u anmaya devam edersen,  vallahi sonunda üzüntünden ya hasta olacaksın veya öleceksin.\" dediler.', 'قالوا تالله تفتوا تذكر يوسف حتي تكون حرضا او تكون من الهلكين'),
(1682, 12, 86, 'قَالَ اِنَّـمَٓا اَشْكُوا بَثّ۪ي وَحُزْن۪ٓي اِلَى اللّٰهِ وَاَعْلَمُ مِنَ اللّٰهِ مَا لَا تَعْلَمُونَ', 'Kale innema eşku bessi ve huzni ilallahi ve a\'lemu inallahi ma la ta\'lemun.', '\"Gönlümden geçenleri ve kederimi yalnızca Allah\'a arz ediyorum. Ve Allah tarafından bilmeyeceğiniz şeyleri bilirim.\" dedi.', 'قال انما اشكوا بثي وحزني الي الله واعلم من الله ما لا تعلمون'),
(1683, 12, 87, 'يَا بَنِيَّ اذْهَبُوا فَتَحَسَّسُوا مِنْ يُوسُفَ وَاَخ۪يهِ وَلَا تَايْـَٔسُوا مِنْ رَوْحِ اللّٰهِۜ اِنَّهُ لَا يَايْـَٔسُ مِنْ رَوْحِ اللّٰهِ اِلَّا الْقَوْمُ الْكَافِرُونَ', 'Ya beniyyezhebu fe tehassesu min yusufe ve ehihi ve la te\'yesu min revhillah, innehu la ye\'yesu min revhillahi illel kavmul kafirun.', '\"Ey oğullarım! Gidin Yusuf\'u ve kardeşini araştırın. Allah\'ın rahmetinden umut kesmeyin; çünkü Kafir bir halktan başkası O\'nun rahmetinden umudunu kesmez.\"', 'يبني اذهبوا فتحسسوا من يوسف واخيه ولا تايسوا من روح الله انه لا يايس من روح الله الا القوم الكفرون'),
(1684, 12, 88, 'فَلَمَّا دَخَلُوا عَلَيْهِ قَالُوا يَٓا اَيُّهَا الْعَز۪يزُ مَسَّنَا وَاَهْلَنَا الضُّرُّ وَجِئْنَا بِبِضَاعَةٍ مُزْجٰيةٍ فَاَوْفِ لَنَا الْكَيْلَ وَتَصَدَّقْ عَلَيْنَاۜ اِنَّ اللّٰهَ يَجْزِي الْمُتَصَدِّق۪ينَ', 'Fe lemma dehalu aleyhi kalu ya eyyuhel azizu messena ve ehlened durru ve ci\'na bi bidaatin muzcatin fe evfi lenel keyle ve tesaddak aleyna, innallahe yeczil mutesaddikin.', 'Sonra onun yanına girdiklerinde: \"Ey saygıdeğer Aziz![1] Bize ve ailemize darlık dokundu. Az bir sermaye ile geldik. Bize tam ölçek ver ve bize tasaddukta[2] bulun. Kuşkusuz,  Allah tasadduk edenlerin ödülünü verir.\" dediler.', 'فلما دخلوا عليه قالوا يايها العزيز مسنا واهلنا الضر وجينا ببضعة مزجية فاوف لنا الكيل وتصدق علينا ان الله يجزي المتصدقين'),
(1685, 12, 89, 'قَالَ هَلْ عَلِمْتُمْ مَا فَعَلْتُمْ بِيُوسُفَ وَاَخ۪يهِ اِذْ اَنْتُمْ جَاهِلُونَ', 'Kale hel alimtum ma fealtum bi yusufe ve ahihi iz entum cahilun.', '\"Yusuf\'a ve kardeşine cahilce ne yaptığınızı biliyor musunuz?\" dedi.', 'قال هل علمتم ما فعلتم بيوسف واخيه اذ انتم جهلون'),
(1686, 12, 90, 'قَالُٓوا ءَاِنَّكَ لَاَنْتَ يُوسُفُۜ قَالَ اَنَا۬ يُوسُفُ وَهٰذَٓا اَخ۪يۘ قَدْ مَنَّ اللّٰهُ عَلَيْنَاۜ اِنَّهُ مَنْ يَتَّقِ وَيَصْبِرْ فَاِنَّ اللّٰهَ لَا يُض۪يعُ اَجْرَ الْمُحْسِن۪ينَ', 'Kalu e inneke le ente yusuf, kale ene yusufu ve haza ahi kad mennallahu aleyna, innehu men yettekı ve yasbir fe innallahe la yudi\'u ecrel muhsinin.', '\"Yoksa sen Yusuf musun?\" dediler. \"Ben Yusuf\'um,  bu da kardeşim.\" dedi. \"Doğrusu,  Allah bizi nimetlendirdi. Çünkü kim takvalı olur ve sabrederse,  o zaman Allah,  kesinlikle iyilerin yaptığını karşılıksız bırakmaz.\"', 'قالوا انك لانت يوسف قال انا يوسف وهذا اخي قد من الله علينا انه من يتق ويصبر فان الله لا يضيع اجر المحسنين'),
(1687, 12, 91, 'قَالُوا تَاللّٰهِ لَقَدْ اٰثَرَكَ اللّٰهُ عَلَيْنَا وَاِنْ كُنَّا لَخَاطِـ۪ٔينَ', 'Kalu tallahi lekad aserekellahu aleyna ve in kunna le hatıin.', 'Dediler ki: \"Allah\'a yemin olsun ki,  Allah,  seni bize üstün kıldı. Ve biz gerçekten yanlış yapmışız.\"', 'قالوا تالله لقد اثرك الله علينا وان كنا لخطين'),
(1688, 12, 92, 'قَالَ لَا تَثْر۪يبَ عَلَيْكُمُ الْيَوْمَۜ يَغْفِرُ اللّٰهُ لَكُمْۘ وَهُوَ اَرْحَمُ الرَّاحِم۪ينَ', 'Kale la tesribe aleykumul yevm, yagfirullahu lekum ve huve erhamur rahimin.', 'Yusuf: \"Bugün,  size bir kınama yoktur. Allah,  sizi bağışlayıcılığıyla bağışlasın. O,  merhametlilerin en merhametlisidir.\" dedi.', 'قال لا تثريب عليكم اليوم يغفر الله لكم وهو ارحم الرحمين'),
(1689, 12, 93, 'اِذْهَبُوا بِقَم۪يص۪ي هٰذَا فَاَلْقُوهُ عَلٰى وَجْهِ اَب۪ي يَأْتِ بَص۪يراًۚ وَأْتُون۪ي بِاَهْلِكُمْ اَجْمَع۪ينَ۟', 'Yezhebu bikamisi haza fe elkuhu ala vechi ebi ye\'ti basira, ve\'tuni bi ehlikum ecma\'in.', '\"Şu gömleğimi götürün; babamın yüzüne koyun. Görmeye başlayacaktır. Ailenizin tamamını bana getirin.\" dedi.', 'اذهبوا بقميصي هذا فالقوه علي وجه ابي يات بصيرا واتوني باهلكم اجمعين'),
(1690, 12, 94, 'وَلَمَّا فَصَلَتِ الْع۪يرُ قَالَ اَبُوهُمْ اِنّ۪ي لَاَجِدُ ر۪يحَ يُوسُفَ لَوْلَٓا اَنْ تُفَنِّدُونِ', 'Ve lemma fasalatil\'iru kale ebuhum inni le ecidu riha yusufe lev la en tufennidun.', 'Kafile ayrıldığında babaları: \"Eğer bunamış demezseniz,  doğrusu ben gerçekten Yusuf\'un kokusunu hissediyorum.\" dedi.', 'ولما فصلت العير قال ابوهم اني لاجد ريح يوسف لولا ان تفندون'),
(1691, 12, 95, 'قَالُوا تَاللّٰهِ اِنَّكَ لَف۪ي ضَلَالِكَ الْقَد۪يمِ', 'Kalu tallahi inneke le fi dalalikel kadim.', '\"Allah\'a yemin olsun ki,  sen hala eski şaşkınlığına devam ediyorsun.\" dediler.', 'قالوا تالله انك لفي ضللك القديم'),
(1692, 12, 96, 'فَلَمَّٓا اَنْ جَٓاءَ الْبَش۪يرُ اَلْقٰيهُ عَلٰى وَجْهِه۪ فَارْتَدَّ بَص۪يراًۚ قَالَ اَلَمْ اَقُلْ لَكُمْ اِنّ۪ٓي اَعْلَمُ مِنَ اللّٰهِ مَا لَا تَعْلَمُونَ', 'Fe lemma en cael beşiru elkahu ala vechihi fertedde basira, kale e lem ekul lekum inni a\'lemu minallahi ma la ta\'lemun.', 'Haberci geldiği zaman,  onu yüzüne koyunca gözü hemen görmeye başladı. \"Ben size demedim mi,  ben Allah\'tan sizin bilmediğiniz şeyleri bilirim.\" dedi.', 'فلما ان جا البشير القيه علي وجهه فارتد بصيرا قال الم اقل لكم اني اعلم من الله ما لا تعلمون'),
(1693, 12, 97, 'قَالُوا يَٓا اَبَانَا اسْتَغْفِرْ لَنَا ذُنُوبَنَٓا اِنَّا كُنَّا خَاطِـ۪ٔينَ', 'Kalu ya ebanestagfir lena zunubena inna kunna hatıin.', '\"Ey babamız! Suçlarımız için bağışlama dile. Gerçekten bizler yanlış yaptık.\" dediler.', 'قالوا يابانا استغفر لنا ذنوبنا انا كنا خطين'),
(1694, 12, 98, 'قَالَ سَوْفَ اَسْتَغْفِرُ لَكُمْ رَبّ۪يۜ اِنَّهُ هُوَ الْغَفُورُ الرَّح۪يمُ', 'Kale sevfe estagfiru lekum rabbi, innehu huvel gafurur rahim.', '\"Sizin için Rabbimden bağışlanma dileyeceğim. Kuşkusuz O; Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.\"', 'قال سوف استغفر لكم ربي انه هو الغفور الرحيم'),
(1695, 12, 99, 'فَلَمَّا دَخَلُوا عَلٰى يُوسُفَ اٰوٰٓى اِلَيْهِ اَبَوَيْهِ وَقَالَ ادْخُلُوا مِصْرَ اِنْ شَٓاءَ اللّٰهُ اٰمِن۪ينَۜ', 'Fe lemma dehalu ala yusufe ava ileyhi ebeveyhi ve kaledhulu mısra in şaallahu aminin.', 'Ne zaman ki Yusuf\'un yanına girdiler,  anne ve babasını kucakladı ve \"Allah\'ın izni[1] ile güven içinde Mısır\'a girin.\" dedi.', 'فلما دخلوا علي يوسف اوي اليه ابويه وقال ادخلوا مصر ان شا الله امنين'),
(1696, 12, 100, 'وَرَفَعَ اَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّداًۚ وَقَالَ يَٓا اَبَتِ هٰذَا تَأْو۪يلُ رُءْيَايَ مِنْ قَبْلُۘ قَدْ جَعَلَهَا رَبّ۪ي حَقاًّۜ وَقَدْ اَحْسَنَ ب۪ٓي اِذْ اَخْرَجَن۪ي مِنَ السِّجْنِ وَجَٓاءَ بِكُمْ مِنَ الْبَدْوِ مِنْ بَعْدِ اَنْ نَزَغَ الشَّيْطَانُ بَيْن۪ي وَبَيْنَ اِخْوَت۪يۜ اِنَّ رَبّ۪ي لَط۪يفٌ لِمَا يَشَٓاءُۜ اِنَّهُ هُوَ الْعَل۪يمُ الْحَك۪يمُ', 'Ve refea ebeveyhi alel arşı ve harru lehu succeda, ve kale ya ebeti haza te\'vilu ru\'yaye min kablu kad cealeha rabbi hakka, ve kad ahsene bi iz ahreceni mines sicni ve cae bikum minel bedvi min ba\'di en nezegaş şeytanu beyni ve beyne ıhveti, inne rabbi latifun lima yeşa\' innehu huvel alimul hakim.', 'Yusuf,  anne ve babasını makamına çıkardı. Hepsi onun makamına saygı ile eğildiler.[1] Yusuf: \"Ey babacığım! Bu durum,  daha önceki rüyamın gerçekleşmesidir.[2] Rabb\'im onu gerçek kıldı. Ve gerçekten bana ihsanda bulundu. Çünkü beni zindandan çıkardı. Şeytan benimle kardeşlerimin arasını açtıktan sonra,  O sizi çölden getirdi. Benim Rabb\'im dilediğine lütuf sahibidir. Gerçek şu ki: O,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.\"', 'ورفع ابويه علي العرش وخروا له سجدا وقال يابت هذا تاويل ريي من قبل قد جعلها ربي حقا وقد احسن بي اذ اخرجني من السجن وجا بكم من البدو من بعد ان نزغ الشيطن بيني وبين اخوتي ان ربي لطيف لما يشا انه هو العليم الحكيم'),
(1697, 12, 101, 'رَبِّ قَدْ اٰتَيْتَن۪ي مِنَ الْمُلْكِ وَعَلَّمْتَن۪ي مِنْ تَأْو۪يلِ الْاَحَاد۪يثِۚ فَاطِرَ السَّمٰوَاتِ وَالْاَرْضِ اَنْتَ وَلِيّ۪  فِي الدُّنْيَا وَالْاٰخِرَةِۚ تَوَفَّن۪ي مُسْلِماً وَاَلْحِقْن۪ي بِالصَّالِح۪ينَ', 'Rabbi kad ateyteni minel mulki ve allemteni min te\'vilil ehadis, fatıras semavati vel ardı ente veliyyi fid dunya Vel ahıreh, teveffeni muslimen ve elhıkni bis salihin.', '\"Rabbim! Bana yöneticilik verdin ve bana hadislerin[1] yorumunu öğrettin. Ey göklere ve yere yasalarını[2] koyan! Sen,  dünyada da ahirette de velimsin[3]; canımı müslüman[4] olarak al ve beni salihlerin[5] arasına kat.\"', 'رب قد اتيتني من الملك وعلمتني من تاويل الاحاديث فاطر السموت والارض انت ولي في الدنيا والاخرة توفني مسلما والحقني بالصلحين'),
(1698, 12, 102, 'ذٰلِكَ مِنْ اَنْبَٓاءِ الْغَيْبِ نُوح۪يهِ اِلَيْكَۚ وَمَا كُنْتَ لَدَيْهِمْ اِذْ اَجْمَعُٓوا اَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'Zalike min enbail gaybi nuhihi ileyk, ve ma kunte ledeyhim iz ecmau emrehum ve hum yemkurun.', 'İşte bu sana vahiyle bildirdiğimiz; gaybi[1] haberlerdendir. Yusuf\'un kardeşleri bir araya gelip,  tuzak kurmak için plan yaparlarken sen yanlarında değildin.', 'ذلك من انبا الغيب نوحيه اليك وما كنت لديهم اذ اجمعوا امرهم وهم يمكرون'),
(1699, 12, 103, 'وَمَٓا اَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِن۪ينَ', 'Ve ma ekserun nasi ve lev haraste bi mu\'minin.', 'Ama ne kadar çok istesen de insanların çoğu inanacak değildir.', 'وما اكثر الناس ولو حرصت بمومنين'),
(1700, 12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ اَجْرٍۜ اِنْ هُوَ اِلَّا ذِكْرٌ لِلْعَالَم۪ينَ۟', 'Ve ma tes\'eluhum aleyhi min ecr, in huve illa zikrun lil alemin.', 'Ve sen buna karşılık[1] onlardan bir ücret istemiyorsun. O,  bütün bir insanlık için ancak bir zikirdir.[2]', 'وما تسلهم عليه من اجر ان هو الا ذكر للعلمين'),
(1701, 12, 105, 'وَكَاَيِّنْ مِنْ اٰيَةٍ فِي السَّمٰوَاتِ وَالْاَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'Ve keeyyin min ayetin fis semavati vel ardı yemurrune aleyha ve hum anha mu\'ridun.', 'Göklerde ve yerde nice ayetler[1] var,  ancak onlar yine de bunları umursamadan görmezden gelirler.', 'وكاين من اية في السموت والارض يمرون عليها وهم عنها معرضون'),
(1702, 12, 106, 'وَمَا يُؤْمِنُ اَكْثَرُهُمْ بِاللّٰهِ اِلَّا وَهُمْ مُشْرِكُونَ', 'Ve ma yu\'minu ekseruhum billahi illa ve hum muşrikun.', 'Onların çoğu,  şirk koşmadan[1] Allah\'a inanmazlar.', 'وما يومن اكثرهم بالله الا وهم مشركون'),
(1703, 12, 107, 'اَفَاَمِنُٓوا اَنْ تَأْتِيَهُمْ غَاشِيَةٌ مِنْ عَذَابِ اللّٰهِ اَوْ تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'E fe eminu en te\'tiyehum gaşiyetun min azabillahi ev te\'tiyehumus saatu bagteten ve hum la yeş\'urun.', 'Yoksa onlar,  hiç beklemedikleri bir anda Allah\'ın her şeyi kaplayan azabının gelmesinden veya o saatin[1] onlara,  farkında olmadan ansızın gelmesinden güvende midirler?', 'افامنوا ان تاتيهم غشية من عذاب الله او تاتيهم الساعة بغتة وهم لا يشعرون'),
(1704, 12, 108, 'قُلْ هٰذِه۪ سَب۪يل۪ٓي اَدْعُٓوا اِلَى اللّٰهِ عَلٰى بَص۪يرَةٍ اَنَا۬ وَمَنِ اتَّبَعَن۪يۜ وَسُبْحَانَ اللّٰهِ وَمَٓا اَنَا۬ مِنَ الْمُشْرِك۪ينَ', 'Kul hazihi sebili ed\'u ilallahi ala basiretin ene ve menittebeani, ve subhanallahi ve ma ene minel muşrikin.', 'De ki: \"Benim yolum,  basiret[1] üzere Allah\'a davet etme yoludur. Ve bana uyanların yolu da. Allah\'ı tenzih[2] ederim. Ve ben,  müşriklerden değilim.\"', 'قل هذه سبيلي ادعوا الي الله علي بصيرة انا ومن اتبعني وسبحن الله وما انا من المشركين'),
(1705, 12, 109, 'وَمَٓا اَرْسَلْنَا مِنْ قَبْلِكَ اِلَّا رِجَالاً نُوح۪ٓي اِلَيْهِمْ مِنْ اَهْلِ الْقُرٰىۜ اَفَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ وَلَدَارُ الْاٰخِرَةِ خَيْرٌ لِلَّذ۪ينَ اتَّقَوْاۜ اَفَلَا تَعْقِلُونَ', 'Ve ma erselna min kablike illa ricalen nuhi ileyhim min ehlil kura, e fe lem yesiru fil ardı fe yanzuru keyfe kane akıbetullezine min kablihim, ve le darul ahıreti hayrun lillezinettekav, e fe la ta\'kılun.', 'Senden önce gönderdiğimiz[1] ve kendilerine vahyettiğimiz kimseler de şehirlerde yaşayanlardan[2] başkası değildi. Hem onlar,  yeryüzünde gezip dolaşmazlar mı? Baksalar ya! Kendilerinden öncekilerin sonlarının nasıl olduğuna! Takva sahipleri için Ahiret Yurdu daha hayırlıdır. Hala aklınızı kullanmayacak mısınız?', 'وما ارسلنا من قبلك الا رجالا نوحي اليهم من اهل القري افلم يسيروا في الارض فينظروا كيف كان عقبة الذين من قبلهم ولدار الاخرة خير للذين اتقوا افلا تعقلون'),
(1706, 12, 110, 'حَتّٰٓى اِذَا اسْتَيْـَٔسَ الرُّسُلُ وَظَنُّٓوا اَنَّهُمْ قَدْ كُذِبُوا جَٓاءَهُمْ نَصْرُنَاۙ فَنُجِّيَ مَنْ نَشَٓاءُۜ وَلَا يُرَدُّ بَأْسُنَا عَنِ الْقَوْمِ الْمُجْرِم۪ينَ', 'Hatta izestey\'eser rusulu ve zannu ennehum kad kuzibu caehum nasruna fe nucciye men neşa\', ve la yureddu be\'suna anil kavmil mucrimin.', 'Ne zaman ki resuller,  yalanlanmalarının bitmeyeceği kanaatine varıp ümitlerini iyice yitirince,  onlara yardımımız ulaştı. Sonra da dilediklerimiz kurtarıldı. Azabımız,  suçlu halklardan geri çevrilmez.', 'حتي اذا استيس الرسل وظنوا انهم قد كذبوا جاهم نصرنا فنجي من نشا ولا يرد باسنا عن القوم المجرمين'),
(1707, 12, 111, 'لَقَدْ كَانَ ف۪ي قَصَصِهِمْ عِبْرَةٌ لِاُو۬لِي الْاَلْبَابِۜ مَا كَانَ حَد۪يثاً يُفْتَرٰى وَلٰكِنْ تَصْد۪يقَ الَّذ۪ي بَيْنَ يَدَيْهِ وَتَفْص۪يلَ كُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ', 'Lekad kane fi kasasıhim ibretun li ulil elbab, ma kane hadisen yuftera ve lakin tasdikallezi beyne yedeyhi ve tafsile kulli şey\'in ve huden ve rahmeten li kavmin yu\'minun.', 'Ant olsun ki; onların kıssalarında[1] sağlıklı düşünen temiz akıl sahipleri için ibretler,  alınacak dersler vardır. Bu[2] uydurulan bir hadis[3] değildir. Bilakis,  kendinden öncekilerini onaylayan ve her şeyi ayrıntılı olarak açıklayan ve aynı zamanda inanan halklar için bir yol gösterici ve bir rahmettir', 'لقد كان في قصصهم عبرة لاولي الالبب ما كان حديثا يفتري ولكن تصديق الذي بين يديه وتفصيل كل شي وهدي ورحمة لقوم يومنون'),
(1708, 13, 1, 'الٓمٓرٰ ۠تِلْكَ اٰيَاتُ الْكِتَابِۜ وَالَّـذ۪ٓي اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَ الْحَقُّ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ', 'Elif lam mim ra tilke ayatul kitab, vellezi unzile ileyke min rabbikel hakku ve lakinne ekseren nasi la yu\'minun.', 'Elif,  Lam,  Mim,  Ra. Bunlar Kitap\'ın ayetleridir. O,  sana Rabb\'inden indirilen gerçeğin ta kendisidir. Ne var ki insanların çoğu ona inanmazlar.', 'المر تلك ايت الكتب والذي انزل اليك من ربك الحق ولكن اكثر الناس لا يومنون'),
(1709, 13, 2, 'اَللّٰهُ الَّذ۪ي رَفَعَ السَّمٰوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ اسْتَوٰى عَلَى الْعَرْشِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَۜ كُلٌّ يَجْر۪ي لِاَجَلٍ مُسَمًّىۜ يُدَبِّرُ الْاَمْرَ يُفَصِّلُ الْاٰيَاتِ لَعَلَّكُمْ بِلِقَٓاءِ رَبِّكُمْ تُوقِنُونَ', 'Allahullezi refeas semavati bi gayri amedin terevneha summesteva alel arşı ve sehhareş şemse vel kamer, kullun yecri li ecelin musemma, yudebbirul emre yufassılul ayati leallekum bi likai rabbikum tukınun.', 'Bir dayanak olmaksızın -görmekte olduğunuz gibi- gökleri yükselten Allah\'tır. Sonra,  mutlak gücüyle Güneş\'i ve Ay\'ı koyduğu yasalara bağlı kıldı. Hepsi,  adı konmuş bir ecele[1] doğru akıp gitmektedir. İşleri düzenleyip idare eden O\'dur. Âyetleri ayrıntılı olarak açıklamaktadır ki,  belki Rabb\'inize kavuşacağınıza kesin olarak inanırsınız.', 'الله الذي رفع السموت بغير عمد ترونها ثم استوي علي العرش وسخر الشمس والقمر كل يجري لاجل مسمي يدبر الامر يفصل الايت لعلكم بلقا ربكم توقنون'),
(1710, 13, 3, 'وَهُوَ الَّذ۪ي مَدَّ الْاَرْضَ وَجَعَلَ ف۪يهَا رَوَاسِيَ وَاَنْهَاراًۜ وَمِنْ كُلِّ الثَّمَرَاتِ جَعَلَ ف۪يهَا زَوْجَيْنِ اثْنَيْنِ يُغْشِي الَّيْلَ النَّهَارَۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ', 'Ve huvellezi meddel arda ve ceale fiha revasiye ve enhara, ve min kullis semerati ceale fiha zevceynisneyni yugşil leylen nehar, inne fi zalike le ayatin li kavmin yetefekkerun.', 'Ve O ki,  yeryüzünü uzattı[1] ve orada ağır baskılar ve nehirler yaptı. Orada meyvelerin hepsinden ikili eşler yaptı[2]. Gündüzü geceyle örttü. Bunda tefekkür[3] eden bir halk için ayetler[4]vardır.', 'وهو الذي مد الارض وجعل فيها روسي وانهرا ومن كل الثمرت جعل فيها زوجين اثنين يغشي اليل النهار ان في ذلك لايت لقوم يتفكرون'),
(1711, 13, 4, 'وَفِي الْاَرْضِ قِطَعٌ مُتَجَاوِرَاتٌ وَجَنَّاتٌ مِنْ اَعْنَابٍ وَزَرْعٌ وَنَخ۪يلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقٰى بِمَٓاءٍ وَاحِدٍ۠ وَنُفَضِّلُ بَعْضَهَا عَلٰى بَعْضٍ فِي الْاُكُلِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَعْقِلُونَ', 'Ve fil ardı kıtaun mutecaviratun ve cennatun min a\'nabin ve zer\'un ve nahilun sınvanun ve gayru sınvanin yuska bi main vahid, ve nufaddılu ba\'deha ala ba\'dın fil ukul, inne fi zalike le ayatin li kavmin ya\'kılun.', 'Yeryüzünde aynı su ile sulanan ve birbirine bitişik toprak parçalarında,  üzümlerden bahçeler,  ekinler,  çatallı çatalsız hurma ağaçları vardır. Ve Biz,  onları yenmesinde[1] farklı farklı kılıyoruz. Aklını kullanan bir toplum için bunda ayetler[2] vardır.', 'وفي الارض قطع متجورت وجنت من اعنب وزرع ونخيل صنوان وغير صنوان يسقي بما وحد ونفضل بعضها علي بعض في الاكل ان في ذلك لايت لقوم يعقلون'),
(1712, 13, 5, 'وَاِنْ تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ ءَاِذَا كُنَّا تُرَاباً ءَاِنَّا لَف۪ي خَلْقٍ جَد۪يدٍۜ اُو۬لٰٓئِكَ الَّذ۪ينَ كَفَرُوا بِرَبِّهِمْۚ وَاُو۬لٰٓئِكَ الْاَغْلَالُ ف۪ٓي اَعْنَاقِهِمْۚ وَاُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Ve in ta\'ceb fe acebun kavluhum e iza kunna turaben e inna le fi halkın cedid, ulaikellezine keferu bi rabbihim, ve ulaikel aglalu fi a\'nakıhim, ve ulaike ashabun nar, hum fiha halidun.', 'Eğer şaşırıyorsan,  asıl şaşılacak şey,  onların,  \"Biz toprak olduğumuz zaman mı,  gerçekten biz bir kez daha mı yaratılacağız?\" sözleridir. İşte onlar,  Rabb\'lerini küfreden[1] kimselerdir. İşte onlar,  boyunlarında halkalar olanlardır. Ve işte onlar,  ateş ehlidir. Onlar,  orada sürekli kalacaklardır.', 'وان تعجب فعجب قولهم اذا كنا تربا انا لفي خلق جديد اوليك الذين كفروا بربهم واوليك الاغلل في اعناقهم واوليك اصحب النار هم فيها خلدون'),
(1713, 13, 6, 'وَيَسْتَعْجِلُونَكَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ وَقَدْ خَلَتْ مِنْ قَبْلِهِمُ الْمَثُلَاتُۜ وَاِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِلنَّاسِ عَلٰى ظُلْمِهِمْۚ وَاِنَّ رَبَّكَ لَشَد۪يدُ الْعِقَابِ', 'Ve yesta\'ciluneke bis seyyieti kablel haseneti ve kad halet min kablihimul mesulat, ve inne rabbeke lezu magfiretin lin nasi ala zulmihim, ve inne rabbeke le şedidul ıkab.', 'Ve senden,  iyilikten önce kötülüğü çabuklaştırmanı istiyorlar.[1] Oysaki kendilerinden önce nice ibret alınacak cezalar yaşandı. Rabb\'in,  haksızlıklarına rağmen insanlar için gerçekten bağışlayıcı olandır. Ve elbette ki; Rabb\'in,  Azabı da Çok Şiddetli Olan\'dır.', 'ويستعجلونك بالسيية قبل الحسنة وقد خلت من قبلهم المثلت وان ربك لذو مغفرة للناس علي ظلمهم وان ربك لشديد العقاب'),
(1714, 13, 7, 'وَيَقُولُ الَّذ۪ينَ كَفَرُوا لَوْلَٓا اُنْزِلَ عَلَيْهِ اٰيَةٌ مِنْ رَبِّه۪ۜ اِنَّـمَٓا اَنْتَ مُنْذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ۟', 'Ve yekulullezine keferu lev la unzile aleyhi ayetun min rabbih, innema ente munzirun ve li kulli kavmin had.', 'Kafirler[1],  \"Ona Rabb\'inden bir ayet[2] indirilmeli değil miydi?\" diyorlar. Sen,  yalnızca bir uyarıcısın. Ve her halkın bir yol göstericisi vardır.', 'ويقول الذين كفروا لولا انزل عليه اية من ربه انما انت منذر ولكل قوم هاد'),
(1715, 13, 8, 'اَللّٰهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ اُنْثٰى وَمَا تَغ۪يضُ الْاَرْحَامُ وَمَا تَزْدَادُۜ وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ', 'Allahu ya\'lemu ma tahmilu kullu unsa ve ma tegidul erhamu ve ma tezdad, ve kullu şey\'in indehu bi mıkdar.', 'Allah,  her dişinin neye gebe olduğunu,  rahimlerin neyi azalttığını ve neyi artırdığını bilir. O\'nun katında her şey koyduğu düzene göre işlemektedir.', 'الله يعلم ما تحمل كل انثي وما تغيض الارحام وما تزداد وكل شي عنده بمقدار'),
(1716, 13, 9, 'عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَب۪يرُ الْمُتَعَالِ', 'Alimul gaybi veş şehadetil kebirul muteal.', 'Görüneni ve görünemeyeni bilendir. O,  Mutlak Büyük\'tür ve Her Şeyden Yüce\'dir.', 'علم الغيب والشهدة الكبير المتعال'),
(1717, 13, 10, 'سَوَٓاءٌ مِنْكُمْ مَنْ اَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِه۪ وَمَنْ هُوَ مُسْتَخْفٍ بِالَّيْلِ وَسَارِبٌ بِالنَّهَارِ', 'Sevaun minkum men eserrel kavle ve men cehere bihi ve men huve mustahfin bil leyli ve saribun bin nehar.', 'Sizden,  düşüncesini açıklayan da gizleyen de bir şeyi gece yapan da gündüz yapan da aynıdır.[1]', 'سوا منكم من اسر القول ومن جهر به ومن هو مستخف باليل وسارب بالنهار'),
(1718, 13, 11, 'لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِه۪ يَحْفَظُونَهُ مِنْ اَمْرِ اللّٰهِۜ اِنَّ اللّٰهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتّٰى يُغَيِّرُوا مَا بِاَنْفُسِهِمْۜ وَاِذَٓا اَرَادَ اللّٰهُ بِقَوْمٍ سُٓوءاً فَلَا مَرَدَّ لَهُۚ وَمَا لَهُمْ مِنْ دُونِه۪ مِنْ وَالٍ', 'Lehu muakkibatun min beyni yedeyhi ve min halfihi yahfezunehu min emrillah, innallahe la yugayyiru ma bi kavmin hatta yugayyiru ma bi enfusihim, ve iza eradallahu bi kavmin suen fe la meredde leh, ve ma lehum min dunihi min val.', 'Onu her şeyi ile izleyenler vardır. Allah\'ın işinden olarak onu gözetirler. Kuşkusuz bir halk kendi durumunu değiştirmedikçe,  Allah onların durumunu değiştirmez.[1] Ve Allah,  kötü bir halka ceza vermeyi istediğinde[2] hiçbir güç bunu engelleyemez. Onlar için O\'ndan başka bir veli[3] yoktur.', 'له معقبت من بين يديه ومن خلفه يحفظونه من امر الله ان الله لا يغير ما بقوم حتي يغيروا ما بانفسهم واذا اراد الله بقوم سوا فلا مرد له وما لهم من دونه من وال'),
(1719, 13, 12, 'هُوَ الَّذ۪ي يُر۪يكُمُ الْبَرْقَ خَوْفاً وَطَمَعاً وَيُنْشِئُ السَّحَابَ الثِّقَالَۚ', 'Huveellezi yurikumul berka havfen ve tamean ve yunşius sehabes sikal.', 'O,  korkutan şimşeği gösteren ve umut olarak yağmur yüklü bulutları meydana getirendir.', 'هو الذي يريكم البرق خوفا وطمعا وينشي السحاب الثقال'),
(1720, 13, 13, 'وَيُسَبِّحُ الرَّعْدُ بِحَمْدِه۪ وَالْمَلٰٓئِكَةُ مِنْ خ۪يفَتِه۪ۚ وَيُرْسِلُ الصَّوَاعِقَ فَيُص۪يبُ بِهَا مَنْ يَشَٓاءُ وَهُمْ يُجَادِلُونَ فِي اللّٰهِۚ وَهُوَ شَد۪يدُ الْمِحَالِۜ', 'Ve yusebbihur ra\'du bi hamdihi vel melaiketu min hifetih, ve yursilus savaıka fe yusibu biha men ye?au ve hum yucadilune fillah, ve huve ?edidul mihal.', 'Gök gürültüsü övgüsüyle,  melekler de ürpertisiyle O\'nu tesbih[1] ederler. O,  yıldırımlar gönderir ve onunla dilediğini çarpar. Onlar ise Allah hakkında tartışıp duruyorlar. Ve O,  karşı konulamaz pek çetin bir güç sahibidir.', 'ويسبح الرعد بحمده والمليكة من خيفته ويرسل الصوعق فيصيب بها من يشا وهم يجدلون في الله وهو شديد المحال'),
(1721, 13, 14, 'لَهُ دَعْوَةُ الْحَقِّۜ وَالَّذ۪ينَ يَدْعُونَ مِنْ دُونِه۪ لَا يَسْتَج۪يبُونَ لَهُمْ بِشَيْءٍ اِلَّا كَبَاسِطِ كَفَّيْهِ اِلَى الْمَٓاءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَالِغِه۪ۜ وَمَا دُعَٓاءُ الْكَافِر۪ينَ اِلَّا ف۪ي ضَلَالٍ', 'Lehu da\'vetul hakk, vellezine yed\'une min dunihi la yestecibune lehum bi şey\'in illa kebasitı keffeyhi ilel mai li yebluga fahu ve ma huve bi baligıh, ve ma duaul kafirine illa fi dalal.', 'Gerçek olan dua ancak O\'na yapılandır. Onların,  O\'nun yanı sıra istekte bulundukları varlıklar[1],  hiçbir şekilde onlara karşılık veremezler. Onlar,  elleri suya ulaşmadığı halde,  ağızlarına su kendiliğinden gelsin diye iki avucunu açanlar gibidir. Kafirlerin duası sapkıncadır.', 'له دعوة الحق والذين يدعون من دونه لا يستجيبون لهم بشي الا كبسط كفيه الي الما ليبلغ فاه وما هو ببلغه وما دعا الكفرين الا في ضلل'),
(1722, 13, 15, 'وَلِلّٰهِ يَسْجُدُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِ طَوْعاً وَكَرْهاً وَظِلَالُهُمْ بِالْغُدُوِّ وَالْاٰصَالِ', 'Ve lillahi yescudu men fis semavati vel ardı tav\'an ve kerhen ve zilaluhum bil guduvvi vel asal.', 'Göklerde ve yerde olanlar ve gölgeleri,  isteyerek veya istemeyerek,  sabah akşam[1] Allah\'a secde[2] ederler.', 'ولله يسجد من في السموت والارض طوعا وكرها وظللهم بالغدو والاصال'),
(1723, 13, 16, 'قُلْ مَنْ رَبُّ السَّمٰوَاتِ وَالْاَرْضِۜ  قُلِ اللّٰهُۜ  قُلْ اَفَاتَّخَذْتُمْ مِنْ دُونِه۪ٓ اَوْلِيَٓاءَ لَا يَمْلِكُونَ لِاَنْفُسِهِمْ نَفْعاً وَلَا ضَراًّۜ قُلْ هَلْ يَسْتَوِي الْاَعْمٰى وَالْبَص۪يرُۙ  اَمْ هَلْ تَسْتَوِي الظُّلُمَاتُ وَالنُّورُۚ  اَمْ جَعَلُوا لِلّٰهِ شُرَكَٓاءَ خَلَقُوا كَخَلْقِه۪ فَتَشَابَهَ الْخَلْقُ عَلَيْهِمْۜ  قُلِ اللّٰهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ', 'Kul men rabbus semavati vel ard, kulillah, kul e fettehaztum min dunihi evliyae la yemlikune li enfusihim nef\'an ve la darra, kul hel yestevil a\'ma vel basiru em hel testeviz zulumatu ven nur, em cealu lillahi şurekae halaku ke halkıhi fe teşabehel halku aleyhim, kulillahu haliku kulli şey\'in ve huvel vahidul kahhar.', 'De ki: \"Göklerin ve yerin Rabb\'i kimdir?\" De ki: \"Allah\'tır! O\'nun yanı sıra,  kendileri için yarar da zarar da sağlamaya güç yetiremeyenleri veliler mi edindiniz?\" De ki: \"Hiç gören ile kör bir olur mu? Ya da karanlıkla aydınlık bir midir?\" Yoksa Allah\'a,  O\'nun yaratması gibi yaratması olan ortaklar mı buldular da bu yaratma,  kendilerince birbirine mi benzeşti? De ki: \"Allah her şeyin yaratıcısıdır. O,  Eşsiz ve Benzersiz Bir Olan\'dır,  Varlığın Üzerinde Mutlak Egemen\'dir.\"', 'قل من رب السموت والارض قل الله قل افاتخذتم من دونه اوليا لا يملكون لانفسهم نفعا ولا ضرا قل هل يستوي الاعمي والبصير ام هل تستوي الظلمت والنور ام جعلوا لله شركا خلقوا كخلقه فتشبه الخلق عليهم قل الله خلق كل شي وهو الوحد القهر'),
(1724, 13, 17, 'اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً فَسَالَتْ اَوْدِيَةٌ بِقَدَرِهَا فَاحْتَمَلَ السَّيْلُ زَبَداً رَابِياًۜ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِي النَّارِ ابْتِغَٓاءَ حِلْيَةٍ اَوْ مَتَاعٍ زَبَدٌ مِثْلُهُۜ  كَذٰلِكَ يَضْرِبُ اللّٰهُ الْحَقَّ وَالْبَاطِلَۜ فَاَمَّا الزَّبَدُ فَيَذْهَبُ جُفَٓاءًۚ وَاَمَّا مَا يَنْفَعُ النَّاسَ فَيَمْكُثُ فِي الْاَرْضِۜ كَذٰلِكَ يَضْرِبُ اللّٰهُ الْاَمْثَالَۜ', 'Enzele mines semai maen fe salet evdiyetun bi kaderiha fahtemeles seylu zebeden rabiya, ve mimma yukıdune aleyhi fin naribtigae hılyetin ev metaın zebedun misluh, kezalike yadribullahul hakka vel batıl, fe emmez zebedu fe yezhebu cufa\', ve emma ma yenfaun nase fe yemkusufil ard, kezalike yadrıbullahul emsal.', 'Gökten su indirdi. Dereler kendi ölçüsünce çağlayıp aktı.[1] Akıntı,  üste çıkan köpüğü taşıyıp götürür. Buna benzer bir köpük de değerli maden[2] elde etmek için veya faydalanmak için ateşte eritilen madenlerin üzerinde de oluşur. İşte Allah hakk ve batıla böyle örnek verir. Köpük yok olup gider. İnsana fayda veren şey ise kalıcı olur. İşte Allah böyle örnekler verir.', 'انزل من السما ما فسالت اودية بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار ابتغا حلية او متع زبد مثله كذلك يضرب الله الحق والبطل فاما الزبد فيذهب جفا واما ما ينفع الناس فيمكث في الارض كذلك يضرب الله الامثال'),
(1725, 13, 18, 'لِلَّذ۪ينَ اسْتَجَابُوا لِرَبِّهِمُ الْحُسْنٰىۜ وَالَّذ۪ينَ لَمْ يَسْتَج۪يبُوا لَهُ لَوْ اَنَّ لَهُمْ مَا فِي الْاَرْضِ جَم۪يعاً وَمِثْلَهُ مَعَهُ لَافْتَدَوْا بِه۪ۜ اُو۬لٰٓئِكَ لَهُمْ سُٓوءُ الْحِسَابِۙ وَمَأْوٰيهُمْ جَهَنَّمُۜ وَبِئْسَ الْمِهَادُ۟', 'Lillezinestecabu li rabbihimul husna, vellezine lem yestecibu lehu lev enne lehum ma fil ardı cemian ve mislehu meahu leftedev bih, ulaike lehum suul hısabi ve me\'vahum cehennem, ve bi\'sel mihad.', 'Rabb\'lerinin çağrısına uyanlar için,  en iyi karşılık vardır. O\'na uymayanlar ise,  yeryüzünde bulunanların tamamı ve bir o kadarı daha kendilerinin olsa,  kurtulmak için hepsini karşılık olarak verirlerdi. Hesabın kötüsü onlar içindir. Varacakları yer Cehennem\'dir. O ne kötü bir yataktır.', 'للذين استجابوا لربهم الحسني والذين لم يستجيبوا له لو ان لهم ما في الارض جميعا ومثله معه لافتدوا به اوليك لهم سو الحساب وماويهم جهنم وبيس المهاد'),
(1726, 13, 19, 'اَفَمَنْ يَعْلَمُ اَنَّـمَٓا اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَ الْحَقُّ كَمَنْ هُوَ اَعْمٰىۜ اِنَّمَا يَتَذَكَّرُ اُو۬لُوا الْاَلْبَابِۙ', 'E fe men ya\'lemu ennema unzile ileyke min rabbikel hakku ke men huve a\'ma, innema yetezekkeru ulul elbab.', 'Rabb\'inden sana indirilenin kesin doğru olduğunu bilen kimse,  kör kimse gibi midir? Ancak sağlıklı düşünen akıl sahipleri öğüt alıp gerçeği kavrarlar.', 'افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمي انما يتذكر اولوا الالبب'),
(1727, 13, 20, 'اَلَّذ۪ينَ يُوفُونَ بِعَهْدِ اللّٰهِ وَلَا يَنْقُضُونَ الْم۪يثَاقَۙ', 'Ellezine yufune bi ahdillahi ve la yenkudunel misak.', 'Onlar,  Allah\'la olan ahdi[1] yerine getirirler,  misakı[2] bozmazlar.', 'الذين يوفون بعهد الله ولا ينقضون الميثق'),
(1728, 13, 21, 'وَالَّذ۪ينَ يَصِلُونَ مَٓا اَمَرَ اللّٰهُ بِه۪ٓ اَنْ يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُٓوءَ الْحِسَابِۜ', 'Vellezine yasılune ma emerallahu bihi en yusale ve yahşevne rabbehum ve yehafune suel hisab.', 'Ve o kimseler,  Allah\'ın bağlı kalınmasını emrettiği şeye bağlı[1] kalırlar,  Rabb\'lerini saygı ile yüceltirler,  hesabın kötü olmasından korkarlar.', 'والذين يصلون ما امر الله به ان يوصل ويخشون ربهم ويخافون سو الحساب'),
(1729, 13, 22, 'وَالَّذ۪ينَ صَبَرُوا ابْتِغَٓاءَ وَجْهِ رَبِّهِمْ وَاَقَامُوا الصَّلٰوةَ وَاَنْفَقُوا مِمَّا رَزَقْنَاهُمْ سِراًّ وَعَلَانِيَةً وَيَدْرَؤُ۫نَ بِالْحَسَنَةِ السَّيِّئَةَ اُو۬لٰٓئِكَ لَهُمْ عُقْبَى الدَّارِۙ', 'Vellezine saberubtigae vechi rabbihim ve ekamus salate ve enfeku mimma rezaknahum sirren ve alaniyeten ve yedreune bil hasenetis seyyiete ulaike lehum ukbed dar.', 'Ve o kimseler,  sabırla Rabb\'lerine yönelirler ve salatı ikame ederler[1],  kendilerine verdiğimiz rızıktan gizli ve açık infak[2] ederler,  kötülüğü iyilikle savarlar; dünya yurdunun sonucu onlar içindir.', 'والذين صبروا ابتغا وجه ربهم واقاموا الصلوة وانفقوا مما رزقنهم سرا وعلانية ويدرون بالحسنة السيية اوليك لهم عقبي الدار'),
(1730, 13, 23, 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا وَمَنْ صَلَحَ مِنْ اٰبَٓائِهِمْ وَاَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ وَالْمَلٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍۚ', 'Cennatu adnin yedhuluneha ve men salaha min abaihim ve ezvacihim ve zurriyyatihim vel melaiketu yedhulune aleyhim min kulli bab.', 'Adn Cennetleri onlarındır. Oraya,  anne ve babalarından,  eşlerinden ve soylarından salih[1] olanlar gireceklerdir. Melekler de her kapıdan yanlarına girecekler ve şöyle diyecekler:', 'جنت عدن يدخلونها ومن صلح من ابايهم وازوجهم وذريتهم والمليكة يدخلون عليهم من كل باب'),
(1731, 13, 24, 'سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِۜ', 'Selamun aleykum bi ma sabertum fe ni\'me ukbed dar.', '\"Sabretmeniz [1] nedeniyle size selam olsun. Dünya yurdunun sonu ne güzeldir.\"', 'سلم عليكم بما صبرتم فنعم عقبي الدار'),
(1732, 13, 25, 'وَالَّذ۪ينَ يَنْقُضُونَ عَهْدَ اللّٰهِ مِنْ بَعْدِ م۪يثَاقِه۪ وَيَقْطَعُونَ مَٓا اَمَرَ اللّٰهُ بِه۪ٓ اَنْ يُوصَلَ وَيُفْسِدُونَ فِي الْاَرْضِۙ اُو۬لٰٓئِكَ لَهُمُ اللَّعْنَةُ وَلَهُمْ سُٓوءُ الدَّارِ', 'Vellezine yankudune ahdallahi min ba\'di misakıhi ve yaktaune ma emerallahu bihi en yusale ve yufsidune fil ardı ulaike lehumul la\'netu ve lehum suud dar.', 'Misaklerinden [1] sonra Allah\'ın ahdini [2] bozanlar; Allah\'ın bağlı kalınmasını istediği şeyle bağlarını koparanlar ve yeryüzünde bozgunculuk yapanlara lanet vardır ve dünya yurdunun kötü sonu onlarındır.', 'والذين ينقضون عهد الله من بعد ميثقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اوليك لهم اللعنة ولهم سو الدار'),
(1733, 13, 26, 'اَللّٰهُ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُۜ وَفَرِحُوا بِالْحَيٰوةِ الدُّنْيَاۜ وَمَا الْحَيٰوةُ الدُّنْيَا فِي الْاٰخِرَةِ اِلَّا مَتَاعٌ۟', 'Allahu yebsutur rızka li men yeşau ve yakdir, ve ferihu bil hayatid dunya, ve mal hayatud dunya fil ahıreti illa meta\'u.', 'Allah,  rızkı dilediğine genişletir de ölçülendirir de. Dünya hayatı ile şımardılar. Oysa dünya,  ahiret hayatı yanında bir metadan [1] başka bir şey değildir.', 'الله يبسط الرزق لمن يشا ويقدر وفرحوا بالحيوة الدنيا وما الحيوة الدنيا في الاخرة الا متع'),
(1734, 13, 27, 'وَيَقُولُ الَّذ۪ينَ كَفَرُوا لَوْلَٓا اُنْزِلَ عَلَيْهِ اٰيَةٌ مِنْ رَبِّه۪ۜ قُلْ اِنَّ اللّٰهَ يُضِلُّ مَنْ يَشَٓاءُ وَيَهْد۪ٓي اِلَيْهِ مَنْ اَنَابَۚ', 'Ve yekulullezine keferu lev la unzile aleyhi ayetun min rabbih, kul innallahe yudillu men yeşau ve yehdi ileyhi men enab.', 'Kafirler: \"Rabb\'inden ona bir ayet [1] indirilseydi ya!\" diyorlar. De ki: \"Allah,  hak edeni saptırır[2],  kendisine yönelen kimseyi de doğru yola iletir.\"', 'ويقول الذين كفروا لولا انزل عليه اية من ربه قل ان الله يضل من يشا ويهدي اليه من اناب'),
(1735, 13, 28, 'اَلَّذ۪ينَ اٰمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللّٰهِۜ اَلَا بِذِكْرِ اللّٰهِ تَطْمَئِنُّ الْقُلُوبُۜ', 'Ellezine amenu ve tatmainnu kulubuhum bi zikrillah e la bi zikrillahi tatmainnul kulub.', 'Onlar,  iman edenler ve kalpleri [1] Allah\'ın zikri [2] ile tatmin olanlardır. Kalpler,  ancak Allah\'ın zikri ile tatmin olur.', 'الذين امنوا وتطمين قلوبهم بذكر الله الا بذكر الله تطمين القلوب'),
(1736, 13, 29, 'اَلَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ طُوبٰى لَهُمْ وَحُسْنُ مَاٰبٍ', 'Ellezine amenu ve amilus salihati tuba lehum ve husnu meab.', 'İman eden ve salihatı [1] yapanlara ne mutlu. Dönüş yerinin iyisi onlarındır.', 'الذين امنوا وعملوا الصلحت طوبي لهم وحسن ماب'),
(1737, 13, 30, 'كَذٰلِكَ اَرْسَلْنَاكَ ف۪ٓي اُمَّةٍ قَدْ خَلَتْ مِنْ قَبْلِهَٓا اُمَمٌ لِتَتْلُوَ۬ا عَلَيْهِمُ الَّـذ۪ٓي اَوْحَيْنَٓا اِلَيْكَ وَهُمْ يَكْفُرُونَ بِالرَّحْمٰنِۜ قُلْ هُوَ رَبّ۪ي لَٓا اِلٰهَ اِلَّا هُوَۚ عَلَيْهِ تَوَكَّلْتُ وَاِلَيْهِ مَتَابِ', 'Kezalike erselnake fi ummetin kad halet min kabliha umemun li tetluve aleyhimullezi evhayna ileyke ve hum yekfurune bir rahman, kul huve rabbi la ilahe illa hu, aleyhi tevekkeltu ve ileyhi metab.', 'Kendilerinden önce nice toplumların gelip geçtiği bir topluma seni gönderdik ki,  sana vahyettiğimizi onlara okuyup duyurasın. Onlar,  Rahman\'a nankörlük ediyorlar. De ki: \"O benim Rabbimdir; Ondan başka ilah yoktur. Ben O\'na tevekkül[1] ettim,  tevbe[2] O\'nadır.\"', 'كذلك ارسلنك في امة قد خلت من قبلها امم لتتلوا عليهم الذي اوحينا اليك وهم يكفرون بالرحمن قل هو ربي لا اله الا هو عليه توكلت واليه متاب'),
(1738, 13, 31, 'وَلَوْ اَنَّ قُرْاٰناً سُيِّرَتْ بِهِ الْجِبَالُ اَوْ قُطِّعَتْ بِهِ الْاَرْضُ اَوْ كُلِّمَ بِهِ الْمَوْتٰىۜ بَلْ لِلّٰهِ الْاَمْرُ جَم۪يعاًۜ اَفَلَمْ يَايْـَٔسِ الَّذ۪ينَ اٰمَنُٓوا اَنْ لَوْ يَشَٓاءُ اللّٰهُ لَهَدَى النَّاسَ جَم۪يعاًۜ وَلَا يَزَالُ الَّذ۪ينَ كَفَرُوا تُص۪يبُهُمْ بِمَا صَنَعُوا قَارِعَةٌ اَوْ تَحُلُّ قَر۪يباً مِنْ دَارِهِمْ حَتّٰى يَأْتِيَ وَعْدُ اللّٰهِۜ اِنَّ اللّٰهَ لَا يُخْلِفُ الْم۪يعَادَ۟', 'Ve lev enne kur\'anen suyyiret bihil cibalu ev kuttıat bihil ardu ev kullime bihil mevta, bel lillahil emru cemia, e fe lem ye\'yesillezine amenu en lev yeşaullahu le heden nase cemia,ve la yezalullezine keferu tusibuhum bi ma sanau kariatun ev tehullu kariben min darihim hatta ye\'tiye va\'dullah, innallahe la yuhliful miad.', 'Kur\'an\'la dağlar yürütülseydi veya onunla yeryüzü yarılıp parçalansaydı veya onunla ölüler konuşturulsaydı yine de bir şey değişmezdi. Hayır! Bütün işler Allah\'a aittir. İman edenler hala anlamadılar mı ki Allah tercih edecek[1] olsa bütün insanları doğru yola iletir. Yaltaklanmalarından[2] dolayı Kafirler bela ile karşı karşıya kalıp duracaktır. Veya evlerinin yanı başına inecek. Allah\'ın vaadi gelinceye kadar bu böyle sürüp gidecektir. Kuşkusuz Allah sözünden dönmez.', 'ولو ان قرانا سيرت به الجبال او قطعت به الارض او كلم به الموتي بل لله الامر جميعا افلم يايس الذين امنوا ان لو يشا الله لهدي الناس جميعا ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة او تحل قريبا من دارهم حتي ياتي وعد الله ان الله لا يخلف الميعاد'),
(1739, 13, 32, 'وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَاَمْلَيْتُ لِلَّذ۪ينَ كَفَرُوا ثُمَّ اَخَذْتُهُمْ۠ فَكَيْفَ كَانَ عِقَابِ', 'Ve lekadistuhzie bi rusulin min kablike fe emleytu lillezine keferu summe ehaztuhum, fe keyfe kane ıkab.', 'Ant olsun senden önceki resullerle de alay edildi. Kafirlere süre tanıdım. Sonra zamanı gelince onları yakalayıverdim. Benim cezam nasıl olurmuş gördüler.', 'ولقد استهزي برسل من قبلك فامليت للذين كفروا ثم اخذتهم فكيف كان عقاب'),
(1740, 13, 33, 'اَفَمَنْ هُوَ قَٓائِمٌ عَلٰى كُلِّ نَفْسٍ بِمَا كَسَبَتْۚ وَجَعَلُوا لِلّٰهِ شُرَكَٓاءَۜ قُلْ سَمُّوهُمْۜ اَمْ تُنَبِّؤُ۫نَهُ بِمَا لَا يَعْلَمُ فِي الْاَرْضِ اَمْ بِظَاهِرٍ مِنَ الْقَوْلِۜ بَلْ زُيِّنَ لِلَّذ۪ينَ كَفَرُوا مَكْرُهُمْ وَصُدُّوا عَنِ السَّب۪يلِۜ وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ هَادٍ', 'E fe men huve kaimun ala kulli nefsin bi ma kesebet, ve cealu lillahi şureka\', kul semmuhum, em tunebbiunehu bi ma la ya\'lemu fil ardı em bi zahirin minel kavl, bel zuyyine lillezine keferu mekruhum ve suddu anis sebil, ve men yudlilillahu fe ma lehu min had.', 'Peki,  herkesin ne yaptığını gözeten O değil mi? Onlar yine de ilahlarını Allah\'a ortaklar koştular. De ki: \"Onları[1] istediğiniz isimle isimlendirin bakalım. Yoksa siz,  O\'na yeryüzünde bilmediği bir şeyi mi haber veriyorsunuz? Yoksa boş sözlere mi aldanıyorsunuz?\" Aslında Kafirlere[2] planları güzel gösterildi de doğru yoldan alıkonuldular. Allah kimi saptırırsa[3] artık ona yol gösterecek kimse olamaz.', 'افمن هو قايم علي كل نفس بما كسبت وجعلوا لله شركا قل سموهم ام تنبونه بما لا يعلم في الارض ام بظهر من القول بل زين للذين كفروا مكرهم وصدوا عن السبيل ومن يضلل الله فما له من هاد'),
(1741, 13, 34, 'لَهُمْ عَذَابٌ فِي الْحَيٰوةِ الدُّنْيَا وَلَعَذَابُ الْاٰخِرَةِ اَشَقُّۚ وَمَا لَهُمْ مِنَ اللّٰهِ مِنْ وَاقٍ', 'Lehum azabun fil hayatid dunya ve le azabul ahıreti eşakk, ve ma lehum minallahi min vak.', 'Onlara dünya hayatında bir azap vardır. Ahiret azabı ise daha zordur. Onları Allah\'ın azabından koruyabilecek bir koruyucuları da yoktur.', 'لهم عذاب في الحيوة الدنيا ولعذاب الاخرة اشق وما لهم من الله من واق'),
(1742, 13, 35, 'مَثَلُ الْجَنَّةِ الَّت۪ي وُعِدَ الْمُتَّقُونَۜ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ اُكُلُهَا دَٓائِمٌ وَظِلُّهَاۜ تِلْكَ عُقْبَى الَّذ۪ينَ اتَّقَوْاۗ وَعُقْبَى الْكَافِر۪ينَ النَّارُ', 'Meselul cennetilleti vuidel muttekun, tecri min tahtihel enhar, ukuluha daimun ve zilluha, tilke ukbellezinettekav ve ukbel kafirinen nar.', 'Takva[1] sahiplerine söz verilen Cennet\'in içinden ırmaklar akmaktadır,  meyvesi ve gölgesi süreklidir. İşte bu takva sahiplerinin sonudur. Kafirlerin sonu ise ateştir.', 'مثل الجنة التي وعد المتقون تجري من تحتها الانهر اكلها دايم وظلها تلك عقبي الذين اتقوا وعقبي الكفرين النار'),
(1743, 13, 36, 'وَالَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يَفْرَحُونَ بِمَٓا اُنْزِلَ اِلَيْكَ وَمِنَ الْاَحْزَابِ مَنْ يُنْكِرُ بَعْضَهُۜ  قُلْ اِنَّـمَٓا اُمِرْتُ اَنْ اَعْبُدَ اللّٰهَ وَلَٓا اُشْرِكَ بِه۪ۜ اِلَيْهِ اَدْعُوا وَاِلَيْهِ مَاٰبِ', 'Vellezine ateynahumul kitabe yefrehune bima unzile ileyke ve minel ahzabi men yunkiru ba\'dah, kul innema umirtu en a\'budallahe ve la uşrike bih, ileyhi ed\'u ve ileyhi meab.', 'Kendilerine Kitap verdiğimiz kimseler,  sana indirilen ile sevinirler. Kabilelerden onun bir kısmını küfreden[1] gruplar vardır. De ki: \"Ben yalnızca Allah\'a kulluk[2] etmekle ve O\'na şirk koşmamakla emrolundum. Ben yalnızca O\'na çağırıyorum ve dönüşüm yalnızca O\'nadır.\"', 'والذين اتينهم الكتب يفرحون بما انزل اليك ومن الاحزاب من ينكر بعضه قل انما امرت ان اعبد الله ولا اشرك به اليه ادعوا واليه ماب'),
(1744, 13, 37, 'وَكَذٰلِكَ اَنْزَلْنَاهُ حُكْماً عَرَبِياًّۜ وَلَئِنِ اتَّبَعْتَ اَهْوَٓاءَهُمْ بَعْدَ مَا جَٓاءَكَ مِنَ الْعِلْمِۙ مَا لَكَ مِنَ اللّٰهِ مِنْ وَلِيٍّ وَلَا وَاقٍ۟', 'Ve kezalike enzelnahu hukmen arabiyya, ve le initteba\'te ehvaehum ba\'de ma caeke minel ilmi ma leke minallahi min veliyyin ve la vak.', 'İşte böylece Biz onu Arapça bir hüküm[1] olarak indirdik. Eğer sana gelen ilimden[2] sonra onların hevalarına[3] uyarsan,  seni Allah\'tan koruyacak bir veli[4],  bir koruyucu bulamazsın.', 'وكذلك انزلنه حكما عربيا ولين اتبعت اهواهم بعدما جاك من العلم ما لك من الله من ولي ولا واق'),
(1745, 13, 38, 'وَلَقَدْ اَرْسَلْنَا رُسُلاً مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ اَزْوَاجاً وَذُرِّيَّةًۜ وَمَا كَانَ لِرَسُولٍ اَنْ يَأْتِيَ بِاٰيَةٍ اِلَّا بِاِذْنِ اللّٰهِۜ لِكُلِّ اَجَلٍ كِتَابٌ', 'Ve lekad erselna rusulen min kablike ve cealna lehum ezvacen ve zurriyyeh, ve ma kane li resulin en ye\'tiye bi ayetin illa bi iznillah, li kulli ecelin kitab.', 'Ant olsun ki senden önce de resuller gönderdik. Onlara da eşler ve çocuklar verdik. Bir resul için Allah\'ın izni olmadan bir ayet[1] getirmesi mümkün değildir. Her ecelin[2] bir kitabı[3] vardır.', 'ولقد ارسلنا رسلا من قبلك وجعلنا لهم ازوجا وذرية وما كان لرسول ان ياتي باية الا باذن الله لكل اجل كتاب'),
(1746, 13, 39, 'يَمْحُوا اللّٰهُ مَا يَشَٓاءُ وَيُثْبِتُۚ وَعِنْدَهُٓ اُمُّ الْكِتَابِ', 'Yemhullahu ma yeşau ve yusbit, ve indehu ummul kitab.', 'Allah dilediğini yok eder,  dilediğine de dokunmaz. Ana Kitap O\'nun yanındadır.', 'يمحوا الله ما يشا ويثبت وعنده ام الكتب'),
(1747, 13, 40, 'وَاِنْ مَا نُرِيَنَّكَ بَعْضَ الَّذ۪ي نَعِدُهُمْ اَوْ نَتَوَفَّـيَنَّكَ فَاِنَّمَا عَلَيْكَ الْبَلَاغُ وَعَلَيْنَا الْحِسَابُ', 'Ve in ma nuriyenneke ba\'dallezi neiduhum ev neteveffeyenneke fe innema aleykel belagu ve aleynel hisab.', 'İster onlara yaptığımız uyarının bir kısmını sana gösterelim,  ister senin canını alalım; sana düşen sadece tebliğ yapmaktır.[1] Hesap görmek Bize aittir.', 'وان ما نرينك بعض الذي نعدهم او نتوفينك فانما عليك البلغ وعلينا الحساب'),
(1748, 13, 41, 'اَوَلَمْ يَرَوْا اَنَّا نَأْتِي الْاَرْضَ نَنْقُصُهَا مِنْ اَطْرَافِهَاۜ وَاللّٰهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِه۪ۜ وَهُوَ سَر۪يعُ الْحِسَابِ', 'E ve lem yerev enna ne\'til arda nenkusuha min etrafiha, vallahu yahkumu la muakkıbe li hukmih, ve huve seriul hısab.', 'Yeryüzüne gelip onu çevresinden nasıl eksilttiğimizi[1] görmüyorlar mı? Karar veren Allah\'tır ve O\'nun verdiği kararı bozacak hiç kimse yoktur. O,  hesabı çabuk görendir.', 'اولم يروا انا ناتي الارض ننقصها من اطرافها والله يحكم لا معقب لحكمه وهو سريع الحساب'),
(1749, 13, 42, 'وَقَدْ مَكَرَ الَّذ۪ينَ مِنْ قَبْلِهِمْ فَلِلّٰهِ الْمَكْرُ جَم۪يعاًۜ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍۜ وَسَيَعْلَمُ الْكُفَّارُ لِمَنْ عُقْبَى الدَّارِ', 'Ve kad mekerellezine min kablihim fe lillahil mekru cemia,ya\'lemu ma teksibu kullu nefs, ve se ya\'lemul kuffaru li men ukbed dar.', 'Onlardan öncekiler de planlar yapmışlardı. Oysa Allah\'ın planı bütün planları geçersiz kılar. Zira O,  herkesin ne yaptığını bilir. Kafirler,  bu yurdun sonunun[1] kimin olduğunu bileceklerdir.', 'وقد مكر الذين من قبلهم فلله المكر جميعا يعلم ما تكسب كل نفس وسيعلم الكفر لمن عقبي الدار'),
(1750, 13, 43, 'وَيَقُولُ الَّذ۪ينَ كَفَرُوا لَسْتَ مُرْسَلاًۜ قُلْ كَفٰى بِاللّٰهِ شَه۪يداً بَيْن۪ي وَبَيْنَكُمْۙ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ', 'Ve yekulullezine keferu leste mursela, kul kefa billahi şehiden beyni ve beynekum ve men indehu ilmul kitab.', 'Kafirler,  \"Sen gönderilmiş[1] değilsin.\" diyorlar. De ki: \"Benimle sizin aranızda en iyi tanık olarak Allah ve yanlarında Kitap\'ın bilgisi olanlar yeter.\"', 'ويقول الذين كفروا لست مرسلا قل كفي بالله شهيدا بيني وبينكم ومن عنده علم الكتب'),
(1751, 14, 1, 'الٓـرٰ۠ كِتَابٌ اَنْزَلْنَاهُ اِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ اِلَى النُّورِ بِـاِذْنِ رَبِّهِمْ اِلٰى صِرَاطِ الْعَز۪يزِ الْحَم۪يدِۙ', 'Elif lam ra kitabun enzelnahu ileyke li tuhricen nase minez zulumati ilen nuri bi izni rabbihim ila sıratıl azizil hamid.', 'Elif,  Lam,  Ra. Bu; insanları,  Rabb\'lerinin izni[1] ile karanlıklardan aydınlığa çıkarman; onları Mutlak Üstün Olan\'ın,  Övgüye Değer Yegane Varlık Olan\'ın yoluna iletmen için sana indirdiğimiz bir Kitap\'tır.', 'الر كتب انزلنه اليك لتخرج الناس من الظلمت الي النور باذن ربهم الي صرط العزيز الحميد'),
(1752, 14, 2, 'اَللّٰهِ الَّذ۪ي لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَوَيْلٌ لِلْكَافِر۪ينَ مِنْ عَذَابٍ شَد۪يدٍۙ', 'Allahillezi lehu ma fis semavati ve ma fil ard, ve veylun lil kafirine min azabin şedid.', 'O Allah ki; göklerde ve yerde olan her şey O\'nundur. Görecekleri şiddetli azaptan dolayı,  Kafirlerin[1] vay haline!', 'الله الذي له ما في السموت وما في الارض وويل للكفرين من عذاب شديد'),
(1753, 14, 3, 'اَلَّذ۪ينَ يَسْتَحِبُّونَ الْحَيٰوةَ الدُّنْيَا عَلَى الْاٰخِرَةِ وَيَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ وَيَبْغُونَهَا عِوَجاًۜ اُو۬لٰٓئِكَ ف۪ي ضَلَالٍ بَع۪يدٍ', 'Ellezine yestehıbbunel hayated dunya alel ahıreti ve yasuddune an sebilillahi ve yebguneha iveca, ulaike fi dalalin baid.', 'Onlar,  dünya hayatını ahiret hayatına tercih ederler. Allah\'ın yolundan alıkoyarlar ve onda eğrilik ararlar. İşte onlar,  derin bir sapkınlık içindedirler.', 'الذين يستحبون الحيوة الدنيا علي الاخرة ويصدون عن سبيل الله ويبغونها عوجا اوليك في ضلل بعيد'),
(1754, 14, 4, 'وَمَٓا اَرْسَلْنَا مِنْ رَسُولٍ اِلَّا بِلِسَانِ قَوْمِه۪ لِيُبَيِّنَ لَهُمْۜ فَيُضِلُّ اللّٰهُ مَنْ يَشَٓاءُ وَيَهْد۪ي مَنْ يَشَٓاءُۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Ve ma erselna min resulin illa bi lisani kavmihi li yubeyyine lehum, fe yudillullahu men yeşau ve yehdi men yeşa\', ve huvel azizul hakim.', 'Biz,  mesajımızı anlaşılır olarak iletebilmesi için hiçbir Resulü kendi halkının dilinden başka bir dille göndermedik. Allah,  artık hak eden kimseyi[1] saptırır,  hak eden kimseyi[1] de doğru yola iletir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'وما ارسلنا من رسول الا بلسان قومه ليبين لهم فيضل الله من يشا ويهدي من يشا وهو العزيز الحكيم'),
(1755, 14, 5, 'وَلَقَدْ اَرْسَلْنَا مُوسٰى بِاٰيَاتِنَٓا اَنْ اَخْرِجْ قَوْمَكَ مِنَ الظُّلُمَاتِ اِلَى النُّورِ وَذَكِّرْهُمْ بِاَيَّامِ اللّٰهِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ', 'Ve le kad erselna musa bi ayatina en ahric kavmeke minez zulumati ilen nuri, ve zekkirhum bi eyyamillah, inne fi zalike le ayatin li kulli sabbarin şekur.', 'Ant olsun ki; Musa\'yı,  \"Halkını karanlıklardan aydınlığa çıkar,  onlara Allah\'ın günlerini[1] hatırlat.\" diye ayetlerimizle gönderdik. Kesinlikle bunda sabreden[2] ve şükreden[3] kimseler için nice ayetler[4] vardır.', 'ولقد ارسلنا موسي بايتنا ان اخرج قومك من الظلمت الي النور وذكرهم باييم الله ان في ذلك لايت لكل صبار شكور'),
(1756, 14, 6, 'وَاِذْ قَالَ مُوسٰى لِقَوْمِهِ اذْكُرُوا نِعْمَةَ اللّٰهِ عَلَيْكُمْ اِذْ اَنْجٰيكُمْ مِنْ اٰلِ فِرْعَوْنَ يَسُومُونَكُمْ سُٓوءَ الْعَذَابِ وَيُذَبِّحُونَ اَبْنَٓاءَكُمْ وَيَسْتَحْيُونَ نِسَٓاءَكُمْۜ وَف۪ي ذٰلِكُمْ بَلَٓاءٌ مِنْ رَبِّكُمْ عَظ۪يمٌ۟', 'Ve iz kale musa li kavmihizkuru ni\'metallahi aleykum iz encakum min ali fir\'avne yesumunekum suel azabi ve yuzebbihune ebnaekum ve yestahyune nisaekum, ve fi zalikum belaun min rabbikum azim.', 'Hani! Musa halkına demişti ki: \"Allah\'ın üzerinizdeki nimetini hatırlayın. Hani O,  sizi; oğullarınızı boğazlayıp,  kadınlarınızı sağ bırakarak azabın en kötüsü ile cezalandıran Firavunculardan kurtarmıştı. Bunda,  Rabb\'inizden çok büyük bir sınav vardı.\"', 'واذ قال موسي لقومه اذكروا نعمة الله عليكم اذ انجيكم من ال فرعون يسومونكم سو العذاب ويذبحون ابناكم ويستحيون نساكم وفي ذلكم بلا من ربكم عظيم'),
(1757, 14, 7, 'وَاِذْ تَاَذَّنَ رَبُّكُمْ لَئِنْ شَكَرْتُمْ لَاَز۪يدَنَّكُمْ وَلَئِنْ كَفَرْتُمْ اِنَّ عَذَاب۪ي لَشَد۪يدٌ', 'Ve iz te\'ezzene rabbukum le in şekertum le ezidennekum ve le in kefertum inne azabi le şedid.', 'Hani Rabb\'iniz: \"Eğer şükrederseniz mutlaka size nimetlerimi artırırım,  eğer nankörlük ederseniz bilin ki azabım çok şiddetlidir!\" diye bildirmişti.', 'واذ تاذن ربكم لين شكرتم لازيدنكم ولين كفرتم ان عذابي لشديد'),
(1758, 14, 8, 'وَقَالَ مُوسٰٓى اِنْ تَكْفُرُٓوا اَنْتُمْ وَمَنْ فِي الْاَرْضِ جَم۪يعاًۙ فَاِنَّ اللّٰهَ لَغَنِيٌّ حَم۪يدٌ', 'Ve kale musa in tekfuru entum ve men fil ardı cemi\'an fe innallahe le ganiyyun hamid.', 'Musa dedi ki: \"Eğer siz ve yeryüzünde bulunanların tamamı nankörlük etseniz bile,  iyi bilin ki Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.\"', 'وقال موسي ان تكفروا انتم ومن في الارض جميعا فان الله لغني حميد');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1759, 14, 9, 'اَلَمْ يَأْتِكُمْ نَبَؤُا الَّذ۪ينَ مِنْ قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَۜۛ وَالَّذ۪ينَ مِنْ بَعْدِهِمْۜۛ لَا يَعْلَمُهُمْ اِلَّا اللّٰهُۜ جَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَرَدُّٓوا اَيْدِيَهُمْ ف۪ٓي اَفْوَاهِهِمْ وَقَالُٓوا اِنَّا كَفَرْنَا بِمَٓا اُرْسِلْتُمْ بِه۪ وَاِنَّا لَف۪ي شَكٍّ مِمَّا تَدْعُونَـنَٓا اِلَيْهِ مُر۪يبٍ', 'E lem ye\'tikum nebeullezine min kablikum kavmi nuhın ve adin ve semud, vellezine min ba\'dihim, la ya\'lemuhum illallah, caethum rusuluhum bil beyyinati fe reddu eydiyehum fi efvahihim ve kalu inna keferna bi ma ursiltum bihi ve inna le fi şekkin mimma ted\'unena ileyhi murib.', 'Sizden öncekilerin; Nuh,  Âd,  Semud halklarının ve onlardan sonra gelenlerin haberleri size gelmedi mi? Allah\'tan başkası onları bilmez. Resulleri onlara beyyinelerle[1] geldiği halde onlar zorla susturmaya çalışarak: \"Biz,  kendisiyle gönderildiğiniz şeyi küfrediyoruz;[2] bizi çağırdığınız şey konusunda kaygı verici ikilem içindeyiz.\" dediler.', 'الم ياتكم نبوا الذين من قبلكم قوم نوح وعاد وثمود والذين من بعدهم لا يعلمهم الا الله جاتهم رسلهم بالبينت فردوا ايديهم في افوههم وقالوا انا كفرنا بما ارسلتم به وانا لفي شك مما تدعوننا اليه مريب'),
(1760, 14, 10, 'قَالَتْ رُسُلُهُمْ اَفِي اللّٰهِ شَكٌّ فَاطِرِ السَّمٰوَاتِ وَالْاَرْضِۜ يَدْعُوكُمْ لِيَغْفِرَ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ اِلٰٓى اَجَلٍ مُسَمًّىۜ قَالُٓوا اِنْ اَنْتُمْ اِلَّا بَشَرٌ مِثْلُنَاۜ تُر۪يدُونَ اَنْ تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ اٰبَٓاؤُ۬نَا فَأْتُونَا بِسُلْطَانٍ مُب۪ينٍ', 'Kalet rusuluhum e fillahi şekkun fatırıs semavati vel ard, yed\'ukum li yagfire lekum min zunubikum ve yuahhırekum ila ecelin musemma, kalu in entum illa beşerun misluna, turidune en tesudduna amma kane ya\'budu abauna fe\'tuna bi sultanin mubin.', 'Resulleri dedi ki: \"Göklere ve yere belli bir fıtrat[1] veren,  sizi,  suçlarınızı bağışlamak için çağıran ve belirlenmiş bir ecele[2] kadar sizi erteleyen Allah hakkında mı kuşkudasınız?\" Dediler: \"Siz de ancak bizim gibi sadece bir beşersiniz.[3] Atalarımızın kulluk ettiklerinden bizi çevirmek istiyorsunuz. Öyleyse açık bir sultan[4] getirin!\"', 'قالت رسلهم افي الله شك فاطر السموت والارض يدعوكم ليغفر لكم من ذنوبكم ويوخركم الي اجل مسمي قالوا ان انتم الا بشر مثلنا تريدون ان تصدونا عما كان يعبد اباونا فاتونا بسلطن مبين'),
(1761, 14, 11, 'قَالَتْ لَهُمْ رُسُلُهُمْ اِنْ نَحْنُ اِلَّا بَشَرٌ مِثْلُكُمْ وَلٰكِنَّ اللّٰهَ يَمُنُّ عَلٰى مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ۜ وَمَا كَانَ لَـنَٓا اَنْ نَأْتِيَكُمْ بِسُلْطَانٍ اِلَّا بِاِذْنِ اللّٰهِۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'Kalet lehum rusuluhum in nahnu illa beşerun mislukum ve lakinnallahe yemunnu ala men yeşau min ibadih, ve ma kane lena en ne\'tiyekum bi sultanin illa bi iznillah, ve alallahi fel yetevekkelil mu\'minun.', 'Resulleri onlara dediler ki: \"Biz de ancak sizin gibi beşeriz. Ancak Allah,  kullarından dilediği kimseye iyilikte bulunur.[1] Allah\'ın izni olmaksızın bizim size bir sultan[2] getirmemiz olacak şey değildir. Mü\'minler yalnızca Allah\'a tevekkül[3] etsinler.\"', 'قالت لهم رسلهم ان نحن الا بشر مثلكم ولكن الله يمن علي من يشا من عباده وما كان لنا ان ناتيكم بسلطن الا باذن الله وعلي الله فليتوكل المومنون'),
(1762, 14, 12, 'وَمَا لَـنَٓا اَلَّا نَتَوَكَّلَ عَلَى اللّٰهِ وَقَدْ هَدٰينَا سُبُلَنَاۜ وَلَنَصْبِرَنَّ عَلٰى مَٓا اٰذَيْتُمُونَاۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ۟', 'Ve ma lena ella netevekkele alallahi ve kad hedana subulena, ve le nasbirenne ala ma azeytumuna, ve alallahi fel yetevekkelil mutevekkilun .', '\"Bize ne oluyor ki Allah\'a tevekkül etmeyelim? Üstelik bize yollarımızı göstermişken. Elbette biz,  bize yaşattığınız sıkıntılara sabredeceğiz. Tevekkül edenler de yalnızca Allah\'a tevekkül etsinler.\"', 'وما لنا الا نتوكل علي الله وقد هدينا سبلنا ولنصبرن علي ما اذيتمونا وعلي الله فليتوكل المتوكلون'),
(1763, 14, 13, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لِرُسُلِهِمْ لَنُخْرِجَنَّكُمْ مِنْ اَرْضِنَٓا اَوْ لَتَعُودُنَّ ف۪ي مِلَّتِنَاۜ فَاَوْحٰٓى اِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ الظَّالِم۪ينَۙ', 'Ve kalellezine keferu li rusulihim le nuhricennekum min ardına ev le teudunne fi milletina, fe evha ileyhim rabbuhum le nuhlikennez zalimin.', 'Kafirler,  resullerine: \"Sizi mutlaka yurdumuzdan süreceğiz veya kesinlikle bizim milletimize[1] dönmek zorundasınız!\" dediler. Bunun üzerine Rabbleri onlara: \"Zalimleri mutlaka yok edeceğiz.\" diye vahyetti.', 'وقال الذين كفروا لرسلهم لنخرجنكم من ارضنا او لتعودن في ملتنا فاوحي اليهم ربهم لنهلكن الظلمين'),
(1764, 14, 14, 'وَلَنُسْكِنَنَّكُمُ الْاَرْضَ مِنْ بَعْدِهِمْۜ ذٰلِكَ لِمَنْ خَافَ مَقَام۪ي وَخَافَ وَع۪يدِ', 'Ve le nuskinennekumul arda min ba\'dihim, zalike li men hafe makami ve hafe vaid.', '\"Ve onlardan sonra sizi mutlaka yeryüzünde yerleştireceğiz. Bu,  makamımı ve uyarımı dikkate alan kimseler içindir.\"', 'ولنسكننكم الارض من بعدهم ذلك لمن خاف مقامي وخاف وعيد'),
(1765, 14, 15, 'وَاسْتَفْتَحُوا وَخَابَ كُلُّ جَبَّارٍ عَن۪يدٍۙ', 'Vesteftehu ve habe kullu cebbarin anid.', 'Fetih[1] istediler. Bile bile haktan yüz çeviren zorbaların hepsi kaybetti.', 'واستفتحوا وخاب كل جبار عنيد'),
(1766, 14, 16, 'مِنْ وَرَٓائِه۪ جَهَنَّمُ وَيُسْقٰى مِنْ مَٓاءٍ صَد۪يدٍۙ', 'Min veraihi cehennemu ve yuska min main sadid.', 'Onun ardından da Cehennem vardır ve irinli sudan içirilecektir.', 'من ورايه جهنم ويسقي من ما صديد'),
(1767, 14, 17, 'يَتَجَرَّعُهُ وَلَا يَكَادُ يُس۪يغُهُ وَيَأْت۪يهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍۜ وَمِنْ وَرَٓائِه۪ عَذَابٌ غَل۪يظٌ', 'Yetecerreuhu ve la yekadu yusiguhu ve ye\'tihil mevtu min kulli mekanin ve ma huve bi meyyit, ve min veraihi azabun galiz.', 'Onu yutmaya çalışacak fakat boğazından geçiremeyecekler. Her yanından kendilerine ölüm geldiği halde yine de ölemeyecekler. Ardından da daha ağır bir azap tadacaklar.', 'يتجرعه ولا يكاد يسيغه وياتيه الموت من كل مكان وما هو بميت ومن ورايه عذاب غليظ'),
(1768, 14, 18, 'مَثَلُ الَّذ۪ينَ كَفَرُوا بِرَبِّهِمْ اَعْمَالُهُمْ كَرَمَادٍۨ اشْتَدَّتْ بِهِ الرّ۪يحُ ف۪ي يَوْمٍ عَاصِفٍۜ لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلٰى شَيْءٍۜ ذٰلِكَ هُوَ الضَّلَالُ الْبَع۪يدُ', 'Meselullezine keferu bi rabbihim a\'maluhum ke remadinişteddet bihir rihu fi yevmin asıf, la yakdirune mimma kesebu ala şey\', zalike huved dalalul baid.', 'Rabb\'lerine nankörlük edenlerin yaptıkları,  fırtınalı bir günde rüzgarın şiddetle savurduğu bir kül gibidir. Kazandıklarından hiçbir şey ellerinde kalmaz. İşte bu derin bir sapkınlıktır.', 'مثل الذين كفروا بربهم اعملهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا علي شي ذلك هو الضلل البعيد'),
(1769, 14, 19, 'اَلَمْ تَرَ اَنَّ اللّٰهَ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّۜ اِنْ يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَد۪يدٍۙ', 'E lem tere ennallahe halakas semavati vel arda bil hakk, in yeşa\' yuzhibkum ve ye\'ti bi halkın cedid.', 'Allah\'ın gökleri ve yeri Hakk ile yarattığını görmüyor musun? Dilerse sizi yok eder,  yeni bir nesil yaratır;', 'الم تر ان الله خلق السموت والارض بالحق ان يشا يذهبكم ويات بخلق جديد'),
(1770, 14, 20, 'وَمَا ذٰلِكَ عَلَى اللّٰهِ بِعَز۪يزٍ', 'Ve ma zalike alallahi bi aziz.', 'Bu Allah\'a göre asla büyük bir iş değildir.', 'وما ذلك علي الله بعزيز'),
(1771, 14, 21, 'وَبَرَزُوا لِلّٰهِ جَم۪يعاً فَقَالَ الضُّعَفٰٓؤُ۬ا لِلَّذ۪ينَ اسْتَكْـبَرُٓوا اِنَّا كُنَّا لَكُمْ تَبَعاً فَهَلْ اَنْتُمْ مُغْنُونَ عَنَّا مِنْ عَذَابِ اللّٰهِ مِنْ شَيْءٍۜ قَالُوا لَوْ هَدٰينَا اللّٰهُ لَهَدَيْنَاكُمْۜ سَوَٓاءٌ عَلَيْنَٓا اَجَزِعْنَٓا اَمْ صَبَرْنَا مَا لَنَا مِنْ مَح۪يصٍ۟', 'Ve berezu lillahi cemian fe kaled duafau lillezinestekberu inna kunna lekum tebean fe hel entum mugnune anna min azabillahi min şey\', kalu lev hedanallahu le hedeynakum, sevaun aleyna ecezi\'na em saberna ma lena min mahis.', 'Hepsi,  Allah\'ın huzuruna çıkacaklar. Güçsüz olan kimseler,  büyüklük taslayanlara: \"Gerçekten biz size uyan kimselerdik. Şimdi siz,  Allah\'ın azabından herhangi bir şeyi bizden savabilir misiniz?\" diyecekler. Onlar: \"Eğer Allah bize bir yol gösterseydi biz de kesinlikle size yol göstericiler olurduk.[1] Sabretsek de sabretmesek de bizim için birdir. Bizim için kaçacak bir yer yoktur.\" dediler.', 'وبرزوا لله جميعا فقال الضعفوا للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا من عذاب الله من شي قالوا لو هدينا الله لهدينكم سوا علينا اجزعنا ام صبرنا ما لنا من محيص'),
(1772, 14, 22, 'وَقَالَ الشَّيْطَانُ لَمَّا قُضِيَ الْاَمْرُ اِنَّ اللّٰهَ وَعَدَكُمْ وَعْدَ الْحَقِّ وَوَعَدْتُكُمْ فَاَخْلَفْتُكُمْۜ وَمَا كَانَ لِيَ عَلَيْكُمْ مِنْ سُلْطَانٍ اِلَّٓا اَنْ دَعَوْتُكُمْ فَاسْتَجَبْتُمْ ل۪يۚ فَلَا تَلُومُون۪ي وَلُومُٓوا اَنْفُسَكُمْۜ مَٓا اَنَا۬ بِمُصْرِخِكُمْ وَمَٓا اَنْتُمْ بِمُصْرِخِيَّۜ اِنّ۪ي كَفَرْتُ بِمَٓا اَشْرَكْتُمُونِ مِنْ قَبْلُۜ اِنَّ الظَّالِم۪ينَ لَهُمْ عَذَابٌ اَل۪يمٌ', 'Ve kaleş şeytanu lemma kudıyel emru innallahe veadekum va\'del hakkı ve veadtukum fe ahleftukum, ve ma kane liye aleykum min sultanin illa en deavtukum festecebtum li, fe la telumuni ve lumu enfusekum, ma ene bi musrihikum ve ma entum bi musrıhıyy, inni kefertu bi ma eşrektumuni min kabl, innaz zalimine lehum azabun elim.', 'Ne zaman ki hüküm gerçekleşti,  şeytan onlara: \"Şüphesiz ki Allah\'ın vaktiyle yaptığı uyarıların hepsi gerçekleşti. Ben de size vadettim. Benim verdiğim sözler ise boş çıktı. Zaten benim size karşı zorlayıcı bir gücüm yoktu. Ben size sadece çağrıda bulundum siz de kendiliğinizden çağrıma uydunuz. O halde beni kınamayın,  kendinizi kınayın. Ne ben sizi kurtarabilirim ne de siz beni kurtarabilirsiniz. Gerçekten ben,  daha önce beni Allah\'a ortak koşmanızı da yok saymıştım.\" dedi. Zalimlerin hakkı acı bir azaptır.', 'وقال الشيطن لما قضي الامر ان الله وعدكم وعد الحق ووعدتكم فاخلفتكم وما كان لي عليكم من سلطن الا ان دعوتكم فاستجبتم لي فلا تلوموني ولوموا انفسكم ما انا بمصرخكم وما انتم بمصرخي اني كفرت بما اشركتمون من قبل ان الظلمين لهم عذاب اليم'),
(1773, 14, 23, 'وَاُدْخِلَ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَا بِاِذْنِ رَبِّهِمْۜ تَحِيَّتُهُمْ ف۪يهَا سَلَامٌ', 'Ve udhilellezine amenu ve amilus salihati cennatin tecri min tahtihel enharu halidine fiha bi izni rabbihim, tehıyyetuhum fiha selam.', 'İman eden ve salihatı yapanlar[1],  Rabb\'lerinin izni ile[2] içinde sürekli kalmak üzere içlerinden ırmaklar akan Cennetlere konulurlar. Oradaki yaşam temennileri \"selam\" dır.[3]', 'وادخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر خلدين فيها باذن ربهم تحيتهم فيها سلم'),
(1774, 14, 24, 'اَلَمْ تَرَ كَيْفَ ضَرَبَ اللّٰهُ مَثَلاً كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ اَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَٓاءِۙ', 'E lem tere keyfe daraballahu meselen kelimeten tayyibeten ke şeceretin tayyibetin asluha sabitun ve fer\'uha fis sema.', 'Görmüyor musun Allah nasıl örnek verdi? Hoş bir söz[1],  bakımlı bir ağaç gibidir. Onun kökü sabittir. Ve onun dalları göktedir.', 'الم تر كيف ضرب الله مثلا كلمة طيبة كشجرة طيبة اصلها ثابت وفرعها في السما'),
(1775, 14, 25, 'تُؤْت۪ٓي اُكُلَهَا كُلَّ ح۪ينٍ بِاِذْنِ رَبِّهَاۜ وَيَضْرِبُ اللّٰهُ الْاَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'Tu\'ti ukuleha kulle hinin bi izni rabbiha, ve yadrıbullahul emsale lin nasi leallehum yetezekkerun.', 'O,  Rabb\'inin izni ile her zaman ürün verir. Allah,  öğüt almaları için insanlara böyle örnekler verir.', 'توتي اكلها كل حين باذن ربها ويضرب الله الامثال للناس لعلهم يتذكرون'),
(1776, 14, 26, 'وَمَثَلُ كَلِمَةٍ خَب۪يثَةٍ كَشَجَرَةٍ خَب۪يثَةٍۨ اجْتُثَّتْ مِنْ فَوْقِ الْاَرْضِ مَا لَهَا مِنْ قَرَارٍ', 'Ve meselu kelimetin habisetin ke şeceretin habisetinictusset min fevkıl ardı ma leha min karar.', 'Kötü bir söz de,  kökü yerden sökülmüş,  ayakta duramayan kötü[1] bir ağaç gibidir.', 'ومثل كلمة خبيثة كشجرة خبيثة اجتثت من فوق الارض ما لها من قرار'),
(1777, 14, 27, 'يُثَبِّتُ اللّٰهُ الَّذ۪ينَ اٰمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيٰوةِ الدُّنْيَا وَفِي الْاٰخِرَةِۚ وَيُضِلُّ اللّٰهُ الظَّالِم۪ينَ وَيَفْعَلُ اللّٰهُ مَا يَشَٓاءُ۟', 'Yusebbitullahullezine amenu bil kavlis sabiti fil hayatid dunya ve fil ahıreh, ve yudıllullahuz zalimine ve yef\'alullahu ma yeşa\'.', 'Allah,  iman edenleri dünya hayatında da ahirette de sapasağlam[1] ayakta tutar. Allah,  zalim olanları saptırır. Allah dilediğini yapar.', 'يثبت الله الذين امنوا بالقول الثابت في الحيوة الدنيا وفي الاخرة ويضل الله الظلمين ويفعل الله ما يشا'),
(1778, 14, 28, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ بَدَّلُوا نِعْمَتَ اللّٰهِ كُفْراً وَاَحَلُّوا قَوْمَهُمْ دَارَ الْبَوَارِۙ', 'E lem tere ilellezine beddelu ni\'metallahi kufren ve ehallu kavmehum darel bevar.', 'Allah\'ın nimetini[1] Küfre[2] çevirenleri[3] ve böylece kendi toplumlarını yok olma yurduna sürükleyenleri görüyorsun değil mi?', 'الم تر الي الذين بدلوا نعمت الله كفرا واحلوا قومهم دار البوار'),
(1779, 14, 29, 'جَهَنَّمَۚ يَصْلَوْنَهَاۜ وَبِئْسَ الْقَرَارُ', 'Cehennem, yaslevneha, ve bi\'sel karar.', 'Gidecekleri yer Cehennem\'dir; kalacakları yer ne kötüdür!', 'جهنم يصلونها وبيس القرار'),
(1780, 14, 30, 'وَجَعَلُوا لِلّٰهِ اَنْدَاداً لِيُضِلُّوا عَنْ سَب۪يلِه۪ۜ قُلْ تَمَتَّعُوا فَاِنَّ مَص۪يرَكُمْ اِلَى النَّارِ', 'Ve cealu lillahi endaden li yudıllu an sebilih, kul temetteu fe inne masirekum ilen nar.', 'O\'nun yolundan saptırmak için Allah\'a birtakım eşler koştular. De ki: \"Yararlanın bakalım! Gideceğiniz yer ateştir.\"', 'وجعلوا لله اندادا ليضلوا عن سبيله قل تمتعوا فان مصيركم الي النار'),
(1781, 14, 31, 'قُلْ لِعِبَادِيَ الَّذ۪ينَ اٰمَنُوا يُق۪يمُوا الصَّلٰوةَ وَيُنْفِقُوا مِمَّا رَزَقْنَاهُمْ سِراًّ وَعَلَانِيَةً مِنْ قَبْلِ اَنْ يَأْتِيَ يَوْمٌ لَا بَيْعٌ ف۪يهِ وَلَا خِلَالٌ', 'Kul li ibadiyellezine amenu yukimus salate ve yunfiku mimma razaknahum sirren ve alaniyeten min kabli en ye\'tiye yevmun la bey\'un fihi ve la hilal.', 'İman eden kullarıma söyle: \"İçinde alışverişin[1] ve dostluğun olmadığı o gün gelmeden önce,  salatı ikame etsinler[2],  kendilerine verdiğimiz rızıktan gizli açık infak[3] etsinler.\"', 'قل لعبادي الذين امنوا يقيموا الصلوة وينفقوا مما رزقنهم سرا وعلانية من قبل ان ياتي يوم لا بيع فيه ولا خلل'),
(1782, 14, 32, 'اَللّٰهُ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَاَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً فَاَخْرَجَ بِه۪ مِنَ الثَّمَرَاتِ رِزْقاً لَكُمْۚ وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ بِاَمْرِه۪ۚ وَسَخَّرَ لَكُمُ الْاَنْهَارَۚ', 'Allahullezi halakas semavati vel arda ve enzele mines semai maen fe ahrece bihi mines semerati rızkan lekum, ve sehhare lekumul fulke li tecriye fil bahri bi emrih, ve sehhare lekumul enhar.', 'O Allah ki,  gökleri ve yeri yarattı,  gökten su indirdi ve böylece onunla ürünleri size rızık olarak yetiştirdi; koyduğu yasalarla denizlerde yüzüp giden gemileri hizmetinize verdi ve ırmakları yararınıza sundu.', 'الله الذي خلق السموت والارض وانزل من السما ما فاخرج به من الثمرت رزقا لكم وسخر لكم الفلك لتجري في البحر بامره وسخر لكم الانهر'),
(1783, 14, 33, 'وَسَخَّرَ لَكُمُ الشَّمْسَ وَالْقَمَرَ دَٓائِبَيْنِۚ وَسَخَّرَ لَكُمُ الَّيْلَ وَالنَّهَارَۚ', 'Ve sehhare lekumuş şemse vel kamere daibeyn, ve sehhare lekumul leyle ven nehar.', 'Düzenli bir hareket içinde olan Güneş\'i ve Ay\'ı hizmetinize verdi. Geceyi ve gündüzü de hizmetinize verdi.', 'وسخر لكم الشمس والقمر دايبين وسخر لكم اليل والنهار'),
(1784, 14, 34, 'وَاٰتٰيكُمْ مِنْ كُلِّ مَا سَاَلْتُمُوهُۜ وَاِنْ تَعُدُّوا نِعْمَتَ اللّٰهِ لَا تُحْصُوهَاۜ اِنَّ الْاِنْسَانَ لَظَلُومٌ كَفَّارٌ۟', 'Ve atakum min kulli ma se\'eltumuh, ve in teuddu ni\'metallahi la tuhsuha,innel insane le zalumun keffar.', 'Ondan istediğiniz her şeyden size verdi. Eğer Allah\'ın nimetini sayacak olsanız sayamazsınız. Doğrusu insan,  çok zalimdir,  çok kafirdir.[1]', 'واتيكم من كل ما سالتموه وان تعدوا نعمت الله لا تحصوها ان الانسن لظلوم كفار'),
(1785, 14, 35, 'وَاِذْ قَالَ اِبْرٰه۪يمُ رَبِّ اجْعَلْ هٰذَا الْبَلَدَ اٰمِناً وَاجْنُبْن۪ي وَبَنِيَّ اَنْ نَعْبُدَ الْاَصْنَامَۜ', 'Ve iz kale ibrahimu rabbic\'al hazel belede aminen vecnubni ve beniyye en na\'budel asnam.', 'Bir zamanlar İbrahim şöyle demişti: \"Rabb\'im! Bu şehri güvenli kıl. Beni ve çocuklarımı putlara kulluk yapmaktan uzak tut.\"', 'واذ قال ابرهيم رب اجعل هذا البلد امنا واجنبني وبني ان نعبد الاصنام'),
(1786, 14, 36, 'رَبِّ اِنَّهُنَّ اَضْلَلْنَ كَث۪يراً مِنَ النَّاسِۚ فَمَنْ تَبِعَن۪ي فَاِنَّهُ مِنّ۪يۚ وَمَنْ عَصَان۪ي فَاِنَّكَ غَفُورٌ رَح۪يمٌ', 'Rabbi innehunne adlelne kesiren minen nas, fe men tebiani fe innehu minni, ve men asani fe inneke gafurun rahim.', '\"Rabbim! Doğrusu onlar[1],  insanlardan çoğunu saptırdılar. Kim,  bana uyarsa,  o bendendir. Ve bana uymayana gelince:[2] Kuşkusuz Sen,  Çok Bağışlayıcı\'sın,  Rahmeti Kesintisiz Olan\'sın.\"', 'رب انهن اضللن كثيرا من الناس فمن تبعني فانه مني ومن عصاني فانك غفور رحيم'),
(1787, 14, 37, 'رَبَّـنَٓا اِنّ۪ٓي اَسْكَنْتُ مِنْ ذُرِّيَّت۪ي بِوَادٍ غَيْرِ ذ۪ي زَرْعٍ عِنْدَ بَيْتِكَ الْمُحَرَّمِۙ رَبَّـنَا لِيُق۪يمُوا الصَّلٰوةَ فَاجْعَلْ اَفْـِٔدَةً مِنَ النَّاسِ تَهْو۪ٓي اِلَيْهِمْ وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ', 'Rabbena inni eskentu min zurriyyeti bi vadin gayri zi zer\'ın inde beytilkel muharremi rabbena li yukimus salate fec\'al ef\'ideten minen nasi tehvi ileyhim verzukhum mines semerati leallehum yeşkurun.', '\"Rabbimiz! Gerçekten ben,  neslimden bir kısmını sahipsiz,  ekine elverişli olmayan vadiye; Beyt-i Haram\'ın[1] yanına yerleştirdim; Rabb\'imiz! Salatı ikame etsinler[2]. İnsanlardan bir kısmının gönlünü onlara yönelt. Ve onları kimi ürünlerle rızıklandır. Umulur ki onlar şükrederler.\"', 'ربنا اني اسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرم ربنا ليقيموا الصلوة فاجعل افدة من الناس تهوي اليهم وارزقهم من الثمرت لعلهم يشكرون'),
(1788, 14, 38, 'رَبَّـنَٓا اِنَّكَ تَعْلَمُ مَا نُخْف۪ي وَمَا نُعْلِنُۜ وَمَا يَخْفٰى عَلَى اللّٰهِ مِنْ شَيْءٍ فِي الْاَرْضِ وَلَا فِي السَّمَٓاءِ', 'Rabbena inneke ta\'lemu ma nuhfi ve ma nu\'lin, ve ma yahfa alallahi min şey\'infil ardı ve la fis sema.', '\"Rabb\'imiz! Sen,  gizlediğimiz ve açığa vurduğumuz her şeyi bilirsin. Yerde ve gökte hiçbir şey Allah\'a gizli kalmaz.\"', 'ربنا انك تعلم ما نخفي وما نعلن وما يخفي علي الله من شي في الارض ولا في السما'),
(1789, 14, 39, 'اَلْحَمْدُ لِلّٰهِ الَّذ۪ي وَهَبَ ل۪ي عَلَى الْكِبَرِ اِسْمٰع۪يلَ وَاِسْحٰقَۜ اِنَّ رَبّ۪ي لَسَم۪يعُ الدُّعَٓاءِ', 'Elhamdulillahillezi vehebe li alel kiberi ismaile ve ishak, inne rabbi le semiud dua.', '\"Hamd,  yaşlılığımda bana İsmail\'i ve İshak\'ı bağışlayan Allah\'a aittir. Kuşkusuz,  benim Rabbim duayı işitendir.\"', 'الحمد لله الذي وهب لي علي الكبر اسمعيل واسحق ان ربي لسميع الدعا'),
(1790, 14, 40, 'رَبِّ اجْعَلْن۪ي مُق۪يمَ الصَّلٰوةِ وَمِنْ ذُرِّيَّت۪يۗ رَبَّـنَا وَتَقَبَّلْ دُعَٓاءِ', 'Rabbic\'alni mukimas salati ve min zurriyyeti rabbena ve tekabbel dua.', '\"Rabbim! Beni ve soyumu salatı ikame eden[1] kıl. Rabbimiz isteğimi kabul et.\"', 'رب اجعلني مقيم الصلوة ومن ذريتي ربنا وتقبل دعا'),
(1791, 14, 41, 'رَبَّـنَا اغْفِرْ ل۪ي وَلِوَالِدَيَّ وَلِلْمُؤْمِن۪ينَ يَوْمَ يَقُومُ الْحِسَابُ۟', 'Rabbenagfirli ve li valideyye ve lil mu\'minine yevme yekumul hisab.', '\"Rabb\'imiz! Hesabın görüleceği gün,  beni,  annemi,  babamı ve Mü\'minleri affet.\"', 'ربنا اغفر لي ولولدي وللمومنين يوم يقوم الحساب'),
(1792, 14, 42, 'وَلَا تَحْسَبَنَّ اللّٰهَ غَافِلاً عَمَّا يَعْمَلُ الظَّالِمُونَۜ اِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ ف۪يهِ الْاَبْصَارُۙ', 'Ve la tahsebennallahe gafilen amma ya\'meluz zalimun, innema yuahhıruhum li yevmin teşhasu fihil ebsar.', 'Sakın zalimlerin yaptıkları şeylerden Allah\'ı gafil sanma. O hesaplaşmayı gözlerin dehşetten donup kalacağı güne erteliyor.', 'ولا تحسبن الله غفلا عما يعمل الظلمون انما يوخرهم ليوم تشخص فيه الابصر'),
(1793, 14, 43, 'مُهْطِع۪ينَ مُقْنِع۪ي رُؤُ۫سِهِمْ لَا يَرْتَدُّ اِلَيْهِمْ طَرْفُهُمْۚ وَاَفْـِٔدَتُهُمْ هَوَٓاءٌۜ', 'Muhtıine muknii ruusihim la yerteddu ileyhim tarfuhum, ve ef\'idetuhum heva\'.', 'Başlarını yukarı dikerek[1],  bakışları donup kalmış bir şekilde umutsuzca koşarlar.[2]', 'مهطعين مقنعي روسهم لا يرتد اليهم طرفهم وافدتهم هوا'),
(1794, 14, 44, 'وَاَنْذِرِ النَّاسَ يَوْمَ يَأْت۪يهِمُ الْعَذَابُۙ فَيَقُولُ الَّذ۪ينَ ظَلَمُوا رَبَّـنَٓا اَخِّرْنَٓا اِلٰٓى اَجَلٍ قَر۪يبٍۙ نُجِبْ دَعْوَتَكَ وَنَتَّبِـعِ الرُّسُلَۜ اَوَلَمْ تَكُونُٓوا اَقْسَمْتُمْ مِنْ قَبْلُ مَا لَكُمْ مِنْ زَوَالٍۙ', 'Ve enzirin nase yevme ye\'tihimul azabu fe yekulullezine zalemu rabbena ahhırna ila ecelin karibin nucib da\'veteke ve nettebiır rusul, e ve lem tekunu aksemtum min kablu ma lekum min zeval.', 'Azabın kendilerine geleceği gün ile insanları uyar. O zaman kendilerine haksızlık[1] yapanlar: \"Rabb\'imiz! Bize biraz daha süre ver de Senin çağrını kabul edelim ve resullere uyalım.\" diyecekler. Allah da: \"Daha önce sizin için bir tükenişin,  inişe geçişin olmadığına yemin edenler sizler değil miydiniz?\" diyecek.', 'وانذر الناس يوم ياتيهم العذاب فيقول الذين ظلموا ربنا اخرنا الي اجل قريب نجب دعوتك ونتبع الرسل اولم تكونوا اقسمتم من قبل ما لكم من زوال'),
(1795, 14, 45, 'وَسَكَنْتُمْ ف۪ي مَسَاكِنِ الَّذ۪ينَ ظَلَمُٓوا اَنْفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ الْاَمْثَالَ', 'Ve sekentum fi mesakinillezine zalemu enfusehum ve tebeyyene lekum keyfe fealna bihimve darabna lekumul emsal.', 'Ve siz,  kendilerine zulmeden halkların yurtlarında yaşadınız. Onlara neler yaptığımız sizlere belli olmuştu,  örneklerle açıklamıştık.', 'وسكنتم في مسكن الذين ظلموا انفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم الامثال'),
(1796, 14, 46, 'وَقَدْ مَكَرُوا مَكْرَهُمْ وَعِنْدَ اللّٰهِ مَكْرُهُمْۜ وَاِنْ كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ الْجِبَالُ', 'Ve kad mekeru mekrehum ve indallahi mekruhum, ve in kane mekruhum li tezule minhul cibal.', 'Onlar,  her türlü planı yapmışlardı. Oysaki dağları yerinden oynatacak derecede güçlü olduğunu sandıkları planları Allah\'ın denetimi altındadır.', 'وقد مكروا مكرهم وعند الله مكرهم وان كان مكرهم لتزول منه الجبال'),
(1797, 14, 47, 'فَلَا تَحْسَبَنَّ اللّٰهَ مُخْلِفَ وَعْدِه۪ رُسُلَهُۜ اِنَّ اللّٰهَ عَز۪يزٌ ذُوانْتِقَامٍۜ', 'Fe la tahsebennallahe muhlife va\'dihi rusuleh, innallahe azizun zuntikam.', 'Öyleyse sakın Allah\'ın resullerine verdiği sözden cayacağını sanma! Allah,  Mutlak Üstün Olan\'dır,  Hesap Sorucu\'dur.', 'فلا تحسبن الله مخلف وعده رسله ان الله عزيز ذو انتقام'),
(1798, 14, 48, 'يَوْمَ تُبَدَّلُ الْاَرْضُ غَيْرَ الْاَرْضِ وَالسَّمٰوَاتُ وَبَرَزُوا لِلّٰهِ الْوَاحِدِ الْقَهَّارِ', 'Yevme tubeddelul ardu gayrel ardı ves semavatu ve berezu lillahil vahıdil kahhar.', 'O gün yeryüzü ve gökler başka bir hale dönüştürülür. Ve onlar,  bir ve gücüne karşı konulamaz Allah\'ın huzuruna çıkarlar.', 'يوم تبدل الارض غير الارض والسموت وبرزوا لله الوحد القهار'),
(1799, 14, 49, 'وَتَرَى الْمُجْرِم۪ينَ يَوْمَئِذٍ مُقَرَّن۪ينَ فِي الْاَصْفَادِۚ', 'Ve terel mucrimine yevme izin mukarrenine fil asfad.', 'İzin Günü[1]; suçluları,  birbirlerine yaklaştırılarak zincirlere vurulmuş görürsün.', 'وتري المجرمين يوميذ مقرنين في الاصفاد'),
(1800, 14, 50, 'سَرَاب۪يلُهُمْ مِنْ قَطِرَانٍ وَتَغْشٰى وُجُوهَهُمُ النَّارُۙ', 'Serabiluhum min katıranin ve tagşa vucuhehumun nar.', 'Onların giysileri katrandandır ve yüzlerini ateş sarmıştır.', 'سرابيلهم من قطران وتغشي وجوههم النار'),
(1801, 14, 51, 'لِيَجْزِيَ اللّٰهُ كُلَّ نَفْسٍ مَا كَسَبَتْۜ اِنَّ اللّٰهَ سَر۪يعُ الْحِسَابِ', 'Li yecziyallahu kulle nefsin ma kesebet, innallahe seriul hısab.', 'Allah,  herkese kazandığına göre karşılık verecektir. Kuşkusuz Allah,  hesabı çabuk görendir.', 'ليجزي الله كل نفس ما كسبت ان الله سريع الحساب'),
(1802, 14, 52, 'هٰذَا بَلَاغٌ لِلنَّاسِ وَلِيُنْذَرُوا بِه۪ وَلِيَعْلَمُٓوا اَنَّمَا هُوَ اِلٰهٌ وَاحِدٌ وَلِيَذَّكَّرَ اُو۬لُوا الْاَلْبَابِ', 'Haza belagun lin nasi ve li yunzeru bihi ve li ya\'lemu ennema huve ilahun vahidun ve li yezzekkere ulul elbab.', 'Bu Kur\'an,  kendisiyle uyarılmaları,  Allah\'ın bir tek ilah olduğunun bilinmesi ve sağlıklı düşünen akıl sahiplerinin öğüt almaları için insanlara bir mesajdır.', 'هذا بلغ للناس ولينذروا به وليعلموا انما هو اله وحد وليذكر اولوا الالبب'),
(1803, 15, 1, 'الٓـرٰ۠ تِلْكَ اٰيَاتُ الْكِتَابِ وَقُرْاٰنٍ مُب۪ينٍ', 'Elif lam ra tilke ayatul kitabi ve kur\'anin mubin.', 'Elif,  Lam,  Ra. İşte bunlar,  Kitap\'ın[1] ve Kur\'an-ı Mubin\'in[2] ayetleridir.', 'الر تلك ايت الكتب وقران مبين'),
(1804, 15, 2, 'رُبَمَا يَوَدُّ الَّذ۪ينَ كَفَرُوا لَوْ كَانُوا مُسْلِم۪ينَ', 'Rubema yeveddullezine keferu lev kanu muslimin.', 'Gün gelecek,  Kafirler[1]: \"Keşke Müslüman olsaydık.\" diye yakınacaklar.', 'ربما يود الذين كفروا لو كانوا مسلمين'),
(1805, 15, 3, 'ذَرْهُمْ يَأْكُلُوا وَيَتَمَتَّعُوا وَيُلْهِهِمُ الْاَمَلُ فَسَوْفَ يَعْلَمُونَ', 'Zerhum ye\'kulu ve yetemetteu ve yulhihimul emelu fe sevfe ya\'lemun.', 'Bırak onları; yiyip,  içip faydalansınlar; beklentileri onları oyalasın. Fakat yakında gerçeği anlayacaklar.[1]', 'ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون'),
(1806, 15, 4, 'وَمَٓا اَهْلَكْنَا مِنْ قَرْيَةٍ اِلَّا وَلَهَا كِتَابٌ مَعْلُومٌ', 'Ve ma ehlekna min karyetin illa ve leha kitabun ma\'lum.', 'Biz,  hiçbir kenti,  bilinen bir kitabı[1] olmaksızın helak etmedik.', 'وما اهلكنا من قرية الا ولها كتاب معلوم'),
(1807, 15, 5, 'مَا تَسْبِقُ مِنْ اُمَّةٍ اَجَلَهَا وَمَا يَسْتَأْخِرُونَ', 'Ma tesbiku min ummetin eceleha ve ma yeste\'hırun.', 'Hiçbir toplum,  ecelini öne alamaz ve geciktiremez.', 'ما تسبق من امة اجلها وما يستخرون'),
(1808, 15, 6, 'وَقَالُوا يَٓا اَيُّهَا الَّذ۪ي نُزِّلَ عَلَيْهِ الذِّكْرُ اِنَّكَ لَمَجْنُونٌۜ', 'Ve kalu ya eyyuhellezi nuzzile aleyhiz zikru inneke le mecnun.', '\"Ey! Kendisine Zikir[1] indirildiğini söyleyen,  sen gerçekten mecnunsun!\"[2] dediler.', 'وقالوا يايها الذي نزل عليه الذكر انك لمجنون'),
(1809, 15, 7, 'لَوْ مَا تَأْت۪ينَا بِالْمَلٰٓئِكَةِ اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Lev ma te\'tina bil melaiketi in kunte minas sadıkin.', '\"Eğer doğru söylüyorsan,  bize melekleri getir de görelim!\"[1]', 'لو ما تاتينا بالمليكة ان كنت من الصدقين'),
(1810, 15, 8, 'مَا نُنَزِّلُ الْمَلٰٓئِكَةَ اِلَّا بِالْحَقِّ وَمَا كَانُٓوا اِذاً مُنْظَر۪ينَ', 'Ma nunezzilul melaikete illa bil hakkı ve ma kanu izen munzarin.', 'Biz,  melekleri ancak Hakk ile[1] indiririz. O zaman da işleri bitirilmiş olur.', 'ما ننزل المليكة الا بالحق وما كانوا اذا منظرين'),
(1811, 15, 9, 'اِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَاِنَّا لَهُ لَحَافِظُونَ', 'İnna nahnu nezzelnez zikre ve inna lehu le hafizun.', 'Zikri[1] Biz indirdik ve kesinlikle onun koruyucusu[2] da Biziz.[3]', 'انا نحن نزلنا الذكر وانا له لحفظون'),
(1812, 15, 10, 'وَلَقَدْ اَرْسَلْنَا مِنْ قَبْلِكَ ف۪ي شِيَعِ الْاَوَّل۪ينَ', 'Ve le kad erselna min kablike fi şiyaıl evvelin.', 'Ve ant olsun ki senden önceki geçmiş topluluklara da gönderdik[1].', 'ولقد ارسلنا من قبلك في شيع الاولين'),
(1813, 15, 11, 'وَمَا يَأْت۪يهِمْ مِنْ رَسُولٍ اِلَّا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Ve ma ye\'tihim min resulin illa kanu bihi yestehziun.', 'Kendilerine gelen resullerden alay etmedikleri hiç kimse olmadı.', 'وما ياتيهم من رسول الا كانوا به يستهزون'),
(1814, 15, 12, 'كَذٰلِكَ نَسْلُكُهُ ف۪ي قُلُوبِ الْمُجْرِم۪ينَۙ', 'Kezalike neslukuhu fi kulubil mucrimin.', 'Böylece onu[1] mücrimlerin[2] kalplerine sokarız.', 'كذلك نسلكه في قلوب المجرمين'),
(1815, 15, 13, 'لَا يُؤْمِنُونَ بِه۪ وَقَدْ خَلَتْ سُنَّةُ الْاَوَّل۪ينَ', 'La yu\'minune bihi ve kad halet sunnetul evvelin.', 'Kendilerinden öncekilerin sünneti[1] geçtiği halde ona inanmazlar.', 'لا يومنون به وقد خلت سنة الاولين'),
(1816, 15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِمْ بَاباً مِنَ السَّمَٓاءِ فَظَلُّوا ف۪يهِ يَعْرُجُونَۙ', 'Ve lev fetahna aleyhim baben mines semai fe zallu fihi ya\'rucun.', 'Gökten bir kapı açsak da oraya çıksalar bile.', 'ولو فتحنا عليهم بابا من السما فظلوا فيه يعرجون'),
(1817, 15, 15, 'لَقَالُٓوا اِنَّمَا سُكِّرَتْ اَبْصَارُنَا بَلْ نَحْنُ قَوْمٌ مَسْحُورُونَ۟', 'Le kalu innema sukkiret ebsaruna bel nahnu kavmun meshurun.', '\"Herhalde gözlerimiz döndürüldü[1],  doğrusu büyülenmiş bir topluluğuz.\" derlerdi.', 'لقالوا انما سكرت ابصرنا بل نحن قوم مسحورون'),
(1818, 15, 16, 'وَلَقَدْ جَعَلْنَا فِي السَّمَٓاءِ بُرُوجاً وَزَيَّنَّاهَا لِلنَّاظِر۪ينَۙ', 'Ve le kad cealna fis semai burucen ve zeyyennaha lin nazırin.', 'Ant olsun,  Biz,  semada burçlar yaptık ve bakanlar için onu donattık.', 'ولقد جعلنا في السما بروجا وزينها للنظرين'),
(1819, 15, 17, 'وَحَفِظْنَاهَا مِنْ كُلِّ شَيْطَانٍ رَج۪يمٍۙ', 'Ve hafıznaha min kulli şeytanin recim.', 'Onu her racim[1] şeytandan[2] koruduk.', 'وحفظنها من كل شيطن رجيم'),
(1820, 15, 18, 'اِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَاَتْبَعَهُ شِهَابٌ مُب۪ينٌ', 'İlla menisterakas sem\'a fe etbeahu şihabun mubin.', 'Ancak,  kulak hırsızlığı yapan olursa,  onu parlak bir alev kovalar.[1]', 'الا من استرق السمع فاتبعه شهاب مبين'),
(1821, 15, 19, 'وَالْاَرْضَ مَدَدْنَاهَا وَاَلْقَيْنَا ف۪يهَا رَوَاسِيَ وَاَنْبَتْنَا ف۪يهَا مِنْ كُلِّ شَيْءٍ مَوْزُونٍ', 'Vel arda medednaha ve elkayna fiha revasiye ve enbetna fiha min kulli şey\'in mevzun.', 'Yeryüzünü yaydık ve oraya ağır baskılar yerleştirdik. Ve orada her türlü bitkiyi bir ölçüye göre yetiştirdik.', 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل شي موزون'),
(1822, 15, 20, 'وَجَعَلْنَا لَكُمْ ف۪يهَا مَعَايِشَ وَمَنْ لَسْتُمْ لَهُ بِرَازِق۪ينَ', 'Ve cealna lekum fiha meayişe ve men lestum lehu bi razıkin.', 'Sizin için de geçimlerini sizin sağlamadıklarınız için de orada,  geçim kaynakları meydana getirdik.', 'وجعلنا لكم فيها معيش ومن لستم له برزقين'),
(1823, 15, 21, 'وَاِنْ مِنْ شَيْءٍ اِلَّا عِنْدَنَا خَزَٓائِنُهُۘ وَمَا نُنَزِّلُـهُٓ اِلَّا بِقَدَرٍ مَعْلُومٍ', 'Ve in min şey\'in illa indena hazainuhu ve ma nunezziluhu illa bi kaderin ma\'lum.', 'Hazineleri Bizim yanımızda olmayan hiçbir şey yoktur. Ve Biz,  bilinen bir kaderi olmaksızın[1] onu indirmeyiz.', 'وان من شي الا عندنا خزاينه وما ننزله الا بقدر معلوم'),
(1824, 15, 22, 'وَاَرْسَلْنَا الرِّيَاحَ لَوَاقِـحَ فَاَنْزَلْنَا مِنَ السَّمَٓاءِ مَٓاءً فَاَسْقَيْنَاكُمُوهُۚ وَمَٓا اَنْتُمْ لَهُ بِخَازِن۪ينَ', 'Ve erselner riyaha levakıha fe enzelna mines semai maen fe eskaynakumuh, ve ma entum lehu bi hazinin.', 'Biz,  rüzgarları aşılayıcı[1] olarak gönderdik de böylece gökten su indirdik ve sizi onunla suya kavuşturduk. Onun hazinelerini[2] oluşturan siz değilsiniz.', 'وارسلنا الريح لوقح فانزلنا من السما ما فاسقينكموه وما انتم له بخزنين'),
(1825, 15, 23, 'وَاِنَّا لَنَحْنُ نُحْـي۪ وَنُم۪يتُ وَنَحْنُ الْوَارِثُونَ', 'Ve inna le nahnu nuhyi ve numitu ve nahnul varisun.', 'Sadece Biz diriltir ve Biz öldürürüz. Ve varis[1] olan da Biziz.', 'وانا لنحن نحي ونميت ونحن الورثون'),
(1826, 15, 24, 'وَلَقَدْ عَلِمْنَا الْمُسْتَقْدِم۪ينَ مِنْكُمْ وَلَقَدْ عَلِمْنَا الْمُسْتَأْخِر۪ينَ', 'Ve le kad alimnel mustakdimine minkum ve le kad alimnel muste\'hırin.', 'Ant olsun ki,  sizden öncekileri biliyoruz. Ve ant olsun ki sizden sonrakileri de biliyoruz.', 'ولقد علمنا المستقدمين منكم ولقد علمنا المستخرين'),
(1827, 15, 25, 'وَاِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْۜ اِنَّهُ حَك۪يمٌ عَل۪يمٌ۟', 'Ve inne rabbeke huve yahşuruhum, innehu hakimun alim.', 'Rabb\'in,  bizzat onları haşreder.[1] Kuşkusuz O,  En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'وان ربك هو يحشرهم انه حكيم عليم'),
(1828, 15, 26, 'وَلَقَدْ خَلَقْنَا الْاِنْسَانَ مِنْ صَلْصَالٍ مِنْ حَمَأٍ مَسْنُونٍۚ', 'Ve le kad halaknel insane min salsalin min hamein mesnun.', 'Ant olsun ki; Biz,  insanı salsalinden[1],  dönüşüme uğramış bir balçıktan yarattık.', 'ولقد خلقنا الانسن من صلصل من حما مسنون'),
(1829, 15, 27, 'وَالْجَٓانَّ خَلَقْنَاهُ مِنْ قَبْلُ مِنْ نَارِ السَّمُومِ', 'Vel canne halaknahu min kablu min naris semum.', 'Cinni daha önce \"Semum\'un ateşinden\"[1] yarattık.', 'والجان خلقنه من قبل من نار السموم'),
(1830, 15, 28, 'وَاِذْ قَالَ رَبُّكَ لِلْمَلٰٓئِكَةِ اِنّ۪ي خَالِقٌ بَشَراً مِنْ صَلْصَالٍ مِنْ حَمَأٍ مَسْنُونٍ', 'Ve iz kale rabbuke lil melaiketi inni halikun beşeren min salsalin min hamein mesnun.', 'Hani Rabb\'in meleklere: \"Ben salsalinden[1],  dönüşüme uğramış bir balçıktan,  bir beşer[1] yaratacağım.\" demişti.', 'واذ قال ربك للمليكة اني خلق بشرا من صلصل من حما مسنون'),
(1831, 15, 29, 'فَاِذَا سَوَّيْتُهُ وَنَفَخْتُ ف۪يهِ مِنْ رُوح۪ي فَقَعُوا لَهُ سَاجِد۪ينَ', 'Fe iza sevveytuhu ve nefahtu fihi min ruhi fekau lehu sacidin.', '\"Onu biçimlendirip ve ona ruhumdan üflediğimde[1],  hemen ona secde edin![2]\"', 'فاذا سويته ونفخت فيه من روحي فقعوا له سجدين'),
(1832, 15, 30, 'فَسَجَدَ الْمَلٰٓئِكَةُ كُلُّهُمْ اَجْمَعُونَۙ', 'Fe secedel melaiketu kulluhum ecmaun.', 'Bunun üzerine bütün melekler ona secde ettiler.', 'فسجد المليكة كلهم اجمعون'),
(1833, 15, 31, 'اِلَّٓا اِبْل۪يسَۜ اَبٰٓى اَنْ يَكُونَ مَعَ السَّاجِد۪ينَ', 'İlla iblis, eba en yekune meas sacidin.', 'İblis hariç. O,  secde edenlerle birlikte olmaktan kaçındı.', 'الا ابليس ابي ان يكون مع السجدين'),
(1834, 15, 32, 'قَالَ يَٓا اِبْل۪يسُ مَا لَكَ اَلَّا تَكُونَ مَعَ السَّاجِد۪ينَ', 'Kale ya iblisu ma leke ella tekune meas sacidin.', '\"Ey iblis! Neden secde edenlerle birlikte olmadın?\" dedi.', 'قال يابليس ما لك الا تكون مع السجدين'),
(1835, 15, 33, 'قَالَ لَمْ اَكُنْ لِاَسْجُدَ لِبَشَرٍ خَلَقْتَهُ مِنْ صَلْصَالٍ مِنْ حَمَأٍ مَسْنُونٍ', 'Kale lem ekun li escude li beşerin halaktehu min salsalin min hamein mesnun.', 'İblis: \"Ben; salsalinden[1],  dönüşüme uğramış bir balçıktan yarattığın bir beşere[2],  secde etmem.\" dedi', 'قال لم اكن لاسجد لبشر خلقته من صلصل من حما مسنون'),
(1836, 15, 34, 'قَالَ فَاخْرُجْ مِنْهَا فَاِنَّكَ رَج۪يمٌ', 'Kale fahruc minha fe inneke recim.', 'Allah: \"Çık oradan! Sen kesinlikle kovulmuş birisin.\" dedi.', 'قال فاخرج منها فانك رجيم'),
(1837, 15, 35, 'وَاِنَّ عَلَيْكَ اللَّعْنَةَ اِلٰى يَوْمِ الدّ۪ينِ', 'Ve inne aleykel la\'nete ila yevmid din.', '\"Lanet[1],  Din Günü\'ne kadar senin üzerindedir.\" dedi.', 'وان عليك اللعنة الي يوم الدين'),
(1838, 15, 36, 'قَالَ رَبِّ فَاَنْظِرْن۪ٓي اِلٰى يَوْمِ يُبْعَثُونَ', 'Kale rabbi fe enzırni ila yevmi yub\'asun.', 'İblis: \"Rabbim! Öyleyse yeniden diriltilecekleri güne kadar,  bana süre tanı.\" dedi.', 'قال رب فانظرني الي يوم يبعثون'),
(1839, 15, 37, 'قَالَ فَاِنَّكَ مِنَ الْمُنْظَر۪ينَۙ', 'Kale fe inneke minel munzarin.', 'Allah: \"Sen,  süre verilenlerdensin;\"[1]', 'قال فانك من المنظرين'),
(1840, 15, 38, 'اِلٰى يَوْمِ الْوَقْتِ الْمَعْلُومِ', 'İla yevmil vaktil ma\'lum.', '\"Bilinen zamanın gününe kadar.\" dedi.', 'الي يوم الوقت المعلوم'),
(1841, 15, 39, 'قَالَ رَبِّ بِمَٓا اَغْوَيْتَن۪ي لَاُزَيِّنَنَّ لَهُمْ فِي الْاَرْضِ وَلَاُغْوِيَنَّهُمْ اَجْمَع۪ينَۙ', 'Kale rabbi bi ma agveyteni le uzeyyinenne lehum fil ardı ve le ugviyennehum ecmein.', 'İblis: \"Rabbim! Beni azdırmandan dolayı[1],  ben de yeryüzündeki her şeyi cazip göstererek,  kesinlikle onların hepsini azdıracağım.[2]\"', 'قال رب بما اغويتني لازينن لهم في الارض ولاغوينهم اجمعين'),
(1842, 15, 40, 'اِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَص۪ينَ', 'İlla ıbadeke minhumul muhlasin.', '\"Ancak onlardan muhles[1] kulların hariç.\"', 'الا عبادك منهم المخلصين'),
(1843, 15, 41, 'قَالَ هٰذَا صِرَاطٌ عَلَيَّ مُسْتَق۪يمٌ', 'Kale haza sıratun aleyye mustekim.', 'Allah: \"Bu,  Bana varan dosdoğru yoldur.[1]\" dedi.', 'قال هذا صرط علي مستقيم'),
(1844, 15, 42, 'اِنَّ عِبَاد۪ي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ اِلَّا مَنِ اتَّبَعَكَ مِنَ الْغَاو۪ينَ', 'İnne ıbadi leyse leke aleyhim sultanun illa menittebeake minel gavin.', 'Sana uyan azgınlar hariç,  kullarım üzerinde hiçbir yaptırım gücün yoktur.', 'ان عبادي ليس لك عليهم سلطن الا من اتبعك من الغاوين'),
(1845, 15, 43, 'وَاِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ اَجْمَع۪ينَۙ', 'Ve inne cehenneme le mev\'ıduhum ecmain.', 'Onların tamamının buluşma yeri Cehennem\'dir.', 'وان جهنم لموعدهم اجمعين'),
(1846, 15, 44, 'لَهَا سَبْعَةُ اَبْوَابٍۜ لِكُلِّ بَابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ۟', 'Leha seb\'atu ebvab, likulli babin minhum cuz\'un maksum.', 'Onun yedi[1] kapısı vardır. Her kapıya onlardan bir grup ayrılmıştır.', 'لها سبعة ابوب لكل باب منهم جز مقسوم'),
(1847, 15, 45, 'اِنَّ الْمُتَّق۪ينَ ف۪ي جَنَّاتٍ وَعُيُونٍۜ', 'İnnel muttekine fi cennatin ve uyun.', 'Takva[1] sahipleri,  Cennetlerde ve pınarların başlarındadırlar.', 'ان المتقين في جنت وعيون'),
(1848, 15, 46, 'اُدْخُلُوهَا بِسَلَامٍ اٰمِن۪ينَ', 'Udhuluha bi selamin aminin.', 'Onlara: \"Güven ve esenlik içinde oraya girin.\" denecek.', 'ادخلوها بسلم امنين'),
(1849, 15, 47, 'وَنَزَعْنَا مَا ف۪ي صُدُورِهِمْ مِنْ غِلٍّ اِخْوَاناً عَلٰى سُرُرٍ مُتَقَابِل۪ينَ', 'Ve neza\'na ma fi sudurihim min gıllin ıhvanen ala sururin mutekabilin.', 'Ve onların göğüslerindeki kötü duyguların tamamını yok ettik. Onlar,  kardeşler olarak,  tahtlar üzerinde karşı karşıya otururlar.', 'ونزعنا ما في صدورهم من غل اخونا علي سرر متقبلين'),
(1850, 15, 48, 'لَا يَمَسُّهُمْ ف۪يهَا نَصَبٌ وَمَا هُمْ مِنْهَا بِمُخْرَج۪ينَ', 'La yemessuhum fiha nasabun ve ma hum minha bi muhrecin.', 'Orada,  kendilerine hiçbir yorgunluk dokunmaz ve oradan hiç çıkarılmayacaklardır.', 'لا يمسهم فيها نصب وما هم منها بمخرجين'),
(1851, 15, 49, 'نَبِّئْ عِبَاد۪ٓي اَنّ۪ٓي اَنَا الْغَفُورُ الرَّح۪يمُۙ', 'Nebbi\' ibadi enni enel gafurur rahim.', 'Kullarıma haber ver: \"Ben,  Çok Bağışlayıcıyım,  Kesintisiz Rahmet Sahibiyim.\"', 'نبي عبادي اني انا الغفور الرحيم'),
(1852, 15, 50, 'وَاَنَّ عَذَاب۪ي هُوَ الْعَذَابُ الْاَل۪يمُ', 'Ve enne azabi huvel azabul elim.', 'Fakat azabım,  elem verici bir azaptır.', 'وان عذابي هو العذاب الاليم'),
(1853, 15, 51, 'وَنَبِّئْهُمْ عَنْ ضَيْفِ اِبْرٰه۪يمَۢ', 'Ve nebbi\'hum an dayfi ibrahim.', 'Onlara İbrahim\'in misafirlerinden haber ver.', 'ونبيهم عن ضيف ابرهيم'),
(1854, 15, 52, 'اِذْ دَخَلُوا عَلَيْهِ فَقَالُوا سَلَاماًۜ قَالَ اِنَّا مِنْكُمْ وَجِلُونَ', 'İz dehalu aleyhi fe kalu selama, kale inna minkum vecilun.', 'İbrahim\'in yanına girdiklerinde,  \"Selam.\" dediler. İbrahim: \"Doğrusu,  sizden korkuyoruz.\" dedi.', 'اذ دخلوا عليه فقالوا سلما قال انا منكم وجلون'),
(1855, 15, 53, 'قَالُوا لَا تَوْجَلْ اِنَّا نُبَشِّرُكَ بِغُلَامٍ عَل۪يمٍ', 'Kalu la tevcel inna nubeşşiruke bi gulamin alim.', 'Onlar: \"Korkma! Biz,  sana alim[1] bir oğul müjdeliyoruz.\" dediler.', 'قالوا لا توجل انا نبشرك بغلم عليم'),
(1856, 15, 54, 'قَالَ اَبَشَّرْتُمُون۪ي عَلٰٓى اَنْ مَسَّنِيَ الْكِبَرُ فَبِمَ تُبَشِّرُونَ', 'Kale e beşşertumuni ala en messeniyel kiberu fe bime tubeşşirun.', 'İbrahim: \"Ben yaşlı bir beşer olduğum halde mi,  beni müjdeliyorsunuz? Neye dayanarak bu müjdeyi veriyorsunuz?\"', 'قال ابشرتموني علي ان مسني الكبر فبم تبشرون'),
(1857, 15, 55, 'قَالُوا بَشَّرْنَاكَ بِالْحَقِّ فَلَا تَكُنْ مِنَ الْقَانِط۪ينَ', 'Kalu beşşernake bil hakkı fe la tekun minel kanıtin.', 'Onlar: \"Seni,  hakk[1] ile müjdeliyoruz. Asla ümidini kesenlerden olma.\" dediler.', 'قالوا بشرنك بالحق فلا تكن من القنطين'),
(1858, 15, 56, 'قَالَ وَمَنْ يَقْنَطُ مِنْ رَحْمَةِ رَبِّه۪ٓ اِلَّا الضَّٓالُّونَ', 'Kale ve men yaknetu min rahmeti rabbihi illad dallun.', 'İbrahim: \"Rabb\'inin rahmetinden,  sapkınlardan başka kim ümidini keser?\" dedi.', 'قال ومن يقنط من رحمة ربه الا الضالون'),
(1859, 15, 57, 'قَالَ فَمَا خَطْبُكُمْ اَيُّهَا الْمُرْسَلُونَ', 'Kale fe ma hatbukum eyyuhel murselun.', 'İbrahim: \"Ey elçiler! Sizin niyetiniz ne?\" dedi.', 'قال فما خطبكم ايها المرسلون'),
(1860, 15, 58, 'قَالُٓوا اِنَّٓا اُرْسِلْـنَٓا اِلٰى قَوْمٍ مُجْرِم۪ينَۙ', 'Kalu inna ursilna ila kavmin mucrimin.', '\"Biz,  suç işleyen bir halka gönderildik.\" dediler.', 'قالوا انا ارسلنا الي قوم مجرمين'),
(1861, 15, 59, 'اِلَّٓا اٰلَ لُوطٍۜ اِنَّا لَمُنَجُّوهُمْ اَجْمَع۪ينَۙ', 'İlla ale lut, inna le muneccuhum ecma\'in.', '\"Ancak Lut ailesinin[1] tamamını kurtaracağız.\"', 'الا ال لوط انا لمنجوهم اجمعين'),
(1862, 15, 60, 'اِلَّا امْرَاَتَهُ قَدَّرْنَٓاۙ اِنَّهَا لَمِنَ الْغَابِر۪ينَ۟', 'İllemre\'etehu kadderna inneha le minel gabirin.', 'Onun karısı hariç. Onun,  mutlaka geride kalanlardan olmasını takdir ettik.[1]', 'الا امراته قدرنا انها لمن الغبرين'),
(1863, 15, 61, 'فَلَمَّا جَٓاءَ اٰلَ لُوطٍۨ الْمُرْسَلُونَۙ', 'Fe lemma cae ale lutınil murselun.', 'Elçiler,  Lut\'un ailesine geldiklerinde,', 'فلما جا ال لوط المرسلون'),
(1864, 15, 62, 'قَالَ اِنَّكُمْ قَوْمٌ مُنْكَرُونَ', 'Kale innekum kavmun munkerun.', 'Lut: \"Doğrusu çekinilecek kimselersiniz.\" dedi.', 'قال انكم قوم منكرون'),
(1865, 15, 63, 'قَالُوا بَلْ جِئْنَاكَ بِمَا كَانُوا ف۪يهِ يَمْتَرُونَ', 'Kalu bel ci\'nake bi ma kanu fihi yemterun.', 'Elçiler: \"Hayır! Biz sana hakkında kuşku duyulan azabın haberini getirdik;\"', 'قالوا بل جينك بما كانوا فيه يمترون'),
(1866, 15, 64, 'وَاَتَيْنَاكَ بِالْحَقِّ وَاِنَّا لَصَادِقُونَ', 'Ve eteynake bil hakkı ve inna le sadikun.', '\"Doğru söyleyenleriz! Biz sana Hakk\'ı[1] getirdik.\"', 'واتينك بالحق وانا لصدقون'),
(1867, 15, 65, 'فَاَسْرِ بِاَهْلِكَ بِقِطْعٍ مِنَ الَّيْلِ وَاتَّبِـعْ اَدْبَارَهُمْ وَلَا يَلْتَفِتْ مِنْكُمْ اَحَدٌ وَامْضُوا حَيْثُ تُؤْمَرُونَ', 'Fe esri bi ehlike bi kıt\'ın minel leyli vettebı\' edbarehum ve la yeltefit minkum ehadun vamdu haysu tu\'merun.', '\"Hemen gecenin bir bölümünde,  aileni[1] yola çıkar,  arkalarından onları takip et. Sağa sola takılıp oyalanmadan,  bir an önce emrolunduğunuz[2] yere doğru gidin.\"', 'فاسر باهلك بقطع من اليل واتبع ادبرهم ولا يلتفت منكم احد وامضوا حيث تومرون'),
(1868, 15, 66, 'وَقَضَيْنَٓا اِلَيْهِ ذٰلِكَ الْاَمْرَ اَنَّ دَابِرَ هٰٓؤُ۬لَٓاءِ مَقْطُوعٌ مُصْبِح۪ينَ', 'Ve kadayna ileyhi zalikel emre enne dabire haulai maktuun musbihin.', 'Sabaha girerlerken,  onların kökünün kesileceği kararımızı,  ona bildirdik.', 'وقضينا اليه ذلك الامر ان دابر هولا مقطوع مصبحين'),
(1869, 15, 67, 'وَجَٓاءَ اَهْلُ الْمَد۪ينَةِ يَسْتَبْشِرُونَ', 'Ve cae ehlul medineti yestebşirun.', 'Şehir[1] halkı sevinerek geldiler.', 'وجا اهل المدينة يستبشرون'),
(1870, 15, 68, 'قَالَ اِنَّ هٰٓؤُ۬لَٓاءِ ضَيْف۪ي فَلَا تَفْضَحُونِۙ', 'Kale inne haulai dayfi fe la tefdahun.', 'Lut: \"Bunlar benim misafirlerim. Sakın beni mahcup etmeyin;', 'قال ان هولا ضيفي فلا تفضحون'),
(1871, 15, 69, 'وَاتَّقُوا اللّٰهَ وَلَا تُخْزُونِ', 'Vettekullahe ve la tuhzun.', 'Allah\'a karşı takva sahibi olun. Beni rezil etmeyin.\" dedi.', 'واتقوا الله ولا تخزون'),
(1872, 15, 70, 'قَالُٓوا اَوَلَمْ نَنْهَكَ عَنِ الْعَالَم۪ينَ', 'Kalu e ve lem nenheke anil alemin.', 'Şehir[1] halkı: \"Seni,  başkalarının işine karışmaktan men etmedik mi?\" dediler.', 'قالوا اولم ننهك عن العلمين'),
(1873, 15, 71, 'قَالَ هٰٓؤُ۬لَٓاءِ بَنَات۪ٓي اِنْ كُنْتُمْ فَاعِل۪ينَۜ', 'Kale haulai benati in kuntum failin.', 'Lut. \"Eğer bir şey yapacaksanız işte kızlarım.[1]\" dedi.', 'قال هولا بناتي ان كنتم فعلين'),
(1874, 15, 72, 'لَعَمْرُكَ اِنَّهُمْ لَف۪ي سَكْرَتِهِمْ يَعْمَهُونَ', 'Le amruke innehum le fi sekretihim ya\'mehun.', 'Ömrüne ant olsun ki,  onlar sarhoşlukları içinde bocalayıp duruyorlardı.', 'لعمرك انهم لفي سكرتهم يعمهون'),
(1875, 15, 73, 'فَاَخَذَتْهُمُ الصَّيْحَةُ مُشْرِق۪ينَۙ', 'Fe ehazethumus sayhatu muşrikin.', 'Tan yeri ağarırken korkunç bir ses onları yakaladı.', 'فاخذتهم الصيحة مشرقين'),
(1876, 15, 74, 'فَجَعَلْنَا عَالِيَهَا سَافِلَهَا وَاَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِنْ سِجّ۪يلٍۜ', 'Fe cealna aliyeha safileha ve emterna aleyhim hıcareten min siccil.', 'Böylece şehri altüst ettik ve üzerlerine balçıktan pişirilmiş taşlar yağdırdık.', 'فجعلنا عليها سافلها وامطرنا عليهم حجارة من سجيل'),
(1877, 15, 75, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِلْمُتَوَسِّم۪ينَ', 'İnne fi zalike le ayatin lil mutevessimin .', 'Bunda,  derin kavrayış yetisi[1] olanlar için kesinlikle ayetler[2] vardır.', 'ان في ذلك لايت للمتوسمين'),
(1878, 15, 76, 'وَاِنَّهَا لَبِسَب۪يلٍ مُق۪يمٍ', 'Ve inneha le bi sebilin mukim.', 'O[1],  bir yol üzerinde durmaktadır.', 'وانها لبسبيل مقيم'),
(1879, 15, 77, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِلْمُؤْمِن۪ينَۜ', 'İnne fi zalike le ayeten lil mu\'minin.', 'Bunda,  inananlar için bir ayet[1] vardır.', 'ان في ذلك لاية للمومنين'),
(1880, 15, 78, 'وَاِنْ كَانَ اَصْحَابُ الْاَيْكَةِ لَظَالِم۪ينَۙ', 'Ve in kane ashabul eyketi le zalimin .', 'Eykeliler gerçekten zalim kimselerdi.', 'وان كان اصحب الايكة لظلمين'),
(1881, 15, 79, 'فَانْتَقَمْنَا مِنْهُمْۢ وَاِنَّهُمَا لَبِاِمَامٍ مُب۪ينٍۜ۟', 'Fentekamna minhum, ve innehuma le bi imamin mubin.', 'Onlardan intikam aldık. İkisi[1] de kesinlikle açık bir rehberdir.[2]', 'فانتقمنا منهم وانهما لبامام مبين'),
(1882, 15, 80, 'وَلَقَدْ كَذَّبَ اَصْحَابُ الْحِجْرِ الْمُرْسَل۪ينَۙ', 'Ve le kad kezzebe ashabul hıcril murselin.', 'Ant olsun ki Hicr[1] halkı da gönderilen elçileri yalanladı.', 'ولقد كذب اصحب الحجر المرسلين'),
(1883, 15, 81, 'وَاٰتَيْنَاهُمْ اٰيَاتِنَا فَكَانُوا عَنْهَا مُعْرِض۪ينَۙ', 'Ve ateynahum ayatina fe kanu anha mu\'rıdin.', 'Onlara ayetlerimizi[1] verdik,  fakat ondan yüz çevirdiler.', 'واتينهم ايتنا فكانوا عنها معرضين'),
(1884, 15, 82, 'وَكَانُوا يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتاً اٰمِن۪ينَ', 'Ve kanu yanhıtune minel cibali buyuten aminin.', 'Güya dağlardan güvenli evler yontuyorlardı.', 'وكانوا ينحتون من الجبال بيوتا امنين'),
(1885, 15, 83, 'فَاَخَذَتْهُمُ الصَّيْحَةُ مُصْبِح۪ينَۙ', 'Fe ehazethumus sayhatu musbıhin.', 'Derken,  sabaha karşı korkunç bir ses onları yakaladı.', 'فاخذتهم الصيحة مصبحين'),
(1886, 15, 84, 'فَمَٓا اَغْنٰى عَنْهُمْ مَا كَانُوا يَكْسِبُونَۜ', 'Fe ma agna anhum ma kanu yeksibun.', 'Sahip oldukları şeylerin,  kendilerine hiçbir yararı olmadı.', 'فما اغني عنهم ما كانوا يكسبون'),
(1887, 15, 85, 'وَمَا خَلَقْنَا السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَٓا اِلَّا بِالْحَقِّۜ وَاِنَّ السَّاعَةَ لَاٰتِيَةٌ فَاصْفَحِ الصَّفْحَ الْجَم۪يلَ', 'Ve ma halaknes semavati vel arda ve ma beynehuma illa bil hakk, ve innes saate le atiyetun fasfehıs safhal cemil.', 'Biz; gökleri,  yeri ve ikisinin arasındakilerini hakk ile yarattık. Elbette ki o Sa\'at[1] mutlaka gelecektir. O halde,  sen onlara aldırış etme ve güzelce yüz çevir.', 'وما خلقنا السموت والارض وما بينهما الا بالحق وان الساعة لاتية فاصفح الصفح الجميل'),
(1888, 15, 86, 'اِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَل۪يمُ', 'İnne rabbeke huvel hallakul alim.', 'Rabb\'in Her Şeyi Yaratan\'dır ve Her Şeyi Bilen\'dir.', 'ان ربك هو الخلق العليم'),
(1889, 15, 87, 'وَلَقَدْ اٰتَيْنَاكَ سَبْعاً مِنَ الْمَثَان۪ي وَالْقُرْاٰنَ الْعَظ۪يمَ', 'Ve le kad ateynake seb\'an minel mesani vel kur\'anel azim.', 'Ant olsun ki sana seb\'an[1] mine\'l- mesani[2] ve yüce Kur\'an\'ı verdik.', 'ولقد اتينك سبعا من المثاني والقران العظيم'),
(1890, 15, 88, 'لَا تَمُدَّنَّ عَيْنَيْكَ اِلٰى مَا مَتَّعْنَا بِه۪ٓ اَزْوَاجاً مِنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِن۪ينَ', 'La temuddenne ayneyke ila ma metta\'na bihi ezvacen minhum ve la tahzen aleyhim vahfıd cenahake lil mu\'minin.', 'Onlardan bazılarına,  kat kat vererek,  kendilerini yararlandırdığımız şeylere imrenme. Onlar için üzülme.[1] Sen,  mü\'minlere kol kanat ger.', 'لا تمدن عينيك الي ما متعنا به ازوجا منهم ولا تحزن عليهم واخفض جناحك للمومنين'),
(1891, 15, 89, 'وَقُلْ اِنّ۪ٓي اَنَا النَّذ۪يرُ الْمُب۪ينُۚ', 'Ve kul inni enen nezirul mubin.', 'De ki: \"Ben ancak apaçık bir uyarıcıyım.\"', 'وقل اني انا النذير المبين'),
(1892, 15, 90, 'كَمَٓا اَنْزَلْنَا عَلَى الْمُقْتَسِم۪ينَۙ', 'Ke ma enzelna alel muktesimin.', 'Muktesimlere[1] indirdiğimiz şey gibi.', 'كما انزلنا علي المقتسمين'),
(1893, 15, 91, 'اَلَّذ۪ينَ جَعَلُوا الْقُرْاٰنَ عِض۪ينَ', 'Ellezine cealul kur\'ane ıdin.', 'Onlar şimdi de Kur\'an\'ı parça parça yaptılar.[1]', 'الذين جعلوا القران عضين'),
(1894, 15, 92, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ اَجْمَع۪ينَۙ', 'Fe ve rabbike le nes\'elennehum ecmain.', 'Rabb\'ine ant olsun ki kesinlikle onların hepsine soracağız.', 'فوربك لنسلنهم اجمعين'),
(1895, 15, 93, 'عَمَّا كَانُوا يَعْمَلُونَ', 'Amma kanu ya\'melun.', 'Yaptıkları şeylerden.', 'عما كانوا يعملون'),
(1896, 15, 94, 'فَاصْدَعْ بِمَا تُؤْمَرُ وَاَعْرِضْ عَنِ الْمُشْرِك۪ينَ', 'Fasda\' bi ma tu\'meru ve a\'rıd anil muşrikin.', 'Emrolunduğun şeyi açıkça söyle ve müşriklere aldırma.', 'فاصدع بما تومر واعرض عن المشركين'),
(1897, 15, 95, 'اِنَّا كَفَيْنَاكَ الْمُسْتَهْزِء۪ينَۙ', 'İnna kefeynakel mustehziin.', 'Alay edenlere karşı,  Biz,  sana yeteriz.', 'انا كفينك المستهزين'),
(1898, 15, 96, 'اَلَّذ۪ينَ يَجْعَلُونَ مَعَ اللّٰهِ اِلٰهاً اٰخَرَۚ فَسَوْفَ يَعْلَمُونَ', 'Ellezine yec\'alune meallahi ilahen ahar, fe sevfe ya\'lemun.', 'Allah\'ın yanı sıra başka ilah edinenler,  yakında gerçeği anlayacaklar!', 'الذين يجعلون مع الله الها اخر فسوف يعلمون'),
(1899, 15, 97, 'وَلَقَدْ نَعْلَمُ اَنَّكَ يَض۪يقُ صَدْرُكَ بِمَا يَقُولُونَۙ', 'Ve le kad na\'lemu enneke yadiku sadruke bi ma yekulun.', 'Ant olsun; Biz,  onların söylediklerinden dolayı senin göğsünün daraldığını biliyoruz.', 'ولقد نعلم انك يضيق صدرك بما يقولون'),
(1900, 15, 98, 'فَسَبِّـحْ بِحَمْدِ رَبِّكَ وَكُنْ مِنَ السَّاجِد۪ينَۙ', 'Fe sebbih bi hamdi rabbike ve kun mines sacidin.', 'Rabb\'ini hamd ile tesbih et[1] ve secde[2] edenlerden ol.', 'فسبح بحمد ربك وكن من السجدين'),
(1901, 15, 99, 'وَاعْبُدْ رَبَّكَ حَتّٰى يَأْتِيَكَ الْيَق۪ينُ', 'Va\'bud rabbeke hatta ye\'tiyekel yakin.', 'Sana yakin[1] gelinceye kadar,  Rabb\'ine kulluk et!', 'واعبد ربك حتي ياتيك اليقين'),
(1902, 16, 1, 'اَتٰٓى اَمْرُ اللّٰهِ فَلَا تَسْتَعْجِلُوهُۜ سُبْحَانَهُ وَتَعَالٰى عَمَّا يُشْرِكُونَ', 'Eta emrullahi fe la testa\'ciluh, subhanehu ve teala amma yuşrikun.', 'Allah\'ın emri geldi. Artık onda acele etmeyin. O,  onların şirk koştukları şeylerden münezzehtir[1] ve yücedir.', 'اتي امر الله فلا تستعجلوه سبحنه وتعلي عما يشركون'),
(1903, 16, 2, 'يُنَزِّلُ الْمَلٰٓئِكَةَ بِالرُّوحِ مِنْ اَمْرِه۪ عَلٰى مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ٓ اَنْ اَنْذِرُٓوا اَنَّهُ لَٓا اِلٰهَ اِلَّٓا اَنَا۬ فَاتَّقُونِ', 'Yunezzilul melaikete bir ruhi min emrihi ala men yeşau min ibadihi en enziru ennehu la ilahe illa ene fettekun.', 'Benden başka ilah yoktur,  öyleyse bana karşı takva[1] sahibi olun uyarısında bulunmaları için kullarından dilediğine[2] emrinden ruh[3] ile melekleri[4] indirir.', 'ينزل المليكة بالروح من امره علي من يشا من عباده ان انذروا انه لا اله الا انا فاتقون'),
(1904, 16, 3, 'خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّۜ تَعَالٰى عَمَّا يُشْرِكُونَ', 'Halakas semavati vel arda bil hakk, teala amma yuşrikun.', 'Gökleri ve yeryüzünü hakikat ile yarattı. O,  onların şirk[1] koştuklarından yücedir.', 'خلق السموت والارض بالحق تعلي عما يشركون'),
(1905, 16, 4, 'خَلَقَ الْاِنْسَانَ مِنْ نُطْفَةٍ فَاِذَا هُوَ خَص۪يمٌ مُب۪ينٌ', 'Halakal insane min nutfetin fe iza huve hasimun mubin.', 'İnsanı bir nutfeden[1] yarattı. Böyleyken bir de bakarsın,  o apaçık bir düşmandır.[2]', 'خلق الانسن من نطفة فاذا هو خصيم مبين'),
(1906, 16, 5, 'وَالْاَنْعَامَ خَلَقَهَاۚ لَكُمْ ف۪يهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَۖ', 'Vel en\'ame halakaha, lekum fiha dif\'un ve menafiu ve minha te\'kulun.', 'Hayvanları,  sizin için O yarattı. Isınma ve birçok yararları yanında,  onlardan yiyecekler de elde edersiniz.', 'والانعم خلقها لكم فيها دف ومنفع ومنها تاكلون'),
(1907, 16, 6, 'وَلَكُمْ ف۪يهَا جَمَالٌ ح۪ينَ تُر۪يحُونَ وَح۪ينَ تَسْرَحُونَۖ', 'Ve lekum fiha cemalun hine turihune ve hine tesrehun.', 'Akşamları yayılmaktan gelirlerken de sabahları yayılıma gönderirken de onlarda sizin için bir güzellik vardır.[1]', 'ولكم فيها جمال حين تريحون وحين تسرحون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(1908, 16, 7, 'وَتَحْمِلُ اَثْقَالَكُمْ اِلٰى بَلَدٍ لَمْ تَكُونُوا بَالِغ۪يهِ اِلَّا بِشِقِّ الْاَنْفُسِۜ اِنَّ رَبَّكُمْ لَرَؤُ۫فٌ رَح۪يمٌۙ', 'Ve tahmilu eskalekum ila beledin lem tekunu balıgihi illa bi şıkkıl enfus, inne rabbekum le raufun rahim.', 'Zorlukla ulaşabileceğiniz yerlere yüklerinizi taşırlar. Kuşkusuz,  Rabb\'iniz Çok Şefkatli\'dir,  Rahmeti Kesintisiz\'dir.', 'وتحمل اثقالكم الي بلد لم تكونوا بلغيه الا بشق الانفس ان ربكم لروف رحيم'),
(1909, 16, 8, 'وَالْخَيْلَ وَالْبِغَالَ وَالْحَم۪يرَ لِتَرْكَبُوهَا وَز۪ينَةًۜ وَيَخْلُقُ مَا لَا تَعْلَمُونَ', 'Vel hayle vel bigale vel hamire li terkebuha ve zineh, ve yahluku ma la ta\'lemun.', 'Sizin için binek ve süs hayvanı olarak atları,  katırları ve eşekleri yarattı. Ve O,  bilmediğiniz şeyleri yaratmaktadır.', 'والخيل والبغال والحمير لتركبوها وزينة ويخلق ما لا تعلمون'),
(1910, 16, 9, 'وَعَلَى اللّٰهِ قَصْدُ السَّب۪يلِ وَمِنْهَا جَٓائِرٌۜ وَلَوْ شَٓاءَ لَهَدٰيكُمْ اَجْمَع۪ينَ۟', 'Ve alallahi kasdus sebili ve minha cair, ve lev şae le hedakum ecmain.', 'Doğru yolu göstermek Allah\'a aittir. Yolun eğrisi de vardır. Eğer O dileseydi[1],  hepinizi hidayete erdirirdi.', 'وعلي الله قصد السبيل ومنها جاير ولو شا لهديكم اجمعين'),
(1911, 16, 10, 'هُوَ الَّـذ۪ٓي اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً لَكُمْ مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ ف۪يهِ تُس۪يمُونَ', 'Huvellezi enzele mines semai maen lekum minhu şarabun ve minhu şecerun fihi tusimun.', 'Gökten su indiren O\'dur. İçme sularınız O\'ndandır. Hayvanlarınızı otlattığınız bitkiler de O\'ndandır.', 'هو الذي انزل من السما ما لكم منه شراب ومنه شجر فيه تسيمون'),
(1912, 16, 11, 'يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخ۪يلَ وَالْاَعْنَابَ وَمِنْ كُلِّ الثَّمَرَاتِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَتَفَكَّرُونَ', 'Yunbitu lekum bihiz zer\'a vez zeytune ven nahile vel a\'nabe ve min kullis semerat, inne fi zalike le ayeten li kavmin yetefekkerun.', 'O su ile sizin için ekinler,  zeytinler,  hurmalar,  üzümler ve her türlü meyveden bitiriyor. Kuşkusuz,  düşünen bir halk için elbette bir ayet[1] vardır.', 'ينبت لكم به الزرع والزيتون والنخيل والاعنب ومن كل الثمرت ان في ذلك لاية لقوم يتفكرون'),
(1913, 16, 12, 'وَسَخَّرَ لَكُمُ الَّيْلَ وَالنَّهَارَۙ وَالشَّمْسَ وَالْقَمَرَۜ وَالنُّجُومُ مُسَخَّرَاتٌ بِاَمْرِه۪ۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَعْقِلُونَۙ', 'Ve sehhara lekumul leyle ven nehare veş şemse vel kamer, ven nucumu musahharatun bi emrih, inne fi zalike le ayatin li kavmin ya\'kılun.', 'O,  geceyi ve gündüzü,  Güneş\'i ve Ay\'ı yararlanmanıza sundu. Yıldızlar da O\'nun buyruğu ile boyun eğdirilmiştir. Bunda aklını kullanan bir halk için ayetler[1] vardır.', 'وسخر لكم اليل والنهار والشمس والقمر والنجوم مسخرت بامره ان في ذلك لايت لقوم يعقلون'),
(1914, 16, 13, 'وَمَا ذَرَاَ لَكُمْ فِي الْاَرْضِ مُخْتَلِفاً اَلْوَانُهُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَذَّكَّرُونَ', 'Ve ma zerae lekum fil ardı muhtelifen elvanuh, inne fi zalike le ayeten li kavmin yezzekkerun.', 'Yeryüzünde,  rengarenk şeyleri,  sizin için üretip çoğalttı.[1] Bunda öğüt alan bir halk için elbette ayet[2] vardır.', 'وما ذرا لكم في الارض مختلفا الونه ان في ذلك لاية لقوم يذكرون'),
(1915, 16, 14, 'وَهُوَ الَّذ۪ي سَخَّرَ الْبَحْرَ لِتَأْكُلُوا مِنْهُ لَحْماً طَرِياًّ وَتَسْتَخْرِجُوا مِنْهُ حِلْيَةً تَلْبَسُونَهَاۚ وَتَرَى الْفُلْكَ مَوَاخِرَ ف۪يهِ وَلِتَبْتَغُوا مِنْ فَضْلِه۪ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Ve huvellezi sehharel bahre li te\'kulu minhu lahmen tariyyen ve testahricu minhu hilyeten telbesuneha, ve terel fulke mevahira fihi ve li tebtegu min fadlihi ve leallekum teşkurun.', 'Taze et yemeniz ve takındığınız süs eşyası çıkarmanız için denizi yararlanmanıza sunan O\'dur. Lütfundan rızık aramanız için,  onun içinde suları yararak giden gemiler görürsün. Umulur ki şükredersiniz.', 'وهو الذي سخر البحر لتاكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها وتري الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون'),
(1916, 16, 15, 'وَاَلْقٰى فِي الْاَرْضِ رَوَاسِيَ اَنْ تَم۪يدَ بِكُمْ وَاَنْهَاراً وَسُبُلاً لَعَلَّكُمْ تَهْتَدُونَۙ', 'Ve elka fil ardı revasiye en temide bikum ve enharen ve subulen leallekum tehtedun.', 'O,  sizi sarsar diye yeryüzüne ağır baskı koydu. Yolunuzu bulmanız için nehirler ve yollardan izler bıraktı;', 'والقي في الارض روسي ان تميد بكم وانهرا وسبلا لعلكم تهتدون'),
(1917, 16, 16, 'وَعَلَامَاتٍۜ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ', 'Ve alamat, ve bin necmi hum yehtedun.', 'Ve işaretler. Onlar,  yıldızla yol bulurlar.', 'وعلمت وبالنجم هم يهتدون'),
(1918, 16, 17, 'اَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُۜ اَفَلَا تَذَكَّرُونَ', 'E fe men yahluku ke men la yahluk, e fe la tezekkerun.', 'O halde yaratan ile yaratmayan bir midir? Hala tezekkür[1] etmez misiniz?', 'افمن يخلق كمن لا يخلق افلا تذكرون'),
(1919, 16, 18, 'وَاِنْ تَعُدُّوا نِعْمَةَ اللّٰهِ لَا تُحْصُوهَاۜ اِنَّ اللّٰهَ لَغَفُورٌ رَح۪يمٌ', 'Ve in teuddu ni\'metallahi la tuhsuha, innallahe le gafurun rahim.', 'Eğer Allah\'ın nimetlerini sayacak olsanız,  onu hesaplayamazsınız. Kuşkusuz,  Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'وان تعدوا نعمة الله لا تحصوها ان الله لغفور رحيم'),
(1920, 16, 19, 'وَاللّٰهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'Vallahu ya\'lemu ma tusirrune ve ma tu\'linun.', 'Allah,  gizlediğiniz şeyleri de açığa vurduğunuz şeyleri de bilir.', 'والله يعلم ما تسرون وما تعلنون'),
(1921, 16, 20, 'وَالَّذ۪ينَ يَدْعُونَ مِنْ دُونِ اللّٰهِ لَا يَخْلُقُونَ شَيْـٔاً وَهُمْ يُخْلَقُونَۜ', 'Vellezine yed\'une min dunillahi la yahlukune şey\'en ve hum yuhlekun.', 'Onların,  Allah\'ın yanı sıra dua ettikleri,  bir şey yaratamazlar. Kendileri yaratılmışlardır.', 'والذين يدعون من دون الله لا يخلقون شيا وهم يخلقون'),
(1922, 16, 21, 'اَمْوَاتٌ غَيْرُ اَحْيَٓاءٍۚ وَمَا يَشْعُرُونَۙ اَيَّانَ يُبْعَثُونَ۟', 'Emvatun gayru ahya\', ve ma yeş\'urune eyyane yub\'asun.', 'Diri değil,  ölüdürler. Diriltilecekleri zamandan habersizdirler.', 'اموت غير احيا وما يشعرون ايان يبعثون'),
(1923, 16, 22, 'اِلٰهُكُمْ اِلٰهٌ وَاحِدٌۚ فَالَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ قُلُوبُهُمْ مُنْكِرَةٌ وَهُمْ مُسْتَكْبِرُونَ', 'İlahukum ilahun vahid, fellezine la yu\'minune bil ahirati kulubuhum munkiretun ve hum mustekbirun.', 'Sizin ilahınız,  bir tek ilahtır. Buna rağmen,  ahirete inanmayanların kalpleri,  bunu kabul etmez. Ve onlar büyüklenen kimselerdir.', 'الهكم اله وحد فالذين لا يومنون بالاخرة قلوبهم منكرة وهم مستكبرون'),
(1924, 16, 23, 'لَا جَرَمَ اَنَّ اللّٰهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَۜ اِنَّهُ لَا يُحِبُّ الْمُسْتَكْبِر۪ينَ', 'La cereme ennallahe ya\'lemu ma yusirrune ve ma yu\'linun, innehu la yuhıbbul mustekbirin.', 'Allah\'ın,  onların gizlediklerini de açığa vurduklarını da bildiğinden kuşku yok. Gerçek şu ki O,  büyüklük taslayanları sevmez.', 'لا جرم ان الله يعلم ما يسرون وما يعلنون انه لا يحب المستكبرين'),
(1925, 16, 24, 'وَاِذَا ق۪يلَ لَهُمْ مَاذَٓا اَنْزَلَ رَبُّكُمْۙ قَالُٓوا اَسَاط۪يرُ الْاَوَّل۪ينَۙ', 'Ve iza kile lehum ma za enzele rabbukum kalu esatirul evvelin.', 'Onlara,  \"Rabb\'inizin indirdiği şey nedir?\" diye sorulduğu zaman,  \"Öncekilerin masalları!\" derler.', 'واذا قيل لهم ماذا انزل ربكم قالوا اسطير الاولين'),
(1926, 16, 25, 'لِيَحْمِلُٓوا اَوْزَارَهُمْ كَامِلَةً يَوْمَ الْقِيٰمَةِۙ وَمِنْ اَوْزَارِ الَّذ۪ينَ يُضِلُّونَهُمْ بِغَيْرِ عِلْمٍۜ اَلَا سَٓاءَ مَا يَزِرُونَ۟', 'Liyahmilu evzarehum kamileten yevmel kıyameti ve min evzarillezine yudıllunehum bi gayri ilm, e la sae ma yezirun.', 'Kıyamet Günü,  kendi yüklerinin tamamını ve saptırdıkları cahillerin yüklerinden bir kısmını,  yüklenmiş olurlar. Dikkat edin! Yüklendikleri şey ne kötüdür!', 'ليحملوا اوزارهم كاملة يوم القيمة ومن اوزار الذين يضلونهم بغير علم الا سا ما يزرون'),
(1927, 16, 26, 'قَدْ مَكَرَ الَّذ۪ينَ مِنْ قَبْلِهِمْ فَاَتَى اللّٰهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ وَاَتٰيهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'Kad mekerellezine min kablihim fe etallahu bunyanehum minel kavaıdi fe harre aleyhimus sakfu min fevkıhim ve etahumul azabu min haysu la yeş\'urun.', 'Onlardan öncekiler de düzen kurmuşlardı. Allah,  onların yapılarını temelden yıktı,  çatıları da tepelerine çöktü. Onlara,  bu azap,  hesaba katmadıkları yerden geldi.[1]', 'قد مكر الذين من قبلهم فاتي الله بنينهم من القواعد فخر عليهم السقف من فوقهم واتيهم العذاب من حيث لا يشعرون'),
(1928, 16, 27, 'ثُمَّ يَوْمَ الْقِيٰمَةِ يُخْز۪يهِمْ وَيَقُولُ اَيْنَ شُرَكَٓاءِيَ الَّذ۪ينَ كُنْتُمْ تُشَٓاقُّونَ ف۪يهِمْۜ قَالَ الَّذ۪ينَ اُو۫تُوا الْعِلْمَ اِنَّ الْخِزْيَ الْيَوْمَ وَالسُّٓوءَ عَلَى الْكَافِر۪ينَۙ', 'Summe yevmel kıyameti yuhzihim ve yekulu eyne şurekaiyellezine kuntum tuşakkune fihim, kalellezine utul ilme innel hızyel yevme ves sue alel kafirin.', 'Sonra Kıyamet Günü,  onları rezil edecek. Ve \"Hani uğrunda ayrılığa düştüğünüz ortaklarım nerede?\" diyecek. Kendilerine ilim[1] verilenler,  \"Rezillik ve kötülük,  bugün Kafirlerin[2] üzerinedir.\" diyecek.', 'ثم يوم القيمة يخزيهم ويقول اين شركاي الذين كنتم تشقون فيهم قال الذين اوتوا العلم ان الخزي اليوم والسو علي الكفرين'),
(1929, 16, 28, 'اَلَّذ۪ينَ تَتَوَفّٰيهُمُ الْمَلٰٓئِكَةُ ظَالِم۪ٓي اَنْفُسِهِمْۖ فَاَلْقَوُا السَّلَمَ مَا كُنَّا نَعْمَلُ مِنْ سُٓوءٍۜ بَلٰٓى اِنَّ اللّٰهَ عَل۪يمٌ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ellezine teteveffahumul melaiketu zalimi enfusihim fe elkavus seleme ma kunna na\'melu min su\', bela innallahe alimun bima kuntum ta\'melun.', 'Melekler,  kendilerine haksızlık yapanların[1] canlarını alacakları zaman,  onlar,  teslimiyet içinde:[2] \"Biz,  kötü bir iş yapmadık.\" dediler. Hayır! Kuşkusuz,  Allah,  yapmış olduğunuz şeyleri çok iyi bilendir.', 'الذين تتوفيهم المليكة ظالمي انفسهم فالقوا السلم ما كنا نعمل من سو بلي ان الله عليم بما كنتم تعملون'),
(1930, 16, 29, 'فَادْخُلُٓوا اَبْوَابَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَاۜ فَلَبِئْسَ مَثْوَى الْمُتَكَبِّر۪ينَ', 'Fedhulu ebvabe cehenneme halidine fiha fe lebi\'se mesvel mutekebbirin.', 'O halde,  içinde ebedi kalıcılar olarak Cehennem\'in kapılarından girin! Büyüklük taslayanlar için ne kötü bir yerdir orası.', 'فادخلوا ابوب جهنم خلدين فيها فلبيس مثوي المتكبرين'),
(1931, 16, 30, 'وَق۪يلَ لِلَّذ۪ينَ اتَّقَوْا مَاذَٓا اَنْزَلَ رَبُّكُمْۜ قَالُوا خَيْراًۜ لِلَّذ۪ينَ اَحْسَنُوا ف۪ي هٰذِهِ الدُّنْيَا حَسَنَةٌۜ وَلَدَارُ الْاٰخِرَةِ خَيْرٌۜ وَلَنِعْمَ دَارُ الْمُتَّق۪ينَۙ', 'Ve kile lillezinettekav ma za enzele rabbukum, kalu hayra, lillezine ahsenu fi hazihid dunya haseneh, ve le darul ahıreti hayr, ve le ni\'me darul muttekin.', 'Ve takva[1] sahiplerine: \"Rabb\'inizin indirdiği şey nedir?\" denildi. \"İyilik.\" dediler. Bu dünyada,  iyilik yapanlar için iyilik vardır. Ve elbette ahiret yurdu daha hayırlıdır. Takva sahiplerinin yurdu ne güzeldir.', 'وقيل للذين اتقوا ماذا انزل ربكم قالوا خيرا للذين احسنوا في هذه الدنيا حسنة ولدار الاخرة خير ولنعم دار المتقين'),
(1932, 16, 31, 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ لَهُمْ ف۪يهَا مَا يَشَٓاؤُ۫نَۜ كَذٰلِكَ يَجْزِي اللّٰهُ الْمُتَّق۪ينَۙ', 'Cennatu adnin yedhuluneha tecri min tahtihel enharu lehum fiha ma yeşaun, kezalike yeczillahul muttekin.', 'İçinden ırmaklar akan Adn Cennetlerine girerler. Orada,  onlar için diledikleri şeyler var. İşte Allah,  takva sahiplerini böyle ödüllendirir.', 'جنت عدن يدخلونها تجري من تحتها الانهر لهم فيها ما يشاون كذلك يجزي الله المتقين'),
(1933, 16, 32, 'اَلَّذ۪ينَ تَتَوَفّٰيهُمُ الْمَلٰٓئِكَةُ طَيِّب۪ينَۙ يَقُولُونَ سَلَامٌ عَلَيْكُمُۙ ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ellezine teteveffahumul melaiketu tayyibine yekulune selamun aleykumudhulul cennete bima kuntum ta\'melun.', 'Melekler,  onların[1] canlarını tayyib[1] şekilde alırlar. \"Selam size. Yapmış olduğunuz iyi şeylere karşılık girin Cennete.[3]\" derler.', 'الذين تتوفيهم المليكة طيبين يقولون سلم عليكم ادخلوا الجنة بما كنتم تعملون'),
(1934, 16, 33, 'هَلْ يَنْظُرُونَ اِلَّٓا اَنْ تَأْتِيَهُمُ الْمَلٰٓئِكَةُ اَوْ يَأْتِيَ اَمْرُ رَبِّكَۜ كَذٰلِكَ فَعَلَ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ وَمَا ظَلَمَهُمُ اللّٰهُ وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'Hel yanzurune illa en te\'tiyehumul melaiketu ev ye\'tiye emru rabbik, kezalike fe alellezine min kablihim, ve ma zalemehumullahu ve lakin kanu enfusehum yazlimun.', 'Kendilerine meleklerin gelmesinden veya Rabb\'inin emrinin gelmesinden başka bir şey mi bekliyorlar? Onlardan öncekiler de böyle yapmışlardı. Allah onlara haksızlık yapmadı. Fakat onlar kendilerine haksızlık yapıyorlardı.', 'هل ينظرون الا ان تاتيهم المليكة او ياتي امر ربك كذلك فعل الذين من قبلهم وما ظلمهم الله ولكن كانوا انفسهم يظلمون'),
(1935, 16, 34, 'فَاَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ۟', 'Fe esabehum seyyiatu ma amilu ve haka bihim ma kanu bihi yestehziun.', 'Böylece yaptıklarının kötülükleri onlara isabet etti. Alay ettikleri şey kendilerini kuşattı.', 'فاصابهم سيات ما عملوا وحاق بهم ما كانوا به يستهزون'),
(1936, 16, 35, 'وَقَالَ الَّذ۪ينَ اَشْرَكُوا لَوْ شَٓاءَ اللّٰهُ مَا عَبَدْنَا مِنْ دُونِه۪ مِنْ شَيْءٍ نَحْنُ وَلَٓا اٰبَٓاؤُ۬نَا وَلَا حَرَّمْنَا مِنْ دُونِه۪ مِنْ شَيْءٍۜ كَذٰلِكَ فَعَلَ الَّذ۪ينَ مِنْ قَبْلِهِمْۚ فَهَلْ عَلَى الرُّسُلِ اِلَّا الْبَلَاغُ الْمُب۪ينُ', 'Ve kalellezine eşreku lev şaallahu ma abedna min dunihi min şey\'in nahnu ve la abauna ve la harremna min dunihi min şey\', kezalike fe alellezine min kablihim, fe hel aler rusuli illel belagul mubin.', 'Şirk koşanlar,  \"Eğer Allah dileseydi biz onun yanı sıra başkasına kul olmazdık. Babalarımız da olmazdı. Ne biz ne de babalarımız O\'nun haram kıldığından başka hiçbir şeyi haram kılmazdık.\"[1] dediler. Onlardan öncekiler de böyle yaptılar. Bu durumda resullerin üzerine düşen,  vahyi apaçık bir şekilde tebliğden başkası değil.', 'وقال الذين اشركوا لو شا الله ما عبدنا من دونه من شي نحن ولا اباونا ولا حرمنا من دونه من شي كذلك فعل الذين من قبلهم فهل علي الرسل الا البلغ المبين'),
(1937, 16, 36, 'وَلَقَدْ بَعَثْنَا ف۪ي كُلِّ اُمَّةٍ رَسُولاً اَنِ اعْبُدُوا اللّٰهَ وَاجْتَنِبُوا الطَّاغُوتَۚ فَمِنْهُمْ مَنْ هَدَى اللّٰهُ وَمِنْهُمْ مَنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُۜ فَس۪يرُوا فِي الْاَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّب۪ينَ', 'Ve le kad beasna fi kulli ummetin resulen eni\'budullahe vectenibut tagut, fe minhum men hedallahu ve minhum men hakkat aleyhid dalaleh, fe siru fil ardı fanzuru keyfe kane akıbetul mukezzibin.', 'Ant olsun ki,  Biz,  her ümmete[1],  Allah\'a kulluk etmeleri ve tağuttan[2] uzak durmaları için bir resul gönderdik. Allah onlardan kimini[3] doğru yola iletti,  kimine[3] de sapkınlık hak oldu. Şimdi yeryüzünde gezin de yalanlayanların sonunun nasıl olduğuna bakın.', 'ولقد بعثنا في كل امة رسولا ان اعبدوا الله واجتنبوا الطغوت فمنهم من هدي الله ومنهم من حقت عليه الضللة فسيروا في الارض فانظروا كيف كان عقبة المكذبين'),
(1938, 16, 37, 'اِنْ تَحْرِصْ عَلٰى هُدٰيهُمْ فَاِنَّ اللّٰهَ لَا يَهْد۪ي مَنْ يُضِلُّ وَمَا لَهُمْ مِنْ نَاصِر۪ينَ', 'İn tahris ala hudahum fe innallahe la yehdi men yudıllu ve ma lehum min nasırin.', 'Sen,  onların,  doğru yola ermelerini ne kadar çok istersen iste; sapkınlıkta kararlı olanları Allah doğru yola iletmez. Onlar için bir yardımcı da bulunmaz.', 'ان تحرص علي هديهم فان الله لا يهدي من يضل وما لهم من نصرين'),
(1939, 16, 38, 'وَاَقْسَمُوا بِاللّٰهِ جَهْدَ اَيْمَانِهِمْۙ  لَا يَبْعَثُ اللّٰهُ مَنْ يَمُوتُۜ بَلٰى وَعْداً عَلَيْهِ حَقاًّ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَۙ', 'Ve aksemu billahi cehde eymanihim la yeb\'asullahu men yemut, bela va\'den aleyhi hakkan ve lakinne ekseren nasi la ya\'lemun.', '\"Allah,  ölen bir kimseyi diriltmez.\" diye olanca güçleriyle Allah\'a yemin ettiler. Hayır! Allah\'ın ölüleri diriltmesi kesin bir sözdür. Ancak insanların çoğu bu gerçeği kavramazlar.', 'واقسموا بالله جهد ايمنهم لا يبعث الله من يموت بلي وعدا عليه حقا ولكن اكثر الناس لا يعلمون'),
(1940, 16, 39, 'لِيُبَيِّنَ لَهُمُ الَّذ۪ي يَخْتَلِفُونَ ف۪يهِ وَلِيَعْلَمَ الَّذ۪ينَ كَفَرُٓوا اَنَّهُمْ كَانُوا كَاذِب۪ينَ', 'Li yubeyyine lehumullezi yahtelifune fihi ve li ya\'lemellezine keferu ennehum kanu kazibin.', 'Karşı çıktıkları şeyin[1] onlara açıklanması ve Kafirlerin yalancılar olduklarını bilmeleri için diriltileceklerdir.', 'ليبين لهم الذي يختلفون فيه وليعلم الذين كفروا انهم كانوا كذبين'),
(1941, 16, 40, 'اِنَّمَا قَوْلُنَا لِشَيْءٍ اِذَٓا اَرَدْنَاهُ اَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ۟', 'İnnema kavluna li şey\'in iza erednahu en nekule lehu kun fe yekun.', 'Bir şeyin olmasını istediğimiz zaman,  sözümüz ona sadece,  \"Ol.\" demektir. O da olur.[1]', 'انما قولنا لشي اذا اردنه ان نقول له كن فيكون'),
(1942, 16, 41, 'وَالَّذ۪ينَ هَاجَرُوا فِي اللّٰهِ مِنْ بَعْدِ مَا ظُلِمُوا لَنُبَوِّئَنَّهُمْ فِي الدُّنْيَا حَسَنَةًۜ وَلَاَجْرُ الْاٰخِرَةِ اَكْبَرُۢ لَوْ كَانُوا يَعْلَمُونَۙ', 'Vellezine haceru fillahi min ba\'di ma zulimu li nubevvi ennehum fid dunya haseneh, ve le ecrul ahıreti ekber, lev kanu ya\'lemun.', 'Zulme uğramalarından sonra,  Allah yolunda hicret eden kimseleri,  kesinlikle dünyada iyi bir yere yerleştiririz. Ahiret ödülü ise daha büyüktür. Keşke hicretten geri kalanlar bunu bilselerdi!', 'والذين هاجروا في الله من بعد ما ظلموا لنبوينهم في الدنيا حسنة ولاجر الاخرة اكبر لو كانوا يعلمون'),
(1943, 16, 42, 'اَلَّذ۪ينَ صَبَرُوا وَعَلٰى رَبِّهِمْ يَتَوَكَّلُونَ', 'Ellezine saberu ve ala rabbihim yetevekkelun.', 'Onlar[1],  sabreden kimselerdir. Rablerine,  tevekkül[2] edenlerdir.', 'الذين صبروا وعلي ربهم يتوكلون'),
(1944, 16, 43, 'وَمَٓا اَرْسَلْنَا مِنْ قَبْلِكَ اِلَّا رِجَالاً نُوح۪ٓي اِلَيْهِمْ فَسْـَٔلُٓوا اَهْلَ الذِّكْرِ اِنْ كُنْتُمْ لَا تَعْلَمُونَۙ', 'Ve ma erselna min kablike illa ricalen nuhi ileyhim fes\'elu ehlez zikri in kuntum la ta\'lemun.', 'Senden önce de vahyimizi iletmede elçi olarak insandan[1] başkasını görevlendirmedik. Eğer bilmiyorsanız,  zikir ehline[2] sorun.', 'وما ارسلنا من قبلك الا رجالا نوحي اليهم فسلوا اهل الذكر ان كنتم لا تعلمون'),
(1945, 16, 44, 'بِالْبَيِّنَاتِ وَالزُّبُرِۜ وَاَنْزَلْـنَٓا اِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ اِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 'Bil beyyinati vez zubur, ve enzelna ileykez zikre li tubeyyine lin nasi ma nuzzile ileyhim ve leallehum yetefekkerun.', 'Onları[1] beyyinelerle[2] zeburlarla[3] gönderdik. Sana da zikri[4] indirdik. İnsanlara,  kendilerine indirileni beyan edesin.[5] Ki böylece düşünüp öğüt alırlar.', 'بالبينت والزبر وانزلنا اليك الذكر لتبين للناس ما نزل اليهم ولعلهم يتفكرون'),
(1946, 16, 45, 'اَفَاَمِنَ الَّذ۪ينَ مَكَرُوا السَّيِّـَٔاتِ اَنْ يَخْسِفَ اللّٰهُ بِهِمُ الْاَرْضَ اَوْ يَأْتِيَهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَۙ', 'E fe eminellezine mekeru seyyiati en yahsifallahu bihimul arda ev ye\'tiyehumul azabu min haysu la yeş\'urun.', 'Sana sinsice kötü tuzaklar kuranlar,  Allah\'ın,  kendilerini yerin dibine geçirmeyeceğinden veya ummadıkları bir yerden azabın gelmeyeceğinden emin midirler?', 'افامن الذين مكروا السيات ان يخسف الله بهم الارض او ياتيهم العذاب من حيث لا يشعرون'),
(1947, 16, 46, 'اَوْ يَأْخُذَهُمْ ف۪ي تَقَلُّبِهِمْ فَمَا هُمْ بِمُعْجِز۪ينَۙ', 'Ev ye\'huzehum fi tekallubihim fe ma hum bi mu\'cizin.', 'Veya gezinip dururlarken,  onları ansızın yakalamasından. Onlar,  bunu engelleyemezler de.', 'او ياخذهم في تقلبهم فما هم بمعجزين'),
(1948, 16, 47, 'اَوْ يَأْخُذَهُمْ عَلٰى تَخَوُّفٍۜ فَاِنَّ رَبَّكُمْ لَرَؤُ۫فٌ رَح۪يمٌ', 'Ev ye\'huzehum ala tehavvuf, fe inne rabbekum le raufun rahim.', 'Veya kendilerini,  korku üzerinde yakalamayacağından. Buna rağmen,  doğrusu Rabb\'iniz,  Çok Şefkatli\'dir,  Rahmeti Kesintisiz\'dir.', 'او ياخذهم علي تخوف فان ربكم لروف رحيم'),
(1949, 16, 48, 'اَوَلَمْ يَرَوْا اِلٰى مَا خَلَقَ اللّٰهُ مِنْ شَيْءٍ يَتَفَيَّؤُ۬ا ظِلَالُهُ عَنِ الْيَم۪ينِ وَالشَّمَٓائِلِ سُجَّداً لِلّٰهِ وَهُمْ دَاخِرُونَ', 'E ve lem yerev ila ma halakallahu min şey\'in yetefeyyeu zilaluhu anil yemini veş şemaili succeden lillahi ve hum dahırun.', 'Onlar,  Allah\'ın yarattığı şeylerden,  herhangi bir şeye bakmazlar mı? Gölgelerinin; secde[2] ederek,  saygıyla sağa sola dönüp O\'nun yasalarına nasıl uyduklarını görmüyorlar mı?', 'اولم يروا الي ما خلق الله من شي يتفيوا ظلله عن اليمين والشمايل سجدا لله وهم دخرون'),
(1950, 16, 49, 'وَلِلّٰهِ يَسْجُدُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ مِنْ دَٓابَّةٍ وَالْمَلٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 'Ve lillahi yescudu ma fis semavati ve ma fil ardı min dabbetin vel melaiketu ve hum la yestekbirun.', 'Göklerde ve yerde bulunan hareket halindeki varlıkların tamamı ve melekler büyüklenmeden,  Allah\'a secde ederler.[1]', 'ولله يسجد ما في السموت وما في الارض من دابة والمليكة وهم لا يستكبرون'),
(1951, 16, 50, 'يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ۟', 'Yehafune rabbehum min fevkıhim ve yef\'alune ma yu\'merun.', 'Kendilerine egemen olan Rabb\'lerine karşı gelmekten korkarlar ve emrolundukları şeyleri yaparlar.', 'يخافون ربهم من فوقهم ويفعلون ما يومرون'),
(1952, 16, 51, 'وَقَالَ اللّٰهُ لَا تَتَّخِذُٓوا اِلٰهَيْنِ اثْنَيْنِۚ اِنَّمَا هُوَ اِلٰهٌ وَاحِدٌۚ فَاِيَّايَ فَارْهَبُونِ', 'Ve kalallahu la tettehızu ilaheynisneyn, innema huve ilahun vahıd, fe iyyaye ferhebun.', 'Allah: \"İki ilah edinmeyin! O,  ancak tek bir ilahtır. O halde,  yalnızca Bana rehbet[1] duyun.\"', 'وقال الله لا تتخذوا الهين اثنين انما هو اله وحد فايي فارهبون'),
(1953, 16, 52, 'وَلَهُ مَا فِي السَّمٰوَاتِ وَالْاَرْضِ وَلَهُ الدّ۪ينُ وَاصِباًۜ اَفَغَيْرَ اللّٰهِ تَتَّقُونَ', 'Ve lehu ma fis semavati vel ardı ve lehud dinu vasıba, e fe gayrallahi tettekun.', 'Göklerde ve yerde ne varsa,  yalnız O\'nundur. Din de yalnızca O\'nundur.[1] Böyleyken,  Allah\'tan başkasına mı takvalı oluyorsunuz?[2]', 'وله ما في السموت والارض وله الدين واصبا افغير الله تتقون'),
(1954, 16, 53, 'وَمَا بِكُمْ مِنْ نِعْمَةٍ فَمِنَ اللّٰهِ ثُمَّ اِذَا مَسَّكُمُ الضُّرُّ فَاِلَيْهِ تَجْـَٔرُونَۚ', 'Ve ma bikum min ni\'metin fe minallahi summe iza messekumud durru fe ileyhi tec\'erun.', 'Sahip olduğunuz nimetlerin tamamı,  Allah\'tandır. Sonra bir sıkıntıya uğradığınızda,  yalnız O\'na yalvarırsınız.', 'وما بكم من نعمة فمن الله ثم اذا مسكم الضر فاليه تجرون'),
(1955, 16, 54, 'ثُمَّ اِذَا كَشَفَ الضُّرَّ عَنْكُمْ اِذَا فَر۪يقٌ مِنْكُمْ بِرَبِّهِمْ يُشْرِكُونَۙ', 'Summe iza keşefad durra ankum iza ferikun minkum bi rabbihim yuşrikun.', 'Sonra O,  sizden sıkıntıyı giderince,  bir kısmınız hemen Rabb\'lerine şirk koşmaya başlar.', 'ثم اذا كشف الضر عنكم اذا فريق منكم بربهم يشركون'),
(1956, 16, 55, 'لِيَكْفُرُوا بِمَٓا اٰتَيْنَاهُمْۜ فَتَمَتَّعُوا۠ فَسَوْفَ تَعْلَمُونَ', 'Li yekfuru bima ateynahum, fe temetteu, fesevfe ta\'lemun.', 'Kendilerine verdiklerimize nankörlük ediyorlar. Şimdilik faydalanın bakalım! Yakında göreceksiniz!', 'ليكفروا بما اتينهم فتمتعوا فسوف تعلمون'),
(1957, 16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَص۪يباً مِمَّا رَزَقْنَاهُمْۜ تَاللّٰهِ لَتُسْـَٔلُنَّ عَمَّا كُنْتُمْ تَفْتَرُونَ', 'Ve yec\'alune li ma la ya\'lemune nasiben mimma razaknahum, tallahi le tus\'elunne amma kuntum tefterun.', 'Onlar,  kendilerini rızıklandırdığımız şeylerden bilinçsizce[1] pay ayırıyorlar. Allah\'a yemin olsun ki,  uydurduğunuz bu şeylerden kesinlikle hesaba çekileceksiniz.', 'ويجعلون لما لا يعلمون نصيبا مما رزقنهم تالله لتسلن عما كنتم تفترون'),
(1958, 16, 57, 'وَيَجْعَلُونَ لِلّٰهِ الْبَنَاتِ سُبْحَانَهُۙ وَلَهُمْ مَا يَشْتَهُونَ', 'Ve yec\'alune lillahil benati subhanehu ve lehum ma yeştehun.', 'Kız çocuklarını Allah\'a yakıştırıyorlar. O,  bundan münezzehtir.[1] Hoşlandıklarını[2] da kendilerine ayırıyorlar.', 'ويجعلون لله البنت سبحنه ولهم ما يشتهون'),
(1959, 16, 58, 'وَاِذَا بُشِّرَ اَحَدُهُمْ بِالْاُنْثٰى ظَلَّ وَجْهُهُ مُسْوَداًّ وَهُوَ كَظ۪يمٌۚ', 'Ve iza buşşire ehaduhum bil unsa zalle vechuhu musvedden ve huve kezim.', 'Onlardan birisine,  çocuğunun kız olduğu haberi verildiği zaman,  kızgınlığından yüzü kapkara kesilir.', 'واذا بشر احدهم بالانثي ظل وجهه مسودا وهو كظيم'),
(1960, 16, 59, 'يَتَوَارٰى مِنَ الْقَوْمِ مِنْ سُٓوءِ مَا بُشِّرَ بِه۪ۜ اَيُمْسِكُهُ عَلٰى هُونٍ اَمْ يَدُسُّهُ فِي التُّرَابِۜ اَلَا سَٓاءَ مَا يَحْكُمُونَ', 'Yetevara minel kavmi min sui ma buşşire bih, e yumsikuhu ala hunin em yedussuhu fit turab, e la sae ma yahkumun.', 'Aldığı haberin kötülüğünden,  insanların yüzüne bakamaz olur! Bu zillete[1] karşı onu yanında mı tutsun,  yoksa toprağa mı gömsün! Dikkat edin,  verdikleri hüküm[2] ne kötüdür!', 'يتوري من القوم من سو ما بشر به ايمسكه علي هون ام يدسه في التراب الا سا ما يحكمون'),
(1961, 16, 60, 'لِلَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ مَثَلُ السَّوْءِۚ وَلِلّٰهِ الْمَثَلُ الْاَعْلٰىۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ۟', 'Lillezine la yu\'minune bil ahıreti meselus sev\', ve lillahil meselul a\'la, ve huvel azizul hakim.', 'Kötü misaller[1] ahirete inanmayanlara aittir. En yüce misaller Allah içindir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'للذين لا يومنون بالاخرة مثل السو ولله المثل الاعلي وهو العزيز الحكيم'),
(1962, 16, 61, 'وَلَوْ يُؤَاخِذُ اللّٰهُ النَّاسَ بِظُلْمِهِمْ مَا تَرَكَ عَلَيْهَا مِنْ دَٓابَّةٍ وَلٰكِنْ يُؤَخِّرُهُمْ اِلٰٓى اَجَلٍ مُسَمًّىۚ فَاِذَا جَٓاءَ اَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'Ve lev yuahızullahun nase bi zulmihim ma tereke aleyha min dabbetin ve lakin yuahhıruhum ila ecelin musemma, fe iza cae eceluhum la yeste\'hırune saaten ve la yestakdimun.', 'Eğer Allah insanları,  haksızlıkları nedeniyle cezalandıracak olsaydı,  yeryüzünde hiçbir canlı bırakmazdı. Ancak onları adı konulmuş bir süreye kadar erteler. Süreleri dolduğu zaman,  ne bir saat ertelenir ne de öne alınır.', 'ولو يواخذ الله الناس بظلمهم ما ترك عليها من دابة ولكن يوخرهم الي اجل مسمي فاذا جا اجلهم لا يستخرون ساعة ولا يستقدمون'),
(1963, 16, 62, 'وَيَجْعَلُونَ لِلّٰهِ مَا يَكْرَهُونَ وَتَصِفُ اَلْسِنَتُهُمُ الْكَذِبَ اَنَّ لَهُمُ الْحُسْنٰىۜ لَا جَرَمَ اَنَّ لَهُمُ النَّارَ وَاَنَّهُمْ مُفْرَطُونَ', 'Ve yec\'alune lillahi ma yekrehune ve tesıfu elsinetuhumul kezibe enne lehumul husna, la cereme enne lehumun nare ve ennehum mufretun.', 'Onlar,  hoşlanmadıkları şeyleri Allah\'a ait kılarlar. Dilleri en iyinin kendilerine ait olduğu yalanını söyler durur. Ateş onlara aittir. Onlar ifratta[1] olanlardır.', 'ويجعلون لله ما يكرهون وتصف السنتهم الكذب ان لهم الحسني لا جرم ان لهم النار وانهم مفرطون'),
(1964, 16, 63, 'تَاللّٰهِ لَقَدْ اَرْسَلْـنَٓا اِلٰٓى اُمَمٍ مِنْ قَبْلِكَ فَزَيَّنَ لَهُمُ الشَّيْطَانُ اَعْمَالَهُمْ فَهُوَ وَلِيُّهُمُ الْيَوْمَ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'Tallahi lekad erselna ila umemin min kablike fe zeyyene lehumuş şeytanu a\'malehum fe huve veliyyuhumul yevme ve lehum azabun elim.', 'Allah\'a ant olsun ki,  Biz,  kesinlikle senden önceki toplumlara da elçiler gönderdik. Şeytan,  onlara yaptıklarını süslü gösterdi. Şeytan,  o gün de bugün de onların velisidir.[1] Onlar için acı veren bir azap vardır.', 'تالله لقد ارسلنا الي امم من قبلك فزين لهم الشيطن اعملهم فهو وليهم اليوم ولهم عذاب اليم'),
(1965, 16, 64, 'وَمَٓا اَنْزَلْنَا عَلَيْكَ الْكِتَابَ اِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا ف۪يهِۙ وَهُدًى وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ', 'Ve ma enzelna aleykel kitabe illa li tubeyyine lehumullezihtelefu fihi ve huden ve rahmeten li kavmin yu\'minun.', 'Biz,  sana Kitap\'ı,  hakkında ayrılığa düştükleri şeyleri,  kendilerine beyan[1] etmen ve inanan bir halk için yol gösterici ve rahmet olmasından başka bir şey için indirmedik.', 'وما انزلنا عليك الكتب الا لتبين لهم الذي اختلفوا فيه وهدي ورحمة لقوم يومنون'),
(1966, 16, 65, 'وَاللّٰهُ اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً فَاَحْيَا بِهِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَسْمَعُونَ۟', 'Vallahu enzele mines semai maen fe ahya bihil arda ba\'de mevtiha, inne fi zalike le ayeten li kavmin yesmeun.', 'Allah,  gökyüzünden suyu indirerek,  ölümünden sonra yeryüzüne hayat verdi. Bunda dinleyen[1] bir halk için kesinlikle bir ayet[2] vardır.', 'والله انزل من السما ما فاحيا به الارض بعد موتها ان في ذلك لاية لقوم يسمعون'),
(1967, 16, 66, 'وَاِنَّ لَكُمْ فِي الْاَنْعَامِ لَعِبْرَةًۜ  نُسْق۪يكُمْ مِمَّا ف۪ي بُطُونِه۪ مِنْ بَيْنِ فَرْثٍ وَدَمٍ لَبَناً خَالِصاً سَٓائِغاً لِلشَّارِب۪ينَ', 'Ve inne lekum fil en\'ami le ibreh, nuskikum mimma fi butunihi min beyni fersin ve demin lebenen halisen saigan liş şaribin.', 'Hayvanlarda da sizin için bir ibret vardır. Size,  onların karınlarındaki fışkı[1] ile kan arasından süzülüp gelen içimi lezzetli,  halis[2] bir süt içiriyoruz.', 'وان لكم في الانعم لعبرة نسقيكم مما في بطونه من بين فرث ودم لبنا خالصا سايغا للشربين'),
(1968, 16, 67, 'وَمِنْ ثَمَرَاتِ النَّخ۪يلِ وَالْاَعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَراً وَرِزْقاً حَسَناًۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَعْقِلُونَ', 'Ve min semeratin nahili vel a\'nabi tettehizune minhu sekeren ve rızkan hasena, inne fi zalike le ayeten li kavmin ya\'kılun.', 'Üzüm ve hurma meyvelerinden sarhoşluk veren içecek[1] ve faydalı besinler elde edersiniz. Aklını kullanan bir halk için,  bunda kesinlikle bir ayet[2] vardır.', 'ومن ثمرت النخيل والاعنب تتخذون منه سكرا ورزقا حسنا ان في ذلك لاية لقوم يعقلون'),
(1969, 16, 68, 'وَاَوْحٰى رَبُّكَ اِلَى النَّحْلِ اَنِ اتَّخِذ۪ي مِنَ الْجِبَالِ بُيُوتاً وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَۙ', 'Ve evha rabbuke ilen nahli enittehızi minel cibali buyuten ve mineş şeceri ve mimma ya\'rişun.', 'Rabbin,  bal arısına; dağlarda,  ağaçlarda ve hazırladıkları şeylerde[1] yuva edinmesini vahyetti.[2]', 'واوحي ربك الي النحل ان اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون'),
(1970, 16, 69, 'ثُمَّ كُل۪ي مِنْ كُلِّ الثَّمَرَاتِ فَاسْلُك۪ي سُبُلَ رَبِّكِ ذُلُلاًۜ يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ مُخْتَلِفٌ اَلْوَانُهُ ف۪يهِ شِفَٓاءٌ لِلنَّاسِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَتَفَكَّرُونَ', 'Summe kuli min kullis semerati fesluki subule rabbiki zulula, yahrucu min butuniha şarabun muhtelifun elvanuhu fihi şifaun lin nas, inne fi zalike le ayeten li kavmin yetefekkerun.', '\"Sonra,  her çeşit bitkiden ye. Rabb\'inin emre amade kılınmış yollarında dolaş.\"[1] Onun karınlarından,  çeşitli renklerde şarap[2] çıkar. Onda,  insanlar için şifa vardır. Bunda düşünen bir toplum için kesinlikle bir ayet vardır.', 'ثم كلي من كل الثمرت فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف الونه فيه شفا للناس ان في ذلك لاية لقوم يتفكرون'),
(1971, 16, 70, 'وَاللّٰهُ خَلَقَكُمْ ثُمَّ يَتَوَفّٰيكُمْ وَمِنْكُمْ مَنْ يُرَدُّ اِلٰٓى اَرْذَلِ الْعُمُرِ لِكَيْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـٔاًۜ اِنَّ اللّٰهَ عَل۪يمٌ قَد۪يرٌ۟', 'Vallahu halakakum summe yeteveffakum ve minkum men yureddu ila erzelil umuri li keyla ya\'leme ba\'de ilmin şey\'a, innallahe alimun kadir.', 'Sizi,  Allah yarattı,  sonra da sizi vefat ettirecek. Sizden kiminiz de bilir bir haldeyken[1],  hiçbir şey bilmeyen ihtiyar bir bunak oluncaya dek yaşatılır. Allah,  Her Şeyi Bilen\'dir,  Her Şeye Gücü Yeten\'dir.', 'والله خلقكم ثم يتوفيكم ومنكم من يرد الي ارذل العمر لكي لا يعلم بعد علم شيا ان الله عليم قدير'),
(1972, 16, 71, 'وَاللّٰهُ فَضَّلَ بَعْضَكُمْ عَلٰى بَعْضٍ فِي الرِّزْقِۚ فَمَا الَّذ۪ينَ فُضِّلُوا بِرَٓادّ۪ي رِزْقِهِمْ عَلٰى مَا مَلَكَتْ اَيْمَانُهُمْ فَهُمْ ف۪يهِ سَوَٓاءٌۜ  اَفَبِنِعْمَةِ اللّٰهِ يَجْحَدُونَ', 'Vallahu faddale ba\'dakum ala ba\'dın fir rızk, femellezine fuddılu bi raddi rızkıhim ala ma meleket eymanehum fe hum fihi seva\', e fe bi ni\'metillahi yechadun.', 'Allah,  rızık konusunda kiminizi kiminize üstün kıldı. Üstün kılınanlar; rızıklarını yeminle hak sahibi oldukları[1] kimselere aktarıyorlar da onlar,  onda eşit oluyorlar mı? O halde,  Allah\'ın nimetini mi inkar ediyorlar?[2]', 'والله فضل بعضكم علي بعض في الرزق فما الذين فضلوا برادي رزقهم علي ما ملكت ايمنهم فهم فيه سوا افبنعمة الله يجحدون'),
(1973, 16, 72, 'وَاللّٰهُ جَعَلَ لَكُمْ مِنْ اَنْفُسِكُمْ اَزْوَاجاً وَجَعَلَ لَكُمْ مِنْ اَزْوَاجِكُمْ بَن۪ينَ وَحَفَدَةً وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِۜ اَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ اللّٰهِ هُمْ يَكْفُرُونَۙ', 'Vallahu ceale lekum min enfusikum ezvacen ve ceale lekum min ezvacikum benine ve hafedeten ve rezakakum minet tayyibat, e fe bil batıli yu\'minune ve bi ni\'metillahi hum yekfurun.', 'Allah sizin için,  kendinizden eşler var etti ve eşlerden de çocuklar ve torunlar var etti. Temiz şeylerle rızıklandırdı. Hala batıla mı inanıyorlar? Allah\'ın nimetine nankörlük mü ediyorlar?', 'والله جعل لكم من انفسكم ازوجا وجعل لكم من ازوجكم بنين وحفدة ورزقكم من الطيبت افبالبطل يومنون وبنعمت الله هم يكفرون'),
(1974, 16, 73, 'وَيَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقاً مِنَ السَّمٰوَاتِ وَالْاَرْضِ شَيْـٔاً وَلَا يَسْتَط۪يعُونَۚ', 'Ve ya\'budune min dunillahi ma la yemliku lehum rızkan mines semavati vel ardı şey\'en ve la yestetiun.', 'Onlar,  Allah\'ın yanı sıra,  göklerden ve yerden kendilerine hiçbir rızık veremeyen ve hiçbir şeye güçleri yetmeyen şeylere kulluk ediyorlar.', 'ويعبدون من دون الله ما لا يملك لهم رزقا من السموت والارض شيا ولا يستطيعون'),
(1975, 16, 74, 'فَلَا تَضْرِبُوا لِلّٰهِ الْاَمْثَالَۜ اِنَّ اللّٰهَ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُونَ', 'Fe la tadribu lillahil emsal, innallahe ya\'lemu ve entum la ta\'lemun.', 'Artık Allah\'a benzerler uydurmayın. Kuşkusuz,  Allah bilir siz bilmezsiniz.', 'فلا تضربوا لله الامثال ان الله يعلم وانتم لا تعلمون'),
(1976, 16, 75, 'ضَرَبَ اللّٰهُ مَثَلاً عَبْداً مَمْلُوكاً لَا يَقْدِرُ عَلٰى شَيْءٍ وَمَنْ رَزَقْنَاهُ مِنَّا رِزْقاً حَسَناً فَهُوَ يُنْفِقُ مِنْهُ سِراًّ وَجَهْراًۜ هَلْ يَسْتَوُ۫نَۜ اَلْحَمْدُ لِلّٰهِۜ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَ', 'Daraballahu meselen abden memluken la yakdiru ala şey\'in ve men razaknahu minna rızkan hasenen fe huve yunfiku minhu sırren ve cehra, hel yestevun, elhamdulillah, bel ekseruhum la ya\'lemun.', 'Allah,  hiçbir şeye gücü yetmeyen ve başkasının malı olmuş bir abd[1] ile tarafımızdan kendisine iyi bir rızık verip de ondan gizli ve açık olarak yardımda bulunan bir kimseyi örnek verir. Bunlar,  hiç bir olurlar mı? Hamd,  Allah\'a mahsustur. Ne var ki onların çoğu bilmezler.', 'ضرب الله مثلا عبدا مملوكا لا يقدر علي شي ومن رزقنه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستون الحمد لله بل اكثرهم لا يعلمون'),
(1977, 16, 76, 'وَضَرَبَ اللّٰهُ مَثَلاً رَجُلَيْنِ اَحَدُهُمَٓا اَبْكَمُ لَا يَقْدِرُ عَلٰى شَيْءٍ وَهُوَ كَلٌّ عَلٰى مَوْلٰيهُۙ اَيْنَمَا يُوَجِّهْهُ لَا يَأْتِ بِخَيْرٍۜ هَلْ يَسْتَو۪ي هُوَۙ وَمَنْ يَأْمُرُ بِالْعَدْلِۙ وَهُوَ عَلٰى صِرَاطٍ مُسْتَق۪يمٍ۟', 'Ve daraballahu meselen raculeyni ehaduhuma ebkemu la yakdiru ala şey\'in ve huve kellun ala mevlahu eynema yuveccihhu la ye\'ti bi hayr, hel yestevi huve ve men ye\'muru bil adli ve huve ala sıratın mustakim.', 'Allah,  iki adamı da örnek verdi: Bunlardan biri dilsiz ve hiçbir şeye gücü yetmez; mevlasına[1] bir yüktür. Onu nereye gönderirse göndersin,  bir iş beceremez. Bu adamla,  adaleti emreden ve dosdoğru yolda olan eşit olur mu?', 'وضرب الله مثلا رجلين احدهما ابكم لا يقدر علي شي وهو كل علي موليه اينما يوجهه لا يات بخير هل يستوي هو ومن يامر بالعدل وهو علي صرط مستقيم'),
(1978, 16, 77, 'وَلِلّٰهِ غَيْبُ السَّمٰوَاتِ وَالْاَرْضِۜ وَمَٓا اَمْرُ السَّاعَةِ اِلَّا كَلَمْحِ الْبَصَرِ اَوْ هُوَ اَقْرَبُۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ve lillahi gaybus semavati vel ard, ve ma emrus saati illa kelemhıl basari ev huve akreb, innallahe ala kulli şey\'in kadir.', 'Göklerin ve yerin gaybı,  yalnızca Allah\'a aittir. Sa\'at\'in[1] emri de yalnızca göz açıp kapamak veya ondan daha az bir zamanda olacaktır. Kuşkusuz,  Allah Her Şeye Kadir\'dir.', 'ولله غيب السموت والارض وما امر الساعة الا كلمح البصر او هو اقرب ان الله علي كل شي قدير'),
(1979, 16, 78, 'وَاللّٰهُ اَخْرَجَكُمْ مِنْ بُطُونِ اُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْـٔاًۙ وَجَعَلَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٔدَةَۙ لَعَلَّكُمْ تَشْكُرُونَ', 'Vallahu ahrecekum min butuni ummehatikum la ta\'lemune şey\'en ve ceale lekumus sem\'a vel ebsare vel ef\'idete leallekum teşkurun.', 'Ve Allah,  sizi hiçbir şey bilmez halde,  annelerinizin karnından çıkardı. Size işitme yetisi[1],  görme yetisi[2] ve anlama yetisi[3] verdi. Umulur ki şükredersiniz.', 'والله اخرجكم من بطون امهتكم لا تعلمون شيا وجعل لكم السمع والابصر والافدة لعلكم تشكرون'),
(1980, 16, 79, 'اَلَمْ يَرَوْا اِلَى الطَّيْرِ مُسَخَّرَاتٍ ف۪ي جَوِّ السَّمَٓاءِۜ مَا يُمْسِكُهُنَّ اِلَّا اللّٰهُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ', 'E lem yerev ilet tayri musahharatin fi cevvis sema, ma yumsikuhunne illallah, inne fi zalike le ayatin li kavmin yu\'minun.', 'Gökyüzünün boşluğunda ilahi yasa gereği,  uçuşan kuşları görmüyorlar mı? Onları,  Allah\'tan başkası o boşlukta tutamaz. Bunda inanan bir halk için ayetler[1] vardır.', 'الم يروا الي الطير مسخرت في جو السما ما يمسكهن الا الله ان في ذلك لايت لقوم يومنون'),
(1981, 16, 80, 'وَاللّٰهُ جَعَلَ لَكُمْ مِنْ بُيُوتِكُمْ سَكَناً وَجَعَلَ لَكُمْ مِنْ جُلُودِ الْاَنْعَامِ بُيُوتاً تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ اِقَامَتِكُمْۙ وَمِنْ اَصْوَافِهَا وَاَوْبَارِهَا وَاَشْعَارِهَٓا اَثَاثاً وَمَتَاعاً اِلٰى ح۪ينٍ', 'Vallahu ceale lekum min buyutikum sekenen ve ceale lekum min culudil en\'ami buyuten testehıffuneha yevme za\'nikum ve yevme ikametikum ve min asvafiha ve evbariha ve eş\'ariha esasen ve metaan ila hin.', 'Allah,  evlerinizden sizin için bir huzur ve dinginlik yeri yaptı. Ve sizin için,  hayvanların derilerinden yolculuğunuz sırasında ve konaklamanızda taşınabilir çadırdan evler ve yünlerinden,  tüylerinden,  kıllarından ev eşyası ve geçim aracı yaptı.', 'والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الانعم بيوتا تستخفونها يوم ظعنكم ويوم اقامتكم ومن اصوافها واوبارها واشعارها اثثا ومتعا الي حين'),
(1982, 16, 81, 'وَاللّٰهُ جَعَلَ لَكُمْ مِمَّا خَلَقَ ظِلَالاً وَجَعَلَ لَكُمْ مِنَ الْجِبَالِ اَكْنَاناً وَجَعَلَ لَكُمْ سَرَاب۪يلَ تَق۪يكُمُ الْحَرَّ وَسَرَاب۪يلَ تَق۪يكُمْ بَأْسَكُمْۜ كَذٰلِكَ يُتِمُّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', 'Vallahu ceale lekum mimma halaka zılalen ve ceale lekum minel cibali eknanen ve ceale lekum serabile tekikumul harra ve serabile tekikum be\'sekum, kezalike yutimmu ni\'metehu aleykum leallekum tuslimun.', 'Allah,  sizin için,  yarattığı şeylerden gölgeler yaptı. Sizin için dağlardan sığınaklar,  sizi sıcaktan koruyacak giysiler ve şiddetli darbelerden koruyacak giysiler[1] yaptı. Sizin üzerinizdeki nimetini işte böyle tamamlıyor. Umulur ki; böylece teslim[2] olursunuz.', 'والله جعل لكم مما خلق ظللا وجعل لكم من الجبال اكننا وجعل لكم سربيل تقيكم الحر وسربيل تقيكم باسكم كذلك يتم نعمته عليكم لعلكم تسلمون'),
(1983, 16, 82, 'فَاِنْ تَوَلَّوْا فَاِنَّمَا عَلَيْكَ الْبَلَاغُ الْمُب۪ينُ', 'Fe in tevellev fe innema aleykel belagul mubin.', 'Eğer yüz çevirirlerse,  sana düşen sadece açık bir şekilde tebliğ[1] etmektir.', 'فان تولوا فانما عليك البلغ المبين'),
(1984, 16, 83, 'يَعْرِفُونَ نِعْمَتَ اللّٰهِ ثُمَّ يُنْكِرُونَهَا وَاَكْثَرُهُمُ الْكَافِرُونَ۟', 'Ya\'rifune ni\'metallahi summe yunkiruneha ve ekseruhumul kafirun.', 'Onlar,  bu nimetleri Allah\'ın verdiğini biliyorlar. Sonra da onu görmezden geliyorlar. Onların çoğu Kafir[2] kimselerdir.', 'يعرفون نعمت الله ثم ينكرونها واكثرهم الكفرون'),
(1985, 16, 84, 'وَيَوْمَ نَبْعَثُ مِنْ كُلِّ اُمَّةٍ شَه۪يداً ثُمَّ لَا يُؤْذَنُ لِلَّذ۪ينَ كَفَرُوا وَلَا هُمْ يُسْتَعْتَبُونَ', 'Ve yevme neb\'asu min kulli ummetin şehiden summe la yu\'zenu lillezinekeferu ve la hum yusta\'tebun.', 'Her ümmetten[1] bir tanık getirdiğimiz gün,  artık Kafirlere izin verilmez. Onlardan özür dilemeleri de istenmez.', 'ويوم نبعث من كل امة شهيدا ثم لا يوذن للذين كفروا ولا هم يستعتبون'),
(1986, 16, 85, 'وَاِذَا رَاَ الَّذ۪ينَ ظَلَمُوا الْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنْظَرُونَ', 'Ve iza raellezine zalemul azabe fe la yuhaffefuanhum ve la hum yunzarun.', 'Zulmeden kimseler,  azapla karşı karşıya kaldıklarında,  artık onlardan azap hafifletilmez. Ve onlara fırsat da verilmez.', 'واذا را الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون'),
(1987, 16, 86, 'وَاِذَا رَاَ الَّذ۪ينَ اَشْرَكُوا شُرَكَٓاءَهُمْ قَالُوا رَبَّـنَا هٰٓؤُ۬لَٓاءِ شُرَكَٓاؤُ۬نَا الَّذ۪ينَ كُنَّا نَدْعُوا مِنْ دُونِكَۚ فَاَلْقَوْا اِلَيْهِمُ الْقَوْلَ اِنَّكُمْ لَكَاذِبُونَۚ', 'Ve iza raellezine eşreku şurekaehum kalu rabbena haulai şurekaunellezine kunna ned\'u min dunik, fe elkav ileyhimul kavle innekum le kazibun.', 'Şirk[1] koşanlar,  şirk koştuklarını gördüklerinde: \"Rabb\'imiz! İşte bunlar,  Senin yanın sıra istekte bulunduğumuz,  yakardığımız ortaklarımız.\" diyecekler. Şirk koşulanlar da: \"Siz,  kesinlikle yalan söyleyenlersiniz.\" diyerek,  onları yalanlarlar.', 'واذا را الذين اشركوا شركاهم قالوا ربنا هولا شركاونا الذين كنا ندعوا من دونك فالقوا اليهم القول انكم لكذبون'),
(1988, 16, 87, 'وَاَلْقَوْا اِلَى اللّٰهِ يَوْمَئِذٍۨ السَّلَمَ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ', 'Ve elkav ilallahi yevme izinis seleme ve dalle anhum ma kanu yefterun.', 'İzin Günü[1],  Allah\'a teslim olurlar. Uydurdukları şeyler,  yüzüstü bırakarak onlardan uzaklaşırlar.', 'والقوا الي الله يوميذ السلم وضل عنهم ما كانوا يفترون'),
(1989, 16, 88, 'اَلَّذ۪ينَ كَفَرُوا وَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ زِدْنَاهُمْ عَذَاباً فَوْقَ الْعَذَابِ بِمَا كَانُوا يُفْسِدُونَ', 'Ellezine keferu ve saddu an sebilillahi zidnahum azaben fevkal azabi bima kanu yufsidun.', 'Allah\'ın yolundan alıkoyan Kafirlere,  yaptıkları bozgunculuk nedeniyle azap üstüne azap katarız.', 'الذين كفروا وصدوا عن سبيل الله زدنهم عذابا فوق العذاب بما كانوا يفسدون'),
(1990, 16, 89, 'وَيَوْمَ نَبْعَثُ ف۪ي كُلِّ اُمَّةٍ شَه۪يداً عَلَيْهِمْ مِنْ اَنْفُسِهِمْ وَجِئْنَا بِكَ شَه۪يداً عَلٰى هٰٓؤُ۬لَٓاءِۜ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَاناً لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرٰى لِلْمُسْلِم۪ينَ۟', 'Ve yevme neb\'asu fi kulli ummetin şehiden aleyhim min enfusihim ve ci\'nabike şehiden ala haula, ve nezzelna aleykel kitabe tibyanen likulli şey\'in ve huden ve rahmeten ve buşra lil muslimin.', 'Biz,  o gün,  her ümmet için kendi aralarından üzerlerine bir tanık getireceğiz. Seni de teslim olanlar için[1] yol gösterici,  rahmet ve haber verici olarak sana indirdiğimiz kitap ile her şeyin açıklandığına dair bunlara tanıklık yapman için getireceğiz.', 'ويوم نبعث في كل امة شهيدا عليهم من انفسهم وجينا بك شهيدا علي هولا ونزلنا عليك الكتب تبينا لكل شي وهدي ورحمة وبشري للمسلمين'),
(1991, 16, 90, 'اِنَّ اللّٰهَ يَأْمُرُ بِالْعَدْلِ وَالْاِحْسَانِ وَا۪يتَٓائِ ذِي الْقُرْبٰى وَيَنْهٰى عَنِ الْفَحْشَٓاءِ وَالْمُنْكَرِ وَالْبَغْيِۚ  يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'İnnallahe ye\'muru bil adli vel ihsani ve itai zil kurba ve yenha anil fahşai vel munkeri vel bagy, yeizukum leallekum tezekkerun.', 'Allah; adaleti,  ihsanı[1] ve yakınlarınızda olanlara yardım etmeyi,  buyurmakta; fahşadan[2],  münkerden[3] ve beğyiden[4] men etmektedir. İyice anlayıp tutmanız için size öğüt veriyor.', 'ان الله يامر بالعدل والاحسن وايتاي ذي القربي وينهي عن الفحشا والمنكر والبغي يعظكم لعلكم تذكرون'),
(1992, 16, 91, 'وَاَوْفُوا بِعَهْدِ اللّٰهِ اِذَا عَاهَدْتُمْ وَلَا تَنْقُضُوا الْاَيْمَانَ بَعْدَ تَوْك۪يدِهَا وَقَدْ جَعَلْتُمُ اللّٰهَ عَلَيْكُمْ كَف۪يلاًۜ اِنَّ اللّٰهَ يَعْلَمُ مَا تَفْعَلُونَ', 'Ve evfu bi ahdillahi iza ahedtum ve la tenkudul eymane ba\'de tevkidiha ve kad cealtumullahe aleykum kefila, innallahe ya\'lemu ma tef\'alun.', 'Söz verdiğiniz zaman,  verdiğiniz sözü Allah için tutun. Allah\'ı kendinize kefil kılarak,  pekiştirdikten sonra yeminlerinizi bozmayın. Allah ne yaptığınızı bilir.', 'واوفوا بعهد الله اذا عهدتم ولا تنقضوا الايمن بعد توكيدها وقد جعلتم الله عليكم كفيلا ان الله يعلم ما تفعلون'),
(1993, 16, 92, 'وَلَا تَكُونُوا كَالَّت۪ي نَقَضَتْ غَزْلَهَا مِنْ بَعْدِ قُوَّةٍ اَنْكَاثاًۜ تَتَّخِذُونَ اَيْمَانَكُمْ دَخَلاً بَيْنَكُمْ اَنْ تَكُونَ اُمَّةٌ هِيَ اَرْبٰى مِنْ اُمَّةٍۜ اِنَّمَا يَبْلُوكُمُ اللّٰهُ بِه۪ۜ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ الْقِيٰمَةِ مَا كُنْتُمْ ف۪يهِ تَخْتَلِفُونَ', 'Ve la tekunu kelleti nekadat gazleha min ba\'di kuvvetin enkasa, tettehızune eymanekum dehalen beynekum en tekune ummetun hiye erba min ummeh, innema yeblukumullahu bih, ve le yubeyyinenne lekum yevmel kıyameti ma kuntum fihi tahtelifun.', 'İçinizden bir topluluğun başka bir topluluktan daha ribalı[1] olmasından etkilenerek,  yeminlerinizi aldatma amacıyla; ipliğini sağlamca eğirdikten sonra,  onu geri çözüp bozan kadın gibi olmayın. Allah,  sizi bununla[2] sınıyor. Hakkında anlaşmazlığa düştüğünüz şeyler,  kıyamet günü size açıklanacaktır.', 'ولا تكونوا كالتي نقضت غزلها من بعد قوة انكثا تتخذون ايمنكم دخلا بينكم ان تكون امة هي اربي من امة انما يبلوكم الله به وليبينن لكم يوم القيمة ما كنتم فيه تختلفون'),
(1994, 16, 93, 'وَلَوْ شَٓاءَ اللّٰهُ لَجَعَلَكُمْ اُمَّةً وَاحِدَةً وَلٰكِنْ يُضِلُّ مَنْ يَشَٓاءُ وَيَهْد۪ي مَنْ يَشَٓاءُۜ وَلَتُسْـَٔلُنَّ عَمَّا كُنْتُمْ تَعْمَلُونَ', 'Ve lev şaallahu le cealekum ummeten vahideten ve lakin yudıllu men yeşau ve yehdi men yeşa\', ve le tus\'elunne amma kuntum ta\'melun.', 'Allah,  dileseydi[1] sizi tek bir ümmet[2] yapardı. Fakat Allah hak edeni[3] saptırır,  hak edeni[3] de doğru yola iletir. Siz,  yaptığınız her şeyden sorumlu tutulacaksınız.[4]', 'ولو شا الله لجعلكم امة وحدة ولكن يضل من يشا ويهدي من يشا ولتسلن عما كنتم تعملون'),
(1995, 16, 94, 'وَلَا تَتَّخِذُٓوا اَيْمَانَكُمْ دَخَلاً بَيْنَكُمْ فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا السُّٓوءَ بِمَا صَدَدْتُمْ عَنْ سَب۪يلِ اللّٰهِۚ وَلَكُمْ عَذَابٌ عَظ۪يمٌ', 'Ve la tettehızu eymanekum dehalen beynekum fe tezille kademun ba\'de subutiha ve tezukus sue bima sadedtum an sebilillah, ve lekum azabun azim.', 'Yeminlerinizi,  aranızda aldatma ve bozgunculuğa araç yapmayın. Yoksa yere sağlam bastıktan sonra[1] ayak kayar. Allah\'ın yoluna engel olduğunuzdan dolayı kötülükle karşı karşıya kalırsınız. Ve büyük bir azaba uğrarsınız.', 'ولا تتخذوا ايمنكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السو بما صددتم عن سبيل الله ولكم عذاب عظيم'),
(1996, 16, 95, 'وَلَا تَشْتَرُوا بِعَهْدِ اللّٰهِ ثَمَناً قَل۪يلاًۜ اِنَّمَا عِنْدَ اللّٰهِ هُوَ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Ve la teşteru bi ahdillahi semenen kalila, innema indallahi huve hayrun lekum in kuntum ta\'lemun.', 'Allah\'ın ahdini[1],  küçük bir çıkara değiştirmeyin. Şayet bilirseniz,  Allah\'ın yanındaki ödülünüz daha iyidir.', 'ولا تشتروا بعهد الله ثمنا قليلا انما عند الله هو خير لكم ان كنتم تعلمون'),
(1997, 16, 96, 'مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللّٰهِ بَاقٍۜ وَلَنَجْزِيَنَّ الَّذ۪ينَ صَبَرُٓوا اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوا يَعْمَلُونَ', 'Ma ındekum yenfedu ve ma ındallahi bak, ve le necziyennellezine saberu ecrehum bi ahseni ma kanu ya\'melun.', 'Sizin yanınızda olan şeyler tükenir,  Allah\'ın yanında olan şeyler ise tükenmez. Sabredenlere,  ödüllerini yaptıkları şeylerin karşılığı olarak en iyi şekilde vereceğiz.', 'ما عندكم ينفد وما عند الله باق ولنجزين الذين صبروا اجرهم باحسن ما كانوا يعملون'),
(1998, 16, 97, 'مَنْ عَمِلَ صَالِحاً مِنْ ذَكَرٍ اَوْ اُنْثٰى وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيٰوةً طَيِّبَةًۚ وَلَنَجْزِيَنَّهُمْ اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوا يَعْمَلُونَ', 'Men amile salihan min zekerin ev unsa ve huve mu\'minun fe le nuhyiyennehu hayaten tayyibeh, ve le necziyennehum ecrehum bi ahseni ma kanu ya\'melun.', 'Erkek ve kadın,  mü\'min olarak kim salihatı yaparsa[1],  ona hoş,  temiz bir hayat yaşatırız. Kesinlikle yaptıklarının karşılığını daha iyisiyle veririz.', 'من عمل صلحا من ذكر او انثي وهو مومن فلنحيينه حيوة طيبة ولنجزينهم اجرهم باحسن ما كانوا يعملون'),
(1999, 16, 98, 'فَاِذَا قَرَأْتَ الْقُرْاٰنَ فَاسْتَعِذْ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّج۪يمِ', 'Fe iza kare\'tel kur\'ane festeız billahi mineş şeytanir racim.', 'Kur\'an okuduğun zaman,  recmedilmiş[1] şeytandan Allah\'a sığın.[2]', 'فاذا قرات القران فاستعذ بالله من الشيطن الرجيم'),
(2000, 16, 99, 'اِنَّهُ لَيْسَ لَهُ سُلْطَانٌ عَلَى الَّذ۪ينَ اٰمَنُوا وَعَلٰى رَبِّهِمْ يَتَوَكَّلُونَ', 'İnnehu leyse lehu sultanun alellezine amenu ve ala rabbihim yetevekkelun.', 'Kuşkusuz,  iman etmiş ve Rabb\'lerine tevekkül[1] eden kimseler üzerinde,  onun bir sultanlığı[2] yoktur.', 'انه ليس له سلطن علي الذين امنوا وعلي ربهم يتوكلون'),
(2001, 16, 100, 'اِنَّمَا سُلْطَانُهُ عَلَى الَّذ۪ينَ يَتَوَلَّوْنَهُ وَالَّذ۪ينَ هُمْ بِه۪ مُشْرِكُونَ۟', 'İnnema sultanuhu alellezine yetevellevnehu vellezine hum bihi müşrikun.', 'Onun sultanlığı, [1] ancak kendisini veli[2] edinen ve Allah\'a ortak koşan kimseler için söz konusudur.', 'انما سلطنه علي الذين يتولونه والذين هم به مشركون'),
(2002, 16, 101, 'وَاِذَا بَدَّلْـنَٓا اٰيَةً مَكَانَ اٰيَةٍۙ وَاللّٰهُ اَعْلَمُ بِمَا يُنَزِّلُ قَالُٓوا اِنَّـمَٓا اَنْتَ مُفْتَرٍۜ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَ', 'Ve iza beddelna ayeten mekane ayetin vallahu a\'lemu bima yunezzilu kalu innema ente mufter, bel ekseruhum la ya\'lemun.', 'Biz,  bir ayeti,  başka bir ayetle değiştirdiğimiz[1] zaman: \"Allah ne indirdiğini bilirken[2],  sen kesinlikle uyduruyorsun.\" derler. Hayır,  onların çoğu gerçeği bilmiyor.', 'واذا بدلنا اية مكان اية والله اعلم بما ينزل قالوا انما انت مفتر بل اكثرهم لا يعلمون'),
(2003, 16, 102, 'قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِنْ رَبِّكَ بِالْحَقِّ لِيُثَبِّتَ الَّذ۪ينَ اٰمَنُوا وَهُدًى وَبُشْرٰى لِلْمُسْلِم۪ينَ', 'Kul nezzelehu ruhul kudusi min rabbike bil hakkı li yusebbitellezine amenu ve huden ve buşra lil muslimin.', 'De ki: \"İman edenlerin; imanlarını pekiştirmek,  Müslümanlara kılavuz ve müjde olmak üzere,  Rabb\'inden,  Hakk ile o Kudus\'un Ruhu[1] çokça[2] indi.\"', 'قل نزله روح القدس من ربك بالحق ليثبت الذين امنوا وهدي وبشري للمسلمين'),
(2004, 16, 103, 'وَلَقَدْ نَعْلَمُ اَنَّهُمْ يَقُولُونَ اِنَّمَا يُعَلِّمُهُ بَشَرٌۜ لِسَانُ الَّذ۪ي يُلْحِدُونَ اِلَيْهِ اَعْجَمِيٌّ وَهٰذَا لِسَانٌ عَرَبِيٌّ مُب۪ينٌ', 'Ve lekad na\'lemu ennehum yekulune innema yuallimuhu beşer, lisanullezi yulhıdune ileyhi a\'cemiyyun ve haza lisanun arabiyyun mubin.', 'Ant olsun ki Biz,  onların: \"Ona ancak bir beşer[1] öğretiyor.\" dediklerini biliyoruz. Kastettikleri kimsenin dili yabancıdır. Bu ise apaçık bir Arapça\'dır.', 'ولقد نعلم انهم يقولون انما يعلمه بشر لسان الذي يلحدون اليه اعجمي وهذا لسان عربي مبين'),
(2005, 16, 104, 'اِنَّ الَّذ۪ينَ لَا يُؤْمِنُونَ بِاٰيَاتِ اللّٰهِۙ لَا يَهْد۪يهِمُ اللّٰهُ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnellezine la yu\'minune bi ayatillahi la yehdihimullahu ve lehum azabun elim.', 'Allah,  Allah\'ın ayetlerine inanmayanları doğru yola iletmez. Ve onlar için çok acı bir azap vardır.', 'ان الذين لا يومنون بايت الله لا يهديهم الله ولهم عذاب اليم'),
(2006, 16, 105, 'اِنَّمَا يَفْتَرِي الْكَذِبَ الَّذ۪ينَ لَا يُؤْمِنُونَ بِاٰيَاتِ اللّٰهِۚ وَاُو۬لٰٓئِكَ هُمُ الْكَاذِبُونَ', 'İnnema yefteril kezibellezine la yu\'minune bi ayatillahi ve ulaike humul kazibun.', 'Ancak,  Allah\'ın ayetlerine inanmayanlar yalan uydururlar. Zaten onlar,  yalancıların ta kendileridir.', 'انما يفتري الكذب الذين لا يومنون بايت الله واوليك هم الكذبون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2007, 16, 106, 'مَنْ كَفَرَ بِاللّٰهِ مِنْ بَعْدِ ا۪يمَانِه۪ٓ اِلَّا مَنْ اُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْا۪يمَانِ وَلٰكِنْ مَنْ شَرَحَ بِالْكُفْرِ صَدْراً فَعَلَيْهِمْ غَضَبٌ مِنَ اللّٰهِۚ وَلَهُمْ عَذَابٌ عَظ۪يمٌ', 'Men kefere billahi min ba\'di imanihi illa men ukrihe ve kalbuhu mutmainnun bil imani ve lakin men şereha bil kufri sadran fe aleyhim gadabun minallah, ve lehum azabun azim.', 'Kalbi iman ile yatışmış olduğu halde,  -baskı ile inkara zorlanan kimse hariç- kim imanından sonra Allah\'ı küfrederse[1] ve kim küfre göğüs açarsa,  bilsin ki Allah\'ın gazabı onların üzerinedir. Bunlar için büyük bir azap vardır.', 'من كفر بالله من بعد ايمنه الا من اكره وقلبه مطمين بالايمن ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم'),
(2008, 16, 107, 'ذٰلِكَ بِاَنَّهُمُ اسْتَحَبُّوا الْحَيٰوةَ الدُّنْيَا عَلَى الْاٰخِرَةِۙ وَاَنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الْكَافِر۪ينَ', 'Zalike bi ennehumustehebbul hayated dunya alel ahıreti ve ennallahe la yehdil kavmel kafirin.', 'Bunun nedeni,  onların dünya hayatını sevip onu ahirete tercih etmeleridir. Allah,  Kafir halkı doğru yola iletmez.', 'ذلك بانهم استحبوا الحيوة الدنيا علي الاخرة وان الله لا يهدي القوم الكفرين'),
(2009, 16, 108, 'اُو۬لٰٓئِكَ الَّذ۪ينَ طَبَعَ اللّٰهُ عَلٰى قُلُوبِهِمْ وَسَمْعِهِمْ وَاَبْصَارِهِمْۚ وَاُو۬لٰٓئِكَ هُمُ الْغَافِلُونَ', 'Ulaikellezine tabeallahu ala kulubihim ve sem\'ihim ve ebsarihim, ve ulaike humul gafilun.', 'İşte onlar,  Allah\'ın kalplerini[1],  kulaklarını ve gözlerini mühürlediği kimselerdir. Onlar,  gafil olanların ta kendileridir.', 'اوليك الذين طبع الله علي قلوبهم وسمعهم وابصرهم واوليك هم الغفلون'),
(2010, 16, 109, 'لَا جَرَمَ اَنَّهُمْ فِي الْاٰخِرَةِ هُمُ الْخَاسِرُونَ', 'La cereme ennehum fil ahıreti humul hasirun.', 'Kuşkusuz onlar,  ahirette hüsranda olanlardır.', 'لا جرم انهم في الاخرة هم الخسرون'),
(2011, 16, 110, 'ثُمَّ اِنَّ رَبَّكَ لِلَّذ۪ينَ هَاجَرُوا مِنْ بَعْدِ مَا فُتِنُوا ثُمَّ جَاهَدُوا وَصَبَرُٓواۙ اِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَح۪يمٌ۟', 'Summe inne rabbeke lillezine haceru min ba\'di ma futinu summe cahedu ve saberu inne rabbeke min ba\'diha le gafurun rahim.', 'Sonra,  Rabb\'in,  zulme uğrayıp hicret etme zorunda kalan,  ardından da cihat edip,  sabredenlerin[1] yanındadır. Rabb\'in,  onlara karşı Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ثم ان ربك للذين هاجروا من بعد ما فتنوا ثم جهدوا وصبروا ان ربك من بعدها لغفور رحيم'),
(2012, 16, 111, 'يَوْمَ تَأْت۪ي كُلُّ نَفْسٍ تُجَادِلُ عَنْ نَفْسِهَا وَتُوَفّٰى كُلُّ نَفْسٍ مَا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'Yevme te\'ti kullu nefsin tucadilu an nefsiha ve tuveffa kullu nefsin ma amilet ve hum la yuzlemun.', 'O gün gelir ve herkes kendi canını kurtarmak için çabalar. Herkese,  yaptığı şeylerin karşılığı tastamam ödenir. Onlara asla haksızlık edilmez.', 'يوم تاتي كل نفس تجدل عن نفسها وتوفي كل نفس ما عملت وهم لا يظلمون'),
(2013, 16, 112, 'وَضَرَبَ اللّٰهُ مَثَلاً قَرْيَةً كَانَتْ اٰمِنَةً مُطْمَئِنَّةً يَأْت۪يهَا رِزْقُهَا رَغَداً مِنْ كُلِّ مَكَانٍ فَكَفَرَتْ بِاَنْعُمِ اللّٰهِ فَاَذَاقَهَا اللّٰهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ', 'Ve daraballahu meselen karyeten kanet amineten mutmainneten ye\'tiha rızkuha ragaden min kulli mekanin fe keferet bi en\'umillahi fe ezakahallahu libasel cui vel havfi bima kanu yasnaun.', 'Allah,  güvenli ve her yönden tatmin olmuş bir kenti örnek verdi. Oraya,  her yerden bol bol rızık geliyordu. Ne var ki,  Allah\'ın nimetlerine nankörlük ettiler. Bunun üzerine Allah da onlara kaypaklıkları nedeniyle açlık ve korku elbisesini tattırdı.[1]', 'وضرب الله مثلا قرية كانت امنة مطمينة ياتيها رزقها رغدا من كل مكان فكفرت بانعم الله فاذقها الله لباس الجوع والخوف بما كانوا يصنعون'),
(2014, 16, 113, 'وَلَقَدْ جَٓاءَهُمْ رَسُولٌ مِنْهُمْ فَكَذَّبُوهُ فَاَخَذَهُمُ الْعَذَابُ وَهُمْ ظَالِمُونَ', 'Ve lekad caehum resulun minhum fe kezzebuhu fe ehazehumul azabu ve hum zalimun.', 'Ant olsun ki,  onlara,  içlerinden bir resul geldi. Fakat onu yalanladılar. Bunun üzerine onları azap yakaladı. Onlar zalimlerdir.', 'ولقد جاهم رسول منهم فكذبوه فاخذهم العذاب وهم ظلمون'),
(2015, 16, 114, 'فَكُلُوا مِمَّا رَزَقَكُمُ اللّٰهُ حَلَالاً طَيِّباًۖ وَاشْكُرُوا نِعْمَتَ اللّٰهِ اِنْ كُنْتُمْ اِيَّاهُ تَعْبُدُونَ', 'Fe kulu mimma razakakumullahu halalen tayyiben veşkuru ni\'metallahi in kuntum iyyahu ta\'budun.', 'Eğer Allah\'a kulluk ediyorsanız,  Allah\'ın nimetine şükredin. Allah\'ın size verdiği rızıklardan helal ve temiz olarak yiyin.', 'فكلوا مما رزقكم الله حللا طيبا واشكروا نعمت الله ان كنتم اياه تعبدون'),
(2016, 16, 115, 'اِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنْز۪يرِ وَمَٓا اُهِلَّ لِغَيْرِ اللّٰهِ بِه۪ۚ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İnnema harreme aleykumul meytete veddeme ve lahmel hınziri ve ma uhılle li gayrillahi bih, fe menıdturra gayre bagın ve la adin fe innallahe gafurun rahim.', 'Allah,  size haram kıldı: ölmüş hayvan etini,  kanı,  domuz etini ve Allah\'tan başkası adına kesilenleri[1] Ancak kim mecbur kalırsa[2] haddi aşmadığı ve hakkı çiğnemediği takdirde yiyebilir.[3] Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'انما حرم عليكم الميتة والدم ولحم الخنزير وما اهل لغير الله به فمن اضطر غير باغ ولا عاد فان الله غفور رحيم'),
(2017, 16, 116, 'وَلَا تَقُولُوا لِمَا تَصِفُ اَلْسِنَتُكُمُ الْكَذِبَ هٰذَا حَلَالٌ وَهٰذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللّٰهِ الْكَذِبَۜ اِنَّ الَّذ۪ينَ يَفْتَرُونَ عَلَى اللّٰهِ الْكَذِبَ لَا يُفْلِحُونَۜ', 'Ve la tekulu lima tesıfu elsinetukumul kezibe haza halalun ve haza haramun li tefteru alallahil kezib, innellezine yefterune alallahil kezibe la yuflihun.', 'Kendi yalanlarınızı,  Allah\'a dayandırarak,  dilinize geldiği gibi yalan yanlış,  \"Şu helaldir,  şu haramdır.\" demeyin. Uydurduğu yalanı Allah\'a dayandıranlar,  kurtuluşa eremezler.[1]', 'ولا تقولوا لما تصف السنتكم الكذب هذا حلل وهذا حرام لتفتروا علي الله الكذب ان الذين يفترون علي الله الكذب لا يفلحون'),
(2018, 16, 117, 'مَتَاعٌ قَل۪يلٌۖ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'Metaun kalilun ve lehum azabun elim.', 'Bu yaptıkları az bir yararlanmadır. Onlara acı bir azap vardır.', 'متع قليل ولهم عذاب اليم'),
(2019, 16, 118, 'وَعَلَى الَّذ۪ينَ هَادُوا حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِنْ قَبْلُۚ وَمَا ظَلَمْنَاهُمْ وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'Ve alellezine hadu harremna ma kasasna aleyke min kabl, ve ma zalemnahum ve lakin kanu enfusehum yazlimun.', 'Sana anlattıklarımızı daha önce Yahudilere de haram kılmıştık. Biz,  onlara haksızlık yapmadık. Fakat onlar kendi kendilerine haksızlık ediyorlardı.', 'وعلي الذين هادوا حرمنا ما قصصنا عليك من قبل وما ظلمنهم ولكن كانوا انفسهم يظلمون'),
(2020, 16, 119, 'ثُمَّ اِنَّ رَبَّكَ لِلَّذ۪ينَ عَمِلُوا السُّٓوءَ بِجَهَالَةٍ ثُمَّ تَابُوا مِنْ بَعْدِ ذٰلِكَ وَاَصْلَحُٓواۙ اِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَح۪يمٌ۟', 'Summe inne rabbeke lillezine amilus sue bi cehaletin summe tabu min ba\'di zalike ve aslahu inne rabbeke min ba\'diha le gafurun rahim.', 'Sonra,  Rabb\'in,  cahillikle[1] kötülük yapan ve sonra bunun ardından tevbe edip kendisini düzelten kimseleri bağışlar. Çünkü Rabb\'in Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ثم ان ربك للذين عملوا السو بجهلة ثم تابوا من بعد ذلك واصلحوا ان ربك من بعدها لغفور رحيم'),
(2021, 16, 120, 'اِنَّ اِبْرٰه۪يمَ كَانَ اُمَّةً قَانِتاً لِلّٰهِ حَن۪يفاًۜ وَلَمْ يَكُ مِنَ الْمُشْرِك۪ينَۙ', 'İnne ibrahime kane ummeten kaniten lillahi hanifa ve lem yeku minel muşrikin.', 'İbrahim,  hanif[1] olarak Allah\'a yönelen bir ümmetti.[2] Ve müşriklerden değildi.', 'ان ابرهيم كان امة قانتا لله حنيفا ولم يك من المشركين'),
(2022, 16, 121, 'شَاكِراً لِاَنْعُمِهِۜ اِجْتَبٰيهُ وَهَدٰيهُ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Şakiren li en\'umih, ictebahu ve hudahu ila sıratın mustekim.', 'Allah\'ın nimetlerine şükrediciydi. Onu seçti ve dosdoğru yola iletti.', 'شاكرا لانعمه اجتبيه وهديه الي صرط مستقيم'),
(2023, 16, 122, 'وَاٰتَيْنَاهُ فِي الدُّنْيَا حَسَنَةًۜ وَاِنَّهُ فِي الْاٰخِرَةِ لَمِنَ الصَّالِح۪ينَۜ', 'Ve ateynahu fid dunya haseneh, ve innehu fil ahıreti le mines salihin.', 'Ona dünyada iyilikler verdik ve kuşkusuz o,  ahirette de salihlerdendir.[1]', 'واتينه في الدنيا حسنة وانه في الاخرة لمن الصلحين'),
(2024, 16, 123, 'ثُمَّ اَوْحَيْنَٓا اِلَيْكَ اَنِ اتَّبِـعْ مِلَّةَ اِبْرٰه۪يمَ حَن۪يفاًۜ وَمَا كَانَ مِنَ الْمُشْرِك۪ينَ', 'Summe evhayna ileyke enittebi\' millete ibrahime hanifa, ve ma kane minel muşrikin.', 'Sonra sana: \"Hanif olarak İbrahim\'in milletine[1] uy,  o müşriklerden değildi.\" diye vahyettik.', 'ثم اوحينا اليك ان اتبع ملة ابرهيم حنيفا وما كان من المشركين'),
(2025, 16, 124, 'اِنَّمَا جُعِلَ السَّبْتُ عَلَى الَّذ۪ينَ اخْتَلَفُوا ف۪يهِۜ وَاِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'İnnema cuiles sebtu alellezinahtelefu fih, ve inne rabbeke le yahkumu beynehum yevmel kıyameti fima kanu fihi yahtelifun.', 'Sebt[1] yalnızca ihtilafa düşenler üzerine kılındı.[2] Kuşkusuz,  senin Rabb\'in ihtilaf edip durdukları şeyler hakkında Kıyamet Günü,  aralarında kesinlikle hüküm verecektir.', 'انما جعل السبت علي الذين اختلفوا فيه وان ربك ليحكم بينهم يوم القيمة فيما كانوا فيه يختلفون'),
(2026, 16, 125, 'اُدْعُ اِلٰى سَب۪يلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّت۪ي هِيَ اَحْسَنُۜ اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِمَنْ ضَلَّ عَنْ سَب۪يلِه۪ وَهُوَ اَعْلَمُ بِالْمُهْتَد۪ينَ', 'Ud\'u ila sebili rabbike bil hikmeti vel mev\'ızatil haseneti ve cadilhum billeti hiye ahsen, inne rabbeke huve a\'lemu bi men dalle an sebilihi ve huve a\'lemu bil muhtedin.', 'Rabb\'inin yoluna,  hikmetle[1] ve iyiliği öğütleyerek çağır. Onlarla en iyi şekilde mücadele et. Kuşkusuz Rabb\'in,  kimin Kendi yolundan saptığını çok iyi bilir; doğru yolda olanları da en iyi O bilir.', 'ادع الي سبيل ربك بالحكمة والموعظة الحسنة وجدلهم بالتي هي احسن ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين'),
(2027, 16, 126, 'وَاِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِه۪ۜ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِر۪ينَ', 'Ve in akabtum fe akıbu bi misli ma ukıbtum bih, ve le in sabertum le huve hayrun lis sabirin.', 'Eğer siz,  sert karşılık vermek zorunda kalırsanız,  o zaman onların size verdiği karşılığa orantılı olarak karşılık verin. Ama sabrederseniz[1],  elbette böyle bir davranış sabredenler için daha hayırlıdır.', 'وان عاقبتم فعاقبوا بمثل ما عوقبتم به ولين صبرتم لهو خير للصبرين'),
(2028, 16, 127, 'وَاصْبِرْ وَمَا صَبْرُكَ اِلَّا بِاللّٰهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ ف۪ي ضَيْقٍ مِمَّا يَمْكُرُونَ', 'Vasbır ve ma sabruke illa billahi ve la tahzen aleyhim ve la teku fi daykın mimma yemkurun.', 'Sabret! Senin sabrın yalnızca Allah iledir[1]. Onlar için üzülme. Onların kurdukları tuzaklar nedeniyle darlanma.', 'واصبر وما صبرك الا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون'),
(2029, 16, 128, 'اِنَّ اللّٰهَ مَعَ الَّذ۪ينَ اتَّقَوْا وَالَّذ۪ينَ هُمْ مُحْسِنُونَ', 'İnnallahe meallezinettekav vellezine hum muhsinun.', 'Kuşkusuz,  Allah,  takvalı[1] olanlarla ve iyi davranan kimselerle beraberdir.', 'ان الله مع الذين اتقوا والذين هم محسنون'),
(2030, 17, 1, 'سُبْحَانَ الَّـذ۪ٓي اَسْرٰى بِعَبْدِه۪ لَيْلاً مِنَ الْمَسْجِدِ الْحَرَامِ اِلَى الْمَسْجِدِ الْاَقْصَا الَّذ۪ي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ اٰيَاتِنَاۜ اِنَّهُ هُوَ السَّم۪يعُ الْبَص۪يرُ', 'Subhanellezi esra bi abdihi leylen minel mescidil harami ilel mescidil aksallezi barekna havlehu li nuriyehu min ayatina, innehu huves semiul basir.', 'O subhandır.[1] Kulunu,  Mescid-i Haram\'dan[2] çevresini mübarek kıldığımız Mescid-i Aksa\'ya[3] bir gece yürüttü. Ona ayetlerimizi göstermek için. Kuşkusuz O,  Her Şeyi Duyan\'dır,  Her Şeyi Gören\'dir.', 'سبحن الذي اسري بعبده ليلا من المسجد الحرام الي المسجد الاقصا الذي بركنا حوله لنريه من ايتنا انه هو السميع البصير'),
(2031, 17, 2, 'وَاٰتَيْنَا مُوسَى الْكِتَابَ وَجَعَلْنَاهُ هُدًى لِبَن۪ٓي اِسْرَٓائ۪لَ اَلَّا تَتَّخِذُوا مِنْ دُون۪ي وَك۪يلاًۜ', 'Ve ateyna musel kitabe ve cealnahu huden li beni israile ella tettehızu min duni vekila.', 'Musa\'ya,  İsrailoğulları\'na,  Ben\'den başka bir vekil[1] edinmeyin diye,  doğru yola ileten o Kitap\'ı verdik.', 'واتينا موسي الكتب وجعلنه هدي لبني اسريل الا تتخذوا من دوني وكيلا'),
(2032, 17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍۜ اِنَّهُ كَانَ عَبْداً شَكُوراً', 'Zurriyyete men hamelna mea nuh, innehu kane abden şekura.', 'Ey Nuh ile birlikte taşıdığımız kimselerin soyundan olanlar! Gerçek şu ki,  o çok şükreden bir kuldu.', 'ذرية من حملنا مع نوح انه كان عبدا شكورا'),
(2033, 17, 4, 'وَقَضَيْنَٓا اِلٰى بَن۪ٓي اِسْرَٓائ۪لَ فِي الْكِتَابِ لَتُفْسِدُنَّ فِي الْاَرْضِ مَرَّتَيْنِ وَلَتَعْـلُنَّ عُـلُواًّ كَب۪يراً', 'Ve kadayna ila beni israile fil kitabi le tufsidunne fil ardı merreteyni ve le ta\'lunne uluvven kebira.', 'İsrailoğulları\'na Kitap\'ta[1] yargıda bulunduk: \"Siz kesinlikle iki kez yeryüzünde fesat çıkaracaksınız ve kibirlenip böbürleneceksiniz.\"', 'وقضينا الي بني اسريل في الكتب لتفسدن في الارض مرتين ولتعلن علوا كبيرا'),
(2034, 17, 5, 'فَاِذَا جَٓاءَ وَعْدُ اُو۫لٰيهُمَا بَعَثْنَا عَلَيْكُمْ عِبَاداً لَنَٓا اُو۬ل۪ي بَأْسٍ شَد۪يدٍ فَجَاسُوا خِلَالَ الدِّيَارِۜ وَكَانَ وَعْداً مَفْعُولاً', 'Fe iza cae va\'du ulahuma beasna aleykum ibaden lena ulibe\'sin şedidin fe casu hılaled diyar, ve kane va\'den mef\'ula.', 'Birincisinin zamanı gelince çok güçlü kullarımızı üzerinize gönderdik. Yurtlarının içlerine kadar girdiler,  işgal ettiler. Böylece yapılan uyarı gerçekleşmiş oldu.', 'فاذا جا وعد اوليهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلل الديار وكان وعدا مفعولا'),
(2035, 17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ الْكَرَّةَ عَلَيْهِمْ وَاَمْدَدْنَاكُمْ بِاَمْوَالٍ وَبَن۪ينَ وَجَعَلْنَاكُمْ اَكْثَرَ نَف۪يراً', 'Summe rededna lekumul kerrete aleyhim ve emdednakum bi emvalin ve benine ve cealnakum eksere nefira.', 'Sonra sizi,  onlara karşı tekrar üstün kıldık. Size mallarla ve evlatlarla yardım ettik. Ve sayınızı çokça artırdık.', 'ثم رددنا لكم الكرة عليهم وامددنكم بامول وبنين وجعلنكم اكثر نفيرا'),
(2036, 17, 7, 'اِنْ اَحْسَنْتُمْ اَحْسَنْتُمْ لِاَنْفُسِكُمْ وَاِنْ اَسَأْتُمْ فَلَهَاۜ فَاِذَا جَٓاءَ وَعْدُ الْاٰخِرَةِ لِيَسُٓؤُ۫ا وُجُوهَكُمْ وَلِيَدْخُلُوا الْمَسْجِدَ كَمَا دَخَلُوهُ اَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا مَا عَلَوْا تَتْب۪يراً', 'İn ahsentum ahsentum li enfusikum ve in ese\'tum fe leha, fe iza cae va\'dul ahıreti li yesuu vucuhekum ve li yedhulul mescide kema dehaluhu evvele merretin ve li yutebbiru ma alev tetbira.', 'Eğer iyilik yaparsanız,  kendinize iyilik yapmış olursunuz. Eğer kötü olursanız,  o da kendiniz içindir. Diğer bozgunculuğunuzun cezalandırma zamanı geldiğinde,  sizi kötü duruma düşürmek için,  ilk kez girdikleri gibi mescide[1] girsinler. Ve yücelttiğiniz şeyleri darmadağın edip mahvetsinler.', 'ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جا وعد الاخرة ليسوا وجوهكم وليدخلوا المسجد كما دخلوه اول مرة وليتبروا ما علوا تتبيرا'),
(2037, 17, 8, 'عَسٰى رَبُّكُمْ اَنْ يَرْحَمَكُمْۚ وَاِنْ عُدْتُمْ عُدْنَاۢ وَجَعَلْنَا جَهَنَّمَ لِلْكَافِر۪ينَ حَص۪يراً', 'Asa rabbukum en yerhamekum, ve in udtum udna, ve cealna cehenneme lil kafirine hasira.', 'Umulur ki Rabb\'iniz size merhamet eder. Eğer siz dönerseniz,  Biz de döneriz.[1] Ve Biz Cehennem\'i Kafirler[2] için kuşatıcı kıldık.', 'عسي ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكفرين حصيرا'),
(2038, 17, 9, 'اِنَّ هٰذَا الْقُرْاٰنَ يَهْد۪ي لِلَّت۪ي هِيَ اَقْوَمُ وَيُبَشِّرُ الْمُؤْمِن۪ينَ الَّذ۪ينَ يَعْمَلُونَ الصَّالِحَاتِ اَنَّ لَهُمْ اَجْراً كَب۪يراًۙ', 'İnne hazel kur\'ane yehdi lilleti hiye akvemu ve yubeşşirul mu\'mininellezine ya\'melunes salihati enne lehum ecren kebira.', 'Kuşkusuz bu Kur\'an,  en doğru yolu gösterir. Salihatı yapan[1] müminlere kesinlikle büyük bir ödül olduğunu müjdeler.', 'ان هذا القران يهدي للتي هي اقوم ويبشر المومنين الذين يعملون الصلحت ان لهم اجرا كبيرا'),
(2039, 17, 10, 'وَاَنَّ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ اَعْتَدْنَا لَهُمْ عَذَاباً اَل۪يماً۟', 'Ve ennellezine la yu\'minune bil ahıreti a\'tedna lehum azaben elima.', 'Ahirete inanmayanlara can yakıcı bir azap hazırlandığını haber verir.', 'وان الذين لا يومنون بالاخرة اعتدنا لهم عذابا اليما'),
(2040, 17, 11, 'وَيَدْعُ الْاِنْسَانُ بِالشَّرِّ دُعَٓاءَهُ بِالْخَيْرِۜ وَكَانَ الْاِنْسَانُ عَجُولاً', 'Ve yed\'ul insanu biş şerri duaehu bil hayr, ve kanel insanu acula.', 'İnsan hayra dua eder gibi,  şerre dua ediyor. İnsan çok acelecidir.', 'ويدع الانسن بالشر دعاه بالخير وكان الانسن عجولا'),
(2041, 17, 12, 'وَجَعَلْنَا الَّيْلَ وَالنَّهَارَ اٰيَتَيْنِ فَمَحَوْنَٓا اٰيَةَ الَّيْلِ وَجَعَلْـنَٓا اٰيَةَ النَّهَارِ مُبْصِرَةً لِتَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ وَلِتَعْلَمُوا عَدَدَ السِّن۪ينَ وَالْحِسَابَۜ وَكُلَّ شَيْءٍ فَصَّلْنَاهُ تَفْص۪يلاً', 'Ve cealnel leyle ven nehare ayeteyni fe mehavna ayetel leyli ve cealna ayeten nehari mubsıraten li tebtegu fadlen min rabbikum ve li ta\'lemu adedes sinine vel hisab, ve kulle şey\'in fassalnahu tafsila.', 'Biz geceyi ve gündüzü iki ayet[1] yaptık. Sonra geceyi karanlık,  gündüzü aydınlık yaptık ki Rabb\'inizin bahşettiği nimetleri çalışıp kazanasınız ve yılların sayısını ve hesabını yapma imkanı bulasınız. Biz,  her şeyi ayrıntılı olarak açıkladık.', 'وجعلنا اليل والنهار ايتين فمحونا اية اليل وجعلنا اية النهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شي فصلنه تفصيلا'),
(2042, 17, 13, 'وَكُلَّ اِنْسَانٍ اَلْزَمْنَاهُ طَٓائِرَهُ ف۪ي عُنُقِه۪ۜ وَنُخْرِجُ لَهُ يَوْمَ الْقِيٰمَةِ كِتَاباً يَلْقٰيهُ مَنْشُوراً', 'Ve kulle insanin elzemnahu tairehu fi unukıh, ve nuhricu lehu yevmel kıyameti kitaben yelkahu menşura.', 'Her insanın kuşunu[1] kendi boynuna doladık.[1] Kıyamet günü,  yaptıklarının tamamını gösteren kitabı önüne koyarız.', 'وكل انسن الزمنه طيره في عنقه ونخرج له يوم القيمة كتبا يلقيه منشورا'),
(2043, 17, 14, 'اِقْرَأْ كِتَابَكَۜ كَفٰى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَس۪يباًۜ', 'Ikra\' kitabek, kefa bi nefsikel yevme aleyke hasiba.', 'Kitabını[1] oku. Bugün hesap görücü olarak sen kendine yetersin.', 'اقرا كتبك كفي بنفسك اليوم عليك حسيبا'),
(2044, 17, 15, 'مَنِ اهْتَدٰى فَاِنَّمَا يَهْتَد۪ي لِنَفْسِه۪ۚ وَمَنْ ضَلَّ فَاِنَّمَا يَضِلُّ عَلَيْهَاۜ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ اُخْرٰىۜ وَمَا كُنَّا مُعَذِّب۪ينَ حَتّٰى نَبْعَثَ رَسُولاً', 'Menihteda fe innema yehtedi li nefsih, ve men dalle fe innema yadıllu aleyha, ve la teziru vaziretun vizre uhra, ve ma kunna muazzibine hatta neb\'ase resula.', 'Kim doğru yolda olursa,  ancak kendi iyiliği için doğru yolda olur. Kim de saparsa ancak kendi kötülüğü için sapmış olur. Ve hiçbir yük taşıyıcı,  başkasının yükünü yüklenmez.[1] Ve Biz,  bir resul göndermedikçe azap edecek değiliz.', 'من اهتدي فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازرة وزر اخري وما كنا معذبين حتي نبعث رسولا'),
(2045, 17, 16, 'وَاِذَٓا اَرَدْنَٓا اَنْ نُهْلِكَ قَرْيَةً اَمَرْنَا مُتْرَف۪يهَا فَفَسَقُوا ف۪يهَا فَحَقَّ عَلَيْهَا الْقَوْلُ فَدَمَّرْنَاهَا تَدْم۪يراً', 'Ve iza eredna en nuhlike karyeten emerna mutrafiha fe feseku fiha fe hakka aleyhel kavlu fe demmernaha tedmira.', 'Biz bir beldeyi yok etmek istersek,  varlık ve güç sahibi ileri gelenlerine uyarımızı yaparız,  buna rağmen bozgunculuk yaparlarsa böylece söz[1] hak olur. Ve onu helak ederek yok ederiz.', 'واذا اردنا ان نهلك قرية امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرنها تدميرا'),
(2046, 17, 17, 'وَكَمْ اَهْلَكْنَا مِنَ الْقُرُونِ مِنْ بَعْدِ نُوحٍۜ وَكَفٰى بِرَبِّكَ بِذُنُوبِ عِبَادِه۪ خَب۪يراً بَص۪يراً', 'Ve kem ehlekna minel kuruni min ba\'di nuh ve kefa bi rabbike bi zunubi ıbadihi habiren basira.', 'Nuh\'tan sonra böyle nice nesilleri yok ettik. Kullarının suçlarını görmede ve haberdar olmada tek başına Rabb\'in yeter.', 'وكم اهلكنا من القرون من بعد نوح وكفي بربك بذنوب عباده خبيرا بصيرا'),
(2047, 17, 18, 'مَنْ كَانَ يُر۪يدُ الْعَاجِلَةَ عَجَّلْنَا لَهُ ف۪يهَا مَا نَشَٓاءُ لِمَنْ نُر۪يدُ ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَۚ يَصْلٰيهَا مَذْمُوماً مَدْحُوراً', 'Men kane yuridul acilete accelna lehu fiha ma neşau li men nuridu summe cealna lehu cehennem, yaslaha mezmumen medhura.', 'Kim aceleyi[1] isterse,  hak eden[2] kimseye dilediğimiz şeyi çabuklaştırırız. Sonra onun için Cehennem\'i mekan yaparız. Kınanmış ve kovulmuş olarak oraya girer.', 'من كان يريد العاجلة عجلنا له فيها ما نشا لمن نريد ثم جعلنا له جهنم يصليها مذموما مدحورا'),
(2048, 17, 19, 'وَمَنْ اَرَادَ الْاٰخِرَةَ وَسَعٰى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَاُو۬لٰٓئِكَ كَانَ سَعْيُهُمْ مَشْكُوراً', 'Ve men eradel ahırete ve saa leha sa\'yeha ve huve mu\'minun fe ulaike kane sa\'yuhum meşkura.', 'Kim de ahireti isterse ve mümin olarak onun gerektirdiği şekilde çalışırsa,  işte onların çalışmaları meşkurdur.[1]', 'ومن اراد الاخرة وسعي لها سعيها وهو مومن فاوليك كان سعيهم مشكورا'),
(2049, 17, 20, 'كُلاًّ نُمِدُّ هٰٓؤُ۬لَٓاءِ وَهٰٓؤُ۬لَٓاءِ مِنْ عَطَٓاءِ رَبِّكَۜ وَمَا كَانَ عَطَٓاءُ رَبِّكَ مَحْظُوراً', 'Kullen numiddu haulai ve haulai min atai rabbik, ve ma kane atau rabbike mahzura.', 'Biz,  bu dünyayı isteyene de ahireti isteyene de veririz. Bu,  Rabb\'inin atalarındandır.[1] Rabb\'inin ataları kısıtlanmış değildir.', 'كلا نمد هولا وهولا من عطا ربك وما كان عطا ربك محظورا'),
(2050, 17, 21, 'اُنْظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلٰى بَعْضٍۜ وَلَلْاٰخِرَةُ اَكْبَرُ دَرَجَاتٍ وَاَكْبَرُ تَفْض۪يلاً', 'Unzur keyfe faddalna ba\'dahum ala ba\'d, ve lel ahıretu ekberu derecatin ve ekberu tafdila.', 'Bak! Onların bir kısmını bir kısmından daha fazla imkan sahibi kıldık. Elbette ahiret,  dereceler ve imkan bakımından da daha büyüktür.', 'انظر كيف فضلنا بعضهم علي بعض وللاخرة اكبر درجت واكبر تفضيلا'),
(2051, 17, 22, 'لَا تَجْعَلْ مَعَ اللّٰهِ اِلٰهاً اٰخَرَ فَتَقْعُدَ مَذْمُوماً مَخْذُولاً۟', 'La tec\'al meallahi ilahen ahare fe tak\'ude mezmumen mahzula.', 'Allah ile birlikte başka bir ilah edinme. Yoksa kınanmış ve hor görülmüş olarak kalırsın.', 'لا تجعل مع الله الها اخر فتقعد مذموما مخذولا'),
(2052, 17, 23, 'وَقَضٰى رَبُّكَ اَلَّا تَعْبُدُٓوا اِلَّٓا اِيَّاهُ وَبِالْوَالِدَيْنِ اِحْسَاناًۜ اِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ اَحَدُهُمَٓا اَوْ كِلَاهُمَا فَلَا تَقُلْ لَهُمَٓا اُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلاً كَر۪يماً', 'Ve kada rabbuke ella ta\'budu illa iyyahu ve bil valideyni ihsana, imma yebluganne indekel kibere ehaduhuma ev kila huma fe la tekul lehuma uffin ve la tenher huma ve kul lehuma kavlen kerima.', 'Rabb\'in,  Kendisinden başkasına kul[1] olmamanızı,  anne ve babaya iyi davranmanızı kaza[2] etti. Eğer ikisinden birisi veya her ikisi senin yanında yaşlanırlarsa sakın onlara \"öf\" deme,  onlara kaba davranma. Ve ikisine de kerim[3] şekilde konuş.', 'وقضي ربك الا تعبدوا الا اياه وبالولدين احسنا اما يبلغن عندك الكبر احدهما او كلاهما فلا تقل لهما اف ولا تنهرهما وقل لهما قولا كريما'),
(2053, 17, 24, 'وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَان۪ي صَغ۪يراًۜ', 'Vahfıd lehuma cenahaz zulli miner rahmeti ve kul rabbirhamhuma kema rabbeyani sagira.', 'Ve merhametle,  alçakgönüllüce onlara kol kanat ger. Ve de ki: \"Rabb\'im,  onların beni büyütürken gösterdikleri merhamet gibi,  onlara merhamet et.\"', 'واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربياني صغيرا'),
(2054, 17, 25, 'رَبُّكُمْ اَعْلَمُ بِمَا ف۪ي نُفُوسِكُمْۜ اِنْ تَكُونُوا صَالِح۪ينَ فَاِنَّهُ كَانَ لِلْاَوَّاب۪ينَ غَفُوراً', 'Rabbukum a\'lemu bi ma fi nufusikum, in tekunu salihine fe innehu kane lil evvabine gafura.', 'Rabb\'iniz niyetinizi çok iyi bilir[1]. Eğer salihler[2] olursanız,  o zaman kuşkusuz O,  Kendisine yönelenleri bağışlayıcıdır.', 'ربكم اعلم بما في نفوسكم ان تكونوا صلحين فانه كان للاوابين غفورا'),
(2055, 17, 26, 'وَاٰتِ ذَا الْقُرْبٰى حَقَّهُ وَالْمِسْك۪ينَ وَابْنَ السَّب۪يلِ وَلَا تُبَذِّرْ تَبْذ۪يراً', 'Ve ati zel kurba hakkahu vel miskine vebnes sebili ve la tubezzir tebzira.', 'Yakınlık sahibine[1],  düşkünlere ve yol oğluna[2] yardım yap! Savurganlık yaparak saçıp savurma.', 'وات ذا القربي حقه والمسكين وابن السبيل ولا تبذر تبذيرا'),
(2056, 17, 27, 'اِنَّ الْمُبَذِّر۪ينَ كَانُٓوا اِخْوَانَ الشَّيَاط۪ينِۜ وَكَانَ الشَّيْطَانُ لِرَبِّه۪ كَفُوراً', 'İnnel mubezzirine kanu ihvaneş şeyatin, ve kaneş şeytanu li rabbihi kefura.', 'Saçıp savuranlar,  şeytanların kardeşleridir. Şeytan ise Rabb\'ine karşı çok nankördür.', 'ان المبذرين كانوا اخون الشيطين وكان الشيطن لربه كفورا'),
(2057, 17, 28, 'وَاِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَٓاءَ رَحْمَةٍ مِنْ رَبِّكَ تَرْجُوهَا فَقُلْ لَهُمْ قَوْلاً مَيْسُوراً', 'Ve imma tu\'ridanne anhumubtigae rahmetin min rabbike tercuha fe kul lehum kavlen meysura.', 'Rabb\'inden,  ümit ettiğin rahmeti isterken,  onlardan yüz çevirirsen[1] bari yumuşak davranarak gönüllerini al.', 'واما تعرضن عنهم ابتغا رحمة من ربك ترجوها فقل لهم قولا ميسورا'),
(2058, 17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً اِلٰى عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُوماً مَحْسُوراً', 'Ve la tec\'al yedeke magluleten ila unukıke ve la tebsutha kullel bastı fe tak\'ude melumen mahsura.', 'Elini bağlayıp boynuna asma. Onu büsbütün de açma.[1] Aksi halde kınanırsın ve yaptığına pişman olur kalırsın.[2]', 'ولا تجعل يدك مغلولة الي عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا'),
(2059, 17, 30, 'اِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُۜ اِنَّهُ كَانَ بِعِبَادِه۪ خَب۪يراً بَص۪يراً۟', 'İnne rabbeke yebsutur rızka li men yeşau ve yakdir, innehu kane bi ibadihi habiran basira.', 'Rabb\'in,  dilediği kimsenin rızkını genişletir ve bir ölçüye göre verir. O,  kullarından Haberdar Olan\'dır,  Her Şeyi Gören\'dir.', 'ان ربك يبسط الرزق لمن يشا ويقدر انه كان بعباده خبيرا بصيرا'),
(2060, 17, 31, 'وَلَا تَقْتُلُٓوا اَوْلَادَكُمْ خَشْيَةَ اِمْلَاقٍۜ نَحْنُ نَرْزُقُهُمْ وَاِيَّاكُمْۜ اِنَّ قَتْلَهُمْ كَانَ خِطْـٔاً كَب۪يراً', 'Ve la taktulu evladekum haşyete imlak, nahnu nerzukuhum ve iyyakum, inne katlehum kane hıt\'en kebira.', 'Yoksulluk endişesi ile çocuklarınızı öldürmeyin. Onları ve sizi sadece Biz rızıklandırırız. Onların öldürülmesi büyük bir yanlıştır.', 'ولا تقتلوا اولدكم خشية املق نحن نرزقهم واياكم ان قتلهم كان خطيا كبيرا'),
(2061, 17, 32, 'وَلَا تَقْرَبُوا الزِّنٰٓى اِنَّهُ كَانَ فَاحِشَةًۜ وَسَٓاءَ سَب۪يلاً', 'Ve la takrebuz zina innehu kane fahışeh, ve sae sebila.', 'Zinaya yaklaşmayın[1]. Kuşkusuz o bir fuhuştur[2] ve kötü bir yoldur.', 'ولا تقربوا الزني انه كان فحشة وسا سبيلا'),
(2062, 17, 33, 'وَلَا تَقْتُلُوا النَّفْسَ الَّت۪ي حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّۜ وَمَنْ قُتِلَ مَظْلُوماً فَقَدْ جَعَلْنَا لِوَلِيِّه۪ سُلْطَاناً فَلَا يُسْرِفْ فِي الْقَتْلِۜ اِنَّهُ كَانَ مَنْصُوراً', 'Ve la taktulun nefselleti harremallahu illa bil hakk, ve men kutile mazlumen fe kad cealna li veliyyihi sultanen fe la yusrif fil katl, innehu kane mensura.', 'Allah\'ın haram[1] kıldığı bir canı haksız yere öldürmeyin. Kim haksız yere öldürülürse,  Biz onun velisini sultan[2] kıldık. O da öldürmede haddi aşmasın. O yardım olunmuştur.[3]', 'ولا تقتلوا النفس التي حرم الله الا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطنا فلا يسرف في القتل انه كان منصورا'),
(2063, 17, 34, 'وَلَا تَقْرَبُوا مَالَ الْيَت۪يمِ اِلَّا بِالَّت۪ي هِيَ اَحْسَنُ حَتّٰى يَبْلُغَ اَشُدَّهُۖ وَاَوْفُوا بِالْعَهْدِۚ اِنَّ الْعَهْدَ كَانَ مَسْؤُ۫لاً', 'Ve la takrebu malel yetimi illa billeti hiye ahsenu hatta yebluga eşuddeh, ve evfu bil ahd, innel ahde kane mes\'ula.', 'Olgunluk çağına erişinceye kadar,  iyiliği için olmadıkça yetimin malına dokunmayın. Ve verdiğiniz sözleri[1] yerine getirin. Verilen söz insanı sorumlu yapar.', 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا بالعهد ان العهد كان مسولا'),
(2064, 17, 35, 'وَاَوْفُوا الْكَيْلَ اِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَق۪يمِۜ ذٰلِكَ خَيْرٌ وَاَحْسَنُ تَأْو۪يلاً', 'Ve evful keyle iza kiltum vezinu bil kıstasil mustekim, zalike hayrun ve ahsenu te\'vila.', 'Ölçtüğünüz zaman tam ölçün ve doğru terazi ile tartın. Hayırlı ve iyi olan budur.', 'واوفوا الكيل اذا كلتم وزنوا بالقسطاس المستقيم ذلك خير واحسن تاويلا'),
(2065, 17, 36, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِه۪ عِلْمٌۜ اِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤٰادَ كُلُّ اُو۬لٰٓئِكَ كَانَ عَنْهُ مَسْؤُ۫لاً', 'Ve la takfu ma leyse leke bihi ilm, innes sem\'a vel basara vel fuade kullu ulaike kane anhu mes\'ula.', 'Hakkında bilgi sahibi olmadığın şeyin peşine düşme! Kuşkusuz kulak,  göz ve fuad[1] bunların hepsi ondan sorumludur.', 'ولا تقف ما ليس لك به علم ان السمع والبصر والفواد كل اوليك كان عنه مسولا'),
(2066, 17, 37, 'وَلَا تَمْشِ فِي الْاَرْضِ مَرَحاًۚ اِنَّكَ لَنْ تَخْرِقَ الْاَرْضَ وَلَنْ تَبْلُغَ الْجِبَالَ طُولاً', 'Ve la temşi fil ardı mereha, inneke len tahrikal arda ve len teblugal cibale tula.', 'Yeryüzünde büyüklenerek yürüme! Sen asla yeri yaramazsın ve boyca dağlara erişemezsin.', 'ولا تمش في الارض مرحا انك لن تخرق الارض ولن تبلغ الجبال طولا'),
(2067, 17, 38, 'كُلُّ ذٰلِكَ كَانَ سَيِّئُهُ عِنْدَ رَبِّكَ مَكْرُوهاً', 'Kullu zalike kane seyyiuhu inde rabbike mekruha.', 'Bütün bunlar,  Rabb\'inin yanında hoş görülmeyen kötü şeylerdir.', 'كل ذلك كان سييه عند ربك مكروها'),
(2068, 17, 39, 'ذٰلِكَ مِمَّٓا اَوْحٰٓى اِلَيْكَ رَبُّكَ مِنَ الْحِكْمَةِۜ وَلَا تَجْعَلْ مَعَ اللّٰهِ اِلٰهاً اٰخَرَ فَتُلْقٰى ف۪ي جَهَنَّمَ مَلُوماً مَدْحُوراً', 'Zalike mimma evha ileyke rabbuke minel hikmeh, ve la tec\'al meallahi ilahen ahare fe tulka fi cehenneme melumen medhura.', 'İşte bunlar,  senin Rabb\'inin,  sana hikmetten[1] vahyettiği şeylerdendir. Allah ile birlikte başka ilah edinme. Yoksa kınanmış ve kovulmuş olarak Cehennem\'e atılırsın.', 'ذلك مما اوحي اليك ربك من الحكمة ولا تجعل مع الله الها اخر فتلقي في جهنم ملوما مدحورا'),
(2069, 17, 40, 'اَفَاَصْفٰيكُمْ رَبُّكُمْ بِالْبَن۪ينَ وَاتَّخَذَ مِنَ الْمَلٰٓئِكَةِ اِنَاثاًۜ اِنَّكُمْ لَتَقُولُونَ قَوْلاً عَظ۪يماً۟', 'E fe asfakum rabbukum bil benine vettehaze minel melaiketi inasa, innekum le tekulune kavlen azima.', 'Rabb\'iniz,  oğulları size ayırdı da kendisi meleklerden kızlar mı edindi? Siz gerçekten çok büyük laf ediyorsunuz.[1]', 'افاصفيكم ربكم بالبنين واتخذ من المليكة انثا انكم لتقولون قولا عظيما'),
(2070, 17, 41, 'وَلَقَدْ صَرَّفْنَا ف۪ي هٰذَا الْقُرْاٰنِ لِيَذَّكَّرُواۜ وَمَا يَز۪يدُهُمْ اِلَّا نُفُوراً', 'Ve lekad sarrafna fi hazel kur\'ani li yezzekkeru, ve ma yeziduhum illa nufura.', 'Ant olsun ki Biz,  bu Kur\'an\'da öğüt alsınlar diye her türlü açıklamayı yaptık. Oysaki bu onların yalnızca nefretlerini arttırdı.', 'ولقد صرفنا في هذا القران ليذكروا وما يزيدهم الا نفورا'),
(2071, 17, 42, 'قُلْ لَوْ كَانَ مَعَهُٓ اٰلِهَةٌ  كَمَا يَقُولُونَ اِذاً لَابْتَغَوْا اِلٰى ذِي الْعَرْشِ سَب۪يلاً', 'Kul lev kane meahu alihetun kema yekulune izen lebtegav ila zil arşı sebila.', 'De ki: \"Eğer dedikleri gibi,  O\'nunla beraber başka ilahlar olsaydı,  o zaman onlar da mutlaka arşın sahibine bir yol[1] ararlardı.\"', 'قل لو كان معه الهة كما يقولون اذا لابتغوا الي ذي العرش سبيلا'),
(2072, 17, 43, 'سُبْحَانَهُ وَتَعَالٰى عَمَّا يَقُولُونَ عُلُواًّ كَب۪يراً', 'Subhanehu ve teala amma yekulune uluvven kebira.', 'Allah,  onların iddialarından Münezzeh\'tir[1] ve Yüceler Yücesidir.', 'سبحنه وتعلي عما يقولون علوا كبيرا'),
(2073, 17, 44, 'تُسَبِّحُ لَهُ السَّمٰوَاتُ السَّبْعُ وَالْاَرْضُ وَمَنْ ف۪يهِنَّۜ وَاِنْ مِنْ شَيْءٍ اِلَّا يُسَبِّحُ بِحَمْدِه۪ وَلٰكِنْ لَا تَفْقَهُونَ تَسْب۪يحَهُمْۜ اِنَّهُ كَانَ حَل۪يماً غَفُوراً', 'Tusebbihu lehus semavatus seb\'u vel ardu ve men fihinn, ve in min şey\'in illa yusebbihu bi hamdihi ve lakin la tefkahune tesbihahum, innehu kane halimen gafura.', 'Yedi gök,  yeryüzü ve içindekiler,  O\'nu tesbih[1] ederler. Onu hamd[2] ile tesbih etmeyen hiçbir şey yoktur. Fakat siz,  onların tesbihlerini kavrayamazsınız. Kuşkusuz O,  Çok Hoşgörülü\'dür,  Çok Bağışlayıcı\'dır.', 'تسبح له السموت السبع والارض ومن فيهن وان من شي الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا'),
(2074, 17, 45, 'وَاِذَا قَرَأْتَ الْقُرْاٰنَ جَعَلْنَا بَيْنَكَ وَبَيْنَ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ حِجَاباً مَسْتُوراًۙ', 'Ve iza kara\'tel kur\'ane cealna beyneke ve beynellezine la yu\'minune bil ahıreti hicaben mestura.', 'Kur\'an okuduğun[1] zaman,  seninle ahirete inanmayanlar arasına görünmez bir perde çekeriz.', 'واذا قرات القران جعلنا بينك وبين الذين لا يومنون بالاخرة حجابا مستورا'),
(2075, 17, 46, 'وَجَعَلْنَا عَلٰى قُلُوبِهِمْ اَكِنَّةً اَنْ يَفْقَهُوهُ وَف۪ٓي اٰذَانِهِمْ وَقْراًۜ وَاِذَا ذَكَرْتَ رَبَّكَ فِي الْقُرْاٰنِ وَحْدَهُ وَلَّوْا عَلٰٓى اَدْبَارِهِمْ نُفُوراً', 'Ve cealna ala kulubihim ekinneten en yefkahuhu ve fi azanihim vakra, ve iza zekerte rabbeke fil kur\'ani vahdehu vellev ala edbarihim nufura.', 'Kur\'an\'ı anlamalarına engel olsun diye,  kalplerine[1] perde,  kulaklarına bir ağırlık koyduk. Sen,  Kur\'an\'da Rabb\'inin tekliğini andığın zaman,  nefretle arkalarını dönüp kaçarlar.', 'وجعلنا علي قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا واذا ذكرت ربك في القران وحده ولوا علي ادبرهم نفورا'),
(2076, 17, 47, 'نَحْنُ اَعْلَمُ بِمَا يَسْتَمِعُونَ بِه۪ٓ اِذْ يَسْتَمِعُونَ اِلَيْكَ وَاِذْ هُمْ نَجْوٰٓى اِذْ يَقُولُ الظَّالِمُونَ اِنْ تَتَّبِعُونَ اِلَّا رَجُلاً مَسْحُوراً', 'Nahnu a\'lemu bima yestemiune bihi iz yestemiune ileyke ve iz hum necva iz yekuluz zalimune in tettebiune illa raculen meshura.', 'Biz onların seni ne amaçla dinlediklerini ve kendi aralarında fısıldaştıklarında da,  o zalimlerin: \"Siz büyülenmiş bir adamdan başkasına uymuyorsunuz.\" dediklerini çok iyi biliyoruz.', 'نحن اعلم بما يستمعون به اذ يستمعون اليك واذ هم نجوي اذ يقول الظلمون ان تتبعون الا رجلا مسحورا'),
(2077, 17, 48, 'اُنْظُرْ كَيْفَ ضَرَبُوا لَكَ الْاَمْثَالَ فَضَلُّوا فَلَا يَسْتَط۪يعُونَ سَب۪يلاً', 'Unzur keyfe darabu lekel emsale fe dallu fe la yestetiune sebila.', 'Seni neye benzettiklerine[1] bir bak! Bu yüzden sapkınlaştılar. Artık,  bir daha doğru yolu bulamazlar.', 'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا'),
(2078, 17, 49, 'وَقَالُٓوا ءَاِذَا كُنَّا عِظَاماً وَرُفَاتاً ءَاِنَّا لَمَبْعُوثُونَ خَلْقاً جَد۪يداً', 'Ve kalu e iza kunna izamen ve rufaten e inna le meb\'usune halkan cedida.', '\"Biz kemik yığını ve toz toprak olduktan sonra,  gerçekten de yeni bir yaratılışla mı diriltileceğiz?\" dediler.', 'وقالوا اذا كنا عظما ورفتا انا لمبعوثون خلقا جديدا'),
(2079, 17, 50, 'قُلْ كُونُوا حِجَارَةً اَوْ حَد۪يداًۙ', 'Kul kunu hicareten ev hadida.', 'De ki: \"İster taş ister demir olun;\"', 'قل كونوا حجارة او حديدا'),
(2080, 17, 51, 'اَوْ خَلْقاً مِمَّا يَكْبُرُ ف۪ي صُدُورِكُمْۚ فَسَيَقُولُونَ مَنْ يُع۪يدُنَاۜ قُلِ الَّذ۪ي فَطَرَكُمْ اَوَّلَ مَرَّةٍۚ فَسَيُنْغِضُونَ اِلَيْكَ رُؤُ۫سَهُمْ وَيَقُولُونَ مَتٰى هُوَۜ قُلْ عَسٰٓى اَنْ يَكُونَ قَر۪يباً', 'Ev halkan mimma yekburu fi sudurikum, fe se yekulune men yuidun, kulillezi fetarakum evvele merreh, fe se yungıdune ileyke ruusehum ve yekulune meta huv, kul asa en yekune kariba.', '\"Veya göğüslerinizde büyüyen[1] herhangi bir varlık.\" Sonra da,  \"Bizi kim geri çevirecek?[2]\" diyecekler. De ki: \"Size ilk defa fıtrat[3] belirlemiş olan.\" Alaylı alaylı başlarını sallayarak: \"Ne zamandır o?\" diyecekler. De ki: \"Belki de pek yakın bir zamanda.\"', 'او خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم اول مرة فسينغضون اليك روسهم ويقولون متي هو قل عسي ان يكون قريبا'),
(2081, 17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَج۪يبُونَ بِحَمْدِه۪ وَتَظُنُّونَ اِنْ لَبِثْتُمْ اِلَّا قَل۪يلاً۟', 'Yevme yed\'ukum fe testecibune bi hamdihi ve tezunnune in lebistum illa kalila.', '\"Sizi çağıracağı[1] gün,  O\'nu överek çağrıya uyacaksınız ve dünyada çok kısa bir süre kaldığınızı sanacaksınız.\"', 'يوم يدعوكم فتستجيبون بحمده وتظنون ان لبثتم الا قليلا'),
(2082, 17, 53, 'وَقُلْ لِعِبَاد۪ي يَقُولُوا الَّت۪ي هِيَ اَحْسَنُۜ اِنَّ الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْۜ اِنَّ الشَّيْطَانَ كَانَ لِلْاِنْسَانِ عَدُواًّ مُب۪يناً', 'Ve kul li ibadi yekululleti hiye ahsen, inneş şeytane yenzegu beynehum, inneş şeytane kane lil insani aduvven mubina.', 'Kullarıma de ki: \"Sözün en iyi olanını söylesinler!\" Şeytan,  onların aralarını bozar. Şeytan,  insan için apaçık bir düşmandır.', 'وقل لعبادي يقولوا التي هي احسن ان الشيطن ينزغ بينهم ان الشيطن كان للانسن عدوا مبينا'),
(2083, 17, 54, 'رَبُّكُمْ اَعْلَمُ بِكُمْۜ اِنْ يَشَأْ يَرْحَمْكُمْ اَوْ اِنْ يَشَأْ يُعَذِّبْكُمْۜ وَمَٓا اَرْسَلْنَاكَ عَلَيْهِمْ وَك۪يلاً', 'Rabbukum a\'lemu bikum, in yeşa\' yerhamkum ev in yeşa\' yuazzibkum, ve ma erselnake aleyhim vekila.', 'Rabb\'iniz sizi daha iyi bilir. Hak edene merhamet eder veya hak edene azap eder[1]. Seni onlara vekil[2] olarak göndermedik.', 'ربكم اعلم بكم ان يشا يرحمكم او ان يشا يعذبكم وما ارسلنك عليهم وكيلا'),
(2084, 17, 55, 'وَرَبُّكَ اَعْلَمُ بِمَنْ فِي السَّمٰوَاتِ وَالْاَرْضِۜ وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيّ۪نَ عَلٰى بَعْضٍ وَاٰتَيْنَا دَاوُ۫دَ زَبُوراً', 'Ve rabbuke a\'lemu bi men fis semavati vel ard, ve lekad faddalna ba\'dan nebiyyine ala ba\'dın ve ateyna davude zebura.', 'Göklerde ve yeryüzünde kimlerin olduğunu Rabb\'in daha iyi bilir. Ant olsun ki Biz nebilerin kimini kiminden,  kimi nitelikleriyle üstün kıldık. Davud\'a Zebur\'u verdik.', 'وربك اعلم بمن في السموت والارض ولقد فضلنا بعض النبين علي بعض واتينا داود زبورا'),
(2085, 17, 56, 'قُلِ ادْعُوا الَّذ۪ينَ زَعَمْتُمْ مِنْ دُونِه۪ فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنْكُمْ وَلَا تَحْو۪يلاً', 'Kulid\'ullezine zeamtum min dunihi fe la yemlikune keşfed durri ankum ve la tahvila.', 'De ki: \"O\'nun yanı sıra,  zanda bulunduklarınızı[1] çağırın.\" Oysa onlar,  sizden bir sıkıntıyı yok etme veya onu değiştirmeye güç yetiremezler.', 'قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا'),
(2086, 17, 57, 'اُو۬لٰٓئِكَ الَّذ۪ينَ يَدْعُونَ يَبْتَغُونَ اِلٰى رَبِّهِمُ الْوَس۪يلَةَ اَيُّهُمْ اَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُۜ اِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُوراً', 'Ulaikellezine yed\'une yebtegune ila rabbihimul vesilete eyyuhum akrebu ve yercune rahmetehu ve yehafune azabeh, inne azabe rabbike kane mahzura.', 'İşte onların,  o yöneldikleri de[1] Rabb\'lerine daha yakın olmak için vesile arayan,  O\'nun rahmetini uman ve O\'nun azabından korkan kimselerdir. Gerçekten Rabb\'inin azabı korkunçtur.', 'اوليك الذين يدعون يبتغون الي ربهم الوسيلة ايهم اقرب ويرجون رحمته ويخافون عذابه ان عذاب ربك كان محذورا'),
(2087, 17, 58, 'وَاِنْ مِنْ قَرْيَةٍ اِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ الْقِيٰمَةِ اَوْ مُعَذِّبُوهَا عَذَاباً شَد۪يداًۜ كَانَ ذٰلِكَ فِي الْكِتَابِ مَسْطُوراً', 'Ve in min karyetin illa nahnu muhlikuha kable yevmil kıyameti ev muazzibuha azaben şedida, kane zalike fil kitabi mestura.', 'Hiçbir belde[1] yoktur ki,  Kıyamet Günü\'nden önce biz onu yok etmeyelim veya şiddetli bir azap ile azaplandırmayalım. Bu Kitap\'ta[2] kayıtlıdır.', 'وان من قرية الا نحن مهلكوها قبل يوم القيمة او معذبوها عذابا شديدا كان ذلك في الكتب مسطورا'),
(2088, 17, 59, 'وَمَا مَنَعَنَٓا اَنْ نُرْسِلَ بِالْاٰيَاتِ اِلَّٓا اَنْ كَذَّبَ بِهَا الْاَوَّلُونَۜ وَاٰتَيْنَا ثَمُودَ النَّاقَةَ مُبْصِرَةً فَظَلَمُوا بِهَاۜ وَمَا نُرْسِلُ بِالْاٰيَاتِ اِلَّا تَخْو۪يفاً', 'Ve ma meneana en nursile bil ayati illa en kezzebe bihel evvelun, ve ateyna semuden nakate mubsıraten fe zalemu biha, ve ma nursilu bil ayati illa tahvifa.', 'Bizi ayet[1] göndermekten alıkoyan şey,  öncekilerin onu[2] yalanlamış olmalarıdır. Semud halkına göz göre göre o dişi deveyi verdik. Onunla kendilerine zulmettiler.[3] Ve Biz,  ayetleri[4] uyarmaktan başka bir şey için göndermeyiz.', 'وما منعنا ان نرسل بالايت الا ان كذب بها الاولون واتينا ثمود الناقة مبصرة فظلموا بها وما نرسل بالايت الا تخويفا'),
(2089, 17, 60, 'وَاِذْ قُلْنَا لَكَ اِنَّ رَبَّكَ اَحَاطَ بِالنَّاسِۜ وَمَا جَعَلْنَا الرُّءْيَا الَّت۪ٓي اَرَيْنَاكَ اِلَّا فِتْنَةً لِلنَّاسِ وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْاٰنِۜ وَنُخَوِّفُهُمْۙ فَمَا يَز۪يدُهُمْ اِلَّا طُغْيَاناً كَب۪يراً۟', 'Ve iz kulna leke inne rabbeke ehata bin nas, ve ma cealner ru\'yalleti ereynake illa fitneten lin nasi veş şeceretel mel\'unete fil kur\'an, ve nuhavvifuhum fe ma yeziduhum illa tugyanen kebira.', 'Hani bir zaman sana: \"Rabb\'in insanları kuşatmıştır.\" demiştik. Sana gösterdiğimiz o rüyeti[1] ve Kur\'an\'da lanet edilen ağacı[2],  sadece insanlar için fitne[3] kıldık. Biz onları uyarıyoruz. Fakat bu onların aşırı azgınlıklarını daha da artırmaktan başka bir şeye yaramıyor.', 'واذ قلنا لك ان ربك احاط بالناس وما جعلنا الريا التي ارينك الا فتنة للناس والشجرة الملعونة في القران ونخوفهم فما يزيدهم الا طغينا كبيرا'),
(2090, 17, 61, 'وَاِذْ قُلْنَا لِلْمَلٰٓئِكَةِ اسْجُدُوا لِاٰدَمَ فَسَجَدُٓوا اِلَّٓا اِبْل۪يسَۜ قَالَ ءَاَسْجُدُ لِمَنْ خَلَقْتَ ط۪يناًۚ', 'Ve iz kulna lil melaiketiscudu li ademe fe secedu illa iblis, kale e escudu li men halakte tina.', 'Hani Biz meleklere,  \"Âdem\'e secde edin.[1]\" dediğimiz zaman,  iblis hariç hepsi secde etti. İblis,  \"Ben,  çamurdan yarattığın kimseye mi secde edeceğim?\" dedi.', 'واذ قلنا للمليكة اسجدوا لادم فسجدوا الا ابليس قال اسجد لمن خلقت طينا'),
(2091, 17, 62, 'قَالَ اَرَاَيْتَكَ هٰذَا الَّذ۪ي كَرَّمْتَ عَلَيَّۘ  لَئِنْ اَخَّرْتَنِ اِلٰى يَوْمِ الْقِيٰمَةِ لَاَحْتَنِكَنَّ ذُرِّيَّتَهُٓ اِلَّا قَل۪يلاً', 'Kale e raeyteke hazellezi kerremte aley, le in ahharteni ila yevmil kıyameti le ahtenikenne zurriyyetehu illa kalila.', 'Dedi ki: \"Bu mu benden mükerrem[1] kıldığın varlık? Eğer bana Kıyamet Günü\'ne kadar müsaade edersen,  pek azı hariç,  onun soyunu kesinlikle buyruğum altına alacağım.\"', 'قال اريتك هذا الذي كرمت علي لين اخرتن الي يوم القيمة لاحتنكن ذريته الا قليلا'),
(2092, 17, 63, 'قَالَ اذْهَبْ فَمَنْ تَبِعَكَ مِنْهُمْ فَاِنَّ جَهَنَّمَ جَزَٓاؤُ۬كُمْ جَزَٓاءً مَوْفُوراً', 'Kalezheb fe men tebiake minhum fe inne cehenneme cezaukum cezaen mevfura.', 'Allah,  \"Git! Onlardan kim sana uyarsa,  bilin ki bunun karşılığı tam bir karşılık olarak Cehennem\'dir.\" dedi.', 'قال اذهب فمن تبعك منهم فان جهنم جزاوكم جزا موفورا'),
(2093, 17, 64, 'وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُمْ بِصَوْتِكَ وَاَجْلِبْ عَلَيْهِمْ بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِي الْاَمْوَالِ وَالْاَوْلَادِ وَعِدْهُمْۜ وَمَا يَعِدُهُمُ الشَّيْطَانُ اِلَّا غُرُوراً', 'Vestefziz menisteta\'te minhum bi savtike ve eclib aleyhim bi haylike ve recilike ve şarikhum fil emvali vel evladi vaıdhum, ve ma yaiduhumuş şeytanu illa gurura.', '\"Onlardan,  gücünün yettiğini sesinle[1] ayart. Atlıların ve yayalarınla[2] onları yaygara ile yönlendir. Mallarında ve çocuklarında onlara ortak ol[3]. Ve onlara vaatlerde bulun. Şeytanın vadettikleri gururdan[4] başka bir şey değildir.\"', 'واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الامول والاولد وعدهم وما يعدهم الشيطن الا غرورا'),
(2094, 17, 65, 'اِنَّ عِبَاد۪ي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌۜ وَكَفٰى بِرَبِّكَ وَك۪يلاً', 'İnne ibadi leyse leke aleyhim sultan, ve kefa bi rabbike vekila.', '\"Bana yönelmiş kullarım üzerinde,  senin bir sultanın[1] yoktur. Vekil[2] olarak Rabb\'in yeter.\"', 'ان عبادي ليس لك عليهم سلطن وكفي بربك وكيلا'),
(2095, 17, 66, 'رَبُّكُمُ الَّذ۪ي يُزْج۪ي لَكُمُ الْفُلْكَ فِي الْبَحْرِ لِتَبْتَغُوا مِنْ فَضْلِه۪ۜ اِنَّهُ كَانَ بِكُمْ رَح۪يماً', 'Rabbukumullezi yuzci lekumul fulke fil bahri li tebtegu min fadlih, innehu kane bi kum rahima.', 'Rabb\'iniz,  lütfundan arayasınız[1] diye sizin için denizde gemileri yürütendir. O\'nun size olan rahmeti kesintisizdir.', 'ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله انه كان بكم رحيما'),
(2096, 17, 67, 'وَاِذَا مَسَّكُمُ الضُّرُّ فِي الْبَحْرِ ضَلَّ مَنْ تَدْعُونَ اِلَّٓا اِيَّاهُۚ فَلَمَّا نَجّٰيكُمْ اِلَى الْبَرِّ اَعْرَضْتُمْۜ وَكَانَ الْاِنْسَانُ كَفُوراً', 'Ve iza messekumud durru fil bahri dalle men ted\'une illa iyyah, fe lemma neccakum ilel berri a\'radtum, ve kanel insanu kefura.', 'Denizde bir sıkıntı size dokunduğu zaman,  O\'ndan başka yalvardıklarınız kaybolup gider. Fakat sizi karaya çıkarınca,  yüz çevirirsiniz. İnsan çok nankördür.[1]', 'واذا مسكم الضر في البحر ضل من تدعون الا اياه فلما نجيكم الي البر اعرضتم وكان الانسن كفورا'),
(2097, 17, 68, 'اَفَاَمِنْتُمْ اَنْ يَخْسِفَ بِكُمْ جَانِبَ الْبَرِّ اَوْ يُرْسِلَ عَلَيْكُمْ حَاصِباً ثُمَّ لَا تَجِدُوا لَكُمْ وَك۪يلاًۙ', 'E fe emintum en yahsife bikum canibel berri ev yursile aleykum hasiben summe la tecidu lekum vekila.', 'Peki,  sizi karada yerin dibine geçirmesinden veya üzerinize bir kasırga göndermesinden güvende misiniz? Sonra kendinize bir vekil[1] de bulamazsınız.', 'افامنتم ان يخسف بكم جانب البر او يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا'),
(2098, 17, 69, 'اَمْ اَمِنْتُمْ اَنْ يُع۪يدَكُمْ ف۪يهِ تَارَةً اُخْرٰى فَيُرْسِلَ عَلَيْكُمْ قَاصِفاً مِنَ الرّ۪يحِ فَيُغْرِقَكُمْ بِمَا كَفَرْتُمْۙ ثُمَّ لَا تَجِدُوا لَكُمْ عَلَيْنَا بِه۪ تَب۪يعاً', 'Em emintum en yuidekum fihi tareten uhra fe yursile aleykum kasıfen miner rihı fe yugrikakum bima kefertum summe la tecidu lekum aleyna bihi tebia.', 'Ya da sizi tekrar oraya[1] döndürüp de böylece üzerinize kasırgalar göndermeyeceğinden ve ettiğiniz nankörlük nedeniyle sizi boğmayacağından emin mi oldunuz? Sonra bu yaptığınızdan dolayı Bize karşı size yardım edecek birini bulamazsınız.', 'ام امنتم ان يعيدكم فيه تارة اخري فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا'),
(2099, 17, 70, 'وَلَقَدْ كَرَّمْنَا بَن۪ٓي اٰدَمَ وَحَمَلْنَاهُمْ فِي الْبَرِّ وَالْبَحْرِ وَرَزَقْنَاهُمْ مِنَ الطَّيِّبَاتِ وَفَضَّلْنَاهُمْ عَلٰى كَث۪يرٍ مِمَّنْ خَلَقْنَا تَفْض۪يلاً۟', 'Ve lekad kerremna beni ademe ve hamelnahum fil berri vel bahri ve razaknahum minet tayyibati ve faddalnahum ala kesirin mimmen halakna tafdila.', 'Ant olsun ki insanoğlunu kerem[1] sahibi kıldık. Onları karada ve denizde taşıdık. Ve onları temiz şeylerle rızıklandırdık. Onları,  yarattıklarımızın birçoğuna üstün kıldık.', 'ولقد كرمنا بني ادم وحملنهم في البر والبحر ورزقنهم من الطيبت وفضلنهم علي كثير ممن خلقنا تفضيلا'),
(2100, 17, 71, 'يَوْمَ نَدْعُوا كُلَّ اُنَاسٍ بِاِمَامِهِمْۚ فَمَنْ اُو۫تِيَ كِتَابَهُ بِيَم۪ينِه۪ فَاُو۬لٰٓئِكَ يَقْرَؤُ۫نَ كِتَابَهُمْ وَلَا يُظْلَمُونَ فَت۪يلاً', 'Yevme ned\'u kulle unasin bi imamihim, fe men utiye kitabehu bi yeminihi fe ulaike yakreune kitabehum ve la yuzlemune fetila.', 'O gün,  bütün insanları imamlarıyla[1] çağırırız. O gün kimin kitabı[2] sağından[3] verilirse,  işte onlar kendi kitaplarını okurlar[4] ve kıl kadar haksızlığa uğratılmazlar.', 'يوم ندعوا كل اناس باممهم فمن اوتي كتبه بيمينه فاوليك يقرون كتبهم ولا يظلمون فتيلا'),
(2101, 17, 72, 'وَمَنْ كَانَ ف۪ي هٰذِه۪ٓ اَعْمٰى فَهُوَ فِي الْاٰخِرَةِ اَعْمٰى وَاَضَلُّ سَب۪يلاً', 'Ve men kane fi hazihi a\'ma fe huve fil ahıreti a\'ma ve edallu sebila.', 'Bu dünyada kör olan,  ahirette de kör olacaktır[1]. Yol bulma bakımından körden daha şaşkın olacaktır.', 'ومن كان في هذه اعمي فهو في الاخرة اعمي واضل سبيلا'),
(2102, 17, 73, 'وَاِنْ كَادُوا لَيَفْتِنُونَكَ عَنِ الَّـذ۪ٓي اَوْحَيْنَٓا اِلَيْكَ لِتَفْتَرِيَ عَلَيْنَا غَيْرَهُۗ وَاِذاً لَاتَّخَذُوكَ خَل۪يلاً', 'Ve in kadu le yeftinuneke anillezi evhayna ileyke li tefteriye aleyna gayreh ve izen lettehazuke halila.', 'Onlar,  fitneyle[1] neredeyse seni,  sana vahyettiğimizden ayırarak,  ondan başkasını Bize karşı uyduran bir iftiracı konumuna düşüreceklerdi.[2] O zaman seni halil[3] edinirlerdi.', 'وان كادوا ليفتنونك عن الذي اوحينا اليك لتفتري علينا غيره واذا لاتخذوك خليلا'),
(2103, 17, 74, 'وَلَوْلَٓا اَنْ ثَبَّتْنَاكَ لَقَدْ كِدْتَ تَرْكَنُ اِلَيْهِمْ شَيْـٔاً قَل۪يلاًۗ', 'Ve lev la en sebbetnake lekad kidte terkenu ileyhim şey\'en kalila.', 'Seni dirençli kılmasaydık,  ant olsun ki sen,  neredeyse az da olsa onlara eğilim gösterecektin.', 'ولولا ان ثبتنك لقد كدت تركن اليهم شيا قليلا'),
(2104, 17, 75, 'اِذاً لَاَذَقْنَاكَ ضِعْفَ الْحَيٰوةِ وَضِعْفَ الْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَص۪يراً', 'İzen le ezaknake di\'fal hayati ve di\'fal memati summe la tecidu leke aleyna nasira.', 'O durumda sana,  hayatın da ölümün de azabını tattırırdık. Sonra Bize karşı bir yardımcı da bulamazdın.', 'اذا لاذقنك ضعف الحيوة وضعف الممات ثم لا تجد لك علينا نصيرا'),
(2105, 17, 76, 'وَاِنْ كَادُوا لَيَسْتَفِزُّونَكَ مِنَ الْاَرْضِ لِيُخْرِجُوكَ مِنْهَا وَاِذاً لَا يَلْبَثُونَ خِلَافَكَ اِلَّا قَل۪يلاً', 'Ve in kadu le yestefizzuneke minel ardı li yuhricuke minha ve izen la yelbesune hilafeke illa kalila.', 'Neredeyse seni bulunduğun yerden çıkman için tedirgin etmeyi başaracaklardı. Eğer öyle olsaydı,  onlar da senin ardından ancak az bir süre kalabilirlerdi.', 'وان كادوا ليستفزونك من الارض ليخرجوك منها واذا لا يلبثون خلفك الا قليلا'),
(2106, 17, 77, 'سُنَّةَ مَنْ قَدْ اَرْسَلْنَا قَبْلَكَ مِنْ رُسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْو۪يلاً۟', 'Sunnete men kad erselna kableke min rusulina ve la tecidu li sunnetina tahvila.', 'Senden önce de gönderdiğimiz resullerimize uyguladığımız sünnetimiz budur. Bizim sünnetimizde[1] bir değişiklik bulamazsın.', 'سنة من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا'),
(2107, 17, 78, 'اَقِمِ الصَّلٰوةَ لِدُلُوكِ الشَّمْسِ اِلٰى غَسَقِ الَّيْلِ وَقُرْاٰنَ الْفَجْرِۜ اِنَّ قُرْاٰنَ الْفَجْرِ كَانَ مَشْهُوداً', 'Ekımis salate li dulukiş şemsi ila gasakıl leyli ve kur\'anel fecr, inne kur\'anel fecri kane meşhuda.', 'Güneş\'in batmasından[1] gecenin karanlığı bastırıncaya kadar salatı ikame et.[2] Ve fecrin kuranı;[3] kuşkusuz fecrin kuranı[4] tanıklıdır.', 'اقم الصلوة لدلوك الشمس الي غسق اليل وقران الفجر ان قران الفجر كان مشهودا'),
(2108, 17, 79, 'وَمِنَ الَّيْلِ فَـتَهَجَّدْ بِه۪ نَافِلَةً لَكَۗ عَسٰٓى اَنْ يَبْعَثَكَ رَبُّكَ مَقَاماً مَحْمُوداً', 'Ve minel leyli fe tehecced bihi nafileten lek, asa en yeb\'aseke rabbuke makamen mahmuda.', 'Sana özgü nafile[1] olarak gecenin bir kısmında onunla[2] fetehecced et[3]. Umulur ki Rabb\'in seni makamı mahmuda[4] ulaştırır.', 'ومن اليل فتهجد به نافلة لك عسي ان يبعثك ربك مقاما محمودا'),
(2109, 17, 80, 'وَقُلْ رَبِّ اَدْخِلْن۪ي مُدْخَلَ صِدْقٍ وَاَخْرِجْن۪ي مُخْرَجَ صِدْقٍ وَاجْعَلْ ل۪ي مِنْ لَدُنْكَ سُلْطَاناً نَص۪يراً', 'Ve kul rabbi edhılni mudhale sıdkın ve ahricni muhrece sıdkın vec\'al li min ledunke sultanen nasira.', 'De ki: \"Rabb\'im! Beni doğru bir girişle girdir ve beni doğru bir çıkış ile çıkar. Ve bana katından bir sultan[1] ver.\"', 'وقل رب ادخلني مدخل صدق واخرجني مخرج صدق واجعل لي من لدنك سلطنا نصيرا'),
(2110, 17, 81, 'وَقُلْ جَٓاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُۜ اِنَّ الْبَاطِلَ كَانَ زَهُوقاً', 'Ve kul cael hakku ve zehekal batıl, innel batıle kane zehuka.', 'De ki: \"Hakk geldi,  Batıl yok oldu.\" Kuşkusuz ki Batıl yok olmaya mahkumdur.', 'وقل جا الحق وزهق البطل ان البطل كان زهوقا'),
(2111, 17, 82, 'وَنُنَزِّلُ مِنَ الْقُرْاٰنِ مَا هُوَ شِفَٓاءٌ وَرَحْمَةٌ لِلْمُؤْمِن۪ينَۙ وَلَا يَز۪يدُ الظَّالِم۪ينَ اِلَّا خَسَاراً', 'Ve nunezzilu minel kur\'ani ma huve şifaun ve rahmetun lil mu\'minine ve la yeziduz zalimine illa hasara.', 'Kur\'an\'dan indirdiğimiz şeyler,  mü\'minler için şifadır,  rahmettir. Zalimlerin ise yalnızca hüsranını arttırır.', 'وننزل من القران ما هو شفا ورحمة للمومنين ولا يزيد الظلمين الا خسارا');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2112, 17, 83, 'وَاِذَٓا اَنْعَمْنَا عَلَى الْاِنْسَانِ اَعْرَضَ وَنَاٰ بِجَانِبِه۪ۚ وَاِذَا مَسَّهُ الشَّرُّ كَانَ يَؤُ۫ساً', 'Ve iza en\'amna alel insani a\'rada ve neabi canibih, ve iza messehuş şerru kane yeusa.', 'Ve kimi insana nimet verdiğimiz zaman,  yüz çevirerek uzaklaşır. Ve ona bir kötülük dokunduğunda umutsuzluğa düşer.', 'واذا انعمنا علي الانسن اعرض ونا بجانبه واذا مسه الشر كان يوسا'),
(2113, 17, 84, 'قُلْ كُلٌّ يَعْمَلُ عَلٰى شَاكِلَتِه۪ۜ فَرَبُّكُمْ اَعْلَمُ بِمَنْ هُوَ اَهْدٰى سَب۪يلاً۟', 'Kul kullun ya\'melu ala şakiletih, fe rabbukum a\'lemu bi men huve ehda sebila.', 'De ki: \"Herkes kendi karakterine göre davranır. Rabb\'in,  kimin doğru yolu seçtiğini iyi bilir.\"', 'قل كل يعمل علي شاكلته فربكم اعلم بمن هو اهدي سبيلا'),
(2114, 17, 85, 'وَيَسْـَٔلُونَكَ عَنِ الرُّوحِۜ قُلِ الرُّوحُ مِنْ اَمْرِ رَبّ۪ي وَمَٓا اُو۫ت۪يتُمْ مِنَ الْعِلْمِ اِلَّا قَل۪يلاً', 'Ve yes\'eluneke anir ruh, kulir ruhu min emri rabbi ve ma utitum minel ilmi illa kalila.', 'Sana ruhtan[1] soruyorlar. De ki: \"Ruh,  Rabb\'imin işindendir[2]. Ve size ilimden çok az verilmiştir.\"', 'ويسلونك عن الروح قل الروح من امر ربي وما اوتيتم من العلم الا قليلا'),
(2115, 17, 86, 'وَلَئِنْ شِئْنَا لَنَذْهَبَنَّ بِالَّـذ۪ٓي اَوْحَيْنَٓا اِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِه۪ عَلَيْنَا وَك۪يلاًۙ', 'Ve lein şi\'na le nezhebenne billezi evhayna ileyke summe la tecidu leke bihi aleyna vekila.', 'Eğer dilersek,  sana vahyettiklerimizi ortadan kaldırırız; sonra Bize karşı kendine bir vekil[1] bulamazsın.', 'ولين شينا لنذهبن بالذي اوحينا اليك ثم لا تجد لك به علينا وكيلا'),
(2116, 17, 87, 'اِلَّا رَحْمَةً مِنْ رَبِّكَۜ اِنَّ فَضْلَهُ  كَانَ عَلَيْكَ كَب۪يراً', 'İlla rahmeten min rabbik, inne fadlehu kane aleyke kebira.', 'Ancak bu,  Rabb\'inden bir rahmettir. O\'nun,  senin üzerindeki lütfu çok büyüktür.', 'الا رحمة من ربك ان فضله كان عليك كبيرا'),
(2117, 17, 88, 'قُلْ لَئِنِ اجْتَمَعَتِ الْاِنْسُ وَالْجِنُّ عَلٰٓى اَنْ يَأْتُوا بِمِثْلِ هٰذَا الْقُرْاٰنِ لَا يَأْتُونَ بِمِثْلِه۪ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَه۪يراً', 'Kul leinictemeatil insu vel cinnu ala en ye\'tu bi misli hazel kur\'ani la ye\'tune bi mislihi ve lev kane ba\'duhum li ba\'dın zahira.', 'De ki: \"Eğer ins[1] ve cinn[1] bu Kur\'an\'ın benzerini getirmek için bir araya gelseler ve birbirlerine yardımcı olsalar yine de onun benzerini ortaya koyamazlar.\"', 'قل لين اجتمعت الانس والجن علي ان ياتوا بمثل هذا القران لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا'),
(2118, 17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ ف۪ي هٰذَا الْقُرْاٰنِ مِنْ كُلِّ مَثَلٍۘ فَاَبٰٓى اَكْثَرُ النَّاسِ اِلَّا كُفُوراً', 'Ve lekad sarrafna lin nasi fi hazel kur\'ani min kulli meselin fe eba ekserun nasi illa kufura.', 'Ant olsun Biz,  bu Kur\'an\'da insanlara her türlü örneği verdik. Buna rağmen insanların çoğu yine de Kafirlikte[1] diretti.', 'ولقد صرفنا للناس في هذا القران من كل مثل فابي اكثر الناس الا كفورا'),
(2119, 17, 90, 'وَقَالُوا لَنْ نُؤْمِنَ لَكَ حَتّٰى تَفْجُرَ لَنَا مِنَ الْاَرْضِ يَنْبُوعاًۙ', 'Ve kalu len nu\'mine leke hatta tefcure lena minel ardı yenbua.', '\"Yerden bizim için bir pınar fışkırtmadıkça sana asla inanmayacağız.\" dediler.', 'وقالوا لن نومن لك حتي تفجر لنا من الارض ينبوعا'),
(2120, 17, 91, 'اَوْ تَكُونَ لَكَ جَنَّةٌ مِنْ نَخ۪يلٍ وَعِنَبٍ فَتُفَجِّرَ الْاَنْهَارَ خِلَالَهَا تَفْج۪يراًۙ', 'Ev tekune leke cennetun min nahilin ve inebin fe tufeccirel enhare hılaleha tefcira.', '\"Veya senin hurma ve üzüm bağlarından bir bahçen olmalı ve aralarından gürül gürül nehirler akıtmalısın.\"', 'او تكون لك جنة من نخيل وعنب فتفجر الانهر خللها تفجيرا'),
(2121, 17, 92, 'اَوْ تُسْقِطَ السَّمَٓاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفاً اَوْ تَأْتِيَ بِاللّٰهِ وَالْمَلٰٓئِكَةِ قَب۪يلاًۙ', 'Ev tuskıtas semae kema zeamte aleyna kisefen ev te\'tiye billahi vel melaiketi kabila.', '\"Veya iddia ettiğin gibi,  göğü paramparça edip üzerimize yıkmalısın. Veya Allah\'ı ve melekleri karşımıza çıkarmalısın.\"', 'او تسقط السما كما زعمت علينا كسفا او تاتي بالله والمليكة قبيلا'),
(2122, 17, 93, 'اَوْ يَكُونَ لَكَ بَيْتٌ مِنْ زُخْرُفٍ اَوْ تَرْقٰى فِي السَّمَٓاءِۜ وَلَنْ نُؤْمِنَ لِرُقِيِّكَ حَتّٰى تُنَزِّلَ عَلَيْنَا كِتَاباً نَقْرَؤُ۬هُۜ قُلْ سُبْحَانَ رَبّ۪ي هَلْ كُنْتُ اِلَّا بَشَراً رَسُولاً۟', 'Ev yekune leke beytun min zuhrufin ev terka fis sema, ve len nu\'mine li rukıyyike hatta tunezzile aleyna kitaben nakreuh, kul subhane rabbi hel kuntu illa beşeren resula.', '\"Veya altından bir evin olmalı,  ya da göğe yükselmelisin. Çıksan dahi,  bize oradan okuyacağımız bir kitap indirmedikçe senin yükselişine asla inanmayız. De ki: \"Benim Rabb\'im noksanlıklardan arıdır. Ben,  bir beşer ve resulden başka bir şey miyim ki?\"', 'او يكون لك بيت من زخرف او ترقي في السما ولن نومن لرقيك حتي تنزل علينا كتبا نقروه قل سبحان ربي هل كنت الا بشرا رسولا'),
(2123, 17, 94, 'وَمَا مَنَعَ النَّاسَ اَنْ يُؤْمِنُٓوا اِذْ جَٓاءَهُمُ الْهُدٰٓى اِلَّٓا اَنْ قَالُٓوا اَبَعَثَ اللّٰهُ بَشَراً رَسُولاً', 'Ve ma menean nase en yu\'minu iz cae humul huda illa en kalu e beasallahu beşeren resula.', 'İnsanlara,  doğru yola ileten rehber gelince,  onları iman etmekten alıkoyan şey,  \"Allah,  ölümlü bir beşeri mi resul gönderdi?\" şeklindeki anlayışlarıdır.', 'وما منع الناس ان يومنوا اذ جاهم الهدي الا ان قالوا ابعث الله بشرا رسولا'),
(2124, 17, 95, 'قُلْ لَوْ كَانَ فِي الْاَرْضِ مَلٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنّ۪ينَ لَنَزَّلْنَا عَلَيْهِمْ مِنَ السَّمَٓاءِ مَلَكاً رَسُولاً', 'Kul lev kane fil ardı melaiketun yemşune mutmainnine le nezzelna aleyhim mines semai meleken resula.', 'De ki: \"Eğer yeryüzünün sakinleri melekler olsaydı,  elbette onlara gökten resul olarak bir melek gönderirdik.\"', 'قل لو كان في الارض مليكة يمشون مطمينين لنزلنا عليهم من السما ملكا رسولا'),
(2125, 17, 96, 'قُلْ كَفٰى بِاللّٰهِ شَه۪يداً بَيْن۪ي وَبَيْنَكُمْۜ اِنَّهُ كَانَ بِعِبَادِه۪ خَب۪يراً بَص۪يراً', 'Kul kefa billahi şehiden beyni ve beynekum, innehu kane bi ıbadihi habiren basira.', 'De ki: \"Benimle sizin aranızda şahit olarak Allah yeter.\" Kuşkusuz O,  kulları için Her Şeyden Haberdar Olan\'dır,  Her Şeyi Gören\'dir.', 'قل كفي بالله شهيدا بيني وبينكم انه كان بعباده خبيرا بصيرا'),
(2126, 17, 97, 'وَمَنْ يَهْدِ اللّٰهُ فَهُوَ الْمُهْتَدِۚ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُمْ اَوْلِيَٓاءَ مِنْ دُونِه۪ۜ وَنَحْشُرُهُمْ يَوْمَ الْقِيٰمَةِ عَلٰى وُجُوهِهِمْ عُمْياً وَبُكْماً وَصُماًّۜ مَأْوٰيهُمْ جَهَنَّمُۜ  كُلَّمَا خَبَتْ زِدْنَاهُمْ سَع۪يراً', 'Ve men yehdillahu fe huvel muhted, ve men yudlil fe len tecide lehum evliyae min dunih, ve nahşuruhum yevmel kıyameti ala vucuhihim umyen ve bukmen ve summa, me\'vahum cehennem, kullema habet zidnahum saira.', 'Allah,  kime hidayet etmişse[1],  işte o doğru yolu bulmuştur. Kimi de saptırırsa[1],  onun için,  O\'ndan başka veliler bulamazsın. Kıyamet Günü,  onları; kör,  sağır ve dilsiz olarak yüzüstü sürünür durumda mahşer yerine toplarız. Onların varacakları yer Cehennem\'dir. O ne zaman dinse,  onlara ateşi artırırız.', 'ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم اوليا من دونه ونحشرهم يوم القيمة علي وجوههم عميا وبكما وصما ماويهم جهنم كلما خبت زدنهم سعيرا'),
(2127, 17, 98, 'ذٰلِكَ جَزَٓاؤُ۬هُمْ بِاَنَّهُمْ كَفَرُوا بِاٰيَاتِنَا وَقَالُٓوا ءَاِذَا كُنَّا عِظَاماً وَرُفَاتاً ءَاِنَّا لَمَبْعُوثُونَ خَلْقاً جَد۪يداً', 'Zalike cezauhum bi ennehum keferu bi ayatina ve kalu e iza kunna izamen ve rufaten e inna le meb\'usune halkan cedida.', 'Onların,  cezalandırılmalarının nedeni,  ayetlerimizi inkar etmelerinden ve \"Biz bir yığın kemik ve ufalanmış toz haline geldikten sonra mı yeni bir yaratılışla diriltilecekmişiz?\" diye alay etmeleridir.', 'ذلك جزاوهم بانهم كفروا بايتنا وقالوا اذا كنا عظما ورفتا انا لمبعوثون خلقا جديدا'),
(2128, 17, 99, 'اَوَلَمْ يَرَوْا اَنَّ اللّٰهَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ قَادِرٌ عَلٰٓى اَنْ يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ اَجَلاً لَا رَيْبَ ف۪يهِۜ فَاَبَى الظَّالِمُونَ اِلَّا كُفُوراً', 'E ve lem yerev ennallahellezi halakas semavati vel arda kadirun ala en yahluka mislehum ve ceale lehum ecelen la reybe fih, fe ebaz zalimune illa kufura.', 'Gökleri ve yeri yaratan Allah\'ın,  tıpkı bunlar gibi,  yeni yaratmalara da gücünün yeteceğini görmüyorlar mı? Kendileri için bir gün sona ereceği kesin olan bir süre tayin etmiştir. Zalimlerin yaptıkları Küfr\'den[1] başka bir şey değildir.', 'اولم يروا ان الله الذي خلق السموت والارض قادر علي ان يخلق مثلهم وجعل لهم اجلا لا ريب فيه فابي الظلمون الا كفورا'),
(2129, 17, 100, 'قُلْ لَوْ اَنْتُمْ تَمْلِكُونَ خَزَٓائِنَ رَحْمَةِ رَبّ۪ٓي اِذاً لَاَمْسَكْتُمْ خَشْيَةَ الْاِنْفَاقِۜ وَكَانَ الْاِنْسَانُ قَتُوراً۟', 'Kul lev entum temlikune hazaine rahmeti rabbi izen le emsektum haşyetel infak, ve kanel insanu katura.', 'De ki: \"Eğer siz,  Rabb\'imin rahmet hazinelerine sahip olsaydınız,  tükenir endişesi ile kimseye bir şey vermezdiniz. Kimi insan çok cimridir.[1]\"', 'قل لو انتم تملكون خزاين رحمة ربي اذا لامسكتم خشية الانفاق وكان الانسن قتورا'),
(2130, 17, 101, 'وَلَقَدْ اٰتَيْنَا مُوسٰى تِسْعَ اٰيَاتٍ بَيِّنَاتٍ فَسْـَٔلْ بَن۪ٓي اِسْرَٓائ۪لَ اِذْ جَٓاءَهُمْ فَقَالَ لَهُ فِرْعَوْنُ اِنّ۪ي لَاَظُنُّكَ يَا مُوسٰى مَسْحُوراً', 'Ve lekad ateyna musa tis\'a ayatin beyyinatin fes\'el beni israile iz caehum fe kale lehu fir\'avnu inni le ezunnuke ya musa meshura.', 'Ant olsun ki Biz Musa\'ya apaçık dokuz ayet[1] verdik. İsrailoğulları\'na sor. Onlara geldiğinde,  Firavun ona,  \"Ey Musa! Ben kesinlikle büyülenmiş olduğunu görüyorum.\" demişti.', 'ولقد اتينا موسي تسع ايت بينت فسل بني اسريل اذ جاهم فقال له فرعون اني لاظنك يموسي مسحورا'),
(2131, 17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَٓا اَنْزَلَ هٰٓؤُ۬لَٓاءِ اِلَّا رَبُّ السَّمٰوَاتِ وَالْاَرْضِ بَصَٓائِرَۚ وَاِنّ۪ي لَاَظُنُّكَ يَا فِرْعَوْنُ مَثْبُوراً', 'Kale lekad alimte ma enzele haulai illa rabbus semavati vel ardı basair, ve inni le ezunnuke ya fir\'avnu mesbura.', 'Musa: \"Bunları uyarıcı,  aydınlatıcı olarak göklerin ve yerin Rabb\'inden başkasının indirmediğini sen bildin. Ey Firavun! Ben de senin mahvolduğunu görüyorum\". dedi.', 'قال لقد علمت ما انزل هولا الا رب السموت والارض بصاير واني لاظنك يفرعون مثبورا'),
(2132, 17, 103, 'فَاَرَادَ اَنْ يَسْتَفِزَّهُمْ مِنَ الْاَرْضِ فَاَغْرَقْنَاهُ وَمَنْ مَعَهُ جَم۪يعاًۙ', 'Fe erade en yestefizzehum minel ardı fe agraknahu ve men meahu cemia.', 'Bunun üzerine yeryüzünü onlara dar etti.[1] Biz,  onu ve beraberinde olanların tamamını suda boğduk.', 'فاراد ان يستفزهم من الارض فاغرقنه ومن معه جميعا'),
(2133, 17, 104, 'وَقُلْنَا مِنْ بَعْدِه۪ لِبَن۪ٓي اِسْرَٓائ۪لَ اسْكُنُوا الْاَرْضَ فَاِذَا جَٓاءَ وَعْدُ الْاٰخِرَةِ جِئْنَا بِكُمْ لَف۪يفاًۜ', 'Ve kulna min ba\'dihi li beni israileskunul arda fe iza cae va\'dul ahıreti ci\'na bikum lefifa.', 'Arkasından İsrailoğulları\'na,  \"güven içinde o yerde yerleşin! Sonra ahiret için verilen süre dolunca hepinizi toplayıp bir araya getireceğiz.\" dedik.', 'وقلنا من بعده لبني اسريل اسكنوا الارض فاذا جا وعد الاخرة جينا بكم لفيفا'),
(2134, 17, 105, 'وَبِالْحَقِّ اَنْزَلْنَاهُ وَبِالْحَقِّ نَزَلَۜ وَمَٓا اَرْسَلْنَاكَ اِلَّا مُبَشِّراً وَنَذ۪يراًۢ', 'Ve bil hakkı enzelnahu ve bil hakkı nezel, ve ma erselnake illa mubeşşiren ve nezira.', 'Onu hakk ile indirdik. Ve hakk[1] ile indi. Seni,  haber verici ve uyarıcı olmandan başka bir şey için göndermedik.', 'وبالحق انزلنه وبالحق نزل وما ارسلنك الا مبشرا ونذيرا'),
(2135, 17, 106, 'وَقُرْاٰناً فَرَقْنَاهُ لِتَقْرَاَهُ۫ عَلَى النَّاسِ عَلٰى مُكْثٍ وَنَزَّلْنَاهُ تَنْز۪يلاً', 'Ve kur\'anen faraknahu li takreehu alen nasi ala muksin ve nezzelnahu tenzila.', 'Kur\'an\'ı; onu,  zamana yayarak insanlara duyurman[1] için bölümler halinde birbiri ardınca indirdik.', 'وقرانا فرقنه لتقراه علي الناس علي مكث ونزلنه تنزيلا'),
(2136, 17, 107, 'قُلْ اٰمِنُوا بِه۪ٓ اَوْ لَا تُؤْمِنُواۜ اِنَّ الَّذ۪ينَ اُو۫تُوا الْعِلْمَ مِنْ قَبْلِه۪ٓ اِذَا يُتْلٰى عَلَيْهِمْ يَخِرُّونَ لِلْاَذْقَانِ سُجَّداًۙ', 'Kul aminu bihi ev la tu\'minu, innellezine utul ilme min kablihi iza yutla aleyhim yahırrune lil ezkani succeda.', 'De ki: \"Ona ister inanın ister inanmayın; daha önce kendilerine ilim verilenler[1],  o,  onlara okunduğu zamanlar,  çeneleri üzerine secdeye[2] kapanırlar.\"', 'قل امنوا به او لا تومنوا ان الذين اوتوا العلم من قبله اذا يتلي عليهم يخرون للاذقان سجدا'),
(2137, 17, 108, 'وَيَقُولُونَ سُبْحَانَ رَبِّنَٓا اِنْ كَانَ وَعْدُ رَبِّنَا لَمَفْعُولاً', 'Ve yekulune subhane rabbina in kane va\'du rabbina le mef\'ula.', 'Ve derler ki: \"Rabb\'imiz her şeyden yücedir. Rabb\'imizin uyarısı kesinlikle gerçekleşecektir.', 'ويقولون سبحن ربنا ان كان وعد ربنا لمفعولا'),
(2138, 17, 109, 'وَيَخِرُّونَ لِلْاَذْقَانِ يَبْكُونَ وَيَز۪يدُهُمْ خُشُوعاً', 'Ve yahırrune lil ezkani yebkune ve yeziduhum huşua.', 'Onlar,  ağlayarak çeneleri üzerine kapanırlar[1]. Bu onların huşularını[2] artırır.', 'ويخرون للاذقان يبكون ويزيدهم خشوعا'),
(2139, 17, 110, 'قُلِ ادْعُوا اللّٰهَ اَوِ ادْعُوا الرَّحْمٰنَۜ  اَياًّ مَا تَدْعُوا فَلَهُ الْاَسْمَٓاءُ الْحُسْنٰىۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذٰلِكَ سَب۪يلاً', 'Kulid\'ullahe evid\'ur rahman, eyyen ma ted\'u fe lehul esmaul husna, ve la techer bi salatike ve la tuhafit biha vebtegı beyne zalike sebila.', 'De ki: \"İster Allah diye çağırın ister Rahman diye çağırın. Hangisiyle çağırırsanız çağırın en iyi isimler O\'nundur.\" Salatında[1] ne fazla yükselt ne de fazla kıs.[2] Bu ikisi arasında bir yol tut.', 'قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسما الحسني ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا'),
(2140, 17, 111, 'وَقُلِ الْحَمْدُ لِلّٰهِ الَّذ۪ي لَمْ يَتَّخِذْ وَلَداً وَلَمْ يَكُنْ لَهُ شَر۪يكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْب۪يراً', 'Ve kulil hamdu lillahillezi lem yettehız veleden ve lem yekun lehu şerikun fil mulki ve lem yekun lehu veliyyun minez zulli ve kebbirhu tekbira.', 'Ve de ki: \"Hamd[1],  çocuk edinmeyen Allah\'a özgüdür. O\'nun mülkte[2] ortağı yoktur. O\'nun acizlikten dolayı bir veliye[3] de ihtiyacı yoktur.\" O\'nu tam bir yüceltme ile yücelt.', 'وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا'),
(2141, 18, 1, 'اَلْحَمْدُ لِلّٰهِ الَّـذ۪ٓي اَنْزَلَ عَلٰى عَبْدِهِ الْـكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِـوَجا۔ًۜ', 'El hamdulillahillezi enzele ala abdihil kitabe ve lem yec\'al lehu ıveca.', 'Hamd[1],  kendisinde hiçbir çelişki olmayan Kitap\'ı indiren Allah\'a aittir.', 'الحمد لله الذي انزل علي عبده الكتب ولم يجعل له عوجا'),
(2142, 18, 2, 'قَيِّماً لِيُنْذِرَ بَأْساً شَد۪يداً مِنْ لَدُنْـهُ وَيُبَشِّرَ الْمُؤْمِن۪ينَ الَّذ۪ينَ يَعْمَلُونَ الصَّالِحَاتِ اَنَّ لَهُمْ اَجْراً حَسَناًۙ', 'Kayyimen li yunzire be\'sen şediden min ledunhu ve yubeşşirel mu\'mininellezine ya\'melunes salihati enne lehum ecren hasena.', 'Dosdoğru bir gözetici olarak; şiddetli azaba karşı uyarmak,  erdemli ve doğru davranışlarda bulunan Mü\'minlere,  en iyi karşılığın onların olduğunu müjdelemek için katından indirdi.', 'قيما لينذر باسا شديدا من لدنه ويبشر المومنين الذين يعملون الصلحت ان لهم اجرا حسنا'),
(2143, 18, 3, 'مَاكِث۪ينَ ف۪يهِ اَبَداًۙ', 'Makisine fihi ebeda.', 'Onlar,  orada[1] ebediyen kalıcıdırlar.', 'مكثين فيه ابدا'),
(2144, 18, 4, 'وَيُنْذِرَ الَّذ۪ينَ قَالُوا اتَّخَذَ اللّٰهُ وَلَداًۗ', 'Ve yunzirellezine kaluttehazellahu veleda.', 'Ve \"Allah,  çocuk edindi.\" diyenleri uyarmak için.', 'وينذر الذين قالوا اتخذ الله ولدا'),
(2145, 18, 5, 'مَا لَهُمْ بِه۪ مِنْ عِلْمٍ وَلَا لِاٰبَٓائِهِمْۜ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ اَفْوَاهِهِمْۜ اِنْ يَقُولُونَ اِلَّا كَذِباً', 'Ma lehum bihi min ilmin ve la li abaihim, keburet kelimeten tahrucu min efvahihim, in yekulune illa keziba.', 'Buna dair kendilerinin de atalarının da hiçbir bilgileri yoktur. Çok büyük söz ediyorlar. Yalandan başka bir şey söylemiyorlar.', 'ما لهم به من علم ولا لابايهم كبرت كلمة تخرج من افوههم ان يقولون الا كذبا'),
(2146, 18, 6, 'فَلَعَلَّكَ بَاخِـعٌ نَفْسَكَ عَلٰٓى اٰثَارِهِمْ اِنْ لَمْ يُؤْمِنُوا بِهٰذَا الْحَد۪يثِ اَسَفاً', 'Fe lealleke bahiun nefseke ala asarihim in lem yu\'minu bi hazel hadisi esefa.', 'Onlar,  bu söze inanmıyorlar diye,  onların durumlarına üzüntünden neredeyse kendini harap edeceksin!', 'فلعلك بخع نفسك علي اثرهم ان لم يومنوا بهذا الحديث اسفا'),
(2147, 18, 7, 'اِنَّا جَعَلْنَا مَا عَلَى الْاَرْضِ ز۪ينَةً لَهَا لِنَبْلُوَهُمْ اَيُّهُمْ اَحْسَنُ عَمَلاً', 'İnna cealna ma alel ardı zineten leha li nebluvehum eyyuhum ahsenu amela.', 'Biz,  hangisinin daha iyi şeyler yapacağına sınav olsun diye,  yeryüzünde olan şeyleri ilgi çekici yaptık.', 'انا جعلنا ما علي الارض زينة لها لنبلوهم ايهم احسن عملا'),
(2148, 18, 8, 'وَاِنَّا لَجَاعِلُونَ مَا عَلَيْهَا صَع۪يداً جُرُزاًۜ', 'Ve inna le cailune ma aleyha saiden curuza.', 'Yeryüzünde olan güzellikleri kupkuru toprak haline getireceğiz.', 'وانا لجعلون ما عليها صعيدا جرزا'),
(2149, 18, 9, 'اَمْ حَسِبْتَ اَنَّ اَصْحَابَ الْكَهْفِ وَالرَّق۪يمِ كَانُوا مِنْ اٰيَاتِنَا عَجَباً', 'Em hasibte enne ashabel kehfi ver rakimi kanu min ayatina acaba.', 'Yoksa sen,  Kehf[1] ve Rakim[2] Ashabı\'nın[3] Bizim en şaşılacak ayetlerimizden[4] olduklarını mı sandın?', 'ام حسبت ان اصحب الكهف والرقيم كانوا من ايتنا عجبا'),
(2150, 18, 10, 'اِذْ اَوَى الْفِتْيَةُ اِلَى الْكَهْفِ فَقَالُوا رَبَّنَٓا اٰتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ اَمْرِنَا رَشَداً', 'İz evel fityetu ilel kehfi fe kalu rabbena atina min ledunke rahmeten ve heyyi\' lena min emrina reşeda.', 'Gençler,  mağaraya sığındıkları zaman şöyle demişlerdi: \"Rabb\'imiz,  bize kendi katından bir rahmet ver. İşimizde doğru olanı yapma bilinci lütfet.\"', 'اذ اوي الفتية الي الكهف فقالوا ربنا اتنا من لدنك رحمة وهيي لنا من امرنا رشدا'),
(2151, 18, 11, 'فَضَرَبْنَا عَلٰٓى اٰذَانِهِمْ فِي الْكَهْفِ سِن۪ينَ عَدَداًۙ', 'Fe darabna ala azanihim fil kehfi sinine adeda.', 'Böylece onları yıllar yılı mağarada dış dünyadan habersiz yaptık.', 'فضربنا علي اذانهم في الكهف سنين عددا'),
(2152, 18, 12, 'ثُمَّ بَعَثْنَاهُمْ لِنَعْلَمَ اَيُّ الْحِزْبَيْنِ اَحْصٰى لِمَا لَبِثُٓوا اَمَداً۟', 'Summe beasnahum li na\'leme eyyul hızbeyni ahsa lima lebisu emeda.', 'Sonra iki gruptan hangisinin kaldıkları süreyi daha iyi hesapladığını ortaya çıkarmak için,  onları tekrar uyandırdık.', 'ثم بعثنهم لنعلم اي الحزبين احصي لما لبثوا امدا'),
(2153, 18, 13, 'نَحْنُ نَقُصُّ عَلَيْكَ نَبَاَهُمْ بِالْحَقِّۜ اِنَّهُمْ فِتْيَةٌ اٰمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًىۗ', 'Nahnu nakussu aleyke nebeehum bil hakk, innehum fityetun amenu bi rabbihim ve zidnahum huda.', 'Biz,  sana onların hikayesini bütün gerçekliği ile anlatıyoruz. Onlar Rabb\'lerine iman eden gençlerdi. Biz de onlara hidayeti[1] arttırdık.', 'نحن نقص عليك نباهم بالحق انهم فتية امنوا بربهم وزدنهم هدي'),
(2154, 18, 14, 'وَرَبَطْنَا عَلٰى قُلُوبِهِمْ اِذْ قَامُوا فَقَالُوا رَبُّنَا رَبُّ السَّمٰوَاتِ وَالْاَرْضِ لَنْ نَدْعُوَ۬ا مِنْ دُونِه۪ٓ اِلٰهاً لَقَدْ قُلْـنَٓا اِذاً شَطَطاً', 'Ve rabatna ala kulubihim iz kamu fe kalu rabbuna rabbus semavati vel ardı len ned\'uve min dunihi ilahen lekad kulna izen şetata.', 'Onların kalplerini pekiştirdik. Kıyam ederek[1]: \"Bizim Rabb\'imiz,  göklerin ve yeryüzünün Rabb\'idir\" dediler. \"Ondan başkasını asla ilah diye çağırmayız. Yoksa kesinlikle saçmalamış oluruz.\"', 'وربطنا علي قلوبهم اذ قاموا فقالوا ربنا رب السموت والارض لن ندعوا من دونه الها لقد قلنا اذا شططا'),
(2155, 18, 15, 'هٰٓؤُ۬لَٓاءِ قَوْمُنَا اتَّخَذُوا مِنْ دُونِه۪ٓ اٰلِهَةًۜ  لَوْلَا يَأْتُونَ عَلَيْهِمْ بِسُلْطَانٍ بَيِّنٍۜ فَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباًۜ', 'Haulai kavmunettehazu min dunihi aliheh, lev la ye\'tune aleyhim bi sultanin beyyin, fe men azlemu mimmeniftera alallahi keziba.', '\"İşte bunlar,  O\'nun yanı sıra ilahlar edinenler bizim halkımızdır. Onların ilahlığını gösteren açık bir yetki belgesi getirselerdi ya! Allah\'a karşı yalan uydurandan daha zalim kim olabilir?\"', 'هولا قومنا اتخذوا من دونه الهة لولا ياتون عليهم بسلطن بين فمن اظلم ممن افتري علي الله كذبا'),
(2156, 18, 16, 'وَاِذِ اعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ اِلَّا اللّٰهَ فَأْوُٓ۫ا اِلَى الْكَهْفِ يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِه۪ وَيُهَيِّئْ لَكُمْ مِنْ اَمْرِكُمْ مِرْفَقاً', 'Ve izi\'tezeltumuhum ve ma ya\'budune illallahe fe\'vu ilel kehfi yenşur lekum rabbukum min rahmetihi ve yuheyyi\' lekum min emrikum mirfeka.', '\"Mademki onlardan ve Allah\'tan başka kulluk[1] ettikleri şeylerden ayrılmayı tercih ettiniz,  o halde mağaraya sığının ki,  Rabb\'iniz size rahmetini açsın ve size destek olarak işlerinizi kolaylaştırsın.\"', 'واذ اعتزلتموهم وما يعبدون الا الله فاوا الي الكهف ينشر لكم ربكم من رحمته ويهيي لكم من امركم مرفقا'),
(2157, 18, 17, 'وَتَرَى الشَّمْسَ اِذَا طَلَعَتْ تَزَاوَرُ عَنْ كَهْفِهِمْ ذَاتَ الْيَم۪ينِ وَاِذَا غَرَبَتْ تَقْرِضُهُمْ ذَاتَ الشِّمَالِ وَهُمْ ف۪ي فَجْوَةٍ مِنْهُۜ ذٰلِكَ مِنْ اٰيَاتِ اللّٰهِۜ مَنْ يَهْدِ اللّٰهُ فَهُوَ الْمُهْتَدِۚ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُ وَلِياًّ مُرْشِداً۟', 'Ve tereş şemse iza taleat tezaveru an kehfihim zatel yemini ve iza garabet takrıduhum zateş şimali ve hum fi fecvetin minh, zalike min ayatillah, men yehdillahu fe huvel muhted, ve men yudlil fe len tecide lehu veliyyen murşida.', 'Onlar,  mağaranın geniş bir dehlizinde bulunurlarken,  Güneş\'in doğduğu zaman,  mağaralarından sağa tarafa yöneldiğini,  battığı zaman da sol tarafa doğru onları makaslayıp geçtiğini görürsün.[1] Bu Allah\'ın ayetlerindendir.[2] Allah,  kimi doğru yola iletirse[3],  işte o doğru yolu bulmuştur. Kimi de sapkınlıkta bırakırsa[3],  artık onun için yol gösteren bir veli[4] bulamazsın.', 'وتري الشمس اذا طلعت تزور عن كهفهم ذات اليمين واذا غربت تقرضهم ذات الشمال وهم في فجوة منه ذلك من ايت الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا'),
(2158, 18, 18, 'وَتَحْسَبُهُمْ اَيْقَاظاً وَهُمْ رُقُودٌۗ وَنُقَلِّبُهُمْ ذَاتَ الْيَم۪ينِ وَذَاتَ الشِّمَالِۗ وَكَلْبُهُمْ بَاسِطٌ ذِرَاعَيْهِ بِالْوَص۪يدِۜ لَوِ اطَّـلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَاراً وَلَمُلِئْتَ مِنْهُمْ رُعْباً', 'Ve tahsebuhum eykazan ve hum rukud, ve nukallibuhum zatel yemini ve zateş şimal, ve kelbuhum basitun ziraayhi bil vasid, levittala\'te aleyhim le velleyte minhum firaren ve le muli\'te minhum ru\'ba.', 'Uykuda oldukları halde sen onları uyanık sanırsın. Ve biz onları sağ yanlarına ve sol yanlarına çeviririz. Köpekleri de avluda ön ayaklarını öne doğru uzatmıştı. Eğer sen onlarla karşılaşsaydın,  gerisin geri kaçardın. Ve korkudan ürperirdin.', 'وتحسبهم ايقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم بسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولمليت منهم رعبا'),
(2159, 18, 19, 'وَكَذٰلِكَ بَعَثْنَاهُمْ لِيَتَسَٓاءَلُوا بَيْنَهُمْۜ قَالَ قَٓائِلٌ مِنْهُمْ كَمْ لَبِثْتُمْۜ قَالُوا لَبِثْنَا يَوْماً اَوْ بَعْضَ يَوْمٍۜ قَالُوا رَبُّكُمْ اَعْلَمُ بِمَا لَبِثْتُمْ فَابْعَثُٓوا اَحَدَكُمْ بِوَرِقِكُمْ هٰذِه۪ٓ اِلَى الْمَد۪ينَةِ فَلْيَنْظُرْ اَيُّهَٓا اَزْكٰى طَعَاماً فَلْيَأْتِكُمْ بِرِزْقٍ مِنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ اَحَداً', 'Ve kezalike beasnahum li yetesaelu beynehum, kale kailun minhum kem lebistum, kalu lebisna yevmen ev ba\'da yevm, kalu rabbukum a\'lemu bi ma lebistum feb\'asu ehadekum bi verıkıkum hazihi ilel medineti fel yanzur eyyuha ezka taamen fel ye\'tikum bi rızkın minhu vel yetelattaf ve la yuş\'ırenne bikum ehada.', 'Onları uyandırdık ve böylece birbirlerine sormaya başladılar. Onlardan biri şu soruyu sordu: \"Ne kadar kaldınız?\" \"Bir gün veya günün bir bölümü kadar.\" dediler. Kimisi de: \"Ne kadar kaldığınızı Rabb\'iniz bilir.\" dedi. \"Sizden birisini,  gümüş paranızla şehre gönderin. Hangi yiyeceği seviyorsanız ondan yiyecek getirsin. Ve sizi kimseye sezdirmemeye dikkat etsin.\"', 'وكذلك بعثنهم ليتسالوا بينهم قال قايل منهم كم لبثتم قالوا لبثنا يوما او بعض يوم قالوا ربكم اعلم بما لبثتم فابعثوا احدكم بورقكم هذه الي المدينة فلينظر ايها ازكي طعاما فلياتكم برزق منه وليتلطف ولا يشعرن بكم احدا'),
(2160, 18, 20, 'اِنَّهُمْ اِنْ يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ اَوْ يُع۪يدُوكُمْ ف۪ي مِلَّتِهِمْ وَلَنْ تُفْلِحُٓوا اِذاً اَبَداً', 'İnnehum in yazheru aleykum yercumukum ev yuidukum fi milletihim ve len tuflihu izen ebeda.', '\"Onlar sizi fark ederlerse,  sizi taşa tutarlar veya kendi milletlerine[1] döndürürler. O zaman,  kesinlikle ebediyen kurtuluşa eremezsiniz.\"', 'انهم ان يظهروا عليكم يرجموكم او يعيدوكم في ملتهم ولن تفلحوا اذا ابدا'),
(2161, 18, 21, 'وَكَذٰلِكَ اَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُٓوا اَنَّ وَعْدَ اللّٰهِ حَقٌّ وَاَنَّ السَّاعَةَ لَا رَيْبَ ف۪يهَاۚ اِذْ يَتَنَازَعُونَ بَيْنَهُمْ اَمْرَهُمْ فَقَالُوا ابْنُوا عَلَيْهِمْ بُنْيَاناًۜ رَبُّهُمْ اَعْلَمُ بِهِمْۜ قَالَ الَّذ۪ينَ غَلَبُوا عَلٰٓى اَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِداً', 'Ve kezalike a\'serna aleyhim li ya\'lemu enne va\'dallahi hakkun ve ennes saate la reybe fiha, iz yetenazeune beynehum emrehum fe kalubnu aleyhim bunyana, rabbuhum a\'lemu bihim, kalellezine galebu ala emrihim le nettehızenne aleyhim mescida.', 'Böylece,  Allah\'ın verdiği sözün gerçek olduğunu,  o Sa\'at\'in[1] kesin olduğunu bilmeleri için onları haberdar ettik. O zaman,  onların durumu hakkında aralarında tartışıyorlardı. \"Onların üzerlerine bir bina yapın; onların Rabb\'leri,  onları daha iyi bilir.\" dediler. Düşünceleri kabul edilenler: \"Onların üzerlerine bir mescid yapalım.\" dediler.', 'وكذلك اعثرنا عليهم ليعلموا ان وعد الله حق وان الساعة لا ريب فيها اذ يتنزعون بينهم امرهم فقالوا ابنوا عليهم بنينا ربهم اعلم بهم قال الذين غلبوا علي امرهم لنتخذن عليهم مسجدا'),
(2162, 18, 22, 'سَيَقُولُونَ ثَلٰثَةٌ رَابِعُهُمْ كَلْبُهُمْۚ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْماً بِالْغَيْبِۚ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْۜ قُلْ رَبّ۪ٓي اَعْلَمُ بِعِدَّتِهِمْ مَا يَعْلَمُهُمْ اِلَّا قَل۪يلٌ۠ فَلَا تُمَارِ ف۪يهِمْ اِلَّا مِرَٓاءً ظَاهِراًۖ وَلَا تَسْتَفْتِ ف۪يهِمْ مِنْهُمْ اَحَداً۟', 'Se yekulune selasetun rabiuhum kelbuhum, ve yekulune hamsetun sadisuhum kelbuhum recmen bil gayb, ve yekulune seb\'atun ve saminuhum kelbuhum, kul rabbi a\'lemu bi ıddetihim ma ya\'lemuhum illa kalil, fe la tumari fihim illa miraen zahira, ve la testefti fihim minhum ehada.', '\"Onlar üç kişidir,  dördüncüsü köpekleridir.\" diyecekler. Gayba taş atar gibi[1] \"Beş kişidir,  altıncısı köpekleridir.\" diyecekler,  \"Yedi kişidir,  sekizincisi köpekleridir.\" diyecekler. De ki: \"Onların sayılarını Rabb\'im bilir. Onları pek az kimseden başkası bilmez.\" Onlar hakkında,  Kur\'an\'ın verdiği bilgi dışında onlarla tartışma. Onlar hakkında tartışan hiç kimseden de bir açıklama isteme.', 'سيقولون ثلثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم رجما بالغيب ويقولون سبعة وثامنهم كلبهم قل ربي اعلم بعدتهم ما يعلمهم الا قليل فلا تمار فيهم الا مرا ظهرا ولا تستفت فيهم منهم احدا'),
(2163, 18, 23, 'وَلَا تَقُولَنَّ لِشَايْءٍ اِنّ۪ي فَاعِلٌ ذٰلِكَ غَداًۙ', 'Ve la tekulenne li şey\'in inni faılun zalike gada.', 'Hiçbir şey için,  \"Ben,  yarın bunu kesinlikle yapacağım.\" deme.', 'ولا تقولن لشاي اني فاعل ذلك غدا'),
(2164, 18, 24, 'اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُۘ وَاذْكُرْ رَبَّكَ اِذَا نَس۪يتَ وَقُلْ عَسٰٓى اَنْ يَهْدِيَنِ رَبّ۪ي لِاَقْرَبَ مِنْ هٰذَا رَشَداً', 'İlla en yeşaallahu vezkur rabbeke iza nesite ve kul asa en yehdiyeni rabbi li akrabe min haza reşeda.', 'Ancak,  \"Allah\'ın dilemesiyle yapacağım.\" de. Ve unuttuğun zaman Rabb\'ini an. Ve \"Umulur ki Rabb\'im beni en doğru olanı yapmaya yöneltir.\" de.', 'الا ان يشا الله واذكر ربك اذا نسيت وقل عسي ان يهدين ربي لاقرب من هذا رشدا'),
(2165, 18, 25, 'وَلَبِثُوا ف۪ي كَـهْفِهِمْ ثَلٰثَ مِائَةٍ سِن۪ينَ وَازْدَادُوا تِسْعاً', 'Ve lebisu fi kehfihim selase mietin sinine vezdadu tis\'a.', 'Onlar,  mağaralarında,  üç yüz yıl kaldılar ve dokuz yıl ilave ettiler.[1]', 'ولبثوا في كهفهم ثلث ماية سنين وازدادوا تسعا'),
(2166, 18, 26, 'قُلِ اللّٰهُ اَعْلَمُ بِمَا لَبِثُواۚ لَهُ غَيْبُ السَّمٰوَاتِ وَالْاَرْضِۜ اَبْصِرْ بِه۪ وَاَسْمِـعْۜ مَا لَهُمْ مِنْ دُونِه۪ مِنْ وَلِيٍّۘ وَلَا يُشْرِكُ ف۪ي حُكْمِه۪ٓ اَحَداً', 'Kulillahu a\'lemu bima lebisu, lehu gaybus semavati vel ard, ebsır bihi ve esmı\', ma lehum min dunihi min veliyyin ve la yuşriku fi hukmihi ehada.', 'De ki: \"Onların ne kadar kaldıklarını en iyi Allah bilir.\" Göklerin ve yerin bilinmezi yalnızca O\'na aittir. En iyi gören ve en iyi işiten O\'dur! Onlar için O\'ndan başka veli[1] yoktur. O,  hükümranlığına[2] kimseyi ortak etmez.', 'قل الله اعلم بما لبثوا له غيب السموت والارض ابصر به واسمع ما لهم من دونه من ولي ولا يشرك في حكمه احدا'),
(2167, 18, 27, 'وَاتْلُ مَٓا اُو۫حِيَ اِلَيْكَ مِنْ كِتَابِ رَبِّكَۚ لَا مُبَدِّلَ لِكَلِمَاتِه۪ وَلَنْ تَجِدَ مِنْ دُونِه۪ مُلْتَحَداً', 'Vetlu ma uhıye ileyke min kitabi rabbik, la mubeddile li kelimatihi ve len tecide min dunihi multehada.', 'Ve sen,  Rabb\'inin Kitap\'ından sana vahyedileni oku! O\'nun kelimelerini[1] değiştirecek yoktur. O\'ndan başka sığınılacak da bulamazsın.', 'واتل ما اوحي اليك من كتاب ربك لا مبدل لكلمته ولن تجد من دونه ملتحدا'),
(2168, 18, 28, 'وَاصْبِرْ نَفْسَكَ مَعَ الَّذ۪ينَ يَدْعُونَ رَبَّهُمْ بِالْغَدٰوةِ وَالْعَشِيِّ يُر۪يدُونَ وَجْهَهُ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْۚ تُر۪يدُ ز۪ينَةَ الْحَيٰوةِ الدُّنْيَا وَلَا تُطِـعْ مَنْ اَغْفَلْنَا قَلْبَهُ عَنْ ذِكْرِنَا وَاتَّبَعَ هَوٰيهُ وَكَانَ اَمْرُهُ فُرُطاً', 'Vasbır nefseke meallezine yed\'une rabbehum bil gadati vel aşiyyi yuridune vechehu ve la ta\'du aynake anhum, turidu zinetel hayatid dunya ve la tutı\' men agfelna kalbehu an zikrina vettebea hevahu ve kane emruhu furuta.', 'Sabah akşam[1] O\'nun yoluna yönelerek,  Rabb\'ine çağrıda bulunanlarla beraber olmada sabırlı ol. Dünya hayatının çekiciliğine kanarak gözlerini onlardan ayırma. Kalbini[2] zikrimizden gafil kıldığımız[3],  tutkularına uymuş,  işi aşırılık olan kimseye boyun eğme. [4]', 'واصبر نفسك مع الذين يدعون ربهم بالغدوة والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينة الحيوة الدنيا ولا تطع من اغفلنا قلبه عن ذكرنا واتبع هويه وكان امره فرطا'),
(2169, 18, 29, 'وَقُلِ الْحَقُّ مِنْ رَبِّكُمْ فَمَنْ شَٓاءَ فَلْيُؤْمِنْ وَمَنْ شَٓاءَ فَلْيَكْفُرْۙ اِنَّٓا اَعْتَدْنَا لِلظَّالِم۪ينَ نَاراًۙ اَحَاطَ بِهِمْ سُرَادِقُهَاۜ وَاِنْ يَسْتَغ۪يثُوا يُغَاثُوا بِمَٓاءٍ كَالْمُهْلِ يَشْوِي الْوُجُوهَۜ بِئْسَ الشَّرَابُۜ وَسَٓاءَتْ مُرْتَفَقاً', 'Ve kulil hakku min rabbikum fe men şae fel yu\'min ve men şae fel yekfur inna a\'tedna liz zalimine naren ehata bihim suradikuha, ve in yestegisu yugasu bi main kel muhli yeşvil vucuh, bi\'seş şerab ve saet murtefeka.', 'De ki: \"Hakk[1] Rabb\'inizdendir. O halde dileyen iman etsin,  dileyen küfretsin.\" Kuşkusuz Biz,  zalimler için bir ateş hazırladık. Çadır gibi onları kuşatan. Eğer yardım isterlerse,  erimiş maden gibi yüzleri haşlayan bir su yağdırılır. O ne kötü bir içecektir! Ve ne kötü bir barınma yeridir.', 'وقل الحق من ربكم فمن شا فليومن ومن شا فليكفر انا اعتدنا للظلمين نارا احاط بهم سرادقها وان يستغيثوا يغاثوا بما كالمهل يشوي الوجوه بيس الشراب وسات مرتفقا'),
(2170, 18, 30, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ اِنَّا لَا نُض۪يعُ اَجْرَ مَنْ اَحْسَنَ عَمَلاًۚ', 'İnnellezine amenu ve amilus salihati inna la nudiu ecre men ahsene amela.', 'Gerçek şu ki; iman edip salihatı[1] yapanlara gelince,  Biz,  iyi bir iş yapan hiç kimsenin yaptığını karşılıksız bırakmayız.', 'ان الذين امنوا وعملوا الصلحت انا لا نضيع اجر من احسن عملا'),
(2171, 18, 31, 'اُو۬لٰٓئِكَ لَهُمْ جَنَّاتُ عَدْنٍ تَجْر۪ي مِنْ تَحْتِهِمُ الْاَنْهَارُ يُحَلَّوْنَ ف۪يهَا مِنْ اَسَاوِرَ مِنْ ذَهَبٍ وَيَلْبَسُونَ ثِيَاباً خُضْراً مِنْ سُنْدُسٍ وَاِسْتَبْرَقٍ مُتَّكِـ۪ٔينَ ف۪يهَا عَلَى الْاَرَٓائِكِۜ نِعْمَ الثَّوَابُۜ وَحَسُنَتْ مُرْتَفَقاً۟', 'Ulaike lehum cennatu adnin tecri min tahtihimul enharu yuhallevne fiha min esavire min zehebin ve yelbesune siyaben hudren min sundusin ve istebrekın muttekiine fiha alel eraik, ni\'mes sevab, ve hasunet murtefeka.', 'İşte onlara Adn Cennetleri vardır. Onların içinden nehirler akar. Orada,  altından bileziklerle süslenirler. İnce ve kalın ipekten yeşil elbiseler giyerler. Orada tahtlar üzerine yaslanırlar. Ne güzel bir karşılık ve ne iyi bir ağırlanma yeri!', 'اوليك لهم جنت عدن تجري من تحتهم الانهر يحلون فيها من اساور من ذهب ويلبسون ثيابا خضرا من سندس واستبرق متكين فيها علي الارايك نعم الثواب وحسنت مرتفقا'),
(2172, 18, 32, 'وَاضْرِبْ لَهُمْ مَثَلاً رَجُلَيْنِ جَعَلْنَا لِاَحَدِهِمَا جَنَّتَيْنِ مِنْ اَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعاًۜ', 'Vadrıb lehum meselen raculeyni cealna li ehadihima cenneteyni min a\'nabin ve hafefnahuma bi nahlin ve cealna beynehuma zer\'a.', 'Onlara iki adamın durumunu örnek ver. Bunlardan birine her türlü üzümden iki bahçe yaptık. Ve bu iki bahçenin çevresini hurmalıklarla donattık. Aralarında da ekinlikler bitirdik.', 'واضرب لهم مثلا رجلين جعلنا لاحدهما جنتين من اعنب وحففنهما بنخل وجعلنا بينهما زرعا'),
(2173, 18, 33, 'كِلْتَا الْجَنَّتَيْنِ اٰتَتْ اُكُلَهَا وَلَمْ تَظْلِمْ مِنْهُ شَيْـٔاًۙ وَفَجَّرْنَا خِلَالَهُمَا نَهَراًۙ', 'Kiltel cenneteyni atet ukuleha ve lem tazlim minhu şey\'en ve feccerna hılalehuma nehera.', 'İki bahçenin ikisi de hiçbir şey eksik bırakmadan meyvelerini verdi. Ve aralarında bir nehir akıttık.', 'كلتا الجنتين اتت اكلها ولم تظلم منه شيا وفجرنا خللهما نهرا'),
(2174, 18, 34, 'وَكَانَ لَهُ ثَمَرٌۚ فَقَالَ لِصَاحِبِه۪ وَهُوَ يُحَاوِرُهُٓ اَنَا۬ اَكْثَرُ مِنْكَ مَالاً وَاَعَزُّ نَفَراً', 'Ve kane lehu semer, fe kale li sahıbihi ve huve yuhaviruhu ene ekseru minke malen ve eazzu nefera.', 'Ve onun serveti oldu. Arkadaşı ile konuşurken: \"Ben malca senden daha zenginim,  insan sayısınca da senden daha güçlüyüm.\" dedi.', 'وكان له ثمر فقال لصحبه وهو يحاوره انا اكثر منك مالا واعز نفرا'),
(2175, 18, 35, 'وَدَخَلَ جَنَّتَهُ وَهُوَ ظَالِمٌ لِنَفْسِه۪ۚ قَالَ مَٓا اَظُنُّ اَنْ تَب۪يدَ هٰذِه۪ٓ اَبَداًۙ', 'Ve dehale cennetehu ve huve zalimun li nefsih, kale ma ezunnu en tebide hazihi ebeda.', 'Ve o kendisine yazık ederek bahçesine girdi: \"Ben,  bunun hiçbir zaman yok olacağını sanmıyorum.\" dedi.', 'ودخل جنته وهو ظالم لنفسه قال ما اظن ان تبيد هذه ابدا'),
(2176, 18, 36, 'وَمَٓا اَظُنُّ السَّاعَةَ قَٓائِمَةًۙ وَلَئِنْ رُدِدْتُ اِلٰى رَبّ۪ي لَاَجِدَنَّ خَيْراً مِنْهَا مُنْقَلَباً', 'Ve ma ezunnus saate kaimeten ve le in rudidtu ila rabbi le ecidenne hayren minha munkaleba.', '\"Kıyametin kopacağını sanmıyorum. Eğer böyle bir şey olur da Rabb\'ime döndürülürsem,  mutlaka orada bundan daha hayırlısını bulurum.\"', 'وما اظن الساعة قايمة ولين رددت الي ربي لاجدن خيرا منها منقلبا'),
(2177, 18, 37, 'قَالَ لَهُ صَاحِبُهُ وَهُوَ يُحَاوِرُهُٓ  اَكَفَرْتَ بِالَّذ۪ي خَلَقَكَ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ سَوّٰيكَ رَجُلاًۜ', 'Kale lehu sahıbuhu ve huve yuhaviruhu e keferte billezi halakake min turabin summe min nutfetin summe sevvake racula.', 'Tartışmaya girdiği arkadaşı ona: \"Seni topraktan,  sonra bir nutfeden yaratan,  sonra da seni insan şekline sokana nankörlük mü ediyorsun?\"', 'قال له صاحبه وهو يحاوره اكفرت بالذي خلقك من تراب ثم من نطفة ثم سويك رجلا'),
(2178, 18, 38, 'لٰكِنَّا۬ هُوَ اللّٰهُ رَبّ۪ي وَلَٓا اُشْرِكُ بِرَبّ۪ٓي اَحَداً', 'Lakinne huvallahu rabbi ve la uşriku bi rabbi ehada.', '\"Oysa benim Rabb\'im Allah\'tır. Ve ben Rabb\'ime kimseyi ortak koşmam.\"', 'لكنا هو الله ربي ولا اشرك بربي احدا'),
(2179, 18, 39, 'وَلَوْلَٓا اِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَٓاءَ اللّٰهُۙ لَا قُوَّةَ اِلَّا بِاللّٰهِۚ اِنْ تَرَنِ اَنَا۬ اَقَلَّ مِنْكَ مَالاً وَوَلَداًۚ', 'Ve lev la iz dehalte cenneteke kulte ma şaallahu la kuvvete illa billah, in tereni ene ekalle minke malen ve veleda.', '\"Her ne kadar beni mal-mülk ve evlat bakımından eksik görüyorsan da bahçene girdiğin zaman: \"Allah ne dilerse o olur,  Allah\'tan başka hiçbir güç yoktur,  deseydin ya!\"', 'ولولا اذ دخلت جنتك قلت ما شا الله لا قوة الا بالله ان ترن انا اقل منك مالا وولدا'),
(2180, 18, 40, 'فَعَسٰى رَبّ۪ٓي اَنْ يُؤْتِيَنِ خَيْراً مِنْ جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَاناً مِنَ السَّمَٓاءِ فَتُصْبِحَ صَع۪يداً زَلَقاًۙ', 'Fe asa rabbi en yu\'tiyeni hayran min cennetike ve yursile aleyha husbanen mines semai fe tusbiha saiden zeleka.', '\"Belki Rabb\'im,  bana senin bahçenden daha hayırlısını verir. Ve seninkinin üzerine de gökten felaketler gönderir de verimsiz,  kupkuru bir toprak olur.\"', 'فعسي ربي ان يوتين خيرا من جنتك ويرسل عليها حسبانا من السما فتصبح صعيدا زلقا'),
(2181, 18, 41, 'اَوْ يُصْبِحَ مَٓاؤُ۬هَا غَوْراً فَلَنْ تَسْتَط۪يعَ لَهُ طَلَباً', 'Ev yusbiha mauha gavren fe len testetia lehu taleba.', '\"Veya onun suyu yerin dibine çekilir de artık onu çıkarmaya asla gücün yetmez.\"', 'او يصبح ماوها غورا فلن تستطيع له طلبا'),
(2182, 18, 42, 'وَاُح۪يطَ بِثَمَرِه۪ فَاَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلٰى مَٓا اَنْفَقَ ف۪يهَا وَهِيَ خَاوِيَةٌ عَلٰى عُرُوشِهَا وَيَقُولُ يَا لَيْتَن۪ي لَمْ اُشْرِكْ بِرَبّ۪ٓي اَحَداً', 'Ve uhita bi semerihi fe asbeha yukallibu keffeyhi ala ma enfeka fiha ve hiye haviyetun ala uruşiha ve yekulu ya leyteni lem uşrik bi rabbi ehada.', 'Onun ürünleri kuşatılıp bitirildi. Ve çardakları üzerine yıkılmıştı. Yaptığı harcamalara üzülerek ellerini ovuştururken,  \"Keşke ben Rabb\'ime hiçbir şeyi ortak koşmasaydım.\" diyordu.', 'واحيط بثمره فاصبح يقلب كفيه علي ما انفق فيها وهي خاوية علي عروشها ويقول يليتني لم اشرك بربي احدا'),
(2183, 18, 43, 'وَلَمْ تَكُنْ لَهُ فِئَةٌ يَنْصُرُونَهُ مِنْ دُونِ اللّٰهِ وَمَا كَانَ مُنْتَصِراًۜ', 'Ve lem tekun lehu fietun yansurunehu min dunillahi ve ma kane muntesira.', 'Allah\'tan başka kendisine yardım edecek kimseler olmadı. Ve kendi kendisini de koruyamadı.', 'ولم تكن له فية ينصرونه من دون الله وما كان منتصرا'),
(2184, 18, 44, 'هُنَالِكَ الْوَلَايَةُ لِلّٰهِ الْحَقِّۜ هُوَ خَيْرٌ ثَوَاباً وَخَيْرٌ عُقْباً۟', 'Hunalikel velayetu lillahil hakk, huve hayrun sevaben ve hayrun ukba.', 'İşte bu durumda velilik,  gerçek olarak yalnızca Allah\'a aittir. O,  ödüllendirme bakımından da en hayırlı olandır. Sonuç bakımından da en hayırlı olandır.', 'هنالك الولية لله الحق هو خير ثوابا وخير عقبا'),
(2185, 18, 45, 'وَاضْرِبْ لَهُمْ مَثَلَ الْحَيٰوةِ الدُّنْيَا كَمَٓاءٍ اَنْزَلْنَاهُ مِنَ السَّمَٓاءِ فَاخْتَلَطَ بِه۪ نَبَاتُ الْاَرْضِ فَاَصْبَحَ هَش۪يماً تَذْرُوهُ الرِّيَاحُۜ وَكَانَ اللّٰهُ عَلٰى كُلِّ شَيْءٍ مُقْتَدِراً', 'Vadrıb lehum meselel hayatid dunya ke main enzelnahu mines semai fahteleta bihi nebatul ardı fe asbeha heşimen tezruhur riyah, ve kanallahu ala kulli şey\'in muktedira.', 'Dünya hayatının neye benzediğine dair şu örneği ver: o,  gökten indirdiğimiz su ile yeryüzünde yeşeren ve daha sonra çer çöp olup rüzgarla sağa sola savrulan bitki gibidir. Allah\'ın Her Şeye Gücü Yeter.', 'واضرب لهم مثل الحيوة الدنيا كما انزلنه من السما فاختلط به نبات الارض فاصبح هشيما تذروه الريح وكان الله علي كل شي مقتدرا'),
(2186, 18, 46, 'اَلْمَالُ وَالْبَنُونَ ز۪ينَةُ الْحَيٰوةِ الدُّنْيَاۚ وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِنْدَ رَبِّكَ ثَوَاباً وَخَيْرٌ اَمَلاً', 'El malu vel benune zinetul hayatid dunya, vel bakıyatus salihatu hayrun inde rabbike sevaben ve hayrun emela.', 'Mal ve çocuklar,  dünya hayatının süsüdür. Kalıcı olan iyi işler ise Rabb\'inin yanında daha değerlidir. Ümit bağlama yönünden de daha değerlidir.', 'المال والبنون زينة الحيوة الدنيا والبقيت الصلحت خير عند ربك ثوابا وخير املا'),
(2187, 18, 47, 'وَيَوْمَ نُسَيِّرُ الْجِبَالَ وَتَرَى الْاَرْضَ بَارِزَةًۙ وَحَشَرْنَاهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ اَحَداًۚ', 'Ve yevme nuseyyirul cibale ve terel arda barizeten ve haşernahum fe lem nugadir minhum ehada.', 'O gün dağları yürüteceğiz. Ve yeryüzünü dümdüz görürsün. Hiç kimseyi bırakmaksızın onların tamamını[1] mahşerde toplarız.', 'ويوم نسير الجبال وتري الارض بارزة وحشرنهم فلم نغادر منهم احدا'),
(2188, 18, 48, 'وَعُرِضُوا عَلٰى رَبِّكَ صَفاًّۜ لَقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ اَوَّلَ مَرَّةٍۘ بَلْ زَعَمْتُمْ اَلَّنْ نَجْعَلَ لَكُمْ مَوْعِداً', 'Ve uridu ala rabbike saffa, lekad ci\'tumuna kema halaknakum evvele merreh, bel zeamtum ellen nec\'ale lekum mev\'ıda.', 'Saf saf Rabb\'ine arz olunacaklar. \"Ant olsun ki siz,  ilk yarattığımız gibi Bize geldiniz. Hayır,  size yaptığımız uyarıları,  gerçekleştirmeyeceğimizi sanıyordunuz.\"', 'وعرضوا علي ربك صفا لقد جيتمونا كما خلقنكم اول مرة بل زعمتم الن نجعل لكم موعدا'),
(2189, 18, 49, 'وَوُضِعَ الْكِتَابُ فَتَرَى الْمُجْرِم۪ينَ مُشْفِق۪ينَ مِمَّا ف۪يهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَالِ هٰذَا الْكِتَابِ لَا يُغَادِرُ صَغ۪يرَةً وَلَا كَب۪يرَةً اِلَّٓا اَحْصٰيهَاۚ وَوَجَدُوا مَا عَمِلُوا حَاضِراًۜ وَلَا يَظْلِمُ رَبُّكَ اَحَداً۟', 'Ve vudıal kitabu fe terel mucrimine muşfikine mimma fihi ve yekulune ya veyletena mali hazel kitabi la yugadiru sagireten ve la kebireten illa ahsaha, ve vecedu ma amilu hadıra, ve la yazlimu rabbuke ehada.', 'Ve kitap ortaya kondu. O zaman suçluların onda olanlardan ürperdiklerini görürsün. \"Eyvah bize! Bu nasıl bir kitap ki,  büyük-küçük saymadık hiçbir şey bırakmamış.\" derler. Yaptıkları her şeyi hazır buldular. Senin Rabb\'in,  hiç kimseye haksızlık yapmaz.', 'ووضع الكتب فتري المجرمين مشفقين مما فيه ويقولون يويلتنا مال هذا الكتب لا يغادر صغيرة ولا كبيرة الا احصيها ووجدوا ما عملوا حاضرا ولا يظلم ربك احدا'),
(2190, 18, 50, 'وَاِذْ قُلْنَا لِلْمَلٰٓئِكَةِ اسْجُدُوا لِاٰدَمَ فَسَجَدُٓوا اِلَّٓا اِبْل۪يسَۜ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ اَمْرِ رَبِّه۪ۜ  اَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُٓ اَوْلِيَٓاءَ مِنْ دُون۪ي وَهُمْ لَكُمْ عَدُوٌّۜ بِئْسَ لِلظَّالِم۪ينَ بَدَلاً', 'Ve iz kulna lil melaiketiscudu li ademe fe secedu illa iblis, kane minel cinni fe feseka an emri rabbih, e fe tettehızunehu ve zurriyyetehu evliyae min duni ve hum lekum aduvv, bi\'se liz zalimine bedela.', 'Hani! Biz,  meleklere,  \"Âdem\'e secde edin.[1]\" demiştik. İblis hariç hepsi secde etmişti. O cinlerdendi. Böylece Rabb\'inin sözünden dışarı çıktı. Benim yanım sıra,  onu ve soyunu evliya mı ediniyorsunuz? Oysa onlar sizin düşmanınızdır. Zalimler için ne kötü bir tercihtir bu!', 'واذ قلنا للمليكة اسجدوا لادم فسجدوا الا ابليس كان من الجن ففسق عن امر ربه افتتخذونه وذريته اوليا من دوني وهم لكم عدو بيس للظلمين بدلا'),
(2191, 18, 51, 'مَٓا اَشْهَدْتُهُمْ خَلْقَ السَّمٰوَاتِ وَالْاَرْضِ وَلَا خَلْقَ اَنْفُسِهِمْۖ وَمَا كُنْتُ مُتَّخِذَ الْمُضِلّ۪ينَ عَضُداً', 'Ma eşhedtuhum halkas semavati vel ardı ve la halka enfusihim ve ma kuntu muttehızel mudılline aduda.', 'Ben onları[1] göklerin ve yeryüzünün yaratılışına ve kendilerinin yaratılışına tanık tutmadım[2]. Ve Ben saptıranları yardımcı edinmedim.', 'ما اشهدتهم خلق السموت والارض ولا خلق انفسهم وما كنت متخذ المضلين عضدا'),
(2192, 18, 52, 'وَيَوْمَ يَقُولُ نَادُوا شُرَكَٓاءِيَ الَّذ۪ينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَج۪يبُوا لَهُمْ وَجَعَلْنَا بَيْنَهُمْ مَوْبِقاً', 'Ve yevme yekulu nadu şurekaiyellezine zeamtum fe deavhum fe lem yestecibu lehum ve cealna beynehum mevbika.', 'O gün Allah,  \"Benim ortaklarım olarak sandıklarınızı haydi çağırın.\" der. Sonra onları çağırdılar fakat onlar,  kendilerine cevap vermedi. Ve Biz onların aralarına aşılmaz bir engel koyduk.', 'ويوم يقول نادوا شركاي الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا'),
(2193, 18, 53, 'وَرَاَ الْمُجْرِمُونَ النَّارَ فَظَنُّٓوا اَنَّهُمْ مُوَاقِعُوهَا وَلَمْ يَجِدُوا عَنْهَا مَصْرِفاً۟', 'Ve reel mucrimunen nare fe zannu ennehum muvakıuha ve lem yecidu anha masrifa.', 'Mücrimler[1] ateşi görünce,  ona düşeceklerini anlarlar. Ancak ondan bir kaçış yolu bulamazlar.', 'ورا المجرمون النار فظنوا انهم مواقعوها ولم يجدوا عنها مصرفا'),
(2194, 18, 54, 'وَلَقَدْ صَرَّفْنَا ف۪ي هٰذَا الْقُرْاٰنِ لِلنَّاسِ مِنْ كُلِّ مَثَلٍۜ وَكَانَ الْاِنْسَانُ اَكْثَرَ شَيْءٍ جَدَلاً', 'Ve lekad sarrafna fi hazel kur\'ani lin nasi min kulli mesel, ve kanel insanu eksere şey\'in cedela.', 'Ant olsun ki Biz,  bu Kur\'an\'da her türlü örneği farklı farklı açıklamalarla verdik. Ne var ki insan bilir bilmez her şeye karşı çıkmayı çok sevmektedir.', 'ولقد صرفنا في هذا القران للناس من كل مثل وكان الانسن اكثر شي جدلا'),
(2195, 18, 55, 'وَمَا مَنَعَ النَّاسَ اَنْ يُؤْمِنُٓوا اِذْ جَٓاءَهُمُ الْهُدٰى وَيَسْتَغْفِرُوا رَبَّهُمْ اِلَّٓا اَنْ تَأْتِيَهُمْ سُنَّةُ الْاَوَّل۪ينَ اَوْ يَأْتِيَهُمُ الْعَذَابُ قُبُلاً', 'Ve ma menean nase en yu\'minu iz cae humul huda ve yestagfiru rabbehum illa en te\'tiyehum sunnetul evveline ev ye\'tiyehumul azabu kubula.', 'Kendilerine doğru yolu gösterici geldiği zaman; insanları,  Rabb\'lerinin bağışlamasını dilemekten ve inanmaktan alıkoyan şey,  kendilerinden öncekilerinin başına gelenlerin,  kendi başlarına da gelmesini ya da azapla karşı karşıya gelmeyi beklemeleridir.', 'وما منع الناس ان يومنوا اذ جاهم الهدي ويستغفروا ربهم الا ان تاتيهم سنة الاولين او ياتيهم العذاب قبلا'),
(2196, 18, 56, 'وَمَا نُرْسِلُ الْمُرْسَل۪ينَ اِلَّا مُبَشِّر۪ينَ وَمُنْذِر۪ينَۚ وَيُجَادِلُ الَّذ۪ينَ كَفَرُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ وَاتَّخَذُٓوا اٰيَات۪ي وَمَٓا اُنْذِرُوا هُزُواً', 'Ve ma nursilul murseline illa mubeşşirine ve munzirin, ve yucadilullezine keferu bil batılı li yudhıdu bihil hakka vettehazu ayati ve ma unziru huzuva.', 'Biz,  resulleri ancak haberdar ediciler ve uyarıcılar olarak göndeririz[1]. Kafirler[2] ise Hakk\'ı Batıl ile ortadan kaldırmak için mücadele ediyorlar. Ve onlar,  ayetlerimizi ve uyarıldıkları şeyleri alaya alıyorlar.', 'وما نرسل المرسلين الا مبشرين ومنذرين ويجدل الذين كفروا بالبطل ليدحضوا به الحق واتخذوا ايتي وما انذروا هزوا'),
(2197, 18, 57, 'وَمَنْ اَظْلَمُ مِمَّنْ ذُكِّرَ بِاٰيَاتِ رَبِّه۪ فَاَعْرَضَ عَنْهَا وَنَسِيَ مَا قَدَّمَتْ يَدَاهُۜ اِنَّا جَعَلْنَا عَلٰى قُلُوبِهِمْ اَكِنَّةً اَنْ يَفْقَهُوهُ وَف۪ٓي اٰذَانِهِمْ وَقْراًۜ وَاِنْ تَدْعُهُمْ اِلَى الْهُدٰى فَلَنْ يَهْتَدُٓوا اِذاً اَبَداً', 'Ve men azlemu mimmen zukkire bi ayati rabbihi fe a\'rada anha ve nesiye ma kaddemet yedah, inna cealna ala kulubihim ekinneten en yefkahuhu ve fi azanihim vakra ve in ted\'uhum ilel huda fe len yehtedu izen ebeda.', 'Rabb\'inin ayetleriyle öğüt verildiği zaman onu dikkate almayan ve yapıp ettiklerini önemsemeyen kimseden daha haksız kim vardır? Biz,  böylelerinin kalplerinin üzerine,  gerçeği düşünüp kavramayı engelleyen bir örtü,  kulaklarına da ağırlık koyduk. Sen onları doğruya yöneltmeye çalışsan da artık asla doğru yola dönmezler.', 'ومن اظلم ممن ذكر بايت ربه فاعرض عنها ونسي ما قدمت يداه انا جعلنا علي قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا وان تدعهم الي الهدي فلن يهتدوا اذا ابدا'),
(2198, 18, 58, 'وَرَبُّكَ الْغَفُورُ ذُوالرَّحْمَةِۜ لَوْ يُؤَاخِذُهُمْ بِمَا كَسَبُوا لَعَجَّلَ لَهُمُ الْعَذَابَۜ بَلْ لَهُمْ مَوْعِدٌ لَنْ يَجِدُوا مِنْ دُونِه۪ مَوْئِلاً', 'Ve rabbukel gafuru zur rahmeh, lev yuahızuhum bi ma kesebu le accele lehumul azab, bel lehum mev\'ıdun len yecidu min dunihi mev\'ila.', 'Bununla beraber,  rahmet sahibi Rabb\'in çok bağışlayıcıdır. Eğer O,  yaptıkları yüzünden onları hemen hesaba çekseydi,  kesinlikle onlara azabı hemen verirdi. Aksine onlar için belirlenmiş bir zaman vardır. Onlar,  O\'ndan başka sığınılacak bir yer asla bulamazlar.', 'وربك الغفور ذو الرحمة لو يواخذهم بما كسبوا لعجل لهم العذاب بل لهم موعد لن يجدوا من دونه مويلا'),
(2199, 18, 59, 'وَتِلْكَ الْقُرٰٓى اَهْلَكْنَاهُمْ لَمَّا ظَلَمُوا وَجَعَلْنَا لِمَهْلِكِهِمْ مَوْعِداً۟', 'Ve tilkel kura ehleknahum lemma zalemu ve cealna li mehlikihim mev\'ıda.', 'İşte zulmettikleri zaman yok ettiğimiz beldeler. Biz onların yok edilmeleri için de bir zaman belirlemiştik.', 'وتلك القري اهلكنهم لما ظلموا وجعلنا لمهلكهم موعدا'),
(2200, 18, 60, 'وَاِذْ قَالَ مُوسٰى لِفَتٰيهُ لَٓا اَبْرَحُ حَتّٰٓى اَبْلُغَ مَجْمَعَ الْبَحْرَيْنِ اَوْ اَمْضِيَ حُقُباً', 'Ve iz kale musa li fetahu la ebrehu hatta ebluga mecmeal bahreyni ev emdıye hukuba.', 'Bir zamanlar Musa,  genç arkadaşına: \"İki denizin birleştiği yere ulaşıncaya kadar yoluma devam edeceğim veya uzun zaman gitmeye devam edeceğim.\" demişti.', 'واذ قال موسي لفتيه لا ابرح حتي ابلغ مجمع البحرين او امضي حقبا'),
(2201, 18, 61, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَاتَّخَذَ سَب۪يلَهُ فِي الْبَحْرِ سَرَباً', 'Fe lemma belega mecmea beynihima nesiya hutehuma fettehaze sebilehu fil bahri sereba.', 'İkisinin arasının[1] birleştiği yere ulaştıklarında hutlarını[2] unuttular. O da denizin derinliklerine doğru kendi yolunu tuttu.', 'فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله في البحر سربا'),
(2202, 18, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتٰيهُ اٰتِنَا غَدَٓاءَنَاۘ لَقَدْ لَق۪ينَا مِنْ سَفَرِنَا هٰذَا نَصَباً', 'Fe lemma caveza kale li fetahu atina gadaena lekad lekina min seferina haza nasaba.', 'Epey bir mesafe aldıktan sonra,  genç arkadaşına,  \"Yolculuğumuz nedeniyle iyice yorulduk,  haydi sabah yemeğimizi getir.\" dedi.', 'فلما جاوزا قال لفتيه اتنا غدانا لقد لقينا من سفرنا هذا نصبا'),
(2203, 18, 63, 'قَالَ اَرَاَيْتَ اِذْ اَوَيْنَٓا اِلَى الصَّخْرَةِ فَاِنّ۪ي نَس۪يتُ الْحُوتَۘ وَمَٓا اَنْسَان۪يهُ اِلَّا الشَّيْطَانُ اَنْ اَذْكُرَهُۚ وَاتَّخَذَ سَب۪يلَهُ فِي الْبَحْرِۗ عَجَباً', 'Kale eraeyte iz eveyna ilas sahrati fe inni nesitul hut, ve ma ensanihu illeş şeytanu en ezkureh, vettehaze sebilehu fil bahri aceba.', '\"Tüh! Şu işe bak! O kayanın yanında durduğumuzda ben hutu[1] unuttum; şeytan hatırlamama engel oldu. O da şaşılacak bir şekilde denizde kendisine yol tuttu.\"', 'قال اريت اذ اوينا الي الصخرة فاني نسيت الحوت وما انسينيه الا الشيطن ان اذكره واتخذ سبيله في البحر عجبا'),
(2204, 18, 64, 'قَالَ ذٰلِكَ مَا كُنَّا نَبْغِۗ فَارْتَدَّا عَلٰٓى اٰثَارِهِمَا قَصَصاًۙ', 'Kale zalike ma kunna nebgı fertedda ala asarihima kasasa.', '\"Hemen oraya dönmeliyiz\" dedi. Ve izlerini takip ederek geri döndüler.', 'قال ذلك ما كنا نبغ فارتدا علي اثارهما قصصا'),
(2205, 18, 65, 'فَوَجَدَا عَبْداً مِنْ عِبَادِنَٓا اٰتَيْنَاهُ رَحْمَةً مِنْ عِنْدِنَا وَعَلَّمْنَاهُ مِنْ لَدُنَّا عِلْماً', 'Fe veceda abden min ibadina ateynahu rahmeten min indina ve allemnahu min ledunna ilma.', 'Derken katımızdan,  kendisine bir rahmet verdiğimiz ve tarafımızdan[1] bir ilim öğrettiğimiz[1] Bizim kullarımızdan bir kul[2] buldular.', 'فوجدا عبدا من عبادنا اتينه رحمة من عندنا وعلمنه من لدنا علما'),
(2206, 18, 66, 'قَالَ لَهُ مُوسٰى هَلْ اَتَّبِعُكَ عَلٰٓى اَنْ تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْداً', 'Kale lehu musa hel ettebiuke ala en tuallimeni mimma ullimte ruşda.', 'Musa ona: \"Sana öğretilen doğru yoldan gitme bilgisini bana da öğretmen için,  sana tabi olabilir miyim?\" dedi.', 'قال له موسي هل اتبعك علي ان تعلمن مما علمت رشدا'),
(2207, 18, 67, 'قَالَ اِنَّكَ لَنْ تَسْتَط۪يعَ مَعِيَ صَبْراً', 'Kale inneke len testetia maiye sabra.', '\"Sen,  benimle beraber olmada sabretmeye asla güç yetiremezsin.\"', 'قال انك لن تستطيع معي صبرا'),
(2208, 18, 68, 'وَكَيْفَ تَصْبِرُ عَلٰى مَا لَمْ تُحِطْ بِه۪ خُبْراً', 'Ve keyfe tesbiru ala ma lem tuhıt bihi hubra.', '\"Haberdar edilerek iç yüzünü kavrayamadığın şeye nasıl sabredebilirsin?\"', 'وكيف تصبر علي ما لم تحط به خبرا'),
(2209, 18, 69, 'قَالَ سَتَجِدُن۪ٓي اِنْ شَٓاءَ اللّٰهُ صَابِراً وَلَٓا اَعْص۪ي لَكَ اَمْراً', 'Kale se teciduni inşaallahu sabiren ve la a\'si leke emra.', '\"İnşaallah beni sabırlı bulacaksın ve senin hiçbir işine karşı çıkmayacağım.\" dedi.', 'قال ستجدني ان شا الله صابرا ولا اعصي لك امرا');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2210, 18, 70, 'قَالَ فَاِنِ اتَّبَعْتَن۪ي فَلَا تَسْـَٔلْن۪ي عَنْ شَيْءٍ حَتّٰٓى اُحْدِثَ لَكَ مِنْهُ ذِكْراً۟', 'Kale fe initteba\'teni fe la tes\'elni an şey\'in hatta uhdise leke minhu zikra.', '\"O halde,  eğer bana uyacaksan,  hakkında bir açıklama yapıncaya kadar bana hiçbir şey hakkında soru sorma.\" dedi.', 'قال فان اتبعتني فلا تسلني عن شي حتي احدث لك منه ذكرا'),
(2211, 18, 71, 'فَانْطَلَقَا۠ حَتّٰٓى اِذَا رَكِبَا فِي السَّف۪ينَةِ خَرَقَهَاۜ قَالَ اَخَرَقْتَهَا لِتُغْرِقَ اَهْلَهَاۚ لَقَدْ جِئْتَ شَيْـٔاً اِمْراً', 'Fentalaka, hatta iza rakiba fis sefineti harakaha kale e harakteha li tugrika ehleha, lekad ci\'te şey\'en imra.', 'Bunun üzerine yürüdüler. Nihayet bir gemiye bindiklerinde onu deldi. Musa: \"İçindekilerini boğmak için mi onu deldin? Gerçekten sen şaşılacak bir iş yaptın.\" dedi.', 'فانطلقا حتي اذا ركبا في السفينة خرقها قال اخرقتها لتغرق اهلها لقد جيت شيا امرا'),
(2212, 18, 72, 'قَالَ اَلَمْ اَقُلْ اِنَّكَ لَنْ تَسْتَط۪يعَ مَعِيَ صَبْراً', 'Kale e lem ekul inneke len testetia maiye sabra.', '\"Gerçek şu ki sen benimle birlikte olmada sabretmeye asla güç yetiremezsin.\" dememiş miydim?', 'قال الم اقل انك لن تستطيع معي صبرا'),
(2213, 18, 73, 'قَالَ لَا تُؤَاخِذْن۪ي بِمَا نَس۪يتُ وَلَا تُرْهِقْن۪ي مِنْ اَمْر۪ي عُسْراً', 'Kale la tuahızni bima nesitu ve la turhıkni min emri usra.', '\"Unutmuş olmamdan dolayı beni kınama ve bu işimden dolayı güçlük çıkarma.\" dedi.', 'قال لا تواخذني بما نسيت ولا ترهقني من امري عسرا'),
(2214, 18, 74, 'فَانْطَلَقَا۠ حَتّٰٓى اِذَا لَقِيَا غُلَاماً فَقَتَلَهُۙ قَالَ اَقَتَلْتَ نَفْساً زَكِيَّةً بِغَيْرِ نَفْسٍۜ لَقَدْ جِئْتَ شَيْـٔاً نُكْراً', 'Fentaleka, hatta iza lekıya gulamen fe katelehu kale e katelte nefsen zekiyyeten bi gayri nefs, lekad ci\'te şey\'en nukra.', 'Tekrar yola koyuldular. Nihayet bir delikanlıya[1] rastladılar. Onu öldürdü. \"Bir cana karşılık olmaksızın zekiyye[2] bir canı öldürdün mü? Gerçekten dehşet verici bir şey yaptın!\"', 'فانطلقا حتي اذا لقيا غلما فقتله قال اقتلت نفسا زكية بغير نفس لقد جيت شيا نكرا'),
(2215, 18, 75, 'قَالَ اَلَمْ اَقُلْ لَكَ اِنَّكَ لَنْ تَسْتَط۪يعَ مَعِيَ صَبْراً', 'Kale e lem ekul leke inneke len testetia maıye sabra.', 'Sana,  \"Sen,  kesinlikle benimle birlikte olmaya sabretmeye asla güç yetiremezsin,  demedim mi?\" dedi.', 'قال الم اقل لك انك لن تستطيع معي صبرا'),
(2216, 18, 76, 'قَالَ اِنْ سَاَلْتُكَ عَنْ شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْن۪يۚ قَدْ بَلَغْتَ مِنْ لَدُنّ۪ي عُذْراً', 'Kale in seeltuke an şey\'in ba\'deha fe la tusahıbni, kad belagte min ledunni uzra.', '\"Eğer bir daha sana bir şey sorarsam,  artık benimle arkadaşlık etmezsin! Tarafımdan[1] yeterince özür dilemede bulundum.\"', 'قال ان سالتك عن شي بعدها فلا تصحبني قد بلغت من لدني عذرا'),
(2217, 18, 77, 'فَانْطَلَقَا۠ حَتّٰٓى اِذَٓا اَتَيَٓا اَهْلَ قَرْيَةٍۨ اسْتَطْعَمَٓا اَهْلَهَا فَاَبَوْا اَنْ يُضَيِّفُوهُمَا فَوَجَدَا ف۪يهَا جِدَاراً يُر۪يدُ اَنْ يَنْقَضَّ فَاَقَامَهُۜ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ اَجْراً', 'Fentaleka, hatta iza eteya ehle karyetin istat\'ama ehleha fe ebev en yudayyifuhuma fe veceda fiha cidaren yuridu en yenkadda fe ekameh, kale lev şi\'te lettehazte aleyhi ecra.', 'Yeniden yola koyuldular. Bir kasabaya varınca,  karşılaştıkları halktan yiyecek istediler. Ne var ki onlar,  kendilerini misafir etmekten kaçındılar. Derken orada yıkılmak üzere olan bir duvar buldular. Hemen onu düzeltti. Musa: \"Eğer isteseydin elbette bunun için bir ücret alırdın.\" dedi.', 'فانطلقا حتي اذا اتيا اهل قرية استطعما اهلها فابوا ان يضيفوهما فوجدا فيها جدارا يريد ان ينقض فاقامه قال لو شيت لتخذت عليه اجرا'),
(2218, 18, 78, 'قَالَ هٰذَا فِرَاقُ بَيْن۪ي وَبَيْنِكَۚ سَاُنَبِّئُكَ بِتَأْو۪يلِ مَا لَمْ تَسْتَطِـعْ عَلَيْهِ صَبْراً', 'Kale haza firaku beyni ve beynik, se unebbiuke bi te\'vili ma lem testetı\' aleyhi sabra.', '\"İşte bu yollarımızın ayrılma vaktidir. Sabırlı olmaya güç yetiremediğin şeylerin içyüzünü sana açıklayacağım.\" dedi.', 'قال هذا فراق بيني وبينك سانبيك بتاويل ما لم تستطع عليه صبرا'),
(2219, 18, 79, 'اَمَّا السَّف۪ينَةُ فَكَانَتْ لِمَسَاك۪ينَ يَعْمَلُونَ فِي الْبَحْرِ فَاَرَدْتُ اَنْ اَع۪يبَهَا وَكَانَ وَرَٓاءَهُمْ مَلِكٌ يَأْخُذُ كُلَّ سَف۪ينَةٍ غَصْباً', 'Emmes sefinetu fe kanet li mesakine ya\'melune fil bahri fe eradtu en eibeha ve kane veraehum melikun ye\'huzu kulle sefinetin gasba.', '\"O gemi,  geçimini denizden sağlayan yoksul kimselere aitti. Gemiyi hasarlı göstermek istedim,  zira onların ilerisinde bütün gemileri gasp eden bir hükümdar vardı.\"', 'اما السفينة فكانت لمسكين يعملون في البحر فاردت ان اعيبها وكان وراهم ملك ياخذ كل سفينة غصبا'),
(2220, 18, 80, 'وَاَمَّا الْغُلَامُ فَكَانَ اَبَوَاهُ مُؤْمِنَيْنِ فَخَش۪ينَٓا اَنْ يُرْهِقَهُمَا طُغْيَاناً وَكُفْراًۚ', 'Ve emmel gulamu fe kane ebevahu mu\'mineyni fe haşina en yurhikahuma tugyanen ve kufra.', '\"Delikanlıya gelince,  anne ve babası Mü\'min kimselerdi. Onları azgınlığa ve Küfre sürüklemesine rızamız olmadı.\"[1]', 'واما الغلم فكان ابواه مومنين فخشينا ان يرهقهما طغينا وكفرا'),
(2221, 18, 81, 'فَاَرَدْنَٓا اَنْ يُبْدِلَهُمَا رَبُّهُمَا خَيْراً مِنْهُ زَكٰوةً وَاَقْرَبَ رُحْماً', 'Fe eredna en yubdilehuma rabbuhuma hayren minhu zekaten ve akrebe ruhma.', '\"Böylece onların Rabb\'lerinin,  onu,  ondan daha hayırlı,  daha zekat[1] ve merhamete daha yakın olanla değiştirmesini istedik.\"', 'فاردنا ان يبدلهما ربهما خيرا منه زكوة واقرب رحما'),
(2222, 18, 82, 'وَاَمَّا الْجِدَارُ فَكَانَ لِغُلَامَيْنِ يَت۪يمَيْنِ فِي الْمَد۪ينَةِ وَكَانَ تَحْتَهُ كَنْزٌ لَهُمَا وَكَانَ اَبُوهُمَا صَالِحاًۚ فَاَرَادَ رَبُّكَ اَنْ يَبْلُغَٓا اَشُدَّهُمَا وَيَسْتَخْرِجَا كَنْزَهُمَاۗ رَحْمَةً مِنْ رَبِّكَۚ وَمَا فَعَلْتُهُ عَنْ اَمْر۪يۜ ذٰلِكَ تَأْو۪يلُ مَا لَمْ تَسْطِـعْ عَلَيْهِ صَبْراًۜ۟', 'Ve emmel cidaru fe kane li gulameyni yetimeyni fil medineti ve kane tahtehu kenzun lehuma ve kane ebuhuma saliha, fe erade rabbuke en yebluga eşuddehuma ve yestahrica kenzehuma rahmeten min rabbik ve ma fealtuhu an emri, zalike te\'vilu ma lem testı\' aleyhi sabra.', '\"Duvar ise o şehirde iki yetim gence aitti. Ve onun altında,  onlara ait bir servet vardı. Babaları iyi bir kimseydi. İşte onun için Rabb\'in,  onların erginlik dönemine erişmesini ve -Rabb\'lerinden bir rahmet olarak- serveti çıkarmalarını istedi. Ve ben onu kendiliğimden bir iş olarak yapmadım. İşte senin sabretmeye güç yetiremediğin şeylerin açıklaması budur.\"[1]', 'واما الجدار فكان لغلمين يتيمين في المدينة وكان تحته كنز لهما وكان ابوهما صلحا فاراد ربك ان يبلغا اشدهما ويستخرجا كنزهما رحمة من ربك وما فعلته عن امري ذلك تاويل ما لم تسطع عليه صبرا'),
(2223, 18, 83, 'وَيَسْـَٔلُونَكَ عَنْ ذِي الْقَرْنَيْنِۜ قُلْ سَاَتْلُوا عَلَيْكُمْ مِنْهُ ذِكْراًۜ', 'Ve yes\'eluneke an zil karneyn, kul se etlu aleykum minhu zikra.', 'Sana,  Zu\'l-Karneyn\'den[1] soruyorlar. De ki: \"Size ondan bir konu anlatacağım.\"', 'ويسلونك عن ذي القرنين قل ساتلوا عليكم منه ذكرا'),
(2224, 18, 84, 'اِنَّا مَكَّنَّا لَهُ فِي الْاَرْضِ وَاٰتَيْنَاهُ مِنْ كُلِّ شَيْءٍ سَبَباًۙ', 'İnna mekkenna lehu fil ardı ve ateynahu min kulli şey\'in sebeba.', 'Doğrusu Biz,  onu yeryüzünde güçlendirdik ve ona her şeyden bir sebep[1] verdik.', 'انا مكنا له في الارض واتينه من كل شي سببا'),
(2225, 18, 85, 'فَاَتْبَعَ سَبَباً', 'Fe etbea sebeba.', 'Böylece bir sebebe tabi oldu.', 'فاتبع سببا'),
(2226, 18, 86, 'حَتّٰٓى اِذَا بَلَغَ مَغْرِبَ الشَّمْسِ وَجَدَهَا تَغْرُبُ ف۪ي عَيْنٍ حَمِئَةٍ وَوَجَدَ عِنْدَهَا قَوْماًۜ قُلْنَا يَا ذَا الْقَرْنَيْنِ اِمَّٓا اَنْ تُعَذِّبَ وَاِمَّٓا اَنْ تَتَّخِذَ ف۪يهِمْ حُسْناً', 'Hatta iza belega magribeş şemsi vecedeha tagrubu fi aynin hamietin ve vecede indeha kavma, kulna ya zel karneyni imma en tuazzibe ve imma en tettehıze fihim husna.', 'Nihayet o,  Güneş\'in battığı yere vardığı zaman,  onu koyu bir suda batıyor buldu. Bir de bunun yanında bir halkla karşılaştı. \"Ey Zu\'l-Karneyn! Dilersen onları cezalandırırsın,  dilersen onlara iyilik edersin.[1]\" dedik.', 'حتي اذا بلغ مغرب الشمس وجدها تغرب في عين حمية ووجد عندها قوما قلنا يذا القرنين اما ان تعذب واما ان تتخذ فيهم حسنا'),
(2227, 18, 87, 'قَالَ اَمَّا مَنْ ظَلَمَ فَسَوْفَ نُعَذِّبُهُ ثُمَّ يُرَدُّ اِلٰى رَبِّه۪ فَيُعَذِّبُهُ عَذَاباً نُكْراً', 'Kale emma men zaleme fe sevfe nuazzibuhu summe yureddu ila rabbihi fe yuazzibuhu azaben nukra.', 'Zu\'l-Karneyn: \"Kim zulmederse ona azap edeceğiz. Sonra Rabb\'ine döndürülür. Böylece ona daha şiddetli bir azapla azap edilir.\" dedi.', 'قال اما من ظلم فسوف نعذبه ثم يرد الي ربه فيعذبه عذابا نكرا'),
(2228, 18, 88, 'وَاَمَّا مَنْ اٰمَنَ وَعَمِلَ صَالِحاً فَلَهُ جَزَٓاءًۨ الْحُسْنٰىۚ وَسَنَقُولُ لَهُ مِنْ اَمْرِنَا يُسْراًۜ', 'Ve emma men amene ve amile salihan fe lehu cezaenil husna ve se nekulu lehu min emrina yusra.', '\"Kim iman eder ve salihatı yaparsa,  en iyi karşılık onundur. Biz,  ona her türlü kolaylığı göstereceğiz.\"', 'واما من امن وعمل صلحا فله جزا الحسني وسنقول له من امرنا يسرا'),
(2229, 18, 89, 'ثُمَّ اَتْـبَعَ سَبَباً', 'Summe etbea sebeba.', 'Sonra bir sebebe[1] tabi oldu.', 'ثم اتبع سببا'),
(2230, 18, 90, 'حَتّٰٓى اِذَا بَلَغَ مَطْلِعَ الشَّمْسِ وَجَدَهَا تَطْلُعُ عَلٰى قَوْمٍ لَمْ نَجْعَلْ لَهُمْ مِنْ دُونِهَا سِتْراًۙ', 'Hatta iza belega matlıaş şemsi vecedeha tatluu ala kavmin lem nec\'al lehum min duniha sitra.', 'Nihayet Güneş\'in doğduğu yere vardığı zaman,  onu,  kendilerini Güneş\'e karşı koruyacak bir örtü yapmadığımız bir halkın üzerine doğarken buldu.', 'حتي اذا بلغ مطلع الشمس وجدها تطلع علي قوم لم نجعل لهم من دونها سترا'),
(2231, 18, 91, 'كَذٰلِكَۜ وَقَدْ اَحَطْنَا بِمَا لَدَيْهِ خُبْراً', 'Kezalik, ve kad ehatna bima ledeyhi hubra.', 'İşte böyle! Biz,  onun yanında olan şeyleri bilgimizle kuşatmıştık.', 'كذلك وقد احطنا بما لديه خبرا'),
(2232, 18, 92, 'ثُمَّ اَتْبَعَ سَبَباً', 'Summe etbea sebeba.', 'Sonra bir sebebe tabi oldu.', 'ثم اتبع سببا'),
(2233, 18, 93, 'حَتّٰٓى اِذَا بَلَغَ بَيْنَ السَّدَّيْنِ وَجَدَ مِنْ دُونِهِمَا قَوْماًۙ لَا يَكَادُونَ يَفْقَهُونَ قَوْلاً', 'Hatta iza belega beynes seddeyni vecede min dunihima kavmen la yekadune yefkahune kavla.', 'Nihayet iki set arasına ulaştığı zaman,  onların yanı başında neredeyse hiç söz anlamayan bir halkla karşılaştı.', 'حتي اذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا'),
(2234, 18, 94, 'قَالُوا يَا ذَا الْقَرْنَيْنِ اِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْاَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجاً عَلٰٓى اَنْ تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَداًّ', 'Kalu ya zel karneyni inne ye\'cuce ve me\'cuce mufsidune fil ardı fe hel nec\'alu leke harcen ala en tec\'ale beynena ve beynehum sedda.', '\"Ey Zu\'l-Karneyn! Şüphesiz Ye\'cuc ve Me\'cuc[1] yeryüzünde fesat çıkaranlardır. Onun için,  onlarla bizim aramıza ücreti mukabilinde bir set yap,  olmaz mı?\" dediler.', 'قالوا يذا القرنين ان ياجوج وماجوج مفسدون في الارض فهل نجعل لك خرجا علي ان تجعل بيننا وبينهم سدا'),
(2235, 18, 95, 'قَالَ مَا مَكَّنّ۪ي ف۪يهِ رَبّ۪ي خَيْرٌ فَاَع۪ينُون۪ي بِقُوَّةٍ اَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْماًۙ', 'Kale ma mekkenni fihi rabbi hayrun fe einuni bi kuvvetin ec\'al beynekum ve beynehum redma.', '\"Rabb\'imin,  beni içinde bulundurduğu imkanlar daha hayırlıdır.\" dedi. \"Şimdi bana güç verin de sizinle onların arasına çok sağlam bir engel yapayım.\" dedi.', 'قال ما مكني فيه ربي خير فاعينوني بقوة اجعل بينكم وبينهم ردما'),
(2236, 18, 96, 'اٰتُون۪ي زُبَرَ الْحَد۪يدِۜ حَتّٰٓى اِذَا سَاوٰى بَيْنَ الصَّدَفَيْنِ قَالَ انْفُخُواۜ حَتّٰٓى اِذَا جَعَلَهُ نَاراًۙ قَالَ اٰتُون۪ٓي اُفْرِ غْ عَلَيْهِ قِطْراًۜ', 'Atuni zuberel hadid, hatta iza sava beynes sadafeyni kalenfuhu, hatta iza cealehu naren kale atuni ufrig aleyhi kıtra.', '\"Bana demir parçaları getirin. İki dağın arası eşit seviyeye gelinceye kadar körükleyin.\" dedi. Onu bir ateş haline getirince,  \"Bana erimiş bakır getirin,  onun üzerine dökeceğim.\" dedi.', 'اتوني زبر الحديد حتي اذا ساوي بين الصدفين قال انفخوا حتي اذا جعله نارا قال اتوني افرغ عليه قطرا'),
(2237, 18, 97, 'فَمَا اسْطَاعُٓوا اَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْباً', 'Femestau en yazheruhu ve mestetau lehu nakba.', 'Artık onu aşmaya ve yarıp geçmeye güç yetiremediler.', 'فما اسطعوا ان يظهروه وما استطعوا له نقبا'),
(2238, 18, 98, 'قَالَ هٰذَا رَحْمَةٌ مِنْ رَبّ۪يۚ فَاِذَا جَٓاءَ وَعْدُ رَبّ۪ي جَعَلَهُ دَكَّٓاءَۚ وَكَانَ وَعْدُ رَبّ۪ي حَقاًّۜ', 'Kale haza rahmetun min rabbi, fe iza cae va\'du rabbi cealehu dekka\', ve kane va\'du rabbi hakka.', '\"Bu Rabb\'imden bir rahmettir. Ama Rabb\'imin uyarısı[1] gerçekleştiği zaman,  onu yerle bir eder. Ve Rabb\'imin uyarısı gerçektir.\" dedi.', 'قال هذا رحمة من ربي فاذا جا وعد ربي جعله دكا وكان وعد ربي حقا'),
(2239, 18, 99, 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ ف۪ي بَعْضٍ وَنُفِخَ فِي الصُّورِ فَجَمَعْنَاهُمْ جَمْعاًۙ', 'Ve terakna ba\'dahum yevmeizin yemucu fi ba\'dın ve nufiha fis suri fe cema\'nahum cem\'a.', 'İzin günü[1] onları terk ederiz. Dalga dalga birbirlerine karışırlar. Ve Sur\'a üfürülür. Hepsini bir araya toplarız.', 'وتركنا بعضهم يوميذ يموج في بعض ونفخ في الصور فجمعنهم جمعا'),
(2240, 18, 100, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِلْكَافِر۪ينَ عَرْضاًۙ', 'Ve aradna cehenneme yevmeizin lil kafirine arda.', 'İzin günü Cehennem\'i Kafirlere sunarız,  tam bir sunuşla.', 'وعرضنا جهنم يوميذ للكفرين عرضا'),
(2241, 18, 101, 'اَلَّذ۪ينَ كَانَتْ اَعْيُنُهُمْ ف۪ي غِطَٓاءٍ عَنْ ذِكْر۪ي وَكَانُوا لَا يَسْتَط۪يعُونَ سَمْعاً۟', 'Ellezine kanet a\'yunuhum fi gıtain an zikri ve kanu la yestetiune sem\'a.', 'Ki onlar,  bizim zikrimize[1] karşı gözleri kapalı ve işitmeye tahammülü olmayanlardır.', 'الذين كانت اعينهم في غطا عن ذكري وكانوا لا يستطيعون سمعا'),
(2242, 18, 102, 'اَفَحَسِبَ الَّذ۪ينَ كَفَرُٓوا اَنْ يَتَّخِذُوا عِبَاد۪ي مِنْ دُون۪ٓي اَوْلِيَٓاءَۜ اِنَّٓا اَعْتَدْنَا جَهَنَّمَ لِلْكَافِر۪ينَ نُزُلاً', 'E fe hasibellezine keferu en yettehızu ibadi min duni evliya\', inna a\'tedna cehenneme lil kafirine nuzula.', 'Yoksa Kafirler[1],  Benim yanım sıra evliya[1] edinebileceklerini mi sandılar? Biz,  Cehennem\'i Kafirlere bir ikram olarak hazırladık.', 'افحسب الذين كفروا ان يتخذوا عبادي من دوني اوليا انا اعتدنا جهنم للكفرين نزلا'),
(2243, 18, 103, 'قُلْ هَلْ نُنَبِّئُكُمْ بِالْاَخْسَر۪ينَ اَعْمَالاًۜ', 'Kul hel nunebbiukum bil ahserine a\'mala.', 'De ki: \"Size,  yaptıklarından dolayı en çok kayba uğrayanları haber verelim mi?\"', 'قل هل ننبيكم بالاخسرين اعملا'),
(2244, 18, 104, 'اَلَّذ۪ينَ ضَلَّ سَعْيُهُمْ فِي الْحَيٰوةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ اَنَّهُمْ يُحْسِنُونَ صُنْعاً', 'Ellezine dalle sa\'yuhum fil hayatid dunya ve hum yahsebune ennehum yuhsinune sun\'a.', '\"Onlar,  dünya hayatında iyi işler yaptıklarını sanırlarken,  yaptıkları boşa gitmiş olan kimselerdir.\"', 'الذين ضل سعيهم في الحيوة الدنيا وهم يحسبون انهم يحسنون صنعا'),
(2245, 18, 105, 'اُو۬لٰٓئِكَ الَّذ۪ينَ كَفَرُوا بِاٰيَاتِ رَبِّهِمْ وَلِقَٓائِه۪ فَحَبِطَتْ اَعْمَالُهُمْ فَلَا نُق۪يمُ لَهُمْ يَوْمَ الْقِيٰمَةِ وَزْناً', 'Ulaikellezine keferu bi ayati rabbihim ve likaihi fe habitat a\'maluhum fe la nukimu lehum yevmel kıyameti vezna.', 'İşte onlar,  Rabblerinin ayetlerini ve O\'na kavuşmayı inkar edenlerdir. Bu nedenle onların bütün yaptıkları boşa gitmiştir. Artık Kıyamet Günü onlara hiçbir değer vermeyiz.', 'اوليك الذين كفروا بايت ربهم ولقايه فحبطت اعملهم فلا نقيم لهم يوم القيمة وزنا'),
(2246, 18, 106, 'ذٰلِكَ جَزَٓاؤُ۬هُمْ جَهَنَّمُ بِمَا كَفَرُوا وَاتَّخَذُٓوا اٰيَات۪ي وَرُسُل۪ي هُزُواً', 'Zalike cezauhum cehennemu bima keferu vettehazu ayati ve rusuli huzuva.', 'Küfretmeleri,  ayetlerimi ve resullerimi alaya almaları nedeniyle onların cezaları Cehennem\'dir.', 'ذلك جزاوهم جهنم بما كفروا واتخذوا ايتي ورسلي هزوا'),
(2247, 18, 107, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلاًۙ', 'İnnellezine amenu ve amilus salihati kanet lehum cennatul firdevsi nuzula.', 'İman edip,  salihatı yapanların[1] ikramı Firdevs Cennetleridir.', 'ان الذين امنوا وعملوا الصلحت كانت لهم جنت الفردوس نزلا'),
(2248, 18, 108, 'خَالِد۪ينَ ف۪يهَا لَا يَبْغُونَ عَنْهَا حِوَلاً', 'Halidine fiha la yebgune anha hıvela.', 'Orada devamlı kalırlar. Asla ayrılmak istemezler.', 'خلدين فيها لا يبغون عنها حولا'),
(2249, 18, 109, 'قُلْ لَوْ كَانَ الْبَحْرُ مِدَاداً لِكَلِمَاتِ رَبّ۪ي لَنَفِدَ الْبَحْرُ قَبْلَ اَنْ تَنْفَدَ كَلِمَاتُ رَبّ۪ي وَلَوْ جِئْنَا بِمِثْلِه۪ مَدَداً', 'Kul lev kanel bahru midaden li kelimati rabbi le nefidel bahru kable en tenfede kelimatu rabbi ve lev ci\'na bi mislihi mededa.', 'De ki: \"Rabb\'imin kelimeleri[1] için denizler ve bir o kadar daha deniz mürekkep olsa; Rabb\'imin kelimeleri bitmeden denizler biterdi.', 'قل لو كان البحر مدادا لكلمت ربي لنفد البحر قبل ان تنفد كلمت ربي ولو جينا بمثله مددا'),
(2250, 18, 110, 'قُلْ اِنَّـمَٓا اَنَا۬ بَشَرٌ مِثْلُكُمْ يُوحٰٓى اِلَيَّ اَنَّـمَٓا اِلٰهُكُمْ اِلٰهٌ وَاحِدٌۚ فَمَنْ كَانَ يَرْجُوا لِقَٓاءَ رَبِّه۪ فَلْيَعْمَلْ عَمَلاً صَالِحاً وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّه۪ٓ اَحَداً', 'Kul innema ene beşerun mislukum yuha ileyye ennema ilahukum ilahun vahid, fe men kane yercu likae rabbihi fel ya\'mel amelen salihan ve la yuşrik bi ıbadeti rabbihi ehada.', 'De ki: \"Ben de ancak sizin gibi bir beşerim. Sizden farkım; bana,  ilahınızın ancak tek ilah olduğu vahyedilmiş olmasıdır. Onun için her kim Rabbine kavuşmayı umuyorsa,  salihatı yapsın ve Rabb\'ine kullukta[1] hiç kimseyi ortak koşmasın.\"', 'قل انما انا بشر مثلكم يوحي الي انما الهكم اله وحد فمن كان يرجوا لقا ربه فليعمل عملا صلحا ولا يشرك بعبادة ربه احدا'),
(2251, 19, 1, 'كٓـهٰيٰعٓصٓۜ', 'Kaf, ha, ya, ayn, sad.', 'Kaf,  Ha,  Ya,  Ayn,  Sad.', 'كهيعص'),
(2252, 19, 2, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُ زَكَرِيَّاۚ', 'Zikru rahmeti rabbike abdehu zekeriyya.', 'Rabb\'inin,  kulu Zekeriya\'ya rahmetinin zikridir.[1]', 'ذكر رحمت ربك عبده زكريا'),
(2253, 19, 3, 'اِذْ نَادٰى رَبَّهُ نِدَٓاءً خَفِياًّ', 'İz nada rabbehu nidaen hafiyya.', 'O,  içten bir seslenişle Rabb\'ine seslenmişti.', 'اذ نادي ربه ندا خفيا'),
(2254, 19, 4, 'قَالَ رَبِّ اِنّ۪ي وَهَنَ الْعَظْمُ مِنّ۪ي وَاشْتَعَلَ الرَّأْسُ شَيْباً وَلَمْ اَكُنْ بِدُعَٓائِكَ رَبِّ شَقِياًّ', 'Kale rabbi inni ve henel azmu minni veştealer re\'su şeyben ve lem ekun bi duaike rabbi şakıyya.', '\"Rabb\'im! Gerçekten ben iyice güçten kesildim. Saçım başım ağardı. Ve Rabb\'im,  Sana ettiğim dualarım hiç karşılıksız kalmadı.\"', 'قال رب اني وهن العظم مني واشتعل الراس شيبا ولم اكن بدعايك رب شقيا'),
(2255, 19, 5, 'وَاِنّ۪ي خِفْتُ الْمَوَالِيَ مِنْ وَرَٓاء۪ي وَكَانَتِ امْرَاَت۪ي عَاقِراً فَهَبْ ل۪ي مِنْ لَدُنْكَ وَلِياًّۚ', 'Ve inni hıftul mevaliye min verai ve kanetimreeti akıran feheb li min ledunke veliyya.', '\"Gerçekten,  benden sonra yerime geçeceklerden çok endişeliyim. Hanımım da kısır. Onun için bana katından bir veli[1] bağışla.\"', 'واني خفت المولي من وراي وكانت امراتي عاقرا فهب لي من لدنك وليا'),
(2256, 19, 6, 'يَرِثُن۪ي وَيَرِثُ مِنْ اٰلِ يَعْقُوبَۗ وَاجْعَلْهُ رَبِّ رَضِياًّ', 'Yerisuni ve yerisu min ali ya\'kube vec\'alhu rabbi radıyya.', '\"Bana ve Yakub soyuna mirasçı olsun. Rabb\'im,  onu hoşnut olunan kıl.\"', 'يرثني ويرث من ال يعقوب واجعله رب رضيا'),
(2257, 19, 7, 'يَا زَكَرِيَّٓا اِنَّـا نُـبَشِّرُكَ بِغُـلَامٍۨ اسْـمُهُ يَحْيٰىۙ لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِياًّ', 'Ya zekeriyya inna nubeşşiruke bi gulaminismuhu yahya lem nec\'al lehu min kablu semiyya.', '\"Ey Zekeriya! Biz,  sana ismi Yahya olan ve daha önce dengi görülmemiş bir oğul müjdeliyoruz.\"', 'يزكريا انا نبشرك بغلم اسمه يحيي لم نجعل له من قبل سميا'),
(2258, 19, 8, 'قَالَ رَبِّ اَنّٰى يَكُونُ ل۪ي غُلَامٌ وَكَانَتِ امْرَاَت۪ي عَاقِراً وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ عِتِياًّ', 'Kale rabbi enna yekunu li gulamun ve kanetimreeti akıran ve kad belagtu minel kiberi ıtiyya.', '\"Rabbim! Hanımım kısır,  ben de ayakta duramayacak kadar yaşlanmışken,  benim nasıl bir oğlum olabilir?\" dedi.', 'قال رب اني يكون لي غلم وكانت امراتي عاقرا وقد بلغت من الكبر عتيا'),
(2259, 19, 9, 'قَالَ كَذٰلِكَۚ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِنْ قَبْلُ وَلَمْ تَكُ شَيْـٔاً', 'Kale kezalik, kale rabbuke huve aleyye heyyinun ve kad halaktuke min kablu ve lem teku şey\'a.', '\"Haklısın,  ne var ki senin Rabb\'in böyle olmasını buyurdu.\" Ve \"Bu Benim için kolaydır. Bundan önce de seni,  sen hiçbir şey değilken yarattım.\" dedi.', 'قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيا'),
(2260, 19, 10, 'قَالَ رَبِّ اجْعَلْ ل۪ٓي اٰيَةًۜ  قَالَ اٰيَتُكَ اَلَّا تُكَلِّمَ النَّاسَ ثَلٰثَ لَيَالٍ سَوِياًّ', 'Kale rabbic\'al li ayeh, kale ayetuke ella tukellimen nase selase leyalin seviyya.', '\"Rabbim! Bana bir ayet[1] ver!\" dedi. \"Senin ayetin[2],  sapasağlam olduğun halde aralıksız üç gece[3] insanlarla konuşmayacak olmandır.\"[4] buyurdu.', 'قال رب اجعل لي اية قال ايتك الا تكلم الناس ثلث ليال سويا'),
(2261, 19, 11, 'فَخَرَجَ عَلٰى قَوْمِه۪ مِنَ الْمِحْرَابِ فَاَوْحٰٓى اِلَيْهِمْ اَنْ سَبِّحُوا بُكْرَةً وَعَشِياًّ', 'Fe harece ala kavmihi minel mihrabi fe evha ileyhim en sebbihu bukreten ve aşiyya.', 'Bunun üzerine mihraptan[1] halkının karşısına çıktı. Onlara,  sabah akşam[2] tesbih[3] etmelerini vahyetti.[4]', 'فخرج علي قومه من المحراب فاوحي اليهم ان سبحوا بكرة وعشيا'),
(2262, 19, 12, 'يَا يَحْيٰى خُذِ الْكِتَابَ بِقُوَّةٍۜ وَاٰتَيْنَاهُ الْحُكْمَ صَبِياًّۙ', 'Ya yahya huzil kitabe bi kuvveh, ve ateynahul hukme sabiyya.', '\"Ey Yahya! Kitap\'ı kuvvetlice tut[1].\" O henüz çocukken ona hikmet[2] verdik.', 'ييحيي خذ الكتب بقوة واتينه الحكم صبيا'),
(2263, 19, 13, 'وَحَنَاناً مِنْ لَدُنَّا وَزَكٰوةًۜ وَكَانَ تَقِياًّۙ', 'Ve hananen min ledunna ve zekah, ve kane tekıyya.', 'Tarafımızdan yumuşak kalplilik ve zekat[1] verdik. Ve o,  takva[2] sahibi oldu.', 'وحنانا من لدنا وزكوة وكان تقيا'),
(2264, 19, 14, 'وَبَراًّ بِوَالِدَيْهِ وَلَمْ يَكُنْ جَبَّاراً عَصِياًّ', 'Ve berren bi valideyhi ve lem yekun cebbaren asıyya.', 'Anne ve babasına karşı birr[1] sahibiydi. Karşı çıkan ve asilik eden biri değildi.', 'وبرا بولديه ولم يكن جبارا عصيا'),
(2265, 19, 15, 'وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَياًّ۟', 'Ve selamun aleyhi yevme vulide ve yevme yemutu ve yevme yub\'asu hayya.', 'Doğduğu gün,  öleceği gün ve canlı olarak yeniden diriltileceği gün onun üzerine selam olsun.', 'وسلم عليه يوم ولد ويوم يموت ويوم يبعث حيا'),
(2266, 19, 16, 'وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَۢ اِذِ انْتَبَذَتْ مِنْ اَهْلِهَا مَكَاناً شَرْقِياًّۙ', 'Vezkur fil kitabı meryem, izintebezet min ehliha mekanen şarkıyya.', 'Kitap\'ta Meryem\'i de an! Hani o,  ailesinden ayrılarak,  doğu tarafında bir yere çekilmişti.', 'واذكر في الكتب مريم اذ انتبذت من اهلها مكانا شرقيا'),
(2267, 19, 17, 'فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجَاباً فَاَرْسَلْـنَٓا اِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَراً سَوِياًّ', 'Fettehazet min dunihim hicaben fe erselna ileyha ruhana fe temessele leha beşeren seviyya.', 'Sonra ailesi ile arasına bir perde çekti.[1] O zaman,  ona ruhumuzu gönderdik. Ona normal bir beşer yapısında temessül etti.[2]', 'فاتخذت من دونهم حجابا فارسلنا اليها روحنا فتمثل لها بشرا سويا'),
(2268, 19, 18, 'قَالَتْ اِنّ۪ٓي اَعُوذُ بِالرَّحْمٰنِ مِنْكَ اِنْ كُنْتَ تَقِياًّ', 'Kalet inni euzu bir rahmani minke in kunte tekıyya.', '\"Senden Rahman\'a sığınırım. Eğer takva sahibi isen.\" dedi.[1]', 'قالت اني اعوذ بالرحمن منك ان كنت تقيا'),
(2269, 19, 19, 'قَالَ اِنَّـمَٓا اَنَا۬ رَسُولُ رَبِّكِۗ لِاَهَبَ لَكِ غُلَاماً زَكِياًّ', 'Kale innema ene resulu rabbiki li ehebe leki gulamen zekiyya.', '\"Ben sadece Rabb\'inin elçisiyim.\" dedi. \"Sana tertemiz bir oğul armağan etmek için geldim.\"', 'قال انما انا رسول ربك لاهب لك غلما زكيا'),
(2270, 19, 20, 'قَالَتْ اَنّٰى يَكُونُ ل۪ي غُلَامٌ وَلَمْ يَمْسَسْن۪ي بَشَرٌ وَلَمْ اَكُ بَغِياًّ', 'Kalet enna yekunu li gulamun ve lem yemsesni beşerun ve lem eku bagıyya.', '\"Benim nasıl bir oğlum olabilir? Bana kesinlikle bir beşer dokunmamışken. Ve ben kesinlikle iffetsiz değilim.\" dedi.', 'قالت اني يكون لي غلم ولم يمسسني بشر ولم اك بغيا'),
(2271, 19, 21, 'قَالَ كَذٰلِكِۚ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٌۚ وَلِنَجْعَلَـهُٓ اٰيَةً لِلنَّاسِ وَرَحْمَةً مِنَّاۚ وَكَانَ اَمْراً مَقْضِياًّ', 'Kale kezalik, kale rabbuki huve aleyye heyyin, ve li nec\'alehu ayeten lin nasi ve rahmeten minna, ve kane emren makdıyya.', '\"İşte böyle.\" dedi.[1] Rabbin: \"O Bana kolaydır. Onu,  insanlara bir ayet[2] ve Bizden bir rahmet kılacağız.\" dedi.\" Bunun böyle olması karara bağlanmıştır.\"', 'قال كذلك قال ربك هو علي هين ولنجعله اية للناس ورحمة منا وكان امرا مقضيا'),
(2272, 19, 22, 'فَحَمَلَتْهُ فَانْتَبَذَتْ بِه۪ مَكَاناً قَصِياًّ', 'Fe hamelethu fentebezet bihi mekanen kasıyya.', 'Ona hamile kaldı ve gözden uzak bir yere çekildi.', 'فحملته فانتبذت به مكانا قصيا'),
(2273, 19, 23, 'فَاَجَٓاءَهَا الْمَخَاضُ اِلٰى جِذْعِ النَّخْلَةِۚ قَالَتْ يَا لَيْتَن۪ي مِتُّ قَبْلَ هٰذَا وَكُنْتُ نَسْياً مَنْسِياًّ', 'Fe ecae hel mehadu ila ciz\'ın nahleh, kalet ya leyteni mittu kable haza ve kuntu nesyen mensiyya.', 'Sonra doğum sancısı onu bir hurma ağacının gövdesine sığınmaya mecbur etti. \"Keşke bundan önce ölseydim de unutulup gitseydim.\" dedi.[1]', 'فاجاها المخاض الي جذع النخلة قالت يليتني مت قبل هذا وكنت نسيا منسيا'),
(2274, 19, 24, 'فَنَادٰيهَا مِنْ تَحْتِهَٓا اَلَّا تَحْزَن۪ي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِياًّ', 'Fe nadaha min tahtiha ella tahzeni kad ceale rabbuki tahteki seriyya.', 'Sonra altından[1] ona \"Üzülme.\" diye bir ses geldi: \"Rabb\'in,  senin alt tarafında[2] olanı şerefli[3] kılmıştır.\"', 'فناديها من تحتها الا تحزني قد جعل ربك تحتك سريا'),
(2275, 19, 25, 'وَهُزّ۪ٓي اِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسَاقِطْ عَلَيْكِ رُطَباً جَنِياًّۘ', 'Ve huzzi ileyki bi ciz\'ın nahleti tusakıt aleyki rutaben ceniyya.', '\"Hurma ağacını silkele. Üzerine olmuş taze hurmalar dökülsün.\"', 'وهزي اليك بجذع النخلة تسقط عليك رطبا جنيا'),
(2276, 19, 26, 'فَكُل۪ي وَاشْرَب۪ي وَقَرّ۪ي عَيْناًۚ فَاِمَّا تَرَيِنَّ مِنَ الْبَشَرِ اَحَداًۙ فَقُول۪ٓي اِنّ۪ي نَذَرْتُ لِلرَّحْمٰنِ صَوْماً فَلَنْ اُكَلِّمَ الْيَوْمَ اِنْسِياًّۚ', 'Fe kuli veşrabi ve karri ayna, fe imma terayinne minel beşeri ehaden fe kuli inni nezertu lir rahmani savmen fe len ukellimel yevme insiyya.', '\"Artık ye ve iç. Gözün aydın olsun! Eğer beşerlerden[1] biri ile karşılaşırsan; ben Rahman\'a savm[2] adadım,  bu nedenle bugün hiç kimse ile konuşmayacağım de.\"', 'فكلي واشربي وقري عينا فاما ترين من البشر احدا فقولي اني نذرت للرحمن صوما فلن اكلم اليوم انسيا'),
(2277, 19, 27, 'فَاَتَتْ بِه۪ قَوْمَهَا تَحْمِلُهُۜ قَالُوا يَا مَرْيَمُ لَقَدْ جِئْتِ شَيْـٔاً فَرِياًّ', 'Fe etet bihi kavmeha tahmiluh, kalu ya meryemu lekad ci\'ti şey\'en feriyya.', 'Sonra onu kucaklayarak halka getirdi. Dediler ki: \"Ey Meryem! Doğrusu sen olmayacak bir şey yaptın.\"', 'فاتت به قومها تحمله قالوا يمريم لقد جيت شيا فريا'),
(2278, 19, 28, 'يَٓا اُخْتَ هٰرُونَ مَا كَانَ اَبُوكِ امْرَاَ سَوْءٍ وَمَا كَانَتْ اُمُّكِ بَغِياًّۚ', 'Ya uhte harune ma kane ebukimrae sev\'in ve ma kanet ummuki begıyya.', '\"Ey Harun\'un kız kardeşi![1] Doğrusu senin baban kötü bir adam değildi. Annen de iffetsiz bir kadın değildi.\"', 'ياخت هرون ما كان ابوك امرا سو وما كانت امك بغيا'),
(2279, 19, 29, 'فَاَشَارَتْ اِلَيْهِ۠ قَالُوا كَيْفَ نُكَلِّمُ مَنْ كَانَ فِي الْمَهْدِ صَبِياًّ', 'Fe eşaret ileyh, kalu keyfe nukellimu men kane fil mehdi sabiyya.', 'Bunun üzerine,  Meryem çocuğu işaret etti. Onlar: \"Biz beşikteki bir çocukla nasıl konuşuruz?\" dediler.[1]', 'فاشارت اليه قالوا كيف نكلم من كان في المهد صبيا'),
(2280, 19, 30, 'قَالَ اِنّ۪ي عَبْدُ اللّٰهِ۠ اٰتَانِيَ الْكِتَابَ وَجَعَلَن۪ي نَبِياًّۙ', 'Kale inni abdullah, ataniyel kitabe ve cealeni nebiyya.', '\"Kuşkusuz ki ben[1] Allah\'ın kuluyum. Bana Kitap verdi ve beni Nebi yaptı.\" dedi.', 'قال اني عبد الله اتيني الكتب وجعلني نبيا'),
(2281, 19, 31, 'وَجَعَلَن۪ي مُبَارَكاً اَيْنَ مَا كُنْتُۖ وَاَوْصَان۪ي بِالصَّلٰوةِ وَالزَّكٰوةِ مَا دُمْتُ حَياًّۖ', 'Ve cealeni mubareken eyne ma kuntu ve evsani bis salati vez zekati ma dumtu hayya.', '\"Ve beni bulunduğum her yerde mübarek[1] kıldı. Ve yaşadığım sürece bana salatı[2] ve zekatı[3] tavsiye etti.[4]\"', 'وجعلني مباركا اين ما كنت واوصيني بالصلوة والزكوة ما دمت حيا'),
(2282, 19, 32, 'وَبَراًّ بِوَالِدَت۪يۘ وَلَمْ يَجْعَلْن۪ي جَبَّاراً شَقِياًّ', 'Ve berren bi valideti ve lem yec\'alni cebbaren şakıyya.', '\"Ve anneme karşı birr[1] yaptı. Ve beni bir zorba,  bir isyankar yapmadı.\"', 'وبرا بولدتي ولم يجعلني جبارا شقيا'),
(2283, 19, 33, 'وَالسَّلَامُ عَلَيَّ يَوْمَ وُلِدْتُ وَيَوْمَ اَمُوتُ وَيَوْمَ اُبْعَثُ حَياًّ', 'Ves selamu aleyye yevme vulidtu ve yevme emutu ve yevme ub\'asu hayya.', '\"Doğurulduğum gün,  öleceğim gün ve canlı olarak diriltileceğim gün,  selam[1] benim üzerimedir.\"', 'والسلم علي يوم ولدت ويوم اموت ويوم ابعث حيا'),
(2284, 19, 34, 'ذٰلِكَ ع۪يسَى ابْنُ مَرْيَمَۚ قَوْلَ الْحَقِّ الَّذ۪ي ف۪يهِ يَمْتَرُونَ', 'Zalike isebnu meryem, kavlel hakkıllezi fihi yemterun.', 'İşte hakkında tartıştıkları Meryem oğlu Îsa hakkında söylenecek gerçek söz budur.', 'ذلك عيسي ابن مريم قول الحق الذي فيه يمترون'),
(2285, 19, 35, 'مَا كَانَ لِلّٰهِ اَنْ يَتَّخِذَ مِنْ وَلَدٍۙ سُبْحَانَهُۜ اِذَا قَضٰٓى اَمْراً فَاِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُۜ', 'Ma kane lillahi en yettehıze min veledin subhaneh, iza kada emren fe innema yekulu lehu kun fe yekun.', 'Allah\'ın çocuk edinmesi olacak şey değildir. O,  her şeyden münezzehtir.[1] Allah bir şeyin olmasına karar verdiği zaman ona \"Ol.\" der,  o da olur.', 'ما كان لله ان يتخذ من ولد سبحنه اذا قضي امرا فانما يقول له كن فيكون'),
(2286, 19, 36, 'وَاِنَّ اللّٰهَ رَبّ۪ي وَرَبُّكُمْ فَاعْبُدُوهُۜ هٰذَا صِرَاطٌ مُسْتَق۪يمٌ', 'Ve innallahe rabbi ve rabbukum fa\'buduh, haza sıratun mustekim.', 'Allah,  benim de Rabb\'im sizin de Rabb\'inizdir. O halde,  O\'na kulluk edin. İşte bu dosdoğru yoldur.', 'وان الله ربي وربكم فاعبدوه هذا صرط مستقيم'),
(2287, 19, 37, 'فَاخْتَلَفَ الْاَحْزَابُ مِنْ بَيْنِهِمْۚ فَوَيْلٌ لِلَّذ۪ينَ كَفَرُوا مِنْ مَشْهَدِ يَوْمٍ عَظ۪يمٍ', 'Fahtelefel ahzabu min beynihim, fe veylun lillezine keferu min meşhedi yevmin azim.', 'Bundan sonra gruplar kendi aralarında çekişmeye başladılar. Büyük günde bütün gerçekler ortaya çıktığı zaman,  o Kafirlerin[1] vay haline.', 'فاختلف الاحزاب من بينهم فويل للذين كفروا من مشهد يوم عظيم'),
(2288, 19, 38, 'اَسْمِعْ بِهِمْ وَاَبْصِرْۙ يَوْمَ يَأْتُونَنَاۚ لٰكِنِ الظَّالِمُونَ الْيَوْمَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Esmi\' bihim ve ebsır yevme ye\'tunena lakiniz zalimunel yevme fi dalalin mubin.', 'Bize gelecekleri gün,  onlara gerçekler işittirilir ve gösterilir. Ne var ki zalimler,  bugün apaçık bir şaşkınlık içindeler.', 'اسمع بهم وابصر يوم ياتوننا لكن الظلمون اليوم في ضلل مبين'),
(2289, 19, 39, 'وَاَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ اِذْ قُضِيَ الْاَمْرُۚ وَهُمْ ف۪ي غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', 'Ve enzirhum yevmel hasreti iz kudıyel emr, ve hum fi gafletin ve hum la yu\'minun.', 'Gaflet[1] içinde olup,  iman etmeyenleri,  emrin yerine getirileceği pişmanlık günüyle uyar.', 'وانذرهم يوم الحسرة اذ قضي الامر وهم في غفلة وهم لا يومنون'),
(2290, 19, 40, 'اِنَّا نَحْنُ نَرِثُ الْاَرْضَ وَمَنْ عَلَيْهَا وَاِلَيْنَا يُرْجَعُونَ۟', 'İnna nahnu nerisul arda ve men aleyha ve ileyna yurceun.', 'Yeryüzüne ve onun üzerindeki her şeye Biz varis olacağız. Ve onlar,  yalnızca Bize döndürülecekler.', 'انا نحن نرث الارض ومن عليها والينا يرجعون'),
(2291, 19, 41, 'وَاذْكُرْ فِي الْكِتَابِ اِبْرٰه۪يمَۜ اِنَّهُ كَانَ صِدّ۪يقاً نَبِياًّ', 'Vezkur fil kitabi ibrahim, innehu kane sıddikan nebiyya.', 'Kitap\'ta İbrahim\'i de an. O,  sadık[1] bir nebiydi.', 'واذكر في الكتب ابرهيم انه كان صديقا نبيا'),
(2292, 19, 42, 'اِذْ قَالَ لِاَب۪يهِ يَٓا اَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْن۪ي عَنْكَ شَيْـٔاً', 'İz kale li ebihi, ya ebeti lime ta\'budu ma la yesmau ve la yubsıru ve la yugni anke şey\'a.', 'Babasına: \"Ey babacığım! İşitmeyen,  görmeyen ve sana hiçbir yararı olmayan şeylere niçin kulluk[1] ediyorsun?\" demişti.', 'اذ قال لابيه يابت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيا'),
(2293, 19, 43, 'يَٓا اَبَتِ اِنّ۪ي قَدْ جَٓاءَن۪ي مِنَ الْعِلْمِ مَا لَمْ يَأْتِكَ فَاتَّبِعْن۪ٓي اَهْدِكَ صِرَاطاً سَوِياًّ', 'Ya ebeti inni kad caeni minel ilmi ma lem ye\'tike fettebi\'ni ehdike sıratan seviyya.', '\"Ey babacığım! Sana gelmeyen bir ilim[1] bana geldi. O halde bana uy. Ki seni dosdoğru olan yola ileteyim.\"', 'يابت اني قد جاني من العلم ما لم ياتك فاتبعني اهدك صراط سويا'),
(2294, 19, 44, 'يَٓا اَبَتِ لَا تَعْبُدِ الشَّيْطَانَۜ اِنَّ الشَّيْطَانَ كَانَ لِلرَّحْمٰنِ عَصِياًّ', 'Ya ebeti la ta\'budiş şeytan, inneş şeytane kane lir rahmani asıyya.', '\"Ey babacığım! Şeytana kulluk etme. Şeytan Rahman\'a isyan eden biridir.\"', 'يابت لا تعبد الشيطن ان الشيطن كان للرحمن عصيا'),
(2295, 19, 45, 'يَٓا اَبَتِ اِنّ۪ٓي اَخَافُ اَنْ يَمَسَّكَ عَذَابٌ مِنَ الرَّحْمٰنِ فَتَكُونَ لِلشَّيْطَانِ وَلِياًّ', 'Ya ebeti inni ehafu en yemesseke azabun miner rahmani fe tekune liş şeytani veliyya.', '\"Ey babacığım! Ben,  Rahman\'dan sana bir azap dokunur[1] da bu durumda şeytan[2] için bir veli[3] olursun diye korkuyorum.\"', 'يابت اني اخاف ان يمسك عذاب من الرحمن فتكون للشيطن وليا'),
(2296, 19, 46, 'قَالَ اَرَاغِبٌ اَنْتَ عَنْ اٰلِهَت۪ي يَٓا اِبْرٰه۪يمُۚ  لَئِنْ لَمْ تَنْتَهِ۬ لَاَرْجُمَنَّكَ وَاهْجُرْن۪ي مَلِياًّ', 'Kale e ragıbun ente an aliheti ya ibrahim, lein lem tentehi le ercumenneke vehcurni meliyya.', '\"Ey İbrahim! Sen,  benim ilahlarıma değer vermiyor musun? Eğer vazgeçmezsen kesinlikle seni taşlarım. Şimdi uzun bir süre gözüme görünme.\" dedi.', 'قال اراغب انت عن الهتي يابرهيم لين لم تنته لارجمنك واهجرني مليا'),
(2297, 19, 47, 'قَالَ سَلَامٌ عَلَيْكَۚ سَاَسْتَغْفِرُ لَكَ رَبّ۪يۜ اِنَّهُ  كَانَ ب۪ي حَفِياًّ', 'Kale selamun aleyk, se estagfiru leke rabbi, innehu kane bi hafiyya.', '\"Sana selam olsun. Seni affetmesi için Rabb\'imden bağışlanma dileyeceğim. Kuşkusuz O,  bana çok lütufkardır.\"[1]', 'قال سلم عليك ساستغفر لك ربي انه كان بي حفيا'),
(2298, 19, 48, 'وَاَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِنْ دُونِ اللّٰهِ وَاَدْعُوا رَبّ۪يۘ عَسٰٓى اَلَّٓا اَكُونَ بِدُعَٓاءِ رَبّ۪ي شَقِياًّ', 'Ve a\'tezilukum ve ma ted\'une min dunillahi ve ed\'u rabbi, asa ella ekune bi duai rabbi şakıyya.', '\"Sizden ve Allah\'ın yanı sıra kulluk ettiğiniz şeylerden uzak durup,  yalnızca Rabb\'ime dua edeceğim. Umulur ki,  Rabb\'ime ettiğim dualar sayesinde mahrum olmam.\"', 'واعتزلكم وما تدعون من دون الله وادعوا ربي عسي الا اكون بدعا ربي شقيا'),
(2299, 19, 49, 'فَلَمَّا اعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِنْ دُونِ اللّٰهِۙ وَهَبْنَا لَـهُٓ اِسْحٰقَ وَيَعْقُوبَۜ وَكُلاًّ جَعَلْنَا نَبِياًّ', 'Fe lemma\'tezelehum ve ma ya\'budune min dunillahi vehebna lehu ishaka ve ya\'kub ve kullen cealna nebiyya.', 'Onlardan ve onların Allah\'ın yanı sıra kulluk ettiklerinden ayrılınca,  Biz,  ona İshak\'ı ve torunu Yakub\'u bağışladık. Hepsini nebi yaptık.', 'فلما اعتزلهم وما يعبدون من دون الله وهبنا له اسحق ويعقوب وكلا جعلنا نبيا'),
(2300, 19, 50, 'وَوَهَبْنَا لَهُمْ مِنْ رَحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِياًّ۟', 'Ve vehebna lehum min rahmetina ve cealna lehum lisane sıdkın aliyya.', 'Ve rahmetimizden onlara lutfettik[1]. Onların doğrulukla anılmalarını sağladık.', 'ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا'),
(2301, 19, 51, 'وَاذْكُرْ فِي الْكِتَابِ مُوسٰىۘ اِنَّهُ كَانَ مُخْلَصاً وَكَانَ رَسُولاً نَبِياًّ', 'Vezkur fil kitabi musa, innehu kane muhlesan ve kane resulen nebiyya.', 'Kitap\'ta Musa\'yı da an. O,  muhles[1] bir resul,  bir nebiydi.', 'واذكر في الكتب موسي انه كان مخلصا وكان رسولا نبيا'),
(2302, 19, 52, 'وَنَادَيْنَاهُ مِنْ جَانِبِ الطُّورِ الْاَيْمَنِ وَقَرَّبْنَاهُ نَجِياًّ', 'Ve nadeynahu min canibit turil eymeni ve karrebnahu neciyya.', 'Ve Tur\'un sağ tarafından ona seslendik. Onu,  özel konuşmak için yaklaştırdık.', 'ونادينه من جانب الطور الايمن وقربنه نجيا'),
(2303, 19, 53, 'وَوَهَبْنَا لَهُ مِنْ رَحْمَتِنَٓا اَخَاهُ هٰرُونَ نَبِياًّ', 'Ve vehebna lehu min rahmetina ehahu harune nebiyya.', 'Ona rahmetimizden bir nebi olarak kardeşi Harun\'u armağan ettik.', 'ووهبنا له من رحمتنا اخاه هرون نبيا'),
(2304, 19, 54, 'وَاذْكُرْ فِي الْكِتَابِ اِسْمٰع۪يلَۘ اِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولاً نَبِياًّۚ', 'Vezkur fil kitabi ismaile innehu kane sadıkal va\'di ve kane resulen nebiyya.', 'Kitap\'ta İsmail\'i de an. O,  sözüne sadık[1] bir resul,  bir nebiydi.', 'واذكر في الكتب اسمعيل انه كان صادق الوعد وكان رسولا نبيا'),
(2305, 19, 55, 'وَكَانَ يَأْمُرُ اَهْلَهُ بِالصَّلٰوةِ وَالزَّكٰوةِۖ وَكَانَ عِنْدَ رَبِّه۪ مَرْضِياًّ', 'Ve kane ye\'muru ehlehu bis salati vez zekati ve kane inde rabbihi mardıyya.', 'Ve o kendisi ile birlikte olanlara salatı ve zekatı buyuruyordu[1]. Ve o Rabb\'inin yanında kendisinden hoşnut olunmuşlardandı.', 'وكان يامر اهله بالصلوة والزكوة وكان عند ربه مرضيا'),
(2306, 19, 56, 'وَاذْكُرْ فِي الْكِتَابِ اِدْر۪يسَۘ اِنَّهُ كَانَ صِدّ۪يقاً نَبِياًّۗ', 'Vezkur fil kitabi idrise innehu kane sıddikan nebiyya.', 'Kitap\'ta İdris\'i de an. O,  çok sadık bir nebiydi.', 'واذكر في الكتب ادريس انه كان صديقا نبيا'),
(2307, 19, 57, 'وَرَفَعْنَاهُ مَكَاناً عَلِياًّ', 'Ve refa\'nahu mekanen aliyya.', 'Onu yüce bir mekana yükselttik.', 'ورفعنه مكان عليا'),
(2308, 19, 58, 'اُو۬لٰٓئِكَ الَّذ۪ينَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِنَ النَّبِيّ۪نَ مِنْ ذُرِّيَّةِ اٰدَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍۘ وَمِنْ ذُرِّيَّةِ اِبْرٰه۪يمَ وَاِسْرَٓائ۪لَ وَمِمَّنْ هَدَيْنَا وَاجْتَبَيْنَاۜ اِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُ الرَّحْمٰنِ خَرُّوا سُجَّداً وَبُكِياًّ', 'Ulaikellezine en\'amallahu aleyhim minen nebiyyine min zurriyyeti ademe ve mimmen hamelna mea nuhin ve min zurriyyeti ibrahime ve israile ve mimmen hedeyna vectebeyna, iza tutla aleyhim ayatur rahmani harru succeden ve bukiyya.', 'İşte bunlar,  Allah\'ın nimetlendirdiği nebilerdendi. Âdem\'in neslinden ve Nuh ile birlikte taşıdıklarımızdan ve İbrahim ve İsrail\'in[1] soyundan ve doğru yola ilettiğimiz ve seçtiklerimizdendir. Onlara[2] Rahman\'ın ayetleri okunduğu zaman ağlayarak secdeye kapanırlardı.', 'اوليك الذين انعم الله عليهم من النبين من ذرية ادم وممن حملنا مع نوح ومن ذرية ابرهيم واسريل وممن هدينا واجتبينا اذا تتلي عليهم ايت الرحمن خروا سجدا وبكيا'),
(2309, 19, 59, 'فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ اَضَاعُوا الصَّلٰوةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَياًّۙ', 'Fe halefe min ba\'dihim halfun edaus salate vettebeuş şehevati fe sevfe yelkavne gayya.', 'Bundan sonra arkalarından gelen sonraki nesil,  salatı zayi ettiler[1] ve şehvetlerine[2] uydular. Yakında kötülükleri kendilerine dönecektir.', 'فخلف من بعدهم خلف اضاعوا الصلوة واتبعوا الشهوت فسوف يلقون غيا'),
(2310, 19, 60, 'اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ صَالِحاً فَاُو۬لٰٓئِكَ يَدْخُلُونَ الْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـٔاًۙ', 'İlla men tabe ve amene ve amile salihan fe ulaike yedhulunel cennete ve la yuzlemune şey\'a.', 'Ancak tevbe[1] edip,  iman eden ve salihatı yapanlar[2] hariç. İşte onlar Cennet\'e girecekler ve onlara hiçbir şekilde haksızlık yapılmayacaktır.', 'الا من تاب وامن وعمل صلحا فاوليك يدخلون الجنة ولا يظلمون شيا'),
(2311, 19, 61, 'جَنَّاتِ عَدْنٍۨ  الَّت۪ي وَعَدَ الرَّحْمٰنُ عِبَادَهُ بِالْغَيْبِۜ اِنَّهُ كَانَ وَعْدُهُ مَأْتِياًّ', 'Cennati adninilleti vaader rahmanu ibadehu bil gayb, innehu kane va\'duhu me\'tiyya.', 'Rahman,  kullarına gıyaben Adn Cennetleri söz verdi. Kuşkusuz O\'nun sözü gerçekleşecektir.', 'جنت عدن التي وعد الرحمن عباده بالغيب انه كان وعده ماتيا'),
(2312, 19, 62, 'لَا يَسْمَعُونَ ف۪يهَا لَغْواً اِلَّا سَلَاماًۜ وَلَهُمْ رِزْقُهُمْ ف۪يهَا بُكْرَةً وَعَشِياًّ', 'La yesmeune fiha lagven illa selama, ve lehum rızkuhum fiha bukreten ve aşiyya.', 'Onlar,  orada boş söz işitmezler. Ancak \"selam\"[1] işitirler. Ve orada,  onların sabah akşam[2] rızıkları vardır.', 'لا يسمعون فيها لغوا الا سلما ولهم رزقهم فيها بكرة وعشيا'),
(2313, 19, 63, 'تِلْكَ الْجَنَّةُ الَّت۪ي نُورِثُ مِنْ عِبَادِنَا مَنْ كَانَ تَقِياًّ', 'Tilkel cennetulleti nurisu min ibadina men kane takıyya.', 'İşte bu,  kullarımızdan takva sahibi olanlara miras olarak vereceğimiz Cennet\'tir.', 'تلك الجنة التي نورث من عبادنا من كان تقيا'),
(2314, 19, 64, 'وَمَا نَتَنَزَّلُ اِلَّا بِاَمْرِ رَبِّكَۚ لَهُ مَا بَيْنَ اَيْد۪ينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِياًّۚ', 'Ve ma netenezzelu illa bi emri rabbik, lehu ma beyne eydina ve ma halfena ve ma beyne zalik, ve ma kane rabbuke nesiyya.', 'Biz,  Rabb\'inin emri olmaksızın inmeyiz. Önümüzdeki,  arkamızdaki[1] ve bunların arasında olan her şey O\'na aittir. Rabb\'in unutkan değildir.', 'وما نتنزل الا بامر ربك له ما بين ايدينا وما خلفنا وما بين ذلك وما كان ربك نسيا'),
(2315, 19, 65, 'رَبُّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِه۪ۜ هَلْ تَعْلَمُ لَهُ سَمِياًّ۟', 'Rabbus semavati vel ardı ve ma beynehuma fa\'budhu vastabir li ibadetih, hel ta\'lemu lehu semiyya.', 'Göklerin,  yerin ve ikisinin arasındakilerin Rabb\'idir. Öyle ise yalnızca O\'na kul ol ve kulluğunda sabırlı ol. İsmi O\'nunla anılmaya değer bir başkasını biliyor musun?', 'رب السموت والارض وما بينهما فاعبده واصطبر لعبادته هل تعلم له سميا'),
(2316, 19, 66, 'وَيَقُولُ الْاِنْسَانُ ءَاِذَا مَا مِتُّ لَسَوْفَ اُخْرَجُ حَياًّ', 'Ve yekulul insanu e iza ma mittu le sevfe uhracu hayya.', 'İnsan: \"Öldükten sonra gerçekten yeniden diriltilecek miyim?\" diyor.', 'ويقول الانسن اذا ما مت لسوف اخرج حيا'),
(2317, 19, 67, 'اَوَلَا يَذْكُرُ الْاِنْسَانُ اَنَّا خَلَقْنَاهُ مِنْ قَبْلُ وَلَمْ يَكُ شَيْـٔاً', 'E ve la yezkurul insanu enna halaknahu min kablu ve lem yeku şey\'a.', 'Oysaki daha önce hiçbir şey değilken,  kendisini yoktan var ettiğimizi düşünmüyor mu?', 'اولا يذكر الانسن انا خلقنه من قبل ولم يك شيا'),
(2318, 19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَالشَّيَاط۪ينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِياًّۚ', 'Fe ve rabbike le nahşurennehum veş şeyatine summe le nuhdırannehum havle cehenneme cisiyya.', 'Rabb\'ine ant olsun ki,  onları ve şeytanları[1] kesinlikle bir araya toplayacağız. Sonra onları Cehennem\'in kenarında diz üstü çökmüş olarak hazır tutacağız.', 'فوربك لنحشرنهم والشيطين ثم لنحضرنهم حول جهنم جثيا'),
(2319, 19, 69, 'ثُمَّ لَنَنْزِعَنَّ مِنْ كُلِّ ش۪يعَةٍ اَيُّهُمْ اَشَدُّ عَلَى الرَّحْمٰنِ عِتِياًّۚ', 'Summe le nenzianne min kulli şiatin eyyuhum eşeddu aler rahmani ıtiyya.', 'Sonra,  her topluluktan,  Rahman\'a karşı kim başkaldırmışsa onları mutlaka ortaya çıkaracağız.', 'ثم لننزعن من كل شيعة ايهم اشد علي الرحمن عتيا'),
(2320, 19, 70, 'ثُمَّ لَنَحْنُ اَعْلَمُ بِالَّذ۪ينَ هُمْ اَوْلٰى بِهَا صِلِياًّ', 'Summe le nahnu a\'lemu billezine hum evla biha sıliyya.', 'Sonra Biz,  onu[1] kimlerin hak ettiğini elbette daha iyi biliriz.', 'ثم لنحن اعلم بالذين هم اولي بها صليا'),
(2321, 19, 71, 'وَاِنْ مِنْكُمْ اِلَّا وَارِدُهَاۚ كَانَ عَلٰى رَبِّكَ حَتْماً مَقْضِياًّۚ', 'Ve in minkum illa variduha, kane ala rabbike hatmen makdıyya.', 'Sizden oraya[1] gelmeyecek hiç kimse yoktur. Bu Rabb\'inin üzerine aldığı kesinleşmiş bir yargıdır.[2]', 'وان منكم الا واردها كان علي ربك حتما مقضيا'),
(2322, 19, 72, 'ثُمَّ نُنَجِّي الَّذ۪ينَ اتَّقَوْا وَنَذَرُ الظَّالِم۪ينَ ف۪يهَا جِثِياًّ', 'Summe nuneccillezinettekav ve nezeruz zalimine fiha cisiyya.', 'Sonra Biz takva sahiplerini kurtuluşa erdireceğiz. Ve zalimleri,  orada diz üstü çökmüş halde bırakacağız.', 'ثم ننجي الذين اتقوا ونذر الظلمين فيها جثيا'),
(2323, 19, 73, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍ قَالَ الَّذ۪ينَ كَفَرُوا لِلَّذ۪ينَ اٰمَنُٓواۙ اَيُّ الْفَر۪يقَيْنِ خَيْرٌ مَقَاماً وَاَحْسَنُ نَدِياًّ', 'Ve iza tutla aleyhim ayatuna beyyinatin kalellezine keferu lillezine amenu eyyul ferikayni hayrun makamen ve ahsenu nediyya.', 'Açıklayıcı kanıt içeren ayetlerimiz onlara okunduğu zaman[1],  Kafirler,  iman edenlere; \"İki gruptan[2] hangisi konumu itibariyle daha hayırlı,  çevresi bakımından daha itibarlıdır?\" dediler.', 'واذا تتلي عليهم ايتنا بينت قال الذين كفروا للذين امنوا اي الفريقين خير مقاما واحسن نديا'),
(2324, 19, 74, 'وَكَمْ اَهْلَكْنَا قَبْلَهُمْ مِنْ قَرْنٍ هُمْ اَحْسَنُ اَثَاثاً وَرِءْياً', 'Ve kem ehlekna kablehum min karnin hum ahsenu esasen ve ri\'ya.', 'Oysa onlardan önce,  mal ve gösterişçe daha iyi olan nice nesilleri yok ettik.', 'وكم اهلكنا قبلهم من قرن هم احسن اثثا وريا'),
(2325, 19, 75, 'قُلْ مَنْ كَانَ فِي الضَّلَالَةِ فَلْيَمْدُدْ لَهُ الرَّحْمٰنُ مَداًّۚ حَتّٰٓى اِذَا رَاَوْا مَا يُوعَدُونَ اِمَّا الْعَذَابَ وَاِمَّا السَّاعَةَۜ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَكَاناً وَاَضْعَفُ جُنْداً', 'Kul men kane fid dalaleti fel yemdud lehur rahmanu medda, hatta iza raev ma yuadune immel azabe ve immes saah, fe se ya\'lemune men huve şerrun mekanen ve ad\'afu cunda.', 'De ki: \"Kim sapkınlıkta ise,  Rahman,  ona vaat edilen şeyi; azabı veya Sa\'at\'i görecekleri zamana kadar,  zamanı uzatarak süre tanır. Böylece kimin yerce daha kötü ve taraftarca daha zayıf olduğunu yakında bilecekler.\"', 'قل من كان في الضللة فليمدد له الرحمن مدا حتي اذا راوا ما يوعدون اما العذاب واما الساعة فسيعلمون من هو شر مكانا واضعف جندا'),
(2326, 19, 76, 'وَيَز۪يدُ اللّٰهُ الَّذ۪ينَ اهْتَدَوْا هُدًىۜ وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِنْدَ رَبِّكَ ثَوَاباً وَخَيْرٌ مَرَداًّ', 'Ve yezidullahullezinehtedev huda, vel bakıyatus salihatu hayrun inde rabbike sevaben ve hayrun meredda.', 'Allah,  doğru yola yönelenleri,  doğru yola iletir. Yapılmış iyi ve yararlı işler Rabb\'inin yanında hem karşılık bakımından hem de sonuç bakımından hayırlı olandır.', 'ويزيد الله الذين اهتدوا هدي والبقيت الصلحت خير عند ربك ثوابا وخير مردا'),
(2327, 19, 77, 'اَفَرَاَيْتَ الَّذ۪ي كَفَرَ بِاٰيَاتِنَا وَقَالَ لَاُو۫تَيَنَّ مَالاً وَوَلَداًۜ', 'E fe raeytellezi kefere bi ayatina ve kale le uteyenne malen ve veleda.', 'Ayetlerimizi inkar edip,  yine de \"Bana kesinlikle mal ve evlat verilecek.\" diyen kimseyi[1] görüyor musun?', 'افريت الذي كفر بايتنا وقال لاوتين مالا وولدا'),
(2328, 19, 78, 'اَطَّـلَعَ الْغَيْبَ اَمِ اتَّخَذَ عِنْدَ الرَّحْمٰنِ عَهْداًۙ', 'Ettalaal gaybe emittehaze inder rahmani ahda.', 'O,  gaybı mı biliyor? Yoksa Rahman\'dan bir söz mü aldı?', 'اطلع الغيب ام اتخذ عند الرحمن عهدا'),
(2329, 19, 79, 'كَلَّاۜ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَداًّۙ', 'Kella, se nektubu ma yekulu ve nemuddu lehu minel azabi medda.', 'Hayır! Onun söylediklerini yazacağız. Ve ona azabı uzattıkça uzatacağız.', 'كلا سنكتب ما يقول ونمد له من العذاب مدا'),
(2330, 19, 80, 'وَنَرِثُهُ مَا يَقُولُ وَيَأْت۪ينَا فَرْداً', 'Ve nerisuhu ma yekulu ve ye\'tina ferda.', 'Ve onun söylediği şeylere Biz mirasçı olacağız.[1] Ve o Bize tek başına gelecek.', 'ونرثه ما يقول وياتينا فردا'),
(2331, 19, 81, 'وَاتَّخَذُوا مِنْ دُونِ اللّٰهِ اٰلِهَةً لِيَكُونُوا لَهُمْ عِزاًّۙ', 'Vettehazu min dunillahi aliheten li yekunu lehum ızza.', 'Ve onlar,  kendileri için bir izzet[1] olsun diye Allah\'tan başka ilahlar edindiler.', 'واتخذوا من دون الله الهة ليكونوا لهم عزا'),
(2332, 19, 82, 'كَلَّاۜ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِداًّ۟', 'Kella, se yekfurune bi ibadetihim ve yekunune aleyhim dıdda.', 'Hayır! İlah edinilenler,  onların kulluklarını inkar edecekler ve onlara düşman kesilecekler.', 'كلا سيكفرون بعبادتهم ويكونون عليهم ضدا'),
(2333, 19, 83, 'اَلَمْ تَرَ اَنَّٓا اَرْسَلْنَا الشَّيَاط۪ينَ عَلَى الْكَافِر۪ينَ تَؤُزُّهُمْ اَزاًّۙ', 'E lem tere enna erselneş şeyatine alel kafirine teuzzuhum ezza.', 'Görmüyor musun? Biz,  Kafirlerin üzerine,  onları tahrik ederek kışkırtan şeytanları saldık.', 'الم تر انا ارسلنا الشيطين علي الكفرين توزهم ازا'),
(2334, 19, 84, 'فَلَا تَعْجَلْ عَلَيْهِمْۜ اِنَّمَا نَعُدُّ لَهُمْ عَداًّۚ', 'Fe la ta\'cel aleyhim, innema neuddu lehum adda.', 'Öyleyse onlar için acele etme.[1] Onların günlerinin hesabını yapıyoruz.', 'فلا تعجل عليهم انما نعد لهم عدا'),
(2335, 19, 85, 'يَوْمَ نَحْشُرُ الْمُتَّق۪ينَ اِلَى الرَّحْمٰنِ وَفْداًۙ', 'Yevme nahşurul muttekine iler rahmani vefda.', 'O gün takva sahiplerini Rahman\'ın huzurunda konuk olarak toplayacağız.', 'يوم نحشر المتقين الي الرحمن وفدا'),
(2336, 19, 86, 'وَنَسُوقُ الْمُجْرِم۪ينَ اِلٰى جَهَنَّمَ وِرْداًۢ', 'Ve nesukul mucrimine ila cehenneme virda.', 'Mücrimleri[1] de susamış olarak[2] Cehenneme süreceğiz.', 'ونسوق المجرمين الي جهنم وردا'),
(2337, 19, 87, 'لَا يَمْلِكُونَ الشَّفَاعَةَ اِلَّا مَنِ اتَّخَذَ عِنْدَ الرَّحْمٰنِ عَهْداًۢ', 'La yemlikuneş şefaate illa menittehaze inder rahmani ahda.', 'Rahman\'ın yanında bir \"ahd\" edinmiş olan kimse hariç,  bir şefaate[1] sahip olamayacaklar.[2]', 'لا يملكون الشفعة الا من اتخذ عند الرحمن عهدا'),
(2338, 19, 88, 'وَقَالُوا اتَّخَذَ الرَّحْمٰنُ وَلَداًۜ', 'Ve kaluttehazer rahmanu veleda.', '\"Rahman bir çocuk edindi.\" dediler.', 'وقالوا اتخذ الرحمن ولدا'),
(2339, 19, 89, 'لَقَدْ جِئْتُمْ شَيْـٔاً اِداًّۙ', 'Lekad ci\'tum şey\'en idda.', 'Ant olsun ki,  siz çok kötü bir iddiada bulundunuz.', 'لقد جيتم شيا ادا'),
(2340, 19, 90, 'تَكَادُ السَّمٰوَاتُ يَتَفَطَّرْنَ مِنْهُ وَتَنْشَقُّ الْاَرْضُ وَتَخِرُّ الْجِبَالُ هَداًّۙ', 'Tekadus semavatu yetefattarne minhu ve tenşakkul ardu ve tehırrul cibalu hedda.', 'Neredeyse gökler çatlayacak,  yer yarılacak ve dağlar gürültü ile devrilecekti.', 'تكاد السموت يتفطرن منه وتنشق الارض وتخر الجبال هدا'),
(2341, 19, 91, 'اَنْ دَعَوْا لِلرَّحْمٰنِ وَلَداًۚ', 'En deav lir rahmani veleda.', 'Rahman\'a bir çocuk isnat ettiler diye.', 'ان دعوا للرحمن ولدا'),
(2342, 19, 92, 'وَمَا يَنْبَغ۪ي لِلرَّحْمٰنِ اَنْ يَتَّخِذَ وَلَداًۜ', 'Ve ma yenbagi lir rahmani en yettehıze veleda.', 'Oysa Rahman\'a çocuk edinmek yaraşmaz.', 'وما ينبغي للرحمن ان يتخذ ولدا'),
(2343, 19, 93, 'اِنْ كُلُّ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِ اِلَّٓا اٰتِي الرَّحْمٰنِ عَبْداًۜ', 'İn kullu men fis semavati vel ardı illa atir rahmani abda.', 'Göklerde ve yerde bulunan herkes Rahman\'a yalnızca kul olarak gelecek.', 'ان كل من في السموت والارض الا اتي الرحمن عبدا'),
(2344, 19, 94, 'لَقَدْ اَحْصٰيهُمْ وَعَدَّهُمْ عَداًّۜ', 'Lekad ahsahum ve addehum adda.', 'Ant olsun ki,  onların tamamını kuşatmış ve bir bir tespit etmiştir.', 'لقد احصيهم وعدهم عدا'),
(2345, 19, 95, 'وَكُلُّهُمْ اٰت۪يهِ يَوْمَ الْقِيٰمَةِ فَرْداً', 'Ve kulluhum atihi yevmel kıyameti ferda.', 'Onların hepsi,  Kıyamet günü O\'na tek başına gelecektir.', 'وكلهم اتيه يوم القيمة فردا'),
(2346, 19, 96, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَيَجْعَلُ لَهُمُ الرَّحْمٰنُ وُداًّ', 'İnnellezine amenu ve amilus salihati se yec\'alu lehumur rahmanu vudda.', 'İman eden ve salihatı yapanları[1],  Rahman sevilenler kılacaktır.', 'ان الذين امنوا وعملوا الصلحت سيجعل لهم الرحمن ودا'),
(2347, 19, 97, 'فَاِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ الْمُتَّق۪ينَ وَتُنْذِرَ بِه۪ قَوْماً لُداًّ', 'Fe innema yessernahu bi lisanike li tubeşşire bihil muttekine ve tunzire bihi kavmen ludda.', 'Böylece Biz onu[1],  kendisi ile takva sahiplerini müjdelemen ve inat eden bir halkı uyarabilmen için senin dilinde kolaylaştırdık.', 'فانما يسرنه بلسانك لتبشر به المتقين وتنذر به قوما لدا');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2348, 19, 98, 'وَكَمْ اَهْلَكْنَا قَبْلَهُمْ مِنْ قَرْنٍۜ هَلْ تُحِسُّ مِنْهُمْ مِنْ اَحَدٍ اَوْ تَسْمَعُ لَهُمْ رِكْزاً', 'Ve kem ehlekna kablehum min karn, hel tuhıssu minhum min ehadin ev tesmeu lehum rikza.', 'Onlardan önce nice nesilleri yok ettik. Onlardan herhangi birilerinin varlığını hissediyor musun? Veya onlardan en küçük bir ses duyabiliyor musun?', 'وكم اهلكنا قبلهم من قرن هل تحس منهم من احد او تسمع لهم ركزا'),
(2349, 20, 1, 'طٰهٰۜ', 'Ta, ha.', 'Ta. Ha.', 'طه'),
(2350, 20, 2, 'مَٓا اَنْزَلْنَا عَلَيْكَ الْقُرْاٰنَ لِتَشْقٰىۙ', 'Ma enzelna aleykel kur\'ane li teşka.', 'Biz,  bu Kur\'an\'ı sana güçlük çekesin diye indirmedik.', 'ما انزلنا عليك القران لتشقي'),
(2351, 20, 3, 'اِلَّا تَذْكِرَةً لِمَنْ يَخْشٰىۙ', 'İlla tezkireten li men yahşa.', 'Ancak huşu[1] duyan kimselere öğüt olsun diye indirdik.', 'الا تذكرة لمن يخشي'),
(2352, 20, 4, 'تَنْز۪يلاً مِمَّنْ خَلَقَ الْاَرْضَ وَالسَّمٰوَاتِ الْعُلٰىۜ', 'Tenzilen mimmen halakal arda ves semavatil ula.', 'Yeri ve yüce gökleri yaratan tarafından indirilmiştir.', 'تنزيلا ممن خلق الارض والسموت العلي'),
(2353, 20, 5, 'اَلرَّحْمٰنُ عَلَى الْعَرْشِ اسْتَوٰى', 'Er rahmanu alel arşisteva.', 'Rahman[1],  Arş üzerine isteva etmiştir.[2]', 'الرحمن علي العرش استوي'),
(2354, 20, 6, 'لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرٰى', 'Lehu ma fis semavati ve ma fil ardı ve ma beynehuma ve ma tahtes sera.', 'Göklerde ve yerde ne varsa ve bu ikisinin arasında ve nemli toprağın altında ne varsa O\'nundur.', 'له ما في السموت وما في الارض وما بينهما وما تحت الثري'),
(2355, 20, 7, 'وَاِنْ تَجْهَرْ بِالْقَوْلِ فَاِنَّهُ يَعْلَمُ السِّرَّ وَاَخْفٰى', 'Ve in techer bil kavli fe innehu ya\'lemus sirre ve ahfa.', 'Sözü açıkça söylesen de söylemesen de bil ki O,  gizliyi de saklıyı da bilir.[1]', 'وان تجهر بالقول فانه يعلم السر واخفي'),
(2356, 20, 8, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۜ  لَهُ الْاَسْمَٓاءُ الْحُسْنٰى', 'Allahu la ilahe illa huve, lehul esmaul husna.', 'Allah,  kendisinden başka ilah olmayandır. En \"iyi isimler\"[1] yalnızca O\'nundur.', 'الله لا اله الا هو له الاسما الحسني'),
(2357, 20, 9, 'وَهَلْ اَتٰيكَ حَد۪يثُ مُوسٰىۢ', 'Ve hel etake hadisu musa.', 'Sana Musa\'nın hadisi[1] ulaştı mı?', 'وهل اتيك حديث موسي'),
(2358, 20, 10, 'اِذْ رَاٰ نَاراً فَقَالَ لِاَهْلِهِ امْكُـثُٓوا اِنّ۪ٓي اٰنَسْتُ نَاراً لَعَلّ۪ٓي اٰت۪يكُمْ مِنْهَا بِقَبَسٍ اَوْ اَجِدُ عَلَى النَّارِ هُدًى', 'İz rea naren fe kale li ehlihimkusu inni anestu naren lealli atikum minha bi kabesin ev ecidu alen nari huda.', 'Hani o bir ateş görmüş ve yanındakilere: \"Ben bir ateş gördüm. Bekleyin! Belki ondan size bir kor getiririm veya ateşin yanında bir yol gösteren bulurum.\" demişti.', 'اذ را نارا فقال لاهله امكثوا اني انست نارا لعلي اتيكم منها بقبس او اجد علي النار هدي'),
(2359, 20, 11, 'فَلَمَّٓا اَتٰيهَا نُودِيَ يَا مُوسٰى', 'Fe lemma etaha nudiye ya musa.', 'Oraya varınca,  \"Ey Musa!\" diye seslenildi.', 'فلما اتيها نودي يموسي'),
(2360, 20, 12, 'اِنّ۪ٓي اَنَا۬ رَبُّكَ فَاخْلَعْ نَعْلَيْكَۚ اِنَّكَ بِالْوَادِ الْمُقَدَّسِ طُوًىۜ', 'İnni ene rabbuke fehla\' na\'leyk, inneke bil vadil mukaddesi tuva.', '\"Ben senin Rabb\'inim. Şimdi ayakkabılarını çıkar[1]. Sen temizlenmiş vadide,  Tuva\'dasın.[2]\"', 'اني انا ربك فاخلع نعليك انك بالواد المقدس طوي'),
(2361, 20, 13, 'وَاَنَا اخْتَرْتُكَ فَاسْتَمِـعْ لِمَا يُوحٰى', 'Ve enahtertuke festemi\' li ma yuha.', '\"Ben seni seçtim.[1] Öyleyse vahyolunanı dinle.\"', 'وانا اخترتك فاستمع لما يوحي'),
(2362, 20, 14, 'اِنَّـن۪ٓي اَنَا اللّٰهُ لَٓا اِلٰهَ اِلَّٓا اَنَا۬ فَاعْبُدْن۪يۙ وَاَقِمِ الصَّلٰوةَ لِذِكْر۪ي', 'İnneni enallahu la ilahe illa ene fa\'budni ve ekımis salate li zikri.', '\"Ben Allah\'ım. Benden başka ilah yoktur. Öyleyse yalnızca Bana kulluk et. Ve öğüdüm için salatı[1] ikame et.\"', 'انني انا الله لا اله الا انا فاعبدني واقم الصلوة لذكري'),
(2363, 20, 15, 'اِنَّ السَّاعَةَ اٰتِيَةٌ اَكَادُ اُخْف۪يهَا لِتُجْزٰى كُلُّ نَفْسٍ بِمَا تَسْعٰى', 'İnnes saate atiyetun ekadu uhfiha li tucza kullu nefsin bima tes\'a.', '\"Zamanını bildirmemiş olsam da herkesin yaptığının karşılığını görmesi için kuşkusuz ki o Sa\'at[1] gelecektir.\"', 'ان الساعة اتية اكاد اخفيها لتجزي كل نفس بما تسعي'),
(2364, 20, 16, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَنْ لَا يُؤْمِنُ بِهَا وَاتَّـبَعَ هَوٰيهُ فَتَرْدٰى', 'Fe la yesuddenneke anha men la yu\'minu biha vettebea hevahu fe terda.', '\"Öyleyse ona[1] inanmayan,  tutku ve kuruntusuna uyan kimse,  seni ondan[2] alıkoymasın. Yoksa helak olursun.\"', 'فلا يصدنك عنها من لا يومن بها واتبع هويه فتردي'),
(2365, 20, 17, 'وَمَا تِلْكَ بِيَم۪ينِكَ يَا مُوسٰى', 'Ve ma tilke bi yeminike ya musa.', '\"Sağ elindeki nedir ey Musa?\"', 'وما تلك بيمينك يموسي'),
(2366, 20, 18, 'قَالَ هِيَ عَصَايَۚ اَتَوَكَّـؤُ۬ا عَلَيْهَا وَاَهُشُّ بِهَا عَلٰى غَنَم۪ي وَلِيَ ف۪يهَا مَاٰرِبُ اُخْرٰى', 'Kale hiye asay, etevekkeu aleyha ve ehuşşu biha ala ganemi ve liye fiha mearibu uhra.', '\"O benim asamdır[1],  ben ona dayanırım. Ve onunla koyunlarıma yaprak silkelerim. Onda benim için başka yararlar da var.\" dedi.', 'قال هي عصاي اتوكوا عليها واهش بها علي غنمي ولي فيها مارب اخري'),
(2367, 20, 19, 'قَالَ اَلْقِهَا يَا مُوسٰى', 'Kale elkıha ya musa.', '\"Ey Musa,  onu yere at.\" dedi.', 'قال القها يموسي'),
(2368, 20, 20, 'فَاَلْقٰيهَا فَاِذَا هِيَ حَيَّةٌ تَسْعٰى', 'Fe elkaha fe iza hiye hayyetun tes\'a.', 'Musa onu atınca bir de ne görsün! Hızla hareket eden bir canlı[1] olmuştu.', 'فالقيها فاذا هي حية تسعي'),
(2369, 20, 21, 'قَالَ خُذْهَا وَلَا تَخَفْ۠ سَنُع۪يدُهَا س۪يرَتَهَا الْاُو۫لٰى', 'Kale huzha ve la tehaf se nuiduha siretehel ula.', 'Allah: \"Onu tut,  korkma! Onu ilk haline döndüreceğiz.\" dedi.', 'قال خذها ولا تخف سنعيدها سيرتها الاولي'),
(2370, 20, 22, 'وَاضْمُمْ يَدَكَ اِلٰى جَنَاحِكَ تَخْرُجْ بَيْضَٓاءَ مِنْ غَيْرِ سُٓوءٍ اٰيَةً اُخْرٰىۙ', 'Vadmum yedeke ila cenahıke tahruc beydae min gayri suin ayeten uhra.', 'Allah: \"Elini koynuna sok. Başka bir ayet[1] olarak,  kusursuz bir beyazlıkta çıksın.\"', 'واضمم يدك الي جناحك تخرج بيضا من غير سو اية اخري'),
(2371, 20, 23, 'لِنُرِيَكَ مِنْ اٰيَاتِنَا الْكُبْرٰىۚ', 'Li nuriyeke min ayatinel kubra.', '\"Bununla daha büyük ayetlerimizden[1] bazılarını sana gösterelim.\"', 'لنريك من ايتنا الكبري'),
(2372, 20, 24, 'اِذْهَبْ اِلٰى فِرْعَوْنَ اِنَّهُ طَغٰى۟', 'İzheb ila fir\'avne innehu taga.', '\"Firavuna git! Çünkü o azgınlaştı.\"', 'اذهب الي فرعون انه طغي'),
(2373, 20, 25, 'قَالَ رَبِّ اشْرَحْ ل۪ي صَدْر۪يۙ', 'Kale rabbişrah li sadri.', '\"Rabbim! Göğsüme genişlik ver.\" dedi.', 'قال رب اشرح لي صدري'),
(2374, 20, 26, 'وَيَسِّرْ ل۪ٓي اَمْر۪يۙ', 'Ve yessir li emri.', '\"Ve işimi kolaylaştır.\"', 'ويسر لي امري'),
(2375, 20, 27, 'وَاحْلُلْ عُقْدَةً مِنْ لِسَان۪يۙ', 'Vahlul ukdeten min lisani.', '\"Dilimden düğümü çöz.\"', 'واحلل عقدة من لساني'),
(2376, 20, 28, 'يَفْقَهُوا قَوْل۪يۖ', 'Yefkahu kavli.', '\"Ki söyleyeceklerimi anlasınlar.\"', 'يفقهوا قولي'),
(2377, 20, 29, 'وَاجْعَلْ ل۪ي وَز۪يراً مِنْ اَهْل۪يۙ', 'Vec\'al li veziren min ehli.', '\"Bana,  yakınlarımdan bir yardımcı ver.\"', 'واجعل لي وزيرا من اهلي'),
(2378, 20, 30, 'هٰرُونَ اَخ۪يۚ', 'Harune ahi.', '\"Kardeşim Harun\'u.\"', 'هرون اخي'),
(2379, 20, 31, 'اُشْدُدْ بِه۪ٓ اَزْر۪يۙ', 'Uşdud bihi ezri.', '\"Onunla gücüme güç kat.\"', 'اشدد به ازري'),
(2380, 20, 32, 'وَاَشْرِكْهُ ف۪ٓي اَمْر۪يۙ', 'Ve eşrikhu fi emri.', '\"Onu görevime ortak et.\"', 'واشركه في امري'),
(2381, 20, 33, 'كَيْ نُسَبِّحَكَ كَث۪يراًۙ', 'Key nusebbihake kesira.', '\"Ki Seni çok tesbih[1] edelim.\"', 'كي نسبحك كثيرا'),
(2382, 20, 34, 'وَنَذْكُرَكَ كَث۪يراًۜ', 'Ve nezkureke kesira.', '\"Seni çokça öğütleyelim.\"', 'ونذكرك كثيرا'),
(2383, 20, 35, 'اِنَّكَ كُنْتَ بِنَا بَص۪يراً', 'İnneke kunte bina basira.', '\"Sen,  bizim her halimizi görmektesin.\"', 'انك كنت بنا بصيرا'),
(2384, 20, 36, 'قَالَ قَدْ اُو۫ت۪يتَ سُؤْلَكَ يَا مُوسٰى', 'Kale kad utite su\'leke ya musa.', '\"Ey Musa! İstediğin sana verildi.\" dedi.', 'قال قد اوتيت سولك يموسي'),
(2385, 20, 37, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً اُخْرٰىۙ', 'Ve lekad menenna aleyke merreten uhra.', '\"Gerçek şu ki,  Biz sana daha önce de lütufta bulunmuştuk.\"', 'ولقد مننا عليك مرة اخري'),
(2386, 20, 38, 'اِذْ اَوْحَيْنَٓا اِلٰٓى اُمِّكَ مَا يُوحٰىۙ', 'İz evhayna ila ummike ma yuha.', '\"Hani annene vahyedilmesi gerekeni vahyetmiştik.\"', 'اذ اوحينا الي امك ما يوحي'),
(2387, 20, 39, 'اَنِ اقْذِف۪يهِ فِي التَّابُوتِ فَاقْذِف۪يهِ فِي الْيَمِّ فَلْيُلْقِهِ الْيَمُّ بِالسَّاحِلِ يَأْخُذْهُ عَدُوٌّ ل۪ي وَعَدُوٌّ لَهُۜ وَاَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِنّ۪يۚ وَلِتُصْنَعَ عَلٰى عَيْن۪يۢ', 'Enıkzifihi fit tabuti fakzifihi fil yemmi felyulkıhil yemmu bis sahıli ye\'huzhu aduvvun li ve aduvvun leh, ve elkaytu aleyke mehabbeten minni ve li tusnea ala ayni.', '\"Onu sandığa koy da suya[1] bırak. Su da onu kıyıya bıraksın. Benim ve onun düşmanı,  onu alsın.\" Ve \"korumam altında yetiştirilmen için seni sevimli biri yaptım.\"', 'ان اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل ياخذه عدو لي وعدو له والقيت عليك محبة مني ولتصنع علي عيني'),
(2388, 20, 40, 'اِذْ تَمْش۪ٓي اُخْتُكَ فَتَقُولُ هَلْ اَدُلُّكُمْ عَلٰى مَنْ يَكْفُلُهُۜ فَرَجَعْنَاكَ اِلٰٓى اُمِّكَ كَيْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَۜ وَقَتَلْتَ نَفْساً فَنَجَّيْنَاكَ مِنَ الْغَمِّ وَفَتَنَّاكَ فُتُوناً۠ فَلَبِثْتَ سِن۪ينَ ف۪ٓي اَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلٰى قَدَرٍ يَا مُوسٰى', 'İz temşi uhtuke fe tekulu hel edullukum ala men yekfuluh, fe reca\'nake ila ummike key takarre aynuha ve la tahzen, ve katelte nefsen fe necceynake minel gammi ve fetennake futuna, fe lebiste sinine fi ehli medyene summe ci\'te ala kaderin ya musa.', '\"Hani kız kardeşin gidip,  \"Size,  ona bakacak birisini bulmanızda yardımcı olayım mı?\" demişti. Böylece gözü aydın olsun ve üzülmesin diye seni annene geri döndürdük. Ve birisini öldürmüştün de seni sıkıntıdan kurtarmıştık. Ve seni çeşitli sınavlarla sınav yaptık. Sonra yıllarca Medyen halkı içinde kaldın. Sonra takdirimiz gereği şimdi buradasın ey Musa!\"', 'اذ تمشي اختك فتقول هل ادلكم علي من يكفله فرجعنك الي امك كي تقر عينها ولا تحزن وقتلت نفسا فنجينك من الغم وفتنك فتونا فلبثت سنين في اهل مدين ثم جيت علي قدر يموسي'),
(2389, 20, 41, 'وَاصْطَنَعْتُكَ لِنَفْس۪يۚ', 'Vastana\'tuke li nefsi.', '\"Seni Kendim için yetiştirdim.\"', 'واصطنعتك لنفسي'),
(2390, 20, 42, 'اِذْهَبْ اَنْتَ وَاَخُوكَ بِاٰيَات۪ي وَلَا تَنِيَا ف۪ي ذِكْر۪يۚ', 'İzheb ente ve ehuke bi ayati ve la teniya fi zikri.', '\"Sen ve kardeşin,  ayetlerimle gidin. Öğütlerimi duyurmada gevşeklik göstermeyin.\"', 'اذهب انت واخوك بايتي ولا تنيا في ذكري'),
(2391, 20, 43, 'اِذْهَبَٓا اِلٰى فِرْعَوْنَ اِنَّهُ طَغٰىۚ', 'İzheba ila fir\'avne innehu taga.', '\"İkiniz de Firavun\'a gidin. Kuşkusuz o azgınlaştı.\"', 'اذهبا الي فرعون انه طغي'),
(2392, 20, 44, 'فَقُولَا لَهُ قَوْلاً لَيِّناً لَعَلَّهُ يَتَذَكَّرُ اَوْ يَخْشٰى', 'Fe kula lehu kavlen leyyinen leallehu yetezekkeru ev yahşa.', '\"Ona yumuşak söz söyleyin. Umulur ki öğüt alır veya huşu[1] duyar.\"', 'فقولا له قولا لينا لعله يتذكر او يخشي'),
(2393, 20, 45, 'قَالَا رَبَّـنَٓا اِنَّـنَا نَخَافُ اَنْ يَفْرُطَ عَلَيْنَٓا اَوْ اَنْ يَطْغٰى', 'Kala rabbena innena nehafu en yefruta aleyna ev en yatga.', '\"Rabb\'imiz! Onun bize karşı aşırı gitmesinden veya azgınlık yapmasından çekiniyoruz.\" dediler.', 'قالا ربنا اننا نخاف ان يفرط علينا او ان يطغي'),
(2394, 20, 46, 'قَالَ لَا تَخَافَٓا اِنَّن۪ي مَعَكُمَٓا اَسْمَعُ وَاَرٰى', 'Kale la tehafa inneni meakuma esmau ve era.', '\"Korkmayın! Kuşkusuz Ben sizinle birlikteyim. İşitir ve görürüm.\" dedi.', 'قال لا تخافا انني معكما اسمع واري'),
(2395, 20, 47, 'فَأْتِيَاهُ فَقُولَٓا اِنَّا رَسُولَا رَبِّكَ فَاَرْسِلْ مَعَنَا بَن۪ٓي اِسْرَٓائ۪لَ وَلَا تُعَذِّبْهُمْۜ قَدْ جِئْنَاكَ بِاٰيَةٍ مِنْ رَبِّكَۜ وَالسَّلَامُ عَلٰى مَنِ اتَّـبَعَ الْهُدٰى', 'Fe\'tiyahu fe kula inna resula rabbike fe ersil meana beni israile ve la tuazzibhum, kad ci\'nake bi ayetin min rabbik, ves selamu ala menittebeal huda.', '\"Hemen ona gidin: \"Kuşkusuz ki biz Rabb\'inin iki resulüyüz. Artık İsrailoğulları\'nı bizimle gönder ve onlara azap etme. Doğrusu biz sana bir ayet[1] ile geldik. Selam[2] doğru yola[3] uyanlaradır.\"', 'فاتياه فقولا انا رسولا ربك فارسل معنا بني اسريل ولا تعذبهم قد جينك باية من ربك والسلم علي من اتبع الهدي'),
(2396, 20, 48, 'اِنَّا قَدْ اُو۫حِيَ اِلَيْنَٓا اَنَّ الْعَذَابَ عَلٰى مَنْ كَذَّبَ وَتَوَلّٰى', 'İnna kad uhıye ileyna ennel azabe ala men kezzebe ve tevella.', '\"Bize,  yalanlayıp aldırmayanların azaba uğrayacakları vahyolundu.\"', 'انا قد اوحي الينا ان العذاب علي من كذب وتولي'),
(2397, 20, 49, 'قَالَ فَمَنْ رَبُّكُمَا يَا مُوسٰى', 'Kale fe men rabbukuma ya musa.', 'Firavun: \"Ey Musa! Rabb\'iniz kimdir?\" dedi.', 'قال فمن ربكما يموسي'),
(2398, 20, 50, 'قَالَ رَبُّنَا الَّـذ۪ٓي اَعْطٰى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدٰى', 'Kale rabbunellezi a\'ta kulle şey\'in halkahu summe heda.', 'Musa: \"Bizim Rabb\'imiz her şeye yaradılışını[1] veren,  sonra da yol gösterendir.\" dedi.', 'قال ربنا الذي اعطي كل شي خلقه ثم هدي'),
(2399, 20, 51, 'قَالَ فَمَا بَالُ الْقُرُونِ الْاُو۫لٰى', 'Kale fe ma balul kurunil ula.', 'Firavun: \"Öyleyse ilk nesillerin durumu ne olacak?\" dedi.', 'قال فما بال القرون الاولي'),
(2400, 20, 52, 'قَالَ عِلْمُهَا عِنْدَ رَبّ۪ي ف۪ي كِتَابٍۚ لَا يَضِلُّ رَبّ۪ي وَلَا يَنْسٰىۘ', 'Kale ilmuha inde rabbi fi kitab, la yadıllu rabbi ve la yensa.', '\"Onun bilgisi Rabb\'imin yanında yazılıdır. Rabb\'im yanlış yapmaz ve unutmaz.\" dedi.', 'قال علمها عند ربي في كتب لا يضل ربي ولا ينسي'),
(2401, 20, 53, 'اَلَّذ۪ي جَعَلَ لَكُمُ الْاَرْضَ مَهْداً وَسَلَكَ لَكُمْ ف۪يهَا سُبُلاً وَاَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءًۜ فَاَخْرَجْنَا بِه۪ٓ اَزْوَاجاً مِنْ نَبَاتٍ شَتّٰى', 'Ellezi ceale lekumul arda mehden ve seleke lekum fiha subulen ve enzele mines semai maa, fe ahrecna bihi ezvacen min nebatin şetta.', 'Yeryüzünü sizin için bir beşik yapan,  orada sizin için yollar açan ve gökten su indiren O\'dur. Onunla her türlü bitkiden çiftler[1] yetiştirdik.', 'الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السما ما فاخرجنا به ازوجا من نبات شتي'),
(2402, 20, 54, 'كُلُوا وَارْعَوْا اَنْعَامَكُمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِاُو۬لِي النُّهٰى۟', 'Kulu ver\'av en\'amekum, inne fi zalike le ayatin li ulin nuha.', 'Yiyin ve hayvanlarınızı otlatın. Bunda,  akıl sahipleri için ayetler[1] vardır.', 'كلوا وارعوا انعمكم ان في ذلك لايت لاولي النهي'),
(2403, 20, 55, 'مِنْهَا خَلَقْنَاكُمْ وَف۪يهَا نُع۪يدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً اُخْرٰى', 'Minha halaknakum ve fiha nuidukum ve minha nuhricukum tareten uhra.', 'Sizi ondan[1] yarattık. Ve sizi ona döndüreceğiz. Ve sizi oradan bir kere daha çıkaracağız.', 'منها خلقنكم وفيها نعيدكم ومنها نخرجكم تارة اخري'),
(2404, 20, 56, 'وَلَقَدْ اَرَيْنَاهُ اٰيَاتِنَا كُلَّهَا فَكَذَّبَ وَاَبٰى', 'Ve lekad ereynahu ayatina kulleha fe kezzebe ve eba.', 'Ant olsun ki; ayetlerimizin[1] hepsini ona[2] gösterdik. Buna rağmen yalanlamada diretti.', 'ولقد ارينه ايتنا كلها فكذب وابي'),
(2405, 20, 57, 'قَالَ اَجِئْتَنَا لِتُخْرِجَنَا مِنْ اَرْضِنَا بِسِحْرِكَ يَا مُوسٰى', 'Kale e ci\'tena li tuhricena min ardına bi sihrike ya musa.', '\"Ey Musa! Sen sihrinle bizi yurdumuzdan çıkarmak için mi geldin?\" dedi.', 'قال اجيتنا لتخرجنا من ارضنا بسحرك يموسي'),
(2406, 20, 58, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِثْلِه۪ فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِداً لَا نُخْلِفُهُ نَحْنُ وَلَٓا اَنْتَ مَكَاناً سُوًى', 'Fe le ne\'tiyenneke bi sıhrin mislihi fec\'al beynena ve beyneke mev\'ıden la nuhlifuhu nahnu ve la ente mekanen suva.', '\"O halde biz de sana,  senin sihrine benzer bir sihirle karşılık vereceğiz. Şimdi üzerinde birlikte anlaşacağımız uygun bir yer ve zaman belirle.\"', 'فلناتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا انت مكانا سوي'),
(2407, 20, 59, 'قَالَ مَوْعِدُكُمْ يَوْمُ الزّ۪ينَةِ وَاَنْ يُحْشَرَ النَّاسُ ضُحًى', 'Kale mev\'ıdukum yevmuz zineti ve en yuhşeren nasu duha.', '\"Sizinle buluşma zamanı,  ziynet[1] günü insanların toplanma zamanı olan kuşluk vakti olsun.\" dedi.', 'قال موعدكم يوم الزينة وان يحشر الناس ضحي'),
(2408, 20, 60, 'فَتَوَلّٰى فِرْعَوْنُ فَجَمَعَ كَيْدَهُ ثُمَّ اَتٰى', 'Fe tevella fir\'avnu fe cemea keydehu summe eta.', 'Bunun üzerine Firavun dönüp gitti ve yapacağı hileleri hazırlattıktan sonra belirlenen yere geldi.', 'فتولي فرعون فجمع كيده ثم اتي'),
(2409, 20, 61, 'قَالَ لَهُمْ مُوسٰى وَيْلَكُمْ لَا تَفْتَرُوا عَلَى اللّٰهِ كَذِباً فَيُسْحِتَكُمْ بِعَذَابٍۚ وَقَدْ خَابَ مَنِ افْتَرٰى', 'Kale lehum musa veylekum la tefteru alallahi keziben fe yushıtekum bi azab, ve kad habe meniftera.', 'Musa onlara: \"Yazıklar olsun size! Yalanlarınızla Allah\'a iftira etmeyin. Yoksa sizi azapla yok eder. İftira edenler,  gerçekten yok olmuştur.\"', 'قال لهم موسي ويلكم لا تفتروا علي الله كذبا فيسحتكم بعذاب وقد خاب من افتري'),
(2410, 20, 62, 'فَتَنَازَعُٓوا اَمْرَهُمْ بَيْنَهُمْ وَاَسَرُّوا النَّجْوٰى', 'Fe tenazeu emrehum beynehum ve eserrun necva.', 'Firavunun adamları fısıltı ile aralarında ne yapacaklarını tartıştılar.', 'فتنزعوا امرهم بينهم واسروا النجوي'),
(2411, 20, 63, 'قَالُٓوا اِنْ هٰذَانِ لَسَاحِرَانِ يُر۪يدَانِ اَنْ يُخْرِجَاكُمْ مِنْ اَرْضِكُمْ بِسِحْرِهِمَا وَيَذْهَبَا بِطَر۪يقَتِكُمُ الْمُثْلٰى', 'Kalu in hazani le sahirani yuridani en yuhricakum min ardıkum bi sihrihima ve yezheba bi tarikatikumul musla.', '\"Bu ikisi kesinlikle sihirbazdır. Sihirleriyle sizi yerinizden çıkarmak,  örnek yolunuzu[1] değiştirmek istiyorlar.\"', 'قالوا ان هذن لسحرن يريدان ان يخرجاكم من ارضكم بسحرهما ويذهبا بطريقتكم المثلي'),
(2412, 20, 64, 'فَاَجْمِعُوا كَيْدَكُمْ ثُمَّ ائْتُوا صَفاًّۚ وَقَدْ اَفْلَحَ الْيَوْمَ مَنِ اسْتَعْلٰى', 'Fe ecmiu keydekum summe\'tu saffa, ve kad eflehal yevme menista\'la.', '\"Şu halde bütün oyunlarınızı birleştirin,  sonra bir düzen içinde ortaya koyun. Bugün üstün gelen kesinlikle başarıyı elde etmiş olur.\"', 'فاجمعوا كيدكم ثم ايتوا صفا وقد افلح اليوم من استعلي'),
(2413, 20, 65, 'قَالُوا يَا مُوسٰٓى اِمَّٓا اَنْ تُلْقِيَ وَاِمَّٓا اَنْ نَكُونَ اَوَّلَ مَنْ اَلْقٰى', 'Kalu ya musa imma en tulkıye ve imma en nekune evvele men elka.', 'Sihirbazlar,  \"Ey Musa! Önce sen mi atacaksın,  yoksa biz mi atalım?\" dediler.', 'قالوا يموسي اما ان تلقي واما ان نكون اول من القي'),
(2414, 20, 66, 'قَالَ بَلْ اَلْقُواۚ فَاِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ اِلَيْهِ مِنْ سِحْرِهِمْ اَنَّهَا تَسْعٰى', 'Kale bel elku, fe iza hıbaluhum ve ısıyyuhum yuhayyelu ileyhi min sıhrihim enneha tes\'a.', 'Musa,  \"Buyurun,  önce siz atın.\" dedi. Yaptıkları büyüden dolayı attıkları sopa ve ip hızla hareket ediyormuş gibi göründü.', 'قال بل القوا فاذا حبالهم وعصيهم يخيل اليه من سحرهم انها تسعي'),
(2415, 20, 67, 'فَاَوْجَسَ ف۪ي نَفْسِه۪ خ۪يفَةً مُوسٰى', 'Fe evcese fi nefsihi hifeten musa.', 'Bunun üzerine Musa\'nın içine korku düştü.', 'فاوجس في نفسه خيفة موسي'),
(2416, 20, 68, 'قُلْنَا لَا تَخَفْ اِنَّكَ اَنْتَ الْاَعْلٰى', 'Kulna la tehaf inneke entel a\'la.', '\"Korkma! Kuşkusuz ki sen üstün geleceksin.\" dedik.', 'قلنا لا تخف انك انت الاعلي'),
(2417, 20, 69, 'وَاَلْقِ مَا ف۪ي يَم۪ينِكَ تَلْقَفْ مَا صَنَعُواۜ اِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍۜ وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ اَتٰى', 'Ve elkı ma fi yeminike telkaf ma sanau, innema sanau keydu sahır, ve la yuflihus sahıru haysu eta.', '\"Sağ elinde olanı at,  onların yaptığı şeyleri yutacak. Onların yaptıkları sihirbaz hilesinden başka bir şey değil. Ve sihirbazlar ne yaparlarsa yapsınlar kurtuluşa eremezler.\"', 'والق ما في يمينك تلقف ما صنعوا انما صنعوا كيد سحر ولا يفلح الساحر حيث اتي'),
(2418, 20, 70, 'فَاُلْقِيَ السَّحَرَةُ سُجَّداً قَالُٓوا اٰمَنَّا بِرَبِّ هٰرُونَ وَمُوسٰى', 'Fe ulkıyes seharatu succeden kalu amenna bi rabbi harune ve musa.', 'Bunun üzerine sihirbazlar,  secde edenler[1] olarak atıldılar.[2] Biz: \"Harun\'un ve Musa\'nın Rabb\'ine iman ettik.\" dediler.', 'فالقي السحرة سجدا قالوا امنا برب هرون وموسي'),
(2419, 20, 71, 'قَالَ اٰمَنْتُمْ لَهُ قَبْلَ اَنْ اٰذَنَ لَكُمْۜ  اِنَّهُ لَكَب۪يرُكُمُ الَّذ۪ي عَلَّمَكُمُ السِّحْرَۚ فَلَاُقَطِّعَنَّ اَيْدِيَكُمْ وَاَرْجُلَكُمْ مِنْ خِلَافٍ وَلَاُصَلِّبَنَّكُمْ ف۪ي جُذُوعِ النَّخْلِۘ وَلَتَعْلَمُنَّ اَيُّـنَٓا اَشَدُّ عَذَاباً وَاَبْقٰى', 'Kale amentum lehu kable en azene lekum, innehu le kebirukumullezi allemekumus sihr, fe le ukattıanne eydiyekum ve erculekum min hilafin ve le usallibennekum fi cuzuın nahli ve le ta\'lemunne eyyuna eşeddu azaben ve ebka.', 'Firavun,  \"Ben izin vermeden ona iman mı ettiniz? Kuşkusuz o,  size sihir öğreten hocanızdır. Kesinlikle ellerinizi ve ayaklarınızı çaprazlama keseceğim ve sizi hurma ağacının gövdesine asacağım. Ve böylece hangimizin azabının daha şiddetli ve kalıcı olduğunu mutlaka öğreneceksiniz.\" dedi.', 'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلاقطعن ايديكم وارجلكم من خلف ولاصلبنكم في جذوع النخل ولتعلمن اينا اشد عذابا وابقي'),
(2420, 20, 72, 'قَالُوا لَنْ نُؤْثِرَكَ عَلٰى مَا جَٓاءَنَا مِنَ الْبَيِّنَاتِ وَالَّذ۪ي فَطَرَنَا فَاقْضِ مَٓا اَنْتَ قَاضٍۜ اِنَّمَا تَقْض۪ي هٰذِهِ الْحَيٰوةَ الدُّنْيَاۜ', 'Kalu len nu\'sireke ala ma caena minel beyyinati vellezi fatarana fakdi ma ente kad, innema takdi hazihil hayated dunya.', '\"Bizim açımızdan,  ortaya konan bu kanıtlayıcı bilgiden sonra,  yaradılışımızın esaslarını belirleyen yaratıcıya karşı seni asla tercih etmeyiz. İstediğin şeyi yap. Senin hükmün ancak bu dünya hayatında geçer.\" dediler.', 'قالوا لن نوثرك علي ما جانا من البينت والذي فطرنا فاقض ما انت قاض انما تقضي هذه الحيوة الدنيا'),
(2421, 20, 73, 'اِنَّٓا اٰمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَايَانَا وَمَٓا اَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِۜ وَاللّٰهُ خَيْرٌ وَاَبْقٰى', 'İnna amenna bi rabbina li yagfire lena hatayana ve ma ekrehtena aleyhi mines sihr, vallahu hayrun ve ebka.', '\"Biz,  yanlışlarımız ve bize sihirle zorla yaptırdığın kötü şeyler için Rabb\'imizin bizi bağışlayacağına inanıyoruz. Allah hayırlı ve kalıcı olandır.\"', 'انا امنا بربنا ليغفر لنا خطينا وما اكرهتنا عليه من السحر والله خير وابقي'),
(2422, 20, 74, 'اِنَّهُ مَنْ يَأْتِ رَبَّهُ مُجْرِماً فَاِنَّ لَهُ جَهَنَّمَۜ   لَا يَمُوتُ ف۪يهَا وَلَا يَحْيٰى', 'İnnehu men ye\'ti rabbehu mucrimen fe inne lehu cehennem, la yemutu fiha ve la yahya.', 'Kim Rabb\'ine mücrim[1] olarak gelirse,  onun yeri Cehennem\'dir. Orada ne ölür ne de yaşar.', 'انه من يات ربه مجرما فان له جهنم لا يموت فيها ولا يحيي'),
(2423, 20, 75, 'وَمَنْ يَأْتِه۪ مُؤْمِناً قَدْ عَمِلَ الصَّالِحَاتِ فَاُو۬لٰٓئِكَ لَهُمُ الدَّرَجَاتُ الْعُلٰىۙ', 'Ve men ye\'tihi mu\'minen kad amiles salihati fe ulaike lehumud derecatul ula.', 'Ve kim O\'na bir mümin olarak salihatı yapmış şekilde gelirse,  işte böyle kimseler için yüksek makamlar vardır.', 'ومن ياته مومنا قد عمل الصلحت فاوليك لهم الدرجت العلي'),
(2424, 20, 76, 'جَنَّاتُ عَدْنٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ وَذٰلِكَ جَزٰٓؤُ۬ا مَنْ تَزَكّٰى۟', 'Cennatu adnin tecri min tahtihel enharu halidine fiha ve zalike cezau men tezekka.', 'İçinden ırmaklar akan Adn Cennetlerinde sürekli kalacaklar. İşte bu arınmış olanlara[1] verilecek karşılıktır.', 'جنت عدن تجري من تحتها الانهر خلدين فيها وذلك جزا من تزكي'),
(2425, 20, 77, 'وَلَقَدْ اَوْحَيْنَٓا اِلٰى مُوسٰٓى اَنْ اَسْرِ بِعِبَاد۪ي فَاضْرِبْ لَهُمْ طَر۪يقاً فِي الْبَحْرِ يَبَساًۚ لَا تَخَافُ دَرَكاً وَلَا تَخْشٰى', 'Ve lekad evhayna ila musa en esri bi ibadi fadrib lehum tarikan fil bahri yebesa, la tehafu dereken ve la tahşa.', 'Ant olsun ki,  Musa\'ya: \"Kullarımla geceleyin yola çık; onlara denizde kuru bir yol aç. Arkanızdan yetişecekler diye korkma,  Allah\'a olan bağlılığını kaybetme!\" diye vahyettik.', 'ولقد اوحينا الي موسي ان اسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخف دركا ولا تخشي'),
(2426, 20, 78, 'فَاَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِه۪ فَغَشِيَهُمْ مِنَ الْيَمِّ مَا غَشِيَهُمْۜ', 'Fe etbeahum fir\'avnu bi cunudihi fe gaşiyehum minel yemmi ma gaşiyehum.', 'Firavun hemen ordusu ile onların ardına düştü. Derken sudan üzerlerine kapanan kapandı.', 'فاتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم'),
(2427, 20, 79, 'وَاَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدٰى', 'Ve edalle fir\'avnu kavmehu ve ma heda.', 'Firavun halkını sapkınlıkta bıraktı; onları doğru yola yöneltmedi.', 'واضل فرعون قومه وما هدي'),
(2428, 20, 80, 'يَا بَن۪ٓي اِسْرَٓائ۪لَ قَدْ اَنْجَيْنَاكُمْ مِنْ عَدُوِّكُمْ وَوٰعَدْنَاكُمْ جَانِبَ الطُّورِ الْاَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوٰى', 'Ya beni israile kad enceynakum min aduvvikum ve vaadnakum canibet turil eymene ve nezzelna aleykumul menne ves selva.', 'Ey İsrailoğulları! Sizi,  düşmanınızdan kurtarmış ve Tur\'un sağ yanında sizden söz almıştık. Ve size menn[1] ve bıldırcın bağışlamıştık.[2]', 'يبني اسريل قد انجينكم من عدوكم ووعدنكم جانب الطور الايمن ونزلنا عليكم المن والسلوي'),
(2429, 20, 81, 'كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَلَا تَطْغَوْا ف۪يهِ فَيَحِلَّ عَلَيْكُمْ غَضَب۪يۚ وَمَنْ يَحْلِلْ عَلَيْهِ غَضَب۪ي فَقَدْ هَوٰى', 'Kulu min tayyibati ma rezaknakum ve la tatgav fihi fe yahılle aleykum gadabi ve men yahlil aleyhi gadabi fe kad heva.', 'Size rızık olarak verdiğimiz temiz şeyleri yiyin. Bu konuda aşırılık yapmayın. Yoksa gazabıma uğrarsınız. Kim gazabıma uğrarsa,  kesinlikle o tepetaklak olmuştur.', 'كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوي'),
(2430, 20, 82, 'وَاِنّ۪ي لَغَفَّارٌ لِمَنْ تَابَ وَاٰمَنَ وَعَمِلَ صَالِحاً ثُمَّ اهْتَدٰى', 'Ve inni le gaffarun li men tabe ve amene ve amile salihan summehteda.', 'Ben,  tevbe eden,  iman edip salihatı yapan[1],  doğru yolda olan kimseyi kesinlikle bağışlarım.', 'واني لغفار لمن تاب وامن وعمل صلحا ثم اهتدي'),
(2431, 20, 83, 'وَمَٓا اَعْجَلَكَ عَنْ قَوْمِكَ يَا مُوسٰى', 'Ve ma a\'celeke an kavmike ya musa.', '\"Ey Musa,  seni halkından aceleyle ayrılmaya sevk eden şey nedir?\"', 'وما اعجلك عن قومك يموسي'),
(2432, 20, 84, 'قَالَ هُمْ اُو۬لَٓاءِ عَلٰٓى اَثَر۪ي وَعَجِلْتُ اِلَيْكَ رَبِّ لِتَرْضٰى', 'Kale hum ulai ala eseri ve aciltu ileyke rabbi li terda.', 'Musa: \"Onlar,  benim yolumdalar. Acele etmemin nedeni,  Sen\'i hoşnut etmektir.\" dedi.', 'قال هم اولا علي اثري وعجلت اليك رب لترضي'),
(2433, 20, 85, 'قَالَ فَاِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنْ بَعْدِكَ وَاَضَلَّهُمُ السَّامِرِيُّ', 'Kale fe inna kad fetenna kavmeke min ba\'dike ve edallehumus samiriyy.', 'Allah: \"Biz,  halkını sınadık. Senden sonra Samiri onları saptırdı.\"', 'قال فانا قد فتنا قومك من بعدك واضلهم السامري'),
(2434, 20, 86, 'فَرَجَعَ مُوسٰٓى اِلٰى قَوْمِه۪ غَضْبَانَ اَسِفاًۚ قَالَ يَا قَوْمِ اَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْداً حَسَناًۜ اَفَطَالَ عَلَيْكُمُ الْعَهْدُ اَمْ اَرَدْتُمْ اَنْ يَحِلَّ عَلَيْكُمْ غَضَبٌ مِنْ رَبِّكُمْ فَاَخْلَفْتُمْ مَوْعِد۪ي', 'Fe recea musa ila kavmihi gadbane esifa, kale ya kavmi e lem yaıdkum rabbukum va\'den hasena, e fe tale aleykumul ahdu em eredtum en yahılle aleykum gadabun min rabbikum fe ahleftum mev\'ıdi.', 'Bunun üzerine Musa,  halkına öfkeli ve üzüntülü bir şekilde geri döndü: \"Ey halkım,  Rabb\'iniz size iyi bir söz vermedi mi? Şimdi bu süre size uzun mu geldi? Yoksa Rabb\'inizin gazabının üzerinize inmesini mi istediniz de bana verdiğiniz sözden döndünüz?\" dedi.', 'فرجع موسي الي قومه غضبن اسفا قال يقوم الم يعدكم ربكم وعدا حسنا افطال عليكم العهد ام اردتم ان يحل عليكم غضب من ربكم فاخلفتم موعدي'),
(2435, 20, 87, 'قَالُوا مَٓا اَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلٰكِنَّا حُمِّلْـنَٓا اَوْزَاراً مِنْ ز۪ينَةِ الْقَوْمِ فَقَذَفْنَاهَا فَكَذٰلِكَ اَلْقَى السَّامِرِيُّۙ', 'Kalu ma ahlefna mev\'ıdeke bi melkina ve lakinna hummilna evzaren min zinetil kavmi fe kazefnaha fe kezalike elkas samiriyy.', '\"Senin sözünden kendi isteğimizle çıkmadık.[1] Fakat biz halkın ziynetlerinden[2] yüklenmiştik.[2] Sonra onları kaldırıp attık.[3] Aynı şekilde Samiri de attı.\"', 'قالوا ما اخلفنا موعدك بملكنا ولكنا حملنا اوزارا من زينة القوم فقذفنها فكذلك القي السامري'),
(2436, 20, 88, 'فَاَخْرَجَ لَهُمْ عِجْلاً جَسَداً لَهُ خُوَارٌ فَقَالُوا هٰذَٓا اِلٰهُكُمْ وَاِلٰهُ مُوسٰى فَنَسِيَۜ', 'Fe ahrece lehum ıclen ceseden lehu huvarun fe kalu haza ilahukum ve ilahu musa fe nesiy.', 'Böylece onlara böğürmesi olan bir boğa[1] cesedi[2] çıkardı. Ve onlara: \"Bu sizin de ilahınız Musa\'nın da. Ancak Musa onu unuttu.\"[3] dediler. [4]', 'فاخرج لهم عجلا جسدا له خوار فقالوا هذا الهكم واله موسي فنسي'),
(2437, 20, 89, 'اَفَلَا يَرَوْنَ اَلَّا يَرْجِعُ اِلَيْهِمْ قَوْلاًۙ وَلَا يَمْلِكُ لَهُمْ ضَراًّ وَلَا نَفْعاً۟', 'E fe la yerevne ella yerciu ileyhim kavlen ve la yemliku lehum darren ve la nef\'a.', 'Onlar,  kendilerine bir cevap veremediğini,  yarar veya zarar verecek bir gücünün olmadığını görmüyorlar mı?', 'افلا يرون الا يرجع اليهم قولا ولا يملك لهم ضرا ولا نفعا'),
(2438, 20, 90, 'وَلَقَدْ قَالَ لَهُمْ هٰرُونُ مِنْ قَبْلُ يَا قَوْمِ اِنَّمَا فُتِنْتُمْ بِه۪ۚ وَاِنَّ رَبَّكُمُ الرَّحْمٰنُ فَاتَّبِعُون۪ي وَاَط۪يعُٓوا اَمْر۪ي', 'Ve lekad kale lehum harunu min kablu ya kavmi innema futintum bih ve inne rabbekumur rahmanu fettebiuni ve etiu emri.', 'Ant olsun ki,  Harun,  daha önce onlara: \"Ey halkım! Kuşku yok ki siz bununla sınava çekildiniz. Kuşkusuz sizin Rabb\'iniz Rahman\'dır. Gelin bana uyun ve buyruklarıma tabi olun.\" demişti.', 'ولقد قال لهم هرون من قبل يقوم انما فتنتم به وان ربكم الرحمن فاتبعوني واطيعوا امري'),
(2439, 20, 91, 'قَالُوا لَنْ نَبْرَحَ عَلَيْهِ عَاكِف۪ينَ حَتّٰى يَرْجِعَ اِلَيْنَا مُوسٰى', 'Kalu len nebreha aleyhi akifine hatta yercia ileyna musa.', 'Halk,  \"Musa bize dönüp gelinceye kadar,  kendimizi buzağıya adamaktan asla vazgeçmeyeceğiz.\" dedi.', 'قالوا لن نبرح عليه عكفين حتي يرجع الينا موسي'),
(2440, 20, 92, 'قَالَ يَا هٰرُونُ مَا مَنَعَكَ اِذْ رَاَيْتَهُمْ ضَلُّواۙ', 'Kale ya harunu ma meneake iz reeytehum dallu.', 'Musa: \"Ey Harun! Bunların sapkınlıklarını gördüğün halde,  onları uyarmaktan seni alıkoyan ne oldu?\"', 'قال يهرون ما منعك اذ رايتهم ضلوا'),
(2441, 20, 93, 'اَلَّا تَتَّبِعَنِۜ اَفَعَصَيْتَ اَمْر۪ي', 'Ella tettebian, e fe asayte emri.', '\"Niçin bana uymadın? Yoksa buyruklarıma karşı mı çıktın?\"', 'الا تتبعن افعصيت امري'),
(2442, 20, 94, 'قَالَ يَبْنَؤُ۬مَّ لَا تَأْخُذْ بِلِحْيَت۪ي وَلَا بِرَأْس۪يۚ اِنّ۪ي خَش۪يتُ اَنْ تَقُولَ فَرَّقْتَ بَيْنَ بَن۪ٓي اِسْرَٓائ۪لَ وَلَمْ تَرْقُبْ قَوْل۪ي', 'Kale yebneumme la te\'huz bi lıhyeti ve la bi re\'si, inni haşitu en tekule ferrakte beyne beni israile ve lem terkub kavli.', 'Harun: \"Ey annemin oğlu! Sakalımı ve saçımı tutma! Gerçek şu ki: ben senin,  \"İsrailoğulları arasında ayrılık çıkardın,  sözümü dinlemedin.\" demenden huşu[1] ettim. dedi.', 'قال يبنوم لا تاخذ بلحيتي ولا براسي اني خشيت ان تقول فرقت بين بني اسريل ولم ترقب قولي'),
(2443, 20, 95, 'قَالَ فَمَا خَطْبُكَ يَا سَامِرِيُّ', 'Kale fe ma hatbuke ya samiriyy.', 'Musa: \"Ey Samiri! Sen ne yapmak istiyorsun?\"', 'قال فما خطبك يسمري'),
(2444, 20, 96, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِه۪ فَقَبَضْتُ قَبْضَةً مِنْ اَثَرِ الرَّسُولِ فَنَبَذْتُهَا وَكَذٰلِكَ سَوَّلَتْ ل۪ي نَفْس۪ي', 'Kale basurtu bi ma lem yabsuru bihi fe kabadtu kabdaten min eserir resuli fe nebeztuha ve kezalike sevvelet li nefsi.', 'Samiri: \"Ben,  onların anlamadıkları şeyi anladım[1]. Resulün öğretisinden az bir şey almıştım işte onu bıraktım. Bunu,  bana nefsim hoş gösterdi.\" dedi.', 'قال بصرت بما لم يبصروا به فقبضت قبضة من اثر الرسول فنبذتها وكذلك سولت لي نفسي'),
(2445, 20, 97, 'قَالَ فَاذْهَبْ فَاِنَّ لَكَ فِي الْحَيٰوةِ اَنْ تَقُولَ لَا مِسَاسَۖ وَاِنَّ لَكَ مَوْعِداً لَنْ تُخْلَفَهُۚ  وَانْظُرْ اِلٰٓى اِلٰهِكَ الَّذ۪ي ظَلْتَ عَلَيْهِ عَاكِفاًۜ لَنُحَرِّقَنَّهُ ثُمَّ لَنَنْسِفَنَّهُ فِي الْيَمِّ نَسْفاً', 'Kale fezheb fe inne leke fil hayati en tekule la misase ve inne leke mev\'ıden len tuhlefeh, vanzur ila ilahikellezi zalte aleyhi akifa, le nuharrikannehu summe le nensifennehu fil yemmi nesfa.', 'Musa: \"Çek git karşımdan! Artık sen,  hayatın boyunca toplumdan dışlanacaksın. Ayrıca senin için,  asla kurtulamayacağın bir buluşma günü var. Bir de kendini adadığın ilahına bak! Onu kesinlikle yakacağız. Sonra da savurup suya saçacağız.\" dedi.', 'قال فاذهب فان لك في الحيوة ان تقول لا مساس وان لك موعدا لن تخلفه وانظر الي الهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا'),
(2446, 20, 98, 'اِنَّـمَٓا اِلٰهُكُمُ اللّٰهُ الَّذ۪ي لَٓا اِلٰهَ اِلَّا هُوَۜ وَسِعَ كُلَّ شَيْءٍ عِلْماً', 'İnnema ilahukumullahullezi la ilahe illa huv, vesia kulle şey\'in ilma.', '\"Sizin ilahınız yalnızca Allah\'tır. O\'ndan başka ilah yoktur. Kuşkusuz,  O\'nun ilmi her şeyi kuşatmıştır.\"', 'انما الهكم الله الذي لا اله الا هو وسع كل شي علما'),
(2447, 20, 99, 'كَذٰلِكَ نَقُصُّ عَلَيْكَ مِنْ اَنْـبَٓاءِ مَا قَدْ سَبَقَۚ وَقَدْ اٰتَيْنَاكَ مِنْ لَدُنَّا ذِكْراًۚ', 'Kezalike nakussu aleyke min enbai ma kad sebak, ve kad ateynake min ledunna zikra.', 'İşte böylece geçmişlerin haberlerinden sana anlatıyoruz. Gerçek şu ki sana katımızdan bir zikir[1] verdik.[2]', 'كذلك نقص عليك من انبا ما قد سبق وقد اتينك من لدنا ذكرا'),
(2448, 20, 100, 'مَنْ اَعْرَضَ عَنْهُ فَاِنَّهُ يَحْمِلُ يَوْمَ الْقِيٰمَةِ وِزْراًۙ', 'Men a\'rada anhu fe innehu yahmilu yevmel kıyameti vizra.', 'Kim ondan[1] yüz çevirirse,  o Kıyamet Günü için ağır bir yük yüklenir.', 'من اعرض عنه فانه يحمل يوم القيمة وزرا'),
(2449, 20, 101, 'خَالِد۪ينَ ف۪يهِۜ وَسَٓاءَ لَهُمْ يَوْمَ الْقِيٰمَةِ حِمْلاًۙ', 'Halidine fih, ve sae lehum yevmel kıyameti hımla.', 'Onlar,  orada sürekli kalacaklardır. Ve yüklendikleri yük,  Kıyamet Günü\'nde onlar için ne kötüdür.', 'خلدين فيه وسا لهم يوم القيمة حملا'),
(2450, 20, 102, 'يَوْمَ يُنْفَخُ فِي الصُّورِ وَنَحْشُرُ الْمُجْرِم۪ينَ يَوْمَئِذٍ زُرْقاًۚ', 'Yevme yunfehu fis suri ve nahşurul mucrimine yevme izin zurka.', 'O gün,  Sur\'a üfürülür. O gün,  mücrimleri şaşkınlıktan gözleri donuklaşmış olarak toplayacağız.', 'يوم ينفخ في الصور ونحشر المجرمين يوميذ زرقا'),
(2451, 20, 103, 'يَتَخَافَتُونَ بَيْنَهُمْ اِنْ لَبِثْتُمْ اِلَّا عَشْراً', 'Yetehafetune beynehum in lebistum illa aşra.', '\"Dünya hayatınız sadece on gün sürdü değil mi?\" diye aralarında fısıldaşırlar.', 'يتخافتون بينهم ان لبثتم الا عشرا'),
(2452, 20, 104, 'نَحْنُ اَعْلَمُ بِمَا يَقُولُونَ اِذْ يَقُولُ اَمْثَلُهُمْ طَر۪يقَةً اِنْ لَبِثْتُمْ اِلَّا يَوْماً۟', 'Nahnu a\'lemu bima yekulune iz yekulu emseluhum tarikaten in lebistum illa yevma.', 'Biz,  aralarında ne konuştuklarını çok iyi biliriz. Onlardan isabetli olanı,  \"Olsa olsa bir gün kaldınız.\" diyecek.', 'نحن اعلم بما يقولون اذ يقول امثلهم طريقة ان لبثتم الا يوما'),
(2453, 20, 105, 'وَيَسْـَٔلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنْسِفُهَا رَبّ۪ي نَسْفاًۙ', 'Ve yes\'eluneke anil cibali fe kul yensifuha rabbi nesfa.', 'Sana dağlardan soruyorlar. De ki: \"Rabb\'im onları ufalayıp savuracak.\"', 'ويسلونك عن الجبال فقل ينسفها ربي نسفا'),
(2454, 20, 106, 'فَيَذَرُهَا قَاعاً صَفْصَفاًۙ', 'Fe yezeruha kaan safsafa.', '\"Onları dümdüz araziye çevirecektir.\"', 'فيذرها قاعا صفصفا'),
(2455, 20, 107, 'لَا تَرٰى ف۪يهَا عِوَجاً وَلَٓا اَمْتاً', 'La tera fiha ivecen ve la emta.', 'Orada ne bir çukur ne de bir tümsek göremezsin.', 'لا تري فيها عوجا ولا امتا'),
(2456, 20, 108, 'يَوْمَئِذٍ يَتَّبِعُونَ الدَّاعِيَ لَا عِوَجَ لَهُۚ وَخَشَعَتِ الْاَصْوَاتُ لِلرَّحْمٰنِ فَلَا تَسْمَعُ اِلَّا هَمْساً', 'Yevme izin yettebiuned daıye la ivece leh, ve haşeatil asvatu lir rahmani fe la tesmeu illa hemsa.', 'O gün,  hiçbir tarafa sapmadan,  davetçiye uyarlar. Rahman\'a karşı sesler kısılmıştır. Fısıltıdan başka bir şey işitemezsin.', 'يوميذ يتبعون الداعي لا عوج له وخشعت الاصوات للرحمن فلا تسمع الا همسا'),
(2457, 20, 109, 'يَوْمَئِذٍ لَا تَنْفَعُ الشَّفَاعَةُ اِلَّا مَنْ اَذِنَ لَهُ الرَّحْمٰنُ وَرَضِيَ لَهُ قَوْلاً', 'Yevme izin la tenfauş şefaatu illa men ezine lehur rahmanu ve radıye lehu kavla.', 'İzin Günü[1],  şefaat fayda vermez. Rahman\'ın kendisine izin verdiği ve sözünden hoşnut olduğu kimse hariç.[2]', 'يوميذ لا تنفع الشفعة الا من اذن له الرحمن ورضي له قولا'),
(2458, 20, 110, 'يَعْلَمُ مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْ وَلَا يُح۪يطُونَ بِه۪ عِلْماً', 'Ya\'lemu ma beyne eydihim ve ma halfehum ve la yuhitune bihi ılma.', 'Onların önlerindekini ve arkalarındakini bilir.[1] Ama onlar,  O\'nu bilgice kavrayamazlar.[2]', 'يعلم ما بين ايديهم وما خلفهم ولا يحيطون به علما'),
(2459, 20, 111, 'وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِۜ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْماً', 'Ve anetil vucuhu lil hayyil kayyum, ve kad habe men hamele zulma.', 'Yüzler,  Hayy[1] ve Kayyum[2] olanın önünde eğilmiştir. Zulüm taşıyıcılar perişan olmuştur.', 'وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما'),
(2460, 20, 112, 'وَمَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْماً وَلَا هَضْماً', 'Ve men ya\'mel mines salihati ve huve mu\'minun fe la yehafu zulmen ve la hadma.', 'İnanan biri olarak salihatı yapan kimse ise haksızlığa uğramaktan da hakkının yeneceğinden de korkmaz.', 'ومن يعمل من الصلحت وهو مومن فلا يخاف ظلما ولا هضما'),
(2461, 20, 113, 'وَكَذٰلِكَ اَنْزَلْنَاهُ قُرْاٰناً عَرَبِياًّ وَصَرَّفْنَا ف۪يهِ مِنَ الْوَع۪يدِ لَعَلَّهُمْ يَتَّقُونَ اَوْ يُحْدِثُ لَهُمْ ذِكْراً', 'Ve kezalike enzelnahu kur\'anen arabiyyen ve sarrafna fihi minel vaidi leallehum yettekune ev yuhdisu lehum zikra.', 'Sana onu Arapça bir Kur\'an olarak indirdik. O\'nda,  uyarıları teker teker bildirdik. Böylece takva[1] sahibi olurlar veya onlar için öğüt veren bir söz olur.', 'وكذلك انزلنه قرانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون او يحدث لهم ذكرا'),
(2462, 20, 114, 'فَتَعَالَى اللّٰهُ الْمَلِكُ الْحَقُّۚ وَلَا تَعْجَلْ بِالْقُرْاٰنِ مِنْ قَبْلِ اَنْ يُقْضٰٓى اِلَيْكَ وَحْيُهُۘ وَقُلْ رَبِّ زِدْن۪ي عِلْماً', 'Fe tealallahul melikul hak, ve la ta\'cel bil kur\'ani min kabli en yukda ileyke vahyuhu ve kul rabbi zidni ılma.', 'Her şeyin gerçek egemeni olan Allah,  yüceler yücesidir. Kur\'an\'ın sana vahyedilmesi bitirilmeden önce acele etme. \"Rabb\'im bana bilgiyi arttır.\" de.', 'فتعلي الله الملك الحق ولا تعجل بالقران من قبل ان يقضي اليك وحيه وقل رب زدني علما'),
(2463, 20, 115, 'وَلَقَدْ عَهِدْنَٓا اِلٰٓى اٰدَمَ مِنْ قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُ عَزْماً۟', 'Ve lekad ahidna ila ademe min kablu fe nesiye ve lem necid lehu azma.', 'Ant olsun ki Biz,  bundan önce Âdem\'e ahit[1] verdik,  ancak o unuttu. Onu azimli bulmadık.', 'ولقد عهدنا الي ادم من قبل فنسي ولم نجد له عزما'),
(2464, 20, 116, 'وَاِذْ قُلْنَا لِلْمَلٰٓئِكَةِ اسْجُدُوا لِاٰدَمَ فَسَجَدُٓوا اِلَّٓا اِبْل۪يسَۜ اَبٰى', 'Ve iz kulna lil melaiketiscudu li ademe fe secedu illa iblis, eba.', 'Hani! Meleklere: \"Âdem\'e secde edin.\"[1] demiştik. Hemen secde etmişlerdi,  iblis ise bundan kaçınmıştı.', 'واذ قلنا للمليكة اسجدوا لادم فسجدوا الا ابليس ابي'),
(2465, 20, 117, 'فَقُلْنَا يَٓا اٰدَمُ اِنَّ هٰذَا عَدُوٌّ لَكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقٰى', 'Fe kulna ya ademu inne haza aduvvun leke ve li zevcike fe la yuhricennekuma minel cenneti fe teşka.', 'Bunun üzerine Biz de: \"Ey Âdem! Kuşkusuz bu sana ve eşine düşmandır. Sakın sizi Cennet\'ten[1] çıkarmasın. Sonra mutsuz olursun.\" dedik.', 'فقلنا يادم ان هذا عدو لك ولزوجك فلا يخرجنكما من الجنة فتشقي'),
(2466, 20, 118, 'اِنَّ لَكَ اَلَّا تَجُوعَ ف۪يهَا وَلَا تَعْرٰىۙ', 'İnne leke ella tecua fiha ve la ta\'ra.', '\"Senin için orada acıkmak ve açıkta kalmak yoktur.\"', 'ان لك الا تجوع فيها ولا تعري'),
(2467, 20, 119, 'وَاَنَّكَ لَا تَظْمَؤُ۬ا ف۪يهَا وَلَا تَضْحٰى', 'Ve enneke la tazmeu fiha ve la tadha.', '\"Orada susuz kalmazsın ve sıcaktan zarar görmezsin.\"', 'وانك لا تظموا فيها ولا تضحي'),
(2468, 20, 120, 'فَوَسْوَسَ اِلَيْهِ الشَّيْطَانُ قَالَ يَٓا اٰدَمُ هَلْ اَدُلُّكَ عَلٰى شَجَرَةِ الْخُلْدِ وَمُلْكٍ لَا يَبْلٰى', 'Fe vesvese ileyhiş şeytanu kale ya ademu hel edulluke ala şeceretil huldi ve mulkin la yebla.', 'Sonra şeytan ona vesvese verdi. Dedi ki: \"Ey Âdem! Sana ebedilik ağacı ve yok olmayacak bir egemenlik[1] için yol göstereyim mi?', 'فوسوس اليه الشيطن قال يادم هل ادلك علي شجرة الخلد وملك لا يبلي'),
(2469, 20, 121, 'فَاَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْاٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِنْ وَرَقِ الْجَنَّةِۘ وَعَصٰٓى اٰدَمُ رَبَّهُ فَغَوٰىۖ', 'Fe ekela minha fe bedet lehuma sev\'atuhuma ve tafıka yahsıfani aleyhima min varakıl cenneti ve asa ademu rabbehu fe gava.', 'Bunun üzerine ikisi de ondan yediler.[1] Hemen çirkinlikleri[2] kendilerine görünüverdi. Cennet yaprağından örtmeye başladılar. Âdem,  Rabb\'ine asilik edip yanıldı.', 'فاكلا منها فبدت لهما سوتهما وطفقا يخصفان عليهما من ورق الجنة وعصي ادم ربه فغوي'),
(2470, 20, 122, 'ثُمَّ اجْتَبٰيهُ رَبُّهُ فَتَابَ عَلَيْهِ وَهَدٰى', 'Summectebahu rabbuhu fe tabe aleyhi ve heda.', 'Sonra Rabbi onu seçti,  tevbesini kabul etti. Ve ona doğru yolu gösterdi.', 'ثم اجتبه ربه فتاب عليه وهدي'),
(2471, 20, 123, 'قَالَ اهْبِطَا مِنْهَا جَم۪يعاً بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۚ فَاِمَّا يَأْتِيَنَّكُمْ مِنّ۪ي هُدًى فَمَنِ اتَّـبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشْقٰى', 'Kalehbita minha cemian ba\'dukum li ba\'dın aduvv, fe imma ye\'tiyennekum minni huden fe menittebea hudaye fe la yadıllu ve la yeşka.', 'Dedi ki: \"Hepiniz oradan ayrılın.[1]\" Bir kısmınız bir kısmınıza düşmansınız. Benden size bir yol gösterici geldiği zaman,  kim yol göstericime uyarsa; işte o sapkınlığa düşmez ve mutsuz olmaz.\" dedi.', 'قال اهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم مني هدي فمن اتبع هداي فلا يضل ولا يشقي'),
(2472, 20, 124, 'وَمَنْ اَعْرَضَ عَنْ ذِكْر۪ي فَاِنَّ لَهُ مَع۪يشَةً ضَنْكاً وَنَحْشُرُهُ يَوْمَ الْقِيٰمَةِ اَعْمٰى', 'Ve men a\'rada an zikri fe inne lehu maişeten danken ve nahşuruhu yevmel kıyameti a\'ma.', 'Kim Ben\'im zikrimden[1] yüz çevirirse,  bilmelidir ki onun için bunalımlı bir yaşam vardır. Kıyamet Günü de onu kör olarak haşrederiz.[2]', 'ومن اعرض عن ذكري فان له معيشة ضنكا ونحشره يوم القيمة اعمي'),
(2473, 20, 125, 'قَالَ رَبِّ لِمَ حَشَرْتَـن۪ٓي اَعْمٰى وَقَدْ كُنْتُ بَص۪يراً', 'Kale rabbi lime haşerteni a\'ma ve kad kuntu basira.', '\"Rabbim,  beni neden kör olarak haşrettin? Oysa dünyada iken gören biriydim.\" der.', 'قال رب لم حشرتني اعمي وقد كنت بصيرا'),
(2474, 20, 126, 'قَالَ كَذٰلِكَ اَتَتْكَ اٰيَاتُنَا فَـنَس۪يتَهَاۚ وَكَذٰلِكَ الْيَوْمَ تُنْسٰى', 'Kale kezalike etetke ayatuna fe nesiteha, ve kezalikel yevme tunsa.', '\"Bu böyledir,  ayetlerimiz sana geldi ancak onları dikkate almadın; bugün de sen terk edileceksin.\" dedi.', 'قال كذلك اتتك ايتنا فنسيتها وكذلك اليوم تنسي'),
(2475, 20, 127, 'وَكَذٰلِكَ نَجْز۪ي مَنْ اَسْرَفَ وَلَمْ يُؤْمِنْ بِاٰيَاتِ رَبِّه۪ۜ وَلَعَذَابُ الْاٰخِرَةِ اَشَدُّ وَاَبْقٰى', 'Ve kezalike neczi men esrefe ve lem yu\'min bi ayati rabbih, ve le azabul ahıreti eşeddu ve ebka.', 'Haddi aşanları ve Rabbinin ayetlerine inanmayanları işte böyle cezalandırırız. Ve ahiret azabı daha şiddetli ve daha kalıcıdır.', 'وكذلك نجزي من اسرف ولم يومن بايت ربه ولعذاب الاخرة اشد وابقي'),
(2476, 20, 128, 'اَفَلَمْ يَهْدِ لَهُمْ كَمْ اَهْلَكْنَا قَبْلَهُمْ مِنَ الْقُرُونِ يَمْشُونَ ف۪ي مَسَاكِنِهِمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِاُو۬لِي النُّهٰى۟', 'E fe lem yehdi lehum kem ehlekna kablehum minel kuruni yemşune fi mesakinihim, inne fi zalike le ayatin li ulin nuha.', 'Şimdi yurtlarında gezip dolaştıkları nesilleri yok etmiş olmamız,  onlar için yol gösterici olmadı mı? Kuşku yok ki bunda kötülükten alıkoyan bir akıl için nice kanıtlar vardır.', 'افلم يهد لهم كم اهلكنا قبلهم من القرون يمشون في مسكنهم ان في ذلك لايت لاولي النهي'),
(2477, 20, 129, 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَكَانَ لِزَاماً وَاَجَلٌ مُسَمًّىۜ', 'Ve lev la kelimetun sebekat min rabbike le kane lizamen ve ecelun musemma.', 'Ve eğer Rabbinden daha önce kararlaştırılmış bir hüküm ve adı konmuş bir süre olmasaydı elbette ceza kaçınılmaz olurdu.[1]', 'ولولا كلمة سبقت من ربك لكان لزاما واجل مسمي'),
(2478, 20, 130, 'فَاصْبِرْ عَلٰى مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَاۚ وَمِنْ اٰنَٓائِ الَّيْلِ فَسَبِّـحْ وَاَطْرَافَ النَّهَارِ لَعَلَّكَ تَرْضٰى', 'Fasbir ala ma yekulune ve sebbih bi hamdi rabbike kable tuluış şemsi ve kable gurubiha, ve min anail leyli fe sebbih ve etrafen nehari lealleke terda.', 'O halde söylenen şeylere sabret! Ve Rabb\'ini,  Güneş\'in doğmasından önce ve batmasından önce ve gecenin bir kısmında ve gündüzün taraflarında[1] hamd ile tesbih[2] et. Umulur ki böylece O\'nun hoşnutluğunu kazanırsın.', 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن اناي اليل فسبح واطراف النهار لعلك ترضي'),
(2479, 20, 131, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ اِلٰى مَا مَتَّعْنَا بِه۪ٓ اَزْوَاجاً مِنْهُمْ زَهْرَةَ الْحَيٰوةِ الدُّنْيَا لِنَفْتِنَهُمْ ف۪يهِۜ وَرِزْقُ رَبِّكَ خَيْرٌ وَاَبْقٰى', 'Ve la temuddenne ayneyke ila ma metta\'na bihi ezvacen minhum zehretel hayatid dunya li neftinehum fih, ve rızku rabbike hayrun ve ebka.', 'Onlardan bazı zümrelere,  kendilerini sınamak için,  dünya hayatının süsü olarak verdiğimiz şeylere imrenme. Rabb\'inin rızkı daha hayırlıdır ve kalıcıdır.', 'ولا تمدن عينيك الي ما متعنا به ازوجا منهم زهرة الحيوة الدنيا لنفتنهم فيه ورزق ربك خير وابقي'),
(2480, 20, 132, 'وَأْمُرْ اَهْلَكَ بِالصَّلٰوةِ وَاصْطَبِرْ عَلَيْهَاۜ لَا نَسْـَٔلُكَ رِزْقاًۜ نَحْنُ نَرْزُقُكَۜ وَالْعَاقِبَةُ لِلتَّقْوٰى', 'Ve\'mur ehleke bis salati vastabir aleyha, la nes\'eluke rızka, nahnu nerzukuk, vel akıbetu lit takva.', 'Ehline salatı buyur.[1] Kendin de onun üzerinde sabırlı ol. Senden rızık istemiyoruz. Seni,  Biz rızıklandırıyoruz. Sonuç takva[2] içindir.', 'وامر اهلك بالصلوة واصطبر عليها لا نسلك رزقا نحن نرزقك والعقبة للتقوي'),
(2481, 20, 133, 'وَقَالُوا لَوْلَا يَأْت۪ينَا بِاٰيَةٍ مِنْ رَبِّه۪ۜ اَوَلَمْ تَأْتِهِمْ بَيِّنَةُ مَا فِي الصُّحُفِ الْاُو۫لٰى', 'Ve kalu lev la ye\'tina bi ayetin min rabbih, e ve lem te\'tihim beyyinetu ma fis suhufil ula.', '\"Rabb\'inden bize bir ayet[1] getirse ya!\" dediler. Onlara,  önceki suhuflarda[2] yer alan kanıt içeren açıklayıcı bilgiler ulaşmadı mı?', 'وقالوا لولا ياتينا باية من ربه اولم تاتهم بينة ما في الصحف الاولي'),
(2482, 20, 134, 'وَلَوْ اَنَّٓا اَهْلَكْنَاهُمْ بِعَذَابٍ مِنْ قَبْلِه۪ لَقَالُوا رَبَّنَا لَوْلَٓا اَرْسَلْتَ اِلَيْنَا رَسُولاً فَنَتَّبِعَ اٰيَاتِكَ مِنْ قَبْلِ اَنْ نَذِلَّ وَنَخْزٰى', 'Ve lev enna ehleknahum bi azabin min kablihi le kalu rabbena lev la erselte ileyna resulen fe nettebia ayatike min kabli en nezille ve nahza.', 'Ve eğer Biz,  ondan önce bir azap ile onları yok etseydik,  \"Ey Rabb\'imiz! Bize bir resul gönderseydin de hor ve rezil olmadan önce Sen\'in ayetlerine uysaydık ya!\" diyeceklerdi.', 'ولو انا اهلكنهم بعذاب من قبله لقالوا ربنا لولا ارسلت الينا رسولا فنتبع ايتك من قبل ان نذل ونخزي'),
(2483, 20, 135, 'قُلْ كُلٌّ مُتَرَبِّصٌ فَتَرَبَّصُواۚ فَسَتَعْلَمُونَ مَنْ اَصْحَابُ الصِّرَاطِ السَّوِيِّ وَمَنِ اهْتَدٰى', 'Kul kullun muterebbisun fe terabbesu, fe se ta\'lemune men ashabus sıratıs seviyyi ve menihteda.', 'De ki: \"Herkes beklemektedir. O halde siz de bekleyin. Kuşku yok ki kimin düzgün yolda olduğunu,  kimin doğru yolu bulduğunu yakında bileceksiniz.\"', 'قل كل متربص فتربصوا فستعلمون من اصحب الصرط السوي ومن اهتدي'),
(2484, 21, 1, 'اِقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ ف۪ي غَفْلَةٍ مُعْرِضُونَۚ', 'Ikterebe lin nasi hisabuhum ve hum fi gafletin mu\'ridun.', 'İnsanlar için hesap vakti[1] yaklaştı. Ne var ki onlar gaflet içinde aldırmıyorlar.', 'اقترب للناس حسابهم وهم في غفلة معرضون'),
(2485, 21, 2, 'مَا يَأْت۪يهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ اِلَّا اسْتَمَعُوهُ وَهُمْ يَلْعَبُونَۙ', 'Ma ye\'tihim min zikrin min rabbihim muhdesin illestemeuhu ve hum yel\'abun.', 'Rabb\'lerinden,  kendilerine gelen söze bürünmüş her yeni öğüdü,  sadece alay ederek dinlerler.', 'ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون'),
(2486, 21, 3, 'لَاهِيَةً قُلُوبُهُمْۜ وَاَسَرُّوا النَّجْوٰىۗ اَلَّذ۪ينَ ظَلَمُواۗ هَلْ هٰذَٓا اِلَّا بَشَرٌ مِثْلُكُمْۚ اَفَتَأْتُونَ السِّحْرَ وَاَنْتُمْ تُبْصِرُونَ', 'Lahiyeten kulubuhum ve eserrun necvellezine zalemu hel haza illa beşerun mislukum, e fe te\'tunes sihre ve entum tubsırun.', 'O haksızlık yapanlar,  akıllarınca önemsemeyerek ve kendi aralarında fısıldayarak: \"Bu,  sizin gibi bir beşerden[1] başka bir şey midir? Yoksa siz,  göz göre göre büyüye mi kapılacaksınız?\" diyorlar.', 'لاهية قلوبهم واسروا النجوي الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون'),
(2487, 21, 4, 'قَالَ رَبّ۪ي يَعْلَمُ الْقَوْلَ فِي السَّمَٓاءِ وَالْاَرْضِۘ وَهُوَ السَّم۪يعُ الْعَل۪يمُ', 'Kale rabbi ya\'lemul kavle fis semai vel ardı ve huves semiul alim.', '\"Rabb\'im,  gökte ve yerde olan her sözü bilir. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.\" dedi.', 'قال ربي يعلم القول في السما والارض وهو السميع العليم'),
(2488, 21, 5, 'بَلْ قَالُٓوا اَضْغَاثُ اَحْلَامٍ بَلِ افْتَرٰيهُ بَلْ هُوَ شَاعِرٌۚ فَلْيَأْتِنَا بِاٰيَةٍ كَمَٓا اُرْسِلَ الْاَوَّلُونَ', 'Bel kalu adgasu ahlamin belifterahu bel huve şaır, fel ye\'tina bi ayetin kema ursilel evvelun.', '\"Hayır,  bunlar karmakarışık düşlerdir. Hayır,  belki onu uydurdu. Hayır,  o bir şairdir. Öyleyse öncekilere gönderildiği gibi bize bir ayet[1] getirsin.\" dediler.', 'بل قالوا اضغث احلم بل افتريه بل هو شاعر فلياتنا باية كما ارسل الاولون'),
(2489, 21, 6, 'مَٓا اٰمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ اَهْلَكْنَاهَاۚ اَفَهُمْ يُؤْمِنُونَ', 'Ma amenet kablehum min karyetin ehleknaha, e fe hum yu\'minun.', 'Onlardan önce yok ettiğimiz hiçbir kent iman etmemişti. Şimdi bunlar mı iman edecekler?[1]', 'ما امنت قبلهم من قرية اهلكنها افهم يومنون'),
(2490, 21, 7, 'وَمَٓا اَرْسَلْنَا قَبْلَكَ اِلَّا رِجَالاً نُوح۪ٓي اِلَيْهِمْ فَسْـَٔلُٓوا اَهْلَ الذِّكْرِ اِنْ كُنْتُمْ لَا تَعْلَمُونَ', 'Ve ma erselna kableke illa ricalen nuhi ileyhim fes\'elu ehlez zikri in kuntum la ta\'lemun.', 'Senden önce de vahyimizi iletmede elçi olarak insandan başkasını görevlendirmedik. Eğer bilmiyorsanız,  zikir ehline[1] sorun.', 'وما ارسلنا قبلك الا رجالا نوحي اليهم فسلوا اهل الذكر ان كنتم لا تعلمون'),
(2491, 21, 8, 'وَمَا جَعَلْنَاهُمْ جَسَداً لَا يَأْكُلُونَ الطَّعَامَ وَمَا  كَانُوا خَالِد۪ينَ', 'Ve ma cealnahum ceseden la ye\'kulunet taame ve ma kanu halidin.', 'Biz,  onları yemeye,  içmeye ihtiyaç duymayan varlıklar yapmadık. Ve onlar ölümsüz de değillerdi.', 'وما جعلنهم جسدا لا ياكلون الطعام وما كانوا خلدين'),
(2492, 21, 9, 'ثُمَّ صَدَقْنَاهُمُ الْوَعْدَ فَاَنْجَيْنَاهُمْ وَمَنْ نَشَٓاءُ وَاَهْلَكْنَا الْمُسْرِف۪ينَ', 'Summe sadaknahumul va\'de fe enceynahum ve men neşau ve ehleknel musrifin.', 'Sonra onlara verdiğimiz söze bağlı kaldık. Onları ve hak eden kimseleri[1] kurtardık. Müsrifleri[2] ise yok ettik.', 'ثم صدقنهم الوعد فانجينهم ومن نشا واهلكنا المسرفين'),
(2493, 21, 10, 'لَقَدْ اَنْزَلْـنَٓا اِلَيْكُمْ كِتَاباً ف۪يهِ ذِكْرُكُمْۜ اَفَلَا تَعْقِلُونَ۟', 'Lekad enzelna ileykum kitaben fihi zikrukum, e fe la ta\'kılun.', 'Ant olsun ki,  gerçekten içinde sizin öğüdünüz[1] olan bir kitap indirdik. Hala aklınızı kullanmayacak mısınız?', 'لقد انزلنا اليكم كتبا فيه ذكركم افلا تعقلون'),
(2494, 21, 11, 'وَكَمْ قَصَمْنَا مِنْ قَرْيَةٍ كَانَتْ ظَالِمَةً وَاَنْشَأْنَا بَعْدَهَا قَوْماً اٰخَر۪ينَ', 'Ve kem kasamna min karyetin kanet zalimeten ve enşe\'na ba\'deha kavmen aharin.', 'Ve Biz,  zalim olan kentlerden nicelerini kırıp geçirdik. Onlardan sonra başka bir halk getirdik.', 'وكم قصمنا من قرية كانت ظالمة وانشانا بعدها قوما اخرين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2495, 21, 12, 'فَلَمَّٓا اَحَسُّوا بَأْسَنَٓا اِذَا هُمْ مِنْهَا يَرْكُضُونَۜ', 'Fe lemma ehassu be\'sena iza hum minha yerkudun.', 'Öyle ki onlar azabımızı hissettikleri zaman,  ondan kaçmaya çalışıyorlardı.', 'فلما احسوا باسنا اذا هم منها يركضون'),
(2496, 21, 13, 'لَا تَرْكُضُوا وَارْجِعُٓوا اِلٰى مَٓا اُتْرِفْتُمْ ف۪يهِ وَمَسَاكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', 'La terkudu verciu ila ma utriftum fihi ve mesakinikum leallekum tus\'elun.', 'Boşuna kaçmayın,  refaha kavuşturulduğunuz şeylere ve evlerinize geri dönün; çünkü hesaba çekileceksiniz.', 'لا تركضوا وارجعوا الي ما اترفتم فيه ومسكنكم لعلكم تسلون'),
(2497, 21, 14, 'قَالُوا يَا وَيْلَنَٓا اِنَّا كُنَّا ظَالِم۪ينَ', 'Kalu ya veylena inna kunna zalimin.', '\"Yazıklar olsun bize! Biz zalimlermişiz.\" dediler.', 'قالوا يويلنا انا كنا ظلمين'),
(2498, 21, 15, 'فَمَا زَالَتْ تِلْكَ دَعْوٰيهُمْ حَتّٰى جَعَلْنَاهُمْ حَص۪يداً خَامِد۪ينَ', 'Fe ma zalet tilke da\'vahum hatta cealnahum hasiden hamidin.', 'Biçilmiş ekin gibi pörsüyüp,  cansız kalıncaya kadar bu çağrıları son bulmadı.', 'فما زالت تلك دعويهم حتي جعلنهم حصيدا خمدين'),
(2499, 21, 16, 'وَمَا خَلَقْنَا السَّمَٓاءَ وَالْاَرْضَ وَمَا بَيْنَهُمَا لَاعِب۪ينَ', 'Ve ma halaknes semae vel arda ve ma beynehuma laıbin.', 'Biz; yeri,  göğü ve ikisinin arasındakileri eğlence olsun diye yaratmadık.', 'وما خلقنا السما والارض وما بينهما لعبين'),
(2500, 21, 17, 'لَوْ اَرَدْنَٓا اَنْ نَتَّخِذَ لَهْواً لَاتَّخَذْنَاهُ مِنْ لَدُنَّاۗ اِنْ كُنَّا فَاعِل۪ينَ', 'Lev eredna en nettehıze lehven lettehaznahu min ledunna in kunna fa\'ılin.', 'Eğer eğlence edinmek isteseydik,  elbette onu kendi şanımıza uygun yapardık. Eğer yapacak olsak böyle yapardık.', 'لو اردنا ان نتخذ لهوا لاتخذنه من لدنا ان كنا فعلين'),
(2501, 21, 18, 'بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَاِذَا هُوَ زَاهِقٌۜ وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ', 'Bel nakzifu bil hakkı alel batıli fe yedmeguhu fe iza huve zahik, ve lekumul veylu mimma tasıfun.', 'Aksine,  Biz; Hakk\'ı,  Batıl\'a karşı ortaya koyarız da onu mahveder. Böylece Batıl yok olur. Nitelediğiniz şeylerden dolayı size yazıklar olsun.', 'بل نقذف بالحق علي البطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون'),
(2502, 21, 19, 'وَلَهُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِۜ وَمَنْ عِنْدَهُ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِه۪ وَلَا يَسْتَحْسِرُونَۚ', 'Ve lehu men fis semavati vel ard, ve men indehu la yestekbirune an ıbadetihi ve la yestahsirun.', 'Göklerde ve yerde ne varsa O\'nundur. O\'nun yanında bulunanlar O\'na kulluk etmekten büyüklenmez ve usanmazlar;', 'وله من في السموت والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون'),
(2503, 21, 20, 'يُسَبِّحُونَ الَّيْلَ وَالنَّهَارَ لَا يَفْتُرُونَ', 'Yusebbihunel leyle ven nehare la yefturun.', 'Gece,  gündüz ara vermeksizin tesbih ederler.', 'يسبحون اليل والنهار لا يفترون'),
(2504, 21, 21, 'اَمِ اتَّخَذُٓوا اٰلِهَةً مِنَ الْاَرْضِ هُمْ يُنْشِرُونَ', 'Emittehazu aliheten minel ardı hum yunşirun.', 'Yoksa yeryüzünde birtakım ilahlar edindiler de ölüleri onlar mı diriltecek?', 'ام اتخذوا الهة من الارض هم ينشرون'),
(2505, 21, 22, 'لَوْ كَانَ ف۪يهِمَٓا اٰلِهَةٌ اِلَّا اللّٰهُ لَفَسَدَتَاۚ فَسُبْحَانَ اللّٰهِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ', 'Lev kane fihima alihetun illallahu le fesedeta, fe subhanallahi rabbil arşi amma yasıfun.', 'Eğer ikisinde[1] de Allah\'tan başka ilahlar olsaydı,  ikisi de kesinlikle fesada uğrardı. Arşın[2] Rabb\'i olan Allah,  onların niteledikleri şeylerden münezzehtir.[3]', 'لو كان فيهما الهة الا الله لفسدتا فسبحن الله رب العرش عما يصفون'),
(2506, 21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', 'La yus\'elu amma yef\'alu ve hum yus\'elun.', 'O,  yaptıklarından dolayı sorgulanamaz. Ama onlar yaptıklarının hesabını vereceklerdir.', 'لا يسل عما يفعل وهم يسلون'),
(2507, 21, 24, 'اَمِ اتَّخَذُوا مِنْ دُونِه۪ٓ اٰلِهَةًۜ قُلْ هَاتُوا بُرْهَانَكُمْۚ هٰذَا ذِكْرُ مَنْ مَعِيَ وَذِكْرُ مَنْ قَبْل۪يۜ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَۙ الْحَقَّ فَهُمْ مُعْرِضُونَ', 'Emittehazu min dunihi aliheh, kul hatu burhanekum, haza zikru men maiye ve zikru men kabli, bel ekseruhum la ya\'lemunel hakka fehum mu\'ridun.', 'Yoksa O\'nun yanı sıra başka ilahlar mı edindiler? De ki: \"Burhanınızı getirin.[1] Bu benimle beraber olanların ve benden öncekilerin öğüdüdür.\" Fakat onların çoğu gerçeği bilmezler ve onlar,  ondan yüz çevirenlerdir.', 'ام اتخذوا من دونه الهة قل هاتوا برهنكم هذا ذكر من معي وذكر من قبلي بل اكثرهم لا يعلمون الحق فهم معرضون'),
(2508, 21, 25, 'وَمَٓا اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ اِلَّا نُوح۪ٓي اِلَيْهِ اَنَّهُ لَٓا اِلٰهَ اِلَّٓا اَنَا۬ فَاعْبُدُونِ', 'Ve ma erselna min kablike min resulin illa nuhi ileyhi ennehu la ilahe illa ene fa\'budun.', 'Senden önce hiçbir resul göndermedik ki,  kendisine,  \"Benden başka ilah yoktur. Onun için Bana kulluk[1] edin.\" diye vahyetmiş olmayalım.', 'وما ارسلنا من قبلك من رسول الا نوحي اليه انه لا اله الا انا فاعبدون'),
(2509, 21, 26, 'وَقَالُوا اتَّخَذَ الرَّحْمٰنُ وَلَداً سُبْحَانَهُۜ بَلْ عِبَادٌ مُكْرَمُونَۙ', 'Ve kaluttehazer rahmanu veleden subhaneh, bel ıbadun mukremun.', 'Ve onlar: \"Rahman çocuk edindi.\" dediler. O,  bundan münezzehtir.[1] Onlar[2],  ikram olunmuş[3] kullardır.', 'وقالوا اتخذ الرحمن ولدا سبحنه بل عباد مكرمون'),
(2510, 21, 27, 'لَا يَسْبِقُونَهُ بِالْقَوْلِ وَهُمْ بِاَمْرِه۪ يَعْمَلُونَ', 'La yesbikunehu bil kavli ve hum bi emrihi ya\'melun.', 'Onlar[1],  O\'nun sözüne aykırı hareket edemezler. Onlar,  yalnızca O\'nun buyruğuna uyarlar.', 'لا يسبقونه بالقول وهم بامره يعملون'),
(2511, 21, 28, 'يَعْلَمُ مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَۙ اِلَّا لِمَنِ ارْتَضٰى وَهُمْ مِنْ خَشْيَتِه۪ مُشْفِقُونَ', 'Ya\'lemu ma beyne eydihim ve ma halfehum ve la yeşfeune illa li menirteda ve hum min haşyetihi muşfikun.', 'Allah,  onların bütün yapıp ettiklerini bilir. Ve onlar,  rızasına ermiş olanlardan başkasına şefaat[1] edemezler. Onlar,  O\'na duydukları derin saygıdan titrerler.', 'يعلم ما بين ايديهم وما خلفهم ولا يشفعون الا لمن ارتضي وهم من خشيته مشفقون'),
(2512, 21, 29, 'وَمَنْ يَقُلْ مِنْهُمْ اِنّ۪ٓي اِلٰهٌ مِنْ دُونِه۪ فَذٰلِكَ نَجْز۪يهِ جَهَنَّمَۜ  كَذٰلِكَ نَجْزِي الظَّالِم۪ينَ۟', 'Ve men yekul minhum inni ilahun min dunihi fe zalike neczihi cehennem, kezalike necziz zalimin.', 'Onlardan kim,  \"O\'nun yanı sıra ben de ilahım.\" derse,  işte o zaman onu Cehennem\'le cezalandırırız. Biz,  zalimleri böyle cezalandırırız.', 'ومن يقل منهم اني اله من دونه فذلك نجزيه جهنم كذلك نجزي الظلمين'),
(2513, 21, 30, 'اَوَلَمْ يَرَ الَّذ۪ينَ كَفَرُٓوا اَنَّ السَّمٰوَاتِ وَالْاَرْضَ كَانَتَا رَتْقاً فَفَتَقْنَاهُمَاۜ وَجَعَلْنَا مِنَ الْمَٓاءِ كُلَّ شَيْءٍ حَيٍّۜ اَفَلَا يُؤْمِنُونَ', 'E ve lem yerellezine keferu ennes semavati vel arda kaneta retkan fe fetaknahuma, ve cealna minel mai kulle şey\'in hayy, e fe la yu\'minun.', 'Kafirler[1]; görmüyorlar mı[2] gökler ve yer bitişikti? Biz onları ayırdık. Suyu hayat kaynağı kıldık. Buna rağmen hala inanmıyorlar mı?', 'اولم ير الذين كفروا ان السموت والارض كانتا رتقا ففتقنهما وجعلنا من الما كل شي حي افلا يومنون'),
(2514, 21, 31, 'وَجَعَلْنَا فِي الْاَرْضِ رَوَاسِيَ اَنْ تَم۪يدَ بِهِمْ وَجَعَلْنَا ف۪يهَا فِجَاجاً سُبُلاً لَعَلَّهُمْ يَهْتَدُونَ', 'Ve cealna fil ardı revasiye en temide bihim ve cealna fiha ficacen subulen leallehum yehtedun.', 'Ve Biz,  onları sarsmasın diye yeryüzüne ağır baskılar yerleştirdik. Orada yol bulmaları için geçitler yaptık.', 'وجعلنا في الارض روسي ان تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون'),
(2515, 21, 32, 'وَجَعَلْنَا السَّمَٓاءَ سَقْفاً مَحْفُوظاًۚ وَهُمْ عَنْ اٰيَاتِهَا مُعْرِضُونَ', 'Ve cealnes semae sakfen mahfuza, ve hum an ayatiha mu\'ridun.', 'Gökyüzünü korunmuş bir tavan yaptık. Onlar hala ayetlerimden[1] yüz çeviriyorlar.', 'وجعلنا السما سقفا محفوظا وهم عن ايتها معرضون'),
(2516, 21, 33, 'وَهُوَ الَّذ۪ي خَلَقَ الَّيْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَۜ  كُلٌّ ف۪ي فَلَكٍ يَسْبَحُونَ', 'Ve huvellezi halakal leyle ven nehare veş şemse vel kamer, kullun fi felekin yesbehun.', 'Geceyi ve gündüzü,  Güneş\'i ve Ay\'ı yaratan O\'dur. Onların her biri kendi yörüngesinde yüzmektedir.', 'وهو الذي خلق اليل والنهار والشمس والقمر كل في فلك يسبحون'),
(2517, 21, 34, 'وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَۜ اَفَا۬ئِنْ مِتَّ فَهُمُ الْخَالِدُونَ', 'Ve ma cealna li beşerin min kablikel huld, e fe in mitte fe humul halidun.', 'Biz,  senden önce de hiçbir beşeri ölümsüz kılmadık. Sen öleceksin de onlar süresiz mi yaşayacaklar?', 'وما جعلنا لبشر من قبلك الخلد افان مت فهم الخلدون'),
(2518, 21, 35, 'كُلُّ نَفْسٍ ذَٓائِقَةُ الْمَوْتِۜ وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةًۜ وَاِلَيْنَا تُرْجَعُونَ', 'Kullu nefsin zaikatul mevt, ve neblukum biş şerri vel hayri fitneh, ve ileyna turceun.', 'Her nefs[1] ölümü tadıcıdır. Sizi sınav olarak,  iyilik ve kötülükle sınarız. Ve siz,  yalnız Bize döndürüleceksiniz.', 'كل نفس ذايقة الموت ونبلوكم بالشر والخير فتنة والينا ترجعون'),
(2519, 21, 36, 'وَاِذَا رَاٰكَ الَّذ۪ينَ كَفَرُٓوا اِنْ يَتَّخِذُونَكَ اِلَّا هُزُواًۜ اَهٰذَا الَّذ۪ي يَذْكُرُ اٰلِهَتَكُمْۚ وَهُمْ بِذِكْرِ الرَّحْمٰنِ هُمْ كَافِرُونَ', 'Ve iza reakellezine keferu in yettehızuneke illa huzuva, e hazellezi yezkuru alihetekum, ve hum bi zikrir rahmani hum kafirun.', 'Ve Kafirler seni gördükleri zaman: \"İlahlarınızı zikreden[1] bu mu?\" diye alaya alıyorlar. Onlar,  Rahman\'ın zikrini[2] Küfredenlerdir.[3]', 'واذا راك الذين كفروا ان يتخذونك الا هزوا اهذا الذي يذكر الهتكم وهم بذكر الرحمن هم كفرون'),
(2520, 21, 37, 'خُلِقَ الْاِنْسَانُ مِنْ عَجَلٍۜ سَاُر۪يكُمْ اٰيَات۪ي فَلَا تَسْتَعْجِلُونِ', 'Hulikal insanu min acel, seurikum ayati fe la testa\'cilun.', 'İnsan aceleden yaratılmıştır.[1] Size,  günü gelince ayetlerimi[2] göstereceğim. Acele etmemi istemeyin.', 'خلق الانسن من عجل ساوريكم ايتي فلا تستعجلون'),
(2521, 21, 38, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadıkin.', '\"Eğer doğru söyleyenlerdenseniz bu uyarı ne zaman gerçekleşecek?\" diyorlar.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(2522, 21, 39, 'لَوْ يَعْلَمُ الَّذ۪ينَ كَفَرُوا ح۪ينَ لَا يَكُفُّونَ عَنْ وُجُوهِهِمُ النَّارَ وَلَا عَنْ ظُهُورِهِمْ وَلَا هُمْ يُنْصَرُونَ', 'Lev ya\'lemullezine keferu hine la yekuffune an vucuhihimun nare ve la an zuhurihim ve la hum yunsarun.', 'Kafirler,  kendilerini her yönden saracak ateşi savamayacakları ve yardımsız kalacakları zamanı ah bir bilselerdi!', 'لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون'),
(2523, 21, 40, 'بَلْ تَأْت۪يهِمْ بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَط۪يعُونَ رَدَّهَا وَلَا هُمْ يُنْظَرُونَ', 'Bel te\'tihim bagteten fe tebhetuhum fe la yesteti\'une reddeha ve la hum yunzarun.', 'Aslında,  onlara ansızın gelecek ve onları şaşkına çevirecek. Artık onu geri çevirmeye güçleri yetmeyecek ve onlara süre de verilmeyecek.', 'بل تاتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون'),
(2524, 21, 41, 'وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَحَاقَ بِالَّذ۪ينَ سَخِرُوا مِنْهُمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ۟', 'Ve lekadistuhzie bi rusulin min kablike fe haka billezine sehıru minhum ma kanu bihi yestehziun.', 'Gerçek şu ki senden önce de birçok resulle alay edildi. Sonra alay ettikleri şey,  alay edenleri kuşattı.', 'ولقد استهزي برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزون'),
(2525, 21, 42, 'قُلْ مَنْ يَكْلَؤُ۬كُمْ بِالَّيْلِ وَالنَّهَارِ مِنَ الرَّحْمٰنِۜ بَلْ هُمْ عَنْ ذِكْرِ رَبِّهِمْ مُعْرِضُونَ', 'Kul men yekleukum bil leyli ven nehari miner rahman, bel hum an zikri rabbihim mu\'ridun.', 'De ki: \"Gece ya da gündüz Rahman\'dan sizi kim koruyabilir?[1]\" Doğrusu onlar,  Rabb\'lerinin öğüdünden yüz çevirenlerdir.', 'قل من يكلوكم باليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون'),
(2526, 21, 43, 'اَمْ لَهُمْ اٰلِهَةٌ تَمْنَعُهُمْ مِنْ دُونِنَاۜ لَا يَسْتَط۪يعُونَ نَصْرَ اَنْفُسِهِمْ وَلَا هُمْ مِنَّا يُصْحَبُونَ', 'Em lehum alihetun temneuhum min dunina, la yestetiune nasre enfusihim ve la hum minna yushabun.', 'Yoksa onların,  onları Bize karşı koruyacak ilahları mı var? Onlar,  kendilerine dahi yardıma güç yetiremezler. Ve onlara Bizim tarafımızdan sahip çıkılmaz.', 'ام لهم الهة تمنعهم من دوننا لا يستطيعون نصر انفسهم ولا هم منا يصحبون'),
(2527, 21, 44, 'بَلْ مَتَّعْنَا هٰٓؤُ۬لَٓاءِ وَاٰبَٓاءَهُمْ حَتّٰى طَالَ عَلَيْهِمُ الْعُمُرُۜ اَفَلَا يَرَوْنَ اَنَّا نَأْتِي الْاَرْضَ نَنْقُصُهَا مِنْ اَطْرَافِهَاۜ اَفَهُمُ الْغَالِبُونَ', 'Bel metta\'na haulai ve abaehum hatta tale aleyhimul umur, e fe la yerevne enna ne\'til arda nenkusuha min etrafiha, e fehumul galibun.', 'Oysaki onlara uzun gelen bir ömür boyunca,  onları ve atalarını geçindirdik. Yeryüzüne müdahale edip onun her tarafında birçok şeyi nasıl yok ettiğimizi[1] görmüyorlar mı? O halde galip olanlar onlar mı?', 'بل متعنا هولا واباهم حتي طال عليهم العمر افلا يرون انا ناتي الارض ننقصها من اطرافها افهم الغلبون'),
(2528, 21, 45, 'قُلْ اِنَّـمَٓا اُنْذِرُكُمْ بِالْوَحْيِۘ وَلَا يَسْمَعُ الصُّمُّ الدُّعَٓاءَ اِذَا مَا يُنْذَرُونَ', 'Kul innema unzirukum bil vahyi ve la yesmeus summud duae iza ma yunzerun.', 'De ki: \"Ben sizi ancak vahiy ile uyarıyorum.\" Ne var ki sağırlar uyarılsalar da çağrıyı duymazlar.', 'قل انما انذركم بالوحي ولا يسمع الصم الدعا اذا ما ينذرون'),
(2529, 21, 46, 'وَلَئِنْ مَسَّتْهُمْ نَفْحَةٌ مِنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَا وَيْلَنَٓا اِنَّا كُنَّا ظَالِم۪ينَ', 'Ve le in messethum nefhatun min azabi rabbike le yekulunne ya veylena inna kunna zalimin.', 'Eğer onlara,  Rabb\'inin azabından bir nebze dokunsa,  \"Eyvah bize! Biz kendimize haksızlık edenleriz.\" diyecekler.', 'ولين مستهم نفحة من عذاب ربك ليقولن يويلنا انا كنا ظلمين'),
(2530, 21, 47, 'وَنَضَعُ الْمَوَاز۪ينَ الْقِسْطَ لِيَوْمِ الْقِيٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـٔاًۜ وَاِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ اَتَيْنَا بِهَاۜ وَكَفٰى بِنَا حَاسِب۪ينَ', 'Ve nedaul mevazinel kısta li yevmil kıyameti fe la tuzlemu nefsun şey\'a ve in kane miskale habbetin min hardelin eteyna biha, ve kefa bina hasibin.', 'Kıyamet Günü hak edileni eksiksiz belirleyen tartıları kurarız. Hiç kimse,  hiçbir biçimde haksızlığa uğratılmaz. Hardal tanesi kadar da olsa her şeyi hesaba katarız. Hesap gören olarak Biz yeteriz.', 'ونضع الموزين القسط ليوم القيمة فلا تظلم نفس شيا وان كان مثقال حبة من خردل اتينا بها وكفي بنا حسبين'),
(2531, 21, 48, 'وَلَقَدْ اٰتَيْنَا مُوسٰى وَهٰرُونَ الْفُرْقَانَ وَضِيَٓاءً وَذِكْراً لِلْمُتَّق۪ينَۙ', 'Ve lekad ateyna musa ve harunel furkane ve dıyaen ve zikren lil muttekin.', 'Ant olsun ki,  Musa ve Harun\'a takva sahipleri için bir ışık olan,  bir öğüt olan Furkan\'ı[1] verdik.', 'ولقد اتينا موسي وهرون الفرقان وضيا وذكرا للمتقين'),
(2532, 21, 49, 'اَلَّذ۪ينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ وَهُمْ مِنَ السَّاعَةِ مُشْفِقُونَ', 'Ellezine yahşevne rabbehum bil gaybi ve hum mines saati muşfikun.', 'Onlar,  Rabb\'lerini görmedikleri halde,  O\'na içten derin bir saygı duyarlar. Ve onlar,  Kıyamet Günü\'nün hesabından endişe ederler.', 'الذين يخشون ربهم بالغيب وهم من الساعة مشفقون'),
(2533, 21, 50, 'وَهٰذَا ذِكْرٌ مُبَارَكٌ اَنْزَلْنَاهُۜ  اَفَاَنْتُمْ لَهُ مُنْكِرُونَ۟', 'Ve haza zikrun mubarekun enzelnah, e fe entum lehu munkirun.', 'Bu,  indirdiğimiz çok değerli bir öğüttür. Böyleyken,  siz onu inkar mı edeceksiniz?', 'وهذا ذكر مبارك انزلنه افانتم له منكرون'),
(2534, 21, 51, 'وَلَقَدْ اٰتَيْنَٓا اِبْرٰه۪يمَ رُشْدَهُ مِنْ قَبْلُ وَكُنَّا بِه۪ عَالِم۪ينَۚ', 'Ve lekad ateyna ibrahime ruşdehu min kablu ve kunna bihi alimin.', 'Ant olsun İbrahim\'e rüşdünü[1] vermiştik. Biz,  onu tanıyorduk.', 'ولقد اتينا ابرهيم رشده من قبل وكنا به علمين'),
(2535, 21, 52, 'اِذْ قَالَ لِاَب۪يهِ وَقَوْمِه۪ مَا هٰذِهِ التَّمَاث۪يلُ الَّت۪ٓي اَنْتُمْ لَهَا عَاكِفُونَ', 'İz kale li ebihi ve kavmihi ma hazihit temasilulleti entum leha akifun.', 'Hani o,  babasına ve halkına: \"Kendinizi adadığınız bu heykeller nedir?\" dedi.', 'اذ قال لابيه وقومه ما هذه التماثيل التي انتم لها عكفون'),
(2536, 21, 53, 'قَالُوا وَجَدْنَٓا اٰبَٓاءَنَا لَهَا عَابِد۪ينَ', 'Kalu vecedna abaena leha abidin.', '\"Biz,  atalarımızı bunlara kulluk edenler olarak bulduk.\" dediler.', 'قالوا وجدنا ابانا لها عبدين'),
(2537, 21, 54, 'قَالَ لَقَدْ كُنْتُمْ اَنْتُمْ وَاٰبَٓاؤُ۬كُمْ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Kale lekad kuntum entum ve abaukum fi dalalin mubin.', '\"Gerçek şu ki siz de,  atalarınız da açık bir sapkınlık içindesiniz.\" dedi.', 'قال لقد كنتم انتم واباوكم في ضلل مبين'),
(2538, 21, 55, 'قَالُٓوا اَجِئْتَنَا بِالْحَقِّ اَمْ اَنْتَ مِنَ اللَّاعِب۪ينَ', 'Kalu e ci\'tena bil hakkı em ente minel laıbin.', '\"Gerçeği mi getirdin,  yoksa bizimle oyun mu oynuyorsun?\" dediler.', 'قالوا اجيتنا بالحق ام انت من اللعبين'),
(2539, 21, 56, 'قَالَ بَلْ رَبُّكُمْ رَبُّ السَّمٰوَاتِ وَالْاَرْضِ الَّذ۪ي فَطَرَهُنَّۘ وَاَنَا۬ عَلٰى ذٰلِكُمْ مِنَ الشَّاهِد۪ينَ', 'Kale bel rabbukum rabbus semavati vel ardıllezi fatarahunne ve ene ala zalikum mineş şahidin.', '\"Hayır! Sizin Rabb\'iniz göklerin ve yerin Rabb\'idir. Onlara işleyiş yasalarını O koymuştur. Bunun böyle olduğundan kesinlikle eminim.\"', 'قال بل ربكم رب السموت والارض الذي فطرهن وانا علي ذلكم من الشهدين'),
(2540, 21, 57, 'وَتَاللّٰهِ لَاَك۪يدَنَّ اَصْنَامَكُمْ بَعْدَ اَنْ تُوَلُّوا مُدْبِر۪ينَ', 'Ve tallahi le ekidenne asnamekum ba\'de en tuvellu mudbirin.', '\"Allah\'a yemin ederim ki,  siz buradan ayrıldıktan sonra,  putlarınız hakkında tasarladığımı gerçekleştireceğim.\"', 'وتالله لاكيدن اصنمكم بعد ان تولوا مدبرين'),
(2541, 21, 58, 'فَجَعَلَهُمْ جُذَاذاً اِلَّا كَب۪يراً لَهُمْ لَعَلَّهُمْ اِلَيْهِ يَرْجِعُونَ', 'Fe cealehum cuzazen illa kebiren lehum leallehum ileyhi yerciun.', 'Sonra da kendisine sorsunlar diye,  büyük olanı hariç diğerlerini parça parça etti.', 'فجعلهم جذذا الا كبيرا لهم لعلهم اليه يرجعون'),
(2542, 21, 59, 'قَالُوا مَنْ فَعَلَ هٰذَا بِاٰلِهَتِنَٓا اِنَّهُ لَمِنَ الظَّالِم۪ينَ', 'Kalu men feale haza bi alihetina innehu le minez zalimin.', '\"Bizim ilahlarımıza bunu kim yaptı? Kuşku yok ki o,  gerçekten zalimlerdendir.\" dediler.', 'قالوا من فعل هذا بالهتنا انه لمن الظلمين'),
(2543, 21, 60, 'قَالُوا سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَـهُٓ اِبْرٰه۪يمُۜ', 'Kalu semi\'na feten yezkuruhum yukalu lehu ibrahim.', '\"İbrahim adında bir gencin onlardan söz ettiğini duyduk.\" dediler.', 'قالوا سمعنا فتي يذكرهم يقال له ابرهيم'),
(2544, 21, 61, 'قَالُوا فَأْتُوا بِه۪ عَلٰٓى اَعْيُنِ النَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', 'Kalu fe\'tu bihi ala a\'yunin nasi leallehum yeşhedun.', '\"O halde onu insanların huzuruna getirin. Belki tanıklık eden çıkar\" dediler.', 'قالوا فاتوا به علي اعين الناس لعلهم يشهدون'),
(2545, 21, 62, 'قَالُٓوا ءَاَنْتَ فَعَلْتَ هٰذَا بِاٰلِهَتِنَا يَٓا اِبْرٰه۪يمُۜ', 'Kalu e ente fealte haza bi alihetina ya ibrahim.', '\"Ey İbrahim! İlahlarımıza bunu sen mi yaptın?\" dediler.', 'قالوا انت فعلت هذا بالهتنا يابرهيم'),
(2546, 21, 63, 'قَالَ بَلْ فَعَلَهُۗ كَب۪يرُهُمْ هٰذَا فَسْـَٔلُوهُمْ اِنْ كَانُوا يَنْطِقُونَ', 'Kale bel fealehu kebiruhum haza fes\'eluhum in kanu yentıkun.', '\"Hayır,  onu şu büyükleri yapmıştır. Eğer konuşabilirlerse haydi onlara sorun!\" dedi.', 'قال بل فعله كبيرهم هذا فسلوهم ان كانوا ينطقون'),
(2547, 21, 64, 'فَرَجَعُٓوا اِلٰٓى اَنْفُسِهِمْ فَقَالُٓوا اِنَّكُمْ اَنْتُمُ الظَّالِمُونَۙ', 'Fe receu ila enfusihim fe kalu innekum entumuz zalimun.', 'Bunun üzerine birbirlerine dönüp,  \"Haksızlık ediyoruz.\" dediler.', 'فرجعوا الي انفسهم فقالوا انكم انتم الظلمون'),
(2548, 21, 65, 'ثُمَّ نُكِسُوا عَلٰى رُؤُ۫سِهِمْۚ لَقَدْ عَلِمْتَ مَا هٰٓؤُ۬لَٓاءِ يَنْطِقُونَ', 'Summe nukisu ala ruusihim, lekad alimte ma haulai yentıkun.', 'Sonra çok geçmeden yine eski kafalarına döndürüldüler: \"Gerçek şu ki sen bunların konuşmadıklarını biliyorsun!\" dediler.', 'ثم نكسوا علي روسهم لقد علمت ما هولا ينطقون'),
(2549, 21, 66, 'قَالَ اَفَتَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَا يَنْفَعُكُمْ شَيْـٔاً وَلَا يَضُرُّكُمْۜ', 'Kale e fe ta\'budune min dunillahi ma la yenfeukum şey\'en ve la yadurrukum.', 'İbrahim: \"Allah\'ı bırakıp da size bir faydası da bir zararı da olmayan şeylere mi kulluk ediyorsunuz?\" dedi.', 'قال افتعبدون من دون الله ما لا ينفعكم شيا ولا يضركم'),
(2550, 21, 67, 'اُفٍّ لَكُمْ وَلِمَا تَعْبُدُونَ مِنْ دُونِ اللّٰهِۜ اَفَلَا تَعْقِلُونَ', 'Uffin lekum ve li ma ta\'budune min dunillah, e fe la ta\'kılun.', '\"Yazıklar olsun size ve Allah\'ın yanı sıra kulluk ettiğiniz şeylere. Siz hala aklınızı kullanmayacak mısınız?\"', 'اف لكم ولما تعبدون من دون الله افلا تعقلون'),
(2551, 21, 68, 'قَالُوا حَرِّقُوهُ وَانْصُرُٓوا اٰلِهَتَكُمْ اِنْ كُنْتُمْ فَاعِل۪ينَ', 'Kalu harrikuhu vansuru alihetekum in kuntum faılin.', 'Halk: \"Eğer yapabilirseniz,  onu yakın! İlahlarınızın intikamını alın!\" dediler.', 'قالوا حرقوه وانصروا الهتكم ان كنتم فعلين'),
(2552, 21, 69, 'قُلْنَا يَا نَارُ كُون۪ي بَرْداً وَسَلَاماً عَلٰٓى اِبْرٰه۪يمَۙ', 'Kulna ya naru kuni berden ve selamen ala ibrahim.', '\"Ey ateş! İbrahim\'e serin ve esenlik ol.\" dedik.', 'قلنا ينار كوني بردا وسلما علي ابرهيم'),
(2553, 21, 70, 'وَاَرَادُوا بِه۪ كَيْداً فَجَعَلْنَاهُمُ الْاَخْسَر۪ينَۚ', 'Ve eradu bihi keyden fe cealna humul ahserin.', 'Ona tuzak kurmak istediler. Fakat onları hüsrana uğrattık.', 'وارادوا به كيدا فجعلنهم الاخسرين'),
(2554, 21, 71, 'وَنَجَّيْنَاهُ وَلُوطاً اِلَى الْاَرْضِ الَّت۪ي بَارَكْنَا ف۪يهَا لِلْعَالَم۪ينَ', 'Ve necceynahu ve lutan ilel ardılleti barakna fiha lil alemin.', 'Onu ve Lut\'u kurtarıp,  alemler için bereketli kıldığımız yurda ulaştırdık.', 'ونجينه ولوطا الي الارض التي بركنا فيها للعلمين'),
(2555, 21, 72, 'وَوَهَبْنَا لَـهُٓ اِسْحٰقَۜ وَيَعْقُوبَ نَافِلَةًۜ وَكُلاًّ جَعَلْنَا صَالِح۪ينَ', 'Ve vehebna lehu ishak, ve ya\'kube nafileh, ve kullen cealna salihin.', 'Ona İshak\'ı ve ayrıca Yakub\'u armağan ettik. Ve hepsini iyi kimseler yaptık.', 'ووهبنا له اسحق ويعقوب نافلة وكلا جعلنا صلحين'),
(2556, 21, 73, 'وَجَعَلْنَاهُمْ اَئِمَّةً يَهْدُونَ بِاَمْرِنَا وَاَوْحَيْنَٓا اِلَيْهِمْ فِعْلَ الْخَيْرَاتِ وَاِقَامَ الصَّلٰوةِ وَا۪يتَٓاءَ الزَّكٰوةِۚ وَكَانُوا لَنَا عَابِد۪ينَۙ', 'Ve cealnahum eimmeten yehdune bi emrina ve evhayna ileyhim fi\'lel hayrati ve ikames salati ve itaez zekah, ve kanu lena abidin.', 'Onları,  buyruklarımızla doğru yolu gösteren önderler kıldık. Onlara hayırlar yapmayı,  salatı[1] ikame etmeyi,  zekatı yapmayı[1] vahyettik. Ve onlar yalnızca bize kulluk eden kimselerdi.', 'وجعلنهم ايمة يهدون بامرنا واوحينا اليهم فعل الخيرت واقام الصلوة وايتا الزكوة وكانوا لنا عبدين'),
(2557, 21, 74, 'وَلُوطاً اٰتَيْنَاهُ حُكْماً وَعِلْماً وَنَجَّيْنَاهُ مِنَ الْقَرْيَةِ الَّت۪ي كَانَتْ تَعْمَلُ الْخَبَٓائِثَۜ اِنَّهُمْ كَانُوا قَوْمَ سَوْءٍ فَاسِق۪ينَۙ', 'Ve lutan ateynahu hukmen ve ılmen ve necceynahu minel karyetilleti kanet ta\'melul habais, innehum kanu kavme sev\'in fasikin.', 'Biz,  Lut\'a bir hüküm,  bir ilim[1] verdik. Onu çirkin işler yapan kentten kurtardık. Onlar fasık[2] olan kötü bir halktı.', 'ولوطا اتينه حكما وعلما ونجينه من القرية التي كانت تعمل الخبيث انهم كانوا قوم سو فسقين'),
(2558, 21, 75, 'وَاَدْخَلْنَاهُ ف۪ي رَحْمَتِنَاۜ اِنَّهُ مِنَ الصَّالِح۪ينَ۟', 'Ve edhalnahu fi rahmetina, innehu mines salihin.', 'Onu rahmetimize dahil ettik. O salihlerdendi[1].', 'وادخلنه في رحمتنا انه من الصلحين'),
(2559, 21, 76, 'وَنُوحاً اِذْ نَادٰى مِنْ قَبْلُ فَاسْتَجَبْنَا لَهُ فَنَجَّيْنَاهُ وَاَهْلَهُ مِنَ الْكَرْبِ الْعَظ۪يمِۚ', 'Ve nuhan iz nada min kablu festecebna lehu fe necceynahu ve ehlehu minel kerbil azim.', 'Ve Nuh\'u da hani o daha önce bize çağrıda bulunmuştu. Biz de çağrısına karşılık verdik. Onu ve ehlini[1] büyük bir felaketten kurtardık.', 'ونوحا اذ نادي من قبل فاستجبنا له فنجينه واهله من الكرب العظيم'),
(2560, 21, 77, 'وَنَصَرْنَاهُ مِنَ الْقَوْمِ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَاۜ اِنَّهُمْ كَانُوا قَوْمَ سَوْءٍ فَاَغْرَقْنَاهُمْ اَجْمَع۪ينَ', 'Ve nasarnahu minel kavmillezine kezzebu bi ayatina, innehum kanu kavme sev\'in fe agraknahum ecmain.', 'Âyetlerimizi yalanlayan bir halka karşı ona yardım ettik. Onlar kötü bir halktı. Bundan dolayı Biz de hepsini boğduk.', 'ونصرنه من القوم الذين كذبوا بايتنا انهم كانوا قوم سو فاغرقنهم اجمعين'),
(2561, 21, 78, 'وَدَاوُ۫دَ وَسُلَيْمٰنَ اِذْ يَحْكُمَانِ فِي الْحَرْثِ اِذْ نَفَشَتْ ف۪يهِ غَنَمُ الْقَوْمِۚ وَكُنَّا لِحُكْمِهِمْ شَاهِد۪ينَۙ', 'Ve davude ve suleymane iz yahkumani fil harsi iz nefeşet fihi ganemul kavm, ve kunna li hukmihim şahidin.', 'Hani Davud ve Süleyman,  halkın koyunlarının yayıldıkları ekin hakkında hüküm veriyorlardı. Biz,  onların hükümlerine tanıktık.', 'وداود وسليمن اذ يحكمان في الحرث اذ نفشت فيه غنم القوم وكنا لحكمهم شهدين'),
(2562, 21, 79, 'فَفَهَّمْنَاهَا سُلَيْمٰنَۚ وَكُلاًّ اٰتَيْنَا حُكْماً وَعِلْماًۘ وَسَخَّرْنَا مَعَ دَاوُ۫دَ الْجِبَالَ يُسَبِّحْنَ وَالطَّيْرَۜ وَكُنَّا فَاعِل۪ينَ', 'Fe fehhemnaha suleyman, ve kullen ateyna hukmen ve ılmen ve sehharna mea davudel cibale yusebbihne vet tayr, ve kunna faılin.', 'Biz,  bunu Süleyman\'a iyice kavrattık. Her ikisine de hüküm[1] ve ilim[2] verdik. Davud\'la beraber tesbih[3] etsinler diye dağları ve kuşları buyruk altına aldık. Ve Biz,  yapanlarız.', 'ففهمنها سليمن وكلا اتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فعلين'),
(2563, 21, 80, 'وَعَلَّمْنَاهُ صَنْعَةَ لَبُوسٍ لَكُمْ لِتُحْصِنَكُمْ مِنْ بَأْسِكُمْۚ فَهَلْ اَنْتُمْ شَاكِرُونَ', 'Ve allemnahu san\'ate lebusin lekum li tuhsınekum min be\'sikum, fe hel entum şakirun.', 'Ona; sizi,  sizin şiddetinizden koruyacak elbise[1] yapma sanatını öğrettik. Öyleyse şükredenler misiniz?', 'وعلمنه صنعة لبوس لكم لتحصنكم من باسكم فهل انتم شكرون'),
(2564, 21, 81, 'وَلِسُلَيْمٰنَ الرّ۪يحَ عَاصِفَةً تَجْر۪ي بِاَمْرِه۪ٓ اِلَى الْاَرْضِ الَّت۪ي بَارَكْنَا ف۪يهَاۜ وَكُنَّا بِكُلِّ شَيْءٍ عَالِم۪ينَ', 'Ve li suleymaner riha asıfeten tecri bi emrihi ilel ardılleti barekna fiha ve kunna bi kulli şey\'in alimin.', 'Ve şiddetli esen rüzgar Süleyman içindi. Onun isteğine uygun şekilde bereketli yerlere doğru eser giderdi. Biz,  Her Şeyi Bilenleriz.', 'ولسليمن الريح عاصفة تجري بامره الي الارض التي بركنا فيها وكنا بكل شي علمين'),
(2565, 21, 82, 'وَمِنَ الشَّيَاط۪ينِ مَنْ يَغُوصُونَ لَهُ وَيَعْمَلُونَ عَمَلاً دُونَ ذٰلِكَۚ وَكُنَّا لَهُمْ حَافِظ۪ينَۙ', 'Ve mineş şeyatini men yegusune lehu ve ya\'melune amelen dune zalik, ve kunna lehum hafızin.', 'Ve şeytanlardan[1] kendisi için dalgıçlık eden ve bundan başka iş yapanlar vardı. Onları gözetim altında tutuyorduk.', 'ومن الشيطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حفظين'),
(2566, 21, 83, 'وَاَيُّوبَ اِذْ نَادٰى رَبَّهُٓ اَنّ۪ي مَسَّنِيَ الضُّرُّ وَاَنْتَ اَرْحَمُ الرَّاحِم۪ينَۚ', 'Ve eyyube iz nada rabbehu enni messeniyed durru ve ente erhamur rahimin.', 'Eyyub\'u da an! Hani o: \"Bana bir dert dokundu. Ve Sen,  merhamet edenlerin en merhametlisisin.\" diye Rabb\'ine seslenmişti.', 'وايوب اذ نادي ربه اني مسني الضر وانت ارحم الرحمين'),
(2567, 21, 84, 'فَاسْتَجَبْنَا لَهُ فَكَشَفْنَا مَا بِه۪ مِنْ ضُرٍّ وَاٰتَيْنَاهُ اَهْلَهُ وَمِثْلَهُمْ مَعَهُمْ رَحْمَةً مِنْ عِنْدِنَا وَذِكْرٰى لِلْعَابِد۪ينَ', 'Festecebna lehu fe keşefna ma bihi min durrin ve ateynahu ehlehu ve mislehum meahum rahmeten min ındina ve zikra lil abidin.', 'Biz de onun çağrısına karşılık verdik. Ve derdini yok ettik. Ve katımızdan bir rahmet ve kulluk edenlere bir öğüt olmak üzere,  kendisine ehlini[1] ve onlarla birlikte bir mislini daha verdik.', 'فاستجبنا له فكشفنا ما به من ضر واتينه اهله ومثلهم معهم رحمة من عندنا وذكري للعبدين'),
(2568, 21, 85, 'وَاِسْمٰع۪يلَ وَاِدْر۪يسَ وَذَا الْكِفْلِۜ  كُلٌّ مِنَ الصَّابِر۪ينَۚ', 'Ve ismaile ve idrise ve zelkifl, kullun mines sabirin.', 'İsmail\'i,  İdris\'i ve Zelkifl\'i de an. Hepsi sabredenlerdendi.', 'واسمعيل وادريس وذا الكفل كل من الصبرين'),
(2569, 21, 86, 'وَاَدْخَلْنَاهُمْ ف۪ي رَحْمَتِنَاۜ اِنَّهُمْ مِنَ الصَّالِح۪ينَ', 'Ve edhalnahum fi rahmetina, innehum mines salihin.', 'Onları rahmetimizle kuşattık. Onlar salih[1] kimselerdi.', 'وادخلنهم في رحمتنا انهم من الصلحين'),
(2570, 21, 87, 'وَذَا النُّونِ اِذْ ذَهَبَ مُغَاضِباً فَظَنَّ اَنْ لَنْ نَقْدِرَ عَلَيْهِ فَنَادٰى فِي الظُّلُمَاتِ اَنْ لَٓا اِلٰهَ اِلَّٓا اَنْتَ سُبْحَانَكَۗ اِنّ۪ي كُنْتُ مِنَ الظَّالِم۪ينَۚ', 'Ve zennuni iz zehebe mugadıben fe zanne en len nakdire aleyhi fe nada fiz zulumati en la ilahe illa ente subhaneke inni kuntu minez zalimin.', 'Ve Zü\'n-Nun\'u[1] da an! Hani öfkelenerek gitmişti de kendisini sıkıntıda bırakmayacağımızı sanmıştı. Sonra karanlıklar içinde,  \"Senden başka ilah yoktur! Sen yüceler yücesisin. Ben haksızlık yaptım!\" diye seslenmişti.', 'وذا النون اذ ذهب مغضبا فظن ان لن نقدر عليه فنادي في الظلمت ان لا اله الا انت سبحنك اني كنت من الظلمين'),
(2571, 21, 88, 'فَاسْتَجَبْنَا لَهُۙ وَنَجَّيْنَاهُ مِنَ الْغَمِّۜ وَكَذٰلِكَ نُنْجِي الْمُؤْمِن۪ينَ', 'Festecebna lehu ve necceynahu minel gamm, ve kezalike nuncil mu\'minin.', 'Bunun üzerine çağrısına karşılık verdik ve onu sıkıntıdan kurtardık. İşte inananları böyle kurtarırız.', 'فاستجبنا له ونجينه من الغم وكذلك نجي المومنين'),
(2572, 21, 89, 'وَزَكَرِيَّٓا اِذْ نَادٰى رَبَّهُ رَبِّ لَا تَذَرْن۪ي فَرْداً وَاَنْتَ خَيْرُ الْوَارِث۪ينَۚ', 'Ve zekeriyya iz nada rabbehu rabbi la tezerni ferden ve ente hayrul varisin.', 'Ve Zekeriyya\'yı da an! Rabb\'ine: \"Rabb\'im! Beni tek başıma bırakma,  Sen varislerin[1] en hayırlısısın.\" diye seslenmişti.', 'وزكريا اذ نادي ربه رب لا تذرني فردا وانت خير الورثين'),
(2573, 21, 90, 'فَاسْتَجَبْنَا لَهُۘ وَوَهَبْنَا لَهُ يَحْيٰى وَاَصْلَحْنَا لَهُ زَوْجَهُۜ اِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَباً وَرَهَباًۜ وَكَانُوا لَنَا خَاشِع۪ينَ', 'Festecebna leh, ve vehebna lehu yahya ve aslahna lehu zevceh, innehum kanu yusariune fil hayrati ve yed\'unena regaben ve reheba, ve kanu lena haşiin.', 'Bunun üzerine çağrısına karşılık verdik. Ve kendisine Yahya\'yı armağan ettik. Ve onun için eşini ıslah[1] ettik. Onlar hayırlarda yarışıyor,  umarak ve endişe ederek Bize yalvarıyorlardı. Ve Bize karşı içtenlikle saygı duyuyorlardı.', 'فاستجبنا له ووهبنا له يحيي واصلحنا له زوجه انهم كانوا يسرعون في الخيرت ويدعوننا رغبا ورهبا وكانوا لنا خشعين'),
(2574, 21, 91, 'وَالَّت۪ٓي اَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا ف۪يهَا مِنْ رُوحِنَا وَجَعَلْنَاهَا وَابْنَهَٓا اٰيَةً لِلْعَالَم۪ينَ', 'Velleti ahsanet ferceha fe nefahna fiha min ruhina ve cealnaha vebneha ayeten lil alemin.', 'Ve namusunu koruyanı da an.[1] Ona ruhumuzdan üfledik.[2] Ve kendisini ve oğlunu alemler için bir ayet[3] kıldık.', 'والتي احصنت فرجها فنفخنا فيها من روحنا وجعلنها وابنها اية للعلمين'),
(2575, 21, 92, 'اِنَّ هٰذِه۪ٓ اُمَّتُكُمْ اُمَّةً وَاحِدَةًۘ وَاَنَا۬ رَبُّكُمْ فَاعْبُدُونِ', 'İnne hazihi ummetukum ummeten vahıdeten ve ene rabbukum fa\'budun.', 'Bu sizin ümmetiniz tek bir ümmettir. Çünkü hepinizin Rabb\'i Ben\'im. O halde yalnızca Bana kulluk edin!', 'ان هذه امتكم امة وحدة وانا ربكم فاعبدون'),
(2576, 21, 93, 'وَتَقَطَّعُٓوا اَمْرَهُمْ بَيْنَهُمْۜ كُلٌّ اِلَيْنَا رَاجِعُونَ۟', 'Ve tekattau emrehum beynehum, kullun ileyna raciun.', 'Emirlerini[1] aralarında bölük pörçük ettiler. Oysa hepsi yalnızca Bize dönecekler.', 'وتقطعوا امرهم بينهم كل الينا رجعون'),
(2577, 21, 94, 'فَمَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِه۪ۚ وَاِنَّا لَهُ كَاتِبُونَ', 'Fe men ya\'mel mines salihati ve huve mu\'minun fe la kufrane li sa\'yih, ve inna lehu katibun.', 'Fakat kim inanmış olarak salihat[1] yaparsa,  onun çabası için kafirlik[2] yapılmaz. Biz,  bütün çabalarını yazmaktayız.', 'فمن يعمل من الصلحت وهو مومن فلا كفران لسعيه وانا له كتبون'),
(2578, 21, 95, 'وَحَرَامٌ عَلٰى قَرْيَةٍ اَهْلَكْنَاهَٓا اَنَّهُمْ لَا يَرْجِعُونَ', 'Ve haramun ala karyetin ehleknaha ennehum la yerciun.', 'Yok ettiğimiz bir kent halkının geri dönmesi haramdır.[1] Onlar bir daha geri dönemezler.', 'وحرم علي قرية اهلكنها انهم لا يرجعون'),
(2579, 21, 96, 'حَتّٰٓى اِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ', 'Hatta iza futihat ye\'cucu ve me\'cucu ve hum min kulli hadebin yensilun.', 'Hatta Ye\'cuc ve Me\'cuc[1] yaygınlaşıp her tarafı kuşatma altına alıncaya kadar.', 'حتي اذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون'),
(2580, 21, 97, 'وَاقْتَرَبَ الْوَعْدُ الْحَقُّ فَاِذَا هِيَ شَاخِصَةٌ اَبْصَارُ الَّذ۪ينَ كَفَرُواۜ يَا وَيْلَنَا قَدْ كُنَّا ف۪ي غَفْلَةٍ مِنْ هٰذَا بَلْ كُنَّا ظَالِم۪ينَ', 'Vakterabel va\'dul hakku fe iza hiye şahısatun ebsarullezine keferu, ya veylena kad kunna fi gafletin min haza bel kunna zalimin.', 'Uyarıldıkları gerçekle yüz yüze geldiklerinde,  Kafirlerin gözleri korku ile büyür. \"Eyvah bizlere! Gerçekten biz aldanış içindeymişiz. Aslında biz,  kendimize haksızlık etmişiz.\"', 'واقترب الوعد الحق فاذا هي شخصة ابصر الذين كفروا يويلنا قد كنا في غفلة من هذا بل كنا ظلمين'),
(2581, 21, 98, 'اِنَّكُمْ وَمَا تَعْبُدُونَ مِنْ دُونِ اللّٰهِ حَصَبُ جَهَنَّمَۜ اَنْتُمْ لَهَا وَارِدُونَ', 'İnnekum ve ma ta\'budune min dunillahi hasabu cehennem, entum leha varidun.', 'Siz ve Allah\'ın yanı sıra kulluk[1] ettikleriniz,  Cehennem\'in odunusunuz. Siz oraya gireceksiniz.', 'انكم وما تعبدون من دون الله حصب جهنم انتم لها وردون'),
(2582, 21, 99, 'لَوْ كَانَ هٰٓؤُ۬لَٓاءِ اٰلِهَةً مَا وَرَدُوهَاۜ وَكُلٌّ ف۪يهَا خَالِدُونَ', 'Lev kane haulai aliheten ma veraduha, ve kullun fiha halidun.', 'Eğer onlar gerçekten ilah olsalardı,  Cehennem\'e girmezlerdi. Oysa hepsi orada sürekli kalacaklardır.', 'لو كان هولا الهة ما وردوها وكل فيها خلدون'),
(2583, 21, 100, 'لَهُمْ ف۪يهَا زَف۪يرٌ وَهُمْ ف۪يهَا لَا يَسْمَعُونَ', 'Lehum fiha zefirun ve hum fiha la yesmeun.', 'Onlar için orada bir inleme vardır ve onlar orada kendi inlemelerinden başka bir şey işitmezler.', 'لهم فيها زفير وهم فيها لا يسمعون'),
(2584, 21, 101, 'اِنَّ الَّذ۪ينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنٰٓىۙ اُو۬لٰٓئِكَ عَنْهَا مُبْعَدُونَۙ', 'İnnellezine sebekat lehum minnel husna ulaike anha mub\'adun.', 'Bizden kendilerine iyilik ulaşanlar,  işte onlar,  ondan[1] uzaklaştırılanlardır.', 'ان الذين سبقت لهم منا الحسني اوليك عنها مبعدون'),
(2585, 21, 102, 'لَا يَسْمَعُونَ حَس۪يسَهَاۚ وَهُمْ ف۪ي مَا اشْتَهَتْ اَنْفُسُهُمْ خَالِدُونَۚ', 'La yesme\'une hasiseha, ve hum fi meştehet enfusuhum halidun.', 'Onlar,  Cehennem\'in uğultusunu bile duymazlar. Ve onlar canlarının istediği şeylerin içinde sürekli kalacaklardır.[1]', 'لا يسمعون حسيسها وهم في ما اشتهت انفسهم خلدون'),
(2586, 21, 103, 'لَا يَحْزُنُهُمُ الْفَزَعُ الْاَكْبَرُ وَتَتَلَقّٰيهُمُ الْمَلٰٓئِكَةُۜ هٰذَا يَوْمُكُمُ الَّذ۪ي كُنْتُمْ تُوعَدُونَ', 'La yahzunuhumul fezeul ekberu ve tetelakkahumul melaikeh, haza yevmukumullezi kuntum tuadun.', 'O en büyük dehşet,  onları kaygılandırmayacak. Ve melekler,  \"İşte bu,  size söz verilen gününüzdür.\" diye onları karşılayacaklar.', 'لا يحزنهم الفزع الاكبر وتتلقيهم المليكة هذا يومكم الذي كنتم توعدون'),
(2587, 21, 104, 'يَوْمَ نَطْوِي السَّمَٓاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِۜ كَمَا بَدَأْنَٓا اَوَّلَ خَلْقٍ نُع۪يدُهُۜ وَعْداً عَلَيْنَاۜ اِنَّا كُنَّا فَاعِل۪ينَ', 'Yevme natvis semae ke tayyis sicilli lil kutub, kema bede\'na evvele halkın nuiduh, va\'den aleyna, inna kunna faılin.', 'O gün,  kitap sayfalarını dürer gibi göğü düreriz. Onu[1] ilk yarattığımız gibi yeniden yaratacağız. Bu Bizim katımızdan verilmiş bir sözdür. Kuşkusuz sözümüzü yerine getiririz.', 'يوم نطوي السما كطي السجل للكتب كما بدانا اول خلق نعيده وعدا علينا انا كنا فعلين'),
(2588, 21, 105, 'وَلَقَدْ كَتَبْنَا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ اَنَّ الْاَرْضَ يَرِثُهَا عِبَادِيَ الصَّالِحُونَ', 'Ve lekad ketebna fiz zeburi min ba\'diz zikri ennel arda yerisuha ıbadiyes salihun.', 'Ve ant olsun ki Biz,  zikirden[1] sonra zeburda[2],  arza[3] salih[4] kullarımızın varis olacağını yazdık.', 'ولقد كتبنا في الزبور من بعد الذكر ان الارض يرثها عبادي الصلحون'),
(2589, 21, 106, 'اِنَّ ف۪ي هٰذَا لَبَلَاغاً لِقَوْمٍ عَابِد۪ينَۜ', 'İnne fi haza le belagan li kavmin abidin.', 'Bunda kulluk eden bir toplum için açık bir duyuru vardır.', 'ان في هذا لبلغا لقوم عبدين'),
(2590, 21, 107, 'وَمَٓا اَرْسَلْنَاكَ اِلَّا رَحْمَةً لِلْعَالَم۪ينَ', 'Ve ma erselnake illa rahmeten lil alemin.', 'Biz,  seni bütün insanlık için sadece bir rahmet olarak gönderdik.', 'وما ارسلنك الا رحمة للعلمين'),
(2591, 21, 108, 'قُلْ اِنَّمَا يُوحٰٓى اِلَيَّ اَنَّـمَٓا اِلٰهُكُمْ اِلٰهٌ وَاحِدٌۚ فَهَلْ اَنْتُمْ مُسْلِمُونَ', 'Kul innema yuha ileyye ennema ilahukum ilahun vahid, fe hel entum muslimun.', 'De ki: \"Bana,  sizin ilahınızın ancak tek bir ilah olduğu vahyolundu. Artık O\'na teslim olacak mısınız?\"', 'قل انما يوحي الي انما الهكم اله وحد فهل انتم مسلمون'),
(2592, 21, 109, 'فَاِنْ تَوَلَّوْا فَقُلْ اٰذَنْتُكُمْ عَلٰى سَوَٓاءٍۜ وَاِنْ اَدْر۪ٓي اَقَر۪يبٌ اَمْ بَع۪يدٌ مَا تُوعَدُونَ', 'Fe in tevellev fe kul azentukum ala seva\', ve in edri e karibun em baidun ma tuadun.', 'Buna rağmen yüz çevirirlerse,  o zaman de ki: \"Herkese eşit olarak duyurdum. Söz verilen şey yakın mı uzak mı orasını bilmiyorum!\"', 'فان تولوا فقل اذنتكم علي سوا وان ادري اقريب ام بعيد ما توعدون'),
(2593, 21, 110, 'اِنَّهُ يَعْلَمُ الْجَهْرَ مِنَ الْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'İnnehu ya\'lemul cehre minel kavli ve ya\'lemu ma tektumun.', '\"O,  açıkça söylenen sözleri de bilir,  gizlediklerinizi de bilir.\"', 'انه يعلم الجهر من القول ويعلم ما تكتمون'),
(2594, 21, 111, 'وَاِنْ اَدْر۪ي لَعَلَّهُ فِتْنَةٌ لَكُمْ وَمَتَاعٌ اِلٰى ح۪ينٍ', 'Ve in edri leallehu fitnetun lekum ve metaun ila hin.', '\"Bilemem,  belki o[1] bir sınav ve sizin için belli bir zamana kadar yararlanmadır.\"', 'وان ادري لعله فتنة لكم ومتع الي حين'),
(2595, 21, 112, 'قَالَ رَبِّ احْكُمْ بِالْحَقِّۜ وَرَبُّنَا الرَّحْمٰنُ الْمُسْتَعَانُ عَلٰى مَا تَصِفُونَ', 'Kale rabbıhkum bil hakk, ve rabbuner rahmanul musteanu ala ma tasıfun.', 'Dedi ki: \"Rabb\'im! Aramızda Hakk ile hükmet. Ve Rabb\'imiz,  yakıştırmalarınıza karşı yardım istenecek Rahman\'dır.\"[1]', 'قل رب احكم بالحق وربنا الرحمن المستعان علي ما تصفون'),
(2596, 22, 1, 'يَٓا اَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْۚ اِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظ۪يمٌ', 'Ya eyyuhen nasutteku rabbekum, inne zelzeletes saati şey\'un azim.', 'Ey insanlar! Rabb\'inize karşı takva[1] sahibi olun. Kuşkusuz,  o Sa\'atin[1] şiddetli sarsıntısı çok büyük bir şeydir.', 'يايها الناس اتقوا ربكم ان زلزلة الساعة شي عظيم'),
(2597, 22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّٓا اَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَارٰى وَمَا هُمْ بِسُكَارٰى وَلٰكِنَّ عَذَابَ اللّٰهِ شَد۪يدٌ', 'Yevme teravneha tezhelu kullu murdıatin amma erdaat ve tedau kullu zati hamlin hamleha ve teren nase sukara ve ma hum bi sukara ve lakinne azaballahi şedid.', 'Onu gördüğünüz gün,  her emzikli kadın emzirdiğini unutur. Her hamile kadın,  bebeğini düşürür. Ve insanları sarhoş olmadıkları halde,  sarhoş gibi görürsün. Zira Allah\'ın azabı çok şiddetlidir.', 'يوم ترونها تذهل كل مرضعة عما ارضعت وتضع كل ذات حمل حملها وتري الناس سكري وما هم بسكري ولكن عذاب الله شديد'),
(2598, 22, 3, 'وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللّٰهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَانٍ مَر۪يدٍۙ', 'Ve minen nasi men yucadilu fillahi bi gayri ilmin ve yettebiu kulle şeytanin merid.', 'Ve insanlardan öyle kimseler vardır ki; hiçbir bilgisi olmadığı halde,  Allah hakkında ileri geri konuşurlar ve bütün azgın şeytanların[1] peşinden giderler.', 'ومن الناس من يجدل في الله بغير علم ويتبع كل شيطن مريد'),
(2599, 22, 4, 'كُتِبَ عَلَيْهِ اَنَّهُ مَنْ تَوَلَّاهُ فَاَنَّهُ يُضِلُّهُ وَيَهْد۪يهِ اِلٰى عَذَابِ السَّع۪يرِ', 'Kutibe aleyhi ennehu men tevellahu fe ennehu yudılluhu ve yehdihi ila azabis sair.', 'Onun[1] hakkında yazıldı: ona uyan kesinlikle bilmelidir ki,  şeytan onu saptırır. Ve onu Sair\'in[2] azabına iletir.', 'كتب عليه انه من تولاه فانه يضله ويهديه الي عذاب السعير'),
(2600, 22, 5, 'يَٓا اَيُّهَا النَّاسُ اِنْ كُنْتُمْ ف۪ي رَيْبٍ مِنَ الْبَعْثِ فَاِنَّا خَلَقْنَاكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِنْ مُضْغَةٍ مُخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِنُبَيِّنَ لَكُمْۜ وَنُقِرُّ فِي الْاَرْحَامِ مَا نَشَٓاءُ اِلٰٓى اَجَلٍ مُسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلاً ثُمَّ لِتَبْلُغُٓوا اَشُدَّكُمْۚ وَمِنْكُمْ مَنْ يُتَوَفّٰى وَمِنْكُمْ مَنْ يُرَدُّ اِلٰٓى اَرْذَلِ الْعُمُرِ لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ شَيْـٔاًۜ وَتَرَى الْاَرْضَ هَامِدَةً فَاِذَٓا اَنْزَلْنَا عَلَيْهَا الْمَٓاءَ اهْتَزَّتْ وَرَبَتْ وَاَنْبَتَتْ مِنْ كُلِّ زَوْجٍ بَه۪يجٍ', 'Ya eyyuhen nasu in kuntum fi raybin minel ba\'si fe inna halaknakum min turabin summe min nutfetin summe min alakatin summe min mudgatin muhallekatin ve gayri muhallekatin li nubeyyine lekum, ve nukırru fil erhami ma neşau ila ecelin musemmen summe nuhricukum tıflen summe li teblugu eşuddekum ve minkum men yuteveffa ve minkum men yuraddu ila erzelil umuri li keyla ya\'leme min ba\'di ilmin şey\'a, ve terel arda hamideten fe iza enzelna aleyhel maehtezzet ve rabet ve enbetet min kulli zevcin behic.', 'Ey insanlar! Eğer öldükten sonra yeniden dirilmekten kuşkunuz varsa; bilin ki Biz,  sizi topraktan,  sonra nutfeden[1],  sonra bir alakadan[2],  sonra yapısı belli belirsiz mudğadan[3] yarattık. Ne olduğunuzu bilin diye size açıklıyoruz. Ve Biz,  dilediğimizi belli bir süreye kadar rahimlerde tutarız. Sonra sizi bir bebek olarak çıkarırız. Sonra kiminiz ergenlik çağına ulaşır. Ve sizden bir kısmınız vefat ettirilir. Kiminiz de ömrünün en kötü dönemine erişir; bir şey bilmez yaşlı bir bunak haline gelir. Yeryüzünü kurumuş ölmüş görürsün,  ama üzerine su indirdiğimiz zaman yeniden hareketlenir,  kabarır ve her bitkiden göz alıcı çiftler bitirir.', 'يايها الناس ان كنتم في ريب من البعث فانا خلقنكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم ونقر في الارحام ما نشا الي اجل مسمي ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفي ومنكم من يرد الي ارذل العمر لكيلا يعلم من بعد علم شيا وتري الارض هامدة فاذا انزلنا عليها الما اهتزت وربت وانبتت من كل زوج بهيج'),
(2601, 22, 6, 'ذٰلِكَ بِاَنَّ اللّٰهَ هُوَ الْحَقُّ وَاَنَّهُ يُحْـيِ الْمَوْتٰى وَاَنَّهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌۙ', 'Zalike bi ennallahe huvel hakku ve ennehu yuhyil mevta ve ennehu ala kulli şey\'in kadir.', 'İşte Hakk olan Allah budur. O,  ölüleri diriltir. Ve O,  Her Şeye Gücü Yeten\'dir.', 'ذلك بان الله هو الحق وانه يحي الموتي وانه علي كل شي قدير'),
(2602, 22, 7, 'وَاَنَّ السَّاعَةَ اٰتِيَةٌ لَا رَيْبَ ف۪يهَاۙ وَاَنَّ اللّٰهَ يَبْعَثُ مَنْ فِي الْقُبُورِ', 'Ve ennes saate atiyetun la raybe fiha ve ennallahe yeb\'asu men fil kubur.', 'Kuşkusuz o Sa\'at[1] gelecektir. Onun geleceği kesindir. Ve Allah,  kabirlerde olanları[2] diriltecektir.', 'وان الساعة اتية لا ريب فيها وان الله يبعث من في القبور'),
(2603, 22, 8, 'وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللّٰهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُن۪يرٍۙ', 'Ve minen nasi men yucadilu fillahi bi gayri ilmin ve la huden ve la kitabin munir.', 'İnsanlardan bazıları,  bir bilgiye,  bir yol göstericiye ve aydınlatıcı bir kitaba dayanmaksızın Allah hakkında tartışıyorlar.', 'ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير'),
(2604, 22, 9, 'ثَانِيَ عِطْفِه۪ لِيُضِلَّ عَنْ سَب۪يلِ اللّٰهِۜ لَهُ فِي الدُّنْيَا خِزْيٌ وَنُذ۪يقُهُ يَوْمَ الْقِيٰمَةِ عَذَابَ الْحَر۪يقِ', 'Saniye ıtfihi li yudılle an sebilillah, lehu fid dunya hızyun ve nuzikuhu yevmel kıyameti azabel harik.', 'Allah\'ın yolundan saptırmak için kıvırıp durur. Onun için dünyada rezillik vardır. Ve ona Kıyamet Günü yakıcı ateşin azabını tattıracağız.', 'ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيمة عذاب الحريق'),
(2605, 22, 10, 'ذٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَاَنَّ اللّٰهَ لَيْسَ بِظَلَّامٍ لِلْعَب۪يدِ۟', 'Zalike bima kaddemet yedake ve ennallahe leyse bi zallamin lil abid.', 'İşte bu kendi tercihinle yaptığın şeylerden dolayıdır. Kuşkusuz Allah,  kullarına haksızlık edici değildir.', 'ذلك بما قدمت يداك وان الله ليس بظلم للعبيد'),
(2606, 22, 11, 'وَمِنَ النَّاسِ مَنْ يَعْبُدُ اللّٰهَ عَلٰى حَرْفٍۚ فَاِنْ اَصَابَهُ خَيْرٌۨ اطْمَاَنَّ بِه۪ۚ وَاِنْ اَصَابَتْهُ فِتْنَةٌۨ انْقَلَبَ عَلٰى وَجْهِه۪۠ خَسِرَ الدُّنْيَا وَالْاٰخِرَةَۜ ذٰلِكَ هُوَ الْخُسْرَانُ الْمُب۪ينُ', 'Ve minen nasi men ya\'budullahe ala harf, fe in asabehu hayrunıtmeenne bih, ve in asabethu fitnetuninkalebe ala vechihi, hasired dunya vel ahıreh, zalike huvel husranul mubin.', 'İnsanlardan bazıları da iş olsun diye Allah\'a kulluk eder. Onun yararına bir şey olursa onunla mutlu olur,  eğer bir fitneyle[1] karşı karşıya kalırsa hemen yönünü değiştirir. O dünyada da ahirette de kaybedendir. İşte o apaçık bir kayıptır.', 'ومن الناس من يعبد الله علي حرف فان اصابه خير اطمان به وان اصابته فتنة انقلب علي وجهه خسر الدنيا والاخرة ذلك هو الخسران المبين'),
(2607, 22, 12, 'يَدْعُوا مِنْ دُونِ اللّٰهِ مَا لَا يَضُرُّهُ وَمَا لَا يَنْفَعُهُۜ ذٰلِكَ هُوَ الضَّلَالُ الْبَع۪يدُ', 'Yed\'u min dunillahi ma la yedurruhu ve ma la yenfeuh, zalike huved dalalul baid.', 'Allah\'ın yanı sıra kendilerine zarar da fayda da veremeyecek olan şeylere dua ediyorlar. İşte bu derin bir sapkınlıktır.', 'يدعوا من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلل البعيد'),
(2608, 22, 13, 'يَدْعُوا لَمَنْ ضَرُّهُٓ اَقْرَبُ مِنْ نَفْعِه۪ۜ لَبِئْسَ الْمَوْلٰى وَلَبِئْسَ الْعَش۪يرُ', 'Yed\'u le men darruhu akrabu min nef\'ıh, le bi\'sel mevla ve le bi\'sel aşir.', 'Gerçekten de zararı yararından daha yakın olana dua ediyorlar. O ne kötü mevla[1] ne kötü yoldaştır!', 'يدعوا لمن ضره اقرب من نفعه لبيس المولي ولبيس العشير'),
(2609, 22, 14, 'اِنَّ اللّٰهَ يُدْخِلُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ اِنَّ اللّٰهَ يَفْعَلُ مَا يُر۪يدُ', 'İnnallahe yudhılullezine amenu ve amilus salihati cennatin tecri min tahtihel enhar, innallahe yef\'alu ma yurid.', 'Allah,  iman eden ve salihatı[1] yapanları altından ırmaklar akan Cennetlere koyacak. Kuşkusuz Allah,  Dilediği Şeyi Yapar.', 'ان الله يدخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر ان الله يفعل ما يريد'),
(2610, 22, 15, 'مَنْ كَانَ يَظُنُّ اَنْ لَنْ يَنْصُرَهُ اللّٰهُ فِي الدُّنْيَا وَالْاٰخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ اِلَى السَّمَٓاءِ ثُمَّ لْيَقْطَعْ فَلْيَنْظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُ مَا يَغ۪يظُ', 'Men kane yezunnu en len yensurehullahu fid dunya vel ahıreti felyemdud bi sebebin iles semai summel yakta\' felyenzur hel yuzhibennekeyduhu ma yagiz.', 'Kim Allah\'ın,  ona dünyada ve ahirette kesinlikle yardım etmeyeceğini zannediyorsa,  o zaman semaya[1] bir araç uzatsın da sonra onu[2] kessin de baksın bakalım bu planı kendisini kızdıran şeyi giderecek mi?', 'من كان يظن ان لن ينصره الله في الدنيا والاخرة فليمدد بسبب الي السما ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ'),
(2611, 22, 16, 'وَكَذٰلِكَ اَنْزَلْنَاهُ اٰيَاتٍ بَيِّنَاتٍۙ وَاَنَّ اللّٰهَ يَهْد۪ي مَنْ يُر۪يدُ', 'Ve kezalike enzelnahu ayatin beyyinatin ve ennallahe yehdi men yurid.', 'Onu apaçık ayetler olarak indirdik. Allah,  hak edene[1] doğru yolu gösterir.', 'وكذلك انزلنه ايت بينت وان الله يهدي من يريد'),
(2612, 22, 17, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَالَّذ۪ينَ هَادُوا وَالصَّابِـ۪ٔينَ وَالنَّصَارٰى وَالْمَجُوسَ وَالَّذ۪ينَ اَشْرَكُواۗ اِنَّ اللّٰهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيٰمَةِۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌ', 'İnnellezine amenu vellezine hadu ves sabiine ven nasara vel mecuse vellezine eşreku innallahe yafsılu beynehum yevmel kıyameh, innallahe ala kulli şey\'in şehid.', 'Allah; İnananlar,  Yahudiler,  Sabiiler,  Hıristiyanlar,  Mecusiler ve Müşrik olanların Kıyamet Günü aralarını ayıracaktır.[1] Allah,  her şeye tanıktır.', 'ان الذين امنوا والذين هادوا والصبين والنصري والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيمة ان الله علي كل شي شهيد'),
(2613, 22, 18, 'اَلَمْ تَرَ اَنَّ اللّٰهَ يَسْجُدُ لَهُ مَنْ فِي السَّمٰوَاتِ وَمَنْ فِي الْاَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَٓابُّ وَكَث۪يرٌ مِنَ النَّاسِۜ وَكَث۪يرٌ حَقَّ عَلَيْهِ الْعَذَابُۜ وَمَنْ يُهِنِ اللّٰهُ فَمَا لَهُ مِنْ مُكْرِمٍۜ اِنَّ اللّٰهَ يَفْعَلُ مَا يَشَٓاءُ', 'E lem tera ennallahe yescudu lehu men fis semavati ve men fil ardı veş şemsu vel kameru ven nucumu vel cibalu veş şeceru ved devabbu ve kesirun minen nas, ve kesirun hakka aleyhil azab, ve men yuhinillahu fe ma lehu min mukrim, innallahe yef\'alu ma yeşa\'.', 'Göklerde ve yerde ne varsa; Güneş\'in,  Ay\'ın ve yıldızların,  dağların,  ağaçların,  hayvanların ve insanların birçoğunun Allah\'a secde[1] ettiklerini görmüyor musun[2]? Birçoğunun da[3] üzerine azap hak oldu. Ve Allah,  kimi küçük düşürürse artık onun için bir yüceltici yoktur. Kuşkusuz Allah,  dilediğini yapar.', 'الم تر ان الله يسجد له من في السموت ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشا'),
(2614, 22, 19, 'هٰذَانِ خَصْمَانِ اخْتَصَمُوا ف۪ي رَبِّهِمْۘ فَالَّذ۪ينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِنْ نَارٍۜ يُصَبُّ مِنْ فَوْقِ رُؤُ۫سِهِمُ الْحَم۪يمُۚ', 'Hazani hasmanihtesamu fi rabbihim fellezine keferu kuttıat lehum siyabun min nar, yusabbu min fevkı ruusihumul hamim.', 'Bu iki karşıt taraf[1],  Rabb\'leri hakkında mücadele eden,  birbirlerine iki düşmandır. Bunlardan Kafirler[2] için ateşten biçilmiş elbiseler vardır. Onların başlarının üstünden kaynar sular dökülecek!', 'هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق روسهم الحميم'),
(2615, 22, 20, 'يُصْهَرُ بِه۪ مَا ف۪ي بُطُونِهِمْ وَالْجُلُودُۜ', 'Yusheru bihi ma fi butunihim vel culud.', 'Bununla iç organları ve derileri eritilecek.', 'يصهر به ما في بطونهم والجلود'),
(2616, 22, 21, 'وَلَهُمْ مَقَامِعُ مِنْ حَد۪يدٍ', 'Ve lehum makamıu min hadid.', 'Ve onlar için demirden topuzlar vardır.', 'ولهم مقمع من حديد'),
(2617, 22, 22, 'كُلَّمَٓا اَرَادُٓوا اَنْ يَخْرُجُوا مِنْهَا مِنْ غَمٍّ اُع۪يدُوا ف۪يهَا وَذُوقُوا عَذَابَ الْحَر۪يقِ۟', 'Kullema eradu en yahrucu minha min gammin uidu fiha ve zuku azabel harik.', 'Azaptan kurtulmak için ne zaman oradan çıkmak isteyecek olurlarsa,  yakıcı azabı tatmaları için oraya geri döndürülürler.', 'كلما ارادوا ان يخرجوا منها من غم اعيدوا فيها وذوقوا عذاب الحريق'),
(2618, 22, 23, 'اِنَّ اللّٰهَ يُدْخِلُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ يُحَلَّوْنَ ف۪يهَا مِنْ اَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤً۬اۜ وَلِبَاسُهُمْ ف۪يهَا حَر۪يرٌ', 'İnnallahe yudhılullezine amenu ve amilus salihati cennatin tecri min tahtihel enharu yuhallevne fiha min esavira min zehebin ve lu\'lua, ve libasuhum fiha harir.', 'Allah,  iman eden ve salihatı yapanları,  içinden ırmaklar akan Cennetlere koyacak. Onlar,  orada altından bilezikler ve inciler ile süslenirler. Elbiseleri ipektendir.', 'ان الله يدخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر يحلون فيها من اساور من ذهب ولولوا ولباسهم فيها حرير'),
(2619, 22, 24, 'وَهُدُٓوا اِلَى الطَّيِّبِ مِنَ الْقَوْلِۗ وَهُدُٓوا اِلٰى صِرَاطِ الْحَم۪يدِ', 'Ve hudu ilet tayyibi minel kavli ve hudu ila sıratıl hamid.', 'Sözün temiz-hoş olanına yönlendirildiler. Hamid\'in[1] yoluna yönlendirildiler.', 'وهدوا الي الطيب من القول وهدوا الي صرط الحميد');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2620, 22, 25, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَيَصُدُّونَ عَنْ سَب۪يلِ اللّٰهِ وَالْمَسْجِدِ الْحَرَامِ الَّذ۪ي جَعَلْنَاهُ لِلنَّاسِ سَوَٓاءًۨ الْعَاكِفُ ف۪يهِ وَالْبَادِۜ وَمَنْ يُرِدْ ف۪يهِ بِـاِلْحَادٍ بِظُـلْمٍ نُذِقْهُ مِنْ عَذَابٍ اَل۪يمٍ۟', 'İnnellezine keferu ve yasuddune an sebilillahi vel mescidil haramillezi cealnahu lin nasi sevaenil akıfu fihi vel bad, ve men yurid fihi bi ilhadin bi zulmin nuzıkhu min azabin elim.', 'Kafir olanlar ve Allah\'ın yolundan ve Mescid-i Haram\'dan engelleyenler -bilsinler ki- onu[1],  orada yerleşik olan ve dışarıdan gelen bütün insanların eşitçe adanmaları için yaptık. Kim orada haksızlıkla sapkınlık yaparsa,  ona acı azaptan tattıracağız.', 'ان الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلنه للناس سوا العكف فيه والباد ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم'),
(2621, 22, 26, 'وَاِذْ بَوَّأْنَا لِاِبْرٰه۪يمَ مَكَانَ الْبَيْتِ اَنْ لَا تُشْرِكْ ب۪ي شَيْـٔاً وَطَهِّرْ بَيْتِيَ لِلطَّٓائِف۪ينَ وَالْقَٓائِم۪ينَ وَالرُّكَّعِ السُّجُودِ', 'Ve iz bevve\'na li ibrahime mekanel beyti en la tuşrik bi şey\'en ve tahhir beytiye lit taifine vel kaimine ver rukkais sucud.', 'Bir zamanlar İbrahim\'e evin[1] yerini göstererek; \"Bana hiçbir şeyi ortak koşma. Evimi tavaf edenler,  kaim olanlar[2],  ruku[3] edenler,  secde edenler[4] için arındır.\"[5] demiştik.', 'واذ بوانا لابرهيم مكان البيت ان لا تشرك بي شيا وطهر بيتي للطايفين والقايمين والركع السجود'),
(2622, 22, 27, 'وَاَذِّنْ فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ رِجَالاً وَعَلٰى كُلِّ ضَامِرٍ يَأْت۪ينَ مِنْ كُلِّ فَجٍّ عَم۪يقٍۙ', 'Ve ezzin fin nasi bil hacci ye\'tuke ricalen ve ala kulli damirin ye\'tine min kulli feccin amik.', 'İnsanları Hacca çağır. Gerek yaya gerek her türlü binek üzerinde,  uzak yakın her yerden sana gelsinler.', 'واذن في الناس بالحج ياتوك رجالا وعلي كل ضامر ياتين من كل فج عميق'),
(2623, 22, 28, 'لِيَشْهَدُوا مَنَافِـعَ لَهُمْ وَيَذْكُرُوا اسْمَ اللّٰهِ ف۪ٓي اَيَّامٍ مَعْلُومَاتٍ عَلٰى مَا رَزَقَهُمْ مِنْ بَه۪يمَةِ الْاَنْعَامِۚ فَكُلُوا مِنْهَا وَاَطْعِمُوا الْـبَٓائِسَ الْفَق۪يرَۘ', 'Li yeşhedu menafia lehum ve yezkurusmallahi fi eyyamin ma\'lumatin ala ma rezakahum min behimetil en\'am, fe kulu minha ve at\'ımul baisel fakir.', 'Bunun kendilerine sağlayacağı yararlara tanık olsunlar. Ve kendilerine rızık olarak verilen hayvanlar üzerine belli günlerde[1] Allah\'ın adını[2] ansınlar. Böylece onlardan yiyin,  muhtaç ve yoksul olanları doyurun.', 'ليشهدوا منفع لهم ويذكروا اسم الله في ايام معلومت علي ما رزقهم من بهيمة الانعم فكلوا منها واطعموا البايس الفقير'),
(2624, 22, 29, 'ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَت۪يقِ', 'Summel yakdu tefesehum vel yufu nuzurahum vel yettavvefu bil beytil atik.', 'Sonra kirlerini gidersinler.[1] Adaklarını yerine getirsinler. Ve Beyt-i Atik\'i[2] tavaf etsinler.', 'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق'),
(2625, 22, 30, 'ذٰلِكَۗ وَمَنْ يُعَظِّمْ حُرُمَاتِ اللّٰهِ فَهُوَ خَيْرٌ لَهُ عِنْدَ رَبِّه۪ۜ وَاُحِلَّتْ لَكُمُ الْاَنْعَامُ اِلَّا مَا يُتْلٰى عَلَيْكُمْ فَاجْتَنِبُوا الرِّجْسَ مِنَ الْاَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِۙ', 'Zalike ve men yuazzım hurumatillahi fe huve hayrun lehu inde rabbih, ve uhıllet lekumul en\'amu illa ma yutla aleykum fectenibur ricse minel evsani vectenibu kavlez zur.', 'İşte böyle. Kim Rabb\'inin yasaklarına uymada gerekli özeni gösterirse,  bu onun için daha hayırlıdır. Size okunanlar[1] hariç,  diğer hayvanlar helal kılındı. Artık putların pisliğinden[2] kaçının. Yalan sözden kaçının.', 'ذلك ومن يعظم حرمت الله فهو خير له عند ربه واحلت لكم الانعم الا ما يتلي عليكم فاجتنبوا الرجس من الاوثن واجتنبوا قول الزور'),
(2626, 22, 31, 'حُنَفَٓاءَ لِلّٰهِ غَيْرَ مُشْرِك۪ينَ بِه۪ۜ وَمَنْ يُشْرِكْ بِاللّٰهِ فَكَاَنَّمَا خَرَّ مِنَ السَّمَٓاءِ فَتَخْطَفُهُ الطَّيْرُ اَوْ تَهْو۪ي بِهِ الرّ۪يحُ ف۪ي مَكَانٍ سَح۪يقٍ', 'Hunefae lillahi gayre muşrikine bih, ve men yuşrik billahi fe ke ennema harre mines semai fe tahtafuhut tayru ev tehvi bihir rihu fi mekanin sahik.', 'Hanifler[1],  onunla[2] Allah\'a şirk koşmayanlardır. Allah\'a şirk koşan kimse,  sanki gökten düşen ve kuşun kaptığı[3] veya rüzgarın uzak yerlere sürüklediği kimse gibidir.', 'حنفا لله غير مشركين به ومن يشرك بالله فكانما خر من السما فتخطفه الطير او تهوي به الريح في مكان سحيق'),
(2627, 22, 32, 'ذٰلِكَۗ وَمَنْ يُعَظِّمْ شَعَٓائِرَ اللّٰهِ فَاِنَّهَا مِنْ تَقْوَى الْقُلُوبِ', 'Zalike ve men yuazzım şeairallahi fe inneha min takval kulub.', 'İşte böyle! Kim Allah\'ın şiarlarına[1] saygı gösterirse,  kuşkusuz bu saygı kalplerin takvasındandır.', 'ذلك ومن يعظم شعير الله فانها من تقوي القلوب'),
(2628, 22, 33, 'لَكُمْ ف۪يهَا مَنَافِـعُ اِلٰٓى اَجَلٍ مُسَمًّى ثُمَّ مَحِلُّـهَٓا اِلَى الْبَيْتِ الْعَت۪يقِ۟', 'Lekum fiha menafiu ila ecelin musemmen summe mahılluha ilel beytil atik.', 'Sizin için onlarda belli bir süreye kadar faydalar vardır. Sonra bunların mahalli Beyt-i Atik\'edir.[1]', 'لكم فيها منفع الي اجل مسمي ثم محلها الي البيت العتيق'),
(2629, 22, 34, 'وَلِكُلِّ اُمَّةٍ جَعَلْنَا مَنْسَكاً لِيَذْكُرُوا اسْمَ اللّٰهِ عَلٰى مَا رَزَقَهُمْ مِنْ بَه۪يمَةِ الْاَنْعَامِۜ فَاِلٰهُكُمْ اِلٰهٌ وَاحِدٌ فَلَـهُٓ اَسْلِمُواۜ وَبَشِّرِ الْمُخْبِت۪ينَۙ', 'Ve li kulli ummetin cealna menseken li yezkurusmallahi ala ma razakahum min behimetil en\'am, fe ilahukum ilahun vahıdun fe lehu eslimu ve beşşiril muhbitin.', 'Rızık olarak verilen hayvanların üzerine Allah\'ın adını anmaları için bütün ümmetlere mensek[1] tayin ettik. Sizin ilahınız bir tek ilahtır. Artık yalnızca ona teslim olun. Samimi insanları haberdar et.', 'ولكل امة جعلنا منسكا ليذكروا اسم الله علي ما رزقهم من بهيمة الانعم فالهكم اله وحد فله اسلموا وبشر المخبتين'),
(2630, 22, 35, 'اَلَّذ۪ينَ اِذَا ذُكِرَ اللّٰهُ وَجِلَتْ قُلُوبُهُمْ وَالصَّابِر۪ينَ عَلٰى مَٓا اَصَابَهُمْ وَالْمُق۪يمِي الصَّلٰوةِۙ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ', 'Ellezine iza zukirallahu vecilet kulubuhum vas sabirine ala ma esabehum vel mukimis salati ve mimma razaknahum yunfikun.', 'Onlar ki[1] Allah anıldığı zaman kalpleri ürperir,  başlarına gelene sabrederler[2],  salatı ikame ederler[3],  kendilerini rızıklandırdığımız şeylerden infak[4] ederler.', 'الذين اذا ذكر الله وجلت قلوبهم والصبرين علي ما اصابهم والمقيمي الصلوة ومما رزقنهم ينفقون'),
(2631, 22, 36, 'وَالْبُدْنَ جَعَلْنَاهَا لَكُمْ مِنْ شَعَٓائِرِ اللّٰهِ لَكُمْ ف۪يهَا خَيْرٌۗ فَاذْكُرُوا اسْمَ اللّٰهِ عَلَيْهَا صَوَٓافَّۚ فَاِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَاَطْعِمُوا الْقَانِـعَ وَالْمُعْتَرَّۜ  كَذٰلِكَ سَخَّرْنَاهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'Vel budne cealnaha lekum min şeairillahi lekum fiha hayr, fezkurusmallahi aleyha savaff, fe iza vecebet cunubuha fe kulu minha ve at\'ımul kania vel mu\'terr, kezalike sahharnaha lekum leallekum teşkurun.', 'Büyükbaş hayvanları da[1] sizin için Allah\'ın şiarlarından[2] kıldık. Sizin için onlarda hayır vardır. Ayakları bağlı halde keserlerken üzerlerine Allah\'ın adını anın. Yanları üzerine düşünce onları yiyin. İsteyene de istemeyene de yedirin. Böylece onları yararlanmanıza sunduk. Umulur ki şükredersiniz.', 'والبدن جعلنها لكم من شعير الله لكم فيها خير فاذكروا اسم الله عليها صواف فاذا وجبت جنوبها فكلوا منها واطعموا القانع والمعتر كذلك سخرنها لكم لعلكم تشكرون'),
(2632, 22, 37, 'لَنْ يَنَالَ اللّٰهَ لُحُومُهَا وَلَا دِمَٓاؤُ۬هَا وَلٰكِنْ يَنَالُهُ التَّقْوٰى مِنْكُمْۜ  كَذٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا اللّٰهَ عَلٰى مَا هَدٰيكُمْۜ وَبَشِّرِ الْمُحْسِن۪ينَ', 'Len yenalellahe luhumuha ve la dimauha ve lakin yenaluhut takva minkum, kezalike sahharaha lekum li tukebbirullahe ala ma hedakum, ve beşşiril muhsinin.', 'Onların[1] ne etleri ne kanları asla Allah\'a ulaşmaz. Ona ulaşacak olan sizin takvanızdır. Sizi doğru yola ilettiğinden dolayı Allah\'ı yüceltmeniz için onları sizin yararınıza sundu. İyi olan kimseleri müjdele.', 'لن ينال الله لحومها ولا دماوها ولكن يناله التقوي منكم كذلك سخرها لكم لتكبروا الله علي ما هديكم وبشر المحسنين'),
(2633, 22, 38, 'اِنَّ اللّٰهَ يُدَافِـعُ عَنِ الَّذ۪ينَ اٰمَنُواۜ اِنَّ اللّٰهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ۟', 'İnnallahe yudafiu anillezine amenu, innallahe la yuhıbbu kulle havvanin kefur.', 'Allah,  inananları savunur. Allah,  hain nankörleri sevmez.', 'ان الله يدفع عن الذين امنوا ان الله لا يحب كل خوان كفور'),
(2634, 22, 39, 'اُذِنَ لِلَّذ۪ينَ يُقَاتَلُونَ بِاَنَّهُمْ ظُلِمُواۜ وَاِنَّ اللّٰهَ عَلٰى نَصْرِهِمْ لَقَد۪يرٌۙ', 'Uzine lillezine yukatelune bi ennehum zulim, ve innallahe ala nasrihim le kadir.', 'Kendileriyle savaşılan kimselerin,  zulme uğramaları nedeniyle,  savaşmalarına izin verildi. Kuşkusuz Allah,  onlara yardım etmeye kadirdir.', 'اذن للذين يقتلون بانهم ظلموا وان الله علي نصرهم لقدير'),
(2635, 22, 40, 'اَلَّذ۪ينَ اُخْرِجُوا مِنْ دِيَارِهِمْ بِغَيْرِ حَقٍّ اِلَّٓا اَنْ يَقُولُوا رَبُّنَا اللّٰهُۜ وَلَوْلَا دَفْعُ اللّٰهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَهُدِّمَتْ صَوَامِــعُ وَبِيَعٌ وَصَلَوَاتٌ وَمَسَاجِدُ يُذْكَرُ ف۪يهَا اسْمُ اللّٰهِ كَث۪يراًۜ وَلَيَنْصُرَنَّ اللّٰهُ مَنْ يَنْصُرُهُۜ اِنَّ اللّٰهَ لَقَوِيٌّ عَز۪يزٌ', 'Ellezine uhricu min diyarihim bi gayri hakkın illa en yekulu rabbunallah, ve lev la def\'ullahin nase ba\'dahum bi ba\'dın lehuddimet savamıu ve biyaun ve salavatun ve mesacidu yuzkeru fihesmullahi kesira, ve le yansurennallahu men yansuruh, innallahe le kaviyyun aziz.', 'Onlar,  sadece \"Rabb\'imiz Allah\'tır.\" dedikleri için haksız yere yurtlarından çıkarıldılar. Eğer Allah,  insanların bazılarını bazılarıyla savmasaydı,  içinde Allah\'ın isminin çokça anıldığı sevamiu[1],  biyeun[2],  selavat[3],  mescitler mutlaka yıkılırdı. Allah,  kendisine yardım edene[4] mutlaka yardım eder. Kuşkusuz Allah,  Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'الذين اخرجوا من ديرهم بغير حق الا ان يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صومع وبيع وصلوت ومسجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره ان الله لقوي عزيز'),
(2636, 22, 41, 'اَلَّذ۪ينَ اِنْ مَكَّنَّاهُمْ فِي الْاَرْضِ اَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ وَاَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِۜ وَلِلّٰهِ عَاقِبَةُ الْاُمُورِ', 'Ellezine in mekkennahum fil ardı ekamus salate ve atevuz zekate ve emeru bil ma\'rufi ve nehev anil munker, ve lillahi akıbetul umur.', 'Eğer yeryüzünde onları egemen kılarsak,  salatı ikame ederler[1],  zekatı yaparlar[1],  ma\'ruf olanı yapar,  münkerden sakındırırlar.[2] Bütün işlerin sonucu Allah\'a dönecektir.', 'الذين ان مكنهم في الارض اقاموا الصلوة واتوا الزكوة وامروا بالمعروف ونهوا عن المنكر ولله عقبة الامور'),
(2637, 22, 42, 'وَاِنْ يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُۙ', 'Ve in yukezzibuke fe kad kezzebet kablehum kavmu nuhın ve adun ve semud.', 'Eğer seni yalanlıyorlarsa,  bil ki onlardan önce; Nuh,  Âd ve Semud halkları da nebilerini yalanlamışlardı.', 'وان يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود'),
(2638, 22, 43, 'وَقَوْمُ اِبْرٰه۪يمَ وَقَوْمُ لُوطٍۙ', 'Ve kavmu ibrahime ve kavmu lut.', 'İbrahim ve Lut halkları da yalanlamışlardı.', 'وقوم ابرهيم وقوم لوط'),
(2639, 22, 44, 'وَاَصْحَابُ مَدْيَنَۚ وَكُذِّبَ مُوسٰى فَاَمْلَيْتُ لِلْكَافِر۪ينَ ثُمَّ اَخَذْتُهُمْۚ فَكَيْفَ كَانَ نَك۪يرِ', 'Ve ashabu medyen, ve kuzzibe musa fe emleytu lil kafirine summe ehaztuhum, fe keyfe kane nekir.', 'Ve Medyen sahipleri de. Musa da yalanlandı. Fakat Kafirlere süre tanıdım. Sonra da onları yakaladım. Benim inkarım[1] nasılmış gördüler.', 'واصحب مدين وكذب موسي فامليت للكفرين ثم اخذتهم فكيف كان نكير'),
(2640, 22, 45, 'فَكَاَيِّنْ مِنْ قَرْيَةٍ اَهْلَكْنَاهَا وَهِيَ ظَالِمَةٌ فَهِيَ خَاوِيَةٌ عَلٰى عُرُوشِهَا وَبِئْرٍ مُعَطَّـلَةٍ وَقَصْرٍ مَش۪يدٍ', 'Fe ke eyyin min karyetin ehleknaha ve hiye zalimetun fe hiye haviyetun ala uruşiha ve bi\'rin muattalatin ve kasrın meşid.', 'Böylece zulüm yapmalarından dolayı nice kentleri yok ettik. Çatıları çökmüş,  duvarları yıkılmış; sahipsiz kalmış kuyular ve görkemli saraylar vardır.', 'فكاين من قرية اهلكنها وهي ظالمة فهي خاوية علي عروشها وبير معطلة وقصر مشيد'),
(2641, 22, 46, 'اَفَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَٓا اَوْ اٰذَانٌ يَسْمَعُونَ بِهَاۚ فَاِنَّهَا لَا تَعْمَى الْاَبْصَارُ وَلٰكِنْ تَعْمَى الْقُلُوبُ الَّت۪ي فِي الصُّدُورِ', 'E fe lem yesiru fil ardı fe tekune lehum kulubun ya\'kılune biha ev azanunyesmeune biha, fe inneha la ta\'mal ebsaru ve lakin ta\'mal kulubulleti fis sudur.', 'Onlar,  yeryüzünde dolaşmıyorlar mı ki kendilerinin,  kendisi ile akıl edecekleri kalpleri[1] veya kendisi ile işitecek kulakları olsun. Gerçek şu ki,  kör olan gözler değildir,  kör olan göğüslerde olan kalplerdir.', 'افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمي الابصر ولكن تعمي القلوب التي في الصدور'),
(2642, 22, 47, 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ وَلَنْ يُخْلِفَ اللّٰهُ وَعْدَهُۜ وَاِنَّ يَوْماً عِنْدَ رَبِّكَ كَاَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ', 'Ve yesta\'ciluneke bil azabi ve len yuhlifallahu va\'deh, ve inne yevmen inde rabbike ke elfi senetin mimma teuddun.', 'Ve senden azabı çabuklaştırmanı istiyorlar. Oysa Allah,  sözünden asla dönmez. Kuşkusuz Rabb\'ine göre bir gün,  sizin saydıklarınızdan bin yıl gibidir.', 'ويستعجلونك بالعذاب ولن يخلف الله وعده وان يوما عند ربك كالف سنة مما تعدون'),
(2643, 22, 48, 'وَكَاَيِّنْ مِنْ قَرْيَةٍ اَمْلَيْتُ لَهَا وَهِيَ ظَالِمَةٌ ثُمَّ اَخَذْتُهَاۚ وَاِلَيَّ الْمَص۪يرُ۟', 'Ve ke eyyin min karyetin emleytu leha ve hiye zalimetun summe ehaztuha, ve ileyyel masir.', 'Zulmedip duran nice kentler vardı ki onlara süre vermiştim. Sonra onları yakaladım. Ve dönüş Bana\'dır.', 'وكاين من قرية امليت لها وهي ظالمة ثم اخذتها والي المصير'),
(2644, 22, 49, 'قُلْ يَٓا اَيُّهَا النَّاسُ اِنَّـمَٓا اَنَا۬ لَكُمْ نَذ۪يرٌ مُب۪ينٌۚ', 'Kul ya eyyuhen nasu innema ene lekum nezirun mubin.', 'De ki: \"Ey insanlar! Ben sizin için yalnızca apaçık bir uyarıcıyım.\"', 'قل يايها الناس انما انا لكم نذير مبين'),
(2645, 22, 50, 'فَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَر۪يمٌ', 'Fellezine amenu ve amilus salihati lehum magfiretun ve rızkun kerim.', 'İman edip salihatı[1] yapanlar için bağışlanma ve bol rızık vardır.', 'فالذين امنوا وعملوا الصلحت لهم مغفرة ورزق كريم'),
(2646, 22, 51, 'وَالَّذ۪ينَ سَعَوْا ف۪ٓي اٰيَاتِنَا مُعَاجِز۪ينَ اُو۬لٰٓئِكَ اَصْحَابُ الْجَح۪يمِ', 'Vellezine seav fi ayatina muacizine ulaike ashabul cehim.', 'Ayetlerimizi geçersiz bırakma yarışında olanlar,  işte onlar Cehennem ehlidir.', 'والذين سعوا في ايتنا معجزين اوليك اصحب الجحيم'),
(2647, 22, 52, 'وَمَٓا اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ وَلَا نَبِيٍّ اِلَّٓا اِذَا تَمَنّٰٓى اَلْقَى الشَّيْطَانُ ف۪ٓي اُمْنِيَّتِه۪ۚ فَيَنْسَخُ اللّٰهُ مَا يُلْقِي الشَّيْطَانُ ثُمَّ يُحْكِمُ اللّٰهُ اٰيَاتِه۪ۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌۙ', 'Ve ma erselna min kablike min resulin ve la nebiyyin illa iza temenna elkaş şeytanu fi umniyyetih, fe yensehullahu ma yulkış şeytanu summe yuhkimullahu ayatih, vallahu alimun hakim.', 'Senden önce gönderdiğimiz her Resul ve Nebi,  bir şey dilediği[1] zaman,  şeytan[2] onun bu dileğine bir şeyler katmak istedi.[3] Fakat Allah,  şeytanın kattığı şeyleri yok eder. Sonra Allah,  kendi ayetlerini sağlamlaştırır. Ve Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'وما ارسلنا من قبلك من رسول ولا نبي الا اذا تمني القي الشيطن في امنيته فينسخ الله ما يلقي الشيطن ثم يحكم الله ايته والله عليم حكيم'),
(2648, 22, 53, 'لِيَجْعَلَ مَا يُلْقِي الشَّيْطَانُ فِتْنَةً لِلَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ وَالْقَاسِيَةِ قُلُوبُهُمْۜ وَاِنَّ الظَّالِم۪ينَ لَف۪ي شِقَاقٍ بَع۪يدٍۙ', 'Li yec\'ale ma yulkış şeytanu fitneten lillezine fi kulubihim maradun vel kasiyeti kulubuhum, ve innez zalimine le fi şikakın baid.', 'Kalplerinde hastalık olan ve kalpleri kararıp katılaşmış olanlara,  şeytanın kattığı şeyi[1],  sınav vesilesi kıldık. Zalimler derin bir yanılgı içindedirler.', 'ليجعل ما يلقي الشيطن فتنة للذين في قلوبهم مرض والقاسية قلوبهم وان الظلمين لفي شقاق بعيد'),
(2649, 22, 54, 'وَلِيَعْلَمَ الَّذ۪ينَ اُو۫تُوا الْعِلْمَ اَنَّهُ الْحَقُّ مِنْ رَبِّكَ فَيُؤْمِنُوا بِه۪ فَتُخْبِتَ لَهُ قُلُوبُهُمْۜ وَاِنَّ اللّٰهَ لَهَادِ الَّذ۪ينَ اٰمَنُٓوا اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Ve li ya\'lemellezine utul ılme ennehul hakku min rabbike fe yu\'minu bihi fe tuhbite lehu kulubuhum, ve innallahe le hadillezine amenu ila sıratın mustakim.', 'İlim[1] verilen kimselerin[2],  onun[3] Rabb\'inden gelen bir gerçek olduğunu bilmeleri,  ona iman etmeleri ve kalplerinin tatmin olması içindir. Allah,  inananlara dosdoğru yolu gösterendir.', 'وليعلم الذين اوتوا العلم انه الحق من ربك فيومنوا به فتخبت له قلوبهم وان الله لهاد الذين امنوا الي صرط مستقيم'),
(2650, 22, 55, 'وَلَا يَزَالُ الَّذ۪ينَ كَفَرُوا ف۪ي مِرْيَةٍ مِنْهُ حَتّٰى تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً اَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَق۪يمٍ', 'Ve la yezalullezine keferu fi miryetin minhu hatta te\'tiyehumus saatu bagteten ev ye\'tiyehum azabu yevmin akim.', 'Kafirler de Sa\'at[1] ansızın gelinceye veya ardından başka bir gün olmayan günün azabı gelinceye kadar ondan[2] kuşku duymaya devam edeceklerdir.', 'ولا يزال الذين كفروا في مرية منه حتي تاتيهم الساعة بغتة او ياتيهم عذاب يوم عقيم'),
(2651, 22, 56, 'اَلْمُلْكُ يَوْمَئِذٍ لِلّٰهِۜ يَحْكُمُ بَيْنَهُمْۜ فَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ ف۪ي جَنَّاتِ النَّع۪يمِ', 'El mulku yevme izin lillah, yahkumu beynehum, fellezine amenu ve amilus salihati fi cennatin naim.', 'Egemenlik,  İzin Günü[1] tamamen Allah\'a aittir,  insanlar arasında yalnızca O hüküm verir. Artık iman eden ve salihatı yapanlar,  nimet cennetlerindedirler.', 'الملك يوميذ لله يحكم بينهم فالذين امنوا وعملوا الصلحت في جنت النعيم'),
(2652, 22, 57, 'وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَا فَاُو۬لٰٓئِكَ لَهُمْ عَذَابٌ مُه۪ينٌ', 'Vellezine keferu ve kezzebu bi ayatina fe ulaike lehum azabun muhin.', 'Kafir olan[1] ve ayetlerimizi yalanlayan kimseler için alçaltıcı bir azap vardır.', 'والذين كفروا وكذبوا بايتنا فاوليك لهم عذاب مهين'),
(2653, 22, 58, 'وَالَّذ۪ينَ هَاجَرُوا ف۪ي سَب۪يلِ اللّٰهِ ثُمَّ قُتِلُٓوا اَوْ مَاتُوا لَيَرْزُقَنَّهُمُ اللّٰهُ رِزْقاً حَسَناًۜ وَاِنَّ اللّٰهَ لَهُوَ خَيْرُ الرَّازِق۪ينَ', 'Vellezine haceru fi sebilillahi summe kutilu ev matu le yerzukannehumullahu rızkan hasena, ve innallahe le huve hayrur razikin.', 'Allah yolunda hicret edip de sonra öldürülmüş ve ölmüş olanları,  Allah kesinlikle iyi bir rızıkla rızıklandıracaktır. Kuşkusuz Allah,  rızık verenlerin en hayırlısıdır.', 'والذين هاجروا في سبيل الله ثم قتلوا او ماتوا ليرزقنهم الله رزقا حسنا وان الله لهو خير الرزقين'),
(2654, 22, 59, 'لَيُدْخِلَنَّهُمْ مُدْخَلاً يَرْضَوْنَهُۜ وَاِنَّ اللّٰهَ لَعَل۪يمٌ حَل۪يمٌ', 'Le yudhılennehum mudhalen yerdavneh, ve innallahe le alimun halim.', 'Onları kesinlikle hoşnut olacakları bir yere yerleştirecektir. Allah,  Her Şeyi Bilen\'dir,  Çok Şefkatli\'dir.', 'ليدخلنهم مدخلا يرضونه وان الله لعليم حليم'),
(2655, 22, 60, 'ذٰلِكَۚ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِه۪ ثُمَّ بُغِيَ عَلَيْهِ لَيَنْصُرَنَّهُ اللّٰهُۜ اِنَّ اللّٰهَ لَعَفُوٌّ غَفُورٌ', 'Zalik, ve men akabe bi misli ma ukıbe bihi summe bugıye aleyhi le yansurennehullah, innallahe le afuvvun gafur.', 'Bu böyledir! Kim kendisine yapılan haksız bir saldırıya aynı oranda karşılık verirse,  sonra yine saldırıya uğrarsa Allah ona yardım eder. Allah,  Çok Affedici\'dir,  Çok Bağışlayıcı\'dır.', 'ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله ان الله لعفو غفور'),
(2656, 22, 61, 'ذٰلِكَ بِاَنَّ اللّٰهَ يُولِجُ الَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي الَّيْلِ وَاَنَّ اللّٰهَ سَم۪يعٌ بَص۪يرٌ', 'Zalike bi ennallahe yulicul leyle fin nehari ve yulicun nehare fil leyli ve ennallahe semiun basir.', 'Bu böyledir! Allah,  geceyi gündüze,  gündüzü de geceye döndürür. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Gören\'dir.', 'ذلك بان الله يولج اليل في النهار ويولج النهار في اليل وان الله سميع بصير'),
(2657, 22, 62, 'ذٰلِكَ بِاَنَّ اللّٰهَ هُوَ الْحَقُّ وَاَنَّ مَا يَدْعُونَ مِنْ دُونِه۪ هُوَ الْبَاطِلُ وَاَنَّ اللّٰهَ هُوَ الْعَلِيُّ الْكَب۪يرُ', 'Zalike bi ennallahe huvel hakku ve enne ma yed\'une min dunihi huvel batılu ve ennallahe huvel aliyyul kebir.', 'İşte böyledir! Allah Hakk\'ın ta kendisidir. O\'ndan başka yöneldikleriniz ise Batıl\'dır. Allah,  Çok Yüce\'dir,  Çok Büyük\'tür.', 'ذلك بان الله هو الحق وان ما يدعون من دونه هو البطل وان الله هو العلي الكبير'),
(2658, 22, 63, 'اَلَمْ تَرَ اَنَّ اللّٰهَ اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءًۘ فَتُصْبِـحُ الْاَرْضُ مُخْضَرَّةًۜ اِنَّ اللّٰهَ لَط۪يفٌ خَب۪يرٌۚ', 'E lem tere ennallahe enzele mines semai maen fe tusbihul ardu muhdarreh, innallahe latifun habir.', 'Allah\'ın gökten indirdiği su ile yeryüzünü nasıl yeşerttiğini görmüyor musun? Allah,  Bütün Ayrıntıları Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'الم تر ان الله انزل من السما ما فتصبح الارض مخضرة ان الله لطيف خبير'),
(2659, 22, 64, 'لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَاِنَّ اللّٰهَ لَهُوَ الْغَنِيُّ الْحَم۪يدُ۟', 'Lehu ma fis semavati ve ma fil ard, ve innallahe le huvel ganiyyul hamid.', 'Göklerde ve yeryüzünde olan her şey O\'nundur. Kuşkusuz Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'له ما في السموت وما في الارض وان الله لهو الغني الحميد'),
(2660, 22, 65, 'اَلَمْ تَرَ اَنَّ اللّٰهَ سَخَّرَ لَكُمْ مَا فِي الْاَرْضِ وَالْفُلْكَ تَجْر۪ي فِي الْبَحْرِ بِاَمْرِه۪ۜ وَيُمْسِكُ السَّمَٓاءَ اَنْ تَقَعَ عَلَى الْاَرْضِ اِلَّا بِاِذْنِه۪ۜ اِنَّ اللّٰهَ بِالنَّاسِ لَرَؤُ۫فٌ رَح۪يمٌ', 'E lem tere ennallahe sahhara lekum ma fil ardı vel fulke tecri fil bahri bi emrih, ve yumsikus semae en tekaa alel ardı illa bi iznih, innallahe bin nasi le raufun rahim.', 'Allah\'ın,  yeryüzünde olanları emrinize amade kıldığını görmedin mi? Ve gemiler denizde O\'nun emri ile akıp gider. Yeryüzüne düşmesin diye göğü iradesiyle[1] O tutuyor. Kuşkusuz Allah,  insanlara Çok Şefkatli\'dir. Rahmeti Kesintisiz\'dir.', 'الم تر ان الله سخر لكم ما في الارض والفلك تجري في البحر بامره ويمسك السما ان تقع علي الارض الا باذنه ان الله بالناس لروف رحيم'),
(2661, 22, 66, 'وَهُوَ الَّـذ۪ٓي اَحْيَاكُمْۘ ثُمَّ يُم۪يتُكُمْ ثُمَّ يُحْي۪يكُمْۜ اِنَّ الْاِنْسَانَ لَكَفُورٌ', 'Ve huvellezi ahyakum summe yumitukum summe yuhyikum, innel insane le kefur.', 'Ve size hayat veren,  sonra sizi öldürecek olan,  sonra da sizi diriltecek olan O\'dur. İnsan[1] gerçekten çok nankördür.', 'وهو الذي احياكم ثم يميتكم ثم يحييكم ان الانسن لكفور'),
(2662, 22, 67, 'لِكُلِّ اُمَّةٍ جَعَلْنَا مَنْسَكاً هُمْ نَاسِكُوهُ فَلَا يُنَازِعُنَّكَ فِي الْاَمْرِ وَادْعُ اِلٰى رَبِّكَۜ اِنَّكَ لَعَلٰى هُدًى مُسْتَق۪يمٍ', 'Li kulli ummetin cealna menseken hum nasikuhu fe la yunaziunneke fil emri ved\'u ila rabbik, inneke le ala huden mustekim.', 'Her ümmet[1] için bir mensek[2] belirledik. Herkes kendi mensekini[2] sürdürür. O halde bu işte seninle çekişmesinler. Sen,  Rabb\'ine çağır. Kuşkusuz ki sen dosdoğru bir yol üzerindesin.', 'لكل امة جعلنا منسكا هم ناسكوه فلا ينزعنك في الامر وادع الي ربك انك لعلي هدي مستقيم'),
(2663, 22, 68, 'وَاِنْ جَادَلُوكَ فَقُلِ اللّٰهُ اَعْلَمُ بِمَا تَعْمَلُونَ', 'Ve in cadeluke fe kulillahu a\'lemu bima ta\'melun.', 'Eğer seninle tartışırlarsa,  o zaman: \"Allah yapmakta olduğunuz şeyleri en iyi bilendir.\" de.', 'وان جدلوك فقل الله اعلم بما تعملون'),
(2664, 22, 69, 'اَللّٰهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كُنْتُمْ ف۪يهِ تَخْتَلِفُونَ', 'Allahu yahkumu beynekum yevmel kıyameti fima kuntum fihi tahtelifun.', 'Allah,  Kıyamet Günü üzerinde görüş ayrılığına düştüğünüz konularda aranızda hüküm verecektir.', 'الله يحكم بينكم يوم القيمة فيما كنتم فيه تختلفون'),
(2665, 22, 70, 'اَلَمْ تَعْلَمْ اَنَّ اللّٰهَ يَعْلَمُ مَا فِي السَّمَٓاءِ وَالْاَرْضِۜ اِنَّ ذٰلِكَ ف۪ي كِتَابٍۜ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَس۪يرٌ', 'E lem ta\'lem ennallahe ya\'lemu ma fis semai vel ard, inne zalike fi kitab, inne zalike alallahi yesir.', 'Allah\'ın gökte ve yerde olan şeyleri kesinlikle bildiğini bilmez misin? Bu bir Kitap\'tadır[1]. Bu Allah\'a kolaydır.', 'الم تعلم ان الله يعلم ما في السما والارض ان ذلك في كتب ان ذلك علي الله يسير'),
(2666, 22, 71, 'وَيَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَمْ يُنَزِّلْ بِه۪ سُلْطَاناً وَمَا لَيْسَ لَهُمْ بِه۪ عِلْمٌۜ وَمَا لِلظَّالِم۪ينَ مِنْ نَص۪يرٍ', 'Ve ya\'budune min dunillahi ma lem yunezzil bihi sultanen ve ma leyse lehum bihi ılm, ve ma liz zalimine min nasir.', 'Onlar; Allah\'ın yanı sıra O\'nun kendileri hakkında bir sultan[1] indirmediği ve hakkında bilgi sahibi olmadıkları şeylere kulluk[2] ediyorlar. Zalimler için hiçbir yardım edici yoktur.', 'ويعبدون من دون الله ما لم ينزل به سلطنا وما ليس لهم به علم وما للظلمين من نصير'),
(2667, 22, 72, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍ تَعْرِفُ ف۪ي وُجُوهِ الَّذ۪ينَ كَفَرُوا الْمُنْكَرَۜ يَكَادُونَ يَسْطُونَ بِالَّذ۪ينَ يَتْلُونَ عَلَيْهِمْ اٰيَاتِنَاۜ قُلْ اَفَاُنَبِّئُكُمْ بِشَرٍّ مِنْ ذٰلِكُمْۜ اَلنَّارُۜ وَعَدَهَا اللّٰهُ الَّذ۪ينَ كَفَرُواۜ وَبِئْسَ الْمَص۪يرُ۟', 'Ve iza tutla aleyhim ayatuna beyyinatin ta\'rifu fi vucuhillezine keferul munker, yekadune yestune billezine yetlune aleyhim ayatina, kul e fe unebbiukum bi şerrin min zalikum, en nar, vaadehallahullezine keferu, ve bi\'sel masir.', 'Onlara apaçık ayetlerimiz okunduğu zaman,  o Kafirlerin yüzlerindeki hoşnutsuzluğu görürsün. Nerede ise kendilerine ayetlerimizi okuyanlara saldıracaklar. De ki: \"Size bundan daha kötüsünü haber vereyim mi? Ateş! Allah\'ın Kafirlere sözüdür. O,  ne kötü bir varış yeridir.\"', 'واذا تتلي عليهم ايتنا بينت تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم ايتنا قل افانبيكم بشر من ذلكم النار وعدها الله الذين كفروا وبيس المصير'),
(2668, 22, 73, 'يَٓا اَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُۜ اِنَّ الَّذ۪ينَ تَدْعُونَ مِنْ دُونِ اللّٰهِ لَنْ يَخْلُقُوا ذُبَاباً وَلَوِ اجْتَمَعُوا لَهُۜ وَاِنْ يَسْلُبْهُمُ الذُّبَابُ شَيْـٔاً لَا يَسْتَنْقِذُوهُ مِنْهُۜ ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ', 'Ya eyyuhen nasu duribe meselun festemiu leh, innellezine ted\'une min dunillahi len yahluku zubaben ve levictemeu leh, ve in yeslubhumuz zubabu şey\'en la yestenkızuhu minh, daufat talibu vel matlub.', 'Ey insanlar! Verilen örneği dikkatle dinleyin: Allah\'ın yanı sıra kulluk ettikleriniz bir araya gelseler,  kesinlikle bir sineği bile yaratamazlar. Değil yaratmak,  sinek onlardan bir şey kapsa,  onu bile kurtaramazlar. İsteyen de kendisinden istenen de ne kadar acizdir.', 'يايها الناس ضرب مثل فاستمعوا له ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وان يسلبهم الذباب شيا لا يستنقذوه منه ضعف الطالب والمطلوب'),
(2669, 22, 74, 'مَا قَدَرُوا اللّٰهَ حَقَّ قَدْرِه۪ۜ اِنَّ اللّٰهَ لَقَوِيٌّ عَز۪يزٌ', 'Ma kaderullahe hakka kadrih, innallahe le kaviyyun aziz.', 'Allah\'ı gereği gibi takdir edemediler[1]. Kuşkusuz Allah,  Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'ما قدروا الله حق قدره ان الله لقوي عزيز'),
(2670, 22, 75, 'اَللّٰهُ يَصْطَف۪ي مِنَ الْمَلٰٓئِكَةِ رُسُلاً وَمِنَ النَّاسِۜ اِنَّ اللّٰهَ سَم۪يعٌ بَص۪يرٌۚ', 'Allahu yastafi minel melaiketi rusulen ve minen nas, innallahe semiun basir.', 'Allah; meleklerden de resuller seçer,  insanlardan da. Kuşkusuz,  Allah,  Her Şeyden Haberdar Olan\'dır,  Her Şeyi Gören\'dir.', 'الله يصطفي من المليكة رسلا ومن الناس ان الله سميع بصير'),
(2671, 22, 76, 'يَعْلَمُ مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ', 'Ya\'lemu ma beyne eydihim ve ma halfehum, ve ilallahi turceul umur.', 'Onların geçmişte yaptıklarını da gelecekte yapacaklarını da bilir. Ve işler yalnızca Allah\'a döndürülür.', 'يعلم ما بين ايديهم وما خلفهم والي الله ترجع الامور'),
(2672, 22, 77, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَۚ', 'Ya eyyuhellezine amenurkeu vescudu va\'budu rabbekum vef\'alul hayre leallekum tuflihun.', 'Ey iman edenler! Ruku[1] edin,  secde[2] edin,  Rabb\'inize kulluk edin,  hayır yapın ki kurtuluşa erebilesiniz.', 'يايها الذين امنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون'),
(2673, 22, 78, 'وَجَاهِدُوا فِي اللّٰهِ حَقَّ جِهَادِه۪ۜ هُوَ اجْتَبٰيكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدّ۪ينِ مِنْ حَرَجٍۜ مِلَّةَ اَب۪يكُمْ اِبْرٰه۪يمَۜ هُوَ سَمّٰيكُمُ الْمُسْلِم۪ينَ مِنْ قَبْلُ وَف۪ي هٰذَا لِيَكُونَ الرَّسُولُ شَه۪يداً عَلَيْكُمْ وَتَكُونُوا شُهَدَٓاءَ عَلَى النَّاسِۚ فَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاعْتَصِمُوا بِاللّٰهِۜ هُوَ مَوْلٰيكُمْۚ فَنِعْمَ الْمَوْلٰى وَنِعْمَ النَّص۪يرُ', 'Ve cahidu fillahi hakka cihadih, huvectebakum ve ma ceale aleykum fid dini min harac, millete ebikum ibrahim, huve semmakumul muslimine min kablu ve fi haza li yekuner resulu şehiden aleykum ve tekunu şuhedae alen nas, fe ekimus salate ve atuz zekate va\'tesımu billah, huve mevlakum, fe ni\'mel mevla ve ni\'men nasir.', 'Allah yolunda gerektiği gibi cihad[1] edin. O sizi seçti. Dinde size bir zorluk yüklemedi. Bu atanız İbrahim\'in milleti[2]. O,  daha önce de şimdi de sizi Müslümanlar olarak isimlendirdi. Resul,  size tanık olsun,  siz de diğer insanlara. Öyleyse salatı ikame edin,  zekatı yapın[3] ve Allah\'a sımsıkı bağlanın. O,  sizin mevlanızdır[4]. Ne güzel Mevla ne güzel yardımcıdır.', 'وجهدوا في الله حق جهاده هو اجتبيكم وما جعل عليكم في الدين من حرج ملة ابيكم ابرهيم هو سميكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهدا علي الناس فاقيموا الصلوة واتوا الزكوة واعتصموا بالله هو موليكم فنعم المولي ونعم النصير'),
(2674, 23, 1, 'قَدْ اَفْلَحَ الْمُؤْمِنُونَۙ', 'Kad eflehal mu\'minun.', 'Mü\'minler gerçekten kurtuluşa ermişlerdir.', 'قد افلح المومنون'),
(2675, 23, 2, 'اَلَّذ۪ينَ هُمْ ف۪ي صَلَاتِهِمْ خَاشِعُونَۙ', 'Ellezine hum fi salatihim haşiun.', 'Onlar,  salatlarında[1] huşu[2] içinde olan kimselerdir.', 'الذين هم في صلاتهم خشعون'),
(2676, 23, 3, 'وَالَّذ۪ينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَۙ', 'Vellezine hum anil lagvi mu\'ridun.', 'Onlar boş şeylerden yüz çevirirler.', 'والذين هم عن اللغو معرضون'),
(2677, 23, 4, 'وَالَّذ۪ينَ هُمْ لِلزَّكٰوةِ فَاعِلُونَۙ', 'Vellezine hum liz zekati failun.', 'Ve onlar,  zekat için[1] çalışanlardır.', 'والذين هم للزكوة فعلون'),
(2678, 23, 5, 'وَالَّذ۪ينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَۙ', 'Vellezine hum li furucihim hafizun.', 'Ve onlar,  ırzlarını korurlar.', 'والذين هم لفروجهم حفظون'),
(2679, 23, 6, 'اِلَّا عَلٰٓى اَزْوَاجِهِمْ اَوْ مَا مَلَكَتْ اَيْمَانُهُمْ فَاِنَّهُمْ غَيْرُ مَلُوم۪ينَۚ', 'İlla ala ezvacihim ev ma meleket eymanuhum fe innehum gayru melumin.', 'Eşleri veya yeminle[1] sahip oldukları hariç.[1] Bundan dolayı kınanmazlar.[2]', 'الا علي ازوجهم او ما ملكت ايمنهم فانهم غير ملومين'),
(2680, 23, 7, 'فَمَنِ ابْتَغٰى وَرَٓاءَ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الْعَادُونَۚ', 'Fe menibtega verae zalike fe ulaike humul adun.', 'Kim bunun ötesinde[1] bir şey isterse,  işte onlar haddi aşanlardır.', 'فمن ابتغي ورا ذلك فاوليك هم العادون'),
(2681, 23, 8, 'وَالَّذ۪ينَ هُمْ لِاَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَۙ', 'Vellezine hum li emanatihim ve ahdihim raun.', 'Onlar,  kendilerine verilen emanetler için sözlerine bağlı kalan kimselerdir.', 'والذين هم لامنتهم وعهدهم رعون'),
(2682, 23, 9, 'وَالَّذ۪ينَ هُمْ عَلٰى صَلَوَاتِهِمْ يُحَافِظُونَۢ', 'Vellezine hum ala salavatihim yuhafızun.', 'Onlar,  salatlarını[1] koruyan kimselerdir.', 'والذين هم علي صلوتهم يحافظون'),
(2683, 23, 10, 'اُو۬لٰٓئِكَ هُمُ الْوَارِثُونَۙ', 'Ulaike humul varisun.', 'İşte onlar varis[1] olanlardır.', 'اوليك هم الورثون'),
(2684, 23, 11, 'اَلَّذ۪ينَ يَرِثُونَ الْفِرْدَوْسَۜ هُمْ ف۪يهَا خَالِدُونَ', 'Ellezine yerisunel firdevs, hum fiha halidun.', 'Onlar,  Firdevse[1] varis olacaklar ve orada sürekli kalacaklardır.', 'الذين يرثون الفردوس هم فيها خلدون'),
(2685, 23, 12, 'وَلَقَدْ خَلَقْنَا الْاِنْسَانَ مِنْ سُلَالَةٍ مِنْ ط۪ينٍۚ', 'Ve lekad halaknal insane min sulaletin min tin.', 'Ant olsun ki,  insanı çamurun özünden yarattık.[1]', 'ولقد خلقنا الانسن من سللة من طين'),
(2686, 23, 13, 'ثُمَّ جَعَلْنَاهُ نُطْفَةً ف۪ي قَرَارٍ مَك۪ينٍۖ', 'Summe cealnahu nutfeten fi kararin mekin.', 'Sonra onu güvenli ve sağlam bir mekanda[1] bir nutfe[2] kıldık.', 'ثم جعلنه نطفة في قرار مكين'),
(2687, 23, 14, 'ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً فَخَلَقْنَا الْمُضْغَةَ عِظَاماً فَكَسَوْنَا الْعِظَامَ لَحْماًۗ ثُمَّ اَنْشَأْنَاهُ خَلْقاً اٰخَرَۜ فَتَبَارَكَ اللّٰهُ اَحْسَنُ الْخَالِق۪ينَۜ', 'Summe halaknen nutfete alakaten fe halaknel alakate mudgaten fe halaknel mudgate ızamen fe kesevnel izame lahmen summe enşe\'nahu halkan ahar, fe tebarekallahu ahsenul halikin.', 'Sonra nutfeyi[1] bir alaka[2] olarak yarattık. Alakayı da mudğa[3] olarak yarattık. Mudğadan da kemikleri yarattık. Kemiklere de et giydirdik. Sonra onu başka bir yaratılışla şekillendirdik. Yaratıcıların en iyisi olan Allah ne yücedir.', 'ثم خلقنا النطفة علقة فخلقنا العلقة مضغة فخلقنا المضغة عظما فكسونا العظم لحما ثم انشانه خلقا اخر فتبارك الله احسن الخلقين'),
(2688, 23, 15, 'ثُمَّ اِنَّكُمْ بَعْدَ ذٰلِكَ لَمَيِّتُونَۜ', 'Summe innekum ba\'de zalike le meyyitun.', 'Sonra kuşku yok ki bunun ardından öleceksiniz.', 'ثم انكم بعد ذلك لميتون'),
(2689, 23, 16, 'ثُمَّ اِنَّكُمْ يَوْمَ الْقِيٰمَةِ تُبْعَثُونَ', 'Summe innekum yevmel kıyameti tub\'asun.', 'Sonra kuşkusuz siz Kıyamet Günü diriltileceksiniz.', 'ثم انكم يوم القيمة تبعثون'),
(2690, 23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَٓائِقَۗ وَمَا كُنَّا عَنِ الْخَلْقِ غَافِل۪ينَ', 'Ve lekad halakna fevkakum seb\'a taraika ve ma kunna anil halkı gafilin.', 'Ant olsun ki üzerinizde yolların yedisini yarattık. Ve Biz yarattıklarımızdan habersiz[1] değiliz.', 'ولقد خلقنا فوقكم سبع طرايق وما كنا عن الخلق غفلين'),
(2691, 23, 18, 'وَاَنْزَلْنَا مِنَ السَّمَٓاءِ مَٓاءً بِقَدَرٍ فَاَسْكَنَّاهُ فِي الْاَرْضِۗ وَاِنَّا عَلٰى ذَهَابٍ بِه۪ لَقَادِرُونَۚ', 'Ve enzelna mines semai maen bi kaderin fe eskennahu fil ardı ve inna ala zehabin bihi le kadirun.', 'Gökten kararınca su indirdik. Ve onu yeryüzünde yerleştirdik.[1] Kuşkusuz Biz,  onu gidermeye de gücü yetenleriz.', 'وانزلنا من السما ما بقدر فاسكنه في الارض وانا علي ذهاب به لقدرون'),
(2692, 23, 19, 'فَاَنْشَأْنَا لَكُمْ بِه۪ جَنَّاتٍ مِنْ نَخ۪يلٍ وَاَعْنَابٍۢ لَكُمْ ف۪يهَا فَوَاكِهُ۬ كَث۪يرَةٌ وَمِنْهَا تَأْكُلُونَۙ', 'Fe enşe\'na lekum bihi cennatin min nahilin ve a\'nab, lekum fiha fevakihu kesiretun ve minha te\'kulun.', 'Böylece onunla,  sizin için hurma ve üzüm cennetleri[1] meydana getirdik. Keza,  oralarda yemekte olduğunuz pek çok meyve çeşitleri vardır.', 'فانشانا لكم به جنت من نخيل واعنب لكم فيها فوكه كثيرة ومنها تاكلون'),
(2693, 23, 20, 'وَشَجَرَةً تَخْرُجُ مِنْ طُورِ سَيْنَٓاءَ تَنْبُتُ بِالدُّهْنِ وَصِبْغٍ لِلْاٰكِل۪ينَ', 'Ve şecereten tahrucu min turi seynae tenbutu bid duhni ve sıbgın lil akilin.', 'Tur-i Sina\'da[1],  yağ elde edilen ve aynı zamanda katık olarak yenen ağaç[2] yetiştirdik.', 'وشجرة تخرج من طور سينا تنبت بالدهن وصبغ للاكلين'),
(2694, 23, 21, 'وَاِنَّ لَكُمْ فِي الْاَنْعَامِ لَعِبْرَةًۜ نُسْق۪يكُمْ مِمَّا ف۪ي بُطُونِهَا وَلَكُمْ ف۪يهَا مَنَافِعُ كَث۪يرَةٌ وَمِنْهَا تَأْكُلُونَۙ', 'Ve inne lekum fil en\'ami le ibreh, nuskikum mimma fi butuniha ve lekum fiha menafiu kesiretun ve minha te\'kulun.', 'Hayvanlardan da sizin için alınacak dersler vardır. Onların karınlarındaki şeyden size içiriyoruz. Ve onlarda sizin için pek çok yararlar vardır. Ve onlardan yersiniz.', 'وان لكم في الانعم لعبرة نسقيكم مما في بطونها ولكم فيها منفع كثيرة ومنها تاكلون'),
(2695, 23, 22, 'وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ۟', 'Ve aleyha ve alel fulki tuhmelun.', 'Onları ve gemileri taşıma aracı olarak kullanırsınız.', 'وعليها وعلي الفلك تحملون'),
(2696, 23, 23, 'وَلَقَدْ اَرْسَلْنَا نُوحاً اِلٰى قَوْمِه۪ فَقَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ  اَفَلَا تَتَّقُونَ', 'Ve lekad erselna nuhan ila kavmihi fe kale ya kavmi\' budullahe ma lekum min ilahin gayruh, e fe la tettekun.', 'Ant olsun ki Biz,  Nuh\'u halkına gönderdik. \"Ey halkım! Allah\'a kulluk edin. Sizin için O\'ndan başka ilah yoktur. Hala takva sahibi olmayacak mısınız?\" dedi.', 'ولقد ارسلنا نوحا الي قومه فقال يقوم اعبدوا الله ما لكم من اله غيره افلا تتقون'),
(2697, 23, 24, 'فَقَالَ الْمَلَؤُا الَّذ۪ينَ كَفَرُوا مِنْ قَوْمِه۪ مَا هٰذَٓا اِلَّا بَشَرٌ مِثْلُكُمْۙ يُر۪يدُ اَنْ يَتَفَضَّلَ عَلَيْكُمْۜ وَلَوْ شَٓاءَ اللّٰهُ لَاَنْزَلَ مَلٰٓئِكَةًۚ مَا سَمِعْنَا بِهٰذَا ف۪ٓي اٰبَٓائِنَا الْاَوَّل۪ينَۚ', 'Fe kalel meleullezine keferu min kavmihi ma haza illa beşerun mıslukum yuridu en yetefaddale aleykum, ve lev şaallahu le enzele melaikeh, ma semi\'na bi haza fi abainel evvelin.', 'Bunun üzerine halkından Kafir[1] meleler:[2] \"Bu,  sizin gibi bir beşerden başka bir şey değildir. Size karşı üstünlük kurmak istiyor. Eğer Allah isteseydi mutlaka melekler indirirdi. Geçmiş atalarımızdan da böyle bir şey duymadık.\" dediler.', 'فقال الملوا الذين كفروا من قومه ما هذا الا بشر مثلكم يريد ان يتفضل عليكم ولو شا الله لانزل مليكة ما سمعنا بهذا في اباينا الاولين'),
(2698, 23, 25, 'اِنْ هُوَ اِلَّا رَجُلٌ بِه۪ جِنَّةٌ فَتَرَبَّصُوا بِه۪ حَتّٰى ح۪ينٍ', 'İn huve illa raculun bihi cinnetun fe terabbasu bihi hatta hin.', '\"O[1] ancak cinlenmiş bir adamdır. O halde kesinlikle bir süre[2] bekleyin.\"', 'ان هو الا رجل به جنة فتربصوا به حتي حين'),
(2699, 23, 26, 'قَالَ رَبِّ انْصُرْن۪ي بِمَا كَذَّبُونِ', 'Kale rabbinsurni bima kezzebun.', 'Nuh: \"Rabb\'im! Yalanlamalarına karşı bana yardım et!\" dedi.', 'قال رب انصرني بما كذبون'),
(2700, 23, 27, 'فَاَوْحَيْنَٓا اِلَيْهِ اَنِ اصْنَعِ الْفُلْكَ بِاَعْيُنِنَا وَوَحْيِنَا فَاِذَا جَٓاءَ اَمْرُنَا وَفَارَ التَّنُّورُۙ فَاسْلُكْ ف۪يهَا مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَاَهْلَكَ اِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْۚ وَلَا تُخَاطِبْن۪ي فِي الَّذ۪ينَ ظَلَمُواۚ اِنَّهُمْ مُغْرَقُونَ', 'Fe evhayna ileyhi enısnaıl fulke bi a\'yunina ve vahyina fe iza cae emruna ve faret tennuru fesluk fiha min kullin zevceynisneyni ve ehleke illa men sebeka aleyhil kavlu minhum, ve la tuhatıbni fillezine zalemu, innehum mugrakun.', 'Bunun üzerine Biz,  ona: \"Gözetimimiz altında vahyimiz ile bildirdiğimiz gibi gemi yap.\" diye vahyettik. Böylece emrimiz gereği Tennur kaynadığı[1] zaman hemen ona[2] her cinsten eşler olarak iki adet ve ehlini[3] bindir. Onlardan,  haklarında önceden hüküm verilenler hariç. Ve zulmedenler hakkında Benden bir dilekte bulunma. Onlar boğulacak olanlardır.', 'فاوحينا اليه ان اصنع الفلك باعيننا ووحينا فاذا جا امرنا وفار التنور فاسلك فيها من كل زوجين اثنين واهلك الا من سبق عليه القول منهم ولا تخطبني في الذين ظلموا انهم مغرقون'),
(2701, 23, 28, 'فَاِذَا اسْتَوَيْتَ اَنْتَ وَمَنْ مَعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ لِلّٰهِ الَّذ۪ي نَجّٰينَا مِنَ الْقَوْمِ الظَّالِم۪ينَ', 'Fe izesteveyte ente ve men meake alel fulki fe kulil hamdu lillahillezi neccana minel kavmiz zalimin.', 'Sen ve seninle birlikte olanlar gemiye bindiğiniz zaman: \"Zalim halktan bizi kurtaran Allah\'a hamdolsun.\" de.', 'فاذا استويت انت ومن معك علي الفلك فقل الحمد لله الذي نجينا من القوم الظلمين'),
(2702, 23, 29, 'وَقُلْ رَبِّ اَنْزِلْن۪ي مُنْزَلاً مُبَارَكاً وَاَنْتَ خَيْرُ الْمُنْزِل۪ينَ', 'Ve kul rabbi enzilni munzelen mubareken ve ente hayrul munzilin.', 'Ve de ki: \"Rabbim! Beni kutlu,  bereketli bir yere indir. Ve Sen doğru yere yerleştireceklerin en hayırlısısın.\"', 'وقل رب انزلني منزلا مباركا وانت خير المنزلين'),
(2703, 23, 30, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ وَاِنْ كُنَّا لَمُبْتَل۪ينَ', 'İnne fi zalike le ayatin ve in kunna le mubtelin.', 'Bunda kesinlikle ayetler[1] vardır. Ve Biz kesinlikle sınayanlarız.', 'ان في ذلك لايت وان كنا لمبتلين'),
(2704, 23, 31, 'ثُمَّ اَنْشَأْنَا مِنْ بَعْدِهِمْ قَرْناً اٰخَر۪ينَۚ', 'Summe enşe\'na min ba\'dihim karnen aharin.', 'Sonra onların ardından başka bir nesil ortaya çıkardık.', 'ثم انشانا من بعدهم قرنا اخرين'),
(2705, 23, 32, 'فَاَرْسَلْنَا ف۪يهِمْ رَسُولاً مِنْهُمْ اَنِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ اِلٰهٍ غَيْرُهُۜ  اَفَلَا تَتَّقُونَ۟', 'Fe erselna fihim resulen minhum eni\'budullahe ma lekum min ilahin gayruh, e fe la tettekun.', 'Onlara,  kendi içlerinden,  \"Allah\'a kulluk edin,  sizin O\'ndan başka ilahınız yoktur,  hala takva sahibi olmayacak mısınız?\" diyen bir Resul gönderdik.', 'فارسلنا فيهم رسولا منهم ان اعبدوا الله ما لكم من اله غيره افلا تتقون'),
(2706, 23, 33, 'وَقَالَ الْمَلَأُ مِنْ قَوْمِهِ الَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِلِقَٓاءِ الْاٰخِرَةِ وَاَتْرَفْنَاهُمْ فِي الْحَيٰوةِ الدُّنْيَاۙ مَا هٰذَٓا اِلَّا بَشَرٌ مِثْلُكُمْۙ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 'Ve kalel meleu min kavmihillezine keferu ve kezzebu bi likail ahıreti ve etrafnahum fil hayatid dunya ma haza illa beşerun mislukum ye\'kulu mimma te\'kulune minhu yeşrebu mimma teşrabun.', 'Dünya hayatında refaha kavuşturduğumuz,  Kafirlik[1] eden ve ahirete kavuşmayı yalanlayan kavminin meleleri[1]: \"Bu da sizin gibi bir beşerdir[2]. Sizin yediğinizden yiyor,  sizin içtiğinizden içiyor.\" dediler.', 'وقال الملا من قومه الذين كفروا وكذبوا بلقا الاخرة واترفنهم في الحيوة الدنيا ما هذا الا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون'),
(2707, 23, 34, 'وَلَئِنْ اَطَعْتُمْ بَشَراً مِثْلَكُمْ اِنَّكُمْ اِذاً لَخَاسِرُونَ', 'Ve lein eta\'tum beşeren mislekum innekum izen le hasirun.', '\"Eğer siz,  sizden hiçbir farkı olmayan böyle bir beşere uyacak olursanız,  kesinlikle hüsrana uğrarsınız.', 'ولين اطعتم بشرا مثلكم انكم اذا لخسرون'),
(2708, 23, 35, 'اَيَعِدُكُمْ اَنَّكُمْ اِذَا مِتُّمْ وَكُنْتُمْ تُرَاباً وَعِظَاماً اَنَّكُمْ مُخْرَجُونَۖ', 'E yaıdukum ennekum iza mittum ve kuntum turaben ve izamen ennekum muhracun.', '\"Sizi; ölüp,  toprak ve kemik haline geldikten sonra,  yeniden diriltileceğinizle mi uyarıyor?\"', 'ايعدكم انكم اذا متم وكنتم ترابا وعظما انكم مخرجون'),
(2709, 23, 36, 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَۖ', 'Heyhate heyhate lima tuadun.', '\"Yazık,  yazık! Uyarıldığınız şey,  hiç olacak şey mi?\"', 'هيهات هيهات لما توعدون'),
(2710, 23, 37, 'اِنْ هِيَ اِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوث۪ينَۖ', 'İn hiye illa hayatuned dunya nemutu ve nahya ve ma nahnu bi meb\'usin.', '\"Hayat,  yalnızca bu dünyadan ibarettir. Yaşarız ve ölürüz. Yeniden diriltilecek değiliz.\"', 'ان هي الا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين'),
(2711, 23, 38, 'اِنْ هُوَ اِلَّا رَجُلٌۨ افْـتَرٰى عَلَى اللّٰهِ كَذِباً وَمَا نَحْنُ لَهُ بِمُؤْمِن۪ينَ', 'İn huve illa raculuniftera alallahi keziben ve ma nahnu lehu bi mu\'minin.', 'O,  uydurduğu yalanı Allah\'a dayandıran bir kimsedir. Ona inanacak değiliz.\"', 'ان هو الا رجل افتري علي الله كذبا وما نحن له بمومنين'),
(2712, 23, 39, 'قَالَ رَبِّ انْصُرْن۪ي بِمَا كَذَّبُونِ', 'Kale rabbinsurni bima kezzebun.', '\"Rabbim! Yalanlamaları nedeniyle bana yardım et.\" dedi.', 'قال رب انصرني بما كذبون'),
(2713, 23, 40, 'قَالَ عَمَّا قَل۪يلٍ لَيُصْبِحُنَّ نَادِم۪ينَۚ', 'Kale amma kalilin le yusbihunne nadimin.', 'Allah: \"Pek yakında kesinlikle pişman olacaklar.\" dedi.', 'قال عما قليل ليصبحن ندمين'),
(2714, 23, 41, 'فَاَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ فَجَعَلْنَاهُمْ غُـثَٓاءًۚ فَبُعْداً لِلْقَوْمِ الظَّالِم۪ينَ', 'Fe ehazethumus sayhatu bil hakkı fe cealnahum gusaen, fe bu\'den lil kavmiz zalimin.', 'Derken,  kaçınılmaz bir gerçek olarak sayha[1] onları yakalayıverdi. Böylece onları çerçöp yaptık. Zalim halk yok oldu.', 'فاخذتهم الصيحة بالحق فجعلنهم غثا فبعدا للقوم الظلمين'),
(2715, 23, 42, 'ثُمَّ اَنْشَأْنَا مِنْ بَعْدِهِمْ قُرُوناً اٰخَر۪ينَۜ', 'Summe enşe\'na min ba\'dihim kurunen aharin.', 'Sonra,  onların ardından başka nesiller getirdik.', 'ثم انشانا من بعدهم قرونا اخرين'),
(2716, 23, 43, 'مَا تَسْبِقُ مِنْ اُمَّةٍ اَجَلَهَا وَمَا يَسْتَأْخِرُونَۜ', 'Ma tesbiku min ummetin eceleha ve ma yeste\'hırun.', 'Hiçbir ümmet[1] ecelini[2] öne alamaz ve erteleyemez.', 'ما تسبق من امة اجلها وما يستخرون'),
(2717, 23, 44, 'ثُمَّ اَرْسَلْنَا رُسُلَنَا تَتْرَاۜ  كُلَّمَا جَٓاءَ اُمَّةً رَسُولُهَا كَذَّبُوهُ فَاَتْبَعْنَا بَعْضَهُمْ بَعْضاً وَجَعَلْنَاهُمْ اَحَاد۪يثَۚ فَبُعْداً لِقَوْمٍ لَا يُؤْمِنُونَ', 'Summe erselna rusulena tetra, kullema cae ummeten resuluha kezzebuhu fe etba\'na ba\'dahum ba\'dan ve cealnahum ehadis, fe bu\'den li kavmin la yu\'minun.', 'Sonra ardı ardına elçilerimizi gönderdik. Her ümmet,  kendilerine gelen resulleri yalanladı. Biz de onları ardı sıra devirdik. Ve onları halkın dilinde hadis[1] konusu yaptık. İnanmayan halk uzak olsun.', 'ثم ارسلنا رسلنا تترا كل ما جا امة رسولها كذبوه فاتبعنا بعضهم بعضا وجعلنهم احاديث فبعدا لقوم لا يومنون'),
(2718, 23, 45, 'ثُمَّ اَرْسَلْنَا مُوسٰى وَاَخَاهُ هٰرُونَ بِاٰيَاتِنَا وَسُلْطَانٍ مُب۪ينٍۙ', 'Summe erselna musa ve ehahu harune bi ayatina ve sultanin mubin.', 'Sonra da Musa ve kardeşi Harun\'u ayetlerimizle ve apaçık bir görevle gönderdik;', 'ثم ارسلنا موسي واخاه هرون بايتنا وسلطن مبين'),
(2719, 23, 46, 'اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ فَاسْتَكْـبَرُوا وَكَانُوا قَوْماً عَال۪ينَۚ', 'İla fir\'avne ve meleihi festekberu ve kanu kavmen alin.', 'Firavun ve melelerine[1]. Ancak onlar kibirlendiler. Büyüklük taslayan bir halk oldular.', 'الي فرعون وملايه فاستكبروا وكانوا قوما عالين'),
(2720, 23, 47, 'فَقَالُٓوا اَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَابِدُونَۚ', 'Fe kalu e nu\'minu li beşereyni mislina ve kavmuhuma lena abidun.', 'Sonra da: \"Bizden farkı olmayan,  üstelik halkı da bize kulluk eden bu iki beşere mi inanacağız?\" dediler.', 'فقالوا انومن لبشرين مثلنا وقومهما لنا عبدون'),
(2721, 23, 48, 'فَكَذَّبُوهُمَا فَكَانُوا مِنَ الْمُهْلَك۪ينَ', 'Fe kezzebuhuma fe kanu minel muhlekin.', 'Onları yalanladılar. Ve helak edilenlerden oldular.', 'فكذبوهما فكانوا من المهلكين'),
(2722, 23, 49, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ لَعَلَّهُمْ يَهْتَدُونَ', 'Ve lekad ateyna musel kitabe leallehum yehtedun.', 'Ve ant olsun,  onlar doğru yolu bulsunlar diye Musa\'ya Kitap\'ı[1] verdik.', 'ولقد اتينا موسي الكتب لعلهم يهتدون'),
(2723, 23, 50, 'وَجَعَلْنَا ابْنَ مَرْيَمَ وَاُمَّهُٓ اٰيَةً وَاٰوَيْنَاهُمَٓا اِلٰى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَع۪ينٍ۟', 'Ve cealnebne meryeme ve ummehu ayeten ve aveynahuma ila rabvetin zati kararin ve main.', 'Meryem oğlunu ve annesini bir ayet[1] kıldık. Ve ikisini,  suyu olan yerleşime uygun bir tepeye yerleştirdik.', 'وجعلنا ابن مريم وامه اية واوينهما الي ربوة ذات قرار ومعين'),
(2724, 23, 51, 'يَٓا اَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحاًۜ اِنّ۪ي بِمَا تَعْمَلُونَ عَل۪يمٌۜ', 'Ya eyyuher rusulu kulu minet tayyibati va\'melu saliha, inni bima ta\'melune alim.', 'Ey resuller! Helal ve temiz şeylerden yiyin. Ve salihatı yapın. Kuşkusuz yaptığınız şeyleri bilirim.', 'يايها الرسل كلوا من الطيبت واعملوا صلحا اني بما تعملون عليم'),
(2725, 23, 52, 'وَاِنَّ هٰذِه۪ٓ  اُمَّتُكُمْ اُمَّةً وَاحِدَةً وَاَنَا۬ رَبُّكُمْ فَاتَّقُونِ', 'Ve inne hazihi ummetukum ummeten vahıdeten ve ene rabbukum fettekun.', 'Bu sizin ümmetiniz[1],  tek bir ümmettir[2]. Ben de sizin Rabb\'inizim. O halde bana karşı takva sahibi olun.', 'وان هذه امتكم امة وحدة وانا ربكم فاتقون'),
(2726, 23, 53, 'فَـتَقَطَّـعُٓوا اَمْرَهُمْ بَيْنَهُمْ زُبُراًۜ  كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ', 'Fe tekattau emrehum beynehum zubura, kullu hızbin bima ledeyhim ferihun.', 'Sonra işlerini aralarında parça parça ettiler. Her bir grup kendine olanla yetinmektedir.', 'فتقطعوا امرهم بينهم زبرا كل حزب بما لديهم فرحون'),
(2727, 23, 54, 'فَذَرْهُمْ ف۪ي غَمْرَتِهِمْ حَتّٰى ح۪ينٍ', 'Fe zerhum fi gamratihim hatta hin.', 'Artık onları belli bir süreye kadar aymazlıkları ile baş başa bırak!', 'فذرهم في غمرتهم حتي حين'),
(2728, 23, 55, 'اَيَحْسَبُونَ اَنَّمَا نُمِدُّهُمْ بِه۪ مِنْ مَالٍ وَبَن۪ينَۙ', 'E yahsebune ennema numidduhum bihi min malin ve benin.', 'Mal ve oğullarla onlara iyilik yaptığımızı mı sanıyorlar?', 'ايحسبون انما نمدهم به من مال وبنين'),
(2729, 23, 56, 'نُسَارِعُ لَهُمْ فِي الْخَيْرَاتِۜ بَلْ لَا يَشْعُرُونَ', 'Nusariu lehum fil hayrat bel la yeş\'urun.', 'Hayırlarını çabuklaştırdığımızı mı sanıyorlar. Hayır,  gerçeği kavrayacak bilinçte değiller.', 'نسارع لهم في الخيرت بل لا يشعرون'),
(2730, 23, 57, 'اِنَّ الَّذ۪ينَ هُمْ مِنْ خَشْيَةِ رَبِّهِمْ مُشْفِقُونَۙ', 'İnnellezine hum min haşyeti rabbihim muşfikun.', 'Rabb\'lerine karşı derin saygı duyan kimseler,  O\'nu incitmekten çekinirler.', 'ان الذين هم من خشية ربهم مشفقون'),
(2731, 23, 58, 'وَالَّذ۪ينَ هُمْ بِاٰيَاتِ رَبِّهِمْ يُؤْمِنُونَۙ', 'Vellezine hum bi ayati rabbihim yu\'minun.', 'Onlar,  Rabb\'lerinin ayetlerine inanırlar.', 'والذين هم بايت ربهم يومنون'),
(2732, 23, 59, 'وَالَّذ۪ينَ هُمْ بِرَبِّهِمْ لَا يُشْرِكُونَۙ', 'Vellezine hum bi rabbihim la yuşrikun.', 'Onlar,  Rabb\'lerine şirk koşmazlar.', 'والذين هم بربهم لا يشركون'),
(2733, 23, 60, 'وَالَّذ۪ينَ يُؤْتُونَ مَٓا اٰتَوْا وَقُلُوبُهُمْ وَجِلَةٌ اَنَّهُمْ اِلٰى رَبِّهِمْ رَاجِعُونَۙ', 'Vellezine yu\'tune ma atev ve kulubuhum veciletun ennehum ila rabbihim raciun.', 'Rabb\'lerine döneceklerinin bilinciyle,  derin bir saygı içinde vermeleri gerekenleri verirler.', 'والذين يوتون ما اتوا وقلوبهم وجلة انهم الي ربهم رجعون'),
(2734, 23, 61, 'اُو۬لٰٓئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ', 'Ulaike yusariune fil hayrati ve hum leha sabikun.', 'İşte onlar,  hayırlarda yarışırlar ve onda öncülük ederler.', 'اوليك يسرعون في الخيرت وهم لها سبقون'),
(2735, 23, 62, 'وَلَا نُكَلِّفُ نَفْساً اِلَّا وُسْعَهَا وَلَدَيْنَا كِتَابٌ يَنْطِقُ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'Ve la nukellifu nefsen illa vus\'aha ve ledeyna kitabun yantıku bil hakkı ve hum la yuzlemun.', 'Hiç kimseyi gücünün yettiğinden fazlasıyla sorumlu tutmayız. Nezdimizde gerçeği söyleyen bir kitap vardır. Onlar haksızlığa uğratılmazlar.', 'ولا نكلف نفسا الا وسعها ولدينا كتب ينطق بالحق وهم لا يظلمون'),
(2736, 23, 63, 'بَلْ قُلُوبُهُمْ ف۪ي غَمْرَةٍ مِنْ هٰذَا وَلَهُمْ اَعْمَالٌ مِنْ دُونِ ذٰلِكَ هُمْ لَهَا عَامِلُونَ', 'Bel kulubuhum fi gamratin min haza ve lehum a\'malun min duni zalike hum leha amilun.', 'Fakat onların kalpleri[1] bundan gaflet[2] içindedir. Onlar,  başka işlerle[3] uğraşıp durmaktadırlar.', 'بل قلوبهم في غمرة من هذا ولهم اعمل من دون ذلك هم لها عملون'),
(2737, 23, 64, 'حَتّٰٓى اِذَٓا اَخَذْنَا مُتْرَف۪يهِمْ بِالْعَذَابِ اِذَا هُمْ يَجْـَٔرُونَۜ', 'Hatta iza ehazna mutrafihim bil azabi iza hum yec\'erun.', 'Nihayet varlıklılarını azapla yakaladığımızda,  hemen feryat etmeye başlarlar.', 'حتي اذا اخذنا مترفيهم بالعذاب اذا هم يجرون'),
(2738, 23, 65, 'لَا تَجْـَٔرُوا الْيَوْمَ اِنَّكُمْ مِنَّا لَا تُنْصَرُونَ', 'La tec\'erul yevme innekum minna la tunsarun.', 'Bugün boşuna feryat etmeyin. Kesinlikle Bize karşı size yardım olunmaz.', 'لا تجروا اليوم انكم منا لا تنصرون'),
(2739, 23, 66, 'قَدْ كَانَتْ اٰيَات۪ي تُتْلٰى عَلَيْكُمْ فَكُنْتُمْ عَلٰٓى اَعْقَابِكُمْ تَنْكِصُونَۙ', 'Kad kanet ayati tutla aleykum fe kuntum ala a\'kabikum tenkisun.', 'Vaktinde ayetlerimiz size okunduğunda siz onları hiçe sayıyordunuz.', 'قد كانت ايتي تتلي عليكم فكنتم علي اعقبكم تنكصون'),
(2740, 23, 67, 'مُسْتَكْبِر۪ينَ بِه۪ۗ سَامِراً تَهْجُرُونَ', 'Mustekbirine bihi samiran tehcurun.', 'Ayetlerime karşı büyüklük taslayarak,  geceleri toplanıp saçma sapan değerlendirmeler yapıyordunuz.', 'مستكبرين به سمرا تهجرون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2741, 23, 68, 'اَفَلَمْ يَدَّبَّرُوا الْقَوْلَ اَمْ جَٓاءَهُمْ مَا لَمْ يَأْتِ اٰبَٓاءَهُمُ الْاَوَّل۪ينَۘ', 'E fe lem yeddebberul kavle em caehum ma lem ye\'ti abaehumul evvelin.', 'Onlar,  hala sözün[1] üzerinde düşünmüyorlar mı? Yoksa onlara,  atalarına gelmemiş bir şey mi geldi?', 'افلم يدبروا القول ام جاهم ما لم يات اباهم الاولين'),
(2742, 23, 69, 'اَمْ لَمْ يَعْرِفُوا رَسُولَهُمْ فَهُمْ لَهُ مُنْكِرُونَۘ', 'Em lem ya\'rifu resulehum fe hum lehu munkirun.', 'Yoksa resullerinin nasıl birisi olduğunu bilmiyorlar da onun için mi onu reddediyorlar?', 'ام لم يعرفوا رسولهم فهم له منكرون'),
(2743, 23, 70, 'اَمْ يَقُولُونَ بِه۪ جِنَّةٌۜ  بَلْ جَٓاءَهُمْ بِالْحَقِّ وَاَكْثَرُهُمْ لِلْحَقِّ كَارِهُونَ', 'Em yekulune bihi cinneh, bel caehum bil hakkı ve ekseruhum lil hakkı karihun.', 'Yoksa onda bir delilik olduğunu mu söylüyorlar? Hayır,  onlara,  Hakk ile geldi. Ne var ki onların çoğu Hakk\'tan hoşlanmıyorlar.', 'ام يقولون به جنة بل جاهم بالحق واكثرهم للحق كرهون'),
(2744, 23, 71, 'وَلَوِ اتَّبَعَ الْحَقُّ اَهْوَٓاءَهُمْ لَفَسَدَتِ السَّمٰوَاتُ وَالْاَرْضُ وَمَنْ ف۪يهِنَّۜ بَلْ اَتَيْنَاهُمْ بِذِكْرِهِمْ فَهُمْ عَنْ ذِكْرِهِمْ مُعْرِضُونَۜ', 'Ve levittebeal hakku ehvaehum le fesedetis semavatu vel ardu ve men fi hinn, bel eteynahum bi zikrihim fe hum an zikrihim mu\'ridun.', 'Eğer Hakk[1] onların hevalarına[2] göre belirlenseydi gökler,  yer ve onların içindekiler bozguna uğrardı. Hayır,  faydalarına olacak zikirlerini[3] getirdik. Ne var ki onlar faydalarına olan zikirden[3] yüz çevirenlerdir.', 'ولو اتبع الحق اهواهم لفسدت السموت والارض ومن فيهن بل اتينهم بذكرهم فهم عن ذكرهم معرضون'),
(2745, 23, 72, 'اَمْ تَسْـَٔلُهُمْ خَرْجاً فَخَرَاجُ رَبِّكَ خَيْرٌۗ وَهُوَ خَيْرُ الرَّازِق۪ينَ', 'Em tes\'eluhum harcen fe haracu rabbike hayrun ve huve hayrur razikin.', 'Yoksa onlardan bir karşılık mı bekliyorsun? Rabbinin vereceği karşılık daha hayırlıdır. O rızıklandıranların en hayırlısıdır.', 'ام تسلهم خرجا فخراج ربك خير وهو خير الرزقين'),
(2746, 23, 73, 'وَاِنَّكَ لَتَدْعُوهُمْ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Ve inneke le ted\'uhum ila sıratın mustakim.', 'Kuşkusuz sen onları dosdoğru bir yola çağırıyorsun.', 'وانك لتدعوهم الي صرط مستقيم'),
(2747, 23, 74, 'وَاِنَّ  الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ عَنِ الصِّرَاطِ لَنَاكِبُونَ', 'Ve innellezine la yu\'minune bil ahıreti anis sıratı le nakibun.', 'Kuşkusuz ahirete inanmayanlar,  bu doğru yoldan sapanlardır.', 'وان الذين لا يومنون بالاخرة عن الصرط لنكبون'),
(2748, 23, 75, 'وَلَوْ رَحِمْنَاهُمْ وَكَشَفْنَا مَا بِهِمْ مِنْ ضُرٍّ لَلَجُّوا ف۪ي طُغْيَانِهِمْ يَعْمَهُونَ', 'Ve lev rahımnahum ve keşefna ma bihim min durrin le leccu fi tugyanihim ya\'mehun.', 'Onlara,  rahmet edip sıkıntılarını gidersek,  yine de azgınlıklarına devam ederler.', 'ولو رحمنهم وكشفنا ما بهم من ضر للجوا في طغينهم يعمهون'),
(2749, 23, 76, 'وَلَقَدْ اَخَذْنَاهُمْ بِالْعَذَابِ فَمَا اسْتَكَانُوا لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', 'Ve lekad ehaznahum bil azabi fe mestekanu li rabbihim ve ma yetedarreun.', 'Ant olsun,  onları azap ile yakaladık[1]. Ancak Rabbleri için uslanmadılar ve tezarruda[2] bulunmadılar.', 'ولقد اخذنهم بالعذاب فما استكانوا لربهم وما يتضرعون'),
(2750, 23, 77, 'حَتّٰٓى اِذَا فَتَحْنَا عَلَيْهِمْ بَاباً ذَا عَذَابٍ شَد۪يدٍ اِذَا هُمْ ف۪يهِ مُبْلِسُونَ۟', 'Hatta iza fetahna aleyhim baben za azabin şedidin iza hum fihi mublisun.', 'Ne var ki üzerlerine şiddetli bir azap kapısı açtığımız zaman,  bütün ümitleri boşa çıkacaktır.', 'حتي اذا فتحنا عليهم بابا ذا عذاب شديد اذا هم فيه مبلسون'),
(2751, 23, 78, 'وَهُوَ الَّـذ۪ٓي اَنْشَاَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٔدَةَۜ قَل۪يلاً مَا تَشْكُرُونَ', 'Ve huvellezi enşee lekumus sem\'a vel ebsara vel ef\'ideh, kalilen ma teşkurun.', 'Size; işitme,  görme ve ef\'ide[1] veren O\'dur. Ne kadar az şükrediyorsunuz?[2]', 'وهو الذي انشا لكم السمع والابصر والافدة قليلا ما تشكرون'),
(2752, 23, 79, 'وَهُوَ الَّذ۪ي ذَرَاَكُمْ فِي الْاَرْضِ وَاِلَيْهِ تُحْشَرُونَ', 'Ve huvellezi zereekum fil ardı ve ileyhi tuhşerun.', 'Sizi yeryüzünde çoğaltan O\'dur. Ve O\'nun huzurunda toplanacaksınız.', 'وهو الذي ذراكم في الارض واليه تحشرون'),
(2753, 23, 80, 'وَهُوَ الَّذ۪ي يُحْـي۪ وَيُم۪يتُ وَلَهُ اخْتِلَافُ الَّيْلِ وَالنَّهَارِۜ اَفَلَا تَعْقِلُونَ', 'Ve huvellezi yuhyi ve yumitu ve lehuhtilaful leyli ven nehar, e fe la ta\'kılun.', 'Hayat veren de ve öldüren de O\'dur. Gece ve gündüzün oluşması O\'nun yasalarına göredir. Siz hala aklınızı kullanmayacak mısınız?', 'وهو الذي يحي ويميت وله اختلف اليل والنهار افلا تعقلون'),
(2754, 23, 81, 'بَلْ قَالُوا مِثْلَ مَا قَالَ الْاَوَّلُونَ', 'Bel kalu misle ma kalel evvelun.', 'Ancak onlar öncekilerin dediklerinin aynısını dediler.', 'بل قالوا مثل ما قال الاولون'),
(2755, 23, 82, 'قَالُٓوا ءَاِذَا مِتْنَا وَكُنَّا تُرَاباً وَعِظَاماً ءَاِنَّا لَمَبْعُوثُونَ', 'Kalu e iza mitna ve kunna turaben ve izamen e inna le meb\'usun.', 'Dediler ki: \"Ölüp de toprak ve kemik yığını olduktan sonra mı diriltileceğiz?\"', 'قالوا اذا متنا وكنا ترابا وعظما انا لمبعوثون'),
(2756, 23, 83, 'لَقَدْ وُعِدْنَا نَحْنُ وَاٰبَٓاؤُ۬نَا هٰذَا مِنْ قَبْلُ اِنْ هٰذَٓا اِلَّٓا اَسَاط۪يرُ الْاَوَّل۪ينَ', 'Lekad vuıdna nahnu ve abauna haza min kablu in haza illa esatirul evvelin.', '\"Ant olsun ki bize yapılan bu uyarı,  daha önce atalarımıza da yapılmıştı. Bu eskilerin masallarından başka bir şey değildir.\"', 'لقد وعدنا نحن واباونا هذا من قبل ان هذا الا اسطير الاولين'),
(2757, 23, 84, 'قُلْ لِمَنِ الْاَرْضُ وَمَنْ ف۪يهَٓا اِنْ كُنْتُمْ تَعْلَمُونَ', 'Kul li menil ardu ve men fiha in kuntum ta\'lemun.', 'De ki: \"Söyleyin bakalım,  yeryüzü ve onda bulunanlar kime aittir?\"', 'قل لمن الارض ومن فيها ان كنتم تعلمون'),
(2758, 23, 85, 'سَيَقُولُونَ لِلّٰهِۜ قُلْ اَفَلَا تَذَكَّرُونَ', 'Seyekulune lillah, kul e fe la tezekkerun.', '\"Allah\'a aittir.\" diyecekler. De ki: \"Hala öğüt almayacak mısınız?\"', 'سيقولون لله قل افلا تذكرون'),
(2759, 23, 86, 'قُلْ مَنْ رَبُّ السَّمٰوَاتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْعَظ۪يمِ', 'Kul men rabbus semavatis seb\'ı ve rabbul arşil azim.', 'De ki: \"Yedi göğün ve muazzam arşın[1] Rabb\'i kimdir?\"', 'قل من رب السموت السبع ورب العرش العظيم'),
(2760, 23, 87, 'سَيَقُولُونَ لِلّٰهِۜ قُلْ اَفَلَا تَتَّقُونَ', 'Seyekulune lillah, kul e fe la tettekun.', '\"Allah\'tır.\" diyecekler. De ki: \"O halde takva sahibi olmayacak mısınız?\"', 'سيقولون لله قل افلا تتقون'),
(2761, 23, 88, 'قُلْ مَنْ بِيَدِه۪ مَلَكُوتُ كُلِّ شَيْءٍ وَهُوَ يُج۪يرُ وَلَا يُجَارُ عَلَيْهِ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Kul men bi yedihi melekutu kulli şey\'in ve huve yuciru ve la yucaru aleyhi in kuntum ta\'lemun.', 'Sor bakalım: \"Evrenin egemenliğine sahip olan,  koruyup gözeten ve kendisine karşı kimsenin korunamayacağı kimdir? Biliyorsanız söyleyin!\"', 'قل من بيده ملكوت كل شي وهو يجير ولا يجار عليه ان كنتم تعلمون'),
(2762, 23, 89, 'سَيَقُولُونَ لِلّٰهِۜ قُلْ فَاَنّٰى تُسْحَرُونَ', 'Seyekulune lillah, kul fe enna tusharun.', '\"Allah\'tır.\" diyecekler. De ki: \"Öyleyse nasıl oluyor da aldanıyorsunuz?\"', 'سيقولون لله قل فاني تسحرون'),
(2763, 23, 90, 'بَلْ اَتَيْنَاهُمْ بِالْحَقِّ وَاِنَّهُمْ لَكَاذِبُونَ', 'Bel eteynahum bil hakkı ve innehum le kazibun.', 'Oysa onlara Hakkı sunuyoruz. Onlar ise kesinlikle yalanlamaktadırlar.', 'بل اتينهم بالحق وانهم لكذبون'),
(2764, 23, 91, 'مَا اتَّخَذَ اللّٰهُ مِنْ وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ اِلٰهٍ اِذاً لَذَهَبَ كُلُّ اِلٰهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلٰى بَعْضٍۜ سُبْحَانَ اللّٰهِ عَمَّا يَصِفُونَۙ', 'Mettehazallahu min veledin ve ma kane meahu min ilahin izen le zehebe kullu ilahin bima halaka ve le ala ba\'duhum ala ba\'d, subhanallahi amma yasıfun.', 'Allah,  çocuk edinmemiştir. Ve O\'nun yanı sıra bir ilah daha yoktur. Eğer olsaydı her ilah kendi yarattığı ile birlikte hareket eder ve kimisi kimisine üstün olurdu. Allah,  onların niteledikleri şeylerden münezzehtir.[1]', 'ما اتخذ الله من ولد وما كان معه من اله اذا لذهب كل اله بما خلق ولعلا بعضهم علي بعض سبحن الله عما يصفون'),
(2765, 23, 92, 'عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَتَعَالٰى عَمَّا يُشْرِكُونَ۟', 'Alimil gaybi veş şehadeti fe teala amma yuşrikun.', 'O,  gizliyi de açığı da bilir. Onların şirk koştuklarından çok yücedir.', 'علم الغيب والشهدة فتعلي عما يشركون'),
(2766, 23, 93, 'قُلْ رَبِّ اِمَّا تُرِيَنّ۪ي مَا يُوعَدُونَۙ', 'Kul rabbi imma turiyenni ma yuadun.', 'De ki: \"Rabbim! Eğer onlara uyarısı yapılan azabı bana göstereceksen;\"', 'قل رب اما تريني ما يوعدون'),
(2767, 23, 94, 'رَبِّ فَلَا تَجْعَلْن۪ي فِي الْقَوْمِ الظَّالِم۪ينَ', 'Rabbi fe la tec\'alni fil kavmiz zalimin.', '\"Rabbim! Beni,  o zalim halk içinde bırakma.\"', 'رب فلا تجعلني في القوم الظلمين'),
(2768, 23, 95, 'وَاِنَّا عَلٰٓى اَنْ نُرِيَكَ مَا نَعِدُهُمْ لَقَادِرُونَ', 'Ve inna ala en nuriyeke ma neıduhum le kadirun.', 'Kuşkusuz onları uyardığımız şeylere seni tanık yapmaya gücümüz yeter.', 'وانا علي ان نريك ما نعدهم لقدرون'),
(2769, 23, 96, 'اِدْفَعْ بِالَّت۪ي هِيَ اَحْسَنُ السَّيِّئَةَۜ نَحْنُ اَعْلَمُ بِمَا يَصِفُونَ', 'İdfa\' billeti hiye ahsenus seyyieh, nahnu a\'lemu bi ma yasıfun.', 'Kötülüğü en iyi şekilde sav. Biz,  yakıştırmakta oldukları şeyleri çok iyi biliyoruz.', 'ادفع بالتي هي احسن السيية نحن اعلم بما يصفون'),
(2770, 23, 97, 'وَقُلْ رَبِّ اَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاط۪ينِۙ', 'Ve kul rabbi euzu bike min hemezatiş şeyatin.', 'De ki: \"Rabbim! Şeytanların etkilemelerinden Sana sığınırım.\"[1]', 'وقل رب اعوذ بك من همزت الشيطين'),
(2771, 23, 98, 'وَاَعُوذُ بِكَ رَبِّ اَنْ يَحْضُرُونِ', 'Ve euzu bike rabbi en yahdurun.', '\"Rabbim! Benimle yakınlık kurmalarından Sana sığınırım.\"', 'واعوذ بك رب ان يحضرون'),
(2772, 23, 99, 'حَتّٰٓى اِذَا جَٓاءَ اَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُونِۙ', 'Hatta iza cae ehadehumul mevtu kale rabbirciun.', 'Onlardan birine ölüm geldiği zaman,  \"Rabb\'im beni hayata geri döndür.\" der.', 'حتي اذا جا احدهم الموت قال رب ارجعون'),
(2773, 23, 100, 'لَعَلّ۪ٓي اَعْمَلُ صَالِحاً ف۪يمَا تَرَكْتُ كَلَّاۜ اِنَّهَا كَلِمَةٌ هُوَ قَٓائِلُهَاۜ وَمِنْ وَرَٓائِهِمْ بَرْزَخٌ اِلٰى يَوْمِ يُبْعَثُونَ', 'Lealli a\'melu salihan fima terektu kella, inneha kelimetun huve kailuha, ve min veraihim berzahun ila yevmi yub\'asun.', 'Böylece ihmal ettiğim salih[1] işleri yaparım. Hayır! Kuşkusuz onun söylediği kesinlikle boş bir sözden ibarettir. Onların tekrar diriltilecekleri güne kadar arkalarında[2] bir berzah[3] vardır.', 'لعلي اعمل صلحا فيما تركت كلا انها كلمة هو قايلها ومن ورايهم برزخ الي يوم يبعثون'),
(2774, 23, 101, 'فَاِذَا نُفِـخَ فِي الصُّورِ فَلَٓا اَنْسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَٓاءَلُونَ', 'Fe iza nufiha fis suri fe la ensabe beynehum yevme izin ve la yetesaelun.', 'Sura üfürüldüğü gün,  artık ailenin,  akrabanın bir yararı yoktur. Birbirlerinden soramazlar!', 'فاذا نفخ في الصور فلا انساب بينهم يوميذ ولا يتسالون'),
(2775, 23, 102, 'فَمَنْ ثَقُلَتْ مَوَاز۪ينُهُ فَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Fe men sekulet mevazinuhu fe ulaike humul muflihun.', 'Kimlerin tartısı ağır gelirse,  işte onlar kurtuluşa erenlerdir.', 'فمن ثقلت موزينه فاوليك هم المفلحون'),
(2776, 23, 103, 'وَمَنْ خَفَّتْ مَوَاز۪ينُهُ فَاُو۬لٰٓئِكَ الَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ ف۪ي جَهَنَّمَ خَالِدُونَۚ', 'Ve men haffet mevazinuhu fe ulaikellezine hasiru enfusehum fi cehenneme halidun.', 'Ve kimin tartısı hafif gelirse,  işte onlar kendilerine yazık edenlerdir; Cehennem\'de sürekli kalıcıdırlar.', 'ومن خفت موزينه فاوليك الذين خسروا انفسهم في جهنم خلدون'),
(2777, 23, 104, 'تَلْفَحُ وُجُوهَهُمُ النَّارُ وَهُمْ ف۪يهَا كَالِحُونَ', 'Telfehu vucuhehumun naru ve hum fiha kalihun.', '\"Ateş yüzlerini yalar ve onlar,  orada acıyla somurtup kalırlar.\"', 'تلفح وجوههم النار وهم فيها كلحون'),
(2778, 23, 105, 'اَلَمْ تَكُنْ اٰيَات۪ي تُتْلٰى عَلَيْكُمْ فَكُنْتُمْ بِهَا تُكَذِّبُونَ', 'E lem tekun ayati tutla aleykum fe kuntum biha tukezzibun.', 'Ayetlerim size okunduğunda; onları yalanlayanlar siz değil miydiniz?', 'الم تكن ايتي تتلي عليكم فكنتم بها تكذبون'),
(2779, 23, 106, 'قَالُوا رَبَّـنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْماً ضَٓالّ۪ينَ', 'Kalu rabbena galebet aleyna şıkvetuna ve kunna kavmen dallin.', 'Dediler ki: \"Rabb\'imiz! Azgınlığımıza yenilen sapkın bir halktık.\"', 'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين'),
(2780, 23, 107, 'رَبَّـنَٓا اَخْرِجْنَا مِنْهَا فَاِنْ عُدْنَا فَاِنَّا ظَالِمُونَ', 'Rabbena ahricna minha fe in udna fe inna zalimun.', '\"Rabbimiz! Bizi buradan çıkar. Eğer bir daha aynısını yaparsak zalim olduğumuz kesinleşmiş olur.\"', 'ربنا اخرجنا منها فان عدنا فانا ظلمون'),
(2781, 23, 108, 'قَالَ اخْسَؤُ۫ا ف۪يهَا وَلَا تُكَلِّمُونِ', 'Kalahseu fiha ve la tukellimun.', 'Dedi ki: \"Sinin orada! Ben\'den boşuna bir şey istemeyin!\"', 'قال اخسوا فيها ولا تكلمون'),
(2782, 23, 109, 'اِنَّهُ  كَانَ فَر۪يقٌ مِنْ عِبَاد۪ي يَقُولُونَ رَبَّـنَٓا اٰمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَاَنْتَ خَيْرُ الرَّاحِم۪ينَۚ', 'İnnehu kane ferikun min ibadi yekulune rabbena amenna fagfir lena verhamna ve ente hayrur rahımin.', 'Gerçek şu ki,  kimi kullarım: \"Rabb\'imiz! Biz iman ettik; bizi bağışla,  bize merhamet et,  merhametlilerin en iyisi sensin.\" diyorlardı.', 'انه كان فريق من عبادي يقولون ربنا امنا فاغفر لنا وارحمنا وانت خير الرحمين'),
(2783, 23, 110, 'فَاتَّخَذْتُمُوهُمْ سِخْرِياًّ حَتّٰٓى اَنْسَوْكُمْ ذِكْر۪ي وَكُنْتُمْ مِنْهُمْ تَضْحَكُونَ', 'Fettehaztumuhum sıhriyyen hatta ensevkum zikri ve kuntum minhum tadhakun.', '\"Siz ise onları alaya aldınız; öyle ki Benim öğütlerimi kulak ardı ettiniz. Onların haline gülüyordunuz.\"', 'فاتخذتموهم سخريا حتي انسوكم ذكري وكنتم منهم تضحكون'),
(2784, 23, 111, 'اِنّ۪ي جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُٓواۙ اَنَّهُمْ هُمُ الْفَٓائِزُونَ', 'İnni cezeytuhumul yevme bima saberu ennehum humul faizun.', '\"Gerçek şu ki,  bugün onlara sabretmelerinin karşılığını verdim. Onlar kazançlı çıkanlardır.\"', 'اني جزيتهم اليوم بما صبروا انهم هم الفايزون'),
(2785, 23, 112, 'قَالَ كَمْ لَبِثْتُمْ فِي الْاَرْضِ عَدَدَ سِن۪ينَ', 'Kale kem lebistum fil ardı adede sinin.', 'Allah: \"Yeryüzünde kaç yıl kaldınız?\" dedi.', 'قال كم لبثتم في الارض عدد سنين'),
(2786, 23, 113, 'قَالُوا لَبِثْنَا يَوْماً اَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ الْعَٓادّ۪ينَ', 'Kalu lebisna yevmen ev ba\'da yevmin fes\'elil addin.', '\"Bir gün veya günün bir kısmı kadar kaldık. Hesabını tutanlara sor!\" dediler.', 'قالوا لبثنا يوما او بعض يوم فسل العادين'),
(2787, 23, 114, 'قَالَ اِنْ لَبِثْتُمْ اِلَّا قَل۪يلاً لَوْ اَنَّكُمْ كُنْتُمْ تَعْلَمُونَ', 'Kale in lebistum illa kalilen lev ennekum kuntum ta\'lemun.', '\"Sadece az bir süre kaldınız. Keşke o zaman bunu kavramış olsaydınız.\" dedi.', 'قال ان لبثتم الا قليلا لو انكم كنتم تعلمون'),
(2788, 23, 115, 'اَفَحَسِبْتُمْ اَنَّمَا خَلَقْنَاكُمْ عَبَثاً وَاَنَّكُمْ اِلَيْنَا لَا تُرْجَعُونَ', 'E fe hasibtum ennema halaknakum abesen ve ennekum ileyna la turceun.', '\"Yoksa sizi boş yere yarattığımızı ve Bize döndürülmeyeceğinizi mi sandınız?\"', 'افحسبتم انما خلقنكم عبثا وانكم الينا لا ترجعون'),
(2789, 23, 116, 'فَتَعَالَى اللّٰهُ الْمَلِكُ الْحَقُّۚ   لَٓا اِلٰهَ اِلَّا هُوَۚ رَبُّ الْعَرْشِ الْكَر۪يمِ', 'Fe tealallahul melikul hakk, la ilahe illa hu, rabbul arşil kerim.', '\"Şunu bilin ki,  gerçek egemenlik sahibi olan Allah,  çok yücedir. O\'ndan başka ilah yoktur. O şerefli arşın[1] Rabb\'idir.\"', 'فتعلي الله الملك الحق لا اله الا هو رب العرش الكريم'),
(2790, 23, 117, 'وَمَنْ يَدْعُ مَعَ اللّٰهِ اِلٰهاً اٰخَرَۙ   لَا بُرْهَانَ لَهُ بِه۪ۙ فَاِنَّمَا حِسَابُهُ عِنْدَ رَبِّه۪ۜ اِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ', 'Ve men yed\'u maallahi ilahen ahare la burhane lehu bihi fe innema hısabuhu inde rabbih, innehu la yuflihul kafirun.', 'Her kim,  hakkında hiçbir burhan[1] olmadığı halde,  Allah\'ın yanı sıra başka bir ilahtan istekte bulunursa,  bilsin ki onun hesabı yalnızca Rabb\'ine aittir. Kuşku yok ki Kafirler kurtuluşa eremezler.', 'ومن يدع مع الله الها اخر لا برهن له به فانما حسابه عند ربه انه لا يفلح الكفرون'),
(2791, 23, 118, 'وَقُلْ رَبِّ اغْفِرْ وَارْحَمْ وَاَنْتَ خَيْرُ الرَّاحِم۪ينَ', 'Ve kul rabbigfir verham ve ente hayrur rahımin.', 'Ve de ki: \"Rabbim! Bağışla ve merhamet et. Sen merhametlilerin en hayırlısısın.\"', 'وقل رب اغفر وارحم وانت خير الرحمين'),
(2792, 24, 1, 'سُورَةٌ اَنْزَلْنَاهَا وَفَرَضْنَاهَا وَاَنْزَلْنَا ف۪يهَٓا اٰيَاتٍ بَيِّنَاتٍ لَعَلَّكُمْ تَذَكَّرُونَ', 'Suratun enzelnaha ve faradnaha ve enzelna fiha ayatin beyyinatin leallekum tezekkerun.', 'Bu indirip,  farz kıldığımız[1] bir suredir. Onda beyyinat[1] ayetler ortaya koyduk. Umulur ki öğüt alırsınız.', 'سورة انزلنها وفرضنها وانزلنا فيها ايت بينت لعلكم تذكرون'),
(2793, 24, 2, 'اَلزَّانِيَةُ وَالزَّان۪ي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍۖ وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ ف۪ي د۪ينِ اللّٰهِ اِنْ كُنْتُمْ تُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۚ وَلْيَشْهَدْ عَذَابَهُمَا طَٓائِفَةٌ مِنَ الْمُؤْمِن۪ينَ', 'Ez zaniyetu vez zani feclidu kulle vahıdin min huma miete celdetin ve la te\'huzkum bi hima ra\'fetun fi dinillahi in kuntum tu\'minune billahi vel yevmil ahır, vel yeşhed azabehuma taifetun minel mu\'minin.', 'Zina yapan kadın ve zina[1] yapan erkeğin her birine yüzer sopa vurun. Allah\'a ve Ahiret Günü\'ne inanıyorsanız,  onlara karşı duyduğunuz acıma duygusu sizi Allah\'ın bu yasasını uygulamaktan alıkoymasın. Mü\'minlerden bir grup da buna tanık olsun.', 'الزانية والزاني فاجلدوا كل وحد منهما ماية جلدة ولا تاخذكم بهما رافة في دين الله ان كنتم تومنون بالله واليوم الاخر وليشهد عذابهما طايفة من المومنين'),
(2794, 24, 3, 'اَلزَّان۪ي لَا يَنْكِحُ اِلَّا زَانِيَةً اَوْ مُشْرِكَةًۘ وَالزَّانِيَةُ لَا يَنْكِحُهَٓا اِلَّا زَانٍ اَوْ مُشْرِكٌۚ وَحُرِّمَ ذٰلِكَ عَلَى الْمُؤْمِن۪ينَ', 'Ez zani la yenkihu illa zaniyeten ev muşriketen vez zaniyetu la yenkihuha illa zanin ev muşrik, ve hurrime zalike alel mu\'minin.', 'Zina yapan erkek,  zina yapan veya müşrik olan kadından başkası ile evlenmiyor. Zina yapan kadınla zina yapan veya müşrik olan bir erkekten başkası evlenmiyor. Bu uygulama mü\'minlere haram kılındı.[1]', 'الزاني لا ينكح الا زانية او مشركة والزانية لا ينكحها الا زان او مشرك وحرم ذلك علي المومنين'),
(2795, 24, 4, 'وَالَّذ۪ينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِاَرْبَعَةِ شُهَدَٓاءَ فَاجْلِدُوهُمْ ثَمَان۪ينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً اَبَداًۚ وَاُو۬لٰٓئِكَ هُمُ الْفَاسِقُونَۙ', 'Vellezine yermunel muhsanati summe lem ye\'tu bi erbeati şuhedae fecliduhum semanine celdeten ve la takbelu lehum şehadeten ebeda, ve ulaike humul fasikun.', 'Ve muhsan[1] kadınlara iftira edip de sonra dört tanık getiremeyen kimselere seksen sopa vurun. Ve onların tanıklığını ebediyen kabul etmeyin. Onlar fasıktırlar[2].', 'والذين يرمون المحصنت ثم لم ياتوا باربعة شهدا فاجلدوهم ثمنين جلدة ولا تقبلوا لهم شهدة ابدا واوليك هم الفسقون'),
(2796, 24, 5, 'اِلَّا الَّذ۪ينَ تَابُوا مِنْ بَعْدِ ذٰلِكَ وَاَصْلَحُواۚ فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İllellezine tabu min ba\'di zalike ve aslehu, fe innallahe gafurun rahim.', 'Fakat bundan sonra tevbe eden ve kendilerini düzelten kimseler hariç. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم'),
(2797, 24, 6, 'وَالَّذ۪ينَ يَرْمُونَ اَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَٓاءُ اِلَّٓا اَنْفُسُهُمْ فَشَهَادَةُ اَحَدِهِمْ اَرْبَعُ شَهَادَاتٍ بِاللّٰهِۙ اِنَّهُ لَمِنَ الصَّادِق۪ينَ', 'Vellezine yermune ezvacehum ve lem yekun lehum şuhedau illa enfusuhum fe şehadetu ehadihim erbeu şehadatin billahi innehu le mines sadıkin.', 'Eşlerine iftira atanlar,  kendilerinden başka tanıkları yoksa o zaman onların her birinin tanıklığı,  kendisinin doğru söyleyenlerden olduğuna dair dört defa Allah\'ı tanık tutmasıdır.', 'والذين يرمون ازوجهم ولم يكن لهم شهدا الا انفسهم فشهدة احدهم اربع شهدت بالله انه لمن الصدقين'),
(2798, 24, 7, 'وَالْخَامِسَةُ اَنَّ لَعْنَتَ اللّٰهِ عَلَيْهِ اِنْ  كَانَ مِنَ الْكَاذِب۪ينَ', 'Vel hamisetu enne la\'netallahi aleyhi in kane minel kazibin.', 'Beşincide de eğer yalan söyleyenlerden ise,  Allah\'ın lanetinin[1] kendisi üzerine olmasını dilemesidir.', 'والخامسة ان لعنت الله عليه ان كان من الكذبين'),
(2799, 24, 8, 'وَيَدْرَؤُ۬ا عَنْهَا الْعَذَابَ اَنْ تَشْهَدَ اَرْبَعَ شَهَادَاتٍ بِاللّٰهِۙ اِنَّهُ لَمِنَ الْكَاذِب۪ينَۙ', 'Ve yedrau anhel azabe en teşhede erbea şehadatin billahi innehu le minel kazibin.', 'Kadının,  dört kez \"Billahi o kesinlikle yalancıdır.\" şeklinde sözüne Allah\'ı tanık etmesi ondan cezayı kaldırır.', 'ويدروا عنها العذاب ان تشهد اربع شهدت بالله انه لمن الكذبين'),
(2800, 24, 9, 'وَالْخَامِسَةَ اَنَّ غَضَبَ اللّٰهِ عَلَيْهَٓا اِنْ  كَانَ مِنَ الصَّادِق۪ينَ', 'Vel hamisete enne gadaballahi aleyha in kane mines sadikin.', 'Ve beşinci kez eğer o doğru söyleyenlerden ise Allah\'ın gazabının kendisinin üzerine olmasını diler.', 'والخمسة ان غضب الله عليها ان كان من الصدقين'),
(2801, 24, 10, 'وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ وَاَنَّ اللّٰهَ تَـوَّابٌ حَك۪يمٌ۟', 'Ve lev la fadlullahi aleykum ve rahmetuhu ve ennellahe tevvabun hakim.', 'Ya üzerinizde,  Allah\'ın lütuf ve rahmeti olmasaydı! Allah,  tevbeleri[1] Kabul Eden\'dir,  En İyi Hüküm Verendir.', 'ولولا فضل الله عليكم ورحمته وان الله تواب حكيم'),
(2802, 24, 11, 'اِنَّ الَّذ۪ينَ جَٓاؤُ۫ بِالْاِفْكِ عُصْبَةٌ مِنْكُمْۜ  لَا تَحْسَبُوهُ شَراًّ لَكُمْۜ بَلْ هُوَ خَيْرٌ لَكُمْۜ لِكُلِّ امْرِئٍ مِنْهُمْ مَا اكْتَسَبَ مِنَ الْاِثْمِۚ وَالَّذ۪ي تَوَلّٰى كِبْرَهُ مِنْهُمْ لَهُ عَذَابٌ عَظ۪يمٌ', 'İnnellezine cau bil ifki usbetun minkum, la tahsebuhu şerren lekum, bel huve hayrun lekum, li kullimriin minhum mektesebe minel ism, vellezi tevella kibrehu minhum lehu azabun azim.', 'Bu ifk\'i[1] yapanlar içinizden birileridir. Sizin için bunun bir şer olduğunu sanmayın. Aksine bu sizin için bir hayırdır. Onlardan her birine günahtan bir pay vardır. İçlerinden önderlik yapıp bunu organize eden kimse için de çok büyük bir azap vardır.', 'ان الذين جاو بالافك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امري منهم ما اكتسب من الاثم والذي تولي كبره منهم له عذاب عظيم'),
(2803, 24, 12, 'لَوْلَٓا اِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِاَنْفُسِهِمْ خَيْراًۙ وَقَالُوا هٰذَٓا اِفْكٌ مُب۪ينٌ', 'Lev la iz semi\'tumuhu zannel mu\'minune vel mu\'minatu bi enfusihim hayran ve kalu haza ifkun mubin.', 'Mü\'min erkeklerin ve Mü\'min kadınların onu işittikleri zaman,  iyi zan[1] ile \"Bu apaçık iftiradır.\" demeleri gerekmez miydi?', 'لولا اذ سمعتموه ظن المومنون والمومنت بانفسهم خيرا وقالوا هذا افك مبين'),
(2804, 24, 13, 'لَوْلَا جَٓاؤُ۫ عَلَيْهِ بِاَرْبَعَةِ شُهَدَٓاءَۚ  فَاِذْ لَمْ يَأْتُوا بِالشُّهَدَٓاءِ فَاُو۬لٰٓئِكَ عِنْدَ اللّٰهِ هُمُ الْكَاذِبُونَ', 'Lev la cau aleyhi bi erbeati şuheda, fe iz lem ye\'tu biş şuhedai fe ulaike indellahi humul kazibun.', 'İddialarına dört tanık getirmeleri gerekmez miydi? Tanık getiremediklerine göre onlar Allah\'ın yanında yalancıdırlar.', 'لولا جاو عليه باربعة شهدا فاذ لم ياتوا بالشهدا فاوليك عند الله هم الكذبون'),
(2805, 24, 14, 'وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ فِي الدُّنْيَا وَالْاٰخِرَةِ لَمَسَّكُمْ ف۪ي مَٓا اَفَضْتُمْ ف۪يهِ عَذَابٌ عَظ۪يمٌۚ', 'Ve lev la fadlullahi aleykum ve rahmetuhu fid dunya vel ahırati le messekum fi ma efadtum fihi azabun azim.', 'Eğer dünyada ve ahirette Allah\'ın lütuf ve rahmeti sizin üzerinize olmasaydı,  içine düştüğünüz şeyden dolayı size kesinlikle büyük bir azap dokunurdu.', 'ولولا فضل الله عليكم ورحمته في الدنيا والاخرة لمسكم في ما افضتم فيه عذاب عظيم'),
(2806, 24, 15, 'اِذْ تَلَقَّوْنَهُ بِاَلْسِنَتِكُمْ وَتَقُولُونَ بِاَفْوَاهِكُمْ مَا لَيْسَ لَكُمْ بِه۪ عِلْمٌ وَتَحْسَبُونَهُ هَيِّناًۗ وَهُوَ عِنْدَ اللّٰهِ عَظ۪يمٌ', 'İz telakkavnehu bi elsinetikum ve tekulune bi efvahikum ma leyse lekum bihi ilmun ve tahsebunehu heyyinen ve huve indallahi azim.', 'Hani siz onu dillerinize dolayıp,  kendisi hakkında bilgi sahibi olmadığınız şeyi aranızda yayıyordunuz. Ve bunun önemsiz olduğunu sanıyordunuz. Oysaki bunun Allah\'ın yanında önemi çok büyüktür.', 'اذ تلقونه بالسنتكم وتقولون بافواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم'),
(2807, 24, 16, 'وَلَوْلَٓا اِذْ سَمِعْتُمُوهُ قُلْتُمْ مَا يَكُونُ لَـنَٓا اَنْ نَتَكَلَّمَ بِهٰذَاۗ سُبْحَانَكَ هٰذَا بُهْتَانٌ عَظ۪يمٌ', 'Ve lev la iz semi\'tumuhu kultum ma yekunu lena en netekelleme bi haza subhaneke haza buhtanun azim.', 'Ve onu duyduğunuz zaman: \"Bunu konuşmamız bize yakışmaz. Seni tenzih ederiz! Bu büyük bir iftiradır.\" demeniz gerekmez miydi?', 'ولولا اذ سمعتموه قلتم ما يكون لنا ان نتكلم بهذا سبحنك هذا بهتن عظيم'),
(2808, 24, 17, 'يَعِظُكُمُ اللّٰهُ اَنْ تَعُودُوا لِمِثْلِه۪ٓ اَبَداً اِنْ كُنْتُمْ مُؤْمِن۪ينَۚ', 'Yeızukumullahu en teudu li mislihi ebeden in kuntum mu\'minin.', 'Allah size öğüt veriyor: Eğer iman etmiş kimselerseniz,  böyle bir şeyi yapmayı ebediyen yasaklıyor.', 'يعظكم الله ان تعودوا لمثله ابدا ان كنتم مومنين'),
(2809, 24, 18, 'وَيُبَيِّنُ اللّٰهُ لَكُمُ الْاٰيَاتِۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ve yubeyyinullahu lekumul ayat, vallahu alimun hakim.', 'Allah,  size ayetlerini beyan[1] ediyor. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'ويبين الله لكم الايت والله عليم حكيم'),
(2810, 24, 19, 'اِنَّ الَّذ۪ينَ يُحِبُّونَ اَنْ تَش۪يعَ الْفَاحِشَةُ فِي الَّذ۪ينَ اٰمَنُوا لَهُمْ عَذَابٌ اَل۪يمٌۙ فِي الدُّنْيَا وَالْاٰخِرَةِۜ وَاللّٰهُ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُونَ', 'İnnellezine yuhıbbune en teşial fahışetu fillezine amenu lehum azabun elimun fid dunya vel ahırah, vallahu ya\'lemu ve entum la ta\'lemun.', 'İnananlar arasında,  fahişenin[1] yayılmasından hoşlananlara dünya ve ahirette acı bir azap vardır. Allah bilir,  siz bilmezsiniz.', 'ان الذين يحبون ان تشيع الفحشة في الذين امنوا لهم عذاب اليم في الدنيا والاخرة والله يعلم وانتم لا تعلمون'),
(2811, 24, 20, 'وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ وَاَنَّ اللّٰهَ رَؤُ۫فٌ رَح۪يمٌ۟', 'Ve lev la fadlullahi aleykum ve rahmetuhu ve ennallahe raufun rahim.', 'Eğer Allah\'ın lütuf ve rahmeti üzerinizde olmasaydı![1] Allah,  Çok Şefkatli\'dir. Rahmeti Kesintisiz\'dir.', 'ولولا فضل الله عليكم ورحمته وان الله روف رحيم'),
(2812, 24, 21, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِۜ وَمَنْ يَتَّبِـعْ خُطُوَاتِ الشَّيْطَانِ فَاِنَّهُ يَأْمُرُ بِالْفَحْشَٓاءِ وَالْمُنْكَرِۜ وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكٰى مِنْكُمْ مِنْ اَحَدٍ اَبَداًۙ وَلٰكِنَّ اللّٰهَ يُزَكّ۪ي مَنْ يَشَٓاءُۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'Ya eyyuhellezine amenu la tettebiu hutuvatiş şeytan, ve men yettebi\' hutuvatiş şeytani fe innehu ye\'muru bil fahşai vel munker ve lev la fadlullahi aleykum ve rahmetuhu ma zeka minkum min ehadin ebeden ve lakinnallahe yuzekki men yeşau, vallahu semi\'un alim.', 'Ey iman edenler! Şeytanın[1] adımlarını takip etmeyin. Kim şeytanın adımlarını izlerse şunu bilsin ki şeytan,  her türlü aşırılığı ve her türlü çirkinliği telkin eder. Ve eğer Allah\'ın üzerinizdeki lütuf ve rahmeti olmasaydı sizden hiç kimse arınmayı asla başaramazdı. Fakat Allah hak edeni[2] arındırır. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'يايها الذين امنوا لا تتبعوا خطوت الشيطن ومن يتبع خطوت الشيطن فانه يامر بالفحشا والمنكر ولولا فضل الله عليكم ورحمته ما زكي منكم من احد ابدا ولكن الله يزكي من يشا والله سميع عليم'),
(2813, 24, 22, 'وَلَا يَأْتَلِ اُو۬لُوا الْفَضْلِ مِنْكُمْ وَالسَّعَةِ اَنْ يُؤْتُٓوا اُو۬لِي الْقُرْبٰى وَالْمَسَاك۪ينَ وَالْمُهَاجِر۪ينَ ف۪ي سَب۪يلِ اللّٰهِۖ وَلْيَعْفُوا وَلْيَصْفَحُواۜ اَلَا تُحِبُّونَ اَنْ يَغْفِرَ اللّٰهُ لَكُمْۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Ve la ye\'teli ulul fadlı minkum ves seati en yu\'tu ulil kurba vel mesakine vel muhacirine fi sebilillah, vel ya\'fu vel yasfehu, e la tuhıbbune en yagfirallahu lekum, vallahu gafurun rahim.', 'Sizden fazilet[1] ve varlık sahibi olanlar,  yakınlarına,  miskinlere,  Allah yolunda hicret edenlere yardım etmeme konusunda yemin etmesinler. Ve artık bağışlayıp hoş görsünler. Allah\'ın sizi bağışlamasından mutlu olmaz mısınız? Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ولا ياتل اولوا الفضل منكم والسعة ان يوتوا اولي القربي والمسكين والمهجرين في سبيل الله وليعفوا وليصفحوا الا تحبون ان يغفر الله لكم والله غفور رحيم'),
(2814, 24, 23, 'اِنَّ الَّذ۪ينَ يَرْمُونَ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ لُعِنُوا فِي الدُّنْيَا وَالْاٰخِرَةِۖ وَلَهُمْ عَذَابٌ عَظ۪يمٌۙ', 'İnnellezine yermunel muhsanatil gafilatil mu\'minati luınu fid dunya vel ahırati ve lehum azabun azim.', 'Hiçbir şeyden haberi olmadığı halde muhsan[1] mü\'min kadınlara iftira atan kimseler dünya ve ahirette lanetlenmişlerdir. Ve onlar için büyük bir azap vardır.', 'ان الذين يرمون المحصنت الغفلت المومنت لعنوا في الدنيا والاخرة ولهم عذاب عظيم'),
(2815, 24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ اَلْسِنَتُهُمْ وَاَيْد۪يهِمْ وَاَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ', 'Yevme teşhedu aleyhim elsinetuhum ve eydihim ve erculuhum bima kanu ya\'melun.', 'O gün dilleri,  elleri ve ayakları yaptıklarına tanıklık edecektir.', 'يوم تشهد عليهم السنتهم وايديهم وارجلهم بما كانوا يعملون'),
(2816, 24, 25, 'يَوْمَئِذٍ يُوَفّ۪يهِمُ اللّٰهُ د۪ينَهُمُ الْحَقَّ وَيَعْلَمُونَ اَنَّ اللّٰهَ هُوَ الْحَقُّ الْمُب۪ينُ', 'Yevme izin yuveffihimullahu dinehumul hakka ve ya\'lemune ennallahe huvel hakkul mubin.', 'O gün Allah,  onların hesaplarını hakkıyla görecektir. Onlar da Allah\'ın Hakk\'ın ta kendisi olduğunu apaçık bileceklerdir.', 'يوميذ يوفيهم الله دينهم الحق ويعلمون ان الله هو الحق المبين'),
(2817, 24, 26, 'اَلْخَب۪يثَاتُ لِلْخَب۪يث۪ينَ وَالْخَب۪يثُونَ لِلْخَب۪يثَاتِۚ وَالطَّيِّبَاتُ لِلطَّيِّب۪ينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِۚ اُو۬لٰٓئِكَ مُبَرَّؤُ۫نَ مِمَّا يَقُولُونَۜ  لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَر۪يمٌ۟', 'El habisatu lil habisine vel habisune lil habisat, vet tayyibatu lit tayyibine vet tayyibune lit tayyibat, ulaike muberraune mimma yekulun, lehum magfiretun ve rızkun kerim.', 'Habis[1] kadınlar habis erkeklere,  habis erkekler habis kadınlara yakışır. Tayyib[2] kadınlar tayyib erkeklere,  tayyib erkekler de tayyib kadınlara yakışır. Bunlar,  söylenenlerden uzak olanlardır. Onlar için bağışlanma ve cömertçe rızık vardır.', 'الخبيثت للخبيثين والخبيثون للخبيثت والطيبت للطيبين والطيبون للطيبت اوليك مبرون مما يقولون لهم مغفرة ورزق كريم'),
(2818, 24, 27, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَدْخُلُوا بُيُوتاً غَيْرَ بُيُوتِكُمْ حَتّٰى تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلٰٓى اَهْلِهَاۜ ذٰلِكُمْ خَيْرٌ لَكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'Ya eyyuhellezine amenu la tedhulu buyuten gayra buyutikum hatta teste\'nisu ve tusellimu ala ehliha, zalikum hayrun lekum leallekum tezekkerun.', 'Ey iman edenler! Kendi evinizden başka evlere,  sahiplerinin sizi istekle karşılayacaklarından emin olmadan ve selam vermeden[1] girmeyin. Bu sizin için daha hayırlıdır. Umulur ki öğüt alırsınız.', 'يايها الذين امنوا لا تدخلوا بيوتا غير بيوتكم حتي تستانسوا وتسلموا علي اهلها ذلكم خير لكم لعلكم تذكرون'),
(2819, 24, 28, 'فَاِنْ لَمْ تَجِدُوا ف۪يهَٓا اَحَداً فَلَا تَدْخُلُوهَا حَتّٰى يُؤْذَنَ لَكُمْۚ وَاِنْ ق۪يلَ لَكُمُ ارْجِعُوا فَارْجِعُوا هُوَ اَزْكٰى لَكُمْۜ وَاللّٰهُ بِمَا تَعْمَلُونَ عَل۪يمٌ', 'Fe in lem tecidu fiha ehaden fe la tedhuluha hatta yu\'zene lekum ve in kile lekumurciu ferciu huve ezka lekum, vallahu bima ta\'melune alim.', 'Eğer orada kimseyi bulamazsanız,  size izin verilinceye kadar oraya girmeyin. Eğer geri dönmeniz istenirse hemen geri dönün. Bu sizin için daha nezihtir.[1] Allah yaptığınız şeyi hangi amaçla yaptığınızdan haberdardır.', 'فان لم تجدوا فيها احدا فلا تدخلوها حتي يوذن لكم وان قيل لكم ارجعوا فارجعوا هو ازكي لكم والله بما تعملون عليم'),
(2820, 24, 29, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَدْخُلُوا بُيُوتاً غَيْرَ مَسْكُونَةٍ ف۪يهَا مَتَاعٌ لَكُمْۜ وَاللّٰهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'Leyse aleykum cunahun en tedhulu buyuten gayre meskunetin fiha metaun lekum, vallahu ya\'lemu ma tubdune ve ma tektumun.', 'Oturulmayan ama yararlanmak için kullanılan yerlere girmenizde bir sakınca yoktur. Allah,  sizin açığa vurduğunuz şeyleri de gizlediğiniz şeyleri de bilir.', 'ليس عليكم جناح ان تدخلوا بيوتا غير مسكونة فيها متع لكم والله يعلم ما تبدون وما تكتمون'),
(2821, 24, 30, 'قُلْ لِلْمُؤْمِن۪ينَ يَغُضُّوا مِنْ اَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْۜ ذٰلِكَ اَزْكٰى لَهُمْۜ اِنَّ اللّٰهَ خَب۪يرٌ بِمَا يَصْنَعُونَ', 'Kul lil mu\'minine yaguddu min ebsarihim ve yahfezu furucehum, zalike ezka lehum, innellahe habirun bima yasneun.', 'Mü\'min erkeklere söyle,  bakışlarından bir kısmını[1] sakınsınlar ve ırzlarını[2] korusunlar. Bu onlar için daha arınmış çadır. Allah,  davranışlarından haberdardır.', 'قل للمومنين يغضوا من ابصرهم ويحفظوا فروجهم ذلك ازكي لهم ان الله خبير بما يصنعون'),
(2822, 24, 31, 'وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ اَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْد۪ينَ ز۪ينَتَهُنَّ اِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُيُوبِهِنَّۖ وَلَا يُبْد۪ينَ ز۪ينَتَهُنَّ اِلَّا لِبُعُولَتِهِنَّ اَوْ اٰبَٓائِهِنَّ اَوْ اٰبَٓاءِ بُعُولَتِهِنَّ اَوْ اَبْنَٓائِهِنَّ اَوْ اَبْنَٓاءِ بُعُولَتِهِنَّ اَوْ اِخْوَانِهِنَّ اَوْ بَن۪ٓي اِخْوَانِهِنَّ اَوْ بَن۪ٓي اَخَوَاتِهِنَّ اَوْ نِسَٓائِهِنَّ اَوْ مَا مَلَكَتْ اَيْمَانُهُنَّ اَوِ التَّابِع۪ينَ غَيْرِ اُو۬لِي الْاِرْبَةِ مِنَ الرِّجَالِ اَوِ الطِّفْلِ الَّذ۪ينَ لَمْ يَظْهَرُوا عَلٰى عَوْرَاتِ النِّسَٓاءِۖ وَلَا يَضْرِبْنَ بِاَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْف۪ينَ مِنْ ز۪ينَتِهِنَّۜ وَتُوبُٓوا اِلَى اللّٰهِ جَم۪يعاً اَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', 'Ve kul lil mu\'minati yagdudne min ebsarihinne ve yahfazne furucehunne, ve la yubdine zinetehunneilla ma zahera minha, vel yadribne bi humurihinne ala cuyubihinne, ve la yubdine zinetehunne illa li buuletihinne ev abaihinne ev abai buuletihinne ev ebnaihinne ev ebnai buuletihinne ev ıhvanihinne ev beni ıhvanihinne ev beni ehavatihinne ev nisaihinne ev ma meleket eymanuhunne evit tabiine gayri ulil irbeti miner ricali evit tıflillezine lem yazharu ala avratin nisai, ve la yadribne bi erculihinne li yu\'leme ma yuhfine min zinetihinn, ve tubu ilallahi cemian eyyuhel mu\'minune leallekum tuflihun.', 'Ve de Mü\'min kadınlara söyle,  bakışlarından bir kısmını sakınsınlar[1],  ırzlarını[2] korusunlar. Doğal olarak görünmesi gerekli olanlar dışında,  ziynetlerini[3] açığa vurmasınlar[4]. Örtüleri ile göğüslerini örtsünler[5]. Ziynetlerini; kocaları,  babaları,  kocalarının babaları,  oğulları,  kocalarının oğulları,  erkek kardeşleri,  erkek kardeşlerinin oğulları,  kız kardeşlerinin oğulları,  kadınların tamamı,  yeminle sahip oldukları[6],  kadına ihtiyaç duymayan erkek hizmetliler,  kadınların avret yerlerinin[7] henüz farkında olamayan çocuklar hariç,  açığa vurmasınlar. Korudukları ziynetleri bilinsin diye,  ayaklarını vurmasınlar[8]. Ey mü\'minler! Hepiniz topluca Allah\'a tevbe edin. Umulur ki kurtuluşa erersiniz.', 'وقل للمومنت يغضضن من ابصرهن ويحفظن فروجهن ولا يبدين زينتهن الا ما ظهر منها وليضربن بخمرهن علي جيوبهن ولا يبدين زينتهن الا لبعولتهن او ابايهن او ابا بعولتهن او ابنايهن او ابنا بعولتهن او اخونهن او بني اخونهن او بني اخوتهن او نسايهن او ما ملكت ايمنهن او التبعين غير اولي الاربة من الرجال او الطفل الذين لم يظهروا علي عورت النسا ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن وتوبوا الي الله جميعا ايه المومنون لعلكم تفلحون'),
(2823, 24, 32, 'وَاَنْكِحُوا الْاَيَامٰى مِنْكُمْ وَالصَّالِح۪ينَ مِنْ عِبَادِكُمْ وَاِمَٓائِكُمْۜ اِنْ يَكُونُوا فُقَـرَٓاءَ يُغْنِهِمُ اللّٰهُ مِنْ فَضْلِه۪ۜ  وَاللّٰهُ وَاسِعٌ عَل۪يمٌ', 'Ve enkihul eyama minkum ves salihine min ibadikum ve imaikum, in yekunu fukarae yugnihimullahu min fadlih, vallahu vasiun alim.', 'Aranızdaki bekarları,  kölelerinizden ve cariyelerinizden salih[1] olanları nikahlayın[2]. Eğer bunların durumları iyi değilse,  Allah onlara lütufta bulunur. Allah,  Yardımı Çok Kapsamlı Olan\'dır,  Her Şeyi Bilen\'dir.', 'وانكحوا الايمي منكم والصلحين من عبادكم وامايكم ان يكونوا فقرا يغنهم الله من فضله والله وسع عليم'),
(2824, 24, 33, 'وَلْيَسْتَعْفِفِ الَّذ۪ينَ لَا يَجِدُونَ نِكَاحاً حَتّٰى يُغْنِيَهُمُ اللّٰهُ مِنْ فَضْلِه۪ۜ وَالَّذ۪ينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ اَيْمَانُكُمْ فَكَاتِبُوهُمْ اِنْ عَلِمْتُمْ ف۪يهِمْ خَيْراًۗ وَاٰتُوهُمْ مِنْ مَالِ اللّٰهِ الَّـذ۪ٓي اٰتٰيكُمْۜ وَلَا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَٓاءِ اِنْ اَرَدْنَ تَحَصُّناً لِتَبْتَغُوا عَرَضَ الْحَيٰوةِ الدُّنْيَاۜ وَمَنْ يُكْرِهْهُنَّ فَاِنَّ اللّٰهَ مِنْ بَعْدِ اِكْرَاهِهِنَّ غَفُورٌ رَح۪يمٌ', 'Velyesta\'fifillezine la yecidune nikahan hatta yugniyehumullahu min fadlih, vellezine yebtegunel kitabe mimma meleket eymanukum fe katibuhum in alimtum fihim hayren, ve atuhum min malillahillezi atakum, ve la tukrihu feteyatikum alel bigai in eradne tehassunen li tebtegu aradal hayatid dunya ve men yukrıhhunne fe innellahe min ba\'di ikrahihinne gafurun rahim.', 'Nikaha[1] imkan bulamayanlar iffetlerini korusunlar. Allah lütfedip kendilerine bir imkan verinceye dek. Yeminle hak sahibi olduklarınızdan[2] mukatebe[3] yapmak isteyenlerle hemen antlaşma yapın. Eğer iyi niyetli olduklarını biliyorsanız.[4] Ve Allah\'ın size verdiği mallardan onlara verin. İffetli kalmak isteyen gençleri taşkınlığa zorlamayın; basit dünya hayatının geçici çıkarı için. Kim onları zorlarsa,  bilsin ki Allah,  onların zorlanmalarından dolayı onlara karşı Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.[5]', 'وليستعفف الذين لا يجدون نكاحا حتي يغنيهم الله من فضله والذين يبتغون الكتب مما ملكت ايمنكم فكاتبوهم ان علمتم فيهم خيرا واتوهم من مال الله الذي اتيكم ولا تكرهوا فتيتكم علي البغا ان اردن تحصنا لتبتغوا عرض الحيوة الدنيا ومن يكرههن فان الله من بعد اكرههن غفور رحيم'),
(2825, 24, 34, 'وَلَقَدْ اَنْزَلْـنَٓا اِلَيْكُمْ اٰيَاتٍ مُبَيِّنَاتٍ وَمَثَلاً مِنَ الَّذ۪ينَ خَلَوْا مِنْ قَبْلِكُمْ وَمَوْعِظَةً لِلْمُتَّق۪ينَ۟', 'Ve lekad enzelna ileykum ayatin mubeyyinatin ve meselen minellezine halev min kablikum ve mev\'izaten lil muttekin.', 'Ve ant olsun ki size gerçeği apaçık gösteren ayetler,  sizden önce yaşamış olan kuşaklardan örnekler ve takva sahipleri için bir vaaz[1] indirdik.', 'ولقد انزلنا اليكم ايت مبينت ومثلا من الذين خلوا من قبلكم وموعظة للمتقين'),
(2826, 24, 35, 'اَللّٰهُ نُورُ السَّمٰوَاتِ وَالْاَرْضِۜ مَثَلُ نُورِه۪ كَمِشْكٰوةٍ ف۪يهَا مِصْبَاحٌۜ  اَلْمِصْبَاحُ ف۪ي زُجَاجَةٍۜ اَلزُّجَاجَةُ  كَاَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِنْ شَجَرَةٍ مُبَارَكَةٍ زَيْتُونَةٍ لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍۙ يَكَادُ زَيْتُهَا يُض۪ٓيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌۜ  نُورٌ عَلٰى نُورٍۜ يَهْدِي اللّٰهُ لِنُورِه۪ مَنْ يَشَٓاءُۜ وَيَضْرِبُ اللّٰهُ الْاَمْثَالَ لِلنَّاسِۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌۙ', 'Allahu nurus semavati vel ard, meselu nurihi ke mişkatin fiha mısbah, el mısbahu fi zucaceh, ez zucacetu ke enneha kevkebun durriyyun, yukadu min şeceratin mubaraketin zeytunetin la şarkiyetin ve la garbiyyetin, yekadu zeytuha yudiu ve lev lem temseshu nar, nurun ala nur, yehdillahu li nurihi men yeşau, ve yadribullahul emsale lin nas, vallahu bi kulli şey\'in alim.', 'Allah,  göklerin ve yeryüzünün aydınlığıdır.[1] O\'nun aydınlığı,  içinde ışık bulunan kandil yuvası gibidir. O kandil,  bir fanus içindedir. O fanus,  inciden bir yıldız gibidir. Doğuya da batıya da ait olmayan mübarek bir ağacın yağından yakılır. Onun yağı neredeyse kendisine ateş dokunmasa bile ışık verir. Aydınlık üstüne aydınlıktır. Allah,  hak eden[2] kimseyi aydınlığına iletir. Allah,  insanlara örnekler verir. Allah,  her şeyi bütün ayrıntılarıyla bilendir.', 'الله نور السموت والارض مثل نوره كمشكوة فيها مصباح المصباح في زجاجة الزجاجة كانها كوكب دري يوقد من شجرة مبركة زيتونة لا شرقية ولا غربية يكاد زيتها يضي ولو لم تمسسه نار نور علي نور يهدي الله لنوره من يشا ويضرب الله الامثل للناس والله بكل شي عليم'),
(2827, 24, 36, 'ف۪ي بُيُوتٍ اَذِنَ اللّٰهُ اَنْ تُرْفَعَ وَيُذْكَرَ ف۪يهَا اسْمُهُۙ يُسَبِّحُ لَهُ ف۪يهَا بِالْغُدُوِّ وَالْاٰصَالِۙ', 'Fi buyutin ezinallahu en turfea ve yuzkere fihesmuhu yusebbihu lehu fiha bil guduvvi vel asal.', '(Allah\'ın aydınlığı/ışığı) Allah\'ın isminin yüceltilmesine ve öğütlerinin dinlenmesine izin verdiği evlerde[1] vardır. Orada sabah akşam[2] O\'nu tesbih[3] ederler.', 'في بيوت اذن الله ان ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والاصال'),
(2828, 24, 37, 'رِجَالٌۙ  لَا تُلْه۪يهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللّٰهِ وَاِقَامِ الصَّلٰوةِ وَا۪يتَٓاءِ الزَّكٰوةِۙ يَخَافُونَ يَوْماً تَتَقَلَّبُ ف۪يهِ الْقُلُوبُ وَالْاَبْصَارُۙ', 'Ricalun la tulhihim ticaratun ve la bey\'un an zikrillahi ve ikamis salati ve itaiz zekati yehafune yevmen tetekallebu fihil kulubu vel ebsar.', 'Öyle kimseler vardır ki ne mal ne de alışveriş onları Allah\'ın buyruklarına uymaktan,  salatı ikame etmekten[1] ve zekatı yapmaktan[1] alıkoyar. Onlar,  kalplerin ve gözlerin altüst olacağı günden korkarlar.', 'رجال لا تلهيهم تجرة ولا بيع عن ذكر الله واقام الصلوة وايتا الزكوة يخافون يوما تتقلب فيه القلوب والابصر'),
(2829, 24, 38, 'لِيَجْزِيَهُمُ اللّٰهُ اَحْسَنَ مَا عَمِلُوا وَيَز۪يدَهُمْ مِنْ فَضْلِه۪ۜ وَاللّٰهُ يَرْزُقُ مَنْ يَشَٓاءُ بِغَيْرِ حِسَابٍ', 'Li yecziyehumullahu ahsene ma amilu ve yezidehum min fadlih, vallahu yerzuku men yeşau bi gayri hisab.', 'Yaptıklarına karşılık Allah onlara en iyi karşılığı verecek ve lütfundan daha fazlasını da verecektir. Ve Allah hak edeni[1] hesapsız rızıklandırır.', 'ليجزيهم الله احسن ما عملوا ويزيدهم من فضله والله يرزق من يشا بغير حساب'),
(2830, 24, 39, 'وَالَّذ۪ينَ كَفَرُٓوا اَعْمَالُهُمْ كَسَرَابٍ بِق۪يعَةٍ يَحْسَبُهُ الظَّمْاٰنُ مَٓاءًۜ حَتّٰٓى اِذَا جَٓاءَهُ لَمْ يَجِدْهُ شَيْـٔاً وَوَجَدَ اللّٰهَ عِنْدَهُ فَوَفّٰيهُ حِسَابَهُۜ وَاللّٰهُ سَر۪يعُ الْحِسَابِۙ', 'Vellezine keferu a\'maluhum ke serabin bi kiatin yahsebuhuz zam\'anu mae, hatta iza caehu lem yecidhu şey\'en ve vecedallahe indehu fe veffahu hisabeh, vallahu seriul hısab.', 'Kafirlerin[1] yaptıkları,  çöldeki serap gibidir. Susayan onu su zanneder. Ancak yanına vardığında hiçbir şey bulamaz. Orada Allah\'ı bulur[2] ve O da yaptıklarının hesabını eksiksiz görür. Allah hesabı çabuk görendir.', 'والذين كفروا اعملهم كسراب بقيعة يحسبه الظمان ما حتي اذا جاه لم يجده شيا ووجد الله عنده فوفيه حسابه والله سريع الحساب'),
(2831, 24, 40, 'اَوْ كَظُلُمَاتٍ ف۪ي بَحْرٍ لُجِّيٍّ يَغْشٰيهُ مَوْجٌ مِنْ فَوْقِه۪ مَوْجٌ مِنْ فَوْقِه۪ سَحَابٌۜ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍۜ اِذَٓا اَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرٰيهَاۜ وَمَنْ لَمْ يَجْعَلِ اللّٰهُ لَهُ نُوراً فَمَا لَهُ مِنْ نُورٍ۟', 'Ev ke zulumatin fi bahrin lucciyyin yagşahu mevcun min fevkıhi mevcun min fevkıhi sehab, zulumatun ba\'duha fevka ba\'d, iza ahrace yedehu lem yeked yeraha ve men lem yec\'alillahu lehu nuren fe ma lehu min nur.', 'Veya[1] üzerinde bulutlar olan,  üst üste dalgaların kuşattığı derin denizlerdeki karanlığa benzer. Elini göremeyecek kadar,  karanlık üstüne karanlık. Allah\'ın aydınlığıyla aydınlanmamış bir kimse için başka aydınlık yoktur.', 'او كظلمت في بحر لجي يغشيه موج من فوقه موج من فوقه سحاب ظلمت بعضها فوق بعض اذا اخرج يده لم يكد يريها ومن لم يجعل الله له نورا فما له من نور'),
(2832, 24, 41, 'اَلَمْ تَرَ اَنَّ اللّٰهَ يُسَبِّـحُ لَهُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِ وَالطَّيْرُ صَٓافَّاتٍۜ كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْب۪يحَهُۜ وَاللّٰهُ عَل۪يمٌ بِمَا يَفْعَلُونَ', 'E lem tera ennallahe yusebbihu lehu men fis semavati vel ardı vet tayru saffat, kullun kad alime salatehu ve tesbihah, vallahu alimun bima yef\'alun.', 'Göklerde ve yeryüzünde bulunanların,  sürü sürü uçanların,  Allah\'ı nasıl tesbih[1] ettiklerini görmüyor musun? Kuşkusuz hepsi salatını[2] ve tesbihini bilmektedir. Ve Allah,  onların yaptıklarını en iyi bilendir.', 'الم تر ان الله يسبح له من في السموت والارض والطير صفت كل قد علم صلاته وتسبيحه والله عليم بما يفعلون'),
(2833, 24, 42, 'وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۚ وَاِلَى اللّٰهِ الْمَص۪يرُ', 'Ve lillahi mulkus semavati vel ard, ve ilallahil masir.', 'Göklerin ve yeryüzünün egemenliği yalnızca Allah\'a aittir. Sonuçta dönüş Allah\'adır.', 'ولله ملك السموت والارض والي الله المصير'),
(2834, 24, 43, 'اَلَمْ تَرَ اَنَّ اللّٰهَ يُزْج۪ي سَحَاباً ثُمَّ يُؤَلِّفُ بَيْنَهُ ثُمَّ يَجْعَلُهُ رُكَاماً فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِه۪ۚ وَيُنَزِّلُ مِنَ السَّمَٓاءِ مِنْ جِبَالٍ ف۪يهَا مِنْ بَرَدٍ فَيُص۪يبُ بِه۪ مَنْ يَشَٓاءُ وَيَصْرِفُهُ عَنْ مَنْ يَشَٓاءُۜ  يَكَادُ سَنَا بَرْقِه۪ يَذْهَبُ بِالْاَبْصَارِۜ', 'E lem tera ennallahe yuzci sehaben summe yuellifu beynehu summe yec\'aluhu rukamen fe teral vedka yahrucu min hılalih, ve yunezzilu mines semai min cibalin fiha min beredin fe yusibu bihi men yeşau ve yasrifuhu an men yeşau, yekadu sena berkıhi yezhebu bil ebsar.', 'Allah\'ın,  bulutları sürüklediğini,  sonra aralarını birleştirdiğini,  sonra da onları küme haline getirdiğini görmüyor musun? Böylece aralarından yağmur çıktığını görürsün. Ve gökten içinde dolu bulunan dağ gibi kümeleri getiriyor. Neredeyse parıltısı gözlerinizi alan şimşeği dilediğine isabet ettiriyor,  dilediğinden de onu uzak tutuyor.', 'الم تر ان الله يزجي سحابا ثم يولف بينه ثم يجعله ركاما فتري الودق يخرج من خلله وينزل من السما من جبال فيها من برد فيصيب به من يشا ويصرفه عن من يشا يكاد سنا برقه يذهب بالابصر'),
(2835, 24, 44, 'يُقَلِّبُ اللّٰهُ الَّيْلَ وَالنَّهَارَۜ اِنَّ ف۪ي ذٰلِكَ لَعِبْرَةً لِاُو۬لِي الْاَبْصَارِ', 'Yukallibullahul leyle ven nehar, inne fi zalike le ibreten li ulil ebsar.', 'Allah,  geceyi ve gündüzü sürekli değiştirir. Kuşku yok ki,  elbette bunda basiret[1] sahipleri için ibretler vardır.', 'يقلب الله اليل والنهار ان في ذلك لعبرة لاولي الابصر'),
(2836, 24, 45, 'وَاللّٰهُ خَلَقَ كُلَّ دَٓابَّةٍ مِنْ مَٓاءٍۚ فَمِنْهُمْ مَنْ يَمْش۪ي عَلٰى بَطْنِه۪ۚ وَمِنْهُمْ مَنْ يَمْش۪ي عَلٰى رِجْلَيْنِۚ وَمِنْهُمْ مَنْ يَمْش۪ي عَلٰٓى اَرْبَعٍۜ يَخْلُقُ اللّٰهُ مَا يَشَٓاءُۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Vallahu halaka kulle dabbetin min main, fe minhum men yemşi ala batnih ve minhum men yemşi ala ricleyn ve minhum men yemşi ala erba\', yahlukullahu ma yeşau, innellahe ala kulli şey\'in kadir.', 'Allah,  hareket eden her canlıyı sudan yarattı. Onların kimisi karnı,  kimisi iki ayağı,  kimisi de dört ayağı üzerinde yürür. Allah,  dilediğini yaratır. Kuşkusuz,  Allah\'ın Her Şeye Gücü Yeter.', 'والله خلق كل دابة من ما فمنهم من يمشي علي بطنه ومنهم من يمشي علي رجلين ومنهم من يمشي علي اربع يخلق الله ما يشا ان الله علي كل شي قدير'),
(2837, 24, 46, 'لَقَدْ اَنْزَلْـنَٓا اٰيَاتٍ مُبَيِّنَاتٍۜ وَاللّٰهُ يَهْد۪ي مَنْ يَشَٓاءُ اِلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Le kad enzelna ayatin mubeyyinat, vallahu yehdi men yeşau ila sıratın mustakim.', 'Ant olsun ki apaçık ayetler indirdik. Allah,  hak eden[1] kimseyi dosdoğru yola iletir.', 'لقد انزلنا ايت مبينت والله يهدي من يشا الي صرط مستقيم'),
(2838, 24, 47, 'وَيَقُولُونَ اٰمَنَّا بِاللّٰهِ وَبِالرَّسُولِ وَاَطَعْنَا ثُمَّ يَتَوَلّٰى فَر۪يقٌ مِنْهُمْ مِنْ بَعْدِ ذٰلِكَۜ وَمَٓا اُو۬لٰٓئِكَ بِالْمُؤْمِن۪ينَ', 'Ve yekulune amenna billahi ve bir resuli ve ata\'na summe yetevella ferikun minhum min ba\'di zalik ve ma ulaike bil mu\'minin.', '\"Allah\'a ve Resul\'e iman ettik ve tabi olduk.\" diyorlar. Sonra da onların bir kısmı yan çiziyor. Bunlar,  iman etmiş değillerdir.', 'ويقولون امنا بالله وبالرسول واطعنا ثم يتولي فريق منهم من بعد ذلك وما اوليك بالمومنين'),
(2839, 24, 48, 'وَاِذَا دُعُٓوا اِلَى اللّٰهِ وَرَسُولِه۪ لِيَحْكُمَ بَيْنَهُمْ اِذَا فَر۪يقٌ مِنْهُمْ مُعْرِضُونَ', 'Ve iza duu ilallahi ve resulihi li yahkume beynehum iza ferikun minhum mu\'ridun.', 'Aralarında hüküm vermesi için Allah\'a ve Resulüne çağrıldıkları zaman,  onların bir kısmı bundan kaçınır.', 'واذا دعوا الي الله ورسوله ليحكم بينهم اذا فريق منهم معرضون'),
(2840, 24, 49, 'وَاِنْ يَكُنْ لَهُمُ الْحَقُّ يَأْتُٓوا اِلَيْهِ مُذْعِن۪ينَۜ', 'Ve in yekun lehumul hakku ye\'tu ileyhi muz\'ınin.', 'Ama verilen hüküm lehlerine olursa seve seve kabul ederler.', 'وان يكن لهم الحق ياتوا اليه مذعنين'),
(2841, 24, 50, 'اَف۪ي قُلُوبِهِمْ مَرَضٌ اَمِ ارْتَابُٓوا اَمْ يَخَافُونَ اَنْ يَح۪يفَ اللّٰهُ عَلَيْهِمْ وَرَسُولُهُۜ بَلْ اُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ۟', 'E fi kulubihim maradun emirtabu em yehafune en yehifallahu aleyhim ve resuluh, bel ulaike humuz zalimun.', 'Onların kalplerinde bir hastalık mı var? Yoksa kuşku mu duyuyorlar? Yoksa Allah ve Resulünün kendilerine haksızlık edeceğinden mi korkuyorlar? Hayır! Onlar,  zalimlerin ta kendileridir!', 'افي قلوبهم مرض ام ارتابوا ام يخافون ان يحيف الله عليهم ورسوله بل اوليك هم الظلمون'),
(2842, 24, 51, 'اِنَّمَا كَانَ قَوْلَ الْمُؤْمِن۪ينَ اِذَا دُعُٓوا اِلَى اللّٰهِ وَرَسُولِه۪ لِيَحْكُمَ بَيْنَهُمْ اَنْ يَقُولُوا سَمِعْنَا وَاَطَعْنَاۜ وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'İnnema kane kavlel mu\'minine iza duu ilallahi ve resulihi li yahkume beynehum en yekulu semi\'na ve ata\'na ve ulaike humul muflihun.', 'Aralarında hüküm vermesi için Allah\'a ve Resul\'üne çağrıldıkları zaman inananların sözü ancak,  \"İşittik ve itaat ettik.\" demeleri oldu. İşte onlar kurtuluşa erenlerdir.', 'انما كان قول المومنين اذا دعوا الي الله ورسوله ليحكم بينهم ان يقولوا سمعنا واطعنا واوليك هم المفلحون'),
(2843, 24, 52, 'وَمَنْ يُطِـعِ اللّٰهَ وَرَسُولَهُ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُو۬لٰٓئِكَ هُمُ الْفَٓائِزُونَ', 'Ve men yutıillahe ve resulehu ve yahşallahe ve yettakhi fe ulaike humul faizun.', 'Kim Allah\'a ve Resul\'üne itaat[1] eder,  Allah\'a huşu[2] duyar ve O\'na takvalı olursa işte onlar kazançlı çıkacak olanlardır.', 'ومن يطع الله ورسوله ويخش الله ويتقه فاوليك هم الفايزون'),
(2844, 24, 53, 'وَاَقْسَمُوا بِاللّٰهِ جَهْدَ اَيْمَانِهِمْ لَئِنْ اَمَرْتَهُمْ لَيَخْرُجُنَّۜ قُلْ لَا تُقْسِمُواۚ طَاعَةٌ مَعْرُوفَةٌۜ اِنَّ اللّٰهَ خَب۪يرٌ بِمَا تَعْمَلُونَ', 'Ve aksemu billahi cehde eymanihim le in emertehum le yahrucunn, kul la tuksimu, taatun ma\'rufeh, innellahe habirun bima ta\'melun.', 'Münafıklar,  kendilerinden istediğin takdirde kesinlikle savaşa çıkacaklarına dair en kuvvetli yeminleri ile Allah\'a yemin ettiler. De ki: \"Yemin etmeyin. Bağlılık ma\'ruftur.[1]\" Kuşkusuz Allah,  yaptıklarınızdan haberdardır.', 'واقسموا بالله جهد ايمنهم لين امرتهم ليخرجن قل لا تقسموا طاعة معروفة ان الله خبير بما تعملون'),
(2845, 24, 54, 'قُلْ اَط۪يعُوا اللّٰهَ وَاَط۪يعُوا الرَّسُولَۚ فَاِنْ تَوَلَّوْا فَاِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْۜ وَاِنْ تُط۪يعُوهُ تَهْتَدُواۜ وَمَا عَلَى الرَّسُولِ اِلَّا الْبَلَاغُ الْمُب۪ينُ', 'Kul atiullahe ve atiur resul, fe in tevellev fe innema aleyhi ma hummile ve aleykum ma hummiltum, ve in tutiuhu tehtedu, ve ma aler resuli illel belagul mubin.', 'De ki: \"Allah\'a itaat edin. Resul\'e itaat edin.[1]\" Eğer itaat etmezseniz,  ona düşen yalnızca görevini yapmaktır. Size düşen ise sorumlu tutulduğunuz şeye uymaktır. Eğer ona itaat ederseniz,  doğru yolu bulursunuz. Resul\'ün üzerinde,  mesajı açıkça iletmekten başka bir sorumluluk yoktur.', 'قل اطيعوا الله واطيعوا الرسول فان تولوا فانما عليه ما حمل وعليكم ما حملتم وان تطيعوه تهتدوا وما علي الرسول الا البلغ المبين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2846, 24, 55, 'وَعَدَ اللّٰهُ الَّذ۪ينَ اٰمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْاَرْضِ كَمَا اسْتَخْلَفَ الَّذ۪ينَ مِنْ قَبْلِهِمْۖ وَلَيُمَكِّنَنَّ لَهُمْ د۪ينَهُمُ الَّذِي ارْتَضٰى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ اَمْناًۜ يَعْبُدُونَن۪ي لَا يُشْرِكُونَ ب۪ي شَيْـٔاًۜ وَمَنْ كَفَرَ بَعْدَ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الْفَاسِقُونَ', 'Vaadallahullezine amenu minkum ve amilus salihati leyestahlifennehum fil ardı kemestahlefellezine min kablihim, ve leyumekkinenne lehum dinehumullezirteda lehum ve le yubeddilennehum min ba\'di havfihim emna, ya\'buduneni la yuşrikune bi şey\'a, ve men kefere ba\'de zalike fe ulaike humul fasikun.', 'Allah,  sizden iman eden ve salihatı yapanlara[1],  tıpkı kendilerinden öncekileri halife kıldığı gibi,  kendilerini de yeryüzünde halife kılacağını,  onlar için beğenip seçtiği dini mutlaka sağlamlaştıracağını ve endişelerinden sonra onları mutlaka güvene kavuşturacağını vaat etti. Onlar,  Bana kulluk ederler ve hiçbir şeyi ortak koşmazlar. Bundan sonra da kim küfrederse,  işte onlar yoldan çıkanların ta kendileridir.[2]', 'وعد الله الذين امنوا منكم وعملوا الصلحت ليستخلفنهم في الارض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذي ارتضي لهم وليبدلنهم من بعد خوفهم امنا يعبدونني لا يشركون بي شيا ومن كفر بعد ذلك فاوليك هم الفسقون'),
(2847, 24, 56, 'وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَط۪يعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'Ve ekimus salate ve atuz zekate ve atiur resule leallekum turhamun.', 'Salatı ikame edin,  zekatı yapın.[1] Ve Resul\'e itaat edin. Umulur ki merhamet edilirsiniz.', 'واقيموا الصلوة واتوا الزكوة واطيعوا الرسول لعلكم ترحمون'),
(2848, 24, 57, 'لَا تَحْسَبَنَّ الَّذ۪ينَ كَفَرُوا مُعْجِز۪ينَ فِي الْاَرْضِۚ وَمَأْوٰيهُمُ النَّارُۜ وَلَبِئْسَ الْمَص۪يرُ۟', 'La tahsebennellezine keferu mu\'cizine fil ard, ve me\'vahumun nar, ve le bi\'sel masir.', 'Sakın Kafirleri yeryüzünde aciz bırakıcı zannetme. Onların varacağı yer ateştir. Ne kötü bir varış yeridir.', 'لا تحسبن الذين كفروا معجزين في الارض وماويهم النار ولبيس المصير'),
(2849, 24, 58, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لِيَسْتَأْذِنْكُمُ الَّذ۪ينَ مَلَكَتْ اَيْمَانُكُمْ وَالَّذ۪ينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلٰثَ مَرَّاتٍۜ مِنْ قَبْلِ صَلٰوةِ الْفَجْرِ وَح۪ينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّه۪يرَةِ وَمِنْ بَعْدِ صَلٰوةِ الْعِشَٓاءِ۠ ثَلٰثُ عَوْرَاتٍ لَكُمْۜ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّۜ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلٰى بَعْضٍۜ كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمُ الْاٰيَاتِۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ya eyyuhellezine amenu li yeste\'zinkumullezine meleket eymanukum vellezine lem yeblugul hulume minkum selase merrat, min kabli salatil fecri, ve hinetedaune siyabekum minez zahirat, ve min ba\'di salatil ışai, selasu avratin lekum, leyse aleykum ve la aleyhim cunahun ba\'de hunn, tavvafune aleykum ba\'dukum ala ba\'d, kezalike yubeyyinullahu lekumul ayat, vallahu alimun hakim.', 'Ey iman edenler! Antlaşma yoluyla sahip olduğunuz[1] kimseler,  sizden erginlik yaşına gelmemiş olanlar;[2] şu üç vakitte,  yanınıza girmek için sizden izin istesinler; sabah salatından[3] önce,  gün ortasında elbiselerinizi çıkardığınızda,  akşam salatından[4] sonra. Bu üç vakit \"avret\"[5] vaktidir. Bunlar dışında birbirinizin yanına girip çıkmanızda siz ve onlar için bir sakınca yoktur. İşte Allah,  size ayetleri böyle açıklıyor. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يايها الذين امنوا ليستذنكم الذين ملكت ايمنكم والذين لم يبلغوا الحلم منكم ثلث مرت من قبل صلوة الفجر وحين تضعون ثيابكم من الظهيرة ومن بعد صلوة العشا ثلث عورت لكم ليس عليكم ولا عليهم جناح بعدهن طوفون عليكم بعضكم علي بعض كذلك يبين الله لكم الايت والله عليم حكيم'),
(2850, 24, 59, 'وَاِذَا بَلَغَ الْاَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ  كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمْ اٰيَاتِه۪ۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ve iza belegal etfalu minkumul hulume felyeste\'zinu kemeste\'zenellezine min kablihim, kezalike yubeyyinullahu lekum ayatih, vallahu alimun hakim.', 'Ve çocuklarınız,  ergenlik çağına geldiği zaman,  onlardan öncekilerin izin istedikleri gibi izin istesinler. İşte böylece Allah size ayetlerini açıklıyor. Ve Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'واذا بلغ الاطفل منكم الحلم فليستذنوا كما استذن الذين من قبلهم كذلك يبين الله لكم ايته والله عليم حكيم'),
(2851, 24, 60, 'وَالْقَوَاعِدُ مِنَ النِّسَٓاءِ الّٰت۪ي لَا يَرْجُونَ نِكَاحاً فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ اَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِز۪ينَةٍۜ وَاَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّۜ وَاللّٰهُ سَم۪يعٌ عَل۪يمٌ', 'Vel kavaıdu minen nisaillati la yercune nikahan fe leyse aleyhinne cunahun en yeda\'ne siyabehunne gayra muteberricatin bi zineh, ve en yesta\'fifne hayrun lehunn, vallahu semiun alim.', 'Evlenme arzusu kalmamış yaşlı kadınların,  cinsiyetlerini teşhir etme amacı gütmeden dış giysilerini çıkarmalarında bir sakınca yoktur. Sakınmaları daha hayırlıdır. Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'والقوعد من النسا التي لا يرجون نكاحا فليس عليهن جناح ان يضعن ثيابهن غير متبرجت بزينة وان يستعففن خير لهن والله سميع عليم'),
(2852, 24, 61, 'لَيْسَ عَلَى الْاَعْمٰى حَرَجٌ وَلَا عَلَى الْاَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَر۪يضِ حَرَجٌ وَلَا عَلٰٓى اَنْفُسِكُمْ اَنْ تَأْكُلُوا مِنْ بُيُوتِكُمْ اَوْ بُيُوتِ اٰبَٓائِكُمْ اَوْ بُيُوتِ اُمَّهَاتِكُمْ اَوْ بُيُوتِ اِخْوَانِكُمْ اَوْ بُيُوتِ اَخَوَاتِكُمْ اَوْ بُيُوتِ اَعْمَامِكُمْ اَوْ بُيُوتِ عَمَّاتِكُمْ اَوْ بُيُوتِ اَخْوَالِكُمْ اَوْ بُيُوتِ خَالَاتِكُمْ اَوْ مَا مَلَكْتُمْ مَفَاتِحَهُٓ اَوْ صَد۪يقِكُمْۜ لَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَأْكُلُوا جَم۪يعاً اَوْ اَشْتَاتاًۜ فَاِذَا دَخَلْتُمْ بُيُوتاً فَسَلِّمُوا عَلٰٓى اَنْفُسِكُمْ تَحِيَّةً مِنْ عِنْدِ اللّٰهِ مُبَارَكَةً طَيِّبَةًۜ كَذٰلِكَ يُبَيِّنُ اللّٰهُ لَكُمُ الْاٰيَاتِ لَعَلَّكُمْ تَعْقِلُونَ۟', 'Leyse alel a\'ma haracun ve la alel a\'raci haracun ve la alel maridı haracun ve la ala enfusikum en te\'kulu min buyutikum ev buyuti abaikum ev buyuti ummehatikum ev buyuti ihvanikum ev buyuti ehavatikum ev buyuti a\'mamikum ev buyuti ammatikum ev buyuti ahvalikum ev buyuti halatikum ev ma melektum mefatihahu ev sadikıkum, leyse aleykum cunahun en te\'kulu cemian ev eştata, fe iza dahaltum buyuten fe sellimu ala enfusikum tehıyyeten min indillahi mubareketen tayyibeh, kezalike yubeyyinullahu lekumul ayati leallekum ta\'kılun.', 'Köre bir sınırlama yoktur. Sakat olana bir sınırlama yoktur. Hasta olana bir sınırlama yoktur.[1] Ve size de,  evlerinizde veya babalarınızın evlerinde veya annelerinizin evlerinde veya erkek kardeşlerinizin evlerinde veya kız kardeşlerinizin evlerinde veya amcalarınızın evlerinde veya halalarınızın evlerinde veya dayılarınızın evlerinde veya teyzelerinizin evlerinde veya anahtarlarına sahip olduğunuz yerlerde veya arkadaşlarınızın evlerinde yemek yemenizde bir sakınca yoktur. Toplu olarak veya ayrı ayrı olarak yemenizde de bir sakınca yoktur. Evlere girdiğiniz zaman Allah tarafından kutlu ve temiz bir selam[2] ile selam verin. İşte Allah,  size ayetlerini böylece açıklıyor. Umulur ki böylece aklınızı kullanırsınız.', 'ليس علي الاعمي حرج ولا علي الاعرج حرج ولا علي المريض حرج ولا علي انفسكم ان تاكلوا من بيوتكم او بيوت ابايكم او بيوت امهتكم او بيوت اخونكم او بيوت اخوتكم او بيوت اعممكم او بيوت عمتكم او بيوت اخولكم او بيوت خلتكم او ما ملكتم مفاتحه او صديقكم ليس عليكم جناح ان تاكلوا جميعا او اشتاتا فاذا دخلتم بيوتا فسلموا علي انفسكم تحية من عند الله مبركة طيبة كذلك يبين الله لكم الايت لعلكم تعقلون'),
(2853, 24, 62, 'اِنَّمَا الْمُؤْمِنُونَ الَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَرَسُولِه۪ وَاِذَا كَانُوا مَعَهُ عَلٰٓى اَمْرٍ جَامِعٍ لَمْ يَذْهَبُوا حَتّٰى يَسْتَأْذِنُوهُۜ اِنَّ الَّذ۪ينَ يَسْتَأْذِنُونَكَ اُو۬لٰٓئِكَ الَّذ۪ينَ يُؤْمِنُونَ بِاللّٰهِ وَرَسُولِه۪ۚ فَاِذَا اسْتَأْذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَنْ لِمَنْ شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللّٰهَۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İnnelmel mu\'minunellezine amenu billahi ve resulihi ve iza kanu meahu ala emrin camiın lem yezhebu hatta yeste\'zinuh, innellezine yeste\'zinuneke ulaikellezine yu\'minune billahi ve resulih, fe izeste\'zenuke li ba\'dı şe\'nihim fe\'zen li men şi\'te minhum vestağfir lehumullah, innallahe gafurun rahim.', 'Ancak Allah\'a ve Resul\'üne içtenlikle iman etmiş mü\'minler,  toplumu ilgilendiren bir iş için onunla bir araya geldikleri zaman,  ondan izin almadıkça gitmezler. Senden izin isteyen kimseler,  işte onlar Allah\'a ve O\'nun Resulüne iman edenlerdir. Öyle ise,  bazı işleri için senden izin istedikleri zaman onlardan dilediğin kimseye izin ver; onlar için Allah\'tan bağışlanma dile. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'انما المومنون الذين امنوا بالله ورسوله واذا كانوا معه علي امر جامع لم يذهبوا حتي يستذنوه ان الذين يستذنونك اوليك الذين يومنون بالله ورسوله فاذا استذنوك لبعض شانهم فاذن لمن شيت منهم واستغفر لهم الله ان الله غفور رحيم'),
(2854, 24, 63, 'لَا تَجْعَلُوا دُعَٓاءَ الرَّسُولِ بَيْنَكُمْ  كَدُعَٓاءِ بَعْضِكُمْ بَعْضاًۜ قَدْ يَعْلَمُ اللّٰهُ الَّذ۪ينَ يَتَسَلَّلُونَ مِنْكُمْ لِوَاذاًۚ فَلْيَحْذَرِ الَّذ۪ينَ يُخَالِفُونَ عَنْ اَمْرِه۪ٓ اَنْ تُص۪يبَهُمْ فِتْنَةٌ اَوْ يُص۪يبَهُمْ عَذَابٌ اَل۪يمٌ', 'La tec\'alu duaer resuli beynekum ke duai ba\'dıkum ba\'da, kad ya\'lemullahullezine yetesellelune minkum livaza, fel yahzerillezine yuhalifune an emrihi en tusibehum fitnetun ev yusibehum azabun elim.', 'Resul\'ün çağrısını,  birbirinize yaptığınız çağrıyla denk tutmayın. İçinizden birbirinin arkasına saklanarak sıvışmak isteyenleri Allah biliyor. Bu sebeple onun buyurmalarına karşı gelenler,  kendilerine bir fitnenin veya çok acıklı bir azabın isabet etmesinden sakınsınlar.', 'لا تجعلوا دعا الرسول بينكم كدعا بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر الذين يخالفون عن امره ان تصيبهم فتنة او يصيبهم عذاب اليم'),
(2855, 24, 64, 'اَلَٓا اِنَّ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ قَدْ يَعْلَمُ مَٓا اَنْتُمْ عَلَيْهِۜ وَيَوْمَ يُرْجَعُونَ اِلَيْهِ فَيُنَبِّئُهُمْ بِمَا عَمِلُواۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'E la inne lillahi ma fis semavati vel ard, kad ya\'lemu ma entum aleyh, ve yevme yurceune ileyhi fe yunebbiuhum bi ma amilu, vallahu bi kulli şey\'in alim.', 'Unutmayın! Göklerde ve yerde olan her şey Allah\'ındır. O sizin ne üzerinde olduğunuzu kesinlikle bilir. O\'na döndürüldükleri gün,  onlara yaptıklarını haber verecektir. Allah,  Her Şeyi En İyi Bilen\'dir.', 'الا ان لله ما في السموت والارض قد يعلم ما انتم عليه ويوم يرجعون اليه فينبيهم بما عملوا والله بكل شي عليم'),
(2856, 25, 1, 'تَبَارَكَ الَّذ۪ي نَزَّلَ الْفُرْقَانَ عَلٰى عَبْدِه۪ لِيَكُونَ لِلْعَالَم۪ينَ نَذ۪يراًۙ', 'Tebarekellezi nezzelel furkane ala abdihi li yekune lil alemine nezira.', 'Âlemlere uyarıcı olması için,  kuluna Furkan\'ı[1] indiren ne mübarektir![2]', 'تبارك الذي نزل الفرقان علي عبده ليكون للعلمين نذيرا'),
(2857, 25, 2, 'اَلَّذ۪ي لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَلَمْ يَتَّخِذْ وَلَداً وَلَمْ يَكُنْ لَهُ شَر۪يكٌ فِي الْمُلْكِ وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْد۪يراً', 'Ellezi lehu mulkus semavati vel ardı ve lem yettehız veleden ve lem yekun lehu şerikun fil mulki ve halaka kulle şey\'in fe kadderahu takdira.', 'O ki,  göklerin ve yerin egemenliği yalnızca O\'na aittir. Ve O,  çocuk edinmemiştir. Egemenlikte O\'nun ortağı yoktur. Her şeyi yaratan,  işleyiş ve varoluş yasalarını belirleyen O\'dur.', 'الذي له ملك السموت والارض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شي فقدره تقديرا'),
(2858, 25, 3, 'وَاتَّخَذُوا مِنْ دُونِه۪ٓ اٰلِهَةً لَا يَخْلُقُونَ شَيْـٔاً وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِاَنْفُسِهِمْ ضَراًّ وَلَا نَفْعاً وَلَا يَمْلِكُونَ مَوْتاً وَلَا حَيٰوةً وَلَا نُشُوراً', 'Vettehazu min dunihi aliheten la yahlukune şey\'en ve hum yuhlekune ve la yemlikune li enfusihim darran ve la nef\'an ve la yemlikune mevten ve la hayaten ve la nuşura.', 'O\'nun yanı sıra hiçbir şeyi yaratamayan,  kendileri yaratılmış olan,  kendilerine yarar sağlama ve kendilerinden zararı savma güçleri olmayan; ölüme,  hayata ve ölümden sonra diriltmeye güçleri yetmeyenleri ilahlar edindiler.', 'واتخذوا من دونه الهة لا يخلقون شيا وهم يخلقون ولا يملكون لانفسهم ضرا ولا نفعا ولا يملكون موتا ولا حيوة ولا نشورا'),
(2859, 25, 4, 'وَقَالَ الَّذ۪ينَ كَفَرُٓوا اِنْ هٰذَٓا اِلَّٓا اِفْكٌۨ افْتَرٰيهُ وَاَعَانَهُ عَلَيْهِ قَوْمٌ اٰخَرُونَۚۛ فَقَدْ جَٓاؤُ۫ ظُلْماً وَزُوراًۚۛ', 'Ve kalellezine keferu in haza illa ifkunifterahu ve eanehu aleyhi kavmun aharun, fe kad cau zulmen ve zura.', 'Kafirler: \"Bu sadece onun uydurduğu bir yalandır. Ona bu konuda diğer toplumlar da yardım etti.\" dediler. Böylece haksızca iftira ettiler.', 'وقال الذين كفروا ان هذا الا افك افتريه واعانه عليه قوم اخرون فقد جاو ظلما وزورا'),
(2860, 25, 5, 'وَقَالُٓوا اَسَاط۪يرُ الْاَوَّل۪ينَ اكْتَتَبَهَا فَهِيَ تُمْلٰى عَلَيْهِ بُكْرَةً وَاَص۪يلاً', 'Ve kalu esatirul evvelinektetebeha fe hiye tumla aleyhi bukreten ve asila.', 'Ve \"O,  onun yazdırdığı ve sabah akşam[1] ona dikte ettikleri evvelkilerin masallarıdır.\" dediler.', 'وقالوا اسطير الاولين اكتتبها فهي تملي عليه بكرة واصيلا'),
(2861, 25, 6, 'قُلْ اَنْزَلَهُ الَّذ۪ي يَعْلَمُ السِّرَّ فِي السَّمٰوَاتِ وَالْاَرْضِۜ اِنَّهُ كَانَ غَفُوراً رَح۪يماً', 'Kul enzelehullezi ya\'lemus sırre fis semavati vel ard, innehu kane gafuran rahima.', 'De ki: \"Onu,  göklerin ve yerin sırrını Bilen indirdi. Kuşkusuz O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.\"', 'قل انزله الذي يعلم السر في السموت والارض انه كان غفورا رحيما'),
(2862, 25, 7, 'وَقَالُوا مَالِ هٰذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْش۪ي فِي الْاَسْوَاقِۜ  لَوْلَٓا اُنْزِلَ اِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُ نَذ۪يراًۙ', 'Ve kalu mali hazer resuli ye\'kulit taame ve yemşi fil esvak, lev la unzile ileyhi melekun fe yekune meahu nezira.', 'Dediler ki: \"Bu nasıl bir resul ki,  yiyor-içiyor,  çarşı-pazar dolaşıyor. Ona bir melek indirilseydi de onunla birlikte uyarıcı olsaydı ya!\"', 'وقالوا مال هذا الرسول ياكل الطعام ويمشي في الاسواق لولا انزل اليه ملك فيكون معه نذيرا'),
(2863, 25, 8, 'اَوْ يُلْقٰٓى اِلَيْهِ كَنْزٌ اَوْ تَكُونُ لَهُ جَنَّةٌ يَأْكُلُ مِنْهَاۜ وَقَالَ الظَّالِمُونَ اِنْ تَتَّبِعُونَ اِلَّا رَجُلاً مَسْحُوراً', 'Ev yulka ileyhi kenzun ev tekunu lehu cennetunye\'kulu minha, ve kalez zalimune in tettebiune illa raculen meshura.', '\"Veya ona bir hazine verilseydi veya kendisinden yiyeceği bir bahçesi olsaydı ya!\" Bu zalimler: \"Siz yalnızca büyülenmiş bir adama uyuyorsunuz.\" dediler.', 'او يلقي اليه كنز او تكون له جنة ياكل منها وقال الظلمون ان تتبعون الا رجلا مسحورا'),
(2864, 25, 9, 'اُنْظُرْ كَيْفَ ضَرَبُوا لَكَ الْاَمْثَالَ فَضَلُّوا فَلَا يَسْتَط۪يعُونَ سَب۪يلاً۟', 'Unzur keyfe darabu lekel emsale fe dallu fe la yestetiune sebila.', 'Senin için nasıl örnekler verdiklerine bir bak. Böylece saptılar,  artık bir çıkış yolu bulamazlar.', 'انظر كيف ضربوا لك الامثل فضلوا فلا يستطيعون سبيلا'),
(2865, 25, 10, 'تَبَارَكَ الَّـذ۪ٓي اِنْ شَٓاءَ جَعَلَ لَكَ خَيْراً مِنْ ذٰلِكَ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۙ وَيَجْعَلْ لَكَ قُصُوراً', 'Tebarekellezi in şae ceale leke hayren min zalike cennatin tecri min tahtihel enharu ve yec\'al leke kusura.', 'O,  öyle mübarektir[1] ki,  dilerse sana bundan daha hayırlı olan,  içinden ırmaklar akan bahçeler verir. Köşkler de verir.', 'تبارك الذي ان شا جعل لك خيرا من ذلك جنت تجري من تحتها الانهر ويجعل لك قصورا'),
(2866, 25, 11, 'بَلْ كَذَّبُوا بِالسَّاعَةِ وَاَعْتَدْنَا لِمَنْ كَذَّبَ بِالسَّاعَةِ سَع۪يراًۚ', 'Bel kezzebu bis saati ve a\'tedna li men kezzebe bis saati saira.', 'Hayır! Onlar Sa\'at\'i[1] yalanladılar. Ve Biz,  o Sa\'at\'i yalanlayanlara alevli ateş hazırladık.', 'بل كذبوا بالساعة واعتدنا لمن كذب بالساعة سعيرا'),
(2867, 25, 12, 'اِذَا رَاَتْهُمْ مِنْ مَكَانٍ بَع۪يدٍ سَمِعُوا لَهَا تَغَيُّظاً وَزَف۪يراً', 'İza raethum min mekanin baidin semiu leha tegayyuzan ve zefira.', 'Cehennem onları[1] uzak bir yerden gördüğü zaman,  onun öfkelenmesini ve uğultusunu işittiler.[2]', 'اذا راتهم من مكان بعيد سمعوا لها تغيظا وزفيرا'),
(2868, 25, 13, 'وَاِذَٓا اُلْقُوا مِنْهَا مَكَاناً ضَيِّقاً مُقَرَّن۪ينَ دَعَوْا هُنَالِكَ ثُبُوراًۜ', 'Ve iza ulku minha mekanen dayyıkan mukarrenine deav hunalike subura.', 'Çaresizlik içinde,  dar bir yere atıldıkları zaman orada yok olmak için yakaracaklar.', 'واذا القوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا'),
(2869, 25, 14, 'لَا تَدْعُوا الْيَوْمَ ثُبُوراً وَاحِداً وَادْعُوا ثُبُوراً كَث۪يراً', 'La ted\'ul yevme suburan vahıden ved\'u suburan kesira.', 'Bugün bir kez değil,  defalarca yok olmayı isteyin.', 'لا تدعوا اليوم ثبورا وحدا وادعوا ثبورا كثيرا'),
(2870, 25, 15, 'قُلْ اَذٰلِكَ خَيْرٌ اَمْ جَنَّةُ الْخُلْدِ الَّت۪ي وُعِدَ الْمُتَّقُونَۜ كَانَتْ لَهُمْ جَزَٓاءً وَمَص۪يراً', 'Kul e zalike hayrun em cennetul huldilleti vuidel muttekun, kanet lehum cezaen ve masira.', 'De ki: \"Bu mu daha hayırlıdır,  yoksa takva sahipleri için bir ödül olan,  dönüş yeri olarak söz verilen süresiz Cennet mi?\"', 'قل اذلك خير ام جنة الخلد التي وعد المتقون كانت لهم جزا ومصيرا'),
(2871, 25, 16, 'لَهُمْ ف۪يهَا مَا يَشَٓاؤُ۫نَ خَالِد۪ينَۜ  كَانَ عَلٰى رَبِّكَ وَعْداً مَسْؤُ۫لاً', 'Lehum fiha ma yeşaune halidin, kane ala rabbike va\'den mes\'ula.', 'Onlar için orada diledikleri her şey süresiz olarak vardır. Bu Rabb\'inin yerine getirmeyi üstlendiği bir sözdür.', 'لهم فيها ما يشاون خلدين كان علي ربك وعدا مسولا'),
(2872, 25, 17, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِنْ دُونِ اللّٰهِ فَيَقُولُ ءَاَنْتُمْ اَضْلَلْتُمْ عِبَاد۪ي هٰٓؤُ۬لَٓاءِ اَمْ هُمْ ضَلُّوا السَّب۪يلَۜ', 'Ve yevme yahşuruhum ve ma ya\'budune min dunillahi fe yekulu e entum adleltum ibadi haulai em hum dallus sebil.', 'Ve o gün,  onları ve Allah\'ın yanı sıra kulluk ettikleri şeyleri toplar,  sonra da onlara: \"Kullarımı siz mi saptırdınız yoksa kendileri mi yoldan çıktılar?\" der.', 'ويوم يحشرهم وما يعبدون من دون الله فيقول انتم اضللتم عبادي هولا ام هم ضلوا السبيل'),
(2873, 25, 18, 'قَالُوا سُبْحَانَكَ مَا كَانَ يَنْبَغ۪ي لَـنَٓا اَنْ نَتَّخِذَ مِنْ دُونِكَ مِنْ اَوْلِيَٓاءَ وَلٰكِنْ مَتَّعْتَهُمْ وَاٰبَٓاءَهُمْ حَتّٰى نَسُوا الذِّكْرَۚ وَكَانُوا قَوْماً بُوراً', 'Kalu subhaneke ma kane yenbegi lena en nettehıze min dunike min evliyae ve lakin metta\'tehum ve abaehum hatta nesuz zikre, ve kanu kavmen bura.', 'Dediler ki: \"Seni tenzih ederiz,  Senden başka veliler[1] edinmek bize yakışmaz. Ancak Sen,  onları ve atalarını bolca nimetlenirdin,  nihayet onlar öğüdüne uymayı boş verdiler. Ve helak olmayı hak eden bir halk oldular.\"', 'قالوا سبحنك ما كان ينبغي لنا ان نتخذ من دونك من اوليا ولكن متعتهم واباهم حتي نسوا الذكر وكانوا قوما بورا'),
(2874, 25, 19, 'فَقَدْ كَذَّبُوكُمْ بِمَا تَقُولُونَۙ فَمَا تَسْتَط۪يعُونَ صَرْفاً وَلَا نَصْراًۚ وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَاباً كَب۪يراً', 'Fe kad kezzebukum bima tekulune fe ma testetiune sarfan ve la nasra, ve men yazlım minkum nuzıkhu azaben kebira.', 'İşte onlar[1] söylediklerinizden dolayı sizi yalanladılar. Artık uzaklaştırmaya[2] ve yardım almaya güç yetiremezsiniz. Ve sizden kim haksızlık etmişse ona büyük azabı tattıracağız.', 'فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا'),
(2875, 25, 20, 'وَمَٓا اَرْسَلْنَا قَبْلَكَ مِنَ الْمُرْسَل۪ينَ اِلَّٓا اِنَّهُمْ لَيَأْكُلُونَ الطَّعَامَ وَيَمْشُونَ فِي الْاَسْوَاقِۜ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةًۜ اَتَصْبِرُونَۚ وَكَانَ رَبُّكَ بَص۪يراً۟', 'Ve ma erselna kableke minel murseline illa innehum le ye\'kulunet taame ve yemşune fil esvakı ve cealna ba\'dakum li ba\'dın fitneten, e tasbirun, ve kane rabbuke basira.', 'Kesinlikle Biz,  senden önce de yemek yiyen ve çarşılarda dolaşan resullerden farklı resul göndermedik. Ve sizin bir kısmınızı[1] bir kısmınız[2] için sınav kıldık. Bakalım sabrediyor musunuz? Rabb\'in Her Şeyi Gören\'dir.', 'وما ارسلنا قبلك من المرسلين الا انهم لياكلون الطعام ويمشون في الاسواق وجعلنا بعضكم لبعض فتنة اتصبرون وكان ربك بصيرا'),
(2876, 25, 21, 'وَقَالَ الَّذ۪ينَ لَا يَرْجُونَ لِقَٓاءَنَا لَوْلَٓا اُنْزِلَ عَلَيْنَا الْمَلٰٓئِكَةُ اَوْ نَرٰى رَبَّـنَاۜ لَقَدِ اسْتَكْبَرُوا ف۪ٓي اَنْفُسِهِمْ وَعَتَوْ عُتُواًّ كَب۪يراً', 'Ve kalellezine la yercune likaena lev la unzile aleynel melaiketu ev nera rabbena, lekad istekberu fi enfusihim ve atev utuvven kebira.', 'Bizimle karşılaşacaklarına ihtimal vermeyenler: \"Bize meleklerin indirilmesi veya Rabbimizi görmemiz gerekmez miydi?\" dediler. Ant olsun ki onlar kendi kendilerine büyüklendiler ve büyük bir taşkınlıkla hadlerini aştılar.', 'وقال الذين لا يرجون لقانا لولا انزل علينا المليكة او نري ربنا لقد استكبروا في انفسهم وعتو عتوا كبيرا'),
(2877, 25, 22, 'يَوْمَ يَرَوْنَ الْمَلٰٓئِكَةَ لَا بُشْرٰى يَوْمَئِذٍ لِلْمُجْرِم۪ينَ وَيَقُولُونَ حِجْراً مَحْجُوراً', 'Yevme yerevnel melaikete la buşra yevme izin lil mucrimine ve yekulune hicran mahcura.', 'Suçları kendilerini kuşatmış olanlar,  melekleri görecekleri gün,  onlar için hiç de sevindirici olmayacak,  melekler onlara: \"Boşuna beklemeyin size sevindirici haber imkansız.\" diyecekler.', 'يوم يرون المليكة لا بشري يوميذ للمجرمين ويقولون حجرا محجورا'),
(2878, 25, 23, 'وَقَدِمْنَٓا اِلٰى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَٓاءً مَنْثُوراً', 'Ve kadimna ila ma amilu min amelin fe cealnahu hebaen mensura.', 'Ve onların yaptıklarının tamamını savrulmuş toz zerresi gibi boşa çıkaracağız.[1]', 'وقدمنا الي ما عملوا من عمل فجعلنه هبا منثورا'),
(2879, 25, 24, 'اَصْحَابُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُسْتَقَراًّ وَاَحْسَنُ مَق۪يلاً', 'Ashabul cenneti yevme izin hayrun mustekarran ve ahsenu makila.', 'O gün,  Cennet ehli en yararlı yerde eğlenecek ve en iyi yerde dinlenecek.', 'اصحب الجنة يوميذ خير مستقرا واحسن مقيلا'),
(2880, 25, 25, 'وَيَوْمَ تَشَقَّقُ السَّمَٓاءُ بِالْغَمَامِ وَنُزِّلَ الْمَلٰٓئِكَةُ تَنْز۪يلاً', 'Ve yevme teşakkakus semau bil gamami ve nuzzilel melaiketu tenzila.', 'O gün,  gök beyaz bulutlar şeklinde parçalanacak ve melekler ardı sıra indirilecek.', 'ويوم تشقق السما بالغمم ونزل المليكة تنزيلا'),
(2881, 25, 26, 'اَلْمُلْكُ يَوْمَئِذٍۨ الْحَقُّ لِلرَّحْمٰنِۜ وَكَانَ يَوْماً عَلَى الْكَافِر۪ينَ عَس۪يراً', 'El mulku yevmeizinil hakku lir rahman, ve kane yevmen alel kafirine asira.', 'İzin Günü[1] egemenlik yalnızca Rahman\'a aittir. O gün,  Kafirler için zor bir gündür.', 'الملك يوميذ الحق للرحمن وكان يوما علي الكفرين عسيرا'),
(2882, 25, 27, 'وَيَوْمَ يَعَضُّ الظَّالِمُ عَلٰى يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَب۪يلاً', 'Ve yevme yeadduz zalimu ala yedeyhi yekulu ya leytenittehaztu mear resuli sebila.', 'O gün,  zalim kimse,  ellerini ısırarak: \"Eyvah,  keşke Resul\'ün tuttuğu yolu tutmuş olsaydım.\" diyecek.', 'ويوم يعض الظالم علي يديه يقول يليتني اتخذت مع الرسول سبيلا'),
(2883, 25, 28, 'يَا وَيْلَتٰى لَيْتَن۪ي لَمْ اَتَّخِذْ فُلَاناً خَل۪يلاً', 'Ya veyleta leyteni lem ettehız fulanen halila.', '\"Eyvah! Keşke falancayı dost edinmeseydim!\"', 'يويلتي ليتني لم اتخذ فلانا خليلا'),
(2884, 25, 29, 'لَقَدْ اَضَلَّن۪ي عَنِ الذِّكْرِ بَعْدَ اِذْ جَٓاءَن۪يۜ وَكَانَ الشَّيْطَانُ لِلْاِنْسَانِ خَذُولاً', 'Lekad edalleni aniz zikri ba\'de iz caeni, ve kaneş şeytanu lil insani hazula.', '\"Ant olsun ki bana öğüt geldiği halde,  beni o sapıttı.\" Şeytan,  insanı yalnız ve yardımsız bırakır!', 'لقد اضلني عن الذكر بعد اذ جاني وكان الشيطن للانسن خذولا'),
(2885, 25, 30, 'وَقَالَ الرَّسُولُ يَا رَبِّ اِنَّ قَوْمِي اتَّخَذُوا هٰذَا الْقُرْاٰنَ مَهْجُوراً', 'Ve kaler resulu ya rabbi inne kavmittehazu hazel kur\'ane mehcura.', 'Resul: \"Ey Rabb\'im,  halkım bu Kur\'an\'ı mehcur[1] tuttu.\" dedi.', 'وقال الرسول يرب ان قومي اتخذوا هذا القران مهجورا'),
(2886, 25, 31, 'وَكَذٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُواًّ مِنَ الْمُجْرِم۪ينَۜ وَكَفٰى بِرَبِّكَ هَادِياً وَنَص۪يراً', 'Ve kezalike cealna li kulli nebiyyin aduvven minel mucrimin, ve kefa bi rabbike hadiyen ve nasira.', 'Bu hep böyle olmuştur. Biz her nebiye,  mücrimlerden[1] bir düşman kıldık. Yol gösterici ve yardım edici olarak Rabb\'in sana yeter.', 'وكذلك جعلنا لكل نبي عدوا من المجرمين وكفي بربك هاديا ونصيرا'),
(2887, 25, 32, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لَوْلَا نُزِّلَ عَلَيْهِ الْقُرْاٰنُ جُمْلَةً وَاحِدَةًۚ كَذٰلِكَ لِنُثَبِّتَ بِه۪ فُؤٰادَكَ وَرَتَّلْنَاهُ تَرْت۪يلاً', 'Ve kalellezine keferu lev la nuzzile aleyhil kur\'anu, cumleten vahideh, kezalike li nusebbite bihi fuadeke ve rettelnahu tertila.', 'Kafirler: \"Kur\'an ona bir defada ve topluca indirilmeli değil miydi?\" dediler. Oysaki bu,  onu kalbine iyice yerleştirelim diyedir. Onu düzenli bir şekilde pekiştire pekiştire indirdik.', 'وقال الذين كفروا لولا نزل عليه القران جملة وحدة كذلك لنثبت به فوادك ورتلنه ترتيلا'),
(2888, 25, 33, 'وَلَا يَأْتُونَكَ بِمَثَلٍ اِلَّا جِئْنَاكَ بِالْحَقِّ وَاَحْسَنَ تَفْس۪يراًۜ', 'Ve la ye\'tuneke bi meselin illa ci\'nake bil hakkı ve ahsene tefsira.', 'Onların sana verecekleri her örneğe karşılık,  biz sana hakkı en iyi şekilde açıklarız.', 'ولا ياتونك بمثل الا جينك بالحق واحسن تفسيرا'),
(2889, 25, 34, 'اَلَّذ۪ينَ يُحْشَرُونَ عَلٰى وُجُوهِهِمْ اِلٰى جَهَنَّمَۙ اُو۬لٰٓئِكَ شَرٌّ مَكَاناً وَاَضَلُّ سَب۪يلاً۟', 'Ellezine yuhşerune ala vucuhihim ila cehenneme ulaike şerrun mekanen ve edallu sebila.', 'Yüzüstü Cehennem\'e toplanacak olanlar; işte onlar,  yerce çok kötü ve yolca çok sapkınlardır.', 'الذين يحشرون علي وجوههم الي جهنم اوليك شر مكانا واضل سبيلا'),
(2890, 25, 35, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ وَجَعَلْنَا مَعَهُٓ اَخَاهُ هٰرُونَ وَز۪يراًۚ', 'Ve lekad ateyna musel kitabe ve cealna meahu ehahu harune vezira.', 'Ant olsun ki Musa\'ya kitabı verdik. Ve kardeşi Harun\'u da ona yardımcı yaptık.', 'ولقد اتينا موسي الكتب وجعلنا معه اخاه هرون وزيرا'),
(2891, 25, 36, 'فَقُلْنَا اذْهَبَٓا اِلَى الْقَوْمِ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِنَاۜ فَدَمَّرْنَاهُمْ تَدْم۪يراًۜ', 'Fe kulnazheba ilel kavmillezine kezzebu bi ayatina, fe demmernahum tedmira.', 'Sonra da \"Ayetlerimizi yalanlayan o halka gidin.\" dedik. Sonunda da onları helak ederek yok ettik.', 'فقلنا اذهبا الي القوم الذين كذبوا بايتنا فدمرنهم تدميرا'),
(2892, 25, 37, 'وَقَوْمَ نُوحٍ لَمَّا كَذَّبُوا الرُّسُلَ اَغْرَقْنَاهُمْ وَجَعَلْنَاهُمْ لِلنَّاسِ اٰيَةًۜ وَاَعْتَدْنَا لِلظَّالِم۪ينَ عَـذَاباً اَل۪يماًۚ', 'Ve kavme nuhın lemma kezzebur rusule agraknahum ve cealnahum lin nasi ayeh, ve a\'tedna liz zalimine azaben elima.', 'Nuh\'un halkı,  resulleri yalanladıklarında suda boğduk ve onları insanlar için bir ayet[1] yaptık. Ve zalimler için acı veren bir azap hazırladık.', 'وقوم نوح لما كذبوا الرسل اغرقنهم وجعلنهم للناس اية واعتدنا للظلمين عذابا اليما'),
(2893, 25, 38, 'وَعَـاداً وَثَمُودَا۬ وَاَصْحَابَ الرَّسِّ وَقُرُوناً بَيْنَ ذٰلِكَ كَث۪يراً', 'Ve aden ve semuda ve ashaber ressi ve kurunen beyne zalike kesira.', 'Âd\'ı,  Semud\'u,  Ress yandaşlarını ve bunlar arasında yaşayan daha birçok nesilleri de;', 'وعادا وثمودا واصحب الرس وقرونا بين ذلك كثيرا'),
(2894, 25, 39, 'وَكُلاًّ ضَرَبْنَا لَهُ الْاَمْثَالَۘ وَكُلاًّ تَبَّرْنَا تَتْب۪يراً', 'Ve kullen darabna lehul emsale ve kullen tebberna tetbira.', 'Ve onların hepsini örneklerle uyardık ve hepsini mahvederek helak ettik.', 'وكلا ضربنا له الامثل وكلا تبرنا تتبيرا'),
(2895, 25, 40, 'وَلَقَدْ اَتَوْا عَلَى الْقَرْيَةِ الَّت۪ٓي اُمْطِرَتْ مَطَرَ السَّوْءِۜ اَفَلَمْ يَكُونُوا يَرَوْنَهَاۚ بَلْ كَانُوا لَا يَرْجُونَ نُشُوراً', 'Ve lekad atev alel karyetilleti umtırat mataras sev\', e fe lem yekunu yerevneha, bel kanu la yercune nuşura.', 'Ve ant olsun ki onlar,  felaket yağmuru yağdırılmış olan beldeye vardılar. Peki,  onu da mı görmediler? Aksine onlar,  öldükten sonra dirilmeyi beklemiyorlar.', 'ولقد اتوا علي القرية التي امطرت مطر السو افلم يكونوا يرونها بل كانوا لا يرجون نشورا'),
(2896, 25, 41, 'وَاِذَا رَاَوْكَ اِنْ يَتَّخِذُونَكَ اِلَّا هُزُواًۜ اَهٰذَا الَّذ۪ي بَعَثَ اللّٰهُ رَسُولاً', 'Ve iza reavke in yettehızuneke illa huzuva, e hazellezi beasallahu resula.', 'Seni gördükleri zaman: \"Allah\'ın Resul olarak gönderdiği bu mu?\" diye alay konusu ediniyorlar.', 'واذا راوك ان يتخذونك الا هزوا اهذا الذي بعث الله رسولا'),
(2897, 25, 42, 'اِنْ كَادَ لَيُضِلُّنَا عَنْ اٰلِهَتِنَا لَوْلَٓا اَنْ صَبَرْنَا عَلَيْهَاۜ وَسَوْفَ يَعْلَمُونَ ح۪ينَ يَرَوْنَ الْعَذَابَ مَنْ اَضَلُّ سَب۪يلاً', 'İn kade le yudılluna an alihetina lev la en saberna aleyha, ve sevfe ya\'lemune hine yerevnel azabe men edallu sebila.', '\"Şayet ilahlarımıza bağlılıkta kararlı olmasaydık,  neredeyse bizi saptırıyordu.\" diyorlar. Azabı gördükleri zaman kimin sapkın olduğunu bileceklerdir.', 'ان كاد ليضلنا عن الهتنا لولا ان صبرنا عليها وسوف يعلمون حين يرون العذاب من اضل سبيلا'),
(2898, 25, 43, 'اَرَاَيْتَ مَنِ اتَّخَذَ اِلٰهَهُ هَوٰيهُۜ اَفَاَنْتَ تَكُونُ عَلَيْهِ وَك۪يلاًۙ', 'E raeyte menittehaze ilahehu hevah, e fe ente tekunu aleyhi vekila.', 'Hevasını[1] ilah edinen kimseyi görüyorsun! Onun sorumluluğunu sen üstlenebilir misin?', 'اريت من اتخذ الهه هويه افانت تكون عليه وكيلا'),
(2899, 25, 44, 'اَمْ تَحْسَبُ اَنَّ اَكْثَرَهُمْ يَسْمَعُونَ اَوْ يَعْقِلُونَۜ اِنْ هُمْ اِلَّا كَالْاَنْـعَامِ بَلْ هُمْ اَضَلُّ سَب۪يلاً۟', 'Em tahsebu enne ekserehum yesmeune ev ya\'kılun, in hum illa kel en\'ami bel hum edallu sebila.', 'Yoksa onların çoğunun gerçeğe kulak verdiğini veya akıllarını kullandıklarını mı sanıyorsun? Onlar tıpkı hayvanlar gibidir. Hatta doğru yolu seçmede hayvanlardan daha yetersizdirler.', 'ام تحسب ان اكثرهم يسمعون او يعقلون ان هم الا كالانعم بل هم اضل سبيلا'),
(2900, 25, 45, 'اَلَمْ تَرَ اِلٰى رَبِّكَ كَيْفَ مَدَّ الظِّلَّۚ وَلَوْ شَٓاءَ لَجَعَلَهُ سَاكِناًۚ ثُمَّ جَعَلْنَا الشَّمْسَ عَلَيْهِ دَل۪يلاًۙ', 'E lem tere ila rabbike keyfe meddez zıll, ve lev şae le cealehu sakina, summe cealneş şemse aleyhi delila.', 'Rabb\'inin gölgeyi nasıl uzattığını görmez misin? Dileseydi onu sabit kılardı. Sonra da Güneş\'i ona[1] yol gösterici yaptık.', 'الم تر الي ربك كيف مد الظل ولو شا لجعله ساكنا ثم جعلنا الشمس عليه دليلا'),
(2901, 25, 46, 'ثُمَّ قَبَضْنَاهُ اِلَيْنَا قَبْضاً يَس۪يراً', 'Summe kabadnahu ileyna kabdan yesira.', 'Sonra da onu kolayca kendimize çektik.', 'ثم قبضنه الينا قبضا يسيرا'),
(2902, 25, 47, 'وَهُوَ الَّذ۪ي جَعَلَ لَكُمُ الَّيْلَ لِبَاساً وَالنَّوْمَ سُبَاتاً وَجَعَلَ النَّهَارَ نُشُوراً', 'Ve huvellezi ceale lekumul leyle libasen ven nevme subaten ve cealen nehare nuşura.', 'Sizin için geceyi örtü,  uykuyu dinlenme ve gündüzü çalışma zamanı kıldık.', 'وهو الذي جعل لكم اليل لباسا والنوم سباتا وجعل النهار نشورا'),
(2903, 25, 48, 'وَهُوَ الَّـذ۪ٓي اَرْسَلَ الرِّيَاحَ بُشْراً بَيْنَ يَدَيْ رَحْمَتِه۪ۚ وَاَنْزَلْنَا مِنَ السَّمَٓاءِ مَٓاءً طَهُوراًۙ', 'Ve huvellezi erseler riyaha buşren beyne yedey rahmetih, ve enzelna mines semai maen tahura.', 'Rahmetinin önünde rüzgarı haberci olarak gönderen O\'dur. Biz,  gökten tertemiz bir su indirdik.', 'وهو الذي ارسل الريح بشرا بين يدي رحمته وانزلنا من السما ما طهورا'),
(2904, 25, 49, 'لِنُحْيِيَ بِه۪ بَلْدَةً مَيْتاً وَنُسْقِيَهُ مِمَّا خَلَقْنَٓا اَنْعَاماً وَاَنَاسِيَّ كَث۪يراً', 'Li nuhyiye bihi beldeten meyten ve nuskıyehu mimma halakna en\'amen ve enasiyye kesira.', 'Ki o yağmurla ölü bir beldeyi canlandırmak,  yaratmış olduğumuz hayvanları ve insanları suya kavuşturmak içindir.', 'لنحيي به بلدة ميتا ونسقيه مما خلقنا انعما واناسي كثيرا'),
(2905, 25, 50, 'وَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ لِيَذَّكَّرُواۘ  فَاَبٰٓى اَكْثَرُ النَّاسِ اِلَّا كُفُوراً', 'Ve lekad sarrafnahu beynehum li yezzekkeru fe eba ekserun nasi illa kufura.', 'Ant olsun ki Biz,  öğüt almaları için onu,  onların aralarında paylaştırdık. Ancak insanların çoğu nankörlük etmekte direttiler.', 'ولقد صرفنه بينهم ليذكروا فابي اكثر الناس الا كفورا'),
(2906, 25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا ف۪ي كُلِّ قَرْيَةٍ نَذ۪يراًۘ', 'Ve lev şi\'na le beasna fi kulli karyetin nezira.', 'Eğer dileseydik,  elbette her beldeden bir uyarıcı çıkarırdık.', 'ولو شينا لبعثنا في كل قرية نذيرا'),
(2907, 25, 52, 'فَلَا تُطِعِ الْكَافِر۪ينَ وَجَاهِدْهُمْ بِه۪ جِهَاداً كَب۪يراً', 'Fe la tutııl kafirine ve cahidhum bihi cihaden kebira.', 'Öyleyse Kafirlere[1] boyun eğme. Onunla[2] onlara karşı var gücünle büyük bir mücadeleye giriş.', 'فلا تطع الكفرين وجهدهم به جهادا كبيرا'),
(2908, 25, 53, 'وَهُوَ الَّذ۪ي مَرَجَ الْبَحْرَيْنِ هٰذَا عَذْبٌ فُرَاتٌ وَهٰذَا مِلْحٌ اُجَاجٌۚ وَجَعَلَ بَيْنَهُمَا بَرْزَخاً وَحِجْراً مَحْجُوراً', 'Ve huvellezi meracel bahreyni haza azbun furatun ve haza milhun ucac, ve ceale beynehuma, berzehan ve hıcran mahcura.', 'Ve iki denizi serbest bırakan O\'dur; biri lezzetli ve tatlı,  diğeri tuzlu ve acı. Aralarına bir perde koydu. Birbirlerine karışmalarını engelledi.', 'وهو الذي مرج البحرين هذا عذب فرات وهذا ملح اجاج وجعل بينهما برزخا وحجرا محجورا'),
(2909, 25, 54, 'وَهُوَ الَّذ۪ي خَلَقَ مِنَ الْمَٓاءِ بَشَراً فَجَعَلَهُ نَسَباً وَصِهْراًۜ وَكَانَ رَبُّكَ قَد۪يراً', 'Ve huvellezi halaka minel mai beşeren fe cealehu neseben ve sıhra, ve kane rabbuke kadira.', 'O,  beşeri[1] sudan yarattı. Sonra onu,  soy sop ve akraba sahibi kıldı. Senin Rabb\'in her şeye güç yetirendir.', 'وهو الذي خلق من الما بشرا فجعله نسبا وصهرا وكان ربك قديرا'),
(2910, 25, 55, 'وَيَعْبُدُونَ مِنْ دُونِ اللّٰهِ مَا لَا يَنْفَعُهُمْ وَلَا يَضُرُّهُمْۜ وَكَانَ الْكَافِرُ عَلٰى رَبِّه۪ ظَه۪يراً', 'Ve ya\'budune min dunillahi ma la yenfeuhum ve la yadurruhum, ve kanel kafiru ala rabbihi zahira.', 'Allah\'ın yanı sıra kendilerine bir yararı da zararı da olmayan şeylere kulluk ediyorlar. Kafir,  Rabb\'ine karşı olanın destekçisidir.', 'ويعبدون من دون الله ما لا ينفعهم ولا يضرهم وكان الكافر علي ربه ظهيرا'),
(2911, 25, 56, 'وَمَٓا اَرْسَلْنَاكَ اِلَّا مُبَشِّراً وَنَذ۪يراً', 'Ve ma erselnake illa mubeşşiren ve nezira.', 'Biz,  seni haberci ve uyarıcı olmanın dışında başka bir şey için göndermedik.', 'وما ارسلنك الا مبشرا ونذيرا'),
(2912, 25, 57, 'قُلْ مَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍ اِلَّا مَنْ شَٓاءَ اَنْ يَتَّخِذَ اِلٰى رَبِّه۪ سَب۪يلاً', 'Kul ma es\'elukum aleyhi min ecrin illa men şae en yettehıze ila rabbihi sebila.', 'De ki: \"Yaptığım çağrı için; sizden,  Rabbinizin yolunu seçmenizi istemekten başka bir ücret istemiyorum.\"[1]', 'قل ما اسلكم عليه من اجر الا من شا ان يتخذ الي ربه سبيلا'),
(2913, 25, 58, 'وَتَوَكَّلْ عَلَى الْحَيِّ الَّذ۪ي لَا يَمُوتُ وَسَبِّـحْ بِحَمْدِه۪ۜ وَكَفٰى بِه۪ بِذُنُوبِ عِبَادِه۪ خَب۪يراًۚۛ', 'Ve tevekkel alel hayyillezi la yemutu ve sebbih bi hamdih, ve kefa bihi bi zunubi ibadihi habira.', 'Ve sen,  ölümsüz Olan\'a güvenip dayan. Ve O\'nu övgü ile yücelt. O\'nun kullarının suçlarından haberdar olması sana yeter.', 'وتوكل علي الحي الذي لا يموت وسبح بحمده وكفي به بذنوب عباده خبيرا'),
(2914, 25, 59, 'اَلَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَا ف۪ي سِتَّةِ اَيَّامٍ ثُمَّ اسْتَوٰى عَلَى الْعَرْشِۚۛ اَلرَّحْمٰنُ فَسْـَٔلْ بِه۪ خَب۪يراً', 'Ellezi halakas semavati vel arda ve ma beynehuma fi sitteti eyyamin summesteva alel arşir rahmanu fes\'el bihi habira.', 'O; gökleri,  yeri ve ikisinin arasındakileri altı günde[1] yarattı. Sonra arşa isteva etti.[2] O,  Rahman\'dır. Öyleyse her şeyden haberdar olandan iste.', 'الذي خلق السموت والارض وما بينهما في ستة ايام ثم استوي علي العرش الرحمن فسل به خبيرا'),
(2915, 25, 60, 'وَاِذَا ق۪يلَ لَهُمُ اسْجُدُوا لِلرَّحْمٰنِ قَالُوا وَمَا الرَّحْمٰنُۗ اَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُوراً۟', 'Ve iza kile lehumuscudu lir rahmani kalu ve mer rahmanu e nescudu li ma te\'muruna ve zadehum nufura.', 'Ve onlara,  \"Rahman\'a secde[1] edin.\" dendiği zaman,  \"Rahman da neymiş? Senin bize buyurduğun her şeye secde mi edeceğiz?\" dediler. Bu çağrın onların nefretlerini arttırdı.', 'واذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن انسجد لما تامرنا وزادهم نفورا'),
(2916, 25, 61, 'تَبَارَكَ الَّذ۪ي جَعَلَ فِي السَّمَٓاءِ بُرُوجاً وَجَعَلَ ف۪يهَا سِرَاجاً وَقَمَراً مُن۪يراً', 'Tebarekellezi ceale fis semai burucen ve ceale fiha siracen ve kameren munira.', 'Gökte burçlar yapan ve orada bir Çerağ[1] ve aydınlatan Ay\'ı yapan ne mübarektir.[2]', 'تبارك الذي جعل في السما بروجا وجعل فيها سراجا وقمرا منيرا'),
(2917, 25, 62, 'وَهُوَ الَّذ۪ي جَعَلَ الَّيْلَ وَالنَّهَارَ خِلْفَةً لِمَنْ اَرَادَ اَنْ يَذَّكَّرَ اَوْ اَرَادَ شُكُوراً', 'Ve huvellezi cealel leyle ven nehare hılfeten li men erade en yezzekkere ev erade şukura.', 'Ve O,  öğüt almak veya şükretmek isteyenler için gece ile gündüzü art arda getirendir.', 'وهو الذي جعل اليل والنهار خلفة لمن اراد ان يذكر او اراد شكورا'),
(2918, 25, 63, 'وَعِبَادُ الرَّحْمٰنِ الَّذ۪ينَ يَمْشُونَ عَلَى الْاَرْضِ هَوْناً وَاِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَاماً', 'Ve ibadur rahmanillezine yemşune alel ardı hevnen ve iza hatabehumul cahilune kalu selama.', 'Rahman\'ın kulları yeryüzünde alçak gönüllülükle yürürler. Cahiller,  onlara laf attıkları zaman,  \"Selam.\"[1] derler.', 'وعباد الرحمن الذين يمشون علي الارض هونا واذا خاطبهم الجهلون قالوا سلما'),
(2919, 25, 64, 'وَالَّذ۪ينَ يَب۪يتُونَ لِرَبِّهِمْ سُجَّداً وَقِيَاماً', 'Vellezine yebitune li rabbihim succeden ve kıyama.', 'Onlar,  Rabblerinin buyruklarına tabi olmada ve yerine getirmede önlem alırlar ve özenli davranırlar.[1]', 'والذين يبيتون لربهم سجدا وقيما'),
(2920, 25, 65, 'وَالَّذ۪ينَ يَقُولُونَ رَبَّـنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَۗ اِنَّ عَذَابَهَا كَانَ غَرَاماًۗ', 'Vellezine yekulune rabbenasrif anna azabe cehenneme inne azabeha kane garama.', 'Onlar: \"Rabbimiz Cehennem azabını bizden uzaklaştır. Kuşkusuz onun azabı sürekli bir yok oluştur.\" derler.', 'والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما'),
(2921, 25, 66, 'اِنَّهَا سَٓاءَتْ مُسْتَقَراًّ وَمُقَاماً', 'İnneha saet mustekarren ve mukama.', 'Kuşkusuz o,  kötü bir konaklama yeri ve konaktır.', 'انها سات مستقرا ومقاما'),
(2922, 25, 67, 'وَالَّذ۪ينَ اِذَٓا اَنْفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذٰلِكَ قَوَاماً', 'Vellezine iza enfeku lem yusrifu ve lem yakturu ve kane beyne zalike kavama.', 'Onlar,  infak[1] ettikleri zaman israf da cimrilik de etmezler. Bu ikisi arasında bir denge kurarlar.', 'والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما'),
(2923, 25, 68, 'وَالَّذ۪ينَ لَا يَدْعُونَ مَعَ اللّٰهِ اِلٰهاً اٰخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّت۪ي حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّ وَلَا يَزْنُونَۚ وَمَنْ يَفْعَلْ ذٰلِكَ يَلْقَ اَثَاماًۙ', 'Vellezine la yed\'une meallahi ilahen ahara ve la yaktulunen nefselleti harremallahu illa bil hakkı ve la yeznun, ve men yef\'al zalike yelka esama.', 'Onlar,  Allah\'la birlikte başka bir ilaha dua etmezler. Allah\'ın haram kıldığı canı geçerli bir neden olmadıkça öldürmezler. Zina yapmazlar. Kim bunları yaparsa günah işlemiş olur.', 'والذين لا يدعون مع الله الها اخر ولا يقتلون النفس التي حرم الله الا بالحق ولا يزنون ومن يفعل ذلك يلق اثاما'),
(2924, 25, 69, 'يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيٰمَةِ وَيَخْلُدْ ف۪يه۪۫ مُهَاناًۗ', 'Yudaaf lehul azabu yevmel kıyameti ve yahlud fihi muhana.', 'Kıyamet Günü onun azabı katlanır ve orada sürekli horlanmış olarak kalır.', 'يضعف له العذاب يوم القيمة ويخلد فيه مهانا'),
(2925, 25, 70, 'اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ عَمَلاً صَالِحاً فَاُو۬لٰٓئِكَ يُبَدِّلُ اللّٰهُ سَيِّـَٔاتِهِمْ حَسَنَاتٍۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'İlla men tabe ve amene ve amile amelen salihan fe ulaike yubeddilullahu seyyiatihim hasenat, ve kanallahu gafuren rahima.', 'Ancak tevbe eden,  iman edip salihatı yapanlar[1] hariç. Allah onların kötülüklerini iyiliklere çevirir. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'الا من تاب وامن وعمل عملا صلحا فاوليك يبدل الله سياتهم حسنت وكان الله غفورا رحيما'),
(2926, 25, 71, 'وَمَنْ تَابَ وَعَمِلَ صَالِحاً فَاِنَّهُ يَتُوبُ اِلَى اللّٰهِ مَتَاباً', 'Ve men tabe ve amile salihan fe innehu yetubu ilallahi metaba.', 'Kim tevbe eder ve salihatı yaparsa,  kuşkusuz o,  bağışlanmış olarak Allah\'a döner.', 'ومن تاب وعمل صلحا فانه يتوب الي الله متابا'),
(2927, 25, 72, 'وَالَّذ۪ينَ لَا يَشْهَدُونَ الزُّورَۙ وَاِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَاماً', 'Vellezine la yeşhedunez zura ve iza merru bil lagvi merru kirama.', 'Onlar,  yalan yere tanıklık etmezler. Boş ve anlamsız bir şeyle karşılaştıkları zaman,  onurlu ve erdemlice oradan uzaklaşırlar.', 'والذين لا يشهدون الزور واذا مروا باللغو مروا كراما'),
(2928, 25, 73, 'وَالَّذ۪ينَ اِذَا ذُكِّرُوا بِاٰيَاتِ رَبِّهِمْ لَمْ يَخِرُّوا عَلَـيْـهَا صُـماًّ وَعُمْيَـاناً', 'Vellezine iza zukkiru bi ayati rabbihim lem yahırru aleyha summen ve umyanen.', 'Onlara,  Rabblerinin ayetleri hatırlatıldığı zaman,  onlara karşı kör ve sağırmış gibi görmezden gelmezler.', 'والذين اذا ذكروا بايت ربهم لم يخروا عليها صما وعميانا'),
(2929, 25, 74, 'وَالَّذ۪ينَ يَقُولُونَ رَبَّـنَا هَبْ لَنَا مِنْ اَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ اَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّق۪ينَ اِمَاماً', 'Vellezine yekulune rabbena heb lena min ezvacina ve zurriyyatina kurrete a\'yunin vec\'alna lil muttekine imama.', 'Ve onlar,  \"Rabbimiz! Eşlerimizden ve soyumuzdan bize göz aydınlığı bağışla. Ve bizi takva sahiplerine önder yap!\" derler.', 'والذين يقولون ربنا هب لنا من ازوجنا وذريتنا قرة اعين واجعلنا للمتقين اماما'),
(2930, 25, 75, 'اُو۬لٰٓئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ ف۪يهَا تَحِيَّةً وَسَلَاماًۙ', 'Ulaike yuczevnel gurfete bi ma saberu ve yulekkavne fiha tahiyyeten ve selama.', 'İşte onlar,  sabretmelerine karşılık yüksek makamlarla ödüllendirilecekler. Orada saygınlık ve esenlik dilekleriyle karşılanacaklardır.', 'اوليك يجزون الغرفة بما صبروا ويلقون فيها تحية وسلما'),
(2931, 25, 76, 'خَالِد۪ينَ ف۪يهَاۜ حَسُنَتْ مُسْتَقَراًّ وَمُقَاماً', 'Halidine fiha, hasunet mustekarren ve mukama.', 'Sürekli orada kalacaklardır. Orası ne güzel bir konaklama yeri ve konaktır.', 'خلدين فيها حسنت مستقرا ومقاما'),
(2932, 25, 77, 'قُلْ مَا يَعْبَؤُ۬ا بِكُمْ رَبّ۪ي لَوْلَا دُعَٓاؤُ۬كُمْۚ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَاماً', 'Kul ma ya\'beu bikum rabbi lev la duaukum, fe kad kezzebtum fe sevfe yekunu lizama.', 'De ki: \"Başkasına yalvarmanız olmazsa Rabbim sizi ne yapsın?[1]\" Oysaki siz yalanladınız. Bunun karşılığını yakında göreceksiniz.', 'قل ما يعبوا بكم ربي لولا دعاوكم فقد كذبتم فسوف يكون لزاما'),
(2933, 26, 1, 'طٰسٓمٓۜ', 'Ta, sin, mim.', 'Ta,  Sin,  Mim.', 'طسم'),
(2934, 26, 2, 'تِلْكَ اٰيَاتُ الْكِتَابِ الْمُب۪ينِ', 'Tilke ayatul kitabil mubin.', 'Bunlar[1] gerçeği apaçık ortaya koyan Kitap\'ın ayetleridir.[1]', 'تلك ايت الكتب المبين'),
(2935, 26, 3, 'لَعَلَّكَ بَاخِعٌ نَفْسَكَ اَلَّا يَكُونُوا مُؤْمِن۪ينَ', 'Lealleke bahıun nefseke ella yekunu mu\'minin.', 'İman etmiyorlar diye,  adeta kendini helak edeceksin.', 'لعلك بخع نفسك الا يكونوا مومنين'),
(2936, 26, 4, 'اِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَٓاءِ اٰيَةً فَظَلَّتْ اَعْنَاقُهُمْ لَهَا خَاضِع۪ينَ', 'İn neşe\' nunezzil aleyhim mines semai ayeten fe zallet a\'nakuhum leha hadıin.', 'Eğer dileseydik gökten öyle bir ayet[1] indirirdik ki hepsi ona boyun eğmek zorunda kalırdı.[2]', 'ان نشا ننزل عليهم من السما اية فظلت اعنقهم لها خضعين'),
(2937, 26, 5, 'وَمَا يَأْت۪يهِمْ مِنْ ذِكْرٍ مِنَ الرَّحْمٰنِ مُحْدَثٍ اِلَّا كَانُوا عَنْهُ مُعْرِض۪ينَ', 'Ve ma ye\'tihim min zikrin miner rahmani muhdesin illa kanu anhu mu\'ridin.', 'Rahman\'dan kendilerine gelen söze bürünmüş her yeni öğütten yüz çevirdiler.', 'وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين'),
(2938, 26, 6, 'فَقَدْ كَذَّبُوا فَسَيَأْت۪يهِمْ اَنْبٰٓؤُ۬ا مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Fe kad kezzebu fe seye\'tihim enbau ma kanu bihi yestehziun.', 'Sonra da kesin olarak yalanladılar. Fakat alay ettikleri şeyin haberleri yakında onlara gelecek.', 'فقد كذبوا فسياتيهم انبوا ما كانوا به يستهزون'),
(2939, 26, 7, 'اَوَلَمْ يَرَوْا اِلَى الْاَرْضِ كَمْ اَنْبَتْنَا ف۪يهَا مِنْ كُلِّ زَوْجٍ كَر۪يمٍ', 'E ve lem yerev ilel ardı kem enbetna fiha min kulli zevcin kerim.', 'Onlar,  yeryüzünü görmüyorlar mı? Her tür bitkiden çiftler olarak bol bol yetiştirdik.', 'اولم يروا الي الارض كم انبتنا فيها من كل زوج كريم'),
(2940, 26, 8, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ  وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Bunda kesinlikle bir ayet[1] vardır. Ancak onların çoğu iman etmedi.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(2941, 26, 9, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Rabbin,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(2942, 26, 10, 'وَاِذْ نَادٰى رَبُّكَ مُوسٰٓى اَنِ ائْتِ الْقَوْمَ الظَّالِم۪ينَۙ', 'Ve iz nada rabbuke musa eni\'til kavmez zalimin.', 'Bir zamanlar Rabb\'in,  zalim halka gitmesi için Musa\'ya seslenmişti.', 'واذ نادي ربك موسي ان ايت القوم الظلمين'),
(2943, 26, 11, 'قَوْمَ فِرْعَوْنَۜ  اَلَا يَتَّقُونَ', 'Kavme fir\'avn, e la yettekun.', '\"Firavun halkı takva[1] sahibi olmayacak mı?\"', 'قوم فرعون الا يتقون'),
(2944, 26, 12, 'قَالَ رَبِّ اِنّ۪ٓي اَخَافُ اَنْ يُكَذِّبُونِۜ', 'Kale rabbi inni ehafu en yukezzibun.', 'Musa,  \"Rabbim! Beni yalanlamalarından korkuyorum.\" dedi.', 'قال رب اني اخاف ان يكذبون'),
(2945, 26, 13, 'وَيَض۪يقُ صَدْر۪ي وَلَا يَنْطَلِقُ لِسَان۪ي فَاَرْسِلْ اِلٰى هٰرُونَ', 'Ve yadiku sadri ve la yentaliku lisani fe ersil ila harun.', '\"Göğsüm daralır,  dilim dönmez;[1] onun için Harun\'u gönder.\"', 'ويضيق صدري ولا ينطلق لساني فارسل الي هرون'),
(2946, 26, 14, 'وَلَهُمْ عَلَيَّ ذَنْبٌ فَاَخَافُ اَنْ يَقْتُلُونِۚ', 'Ve lehum aleyye zenbun fe ehafu en yaktulun.', '\"Onlara göre ben suçluyum. Bu yüzden beni öldürmelerinden korkuyorum.\"', 'ولهم علي ذنب فاخاف ان يقتلون'),
(2947, 26, 15, 'قَالَ كَلَّاۚ فَاذْهَبَا بِاٰيَاتِنَٓا اِنَّا مَعَكُمْ مُسْتَمِعُونَ', 'Kale kella, fezheba bi ayatina inna meakum mustemiun.', '\"Hayır,  haydi ikiniz ayetlerimizle gidin! Kuşkusuz Biz,  sizinle beraber işitenleriz.[1]\" dedi.', 'قال كلا فاذهبا بايتنا انا معكم مستمعون'),
(2948, 26, 16, 'فَأْتِيَا فِرْعَوْنَ فَقُولَٓا اِنَّا رَسُولُ رَبِّ الْعَالَم۪ينَۙ', 'Fe\'tiya fir\'avne fe kula inna resulu rabbil alemin.', 'Haydi! Firavun\'a gidin ve ona: \"Biz,  Âlemlerin Rabbi\'nin resulleriyiz.\" deyin.', 'فاتيا فرعون فقولا انا رسول رب العلمين'),
(2949, 26, 17, 'اَنْ اَرْسِلْ مَعَنَا بَن۪ٓي اِسْرَٓائ۪لَۜ', 'En ersil meana beni israil.', '\"İsrailoğulları\'nı bizimle beraber gönder!\"', 'ان ارسل معنا بني اسريل'),
(2950, 26, 18, 'قَالَ اَلَمْ نُرَبِّكَ ف۪ينَا وَل۪يداً وَلَبِثْتَ ف۪ينَا مِنْ عُمُرِكَ سِن۪ينَ', 'Kale e lem nurabbike fina veliden ve lebiste fina min umurike sinin.', 'Firavun: \"Çocukken,  seni içimizde himaye edip yetiştirmedik mi? Yıllarca yanımızda kalmadın mı?\"', 'قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين'),
(2951, 26, 19, 'وَفَعَلْتَ فَعْلَتَكَ الَّت۪ي فَعَلْتَ وَاَنْتَ مِنَ الْكَافِر۪ينَ', 'Ve fealte fa\'letekelleti fealte ve ente minel kafirin.', '\"Sen ise yapacağını yaptın. Sen kafirlerdensin.[1]\"', 'وفعلت فعلتك التي فعلت وانت من الكفرين'),
(2952, 26, 20, 'قَالَ فَعَلْتُـهَٓا اِذاً وَاَنَا۬ مِنَ الضَّٓالّ۪ينَۜ', 'Kale fealtuha izen ve ene mined dallin.', 'Musa: \"Ben o işi şaşkınlıkla yaptım.\" dedi.', 'قال فعلتها اذا وانا من الضالين'),
(2953, 26, 21, 'فَفَرَرْتُ مِنْكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ ل۪ي رَبّ۪ي حُكْماً وَجَعَلَن۪ي مِنَ الْمُرْسَل۪ينَ', 'Fe ferartu minkum lemma hıftukum fe vehebe li rabbi hukmen ve cealeni minel murselin.', 'Sizden korktuğum için de hemen kaçtım. Sonra Rabbim bana hikmet[1] bağışladı ve beni resullerden kıldı.', 'ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين'),
(2954, 26, 22, 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ اَنْ عَبَّدْتَ بَن۪ٓي اِسْرَٓائ۪لَۜ', 'Ve tilke ni\'metun temunnuha aleyye en abbedte beni israil.', '\"İsrailoğulları\'nı kendine kul edinmiş olmayı bir nimetmiş gibi başıma kakıyorsun.\"[1] dedi.', 'وتلك نعمة تمنها علي ان عبدت بني اسريل'),
(2955, 26, 23, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَالَم۪ينَ', 'Kale fir\'avnu ve ma rabbul alemin.', 'Firavun: \"Âlemlerin Rabb\'i de nedir?\" dedi.', 'قال فرعون وما رب العلمين'),
(2956, 26, 24, 'قَالَ رَبُّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۜ اِنْ كُنْتُمْ مُوقِن۪ينَ', 'Kale rabbus semavati vel ardı ve ma beynehuma, in kuntum mukınin.', 'Musa: \"Eğer bütün gerçekliği ile doğruyu bilmek istiyorsanız,  bilesiniz ki O,  göklerin,  yerin ve bu ikisi arasında bulunanların Rabb\'idir.\" dedi.', 'قال رب السموت والارض وما بينهما ان كنتم موقنين'),
(2957, 26, 25, 'قَالَ لِمَنْ حَوْلَـهُٓ  اَلَا تَسْتَمِعُونَ', 'Kale li men havlehu e la testemiun.', 'Firavun,  etrafındakilere: \"Duymuyor musunuz?\" dedi.', 'قال لمن حوله الا تستمعون'),
(2958, 26, 26, 'قَالَ رَبُّكُمْ وَرَبُّ اٰبَٓائِكُمُ الْاَوَّل۪ينَ', 'Kale rabbukum ve rabbu abaikumul evvelin.', 'Musa: \"Sizin de Rabbiniz,  sizden önceki atalarınızın da Rabbidir\" dedi.', 'قال ربكم ورب ابايكم الاولين'),
(2959, 26, 27, 'قَالَ اِنَّ رَسُولَكُمُ الَّـذ۪ٓي اُرْسِلَ اِلَيْكُمْ لَمَجْنُونٌ', 'Kale inne resulekumullezi ursile ileykum le mecnun.', 'Firavun: \"Size gönderilmiş olan resulünüz,  gerçekten mecnundur[1].\" dedi.', 'قال ان رسولكم الذي ارسل اليكم لمجنون'),
(2960, 26, 28, 'قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَاۜ اِنْ كُنْتُمْ تَعْقِلُونَ', 'Kale rabbul meşrıkı vel magribi ve ma beynehuma, in kuntum ta\'kılun.', 'Musa: \"Eğer aklınızı kullanırsanız anlayacaksınız ki O,  doğunun,  batının ve ikisinin arasındakilerin Rabb\'idir.\" dedi.', 'قال رب المشرق والمغرب وما بينهما ان كنتم تعقلون'),
(2961, 26, 29, 'قَالَ لَئِنِ اتَّخَذْتَ اِلٰهاً غَيْر۪ي لَاَجْعَلَنَّكَ مِنَ الْمَسْجُون۪ينَ', 'Kale leinittehazte ilahen gayri le ec\'alenneke minel mescunin.', 'Firavun: \"Benden başka bir ilah edinirsen,  kesinlikle seni zindana atarım.\" dedi.', 'قال لين اتخذت الها غيري لاجعلنك من المسجونين'),
(2962, 26, 30, 'قَالَ اَوَلَوْ جِئْتُكَ بِشَيْءٍ مُب۪ينٍ', 'Kale e ve lev ci\'tuke bi şey\'in mubin.', 'Musa: \"Sana apaçık bir şey getirsem de mi?\" dedi.', 'قال اولو جيتك بشي مبين'),
(2963, 26, 31, 'قَالَ فَأْتِ بِه۪ٓ اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Kale fe\'ti bihi in kunte mines sadikin.', 'Firavun: \"Öyleyse haydi getir onu. Eğer doğru söyleyenlerdensen.\" dedi.', 'قال فات به ان كنت من الصدقين'),
(2964, 26, 32, 'فَاَلْقٰى عَصَاهُ فَاِذَا هِيَ ثُعْبَانٌ مُب۪ينٌۚ', 'Fe elka asahu fe iza hiye su\'banun mubin.', 'Bunun üzerine Musa,  asasını bırakıverdi; bir de ne görsünler,  apaçık büyük bir yılan.[1]', 'فالقي عصاه فاذا هي ثعبان مبين'),
(2965, 26, 33, 'وَنَزَعَ يَدَهُ فَاِذَا هِيَ بَيْضَٓاءُ لِلنَّاظِر۪ينَ۟', 'Ve nezea yedehu fe iza hiye beydau lin nazırin.', 'Ve elini çıkardı. Bakanlar ne görsün; beyaz bir el.', 'ونزع يده فاذا هي بيضا للنظرين'),
(2966, 26, 34, 'قَالَ لِلْمَلَأِ حَوْلَـهُٓ اِنَّ هٰذَا لَسَاحِرٌ عَل۪يمٌۙ', 'Kale lil melei havlehu inne haza le sahırun alim.', 'Firavun,  yanındaki melelere[1]: \"Bu gerçekten çok bilgili bir sihirbazdır.\" dedi.', 'قال للملا حوله ان هذا لسحر عليم'),
(2967, 26, 35, 'يُر۪يدُ اَنْ يُخْرِجَكُمْ مِنْ اَرْضِكُمْ بِسِحْرِه۪ۗ فَمَاذَا تَأْمُرُونَ', 'Yuridu en yuhricekum min ardıkum bi sıhrihi fe maza te\'murun.', '\"Sizi sihri ile yurdunuzdan çıkarmak istiyor. Ne yapmamı istiyorsunuz?\" dedi.', 'يريد ان يخرجكم من ارضكم بسحره فماذا تامرون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(2968, 26, 36, 'قَالُٓوا اَرْجِهْ وَاَخَاهُ وَابْعَثْ فِي الْمَدَٓائِنِ حَاشِر۪ينَۙ', 'Kalu ercih ve ehahu veb\'as fil medaini haşirin.', '\"Onu ve kardeşini alıkoy. Şehirlere sihirbazları toplamaya birilerini gönder.\" dediler.', 'قالوا ارجه واخاه وابعث في المداين حشرين'),
(2969, 26, 37, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَل۪يمٍ', 'Ye\'tuke bi kulli sehharin alim.', '\"Bütün bilgili sihirbazları sana getirsinler.\"', 'ياتوك بكل سحار عليم'),
(2970, 26, 38, 'فَجُمِعَ السَّحَرَةُ لِم۪يقَاتِ يَوْمٍ مَعْلُومٍۙ', 'Fe cumias seharatu li mikati yevmin ma\'lum.', 'Böylece sihirbazlar,  belirlenen bir günün tayin edilen vaktinde bir araya getirildiler.', 'فجمع السحرة لميقت يوم معلوم'),
(2971, 26, 39, 'وَق۪يلَ لِلنَّاسِ هَلْ اَنْتُمْ مُجْتَمِعُونَۙ', 'Ve kile lin nasi hel entum muctemiun.', 'İnsanlara: \"Siz de toplananlar olun.\" denildi.', 'وقيل للناس هل انتم مجتمعون'),
(2972, 26, 40, 'لَعَلَّنَا نَتَّبِعُ السَّحَرَةَ اِنْ كَانُوا هُمُ الْغَالِب۪ينَ', 'Leallena nettebius seharate in kanu humul galibin.', '\"Umarız sihirbazlar galip gelir; o zaman biz de onlara tabi oluruz.\"', 'لعلنا نتبع السحرة ان كانوا هم الغلبين'),
(2973, 26, 41, 'فَلَمَّا جَٓاءَ السَّحَرَةُ قَالُوا لِفِرْعَوْنَ اَئِنَّ لَنَا لَاَجْراً اِنْ كُنَّا نَحْنُ الْغَالِب۪ينَ', 'Fe lemma caes seharatu kalu li fir\'avne e inne lena le ecran in kunna nahnul galibin.', 'Sihirbazlar Firavun\'a geldiklerinde: \"Eğer galip gelirsek bize bir ödül var mı?\" dediler.', 'فلما جا السحرة قالوا لفرعون اين لنا لاجرا ان كنا نحن الغلبين'),
(2974, 26, 42, 'قَالَ نَعَمْ وَاِنَّكُمْ اِذاً لَمِنَ الْمُقَرَّب۪ينَ', 'Kale neam ve innekum izen le minel mukarrabin.', '\"Evet; o zaman sizi kesinlikle himayeme alırım.\" dedi.', 'قال نعم وانكم اذا لمن المقربين'),
(2975, 26, 43, 'قَالَ لَهُمْ مُوسٰٓى اَلْقُوا مَٓا اَنْتُمْ مُلْقُونَ', 'Kale lehum musa elku ma entum mulkun.', 'Musa onlara: \"Atacağınız şeyi atın.\" dedi.', 'قال لهم موسي القوا ما انتم ملقون'),
(2976, 26, 44, 'فَاَلْقَوْا حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا بِعِزَّةِ فِرْعَوْنَ اِنَّا لَنَحْنُ الْغَالِبُونَ', 'Fe elkav hıbalehum ve ısıyyehum ve kalu bi izzeti fir\'avne inna le nahnul galibun.', 'Bunun üzerine iplerini ve asalarını attılar. \"Firavunun onuru adına elbette galip gelecekler bizler olacağız.\" dediler.', 'فالقوا حبالهم وعصيهم وقالوا بعزة فرعون انا لنحن الغلبون'),
(2977, 26, 45, 'فَاَلْقٰى مُوسٰى عَصَاهُ فَاِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَۚ', 'Fe elka musa asahu fe iza hiye telkafu ma ye\'fikun.', 'Sonra Musa asasını attı. Birde ne görsünler! Uydurdukları şeyleri yutuyor.', 'فالقي موسي عصاه فاذا هي تلقف ما يافكون'),
(2978, 26, 46, 'فَاُلْقِيَ السَّحَرَةُ سَاجِد۪ينَۙ', 'Fe ulkıyes seharatu sacidin.', 'Sihirbazlar hemen teslimiyetlerini ilan ettiler.', 'فالقي السحرة سجدين'),
(2979, 26, 47, 'قَالُٓوا اٰمَنَّا بِرَبِّ الْعَالَم۪ينَۙ', 'Kalu amenna bi rabbil alemin.', '\"Âlemlerin Rabb\'ine inandık.\" dediler.', 'قالوا امنا برب العلمين'),
(2980, 26, 48, 'رَبِّ مُوسٰى وَهٰرُونَ', 'Rabbi musa ve harun.', '\"Musa ve Harun\'un Rabbine.\"', 'رب موسي وهرون'),
(2981, 26, 49, 'قَالَ اٰمَنْتُمْ لَهُ قَبْلَ اَنْ اٰذَنَ لَكُمْۚ اِنَّهُ لَكَب۪يرُكُمُ الَّذ۪ي عَلَّمَكُمُ السِّحْرَۚ  فَلَسَوْفَ تَعْلَمُونَۜ  لَاُقَطِّعَنَّ اَيْدِيَكُمْ وَاَرْجُلَكُمْ مِنْ خِلَافٍ وَلَاُصَلِّبَنَّكُمْ اَجْمَع۪ينَ', 'Kale amentum lehu kable en azene lekum, innehu le kebirukumullezi allemekumus sıhr, fe le sevfe ta\'lemun, le ukattıanne eydiyekum ve erculekum min hılafin ve le usallibennekum ecmain.', 'Firavun,  \"Ben izin vermeden ona iman mı ettiniz? Kuşkusuz o,  size sihir öğreten hocanızdır. Şunu kesin olarak bilin ki ellerinizi ve ayaklarınızı çaprazlama kestireceğim ve kesinlikle hepinizi astıracağım!\" dedi.', 'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلسوف تعلمون لاقطعن ايديكم وارجلكم من خلف ولاصلبنكم اجمعين'),
(2982, 26, 50, 'قَالُوا لَا ضَيْرَۘ اِنَّٓا اِلٰى رَبِّنَا مُنْقَلِبُونَۚ', 'Kalu la dayra inna ila rabbina munkalibun.', '\"Önemli değil. Nasıl olsa Rabbimize döneceğiz.\" dediler.', 'قالوا لا ضير انا الي ربنا منقلبون'),
(2983, 26, 51, 'اِنَّا نَطْمَعُ اَنْ يَغْفِرَ لَنَا رَبُّنَا خَطَايَانَٓا اَنْ كُنَّٓا اَوَّلَ الْمُؤْمِن۪ينَۜ۟', 'İnna natmeu en yagfira lena rabbuna hatayana en kunna evvelel mu\'minin.', '\"İlk Mu\'minler olduğumuz için,  Rabb\'imizin yanlışlarımızı bağışlayacağını ümit ediyoruz.\" dediler.', 'انا نطمع ان يغفر لنا ربنا خطينا ان كنا اول المومنين'),
(2984, 26, 52, 'وَاَوْحَيْنَٓا اِلٰى مُوسٰٓى اَنْ اَسْرِ بِعِبَاد۪ٓي اِنَّكُمْ مُتَّبَعُونَ', 'Ve evhayna ila musa en esri bi ıbadi innekum muttebeun.', 'Musa\'ya: \"Kullarım ile gece yola çık. Kesinlikle siz takip edileceksiniz.\" diye vahyettik.', 'واوحينا الي موسي ان اسر بعبادي انكم متبعون'),
(2985, 26, 53, 'فَاَرْسَلَ فِرْعَوْنُ فِي الْمَدَٓائِنِ حَاشِر۪ينَۚ', 'Fe ersele fir\'avnu fil medaini haşirin.', 'Derken Firavun,  şehirlere toplayıcılar gönderdi.', 'فارسل فرعون في المداين حشرين'),
(2986, 26, 54, 'اِنَّ هٰٓؤُ۬لَٓاءِ لَشِرْذِمَةٌ قَل۪يلُونَۙ', 'İnne haulai le şirzimetun kalilun.', '\"Bunlar önemsiz bir topluluktur.\"', 'ان هولا لشرذمة قليلون'),
(2987, 26, 55, 'وَاِنَّهُمْ لَنَا لَـغَٓائِظُونَۙ', 'Ve innehum lena le gaizun.', '\"Ve bize karşı kin ve nefret duyuyorlar.\"', 'وانهم لنا لغايظون'),
(2988, 26, 56, 'وَاِنَّا لَجَم۪يعٌ حَاذِرُونَۜ', 'Ve inna le cemiun hazirun.', '\"Biz ise hazırlıklı bir topluluğuz.\"', 'وانا لجميع حذرون'),
(2989, 26, 57, 'فَاَخْرَجْنَاهُمْ مِنْ جَنَّاتٍ وَعُيُونٍۙ', 'Fe ahracnahum min cennatin ve uyun.', 'Derken onları cennetlerden[1] ve çeşmelerden çıkardık.', 'فاخرجنهم من جنت وعيون'),
(2990, 26, 58, 'وَكُنُوزٍ وَمَقَامٍ كَر۪يمٍۙ', 'Ve kunuzin ve makamin kerim.', 'Ve hazinelerden ve kerim[1] makamlardan.', 'وكنوز ومقام كريم'),
(2991, 26, 59, 'كَذٰلِكَۜ وَاَوْرَثْنَاهَا بَن۪ٓي اِسْرَٓائ۪لَۚ', 'Kezalik, ve evresnaha beni israil.', 'İşte böylece onlara İsrailoğulları\'nı varis kıldık.', 'كذلك واورثنها بني اسريل'),
(2992, 26, 60, 'فَاَتْبَعُوهُمْ مُشْرِق۪ينَ', 'Fe etbeuhum muşrikin.', 'Gün doğarken onların ardına düştüler.', 'فاتبعوهم مشرقين'),
(2993, 26, 61, 'فَلَمَّا تَـرَٓاءَ الْجَمْعَانِ قَالَ اَصْحَابُ مُوسٰٓى اِنَّا لَمُدْرَكُونَۚ', 'Fe lemma terael cem\'ani kale ashabu musa inna le mudrakun.', 'İki topluluk birbirini görünce,  Musa\'nın taraftarları,  \"İşte şimdi yakalandık.\" dediler.', 'فلما ترا الجمعان قال اصحب موسي انا لمدركون'),
(2994, 26, 62, 'قَالَ كَلَّاۚ اِنَّ مَعِيَ رَبّ۪ي سَيَهْد۪ينِ', 'Kale kella, inne maiye rabbi seyehdin.', 'Musa: \"Hayır,  endişelenmeyin! Kuşkusuz Rabb\'im benimledir. Bana yol gösterecektir.\" dedi.', 'قال كلا ان معي ربي سيهدين'),
(2995, 26, 63, 'فَاَوْحَيْنَٓا اِلٰى مُوسٰٓى اَنِ اضْرِبْ بِعَصَاكَ الْبَحْرَۜ فَانْفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظ۪يمِۚ', 'Fe evhayna ila musa enıdrib bi asakel bahr, fenfeleka fe kane kullu firkın ket tavdil azim.', 'Musa\'ya,  \"Asanı denize vur.\" diye vahyettik. Deniz hemen yarıldı. Her bir parçası büyük,  yüksek bir dağ gibiydi.', 'فاوحينا الي موسي ان اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم'),
(2996, 26, 64, 'وَاَزْلَفْنَا ثَمَّ الْاٰخَر۪ينَۚ', 'Ve ezlefna semmel aharin.', 'Diğerlerini[1] de oraya yaklaştırdık.', 'وازلفنا ثم الاخرين'),
(2997, 26, 65, 'وَاَنْجَيْنَا مُوسٰى وَمَنْ مَعَهُٓ اَجْمَع۪ينَۚ', 'Ve enceyna musa ve men meahu ecmain.', 'Musa ve beraberinde olanların hepsini kurtardık.', 'وانجينا موسي ومن معه اجمعين'),
(2998, 26, 66, 'ثُمَّ اَغْرَقْنَا الْاٰخَر۪ينَۜ', 'Summe agraknel aharin.', 'Sonra da diğerlerini boğduk.', 'ثم اغرقنا الاخرين'),
(2999, 26, 67, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Kuşkusuz bunda bir ayet[1] vardır. Buna rağmen onların çokları inanmamaktadır.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(3000, 26, 68, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Kuşkusuz Rabbin,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3001, 26, 69, 'وَاتْلُ عَلَيْهِمْ نَبَاَ اِبْرٰه۪يمَۢ', 'Vetlu aleyhim nebee ibrahim.', 'Onlara İbrahim\'in haberini anlat.', 'واتل عليهم نبا ابرهيم'),
(3002, 26, 70, 'اِذْ قَالَ لِاَب۪يهِ وَقَوْمِه۪ مَا تَعْبُدُونَ', 'İz kale li ebihi ve kavmihi ma ta\'budun.', 'Babasına ve halkına; \"Siz neye kulluk ediyorsunuz?\" demişti.', 'اذ قال لابيه وقومه ما تعبدون'),
(3003, 26, 71, 'قَالُوا نَعْبُدُ اَصْنَاماً فَنَظَلُّ لَهَا عَاكِف۪ينَ', 'Kalu na\'budu asnamen fe nezallu leha akifin.', '\"Putlara kulluk ediyoruz. Kendimizi onlara adamaktan vazgeçmeyeceğiz.\" dediler.', 'قالوا نعبد اصناما فنظل لها عكفين'),
(3004, 26, 72, 'قَالَ هَلْ يَسْمَعُونَكُمْ اِذْ تَدْعُونَۙ', 'Kale hel yesmeunekum iz ted\'un.', 'İbrahim: \"Onlara dua ettiğiniz zaman sizi işitiyorlar mı?\" dedi.', 'قال هل يسمعونكم اذ تدعون'),
(3005, 26, 73, 'اَوْ يَنْفَعُونَكُمْ اَوْ يَضُرُّونَ', 'Ev yenfeunekum ev yedurrun.', '\"Veya size bir yararları ya da zararları oluyor mu?\"', 'او ينفعونكم او يضرون'),
(3006, 26, 74, 'قَالُوا بَلْ وَجَدْنَٓا اٰبَٓاءَنَا كَذٰلِكَ يَفْعَلُونَ', 'Kalu bel vecedna abaena kezalike yef\'alun.', 'Onlar: \"Ama atalarımızı böyle yaparlarken bulduk.\" dediler.', 'قالوا بل وجدنا ابانا كذلك يفعلون'),
(3007, 26, 75, 'قَالَ اَفَرَاَيْتُمْ مَا كُنْتُمْ تَعْبُدُونَۙ', 'Kale e fe raeytum ma kuntum ta\'budun.', 'İbrahim: \"Peki neye kulluk ettiğinizi hiç düşünüyor musunuz?\" dedi.', 'قال افريتم ما كنتم تعبدون'),
(3008, 26, 76, 'اَنْتُمْ وَاٰبَٓاؤُ۬كُمُ الْاَقْدَمُونَ', 'Entum ve abaukumul akdemun.', '\"Siz ve geçmiş atalarınız.\"', 'انتم واباوكم الاقدمون'),
(3009, 26, 77, 'فَاِنَّهُمْ عَدُوٌّ ل۪ٓي اِلَّا رَبَّ الْعَالَم۪ينَۙ', 'Fe innehum aduvvun li illa rabbel alemin.', '\"Yalnızca Âlemlerin Rabbi (dostumdur). O\'nun dışındakilerin hepsi benim düşmanımdır.\"', 'فانهم عدو لي الا رب العلمين'),
(3010, 26, 78, 'اَلَّذ۪ي خَلَقَن۪ي فَهُوَ يَهْد۪ينِۙ', 'Ellezi halakani fe huve yehdin.', '\"Beni yaratan ve yol gösteren O\'dur.\"', 'الذي خلقني فهو يهدين'),
(3011, 26, 79, 'وَالَّذ۪ي هُوَ يُطْعِمُن۪ي وَيَسْق۪ينِۙ', 'Vellezi huve yut\'ımuni ve yeskin.', '\"O\'dur beni yediren ve içiren.\"', 'والذي هو يطعمني ويسقين'),
(3012, 26, 80, 'وَاِذَا مَرِضْتُ فَهُوَ يَشْف۪ينِۖ', 'Ve iza maridtu fe huve yeşfin.', '\"Hastalandığım zaman,  O\'dur bana şifa veren.\"', 'واذا مرضت فهو يشفين'),
(3013, 26, 81, 'وَالَّذ۪ي يُم۪يتُن۪ي ثُمَّ يُحْي۪ينِۙ', 'Vellezi yumituni summe yuhyin.', '\"Beni öldürecek ve tekrar diriltecek olan O\'dur.\"', 'والذي يميتني ثم يحيين'),
(3014, 26, 82, 'وَالَّـذ۪ٓي اَطْمَعُ اَنْ يَغْفِرَ ل۪ي خَط۪ٓيـَٔت۪ي يَوْمَ الدّ۪ينِۜ', 'Vellezi atmeu en yagfira li hatieti yevmed din.', '\"Ve Din Günü[1] yanlışımı bağışlayacağını umduğum O\'dur.\"', 'والذي اطمع ان يغفر لي خطيتي يوم الدين'),
(3015, 26, 83, 'رَبِّ هَبْ ل۪ي حُكْماً وَاَلْحِقْن۪ي بِالصَّالِح۪ينَۙ', 'Rabbi heb li hukmen ve elhıkni bis salihin.', '\"Rabb\'im bana karşılıksız hüküm ver[1] ve beni salihlerin[2] arasına dahil et.\"', 'رب هب لي حكما والحقني بالصلحين'),
(3016, 26, 84, 'وَاجْعَلْ ل۪ي لِسَانَ صِدْقٍ فِي الْاٰخِر۪ينَۙ', 'Vec\'al li lisane sıdkın fil ahırin.', '\"Ve sonrakiler arasında güzel bir ün ile anılmamı nasip et.\"', 'واجعل لي لسان صدق في الاخرين'),
(3017, 26, 85, 'وَاجْعَلْن۪ي مِنْ وَرَثَةِ جَنَّةِ النَّع۪يمِۙ', 'Vec\'alni min veraseti cennetin naim.', '\"Ve beni nimeti bol Cennet\'in mirasçılarından kıl.\"', 'واجعلني من ورثة جنة النعيم'),
(3018, 26, 86, 'وَاغْفِرْ  لِاَب۪ٓي اِنَّهُ  كَانَ مِنَ الضَّٓالّ۪ينَۙ', 'Vagfir li ebi innehu kane mined dallin.', '\"Babamı bağışla,  o sapkınlardandır.\"', 'واغفر لابي انه كان من الضالين'),
(3019, 26, 87, 'وَلَا تُخْزِن۪ي يَوْمَ يُبْعَثُونَۙ', 'Ve la tuhzini yevme yub\'asun.', '\"Yeniden dirilme gününde beni utandırma.\"', 'ولا تخزني يوم يبعثون'),
(3020, 26, 88, 'يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَۙ', 'Yevme la yenfau malun ve la benun.', '\"Evladın ve malın yarar sağlamadığı gün.\"', 'يوم لا ينفع مال ولا بنون'),
(3021, 26, 89, 'اِلَّا مَنْ اَتَى اللّٰهَ بِقَلْبٍ سَل۪يمٍۜ', 'İlla men etallahe bi kalbin selim.', '\"Allah\'a selim[1] bir kalple gelenler hariç.\"', 'الا من اتي الله بقلب سليم'),
(3022, 26, 90, 'وَاُزْلِفَتِ الْجَنَّةُ لِلْمُتَّق۪ينَۙ', 'Ve uzlifetil cennetu lil muttekin.', 'Ve Cennet,  takva sahipleri için yaklaştırılır.', 'وازلفت الجنة للمتقين'),
(3023, 26, 91, 'وَبُرِّزَتِ الْجَح۪يمُ لِلْغَاو۪ينَۙ', 'Ve burrizetil cahimu lil gavin.', 'Ve Cehennem azgınların karşısına çıkarılır.', 'وبرزت الجحيم للغاوين'),
(3024, 26, 92, 'وَق۪يلَ لَهُمْ اَيْنَ مَا كُنْتُمْ تَعْبُدُونَۙ', 'Ve kile lehum eyne ma kuntum ta\'budun.', 'Ve onlara: \"Kulluk ettikleriniz nerede?\" denilir.', 'وقيل لهم اين ما كنتم تعبدون'),
(3025, 26, 93, 'مِنْ دُونِ اللّٰهِۜ هَلْ يَنْصُرُونَكُمْ اَوْ يَنْتَصِرُونَۜ', 'Min dunillah, hel yensurunekum ev yentesırun.', '\"Allah\'tan başka size yardım edebilecek var mı? Veya kendilerine bir yararları olabilir mi?', 'من دون الله هل ينصرونكم او ينتصرون'),
(3026, 26, 94, 'فَكُبْكِبُوا ف۪يهَا هُمْ وَالْغَاوُ۫نَۙ', 'Fe kubkıbu fiha hum vel gavun.', 'Arkasından onlar ve azgınlar[1] onun içine tepetaklak atılacaklar.', 'فكبكبوا فيها هم والغاون'),
(3027, 26, 95, 'وَجُنُودُ اِبْل۪يسَ اَجْمَعُونَۜ', 'Ve cunudu iblise ecmeun.', 'Ve iblisin bütün askerleri.', 'وجنود ابليس اجمعون'),
(3028, 26, 96, 'قَالُوا وَهُمْ ف۪يهَا يَخْتَصِمُونَۙ', 'Kalu ve hum fiha yahtesımun.', 'Onlar,  orada birbirleriyle çekişerek diyecekler ki:', 'قالوا وهم فيها يختصمون'),
(3029, 26, 97, 'تَاللّٰهِ اِنْ كُنَّا لَف۪ي ضَلَالٍ مُب۪ينٍۙ', 'Tallahi in kunna le fi dalalin mubin.', '\"Allah\'a yemin olsun ki,  biz apaçık bir sapkınlık içindeymişiz.\"', 'تالله ان كنا لفي ضلل مبين'),
(3030, 26, 98, 'اِذْ نُسَوّ۪يكُمْ بِرَبِّ الْعَالَم۪ينَ', 'İz nusevvikum bi rabbil alemin.', '\"Çünkü sizi Âlemlerin Rabb\'i ile bir tutuyorduk.\"', 'اذ نسويكم برب العلمين'),
(3031, 26, 99, 'وَمَٓا اَضَلَّـنَٓا اِلَّا الْمُجْرِمُونَ', 'Ve ma edallena illel mucrimun.', '\"Ve bizi hep o mucrimler[1] saptırdı.\"', 'وما اضلنا الا المجرمون'),
(3032, 26, 100, 'فَمَا لَنَا مِنْ شَافِع۪ينَۙ', 'Fe ma lena min şafiin.', '\"Artık şefaat[1] edecek kimsemiz de yok.\"', 'فما لنا من شفعين'),
(3033, 26, 101, 'وَلَا صَد۪يقٍ حَم۪يمٍ', 'Ve la sadikın hamim.', '\"Gerçek bir dostumuz da.\"', 'ولا صديق حميم'),
(3034, 26, 102, 'فَلَوْ اَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ الْمُؤْمِن۪ينَ', 'Fe lev enne lena kerraten fe nekune minel mu\'minin.', '\"Keşke bizim için geri dönüş olsaydı da biz de inananlardan olsaydık.\"', 'فلو ان لنا كرة فنكون من المومنين'),
(3035, 26, 103, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Bunda[1] bir ayet[2] vardır. Buna rağmen onların çoğu inanmamaktadırlar.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(3036, 26, 104, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Kuşkusuz senin Rabbin Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3037, 26, 105, 'كَذَّبَتْ قَوْمُ نُوحٍۨ الْمُرْسَل۪ينَۚ', 'Kezzebet kavmu nuhınil murselin.', 'Nuh halkı gönderilmişleri[1] yalanladı.', 'كذبت قوم نوح المرسلين'),
(3038, 26, 106, 'اِذْ قَالَ لَهُمْ اَخُوهُمْ نُوحٌ اَلَا تَتَّقُونَۚ', 'İz kale lehum ehuhum nuhun e la tettekun.', 'Kardeşleri Nuh onlara: \"Takva sahibi olmayacak mısınız?\" demişti.', 'اذ قال لهم اخوهم نوح الا تتقون'),
(3039, 26, 107, 'اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'İnni lekum resulun emin.', '\"Sizin için güvenilir bir Resulüm.\"', 'اني لكم رسول امين'),
(3040, 26, 108, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Öyleyse Allah için takva[1] sahibi olun ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3041, 26, 109, 'وَمَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍۚ اِنْ اَجْرِيَ اِلَّا عَلٰى رَبِّ الْعَالَم۪ينَۚ', 'Ve ma es\'elukum aleyhi min ecr, in ecriye illa ala rabbil alemin.', '\"Buna karşılık sizden bir ücret istemiyorum. Benim ücretim yalnızca alemlerin Rabb\'ine aittir.\"', 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين'),
(3042, 26, 110, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۜ', 'Fettekullahe ve etiun.', '\"Öyleyse Allah için takva sahibi olun ve bana tabi olun.\"', 'فاتقوا الله واطيعون'),
(3043, 26, 111, 'قَالُٓوا اَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْاَرْذَلُونَۜ', 'Kalu e nu\'minu leke vettebeakel erzelun.', '\"Toplumun en yoksun kesimi sana uymaktayken,  biz kendimizi onlarla bir tutup sana inanır mıyız?\" dediler.', 'قالوا انومن لك واتبعك الارذلون'),
(3044, 26, 112, 'قَالَ وَمَا عِلْم۪ي بِمَا كَانُوا يَعْمَلُونَۚ', 'Kale ve ma ilmi bima kanu ya\'melun.', '\"Onların tercihlerini belirleyici ben değilim.[1]\" dedi.', 'قال وما علمي بما كانوا يعملون'),
(3045, 26, 113, 'اِنْ حِسَابُهُمْ اِلَّا عَلٰى رَبّ۪ي لَوْ تَشْعُرُونَۚ', 'İn hısabuhum illa ala rabbi lev teş\'urun.', '\"Onların hesabı ancak Rabbime aittir. Eğer düşünürseniz gerçeği anlarsınız.\"', 'ان حسابهم الا علي ربي لو تشعرون'),
(3046, 26, 114, 'وَمَٓا اَنَا۬ بِطَارِدِ الْمُؤْمِن۪ينَۚ', 'Ve ma ene bi taridil mu\'minin.', '\"İnananları kovacak değilim.\"', 'وما انا بطارد المومنين'),
(3047, 26, 115, 'اِنْ اَنَا۬ اِلَّا نَذ۪يرٌ مُب۪ينٌۜ', 'İn ene illa nezirun mubin.', '\"Ben,  yalnızca apaçık bir uyarıcıyım.\"', 'ان انا الا نذير مبين'),
(3048, 26, 116, 'قَالُوا لَئِنْ لَمْ تَنْتَهِ۬ يَا نُوحُ لَتَكُونَنَّ مِنَ الْمَرْجُوم۪ينَۜ', 'Kalu le in lem tentehi ya nuhule tekunenne minel mercumin.', '\"Ey Nuh! Eğer kesin olarak vazgeçmezsen,  iyi bil ki,  kesinlikle taşlananlardan[1] olursun!\" dediler.', 'قالوا لين لم تنته ينوح لتكونن من المرجومين'),
(3049, 26, 117, 'قَالَ رَبِّ اِنَّ قَوْم۪ي كَذَّبُونِۚ', 'Kale rabbi inne kavmi kezzebun.', '\"Rabbim! Halkım beni yalanladı.\" dedi.', 'قال رب ان قومي كذبون'),
(3050, 26, 118, 'فَافْتَحْ بَيْن۪ي وَبَيْنَهُمْ فَتْحاً وَنَجِّن۪ي وَمَنْ مَعِيَ مِنَ الْمُؤْمِن۪ينَ', 'Feftah beyni ve beynehum fethan ve neccini ve men maiye minel mu\'minin.', '\"Artık benim onlarla işimi tamamen bitir. Beni ve benimle beraber iman edenleri kurtar.\" dedi.', 'فافتح بيني وبينهم فتحا ونجني ومن معي من المومنين'),
(3051, 26, 119, 'فَاَنْجَيْنَاهُ وَمَنْ مَعَهُ فِي الْفُلْكِ الْمَشْحُونِۚ', 'Fe enceynahu ve men meahu fil fulkil meşhun.', 'Bunun üzerine onu ve onunla birlikte olanları dolan gemide kurtardık.', 'فانجينه ومن معه في الفلك المشحون'),
(3052, 26, 120, 'ثُمَّ اَغْرَقْنَا بَعْدُ الْبَاق۪ينَۜ', 'Summe agrakna ba\'dul bakin.', 'Sonra geride kalanları boğduk.', 'ثم اغرقنا بعد الباقين'),
(3053, 26, 121, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Bunda kesinlikle bir ayet[1] vardır. Yine de onların çoğu iman edenlerden olmadı.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(3054, 26, 122, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Rabbin,  elbette Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3055, 26, 123, 'كَذَّبَتْ عَادٌۨ الْمُرْسَل۪ينَۚ', 'Kezzebet adunil murselin.', 'Âd halkı gönderilmişleri[1] yalanladı.', 'كذبت عاد المرسلين'),
(3056, 26, 124, 'اِذْ قَالَ لَهُمْ اَخُوهُمْ هُودٌ اَلَا تَتَّقُونَۚ', 'İz kale lehum ehuhum hudun e la tettekun.', 'Kardeşleri Hud onlara: \"Takva sahibi olmayacak mısınız?\" demişti.', 'اذ قال لهم اخوهم هود الا تتقون'),
(3057, 26, 125, 'اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'İnni lekum resulun emin.', '\"Sizin için güvenilir bir resulüm.\"', 'اني لكم رسول امين'),
(3058, 26, 126, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Öyleyse Allah için takva sahibi olun ve bana tabi olun.\"', 'فاتقوا الله واطيعون'),
(3059, 26, 127, 'وَمَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍۚ  اِنْ اَجْرِيَ اِلَّا عَلٰى رَبِّ الْعَالَم۪ينَۜ', 'Ve ma es\'elukum aleyhi min ecr, in ecriye illa ala rabbil alemin.', '\"Buna karşılık sizden bir ücret istemiyorum. Benim ücretim yalnızca alemlerin Rabb\'ine aittir.\"', 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين'),
(3060, 26, 128, 'اَتَبْنُونَ بِكُلِّ ر۪يعٍ اٰيَةً تَعْبَثُونَۙ', 'E tebnune bi kulli riın ayeten ta\'besun.', '\"Her yüksek tepeye ayet[1] bina ederek mi oyalanıyorsunuz?\"', 'اتبنون بكل ريع اية تعبثون'),
(3061, 26, 129, 'وَتَتَّخِذُونَ مَصَانِـعَ لَعَلَّكُمْ تَخْلُدُونَۚ', 'Ve tettehızune mesania leallekum tahludun.', '\"Hiç ölmeyeceğinizi sanarak sağlam yapılar ediniyorsunuz.\"', 'وتتخذون مصانع لعلكم تخلدون'),
(3062, 26, 130, 'وَاِذَا بَطَشْتُمْ بَطَشْتُمْ جَبَّار۪ينَۚ', 'Ve iza betaştum betaştum cebbarin.', '\"Elinize imkan geçtiği zaman,  onu zorbaca kullanıyorsunuz.\"', 'واذا بطشتم بطشتم جبارين'),
(3063, 26, 131, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Gelin Allah\'a karşı takva sahibi olun. Ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3064, 26, 132, 'وَاتَّقُوا الَّـذ۪ٓي اَمَدَّكُمْ بِمَا تَعْلَمُونَۚ', 'Vettekullezi emeddekum bima ta\'lemun.', '\"Bildiğiniz şeylerle[1] size yardım edene karşı takva sahibi olun.\"', 'واتقوا الذي امدكم بما تعلمون'),
(3065, 26, 133, 'اَمَدَّكُمْ بِاَنْعَامٍ وَبَن۪ينَۙ', 'Emeddekum bi en\'amin ve benin.', '\"Size davarlarla,  evlatlarla yardım etti.\"', 'امدكم بانعم وبنين'),
(3066, 26, 134, 'وَجَنَّاتٍ وَعُيُونٍۚ', 'Ve cennatin ve uyun.', '\"Ve bahçelerle ve pınarlarla.\"', 'وجنت وعيون'),
(3067, 26, 135, 'اِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ۪يمٍۜ', 'İnni ehafu aleykum azabe yevmin azim.', '\"Ben sizin için büyük bir günün azabından korkuyorum.\"', 'اني اخاف عليكم عذاب يوم عظيم'),
(3068, 26, 136, 'قَالُوا سَوَٓاءٌ عَلَيْنَٓا اَوَعَظْتَ اَمْ لَمْ تَكُنْ مِنَ الْوَاعِظ۪ينَۙ', 'Kalu sevaun aleyna e vaazte em lem tekun minel vaızin.', '\"Bize öğüt versen de veya öğüt verenlerden olmasan da bizim için birdir.\" dediler.', 'قالوا سوا علينا اوعظت ام لم تكن من الوعظين'),
(3069, 26, 137, 'اِنْ هٰذَٓا اِلَّا خُلُقُ الْاَوَّل۪ينَۙ', 'İn haza illa hulukul evvelin.', '\"Bu öncekilerin uydurmasından başka bir şey değildir.\"', 'ان هذا الا خلق الاولين'),
(3070, 26, 138, 'وَمَا نَحْنُ بِمُعَذَّب۪ينَۚ', 'Ve ma nahnu bi muazzebin.', '\"Biz,  azaba uğratılacak da değiliz.\"', 'وما نحن بمعذبين'),
(3071, 26, 139, 'فَكَذَّبُوهُ فَاَهْلَكْنَاهُمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'Fe kezzebuhu fe ehleknahum, inne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Onu[1] yalanladılar. Bunun üzerine onları helak ettik. Bunda bir ayet[2] vardır. Buna rağmen insanların pek çoğu inanmamaktadırlar.', 'فكذبوه فاهلكنهم ان في ذلك لاية وما كان اكثرهم مومنين'),
(3072, 26, 140, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Rabb\'in; Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3073, 26, 141, 'كَذَّبَتْ ثَمُودُ الْمُرْسَل۪ينَۚ', 'Kezzebet semudul murselin.', 'Semud halkı gönderilmişleri[1] yalanladı.', 'كذبت ثمود المرسلين'),
(3074, 26, 142, 'اِذْ قَالَ لَهُمْ اَخُوهُمْ صَالِحٌ اَلَا تَتَّقُونَۚ', 'İz kale lehum ehuhum salihun e la tettekun.', 'Hani! Kardeşleri Salih onlara: \"Takva sahibi olmayacak mısınız?\" demişti.', 'اذ قال لهم اخوهم صلح الا تتقون'),
(3075, 26, 143, 'اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'İnni lekum resulun emin.', '\"Sizin için güvenilir bir Resulüm.\"', 'اني لكم رسول امين'),
(3076, 26, 144, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Allah için takva sahibi olun ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3077, 26, 145, 'وَمَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍۚ اِنْ اَجْرِيَ اِلَّا عَلٰى رَبِّ الْعَالَم۪ينَۜ', 'Ve ma es\'elukum aleyhi min ecr, in ecriye illa ala rabbil alemin.', '\"Buna karşılık sizden bir ücret istemiyorum. Benim ücretim yalnızca alemlerin Rabbine aittir.\"', 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين'),
(3078, 26, 146, 'اَتُتْرَكُونَ ف۪ي مَا هٰهُنَٓا اٰمِن۪ينَۙ', 'E tutrakune fi ma hahuna aminin.', '\"Siz burada; bulunduğunuz yerde hep güven içinde bırakılacak mısınız?\"', 'اتتركون في ما ههنا امنين'),
(3079, 26, 147, 'ف۪ي جَنَّاتٍ وَعُيُونٍۙ', 'Fi cennatin ve uyun.', '\"Cennetlerde[1] ve çeşme başlarında.\"', 'في جنت وعيون'),
(3080, 26, 148, 'وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَض۪يمٌۚ', 'Ve zuruın ve nahlin tal\'uha hedim.', '\"Ekinliklerde ve salkımlı hurmalıklarda.\"', 'وزروع ونخل طلعها هضيم'),
(3081, 26, 149, 'وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتاً فَارِه۪ينَۚ', 'Ve tenhıtune minel cibali buyuten farihin.', '\"Ve dağlardan ustalıkla yonttuğunuz evlerde.\"', 'وتنحتون من الجبال بيوتا فرهين'),
(3082, 26, 150, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Allah için takvalı[1] olun ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3083, 26, 151, 'وَلَا تُط۪يعُٓوا اَمْرَ الْمُسْرِف۪ينَۙ', 'Ve la tutiu emral musrifin.', '\"Ve müsriflerin[1] buyruklarına uymayın.\"', 'ولا تطيعوا امر المسرفين'),
(3084, 26, 152, 'اَلَّذ۪ينَ يُفْسِدُونَ فِي الْاَرْضِ وَلَا يُصْلِحُونَ', 'Ellezine yufsidune fil ardı ve la yuslihun.', '\"Onlar,  yeryüzünde bozgunculuk yapıyorlar,  düzeltmiyorlar.\"', 'الذين يفسدون في الارض ولا يصلحون'),
(3085, 26, 153, 'قَالُٓوا اِنَّـمَٓا اَنْتَ مِنَ الْمُسَحَّر۪ينَۚ', 'Kalu innema ente minel musahharin.', '\"Sen kesinlikle büyülenmişlerdensin.\" dediler.', 'قالوا انما انت من المسحرين'),
(3086, 26, 154, 'مَٓا اَنْتَ اِلَّا بَشَرٌ مِثْلُنَاۚ فَأْتِ بِاٰيَةٍ اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Ma ente illa beşerun misluna, fe\'ti bi ayetin in kunte mines sadikin.', '\"Sen de ancak bizim gibi bir beşersin[1]. Eğer doğru söyleyenlerden isen bize bir ayet[2]getir.\"', 'ما انت الا بشر مثلنا فات باية ان كنت من الصدقين'),
(3087, 26, 155, 'قَالَ هٰذِه۪ نَاقَةٌ لَهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَعْلُومٍۚ', 'Kale hazihi nakatun leha şirbun ve lekum şirbu yevmin ma\'lum.', '\"İşte bu dişi deve.[1] Su içme hakkı; belirli bir gün onun ve belirli bir gün sizindir.\" dedi.', 'قال هذه ناقة لها شرب ولكم شرب يوم معلوم'),
(3088, 26, 156, 'وَلَا تَمَسُّوهَا بِسُٓوءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظ۪يمٍ', 'Ve la temessuha bi suin fe ye\'huzekum azabu yevmin azim.', '\"Sakın ona bir kötülük dokundurmayın. Yoksa büyük günün azabı sizi yakalar.\"', 'ولا تمسوها بسو فياخذكم عذاب يوم عظيم'),
(3089, 26, 157, 'فَعَقَرُوهَا فَاَصْبَحُوا نَادِم۪ينَۙ', 'Fe akaruha fe asbahu nadimin.', 'Derken onu boğazladılar. Sonra da pişman oldular.', 'فعقروها فاصبحوا ندمين'),
(3090, 26, 158, 'فَاَخَذَهُمُ الْعَذَابُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'Fe ehazehumul azab, inne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Fakat azap onları yakaladı. Kuşkusuz bunda[1] bir ayet[2] vardır. Yine de insanların çoğu inanmadılar.', 'فاخذهم العذاب ان في ذلك لاية وما كان اكثرهم مومنين'),
(3091, 26, 159, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Rabbin,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3092, 26, 160, 'كَذَّبَتْ قَوْمُ لُوطٍۨ الْمُرْسَل۪ينَۚ', 'Kezzebet kavmu lutınil murselin.', 'Lut halkı gönderilmişleri[1] yalanladı.', 'كذبت قوم لوط المرسلين'),
(3093, 26, 161, 'اِذْ قَالَ لَهُمْ اَخُوهُمْ لُوطٌ اَلَا تَتَّقُونَۚ', 'İz kale lehum ehuhum lutun e la tettekun.', 'Kardeşleri Lut onlara: \"Takva sahibi olmayacak mısınız?\" demişti.', 'اذ قال لهم اخوهم لوط الا تتقون'),
(3094, 26, 162, 'اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'İnni lekum resulun emin.', '\"Sizin için güvenilir bir resulüm.\"', 'اني لكم رسول امين'),
(3095, 26, 163, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\" Allah için takva sahibi olun ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3096, 26, 164, 'وَمَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍۚ اِنْ اَجْرِيَ اِلَّا عَلٰى رَبِّ الْعَالَم۪ينَۜ', 'Ve ma es\'elukum aleyhi min ecr, in ecriye illa ala rabbil alemin.', '\"Buna karşılık sizden bir ücret istemiyorum. Benim ücretim yalnızca alemlerin Rabb\'ine aittir.\"', 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين'),
(3097, 26, 165, 'اَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَم۪ينَۙ', 'E te\'tunez zukrane minel alemin.', '\"İnsanlardan erkeklerle mi ilişkiye giriyorsunuz?\"', 'اتاتون الذكران من العلمين'),
(3098, 26, 166, 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُمْ مِنْ اَزْوَاجِكُمْۜ بَلْ اَنْتُمْ قَوْمٌ عَادُونَ', 'Ve tezerune ma halaka lekum rabbukum min ezvacikum, bel entum kavmun adun.', '\"Rabbinizin sizin için yarattığı eşlerinizi bırakıyorsunuz. Hayır! Siz azgın bir halksınız.\"', 'وتذرون ما خلق لكم ربكم من ازوجكم بل انتم قوم عادون'),
(3099, 26, 167, 'قَالُوا لَئِنْ لَمْ تَنْتَهِ۬ يَا لُوطُ لَتَكُونَنَّ مِنَ الْمُخْرَج۪ينَ', 'Kalu le in lem tentehi ya lutu le tekunenne minel muhracin.', '\"Ey Lut! Eğer kesin olarak vazgeçmezsen,  kesinlikle sürülenlerden[1] olacaksın.\" dediler.', 'قالوا لين لم تنته يلوط لتكونن من المخرجين'),
(3100, 26, 168, 'قَالَ اِنّ۪ي لِعَمَلِكُمْ مِنَ الْقَال۪ينَۜ', 'Kale inni li amelikum minel kalin.', 'Lut: \"Sizi yaptıklarınızdan dolayı kınıyorum.\" dedi.', 'قال اني لعملكم من القالين'),
(3101, 26, 169, 'رَبِّ نَجِّن۪ي وَاَهْل۪ي مِمَّا يَعْمَلُونَ', 'Rabbi neccini ve ehli mimma ya\'melun.', '\"Rabb\'im beni ve ehlimi[1] bunların yaptıklarından kurtar.\"', 'رب نجني واهلي مما يعملون'),
(3102, 26, 170, 'فَنَجَّيْنَاهُ وَاَهْلَـهُٓ  اَجْمَع۪ينَۙ', 'Fe necceynahu ve ehlehu ecmain.', 'Bunun üzerine onu ve ehlinin tamamını kurtardık.', 'فنجينه واهله اجمعين'),
(3103, 26, 171, 'اِلَّا عَجُوزاً فِي الْغَابِر۪ينَۚ', 'İlla acuzen fil gabirin.', 'Geride kalanlardan aciz[1] bir kadın hariç.', 'الا عجوزا في الغبرين'),
(3104, 26, 172, 'ثُمَّ دَمَّرْنَا الْاٰخَر۪ينَۚ', 'Summe demmernel aharin.', 'Sonra diğerlerini dumura[1] uğrattık.', 'ثم دمرنا الاخرين'),
(3105, 26, 173, 'وَاَمْطَرْنَا عَلَيْهِمْ مَطَراًۚ فَسَٓاءَ مَطَرُ الْمُنْذَر۪ينَ', 'Ve emtarna aleyhim matara, fe sae matarul munzerin.', 'Ve üzerlerine taştan[1] yağmur yağdırdık. Uyarılanların yağmuru ne kötüdür!', 'وامطرنا عليهم مطرا فسا مطر المنذرين'),
(3106, 26, 174, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Kuşkusuz bunda[1] bir ayet[2] vardır. Ama onların çoğu iman edenlerden olmadı.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(3107, 26, 175, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Senin Rabbin,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3108, 26, 176, 'كَذَّبَ اَصْحَابُ لْـَٔيْكَةِ الْمُرْسَل۪ينَۚ', 'Kezzebe ashabul eyketil murselin.', 'Eyke halkı gönderilmişleri[1] yalanladı.', 'كذب اصحب ليكة المرسلين'),
(3109, 26, 177, 'اِذْ قَالَ لَهُمْ شُعَيْبٌ اَلَا تَتَّقُونَۚ', 'İz kale lehum şuaybun e la tettekun.', 'Hani! Şuayb onlara: \"Takva sahibi olmayacak mısınız?\" demişti.', 'اذ قال لهم شعيب الا تتقون'),
(3110, 26, 178, 'اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'İnni lekum resulun emin.', '\"Sizin için güvenilir bir resulüm.\"', 'اني لكم رسول امين'),
(3111, 26, 179, 'فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِۚ', 'Fettekullahe ve etiun.', '\"Allah için takva sahibi olun ve bana itaat edin.\"', 'فاتقوا الله واطيعون'),
(3112, 26, 180, 'وَمَٓا اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍۚ اِنْ اَجْرِيَ اِلَّا عَلٰى رَبِّ الْعَالَم۪ينَۜ', 'Ve ma es\'elukum aleyhi min ecr, in ecriye illa ala rabbil alemin.', '\"Buna karşılık sizden bir ücret istemiyorum. Benim ücretim yalnızca alemlerin Rabb\'ine aittir.\"', 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين'),
(3113, 26, 181, 'اَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِر۪ينَۚ', 'Evful keyle ve la tekunu minel muhsirin.', '\"Ölçüde tam olun. Hak yiyenlerden olmayın.\"', 'اوفوا الكيل ولا تكونوا من المخسرين'),
(3114, 26, 182, 'وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَق۪يمِۚ', 'Vezinu bil kıstasil mustekim.', '\"Doğru terazi ile tartın.\"', 'وزنوا بالقسطاس المستقيم'),
(3115, 26, 183, 'وَلَا تَبْخَسُوا النَّاسَ اَشْيَٓاءَهُمْ وَلَا تَعْثَوْا فِي الْاَرْضِ مُفْسِد۪ينَۚ', 'Ve la tebhasun nase eşyaehum ve la ta\'sev fil ardı mufsidin.', '\"İnsanların mallarını değerinden düşürmeyin. Bozgunculuk yaparak yeryüzünde karışıklık çıkarmayın.\"', 'ولا تبخسوا الناس اشياهم ولا تعثوا في الارض مفسدين'),
(3116, 26, 184, 'وَاتَّقُوا الَّذ۪ي خَلَقَكُمْ وَالْجِبِلَّةَ الْاَوَّل۪ينَۜ', 'Vettekullezi halakakum vel cibilletel evvelin.', '\"Sizi ve sizden önceki nesilleri yaratana karşı takva sahibi olun.\"', 'واتقوا الذي خلقكم والجبلة الاولين'),
(3117, 26, 185, 'قَالُٓوا اِنَّـمَٓا اَنْتَ مِنَ الْمُسَحَّر۪ينَۙ', 'Kalu innema ente minel musahharin.', '\"Sen iyice büyülenmişlerdensin.\" dediler.', 'قالوا انما انت من المسحرين'),
(3118, 26, 186, 'وَمَٓا اَنْتَ اِلَّا بَشَرٌ مِثْلُنَا وَاِنْ نَظُنُّكَ لَمِنَ الْكَاذِب۪ينَۚ', 'Ve ma ente illa beşerun misluna ve in nazunnuke le minel kazibin.', '\"Sen de bizim gibi bir beşerden başka bir şey değilsin. Kesinlikle yalancı olduğunu düşünüyoruz.\"', 'وما انت الا بشر مثلنا وان نظنك لمن الكذبين'),
(3119, 26, 187, 'فَاَسْقِطْ عَلَيْنَا كِسَفاً مِنَ السَّمَٓاءِ اِنْ كُنْتَ مِنَ الصَّادِق۪ينَۜ', 'Fe eskıt aleyna kisefen mines semai in kunte mines sadıkin.', '\"Eğer doğru söylüyorsan,  haydi gökten üzerimize parçalar düşür.\"', 'فاسقط علينا كسفا من السما ان كنت من الصدقين'),
(3120, 26, 188, 'قَالَ رَبّ۪ٓي اَعْلَمُ بِمَا تَعْمَلُونَ', 'Kale rabbi a\'lemu bi ma ta\'melun.', 'Şuayb: \"Rabbim yaptıklarınızı daha iyi bilir.\"[1] dedi.', 'قال ربي اعلم بما تعملون'),
(3121, 26, 189, 'فَكَذَّبُوهُ فَاَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِۜ اِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Fe kezzebuhu fe ehazehum azabu yevmiz zulleh, innehu kane azabe yevmin azim.', 'Ne var ki onu yalanladılar. Bunun üzerine gölge gününün azabı onları yakaladı. Kuşkusuz o,  büyük günün azabıydı.', 'فكذبوه فاخذهم عذاب يوم الظلة انه كان عذاب يوم عظيم'),
(3122, 26, 190, 'اِنَّ ف۪ي ذٰلِكَ لَاٰيَةًۜ وَمَا كَانَ اَكْثَرُهُمْ مُؤْمِن۪ينَ', 'İnne fi zalike le ayeh, ve ma kane ekseruhum mu\'minin.', 'Kuşkusuz bunda[1] bir ayet[2] vardır. Ama onların çoğu iman edenlerden olmadı.', 'ان في ذلك لاية وما كان اكثرهم مومنين'),
(3123, 26, 191, 'وَاِنَّ رَبَّكَ لَهُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'Ve inne rabbeke le huvel azizur rahim.', 'Rabbin,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'وان ربك لهو العزيز الرحيم'),
(3124, 26, 192, 'وَاِنَّهُ لَتَنْز۪يلُ رَبِّ الْعَالَم۪ينَۜ', 'Ve innehu le tenzilu rabbil alemin.', 'O[1],  kesinlikle alemlerin Rabb\'inin indirmesidir.', 'وانه لتنزيل رب العلمين'),
(3125, 26, 193, 'نَزَلَ بِهِ الرُّوحُ الْاَم۪ينُۙ', 'Nezele bihir ruhul emin.', 'Onunla er-ruh\'ul emin[1] indi.', 'نزل به الروح الامين'),
(3126, 26, 194, 'عَلٰى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِر۪ينَۙ', 'Ala kalbike li tekune minel munzirin.', 'Senin kalbine. Uyarıcılardan olman için.', 'علي قلبك لتكون من المنذرين'),
(3127, 26, 195, 'بِلِسَانٍ عَرَبِيٍّ مُب۪ينٍۜ', 'Bi lisanin arabiyyin mubin.', 'Apaçık Arapça bir lisan ile.', 'بلسان عربي مبين'),
(3128, 26, 196, 'وَاِنَّهُ لَف۪ي زُبُرِ الْاَوَّل۪ينَ', 'Ve innehu lefi zuburil evvelin.', 'Kuşkusuz o kesinlikle öncekilerin Zebur\'larında[1] da vardır.', 'وانه لفي زبر الاولين'),
(3129, 26, 197, 'اَوَلَمْ يَكُنْ لَهُمْ اٰيَةً اَنْ يَعْلَمَهُ عُلَمٰٓؤُ۬ا بَن۪ٓي اِسْرَٓائ۪لَۜ', 'E ve lem yekun lehum ayeten en ya\'lemehu ulemau beni israil.', 'Ve İsrailoğulları bilginlerinin onu bilmesi[1],  onlar için bir ayet[2] değil mi?', 'اولم يكن لهم اية ان يعلمه علموا بني اسريل'),
(3130, 26, 198, 'وَلَوْ نَزَّلْنَاهُ عَلٰى بَعْضِ الْاَعْجَم۪ينَۙ', 'Ve lev nezzelnahu ala ba\'dıl a\'cemin.', 'Eğer onu yabancılardan[1] birisine indirseydik;', 'ولو نزلنه علي بعض الاعجمين'),
(3131, 26, 199, 'فَقَرَاَهُ عَلَيْهِمْ مَا كَانُوا بِه۪ مُؤْمِن۪ينَۜ', 'Fe karaehu aleyhim ma kanu bihi mu\'minin.', 'O da bunu onlara okusaydı,  onlar yine de inanmayacaklardı.', 'فقراه عليهم ما كانوا به مومنين'),
(3132, 26, 200, 'كَذٰلِكَ سَلَكْنَاهُ ف۪ي قُلُوبِ الْمُجْرِم۪ينَۜ', 'Kezalike seleknahu fi kulubil mucrimin.', 'Böylece onu[1] mücrimlerin[2] kalplerine soktuk.[3]', 'كذلك سلكنه في قلوب المجرمين'),
(3133, 26, 201, 'لَا يُؤْمِنُونَ بِه۪ حَتّٰى يَرَوُا الْعَذَابَ الْاَل۪يمَۙ', 'La yu\'minune bihi hatta yeravul azabel elim.', 'Acıklı azabı görmedikçe ona inanmazlar.', 'لا يومنون به حتي يروا العذاب الاليم'),
(3134, 26, 202, 'فَيَأْتِيَهُمْ بَغْتَةً وَهُمْ لَا يَشْعُرُونَۙ', 'Fe ye\'tiyehum bagteten ve hum la yeş\'urun.', 'İşte bu[1] onlara,  onlar farkında olmadan,  ansızın gelecektir.', 'فياتيهم بغتة وهم لا يشعرون'),
(3135, 26, 203, 'فَيَقُولُوا هَلْ نَحْنُ مُنْظَرُونَۜ', 'Fe yekulu hel nahnu munzarun.', 'O zaman; \"Bize birazcık olsun süre verilir mi acaba?\" diyecekler.', 'فيقولوا هل نحن منظرون'),
(3136, 26, 204, 'اَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'E fe bi azabina yesta\'cilun.', 'Yoksa azabımızı çabuklaştırmak mı istiyorlar?', 'افبعذابنا يستعجلون'),
(3137, 26, 205, 'اَفَرَاَيْتَ اِنْ مَتَّعْنَاهُمْ سِن۪ينَۙ', 'E fe raeyte in metta\'nahum sinin.', 'Gördün mü? Onlara yıllarca yararlanmalarına fırsat versek,', 'افريت ان متعنهم سنين'),
(3138, 26, 206, 'ثُمَّ جَٓاءَهُمْ مَا كَانُوا يُوعَدُونَۙ', 'Summe caehum ma kanu yuadun.', 'Sonra da onlara yapılan uyarı[1] gerçekleşse,', 'ثم جاهم ما كانوا يوعدون'),
(3139, 26, 207, 'مَٓا اَغْنٰى عَنْهُمْ مَا كَانُوا يُمَتَّعُونَۜ', 'Ma agna anhum ma kanu yumetteun.', 'Yararlandıkları şeyler onlara hiçbir yarar sağlamaz.', 'ما اغني عنهم ما كانوا يمتعون'),
(3140, 26, 208, 'وَمَٓا اَهْلَكْنَا مِنْ قَرْيَةٍ اِلَّا لَهَا مُنْذِرُونَۗۛ', 'Ve ma ehlekna min karyetin illa leha munzirun.', 'Uyarıcıları olmayan[1] hiçbir kenti yok etmedik.', 'وما اهلكنا من قرية الا لها منذرون'),
(3141, 26, 209, 'ذِكْرٰى۠ۛ وَمَا كُنَّا ظَالِم۪ينَ', 'Zikra, ve ma kunna zalimin.', 'Bu öğüttür[1]. Biz,  haksızlık yapanlardan olmadık.[2]', 'ذكري وما كنا ظلمين'),
(3142, 26, 210, 'وَمَا تَنَزَّلَتْ بِهِ الشَّيَاط۪ينُ', 'Ve ma tenezzelet bihiş şeyatin.', 'Onu,  şeytanlar[1] indirmedi.', 'وما تنزلت به الشيطين'),
(3143, 26, 211, 'وَمَا يَنْبَغ۪ي لَهُمْ وَمَا يَسْتَط۪يعُونَۜ', 'Ve ma yenbagi lehum ve ma yestetiun.', 'Bu onların harcı değil,  hem buna güçleri de yetmez.', 'وما ينبغي لهم وما يستطيعون'),
(3144, 26, 212, 'اِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَۜ', 'İnnehum anis sem\'i le ma\'zulun.', 'Çünkü onlar,  işitmekten[1] kesin olarak uzak tutulmuş olanlardır.', 'انهم عن السمع لمعزولون'),
(3145, 26, 213, 'فَلَا تَدْعُ مَعَ اللّٰهِ اِلٰهاً اٰخَرَ فَتَكُونَ مِنَ الْمُعَذَّب۪ينَۚ', 'Fe la ted\'u meallahi ilahen ahara fe tekune minel muazzebin.', 'O halde Allah ile beraber başka bir ilaha yönelme. Yoksa azap edilenlerden olursun.', 'فلا تدع مع الله الها اخر فتكون من المعذبين'),
(3146, 26, 214, 'وَاَنْذِرْ عَش۪يرَتَكَ الْاَقْرَب۪ينَۙ', 'Ve enzir aşiretekel akrebin.', 'Önce yakın akrabalarını uyar.', 'وانذر عشيرتك الاقربين'),
(3147, 26, 215, 'وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّـبَعَكَ مِنَ الْمُؤْمِن۪ينَۚ', 'Vahfıd cenahake li menittebeake minel mu\'minin.', 'Ve sana uyan inananlara sahip çık.', 'واخفض جناحك لمن اتبعك من المومنين'),
(3148, 26, 216, 'فَاِنْ عَصَوْكَ فَقُلْ اِنّ۪ي بَر۪ٓيءٌ مِمَّا تَعْمَلُونَۚ', 'Fe in asavke fe kul inni beriun mimma ta\'melun.', 'Eğer sana karşı çıkarlarsa,  \"Ben sizin yaptıklarınızdan uzağım.\" de.', 'فان عصوك فقل اني بري مما تعملون'),
(3149, 26, 217, 'وَتَوَكَّلْ عَلَى الْعَز۪يزِ الرَّح۪يمِۙ', 'Ve tevekkel alel azizir rahim.', 'Mutlak Üstün Olan\'a,  Rahmeti Kesintisiz Olan\'a tevekkül[1] et.', 'وتوكل علي العزيز الرحيم'),
(3150, 26, 218, 'اَلَّذ۪ي يَرٰيكَ ح۪ينَ تَقُومُۙ', 'Ellezi yerake hine tekum.', 'Kıyam[1] ettiğin zaman O seni görür.', 'الذي يريك حين تقوم'),
(3151, 26, 219, 'وَتَقَلُّبَكَ فِي السَّاجِد۪ينَ', 'Ve tekallubeke fis sacidin.', 'Secde[1] edenler içindeki hareketini de.', 'وتقلبك في السجدين'),
(3152, 26, 220, 'اِنَّهُ هُوَ السَّم۪يعُ الْعَل۪يمُ', 'İnnehu huves semiul alim.', 'O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'انه هو السميع العليم'),
(3153, 26, 221, 'هَلْ اُنَبِّئُكُمْ عَلٰى مَنْ تَنَزَّلُ الشَّيَاط۪ينُۜ', 'Hel unebbiukum ala men tenezzeluş şeyatin.', 'Şeytanların kimlere indiğini size haber vereyim mi?', 'هل انبيكم علي من تنزل الشيطين'),
(3154, 26, 222, 'تَنَزَّلُ عَلٰى كُلِّ اَفَّاكٍ اَث۪يمٍۙ', 'Tenezzelu ala kulli effakin esim.', 'Bütün iftiracı günahkarlara inerler.', 'تنزل علي كل افاك اثيم'),
(3155, 26, 223, 'يُلْقُونَ السَّمْعَ وَاَكْثَرُهُمْ كَاذِبُونَۜ', 'Yulkunes sem\'a ve ekseruhum kazibun.', 'Onlar,  kulak verirler[1] ve onların çoğu yalancıdırlar.', 'يلقون السمع واكثرهم كذبون'),
(3156, 26, 224, 'وَالشُّعَرَٓاءُ يَتَّبِعُهُمُ الْغَاوُ۫نَۜ', 'Veş şuarau yettebiuhumul gavun.', 'Ve o şairler; onlara azgınlar tabi olur.[1]', 'والشعرا يتبعهم الغاون'),
(3157, 26, 225, 'اَلَمْ تَرَ اَنَّهُمْ ف۪ي كُلِّ وَادٍ يَه۪يمُونَۙ', 'E lem tera ennehum fi kulli vadin yehimun.', 'Onların her vadide nasıl şaşkın şaşkın dolaştıklarını görmüyor musun?', 'الم تر انهم في كل واد يهيمون'),
(3158, 26, 226, 'وَاَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَۙ', 'Ve ennehum yekulune ma la yef\'alun.', 'Onlar yapmayacakları şeyleri söylerler.', 'وانهم يقولون ما لا يفعلون'),
(3159, 26, 227, 'اِلَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَذَكَرُوا اللّٰهَ كَث۪يراً وَانْتَصَرُوا مِنْ بَعْدِ مَا ظُلِمُواۜ وَسَيَعْلَمُ الَّذ۪ينَ ظَلَمُٓوا اَيَّ مُنْقَلَبٍ يَنْقَلِبُونَ', 'İllellezine amenu ve amilus salihati ve zekerullahe kesiran ventesaru min ba\'di ma zulimu, ve se ya\'lemullezine zalemu eyye munkalebin yenkalibun.', 'Ancak inananlar,  salihatı yapanlar,  her zaman Allah\'ın öğüdünü dinleyenler ve haksızlığa uğratıldıklarında kendilerini savunanlar hariç.[1] Zulmedenler,  nasıl bir alt üst oluşla,  alt üst[2] olacaklarını yakında bileceklerdir.', 'الا الذين امنوا وعملوا الصلحت وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا اي منقلب ينقلبون'),
(3160, 27, 1, 'طٰسٓ۠ تِلْكَ اٰيَاتُ الْقُرْاٰنِ وَكِتَابٍ مُب۪ينٍۙ', 'Ta sin, tilke ayatul kur\'ani ve kitabin mubin.', 'Ta,  Sin. İşte bunlar[1] Kur\'an\'ın,  gerçeği apaçık ortaya koyan Kitap\'ın ayetleridir.[2]', 'طس تلك ايت القران وكتب مبين'),
(3161, 27, 2, 'هُدًى وَبُشْرٰى لِلْمُؤْمِن۪ينَۙ', 'Huden ve buşra lil mu\'minin.', 'İnananlar için doğru yola iletici ve haber vericidir.', 'هدي وبشري للمومنين'),
(3162, 27, 3, 'اَلَّذ۪ينَ يُق۪يمُونَ الصَّلٰوةَ وَيُؤْتُونَ الزَّكٰوةَ وَهُمْ بِالْاٰخِرَةِ هُمْ يُوقِنُونَ', 'Ellezine yukimunes salate ve yu\'tunez zekate ve hum bil ahıreti hum yukınun.', 'Onlar,  salatı ikame ederler,  zekatı yaparlar.[1] Onlar,  ahirete kesin olarak inanırlar.', 'الذين يقيمون الصلوة ويوتون الزكوة وهم بالاخرة هم يوقنون'),
(3163, 27, 4, 'اِنَّ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ زَيَّنَّا لَهُمْ اَعْمَالَهُمْ فَهُمْ يَعْمَهُونَۜ', 'İnnellezine la yu\'minune bil ahireti zeyyenna lehum a\'malehum fe hum ya\'mehun.', 'Hesap Günü\'ne inanmayanlara,  yaptıklarını sevimli gösterdik. Bu yüzden şaşkınlık içinde bocalayıp dururlar.', 'ان الذين لا يومنون بالاخرة زينا لهم اعملهم فهم يعمهون'),
(3164, 27, 5, 'اُو۬لٰٓئِكَ الَّذ۪ينَ لَهُمْ سُٓوءُ الْعَذَابِ وَهُمْ فِي الْاٰخِرَةِ هُمُ الْاَخْسَرُونَ', 'Ulaikellezine lehum suul azabi ve hum fil ahıreti humul ahserun.', 'Onlar için azabın kötüsü vardır. Onlar,  Hesap Günü\'nde en çok ziyana uğrayacak kimselerdir.', 'اوليك الذين لهم سو العذاب وهم في الاخرة هم الاخسرون'),
(3165, 27, 6, 'وَاِنَّكَ لَتُلَقَّى الْقُرْاٰنَ مِنْ لَدُنْ حَك۪يمٍ عَل۪يمٍ', 'Ve inneke le tulekkal kur\'ane minledun hakimin alim.', 'Kuşkusuz Sen En İyi Hüküm Veren ve Her Şeyi Bilen tarafından Kur\'an verilensin[1].', 'وانك لتلقي القران من لدن حكيم عليم'),
(3166, 27, 7, 'اِذْ قَالَ مُوسٰى لِاَهْلِه۪ٓ اِنّ۪ٓي اٰنَسْتُ نَاراًۜ سَاٰت۪يكُمْ مِنْهَا بِخَبَرٍ اَوْ اٰت۪يكُمْ بِشِهَابٍ قَبَسٍ لَعَلَّكُمْ تَصْطَلُونَ', 'İz kale musa li ehlihi inni anestu nara, se atikum minha bi haberin ev atikum bi şihabin kabesin leallekum tastalun.', 'Hani Musa,  yakınlarına: \"Bir ateş fark ettim. Size ondan bir haber veya ısınmanız için kor halinde bir parça ateş getireceğim.\" demişti.', 'اذ قال موسي لاهله اني انست نارا ساتيكم منها بخبر او اتيكم بشهاب قبس لعلكم تصطلون'),
(3167, 27, 8, 'فَلَمَّا جَٓاءَهَا نُودِيَ اَنْ بُورِكَ مَنْ فِي النَّارِ وَمَنْ حَوْلَهَاۜ وَسُبْحَانَ اللّٰهِ رَبِّ الْعَالَم۪ينَ', 'Fe lemma caeha nudiye en burike men fin nari ve men havleha, ve subhanallahi rabbil alemin.', 'Oraya gittiği zaman ona seslenildi: \"Ateşin içinde ve etrafında olanlar kutlu kılındı. Ve Âlemlerin Rabbi olan Allah,  Subhan\'dır.[1]\"', 'فلما جاها نودي ان بورك من في النار ومن حولها وسبحن الله رب العلمين'),
(3168, 27, 9, 'يَا مُوسٰٓى اِنَّـهُٓ  اَنَا اللّٰهُ الْعَز۪يزُ الْحَك۪يمُۙ', 'Ya musa innehu enallahul azizul hakim.', '\"Ey Musa! Ben,  Mutlak Üstün Olan ve En İyi Hüküm Veren Allah\'ım!\"', 'يموسي انه انا الله العزيز الحكيم'),
(3169, 27, 10, 'وَاَلْقِ عَصَاكَۜ فَلَمَّا رَاٰهَا تَهْتَزُّ  كَاَنَّهَا جَٓانٌّ وَلّٰى مُدْبِراً وَلَمْ يُعَقِّبْۜ يَا مُوسٰى لَا تَخَفْ اِنّ۪ي لَا يَخَافُ لَدَيَّ الْمُرْسَلُونَۗ', 'Ve elkı asak, fe lemma reaha tehtezzu ke enneha cannun vella mudbiren ve lem yuakkıb, ya musa la tehaf inni la yehafu ledeyyel murselun.', '\"Asanı bırak!\" Musa,  asasını bırakmasıyla birlikte onun yılan gibi hareket ettiğini görünce,  geri dönüp arkasına bakmadan kaçtı. \"Ey Musa! Korkma,  gerçekten Benim. Benim huzurumda resuller korkmaz.\"', 'والق عصاك فلما راها تهتز كانها جان ولي مدبرا ولم يعقب يموسي لا تخف اني لا يخاف لدي المرسلون'),
(3170, 27, 11, 'اِلَّا مَنْ ظَلَمَ ثُمَّ بَدَّلَ حُسْناً بَعْدَ سُٓوءٍ فَاِنّ۪ي غَفُورٌ رَح۪يمٌ', 'İlla men zaleme summe beddele husnen ba\'de suin fe inni gafurun rahim.', '\"Kim haksızlık yapar,  sonra da yaptığı kötülüğü iyiliğe çevirirse,  bilsin ki Ben,  Çok Bağışlayıcı\'yım ve Rahmeti Kesintisiz Olan\'ım.\"', 'الا من ظلم ثم بدل حسنا بعد سو فاني غفور رحيم'),
(3171, 27, 12, 'وَاَدْخِلْ يَدَكَ ف۪ي جَيْبِكَ تَخْرُجْ بَيْضَٓاءَ مِنْ غَيْرِ سُٓوءٍ ف۪ي تِسْعِ اٰيَاتٍ اِلٰى فِرْعَوْنَ وَقَوْمِه۪ۜ اِنَّهُمْ كَانُوا قَوْماً فَاسِق۪ينَ', 'Ve edhıl yedeke fi ceybike tahruc beydae min gayri suin fi tis\'ı ayatin ila fir\'avne ve kavmih, innehum kanu kavmen fasikin.', '\"Ve elini koynuna sok. Kötülük[1] olmaksızın onu bembeyaz olarak çıkar. Firavun ve halkına dokuz ayet[2] ile git. Çünkü onlar fasık[3] bir halk oldular.\"', 'وادخل يدك في جيبك تخرج بيضا من غير سو في تسع ايت الي فرعون وقومه انهم كانوا قوما فسقين'),
(3172, 27, 13, 'فَلَمَّا جَٓاءَتْهُمْ اٰيَاتُنَا مُبْصِرَةً قَالُوا هٰذَا سِحْرٌ مُب۪ينٌۚ', 'Fe lemma caethum ayatuna mubsıraten kalu haza sihrun mubin.', 'Onlara,  gerçeği ortaya koyan ayetlerimiz[1] gelince,  \"Bu apaçık sihirdir.\" dediler.', 'فلما جاتهم ايتنا مبصرة قالوا هذا سحر مبين'),
(3173, 27, 14, 'وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَٓا اَنْفُسُهُمْ ظُلْماً وَعُلُواًّۜ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِد۪ينَ۟', 'Ve cehadu biha vesteykanetha enfusuhum zulmen ve uluvva, fenzur keyfe kane akıbetul mufsidin.', 'Doğruluğundan emin oldukları halde,  haksızca ve büyüklenerek mücadele ettiler. Ama bozguncuların sonlarının nasıl olduğuna bir bak!', 'وجحدوا بها واستيقنتها انفسهم ظلما وعلوا فانظر كيف كان عقبة المفسدين'),
(3174, 27, 15, 'وَلَقَدْ اٰتَيْنَا دَاوُ۫دَ وَسُلَيْمٰنَ عِلْماًۚ وَقَالَا الْحَمْدُ لِلّٰهِ الَّذ۪ي فَضَّلَنَا عَلٰى كَث۪يرٍ مِنْ عِبَادِهِ الْمُؤْمِن۪ينَ', 'Ve lekad ateyna davude ve suleymane ilma, ve kalal hamdu lillahillezi faddalena ala kesirin min ibadihil mu\'minin.', 'Ant olsun ki Davud\'a ve Süleyman\'a bir ilim[1] verdik. İkisi de: \"Tüm övgüler,  bizi,  inanan kullarının birçoğuna üstün kılan Allah\'adır.\" dediler.', 'ولقد اتينا داود وسليمن علما وقالا الحمد لله الذي فضلنا علي كثير من عباده المومنين'),
(3175, 27, 16, 'وَوَرِثَ سُلَيْمٰنُ دَاوُ۫دَ وَقَالَ يَٓا اَيُّهَا النَّاسُ عُلِّمْنَا مَنْطِقَ الطَّيْرِ وَاُو۫ت۪ينَا مِنْ كُلِّ شَيْءٍۜ اِنَّ هٰذَا لَهُوَ الْفَضْلُ الْمُب۪ينُ', 'Ve varise suleymanu davude ve kale ya eyyuhen nasu ullimna mentıkat tayrı, ve utina min kulli şey\', inne haza le huvel fadlul mubin.', 'Süleyman,  Davud\'a mirasçı oldu[1]. Süleyman: \"Ey insanlar! Bize kuşdili[2] öğretildi. Bize her şeyden verildi. Bu apaçık ilahi bir armağandır.\" dedi.', 'وورث سليمن داود وقال يايها الناس علمنا منطق الطير واوتينا من كل شي ان هذا لهو الفضل المبين'),
(3176, 27, 17, 'وَحُشِرَ لِسُلَيْمٰنَ جُنُودُهُ مِنَ الْجِنِّ وَالْاِنْسِ وَالطَّيْرِ فَهُمْ يُوزَعُونَ', 'Ve huşire li suleymane cunuduhu minel cinni vel insi vet tayrı fe hum yuzeun.', 'Süleyman için,  ins ve cinn[1] ve kuşlardan ordular toplandı. Sonra da sevk edildiler.', 'وحشر لسليمن جنوده من الجن والانس والطير فهم يوزعون'),
(3177, 27, 18, 'حَتّٰٓى اِذَٓا اَتَوْا عَلٰى وَادِ النَّمْلِۙ قَالَتْ نَمْلَةٌ يَٓا اَيُّهَا النَّمْلُ ادْخُلُوا مَسَاكِنَكُمْۚ لَا يَحْطِمَنَّكُمْ سُلَيْمٰنُ وَجُنُودُهُۙ وَهُمْ لَا يَشْعُرُونَ', 'Hatta iza etev ala vadin nemli kalet nemletun ya eyyuhen nemludhulu mesakinekum, la yahtımennekum suleymanu ve cunuduhu ve hum la yeş\'urun.', 'Nihayet Neml[1] Vadisi\'ne geldikleri zaman,  dişi bir neml: \"Ey nemller! Meskenlerinize[2] girin,  Süleyman ve orduları istemeyerek sizi kırıp geçirmesin.\" dedi.', 'حتي اذا اتوا علي واد النمل قالت نملة يايها النمل ادخلوا مسكنكم لا يحطمنكم سليمن وجنوده وهم لا يشعرون'),
(3178, 27, 19, 'فَتَبَسَّمَ ضَاحِكاً مِنْ قَوْلِهَا وَقَالَ رَبِّ اَوْزِعْن۪ٓي اَنْ اَشْكُرَ نِعْمَتَكَ الَّت۪ٓي اَنْعَمْتَ عَلَيَّ وَعَلٰى وَالِدَيَّ وَاَنْ اَعْمَلَ صَالِحاً تَرْضٰيهُ وَاَدْخِلْن۪ي بِرَحْمَتِكَ ف۪ي عِبَادِكَ الصَّالِح۪ينَ', 'Fe tebesseme dahıken min kavliha ve kale rabbi evzı\'ni en eşkure ni\'metekelleti en\'amte aleyye ve ala valideyye ve en a\'mele salihan terdahu ve edhılni bi rahmetike fi ibadikes salihin.', 'Bunun üzerine Süleyman onun sözüne gülümseyerek tebessüm etti. Ve \"Ey Rabb\'im! Bana,  anne ve babama bağışladığın nimetlerin karşılığında,  şükretmede ve hoşnut olacağın işler yapmada beni başarılı kıl. Ve rahmetinle beni salih[1] kullarının arasına kat.\" dedi.', 'فتبسم ضاحكا من قولها وقال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلي ولدي وان اعمل صلحا ترضيه وادخلني برحمتك في عبادك الصلحين'),
(3179, 27, 20, 'وَتَفَقَّدَ الطَّيْرَ فَقَالَ مَا لِيَ لَٓا اَرَى الْهُدْهُدَۘ اَمْ كَانَ مِنَ الْغَٓائِب۪ينَ', 'Ve tefekkadat tayra fe kale maliye la eral hudhude em kane minel gaibin.', 'Süleyman kuş topluluğunu yokladı. Sonra: \"Hudhud\'u niçin göremiyorum? Yoksa kayıplara mı karıştı?\" dedi.', 'وتفقد الطير فقال ما لي لا اري الهدهد ام كان من الغايبين'),
(3180, 27, 21, 'لَاُعَذِّبَنَّهُ عَذَاباً شَد۪يداً اَوْ لَا۬اَذْبَحَنَّهُٓ اَوْ لَيَأْتِيَنّ۪ي بِسُلْطَانٍ مُب۪ينٍ', 'Le uazzibennehu azaben şediden ev le ezbehannehu ev le ye\'tiyenni bi sultanin mubin.', '\"Kesinlikle ona şiddetli bir ceza vereceğim. Ya da onu boğazlayacağım. Ya da bana mazereti ile ilgili açık bir belge getirecek.\"', 'لاعذبنه عذابا شديدا او لااذبحنه او لياتيني بسلطن مبين'),
(3181, 27, 22, 'فَمَكَثَ غَيْرَ بَع۪يدٍ فَقَالَ اَحَطْتُ بِمَا لَمْ تُحِطْ بِه۪ وَجِئْتُكَ مِنْ سَبَأٍ بِنَبَأٍ يَق۪ينٍ', 'Fe mekese gayre baidin fe kale ehattu bi ma lem tuhıt bihi ve ci\'tuke min sebein bi nebein yakin.', 'Çok geçmeden geldi. Ve: \"Senin kuşatamadığın[1] bir şeyi kuşattım. Sana Sebe\'den kesin doğru olan bir haber getirdim.\" dedi.', 'فمكث غير بعيد فقال احطت بما لم تحط به وجيتك من سبا بنبا يقين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3182, 27, 23, 'اِنّ۪ي وَجَدْتُ امْرَاَةً تَمْلِكُهُمْ وَاُو۫تِيَتْ مِنْ كُلِّ شَيْءٍ وَلَهَا عَرْشٌ عَظ۪يمٌ', 'İnni vecedtumreeten temlikuhum ve utiyet min kulli şey\'in ve leha arşun azim.', '\"Onlara yöneticilik yapan bir kadın buldum. Ona her şeyden verilmiş. Çok görkemli bir tahtı var.\"', 'اني وجدت امراة تملكهم واوتيت من كل شي ولها عرش عظيم'),
(3183, 27, 24, 'وَجَدْتُهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِنْ دُونِ اللّٰهِ وَزَيَّنَ لَهُمُ الشَّيْطَانُ اَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّب۪يلِ فَهُمْ لَا يَهْتَدُونَۙ', 'Vecedtuha ve kavmeha yescudune liş şemsi min dunillahi ve zeyyene lehümuş şeytanu a\'malehum fe saddehum anis sebili fe hum la yehtedun.', '\"Kendisini de toplumunu da Allah\'ın yanı sıra Güneş\'e secde[1] ederken buldum. Şeytan onlara yaptıklarını güzel göstererek onları doğru yoldan alıkoymuş,  bundan dolayı da doğru yolu bulamıyorlar.\"', 'وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطن اعملهم فصدهم عن السبيل فهم لا يهتدون'),
(3184, 27, 25, 'اَلَّا يَسْجُدُوا لِلّٰهِ الَّذ۪ي يُخْرِجُ الْخَبْءَ فِي السَّمٰوَاتِ وَالْاَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'Ella yescudu lillahillezi yuhriculhab\'e fis semavati vel ardı ve ya\'lemu ma tuhfune ve ma tu\'linun.', '\"Göklerde ve yerde saklı olanı çıkaran,  sizin sakladığınızı da açıkladığınızı da bilen Allah\'a secde etmeleri gerekmez mi?\"', 'الا يسجدوا لله الذي يخرج الخب في السموت والارض ويعلم ما تخفون وما تعلنون'),
(3185, 27, 26, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَ رَبُّ الْعَرْشِ الْعَظ۪يمِ', 'Allahu la ilahe illa huve rabbul arşil azim.', '\"Allah ki,  büyük arşın[1] sahibidir. O\'ndan başka ilah yoktur.\"', 'الله لا اله الا هو رب العرش العظيم'),
(3186, 27, 27, 'قَالَ سَنَنْظُرُ اَصَدَقْتَ اَمْ كُنْتَ مِنَ الْكَاذِب۪ينَ', 'Kale se nenzuru e sadakte em kunte minel kazibin.', 'Süleyman,  Hudhud\'a: \"Bakacağız! Doğru mu söyledin yoksa yalan mı!\" dedi.', 'قال سننظر اصدقت ام كنت من الكذبين'),
(3187, 27, 28, 'اِذْهَبْ بِكِتَاب۪ي هٰذَا فَاَلْقِهْ اِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانْظُرْ مَاذَا يَرْجِعُونَ', 'İzheb bi kitabi haza fe elkıh ileyhim summe tevelle anhum fenzur maza yerciun.', '\"Bu mektubumu götür,  onlara ilet. Sonra bir kenara çekilip ne tepki vereceklerini gözle.\"', 'اذهب بكتبي هذا فالقه اليهم ثم تول عنهم فانظر ماذا يرجعون'),
(3188, 27, 29, 'قَالَتْ يَٓا اَيُّهَا الْمَلَؤُ۬ا اِنّ۪ٓي اُلْقِيَ اِلَيَّ كِتَابٌ كَر۪يمٌ', 'Kalet ya eyyuhel meleu inni ulkıye ileyye kitabun kerim.', 'Sebe melikesi: \"Ey meleler![1] Bana çok şerefli bir mektup bırakıldı.\" dedi.', 'قالت يايها الملوا اني القي الي كتب كريم'),
(3189, 27, 30, 'اِنَّهُ مِنْ سُلَيْمٰنَ وَاِنَّهُ بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّح۪يمِۙ', 'İnnehu min suleymane ve innehu bismillahir rahmanir rahim.', '\"O,  Süleyman\'ın mektubudur. Rahmeti Bol ve Kesintisiz olan Allah\'ın adıyla başlıyor.\"', 'انه من سليمن وانه بسم الله الرحمن الرحيم'),
(3190, 27, 31, 'اَلَّا تَعْلُوا عَلَيَّ وَأْتُون۪ي مُسْلِم۪ينَ۟', 'Ella ta\'lu aleyye ve\'tuni muslimin.', '\"Sakın bana karşı büyüklük taslamayın. Teslimiyet[1] içinde bana gelin!\" diyor.', 'الا تعلوا علي واتوني مسلمين'),
(3191, 27, 32, 'قَالَتْ يَٓا اَيُّهَا الْمَلَؤُ۬ا اَفْتُون۪ي ف۪ٓي اَمْر۪يۚ مَا كُنْتُ قَاطِعَةً اَمْراً حَتّٰى تَشْهَدُونِ', 'Kalet ya eyyuhel meleu eftuni fi emri, ma kuntu katıaten emren hatta teşhedun.', '\"Ey meleler! Bu istekle ilgili bana görüşlerinizi bildirin. Siz,  olmadan ben kesin bir karar verecek değilim.\" dedi.', 'قالت يايها الملوا افتوني في امري ما كنت قاطعة امرا حتي تشهدون'),
(3192, 27, 33, 'قَالُوا نَحْنُ اُو۬لُوا قُوَّةٍ وَاُو۬لُوا بَأْسٍ شَد۪يدٍ وَالْاَمْرُ اِلَيْكِ فَانْظُر۪ي مَاذَا تَأْمُر۪ينَ', 'Kalu nahnu ulu kuvvetin ve ulu be\'sin şedidin vel emru ileyki fenzuri maza te\'murin.', '\"Biz güçlüyüz ve çok büyük savaş gücüne sahibiz. Buyruk senindir. Nasıl istiyorsan öyle olsun.\" dediler.', 'قالوا نحن اولوا قوة واولوا باس شديد والامر اليك فانظري ماذا تامرين'),
(3193, 27, 34, 'قَالَتْ اِنَّ الْمُلُوكَ اِذَا دَخَلُوا قَرْيَةً اَفْسَدُوهَا وَجَعَلُٓوا اَعِزَّةَ اَهْلِهَٓا اَذِلَّةًۚ وَكَذٰلِكَ يَفْعَلُونَ', 'Kalet innel muluke iza dehalu karyeten efseduha ve cealu eizzete ehliha ezilleh, ve kezalike yef\'alun.', 'Sebe melikesi: \"Hükümdarlar bir ülkeye girdikleri zaman,  orayı bozguna uğratırlar. Oranın halkından izzet sahibi olanları zillete düşürürler. Onlar da böyle yapacaklar.\" dedi.', 'قالت ان الملوك اذا دخلوا قرية افسدوها وجعلوا اعزة اهلها اذلة وكذلك يفعلون'),
(3194, 27, 35, 'وَاِنّ۪ي مُرْسِلَةٌ اِلَيْهِمْ بِهَدِيَّةٍ فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ', 'Ve inni mursiletun ileyhim bi hediyyetin fe nazıratun bime yerciul murselun.', '\"Onlara hediyeler göndereyim. Bakalım elçiler nasıl bir cevapla dönecekler?\"', 'واني مرسلة اليهم بهدية فناظرة بم يرجع المرسلون'),
(3195, 27, 36, 'فَلَمَّا جَٓاءَ سُلَيْمٰنَ قَالَ اَتُمِدُّونَنِ بِمَالٍۘ فَمَٓا اٰتٰينِ‌يَ اللّٰهُ خَيْرٌ مِمَّٓا اٰتٰيكُمْۚ بَلْ اَنْتُمْ بِهَدِيَّتِكُمْ تَفْرَحُونَ', 'Fe lemma cae suleymane kale e tumidduneni bi malin fe ma ataniyallahu hayrun mimma atakum, bel entum bi hediyyetikum tefrahun.', 'Elçi Süleyman\'a geldiğinde,  Süleyman: \"Bana mal ile yardım etmek mi istiyorsunuz? Oysa Allah\'ın bana verdiği,  size verdiğinden daha hayırlıdır. Böyle hediyelere ancak sizin gibiler sevinir.\" dedi.', 'فلما جا سليمن قال اتمدونن بمال فما اتين الله خير مما اتيكم بل انتم بهديتكم تفرحون'),
(3196, 27, 37, 'اِرْجِعْ اِلَيْهِمْ فَلَنَأْتِيَنَّهُمْ بِجُنُودٍ لَا قِبَلَ لَهُمْ بِهَا وَلَنُخْرِجَنَّهُمْ مِنْهَٓا اَذِلَّةً وَهُمْ صَاغِرُونَ', 'İrcı\' ileyhim fe le ne\'tiyennehum bi cunudin la kıbele lehum biha ve le nuhricennehum minha ezilleten ve hum sagırun.', '\"Onlara geri dön. Karşı koyamayacakları bir ordu ile gelir,  onları yurtlarından hor ve aşağılanmış olarak çıkarırım.\"', 'ارجع اليهم فلناتينهم بجنود لا قبل لهم بها ولنخرجنهم منها اذلة وهم صغرون'),
(3197, 27, 38, 'قَالَ يَٓا اَيُّهَا الْمَلَؤُ۬ا اَيُّكُمْ يَأْت۪ين۪ي بِعَرْشِهَا قَبْلَ اَنْ يَأْتُون۪ي مُسْلِم۪ينَ', 'Kale ya eyyuhel meleu eyyekum ye\'tini bi arşiha kable en ye\'tuni muslimin.', 'Süleyman: \"Ey meleler![1] Onlar teslimiyet içinde bana gelmeden önce hanginiz onun tahtını bana getirebilir?\" dedi.', 'قال يايها الملوا ايكم ياتيني بعرشها قبل ان ياتوني مسلمين'),
(3198, 27, 39, 'قَالَ عِفْر۪يتٌ مِنَ الْجِنِّ اَنَا۬ اٰت۪يكَ بِه۪ قَبْلَ اَنْ تَقُومَ مِنْ مَقَامِكَۚ وَاِنّ۪ي عَلَيْهِ لَقَوِيٌّ اَم۪ينٌ', 'Kale ıfritun minel cinni ene atike bihi kable en tekume min makamik ve inni aleyhi le kaviyyun emin.', 'Cinlerden bir ifrit[1]: \"Sen makamından kalkmadan önce onu sana getiririm. Bunu gerçekleştirebileceğimden eminim.\" dedi.', 'قال عفريت من الجن انا اتيك به قبل ان تقوم من مقامك واني عليه لقوي امين'),
(3199, 27, 40, 'قَالَ الَّذ۪ي عِنْدَهُ عِلْمٌ مِنَ الْكِتَابِ اَنَا۬ اٰت۪يكَ بِه۪ قَبْلَ اَنْ يَرْتَدَّ اِلَيْكَ طَرْفُكَۜ فَلَمَّا رَاٰهُ مُسْتَقِراًّ عِنْدَهُ قَالَ هٰذَا مِنْ فَضْلِ رَبّ۪ي۠ لِيَبْلُوَن۪ٓي ءَاَشْكُرُ اَمْ اَكْفُرُۜ وَمَنْ شَكَرَ فَاِنَّمَا يَشْكُرُ لِنَفْسِه۪ۚ وَمَنْ كَفَرَ فَاِنَّ رَبّ۪ي غَنِيٌّ كَر۪يمٌ', 'Kalellezi indehu ilmun minel kitabi ene atike bihi kable en yertedde ileyke tarfuk, fe lemma reahu mustekırran indehu kale haza min fadlı rabbi, li yebluveni e eşkur em ekfur, ve men şekere fe innema yeşkuru li nefsih ve men kefere fe inne rabbi ganiyyun kerim.', 'Kitaptan[1] yanında bir bilgi bulunan kimse: \"Onu bakışın sana dönmeden[2] getiririm.\" dedi. Süleyman,  onun yanı başında durduğunu görünce: \"Bu Rabb\'imin lütfundandır; şükür mü edeceğim yoksa nankörlük mü edeceğim diye beni sınamak içindir.\" dedi. Ve kim şükrederse kendisi için şükretmiş olur,  kim de nankörlük ederse,  bilsin ki Rabb\'im Hiçbir Şeye Muhtaç Olmayan\'dır,  Cömert\'tir.', 'قال الذي عنده علم من الكتب انا اتيك به قبل ان يرتد اليك طرفك فلما راه مستقرا عنده قال هذا من فضل ربي ليبلوني اشكر ام اكفر ومن شكر فانما يشكر لنفسه ومن كفر فان ربي غني كريم'),
(3200, 27, 41, 'قَالَ نَكِّرُوا لَهَا عَرْشَهَا نَنْظُرْ اَتَهْتَد۪ٓي اَمْ تَكُونُ مِنَ الَّذ۪ينَ لَا يَهْتَدُونَ', 'Kale nekkiru leha arşeha nenzur e tehtedi em tekunu minellezine la yehtedun.', 'Süleyman: \"Onun tahtının şeklini değiştirin. Bakalım doğruyu bulacak mı yoksa doğruyu bulamayanlardan mı olacak?\" dedi.', 'قال نكروا لها عرشها ننظر اتهتدي ام تكون من الذين لا يهتدون'),
(3201, 27, 42, 'فَلَمَّا جَٓاءَتْ ق۪يلَ اَهٰكَذَا عَرْشُكِۜ قَالَتْ كَاَنَّهُ هُوَۚ وَاُو۫ت۪ينَا الْعِلْمَ مِنْ قَبْلِهَا وَكُنَّا مُسْلِم۪ينَ', 'Fe lemma caet kile e hakeza arşuk, kalet ke ennehu huve ve utinel ilme min kabliha ve kunna muslimin.', 'Melike geldiğinde ona: \"Senin tahtın böyle miydi?\" denildi. \"Sanki onun gibi.\" dedi. Ve \"Bize daha önce bilgi verildi ve biz teslimiyet gösterdik!\"', 'فلما جات قيل اهكذا عرشك قالت كانه هو واوتينا العلم من قبلها وكنا مسلمين'),
(3202, 27, 43, 'وَصَدَّهَا مَا كَانَتْ تَعْبُدُ مِنْ دُونِ اللّٰهِۜ اِنَّهَا كَانَتْ مِنْ قَوْمٍ كَافِر۪ينَ', 'Ve saddeha ma kanet ta\'budu min dunillah, inneha kanet min kavmin kafirin.', 'Allah\'ın yanı sıra kulluk[1] ettiği şeyler,  onu alıkoymuştu. Çünkü o Kafir[2] bir halktandı.', 'وصدها ما كانت تعبد من دون الله انها كانت من قوم كفرين'),
(3203, 27, 44, 'ق۪يلَ لَهَا ادْخُلِي الصَّرْحَۚ فَلَمَّا رَاَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَنْ سَاقَيْهَاۜ قَالَ اِنَّهُ صَرْحٌ مُمَرَّدٌ مِنْ قَوَار۪يرَۜ قَالَتْ رَبِّ اِنّ۪ي ظَلَمْتُ نَفْس۪ي وَاَسْلَمْتُ مَعَ سُلَيْمٰنَ لِلّٰهِ رَبِّ الْعَالَم۪ينَ۟', 'Kile lehadhulis sarh, fe lemma raethu hasibethu lucceten ve keşefet an sakayha, kale innehu sarhun mumerradun min kavarir, kalet rabbi inni zalemtu nefsi ve eslemtu mea suleymane lillahi rabbil alemin.', 'Ona,  \"Köşke gir!\" denildi. Köşkü görünce,  onu[1] derin su sanarak bacaklarını sıvadı. Süleyman,  \"Bu billurdan döşenmiş şeffaf bir zemindir.\" dedi. Melike,  \"Rabb\'im,  ben kendime haksızlık ettim. Süleyman ile birlikte alemlerin Rabbi olan Allah\'a teslim oldum.\" dedi.', 'قيل لها ادخلي الصرح فلما راته حسبته لجة وكشفت عن ساقيها قال انه صرح ممرد من قوارير قالت رب اني ظلمت نفسي واسلمت مع سليمن لله رب العلمين'),
(3204, 27, 45, 'وَلَقَدْ اَرْسَلْـنَٓا اِلٰى ثَمُودَ اَخَـاهُمْ صَـالِحاً اَنِ اعْبُـدُوا اللّٰهَ فَاِذَا هُمْ فَر۪يقَانِ يَخْتَصِمُونَ', 'Ve lekad erselna ila semude ehahum salihan eni\'budullahe fe izahum ferikani yahtesımun.', 'Ant olsun ki Semud halkına da,  \"Allah\'a kulluk edin.\" diye kardeşleri Salih\'i gönderdik. Ne var ki birbirleri ile çekişen iki grup oldular.', 'ولقد ارسلنا الي ثمود اخاهم صلحا ان اعبدوا الله فاذا هم فريقان يختصمون'),
(3205, 27, 46, 'قَالَ يَا قَوْمِ لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِۚ لَوْلَا تَسْتَغْفِرُونَ اللّٰهَ لَعَلَّكُمْ تُرْحَمُونَ', 'Kale ya kavmi lime testa\'cilune bis seyyieti kablel haseneh, lev la testagfirunallahe leallekum turhamun.', 'Salih: \"Ey halkım! Neden iyilik dururken,  kötülüğün bir an önce olmasını istiyorsunuz? Allah\'tan bağışlanma dileseniz olmaz mı? Belki bağışlanırsınız!\" dedi.', 'قال يقوم لم تستعجلون بالسيية قبل الحسنة لولا تستغفرون الله لعلكم ترحمون'),
(3206, 27, 47, 'قَالُوا اطَّيَّرْنَا بِكَ وَبِمَنْ مَعَكَۜ قَالَ طَٓائِرُكُمْ عِنْدَ اللّٰهِ بَلْ اَنْتُمْ قَوْمٌ تُفْتَنُونَ', 'Kalut tayyerna bike ve bi men meak, kale tairukum indallahi bel entum kavmun tuftenun.', '\"Sen ve seninle beraber olanlar bize uğursuzluk getirdiniz.\" dediler. Salih: \"Sizin uğursuzluğunuz Allah\'ın takdirindedir. Belki sınav olunmakta olan bir toplumsunuz!\" dedi.', 'قالوا اطيرنا بك وبمن معك قال طيركم عند الله بل انتم قوم تفتنون'),
(3207, 27, 48, 'وَكَانَ فِي الْمَد۪ينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِي الْاَرْضِ وَلَا يُصْلِحُونَ', 'Ve kane fil medineti tis\'atu rahtın yufsidune fil ardı ve la yuslihun.', 'Kentte bozguncu olan,  bozgunculuk yapan dokuz kabile vardı. Yeryüzünde bozgunculuk yapardı. Düzeltmeye yanaşmazlardı.', 'وكان في المدينة تسعة رهط يفسدون في الارض ولا يصلحون'),
(3208, 27, 49, 'قَالُوا تَقَاسَمُوا بِاللّٰهِ لَنُبَيِّتَنَّهُ وَاَهْلَهُ ثُمَّ لَنَقُولَنَّ لِوَلِيِّه۪ مَا شَهِدْنَا مَهْلِكَ اَهْلِه۪ وَاِنَّا لَصَادِقُونَ', 'Kalu tekasemu billahi le nubeyyitennehu ve ehlehu summe le nekulenne li veliyyihi ma şehidna mehlike ehlihi ve inna le sadikun.', 'Allah\'a yemin ederek dediler ki: \"Gece ona ve ailesine baskın yapalım. Sonra da onun velisine[1] ailesinin yok edilmesiyle bir ilgimiz yok,  biz kesinlikle doğru söyleyenleriz diyelim.\"', 'قالوا تقاسموا بالله لنبيتنه واهله ثم لنقولن لوليه ما شهدنا مهلك اهله وانا لصدقون'),
(3209, 27, 50, 'وَمَكَرُوا مَكْراً وَمَكَرْنَا مَكْراً وَهُمْ لَا يَشْعُرُونَ', 'Ve mekeru mekran ve mekerna mekran ve hum la yeş\'urun.', 'Plan yaptılar. Biz de planlarını boşa çıkardık. Fakat farkına varamadılar.', 'ومكروا مكرا ومكرنا مكرا وهم لا يشعرون'),
(3210, 27, 51, 'فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْۙ اَنَّا دَمَّرْنَاهُمْ وَقَوْمَهُمْ اَجْمَع۪ينَ', 'Fenzur keyfe kane akıbetu mekrihim enna demmernahum ve kavmehum ecmein.', 'Onların planlarının sonucunun nasıl olduğuna bak; onları ve halklarını yerle bir ettik.', 'فانظر كيف كان عقبة مكرهم انا دمرنهم وقومهم اجمعين'),
(3211, 27, 52, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُواۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِقَوْمٍ يَعْلَمُونَ', 'Fe tilke buyutuhum haviyeten bima zalemu, inne fi zalike le ayeten li kavmin ya\'lemun.', 'İşte,  haksızlıkları nedeniyle harabe olan evleri! Bilen bir toplum için bunda kesinlikle bir ayet[1] vardır.', 'فتلك بيوتهم خاوية بما ظلموا ان في ذلك لاية لقوم يعلمون'),
(3212, 27, 53, 'وَاَنْجَيْنَا الَّذ۪ينَ اٰمَنُوا وَكَانُوا يَتَّقُونَ', 'Ve enceynellezine amenu ve kanu yettekun.', 'İman edip takva sahibi olanları ise kurtardık.', 'وانجينا الذين امنوا وكانوا يتقون'),
(3213, 27, 54, 'وَلُوطاً اِذْ قَالَ لِقَوْمِه۪ٓ اَتَأْتُونَ الْفَاحِشَةَ وَاَنْتُمْ تُبْصِرُونَ', 'Ve lutan iz kale li kavmihi ete\'tunel fahışete ve entum tubsırun.', 'Lut,  halkına şöyle demişti: \"Göz göre göre fahişelik[1] mi yapıyorsunuz?\"', 'ولوطا اذ قال لقومه اتاتون الفحشة وانتم تبصرون'),
(3214, 27, 55, 'اَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِنْ دُونِ النِّسَٓاءِۜ بَلْ اَنْتُمْ قَوْمٌ تَجْهَلُونَ', 'E innekum le te\'tuner ricale şehveten min dunin nisai, bel entum kavmun techelun.', '\"Kadınları bırakıp şehvetle erkeklere mi yanaşıyorsunuz? Hayır! Siz gerçekten cahil[1] bir toplumsunuz.\"', 'اينكم لتاتون الرجال شهوة من دون النسا بل انتم قوم تجهلون'),
(3215, 27, 56, 'فَمَا كَانَ جَوَابَ قَوْمِه۪ٓ اِلَّٓا اَنْ قَالُٓوا اَخْرِجُٓوا اٰلَ لُوطٍ مِنْ قَرْيَتِكُمْۚ اِنَّهُمْ اُنَاسٌ يَتَطَهَّرُونَ', 'Fe ma kane cevabe kavmihi illa en kalu ahricu ale lutın min karyetikum innehum unasun yetetahherun.', 'Fakat halkının cevabı: \"Lut ailesini kasabamızdan çıkarın; çünkü onlar temiz kalmak isteyen kimselermiş!\" olmaktan başka bir şey olmadı.', 'فما كان جواب قومه الا ان قالوا اخرجوا ال لوط من قريتكم انهم اناس يتطهرون'),
(3216, 27, 57, 'فَاَنْجَيْنَاهُ وَاَهْلَـهُٓ اِلَّا امْرَاَتَهُۘ قَدَّرْنَاهَا مِنَ الْغَابِر۪ينَ', 'Fe enceynahu ve ehlehu illemreetehu kaddernaha minel gabirin.', 'Bunun üzerine onu ve taraftarlarını kurtardık; karısı hariç. Onun geride kalanlardan olmasını uygun gördük.', 'فانجينه واهله الا امراته قدرنها من الغبرين'),
(3217, 27, 58, 'وَاَمْطَرْنَا عَلَيْهِمْ مَطَراًۚ فَسَٓاءَ مَطَرُ الْمُنْذَر۪ينَ۟', 'Ve emtarna aleyhim matara, fe sae matarul munzerin.', 'Ve onların üzerlerine taştan[1] yağmur yağdırdık. Uyarılanların yağmuru; çok kötü oldu.', 'وامطرنا عليهم مطرا فسا مطر المنذرين'),
(3218, 27, 59, 'قُلِ الْحَمْدُ لِلّٰهِ وَسَلَامٌ عَلٰى عِبَادِهِ الَّذ۪ينَ اصْطَفٰىۜ آٰللّٰهُ خَيْرٌ اَمَّا يُشْرِكُونَۜ', 'Kulil hamdu lillahi ve selamun ala ibadihillezinastafa, allahu hayrun emma yuşrikun.', 'De ki: \"Allah\'a hamd olsun.\" Selam onun seçtiği kullarının üzerinedir. Allah mı daha hayırlıdır yoksa ona şirk koştukları mı?', 'قل الحمد لله وسلم علي عباده الذين اصطفي الله خير اما يشركون'),
(3219, 27, 60, 'اَمَّنْ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَاَنْزَلَ لَكُمْ مِنَ السَّمَٓاءِ مَٓاءًۚ فَاَنْبَتْنَا بِه۪ حَدَٓائِقَ ذَاتَ بَهْجَةٍۚ مَا كَانَ لَكُمْ اَنْ تُنْبِتُوا شَجَرَهَاۜ ءَاِلٰهٌ مَعَ اللّٰهِۜ بَلْ هُمْ قَوْمٌ يَعْدِلُونَۜ', 'Emmen halakas semavati vel arda ve enzele lekum mines semai ma\', fe enbetna bihi hadaika zate behceh, ma kane lekum en tunbitu şecereha, e ilahun meallah, bel hum kavmun ya\'dilun.', 'Veya gökleri ve yeri yaratan ve sizin için gökten su indiren mi? Biz onunla,  bir ağacını dahi yetiştiremeyeceğiniz güzel bahçeler yetiştirdik. Allah ile birlikte başka bir ilah mı var? Hayır,  onlar sapkınlık ediyorlar.', 'امن خلق السموت والارض وانزل لكم من السما ما فانبتنا به حدايق ذات بهجة ما كان لكم ان تنبتوا شجرها اله مع الله بل هم قوم يعدلون'),
(3220, 27, 61, 'اَمَّنْ جَعَلَ الْاَرْضَ قَرَاراً وَجَعَلَ خِلَالَـهَٓا اَنْهَاراً وَجَعَلَ لَهَا رَوَاسِيَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزاًۜ ءَاِلٰهٌ مَعَ اللّٰهِۜ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَۜ', 'Emmen cealel arda kararen ve ceale hılaleha enharen ve ceale leha revasiye ve ceale beynel bahreyni haciza, e ilahun meallah, bel ekseruhum la ya\'lemun.', 'Yoksa yeryüzünü yerleşme yeri yapan ve orda nehirler akıtan,  orada ağır baskılar koyan ve iki deniz arasına engel koyan mı? Allah ile beraber bir ilah mı? Hayır,  onların çoğu bilmiyorlar.', 'امن جعل الارض قرارا وجعل خللها انهرا وجعل لها روسي وجعل بين البحرين حاجزا اله مع الله بل اكثرهم لا يعلمون'),
(3221, 27, 62, 'اَمَّنْ يُج۪يبُ الْمُضْطَرَّ اِذَا دَعَاهُ وَيَكْشِفُ السُّٓوءَ وَيَجْعَلُكُمْ خُلَـفَٓاءَ الْاَرْضِۜ ءَاِلٰهٌ مَعَ اللّٰهِۜ قَل۪يلاً مَا تَذَكَّرُونَۜ', 'Emmen yucibul mudtarra iza deahu ve yekşifus sue ve yec\'alukum hulefael ard, e ilahun meallah, kalilen ma tezekkerun.', 'Yoksa darda kalanın çağrısına karşılık veren,  kötülüğü gideren ve sizi yeryüzünün halifeleri[1] yapan mı? Allah ile birlikte başka bir ilah mı? Ne kadar az öğüt alıyorsunuz?', 'امن يجيب المضطر اذا دعاه ويكشف السو ويجعلكم خلفا الارض اله مع الله قليلا ما تذكرون'),
(3222, 27, 63, 'اَمَّنْ يَهْد۪يكُمْ ف۪ي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ وَمَنْ يُرْسِلُ الرِّيَاحَ بُشْراً بَيْنَ يَدَيْ رَحْمَتِه۪ۜ ءَاِلٰهٌ مَعَ اللّٰهِۜ تَعَالَى اللّٰهُ عَمَّا يُشْرِكُونَۜ', 'Emmen yehdikum fi zulumatil berri vel bahri ve men yursilur riyaha buşren beyne yedey rahmetih, e ilahun meallah, tealallahu amma yuşrikun.', 'Yoksa karanın ve denizin karanlıklarında size yol gösteren mi? Rahmetinin önünde müjdeci olarak rüzgarları gönderen mi? Allah ile birlikte bir ilah mı? Allah,  onların şirk koştuklarından çok yücedir.', 'امن يهديكم في ظلمت البر والبحر ومن يرسل الريح بشرا بين يدي رحمته اله مع الله تعلي الله عما يشركون'),
(3223, 27, 64, 'اَمَّنْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُ وَمَنْ يَرْزُقُكُمْ مِنَ السَّمَٓاءِ وَالْاَرْضِۜ ءَاِلٰهٌ مَعَ اللّٰهِۜ قُلْ هَاتُوا بُرْهَانَكُمْ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Emmen yebdeul halka summe yuiduhu ve men yerzukukum mines semai vel ard, e ilahun meallah, kul hatu burhanekum in kuntum sadikin.', 'Yoksa ilk kez yaratan,  sonra da yaratmayı tekrarlayacak olan,  sizi gökten ve yerden rızıklandıran mı? Allah ile birlikte başka bir ilah mı? De ki: \"Eğer doğru söyleyenlerdenseniz burhanınızı[1] getirin.\"', 'امن يبدوا الخلق ثم يعيده ومن يرزقكم من السما والارض اله مع الله قل هاتوا برهنكم ان كنتم صدقين'),
(3224, 27, 65, 'قُلْ لَا يَعْلَمُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِ الْغَيْبَ اِلَّا اللّٰهُۜ وَمَا يَشْعُرُونَ اَيَّانَ يُبْعَثُونَ', 'Kul la ya\'lemu men fis semavati vel ardıl gaybe illallah ve ma yeş\'urune eyyane yub\'asun.', 'De ki: \"Göklerde ve yerde gaybı Allah\'tan başka kimse bilemez. Onlar ne zaman diriltileceklerinin bilincinde olamazlar.\"', 'قل لا يعلم من في السموت والارض الغيب الا الله وما يشعرون ايان يبعثون'),
(3225, 27, 66, 'بَلِ ادَّارَكَ عِلْمُهُمْ فِي الْاٰخِرَةِ۠ بَلْ هُمْ ف۪ي شَكٍّ مِنْهَا۠ بَلْ هُمْ مِنْهَا عَمُونَ۟', 'Beliddareke ilmuhum fil ahıreh, bel hum fi şekkin minha, bel hum minha amun.', 'Aslında onlar ahiret hakkında yeterince bilgilendirildiler. Fakat hala şüphe içindeler. Doğrusu bundan yana kördürler.', 'بل ادرك علمهم في الاخرة بل هم في شك منها بل هم منها عمون'),
(3226, 27, 67, 'وَقَالَ الَّذ۪ينَ كَفَرُٓوا ءَاِذَا كُنَّا تُرَاباً وَاٰبَٓاؤُ۬نَٓا اَئِنَّا لَمُخْرَجُونَ', 'Ve kalellezine keferu e iza kunna turaben ve abauna e inna le muhracun.', 'Kafirler: \"Biz ve atalarımız toprak olduktan sonra,  gerçekten de diriltilip çıkartılacak mıyız?\" dediler.', 'وقال الذين كفروا اذا كنا ترابا واباونا اينا لمخرجون'),
(3227, 27, 68, 'لَقَدْ وُعِدْنَا هٰذَا نَحْنُ وَاٰبَٓاؤُ۬نَا مِنْ قَبْلُۙ اِنْ هٰذَٓا اِلَّٓا اَسَاط۪يرُ الْاَوَّل۪ينَ', 'Lekad vuıdna haza nahnu ve abauna min kablu in haza illa esatirul evvelin.', '\"Ant olsun,  bu bize söylenen daha önce atalarımıza da söylenmişti. Ancak bunlar evvelkilerin masallarından başka bir şey değildir.\" dediler.', 'لقد وعدنا هذا نحن واباونا من قبل ان هذا الا اسطير الاولين'),
(3228, 27, 69, 'قُلْ س۪يرُوا فِي الْاَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِم۪ينَ', 'Kul siru fil ardı fenzuru keyfe kane akibetul mucrimin.', 'De ki: \"Yeryüzünde gezip dolaşın,  mücrimlerin[1] sonları nasıl olmuş bir görün?\"', 'قل سيروا في الارض فانظروا كيف كان عقبة المجرمين'),
(3229, 27, 70, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُنْ ف۪ي ضَيْقٍ مِمَّا يَمْكُرُونَ', 'Ve la tahzen aleyhim ve la tekun fi daykın mimma yemkurun.', 'Onlar için üzülme! Yaptıkları planlardan dolayı canını sıkma.', 'ولا تحزن عليهم ولا تكن في ضيق مما يمكرون'),
(3230, 27, 71, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadıkin.', '\"Eğer doğru söyleyenlerdenseniz,  bu uyarı ne zaman gerçekleşecek?\" diyorlar.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(3231, 27, 72, 'قُلْ عَسٰٓى اَنْ يَكُونَ رَدِفَ لَكُمْ بَعْضُ الَّذ۪ي تَسْتَعْجِلُونَ', 'Kul asa en yekune radife lekum ba\'dullezi testa\'cilun.', 'De ki: \"Çarçabuk istediğiniz azabın bir kısmı belki de size yaklaşmıştır.\"', 'قل عسي ان يكون ردف لكم بعض الذي تستعجلون'),
(3232, 27, 73, 'وَاِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَشْكُرُونَ', 'Ve inne rabbeke le zu fadlın alen nasi ve lakinne ekserehum la yeşkurun.', 'Senin Rabb\'in insanlara karşı lütuf[1] sahibidir. Ne var ki onların çoğu şükretmiyorlar.[2]', 'وان ربك لذو فضل علي الناس ولكن اكثرهم لا يشكرون'),
(3233, 27, 74, 'وَاِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'Ve inne rabbeke le ya\'lemu ma tukinnu suduruhum ve ma yu\'linun.', 'Rabb\'in,  onların kalplerinde[1] gizlediklerini de açıkladıklarını da kesin olarak bilmektedir.', 'وان ربك ليعلم ما تكن صدورهم وما يعلنون'),
(3234, 27, 75, 'وَمَا مِنْ غَٓائِبَةٍ فِي السَّمَٓاءِ وَالْاَرْضِ اِلَّا ف۪ي كِتَابٍ مُب۪ينٍ', 'Ve ma min gaibetin fis semai vel ardı illa fi kitabin mubin.', 'Gökte ve yerde gayb[1] olan hiçbir şey yoktur ki apaçık bir kitapta[2] olmasın.', 'وما من غايبة في السما والارض الا في كتب مبين'),
(3235, 27, 76, 'اِنَّ هٰذَا الْقُرْاٰنَ يَقُصُّ عَلٰى بَن۪ٓي اِسْرَٓائ۪لَ اَكْثَرَ الَّذ۪ي هُمْ ف۪يهِ يَخْتَلِفُونَ', 'İnne hazel kur\'ane yakussu ala beni israile ekserellezi hum fihi yahtelifun.', 'Bu Kur\'an; İsrailoğulları\'na,  hakkında ayrılığa düştükleri pek çok şeyi açıklıyor.', 'ان هذا القران يقص علي بني اسريل اكثر الذي هم فيه يختلفون'),
(3236, 27, 77, 'وَاِنَّهُ لَهُدًى وَرَحْمَةٌ لِلْمُؤْمِن۪ينَ', 'Ve innehu le huden ve rahmetun lil mu\'minin.', 'O,  Mü\'minler için yol gösterici ve rahmettir.', 'وانه لهدي ورحمة للمومنين'),
(3237, 27, 78, 'اِنَّ رَبَّكَ يَقْض۪ي بَيْنَهُمْ بِحُكْمِه۪ۚ وَهُوَ الْعَز۪يزُ الْعَل۪يمُۚ', 'İnne rabbeke yakdi beynehum bi hukmihi, ve huvel azizul alim.', 'Rabb\'in,  onların arasında hükmünü verecek. O,  Mutlak Üstün Olan\'dır,  Her Şeyi Bilen\'dir.', 'ان ربك يقضي بينهم بحكمه وهو العزيز العليم'),
(3238, 27, 79, 'فَتَوَكَّلْ عَلَى اللّٰهِۜ اِنَّكَ عَلَى الْحَقِّ الْمُب۪ينِ', 'Fe tevekkel alallah, inneke alel hakkıl mubin.', 'Öyleyse Allah\'a tevekkül[1] et. Kuşkusuz sen,  apaçık gerçek üzerindesin.', 'فتوكل علي الله انك علي الحق المبين'),
(3239, 27, 80, 'اِنَّكَ لَا تُسْمِــعُ الْمَوْتٰى وَلَا تُسْمِــعُ الصُّمَّ الدُّعَٓاءَ اِذَا وَلَّوْا مُدْبِر۪ينَ', 'İnneke la tusmiul mevta ve la tusmius summed duae iza vellev mudbirin.', 'Sen,  ölülere duyuramazsın. Mesajı aldırmayan sağırlara da duyuramazsın.', 'انك لا تسمع الموتي ولا تسمع الصم الدعا اذا ولوا مدبرين'),
(3240, 27, 81, 'وَمَٓا اَنْتَ بِهَادِي الْعُمْيِ عَنْ ضَلَالَتِهِمْۜ اِنْ تُسْمِــعُ اِلَّا مَنْ يُؤْمِنُ بِاٰيَاتِنَا فَهُمْ مُسْلِمُونَ', 'Ve ma ente bi hadil umyi an dalaletihim, in tusmiu illa men yu\'minu bi ayatina fe hum muslimun.', 'Sen körleri,  sapkınlıktan çevirip doğru yola iletemezsin; sen ancak ayetlerimize iman edip teslim olanlara gerçeği duyurabilirsin.', 'وما انت بهادي العمي عن ضللتهم ان تسمع الا من يومن بايتنا فهم مسلمون'),
(3241, 27, 82, 'وَاِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ اَخْرَجْنَا لَهُمْ دَٓابَّةً مِنَ الْاَرْضِ تُكَلِّمُهُمْۙ اَنَّ النَّاسَ كَانُوا بِاٰيَاتِنَا لَا يُوقِنُونَ۟', 'Ve iza vakaal kavlu aleyhim ahracna lehum dabbeten minel ardı tukellimuhum ennen nase kanu bi ayatina la yukınun.', 'Üzerlerine söz[1] gerçekleştiği zaman,  onlara yerden bir dabbe[2] çıkarırız. Kuşkusuz o,  onlara,  insanların[3] ayetlerimize inanmadıklarını söyler.[4]', 'واذا وقع القول عليهم اخرجنا لهم دابة من الارض تكلمهم ان الناس كانوا بايتنا لا يوقنون'),
(3242, 27, 83, 'وَيَوْمَ نَحْشُرُ مِنْ كُلِّ اُمَّةٍ فَوْجاً مِمَّنْ يُكَذِّبُ بِاٰيَاتِنَا فَهُمْ يُوزَعُونَ', 'Ve yevme nahşuru min kulli ummetin fevcen mimmen yukezzibu bi ayatina fe hum yuzeun.', 'O gün bütün toplumlardan,  ayetlerimizi yalanlayanları gruplar halinde toplayacağız. Artık onlar sımsıkı tutuklanıp sevk edilirler.', 'ويوم نحشر من كل امة فوجا ممن يكذب بايتنا فهم يوزعون'),
(3243, 27, 84, 'حَتّٰٓى اِذَا جَٓاؤُ۫ قَالَ اَكَذَّبْتُمْ بِاٰيَات۪ي وَلَمْ تُح۪يطُوا بِهَا عِلْماً اَمَّاذَا كُنْتُمْ تَعْمَلُونَ', 'Hatta iza cau kale e kezzebtum bi ayati ve lem tuhitu biha ılmen em maza kuntum ta\'melun.', 'Ve geldikleri zaman: \"Onu bilgi ile kavramadınız[1] da mı ayetlerimi yalanladınız? Yoksa başka bir neden mi var?\" dedi.', 'حتي اذا جاو قال اكذبتم بايتي ولم تحيطوا بها علما اماذا كنتم تعملون'),
(3244, 27, 85, 'وَوَقَعَ الْقَوْلُ عَلَيْهِمْ بِمَا ظَلَمُوا فَهُمْ لَا يَنْطِقُونَ', 'Ve vakaal kavlu aleyhim bima zalemu fe hum la yentıkun.', 'Ve haksızlıkları[1] nedeniyle üzerlerine söz[2] gerçekleşmiş oldu. Artık onlar konuşamazlar.', 'ووقع القول عليهم بما ظلموا فهم لا ينطقون'),
(3245, 27, 86, 'اَلَمْ يَرَوْا اَنَّا جَعَلْنَا الَّيْلَ لِيَسْكُنُوا ف۪يهِ وَالنَّهَارَ مُبْصِراًۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ', 'E lem yerev enna cealnel leyle li yeskunu fihi ven nehara mubsıra, inne fi zalike le ayatin li kavmin yu\'minun.', 'Dinginlik için geceyi nasıl karanlık,  iş görmeleri için gündüzü de nasıl aydınlık yaptığımızı görmüyorlar mı? Kuşkusuz bunda inanan toplum için ayetler[1] vardır.', 'الم يروا انا جعلنا اليل ليسكنوا فيه والنهار مبصرا ان في ذلك لايت لقوم يومنون'),
(3246, 27, 87, 'وَيَوْمَ يُنْفَخُ فِي الصُّورِ فَفَزِ  عَ مَنْ فِي السَّمٰوَاتِ وَمَنْ فِي الْاَرْضِ اِلَّا مَنْ شَٓاءَ اللّٰهُۜ وَكُلٌّ اَتَوْهُ دَاخِر۪ينَ', 'Ve yevme yunfehu fis suri fe fezia men fis semavati ve men fil ardı illa men şaallah, ve kullun etevhu dahırin.', 'Sur\'a üflendiği gün,  Allah\'ın dilediği kimseler[1] hariç,  göklerde ve yerde olanlar dehşete kapılacak ve hepsi aşağılanmış olarak geleceklerdir.', 'ويوم ينفخ في الصور ففزع من في السموت ومن في الارض الا من شا الله وكل اتوه دخرين'),
(3247, 27, 88, 'وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِيَ تَمُرُّ مَرَّ السَّحَابِۜ صُنْعَ اللّٰهِ الَّـذ۪ٓي اَتْقَنَ كُلَّ شَيْءٍۜ اِنَّهُ خَب۪يرٌ بِمَا تَفْعَلُونَ', 'Ve terel cibale tahsebuha camideten ve hiye temurru merres sehab, sun\'allahillezi etkane kulle şey\', innehu habirun bima tef\'alun.', 'Dağı görürsün,  onu hareketsiz sanırsın. Oysaki o bulut gibi hareket eder. Her şeyi mükemmel yapan Allah\'ın işidir bu. Kuşkusuz O,  yaptığınız her şeyden haberdardır.', 'وتري الجبال تحسبها جامدة وهي تمر مر السحاب صنع الله الذي اتقن كل شي انه خبير بما تفعلون'),
(3248, 27, 89, 'مَنْ جَٓاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْهَاۚ وَهُمْ مِنْ فَزَعٍ يَوْمَئِذٍ اٰمِنُونَ', 'Men cae bil haseneti fe lehu hayrun minha, ve hum min fezein yevmeizin aminun.', 'Kim iyi şeylerle geldiyse,  onun için getirdiğinden daha iyisi vardır. Onlar,  İzin Günü[1] dehşetten güvende olanlardır.', 'من جا بالحسنة فله خير منها وهم من فزع يوميذ امنون'),
(3249, 27, 90, 'وَمَنْ جَٓاءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِي النَّارِۜ هَلْ تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُونَ', 'Ve men cae bis seyyieti fe kubbet vucuhuhum fin nar, hel tuczevne illa ma kuntum ta\'melun.', 'Ve kim kötü şeylerle gelirse,  onlar da yüzüstü ateşe atılır. Yaptıklarınızın karşılığından başka bir şeyle mi cezalandırılıyorsunuz?', 'ومن جا بالسيية فكبت وجوههم في النار هل تجزون الا ما كنتم تعملون'),
(3250, 27, 91, 'اِنَّـمَٓا اُمِرْتُ اَنْ اَعْبُدَ رَبَّ هٰذِهِ الْبَلْدَةِ الَّذ۪ي حَرَّمَهَا وَلَهُ كُلُّ شَيْءٍۘ وَاُمِرْتُ اَنْ اَكُونَ مِنَ الْمُسْلِم۪ينَۙ', 'İnnema umirtu en a\'bude rabbe hazihil beldetillezi harremeha ve lehu kullu şey\'in ve umırtu en ekune minel muslimin.', 'Ben,  sadece bu beldeye saygınlık veren Rabb\'e kul olmakla emrolundum! Her şey O\'nundur. Ve ben Müslimin olmakla emrolundum!', 'انما امرت ان اعبد رب هذه البلدة الذي حرمها وله كل شي وامرت ان اكون من المسلمين'),
(3251, 27, 92, 'وَاَنْ اَتْلُوَا الْقُرْاٰنَۚ فَمَنِ اهْتَدٰى فَاِنَّمَا يَهْتَد۪ي لِنَفْسِه۪ۚ وَمَنْ ضَلَّ فَقُلْ اِنَّـمَٓا اَنَا۬ مِنَ الْمُنْذِر۪ينَ', 'Ve en etluvel kur\'an, fe menihteda fe innema yehtedi li nefsih, ve men dalle fe kul innema ene minel munzirin.', 'Ve Kur\'an okumakla[1]. Her kim doğru yola yönelirse,  kendisi için yönelmiş olur. Ve sapkın yolu seçenlere: \"Ben yalnızca bir uyarıcıyım.\" de.', 'وان اتلوا القران فمن اهتدي فانما يهتدي لنفسه ومن ضل فقل انما انا من المنذرين'),
(3252, 27, 93, 'وَقُلِ الْحَمْدُ لِلّٰهِ سَيُر۪يكُمْ اٰيَاتِه۪ فَتَعْرِفُونَهَاۜ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ', 'Ve kulil hamdu lillahi seyurikum ayatihi fe ta\'rifuneha, ve ma rabbuke bi gafilin amma ta\'melun.', 'Ve de ki: \"Hamd Allah\'adır. Size ayetlerini[1] gösterecek,  siz de onları tanıyacaksınız.\" Senin Rabb\'in,  yaptıklarınızdan habersiz değildir.', 'وقل الحمد لله سيريكم ايته فتعرفونها وما ربك بغفل عما تعملون'),
(3253, 28, 1, 'طٰسٓمٓۜ', 'Ta sin mim.', 'Ta. Sin. Mim.', 'طسم'),
(3254, 28, 2, 'تِلْكَ اٰيَاتُ الْكِتَابِ الْمُب۪ينِ', 'Tilke ayatul kitabil mubin.', 'İşte bunlar[1] gerçeği apaçık ortaya koyan Kitap\'ın ayetleridir.[1]', 'تلك ايت الكتب المبين'),
(3255, 28, 3, 'نَتْلُوا عَلَيْكَ مِنْ نَبَأِ مُوسٰى وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', 'Netlu aleyke min nebei musa ve fir\'avne bil hakkı li kavmin yu\'minun.', 'Biz,  sana inanan bir halk için ders alsınlar diye Musa ve Firavun\'un haberinden bir kısım gerçeği anlatacağız.', 'نتلوا عليك من نبا موسي وفرعون بالحق لقوم يومنون'),
(3256, 28, 4, 'اِنَّ فِرْعَوْنَ عَلَا فِي الْاَرْضِ وَجَعَلَ اَهْلَهَا شِيَعاً يَسْتَضْعِفُ طَٓائِفَةً مِنْهُمْ يُذَبِّـحُ اَبْنَٓاءَهُمْ وَيَسْتَحْـي۪ نِسَٓاءَهُمْۜ اِنَّهُ كَانَ مِنَ الْمُفْسِد۪ينَ', 'İnne fir\'avne ala fil ardı ve ceale ehleha şiyean yestad\'ıfu taifeten minhum yuzebbihu ebnaehum ve yestahyi nisaehum, innehu kane minel mufsidin.', 'Gerçek şu ki: Firavun,  büyüklenerek halkını sınıflara ayırdı. Onlardan bir sınıfı güçsüz düşürerek ezmek istiyor; erkek çocuklarını boğazlatıyor ve kadınlarını sağ bırakıyordu. Kuşkusuz o,  bozgunculardandı.', 'ان فرعون علا في الارض وجعل اهلها شيعا يستضعف طايفة منهم يذبح ابناهم ويستحي نساهم انه كان من المفسدين'),
(3257, 28, 5, 'وَنُر۪يدُ اَنْ نَمُنَّ عَلَى الَّذ۪ينَ اسْتُضْعِفُوا فِي الْاَرْضِ وَنَجْعَلَهُمْ اَئِمَّةً وَنَجْعَلَهُمُ الْوَارِث۪ينَۙ', 'Ve nuridu en nemunne alellezinestud\'ıfu fil ardı ve nec\'alehum eimmeten ve nec\'alehumul varisin.', 'Biz ise,  yeryüzünde ezilenlere iyilik yapmak[1] ve onları önderler kılmak ve varisler[2] yapmak istiyoruz.', 'ونريد ان نمن علي الذين استضعفوا في الارض ونجعلهم ايمة ونجعلهم الورثين'),
(3258, 28, 6, 'وَنُمَكِّنَ لَهُمْ فِي الْاَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا مِنْهُمْ مَا كَانُوا يَحْذَرُونَ', 'Ve numekkine lehum fil ardı ve nuriye fir\'avne ve hamane ve cunudehuma minhum ma kanu yahzerun.', 'Ve onları yeryüzünde iktidar yapalım,  Firavun\'a,  Haman\'a[1] ve ikisinin ordusuna,  onlardan çekindikleri şeyleri gösterelim.', 'ونمكن لهم في الارض ونري فرعون وهمن وجنودهما منهم ما كانوا يحذرون'),
(3259, 28, 7, 'وَاَوْحَيْنَٓا اِلٰٓى اُمِّ مُوسٰٓى اَنْ اَرْضِع۪يهِۚ فَاِذَا خِفْتِ عَلَيْهِ فَاَلْق۪يهِ فِي الْيَمِّ وَلَا تَخَاف۪ي وَلَا تَحْزَن۪يۚ اِنَّا رَٓادُّوهُ اِلَيْكِ وَجَاعِلُوهُ مِنَ الْمُرْسَل۪ينَ', 'Ve evhayna ila ummi musa en erdıih, fe iza hıfti aleyhi fe elkihi fil yemmi ve la tehafi ve la tahzeni, inna radduhu ileyki ve caıluhu minel murselin.', 'Musa\'nın annesine vahyettik: \"Onu emzir! Eğer onun için korkarsan,  onu suya[1] bırak. Ve korkma,  üzülme. Biz,  onu sana döndüreceğiz. Ve onu resullerden yapacağız.\"', 'واوحينا الي ام موسي ان ارضعيه فاذا خفت عليه فالقيه في اليم ولا تخافي ولا تحزني انا رادوه اليك وجاعلوه من المرسلين'),
(3260, 28, 8, 'فَالْتَقَطَهُٓ اٰلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُواًّ وَحَزَناًۜ اِنَّ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا كَانُوا خَاطِـ۪ٔينَ', 'Feltekatahu alu fir\'avne li yekune lehum aduvven ve hazena, inne fir\'avne ve hamane ve cunudehuma kanu hatıin.', 'Derken Firavun ailesi,  kendileri için bir düşman ve başlarına dert olacak olan onu,  buluntu olarak aldı. Firavun,  Haman ve askerleri yanlış yaptılar.', 'فالتقطه ال فرعون ليكون لهم عدوا وحزنا ان فرعون وهمن وجنودهما كانوا خطين'),
(3261, 28, 9, 'وَقَالَتِ امْرَاَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ ل۪ي وَلَكَۜ لَا تَقْتُلُوهُۗ عَسٰٓى اَنْ يَنْفَعَنَٓا اَوْ نَتَّخِذَهُ وَلَداً وَهُمْ لَا يَشْعُرُونَ', 'Ve kaletimraetu fir\'avne kurretu aynin li ve lek, la taktuluhu asa en yenfeana ev nettehızehu veleden ve hum la yeş\'urun.', 'Ve Firavun\'un karısı: \"Bana ve sana göz aydınlığı olsun. Onu öldürmeyin,  belki bize yararı olur. Veya onu evlat ediniriz.\" dedi. Onlar,  olacakların ayırdında değillerdi.', 'وقالت امرات فرعون قرت عين لي ولك لا تقتلوه عسي ان ينفعنا او نتخذه ولدا وهم لا يشعرون'),
(3262, 28, 10, 'وَاَصْبَحَ فُؤٰادُ اُمِّ مُوسٰى فَارِغاًۜ اِنْ كَادَتْ لَتُبْد۪ي بِه۪ لَوْلَٓا اَنْ رَبَطْنَا عَلٰى قَلْبِهَا لِتَكُونَ مِنَ الْمُؤْمِن۪ينَ', 'Ve asbaha fuadu ummi musa fariga, in kadet le tubdi bihi lev la en rabatna ala kalbiha li tekune minel mu\'minin.', 'Musa\'nın annesi gönlü boş olarak sabahladı. Eğer Biz sözümüze güvenenlerden olması için gönlünü pekiştirmeseydik az kalsın durumu açığa vuracaktı.', 'واصبح فواد ام موسي فرغا ان كادت لتبدي به لولا ان ربطنا علي قلبها لتكون من المومنين'),
(3263, 28, 11, 'وَقَالَتْ لِاُخْتِه۪ قُصّ۪يهِۘ فَبَصُرَتْ بِه۪ عَنْ جُنُبٍ وَهُمْ لَا يَشْعُرُونَۙ', 'Ve kalet li uhtihi kussihi fe besurat bihi an cunubin ve hum la yeş\'urun.', 'Kız kardeşine:[1] \"Onu izlemeye al.\" dedi. O da onlar farkında olmadan onu uzaktan izledi.', 'وقالت لاخته قصيه فبصرت به عن جنب وهم لا يشعرون'),
(3264, 28, 12, 'وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ فَقَالَتْ هَلْ اَدُلُّكُمْ عَلٰٓى اَهْلِ بَيْتٍ يَكْفُلُونَهُ لَكُمْ وَهُمْ لَهُ نَاصِحُونَ', 'Ve harremna aleyhil meradıa min kablu fe kalet hel edullukum ala ehli beytin yekfulunehu lekum ve hum lehu nasıhun.', 'Biz,  onun,  sütannelerinin sütünü emmemesini sağladık. Bunun üzerine:[1] \"Size,  onun bakımını üstlenecek ve onu iyi yetiştirecek bir aile göstereyim mi?\" dedi.', 'وحرمنا عليه المراضع من قبل فقالت هل ادلكم علي اهل بيت يكفلونه لكم وهم له نصحون'),
(3265, 28, 13, 'فَرَدَدْنَاهُ اِلٰٓى اُمِّه۪ كَيْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ اَنَّ وَعْدَ اللّٰهِ حَقٌّ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ۟', 'Fe redednahu ila ummihi key tekarra aynuha ve la tahzene ve li ta\'leme enne va\'dallahi hakkun ve lakinne ekserehum la ya\'lemun.', 'Derken gözü aydın olsun,  üzülmesin diye onu annesine kavuşturduk. Ve Allah\'ın sözünün gerçek olduğunu fakat onların çoğunun bunu anlamadığını bilsin.', 'فرددنه الي امه كي تقر عينها ولا تحزن ولتعلم ان وعد الله حق ولكن اكثرهم لا يعلمون'),
(3266, 28, 14, 'وَلَمَّا بَلَغَ اَشُدَّهُ وَاسْتَوٰٓى اٰتَيْنَاهُ حُكْماً وَعِلْماًۜ وَكَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'Ve lemma belega eşuddehu vesteva ateynahu hukmen ve ilma, ve kezalike neczil muhsinin.', 'Ve güçlü çağına erişip olgunlaşınca,  ona hikmet[1] ve ilim verdik.[2] İyileri işte böyle ödüllendiririz.', 'ولما بلغ اشده واستوي اتينه حكما وعلما وكذلك نجزي المحسنين'),
(3267, 28, 15, 'وَدَخَلَ الْمَد۪ينَةَ عَلٰى ح۪ينِ غَفْلَةٍ مِنْ اَهْلِهَا فَوَجَدَ ف۪يهَا رَجُلَيْنِ يَقْتَتِلَانِۘ هٰذَا مِنْ ش۪يعَتِه۪ وَهٰذَا مِنْ عَدُوِّه۪ۚ فَاسْتَغَاثَهُ الَّذ۪ي مِنْ ش۪يعَتِه۪ عَلَى الَّذ۪ي مِنْ عَدُوِّه۪ۙ فَوَكَزَهُ مُوسٰى فَقَضٰى عَلَيْهِۘ قَالَ هٰذَا مِنْ عَمَلِ الشَّيْطَانِۜ اِنَّهُ عَدُوٌّ مُضِلٌّ مُب۪ينٌ', 'Ve dehalel medinete ala hini gafletin min ehliha fe vecede fiha raculeyni yaktetilani haza min şiatihi ve haza min aduvvih, festegasehullezi min şiatihi alellezi min aduvvihi, fe vekezehu musa fe kada aleyhi kale haza min ameliş şeytan, innehu aduvvun mudillun mubin.', 'Musa,  şehir halkının habersiz olduğu bir sırada şehre girdi. Orada biri kendi tarafından,  diğeri de düşman olan taraftan kavga eden iki kişi buldu. Kendi tarafından olan,  diğerine karşı ondan yardım istedi. Bunun üzerine Musa onu yumrukladı ve ölümüne neden oldu. Musa: \"Bu şeytanın işindendir. Kuşkusuz o,  saptırıcı apaçık bir düşmandır.\" dedi.', 'ودخل المدينة علي حين غفلة من اهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغثه الذي من شيعته علي الذي من عدوه فوكزه موسي فقضي عليه قال هذا من عمل الشيطن انه عدو مضل مبين'),
(3268, 28, 16, 'قَالَ رَبِّ اِنّ۪ي ظَلَمْتُ نَفْس۪ي فَاغْفِرْ ل۪ي فَغَفَرَ لَهُۜ اِنَّهُ هُوَ الْغَفُورُ الرَّح۪يمُ', 'Kale rabbi inni zalemtu nefsi fagfirli fe gafera leh, innehu huvel gafurur rahim.', '\"Rabb\'im! Doğrusu ben kendime haksızlık yaptım. Artık beni bağışla.\" dedi. Böylece onu bağışladı. Gerçekten O; Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'قال رب اني ظلمت نفسي فاغفر لي فغفر له انه هو الغفور الرحيم'),
(3269, 28, 17, 'قَالَ رَبِّ بِمَٓا اَنْعَمْتَ عَلَيَّ فَلَنْ اَكُونَ ظَه۪يراً لِلْمُجْرِم۪ينَ', 'Kale rabbi bima en\'amte aleyye fe len ekune zahiren lil mucrimin.', 'Rabb\'im! Bana verdiğin nimet sayesinde,  bundan böyle asla mücrimlere arka çıkmayacağım.\" dedi.', 'قال رب بما انعمت علي فلن اكون ظهيرا للمجرمين'),
(3270, 28, 18, 'فَاَصْبَحَ فِي الْمَد۪ينَةِ خَٓائِفاً يَتَرَقَّبُ فَاِذَا الَّذِي اسْتَنْصَرَهُ بِالْاَمْسِ يَسْتَصْرِخُهُۜ قَالَ لَهُ مُوسٰٓى اِنَّكَ لَغَوِيٌّ مُب۪ينٌ', 'Fe asbaha fil medineti haifen yeterakkabu fe izellezistensarahu bil emsi yestasrihuh, kale lehu musa inneke le gaviyyun mubin.', 'Korku içinde etrafı kollayarak şehirde sabahladı. Bir de baktı ki dün yardım isteyen kişi yine yardım istiyor. Musa: \"Sen apaçık bir azgınsın!\" dedi.', 'فاصبح في المدينة خايفا يترقب فاذا الذي استنصره بالامس يستصرخه قال له موسي انك لغوي مبين'),
(3271, 28, 19, 'فَلَمَّٓا اَنْ اَرَادَ اَنْ يَبْطِشَ بِالَّذ۪ي هُوَ عَدُوٌّ لَهُمَاۙ قَالَ يَا مُوسٰٓى اَتُر۪يدُ اَنْ تَقْتُلَن۪ي كَمَا قَتَلْتَ نَفْساً بِالْاَمْسِۗ اِنْ تُر۪يدُ اِلَّٓا اَنْ تَكُونَ جَبَّاراً فِي الْاَرْضِ وَمَا تُر۪يدُ اَنْ تَكُونَ مِنَ الْمُصْلِح۪ينَ', 'Fe lemma en erade en yabtışe billezi huve aduvvun lehuma kale ya musa e turidu en taktuleni kema katelte nefsen bil emsi in turidu illa en tekune cebbaren fil ardı ve ma turidu en tekune minel muslihin.', 'İkisinin de düşmanı olan adamı yakalamak istediğinde: \"Ey Musa! Dün öldürdüğün kimse gibi beni de mi öldürmek istiyorsun? Sen yalnızca yeryüzünde bir zorba olmak istiyorsun,  arayı düzelticilerden olmak istemiyorsun.\" dedi.', 'فلما ان اراد ان يبطش بالذي هو عدو لهما قال يموسي اتريد ان تقتلني كما قتلت نفسا بالامس ان تريد الا ان تكون جبارا في الارض وما تريد ان تكون من المصلحين'),
(3272, 28, 20, 'وَجَٓاءَ رَجُلٌ مِنْ اَقْصَا الْمَد۪ينَةِ يَسْعٰىۘ قَالَ يَا مُوسٰٓى اِنَّ الْمَلَاَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَاخْرُجْ اِنّ۪ي لَكَ مِنَ النَّاصِح۪ينَ', 'Ve cae raculun min aksal medineti yes\'a kale ya musa innel melee ye\'temirune bike li yaktuluke fahruc inni leke minen nasıhin.', 'Şehrin diğer tarafından bir adam koşarak geldi. \"Ey Musa! Meleler[1] senin öldürülmen konusunda görüşme yapıyorlar. Derhal kaybol. Seni iyiliğin için uyarıyorum.\" dedi.', 'وجا رجل من اقصا المدينة يسعي قال يموسي ان الملا ياتمرون بك ليقتلوك فاخرج اني لك من النصحين'),
(3273, 28, 21, 'فَخَرَجَ مِنْهَا خَٓائِفاً يَتَرَقَّبُۘ قَالَ رَبِّ نَجِّن۪ي مِنَ الْقَوْمِ الظَّالِم۪ينَ۟', 'Fe harece minha haifen yeterakkabu, kale rabbi neccini minel kavmiz zalimin.', 'Bunun üzerine korku içinde etrafı kollayarak oradan ayrıldı: \"Rabb\'im! Beni bu zalim halktan kurtar.\" dedi.', 'فخرج منها خايفا يترقب قال رب نجني من القوم الظلمين'),
(3274, 28, 22, 'وَلَمَّا تَوَجَّهَ تِلْقَٓاءَ مَدْيَنَ قَالَ عَسٰى رَبّ۪ٓي اَنْ يَهْدِيَن۪ي سَوَٓاءَ السَّب۪يلِ', 'Ve lemma teveccehe tilkae medyene kale asa rabbi en yehdiyeni sevaes sebil.', 'Medyen tarafına yöneldiğinde: \"Umarım Rabb\'im bana bir çıkış yolu gösterir.\" dedi.', 'ولما توجه تلقا مدين قال عسي ربي ان يهديني سوا السبيل'),
(3275, 28, 23, 'وَلَمَّا وَرَدَ مَٓاءَ مَدْيَنَ وَجَدَ عَلَيْهِ اُمَّةً مِنَ النَّاسِ يَسْقُونَۘ وَوَجَدَ مِنْ دُونِهِمُ امْرَاَتَيْنِ تَذُودَانِۚ قَالَ مَا خَطْبُكُمَاۜ قَالَتَا لَا نَسْق۪ي حَتّٰى يُصْدِرَ الرِّعَٓاءُ وَاَبُونَا شَيْخٌ كَب۪يرٌ', 'Ve lemma verede mae medyene vecede aleyhi ummeten minen nasi yeskun, ve vecede min dunihimumreeteyni tezudan, kale ma hatbukuma, kaleta la neski hatta yusdirar riau ve ebuna şeyhun kebir.', 'Medyen suyuna vardığında,  orada hayvanlarını sulamakta olan birçok insan gördü. Bir de sürülerini sulamayı gözetleyen iki kadın vardı. Onlara: \"Neden böyle duruyorsunuz?\" dedi. \"Çobanlar sulayıp çekilmeden biz sulayamayız. Babamız çok ihtiyardır.\" dediler.', 'ولما ورد ما مدين وجد عليه امة من الناس يسقون ووجد من دونهم امراتين تذودان قال ما خطبكما قالتا لا نسقي حتي يصدر الرعا وابونا شيخ كبير'),
(3276, 28, 24, 'فَسَقٰى لَهُمَا ثُمَّ تَوَلّٰٓى اِلَى الظِّلِّ فَقَالَ رَبِّ اِنّ۪ي لِمَٓا اَنْزَلْتَ اِلَيَّ مِنْ خَيْرٍ فَق۪يرٌ', 'Fe seka lehuma summe tevella ilez zılli fe kale rabbi inni lima enzelte ileyye min hayrin fakir.', 'Bunun üzerine ikisi için hayvanları suladı. Sonra gölgeye çekildi. \"Rabb\'im! Ben,  bana hayır olarak indirdiğin her şeye muhtacım.\" dedi.', 'فسقي لهما ثم تولي الي الظل فقال رب اني لما انزلت الي من خير فقير'),
(3277, 28, 25, 'فَجَٓاءَتْهُ اِحْدٰيهُمَا تَمْش۪ي عَلَى اسْتِحْيَٓاءٍۘ قَالَتْ اِنَّ اَب۪ي يَدْعُوكَ لِيَجْزِيَكَ اَجْرَ مَا سَقَيْتَ لَنَاۜ فَلَمَّا جَٓاءَهُ وَقَصَّ عَلَيْهِ الْقَصَصَۙ قَالَ لَا تَخَفْ۠ نَجَوْتَ مِنَ الْقَوْمِ الظَّالِم۪ينَ', 'Fe caethu ıhdahuma temşi alestihyain, kalet inne ebi yed\'uke li yecziyeke ecra ma sekayte lena, fe lemma caehu ve kassa aleyhil kasasa kale la tehaf, necevte minel kavmiz zalimin.', 'Derken,  iki kızdan biri utana utana Musa\'ya geldi: \"Babam,  bizim yerimize sulamanın karşılığını vermek için seni çağırıyor.\" dedi. Musa,  yanına vararak başından geçenleri anlattı. \"Korkma! Zalimlerden kurtuldun.\" dedi.', 'فجاته احديهما تمشي علي استحيا قالت ان ابي يدعوك ليجزيك اجر ما سقيت لنا فلما جاه وقص عليه القصص قال لا تخف نجوت من القوم الظلمين'),
(3278, 28, 26, 'قَالَتْ اِحْدٰيهُمَا يَٓا اَبَتِ اسْتَأْجِرْهُۘ اِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْاَم۪ينُ', 'Kalet ıhdahuma ya ebetiste\'cirhu inne hayra meniste\'certel kaviyyul emin.', 'İki kızından biri: \"Ey babacığım! Onu ücretle tut. Gerçekten o,  ücretle tutacaklarının en iyisi,  güçlüsü ve güvenilirdir.\" dedi.', 'قالت احديهما يابت استجره ان خير من استجرت القوي الامين'),
(3279, 28, 27, 'قَالَ اِنّ۪ٓي اُر۪يدُ اَنْ اُنْكِحَكَ اِحْدَى ابْنَتَيَّ هَاتَيْنِ عَلٰٓى اَنْ تَأْجُرَن۪ي ثَمَانِيَ حِجَجٍۚ فَاِنْ اَتْمَمْتَ عَشْراً فَمِنْ عِنْدِكَۚ وَمَٓا اُر۪يدُ اَنْ اَشُقَّ عَلَيْكَۜ سَتَجِدُن۪ٓي اِنْ شَٓاءَ اللّٰهُ مِنَ الصَّالِح۪ينَ', 'Kale inni uridu en unkihake ihdebneteyye hateyni ala en te\'cureni semaniye hıcec, fe in etmemte aşran fe min indik, ve ma uridu en eşukka aleyk, seteciduni in şaallahu mines salihin.', 'Bu iki kızımdan birini,  bana sekiz hacc[1] boyunca çalışmana karşılık seninle evlendirmek istiyorum. Eğer ona tamamlarsan sen bilirsin. Sana rahatsızlık vermek istemem. İnşaallah beni salihlerden[2] bulacaksın.\" dedi.', 'قال اني اريد ان انكحك احدي ابنتي هتين علي ان تاجرني ثمني حجج فان اتممت عشرا فمن عندك وما اريد ان اشق عليك ستجدني ان شا الله من الصلحين'),
(3280, 28, 28, 'قَالَ ذٰلِكَ بَيْن۪ي وَبَيْنَكَۜ اَيَّمَا الْاَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَانَ عَلَيَّۜ وَاللّٰهُ عَلٰى مَا نَقُولُ وَك۪يلٌ۟', 'Kale zalike beyni ve beynek, eyyemel eceleyni kadaytu fe la udvane aleyy, vallahu ala ma nekulu vekil.', '\"Bu ikimizin arasındadır. Bu iki süreden hangisini tamamlarsam tamamlıyayım bana kırgınlık olmasın. Konuştuklarımıza Allah tanıktır.\" dedi.', 'قال ذلك بيني وبينك ايما الاجلين قضيت فلا عدون علي والله علي ما نقول وكيل'),
(3281, 28, 29, 'فَلَمَّا قَضٰى مُوسَى الْاَجَلَ وَسَارَ بِاَهْلِه۪ٓ اٰنَسَ مِنْ جَانِبِ الطُّورِ نَاراًۚ قَالَ لِاَهْلِهِ امْكُثُٓوا اِنّ۪ٓي اٰنَسْتُ نَاراً لَعَلّ۪ٓي اٰت۪يكُمْ مِنْهَا بِخَبَرٍ اَوْ جَذْوَةٍ مِنَ النَّارِ لَعَلَّكُمْ تَصْطَلُونَ', 'Fe lemma kada musel ecele ve sare bi ehlihi anese min canibit turi nara, kale li ehlihimkusu inni anestu naren lealli atikum minha bi haberin ev cezvetin minen nari leallekum testalun.', 'Musa,  süresini tamamlayınca,  ailesi ile yola çıktı. Tur tarafında bir ateş fark etti. Ailesine: \"Bekleyin. Ben bir ateş gördüm. Belki size ondan bir haber veya ısınmanız için bir ateş getiririm.\" dedi.', 'فلما قضي موسي الاجل وسار باهله انس من جانب الطور نارا قال لاهله امكثوا اني انست نارا لعلي اتيكم منها بخبر او جذوة من النار لعلكم تصطلون'),
(3282, 28, 30, 'فَلَمَّٓا اَتٰيهَا نُودِيَ مِنْ شَاطِئِ الْوَادِ الْاَيْمَنِ فِي الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ اَنْ يَا مُوسٰٓى اِنّ۪ٓي اَنَا اللّٰهُ رَبُّ الْعَالَم۪ينَۙ', 'Fe lemma etaha nudiye min şatııl vadil eymeni fil buk\'atil mubareketi mineş şecerati en ya musa inni enallahu rabbul alemin.', 'Oraya vardığında,  kutlu yerdeki vadinin sağ kıyısındaki bir ağaçtan kendisine seslenildi: \"Ey Musa! Ben,  alemlerin Rabb\'i Allah\'ım.\"', 'فلما اتيها نودي من شطي الواد الايمن في البقعة المبركة من الشجرة ان يموسي اني انا الله رب العلمين'),
(3283, 28, 31, 'وَاَنْ اَلْقِ عَصَاكَۜ فَلَمَّا رَاٰهَا تَهْتَزُّ كَاَنَّهَا جَٓانٌّ وَلّٰى مُدْبِراً وَلَمْ يُعَقِّبْۜ يَا مُوسٰٓى اَقْبِلْ وَلَا تَخَفْ۠ اِنَّكَ مِنَ الْاٰمِن۪ينَ', 'Ve en elkı asak, fe lemma reaha tehtezzu keenneha cannun vella mudbiren ve lem yuakkıb, ya musa akbil ve la tehaf, inneke minel aminin.', 'Asanı yere bırak! Onun yılan gibi hareket ettiğini görünce,  dönüp arkasına bakmadan kaçtı. \"Ey Musa,  dön! Korkma,  güvende olanlardansın.\"', 'وان الق عصاك فلما راها تهتز كانها جان ولي مدبرا ولم يعقب يموسي اقبل ولا تخف انك من الامنين'),
(3284, 28, 32, 'اُسْلُكْ يَدَكَ ف۪ي جَيْبِكَ تَخْرُجْ بَيْضَٓاءَ مِنْ غَيْرِ سُٓوءٍۘ وَاضْمُمْ اِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ فَذَانِكَ بُرْهَانَانِ مِنْ رَبِّكَ اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ۜ اِنَّهُمْ كَانُوا قَوْماً فَاسِق۪ينَ', 'Usluk yedeke fi ceybike tahruc beydae min gayri su, vadmum ileyke cenahake miner rehbi fe zanike burhanani min rabbike ila fir\'avne ve melaih, innehum kanu kavmen fasikin.', '\"Elini koynuna sok,  kusursuz beyaz olarak çıkar. Telaşlanma,  kollarını kendine çek. Bu ikisi,  senin Rabb\'inden,  Firavun ve onun melelerine[1] iki burhandır.[2] Kuşkusuz ki onlar,  sapkın bir kavimdir.\"', 'اسلك يدك في جيبك تخرج بيضا من غير سو واضمم اليك جناحك من الرهب فذانك برهنان من ربك الي فرعون وملايه انهم كانوا قوما فسقين'),
(3285, 28, 33, 'قَالَ رَبِّ اِنّ۪ي قَتَلْتُ مِنْهُمْ نَفْساً فَاَخَافُ اَنْ يَقْتُلُونِ', 'Kale rabbi inni kateltu minhum nefsen fe ehafu en yaktulun.', '\"Rabb\'im! Onlardan birisini öldürdüm. Onların da beni öldürmelerinden korkuyorum.\" dedi.', 'قال رب اني قتلت منهم نفسا فاخاف ان يقتلون'),
(3286, 28, 34, 'وَاَخ۪ي هٰرُونُ هُوَ اَفْصَحُ مِنّ۪ي لِسَاناً فَاَرْسِلْهُ مَعِيَ رِدْءاً يُصَدِّقُن۪يۘ اِنّ۪ٓي اَخَافُ اَنْ يُكَذِّبُونِ', 'Ve ahi harunu huve efsahu minni lisanen fe ersilhu maiye rid\'en yusaddıkuni, inni ehafu en yukezzibun.', '\"Kardeşim Harun\'un konuşması benden daha düzgündür. Onu da beni doğrulayan bir yardımcı olarak,  benimle birlikte gönder. Doğrusu beni yalanlamalarından korkuyorum.\"', 'واخي هرون هو افصح مني لسانا فارسله معي ردا يصدقني اني اخاف ان يكذبون'),
(3287, 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِاَخ۪يكَ وَنَجْعَلُ لَكُمَا سُلْطَاناً فَلَا يَصِلُونَ اِلَيْكُمَا بِاٰيَاتِنَاۚ اَنْتُمَا وَمَنِ اتَّـبَعَكُمَا الْغَالِبُونَ', 'Kale se neşuddu adudeke bi ahike ve nec\'alu lekuma sultanen fe la yasılune ileykuma bi ayatina, entuma ve menittebeakumel galibun.', '\"Senin gücünü kardeşinle arttıracağız. İkinizi de sultan[1] kılacağız. Onlar,  ayetlerimizden[2] dolayı size karşı koyamayacaklar. Siz ikiniz ve sizi izleyenler kazanacaksınız.\" dedi.', 'قال سنشد عضدك باخيك ونجعل لكما سلطنا فلا يصلون اليكما بايتنا انتما ومن اتبعكما الغلبون'),
(3288, 28, 36, 'فَلَمَّا جَٓاءَهُمْ مُوسٰى بِاٰيَاتِنَا بَيِّنَاتٍ قَالُوا مَا هٰذَٓا اِلَّا سِحْرٌ مُفْتَرًى وَمَا سَمِعْنَا بِهٰذَا ف۪ٓي اٰبَٓائِنَا الْاَوَّل۪ينَ', 'Fe lemma caehum musa bi ayatina beyyinatin kalu ma haza illa sihrun mufteren ve ma semi\'na bi haza fi abainel evvelin.', 'Musa onlara apaçık ayetlerimizi[1] iletince: \"Bu,  uydurulmuş bir sihirden başka bir şey değildir. Biz önceki atalarımızdan böyle bir şey duymadık.\" dediler.', 'فلما جاهم موسي بايتنا بينت قالوا ما هذا الا سحر مفتري وما سمعنا بهذا في اباينا الاولين'),
(3289, 28, 37, 'وَقَالَ مُوسٰى رَبّ۪ٓي اَعْلَمُ بِمَنْ جَٓاءَ بِالْهُدٰى مِنْ عِنْدِه۪ وَمَنْ تَكُونُ لَهُ عَاقِبَةُ الدَّارِۜ اِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', 'Ve kale musa rabbi a\'lemu bi men cae bil huda min indihi ve men tekunu lehu akıbetud dar, innehu la yuflihuz zalimun.', 'Musa: \"Rabb\'im,  kimin kendi katından doğru yolu göstermek için geldiğini ve hayırlı sonucun kimin olacağını en iyi bilendir. Kuşkusuz zalimler kurtuluşa eremezler.\" dedi.', 'وقال موسي ربي اعلم بمن جا بالهدي من عنده ومن تكون له عقبة الدار انه لا يفلح الظلمون'),
(3290, 28, 38, 'وَقَالَ فِرْعَوْنُ يَٓا اَيُّهَا الْمَلَأُ مَا عَلِمْتُ لَكُمْ مِنْ اِلٰهٍ غَيْر۪يۚ فَاَوْقِدْ ل۪ي يَا هَامَانُ عَلَى الطّ۪ينِ فَاجْعَلْ ل۪ي صَرْحاً لَعَلّ۪ٓي اَطَّلِعُ اِلٰٓى اِلٰهِ مُوسٰىۙ وَاِنّ۪ي لَاَظُنُّهُ مِنَ الْكَاذِب۪ينَ', 'Ve kale fir\'avnu ya eyyuhel meleu ma alimtu lekum min ilahin gayri, fe evkıd li ya hamanu alet tini fec\'al li sarhan lealli attaliu ila ilahi musa ve inni le ezunnuhu minel kazibin.', 'Firavun: \"Ey halkımın meleleri![1] Ben,  sizin için benden başka ilah bilmiyorum.[2] Ey Haman,  benim için çamur üzerine hemen bir ateş yak;[3] bana yüksek bir kule yap. Belki Musa\'nın ilahı ile karşılaşırım. Onun yalancılardan olduğunu zannediyorum.\"[4] dedi.', 'وقال فرعون يايها الملا ما علمت لكم من اله غيري فاوقد لي يهمن علي الطين فاجعل لي صرحا لعلي اطلع الي اله موسي واني لاظنه من الكذبين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3291, 28, 39, 'وَاسْتَكْبَرَ هُوَ وَجُنُودُهُ فِي الْاَرْضِ بِغَيْرِ الْحَقِّ وَظَنُّٓوا اَنَّهُمْ اِلَيْنَا لَا يُرْجَعُونَ', 'Vestekbere huve ve cunuduhu fil ardı bi gayril hakkı ve zannu ennehum ileyna la yurceun.', 'O ve ordusu yeryüzünde haksız yere büyüklendiler ve gerçekten de Bize döndürülmeyeceklerini sandılar.', 'واستكبر هو وجنوده في الارض بغير الحق وظنوا انهم الينا لا يرجعون'),
(3292, 28, 40, 'فَاَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّۚ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الظَّالِم۪ينَ', 'Fe ehaznahu ve cunudehu fe nebeznahum fil yemm, fanzur keyfe kane akıbetuz zalimin.', 'Sonra onu ve askerlerini yakalayıp suya gömdük. Bak bakalım,  zalimlerin sonunun nasıl olduğuna!', 'فاخذنه وجنوده فنبذنهم في اليم فانظر كيف كان عقبة الظلمين'),
(3293, 28, 41, 'وَجَعَلْنَاهُمْ اَئِمَّةً يَدْعُونَ اِلَى النَّارِۚ وَيَوْمَ الْقِيٰمَةِ لَا يُنْصَرُونَ', 'Ve cealnahum eimmeten yed\'une ilen nar, ve yevmel kıyameti la yunsarun.', 'Onları,  ateşe çağıran önderler yaptık. Ve Kıyamet Günü onlara yardım edilmez.', 'وجعلنهم ايمة يدعون الي النار ويوم القيمة لا ينصرون'),
(3294, 28, 42, 'وَاَتْبَعْنَاهُمْ ف۪ي هٰذِهِ الدُّنْيَا لَعْنَةًۚ وَيَوْمَ الْقِيٰمَةِ هُمْ مِنَ الْمَقْبُوح۪ينَ۟', 'Ve etba\'nahum fi hazihid dunya la\'neh ve yevmel kıyameti hum minel makbuhin.', 'Bu dünyada arkalarına bir lanet taktık.[1] Kıyamet Günü ise onlar çirkinleştirilmiş olanlardandır.', 'واتبعنهم في هذه الدنيا لعنة ويوم القيمة هم من المقبوحين'),
(3295, 28, 43, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ مِنْ بَعْدِ مَٓا اَهْلَكْنَا الْقُرُونَ الْاُو۫لٰى بَصَٓائِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَعَلَّهُمْ يَتَذَكَّرُونَ', 'Ve lekad ateyna musel kitabe min ba\'di ma ehleknel kurunel ula besaire lin nasi ve huden ve rahmeten leallehum yetezekkerun.', 'Ant olsun ki önceki nesilleri yok ettikten sonra; Musa\'ya,  öğüt alırlar diye,  basiretler[1],  doğru yolu gösteren ve rahmet olarak Kitap\'ı verdik.', 'ولقد اتينا موسي الكتب من بعد ما اهلكنا القرون الاولي بصاير للناس وهدي ورحمة لعلهم يتذكرون'),
(3296, 28, 44, 'وَمَا كُنْتَ بِجَانِبِ الْغَرْبِيِّ اِذْ قَضَيْنَٓا اِلٰى مُوسَى الْاَمْرَ وَمَا كُنْتَ مِنَ الشَّاهِد۪ينَۙ', 'Ve ma kunte bi canibil garbiyyi iz kadayna ila musel emre ve ma kunte mineş şahidin.', 'Sen,  Musa\'ya o emri yerine getirdiğimizde batı tarafında[1] değildin. Ve sen,  tanık olanlardan da değildin.', 'وما كنت بجانب الغربي اذ قضينا الي موسي الامر وما كنت من الشهدين'),
(3297, 28, 45, 'وَلٰكِنَّٓا اَنْشَأْنَا قُرُوناً فَتَطَاوَلَ عَلَيْهِمُ الْعُمُرُۚ وَمَا كُنْتَ ثَاوِياً ف۪ٓي اَهْلِ مَدْيَنَ تَتْلُوا عَلَيْهِمْ اٰيَاتِنَاۙ وَلٰكِنَّا كُنَّا مُرْسِل۪ينَ', 'Ve lakinna enşe\'na kurunen fe tetavele aleyhimul umur, ve ma kunte saviyen fi ehli medyene tetlu aleyhim ayatina, ve lakinna kunna mursilin.', 'Üstelik nice nesiller inşa ettik. Üzerlerinden ömürler geçti. Medyen Halkı arasında ayetlerimizi okuyan da sen değildin. Fakat seni Resul olarak gönderen Biziz.[1]', 'ولكنا انشانا قرونا فتطاول عليهم العمر وما كنت ثاويا في اهل مدين تتلوا عليهم ايتنا ولكنا كنا مرسلين'),
(3298, 28, 46, 'وَمَا كُنْتَ بِجَانِبِ الطُّورِ اِذْ نَادَيْنَا وَلٰكِنْ رَحْمَةً مِنْ رَبِّكَ لِتُنْذِرَ قَوْماً مَٓا اَتٰيهُمْ مِنْ نَذ۪يرٍ مِنْ قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'Ve ma kunte bi canibit turi iz nadeyna, ve lakin rahmeten min rabbike li tunzire kavmen ma etahum min nezirin min kablike leallehum yetezekkerun.', 'Ve seslendiğimiz zaman,  Tur\'un yanında da değildin. Fakat senden önce,  kendilerine bir uyarıcı gelmemiş olan halkı uyarman için,  seni Rabb\'inden bir rahmet olarak gönderdik. Umulur ki öğüt alırlar.', 'وما كنت بجانب الطور اذ نادينا ولكن رحمة من ربك لتنذر قوما ما اتيهم من نذير من قبلك لعلهم يتذكرون'),
(3299, 28, 47, 'وَلَوْلَٓا اَنْ تُص۪يبَهُمْ مُص۪يبَةٌ بِمَا قَدَّمَتْ اَيْد۪يهِمْ فَيَقُولُوا رَبَّـنَا لَوْلَٓا اَرْسَلْتَ اِلَيْنَا رَسُولاً فَنَتَّبِعَ اٰيَاتِكَ وَنَكُونَ مِنَ الْمُؤْمِن۪ينَ', 'Ve lev la en tusibehum musibetun bima kaddemet eydihim fe yekulu rabbena lev la erselte ileyna resulen fe nettebia ayatike ve nekune minel mu\'minin.', 'Eğer elleriyle sundukları nedeniyle[1] onlara bir bela isabet ederse: \"Rabb\'imiz! Keşke bize bir resul gönderseydin böylece biz,  Senin ayetlerine tabi olur ve inananlardan olurduk.\" diyemesinler diye.[2]', 'ولولا ان تصيبهم مصيبة بما قدمت ايديهم فيقولوا ربنا لولا ارسلت الينا رسولا فنتبع ايتك ونكون من المومنين'),
(3300, 28, 48, 'فَلَمَّا جَٓاءَهُمُ الْحَقُّ مِنْ عِنْدِنَا قَالُوا لَوْلَٓا اُو۫تِيَ مِثْلَ مَٓا اُو۫تِيَ مُوسٰىۜ اَوَلَمْ يَكْفُرُوا بِمَٓا اُو۫تِيَ مُوسٰى مِنْ قَبْلُۚ قَالُوا سِحْرَانِ تَظَاهَرَا۠ وَقَالُٓوا اِنَّا بِكُلٍّ كَافِرُونَ', 'Fe lemma caehumul hakku min indina kalu lev la utiye misle ma utıye musa, e ve lem yekfuru bima utiye musa min kabl, kalu sihrani tezaher, ve kalu inna bi kullin kafirun.', 'Ne var ki onlara hakk gelince: \"Musa\'ya verilen gibi[1] ona da verilseydi olmaz mıydı?\" dediler. Oysaki Musa\'ya verilenleri de daha önce inkar etmediler mi? \"Bunlar,  birbirine destek olan iki sihirbaz.\" dediler. Biz hepsini inkar edenleriz.\" dediler.', 'فلما جاهم الحق من عندنا قالوا لولا اوتي مثل ما اوتي موسي اولم يكفروا بما اوتي موسي من قبل قالوا سحران تظهرا وقالوا انا بكل كفرون'),
(3301, 28, 49, 'قُلْ فَأْتُوا بِكِتَابٍ مِنْ عِنْدِ اللّٰهِ هُوَ اَهْدٰى مِنْهُمَٓا اَتَّبِعْهُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kul fe\'tu bi kitabin min indillahi huve ehda min huma ettebi\' hu in kuntum sadikin.', 'De ki: \"Eğer doğru söyleyenlerdenseniz,  Allah\'ın katından,  o ikisinden[1] daha doğru yola ileten bir kitap getirin de ben de ona uyayım.\"', 'قل فاتوا بكتب من عند الله هو اهدي منهما اتبعه ان كنتم صدقين'),
(3302, 28, 50, 'فَاِنْ لَمْ يَسْتَج۪يبُوا لَكَ فَاعْلَمْ اَنَّمَا يَتَّبِعُونَ اَهْوَٓاءَهُمْۜ وَمَنْ اَضَلُّ مِمَّنِ اتَّبَعَ هَوٰيهُ بِغَيْرِ هُدًى مِنَ اللّٰهِۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'Fe in lem yestecibu leke fa\'lem ennema yettebiune ehvaehum, ve men edallu mimmenittebea hevahu bi gayri huden minallah, innallahe la yehdil kavmez zalimin.', 'Buna rağmen eğer sana uymazlarsa,  bil ki onlar hevalarına[1] uymaktadırlar. Allah\'tan bir yol gösterici olmaksızın kendi hevasına uyandan daha sapkın kim olabilir? Kuşkusuz Allah,  zalim bir toplumu doğru yola iletmez.', 'فان لم يستجيبوا لك فاعلم انما يتبعون اهواهم ومن اضل ممن اتبع هويه بغير هدي من الله ان الله لا يهدي القوم الظلمين'),
(3303, 28, 51, 'وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَۜ‌۟', 'Ve lekad vassalna lehumul kavle leallehum yetezekkerun.', 'Ant olsun! Öğüt alırlar diye,  onlara Söz\'ü[1] ardı ardına yolladık.', 'ولقد وصلنا لهم القول لعلهم يتذكرون'),
(3304, 28, 52, 'اَلَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ مِنْ قَبْلِه۪ هُمْ بِه۪ يُؤْمِنُونَ', 'Ellezine ateynahumul kitabe min kablihi hum bihi yu\'minun.', 'Ondan[1] önce kendilerine kitap verdiklerimiz,  O\'na[2] inanırlar.', 'الذين اتينهم الكتب من قبله هم به يومنون'),
(3305, 28, 53, 'وَاِذَا يُتْلٰى عَلَيْهِمْ قَالُٓوا اٰمَنَّا بِه۪ٓ اِنَّهُ الْحَقُّ مِنْ رَبِّنَٓا اِنَّا كُنَّا مِنْ قَبْلِه۪ مُسْلِم۪ينَ', 'Ve iza yutla aleyhim kalu amenna bihi innehul hakku min rabbina inna kunna min kablihi muslimin.', 'Onlara okunduğu[1] zaman: \"Ona inandık. Kuşkusuz o,  Rabb\'imizden gelen Hak\'tır. Biz ondan önce de teslim[2] olanlardık.\" dediler.', 'واذا يتلي عليهم قالوا امنا به انه الحق من ربنا انا كنا من قبله مسلمين'),
(3306, 28, 54, 'اُو۬لٰٓئِكَ يُؤْتَوْنَ اَجْرَهُمْ مَرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَؤُ۫نَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ', 'Ulaike yu\'tevne ecrehum merreteyni bima saberu ve yedraune bil hasenetis seyyiete ve mimma razaknahum yunfikun.', 'İşte onlara sabrettiklerinden dolayı,  ödülleri iki kat verilecektir. Onlar,  kötülüğü iyilik ile savarlar. Kendilerine verdiğimiz rızıktan infak[1] ederler.', 'اوليك يوتون اجرهم مرتين بما صبروا ويدرون بالحسنة السيية ومما رزقنهم ينفقون'),
(3307, 28, 55, 'وَاِذَا سَمِعُوا اللَّغْوَ اَعْرَضُوا عَنْهُ وَقَالُوا لَـنَٓا اَعْمَالُنَا وَلَكُمْ اَعْمَالُكُمْۘ سَلَامٌ عَلَيْكُمْۘ لَا نَبْتَغِي الْجَاهِل۪ينَ', 'Ve iza semiullagve a\'radu anhu, ve kalu lena a\'maluna ve lekum a\'malukum selamun aleykum la nebtegil cahilin.', 'Onlar,  kötü ve çirkin bir söz duydukları zaman,  ondan yüz çevirirler. Ve: \"Bizim yaptıklarımız bize,  sizin yaptıklarınız da size aittir. Selam üzerinize olsun. Bizim cahillerle işimiz olmaz.\" derler.', 'واذا سمعوا اللغو اعرضوا عنه وقالوا لنا اعملنا ولكم اعملكم سلم عليكم لا نبتغي الجهلين'),
(3308, 28, 56, 'اِنَّكَ لَا تَهْد۪ي مَنْ اَحْبَبْتَ وَلٰكِنَّ اللّٰهَ يَهْد۪ي مَنْ يَشَٓاءُۚ وَهُوَ اَعْلَمُ بِالْمُهْتَد۪ينَ', 'İnneke la tehdi men ahbebte ve lakinnallahe yehdi men yeşa\', ve huve a\'lemu bil muhtedin.', 'Sen,  sevdiğin kimseyi doğru yola iletemezsin; ama Allah hak edeni doğru yola iletir. O,  doğru yolu seçenleri iyi bilir.', 'انك لا تهدي من احببت ولكن الله يهدي من يشا وهو اعلم بالمهتدين'),
(3309, 28, 57, 'وَقَالُٓوا اِنْ نَتَّبِـعِ الْهُدٰى مَعَكَ نُتَخَطَّفْ مِنْ اَرْضِنَاۜ اَوَلَمْ نُمَكِّنْ لَهُمْ حَرَماً اٰمِناً يُجْبٰٓى اِلَيْهِ ثَمَرَاتُ كُلِّ شَيْءٍ رِزْقاً مِنْ لَدُنَّا وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Ve kalu in nettebiıl huda meake nutehattaf min ardına, e ve lem numekkin lehum haremen aminen yucba ileyhi semeratu kulli şey\'in rızkan min ledunna ve lakinne ekserehum la ya\'lemun.', '\"Eğer seninle beraber doğru yoldan gidersek,  yerimizden kovuluruz.\" dediler. Katımızdan bir rızık olarak her türlü ürünün kendilerine getirildiği,  saygı duyulan kutlu yere[1] güven içinde yerleştirmedik mi? Ne var ki onların çoğu bilmiyorlar.[2]', 'وقالوا ان نتبع الهدي معك نتخطف من ارضنا اولم نمكن لهم حرما امنا يجبي اليه ثمرت كل شي رزقا من لدنا ولكن اكثرهم لا يعلمون'),
(3310, 28, 58, 'وَكَمْ اَهْلَكْنَا مِنْ قَرْيَةٍ بَطِرَتْ مَع۪يشَتَهَاۚ فَتِلْكَ مَسَاكِنُهُمْ لَمْ تُسْكَنْ مِنْ بَعْدِهِمْ اِلَّا قَل۪يلاًۜ وَكُنَّا نَحْنُ الْوَارِث۪ينَ', 'Ve kem ehlekna min karyetin batırat maişeteha, fe tilke mesakinuhum lem tusken min ba\'dihim illa kalila, ve kunna nahnul varisin.', 'Şımararak,  geçindikleri şeylere şükretmeyen nice kenti yıkıma uğrattık. İşte bunlar,  onların yerleşim yerleri! Kendilerinden sonra pek az kullanılan evleri. Şimdi onların hepsi bize kaldı.', 'وكم اهلكنا من قرية بطرت معيشتها فتلك مسكنهم لم تسكن من بعدهم الا قليلا وكنا نحن الورثين'),
(3311, 28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ الْقُرٰى حَتّٰى يَبْعَثَ ف۪ٓي اُمِّهَا رَسُولاً يَتْلُوا عَلَيْهِمْ اٰيَاتِنَاۚ وَمَا كُنَّا مُهْلِكِي الْقُرٰٓى اِلَّا وَاَهْلُهَا ظَالِمُونَ', 'Ve ma kane rabbuke muhlikel kura hatta yeb\'ase fi ummiha resulen yetlu aleyhim ayatina, ve ma kunna muhlikil kura illa ve ehluha zalimun.', 'Rabb\'in,  ülkelerin ana merkezlerine kendilerine ayetlerimizi okuyan bir resulü göndermedikçe,  yıkıma uğratıcı olmadı. Biz,  halkı zulmetmedikçe,  kentleri yıkıma uğratıcı değiliz.', 'وما كان ربك مهلك القري حتي يبعث في امها رسولا يتلوا عليهم ايتنا وما كنا مهلكي القري الا واهلها ظلمون'),
(3312, 28, 60, 'وَمَٓا اُو۫ت۪يتُمْ مِنْ شَيْءٍ فَمَتَاعُ الْحَيٰوةِ الدُّنْيَا وَز۪ينَتُهَاۚ وَمَا عِنْدَ اللّٰهِ خَيْرٌ وَاَبْقٰىۜ اَفَلَا تَعْقِلُونَ۟', 'Ve ma utitum min şey\'in fe metaul hayatid dunya ve zinetuha ve ma indallahi hayrun ve ebka, e fe la ta\'kılun.', 'Size verilen her şey,  aslında dünya hayatının geçimliğidir ve ziynetidir.[1] Allah\'ın katında olanlar ise daha hayırlı ve daha kalıcıdır. Hala aklınızı kullanmayacak mısınız?', 'وما اوتيتم من شي فمتع الحيوة الدنيا وزينتها وما عند الله خير وابقي افلا تعقلون'),
(3313, 28, 61, 'اَفَمَنْ وَعَدْنَاهُ وَعْداً حَسَناً فَهُوَ لَاق۪يهِ كَمَنْ مَتَّعْنَاهُ مَتَاعَ الْحَيٰوةِ الدُّنْيَا ثُمَّ هُوَ يَوْمَ الْقِيٰمَةِ مِنَ الْمُحْضَر۪ينَ', 'E fe men vaadnahu va\'den hasenen fe huve lakihi ke men metta\'nahu metaal hayatid dunya summe huve yevmel kıyameti minel muhdarin.', 'Öyleyse,  kendisine iyi bir söz verdiğimiz ve mutlaka ona kavuşacak olan kimse,  dünya hayatının geçimliği ile geçimlerini sağladığımız,  sonra Kıyamet Günü hazır bulundurulacak[1] olan kimse gibi midir?', 'افمن وعدنه وعدا حسنا فهو لقيه كمن متعنه متع الحيوة الدنيا ثم هو يوم القيمة من المحضرين'),
(3314, 28, 62, 'وَيَوْمَ يُنَاد۪يهِمْ فَيَقُولُ اَيْنَ شُرَكَٓاءِيَ الَّذ۪ينَ كُنْتُمْ تَزْعُمُونَ', 'Ve yevme yunadihim fe yekulu eyne şurekaiyellezine kuntum tez\'umun.', 'O gün,  onlara seslenilir: \"Benim ortaklarım olduğunu ileri sürdükleriniz hani nerede?\"', 'ويوم يناديهم فيقول اين شركاي الذين كنتم تزعمون'),
(3315, 28, 63, 'قَالَ الَّذ۪ينَ حَقَّ عَلَيْهِمُ الْقَوْلُ رَبَّنَا هٰٓؤُ۬لَٓاءِ الَّذ۪ينَ اَغْوَيْنَاۚ اَغْوَيْنَاهُمْ كَمَا غَوَيْنَاۚ تَبَرَّأْنَٓا اِلَيْكَۘ مَا كَانُٓوا اِيَّانَا يَعْبُدُونَ', 'Kalellezine hakka aleyhimul kavlu rabbena haulaillezine agveyna, agveynahum kema gaveyna, teberre\'na ileyke ma kanu iyyana ya\'budun.', 'Haklarında sözün gerçekleştiği[1] kimseler: \"Rabb\'imiz! İşte bunlar azdırdığımız kimselerdir. Kendimiz azdığımız gibi,  onları da azdırdık.[2] Uzak olduğumuzu[3] Sana arz ederiz. Zaten onlar,  bize kulluk etmiyorlardı.\" dediler.', 'قال الذين حق عليهم القول ربنا هولا الذين اغوينا اغوينهم كما غوينا تبرانا اليك ما كانوا ايانا يعبدون'),
(3316, 28, 64, 'وَق۪يلَ ادْعُوا شُرَكَٓاءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَج۪يبُوا لَهُمْ وَرَاَوُا الْعَذَابَۚ لَوْ اَنَّهُمْ كَانُوا يَهْتَدُونَ', 'Ve kiled\'u şurekaekum fe deavhum fe lem yestecibu lehum ve reavul azab, lev ennehum kanu yehtedun.', 'Ve onlara: \"Ortaklarınızı çağırın.\" denildi. Onlar da çağırdılar. Ancak cevap alamadılar ve azapla karşı karşıya kaldılar. Keşke zamanında doğru yolu seçselerdi.', 'وقيل ادعوا شركاكم فدعوهم فلم يستجيبوا لهم وراوا العذاب لو انهم كانوا يهتدون'),
(3317, 28, 65, 'وَيَوْمَ يُنَاد۪يهِمْ فَيَقُولُ مَاذَٓا اَجَبْتُمُ الْمُرْسَل۪ينَ', 'Ve yevme yunadihim fe yekulu maza ecebtumul murselin.', 'Ve o gün Allah,  onlara seslenecek: \"Gönderilen resullere ne cevap verdiniz?\"', 'ويوم يناديهم فيقول ماذا اجبتم المرسلين'),
(3318, 28, 66, 'فَعَمِيَتْ عَلَيْهِمُ الْاَنْـبَٓاءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَٓاءَلُونَ', 'Fe amiyet aleyhimul enbau yevme izin fe hum la yetesaelun.', 'İzin Günü[1],  bütün özür yolları onlara kapanır. Artık onlar sorulmazlar.', 'فعميت عليهم الانبا يوميذ فهم لا يتسالون'),
(3319, 28, 67, 'فَاَمَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ صَالِحاً فَعَسٰٓى اَنْ يَكُونَ مِنَ الْمُفْلِح۪ينَ', 'Fe emma men tabe ve amene ve amile salihan fe asa en yekune minel muflihin.', 'Fakat tevbe eden[1],  iman eden ve salihatı yapan[2] kimse,  kurtuluşa erenlerden olacağını umabilir.', 'فاما من تاب وامن وعمل صلحا فعسي ان يكون من المفلحين'),
(3320, 28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَٓاءُ وَيَخْتَارُۜ مَا كَانَ لَهُمُ الْخِيَرَةُۜ سُبْحَانَ اللّٰهِ وَتَعَالٰى عَمَّا يُشْرِكُونَ', 'Ve rabbuke yahluku ma yeşau ve yahtar, ma kane lehumul hıyarat, subhanallahi ve teala amma yuşrikun.', 'Ve Rabb\'in,  dilediği şeyi yaratır ve onlar için hayırlı olanı seçer.[1] Seçim onların değildir. Allah,  onların ortak koştuklarından münezzehtir ve yüceler yücesidir.', 'وربك يخلق ما يشا ويختار ما كان لهم الخيرة سبحن الله وتعلي عما يشركون'),
(3321, 28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'Ve rabbuke ya\'lemu ma tukinnu suduruhum ve ma yu\'linun.', 'Ve Rabb\'in,  onların sinelerinde gizledikleri şeyleri de açığa vurdukları şeyleri de bilir.', 'وربك يعلم ما تكن صدورهم وما يعلنون'),
(3322, 28, 70, 'وَهُوَ اللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۜ  لَهُ الْحَمْدُ فِي الْاُو۫لٰى وَالْاٰخِرَةِۘ وَلَهُ الْحُكْمُ وَاِلَيْهِ تُرْجَعُونَ', 'Ve huvallahu la ilahe illa huve, lehul hamdu fil ula vel ahırati ve lehul hukmu ve ileyhi turceun.', 'O,  Kendisinden başka ilah olmayan Allah\'tır. Her işin başında da sonunda da tüm övgüler onun içindir. Ve karar O\'na aittir. Ve O\'na döndürüleceksiniz.', 'وهو الله لا اله الا هو له الحمد في الاولي والاخرة وله الحكم واليه ترجعون'),
(3323, 28, 71, 'قُلْ اَرَاَيْتُمْ اِنْ جَعَلَ اللّٰهُ عَلَيْكُمُ الَّيْلَ سَرْمَداً اِلٰى يَوْمِ الْقِيٰمَةِ مَنْ اِلٰهٌ غَيْرُ اللّٰهِ يَأْت۪يكُمْ بِضِيَٓاءٍۜ اَفَلَا تَسْمَعُونَ', 'Kul e reeytum in cealallahu aleykumul leyle sermeden ila yevmil kıyameti men ilahun gayrullahi ye\'tikum bi dıya\', e fe la tesme\'un.', 'Baksanıza! Eğer Allah,  üzerinize geceyi,  Kıyamet Günü\'ne kadar aralıksız devam ettirse,  Allah\'tan başka size aydınlığı verecek olan ilah kimdir? Hala gerçeğe kulak vermeyecek misiniz?', 'قل اريتم ان جعل الله عليكم اليل سرمدا الي يوم القيمة من اله غير الله ياتيكم بضيا افلا تسمعون'),
(3324, 28, 72, 'قُلْ اَرَاَيْتُمْ اِنْ جَعَلَ اللّٰهُ عَلَيْكُمُ النَّهَارَ سَرْمَداً اِلٰى يَوْمِ الْقِيٰمَةِ مَنْ اِلٰهٌ غَيْرُ اللّٰهِ يَأْت۪يكُمْ بِلَيْلٍ تَسْكُنُونَ ف۪يهِۜ اَفَلَا تُبْصِرُونَ', 'Kul e reeytum in cealallahu aleykumun nehare sermeden ila yevmil kıyameti men ilahun gayrullahi ye\'tikum bi leylin teskunune fih, e fe la tubsırun.', 'Baksanıza! Eğer Allah,  üzerinize gündüzü kıyamet gününe kadar aralıksız devam ettirse,  Allah\'tan başka size içinde dinlendiğiniz geceyi getirecek ilah kimdir? Hala gerçeği görmeyecek misiniz?', 'قل اريتم ان جعل الله عليكم النهار سرمدا الي يوم القيمة من اله غير الله ياتيكم بليل تسكنون فيه افلا تبصرون'),
(3325, 28, 73, 'وَمِنْ رَحْمَتِه۪ جَعَلَ لَكُمُ الَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا ف۪يهِ وَلِتَبْتَغُوا مِنْ فَضْلِه۪ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Ve min rahmetihi ceale lekumul leyle ven nehare li teskunu fihi ve li tebtegu min fadlihi ve leallekum teşkurun.', 'Gece ve gündüzün olması O\'nun rahmetindendir; dinlenmeniz için ve lütfundan rızkınızı temin etmeniz için geceyi ve gündüzü düzenledi. Umulur ki şükredersiniz.[1]', 'ومن رحمته جعل لكم اليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون'),
(3326, 28, 74, 'وَيَوْمَ يُنَاد۪يهِمْ فَيَقُولُ اَيْنَ شُرَكَٓاءِيَ الَّذ۪ينَ كُنْتُمْ تَزْعُمُونَ', 'Ve yevme yunadihim fe yekulu eyne şurekaiyellezine kuntum tez\'umun.', 'O gün onlara seslenecek: \"Ortaklarım olduğunu iddia ettikleriniz hani nerede?\" diye soracak.', 'ويوم يناديهم فيقول اين شركاي الذين كنتم تزعمون'),
(3327, 28, 75, 'وَنَزَعْنَا مِنْ كُلِّ اُمَّةٍ شَه۪يداً فَقُلْنَا هَاتُوا بُرْهَانَكُمْ فَعَلِمُٓوا اَنَّ الْحَقَّ لِلّٰهِ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ۟', 'Ve neza\'na min kulli ummetin şehiden fe kulna hatu burhanekum fe alimu ennel hakka lillahi ve dalle anhum ma kanu yefterun.', 'Her ümmetten bir tanık çıkarırız. Sonra da: \"Burhanlarınızı[1] getirin.\" deriz. Böylece hakikatin Allah\'a ait olduğunu anlarlar. Uydurdukları şeyler,  onlardan ayrılıp kaybolurlar.', 'ونزعنا من كل امة شهيدا فقلنا هاتوا برهنكم فعلموا ان الحق لله وضل عنهم ما كانوا يفترون'),
(3328, 28, 76, 'اِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسٰى فَبَغٰى عَلَيْهِمْۖ وَاٰتَيْنَاهُ مِنَ الْكُنُوزِ مَٓا اِنَّ مَفَاتِحَهُ لَتَنُٓوأُ بِالْعُصْبَةِ اُو۬لِي الْقُوَّةِۗ اِذْ قَالَ لَهُ قَوْمُهُ لَا تَفْرَحْ اِنَّ اللّٰهَ لَا يُحِبُّ الْفَرِح۪ينَ', 'İnne karune kane min kavmi musa, fe bega aleyhim, ve ateynahu minel kunuzi ma inne mefatihahu le tenuu bil usbeti ulil kuvveh, iz kale lehu kavmuhu la tefrah innallahe la yuhıbbul ferihin.', 'Karun,  Musa\'nın halkından birisiydi. Halkına karşı azgınlaştı. Ona öyle hazineler vermiştik ki,  onların anahtarlarını güçlü bir topluluk zor taşıyordu. Halkı ona: \"Şımarma! Allah şımaranları sevmez.\" demişti.', 'ان قرون كان من قوم موسي فبغي عليهم واتينه من الكنوز ما ان مفاتحه لتنوا بالعصبة اولي القوة اذ قال له قومه لا تفرح ان الله لا يحب الفرحين'),
(3329, 28, 77, 'وَابْتَغِ ف۪يمَٓا اٰتٰيكَ اللّٰهُ الدَّارَ الْاٰخِرَةَ وَلَا تَنْسَ نَص۪يبَكَ مِنَ الدُّنْيَا وَاَحْسِنْ كَمَٓا اَحْسَنَ اللّٰهُ اِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِي الْاَرْضِۜ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُفْسِد۪ينَ', 'Vebtegı fima atakellahud darel ahırete ve la tense nasibekemined dunya ve ahsin kema ahsenallahu ileyke ve la tebgıl fesade fil ard, innallahe la yuhıbbul mufsidin.', '\"Allah\'ın sana verdikleri ile ahiret yurdunu elde etmeye çalış. Ve dünyadan da nasibini unutma. Allah\'ın sana iyilikte bulunduğu gibi,  sen de insanlara iyilikte bulun. Ve yeryüzünde bozgunculuk yapma. Allah,  bozguncuları sevmez.\"', 'وابتغ فيما اتيك الله الدار الاخرة ولا تنس نصيبك من الدنيا واحسن كما احسن الله اليك ولا تبغ الفساد في الارض ان الله لا يحب المفسدين'),
(3330, 28, 78, 'قَالَ اِنَّـمَٓا اُو۫ت۪يتُهُ عَلٰى عِلْمٍ عِنْد۪يۜ اَوَلَمْ يَعْلَمْ اَنَّ اللّٰهَ قَدْ اَهْلَكَ مِنْ قَبْلِه۪ مِنَ الْقُرُونِ مَنْ هُوَ اَشَدُّ مِنْهُ قُوَّةً وَاَكْثَرُ جَمْعاًۜ وَلَا يُسْـَٔلُ عَنْ ذُنُوبِهِمُ الْمُجْرِمُونَ', 'Kale innema utituhu ala ilmin indi, e ve lem ya\'lem ennellahe kad ehleke min kablihi minel kuruni men huve eşeddu minhu kuvveten ve ekseru cem\'a, ve la yus\'elu an zunubihimul mucrimun.', 'Karun: \"Bu serveti bilgili olmam sayesinde elde ettim.\" dedi. Allah\'ın daha önce ondan daha güçlü olan ve ondan daha çok taraftarı ve birikimi olan kuşakları yıkıma uğratmış olduğunu bilmiyor mu? Mücrimlere[1] suçlarından sorulmaz.[2]', 'قال انما اوتيته علي علم عندي اولم يعلم ان الله قد اهلك من قبله من القرون من هو اشد منه قوة واكثر جمعا ولا يسل عن ذنوبهم المجرمون'),
(3331, 28, 79, 'فَخَرَجَ عَلٰى قَوْمِه۪ ف۪ي ز۪ينَتِه۪ۜ قَالَ الَّذ۪ينَ يُر۪يدُونَ الْحَيٰوةَ الدُّنْيَا يَا لَيْتَ لَنَا مِثْلَ مَٓا اُو۫تِيَ قَارُونُۙ اِنَّهُ لَذُو حَظٍّ عَظ۪يمٍ', 'Fe harece ala kavmihi fi zinetih, kalellezine yuridunel hayated dunya ya leyte lena misle ma utiye karunu innehu le zu hazzın azim.', 'Karun,  ziynetli[1] bir şekilde halkının karşısına çıktı. Dünya hayatına düşkünlüğü olanlar: \"Keşke bizim de Karun gibi varlığımız olsaydı! Gerçekten o,  çok kısmetli biri.\" diye iç geçirdiler.', 'فخرج علي قومه في زينته قال الذين يريدون الحيوة الدنيا يليت لنا مثل ما اوتي قرون انه لذو حظ عظيم'),
(3332, 28, 80, 'وَقَالَ الَّذ۪ينَ اُو۫تُوا الْعِلْمَ وَيْلَكُمْ ثَوَابُ اللّٰهِ خَيْرٌ لِمَنْ اٰمَنَ وَعَمِلَ صَالِحاًۚ وَلَا يُلَقّٰيهَٓا اِلَّا الصَّابِرُونَ', 'Ve kalellezine utul ilme veylekum sevabullahi hayrun li men amene ve amile saliha ve la yulekkaha illes sabirun.', 'İlim verilmiş olanlar[1]: \"Size yazıklar olsun! İnanan ve salihatı[2] yapan kimselere Allah\'ın vereceği ödül daha hayırlıdır. Buna sabredenlerden[3] başkası kavuşamaz.\" dediler.', 'وقال الذين اوتوا العلم ويلكم ثواب الله خير لمن امن وعمل صلحا ولا يلقيها الا الصبرون'),
(3333, 28, 81, 'فَخَسَفْنَا بِه۪ وَبِدَارِهِ الْاَرْضَ فَمَا كَانَ لَهُ مِنْ فِئَةٍ يَنْصُرُونَهُ مِنْ دُونِ اللّٰهِۗ وَمَا كَانَ مِنَ الْمُنْتَصِر۪ينَ', 'Fe hasefna bihi ve bidarihil arda fe ma kane lehu min fietin yensurunehu min dunillahi ve ma kane minel muntasırin.', 'Sonra,  onu ve yurdunu yerin dibine geçirdik. Allah\'a karşı kendisine yardım edecek bir taraftar da olmadı. Yardım edilenlerden de olmadı.', 'فخسفنا به وبداره الارض فما كان له من فية ينصرونه من دون الله وما كان من المنتصرين'),
(3334, 28, 82, 'وَاَصْبَحَ الَّذ۪ينَ تَمَنَّوْا مَكَانَهُ بِالْاَمْسِ يَقُولُونَ وَيْكَاَنَّ اللّٰهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ مِنْ عِبَادِه۪ وَيَقْدِرُۚ لَوْلَٓا اَنْ مَنَّ اللّٰهُ عَلَيْنَا لَخَسَفَ بِنَاۜ وَيْكَاَنَّهُ لَا يُفْلِحُ الْكَافِرُونَ۟', 'Ve asbehallezine temennev mekanehu bil emsi yekulune vey keennellahe yebsutur rızka li men yeşau min ıbadihi ve yakdir, lev la en mennallahu aleyna le hasefe bina, vey keennehu la yuflihul kafirun.', 'Dün,  onun yerinde olmayı isteyenler; bugün,  \"Demek ki,  kullarından dilediğine rızkı genişleten ve ölçülendiren Allah\'mış. Eğer Allah bize lutfetmiş[1] olmasaydı,  bizi de yerin dibine geçirirdi. Demek ki Kafirler[2] kurtuluşa eremezler.\" dediler.', 'واصبح الذين تمنوا مكانه بالامس يقولون ويكان الله يبسط الرزق لمن يشا من عباده ويقدر لولا ان من الله علينا لخسف بنا ويكانه لا يفلح الكفرون'),
(3335, 28, 83, 'تِلْكَ الدَّارُ الْاٰخِرَةُ نَجْعَلُهَا لِلَّذ۪ينَ لَا يُر۪يدُونَ عُلُواًّ فِي الْاَرْضِ وَلَا فَسَاداًۜ وَالْعَاقِبَةُ لِلْمُتَّق۪ينَ', 'Tilked darul ahıretu nec\'aluha lillezine la yuridune uluvven fil ardı ve la fesada, vel akıbetu lil muttekin.', 'İşte ahiret yurdu! Onu,  yeryüzünde büyüklük taslamayan ve bozgunculuk yapmayan kimseler için ayırdık. Gelecek takva[1] sahiplerinindir.', 'تلك الدار الاخرة نجعلها للذين لا يريدون علوا في الارض ولا فسادا والعقبة للمتقين'),
(3336, 28, 84, 'مَنْ جَٓاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْهَاۚ وَمَنْ جَٓاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى الَّذ۪ينَ عَمِلُوا السَّيِّـَٔاتِ اِلَّا مَا كَانُوا يَعْمَلُونَ', 'Men cae bil haseneti fe lehu hayrun minha ve men cae bis seyyieti fe la yuczellezine amilus seyyiati illa ma kanu ya\'melun.', 'Kim bir iyilik ile gelirse; ona,  ondan daha hayırlısı vardır. Kim de bir kötülük ile gelirse; yaptığı kötülük kadar cezalandırılır.', 'من جا بالحسنة فله خير منها ومن جا بالسيية فلا يجزي الذين عملوا السيات الا ما كانوا يعملون'),
(3337, 28, 85, 'اِنَّ الَّذ۪ي فَرَضَ عَلَيْكَ الْقُرْاٰنَ لَـرَٓادُّكَ اِلٰى مَعَادٍۜ   قُلْ رَبّ۪ٓي اَعْلَمُ مَنْ جَٓاءَ بِالْهُدٰى وَمَنْ هُوَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'İnnellezi farada aleykel kur\'ane le radduke ila mead, kul rabbi a\'lemu men cae bil huda ve men huve fi dalalin mubin.', 'Sana Kur\'an\'ı farz kılan[1],  elbette seni dönülecek yere döndürecektir. De ki: \"Kimin doğru yolda olduğunu ve kimin sapkın olduğunu Rabb\'im bilir.\"', 'ان الذي فرض عليك القران لرادك الي معاد قل ربي اعلم من جا بالهدي ومن هو في ضلل مبين'),
(3338, 28, 86, 'وَمَا كُنْتَ تَرْجُٓوا اَنْ يُلْقٰٓى اِلَيْكَ الْكِتَابُ اِلَّا رَحْمَةً مِنْ رَبِّكَ فَلَا تَكُونَنَّ ظَه۪يراً لِلْكَافِر۪ينَۘ', 'Ve ma kunte tercu en yulka ileykel kitabu illa rahmeten min rabbike fe la tekunenne zahiren lil kafirin.', 'Sen,  Kitap\'ın sana iletileceğini beklemiyordun. O,  ancak Rabb\'inden bir rahmet olarak verildi. Öyleyse sakın Kafirlere destek[1] olma.', 'وما كنت ترجوا ان يلقي اليك الكتب الا رحمة من ربك فلا تكونن ظهيرا للكفرين'),
(3339, 28, 87, 'وَلَا يَصُدُّنَّكَ عَنْ اٰيَاتِ اللّٰهِ بَعْدَ اِذْ اُنْزِلَتْ اِلَيْكَ وَادْعُ اِلٰى رَبِّكَ وَلَا تَكُونَنَّ مِنَ الْمُشْرِك۪ينَۚ', 'Ve la yasuddunneke an ayatillahi ba\'de iz unzılet ileyke ved\'u ila rabbike ve la tekunenne minel muşrikin.', 'Sana indirilen,  Allah\'ın ayetleridir. Sakın seni ondan alıkoymasınlar[1]. Sen,  insanları Rabb\'ine çağır. Müşriklerden olma.[2]', 'ولا يصدنك عن ايت الله بعد اذ انزلت اليك وادع الي ربك ولا تكونن من المشركين'),
(3340, 28, 88, 'وَلَا تَدْعُ مَعَ اللّٰهِ اِلٰهاً اٰخَرَۢ  لَٓا اِلٰهَ اِلَّا هُوَ۠   كُلُّ شَيْءٍ هَالِكٌ اِلَّا وَجْهَهُۜ  لَهُ الْحُكْمُ وَاِلَيْهِ تُرْجَعُونَ', 'Ve la ted\'u meallahi ilahen ahar, la ilahe illa hu, kullu şey\'in halikun illa vecheh, lehul hukmu ve ileyhi turceun.', 'Allah ile birlikte başka ilahtan istekte bulunma. O\'ndan başka ilah yoktur. O\'nun yüzü[1] hariç her şey yok olucudur. Hüküm O\'nundur. Ve O\'na döndürüleceksiniz.', 'ولا تدع مع الله الها اخر لا اله الا هو كل شي هالك الا وجهه له الحكم واليه ترجعون'),
(3341, 29, 1, 'الٓمٓ ۠', 'Elif lam mim.', 'Elif. Lam. Mim.', 'الم'),
(3342, 29, 2, 'اَحَسِبَ النَّاسُ اَنْ يُتْرَكُٓوا اَنْ يَقُولُٓوا اٰمَنَّا وَهُمْ لَا يُفْتَنُونَ', 'E hasiben nasu en yutreku en yekulu amenna ve hum la yuftenun.', 'İnsanlar,  inandık demekle fitnelendirilmeden[1] bırakılacaklarını mı sanıyorlar.', 'احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون'),
(3343, 29, 3, 'وَلَقَدْ فَتَنَّا الَّذ۪ينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللّٰهُ الَّذ۪ينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِب۪ينَ', 'Ve lekad fetennellezine min kablihim fe le ya\'lemennellahullezine sadaku ve le ya\'lemenel kazibin.', 'Ant olsun ki onlardan öncekilerini de fitnelendirmiştik. Böylece Allah,  kimin samimi kimin de yalancı olduğunu ortaya çıkarmaktadır.', 'ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكذبين'),
(3344, 29, 4, 'اَمْ حَسِبَ الَّذ۪ينَ يَعْمَلُونَ السَّيِّـَٔاتِ اَنْ يَسْبِقُونَاۜ سَٓاءَ مَا يَحْكُمُونَ', 'Em hasibellezine ya\'melunes seyyiati en yesbikuna, sae ma yahkumun.', 'Yoksa kötülük yapanlar,  Bizden kurtulacaklarını mı sanıyorlar? Ne kötü bir yargıda bulunuyorlar!', 'ام حسب الذين يعملون السيات ان يسبقونا سا ما يحكمون'),
(3345, 29, 5, 'مَنْ كَانَ يَرْجُوا لِقَٓاءَ اللّٰهِ فَاِنَّ اَجَلَ اللّٰهِ لَاٰتٍۜ وَهُوَ السَّم۪يعُ الْعَل۪يمُ', 'Men kane yercu likaallahi fe inne ecelallahi leat, ve huves semiul alim.', 'Allah\'a kavuşacaklarını[1] umanlar bilsinler ki,  Allah\'ın belirlediği zaman mutlaka gelecektir. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'من كان يرجوا لقا الله فان اجل الله لات وهو السميع العليم'),
(3346, 29, 6, 'وَمَنْ جَاهَدَ فَاِنَّمَا يُجَاهِدُ لِنَفْسِه۪ۜ اِنَّ اللّٰهَ لَغَنِيٌّ عَنِ الْعَالَم۪ينَ', 'Ve men cahede fe innema yucahidu li nefsih, innallahe le ganiyyun anil alemin.', 'Kim cihad[1] ederse,  ancak kendisi için cihad etmiş olur. Allah,  kesinlikle hiç kimseye,  hiçbir şeye muhtaç değildir.[2]', 'ومن جهد فانما يجهد لنفسه ان الله لغني عن العلمين'),
(3347, 29, 7, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ اَحْسَنَ الَّذ۪ي كَانُوا يَعْمَلُونَ', 'Vellezine amenu ve amilus salihati le nukeffiranne anhum seyyiatihim ve le necziyennehum ahsenellezi kanu ya\'melun.', 'İnanan ve salihatı[1] yapanların kötülüklerine mutlaka küfrederiz.[2] Ve kesinlikle onlara yaptıklarından daha iyisi ile karşılık vereceğiz.', 'والذين امنوا وعملوا الصلحت لنكفرن عنهم سياتهم ولنجزينهم احسن الذي كانوا يعملون'),
(3348, 29, 8, 'وَوَصَّيْنَا الْاِنْسَانَ بِوَالِدَيْهِ حُسْناًۜ وَاِنْ جَاهَدَاكَ لِتُشْرِكَ ب۪ي مَا لَيْسَ لَكَ بِه۪ عِلْمٌ فَلَا تُطِعْهُمَاۜ اِلَيَّ مَرْجِعُكُمْ فَاُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ve vassaynel insane bi valideyhi husna, ve in cahedake li tuşrike bi ma leyse leke bihi ilmun fe la tutı\'huma, ileyye merciukum fe unebbiukum bima kuntum ta\'melun.', 'Biz,  insana anne ve babasına iyi davranmasını tavsiye ettik. Eğer onlar,  hakkında bilgin[1] olmayan bir şey ile Bana şirk koşman için seninle cihad[2] ederlerse,  onları dinleme. Dönüşünüz ancak Bana\'dır. O zaman yapmış olduklarınızı size haber vereceğim.', 'ووصينا الانسن بولديه حسنا وان جهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبيكم بما كنتم تعملون'),
(3349, 29, 9, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُدْخِلَنَّهُمْ فِي الصَّالِح۪ينَ', 'Vellezine amenu ve amilus salihati le nudhılennehum fis salihin.', 'İnanan ve salihatı[1] yapanları da; kesinlikle salihlerin[2] arasına katacağız.', 'والذين امنوا وعملوا الصلحت لندخلنهم في الصلحين'),
(3350, 29, 10, 'وَمِنَ النَّاسِ مَنْ يَقُولُ اٰمَنَّا بِاللّٰهِ فَاِذَٓا اُو۫ذِيَ فِي اللّٰهِ جَعَلَ فِتْنَةَ النَّاسِ كَعَذَابِ اللّٰهِۜ وَلَئِنْ جَٓاءَ نَصْرٌ مِنْ رَبِّكَ لَيَقُولُنَّ اِنَّا كُنَّا مَعَكُمْۜ اَوَلَيْسَ اللّٰهُ بِاَعْلَمَ بِمَا ف۪ي صُدُورِ الْعَالَم۪ينَ', 'Ve minen nasi men yekulu amenna billahi fe iza uziye fillahi ceale fitneten nasi ke azabillah, ve le in cae nasrun min rabbike le yekulunne inna kunna meakum, e ve leysallahu bi a\'leme bi ma fi suduril alemin.', 'Allah\'a iman ettiğini söyleyen kimi insanlar vardır ki,  Allah yolunda bir eziyet gördükleri zaman,  insanların fitnesini[1] Allah\'ın azabı ile bir tutarlar. Eğer Rabb\'lerinden bir yardım gelecek olsa[2],  kesinlikle,  \"Kuşku yok ki biz sizinle beraberdik.\" diyeceklerdir. Oysaki Allah,  herkesin göğsünde olanı en iyi bilen değil midir?', 'ومن الناس من يقول امنا بالله فاذا اوذي في الله جعل فتنة الناس كعذاب الله ولين جا نصر من ربك ليقولن انا كنا معكم اوليس الله باعلم بما في صدور العلمين'),
(3351, 29, 11, 'وَلَيَعْلَمَنَّ اللّٰهُ الَّذ۪ينَ اٰمَنُوا وَلَيَعْلَمَنَّ الْمُنَافِق۪ينَ', 'Ve le ya\'lemennallahullezine amenu ve le ya\'lemennel munafikin.', 'Allah,  elbette inananları bilir ve elbette kimlerin de münafık[1] olduğunu da bilir.', 'وليعلمن الله الذين امنوا وليعلمن المنفقين'),
(3352, 29, 12, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لِلَّذ۪ينَ اٰمَنُوا اتَّبِعُوا سَب۪يلَنَا وَلْنَحْمِلْ خَطَايَاكُمْۜ وَمَا هُمْ بِحَامِل۪ينَ مِنْ خَطَايَاهُمْ مِنْ شَيْءٍۜ اِنَّهُمْ لَكَاذِبُونَ', 'Ve kalellezine keferu lillezine amenuttebiu sebilena velnahmil hatayakum, ve ma hum bi hamiline min hatayahum min şey\', innehum le kazibun.', 'Kafirler: İnananlara: \"Bizim yolumuza uyun,  sizin yanlışlarınızı biz üstlenelim.\" dediler. Oysa onlar,  başkalarının hatalarından hiçbir şey üstlenemezler. Kesinlikle onlar yalancıdırlar.', 'وقال الذين كفروا للذين امنوا اتبعوا سبيلنا ولنحمل خطيكم وما هم بحملين من خطيهم من شي انهم لكذبون'),
(3353, 29, 13, 'وَلَيَحْمِلُنَّ اَثْقَالَهُمْ وَاَثْقَالاً مَعَ اَثْقَالِهِمْۘ وَلَيُسْـَٔلُنَّ يَوْمَ الْقِيٰمَةِ عَمَّا كَانُوا يَفْتَرُونَ۟', 'Ve le yahmilunne eskalehum ve eskalen mea eskalihim ve le yus\'elunne yevmel kıyameti amma kanu yefterun.', 'Onlar hem kendi yüklerini hem kendi yükleri ile birlikte başka yükleri taşıyacaklar. Kıyamet Günü,  kesinlikle uydurdukları şeylerden hesaba çekilecekler.', 'وليحملن اثقالهم واثقالا مع اثقالهم وليسلن يوم القيمة عما كانوا يفترون'),
(3354, 29, 14, 'وَلَقَدْ اَرْسَلْنَا نُوحاً اِلٰى قَوْمِه۪ فَلَبِثَ ف۪يهِمْ اَلْفَ سَنَةٍ اِلَّا خَمْس۪ينَ عَاماًۜ فَاَخَذَهُمُ الطُّوفَانُ وَهُمْ ظَالِمُونَ', 'Ve lekad erselna nuhan ila kavmihi, fe lebise fihim elfe senetin illa hamsine ama, fe ehazehumut tufanu ve hum zalimun.', 'Ant olsun ki Nuh\'u halkına gönderdik. Onların içinde bin aydan[1] elli yıl[2] eksik kaldı. Sonunda haksızlık edenleri tufan aldı.', 'ولقد ارسلنا نوحا الي قومه فلبث فيهم الف سنة الا خمسين عاما فاخذهم الطوفان وهم ظلمون'),
(3355, 29, 15, 'فَاَنْجَيْنَاهُ وَاَصْحَابَ السَّف۪ينَةِ وَجَعَلْنَاهَٓا اٰيَةً لِلْعَالَم۪ينَ', 'Fe enceynahu ve ashabes sefineti ve cealna haayeten lil alemin.', 'Böylece onu ve gemideki arkadaşlarını kurtardık. Onu[1] cümle aleme bir ayet[2] yaptık.', 'فانجينه واصحب السفينة وجعلنها اية للعلمين'),
(3356, 29, 16, 'وَاِبْرٰه۪يمَ اِذْ قَالَ لِقَوْمِهِ اعْبُدُوا اللّٰهَ وَاتَّقُوهُۜ ذٰلِكُمْ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Ve ibrahime iz kale li kavmihi\'budullahe vettekuh, zalikum hayrun lekum in kuntum ta\'lemun.', 'İbrahim,  halka: \"Allah\'a kul[1] olun ve O\'na karşı takva sahibi olun. Eğer bilirseniz bu sizin için daha hayırlıdır.\" demişti.', 'وابرهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون'),
(3357, 29, 17, 'اِنَّمَا تَعْبُدُونَ مِنْ دُونِ اللّٰهِ اَوْثَاناً وَتَخْلُقُونَ اِفْكاًۜ اِنَّ الَّذ۪ينَ تَعْبُدُونَ مِنْ دُونِ اللّٰهِ لَا يَمْلِكُونَ لَكُمْ رِزْقاً فَابْتَغُوا عِنْدَ اللّٰهِ الرِّزْقَ وَاعْبُدُوهُ وَاشْكُرُوا لَهُۜ اِلَيْهِ تُرْجَعُونَ', 'İnnema ta\'budune min dunillahi evsanen ve tahlukune ifka, innellezine ta\'budune min dunillahi la yemlikune lekum rızkan, febtegu indallahir rızka va\'buduhu veşkuru leh, ileyhi turceun.', '\"Siz ise,  Allah\'tan başka,  birtakım putlara kulluk ediyorsunuz ve tasarladığınız putlarla iftira ediyorsunuz. Şunu iyi bilin ki,  Allah\'tan başka kulluk ettikleriniz,  size bir rızık vermeye güç yetiremezler. Öyleyse,  rızkı Allah\'tan isteyin. Ve yalnızca O\'na kulluk edin. O\'na şükredin. Eninde sonunda O\'na döndürüleceksiniz.\"', 'انما تعبدون من دون الله اوثنا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون'),
(3358, 29, 18, 'وَاِنْ تُكَذِّبُوا فَقَدْ كَذَّبَ اُمَمٌ مِنْ قَبْلِكُمْۜ وَمَا عَلَى الرَّسُولِ اِلَّا الْبَلَاغُ الْمُب۪ينُ', 'Ve in tukezzibu fe kad kezzebe umemun min kablikum, ve ma aler resuli illel belagul mubin.', '\"Eğer yalanlarsanız,  şunu bilin ki,  sizden öncekiler de yalanlamışlardı. Resule düşen de açıkça çağrı yapmaktan başka bir şey değildir.\"', 'وان تكذبوا فقد كذب امم من قبلكم وما علي الرسول الا البلغ المبين'),
(3359, 29, 19, 'اَوَلَمْ يَرَوْا كَيْفَ يُبْدِئُ اللّٰهُ الْخَلْقَ ثُمَّ يُع۪يدُهُۜ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَس۪يرٌ', 'E ve lem yerev keyfe yubdiullahul halka, summe yuiduh , inne zalike alallahi yesir.', 'Onlar,  Allah\'ın yaratmayı nasıl başlattığını hiç düşünmüyorlar mı? Sonra onu tekrarlayacak. Kuşkusuz bu,  Allah\'a çok kolaydır.', 'اولم يروا كيف يبدي الله الخلق ثم يعيده ان ذلك علي الله يسير'),
(3360, 29, 20, 'قُلْ س۪يرُوا فِي الْاَرْضِ فَانْظُرُوا كَيْفَ بَدَاَ الْخَلْقَ ثُمَّ اللّٰهُ يُنْشِئُ النَّشْاَةَ الْاٰخِرَةَۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌۚ', 'Kul siru fil ardı fanzuru keyfe bedeel halka, summallahu yunşiun neş\'etel ahıreh, innallahe ala kulli şey\'in kadir.', 'De ki: \"Yeryüzünde gezip dolaşın da ilk[1] yaratışın nasıl olduğuna bakın. Sonra Allah,  son inşa etmeyi de aynı şekilde yapacaktır. Allah,  Her Şeye Güç Yetiren\'dir.\"', 'قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشي النشاة الاخرة ان الله علي كل شي قدير'),
(3361, 29, 21, 'يُعَذِّبُ مَنْ يَشَٓاءُ وَيَرْحَمُ مَنْ يَشَٓاءُۚ وَاِلَيْهِ تُقْلَبُونَ', 'Yuazzibu men yeşau ve yerhamu men yeşa\', ve ileyhi tuklebun.', 'O,  Hak eden[1] kimseye azap eder,  hak eden[1] kimseye de rahmet eder.[1] Ve O\'na döndürüleceksiniz.', 'يعذب من يشا ويرحم من يشا واليه تقلبون'),
(3362, 29, 22, 'وَمَٓا اَنْتُمْ بِمُعْجِز۪ينَ فِي الْاَرْضِ وَلَا فِي السَّمَٓاءِۘ وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ۟', 'Ve ma entum bi mu\'cizine fil ardı ve la fis semai ve ma lekum min dunillahi min veliyyin ve la nasir.', 'Siz,  yerde ve gökte aciz bırakacak değilsiniz. Sizin Allah\'ın yanı sıra başka veliniz ve yardımcınız yoktur.', 'وما انتم بمعجزين في الارض ولا في السما وما لكم من دون الله من ولي ولا نصير'),
(3363, 29, 23, 'وَالَّذ۪ينَ كَفَرُوا بِاٰيَاتِ اللّٰهِ وَلِقَٓائِه۪ٓ اُو۬لٰٓئِكَ يَـئِسُوا مِنْ رَحْمَت۪ي وَاُو۬لٰٓئِكَ لَهُمْ عَذَابٌ اَل۪يمٌ', 'Vellezine keferu bi ayatillahi ve likaihi ulaike yeisu min rahmeti ve ulaike lehum azabun elim.', 'Allah\'ın ayetlerini ve O\'nunla buluşma gerçeğini yok sayanlar; işte onlar,  Benim rahmetimden ümitlerini kesmişlerdir. Onlar için acıklı bir azap vardır.', 'والذين كفروا بايت الله ولقايه اوليك ييسوا من رحمتي واوليك لهم عذاب اليم'),
(3364, 29, 24, 'فَمَا كَانَ جَوَابَ قَوْمِه۪ٓ اِلَّٓا اَنْ قَالُوا اقْتُلُوهُ اَوْ حَرِّقُوهُ فَاَنْجٰيهُ اللّٰهُ مِنَ النَّارِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ', 'Fe ma kane cevabe kavmihi illa en kaluktuluhu ev harrýkuhu fe encahullahu minen nar, inne fi zalike le ayatin li kavmin yu\'minun.', 'Sonra onun halkının cevabı: \"Onu öldürün veya yakın!\" demeleri oldu. Bunun üzerine Allah,  onu ateşten kurtardı. Bunda iman edecek bir halk için kesinlikle ayetler[1] vardır.', 'فما كان جواب قومه الا ان قالوا اقتلوه او حرقوه فانجيه الله من النار ان في ذلك لايت لقوم يومنون'),
(3365, 29, 25, 'وَقَالَ اِنَّمَا اتَّخَذْتُمْ مِنْ دُونِ اللّٰهِ اَوْثَاناًۙ مَوَدَّةَ بَيْنِكُمْ فِي الْحَيٰوةِ الدُّنْيَاۚ ثُمَّ يَوْمَ الْقِيٰمَةِ يَكْفُرُ بَعْضُكُمْ بِبَعْضٍ وَيَلْعَنُ بَعْضُكُمْ بَعْضاًۘ وَمَأْوٰيكُمُ النَّارُ  وَمَا لَكُمْ مِنْ نَاصِر۪ينَۗ', 'Ve kale innemettehaztum min dunillahi evsanen meveddete beynikum fil hayatid dunya, summe yevmel kıyameti yekfuru ba\'dukum bi ba\'dın ve yel\'anu ba\'dukum ba\'dan ve me\'vakumun naru ve ma lekum min nasırin.', 'İbrahim: \"Siz,  dünya hayatında Allah\'ın yanı sıra putları aranızda dostluk vesilesi edindiniz. Sonra Kıyamet Günü,  bir kısmınız bir kısmınızı yalanlayacak ve bir kısmınız bir kısmınızı lanetleyeceksiniz. Varacağınız yer ateştir. Ve sizin için bir yardımcı yoktur.\" dedi.', 'وقال انما اتخذتم من دون الله اوثنا مودة بينكم في الحيوة الدنيا ثم يوم القيمة يكفر بعضكم ببعض ويلعن بعضكم بعضا وماويكم النار وما لكم من نصرين'),
(3366, 29, 26, 'فَاٰمَنَ لَهُ لُوطٌۢ وَقَالَ اِنّ۪ي مُهَاجِرٌ اِلٰى رَبّ۪يۜ اِنَّهُ هُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Fe amene lehu lut  ve kale inni muhacirun ila rabbi, innehu huvel azizul hakim.', 'Bunun üzerine Lut,  O\'na[1] inandı. Ve dedi ki: \"Ben,  Rabb\'im için hicret ediyorum. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.\"', 'فامن له لوط وقال اني مهاجر الي ربي انه هو العزيز الحكيم'),
(3367, 29, 27, 'وَوَهَبْنَا لَـهُٓ اِسْحٰقَ وَيَعْقُوبَ وَجَعَلْنَا ف۪ي ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَابَ وَاٰتَيْنَاهُ اَجْرَهُ فِي الدُّنْيَاۚ وَاِنَّهُ فِي الْاٰخِرَةِ لَمِنَ الصَّالِح۪ينَ', 'Ve vehebna lehu ishaka ve ya\'kube ve cealna fi zurriyyetihin nubuvvete vel kitabe, ve ateynahu ecrehu fid dunya, ve innehu fil ahıreti le mines salihin.', 'Biz O\'na İshak\'ı ve Yakub\'u hibe ettik. Onun soyundan gelenlere nebilik ve kitap verdik. Böylece O\'na dünyada ödülünü verdik. O,  ahirette de elbette salihlerden olacaktır.', 'ووهبنا له اسحق ويعقوب وجعلنا في ذريته النبوة والكتب واتينه اجره في الدنيا وانه في الاخرة لمن الصلحين'),
(3368, 29, 28, 'وَلُوطاً اِذْ قَالَ لِقَوْمِه۪ٓ اِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَۘ مَا سَبَقَكُمْ بِهَا مِنْ اَحَدٍ مِنَ الْعَالَم۪ينَ', 'Ve lutan iz kale li kavmihi innekum le te\'tunel fahışete ma sebekakum biha min ehadin minel alemin.', 'Hani Lut halkına: \"Siz,  bu alemde sizden önce yaşamış olanların hiçbirinin yapmadığı bir fahişeliğe[1] yöneliyorsunuz.\" demişti.', 'ولوطا اذ قال لقومه انكم لتاتون الفحشة ما سبقكم بها من احد من العلمين'),
(3369, 29, 29, 'اَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ وَتَقْطَعُونَ السَّب۪يلَ وَتَأْتُونَ ف۪ي نَاد۪يكُمُ الْمُنْكَرَۜ فَمَا كَانَ جَوَابَ قَوْمِه۪ٓ اِلَّٓا اَنْ قَالُوا ائْتِنَا بِعَذَابِ اللّٰهِ اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'E innekum le te\'tuner ricale ve taktaunes sebile ve te\'tune fi nadikumulmunker, fe ma kane cevabe kavmihi illa en kalu\'tina bi azabillahi in kunte mines sadikin.', '\"Gerçekten siz; erkeklere yönelecek,  yanlış yolu seçecek ve bir araya gelerek çirkinlik yapacak mısınız?\" Halkının yanıtı: \"Eğer doğru söyleyenlerden isen Allah\'ın azabını bize getir.\" demeleri oldu.', 'اينكم لتاتون الرجال وتقطعون السبيل وتاتون في ناديكم المنكر فما كان جواب قومه الا ان قالوا ايتنا بعذاب الله ان كنت من الصدقين'),
(3370, 29, 30, 'قَالَ رَبِّ انْصُرْن۪ي عَلَى الْقَوْمِ الْمُفْسِد۪ينَ۟', 'Kale rabbinsurni alel kavmil mufsidin.', 'Lut: \"Rabb\'im! Bozgunculuk yapan halka karşı bana yardım et.\" dedi.', 'قال رب انصرني علي القوم المفسدين'),
(3371, 29, 31, 'وَلَمَّا جَٓاءَتْ رُسُلُـنَٓا اِبْرٰه۪يمَ بِالْبُشْرٰىۙ قَالُٓوا اِنَّا مُهْلِكُٓوا اَهْلِ هٰذِهِ الْقَرْيَةِۚ اِنَّ اَهْلَهَا كَانُوا ظَالِم۪ينَۚ', 'Ve lemma caet rusuluna ibrahime bil buşra, kalu inna muhliku ehli hazihil karyeh, inne ehleha kanu zalimin.', 'Resullerimiz[1] İbrahim\'e müjdeyi getirdiklerinde:[2] \"Biz bu beldenin halkını helak edeceğiz.\" dediler. \"Zira bu beldenin halkı zalim oldular.\"', 'ولما جات رسلنا ابرهيم بالبشري قالوا انا مهلكوا اهل هذه القرية ان اهلها كانوا ظلمين'),
(3372, 29, 32, 'قَالَ اِنَّ ف۪يهَا لُـوطاًۜ قَالُوا نَحْنُ اَعْلَمُ بِمَنْ ف۪يهَاۘ لَنُنَجِّيَنَّهُ وَاَهْلَـهُٓ اِلَّا امْرَاَتَهُۘ كَانَتْ مِنَ الْغَابِر۪ينَ', 'Kale inne fiha luta, kalu nahnu a\'lemu bi men fiha le nunecciyennehu ve ehlehu illemreetehu kanet minel gabirin.', 'İbrahim: \"Fakat orada Lut var!\" dedi. \"Biz,  orada kimin olduğunu daha iyi biliriz. Geride kalanlarla beraber olacak olan karısı hariç,  onu ve ehlini[1] mutlaka kurtaracağız.\" dediler.', 'قال ان فيها لوطا قالوا نحن اعلم بمن فيها لننجينه واهله الا امراته كانت من الغبرين'),
(3373, 29, 33, 'وَلَمَّٓا اَنْ جَٓاءَتْ رُسُلُنَا لُـوطاً س۪ٓيءَ بِهِمْ وَضَـاقَ بِهِمْ ذَرْعاً وَقَالُوا لَا تَخَفْ وَلَا تَحْزَنْ۠ اِنَّا مُنَجُّوكَ وَاَهْلَكَ اِلَّا امْرَاَتَكَ كَانَتْ مِنَ الْغَابِر۪ينَ', 'Ve lemma en caet rusuluna lutan sie bihim ve daka bihim zer\'an, ve kalu la tehaf ve la tahzen, inna muneccuke ve ehleke illemreeteke kanet minel gabirin.', 'Elçilerimiz Lut\'a vardıkları zaman,  onların gelmelerinden dolayı telaşlandı,  sarkıntılık yapacaklarını düşünerek içi daraldı. Elçiler: \"Korkma ve üzülme; Biz -geride kalanlarla beraber olacak olan karın hariç- seni ve ehlini mutlaka kurtaracağız.\" dediler.', 'ولما ان جات رسلنا لوطا سي بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن انا منجوك واهلك الا امراتك كانت من الغبرين'),
(3374, 29, 34, 'اِنَّا مُنْزِلُونَ عَلٰٓى اَهْلِ هٰذِهِ الْقَرْيَةِ رِجْزاً مِنَ السَّمَٓاءِ بِمَا كَانُوا يَفْسُقُونَ', 'İnna munzilune ala ehli hazihil karyeti riczen mines semai bima kanu yefsukun.', 'Biz,  bu belde halkının üzerine,  yoldan çıkmaları nedeniyle gökten bir azap indireceğiz.', 'انا منزلون علي اهل هذه القرية رجزا من السما بما كانوا يفسقون'),
(3375, 29, 35, 'وَلَقَدْ تَرَكْنَا مِنْهَٓا اٰيَةً بَيِّنَةً لِقَوْمٍ يَعْقِلُونَ', 'Ve lekad terekna minha ayeten beyyineten li kavmin ya\'kılun.', 'Ant olsun ki Biz,  aklını kullanan bir halk için ondan[1] apaçık bir ayet[2] bıraktık.', 'ولقد تركنا منها اية بينة لقوم يعقلون'),
(3376, 29, 36, 'وَاِلٰى مَدْيَنَ اَخَاهُمْ شُعَيْباًۙ فَقَالَ يَا قَوْمِ اعْبُدُوا اللّٰهَ وَارْجُوا الْيَوْمَ الْاٰخِرَ وَلَا تَعْثَوْا فِي الْاَرْضِ مُفْسِد۪ينَ', 'Ve ila medyene ehahum şuayben fe kale ya kavmi\'budullahe vercul yevmel ahıre ve la ta\'sev fil ardı mufsidin.', 'Medyen halkına da kardeşleri Şuayb\'ı gönderdik. Şuayb: \"Ey halkım! Allah\'a kulluk edin. Ahiret Günü\'nü umut edin. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın!\" dedi.', 'والي مدين اخاهم شعيبا فقال يقوم اعبدوا الله وارجوا اليوم الاخر ولا تعثوا في الارض مفسدين'),
(3377, 29, 37, 'فَكَذَّبُوهُ فَاَخَذَتْهُمُ الرَّجْفَةُ فَاَصْبَحُوا ف۪ي دَارِهِمْ جَاثِم۪ينَۘ', 'Fe kezzebuhu fe ehazethumur recfetu fe asbehu fi darihim casimin.', 'Fakat onu yalanladılar. Bu nedenle onları şiddetli bir sarsıntı yakaladı ve yurtlarında dizüstü çöke kaldılar.', 'فكذبوه فاخذتهم الرجفة فاصبحوا في دارهم جثمين'),
(3378, 29, 38, 'وَعَاداً وَثَمُودَا۬ وَقَدْ تَبَيَّنَ لَكُمْ مِنْ مَسَاكِنِهِمْ۠ وَزَيَّنَ لَهُمُ الشَّيْطَانُ اَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّب۪يلِ وَكَانُوا مُسْتَبْصِر۪ينَۙ', 'Ve aden ve semude ve kad tebeyyene lekum min mesakinihim, ve zeyyene lehumuş şeytanu a\'malehum fe saddehum anis sebili ve kanu mustebsırin.', 'Âd ve Semud\'un sonları da yurtlarının durumundan size belli olmaktadır. Şeytan yaptıklarını güzel göstererek onların yanlış yolu seçmelerine sebep oldu. Oysaki doğruyu görebilirlerdi.', 'وعادا وثمودا وقد تبين لكم من مسكنهم وزين لهم الشيطن اعملهم فصدهم عن السبيل وكانوا مستبصرين'),
(3379, 29, 39, 'وَقَارُونَ وَفِرْعَوْنَ وَهَامَانَ وَلَقَدْ جَٓاءَهُمْ مُوسٰى بِالْبَيِّنَاتِ فَاسْتَكْبَرُوا فِي الْاَرْضِ وَمَا كَانُوا سَابِق۪ينَۚ', 'Ve karune ve fir\'avne ve hamane ve lekad caehum musa bil beyyinati festekberu fil ardı ve ma kanu sabikin.', 'Karun,  Firavun ve Haman\'a; Musa kanıt içeren,  açıklayıcı bilgiyle geldi. Ne var ki onlar yeryüzünde büyüklük tasladılar. Onlar kurtulanlardan olmadılar.[1]', 'وقرون وفرعون وهمن ولقد جاهم موسي بالبينت فاستكبروا في الارض وما كانوا سبقين'),
(3380, 29, 40, 'فَكُلاًّ اَخَذْنَا بِذَنْبِه۪ۚ فَمِنْهُمْ مَنْ اَرْسَلْنَا عَـلَيْهِ حَـاصِباًۚ وَمِنْهُمْ مَنْ اَخَذَتْهُ الصَّيْحَةُۚ وَمِنْهُمْ مَنْ خَسَفْنَا بِهِ الْاَرْضَۚ وَمِنْهُمْ مَنْ اَغْرَقْنَاۚ وَمَا كَانَ اللّٰهُ لِيَظْلِمَهُمْ وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَ', 'Fe kullen ehazna bi zenbih, fe minhum men erselna aleyhi hasıba, ve minhum men ehazethussayhah, ve minhum men hasefnabihil ard, ve minhum men agrakna, ve ma kanallahu li yazlimehum ve lakin kanu enfusehum yazlimun.', 'Bunun üzerine suçları nedeniyle hepsini cezalandırdık. Bir kısmının üzerine taşlar savuran rüzgarlar gönderdik. Kimisini de korkunç bir ses yakaladı. Kimisini de yerin dibine geçirdik. Kimisini de boğduk. Böyle yapmakla,  Allah onlara haksızlık yapmadı. Fakat onlar kendi kendilerine haksızlık yaptılar.', 'فكلا اخذنا بذنبه فمنهم من ارسلنا عليه حاصبا ومنهم من اخذته الصيحة ومنهم من خسفنا به الارض ومنهم من اغرقنا وما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون'),
(3381, 29, 41, 'مَثَلُ الَّذ۪ينَ اتَّخَذُوا مِنْ دُونِ اللّٰهِ اَوْلِيَٓاءَ كَمَثَلِ الْعَنْكَبُوتِۚ اِتَّخَذَتْ بَيْتاًۜ وَاِنَّ اَوْهَنَ الْبُيُوتِ لَبَيْتُ الْعَنْكَبُوتِۢ لَوْ كَانُوا يَعْلَمُونَ', 'Meselullezinettehazu min dunillahi evliyae ke meselil ankebut, ittehazet beyta ve inne evhenel buyuti le beytul ankebut, lev kanu ya\'lemun.', 'Allah\'ın yanı sıra veliler[1] edinenlerin durumu,  kendisine dişi örümceğin evini ev edinenin durumu gibidir. Kuşkusuz evlerin en dayanıksızı dişi örümceğin evidir. Keşke bunu kavrayabilselerdi.', 'مثل الذين اتخذوا من دون الله اوليا كمثل العنكبوت اتخذت بيتا وان اوهن البيوت لبيت العنكبوت لو كانوا يعلمون'),
(3382, 29, 42, 'اِنَّ اللّٰهَ يَعْلَمُ مَا يَدْعُونَ مِنْ دُونِه۪ مِنْ شَيْءٍۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'İnnallahe ya\'lemu ma yed\'une min dunihi min şey\', ve huvel azizul hakim.', 'Kuşkusuz Allah,  onların Kendisinin yanı sıra yöneldikleri şeylerin ne olduğunu[1] bilir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ان الله يعلم ما يدعون من دونه من شي وهو العزيز الحكيم'),
(3383, 29, 43, 'وَتِلْكَ الْاَمْثَالُ نَضْرِبُهَا لِلنَّاسِۚ وَمَا يَعْقِلُـهَٓا اِلَّا الْعَالِمُونَ', 'Ve tilkel emsalu nadribuha lin nas ve ma ya\'kıluha illel alimun.', 'Bu örnekleri insanlara veriyoruz. Onu alimlerden[1] başkası kavrayamaz.', 'وتلك الامثل نضربها للناس وما يعقلها الا العلمون'),
(3384, 29, 44, 'خَلَقَ اللّٰهُ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِلْمُؤْمِن۪ينَ۟', 'Halakallahus semavati vel arda bil hakk, inne fi zalike le ayeten lil mu\'minin.', 'Allah,  gökleri ve yeri hakk ile yarattı. Bunda inananlar için kesinlikle bir ayet[1] vardır.', 'خلق الله السموت والارض بالحق ان في ذلك لاية للمومنين'),
(3385, 29, 45, 'اُتْلُ مَٓا اُو۫حِيَ اِلَيْكَ مِنَ الْكِتَابِ وَاَقِمِ الصَّلٰوةَۜ اِنَّ الصَّلٰوةَ تَنْهٰى عَنِ الْفَحْشَٓاءِ وَالْمُنْكَرِۜ وَلَذِكْرُ اللّٰهِ  اَكْبَرُۜ  وَاللّٰهُ  يَعْلَمُ  مَا  تَصْنَعُونَ', 'Utlu ma uhıye ileyke minel kitabi ve ekımıs salat, innes salate tenha anil fahşai vel munker, ve le zikrullahi ekber, vallahu ya\'lemu ma tasneun.', 'Kitap\'tan sana vahyolunan şeyi oku. Salatı ikame et.[1] Salat[2],  fahşadan[3] ve münkerden[4] alıkoyar. Kesinlikle Allah\'ın zikri[5] daha büyüktür. Allah,  yaptığınız[6] şeyleri bilir.', 'اتل ما اوحي اليك من الكتب واقم الصلوة ان الصلوة تنهي عن الفحشا والمنكر ولذكر الله اكبر والله يعلم ما تصنعون'),
(3386, 29, 46, 'وَلَا تُجَادِلُٓوا اَهْلَ الْكِتَابِ اِلَّا بِالَّت۪ي هِيَ اَحْسَنُۗ اِلَّا الَّذ۪ينَ ظَلَمُوا مِنْهُمْ وَقُولُٓوا اٰمَنَّا بِالَّـذ۪ٓي اُنْزِلَ اِلَيْنَا وَاُنْزِلَ اِلَيْكُمْ وَاِلٰهُنَا وَاِلٰهُكُمْ وَاحِدٌ وَنَحْنُ لَهُ مُسْلِمُونَ', 'Ve la tucadilu ehlel kitabi illa billeti hiye ahsenu illellezine zalemu minhum ve kulu amenna billezi unzile ileyna ve unzile ileykum ve ilahuna ve ilahukum vahıdun ve nahnu lehu muslimun.', 'Haksızlık edenleri hariç,  Kitap Ehli ile ancak en iyi şekilde mücadele edin. Ve deyin ki: \"Biz,  bize indirilene de size indirilene de inandık. Bizim ve sizin ilahınız birdir. Biz de O\'na teslim olanlarız.\"', 'ولا تجدلوا اهل الكتب الا بالتي هي احسن الا الذين ظلموا منهم وقولوا امنا بالذي انزل الينا وانزل اليكم والهنا والهكم وحد ونحن له مسلمون'),
(3387, 29, 47, 'وَكَذٰلِكَ اَنْزَلْـنَٓا اِلَيْكَ الْكِتَابَۜ فَالَّذ۪ينَ اٰتَيْنَاهُمُ الْكِتَابَ يُؤْمِنُونَ بِه۪ۚ وَمِنْ هٰٓؤُ۬لَٓاءِ مَنْ يُؤْمِنُ بِه۪ۜ وَمَا يَجْحَدُ بِاٰيَاتِنَٓا اِلَّا الْكَافِرُونَ', 'Ve kezalike enzelna ileykel kitab, fellezine ateyna humul kitabe yu\'minune bih, ve min haulai men yu\'minu bih, ve ma yechadu bi ayatina illel kafirun.', 'İşte böylece sana Kitap\'ı indirdik. Kendilerine Kitap ulaştırdıklarımız[1],  ona inanırlar. Şu kimselerden[2] de O\'na inanacaklar vardır. Kafirlerden başkası ayetlerimizi inkar etmez.', 'وكذلك انزلنا اليك الكتب فالذين اتينهم الكتب يومنون به ومن هولا من يومن به وما يجحد بايتنا الا الكفرون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3388, 29, 48, 'وَمَا كُنْتَ تَتْلُوا مِنْ قَبْلِه۪ مِنْ كِتَابٍ وَلَا تَخُطُّهُ بِيَم۪ينِكَ اِذاً لَارْتَابَ الْمُبْطِلُونَ', 'Ve ma kunte tetlu min kablihi min kitabin ve la tehuttuhu bi yeminike izen lertabel mubtılun.', 'Sen,  daha önce[1] herhangi bir kitaptan okuyor ve onu yazıyor değildin. Öyle olsaydı,  mesajını geçersiz yapmak isteyenler kesinlikle kuşkulanırlardı.[2]', 'وما كنت تتلوا من قبله من كتب ولا تخطه بيمينك اذا لارتاب المبطلون'),
(3389, 29, 49, 'بَلْ هُوَ اٰيَاتٌ بَيِّنَاتٌ ف۪ي صُدُورِ الَّذ۪ينَ اُو۫تُوا الْعِلْمَۜ وَمَا يَجْحَدُ بِاٰيَاتِنَٓا اِلَّا الظَّالِمُونَ', 'Bel huve ayatun beyyinatun fi sudurillezine utul ilm, ve ma yechadu bi ayatina illez zalimun.', 'Hayır! O,  kendilerine ilim[1] verilenlerin gönüllerinde yer eden apaçık ayetlerdir. Bizim ayetlerimizi zalimlerden başkası yalanlamaz.', 'بل هو ايت بينت في صدور الذين اوتوا العلم وما يجحد بايتنا الا الظلمون'),
(3390, 29, 50, 'وَقَالُوا لَوْلَٓا اُنْزِلَ عَلَيْهِ اٰيَاتٌ مِنْ رَبِّه۪ۜ قُلْ اِنَّمَا الْاٰيَاتُ عِنْدَ اللّٰهِۜ وَاِنَّـمَٓا اَنَا۬ نَذ۪يرٌ مُب۪ينٌ', 'Ve kalu lev la unzile aleyhi ayatun min rabbih, kul innemel ayatu indallah, ve innema ene nezirun mubin.', '\"Ona Rabb\'inden ayetler[1] indirilmeli değil miydi?\" dediler. De ki: \"Ayetler ancak Allah\'ın yanındadır. Ben ancak apaçık bir uyarıcıyım.\"[2]', 'وقالوا لولا انزل عليه ايت من ربه قل انما الايت عند الله وانما انا نذير مبين'),
(3391, 29, 51, 'اَوَلَمْ يَكْفِهِمْ اَنَّٓا اَنْزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلٰى عَلَيْهِمْۜ اِنَّ ف۪ي ذٰلِكَ لَرَحْمَةً وَذِكْرٰى لِقَوْمٍ يُؤْمِنُونَ۟', 'E ve lem yekfihim enna enzelna aleykel kitabe yutla aleyhim, inne fi zalike le rahmeten ve zikra li kavmin yu\'minun.', 'Kendilerine okunan Kitap\'ı sana indirmemiz onlara yetmedi mi? Kuşkusuz bunda[1] inanan bir toplum için bir rahmet[2] ve zikir[3] vardır.', 'اولم يكفهم انا انزلنا عليك الكتب يتلي عليهم ان في ذلك لرحمة وذكري لقوم يومنون'),
(3392, 29, 52, 'قُلْ كَفٰى بِاللّٰهِ بَيْن۪ي وَبَيْنَكُمْ شَه۪يداًۚ يَعْلَمُ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ وَالَّذ۪ينَ اٰمَنُوا بِالْبَاطِلِ وَكَفَرُوا بِاللّٰهِۙ اُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ', 'Kul kefa billahi beyni ve beynekum şehida, ya\'lemu ma fis semavati vel ard, vellezine amenu bil batılı ve keferu billahi ulaike humul hasirun.', 'De ki: \"Benimle sizin aranızda tanık olarak Allah yeter. O,  göklerde ve yerde olanları bilir.\" Batıla inananlar ve Allah\'ı yalanlayan kimseler,  işte onlar hüsranda olanlardır.', 'قل كفي بالله بيني وبينكم شهيدا يعلم ما في السموت والارض والذين امنوا بالبطل وكفروا بالله اوليك هم الخسرون'),
(3393, 29, 53, 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِۜ وَلَوْلَٓا اَجَلٌ مُسَمًّى لَجَٓاءَهُمُ الْعَذَابُۜ وَلَيَأْتِيَنَّهُمْ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'Ve yesta\'ciluneke bil azab, ve lev la ecelun musemmen le caehumul azab, ve le ye\'tiyennehum bagteten ve hum la yeş\'urun.', 'Senden azabı hemen getirmeni istiyorlar. Eğer belirlenmiş bir zaman olmasaydı,  azap onlara elbette gelmişti. Ve o,  hiç farkında olmadıkları bir sırada ansızın gelecek.', 'ويستعجلونك بالعذاب ولولا اجل مسمي لجاهم العذاب ولياتينهم بغتة وهم لا يشعرون'),
(3394, 29, 54, 'يَسْتَعْجِلُونَكَ بِالْعَذَابِۜ وَاِنَّ جَهَنَّمَ لَمُح۪يطَةٌ بِالْكَافِر۪ينَۙ', 'Yesta\'ciluneke bil azab, ve inne cehenneme le muhitatun bil kafirin.', 'Senden azabı hemen getirmeni istiyorlar. Oysaki Cehennem kesinlikle Kafirleri[1] çepeçevre kuşatacaktır.', 'يستعجلونك بالعذاب وان جهنم لمحيطة بالكفرين'),
(3395, 29, 55, 'يَوْمَ يَغْشٰيهُمُ الْعَذَابُ مِنْ فَوْقِهِمْ وَمِنْ تَحْتِ اَرْجُلِهِمْ وَيَقُولُ ذُوقُوا مَا كُنْتُمْ تَعْمَلُونَ', 'Yevme yagşahumul azabu min fevkıhim ve min tahti erculihim ve yekulu zuku ma kuntum ta\'melun.', 'O gün,  azap üstlerinden ve ayaklarının altından onları kuşatacak. Ve \"Yapmış olduğunuz şeylerin cezasını tadın!\" der.', 'يوم يغشيهم العذاب من فوقهم ومن تحت ارجلهم ويقول ذوقوا ما كنتم تعملون'),
(3396, 29, 56, 'يَا عِبَادِيَ الَّذ۪ينَ اٰمَنُٓوا اِنَّ اَرْض۪ي وَاسِعَةٌ فَاِيَّايَ فَاعْبُدُونِ', 'Ya ıbadıyellezine amenu inne ardi vasiatun fe iyyaye fa\'budun.', 'Ey inanan kullarım! Yeryüzüm geniştir.[1] Öyleyse yalnız Bana kulluk edin.', 'يعبادي الذين امنوا ان ارضي وسعة فايي فاعبدون'),
(3397, 29, 57, 'كُلُّ نَفْسٍ ذَٓائِقَةُ الْمَوْتِ ثُمَّ اِلَيْنَا تُرْجَعُونَ', 'Kullu nefsin zaikatul mevti summe ileyna turceun.', 'Her nefs[1] ölümü tadıcıdır. Sonra Bize döndürüleceksiniz.', 'كل نفس ذايقة الموت ثم الينا ترجعون'),
(3398, 29, 58, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُبَوِّئَنَّهُمْ مِنَ الْجَنَّةِ غُرَفاً تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ نِعْمَ اَجْرُ الْعَامِل۪ينَۗ', 'Vellezine amenu ve amilus salihati le nubevviennehum minel cenneti gurafan tecrimin tahtihel enharu halidine fiha, ni\'me ecrul amilin.', 'İnananları ve salihatı yapanları,  içinde sürekli kalacakları Cennet\'te; altından ırmaklar akan köşklere yerleştireceğiz. İyi işler yapanların ödülü ne güzeldir!', 'والذين امنوا وعملوا الصلحت لنبوينهم من الجنة غرفا تجري من تحتها الانهر خلدين فيها نعم اجر العملين'),
(3399, 29, 59, 'اَلَّذ۪ينَ صَبَرُوا وَعَلٰى رَبِّهِمْ يَتَوَكَّلُونَ', 'Ellezine saberu ve ala rabbihim yetevekkelun.', 'Onlar,  sabreden ve Rabb\'lerine tevekkül[1] edenlerdir.', 'الذين صبروا وعلي ربهم يتوكلون'),
(3400, 29, 60, 'وَكَاَيِّنْ مِنْ دَٓابَّةٍ لَا تَحْمِلُ رِزْقَهَاۗ اَللّٰهُ يَرْزُقُهَا وَاِيَّاكُمْۘ وَهُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve keeyyin min dabbetin la tahmilu rızkaha allahu yerzukuha ve iyyakum ve huves semiul alim.', 'Rızıklarını temin edemeyen[1] nice dabbe[2] vardır. Onlara da size de Allah rızık verir. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'وكاين من دابة لا تحمل رزقها الله يرزقها واياكم وهو السميع العليم'),
(3401, 29, 61, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ لَيَقُولُنَّ اللّٰهُۚ فَاَنّٰى يُؤْفَكُونَ', 'Ve le in seeltehum men halakas semavati vel arda ve sehhareş şemse vel kamere le yekulunnallah, fe enna yu\'fekun.', 'Gerçek şu ki,  onlara: \"Gökleri ve yeri kim yarattı,  Güneş\'i ve Ay\'ı yararınıza sunan kimdir?\" diye sorsan,  kesinlikle \"Allah.\" diyecekler. O halde nasıl başka varlıklara yöneliyorlar!', 'ولين سالتهم من خلق السموت والارض وسخر الشمس والقمر ليقولن الله فاني يوفكون'),
(3402, 29, 62, 'اَللّٰهُ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ مِنْ عِبَادِه۪ وَيَقْدِرُ لَهُۜ اِنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Allahu yebsutur rızka li men yeşau min ibadihi ve yakdiru leh, innallahe bi kulli şey\'in alim.', 'Allah,  kullarından dilediğine rızkı genişletir ve onun için takdir eder. Kuşkusuz Allah,  Her Şeyi En İyi Bilen\'dir.', 'الله يبسط الرزق لمن يشا من عباده ويقدر له ان الله بكل شي عليم'),
(3403, 29, 63, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ نَزَّلَ مِنَ السَّمَٓاءِ مَٓاءً فَاَحْيَا بِهِ الْاَرْضَ مِنْ بَعْدِ مَوْتِهَا لَيَقُولُنَّ اللّٰهُۜ  قُلِ الْحَمْدُ لِلّٰهِۜ بَلْ اَكْثَرُهُمْ لَا يَعْقِلُونَ۟', 'Ve le in seeltehum men nezzele mines semai maen fe ahya bihil arda min ba\'di mevtiha le yekulunnallah, kulil hamdu lillah, bel ekseruhum la ya\'kılun.', 'Eğer onlara: \"Gökten su indirip de onunla yeryüzünü ölümünden sonra dirilten kimdir?\" diye sorsan,  kesinlikle \"Allah\" diyecekler. De ki: \"Hamd[1] Allah\'a özgüdür.\" Fakat onların çoğu akıllarını kullanmıyorlar.', 'ولين سالتهم من نزل من السما ما فاحيا به الارض من بعد موتها ليقولن الله قل الحمد لله بل اكثرهم لا يعقلون'),
(3404, 29, 64, 'وَمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَٓا اِلَّا لَهْوٌ وَلَعِبٌۜ وَاِنَّ الدَّارَ الْاٰخِرَةَ لَهِيَ الْحَيَوَانُۢ لَوْ كَانُوا يَعْلَمُونَ', 'Ve ma hazihil hayatud dunya illa lehvun ve laib, ve inned darel ahırete le hiyel hayevan, lev kanu ya\'lemun.', 'Bu dünya hayatı bir oyun ve eğlenceden başka bir şey değildir. Ahiret yurdu,  gerçek hayattır. Keşke,  bunun farkında olsalardı!', 'وما هذه الحيوة الدنيا الا لهو ولعب وان الدار الاخرة لهي الحيوان لو كانوا يعلمون'),
(3405, 29, 65, 'فَاِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللّٰهَ مُخْلِص۪ينَ لَهُ الدّ۪ينَۚ فَلَمَّا نَجّٰيهُمْ اِلَى الْبَرِّ اِذَا هُمْ يُشْرِكُونَۙ', 'Fe iza rakibu fil fulki deavullahe muhlisine lehud din, fe lemma neccahum ilel berri iza hum yuşrikun.', 'Gemiye bindikleri zaman[1],  dini yalnız Allah\'a özgü kılarak O\'na dua ederler. Fakat onları karaya çıkarıp kurtardığımız zaman,  hemen şirk koşarlar.', 'فاذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجيهم الي البر اذا هم يشركون'),
(3406, 29, 66, 'لِيَكْفُرُوا بِمَٓا اٰتَيْنَاهُمْۙ وَلِيَتَمَتَّعُوا۠ فَسَوْفَ يَعْلَمُونَ', 'Li yekfuru bima ateynahum ve li yetemettau, fe sevfe ya\'lemun.', 'Onlar,  kendilerine verdiğimiz nimetlere nankörlük etsinler ve gönüllerince yaşasınlar! Yakında neyin ne olduğunu görecekler!', 'ليكفروا بما اتينهم وليتمتعوا فسوف يعلمون'),
(3407, 29, 67, 'اَوَلَمْ يَرَوْا اَنَّا جَعَلْنَا حَرَماً اٰمِناً وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْۜ اَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ اللّٰهِ يَكْفُرُونَ', 'E ve lem yerev enna cealna haramen aminen ve yutehattafun nasu min havlihim, e fe bil batılı yu\'minune ve bi ni\'metillahi yekfurun.', 'Çevresindeki insanlar can güvenliği içinde değilken,  orayı[1] güvenli harem[2] ve emin bir yer kıldığımızı görmediler mi? Hala batıla mı inanıyorlar ve Allah\'ın nimetine nankörlük mü ediyorlar?', 'اولم يروا انا جعلنا حرما امنا ويتخطف الناس من حولهم افبالبطل يومنون وبنعمة الله يكفرون'),
(3408, 29, 68, 'وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ كَذِباً اَوْ كَذَّبَ بِالْحَقِّ لَمَّا جَٓاءَهُۜ اَلَيْسَ ف۪ي جَهَنَّمَ مَثْوًى لِلْكَافِر۪ينَ', 'Ve men azlemu mimmeniftera alallahi keziben ev kezzebe bil hakkı lemma caeh, e leyse fi cehenneme mesven lil kafirin.', 'Uydurduğu yalanı Allah\'a isnat eden iftiracıdan veya kendisine gelen hakikati yalanlayandan daha zalim kim vardır? Kafirler için Cehennem\'de yer mi yok?', 'ومن اظلم ممن افتري علي الله كذبا او كذب بالحق لما جاه اليس في جهنم مثوي للكفرين'),
(3409, 29, 69, 'وَالَّذ۪ينَ جَاهَدُوا ف۪ينَا لَنَهْدِيَنَّهُمْ سُبُلَنَاۜ وَاِنَّ اللّٰهَ لَمَعَ الْمُحْسِن۪ينَ', 'Vellezine cahedu fina le nehdiyennehum subulena ve innallahe le meal muhsinin.', 'Biz,  Bizim yolumuzda cihad edenleri[1] elbette yollarımıza iletiriz. Kuşkusuz Allah,  muhsinlerle[2] beraberdir.', 'والذين جهدوا فينا لنهدينهم سبلنا وان الله لمع المحسنين'),
(3410, 30, 1, 'الٓمٓ۠', 'Elif lam mim.', 'Elif. Lam. Mim.', 'الم'),
(3411, 30, 2, 'غُلِبَتِ الرُّومُۙ', 'Gulibetir rum.', 'Rum\'a galip gelindi.', 'غلبت الروم'),
(3412, 30, 3, 'ف۪ٓي اَدْنَى الْاَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَۙ', 'Fi ednel ardı ve hum min ba\'di galebihim se yaglibun.', 'En yakın bir yerde. Bu yenilgilerinden sonra pek yakında galip geleceklerdir.[1]', 'في ادني الارض وهم من بعد غلبهم سيغلبون'),
(3413, 30, 4, 'ف۪ي بِضْعِ سِن۪ينَۜ لِلّٰهِ الْاَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُۜ وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَۙ', 'Fi bıd\'ı sinin, lillahil emru min kablu ve min ba\'d, ve yevme izin yefrahul mu\'minun.', 'Birkaç yıl içinde[1]. Önce de sonra da her buyruk Allah\'ındır. Ve İzin Günü inananlar sevineceklerdir.', 'في بضع سنين لله الامر من قبل ومن بعد ويوميذ يفرح المومنون'),
(3414, 30, 5, 'بِنَصْرِ اللّٰهِۜ يَنْصُرُ مَنْ يَشَٓاءُۜ وَهُوَ الْعَز۪يزُ الرَّح۪يمُ', 'Bi nasrillah, yansuru men yeşa\', ve huvel azizur rahim.', 'Hak eden kimseye[1] yardım eden Allah\'ın yardımıyla. O,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'بنصر الله ينصر من يشا وهو العزيز الرحيم'),
(3415, 30, 6, 'وَعْدَ اللّٰهِۜ لَا يُخْلِفُ اللّٰهُ وَعْدَهُ وَلٰكِنَّ اَكْثَرَ  النَّاسِ لَا يَعْلَمُونَ', 'Va\'dallah, la yuhlifullahu va\'dehu ve lakinne ekseren nasi la ya\'lemun.', 'Bu,  Allah\'ın sözüdür. Allah verdiği sözden dönmez. Fakat insanların çoğu bunun bilincinde değildirler.', 'وعد الله لا يخلف الله وعده ولكن اكثر الناس لا يعلمون'),
(3416, 30, 7, 'يَعْلَمُونَ ظَاهِراً مِنَ الْحَيٰوةِ الدُّنْيَاۚ وَهُمْ عَنِ الْاٰخِرَةِ هُمْ غَافِلُونَ', 'Ya\'lemune zahiren minel hayatid dunya, ve hum anil ahıreti hum gafilun.', 'Onlar,  dünya hayatının görünen yüzünü bilirler. Onlar,  ahiret hayatının bilincinde değildirler.', 'يعلمون ظهرا من الحيوة الدنيا وهم عن الاخرة هم غفلون'),
(3417, 30, 8, 'اَوَلَمْ يَتَفَكَّرُوا ف۪ٓي اَنْفُسِهِمْ۠ مَا خَلَقَ اللّٰهُ السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَٓا اِلَّا بِالْحَقِّ وَاَجَلٍ مُسَمًّىۜ وَاِنَّ كَث۪يراً مِنَ النَّاسِ بِلِقَٓائِ۬ رَبِّهِمْ لَكَافِرُونَ', 'E ve lem yetefekkeru fi enfusihim, ma halakallahus semavati vel arda ve ma beynehuma illa bil hakkı ve ecelin musemma ve inne kesiran minen nasi bi likai rabbihim le kafirun.', 'Onlar,  muhasebe yapıp hiç düşünmüyorlar mı? Allah; gökleri,  yeri ve bu ikisinin arasındaki şeyleri ancak hakk ile ve belli bir süre için yarattı. İnsanların çoğu Rabb\'lerinin huzuruna çıkacaklarını küfrediyorlar.[1]', 'اولم يتفكروا في انفسهم ما خلق الله السموت والارض وما بينهما الا بالحق واجل مسمي وان كثيرا من الناس بلقاي ربهم لكفرون'),
(3418, 30, 9, 'اَوَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ كَانُٓوا اَشَدَّ مِنْهُمْ قُوَّةً وَاَثَارُوا الْاَرْضَ وَعَمَرُوهَٓا اَكْثَرَ مِمَّا عَمَرُوهَا وَجَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِۜ فَمَا كَانَ اللّٰهُ لِيَظْلِمَهُمْ وَلٰكِنْ كَانُٓوا اَنْفُسَهُمْ يَظْلِمُونَۜ', 'E ve lem yesiru fil ardı fe yenzuru keyfe kane akıbetullezine min kablihim, kanu eşedde minhum kuvveten, ve esarul arda ve ameruha eksera mimma ameruha ve caethum rusuluhum bil beyyinat, fe ma kanallahu li yazlimehum ve lakin kanu enfusehum yazlimun.', 'Yeryüzünde dolaşıp,  kendilerinden öncekilerinin sonları nasıl olmuş,  bir bakmadılar mı? Onlar,  kendilerinden daha güçlüydüler; yeryüzünü alt üst etmişlerdi; onu,  kendilerinin imar ettiklerinden daha çok imar etmişlerdi. Resulleri,  onlara nice açık belgelerle gelmişti. Allah onlara haksızlık yapmamış,  onlar kendi kendilerine haksızlık yapmışlardı.', 'اولم يسيروا في الارض فينظروا كيف كان عقبة الذين من قبلهم كانوا اشد منهم قوة واثاروا الارض وعمروها اكثر مما عمروها وجاتهم رسلهم بالبينت فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون'),
(3419, 30, 10, 'ثُمَّ  كَانَ عَاقِبَةَ الَّذ۪ينَ اَسَٓاؤُا السُّٓوآٰى اَنْ كَذَّبُوا بِاٰيَاتِ اللّٰهِ وَكَانُوا بِهَا يَسْتَهْزِؤُ۫نَ۟', 'Summe kane akıbetellezine esaus sua en kezzebu bi ayatillahi ve kanu biha yestehziun.', 'Sonra,  Allah\'ın ayetlerini yalanlayıp,  alaya alarak kötülük yapanların sonları çok kötü oldu.', 'ثم كان عقبة الذين اسوا السواي ان كذبوا بايت الله وكانوا بها يستهزون'),
(3420, 30, 11, 'اَللّٰهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُ ثُمَّ اِلَيْهِ تُرْجَعُونَ', 'Allahu yebdeul halka summe yuiduhu summe ileyhi turceun.', 'Allah,  önce yaratmaya başlar,  sonra onu iade[1] eder. Sonra da O\'na döndürülürsünüz.', 'الله يبدوا الخلق ثم يعيده ثم اليه ترجعون'),
(3421, 30, 12, 'وَيَوْمَ تَقُومُ السَّاعَةُ يُبْلِسُ الْمُجْرِمُونَ', 'Ve yevme tekumus saatu yublisul mucrimun.', 'Sa\'atin gerçekleştiği gün[1],  mücrimler[2] umutlarını kaybederler.', 'ويوم تقوم الساعة يبلس المجرمون'),
(3422, 30, 13, 'وَلَمْ يَكُنْ لَهُمْ مِنْ شُرَكَٓائِهِمْ شُفَعٰٓؤُ۬ا وَكَانُوا بِشُرَكَٓائِهِمْ كَافِر۪ينَ', 'Ve lem yekun lehum min şurekaihim şufeau ve kanu bi şurekaihim kafirin.', 'Ortak koştukları da onlara şefaatçi[1] olmayacaktır. Ortaklarını da yok sayacaklar.', 'ولم يكن لهم من شركايهم شفعوا وكانوا بشركايهم كفرين'),
(3423, 30, 14, 'وَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', 'Ve yevme tekumus saatu yevmeizin yeteferrakun.', 'Sa\'at\'in gerçekleştiği gün[1]; İzin Günü[2],  onlar[3] birbirinden ayrılırlar.', 'ويوم تقوم الساعة يوميذ يتفرقون'),
(3424, 30, 15, 'فَاَمَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَهُمْ ف۪ي رَوْضَةٍ يُحْبَرُونَ', 'Fe emmellezine amenu ve amilus salihati fe hum fi ravdatin yuhberun.', 'Fakat inananlar ve salihatı yapanlar, [1] onlar güzel bir bahçede mutluluk içinde yaşayacaklardır.', 'فاما الذين امنوا وعملوا الصلحت فهم في روضة يحبرون'),
(3425, 30, 16, 'وَاَمَّا الَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَا وَلِقَٓائِ الْاٰخِرَةِ فَاُو۬لٰٓئِكَ فِي الْعَذَابِ مُحْضَرُونَ', 'Ve emmellezine keferu ve kezzebu bi ayatina ve likail ahıreti fe ulaike fil azabi muhdarun.', 'Kafir olup ayetlerimizi ve ahiret kavuşmasını yalanlayan kimselere gelince; onlar,  azap içinde hazır bulundurulurlar.', 'واما الذين كفروا وكذبوا بايتنا ولقاي الاخرة فاوليك في العذاب محضرون'),
(3426, 30, 17, 'فَسُبْحَانَ اللّٰهِ ح۪ينَ تُمْسُونَ وَح۪ينَ تُصْبِحُونَ', 'Fe subhanallahi hine tumsune ve hine tusbıhun.', 'O halde akşama kavuştuğunuz zaman ve sabaha kavuştuğunuz zaman[1] tesbih[2] Allah\'ındır.[3]', 'فسبحن الله حين تمسون وحين تصبحون'),
(3427, 30, 18, 'وَلَهُ الْحَمْدُ فِي السَّمٰوَاتِ وَالْاَرْضِ وَعَشِياًّ وَح۪ينَ تُظْهِرُونَ', 'Ve lehul hamdu fis semavati vel ardı ve aşiyyen ve hine tuzhırun.', 'Karanlık ve aydınlık zamanlarda,  göklerde ve yerde hamd[1],  O\'na aittir.', 'وله الحمد في السموت والارض وعشيا وحين تظهرون'),
(3428, 30, 19, 'يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَيُحْـيِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ وَكَذٰلِكَ تُخْرَجُونَ۟', 'Yuhricul hayye minel meyyiti ve yuhricul meyyite minel hayyi ve yuhyil arda ba\'de mevtiha, ve kezalike tuhrecun.', 'O,  ölüden diriyi,  diriden de ölüyü çıkarır. Ve ölmüş yeryüzüne hayat verir. İşte,  tıpkı bunun gibi siz de diriltileceksiniz.', 'يخرج الحي من الميت ويخرج الميت من الحي ويحي الارض بعد موتها وكذلك تخرجون'),
(3429, 30, 20, 'وَمِنْ اٰيَاتِه۪ٓ اَنْ خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ اِذَٓا اَنْتُمْ بَشَرٌ تَنْتَشِرُونَ', 'Ve min ayatihi en halakakum min turabin summe iza entum beşerun tenteşirun.', 'Sizi topraktan yaratması,  O\'nun ayetlerindendir.[1] Ardından da yeryüzüne dağılan bir beşer[2] oldunuz.', 'ومن ايته ان خلقكم من تراب ثم اذا انتم بشر تنتشرون'),
(3430, 30, 21, 'وَمِنْ اٰيَاتِه۪ٓ اَنْ خَلَقَ لَكُمْ مِنْ اَنْفُسِكُمْ اَزْوَاجاً لِتَسْكُـنُٓوا اِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةًۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ', 'Ve min ayatihi en halaka lekum min enfusikum ezvacen li teskunu ileyha ve ceale beynekum meveddeten ve rahmeh, inne fi zalike le ayatin li kavmin yetefekkerun.', 'O\'nun ayetlerinden[1] biri de,  sizin için kendi cinsinizden eşler yaratmasıdır. Siz,  onunla dinginleşir huzur bulursunuz. Birbirinize karşı,  aranızda sevgi ve rahmet oluşturdu. Düşünen bir toplum için bunda nice ayetler[1] vardır.', 'ومن ايته ان خلق لكم من انفسكم ازوجا لتسكنوا اليها وجعل بينكم مودة ورحمة ان في ذلك لايت لقوم يتفكرون'),
(3431, 30, 22, 'وَمِنْ اٰيَاتِه۪ خَلْقُ السَّمٰوَاتِ وَالْاَرْضِ وَاخْتِلَافُ اَلْسِنَتِكُمْ وَاَلْوَانِكُمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِلْعَالِم۪ينَ', 'Ve min ayatihi halkus semavati vel ardı vahtilafu elsinetikum ve elvanikum, inne fi zalike le ayatin lil alimin.', 'Göklerin ve yerin yaratılışı,  dillerinizin ve renklerinizin farklı oluşu O\'nun ayetlerindendir[1]. Bunda bilenler[2] için ayetler[3] vardır.', 'ومن ايته خلق السموت والارض واختلف السنتكم والونكم ان في ذلك لايت للعلمين'),
(3432, 30, 23, 'وَمِنْ اٰيَاتِه۪ مَنَامُكُمْ بِالَّيْلِ وَالنَّهَارِ وَابْتِغَٓاؤُ۬كُمْ مِنْ فَضْلِه۪ۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَسْمَعُونَ', 'Ve min ayatihi menamukum bil leyli ven nehari vebtigaukum min fadlih, inne fi zalike le ayatin li kavmin yesmeun.', 'Yine gece uyumanız,  gündüz O\'nun fazlından[1] rızık aramanız O\'nun ayetlerindendir[2]. Bunda,  anlayan bir halk için ayetler vardır.', 'ومن ايته منامكم باليل والنهار وابتغاوكم من فضله ان في ذلك لايت لقوم يسمعون'),
(3433, 30, 24, 'وَمِنْ اٰيَاتِه۪ يُر۪يكُمُ الْبَرْقَ خَوْفاً وَطَمَعاً وَيُنَزِّلُ مِنَ السَّمَٓاءِ مَٓاءً فَيُحْـي۪ بِهِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَعْقِلُونَ', 'Ve min ayatihi yurikumul berka havfen ve tamaan, ve yunezzilu mines semai maen fe yuhyi bihil arda ba\'de mevtiha, inne fi zalike le ayatin li kavmin ya\'kılun.', 'Size,  bir yandan korku veren bir yandan da yağmurun belirtisi olarak umut veren şimşeği göstermesi ve gökten su indirerek,  ölmüş yeryüzüne hayat vermesi O\'nun ayetlerindendir.[1] Bunda aklını kullanan bir kavim için kesinlikle ayetler vardır.', 'ومن ايته يريكم البرق خوفا وطمعا وينزل من السما ما فيحي به الارض بعد موتها ان في ذلك لايت لقوم يعقلون'),
(3434, 30, 25, 'وَمِنْ اٰيَاتِه۪ٓ اَنْ تَقُومَ السَّمَٓاءُ وَالْاَرْضُ بِاَمْرِه۪ۜ ثُمَّ اِذَا دَعَاكُمْ دَعْوَةً مِنَ الْاَرْضِ اِذَٓا اَنْتُمْ تَخْرُجُونَ', 'Ve min ayatihi en tekumes semau vel ardu bi emrih, summe iza deakum da\'veten minel ardı iza entum tahrucun.', 'Göklerin ve yerin,  buyruğu ile durması[1],  O\'nun ayetlerindendir.[2] Sonra bir tek çağırışla çağırdığı zaman yerden derhal çıkacaksınız.[3]', 'ومن ايته ان تقوم السما والارض بامره ثم اذا دعاكم دعوة من الارض اذا انتم تخرجون'),
(3435, 30, 26, 'وَلَهُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِۜ كُلٌّ لَهُ قَانِتُونَ', 'Ve lehu men fis semavati vel ard, kullun lehu kanitun.', 'Göklerde ve yerde olanların tamamı O\'nundur. Hepsi O\'nun yasalarına bağlıdır.', 'وله من في السموت والارض كل له قنتون'),
(3436, 30, 27, 'وَهُوَ الَّذ۪ي يَبْدَؤُا الْخَلْقَ ثُمَّ يُع۪يدُهُ وَهُوَ اَهْوَنُ عَلَيْهِۜ وَلَهُ الْمَثَلُ الْاَعْلٰى فِي السَّمٰوَاتِ وَالْاَرْضِۚ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ۟', 'Ve huvellezi yebdeul halka summe yuiduhu, ve huve ehvenu aleyh, ve lehul meselul a\'la fis semavati vel ard, ve huvel azizul hakim.', 'Yaratmayı ilk kez başlatan,  sonra onu tekrar eden[1] O\'dur. Bu,  O\'nun için çok kolaydır. Göklerde ve yerde en yüce nitelikler O\'nundur. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'وهو الذي يبدوا الخلق ثم يعيده وهو اهون عليه وله المثل الاعلي في السموت والارض وهو العزيز الحكيم'),
(3437, 30, 28, 'ضَرَبَ لَكُمْ مَثَلاً مِنْ اَنْفُسِكُمْۜ هَلْ لَكُمْ مِنْ مَا مَلَكَتْ اَيْمَانُكُمْ مِنْ شُرَكَٓاءَ ف۪ي مَا رَزَقْنَاكُمْ فَاَنْتُمْ ف۪يهِ سَوَٓاءٌ تَخَافُونَهُمْ كَخ۪يفَتِكُمْ اَنْفُسَكُمْۜ كَذٰلِكَ نُفَصِّلُ الْاٰيَاتِ لِقَوْمٍ يَعْقِلُونَ', ': Darabe lekum meselen min enfusikum, hel lekum min ma meleket eymanukum min şurekae fi ma rezaknakum fe entum fihi sevaun tehafunehum ke hifetikum enfusekum, kezalike nufassılul ayati li kavmin ya\'kılun.', 'Kendinizden,  size bir örnek vermektedir: \"Size verdiğimiz mallarda yeminle hak sahibi olduğunuz[1] kimselerden ortaklarınız var mı? Siz ve onlar bu mallarda eşit misiniz? Onları,  birbirinizi saydığınız gibi sayar mısınız? Aklını kullanan bir kavim için ayetleri işte böyle açıklıyoruz.\"[2]', 'ضرب لكم مثلا من انفسكم هل لكم من ما ملكت ايمنكم من شركا في ما رزقنكم فانتم فيه سوا تخافونهم كخيفتكم انفسكم كذلك نفصل الايت لقوم يعقلون'),
(3438, 30, 29, 'بَلِ اتَّبَعَ الَّذ۪ينَ ظَلَمُٓوا اَهْوَٓاءَهُمْ بِغَيْرِ عِلْمٍۚ فَمَنْ يَهْد۪ي مَنْ اَضَلَّ اللّٰهُۜ وَمَا لَهُمْ مِنْ نَاصِر۪ينَ', 'Belittebeallezine zalemu ehvaehum bi gayri ilm, fe men yehdi men edallallah, ve ma lehum min nasırin.', 'Hayır,  zalimler körü körüne hevalarına[1] uydular. Bundan sonra[2] Allah\'ın şaşırttığını kim doğru yola iletebilir? Ve onların yardımcıları da yoktur.', 'بل اتبع الذين ظلموا اهواهم بغير علم فمن يهدي من اضل الله وما لهم من نصرين'),
(3439, 30, 30, 'فَاَقِمْ وَجْهَكَ لِلدّ۪ينِ حَن۪يفاًۜ فِطْرَتَ اللّٰهِ الَّت۪ي فَطَرَ النَّاسَ عَلَيْهَاۜ لَا تَبْد۪يلَ لِخَلْقِ اللّٰهِۜ ذٰلِكَ الدّ۪ينُ الْقَيِّمُۗ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَۗ', 'Fe ekim vecheke lid dini hanifa, fıtratallahilleti fataran nase aleyha, la tebdile li halkıllah, zaliked dinul kayyimu ve lakinne ekseren nasi la ya\'lemun.', 'O halde hanif[1] olarak dine yüzünü[2] ikame et[3]. İnsanları,  üzerinde yaratmış olduğu Allah\'ın fıtratına.[4] Allah\'ın yaratmasında değişme olmaz. Kayyum[5] olan din budur. Fakat insanların çoğu bilmiyorlar.', 'فاقم وجهك للدين حنيفا فطرت الله التي فطر الناس عليها لا تبديل لخلق الله ذلك الدين القيم ولكن اكثر الناس لا يعلمون'),
(3440, 30, 31, 'مُن۪يب۪ينَ اِلَيْهِ وَاتَّقُوهُ وَاَق۪يمُوا الصَّلٰوةَ وَلَا تَكُونُوا مِنَ الْمُشْرِك۪ينَۙ', 'Munibine ileyhi vettekuhu ve ekimus salate ve la tekunu minel muşrikin.', 'O\'na yönelin. O\'na karşı takva[1] sahibi olun. Salatı ikame edin[2]. Müşriklerden olmayın.', 'منيبين اليه واتقوه واقيموا الصلوة ولا تكونوا من المشركين'),
(3441, 30, 32, 'مِنَ الَّذ۪ينَ فَرَّقُوا د۪ينَهُمْ وَكَانُوا شِيَعاًۜ كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ', 'Minellezine ferraku dinehum ve kanu şiyea, kullu hızbin bima ledeyhim ferihun.', 'Dinlerini parçalara bölen[1],  gruplara ayrılan ve her grubun kendi yanındakiyle böbürlendiği kimselerden olmayın.', 'من الذين فرقوا دينهم وكانوا شيعا كل حزب بما لديهم فرحون'),
(3442, 30, 33, 'وَاِذَا مَسَّ النَّاسَ ضُرٌّ دَعَوْا رَبَّهُمْ مُن۪يب۪ينَ اِلَيْهِ ثُمَّ اِذَٓا اَذَاقَهُمْ مِنْهُ رَحْمَةً اِذَا فَر۪يقٌ مِنْهُمْ بِرَبِّهِمْ يُشْرِكُونَۙ', 'Ve iza messen nase durrun deav rabbehum munibine ileyhi summe iza ezakahum minhu rahmeten iza ferikun minhum bi rabbihim yuşrikun.', 'İnsanların başlarına bir sıkıntı gelince,  Rabb\'lerine yönelerek O\'na dua ederler. Sonra,  onlara kendinden bir rahmet tattırınca,  onlardan bir kısmı Rabb\'lerine şirk[1] koşarlar.', 'واذا مس الناس ضر دعوا ربهم منيبين اليه ثم اذا اذاقهم منه رحمة اذا فريق منهم بربهم يشركون'),
(3443, 30, 34, 'لِيَكْفُرُوا بِمَٓا اٰتَيْنَاهُمْۜ فَتَمَتَّعُوا۠ فَسَوْفَ تَعْلَمُونَ', 'Li yekfuru bima ateynahum, fe temetteu fe sevfe ta\'lemun.', 'Kendilerine verdiğimiz şeylere nankörlük ederler. İstediğiniz gibi yaşayın bakalım! İleride gerçeği göreceksiniz.', 'ليكفروا بما اتينهم فتمتعوا فسوف تعلمون'),
(3444, 30, 35, 'اَمْ اَنْزَلْنَا عَلَيْهِمْ سُلْطَاناً فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا بِه۪ يُشْرِكُونَ', 'Em enzelna aleyhim sultanen fe huve yetekellemu bima kanu bihi yuşrikun.', 'Yoksa onlara bir sultan[1] gönderdik de o,  onlara şirk koşmalarını mı söylüyor?', 'ام انزلنا عليهم سلطنا فهو يتكلم بما كانوا به يشركون'),
(3445, 30, 36, 'وَاِذَٓا اَذَقْنَا النَّاسَ رَحْمَةً فَرِحُوا بِهَاۜ وَاِنْ تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ اَيْد۪يهِمْ اِذَا هُمْ يَقْنَطُونَ', 'Ve iza ezaknen nase rahmeten ferihu biha, ve in tusıbhum seyyietun bima kaddemet eydihim iza hum yaknetun.', 'İnsanlara bir rahmet tattırdığımız zaman,  onunla şımarırlar. Kendi yaptıklarından dolayı başlarına bir kötülük gelirse,  o zaman hemen umutsuzluğa kapılırlar.', 'واذا اذقنا الناس رحمة فرحوا بها وان تصبهم سيية بما قدمت ايديهم اذا هم يقنطون'),
(3446, 30, 37, 'اَوَلَمْ يَرَوْا اَنَّ اللّٰهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ', 'EE ve lem yerev ennellahe yebsutur rızka li men yeşau ve yakdir, inne fi zalike le ayatin li kavmin yu\'minun.', 'Allah\'ın dilediği kimse için rızkı genişlettiğini ve ölçülendirdiğini bilmediler mi? Bunda inanan bir halk için ayetler[1] vardır.', 'اولم يروا ان الله يبسط الرزق لمن يشا ويقدر ان في ذلك لايت لقوم يومنون'),
(3447, 30, 38, 'فَاٰتِ ذَا الْقُرْبٰى حَقَّهُ وَالْمِسْك۪ينَ وَابْنَ السَّب۪يلِۜ ذٰلِكَ خَيْرٌ لِلَّذ۪ينَ يُر۪يدُونَ وَجْهَ اللّٰهِۘ وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Fe ati zel kurba hakkahu vel miskine vebnes sebil, zalike hayrun lillezine yuridune vechallahi ve ulaike humul muflihun.', 'Öyleyse; yakınlara,  miskine[1] ve yol oğluna[2] hakkını ver. Bu,  Allah\'ın yüzünü[3] dileyenler için daha hayırlıdır. İşte onlar kurtuluşa erenlerdir.', 'فات ذا القربي حقه والمسكين وابن السبيل ذلك خير للذين يريدون وجه الله واوليك هم المفلحون'),
(3448, 30, 39, 'وَمَٓا اٰتَيْتُمْ مِنْ رِباً لِيَرْبُوَ۬ا ف۪ٓي اَمْوَالِ النَّاسِ فَلَا يَرْبُوا عِنْدَ اللّٰهِۚ وَمَٓا اٰتَيْتُمْ مِنْ زَكٰوةٍ تُر۪يدُونَ وَجْهَ اللّٰهِ فَاُو۬لٰٓئِكَ هُمُ الْمُضْعِفُونَ', 'Ve ma ateytum min riben li yerbuve fi emvalin nasi fe la yerbu indallah, ve ma ateytum min zekatin turidune vechallahi fe ulaike humul mud\'ıfun.', 'İnsanların mallarında artsın diye ribadan verdiğiniz,  Allah\'ın katında artmaz. Allah\'ın yüzünü[1] dileyerek zekattan[2] verenler,  işte bunu yapanlar kat kat arttıranlardır.', 'وما اتيتم من ربا ليربوا في امول الناس فلا يربوا عند الله وما اتيتم من زكوة تريدون وجه الله فاوليك هم المضعفون'),
(3449, 30, 40, 'اَللّٰهُ الَّذ۪ي خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُم۪يتُكُمْ ثُمَّ يُحْي۪يكُمْۜ هَلْ مِنْ شُرَكَٓائِكُمْ مَنْ يَفْعَلُ مِنْ ذٰلِكُمْ مِنْ شَيْءٍۜ سُبْحَانَهُ وَتَعَالٰى عَمَّا يُشْرِكُونَ۟', 'Allahullezi halakakum summe rezekakum summe yumitukum summe yuhyikum, hel min şurekaikum men yef\'alu min zalikum min şey\', subhanehu ve teala amma yuşrikun.', 'O Allah ki,  sizi yaratan,  sonra sizi yaşatan,  sonra sizi öldüren,  sonra sizi diriltendir. Ortak koştuklarınızdan bunları yapacak olan var mı? Allah,  onların şirk koştuklarından münezzehtir,  yüceler yücesidir.', 'الله الذي خلقكم ثم رزقكم ثم يميتكم ثم يحييكم هل من شركايكم من يفعل من ذلكم من شي سبحنه وتعلي عما يشركون'),
(3450, 30, 41, 'ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ اَيْدِي النَّاسِ لِيُذ۪يقَهُمْ بَعْضَ الَّذ۪ي عَمِلُوا لَعَلَّهُمْ يَرْجِعُونَ', 'Zaharel fesadu fil berri vel bahri bima kesebet eydin nasi, li yuzikahum ba\'dallezi amilu leallehum yerciun.', 'İnsanların kendi yaptıklarından dolayı karada ve denizde fesat ortaya çıktı. Belki akıllarını başlarına alırlar diye yaptıklarının bir kısmı onlara tattırıldı.', 'ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون'),
(3451, 30, 42, 'قُلْ س۪يرُوا فِي الْاَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلُۜ كَانَ اَكْثَرُهُمْ مُشْرِك۪ينَ', 'Kul siru fil ardı fenzuru keyfe kane akıbetullezine min kabl, kane ekseruhum muşrikin.', 'De ki: \"Yeryüzünde gezin de daha öncekilerin sonlarının nasıl olduğuna bakın. Onların çoğu müşriklerdendi.\"', 'قل سيروا في الارض فانظروا كيف كان عقبة الذين من قبل كان اكثرهم مشركين'),
(3452, 30, 43, 'فَاَقِمْ وَجْهَكَ لِلدّ۪ينِ الْقَيِّمِ مِنْ قَبْلِ اَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ مِنَ اللّٰهِ يَوْمَئِذٍ يَصَّدَّعُونَ', 'Fe ekim vecheke lid dinil kayyimi min kabli en ye\'tiye yevmun la meredde lehu minallahi yevmeizin yassaddeun.', 'Öyleyse Allah tarafından geri döndürülmesi olmayan gün gelmeden önce,  yönünü,  koruyup güvene alan dine çevir,  ona sıkı sıkıya bağlan. İzin Günü[1] onlar bölük bölük ayrılırlar.[2]', 'فاقم وجهك للدين القيم من قبل ان ياتي يوم لا مرد له من الله يوميذ يصدعون'),
(3453, 30, 44, 'مَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُۚ وَمَنْ عَمِلَ صَالِحاً فَلِاَنْفُسِهِمْ يَمْهَدُونَۙ', 'Men kefere fe aleyhi kufruh, ve men amile salihan fe li enfusihim yemhedun.', 'Kim küfrederse[1],  küfrü kendi aleyhinedir. Kim salihatı[2] yaparsa,  onlar kendileri için iyi bir gelecek hazırlamış olurlar.', 'من كفر فعليه كفره ومن عمل صلحا فلانفسهم يمهدون'),
(3454, 30, 45, 'لِيَجْزِيَ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنْ فَضْلِه۪ۜ اِنَّهُ لَا يُحِبُّ الْكَافِر۪ينَ', 'Li yecziyellezine amenu ve amilus salihati min fadlih, innehu la yuhıbbul kafirin.', 'İnanan ve salihatı yapanlara lütfundan karşılık verir. O,  Kafirleri sevmez.', 'ليجزي الذين امنوا وعملوا الصلحت من فضله انه لا يحب الكفرين'),
(3455, 30, 46, 'وَمِنْ اٰيَاتِه۪ٓ اَنْ يُرْسِلَ الرِّيَاحَ مُبَشِّرَاتٍ وَلِيُذ۪يقَكُمْ مِنْ رَحْمَتِه۪ وَلِتَجْرِيَ الْفُلْكُ بِاَمْرِه۪ وَلِتَبْتَغُوا مِنْ فَضْلِه۪ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Ve min ayatihi en yursiler riyaha mubeşşiratin ve li yuzikakum min rahmetihi ve li tecriyel fulku bi emrihi ve li tebtegu min fadlihi ve leallekum teşkurun.', 'Rüzgarları müjdeci olarak göndererek,  rahmetinden size tattırması,  buyruğu ile gemilerin akıp gitmesi ve lütfundan rızık istemeniz,  O\'nun ayetlerindendir.[1] Umulur ki şükredenlerden olursunuz.', 'ومن ايته ان يرسل الريح مبشرت وليذيقكم من رحمته ولتجري الفلك بامره ولتبتغوا من فضله ولعلكم تشكرون'),
(3456, 30, 47, 'وَلَقَدْ اَرْسَلْنَا مِنْ قَبْلِكَ رُسُلاً اِلٰى قَوْمِهِمْ فَجَٓاؤُ۫هُمْ بِالْبَيِّنَاتِ فَانْتَقَمْنَا مِنَ الَّذ۪ينَ اَجْرَمُواۜ وَكَانَ حَقاًّ عَلَيْنَا نَصْرُ الْمُؤْمِن۪ينَ', 'Ve lekad erselna min kablike rusulen ila kavmihim fe cauhum bil beyyinati fentekamna minellezine ecramu, ve kane hakkan aleyna nasrul mu\'minin.', 'Ant olsun ki,  senden önce,  birçok resulü halklarına gönderdik. Onlara beyyineler[1] getirdiler. Ardından suçlulardan intikam aldık. Mü\'min kimselere yardım etmek Bize hak oldu.', 'ولقد ارسلنا من قبلك رسلا الي قومهم فجاوهم بالبينت فانتقمنا من الذين اجرموا وكان حقا علينا نصر المومنين'),
(3457, 30, 48, 'اَللّٰهُ الَّذ۪ي يُرْسِلُ الرِّيَاحَ فَتُث۪يرُ سَحَاباً فَيَبْسُطُهُ فِي السَّمَٓاءِ كَيْفَ يَشَٓاءُ وَيَجْعَلُهُ  كِسَفاً فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِه۪ۚ فَاِذَٓا اَصَابَ بِه۪ مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ٓ اِذَا هُمْ يَسْتَبْشِرُونَ', 'Allahullezi yursilur riyaha fe tusiru sehaben fe yebsutuhu fis semai keyfe yeşau ve yec\'aluhu kisefen fe terel vedka yahrucu min hılalih, fe iza esabe bihi men yeşau min ibadihi iza hum yestebşirun.', 'Allah,  rüzgarı göndererek bulutları hareket ettirir. Sonra onu gökyüzünde dilediği gibi yayıp kütleler haline getirir. Sonra onun arasından yağmurun çıktığını görürsün. Böylece kullarından dilediğine onu isabet ettirdiği zaman onlar sevinirler.', 'الله الذي يرسل الريح فتثير سحابا فيبسطه في السما كيف يشا ويجعله كسفا فتري الودق يخرج من خلله فاذا اصاب به من يشا من عباده اذا هم يستبشرون'),
(3458, 30, 49, 'وَاِنْ كَانُوا مِنْ قَبْلِ اَنْ يُنَزَّلَ عَلَيْهِمْ مِنْ قَبْلِه۪ لَمُبْلِس۪ينَ', 'Ve in kanu min kabli en yunezzele aleyhim min kablihi le mublisin.', 'Oysa onlar,  yağmurun onlara indirilmesinden önce gerçekten ümitlerini kesenlerdi.', 'وان كانوا من قبل ان ينزل عليهم من قبله لمبلسين'),
(3459, 30, 50, 'فَانْظُرْ اِلٰٓى اٰثَارِ رَحْمَتِ اللّٰهِ كَيْفَ يُحْـيِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ اِنَّ ذٰلِكَ لَمُحْـيِ الْمَوْتٰىۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Fenzur ila asari rahmetillahi keyfe yuhyil arda ba\'de mevtiha, inne zalike le muhyil mevta, ve huve ala kulli şey\'in kadir.', 'Allah\'ın rahmetinin eserlerine bir bak! Ölümünden sonra yeryüzünü nasıl diriltiyor! Ölüleri de kesinlikle diriltecek O\'dur. O,  Her Şeye Güç Yetiren\'dir.', 'فانظر الي اثر رحمت الله كيف يحي الارض بعد موتها ان ذلك لمحيي الموتي وهو علي كل شي قدير'),
(3460, 30, 51, 'وَلَئِنْ اَرْسَلْنَا ر۪يحاً فَرَاَوْهُ مُصْفَراًّ لَظَلُّوا مِنْ بَعْدِه۪ يَكْفُرُونَ', 'Ve le in erselna rihan fe raevhu musfarran le zallu min ba\'dihi yekfurun.', 'Eğer rüzgar göndersek,  ekini ve bitkileri sararmış görseler,  nankörlük etmeye başlarlar.', 'ولين ارسلنا ريحا فراوه مصفرا لظلوا من بعده يكفرون'),
(3461, 30, 52, 'فَاِنَّكَ لَا تُسْمِعُ الْمَوْتٰى وَلَا تُسْمِعُ الصُّمَّ الدُّعَٓاءَ اِذَا وَلَّوْا مُدْبِر۪ينَ', 'Fe inneke la tusmiul mevta ve la tusmius summed duae iza vellev mudbirin.', 'Şu bir gerçek ki,  sen ölülere[1] duyuramazsın. Arkasını dönüp giden sağırlara[2] da çağrıyı duyuramazsın.[3]', 'فانك لا تسمع الموتي ولا تسمع الصم الدعا اذا ولوا مدبرين'),
(3462, 30, 53, 'وَمَٓا اَنْـتَ بِهَادِ الْعُمْيِ عَنْ ضَلَالَتِهِمْۜ اِنْ تُسْمِعُ اِلَّا مَنْ يُؤْمِنُ بِاٰيَاتِنَا فَهُمْ مُسْلِمُونَ۟', 'Ve ma ente bi hadil umyi an dalaletihim, in tusmiu illa men yu\'minu bi ayatina fe hum muslimun.', 'Sen,  körleri[1] sapkınlıklarından kurtarıp doğru yola iletemezsin. Sen,  ayetlerimizi ancak iman edeceklere duyurabilirsin; zira onlar teslim[2] olmuş kimselerdir.', 'وما انت بهاد العمي عن ضللتهم ان تسمع الا من يومن بايتنا فهم مسلمون'),
(3463, 30, 54, 'اَللّٰهُ الَّذ۪ي خَلَقَكُمْ مِنْ ضَعْفٍ ثُمَّ جَعَلَ مِنْ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنْ بَعْدِ قُوَّةٍ ضَعْفاً وَشَيْبَةًۜ يَخْلُقُ مَا يَشَٓاءُۚ وَهُوَ الْعَل۪يمُ الْقَد۪يرُ', 'Allahullezi halakakum min da\'fin summe ceale min ba\'di da\'fin kuvveten summe ceale min ba\'di kuvvetin da\'fen ve şeybeh, yahluku ma yeşau, ve huvel alimul kadir.', 'Sizi önce zayıf[1] yaratıp,  ardından size güç veren sonra bu gücün ardından sizi zayıf ve yaşlı kılan Allah\'tır. O,  dilediği şeyi yaratır. Ve O,  Her Şeyi Bilen\'dir,  Her Şeye Gücü Yeten\'dir.', 'الله الذي خلقكم من ضعف ثم جعل من بعد ضعف قوة ثم جعل من بعد قوة ضعفا وشيبة يخلق ما يشا وهو العليم القدير'),
(3464, 30, 55, 'وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَۙ مَا لَبِثُوا غَيْرَ سَاعَةٍۜ  كَذٰلِكَ كَانُوا يُؤْفَكُونَ', 'Ve yevme tekumus saatu yuksimul mucrimune ma lebisu gayra saah, kezalike kanu yu\'fekun.', 'Kıyametin koptuğu gün,  mücrimler[1] dünyada bir saatten fazla kalmadıklarına yemin ederler. Onlar işte böyle döndürülüyorlardı.[2]', 'ويوم تقوم الساعة يقسم المجرمون ما لبثوا غير ساعة كذلك كانوا يوفكون'),
(3465, 30, 56, 'وَقَالَ الَّذ۪ينَ اُو۫تُوا الْعِلْمَ وَالْا۪يمَانَ لَقَدْ لَبِثْتُمْ ف۪ي كِتَابِ اللّٰهِ اِلٰى يَوْمِ الْبَعْثِۘ فَهٰذَا يَوْمُ الْبَعْثِ وَلٰكِنَّكُمْ كُنْتُمْ لَا تَعْلَمُونَ', 'Ve kalellezine utul ilme vel imane lekad lebistum fi kitabillahi ila yevmil ba\'si fe haza yevmul ba\'si ve lakinnekum kuntum la ta\'lemun.', 'Kendilerine bilgi ve iman verilenler: \"Ant olsun ki,  siz Allah\'ın yasasındaki diriliş gününe kadar kaldınız. İşte bu dirilme günüdür. Ne var ki siz bu gerçeği algılayamadınız.', 'وقال الذين اوتوا العلم والايمن لقد لبثتم في كتب الله الي يوم البعث فهذا يوم البعث ولكنكم كنتم لا تعلمون'),
(3466, 30, 57, 'فَيَوْمَئِذٍ لَا يَنْفَعُ الَّذ۪ينَ ظَلَمُوا مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', 'Fe yevmeizin la yenfeullezine zalemu ma\'ziratuhum ve la hum yusta\'tebun.', 'Artık o gün zalimlere mazeretleri yarar sağlamaz. Onlardan mazeret de istenmeyecek.', 'فيوميذ لا ينفع الذين ظلموا معذرتهم ولا هم يستعتبون'),
(3467, 30, 58, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ ف۪ي هٰذَا الْقُرْاٰنِ مِنْ كُلِّ مَثَلٍۜ وَلَئِنْ جِئْتَهُمْ بِاٰيَةٍ لَيَقُولَنَّ الَّذ۪ينَ كَفَرُٓوا اِنْ اَنْتُمْ اِلَّا مُبْطِلُونَ', 'Ve lekad darebna lin nasi fi hazel kur\'ani min kulli mesel, ve le in ci\'tehum bi ayetin le yekulennellezine keferu in entum illa mubtılun.', 'Ant olsun ki,  insanlar için bu Kur\'an\'da her türlü örneği vererek gerçekleri anlattık. Sen onlara bir ayet[1] de getirsen,  Kafirler kesinlikle: \"Siz,  sadece,  asılsız iddialarda bulunan kimselersiniz.\" derler.', 'ولقد ضربنا للناس في هذا القران من كل مثل ولين جيتهم باية ليقولن الذين كفروا ان انتم الا مبطلون'),
(3468, 30, 59, 'كَذٰلِكَ يَطْبَعُ اللّٰهُ عَلٰى قُلُوبِ الَّذ۪ينَ لَا يَعْلَمُونَ', 'Kezalike yatbaullahu ala kulubillezine la ya\'lemun.', 'İşte Allah,  bilmeyen[1] kimselerin kalplerinin üzerini böyle mühürler.', 'كذلك يطبع الله علي قلوب الذين لا يعلمون'),
(3469, 30, 60, 'فَاصْبِرْ اِنَّ وَعْدَ اللّٰهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ الَّذ۪ينَ لَا يُوقِنُونَ', 'Fasbir inne va\'dallahi hakkun ve la yestahıffennekellezine la yukınun.', 'Öyleyse sabret,  kuşkusuz Allah\'ın verdiği söz kesindir. Sakın ha! İnanmayanlar seni gevşetmesinler.', 'فاصبر ان وعد الله حق ولا يستخفنك الذين لا يوقنون'),
(3470, 31, 1, 'الٓمٓ۠', 'Elif lam mim.', 'Elif. Lam. Mim.', 'الم'),
(3471, 31, 2, 'تِلْكَ اٰيَاتُ الْكِتَابِ الْحَك۪يمِۙ', 'Tilke ayatul kitabil hakim.', 'İşte bunlar[1],  hakim olan Kitap\'ın ayetleridir.', 'تلك ايت الكتب الحكيم'),
(3472, 31, 3, 'هُدًى وَرَحْمَةً لِلْمُحْسِن۪ينَۙ', 'Huden ve rahmeten lil muhsinin.', 'İyiler için yol gösterici ve rahmettir.', 'هدي ورحمة للمحسنين'),
(3473, 31, 4, 'اَلَّذ۪ينَ يُق۪يمُونَ الصَّلٰوةَ وَيُؤْتُونَ الزَّكٰوةَ وَهُمْ بِالْاٰخِرَةِ هُمْ يُوقِنُونَۜ', 'Ellezine yukimunes salate ve yu\'tunez zekate ve hum bil ahıreti hum yukinun.', 'Onlar,  salatı ikame ederler ve zekatı yaparlar[1]. Onlar ahirete kesin olarak iman ederler.', 'الذين يقيمون الصلوة ويوتون الزكوة وهم بالاخرة هم يوقنون'),
(3474, 31, 5, 'اُو۬لٰٓئِكَ عَلٰى هُدًى مِنْ رَبِّهِمْ وَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Ulaike ala huden min rabbihim ve ulaike humul muflihun.', 'İşte onlar,  Rabb\'leri tarafından doğru yol üzerindedirler. Onlar kurtuluşa erenlerdir.', 'اوليك علي هدي من ربهم واوليك هم المفلحون'),
(3475, 31, 6, 'وَمِنَ النَّاسِ مَنْ يَشْتَر۪ي لَهْوَ الْحَد۪يثِ لِيُضِلَّ عَنْ سَب۪يلِ اللّٰهِ بِغَيْرِ عِلْمٍۙ وَيَتَّخِذَهَا هُزُواًۜ اُو۬لٰٓئِكَ لَهُمْ عَذَابٌ مُه۪ينٌ', 'Ve minen nasi men yeşteri lehvel hadisi li yudılle an sebilillahi bi gayri ilmin ve yettehızeha huzuva, ulaike lehum azabun muhin.', 'İnsanlardan,  bilgisi olmadığı halde; Allah\'ın yolundan saptırmak ve onu alay konusu edinmek için gerçeği boş hadislerle[1] değiştirenler vardır. İşte onlar için aşağılayıcı bir azap vardır.', 'ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اوليك لهم عذاب مهين'),
(3476, 31, 7, 'وَاِذَا تُتْلٰى عَلَيْهِ اٰيَاتُنَا وَلّٰى مُسْتَكْبِراً كَاَنْ لَمْ يَسْمَعْهَا كَاَنَّ ف۪ٓي اُذُنَيْهِ وَقْراًۚ فَبَشِّرْهُ بِعَذَابٍ اَل۪يمٍ', 'Ve iza tutla aleyhi ayatuna vella mustekbiren ke en lem yesma\'ha ke enne fi uzuneyhi vakra, fe beşşirhu bi azabin elim.', 'Ona ayetlerimiz okunduğu zaman sanki onları duymamış,  sanki kulakları sağırmış gibi,  küstahça umursamazlıktan gelir. Öyleyse onu,  çok acı veren bir azaptan haberdar et.', 'واذا تتلي عليه ايتنا ولي مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم'),
(3477, 31, 8, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتُ النَّع۪يمِۙ', 'İnnellezine amenu ve amilus salihati lehum cennatun na\'im.', 'İman eden ve salihatı[1] yapanlar için,  Naim Cennet\'ler vardır.', 'ان الذين امنوا وعملوا الصلحت لهم جنت النعيم'),
(3478, 31, 9, 'خَالِد۪ينَ ف۪يهَاۜ وَعْدَ اللّٰهِ حَقاًّۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Halidine fiha, va\'dallahi hakka, ve huvel azizul hakim.', 'Orada sürekli kalırlar. Allah\'ın vaadi gerçektir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'خلدين فيها وعد الله حقا وهو العزيز الحكيم'),
(3479, 31, 10, 'خَلَقَ السَّمٰوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا وَاَلْقٰى فِي الْاَرْضِ رَوَاسِيَ اَنْ تَم۪يدَ بِكُمْ وَبَثَّ ف۪يهَا مِنْ كُلِّ دَٓابَّةٍۜ وَاَنْزَلْنَا مِنَ السَّمَٓاءِ مَٓاءً فَاَنْبَتْنَا ف۪يهَا مِنْ كُلِّ زَوْجٍ كَر۪يمٍ', 'Halakas semavati bi gayri amedin terevneha ve elka fil ardı revasiye en temide bikum ve besse fiha min kulli dabbeh, ve enzelna mines semai maen fe enbetna fiha min kulli zevcin kerim.', 'Gördüğünüz gibi gökleri direksiz yarattı. Yeryüzüne de sizi sarsmaması için ağır baskılar yerleştirdi. Orada her türlü canlıyı yaydı. Gökten su indirip,  orada her kerim[1] çiftten bitki bitirdi.', 'خلق السموت بغير عمد ترونها والقي في الارض روسي ان تميد بكم وبث فيها من كل دابة وانزلنا من السما ما فانبتنا فيها من كل زوج كريم'),
(3480, 31, 11, 'هٰذَا خَلْقُ اللّٰهِ فَاَرُون۪ي مَاذَا خَلَقَ الَّذ۪ينَ مِنْ دُونِه۪ۜ بَلِ الظَّالِمُونَ ف۪ي ضَلَالٍ مُب۪ينٍ۟', 'Haza halkullahi fe eruni maza halakallezine min dunih, beliz zalimune fi dalalin mubin.', 'Bu Allah\'ın yaratmasıdır. Haydi,  bana O\'ndan başkasının ne yarattığını gösterin. Hayır! Zalimler apaçık bir sapkınlık içindedirler.', 'هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظلمون في ضلل مبين'),
(3481, 31, 12, 'وَلَقَدْ اٰتَيْنَا لُقْمٰنَ الْحِكْمَةَ اَنِ اشْكُرْ لِلّٰهِۜ وَمَنْ يَشْكُرْ فَاِنَّمَا يَشْكُرُ لِنَفْسِه۪ۚ وَمَنْ كَفَرَ فَاِنَّ اللّٰهَ غَنِيٌّ حَم۪يدٌ', 'Ve lekad ateyna lukmanel hikmete enişkur lillah, ve men yeşkur fe innema yeşkuru li nefsih, ve men kefere fe innellahe ganiyyun hamid.', 'Ant olsun ki,  \"Allah\'a şükret.\" diye,  Lokman\'a hikmet[1] verdik. Kim şükrederse[2] kendisi için şükreder. Kim de nankörlük ederse bilsin ki Allah kimsenin şükrüne muhtaç değildir. Bütün övgüler O\'nadır.', 'ولقد اتينا لقمن الحكمة ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد'),
(3482, 31, 13, 'وَاِذْ قَالَ لُقْمٰنُ لِابْنِه۪ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللّٰهِۜ اِنَّ الشِّرْكَ لَظُلْمٌ عَظ۪يمٌ', 'Ve iz kale lukmanu libnihi ve huve yaızuhu ya buneyye la tuşrik billah, inneş şirke le zulmun azim.', 'Vaktiyle Lokman oğluna öğüt vererek: \"Ey yavrucuğum! Allah\'a şirk[1] koşma,  kuşkusuz şirk koşmak çok büyük bir zulümdür.[2]\" demişti.', 'واذ قال لقمن لابنه وهو يعظه يبني لا تشرك بالله ان الشرك لظلم عظيم'),
(3483, 31, 14, 'وَوَصَّيْنَا الْاِنْسَانَ بِوَالِدَيْهِۚ حَمَلَتْهُ اُمُّهُ وَهْناً عَلٰى وَهْنٍ وَفِصَالُهُ ف۪ي عَامَيْنِ اَنِ اشْكُرْ ل۪ي وَلِوَالِدَيْكَۜ اِلَيَّ الْمَص۪يرُ', 'Ve vassaynel insane bi valideyh, hamelethu ummuhu vehnen ala vehnin ve fisaluhu fi ameyni enişkurli ve li valideyk, ileyyel masir.', 'İnsana,  anne ve babasını vasiyet ettik. Onu,  annesi zorluk üzerine zorluk içinde taşıdı. İki yıl boyunca ona süt verdi. Bana,  anne ve babana şükret![1] Dönüş Bana\'dır.', 'ووصينا الانسن بولديه حملته امه وهنا علي وهن وفصله في عامين ان اشكر لي ولولديك الي المصير'),
(3484, 31, 15, 'وَاِنْ جَاهَدَاكَ عَلٰٓى اَنْ تُشْرِكَ ب۪ي مَا لَيْسَ لَكَ بِه۪ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفاًۘ وَاتَّبِعْ سَب۪يلَ مَنْ اَنَابَ اِلَيَّۚ ثُمَّ اِلَيَّ مَرْجِعُكُمْ فَاُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ve in cahedake ala en tuşrike bi ma leyse leke bihi ilmun fe la tutı\'huma ve sahibhuma fid dunya magrufen vettebi\' sebile men enabe ileyy, summe ileyye merciukum fe unebbiukum bi ma kuntum ta\'melun.', 'Eğer o ikisi,  hakkında bilgin olmayan bir şeyi Bana ortak koşman için seninle cihad[1] ederlerse,  o zaman sakın onlara itaat etme. Dünyada onlarla güzel geçin. Bana yönelen kimselerin yoluna uy. Sonra dönüşünüz Bana\'dır. O zaman yaptığınız şeyleri size haber vereceğim.', 'وان جهداك علي ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبيكم بما كنتم تعملون'),
(3485, 31, 16, 'يَا بُنَيَّ اِنَّـهَٓا اِنْ تَكُ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ فَتَكُنْ ف۪ي صَخْرَةٍ اَوْ فِي السَّمٰوَاتِ اَوْ فِي الْاَرْضِ يَأْتِ بِهَا اللّٰهُۜ اِنَّ اللّٰهَ لَط۪يفٌ خَب۪يرٌ', 'Ya buneyye inneha in teku miskale habbetin min hardalin fe tekun fi sahretin ev fis semavati ev fil ardı ye\'ti bihallah, innellahe latifun habir.', '\"Ey oğulcuğum! Yaptıkların bir hardal tanesi kadar olup da bir kayanın içinde veya gökyüzünde veya yer altında bile olsa,  Allah onu meydana çıkarır. Kuşkusuz Allah,  Bütün Ayrıntıları Bilen\'dir,  Her Şeyden Haberdar\'dır.\"', 'يبني انها ان تك مثقال حبة من خردل فتكن في صخرة او في السموت او في الارض يات بها الله ان الله لطيف خبير'),
(3486, 31, 17, 'يَا بُنَيَّ اَقِمِ الصَّلٰوةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلٰى مَٓا اَصَابَكَۜ اِنَّ ذٰلِكَ مِنْ عَزْمِ الْاُمُورِۚ', 'Ya buneyye ekımıs salate ve\'mur bil ma\'rufi venhe anil munkeri vasbir ala ma esabek, inne zalike min azmil umur.', '\"Ey oğulcuğum! Salatı ikame et[1],  ma\'ruf[2] olanı yap,  münker olandan sakındır.[2] Karşılaştığın zorluklara sabret.[3] Bunlar kararlılık göstermen gereken şeylerdir.\"', 'يبني اقم الصلوة وامر بالمعروف وانه عن المنكر واصبر علي ما اصابك ان ذلك من عزم الامور'),
(3487, 31, 18, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِي الْاَرْضِ مَرَحاًۜ اِنَّ اللّٰهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍۚ', 'Ve la tusa\'ir haddeke lin nasi ve la temşi fil ardı meraha innellahe la yuhıbbu kulle muhtalin fehur.', '\"Kibirli bir tavırla insanları küçümseyerek onlardan yüz çevirme ve yeryüzünde böbürlenerek yürüme. Kuşkusuz Allah,  kendisini beğenen ve övünüp duranları sevmez.\"', 'ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور'),
(3488, 31, 19, 'وَاقْصِدْ ف۪ي مَشْيِكَ وَاغْضُضْ مِنْ صَوْتِكَۜ اِنَّ اَنْكَرَ الْاَصْوَاتِ لَصَوْتُ الْحَم۪يرِ۟', 'Vaksid fi meşyike vagdud min savtik, inne enkerel asvati le savtul hamir.', '\"Yürüyüşünde ölçülü ol; sesini alçalt. Seslerin en çirkini,  eşeklerin sesidir.\"', 'واقصد في مشيك واغضض من صوتك ان انكر الاصوت لصوت الحمير'),
(3489, 31, 20, 'اَلَمْ تَرَوْا اَنَّ اللّٰهَ سَخَّرَ لَكُمْ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ وَاَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةًۜ وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللّٰهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُن۪يرٍ', 'EE lem terev ennellahe sehhare lekum ma fis semavati ve ma fil ardı ve esbega aleykum niamehu zahireten ve batıneh, ve minen nasi men yucadilu fillahi bi gayri ilmin ve la huden ve la kitabin munir.', 'Allah\'ın,  göklerde ve yerde olan her şeyi sizin hizmetinize sunduğunu,  görünen görünmeyen[1] nimetleri sizin için bollaştırdığını görmüyor musunuz? Yine de kimi insanlar; bir bilgiye,  bir yol göstericiye ve aydınlatıcı bir kitaba dayanmaksızın Allah hakkında tartışıyorlar.', 'الم تروا ان الله سخر لكم ما في السموت وما في الارض واسبغ عليكم نعمه ظهرة وباطنة ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير'),
(3490, 31, 21, 'وَاِذَا ق۪يلَ لَهُمُ اتَّبِعُوا مَٓا اَنْزَلَ اللّٰهُ قَالُوا بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ اٰبَٓاءَنَاۜ اَوَلَوْ كَانَ الشَّيْطَانُ يَدْعُوهُمْ اِلٰى عَذَابِ السَّع۪يرِ', 'Ve iza kile lehumuttebiu ma enzelallahu kalu bel nettebiu ma vecedna aleyhi abaena, e ve lev kaneş şeytanu yed\'uhum ila azabis sair.', 'Onlara,  \"Allah\'ın indirdiği şeye uyun.\" dendiği zaman: \"Hayır! Biz atalarımızı üzerinde bulduğumuz şeye uyarız.\" dediler. Peki! Ya şeytan[1] onları alevli ateşin azabına çağırmış olsa da mı?', 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما وجدنا عليه ابانا اولو كان الشيطن يدعوهم الي عذاب السعير'),
(3491, 31, 22, 'وَمَنْ يُسْلِمْ وَجْهَهُٓ اِلَى اللّٰهِ وَهُوَ مُحْسِنٌ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقٰىۜ وَاِلَى اللّٰهِ عَاقِبَةُ الْاُمُورِ', 'Ve men yuslim vechehu ilallahi ve huve muhsinun fe kadistemseke bil urvetil vuska, ve ilallahi akibetul umur.', 'Kim muhsin[1] olarak,  tüm varlığı ile Allah\'a yönelirse,  işte o,  gerçekten en sağlam tutamağa tutunmuştur. İşlerin sonucu yalnızca Allah\'a aittir.', 'ومن يسلم وجهه الي الله وهو محسن فقد استمسك بالعروة الوثقي والي الله عقبة الامور'),
(3492, 31, 23, 'وَمَنْ كَفَرَ فَلَا يَحْزُنْكَ كُفْرُهُ ۜ اِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُمْ بِمَا عَمِلُواۜ اِنَّ اللّٰهَ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Ve men kefere fe la yahzunke kufruh, ileyna merciuhum fe nunebbiuhum bi ma amil, innallahe alimun bi zatis sudur.', 'Kim de Kafirlik[1] ederse,  artık onun Küfrü seni üzmesin. Onların dönüşü yalnızca Bize\'dir. Yaptıkları şeyleri haber vereceğiz. Kuşkusuz Allah,  sinelerde olanı en iyi bilendir.', 'ومن كفر فلا يحزنك كفره الينا مرجعهم فننبيهم بما عملوا ان الله عليم بذات الصدور'),
(3493, 31, 24, 'نُمَتِّعُهُمْ قَل۪يلاً ثُمَّ نَضْطَرُّهُمْ اِلٰى عَذَابٍ غَل۪يظٍ', 'Numettiuhum kalilen summe nadtarruhum ila azabin galiz.', 'Onları biraz yararlandırırız.[1] Sonra ağır bir azaba maruz bırakırız.', 'نمتعهم قليلا ثم نضطرهم الي عذاب غليظ'),
(3494, 31, 25, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ لَيَقُولُنَّ اللّٰهُۜ  قُلِ الْحَمْدُ لِلّٰهِۜ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَ', 'Ve le in seeltehum men halakas semavati vel arda le yekulunnellah, kulil hamdulillah, bel ekseruhum la ya\'lemun.', 'Eğer onlara: \"Gökleri ve yeri kim yarattı?\" diye sorsan,  kesinlikle \"Allah.\" diyecekler. De ki: \"Bütün övgüler Allah\'a layıktır.\" Hayır,  çokları bunu idrak etmezler.', 'ولين سالتهم من خلق السموت والارض ليقولن الله قل الحمد لله بل اكثرهم لا يعلمون'),
(3495, 31, 26, 'لِلّٰهِ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۜ اِنَّ اللّٰهَ هُوَ الْغَنِيُّ الْحَم۪يدُ', 'Lillahi ma fis semavati vel ard, innallahe huvel ganiyyul hamid.', 'Göklerde ve yerde olanlar,  Allah\'ındır. Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'لله ما في السموت والارض ان الله هو الغني الحميد');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3496, 31, 27, 'وَلَوْ اَنَّ مَا فِي الْاَرْضِ مِنْ شَجَرَةٍ اَقْلَامٌ وَالْبَحْرُ يَمُدُّهُ مِنْ بَعْدِه۪ سَبْعَةُ اَبْحُرٍ مَا نَفِدَتْ كَلِمَاتُ اللّٰهِۜ اِنَّ اللّٰهَ عَز۪يزٌ حَك۪يمٌ', 'Ve lev enne ma fil ardı min şeceretin aklamun vel bahru yemudduhu min ba\'dihi seb\'atu ebhurin ma nefidet kelimatullah, innellahe azizun hakim.', 'Eğer yeryüzünde bulunan ağaçlar kalem olsaydı; deniz ve yedi[1] deniz[2] daha ilave edilseydi,  Allah\'ın kelimeleri[3] tükenmezdi. Kuşkusuz Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir', 'ولو انما في الارض من شجرة اقلم والبحر يمده من بعده سبعة ابحر ما نفدت كلمت الله ان الله عزيز حكيم'),
(3497, 31, 28, 'مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ اِلَّا كَنَفْسٍ وَاحِدَةٍۜ اِنَّ اللّٰهَ سَم۪يعٌ بَص۪يرٌ', 'Ma halkukum ve la ba\'sukum illa ke nefsin vahıdeh, innallahe semiun basir.', 'Sizin yaratılmanız ve ölümden sonra diriltilmeniz Allah için bir kişiyi yaratmak ve diriltmek kadar kolaydır. Kuşkusuz Allah,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'ما خلقكم ولا بعثكم الا كنفس وحدة ان الله سميع بصير'),
(3498, 31, 29, 'اَلَمْ تَرَ اَنَّ اللّٰهَ يُولِجُ الَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي الَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَۘ   كُلٌّ يَجْر۪ٓي اِلٰٓى اَجَلٍ مُسَمًّى وَاَنَّ اللّٰهَ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'E lem tere ennallahe yulicul leyle fin nehari ve yulicun nehare fil leyli, ve sehhareş şemse vel kamere kullun yecri ila ecelin musemmen ve ennallahe bi ma ta\'melune habir.', 'Allah\'ın; geceyi gündüze,  gündüzü de geceye çevirdiğini görmüyor musun? Güneş\'i ve Ay\'ı buyruk altına aldı. Her biri belirlenmiş bir süreye kadar hareketini sürdürüyor. Kuşkusuz Allah,  yaptıklarınızdan haberdardır.', 'الم تر ان الله يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري الي اجل مسمي وان الله بما تعملون خبير'),
(3499, 31, 30, 'ذٰلِكَ بِاَنَّ اللّٰهَ هُوَ الْحَقُّ وَاَنَّ مَا يَدْعُونَ مِنْ دُونِهِ الْبَاطِلُۙ وَاَنَّ اللّٰهَ هُوَ الْعَلِيُّ الْكَب۪يرُ۟', 'Zalike bi ennellahe huvel hakku ve enne ma yed\'une min dunihil batılu ve ennallahe huvel aliyyul kebir.', 'Çünkü Allah gerçekliğin ta kendisidir. Ve onların,  O\'nun yanı sıra yakardıkları ise kesinlikle gerçek dışıdır. Kuşkusuz Allah,  Çok Yüce\'dir,  Çok Büyük\'tür.', 'ذلك بان الله هو الحق وان ما يدعون من دونه البطل وان الله هو العلي الكبير'),
(3500, 31, 31, 'اَلَمْ تَرَ اَنَّ الْفُلْكَ تَجْر۪ي فِي الْبَحْرِ بِنِعْمَتِ اللّٰهِ لِيُرِيَكُمْ مِنْ اٰيَاتِه۪ۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ', 'E lem tere ennel fulke tecri fil bahri bi ni\'metillahi li yuriyekum min ayatih inne fi zalike le ayatin li kulli sabbarin şekur.', 'Allah\'ın nimeti[1] ile denizde yüzen gemileri görmüyor musunuz? Allah,  bununla size ayetlerinden[2] göstermektedir. Kuşkusuz bunda sabreden[3] ve şükredenler[4] için dersler vardır.', 'الم تر ان الفلك تجري في البحر بنعمت الله ليريكم من ايته ان في ذلك لايت لكل صبار شكور'),
(3501, 31, 32, 'وَاِذَا غَشِيَهُمْ مَوْجٌ كَالظُّلَلِ دَعَوُا اللّٰهَ مُخْلِص۪ينَ لَهُ الدّ۪ينَۚ فَلَمَّا نَجّٰيهُمْ اِلَى الْبَرِّ فَمِنْهُمْ مُقْتَصِدٌۜوَمَا يَجْحَدُ بِاٰيَاتِنَٓا اِلَّا كُلُّ خَتَّارٍ كَفُورٍ', 'Ve iza gaşiyehum mevcun kez zuleli deavullahe muhlisine lehud din, fe lemma neccahum ilel berri fe minhum muktesıd, ve ma yechadu bi ayatina illa kullu hattarin kefur.', 'Ve karanlık gölgeler gibi dalgalar onları sardığı zaman,  dini O\'na has kılarak Allah\'a yalvarırlar. Ama onları karaya çıkarıp kurtardığı zaman,  onlardan bir kısmı orta bir yol tutar. Ve Bizim ayetlerimize ancak,  tam hain ve tam nankör olanlardan başkası bile bile ilgisiz kalmaz.', 'واذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجيهم الي البر فمنهم مقتصد وما يجحد بايتنا الا كل ختار كفور'),
(3502, 31, 33, 'يَٓا اَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْماً لَا يَجْز۪ي وَالِدٌ عَنْ وَلَدِه۪ۘ وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِه۪ شَيْـٔاًۜ اِنَّ وَعْدَ اللّٰهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيٰوةُ الدُّنْيَا۠ وَلَا يَغُرَّنَّكُمْ بِاللّٰهِ الْغَرُورُ', 'Ya eyyuhen nasutteku rabbekum vahşev yevmen la yeczi validun an veledihi ve la mevludun huve cazin an validihi şey\'a inne va\'dallahi hakkun fe la tegurrennekumul hayatud dunya, ve la yagurrennekum billahil garur.', 'Ey insanlar! Rabb\'inize takvalı olun. Ve babanın çocuğuna hiçbir yarar sağlayamadığı,  çocuğun da babasına hiçbir şey ile yarar sağlayamadığı günden sakının. Allah\'ın sözü gerçektir. Öyleyse,  dünya hayatı sizi aldatmasın! Sakın aldatıcı[1] sizi Allah ile aldatmasın.[2]', 'يايها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيا ان وعد الله حق فلا تغرنكم الحيوة الدنيا ولا يغرنكم بالله الغرور'),
(3503, 31, 34, 'اِنَّ اللّٰهَ عِنْدَهُ عِلْمُ السَّاعَةِۚ وَيُنَزِّلُ الْغَيْثَۚ وَيَعْلَمُ مَا فِي الْاَرْحَامِۜ وَمَا تَدْر۪ي نَفْسٌ مَاذَا تَكْسِبُ غَداًۜ وَمَا تَدْر۪ي نَفْسٌ بِاَيِّ اَرْضٍ تَمُو تُ  ۜ  اِنَّ اللّٰهَ عَل۪يمٌ خَب۪يرٌ', 'İnnallahe indehu ilmus saah, ve yunezzilul gays, ve ya\'lemu ma fil erham, ve ma tedri nefsun maza teksibu gada, ve ma tedri nefsun bi eyyi ardın temut, innallahe alimun habir.', 'Sa\'atin[1] bilgisi,  Allah\'ın yanındadır. Ve O,  yağmuru yağdırır,  rahimde olanı bilir. Kimse yarın ne kazanacağını bilemez. Kimse nerede öleceğini de bilemez. Kuşkusuz Allah,  Her Şeyi Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'ان الله عنده علم الساعة وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير'),
(3504, 32, 1, 'الٓـمٓ۠', 'Elif lam mim.', 'Elif. Lam. Mim.', 'الم'),
(3505, 32, 2, 'تَنْز۪يلُ الْكِتَابِ لَا رَيْبَ ف۪يهِ مِنْ رَبِّ الْعَالَم۪ينَۜ', 'Tenzilul kitabi la reybe fihi min rabbil alemin.', 'Mutlak doğru olan bu Kitap\'ın indirilişi,  alemlerin Rabb\'indendir.', 'تنزيل الكتب لا ريب فيه من رب العلمين'),
(3506, 32, 3, 'اَمْ يَقُولُونَ افْتَرٰيهُۚ بَلْ هُوَ الْحَقُّ مِنْ رَبِّكَ لِتُنْذِرَ قَوْماً مَٓا اَتٰيهُمْ مِنْ نَذ۪يرٍ مِنْ قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'Em yekulunefterah, bel huvel hakku min rabbike li tunzire kavmen ma etahum min nezirin min kablike leallehum yehtedun.', 'Yoksa \"Onu kendisi uydurdu\" mu diyorlar? Bilakis! O,  Rabb\'inden bir gerçektir. Senden önce kendilerine bir uyarıcı gelmemiş olan halkı uyarman içindir. Umulur ki böylece onlar,  doğru yolu seçerler.', 'ام يقولون افتريه بل هو الحق من ربك لتنذر قوما ما اتيهم من نذير من قبلك لعلهم يهتدون'),
(3507, 32, 4, 'اَللّٰهُ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَا ف۪ي سِتَّةِ اَيَّامٍ ثُمَّ اسْتَوٰى عَلَى الْعَرْشِۜ مَا لَكُمْ مِنْ دُونِه۪ مِنْ وَلِيٍّ وَلَا شَف۪يعٍۜ اَفَلَا تَتَذَكَّرُونَ', 'Allahullezi halakas semavati vel arda ve ma beynehuma fi sitteti eyyamin summesteva alel arş, ma lekum min dunihi min veliyyin ve la şefii, e fe la tetezekkerun.', 'O Allah ki; gökleri,  yeri ve ikisinin arasındakileri altı günde[1] yarattı. Sonra arşa isteva etti.[2] Sizin O\'ndan başka veliniz[3] ve şefaatçiniz yoktur. Hala öğüt almaz mısınız?', 'الله الذي خلق السموت والارض وما بينهما في ستة ايام ثم استوي علي العرش ما لكم من دونه من ولي ولا شفيع افلا تتذكرون'),
(3508, 32, 5, 'يُدَبِّرُ الْاَمْرَ مِنَ السَّمَٓاءِ اِلَى الْاَرْضِ ثُمَّ يَعْرُجُ اِلَيْهِ ف۪ي يَوْمٍ كَانَ مِقْدَارُهُٓ اَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ', 'Yudebbirul emre mines semai ilel ardı summe ya\'rucu ileyhi fi yevmin kane mıkdaruhu elfe senetin mimma teuddun.', 'Gökten yeryüzüne kadar işleri düzenler. Sonra miktarı sizin hesabınıza göre bin yıl süren bir gün[1] içinde işler O\'na yükselir.[2]', 'يدبر الامر من السما الي الارض ثم يعرج اليه في يوم كان مقداره الف سنة مما تعدون'),
(3509, 32, 6, 'ذٰلِكَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَز۪يزُ الرَّح۪يمُۙ', 'Zalike alimul gaybi veş şehadetil azizur rahim.', 'İşte O,  görünmeyeni ve görüneni bilen Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'ذلك علم الغيب والشهدة العزيز الرحيم'),
(3510, 32, 7, 'اَلَّـذ۪ٓي اَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ وَبَدَاَ خَلْقَ الْاِنْسَانِ مِنْ ط۪ينٍۚ', 'Ellezi ahsene kulle şey\'in halakahu ve bedee halkal insani min tin.', 'O ki yarattığı her şeyi en iyi şekilde yaratmıştır. İnsanı yaratmaya çamurdan[1] başladı.', 'الذي احسن كل شي خلقه وبدا خلق الانسن من طين'),
(3511, 32, 8, 'ثُمَّ جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَٓاءٍ مَه۪ينٍۚ', 'Summe ceale neslehu min sulaletin min main mehin.', 'Sonra onun soyunu[1] bir özden,  basit bir sudan[2],  devam ettirdi.', 'ثم جعل نسله من سللة من ما مهين'),
(3512, 32, 9, 'ثُمَّ سَوّٰيهُ وَنَفَخَ ف۪يهِ مِنْ رُوحِه۪ وَجَعَلَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٔدَةَۜ قَل۪يلاً مَا تَشْكُرُونَ', 'Summe sevvahu ve nefeha fihi min ruhihi ve ceale lekumus sem\'a vel ebsare vel ef\'ideh, kalilen ma teşkurun.', 'Sonra onu düzenledi ve ona ruhundan üfledi[1]. Size duyma yetisi,  görme yetisi ve fuad[2] verdi. Ne kadar az şükrediyorsunuz!', 'ثم سويه ونفخ فيه من روحه وجعل لكم السمع والابصر والافدة قليلا ما تشكرون'),
(3513, 32, 10, 'وَقَالُٓوا ءَاِذَا ضَلَلْنَا فِي الْاَرْضِ ءَاِنَّا لَف۪ي خَلْقٍ جَد۪يدٍۜ بَلْ هُمْ بِلِقَٓاءِ رَبِّهِمْ كَافِرُونَ', 'Ve kalu e iza dalelna fil ardı e inna le fi halkın cedid, bel hum bi likai rabbihim kafirun.', 'Onlar: \"Toprakta yok olup kaybolduktan sonra yeniden mi yaratılacağız?\" dediler. Hayır; onlar,  Rabb\'lerine kavuşmayı yalanlıyorlar.', 'وقالوا اذا ضللنا في الارض انا لفي خلق جديد بل هم بلقا ربهم كفرون'),
(3514, 32, 11, 'قُلْ يَتَوَفّٰيكُمْ مَلَكُ الْمَوْتِ الَّذ۪ي وُكِّلَ بِكُمْ ثُمَّ اِلٰى رَبِّكُمْ تُرْجَعُونَ۟', 'Kul yeteveffakum melekul mevtillezi vukkile bikum summe ila rabbikum turceun.', 'De ki: \"Size vekil kılınan[1] ölüm meleği,  sizi vefat ettirecek. Sonra Rabb\'inize döndürüleceksiniz.[2]', 'قل يتوفيكم ملك الموت الذي وكل بكم ثم الي ربكم ترجعون'),
(3515, 32, 12, 'وَلَوْ تَرٰٓى اِذِ الْمُجْرِمُونَ نَاكِسُوا رُؤُ۫سِهِمْ عِنْدَ رَبِّهِمْۜ رَبَّـنَٓا اَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَـالِحاً اِنَّا مُوقِنُونَ', 'Ve lev tera izil mucrimune nakısu ruusihim inde rabbihim, rabbena ebsarna ve semi\'na ferci\'na na\'mel salihan inna mukinun.', 'Mücrimleri,  Rabblerinin huzurunda başları öne eğilmiş olarak: \"Rabb\'imiz! Gördük ve dinledik,  şimdi bizi dünyaya geri gönder de salihatı[1] yapalım. Biz,  artık kesin bir şekilde inandık.\" derlerken bir görsen!', 'ولو تري اذ المجرمون ناكسوا روسهم عند ربهم ربنا ابصرنا وسمعنا فارجعنا نعمل صلحا انا موقنون'),
(3516, 32, 13, 'وَلَوْ شِئْنَا لَاٰتَيْنَا كُلَّ نَفْسٍ هُدٰيهَا وَلٰكِنْ حَقَّ الْقَوْلُ مِنّ۪ي لَاَمْلَـَٔنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ اَجْمَع۪ينَ', 'Ve lev şi\'na le ateyna kulle nefsin hudaha ve lakin hakkal kavlu minni le emleenne cehenneme minel cinneti ven nasi ecmain.', 'Eğer dileseydik,  herkese elbette hidayetini verirdik.[1] Fakat Ben\'den söz[2] hak oldu: \"Cehennemi tamamen cin ve insanlardan dolduracağım.\"[3]', 'ولو شينا لاتينا كل نفس هديها ولكن حق القول مني لاملان جهنم من الجنة والناس اجمعين'),
(3517, 32, 14, 'فَذُوقُوا بِمَا نَس۪يتُمْ لِقَٓاءَ يَوْمِكُمْ هٰذَاۚ اِنَّا نَس۪ينَاكُمْ وَذُوقُوا عَذَابَ الْخُلْدِ بِمَا كُنْتُمْ تَعْمَلُونَ', 'Fe zuku bi ma nesitum likae yevmikum haza, inna nesinakum ve zuku azabel huldi bi ma kuntum ta\'melun.', 'Öyleyse bu gününüzle karşılaşmayı unuttuğunuz[1] için tadın azabı. Kuşkusuz Biz de sizi unuttuk.[2] Yapmış olduklarınıza karşılık,  sürekli olan azabı tadın.', 'فذوقوا بما نسيتم لقا يومكم هذا انا نسينكم وذوقوا عذاب الخلد بما كنتم تعملون'),
(3518, 32, 15, 'اِنَّمَا يُؤْمِنُ بِاٰيَاتِنَا الَّذ۪ينَ اِذَا ذُكِّرُوا بِهَا خَرُّوا سُجَّداً وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ', 'İnnema yu\'minu bi ayatinellezine iza zukkiru biha harru succeden ve sebbehu bi hamdi rabbihim ve hum la yestekbirun.', 'Bizim ayetlerimize inananlar; kendilerine öğüt verildiği zaman saygı gösterirler[1] ve Rabblerini övgü ile yüceltirler. Onlar asla büyüklük taslamazlar.', 'انما يومن بايتنا الذين اذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون'),
(3519, 32, 16, 'تَتَجَافٰى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفاً وَطَمَعاًۘ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ', 'Tetecafa cunubuhum anil medacıi yed\'une rabbehum havfen ve tamaan ve mimma razaknahum yunfikun.', 'Onlar,  yataklarından kalkarak[1] korku ve ümit içinde Rabblerine dua ederler. Kendilerine verdiğimiz rızıklardan infak[2] ederler.', 'تتجافي جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقنهم ينفقون'),
(3520, 32, 17, 'فَلَا تَعْلَمُ نَفْسٌ مَٓا اُخْفِيَ لَهُمْ مِنْ قُرَّةِ اَعْيُنٍۚ جَزَٓاءً بِمَا كَانُوا يَعْمَلُونَ', 'Fe la ta\'lemu nefsun ma uhfiye lehum min kurreti a\'yun, cezaen bi ma kanu ya\'melun.', 'Hiç kimse,  yaptıkları iyi şeylerin karşılığı olarak,  kendisini ne tür bir mutluluğun beklediğini bilmez.', 'فلا تعلم نفس ما اخفي لهم من قرة اعين جزا بما كانوا يعملون'),
(3521, 32, 18, 'اَفَمَنْ كَانَ مُؤْمِناً كَمَنْ كَانَ فَاسِقاًۜ لَا يَسْتَوُ۫نَ', 'E fe men kane mu\'minen kemen kane fasika, la yestevun.', 'Öyleyse,  mü\'min kimse \"fasık\"[1] olan kimse gibi midir? Elbette bunlar bir olmazlar.', 'افمن كان مومنا كمن كان فاسقا لا يستون'),
(3522, 32, 19, 'اَمَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ جَنَّاتُ الْمَأْوٰىۘ نُزُلاً بِمَا كَانُوا يَعْمَلُونَ', 'Emmellezine amenu ve amilus salihati fe lehum cennatul me\'va nuzulen bi ma kanu ya\'melun.', 'İman eden ve salihatı yapanlar,  işte onlar için,  yapmış olduklarından dolayı konaklama yeri olarak Me\'va Cennetleri var.', 'اما الذين امنوا وعملوا الصلحت فلهم جنت الماوي نزلا بما كانوا يعملون'),
(3523, 32, 20, 'وَاَمَّا الَّذ۪ينَ فَسَقُوا فَمَأْوٰيهُمُ النَّارُۜ  كُلَّمَٓا اَرَادُٓوا اَنْ يَخْرُجُوا مِنْهَٓا اُع۪يدُوا ف۪يهَا وَق۪يلَ لَهُمْ ذُوقُوا عَذَابَ النَّارِ الَّذ۪ي كُنْتُمْ بِه۪ تُكَذِّبُونَ', 'Ve emmellezine feseku fe me\'vahumun nar, kulle ma eradu en yahrucu minha uidu fiha, ve kile lehum zuku azaben narillezi kuntum bihi tukezzibun.', 'Fasıklara gelince,  onların barınağı ateştir. Her çıkmak istediklerinde,  oraya yeniden iade edilirler. Ve onlara: \"Yalanladığınız ateşin azabını tadın!\" denir.', 'واما الذين فسقوا فماويهم النار كلما ارادوا ان يخرجوا منها اعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون'),
(3524, 32, 21, 'وَلَنُذ۪يقَنَّهُمْ مِنَ الْعَذَابِ الْاَدْنٰى دُونَ الْعَذَابِ الْاَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve le nuzikannehum minel azabil edna dunel azabil ekberi leallehum yerciun.', 'Onlara,  büyük azaptan[1] önce,  daha yakın[2] olan azaptan tattıracağız. Belki dönerler.[3]', 'ولنذيقنهم من العذاب الادني دون العذاب الاكبر لعلهم يرجعون'),
(3525, 32, 22, 'وَمَنْ اَظْلَمُ مِمَّنْ ذُكِّرَ بِاٰيَاتِ رَبِّه۪ ثُمَّ اَعْرَضَ عَنْهَاۜ اِنَّا مِنَ الْمُجْرِم۪ينَ مُنْتَقِمُونَ۟', 'Ve men azlemu mimmen zukkire bi ayati rabbihi summe a\'rada anha, inna minel mucrimine muntekimun.', 'Rabb\'inin ayetleri ile öğütlendiği halde,  ondan yüz çeviren kimseden daha zalim kim vardır? Kuşkusuz Biz,  mücrimlere hak ettikleri cezayı vereceğiz.', 'ومن اظلم ممن ذكر بايت ربه ثم اعرض عنها انا من المجرمين منتقمون'),
(3526, 32, 23, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ فَلَا تَكُنْ ف۪ي مِرْيَةٍ مِنْ لِقَٓائِه۪ وَجَعَلْنَاهُ هُدًى لِبَن۪ٓي اِسْرَٓائ۪لَۚ', 'Ve lekad ateyna musel kitabe fe la tekun fi miryetin min likaihi ve cealnahu huden li beni israil.', 'Ant olsun ki Musa\'ya Kitap verdik. Sakın ona kavuşmaktan[1] kuşku içinde olma. Onu[2] İsrailoğulları için yol gösterici yaptık.', 'ولقد اتينا موسي الكتب فلا تكن في مرية من لقايه وجعلنه هدي لبني اسريل'),
(3527, 32, 24, 'وَجَعَلْنَا مِنْهُمْ اَئِمَّةً يَهْدُونَ بِاَمْرِنَا لَمَّا صَبَرُواۜ وَكَانُوا بِاٰيَاتِنَا يُوقِنُونَ', 'Ve cealna minhum eimmeten yehdune bi emrina lemma saberu ve kanu bi ayatina yukınun.', 'Sabrettikleri ve ayetlerimize tam bir bağlılık gösterdikleri için,  onlardan buyruğumuzla doğru yola ileten önderler çıkardık.', 'وجعلنا منهم ايمة يهدون بامرنا لما صبروا وكانوا بايتنا يوقنون'),
(3528, 32, 25, 'اِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'İnne rabbeke huve yafsilu beynehum yevmel kıyameti fima kanu fihi yahtelifun.', 'Senin Rabbin; Kıyamet Günü,  anlaşmazlığa düştükleri şeylerde onların arasını ayırır.[1]', 'ان ربك هو يفصل بينهم يوم القيمة فيما كانوا فيه يختلفون'),
(3529, 32, 26, 'اَوَلَمْ يَهْدِ لَهُمْ كَمْ اَهْلَكْنَا مِنْ قَبْلِهِمْ مِنَ الْقُرُونِ يَمْشُونَ ف۪ي مَسَاكِنِهِمْۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍۜ اَفَلَا يَسْمَعُونَ', 'E ve lem yehdi lehum kem ehlekna min kablihim minel kuruni yemşune fi mesakinihim, inne fi zalike le ayat, e fe la yesmeun.', 'Yaşadıkları yerlerde,  daha önce gezip dolaşmış olan nice nesilleri yok etmiş olmamız,  onları doğru yola iletmeye yetmedi mi? Kuşkusuz bunda nice ayetler[1] vardır. Hala söz dinlemeyecekler mi?', 'اولم يهد لهم كم اهلكنا من قبلهم من القرون يمشون في مسكنهم ان في ذلك لايت افلا يسمعون'),
(3530, 32, 27, 'اَوَلَمْ يَرَوْا اَنَّا نَسُوقُ الْمَٓاءَ اِلَى الْاَرْضِ الْجُرُزِ فَنُخْرِجُ بِه۪ زَرْعاً تَأْكُلُ مِنْهُ اَنْعَامُهُمْ وَاَنْفُسُهُمْۜ اَفَلَا يُبْصِرُونَ', 'E ve lem yerev enna nesukul mae ilel ardıl curuzi fe nuhricu bihi zar\'an te\'kulu minhu en\'amuhum ve enfusuhum e fe la yubsirun.', 'Çorak araziye suyu sevk edip,  onunla hayvanlarının ve kendilerinin yedikleri bitkileri çıkardığımızı görmüyorlar mı? Bundan ibret almaları gerekmez mi?', 'اولم يروا انا نسوق الما الي الارض الجرز فنخرج به زرعا تاكل منه انعمهم وانفسهم افلا يبصرون'),
(3531, 32, 28, 'وَيَقُولُونَ مَتٰى هٰذَا الْفَتْحُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel fethu in kuntum sadikin.', '\"Eğer doğru kimselerseniz,  Bu fetih[1] ne zaman?\" diyorlar.', 'ويقولون متي هذا الفتح ان كنتم صدقين'),
(3532, 32, 29, 'قُلْ يَوْمَ الْفَتْحِ لَا يَنْفَعُ الَّذ۪ينَ كَفَرُٓوا ا۪يمَانُهُمْ وَلَا هُمْ يُنْظَرُونَ', 'Kul yevmel fethi la yenfeullezine keferu imanuhum ve la hum yunzarun.', 'De ki: \"Kafirlerin[1] fetih günü[2] inanmaları kendilerine bir yarar sağlamaz. Ve onlara süre de tanınmaz.\"', 'قل يوم الفتح لا ينفع الذين كفروا ايمنهم ولا هم ينظرون'),
(3533, 32, 30, 'فَاَعْرِضْ عَنْهُمْ وَانْتَظِرْ اِنَّهُمْ مُنْتَظِرُونَ', 'Fe a\'rıd anhum ventezır innehum muntezırun.', 'Artık onları kendi hallerine bırak ve olacakları bekle. Doğrusu onlar da bekleyenlerdir.', 'فاعرض عنهم وانتظر انهم منتظرون'),
(3534, 33, 1, 'يَٓا اَيُّهَا النَّبِيُّ اتَّقِ اللّٰهَ وَلَا تُطِعِ الْكَافِر۪ينَ وَالْمُنَافِق۪ينَۜ اِنَّ اللّٰهَ كَانَ عَل۪يماً حَك۪يماًۙ', 'Ya eyyuhen nebiyyuttekillahe ve la tutıil kafirine vel munafikin, innallahe kane alimen hakima.', 'Ey Nebi! Allah\'a takvalı ol.[1] Kafirlere ve münafıklara uyma.[2] Kuşkusuz Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'يايها النبي اتق الله ولا تطع الكفرين والمنفقين ان الله كان عليما حكيما'),
(3535, 33, 2, 'وَاتَّبِعْ مَا يُوحٰٓى اِلَيْكَ مِنْ رَبِّكَۜ اِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُونَ خَب۪يراًۙ', 'Vettebi\' ma yuha ileyke min rabbik, innallahe kane bima ta\'melune habira.', 'Rabbinden sana vahyedilen neyse yalnızca ona uy. Kuşkusuz Allah,  yaptığınız şeylerden haberdardır.', 'واتبع ما يوحي اليك من ربك ان الله كان بما تعملون خبيرا'),
(3536, 33, 3, 'وَتَوَكَّلْ عَلَى اللّٰهِۜ وَكَفٰى بِاللّٰهِ وَك۪يلاً', 'Ve tevekkel alallah ve kefa billahi vekila.', 'Allah\'a tevekkül[1] et. Vekil[2] olarak Allah yeter.', 'وتوكل علي الله وكفي بالله وكيلا'),
(3537, 33, 4, 'مَا جَعَلَ اللّٰهُ لِرَجُلٍ مِنْ قَلْبَيْنِ ف۪ي جَوْفِه۪ۚ وَمَا جَعَلَ اَزْوَاجَكُمُ الّٰٓئ۪ تُظَاهِرُونَ مِنْهُنَّ اُمَّهَاتِكُمْۚ وَمَا جَعَلَ اَدْعِيَٓاءَكُمْ اَبْنَٓاءَكُمْۜ ذٰلِكُمْ قَوْلُكُمْ بِاَفْوَاهِكُمْۜ وَاللّٰهُ يَقُولُ الْحَقَّ وَهُوَ يَهْدِي السَّب۪يلَ', 'Ma cealallahu li raculin min kalbeyni fi cevfih, ve ma ceale ezvacekumullai tuzahırune min hunne ummehatikum, ve ma ceale ed\'ıyaekum ebnaekum, zalikum kavlukum bi efvahikum, vallahu yekulul hakka ve huve yehdis sebil.', 'Allah,  hiç kimsenin bedenine iki kalp yerleştirmedi. Zihar[1] yaptığınız eşlerinizi,  size anne yapmadı. Ve himayeniz altına aldıklarınızı[2] öz evladınız kılmadı. Bunlar sizin söylediğiniz boş sözlerdir. Allah gerçeği söyler. Ve doğru yola O iletir.', 'ما جعل الله لرجل من قلبين في جوفه وما جعل ازوجكم الي تظهرون منهن امهتكم وما جعل ادعياكم ابناكم ذلكم قولكم بافوهكم والله يقول الحق وهو يهدي السبيل'),
(3538, 33, 5, 'اُدْعُوهُمْ لِاٰبَٓائِهِمْ هُوَ اَقْسَطُ عِنْدَ اللّٰهِۚ فَاِنْ لَمْ تَعْلَمُٓوا اٰبَٓاءَهُمْ فَاِخْوَانُكُمْ فِي الدّ۪ينِ وَمَوَال۪يكُمْۜ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ ف۪يمَٓا اَخْطَأْتُمْ بِه۪ۙ وَلٰكِنْ مَا تَعَمَّدَتْ قُلُوبُكُمْۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'Ud\'uhum li abaihim huve aksatu indallah, fe in lem ta\'lemu abaehum fe ıhvanukum fid dini ve mevalikum, ve leyse aleykum cunahun fima ahta\'tum bihi ve lakin ma taammedet kulubukum, ve kanallahu gafuren rahima.', 'Onları[1] babalarına nispetle çağırın.[2] Bu Allah\'ın yanında daha hakkaniyetlidir. Eğer babalarını bilmiyorsanız,  artık onlar dinde kardeşleriniz ve sorumluluklarını üstlendiğiniz kimselerdir. Bilinçli olarak yaptığınız şeyler dışında,  yanlışlıkla yaptıklarınızda sizin için bir günah yoktur. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ادعوهم لابايهم هو اقسط عند الله فان لم تعلموا اباهم فاخونكم في الدين وموليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما'),
(3539, 33, 6, 'اَلنَّبِيُّ اَوْلٰى بِالْمُؤْمِن۪ينَ مِنْ اَنْفُسِهِمْ وَاَزْوَاجُهُٓ اُمَّهَاتُهُمْۜ وَاُو۬لُوا الْاَرْحَامِ بَعْضُهُمْ اَوْلٰى بِبَعْضٍ ف۪ي كِتَابِ اللّٰهِ مِنَ الْمُؤْمِن۪ينَ وَالْمُهَاجِر۪ينَ اِلَّٓا اَنْ تَفْعَلُٓوا اِلٰٓى اَوْلِيَٓائِكُمْ مَعْرُوفاًۜ كَانَ ذٰلِكَ فِي الْكِتَابِ مَسْطُوراً', 'En nebiyyu evla bil mu\'minine min enfusihim ve ezvacuhu ummehatuhum, ve ulul erhami ba\'duhum evla bi ba\'dın fi kitabillahi minel mu\'minine vel muhacirine illa en tef\'alu ila evliyaikum ma\'rufa, kane zalike fil kitabi mestura.', 'Nebi,  inananlar için kendi canlarından daha yakındır. O\'nun eşleri onların anneleridir. Aralarında aile bağı olanlar; Allah\'ın Kitap\'ına göre birbirlerine,  diğer mü\'minlerden[1] ve muhacirlerden[2] daha yakındırlar[3]. Ancak velilerinize[4] yapacağınız iyilik hariç. İşte bunlar Kitap\'ta[5] kayıtlıdır.', 'النبي اولي بالمومنين من انفسهم وازوجه امهتهم واولوا الارحام بعضهم اولي ببعض في كتب الله من المومنين والمهجرين الا ان تفعلوا الي اوليايكم معروفا كان ذلك في الكتب مسطورا'),
(3540, 33, 7, 'وَاِذْ اَخَذْنَا مِنَ النَّبِيّ۪نَ م۪يثَاقَهُمْ وَمِنْكَ وَمِنْ نُوحٍ وَاِبْرٰه۪يمَ وَمُوسٰى وَع۪يسَى ابْنِ مَرْيَمَۖ وَاَخَذْنَا مِنْهُمْ م۪يثَاقاً غَل۪يظاًۙ', 'Ve iz ehazna minen nebiyyine misakahum ve minke ve min nuhın ve ibrahime ve musa ve isebni meryeme ve ehazna minhum misakan galiza.', 'Hani Biz,  nebilerden kesin söz almıştık. Ve senden,  Nuh\'tan,  İbrahim\'den,  Musa\'dan ve Meryem oğlu Îsa\'dan,  hepsinden sağlam söz aldık.', 'واذ اخذنا من النبين ميثقهم ومنك ومن نوح وابرهيم وموسي وعيسي ابن مريم واخذنا منهم ميثقا غليظا'),
(3541, 33, 8, 'لِيَسْـَٔلَ الصَّادِق۪ينَ عَنْ صِدْقِهِمْۚ وَاَعَدَّ لِلْكَافِر۪ينَ عَذَاباً اَل۪يماً۟', 'Li yes\'eles sadikine an sıdkıhim, ve eadde lil kafirine azaben elima.', 'Ki,  doğru kimselere,  doğruluklarını sorsun.[1] Ve Kafirlere[2] de acı verecek bir azap hazırladı.', 'ليسل الصدقين عن صدقهم واعد للكفرين عذابا اليما'),
(3542, 33, 9, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اذْكُرُوا نِعْمَةَ اللّٰهِ عَلَيْكُمْ اِذْ جَٓاءَتْكُمْ جُنُودٌ فَاَرْسَلْنَا عَلَيْهِمْ ر۪يحاً وَجُنُوداً لَمْ تَرَوْهَاۜ وَكَانَ اللّٰهُ بِمَا تَعْمَلُونَ بَص۪يراًۚ', 'Ya eyyuhellezine amenuzkuru ni\'metallahi aleykum iz caetkum cunudun fe erselna aleyhim rihan ve cunuden lem terevha, ve kanallahu bima ta\'melune basira.', 'Ey iman edenler! Allah\'ın size olan nimetlerini hatırlayın! Hani,  üzerinize ordular gelmişti de Biz,  onların üzerine rüzgar[1] ve göremediğiniz ordular göndermiştik. Allah,  yaptıklarınızı görendir.[2]', 'يايها الذين امنوا اذكروا نعمة الله عليكم اذ جاتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا'),
(3543, 33, 10, 'اِذْ جَٓاؤُ۫كُمْ مِنْ فَوْقِكُمْ وَمِنْ اَسْفَلَ مِنْكُمْ وَاِذْ زَاغَتِ الْاَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللّٰهِ الظُّنُونَا', 'İz caukum min fevkıkum ve min esfele minkum ve iz zagatil ebsaru ve belegatil kulubul hanacire ve tezunnune billahiz zununa.', 'Hani onlar,  alttan ve üstten,  her yönden size saldırmışlardı. Gözler kaymış,  yürekler ağızlara gelmişti. Ve siz,  Allah hakkında zan üzerine zanda bulunuyordunuz.[1]', 'اذ جاوكم من فوقكم ومن اسفل منكم واذ زاغت الابصر وبلغت القلوب الحناجر وتظنون بالله الظنونا'),
(3544, 33, 11, 'هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالاً شَد۪يداً', 'Hunalikebtuliyel mu\'minune ve zulzilu zilzalen şedida.', 'Orada,  inananlar sınava tabi oldular. Şiddetli bir sarsıntı ile sarsıldılar.', 'هنالك ابتلي المومنون وزلزلوا زلزالا شديدا'),
(3545, 33, 12, 'وَاِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ مَا وَعَدَنَا اللّٰهُ وَرَسُولُـهُٓ اِلَّا غُرُوراً', 'Ve iz yekulul munafikune vellezine fi kulubihim maradun ma vaadenallahu ve resuluhu illa gurura.', 'O zaman münafıklar[1] ve kalplerinde hastalık olanlar,  \"Allah ve Resulü bize boş vaatte[2] bulunmuş.\" diyorlardı.', 'واذ يقول المنفقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا'),
(3546, 33, 13, 'وَاِذْ قَالَتْ طَٓائِفَةٌ مِنْهُمْ يَٓا اَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَارْجِعُواۚ وَيَسْتَأْذِنُ فَر۪يقٌ مِنْهُمُ النَّبِيَّ يَقُولُونَ اِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِيَ بِعَوْرَةٍۜ اِنْ يُر۪يدُونَ اِلَّا فِرَاراً', 'Ve iz kalet taifetun minhum ya ehle yesribe la mukame lekum ferciu, ve yeste\'zinu ferikun minhumun nebiyye yekulune inne buyutena avretun ve ma hiye bi avreh, in yuridune illa firara.', 'Onlardan bir topluluk: \"Ey Yesrib[1] halkı,  sizin için burada duracak bir yer yok,  hemen dönün. Yine onlardan bir grup da: \"Evlerimiz gerçekten korumasızdır.\" diyerek Nebiden izin istiyorlardı. Oysaki evleri korumasız değildi. Onlar,  savaştan kaçmak için bahane arıyorlardı.', 'واذ قالت طايفة منهم ياهل يثرب لا مقام لكم فارجعوا ويستذن فريق منهم النبي يقولون ان بيوتنا عورة وما هي بعورة ان يريدون الا فرارا'),
(3547, 33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِمْ مِنْ اَقْطَارِهَا ثُمَّ سُئِلُوا الْفِتْنَةَ لَاٰتَوْهَا وَمَا تَلَبَّثُوا بِهَٓا اِلَّا يَس۪يراً', 'Ve lev duhılet aleyhim min aktariha summe suilul fitnete le atevha ve ma telebbesu biha illa yesira.', 'Fakat onların üzerlerine,  her bir taraftan girilip kuşatılsalardı ve sonra da fitne[1] çıkarmaları istenseydi,  tereddüt etmeksizin bunu hemen yerine getirirlerdi.', 'ولو دخلت عليهم من اقطارها ثم سيلوا الفتنة لاتوها وما تلبثوا بها الا يسيرا'),
(3548, 33, 15, 'وَلَقَدْ كَانُوا عَاهَدُوا اللّٰهَ مِنْ قَبْلُ لَا يُوَلُّونَ الْاَدْبَارَۜ وَكَانَ عَهْدُ اللّٰهِ مَسْؤُ۫لاً', 'Ve lekad kanu ahedullahe min kablu la yuvellunel edbar, ve kane ahdullahi mes\'ula.', 'Oysaki onlar,  daha önce arkalarını dönüp kaçmayacaklarına dair Allah\'a söz vermişlerdi. Allah\'a verilen söz sorumluluktur.', 'ولقد كانوا عهدوا الله من قبل لا يولون الادبر وكان عهد الله مسولا'),
(3549, 33, 16, 'قُلْ لَنْ يَنْفَعَكُمُ الْفِرَارُ اِنْ فَرَرْتُمْ مِنَ الْمَوْتِ اَوِ الْقَتْلِ وَاِذاً لَا تُمَتَّعُونَ اِلَّا قَل۪يلاً', 'Kul len yenfeakumul firaru in ferertum minel mevti evil katli ve izen la tumetteune illa kalila.', 'De ki: \"Eğer ölümden veya öldürülmekten kaçıyorsanız,  kaçmak asla size yarar sağlamaz. Öyle olsa bile çok az faydalanırsınız.\"', 'قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا'),
(3550, 33, 17, 'قُلْ مَنْ ذَا الَّذ۪ي يَعْصِمُكُمْ مِنَ اللّٰهِ اِنْ اَرَادَ بِكُمْ سُٓوءاً اَوْ اَرَادَ بِكُمْ رَحْمَةًۜ وَلَا يَجِدُونَ لَهُمْ مِنْ دُونِ اللّٰهِ وَلِياًّ وَلَا نَص۪يراً', 'Kul men zellezi ya\'sımukum minallahi in erade bikum suen ev eradebikum rahmeh, ve la yecidune lehum min dunillahi veliyyen ve la nasira.', 'De ki: Eğer Allah başınıza bir kötülük getirmeyi dilese sizi kim koruyabilir? Veya size bir rahmet dilese...[1] Onlar,  kendileri için Allah\'tan başka bir veli de bir yardımcı da bulamazlar.', 'قل من ذا الذي يعصمكم من الله ان اراد بكم سوا او اراد بكم رحمة ولا يجدون لهم من دون الله وليا ولا نصيرا'),
(3551, 33, 18, 'قَدْ يَعْلَمُ اللّٰهُ الْمُعَوِّق۪ينَ مِنْكُمْ وَالْقَٓائِل۪ينَ لِاِخْوَانِهِمْ هَلُمَّ اِلَيْنَاۚ وَلَا يَأْتُونَ الْبَأْسَ اِلَّا قَل۪يلاًۙ', 'Kad ya\'lemullahul muavvikine minkum vel kailine li ıhvanihim helumme ileyna, ve la ye\'tunel be\'se illa kalila.', 'Allah,  sizden engel[1] olmaya çalışanları ve kardeşlerine:[2] \"Bize gelin.\"[3] diyenleri kesinlikle biliyor. Onların pek azı hariç savaşa gelmezler.', 'قد يعلم الله المعوقين منكم والقايلين لاخونهم هلم الينا ولا ياتون الباس الا قليلا'),
(3552, 33, 19, 'اَشِحَّةً عَلَيْكُمْۚ فَاِذَا جَٓاءَ الْخَوْفُ رَاَيْتَهُمْ يَنْظُرُونَ اِلَيْكَ تَدُورُ اَعْيُنُهُمْ كَالَّذ۪ي يُغْشٰى عَلَيْهِ مِنَ الْمَوْتِۚ فَاِذَا ذَهَبَ الْخَوْفُ سَلَقُوكُمْ بِاَلْسِنَةٍ حِدَادٍ اَشِحَّةً عَلَى الْخَيْرِۜ اُو۬لٰٓئِكَ لَمْ يُؤْمِنُوا فَاَحْبَطَ اللّٰهُ اَعْمَالَهُمْۜ وَكَانَ ذٰلِكَ عَلَى اللّٰهِ يَس۪يراً', 'Eşıhhaten aleykum fe iza cael havfu reeytehum yenzurune ileyke teduru a\'yunuhum kellezi yugşa aleyhi minel mevt, fe iza zehebel havfu selekukum bi elsinetin hıdadin eşıhhaten alel hayr, ulaike lem yu\'minu fe ahbetallahu a\'malehum, ve kane zalike alallahi yesira.', 'Size karşı çok isteksizdirler. Fakat korku gelince,  ölümden dolayı baygınlık çökmüş kimse gibi gözleri dönmüş olarak sana baktıklarını görürsün. Sonra korkuyu savınca,  hayra[1] karşı kıskançlıkla sivri dilleriyle sizi incitirler. İşte onlar mü\'min değiller. Allah yaptıklarını boşa çıkardı. Bu Allah\'a kolaydır.', 'اشحة عليكم فاذا جا الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشي عليه من الموت فاذا ذهب الخوف سلقوكم بالسنة حداد اشحة علي الخير اوليك لم يومنوا فاحبط الله اعملهم وكان ذلك علي الله يسيرا'),
(3553, 33, 20, 'يَحْسَبُونَ الْاَحْزَابَ لَمْ يَذْهَبُواۚ وَاِنْ يَأْتِ الْاَحْزَابُ يَوَدُّوا لَوْ اَنَّهُمْ بَادُونَ فِي الْاَعْرَابِ يَسْـَٔلُونَ عَنْ اَنْبَٓائِكُمْۜ وَلَوْ كَانُوا ف۪يكُمْ مَا قَاتَلُٓوا اِلَّا قَل۪يلاً۟', 'Yahsebunel ahzabe lem yezhebu, ve in ye\'til ahzabu yeveddu lev ennehum badune fil a\'rabi yes\'elune an enbaikum, ve lev kanu fikum ma katelu illa kalila.', 'Onlar,  düşman birliklerinin gitmediğini sanıyorlardı. Eğer birlikler gelseler[1],  çölde yaşayan Arapların arasına karışıp,  ne halde bulunduğunuzu sormak isterler[2]. Eğer sizin aranızda olsalardı,  pek azı hariç,  savaşmazlardı.', 'يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسلون عن انبايكم ولو كانوا فيكم ما قتلوا الا قليلا'),
(3554, 33, 21, 'لَقَدْ كَانَ لَكُمْ ف۪ي رَسُولِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَث۪يراًۜ', 'Lekad kane lekum fi resulillahi usvetun hasenetun limen kane yercullahe vel yevmel ahıre ve zekerallahe kesira.', 'Ant olsun ki,  sizden Allah\'a ve Ahiret Günü\'ne kavuşmayı uman ve Allah\'ı çokça zikredenler[1] için,  Allah\'ın Resul\'ünde iyi bir örnek vardır.', 'لقد كان لكم في رسول الله اسوة حسنة لمن كان يرجوا الله واليوم الاخر وذكر الله كثيرا'),
(3555, 33, 22, 'وَلَمَّا رَاَ الْمُؤْمِنُونَ الْاَحْزَابَۙ قَالُوا هٰذَا مَا وَعَدَنَا اللّٰهُ وَرَسُولُهُ وَصَدَقَ اللّٰهُ وَرَسُولُهُۘ وَمَا زَادَهُمْ اِلَّٓا ا۪يمَاناً وَتَسْل۪يماًۜ', 'Ve lemma real mu\'minunel ahzabe kalu haza ma vaadenallahu ve resuluhu ve sadakallahu ve resuluhu ve ma zadehum illa imanen ve teslima.', 'Mü\'minler,  düşman birliklerini gördükleri zaman: \"İşte bu,  Allah\'ın ve Resul\'ünün bize söz verdiği şeydir. Allah ve O\'nun Resul\'ü doğru söyledi.\" Bu,  onların yalnızca iman ve teslimiyetlerini arttırdı.', 'ولما را المومنون الاحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم الا ايمنا وتسليما'),
(3556, 33, 23, 'مِنَ الْمُؤْمِن۪ينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللّٰهَ عَلَيْهِۚ فَمِنْهُمْ مَنْ قَضٰى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُۘ وَمَا بَدَّلُوا تَبْد۪يلاًۙ', 'Minel mu\'minine ricalun sadaku ma ahedullahe aleyh, fe minhum men kada nahbehu ve minhum men yentezıru ve ma beddelu tebdila.', 'Mü\'minlerden öyle erler[1] var ki; Allah\'a,  üzerine söz verdikleri şeylere bağlılık gösterdiler. Böylece onlardan bir kısmı verdiği sözü yerine getirdi,  bir kısmı da beklemektedir.[2] Verdikleri sözden asla dönmediler.', 'من المومنين رجال صدقوا ما عهدوا الله عليه فمنهم من قضي نحبه ومنهم من ينتظر وما بدلوا تبديلا'),
(3557, 33, 24, 'لِيَجْزِيَ اللّٰهُ الصَّادِق۪ينَ بِصِدْقِهِمْ وَيُعَذِّبَ الْمُنَافِق۪ينَ اِنْ شَٓاءَ اَوْ يَتُوبَ عَلَيْهِمْۜ اِنَّ اللّٰهَ كَانَ غَفُوراً رَح۪يماًۚ', 'Li yecziyallahus sadıkine bi sıdkıhım ve yuazzibel munafıkine in şae ev yetube aleyhim, innallahe kane gafuren rahima.', 'Allah,  doğru kimseleri,  doğruluklarından dolayı ödüllendirecek,  münafıkları,  dilerse cezalandıracak veya tevbelerini kabul edecektir. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ليجزي الله الصدقين بصدقهم ويعذب المنفقين ان شا او يتوب عليهم ان الله كان غفورا رحيما'),
(3558, 33, 25, 'وَرَدَّ اللّٰهُ الَّذ۪ينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْراًۜ وَكَفَى اللّٰهُ الْمُؤْمِن۪ينَ الْقِتَالَۜ وَكَانَ اللّٰهُ قَوِياًّ عَز۪يزاًۚ', 'Ve reddallahullezine keferu bi gayzıhim lem yenalu hayra, ve kefallahul mu\'mininel kıtal, ve kanallahu kaviyyen aziza.', 'Kafirleri bir yarar elde etmeden kinleriyle geri çevirdi. Ve Allah,  Mü\'minlere savaşta yeterli geldi. Allah,  Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'ورد الله الذين كفروا بغيظهم لم ينالوا خيرا وكفي الله المومنين القتال وكان الله قويا عزيزا'),
(3559, 33, 26, 'وَاَنْزَلَ الَّذ۪ينَ ظَاهَرُوهُمْ مِنْ اَهْلِ الْكِتَابِ مِنْ صَيَاص۪يهِمْ وَقَذَفَ ف۪ي قُلُوبِهِمُ الرُّعْبَ فَر۪يقاً تَقْتُلُونَ وَتَأْسِرُونَ فَر۪يقاًۚ', 'Ve enzelellezine zaheruhum min ehlil kitabi min sayasihım ve kazefe fi kulubihimur ru\'be feriykan taktulune ve te\'sirune ferika.', 'Allah,  Kitap Ehli\'nden düşmanlara yardım edenleri kalelerinden indirdi. Ve yüreklerine korku saldı. Bir kısmını öldürüyor,  bir kısmını esir alıyordunuz.', 'وانزل الذين ظهروهم من اهل الكتب من صياصيهم وقذف في قلوبهم الرعب فريقا تقتلون وتاسرون فريقا'),
(3560, 33, 27, 'وَاَوْرَثَكُمْ اَرْضَهُمْ وَدِيَارَهُمْ وَاَمْوَالَهُمْ وَاَرْضاً لَمْ تَطَؤُ۫هَاۜ وَكَانَ اللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يراً۟', 'Ve evresekum ardahum ve diyarehum ve emvalehum ve ardan lem tetauha, ve kanallahu ala kulli şey\'in kadira.', 'Sizi,  onların yerlerine,  yurtlarına,  mallarına ve hiç ayak basmadığınız yerlere mirasçı yaptı. Allah,  Her Şeye Güç Yetiren\'dir.[1]', 'واورثكم ارضهم وديرهم وامولهم وارضا لم تطوها وكان الله علي كل شي قديرا'),
(3561, 33, 28, 'يَٓا اَيُّهَا النَّبِيُّ قُلْ لِاَزْوَاجِكَ اِنْ كُنْتُنَّ تُرِدْنَ الْحَيٰوةَ الدُّنْيَا وَز۪ينَتَهَا فَتَعَالَيْنَ اُمَتِّعْكُنَّ وَاُسَرِّحْكُنَّ سَرَاحاً جَم۪يلاً', 'Ya eyyuhen nebiyyu kul li ezvacike in kuntunne turidnel hayated dunya ve ziyneteha fe tealeyne umetti\'kunne ve userrihkunne serahan cemila.', 'Ey Nebi! Eşlerine de ki: \"Eğer dünya hayatını ve onun ziynetini istiyorsanız,  gelin sizi yararlandırayım.[1] Ve sizi güzellikle boşayayım.\"', 'يايها النبي قل لازوجك ان كنتن تردن الحيوة الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا'),
(3562, 33, 29, 'وَاِنْ كُنْتُنَّ تُرِدْنَ اللّٰهَ وَرَسُولَهُ وَالدَّارَ الْاٰخِرَةَ فَاِنَّ اللّٰهَ اَعَدَّ لِلْمُحْسِنَاتِ مِنْكُنَّ اَجْراً عَظ۪يماً', 'Ve in kuntunne turidnallahe ve resulehu veddarel\'ahırete fe innallahe eadde lil muhsinati minkunne ecren azima.', '\"Eğer Allah ve Resul\'ünü ve Ahiret Yurdu\'nu istiyorsanız,  kuşkusuz Allah,  sizden Muhsin[1] olan kadınlar için büyük bir ecir[2] hazırlamıştır.\"', 'وان كنتن تردن الله ورسوله والدار الاخرة فان الله اعد للمحسنت منكن اجرا عظيما'),
(3563, 33, 30, 'يَا نِسَٓاءَ النَّبِيِّ مَنْ يَأْتِ مِنْكُنَّ بِفَاحِشَةٍ مُبَيِّنَةٍ يُضَاعَفْ لَهَا الْعَذَابُ ضِعْفَيْنِۜ وَكَانَ ذٰلِكَ عَلَى اللّٰهِ يَس۪يراً', 'Ya nisaen nebiyyi men ye\'ti min kunne bi fahışetin mubeyyinetin yuda\'af lehel\'azabu dı\'feyn, ve kane zalike alallahi yesira.', 'Ey Nebi\'nin hanımları! Sizden kim açık bir fuhuş[1] yaparsa,  onun azabı iki kat arttırılır. Ve bu Allah\'a göre pek kolaydır.', 'ينسا النبي من يات منكن بفحشة مبينة يضعف لها العذاب ضعفين وكان ذلك علي الله يسيرا'),
(3564, 33, 31, 'وَمَنْ يَقْنُتْ مِنْكُنَّ لِلّٰهِ وَرَسُولِه۪ وَتَعْمَلْ صَالِحاً نُؤْتِهَٓا اَجْرَهَا مَرَّتَيْنِۙ وَاَعْتَدْنَا لَهَا رِزْقاً كَر۪يماً', 'Ve men yaknut min kunne lillahi ve resulihi ve ta\'mel salihan nu\'tiha ecreha merreteyni ve a\'tedna leha rızkan kerima.', 'Ve sizden kim Allah ve Resul\'üne[1] içtenlikle uyar ve salih[2] olanı yaparsa ona da iki kat ödül veririz. Ayrıca ona cömertçe bir rızık hazırlamışızdır.', 'ومن يقنت منكن لله ورسوله وتعمل صلحا نوتها اجرها مرتين واعتدنا لها رزقا كريما'),
(3565, 33, 32, 'يَا نِسَٓاءَ النَّبِيِّ لَسْتُنَّ  كَاَحَدٍ مِنَ النِّسَٓاءِ اِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذ۪ي ف۪ي قَلْبِه۪ مَرَضٌ وَقُلْنَ قَوْلاً مَعْرُوفاًۚ', 'Ya nisaen nebiyyi lestunne ke ehadin minen nisai inittekaytunne fe la tahda\'ne bil kavli fe yatmaallezi fi kalbihi maradun ve kulne kavlen ma\'rufa.', 'Ey Nebi\'nin hanımları! Siz diğer kadınlardan biri değilsiniz. Eğer takvalıysanız,  yabancı erkeklerle edalı[1] bir üslupla konuşmayın. Zira kalbinde kötülük olan bir kimse buna yanlış anlam yükleyebilir. Sözün maruf[2] olanını söyleyin.', 'ينسا النبي لستن كاحد من النسا ان اتقيتن فلا تخضعن بالقول فيطمع الذي في قلبه مرض وقلن قولا معروفا'),
(3566, 33, 33, 'وَقَرْنَ ف۪ي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْاُو۫لٰى وَاَقِمْنَ الصَّلٰوةَ وَاٰت۪ينَ الزَّكٰوةَ وَاَطِعْنَ اللّٰهَ وَرَسُولَهُۜ اِنَّمَا يُر۪يدُ اللّٰهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ اَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْه۪يراًۚ', 'Ve karne fi buyutikunne ve la teberrecne teberrucel cahiliyyetil ula ve ekımnes salate ve atinez zekate ve atı\'nallahe ve resuleh, innema yuridullahu li yuzhibe ankumur ricse ehlel beyti ve yutahhirekum tathira.', 'Evlerinizde vakarlı olun.[1] Cahiliye dönemindeki gösteriş gibi gösteriş yapmayın. Salatı[2] ikame edin,  zekatı[2] yapın. Allah\'a ve Resul\'üne itaat edin.[3] Ey Nebi\'nin ailesi! Allah sizden her türlü kirliliği giderip sizi tertemiz kılmak istiyor.', 'وقرن في بيوتكن ولا تبرجن تبرج الجهلية الاولي واقمن الصلوة واتين الزكوة واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا'),
(3567, 33, 34, 'وَاذْكُرْنَ مَا يُتْلٰى ف۪ي بُيُوتِكُنَّ مِنْ اٰيَاتِ اللّٰهِ وَالْحِكْمَةِۜ اِنَّ اللّٰهَ كَانَ لَط۪يفاً خَب۪يراً۟', 'Vezkurne ma yutla fi buyutikunne min ayatillahi vel hikmeh, innallahe kane latifen habira.', 'Evlerinizde okunmakta olan Allah\'ın ayetlerini ve hikmetini[1] aklınızdan çıkarmayın. Kuşkusuz Allah,  Bütün Ayrıntıları Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'واذكرن ما يتلي في بيوتكن من ايت الله والحكمة ان الله كان لطيفا خبيرا'),
(3568, 33, 35, 'اِنَّ الْمُسْلِم۪ينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ وَالْقَانِت۪ينَ وَالْقَانِتَاتِ وَالصَّادِق۪ينَ وَالصَّادِقَاتِ وَالصَّابِر۪ينَ وَالصَّابِرَاتِ وَالْخَاشِع۪ينَ وَالْخَاشِعَاتِ وَالْمُتَصَدِّق۪ينَ وَالْمُتَصَدِّقَاتِ وَالصَّٓائِم۪ينَ وَالصَّٓائِمَاتِ وَالْحَافِظ۪ينَ فُرُوجَهُمْ وَالْحَافِظَاتِ وَالذَّاكِر۪ينَ اللّٰهَ كَث۪يراً وَالذَّاكِرَاتِ اَعَدَّ اللّٰهُ لَهُمْ مَغْفِرَةً وَاَجْراً عَظ۪يماً', 'İnnel muslimine vel muslimati vel mu\'minine vel mu\'minati vel kanitine vel kanitati ves sadikine ves sadikati ves sabirine ves sabirati vel haşiine vel haşiati vel mutesaddikine vel mutesaddikati ves saimine ves saimati vel hafızine furucehum vel hafızati vez zakirinallahe kesiren vez zakirati eaddallahu lehum magfireten ve ecren azima.', 'Müslüman erkekler ve Müslüman kadınlar,  mü\'min erkekler ve mü\'min kadınlar,  adanmış erkekler ve adanmış kadınlar, [1] sadık erkekler ve sadık kadınlar,  sabreden erkekler ve sabreden kadınlar,  huşulu[2] erkekler ve huşulu kadınlar,  sadaka veren erkekler ve sadaka veren kadınlar,  saim olan[3] erkekler ve saim olan[3] kadınlar,  ırzlarını koruyan erkekler ve ırzlarını koruyan kadınlar ve Allah\'ı çok zikreden erkekler ve Allah\'ı çok zikreden kadınlar[4]; Allah,  onlar için bağışlanma ve büyük bir ödül hazırlamıştır.', 'ان المسلمين والمسلمت والمومنين والمومنت والقنتين والقنتت والصدقين والصدقت والصبرين والصبرت والخشعين والخشعت والمتصدقين والمتصدقت والصيمين والصيمت والحفظين فروجهم والحفظت والذكرين الله كثيرا والذكرت اعد الله لهم مغفرة واجرا عظيما'),
(3569, 33, 36, 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ اِذَا قَضَى اللّٰهُ وَرَسُولُهُٓ  اَمْراً اَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ اَمْرِهِمْۜ وَمَنْ يَعْصِ اللّٰهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلَالاً مُب۪يناً', 'Ve ma kane li mu\'minin ve la mu\'minetin iza kadallahu ve resuluhu emren en yekune lehumul hıyeretu min emrihim, ve men ya\'sıllahe ve resulehu fe kad dalle dalalen mubina.', 'Allah ve Resul\'ü bir konuda karar verdiği zaman[1],  hiçbir inanan erkek ve inanan kadın için,  o konuda tercih hakkı yoktur. Kim Allah ve Resul\'üne asilik ederse o,  açık bir sapkınlıkla sapmış olur.', 'وما كان لمومن ولا مومنة اذا قضي الله ورسوله امرا ان يكون لهم الخيرة من امرهم ومن يعص الله ورسوله فقد ضل ضللا مبينا'),
(3570, 33, 37, 'وَاِذْ تَقُولُ لِلَّـذ۪ٓي اَنْعَمَ اللّٰهُ عَلَيْهِ وَاَنْعَمْتَ عَلَيْهِ اَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللّٰهَ وَتُخْف۪ي ف۪ي نَفْسِكَ مَا اللّٰهُ مُبْد۪يهِ وَتَخْشَى النَّاسَۚ وَاللّٰهُ اَحَقُّ اَنْ تَخْشٰيهُۜ فَلَمَّا قَضٰى زَيْدٌ مِنْهَا وَطَراً زَوَّجْنَاكَهَا لِكَيْ لَا يَكُونَ عَلَى الْمُؤْمِن۪ينَ حَرَجٌ ف۪ٓي اَزْوَاجِ اَدْعِيَٓائِهِمْ اِذَا قَضَوْا مِنْهُنَّ وَطَراًۜ وَكَانَ اَمْرُ اللّٰهِ مَفْعُولاً', 'Ve iz tekulu lillezi en\'amallahu aleyhi ve en\'amte aleyhi emsik aleyke zevceke vettekıllah ve tuhfi fi nefsike mallahu mubdihi ve tahşen nas, vallahu ehakku en tahşah, fe lemma kada zeydun minha vetaran zevvecna keha likey la yekune alel mu\'minine haracun fi ezvaci ed\'ıyaihim iza kadav min hunne vetara, ve kane emrullahi mef\'ula.', 'Allah\'ın kendisine nimet verdiği ve senin de nimet verdiğin kimseye diyordun ki: \"Eşini yanında tut. Allah\'a karşı takvalı ol.[1] Allah\'ın açığa çıkaracağı şeyi içinde gizliyorsun. İnsanlara huşu[2] duyuyorsun; oysaki huşu duyman gereken Allah\'tır.[3]\" Sonra Zeyd ondan tamamıyla ayrılınca,  Biz onu sana eş yaptık ki böylece himaye edilenlerin[4] boşadıkları kadınlarla evlenmelerinde inananların üzerinde bir güçlük olmasın. İşte Allah\'ın emri böylece yerine gelmiş oldu.', 'واذ تقول للذي انعم الله عليه وانعمت عليه امسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشي الناس والله احق ان تخشيه فلما قضي زيد منها وطرا زوجنكها لكي لا يكون علي المومنين حرج في ازوج ادعيايهم اذا قضوا منهن وطرا وكان امر الله مفعولا'),
(3571, 33, 38, 'مَا كَانَ عَلَى النَّبِيِّ مِنْ حَرَجٍ ف۪يمَا فَرَضَ اللّٰهُ لَهُۜ سُنَّةَ اللّٰهِ فِي الَّذ۪ينَ خَلَوْا مِنْ قَبْلُۜ وَكَانَ اَمْرُ اللّٰهِ قَدَراً مَقْدُوراًۙ', 'Ma kane alen nebiyyi min harecin fima faradallahu leh, sunnetallahi fillezine halev min kabl, ve kane emrullahi kaderen makdura.', 'Nebi,  Allah\'ın farz kılması gereği olarak bir şeyi yapmasından dolayı suçlanamaz. Bu,  daha önceki toplumlarda da geçerli olan Allah\'ın yasasıdır. Allah\'ın emri,  kesinleşmiş bir yazgıdır.', 'ما كان علي النبي من حرج فيما فرض الله له سنة الله في الذين خلوا من قبل وكان امر الله قدرا مقدورا'),
(3572, 33, 39, 'اَلَّذ۪ينَ يُبَلِّغُونَ رِسَالَاتِ اللّٰهِ وَيَخْشَوْنَهُ وَلَا يَخْشَوْنَ اَحَداً اِلَّا اللّٰهَۜ وَكَفٰى بِاللّٰهِ حَس۪يباً', 'Ellezine yubelligune risalatillahi ve yahşevnehu ve la yahşevne ehaden illallah, ve kefa billahi hasiba.', 'Onlar,  Allah\'ın mesajını iletirler ve O\'na huşu[1] duyarlar ve Allah\'tan başka hiç kimseye huşu duymazlar. Allah,  hesap görücü olarak yeter.[2]', 'الذين يبلغون رسلت الله ويخشونه ولا يخشون احدا الا الله وكفي بالله حسيبا'),
(3573, 33, 40, 'مَا كَانَ مُحَمَّدٌ اَبَٓا اَحَدٍ مِنْ رِجَالِكُمْ وَلٰكِنْ رَسُولَ اللّٰهِ وَخَاتَمَ النَّبِيّ۪نَۜ وَكَانَ اللّٰهُ بِكُلِّ شَيْءٍ عَل۪يماً۟', 'Ma kane muhammedun eba ehadin min ricalikum, ve lakin resulallahi ve hatemen nebiyyin, ve kanallahu bi kulli şey\'in alima.', 'Muhammed içinizden hiç birinizin babası değildir; fakat Allah\'ın Resul\'ü[1] ve nebilerin[1] sonuncusudur. Allah,  her şeyi en iyi bilendir.', 'ما كان محمد ابا احد من رجالكم ولكن رسول الله وخاتم النبين وكان الله بكل شي عليما'),
(3574, 33, 41, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اذْكُرُوا اللّٰهَ ذِكْراً كَث۪يراًۙ', 'Ya eyyuhellezine amenuzkurullahe zikren kesira.', 'Ey iman edenler! Çok anışla Allah\'ı anın.', 'يايها الذين امنوا اذكروا الله ذكرا كثيرا'),
(3575, 33, 42, 'وَسَبِّحُوهُ بُكْرَةً وَاَص۪يلاً', 'Ve sebbihuhu bukreten ve asila.', 'O\'nu günün başında sonunda[1] tesbih[2] edin.', 'وسبحوه بكرة واصيلا'),
(3576, 33, 43, 'هُوَ الَّذ۪ي يُصَلّ۪ي عَلَيْكُمْ وَمَلٰٓئِكَتُهُ لِيُخْرِجَكُمْ مِنَ الظُّلُمَاتِ اِلَى النُّورِۜ وَكَانَ بِالْمُؤْمِن۪ينَ رَح۪يماً', 'Huvellezi yusalli aleykum ve melaiketuhu li yuhricekum minez zulumati ilen nur, ve kane bil mu\'minine rahima.', 'Allah ve melekleri,  sizi karanlıklardan aydınlığa çıkarmak için size salat[1] etmektedir. O,  Mü\'minlere karşı çok merhametlidir.', 'هو الذي يصلي عليكم ومليكته ليخرجكم من الظلمت الي النور وكان بالمومنين رحيما'),
(3577, 33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُ سَلَامٌۚ وَاَعَدَّ لَهُمْ اَجْراً كَر۪يماً', 'Tehiyyetuhum yevme yelkavnehu selam, ve eadde lehum ecren kerima.', 'O\'na kavuşacakları gün,  \"selam[1]\" ile karşılanırlar. Onlar için cömertçe ödül hazırlanmıştır.', 'تحيتهم يوم يلقونه سلم واعد لهم اجرا كريما'),
(3578, 33, 45, 'يَٓا اَيُّهَا النَّبِيُّ اِنَّٓا اَرْسَلْنَاكَ شَاهِداً وَمُبَشِّراً وَنَذ۪يراًۙ', 'Ya eyyuhen nebiyyu inna erselnake şahiden ve mubeşşiren ve nezira.', 'Ey Nebi! Biz seni tanık,  haber veren ve uyarıcı olarak gönderdik.', 'يايها النبي انا ارسلنك شهدا ومبشرا ونذيرا'),
(3579, 33, 46, 'وَدَاعِياً اِلَى اللّٰهِ بِـاِذْنِه۪ وَسِرَاجاً مُن۪يراً', 'Ve daiyen ilallahi bi iznihi ve siracen munira.', 'O\'nun izni[1] ile Allah\'a çağıran ve aydınlatan bir kandil[2] olarak.', 'وداعيا الي الله باذنه وسراجا منيرا'),
(3580, 33, 47, 'وَبَشِّرِ الْمُؤْمِن۪ينَ بِاَنَّ لَهُمْ مِنَ اللّٰهِ فَضْلاً كَب۪يراً', 'Ve beşşiril mu\'minine bi enne lehum minallahi fadlen kebira.', 'Mü\'minleri müjdele! Onlar için Allah\'tan büyük bir lütuf vardır.', 'وبشر المومنين بان لهم من الله فضلا كبيرا'),
(3581, 33, 48, 'وَلَا تُطِـعِ الْكَافِر۪ينَ وَالْمُنَافِق۪ينَ وَدَعْ اَذٰيهُمْ وَتَوَكَّلْ عَلَى اللّٰهِۜ وَكَفٰى بِاللّٰهِ وَك۪يلاً', 'Ve la tutııl kafirine vel munafikine veda\'ezahum ve tevekkel alallah, ve kefa billahi vekila.', 'Kafirlere ve münafıklara boyun eğme,  onların baskılarına aldırma. Allah\'a tevekkül[1] et. Vekil[2] olarak Allah yeter.', 'ولا تطع الكفرين والمنفقين ودع اذيهم وتوكل علي الله وكفي بالله وكيلا'),
(3582, 33, 49, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ اَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَاۚ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحاً جَم۪يلاً', 'Ya eyyuhellezine amenu iza nekahtumul mu\'minati summe tallaktumuhunne min kabli en temessuhunne fe ma lekum aleyhinne min iddetin ta\'tedduneha, fe mettiuhunne ve serrihuhunne serahan cemila.', 'Ey iman edenler! Mü\'min kadınlarla evlenip,  sonra onlara dokunmadan boşarsanız,  onların iddet süresince beklemelerini isteme hakkınız yoktur. Böyle bir durumda onları hemen yararlandırın[1] ve güzellikle ayrılın.', 'يايها الذين امنوا اذا نكحتم المومنت ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عدة تعتدونها فمتعوهن وسرحوهن سراحا جميلا'),
(3583, 33, 50, 'يَٓا اَيُّهَا النَّبِيُّ اِنَّٓا اَحْلَلْنَا لَكَ اَزْوَاجَكَ الّٰـت۪ٓي اٰتَيْتَ اُجُورَهُنَّ وَمَا مَلَكَتْ يَم۪ينُكَ مِمَّٓا اَفَٓاءَ اللّٰهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّاتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَالَاتِكَ الّٰت۪ي هَاجَرْنَ مَعَكَۘ وَامْرَاَةً مُؤْمِنَةً اِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ اِنْ اَرَادَ النَّبِيُّ اَنْ يَسْتَنْكِحَهَاۗ خَالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِن۪ينَۜ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ ف۪ٓي اَزْوَاجِهِمْ وَمَا مَلَكَتْ اَيْمَانُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'Ya eyyuhen nebiyyu inna ahlelna leke ezvacekelleti ateyte ucurehunne ve ma meleket yeminuke mimma efaallahu aleyke ve benati ammike ve benati ammatike ve benati halike ve benati halatikellati hacerne meak, vemreeten mu\'mineten in vehebet nefseha lin nebiyyi in eraden nebiyyu en yestenkihaha halisaten leke min dunil mu\'minin, kad alimna ma faradna aleyhim fi ezvacihim ve ma meleket eymanuhum li keyla yekune aleyke harac, ve kanallahu gafuran rahima.', 'Ey Nebi! Biz,  ecirlerini[1] verdiğin eşlerini ve savaşlarda Allah\'ın fey[2] olarak sana verdiği antlaşma yolu ile hak sahibi olduklarını[3],  sana helal kıldık. Seninle birlikte hicret eden amcanın kızları,  halalarının kızları,  dayının kızları,  teyzelerinin kızları ve kendisini Nebiye hibe[4] edip de nebinin de evlenmeyi uygun gördüğü mü\'min kadını -ki bu yalnızca sana özgüdür- sana helal kıldık. Onlara[5] zevceleri ve antlaşma yolu ile hak sahibi oldukları[3] konusunda neyi farz[6] kıldığımızı biliriz. Bu durum senin için bir güçlük olmasın diyedir. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها النبي انا احللنا لك ازوجك التي اتيت اجورهن وما ملكت يمينك مما افا الله عليك وبنات عمك وبنات عمتك وبنات خالك وبنات خلتك التي هاجرن معك وامراة مومنة ان وهبت نفسها للنبي ان اراد النبي ان يستنكحها خالصة لك من دون المومنين قد علمنا ما فرضنا عليهم في ازوجهم وما ملكت ايمنهم لكيلا يكون عليك حرج وكان الله غفورا رحيما'),
(3584, 33, 51, 'تُرْج۪ي مَنْ تَشَٓاءُ مِنْهُنَّ وَتُــْٔـو۪ٓي اِلَيْكَ مَنْ تَشَٓاءُۜ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَۜ  ذٰلِكَ اَدْنٰٓى اَنْ تَقَرَّ اَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَٓا اٰتَيْتَهُنَّ كُلُّهُنَّۜ وَاللّٰهُ يَعْلَمُ مَا ف۪ي قُلُوبِكُمْۜ وَكَانَ اللّٰهُ عَل۪يماً حَل۪يماً', 'Turci men teşau minhunne ve tu\'vi ileyke men teşau, ve menibtegayte mimmen azelte fe la cunaha aleyk, zalike edna en tekarre a\'yunuhunne ve la yahzenne ve yerdayne bima ateytehunne kulluhunn, vallahu ya\'lemu ma fi kulubikum ve kanallahu alimen halima.', 'Onlardan[1] dilediğini ertelersin,  dilediğini yanına alırsın. Bıraktıklarından[1],  istediğini yanına almanda senin için bir sakınca yoktur. En uygun olanı budur. Bu,  onların gözlerinin aydın olması[2] ve hüzünlenmemeleri ve kendilerine verdiğinle hoşnut olmaları için en uygun olanıdır. Allah,  kalplerinizde olanı bilmektedir. Allah,  Her Şeyi Bilen\'dir,  Çok Şefkatli\'dir.', 'ترجي من تشا منهن وتوي اليك من تشا ومن ابتغيت ممن عزلت فلا جناح عليك ذلك ادني ان تقر اعينهن ولا يحزن ويرضين بما اتيتهن كلهن والله يعلم ما في قلوبكم وكان الله عليما حليما');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3585, 33, 52, 'لَا يَحِلُّ لَكَ النِّسَٓاءُ مِنْ بَعْدُ وَلَٓا اَنْ تَبَدَّلَ بِهِنَّ مِنْ اَزْوَاجٍ وَلَوْ اَعْجَبَكَ حُسْنُهُنَّ اِلَّا مَا مَلَكَتْ يَم۪ينُكَۜ وَكَانَ اللّٰهُ عَلٰى كُلِّ شَيْءٍ رَق۪يـباً۟', 'La yahıllu leken nisau min ba\'du ve la en tebeddele bihinne min ezvacin ve lev a\'cebeke husnuhunne illa ma meleket yeminuk, ve kanallahu ala kulli şey\'in rakiba.', 'Bundan böyle başka kadınlarla evlenmen,  eşlerini boşayıp yerine iyi olması hoşuna gitse bile başka kadın alman sana helal olmaz.[1] Ancak antlaşma yolu ile[2] hak sahibi olduğun hariç. Allah,  her şeyi gözetleyip denetleyendir.', 'لا يحل لك النسا من بعد ولا ان تبدل بهن من ازوج ولو اعجبك حسنهن الا ما ملكت يمينك وكان الله علي كل شي رقيبا'),
(3586, 33, 53, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ اِلَّٓا اَنْ يُؤْذَنَ لَكُمْ اِلٰى طَعَامٍ غَيْرَ نَاظِر۪ينَ اِنٰيهُۙ وَلٰكِنْ اِذَا دُع۪يتُمْ فَادْخُلُوا فَاِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلَا مُسْتَأْنِس۪ينَ لِحَد۪يثٍۜ اِنَّ ذٰلِكُمْ كَانَ يُؤْذِي النَّبِيَّ فَيَسْتَحْـي۪ مِنْكُمْۘ وَاللّٰهُ لَا يَسْتَحْـي۪ مِنَ الْحَقِّۜ وَاِذَا سَاَلْتُمُوهُنَّ مَتَاعاً فَسْـَٔلُوهُنَّ مِنْ وَرَٓاءِ حِجَابٍۜ ذٰلِكُمْ اَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّۜ وَمَا كَانَ لَكُمْ اَنْ تُؤْذُوا رَسُولَ اللّٰهِ وَلَٓا اَنْ تَنْكِحُٓوا اَزْوَاجَهُ مِنْ بَعْدِه۪ٓ اَبَداًۜ اِنَّ ذٰلِكُمْ كَانَ عِنْـدَ اللّٰهِ عَظ۪يـماً', 'Ya eyyuhellezine amenu la tedhulu buyuten nebiyyi illa en yu\'zene lekum ila taamin gayre nazırine inahu ve lakin iza duitum fedhulu fe iza taimtum fenteşiru ve la muste\'nisine li hadis, inne zalikum kane yu\'zin nebiyye fe yestahyi minkum vallahu la yestahyi minel hakk, ve iza seeltumuhunne metaan fes\'eluhunne min verai hıcab, zalikum atharu li kulubikum ve kulubihinn, ve ma kane lekum en tu\'zu resulallahi ve la en tenkihu ezvacehu min ba\'dihi ebeda, inne zalikum kane indallahi azima.', 'Ey iman edenler! Nebi\'nin evlerine,  yemeğe izin verilmiş olmasının dışında vakitli vakitsiz izinsiz girmeyin. Ama çağrılmışsanız o başka. Yemeği yiyince de hadise[1] dalıp oyalanmayın,  hemen dağılın. Doğrusu bu haliniz Nebi\'yi rahatsız ediyor,  o sizi kırmamak için bir şey demiyor. Allah ise gerçeği açıklamaktan çekinmez. Onlardan bir şey isteyeceğiniz zaman da hicap[2] arkasından isteyin. Bu sizin kalpleriniz için de onların kalpleri için de daha uygundur. Allah\'ın Resulüne rahatsızlık vermeniz doğru olmaz. Kendisinden sonra eşleriyle asla evlenemezsiniz. Kuşkusuz bu Allah\'ın yanında büyük şeydir.', 'يايها الذين امنوا لا تدخلوا بيوت النبي الا ان يوذن لكم الي طعام غير نظرين انيه ولكن اذا دعيتم فادخلوا فاذا طعمتم فانتشروا ولا مستنسين لحديث ان ذلكم كان يوذي النبي فيستحي منكم والله لا يستحي من الحق واذا سالتموهن متعا فسلوهن من ورا حجاب ذلكم اطهر لقلوبكم وقلوبهن وما كان لكم ان توذوا رسول الله ولا ان تنكحوا ازوجه من بعده ابدا ان ذلكم كان عند الله عظيما'),
(3587, 33, 54, 'اِنْ تُبْدُوا شَيْـٔاً اَوْ تُخْفُوهُ فَاِنَّ اللّٰهَ كَانَ بِكُلِّ شَيْءٍ عَل۪يماً', 'İn tubdu şey\'en ev tuhfuhu fe innallahe kane bi kulli şey\'in alima.', 'Bir şeyi açığa vursanız da gizleseniz de şunu bilin ki; kuşkusuz Allah,  Her Şeyi En İyi Bilen\'dir.', 'ان تبدوا شيا او تخفوه فان الله كان بكل شي عليما'),
(3588, 33, 55, 'لَا جُنَاحَ عَلَيْهِنَّ ف۪ٓي اٰبَٓائِهِنَّ وَلَٓا اَبْنَٓائِهِنَّ وَلَٓا اِخْوَانِهِنَّ وَلَٓا اَبْنَٓاءِ اِخْوَانِهِنَّ وَلَٓا اَبْنَٓاءِ اَخَوَاتِهِنَّ وَلَا نِسَٓائِهِنَّ وَلَا مَا مَلَكَتْ اَيْمَانُهُنَّۚ وَاتَّق۪ينَ اللّٰهَۜ اِنَّ اللّٰهَ كَانَ عَلٰى كُلِّ شَيْءٍ شَه۪يداً', 'La cunaha aleyhinne fi abaihinne ve la ebnaihinne ve la ihvanihinne ve la ebnai ihvanihinne ve la ebnai ehavatihinne ve la nisaihinne ve la ma meleket eymanuhun, vettekinallah, innallahe kane ala kulli şey\'in şehida.', 'Onlara; Babaları,  oğulları,  kardeşleri,  erkek kardeşlerinin oğulları,  kız kardeşlerinin oğulları,  hemcinsleri ve antlaşma ile hak sahibi oldukları[1] ile serbestçe görüşmelerinde bir sakınca yoktur. Allah\'a karşı takva[2] sahibi olun. Kuşkusuz Allah,  Her Şeye Tanık\'tır.', 'لا جناح عليهن في ابايهن ولا ابنايهن ولا اخونهن ولا ابنا اخونهن ولا ابنا اخوتهن ولا نسايهن ولا ما ملكت ايمنهن واتقين الله ان الله كان علي كل شي شهيدا'),
(3589, 33, 56, 'اِنَّ اللّٰهَ وَمَلٰٓئِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّۜ يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْل۪يماً', 'İnnallahe ve melaiketehu yusallune alen nebiyyi, ya eyyuhellezine amenu sallu aleyhi ve sellimu teslima.', 'Kuşkusuz Allah ve melekleri,  Nebi\'ye salat[1] ederler. Ey iman edenler! Siz de O\'na salat edin. Tam bir bağlılıkla selam[2] edin.', 'ان الله ومليكته يصلون علي النبي يايها الذين امنوا صلوا عليه وسلموا تسليما'),
(3590, 33, 57, 'اِنَّ الَّذ۪ينَ يُؤْذُونَ اللّٰهَ وَرَسُولَهُ لَعَنَهُمُ اللّٰهُ فِي الدُّنْيَا وَالْاٰخِرَةِ وَاَعَدَّ لَهُمْ عَذَاباً مُه۪يناً', 'İnnellezine yu\'zunallahe ve resulehu leanehumullahu fid dunya vel ahıreti ve eadde lehum azaben muhina.', 'Allah ve Resul\'üne eziyet edenlere,  Allah,  dünya ve ahirette lanet[1] etti. Ve onlar için alçaltıcı bir azap hazırladı.', 'ان الذين يوذون الله ورسوله لعنهم الله في الدنيا والاخرة واعد لهم عذابا مهينا'),
(3591, 33, 58, 'وَالَّذ۪ينَ يُؤْذُونَ الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ بِغَيْرِ مَا اكْتَسَبُوا فَقَدِ احْتَمَلُوا بُهْتَاناً وَاِثْماً مُب۪يناً۟', 'Vellezine yu\'zunel mu\'minine vel mu\'minati bi gayri mektesebu fe kadihtemelu buhtanen ve ismen mubina.', 'Mü\'min erkeklere ve Mü\'min kadınlara yapmadıkları bir şey nedeniyle eziyet eden kimseler,  bu durumda iftira ve apaçık günah yüklenmiş oldular.', 'والذين يوذون المومنين والمومنت بغير ما اكتسبوا فقد احتملوا بهتنا واثما مبينا'),
(3592, 33, 59, 'يَٓا اَيُّهَا النَّبِيُّ قُلْ لِاَزْوَاجِكَ وَبَنَاتِكَ وَنِسَٓاءِ الْمُؤْمِن۪ينَ يُدْن۪ينَ عَلَيْهِنَّ مِنْ جَلَاب۪يبِهِنَّۜ ذٰلِكَ اَدْنٰٓى اَنْ يُعْرَفْنَ فَلَا يُؤْذَيْنَۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'Ya eyyuhen nebiyyu kul li ezvacike ve benatike ve nisail mu\'minine yudnine aleyhinne min celabibihinn, zalike edna en yu\'refne fe la yu\'zeyn ve kanallahu gafuren rahima.', 'Ey Nebi! Eşlerine,  kızlarına ve Mü\'minlerin kadınlarına söyle,  cilbablarını[1] üzerlerine salsınlar[2]. Bu,  salma onların bilinmeleri[3] ve eziyet edilmemeleri[4] için daha uygundur. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها النبي قل لازوجك وبناتك ونسا المومنين يدنين عليهن من جلبيبهن ذلك ادني ان يعرفن فلا يوذين وكان الله غفورا رحيما'),
(3593, 33, 60, 'لَئِنْ لَمْ يَنْتَهِ الْمُنَافِقُونَ وَالَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ وَالْمُرْجِفُونَ فِي الْمَد۪ينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ ف۪يهَٓا اِلَّا قَل۪يلاًۚۛ', 'Le in lem yentehil munafikune vellezine fi kulubihim maradun vel murcifune fil medineti le nugriyenneke bihim summe la yucaviruneke fiha illa kalila.', 'Eğer,  münafıklar,  kalplerinde hastalık bulunanlar,  şehirde yalan ve kötü haber yayanlar bu davranışlarına son vermezlerse,  ant olsun ki,  seni onlara musallat ederiz de seninle bir arada daha fazla kalamazlar.', 'لين لم ينته المنفقون والذين في قلوبهم مرض والمرجفون في المدينة لنغرينك بهم ثم لا يجاورونك فيها الا قليلا'),
(3594, 33, 61, 'مَلْعُون۪ينَۚۛ اَيْنَ مَا ثُقِفُٓوا اُخِذُوا وَقُتِّلُوا تَقْت۪يلاً', 'Mel\'unin, eyne ma sukıfu uhızu ve kuttılu taktila.', 'Lanetlenmiş kimseler olarak,  nerede rastlansalar yakalanıp,  kıyasıya öldürülürler.[1]', 'ملعونين اينما ثقفوا اخذوا وقتلوا تقتيلا'),
(3595, 33, 62, 'سُنَّةَ اللّٰهِ فِي الَّذ۪ينَ خَلَوْا مِنْ قَبْلُۚ وَلَنْ تَجِدَ لِسُنَّةِ اللّٰهِ تَبْد۪يلاً', 'Sunnetallahi fillezine halev min kabl, ve len tecide li sunnetillahi tebdila.', 'Gelmiş geçmiş olanların tamamı[1] hakkında Allah\'ın sünneti[2] budur. Ve Allah\'ın sünnetinde asla bir değişiklik bulamazsın.', 'سنة الله في الذين خلوا من قبل ولن تجد لسنة الله تبديلا'),
(3596, 33, 63, 'يَسْـَٔلُكَ النَّاسُ عَنِ السَّاعَةِۜ قُلْ اِنَّمَا عِلْمُهَا عِنْدَ اللّٰهِۜ وَمَا يُدْر۪يكَ لَعَلَّ السَّاعَةَ تَكُونُ قَر۪يباً', 'Yes\'eluken nasu anis saah, kul innema ilmuha indallah, ve ma yudrike lealles saate tekunu kariba.', 'İnsanlar sana Sa\'at\'ten[1] soruyorlar. De ki: \"Onun bilgisi yalnızca Allah\'ın yanındadır. Ne bilirsin belki de o Sa\'at yaklaşmıştır.', 'يسلك الناس عن الساعة قل انما علمها عند الله وما يدريك لعل الساعة تكون قريبا'),
(3597, 33, 64, 'اِنَّ اللّٰهَ لَعَنَ الْكَافِر۪ينَ وَاَعَدَّ لَهُمْ سَع۪يراًۙ', 'İnnallahe leanel kafirine ve eadde lehum saira.', 'Allah,  Kafirlere lanet etmiştir.[1] Onlar için alevli ateşi hazırlamıştır.', 'ان الله لعن الكفرين واعد لهم سعيرا'),
(3598, 33, 65, 'خَالِد۪ينَ ف۪يهَٓا اَبَداًۚ لَا يَجِدُونَ وَلِياًّ وَلَا نَص۪يراًۚ', 'Halidine fiha ebeda, la yecidune veliyyen ve la nasira.', 'Orada sürekli kalıcıdırlar. Orada bir koruyucu ve yardımcı bulamazlar.', 'خلدين فيها ابدا لا يجدون وليا ولا نصيرا'),
(3599, 33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِي النَّارِ يَقُولُونَ يَا لَيْتَنَٓا اَطَعْنَا اللّٰهَ وَاَطَعْنَا الرَّسُولَا', 'Yevme tukallebu vucuhuhum fin nari yekulune ya leytena eta\'nallahe ve eta\'ner resula.', 'Yüzlerinin ateşin içinde bir taraftan bir tarafa çevrileceği gün: \"Keşke biz,  Allah\'a ve Resul\'e itaat etseydik.\" derler.', 'يوم تقلب وجوههم في النار يقولون يليتنا اطعنا الله واطعنا الرسولا'),
(3600, 33, 67, 'وَقَالُوا رَبَّنَٓا اِنَّٓا اَطَعْنَا سَادَتَنَا وَكُـبَرَٓاءَنَا فَاَضَلُّونَا السَّب۪يلَا', 'Ve kalu rabbena inna ata\'na sadetena ve kuberaena fe edallunes sebil.', '\"Ey Rabb\'imiz! Biz büyüklerimize ve beylerimize[1] uyduk,  onlar da bizi yanlış yola saptırdılar.\" derler.', 'وقالوا ربنا انا اطعنا سادتنا وكبرانا فاضلونا السبيلا'),
(3601, 33, 68, 'رَبَّنَٓا اٰتِهِمْ ضِعْفَيْنِ مِنَ الْعَذَابِ وَالْعَنْهُمْ لَعْناً كَب۪يراً۟', 'Rabbena atihim dı\'feyni minel azabi vel anhum la\'nen kebira.', '\"Rabb\'imiz! Onlara iki kat azap ver ve onları büyük bir lanete uğrat.[1]\"', 'ربنا اتهم ضعفين من العذاب والعنهم لعنا كبيرا'),
(3602, 33, 69, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَكُونُوا كَالَّذ۪ينَ اٰذَوْا مُوسٰى فَبَرَّاَهُ اللّٰهُ مِمَّا قَالُواۜ وَكَانَ عِنْدَ اللّٰهِ وَج۪يهاً', 'Ya eyyuhellezine amenu la tekunu kellezine azev musa fe berreehullahu mimma kalu, ve kane indallahi veciha.', 'Ey iman edenler! Musa\'ya eziyet eden kimseler gibi olmayın! Allah; O\'nu,  onların söylediklerinden[1] temize çıkardı. O,  Allah\'ın yanında yüzü ak olan biriydi.', 'يايها الذين امنوا لا تكونوا كالذين اذوا موسي فبراه الله مما قالوا وكان عند الله وجيها'),
(3603, 33, 70, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَقُولُوا قَوْلاً سَد۪يداًۙ', 'Ya eyyuhellezine amenuttekullahe ve kulu kavlen sedida.', 'Ey iman edenler! Allah\'a takvalı davranın ve daima doğruyu söyleyin;', 'يايها الذين امنوا اتقوا الله وقولوا قولا سديدا'),
(3604, 33, 71, 'يُصْلِحْ لَكُمْ اَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْۜ وَمَنْ يُطِـعِ اللّٰهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزاً عَظ۪يماً', 'Yuslıh lekum a\'malekum ve yagfir lekum zunubekum, ve men yutıillahe ve resulehu fe kad faze fevzen azima.', 'Ki yaptıklarınızı sizin için düzeltsin[1],  suçlarınızı bağışlasın. Her kim Allah\'a ve Resul\'üne itaat[2] ederse en büyük kurtuluşla kurtuluşa ermiş olur.', 'يصلح لكم اعملكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما'),
(3605, 33, 72, 'اِنَّا عَرَضْنَا الْاَمَانَةَ عَلَى السَّمٰوَاتِ وَالْاَرْضِ وَالْجِبَالِ فَاَبَيْنَ اَنْ يَحْمِلْنَهَا وَاَشْفَقْنَ مِنْهَا وَحَمَلَهَا الْاِنْسَانُۜ اِنَّهُ كَانَ ظَلُوماً جَهُولاًۙ', 'İnna aradnel emanete ales semavati vel ardı vel cibali fe ebeyne en yahmilneha ve eşfakne minha ve hamelehal insan, innehu kane zalumen cehula.', 'Biz,  emaneti[1] göklere,  yere ve dağlara sunduk. Onu yüklenmeye yanaşmadılar[2]. Ondan korktular.[3] Onu insan yüklendi. O,  çok zalim ve çok cahildir.[4]', 'انا عرضنا الامانة علي السموت والارض والجبال فابين ان يحملنها واشفقن منها وحملها الانسن انه كان ظلوما جهولا'),
(3606, 33, 73, 'لِيُعَذِّبَ اللّٰهُ الْمُنَافِق۪ينَ وَالْمُنَافِقَاتِ وَالْمُشْرِك۪ينَ وَالْمُشْرِكَاتِ وَيَتُوبَ اللّٰهُ عَلَى الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'Li yuazziballahul munafikine vel munafikati vel muşrikine vel muşrikati ve yetuballahu alel mu\'minine vel mu\'minat, ve kanallahu gafuren rahima.', 'Allah,  münafık erkeklere ve kadınlara; Müşrik erkeklere ve kadınlara azap eder; Mü\'min erkeklerin ve kadınların tevbelerini kabul eder.[1] Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ليعذب الله المنفقين والمنفقت والمشركين والمشركت ويتوب الله علي المومنين والمومنت وكان الله غفورا رحيما'),
(3607, 34, 1, 'اَلْحَمْدُ لِلّٰهِ الَّذ۪ي لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ وَلَهُ الْحَمْدُ فِي الْاٰخِرَةِۜ  وَهُوَ الْحَك۪يمُ الْخَب۪يرُ', 'El hamdu lillahillezi lehu ma fis semavati ve ma fil ardı ve lehul hamdu fil ahireh, ve huvel hakimul habir.', 'Hamd[1],  göklerde ve yerde olan şeyler kendisine ait olan Allah içindir. Hamd,  ahirette de O\'na aittir. O,  En İyi Hüküm Veren\'dir,  Her Şeyden Haberdar\'dır.', 'الحمد لله الذي له ما في السموت وما في الارض وله الحمد في الاخرة وهو الحكيم الخبير'),
(3608, 34, 2, 'يَعْلَمُ مَا يَلِجُ فِي الْاَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنْزِلُ مِنَ السَّمَٓاءِ وَمَا يَعْرُجُ ف۪يهَاۜ وَهُوَ الرَّح۪يمُ الْغَفُورُ', 'Ya\'lemu ma yelicu fil ardı ve ma yahrucu minha ve ma yenzilu mines semai ve ma yarucu fiha, ve huver rahimul gafur.', 'O,  yere gireni ve ondan çıkanı,  gökten ineni ve ona yükseleni bilir. O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يعلم ما يلج في الارض وما يخرج منها وما ينزل من السما وما يعرج فيها وهو الرحيم الغفور'),
(3609, 34, 3, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لَا تَأْت۪ينَا السَّاعَةُۜ قُلْ بَلٰى وَرَبّ۪ي لَتَأْتِيَنَّكُمْ عَالِمِ الْغَيْبِۚ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِي السَّمٰوَاتِ وَلَا فِي الْاَرْضِ وَلَٓا اَصْغَرُ مِنْ ذٰلِكَ وَلَٓا اَكْبَرُ اِلَّا ف۪ي كِتَابٍ مُب۪ينٍۙ', 'Ve kalellezine keferu la te\'tines saah, kul bela ve rabbi le te\'tiyennekum alimil gayb, la ya\'zubu anhu miskalu zerretin fis semavati ve la fil ardı ve la asgaru min zalike ve la ekberu illa fi kitabin mubin.', 'Kafirler[1]: \"Bize o Sa\'at[2] gelmeyecek.\" dediler. De ki: \"Bilakis! Gaybı bilen Rabb\'ime ant olsun ki,  o kesinlikle size gelecektir. Göklerde olsun,  yerde olsun zerre kadar da olsa hiçbir şey O\'ndan gizli kalmaz. En küçüğünden en büyüğüne kadar her şey Kitab-ı Mubin\'dedir.[3]', 'وقال الذين كفروا لا تاتينا الساعة قل بلي وربي لتاتينكم علم الغيب لا يعزب عنه مثقال ذرة في السموت ولا في الارض ولا اصغر من ذلك ولا اكبر الا في كتب مبين'),
(3610, 34, 4, 'لِيَجْزِيَ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِۜ اُو۬لٰٓئِكَ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَر۪يمٌ', 'Li yecziyellezine amenu ve amilus salihat, ulaike lehum magfiretun ve rızkun kerim.', 'O gün; iman edip,  salihatı yapanları[1] ödüllendirecektir. Onlar için bağışlanma ve cömertçe rızık vardır.', 'ليجزي الذين امنوا وعملوا الصلحت اوليك لهم مغفرة ورزق كريم'),
(3611, 34, 5, 'وَالَّذ۪ينَ سَعَوْ ف۪ٓي اٰيَاتِنَا مُعَاجِز۪ينَ اُو۬لٰٓئِكَ لَهُمْ عَذَابٌ مِنْ رِجْزٍ اَل۪يمٌۗ', 'Vellezine seav fi ayatina muacizine ulaike lehum azabun min riczin elim.', 'Ayetlerimizi etkisiz bırakmak için çalışanlar; işte onlar,  onlar için elem verici kötü bir azap vardır.', 'والذين سعو في ايتنا معجزين اوليك لهم عذاب من رجز اليم'),
(3612, 34, 6, 'وَيَرَى الَّذ۪ينَ اُو۫تُوا الْعِلْمَ الَّـذ۪ٓي اُنْزِلَ اِلَيْكَ مِنْ رَبِّكَ هُوَ الْحَقَّۙ وَيَهْد۪ٓي اِلٰى صِرَاطِ الْعَز۪يزِ الْحَم۪يدِ', 'Ve yerellezine utul ılmellezi unzile ileyke min rabbike huvel hakka ve yehdi ila sıratıl azizil hamid.', 'Kendilerine ilim[1] verilmiş olanlar[2],  Rabb\'inden sana indirilenin yegane gerçek olduğunu ve onun; Aziz\'in,  Hamid\'in[3] yoluna ilettiğini görüyorlar.', 'ويري الذين اوتوا العلم الذي انزل اليك من ربك هو الحق ويهدي الي صرط العزيز الحميد'),
(3613, 34, 7, 'وَقَالَ الَّذ۪ينَ كَفَرُوا هَلْ نَدُلُّكُمْ عَلٰى رَجُلٍ يُنَبِّئُكُمْ اِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍۙ اِنَّكُمْ لَف۪ي خَلْقٍ جَد۪يدٍۚ', 'Ve kalellezine keferu hel nedullukum ala raculin yunebbiukum iza muzzıktum kulle mumezzekın innekum le fi halkın cedid.', 'Kafirler alayımsı bir şekilde: \"Çürüyüp,  lime lime parçalandığınız zaman,  sizin yeniden dirileceğinizi haber veren bir adamı size gösterelim mi?\" dediler.', 'وقال الذين كفروا هل ندلكم علي رجل ينبيكم اذا مزقتم كل ممزق انكم لفي خلق جديد'),
(3614, 34, 8, 'اَفْتَرٰى عَلَى اللّٰهِ كَذِباً اَمْ بِه۪ جِنَّةٌۜ  بَلِ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ فِي الْعَذَابِ وَالضَّلَالِ الْبَع۪يدِ', 'Eftera alallahi keziben em bihi cinneh, belillezine la yuminune bil ahireti fil azabi ved dalalil baid.', 'Bu adam,  ya uydurduklarını Allah\'a dayandırıyor ya da cinnet geçiriyor! Hayır,  aslında ahirete inanmayanlar,  çaresizlik ve derin bir sapkınlık içindedirler.', 'افتري علي الله كذبا ام به جنة بل الذين لا يومنون بالاخرة في العذاب والضلل البعيد'),
(3615, 34, 9, 'اَفَلَمْ يَرَوْا اِلٰى مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْ مِنَ السَّمَٓاءِ وَالْاَرْضِۜ اِنْ نَشَأْ نَخْسِفْ بِهِمُ الْاَرْضَ اَوْ نُسْقِطْ عَلَيْهِمْ كِسَفاً مِنَ السَّمَٓاءِۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَةً لِكُلِّ عَبْدٍ مُن۪يبٍ۟', 'E fe lem yerev ila ma beyne eydihim ve ma halfehum mines semai vel ard, in neşe\'nahsif bihimul arda ev nuskıt aleyhim kisefen mines sema, inne fi zalike le ayeten li kulli abdin munib.', 'Onlar,  göklerde ve yerde,  önlerinde ve arkalarında olanları görmediler mi? Dilersek onları yere geçiririz. Veya gökten üzerlerine parçalar düşürürüz. Bunlarda[1] yönelen[2] her kul için ayet[3] vardır.', 'افلم يروا الي ما بين ايديهم وما خلفهم من السما والارض ان نشا نخسف بهم الارض او نسقط عليهم كسفا من السما ان في ذلك لاية لكل عبد منيب'),
(3616, 34, 10, 'وَلَقَدْ اٰتَيْنَا دَاوُ۫دَ مِنَّا فَضْلاًۜ يَا جِبَالُ اَوِّب۪ي مَعَهُ وَالطَّيْرَۚ وَاَلَنَّا لَهُ الْحَد۪يدَۙ', 'Ve lekad ateyna davude minna fadla, ya cibalu evvibi meahu vet tayr, ve elenna lehul hadid.', 'Ant olsun ki,  katımızdan Davud\'a bir fazilet[1] verdik. Ey dağlar ve kuşlar! Onunla beraber övgüyü tekrarlayın. Ve onun için demiri yumuşattık.[2]', 'ولقد اتينا داود منا فضلا يجبال اوبي معه والطير والنا له الحديد'),
(3617, 34, 11, 'اَنِ اعْمَلْ سَابِغَاتٍ وَقَدِّرْ فِي السَّرْدِ وَاعْمَلُوا صَالِحاًۜ اِنّ۪ي بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Enimel sabigatin ve kaddir fis serdi va\'melu saliha, inni bima tamelune basir.', 'Bedeni örten zırhlar yap. Bağlantılarını güzel şekilde tasarla. Salihatı[1] yapın. Ben,  yaptıklarınızı bütün gerçeğiyle görenim.', 'ان اعمل سبغت وقدر في السرد واعملوا صلحا اني بما تعملون بصير'),
(3618, 34, 12, 'وَلِسُلَيْمٰنَ الرّ۪يحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌۚ وَاَسَلْنَا لَهُ عَيْنَ الْقِطْرِۜ وَمِنَ الْجِنِّ مَنْ يَعْمَلُ بَيْنَ يَدَيْهِ بِاِذْنِ رَبِّه۪ۜ وَمَنْ يَزِغْ مِنْهُمْ عَنْ اَمْرِنَا نُذِقْهُ مِنْ عَذَابِ السَّع۪يرِ', 'Ve li suleymaner riha guduvvuha şehrun ve revahuha şehr, ve eselna lehu aynel kıtr, ve minel cinni men ya\'melu beyne yedeyhi bi izni rabbih, ve men yezıg minhum an emrina nuzıkhu min azabis sair.', 'Sabahleyin bir aylık yol gitmeyi,  akşamleyin bir aylık yoldan geri dönmeyi sağlayan rüzgar[1],  Süleyman içindi. Ve erimiş bakırı kaynağından ona akıttık. Ve cinlerden,  Rabb\'inin izni ile[2] onun elinin altında çalışanlar vardı. Onlardan kim emrimizden çıkacak olsa,  ona alevli ateşin azabından tattırdık.', 'ولسليمن الريح غدوها شهر ورواحها شهر واسلنا له عين القطر ومن الجن من يعمل بين يديه باذن ربه ومن يزغ منهم عن امرنا نذقه من عذاب السعير'),
(3619, 34, 13, 'يَعْمَلُونَ لَهُ مَا يَشَٓاءُ مِنْ مَحَار۪يبَ وَتَمَاث۪يلَ وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَاسِيَاتٍۜ اِعْمَلُٓوا اٰلَ دَاوُ۫دَ شُكْراًۜ وَقَل۪يلٌ مِنْ عِبَادِيَ الشَّكُورُ', 'Ya\'melune lehu ma yeşau min meharibe ve temasile ve cifanin kel cevabi ve kudurin rasiyat, i\'melu ale davude şukra, ve kalilun min ibadiyeş şekur.', 'Ona dilediği gibi mabetler[1],  şekil verilmiş eşyalar,  havuz büyüklüğünde çanaklar[2] ve sabit[3] ağır kazanlar yapıyorlardı. Ey Davud\'u izleyenler! Şükür için çalışın. Ama kullarım içinde şükreden çok azdır.', 'يعملون له ما يشا من محريب وتمثيل وجفان كالجواب وقدور راسيت اعملوا ال داود شكرا وقليل من عبادي الشكور'),
(3620, 34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلٰى مَوْتِه۪ٓ اِلَّا دَٓابَّةُ الْاَرْضِ تَأْكُلُ مِنْسَاَتَهُۚ فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ اَنْ لَوْ كَانُوا يَعْلَمُونَ الْغَيْبَ مَا لَبِثُوا فِي الْعَذَابِ الْمُه۪ينِ', 'Fe lemma kadayna aleyhil mevte ma dellehum ala mevtihi illa dabbetul ardı te\'kulu minseeteh, fe lemma harre tebeyyenetil cinnu en lev kanu ya\'lemunel gaybe ma lebisu fil azabil muhin.', 'Onun ölümünü gerçekleştirdiğimiz zaman; ölümünü,  \"minsee\"yi[1] kemiren \"debbetularz\"dan[2] başka bir şey ortaya çıkarmadı. Yere kapandığında ortaya çıktı ki; cinler o gaybı[3] bilselerdi,  o alçaltıcı azap[4] içinde kalmazlardı.', 'فلما قضينا عليه الموت ما دلهم علي موته الا دابة الارض تاكل منساته فلما خر تبينت الجن ان لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين'),
(3621, 34, 15, 'لَقَدْ كَانَ لِسَبَأٍ ف۪ي مَسْكَنِهِمْ اٰيَةٌۚ جَنَّتَانِ عَنْ يَم۪ينٍ وَشِمَالٍۜ كُلُوا مِنْ رِزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُۜ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', 'Lekad kane li sebein fi meskenihim ayeh, cennetani an yeminin ve şimal, kulu min rızkı rabbikum veşkuru leh, beldetun tayyibetun ve rabbun gafur.', 'Ant olsun ki,  Sebelilerin yaşadıkları yerde bir ayet[1] vardı: Sağda ve Solda iki cennet![2] Rabb\'inizin rızkından yiyin ve O\'na şükredin.[3] Temiz bir belde ve çok bağışlayıcı bir Rabb!', 'لقد كان لسبا في مسكنهم اية جنتان عن يمين وشمال كلوا من رزق ربكم واشكروا له بلدة طيبة ورب غفور'),
(3622, 34, 16, 'فَاَعْرَضُوا فَاَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ وَبَدَّلْنَاهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيْ اُكُلٍ خَمْطٍ وَاَثْلٍ وَشَيْءٍ مِنْ سِدْرٍ قَل۪يلٍ', 'Fe a\'radu fe erselna aleyhim seylel arimi ve beddelna-hum bi cenneteyhim cenneteyni zevatey ukulin hamtın ve eslin ve şeyin min sidrin kalil.', 'Onlarsa yüz çevirdiler[1]. Biz de üzerlerine su seddinin suyunu salıverdik. Ve iki cennetlerini[2],  acı meyveli ağaçlara,  meyvesiz ağaçlara ve az miktarda sedir ağacı bulunan iki cennete[2] çevirdik.', 'فاعرضوا فارسلنا عليهم سيل العرم وبدلنهم بجنتيهم جنتين ذواتي اكل خمط واثل وشي من سدر قليل'),
(3623, 34, 17, 'ذٰلِكَ جَزَيْنَاهُمْ بِمَا كَفَرُواۜ وَهَلْ نُجَاز۪ٓي اِلَّا الْكَفُورَ', 'Zalike cezeynahum bima keferu, ve hel nucazi illel kefur.', 'Bu,  Kafirlik[1] etmeleri nedeniyle,  onları cezalandırmamızdır. Biz,  yalnızca Kafirleri[1] cezalandırırız.', 'ذلك جزينهم بما كفروا وهل نجزي الا الكفور'),
(3624, 34, 18, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّت۪ي بَارَكْنَا ف۪يهَا قُرًى ظَاهِرَةً وَقَدَّرْنَا ف۪يهَا السَّيْرَۜ س۪يرُوا ف۪يهَا لَيَالِيَ وَاَيَّاماً اٰمِن۪ينَ', 'Ve cealna beynehum ve beynel kurelleti barekna fiha kuren zahireten ve kadderna fihes seyr, siru fiha leyaliye ve eyyamen aminin.', 'Onlarla bereketli kıldığımız kentler arasında birbirlerine yakın kasabalar yaptık. Bunlar arasında yolculuk yapılacak yollar düzenledik. \"Buralarda geceleri ve gündüzleri güvenli olarak yolculuk yapın dedik.', 'وجعلنا بينهم وبين القري التي بركنا فيها قري ظهرة وقدرنا فيها السير سيروا فيها ليالي واياما امنين'),
(3625, 34, 19, 'فَقَالُوا رَبَّنَا بَاعِدْ بَيْنَ اَسْفَارِنَا وَظَلَمُٓوا اَنْفُسَهُمْ فَجَعَلْنَاهُمْ اَحَاد۪يثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ', 'Fe kalu rabbena baidbeyne esfarina ve zalemu enfusehum fe cealnahum ehadise ve mezzaknahum kulle mumezzak, inne fi zalike le ayatin li kulli sabbarin şekur.', 'Fakat onlar: \"Rabb\'imiz! Yolculuk mesafelerimizi uzat.[1]\" dediler ve kendilerine zulmettiler. Biz de onları dillerde dolaşan hadis[2] yaptık. Ve onları tamamen parça parça dağıttık. Kuşkusuz bunda çok sabredenlerin ve çok şükredenlerin tamamı için kesinlikle ayetler[3] vardır.', 'فقالوا ربنا بعد بين اسفارنا وظلموا انفسهم فجعلنهم احاديث ومزقنهم كل ممزق ان في ذلك لايت لكل صبار شكور'),
(3626, 34, 20, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ اِبْل۪يسُ ظَنَّهُ فَاتَّبَعُوهُ اِلَّا فَر۪يقاً مِنَ الْمُؤْمِن۪ينَ', 'Ve lekad saddaka aleyhim iblisu zannehu fettebeuhu illa ferikan minel muminin.', 'Ant olsun ki,  iblis onlar hakkındaki beklentisini gerçekleştirdi. İnananlardan oluşan bir topluluk hariç,  hepsi ona uydular.', 'ولقد صدق عليهم ابليس ظنه فاتبعوه الا فريقا من المومنين'),
(3627, 34, 21, 'وَمَا كَانَ لَهُ عَلَيْهِمْ مِنْ سُلْطَانٍ اِلَّا لِنَعْلَمَ مَنْ يُؤْمِنُ بِالْاٰخِرَةِ مِمَّنْ هُوَ مِنْهَا ف۪ي شَكٍّۜ وَرَبُّكَ عَلٰى كُلِّ شَيْءٍ حَف۪يظٌ۟', 'Ve ma kane lehu aleyhim min sultanin illa li na\'leme men yu\'minu bil ahireti mimmen huve minha fi şekk, ve rabbuke ala kulli şeyin hafiz.', 'Aslında iblisin onlar üzerinde bir sultanlığı[1] yoktu. Fakat Biz,  ahirete iman edenle ondan kuşku duyanı ayırt edeceğiz. Senin Rabb\'in Her Şeyi Gözetip Koruyan\'dır.', 'وما كان له عليهم من سلطن الا لنعلم من يومن بالاخرة ممن هو منها في شك وربك علي كل شي حفيظ'),
(3628, 34, 22, 'قُلِ ادْعُوا الَّذ۪ينَ زَعَمْتُمْ مِنْ دُونِ اللّٰهِۚ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِي السَّمٰوَاتِ وَلَا فِي الْاَرْضِ وَمَا لَهُمْ ف۪يهِمَا مِنْ شِرْكٍ وَمَا لَهُ مِنْهُمْ مِنْ ظَه۪يرٍ', 'Kulid\'ullezine zeamtum min dunillah, la yemlikune miskale zerretin fis semavati ve la fil ardı ve ma lehum fihima min şirkin ve ma lehu minhum min zahir.', 'De ki: \"Allah\'ın yanı sıra değer verdiklerinize yakarın! Onlar,  göklerde ve yerde zerre kadar bir şeye sahip değildirler. Onların,  Göklerin ve yerin yaratılmalarında bir payları yoktur. Ve Allah\'ın,  onların yardımına ihtiyacı da yoktur.', 'قل ادعوا الذين زعمتم من دون الله لا يملكون مثقال ذرة في السموت ولا في الارض وما لهم فيهما من شرك وما له منهم من ظهير'),
(3629, 34, 23, 'وَلَا تَنْفَعُ الشَّفَاعَةُ عِنْدَهُٓ اِلَّا لِمَنْ اَذِنَ لَهُۜ حَتّٰٓى اِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا مَاذَاۙ قَالَ رَبُّكُمْۜ قَالُوا الْحَقَّۚ وَهُوَ الْعَلِيُّ الْكَب۪يرُ', 'Ve la tenfeuş şefaatu indehu illa li men ezine leh, hatta iza fuzzia an kulubihim kalu maza kale rabbukum, kalul hakk, ve huvel aliyyul kebir.', 'O\'nun yanında şefaat,  yalnızca izin verdiği kimseye fayda verir.[1] Kalplerindeki korku giderilince: \"Rabb\'imiz ne buyurdu?\" derler. \"Gerçeği.\" derler. Ve O,  Çok Yüce\'dir,  Çok Büyük\'tür.', 'ولا تنفع الشفعة عنده الا لمن اذن له حتي اذا فزع عن قلوبهم قالوا ماذا قال ربكم قالوا الحق وهو العلي الكبير'),
(3630, 34, 24, 'قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّمٰوَاتِ وَالْاَرْضِۜ قُلِ اللّٰهُۙ وَاِنَّٓا اَوْ اِيَّاكُمْ لَعَلٰى هُدًى اَوْ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Kul men yerzukukum mines semavati vel ard, kulillahu ve inna ev iyyakum le ala huden ev fi dalalin mubin.', 'De ki: \"Göklerden ve yerden sizi rızıklandıran kimdir?\" De ki: \"Allah. Ya siz ya da biz doğru yoldayız veya ya biz ya da siz açıkça bir sapkınlık içindeyiz.\"', 'قل من يرزقكم من السموت والارض قل الله وانا او اياكم لعلي هدي او في ضلل مبين'),
(3631, 34, 25, 'قُلْ لَا تُسْـَٔلُونَ عَمَّٓا اَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', 'Kul la tus\'elune amma ecremna ve la nus\'elu amma ta\'melun.', 'De ki: \"Bizim yaptığımız cürümden[1] siz sorumlu tutulmazsınız. Ve biz de sizin yaptıklarınızdan sorumlu tutulmayız.\"', 'قل لا تسلون عما اجرمنا ولا نسل عما تعملون'),
(3632, 34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّۜ وَهُوَ الْفَتَّاحُ الْعَل۪يمُ', 'Kul yecmeu beynena rabbuna summe yeftehu beynena bil hakk, ve huvel fettahul alim.', 'De ki: \"Rabb\'imiz hepimizi bir araya toplayacak sonra da aramızda adaletle yargıda bulunacaktır. O; En Adil Yargıç\'tır,  Her Şeyi Bilen\'dir.\"', 'قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم'),
(3633, 34, 27, 'قُلْ اَرُونِيَ الَّذ۪ينَ اَلْحَقْتُمْ بِه۪ شُرَكَٓاءَ كَلَّاۜ بَلْ هُوَ اللّٰهُ الْعَز۪يزُ الْحَك۪يمُ', 'Kul eruniyellezine elhaktum bihi şurekae kella, bel huvallahul azizul hakim.', 'De ki: \"O\'na ortak kabul ettiklerinizi bana gösterin! Asla böyle bir şey olamaz. O,  Allah ki; Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.\"', 'قل اروني الذين الحقتم به شركا كلا بل هو الله العزيز الحكيم'),
(3634, 34, 28, 'وَمَٓا اَرْسَلْنَاكَ اِلَّا كَٓافَّةً لِلنَّاسِ بَش۪يراً وَنَذ۪يراً وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', 'Ve ma erselnake illa kaffeten lin nasi beşiren ve neziren ve lakinne ekseren nasi la ya\'lemun.', 'Biz,  seni bütün insanlığa yalnızca haber verici ve uyarıcı olarak gönderdik. Ne var ki insanların çoğu bu gerçeği anlamıyorlar.', 'وما ارسلنك الا كافة للناس بشيرا ونذيرا ولكن اكثر الناس لا يعلمون'),
(3635, 34, 29, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadikin.', '\"Eğer doğru söylüyorsanız,  bizi tehdit ettiğiniz uyarı ne zaman?\" diyorlar.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(3636, 34, 30, 'قُلْ لَكُمْ م۪يعَادُ يَوْمٍ لَا تَسْتَأْخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ۟', 'Kul lekum miadu yevmin la teste\'hirune anhu saaten ve la testakdimun.', 'De ki: \"Size yapılan uyarının bir zamanı vardır. Ondan,  bir saat bile geri de kalmazsınız ileri de geçemezsiniz.\"', 'قل لكم ميعاد يوم لا تستخرون عنه ساعة ولا تستقدمون'),
(3637, 34, 31, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لَنْ نُؤْمِنَ بِهٰذَا الْقُرْاٰنِ وَلَا بِالَّذ۪ي بَيْنَ يَدَيْهِۜ وَلَوْ تَرٰٓى اِذِ الظَّالِمُونَ مَوْقُوفُونَ عِنْدَ رَبِّهِمْۚ يَرْجِعُ بَعْضُهُمْ اِلٰى بَعْضٍۨ الْقَوْلَۚ يَقُولُ الَّذ۪ينَ اسْتُضْعِفُوا لِلَّذ۪ينَ اسْتَكْبَرُوا  لَوْلَٓا اَنْتُمْ لَكُنَّا مُؤْمِن۪ينَ', 'Ve kalellezine keferu len nu\'mine bi hazel kur\'ani ve la billezi beyne yedeyh, ve lev tera iziz zalimune mevkufune inde rabbihim, yerciu ba\'duhum ila ba\'dınil kavl, yekulullezinestud\'ifu lillezinestekberu lev la entum le kunna muminin.', 'Kafirler,  \"Biz ne bu Kur\'an\'a ne de ondan önce gelene asla inanmayacağız.\" dediler. Sen bu zalimleri,  Rabb\'leri huzuruna çıkarıldıklarında nasıl birbirlerine sataştıklarını bir görsen! Güçsüzler,  büyüklük taslayan kimselere,  \"Eğer siz olmasaydınız,  biz kesinlikle inananlar olurduk.\" derler.', 'وقال الذين كفروا لن نومن بهذا القران ولا بالذي بين يديه ولو تري اذ الظلمون موقوفون عند ربهم يرجع بعضهم الي بعض القول يقول الذين استضعفوا للذين استكبروا لولا انتم لكنا مومنين'),
(3638, 34, 32, 'قَالَ الَّذ۪ينَ اسْتَكْبَرُوا لِلَّذ۪ينَ اسْتُضْعِفُٓوا اَنَحْنُ صَدَدْنَاكُمْ عَنِ الْهُدٰى بَعْدَ اِذْ جَٓاءَكُمْ بَلْ كُنْتُمْ مُجْرِم۪ينَ', 'Kalellezinestekberu lillezinestud\'ifu e nahnu sadednakum anil huda ba\'de iz caekum bel kuntum mucrimin.', 'Büyüklük taslayanlar,  mus\'tezaflara[1]: \"Size doğru yol gösterildiğinde,  sizi o yoldan biz mi alıkoyduk? Hayır! Siz zaten suçlu kimselerdiniz.\"[1] dediler.', 'قال الذين استكبروا للذين استضعفوا انحن صددنكم عن الهدي بعد اذ جاكم بل كنتم مجرمين'),
(3639, 34, 33, 'وَقَالَ الَّذ۪ينَ اسْتُضْعِفُوا لِلَّذ۪ينَ اسْتَكْبَرُوا بَلْ مَكْرُ الَّيْلِ وَالنَّهَارِ اِذْ تَأْمُرُونَـنَٓا اَنْ نَكْفُرَ بِاللّٰهِ وَنَجْعَلَ لَهُٓ  اَنْدَاداًۜ وَاَسَرُّوا النَّدَامَةَ لَمَّا رَاَوُا الْعَذَابَۜ وَجَعَلْنَا الْاَغْلَالَ ف۪ٓي اَعْنَاقِ الَّذ۪ينَ كَفَرُواۜ هَلْ يُجْزَوْنَ اِلَّا مَا كَانُوا يَعْمَلُونَ', 'Ve kalellezinestud\'ifu lillezinestekberu bel mekrul leyli ven nehari iz te\'murunena en nekfure billahi ve nec\'ale lehu endada, ve eserrun nedamete lemma raevul azab, ve cealnel aglale fi a\'nakıllezine keferu, hel yuczevne illa ma kanu ya\'melun.', 'Mus\'tezaflar[1],  büyüklük taslayanlara: \"Hayır! Gece gündüz[2] kurduğunuz tuzaklarla bize,  Allah\'ı yalanlamamızı,  O\'na birtakım eşler koşmamızı öneriyordunuz.\" dediler. Azabı gördükleri zaman,  için için pişman olacaklar. Kafirlerin boyunlarına demir halkalar geçiririz. Onlar,  yalnızca yapmış oldukları şeylerin karşılığını görecekler.', 'وقال الذين استضعفوا للذين استكبروا بل مكر اليل والنهار اذ تامروننا ان نكفر بالله ونجعل له اندادا واسروا الندامة لما راوا العذاب وجعلنا الاغلل في اعناق الذين كفروا هل يجزون الا ما كانوا يعملون'),
(3640, 34, 34, 'وَمَٓا اَرْسَلْنَا ف۪ي قَرْيَةٍ مِنْ نَذ۪يرٍ اِلَّا قَالَ مُتْرَفُوهَٓاۙ اِنَّا بِمَٓا اُرْسِلْتُمْ بِه۪ كَافِرُونَ', 'Ve ma erselna fi karyetin min nezirin illa kale mutrefuha inna bima ursiltum bihi kafirun.', 'Biz,  hangi beldeye bir uyarıcı gönderdiysek,  oranın mutref[1] olanları: \"Biz,  sizin getirdiğiniz şeyleri küfrediyoruz.\" dediler.', 'وما ارسلنا في قرية من نذير الا قال مترفوها انا بما ارسلتم به كفرون'),
(3641, 34, 35, 'وَقَالُوا نَحْنُ اَكْثَرُ اَمْوَالاً وَاَوْلَاداًۙ وَمَا نَحْنُ بِمُعَذَّب۪ينَ', 'Ve kalu nahnu ekseru emvalen ve evladen ve ma nahnu bi muazzebin.', '\"Biz,  varlık ve evlat olarak çok daha fazlayız. Ve biz,  azap görecek de değiliz.\" dediler.', 'وقالوا نحن اكثر امولا واولدا وما نحن بمعذبين'),
(3642, 34, 36, 'قُلْ اِنَّ رَبّ۪ي يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ۟', 'Kul inne rabbi yebsutur rızka limen yeşau ve yakdiru ve lakinne ekseren nasi la ya\'lemun.', 'De ki: \"Benim Rabb\'im,  dilediği kimseye rızkı genişletir ve takdir eder. Fakat insanların çoğu idrak etmezler.\"', 'قل ان ربي يبسط الرزق لمن يشا ويقدر ولكن اكثر الناس لا يعلمون'),
(3643, 34, 37, 'وَمَٓا اَمْوَالُكُمْ وَلَٓا اَوْلَادُكُمْ بِالَّت۪ي تُقَرِّبُكُمْ عِنْدَنَا زُلْفٰٓى اِلَّا مَنْ اٰمَنَ وَعَمِلَ صَالِحاًۘ فَاُو۬لٰٓئِكَ لَهُمْ جَزَٓاءُ الضِّعْفِ بِمَا عَمِلُوا وَهُمْ فِي الْغُرُفَاتِ اٰمِنُونَ', 'Ve ma emvalukum ve la evladukum billeti tukarribukum indena zulfa illa men amene ve amile salihan fe ulaike lehum cezaud dı\'fi bima amilu ve hum fil gurufati aminun.', 'Sizi,  Bize yaklaştıracak olan,  mallarınız ve evlatlarınız değildir. İnananlar ve salihatı yapanlar,  işte onlara yaptıklarına karşılık kat kat ödül vardır. Ve onlar,  yüksek makamlarda güven içindedirler.', 'وما امولكم ولا اولدكم بالتي تقربكم عندنا زلفي الا من امن وعمل صلحا فاوليك لهم جزا الضعف بما عملوا وهم في الغرفت امنون'),
(3644, 34, 38, 'وَالَّذ۪ينَ يَسْعَوْنَ ف۪ٓي اٰيَاتِنَا مُعَاجِز۪ينَ اُو۬لٰٓئِكَ فِي الْعَذَابِ مُحْضَرُونَ', 'Vellezine yes\'avne fi ayatina muacizine ulaike fil azabi muhdarun.', 'Ayetlerimizi etkisiz kılmak için uğraşanlar,  işte onlar azapla karşı karşıya kalacak olanlardır.', 'والذين يسعون في ايتنا معجزين اوليك في العذاب محضرون'),
(3645, 34, 39, 'قُلْ اِنَّ رَبّ۪ي يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ مِنْ عِبَادِه۪ وَيَقْدِرُ لَهُۜ وَمَٓا اَنْفَقْتُمْ مِنْ شَيْءٍ فَهُوَ يُخْلِفُهُۚ وَهُوَ خَيْرُ الرَّازِق۪ينَ', 'Kul inne rabbi yebsutur rızka li men yeşau min ibadihi ve yakdiru leh, ve ma enfaktum min şeyin fe huve yuhlifuh, ve huve hayrur razikin.', 'De ki: \"Benim Rabb\'im,  kullarından dilediği kimse için rızkı genişletir ve takdir eder. Bir şey infak[1] ettiğiniz zaman; O,  onun karşılığını verir. Ve O,  rızık verenlerin en hayırlısıdır.', 'قل ان ربي يبسط الرزق لمن يشا من عباده ويقدر له وما انفقتم من شي فهو يخلفه وهو خير الرزقين'),
(3646, 34, 40, 'وَيَوْمَ يَحْشُرُهُمْ جَم۪يعاً ثُمَّ يَقُولُ لِلْمَلٰٓئِكَةِ اَهٰٓؤُ۬لَٓاءِ اِيَّاكُمْ  كَانُوا يَعْبُدُونَ', 'Ve yevme yahşuruhum cemian summe yekulu lil melaiketi e haulai iyyakum kanu ya\'budun.', 'Ve o gün O,  onların hepsini bir araya toplayacak. Sonra meleklere: \"Şunlar,  size mi kulluk ediyorlardı?\" diye soracak.', 'ويوم يحشرهم جميعا ثم يقول للمليكة اهولا اياكم كانوا يعبدون'),
(3647, 34, 41, 'قَالُوا سُبْحَانَكَ اَنْتَ وَلِيُّنَا مِنْ دُونِهِمْۚ بَلْ كَانُوا يَعْبُدُونَ الْجِنَّۚ اَكْثَرُهُمْ بِهِمْ مُؤْمِنُونَ', 'Kalu subhaneke ente veliyyuna min dunihim, bel kanu ya\'budunel cinn, ekseruhum bihim mu\'minun.', 'Onlar: \"Seni tenzih[1] ederiz. Bizim velimiz[2] onlar değil,  Sen\'sin. Bilakis,  onlar,  cinlere kulluk ediyorlardı. Çoğu onlara inanıyorlardı.\" derler.', 'قالوا سبحنك انت ولينا من دونهم بل كانوا يعبدون الجن اكثرهم بهم مومنون'),
(3648, 34, 42, 'فَالْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَفْعاً وَلَا ضَراًّۜ وَنَقُولُ لِلَّذ۪ينَ ظَلَمُوا ذُوقُوا عَذَابَ النَّارِ الَّت۪ي كُنْتُمْ بِهَا تُكَذِّبُونَ', 'Fel yevme la yemliku ba\'dukum li ba\'dın nef\'an ve la darra, ve nekulu lillezine zalemu zuku azaben narilleti kuntum biha tukezzibun.', 'Artık bugün birbirinize ne yarar ne de zarar vermeye gücünüz yeter. Zulmedenlere: \"Yalanlamış olduğunuz ateşin azabını tadın.\" diyeceğiz.', 'فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب النار التي كنتم بها تكذبون'),
(3649, 34, 43, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍ قَالُوا مَا هٰذَٓا اِلَّا رَجُلٌ يُر۪يدُ اَنْ يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ اٰبَٓاؤُ۬كُمْۚ وَقَالُوا مَا هٰذَٓا اِلَّٓا اِفْكٌ مُفْتَرًىۜ وَقَالَ الَّذ۪ينَ كَفَرُوا لِلْحَقِّ لَمَّا جَٓاءَهُمْۙ اِنْ هٰذَٓا اِلَّا سِحْرٌ مُب۪ينٌ', 'Ve iza tutla aleyhim ayatuna beyyinatin kalu ma haza illa raculun yuridu en yasuddekum amma kane ya\'budu abaukum, ve kalu ma haza illa ifkun muftera ve kalellezine keferu lil hakkı lemma caehum in haza illa sihrun mubin.', 'Onlara apaçık ayetlerimiz okunduğu zaman: \"Bu,  ancak,  atalarınızın tapmakta olduğu şeylerden sizi vazgeçirmek isteyen bir adamdan başkası değildir.\" dediler. Ve dediler ki: \"Bu,  uydurulmuş bir iftiradan başka bir şey değildir.\" Kafirler,  kendilerine gerçek gelince: \"Bu,  ancak apaçık bir büyüdür.\" dediler.', 'واذا تتلي عليهم ايتنا بينت قالوا ما هذا الا رجل يريد ان يصدكم عما كان يعبد اباوكم وقالوا ما هذا الا افك مفتري وقال الذين كفروا للحق لما جاهم ان هذا الا سحر مبين'),
(3650, 34, 44, 'وَمَٓا اٰتَيْنَاهُمْ مِنْ كُتُبٍ يَدْرُسُونَهَا وَمَٓا اَرْسَلْنَٓا اِلَيْهِمْ قَبْلَكَ مِنْ نَذ۪يرٍۜ', 'Ve ma ateynahum min kutubin yedrusuneha ve ma erselna ileyhim kableke min nezir.', 'Biz,  onlara bilgilenecekleri kitaplardan[1] vermedik. Ve senden önce onlara bir uyarıcı da göndermedik.', 'وما اتينهم من كتب يدرسونها وما ارسلنا اليهم قبلك من نذير'),
(3651, 34, 45, 'وَكَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْۙ وَمَا بَلَغُوا مِعْشَارَ مَٓا اٰتَيْنَاهُمْ فَكَذَّبُوا رُسُل۪ي۠ فَكَيْفَ كَانَ نَك۪يرِ۟', 'Ve kezzebellezine min kablihim ve ma belegu mi\'şare ma ateynahum fe kezzebu rusuli, fe keyfe kane nekir.', 'Kendilerinden öncekiler de yalanlamışlardı. Ve onlara verdiğimiz nimetlerin onda birine bile sahip değillerdi. Buna rağmen resullerimizi yalanladılar. Fakat Beni yok sayma neymiş gördüler!', 'وكذب الذين من قبلهم وما بلغوا معشار ما اتينهم فكذبوا رسلي فكيف كان نكير'),
(3652, 34, 46, 'قُلْ اِنَّـمَٓا اَعِظُـكُمْ بِوَاحِدَةٍۚ اَنْ تَقُومُوا لِلّٰهِ مَثْنٰى وَفُرَادٰى ثُمَّ تَتَفَكَّرُوا۠ مَا بِصَاحِبِكُمْ مِنْ جِنَّةٍۜ اِنْ هُوَ اِلَّا نَذ۪يرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَد۪يدٍ', 'Kul innema eızukum bi vahideh, en tekumu lillahi mesna ve furada summe tetefekkeru, ma bi sahıbikum min cinneh, in huve illa nezirun lekum beyne yedey azabin şedid.', 'De ki: \"Size yalnızca bir tek şey öğütlüyorum. Allah için ikişer ikişer ve teker teker bir araya gelin[1]. Sonra iyice düşünün.\" Sizin arkadaşınızda bir delilik yoktur. O,  şiddetli bir azabın öncesinde bir uyarıcıdır.', 'قل انما اعظكم بوحدة ان تقوموا لله مثني وفردي ثم تتفكروا ما بصاحبكم من جنة ان هو الا نذير لكم بين يدي عذاب شديد'),
(3653, 34, 47, 'قُلْ مَا سَاَلْتُكُمْ مِنْ اَجْرٍ فَهُوَ لَكُمْۜ اِنْ اَجْرِيَ اِلَّا عَلَى اللّٰهِۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌ', 'Kul ma seeltukum min ecrin fe huve lekum, in ecriye illa alallah, ve huve ala kulli şeyin şehid.', 'De ki: \"Sizden bir karşılık beklemiyorum. Sizden bir beklentim yok. Benim ücretim,  yalnızca Allah\'a aittir. Ve O,  Her Şeye Tanık\'tır.\"', 'قل ما سالتكم من اجر فهو لكم ان اجري الا علي الله وهو علي كل شي شهيد'),
(3654, 34, 48, 'قُلْ اِنَّ رَبّ۪ي يَقْذِفُ بِالْحَقِّۚ عَلَّامُ الْغُيُوبِ', 'Kul inne rabbi yakzifu bil hakk, allamul guyub.', 'De ki \"Benim Rabb\'im gerçeği ortaya koyar. O,  bütün gaybı[1] en iyi bilendir.\"', 'قل ان ربي يقذف بالحق علم الغيوب'),
(3655, 34, 49, 'قُلْ جَٓاءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُع۪يدُ', 'Kul cael hakku ve ma yubdiul batılu ve ma yuid.', 'De ki: \"Hakk[1] geldi. Artık,  Batıl[2] ortaya bir şey koyamaz da geri getiremez de.\"', 'قل جا الحق وما يبدي البطل وما يعيد'),
(3656, 34, 50, 'قُلْ اِنْ ضَلَلْتُ فَاِنَّـمَٓا اَضِلُّ عَلٰى نَفْس۪يۚ وَاِنِ اهْتَدَيْتُ فَبِمَا يُوح۪ٓي اِلَيَّ رَبّ۪يۜ اِنَّهُ سَم۪يعٌ قَر۪يبٌ', 'Kul in dalaltu fe innema edıllu ala nefsi, ve in ihtedeytu fe bima yuhi ileyye rabbi, innehu semiun karib.', 'De ki: \"Eğer yanlış yola sapmışsam sadece kendi zararıma sapmış olurum. Eğer doğru yoldaysam,  bilesiniz ki Rabb\'imin bana verdiği vahiy sayesindedir. O,  Her Şeyi Duyan\'dır,  En Yakın Olan\'dır.', 'قل ان ضللت فانما اضل علي نفسي وان اهتديت فبما يوحي الي ربي انه سميع قريب'),
(3657, 34, 51, 'وَلَوْ تَرٰٓى اِذْ فَزِعُوا فَلَا فَوْتَ وَاُخِذُوا مِنْ مَكَانٍ قَر۪يبٍۙ', 'Ve lev tera iz feziu fe la fevte ve uhızu min mekanin karib.', 'Onları,  korkuya kapıldıkları zaman bir görsen. Artık kurtuluş yoktur. Yakın bir yerden[1] yakalandılar.', 'ولو تري اذ فزعوا فلا فوت واخذوا من مكان قريب'),
(3658, 34, 52, 'وَقَالُٓوا اٰمَنَّا بِه۪ۚ وَاَنّٰى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَع۪يدٍۚ', 'Ve kalu amenna bih, ve enna lehumut tenavuşu min mekanin baid.', '\"O\'na iman ettik.\" dediler. Bunu uzak bir yerden[1] nasıl elde edebilirler?', 'وقالوا امنا به واني لهم التناوش من مكان بعيد'),
(3659, 34, 53, 'وَقَدْ كَفَرُوا بِه۪ مِنْ قَبْلُۚ وَيَقْذِفُونَ بِالْغَيْبِ مِنْ مَكَانٍ بَع۪يدٍ', 'Ve kad keferu bihi min kabl, ve yakzifune bil gaybi min mekanin baid.', 'Oysaki daha önce onu[1] kesin olarak yalanlamışlardı. Uzak bir yerden[2] gayb[3] hakkında atıp tutuyorlardı.', 'وقد كفروا به من قبل ويقذفون بالغيب من مكان بعيد'),
(3660, 34, 54, 'وَح۪يلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِاَشْيَاعِهِمْ مِنْ قَبْلُۜ اِنَّهُمْ كَانُوا ف۪ي شَكٍّ مُر۪يبٍ', 'Ve hile beynehum ve beyne ma yeştehune kema fuile bi eşyaihim min kabl, innehum kanu fi şekkin murib.', 'Tıpkı bundan önce benzerlerine yapıldığı gibi; artık canlarının arzu ettiğini yapamayacaklar. Onlar kaygı verici ikilem içindeydiler.[1]', 'وحيل بينهم وبين ما يشتهون كما فعل باشياعهم من قبل انهم كانوا في شك مريب'),
(3661, 35, 1, 'اَلْحَمْدُ لِلّٰهِ فَاطِرِ السَّمٰوَاتِ وَالْاَرْضِ جَاعِلِ الْمَلٰٓئِكَةِ رُسُلاً اُو۬ل۪ٓي اَجْنِحَةٍ مَثْنٰى وَثُلٰثَ وَرُبَاعَۜ يَز۪يدُ فِي الْخَلْقِ مَا يَشَٓاءُۜ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Elhamdu lillahi fatırıs semavati vel ardı cailil melaiketi rusulen uli ecnihatin mesna ve sulase ve rubaa, yezidu fil halkı ma yeşau, innallahe ala kulli şey\'in kadir.', 'Hamd göklere ve yere yaradılış yasalarını koyan,  melekleri ikişer,  üçer,  dörder kanatlı resuller[1] yapan Allah\'a özgüdür. O,  yaratmada dilediğini arttırır. Allah,  Her Şeye Gücü Yeten\'dir.', 'الحمد لله فاطر السموت والارض جاعل المليكة رسلا اولي اجنحة مثني وثلث وربع يزيد في الخلق ما يشا ان الله علي كل شي قدير'),
(3662, 35, 2, 'مَا يَفْتَحِ اللّٰهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَاۚ وَمَا يُمْسِكْۙ فَلَا مُرْسِلَ لَهُ مِنْ بَعْدِه۪ۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Ma yeftehillahu lin nasi min rahmetin fe la mumsike leha, ve ma yumsik fe la mursile lehu min ba\'dih, ve huvel azizul hakim.', 'Allah,  insanlar için rahmetinden neyi açarsa artık onu tutacak biri olamaz. Her neyi tutarsa da artık O\'ndan sonra onu gönderecek de yoktur. Ve O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ما يفتح الله للناس من رحمة فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم'),
(3663, 35, 3, 'يَٓا اَيُّهَا النَّاسُ اذْكُرُوا نِعْمَتَ اللّٰهِ عَلَيْكُمْۜ هَلْ مِنْ خَالِقٍ غَيْرُ اللّٰهِ يَرْزُقُكُمْ مِنَ السَّمَٓاءِ وَالْاَرْضِۜ  لَٓا اِلٰهَ اِلَّا هُوَۘ   فَاَنّٰى تُؤْفَكُونَ', 'Ya eyyuhen nasuzkuru ni\'metallahi aleykum, hel min halikın gayrullahi yerzukukum mines semai vel ard, la ilahe illa huve fe enna tu\'fekun.', 'Ey insanlar! Allah\'ın üzerinizdeki nimetini hatırlayın. Allah\'tan başka gökten ve yerden size rızık veren bir yaratıcı var mı? O\'ndan başka ilah yoktur. O halde ne diye döndürülüyorsunuz?[1]', 'يايها الناس اذكروا نعمت الله عليكم هل من خلق غير الله يرزقكم من السما والارض لا اله الا هو فاني توفكون'),
(3664, 35, 4, 'وَاِنْ يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ', 'Ve in yukezzibuke fe kad kuzzibet rusulun min kablik, ve ilallahi turceul umur.', 'Eğer seni yalanlıyorlarsa,  bil ki senden önceki resuller de yalanlanmışlardı. Bütün işler Allah\'a döndürülür.', 'وان يكذبوك فقد كذبت رسل من قبلك والي الله ترجع الامور'),
(3665, 35, 5, 'يَٓا اَيُّهَا النَّاسُ اِنَّ وَعْدَ اللّٰهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيٰوةُ الدُّنْيَا۠ وَلَا يَغُرَّنَّكُمْ بِاللّٰهِ الْغَرُورُ', 'Ya eyyuhen nasu inne va\'dallahi hakkun fe la tegurrennekumul hayatud dunya, ve la yegurrennekum billahil garur.', 'Ey insanlar! Allah\'ın sözü gerçektir. Öyleyse,  dünya hayatı sizi aldatmasın! Sakın aldatıcı sizi Allah ile aldatmasın.[1]', 'يايها الناس ان وعد الله حق فلا تغرنكم الحيوة الدنيا ولا يغرنكم بالله الغرور'),
(3666, 35, 6, 'اِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُواًّۜ اِنَّمَا يَدْعُوا حِزْبَهُ لِيَكُونُوا مِنْ اَصْحَابِ السَّع۪يرِۜ', 'İnneş şeytane lekum aduvvun fettehızuhu aduvva, innema yed\'u hızbehu li yekunu min ashabis seir.', 'Kuşkusuz şeytan[1] sizin düşmanınızdır. Öyleyse siz de onu düşman edinin. O kendisine uyanları alevli ateşin halkından olmaya çağırır.', 'ان الشيطن لكم عدو فاتخذوه عدوا انما يدعوا حزبه ليكونوا من اصحب السعير'),
(3667, 35, 7, 'اَلَّذ۪ينَ كَفَرُوا لَهُمْ عَذَابٌ شَد۪يدٌۜ وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ مَغْفِرَةٌ وَاَجْرٌ كَب۪يرٌ۟', 'Ellezine keferu lehum azabun şedid, vellezine amenu ve amilus salihati lehum magfiretun ve ecrun kebir.', 'Kafirler[1] için şiddetli bir azap vardır. İnananlar ve salihatı[2] yapanlar için bağışlanma ve büyük bir ödül vardır.', 'الذين كفروا لهم عذاب شديد والذين امنوا وعملوا الصلحت لهم مغفرة واجر كبير'),
(3668, 35, 8, 'اَفَمَنْ زُيِّنَ لَهُ سُٓوءُ عَمَلِه۪ فَرَاٰهُ حَسَناًۜ فَاِنَّ اللّٰهَ يُضِلُّ مَنْ يَشَٓاءُ وَيَهْد۪ي مَنْ يَشَٓاءُۘ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍۜ اِنَّ اللّٰهَ عَل۪يمٌ بِمَا يَصْنَعُونَ', 'E fe men zuyyine lehu suu amelihi fe reahu hasena, fe innallahe yudıllu men yeşau ve yehdi men yeşau, fe la tezheb nefsuke aleyhim haserat, innallahe alimun bima yesneun.', 'Yaptığı kötü işleri kendisine yakıştıran ve onu güzel gören kimseye ne demeli? Allah,  Hak edeni saptırır,  hak edeni de doğru yola iletir[1]. Dolayısıyla onlar için üzülüp kendini harap etme. Allah,  onların yapmakta olduklarını en iyi bilendir.', 'افمن زين له سو عمله فراه حسنا فان الله يضل من يشا ويهدي من يشا فلا تذهب نفسك عليهم حسرت ان الله عليم بما يصنعون'),
(3669, 35, 9, 'وَاللّٰهُ الَّـذ۪ٓي اَرْسَلَ الرِّيَاحَ فَتُث۪يرُ سَحَاباً فَسُقْنَاهُ اِلٰى بَلَدٍ مَيِّتٍ فَاَحْيَيْنَا بِهِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ  كَذٰلِكَ النُّشُورُ', 'Vallahullezi, erseler riyaha fe tusiru sehaben fe suknahu ila beledin meyyitin fe ahyeyna bihil arda ba\'de mevtiha, kezaliken nuşur.', 'Allah,  rüzgarları göndererek bulutları harekete geçirendir. Sonra onu ölü bir beldeye yönelterek,  onunla,  ölü yeryüzüne hayat veririz. İşte yeniden diriliş de böyledir.', 'والله الذي ارسل الريح فتثير سحابا فسقنه الي بلد ميت فاحيينا به الارض بعد موتها كذلك النشور'),
(3670, 35, 10, 'مَنْ كَانَ يُر۪يدُ الْعِزَّةَ فَلِلّٰهِ الْعِزَّةُ جَم۪يعاًۜ اِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِـحُ يَرْفَعُهُۜ وَالَّذ۪ينَ يَمْكُرُونَ السَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَد۪يدٌۜ وَمَكْرُ اُو۬لٰٓئِكَ هُوَ يَبُورُ', 'Men kane yuridul izzete fe lillahil izzetu cemia, ileyhi yes\'adul kelimut tayyibu vel amelus salihu yerfeuh, vellezine yemkurunes seyyiati lehum azabun şedid, ve mekru ulaike huve yebur.', 'Kim izzet[1] istiyorsa,  bilsin ki izzet tamamen Allah\'a aittir. Temiz sözler[2] O\'na yükselir. Düzgün iş[3] onu[4] yükseltir. Kötülük planı yapanlar için,  şiddetli bir azap vardır. Kurdukları düzenler boşa gidecektir.', 'من كان يريد العزة فلله العزة جميعا اليه يصعد الكلم الطيب والعمل الصلح يرفعه والذين يمكرون السيات لهم عذاب شديد ومكر اوليك هو يبور'),
(3671, 35, 11, 'وَاللّٰهُ خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ جَعَلَكُمْ اَزْوَاجاًۜ وَمَا تَحْمِلُ مِنْ اُنْثٰى وَلَا تَضَعُ اِلَّا بِعِلْمِه۪ۜ وَمَا يُعَمَّرُ مِنْ مُعَمَّرٍ وَلَا يُنْقَصُ مِنْ عُمُرِه۪ٓ  اِلَّا ف۪ي كِتَابٍۜ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَس۪يرٌ', 'Vallahu halakakum min turabin summe min nutfetin summe cealekum ezvaca, ve ma tahmilu min unsa ve la tedau illa bi ilmih, ve ma yuammeru min muammerin ve la yunkasu min umurihi illa fi kitab, inne zalike alallahi yesir.', 'Allah; sizi topraktan,  sonra nutfeden[1] yarattı. Sonra sizi çiftler kıldı. Hiçbir dişi,  O\'nun bilgisi olmadan ne hamile kalabilir ne de doğurabilir. Bir kimseye ömür verilmesi; ömrünün uzaması veya kısalması,  hepsi bir Kitap\'tadır.[2] Kuşkusuz bu Allah\'a kolaydır.', 'والله خلقكم من تراب ثم من نطفة ثم جعلكم ازوجا وما تحمل من انثي ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتب ان ذلك علي الله يسير'),
(3672, 35, 12, 'وَمَا يَسْتَوِي الْبَحْرَانِۗ هٰذَا عَذْبٌ فُرَاتٌ سَٓائِـغٌ شَرَابُهُ وَهٰذَا مِلْحٌ اُجَاجٌۜ وَمِنْ كُلٍّ تَأْكُلُونَ لَحْماً طَرِياًّ وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَاۚ وَتَرَى الْفُلْكَ ف۪يهِ مَوَاخِرَ لِتَبْتَغُوا مِنْ فَضْلِه۪ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Ve ma yestevil bahrani haza azbun furatun saigun şerabuhu ve haza milhun ucac, ve min kullin te\'kulune lahmen tariyyen ve testahricune hilyeten telbesuneha, ve terel fulke fihi mevahire li tebtegu min fadlihi ve leallekum teşkurun.', 'İki deniz bir değildir. Biri lezzetlidir,  tatlıdır. Susuzluğu gideren içimi rahat olandır. Diğeri tuzlu ve acıdır. Her ikisinden de taze et yersiniz. Ve her ikisinden de kullandığınız süs eşyası çıkarırsınız. O\'nun lütfundan rızık aramanız için,  onu yararak giden gemileri görürsün. Umulur ki şükredersiniz.', 'وما يستوي البحران هذا عذب فرات سايغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حلية تلبسونها وتري الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون'),
(3673, 35, 13, 'يُولِجُ الَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي الَّيْلِۙ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَۘ كُلٌّ يَجْر۪ي لِاَجَلٍ مُسَمًّىۜ ذٰلِكُمُ اللّٰهُ رَبُّكُمْ لَهُ الْمُلْكُۜ وَالَّذ۪ينَ تَدْعُونَ مِنْ دُونِه۪ مَا يَمْلِكُونَ مِنْ قِطْم۪يرٍۜ', 'Yulicul leyle fin nehari ve yulicun nehare fil leyli ve sehhareş şemse vel kamere kullun yecri li ecelin musemma, zalikumullahu rabbukum lehul mulk, vellezine ted\'une min dunihi ma yemlikune min kıtmir.', 'O,  geceyi gündüze,  gündüzü de geceye çevirir. Güneş\'i ve Ay\'ı buyruk altına aldı. Her biri belirlenmiş bir süreye kadar hareketini sürdürüyor. İşte bu,  Allah\'tır,  Rabb\'inizdir. Egemenlik O\'nundur. O\'nun yanı sıra çağırdığınız kimseler,  bir çekirdeğin zarına bile sahip değiller.', 'يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري لاجل مسمي ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3674, 35, 14, 'اِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَٓاءَكُمْۚ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْۜ وَيَوْمَ الْقِيٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْۜ وَلَا يُنَبِّئُكَ مِثْلُ خَب۪يرٍ۟', 'İn ted\'uhum la yesmeu duaekum, ve lev semiu mestecabu lekum, ve yevmel kıyameti yekfurune bi şirkikum, ve la yunebbiuke mislu habir.', 'Eğer onları çağırırsanız,  çağrınızı işitmezler. İşitmiş olsalar bile size cevap veremezler. Kıyamet Günü,  kendilerine yakıştırdığınız şirki reddederler. Sana,  Her Şeyden Haberdar Olan\'ın,  haber verdiği gibi hiç kimse haber veremez.', 'ان تدعوهم لا يسمعوا دعاكم ولو سمعوا ما استجابوا لكم ويوم القيمة يكفرون بشرككم ولا ينبيك مثل خبير'),
(3675, 35, 15, 'يَٓا اَيُّهَا النَّاسُ اَنْتُمُ الْفُقَـرَٓاءُ اِلَى اللّٰهِۚ وَاللّٰهُ هُوَ الْغَنِيُّ الْحَم۪يدُ', 'Ya eyyuhen nasu entumul fukarau ilallahi, vallahu huvel ganiyyul hamid.', 'Ey insanlar! Allah\'a muhtaç olanlar sizlersiniz. Allah ise hiçbir şeye muhtaç değildir. Övgüye layık olandır.', 'يايها الناس انتم الفقرا الي الله والله هو الغني الحميد'),
(3676, 35, 16, 'اِنْ يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَد۪يدٍۚ', 'İn yeşe\' yuzhibkum ve ye\'ti bi halkın cedid.', 'Eğer dilerse sizi yok eder ve yeni bir halk getirir.', 'ان يشا يذهبكم ويات بخلق جديد'),
(3677, 35, 17, 'وَمَا ذٰلِكَ عَلَى اللّٰهِ بِعَز۪يزٍ', 'Ve ma zalike alallahi bi aziz.', 'Bu,  Allah için asla güç bir şey değildir.', 'وما ذلك علي الله بعزيز'),
(3678, 35, 18, 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ اُخْرٰىۜ وَاِنْ تَدْعُ مُثْقَلَةٌ اِلٰى حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَيْءٌ وَلَوْ كَانَ ذَا قُرْبٰىۜ اِنَّمَا تُنْذِرُ الَّذ۪ينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ وَاَقَامُوا الصَّلٰوةَۜ وَمَنْ تَزَكّٰى فَاِنَّمَا يَتَزَكّٰى لِنَفْسِه۪ۜ وَاِلَى اللّٰهِ الْمَص۪يرُ', 'Ve la teziru vaziretun vizre uhra, ve in ted\'u muskaletun ila himliha la yuhmel minhu şey\'un ve lev kane za kurba, innema tunzirullezine yahşevne rabbehum bil gaybi ve ekamus salah, ve men tezekka fe innema yetezekka li nefsih, ve ilallahil masir.', 'Yük taşıyan birisi, [1] bir başkasının yükünü taşımaz.[1] Yükü ağır olan kimse,  bir başkasını yardıma çağırsa,  çağırdığı yakını da olsa ona yardım etmez.[2] Sen,  ancak görmedikleri halde Rabb\'ine içtenlikle saygı duyan ve salatı[3] ikame edenleri uyarırsın. Her kim arınırsa[4] kendisi için arınmış olur. Dönüş Allah\'adır.', 'ولا تزر وازرة وزر اخري وان تدع مثقلة الي حملها لا يحمل منه شي ولو كان ذا قربي انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلوة ومن تزكي فانما يتزكي لنفسه والي الله المصير'),
(3679, 35, 19, 'وَمَا يَسْتَوِي الْاَعْمٰى وَالْبَص۪يرُۙ', 'Ve ma yestevil a\'ma vel basir.', 'Körle gören bir değildir.[1]', 'وما يستوي الاعمي والبصير'),
(3680, 35, 20, 'وَلَا الظُّلُمَاتُ وَلَا النُّورُۙ', 'Ve lez zulumatu ve len nur.', 'Karanlık ve aydınlık bir değildir.', 'ولا الظلمت ولا النور'),
(3681, 35, 21, 'وَلَا الظِّلُّ وَلَا الْحَرُورُۚ', 'Ve lez zıllu ve lel harur.', 'Serinlik ve sıcaklık bir değildir.', 'ولا الظل ولا الحرور'),
(3682, 35, 22, 'وَمَا يَسْتَوِي الْاَحْيَٓاءُ وَلَا الْاَمْوَاتُۜ اِنَّ اللّٰهَ يُسْمِــعُ مَنْ يَشَٓاءُۚ وَمَٓا اَنْتَ بِمُسْمِــعٍ مَنْ فِي الْقُبُورِ', 'Ve ma yestevil ahyau ve lel emvat, innallahe yusmiu men yeşau, ve ma ente bi musmiin men fil kubur.', 'Dirilerle ölüler bir değildir. Kuşkusuz ki Allah,  hak edene[1] duyurur. Sen mezarlarda olanlara asla duyuramazsın.', 'وما يستوي الاحيا ولا الاموت ان الله يسمع من يشا وما انت بمسمع من في القبور'),
(3683, 35, 23, 'اِنْ اَنْتَ اِلَّا نَذ۪يرٌ', 'İn ente illa nezir.', 'Sen yalnızca bir uyarıcısın.', 'ان انت الا نذير'),
(3684, 35, 24, 'اِنَّٓا اَرْسَلْنَاكَ بِالْحَقِّ بَش۪يراً وَنَذ۪يراًۜ وَاِنْ مِنْ اُمَّةٍ اِلَّا خَلَا ف۪يهَا نَذ۪يرٌ', 'İnna erselnake bil hakkı beşiren ve nezira, ve in min ummetin illa hala fiha nezir.', 'Kuşkusuz Biz seni,  gerçek ile bir haber verici ve uyarıcı olarak gönderdik. Her ümmet[1] içinde bir uyarıcı geçmiştir.', 'انا ارسلنك بالحق بشيرا ونذيرا وان من امة الا خلا فيها نذير'),
(3685, 35, 25, 'وَاِنْ يُكَذِّبُوكَ فَقَدْ كَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْۚ جَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ وَبِالزُّبُرِ وَبِالْكِتَابِ الْمُن۪يرِ', 'Ve in yukezzibuke fe kad kezzebellezine min kablihim, caethum rusuluhum bil beyyinati ve biz zuburi ve bil kitabil munir.', 'Eğer seni yalanlıyorlarsa,  bil ki onlardan öncekiler de yalanlamışlardı. Onların resulleri,  onlara kanıt içeren bilgiyle,  sahifelerle ve aydınlatıcı kitaplarla gelmişlerdi.', 'وان يكذبوك فقد كذب الذين من قبلهم جاتهم رسلهم بالبينت وبالزبر وبالكتب المنير'),
(3686, 35, 26, 'ثُمَّ اَخَذْتُ الَّذ۪ينَ كَفَرُوا فَكَيْفَ كَانَ نَك۪يرِ۟', 'Summe ehaztullezine keferu fe keyfe kane nekir.', 'Sonra Kafirleri[1] yakaladım. Benim inkarım nasıl oldu?[2]', 'ثم اخذت الذين كفروا فكيف كان نكير'),
(3687, 35, 27, 'اَلَمْ تَرَ اَنَّ اللّٰهَ اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءًۚ فَاَخْرَجْنَا بِه۪ ثَمَرَاتٍ مُخْتَلِفاً اَلْوَانُهَاۜ وَمِنَ الْجِبَالِ جُدَدٌ ب۪يضٌ وَحُمْرٌ مُخْتَلِفٌ اَلْوَانُهَا وَغَرَاب۪يبُ سُودٌ', 'E lem tere ennallahe enzele mines semai maen, fe ahrecna bihi semeratin muhtelifen elvanuha, ve minel cibali cudedun bidun ve humrun muhtelifun elvanuha ve garabibu sud.', 'Allah\'ın gökten su indirdiğini görmüyor musun? Onunla rengarenk ürünler çıkardık. Ve dağlarda da beyazlı,  kırmızılı ve çeşitli renklerde,  siyah ve simsiyah katmanlar oluşturduk.', 'الم تر ان الله انزل من السما ما فاخرجنا به ثمرت مختلفا الونها ومن الجبال جدد بيض وحمر مختلف الونها وغرابيب سود'),
(3688, 35, 28, 'وَمِنَ النَّاسِ وَالدَّوَٓابِّ وَالْاَنْعَامِ مُخْتَلِفٌ اَلْوَانُهُ كَذٰلِكَۜ اِنَّمَا يَخْشَى اللّٰهَ مِنْ عِبَادِهِ الْعُلَمٰٓؤُ۬اۜ اِنَّ اللّٰهَ عَز۪يزٌ غَفُورٌ', 'Ve minen nasi ved devabbi vel en\'ami muhtelifun elvanuhu kezalik, innema yahşallahe min ibadihil ulemau, innallahe azizun gafur.', 'İnsanlardan,  hayvanlardan ve diğer canlılardan da çeşitli renkte olanları vardır. Allah\'ın kullarından yalnız ilim sahibi[1] olanlar haşyet[2] ederler. Kuşkusuz ki Allah,  Mutlak Üstün Olan\'dır,  Çok Bağışlayıcı\'dır.', 'ومن الناس والدواب والانعم مختلف الونه كذلك انما يخشي الله من عباده العلموا ان الله عزيز غفور'),
(3689, 35, 29, 'اِنَّ الَّذ۪ينَ يَتْلُونَ كِتَابَ اللّٰهِ وَاَقَامُوا الصَّلٰوةَ وَاَنْفَقُوا مِمَّا رَزَقْنَاهُمْ سِراًّ وَعَلَانِيَةً يَرْجُونَ تِجَارَةً لَنْ تَبُورَۙ', 'İnnellezine yetlune kitaballahi ve ekamus salate ve enfeku mimma rezaknahum sirren ve alaniyeten yercune ticareten len tebur.', 'Kuşkusuz Allah\'ın Kitap\'ını okuyanlar,  salatı ikame edenler ve rızıklandırdığımız şeylerden gizli ve açık olarak ihtiyaç sahiplerine verenler,  asla kesilmeyecek bir kazanç umabilirler.', 'ان الذين يتلون كتب الله واقاموا الصلوة وانفقوا مما رزقنهم سرا وعلانية يرجون تجرة لن تبور'),
(3690, 35, 30, 'لِيُوَفِّيَهُمْ اُجُورَهُمْ وَيَز۪يدَهُمْ مِنْ فَضْلِه۪ۜ اِنَّهُ غَفُورٌ شَكُورٌ', 'Li yuveffiyehum ucurehum ve yezidehum min fadlih, innehu gafurun şekur.', 'Onlara,  yaptıklarının karşılığını lütfundan arttırarak fazlasıyla verir. Kuşkusuz ki O,  Çok Bağışlayıcı\'dır,  Yapılan Şeyin Karşılığını Veren\'dir.', 'ليوفيهم اجورهم ويزيدهم من فضله انه غفور شكور'),
(3691, 35, 31, 'وَالَّـذ۪ٓي اَوْحَيْنَٓا اِلَيْكَ مِنَ الْكِتَابِ هُوَ الْحَقُّ مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِۜ اِنَّ اللّٰهَ بِعِبَادِه۪ لَخَب۪يرٌ بَص۪يرٌ', 'Vellezi evhayna ileyke minel kitabi huvel hakku musaddikan lima beyne yedeyh, innallahe bi ibadihi le habirun basir.', 'Sana Kitap\'tan vahyettiğimiz,  kendisinden öncekileri tasdik edici olarak gerçektir. Kuşkusuz Allah,  Kullarından Haberdar Olan\'dır,  Her Şeyi Gören\'dir.', 'والذي اوحينا اليك من الكتب هو الحق مصدقا لما بين يديه ان الله بعباده لخبير بصير'),
(3692, 35, 32, 'ثُمَّ اَوْرَثْنَا الْكِتَابَ الَّذ۪ينَ اصْطَفَيْنَا مِنْ عِبَادِنَاۚ فَمِنْهُمْ ظَالِمٌ لِنَفْسِه۪ۚ وَمِنْهُمْ مُقْتَصِدٌۚ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِاِذْنِ اللّٰهِۜ ذٰلِكَ هُوَ الْفَضْلُ الْكَب۪يرُۜ', 'Summe evresnel kitabellezinastafeyna min ibadina, fe minhum zalimun li nefsih, ve minhum muktesid, ve minhum sabikun bil hayrati bi iznillah, zalike huvel fadlul kebir.', 'Sonra kullarımızdan seçtiğimiz kimselere Kitap\'ı miras bıraktık. Onlardan bir kısmı kendilerine zulmederler,  onlardan bir kısmı ortalama bir yol tutarlar,  onlardan bir kısmı da Allah\'ın izniyle hayırlarda önde giderler.[1] İşte büyük fazilet budur.', 'ثم اورثنا الكتب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرت باذن الله ذلك هو الفضل الكبير'),
(3693, 35, 33, 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ ف۪يهَا مِنْ اَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤً۬اۚ وَلِبَاسُهُمْ ف۪يهَا حَر۪يرٌ', 'Cennatu adnin yedhuluneha yuhallevne fiha min esavire min zehebin ve lu\'lua, ve libasuhum fiha harir.', 'Onların girecekleri yer Adn Cennetleridir. Orada,  altından bilezik ve incilerle süslenecekler. Giysileri ise ipektendir.', 'جنت عدن يدخلونها يحلون فيها من اساور من ذهب ولولوا ولباسهم فيها حرير'),
(3694, 35, 34, 'وَقَالُوا الْحَمْدُ لِلّٰهِ الَّـذ۪ٓي اَذْهَبَ عَنَّا الْحَزَنَۜ اِنَّ رَبَّـنَا لَغَفُورٌ شَكُورٌۙ', 'Ve kalul hamdu lillahillezi ezhebe annel hazen, inne rabbena le gafurun şekur.', '\"Bizden hüznü gideren Allah\'a hamdolsun. Rabb\'imiz gerçekten Çok Bağışlayıcı\'dır,  Yapılan Şeyin Karşılığını Veren\'dir.\" derler.', 'وقالوا الحمد لله الذي اذهب عنا الحزن ان ربنا لغفور شكور'),
(3695, 35, 35, 'اَلَّـذ۪ٓي اَحَلَّنَا دَارَ الْمُقَامَةِ مِنْ فَضْلِه۪ۚ لَا يَمَسُّنَا ف۪يهَا نَصَبٌ وَلَا يَمَسُّنَا ف۪يهَا لُغُوبٌ', 'Ellezi ehallena darel mukameti min fadlih, la yemessuna fiha nasabun ve la yemessuna fiha lugub.', 'O ki,  bizi lütfundan kalınacak bir yurda yerleştirdi. Orada bize bir yorgunluk dokunmayacak ve orada bize bir usanç gelmeyecek.', 'الذي احلنا دار المقامة من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب'),
(3696, 35, 36, 'وَالَّذ۪ينَ كَفَرُوا لَهُمْ نَارُ جَهَنَّمَۚ لَا يُقْضٰى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَاۜ  كَذٰلِكَ نَجْز۪ي كُلَّ كَفُورٍۚ', 'Vellezine keferu lehum naru cehennem, la yukda aleyhim fe yemutu ve la yuhaffefu anhum min azabiha, kezalike neczi kulle kefur.', 'Kafirlere gelince,  onlar için Cehennem ateşi vardır. Ölmelerine karar verilmez ki ölüp kurtulsunlar. Onların azaplarından da hafifletilmez. İşte bütün kafirleri böyle cezalandırırız.', 'والذين كفروا لهم نار جهنم لا يقضي عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور'),
(3697, 35, 37, 'وَهُمْ يَصْطَرِخُونَ ف۪يهَاۚ رَبَّنَٓا اَخْرِجْنَا نَعْمَلْ صَالِحاً غَيْرَ الَّذ۪ي كُنَّا نَعْمَلُۜ اَوَلَمْ نُعَمِّرْكُمْ مَا يَتَذَكَّرُ ف۪يهِ مَنْ تَذَكَّرَ وَجَٓاءَكُمُ النَّذ۪يرُۜ فَذُوقُوا فَمَا لِلظَّالِم۪ينَ مِنْ نَص۪يرٍ۟', 'Ve hum yastarihune fiha, rabbena ahricna na\'mel salihan gayrellezi kunna na\'mel, e ve lem nuammirkum ma yetezekkeru fihi men tezekkere ve caekumun nezir, fe zuku fe ma liz zalimine min nasir.', 'Onlar,  orada yardım için bağırıp çağırırlar: \"Rabb\'imiz! Bizi çıkar,  daha önce yaptığımızdan başka,  düzgün amel yapalım.\" Size dünyada öğüt dinleyecek kimsenin,  öğüt dinlemesine yetecek kadar bir ömür vermedik mi? Size uyarıcı gelmedi mi? O halde tadın! Artık zalimler için bir yardımcı yoktur.', 'وهم يصطرخون فيها ربنا اخرجنا نعمل صلحا غير الذي كنا نعمل اولم نعمركم ما يتذكر فيه من تذكر وجاكم النذير فذوقوا فما للظلمين من نصير'),
(3698, 35, 38, 'اِنَّ اللّٰهَ عَالِمُ غَيْبِ السَّمٰوَاتِ وَالْاَرْضِۜ اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'İnnallahe alimu gaybis semavati vel ard, innehu alimun bi zatis sudur.', 'Kuşkusuz Allah,  göklerin ve yerin gaybını[1] bilendir. Kuşkusuz O,  göğüslerde olanı en iyi bilendir.[2]', 'ان الله علم غيب السموت والارض انه عليم بذات الصدور'),
(3699, 35, 39, 'هُوَ الَّذ۪ي جَعَلَكُمْ خَلَٓائِفَ فِي الْاَرْضِۜ فَمَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُۜ وَلَا يَز۪يدُ الْكَافِر۪ينَ كُفْرُهُمْ عِنْدَ رَبِّهِمْ اِلَّا مَقْتاًۚ وَلَا يَز۪يدُ الْكَافِر۪ينَ كُفْرُهُمْ اِلَّا خَسَاراً', 'Huvellezi cealekum halaife fil ard, fe men kefere fe aleyhi kufruh, ve la yezidul kafirine kufruhum inde rabbihim illa makta, ve la yezidul kafirine kufruhum illa hasara.', 'Sizi yeryüzünde halifeler[1] yapan O\' dur. Kim gerçeğe Kafirlik ederse,  Küfretmesi[2] kendi zararınadır. Kafirlerin Küfrleri,  kendileri için Rabb\'lerinin yanında gazabı artırmaktan başka bir şeye yaramaz. Kafirlerin,  küfrü sadece kendilerinin zararını artırır.', 'هو الذي جعلكم خليف في الارض فمن كفر فعليه كفره ولا يزيد الكفرين كفرهم عند ربهم الا مقتا ولا يزيد الكفرين كفرهم الا خسارا'),
(3700, 35, 40, 'قُلْ اَرَاَيْتُمْ شُرَكَٓاءَكُمُ الَّذ۪ينَ تَدْعُونَ مِنْ دُونِ اللّٰهِۜ اَرُون۪ي مَاذَا خَلَقُوا مِنَ الْاَرْضِ اَمْ لَهُمْ شِرْكٌ فِي السَّمٰوَاتِۚ اَمْ اٰتَيْنَاهُمْ كِتَاباً فَهُمْ عَلٰى بَيِّنَتٍ مِنْهُۚ بَلْ اِنْ يَعِدُ الظَّالِمُونَ بَعْضُهُمْ بَعْضاً اِلَّا غُرُوراً', 'Kul ereeytum şurekaekumullezine ted\'une min dunillah, eruni maza halaku minel ardı em lehum şirkun fis semavat, em ateynahum kitaben fe hum ala beyyinetin minh, bel in yaıduz zalimune ba\'duhum ba\'dan illa gurura.', 'De ki: \"Allah\'ın yanı sıra yakardıklarınıza bir bakın bakalım! Onların,  yeryüzünde yarattıkları bir şey varsa bana gösterin! Yoksa onların göklerde bir ortakları mı var? Ya da onlara bir kitap verdik de onlar,  ondan bir beyyine[1] üzerinde midirler? Hayır,  hayır! Zalimlerin birbirlerine verdikleri sözler[2],  aldatmacadan başka bir şey değildir.', 'قل اريتم شركاكم الذين تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموت ام اتينهم كتبا فهم علي بينت منه بل ان يعد الظلمون بعضهم بعضا الا غرورا'),
(3701, 35, 41, 'اِنَّ اللّٰهَ يُمْسِكُ السَّمٰوَاتِ وَالْاَرْضَ اَنْ تَزُولَاۚ وَلَئِنْ زَالَتَٓا اِنْ اَمْسَكَهُمَا مِنْ اَحَدٍ مِنْ بَعْدِه۪ۜ اِنَّهُ  كَانَ حَل۪يماً غَفُوراً', 'İnnallahe yumsikus semavati vel arda en tezula, ve le in zaleta in emsekehuma min ehadin min ba\'dih, innehu kane halimen gafura.', 'Gökleri ve yeri koyduğu yasalarla yok olmaktan koruyan Allah\'tır. Ant olsun ki eğer onlar yok olurlarsa,  o ikisini O\'ndan başka tutacak yoktur. Kuşkusuz O,  Çok Şefkatli\'dir. Çok Bağışlayıcı\'dır.', 'ان الله يمسك السموت والارض ان تزولا ولين زالتا ان امسكهما من احد من بعده انه كان حليما غفورا'),
(3702, 35, 42, 'وَاَقْسَمُوا بِاللّٰهِ جَهْدَ اَيْمَانِهِمْ لَئِنْ جَٓاءَهُمْ نَذ۪يرٌ لَيَكُونُنَّ اَهْدٰى مِنْ اِحْدَى الْاُمَمِۚ فَلَمَّا جَٓاءَهُمْ نَذ۪يرٌ مَا زَادَهُمْ اِلَّا نُفُوراًۙ', 'Ve aksemu billahi cehde eymanihim le in caehum nezirun le yekununne ehda min ihdel umem, fe lemma caehum nezirun ma zadehum illa nufura.', 'Eğer kendilerine bir uyarıcı gelirse,  diğer toplumlardan kesinlikle daha doğru yolda olacaklarına dair var güçleriyle Allah\'a yeminler etmişlerdi. Fakat onlara uyarıcı geldiğinde bu onların yalnızca nefretlerini artırdı.', 'واقسموا بالله جهد ايمنهم لين جاهم نذير ليكونن اهدي من احدي الامم فلما جاهم نذير ما زادهم الا نفورا'),
(3703, 35, 43, 'اِسْتِكْبَاراً فِي الْاَرْضِ وَمَكْرَ السَّيِّئِۜ وَلَا يَح۪يقُ الْمَكْرُ السَّيِّئُ اِلَّا بِاَهْلِه۪ۜ فَهَلْ يَنْظُرُونَ اِلَّا سُنَّتَ الْاَوَّل۪ينَۚ فَلَنْ تَجِدَ لِسُنَّتِ اللّٰهِ تَبْد۪يلاًۚ وَلَنْ تَجِدَ لِسُنَّتِ اللّٰهِ تَحْو۪يلاً', 'İstikbaren fil ardı ve mekres seyyii, ve la yahikul mekrus seyyiu illa bi ehlih, fe hel yenzurune illa sunnetel evvelin, fe len tecide li sunnetillahi tebdila, ve len tecide li sunnetillahi tahvila.', 'Yeryüzünde büyüklendiler ve kötü planlar yaptılar. Oysa kötü planlar,  sahibinden başkasını kuşatmaz. Öyleyse onlar,  öncekilerin sünnetinden[1] başkasını mı gözlüyorlar? Halbuki Allah\'ın sünnetinde[2] asla bir değişiklik bulamazsın. Allah\'ın sünnetinde asla bir sapma bulamazsın.', 'استكبارا في الارض ومكر السيي ولا يحيق المكر السيي الا باهله فهل ينظرون الا سنت الاولين فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا'),
(3704, 35, 44, 'اَوَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلِهِمْ وَكَانُٓوا اَشَدَّ مِنْهُمْ قُوَّةًۜ وَمَا كَانَ اللّٰهُ لِيُعْجِزَهُ مِنْ شَيْءٍ فِي السَّمٰوَاتِ وَلَا فِي الْاَرْضِۜ اِنَّهُ كَانَ عَل۪يماً قَد۪يراً', 'E ve lem yesiru fil ardı fe yenzuru keyfe kane akıbetullezine min kablihim ve kanu eşedde minhum kuvveh, ve ma kanallahu li yu\'cizehu min şey\'in fis semavati ve la fil ard, innehu kane alimen kadira.', 'Yeryüzünde dolaşıp,  kendilerinden öncekilerinin sonları nasıl olmuş,  bir bakmadılar mı? Oysaki onlar,  güç olarak kendilerinden daha güçlüydüler. Göklerde ve yerde Allah\'ı aciz bırakacak hiçbir şey yoktur. O,  Her Şeyi Bilen\'dir,  Her Şeye Gücü Yeten\'dir.', 'اولم يسيروا في الارض فينظروا كيف كان عقبة الذين من قبلهم وكانوا اشد منهم قوة وما كان الله ليعجزه من شي في السموت ولا في الارض انه كان عليما قديرا'),
(3705, 35, 45, 'وَلَوْ يُؤَاخِذُ اللّٰهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلٰى ظَهْرِهَا مِنْ دَٓابَّةٍ وَلٰكِنْ يُؤَخِّرُهُمْ اِلٰٓى اَجَلٍ مُسَمًّىۚ فَاِذَا جَٓاءَ اَجَلُهُمْ فَاِنَّ اللّٰهَ كَانَ بِعِبَادِه۪ بَص۪يراً', 'Ve lev yuahızullahun nase bima kesebu ma tereke ala zahriha min dabbetin, ve lakin yuahhıruhum ila ecelin musemma, fe iza cae eceluhum fe innallahe kane bi ibadihi basira.', 'Eğer Allah,  insanların yaptıklarının hesabını hemen görecek olsaydı,  yeryüzünde hiçbir canlı bırakmazdı. Fakat O,  onlara belli bir zamana kadar süre vermektedir. Belirlenen süre dolduğu zaman da kuşkusuz Allah kendi kullarını en iyi görendir.[1]', 'ولو يواخذ الله الناس بما كسبوا ما ترك علي ظهرها من دابة ولكن يوخرهم الي اجل مسمي فاذا جا اجلهم فان الله كان بعباده بصيرا'),
(3706, 36, 1, 'يٰسٓۜ', 'Ya sin.', 'Ya-Sin.', 'يس'),
(3707, 36, 2, 'وَالْقُرْاٰنِ الْحَك۪يمِۙ', 'Vel kur\'anil hakim.', 'Hakim[1] Kur\'an\'a ant olsun.', 'والقران الحكيم'),
(3708, 36, 3, 'اِنَّكَ لَمِنَ الْمُرْسَل۪ينَۙ', 'İnneke leminel murselin.', 'Kuşkusuz sen,  gönderilmiş elçilerdensin.', 'انك لمن المرسلين'),
(3709, 36, 4, 'عَلٰى صِرَاطٍ مُسْتَق۪يمٍۜ', 'Ala sıratın mustekim.', 'Dosdoğru bir yoldasın;', 'علي صرط مستقيم'),
(3710, 36, 5, 'تَنْز۪يلَ الْعَز۪يزِ الرَّح۪يمِۙ', 'Tenzilel azizir rahim.', 'Bu Kur\'an,  Mutlak Üstün ve Rahmeti Kesintisiz olan tarafından,', 'تنزيل العزيز الرحيم'),
(3711, 36, 6, 'لِتُنْذِرَ قَوْماً مَٓا اُنْذِرَ اٰبَٓاؤُ۬هُمْ فَهُمْ غَافِلُونَ', 'Li tunzire kavmen ma unzire abauhum fe hum gafilun.', 'Ataları uyarıldığı halde[2] yine de gaflet içinde olan bir halkı uyarman için indirilmiştir.', 'لتنذر قوما ما انذر اباوهم فهم غفلون'),
(3712, 36, 7, 'لَقَدْ حَقَّ الْقَوْلُ عَلٰٓى اَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'Lekad hakkal kavlu ala ekserihim fe hum la yu\'minun.', 'Ant olsun ki,  onların çoğu üzerine söz[1] hakk oldu. Artık onlar inanmazlar.', 'لقد حق القول علي اكثرهم فهم لا يومنون'),
(3713, 36, 8, 'اِنَّا جَعَلْنَا ف۪ٓي اَعْنَاقِهِمْ اَغْلَالاً فَهِيَ اِلَى الْاَذْقَانِ فَهُمْ مُقْمَحُونَ', 'İnna cealna fi a\'nakıhim aglalen fe hiye ilel ezkani fe hum mukmehun.', 'Biz,  onların boyunlarına,  çenelerine kadar dayanan demir halkalar geçirdik. Bu nedenle başları sürekli yukarıda kalkık olanlardır.[1]', 'انا جعلنا في اعنقهم اغللا فهي الي الاذقان فهم مقمحون'),
(3714, 36, 9, 'وَجَعَلْنَا مِنْ بَيْنِ اَيْد۪يهِمْ سَداًّ وَمِنْ خَلْفِهِمْ سَداًّ فَاَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ', 'Ve cealna min beyni eydihim sedden ve min halfihim sedden fe agşeynahum fe hum la yubsırun.', 'Önlerine ve arkalarına birer set çektik[1]. Böylece onları perdeledik. Artık gerçeği görmezler.[2]', 'وجعلنا من بين ايديهم سدا ومن خلفهم سدا فاغشينهم فهم لا يبصرون'),
(3715, 36, 10, 'وَسَوَٓاءٌ عَلَيْهِمْ ءَاَنْذَرْتَهُمْ اَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ', 'Ve sevaun aleyhim e enzertehum em lem tunzirhum la yu\'minun.', 'Uyarsan da uyarmasan da onlar için birdir. Onlar inanmazlar.', 'وسوا عليهم انذرتهم ام لم تنذرهم لا يومنون'),
(3716, 36, 11, 'اِنَّمَا تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشِيَ الرَّحْمٰنَ بِالْغَيْبِۚ فَبَشِّرْهُ بِمَغْفِرَةٍ وَاَجْرٍ كَر۪يمٍ', 'İnnema tunziru menittebeaz zikre ve haşiyer rahmane bil gayb, fe beşşirhu bi magfiretin ve ecrin kerim.', 'Sen ancak Zikir\'e[1] uyan ve görmediği halde Rahman\'a haşyet[2] duyan kimseyi uyarabilirsin.[3] İşte böylesine bağışlanma ve çok şerefli bir ödülü haber ver.', 'انما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفرة واجر كريم'),
(3717, 36, 12, 'اِنَّا نَحْنُ نُحْـيِ الْمَوْتٰى وَنَكْتُبُ مَا قَدَّمُوا وَاٰثَارَهُمْۜ وَكُلَّ شَيْءٍ اَحْصَيْنَاهُ ف۪ٓي اِمَامٍ مُب۪ينٍ۟', 'İnna nahnu nuhyil mevta ve nektubu ma kaddemu ve asarehum ve kulle şey\'in ahsaynahu fi imamin mubin.', 'Kuşkusuz ölüleri Biz diriltiriz Biz. Önceden yapıp gönderdiklerini ve geride bıraktıklarını yazarız. Biz her şeyi bir \"imam-ı mübin\"de[1] kayıt altına almışızdır.', 'انا نحن نحي الموتي ونكتب ما قدموا واثرهم وكل شي احصينه في امام مبين'),
(3718, 36, 13, 'وَاضْرِبْ لَهُمْ مَثَلاً اَصْحَابَ الْقَرْيَةِۢ اِذْ جَٓاءَهَا الْمُرْسَلُونَۚ', 'Vadrıb lehum meselen ashabel karyeh, iz cae hel murselun.', 'Onlara,  o kentin halkını örnek ver. Hani,  onlara resuller gelmişti.', 'واضرب لهم مثلا اصحب القرية اذ جاها المرسلون'),
(3719, 36, 14, 'اِذْ اَرْسَلْـنَٓا اِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُٓوا اِنَّٓا اِلَيْكُمْ مُرْسَلُونَ', 'İz erselna ileyhimusneyni fe kezzebuhuma fe azzezna bi salisin fe kalu inna ileykum murselun.', 'Onlara iki resul göndermiştik. Fakat ikisini de yalanladılar. Bunun üzerine üçüncü ile destekledik. Dediler ki: \"Biz,  size gönderilmiş resulleriz.\"', 'اذ ارسلنا اليهم اثنين فكذبوهما فعززنا بثالث فقالوا انا اليكم مرسلون'),
(3720, 36, 15, 'قَالُوا مَٓا اَنْتُمْ اِلَّا بَشَرٌ مِثْلُنَاۙ وَمَٓا اَنْزَلَ الرَّحْمٰنُ مِنْ شَيْءٍۙ اِنْ اَنْتُمْ اِلَّا تَكْذِبُونَ', 'Kalu ma entum illa beşerun misluna ve ma enzeler rahmanu min şey\'in in entum illa tekzibun.', 'Onlar: \"Siz de bizim gibi birer beşersiniz. Rahman herhangi bir şey indirmedi. Siz sadece yalan söylüyorsunuz.\" dediler.', 'قالوا ما انتم الا بشر مثلنا وما انزل الرحمن من شي ان انتم الا تكذبون'),
(3721, 36, 16, 'قَالُوا رَبُّنَا يَعْلَمُ اِنَّٓا اِلَيْكُمْ لَمُرْسَلُونَ', 'Kalu rabbuna ya\'lemu inna ileykum le murselun.', '\"Rabb\'imiz biliyor ki,  biz gerçekten size gönderilmiş resulleriz.\" dediler.', 'قالوا ربنا يعلم انا اليكم لمرسلون'),
(3722, 36, 17, 'وَمَا عَلَيْنَٓا اِلَّا الْبَلَاغُ الْمُب۪ينُ', 'Ve ma aleyna illel belagul mubin.', '\"Bize düşen yalnızca açıkça iletmektir.\"', 'وما علينا الا البلغ المبين'),
(3723, 36, 18, 'قَالُٓوا اِنَّا تَطَيَّرْنَا بِكُمْۚ لَئِنْ لَمْ تَنْتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ مِنَّا عَذَابٌ اَل۪يمٌ', 'Kalu inna tetayyerna bi kum, le in lem tentehu le nercumennekum ve le yemessennekum minna azabun elim.', '\"Siz bize kesinlikle uğursuzluk getirdiniz. Eğer vazgeçmezseniz,  kesinlikle sizi taşlarız. Ve bizden size çok acıklı bir azap dokunur.\" dediler.', 'قالوا انا تطيرنا بكم لين لم تنتهوا لنرجمنكم وليمسنكم منا عذاب اليم'),
(3724, 36, 19, 'قَالُوا طَٓائِرُكُمْ مَعَكُمْۜ اَئِنْ ذُكِّرْتُمْۜ بَلْ اَنْتُمْ قَوْمٌ مُسْرِفُونَ', 'Kalu tairikum meakum, e in zukkirtum, bel entum kavmun musrifun.', '\"Uğursuzluğunuz kendinizdendir. Size öğüt verildi diye mi?[1] Hayır! Siz müsrif[2] bir halksınız.\" dediler.', 'قالوا طيركم معكم اين ذكرتم بل انتم قوم مسرفون'),
(3725, 36, 20, 'وَجَٓاءَ مِنْ اَقْصَا الْمَد۪ينَةِ رَجُلٌ يَسْعٰى قَالَ يَا قَوْمِ اتَّبِعُوا الْمُرْسَل۪ينَۙ', 'Ve cae min aksal medineti raculun yes\'a kale ya kavmittebiul murselin.', 'Şehrin en uzak yerinden bir adam koşarak geldi: \"Ey halkım,  gönderilmiş olan resullere uyun!\" dedi.', 'وجا من اقصا المدينة رجل يسعي قال يقوم اتبعوا المرسلين'),
(3726, 36, 21, 'اِتَّبِعُوا مَنْ لَا يَسْـَٔلُكُمْ اَجْراً وَهُمْ مُهْتَدُونَ', 'İttebiu men la yes\'elukum ecren ve hum muhtedun.', '\"Sizden herhangi bir karşılık beklemeyen bu kimselere uyun. Onlar doğru yolda olanlardır.\"', 'اتبعوا من لا يسلكم اجرا وهم مهتدون'),
(3727, 36, 22, 'وَمَا لِيَ لَٓا اَعْبُدُ الَّذ۪ي فَطَرَن۪ي وَاِلَيْهِ تُرْجَعُونَ', 'Ve ma liye la a\'budullezi fatarani ve ileyhi turceun.', '\"Ben,  niçin benim fıtratımı[1] belirleyene kulluk etmeyeyim? Siz de O\'na döndürüleceksiniz.\"', 'وما لي لا اعبد الذي فطرني واليه ترجعون'),
(3728, 36, 23, 'ءَاَتَّخِذُ مِنْ دُونِه۪ٓ اٰلِهَةً اِنْ يُرِدْنِ الرَّحْمٰنُ بِضُرٍّ لَا تُغْنِ عَنّ۪ي شَفَاعَتُهُمْ شَيْـٔاً وَلَا يُنْقِذُونِۚ', 'E ettehızu min dunihi aliheten in yuridnir rahmanu bi durrin la tugni anni şefaatuhum şey\'en ve la yunkızun.', '\"Ben,  O\'nun yanı sıra ilahlar edinir miyim? Eğer Rahman,  bana bir zarar dilerse,  onların şefaatinin[1] bana hiçbir yararı olmaz. Onlar beni kurtaramazlar.\"', 'اتخذ من دونه الهة ان يردن الرحمن بضر لا تغن عني شفعتهم شيا ولا ينقذون'),
(3729, 36, 24, 'اِنّ۪ٓي اِذاً لَف۪ي ضَلَالٍ مُب۪ينٍ', 'İnni izen le fi dalalin mubin.', '\"Öyle olsaydı[1] ben,  kesinlikle apaçık bir sapkınlık içinde olurdum.\"', 'اني اذا لفي ضلل مبين'),
(3730, 36, 25, 'اِنّ۪ٓي اٰمَنْتُ بِرَبِّكُمْ فَاسْمَعُونِۜ', 'İnni amentu bi rabbikum fesmeun.', '\"Ben,  sizin de Rabb\'iniz olana inandım. Beni dinleyin!\"', 'اني امنت بربكم فاسمعون'),
(3731, 36, 26, 'ق۪يلَ ادْخُلِ الْجَنَّةَۜ قَالَ يَا لَيْتَ قَوْم۪ي يَعْلَمُونَۙ', 'Kiled hulil cenneh, kale ya leyte kavmi ya\'lemun.', 'Ona,  \"Cennete gir!\" denildi. \"Keşke halkım bilseydi;\"', 'قيل ادخل الجنة قال يليت قومي يعلمون'),
(3732, 36, 27, 'بِمَا غَفَرَ ل۪ي رَبّ۪ي وَجَعَلَن۪ي مِنَ الْمُكْرَم۪ينَ', 'Bima gafere li rabbi ve cealeni minel mukremin.', '\"Rabb\'imin beni bağışladığını ve ikram edilenlerden yaptığını.\"', 'بما غفر لي ربي وجعلني من المكرمين'),
(3733, 36, 28, 'وَمَٓا اَنْزَلْنَا عَلٰى قَوْمِه۪ مِنْ بَعْدِه۪ مِنْ جُنْدٍ مِنَ السَّمَٓاءِ وَمَا كُنَّا مُنْزِل۪ينَ', 'Ve ma enzelna ala kavmihi min ba\'dihi min cundin mines semai ve ma kunna munzilin.', 'Ondan sonra,  halkının üzerine gökten hiçbir ordu indirmedik,  indirecek de değildik!', 'وما انزلنا علي قومه من بعده من جند من السما وما كنا منزلين'),
(3734, 36, 29, 'اِنْ كَانَتْ اِلَّا صَيْحَةً وَاحِدَةً فَاِذَا هُمْ خَامِدُونَ', 'İn kanet illa sayhaten vahıdetenfe iza hum hamidun.', 'Sadece bir sayha![1] O zaman onlar sönenler oldular!', 'ان كانت الا صيحة وحدة فاذا هم خمدون'),
(3735, 36, 30, 'يَا حَسْرَةً عَلَى الْعِبَادِۚ مَا يَأْت۪يهِمْ مِنْ رَسُولٍ اِلَّا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Ya hasreten alel ıbad, ma ye\'tihim min resulin illa kanu bihi yestehziun.', 'Yazıklar olsun o kullara! Kendilerine gelen her resulle alay ettiler.', 'يحسرة علي العباد ما ياتيهم من رسول الا كانوا به يستهزون'),
(3736, 36, 31, 'اَلَمْ يَرَوْا كَمْ اَهْلَكْنَا قَبْلَهُمْ مِنَ الْقُرُونِ اَنَّهُمْ اِلَيْهِمْ لَا يَرْجِعُونَ', 'E lem yerev kem ehlekna kablehum minel kuruni ennehum ileyhim la yerciun.', 'Kendilerinden önce nice nesilleri yok ettiğimizi ve bir daha geri dönemediklerini düşünmezler mi?', 'الم يروا كم اهلكنا قبلهم من القرون انهم اليهم لا يرجعون'),
(3737, 36, 32, 'وَاِنْ كُلٌّ لَمَّا جَم۪يعٌ لَدَيْنَا مُحْضَرُونَ۟', 'Ve in kullun lemma cemiun ledeyna muhdarun.', 'Onların hepsi de toplanıp kesinlikle karşımızda hazır bulundurulacaklardır.', 'وان كل لما جميع لدينا محضرون'),
(3738, 36, 33, 'وَاٰيَةٌ لَهُمُ الْاَرْضُ الْمَيْتَةُۚ اَحْيَيْنَاهَا وَاَخْرَجْنَا مِنْهَا حَباًّ فَمِنْهُ يَأْكُلُونَ', 'Ve ayetun lehumul ardul meyteh, ahyeynaha ve ahrecna minha habben fe minhu ye\'kulun.', 'Ölü toprak,  onlara bir ayettir.[1] Onu canlandırdık ve ondan ürünler çıkardık. Böylece ondan yerler.', 'واية لهم الارض الميتة احيينها واخرجنا منها حبا فمنه ياكلون'),
(3739, 36, 34, 'وَجَعَلْنَا ف۪يهَا جَنَّاتٍ مِنْ نَخ۪يلٍ وَاَعْنَابٍ وَفَجَّرْنَا ف۪يهَا مِنَ الْعُيُونِۙ', 'Ve cealna fiha cennatin min nahilin ve a\'nabin ve feccerna fiha minel uyun.', 'Orada hurma ve üzüm bahçeleri yaptık. Ve orada pınarlar akıttık.', 'وجعلنا فيها جنت من نخيل واعنب وفجرنا فيها من العيون'),
(3740, 36, 35, 'لِيَأْكُلُوا مِنْ ثَمَرِه۪ۙ وَمَا عَمِلَتْهُ اَيْد۪يهِمْۜ اَفَلَا يَشْكُرُونَ', 'Li ye\'kulu min semerihi ve ma amilethu eydihim, e fe la yeşkurun.', 'Onun ürünlerinden ve elleriyle yaptıklarından yesinler diye. Hala şükretmeyecekler mi?', 'لياكلوا من ثمره وما عملته ايديهم افلا يشكرون'),
(3741, 36, 36, 'سُبْحَانَ الَّذ۪ي خَلَقَ الْاَزْوَاجَ كُلَّهَا مِمَّا تُنْبِتُ الْاَرْضُ وَمِنْ اَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', 'Subhanellezi halakal ezvace kulleha mimma tunbitulardu ve min enfusihim ve mimma la ya\'lemun.', 'Yerin bitirdiklerinden,  kendilerinden ve bilemeyecekleri şeylerden çiftler yaratan,  O,  Sübhan\'dır.[1]', 'سبحن الذي خلق الازوج كلها مما تنبت الارض ومن انفسهم ومما لا يعلمون'),
(3742, 36, 37, 'وَاٰيَةٌ لَهُمُ الَّيْلُۚ نَسْلَخُ مِنْهُ النَّهَارَ فَاِذَا هُمْ مُظْلِمُونَۙ', 'Ve ayetun lehumul leyl, neslehu minhun nehare fe iza hum muzlimun.', 'Gece de onlar için bir ayettir[1]. Ondan gündüzü çekip alırız da onlar karanlıkta kalırlar.', 'واية لهم اليل نسلخ منه النهار فاذا هم مظلمون'),
(3743, 36, 38, 'وَالشَّمْسُ تَجْر۪ي لِمُسْتَقَرٍّ لَهَاۜ ذٰلِكَ تَقْد۪يرُ الْعَز۪يزِ الْعَل۪يمِۜ', 'Veş şemsu tecri li mustekarrin leha, zalike takdirul azizil alim.', 'Güneş,  kendisi için karar kılınan yörüngesinde akar gider. İşte bu Mutlak Üstün Olan\'ın,  Her Şeyi Bilen\'in yasasıdır.', 'والشمس تجري لمستقر لها ذلك تقدير العزيز العليم'),
(3744, 36, 39, 'وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتّٰى عَادَ كَالْعُرْجُونِ الْقَد۪يمِ', 'Vel kamere kaddernahu menazile hatta adekel urcunil kadim.', 'Ay\'a da menziller takdir ettik. Sonunda kuru bir hurma dalına döner.', 'والقمر قدرنه منازل حتي عاد كالعرجون القديم'),
(3745, 36, 40, 'لَا الشَّمْسُ يَنْبَغ۪ي لَـهَٓا اَنْ تُدْرِكَ الْقَمَرَ وَلَا الَّيْلُ سَابِقُ النَّهَارِۜ وَكُلٌّ ف۪ي فَلَكٍ يَسْبَحُونَ', 'Leş şemsu yenbegi leha en tudrikel kamere ve lel leylu sabikun nehar, ve kullun fi felekin yesbehun.', 'Ne Güneş Ay\'a erişebilir ve ne de gecenin gündüzü geçmesi mümkün olabilir. Hepsi de bir yörüngede hareket ederler.', 'لا الشمس ينبغي لها ان تدرك القمر ولا اليل سابق النهار وكل في فلك يسبحون'),
(3746, 36, 41, 'وَاٰيَةٌ لَهُمْ اَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِۙ', 'Ve ayetun lehum enna hamelna zurriyyetehum fil fulkil meşhun.', 'Onların soyunu dolu gemilerde taşımamız onlar için bir ayettir.[1]', 'واية لهم انا حملنا ذريتهم في الفلك المشحون'),
(3747, 36, 42, 'وَخَلَقْنَا لَهُمْ مِنْ مِثْلِه۪ مَا يَرْكَبُونَ', 'Ve halakna lehum min mislihi ma yerkebun.', 'Onlar için,  onun gibi binecekleri şeyler yarattık.', 'وخلقنا لهم من مثله ما يركبون'),
(3748, 36, 43, 'وَاِنْ نَشَأْ نُغْرِقْهُمْ فَلَا صَر۪يخَ لَهُمْ وَلَا هُمْ يُنْقَذُونَۙ', 'Ve in neşe\' nugrıkhum fe la sariha lehum ve la hum yunkazun.', 'Dilersek onları batırırız. Ne onlara yardım eden bulunur ne de onlar kurtulabilir.', 'وان نشا نغرقهم فلا صريخ لهم ولا هم ينقذون'),
(3749, 36, 44, 'اِلَّا رَحْمَةً مِنَّا وَمَتَاعاً اِلٰى ح۪ينٍ', 'İlla rahmeten minna ve metaan ila hin.', 'Bizden bir merhamet ve belli bir zamana kadar yararlandırmamız hariçtir.', 'الا رحمة منا ومتعا الي حين'),
(3750, 36, 45, 'وَاِذَا ق۪يلَ لَهُمُ اتَّقُوا مَا بَيْنَ اَيْد۪يكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'Ve iza kile lehumutteku ma beyne eydikum ve ma halfekum leallekum turhamun.', 'Onlara: \"Sahip olduğunuz ve olacağınız şeylerde takva[1] sahibi olun. Umulur ki böylece merhamet olunursunuz.\" denildiği zaman;', 'واذا قيل لهم اتقوا ما بين ايديكم وما خلفكم لعلكم ترحمون'),
(3751, 36, 46, 'وَمَا تَأْت۪يهِمْ مِنْ اٰيَةٍ مِنْ اٰيَاتِ رَبِّهِمْ اِلَّا كَانُوا عَنْهَا مُعْرِض۪ينَ', 'Ve ma te\'tihim min ayetin min ayati rabbihim illa kanu anha mu\'ridin.', 'Onlar,  Rabb\'lerinin ayetlerinden hangi ayet gelirse gelsin ondan yüz çevirenler oldular.', 'وما تاتيهم من اية من ايت ربهم الا كانوا عنها معرضين'),
(3752, 36, 47, 'وَاِذَا ق۪يلَ لَهُمْ اَنْفِقُوا مِمَّا رَزَقَكُمُ اللّٰهُۙ قَالَ الَّذ۪ينَ كَفَرُوا لِلَّذ۪ينَ اٰمَنُٓوا اَنُطْعِمُ مَنْ لَوْ يَشَٓاءُ اللّٰهُ اَطْعَمَهُۗ اِنْ اَنْتُمْ اِلَّا ف۪ي ضَلَالٍ مُب۪ينٍ', 'Ve iza kile lehum enfiku mimma rezakakumullahu kalellezine keferu lillezine amenu e nut\'imu men lev yeşaullahu at\'ameh, in entum illa fi dalalin mubin.', 'Onlara: \"Allah\'ın sizi rızıklandırdığı şeylerden infak[1] edin.\" dendiği zaman,  Kafirler,  iman edenlere: \"Allah\'ın dileseydi doyuracağı kimseyi biz mi doyuracağız? Siz ancak apaçık bir sapkınlık içindesiniz.\" dediler.', 'واذا قيل لهم انفقوا مما رزقكم الله قال الذين كفروا للذين امنوا انطعم من لو يشا الله اطعمه ان انتم الا في ضلل مبين'),
(3753, 36, 48, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadikin.', '\"Madem doğru söyleyenlerseniz,  bu vaat[1] ne zaman?\"[2] derler.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(3754, 36, 49, 'مَا يَنْظُرُونَ اِلَّا صَيْحَةً وَاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', 'Ma yenzurune illa sayhaten vahıdeten te\'huzuhum ve hum yahıssımun.', 'Onlar birbirleri ile çekişirlerken,  onları yakalayacak tek bir çığlıktan başkasını gözlemiyorlar.', 'ما ينظرون الا صيحة وحدة تاخذهم وهم يخصمون'),
(3755, 36, 50, 'فَلَا يَسْتَط۪يعُونَ تَوْصِيَةً وَلَٓا اِلٰٓى اَهْلِهِمْ يَرْجِعُونَ۟', 'Fe la yestetiune tavsiyeten ve la ila ehlihim yerciun.', 'Artık vasiyette bulunmaya da ailelerine dönmeye de güçleri yetmez.', 'فلا يستطيعون توصية ولا الي اهلهم يرجعون'),
(3756, 36, 51, 'وَنُفِـخَ فِي الصُّورِ فَاِذَا هُمْ مِنَ الْاَجْدَاثِ اِلٰى رَبِّهِمْ يَنْسِلُونَ', 'Ve nufiha fis suri fe iza hum minel ecdasi ila rabbihim yensilun.', 'Sur\'a[1] üflenmiştir! İşte o zaman onlar,  kabirlerinden Rabb\'lerine akın ederler.', 'ونفخ في الصور فاذا هم من الاجداث الي ربهم ينسلون'),
(3757, 36, 52, 'قَالُوا يَا وَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَ۔اۢ هٰذَا مَا وَعَدَ الرَّحْمٰنُ وَصَدَقَ الْمُرْسَلُونَ', 'Kalu ya veylena men beasena min merkadina, haza ma vaader rahmanuve sadakal murselun.', '\"Eyvah bize! Yattığımız yerden bizi kim kaldırdı?[1] Bu Rahman\'ın uyardığı şeydir. Resuller doğru söylemişler.\" dediler.', 'قالوا يويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون'),
(3758, 36, 53, 'اِنْ كَانَتْ اِلَّا صَيْحَةً وَاحِدَةً فَاِذَا هُمْ جَم۪يعٌ لَدَيْنَا مُحْضَرُونَ', 'İn kanet illa sayhaten vahıdeten fe iza hum cemiun ledeyna muhdarun.', 'Sadece tek bir sayha![1] İşte o zaman onların tamamı huzurumuza getirilirler.', 'ان كانت الا صيحة وحدة فاذا هم جميع لدينا محضرون'),
(3759, 36, 54, 'فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـٔاً وَلَا تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُونَ', 'Fel yevme la tuzlemu nefsun şey\'en ve la tuczevne illa ma kuntum ta\'melun.', 'Artık bugün kişi,  hiçbir haksızlık görmeyecek. Sadece yaptıklarınızın karşılığını göreceksiniz.', 'فاليوم لا تظلم نفس شيا ولا تجزون الا ما كنتم تعملون'),
(3760, 36, 55, 'اِنَّ اَصْحَابَ الْجَنَّةِ الْيَوْمَ ف۪ي شُغُلٍ فَاكِهُونَۚ', 'İnne ashabel cennetil yevme fi şugulin fakihun.', 'Kuşkusuz Cennet ehli bugün keyifli bir uğraş içindedir.', 'ان اصحب الجنة اليوم في شغل فكهون'),
(3761, 36, 56, 'هُمْ وَاَزْوَاجُهُمْ ف۪ي ظِلَالٍ عَلَى الْاَرَٓائِكِ مُتَّكِؤُ۫نَ', 'Hum ve ezvacuhum fi zılalin alel eraiki muttekiun.', 'Onlar ve eşleri gölgeliklerde tahtlar üzerine kurulmuşlardır.', 'هم وازوجهم في ظلل علي الارايك متكون'),
(3762, 36, 57, 'لَهُمْ ف۪يهَا فَاكِهَةٌ وَلَهُمْ مَا يَدَّعُونَۚ', 'Lehum fiha fakihetun ve lehum ma yeddeun.', 'Orada onlar için meyve ve gönüllerinin çektiği her şey vardır.', 'لهم فيها فكهة ولهم ما يدعون'),
(3763, 36, 58, 'سَلَامٌ قَوْلاً مِنْ رَبٍّ رَح۪يمٍ', 'Selamun kavlen min rabbin rahim.', 'Rahmeti kesintisiz Rabb\'den söz selamdır.[1]', 'سلم قولا من رب رحيم'),
(3764, 36, 59, 'وَامْتَازُوا الْيَوْمَ اَيُّهَا الْمُجْرِمُونَ', 'Vemtazul yevme eyyuhel mucrimun.', 'Ey mücrimler![1] Bugün ayrılın!', 'وامتزوا اليوم ايها المجرمون'),
(3765, 36, 60, 'اَلَمْ اَعْهَدْ اِلَيْكُمْ يَا بَن۪ٓي اٰدَمَ اَنْ لَا تَعْبُدُوا الشَّيْطَانَۚ اِنَّهُ لَكُمْ عَدُوٌّ مُب۪ينٌۙ', 'E lem a\'had ileykum ya beni ademe en la ta\'buduş şeytan, innehu lekum aduvvun mubin.', 'Ey ademoğulları! Ben,  size \"Şeytana kulluk etmeyin,  o sizin için apaçık düşmandır,  diye uyarıda bulunmadım mı?\"', 'الم اعهد اليكم يبني ادم ان لا تعبدوا الشيطن انه لكم عدو مبين'),
(3766, 36, 61, 'وَاَنِ اعْبُدُون۪يۜ هٰذَا صِرَاطٌ مُسْتَق۪يمٌ', 'Ve eni\'buduni, haza sıratun mustekim.', 'Bana kulluk[1] edin. Dosdoğru yol budur.', 'وان اعبدوني هذا صرط مستقيم'),
(3767, 36, 62, 'وَلَقَدْ اَضَلَّ مِنْكُمْ جِبِلاًّ كَث۪يراًۜ اَفَلَمْ تَكُونُوا تَعْقِلُونَ', 'Ve lekad edalle minkum cibillen kesira, e fe lem tekunu ta\'kılun.', 'Ant olsun ki sizden birçoklarını saptırdı. Sizde bunu anlayacak akıl yok muydu?', 'ولقد اضل منكم جبلا كثيرا افلم تكونوا تعقلون'),
(3768, 36, 63, 'هٰذِه۪ جَهَنَّمُ الَّت۪ي كُنْتُمْ تُوعَدُونَ', 'Hazihi cehennemulleti kuntum tuadun.', 'İşte,  uyarılmış olduğunuz Cehennem budur.', 'هذه جهنم التي كنتم توعدون'),
(3769, 36, 64, 'اِصْلَوْهَا الْيَوْمَ بِمَا كُنْتُمْ تَكْفُرُونَ', 'Islevhel yevme bima kuntum tekfurun.', 'Kafir olduğunuz için bugün oraya girin!', 'اصلوها اليوم بما كنتم تكفرون'),
(3770, 36, 65, 'اَلْيَوْمَ نَخْتِمُ عَلٰٓى اَفْوَاهِهِمْ وَتُكَلِّمُنَٓا اَيْد۪يهِمْ وَتَشْهَدُ اَرْجُلُهُمْ بِمَا كَانُوا يَكْسِبُونَ', 'El yevme nahtimu ala efvahihim ve tukellimuna eydihim ve teşhedu erculuhum bima kanu yeksibun.', 'Bugün onların ağızlarını kapatırız. Bize elleri konuşur,  ayakları da kazandıkları şeylere tanıklık eder.', 'اليوم نختم علي افوههم وتكلمنا ايديهم وتشهد ارجلهم بما كانوا يكسبون'),
(3771, 36, 66, 'وَلَوْ نَشَٓاءُ لَطَمَسْنَا عَلٰٓى اَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَاَنّٰى يُبْصِرُونَ', 'Ve lev neşau le tamesna ala a\'yunihim festebekus sırata fe enna yubsırun.', 'Eğer dileseydik,  elbette gözlerini kör ederdik de yol bulmak için koşuşturup dururlardı. Yollarını nasıl bulacaklardı ki?', 'ولو نشا لطمسنا علي اعينهم فاستبقوا الصرط فاني يبصرون'),
(3772, 36, 67, 'وَلَوْ نَشَٓاءُ لَمَسَخْنَاهُمْ عَلٰى مَكَانَتِهِمْ فَمَا اسْتَطَاعُوا مُضِياًّ وَلَا يَرْجِعُونَ۟', 'Ve lev neşau le mesahnahum ala mekanetihim fe mastetau mudiyyen ve la yerciun.', 'Eğer dileseydik,  oldukları yerde sabit bir şekle dönüştürürdük, [1] ileri gitmeye de geri dönmeye de güç yetiremezlerdi.', 'ولو نشا لمسخنهم علي مكانتهم فما استطعوا مضيا ولا يرجعون'),
(3773, 36, 68, 'وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِۜ اَفَلَا يَعْقِلُونَ', 'Ve men nuammirhu nunekkishu fil halk, e fe la ya\'kılun.', 'Kimin ömrünü uzatırsak,  zamanla yaratılış olarak onu tersine çeviririz.[1] Buna rağmen hala akıllarını kullanmayacaklar mı?', 'ومن نعمره ننكسه في الخلق افلا يعقلون'),
(3774, 36, 69, 'وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغ۪ي لَهُۜ اِنْ هُوَ اِلَّا ذِكْرٌ وَقُرْاٰنٌ مُب۪ينٌۙ', 'Ve ma allemnahuş şi\'re ve ma yenbagi leh, in huve illa zikrun ve kur\'anun mubin.', 'Biz ona şiir öğretmedik. Ve bu,  ona yakışmaz da. O,  yalnızca bir Öğüt ve apaçık Kur\'an\'dır.', 'وما علمنه الشعر وما ينبغي له ان هو الا ذكر وقران مبين'),
(3775, 36, 70, 'لِيُنْذِرَ مَنْ كَانَ حَياًّ وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِر۪ينَ', 'Li yunzire men kane hayyen ve yehıkkal kavlu alel kafirin.', 'O,  diri olanları uyarmak[1] ve Kafirlerin[2] üzerine Söz\'ün[3] hak olması içindir.', 'لينذر من كان حيا ويحق القول علي الكفرين'),
(3776, 36, 71, 'اَوَلَمْ يَرَوْا اَنَّا خَلَقْنَا لَهُمْ مِمَّا عَمِلَتْ اَيْد۪ينَٓا اَنْعَاماً فَهُمْ لَهَا مَالِكُونَ', 'E ve lem yerev enna halakna lehum mimma amilet eydina en\'amen fe hum leha malikun.', 'Ellerimizin[1] yaptıklarından,  onlara sahip oldukları hayvanlar yarattığımızı görmüyorlar mı?', 'اولم يروا انا خلقنا لهم مما عملت ايدينا انعما فهم لها ملكون'),
(3777, 36, 72, 'وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', 'Ve zellelnaha lehum fe minha rakubuhum ve minha ye\'kulun.', 'Bu hayvanları yararlanmalarına sunduk. Kimine biniyor,  kimini de yiyorlar.', 'وذللنها لهم فمنها ركوبهم ومنها ياكلون'),
(3778, 36, 73, 'وَلَهُمْ ف۪يهَا مَنَافِـعُ وَمَشَارِبُۜ اَفَلَا يَشْكُرُونَ', 'Ve lehum fiha menafiu ve meşarib, e fe la yeşkurun.', 'Bu hayvanlarda onlar için yararlar[1] ve içecek[1] şeyler vardır. Hala şükretmeyecekler mi?', 'ولهم فيها منفع ومشارب افلا يشكرون'),
(3779, 36, 74, 'وَاتَّخَذُوا مِنْ دُونِ اللّٰهِ اٰلِهَةً لَعَلَّهُمْ يُنْصَرُونَۜ', 'Vettehazu min dunillahi aliheten leallehum yunsarun.', 'Onlar,  Allah\'ın yanı sıra,  kendilerinden yardım umdukları ilahlar edindiler.[1]', 'واتخذوا من دون الله الهة لعلهم ينصرون'),
(3780, 36, 75, 'لَا يَسْتَط۪يعُونَ نَصْرَهُمْۙ وَهُمْ لَهُمْ جُنْدٌ مُحْضَرُونَ', 'La yestetiune nasrahum ve hum lehum cundun muhdarun.', 'Oysa bu ilahlar onlara yardım etmeye güç yetiremezler. Ne var ki kendileri[1] onlar için[2] hazır askerlerdir.', 'لا يستطيعون نصرهم وهم لهم جند محضرون'),
(3781, 36, 76, 'فَلَا يَحْزُنْكَ قَوْلُهُمْۢ اِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'Fe la yahzunke kavluhum, inna na\'lemu ma yusirrune ve ma yu\'linun.', 'Artık onların[1] sözleri seni üzmesin. Biz,  onların gizlediklerini de açığa vurduklarını da biliyoruz.', 'فلا يحزنك قولهم انا نعلم ما يسرون وما يعلنون'),
(3782, 36, 77, 'اَوَلَمْ يَرَ الْاِنْسَانُ اَنَّا خَلَقْنَاهُ مِنْ نُطْفَةٍ فَاِذَا هُوَ خَص۪يمٌ مُب۪ينٌ', 'E ve lem yerel insanu enna halaknahu min nutfetin fe iza huve hasimun mubin.', 'İnsan,  onu bir nutfeden[1] yarattığımızı düşünmüyor mu? Şimdi de Bize apaçık düşman oldu.', 'اولم ير الانسن انا خلقنه من نطفة فاذا هو خصيم مبين'),
(3783, 36, 78, 'وَضَرَبَ لَنَا مَثَلاً وَنَسِيَ خَلْقَهُۜ قَالَ مَنْ يُحْـيِ الْعِظَامَ وَهِيَ رَم۪يمٌ', 'Ve darebe lena meselen ve nesiye halkah, kale men yuhyil izame ve hiye remim.', 'Nasıl yaratıldığını dikkate almayarak,  bir de Bize örnek veriyor: \"Kemiklerimiz çürüyüp gitmişken,  kim onlara can verecek?\" diyor.', 'وضرب لنا مثلا ونسي خلقه قال من يحي العظم وهي رميم'),
(3784, 36, 79, 'قُلْ يُحْي۪يهَا الَّـذ۪ٓي اَنْشَاَهَٓا اَوَّلَ مَرَّةٍۜ وَهُوَ بِكُلِّ خَلْقٍ عَل۪يمٌۙ', 'Kul yuhyihellezi enşeeha evvele merreh, ve huve bi kulli halkın alim.', 'De ki: \"Onu ilk defa inşa[1] eden,  ona hayat verecek. Ve O,  yaratmayı çok iyi bilendir.\"', 'قل يحييها الذي انشاها اول مرة وهو بكل خلق عليم'),
(3785, 36, 80, 'اَلَّذ۪ي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الْاَخْضَرِ نَاراً فَاِذَٓا اَنْتُمْ مِنْهُ تُوقِدُونَ', 'Ellezi ceale lekum mineş şeceril ahdarinaren fe iza entum minhu tukıdun.', 'Size yemyeşil ağaçtan ateş çıkaran O\'dur. Siz,  ondan yakıp duruyorsunuz.', 'الذي جعل لكم من الشجر الاخضر نارا فاذا انتم منه توقدون'),
(3786, 36, 81, 'اَوَلَيْسَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِقَادِرٍ عَلٰٓى اَنْ يَخْلُقَ مِثْلَهُمْۜ بَلٰى وَهُوَ الْخَلَّاقُ الْعَل۪يمُ', 'E ve leysellezi halakas semavati vel arda bi kadirin ala en yahluka mislehum, bela ve huvel hallakul alim.', 'Gökleri ve yeri yaratanın,  onların benzerlerini de yaratmaya gücü yetmez mi? Evet O,  Yegane Yaratıcı\'dır,  Her Şeyi Bilen\'dir.', 'اوليس الذي خلق السموت والارض بقدر علي ان يخلق مثلهم بلي وهو الخلق العليم'),
(3787, 36, 82, 'اِنَّـمَٓا اَمْرُهُٓ اِذَٓا اَرَادَ شَيْـٔاً اَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ', 'İnnema emruhu iza erade şey\'en en yekule lehu kun fe yekun.', 'O,  bir şey yaratmak istediğinde,  ona: \"Ol.\" der. O da hemen oluverir.', 'انما امره اذا اراد شيا ان يقول له كن فيكون'),
(3788, 36, 83, 'فَسُبْحَانَ الَّذ۪ي بِيَدِه۪ مَلَكُوتُ كُلِّ شَيْءٍ وَاِلَيْهِ تُرْجَعُونَ', 'Fe subhanellezi bi yedihi melekutu kulli şey\'in ve ileyhi turceun.', 'O,  çok yüce ve çok üstündür. Her şeyin mülkü ve egemenliği O\'nun elindedir. Ve O\'na döndürüleceksiniz.', 'فسبحن الذي بيده ملكوت كل شي واليه ترجعون'),
(3789, 37, 1, 'وَالصَّٓافَّاتِ صَفاًّۙ', 'Ves saffati saffa.', 'Saf bağlayarak,  saflar halinde dizilenlere ant olsun.', 'والصفت صفا'),
(3790, 37, 2, 'فَالزَّاجِرَاتِ زَجْراًۙ', 'Fez zacirati zecra.', 'Haykırıp sürenlere,', 'فالزجرت زجرا'),
(3791, 37, 3, 'فَالتَّالِيَاتِ ذِكْراًۙ', 'Fet taliyati zikra.', 'Öğüt okuyanlara,', 'فالتليت ذكرا'),
(3792, 37, 4, 'اِنَّ اِلٰهَكُمْ لَوَاحِدٌۜ', 'İnne ilahekum le vahıd.', 'Kuşkusuz ilahınız elbette Bir Tek\'tir.', 'ان الهكم لوحد'),
(3793, 37, 5, 'رَبُّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ الْمَشَارِقِۜ', 'Rabbus semavati vel ardı ve ma beynehuma ve rabbul meşarık.', 'Göklerin,  yerin ve ikisinin arasında olanların Rabb\'idir. Ve doğuların[1] Rabb\'idir.', 'رب السموت والارض وما بينهما ورب المشرق'),
(3794, 37, 6, 'اِنَّا زَيَّنَّا السَّمَٓاءَ الدُّنْيَا بِز۪ينَةٍۨ الْـكَوَاكِبِۙ', 'İnna zeyyennes semaed dunya bi ziynetinil kevakib.', 'Biz,  dünya semasını bir ziynetle,  yıldızlarla bezedik.', 'انا زينا السما الدنيا بزينة الكواكب'),
(3795, 37, 7, 'وَحِفْظاً مِنْ كُلِّ شَيْطَانٍ مَارِدٍۚ', 'Ve hıfzan min kulli şeytanin marid.', 'Bütün Marid[1] şeytanlardan koruduk.', 'وحفظا من كل شيطن مارد'),
(3796, 37, 8, 'لَا يَسَّمَّعُونَ اِلَى الْمَلَأِ الْاَعْلٰى وَيُقْذَفُونَ مِنْ كُلِّ جَانِبٍۗ', 'La yessemmeune ilel meleil a\'la ve yukzefune minkulli canib.', 'Mele-i A\'la\'ya[1] kulak verip dinleyemezler; her taraftan kovulurlar.', 'لا يسمعون الي الملا الاعلي ويقذفون من كل جانب'),
(3797, 37, 9, 'دُحُوراً وَلَهُمْ عَذَابٌ وَاصِبٌۙ', 'Duhuran ve lehum azabun vasib.', 'Kovulmuş olarak,  onlar için kesintisiz azap vardır.', 'دحورا ولهم عذاب واصب'),
(3798, 37, 10, 'اِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَاَتْبَعَهُ شِهَابٌ ثَاقِبٌ', 'İlla men hatıfel hatfete fe etbeahu şihabun sakib.', 'Ancak oradan bir söz kapan olursa,  kayıp giden parlak bir alev ona yetişir ve onu yakar.', 'الا من خطف الخطفة فاتبعه شهاب ثاقب'),
(3799, 37, 11, 'فَاسْتَفْتِهِمْ اَهُمْ اَشَدُّ خَلْقاً اَمْ مَنْ خَلَقْنَاۜ اِنَّا خَلَقْنَاهُمْ مِنْ ط۪ينٍ لَازِبٍ', 'Festeftihim e hum eşeddu halkan em men halakna, inna halaknahum min tinin lazib.', 'Şimdi onlara sor: \"Onları yaratmak mı daha zor,  yoksa diğer yarattıklarımızı mı?[1]\" Oysa kendilerini yapışkan bir çamurdan yarattık.', 'فاستفتهم اهم اشد خلقا ام من خلقنا انا خلقنهم من طين لازب'),
(3800, 37, 12, 'بَلْ عَجِبْتَ وَيَسْخَرُونَۖ', 'Bel acibte ve yesharun.', 'Evet,  sen hayran kaldın,  onlar ise alay ediyorlar.', 'بل عجبت ويسخرون'),
(3801, 37, 13, 'وَاِذَا ذُكِّرُوا لَا يَذْكُرُونَۖ', 'Ve iza zukkiru la yezkurun.', 'Kendilerine öğüt verildiği zaman,  öğüdü dikkate almıyorlar.', 'واذا ذكروا لا يذكرون'),
(3802, 37, 14, 'وَاِذَا رَاَوْا اٰيَةً يَسْتَسْخِرُونَۖ', 'Ve iza raev ayeten yesteshırun.', 'Ve bir ayet[1] gördükleri zaman eğlenceye alıyorlar.', 'واذا راوا اية يستسخرون'),
(3803, 37, 15, 'وَقَالُٓوا اِنْ هٰذَٓا اِلَّا سِحْرٌ مُب۪ينٌۚ', 'Ve kalu in haza illa sihrun mubin.', '\"Bu apaçık bir büyüden başka bir şey değildir.\" diyorlar.', 'وقالوا ان هذا الا سحر مبين'),
(3804, 37, 16, 'ءَاِذَا مِتْنَا وَكُنَّا تُرَاباً وَعِظَاماً ءَاِنَّا لَمَبْعُوثُونَۙ', 'E iza mitna ve kunna turaben ve izamen e inna le meb\'usun.', '\"Öldüğümüz; toprak ve kemik olduğumuz zaman,  yeniden diriltileceğiz öyle mi?\"', 'اذا متنا وكنا ترابا وعظما انا لمبعوثون'),
(3805, 37, 17, 'اَوَاٰبَٓاؤُ۬نَا الْاَوَّلُونَۜ', 'E ve abaunel evvelun.', '\"Yok olup gitmiş atalarımız da mı?\"', 'اواباونا الاولون'),
(3806, 37, 18, 'قُلْ نَعَمْ وَاَنْتُمْ دَاخِرُونَۚ', 'Kul neam ve entum dahırun.', 'De ki: \"Evet,  aşağılanmış olarak.\"', 'قل نعم وانتم دخرون'),
(3807, 37, 19, 'فَاِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ فَاِذَا هُمْ يَنْظُرُونَ', 'Fe innema hiye zecretun vahıdetun fe iza hum yenzurun.', 'Artık o tek bir haykırıştır.[1] O zaman neyin ne olduğunu görecekler.', 'فانما هي زجرة وحدة فاذا هم ينظرون'),
(3808, 37, 20, 'وَقَالُوا يَا وَيْلَنَا هٰذَا يَوْمُ الدّ۪ينِ', 'Ve kalu ya veylena haza yevmud din.', '\"Eyvah bizlere! İşte bu Din Günü\'dür\"[1] derler.', 'وقالوا يويلنا هذا يوم الدين'),
(3809, 37, 21, 'هٰذَا يَوْمُ الْفَصْلِ الَّذ۪ي كُنْتُمْ بِه۪ تُكَذِّبُونَ۟', 'Haza yevmul faslillezi kuntum bihi tukezzibun.', 'Bu,  yalanladığınız Fasıl Günü\'dür.[1]', 'هذا يوم الفصل الذي كنتم به تكذبون'),
(3810, 37, 22, 'اُحْشُرُوا الَّذ۪ينَ ظَلَمُوا وَاَزْوَاجَهُمْ وَمَا كَانُوا يَعْبُدُونَۙ', 'Uhşurullezine zalemu ve ezvacehum ve ma kanu ya\'budun.', 'Toplayın o zulmedenleri,  eşlerini[1] ve onların kulluk ettikleri şeyleri;', 'احشروا الذين ظلموا وازوجهم وما كانوا يعبدون'),
(3811, 37, 23, 'مِنْ دُونِ اللّٰهِ فَاهْدُوهُمْ اِلٰى صِرَاطِ الْجَح۪يمِۙ', 'Min dunillahi fehduhum ila sıratıl cahim.', 'Allah\'ın yanı sıra. Artık onlara Cehennem yolunu gösterin.', 'من دون الله فاهدوهم الي صرط الجحيم'),
(3812, 37, 24, 'وَقِفُوهُمْ اِنَّهُمْ مَسْؤُ۫لُونَۙ', 'Vakıfuhum innehum mes\'ulun.', 'Onları durdurun! Kuşkusuz onlar sorumludurlar.', 'وقفوهم انهم مسولون'),
(3813, 37, 25, 'مَا لَـكُمْ لَا تَنَاصَرُونَ', 'Ma lekum la tenasarun.', 'Size ne oldu da dünyadaki gibi yardımlaşmıyorsunuz?', 'ما لكم لا تناصرون'),
(3814, 37, 26, 'بَلْ هُمُ الْيَوْمَ مُسْتَسْلِمُونَ', 'Bel humul yevme musteslimun.', 'Hayır! Onlar o gün teslim olmuşlardır.[1]', 'بل هم اليوم مستسلمون'),
(3815, 37, 27, 'وَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَتَسَٓاءَلُونَ', 'Ve akbele ba\'duhum ala ba\'dın yetesaelun.', 'Karşılıklı olarak birbirlerini suçluyorlar.', 'واقبل بعضهم علي بعض يتسالون'),
(3816, 37, 28, 'قَالُٓوا اِنَّكُمْ كُنْتُمْ تَأْتُونَنَا عَنِ الْيَم۪ينِ', 'Kalu innekum kuntum te\'tunena anil yemin.', '\"Gerçek şu ki siz bize,  hep sağ taraftan[1] geliyordunuz.\" derler.', 'قالوا انكم كنتم تاتوننا عن اليمين'),
(3817, 37, 29, 'قَالُوا بَلْ لَمْ تَكُونُوا مُؤْمِن۪ينَۚ', 'Kalu bel lem tekunu mu\'minin.', '\"Hayır,  siz zaten inanan kimseler değildiniz.\" derler.', 'قالوا بل لم تكونوا مومنين'),
(3818, 37, 30, 'وَمَا كَانَ لَنَا عَلَيْكُمْ مِنْ سُلْطَانٍۚ بَلْ كُنْتُمْ قَوْماً طَاغ۪ينَ', 'Ve ma kane lena aleykum min sultan, bel kuntum kavmen tagin.', '\"Bizim sizin üzerinizde yetkimiz yoktu. Bilakis,  siz azmış bir halktınız.\"', 'وما كان لنا عليكم من سلطن بل كنتم قوما طغين'),
(3819, 37, 31, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَاۗ اِنَّا لَذَٓائِقُونَ', 'Fe hakka aleyna kavlu rabbina inna le zaıkun.', '\"Artık Rabb\'imizin Söz\'ü[1] üzerimize hak oldu. Kuşkusuz biz,  azabı tadacak olanlarız.\"', 'فحق علينا قول ربنا انا لذايقون'),
(3820, 37, 32, 'فَاَغْوَيْنَا‌كُمْ اِنَّا كُنَّا غَاو۪ينَ', 'Fe agveynakum inna kunna gavin.', '\"Biz,  sizi azdırdık,  çünkü biz azgındık.\"', 'فاغوينكم انا كنا غوين'),
(3821, 37, 33, 'فَاِنَّهُمْ يَوْمَئِذٍ فِي الْعَذَابِ مُشْتَرِكُونَ', 'Fe innehum yevme izin fil azabi muşterikun.', 'Onlar,  izin günü[1] azapta ortaktırlar.', 'فانهم يوميذ في العذاب مشتركون'),
(3822, 37, 34, 'اِنَّا كَذٰلِكَ نَفْعَلُ بِالْمُجْرِم۪ينَ', 'İnna kezalike nef\'alu bil mucrimin.', 'Mücrimleri[1] böyle cezalandırırız.', 'انا كذلك نفعل بالمجرمين'),
(3823, 37, 35, 'اِنَّهُمْ كَانُٓوا اِذَا ق۪يلَ لَهُمْ لَٓا اِلٰهَ اِلَّا اللّٰهُ يَسْتَكْبِرُونَۙ', 'İnnehum kanu iza kile lehum la ilahe illallahu yestekbirun.', 'Onlar,  kendilerine: \"Allah\'tan başka ilah yoktur.\" denildiği zaman büyüklük taslayanlardı.', 'انهم كانوا اذا قيل لهم لا اله الا الله يستكبرون'),
(3824, 37, 36, 'وَيَقُولُونَ اَئِنَّا لَتَارِكُٓوا اٰلِهَتِنَا لِشَاعِرٍ مَجْنُونٍۜ', 'Ve yekulune e inna le tariku alihetina li şairin mecnun.', '\"Mecnun[1] bir şair için ilahlarımızı terk edenler mi olacağız?\" derlerdi.', 'ويقولون اينا لتاركوا الهتنا لشاعر مجنون'),
(3825, 37, 37, 'بَلْ جَٓاءَ بِالْحَقِّ وَصَدَّقَ الْمُرْسَل۪ينَ', 'Bel cae bil hakkı ve saddakal murselin.', 'Bilakis,  o,  Hakkı getirdi ve gönderilmiş resulleri doğruladı.', 'بل جا بالحق وصدق المرسلين'),
(3826, 37, 38, 'اِنَّكُمْ لَذَٓائِقُوا الْعَذَابِ الْاَل۪يمِۚ', 'İnnekum le zaikul azabil elim.', 'Siz,  kesinlikle elim azabı tadacak olanlarsınız.', 'انكم لذايقوا العذاب الاليم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(3827, 37, 39, 'وَمَا تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُونَۙ', 'Ve ma tuczevne illa ma kuntum ta\'melun.', 'Sadece yapmış olduğunuz şeyin karşılığını alacaksınız.', 'وما تجزون الا ما كنتم تعملون'),
(3828, 37, 40, 'اِلَّا عِبَادَ اللّٰهِ الْمُخْلَص۪ينَ', 'İlla ibadallahil muhlesin.', 'Allah\'ın muhles[1] kulları hariç.', 'الا عباد الله المخلصين'),
(3829, 37, 41, 'اُو۬لٰٓئِكَ لَهُمْ رِزْقٌ مَعْلُومٌۙ', 'Ulaike lehum rizkun ma\'lum.', 'Onlar için bilinen bir rızık vardır.', 'اوليك لهم رزق معلوم'),
(3830, 37, 42, 'فَوَا‌كِهُۚ وَهُمْ مُكْرَمُونَۙ', 'Fevakih, ve hum mukremun.', 'Onlara meyveler ikram edilecek.', 'فوكه وهم مكرمون'),
(3831, 37, 43, 'ف۪ي جَنَّاتِ النَّع۪يمِۙ', 'Fi cennatin naim.', 'Naim cennetlerinde.', 'في جنت النعيم'),
(3832, 37, 44, 'عَلٰى سُرُرٍ مُتَقَابِل۪ينَ', 'Ala sururin mutekabilin.', 'Karşılıklı tahtlar üzerinde.', 'علي سرر متقبلين'),
(3833, 37, 45, 'يُطَافُ عَلَيْهِمْ بِكَأْسٍ مِنْ مَع۪ينٍۙ', 'Yutafu aleyhim bi ke\'sin min main.', 'Etraflarında kaynaklardan doldurulmuş kaseler dolaştırılır.', 'يطاف عليهم بكاس من معين'),
(3834, 37, 46, 'بَيْضَٓاءَ لَذَّةٍ لِلشَّارِب۪ينَۚ', 'Beydae lezzetin liş şaribin.', 'Berrak,  içenlere lezzet veren.', 'بيضا لذة للشربين'),
(3835, 37, 47, 'لَا ف۪يهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنْزَفُونَ', 'La fiha gavlun ve la hum anha yunzefun.', 'İçinde kötü etkisi olan bir şey yoktur. Ve ondan onların akılları karışmaz.', 'لا فيها غول ولا هم عنها ينزفون'),
(3836, 37, 48, 'وَعِنْدَهُمْ قَاصِرَاتُ الطَّرْفِ ع۪ينٌۙ', 'Ve indehum kasıratut tarfı in.', 'Yanlarında bakışlarını koruyanlar[1] vardır.', 'وعندهم قصرت الطرف عين'),
(3837, 37, 49, 'كَاَنَّهُنَّ بَيْضٌ مَكْنُونٌ', 'Ke enne hunne beydun meknun.', 'Onlar,  iyi korunmuş yumurta[1] gibidir.', 'كانهن بيض مكنون'),
(3838, 37, 50, 'فَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَتَسَٓاءَلُونَ', 'Fe akbele ba\'duhum ala ba\'dın yetesaelun.', 'Birbirleriyle karşılıklı sohbet ediyorlar.', 'فاقبل بعضهم علي بعض يتسالون'),
(3839, 37, 51, 'قَالَ قَٓائِلٌ مِنْهُمْ اِنّ۪ي كَانَ ل۪ي قَر۪ينٌۙ', 'Kale kailun minhum inni kane li karin.', 'İçlerinden biri dedi ki: \"Benim yakın bir arkadaşım vardı.\"', 'قال قايل منهم اني كان لي قرين'),
(3840, 37, 52, 'يَقُولُ اَئِنَّكَ لَمِنَ الْمُصَدِّق۪ينَ', 'Yekulu e inneke le minel musaddikin.', 'Diyordu ki: \"Sen gerçekten ahireti doğrulayanlardan mısın?\"', 'يقول انك لمن المصدقين'),
(3841, 37, 53, 'ءَاِذَا مِتْنَا وَكُنَّا تُرَاباً وَعِظَاماً ءَاِنَّا لَمَد۪ينُونَ', 'E iza mitna ve kunna turaben ve izamen e inna le medinun.', '\"Öldüğümüz,  toprak ve kemik olduğumuz zaman,  gerçekten cezalandırılacak mıyız?\"', 'اذا متنا وكنا ترابا وعظما انا لمدينون'),
(3842, 37, 54, 'قَالَ هَلْ اَنْتُمْ مُطَّلِعُونَ', 'Kale hel entum muttaliun.', '\"Siz yakından bilenler misiniz?\" derdi.', 'قال هل انتم مطلعون'),
(3843, 37, 55, 'فَاطَّـلَعَ فَرَاٰهُ ف۪ي سَوَٓاءِ الْجَح۪يمِ', 'Fettalea fe reahu fi sevail cahim.', 'Derken yakından tanık oldu. Onu Cehennem\'in ortasında gördü.', 'فاطلع فراه في سوا الجحيم'),
(3844, 37, 56, 'قَالَ تَاللّٰهِ اِنْ كِدْتَ لَتُرْد۪ينِۙ', 'Kale tallahi in kidte le turdin.', '\"Vallahi az kalsın beni de mahvedecektin.\" dedi.', 'قال تالله ان كدت لتردين'),
(3845, 37, 57, 'وَلَوْلَا نِعْمَةُ رَبّ۪ي لَكُنْتُ مِنَ الْمُحْضَر۪ينَ', 'Ve lev la ni\'metu rabbi le kuntu minel muhdarin.', '\"Eğer Rabb\'imin nimeti[1] olmasaydı,  ben de Cehenneme atılanlardan olurdum.\"', 'ولولا نعمة ربي لكنت من المحضرين'),
(3846, 37, 58, 'اَفَمَا نَحْنُ بِمَيِّت۪ينَۙ', 'E fe ma nahnu bi meyyitin.', '\"Biz artık bir daha ölmeyeceğiz,  öyle değil mi?\"', 'افما نحن بميتين'),
(3847, 37, 59, 'اِلَّا مَوْتَتَنَا الْاُو۫لٰى وَمَا نَحْنُ بِمُعَذَّب۪ينَ', 'İlla mevtetenel ula ve ma nahnu bi muazzebin.', '\"İlk ölümümüzden başka ölüm görmeyecek,  azaba uğratılacaklar da olmayacağız.\"', 'الا موتتنا الاولي وما نحن بمعذبين'),
(3848, 37, 60, 'اِنَّ هٰذَا لَهُوَ الْفَوْزُ الْعَظ۪يمُ', 'İnne haza le huvel fevzul azim.', 'Bu gerçekten en büyük başarıdır.', 'ان هذا لهو الفوز العظيم'),
(3849, 37, 61, 'لِمِثْلِ هٰذَا فَلْيَعْمَلِ الْعَامِلُونَ', 'Li misli haza fel ya\'melil amilun.', 'Çalışanlar,  bunun gibi şeyler için çalışsın.', 'لمثل هذا فليعمل العملون'),
(3850, 37, 62, 'اَذٰلِكَ خَيْرٌ نُزُلاً اَمْ شَجَرَةُ الزَّقُّومِ', 'E zalike hayrun nuzulen em şeceretuz zakkum.', 'İkram olarak bu mu daha iyi,  yoksa zakkum ağacı mı?', 'اذلك خير نزلا ام شجرة الزقوم'),
(3851, 37, 63, 'اِنَّا جَعَلْنَاهَا فِتْنَةً لِلظَّالِم۪ينَ', 'İnna cealnaha fitneten liz zalimin.', 'Biz,  onu zalimler için bir fitne yaptık.', 'انا جعلنها فتنة للظلمين'),
(3852, 37, 64, 'اِنَّهَا شَجَرَةٌ تَخْرُجُ ف۪ٓي اَصْلِ الْجَح۪يمِۙ', 'İnneha şeceretun tahrucu fi aslil cahim.', 'O,  Cehennem\'in dibinde çıkan bir ağaçtır.', 'انها شجرة تخرج في اصل الجحيم'),
(3853, 37, 65, 'طَلْعُهَا كَاَنَّهُ رُؤُ۫سُ الشَّيَاط۪ينِ', 'Tal\'uha ke ennehu ruusuş şeyatin.', 'Tomurcukları şeytanların başları[1] gibidir.', 'طلعها كانه روس الشيطين'),
(3854, 37, 66, 'فَاِنَّهُمْ لَاٰكِلُونَ مِنْهَا فَمَالِؤُ۫نَ مِنْهَا الْبُطُونَۜ', 'Fe innehum le akilune minha fe maliune min hel butun.', 'Onlar,  ondan yiyecekler ve karınlarını onunla dolduracaklardır.', 'فانهم لاكلون منها فمالون منها البطون'),
(3855, 37, 67, 'ثُمَّ اِنَّ لَهُمْ عَلَيْهَا لَشَوْباً مِنْ حَم۪يمٍۚ', 'Summe inne lehum aleyha le şevben min hamim.', 'Sonra da onun üstüne kaynar su karıştırılmış bir içecek vardır.', 'ثم ان لهم عليها لشوبا من حميم'),
(3856, 37, 68, 'ثُمَّ اِنَّ مَرْجِعَهُمْ لَاِلَى الْجَح۪يمِ', 'Summe inne merciahum le ilel cahim.', 'Sonra dönecekleri yer,  kesinlikle Cehennem\'dir.', 'ثم ان مرجعهم لالي الجحيم'),
(3857, 37, 69, 'اِنَّهُمْ اَلْفَوْا اٰبَٓاءَهُمْ ضَٓالّ۪ينَۙ', 'İnnehum elfev abaehum dalline.', 'Onlar,  atalarını sapkın bir halde buldular.', 'انهم الفوا اباهم ضالين'),
(3858, 37, 70, 'فَهُمْ عَلٰٓى اٰثَارِهِمْ يُهْرَعُونَ', 'Fe hum ala asarihim yuhreun.', 'Kendileri de onların izleri üzerinde koşturdular.', 'فهم علي اثرهم يهرعون'),
(3859, 37, 71, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ اَكْثَرُ الْاَوَّل۪ينَۙ', 'Ve lekad dalle kablehum ekserul evvelin.', 'Ant olsun ki onlardan öncekilerin çoğu sapkındı.', 'ولقد ضل قبلهم اكثر الاولين'),
(3860, 37, 72, 'وَلَقَدْ اَرْسَلْنَا ف۪يهِمْ مُنْذِر۪ينَ', 'Ve lekad erselna fi him munzirin.', 'Ant olsun ki onlara içlerinden uyarıcılar gönderdik.', 'ولقد ارسلنا فيهم منذرين'),
(3861, 37, 73, 'فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنْذَر۪ينَۙ', 'Fanzur keyfe kane akibetul munzerin.', 'Uyarılanların sonlarının nasıl olduğuna bir bak!', 'فانظر كيف كان عقبة المنذرين'),
(3862, 37, 74, 'اِلَّا عِبَادَ اللّٰهِ الْمُخْلَص۪ينَ۟', 'İlla ibadallahil muhlasin.', 'Ancak Allah\'ın muhles[1] kulları hariç.', 'الا عباد الله المخلصين'),
(3863, 37, 75, 'وَلَقَدْ نَادٰينَا نُوحٌ فَلَنِعْمَ الْمُج۪يبُونَۚ', 'Ve lekad nadana nuhun fe le ni\'mel mucibun.', 'Ant olsun ki Nuh,  Bize dua etmişti. Biz,  ne güzel karşılık vermiştik!', 'ولقد نادينا نوح فلنعم المجيبون'),
(3864, 37, 76, 'وَنَجَّيْنَاهُ وَاَهْلَهُ مِنَ الْكَرْبِ الْعَظ۪يمِۘ', 'Ve necceynahu ve ehlehu minel kerbil azim.', 'Onu ve ehlini[1] büyük sıkıntıdan kurtardık.', 'ونجينه واهله من الكرب العظيم'),
(3865, 37, 77, 'وَجَعَلْنَا ذُرِّيَّتَهُ هُمُ الْبَاق۪ينَۘ', 'Ve cealna zurriyyetehu humul bakin.', 'Onun soyunu kalıcı kıldık.', 'وجعلنا ذريته هم الباقين'),
(3866, 37, 78, 'وَتَرَكْنَا عَلَيْهِ فِي الْاٰخِر۪ينَۘ', 'Ve terekna aleyhi fil ahirin.', 'Sonradan gelenler içinde onu destekleyiciler bıraktık.', 'وتركنا عليه في الاخرين'),
(3867, 37, 79, 'سَلَامٌ عَلٰى نُوحٍ فِي الْعَالَم۪ينَ', 'Selamun ala nuhın fil alemin.', 'Âlemler içinde,  Nuh\'a selam olsun.', 'سلم علي نوح في العلمين'),
(3868, 37, 80, 'اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'İnna kezalike neczil muhsinin.', 'İyilere,  işte böyle karşılık veririz.', 'انا كذلك نجزي المحسنين'),
(3869, 37, 81, 'اِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِن۪ينَ', 'İnnehu min ibadinel mu\'minin.', 'O,  Bizim Mü\'min kullarımızdandı.', 'انه من عبادنا المومنين'),
(3870, 37, 82, 'ثُمَّ اَغْرَقْنَا الْاٰخَر۪ينَ', 'Summe agraknel aharin.', 'Sonra diğerlerini boğduk.', 'ثم اغرقنا الاخرين'),
(3871, 37, 83, 'وَاِنَّ مِنْ ش۪يعَتِه۪ لَاِبْرٰه۪يمَۢ', 'Ve inne min şiatihi le ibrahim.', 'İbrahim,  onun yolunu izleyenlerdendi.', 'وان من شيعته لابرهيم'),
(3872, 37, 84, 'اِذْ جَٓاءَ رَبَّهُ بِقَلْبٍ سَل۪يمٍ', 'İz cae rabbehu bi kalbin selim.', 'O,  Rabb\'ine selim[1] bir kalp[2] ile gelmişti.', 'اذ جا ربه بقلب سليم'),
(3873, 37, 85, 'اِذْ قَالَ لِاَب۪يهِ وَقَوْمِه۪ مَاذَا تَعْبُدُونَۚ', 'İz kale li ebihi ve kavmihi maza ta\'budun.', 'Babasına ve halka: \"Nelere kulluk ediyorsunuz?\" demişti.', 'اذ قال لابيه وقومه ماذا تعبدون'),
(3874, 37, 86, 'اَئِفْكاً اٰلِهَةً دُونَ اللّٰهِ تُر۪يدُونَۜ', 'E ifken aliheten dunallahi turidun.', '\"Allah\'ı bırakarak uydurma ilahlar mı istiyorsunuz?\"', 'ايفكا الهة دون الله تريدون'),
(3875, 37, 87, 'فَمَا ظَنُّكُمْ بِرَبِّ الْعَالَم۪ينَ', 'Fe ma zannukum bi rabbil alemin.', '\"Âlemlerin Rabb\'i hakkında nasıl bir anlayışa sahipsiniz?\"', 'فما ظنكم برب العلمين'),
(3876, 37, 88, 'فَنَظَرَ نَظْرَةً فِي النُّجُومِۙ', 'Fe nazara nazraten fin nucum.', 'Yıldızlara bir nazarla nazar etti.[1]', 'فنظر نظرة في النجوم'),
(3877, 37, 89, 'فَقَالَ اِنّ۪ي سَق۪يمٌ', 'Fe kale inni sakim.', '\"Ben gerçekten hastayım!\" dedi.', 'فقال اني سقيم'),
(3878, 37, 90, 'فَتَوَلَّوْا عَنْهُ مُدْبِر۪ينَ', 'Fe tevellev anhu mudbirin.', 'Bunun üzerine ondan yüz çevirerek,  arkalarını dönüp gittiler.', 'فتولوا عنه مدبرين'),
(3879, 37, 91, 'فَرَاغَ اِلٰٓى اٰلِهَتِهِمْ فَقَالَ اَلَا تَأْكُلُونَۚ', 'Feraga ila alihetihim fe kale e la te\'kulun.', 'Onların ilahlarına yanaşarak: \"Yemez misiniz?\" dedi.', 'فراغ الي الهتهم فقال الا تاكلون'),
(3880, 37, 92, 'مَا لَكُمْ لَا تَنْطِقُونَ', 'Ma lekum la tentıkun.', '\"Neyiniz var? Neden konuşmuyorsunuz?\"', 'ما لكم لا تنطقون'),
(3881, 37, 93, 'فَرَاغَ عَلَيْهِمْ ضَرْباً بِالْيَم۪ينِ', 'Feraga aleyhim darben bil yemin.', 'Üzerlerine yürüyüp sağıyla[1] vurdu.', 'فراغ عليهم ضربا باليمين'),
(3882, 37, 94, 'فَاَقْبَلُٓوا اِلَيْهِ يَزِفُّونَ', 'Fe akbelu ileyhi yeziffun.', 'Bunun üzerine koşuşturarak ona yöneldiler.', 'فاقبلوا اليه يزفون'),
(3883, 37, 95, 'قَالَ اَتَعْبُدُونَ مَا تَنْحِتُونَۙ', 'Kale e ta\'budune ma tenhıtun.', '\"Siz yonttuğunuz şeylere mi kulluk ediyorsunuz?\"', 'قال اتعبدون ما تنحتون'),
(3884, 37, 96, 'وَاللّٰهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', 'Vallahu halakakum ve ma ta\'melun.', '\"Sizi de yaptığınız şeyleri de Allah yarattı.\"', 'والله خلقكم وما تعملون'),
(3885, 37, 97, 'قَالُوا ابْنُوا لَهُ بُنْيَاناً فَاَلْقُوهُ فِي الْجَح۪يمِ', 'Kalubnu lehu bunyanen fe elkuhu fil cahim.', '\"Onun için bir yer hazırlayın,  sonra da onu cehenneme[1] atın.\" dediler.', 'قالوا ابنوا له بنينا فالقوه في الجحيم'),
(3886, 37, 98, 'فَاَرَادُوا بِه۪ كَيْداً فَجَعَلْنَاهُمُ الْاَسْفَل۪ينَ', 'Fe eradu bihi keyden fe cealna humul esfelin.', 'Ona tuzak kurmak istediler. Tuzaklarını boşa çıkarıp onları aşağılık bir duruma düşürdük.', 'فارادوا به كيدا فجعلنهم الاسفلين'),
(3887, 37, 99, 'وَقَالَ اِنّ۪ي ذَاهِبٌ اِلٰى رَبّ۪ي سَيَهْد۪ينِ', 'Ve kale inni zahibun ila rabbi seyehdin.', 'İbrahim: \"Ben,  Rabb\'ime gidiyorum[1],  O,  bana yol gösterecek.\" dedi.', 'وقال اني ذاهب الي ربي سيهدين'),
(3888, 37, 100, 'رَبِّ هَبْ ل۪ي مِنَ الصَّالِح۪ينَ', 'Rabbi heb li mines salihin.', '\"Rabb\'im! Bana salihlerden[1] bağışla.\"', 'رب هب لي من الصلحين'),
(3889, 37, 101, 'فَبَشَّرْنَاهُ بِغُلَامٍ حَل۪يمٍ', 'Fe beşşernahu bi gulamin halim.', 'Bunun üzerine onu yumuşak huylu bir oğulla müjdeledik.', 'فبشرنه بغلم حليم'),
(3890, 37, 102, 'فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَا بُنَيَّ اِنّ۪ٓي اَرٰى فِي الْمَنَامِ اَنّ۪ٓي اَذْبَحُكَ فَانْظُرْ مَاذَا تَرٰىۜ قَالَ يَٓا اَبَتِ افْعَلْ مَا تُؤْمَرُۘ سَتَجِدُن۪ٓي اِنْ شَٓاءَ اللّٰهُ مِنَ الصَّابِر۪ينَ', 'Fe lemma belega meahus sa\'ye kale ya buneyye inni era fil menami enni ezbehuke fanzur maza tera, kale ya ebetif\'al ma tu\'meru seteciduni inşaallahu mines sabirin.', 'Çocuk babasıyla birlikte iş tutacak çağa eriştiği zaman,  babası: \"Ey oğulcuğum! Ben,  uykumda seni boğazladığımı görüyorum. Bir düşün bakalım,  sen ne dersin?\" dedi. Çocuk: \"Ey babacığım! Sana buyurulanı yap. İnşallah beni sabredenlerden bulacaksın.\" dedi.', 'فلما بلغ معه السعي قال يبني اني اري في المنام اني اذبحك فانظر ماذا تري قال يابت افعل ما تومر ستجدني ان شا الله من الصبرين'),
(3891, 37, 103, 'فَلَمَّٓا اَسْلَمَا وَتَلَّهُ لِلْجَب۪ينِۚ', 'Fe lemma eslema ve tellehu lil cebin.', 'Sonra,  ikisi de teslim olup,  yanı üzere getirdi,', 'فلما اسلما وتله للجبين'),
(3892, 37, 104, 'وَنَادَيْنَاهُ اَنْ يَٓا اِبْرٰه۪يمُۙ', 'Ve nadeynahu en ya ibrahim.', '\"Ey İbrahim!\" diye ona seslendik.', 'ونادينه ان يابرهيم'),
(3893, 37, 105, 'قَدْ صَدَّقْتَ الرُّءْيَاۚ اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'Kad saddakter ru\'ya, inna kezalike neczil muhsinin.', 'Sen kesinlikle o rüyayı doğruladın. Biz,  Muhsinlere[1] işte böyle karşılık veririz.', 'قد صدقت الرويا انا كذلك نجزي المحسنين'),
(3894, 37, 106, 'اِنَّ هٰذَا لَهُوَ الْبَلٰٓؤُا الْمُب۪ينُ', 'İnne haza le huvel belaul mubin.', 'Bu,  kesin olarak apaçık bir beladır.[1]', 'ان هذا لهو البلوا المبين'),
(3895, 37, 107, 'وَفَدَيْنَاهُ بِذِبْحٍ عَظ۪يمٍ', 'Ve fedeynahu bi zibhın azim.', 'Ona fidye[1] olarak büyük bir kurbanlık verdik.[2]', 'وفدينه بذبح عظيم'),
(3896, 37, 108, 'وَتَرَكْنَا عَلَيْهِ فِي الْاٰخِر۪ينَ', 'Ve terekna aleyhi fil ahirin.', 'Gelecek nesiller arasında ona iyi bir ün bıraktık.', 'وتركنا عليه في الاخرين'),
(3897, 37, 109, 'سَلَامٌ عَلٰٓى اِبْرٰه۪يمَ', 'Selamun ala ibrahim.', 'İbrahim\'e selam olsun.', 'سلم علي ابرهيم'),
(3898, 37, 110, 'كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'Kezalike neczil muhsinin.', 'İşte Biz,  iyilere böyle karşılık veririz.', 'كذلك نجزي المحسنين'),
(3899, 37, 111, 'اِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِن۪ينَ', 'İnnehu min ibadinel mu\'minin.', 'O,  Bizim Mü\'min kullarımızdandı.', 'انه من عبادنا المومنين'),
(3900, 37, 112, 'وَبَشَّرْنَاهُ بِاِسْحٰقَ نَبِياًّ مِنَ الصَّالِح۪ينَ', 'Ve beşşernahu bi ishaka nebiyyen mines salihin.', 'Biz,  onu salihlerden bir nebi olan İshak ile müjdeledik.', 'وبشرنه باسحق نبيا من الصلحين'),
(3901, 37, 113, 'وَبَارَكْنَا عَلَيْهِ وَعَلٰٓى اِسْحٰقَۜ وَمِنْ ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِنَفْسِه۪ مُب۪ينٌ۟', 'Ve barekna aleyhi ve ala ishak, ve min zurriyyetihima muhsinun ve zalimun li nefsihi mubin.', 'Ona ve İshak\'a bereket verdik. Her ikisinin soyundan muhsin[1] olan da kendisine açıkça zulmeden[2] de vardır.', 'وبركنا عليه وعلي اسحق ومن ذريتهما محسن وظالم لنفسه مبين'),
(3902, 37, 114, 'وَلَقَدْ مَنَنَّا عَلٰى مُوسٰى وَهٰرُونَۚ', 'Ve lekad menenna ala musa ve harun.', 'Ant olsun ki Musa ve Harun\'a nimetler verdik.', 'ولقد مننا علي موسي وهرون'),
(3903, 37, 115, 'وَنَجَّيْنَاهُمَا وَقَوْمَهُمَا مِنَ الْكَرْبِ الْعَظ۪يمِۚ', 'Ve necceyna huma ve kavme huma minel kerbil azim.', 'O ikisini ve onlarla birlikte hareket eden halkı büyük sıkıntıdan kurtardık.', 'ونجينهما وقومهما من الكرب العظيم'),
(3904, 37, 116, 'وَنَصَرْنَاهُمْ فَكَانُوا هُمُ الْغَالِب۪ينَۚ', 'Ve nasarnahum fe kanu humul galibin.', 'Onlara yardım ettik. Galip gelenler onlar oldular.', 'ونصرنهم فكانوا هم الغلبين'),
(3905, 37, 117, 'وَاٰتَيْنَاهُمَا الْكِتَابَ الْمُسْتَب۪ينَۚ', 'Ve ateyna humel kitabel mustebin.', 'Onlara gerçekleri açıklayan kitap verdik.', 'واتينهما الكتب المستبين'),
(3906, 37, 118, 'وَهَدَيْنَاهُمَا الصِّرَاطَ الْمُسْتَق۪يمَۚ', 'Ve hedeyna humes sıratal mustekim.', 'Onları dosdoğru yola ilettik.', 'وهدينهما الصرط المستقيم'),
(3907, 37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِي الْاٰخِر۪ينَ', 'Ve terekna aleyhima fil ahirin.', 'Gelecek nesiller arasında ona iyi bir ün bıraktık.', 'وتركنا عليهما في الاخرين'),
(3908, 37, 120, 'سَلَامٌ عَلٰى مُوسٰى وَهٰرُونَ', 'Selamun ala musa ve harun.', 'Musa ve Harun\'a selam olsun.', 'سلم علي موسي وهرون'),
(3909, 37, 121, 'اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'İnna kezalike neczil muhsinin.', 'Biz,  muhsinleri böyle ödüllendiririz.', 'انا كذلك نجزي المحسنين'),
(3910, 37, 122, 'اِنَّهُمَا مِنْ عِبَادِنَا الْمُؤْمِن۪ينَ', 'İnne huma min ibadinel mu\'minin.', 'İkisi de Bizim Mü\'min kullarımızdandı.', 'انهما من عبادنا المومنين'),
(3911, 37, 123, 'وَاِنَّ اِلْيَاسَ لَمِنَ الْمُرْسَل۪ينَۜ', 'Ve inne ilyase le minel murselin.', 'İlyas da kesinlikle gönderilenlerdendir.', 'وان الياس لمن المرسلين'),
(3912, 37, 124, 'اِذْ قَالَ لِقَوْمِه۪ٓ اَلَا تَتَّقُونَ', 'İz kale li kavmihi e la tettekun.', 'Hani o,  halkına: \"Siz,  takva[1] sahibi olmayacak mısınız?\" demişti.', 'اذ قال لقومه الا تتقون'),
(3913, 37, 125, 'اَتَدْعُونَ بَعْلاً وَتَذَرُونَ اَحْسَنَ الْخَالِق۪ينَۙ', 'Eted\'une ba\'len ve tezerune ahsenel halikin.', '\"Yaratanların en iyisini bırakıp da Ba\'le[1] mi yöneliyorsunuz?\"', 'اتدعون بعلا وتذرون احسن الخلقين'),
(3914, 37, 126, 'اَللّٰهَ رَبَّكُمْ وَرَبَّ اٰبَٓائِكُمُ الْاَوَّل۪ينَ', 'Allahe rabbekum ve rabbe abaikumul evvelin.', '\"Allah,  sizin ve atalarınızın Rabb\'idir.\"', 'الله ربكم ورب ابايكم الاولين'),
(3915, 37, 127, 'فَكَذَّبُوهُ فَاِنَّهُمْ لَمُحْضَرُونَۙ', 'Fe kezzebuhu fe inne hum le muhdarun.', 'Ancak onu yalanladılar. Kuşkusuz onlar hazır bulundurulacak olanlardır.[1]', 'فكذبوه فانهم لمحضرون'),
(3916, 37, 128, 'اِلَّا عِبَادَ اللّٰهِ الْمُخْلَص۪ينَ', 'İlla ibadallahil muhlasin.', 'Allah\'ın muhles kulları hariç.', 'الا عباد الله المخلصين'),
(3917, 37, 129, 'وَتَرَكْنَا عَلَيْهِ فِي الْاٰخِر۪ينَ', 'Ve terekna aleyhi fil ahirin.', 'Gelecek nesiller arasında ona iyi bir ün bıraktık.', 'وتركنا عليه في الاخرين'),
(3918, 37, 130, 'سَلَامٌ عَلٰٓى اِلْ‌يَاس۪ينَ', 'Selamun ala ilyasin.', 'İlyas\'a selam olsun.', 'سلم علي ال ياسين'),
(3919, 37, 131, 'اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'İnna kezalike neczil muhsinin.', 'İşte Biz,  iyilere böyle karşılık veririz.', 'انا كذلك نجزي المحسنين'),
(3920, 37, 132, 'اِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِن۪ينَ', 'İnnehu min ibadinel mu\'minin.', 'O,  Bizim Mü\'min kullarımızdandı.', 'انه من عبادنا المومنين'),
(3921, 37, 133, 'وَاِنَّ لُوطاً لَمِنَ الْمُرْسَل۪ينَۜ', 'Ve inne lutan le minel murselin.', 'Lut da kesinlikle gönderilenlerdendir.', 'وان لوطا لمن المرسلين'),
(3922, 37, 134, 'اِذْ نَجَّيْنَاهُ وَاَهْلَـهُٓ اَجْمَع۪ينَۙ', 'İz necceynahu ve ehlehu ecmain.', 'Hani onu ve yanında yer alanların tamamını kurtarmıştık.', 'اذ نجينه واهله اجمعين'),
(3923, 37, 135, 'اِلَّا عَجُوزاً فِي الْغَابِر۪ينَ', 'İlla acuzen fil gabirin.', 'Ancak geride kalan acuze[1] bir kadın hariç.', 'الا عجوزا في الغبرين'),
(3924, 37, 136, 'ثُمَّ دَمَّرْنَا الْاٰخَر۪ينَ', 'Summe demmernel aharin.', 'Sonra diğerlerini dumura uğrattık.', 'ثم دمرنا الاخرين'),
(3925, 37, 137, 'وَاِنَّكُمْ لَتَمُرُّونَ عَلَيْهِمْ مُصْبِح۪ينَۙ', 'Ve innekum le temurrune aleyhim musbihin.', 'Siz,  gündüz onların yanlarından geçip gidiyorsunuz.', 'وانكم لتمرون عليهم مصبحين'),
(3926, 37, 138, 'وَبِالَّيْلِۜ اَفَلَا تَعْقِلُونَ۟', 'Ve bil leyl, e fe la ta\'kılun.', 'Ve geceleyin de. Hala aklınızı kullanmayacak mısınız?', 'وباليل افلا تعقلون'),
(3927, 37, 139, 'وَاِنَّ يُونُسَ لَمِنَ الْمُرْسَل۪ينَۜ', 'Ve inne yunuse le minel murselin.', 'Yunus da kesinlikle gönderilenlerdendir.', 'وان يونس لمن المرسلين'),
(3928, 37, 140, 'اِذْ اَبَقَ اِلَى الْفُلْكِ الْمَشْحُونِۙ', 'İz ebeka ilel fulkil meşhun.', 'Hani o,  dolu gemiye kaçmıştı.', 'اذ ابق الي الفلك المشحون'),
(3929, 37, 141, 'فَسَاهَمَ فَكَانَ مِنَ الْمُدْحَض۪ينَۚ', 'Fe saheme fe kane minel mudhadin.', 'Sonra kura çekti ve kaybedenlerden oldu.', 'فساهم فكان من المدحضين'),
(3930, 37, 142, 'فَالْتَقَمَهُ الْحُوتُ وَهُوَ مُل۪يمٌ', 'Feltekamehul hutu ve huve mulim.', 'O kendisini suçlayıp dururken,  hut[1] onu yuttu.', 'فالتقمه الحوت وهو مليم'),
(3931, 37, 143, 'فَلَوْلَٓا اَنَّهُ كَانَ مِنَ الْمُسَبِّح۪ينَۙ', 'Fe lev la ennehu kane minel musebbihin.', 'Eğer o gerçekten tesbih[1] edenlerden olmasaydı;', 'فلولا انه كان من المسبحين'),
(3932, 37, 144, 'لَلَبِثَ ف۪ي بَطْنِه۪ٓ اِلٰى يَوْمِ يُبْعَثُونَ', 'Le lebise fi batnihi ila yevmi yub\'asun.', 'Diriltilecekleri güne kadar[1] balığın karnında kalırdı.', 'للبث في بطنه الي يوم يبعثون'),
(3933, 37, 145, 'فَنَبَذْنَاهُ بِالْعَرَٓاءِ وَهُوَ سَق۪يمٌۚ', 'Fe nebeznahu bil arai ve huve sakim.', 'Sonunda,  onu bitkin bir halde ıssız bir yere attık.', 'فنبذنه بالعرا وهو سقيم'),
(3934, 37, 146, 'وَاَنْبَتْنَا عَلَيْهِ شَجَرَةً مِنْ يَقْط۪ينٍۚ', 'Ve enbetna aleyhi şecereten min yaktin.', 'Onun üzerine geniş yapraklılardan bir ağaç bitirdik.', 'وانبتنا عليه شجرة من يقطين'),
(3935, 37, 147, 'وَاَرْسَلْنَاهُ اِلٰى مِائَةِ اَلْفٍ اَوْ يَز۪يدُونَۚ', 'Ve erselnahu ila mieti elfin ev yezidun.', 'Onu,  nüfusu yüz binden fazla bir halka Resul olarak gönderdik.', 'وارسلنه الي ماية الف او يزيدون'),
(3936, 37, 148, 'فَاٰمَنُوا فَمَتَّعْنَاهُمْ اِلٰى ح۪ينٍۜ', 'Fe amenu fe metta\'nahum ila hin.', 'Bu sefer inandılar. Biz de onları belli bir süre yararlandırdık.', 'فامنوا فمتعنهم الي حين'),
(3937, 37, 149, 'فَاسْتَفْتِهِمْ اَلِرَبِّكَ الْبَنَاتُ وَلَهُمُ الْبَنُونَۙ', 'Festeftihim e li rabbikel benatu ve lehumul benun.', 'Haydi,  onlara sor: \"Kız çocuklar Rabb\'inin de oğlan çocuklar onların mı?\"', 'فاستفتهم الربك البنات ولهم البنون'),
(3938, 37, 150, 'اَمْ خَلَقْنَا الْمَلٰٓئِكَةَ اِنَاثاً وَهُمْ شَاهِدُونَ', 'Em halaknel melaikete inasen ve hum şahidun.', 'Yoksa Biz melekleri dişi olarak yarattık da onlar buna tanık mı oldular?', 'ام خلقنا المليكة انثا وهم شهدون'),
(3939, 37, 151, 'اَلَٓا اِنَّهُمْ مِنْ اِفْكِهِمْ لَيَقُولُونَۙ', 'E la innehum min ifkihim le yekulun.', 'Dikkat edin! Doğrusu uydurdukları iftiralarından dolayı;', 'الا انهم من افكهم ليقولون'),
(3940, 37, 152, 'وَلَدَ اللّٰهُۙ وَاِنَّهُمْ لَكَاذِبُونَ', 'Veledallahu ve innehum le kazibun.', '\"Allah\'ın çocuğu oldu.\" diyorlar. Onlar,  kesinlikle yalancıdırlar.', 'ولد الله وانهم لكذبون'),
(3941, 37, 153, 'اَصْطَفَى الْبَنَاتِ عَلَى الْبَن۪ينَۜ', 'Astafel benati alel benin.', 'Allah; kızları,  oğullara tercih etmiş öyle mi?', 'اصطفي البنات علي البنين'),
(3942, 37, 154, 'مَا لَـكُمْ۠  كَيْفَ تَحْكُمُونَ', 'Ma lekum, keyfe tahkumun.', 'Size ne oluyor? Nasıl böyle bir hüküm veriyorsunuz?', 'ما لكم كيف تحكمون'),
(3943, 37, 155, 'اَفَلَا تَذَكَّرُونَۚ', 'E fe la tezekkerun.', 'Hiç mi öğüt almıyorsunuz?', 'افلا تذكرون'),
(3944, 37, 156, 'اَمْ لَـكُمْ سُلْطَانٌ مُب۪ينٌۙ', 'Em lekum sultanun mubin.', 'Yoksa elinizde açık bir belgeniz mi var?', 'ام لكم سلطن مبين'),
(3945, 37, 157, 'فَأْتُوا بِكِتَابِكُمْ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Fe\'tu bi kitabikum in kuntum sadikin.', 'Eğer doğru söyleyenlerdenseniz,  o halde kitabınızı[1] getirin.', 'فاتوا بكتبكم ان كنتم صدقين'),
(3946, 37, 158, 'وَجَعَلُوا بَيْنَهُ وَبَيْنَ الْجِنَّةِ نَسَباًۜ وَلَقَدْ عَلِمَتِ الْجِنَّةُ اِنَّهُمْ لَمُحْضَرُونَۙ', 'Ve cealu beynehu ve beynel cinneti neseba, ve lekad alimetil cinnetu innehum le muhdarun.', 'Allah ile cinler[1] arasında soy bağı uydurdular. Ant olsun ki cinler de kesinlikle onların hazır bulundurulacaklarını[2] bilmektedirler.', 'وجعلوا بينه وبين الجنة نسبا ولقد علمت الجنة انهم لمحضرون'),
(3947, 37, 159, 'سُبْحَانَ اللّٰهِ عَمَّا يَصِفُونَۙ', 'Subhanallahi amma yasifun.', 'Allah,  onların niteledikleri şeyden münezzehtir.[1]', 'سبحن الله عما يصفون'),
(3948, 37, 160, 'اِلَّا عِبَادَ اللّٰهِ الْمُخْلَص۪ينَ', 'İlla ibadallahil muhlasin.', 'Allah\'ın muhles kulları hariç.', 'الا عباد الله المخلصين'),
(3949, 37, 161, 'فَاِنَّكُمْ وَمَا تَعْبُدُونَۙ', 'Fe innekum ve ma ta\'budun.', 'Artık siz ve kulluk yaptıklarınız,', 'فانكم وما تعبدون'),
(3950, 37, 162, 'مَٓا اَنْتُمْ عَلَيْهِ بِفَاتِن۪ينَۙ', 'Ma entum aleyhi bi fatinin.', 'O\'na karşı fitneye düşüremezsiniz.', 'ما انتم عليه بفتنين'),
(3951, 37, 163, 'اِلَّا مَنْ هُوَ صَالِ الْجَح۪يمِ', 'İlla men huve salil cahim.', 'Cehennem\'e girecekler hariç.', 'الا من هو صال الجحيم'),
(3952, 37, 164, 'وَمَا مِنَّٓا اِلَّا لَهُ مَقَامٌ مَعْلُومٌ', 'Ve ma minna illa lehu makamun ma\'lum.', '\"Bizden her birimizin belli bir makamı vardır.\"', 'وما منا الا له مقام معلوم'),
(3953, 37, 165, 'وَاِنَّا لَنَحْنُ الصَّٓافُّونَۚ', 'Ve inna le nahnus saffun.', '\"Biziz biz,  saf saf duranlar.\"', 'وانا لنحن الصافون'),
(3954, 37, 166, 'وَاِنَّا لَنَحْنُ الْمُسَبِّحُونَ', 'Ve inna le nahnul musebbihun.', '\"Biziz biz,  tesbih[1] edenler.\"', 'وانا لنحن المسبحون'),
(3955, 37, 167, 'وَاِنْ كَانُوا لَيَقُولُونَۙ', 'Ve in kanu le yekulun.', 'Eğer diyecek olurlarsa:', 'وان كانوا ليقولون'),
(3956, 37, 168, 'لَوْ اَنَّ عِنْدَنَا ذِكْراً مِنَ الْاَوَّل۪ينَۙ', 'Lev enne indena zikren minel evvelin.', '\"Yanımızda öncekilere verilen öğüt[1] gibi bir öğüt olsaydı.\"', 'لو ان عندنا ذكرا من الاولين'),
(3957, 37, 169, 'لَـكُنَّا عِبَادَ اللّٰهِ الْمُخْلَص۪ينَ', 'Le kunna ibadallahil muhlasin.', '\"Biz de Allah\'ın muhles kullarından olurduk.\"', 'لكنا عباد الله المخلصين'),
(3958, 37, 170, 'فَـكَفَرُوا بِه۪ۚ فَسَوْفَ يَعْلَمُونَ', 'Fe keferu bih, fe sevfe ya\'lemun.', 'Fakat onu[1] yalanladılar. Artık yakında bilecekler.', 'فكفروا به فسوف يعلمون'),
(3959, 37, 171, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا الْمُرْسَل۪ينَۚ', 'Ve lekad sebekat kelimetuna li ibadinel murselin.', 'Ant olsun ki gönderilen kullarımıza şu sözü verdik:', 'ولقد سبقت كلمتنا لعبادنا المرسلين'),
(3960, 37, 172, 'اِنَّهُمْ لَهُمُ الْمَنْصُورُونَۖ', 'İnnehum le humul mensurun.', 'Onlar,  kesinlikle yardım edilecek olanlardır.', 'انهم لهم المنصورون'),
(3961, 37, 173, 'وَاِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ', 'Ve inne cundena le humul galibun.', 'Bizim ordumuz onlara mutlaka galip gelecektir.', 'وان جندنا لهم الغلبون'),
(3962, 37, 174, 'فَتَوَلَّ عَنْهُمْ حَتّٰى ح۪ينٍۙ', 'Fe tevelle anhum hatta hin.', 'Artık bir süre onlardan yüz çevir.', 'فتول عنهم حتي حين'),
(3963, 37, 175, 'وَاَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', 'Ve ebsirhum fe sevfe yubsirun.', 'Onları gözle! Yakında onlar da görecekler.', 'وابصرهم فسوف يبصرون'),
(3964, 37, 176, 'اَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'E fe bi azabina yesta\'cilun.', 'Yoksa azabımızı acele mi istiyorlar?', 'افبعذابنا يستعجلون'),
(3965, 37, 177, 'فَاِذَا نَزَلَ بِسَاحَتِهِمْ فَسَٓاءَ صَبَاحُ الْمُنْذَر۪ينَ', 'Fe iza nezele bisahatihim fe sae sabahul munzerin.', 'Fakat onların bulundukları yere indiği zaman,  uyarılanların sabahı ne kötüdür!', 'فاذا نزل بساحتهم فسا صباح المنذرين'),
(3966, 37, 178, 'وَتَوَلَّ عَنْهُمْ حَتّٰى ح۪ينٍۙ', 'Ve tevelle anhum hatta hin.', 'Artık bir süre onlardan yüz çevir.', 'وتول عنهم حتي حين'),
(3967, 37, 179, 'وَاَبْصِرْ فَسَوْفَ يُبْصِرُونَ', 'Ve ebsir fe sevfe yubsirun.', 'Onları gözle! Yakında onlar da görecekler.', 'وابصر فسوف يبصرون'),
(3968, 37, 180, 'سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَۚ', 'Subhane rabbike rabbil izzeti amma yasifun.', 'İzzetin[1] Rabbi olan Rabb\'in,  onların nitelediği şeylerden münezzehtir.', 'سبحن ربك رب العزة عما يصفون'),
(3969, 37, 181, 'وَسَلَامٌ عَلَى الْمُرْسَل۪ينَۚ', 'Ve selamun alel murselin.', 'Gönderilenlere[1] selam olsun.', 'وسلم علي المرسلين'),
(3970, 37, 182, 'وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَ', 'Vel hamdu lillahi rabbil alemin.', 'Hamd,  alemlerin Rabbi Allah\'adır.', 'والحمد لله رب العلمين'),
(3971, 38, 1, 'صٓ وَالْقُرْاٰنِ ذِي الذِّكْرِۜ', 'Sad, vel kur\'ani ziz zikr.', 'Sad. Zikir[1] sahibi Kur\'an\'a ant olsun.', 'ص والقران ذي الذكر'),
(3972, 38, 2, 'بَلِ الَّذ۪ينَ كَفَرُوا ف۪ي عِزَّةٍ وَشِقَاقٍ', 'Belillezine keferu fi ızzetin ve şikak.', 'Doğrusu Kafirler[1] büyüklenmelerine yediremediklerinden muhalefet ediyorlar.', 'بل الذين كفروا في عزة وشقاق'),
(3973, 38, 3, 'كَمْ اَهْلَكْنَا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ فَنَادَوْا وَلَاتَ ح۪ينَ مَنَاصٍ', 'Kem ehlekna min kablihim min karnin fe nadev ve late hine menas.', 'Onlardan önce nice kuşakları yok ettik. O zaman feryat ettiler,  ama artık kurtuluş vakti geçmişti.', 'كم اهلكنا من قبلهم من قرن فنادوا ولات حين مناص'),
(3974, 38, 4, 'وَعَجِبُٓوا اَنْ جَٓاءَهُمْ مُنْذِرٌ مِنْهُمْۘ وَقَالَ الْكَافِرُونَ هٰذَا سَاحِرٌ كَذَّابٌۚ', 'Ve acibu en caehum munzirun minhum ve kalel kafirune haza sahırun kezzab.', 'İçlerinden,  kendilerine bir uyarıcı gelmesine şaşırdılar. Kafirler: \"Bu,  yalancı bir büyücüdür.\" dediler.', 'وعجبوا ان جاهم منذر منهم وقال الكفرون هذا سحر كذاب'),
(3975, 38, 5, 'اَجَعَلَ الْاٰلِهَةَ اِلٰهاً وَاحِداًۚ اِنَّ هٰذَا لَشَيْءٌ عُجَابٌ', 'E cealel alihete ilahen vahıda, inne haza le şey\'un ucab.', '\"O,  bunca ilahı,  bir tek ilah mı kılıyor? Kuşkusuz bu şaşılacak bir şeydir.\"', 'اجعل الالهة الها وحدا ان هذا لشي عجاب'),
(3976, 38, 6, 'وَانْطَلَقَ الْمَلَأُ مِنْهُمْ اَنِ امْشُوا وَاصْبِرُوا عَلٰٓى اٰلِهَتِكُمْۚ اِنَّ هٰذَا لَشَيْءٌ يُرَادُۚ', 'Ventalekal meleu minhum enimşu vasbiru ala alihetikum inne haza le şey\'un yurad.', 'Onlardan,  meleler[1] harekete geçerek: \"Bildiğiniz yoldan gitmeye devam edin,  ilahlarınızı bırakmayın. Kesinlikle sizden beklenen budur.\" dediler.', 'وانطلق الملا منهم ان امشوا واصبروا علي الهتكم ان هذا لشي يراد'),
(3977, 38, 7, 'مَا سَمِعْنَا بِهٰذَا فِي الْمِلَّةِ الْاٰخِرَةِۚ  اِنْ هٰذَٓا اِلَّا اخْتِلَاقٌۚ', 'Ma semi\'na bi haza fil milletil ahıreh, in haza illahtilak.', '\"Biz,  bunu[1] son inanç sistemlerinde de duymadık. Bu yalnızca bir uydurmadır.\"', 'ما سمعنا بهذا في الملة الاخرة ان هذا الا اختلق'),
(3978, 38, 8, 'ءَاُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنَاۜ بَلْ هُمْ ف۪ي شَكٍّ مِنْ ذِكْر۪يۚ بَلْ لَمَّا يَذُوقُوا عَذَابِۜ', 'E unzile aleyhiz zikru min beynina, bel hum fi şekkin min zikri, bel lemma yezuku azab.', '\"Zikir[1],  aramızda ona mı indirildi?\" Oysaki onlar Benim zikrimden kuşku içindedirler. Hayır,  onlar azabımı henüz tatmadılar.', 'انزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب'),
(3979, 38, 9, 'اَمْ عِنْدَهُمْ خَزَٓائِنُ رَحْمَةِ رَبِّكَ الْعَز۪يزِ الْوَهَّابِۚ', 'Em indehum hazainu rahmeti rabbikel azizil vehhab.', 'Yoksa Çok Yüce ve Çok Bağışta Bulunan Rabb\'inin rahmet hazineleri onların yanında mı?', 'ام عندهم خزاين رحمة ربك العزيز الوهاب'),
(3980, 38, 10, 'اَمْ لَهُمْ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا۠ فَلْيَرْتَقُوا فِي الْاَسْبَابِ', 'Em lehum mulkus semavati vel ardı ve ma beynehuma, felyerteku fil esbab.', 'Ya da göklerin,  yerin ve ikisi arasındakilerin mülkü onlara mı ait? O halde sebepler bulsunlar da yükselsinler!', 'ام لهم ملك السموت والارض وما بينهما فليرتقوا في الاسبب'),
(3981, 38, 11, 'جُنْدٌ مَا هُنَالِكَ مَهْزُومٌ مِنَ الْاَحْزَابِ', 'Cundun ma hunalike mehzumun minel ahzab.', 'Onlar,  burada bozguna uğramış gruplardan meydana gelmiş bir ordudur.', 'جند ما هنالك مهزوم من الاحزاب'),
(3982, 38, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُوالْاَوْتَادِۙ', 'Kezzebet kablehum kavmu nuhın ve adun ve fir\'avnu zul evtadi.', 'Onlardan önce Nuh toplumu,  Âd,  kazıklar sahibi Firavun da yalanlamıştı.', 'كذبت قبلهم قوم نوح وعاد وفرعون ذو الاوتاد'),
(3983, 38, 13, 'وَثَمُودُ وَقَوْمُ لُوطٍ وَاَصْحَابُ لْـَٔيْكَةِۜ  اُو۬لٰٓئِكَ الْاَحْزَابُ', 'Ve semudu ve kavmu lutın ve ashabul eykeh, ulaikel ahzab.', 'Ve Semud,  Lut\'un halkı ve Eyke halkı; işte onlar da işbirlikçi gruplardır.', 'وثمود وقوم لوط واصحب ليكة اوليك الاحزاب'),
(3984, 38, 14, 'اِنْ كُلٌّ اِلَّا كَذَّبَ الرُّسُلَ فَحَقَّ عِقَابِ۟', 'İn kullun illa kezzeber rusule fe hakka ıkab.', 'Onların hepsi de resulleri yalanladı. Bu nedenle azabımı hak ettiler.', 'ان كل الا كذب الرسل فحق عقاب'),
(3985, 38, 15, 'وَمَا يَنْظُرُ هٰٓؤُ۬لَٓاءِ اِلَّا صَيْحَةً وَاحِدَةً مَا لَهَا مِنْ فَوَاقٍ', 'Ve ma yanzuru haulai illa sayhaten vahıdeten ma leha min fevak.', 'Bunlar geri dönüşü olmayan bir çığlıktan başkasını beklemiyorlar.', 'وما ينظر هولا الا صيحة وحدة ما لها من فواق'),
(3986, 38, 16, 'وَقَالُوا رَبَّنَا عَجِّلْ لَنَا قِطَّنَا قَبْلَ يَوْمِ الْحِسَابِ', 'Ve kalu rabbena accil lena kıttana kable yevmil hisab.', 'Ve: \"Rabb\'imiz,  Hesap Günü\'nden önce[1] azaptan payımıza düşeni hemen ver.\" dediler.', 'وقالوا ربنا عجل لنا قطنا قبل يوم الحساب'),
(3987, 38, 17, 'اِصْبِرْ عَلٰى مَا يَقُولُونَ وَاذْكُرْ عَبْدَنَا دَاوُ۫دَ ذَا الْاَيْدِۚ اِنَّـهُٓ  اَوَّابٌ', 'Isbır ala ma yekulune vezkur abdena davude zel eyd, innehu evvab.', 'Onların dediklerine sabret,  güçlerin sahibi kulumuz Davud\'u düşün. O,  her durumda Allah\'a yönelirdi.', 'اصبر علي ما يقولون واذكر عبدنا داود ذا الايد انه اواب'),
(3988, 38, 18, 'اِنَّا سَخَّرْنَا الْجِبَالَ مَعَهُ يُسَبِّحْنَ بِالْعَشِيِّ وَالْاِشْرَاقِۙ', 'İnna sahharnel cibale meahu yusebbıhne bil aşiyyi vel işrak.', 'Dağları boyun eğdirdik. Akşamdan gündoğumuna[1] onunla birlikte tesbih[2] ederlerdi.', 'انا سخرنا الجبال معه يسبحن بالعشي والاشراق'),
(3989, 38, 19, 'وَالطَّيْرَ مَحْشُورَةًۜ   كُلٌّ لَـهُٓ  اَوَّابٌ', 'Vet tayre mahşureh, kullun lehu evvab.', 'Kuşların tamamı toplu halde ona yönelmişlerdi.', 'والطير محشورة كل له اواب'),
(3990, 38, 20, 'وَشَدَدْنَا مُلْكَهُ وَاٰتَيْنَاهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ', 'Ve şededna mulkehu ve ateynahul hikmete ve faslel hıtab.', 'Onun gücünü pekiştirdik. Ona hikmeti[1] ve fesle-l hitabı[2] verdik.', 'وشددنا ملكه واتينه الحكمة وفصل الخطاب'),
(3991, 38, 21, 'وَهَلْ اَتٰيكَ نَـبَؤُا الْخَصْمِۢ  اِذْ تَسَوَّرُوا الْمِحْرَابَۙ', 'Ve hel etake nebeul hasm, iz tesevverul mihrab.', 'Birbirleriyle davalıların haberi sana geldi mi? Duvarı aşarak mihraba gelmişlerdi!', 'وهل اتيك نبوا الخصم اذ تسوروا المحراب'),
(3992, 38, 22, 'اِذْ دَخَلُوا عَلٰى دَاوُ۫دَ فَفَزِعَ مِنْهُمْ قَالُوا لَا تَخَفْۚ خَصْمَانِ بَغٰى بَعْضُنَا عَلٰى بَعْضٍ فَاحْكُمْ بَيْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ وَاهْدِنَٓا اِلٰى سَوَٓاءِ الصِّرَاطِ', 'İz dehalu ala davude fe fezia minhum kalu la tehaf, hasmani bega ba\'duna ala ba\'dın fahkum beynena bil hakkı ve la tuştıt vehdina ila sevais sırat.', 'Davud\'un yanına girdiklerinde o,  onlardan korktu. \"Korkma! İki davacıyız. Birimiz ötekine haksızlık etti. Şimdi sen,  hakkımızda hakk ile hüküm ver. Haksızlık etme. Bize makul olan yolu göster.\" dediler.', 'اذ دخلوا علي داود ففزع منهم قالوا لا تخف خصمان بغي بعضنا علي بعض فاحكم بيننا بالحق ولا تشطط واهدنا الي سوا الصرط'),
(3993, 38, 23, 'اِنَّ هٰذَٓا اَخ۪ي لَهُ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِيَ نَعْجَةٌ وَاحِدَةٌ فَقَالَ اَكْفِلْن۪يهَا وَعَزَّن۪ي فِي الْخِطَابِ', 'İnne haza ahi lehu tis\'un ve tis\'une na\'ceten ve liye na\'cetun vahidetun fe kale ekfilniha ve azzeni fil hıtab.', '\"Bu benim kardeşim[1] Onun doksan dokuz koyunu var ve benim bir tek koyunum var. Buna rağmen onu da kendisine vermemi istedi ve tartışmamızda bana üstünlük sağladı.[2]\"', 'ان هذا اخي له تسع وتسعون نعجة ولي نعجة وحدة فقال اكفلنيها وعزني في الخطاب'),
(3994, 38, 24, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ اِلٰى نِعَاجِه۪ۜ وَاِنَّ كَث۪يراً مِنَ الْخُلَطَٓاءِ لَيَبْغ۪ي بَعْضُهُمْ عَلٰى بَعْضٍ اِلَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَقَل۪يلٌ مَا هُمْۜ وَظَنَّ دَاوُ۫دُ اَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَا‌كِعاً وَاَنَابَ', 'Kale lekad zalemeke bi suali na\'cetike ila niacih, ve inne kesiren minel huletai le yebgi ba\'duhum ala ba\'dın illellezine amenu ve amilus salihati ve kalilun ma hum, ve zanne davudu ennema fetennahu festagfere rabbehu ve harre rakian ve enab.', '\"Gerçekten,  senin koyununu kendi koyunlarına katmayı istemekle doğrusu sana haksızlık etmiştir. Ortakların çoğu,  birbirlerine haksızlık ediyorlar. Ancak iman edenler ve salihatı[1] yapanlar haksızlık etmezler. Ancak onlar da ne kadar azdır!\" dedi. Davud,  kendisini fitnelendirdiğimizi[2] iyice anladı. Hemen Rabbinden bağışlanma[3] diledi,  ruku[4] ederek,  tam bir teslimiyetle Rabb\'ine yöneldi.[5]', 'قال لقد ظلمك بسوال نعجتك الي نعاجه وان كثيرا من الخلطا ليبغي بعضهم علي بعض الا الذين امنوا وعملوا الصلحت وقليل ما هم وظن داود انما فتنه فاستغفر ربه وخر راكعا واناب'),
(3995, 38, 25, 'فَغَفَرْنَا لَهُ ذٰلِكَۜ وَاِنَّ لَهُ عِنْدَنَا لَزُلْفٰى وَحُسْنَ مَاٰبٍ', 'Fe gaferna lehu zalik, ve inne lehu indena le zulfa ve husne meab.', 'Böylece onu bundan dolayı bağışladık. Onun yanımızda yüksek konumu ve iyi bir sığınağı vardır.', 'فغفرنا له ذلك وان له عندنا لزلفي وحسن ماب'),
(3996, 38, 26, 'يَا دَاوُ۫دُ اِنَّا جَعَلْنَاكَ خَل۪يفَةً فِي الْاَرْضِ فَاحْكُمْ بَيْنَ النَّاسِ بِالْحَقِّ وَلَا تَتَّبِعِ الْهَوٰى فَيُضِلَّكَ عَنْ سَب۪يلِ اللّٰهِۜ  اِنَّ الَّذ۪ينَ يَضِلُّونَ عَنْ سَب۪يلِ اللّٰهِ لَهُمْ عَذَابٌ شَد۪يدٌ بِمَا نَسُوا يَوْمَ الْحِسَابِ۟', 'Ya davudu inna cealnake halifeten fil ardı fahkum beynen nasi bil hakkı ve la tettebiil heva fe yudılleke an sebilillah, innellezine yadıllune an sebilillahi lehum azabun şedidun bi ma nesu yevmel hisab.', 'Ey Davud! Biz seni yeryüzünde bir halife[1] yaptık. İnsanlar arasında Hakk ile hükmet. Hevaya[2] uyma. Aksi halde heva seni Allah\'ın yolundan saptırır. Allah\'ın yolundan sapanlar,  hesap gününü göz ardı etmiş olduklarından,  kendileri için çok şiddetli bir azap vardır.', 'يداود انا جعلنك خليفة في الارض فاحكم بين الناس بالحق ولا تتبع الهوي فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب'),
(3997, 38, 27, 'وَمَا خَلَقْنَا السَّمَٓاءَ وَالْاَرْضَ وَمَا بَيْنَهُمَا بَاطِلاًۜ ذٰلِكَ ظَنُّ الَّذ۪ينَ كَفَرُواۚ فَوَيْلٌ لِلَّذ۪ينَ كَفَرُوا مِنَ النَّارِۜ', 'Ve ma halaknes semae vel arda ve ma beynehuma batıla, zalike zannullezine keferu, fe veylun lillezine keferu minen nar.', 'Biz,  göğü,  yeri ve ikisi arasında olanları boşuna yaratmadık. Bu,  Kafirlerin görüşüdür. Kendilerini ateşe atan,  Kafirlerin vay haline.', 'وما خلقنا السما والارض وما بينهما بطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار'),
(3998, 38, 28, 'اَمْ نَجْعَلُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَالْمُفْسِد۪ينَ فِي الْاَرْضِۘ اَمْ نَجْعَلُ الْمُتَّق۪ينَ كَالْفُجَّارِ', 'Em nec\'alullezine amenu ve amilus salihati kel mufsidine fil ardı em nec\'alul muttekine kel fuccar.', 'İman eden ve salihatı[1] yapanları,  yeryüzünde bozgunculuk yapanlarla bir tutar mıyız? Ya da takva sahiplerini facirlerle[2] bir tutar mıyız?', 'ام نجعل الذين امنوا وعملوا الصلحت كالمفسدين في الارض ام نجعل المتقين كالفجار'),
(3999, 38, 29, 'كِتَابٌ اَنْزَلْنَاهُ اِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُٓوا اٰيَاتِه۪ وَلِيَتَذَكَّرَ اُو۬لُوا الْاَلْبَابِ', 'Kitabun enzelnahu ileyke mubarekun li yeddebberu ayatihi ve li yetezekkere ulul elbab.', 'Bu; akıl sahiplerinin,  ayetlerini düşünüp öğüt almaları için,  sana indirdiğimiz kutlu bir Kitap\'tır.', 'كتب انزلنه اليك مبرك ليدبروا ايته وليتذكر اولوا الالبب'),
(4000, 38, 30, 'وَوَهَبْنَا لِدَاوُ۫دَ سُلَيْمٰنَۜ نِعْمَ الْعَبْدُۜ اِنَّهُٓ  اَوَّابٌۜ', 'Ve vehebna li davude suleyman, ni\'mel abd, innehu evvab.', 'Davud\'a Süleyman\'ı armağan ettik. Ne güzel bir kuldu. O,  her zaman Allah\'a yönelendi.', 'ووهبنا لداود سليمن نعم العبد انه اواب'),
(4001, 38, 31, 'اِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ الْجِيَادُۙ', 'İz urıda aleyhi bil aşiyyis safinatul ciyad.', 'Bir zaman kendisine,  akşamüstü iyi cins safkan atlar sunulmuştu.', 'اذ عرض عليه بالعشي الصفنت الجياد'),
(4002, 38, 32, 'فَقَالَ اِنّ۪ٓي اَحْبَبْتُ حُبَّ الْخَيْرِ عَنْ ذِكْرِ رَبّ۪يۚ حَتّٰى تَوَارَتْ بِالْحِجَابِ۠', 'Fe kale inni ahbebtu hubbel hayri an zikri rabbi, hatta tevaret bil hıcab.', '\"Doğrusu ben Rabb\'imin öğüdünden dolayı hayra muhabbeti sevdim.\"[1] dedi. Derken gözden kayboldular.[2]', 'فقال اني احببت حب الخير عن ذكر ربي حتي توارت بالحجاب'),
(4003, 38, 33, 'رُدُّوهَا عَلَيَّۜ فَطَفِقَ مَسْحاً بِالسُّوقِ وَالْاَعْنَاقِ', 'Rudduha aleyy, fe tafika meshan bis sukı vel a\'nak.', '\"Onları bana geri getirin.\" Ardından bacaklarını ve boyunlarını mesh[1] etmeye başladı.[2]', 'ردوها علي فطفق مسحا بالسوق والاعناق'),
(4004, 38, 34, 'وَلَقَدْ فَتَنَّا سُلَيْمٰنَ وَاَلْقَيْنَا عَلٰى كُرْسِيِّه۪ جَسَداً ثُمَّ اَنَابَ', 'Ve lekad fetenna suleymane ve elkayna ala kursiyyihi ceseden summe enab.', 'Ant olsun ki Süleyman\'ı fitnelendirdik.[1] Kürsüsünün[2] üzerine bir ceset bıraktık.[3] Sonra o Bize yöneldi.[4]', 'ولقد فتنا سليمن والقينا علي كرسيه جسدا ثم اناب'),
(4005, 38, 35, 'قَالَ رَبِّ اغْفِرْ ل۪ي وَهَبْ ل۪ي مُلْكاً لَا يَنْبَغ۪ي لِاَحَدٍ مِنْ بَعْد۪يۚ اِنَّكَ اَنْتَ الْوَهَّابُ', 'Kale rabbigfir li veheb li mulken la yenbagi li ehadin min ba\'di, inneke entel vehhab.', '\"Ey Rabb\'im! Beni bağışla. Bana,  benden sonra hiç kimsenin sahip olamayacağı bir mülk[1] bağışla. Kuşkusuz ki Sen,  Bol Bol Bağışlayıcı\'sın.\" dedi.', 'قال رب اغفر لي وهب لي ملكا لا ينبغي لاحد من بعدي انك انت الوهاب'),
(4006, 38, 36, 'فَسَخَّرْنَا لَهُ الرّ۪يحَ تَجْر۪ي بِاَمْرِه۪ رُخَٓاءً حَيْثُ اَصَابَۙ', 'Fe sehharna lehur riha tecri bi emrihi ruhaen haysu esab.', 'Bunun üzerine rüzgarı onun emrine verdik. Onun emri ile dilediği yere yumuşak bir esinti ile akıp gidiyordu.', 'فسخرنا له الريح تجري بامره رخا حيث اصاب'),
(4007, 38, 37, 'وَالشَّيَاط۪ينَ كُلَّ بَنَّٓاءٍ وَغَوَّاصٍۙ', 'Veş şeyatine kulle bennain ve gavvasın.', 'Ve şeytanları.[1] Her türlü yapı ustasını ve dalgıçları[2]', 'والشيطين كل بنا وغواص'),
(4008, 38, 38, 'وَاٰخَر۪ينَ مُقَرَّن۪ينَ فِي الْاَصْفَادِ', 'Ve aharine mukarrenine fil asfad.', 'Ve zincirlerle bağlanmış olan[1] diğerlerini de.', 'واخرين مقرنين في الاصفاد'),
(4009, 38, 39, 'هٰذَا عَطَٓاؤُ۬نَا فَامْنُنْ اَوْ اَمْسِكْ بِغَيْرِ حِسَابٍ', 'Haza atauna femnun ev emsik bi gayri hisab.', 'Bu Bizim verdiklerimizdir. Artık hesabı sana kalmış,  dilediğine ver veya verme.', 'هذا عطاونا فامنن او امسك بغير حساب'),
(4010, 38, 40, 'وَاِنَّ لَهُ عِنْدَنَا لَزُلْفٰى وَحُسْنَ مَاٰبٍ۟', 'Ve inne lehu ındena le zulfa ve husne meab.', 'Onun yanımızda iyi bir makamı ve iyi bir geleceği vardır.', 'وان له عندنا لزلفي وحسن ماب'),
(4011, 38, 41, 'وَاذْكُرْ عَبْدَنَٓا اَيُّوبَۢ اِذْ نَادٰى رَبَّهُٓ اَنّ۪ي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍۜ', 'Vezkur abdena eyyub, iz nada rabbehu enni messeniyeş şeytanu bi nusbin ve azab.', 'Kulumuz Eyyub\'u da hatırla. Bir zamanlar Rabb\'ine seslenmişti: \"Şeytan bana dert ve azap dokundurdu.\"[1]', 'واذكر عبدنا ايوب اذ نادي ربه اني مسني الشيطن بنصب وعذاب'),
(4012, 38, 42, 'اُرْكُضْ بِرِجْلِكَۚ هٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ', 'Urkud biriclik, haza mugteselun baridun ve şerab.', '\"Ey Eyyub! Ayağın ile topukla![1] İşte bu hem yıkanılacak hem de içilecek soğuk su.\"', 'اركض برجلك هذا مغتسل بارد وشراب'),
(4013, 38, 43, 'وَوَهَبْنَا لَهُٓ   اَهْلَهُ وَمِثْلَهُمْ مَعَهُمْ رَحْمَةً مِنَّا وَذِكْرٰى لِاُو۬لِي الْاَلْبَابِ', 'Ve vehebna lehu ehlehu ve mislehum meahum rahmeten minna ve zikra li ulil elbab.', 'Katımızdan bir rahmet ve akıl sahipleri için bir ibret olarak,  ona yanında yer alanları ve onlarla birlikte bir o kadarını daha bahşettik.', 'ووهبنا له اهله ومثلهم معهم رحمة منا وذكري لاولي الالبب'),
(4014, 38, 44, 'وَخُذْ بِيَدِكَ ضِغْثاً فَاضْرِبْ بِه۪ وَلَا تَحْنَثْۜ اِنَّا وَجَدْنَاهُ صَابِراًۜ نِعْمَ الْعَبْدُۜ اِنَّهُٓ  اَوَّابٌ', 'Ve huz bi yedike dıgsen fadrıb bihi ve la tahnes, inna vecednahu sabira, ni\'mel abd, innehu evvab.', 'Ve eline bir deste al,  onunla yola koyul[1] ve hanis[2] olma. Biz,  onu sabredici bulduk. O ne iyi kuldu! O,  her zaman Allah\'a yöneldi.[3]', 'وخذ بيدك ضغثا فاضرب به ولا تحنث انا وجدنه صابرا نعم العبد انه اواب'),
(4015, 38, 45, 'وَاذْكُرْ عِبَادَنَٓا اِبْرٰه۪يمَ وَاِسْحٰقَ وَيَعْقُوبَ اُو۬لِي الْاَيْد۪ي وَالْاَبْصَارِ', 'Vezkur ıbadena ibrahime ve ishaka ve ya\'kube ulil eydi vel ebsar.', 'Güç ve basiret sahibi olan kullarımız İbrahim\'i,  İshak\'ı ve Yakub\'u da an.', 'واذكر عبادنا ابرهيم واسحق ويعقوب اولي الايدي والابصر'),
(4016, 38, 46, 'اِنَّٓا اَخْلَصْنَاهُمْ بِخَالِصَةٍ ذِكْرَى الدَّارِۚ', 'İnna ahlasnahum bi halisatin zikred dar.', 'Biz,  onları sürekli ahiret yurdu düşüncesiyle arınmış,  samimiyet sahibi kimseler yaptık.', 'انا اخلصنهم بخالصة ذكري الدار'),
(4017, 38, 47, 'وَاِنَّهُمْ عِنْدَنَا لَمِنَ الْمُصْطَفَيْنَ الْاَخْيَارِ', 'Ve innehum ındena le minel mustafeynel ahyar.', 'Onlar,  yanımızda seçkin ve hayırlı kimselerdendir.', 'وانهم عندنا لمن المصطفين الاخيار'),
(4018, 38, 48, 'وَاذْكُرْ اِسْمٰع۪يلَ وَالْيَسَعَ وَذَا الْـكِفْلِۜ وَكُلٌّ مِنَ الْاَخْيَارِۜ', 'Vezkur ismaile velyesea ve zel kifl, ve kullun minel ahyar.', 'İsmail\'i,  Elyesa\'yı ve Zulkifl\'i de an. Hepsi de hayırlı kimselerdendir.', 'واذكر اسمعيل واليسع وذا الكفل وكل من الاخيار'),
(4019, 38, 49, 'هٰذَا ذِكْرٌۜ وَاِنَّ لِلْمُتَّق۪ينَ لَحُسْنَ مَاٰبٍۙ', 'Haza zikr, ve inne lil muttekine le husne meab.', 'Bu bir öğüttür. Kuşkusuz takva sahipleri için iyi bir gelecek vardır.', 'هذا ذكر وان للمتقين لحسن ماب'),
(4020, 38, 50, 'جَنَّاتِ عَدْنٍ مُفَتَّحَةً لَهُمُ الْاَبْوَابُۚ', 'Cennati adnin mufettehaten le humul ebvab.', 'Adn Cennetlerinin kapıları onlara açıktır.', 'جنت عدن مفتحة لهم الابوب'),
(4021, 38, 51, 'مُتَّكِـ۪ٔينَ ف۪يهَا يَدْعُونَ ف۪يهَا بِفَاكِهَةٍ كَث۪يرَةٍ وَشَرَابٍ', 'Muttekine fiha yed\'une fiha bi fakihetin kesiretin ve şerab.', 'Orada keyiflerince oturmuş olarak onlara pek çok meyve ve içecek sunulur.', 'متكين فيها يدعون فيها بفكهة كثيرة وشراب'),
(4022, 38, 52, 'وَعِنْدَهُمْ قَاصِرَاتُ الطَّرْفِ اَتْرَابٌ', 'Ve ındehum kasıratut tarfi etrab.', 'Ve yanlarında,  bakışlarını koruyan yaşıtlar vardır.[1]', 'وعندهم قصرت الطرف اتراب'),
(4023, 38, 53, 'هٰذَا مَا تُوعَدُونَ لِيَوْمِ الْحِسَابِ', 'Haza ma tuadune li yevmil hisab.', 'İşte bu,  hesap günü için size söz verilenlerdir.', 'هذا ما توعدون ليوم الحساب'),
(4024, 38, 54, 'اِنَّ هٰذَا لَرِزْقُنَا مَا لَهُ مِنْ نَفَادٍۚ', 'İnne haza le rızkuna ma lehu min nefad.', 'Bu,  bitmez tükenmez rızkımızdır.', 'ان هذا لرزقنا ما له من نفاد'),
(4025, 38, 55, 'هٰذَاۜ وَاِنَّ لِلطَّاغ۪ينَ لَشَرَّ مَاٰبٍۙ', 'Haza, ve inne lit tagıyne le şerre meab.', 'İyilerin durumu budur. Azgınlar için ise kötü bir gelecek vardır.', 'هذا وان للطغين لشر ماب'),
(4026, 38, 56, 'جَهَنَّمَۚ يَصْلَوْنَهَاۚ فَبِئْسَ الْمِهَادُ', 'Cehennem, yaslevneha, fe bi\'sel mihad.', 'Varacakları yer Cehennem\'dir. Orası ne kötü bir yataktır.', 'جهنم يصلونها فبيس المهاد'),
(4027, 38, 57, 'هٰذَاۙ فَلْيَذُوقُوهُ حَم۪يمٌ وَغَسَّاقٌۙ', 'Haza fel yezukuhu hamiymun ve gassak.', 'İşte kaynar ve kokuşmuş su; tatsınlar bakalım!', 'هذا فليذوقوه حميم وغساق'),
(4028, 38, 58, 'وَاٰخَرُ مِنْ شَكْلِه۪ٓ  اَزْوَاجٌۜ', 'Ve aharu min şeklihi ezvac.', 'Ve aynı türden çeşit çeşit azaplar.', 'واخر من شكله ازوج'),
(4029, 38, 59, 'هٰذَا فَوْجٌ مُقْتَحِمٌ مَعَكُمْۚ لَا مَرْحَباً بِهِمْۜ  اِنَّهُمْ صَالُوا النَّارِ', 'Haza fevcun muktehımun meakum, la merhaben bihim, innehum salun nar.', 'İşte bunlar da sizinle birlikte azaba katlanacak olan bir gruptur. Onlara rahatlık yoktur. Onlar,  ateşe girecek olanlardır.', 'هذا فوج مقتحم معكم لا مرحبا بهم انهم صالوا النار'),
(4030, 38, 60, 'قَالُوا بَلْ اَنْتُمْ۠  لَا مَرْحَباً بِكُمْۜ  اَنْتُمْ قَدَّمْتُمُوهُ لَنَاۚ فَبِئْسَ الْقَرَارُ', 'Kalu bel entum, la merhaben bikum, entum kaddemtumuhu lena, febi\'sel karar.', 'Diğerleri ise: \"Hayır! Asıl size rahatlık yok. Ona uğramamızın sebebi sizsiniz. O ne kötü bir konaklama yeridir!\" dediler.', 'قالوا بل انتم لا مرحبا بكم انتم قدمتموه لنا فبيس القرار'),
(4031, 38, 61, 'قَالُوا رَبَّنَا مَنْ قَدَّمَ لَنَا هٰذَا فَزِدْهُ عَذَاباً ضِعْفاً فِي النَّارِ', 'Kalu rabbena men kaddeme lena haza fe zidhu azaben dı\'fen fin nar.', '\"Rabb\'imiz! Buna kim sebep olduysa onun ateşteki azabını kat kat arttır!\" dediler.', 'قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار'),
(4032, 38, 62, 'وَقَالُوا مَا لَنَا لَا نَرٰى رِجَالاً كُنَّا نَعُدُّهُمْ مِنَ الْاَشْرَارِۜ', 'Ve kalu ma lena la nera ricalen kunna neudduhum minel eşrar.', '\"Biz,  neden kötülerden olarak gördüğümüz adamları[1] görmüyoruz?\" derler.', 'وقالوا ما لنا لا نري رجالا كنا نعدهم من الاشرار'),
(4033, 38, 63, 'اَتَّخَذْنَاهُمْ سِخْرِياًّ اَمْ زَاغَتْ عَنْهُمُ الْاَبْصَارُ', 'Ettehaznahum sıhriyyen em zagat anhumul ebsar.', 'Hani kendilerini alaya almıştık! Yoksa buradalar da biz mi görmüyoruz?', 'اتخذنهم سخريا ام زاغت عنهم الابصر'),
(4034, 38, 64, 'اِنَّ ذٰلِكَ لَحَقٌّ تَخَاصُمُ اَهْلِ النَّارِ۟', 'İnne zalike le hakkun tehasumu ehlin nar.', 'Ateş halkının birbirleriyle bu çekişmeleri kesinlikle gerçektir.', 'ان ذلك لحق تخاصم اهل النار'),
(4035, 38, 65, 'قُلْ اِنَّـمَٓا اَنَا۬ مُنْذِرٌۗ وَمَا مِنْ اِلٰهٍ اِلَّا اللّٰهُ الْوَاحِدُ الْقَهَّارُۚ', 'Kul innema ene munzirun ve ma min ilahin ilallahul vahıdul kahhar.', 'De ki: \"Ben yalnızca bir uyarıcıyım. Tek ve kahredici olan Allah\'tan başka ilah yoktur.\"', 'قل انما انا منذر وما من اله الا الله الوحد القهار'),
(4036, 38, 66, 'رَبُّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا الْعَز۪يزُ الْغَفَّارُ', 'Rabbus semavati vel ardı ve ma beynehumel azizul gaffar.', 'Göklerin,  yerin ve ikisinin arasında olan şeylerin Rabbi Mutlak Üstün Olan\'dır,  Çok Bağışlayıcı\'dır.', 'رب السموت والارض وما بينهما العزيز الغفر'),
(4037, 38, 67, 'قُلْ هُوَ نَبَؤٌا عَظ۪يمٌۙ', 'Kul huve nebeun azimun.', 'De ki: \"O,  çok büyük bir haberdir.\"', 'قل هو نبوا عظيم'),
(4038, 38, 68, 'اَنْتُمْ عَنْهُ مُعْرِضُونَ', 'Entum anhu mu\'ridun.', '\"Siz,  ondan yüz çeviriyorsunuz.\"', 'انتم عنه معرضون'),
(4039, 38, 69, 'مَا كَانَ لِيَ مِنْ عِلْمٍ بِالْمَلَأِ الْاَعْلٰٓى اِذْ يَخْتَصِمُونَ', 'Ma kane liye min ilmin bil meleil a\'la iz yahtesımun.', 'Onlar tartışırlarken,  benim Mele-i A\'la\'ya[1] dair bir bilgim yoktu.', 'ما كان لي من علم بالملا الاعلي اذ يختصمون'),
(4040, 38, 70, 'اِنْ يُوحٰٓى اِلَيَّ اِلَّٓا اَنَّمَٓا اَنَا۬ نَذ۪يرٌ مُب۪ينٌ', 'İn yuha ileyye illa ennema ene nezirun mubin.', 'Bana,  yalnızca apaçık bir uyarıcı olduğum için vahyediliyor.\"', 'ان يوحي الي الا انما انا نذير مبين'),
(4041, 38, 71, 'اِذْ قَالَ رَبُّكَ لِلْمَلٰٓئِكَةِ اِنّ۪ي خَالِقٌ بَشَراً مِنْ ط۪ينٍ', 'İz kale rabbuke lil melaiketi inni halikun beşeren min tin.', 'Hani Rabb\'in meleklere: \"Ben çamurdan bir beşer yaratacağım.\" demişti.', 'اذ قال ربك للمليكة اني خلق بشرا من طين'),
(4042, 38, 72, 'فَاِذَا سَوَّيْتُهُ وَنَفَخْتُ ف۪يهِ مِنْ رُوح۪ي فَقَعُوا لَهُ سَاجِد۪ينَ', 'Fe iza sevveytuhu ve nefahtu fihi min ruhi fe kau lehu sacidin.', 'Onu biçimlendirip,  ruhumdan üflediğim[1] zaman derhal ona secdeye kapanın![2]', 'فاذا سويته ونفخت فيه من روحي فقعوا له سجدين'),
(4043, 38, 73, 'فَسَجَدَ الْمَلٰٓئِكَةُ  كُلُّهُمْ اَجْمَعُونَۙ', 'Fe secedel melaiketu kulluhum ecmaun.', 'Bunun üzerine meleklerin tamamı,  hep birlikte secde ettiler.[1]', 'فسجد المليكة كلهم اجمعون'),
(4044, 38, 74, 'اِلَّٓا اِبْل۪يسَۜ اِسْتَكْـبَرَ وَكَانَ مِنَ الْكَافِر۪ينَ', 'İlla iblis, istekbere ve kane minel kafirin.', 'Ancak iblis etmedi. O kibirlendi ve zaten o kafirlerdendi.[1]', 'الا ابليس استكبر وكان من الكفرين'),
(4045, 38, 75, 'قَالَ يَٓا اِبْل۪يسُ مَا مَنَعَكَ اَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّۜ اَسْتَكْـبَرْتَ اَمْ كُنْتَ مِنَ الْعَال۪ينَ', 'Kale ya iblisu ma meneake en tescude lima halaktu bi yedeyy, estekberte em kunte minel alin.', '\"Ey iblis! İki elimle[1] yarattığım şeye secde etmekten seni alıkoyan nedir? Büyüklük mü taslıyorsun,  yoksa kendini çok mu üstün görüyorsun?\" dedi.', 'قال يابليس ما منعك ان تسجد لما خلقت بيدي استكبرت ام كنت من العالين'),
(4046, 38, 76, 'قَالَ اَنَا۬ خَيْرٌ مِنْهُۜ خَلَقْتَن۪ي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ ط۪ينٍ', 'Kale ene hayrun minh, halakteni min narin ve halaktehu min tin.', '\"Ben ondan hayırlıyım.[1] Beni ateşten yarattın,  onu çamurdan yarattın.\" dedi.', 'قال انا خير منه خلقتني من نار وخلقته من طين'),
(4047, 38, 77, 'قَالَ فَاخْرُجْ مِنْهَا فَاِنَّكَ رَج۪يمٌۚ', 'Kale fahruc minha fe inneke recim.', '\"Oradan çık! Sen kesinlikle racimsin.[1]\" dedi.', 'قال فاخرج منها فانك رجيم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4048, 38, 78, 'وَاِنَّ عَلَيْكَ لَعْنَت۪ٓي اِلٰى يَوْمِ الدّ۪ينِ', 'Ve inne aleyke la\'neti ila yevmid din.', 'Lanetim[1],  Din Günü\'ne[2] kadar senin üzerindedir.', 'وان عليك لعنتي الي يوم الدين'),
(4049, 38, 79, 'قَالَ رَبِّ فَاَنْظِرْن۪ٓي اِلٰى يَوْمِ يُبْعَثُونَ', 'Kale rabbi fe enzırni ila yevmi yub\'asun.', 'İblis: \"Rabb\'im! O halde yeniden dirilme gününe kadar bana süre ver.\" dedi.', 'قال رب فانظرني الي يوم يبعثون'),
(4050, 38, 80, 'قَالَ فَاِنَّكَ مِنَ الْمُنْظَر۪ينَۙ', 'Kale fe inneke minel munzarin.', 'Allah,  \"Peki süre verilenlerdensin.\" dedi.', 'قال فانك من المنظرين'),
(4051, 38, 81, 'اِلٰى يَوْمِ الْوَقْتِ الْمَعْلُومِ', 'İla yevmil vaktil ma\'lum.', 'Zamanı bilinen güne[1] kadar.', 'الي يوم الوقت المعلوم'),
(4052, 38, 82, 'قَالَ فَبِعِزَّتِكَ لَاُغْوِيَنَّهُمْ اَجْمَع۪ينَۙ', 'Kale fe bi izzetike le ugviyennehum ecmain.', 'İblis: \"Öyleyse,  izzetine[1] ant olsun ki onların hepsini azdıracağım.\" dedi.', 'قال فبعزتك لاغوينهم اجمعين'),
(4053, 38, 83, 'اِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَص۪ينَ', 'İlla ibadeke minhumul muhlasin.', '\"Ancak içlerinden muhles[1] kulların hariç.\"', 'الا عبادك منهم المخلصين'),
(4054, 38, 84, 'قَالَ فَالْحَقُّۘ وَالْحَقَّ اَقُولُۚ', 'Kale fel hakku vel hakka ekul.', '\"Gerçek budur. Ben,  gerçeği söylerim.\" dedi.', 'قال فالحق والحق اقول'),
(4055, 38, 85, 'لَاَمْلَـَٔنَّ جَهَنَّمَ مِنْكَ وَمِمَّنْ تَبِعَكَ مِنْهُمْ اَجْمَع۪ينَ', 'Le emleenne cehenneme minke ve mimmen tebiake minhum ecmain.', 'Allah: \"Ant olsun ki Cehennem\'i senden ve sana uyanlardan dolduracağım.\" dedi.', 'لاملان جهنم منك وممن تبعك منهم اجمعين'),
(4056, 38, 86, 'قُلْ مَٓا اَسْـَٔلُـكُمْ عَلَيْهِ مِنْ اَجْرٍ وَمَٓا اَنَا۬ مِنَ الْمُتَكَلِّف۪ينَ', 'Kul ma es\'elukum aleyhi min ecrin ve ma ene minel mutekellifin.', 'De ki: \"Sizden yaptığım bu işe karşı bir ücret istemiyorum. Ve ben kendiliğimden bir sorumluluk getirenlerden değilim.\"', 'قل ما اسلكم عليه من اجر وما انا من المتكلفين'),
(4057, 38, 87, 'اِنْ هُوَ اِلَّا ذِكْرٌ لِلْعَالَم۪ينَ', 'İn huve illa zikrun lil alemin.', 'O,  ancak bütün insanlık için bir zikirdir.[1]', 'ان هو الا ذكر للعلمين'),
(4058, 38, 88, 'وَلَتَعْلَمُنَّ نَبَاَهُ بَعْدَ ح۪ينٍ', 'Ve le talemunne nebeehu ba\'de hin.', 'Onun haberini bir zaman sonra kesinlikle bileceksiniz.[1]', 'ولتعلمن نباه بعد حين'),
(4059, 39, 1, 'تَنْز۪يلُ الْكِتَابِ مِنَ اللّٰهِ الْعَز۪يزِ الْحَك۪يمِ', 'Tenzilul kitabi minallahil azizil hakim.', 'Kitap\'ın indirilmesi,  Mutlak Üstün Olan,  En İyi Hüküm Veren Allah tarafındandır.', 'تنزيل الكتب من الله العزيز الحكيم'),
(4060, 39, 2, 'اِنَّٓا اَنْزَلْـنَٓا اِلَيْكَ الْكِتَابَ بِالْحَقِّ فَاعْبُدِ اللّٰهَ مُخْلِصاً لَهُ الدّ۪ينَۜ', 'İnna enzelna ileykel kitabe bil hakkı fa\'budillahe muhlisan lehud din.', 'Biz,  bu Kitap\'ı sana hakk ile indirdik. Öyleyse dini yalnızca O\'na halis kılarak[1] Allah\'a kulluk[2] et.', 'انا انزلنا اليك الكتب بالحق فاعبد الله مخلصا له الدين'),
(4061, 39, 3, 'اَلَا لِلّٰهِ الدّ۪ينُ الْخَالِصُۜ وَالَّذ۪ينَ اتَّخَذُوا مِنْ دُونِه۪ٓ اَوْلِيَٓاءَۢ مَا نَعْبُدُهُمْ اِلَّا لِيُقَرِّبُونَٓا اِلَى اللّٰهِ زُلْفٰىۜ اِنَّ اللّٰهَ يَحْكُمُ بَيْنَهُمْ ف۪ي مَا هُمْ ف۪يهِ يَخْتَلِفُونَۜ اِنَّ اللّٰهَ لَا يَهْد۪ي مَنْ هُوَ كَاذِبٌ كَفَّارٌ', 'E la lillahid dinul halis, vellezinettehazu min dunihi evliya, ma na\'buduhum illa li yukarribuna ilallahi zulfa, innallahe yahkumu beynehum fi ma hum fihi yahtelifun, innallahe la yehdi men huve kazibun keffar.', 'Dikkat edin! Halis[1] din yalnızca Allah\'a aittir. O\'nun yanı sıra veliler[2] edinenler: \"Onlara,  bizi Allah\'a daha yakın bir seviyeye yaklaştırsınlar diye kulluk[3] ediyoruz.\" diyorlar. Allah,  hakkında tartıştıkları şey için hükmünü verecektir. Allah,  yalancı ve azılı nankörleri doğru yola iletmez.', 'الا لله الدين الخالص والذين اتخذوا من دونه اوليا ما نعبدهم الا ليقربونا الي الله زلفي ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كذب كفار'),
(4062, 39, 4, 'لَوْ اَرَادَ اللّٰهُ اَنْ يَتَّخِذَ وَلَداً لَاصْطَفٰى مِمَّا يَخْلُقُ مَا يَشَٓاءُۙ سُبْحَانَهُۜ هُوَ اللّٰهُ الْوَاحِدُ الْقَهَّارُ', 'Lev eradallahu en yettehıze veleden lastafa mimma yahluku ma yeşau subhaneh, huvallahul vahıdul kahhar.', 'Eğer Allah bir çocuk edinmek isteseydi,  yaratacağından dilediğini seçerdi. O,  bundan münezzehtir.[1] O Allah,  Eşsiz ve Benzersiz Tek Olan\'dır,  Varlığın Üzerinde Mutlak Egemen\'dir.', 'لو اراد الله ان يتخذ ولدا لاصطفي مما يخلق ما يشا سبحنه هو الله الوحد القهار'),
(4063, 39, 5, 'خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّۚ يُكَوِّرُ الَّيْلَ عَلَى النَّهَارِ وَيُكَوِّرُ النَّهَارَ عَلَى الَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَۜ  كُلٌّ يَجْر۪ي لِاَجَلٍ مُسَمًّىۜ اَلَا هُوَ الْعَز۪يزُ الْغَفَّارُ', 'Halakas semavati vel arda bil hakk, yukevvirul leyle alen nehari ve yukevvirun nehare alel leyli ve sehhareş şemse vel kamer, kullun yecri li ecelin musemma, e la huvel azizul gaffar.', 'Gökleri ve yeri hakk ile yarattı. Geceyi gündüze,  gündüzü geceye çevirir. Güneş\'i ve Ay\'ı buyruk altına almıştır. Hepsi belirlenmiş bir zamana akıp gitmektedir. İyi bilin ki O,  Mutlak Üstün Olan\'dır,  Çok Bağışlayıcı\'dır.', 'خلق السموت والارض بالحق يكور اليل علي النهار ويكور النهار علي اليل وسخر الشمس والقمر كل يجري لاجل مسمي الا هو العزيز الغفر'),
(4064, 39, 6, 'خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَاَنْزَلَ لَكُمْ مِنَ الْاَنْعَامِ ثَمَانِيَةَ اَزْوَاجٍۜ يَخْلُقُكُمْ ف۪ي بُطُونِ اُمَّهَاتِكُمْ خَلْقاً مِنْ بَعْدِ خَلْقٍ ف۪ي ظُلُمَاتٍ ثَلٰثٍۜ ذٰلِكُمُ اللّٰهُ رَبُّكُمْ لَهُ الْمُلْكُۜ لَٓا اِلٰهَ اِلَّا هُوَۚ فَاَنّٰى تُصْرَفُونَ', 'Halakakum min nefsin vahıdetin summe ceale minha zevceha ve enzele lekum minel en\'ami semaniyete ezvac, yahlukukum fi butuni ummehatikum halkan min ba\'di halkın fi zulumatin selas, zalikumullahu rabbukum lehul mulk, la ilahe illa huve, fe enna tusrafun.', 'Sizi tek bir nefisten[1] yarattı. Sonra ondan[2] eşini meydana getirdi. Sizin için hayvanlardan sekiz eş bağışladı. Sizi annelerinizin karnında üç karanlık içinde,  yaratılıştan sonra bir yaratılış ile yaratıyor. İşte bu sizin Rabb\'iniz Allah\'tır. Mülk,  O\'nundur. O\'ndan başka ilah yoktur. Öyleyse nasıl oluyor da başka şeylere yöneliyorsunuz?', 'خلقكم من نفس وحدة ثم جعل منها زوجها وانزل لكم من الانعم ثمنية ازوج يخلقكم في بطون امهتكم خلقا من بعد خلق في ظلمت ثلث ذلكم الله ربكم له الملك لا اله الا هو فاني تصرفون'),
(4065, 39, 7, 'اِنْ تَكْفُرُوا فَاِنَّ اللّٰهَ غَنِيٌّ عَنْكُمْ وَلَا يَرْضٰى لِعِبَادِهِ الْكُفْرَۚ وَاِنْ تَشْكُرُوا يَرْضَهُ۬ لَكُمْۜ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ اُخْرٰىۜ ثُمَّ اِلٰى رَبِّكُمْ مَرْجِعُكُمْ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَۜ اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'İn tekfuru fe innallahe ganiyyun ankum, ve la yerda li ıbadihil kufr, ve in teşkuru yerdahu lekum, ve la teziru vaziretun vizra uhra, summe ila rabbikum merciukum fe yunebbiukum bima kuntum ta\'melun, innehu alimun bi zatis sudur.', 'Eğer Küfrederseniz[1]; bilin ki Allah\'ın size hiçbir ihtiyacı yoktur. O,  kullarının Küfründen[2] hoşnut olmaz. Eğer şükrederseniz[2] ondan hoşnut olur. Hiç kimse bir başkasının yükünü yüklenmez.[4] Sonunda dönüşünüz Rabb\'inizedir. Böylece yapmış olduklarınızı size haber verecektir. Kuşkusuz O,  sinelerde olanı en iyi bilendir.', 'ان تكفروا فان الله غني عنكم ولا يرضي لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازرة وزر اخري ثم الي ربكم مرجعكم فينبيكم بما كنتم تعملون انه عليم بذات الصدور'),
(4066, 39, 8, 'وَاِذَا مَسَّ الْاِنْسَانَ ضُرٌّ دَعَا رَبَّهُ مُن۪يباً اِلَيْهِ ثُمَّ اِذَا خَوَّلَهُ نِعْمَةً مِنْهُ نَسِيَ مَا كَانَ يَدْعُٓوا اِلَيْهِ مِنْ قَبْلُ وَجَعَلَ لِلّٰهِ اَنْدَاداً لِيُضِلَّ عَنْ سَب۪يلِه۪ۜ قُلْ تَمَتَّعْ بِكُفْرِكَ قَل۪يلاًۗ اِنَّكَ مِنْ اَصْحَابِ النَّارِ', 'Ve iza messel insane durrun dea rabbehu muniben ileyhi summe iza havvelehu ni\'meten minhu nesiye ma kane yed\'u ileyhi min kablu ve ceale lillahi endaden li yudılle an sebilih, kul temetta\' bi kufrike kalilen inneke min ashabin nar.', 'İnsana bir sıkıntı dokunduğu zaman,  Rabbine yönelerek bütün benliğiyle O\'na dua eder. Sonra kendisine bir nimet lütfettiği zaman,  daha önce O\'na yöneldiği halini unutur. O\'nun yolundan saptırmak için Allah\'a ortaklar koşar. De ki: \"Nankörlüğünle biraz daha yararlan. Kuşkusuz ki sen ateşin halkındansın.\"', 'واذا مس الانسن ضر دعا ربه منيبا اليه ثم اذا خوله نعمة منه نسي ما كان يدعوا اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحب النار'),
(4067, 39, 9, 'اَمَّنْ هُوَ قَانِتٌ اٰنَٓاءَ الَّيْلِ سَاجِداً وَقَٓائِماً يَحْذَرُ الْاٰخِرَةَ وَيَرْجُوا رَحْمَةَ رَبِّه۪ۜ قُلْ هَلْ يَسْتَوِي الَّذ۪ينَ يَعْلَمُونَ وَالَّذ۪ينَ لَا يَعْلَمُونَۜ اِنَّمَا يَتَذَكَّرُ اُو۬لُوا الْاَلْبَابِ۟', 'Em men huve kanitun anael leyli saciden ve kaimen yahzerul ahırete ve yercu rahmete rabbih, kul hel yestevillezine ya\'lemune vellezine la ya\'lemun, innema yetezekkeru ulul elbab.', 'Gece saatlerinde secde ederek,  kıyam durarak itaatkar olan,  ahireti hesaba katan ve Rabb\'inin rahmetini uman kimse,  bu nankörlerle bir tutulur mu hiç? De ki: \"Hiç bilenlerle bilmeyenler bir olur mu?[1]\" Kesinlikle yalnızca temiz akıl sahipleri öğüt alırlar.', 'امن هو قنت انا اليل ساجدا وقايما يحذر الاخرة ويرجوا رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولوا الالبب'),
(4068, 39, 10, 'قُلْ يَا عِبَادِ الَّذ۪ينَ اٰمَنُوا اتَّقُوا رَبَّكُمْۜ لِلَّذ۪ينَ اَحْسَنُوا ف۪ي هٰذِهِ الدُّنْيَا حَسَنَةٌۜ وَاَرْضُ اللّٰهِ وَاسِعَةٌۜ اِنَّمَا يُوَفَّى الصَّابِرُونَ اَجْرَهُمْ بِغَيْرِ حِسَابٍ', 'Kul ya ıbadıllezine amenutteku rabbekum, lillezine ahsenu fi hazihid dunya haseneh, ve ardullahi vasiah innema yuveffas sabirune ecrehum bi gayri hisab.', 'De ki: \"Ey inanan kullar! Rabb\'inize karşı takvalı olun. Bu dünyada,  iyi olanlar için iyilik vardır. Allah\'ın arzı geniştir. Ancak sabredenlere[1] ödülleri hesapsız ödenir.', 'قل يعباد الذين امنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنة وارض الله وسعة انما يوفي الصبرون اجرهم بغير حساب'),
(4069, 39, 11, 'قُلْ اِنّ۪ٓي اُمِرْتُ اَنْ اَعْبُدَ اللّٰهَ مُخْلِصاً لَهُ الدّ۪ينَۙ', 'Kul inni umirtu en a\'budallahe muhlisan lehud din.', 'De ki: \"Ben,  dini yalnızca Kendisine özgü kılarak[1],  Allah\'a kulluk etmekle emrolundum.\"', 'قل اني امرت ان اعبد الله مخلصا له الدين'),
(4070, 39, 12, 'وَاُمِرْتُ لِاَنْ اَكُونَ اَوَّلَ الْمُسْلِم۪ينَ', 'Ve umirtu li en ekune evvelel muslimin.', '\"Ve bana teslim olanların ilki[1] olmam buyruldu.\"', 'وامرت لان اكون اول المسلمين'),
(4071, 39, 13, 'قُلْ اِنّ۪ٓي اَخَافُ اِنْ عَصَيْتُ رَبّ۪ي عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Kul inni ehafu in asaytu rabbi azabe yevmin azim.', 'De ki: \"Eğer Rabb\'ime karşı gelirsem,  büyük günün azabından korkarım.\"', 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم'),
(4072, 39, 14, 'قُلِ اللّٰهَ اَعْبُدُ مُخْلِصاً لَهُ د۪ين۪يۙ', 'Kulillahe a\'budu muhlisan lehu dini.', 'De ki: \"Ben,  dinimi Allah\'a özgü kılarak[1] O\'na kulluk ederim.\"', 'قل الله اعبد مخلصا له ديني'),
(4073, 39, 15, 'فَاعْبُدُوا مَا شِئْتُمْ مِنْ دُونِه۪ۜ  قُلْ اِنَّ الْخَاسِر۪ينَ الَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ وَاَهْل۪يهِمْ يَوْمَ الْقِيٰمَةِۜ  اَلَا ذٰلِكَ هُوَ الْخُسْرَانُ الْمُب۪ينُ', 'Fa\'budu ma şi\'tum min dunih, kul innel hasirine ellezine hasiru enfusehum ve ehlihim yevmel kıyameh e la zalike huvel husranul mubin.', '\"Siz de O\'nun yanı sıra istediğinize kulluk[1] edin.\" De ki: \"Asıl kaybedenler,  Kıyamet Günü\'nde kendilerini ve yakınlarını kayba uğratacak olanlardır.\" Dikkat edin! İşte apaçık kayıp budur.', 'فاعبدوا ما شيتم من دونه قل ان الخسرين الذين خسروا انفسهم واهليهم يوم القيمة الا ذلك هو الخسران المبين'),
(4074, 39, 16, 'لَهُمْ مِنْ فَوْقِهِمْ ظُلَلٌ مِنَ النَّارِ وَمِنْ تَحْتِهِمْ ظُلَلٌۜ ذٰلِكَ يُخَوِّفُ اللّٰهُ بِه۪ عِبَادَهُۜ يَا عِبَادِ فَاتَّقُونِ', 'Lehum min fevkıhim zulelun minen nari ve min tahtihim zulel, zalike yuhavvifullahu bihi ıbadeh, ya ıbadi fettekun.', 'Onların üstlerinde de altlarında da ateşten katmanlar vardır. İşte Allah\'ın,  kullarını uyarıp sakınmalarını istediği şey budur. Ey kullarım,  Bana karşı takvalı[1] olun!', 'لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يعباد فاتقون'),
(4075, 39, 17, 'وَالَّذ۪ينَ اجْتَنَبُوا الطَّاغُوتَ اَنْ يَعْبُدُوهَا وَاَنَابُٓوا اِلَى اللّٰهِ لَهُمُ الْبُشْرٰىۚ فَبَشِّرْ عِبَادِۙ', 'Vellezinectenebut tagute en ya\'buduha ve enabu ilallahi lehumul buşra, fe beşşir ıbad.', 'Tağuta[1] kulluk etmekten kaçınan ve Allah\'a yönelenlere müjdeler olsun. O halde bu kullarımı müjdele.', 'والذين اجتنبوا الطغوت ان يعبدوها وانابوا الي الله لهم البشري فبشر عباد'),
(4076, 39, 18, 'اَلَّذ۪ينَ يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ اَحْسَنَهُۜ  اُو۬لٰٓئِكَ الَّذ۪ينَ هَدٰيهُمُ اللّٰهُ وَاُو۬لٰٓئِكَ هُمْ اُو۬لُوا الْاَلْبَابِ', 'Ellezine yestemiunel kavle fe yettebiune ahseneh, ulaikellezine hedahumullahu ve ulaike hum ulul elbab.', 'Sözü dinleyip,  en iyisine uyarlar. İşte onlar,  Allah\'ın doğru yola ilettiği kimselerdir. İşte onlar sağlıklı düşünen akıl sahipleridir.', 'الذين يستمعون القول فيتبعون احسنه اوليك الذين هديهم الله واوليك هم اولوا الالبب'),
(4077, 39, 19, 'اَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِۜ اَفَاَنْتَ تُنْقِذُ مَنْ فِي النَّارِۚ', 'E fe men hakka aleyhi kelimetul azab, e fe ente tunkızu men fin nar.', 'Hakkında azap kararı gerçekleşmiş olana gelince; ateşte olanı sen mi kurtaracaksın?', 'افمن حق عليه كلمة العذاب افانت تنقذ من في النار'),
(4078, 39, 20, 'لٰكِنِ الَّذ۪ينَ اتَّقَوْا رَبَّهُمْ لَهُمْ غُرَفٌ مِنْ فَوْقِهَا غُرَفٌ مَبْنِيَّةٌۙ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ وَعْدَ اللّٰهِۜ لَا يُخْلِفُ اللّٰهُ الْم۪يعَادَ', 'Lakinillezinettekav rabbehum lehum gurefun min fevkıha gurefun mebniyyetun tecri min tahtihel enhar, va\'dallah, la yuhlifullahul miad.', 'Fakat Rabb\'lerine takvalı olanlar için kat kat bina edilmiş,  önlerinde nehirler akan köşkler vardır. Bu Allah\'ın verdiği sözdür. Allah verdiği sözden dönmez.', 'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجري من تحتها الانهر وعد الله لا يخلف الله الميعاد'),
(4079, 39, 21, 'اَلَمْ تَرَ اَنَّ اللّٰهَ اَنْزَلَ مِنَ السَّمَٓاءِ مَٓاءً فَسَلَكَهُ يَنَاب۪يعَ فِي الْاَرْضِ ثُمَّ يُخْرِجُ بِه۪ زَرْعاً مُخْتَلِفاً اَلْوَانُهُ ثُمَّ يَه۪يجُ فَـتَرٰيهُ مُصْفَراًّ ثُمَّ يَجْعَلُهُ حُطَاماًۜ اِنَّ ف۪ي ذٰلِكَ لَذِكْرٰى لِاُو۬لِي الْاَلْبَابِ۟', 'E lem tere ennallahe enzele mines semai maen fe selekehu yenabia fil ardı summe yuhricu bihi zer\'an muhtelifen elvanuhu summe yehicu fe terahu musferran summe yec\'aluhu hutama, inne fi zalike le zikra li ulil elbab.', 'Allah\'ın,  gökten su indirdiğini ve onu su kaynakları şeklinde yeryüzünde akıttığını,  sonra onunla rengarenk ekinler çıkardığını,  daha sonra onların sararıp kuruduklarını; kuru bir çöpe döndüğünü görmedin mi? Kuşkusuz bunda sağlıklı düşünen akıl sahipleri için bir öğüt vardır.', 'الم تر ان الله انزل من السما ما فسلكه ينبيع في الارض ثم يخرج به زرعا مختلفا الونه ثم يهيج فتريه مصفرا ثم يجعله حطما ان في ذلك لذكري لاولي الالبب'),
(4080, 39, 22, 'اَفَمَنْ شَرَحَ اللّٰهُ صَدْرَهُ لِلْاِسْلَامِ فَهُوَ عَلٰى نُورٍ مِنْ رَبِّه۪ۜ فَوَيْلٌ لِلْقَاسِيَةِ قُلُوبُهُمْ مِنْ ذِكْرِ اللّٰهِۜ اُو۬لٰٓئِكَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'E fe men şerehallahu sadrehu lil islami fe huve ala nurin min rabbih, fe veylun lil kasiyeti kulubuhum min zikrillah, ulaike fi dalalin mubin.', 'Allah\'ın,  göğsünü İslam\'a açtığı kimse,  Rabb\'inden bir ışık üzerinde olmaz mı? Öyleyse Allah\'ın öğütlerine karşı kalpleri katılaşmış olanlara yazıklar olsun! İşte onlar,  apaçık bir sapkınlık içindedirler.', 'افمن شرح الله صدره للاسلم فهو علي نور من ربه فويل للقسية قلوبهم من ذكر الله اوليك في ضلل مبين'),
(4081, 39, 23, 'اَللّٰهُ نَزَّلَ اَحْسَنَ الْحَد۪يثِ كِتَاباً مُتَشَابِهاً مَثَانِيَۗ  تَقْشَعِرُّ مِنْهُ جُلُودُ الَّذ۪ينَ يَخْشَوْنَ رَبَّهُمْۚ ثُمَّ تَل۪ينُ جُلُودُهُمْ وَقُلُوبُهُمْ اِلٰى ذِكْرِ اللّٰهِۜ ذٰلِكَ هُدَى اللّٰهِ يَهْد۪ي بِه۪ مَنْ يَشَٓاءُۜ وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ هَادٍ', 'Allahu nezzele ahsenel hadisi kitaben muteşabihen mesaniye takşaırru minhu culudullezine yahşevne rabbehum, summe telinu culuduhum ve kulubuhum ila zikrillah, zalike hudallahi yehdi bihi men yeşau, ve men yudlilillahu fe ma lehu min had.', 'Allah,  hadisin[1] en iyisini; muteşabih[2],  ikişerli[3] bir Kitap halinde indirdi. Ondan,  Rabb\'lerine karşı içtenlikli saygısı olanların tüyleri ürperir. Ardından da benlikleri ve kalpleri Allah\'ın öğüdü ile huzura kavuşur. İşte bu,  Allah\'ın doğru yolu gösteren kılavuzudur. Onunla hak edeni[4] doğru yola iletir; Allah,  kimi sapkınlıkta bırakırsa,  artık ona doğru yolu gösteren bulunamaz.', 'الله نزل احسن الحديث كتبا متشبها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم الي ذكر الله ذلك هدي الله يهدي به من يشا ومن يضلل الله فما له من هاد'),
(4082, 39, 24, 'اَفَمَنْ يَتَّق۪ي بِوَجْهِه۪ سُٓوءَ الْعَذَابِ يَوْمَ الْقِيٰمَةِۜ وَق۪يلَ لِلظَّالِم۪ينَ ذُوقُوا مَا كُنْتُمْ تَكْسِبُونَ', 'E fe men yetteki bi vechihi suel azabi yevmel kıyame, ve kıyle liz zalimine zuku ma kuntum teksibun.', 'O halde Kıyamet Günü,  kendisini kötü azaptan kim koruyabilir? Zalimlere: \"Kazandığınızın karşılığını tadın!\" denir.', 'افمن يتقي بوجهه سو العذاب يوم القيمة وقيل للظلمين ذوقوا ما كنتم تكسبون'),
(4083, 39, 25, 'كَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْ فَاَتٰيهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'Kezzebellezine min kablihim fe etahumul azabu min haysu la yeş\'urun.', 'Onlardan öncekiler de yalanlamışlardı da kendilerine hiç beklemedikleri yerden azap geldi.', 'كذب الذين من قبلهم فاتيهم العذاب من حيث لا يشعرون'),
(4084, 39, 26, 'فَاَذَاقَهُمُ اللّٰهُ الْخِزْيَ فِي الْحَيٰوةِ الدُّنْيَاۚ وَلَعَذَابُ الْاٰخِرَةِ اَكْبَرُۢ لَوْ كَانُوا يَعْلَمُونَ', 'Fe ezakahumullahul hızye fil hayatid dunya, ve le azabul ahıreti ekber, lev kanu ya\'lemun.', 'Allah,  onlara dünya hayatında zilleti tattırdı. Ahiret azabı elbette daha büyüktür. Keşke bilmiş olsalardı.', 'فاذاقهم الله الخزي في الحيوة الدنيا ولعذاب الاخرة اكبر لو كانوا يعلمون'),
(4085, 39, 27, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ ف۪ي هٰذَا الْقُرْاٰنِ مِنْ كُلِّ مَثَلٍ لَعَلَّهُمْ يَتَذَكَّرُونَۚ', 'Ve lekad darebna lin nasi fi hazel kur\'ani min kulli meselin leallehum yetezekkerun.', 'Ant olsun ki Kur\'an\'da insanlar için her konudan örnekler verdik. Umulur ki böylece öğüt alırlar.', 'ولقد ضربنا للناس في هذا القران من كل مثل لعلهم يتذكرون'),
(4086, 39, 28, 'قُرْاٰناً عَرَبِياًّ غَيْرَ ذ۪ي عِوَجٍ لَعَلَّهُمْ يَتَّقُونَ', 'Kur\'anen arabiyyen gayre zi ivecin leallehum yettekun.', 'Kusursuz,  Arapça bir Kur\'an\'dır. Umulur ki takva sahibi olurlar.', 'قرانا عربيا غير ذي عوج لعلهم يتقون'),
(4087, 39, 29, 'ضَرَبَ اللّٰهُ مَثَلاً رَجُلاً ف۪يهِ شُرَكَٓاءُ مُتَشَاكِسُونَ وَرَجُلاً سَلَماً لِرَجُلٍۜ هَلْ يَسْتَوِيَانِ مَثَلاًۜ اَلْحَمْدُ لِلّٰهِۚ بَلْ اَكْثَرُهُمْ لَا يَعْلَمُونَ', 'Daraballahu meselen raculen fihi şurekau muteşakisune ve raculen selemen li racul, hel yesteviyani mesel, el hamdulillah, bel ekseruhum la ya\'lemun.', 'Allah,  aralarında anlaşamayan birkaç ortağa bağlı bir kimse ile tek bir kişiye bağlı bir kimseyi örnek verdi: Bu iki kimsenin durumu hiçbir olur mu? Övgü yalnızca Allah\'a özgüdür. Ama çokları bilmiyorlar.', 'ضرب الله مثلا رجلا فيه شركا متشكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل اكثرهم لا يعلمون'),
(4088, 39, 30, 'اِنَّكَ مَيِّتٌ وَاِنَّهُمْ مَيِّتُونَۘ', 'İnneke meyyitun ve innehum meyyitun.', 'Kuşkusuz sen ölümlüsün,  kuşkusuz onlar da ölümlüdürler.', 'انك ميت وانهم ميتون'),
(4089, 39, 31, 'ثُمَّ اِنَّكُمْ يَوْمَ الْقِيٰمَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ۟', 'Summe innekum yevmel kıyameti ınde rabbikum tahtasımun.', 'Sonra Kıyamet Günü hepiniz Rabb\'inizin huzurunda davalaşacaksınız.', 'ثم انكم يوم القيمة عند ربكم تختصمون'),
(4090, 39, 32, 'فَمَنْ اَظْلَمُ مِمَّنْ كَذَبَ عَلَى اللّٰهِ وَكَذَّبَ بِالصِّدْقِ اِذْ جَٓاءَهُۜ اَلَيْسَ ف۪ي جَهَنَّمَ مَثْوًى لِلْكَافِر۪ينَ', 'Fe men azlemu mimmen kezzebe alallahi ve kezzebe bis sıdkı iz caeh, e leyse fi cehenneme mesven lil kafirin.', 'Öyleyse,  Allah adına yalan uyduran ve kendisine gelen doğruyu yalanlayandan daha zalim kim olabilir? Kafirlerin[1] yeri Cehennem\'de değil mi?', 'فمن اظلم ممن كذب علي الله وكذب بالصدق اذ جاه اليس في جهنم مثوي للكفرين'),
(4091, 39, 33, 'وَالَّذ۪ي جَٓاءَ بِالصِّدْقِ وَصَدَّقَ بِه۪ٓ اُو۬لٰٓئِكَ هُمُ الْمُتَّقُونَ', 'Vellezi cae bis sıdkı ve saddeka bihi ulaike humul muttekun.', 'Doğruyu getirenler ve onu doğrulayanlar,  işte onlar takva sahibidirler.', 'والذي جا بالصدق وصدق به اوليك هم المتقون'),
(4092, 39, 34, 'لَهُمْ مَا يَشَٓاؤُ۫نَ عِنْدَ رَبِّهِمْۜ ذٰلِكَ جَزٰٓؤُا الْمُحْسِن۪ينَۚ', 'Lehum ma yeşaune inde rabbihim, zalike cezaul muhsinin.', 'Onlar için Rabbleri yanında diledikleri her şey vardır. İşte budur muhsin[1] olanların karşılığı.', 'لهم ما يشاون عند ربهم ذلك جزا المحسنين'),
(4093, 39, 35, 'لِيُكَفِّرَ اللّٰهُ عَنْهُمْ اَسْوَاَ الَّذ۪ي عَمِلُوا وَيَجْزِيَهُمْ اَجْرَهُمْ بِاَحْسَنِ الَّذ۪ي كَانُوا يَعْمَلُونَ', 'Li yukeffirallahu anhum esveellezi amilu ve yecziyehum ecrehum bi ahsenillezi kanu ya\'melun.', 'Allah,  onların[1] yaptıklarının en kötülerine kafir[2] olacak; yaptıklarının karşılığında,  en iyisiyle karşılık verecek.', 'ليكفر الله عنهم اسوا الذي عملوا ويجزيهم اجرهم باحسن الذي كانوا يعملون'),
(4094, 39, 36, 'اَلَيْسَ اللّٰهُ بِكَافٍ عَبْدَهُۜ وَيُخَوِّفُونَكَ بِالَّذ۪ينَ مِنْ دُونِه۪ۜ وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ هَادٍۚ', 'E leysallahu bi kafin abdeh, ve yuhavvifuneke billezine min dunih, ve men yudlilillahu fe ma lehu min had.', 'Allah,  kuluna yeterli değil mi? Onlar seni O\'ndan başkası ile korkutmaya çalışıyorlar. Allah,  kimi sapkınlıkta bırakırsa,  onu doğruya iletecek yoktur.[1]', 'اليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد'),
(4095, 39, 37, 'وَمَنْ يَهْدِ اللّٰهُ فَمَا لَهُ مِنْ مُضِلٍّۜ اَلَيْسَ اللّٰهُ بِعَز۪يزٍ ذِي انْتِقَامٍ', 'Ve men yehdillahu fe ma lehu min mudıll, e leysallahu bi azizin zintikam.', 'Allah,  kimi doğru yola iletirse,  onu saptırabilecek yoktur. Allah,  Mutlak Üstün Olan; intikam sahibi[1] olan değil midir?', 'ومن يهد الله فما له من مضل اليس الله بعزيز ذي انتقام'),
(4096, 39, 38, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ لَيَقُولُنَّ اللّٰهُۜ قُلْ اَفَرَاَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللّٰهِ اِنْ اَرَادَنِيَ اللّٰهُ بِضُرٍّ هَلْ هُنَّ كَاشِفَاتُ ضُرِّه۪ٓ اَوْ اَرَادَن۪ي بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَاتُ رَحْمَتِه۪ۜ قُلْ حَسْبِيَ اللّٰهُۜ عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ', 'Ve le in seeltehum men halakas semavati vel arda le yekulunnallah, kul e fe raeytum ma ted\'une min dunillahi in eradeniyallahu bi durrin hel hunne kaşifatu durrihi ev eradeni bi rahmetin hel hunne mumsikatu rahmetih, kul hasbiyallah, aleyhi yetevekkelul mutevekkılun.', 'Onlara: \"Gökleri ve yeri kim yarattı?\" diye sorsan,  \"Elbette Allah.\" Diyecekler. De ki: \"O halde Allah\'ın yanı sıra yöneldiğiniz ilahlar,  eğer Allah bana bir sıkıntı vermek istese,  o sıkıntıya engel olabilirler mi? Veya Allah bana bir rahmet dilese,  buna engel olabilirler mi?\" De ki: \"Allah bana yeter!\" De ki: \"Sığınıp güvenmek isteyenler,  yalnızca O\'na sığınıp güvensinler.\"', 'ولين سالتهم من خلق السموت والارض ليقولن الله قل افريتم ما تدعون من دون الله ان ارادني الله بضر هل هن كشفت ضره او ارادني برحمة هل هن ممسكت رحمته قل حسبي الله عليه يتوكل المتوكلون'),
(4097, 39, 39, 'قُلْ يَا قَوْمِ اعْمَلُوا عَلٰى مَكَانَتِكُمْ اِنّ۪ي عَامِلٌۚ فَسَوْفَ تَعْلَمُونَۙ', 'Kul ya kavmi\'melu ala mekanetikum inni amil, fe sevfe ta\'lemune.', 'De ki: \"Ey halkım! Elinizden geleni yapın! Ben de bana düşeni yapacağım. Yakında anlayacaksınız!\"[1]', 'قل يقوم اعملوا علي مكانتكم اني عمل فسوف تعلمون'),
(4098, 39, 40, 'مَنْ يَأْت۪يهِ عَذَابٌ يُخْز۪يهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُق۪يمٌ', 'Men ye\'tihi azabun yuhzihi ve yahıllu aleyhi azabun mukim.', '\"Alçaltıcı azabın ve kalıcı azabın kime geleceğini.\"', 'من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم'),
(4099, 39, 41, 'اِنَّٓا اَنْزَلْنَا عَلَيْكَ الْكِتَابَ لِلنَّاسِ بِالْحَقِّۚ فَمَنِ اهْتَدٰى فَلِنَفْسِه۪ۚ وَمَنْ ضَلَّ فَاِنَّمَا يَضِلُّ عَلَيْهَاۚ وَمَٓا اَنْتَ عَلَيْهِمْ بِوَك۪يلٍ۟', 'İnna enzelna aleykel kitabe lin nasi bil hakkı, fe men ihteda fe li nefsih, ve men dalle fe innema yadıllu aleyha, ve ma ente aleyhim bi vekil.', 'Biz,  sana bu Kitap\'ı insanlar için \"hakk\" ile indirdik. Artık kim doğru yolu seçerse bu kendi yararınadır. Kim de sapkınlığı seçerse kendi zararına sapmış olur. Sen onların üzerine vekil değilsin.', 'انا انزلنا عليك الكتب للناس بالحق فمن اهتدي فلنفسه ومن ضل فانما يضل عليها وما انت عليهم بوكيل'),
(4100, 39, 42, 'اَللّٰهُ يَتَوَفَّى الْاَنْفُسَ ح۪ينَ مَوْتِهَا وَالَّت۪ي لَمْ تَمُتْ ف۪ي مَنَامِهَاۚ فَيُمْسِكُ الَّت۪ي قَضٰى عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْاُخْرٰٓى اِلٰٓى اَجَلٍ مُسَمًّىۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ', 'Allahu yeteveffel enfuse hine mevtiha velleti lem temut fi menamiha, fe yumsikulleti kada aleyhel mevte ve yursilul uhra ila ecelin musemma, inne fi zalike le ayatin li kavmin yetefekkerun.', 'Allah,  öleceklerin ölümleri anında canlarını alır; ölmeyecek olanların da uykularında. Ölümüne hükmettiğini yanında tutar,  diğerlerini belirlenmiş bir süreye kadar salıverir. Bunda düşünen bir halk için alınacak pek çok ders vardır.', 'الله يتوفي الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضي عليها الموت ويرسل الاخري الي اجل مسمي ان في ذلك لايت لقوم يتفكرون'),
(4101, 39, 43, 'اَمِ اتَّخَذُوا مِنْ دُونِ اللّٰهِ شُفَعَٓاءَۜ  قُلْ اَوَلَوْ كَانُوا لَا يَمْلِكُونَ شَيْـٔاً وَلَا يَعْقِلُونَ', 'Emittehazu min dunillahi şufeae, kul e ve lev kanu la yemlikune şey\'en ve la ya\'kılun.', 'Yoksa Allah\'ın yanı sıra şefaatçiler[1] mi edindiler? De ki: \"Onlar hiçbir şeye sahip olmasalar ve akıl etmeseler de mi?', 'ام اتخذوا من دون الله شفعا قل اولو كانوا لا يملكون شيا ولا يعقلون'),
(4102, 39, 44, 'قُلْ لِلّٰهِ الشَّفَاعَةُ جَم۪يعاًۜ لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ ثُمَّ اِلَيْهِ تُرْجَعُونَ', 'Kul lillahiş şefaatu cemia, lehu mulkus semavati vel ard, summe ileyhi turceun.', 'De ki: \"Şefaat etme tamamıyla Allah\'ın elindedir.[1] Göklerin ve yerin egemenliği yalnızca O\'na aittir. Sonra O\'na döndürüleceksiniz.', 'قل لله الشفعة جميعا له ملك السموت والارض ثم اليه ترجعون'),
(4103, 39, 45, 'وَاِذَا ذُكِرَ اللّٰهُ وَحْدَهُ اشْمَاَزَّتْ قُلُوبُ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِۚ وَاِذَا ذُكِرَ الَّذ۪ينَ مِنْ دُونِه۪ٓ اِذَا هُمْ يَسْتَبْشِرُونَ', 'Ve iza zukirallahu vahdehuşmeezzet kulubullezine la yu\'minune bil ahıreh, ve iza zukirellezine min dunihi iza hum yestebşirun.', 'Allah,  \"tek başına\"[1] anıldığı zaman,  ahirete inanmayanların kalpleri burkulur. O\'nun yanı sıra başkası[2] anıldığı zaman sevinip mutluluk duyarlar.', 'واذا ذكر الله وحده اشمازت قلوب الذين لا يومنون بالاخرة واذا ذكر الذين من دونه اذا هم يستبشرون'),
(4104, 39, 46, 'قُلِ اللّٰهُمَّ فَاطِرَ السَّمٰوَاتِ وَالْاَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ اَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'Kulillahumme fatıras semavati vel ardı alimel gaybi veş şehadeti ente tahkumu beyne ıbadike fi ma kanu fihi yahtelifun.', 'De ki: \"Göklere ve yere işleyiş yasalarını koyan,  gaybı[1] ve görüneni bilen Allah\'ım! Kullarının aralarında çekiştikleri şeyler hakkında hüküm verecek olan Sen\'sin.\"', 'قل اللهم فاطر السموت والارض علم الغيب والشهدة انت تحكم بين عبادك في ما كانوا فيه يختلفون'),
(4105, 39, 47, 'وَلَوْ اَنَّ لِلَّذ۪ينَ ظَلَمُوا مَا فِي الْاَرْضِ جَم۪يعاً وَمِثْلَهُ مَعَهُ لَافْتَدَوْا بِه۪ مِنْ سُٓوءِ الْعَذَابِ يَوْمَ الْقِيٰمَةِۜ وَبَدَا لَهُمْ مِنَ اللّٰهِ مَا لَمْ يَكُونُوا يَحْتَسِبُونَ', 'Ve lev enne lillezine zalemu ma fil ardı cemian ve mislehu meahu leftedev bihi min suil azabi yevmel kıyameh, ve beda lehum minallahi ma lem yekunu yahtesibun.', 'Eğer yeryüzünde olanların tamamı ve bir o kadarı daha,  o zulmedenlerin olsaydı,  Kıyamet Günü azabın kötülüğünden kurtulmak için kesinlikle onu fidye olarak verirlerdi. Hiç hesaba katmadıkları şeyler,  Allah tarafından karşılarına çıkarılacaktır.', 'ولو ان للذين ظلموا ما في الارض جميعا ومثله معه لافتدوا به من سو العذاب يوم القيمة وبدا لهم من الله ما لم يكونوا يحتسبون'),
(4106, 39, 48, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Ve beda lehum seyyiatu ma kesebu ve haka bihim ma kanu bihi yestehziun.', 'Ve kazandıkları kötülükler açığa çıktı. Kendisi ile alay ettikleri şey[1] onları kuşattı.', 'وبدا لهم سيات ما كسبوا وحاق بهم ما كانوا به يستهزون'),
(4107, 39, 49, 'فَاِذَا مَسَّ الْاِنْسَانَ ضُرٌّ دَعَانَاۘ ثُمَّ اِذَا خَوَّلْنَاهُ نِعْمَةً مِنَّاۙ قَالَ اِنَّـمَٓا اُو۫ت۪يتُهُ عَلٰى عِلْمٍۜ بَلْ هِيَ فِتْنَةٌ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Fe iza messel insane durrun deana, summe iza havvelnahu ni\'meten minna kale innema utituhu ala ilm, bel hiye fitnetun ve lakinne ekserehum la ya\'lemun.', 'İnsanın başı derde girdiği zaman Bize yönelir. Sonra ona tarafımızdan bir yardım bahşettiğimizde: \"Bu bana bilgimden/yeteneğimden dolayı verilmiştir.\" der. Hayır! O bir fitnedir[1]. Ne var ki onların çoğu bilmezler.', 'فاذا مس الانسن ضر دعانا ثم اذا خولنه نعمة منا قال انما اوتيته علي علم بل هي فتنة ولكن اكثرهم لا يعلمون'),
(4108, 39, 50, 'قَدْ قَالَهَا الَّذ۪ينَ مِنْ قَبْلِهِمْ فَمَٓا اَغْنٰى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ', 'Kad kalehellezine min kablihim fe ma agna anhum ma kanu yeksibun.', 'Gerçekten,  onlardan öncekiler de böyle söylemişti. Fakat kazanmış oldukları şeyler onlara bir yarar sağlamadı.', 'قد قالها الذين من قبلهم فما اغني عنهم ما كانوا يكسبون'),
(4109, 39, 51, 'فَاَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُواۜ وَالَّذ۪ينَ ظَلَمُوا مِنْ هٰٓؤُ۬لَٓاءِ سَيُص۪يبُهُمْ سَيِّـَٔاتُ مَا كَسَبُواۙ وَمَا هُمْ بِمُعْجِز۪ينَ', 'Fe esabehum seyyiatu ma kesebu, vellezine zalemu min haulai se yusibuhum seyyiatu ma kesebu ve ma hum bi mu\'cizin.', 'Kazandıkları şeylerin kötülükleri kendilerine isabet etti. Bunlardan zulmeden kimselerin de kazandıkları şeylerin kötülükleri onlara yakında isabet edecektir. Ve onlar azabı önleyecek güce sahip değiller.', 'فاصابهم سيات ما كسبوا والذين ظلموا من هولا سيصيبهم سيات ما كسبوا وما هم بمعجزين'),
(4110, 39, 52, 'اَوَلَمْ يَعْلَمُٓوا اَنَّ اللّٰهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يُؤْمِنُونَ۟', 'E ve lem ya\'lemu ennallahe yebsutur rızka li men yeşau ve yakdir, inne fi zalike le ayatin li kavmin yu\'minun.', 'Allah\'ın dilediğine rızkı genişlettiğini ve ölçülendirdiğini bilmediler mi? Bunda iman edecek bir toplum için ayetler[1] vardır.', 'اولم يعلموا ان الله يبسط الرزق لمن يشا ويقدر ان في ذلك لايت لقوم يومنون'),
(4111, 39, 53, 'قُلْ يَا عِبَادِيَ الَّذ۪ينَ اَسْرَفُوا عَلٰٓى اَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللّٰهِۜ اِنَّ اللّٰهَ يَغْفِرُ الذُّنُوبَ جَم۪يعاًۜ اِنَّهُ هُوَ الْغَفُورُ الرَّح۪يمُ', 'Kul ya ıbadiyellezine esrefu ala enfusihim la taknetu min rahmetillah, innallahe yagfiruz zunube cemia, innehu huvel gafurur rahim.', 'De ki: \"Ey kendilerine karşı israf[1] eden kullarım! Allah\'ın rahmetinden ümit kesmeyin. Allah,  suçların hepsini bağışlar. O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'قل يعبادي الذين اسرفوا علي انفسهم لا تقنطوا من رحمة الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيم'),
(4112, 39, 54, 'وَاَن۪يبُٓوا اِلٰى رَبِّكُمْ وَاَسْلِمُوا لَهُ مِنْ قَبْلِ اَنْ يَأْتِيَكُمُ الْعَذَابُ ثُمَّ لَا تُنْصَرُونَ', 'Ve enibu ila rabbikum ve eslimu lehu min kabli en ye\'tiyekumul azabu summe la tunsarun.', 'Rabb\'inize yönelin! Ve size azap gelmeden önce O\'na teslim olun. Sonra yardım olunmazsınız.', 'وانيبوا الي ربكم واسلموا له من قبل ان ياتيكم العذاب ثم لا تنصرون'),
(4113, 39, 55, 'وَاتَّبِعُٓوا اَحْسَنَ مَٓا اُنْزِلَ اِلَيْكُمْ مِنْ رَبِّكُمْ مِنْ قَبْلِ اَنْ يَأْتِيَكُمُ الْعَذَابُ بَغْتَةً وَاَنْتُمْ لَا تَشْعُرُونَۙ', 'Vettebiu ahsene ma unzile ileykum min rabbikum min kabli en ye\'tiyekumul azabu bagteten ve entum la teş\'urun.', 'Hiç beklemediğiniz bir anda,  size ansızın azap gelmeden önce,  Rabb\'inizden size indirilen en iyi olana[1] uyun.', 'واتبعوا احسن ما انزل اليكم من ربكم من قبل ان ياتيكم العذاب بغتة وانتم لا تشعرون'),
(4114, 39, 56, 'اَنْ تَقُولَ نَفْسٌ يَا حَسْرَتٰى عَلٰى مَا فَرَّطْتُ ف۪ي جَنْبِ اللّٰهِ وَاِنْ كُنْتُ لَمِنَ السَّاخِر۪ينَۙ', 'En tekule nefsun ya hasreta ala ma ferrattu fi cenbillahi ve in kuntu le mines sahirin.', 'Sonunda: \"Allah\'a karşı aşırı gittiğimden dolayı yazıklar olsun bana! Doğrusu ben alay edenlerdendim.\" Dememeniz için;', 'ان تقول نفس يحسرتي علي ما فرطت في جنب الله وان كنت لمن السخرين'),
(4115, 39, 57, 'اَوْ تَقُولَ لَوْ اَنَّ اللّٰهَ هَدٰين۪ي لَكُنْتُ مِنَ الْمُتَّق۪ينَۙ', 'Ev tekule lev ennallahe hedani le kuntu minel muttekin.', 'Veya \"Allah bana doğru yolu gösterseydi,  takva sahibi olurdum.\" dememeniz için;', 'او تقول لو ان الله هديني لكنت من المتقين'),
(4116, 39, 58, 'اَوْ تَقُولَ ح۪ينَ تَرَى الْعَذَابَ لَوْ اَنَّ ل۪ي كَرَّةً فَاَكُونَ مِنَ الْمُحْسِن۪ينَ', 'Ev tekule hine terel azabe lev enne li kerreten fe ekune minel muhsinin.', 'Veya azabı gördüğü zaman,  \"Keşke bir kez daha dünyaya dönme imkanım olsaydı,  o zaman muhsinlerden[1] olurdum.\" dememeniz için.', 'او تقول حين تري العذاب لو ان لي كرة فاكون من المحسنين'),
(4117, 39, 59, 'بَلٰى قَدْ جَٓاءَتْكَ اٰيَات۪ي فَكَذَّبْتَ بِهَا وَاسْتَكْبَرْتَ وَكُنْتَ مِنَ الْكَافِر۪ينَ', 'Bela kad caetke ayati fe kezzebte biha vestekberte ve kunte minel kafirin.', 'Hayır[1],  sana ayetlerim gelmişti de onları yalanlamıştın,  büyüklük taslamış ve Kafirlerden olmuştun.', 'بلي قد جاتك ايتي فكذبت بها واستكبرت وكنت من الكفرين'),
(4118, 39, 60, 'وَيَوْمَ الْقِيٰمَةِ تَرَى الَّذ۪ينَ كَذَبُوا عَلَى اللّٰهِ وُجُوهُهُمْ مُسْوَدَّةٌۜ اَلَيْسَ ف۪ي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّر۪ينَ', 'Ve yevmel kıyameti terellezine kezebu alallahi vucuhuhum musveddeh, e leysefi cehenneme mesven lil mutekebbirin.', 'Kıyamet Günü,  Allah hakkında yalan söyleyenlerin yüzlerini kararmış görürsün. Büyüklük taslayanların yeri Cehennem\'de değil mi?', 'ويوم القيمة تري الذين كذبوا علي الله وجوههم مسودة اليس في جهنم مثوي للمتكبرين'),
(4119, 39, 61, 'وَيُنَجِّي اللّٰهُ الَّذ۪ينَ اتَّقَوْا بِمَفَازَتِهِمْۘ لَا يَمَسُّهُمُ السُّٓوءُ وَلَا هُمْ يَحْزَنُونَ', 'Ve yuneccillahullezinettekav bi mefazetihim la yemessuhumus suu ve la hum yahzenun.', 'Allah,  takva[1] sahiplerini,  hak ettikleri kurtuluşa erdirecektir. Onlara kötülük dokunmaz. Onlar üzülmezler de.', 'وينجي الله الذين اتقوا بمفازتهم لا يمسهم السو ولا هم يحزنون'),
(4120, 39, 62, 'اَللّٰهُ خَالِقُ كُلِّ شَيْءٍۘ وَهُوَ عَلٰى كُلِّ شَيْءٍ وَك۪يلٌ', 'Allahu haliku kulli şey\'in ve huve ala kulli şey\'in vekil.', 'Allah,  her şeyin yaratıcısıdır. O,  Her Şeye Vekil\'dir.[1]', 'الله خلق كل شي وهو علي كل شي وكيل'),
(4121, 39, 63, 'لَهُ مَقَال۪يدُ السَّمٰوَاتِ وَالْاَرْضِۜ وَالَّذ۪ينَ كَفَرُوا بِاٰيَاتِ اللّٰهِ اُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ۟', 'Lehu makalidus semavati vel ard, vellezine keferu bi ayatillahi ulaike humul hasirun.', 'Göklerin ve yerin kilidi[1] O\'na aittir. Allah\'ın ayetlerini yalanlayanlar; işte onlar,  hüsrana uğrayanlardır.', 'له مقاليد السموت والارض والذين كفروا بايت الله اوليك هم الخسرون'),
(4122, 39, 64, 'قُلْ اَفَغَيْرَ اللّٰهِ تَأْمُرُٓونّ۪ٓي اَعْبُدُ اَيُّهَا الْجَاهِلُونَ', 'Kul e fe gayrallahi te\'murunni a\'budu eyyuhel cahilun.', 'De ki: \"Ey cahiller! Buna rağmen,  Allah\'tan başkasına kulluk etmemi mi istiyorsunuz?\"', 'قل افغير الله تامروني اعبد ايها الجهلون'),
(4123, 39, 65, 'وَلَقَدْ اُو۫حِيَ اِلَيْكَ وَاِلَى الَّذ۪ينَ مِنْ قَبْلِكَۚ لَئِنْ اَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِر۪ينَ', 'Ve lekad uhıye ileyke ve ilellezine min kablik, le in eşrekte le yahbetanne ameluke ve le tekunenne minel hasirin.', 'Ant olsun ki,  sana ve senden öncekilere şöyle vahyolundu: \"Eğer Allah\'a şirk[1] koşarsan şunu iyi bil ki bütün yaptıkların boşa gider ve hüsrana uğrayanlardan olursun.\"', 'ولقد اوحي اليك والي الذين من قبلك لين اشركت ليحبطن عملك ولتكونن من الخسرين'),
(4124, 39, 66, 'بَلِ اللّٰهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِر۪ينَ', 'Belillahe fa\'bud ve kun mineş şakirin.', '\"O halde yalnız Allah\'a kulluk et ve şükredenlerden ol!\"', 'بل الله فاعبد وكن من الشكرين'),
(4125, 39, 67, 'وَمَا قَدَرُوا اللّٰهَ حَقَّ قَدْرِه۪ۗ وَالْاَرْضُ جَم۪يعاً قَبْضَتُهُ يَوْمَ الْقِيٰمَةِ وَالسَّمٰوَاتُ مَطْوِيَّاتٌ بِيَم۪ينِه۪ۜ سُبْحَانَهُ وَتَعَالٰى عَمَّا يُشْرِكُونَ', 'Ve ma kaderullahe hakka kadrihi vel ardu cemian kabdatuhu yevmel kıyameti ves semavatu matviyyatun bi yeminih, subhanehu ve te\'ala amma yuşrikun.', 'Allah\'ı hakkıyla takdir etmediler. Yeryüzü,  Kıyamet Günü tamamıyla O\'nun avucundadır. Gökler de O\'nun sağ eliyle[1] dürülmüş olacaktır. O,  onların ortak koştuklarından münezzehtir ve çok yücedir.', 'وما قدروا الله حق قدره والارض جميعا قبضته يوم القيمة والسموت مطويت بيمينه سبحنه وتعلي عما يشركون'),
(4126, 39, 68, 'وَنُفِـخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمٰوَاتِ وَمَنْ فِي الْاَرْضِ اِلَّا مَنْ شَٓاءَ اللّٰهُۚ ثُمَّ نُفِـخَ ف۪يهِ اُخْرٰى فَاِذَا هُمْ قِيَامٌ يَنْظُرُونَ', 'Ve nufiha fis suri fe saıka men fis semavati ve men fil ardı illa men şaallah, summe nufiha fihi uhra fe izahum kıyamun yanzurun.', 'Sur\'a üflenmiş,  Allah\'ın dilediği hariç göklerde ve yerde olanlar çarpılıp yıkılıvermiştir. Sonra ona bir kez daha üfürüldüğü zaman onlar kalkarak bakınırlar.', 'ونفخ في الصور فصعق من في السموت ومن في الارض الا من شا الله ثم نفخ فيه اخري فاذا هم قيام ينظرون'),
(4127, 39, 69, 'وَاَشْرَقَتِ الْاَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ الْكِتَابُ وَج۪ٓيءَ بِالنَّبِيّ۪نَ وَالشُّهَدَٓاءِ وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'Ve eşrekatil ardu bi nuri rabbiha ve vudıal kitabu ve cie bin nebiyyine veş şuhedai ve kudıye beynehum bil hakkı ve hum la yuzlemun.', 'Yer[1] Rabb\'inin aydınlığı ile aydınlanır,  kitap[2] ortaya konur,  Nebiler ve tanıklar getirilir; aralarında hakk ile karar verilir. Ve onlar asla haksızlığa uğramazlar.', 'واشرقت الارض بنور ربها ووضع الكتب وجاي بالنبين والشهدا وقضي بينهم بالحق وهم لا يظلمون'),
(4128, 39, 70, 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَا عَمِلَتْ وَهُوَ اَعْلَمُ بِمَا يَفْعَلُونَ۟', 'Ve vuffiyet kullu nefsin ma amilet ve huve a\'lemu bima yef\'alun.', 'Herkese yaptığının karşılığı tam olarak verilir. O,  onların yaptıklarını en iyi bilendir.', 'ووفيت كل نفس ما عملت وهو اعلم بما يفعلون'),
(4129, 39, 71, 'وَس۪يقَ الَّذ۪ينَ كَفَرُٓوا اِلٰى جَهَنَّمَ زُمَراًۜ حَتّٰٓى اِذَا جَٓاؤُ۫هَا فُتِحَتْ اَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُـهَٓا اَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَتْلُونَ عَلَيْكُمْ اٰيَاتِ رَبِّكُمْ وَيُنْذِرُونَكُمْ لِقَٓاءَ يَوْمِكُمْ هٰذَاۜ قَالُوا بَلٰى وَلٰكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكَافِر۪ينَ', 'Vesikallezine keferu ila cehenneme zumera, hatta iza cauha futihat ebvabuha, ve kale lehum hazenetuha e lem ye\'tikum rusulun minkum yetlune aleykum ayati rabbikum ve yunzirunekum likae yevmikum haza, kalu bela ve lakin hakkat kelimetul azabi alel kafirin.', 'Kafirler[1] bölük bölük Cehennem\'e sürülürler. Oraya vardıklarında,  kapıları açılır. Cehennem\'in bekçileri onlara: \"İçinizden size Rabb\'inizin ayetlerini okuyan,  sizi bu gününüzle karşılaşacağınıza dair uyaran resuller gelmedi mi?\" derler. Onlar: \"Evet geldi.\" derler. Fakat azap sözü Kafirlerin üzerine gerçekleşti.', 'وسيق الذين كفروا الي جهنم زمرا حتي اذا جاوها فتحت ابوبها وقال لهم خزنتها الم ياتكم رسل منكم يتلون عليكم ايت ربكم وينذرونكم لقا يومكم هذا قالوا بلي ولكن حقت كلمة العذاب علي الكفرين'),
(4130, 39, 72, 'ق۪يلَ ادْخُلُٓوا اَبْوَابَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَاۚ فَبِئْسَ مَثْوَى الْمُتَكَبِّر۪ينَ', 'Kiledhulu ebvabe cehenneme halidine fiha, fe bi\'se mesvel mutekebbirin.', '\"İçinde sürekli kalmak üzere Cehennem\'in kapılarından girin!\" denir. Büyüklük taslayanların kalacakları yer ne kötüdür.', 'قيل ادخلوا ابوب جهنم خلدين فيها فبيس مثوي المتكبرين'),
(4131, 39, 73, 'وَس۪يقَ الَّذ۪ينَ اتَّقَوْا رَبَّهُمْ اِلَى الْجَنَّةِ زُمَراًۜ حَتّٰٓى اِذَا جَٓاؤُ۫هَا وَفُتِحَتْ اَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِد۪ينَ', 'Vesikallezinettekav rabbehum ilel cenneti zumera, hatta iza cauha ve futihat ebvabuha ve kale lehum hazenetuha selamun aleykum tıbtum fedhuluha halidin.', 'Rabb\'lerine karşı takva sahibi olanlar grup grup Cennet\'e sevk edilirler. Oraya vardıklarında,  onun kapıları açılır. Onun görevlileri,  onlara: \"Selam sizlere,  siz aklandınız! Sürekli kalmak üzere ona girin.\" derler.', 'وسيق الذين اتقوا ربهم الي الجنة زمرا حتي اذا جاوها وفتحت ابوبها وقال لهم خزنتها سلم عليكم طبتم فادخلوها خلدين'),
(4132, 39, 74, 'وَقَالُوا الْحَمْدُ لِلّٰهِ الَّذ۪ي صَدَقَنَا وَعْدَهُ وَاَوْرَثَنَا الْاَرْضَ نَتَبَوَّاُ مِنَ الْجَنَّةِ حَيْثُ نَشَٓاءُۚ فَنِعْمَ اَجْرُ الْعَامِل۪ينَ', 'Ve kalul hamdu lillahillezi sadakana va\'dehu ve evresenel arda netebevveu minel cenneti haysu neşa, fe ni\'me ecrul amilin.', 'Onlar da: \"Hamd,  bize verdiği sözü yerine getiren Allah\'a özgüdür. Bizi bu yere varis kıldı. Cennet\'te istediğimiz yerde kalabiliyoruz. Çalışanların[1] ödülü ne güzel.\" derler.', 'وقالوا الحمد لله الذي صدقنا وعده واورثنا الارض نتبوا من الجنة حيث نشا فنعم اجر العملين'),
(4133, 39, 75, 'وَتَرَى الْمَلٰٓئِكَةَ حَٓافّ۪ينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْۚ وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَق۪يلَ الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَ', 'Ve terel melaikete haffine min havlil arşı yusebbihune bi hamdi rabbihim, ve kudıye beynehum bil hakkı ve kıylel hamdu lillahi rabbil alemin.', 'Melekleri,  arşın[1] çevresini kuşatmış olarak,  Rabb\'lerini övgü ile yücelttiklerini görürsün. Artık onların[2] aralarında hakk ile hüküm verilmiştir. \"Âlemlerin Rabb\'ine hamdolsun.\" denir.', 'وتري المليكة حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العلمين'),
(4134, 40, 1, 'حٰمٓۜ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4135, 40, 2, 'تَنْز۪يلُ الْكِتَابِ مِنَ اللّٰهِ الْعَز۪يزِ الْعَل۪يمِۙ', 'Tenzilul kitabi minallahil azizil alim.', 'Bu Kitap\'ın indirilmesi,  Mutlak Üstün Olan,  Her Şeyi Bilen Allah tarafındandır.', 'تنزيل الكتب من الله العزيز العليم'),
(4136, 40, 3, 'غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَد۪يدِ الْعِقَابِ ذِي الطَّوْلِۜ لَٓا اِلٰهَ اِلَّا هُوَۜ اِلَيْهِ الْمَص۪يرُ', 'Gafiriz zenbi ve kabilit tevbi şedidil ikabi zit tavl, la ilahe illa huve, ileyhil masir.', 'O,  suçu bağışlayan,  tevbeyi kabul eden,  cezası şiddetli,  sınırsız güç[1] sahibi olandır. O\'ndan başka ilah yoktur. Dönüş,  yalnızca O\'nadır.', 'غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير'),
(4137, 40, 4, 'مَا يُجَادِلُ ف۪ٓي اٰيَاتِ اللّٰهِ اِلَّا الَّذ۪ينَ كَفَرُوا فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِي الْبِلَادِ', 'Ma yucadilu fi ayatillahi illellezine keferu fe la yagrurke tekallubuhum fil bilad.', 'Kafirlerden[1] başkası Allah\'ın ayetleri hakkında tartışmaz. Onların beldelerde[2] diledikleri gibi gezip tozmaları seni aldatmasın.', 'ما يجدل في ايت الله الا الذين كفروا فلا يغررك تقلبهم في البلد'),
(4138, 40, 5, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَالْاَحْزَابُ مِنْ بَعْدِهِمْۖ وَهَمَّتْ كُلُّ اُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَادَلُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ فَاَخَذْتُهُمْ۠ فَكَيْفَ كَانَ عِقَابِ', 'Kezzebet kablehum kavmu nuhın vel ahzabu min ba\'dıhım ve hemmet kullu ummetin bi resulihim li ye\'huzuhu ve cadelu bil batılı li yudhıdu bihil hakka fe ehaztuhum, fe keyfe kane ıkab.', 'Onlardan önce Nuh halkı ve onlardan sonraki topluluklar da yalanladılar. Her ümmet,  kendi resullerini yalanlamaya yöneldi. Hakk\'ı,  Batıl\'la yok etmek için mücadele ettiler. Ben de onları yakalayıverdim. Akabinde cezalandırmam nasılmış gördüler!', 'كذبت قبلهم قوم نوح والاحزاب من بعدهم وهمت كل امة برسولهم لياخذوه وجدلوا بالبطل ليدحضوا به الحق فاخذتهم فكيف كان عقاب'),
(4139, 40, 6, 'وَكَذٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذ۪ينَ كَفَرُٓوا اَنَّهُمْ اَصْحَابُ النَّارِۢ', 'Ve kezalike hakkat kelimetu rabbike alellezine keferu ennehum ashabun nar.', 'İşte böylece Kafirlerin üzerine,  Rabb\'inin,  \"Kuşkusuz ki onlar Cehennem halkıdır.\" Kelimesi[1] hak oldu.', 'وكذلك حقت كلمت ربك علي الذين كفروا انهم اصحب النار'),
(4140, 40, 7, 'اَلَّذ۪ينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِه۪ وَيَسْتَغْفِرُونَ لِلَّذ۪ينَ اٰمَنُواۚ رَبَّـنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْماً فَاغْفِرْ لِلَّذ۪ينَ تَابُوا وَاتَّبَعُوا سَب۪يلَكَ وَقِهِمْ عَذَابَ الْجَح۪يمِ', 'Ellezine yahmilunel arşa ve men havlehu yusebbihune bi hamdi rabbihim ve yu\'minune bihi ve yestagfirune lillezine amenu, rabbena vesi\'te kulle şey\'in rahmeten ve ilmen fagfir lillezine tabu vettebeu sebileke vekıhim azabel cahim.', 'Arş\'ı[1] yüklenenler ve çevresinde bulunanlar,  Rabblerini övgü ile yüceltirler. Ve O\'na iman ederler. İman edenler için bağışlanma dilerler: \"Rabb\'imiz! Sen,  rahmet ve bilgice her şeyi kuşattın. Tevbe edip senin dosdoğru yoluna uyan kimseleri bağışla. Onları Cehennem azabından koru.\"', 'الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويومنون به ويستغفرون للذين امنوا ربنا وسعت كل شي رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم'),
(4141, 40, 8, 'رَبَّنَا وَاَدْخِلْهُمْ جَنَّاتِ عَدْنٍۨ الَّت۪ي وَعَدْتَهُمْ وَمَنْ صَلَحَ مِنْ اٰبَٓائِهِمْ وَاَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْۜ اِنَّكَ اَنْتَ الْعَز۪يزُ الْحَك۪يمُۚ', 'Rabbena ve edhilhum cennati adninilleti vaadtehum ve men salaha min abaihim ve ezvacihim ve zurriyyatihim inneke entel azizul hakim.', '\"Rabb\'imiz! Onları; onların atalarından,  eşlerinden ve soylarından salih kimseleri,  kendilerine söz verdiğin Adn Cennetlerine koy. Sen,  Mutlak Üstün Olan\'sın,  En İyi Hüküm Veren\'sin.\"', 'ربنا وادخلهم جنت عدن التي وعدتهم ومن صلح من ابايهم وازوجهم وذريتهم انك انت العزيز الحكيم'),
(4142, 40, 9, 'وَقِهِمُ السَّيِّـَٔاتِۜ  وَمَنْ تَقِ السَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۜ وَذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُ۟', 'Vekıhimus seyyiat, ve men tekıs seyyiati yevme izin fe kad rahimteh ve zalike huvel fevzul azim.', '\"Onları kötülüklerden koru. Ve Sen izin günü[1] kimi kötülüklerden korursan,  ona rahmet etmiş olursun. İşte bu,  büyük kurtuluştur.\"', 'وقهم السيات ومن تق السيات يوميذ فقد رحمته وذلك هو الفوز العظيم'),
(4143, 40, 10, 'اِنَّ الَّذ۪ينَ كَفَرُوا يُنَادَوْنَ لَمَقْتُ اللّٰهِ اَكْبَرُ مِنْ مَقْتِكُمْ اَنْفُسَكُمْ اِذْ تُدْعَوْنَ اِلَى الْا۪يمَانِ فَتَكْفُرُونَ', 'İnnellezine keferu yunadevne le maktullahi ekberu min maktikum enfusekum iz tud\'avne ilel imani fe tekfurun.', 'Kafirlere seslenilir: \"Elbette ki Allah\'ın kızgınlığı,  kendinize duymuş olduğunuz kızgınlıktan daha büyüktür. Zira siz inanmaya çağrıldığınız zaman,  Kafirlik ediyordunuz.\"', 'ان الذين كفروا ينادون لمقت الله اكبر من مقتكم انفسكم اذ تدعون الي الايمن فتكفرون'),
(4144, 40, 11, 'قَالُوا رَبَّنَٓا اَمَتَّنَا اثْنَتَيْنِ وَاَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ اِلٰى خُرُوجٍ مِنْ سَب۪يلٍ', 'Kalu rabbena emettenesneteyni ve ahyeytenesneteyni fa\'terefna bi zunubina fe hel ila hurucin min sebil.', 'Dediler ki: \"Rabb\'imiz! Bizi iki kez öldürdün,  iki kez dirilttin[1]. Artık suçlarımızı itiraf ettik. Şimdi bu durumdan kurtulmanın bir yolu var mı?\"', 'قالوا ربنا امتنا اثنتين واحييتنا اثنتين فاعترفنا بذنوبنا فهل الي خروج من سبيل'),
(4145, 40, 12, 'ذٰلِكُمْ بِاَنَّـهُٓ اِذَا دُعِيَ اللّٰهُ وَحْدَهُ كَفَرْتُمْۚ وَاِنْ يُشْرَكْ بِه۪ تُؤْمِنُواۜ فَالْحُكْمُ لِلّٰهِ الْعَلِيِّ الْكَب۪يرِ', 'Zalikum bi ennehu iza duiyallahu vahdehu kefertum, ve in yuşrek bihi tu\'minu, fel hukmu lillahil aliyyil kebir.', 'Bu,  sizin bir tek Allah\'a çağrıldığınız zaman Küfr[1] etmeniz nedeniyledir. O\'na şirk koşulunca inanıyordunuz. Artık karar yüce ve büyük olan Allah\'ındır.', 'ذلكم بانه اذا دعي الله وحده كفرتم وان يشرك به تومنوا فالحكم لله العلي الكبير'),
(4146, 40, 13, 'هُوَ الَّذ۪ي يُر۪يكُمْ اٰيَاتِه۪ وَيُنَزِّلُ لَكُمْ مِنَ السَّمَٓاءِ رِزْقاًۜ وَمَا يَتَذَكَّرُ اِلَّا مَنْ يُن۪يبُ', 'Huvellezi yurikum ayatihi ve yunezzilu lekum mines semai rızka, ve ma yetezekkeru illa men yunib.', 'O,  size ayetlerini[1] gösteren,  sizin için gökten rızık indirendir. Ancak,  gönülden yönelenler öğüt alırlar.', 'هو الذي يريكم ايته وينزل لكم من السما رزقا وما يتذكر الا من ينيب'),
(4147, 40, 14, 'فَادْعُوا اللّٰهَ مُخْلِص۪ينَ لَهُ الدّ۪ينَ وَلَوْ كَرِهَ الْكَافِرُونَ', 'Fed\'ullahe muhlisine lehud dine ve lev kerihel kafirun.', 'Öyleyse,  Kafirler hoşlanmasa da dini yalnızca kendisine özgü[1] kılarak Allah\'a dua edin.', 'فادعوا الله مخلصين له الدين ولو كره الكفرون'),
(4148, 40, 15, 'رَف۪يعُ الدَّرَجَاتِ ذُوالْعَرْشِۚ يُلْقِي الرُّوحَ مِنْ اَمْرِه۪ عَلٰى مَنْ يَشَٓاءُ مِنْ عِبَادِه۪ لِيُنْذِرَ يَوْمَ التَّلَاقِۙ', 'Refiud derecati zul arş, yulkır ruha min emrihi ala men yeşau min ıbadihi li yunzire yevmet telak.', 'O,  dereceleri yükseltendir,  Arş\'ın[1] sahibidir. O,  \"Buluşma Günü\" hakkında insanları uyarmak için Kendi buyruğundan olan ruhu[2] kullarından dilediğine ulaştırır.', 'رفيع الدرجت ذو العرش يلقي الروح من امره علي من يشا من عباده لينذر يوم التلاق'),
(4149, 40, 16, 'يَوْمَ هُمْ بَارِزُونَۚ لَا يَخْفٰى عَلَى اللّٰهِ مِنْهُمْ شَيْءٌۜ لِمَنِ الْمُلْكُ الْيَوْمَۜ لِلّٰهِ الْوَاحِدِ الْقَهَّارِ', 'Yevme hum barizun la yahfa alallahi min hum şey\'un, li menil mulkul yevm, lillahil vahidil kahhar.', 'O gün,  onlar ortaya çıkarlar. Onların hiçbir şeyi Allah\'a gizli kalmaz. O gün,  mülk[1] kimindir? Tek ve Kahhar[2] Olan Allah\'ındır.', 'يوم هم برزون لا يخفي علي الله منهم شي لمن الملك اليوم لله الوحد القهار'),
(4150, 40, 17, 'اَلْيَوْمَ تُجْزٰى كُلُّ نَفْسٍ بِمَا كَسَبَتْۜ لَا ظُلْمَ الْيَوْمَۜ اِنَّ اللّٰهَ سَر۪يعُ الْحِسَابِ', 'El yevme tucza kullu nefsin bima kesebet, la zulmel yevm, innallahe seriul hisab.', 'Bugün her kişi kazandıklarıyla[1] hesaba çekilecektir. Bugün,  haksızlık yoktur. Kuşkusuz Allah hesabı çabuk görendir.', 'اليوم تجزي كل نفس بما كسبت لا ظلم اليوم ان الله سريع الحساب'),
(4151, 40, 18, 'وَاَنْذِرْهُمْ يَوْمَ الْاٰزِفَةِ اِذِ الْقُلُوبُ لَدَى الْحَنَاجِرِ كَاظِم۪ينَۜ مَا لِلظَّالِم۪ينَ مِنْ حَم۪يمٍ وَلَا شَف۪يعٍ يُطَاعُۜ', 'Ve enzirhum yevmel azifeti izil kulubu ledel hanaciri kazımin, ma liz zalimine min hamimin ve la şefiin yutau.', 'Yaklaşan gün hakkında onları uyar. O gün korkudan yürekler ağızlara gelir. Zalimler için ne samimi bir dost ne de sözü dinlenir bir şefaatçi[1] vardır.', 'وانذرهم يوم الازفة اذ القلوب لدي الحناجر كظمين ما للظلمين من حميم ولا شفيع يطاع'),
(4152, 40, 19, 'يَعْلَمُ خَٓائِنَةَ الْاَعْيُنِ وَمَا تُخْفِي الصُّدُورُ', 'Ya\'lemu hainetel a\'yuni ve ma tuhfis sudur.', 'O,  bakışlardaki art niyeti ve göğüslerin gizlediğini bilir.', 'يعلم خاينة الاعين وما تخفي الصدور');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4153, 40, 20, 'وَاللّٰهُ يَقْض۪ي بِالْحَقِّۜ وَالَّذ۪ينَ يَدْعُونَ مِنْ دُونِه۪ لَا يَقْضُونَ بِشَيْءٍۜ اِنَّ اللّٰهَ هُوَ السَّم۪يعُ الْبَص۪يرُ۟', 'Vallahu yakdi bil hakk, vellezine yed\'une min dunihi la yakdune bi şey\'in, innallahe huves semiul basir.', 'Allah,  hakkı gerçekleştirir. Allah\'ın yanı sıra yöneldikleri kimseler ise hiçbir şeyi gerçekleştiremezler. Kuşkusuz Allah,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'والله يقضي بالحق والذين يدعون من دونه لا يقضون بشي ان الله هو السميع البصير'),
(4154, 40, 21, 'اَوَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ كَانُوا مِنْ قَبْلِهِمْۜ كَانُوا هُمْ اَشَدَّ مِنْهُمْ قُوَّةً وَاٰثَاراً فِي الْاَرْضِ فَاَخَذَهُمُ اللّٰهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُمْ مِنَ اللّٰهِ مِنْ وَاقٍ', 'E ve lem yesiru fil ardı fe yenzuru keyfe kane akibetullezine kanu min kablihim, kanu hum eşedde min hum kuvveten ve asaran fil ardı fe ehazehumullahu bi zunubihim ve ma kane lehum minallahi min vak.', 'Onlar,  yeryüzünde gezinip,  kendilerinden önce gelip geçmiş olanların sonlarının nasıl olduğuna bakmazlar mı? Onlar,  yeryüzünde güç olarak ve bıraktıkları eserler bakımından daha üstündüler. Yine de Allah onları,  suçları[1] nedeniyle cezalandırdı. Kendilerini Allah\'tan koruyan kimse olmadı.', 'اولم يسيروا في الارض فينظروا كيف كان عقبة الذين كانوا من قبلهم كانوا هم اشد منهم قوة واثارا في الارض فاخذهم الله بذنوبهم وما كان لهم من الله من واق'),
(4155, 40, 22, 'ذٰلِكَ بِاَنَّهُمْ كَانَتْ تَأْت۪يهِمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَكَفَرُوا فَاَخَذَهُمُ اللّٰهُۜ اِنَّهُ قَوِيٌّ شَد۪يدُ الْعِقَابِ', 'Zalike bi ennehum kanet te\'tihim rusuluhum bil beyyinati fe keferu fe ehazehumullah, innehu kaviyyun şedidul ikab.', 'Bu,  resuller kendilerine kanıt içeren belgelerle geldikleri halde onları yalanlamaları nedeniyledir. Bunun üzerine Allah onları cezalandırdı. O,  Mutlak Güç Sahibi\'dir,  Cezalandırması Çok Şiddetli Olan\'dır.', 'ذلك بانهم كانت تاتيهم رسلهم بالبينت فكفروا فاخذهم الله انه قوي شديد العقاب'),
(4156, 40, 23, 'وَلَقَدْ اَرْسَلْنَا مُوسٰى بِاٰيَاتِنَا وَسُلْطَانٍ مُب۪ينٍۙ', 'Ve lekad erselna musa bi ayatina ve sultanin mubin.', 'Ant olsun ki,  Musa\'yı ayetlerimizle ve apaçık bir yetkiyle gönderdik:', 'ولقد ارسلنا موسي بايتنا وسلطن مبين'),
(4157, 40, 24, 'اِلٰى فِرْعَوْنَ وَهَامَانَ وَقَارُونَ فَقَالُوا سَاحِرٌ كَذَّابٌ', 'İla fir\'avne ve hamane ve karune fe kalu sahirun kezzab.', 'Firavun\'a,  Haman\'a ve Karun\'a. Fakat onlar: \"Bu yalancı bir sihirbazdır.\" dediler.', 'الي فرعون وهمن وقرون فقالوا سحر كذاب'),
(4158, 40, 25, 'فَلَمَّا جَٓاءَهُمْ بِالْحَقِّ مِنْ عِنْدِنَا قَالُوا اقْتُلُٓوا اَبْنَٓاءَ الَّذ۪ينَ اٰمَنُوا مَعَهُ وَاسْتَحْيُوا نِسَٓاءَهُمْۜ وَمَا كَيْدُ الْكَافِر۪ينَ اِلَّا ف۪ي ضَلَالٍ', 'Fe lemma caehum bil hakkı min indina kaluktulu ebnaellezine amenu meahu vestahyu nisaehum, ve ma keydul kafirine illa fi dalal.', 'Böylece katımızdan hakk ile geldiği zaman onlar: \"Onunla birlikte iman eden kimselerin oğullarını öldürün; kadınlarını ise sağ bırakın.\" dediler. Kafirlerin düzeni,  sapkınlığa düşmekten başka bir şey değildir.', 'فلما جاهم بالحق من عندنا قالوا اقتلوا ابنا الذين امنوا معه واستحيوا نساهم وما كيد الكفرين الا في ضلل'),
(4159, 40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُون۪ٓي اَقْتُلْ مُوسٰى وَلْيَدْعُ رَبَّهُۚ اِنّ۪ٓي اَخَافُ اَنْ يُبَدِّلَ د۪ينَكُمْ اَوْ اَنْ يُظْهِرَ فِي الْاَرْضِ الْفَسَادَ', 'Ve kale fir\'avnu zeruni aktul musa vel yed\'u rabbeh, inni ehafu en yubeddile dinekum ev en yuzhire fil ardıl fesad.', 'Firavun: \"Bırakın beni,  Musa\'yı öldüreyim. O istediği kadar Rabb\'ini yardıma çağırsın. Ben,  onun sizin dininizi[1] değiştirmesinden veya yeryüzünde fesat çıkarmasından korkuyorum.\" dedi.', 'وقال فرعون ذروني اقتل موسي وليدع ربه اني اخاف ان يبدل دينكم او ان يظهر في الارض الفساد'),
(4160, 40, 27, 'وَقَالَ مُوسٰٓى اِنّ۪ي عُذْتُ بِرَبّ۪ي وَرَبِّكُمْ مِنْ كُلِّ مُتَكَبِّرٍ لَا يُؤْمِنُ بِيَوْمِ الْحِسَابِ۟', 'Ve kale musa inni uztu bi rabbi ve rabbikum min kulli mutekebbirin la yu\'minu bi yevmil hisab.', 'Musa: \"Kuşkusuz ben,  Hesap Günü\'ne inanmayan bütün kibirlilerden,  benim de Rabb\'im,  sizin de Rabb\'iniz olan Allah\'a sığınırım.\" dedi.', 'وقال موسي اني عذت بربي وربكم من كل متكبر لا يومن بيوم الحساب'),
(4161, 40, 28, 'وَقَالَ رَجُلٌ مُؤْمِنٌۗ مِنْ اٰلِ فِرْعَوْنَ يَكْتُمُ ا۪يمَانَهُٓ اَتَقْتُلُونَ رَجُلاً اَنْ يَقُولَ رَبِّيَ اللّٰهُ وَقَدْ جَٓاءَكُمْ بِالْبَيِّنَاتِ مِنْ رَبِّكُمْۜ وَاِنْ يَكُ كَاذِباً فَعَلَيْهِ كَذِبُهُۚ وَاِنْ يَكُ صَادِقاً يُصِبْكُمْ بَعْضُ الَّذ۪ي يَعِدُكُمْۜ اِنَّ اللّٰهَ لَا يَهْد۪ي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', 'Ve kale raculun mu\'minun min ali fir\'avne yektumu imanehu e taktulune raculen en yekule rabbiyallahu ve kad caekum bil beyyinati min rabbikum, ve in yeku kaziben fe aleyhi kezibuh, ve in yeku sadikan yusibkum ba\'dullezi yeidukum, innallahe la yehdi men huve musrifun kezzab.', 'Firavun taraftarlarından imanını gizleyen bir kimse,  şöyle dedi: \"Rabb\'im Allah\'tır dediği için mi bir adamı öldüreceksiniz? Oysaki o,  size Rabb\'inizden açık kanıtlarla geldi. Eğer yalancı biriyse yalanı kendi aleyhinedir. Eğer doğru söylüyorsa uyardığı şeylerin bir kısmı size isabet edecektir. Allah,  aşırı giden yalancı bir kimseyi doğru yola iletmez.\"', 'وقال رجل مومن من ال فرعون يكتم ايمنه اتقتلون رجلا ان يقول ربي الله وقد جاكم بالبينت من ربكم وان يك كذبا فعليه كذبه وان يك صادقا يصبكم بعض الذي يعدكم ان الله لا يهدي من هو مسرف كذاب'),
(4162, 40, 29, 'يَا قَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظَاهِر۪ينَ فِي الْاَرْضِۘ فَمَنْ يَنْصُرُنَا مِنْ بَأْسِ اللّٰهِ اِنْ جَٓاءَنَاۜ قَالَ فِرْعَوْنُ مَٓا اُر۪يكُمْ اِلَّا مَٓا اَرٰى وَمَٓا اَهْد۪يكُمْ اِلَّا سَب۪يلَ الرَّشَادِ', 'Ya kavmi lekumul mulkul yevme zahirine fil ardı fe men yensuruna min be\'sillahi in caena, kale fir\'avnu ma urikum illa ma era ve ma ehdikum illa sebiler reşad.', '\"Ey halkım! Bugün yeryüzünde gücü elinizde bulunduranlar olarak mülk[1] sizindir. Şayet gelecek olursa Allah\'ın azabından bizi kim kurtarabilir?\" Firavun: \"Ben size,  gördüğüm şeyden başkasını göstermiyorum. Ve ben,  sizi reşadın[2] yolundan başkasına iletemem.\" dedi.', 'يقوم لكم الملك اليوم ظهرين في الارض فمن ينصرنا من باس الله ان جانا قال فرعون ما اريكم الا ما اري وما اهديكم الا سبيل الرشاد'),
(4163, 40, 30, 'وَقَالَ الَّـذ۪ٓي اٰمَنَ يَا قَوْمِ اِنّ۪ٓي اَخَافُ عَلَيْكُمْ مِثْلَ يَوْمِ الْاَحْزَابِۙ', 'Ve kalellezi amene ya kavmi inni ehafu aleykum misle yevmil ahzab.', 'İman etmiş olan kimse: \"Ey halkım! Ben daha önce birçok toplumun başına gelenin sizin başınıza da gelmesinden korkuyorum.\"', 'وقال الذي امن يقوم اني اخاف عليكم مثل يوم الاحزاب'),
(4164, 40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَالَّذ۪ينَ مِنْ بَعْدِهِمْۜ وَمَا اللّٰهُ يُر۪يدُ ظُلْماً لِلْعِبَادِ', 'Misle de\'bi kavmi nuhın ve adin ve semude vellezine min ba\'dihim, ve mallahu yuridu zulmen lil ibad.', '\"Nuh,  Âd,  Semud ve onlardan sonraki toplumların durumu gibi. Allah,  kullarına haksızlık edici değildir.\"', 'مثل داب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد'),
(4165, 40, 32, 'وَيَا قَوْمِ اِنّ۪ٓي اَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِۙ', 'Ve ya kavmi inni ehafu aleykum yevmet tenad.', '\"Ey halkım! Ben sizin için o feryat[1] gününden korkuyorum.\"', 'ويقوم اني اخاف عليكم يوم التناد'),
(4166, 40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِر۪ينَۚ مَا لَكُمْ مِنَ اللّٰهِ مِنْ عَاصِمٍۚ وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ هَادٍ', 'Yevme tuvellune mudbirin, ma lekum minallahi min asım ve men yudlilillahu fe ma lehu min had.', 'Arkanıza bakmadan kaçacağınız gün,  sizi Allah\'ın azabından koruyabilecek kimse yoktur. Allah,  kimi sapkınlıkta bırakırsa[1] ona doğru yolu gösterecek yoktur.', 'يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد'),
(4167, 40, 34, 'وَلَقَدْ جَٓاءَكُمْ يُوسُفُ مِنْ قَبْلُ بِالْبَيِّنَاتِ فَمَا زِلْتُمْ ف۪ي شَكٍّ مِمَّا جَٓاءَكُمْ بِه۪ۜ حَتّٰٓى اِذَا هَلَكَ قُلْتُمْ لَنْ يَبْعَثَ اللّٰهُ مِنْ بَعْدِه۪ رَسُولاًۜ كَذٰلِكَ يُضِلُّ اللّٰهُ مَنْ هُوَ مُسْرِفٌ مُرْتَابٌۚ', 'Ve lekad caekum yusufu min kablu bil beyyinati fe ma ziltum fi şekkin mimma caekum bih, hatta iza heleke kultum len yeb\'asallahu min ba\'dihi resula, kezalike yudıllullahu men huve musrifun murtab.', 'Ant olsun ki daha önce Yusuf size açık kanıt içeren belgelerle gelmişti. Ancak o zaman onun size getirdiği şeyler hakkında kuşkulanıp durmuştunuz. Yusuf ölünce de: \"Bundan sonra Allah asla Resul göndermez.\" dediniz. Allah,  haddi aşan,  güvenmeyen kimseyi işte böyle saptırır.', 'ولقد جاكم يوسف من قبل بالبينت فما زلتم في شك مما جاكم به حتي اذا هلك قلتم لن يبعث الله من بعده رسولا كذلك يضل الله من هو مسرف مرتاب'),
(4168, 40, 35, 'اَلَّذ۪ينَ يُجَادِلُونَ ف۪ٓي اٰيَاتِ اللّٰهِ بِغَيْرِ سُلْطَانٍ اَتٰيهُمْۜ كَبُرَ مَقْتاً عِنْدَ اللّٰهِ وَعِنْدَ الَّذ۪ينَ اٰمَنُواۜ  كَذٰلِكَ يَطْبَعُ اللّٰهُ عَلٰى كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', 'Ellezine yucadilune fi ayatillahi bi gayri sultanin etahum, kebure makten indallahi ve indellezine amenu, kezalike yatbaullahu ala kulli kalbi mutekebbirin cebbar.', 'O kimseler,  kendilerine görevli kılınmış,  yetki verilmiş bir kimse gelmediği halde,  Allah\'ın ayetleri hakkında tartışırlar. Bu da Allah\'ın yanında da insanların yanında da büyük bir kızgınlığa neden olur. İşte böyle! Allah,  her büyüklük taslayanın kalbini mühürler.', 'الذين يجدلون في ايت الله بغير سلطن اتيهم كبر مقتا عند الله وعند الذين امنوا كذلك يطبع الله علي كل قلب متكبر جبار'),
(4169, 40, 36, 'وَقَالَ فِرْعَوْنُ يَا هَامَانُ ابْنِ ل۪ي صَرْحاً لَعَلّ۪ٓي اَبْلُغُ الْاَسْبَابَۙ', 'Ve kale fir\'avnu ya hamanubni li sarhan lealli eblugul esbab.', 'Firavun: \"Ey Haman! Benim için yüksek bir kule yap. Belki böylece o sebeplere ulaşırım;\"', 'وقال فرعون يهمن ابن لي صرحا لعلي ابلغ الاسبب'),
(4170, 40, 37, 'اَسْبَابَ السَّمٰوَاتِ فَاَطَّلِعَ اِلٰٓى اِلٰهِ مُوسٰى وَاِنّ۪ي لَاَظُنُّهُ كَاذِباًۜ وَكَذٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُٓوءُ عَمَلِه۪ وَصُدَّ عَنِ السَّب۪يلِۜ وَمَا كَيْدُ فِرْعَوْنَ اِلَّا ف۪ي تَبَابٍ۟', 'Esbabes semavati fe attalia ila ilahi musa ve inni le ezunnuhu kaziba, ve kezalike zuyyine li fir\'avne suu amelihi ve sudde anis sebil, ve ma keydu fir\'avne illa fi tebab.', '\"Göklerin sebeplerine. Böylece Musa\'nın ilahını görürüm. Çünkü ben onun yalancı olduğunu sanıyorum.\" dedi. Ve işte böylece Firavun\'a,  yaptığı kötü iş iyi gösterildi ve doğru yoldan çıkarıldı. Firavunun planı,  hüsrandan başka bir şeye yaramadı.', 'اسبب السموت فاطلع الي اله موسي واني لاظنه كذبا وكذلك زين لفرعون سو عمله وصد عن السبيل وما كيد فرعون الا في تباب'),
(4171, 40, 38, 'وَقَالَ الَّـذ۪ٓي اٰمَنَ يَا قَوْمِ اتَّبِعُونِ اَهْدِكُمْ سَب۪يلَ الرَّشَادِۚ', 'Ve kalellezi amene ya kavmittebiuni ehdikum sebiler reşad.', 'İman etmiş olan kimse: \"Ey halkım! Bana uyun ki sizi reşadın[1] yoluna ileteyim.\"', 'وقال الذي امن يقوم اتبعون اهدكم سبيل الرشاد'),
(4172, 40, 39, 'يَا قَوْمِ اِنَّمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَا مَتَاعٌۘ وَاِنَّ الْاٰخِرَةَ هِيَ دَارُ الْقَرَارِ', 'Ya kavmi innema hazihil hayatud dunya metaun ve innel ahirete hiye darul karar.', '\"Ey halkım! Bu dünya hayatı geçici bir yararlanmadır. Ahiret hayatı ise kesinlikle devamlı kalınacak yerdir.\"', 'يقوم انما هذه الحيوة الدنيا متع وان الاخرة هي دار القرار'),
(4173, 40, 40, 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزٰٓى اِلَّا مِثْلَهَاۚ وَمَنْ عَمِلَ صَالِحاً مِنْ ذَكَرٍ اَوْ اُنْثٰى وَهُوَ مُؤْمِنٌ فَاُو۬لٰٓئِكَ يَدْخُلُونَ الْجَنَّةَ يُرْزَقُونَ ف۪يهَا بِغَيْرِ حِسَابٍ', 'Men amile seyyieten fe la yucza illa misleha, ve men amile salihan min zekerin ev unsa ve huve mu\'minun fe ulaike yedhulunel cennete yurzekune fiha bi gayri hisab.', '\"Kim bir kötülük yaparsa,  ona yaptığının karşılığından fazlasıyla karşılık verilmez. Erkek veya kadın,  her kim mü\'min olarak salih[1] olanı yaparsa,  işte onlar hesapsız şekilde rızıklanmak üzere Cennet\'e girerler.\"', 'من عمل سيية فلا يجزي الا مثلها ومن عمل صلحا من ذكر او انثي وهو مومن فاوليك يدخلون الجنة يرزقون فيها بغير حساب'),
(4174, 40, 41, 'وَيَا قَوْمِ مَا ل۪ٓي اَدْعُوكُمْ اِلَى النَّجٰوةِ وَتَدْعُونَن۪ٓي اِلَى النَّارِۜ', 'Ve ya kavmi ma li ed\'ukum ilen necati ve ted\'uneni ilen nar.', '\"Ey halkım! Ne gariptir ki siz beni ateşe,  ben ise sizi kurtuluşa çağırıyorum!\"', 'ويقوم ما لي ادعوكم الي النجوة وتدعونني الي النار'),
(4175, 40, 42, 'تَدْعُونَن۪ي لِاَكْفُرَ بِاللّٰهِ وَاُشْرِكَ بِه۪ مَا لَيْسَ ل۪ي بِه۪ عِلْمٌۘ وَاَنَا۬ اَدْعُوكُمْ اِلَى الْعَز۪يزِ الْغَفَّارِ', 'Ted\'uneni li ekfure billahi ve uşrike bihi ma leyse li bihi ilmun ve ene ed\'ukum ilel azizil gaffar.', '\"Siz beni Allah\'ı yalanlamaya ve hakkında bilgim olmayan şeyleri O\'na ortak koşmaya çağırıyorsunuz. Ben ise sizi Mutlak Üstün ve Çok Bağışlayıcı Olan\'a çağırıyorum.\"', 'تدعونني لاكفر بالله واشرك به ما ليس لي به علم وانا ادعوكم الي العزيز الغفر'),
(4176, 40, 43, 'لَا جَرَمَ اَنَّمَا تَدْعُونَن۪ٓي اِلَيْهِ لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيَا وَلَا فِي الْاٰخِرَةِ وَاَنَّ مَرَدَّنَٓا اِلَى اللّٰهِ وَاَنَّ الْمُسْرِف۪ينَ هُمْ اَصْحَابُ النَّارِ', 'La cereme ennema ted\'uneni ileyhi leyse lehu da\'vetun fid dunya ve la fil ahireti ve enne mereddena ilallahi ve ennel musrifine hum ashabun nar.', '\"Şu bir gerçek ki,  sizin beni kendisine çağırdığınız şey,  dünyada da ahirette de kendisine çağıranlara cevap verme gücü olmayan şeydir. Kuşkusuz dönüşümüz Allah\'adır. Haddi aşanlar Cehennemliktirler.\"', 'لا جرم انما تدعونني اليه ليس له دعوة في الدنيا ولا في الاخرة وان مردنا الي الله وان المسرفين هم اصحب النار'),
(4177, 40, 44, 'فَسَتَذْكُرُونَ مَٓا اَقُولُ لَكُمْۜ وَاُفَوِّضُ اَمْر۪ٓي اِلَى اللّٰهِۜ اِنَّ اللّٰهَ بَص۪يرٌ بِالْعِبَادِ', 'Fe se tezkurune ma ekulu lekum, ve ufevvidu emri ilallah, innallahe basirun bil ibad.', '\"Sizin için söylediklerimin doğruluğunu yakında anlayacaksınız. Ben işimi Allah\'a havale ediyorum. Allah,  kullarının yaptığı her şeyi görmektedir.\"', 'فستذكرون ما اقول لكم وافوض امري الي الله ان الله بصير بالعباد'),
(4178, 40, 45, 'فَوَقٰيهُ اللّٰهُ سَيِّـَٔاتِ مَا مَكَرُوا وَحَاقَ بِاٰلِ فِرْعَوْنَ سُٓوءُ الْعَذَابِۚ', 'Fe vekahullahu seyyiati ma mekeru ve haka bi ali fir\'avne suul azab.', 'Sonra Allah onu[1],  onların yaptıkları planların kötülüklerinden korudu. Firavuncuları ise azabın kötüsü kuşattı.', 'فوقيه الله سيات ما مكروا وحاق بال فرعون سو العذاب'),
(4179, 40, 46, 'اَلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُواًّ وَعَشِياًّۚ وَيَوْمَ تَقُومُ السَّاعَةُ۠ اَدْخِلُٓوا اٰلَ فِرْعَوْنَ اَشَدَّ الْعَذَابِ', 'En naru yu\'radune aleyha guduvven ve aşiyya ve yevme tekumus saah, edhılu ale firavne eşeddel azab.', 'Ateş! Sabah akşam ona[1] arz olunurlar. O saatin gerçekleşeceği gün: \"Firavuncuları azabın şiddetlisine sokun!\"', 'النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة ادخلوا ال فرعون اشد العذاب'),
(4180, 40, 47, 'وَاِذْ يَتَحَٓاجُّونَ فِي النَّارِ فَيَقُولُ الضُّعَفٰٓؤُ۬ا لِلَّذ۪ينَ اسْتَكْـبَرُٓوا اِنَّا كُنَّا لَكُمْ تَبَعاً فَهَلْ اَنْتُمْ مُغْنُونَ عَنَّا نَص۪يباً مِنَ النَّارِ', 'Ve iz yetehaccune fin nari fe yekulud duafau lillezinestekberu inna kunna lekum tebean fe hel entum mugnune anna nasiben minen nar.', 'Ateşin içinde birbirlerini suçlarlar; güçsüz olanlar,  büyüklük taslayanlara: \"Biz size uyduk,  şimdi siz ateşin bir kısmını bizden savabilir misiniz?\" derler.', 'واذ يتحاجون في النار فيقول الضعفوا للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا نصيبا من النار'),
(4181, 40, 48, 'قَالَ الَّذ۪ينَ اسْتَكْبَرُٓوا اِنَّا كُلٌّ ف۪يهَٓا اِنَّ اللّٰهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ', 'Kalellezi nestekberu inna kullun fiha innallahe kad hakeme beynel ibad.', 'Büyüklük taslayanlar: \"Hepimiz onun içindeyiz. Artık Allah,  kulları arasında hükmünü verdi.\" derler.', 'قال الذين استكبروا انا كل فيها ان الله قد حكم بين العباد'),
(4182, 40, 49, 'وَقَالَ الَّذ۪ينَ فِي النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُوا رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْماً مِنَ الْعَذَابِ', 'Ve kalellezine fin nari li hazeneti cehennemed\'u rabbekum yuhaffif anna yevmen minel azab.', 'Ateşte olanlar,  Cehennem görevlilerine: \"Rabb\'inize dua edin de bir gün de olsa azabı bizden hafifletsin.\" derler.', 'وقال الذين في النار لخزنة جهنم ادعوا ربكم يخفف عنا يوما من العذاب'),
(4183, 40, 50, 'قَالُٓوا اَوَلَمْ تَكُ تَأْت۪يكُمْ رُسُلُكُمْ بِالْبَيِّنَاتِۜ قَالُوا بَلٰىۜ قَالُوا فَادْعُواۚ وَمَا دُعٰٓـؤُا الْكَافِر۪ينَ اِلَّا ف۪ي ضَلَالٍ۟', 'Kalu e ve lem teku te\'tikum rusulukum bil beyyinat, kalu bela, kalu fed\'u, ve ma duaul kafirine illa fi dalal.', 'Görevliler: \"Resulleriniz,  size kanıt içeren bilgilerle gelmediler mi?\" derler. Onlar: \"Evet,  geldiler.\" derler. Görevliler: \"O halde kendiniz yalvarıp yakarın; Kafirlerin duası ancak boş ve anlamsızdır.\" derler.', 'قالوا اولم تك تاتيكم رسلكم بالبينت قالوا بلي قالوا فادعوا وما دعوا الكفرين الا في ضلل'),
(4184, 40, 51, 'اِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذ۪ينَ اٰمَنُوا فِي الْحَيٰوةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْاَشْهَادُۙ', 'İnna le nensuru rusulena vellezine amenu fil hayatid dunya ve yevme yekumul eşhad.', 'Biz,  resullerimize ve inanan kimselere dünya hayatında ve tanıkların tanıklık edecekleri günde[1] kesinlikle yardım ederiz.', 'انا لننصر رسلنا والذين امنوا في الحيوة الدنيا ويوم يقوم الاشهد'),
(4185, 40, 52, 'يَوْمَ لَا يَنْفَعُ الظَّالِم۪ينَ مَعْذِرَتُهُمْ وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُٓوءُ الدَّارِ', 'Yevme la yenfeuz zalimine ma\'ziretuhum ve lehumulla\'netu ve lehum suud dar.', 'O gün zalimlere,  mazeretleri yarar sağlamaz. Onlara lanet[1] okunacak ve yurtların en kötüsü onlar içindir.', 'يوم لا ينفع الظلمين معذرتهم ولهم اللعنة ولهم سو الدار'),
(4186, 40, 53, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْهُدٰى وَاَوْرَثْنَا بَن۪ٓي اِسْرَٓائ۪ـلَ الْكِتَابَۙ', 'Ve lekad ateyna musel huda ve evresna beni israilel kitab.', 'Ant olsun ki Musa\'ya hidayet[1] verdik. İsrailoğulları\'na Kitap\'ı miras bıraktık;', 'ولقد اتينا موسي الهدي واورثنا بني اسريل الكتب'),
(4187, 40, 54, 'هُدًى وَذِكْرٰى لِاُو۬لِي الْاَلْبَابِ', 'Huden ve zikra li ulil elbab.', 'Temiz akıl sahipleri için doğru yolu gösterici ve öğüt olarak.', 'هدي وذكري لاولي الالبب'),
(4188, 40, 55, 'فَاصْبِرْ اِنَّ وَعْدَ اللّٰهِ حَقٌّ وَاسْتَغْفِرْ لِذَنْبِكَ وَسَبِّـحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالْاِبْكَارِ', 'Fasbir inne va\'dallahi hakkun vestagfir li zenbike ve sebbih bi hamdi rabbike bil aşiyyi vel ibkar.', 'O halde sabret. Kuşkusuz Allah\'ın verdiği söz gerçektir. Suçların için bağışlanma dile. Akşam sabah[1] Rabb\'ini hamd ile tesbih[2] et.', 'فاصبر ان وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والابكر'),
(4189, 40, 56, 'اِنَّ الَّذ۪ينَ يُجَادِلُونَ ف۪ٓي اٰيَاتِ اللّٰهِ بِغَيْرِ سُلْطَانٍ اَتٰيهُمْۙ اِنْ ف۪ي صُدُورِهِمْ اِلَّا كِبْرٌ مَا هُمْ بِبَالِغ۪يهِۚ فَاسْتَعِذْ بِاللّٰهِۜ اِنَّهُ هُوَ السَّم۪يعُ الْبَص۪يرُ', 'İnnellezine yucadilune fi ayatillahi bi gayri sultanin etahum in fi sudurihim illa kibrun ma hum bi baligih, festeiz billah, innehu huves semiul basir.', 'Yetkili kılınmadıkları[1] halde Allah\'ın ayetleri hakkında ileri geri konuşanların kalplerinde,  hiçbir zaman tatmin edemeyecekleri bir büyüklenme tutkusu vardır. Sen,  Allah\'a sığın. O,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'ان الذين يجدلون في ايت الله بغير سلطن اتيهم ان في صدورهم الا كبر ما هم ببلغيه فاستعذ بالله انه هو السميع البصير'),
(4190, 40, 57, 'لَخَلْقُ السَّمٰوَاتِ وَالْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', 'Le halkus semavati vel ardı ekberu min halkın nasi ve lakinne ekseren nasi la ya\'lemun.', 'Elbette ki göklerin ve yerin yaratılması,  insanların yaratılmasından daha büyük bir şeydir. Ama insanların çoğu bu gerçeği kavramıyorlar.', 'لخلق السموت والارض اكبر من خلق الناس ولكن اكثر الناس لا يعلمون'),
(4191, 40, 58, 'وَمَا يَسْتَوِي الْاَعْمٰى وَالْبَص۪يرُ وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُس۪ٓيءُۜ قَل۪يلاً مَا تَـتَذَكَّرُونَ', 'Ve ma yestevil a\'ma vel basiru vellezine amenu ve amilus salihati ve lel musiu, kalilen ma tetezekkerun.', 'Kör ile gören bir değildir[1]. İman edip salihatı[2] yapanlar ile kötülük yapanlar[3] da bir değildir. Ne kadar az düşünüyorsunuz?', 'وما يستوي الاعمي والبصير والذين امنوا وعملوا الصلحت ولا المسي قليلا ما تتذكرون'),
(4192, 40, 59, 'اِنَّ السَّاعَةَ لَاٰتِيَةٌ لَا رَيْبَ ف۪يهَا وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ', 'İnnes saate le atiyetun la reybe fiha ve lakinne ekseren nasi la yu\'minun.', 'Kuşkusuz ki o Sa\'at[1] mutlaka gelecektir. Onun geleceği kesinlikle doğrudur. Fakat insanların çoğu buna inanmazlar.', 'ان الساعة لاتية لا ريب فيها ولكن اكثر الناس لا يومنون'),
(4193, 40, 60, 'وَقَالَ رَبُّكُمُ ادْعُون۪ٓي اَسْتَجِبْ لَكُمْۜ اِنَّ الَّذ۪ينَ يَسْتَكْبِرُونَ عَنْ عِبَادَت۪ي سَيَدْخُلُونَ جَهَنَّمَ دَاخِر۪ينَ۟', 'Ve kale rabbukumud\'uni estecib lekum, innellezine yestekbirune an ibadeti se yedhulune cehenneme dahırin.', 'Rabb\'iniz: \"Bana dua edin ki size karşılık vereyim. Bana kulluk etmeye büyüklenenler,  horlanmış olarak Cehennem\'e gireceklerdir.\" dedi.', 'وقال ربكم ادعوني استجب لكم ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين'),
(4194, 40, 61, 'اَللّٰهُ الَّذ۪ي جَعَلَ لَكُمُ الَّيْلَ لِتَسْكُنُوا ف۪يهِ وَالنَّهَارَ مُبْصِراًۜ اِنَّ اللّٰهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', 'Allahullezi ceale lekumul leyle li teskunu fihi ven nehare mubsıra, innallahe le zu fadlin alen nasi ve lakinne ekseren nasi la yeşkurun.', 'Allah,  dinginlik bulmanız için geceyi karanlık,  gündüzü de[1] aydınlık yapandır. Allah,  insanlara karşı lütuf sahibidir. Ancak insanların çoğu şükretmezler.', 'الله الذي جعل لكم اليل لتسكنوا فيه والنهار مبصرا ان الله لذو فضل علي الناس ولكن اكثر الناس لا يشكرون'),
(4195, 40, 62, 'ذٰلِكُمُ اللّٰهُ رَبُّكُمْ خَالِقُ كُلِّ شَيْءٍۢ  لَٓا اِلٰهَ اِلَّا هُوَۘ فَاَنّٰى تُؤْفَكُونَ', 'Zalikumullahu rabbukum haliku kulli şey\'in la ilahe illa huve fe enna tu\'fekun.', 'İşte Rabbiniz olan Allah budur. O,  her şeyin yaratıcısıdır. O\'ndan başka ilah yoktur. O halde nasıl oluyor da başka şeylere yöneliyorsunuz?', 'ذلكم الله ربكم خلق كل شي لا اله الا هو فاني توفكون'),
(4196, 40, 63, 'كَذٰلِكَ يُؤْفَكُ الَّذ۪ينَ كَانُوا بِاٰيَاتِ اللّٰهِ يَجْحَدُونَ', 'Kezalike yu\'fekullezine kanu bi ayatillahi yechadun.', 'Allah\'ın ayetlerini bile bile reddedenler,  işte böyle haktan uzaklaşmışlardı.', 'كذلك يوفك الذين كانوا بايت الله يجحدون'),
(4197, 40, 64, 'اَللّٰهُ الَّذ۪ي جَعَلَ لَكُمُ الْاَرْضَ قَرَاراً وَالسَّمَٓاءَ بِنَٓاءً وَصَوَّرَكُمْ فَاَحْسَنَ صُوَرَكُمْ وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِۜ ذٰلِكُمُ اللّٰهُ رَبُّكُمْۚ فَـتَبَارَكَ اللّٰهُ رَبُّ الْعَالَم۪ينَ', 'Allahullezi ceale lekumul arda kararen ves semae binaen ve savverekum fe ahsene suverekum ve razakakum minet tayyibat, zalikumullahu rabbukum, fe tebarekallahu rabbul alemin.', 'Sizin için yeryüzünü yerleşim alanı,  gökyüzünü de üzerinize bir tavan gibi yapan Allah\'tır. O,  size en iyi şekille şekil veren ve sizi temiz şeylerden rızıklandırandır. İşte Rabbiniz olan Allah odur. Âlemlerin Rabb\'i olan Allah,  ne mübarektir.[1]', 'الله الذي جعل لكم الارض قرارا والسما بنا وصوركم فاحسن صوركم ورزقكم من الطيبت ذلكم الله ربكم فتبارك الله رب العلمين'),
(4198, 40, 65, 'هُوَ الْحَيُّ لَٓا اِلٰهَ اِلَّا هُوَ فَادْعُوهُ مُخْلِص۪ينَ لَهُ الدّ۪ينَۜ اَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَم۪ينَ', 'Huvel hayyu la ilahe illa huve fed\'uhu muhlisine lehud din, el hamdu lillahi rabbil alemin.', 'O,  diridir. Ondan başka ilah yoktur. O halde dini yalnızca O\'na has kılarak O\'na dua edin. Hamd yalnızca alemlerin Rabb\'i olan Allah\'a özgüdür.', 'هو الحي لا اله الا هو فادعوه مخلصين له الدين الحمد لله رب العلمين'),
(4199, 40, 66, 'قُلْ اِنّ۪ي نُه۪يتُ اَنْ اَعْبُدَ الَّذ۪ينَ تَدْعُونَ مِنْ دُونِ اللّٰهِ لَمَّا جَٓاءَنِيَ الْبَيِّنَاتُ مِنْ رَبّ۪ي وَاُمِرْتُ اَنْ اُسْلِمَ لِرَبِّ الْعَالَم۪ينَ', 'Kul inni nuhitu en a\'budellezine ted\'une min dunillahi lemma caeniyel beyyinatu min rabbi ve umirtu en uslime li rabbil alemin.', 'De ki: \"Bana,  Rabb\'imden gelen açık kanıtlar içeren bilgilerle; sizin,  Allah\'tan başka yöneldiklerinize kulluk[1] etmekten kesinlikle men edildim ve ben alemlerin Rabb\'ine teslim olmakla emrolundum.\"', 'قل اني نهيت ان اعبد الذين تدعون من دون الله لما جاني البينت من ربي وامرت ان اسلم لرب العلمين'),
(4200, 40, 67, 'هُوَ الَّذ۪ي خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلاً ثُمَّ لِتَبْلُغُٓوا اَشُدَّكُمْ ثُمَّ لِتَكُونُوا شُيُوخاًۚ وَمِنْكُمْ مَنْ يُتَوَفّٰى مِنْ قَبْلُ وَلِتَبْلُغُٓوا اَجَلاً مُسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', 'Huvellezi halakakum min turabin summe min nutfetin summe min alakatin summe yuhricukum tıflen summe li teblugu eşuddekum summe li tekunu şuyuha, ve minkum men yuteveffa min kablu ve li teblugu ecelen musemmen ve leallekum ta\'kılun.', 'O,  sizi topraktan yaratandır. Sonra bir nutfeden[1],  sonra bir alakadan.[2] Sonra sizi bir bebek olarak dünyaya getiriyor. Nihayet olgunluk çağına ulaşır,  derken yaşlanırsınız. Kiminiz bu süreci tamamlamadan vefat ettirilir. Kiminiz de belirlenen süreye kadar yaşarsınız. Umulur ki aklınızı kullanırsınız.', 'هو الذي خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا اشدكم ثم لتكونوا شيوخا ومنكم من يتوفي من قبل ولتبلغوا اجلا مسمي ولعلكم تعقلون'),
(4201, 40, 68, 'هُوَ الَّذ۪ي يُحْـي۪ وَيُم۪يتُۚ فَاِذَا قَضٰٓى اَمْراً فَاِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ۟', 'Huvellezi yuhyi ve yumit, fe iza kada emren fe innema yekulu lehu kun fe yekun.', 'Hayat veren de öldüren de O\'dur. O,  bir işin olmasını istediği zaman ona sadece \"Ol.\" der,  o da olur.', 'هو الذي يحي ويميت فاذا قضي امرا فانما يقول له كن فيكون'),
(4202, 40, 69, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ يُجَادِلُونَ ف۪ٓي اٰيَاتِ اللّٰهِۜ اَنّٰى يُصْرَفُونَۚۛ', 'E lem tere ilellezine yucadilune fi ayatillah, enna yusrafun.', 'Allah\'ın ayetleri hakkında tartışanları görmedin mi? Nasıl da saptırılıyorlar!', 'الم تر الي الذين يجدلون في ايت الله اني يصرفون'),
(4203, 40, 70, 'اَلَّذ۪ينَ كَذَّبُوا بِالْكِتَابِ وَبِمَٓا اَرْسَلْنَا بِه۪ رُسُلَنَا۠ۛ فَسَوْفَ يَعْلَمُونَۙ', 'Ellezine kezzebu bil kitabi ve bima erselna bihi rusulena, fe sevfe ya\'lemun.', 'Bu Kitap\'ı ve resullerimizle gönderdiklerimizi[1] yalanlayanlar elbette yakında gerçeği anlayacaklar.', 'الذين كذبوا بالكتب وبما ارسلنا به رسلنا فسوف يعلمون'),
(4204, 40, 71, 'اِذِ الْاَغْلَالُ ف۪ٓي اَعْنَاقِهِمْ وَالسَّلَاسِلُۜ يُسْحَبُونَۙ', 'İzil aglalu fi a\'nakıhim ves selasil, yushabun.', 'O vakit boyunlarında halkalar ve zincirler olduğu halde sürüklenecekler.', 'اذ الاغلل في اعنقهم والسلسل يسحبون'),
(4205, 40, 72, 'فِي الْحَم۪يمِ ثُمَّ فِي النَّارِ يُسْجَرُونَۚ', 'Fil hamimi summe fin nari yuscerun.', 'Kaynar suda sonra ateşte yakılacaklar.', 'في الحميم ثم في النار يسجرون'),
(4206, 40, 73, 'ثُمَّ ق۪يلَ لَهُمْ اَيْنَ مَا كُنْتُمْ تُشْرِكُونَۙ', 'Summe kile lehum eyne ma kuntum tuşrikun.', 'Sonra onlara: \"Şirk koştuklarınız nerede?\" denir;', 'ثم قيل لهم اين ما كنتم تشركون'),
(4207, 40, 74, 'مِنْ دُونِ اللّٰهِۜ قَالُوا ضَلُّوا عَنَّا بَلْ لَمْ نَكُنْ نَدْعُوا مِنْ قَبْلُ شَيْـٔاًۜ كَذٰلِكَ يُضِلُّ اللّٰهُ الْكَافِر۪ينَ', 'Min dunillah, kalu dallu anna bel lem nekun ned\'u min kablu şey\'a, kezalike yudıllullahul kafirin.', 'Allah\'tan başka. Derler ki: \"Onlar bizi ortada bırakıp kayboldular. Demek ki daha önce yakardıklarımız bir hiçmiş.\" derler. İşte Allah,  Kafirleri böyle sapkınlıkta bırakır.', 'من دون الله قالوا ضلوا عنا بل لم نكن ندعوا من قبل شيا كذلك يضل الله الكفرين'),
(4208, 40, 75, 'ذٰلِكُمْ بِمَا كُنْتُمْ تَفْرَحُونَ فِي الْاَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَمْرَحُونَۚ', 'Zalikum bima kuntum tefrehune fil ardı bi gayril hakkı ve bima kuntum temrehun.', 'İşte bu,  yeryüzünde hak hukuk tanımaksızın şımarıp azmanız nedeniyledir.', 'ذلكم بما كنتم تفرحون في الارض بغير الحق وبما كنتم تمرحون'),
(4209, 40, 76, 'اُدْخُلُٓوا اَبْوَابَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَاۚ فَبِئْسَ مَثْوَى الْمُتَكَبِّر۪ينَ', 'Udhulu ebvabe cehenneme halidine fiha, fe bi\'se mesvel mutekebbirin.', 'Orada sürekli kalmak üzere Cehennem\'in kapılarından girin. İşte,  büyüklenenlerin yeri ne kötüdür!', 'ادخلوا ابوب جهنم خلدين فيها فبيس مثوي المتكبرين'),
(4210, 40, 77, 'فَاصْبِرْ اِنَّ وَعْدَ اللّٰهِ حَقٌّۚ فَاِمَّا نُرِيَنَّكَ بَعْضَ الَّذ۪ي نَعِدُهُمْ اَوْ نَتَوَفَّيَنَّكَ فَاِلَيْنَا يُرْجَعُونَ', 'Fasbir inne va\'dallahi hakk, fe imma nuriyenneke ba\'dallezi neıduhum ev neteveffeyenneke fe ileyna yurceun.', 'O halde sabret. Kuşkusuz Allah\'ın yaptığı uyarı gerçektir. Onlara yaptığımız uyarılardan bir kısmını sana göstersek de göstermeden seni vefat ettirsek de sonunda onlar yalnızca Bize döndürüleceklerdir.', 'فاصبر ان وعد الله حق فاما نرينك بعض الذي نعدهم او نتوفينك فالينا يرجعون'),
(4211, 40, 78, 'وَلَقَدْ اَرْسَلْنَا رُسُلاً مِنْ قَبْلِكَ مِنْهُمْ مَنْ قَصَصْنَا عَلَيْكَ وَمِنْهُمْ مَنْ لَمْ نَقْصُصْ عَلَيْكَۜ وَمَا كَانَ لِرَسُولٍ اَنْ يَأْتِيَ بِاٰيَةٍ اِلَّا بِـاِذْنِ اللّٰهِۚ فَاِذَا جَٓاءَ اَمْرُ اللّٰهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ۟', 'Ve lekad erselna rusulen min kablike minhum men kasasna aleyke ve minhum men lem naksus aleyk, ve ma kane li resulin en ye\'tiye bi ayetin illa bi iznillah, fe iza cae emrullahi kudıye bil hakkı ve hasire hunalikel mubtılun.', 'Ant olsun ki,  senden önce de birçok Resul gönderdik. Onlardan bir kısmını sana anlattık,  bir kısmını ise anlatmadık. Hiçbir Resul,  Allah\'ın izni olmaksızın bir ayet[1] getiremez. Allah\'ın buyruğu geldiği zaman hak yerini bulur. Batıldan yana olanlar hüsrana uğrarlar.', 'ولقد ارسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول ان ياتي باية الا باذن الله فاذا جا امر الله قضي بالحق وخسر هنالك المبطلون'),
(4212, 40, 79, 'اَللّٰهُ الَّذ۪ي جَعَلَ لَكُمُ الْاَنْعَامَ لِتَرْكَبُوا مِنْهَا وَمِنْهَا تَأْكُلُونَۘ', 'Allahullezi ceale lekumul en\'ame li terkebu minha ve minha te\'kulun.', 'Binmeniz ve yemeniz için hayvanları yararlanmanıza sunan Allah\'tır.', 'الله الذي جعل لكم الانعم لتركبوا منها ومنها تاكلون'),
(4213, 40, 80, 'وَلَكُمْ ف۪يهَا مَنَافِـعُ وَلِتَبْلُغُوا عَلَيْهَا حَاجَةً ف۪ي صُدُورِكُمْ وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَۜ', 'Ve lekum fiha menafiu ve li teblugu aleyha haceten fi sudurikum ve aleyha ve alel fulki tuhmelun.', 'Ve sizin için onlarda daha nice yararlar var. Onlarla arzu ettiğiniz yere ulaşırsınız. Onların ve gemilerin üzerinde taşınırsınız.', 'ولكم فيها منفع ولتبلغوا عليها حاجة في صدوركم وعليها وعلي الفلك تحملون'),
(4214, 40, 81, 'وَيُر۪يكُمْ اٰيَاتِه۪ۗ فَاَيَّ اٰيَاتِ اللّٰهِ تُنْكِرُونَ', 'Ve yurikum ayatihi fe eyye ayatillahi tunkirun.', 'Allah size ayetlerini[1] gösteriyor. O halde Allah\'ın ayetlerinden hangisini inkar ediyorsunuz?', 'ويريكم ايته فاي ايت الله تنكرون'),
(4215, 40, 82, 'اَفَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ كَانُٓوا اَكْثَرَ مِنْهُمْ وَاَشَدَّ قُوَّةً وَاٰثَاراً فِي الْاَرْضِ فَمَٓا اَغْنٰى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ', 'E fe lem yesiru fil ardı fe yenzuru keyfe kane akıbetullezine min kablihim, kanu eksere minhum ve eşedde kuvveten ve asaren fil ardı fema agna anhum ma kanu yeksibun.', 'Hem onlar,  yeryüzünde gezip dolaşmazlar mı? Baksalar ya! Kendilerinden öncekilerin sonlarının nasıl olduğuna! Onlar,  güç ve yeryüzündeki eserleri bakımından daha üstündüler. Öyle olduğu halde sahip oldukları şeyler kendilerine yarar sağlamadı.', 'افلم يسيروا في الارض فينظروا كيف كان عقبة الذين من قبلهم كانوا اكثر منهم واشد قوة واثارا في الارض فما اغني عنهم ما كانوا يكسبون'),
(4216, 40, 83, 'فَلَمَّا جَٓاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَرِحُوا بِمَا عِنْدَهُمْ مِنَ الْعِلْمِ وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Fe lemma caethum rusuluhum bil beyyinati ferihu bima indehum minel ilmi ve haka bihim ma kanu bihi yestehziun.', 'Resulleri kendilerine kanıt içeren açıklayıcı bilgilerle geldiği zaman,  sahip oldukları bilgiye güvenerek şımardılar ve kendisi ile alay ettikleri şey onları kuşattı.', 'فلما جاتهم رسلهم بالبينت فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزون'),
(4217, 40, 84, 'فَلَمَّا رَاَوْا بَأْسَنَا قَالُٓوا اٰمَنَّا بِاللّٰهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِه۪ مُشْرِك۪ينَ', 'Fe lemma reev be\'sena kalu amenna billahi vahdehu ve keferna bima kunna bihi muşrikin.', 'Bizim cezamızı gördükleri zaman: \"Allah\'ın tekliğine iman ettik ve O\'na şirk koştuklarımızı inkar ettik.\" dediler.', 'فلما راوا باسنا قالوا امنا بالله وحده وكفرنا بما كنا به مشركين'),
(4218, 40, 85, 'فَلَمْ يَكُ يَنْفَعُهُمْ ا۪يمَانُهُمْ لَمَّا رَاَوْا بَأْسَنَاۜ سُنَّتَ اللّٰهِ الَّت۪ي قَدْ خَلَتْ ف۪ي عِبَادِه۪ۚ وَخَسِرَ هُنَالِكَ الْكَافِرُونَ', 'Fe lem yeku yenfeuhum imanuhum lemma reev be\'sena, sunnetallahilleti kad halet fi ibadih, ve hasire hunalikel kafirun.', 'Cezamızı görünce iman etmeleri onlara bir fayda vermedi. Allah\'ın kulları hakkındaki geçmişten bugüne uyguladığı yasası[1] budur. Kafirler orada zarara uğradılar.', 'فلم يك ينفعهم ايمنهم لما راوا باسنا سنت الله التي قد خلت في عباده وخسر هنالك الكفرون'),
(4219, 41, 1, 'حٰمٓۜ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4220, 41, 2, 'تَنْز۪يلٌ مِنَ الرَّحْمٰنِ الرَّح۪يمِۚ', 'Tenzilun miner rahmanir rahim.', 'Rahmeti bol ve kesintisiz olan tarafından indirilmiştir.', 'تنزيل من الرحمن الرحيم'),
(4221, 41, 3, 'كِتَابٌ فُصِّلَتْ اٰيَاتُهُ قُرْاٰناً عَرَبِياًّ لِقَوْمٍ يَعْلَمُونَۙ', 'Kitabun fussilet ayatuhu kur\'anen arabiyyen li kavmin ya\'lemun.', 'Bilen[1] bir halk için,  ayetleri detaylandırılmış,  Arapça kur\'an[2] bir Kitap\'tır.', 'كتب فصلت ايته قرانا عربيا لقوم يعلمون'),
(4222, 41, 4, 'بَش۪يراً وَنَذ۪يراًۚ فَاَعْرَضَ اَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'Beşiren ve nezira, fe a\'rada ekseruhum fehum la yesmeun.', 'Haber verici ve uyarıcı olarak. Fakat insanların çoğu ondan yüz çevirmekte ve onu dinlememektedirler.', 'بشيرا ونذيرا فاعرض اكثرهم فهم لا يسمعون'),
(4223, 41, 5, 'وَقَالُوا قُلُوبُنَا ف۪ٓي اَكِنَّةٍ مِمَّا تَدْعُونَٓا اِلَيْهِ وَف۪ٓي اٰذَانِنَا وَقْرٌ وَمِنْ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَاعْمَلْ اِنَّـنَا عَامِلُونَ', 'Ve kalu kulubuna fi ekinnetin mimma ted\'una ileyhi ve fi azanina vakrun ve min beynina ve beynike hicabun fa\'mel innena amilun.', '\"Bizi kendisine çağırdığın şeye karşı,  kalplerimiz örtülü,  kulaklarımızda bir ağırlık ve bizimle senin aranda bir perde vardır. Artık sen,  bildiğini yap,  biz de bildiğimizi yapacağız.\" dediler.', 'وقالوا قلوبنا في اكنة مما تدعونا اليه وفي اذاننا وقر ومن بيننا وبينك حجاب فاعمل اننا عملون'),
(4224, 41, 6, 'قُلْ اِنَّـمَٓا اَنَا۬ بَشَرٌ مِثْلُكُمْ يُوحٰٓى اِلَيَّ اَنَّـمَٓا اِلٰهُـكُمْ اِلٰهٌ وَاحِدٌ فَاسْتَق۪يمُٓوا اِلَيْهِ وَاسْتَغْفِرُوهُۜ وَوَيْلٌ لِلْمُشْرِك۪ينَۙ', 'Kul innema ene beşerun mislukum yuha ileyye ennema ilahukum ilahun vahidun festekimu ileyhi vestagfiruh, ve veylun lil muşrikin.', 'De ki: \"Ben de sizin gibi bir beşerim.[1] Bana vahyolunuyor ki,  sizin ilahınız[2],  bir tek ilahtır. Öyleyse doğrudan O\'na yönelin ve yalnızca O\'ndan bağışlanma dileyin. Müşriklerin vay haline!\"', 'قل انما انا بشر مثلكم يوحي الي انما الهكم اله وحد فاستقيموا اليه واستغفروه وويل للمشركين'),
(4225, 41, 7, 'اَلَّذ۪ينَ لَا يُؤْتُونَ الزَّكٰوةَ وَهُمْ بِالْاٰخِرَةِ هُمْ كَافِرُونَ', 'Ellezine la yu\'tunez zekate ve hum bil ahireti hum kafirun.', 'Onlar[1] zekat[2] yapmazlar. Ahireti inkar ederler.', 'الذين لا يوتون الزكوة وهم بالاخرة هم كفرون'),
(4226, 41, 8, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ اَجْرٌ غَيْرُ مَمْنُونٍ۟', 'İnnellezine amenu ve amilus salihati lehum ecrun gayru memnun.', 'İnanan ve salihatı[1] yapanlar için minnet altında bırakmayan bir ödül vardır.', 'ان الذين امنوا وعملوا الصلحت لهم اجر غير ممنون'),
(4227, 41, 9, 'قُلْ اَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذ۪ي خَلَقَ الْاَرْضَ ف۪ي يَوْمَيْنِ وَتَجْعَلُونَ لَـهُٓ اَنْدَاداًۜ ذٰلِكَ رَبُّ الْعَالَم۪ينَۚ', 'Kul e innekum le tekfurune billezi halakal arda fi yevmeyni ve tec\'alune lehu endada, zalike rabbul alemin.', 'De ki: \"Gerçekten de yeri iki günde yaratana mı nankörlük ediyorsunuz? O\'na denk olanlar mı görüyorsunuz? O,  alemlerin Rabb\'idir.\"', 'قل اينكم لتكفرون بالذي خلق الارض في يومين وتجعلون له اندادا ذلك رب العلمين'),
(4228, 41, 10, 'وَجَعَلَ ف۪يهَا رَوَاسِيَ مِنْ فَوْقِهَا وَبَارَكَ ف۪يهَا وَقَدَّرَ ف۪يهَٓا اَقْوَاتَهَا ف۪ٓي اَرْبَعَةِ اَيَّامٍۜ سَوَٓاءً لِلسَّٓائِل۪ينَ', 'Ve ceale fiha revasiye min fevkıha ve bareke fiha ve kaddere fiha akvateha fi erbeati eyyam, sevaen lis sailin.', 'Orada; onun üzerinde ağır baskılar oluşturdu. Ve orayı bereketli kıldı. Orada rızkını temin etmek isteyenler için,  rızıkları,  fark gözetmeden dört gün içinde takdir etti.', 'وجعل فيها روسي من فوقها وبرك فيها وقدر فيها اقوتها في اربعة ايام سوا للسايلين'),
(4229, 41, 11, 'ثُمَّ اسْتَوٰٓى اِلَى السَّمَٓاءِ وَهِيَ دُخَانٌ فَقَالَ لَهَا وَلِلْاَرْضِ ائْتِيَا طَوْعاً اَوْ كَرْهاًۜ قَالَـتَٓا اَتَيْنَا طَٓائِع۪ينَ', 'Summesteva iles semai ve hiye duhanun fe kale leha ve lil ardı\'tiya tav\'an ev kerha, kaleta eteyna taiin.', 'Sonra duman halinde bulunan göğe yöneldi. Ona ve yeryüzüne: \"İsteyerek veya istemeyerek gelin!\" dedi. İkisi de: \"İsteyerek geldik.\" dediler.[1]', 'ثم استوي الي السما وهي دخان فقال لها وللارض ايتيا طوعا او كرها قالتا اتينا طايعين'),
(4230, 41, 12, 'فَقَضٰيهُنَّ سَبْعَ سَمٰوَاتٍ ف۪ي يَوْمَيْنِ وَاَوْحٰى ف۪ي كُلِّ سَمَٓاءٍ اَمْرَهَاۜ وَزَيَّنَّا السَّمَٓاءَ الدُّنْيَا بِمَصَاب۪يحَۗ وَحِفْظاًۜ ذٰلِكَ تَقْد۪يرُ الْعَز۪يزِ الْعَل۪يمِ', 'Fe kadahunne seb\'a semavatin fi yevmeyni ve evha fi kulli semain emreha ve zeyyennes semaed dunya bi mesabiha ve hıfza, zalike takdirul azizil alim.', 'Böylece onları iki günde yedi gök olarak tamamladı. Ve her göğe işini vahyetti.[1] Ve dünya göğünü kandillerle süsleyip koruduk. İşte bu,  Mutlak Üstün Olan ve Her Şeyi Bilen\'in takdiridir.', 'فقضيهن سبع سموت في يومين واوحي في كل سما امرها وزينا السما الدنيا بمصبيح وحفظا ذلك تقدير العزيز العليم'),
(4231, 41, 13, 'فَاِنْ اَعْرَضُوا فَقُلْ اَنْذَرْتُكُمْ صَاعِقَةً مِثْلَ صَاعِقَةِ عَادٍ وَثَمُودَۜ', 'Fe in a\'radu fe kul enzertukum saıkaten misle saıkati adin ve semud.', 'Eğer hala yüz çevirirlerse,  onlara de ki: \"Âd ve Semud\'un yıldırımı gibi bir yıldırıma karşı sizi uyardım.\"', 'فان اعرضوا فقل انذرتكم صعقة مثل صعقة عاد وثمود'),
(4232, 41, 14, 'اِذْ جَٓاءَتْهُمُ الرُّسُلُ مِنْ بَيْنِ اَيْد۪يهِمْ وَمِنْ خَلْفِهِمْ اَلَّا تَعْبُدُٓوا اِلَّا اللّٰهَۜ   قَالُوا لَوْ شَٓاءَ رَبُّنَا لَاَنْزَلَ مَلٰٓئِكَةً فَاِنَّا بِمَٓا اُرْسِلْتُمْ بِه۪ كَافِرُونَ', 'İz caethumur rusulu min beyni eydihim ve min halfihim ella ta\'budu illallah, kalu lev şae rabbuna le enzele melaiketen fe inna bima ursiltum bihi kafirun.', 'Hani! Onlara,  onlardan önceki ve sonrakilere,  \"Allah\'tan başkasına kulluk etmeyin.\" diye resuller gelmişti. Onlar,  \"Eğer Rabb\'imiz isteseydi kesinlikle melekler indirirdi. O halde biz kendisiyle gönderilmiş olduğunuz şeylere Kafirlik[1] ediyoruz.\" demişlerdi.', 'اذ جاتهم الرسل من بين ايديهم ومن خلفهم الا تعبدوا الا الله قالوا لو شا ربنا لانزل مليكة فانا بما ارسلتم به كفرون'),
(4233, 41, 15, 'فَاَمَّا عَادٌ فَاسْتَكْبَرُوا فِي الْاَرْضِ بِغَيْرِ الْحَقِّ وَقَالُوا مَنْ اَشَدُّ مِنَّا قُوَّةًۜ  اَوَلَمْ يَرَوْا اَنَّ اللّٰهَ الَّذ۪ي خَلَقَهُمْ هُوَ اَشَدُّ مِنْهُمْ قُوَّةًۜ وَكَانُوا بِاٰيَاتِنَا يَجْحَدُونَ', 'Fe emma adun festekberu fil ardı bi gayril hakkı ve kalu men eşeddu minna kuvveh, e ve lem yerev ennellahellezi halakahum huve eşeddu minhum kuvveh ve kanu bi ayatina yechadun.', 'Âd\'a gelince,  onlar yeryüzünde haksız yere büyüklük tasladılar: \"Bizden daha güçlü kim olabilir?\" dediler. Kendilerini yaratan Allah\'ın,  kendilerinden daha güçlü olduğunu görmediler mi? Ayetlerimizi bile bile reddediyorlardı.', 'فاما عاد فاستكبروا في الارض بغير الحق وقالوا من اشد منا قوة اولم يروا ان الله الذي خلقهم هو اشد منهم قوة وكانوا بايتنا يجحدون'),
(4234, 41, 16, 'فَاَرْسَلْنَا عَلَيْهِمْ ر۪يحاً صَرْصَراً ف۪ٓي اَيَّامٍ نَحِسَاتٍ لِنُذ۪يقَهُمْ عَذَابَ الْخِزْيِ فِي الْحَيٰوةِ الدُّنْيَاۜ وَلَعَذَابُ الْاٰخِرَةِ اَخْزٰى وَهُمْ لَا يُنْصَرُونَ', 'Fe erselna aleyhim rihan sarsaran fi eyyamin nahisatin li nuzikahum azabel hizyi fil hayatid dunya, ve le azabul ahireti ahza ve hum la yunsarun.', 'Bunun üzerine,  dünya hayatında zillet azabını onlara tattırmamız için,  o bahtsız günlerde dondurucu bir rüzgar gönderdik. Ahiret azabı ise elbette daha rezil edicidir. Ve onlara yardım da olunmaz.', 'فارسلنا عليهم ريحا صرصرا في ايام نحسات لنذيقهم عذاب الخزي في الحيوة الدنيا ولعذاب الاخرة اخزي وهم لا ينصرون'),
(4235, 41, 17, 'وَاَمَّا ثَمُودُ فَهَدَيْنَاهُمْ فَاسْتَحَبُّوا الْعَمٰى عَلَى الْهُدٰى فَاَخَذَتْهُمْ صَاعِقَةُ الْعَذَابِ الْهُونِ بِمَا كَانُوا يَكْسِبُونَۚ', 'Ve emma semudu fe hedeynahum festehabbul ama alel huda fe ehazethum saıkatul azabil huni bima kanu yeksibun.', 'Semud halkına gelince,  onlara doğru yolu göstermiştik. Fakat onlar körlüğü doğru yola tercih ettiler. Bunun üzerine,  yaptıkları şeyler nedeniyle,  alçaltıcı azabın yıldırımı onları yakaladı.', 'واما ثمود فهدينهم فاستحبوا العمي علي الهدي فاخذتهم صعقة العذاب الهون بما كانوا يكسبون'),
(4236, 41, 18, 'وَنَجَّيْنَا الَّذ۪ينَ اٰمَنُوا وَكَانُوا يَتَّقُونَ۟', 'Ve necceynellezine amenu ve kanu yettekun.', 'Biz,  inanan ve takvalı davranan kimseleri kurtardık.', 'ونجينا الذين امنوا وكانوا يتقون'),
(4237, 41, 19, 'وَيَوْمَ يُحْشَرُ اَعْدَٓاءُ اللّٰهِ اِلَى النَّارِ فَهُمْ يُوزَعُونَ', 'Ve yevme yuhşeru a\'daullahi ilen nari fe hum yuzeun.', 'O gün,  Allah\'ın düşmanları bir araya getirilip topluca ateşe sürülecekler.', 'ويوم يحشر اعدا الله الي النار فهم يوزعون'),
(4238, 41, 20, 'حَتّٰٓى اِذَا مَا جَٓاؤُ۫هَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَاَبْصَارُهُمْ وَجُلُودُهُمْ بِمَا كَانُوا يَعْمَلُونَ', 'Hatta iza ma cauha şehide aleyhim sem\'uhum ve ebsaruhum ve culuduhum bima kanu ya\'melun.', 'Nihayet oraya geldikleri zaman,  yapmış oldukları şeylere; işitme,  görme duyuları ve bedenleri kendi aleyhlerine tanıklık ederler.', 'حتي اذا ما جاوها شهد عليهم سمعهم وابصرهم وجلودهم بما كانوا يعملون'),
(4239, 41, 21, 'وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنَاۜ قَالُٓوا اَنْطَقَنَا اللّٰهُ الَّـذ۪ٓي اَنْطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ اَوَّلَ مَرَّةٍ وَاِلَيْهِ تُرْجَعُونَ', 'Ve kalu li culudihim lime şehidtum aleyna, kalu entakanallahullezi entaka kulle şey\'in ve huve halakakum evvele merretin ve ileyhi turceun.', 'Bedenlerine,  \"Niçin aleyhimize tanıklık ettiniz?\" dediler. Bedenleri de: \"Bizi,  her şeyi konuşturan Allah konuşturdu. Sizi ilk defa O yarattı ve O\'na döndürülüyorsunuz.\"', 'وقالوا لجلودهم لم شهدتم علينا قالوا انطقنا الله الذي انطق كل شي وهو خلقكم اول مرة واليه ترجعون'),
(4240, 41, 22, 'وَمَا كُنْتُمْ تَسْتَتِرُونَ اَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَٓا اَبْصَارُكُمْ وَلَا جُلُودُكُمْ وَلٰكِنْ ظَنَنْتُمْ اَنَّ اللّٰهَ لَا يَعْلَمُ كَث۪يراً مِمَّا تَعْمَلُونَ', 'Ve ma kuntum testetirune en yeşhede aleykum sem\'ukum ve la ebsarukum ve la culudukum ve lakin zanentum ennellahe la ya\'lemu kesiren mimma ta\'melun.', '\"İşitme ve görme duyunuz ve bedeniniz aleyhinize tanıklık eder diye sakınmıyordunuz. Yapmakta olduğunuz birçok şeyi Allah\'ın bilmediğini zannediyordunuz.\"', 'وما كنتم تستترون ان يشهد عليكم سمعكم ولا ابصركم ولا جلودكم ولكن ظننتم ان الله لا يعلم كثيرا مما تعملون'),
(4241, 41, 23, 'وَذٰلِكُمْ ظَنُّكُمُ الَّذ۪ي ظَنَنْتُمْ بِرَبِّكُمْ اَرْدٰيكُمْ فَاَصْبَحْتُمْ مِنَ الْخَاسِر۪ينَ', 'Ve zalikum zannukumullezi zanentum bi rabbikum erdakum fe asbahtum minel hasirin.', '\"İşte Rabb\'iniz hakkındaki bu zannınız,  sizi helake sürükledi. Böylece hüsrana uğrayanlardan oldunuz.\"', 'وذلكم ظنكم الذي ظننتم بربكم ارديكم فاصبحتم من الخسرين'),
(4242, 41, 24, 'فَاِنْ يَصْبِرُوا فَالنَّارُ مَثْوًى لَهُمْۚ وَاِنْ يَسْتَعْتِبُوا فَمَا هُمْ مِنَ الْمُعْتَب۪ينَ', 'Fe in yasbiru fen naru mesven lehum ve in yesta\'tibu fe ma hum minel mu\'tebin.', 'Artık dayanabilirlerse[1],  onlar için konaklama yeri ateştir. Eğer özür beyan edip[2] af isteseler de onlar affedilecek olanlardan değillerdir.', 'فان يصبروا فالنار مثوي لهم وان يستعتبوا فما هم من المعتبين'),
(4243, 41, 25, 'وَقَيَّضْنَا لَهُمْ قُرَنَٓاءَ فَزَيَّنُوا لَهُمْ مَا بَيْنَ اَيْد۪يهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ الْقَوْلُ ف۪ٓي اُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِهِمْ مِنَ الْجِنِّ وَالْاِنْسِۚ اِنَّهُمْ كَانُوا خَاسِر۪ينَ۟', 'Ve kayyadna lehum kurenae fe zeyyenu lehum ma beyne eydihim ve ma halfehum ve hakka aleyhimul kavlu fi umemin kad halet min kablihim minel cinni vel ins, innehum kanu hasirin.', 'Biz,  onlara birtakım yandaşlar musallat ettik. Yaptıklarını ve yapacaklarını onlara süslü gösterdiler. Cinn ve insten[1],  kendilerinden önce gelip geçmiş topluluklarda yürürlükte olan \"söz\"[2] üzerlerine gerçekleşti. Onlar hüsrana uğrayan kimselerdir.', 'وقيضنا لهم قرنا فزينوا لهم ما بين ايديهم وما خلفهم وحق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خسرين'),
(4244, 41, 26, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لَا تَسْمَعُوا لِهٰذَا الْقُرْاٰنِ وَالْغَوْا ف۪يهِ لَعَلَّكُمْ تَغْلِبُونَ', 'Ve kalellezine keferu la tesmeu li hazel kur\'ani velgav fihi leallekum taglibun.', 'Kafirler: \"Bu Kur\'an\'ı dinlemeyin,  gürültü edin[1],  belki üstün gelirsiniz.\" dediler.', 'وقال الذين كفروا لا تسمعوا لهذا القران والغوا فيه لعلكم تغلبون'),
(4245, 41, 27, 'فَلَنُذ۪يقَنَّ الَّذ۪ينَ كَفَرُوا عَذَاباً شَد۪يداً وَلَنَجْزِيَنَّهُمْ اَسْوَاَ الَّذ۪ي كَانُوا يَعْمَلُونَ', 'Fe le nuzikannellezine keferu azaben şediden ve le necziyennehum esveellezi kanu ya\'melun.', 'Böylesi Kafirlere şiddetli bir azap tattıracağız. Ve onları yaptıklarının en kötüsü ile kesinlikle cezalandıracağız.', 'فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم اسوا الذي كانوا يعملون'),
(4246, 41, 28, 'ذٰلِكَ جَزَٓاءُ اَعْدَٓاءِ اللّٰهِ النَّارُۚ لَهُمْ ف۪يهَا دَارُ الْخُلْدِۜ جَزَٓاءً بِمَا كَانُوا بِاٰيَاتِنَا يَجْحَدُونَ', 'Zalike cezau a\'daillahin nar, lehum fiha darul huld, cezaen bimakanu bi ayatina yechadun.', 'İşte böyle! Allah\'ın düşmanlarının cezası ateştir. Ayetlerimizi bilerek reddetmeleri nedeniyle ceza olarak,  onlar için orada ebedilik yurdu vardır.', 'ذلك جزا اعدا الله النار لهم فيها دار الخلد جزا بما كانوا بايتنا يجحدون'),
(4247, 41, 29, 'وَقَالَ الَّذ۪ينَ كَفَرُوا رَبَّـنَٓا اَرِنَا الَّذَيْنِ اَضَلَّانَا مِنَ الْجِنِّ وَالْاِنْسِ نَجْعَلْهُمَا تَحْتَ اَقْدَامِنَا لِيَكُونَا مِنَ الْاَسْفَل۪ينَ', 'Ve kalellezine keferu rabbena erinellezeyni edallana minel cinni vel insi nec\'al huma tahte akdamina li yekuna minel esfelin.', 'Kafirler: \"Rabb\'imiz! Cinn ve insten[1] bizi saptıranları bize göster. Aşağılanmışlardan olmaları için onları ayaklarımızın altına alalım.\" dediler.', 'وقال الذين كفروا ربنا ارنا الذين اضلانا من الجن والانس نجعلهما تحت اقدامنا ليكونا من الاسفلين'),
(4248, 41, 30, 'اِنَّ الَّذ۪ينَ قَالُوا رَبُّنَا اللّٰهُ ثُمَّ اسْتَقَامُوا تَـتَنَزَّلُ عَلَيْهِمُ الْمَلٰٓئِكَةُ اَلَّا تَخَافُوا وَلَا تَحْزَنُوا وَاَبْشِرُوا بِالْجَنَّةِ الَّت۪ي كُنْتُمْ تُوعَدُونَ', 'İnnellezine kalu rabbunallahu summestekamu tetenezzelu aleyhimul melaiketu ella tehafu ve la tahzenu ve ebşiru bil cennetilleti kuntum tuadun.', '\"Rabb\'imiz Allah\'tır.\" deyip,  dosdoğru olanlara gelince,  onlara melekler gelerek: \"Korkmayın ve üzülmeyin. Söz verildiğiniz Cennet\'le sevinin!\" derler.', 'ان الذين قالوا ربنا الله ثم استقموا تتنزل عليهم المليكة الا تخافوا ولا تحزنوا وابشروا بالجنة التي كنتم توعدون'),
(4249, 41, 31, 'نَحْنُ اَوْلِيَٓاؤُ۬كُمْ فِي الْحَيٰوةِ الدُّنْيَا وَفِي الْاٰخِرَةِۚ وَلَكُمْ ف۪يهَا مَا تَشْتَـه۪ٓي اَنْفُسُكُمْ وَلَكُمْ ف۪يهَا مَا تَدَّعُونَۜ', 'Nahnu evliyaukum fil hayatid dunya ve fil ahireh, ve lekum fiha ma teştehi enfusukum ve lekum fiha ma teddeun.', '\"Biz,  dünya hayatında ve ahirette sizin evliyanızız.[1] Orada canlarınızın istediği her şey vardır ve istediğiniz her şey emrinizdedir.\"', 'نحن اولياوكم في الحيوة الدنيا وفي الاخرة ولكم فيها ما تشتهي انفسكم ولكم فيها ما تدعون'),
(4250, 41, 32, 'نُزُلاً مِنْ غَفُورٍ رَح۪يمٍ۟', 'Nuzulen min gafurin rahim.', '\"Çok Bağışlayıcı ve Rahmeti Kesintisiz olan tarafından bir ikram olarak.\"', 'نزلا من غفور رحيم'),
(4251, 41, 33, 'وَمَنْ اَحْسَنُ قَوْلاً مِمَّنْ دَعَٓا اِلَى اللّٰهِ وَعَمِلَ صَالِحاً وَقَالَ اِنَّن۪ي مِنَ الْمُسْلِم۪ينَ', 'Ve men ahsenu kavlen mimmen dea ilallahi ve amile salihan ve kale inneni minel muslimin.', 'Allah\'a çağıran,  salihatı yapan ve \"Ben Müslüman olanlardanım.\" diyen kimseden daha iyi sözlü kim vardır?', 'ومن احسن قولا ممن دعا الي الله وعمل صلحا وقال انني من المسلمين'),
(4252, 41, 34, 'وَلَا تَسْتَوِي الْحَسَنَةُ وَلَا السَّيِّئَةُۜ اِدْفَعْ بِالَّت۪ي هِيَ اَحْسَنُ فَاِذَا الَّذ۪ي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ  كَاَنَّهُ وَلِيٌّ حَم۪يمٌ', 'Ve la testevil hasenetu ve les seyyieh, idfa\' billeti hiye ahsenu fe izellezi beyneke ve beynehu adavetun ke ennehu veliyyun hamim.', 'İyilikle kötülük bir değildir. Kötülüğü iyilikle sav.[1] Bir de bakmışsın ki seninle arasında düşmanlık olan kişi,  candan velin[2] oluvermiş.', 'ولا تستوي الحسنة ولا السيية ادفع بالتي هي احسن فاذا الذي بينك وبينه عدوة كانه ولي حميم'),
(4253, 41, 35, 'وَمَا يُلَقّٰيهَٓا اِلَّا الَّذ۪ينَ صَبَرُواۚ وَمَا يُلَقّٰيهَٓا اِلَّا ذُوحَظٍّ عَظ۪يمٍ', 'Ve ma yulakkaha illellezine saberu, ve ma yulakkaha illa zu hazzın azim.', 'Buna[1] ancak sabredenler kavuşturulur ve buna büyük haz[2] sahipleri kavuşturulur.', 'وما يلقيها الا الذين صبروا وما يلقيها الا ذو حظ عظيم'),
(4254, 41, 36, 'وَاِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللّٰهِۜ اِنَّهُ هُوَ السَّم۪يعُ الْعَل۪يمُ', 'Ve imma yenzeganneke mineş şeytani nezgun festeız billah, innehu huves semiul alim.', 'Eğer şeytan,  bir dürtüş[1] ile seni dürtecek olursa hemen Allah\'a sığın[2]. O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'واما ينزغنك من الشيطن نزغ فاستعذ بالله انه هو السميع العليم'),
(4255, 41, 37, 'وَمِنْ اٰيَاتِهِ الَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُۜ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلّٰهِ الَّذ۪ي خَلَقَهُنَّ اِنْ كُنْتُمْ اِيَّاهُ تَعْبُدُونَ', 'Ve min ayatihil leylu ven neharu veş şemsu vel kamer, la tescudu liş şemsi ve la lil kameri vescudu lillahillezi halakahunne in kuntum iyyahu ta\'budun.', 'Gece ve gündüz; Güneş ve Ay O\'nun ayetlerindendir.[1] Güneş\'e ve Ay\'a secde[2] etmeyin. Eğer yalnızca O\'na kulluk ediyorsanız,  onları yaratmış olana secde edin.', 'ومن ايته اليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن ان كنتم اياه تعبدون'),
(4256, 41, 38, 'فَاِنِ اسْتَكْبَرُوا فَالَّذ۪ينَ عِنْدَ رَبِّكَ يُسَبِّحُونَ لَهُ بِالَّيْلِ وَالنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ', 'Fe inistekberu fellezine inde rabbike yusebbihune lehu bil leyli ven nehari ve hum la yes\'emun.', 'Eğer kibirlenirlerse,  bilsinler ki,  Rabb\'inin katında bulunanlar,  gece gündüz[1],  O\'nu tesbih[2] ederler ve onlar hiç usanmazlar.', 'فان استكبروا فالذين عند ربك يسبحون له باليل والنهار وهم لا يسمون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4257, 41, 39, 'وَمِنْ اٰيَاتِه۪ٓ اَنَّكَ تَرَى الْاَرْضَ خَاشِعَةً فَاِذَٓا اَنْزَلْنَا عَلَيْهَا الْمَٓاءَ اهْتَزَّتْ وَرَبَتْۜ اِنَّ الَّـذ۪ٓي اَحْيَاهَا لَمُحْـيِ الْمَوْتٰىۜ اِنَّهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ve min ayatihi enneke terel arda haşiaten fe iza enzelna aleyhel maehtezzet ve rebet, innellezi ahyaha le muhyil mevta, innehu ala kulli şey\'in kadir.', 'Kupkuru olarak gördüğün yeryüzünün,  sonradan üzerine su indirdiğimiz zaman harekete geçmesi ve nemalanıp kabarması da O\'nun ayetlerindendir.[1] Ona hayat veren,  elbette ki ölüleri de diriltir. O,  Her Şeye Gücü Yeten\'dir.', 'ومن ايته انك تري الارض خشعة فاذا انزلنا عليها الما اهتزت وربت ان الذي احياها لمحيي الموتي انه علي كل شي قدير'),
(4258, 41, 40, 'اِنَّ الَّذ۪ينَ يُلْحِدُونَ ف۪ٓي اٰيَاتِنَا لَا يَخْفَوْنَ عَلَيْنَاۜ  اَفَمَنْ يُلْقٰى فِي النَّارِ خَيْرٌ اَمْ مَنْ يَأْت۪ٓي اٰمِناً يَوْمَ الْقِيٰمَةِۜ اِعْمَلُوا مَا شِئْتُمْۙ اِنَّهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'İnnellezine yulhıdune fi ayatina la yahfevne aleyna, e fe men yulka fin nari hayrun em men ye\'ti aminen yevmel kıyameh, i\'melu ma şi\'tum innehu bima ta\'melune basir.', 'Ayetlerimizde saptırma yapanlar,  Bize gizli kalmazlar. O halde Kıyamet Günü ateşe atılan kimse mi yoksa Bize güven içinde gelenler mi hayırlıdır? Dilediğinizi yapın. Kuşkusuz O,  yaptığınız şeyleri en iyi görendir.', 'ان الذين يلحدون في ايتنا لا يخفون علينا افمن يلقي في النار خير ام من ياتي امنا يوم القيمة اعملوا ما شيتم انه بما تعملون بصير'),
(4259, 41, 41, 'اِنَّ الَّذ۪ينَ كَفَرُوا بِالذِّكْرِ لَمَّا جَٓاءَهُمْۚ وَاِنَّهُ لَكِتَابٌ عَز۪يزٌۙ', 'İnnellezine keferu biz zikri lemma caehum, ve innehu le kitabun aziz.', 'Onlar,  kendilerine zikir[1] geldiği zaman onu Küfrettiler. Kuşkusuz O,  yüce bir Kitap\'tır.', 'ان الذين كفروا بالذكر لما جاهم وانه لكتب عزيز'),
(4260, 41, 42, 'لَا يَأْت۪يهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِه۪ۜ تَنْز۪يلٌ مِنْ حَك۪يمٍ حَم۪يدٍ', 'La ye\'tihil batılu min beyni yedeyhi ve la min halfih, tenzilun min hakimin hamid.', 'Ona önünden ve arkasından batıl yaklaşamaz. En İyi Hüküm Veren,  Övgüye Değer Yegane Varlık tarafından indirilmiştir.', 'لا ياتيه البطل من بين يديه ولا من خلفه تنزيل من حكيم حميد'),
(4261, 41, 43, 'مَا يُقَالُ لَكَ اِلَّا مَا قَدْ ق۪يلَ لِلرُّسُلِ مِنْ قَبْلِكَۜ اِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ اَل۪يمٍ', 'Ma yukalu leke illa ma kad kile lir rusuli min kablik, inne rabbeke le zu magfiretin ve zu ikabin elim.', 'Sana,  senden önceki resullere söylenmiş olandan başka bir şey söylenmiyor.[1] Senin Rabb\'in,  kesinlikle bağışlamanın ve acı veren azabın sahibidir.', 'ما يقال لك الا ما قد قيل للرسل من قبلك ان ربك لذو مغفرة وذو عقاب اليم'),
(4262, 41, 44, 'وَلَوْ جَعَلْنَاهُ قُرْاٰناً اَعْجَمِياًّ لَقَالُوا لَوْلَا فُصِّلَتْ اٰيَاتُهُۜ  ءَاَۭۘعْجَمِيٌّ وَعَرَبِيٌّۜ قُلْ هُوَ لِلَّذ۪ينَ اٰمَنُوا هُدًى وَشِفَٓاءٌۜ وَالَّذ۪ينَ لَا يُؤْمِنُونَ ف۪ٓي اٰذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًىۜ اُو۬لٰٓئِكَ يُنَادَوْنَ مِنْ مَكَانٍ بَع۪يدٍ۟', 'Ve lev cealnahu kur\'anen a\'cemiyyen le kalu lev la fussilet ayatuh, e a\'cemiyyun ve arabiy, kul huve lillezine amenu huden ve şifaun, vellezine la yu\'minune fi azanihim vakrun ve huve aleyhim ama, ulaike yunadevne min mekanin baid.', 'Biz,  onu yabancı bir dille \"kuran\"[1] yapsaydık,  mutlaka: \"O\'nun ayetleri açıklanmalı değil miydi?\" derlerdi. Yabancı dilde bir kurana[2] Arap muhatap,  hiç olur mu? De ki: \"O,  inananlar için bir yol gösterici ve bir şifadır.\" Ve inanmayanlara gelince,  onların kulaklarında bir ağırlık vardır. Ve O,  onlara kapalıdır. Onlara sanki uzak bir yerden seslenilmektedir.[3]', 'ولو جعلنه قرانا اعجميا لقالوا لولا فصلت ايته اعجمي وعربي قل هو للذين امنوا هدي وشفا والذين لا يومنون في اذانهم وقر وهو عليهم عمي اوليك ينادون من مكان بعيد'),
(4263, 41, 45, 'وَلَقَدْ اٰتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ ف۪يهِۜ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْۜ وَاِنَّهُمْ لَف۪ي شَكٍّ مِنْهُ مُر۪يبٍ', 'Ve lekad ateyna musel kitabe fahtulife fih, ve lev la kelimetun sebekat min rabbike le kudıye beynehum, ve innehum lefi şekkin minhu murib.', 'Ant olsun ki Biz,  Musa\'ya Kitap\'ı vermiştik de onda görüş ayrılığına düştüler. Eğer Rabbinin önceden verilmiş bir kararı olmasaydı[1],  aralarında hemen hüküm verilir,  işleri bitirilirdi. Onlar,  Kur\'an hakkında tam bir ikilem ve kaygı içindeler.', 'ولقد اتينا موسي الكتب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب'),
(4264, 41, 46, 'مَنْ عَمِلَ صَالِحاً فَلِنَفْسِه۪ وَمَنْ اَسَٓاءَ فَعَلَيْهَاۜ وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَب۪يدِ', 'Men amile salihan fe li nefsihi ve men esae fe aleyha, ve ma rabbuke bi zallamin lil abid.', 'Kim salihatı yaparsa kendisi için yapmış olur. Kim de bir kötülük yaparsa,  kötülüğü kendisi içindir. Senin Rabb\'in kullarına asla haksızlık yapmaz.', 'من عمل صلحا فلنفسه ومن اسا فعليها وما ربك بظلم للعبيد'),
(4265, 41, 47, 'اِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِۜ وَمَا تَخْرُجُ مِنْ ثَمَرَاتٍ مِنْ اَكْمَامِهَا وَمَا تَحْمِلُ مِنْ اُنْثٰى وَلَا تَضَعُ اِلَّا بِعِلْمِه۪ۜ وَيَوْمَ يُنَاد۪يهِمْ اَيْنَ شُرَكَٓاء۪يۙ قَالُٓوا اٰذَنَّاكَۙ مَا مِنَّا مِنْ شَه۪يدٍۚ', 'İleyhi yureddu ilmus saah, ve ma tahrucu min semeratinmin ekmamiha ve ma tahmilu min unsa ve la tedau illa bi ilmih, ve yevme yunadihim eyne şurekai kalu azennake ma minna min şehid.', 'O Sa\'at\'ın[1] bilgisi yalnızca O\'na havale olunur. O\'nun bilgisi[2] dışında hiçbir ürün kabuğundan çıkmaz. Hiçbir dişi hamile kalmaz ve doğum yapmaz. Onlara: \"Bana ortak koştuklarınız nerede?\" diye seslenileceği gün,  onlar: \"Bizden bir tanık olmadığını[3] Sana bildiririz.\" derler.', 'اليه يرد علم الساعة وما تخرج من ثمرت من اكمامها وما تحمل من انثي ولا تضع الا بعلمه ويوم يناديهم اين شركاي قالوا اذنك ما منا من شهيد'),
(4266, 41, 48, 'وَضَلَّ عَنْهُمْ مَا كَانُوا يَدْعُونَ مِنْ قَبْلُ وَظَنُّوا مَا لَهُمْ مِنْ مَح۪يصٍ', 'Ve dalle anhum ma kanu yed\'une min kablu ve zannu ma lehum min mahis.', 'Ve daha önce tapındıkları şeyler,  onlardan uzaklaşıp gittiler. Onlar,  kendileri için kaçıp kurtulacak yer olmadığını anladılar.', 'وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص'),
(4267, 41, 49, 'لَا يَسْـَٔمُ الْاِنْسَانُ مِنْ دُعَٓاءِ الْخَيْرِۘ وَاِنْ مَسَّهُ الشَّرُّ فَيَؤُ۫سٌ قَنُوطٌ', 'La yes\'emul insanu min duail hayri ve in messehuş şerru fe yeusun kanut.', 'İnsan iyilik[1] istemekten bıkıp usanmaz. Eğer kendisine bir kötülük dokunursa,  hemen karamsarlığa kapılır ve ümitsiz olur.', 'لا يسم الانسن من دعا الخير وان مسه الشر فيوس قنوط'),
(4268, 41, 50, 'وَلَئِنْ اَذَقْنَاهُ رَحْمَةً مِنَّا مِنْ بَعْدِ ضَرَّٓاءَ مَسَّتْهُ لَيَقُولَنَّ هٰذَا ل۪يۙ وَمَٓا اَظُنُّ السَّاعَةَ قَٓائِمَةًۙ وَلَئِنْ رُجِعْتُ اِلٰى رَبّ۪ٓي اِنَّ ل۪ي عِنْدَهُ لَلْحُسْنٰىۚ فَلَنُنَبِّئَنَّ الَّذ۪ينَ كَفَرُوا بِمَا عَمِلُواۘ وَلَنُذ۪يقَنَّهُمْ مِنْ عَذَابٍ غَل۪يظٍ', 'Ve le in ezaknahu rahmeten minna min ba\'di darrae messethu le yekulenne haza li ve ma ezunnus saate kaimeten ve le in ruci\'tu ila rabbi inne li indehu lel husna, fe le nunebbiennellezine keferu bima amilu ve le nuzikannehum min azabin galiz.', 'Fakat kendisine dokunan sıkıntıdan sonra,  ona Tarafımızdan bir rahmet[1] tattırsak: \"Bu benim hakkımdır. Ve Sa\'at\'ın[2] geleceğini de sanmıyorum. Gelse bile,  Rabb\'imin huzuruna çıkarılacak olursam,  O\'nun yanında kesinlikle benim için en iyisi vardır.\" der. O zaman,  Kafirlere yaptıklarını kesinlikle bildireceğiz ve onlara kesinlikle ağır bir cezadan tattıracağız.', 'ولين اذقنه رحمة منا من بعد ضرا مسته ليقولن هذا لي وما اظن الساعة قايمة ولين رجعت الي ربي ان لي عنده للحسني فلننبين الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ'),
(4269, 41, 51, 'وَاِذَٓا اَنْعَمْنَا عَلَى الْاِنْسَانِ اَعْرَضَ وَنَاٰ بِجَانِبِه۪ۚ وَاِذَا مَسَّهُ الشَّرُّ فَذُو دُعَٓاءٍ عَر۪يضٍ', 'Ve iza en\'amna alel insani a\'rada ve nea bi canibih, ve iza messehuş şerru fe zu duain arid.', 'İnsana nimet verdiğimiz zaman,  yüz çevirip yan çizer.[1] Kendisine bir kötülük dokunduğu zaman da bol bol dua ederek yardım ister.', 'واذا انعمنا علي الانسن اعرض ونا بجانبه واذا مسه الشر فذو دعا عريض'),
(4270, 41, 52, 'قُلْ اَرَاَيْتُمْ اِنْ كَانَ مِنْ عِنْدِ اللّٰهِ ثُمَّ كَفَرْتُمْ بِه۪ مَنْ اَضَلُّ مِمَّنْ هُوَ ف۪ي شِقَاقٍ بَع۪يدٍ', 'Kul e reeytum in kane min indillahi summe kefertum bihi men edallu mimmen huve fi şikakın baid.', 'De ki: \"Gördünüz mü?[1] Eğer Kur\'an Allah katından olduğu halde,  siz onu inkar ediyor ve tanımıyorsanız; bu durumda,  haktan uzak kalandan daha sapkın kim olabilir?\"', 'قل اريتم ان كان من عند الله ثم كفرتم به من اضل ممن هو في شقاق بعيد'),
(4271, 41, 53, 'سَنُر۪يهِمْ اٰيَاتِنَا فِي الْاٰفَاقِ وَف۪ٓي اَنْفُسِهِمْ حَتّٰى يَتَبَـيَّنَ لَهُمْ اَنَّهُ الْحَقُّۜ اَوَلَمْ يَكْفِ بِرَبِّكَ اَنَّهُ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌ', 'Se nurihim ayatina fil afakı ve fi enfusihim hatta yetebeyyene lehum ennehul hakk, e ve lem yekfi bi rabbike ennehu ala kulli şey\'in şehid.', 'Âyetlerimizi[1] afakta[2] ve enfüste[3] onlara göstereceğiz. Onun[4] gerçek olduğu açıkça belli olsun diye. Rabb\'inin her şeye tanık olması yeterli değil mi?', 'سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شي شهيد'),
(4272, 41, 54, 'اَلَٓا اِنَّهُمْ ف۪ي مِرْيَةٍ مِنْ لِقَٓاءِ رَبِّهِمْۜ  اَلَٓا اِنَّهُ بِكُلِّ شَيْءٍ مُح۪يطٌ', 'E la innehum fi miryetin min likai rabbihim, e la innehu bi kulli şey\'in muhit.', 'İyi bilin ki onlar,  Rabb\'lerine kavuşacaklarından kuşku duyuyorlar. İyi bilin ki O,  Her Şeyi Kuşatan\'dır.', 'الا انهم في مرية من لقا ربهم الا انه بكل شي محيط'),
(4273, 42, 1, 'حٰمٓ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4274, 42, 2, 'عٓسٓقٓ۠', 'Ayn sin kaf.', 'Ayn,  Sin,  Kaf.', 'عسق'),
(4275, 42, 3, 'كَذٰلِكَ يُوح۪ٓي اِلَيْكَ وَاِلَى الَّذ۪ينَ مِنْ قَبْلِكَۙ اللّٰهُ الْعَز۪يزُ الْحَك۪يمُ', 'Kezalike yuhi ileyke ve ilellezine min kablikellahul azizul hakim.', 'Mutlak Üstün Olan,  En İyi Hüküm Veren Allah,  sana ve senden öncekilere işte böyle vahyeder.', 'كذلك يوحي اليك والي الذين من قبلك الله العزيز الحكيم'),
(4276, 42, 4, 'لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَهُوَ الْعَلِيُّ الْعَظ۪يمُ', 'Lehu ma fis semavati ve ma fil ard, ve huvel aliyyul azim.', 'Göklerde ve yerde olan her şey O\'nundur. O,  Çok Yüce\'dir,  Çok Ulu\'dur.', 'له ما في السموت وما في الارض وهو العلي العظيم'),
(4277, 42, 5, 'تَكَادُ السَّمٰوَاتُ يَتَفَطَّرْنَ مِنْ فَوْقِهِنَّ وَالْمَلٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَنْ فِي الْاَرْضِۜ اَلَٓا اِنَّ اللّٰهَ هُوَ الْغَفُورُ الرَّح۪يمُ', 'Tekadus semavatu yetefattarne min fevkıhinne vel melaiketu yusebbihune bi hamdi rabbihim ve yestagfirune li men fil ard, e la innellahe huvel gafurur rahim.', 'Gökler neredeyse üstlerinden çatlayacak. Melekler ise Rabblerini övgü ile yüceltiyor,  yeryüzünde bulunanlar için bağışlanma diliyorlar. İyi bilin ki Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'تكاد السموت يتفطرن من فوقهن والمليكة يسبحون بحمد ربهم ويستغفرون لمن في الارض الا ان الله هو الغفور الرحيم'),
(4278, 42, 6, 'وَالَّذ۪ينَ اتَّخَذُوا مِنْ دُونِه۪ٓ اَوْلِيَٓاءَ اللّٰهُ حَف۪يظٌ عَلَيْهِمْۘ وَمَٓا اَنْتَ عَلَيْهِمْ بِوَك۪يلٍ', 'Vellezinettehazu min dunihi evliyallahu hafizun aleyhim ve ma ente aleyhim bi vekil.', 'Onlar,  O\'nun yanı sıra veliler[1] edindiler. Allah,  onları görüp gözetlemektedir. Sen onlara vekil değilsin.', 'والذين اتخذوا من دونه اوليا الله حفيظ عليهم وما انت عليهم بوكيل'),
(4279, 42, 7, 'وَكَذٰلِكَ اَوْحَيْنَٓا اِلَيْكَ قُرْاٰناً عَرَبِياًّ لِتُنْذِرَ اُمَّ الْقُرٰى وَمَنْ حَوْلَهَا وَتُنْذِرَ يَوْمَ الْجَمْعِ لَا رَيْبَ ف۪يهِۜ فَر۪يقٌ فِي الْجَنَّةِ وَفَر۪يقٌ فِي السَّع۪يرِ', 'Ve kezalike evhayna ileyke kur\'anen arabiyyen li tunzire ummel kura ve men havleha ve tunzire yevmel cem\'i la reybe fih, ferikun fil cenneti ve ferikun fis sair.', 'Kentlerin anası[1] ve civarındakileri,  geleceği kesin olan toplanma günü ile uyarman için sana Arapça bir Kur\'an vahyettik. Onların bir kısmı Cennet\'tedir,  bir kısmı da alevli ateştedir.', 'وكذلك اوحينا اليك قرانا عربيا لتنذر ام القري ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنة وفريق في السعير'),
(4280, 42, 8, 'وَلَوْ شَٓاءَ اللّٰهُ لَجَعَلَهُمْ اُمَّةً وَاحِدَةً وَلٰكِنْ يُدْخِلُ مَنْ يَشَٓاءُ ف۪ي رَحْمَتِه۪ۜ وَالظَّالِمُونَ مَا لَهُمْ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'Ve lev şaallahu le cealehum ummeten vahıdeten ve lakin yudhilu men yeşau fi rahmetih, vez zalimune ma lehum min veliyyin ve la nasir.', 'Eğer Allah dileseydi[1] kesinlikle onları bir tek ümmet[2] yapardı. Ne var ki O hak eden[3] kimseyi rahmetinin içine koyar. Zalimlere gelince,  onların velisi ve yardımcısı yoktur.', 'ولو شا الله لجعلهم امة وحدة ولكن يدخل من يشا في رحمته والظلمون ما لهم من ولي ولا نصير'),
(4281, 42, 9, 'اَمِ اتَّخَذُوا مِنْ دُونِه۪ٓ اَوْلِيَٓاءَۚ  فَاللّٰهُ هُوَ الْوَلِيُّ وَهُوَ يُحْـيِ الْمَوْتٰىۘ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ۟', 'Emittehazu min dunihi evliyae, fallahu huvel veliyyu ve huve yuhyil mevta ve huve ala kulli şey\'in kadir.', 'Yoksa O\'ndan başka veliler mi edindiler? Oysa ki veli yalnızca O\'dur. O,  ölüleri diriltir ve O,  Her Şeye Gücü Yeten\'dir.', 'ام اتخذوا من دونه اوليا فالله هو الولي وهو يحي الموتي وهو علي كل شي قدير'),
(4282, 42, 10, 'وَمَا اخْتَلَفْتُمْ ف۪يهِ مِنْ شَيْءٍ فَحُكْمُهُٓ اِلَى اللّٰهِۜ ذٰلِكُمُ اللّٰهُ رَبّ۪ي عَلَيْهِ تَوَكَّلْتُۗ وَاِلَيْهِ اُن۪يبُ', 'Ve mahteleftum fihi min şey\'in fe hukmuhu ilallah, zalikumullahu rabbi aleyhi tevekkeltu ve ileyhi unib.', 'Bir şey hakkında anlaşmazlığa düşerseniz,  artık onun hükmü Allah\'a aittir. İşte o Allah,  benim Rabb\'imdir. O\'na tevekkül[1] ettim ve O\'na yöneldim.', 'وما اختلفتم فيه من شي فحكمه الي الله ذلكم الله ربي عليه توكلت واليه انيب'),
(4283, 42, 11, 'فَاطِرُ السَّمٰوَاتِ وَالْاَرْضِۜ جَعَلَ لَكُمْ مِنْ اَنْفُسِكُمْ اَزْوَاجاً وَمِنَ الْاَنْعَامِ اَزْوَاجاًۚ يَذْرَؤُ۬كُمْ ف۪يهِۜ لَيْسَ كَمِثْلِه۪ شَيْءٌۚ وَهُوَ السَّم۪يعُ الْبَص۪يرُ', 'Fatırus semavati vel ard, ceale lekum min enfusikum ezvacen ve minel en\'ami ezvaca, yezreukum fih, leyse ke mislihi şey\'un, ve huves semiul basir.', 'Göklerin ve yerin fıtratını[1] belirleyendir. Size,  kendinizden çiftler,  hayvanlardan çiftler yapandır. Orada sizi bir düzen içinde üretiyor. O\'na benzer hiçbir şey yoktur. O,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'فاطر السموت والارض جعل لكم من انفسكم ازوجا ومن الانعم ازوجا يذروكم فيه ليس كمثله شي وهو السميع البصير'),
(4284, 42, 12, 'لَهُ مَقَال۪يدُ السَّمٰوَاتِ وَالْاَرْضِۚ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَٓاءُ وَيَقْدِرُۜ اِنَّهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Lehu mekalidus semavati vel ard, yebsutur rızka li men yeşau ve yakdir, innehu bi kulli şey\'in alim.', 'Göklerin ve yeryüzünün kilitleri[1] yalnızca O\'nundur. O,  dilediği kimse için rızkı genişletir ve takdir eder. O,  Her Şeyi En İyi Bilen\'dir.', 'له مقاليد السموت والارض يبسط الرزق لمن يشا ويقدر انه بكل شي عليم'),
(4285, 42, 13, 'شَرَعَ لَكُمْ مِنَ الدّ۪ينِ مَا وَصّٰى بِه۪ نُوحاً وَالَّـذ۪ٓي اَوْحَيْنَٓا اِلَيْكَ وَمَا وَصَّيْنَا بِه۪ٓ اِبْرٰه۪يمَ وَمُوسٰى وَع۪يسٰٓى اَنْ اَق۪يمُوا الدّ۪ينَ وَلَا تَتَفَرَّقُوا ف۪يهِۜ   كَبُرَ عَلَى الْمُشْرِك۪ينَ مَا تَدْعُوهُمْ اِلَيْهِۜ اَللّٰهُ يَجْتَب۪ٓي اِلَيْهِ مَنْ يَشَٓاءُ وَيَهْد۪ٓي اِلَيْهِ مَنْ يُن۪يبُ', 'Şerea lekum mined dini ma vassa bihi nuhan vellezi evhayna ileyke ve ma vassayna bihi ibrahime ve musa ve isa, en ekimud dine ve la teteferreku fih, kebure alel muşrikine ma ted\'uhum ileyh, allahu yectebi ileyhi men yeşau ve yehdi ileyhi men yunib.', 'O,  size dinden Nuh\'a tavsiye ettiğini,  sana vahyettiğimizi; İbrahim\'e,  Musa\'ya ve İsa\'ya,  tavsiye buyurduğumuzu şeriat[1] yaptı. \"Dini ayakta tutun[2] ve onda ayrılığa düşmeyin.\" Senin kendilerini davet ettiğin şey,  müşriklere ağır geldi. Allah,  hak eden[3] kimseyi kendisine seçer ve kendisine yönelen kimseye doğru yolu gösterir.', 'شرع لكم من الدين ما وصي به نوحا والذي اوحينا اليك وما وصينا به ابرهيم وموسي وعيسي ان اقيموا الدين ولا تتفرقوا فيه كبر علي المشركين ما تدعوهم اليه الله يجتبي اليه من يشا ويهدي اليه من ينيب'),
(4286, 42, 14, 'وَمَا تَفَرَّقُٓوا اِلَّا مِنْ بَعْدِ مَا جَٓاءَهُمُ الْعِلْمُ بَغْياً بَيْنَهُمْۜ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ اِلٰٓى اَجَلٍ مُسَمًّى لَقُضِيَ بَيْنَهُمْۜ وَاِنَّ الَّذ۪ينَ اُو۫رِثُوا الْكِتَابَ مِنْ بَعْدِهِمْ لَف۪ي شَكٍّ مِنْهُ مُر۪يبٍ', 'Ve ma teferreku illa min ba\'di ma caehumul ilmu bagyen beynehum, ve lev la kelimetun sebekat min rabbike ila ecelin musemmen le kudıye beynehum, ve innellezine urisul kitabe min ba\'dihim le fi şekkin minhu murib.', 'Onların,  kendilerine ilim[1] geldikten sonra anlaşmazlığa düşmelerinin nedeni kıskançlık ve ihtiraslarıdır. Eğer Rabb\'inden,  \"belirlenmiş bir süreye kadar\" sözü verilmemiş olunsaydı,  aralarında hemen hüküm gerçekleştirilirdi. Onların ardından Kitap\'a mirasçı olanlar[2],  tam bir ikilem ve kaygı içindedirler.', 'وما تفرقوا الا من بعد ما جاهم العلم بغيا بينهم ولولا كلمة سبقت من ربك الي اجل مسمي لقضي بينهم وان الذين اورثوا الكتب من بعدهم لفي شك منه مريب'),
(4287, 42, 15, 'فَلِذٰلِكَ فَادْعُۚ وَاسْتَقِمْ كَمَٓا اُمِرْتَۚ وَلَا تَتَّبِعْ اَهْوَٓاءَهُمْۚ وَقُلْ اٰمَنْتُ بِمَٓا اَنْزَلَ اللّٰهُ مِنْ كِتَابٍۚ وَاُمِرْتُ لِاَعْدِلَ بَيْنَكُمْۜ اَللّٰهُ رَبُّنَا وَرَبُّكُمْۜ لَـنَٓا اَعْمَالُنَا وَلَكُمْ اَعْمَالُكُمْۜ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمْۜ اَللّٰهُ يَجْمَعُ بَيْنَنَاۚ وَاِلَيْهِ الْمَص۪يرُۜ', 'Fe li zalike fed\'u vestekım kema umirt, ve la tettebi\' ehvaehum, ve kul amentu bi ma enzelallahu min kitab, ve umirtu li a\'dile beynekum, allahu rabbuna ve rabbukum, lena a\'maluna ve lekum a\'malukum, la huccete beynena ve beynekum, allahu yecmeubeynena, ve ileyhil masir.', 'İşte bunun için,  artık sen onlara çağrıda bulun. Buyrulduğun gibi dosdoğru ol. Onların hevalarına[1] uyma. Onlara de ki: \"Allah\'ın Kitap\'tan indirdiği şeye inandım. Ve bana aranızda adaleti gerçekleştirmem buyruldu. Allah,  bizim de Rabb\'imizdir,  sizin de Rabb\'inizdir. Bizim yaptıklarımız bize,  sizin yaptıklarınız da sizedir. Öyleyse aramızda çekişmeye gerek yoktur. Nasıl olsa Allah aramızı bulacak.[2] Dönüş yalnızca O\'nadır.', 'فلذلك فادع واستقم كما امرت ولا تتبع اهواهم وقل امنت بما انزل الله من كتب وامرت لاعدل بينكم الله ربنا وربكم لنا اعملنا ولكم اعملكم لا حجة بيننا وبينكم الله يجمع بيننا واليه المصير'),
(4288, 42, 16, 'وَالَّذ۪ينَ يُحَٓاجُّونَ فِي اللّٰهِ مِنْ بَعْدِ مَا اسْتُج۪يبَ لَهُ حُجَّتُهُمْ دَاحِضَةٌ عِنْدَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَد۪يدٌ', 'Vellezine yuhaccune fillahi min ba\'di mestucibe lehu huccetuhum dahıdatun inde rabbihim ve aleyhim gadabun ve lehum azabun şedid.', 'Allah\'a olan çağrıya olumlu yanıt verdikten sonra,  O\'nun hakkında tartışanların ileri sürdükleri kanıtlar,  Rabb\'lerinin yanında geçersizdir. Onların üzerinde gazap vardır,  şiddetli bir azap da onlar içindir.', 'والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد'),
(4289, 42, 17, 'اَللّٰهُ الَّـذ۪ٓي اَنْزَلَ الْكِتَابَ بِالْحَقِّ وَالْم۪يزَانَۜ وَمَا يُدْر۪يكَ لَعَلَّ السَّاعَةَ قَر۪يبٌ', 'Allahullezi enzelel kitabe bil hakkı vel mizan ve ma yudrike lealles saate karib.', 'Allah,  Kitap\'ı ve mizanı[1] hakk ile indirendir. Nereden bileceksin ki belki de o Sa\'at[2] çok yakındır!', 'الله الذي انزل الكتب بالحق والميزان وما يدريك لعل الساعة قريب'),
(4290, 42, 18, 'يَسْتَعْجِلُ بِهَا الَّذ۪ينَ لَا يُؤْمِنُونَ بِهَاۚ وَالَّذ۪ينَ اٰمَنُوا مُشْفِقُونَ مِنْهَاۙ وَيَعْلَمُونَ اَنَّهَا الْحَقُّۜ اَلَٓا اِنَّ الَّذ۪ينَ يُمَارُونَ فِي السَّاعَةِ لَف۪ي ضَلَالٍ بَع۪يدٍ', 'Yesta\'cilu bihellezine la yu\'minune biha, vellezine amenu muşfikune minha ve ya\'lemune ennehel hakk, e la innellezine yumarune fis saati le fi dalalin baid.', 'İnanmayanlar,  alayımsı bir şekilde,  onun hemen gerçekleşmesini istiyorlar. İnananlar ise tedbirlidirler. Onun gerçek olduğunu bilirler. Sa\'at[1] hakkında tartışanlar,  derin bir sapkınlık içindedirler.', 'يستعجل بها الذين لا يومنون بها والذين امنوا مشفقون منها ويعلمون انها الحق الا ان الذين يمارون في الساعة لفي ضلل بعيد'),
(4291, 42, 19, 'اَللّٰهُ لَط۪يفٌ بِعِبَادِه۪ يَرْزُقُ مَنْ يَشَٓاءُۚ وَهُوَ الْقَوِيُّ الْعَز۪يزُ۟', 'Allahu latifun bi ibadihi yerzuku men yeşau, ve huvel kaviyyul aziz.', 'Allah,  kullarına karşı çok hoşnut edicidir. Dilediğini rızıklandırır[1]. O,  Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'الله لطيف بعباده يرزق من يشا وهو القوي العزيز'),
(4292, 42, 20, 'مَنْ كَانَ يُر۪يدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهُ ف۪ي حَرْثِه۪ۚ وَمَنْ كَانَ يُر۪يدُ حَرْثَ الدُّنْيَا نُؤْتِه۪ مِنْهَا وَمَا لَهُ فِي الْاٰخِرَةِ مِنْ نَص۪يبٍ', 'Men kane yuridu harsel ahireti nezid lehu fi harsih, ve men kane yuridu harsed dunya nu\'tihi minha ve ma lehu fil ahireti min nasib.', 'Kim ahiret ekinini[1] isterse,  Biz onun kazancını artırırız. Kim dünya ekinini isterse,  ona da ondan artırırız. Ve onun için ahirette hiçbir nasip yoktur.', 'من كان يريد حرث الاخرة نزد له في حرثه ومن كان يريد حرث الدنيا نوته منها وما له في الاخرة من نصيب'),
(4293, 42, 21, 'اَمْ لَهُمْ شُرَكٰٓؤُ۬ا شَرَعُوا لَهُمْ مِنَ الدّ۪ينِ مَا لَمْ يَأْذَنْ بِهِ اللّٰهُۜ وَلَوْلَا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْۜ وَاِنَّ الظَّالِم۪ينَ لَهُمْ عَذَابٌ اَل۪يمٌ', 'Em lehum şurekau şerau lehum mined dini ma lem ye\'zen bihillah, ve lev la kelimetul faslı le kudiye beynehum, ve innez zalimine lehum azabun elim.', 'Yoksa onların,  Allah\'ın dinde izin vermediği bir şeyi,  kendilerine meşru kılan ortakları mı var? Eğer \"ayırma kelimesi\"[1] olmasaydı kesinlikle aralarında hemen hüküm verilirdi. Kuşkusuz ki zalimler için acı bir azap vardır.', 'ام لهم شركوا شرعوا لهم من الدين ما لم ياذن به الله ولولا كلمة الفصل لقضي بينهم وان الظلمين لهم عذاب اليم'),
(4294, 42, 22, 'تَرَى الظَّالِم۪ينَ مُشْفِق۪ينَ مِمَّا كَسَبُوا وَهُوَ وَاقِـعٌ بِهِمْۜ وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ ف۪ي رَوْضَاتِ الْجَنَّاتِۚ لَهُمْ مَا يَشَٓاؤُ۫نَ عِنْدَ رَبِّهِمْۜ ذٰلِكَ هُوَ الْفَضْلُ الْكَب۪يرُ', 'Terez zalimine muşfikine mimma kesebu ve huve vakıun bihim, vellezine amenu ve amilus salihati fi ravdatil cennat, lehum ma yeşaune inde rabbihim zalike huvel fadlul kebir.', 'Kazandıkları şeylerle karşı karşıya geldiklerinde,  zalimlerin endişeye kapıldıklarını görürsün. İman edip salihatı[1] yapanlar da Cennetlerin bahçelerindedirler. Onlar için Rabb\'lerinin yanında istedikleri her şey vardır. İşte bu büyük ikramdır.', 'تري الظلمين مشفقين مما كسبوا وهو واقع بهم والذين امنوا وعملوا الصلحت في روضات الجنت لهم ما يشاون عند ربهم ذلك هو الفضل الكبير'),
(4295, 42, 23, 'ذٰلِكَ الَّذ۪ي يُبَشِّرُ اللّٰهُ عِبَادَهُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِۜ قُلْ لَٓا اَسْـَٔلُكُمْ عَلَيْهِ اَجْراً اِلَّا الْمَوَدَّةَ فِي الْقُرْبٰىۜ وَمَنْ يَقْتَرِفْ حَسَنَةً نَزِدْ لَهُ ف۪يهَا حُسْناًۜ اِنَّ اللّٰهَ غَفُورٌ شَكُورٌ', 'Zalikellezi yubeşşirullahu ibadehullezine amenu ve amilus salihat, kul la es\'elukum aleyhi ecren illel meveddete fil kurba ve men yakterif haseneten nezid lehu fiha husna, innellahe gafurun şekur.', 'İşte bu,  Allah\'ın,  iman edip salihatı yapan[1] kullarına müjdelediği şeydir. De ki: \"Ben bu çağrıya karşılık \"yakınlıkta sevgiden\"[2] başka sizden bir ücret istemiyorum. Her kim bir iyilik yaparsa,  onun için iyilikleri artırırız. Allah,  Çok Bağışlayıcı\'dır,  Çok Şükreden\'dir.[3]', 'ذلك الذي يبشر الله عباده الذين امنوا وعملوا الصلحت قل لا اسلكم عليه اجرا الا المودة في القربي ومن يقترف حسنة نزد له فيها حسنا ان الله غفور شكور'),
(4296, 42, 24, 'اَمْ يَقُولُونَ افْتَرٰى عَلَى اللّٰهِ كَذِباًۚ فَاِنْ يَشَأِ اللّٰهُ يَخْتِمْ عَلٰى قَلْبِكَۜ وَيَمْحُ اللّٰهُ الْبَاطِلَ وَيُحِقُّ الْحَقَّ بِكَلِمَاتِه۪ۜ اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Em yekuluneftera alallahi keziba, fe in yeşeillahu yahtim ala kalbik, ve yemhullahul batıla ve yuhıkkul hakka bi kelimatih, innehu alimun bi zatis sudur.', 'Onlar,  senin için \"Allah\'a karşı yalan uydurdu.\" diyorlar. Oysaki Allah dilerse[1] senin kalbini de mühürler. Batılı yok eder. Ve kelimeleriyle[2] hakkı[3] gerçekleştirir. O,  göğüslerde olanı çok iyi bilendir.', 'ام يقولون افتري علي الله كذبا فان يشا الله يختم علي قلبك ويمح الله البطل ويحق الحق بكلمته انه عليم بذات الصدور'),
(4297, 42, 25, 'وَهُوَ الَّذ۪ي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِه۪ وَيَعْفُوا عَنِ السَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَۙ', 'Ve huvellezi yakbelut tevbete an ibadihi ve ya\'fu anis seyyiati ve ya\'lemu ma tef\'alun.', 'Ve O,  kullarının tevbesini kabul eder ve kötülüklerini bağışlar. Ve yaptığınız şeyleri bilir.', 'وهو الذي يقبل التوبة عن عباده ويعفوا عن السيات ويعلم ما تفعلون'),
(4298, 42, 26, 'وَيَسْتَج۪يبُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَيَز۪يدُهُمْ مِنْ فَضْلِه۪ۜ وَالْكَافِرُونَ لَهُمْ عَذَابٌ شَد۪يدٌ', 'Ve yestecibullezine amenu ve amilus salihati ve yeziduhum min fadlih, vel kafirune lehum azabun şedid.', 'İman edip salihatı yapanların isteklerini kabul eder ve onlara lütfundan daha fazlasını verir. Kafirlere\" ise şiddetli bir azap vardır.', 'ويستجيب الذين امنوا وعملوا الصلحت ويزيدهم من فضله والكفرون لهم عذاب شديد'),
(4299, 42, 27, 'وَلَوْ بَسَطَ اللّٰهُ الرِّزْقَ لِعِبَادِه۪ لَبَغَوْا فِي الْاَرْضِ وَلٰكِنْ يُنَزِّلُ بِقَدَرٍ مَا يَشَٓاءُۜ اِنَّهُ بِعِبَادِه۪ خَب۪يرٌ بَص۪يرٌ', 'Ve lev besetallahur rızka li ibadihi le begav fil ardı ve lakin yunezzilu bi kaderin ma yeşau, innehu bi ibadihi habirun basir.', 'Eğer Allah,  kullarına rızkı genişletseydi,  kesinlikle yeryüzünde azarlardı. Fakat O,  dilediği kadarını indirir. Kuşkusuz O,  kullarının Her Şeyinden Haberdar Olan\'dır,  Her Şeyi Gören\'dir.', 'ولو بسط الله الرزق لعباده لبغوا في الارض ولكن ينزل بقدر ما يشا انه بعباده خبير بصير'),
(4300, 42, 28, 'وَهُوَ الَّذ۪ي يُنَزِّلُ الْغَيْثَ مِنْ بَعْدِ مَا قَنَطُوا وَيَنْشُرُ رَحْمَتَهُۜ  وَهُوَ الْوَلِيُّ الْحَم۪يدُ', 'Ve huvellezi yunezzilul gayse min ba\'di ma kanetu ve yenşuru rahmeteh, ve huvel veliyyul hamid.', 'O,  insanlar ümitsizliğe düştükten sonra yağmuru yağdıran ve rahmetini yayandır. Ve O,  Gerçek Gözetici\'dir,  Övgüye Değer Yegane Varlık\'tır.', 'وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد'),
(4301, 42, 29, 'وَمِنْ اٰيَاتِه۪ خَلْقُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَثَّ ف۪يهِمَا مِنْ دَٓابَّةٍۜ وَهُوَ عَلٰى جَمْعِهِمْ اِذَا يَشَٓاءُ قَد۪يرٌ۟', 'Ve min ayatihi halkus semavati vel ardı ve ma besse fihima min dabbeh, ve huve ala cem\'ihim iza yeşau kadir.', 'Göklerin ve yeryüzünün yaratılması ve o ikisinde[1] her canlıdan çoğaltıp yayması,  O\'nun ayetlerindendir.[2] O,  dilediği zaman onları toplamaya gücü yetendir.', 'ومن ايته خلق السموت والارض وما بث فيهما من دابة وهو علي جمعهم اذا يشا قدير'),
(4302, 42, 30, 'وَمَٓا اَصَابَكُمْ مِنْ مُص۪يبَةٍ فَبِمَا كَسَبَتْ اَيْد۪يكُمْ وَيَعْفُوا عَنْ كَث۪يرٍۜ', 'Ve ma esabekum min musibetin fe bi ma kesebet eydikum ve ya\'fu an kesir.', 'Size isabet eden musibet kendi ellerinizle yaptığınız şeyler yüzündendir. O,  çoğuna da engel oluyor.', 'وما اصابكم من مصيبة فبما كسبت ايديكم ويعفوا عن كثير'),
(4303, 42, 31, 'وَمَٓا اَنْتُمْ بِمُعْجِز۪ينَ فِي الْاَرْضِۚ وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَص۪يرٍ', 'Ve ma entum bi mu\'cizine fil ard, ve ma lekum min dunillahi min veliyyin ve la nasir.', 'Siz,  yeryüzünde aciz bırakabilecek olanlar değilsiniz. Sizin,  Allah\'tan başka bir veliniz[1] ve yardımcınız yoktur.', 'وما انتم بمعجزين في الارض وما لكم من دون الله من ولي ولا نصير'),
(4304, 42, 32, 'وَمِنْ اٰيَاتِهِ الْجَوَارِ فِي الْبَحْرِ كَالْاَعْلَامِۜ', 'Ve min ayatihil cevari fil bahri kel a\'lam.', 'Denizdeki dağ gibi akıp giden gemiler O\'nun ayetlerindendir.[1]', 'ومن ايته الجوار في البحر كالاعلم'),
(4305, 42, 33, 'اِنْ يَشَأْ يُسْكِنِ الرّ۪يحَ فَيَظْلَلْنَ رَوَاكِدَ عَلٰى ظَهْرِه۪ۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍۙ', 'İn yeşe\' yuskinir riha fe yazlelne revakide ala zahrih, inne fi zalike le ayatin li kulli sabbarin şekur.', 'Dilerse rüzgarı durdurur da denizin yüzünde kalakalırlar. Kuşkusuz bunda çok sabreden ve çok şükredenler için ayetler[1] vardır.', 'ان يشا يسكن الريح فيظللن رواكد علي ظهره ان في ذلك لايت لكل صبار شكور'),
(4306, 42, 34, 'اَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا وَيَعْفُ عَنْ كَث۪يرٍۘ', 'Ev yubıkhunne bima kesebu ve ya\'fu an kesir.', 'Veya yaptıkları şeylerden dolayı onları yok eder veya birçoğunu bağışlar.', 'او يوبقهن بما كسبوا ويعف عن كثير'),
(4307, 42, 35, 'وَيَعْلَمَ الَّذ۪ينَ يُجَادِلُونَ ف۪ٓي اٰيَاتِنَاۜ مَا لَهُمْ مِنْ مَح۪يصٍ', 'Ve ya\'lemellezine yucadilune fi ayatina, ma lehum min mahis.', 'Ayetlerimiz hakkında mücadele edenler,  kendileri için sığınacak bir yer olmadığını bilsinler.', 'ويعلم الذين يجدلون في ايتنا ما لهم من محيص'),
(4308, 42, 36, 'فَمَٓا اُو۫ت۪يتُمْ مِنْ شَيْءٍ فَمَتَاعُ الْحَيٰوةِ الدُّنْيَاۚ وَمَا عِنْدَ اللّٰهِ خَيْرٌ وَاَبْقٰى لِلَّذ۪ينَ اٰمَنُوا وَعَلٰى رَبِّهِمْ يَتَوَكَّلُونَۚ', 'Fe ma utitum min şey\'in fe meta\'ul hayatid dunya, ve ma ındallahi hayrun ve ebka lillezine amenu ve ala rabbihim yetevekkelun.', 'Size verilen her şey,  geçici dünya hayatının geçimliğidir. İman edip,  Rabb\'lerine tevekkül[1] edenlere Allah katından verilecek nimetler daha hayırlıdır ve daha kalıcıdır.', 'فما اوتيتم من شي فمتع الحيوة الدنيا وما عند الله خير وابقي للذين امنوا وعلي ربهم يتوكلون'),
(4309, 42, 37, 'وَالَّذ۪ينَ يَجْتَنِبُونَ كَـبَٓائِرَ الْاِثْمِ وَالْفَوَاحِشَ وَاِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَۚ', 'Vellezine yectenibune kebairel ismi vel fevahışe ve iza ma gadıbuhum yagfirun.', 'Onlar,  büyük günahlardan ve fahşadan[1] kaçınan ve öfkelendikleri zaman bağışlayan kimselerdir.', 'والذين يجتنبون كبير الاثم والفوحش واذا ما غضبوا هم يغفرون'),
(4310, 42, 38, 'وَالَّذ۪ينَ اسْتَجَابُوا لِرَبِّهِمْ وَاَقَامُوا الصَّلٰوةَۖ وَاَمْرُهُمْ شُورٰى بَيْنَهُمْۖ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَۚ', 'Vellezinestacabu li rabbihim ve ekamus salate ve emruhum şura beynehum ve mimma rezaknahum yunfikun.', 'Rabb\'lerinin çağrısına uyarlar ve salatı ikame[1] ederler. Onlar,  işlerini birbirlerine şura[2] ile yaparlar. Kendilerine verdiğimiz rızıktan infak[3] ederler.', 'والذين استجابوا لربهم واقاموا الصلوة وامرهم شوري بينهم ومما رزقنهم ينفقون'),
(4311, 42, 39, 'وَالَّذ۪ينَ اِذَٓا اَصَابَهُمُ الْبَغْيُ هُمْ يَنْتَصِرُونَ', 'Vellezine iza esabehumul bagyuhum yentesırun.', 'Bir haksızlığa,  zulme uğradıkları zaman,  yardımlaşırlar.', 'والذين اذا اصابهم البغي هم ينتصرون'),
(4312, 42, 40, 'وَجَزٰٓؤُ۬ا سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَاۚ فَمَنْ عَفَا وَاَصْلَحَ فَاَجْرُهُ عَلَى اللّٰهِۜ اِنَّهُ لَا يُحِبُّ الظَّالِم۪ينَ', 'Ve cezau seyyietin, seyyietun misluha, fe men afa ve asleha fe ecruhu alallah, innehu la yuhıbbuz zalimin.', 'Bir kötülüğün karşılığı o kötülük ölçüsündedir. Ama kim bağışlar ve düzeltici olursa artık onun karşılığı Allah\'a aittir. Kuşkusuz O,  haksızlık yapanları sevmez.', 'وجزوا سيية سيية مثلها فمن عفا واصلح فاجره علي الله انه لا يحب الظلمين'),
(4313, 42, 41, 'وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِه۪ فَاُو۬لٰٓئِكَ مَا عَلَيْهِمْ مِنْ سَب۪يلٍۜ', 'Ve le men intesare ba\'de zulmihi fe ulaike ma aleyhim min sebil.', 'Kim de haksızlığa uğradıktan sonra hakkını alırsa,  onun aleyhine bir yol tercih edilmez.', 'ولمن انتصر بعد ظلمه فاوليك ما عليهم من سبيل'),
(4314, 42, 42, 'اِنَّمَا السَّب۪يلُ عَلَى الَّذ۪ينَ يَظْلِمُونَ النَّاسَ وَيَبْغُونَ فِي الْاَرْضِ بِغَيْرِ الْحَقِّۜ  اُو۬لٰٓئِكَ لَهُمْ عَذَابٌ اَل۪يمٌ', 'İnnemes sebilu alellezine yazlimunen nase ve yebgune fil ardı bi gayril hakk, ulaike lehum azabun elim.', 'Fakat insanlara haksızlık yapanların ve yeryüzünde haksız yere zorbalık yapanların aleyhlerine bir yol tercih edilir. İşte onlar,  kendileri için acı bir azap olanlardır.', 'انما السبيل علي الذين يظلمون الناس ويبغون في الارض بغير الحق اوليك لهم عذاب اليم'),
(4315, 42, 43, 'وَلَمَنْ صَبَرَ وَغَفَرَ اِنَّ ذٰلِكَ لَمِنْ عَزْمِ الْاُمُورِ۟', 'Ve le men sabere ve gafere inne zalike le min azmil umur.', 'Ancak kim sabreder ve bağışlarsa,  büyüklük yapmış olur.', 'ولمن صبر وغفر ان ذلك لمن عزم الامور'),
(4316, 42, 44, 'وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِه۪ۜ وَتَرَى الظَّالِم۪ينَ لَمَّا رَاَوُا الْعَذَابَ يَقُولُونَ هَلْ اِلٰى مَرَدٍّ مِنْ سَب۪يلٍۚ', 'Ve men yudlilillahu fe ma lehu min veliyin min ba\'dih, ve terez zalimine lemma reevul azabe yekulune hel ila mereddin min sebil.', 'Allah,  kimi sapkınlıkta bırakırsa[1],  artık bunun ardından onun için bir veli[2] bulunmaz. Haksızlık yapanların,  azabı gördüklerinde: \"Acaba geri dönmenin bir yolu var mı?\" dediklerini göreceksin.', 'ومن يضلل الله فما له من ولي من بعده وتري الظلمين لما راوا العذاب يقولون هل الي مرد من سبيل'),
(4317, 42, 45, 'وَتَرٰيهُمْ يُعْرَضُونَ عَلَيْهَا خَاشِع۪ينَ مِنَ الذُّلِّ يَنْظُرُونَ مِنْ طَرْفٍ خَفِيٍّۜ وَقَالَ الَّذ۪ينَ اٰمَنُٓوا اِنَّ الْخَاسِر۪ينَ الَّذ۪ينَ خَسِرُٓوا اَنْفُسَهُمْ وَاَهْل۪يهِمْ يَوْمَ الْقِيٰمَةِۜ اَلَٓا اِنَّ الظَّالِم۪ينَ ف۪ي عَذَابٍ مُق۪يمٍ', 'Ve terahum yu\'redune aleyha haşiineminez zulli yenzurune min tarfin hafiy, ve kalellezine amenu innel hasirinellezine hasiru enfusehum ve ehlihim yevmel kıyameh, e la innez zalimine fi azabin mukim.', 'Onları,  aşağılanmalarından dolayı başları öne eğilmiş,  göz ucuyla çevrelerine bakarlarken ona[1] sunulduklarını göreceksin. İman edenler: \"Zarara uğrayanlar,  kendilerini ve taraftarlarını Kıyamet Günü zarara uğratmış olan kimselerdir.\" dediler. İyi bilin ki zalimler kalıcı bir azabın içindedirler.', 'وتريهم يعرضون عليها خشعين من الذل ينظرون من طرف خفي وقال الذين امنوا ان الخسرين الذين خسروا انفسهم واهليهم يوم القيمة الا ان الظلمين في عذاب مقيم'),
(4318, 42, 46, 'وَمَا كَانَ لَهُمْ مِنْ اَوْلِيَٓاءَ يَنْصُرُونَهُمْ مِنْ دُونِ اللّٰهِۜ وَمَنْ يُضْلِلِ اللّٰهُ فَمَا لَهُ مِنْ سَب۪يلٍۜ', 'Ve ma kane lehum min evliyae yensurunehum min dunillah. Ve men yudlilillahu fe ma lehu min sebil.', 'Onların,  kendilerine yardım edecek Allah\'tan başka velileri yoktur. Ve Allah kimi sapkınlıkta bırakırsa[1] artık onun için bir kurtuluş yolu yoktur.', 'وما كان لهم من اوليا ينصرونهم من دون الله ومن يضلل الله فما له من سبيل'),
(4319, 42, 47, 'اِسْتَج۪يبُوا لِرَبِّكُمْ مِنْ قَبْلِ اَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ مِنَ اللّٰهِۜ مَا لَكُمْ مِنْ مَلْجَاٍ يَوْمَئِذٍ وَمَا لَكُمْ مِنْ نَك۪يرٍ', 'İstecibu li rabbikum min kabli en ye\'tiye yevmun la meredde lehu minallah, ma lekum min melcein yevme izin ve ma lekum min nekir.', 'Allah tarafından geri döndürülmeyecek olan günün gelmesinden önce,  Rabb\'inizin çağrısına olumlu yanıt verin. İzin Günü[1],  sizin için bir sığınak yoktur. Sizin için kabul etmemek de yoktur.[2]', 'استجيبوا لربكم من قبل ان ياتي يوم لا مرد له من الله ما لكم من ملجا يوميذ وما لكم من نكير'),
(4320, 42, 48, 'فَاِنْ اَعْرَضُوا فَمَٓا اَرْسَلْنَاكَ عَلَيْهِمْ حَف۪يظاًۜ اِنْ عَلَيْكَ اِلَّا الْبَلَاغُۜ وَاِنَّٓا اِذَٓا اَذَقْنَا الْاِنْسَانَ مِنَّا رَحْمَةً فَرِحَ بِهَاۜ وَاِنْ تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ اَيْد۪يهِمْ فَاِنَّ الْاِنْسَانَ كَفُورٌ', 'Fe in a\'redu fe ma erselnake aleyhim hafiza, in aleyke illel belagu, ve inna iza ezaknal insane minna rahmeten feriha biha, ve in tusibhum seyyietun bi ma kaddemet eydihim fe innel insane kefur.', 'Buna rağmen eğer yüz çevirirlerse,  Biz,  seni onların üzerine bekçi olarak göndermedik. Senin üzerine düşen yalnızca çağrıda bulunmaktır. Biz,  insana tarafımızdan bir rahmet tattırdığımız zaman,  insan ona sevinir. Kendi yaptıklarından dolayı başına bir kötülük gelse,  işte o zaman insan kafir[1] kesilir.', 'فان اعرضوا فما ارسلنك عليهم حفيظا ان عليك الا البلغ وانا اذا اذقنا الانسن منا رحمة فرح بها وان تصبهم سيية بما قدمت ايديهم فان الانسن كفور'),
(4321, 42, 49, 'لِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ يَخْلُقُ مَا يَشَٓاءُۜ يَهَبُ لِمَنْ يَشَٓاءُ اِنَاثاً وَيَهَبُ لِمَنْ يَشَٓاءُ الذُّكُورَۙ', 'Lillahi mulkus semavati vel ard, yahluku ma yeşau, yehebu li men yeşau inasen ve yehebu li men yeşauz zukur.', 'Göklerin ve yeryüzünün egemenliği yalnız Allah\'a aittir. O,  dilediği şeyi yaratır. Dilediğine dişiler dilediğine de erkekler bahşeder.', 'لله ملك السموت والارض يخلق ما يشا يهب لمن يشا انثا ويهب لمن يشا الذكور'),
(4322, 42, 50, 'اَوْ يُزَوِّجُهُمْ ذُكْرَاناً وَاِنَاثاًۚ وَيَجْعَلُ مَنْ يَشَٓاءُ عَق۪يماًۜ اِنَّهُ عَل۪يمٌ قَد۪يرٌ', 'Ev yuzevvicuhum zukranen ve inasa, ve yec\'alu men yeşau akima, innehu alimun kadir.', 'Veya hem erkekler hem dişiler; onları çift yapar. Ve dilediğini kısır yapar. Kuşkusuz O,  Her Şeyi Bilen\'dir,  Her Şeye Gücü Yeten\'dir.', 'او يزوجهم ذكرانا وانثا ويجعل من يشا عقيما انه عليم قدير'),
(4323, 42, 51, 'وَمَا كَانَ لِبَشَرٍ اَنْ يُكَلِّمَهُ اللّٰهُ اِلَّا وَحْياً اَوْ مِنْ وَرَٓائِ۬ حِجَابٍ اَوْ يُرْسِلَ رَسُولاً فَيُوحِيَ بِـاِذْنِه۪ مَا يَشَٓاءُۜ اِنَّهُ عَلِيٌّ حَك۪يمٌ', 'Ve ma kane li beşerin en yukellimehullahu illa vahyen ev min verai hıcabin ev yursile resulen fe yuhıye bi iznihi ma yeşau, innehu aliyyun hakim.', 'Allah\'ın,  bir beşer ile konuşması söz konusu değildir. Ancak,  vahiy ile veya bir perde arkasından veya bir resul göndererek,  izni ile[1] dilediğini vahyetmesi dışında. Kuşkusuz O,  Çok Yüce\'dir,  En İyi Hüküm Veren\'dir.[2]', 'وما كان لبشر ان يكلمه الله الا وحيا او من وراي حجاب او يرسل رسولا فيوحي باذنه ما يشا انه علي حكيم'),
(4324, 42, 52, 'وَكَذٰلِكَ اَوْحَيْنَٓا اِلَيْكَ رُوحاً مِنْ اَمْرِنَاۜ مَا كُنْتَ تَدْر۪ي مَا الْكِتَابُ وَلَا الْا۪يمَانُ وَلٰكِنْ جَعَلْنَاهُ نُوراً نَهْد۪ي بِه۪ مَنْ نَشَٓاءُ مِنْ عِبَادِنَاۜ وَاِنَّكَ لَتَهْد۪ٓي اِلٰى صِرَاطٍ مُسْتَق۪يمٍۙ', 'Ve kezalike evhayna ileyke ruhan min emrina, ma kunte tedri mel kitabu ve lel imanu ve lakin cealnahu nuren nehdi bihi men neşau min ibadina, ve inneke le tehdi ila sıratın mustekim.', 'İşte böylece sana buyruğumuzdan[1] bir ruh[2] vahyettik. Sen kitap nedir,  iman nedir bilmezdin. Fakat onu,  kullarımızdan dilediğimiz kimseyi[3] doğru yola ileteceğimiz bir ışık yaptık. Kuşkusuz sen,  dosdoğru bir yola kılavuzluk etmektesin.', 'وكذلك اوحينا اليك روحا من امرنا ما كنت تدري ما الكتب ولا الايمن ولكن جعلنه نورا نهدي به من نشا من عبادنا وانك لتهدي الي صرط مستقيم'),
(4325, 42, 53, 'صِرَاطِ اللّٰهِ الَّذ۪ي لَهُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ اَلَٓا اِلَى اللّٰهِ تَص۪يرُ الْاُمُورُ', 'Sıratıllahillezi lehu ma fis semavati ve ma fil ard, e la ilallahi tesirul umur.', 'Göklerde ve yerde olanların kendisine ait olduğu Allah\'ın yoluna. İyi bilin ki bütün işler sonunda Allah\'a döner.', 'صرط الله الذي له ما في السموت وما في الارض الا الي الله تصير الامور'),
(4326, 43, 1, 'حٰمٓۜ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4327, 43, 2, 'وَالْكِتَابِ الْمُب۪ينِۙ', 'Vel kitabil mubini.', 'Apaçık Kitap\'a ant olsun ki!', 'والكتب المبين'),
(4328, 43, 3, 'اِنَّا جَعَلْنَاهُ قُرْءٰناً عَرَبِياًّ لَعَلَّكُمْ تَعْقِلُونَۚ', 'İnna cealnahu kur\'anen arabiyyen leallekum ta\'kılun.', 'Biz onu düşünüp anlayasınız diye Arapça bir kuran[1] yaptık.', 'انا جعلنه قرنا عربيا لعلكم تعقلون'),
(4329, 43, 4, 'وَاِنَّهُ ف۪ٓي اُمِّ الْكِتَابِ لَدَيْنَا لَعَلِيٌّ حَك۪يمٌۜ', 'Ve innehu fi ummil kitabi ledeyna le aliyyun hakim.', 'Kur\'an,  nezdimizde Ummu\'l Kitap\'tadır[1]. Gerçekten yücedir ve hakimdir.[2]', 'وانه في ام الكتب لدينا لعلي حكيم'),
(4330, 43, 5, 'اَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحاً اَنْ كُنْتُمْ قَوْماً مُسْرِف۪ينَ', 'E fe nadribu ankumuz zikre safhan en kuntum kavmen musrifin.', 'Siz,  israf eden[1] bir halk oldunuz diye,  size öğüt vermekten vaz mı geçelim?', 'افنضرب عنكم الذكر صفحا ان كنتم قوما مسرفين'),
(4331, 43, 6, 'وَكَمْ اَرْسَلْنَا مِنْ نَبِيٍّ فِي الْاَوَّل۪ينَ', 'Ve kem erselna min nebiyin fil evvelin.', 'Öncekiler için de nice nebiler gönderdik.', 'وكم ارسلنا من نبي في الاولين'),
(4332, 43, 7, 'وَمَا يَأْت۪يهِمْ مِنْ نَبِيٍّ اِلَّا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Ve ma yetihim min nebiyin illa kanu bihi yestehziun.', 'Onlar,  kendilerine gelen her nebiyi mutlaka alaya alıyorlardı.', 'وما ياتيهم من نبي الا كانوا به يستهزون'),
(4333, 43, 8, 'فَاَهْلَكْـنَٓا اَشَدَّ مِنْهُمْ بَطْشاً وَمَضٰى مَثَلُ الْاَوَّل۪ينَ', 'Fe ehlekna eşedde minhum batşen ve meda meselul evvelin.', 'Biz,  güç bakımından onlardan daha üstün olanları yok ettik. Geçmişe ait örnek haline geldiler.', 'فاهلكنا اشد منهم بطشا ومضي مثل الاولين'),
(4334, 43, 9, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ الْعَز۪يزُ الْعَل۪يمُۙ', 'Ve le in seeltehum men halakas semavati vel arda le yekulunne halakahunnel azizul alim.', 'Müşriklere: \"Gökleri ve yeri kim yarattı?\" diye sorsan,  kesinlikle: \"Onları Mutlak Üstün Olan,  Her Şeyi Bilen yarattı.\" diyecekler.', 'ولين سالتهم من خلق السموت والارض ليقولن خلقهن العزيز العليم'),
(4335, 43, 10, 'اَلَّذ۪ي جَعَلَ لَكُمُ الْاَرْضَ مَهْداً وَجَعَلَ لَكُمْ ف۪يهَا سُبُلاً لَعَلَّكُمْ تَهْتَدُونَۚ', 'Ellezi cealekumul arda mehden ve cealelekum fiha subulen leallekum tehtedun.', 'O,  yeryüzünü sizin için beşik[1] yaptı. Orada sizin için yollar yaptı[2]. Umulur ki hidayete eresiniz.[3]', 'الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون'),
(4336, 43, 11, 'وَالَّذ۪ي نَزَّلَ مِنَ السَّمَٓاءِ مَٓاءً بِقَدَرٍۚ فَاَنْشَرْنَا بِه۪ بَلْدَةً مَيْتاًۚ كَذٰلِكَ تُخْرَجُونَ', 'Vellezi nezzele mines semai maenbi kader, fe enşerna bihi beldetenmeyten, kezalike tuhrecun.', 'O,  bir ölçüye göre gökten su indirendir. Sonra,  onunla ölü bir beldeyi canlandırdık. İşte siz de böyle yeniden diriltileceksiniz.', 'والذي نزل من السما ما بقدر فانشرنا به بلدة ميتا كذلك تخرجون'),
(4337, 43, 12, 'وَالَّذ۪ي خَلَقَ الْاَزْوَاجَ كُلَّهَا وَجَعَلَ لَكُمْ مِنَ الْفُلْكِ وَالْاَنْعَامِ مَا تَرْكَبُونَۙ', 'Vellezi halakal ezvace kullehave ceale lekum minel fulki vel enami ma terkebun.', 'Her şeyi çift yarattı.[1] Gemilerden ve hayvanlardan binekler kıldı.', 'والذي خلق الازوج كلها وجعل لكم من الفلك والانعم ما تركبون'),
(4338, 43, 13, 'لِتَسْتَوُ۫ا عَلٰى ظُهُورِه۪ ثُمَّ تَذْكُرُوا نِعْمَةَ رَبِّكُمْ اِذَا اسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا سُبْحَانَ الَّذ۪ي سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهُ مُقْرِن۪ينَۙ', 'Li testevu ala zuhurihi summe tezkuru ni\'mete rabbikum izesteveytum aleyhi, ve tekulu subhanellezi sehhare lena haza ve ma kunna lehu mukrinin.', 'Üzerlerine binip,  onlardan yararlanınca,  Rabb\'inizin verdiği nimetleri anarak: \"Bunları,  hizmetimize veren Allah ne yücedir; yoksa bizim bunlara gücümüz yetmezdi.\" deyin.', 'لتستوا علي ظهوره ثم تذكروا نعمة ربكم اذا استويتم عليه وتقولوا سبحن الذي سخر لنا هذا وما كنا له مقرنين'),
(4339, 43, 14, 'وَاِنَّٓا اِلٰى رَبِّنَا لَمُنْقَلِبُونَ', 'Ve inna ila rabbina le munkalibun.', 'Kuşkusuz biz,  sonunda Rabb\'imize döneceğiz.', 'وانا الي ربنا لمنقلبون'),
(4340, 43, 15, 'وَجَعَلُوا لَهُ مِنْ عِبَادِه۪ جُزْءاًۜ اِنَّ الْاِنْسَانَ لَكَفُورٌ مُب۪ينٌۜ', 'Ve cealu lehu min ibadihi cuz\'a, innel insane le kefurun mubin.', 'Bazı kullarını,  O\'nun bir parçası saydılar.[1] Gerçekten,  o insan[2],  açıkça nankörlük etmektedir.', 'وجعلوا له من عباده جزا ان الانسن لكفور مبين'),
(4341, 43, 16, 'اَمِ اتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَاَصْفٰيكُمْ بِالْبَن۪ينَ۟', 'Emittehaze mimma yahluku benatin ve asfakum bil benin.', 'Yoksa O,  yarattıklarından kızları kendisine ayırıp,  oğulları size mi bıraktı?', 'ام اتخذ مما يخلق بنات واصفيكم بالبنين'),
(4342, 43, 17, 'وَاِذَا بُشِّرَ اَحَدُهُمْ بِمَا ضَرَبَ لِلرَّحْمٰنِ مَثَلاً ظَلَّ وَجْهُهُ مُسْوَداًّ وَهُوَ كَظ۪يمٌ', 'Ve iza buşşire ehaduhum bi ma darabe lir rahmani meselen zalle vechuhu musvedden ve huve kezim.', 'Onlardan biri,  kendisine,  Rahman\'a layık gördüğü kız çocuğu haberi verildiği zaman,  yüzü simsiyah kesilir,  içini üzüntü kaplar.', 'واذا بشر احدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم'),
(4343, 43, 18, 'اَوَمَنْ يُنَشَّؤُ۬ا فِي الْحِلْيَةِ وَهُوَ فِي الْخِصَامِ غَيْرُ مُب۪ينٍ', 'E ve men yuneşşeu fil hılyeti ve huve fil hısami gayru mubin.', 'Ve süs içinde büyütülmekten başka işe yaramayanı mı verdi diye hayıflanır!', 'اومن ينشوا في الحلية وهو في الخصام غير مبين'),
(4344, 43, 19, 'وَجَعَلُوا الْمَلٰٓئِكَةَ الَّذ۪ينَ هُمْ عِبَادُ الرَّحْمٰنِ اِنَاثاًۜ اَشَهِدُوا خَلْقَهُمْۜ سَتُكْتَبُ شَهَادَتُهُمْ وَيُسْـَٔلُونَ', 'Ve cealul melaiketellezine hum ibadur rahmani inasa, e şehidu halkahum, setuktebu şehadetuhum ve yus\'elun.', 'Onlar,  Rahman\'ın kulları olan melekleri dişi saydılar. Onların yaratılışlarına tanık mı oldular? Onların bu tanıklıkları yazılacak ve sorguya çekileceklerdir.', 'وجعلوا المليكة الذين هم عبد الرحمن انثا اشهدوا خلقهم ستكتب شهدتهم ويسلون'),
(4345, 43, 20, 'وَقَالُوا لَوْ شَٓاءَ الرَّحْمٰنُ مَا عَبَدْنَاهُمْۜ مَا لَهُمْ بِذٰلِكَ مِنْ عِلْمٍۗ اِنْ هُمْ اِلَّا يَخْرُصُونَۜ', 'Ve kalu lev şaer rahmanu ma abednahum, ma lehum bi zalike min ilmin in hum illa yahrusun.', '\"Eğer Rahman dileseydi,  biz onlara kulluk etmezdik.\" dediler. Onların bu konuda hiçbir bilgileri yoktur. Onlar yalnızca saçmalıyorlar.', 'وقالوا لو شا الرحمن ما عبدنهم ما لهم بذلك من علم ان هم الا يخرصون'),
(4346, 43, 21, 'اَمْ اٰتَيْنَاهُمْ كِتَاباً مِنْ قَبْلِه۪ فَهُمْ بِه۪ مُسْتَمْسِكُونَ', 'Em ateynahum kitaben min kablihi fe hum bihi mustemsikun.', 'Yoksa ondan önce,  onlara kitap verdik de onlar,  ona mı dayanıyorlar?', 'ام اتينهم كتبا من قبله فهم به مستمسكون'),
(4347, 43, 22, 'بَلْ قَالُٓوا اِنَّا وَجَدْنَٓا اٰبَٓاءَنَا عَلٰٓى اُمَّةٍ وَاِنَّا عَلٰٓى اٰثَارِهِمْ مُهْتَدُونَ', 'Bel kalu inna vecedna abaena ala ummetin ve inna ala asarihim muhtedun.', 'Hayır! Dediler ki: \"Doğrusu,  biz,  atalarımızı bir ümmet[1] üzerinde bulduk,  biz de onların izinden gidiyoruz.', 'بل قالوا انا وجدنا ابانا علي امة وانا علي اثرهم مهتدون'),
(4348, 43, 23, 'وَكَذٰلِكَ مَٓا اَرْسَلْنَا مِنْ قَبْلِكَ ف۪ي قَرْيَةٍ مِنْ نَذ۪يرٍ اِلَّا قَالَ مُتْرَفُوهَٓاۙ اِنَّا وَجَدْنَٓا اٰبَٓاءَنَا عَلٰٓى اُمَّةٍ وَاِنَّا عَلٰٓى اٰثَارِهِمْ مُقْتَدُونَ', 'Ve kezalike ma erselna min kablike fi karyetin min nezirin illa kale mutrefuha inna vecedna abaena ala ummetin ve inna ala asarihim muktedun.', 'Tıpkı bunun gibi,  senden önce de ne zaman bir beldeye uyarıcı gönderdiysek,  oranın refah içinde olanları: \"Biz,  atalarımızı bir ümmet üzerinde bulduk. Biz de kesinlikle onların izinden gidiyoruz.\" dediler.', 'وكذلك ما ارسلنا من قبلك في قرية من نذير الا قال مترفوها انا وجدنا ابانا علي امة وانا علي اثرهم مقتدون'),
(4349, 43, 24, 'قَالَ اَوَلَوْ جِئْتُكُمْ بِاَهْدٰى مِمَّا وَجَدْتُمْ عَلَيْهِ اٰبَٓاءَكُمْۜ قَالُٓوا اِنَّا بِمَٓا اُرْسِلْتُمْ بِه۪ كَافِرُونَ', 'Kale e ve lev ci\'tukum bi ehda mimma vecedtum aleyhi abaekum, kalu inna bi ma ursıltum bihi kafirun.', 'Size,  \"Atalarınızı üzerinde bulduğunuz yoldan daha doğrusunu getirmiş olsam da mı?\" deyince,  onlar: \"Biz,  sizinle gönderilene Kafirlik[1] ediyoruz.\" dediler.', 'قل اولو جيتكم باهدي مما وجدتم عليه اباكم قالوا انا بما ارسلتم به كفرون'),
(4350, 43, 25, 'فَانْتَقَمْنَا مِنْهُمْ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّب۪ينَ۟', 'Fentekamna minhum fanzur keyfe kane akıbetul mukezzibin.', 'Bunun üzerine onlara hak ettikleri cezayı verdik. Yalanlayanların sonlarının nasıl olduğuna bir bak!', 'فانتقمنا منهم فانظر كيف كان عقبة المكذبين'),
(4351, 43, 26, 'وَاِذْ قَالَ اِبْرٰه۪يمُ لِاَب۪يهِ وَقَوْمِه۪ٓ اِنَّن۪ي بَرَٓاءٌ مِمَّا تَعْبُدُونَۙ', 'Ve iz kale ibrahimu li ebihi ve kavmihi inneni beraun mimma ta\'budun.', 'Bir zamanlar İbrahim,  babasına ve halkına: \"Ben sizin kulluk ettiklerinizden uzağım demişti.\"', 'واذ قال ابرهيم لابيه وقومه انني برا مما تعبدون'),
(4352, 43, 27, 'اِلَّا الَّذ۪ي فَطَرَن۪ي فَاِنَّهُ سَيَهْد۪ينِ', 'İllellezi fatarani fe innehu se yehdin.', '\"Ancak fıtratımı[1] belirleyen başka. Kuşkusuz O beni doğru yola iletecektir.\"', 'الا الذي فطرني فانه سيهدين'),
(4353, 43, 28, 'وَجَعَلَهَا كَلِمَةً بَاقِيَةً ف۪ي عَقِبِه۪ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve cealeha kelimeten bakıyeten fi akıbihi leallehum yerciun.', 'İbrahim,  gerçeğe yönelmeleri umuduyla takdir edilmiş hükmü gelecek nesiller için de kalıcı bir ilke yaptı.', 'وجعلها كلمة باقية في عقبه لعلهم يرجعون'),
(4354, 43, 29, 'بَلْ مَتَّعْتُ هٰٓؤُ۬لَٓاءِ وَاٰبَٓاءَهُمْ حَتّٰى جَٓاءَهُمُ الْحَقُّ وَرَسُولٌ مُب۪ينٌ', 'Bel metta\'tu haulai ve abaehum hatta caehumul hakku ve resulun mubin.', 'Doğrusu bunları ve atalarını,  kendilerine Hakk ve onu açıklayıcı bir resul gelinceye kadar yararlandırıp yaşattım.', 'بل متعت هولا واباهم حتي جاهم الحق ورسول مبين'),
(4355, 43, 30, 'وَلَمَّا جَٓاءَهُمُ الْحَقُّ قَالُوا هٰذَا سِحْرٌ وَاِنَّا بِه۪ كَافِرُونَ', 'Ve lemma cae humul hakku kalu haza sihrun ve inna bihi kafirun.', 'Onlara,  Hakk geldiği zaman: \"Bu bir büyüdür. Biz onu yalanlayanlarız.\" dediler.', 'ولما جاهم الحق قالوا هذا سحر وانا به كفرون'),
(4356, 43, 31, 'وَقَالُوا لَوْلَا نُزِّلَ هٰذَا الْقُرْاٰنُ عَلٰى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظ۪يمٍ', 'Ve kalu lev la nuzzile hazel kur\'anu ala raculin minel karyeteyni azim.', '\"Bu Kur\'an\'ın,  iki şehrin birinden,  bir büyük adama[1] indirilmesi gerekmez miydi?\" dediler.', 'وقالوا لولا نزل هذا القران علي رجل من القريتين عظيم'),
(4357, 43, 32, 'اَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَۜ نَحْنُ قَسَمْنَا بَيْنَهُمْ مَع۪يشَتَهُمْ فِي الْحَيٰوةِ الدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ لِيَتَّخِذَ بَعْضُهُمْ بَعْضاً سُخْرِياًّۜ وَرَحْمَتُ رَبِّكَ خَيْرٌ مِمَّا يَجْمَعُونَ', 'E hum yaksimune rahmete rabbik, nahnu kasemna beynehum maişetehum fil hayatid dunyave refa\'na ba\'dahum fevka ba\'dın derecatin li yettehıze ba\'duhum ba\'dan suhriyya, ve rahmetu rabbike hayrun mimma yecmaun.', 'Rabb\'inin rahmetini onlar mı dağıtıyorlar? Dünya hayatındaki geçimliklerini Biz paylaştırdık. Birbirlerine işlerini gördürsünler diye,  onların bir kısmını bir kısmının üzerine derecelerle yükselttik. Rabb\'inin rahmeti onların biriktirdiklerinden daha hayırlıdır.[1]', 'اهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحيوة الدنيا ورفعنا بعضهم فوق بعض درجت ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون'),
(4358, 43, 33, 'وَلَوْلَٓا اَنْ يَكُونَ النَّاسُ اُمَّةً وَاحِدَةً لَجَعَلْنَا لِمَنْ يَكْفُرُ بِالرَّحْمٰنِ لِبُيُوتِهِمْ سُقُفاً مِنْ فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَۙ', 'Ve lev la en yekunen nasu ummeten vahıdeten le cealna limen yekfuru bir rahmani li buyutihim sukufen min fıddatin ve mearice aleyha yazherune.', 'Şayet insanlar,  tek bir ümmet[1] haline gelmeyecek olsalardı, [2] Rahman\'ı küfreden[3] kimselerin,  evlerinin tavanlarını ve merdivenlerini gümüşten yapardık.', 'ولولا ان يكون الناس امة وحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون'),
(4359, 43, 34, 'وَلِبُيُوتِهِمْ اَبْوَاباً وَسُرُراً عَلَيْهَا يَتَّكِؤُ۫نَۙ', 'Ve li buyutihim ebvaben ve sururen aleyha yettekiun.', 'Ve evlerinin kapılarını ve üzerine oturup yaslandıkları koltuklarını da.', 'ولبيوتهم ابوبا وسررا عليها يتكون'),
(4360, 43, 35, 'وَزُخْرُفاًۜ وَاِنْ كُلُّ ذٰلِكَ لَمَّا مَتَاعُ الْحَيٰوةِ الدُّنْيَاۜ وَالْاٰخِرَةُ عِنْدَ رَبِّكَ لِلْمُتَّق۪ينَ۟', 'Ve zuhrufa, ve in kullu zalike lemma metaul hayatid dunya, vel ahiretu inde rabbike lil muttekin.', 'Ve altına boğardık. Bunların tamamı,  dünya hayatının kazanımından başka bir şey değildir.[1] Ahiret ise Rabb\'inin yanında,  yalnızca takva[2] sahipleri içindir.', 'وزخرفا وان كل ذلك لما متع الحيوة الدنيا والاخرة عند ربك للمتقين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4361, 43, 36, 'وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمٰنِ نُقَيِّضْ لَهُ شَيْطَاناً فَهُوَ لَهُ قَر۪ينٌ', 'Ve men ya\'şu an zikrir rahmani nukayyıd lehu şeytanen fe huve lehu karin.', 'Her kim Rahman\'ın öğüdüne karşı duyarsız olursa,  Biz ona bir şeytan[1] salarız. Artık şeytan onun yakın arkadaşı olur.', 'ومن يعش عن ذكر الرحمن نقيض له شيطنا فهو له قرين'),
(4362, 43, 37, 'وَاِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ السَّب۪يلِ وَيَحْسَبُونَ اَنَّهُمْ مُهْتَدُونَ', 'Ve innehum le yasuddunehum anis sebili ve yahsebune ennehum muhtedun.', 'Şeytanlar,  onları doğru yoldan saptırdıkları halde,  onlar hala kendilerinin doğru yolda olduklarını sanırlar.', 'وانهم ليصدونهم عن السبيل ويحسبون انهم مهتدون'),
(4363, 43, 38, 'حَتّٰٓى اِذَا جَٓاءَنَا قَالَ يَا لَيْتَ بَيْن۪ي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ الْقَر۪ينُ', 'Hatta iza caena kale ya leyte beyni ve beyneke bu\'del meşrikayni fe bi\'sel karin.', 'Nihayet o[1] Bize geldiği zaman: \"Keşke seninle aramız iki doğu uzaklığı kadar uzak olsaydı.\" der. Öyleyse bu ne kötü bir arkadaşlıktır.', 'حتي اذا جانا قال يليت بيني وبينك بعد المشرقين فبيس القرين'),
(4364, 43, 39, 'وَلَنْ يَنْفَعَكُمُ الْيَوْمَ اِذْ ظَلَمْتُمْ اَنَّكُمْ فِي الْعَذَابِ مُشْتَرِكُونَ', 'Ve len yenfeakumul yevme iz zalemtum ennekum fil azabi muşterikun.', 'Bugün,  pişmanlığınız kesinlikle size bir yarar sağlamaz. Kendinize haksızlık yaptınız. Siz azaba da ortaksınız.', 'ولن ينفعكم اليوم اذ ظلمتم انكم في العذاب مشتركون'),
(4365, 43, 40, 'اَفَاَنْتَ تُسْمِــعُ الصُّمَّ اَوْ تَهْدِي الْعُمْيَ وَمَنْ كَانَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'E fe ente tusmius summe ev tehdil umye ve men kane fi dalalin mubin.', 'O halde sağıra sen mi işittireceksin? Veya köre ve apaçık sapkınlıkta olana doğru yolu gösterebilir misin?', 'افانت تسمع الصم او تهدي العمي ومن كان في ضلل مبين'),
(4366, 43, 41, 'فَاِمَّا نَذْهَبَنَّ بِكَ فَاِنَّا مِنْهُمْ مُنْتَقِمُونَۙ', 'Fe imma nezhebenne bike fe inna minhum muntekımun.', 'Biz,  seni bu dünyadan alıp götürsek bile,  onlara hak ettikleri cezayı mutlaka vereceğiz.', 'فاما نذهبن بك فانا منهم منتقمون'),
(4367, 43, 42, 'اَوْ نُرِيَنَّكَ الَّذ۪ي وَعَدْنَاهُمْ فَاِنَّا عَلَيْهِمْ مُقْتَدِرُونَ', 'Ev nuriyennekellezi vaadnahum fe inna aleyhim muktedirun.', 'Veya onları uyardığımız azabı sana gösteririz. Elbette Bizim onlara gücümüz yeter.', 'او نرينك الذي وعدنهم فانا عليهم مقتدرون'),
(4368, 43, 43, 'فَاسْتَمْسِكْ بِالَّـذ۪ٓي اُو۫حِيَ اِلَيْكَۚ اِنَّكَ عَلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'Festemsik billezi uhıye ileyk, inneke ala sıratın mustekim.', 'Öyleyse sen,  sana vahyedilene sarılmaya bak. Kuşkusuz sen dosdoğru bir yol üzerindesin.', 'فاستمسك بالذي اوحي اليك انك علي صرط مستقيم'),
(4369, 43, 44, 'وَاِنَّهُ لَذِكْرٌ لَكَ وَلِقَوْمِكَۚ وَسَوْفَ تُسْـَٔلُونَ', 'Ve innehu le zikrun leke ve li kavmik, ve sevfe tus\'elun.', 'Kuşkusuz o sana ve halkına bir öğüttür. Ondan sorulacaksınız.', 'وانه لذكر لك ولقومك وسوف تسلون'),
(4370, 43, 45, 'وَسْـَٔلْ مَنْ اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رُسُلِنَاۗ اَجَعَلْنَا مِنْ دُونِ الرَّحْمٰنِ اٰلِهَةً يُعْبَدُونَ۟', 'Ves\'el men erselna min kablike min rusulina e cealna min dunir rahmani aliheten yu\'bedun.', 'Senden önce kendilerine Resul gönderdiklerimize sor. Biz,  Rahman\'dan başka kulluk[1] edilecek ilahlar kılmış mıyız?', 'وسل من ارسلنا من قبلك من رسلنا اجعلنا من دون الرحمن الهة يعبدون'),
(4371, 43, 46, 'وَلَقَدْ اَرْسَلْنَا مُوسٰى بِاٰيَاتِنَٓا اِلٰى فِرْعَوْنَ وَمَلَا۬ئِه۪ فَقَالَ اِنّ۪ي رَسُولُ رَبِّ الْعَالَم۪ينَ', 'Ve lekad erselna musa bi ayatina ila fir\'avne ve melaihi fe kale inni resulu rabbil alemin.', 'Ant olsun ki Biz Musa\'yı ayetlerimizle[1] Firavun\'a ve onun melelerine[2] gönderdik: \"Ben alemlerin Rabb\'inin Resulüyüm.\" dedi.', 'ولقد ارسلنا موسي بايتنا الي فرعون وملايه فقال اني رسول رب العلمين'),
(4372, 43, 47, 'فَلَمَّا جَٓاءَهُمْ بِاٰيَاتِنَٓا اِذَا هُمْ مِنْهَا يَضْحَكُونَ', 'Fe lemma caehum bi ayatina izahum minha yadhakun.', 'Fakat Musa onlara ayetlerimizle[1] gelince,  onlar hemen alay etmeye başladılar.', 'فلما جاهم بايتنا اذا هم منها يضحكون'),
(4373, 43, 48, 'وَمَا نُر۪يهِمْ مِنْ اٰيَةٍ اِلَّا هِيَ اَكْبَرُ مِنْ اُخْتِهَاۘ وَاَخَذْنَاهُمْ بِالْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve ma nurihim min ayetin illa hiye ekberu min uhtiha ve ehaznahum bil azabi leallehum yerciun.', 'Onlara gösterdiğimiz her ayet[1],  bir öncekinden daha büyüktü. Ders alırlar diye onlara kimi sıkıntılar yaşattık.', 'وما نريهم من اية الا هي اكبر من اختها واخذنهم بالعذاب لعلهم يرجعون'),
(4374, 43, 49, 'وَقَالُوا يَٓا اَيُّهَ السَّاحِرُ ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِنْدَكَ اِنَّـنَا لَمُهْتَدُونَ', 'Ve kalu ya eyyuhes sahırud\'u lena rabbeke bima ahide ındeke innena le muhtedun.', '\"Ey sihirbaz![1] Rabb\'inin sana verdiği sözün[2] hatırına bizim için dua et. Kuşkusuz biz doğru yola uyarız.\" dediler.', 'وقالوا يايه الساحر ادع لنا ربك بما عهد عندك اننا لمهتدون'),
(4375, 43, 50, 'فَلَمَّا كَشَفْنَا عَنْهُمُ الْعَذَابَ اِذَا هُمْ يَنْكُثُونَ', 'Fe lemma keşefna an humul azabe iza hum yenkusun.', 'Fakat onları azaptan kurtarınca da hemen sözlerinden döndüler.', 'فلما كشفنا عنهم العذاب اذا هم ينكثون'),
(4376, 43, 51, 'وَنَادٰى فِرْعَوْنُ ف۪ي قَوْمِه۪ قَالَ يَا قَوْمِ اَلَيْسَ ل۪ي مُلْكُ مِصْرَ وَهٰذِهِ الْاَنْهَارُ تَجْر۪ي مِنْ تَحْت۪يۚ اَفَلَا تُبْصِرُونَۜ', 'Ve nada fir\'avnu fi kavmihi kale ya kavmi e leyse li mulku mısra ve hazihil enharu tecri min tahti, e fe la tubsirun.', 'Firavun,  halkına seslendi: \"Ey halkım! Mısır\'ın egemenliği ve ayaklarımın altından akıp giden şu nehirler benim değil mi? Görmüyor musunuz?\"[1]', 'ونادي فرعون في قومه قال يقوم اليس لي ملك مصر وهذه الانهر تجري من تحتي افلا تبصرون'),
(4377, 43, 52, 'اَمْ اَنَا۬ خَيْرٌ مِنْ هٰذَا الَّذ۪ي هُوَ مَه۪ينٌ وَلَا يَكَادُ يُب۪ينُ', 'Em ene hayrun min hazellezi huve mehinun ve la yekadu yubin.', '\"Yoksa ben,  ne istediğini bilmeyen şu zavallıdan daha hayırlı değil miyim?\"', 'ام انا خير من هذا الذي هو مهين ولا يكاد يبين'),
(4378, 43, 53, 'فَلَوْلَٓا اُلْقِيَ عَلَيْهِ اَسْوِرَةٌ مِنْ ذَهَبٍ اَوْ جَٓاءَ مَعَهُ الْمَلٰٓئِكَةُ مُقْتَرِن۪ينَ', 'Fe lev la ulkıye aleyhi esviretun min zehebin ev cae meahul melaiketu mukterinin.', '\"Öyleyse ona takılmış altından bilezikler[1] olmalı veya yanında kendisine eşlik eden melekler gelmeli değil miydi?\"', 'فلولا القي عليه اسورة من ذهب او جا معه المليكة مقترنين'),
(4379, 43, 54, 'فَاسْتَخَفَّ قَوْمَهُ فَاَطَاعُوهُۜ اِنَّهُمْ كَانُوا قَوْماً فَاسِق۪ينَ', 'Festehaffe kavmehu fe atauh, innehum kanu kavmen fasikin.', 'Firavun halkını etkisi altına aldı. Bunun üzerine halkı ona itaat etti. Onlar fasık[1] bir toplum oldular.', 'فاستخف قومه فاطاعوه انهم كانوا قوما فسقين'),
(4380, 43, 55, 'فَلَمَّٓا اٰسَفُونَا انْتَقَمْنَا مِنْهُمْ فَاَغْرَقْنَاهُمْ اَجْمَع۪ينَۙ', 'Fe lemma asefunentekamna minhum fe agraknahum ecmain.', 'Böylece Bize asilik yaptılar. Biz de onları cezalandırdık. Topluca suda boğduk.', 'فلما اسفونا انتقمنا منهم فاغرقنهم اجمعين'),
(4381, 43, 56, 'فَجَعَلْنَاهُمْ سَلَفاً وَمَثَلاً لِلْاٰخِر۪ينَ۟', 'Fe cealnahum selefen ve meselen lil ahırin.', 'Böylece onları gelecek nesiller için ibret verici bir örnek kıldık.', 'فجعلنهم سلفا ومثلا للاخرين'),
(4382, 43, 57, 'وَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً اِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', 'Ve lemma duribebnu meryeme meselen iza kavmuke minhu yasıddun.', 'Meryem oğlu örnek olarak anlatılınca,  halkın hemen yaygara yaptı;', 'ولما ضرب ابن مريم مثلا اذا قومك منه يصدون'),
(4383, 43, 58, 'وَقَالُٓوا ءَاٰلِهَتُنَا خَيْرٌ اَمْ هُوَۜ مَا ضَرَبُوهُ لَكَ اِلَّا جَدَلاًۜ بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'Ve kalu e alihetuna hayrun em huve, ma darebuhu leke illa cedela, bel hum kavmun hasımun.', 'Ve: \"Bizim ilahlarımız mı daha hayırlıdır,  yoksa o[1] mu?\" dediler. Bu örneği,  yalnızca sana muhalefet etmek için verdiler. Doğrusu onlar çok düşmanca davranan bir halktır.', 'وقالوا الهتنا خير ام هو ما ضربوه لك الا جدلا بل هم قوم خصمون'),
(4384, 43, 59, 'اِنْ هُوَ اِلَّا عَبْدٌ اَنْعَمْنَا عَلَيْهِ وَجَعَلْنَاهُ مَثَلاً لِبَن۪ٓي اِسْرَٓائ۪ـلَۜ', 'İn huve illa abdun en\'amna aleyhi ve cealnahu meselen li beni israil.', 'O[1] kendisine nimet verdiğimiz ve İsrailoğulları\'na örnek kıldığımız bir kuldur.', 'ان هو الا عبد انعمنا عليه وجعلنه مثلا لبني اسريل'),
(4385, 43, 60, 'وَلَوْ نَشَٓاءُ لَجَعَلْنَا مِنْكُمْ مَلٰٓئِكَةً فِي الْاَرْضِ يَخْلُفُونَ', 'Ve lev neşau le cealna minkum melaiketen fil ardı yahlufun.', 'Eğer isteseydik sizi yeryüzünde birbirinizin ardı sıra gelen melekler[1] yapardık.', 'ولو نشا لجعلنا منكم مليكة في الارض يخلفون'),
(4386, 43, 61, 'وَاِنَّهُ لَعِلْمٌ لِلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَاتَّبِعُونِۜ هٰذَا صِرَاطٌ مُسْتَق۪يمٌ', 'Ve innehu le ilmun lis saati, fe la temterunne biha vettebiuni, haza sıratun mustekim.', 'Kuşkusuz o, [1] kesinlikle o Sa\'at[2] için bir bilgidir. Sakın ondan kuşku duymayın! Bana uyun. Bu,  dosdoğru yoldur.', 'وانه لعلم للساعة فلا تمترن بها واتبعون هذا صرط مستقيم'),
(4387, 43, 62, 'وَلَا يَصُدَّنَّكُمُ الشَّيْطَانُۚ اِنَّهُ لَكُمْ عَدُوٌّ مُب۪ينٌ', 'Ve la yasuddennekumuş şeytan, innehu lekum aduvvun mubin.', 'Sakın şeytan sizi alıkoymasın. Kuşkusuz o,  sizin için apaçık bir düşmandır.', 'ولا يصدنكم الشيطن انه لكم عدو مبين'),
(4388, 43, 63, 'وَلَمَّا جَٓاءَ ع۪يسٰى بِالْبَيِّنَاتِ قَالَ قَدْ جِئْتُكُمْ بِالْحِكْمَةِ وَلِاُبَيِّنَ لَكُمْ بَعْضَ الَّذ۪ي تَخْتَلِفُونَ ف۪يهِۚ فَاتَّقُوا اللّٰهَ وَاَط۪يعُونِ', 'Ve lemma cae isa bil beyyinati kale kad ci\'tukum bil hikmeti ve li ubeyyine lekum ba\'dellezi tahtelifune fih, fettekullahe ve etiuni.', 'Îsa,  apaçık beyyinelerle[1] geldiği zaman: \"Ben size Hikmeti[2] getirdim. Hakkında anlaşmazlığa düştüğünüz şeylerin bir kısmını size açıklamak için geldim. O halde Allah için takvalı olun ve bana itaat edin.\" dedi.', 'ولما جا عيسي بالبينت قال قد جيتكم بالحكمة ولابين لكم بعض الذي تختلفون فيه فاتقوا الله واطيعون'),
(4389, 43, 64, 'اِنَّ اللّٰهَ هُوَ رَبّ۪ي وَرَبُّكُمْ فَاعْبُدُوهُۜ هٰذَا صِرَاطٌ مُسْتَق۪يمٌ', 'İnnellahe huve rabbi ve rabbukum fa\'buduh, haza sıratun mustekim.', 'Allah,  benim de sizin de Rabb\'inizdir. Öyleyse O\'na kulluk[1] edin! Bu,  dosdoğru yoldur.', 'ان الله هو ربي وربكم فاعبدوه هذا صرط مستقيم'),
(4390, 43, 65, 'فَاخْتَلَفَ الْاَحْزَابُ مِنْ بَيْنِهِمْۚ فَوَيْلٌ لِلَّذ۪ينَ ظَلَمُوا مِنْ عَذَابِ يَوْمٍ اَل۪يمٍ', 'Fahtelefel ahzabu min beynihim, fe veylun lillezine zalemu min azabi yevmin elim.', 'Sonra gruplar kendi aralarında anlaşmazlığa düştüler. Artık acı veren günün azabından dolayı haksızlık yapanların vay haline!', 'فاختلف الاحزاب من بينهم فويل للذين ظلموا من عذاب يوم اليم'),
(4391, 43, 66, 'هَلْ يَنْظُرُونَ اِلَّا السَّاعَةَ اَنْ تَأْتِيَهُمْ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'Hel yenzurune illes saate en te\'tiyehum bagteten ve hum la yeş\'urun.', 'O Sa\'at\'ın[1],  farkında değillerken,  ansızın onlara gelmesinden başka bir şey mi bekliyorlar?', 'هل ينظرون الا الساعة ان تاتيهم بغتة وهم لا يشعرون'),
(4392, 43, 67, 'اَلْاَخِلَّٓاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ اِلَّا الْمُتَّق۪ينَۜ‌۟', 'El ehillau yevme izin ba\'duhum li ba\'din aduvvun illel muttekin.', 'İzin Günü[1],  muttakiler[2] dışında,  dostlar[3] birbirlerine düşmandırlar.', 'الاخلا يوميذ بعضهم لبعض عدو الا المتقين'),
(4393, 43, 68, 'يَا عِبَادِ لَا خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلَٓا اَنْتُمْ تَحْزَنُونَۚ', 'Ya ibadi la havfun aleykumul yevme ve la entum tahzenun.', '\"Ey kullarım! Bugün size korku yoktur. Siz üzülmeyeceksiniz.\"', 'يعباد لا خوف عليكم اليوم ولا انتم تحزنون'),
(4394, 43, 69, 'اَلَّذ۪ينَ اٰمَنُوا بِاٰيَاتِنَا وَكَانُوا مُسْلِم۪ينَۚ', 'Ellezine amenu bi ayatina ve kanu muslimin.', '\"Ayetlerimize iman edenler ve teslim olanlarsınız.\"', 'الذين امنوا بايتنا وكانوا مسلمين'),
(4395, 43, 70, 'اُدْخُلُوا الْجَنَّةَ اَنْتُمْ وَاَزْوَاجُكُمْ تُحْبَرُونَ', 'Udhulul cennete entum ve ezvacukum tuhberun .', 'Cennete girin. Siz ve eşleriniz[1] en iyi şekilde ağırlanacaksınız.\"', 'ادخلوا الجنة انتم وازوجكم تحبرون'),
(4396, 43, 71, 'يُطَافُ عَلَيْهِمْ بِصِحَافٍ مِنْ ذَهَبٍ وَاَكْوَابٍۚ وَف۪يهَا مَا تَشْتَه۪يهِ الْاَنْفُسُ وَتَلَذُّ الْاَعْيُنُۚ وَاَنْتُمْ ف۪يهَا خَالِدُونَۚ', 'Yutafu aleyhim bi sıhafin min zehebin ve ekvab, ve fiha ma teştehihil enfusu ve telezzul a\'yun, ve entum fiha halidun.', 'Onların etraflarında altından tepsiler ve bardaklarla dolaşılır. Orada,  canların çektiği,  gözlerin hoşlandığı her şey vardır. Ve siz orada sürekli kalacaksınız.', 'يطاف عليهم بصحاف من ذهب واكواب وفيها ما تشتهيه الانفس وتلذ الاعين وانتم فيها خلدون'),
(4397, 43, 72, 'وَتِلْكَ الْجَنَّةُ الَّت۪ٓي اُو۫رِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ', 'Ve tilkel cennetulleti uristumuha bi ma kuntum ta\'melun.', 'İşte bu,  yaptıklarınıza karşılık,  mirasçı kılındığınız Cennet\'tir', 'وتلك الجنة التي اورثتموها بما كنتم تعملون'),
(4398, 43, 73, 'لَكُمْ ف۪يهَا فَاكِهَةٌ  كَث۪يرَةٌ مِنْهَا تَأْكُلُونَ', 'Lekum fiha fakihetun kesiretun minha te\'kulun.', 'Sizin için orada yiyeceğiniz pek çok meyve vardır.', 'لكم فيها فكهة كثيرة منها تاكلون'),
(4399, 43, 74, 'اِنَّ الْمُجْرِم۪ينَ ف۪ي عَذَابِ جَهَنَّمَ خَالِدُونَۚ', 'İnnel mucrimine fi azabi cehenneme halidun.', 'Kuşkusuz mücrimler[1],  Cehennem azabında sürekli kalacak olanlardır.', 'ان المجرمين في عذاب جهنم خلدون'),
(4400, 43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ ف۪يهِ مُبْلِسُونَۚ', 'La yufetteru anhum ve hum fihi mublisun.', 'Onlardan azap hafifletilmez. Onlar,  orada umutlarını kesmiş olanlardır.', 'لا يفتر عنهم وهم فيه مبلسون'),
(4401, 43, 76, 'وَمَا ظَلَمْنَاهُمْ وَلٰكِنْ كَانُوا هُمُ الظَّالِم۪ينَ', 'Ve ma zalemnahum ve lakin kanu humuz zalimin.', 'Biz onlara haksızlık yapmadık. Fakat onlar kendi kendilerine haksızlık yaptılar.', 'وما ظلمنهم ولكن كانوا هم الظلمين'),
(4402, 43, 77, 'وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَۜ قَالَ اِنَّكُمْ مَاكِثُونَ', 'Ve nadev ya maliku li yakdi aleyna rabbuk, kale innekum makisun.', '\"Ey malik![1] Rabb\'in bizim aleyhimize hüküm versin.\"[2] diye seslenirler. \"Siz böyle kalacaksınız.\" dedi.', 'ونادوا يملك ليقض علينا ربك قال انكم مكثون'),
(4403, 43, 78, 'لَقَدْ جِئْنَاكُمْ بِالْحَقِّ وَلٰكِنَّ اَكْثَرَكُمْ لِلْحَقِّ كَارِهُونَ', 'Lekad ci\'nakum bil hakkı ve lakinne ekserekum lil hakkı karihun.', 'Ant olsun ki size hakkı[1] getirdik. Ancak çoğunuz haktan hoşlanmadınız.', 'لقد جينكم بالحق ولكن اكثركم للحق كرهون'),
(4404, 43, 79, 'اَمْ اَبْرَمُٓوا اَمْراً فَاِنَّا مُبْرِمُونَۚ', 'Em ebremu emren fe inna mubrimun.', 'Yoksa onlar kesin karar mı verdiler? Biz de kesin kararlıyız!', 'ام ابرموا امرا فانا مبرمون'),
(4405, 43, 80, 'اَمْ يَحْسَبُونَ اَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوٰيهُمْۜ  بَلٰى وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', 'Em yahsebune enna la nesmeu sırrehum ve necvahum, bela ve rusuluna ledeyhim yektubun.', 'Yoksa onların sırlarını ve fısıltılarını duymadığımızı mı sanıyorlar? Hayır! Onların yanlarında bulunan elçilerimiz her şeyi kaydediyorlar.', 'ام يحسبون انا لا نسمع سرهم ونجويهم بلي ورسلنا لديهم يكتبون'),
(4406, 43, 81, 'قُلْ اِنْ كَانَ لِلرَّحْمٰنِ وَلَدٌۗ فَاَنَا۬ اَوَّلُ الْعَابِد۪ينَ', 'Kul in kane lir rahmani veledun fe ena evvelul abidin.', 'De ki: \"Eğer Rahman\'ın çocuğu olsaydı,  ona ilk ben kulluk ederdim.\"[1]', 'قل ان كان للرحمن ولد فانا اول العبدين'),
(4407, 43, 82, 'سُبْحَانَ رَبِّ السَّمٰوَاتِ وَالْاَرْضِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ', 'Subhane rabbis semavati vel ardı rabbil arşi amma yasıfun.', 'Göklerin ve yerin Rabb\'i; arşın Rabb\'i onların niteledikleri şeylerden münezzehtir.', 'سبحن رب السموت والارض رب العرش عما يصفون'),
(4408, 43, 83, 'فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتّٰى يُلَاقُوا يَوْمَهُمُ الَّذ۪ي يُوعَدُونَ', 'Fe zerhum yahudu ve yel\'abu hatta yulaku yevme humullezi yu\'adun.', 'Artık onları kendi hallerine bırak! Uyarıldıkları güne kavuşuncaya değin boş şeylerle oyalanıp dursunlar.', 'فذرهم يخوضوا ويلعبوا حتي يلقوا يومهم الذي يوعدون'),
(4409, 43, 84, 'وَهُوَ الَّذ۪ي فِي السَّمَٓاءِ اِلٰهٌ وَفِي الْاَرْضِ اِلٰهٌۜ وَهُوَ الْحَك۪يمُ الْعَل۪يمُ', 'Ve huvellezi fis semai ilahun ve fil ardı ilah, ve huvel hakimul alim.', 'Gökte de yerde de İlah olan O\'dur. Ve O,  En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'وهو الذي في السما اله وفي الارض اله وهو الحكيم العليم'),
(4410, 43, 85, 'وَتَبَارَكَ الَّذ۪ي لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۚ وَعِنْدَهُ عِلْمُ السَّاعَةِۚ وَاِلَيْهِ تُرْجَعُونَ', 'Ve tebarekellezi lehu mulkus semavati vel\'ardı ve ma beynehuma, ve indehu ilmus saah, ve ileyhi turceun.', 'Göklerin,  yerin ve aralarındaki her şeyin mülkiyeti[1] kendisinin olan Zat ne kutludur. O Sa\'at\'in bilgisi yalnızca O\'nun yanındadır. O\'na döndürüleceksiniz.', 'وتبارك الذي له ملك السموت والارض وما بينهما وعنده علم الساعة واليه ترجعون'),
(4411, 43, 86, 'وَلَا يَمْلِكُ الَّذ۪ينَ يَدْعُونَ مِنْ دُونِهِ الشَّفَاعَةَ اِلَّا مَنْ شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ', 'Ve la yemlikullezine yed\'une min dunihiş şefate illa men şehide bil hakkı ve hum ya\'lemun.', 'Onların,  O\'nun yanı sıra dua ettikleri kimseler şefaate güç yetiremezler. Bunu ancak gerçeğe tanıklık edenler kavrar.[2]', 'ولا يملك الذين يدعون من دونه الشفعة الا من شهد بالحق وهم يعلمون'),
(4412, 43, 87, 'وَلَئِنْ سَاَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللّٰهُ فَاَنّٰى يُؤْفَكُونَۙ', 'Ve le in se\'eltehum men halakahum le yekulunnallahu fe enna yu\'fekun.', 'Onlara,  kendilerini kimin yarattığını sorsan,  kesinlikle \"Allah\" diyeceklerdir. Buna rağmen nasıl başka ilahlara yöneliyorlar.', 'ولين سالتهم من خلقهم ليقولن الله فاني يوفكون'),
(4413, 43, 88, 'وَق۪يلِه۪ يَا رَبِّ اِنَّ هٰٓؤُ۬لَٓاءِ قَوْمٌ لَا يُؤْمِنُونَۢ', 'Ve kilihi ya rabbi inne haulai kavmun la yu\'minun.', 'Nebi\'nin sözü: \"Ey Rabb\'im! Bunlar,  iman etmeyen bir halktır.\"', 'وقيله يرب ان هولا قوم لا يومنون'),
(4414, 43, 89, 'فَاصْفَحْ عَنْهُمْ وَقُلْ سَلَامٌۜ فَسَوْفَ يَعْلَمُونَ', 'Fasfah anhum ve kul selam, fe sevfe ya\'lemun.', 'Onları kendi hallerine bırak: \"Selam olsun.\" de. Yakında gerçeği görecekler.', 'فاصفح عنهم وقل سلم فسوف يعلمون'),
(4415, 44, 1, 'حٰمٓۜ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4416, 44, 2, 'وَالْكِتَابِ الْمُب۪ينِۙ', 'Vel kitabil mubin.', 'Apaçık olan Kitap\'a ant olsun.', 'والكتب المبين'),
(4417, 44, 3, 'اِنَّٓا اَنْزَلْنَاهُ ف۪ي لَيْلَةٍ مُبَارَكَةٍ اِنَّا كُنَّا مُنْذِر۪ينَ', 'İnna enzelnahu fi leyletin mubareketin inna kunna munzirin.', 'Onu kutlu bir gecede indirdik. Kuşkusuz Biz,  uyaranlarız.', 'انا انزلنه في ليلة مبركة انا كنا منذرين'),
(4418, 44, 4, 'ف۪يهَا يُفْرَقُ كُـلُّ اَمْرٍ حَـك۪يمٍۜ', 'Fiha yufreku kullu emrin hakim.', 'Kararlaştırılmış işlerin hepsi,  onda ayırt edilir.', 'فيها يفرق كل امر حكيم'),
(4419, 44, 5, 'اَمْراً مِنْ عِنْدِنَاۜ اِنَّا كُنَّا مُرْسِل۪ينَۚ', 'Emren min indina inna kunna mursilin.', 'Katımızdan bir buyruk olarak. Kuşkusuz Biz resul göndericiyiz.', 'امرا من عندنا انا كنا مرسلين'),
(4420, 44, 6, 'رَحْمَةً مِنْ رَبِّكَۜ اِنَّهُ هُوَ السَّم۪يعُ الْعَل۪يمُۙ', 'Rahmeten min rabbik, innehu huves semiul alim.', 'Rabb\'inden bir rahmet olarak. Kuşkusuz O,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'رحمة من ربك انه هو السميع العليم'),
(4421, 44, 7, 'رَبِّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۢ اِنْ كُنْتُمْ مُوقِن۪ينَ', 'Rabbis semavati vel ardı ve ma beynehuma, in kuntum mukinin.', 'Eğer kesin olarak inanıyorsanız bilin ki O göklerin,  yerin ve ikisinin arasındakilerin Rabb\'idir.', 'رب السموت والارض وما بينهما ان كنتم موقنين'),
(4422, 44, 8, 'لَٓا اِلٰهَ اِلَّا هُوَ يُحْـي۪ وَيُم۪يتُۜ رَبُّكُمْ وَرَبُّ اٰبَٓائِكُمُ الْاَوَّل۪ينَ', 'La ilahe illa huve yuhyi ve yumit, rabbukumve rabbu abaikumul evvelin.', 'Ondan başka ilah[1] yoktur. Diriltir ve öldürür. Sizin ve sizden önceki atalarınızın Rabb\'idir.', 'لا اله الا هو يحي ويميت ربكم ورب ابايكم الاولين'),
(4423, 44, 9, 'بَلْ هُمْ ف۪ي شَكٍّ يَلْعَبُونَ', 'Bel hum fi şekkin yel\'abun.', 'Hayır! Onlar,  kuşku içinde eğlenip duruyorlar.', 'بل هم في شك يلعبون'),
(4424, 44, 10, 'فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَٓاءُ بِدُخَانٍ مُب۪ينٍۙ', 'Fertekib yevme te\'tis semau bi duhanin mubin.', 'Artık göğün,  apaçık bir duman getireceği günü bekle.', 'فارتقب يوم تاتي السما بدخان مبين'),
(4425, 44, 11, 'يَغْشَى النَّاسَۜ هٰذَا عَذَابٌ اَل۪يمٌ', 'Yagşan nas, haza azabun elim.', 'İnsanları sarıp kuşatacak. İşte bu can yakıcı bir azaptır.', 'يغشي الناس هذا عذاب اليم'),
(4426, 44, 12, 'رَبَّـنَا اكْشِفْ عَنَّا الْعَذَابَ اِنَّا مُؤْمِنُونَ', 'Rabbenekşif annel azabe inna mu\'minun.', '\"Rabb\'imiz! Azabı bizden kaldır. Kuşkusuz biz inananlarız.\"', 'ربنا اكشف عنا العذاب انا مومنون'),
(4427, 44, 13, 'اَنّٰى لَهُمُ الذِّكْرٰى وَقَدْ جَٓاءَهُمْ رَسُولٌ مُب۪ينٌۙ', 'Enna lehumuz zikra ve kad caehum resulun mubin.', 'Nerede öğüt almak! Oysaki onlara apaçık bir resul gelmişti.', 'اني لهم الذكري وقد جاهم رسول مبين'),
(4428, 44, 14, 'ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌۢ', 'Summe tevellev anhu ve kalu muallemun mecnun.', '\"Öğretilmiş bir deli.\" dediler. Ve ondan yüz çevirdiler.', 'ثم تولوا عنه وقالوا معلم مجنون'),
(4429, 44, 15, 'اِنَّا كَاشِفُوا الْعَذَابِ قَل۪يلاً اِنَّكُمْ عَٓائِدُونَۢ', 'İnna kaşiful azabi kalilen innekum aidun.', 'Biz,  azabı biraz kaldırsak,  siz kesinlikle dönersiniz!', 'انا كاشفوا العذاب قليلا انكم عايدون'),
(4430, 44, 16, 'يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرٰىۚ اِنَّا مُنْتَقِمُونَ', 'Yevme nebtışul batşetel kubra inna muntekimun.', 'En büyük yakalayışla yakalayacağımız gün,  kuşkusuz Biz,  mutlaka hesap görenleriz.', 'يوم نبطش البطشة الكبري انا منتقمون'),
(4431, 44, 17, 'وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَٓاءَهُمْ رَسُولٌ كَر۪يمٌۙ', 'Ve lekad fetenna kablehum kavme fir\'avne ve caehum resulun kerim.', 'Ant olsun Biz,  onlardan önce Firavun halkını fitnelendirdik.[1] Onlara çok şerefli bir resul gelmişti.', 'ولقد فتنا قبلهم قوم فرعون وجاهم رسول كريم'),
(4432, 44, 18, 'اَنْ اَدُّٓوا اِلَيَّ عِبَادَ اللّٰهِۜ اِنّ۪ي لَكُمْ رَسُولٌ اَم۪ينٌۙ', 'En eddu ileyye ibadallah, inni lekum resulun emin.', '\"Allah\'ın kullarını bana verin.[1] Ben sizin için güvenilir bir resulüm.\"', 'ان ادوا الي عباد الله اني لكم رسول امين'),
(4433, 44, 19, 'وَاَنْ لَا تَعْلُوا عَلَى اللّٰهِۚ اِنّ۪ٓي اٰت۪يكُمْ بِسُلْطَانٍ مُب۪ينٍۚ', 'Ve en la ta\'lu alallah, inniatikum bi sultanin mubin.', '\"Allah\'a karşı ululuk taslamayın. Kuşkusuz ben,  size açıkça görevlendirilmiş biri olarak geliyorum.\"', 'وان لا تعلوا علي الله اني اتيكم بسلطن مبين'),
(4434, 44, 20, 'وَاِنّ۪ي عُذْتُ بِرَبّ۪ي وَرَبِّكُمْ اَنْ تَرْجُمُونِۘ', 'Ve inni uztu bi rabbi ve rabbikumen tercumuni.', '\"Ben,  beni taşlamanızdan,  sizin de Rabb\'iniz olan Rabb\'ime sığındım.\"', 'واني عذت بربي وربكم ان ترجمون'),
(4435, 44, 21, 'وَاِنْ لَمْ تُؤْمِنُوا ل۪ي فَاعْتَزِلُونِ', 'Ve in lem tu\'minu li fa\'teziluni.', '\"Eğer bana inanmıyorsanız,  artık yolumdan çekilin.\"', 'وان لم تومنوا لي فاعتزلون'),
(4436, 44, 22, 'فَدَعَا رَبَّهُٓ  اَنَّ هٰٓؤُ۬لَٓاءِ قَوْمٌ مُجْرِمُونَ', 'Fe dea rabbehu enne haulai kavmun mucrimun.', '\"Bunlar,  suç işleyen bir toplumdur.\" diye Rabb\'ine yakardı.', 'فدعا ربه ان هولا قوم مجرمون'),
(4437, 44, 23, 'فَاَسْرِ بِعِبَاد۪ي لَيْلاً اِنَّكُمْ مُتَّبَعُونَۙ', 'Fe esri bi ibadi leylen innekum muttebeun.', '\"Haydi,  kullarımla geceleyin yola çık. Siz takip edileceksiniz!\"', 'فاسر بعبادي ليلا انكم متبعون'),
(4438, 44, 24, 'وَاتْرُكِ الْبَحْرَ رَهْواًۜ اِنَّهُمْ جُنْدٌ مُغْرَقُونَ', 'Vetrukil bahre rehva, innehum cundun mugrekun.', '\"Denizi olduğu hal üzere bırak.[1] Onlar,  boğulacak olan bir ordudur.\"', 'واترك البحر رهوا انهم جند مغرقون'),
(4439, 44, 25, 'كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍۙ', 'Kem tereku min cennatin ve uyun.', 'Onlar,  bahçelerden,  pınarlardan nicelerini geride bıraktılar.', 'كم تركوا من جنت وعيون'),
(4440, 44, 26, 'وَزُرُوعٍ وَمَقَامٍ كَر۪يمٍۙ', 'Ve zuruin ve makamin kerim.', 'Ve ekinler,  itibarlı makamlar.', 'وزروع ومقام كريم'),
(4441, 44, 27, 'وَنَعْمَةٍ كَانُوا ف۪يهَا فَاكِه۪ينَۙ', 'Ve na\'metin kanu fiha fakihin.', 'Ve sefa sürdükleri nice nimetler.', 'ونعمة كانوا فيها فكهين'),
(4442, 44, 28, 'كَذٰلِكَ۠ وَاَوْرَثْنَاهَا قَوْماً اٰخَر۪ينَ', 'Kezalik, ve evresnaha kavmen aharin.', 'Böylece,  sonraki halkı onlara mirasçı kıldık.', 'كذلك واورثنها قوما اخرين'),
(4443, 44, 29, 'فَمَا بَكَتْ عَلَيْهِمُ السَّمَٓاءُ وَالْاَرْضُ وَمَا كَانُوا مُنْظَر۪ينَ۟', 'Fe ma beket aleyhimus semau vel ardu ve ma kanu munzarin.', 'Onlara ne gök ağladı ne de yer. Ve onlara fırsat da verilmedi.', 'فما بكت عليهم السما والارض وما كانوا منظرين'),
(4444, 44, 30, 'وَلَقَدْ نَجَّيْنَا بَن۪ٓي اِسْرَٓائ۪لَ مِنَ الْعَذَابِ الْمُه۪ينِۙ', 'Ve lekad necceyna beni israile minel azabil muhin.', 'Ant olsun ki İsrailoğulları\'nı o alçaltıcı azaptan Biz kurtardık.', 'ولقد نجينا بني اسريل من العذاب المهين'),
(4445, 44, 31, 'مِنْ فِرْعَوْنَۜ اِنَّهُ كَانَ عَالِياً مِنَ الْمُسْرِف۪ينَ', 'Min fir\'avn, innehu kane aliyen minel musrifin.', 'Firavun\'un zulmünden. Kuşkusuz o,  müsriflerdendi.[1]', 'من فرعون انه كان عاليا من المسرفين'),
(4446, 44, 32, 'وَلَقَدِ اخْتَرْنَاهُمْ عَلٰى عِلْمٍ عَلَى الْعَالَم۪ينَۚ', 'Ve lekadihternahum ala ilmin alel alemin.', 'Ant olsun ki onları[1] bilerek diğer alemler üzerine tercih ettik.[2]', 'ولقد اخترنهم علي علم علي العلمين'),
(4447, 44, 33, 'وَاٰتَيْنَاهُمْ مِنَ الْاٰيَاتِ مَا ف۪يهِ بَلٰٓؤٌا مُب۪ينٌ', 'Ve ateynahum minel ayati ma fihi belaun mubin.', 'Onlara,  içinde apaçık bela[1] olan ayetlerden verdik.', 'واتينهم من الايت ما فيه بلوا مبين'),
(4448, 44, 34, 'اِنَّ هٰٓؤُ۬لَٓاءِ لَيَقُولُونَۙ', 'İnne haulai le yekulun.', 'Bunlar[1] kesinlikle diyorlar ki:', 'ان هولا ليقولون'),
(4449, 44, 35, 'اِنْ هِيَ اِلَّا مَوْتَتُنَا الْاُو۫لٰى وَمَا نَحْنُ بِمُنْشَر۪ينَ', 'İn hiye illa mevtetunel ulave ma nahnu bi munşerin.', '\"Biz yalnızca öleceğiz. Tekrar diriltilecek değiliz.\"', 'ان هي الا موتتنا الاولي وما نحن بمنشرين'),
(4450, 44, 36, 'فَأْتُوا بِاٰبَٓائِنَٓا اِنْ كُنْتُمْ صَادِق۪ينَ', 'Fe\'tu bi abaina in kuntum sadikin.', '\"Eğer doğru söylüyorsanız haydi,  ölmüş atalarımızı bize geri getirin.\"', 'فاتوا باباينا ان كنتم صدقين'),
(4451, 44, 37, 'اَهُمْ خَيْرٌ اَمْ قَوْمُ تُبَّعٍۙ وَالَّذ۪ينَ مِنْ قَبْلِهِمْۜ اَهْلَكْنَاهُمْۘ اِنَّهُمْ كَانُوا مُجْرِم۪ينَ', 'E hum hayrun em kavmu tubbein vellezine min kablihim, ehleknahum innehum kanu mucrimin.', 'Bunlar mı daha hayırlıdır[1] yoksa Tubba halkı[2] mi? Ya da daha önceki kimseler mi? Biz onları yok ettik. Onlar mücrimlerdendiler.', 'اهم خير ام قوم تبع والذين من قبلهم اهلكنهم انهم كانوا مجرمين'),
(4452, 44, 38, 'وَمَا خَلَقْنَا السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَا لَاعِب۪ينَ', 'Ve ma halaknes semavati vel arda ve ma beynehuma laibin.', 'Biz; gökleri,  yeryüzünü ve ikisinin arasında bulunanları oyun olsun diye yaratmadık.', 'وما خلقنا السموت والارض وما بينهما لعبين'),
(4453, 44, 39, 'مَا خَلَقْنَاهُمَٓا اِلَّا بِالْحَقِّ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Ma halaknahuma illa bil hakkı ve lakinne ekserehum la ya\'lemun.', 'İkisini de yalnızca hakk[1] olarak yarattık. Fakat onların çoğu bilmiyorlar.[2]', 'ما خلقنهما الا بالحق ولكن اكثرهم لا يعلمون'),
(4454, 44, 40, 'اِنَّ يَوْمَ الْفَصْلِ م۪يقَاتُهُمْ اَجْمَع۪ينَۙ', 'İnne yevmel faslı mikatuhum ecmain.', 'Ayrışma Günü[1],  onların hepsinin kararlaştırılmış bir araya gelme zamanıdır.', 'ان يوم الفصل ميقتهم اجمعين'),
(4455, 44, 41, 'يَوْمَ لَا يُغْن۪ي مَوْلًى عَنْ مَوْلًى شَيْـٔاً وَلَا هُمْ يُنْصَرُونَۙ', 'Yevme la yugni mevlen an mevlen şey\'en ve la hum yunsarun.', 'O gün,  hiçbir yakının,  yakınına bir yararı olmaz.[1] Onlar,  yardım da olunmazlar.', 'يوم لا يغني مولي عن مولي شيا ولا هم ينصرون'),
(4456, 44, 42, 'اِلَّا مَنْ رَحِمَ اللّٰهُۜ اِنَّهُ هُوَ الْعَز۪يزُ الرَّح۪يمُ۟', 'İlla men rahimallah, innehu huvel azizur rahim.', 'Ancak Allah\'ın rahmet ettiği kimseler hariç. Kuşkusuz O,  Mutlak Üstün Olan\'dır,  Rahmeti Kesintisiz\'dir.', 'الا من رحم الله انه هو العزيز الرحيم'),
(4457, 44, 43, 'اِنَّ شَجَرَتَ الزَّقُّومِۙ', 'İnne şeceretez zakkum.', 'Zakkum ağacı[1],', 'ان شجرت الزقوم'),
(4458, 44, 44, 'طَعَامُ الْاَث۪يمِۚۛ', 'Taamul esim.', 'Günahkarların yemeğidir.', 'طعام الاثيم'),
(4459, 44, 45, 'كَالْمُهْلِۚۛ يَغْل۪ي فِي الْبُطُونِۙ', 'Kel muhl, yagli fil butun.', 'Erimiş maden gibi karınlarında kaynar.', 'كالمهل يغلي في البطون'),
(4460, 44, 46, 'كَغَلْيِ الْحَم۪يمِ', 'Ke galyil hamim.', 'Kaynar suyun kaynaması gibi.', 'كغلي الحميم'),
(4461, 44, 47, 'خُذُوهُ فَاعْتِلُوهُ اِلٰى سَوَٓاءِ الْجَح۪يمِۚ', 'Huzuhu fa\'tiluhu ila sevail cahim.', '\"Onu tutun! Cehennem\'in ortasına sürükleyin.\"', 'خذوه فاعتلوه الي سوا الجحيم'),
(4462, 44, 48, 'ثُمَّ صُبُّوا فَوْقَ رَأْسِه۪ مِنْ عَذَابِ الْحَم۪يمِۜ', 'Summe subbu fevka re\'sihi min azabil hamim.', '\"Sonra başına azap olarak kaynar su dökün.\"', 'ثم صبوا فوق راسه من عذاب الحميم'),
(4463, 44, 49, 'ذُقْۙ ۚ اِنَّكَ اَنْتَ الْعَز۪يزُ الْكَر۪يمُ', 'Zuk, inneke entel azizul kerim.', 'Tat bakalım! Hani sen gerçekten çok güçlü ve şerefli biriydin![1]', 'ذق انك انت العزيز الكريم'),
(4464, 44, 50, 'اِنَّ هٰذَا مَا كُنْتُمْ بِه۪ تَمْتَرُونَ', 'İnne haza ma kuntum bihi temterun.', 'Bu,  sizin kendisinden kuşku duyduğunuz şeydir.', 'ان هذا ما كنتم به تمترون'),
(4465, 44, 51, 'اِنَّ الْمُتَّق۪ينَ ف۪ي مَقَامٍ اَم۪ينٍۙ', 'İnnel muttekine fi makamin emin.', 'Kuşkusuz takva sahipleri güvenli bir yerde olacaklar;', 'ان المتقين في مقام امين'),
(4466, 44, 52, 'ف۪ي جَنَّاتٍ وَعُيُونٍۚ', 'Fi cennatin ve uyun.', 'Bahçelerde ve pınar başlarında.', 'في جنت وعيون'),
(4467, 44, 53, 'يَلْبَسُونَ مِنْ سُنْدُسٍ وَاِسْتَبْرَقٍ مُتَقَابِل۪ينَۚ', 'Yelbesune min sundusin ve istebrakın mutekabilin.', 'İpekten ve atlastan elbiseler giyerler,  karşılıklı otururlar.', 'يلبسون من سندس واستبرق متقبلين'),
(4468, 44, 54, 'كَذٰلِكَ۠ وَزَوَّجْنَاهُمْ بِحُورٍ ع۪ينٍۜ', 'Kezalik, ve zevvecnahum bi hurin in.', 'İşte böyle. Ve onları güzel gözlü hurilerle[1] eşleştirdik.', 'كذلك وزوجنهم بحور عين'),
(4469, 44, 55, 'يَدْعُونَ ف۪يهَا بِكُلِّ فَاكِهَةٍ اٰمِن۪ينَۙ', 'Yed\'une fiha bi kulli fakihetin aminin.', 'Orada güven içinde her türlü meyveden isterler.', 'يدعون فيها بكل فكهة امنين'),
(4470, 44, 56, 'لَا يَذُوقُونَ ف۪يهَا الْمَوْتَ اِلَّا الْمَوْتَةَ الْاُو۫لٰىۚ وَوَقٰيهُمْ عَذَابَ الْجَح۪يمِۙ', 'La yezukune fihel mevte illel mevtetel ula, ve vekahum azabel cahim.', 'Orada bir daha ölümü tatmazlar. Onlar Cehennem azabından korunmuştur.', 'لا يذوقون فيها الموت الا الموتة الاولي ووقيهم عذاب الجحيم'),
(4471, 44, 57, 'فَضْلاً مِنْ رَبِّكَۜ ذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُ', 'Fadlen min rabbik, zalike huvel fevzul azim.', 'Bunlar senin Rabb\'inden bir armağandır. İşte bu,  en büyük kurtuluştur.', 'فضلا من ربك ذلك هو الفوز العظيم'),
(4472, 44, 58, 'فَاِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'Fe innema yessernahu bi lisanike leallehum yetezekkerun.', 'İşte Biz,  onu senin dilinle kolaylaştırdık. Umulur ki onlar öğüt alırlar.', 'فانما يسرنه بلسانك لعلهم يتذكرون'),
(4473, 44, 59, 'فَارْتَقِبْ اِنَّهُمْ مُرْتَقِبُونَ', 'Fertekib innehum murtekıbun.', 'Artık gözetle! Onlar da gözetleyenlerdir.', 'فارتقب انهم مرتقبون'),
(4474, 45, 1, 'حٰمٓۜ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4475, 45, 2, 'تَنْز۪يلُ الْـكِتَابِ مِنَ اللّٰهِ الْعَز۪يزِ الْحَك۪يمِ', 'Tenzilul kitabi minallahil azizil hakim.', 'Bu Kitap\'ın indirilmesi,  Mutlak Üstün Olan,  En İyi Hüküm Veren Allah tarafındandır.', 'تنزيل الكتب من الله العزيز الحكيم'),
(4476, 45, 3, 'اِنَّ فِي السَّمٰوَاتِ وَالْاَرْضِ لَاٰيَاتٍ لِلْمُؤْمِن۪ينَۜ', 'İnne fis semavati vel ardı le ayatin lil mu\'minin.', 'Kuşkusuz göklerde ve yeryüzünde inananlar için ayetler[1] vardır.', 'ان في السموت والارض لايت للمومنين'),
(4477, 45, 4, 'وَف۪ي خَلْقِكُمْ وَمَا يَبُثُّ مِنْ دَٓابَّةٍ اٰيَاتٌ لِقَوْمٍ يُوقِنُونَۙ', 'Ve fi halkıkum ve ma yebussu min dabbetin ayatun li kavmin yukınun.', 'Sizin yaratılışınızda ve üretip yaydığı canlı varlıklarda \"gerçek bilgi\" sahibi olan bir toplum için ayetler vardır.', 'وفي خلقكم وما يبث من دابة ايت لقوم يوقنون'),
(4478, 45, 5, 'وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ وَمَٓا اَنْزَلَ اللّٰهُ مِنَ السَّمَٓاءِ مِنْ رِزْقٍ فَاَحْيَا بِهِ الْاَرْضَ بَعْدَ مَوْتِهَا وَتَصْر۪يفِ الرِّيَاحِ اٰيَاتٌ لِقَوْمٍ يَعْقِلُونَ', 'Vahtilafil leyli ven nehari ve ma enzelallahu mines semai min rızkın fe ahya bihil arda ba\'de mevtiha ve tasrifir riyahı ayatun li kavmin ya\'kılun.', 'Gece ile gündüzün birbirini izlemesinde,  Allah\'ın rızık olarak gökten indirdiği şeyle[1] ölümünden sonra yeryüzünü diriltmesinde ve rüzgarları yönlendirmesinde aklını kullanan bir toplum için ayetler[2] vardır.', 'واختلف اليل والنهار وما انزل الله من السما من رزق فاحيا به الارض بعد موتها وتصريف الريح ايت لقوم يعقلون'),
(4479, 45, 6, 'تِلْكَ اٰيَاتُ اللّٰهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّۚ فَبِاَيِّ حَد۪يثٍ بَعْدَ اللّٰهِ وَاٰيَاتِه۪ يُؤْمِنُونَ', 'Tilke ayatullahi netluha aleyke bil hakk, fe bi eyyi hadisin ba\'dallahi ve ayatihi yu\'minun.', 'İşte bunlar,  Bizim sana hakk[1] olarak anlattığımız Allah\'ın ayetleridir. O halde Allah\'tan ve O\'nun ayetlerinden sonra hangi hadise[2] inanacaklar?', 'تلك ايت الله نتلوها عليك بالحق فباي حديث بعد الله وايته يومنون'),
(4480, 45, 7, 'وَيْلٌ لِكُلِّ اَفَّاكٍ اَث۪يمٍۙ', 'Veylun li kulli effakin esim.', 'Bütün yalancı günahkarların vay haline!', 'ويل لكل افاك اثيم'),
(4481, 45, 8, 'يَسْمَعُ اٰيَاتِ اللّٰهِ تُتْلٰى عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِراً كَاَنْ لَمْ يَسْمَعْهَاۚ فَبَشِّرْهُ بِعَذَابٍ اَل۪يمٍ', 'Yesmeu ayatillahi tutla aleyhi summe yusırru mustekbiren ke en lem yesma\'ha, fe beşşirhu bi azabin elim.', 'Böyle kimseler,  kendilerine okunan Allah\'ın ayetlerini duyduktan sonra,  büyüklük taslayarak sanki hiç duymamış gibi davranır. Artık onu can yakıcı bir azapla haberdar et.', 'يسمع ايت الله تتلي عليه ثم يصر مستكبرا كان لم يسمعها فبشره بعذاب اليم'),
(4482, 45, 9, 'وَاِذَا عَلِمَ مِنْ اٰيَاتِنَا شَيْـٔاًۨ اتَّخَذَهَا هُزُواًۜ  اُو۬لٰٓئِكَ لَهُمْ عَذَابٌ مُه۪ينٌۜ', 'Ve iza alime min ayatina şey\'enittehazeha huzuva, ulaike lehum azabun muhin.', 'Ayetlerimizden bir şey öğrendikleri zaman,  onu alay konusu edinirler. İşte onlar için alçaltıcı bir azap vardır.', 'واذا علم من ايتنا شيا اتخذها هزوا اوليك لهم عذاب مهين'),
(4483, 45, 10, 'مِنْ وَرَٓائِهِمْ جَهَنَّمُۚ وَلَا يُغْن۪ي عَنْهُمْ مَا كَسَبُوا شَيْـٔاً وَلَا مَا اتَّخَذُوا مِنْ دُونِ اللّٰهِ اَوْلِيَٓاءَۚ وَلَهُمْ عَذَابٌ عَظ۪يمٌۜ', 'Min veraihim cehennem, ve la yugni anhum ma kesebu şey\'en ve la mattehazu min dunillahi evliyae, ve lehum azabun azim.', 'Cehennem peşlerindedir. Kazandıkları şeyler ve Allah\'ın yanı sıra edindikleri veliler[1] onlara bir yarar sağlamaz. Onlar için büyük bir azap vardır.', 'من ورايهم جهنم ولا يغني عنهم ما كسبوا شيا ولا ما اتخذوا من دون الله اوليا ولهم عذاب عظيم'),
(4484, 45, 11, 'هٰذَا هُدًىۚ وَالَّذ۪ينَ كَفَرُوا بِاٰيَاتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِنْ رِجْزٍ اَل۪يمٌ۟', 'Haza huda, vellezine keferu bi ayati rabbihim lehum azabun min riczin elim.', 'Bu doğru yol göstericisidir. Rabblerinin ayetlerini yalanlayanlar için çok kötü bir azap vardır.', 'هذا هدي والذين كفروا بايت ربهم لهم عذاب من رجز اليم'),
(4485, 45, 12, 'اَللّٰهُ الَّذ۪ي سَخَّرَ لَكُمُ الْبَحْرَ لِتَجْرِيَ الْفُلْكُ ف۪يهِ بِاَمْرِه۪ وَلِتَبْتَغُوا مِنْ فَضْلِه۪ وَلَعَلَّكُمْ تَشْكُرُونَۚ', 'Allahullezi sahhare lekumul bahre li tecriyel fulku fihi bi emrihi ve li tehtegu min fadlihi ve leallekum teşkurun.', 'Allah,  koyduğu yasalar sayesinde,  içinde gemileri yüzdürmeniz ve O\'nun lütfundan,  onda rızık aramanız için denizi hizmetinize sunandır. Umulur ki şükredersiniz.', 'الله الذي سخر لكم البحر لتجري الفلك فيه بامره ولتبتغوا من فضله ولعلكم تشكرون'),
(4486, 45, 13, 'وَسَخَّرَ لَكُمْ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ جَم۪يعاً مِنْهُۜ اِنَّ ف۪ي ذٰلِكَ لَاٰيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ', 'Ve sahhare lekum ma fis semavati ve ma fil ardı cemian minh, inne fi zalike le ayatin li kavmin yetefekkerun.', 'Göklerde ve yeryüzünde bulunan her şeyi Kendi lütfundan sizin yararlanmanıza sunmuştur. Bunda düşünen bir toplum için ayetler[1] vardır.', 'وسخر لكم ما في السموت وما في الارض جميعا منه ان في ذلك لايت لقوم يتفكرون'),
(4487, 45, 14, 'قُلْ لِلَّذ۪ينَ اٰمَنُوا يَغْفِرُوا لِلَّذ۪ينَ لَا يَرْجُونَ اَيَّامَ اللّٰهِ لِيَجْزِيَ قَوْماً بِمَا كَانُوا يَكْسِبُونَ', 'Kul lillezine amenu yagfiru lillezine la yercune eyyamallahi li yecziye kavmen bi ma kanu yeksibun.', 'İnananlara de ki: \"Allah\'ın,  kendilerini hesaba çekeceği günün geleceğini ummayanları bağışlasınlar. Her halka yaptıklarının karşılığı verilecektir.\"', 'قل للذين امنوا يغفروا للذين لا يرجون ايام الله ليجزي قوما بما كانوا يكسبون'),
(4488, 45, 15, 'مَنْ عَمِلَ صَالِحاً فَلِنَفْسِه۪ۚ وَمَنْ اَسَٓاءَ فَعَلَيْهَاۘ ثُمَّ اِلٰى رَبِّكُمْ تُرْجَعُونَ', 'Men amile salihan fe li nefsih, ve men esae fe aleyha summe ila rabbikum turceun.', 'Her kim iyilik yaparsa kendisi için yapmış olur,  kim de kötülük yaparsa kendisi için yapmış olur. Sonra Rabb\'inize döndürüleceksiniz.', 'من عمل صلحا فلنفسه ومن اسا فعليها ثم الي ربكم ترجعون'),
(4489, 45, 16, 'وَلَقَدْ اٰتَيْنَا بَن۪ٓي اِسْرَٓائ۪ـلَ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ وَرَزَقْنَاهُمْ مِنَ الطَّيِّبَاتِ وَفَضَّلْنَاهُمْ عَلَى الْعَالَم۪ينَۚ', 'Ve lekad ateyna beni israilel kitabe vel hukme ven nubuvvete ve rezaknahum minet tayyibati ve faddalnahum alel alemin.', 'Ant olsun ki İsrailoğulları\'na Kitap,  hüküm ve nebilik verdik. Ve onları temiz rızıklarla rızıklandırdık. Ve onları alemlere tercih ederek ihsanda bulunduk.', 'ولقد اتينا بني اسريل الكتب والحكم والنبوة ورزقنهم من الطيبت وفضلنهم علي العلمين'),
(4490, 45, 17, 'وَاٰتَيْنَاهُمْ بَيِّنَاتٍ مِنَ الْاَمْرِۚ فَمَا اخْتَلَفُٓوا اِلَّا مِنْ بَعْدِ مَا جَٓاءَهُمُ الْعِلْمُۙ بَغْياً بَيْنَهُمْۜ اِنَّ رَبَّكَ يَقْض۪ي بَيْنَهُمْ يَوْمَ الْقِيٰمَةِ ف۪يمَا كَانُوا ف۪يهِ يَخْتَلِفُونَ', 'Ve ateynahum beyyinatin minel emr, fe mahtelefu illa min ba\'di ma caehumul ilmu bagyen beynehum, inne rabbeke yakdi beynehum yevmel kıyameti fi ma kanu fihi yahtelifun.', 'Onlara,  buyruklardan,  apaçık,  açıklayıcı bilgiler verdik. Sonra onlar,  kendilerine ilim geldikten sonra hırslarına kapılarak ayrılığa düştüler. Rabbin,  ayrılığa düştükleri konularda Kıyamet Günü hüküm verecektir.', 'واتينهم بينت من الامر فما اختلفوا الا من بعد ما جاهم العلم بغيا بينهم ان ربك يقضي بينهم يوم القيمة فيما كانوا فيه يختلفون'),
(4491, 45, 18, 'ثُمَّ جَعَلْنَاكَ عَلٰى شَر۪يعَةٍ مِنَ الْاَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِـعْ اَهْوَٓاءَ الَّذ۪ينَ لَا يَعْلَمُونَ', 'Summe cealnake ala şeriatin minel emri fettebi\' ha ve la tettebi\' ehvaellezine la ya\'lemun.', 'Sonra da seni buyruklardan apaçık bir şeriat[1] sahibi yaptık. Öyleyse ona uy! Bilmeyenlerin[2] hevalarına[3] uyma.', 'ثم جعلنك علي شريعة من الامر فاتبعها ولا تتبع اهوا الذين لا يعلمون'),
(4492, 45, 19, 'اِنَّهُمْ لَنْ يُغْنُوا عَنْكَ مِنَ اللّٰهِ شَيْـٔاًۜ وَاِنَّ الظَّالِم۪ينَ بَعْضُهُمْ اَوْلِيَٓاءُ بَعْضٍۚ وَاللّٰهُ وَلِيُّ الْمُتَّق۪ينَ', 'İnnehum len yugnu anke minallahi şey\'a, ve innez zalimine ba\'duhum evliyau ba\'d, vallahu veliyyul muttekin.', 'Onlar,  Allah\'tan gelecek olan hiçbir şeyi senden savamazlar. Zalimler,  birbirlerinin velileridirler[1],  Allah ise takva[2] sahiplerinin velisidir.', 'انهم لن يغنوا عنك من الله شيا وان الظلمين بعضهم اوليا بعض والله ولي المتقين'),
(4493, 45, 20, 'هٰذَا بَصَٓائِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِقَوْمٍ يُوقِنُونَ', 'Haza basairu lin nasi ve huden ve rahmetun li kavmin yukınun.', 'Bu Kur\'an,  insanlar için gerçeği görme,  gerçekten inanan halk için doğru yolu gösterme ve bir rahmettir.', 'هذا بصير للناس وهدي ورحمة لقوم يوقنون'),
(4494, 45, 21, 'اَمْ حَسِبَ الَّذ۪ينَ اجْتَرَحُوا السَّيِّـَٔاتِ اَنْ نَجْعَلَهُمْ كَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِۙ سَوَٓاءً مَحْيَاهُمْ وَمَمَاتُهُمْۜ سَٓاءَ مَا يَحْكُمُونَ۟', 'Em hasibellezinecterahus seyyiati en nec\'alehum kellezine amenu ve amilus salihati sevaen mahyahum ve mematuhum, sae ma yahkumun.', 'Yoksa Bizim,  kötülük yapan kimselerle,  iman edip,  salihatı yapan kimseleri[1],  hayatlarında ve ölümlerinde bir tutacağımızı mı sanıyorlar. Ne kötü yargıda bulunuyorlar!', 'ام حسب الذين اجترحوا السيات ان نجعلهم كالذين امنوا وعملوا الصلحت سوا محياهم ومماتهم سا ما يحكمون'),
(4495, 45, 22, 'وَخَلَقَ اللّٰهُ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّ وَلِتُجْزٰى كُلُّ نَفْسٍ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'Ve halakallahus semavati vel arda bil hakkı ve li tucza kullu nefsin bima kesebet ve hum la yuzlemun.', 'Allah,  gökleri ve yeryüzünü \"hakk\"[1] ile yarattı. Herkes yaptığının karşılığını görecek ve hiç kimseye haksızlık edilmeyecektir.', 'وخلق الله السموت والارض بالحق ولتجزي كل نفس بما كسبت وهم لا يظلمون'),
(4496, 45, 23, 'اَفَرَاَيْتَ مَنِ اتَّخَذَ اِلٰهَهُ هَوٰيهُ وَاَضَلَّهُ اللّٰهُ عَلٰى عِلْمٍ وَخَتَمَ عَلٰى سَمْعِه۪ وَقَلْبِه۪ وَجَعَلَ عَلٰى بَصَرِه۪ غِشَاوَةًۜ  فَمَنْ يَهْد۪يهِ مِنْ بَعْدِ اللّٰهِۜ  اَفَلَا تَذَكَّرُونَ', 'E fe reeyte menittehaze ilahehu hevahu ve edallehullahu ala ilmin ve hateme ala sem\'ihi ve kalbihi ve ceale ala basarihi gışaveh, fe men yehdihi min ba\'dillah, e fe la tezekkerun.', 'Hevasını[1],  ilahlaştıran[2] kimseyi gördün mü? Allah,  bir bilgiye dayalı olarak, [3] onu sapkınlıkta bıraktı. Ve onun kulağını ve kalbini mühürledi. Gözlerine perde çekti. Artık Allah\'tan başka kim onu doğru yola iletebilir? Öğüt almıyor musunuz?', 'افريت من اتخذ الهه هويه واضله الله علي علم وختم علي سمعه وقلبه وجعل علي بصره غشوة فمن يهديه من بعد الله افلا تذكرون'),
(4497, 45, 24, 'وَقَالُوا مَا هِيَ اِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَٓا اِلَّا الدَّهْرُۚ وَمَا لَهُمْ بِذٰلِكَ مِنْ عِلْمٍۚ  اِنْ هُمْ اِلَّا يَظُنُّونَ', 'Ve kalu ma hiye illa hayatuned dunya nemutu ve nahya ve ma yuhlikuna illed dehr, ve ma lehum bi zalike min ilm, in hum illa yezunnun.', 'Onlar,  \"Hayat,  ancak bu dünya hayatından ibarettir. Doğar ve yaşarız,  bizi ancak zaman yok eder.\" dediler. Oysaki bu konuda gerçeğe dayalı hiçbir bilgileri yoktur. Onlar,  yalnızca zanda bulunuyorlar.', 'وقالوا ما هي الا حياتنا الدنيا نموت ونحيا وما يهلكنا الا الدهر وما لهم بذلك من علم ان هم الا يظنون'),
(4498, 45, 25, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍ مَا كَانَ حُجَّتَهُمْ اِلَّٓا اَنْ قَالُوا ائْتُوا بِاٰبَٓائِنَٓا اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve iza tutla aleyhim ayatuna beyyinatin ma kane huccetehum illa en kalu\'tu bi abaina in kuntum sadıkin.', 'Onlara,  ayetlerimiz açık ve kanıtlayıcı olarak okunduğu zaman da hüccetleri[1],  \"Eğer doğru söylüyorsanız,  atalarımızı geri getirin.\" demekten başka bir şey olmadı.', 'واذا تتلي عليهم ايتنا بينت ما كان حجتهم الا ان قالوا ايتوا باباينا ان كنتم صدقين'),
(4499, 45, 26, 'قُلِ اللّٰهُ يُحْي۪يكُمْ ثُمَّ يُم۪يتُكُمْ ثُمَّ يَجْمَعُكُمْ اِلٰى يَوْمِ الْقِيٰمَةِ لَا رَيْبَ ف۪يهِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُونَ۟', 'Kulillahu yuhyikum summe yumitukum summe yecmeukum ila yevmil kıyameti la reybe fihi ve lakinne ekseren nasi la ya\'lemun.', 'De ki: \"Sizi yaşatan sonra öldüren Allah\'tır. Sonra sizi,  gerçekleşeceği kesin olan Kıyamet Günü bir araya toplayacaktır.\" Ancak insanların çoğu bu gerçeği kavramıyorlar.', 'قل الله يحييكم ثم يميتكم ثم يجمعكم الي يوم القيمة لا ريب فيه ولكن اكثر الناس لا يعلمون'),
(4500, 45, 27, 'وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ وَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَخْسَرُ الْمُبْطِلُونَ', 'Ve lillahi mulkus semavati vel ard, ve yevme tekumus saatu yevme izin yahserul mubtılun.', 'Göklerin ve yeryüzünün mülkü Allah\'a aittir. Sa\'at\'ın[1] kopacağı o gün,  İzin Günü[2],  sapkın yolda olanlar hüsrana uğrayacaklardır.', 'ولله ملك السموت والارض ويوم تقوم الساعة يوميذ يخسر المبطلون'),
(4501, 45, 28, 'وَتَرٰى كُلَّ اُمَّةٍ جَاثِيَةً۠   كُلُّ اُمَّةٍ تُدْعٰٓى اِلٰى كِتَابِهَاۜ اَلْيَوْمَ تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ', 'Ve tera kulle ummetin casiyeh, kullu ummetin tud\'a ila kitabiha, el yevme tuczevne ma kuntum ta\'melun.', 'Her ümmeti toplanmış görürsün. Her ümmet,  amel defteriyle yüzleşmeye çağrılır: \"Bugün,  yaptıklarınızın karşılığı size verilecektir.\"', 'وتري كل امة جاثية كل امة تدعي الي كتبها اليوم تجزون ما كنتم تعملون'),
(4502, 45, 29, 'هٰذَا كِتَابُنَا يَنْطِقُ عَلَيْكُمْ بِالْحَقِّۜ اِنَّا كُنَّا نَسْتَنْسِخُ مَا كُنْتُمْ تَعْمَلُونَ', 'Haza kitabuna yentıku aleykum bil hakk, inna kunna nestensihu ma kuntum ta\'melun.', '\"İşte bu,  yüzünüze karşı gerçekleri ortaya koyan amel defterinizdir. Kuşkusuz Biz,  bütün yaptıklarınızı yazdırdık.\"', 'هذا كتبنا ينطق عليكم بالحق انا كنا نستنسخ ما كنتم تعملون'),
(4503, 45, 30, 'فَاَمَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُدْخِلُهُمْ رَبُّهُمْ ف۪ي رَحْمَتِه۪ۜ  ذٰلِكَ هُوَ الْفَوْزُ الْمُب۪ينُ', 'Fe emmellezine amenu ve amilus salihati fe yudhıluhum rabbuhum fi rahmetih, zalike huvel fevzul mubin.', 'İman eden ve salihatı[1] yapan kimseleri Rabbleri rahmeti ile kuşatacaktır. İşte bu,  büyük kurtuluşun ta kendisidir.', 'فاما الذين امنوا وعملوا الصلحت فيدخلهم ربهم في رحمته ذلك هو الفوز المبين'),
(4504, 45, 31, 'وَاَمَّا الَّذ۪ينَ كَفَرُوا۠  اَفَلَمْ تَكُنْ اٰيَات۪ي تُتْلٰى عَلَيْكُمْ فَاسْتَكْـبَرْتُمْ وَكُنْتُمْ قَوْماً مُجْرِم۪ينَ', 'Ve emmellezine keferu, e fe lem tekun ayati tutla aleykum festekbertum ve kuntum kavmen mucrimin.', 'Fakat gerçeği yalanlayan nankörlere denir ki: \"Ayetlerim size okunduğu zaman,  büyüklük taslayarak suç işleyen bir halk olmuştunuz değil mi?\"', 'واما الذين كفروا افلم تكن ايتي تتلي عليكم فاستكبرتم وكنتم قوما مجرمين'),
(4505, 45, 32, 'وَاِذَا ق۪يلَ اِنَّ وَعْدَ اللّٰهِ حَقٌّ وَالسَّاعَةُ لَا رَيْبَ ف۪يهَا قُلْتُمْ مَا نَدْر۪ي مَا السَّاعَةُۙ اِنْ نَظُنُّ اِلَّا ظَناًّ وَمَا نَحْنُ بِمُسْتَيْقِن۪ينَ', 'Ve iza kile inne va\'dallahi hakkun ves saatu la reybe fiha kultum ma nedri mes saatu in nezunnu illa zannen ve ma nahnu bi musteykınin.', '\"Allah\'ın verdiği söz gerçektir ve Sa\'at[1] mutlaka gelecektir.\" dendiği zaman,  siz: \"Biz,  o Sa\'at nedir bilmeyiz? Yalnızca bir varsayım olduğunu sanıyoruz,  kesin bilgi sahibi değiliz.\" dediniz.', 'واذا قيل ان وعد الله حق والساعة لا ريب فيها قلتم ما ندري ما الساعة ان نظن الا ظنا وما نحن بمستيقنين'),
(4506, 45, 33, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ', 'Ve beda lehum seyyiatu ma amilu ve haka bihim ma kanu bihi yestehziun.', 'Yaptıklarının kötülükleri apaçık ortaya kondu ve alay ettikleri şeyler,  onları kuşattı.', 'وبدا لهم سيات ما عملوا وحاق بهم ما كانوا به يستهزون'),
(4507, 45, 34, 'وَق۪يلَ الْيَوْمَ نَنْسٰيكُمْ كَمَا نَس۪يتُمْ لِقَٓاءَ يَوْمِكُمْ هٰذَا وَمَأْوٰيكُمُ النَّارُ وَمَا لَكُمْ مِنْ نَاصِر۪ينَ', 'Ve kilel yevme nensakum kema nesitum likae yevmikum haza ve me\'vakumun naru ve ma lekum min nasırin.', '\"Bugüne kavuşmayı nasıl umursamadıysanız,  Biz de bugün sizi umursamıyoruz. Kalacağınız yer ateştir. Ve sizin için bir yardımcı da yoktur.\" denir.', 'وقيل اليوم ننسيكم كما نسيتم لقا يومكم هذا وماويكم النار وما لكم من نصرين'),
(4508, 45, 35, 'ذٰلِكُمْ بِاَنَّكُمُ اتَّخَذْتُمْ اٰيَاتِ اللّٰهِ هُزُواً وَغَرَّتْكُمُ الْحَيٰوةُ الدُّنْيَاۚ فَالْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'Zalikum bi ennekumuttehaztum ayatillahi huzuven ve garretkumul hayatud dunya, fel yevme la yuhrecune minha ve la hum yusta\'tebun.', 'İşte bu,  Allah\'ın ayetlerini alay konusu etmeniz nedeniyledir. Sizi,  dünya hayatı aldattı. Artık bugün onlar,  Cehennem\'den çıkarılmazlar. Ve onlardan özür de kabul edilmez.', 'ذلكم بانكم اتخذتم ايت الله هزوا وغرتكم الحيوة الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون'),
(4509, 45, 36, 'فَلِلّٰهِ الْحَمْدُ رَبِّ السَّمٰوَاتِ وَرَبِّ الْاَرْضِ رَبِّ الْعَالَم۪ينَ', 'Fe lillahil hamdu rabbis semavati ve rabbil ardı rabbil alemin.', 'Öyleyse övgünün tamamı,  göklerin ve yerin Rabb\'i ve alemlerin Rabb\'i Allah\'a mahsustur.', 'فلله الحمد رب السموت ورب الارض رب العلمين'),
(4510, 45, 37, 'وَلَهُ الْكِبْرِيَٓاءُ فِي السَّمٰوَاتِ وَالْاَرْضِۖ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Ve lehul kibriyau fis semavati vel ard, ve huvel azizul hakim.', 'Göklerde ve yerde erişilmez büyüklük ve egemenlik yalnızca O\'nundur. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'وله الكبريا في السموت والارض وهو العزيز الحكيم'),
(4511, 46, 1, 'حٰمٓ', 'Ha mim.', 'Ha,  Mim.', 'حم'),
(4512, 46, 2, 'تَنْز۪يلُ الْكِتَابِ مِنَ اللّٰهِ الْعَز۪يزِ الْحَك۪يمِ', 'Tenzilul kitabi minallahil azizil hakim.', 'Kitap\'ın indirilmesi Mutlak Üstün Olan,  En İyi Hüküm Veren Allah tarafındandır.', 'تنزيل الكتب من الله العزيز الحكيم'),
(4513, 46, 3, 'مَا خَلَقْنَا السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَٓا اِلَّا بِالْحَقِّ وَاَجَلٍ مُسَمًّىۜ وَالَّذ۪ينَ كَفَرُوا عَمَّٓا اُنْذِرُوا مُعْرِضُونَ', 'Ma halaknes semavati vel arda ve ma beyne huma illa bil hakkı ve ecelin musemma, vellezine keferu amma unziru mu\'ridun.', 'Gökleri,  yeryüzünü ve ikisi arasındakileri gerçek olarak,  belirlenmiş bir süre için yarattık. Kafirler uyarıldıkları şeylerden yüz çevirmektedirler.', 'ما خلقنا السموت والارض وما بينهما الا بالحق واجل مسمي والذين كفروا عما انذروا معرضون'),
(4514, 46, 4, 'قُلْ اَرَاَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللّٰهِ اَرُون۪ي مَاذَا خَلَقُوا مِنَ الْاَرْضِ اَمْ لَهُمْ شِرْكٌ فِي السَّمٰوَاتِۜ ا۪يتُون۪ي بِكِتَابٍ مِنْ قَبْلِ هٰذَٓا اَوْ اَثَارَةٍ مِنْ عِلْمٍ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kul ereeytum ma ted\'une min dunillahi eruni maza halaku minel ardı em lehum şirkun fis semavat, ituni bi kitabin min kabli haza ev esaretin min ilmin in kuntum sadikin.', 'De ki: \"Allah\'ın yanı sıra yakardıklarınıza bir bakın bakalım! Onların,  yeryüzünde yarattıkları bir şey varsa bana gösterin! Yoksa onların göklerde bir ortakları mı var? Eğer doğru söylüyorsanız,  bana,  daha önce gelmiş bir kitap ya da bilgi kırıntısı bir eser getirin.', 'قل اريتم ما تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموت ايتوني بكتب من قبل هذا او اثرة من علم ان كنتم صدقين'),
(4515, 46, 5, 'وَمَنْ اَضَلُّ مِمَّنْ يَدْعُوا مِنْ دُونِ اللّٰهِ مَنْ لَا يَسْتَج۪يبُ لَـهُٓ اِلٰى يَوْمِ الْقِيٰمَةِ وَهُمْ عَنْ دُعَٓائِهِمْ غَافِلُونَ', 'Ve men edallu mimmen yed\'u min dunillahi men la yestecibu lehu ila yevmil kıyameti ve hum an duaihim gafilun.', 'Allah\'ın yanı sıra,  Kıyamet Günü\'ne kadar kendisine cevap veremeyecek ve edilen dualardan haberleri olmayana yönelen kimseden daha sapkın kim olabilir?', 'ومن اضل ممن يدعوا من دون الله من لا يستجيب له الي يوم القيمة وهم عن دعايهم غفلون'),
(4516, 46, 6, 'وَاِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ اَعْدَٓاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِر۪ينَ', 'Ve iza huşiren nasu kanu lehum a\'daen ve kanu bi ibadetihim kafirin.', 'İnsanlar bir araya getirildikleri zaman,  yöneldikleri kimseler,  kendilerine düşman kesilirler ve onların kendilerine kulluk ettiklerini[1] inkar ederler.', 'واذا حشر الناس كانوا لهم اعدا وكانوا بعبادتهم كفرين'),
(4517, 46, 7, 'وَاِذَا تُتْلٰى عَلَيْهِمْ اٰيَاتُنَا بَيِّنَاتٍ قَالَ الَّذ۪ينَ كَفَرُوا لِلْحَقِّ لَمَّا جَٓاءَهُمْۙ هٰذَا سِحْرٌ مُب۪ينٌۜ', 'Ve iza tutla aleyhim ayatuna beyyinatin kalellezine keferu lil hakkı lemma caehum haza sihrun mubin.', 'Ayetlerimiz kendilerine açıklayıcı olarak okunduğu zaman,  Kafirler;[1] kendilerine gelen \"hakk\"[2] için,  \"Bu apaçık bir büyüdür.\" dediler.', 'واذا تتلي عليهم ايتنا بينت قال الذين كفروا للحق لما جاهم هذا سحر مبين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4518, 46, 8, 'اَمْ يَقُولُونَ افْتَرٰيهُۜ  قُلْ اِنِ افْتَرَيْتُهُ فَلَا تَمْلِكُونَ ل۪ي مِنَ اللّٰهِ شَيْـٔاًۜ هُوَ اَعْلَمُ بِمَا تُف۪يضُونَ ف۪يهِۜ   كَفٰى بِه۪ شَه۪يداً بَيْن۪ي وَبَيْنَكُمْۜ وَهُوَ الْغَفُورُ الرَّح۪يمُ', 'Em yekulunefterah, kul iniftereytuhu fe la temlikune li minallahi şey\'a, huve a\'lemu bi ma tufidune fih, kefa bihi şehiden beyni ve beynekum ve huvel gafurur rahim.', 'Yoksa \"Onu uydurdu.\" mu diyorlar? De ki: \"Eğer onu uydurmuş olsaydım,  Allah\'tan bana gelecek şeye siz engel olamazdınız. O,  sizin ona karşı nelere giriştiğinizi çok iyi biliyor. Benimle sizin aranızda tanık olarak O yeter. O,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ام يقولون افتريه قل ان افتريته فلا تملكون لي من الله شيا هو اعلم بما تفيضون فيه كفي به شهيدا بيني وبينكم وهو الغفور الرحيم'),
(4519, 46, 9, 'قُلْ مَا كُنْتُ بِدْعاً مِنَ الرُّسُلِ وَمَٓا اَدْر۪ي مَا يُفْعَلُ ب۪ي وَلَا بِكُمْۜ اِنْ اَتَّبِعُ اِلَّا مَا يُوحٰٓى اِلَيَّ وَمَٓا اَنَا۬ اِلَّا نَذ۪يرٌ مُب۪ينٌ', 'Kul ma kuntu bid\'an miner rusuli ve ma edri ma yuf\'alu bi ve la bikum, in ettebiu illa ma yuha ileyye ve ma ene illa nezirun mubin.', 'De ki: \"İlk resul ben değilim. Bana ve size ne yapılacağını bilmiyorum. Ben,  yalnızca bana vahyedilene uyuyorum. Ben,  yalnızca apaçık bir uyarıcıyım.\"', 'قل ما كنت بدعا من الرسل وما ادري ما يفعل بي ولا بكم ان اتبع الا ما يوحي الي وما انا الا نذير مبين'),
(4520, 46, 10, 'قُلْ اَرَاَيْتُمْ اِنْ كَانَ مِنْ عِنْدِ اللّٰهِ وَكَفَرْتُمْ بِه۪ وَشَهِدَ شَاهِدٌ مِنْ بَن۪ٓي اِسْرَٓائ۪لَ عَلٰى مِثْلِه۪ فَاٰمَنَ وَاسْتَكْـبَرْتُمْۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ۟', 'Kul e reeytum in kane min indillahi ve kefertum bihi ve şehide şahidun min beni israile ala mislihi fe amene vestekbertum innallahe la yehdil kavmez zalimin.', 'De ki: \"Gördünüz mü?[1] Kur\'an gerçekten de Allah katındansa ve siz onu yalanladıysanız; İsrailoğulları\'ndan bir tanık da bunun benzerine tanık olup da inanmışsa ve siz de büyüklük tasladıysanız...[2] Kuşkusuz Allah,  zalim bir halka doğru yolu göstermez.\"', 'قل اريتم ان كان من عند الله وكفرتم به وشهد شاهد من بني اسريل علي مثله فامن واستكبرتم ان الله لا يهدي القوم الظلمين'),
(4521, 46, 11, 'وَقَالَ الَّذ۪ينَ كَفَرُوا لِلَّذ۪ينَ اٰمَنُوا لَوْ كَانَ خَيْراً مَا سَبَقُونَٓا اِلَيْهِۜ وَاِذْ لَمْ يَهْتَدُوا بِه۪ فَسَيَقُولُونَ هٰذَٓا اِفْكٌ قَد۪يمٌ', 'Ve kalellezine keferu lillezine amenulev kane hayren ma sebekuna ileyh, ve iz lem yehtedu bihi fe seyekulune haza ifkun kadim.', 'Kafirler,  inananlar için: \"Eğer Kur\'an\'da bir \"hayır\"[1] olsaydı,  onlar[2],  bizden önce onu kabul etmiş olmazlardı.\"[3] dediler. Kur\'an\'la doğru yolu bulmayı kendilerine yediremediklerinden,  \"Bu eski bir uydurmadır.\" diyeceklerdir.', 'وقال الذين كفروا للذين امنوا لو كان خيرا ما سبقونا اليه واذ لم يهتدوا به فسيقولون هذا افك قديم'),
(4522, 46, 12, 'وَمِنْ قَبْلِه۪ كِتَابُ مُوسٰٓى اِمَاماً وَرَحْمَةًۜ وَهٰذَا كِتَابٌ مُصَدِّقٌ لِسَاناً عَرَبِياًّ لِيُنْذِرَ الَّذ۪ينَ ظَلَمُواۗ وَبُشْرٰى لِلْمُحْسِن۪ينَ', 'Ve min kablihi kitabu musa imamen ve rahmeh ve haza kitabun musaddikun lisanen arabiyyen li yunzirellezine zalemu ve buşra lil muhsinin.', 'Bundan önce önder ve rahmet olarak Musa\'nın Kitap\'ı vardı. Kur\'an zulmedenleri[1] uyarmak; iyi olan kimseleri müjdelemek için,  dili Arapça olan,  tasdik eden[2] bir Kitap\'tır.', 'ومن قبله كتب موسي اماما ورحمة وهذا كتب مصدق لسانا عربيا لينذر الذين ظلموا وبشري للمحسنين'),
(4523, 46, 13, 'اِنَّ الَّذ۪ينَ قَالُوا رَبُّنَا اللّٰهُ ثُمَّ اسْتَقَامُوا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَۚ', 'İnnellezine kalu rabbunallahu summestekamu fe la havfun aleyhim ve la hum yahzenun.', '\"Rabb\'imiz Allah\'tır.\" deyip,  bu sözlerine bağlı kalanlar için hiçbir korku yoktur. Onlar üzülmeyeceklerdir.', 'ان الذين قالوا ربنا الله ثم استقموا فلا خوف عليهم ولا هم يحزنون'),
(4524, 46, 14, 'اُو۬لٰٓئِكَ اَصْحَابُ الْجَنَّةِ خَالِد۪ينَ ف۪يهَاۚ جَزَٓاءً بِمَا كَانُوا يَعْمَلُونَ', 'Ulaike ashabul cenneti halidine fiha, cezaen bima kanu ya\'melun.', 'İşte onlar Cennetliktirler. Yaptıklarına karşılık,  orada sürekli kalacaklardır.', 'اوليك اصحب الجنة خلدين فيها جزا بما كانوا يعملون'),
(4525, 46, 15, 'وَوَصَّيْنَا الْاِنْسَانَ بِوَالِدَيْهِ اِحْسَاناًۜ حَمَلَتْهُ اُمُّهُ كُرْهاً وَوَضَعَتْهُ كُرْهاًۜ وَحَمْلُهُ وَفِصَالُهُ ثَلٰثُونَ شَهْراًۜ حَتّٰٓى اِذَا بَلَغَ اَشُدَّهُ وَبَلَغَ اَرْبَع۪ينَ سَنَةًۙ قَالَ رَبِّ اَوْزِعْن۪ٓي اَنْ اَشْكُرَ نِعْمَتَكَ الَّت۪ٓي اَنْعَمْتَ عَلَيَّ وَعَلٰى وَالِدَيَّ وَاَنْ اَعْمَلَ صَالِحاً تَرْضٰيهُ وَاَصْلِحْ ل۪ي ف۪ي ذُرِّيَّت۪يۚ اِنّ۪ي تُبْتُ اِلَيْكَ وَاِنّ۪ي مِنَ الْمُسْلِم۪ينَ', 'Ve vassaynel insane bi valideyhi ihsana, hamelethu ummuhu kurhen ve vadaathu kurha, ve hamluhu ve fisaluhu selasune şehra, hatta iza belega eşuddehu ve belega erbaine seneten kale rabbi evzı\'ni en eşkure ni\'metekelleti en\'amte aleyye ve ala valideyye ve en a\'mele salihan terdahu ve aslıh li fi zurriyyeti, inni tubtu ileyke ve inni minel muslimin.', 'Biz insana,  anne ve babasına çok iyi davranmasını öğütledik. Annesi onu güçlükle taşıdı[1] ve onu güçlükle bıraktı.[2] Onun taşınması ve ayrılması[3] otuz aydır. Nihayet olgunluk çağına ulaştığı ve kırk yaşını[4] tamamladığında: \"Ey Rabbim! Bana,  anne ve babama bağışladığın nimetlerin karşılığında şükretmede ve hoşnut olacağın işler yapmada beni başarılı kıl. Ve soyuma da düzgün ve düzeltici olmayı nasip et. Kuşkusuz ben,  Sana yöneldim. Ve kuşkusuz ben,  Sana teslim olanlardanım.\" dedi.', 'ووصينا الانسن بولديه احسنا حملته امه كرها ووضعته كرها وحمله وفصله ثلثون شهرا حتي اذا بلغ اشده وبلغ اربعين سنة قال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلي ولدي وان اعمل صلحا ترضيه واصلح لي في ذريتي اني تبت اليك واني من المسلمين'),
(4526, 46, 16, 'اُو۬لٰٓئِكَ الَّذ۪ينَ نَتَقَبَّلُ عَنْهُمْ اَحْسَنَ مَا عَمِلُوا وَنَتَجَاوَزُ عَنْ سَيِّـَٔاتِهِمْ ف۪ٓي اَصْحَابِ الْجَنَّةِۜ وَعْدَ الصِّدْقِ الَّذ۪ي كَانُوا يُوعَدُونَ', 'Ulaikellezine netekabbelu anhum ahsene ma amilu ve netecavezu an seyyiatihim fi ashabil cenneh, va\'des sıdkıllezi kanu yuadun.', 'Onlar,  yaptıklarının karşılığını en iyi şekilde verdiğimiz ve kötülüklerini görmezden geldiğimiz,  Cennet ehli olan kimselerdir. Bu,  kendilerine verilen doğru sözün gerçekleşmesidir.', 'اوليك الذين نتقبل عنهم احسن ما عملوا ونتجاوز عن سياتهم في اصحب الجنة وعد الصدق الذي كانوا يوعدون'),
(4527, 46, 17, 'وَالَّذ۪ي قَالَ لِوَالِدَيْهِ اُفٍّ لَكُمَٓا اَتَعِدَانِن۪ٓي اَنْ اُخْرَجَ وَقَدْ خَلَتِ الْقُرُونُ مِنْ قَبْل۪ي وَهُمَا يَسْتَغ۪يثَانِ اللّٰهَ وَيْلَكَ اٰمِنْۗ اِنَّ وَعْدَ اللّٰهِ حَقٌّۚ فَيَقُولُ مَا هٰذَٓا اِلَّٓا اَسَاط۪يرُ الْاَوَّل۪ينَ', 'Vellezi kale li valideyhi uffın lekuma e teidanini en uhrece ve kad haletil kurunu min kabli ve huma yestegisanillahe veyleke amin, inne va\'dallahi hakk, fe yekulu ma haza illa esatirul evvelin.', 'Anne ve babasına: \"Öf be,  ikinizden de bıktım! Bunca insan gelip geçtiği halde,  hala,  beni öldükten sonra diriltileceğimle mi tehdit ediyorsunuz?\" dedi. Onlar,  onun için Allah\'a dua ederek: \"Yazık sana! Gel iman et. Kuşkusuz Allah\'ın sözü haktır.\" dediler. Bunun üzerine o: \"Bu öncekilerin masallarından başka bir şey değildir.\" dedi.', 'والذي قال لولديه اف لكما اتعدانني ان اخرج وقد خلت القرون من قبلي وهما يستغيثان الله ويلك امن ان وعد الله حق فيقول ما هذا الا اسطير الاولين'),
(4528, 46, 18, 'اُو۬لٰٓئِكَ الَّذ۪ينَ حَقَّ عَلَيْهِمُ الْقَوْلُ ف۪ٓي اُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِهِمْ مِنَ الْجِنِّ وَالْاِنْسِۜ اِنَّهُمْ كَانُوا خَاسِر۪ينَ', 'Ulaikellezine hakka aleyhimul kavlu fi umemin kad halet min kablihim minel cinni vel ins, innehum kanu hasirin.', 'İşte onlar ki,  Cinn ve insten[1],  kendilerinden önce gelip geçmiş topluluklarda yürürlükte olan \"söz\"[2] üzerlerine gerçekleşti. Onlar hüsrana uğrayan kimselerdir.', 'اوليك الذين حق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خسرين'),
(4529, 46, 19, 'وَلِكُلٍّ دَرَجَاتٌ مِمَّا عَمِلُواۚ وَلِيُوَفِّيَهُمْ اَعْمَالَهُمْ وَهُمْ لَا يُظْلَمُونَ', 'Ve li kullin derecatun mimma amilu, ve li yuveffiyehum a\'malehum ve hum la yuzlemun.', 'Herkesin yaptığına karşılık bir derecesi vardır. Hiç kimse haksızlığa uğratılmaksızın,  yaptıklarının karşılığı tam olarak ödenir.', 'ولكل درجت مما عملوا وليوفيهم اعملهم وهم لا يظلمون'),
(4530, 46, 20, 'وَيَوْمَ يُعْرَضُ الَّذ۪ينَ كَفَرُوا عَلَى النَّارِۜ  اَذْهَبْتُمْ طَيِّبَاتِكُمْ ف۪ي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَاۚ فَالْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنْتُمْ تَسْتَكْبِرُونَ فِي الْاَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَفْسُقُونَ۟', 'Ve yevme yu\'radullezine keferu alen nar, ezhebtum tayyibatikum fi hayatikumud dunya vestemta\'tum biha fel yevme tuczevne azabel huni bi ma kuntum testekbirune fil ardı bi gayril hakkı ve bi ma kuntum tefsukun.', 'Kafirler,  ateşe arz edilirlerken,  onlara: \"Dünya hayatınızda sahip olduğunuz tüm güzel şeyleri boşa harcadınız. Onlarla sefa sürdünüz. Yeryüzünde haksız yere büyüklük tasladığınız ve doğru yoldan saptığınız için,  artık bugün alçaltıcı bir azapla cezalandırılacaksınız.\" denir.', 'ويوم يعرض الذين كفروا علي النار اذهبتم طيبتكم في حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون في الارض بغير الحق وبما كنتم تفسقون'),
(4531, 46, 21, 'وَاذْكُرْ اَخَا عَادٍۜ اِذْ اَنْذَرَ قَوْمَهُ بِالْاَحْقَافِ وَقَدْ خَلَتِ النُّذُرُ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِه۪ٓ اَلَّا تَعْبُدُٓوا اِلَّا اللّٰهَۜ اِنّ۪ٓي اَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ۪يمٍ', 'Vezkur eha ad, iz enzere kavmehu bil ahkafi ve kad haletin nuzuru min beyni yedeyhi ve min halfihi ella ta\'budu illallah, inni ehafu aleykum azabe yevmin azim.', 'Âd\'ın kardeşini[1] an! Hani Ahkaf\'taki halkını uyarmıştı. Ondan önce de ve sonra da \"Allah\'tan başkasına kulluk etmeyin! Ben sizin için büyük bir günün azabından korkuyorum.\" diye uyaran nice uyarıcılar gelip geçmişti.', 'واذكر اخا عاد اذ انذر قومه بالاحقاف وقد خلت النذر من بين يديه ومن خلفه الا تعبدوا الا الله اني اخاف عليكم عذاب يوم عظيم'),
(4532, 46, 22, 'قَالُٓوا اَجِئْتَنَا لِتَأْفِكَنَا عَنْ اٰلِهَتِنَاۚ فَأْتِنَا بِمَا تَعِدُنَٓا اِنْ كُنْتَ مِنَ الصَّادِق۪ينَ', 'Kalu eci\'tena li te\'fikena an alihetina, fe\'tina bi ma teıduna in kunte mines sadikin.', '\"Sen bizi ilahlarımızdan[1] vazgeçirmek için mi geldin? Eğer doğru söyleyenlerden isen,  haydi bizi tehdit ettiğin şeyi hemen getir.\" dediler.', 'قالوا اجيتنا لتافكنا عن الهتنا فاتنا بما تعدنا ان كنت من الصدقين'),
(4533, 46, 23, 'قَالَ اِنَّمَا الْعِلْمُ عِنْدَ اللّٰهِۘ وَاُبَلِّغُكُمْ مَٓا اُرْسِلْتُ بِه۪ وَلٰكِنّ۪ٓي اَرٰيكُمْ قَوْماً تَجْـهَلُونَ', 'Kale innemel ilmu indallahi ve ubelligukum ma ursiltu bihi ve lakinni erakum kavmen techelun.', '\"O bilgi,  yalnızca Allah\'ın yanındadır. Ben,  size,  benimle gönderileni bildiriyorum. Ne var ki sizi cahillik eden bir kavim olarak görüyorum.\" dedi.', 'قال انما العلم عند الله وابلغكم ما ارسلت به ولكني اريكم قوما تجهلون'),
(4534, 46, 24, 'فَلَمَّا رَاَوْهُ عَارِضاً مُسْتَقْبِلَ اَوْدِيَتِهِمْۙ قَالُوا هٰذَا عَارِضٌ مُمْطِرُنَاۜ بَلْ هُوَ مَا اسْتَعْجَلْتُمْ بِه۪ۜ ر۪يحٌ ف۪يهَا عَذَابٌ اَل۪يمٌۙ', 'Fe lemma reevhu aridan mustakbile evdiyetihim kalu haza aridun mumtıruna, bel huve mesta\'celtum bih, rihun fiha azabun elim.', 'Onu,  vadilerine doğru gelen yoğun bir bulut halinde gördüklerinde: \"Bu,  bize yağmur getiren bir buluttur.\" dediler. \"Hayır! O,  sizin hemen gelmesini istediğiniz şeydir; acıklı azabı getiren rüzgardır.\"', 'فلما راوه عارضا مستقبل اوديتهم قالوا هذا عارض ممطرنا بل هو ما استعجلتم به ريح فيها عذاب اليم'),
(4535, 46, 25, 'تُدَمِّرُ كُلَّ شَيْءٍ بِاَمْرِ رَبِّهَا فَاَصْبَحُوا لَا يُرٰٓى اِلَّا مَسَاكِنُهُمْۜ  كَذٰلِكَ نَجْزِي الْقَوْمَ الْمُجْرِم۪ينَ', 'Tudemmiru kulle şey\'in bi emri rabbiha fe asbehu la yura illa mesakinuhum kezalike neczil kavmel mucrimin.', '\"Rabb\'inin emri ile her şeyi yok edecek!\" Böylece,  meskenlerinden başka hiçbir şey görünmez oldu. Biz,  suçlu halkı böyle cezalandırırız.', 'تدمر كل شي بامر ربها فاصبحوا لا يري الا مسكنهم كذلك نجزي القوم المجرمين'),
(4536, 46, 26, 'وَلَقَدْ مَكَّنَّاهُمْ ف۪يمَٓا اِنْ مَكَّنَّاكُمْ ف۪يهِ وَجَعَلْنَا لَهُمْ سَمْعاً وَاَبْصَاراً وَاَفْـِٔدَةًۘ  فَمَٓا اَغْنٰى عَنْهُمْ سَمْعُهُمْ وَلَٓا اَبْصَارُهُمْ وَلَٓا اَفْـِٔدَتُهُمْ مِنْ شَيْءٍ اِذْ  كَانُوا يَجْحَدُونَ بِاٰيَاتِ اللّٰهِ وَحَاقَ بِهِمْ مَا كَانُوا بِه۪ يَسْتَهْزِؤُ۫نَ۟', 'Ve lekad mekkenna hum fi ma in mekkennakum fihi ve cealna lehum sem\'an ve ebsaren ve ef\'ideten fe ma agna anhum sem\'uhum ve la ebsaruhum ve la ef\'idetuhum min şey\'in iz kanu yechadune bi ayatillahi ve haka bihim ma kanu bihi yestehziun.', 'Ant olsun ki Biz,  onlara,  size vermediğimiz nice imkanlar vermiştik. Onlara da kulaklar,  gözler ve kalpler[1] verdik. Ne var ki işitme ve görmeleri onlara bir yarar sağlamadı. Kalpleri de onlara bir yarar sağlamadı. Çünkü onlar,  Allah\'ın ayetlerini bile bile reddediyorlardı. Sonunda alaya aldıkları şey onları kuşattı.', 'ولقد مكنهم فيما ان مكنكم فيه وجعلنا لهم سمعا وابصرا وافدة فما اغني عنهم سمعهم ولا ابصرهم ولا افدتهم من شي اذ كانوا يجحدون بايت الله وحاق بهم ما كانوا به يستهزون'),
(4537, 46, 27, 'وَلَقَدْ اَهْلَكْنَا مَا حَوْلَكُمْ مِنَ الْقُرٰى وَصَرَّفْنَا الْاٰيَاتِ لَعَلَّهُمْ يَرْجِعُونَ', 'Ve lekad ehlekna ma havlekum minel kura ve sarrafnel ayati leallehum yerciun.', 'Ant olsun ki çevrenizdeki beldeleri yok ettik. Oysaki dönerler diye ayetlerimizi açıkça bildirmiştik.', 'ولقد اهلكنا ما حولكم من القري وصرفنا الايت لعلهم يرجعون'),
(4538, 46, 28, 'فَلَوْلَا نَصَرَهُمُ الَّذ۪ينَ اتَّخَذُوا مِنْ دُونِ اللّٰهِ قُرْبَاناً اٰلِهَةًۜ بَلْ ضَلُّوا عَنْهُمْۚ وَذٰلِكَ اِفْكُهُمْ وَمَا كَانُوا يَفْتَرُونَ', 'Fe lev la nasare humullezinettehazu min dunillahi kurbanen aliheh, bel dallu anhum, ve zalike ifkuhum ve ma kanu yefterun.', 'Allah\'ın yanı sıra,  kendilerini O\'na yaklaştırsınlar diye edindikleri ilahlar,  onlara yardım etseydi ya! Aksine onları yüzüstü bırakıp kayboldular. Bu; onların,  uydurdukları yalandan ibaret bir şeydi.', 'فلولا نصرهم الذين اتخذوا من دون الله قربانا الهة بل ضلوا عنهم وذلك افكهم وما كانوا يفترون'),
(4539, 46, 29, 'وَاِذْ صَرَفْنَٓا اِلَيْكَ نَفَراً مِنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْاٰنَۚ  فَلَمَّا حَضَرُوهُ قَالُٓوا اَنْصِتُواۚ فَلَمَّا قُضِيَ وَلَّوْا اِلٰى قَوْمِهِمْ مُنْذِر۪ينَ', 'Ve iz sarefna ileyke neferen minel cinni yestemiunel kur\'an, fe lemma hadaruhu kalu ensıtu, fe lemma kudıye vellev ila kavmihim munzirin.', 'Bir grup cinni[1] Kur\'an\'ı dinlemeleri için sana yönlendirmiştik. Onlar,  gelip Kur\'an\'ı dinlemeye başladıklarında birbirlerine,  \"sessiz olun,  dinleyin.\" dediler. Sonra da dinlemeleri bitince kendi halklarını uyarmak için geri döndüler.', 'واذ صرفنا اليك نفرا من الجن يستمعون القران فلما حضروه قالوا انصتوا فلما قضي ولوا الي قومهم منذرين'),
(4540, 46, 30, 'قَالُوا يَا قَوْمَنَٓا اِنَّا سَمِعْنَا كِتَاباً اُنْزِلَ مِنْ بَعْدِ مُوسٰى مُصَدِّقاً لِمَا بَيْنَ يَدَيْهِ يَهْد۪ٓي اِلَى الْحَقِّ وَاِلٰى طَر۪يقٍ مُسْتَق۪يمٍ', 'Kalu ya kavmena inna semi\'na kitaben unzile min ba\'di musa musaddikan li ma beyne yedeyhi yehdi ilel hakkı ve ila tarikın mustekim.', '\"Ey halkımız! Kuşkusuz biz,  Musa\'dan sonra indirilen ve kendinden öncekilerini onaylayan; gerçeği ve dosdoğru yolu gösteren bir kitap dinledik.\" dediler.', 'قالوا يقومنا انا سمعنا كتبا انزل من بعد موسي مصدقا لما بين يديه يهدي الي الحق والي طريق مستقيم'),
(4541, 46, 31, 'يَا قَوْمَنَٓا اَج۪يبُوا دَاعِيَ اللّٰهِ وَاٰمِنُوا بِه۪ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ اَل۪يمٍ', 'Ya kavmena ecibu daiyallahi ve aminu bihi yagfir lekum min zunubikum ve yucirkum min azabin elim.', '\"Ey halkımız! Allah\'ın davetçisine uyun ve Allah\'a iman edin ki suçlarınızı bağışlasın ve sizi acıklı bir azaptan korusun.\"', 'يقومنا اجيبوا داعي الله وامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب اليم'),
(4542, 46, 32, 'وَمَنْ لَا يُجِبْ دَاعِيَ اللّٰهِ فَلَيْسَ بِمُعْجِزٍ فِي الْاَرْضِ وَلَيْسَ لَهُ مِنْ دُونِه۪ٓ اَوْلِيَٓاءُۜ  اُو۬لٰٓئِكَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Ve men la yucib daiyallahi fe leyse bi mu\'cizin fil ardı ve leyse lehu min dunihi evliyau, ulaike fi dalalin mubin.', 'Her kim,  Allah\'a çağıran kimsenin çağrısına uymazsa,  bilsin ki Allah\'ı yeryüzünde aciz bırakacak değildir. Ve onun Allah\'tan başka velileri de yoktur. İşte onlar apaçık bir sapkınlık içindedirler.', 'ومن لا يجب داعي الله فليس بمعجز في الارض وليس له من دونه اوليا اوليك في ضلل مبين'),
(4543, 46, 33, 'اَوَلَمْ يَرَوْا اَنَّ اللّٰهَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلٰٓى اَنْ يُحْيِيَ الْمَوْتٰىۜ بَلٰٓى اِنَّهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'E ve lem yerev ennallahellezi halakas semavati vel arda ve lem ya\'ye bi halkıhinne bi kadirin ala en yuhyiyel mevta, bela innehu ala kulli şey\'in kadir.', 'Onlar,  gökleri ve yeri yaratan ve yaratmaktan yorulmamış olan Allah\'ın,  ölüleri de diriltebileceği gerçeğini anlamıyorlar mı? Evet! Kuşkusuz O,  Her Şeye Güç Yetiren\'dir.', 'اولم يروا ان الله الذي خلق السموت والارض ولم يعي بخلقهن بقدر علي ان يحي الموتي بلي انه علي كل شي قدير'),
(4544, 46, 34, 'وَيَوْمَ يُعْرَضُ الَّذ۪ينَ كَفَرُوا عَلَى النَّارِۜ  اَلَيْسَ هٰذَا بِالْحَقِّۜ قَالُوا بَلٰى وَرَبِّنَاۜ قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ', 'Ve yevme yu\'redullezine keferu alen nar,e leyse haza bil hakk, kalu bela ve rabbina, kale fe zukul azabe bi ma kuntum tekfurun.', 'Kafirler[1],  ateşle karşı karşıya kaldıkları gün,  Allah onlara: \"Bu,  gerçek değil miymiş?\" dedi. Onlar: \"Rabbimize ant olsun ki gerçekmiş.\" dediler. \" O halde kafirliğinizden dolayı azabı tadın.\" dedi.', 'ويوم يعرض الذين كفروا علي النار اليس هذا بالحق قالوا بلي وربنا قال فذوقوا العذاب بما كنتم تكفرون'),
(4545, 46, 35, 'فَاصْبِرْ كَمَا صَبَرَ اُو۬لُوا الْعَزْمِ مِنَ الرُّسُلِ وَلَا تَسْتَعْجِلْ لَهُمْۜ  كَاَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَۙ لَمْ يَلْبَثُٓوا اِلَّا سَاعَةً مِنْ نَهَارٍۜ  بَلَاغٌۚ  فَهَلْ يُهْلَكُ اِلَّا الْقَوْمُ الْفَاسِقُونَ', 'Fasbir kema sabere ulul azmi miner rusuli ve la testa\'cil lehum, ke ennehum yevme yerevne ma yuadune lem yelbesu illa saaten min nehar, belag, fe hel yuhleku illel kavmul fasikun.', 'O halde resullerden kararlılık sahibi olanların sabrettikleri gibi sen de sabret! Onlar için aceleci olma. Onlar,  kendilerine uyarısı yapılan şeyi gördükleri zaman,  dünyada sanki gündüzün bir saati kadar kalmış gibi olurlar.[1] Bu,  bir bildirimdir. Artık doğru yoldan sapmış halktan başkası yok edilmez.', 'فاصبر كما صبر اولوا العزم من الرسل ولا تستعجل لهم كانهم يوم يرون ما يوعدون لم يلبثوا الا ساعة من نهار بلغ فهل يهلك الا القوم الفسقون'),
(4546, 47, 1, 'اَلَّذ۪ينَ كَـفَرُوا وَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ اَضَلَّ اَعْمَالَهُمْ', 'Ellezine keferu ve saddu an sebilillahi edalle a\'malehum.', 'Kafir[1] olanların ve Allah\'ın yolundan alıkoyanların yaptıklarını boşa çıkaracaktır.', 'الذين كفروا وصدوا عن سبيل الله اضل اعملهم'),
(4547, 47, 2, 'وَالَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَاٰمَنُوا بِمَا نُزِّلَ عَلٰى مُحَمَّدٍ وَهُوَ الْحَقُّ مِنْ رَبِّهِمْۙ  كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَاَصْلَحَ بَالَهُمْ', 'Vellezine amenu ve amilus salihati ve amenu bi ma nuzzile ala muhammedin ve huvel hakku min rabbihim keffere anhum seyyiatihim ve asleha balehum.', 'İman eden,  salihatı[1] yapanlar ve Rabb\'leri tarafından Muhammed\'e indirilen \"Hakk\'a\"[2] inanan kimselere gelince,  Allah onların kötülüklerini örtüp durumlarını düzeltecektir.', 'والذين امنوا وعملوا الصلحت وامنوا بما نزل علي محمد وهو الحق من ربهم كفر عنهم سياتهم واصلح بالهم'),
(4548, 47, 3, 'ذٰلِكَ بِاَنَّ الَّذ۪ينَ كَفَرُوا اتَّبَعُوا الْبَاطِلَ وَاَنَّ الَّذ۪ينَ اٰمَنُوا اتَّبَعُوا الْحَقَّ مِنْ رَبِّهِمْۜ   كَذٰلِكَ يَضْرِبُ اللّٰهُ لِلنَّاسِ اَمْثَالَهُمْ', 'Zalike bi ennellezine keferuttebeul batıle ve ennellezine amenuttebeul hakka min rabbihim, kezalike yadribullahu lin nasi emsalehum.', 'Bu,  Kafirlerin[1],  \"Batıl\'a\" uymaları,  inananların ise Rabb\'lerinden gelen \"Hakk\'a\" uymaları nedeniyledir. İşte Allah,  insanlara kendi durumlarını böyle örnek verir.', 'ذلك بان الذين كفروا اتبعوا البطل وان الذين امنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثلهم'),
(4549, 47, 4, 'فَاِذَا لَق۪يتُمُ الَّذ۪ينَ كَفَرُوا فَضَرْبَ الرِّقَابِۜ حَتّٰٓى اِذَٓا اَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَۙ فَاِمَّا مَناًّ بَعْدُ وَاِمَّا فِدَٓاءً حَتّٰى تَضَعَ الْحَرْبُ اَوْزَارَهَاۚۛ ذٰلِكَۜۛ وَلَوْ يَشَٓاءُ اللّٰهُ لَانْتَصَرَ مِنْهُمْۙ وَلٰكِنْ لِيَبْلُوَ۬ا بَعْضَكُمْ بِبَعْضٍۜ وَالَّذ۪ينَ قُتِلُوا ف۪ي سَب۪يلِ اللّٰهِ فَلَنْ يُضِلَّ اَعْمَالَهُمْ', 'Fe iza lekitumullezine keferu fe darber rikab, hatta iza eshantumuhum fe şuddul vesak, fe imma mennen ba\'du ve imma fidaen hatta tedaal harbu evzareha, zalik, ve lev yeşaullahu lentasara minhum ve lakin li yebluve ba\'dakum bi ba\'d, vellezine kutilu fi sebilillahi fe len yudille a\'malehum.', 'Kafirlerle savaşa giriştiğiniz zaman,  boyunlarını vurun[1]. Güçlerini yok edince,  bağı sıkıca bağlayın[2]. Ondan sonra bir bağışlama[3] olarak veya fidye karşılığında savaş sona erince onları serbest bırakın.[4] Eğer Allah isteseydi onlardan savaşsız da intikam alırdı. Fakat böyle olması sizi birbirinizle denemek içindir. Allah yolunda öldürülenlere gelince,  Allah onların yaptıklarını asla karşılıksız bırakmaz.', 'فاذا لقيتم الذين كفروا فضرب الرقاب حتي اذا اثخنتموهم فشدوا الوثاق فاما منا بعد واما فدا حتي تضع الحرب اوزارها ذلك ولو يشا الله لانتصر منهم ولكن ليبلوا بعضكم ببعض والذين قتلوا في سبيل الله فلن يضل اعملهم'),
(4550, 47, 5, 'سَيَهْد۪يهِمْ وَيُصْلِحُ بَالَهُمْۚ', 'Seyehdihim ve yuslihu balehum.', 'Onlara doğru yolu gösterecek ve durumlarını düzeltecektir.', 'سيهديهم ويصلح بالهم'),
(4551, 47, 6, 'وَيُدْخِلُهُمُ الْجَنَّةَ عَرَّفَهَا لَهُمْ', 'Ve yudhıluhumul cennete arrefeha lehum.', 'Onları,  dünyada kendilerine tarif ettiği Cennet\'e yerleştirecektir.', 'ويدخلهم الجنة عرفها لهم'),
(4552, 47, 7, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنْ تَنْصُرُوا اللّٰهَ يَنْصُرْكُمْ وَيُثَبِّتْ اَقْدَامَكُمْ', 'Ya eyyuhellezine amenu in tensurullahe yensurkum ve yusebbit akdamekum.', 'Ey inananlar! Eğer siz Allah\'a yardım ederseniz[1],  O da size yardım eder. Ayaklarınızı sabit kılar.[2]', 'يايها الذين امنوا ان تنصروا الله ينصركم ويثبت اقدامكم'),
(4553, 47, 8, 'وَالَّذ۪ينَ كَفَرُوا فَتَعْساً لَهُمْ وَاَضَلَّ اَعْمَالَهُمْ', 'Vellezine keferu fe tağsen lehumve edalle a\'malehum.', 'Kafirler ise yok olsunlar! Allah,  onların yaptıklarını boşa çıkaracaktır.', 'والذين كفروا فتعسا لهم واضل اعملهم'),
(4554, 47, 9, 'ذٰلِكَ بِاَنَّهُمْ كَرِهُوا مَٓا اَنْزَلَ اللّٰهُ فَاَحْبَطَ اَعْمَالَهُمْ', 'Zalike bi ennehum kerihu ma enzelallahu fe ahbeta a\'malehum.', 'Bu,  onların Allah\'ın indirdiği şeyi kötü görmelerinden dolayıdır. Bundan dolayı Allah,  onların yaptıklarını boşa çıkarmıştır.', 'ذلك بانهم كرهوا ما انزل الله فاحبط اعملهم'),
(4555, 47, 10, 'اَفَلَمْ يَس۪يرُوا فِي الْاَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذ۪ينَ مِنْ قَبْلِهِمْۜ دَمَّرَ اللّٰهُ عَلَيْهِمْۘ وَلِلْكَافِر۪ينَ اَمْثَالُهَا', 'E fe lem yesiru fil ardı fe yenzuru keyfe kane akıbetullezine min kablihim, demmerallahu aleyhim ve lil kafirine emsaluha.', 'Hem onlar,  yeryüzünde gezip dolaşmazlar mı? Baksalar ya! Kendilerinden öncekilerin sonlarının nasıl olduğuna! Allah,  onları yerle bir etti. Onun bir benzeri de Kafirler içindir.', 'افلم يسيروا في الارض فينظروا كيف كان عقبة الذين من قبلهم دمر الله عليهم وللكفرين امثلها'),
(4556, 47, 11, 'ذٰلِكَ بِاَنَّ اللّٰهَ مَوْلَى الَّذ۪ينَ اٰمَنُوا وَاَنَّ الْكَافِر۪ينَ لَا مَوْلٰى لَهُمْ۟', 'Zalike bi ennallahe mevlellezine amenu ve ennel kafirine la mevla lehum.', 'Allah inananların mevlasıdır. Kafirlerin ise hiçbir mevlası yoktur.', 'ذلك بان الله مولي الذين امنوا وان الكفرين لا مولي لهم'),
(4557, 47, 12, 'اِنَّ اللّٰهَ يُدْخِلُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ وَالَّذ۪ينَ كَفَرُوا يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ الْاَنْعَامُ وَالنَّارُ مَثْوًى لَهُمْ', 'İnnallahe yudhılullezine amenu ve amilus salihati cennatin tecri min tahtihel enhar, vellezine keferu yetemetteune ve ye\'kulune kema te\'kulul en\'amu ven naru mesven lehum.', 'Allah,  iman edip salihatı yapanları[1],  içinden ırmaklar akan Cennetlere yerleştirir. Kafirler ise her şeyden yararlanıp,  hayvanların yediği gibi yerler. Onların varacakları yer ateştir.', 'ان الله يدخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر والذين كفروا يتمتعون وياكلون كما تاكل الانعم والنار مثوي لهم'),
(4558, 47, 13, 'وَكَاَيِّنْ مِنْ قَرْيَةٍ هِيَ اَشَدُّ قُوَّةً مِنْ قَرْيَتِكَ الَّت۪ٓي اَخْرَجَتْكَۚ اَهْلَكْنَاهُمْ فَلَا نَاصِرَ لَهُمْ', 'Ve keeyyin min karyetin hiye eşeddu kuvveten min karyetikelleti ahrecetke, ehleknahum fe la nasıra lehum.', 'Güç bakımından,  seni yurdundan çıkaranlardan daha güçlü nice kent halkını yok ettik. Onlara yardım edecek hiç kimse de olmadı.', 'وكاين من قرية هي اشد قوة من قريتك التي اخرجتك اهلكنهم فلا ناصر لهم'),
(4559, 47, 14, 'اَفَمَنْ كَانَ عَلٰى بَيِّنَةٍ مِنْ رَبِّه۪ كَمَنْ زُيِّنَ لَهُ سُٓوءُ عَمَلِه۪ وَاتَّبَعُٓوا اَهْوَٓاءَهُمْ', 'E fe men kane ala beyyinetin min rabbihi ke men zuyyine lehu suu amelihi vettebeu ehvaehum.', 'Rabbinden gelen kanıt içeren apaçık bilgiyi izleyen kimse,  kötü işleri kendisine güzel gösterilen ve hevalarına[1] uyan kimse ile bir olur mu?', 'افمن كان علي بينة من ربه كمن زين له سو عمله واتبعوا اهواهم'),
(4560, 47, 15, 'مَثَلُ الْجَنَّةِ الَّت۪ي وُعِدَ الْمُتَّقُونَۜ ف۪يهَٓا اَنْهَارٌ مِنْ مَٓاءٍ غَيْرِ اٰسِنٍۚ وَاَنْهَارٌ مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُۚ وَاَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِب۪ينَۚ وَاَنْهَارٌ مِنْ عَسَلٍ مُصَفًّىۜ  وَلَهُمْ ف۪يهَا مِنْ كُلِّ الثَّمَرَاتِ وَمَغْفِرَةٌ مِنْ رَبِّهِمْۜ   كَمَنْ هُوَ خَالِدٌ فِي النَّارِ وَسُقُوا مَٓاءً حَم۪يماً فَقَطَّعَ اَمْعَٓاءَهُمْ', 'Meselul cennetilleti vuidel muttekun, fiha enharun min main gayri asin, ve enharun min lebenin lem yetegayyer ta\'muh, ve enharun min hamrin lezzetin liş şaribin, ve enharun min aselin musaffa, ve lehum fiha min kullis semerati ve magfiretun min rabbihim, ke men huve halidun fin nari ve suku maen hamimen fe kattaa em\'aehum.', 'Takva sahiplerine söz verilen Cennet,  şöyledir: İçinde; kokusu ve tadı değişmeyen sudan nehirler,  tadı bozulmayan sütten nehirler,  içenlere zevk veren hamrdan[1] nehirler ve saf baldan nehirler bulunur. Orada,  onlar için her türlü meyve bulunur. Onlara,  Rabb\'lerinden bağışlanma vardır. Bu kimseler,  ateşte devamlı kalacak olan ve sıcak kaynar su içirilen,  bundan dolayı da bağırsakları parça parça olan kimselerle bir olur mu hiç?', 'مثل الجنة التي وعد المتقون فيها انهر من ما غير اسن وانهر من لبن لم يتغير طعمه وانهر من خمر لذة للشربين وانهر من عسل مصفي ولهم فيها من كل الثمرت ومغفرة من ربهم كمن هو خلد في النار وسقوا ما حميما فقطع امعاهم'),
(4561, 47, 16, 'وَمِنْهُمْ مَنْ يَسْتَمِــعُ اِلَيْكَۚ حَتّٰٓى اِذَا خَرَجُوا مِنْ عِنْدِكَ قَالُوا لِلَّذ۪ينَ اُو۫تُوا الْعِلْمَ مَاذَا قَالَ اٰنِفاً۠ اُو۬لٰٓئِكَ الَّذ۪ينَ طَبَعَ اللّٰهُ عَلٰى قُلُوبِهِمْ وَاتَّبَعُٓوا اَهْوَٓاءَهُمْ', 'Ve minhum men yestemiu ileyke, hatta iza harecu min indike kalu lillezine utul ilme maza kale anifa, ulaikellezine tabaallahu ala kulubihim vettebeu ehvaehum.', 'Münafıklardan[1] kimisi de seni dinliyormuş gibi gözükür. Senin yanından ayrıldıktan sonra,  kendilerine ilim verilenlere:[2] \"O,  biraz önce ne dedi?[3]\" dediler. İşte onlar,  Allah\'ın kalplerini mühürledikleri ve hevalarına[4] tabi olan kimselerdir.', 'ومنهم من يستمع اليك حتي اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال انفا اوليك الذين طبع الله علي قلوبهم واتبعوا اهواهم'),
(4562, 47, 17, 'وَالَّذ۪ينَ اهْتَدَوْا زَادَهُمْ هُدًى وَاٰتٰيهُمْ تَقْوٰيهُمْ', 'Vellezinehtedev zadehum huden ve atahum takvahum.', 'Yöneltildikleri doğru yolda olanlara gelince,  onlara doğru yolları pekiştirildi ve onlara takvalarını[1] verdi.', 'والذين اهتدوا زادهم هدي واتيهم تقويهم'),
(4563, 47, 18, 'فَهَلْ يَنْظُرُونَ اِلَّا السَّاعَةَ اَنْ تَأْتِيَهُمْ بَغْتَةًۚ فَقَدْ جَٓاءَ اَشْرَاطُهَاۚ فَاَنّٰى لَهُمْ اِذَا جَٓاءَتْهُمْ ذِكْرٰيهُمْ', 'Fe hel yenzurune illes saate en te\'tiyehum bagteh, fe kad cae eşratuha, fe enna lehum iza caethum zikrahum.', 'İlle de o Sa\'at\'in[1] ansızın gelmesini mi bekliyorlar? Oysa onun belirtileri gelmiştir.[2] O gelecek olduktan sonra,  öğüdü dinlemek onlara ne yarar sağlar ki?', 'فهل ينظرون الا الساعة ان تاتيهم بغتة فقد جا اشراطها فاني لهم اذا جاتهم ذكريهم'),
(4564, 47, 19, 'فَاعْلَمْ اَنَّهُ لَٓا اِلٰهَ اِلَّا اللّٰهُ وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِۜ وَاللّٰهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوٰيكُمْ۟', 'Fa\'lem ennehu la ilahe illallahu vestagfir li zenbike ve lil mu\'minine vel mu\'minat, valla hu ya\'lemu mutekallebekum ve mesvakum.', 'O halde,  Allah\'tan başka ilah olmadığını bil. Kendi suçların için,  inanan erkekler ve kadınlar için bağışlanma dile. Allah,  dönüp dolaşacağınız yeri ve varıp duracağınız yeri bilir.[1]', 'فاعلم انه لا اله الا الله واستغفر لذنبك وللمومنين والمومنت والله يعلم متقلبكم ومثويكم'),
(4565, 47, 20, 'وَيَقُولُ الَّذ۪ينَ اٰمَنُوا لَوْلَا نُزِّلَتْ سُورَةٌۚ فَاِذَٓا اُنْزِلَتْ سُورَةٌ مُحْكَمَةٌ وَذُكِرَ ف۪يهَا الْقِتَالُۙ رَاَيْتَ الَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ يَنْظُرُونَ اِلَيْكَ نَظَرَ الْمَغْشِيِّ عَلَيْهِ مِنَ الْمَوْتِۜ فَاَوْلٰى لَهُمْۚ', 'Ve yekulullezine amenu lev la nuzzilet sureh, fe iza unzilet suretun muhkemetun ve zukire fi hel kıtalu re\'eytellezine fi kulubihim maradun yanzurune ileyke nazaral magşiyyi aleyhi minel mevt, fe evla lehum.', 'İman edenler,  \"Bir sure[1] indirilmeli değil miydi\" derler. Sonra savaştan söz eden,  hükmü kesin bir sure indirilince,  kalpleri hastalıklı kimselerin,  sana,  sanki üzerlerine ölüm hali çökmüş kimseler gibi baygın baygın baktıklarını görürsün. Oysa onlar için uygun olanı;', 'ويقول الذين امنوا لولا نزلت سورة فاذا انزلت سورة محكمة وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولي لهم'),
(4566, 47, 21, 'طَاعَةٌ وَقَوْلٌ مَعْرُوفٌ۠ فَاِذَا عَزَمَ الْاَمْرُ۠ فَلَوْ صَدَقُوا اللّٰهَ لَكَانَ خَيْراً لَهُمْۚ', 'Taatun ve kavlun ma\'ruf, fe iza azemel emr, fe lev sadekullahe le kane hayran lehum.', 'İtaat etmek ve maruf[1] söz söylemektir. Fakat iş kesinleşince[2] Allah\'a verdikleri sözde dursalardı elbette bu onlar için hayırlı olan olurdu.', 'طاعة وقول معروف فاذا عزم الامر فلو صدقوا الله لكان خيرا لهم'),
(4567, 47, 22, 'فَهَلْ عَسَيْتُمْ اِنْ تَوَلَّيْتُمْ اَنْ تُفْسِدُوا فِي الْاَرْضِ وَتُقَطِّعُٓوا اَرْحَامَكُمْ', 'Fe hel aseytum in tevelleytum en tufsidu fil ardı ve tukattıu erhamekum.', 'Yüz çevirmekle[1] yeryüzünde fesadın çıkmasına ve rahmet bağlarının[2] paramparça olmasına sebep olacağınızın farkında mısınız?', 'فهل عسيتم ان توليتم ان تفسدوا في الارض وتقطعوا ارحامكم'),
(4568, 47, 23, 'اُو۬لٰٓئِكَ الَّذ۪ينَ لَعَنَهُمُ اللّٰهُ فَاَصَمَّهُمْ وَاَعْمٰٓى اَبْصَارَهُمْ', 'Ulaikellezine leanehumullahu fe esammehum ve a\'ma ebsarehum.', 'İşte onlar,  Allah\'ın lanetlediği kimselerdir. Böylece onların kulaklarını sağır,  gözlerini kör yaptı.[1]', 'اوليك الذين لعنهم الله فاصمهم واعمي ابصرهم'),
(4569, 47, 24, 'اَفَلَا يَتَدَبَّرُونَ الْقُرْاٰنَ اَمْ عَلٰى قُلُوبٍ اَقْفَالُهَا', 'E fe la yetedebberunel kur\'ane em ala kulubin akfaluha.', 'Onlar,  Kur\'an üzerinde düşünmüyorlar mı?[1] Yoksa kalpleri üzerinde kilitleri mi var?', 'افلا يتدبرون القران ام علي قلوب اقفالها'),
(4570, 47, 25, 'اِنَّ الَّذ۪ينَ ارْتَدُّوا عَلٰٓى اَدْبَارِهِمْ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَىۙ الشَّيْطَانُ سَوَّلَ لَهُمْۜ وَاَمْلٰى لَهُمْ', 'İnnellezinerteddu ala edbarihim min ba\'di ma tebeyyene lehumul hudeş şeytanu sevvele lehum ve emla lehum.', 'Kendilerine doğru yol açıkça belli olduktan sonra,  ona sırt dönenleri,  şeytan[1] aldattı ve onları boş ümitlere yöneltti.', 'ان الذين ارتدوا علي ادبرهم من بعد ما تبين لهم الهدي الشيطن سول لهم واملي لهم'),
(4571, 47, 26, 'ذٰلِكَ بِاَنَّهُمْ قَالُوا لِلَّذ۪ينَ كَرِهُوا مَا نَزَّلَ اللّٰهُ سَنُط۪يعُكُمْ ف۪ي بَعْضِ الْاَمْرِۚ وَاللّٰهُ يَعْلَمُ اِسْرَارَهُمْ', 'Zalike bi ennehum kalu lillezine kerihu ma nezzelallahu senutiukum fi ba\'dil emr, vallahu ya\'lemu israrehum.', 'Bu,  onların,  Allah\'ın indirdiğini beğenmeyen kimselere: \"Bazı işlerde size uyacağız.\" demeleri nedeniyledir. Allah,  onların gizlediklerini biliyor.', 'ذلك بانهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الامر والله يعلم اسرارهم'),
(4572, 47, 27, 'فَكَيْفَ اِذَا تَوَفَّتْهُمُ الْمَلٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَاَدْبَارَهُمْ', 'Fe keyfe iza teveffethumul melaiketu yadribune vucuhehum ve edbarehum.', 'Melekler onları vefat ettirirken,  yüzlerine ve arkalarına vurduklarında onların durumları ne olacak?', 'فكيف اذا توفتهم المليكة يضربون وجوههم وادبرهم'),
(4573, 47, 28, 'ذٰلِكَ بِاَنَّهُمُ اتَّبَعُوا مَٓا اَسْخَطَ اللّٰهَ وَكَرِهُوا رِضْوَانَهُ فَاَحْبَطَ اَعْمَالَهُمْ۟', 'Zalike bi ennehumuttebeu ma eshatallahe ve kerihu rıdvanehu fe ahbeta a\'malehum.', 'Bu,  onların,  Allah\'ı öfkelendiren şeylere uymaları ve O\'nun rızasını gereksiz görmelerindendir. Böylece onların yaptıkları işleri boşa çıkardı.', 'ذلك بانهم اتبعوا ما اسخط الله وكرهوا رضونه فاحبط اعملهم'),
(4574, 47, 29, 'اَمْ حَسِبَ الَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ اَنْ لَنْ يُخْرِجَ اللّٰهُ اَضْغَانَهُمْ', 'Em hasibellezine fi kulubihim maradun en len yuhricallahu adganehum.', 'Yoksa kalplerinde hastalık olanlar,  Allah\'ın,  içlerindeki kini ortaya çıkarmayacağını mı sandılar?', 'ام حسب الذين في قلوبهم مرض ان لن يخرج الله اضغنهم'),
(4575, 47, 30, 'وَلَوْ نَشَٓاءُ لَاَرَيْنَاكَهُمْ فَلَعَرَفْتَهُمْ بِس۪يمٰيهُمْۜ وَلَتَعْرِفَنَّهُمْ ف۪ي لَحْنِ الْقَوْلِۜ وَاللّٰهُ يَعْلَمُ اَعْمَالَكُمْ', 'Ve lev neşau le ereynakehum fe le areftehum bi simahum ve le ta\'rifennehum fi lahnil kavl, vallahu ya\'lemu a\'malekum.', 'Eğer isteseydik onları sana tanıttırırdık. Sen de onları simalarından tanırdın. Yine de sen; onları,  konuşma tarzlarından tanırsın. Allah,  yaptıklarınızı bilir.', 'ولو نشا لارينكهم فلعرفتهم بسيمهم ولتعرفنهم في لحن القول والله يعلم اعملكم'),
(4576, 47, 31, 'وَلَنَبْلُوَنَّكُمْ حَتّٰى نَعْلَمَ الْمُجَاهِد۪ينَ مِنْكُمْ وَالصَّابِر۪ينَۙ وَنَبْلُوَ۬ا اَخْبَارَكُمْ', 'Ve le nebluvennekum hatta na\'lemel mucahidine minkum ves sabirine ve nebluve ahbarekum.', 'İçinizden cihad edenleri ve sabredenleri ortaya çıkarıncaya kadar sizi sınava tabi tutarız. Ve haberlerinizi[1] de sınava tabi tutacağız.', 'ولنبلونكم حتي نعلم المجهدين منكم والصبرين ونبلوا اخباركم'),
(4577, 47, 32, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ وَشَٓاقُّوا الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدٰىۙ لَنْ يَضُرُّوا اللّٰهَ شَيْـٔاًۜ وَسَيُحْبِطُ اَعْمَالَهُمْ', 'İnnellezine keferu ve saddu an sebilillahi ve şakkur resule min ba\'di ma tebeyyene lehumul huda len yedurrullahe şey\'a, ve seyuhbitu a\'malehum.', 'Kafirler[1],  Allah\'ın yolundan alıkoyanlar,  doğru yol açıkça belli olduktan sonra Resul\'e karşı gelen kimseler,  hiçbir şekilde ve asla Allah\'a zarar veremezler. Allah,  onların yaptıklarını boşa çıkaracaktır.', 'ان الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدي لن يضروا الله شيا وسيحبط اعملهم'),
(4578, 47, 33, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اَط۪يعُوا اللّٰهَ وَاَط۪يعُوا الرَّسُولَ وَلَا تُبْطِلُٓوا اَعْمَالَكُمْ', 'Ya eyyuhellezine amenu etiullahe ve etiur resule ve la tubtılu a\'malekum.', 'Ey iman edenler! Allah\'a itaat edin ve Resul\'e itaat edin.[1] Yaptıklarınızı boşa çıkarmayın.[2]', 'يايها الذين امنوا اطيعوا الله واطيعوا الرسول ولا تبطلوا اعملكم'),
(4579, 47, 34, 'اِنَّ الَّذ۪ينَ كَفَرُوا وَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ فَلَنْ يَغْفِرَ اللّٰهُ لَهُمْ', 'İnnellezine keferu ve saddu an sebilillahi summe matu ve hum kuffarun fe len yagfirallahu lehum.', 'Kafir olanlar,  Allah\'ın yolundan alıkoyanlar; sonra da Kafir olarak ölen kimseleri,  Allah,  asla bağışlamayacaktır.', 'ان الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم'),
(4580, 47, 35, 'فَلَا تَهِنُوا وَتَدْعُٓوا اِلَى السَّلْمِۗ وَاَنْتُمُ الْاَعْلَوْنَۗ وَاللّٰهُ مَعَكُمْ وَلَنْ يَتِرَكُمْ اَعْمَالَكُمْ', 'Fe la tehinu ve ted\'u iles selmi ve entumul a\'levne vallahu meakum ve len yetirekum a\'malekum.', 'O halde gevşemeyin ve siz üstünken barışa çağırmayın. Allah,  sizinle beraberdir. Yaptıklarınızı asla boşa çıkarmayacaktır.', 'فلا تهنوا وتدعوا الي السلم وانتم الاعلون والله معكم ولن يتركم اعملكم'),
(4581, 47, 36, 'اِنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَلَهْوٌۜ وَاِنْ تُؤْمِنُوا وَتَتَّقُوا يُؤْتِكُمْ اُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ اَمْوَالَكُمْ', 'İnnemel hayatud dunya laibun ve lehv, ve in tu\'minu ve tetteku yu\'tikum ucurekum ve la yes\'elkum emvalekum.', 'Dünya hayatı yalnızca bir oyun ve eğlencedir. Eğer iman eder ve takva sahibi olursanız,  size ödülleriniz verilir. Ve sizden mallarınızı istemez.', 'انما الحيوة الدنيا لعب ولهو وان تومنوا وتتقوا يوتكم اجوركم ولا يسلكم امولكم'),
(4582, 47, 37, 'اِنْ يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا وَيُخْرِجْ اَضْغَانَكُمْ', 'İn yes\'elkumuha fe yuhfikum tebhalu ve yuhric adganekum.', 'Eğer sizden onu[1] isteyip de sizi zorlasaydı,  cimrilik ederdiniz. Böylece hoşnutsuzluğunuzu açığa çıkarırdı.', 'ان يسلكموها فيحفكم تبخلوا ويخرج اضغنكم'),
(4583, 47, 38, 'هَٓا اَنْتُمْ هٰٓؤُ۬لَٓاءِ تُدْعَوْنَ لِتُنْفِقُوا ف۪ي سَب۪يلِ اللّٰهِۚ فَمِنْكُمْ مَنْ يَبْخَلُۚ وَمَنْ يَبْخَلْ فَاِنَّمَا يَبْخَلُ عَنْ نَفْسِه۪ۜ وَاللّٰهُ الْغَنِيُّ وَاَنْتُمُ الْفُقَـرَٓاءُۚ وَاِنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْماً غَيْرَكُمْۙ ثُمَّ لَا يَكُونُٓوا اَمْثَالَكُمْ', 'Ha entum haulai tud\'avne li tunfiku fi sebilillah, fe minkum men yebhal, ve men yebhal fe innema yebhalu an nefsih, vallahul ganiyyu ve entumul fukarau, ve in tetevellev yestebdil kavmen gayrekum summe la yekunu emsalekum.', 'İşte siz böylesiniz. Allah yolunda infak[1] etmeye çağrılırsınız ancak sizden bir kısmınız cimrilik yapar. Kim cimrilik yaparsa,  aslında kendi aleyhinde cimrilik yapmış olur. Allah zengindir,  siz ise yoksulsunuz. Eğer yüz çevirirseniz,  sizin yerinize başka bir halk getirir. Onlar sizin gibi olmazlar.', 'هانتم هولا تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فانما يبخل عن نفسه والله الغني وانتم الفقرا وان تتولوا يستبدل قوما غيركم ثم لا يكونوا امثلكم'),
(4584, 48, 1, 'اِنَّا فَتَحْنَا لَكَ فَتْحاً مُب۪يناًۙ', 'İnna fetahna leke fethan mubina.', 'Biz,  sana apaçık bir fethin yolunu açtık.', 'انا فتحنا لك فتحا مبينا'),
(4585, 48, 2, 'لِيَغْفِرَ لَكَ اللّٰهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَاَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطاً مُسْتَق۪يماًۙ', 'Li yagfire lekallahu ma tekaddeme min zenbike ve ma teahhare ve yutimme ni\'metehu aleyke ve yehdiyeke sıratan mustekima.', 'Allah,  senin geçmiş ve sonraki suçlarını bağışlasın ve sana nimetini tamamlasın ve seni dosdoğru yola iletsin diye.', 'ليغفر لك الله ما تقدم من ذنبك وما تاخر ويتم نعمته عليك ويهديك صرطا مستقيما'),
(4586, 48, 3, 'وَيَنْصُرَكَ اللّٰهُ نَصْراً عَز۪يزاً', 'Ve yansurekallahu nasran aziza.', 'Ve Allah,  sana çok üstün bir zaferle yardım etsin diye.', 'وينصرك الله نصرا عزيزا'),
(4587, 48, 4, 'هُوَ الَّـذ۪ٓي اَنْزَلَ السَّك۪ينَةَ ف۪ي قُلُوبِ الْمُؤْمِن۪ينَ لِيَزْدَادُٓوا ا۪يمَاناً مَعَ ا۪يمَانِهِمْۜ وَلِلّٰهِ جُنُودُ السَّمٰوَاتِ وَالْاَرْضِۜ وَكَانَ اللّٰهُ عَل۪يماً حَك۪يماًۙ', 'Huvellezi enzeles sekinete fi kulubil mu\'minine li yezdadu imanen mea imanihim, ve lillahi cunudus semavati vel ard, ve kanallahu alimen hakima.', 'İmanları artsın diye,  inananların kalbine sükunet indiren O\'dur. Göklerin ve yerin güçleri Allah\'ındır. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'هو الذي انزل السكينة في قلوب المومنين ليزدادوا ايمنا مع ايمنهم ولله جنود السموت والارض وكان الله عليما حكيما'),
(4588, 48, 5, 'لِيُدْخِلَ الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْۜ وَكَانَ ذٰلِكَ عِنْدَ اللّٰهِ فَوْزاً عَظ۪يماًۙ', 'Li yudhilel mu\'minine vel mu\'minati cennatin tecri min tahtihel enharu halidine fiha ve yukeffire anhum seyyiatihim, ve kane zalike indallahi fevzen azima.', 'Mü\'min erkekleri ve mü\'min kadınları,  içinde sürekli kalmak üzere,  içinden nehirler akan Cennetlere koymak ve kötülüklerini örtmek içindir. İşte Allah\'ın yanında büyük kurtuluş budur.', 'ليدخل المومنين والمومنت جنت تجري من تحتها الانهر خلدين فيها ويكفر عنهم سياتهم وكان ذلك عند الله فوزا عظيما'),
(4589, 48, 6, 'وَيُعَذِّبَ الْمُنَافِق۪ينَ وَالْمُنَافِقَاتِ وَالْمُشْرِك۪ينَ وَالْمُشْرِكَاتِ الظَّٓانّ۪ينَ بِاللّٰهِ ظَنَّ السَّوْءِۜ عَلَيْهِمْ دَٓائِرَةُ السَّوْءِۚ وَغَضِبَ اللّٰهُ عَلَيْهِمْ وَلَعَنَهُمْ وَاَعَدَّ لَهُمْ جَهَنَّمَۜ وَسَٓاءَتْ مَص۪يراً', 'Ve yuazzibel munafikine vel munafikati vel muşrikine vel muşrikatiz zannine billahi zannes sev\'i aleyhim dairetus sev\'i, ve gadiballahu aleyhim ve leanehum ve eadde lehum cehennem, ve saet masira.', 'Allah; hakkında kötü zanda bulunan münafık[1] erkeklere ve kadınlara,  müşrik[2] erkek ve kadınlara azap etsin. Kötü zanları onların üzerlerine dönsün. Allah,  onlara kızdı ve onları lanetledi.[3] Ve onlar için Cehennem\'i hazırladı. Ne kötü bir varış yeri.', 'ويعذب المنفقين والمنفقت والمشركين والمشركت الظانين بالله ظن السو عليهم دايرة السو وغضب الله عليهم ولعنهم واعد لهم جهنم وسات مصيرا'),
(4590, 48, 7, 'وَلِلّٰهِ جُنُودُ السَّمٰوَاتِ وَالْاَرْضِۜ وَكَانَ اللّٰهُ عَز۪يزاً حَك۪يماً', 'Ve lillahi cunudus semavati vel ard, ve kanallahu azizen hakima.', 'Göklerin ve yerin güçleri Allah\'ındır. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ولله جنود السموت والارض وكان الله عزيزا حكيما'),
(4591, 48, 8, 'اِنَّٓا اَرْسَلْنَاكَ شَاهِداً وَمُبَشِّراً وَنَذ۪يراًۙ', 'İnna erselnake şahiden ve mubeşşiren ve nezira.', 'Biz,  seni bir tanık,  haber verici ve uyarıcı olarak gönderdik.', 'انا ارسلنك شهدا ومبشرا ونذيرا'),
(4592, 48, 9, 'لِتُؤْمِنُوا بِاللّٰهِ وَرَسُولِه۪ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۜ وَتُسَبِّحُوهُ بُكْرَةً وَاَص۪يلاً', 'Li tu\'minu billahi ve resulihi ve tuazziruhu ve tuvakkıruh, ve tusebbihuhu bukreten ve asila.', 'Allah\'a ve Resul\'üne iman etmeniz,  O\'na destek olmanız, [1] O\'na saygı göstermeniz ve O\'nu sabah akşam[2] tesbih[3] etmeniz için.', 'لتومنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكرة واصيلا'),
(4593, 48, 10, 'اِنَّ الَّذ۪ينَ يُبَايِعُونَكَ اِنَّمَا يُبَايِعُونَ اللّٰهَۜ يَدُ اللّٰهِ فَوْقَ اَيْد۪يهِمْۚ فَمَنْ نَكَثَ فَاِنَّمَا يَنْكُثُ عَلٰى نَفْسِه۪ۚ وَمَنْ اَوْفٰى بِمَا عَاهَدَ عَلَيْهُ اللّٰهَ فَسَيُؤْت۪يهِ اَجْراً عَظ۪يماً۟', 'İnnellezine yubayiuneke innema yubayiunallah, yedullahi fevka eydihim, fe men nekese fe innema yenkusu ala nefsih, ve men evfa bi ma ahede aleyhullahe fe se yu\'tihi ecren azima.', 'Sana bi\'at[1] edenler,  aslında Allah\'a bi\'at etmişlerdir. Allah\'ın eli[2] onların eli[3] üzerindedir. Kim bağlılığını bozarsa ancak kendi aleyhine bozmuş olur. Kim de Allah\'a verdiği söze bağlı kalırsa,  Allah,  ona büyük bir ödül verecektir.', 'ان الذين يبايعونك انما يبايعون الله يد الله فوق ايديهم فمن نكث فانما ينكث علي نفسه ومن اوفي بما عهد عليه الله فسيوتيه اجرا عظيما'),
(4594, 48, 11, 'سَيَقُولُ لَكَ الْمُخَلَّفُونَ مِنَ الْاَعْرَابِ شَغَلَتْنَٓا اَمْوَالُنَا وَاَهْلُونَا فَاسْتَغْفِرْ لَنَاۚ يَقُولُونَ بِاَلْسِنَتِهِمْ مَا لَيْسَ ف۪ي قُلُوبِهِمْۜ قُلْ فَمَنْ يَمْلِكُ لَكُمْ مِنَ اللّٰهِ شَيْـٔاً اِنْ اَرَادَ بِكُمْ ضَراًّ اَوْ اَرَادَ بِكُمْ نَفْعاًۜ بَلْ كَانَ اللّٰهُ بِمَا تَعْمَلُونَ خَب۪يراً', 'Se yekulu lekel muhallefune minel a\'rabi şegaletna emvaluna ve ehluna festagfir lena, yekulune bi elsinetihim ma leyse fi kulubihim, kul fe men yemliku lekum minallahi şey\'en in erade bikum darren ev erade bikum nef\'a, bel kanallahu bi ma ta\'melune habira.', 'Bedevi Araplardan[1] geri kalanlar[2],  sana: \"Mallarımız ve ailemiz bizim seninle gelmemize engel oldu. Haydi,  Allah\'tan bağışlanmamızı dile.\" diyecekler. Onlar,  kalplerinde olmayanı dilleri ile söylüyorlar. De ki: \"Eğer Allah,  size bir zarar veya yarar dilerse,  buna kim engel olabilir?\" Bilakis,  Allah,  yaptıklarınızdan haberdardır.[3]', 'سيقول لك المخلفون من الاعراب شغلتنا امولنا واهلونا فاستغفر لنا يقولون بالسنتهم ما ليس في قلوبهم قل فمن يملك لكم من الله شيا ان اراد بكم ضرا او اراد بكم نفعا بل كان الله بما تعملون خبيرا'),
(4595, 48, 12, 'بَلْ ظَنَنْتُمْ اَنْ لَنْ يَنْقَلِبَ الرَّسُولُ وَالْمُؤْمِنُونَ اِلٰٓى اَهْل۪يهِمْ اَبَداً وَزُيِّنَ ذٰلِكَ ف۪ي قُلُوبِكُمْ وَظَنَنْتُمْ ظَنَّ السَّوْءِۚ وَكُنْتُمْ قَوْماً بُوراً', 'Bel zanentum en len yenkaliber resulu vel mu\'minune ila ehlihim ebeden ve zuyyine zalike fi kulubikum ve zanentum zannes sev\'i ve kuntum kavmen bura.', 'Hayır! Siz,  Resul ve inananların asla ailelerine dönemeyeceklerini sanmıştınız. Bu zan,  kalplerinize güzel göründü. Kötü bir zanla,  zanda bulundunuz. Siz,  yok olmayı hak eden bir halk oldunuz.', 'بل ظننتم ان لن ينقلب الرسول والمومنون الي اهليهم ابدا وزين ذلك في قلوبكم وظننتم ظن السو وكنتم قوما بورا'),
(4596, 48, 13, 'وَمَنْ لَمْ يُؤْمِنْ بِاللّٰهِ وَرَسُولِه۪ فَاِنَّٓا اَعْتَدْنَا لِلْكَافِر۪ينَ سَع۪يراً', 'Ve men lem yu\'min billahi ve resulihi fe inna a\'tedna lil kafirine saira.', 'Kim Allah\'a ve Resul\'üne inanmazsa[1],  bilsin ki Kafirler[2] için alevli bir ateş hazırladık.', 'ومن لم يومن بالله ورسوله فانا اعتدنا للكفرين سعيرا'),
(4597, 48, 14, 'وَلِلّٰهِ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ يَغْفِرُ لِمَنْ يَشَٓاءُ وَيُعَذِّبُ مَنْ يَشَٓاءُۜ وَكَانَ اللّٰهُ غَفُوراً رَح۪يماً', 'Ve lillahi mulkus semavati vel ard, yagfiru li men yeşau ve yuazzibu men yeşau, ve kanallahu gafuren rahima.', 'Göklerin ve yerin egemenliği Allah\'a aittir. O,  hak edeni[1] bağışlar,  hak edene[1] azap eder. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ولله ملك السموت والارض يغفر لمن يشا ويعذب من يشا وكان الله غفورا رحيما'),
(4598, 48, 15, 'سَيَقُولُ الْمُخَلَّفُونَ اِذَا انْطَلَقْتُمْ اِلٰى مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْۚ يُر۪يدُونَ اَنْ يُبَدِّلُوا كَلَامَ اللّٰهِۜ قُلْ لَنْ تَتَّبِعُونَا كَذٰلِكُمْ قَالَ اللّٰهُ مِنْ قَبْلُۚ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَاۜ بَلْ كَانُوا لَا يَفْقَهُونَ اِلَّا قَل۪يلاً', 'Se yekulul muhallefune izentalaktum ila meganime li te\'huzuha zeruna nettebi\'kum, yuridune en yubeddilu kelamallah, kul len tettebiuna kezalikum kalallahu min kabl, fe se yekulune bel tahsudunena, bel kanu la yefkahune illa kalila.', 'Geri bırakılanlar[1],  ganimetleri almak için gittiğinizde: \"Müsaade edin sizinle gelelim.\" diyecekler. Allah\'ın sözünü[2] değiştirmek istiyorlar. De ki: \"Siz,  asla bizimle gelemezsiniz. Allah,  bu hükmü daha önce buyurmuştu.\"[2] O zaman da: \"Hayır,  siz bizi kıskanıyorsunuz.\" diyecekler. Doğrusu onlar anlayışı kıt kimselerdir.', 'سيقول المخلفون اذا انطلقتم الي مغانم لتاخذوها ذرونا نتبعكم يريدون ان يبدلوا كلم الله قل لن تتبعونا كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون الا قليلا'),
(4599, 48, 16, 'قُلْ لِلْمُخَلَّف۪ينَ مِنَ الْاَعْرَابِ سَتُدْعَوْنَ اِلٰى قَوْمٍ اُو۬ل۪ي بَأْسٍ شَد۪يدٍ تُقَاتِلُونَهُمْ اَوْ يُسْلِمُونَۚ فَاِنْ تُط۪يعُوا يُؤْتِكُمُ اللّٰهُ اَجْراً حَسَناًۚ وَاِنْ تَتَوَلَّوْا كَمَا تَوَلَّيْتُمْ مِنْ قَبْلُ يُعَذِّبْكُمْ عَذَاباً اَل۪يماً', 'Kul lil muhallefine minel a\'rabi setud\'avne ila kavmin uli be\'sin şedidin tukatilunehum ev yuslimun, fe in tutiu yu\'tikumullahu ecren hasena, ve in tetevellev kema tevelleytum min kablu yuazzibkum azaben elima.', 'Bedevi Araplardan[1],  geride kalmayı tercih edenlere de ki: \"Yakında çok güçlü bir halkla savaşmaya çağrılacaksınız,  ya onlarla savaşırsınız ya da onlar teslim olurlar. Bundan sonra,  eğer bu çağrıya uyarsanız Allah size en iyi karşılığı verir. Ama daha önce yan çizdiğiniz gibi yine yan çizecek olursanız,  size acıklı bir azapla,  azap eder.\"', 'قل للمخلفين من الاعراب ستدعون الي قوم اولي باس شديد تقتلونهم او يسلمون فان تطيعوا يوتكم الله اجرا حسنا وان تتولوا كما توليتم من قبل يعذبكم عذابا اليما'),
(4600, 48, 17, 'لَيْسَ عَلَى الْاَعْمٰى حَرَجٌ وَلَا عَلَى الْاَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَر۪يضِ حَرَجٌۜ وَمَنْ يُطِـعِ اللّٰهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۚ وَمَنْ يَتَوَلَّ يُعَذِّبْهُ عَذَاباً اَل۪يماً۟', 'Leyse alel a\'ma haracun ve la alel a\'reci haracun ve la alel maridı harac, ve men yutııllahe ve resulehu yudhılhu cennatin tecri min tahtihel enhar, ve men yetevelle yuazzibhu azaben elima.', 'Köre bir sınırlama yoktur. Sakat olana bir sınırlama yoktur. Hasta olana bir sınırlama yoktur.[1] Kim Allah\'a ve Resul\'üne itaat ederse, [2] Allah,  onları içinden ırmaklar akan Cennetlere koyar. Kim de yan çizerse,  ona acıklı bir azapla azap eder.', 'ليس علي الاعمي حرج ولا علي الاعرج حرج ولا علي المريض حرج ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر ومن يتول يعذبه عذابا اليما'),
(4601, 48, 18, 'لَقَدْ رَضِيَ اللّٰهُ عَنِ الْمُؤْمِن۪ينَ اِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ فَعَلِمَ مَا ف۪ي قُلُوبِهِمْ فَاَنْزَلَ السَّك۪ينَةَ عَلَيْهِمْ وَاَثَابَهُمْ فَتْحاً قَر۪يباًۙ', 'Lekad radiyallahu anil mu\'minine iz yubayiuneke tahteş şecereti fe alime ma fi kulubihim fe enzeles sekinete aleyhim ve esabehum fethan kariba.', 'Ant olsun ki,  o ağacın altında sana bi\'at ettikleri[1] zaman Allah,  inananlardan razı oldu. Onların kalplerinde olanı biliyordu. Onların üzerlerine huzur ve dinginlik indirdi. Onlara yakın bir fetih nasip etti.', 'لقد رضي الله عن المومنين اذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فانزل السكينة عليهم واثبهم فتحا قريبا'),
(4602, 48, 19, 'وَمَغَانِمَ كَث۪يرَةً يَأْخُذُونَهَاۜ وَكَانَ اللّٰهُ عَز۪يزاً حَك۪يماً', 'Ve meganime kesireten ye\'huzuneha, ve kanallahu azizen hakima.', 'Onlara,  elde edecekleri pek çok ganimet nasip etmiştir. Allah,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'ومغانم كثيرة ياخذونها وكان الله عزيزا حكيما'),
(4603, 48, 20, 'وَعَدَكُمُ اللّٰهُ مَغَانِمَ كَث۪يرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هٰذِه۪ وَكَفَّ اَيْدِيَ النَّاسِ عَنْكُمْۚ وَلِتَكُونَ اٰيَةً لِلْمُؤْمِن۪ينَ وَيَهْدِيَكُمْ صِرَاطاً مُسْتَق۪يماًۙ', 'Vaadekumullahu meganime kesireten te\'huzuneha fe accele lekum hazihi ve keffe eydiyen nasi ankum, ve li tekune ayeten lil mu\'minine ve yehdiyekum sıratan mustekima.', 'Allah size,  alacağınız pek çok ganimet sözü verdi. Şimdilik size bunları bahşetti. İnsanların ellerini sizden çekti. İnananlara ayet[1] olsun ve sizi dosdoğru yola iletsin diye.', 'وعدكم الله مغانم كثيرة تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون اية للمومنين ويهديكم صرطا مستقيما'),
(4604, 48, 21, 'وَاُخْرٰى لَمْ تَقْدِرُوا عَلَيْهَا قَدْ اَحَاطَ اللّٰهُ بِهَاۜ وَكَانَ اللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يراً', 'Ve uhra lem takdiru aleyha kad ehatallahu biha, ve kanallahu ala kulli şey\'in kadira.', 'Ve henüz elde edemediğiniz ama Allah\'ın kuşattığı başka şeyler[1] de var. Allah,  Her Şeye Güç Yetiren\'dir.', 'واخري لم تقدروا عليها قد احاط الله بها وكان الله علي كل شي قديرا');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4605, 48, 22, 'وَلَوْ قَاتَلَكُمُ الَّذ۪ينَ كَفَرُوا لَوَلَّوُا الْاَدْبَارَ ثُمَّ لَا يَجِدُونَ وَلِياًّ وَلَا نَص۪يراً', 'Ve lev katelekumullezine keferu le vellevul edbare summe la yecidune veliyyen ve la nasira.', 'Eğer,  Kafirler sizinle savaşsalardı,  arkalarını dönüp kaçarlardı. Sonra da bir veli[1] ve yardımcı bulamazlardı.', 'ولو قتلكم الذين كفروا لولوا الادبر ثم لا يجدون وليا ولا نصيرا'),
(4606, 48, 23, 'سُنَّةَ اللّٰهِ الَّت۪ي قَدْ خَلَتْ مِنْ قَبْلُۚ وَلَنْ تَجِدَ لِسُنَّةِ اللّٰهِ تَبْد۪يلاً', 'Sunnetellahilleti kad halet min kabl, ve len tecide li sunnetillahi tebdila.', 'Bu Allah\'ın öteden beri süregelen yasasıdır. Allah\'ın yasasında asla bir değişiklik bulamazsın.', 'سنة الله التي قد خلت من قبل ولن تجد لسنة الله تبديلا'),
(4607, 48, 24, 'وَهُوَ الَّذ۪ي كَفَّ اَيْدِيَهُمْ عَنْكُمْ وَاَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ مَكَّةَ مِنْ بَعْدِ اَنْ اَظْفَرَكُمْ عَلَيْهِمْۜ وَكَانَ اللّٰهُ بِمَا تَعْمَلُونَ بَص۪يراً', 'Ve huvellezi keffe eydiyehum ankum ve eydiyekum anhum bi batni mekkete min ba\'di en azferekum aleyhim ve kanallahu bi ma ta\'melune basira.', 'Sizi,  Mekke\'nin merkezinde onlara galip kıldıktan sonra,  onların ellerini sizden ve sizin ellerinizi de onlardan çeken O\'dur[1]. Allah,  yaptıklarınızı görendir.', 'وهو الذي كف ايديهم عنكم وايديكم عنهم ببطن مكة من بعد ان اظفركم عليهم وكان الله بما تعملون بصيرا'),
(4608, 48, 25, 'هُمُ الَّذ۪ينَ كَفَرُوا وَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ وَالْهَدْيَ مَعْكُوفاً اَنْ يَبْلُغَ مَحِلَّهُۜ وَلَوْلَا رِجَالٌ مُؤْمِنُونَ وَنِسَٓاءٌ مُؤْمِنَاتٌ لَمْ تَعْلَمُوهُمْ اَنْ تَطَؤُ۫هُمْ فَتُص۪يبَكُمْ مِنْهُمْ مَعَرَّةٌ بِغَيْرِ عِلْمٍۚ لِيُدْخِلَ اللّٰهُ ف۪ي رَحْمَتِه۪ مَنْ يَشَٓاءُۚ لَوْ تَزَيَّلُوا لَعَذَّبْنَا الَّذ۪ينَ كَفَرُوا مِنْهُمْ عَذَاباً اَل۪يماً', 'Humullezine keferu ve saddukum anil mescidil harami vel hedye ma\'kufen en yebluga mahıllehu, ve lev la ricalun mu\'minune ve nisaun mu\'minatun lem ta\'lemuhum en tetauhum fe tusibekum minhum maarratun bi gayri ilm, li yudhılallahu fi rahmetihi men yeşau, lev tezeyyelu le azzebnellezine keferu minhum azaben elima.', 'Onlar,  Kafirlerdir[1]. Sizi Mescid-i Haram\'dan alıkoyan,  ayrılmış kurbanların yerine ulaşmasını engelleyen kimselerdir. Eğer Mü\'min erkeklerden ve kadınlardan olup da kendilerini henüz tanımadığınız için bilmeden onlara zarar vermeniz ve böylece vebale girmeniz söz konusu olmasaydı,  onlarla savaşmanıza izin verilirdi. Allah,  dilediğini rahmetine alır. Eğer birbirlerinden ayrılmış olsalardı elbette onlardan Kafir olanları acı veren bir azapla cezalandırırdık.', 'هم الذين كفروا وصدوكم عن المسجد الحرام والهدي معكوفا ان يبلغ محله ولولا رجال مومنون ونسا مومنت لم تعلموهم ان تطوهم فتصيبكم منهم معرة بغير علم ليدخل الله في رحمته من يشا لو تزيلوا لعذبنا الذين كفروا منهم عذابا اليما'),
(4609, 48, 26, 'اِذْ جَعَلَ الَّذ۪ينَ كَفَرُوا ف۪ي قُلُوبِهِمُ الْحَمِيَّةَ حَمِيَّةَ الْجَاهِلِيَّةِ فَاَنْزَلَ اللّٰهُ سَك۪ينَتَهُ عَلٰى رَسُولِه۪ وَعَلَى الْمُؤْمِن۪ينَ وَاَلْزَمَهُمْ كَلِمَةَ التَّقْوٰى وَكَانُٓوا اَحَقَّ بِهَا وَاَهْلَهَاۜ وَكَانَ اللّٰهُ بِكُلِّ شَيْءٍ عَل۪يماً۟', 'İz cealellezine keferu fi kulubihimul hamiyyete hamiyyetel cahiliyyeti fe enzelallahu sekinetehu ala resulihi ve alel mu\'minine ve elzemehum kelimetet takva ve kanu e hakka biha ve ehleha ve kanallahu bi kulli şey\'in alima.', 'Kafirler,  küçük görme taassubunu,  cahiliye taassubunu kalplerinde taşıyorlardı. Allah da Resulünün ve Mü\'minlerin üzerine dinginlik indirdi. Onları takva sözüne bağlı kıldı. Zaten onlar buna layık ve ehildiler. Allah,  Her Şeyi En İyi Bilen\'dir.', 'اذ جعل الذين كفروا في قلوبهم الحمية حمية الجهلية فانزل الله سكينته علي رسوله وعلي المومنين والزمهم كلمة التقوي وكانوا احق بها واهلها وكان الله بكل شي عليما'),
(4610, 48, 27, 'لَقَدْ صَدَقَ اللّٰهُ رَسُولَهُ الرُّءْيَا بِالْحَقِّۚ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ اِنْ شَٓاءَ اللّٰهُ اٰمِن۪ينَۙ مُحَلِّق۪ينَ رُؤُ۫سَكُمْ وَمُقَصِّر۪ينَۙ لَا تَخَافُونَۜ فَعَلِمَ مَا لَمْ تَعْلَمُوا فَجَعَلَ مِنْ دُونِ ذٰلِكَ فَتْحاً قَر۪يباً', 'Lekad sadakallahu resulehur ru\'ya bil hakk, le tedhulunnel mescidel harame inşaallahu aminine muhallikine ruusekum ve mukassırine la tehafun, fe alime ma lem ta\'lemu fe ceale min duni zalike fethan kariba.', 'Ant olsun ki Allah,  Resulünün rüyasını hakk[1] ile doğruladı. Allah dilerse,  Mescid-i Haram\'a başlarınız tıraş edilmiş ve saçlarınız kısaltılmış olarak korkmadan güven içinde gireceksiniz. Allah,  sizin bilmediğiniz şeyleri biliyordu. Bundan başka size yakın bir fetih takdir etti.', 'لقد صدق الله رسوله الريا بالحق لتدخلن المسجد الحرام ان شا الله امنين محلقين روسكم ومقصرين لا تخافون فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا'),
(4611, 48, 28, 'هُوَ الَّـذ۪ٓي اَرْسَلَ رَسُولَهُ بِالْهُدٰى وَد۪ينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدّ۪ينِ كُلِّه۪ۜ وَكَفٰى بِاللّٰهِ شَه۪يداًۜ', 'Huvellezi ersele resulehu bil huda ve dinil hakkı li yuzhirehu aled dini kullih, ve kefa billahi şehida.', 'Gerçek dini[1] açıkça ortaya koymak için Resul\'ünü doğru yol göstericisi ve gerçek din ile gönderen O\'dur. Tanık olarak Allah yeter.', 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا'),
(4612, 48, 29, 'مُحَمَّدٌ رَسُولُ اللّٰهِۜ وَالَّذ۪ينَ مَعَهُٓ  اَشِدَّٓاءُ عَلَى الْكُفَّارِ رُحَمَٓاءُ بَيْنَهُمْ تَرٰيهُمْ رُكَّعاً سُجَّداً يَبْتَغُونَ فَضْلاً مِنَ اللّٰهِ وَرِضْوَاناًۘ س۪يمَاهُمْ ف۪ي وُجُوهِهِمْ مِنْ اَثَرِ السُّجُودِۜ ذٰلِكَ مَثَلُهُمْ فِي التَّوْرٰيةِۚۛ وَمَثَلُهُمْ فِي الْاِنْج۪يلِ۠ۛ   كَزَرْعٍ اَخْرَجَ شَطْـَٔهُ۫ فَاٰزَرَهُ فَاسْتَغْلَظَ فَاسْتَوٰى عَلٰى سُوقِه۪ يُعْجِبُ الزُّرَّاعَ لِيَغ۪يظَ بِهِمُ الْكُفَّارَۜ وَعَدَ اللّٰهُ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنْهُمْ مَغْفِرَةً وَاَجْراً عَظ۪يماً', 'Muhammedun resulullah, vellezine meahu eşiddau alel kuffari ruhamau beynehum terahum rukkean succeden yebtegune fadlen minallahi ve rıdvanen simahum fi vucuhihim min eseris sucud, zalike meseluhum fit tevrat, ve meseluhum fil incil, ke zer\'in ahrece şat\'ehu fe azerehu festagleza festeva ala sukıhi yu\'cibuz zurraa, li yagiza bihimul kuffar, vaadallahullezine amenu ve amilus salihati minhum magfireten ve ecren azima.', 'Muhammed,  Allah\'ın Resulüdür. Onunla beraber olanlar,  Kafirlere[1] karşı sert,  birbirlerine çok merhametlidirler. Onları; rüku ederken[2],  secde ederken[3] ve Allah\'tan bağışlanma ve hoşnutluk isterlerken görürsün. Onların belirtileri,  yüzlerindeki secde izleridir.[4] İşte bunlar,  onların Tevrat\'taki örnekleridir. İncil\'deki örnekleri de filizini yarıp çıkaran,  sonra onu güçlendirerek kalınlaşıp,  gövdesi üzerinde yükselen ekin gibidir. Bu,  ekincilerin hoşuna gider. Allah,  Kafirlere onlarla üzüntü vermektedir. Allah,  inanıp salihatı[5] yapan kimselere bağışlanma ve büyük bir ödül sözü vermiştir.', 'محمد رسول الله والذين معه اشدا علي الكفار رحما بينهم تريهم ركعا سجدا يبتغون فضلا من الله ورضونا سيماهم في وجوههم من اثر السجود ذلك مثلهم في التورية ومثلهم في الانجيل كزرع اخرج شطه فازره فاستغلظ فاستوي علي سوقه يعجب الزراع ليغيظ بهم الكفار وعد الله الذين امنوا وعملوا الصلحت منهم مغفرة واجرا عظيما'),
(4613, 49, 1, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللّٰهِ وَرَسُولِه۪ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ سَم۪يعٌ عَل۪يمٌ', 'Ya eyyuhellezine amenu la tukaddimu beyne yedeyillahi ve resulihi vettekullah, innallahe semiun alim.', 'Ey iman edenler! Allah\'ın ve Resul\'ünün iki eli arasında öne geçmeyin[1]. Allah\'a için takva[2] sahibi olun. Kuşkusuz Allah,  Her Şeyi Duyan\'dır,  Her Şeyi Bilen\'dir.', 'يايها الذين امنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم'),
(4614, 49, 2, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَرْفَعُٓوا اَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلَا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ اَنْ تَحْبَطَ اَعْمَالُكُمْ وَاَنْتُمْ لَا تَشْعُرُونَ', 'Ya eyyuhellezine amenu la terfeu asvatekum fevka savtin nebiyyi ve la techeru lehu bil kavli ke cehri ba\'dıkum li ba\'dın en tahbeta a\'malukum ve entum la teş\'urun.', 'Ey inananlar! Sesinizi,  Nebi\'nin sesinden daha fazla yükseltmeyin. Birbirinizle bağrışarak konuştuğunuz gibi,  Nebi\'yle yüksek sesle konuşmayın. Yoksa farkında olmadan yaptıklarınız boşa gider.', 'يايها الذين امنوا لا ترفعوا اصوتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعملكم وانتم لا تشعرون'),
(4615, 49, 3, 'اِنَّ الَّذ۪ينَ يَغُضُّونَ اَصْوَاتَهُمْ عِنْدَ رَسُولِ اللّٰهِ اُو۬لٰٓئِكَ الَّذ۪ينَ امْتَحَنَ اللّٰهُ قُلُوبَهُمْ لِلتَّقْوٰىۜ لَهُمْ مَغْفِرَةٌ وَاَجْرٌ عَظ۪يمٌ', 'İnnellezine yeguddune asvatehum inde resulillahi ulaikel lezinemtehanallahu kulubehum lit takva lehum magfiretun ve ecrun azim.', 'Allah\'ın Resulünün yanında kısık sesle konuşanlar; işte onlar,  Allah\'ın takva için kalplerini sınav ettiği kimselerdir. Onlar için bağışlanma ve büyük ödül vardır.', 'ان الذين يغضون اصوتهم عند رسول الله اوليك الذين امتحن الله قلوبهم للتقوي لهم مغفرة واجر عظيم'),
(4616, 49, 4, 'اِنَّ الَّذ۪ينَ يُنَادُونَكَ مِنْ وَرَٓاءِ الْحُجُرَاتِ اَكْثَرُهُمْ لَا يَعْقِلُونَ', 'İnnellezine yunaduneke min verail hucurati ekseruhum la ya\'kılun.', 'Sana odaların dışından seslenenlerin çoğu,  düşüncesiz kimselerdir.', 'ان الذين ينادونك من ورا الحجرات اكثرهم لا يعقلون'),
(4617, 49, 5, 'وَلَوْ اَنَّهُمْ صَبَرُوا حَتّٰى تَخْرُجَ اِلَيْهِمْ لَكَانَ خَيْراً لَهُمْۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Ve lev ennehum saberu hatta tahruce ileyhim le kane hayren lehum, vallahu gafurun rahim.', 'Eğer onlar,  sen yanlarına çıkıncaya kadar sabredip bekleselerdi,  elbette daha iyi olurdu. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ولو انهم صبروا حتي تخرج اليهم لكان خيرا لهم والله غفور رحيم'),
(4618, 49, 6, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنْ جَٓاءَكُمْ فَاسِقٌ بِنَبَأٍ۬ فَتَبَيَّنُٓوا اَنْ تُص۪يبُوا قَوْماً بِجَهَالَةٍ فَتُصْبِحُوا عَلٰى مَا فَعَلْتُمْ نَادِم۪ينَ', 'Ya eyyuhellezine amenu in caekum fasikun bi nebein fe tebeyyenu en tusibu kavmen bi cehaletin fe tusbihu ala ma fealtum nadimin.', 'Ey iman edenler! Eğer fasık[1] bir kimse,  size bir haber getirirse doğru olup olmadığını araştırın. Yoksa bir topluma cahilce kötülük edersiniz de sonra yaptığınız şeye pişman olursunuz.[2]', 'يايها الذين امنوا ان جاكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهلة فتصبحوا علي ما فعلتم ندمين'),
(4619, 49, 7, 'وَاعْلَمُٓوا اَنَّ ف۪يكُمْ رَسُولَ اللّٰهِۜ لَوْ يُط۪يعُكُمْ ف۪ي كَث۪يرٍ مِنَ الْاَمْرِ لَعَنِتُّمْ وَلٰكِنَّ اللّٰهَ حَبَّبَ اِلَيْكُمُ الْا۪يمَانَ وَزَيَّـنَهُ ف۪ي قُلُوبِكُمْ وَكَرَّهَ اِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَۜ  اُو۬لٰٓئِكَ هُمُ الرَّاشِدُونَۙ', 'Va\'lemu enne fikum resulallah, lev yutiukum fi kesirin minel emri le anittum ve lakinnallahe habbebe ileykumul imane ve zeyyenehu fi kulubikum, ve kerrehe ileykumul kufre vel fusuka vel isyan, ulaike humur raşidun.', 'Allah\'ın Resul\'ünün aranızda olduğunu unutmayın. Eğer birçok işte size uysaydı kesinlikle sıkıntıya düşerdiniz. Fakat Allah,  size imanı sevdirdi ve kalplerinizi onunla güzelleştirdi; küfürden,  fasıklıktan ve isyandan nefret ettirdi. İşte bunlardır seçimlerini doğru yapmış olanlar.', 'واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمن وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اوليك هم الرشدون'),
(4620, 49, 8, 'فَضْلاً مِنَ اللّٰهِ وَنِعْمَةًۜ وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Fadlen minallahi ve ni\'meh, vallahu alimun hakim.', 'Bu,  Allah\'tan bir lütuf ve nimettir. Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'فضلا من الله ونعمة والله عليم حكيم'),
(4621, 49, 9, 'وَاِنْ طَٓائِفَتَانِ مِنَ الْمُؤْمِن۪ينَ اقْتَتَلُوا فَاَصْلِحُوا بَيْنَهُمَاۚ فَاِنْ بَغَتْ اِحْدٰيهُمَا عَلَى الْاُخْرٰى فَقَاتِلُوا الَّت۪ي تَبْغ۪ي حَتّٰى تَف۪ٓيءَ اِلٰٓى اَمْرِ اللّٰهِۚ فَاِنْ فَٓاءَتْ فَاَصْلِحُوا بَيْنَهُمَا بِالْعَدْلِ وَاَقْسِطُواۜ اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِط۪ينَ', 'Ve in taifetani minel mu\'mininektetelu fe aslihu beyne huma, fe in begat ihdahuma alel uhra fe katilulleti tebgi hatta tefie ila emrillah, fe in faet fe aslihu beynehuma bil adli ve aksitu, innallahe yuhıbbul muksitin.', 'Eğer Mü\'minlerden iki grup birbirleriyle vuruşurlarsa,  hemen aralarını düzeltin. Eğer ikisinden biri,  diğerine saldırırsa,  saldırgan olanlarla,  Allah\'ın emirlerine uygun davranıncaya kadar savaşın. Eğer böyle davranmaktan vazgeçerlerse o zaman adaletle aralarını düzeltin ve hakkaniyetli olun. Allah,  haktan yana olanları sever.', 'وان طايفتان من المومنين اقتتلوا فاصلحوا بينهما فان بغت احديهما علي الاخري فقتلوا التي تبغي حتي تفي الي امر الله فان فات فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين'),
(4622, 49, 10, 'اِنَّمَا الْمُؤْمِنُونَ اِخْوَةٌ فَاَصْلِحُوا بَيْنَ اَخَوَيْكُمْ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُرْحَمُونَ۟', 'İnnemel mu\'minune ihvetun fe aslihu beyne ehaveykum vettekullahe leallekum turhamun.', 'İnananlar ancak kardeştir. Öyleyse kardeşlerinizin arasını düzeltin. Allah\'a için takva sahibi olun. Umulur ki böylece merhamet olunursunuz.', 'انما المومنون اخوة فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون'),
(4623, 49, 11, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ عَسٰٓى اَنْ يَكُونُوا خَيْراً مِنْهُمْ وَلَا نِسَٓاءٌ مِنْ نِسَٓاءٍ عَسٰٓى اَنْ يَكُنَّ خَيْراً مِنْهُنَّۚ وَلَا تَلْمِزُٓوا اَنْفُسَكُمْ وَلَا تَنَابَزُوا بِالْاَلْقَابِۜ بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْا۪يمَانِۚ وَمَنْ لَمْ يَتُبْ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'Ya eyyuhellezine amenu la yeshar kavmun min kavmin asa en yekunu hayren minhum ve la nisaun min nisain asa en yekunne hayren minhunn, ve la telmizu enfusekum ve la tenabezu bil elkab, bi\'sel ismul fusuku ba\'del iman, ve men lem yetub, fe ulaike humuz zalimun.', 'Ey iman edenler! Bir halk başka bir halkla alay etmesin. Belki alay edilenler,  alay edenlerden daha hayırlıdırlar. Kadınlar da başka kadınlarla alay etmesinler. Belki alay edilen kadınlar,  alay edenlerden daha iyidirler. Birbirinizde kusur aramayın. Birbirinize kötü lakaplar takmayın. İmandan sonra fasık olarak nitelendirilmek ne kötüdür. Kim tevbe etmezse[1] işte onlar zalimdirler.', 'يايها الذين امنوا لا يسخر قوم من قوم عسي ان يكونوا خيرا منهم ولا نسا من نسا عسي ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقب بيس الاسم الفسوق بعد الايمن ومن لم يتب فاوليك هم الظلمون'),
(4624, 49, 12, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اجْتَنِبُوا كَث۪يراً مِنَ الظَّنِّۚ اِنَّ بَعْضَ الظَّنِّ اِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضاًۜ اَيُحِبُّ اَحَدُكُمْ اَنْ يَأْكُلَ لَحْمَ اَخ۪يهِ مَيْتاً فَكَرِهْتُمُوهُۜ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ تَـوَّابٌ رَح۪يمٌ', 'Ya eyyyuhellezine amenuctenibu kesiran minez zanni, inne ba\'daz zanni ismun, ve la tecessesu ve la yagteb ba\'dukum ba\'da, e yuhıbbu ehadukum en ye\'kule lahme ahihi meyten fe kerihtumuh, vettekullah, innallahe tevvabun rahim.', 'Ey inananlar! Zannın[1] birçoğundan sakının. Kuşkusuz bazı zanlar günahtır. Birbirinizin kusurlarını araştırmayın. Bir kısmınız,  bir kısmınızın gıybetini[2] yapmasın. Hiç sizden biriniz,  ölmüş kardeşinin etini yemekten hoşlanır mı? Elbette ondan tiksinirsiniz. Öyleyse Allah\'a için takva[3] sahibi olun. Kuşkusuz Allah,  Tevbeleri Kabul Eden\'dir,  Rahmeti Kesintisiz\'dir.', 'يايها الذين امنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم'),
(4625, 49, 13, 'يَٓا اَيُّهَا النَّاسُ اِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَاُنْثٰى وَجَعَلْنَاكُمْ شُعُوباً وَقَـبَٓائِلَ لِتَعَارَفُواۜ اِنَّ اَكْرَمَكُمْ عِنْدَ اللّٰهِ اَتْقٰيكُمْۜ اِنَّ اللّٰهَ عَل۪يمٌ خَب۪يرٌ', 'Ya eyyuhen nasu inna halaknakum min zekerin ve unsa ve cealnakum şuuben ve kabaile li tearefu, inne ekremekum indallahi etkakum, innallahe alimun habir.', 'Ey insanlar! Sizi bir erkek ve bir dişiden yarattık. Birbirinizle tanışmanız[1] için sizi kabilelere ve sülalelere ayırdık. Allah\'ın yanında en kerim[2] olanınız,  en çok takva sahibi olanınızdır. Kuşkusuz Allah,  Her Şeyi Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'يايها الناس انا خلقنكم من ذكر وانثي وجعلنكم شعوبا وقبايل لتعارفوا ان اكرمكم عند الله اتقيكم ان الله عليم خبير'),
(4626, 49, 14, 'قَالَتِ الْاَعْرَابُ اٰمَنَّاۜ قُلْ لَمْ تُؤْمِنُوا وَلٰكِنْ قُولُٓوا اَسْلَمْنَا وَلَمَّا يَدْخُلِ الْا۪يمَانُ ف۪ي قُلُوبِكُمْۜ وَاِنْ تُط۪يعُوا اللّٰهَ وَرَسُولَهُ لَا يَلِتْكُمْ مِنْ اَعْمَالِكُمْ شَيْـٔاًۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Kaletil a\'rabu amenna, kul lem tu\'minu ve lakin kulu eslemna ve lemma yedhulil imanu fi kulubikum, ve in tutiullahe ve resulehu la yelitkum min a\'malikum şey\'a, innallahe gafurun rahim.', 'Bedevi Araplar,  \"İnandık.\" dediler. De ki: \"Siz inanmadınız,  fakat teslim[1] olduk,  deyin. Çünkü henüz iman kalbinize girmedi. Eğer Allah\'a ve Resul\'üne itaat ederseniz,  O,  yaptıklarınızdan hiçbir şeyi eksiltmez.\" Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'قالت الاعراب امنا قل لم تومنوا ولكن قولوا اسلمنا ولما يدخل الايمن في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعملكم شيا ان الله غفور رحيم'),
(4627, 49, 15, 'اِنَّمَا الْمُؤْمِنُونَ الَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَرَسُولِه۪ ثُمَّ لَمْ يَرْتَابُوا وَجَاهَدُوا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ ف۪ي سَب۪يلِ اللّٰهِۜ اُو۬لٰٓئِكَ هُمُ الصَّادِقُونَ', 'İnnemel mu\'minunellezine amenu billahi ve resulihi summe lem yertabu ve cahedu bi emvalihim ve enfusihim fi sebilillah, ulaike humus sadikun.', 'Mü\'minler,  ancak Allah\'a ve Resul\'üne iman eden,  sonra kesinlikle hiçbir kuşkuya yer vermeyen; malları ve canlarıyla Allah yolunda cihad eden kimselerdir. Onlar,  özü ve sözü bir olanlardır.', 'انما المومنون الذين امنوا بالله ورسوله ثم لم يرتابوا وجهدوا بامولهم وانفسهم في سبيل الله اوليك هم الصدقون'),
(4628, 49, 16, 'قُلْ اَتُعَلِّمُونَ اللّٰهَ بِد۪ينِكُمْ وَاللّٰهُ يَعْلَمُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Kul etualli munallahe bi dinikum vallahu ya\'lemu ma fis semavati ve ma fil ard, vallahu bi kulli şey\'in alim.', 'De ki: \"Dininizi Allah\'a mı öğretiyorsunuz? Allah,  göklerde olanları da yerde olanları da bilir. Allah,  Her Şeyi En İyi Bilen\'dir.\"', 'قل اتعلمون الله بدينكم والله يعلم ما في السموت وما في الارض والله بكل شي عليم'),
(4629, 49, 17, 'يَمُنُّونَ عَلَيْكَ اَنْ اَسْلَمُواۜ قُلْ لَا تَمُنُّوا عَلَيَّ اِسْلَامَكُمْۚ بَلِ اللّٰهُ يَمُنُّ عَلَيْكُمْ اَنْ هَدٰيكُمْ لِلْا۪يمَانِ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Yemunnune aleyke en eslemu kul la temunnu aleyye islamekum, belillahu yemunnu aleykum en hedakum lil imani in kuntum sadikin.', 'Onlar,  teslim olmalarını başına kakıyorlar. De ki: \"İslam\'a boyun eğdiniz diye,  benden minnet beklemeyin. Bilakis,  eğer özü-sözü bir kimselerseniz,  sizi imana erdirdiği için,  siz Allah\'a minnet duyun.\"', 'يمنون عليك ان اسلموا قل لا تمنوا علي اسلمكم بل الله يمن عليكم ان هديكم للايمن ان كنتم صدقين'),
(4630, 49, 18, 'اِنَّ اللّٰهَ يَعْلَمُ غَيْبَ السَّمٰوَاتِ وَالْاَرْضِۜ وَاللّٰهُ بَص۪يرٌ بِمَا تَعْمَلُونَ', 'İnnallahe ya\'lemu gaybes semavati vel ard, vallahu basirun bima ta\'melun.', 'Allah,  göklerin ve yerin gaybını bilir. Allah,  yaptıklarınızı görendir.', 'ان الله يعلم غيب السموت والارض والله بصير بما تعملون'),
(4631, 50, 1, 'قٓ۠ وَالْقُرْاٰنِ الْمَج۪يدِۚ', 'Kaf vel kur\'anil mecid.', 'Kaf. Mecid[1] Kur\'an\'a ant olsun.', 'ق والقران المجيد'),
(4632, 50, 2, 'بَلْ عَجِبُٓوا اَنْ جَٓاءَهُمْ مُنْذِرٌ مِنْهُمْ فَقَالَ الْـكَافِرُونَ هٰذَا شَيْءٌ عَج۪يبٌ', 'Bel acibu en caehum munzirun minhum fe kalel kafirune haza şey\'un acibun.', 'Ama kendilerinden bir uyarıcının onlara gelmesine şaşırdılar. Kafirler: \"Bu şaşılacak bir şey.\" dediler.', 'بل عجبوا ان جاهم منذر منهم فقال الكفرون هذا شي عجيب'),
(4633, 50, 3, 'ءَاِذَا مِتْنَا وَكُنَّا تُرَاباًۚ ذٰلِكَ رَجْعٌ بَع۪يدٌ', 'E iza mitna ve kunna turaba, zalike rec\'un baidun.', '\"Biz ölüp,  toprak olduktan sonra mı diriltileceğiz? İşte bu mümkün olmayan bir dönüştür.\" dediler.', 'اذا متنا وكنا ترابا ذلك رجع بعيد'),
(4634, 50, 4, 'قَدْ عَلِمْنَا مَا تَنْقُصُ الْاَرْضُ مِنْهُمْۚ وَعِنْدَنَا كِتَابٌ حَف۪يظٌ', 'Kad alimna ma tenkusul ardu minhum, ve indena kitabun hafizun.', 'Biz,  yerin onlardan neyi eksilttiğini elbette biliyoruz. Yanımızda her şeyi kayda alan bir Kitap vardır.', 'قد علمنا ما تنقص الارض منهم وعندنا كتب حفيظ'),
(4635, 50, 5, 'بَلْ كَذَّبُوا بِالْحَقِّ لَمَّا جَٓاءَهُمْ فَهُمْ ف۪ٓي اَمْرٍ مَر۪يجٍ', 'Bel kezzebu bil hakkı lemma caehum fe hum fi emrin mericin.', 'Ne var ki onlar,  kendilerine Hakk[1] gelince onu yalanladılar. Bu yüzden karmakarışık bir durumdalar.', 'بل كذبوا بالحق لما جاهم فهم في امر مريج'),
(4636, 50, 6, 'اَفَلَمْ يَنْظُرُٓوا اِلَى السَّمَٓاءِ فَوْقَهُمْ كَيْفَ بَنَيْنَاهَا وَزَيَّنَّاهَا وَمَا لَهَا مِنْ فُرُوجٍ', 'E fe lem yanzuru iles semai fevkahum keyfe beneynaha ve zeyyennaha ve ma leha min furucin.', 'Öyleyse üzerlerindeki göğe bakmıyorlar mı ki,  onu hiçbir çatlağı olmaksızın nasıl bina etmişiz,  nasıl süslemişiz!', 'افلم ينظروا الي السما فوقهم كيف بنينها وزينها وما لها من فروج'),
(4637, 50, 7, 'وَالْاَرْضَ مَدَدْنَاهَا وَاَلْقَيْنَا ف۪يهَا رَوَاسِيَ وَاَنْبَتْنَا ف۪يهَا مِنْ كُلِّ زَوْجٍ بَه۪يجٍۙ', 'Vel arda medednaha ve elkayna fiha revasiye ve enbetna fiha min kulli zevcin behicin.', 'Ve yine yeryüzünü döşedik,  oraya ağır baskılar yerleştirdik. Ve orada her çeşitten göz alıcı çiftler yetiştirdik.', 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل زوج بهيج'),
(4638, 50, 8, 'تَبْصِرَةً وَذِكْرٰى لِكُلِّ عَبْدٍ مُن۪يبٍ', 'Tebsıraten ve zikra li kulli abdin munibin.', 'Bunları,  Allah\'a yönelen kulların basiretini[1] açmak ve öğüt olması için yaptık.', 'تبصرة وذكري لكل عبد منيب'),
(4639, 50, 9, 'وَنَزَّلْنَا مِنَ السَّمَٓاءِ مَٓاءً مُبَارَكاً فَاَنْبَتْنَا بِه۪ جَنَّاتٍ وَحَبَّ الْحَص۪يدِۙ', 'Ve nezzelna mines semai maen mubareken fe enbetna bihi cennatin ve habbel hasidi.', 'Gökten bereketli su indirdik. Onunla cennetler[1] ve biçilecek ekinler yetiştirdik.', 'ونزلنا من السما ما مبركا فانبتنا به جنت وحب الحصيد'),
(4640, 50, 10, 'وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَض۪يدٌۙ', 'Ven nahle basikatin leha tal\'un nadidun.', 'Ve salkımları üst üste yığılmış,  uzun hurma ağaçları.', 'والنخل باسقت لها طلع نضيد'),
(4641, 50, 11, 'رِزْقاً لِلْعِبَادِۙ وَاَحْيَيْنَا بِه۪ بَلْدَةً مَيْتاًۜ  كَذٰلِكَ الْخُرُوجُ', 'Rızkan lil ibadi ve ahyeyna bihi beldeten meyta, kezalikel hurucu.', 'Kullar için rızık olarak. Onunla ölü bir beldeye hayat verdik. İşte yeniden diriliş de böyledir.', 'رزقا للعباد واحيينا به بلدة ميتا كذلك الخروج'),
(4642, 50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَاَصْحَابُ الرَّسِّ وَثَمُودُۙ', 'Kezzebet kablehum kavmu nuhın ve ashabur ressi ve semudu.', 'Onlardan önce Nuh halkı,  Ress\'liler ve Semud yalanlamıştı.', 'كذبت قبلهم قوم نوح واصحب الرس وثمود'),
(4643, 50, 13, 'وَعَادٌ وَفِرْعَوْنُ وَاِخْوَانُ لُوطٍۙ', 'Ve adun ve fir\'avnu ve ihvanu lutın.', 'Ve Âd,  Firavun ve Lut\'un kardeşleri de.', 'وعاد وفرعون واخون لوط'),
(4644, 50, 14, 'وَاَصْحَابُ الْاَيْكَةِ وَقَوْمُ تُبَّعٍۜ  كُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَع۪يدِ', 'Ve ashabul eyketi ve kavmu tubbain, kullun kezzeber rusule fe hakka vaidi.', 'Ve Eykeliler ve Tubba halkı. Hepsi resulleri yalanladılar. Böylece uyarım gerçekleşti.', 'واصحب الايكة وقوم تبع كل كذب الرسل فحق وعيد'),
(4645, 50, 15, 'اَفَعَي۪ينَا بِالْخَلْقِ الْاَوَّلِۜ بَلْ هُمْ ف۪ي لَبْسٍ مِنْ خَلْقٍ جَد۪يدٍ۟', 'E fe ayina bil halkıl evvel, bel hum fi lebsin min halkın cedid.', 'İlk yaratışta yetersiz kaldık mı ki yeniden yaratılıştan şüphe içindeler!', 'افعيينا بالخلق الاول بل هم في لبس من خلق جديد'),
(4646, 50, 16, 'وَلَقَدْ خَلَقْنَا الْاِنْسَانَ وَنَعْلَمُ مَا تُوَسْوِسُ بِه۪ نَفْسُهُۚ وَنَحْنُ اَقْرَبُ اِلَيْهِ مِنْ حَبْلِ الْوَر۪يدِ', 'Ve lekad halaknel insane ve na\'lemu ma tuvesvisu bihi nefsuh, ve nahnu akrebu ileyhi min hablil veridi.', 'Ant olsun ki insanı Biz yarattık. Nefsinin ona neler fısıldadığını biliriz. Ve Biz ona \"habl-i verid\"ten[1] daha yakınız.', 'ولقد خلقنا الانسن ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد'),
(4647, 50, 17, 'اِذْ يَتَلَقَّى الْمُتَلَقِّيَانِ عَنِ الْيَم۪ينِ وَعَنِ الشِّمَالِ قَع۪يدٌ', 'İz yetelakkal mutelakkiyani anil yemini ve aniş şimali kaidun.', 'Sağında ve solunda yerleşmiş iki kaydedici,  yaptıklarını kayda geçirmektedirler.', 'اذ يتلقي المتلقيان عن اليمين وعن الشمال قعيد'),
(4648, 50, 18, 'مَا يَلْفِظُ مِنْ قَوْلٍ اِلَّا لَدَيْهِ رَق۪يبٌ عَت۪يدٌ', 'Ma yelfızu min kavlin illa ledeyhi rakibun atidun.', 'Söylediği her söz,  yanındaki hazır gözleyicilerce gözlenmektedir.', 'ما يلفظ من قول الا لديه رقيب عتيد'),
(4649, 50, 19, 'وَجَٓاءَتْ سَكْرَةُ الْمَوْتِ بِالْحَقِّۜ ذٰلِكَ مَا كُنْتَ مِنْهُ تَح۪يدُ', 'Ve caet sekretul mevti bil hakk, zalike ma kunte minhu tehidu.', 'Ölümün sarhoşluğu kaçınılmaz bir gerçek olarak gelince,  \"İşte senin kaçtığın şey budur!\"', 'وجات سكرة الموت بالحق ذلك ما كنت منه تحيد'),
(4650, 50, 20, 'وَنُفِـخَ فِي الصُّورِۜ ذٰلِكَ يَوْمُ الْوَع۪يدِ', 'Ve nufiha fis sur, zalike yevmul vaidi.', 'Ve Sur\'a üfürülür. \" İşte bu,  vaktiyle uyarıldığınız gündür.\"', 'ونفخ في الصور ذلك يوم الوعيد'),
(4651, 50, 21, 'وَجَٓاءَتْ كُلُّ نَفْسٍ مَعَهَا سَٓائِقٌ وَشَه۪يدٌ', 'Ve caet kullu nefsin meaha saikun ve şehidun.', 'Herkes yanında bir sevk edici ve bir tanıkla birlikte gelir.', 'وجات كل نفس معها سايق وشهيد'),
(4652, 50, 22, 'لَقَدْ كُنْتَ ف۪ي غَفْلَةٍ مِنْ هٰذَا فَـكَشَفْنَا عَنْكَ غِطَٓاءَكَ فَبَصَرُكَ الْيَوْمَ حَد۪يدٌ', 'Lekad kunte fi gafletin min haza fe keşefna anke gıtaeke fe besarukel yevme hadidun.', 'Ant olsun ki sen bugünün geleceğinden gaflet içindeydin. İşte senden perdeyi kaldırdık. Artık bugün gerçeği bütün açıklığıyla görüyorsun.', 'لقد كنت في غفلة من هذا فكشفنا عنك غطاك فبصرك اليوم حديد'),
(4653, 50, 23, 'وَقَالَ قَر۪ينُهُ هٰذَا مَا لَدَيَّ عَت۪يدٌۜ', 'Ve kale karinuhu haza ma ledeyye atid.', 'Onun yakını,  \"İşte bu yanımda olan şey hazırdır.\" der.', 'وقال قرينه هذا ما لدي عتيد'),
(4654, 50, 24, 'اَلْقِيَا ف۪ي جَهَنَّمَ كُلَّ كَفَّارٍ عَن۪يدٍۙ', 'Elkıya fi cehenneme kulle keffarin anidin.', '\"İnatçı,  Kafirlerin tamamını Cehennem\'e atın.\"', 'القيا في جهنم كل كفار عنيد'),
(4655, 50, 25, 'مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ مُر۪يبٍۙ', 'Mennaın lil hayri mu\'tedin muribin.', 'Hayra engel olan,  haddi aşan,  güvensizlik içinde olan.', 'مناع للخير معتد مريب'),
(4656, 50, 26, 'اَلَّذ۪ي جَعَلَ مَعَ اللّٰهِ اِلٰهاً اٰخَرَ فَاَلْقِيَاهُ فِي الْعَذَابِ الشَّد۪يدِ', 'Ellezi ceale meallahi ilahen ahara fe elkıyahu fil azabiş şedidi.', 'O,  Allah ile birlikte başka ilah[1] edindi. Öyleyse,  onu şiddetli azaba atın.', 'الذي جعل مع الله الها اخر فالقياه في العذاب الشديد'),
(4657, 50, 27, 'قَالَ قَر۪ينُهُ رَبَّنَا مَٓا اَطْغَيْتُهُ وَلٰكِنْ كَانَ ف۪ي ضَلَالٍ بَع۪يدٍ', 'Kale karinuhu rabbena ma etgaytuhu ve lakin kane fi dalalin baidin.', 'Onun yakını: \"Rabb\'imiz! Onu ben azdırmadım,  fakat o derin bir sapkınlık içindeydi.\" der.', 'قال قرينه ربنا ما اطغيته ولكن كان في ضلل بعيد'),
(4658, 50, 28, 'قَالَ لَا تَخْتَصِمُوا لَدَيَّ وَقَدْ قَدَّمْتُ اِلَيْكُمْ بِالْوَع۪يدِ', 'Kale la tahtesımu ledeyye ve kad kaddemtu ileykum bil vaidi.', '\"Huzurumda çekişmeyin! Size daha önce uyarımı yapmıştım.\" der.', 'قال لا تختصموا لدي وقد قدمت اليكم بالوعيد'),
(4659, 50, 29, 'مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَمَٓا اَنَا۬ بِظَلَّامٍ لِلْعَب۪يدِ۟', 'Ma yubeddelul kavlu ledeyye ve ma ene bi zallamin lil abid.', '\"Katımda söz değiştirilmez. Ben kullara asla haksızlık eden değilim.\"', 'ما يبدل القول لدي وما انا بظلم للعبيد'),
(4660, 50, 30, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَز۪يدٍ', 'Yevme nekulu li cehenneme helimtele\'ti ve tekulu hel min mezidin.', 'O gün,  Cehennem\'e,  \"Doldun mu?\" deriz. O da \"Daha yok mu?\" der.', 'يوم نقول لجهنم هل امتلات وتقول هل من مزيد'),
(4661, 50, 31, 'وَاُزْلِفَتِ الْجَنَّةُ لِلْمُتَّق۪ينَ غَيْرَ بَع۪يدٍ', 'Ve uzlifetil cennetu lil muttekine gayre baidin.', 'Cennet,  takva sahipleri için uzak değil,  yaklaştırılmıştır.', 'وازلفت الجنة للمتقين غير بعيد'),
(4662, 50, 32, 'هٰذَا مَا تُوعَدُونَ لِكُلِّ اَوَّابٍ حَف۪يظٍۚ', 'Haza ma tuadune li kulli evvabin hafiz.', 'İşte size söz verilen şey budur. Yönelen[1] ve koruyanların[1] tamamı içindir.', 'هذا ما توعدون لكل اواب حفيظ'),
(4663, 50, 33, 'مَنْ خَشِيَ الرَّحْمٰنَ بِالْغَيْبِ وَجَٓاءَ بِقَلْبٍ مُن۪يبٍ', 'Men haşiyer rahmane bil gaybi ve cae bi kalbin munibin.', 'Gaybda[1] Allah\'a huşu[2] duyanların,  gönülden bağlı olanların ödülüdür.', 'من خشي الرحمن بالغيب وجا بقلب منيب'),
(4664, 50, 34, 'اُدْخُلُوهَا بِسَلَامٍۜ ذٰلِكَ يَوْمُ الْخُلُودِ', 'Udhuluha bi selam, zalike yevmul hulud.', 'Oraya esenlikle girin. İşte bu süreklilik günüdür.', 'ادخلوها بسلم ذلك يوم الخلود'),
(4665, 50, 35, 'لَهُمْ مَا يَشَٓاؤُ۫نَ ف۪يهَا وَلَدَيْنَا مَز۪يدٌ', 'Lehum ma yeşaune fiha ve ledeyna mezidun.', 'Onlar için,  orada diledikleri her şey vardır. Yanımızda daha fazlası da vardır.', 'لهم ما يشاون فيها ولدينا مزيد'),
(4666, 50, 36, 'وَكَمْ اَهْلَكْنَا قَبْلَهُمْ مِنْ قَرْنٍ هُمْ اَشَدُّ مِنْهُمْ بَطْشاً فَنَقَّبُوا فِي الْبِلَادِۜ هَلْ مِنْ مَح۪يصٍ', 'Ve kem ehlekna kablehum min karnin hum eşeddu minhum batşen fe nakkabu fil bilad, hel min mahisin.', 'Onlardan önce,  kendilerinden daha güçlü nice nesilleri yok ettik. Yok olmaktan kurtulmak için belde belde dolaştılar. Böyleyken sığınacak bir yer buldular mı?', 'وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلد هل من محيص'),
(4667, 50, 37, 'اِنَّ ف۪ي ذٰلِكَ لَذِكْرٰى لِمَنْ كَانَ لَهُ قَلْبٌ اَوْ اَلْقَى السَّمْعَ وَهُوَ شَه۪يدٌ', 'İnne fi zalike le zikra li men kane lehu kalbun ev elkas sem\'a ve huve şehidun.', 'Kuşkusuz bunda kalbi olan ve can kulağıyla dinleyen ve tanık olan kimseler için kesinlikle alınacak öğüt vardır.', 'ان في ذلك لذكري لمن كان له قلب او القي السمع وهو شهيد'),
(4668, 50, 38, 'وَلَقَدْ خَلَقْنَا السَّمٰوَاتِ وَالْاَرْضَ وَمَا بَيْنَهُمَا ف۪ي سِتَّةِ اَيَّامٍۗ وَمَا مَسَّنَا مِنْ لُغُوبٍ', 'Ve lekad halaknes semavati vel arda ve ma beynehuma fi sitteti eyyamin ve ma messena min lugub.', 'Ant olsun ki gökleri,  yeri ve ikisinin arasındakileri bir yorgunluk olmaksızın altı günde[1] yarattık.', 'ولقد خلقنا السموت والارض وما بينهما في ستة ايام وما مسنا من لغوب'),
(4669, 50, 39, 'فَاصْبِرْ عَلٰى مَا يَقُولُونَ وَسَبِّـحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِۚ', 'Fasbir ala ma yekulune ve sebbih bi hamdi rabbike kable tuluış şemsi ve kablel gurub.', 'Onların söyledikleri şeylere sabret. Güneş\'in doğmasından önce ve batmasından önce Rabb\'ini hamd[1] ile tesbih[2] et.', 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب'),
(4670, 50, 40, 'وَمِنَ الَّيْلِ فَسَبِّحْهُ وَاَدْبَارَ السُّجُودِ', 'Ve minel leyli fe sebbihhu ve edbares sucudi.', 'Geceleyin ve secdelerin ardından O\'nu tesbih et.', 'ومن اليل فسبحه وادبر السجود'),
(4671, 50, 41, 'وَاسْتَمِــعْ يَوْمَ يُنَادِ الْمُنَادِ مِنْ مَكَانٍ قَر۪يبٍۙ', 'Vestemi\' yevme yunadil munadi min mekanin karib.', 'Çağırıcının,  yakın bir yerden çağıracağı güne kulak ver.', 'واستمع يوم يناد المناد من مكان قريب'),
(4672, 50, 42, 'يَوْمَ يَسْمَعُونَ الصَّيْحَةَ بِالْحَقِّۜ ذٰلِكَ يَوْمُ الْخُرُوجِ', 'Yevme yesmeunes sayhate bil hakk, zalike yevmul huruci.', 'O gün,  gerçek olan o çığlığı duyarlar. İşte bu yeniden diriliş günüdür.', 'يوم يسمعون الصيحة بالحق ذلك يوم الخروج'),
(4673, 50, 43, 'اِنَّا نَحْنُ نُحْـي۪ وَنُم۪يتُ وَاِلَيْنَا الْمَص۪يرُۙ', 'İnna nahnu nuhyi ve numitu ve ileynel masiru.', 'Biz; ancak Biz hayat veririz ve öldürürüz. Ve dönüş Bizedir.', 'انا نحن نحي ونميت والينا المصير'),
(4674, 50, 44, 'يَوْمَ تَشَقَّقُ الْاَرْضُ عَنْهُمْ سِرَاعاًۜ ذٰلِكَ حَشْرٌ عَلَيْنَا يَس۪يرٌ', 'Yevme teşakkakul ardu anhum siraa, zalike haşrun aleyna yesirun.', 'O gün yer yarılır,  onlar topraktan çabukça ayrılırlar. İşte bu,  Bizim için kolay bir toplamadır.', 'يوم تشقق الارض عنهم سراعا ذلك حشر علينا يسير'),
(4675, 50, 45, 'نَحْنُ اَعْلَمُ بِمَا يَقُولُونَ وَمَٓا اَنْتَ عَلَيْهِمْ بِجَبَّارٍ فَذَكِّرْ بِالْقُرْاٰنِ مَنْ يَخَافُ وَع۪يدِ', 'Nahnu a\'lemu bi ma yekulune ve ma ente aleyhim bi cebbarin fe zekkir bil kur\'ani men yehafu vaidi.', 'Onların ne dediklerini en iyi bileniz. Sen,  onları zorla yola getirecek değilsin. O halde Benim uyarımdan korkan kimselere Kur\'an\'la öğüt ver.', 'نحن اعلم بما يقولون وما انت عليهم بجبار فذكر بالقران من يخاف وعيد'),
(4676, 51, 1, 'وَالذَّارِيَاتِ ذَرْواًۙ', 'Vez zariyati zerven.', 'Esip savuranlara,', 'والذريت ذروا'),
(4677, 51, 2, 'فَالْحَامِلَاتِ وِقْراًۙ', 'Fel hamilati vıkren.', 'Ve yükü taşıyanlara,', 'فالحملت وقرا'),
(4678, 51, 3, 'فَالْجَارِيَاتِ يُسْراًۙ', 'Fel cariyati yusren.', 'Sonra kolayca akıp gidenlere,', 'فالجريت يسرا'),
(4679, 51, 4, 'فَالْمُقَسِّمَاتِ اَمْراًۙ', 'Fel mukassimati, emren.', 'Sonra işi paylaştıranlara ant olsun ki,', 'فالمقسمت امرا'),
(4680, 51, 5, 'اِنَّمَا تُوعَدُونَ لَصَادِقٌۙ', 'İnnema tuadune le sadikun.', 'Uyarıldığınız şey kesinlikle gerçektir.', 'انما توعدون لصادق'),
(4681, 51, 6, 'وَاِنَّ الدّ۪ينَ لَوَاقِـعٌۜ', 'Ve inned dine le vakıu.', 'Kuşkusuz din[1] kesinlikle gerçekleşecektir.', 'وان الدين لوقع'),
(4682, 51, 7, 'وَالسَّمَٓاءِ ذَاتِ الْحُبُكِۙ', 'Ves semai zatil hubuki.', 'Yollara sahip gökyüzüne ant olsun ki,', 'والسما ذات الحبك'),
(4683, 51, 8, 'اِنَّكُمْ لَف۪ي قَوْلٍ مُخْتَلِفٍۙ', 'İnnekum le fi kavlin muhtelifin.', 'Kuşkusuz siz,  söylediklerinizde çelişki içindesiniz.', 'انكم لفي قول مختلف'),
(4684, 51, 9, 'يُؤْفَكُ عَنْهُ مَنْ اُفِكَۜ', 'Yu\'feku anhu men ufik.', 'Döndürülecek kimse,  ondan çevrilir.[1]', 'يوفك عنه من افك'),
(4685, 51, 10, 'قُتِلَ الْخَرَّاصُونَۙ', 'Kutilel harrasune.', 'Kahrolsun yalancılar.[1]', 'قتل الخرصون'),
(4686, 51, 11, 'اَلَّذ۪ينَ هُمْ ف۪ي غَمْرَةٍ سَاهُونَۙ', 'Ellezine hum fi gamretin sahune.', 'Onlar,  cehalet içinde ne yaptığını bilmeyenlerdir.', 'الذين هم في غمرة ساهون'),
(4687, 51, 12, 'يَسْـَٔلُونَ اَيَّانَ يَوْمُ الدّ۪ينِۜ', 'Yes\'elune eyyane yevmud din.', '\"Din Günü[1] ne zaman?\" diye sorarlar.', 'يسلون ايان يوم الدين'),
(4688, 51, 13, 'يَوْمَ هُمْ عَلَى النَّارِ يُفْتَنُونَ', 'Yevme hum alen nari yuftenune.', 'O gün onlar,  ateşe atılacaklar.', 'يوم هم علي النار يفتنون'),
(4689, 51, 14, 'ذُوقُوا فِتْنَتَكُمْۜ هٰذَا الَّذ۪ي كُنْتُمْ بِه۪ تَسْتَعْجِلُونَ', 'Zuku fitnetekum, hazellezi kuntum bihi testa\'cilun.', 'Fitnenizi[1] tadın. Bu,  sizin acele istediğiniz şeydir.', 'ذوقوا فتنتكم هذا الذي كنتم به تستعجلون'),
(4690, 51, 15, 'اِنَّ الْمُتَّق۪ينَ ف۪ي جَنَّاتٍ وَعُيُونٍۙ', 'İnnel muttekine fi cennatin ve uyunin.', 'Takva sahipleri ise cennetlerde[1] ve pınarlardadırlar.', 'ان المتقين في جنت وعيون'),
(4691, 51, 16, 'اٰخِذ۪ينَ مَٓا اٰتٰيهُمْ رَبُّهُمْۜ اِنَّهُمْ كَانُوا قَبْلَ ذٰلِكَ مُحْسِن۪ينَۜ', 'Ahizine ma atahum rabbuhum, innehum kanu kable zalike muhsinin.', 'Rabb\'lerinin kendilerine verdiğini alanlar,  daha önce iyi olanlardır.', 'اخذين ما اتيهم ربهم انهم كانوا قبل ذلك محسنين'),
(4692, 51, 17, 'كَانُوا قَل۪يلاً مِنَ الَّيْلِ مَا يَهْجَعُونَ', 'Kanu kalilen minel leyli ma yehceun.', 'Geceleri pek az uyurlardı.', 'كانوا قليلا من اليل ما يهجعون'),
(4693, 51, 18, 'وَبِالْاَسْحَارِ هُمْ يَسْتَغْفِرُونَ', 'Ve bil esharihum yestağfirune.', 'Onlar seher vakitlerinde bağışlanma dilerlerdi.', 'وبالاسحار هم يستغفرون'),
(4694, 51, 19, 'وَف۪ٓي اَمْوَالِهِمْ حَقٌّ لِلسَّٓائِلِ وَالْمَحْرُومِ', 'Ve fi emvalihim hakkun lis saili vel mahrumi.', 'Mallarından -istesin,  istemesin- ihtiyaç sahipleri için bir pay ayırırlardı.', 'وفي امولهم حق للسايل والمحروم'),
(4695, 51, 20, 'وَفِي الْاَرْضِ اٰيَاتٌ لِلْمُوقِن۪ينَۙ', 'Ve fil ardı ayatun lil mukınine.', 'Gerçeği kavrayanlar için yeryüzünde nice ayetler[1] vardır.', 'وفي الارض ايت للموقنين'),
(4696, 51, 21, 'وَف۪ٓي اَنْفُسِكُمْۜ  اَفَلَا تُبْصِرُونَ', 'Ve fi enfusikum, e fe la tubsirun.', 'Ve kendiniz de ayetsiniz. Hala görmüyor musunuz?', 'وفي انفسكم افلا تبصرون'),
(4697, 51, 22, 'وَفِي السَّمَٓاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', 'Ve fis semai rızkukum ve ma tuadun.', 'Gökte rızkınız ve uyarıldığınız şeyler vardır.', 'وفي السما رزقكم وما توعدون'),
(4698, 51, 23, 'فَوَرَبِّ السَّمَٓاءِ وَالْاَرْضِ اِنَّهُ لَحَقٌّ مِثْلَ مَٓا اَنَّكُمْ تَنْطِقُونَ۟', 'Fe ve rabbis semai vel ardı innehu le hakkun misle ma ennekum tentıkun.', 'Göklerin ve yeryüzünün Rabb\'ine ant olsun ki,  sizin konuşmanız nasıl gerçekse,  kesinlikle o da[1] o kadar gerçektir.', 'فورب السما والارض انه لحق مثل ما انكم تنطقون'),
(4699, 51, 24, 'هَلْ اَتٰيكَ حَد۪يثُ ضَيْفِ اِبْرٰه۪يمَ الْمُكْرَم۪ينَۢ', 'Hel etake hadisu dayfi ibrahimel mukremin.', 'İbrahim\'ın saygın konuklarının hadisi[1] sana geldi mi?', 'هل اتيك حديث ضيف ابرهيم المكرمين'),
(4700, 51, 25, 'اِذْ دَخَلُوا عَلَيْهِ فَقَالُوا سَلَاماًۜ قَالَ سَلَامٌۚ قَوْمٌ مُنْكَرُونَ', 'İz dehalu aleyhi fe kalu selama, kale selam, kavmun munkerun.', 'Onun yanına geldiklerinde,  \"Selam.\" dediler. \"Selam,  tanınmayan topluluk.\" dedi.', 'اذ دخلوا عليه فقالوا سلما قال سلم قوم منكرون'),
(4701, 51, 26, 'فَرَاغَ اِلٰٓى اَهْلِه۪ فَجَٓاءَ بِعِجْلٍ سَم۪ينٍۙ', 'Fe raga ila ehlihi fe cae bi iclin seminin.', 'Habersizce ailesine gidip,  hemen kızarmış buzağı eti getirdi.', 'فراغ الي اهله فجا بعجل سمين'),
(4702, 51, 27, 'فَقَرَّبَهُٓ اِلَيْهِمْ قَالَ اَلَا تَأْكُلُونَۘ', 'Fe karrebehu ileyhim kale e la te\'kulun.', 'Onları buyur ederek: \"Yemez misiniz?\" dedi.', 'فقربه اليهم قال الا تاكلون'),
(4703, 51, 28, 'فَاَوْجَسَ مِنْهُمْ خ۪يفَةًۜ قَالُوا لَا تَخَفْۜ وَبَشَّرُوهُ بِغُلَامٍ عَل۪يمٍ', 'Fe evcese minhum hifeh, kalu la tehaf, ve beşşeruhu bi gulamin alim.', 'Durumlarından dolayı içine bir korku düştü. \"Korkma.\" dediler ve ona bilgin bir çocuk müjdelediler.', 'فاوجس منهم خيفة قالوا لا تخف وبشروه بغلم عليم'),
(4704, 51, 29, 'فَاَقْبَلَتِ امْرَاَتُهُ ف۪ي صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَق۪يمٌ', 'Fe akbeletimreetuhu fi sarretin fe sakket vecheha ve kalet acuzun akimun.', 'Bunun üzerine hanımı şaşkınlık içinde,  yüzüne vurarak yüksek sesle: \"Ben kısır,  ihtiyar bir kadınım.\" dedi.', 'فاقبلت امراته في صرة فصكت وجهها وقالت عجوز عقيم'),
(4705, 51, 30, 'قَالُوا كَذٰلِكِۙ قَالَ رَبُّكِۜ اِنَّهُ هُوَ الْحَك۪يمُ الْعَل۪يمُ', 'Kalu kezaliki kale rabbuk, innehu huvel hakimul alimu.', '\"Senin Rabb\'inin buyurduğu şey işte budur.\" dediler. O,  En İyi Hüküm Veren\'dir,  Her Şeyi Bilen\'dir.', 'قالوا كذلك قال ربك انه هو الحكيم العليم'),
(4706, 51, 31, 'قَالَ فَمَا خَطْبُكُمْ اَيُّهَا الْمُرْسَلُونَ', 'Kale fe ma hatbukum eyyuhel murselun.', 'İbrahim: \"O halde ey elçiler! Sizin geliş amacınız nedir? dedi.', 'قال فما خطبكم ايها المرسلون'),
(4707, 51, 32, 'قَالُٓوا اِنَّٓا اُرْسِلْـنَٓا اِلٰى قَوْمٍ مُجْرِم۪ينَۙ', 'Kalu inna ursilna ila kavmin mucrimine.', '\"Biz,  suçlu bir topluma gönderildik.\" dediler.', 'قالوا انا ارسلنا الي قوم مجرمين'),
(4708, 51, 33, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةً مِنْ ط۪ينٍۙ', 'Li nursile aleyhim hıcareten min tinin.', 'Onların üzerlerine çamurdan pişirilmiş taşlar yağdırmak için.', 'لنرسل عليهم حجارة من طين'),
(4709, 51, 34, 'مُسَوَّمَةً عِنْدَ رَبِّكَ لِلْمُسْرِف۪ينَ', 'Musevvemeten inde rabbike lil musrifin.', 'Onlar Rabb\'inin katından,  aşırı gidenler için olan taşlardır.', 'مسومة عند ربك للمسرفين'),
(4710, 51, 35, 'فَاَخْرَجْنَا مَنْ كَانَ ف۪يهَا مِنَ الْمُؤْمِن۪ينَۚ', 'Fe ahrecna men kane fiha minel mu\'minin.', 'Orada bulunan inananları çıkardık.', 'فاخرجنا من كان فيها من المومنين'),
(4711, 51, 36, 'فَمَا وَجَدْنَا ف۪يهَا غَيْرَ بَيْتٍ مِنَ الْمُسْلِم۪ينَۚ', 'Fe ma vecedna fiha gayre beytin minel muslimin.', 'Fakat orada,  bir evden başkasında,  Müslümanlardan kimse bulamadık.', 'فما وجدنا فيها غير بيت من المسلمين'),
(4712, 51, 37, 'وَتَرَكْنَا ف۪يهَٓا اٰيَةً لِلَّذ۪ينَ يَخَافُونَ الْعَذَابَ الْاَل۪يمَۜ', 'Ve terekna fiha ayeten lillezine yahafunel azabel elim.', 'Orada can yakan azaptan korkanlar için bir ayet[1] bıraktık.', 'وتركنا فيها اية للذين يخافون العذاب الاليم'),
(4713, 51, 38, 'وَف۪ي مُوسٰٓى اِذْ اَرْسَلْنَاهُ اِلٰى فِرْعَوْنَ بِسُلْطَانٍ مُب۪ينٍ', 'Ve fi musa iz erselnahu ila fir\'avne bi sultanin mubinin.', 'Musa\'da da vardır[1]. Onu Firavun\'a apaçık bir sultanla[2] göndermiştik.', 'وفي موسي اذ ارسلنه الي فرعون بسلطن مبين'),
(4714, 51, 39, 'فَتَوَلّٰى بِرُكْنِه۪ وَقَالَ سَاحِرٌ اَوْ مَجْنُونٌ', 'Fe tevella bi ruknihi ve kale sahırun ev mecnunun.', 'Ancak Firavun yüz çevirdi. \"O bir sihirbaz veya delidir.\" dedi.', 'فتولي بركنه وقال سحر او مجنون'),
(4715, 51, 40, 'فَاَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّ وَهُوَ مُل۪يمٌۜ', 'Fe ehaznahu ve cunudehu fe nebeznahum fil yemmi ve huve mulim.', 'Sonra onu ve ordularını yakaladık ve denize attık. Kendi kendini kınıyordu.', 'فاخذنه وجنوده فنبذنهم في اليم وهو مليم'),
(4716, 51, 41, 'وَف۪ي عَادٍ اِذْ اَرْسَلْنَا عَلَيْهِمُ الرّ۪يحَ الْعَق۪يمَۚ', 'Ve fi adin iz erselna aleyhimur rihal akim.', 'Âd\'da da vardır.[1] Onların üzerine kasıp kavuran rüzgar göndermiştik.', 'وفي عاد اذ ارسلنا عليهم الريح العقيم'),
(4717, 51, 42, 'مَا تَذَرُ مِنْ شَيْءٍ اَتَتْ عَلَيْهِ اِلَّا جَعَلَتْهُ  كَالرَّم۪يمِۜ', 'Ma tezeru min şey\'in etet aleyhi illa cealethu ker remim.', 'Nereye uğradıysa orayı çürümüş çer çöpe çevirmişti.', 'ما تذر من شي اتت عليه الا جعلته كالرميم'),
(4718, 51, 43, 'وَف۪ي ثَمُودَ اِذْ ق۪يلَ لَهُمْ تَمَتَّعُوا حَتّٰى ح۪ينٍ', 'Ve fi semude iz kile lehum temetteu hatta hinin.', 'Semud\'da da vardır.[1] Onlara: \"Belli bir süreye kadar yararlanın.\" denmişti.', 'وفي ثمود اذ قيل لهم تمتعوا حتي حين'),
(4719, 51, 44, 'فَعَتَوْا عَنْ اَمْرِ رَبِّهِمْ فَاَخَذَتْهُمُ الصَّاعِقَةُ وَهُمْ يَنْظُرُونَ', 'Fe atev an emri rabbihim fe ehazethumus saikatu ve hum yanzurun.', 'Fakat Rabb\'lerinin emrinden çıktılar. Bunun üzerine bakıp dururlarken yıldırım onları yakalayıverdi.', 'فعتوا عن امر ربهم فاخذتهم الصعقة وهم ينظرون'),
(4720, 51, 45, 'فَمَا اسْتَطَاعُوا مِنْ قِيَامٍ وَمَا كَانُوا مُنْتَصِر۪ينَۙ', 'Fe mestetau min kıyamin ve ma kanu muntesirine.', 'Ayağa kalkmaya güçleri yetmedi. Yardım görenler de olmadılar.', 'فما استطعوا من قيام وما كانوا منتصرين'),
(4721, 51, 46, 'وَقَوْمَ نُوحٍ مِنْ قَبْلُۜ اِنَّهُمْ كَانُوا قَوْماً فَاسِق۪ينَ۟', 'Ve kavme nuhın min kabl, inne hum kanu kavmen fasıkin.', 'Daha önce Nuh halkını da.[1] Ki onlar fasık bir halktı.', 'وقوم نوح من قبل انهم كانوا قوما فسقين'),
(4722, 51, 47, 'وَالسَّمَٓاءَ بَنَيْنَاهَا بِاَيْدٍ وَاِنَّا لَمُوسِعُونَ', 'Ves semae beneynaha bi eydin ve inna le musiun.', 'Göğü ellerle[1] bina ettik. Kuşkusuz genişletici olan elbette Biziz.', 'والسما بنينها باييد وانا لموسعون'),
(4723, 51, 48, 'وَالْاَرْضَ فَرَشْنَاهَا فَنِعْمَ الْمَاهِدُونَ', 'Vel arda fereşnaha fe ni\'mel mahidun.', 'Yeryüzünü de Biz döşedik. Ne güzel döşeyiciyiz!', 'والارض فرشنها فنعم المهدون'),
(4724, 51, 49, 'وَمِنْ كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', 'Ve min kulli şey\'in halakna zevceyni leallekum tezekkerun.', 'Her şeyi çift[1] yarattık. Umulur ki öğüt alırsınız.', 'ومن كل شي خلقنا زوجين لعلكم تذكرون'),
(4725, 51, 50, 'فَفِرُّٓوا اِلَى اللّٰهِۜ اِنّ۪ي لَكُمْ مِنْهُ نَذ۪يرٌ مُب۪ينٌۚ', 'Fe firru ilallah, inni lekum minhu nezirun mubin.', '\"O halde Allah\'a sığının! Ben,  sizin için O\'nun tarafından gönderilmiş apaçık bir uyarıcıyım.\"', 'ففروا الي الله اني لكم منه نذير مبين'),
(4726, 51, 51, 'وَلَا تَجْعَلُوا مَعَ اللّٰهِ اِلٰهاً اٰخَرَۜ اِنّ۪ي لَكُمْ مِنْهُ نَذ۪يرٌ مُب۪ينٌ', 'Ve la tec\'alu meallahi ilahen ahar, inni lekum minhu nezirun mubin.', '\"Allah\'ın yanı sıra başka bir ilah[1] tanımayın. Ben,  sizin için O\'nun tarafından gönderilmiş apaçık bir uyarıcıyım.\"', 'ولا تجعلوا مع الله الها اخر اني لكم منه نذير مبين'),
(4727, 51, 52, 'كَذٰلِكَ مَٓا اَتَى الَّذ۪ينَ مِنْ قَبْلِهِمْ مِنْ رَسُولٍ اِلَّا قَالُوا سَاحِرٌ اَوْ مَجْنُونٌ', 'Kezalike ma etellezine min kablihim min resulin illa kalu sahırun ev mecnun.', 'Aynen bunlar gibi,  bunlardan öncekiler de kendilerine gelen resullere,  \"Sihirbazdır veya mecnundur.\" dan başka bir şey demediler.', 'كذلك ما اتي الذين من قبلهم من رسول الا قالوا ساحر او مجنون'),
(4728, 51, 53, 'اَتَوَاصَوْا بِه۪ۚ بَلْ هُمْ قَوْمٌ طَاغُونَ', 'E tevasav bih, bel hum kavmun tagun.', 'Sanki böyle yapmayı sonrakilere vasiyet etmişler! Hayır,  onlar azgın bir halktır.', 'اتواصوا به بل هم قوم طاغون'),
(4729, 51, 54, 'فَتَوَلَّ عَنْهُمْ فَمَٓا اَنْتَ بِمَلُومٍۘ', 'Fe tevelle anhum fe ma ente bi melum.', 'O halde onlardan yüz çevir. Artık kınanacak değilsin.', 'فتول عنهم فما انت بملوم'),
(4730, 51, 55, 'وَذَكِّرْ فَاِنَّ الذِّكْرٰى تَنْفَعُ الْمُؤْمِن۪ينَ', 'Ve zekkir fe innez zikra tenfeul mu\'minin.', 'Öğüt ver; kuşkusuz ki öğüt Mü\'minlere fayda verir.', 'وذكر فان الذكري تنفع المومنين'),
(4731, 51, 56, 'وَمَا خَلَقْتُ الْجِنَّ وَالْاِنْسَ اِلَّا لِيَعْبُدُونِ', 'Ve ma halaktul cinne vel inse illa li ya\'budun.', 'Ben,  cinni[1] ve insi[1] yalnızca bana kulluk[2] etsinler diye yarattım.[3]', 'وما خلقت الجن والانس الا ليعبدون'),
(4732, 51, 57, 'مَٓا اُر۪يدُ مِنْهُمْ مِنْ رِزْقٍ وَمَٓا اُر۪يدُ اَنْ يُطْعِمُونِ', 'Ma uridu minhum min rızkın ve ma uridu en yut\'imuni.', 'Onlardan bir rızık da istemiyorum,  Beni doyurmalarını da istemiyorum.', 'ما اريد منهم من رزق وما اريد ان يطعمون'),
(4733, 51, 58, 'اِنَّ اللّٰهَ هُوَ الرَّزَّاقُ ذُوالْقُوَّةِ الْمَت۪ينُ', 'İnnallahe huver rezzaku zul kuvvetil metin.', 'Kuşkusuz rızık veren,  güçlü ve gücünde metin olan Allah\'tır.', 'ان الله هو الرزاق ذو القوة المتين'),
(4734, 51, 59, 'فَاِنَّ لِلَّذ۪ينَ ظَلَمُوا ذَنُوباً مِثْلَ ذَنُوبِ اَصْحَابِهِمْ فَلَا يَسْتَعْجِلُونِ', 'Fe inne lillezine zalemu zenuben misle zenubi ashabihim fe la yesta\'ciluni.', 'Zulmedenlerin azaptan payı,  arkadaşlarının[1] payı gibidir. Artık acele etmesinler.', 'فان للذين ظلموا ذنوبا مثل ذنوب اصحبهم فلا يستعجلون'),
(4735, 51, 60, 'فَوَيْلٌ لِلَّذ۪ينَ كَفَرُوا مِنْ يَوْمِهِمُ الَّذ۪ي يُوعَدُونَ', 'Fe veylun lillezine keferu min yevmihimullezi yuadun.', 'Kendilerine haber verilen azap günü geldiğinde,  Kafirlerin vay haline.', 'فويل للذين كفروا من يومهم الذي يوعدون'),
(4736, 52, 1, 'وَالطُّورِۙ', 'Vet turi.', 'Tur\'a ant olsun;', 'والطور'),
(4737, 52, 2, 'وَكِتَابٍ مَسْطُورٍۙ', 'Ve kitabin mesturin.', 'Satır satır yazılmış Kitap\'a,', 'وكتب مسطور'),
(4738, 52, 3, 'ف۪ي رَقٍّ مَنْشُورٍۙ', 'Fi rakkın menşurin.', 'Üzerine yazı yazılmış,  yayılmış ince deriye.', 'في رق منشور'),
(4739, 52, 4, 'وَالْبَيْتِ الْمَعْمُورِۙ', 'Vel beytil ma\'muri.', 'Beyt-i Mamur[1]\'a ant olsun.', 'والبيت المعمور'),
(4740, 52, 5, 'وَالسَّقْفِ الْمَرْفُوعِۙ', 'Ves sakfil merfui.', 'Yükseltilmiş tavana ant olsun', 'والسقف المرفوع'),
(4741, 52, 6, 'وَالْبَحْرِ الْمَسْجُورِۙ', 'Vel bahril mescuri.', 'Doldurulmuş denize ant olsun.', 'والبحر المسجور'),
(4742, 52, 7, 'اِنَّ عَذَابَ رَبِّكَ لَوَاقِـعٌۙ', 'İnne azabe rabbike le vakı\'un.', 'Rabb\'inin azabı kesinlikle gerçekleşecektir.', 'ان عذاب ربك لوقع'),
(4743, 52, 8, 'مَا لَهُ مِنْ دَافِـعٍۙ', 'Ma lehu min dafiin.', 'Onu savacak yoktur.', 'ما له من دافع'),
(4744, 52, 9, 'يَوْمَ تَمُورُ السَّمَٓاءُ مَوْراًۙ', 'Yevme temurus semau mevren.', 'O gün gök,  sarsıldıkça sarsılır.', 'يوم تمور السما مورا'),
(4745, 52, 10, 'وَتَس۪يرُ الْجِبَالُ سَيْراًۜ', 'Ve tesirul cibalu seyra.', 'Dağlar yerlerinden oynar.', 'وتسير الجبال سيرا'),
(4746, 52, 11, 'فَوَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَۙ', 'Fe veylun yevme izin lil mukezzibine.', 'İzin günü[1] yalanlayanların vay hallerine.', 'فويل يوميذ للمكذبين'),
(4747, 52, 12, 'اَلَّذ۪ينَ هُمْ ف۪ي خَوْضٍ يَلْعَبُونَۢ', 'Ellezine hum fi havdın yel\'abun.', 'Onlar ki,  gereksiz şeylere dalıp oyalanıyorlar.', 'الذين هم في خوض يلعبون'),
(4748, 52, 13, 'يَوْمَ يُدَعُّونَ اِلٰى نَارِ جَهَنَّمَ دَعاًّۜ', 'Yevme yude\'une ila nari cehenneme de\'a.', 'O gün,  Cehennem ateşine sürüklenirler.', 'يوم يدعون الي نار جهنم دعا'),
(4749, 52, 14, 'هٰذِهِ النَّارُ الَّت۪ي كُنْتُمْ بِهَا تُكَذِّبُونَ', 'Hazihin narulleti kuntum biha tukezzibun.', 'İşte bu,  yalanladığınız ateştir!', 'هذه النار التي كنتم بها تكذبون'),
(4750, 52, 15, 'اَفَسِحْرٌ هٰذَٓا اَمْ اَنْتُمْ لَا تُبْصِرُونَ', 'E fe sihrun haza em entum la tubsirun.', 'Bu sihir miymiş? Yoksa siz mi görmüyormuşsunuz?', 'افسحر هذا ام انتم لا تبصرون'),
(4751, 52, 16, 'اِصْلَوْهَا فَاصْبِرُٓوا اَوْ لَا تَصْبِرُواۚ سَوَٓاءٌ عَلَيْكُمْۜ اِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ', 'Islevha fasbiru ev la tasbiru sevaun aleykum, innema tuczevne ma kuntum ta\'melun.', 'Oraya girin. Artık dayansanız da dayanmasanız da sizin için birdir. Yaptığınız şeylerin karşılığını görüyorsunuz.', 'اصلوها فاصبروا او لا تصبروا سوا عليكم انما تجزون ما كنتم تعملون'),
(4752, 52, 17, 'اِنَّ الْمُتَّق۪ينَ ف۪ي جَنَّاتٍ وَنَع۪يمٍۙ', 'İnnel muttekine fi cennatin ve naimin.', 'Takva[1] sahipleri cennetlerde[2] ve nimetler içindedirler;', 'ان المتقين في جنت ونعيم'),
(4753, 52, 18, 'فَاكِه۪ينَ بِمَٓا اٰتٰيهُمْ رَبُّهُمْۚ وَوَقٰيهُمْ رَبُّهُمْ عَذَابَ الْجَح۪يمِ', 'Fakihine bi ma atahum rabbuhum, ve vekahum rabbuhum azabel cahim.', 'Rabb\'lerinin kendilerine verdiklerinden hoşnut olarak. Rabb\'leri onları Cehennem ateşinden korumuştur.', 'فكهين بما اتيهم ربهم ووقيهم ربهم عذاب الجحيم'),
(4754, 52, 19, 'كُلُوا وَاشْرَبُوا هَن۪ٓيـٔاً بِمَا كُنْتُمْ تَعْمَلُونَۙ', 'Kulu veşrebu henien bi ma kuntum ta\'melune.', 'Yaptıklarınızın karşılığı olarak,  afiyetle yiyin ve için;', 'كلوا واشربوا هنيا بما كنتم تعملون'),
(4755, 52, 20, 'مُتَّكِـ۪ٔينَ عَلٰى سُرُرٍ مَصْفُوفَةٍۚ وَزَوَّجْنَاهُمْ بِحُورٍ ع۪ينٍ', 'Muttekiine ala sururin masfufeh, ve zevvecnahum bi hurin inin.', 'Sıra sıra dizilmiş koltuklara yaslanarak. Biz,  onları temiz,  \"güzel bakışlı\" hurilerle[1] eşleştirmişizdir.', 'متكين علي سرر مصفوفة وزوجنهم بحور عين'),
(4756, 52, 21, 'وَالَّذ۪ينَ اٰمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِا۪يمَانٍ اَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَٓا اَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍۜ  كُلُّ امْرِئٍ بِمَا كَسَبَ رَه۪ينٌ', 'Vellezine amenu vettebeathum zurriyyetuhum bi imanin elhakna bihim zurriyyetehum ve ma eletnahum min amelihim min şey\'in, kullumriin bi ma kesebe rehinun.', 'İman eden,  soyları da iman ederek kendilerine tabi olan kimselerin,  soylarını da kendilerine kattık[1]. Ve onların yaptıklarından bir şey eksiltmedik. Herkes kendi yaptıklarının karşılığını alacak.', 'والذين امنوا واتبعتهم ذريتهم بايمن الحقنا بهم ذريتهم وما التنهم من عملهم من شي كل امري بما كسب رهين'),
(4757, 52, 22, 'وَاَمْدَدْنَاهُمْ بِفَاكِهَةٍ وَلَحْمٍ مِمَّا يَشْتَهُونَ', 'Ve emdednahum bi fakihetin ve lahmin mimma yeştehun.', 'Onlara; meyvelerden,  etlerden ve canlarının çektiği şeylerden bol bol sunarız.', 'وامددنهم بفكهة ولحم مما يشتهون'),
(4758, 52, 23, 'يَتَنَازَعُونَ ف۪يهَا كَأْساً لَا لَغْوٌ ف۪يهَا وَلَا تَأْث۪يمٌ', 'Yetenazeune fiha ke\'sen la lagvun fiha ve la te\'simun.', 'Birbirlerine,  saçmalamaya ve günaha yol açmayan kadehler sunacaklar.', 'يتنزعون فيها كاسا لا لغو فيها ولا تاثيم'),
(4759, 52, 24, 'وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَهُمْ كَاَنَّهُمْ لُؤْلُؤٌ۬ مَكْنُونٌ', 'Ve yetufu aleyhim gılmanun lehum ke ennehum lu\'luun meknunun.', 'Sedefleri içine gizlenmiş inci gibi ğılmanlar[1],  hizmet için çevrelerinde dolanırlar.', 'ويطوف عليهم غلمان لهم كانهم لولو مكنون'),
(4760, 52, 25, 'وَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَتَسَٓاءَلُونَ', 'Ve akbele ba\'duhum ala ba\'dın yetesaelun.', 'Bir araya gelerek söyleşirler:', 'واقبل بعضهم علي بعض يتسالون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4761, 52, 26, 'قَالُٓوا اِنَّا كُنَّا قَبْلُ ف۪ٓي اَهْلِنَا مُشْفِق۪ينَ', 'Kalu inna kunna kablu fi ehlina muşfikin.', '\"Doğrusu biz,  daha önce ailemizden dolayı korkuyorduk.\"', 'قالوا انا كنا قبل في اهلنا مشفقين'),
(4762, 52, 27, 'فَمَنَّ اللّٰهُ عَلَيْنَا وَوَقٰينَا عَذَابَ السَّمُومِ', 'Fe mennallahu aleyna ve vekana azabes semum.', '\"Şimdi,  Allah,  bizi nimetlendirdi ve bizi kavurucu ateşin azabından korudu.\"', 'فمن الله علينا ووقينا عذاب السموم'),
(4763, 52, 28, 'اِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُۜ اِنَّهُ هُوَ الْبَرُّ الرَّح۪يمُ۟', 'İnna kunna min kablu ned\'uh, innehu huvel berrur rahim.', '\"İyi ki daha önce yalnızca O\'na yöneldik. Kuşkusuz ki O,  İyilik Yapan\'dır,  Rahmeti Kesintisiz\'dir.\"', 'انا كنا من قبل ندعوه انه هو البر الرحيم'),
(4764, 52, 29, 'فَذَكِّرْ فَمَٓا اَنْتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍۜ', 'Fe zekkir fe ma ente bi ni\'meti rabbike bi kahinin ve la mecnun.', 'O halde öğüt vermeye devam et. Rabb\'inin nimeti sayesinde ne kahin ne de mecnunsun.', 'فذكر فما انت بنعمت ربك بكاهن ولا مجنون'),
(4765, 52, 30, 'اَمْ يَقُولُونَ شَاعِرٌ نَتَرَبَّصُ بِه۪ رَيْبَ الْمَنُونِ', 'Em yekulune şairun neterabbesu bihi reybel menuni.', 'Yoksa: \"O bir şairdir,  ansızın zamanın felaketine uğramasını bekliyoruz.\" mu diyorlar?', 'ام يقولون شاعر نتربص به ريب المنون'),
(4766, 52, 31, 'قُلْ تَرَبَّصُوا فَاِنّ۪ي مَعَكُمْ مِنَ الْمُتَرَبِّص۪ينَۜ', 'Kul terabbesu fe inni meakum minel muterabbisin.', 'De ki: \"Bekleyin! Ben de sizinle birlikte bekleyenlerdenim.\"', 'قل تربصوا فاني معكم من المتربصين'),
(4767, 52, 32, 'اَمْ تَأْمُرُهُمْ اَحْلَامُهُمْ بِهٰذَٓا اَمْ هُمْ قَوْمٌ طَاغُونَۚ', 'Em te\'muruhum ahlamuhum bi haza em hum kavmun tagun.', 'Yoksa onların düşleri böyle mi istiyor? Yoksa onlar azgın bir halk mı?', 'ام تامرهم احلمهم بهذا ام هم قوم طاغون'),
(4768, 52, 33, 'اَمْ يَقُولُونَ تَقَوَّلَهُۚ بَلْ لَا يُؤْمِنُونَۚ', 'Em yekulune tekavveleh, bel la yu\'minun.', 'Yoksa: \"Onu kendisi uydurup söyledi.\" mi diyorlar? İşin gerçeği,  onlar inanmak istemiyorlar.', 'ام يقولون تقوله بل لا يومنون'),
(4769, 52, 34, 'فَلْيَأْتُوا بِحَد۪يثٍ مِثْلِه۪ٓ اِنْ كَانُوا صَادِق۪ينَۜ', 'Fel ye\'tu bi hadisin mislihi in kanu sadikin.', 'Eğer söylediklerinde haklı kimselerse,  onlar da onun gibi bir hadis[1] getirsinler!', 'فلياتوا بحديث مثله ان كانوا صدقين'),
(4770, 52, 35, 'اَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ اَمْ هُمُ الْخَالِقُونَۜ', 'Em huliku min gayri şey\'in em humul halikun.', 'Yoksa onlar,  bir yaratıcı olmaksızın mı yaratıldılar? Yoksa yaratanlar onlar mıdır?', 'ام خلقوا من غير شي ام هم الخلقون'),
(4771, 52, 36, 'اَمْ خَلَقُوا السَّمٰوَاتِ وَالْاَرْضَۚ بَلْ لَا يُوقِنُونَۜ', 'Em halakus semavati vel ard, bel la yukınun.', 'Yoksa gökleri ve yeryüzünü onlar mı yarattı? Hayır,  onlar gerçeğe ulaşmaya yanaşmıyorlar!', 'ام خلقوا السموت والارض بل لا يوقنون'),
(4772, 52, 37, 'اَمْ عِنْدَهُمْ خَزَٓائِنُ رَبِّكَ اَمْ هُمُ الْمُصَيْطِرُونَۜ', 'Em indehum hazainu rabbike em humul musaytırun.', 'Yoksa Rabb\'inin hazineleri onların yanında mı? Veya kendilerinin her şeye güç yetirebileceklerini mi sanıyorlar?', 'ام عندهم خزاين ربك ام هم المصيطرون'),
(4773, 52, 38, 'اَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ ف۪يهِۚ فَلْيَأْتِ مُسْتَمِعُهُمْ بِسُلْطَانٍ مُب۪ينٍۜ', 'Em lehum sullemun yestemiune fih, fel ye\'ti mustemiuhum bi sultanin mubin.', 'Yoksa onların,  orada dinleyecekleri bir merdivenleri mi var? Öyleyse dinleyenleri buna dair bir belge getirsinler!', 'ام لهم سلم يستمعون فيه فليات مستمعهم بسلطن مبين'),
(4774, 52, 39, 'اَمْ لَهُ الْبَنَاتُ وَلَـكُمُ الْبَنُونَۜ', 'Em le hul benatu ve le kumul benun.', 'Yoksa kızlar O\'nun da oğullar sizin mi?', 'ام له البنت ولكم البنون'),
(4775, 52, 40, 'اَمْ تَسْـَٔلُهُمْ اَجْراً فَهُمْ مِنْ مَغْرَمٍ مُثْقَلُونَۜ', 'Em tes\'eluhum ecren fe hum min magremin muskalun.', 'Yoksa sen onlardan bir ücret istiyorsun da bu yüzden onlar ağır bir yük altına mı giriyorlar?', 'ام تسلهم اجرا فهم من مغرم مثقلون'),
(4776, 52, 41, 'اَمْ عِنْدَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَۜ', 'Em indehumul gaybu fe hum yektubun.', 'Yoksa gayb[1] onların yanında da onlar mı yazıyorlar?', 'ام عندهم الغيب فهم يكتبون'),
(4777, 52, 42, 'اَمْ يُر۪يدُونَ كَيْداًۜ فَالَّذ۪ينَ كَفَرُوا هُمُ الْمَك۪يدُونَۜ', 'Em yuridune keyda, fellezine keferu humul mekidun.', 'Yoksa bir tuzak mı kurmak istiyorlar? Ne var ki tuzağa düşecek olanlar Kafirlerdir.[1]', 'ام يريدون كيدا فالذين كفروا هم المكيدون'),
(4778, 52, 43, 'اَمْ لَهُمْ اِلٰهٌ غَيْرُ اللّٰهِۜ سُبْحَانَ اللّٰهِ عَمَّا يُشْرِكُونَ', 'Em lehum ilahun gayrullah, subhanallahi amma yuşrikun.', 'Yoksa onlar için Allah\'tan başka bir ilahları mı var? Allah,  onların şirk koştuklarından münezzehtir.[1]', 'ام لهم اله غير الله سبحن الله عما يشركون'),
(4779, 52, 44, 'وَاِنْ يَرَوْا كِسْفاً مِنَ السَّمَٓاءِ سَاقِطاً يَقُولُوا سَحَابٌ مَرْكُومٌ', 'Ve in yerev kisfen mines semai sakıtan yekulu sehabun merkum.', 'Gökten bir parçanın düştüğünü görseler,  \"Üst üste yığılmış bulutlardır.\" derler![1]', 'وان يروا كسفا من السما ساقطا يقولوا سحاب مركوم'),
(4780, 52, 45, 'فَذَرْهُمْ حَتّٰى يُلَاقُوا يَوْمَهُمُ الَّذ۪ي ف۪يهِ يُصْعَقُونَۙ', 'Fe zerhum hatta yulaku yevmehumullezi fihi yus\'akune.', 'Artık onları cezalandırılacakları güne kavuşuncaya kadar kendi hallerine bırak.', 'فذرهم حتي يلقوا يومهم الذي فيه يصعقون'),
(4781, 52, 46, 'يَوْمَ لَا يُغْن۪ي عَنْهُمْ كَيْدُهُمْ شَيْـٔاً وَلَا هُمْ يُنْصَرُونَۜ', 'Yevme la yugni anhum keyduhum şey\'en ve la hum yunsarun.', 'O gün planları onlara hiçbir yarar sağlamaz. Ve onlar yardım da olunmazlar.', 'يوم لا يغني عنهم كيدهم شيا ولا هم ينصرون'),
(4782, 52, 47, 'وَاِنَّ لِلَّذ۪ينَ ظَلَمُوا عَذَاباً دُونَ ذٰلِكَ وَلٰكِنَّ اَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Ve inne lillezine zalemu azaben dune zalike ve lakinne ekserehum la ya\'lemun.', 'Zulmedenler için bundan başka bir azap daha vardır. Ne var ki onların çoğu,  bunun bilincinde değiller.', 'وان للذين ظلموا عذابا دون ذلك ولكن اكثرهم لا يعلمون'),
(4783, 52, 48, 'وَاصْبِرْ لِحُكْمِ رَبِّكَ فَاِنَّكَ بِاَعْيُنِنَا وَسَبِّـحْ بِحَمْدِ رَبِّكَ ح۪ينَ تَقُومُۙ', 'Vasbir li hukmi rabbike fe inneke bi a\'yunina, ve sebbih bi hamdi rabbike hine tekumu.', 'Rabb\'inin hükmünü sabrederek bekle. Sen gözümüzün önündesin[1]. Ve her kalkışında[2] Rabb\'ini hamd ile tesbih[3] et.', 'واصبر لحكم ربك فانك باعيننا وسبح بحمد ربك حين تقوم'),
(4784, 52, 49, 'وَمِنَ الَّيْلِ فَسَبِّحْهُ وَاِدْبَارَ النُّجُومِ', 'Ve minel leyli fe sebbihhu ve idbaren nucumi.', 'Gecenin bir kısmında ve yıldızların batışının ardından[1] O\'nu tesbih et.[2]', 'ومن اليل فسبحه وادبر النجوم'),
(4785, 53, 1, 'وَالنَّجْمِ اِذَا هَوٰىۙ', 'Ven necmi iza heva.', 'Batan yıldıza ant olsun ki,', 'والنجم اذا هوي'),
(4786, 53, 2, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوٰىۚ', 'Ma dalle sahıbukum ve ma gava.', 'Arkadaşınız sapkın ve azgın değil.', 'ما ضل صاحبكم وما غوي'),
(4787, 53, 3, 'وَمَا يَنْطِقُ عَنِ الْهَوٰىۜ', 'Ve ma yentıku anil heva.', 'Ve o,  hevasından[1] konuşmaz.', 'وما ينطق عن الهوي'),
(4788, 53, 4, 'اِنْ هُوَ اِلَّا وَحْيٌ يُوحٰىۙ', 'İn huve illa vahyun yuha.', 'Onun size söyledikleri,  kendisine vahyedilen vahiyden başkası değildir.[1]', 'ان هو الا وحي يوحي'),
(4789, 53, 5, 'عَلَّمَهُ شَد۪يدُ الْقُوٰىۙ', 'Allemehu şedidul kuva.', 'Ona Üstün Güç Sahibi ve Kudretli Olan öğretti.[1]', 'علمه شديد القوي'),
(4790, 53, 6, 'ذُومِرَّةٍۜ  فَاسْتَوٰىۙ', 'Zu mirreh, festeva.', 'Üstün Akla[1] Sahip,  Egemenlik Kurmuş Olan.', 'ذو مرة فاستوي'),
(4791, 53, 7, 'وَهُوَ بِالْاُفُقِ الْاَعْلٰىۜ', 'Ve huve bil ufukil a\'la.', 'O,  yüksek bir ufuktaydı.', 'وهو بالافق الاعلي'),
(4792, 53, 8, 'ثُمَّ دَنَا فَتَدَلّٰىۙ', 'Summe dena fe tedella.', 'Sonra yaklaştı ve sarktı.', 'ثم دنا فتدلي'),
(4793, 53, 9, 'فَكَانَ قَابَ قَوْسَيْنِ اَوْ اَدْنٰىۚ', 'Fe kane kabe kavseyni ev edna.', 'Böylece iki yay aralığı kadar,  hatta daha yakın oldu.', 'فكان قاب قوسين او ادني'),
(4794, 53, 10, 'فَاَوْحٰٓى اِلٰى عَبْدِه۪ مَٓا اَوْحٰىۜ', 'Fe evha ila abdihi ma evha.', 'Kuluna[1] vahyedeceği şeyi vahyetti.[2]', 'فاوحي الي عبده ما اوحي'),
(4795, 53, 11, 'مَا كَذَبَ الْفُؤٰ۬ادُ مَا رَاٰى', 'Ma kezebel fuadu ma rea.', 'Gönlü,  gördüğünü yalanlamadı.', 'ما كذب الفواد ما راي'),
(4796, 53, 12, 'اَفَتُمَارُونَهُ عَلٰى مَا يَرٰى', 'E fe tumar runehu ala ma yera.', 'Onun gördüğü şeyden kuşku mu duyuyorsunuz?', 'افتمرونه علي ما يري'),
(4797, 53, 13, 'وَلَقَدْ رَاٰهُ نَزْلَةً اُخْرٰىۙ', 'Ve lekad reahu nezleten uhra.', 'Ant olsun ki,  onu başka bir inişinde de gördü.', 'ولقد راه نزلة اخري'),
(4798, 53, 14, 'عِنْدَ سِدْرَةِ الْمُنْتَهٰى', 'İnde sidretil munteha.', 'Sidretu\'l Münteha\'nın[1] yanında.', 'عند سدرة المنتهي'),
(4799, 53, 15, 'عِنْدَهَا جَنَّةُ الْمَأْوٰىۜ', 'İndeha cennetul me\'va.', 'Onun yanında me\'va[1] cenneti[2] vardır.', 'عندها جنة الماوي'),
(4800, 53, 16, 'اِذْ يَغْشَى السِّدْرَةَ مَا يَغْشٰىۙ', 'İz yagşes sidrete ma yagşa.', 'O zaman kaplayan şey,  Sidre\'yi[1] kaplıyordu.', 'اذ يغشي السدرة ما يغشي'),
(4801, 53, 17, 'مَا زَاغَ الْبَصَرُ وَمَا طَغٰى', 'Ma zagal basaru ve ma tega.', 'Bakış şaşmadı ve haddi aşmadı.', 'ما زاغ البصر وما طغي'),
(4802, 53, 18, 'لَقَدْ رَاٰى مِنْ اٰيَاتِ رَبِّهِ الْـكُبْرٰى', 'Lekad rea min ayati rabbihil kubra.', 'Ant olsun,  Rabb\'inin ayetlerinin[1] en büyüğünü gördü.', 'لقد راي من ايت ربه الكبري'),
(4803, 53, 19, 'اَفَرَاَيْتُمُ اللَّاتَ وَالْعُزّٰىۙ', 'E fe reeytumul late vel uzza.', 'Görüyor musunuz Lat\'ı ve Uzza\'yı?', 'افريتم اللت والعزي'),
(4804, 53, 20, 'وَمَنٰوةَ الثَّالِثَةَ الْاُخْرٰى', 'Ve menates salisetel uhra.', 'Diğer üçüncü Menat\'ı?[1]', 'ومنوة الثالثة الاخري'),
(4805, 53, 21, 'اَلَـكُمُ الذَّكَرُ وَلَهُ الْاُنْثٰى', 'E lekumuz zekeru ve lehul unsa.', 'Erkek sizin,  dişi O\'nun mu?', 'الكم الذكر وله الانثي'),
(4806, 53, 22, 'تِلْكَ اِذاً قِسْمَةٌ ض۪يزٰى', 'Tilke izen kısmetun diza.', 'O halde bu insafsız bir paylaştırmadır.', 'تلك اذا قسمة ضيزي'),
(4807, 53, 23, 'اِنْ هِيَ اِلَّٓا اَسْمَٓاءٌ سَمَّيْتُمُوهَٓا اَنْتُمْ وَاٰبَٓاؤُ۬كُمْ مَٓا اَنْزَلَ اللّٰهُ بِهَا مِنْ سُلْطَانٍۜ اِنْ يَتَّبِعُونَ اِلَّا الظَّنَّ وَمَا تَهْوَى الْاَنْفُسُۚ وَلَقَدْ جَٓاءَهُمْ مِنْ رَبِّهِمُ الْهُدٰىۜ', 'İn hiye illa esmaun semmeytumuha entum ve abaukum ma enzelallahu biha min sultan, in yettebiune illez zanne ve ma tehvel enfus, ve lekad caehum min rabbihimul huda.', 'Bu isimler,  sizin ve atalarınızın onlara yakıştırdığı isimlerden başka bir şey değildir. Allah,  onlar için hiçbir yetkilendirmede bulunmadı. Ant olsun ki,  onlara Rabb\'lerinden doğru yolu gösterici[1] geldiği halde,  onlar yalnızca zanna[2] ve benliklerinin hevasına uyuyorlar.', 'ان هي الا اسما سميتموها انتم واباوكم ما انزل الله بها من سلطن ان يتبعون الا الظن وما تهوي الانفس ولقد جاهم من ربهم الهدي'),
(4808, 53, 24, 'اَمْ لِلْاِنْسَانِ مَا تَمَنّٰىۘ', 'Em lil insani ma temenna.', 'Yoksa insan için yalnızca temenni ettiği şey mi var?', 'ام للانسن ما تمني'),
(4809, 53, 25, 'فَلِلّٰهِ الْاٰخِرَةُ وَالْاُو۫لٰى۟', 'Fe lillahil ahiretu vel ula.', 'Ahiret de dünya da Allah\'ındır.', 'فلله الاخرة والاولي'),
(4810, 53, 26, 'وَكَمْ مِنْ مَلَكٍ فِي السَّمٰوَاتِ لَا تُغْن۪ي شَفَاعَتُهُمْ شَيْـٔاً اِلَّا مِنْ بَعْدِ اَنْ يَأْذَنَ اللّٰهُ لِمَنْ يَشَٓاءُ وَيَرْضٰى', 'Ve kem min melekin fis semavati la tugni şefaatuhum şey\'en illa min ba\'di en ye\'zenallahu limen yeşau ve yerda.', 'Göklerde nice melekler var ki,  Allah\'ın dilediği ve hoşnut olduğu kimseler için izin vermesi dışında onların şefaatleri[1] hiçbir yarar sağlamaz.', 'وكم من ملك في السموت لا تغني شفعتهم شيا الا من بعد ان ياذن الله لمن يشا ويرضي'),
(4811, 53, 27, 'اِنَّ الَّذ۪ينَ لَا يُؤْمِنُونَ بِالْاٰخِرَةِ لَيُسَمُّونَ الْمَلٰٓئِكَةَ تَسْمِيَةَ الْاُنْثٰى', 'İnnellezine la yu\'minune bil ahireti le yusemmunel melaikete tesmiyetel unsa.', 'Kuşkusuz ahirete inanmayanlar,  melekleri dişi varlıkların adları ile adlandırıyorlar.[1]', 'ان الذين لا يومنون بالاخرة ليسمون المليكة تسمية الانثي'),
(4812, 53, 28, 'وَمَا لَهُمْ بِه۪ مِنْ عِلْمٍۜ  اِنْ يَتَّبِعُونَ اِلَّا الظَّنَّۚ وَاِنَّ الظَّنَّ لَا يُغْن۪ي مِنَ الْحَقِّ شَيْـٔاًۚ', 'Ve ma lehum bihi min ilm, in yettebiune illez zann, ve innez zanne la yugni minel hakkı şey\'a.', 'Oysaki onların bu konuda hiçbir bilgileri yoktur. Onlar yalnızca zanna uyuyorlar. Oysaki zan,  \"gerçekten\" yana hiçbir değer taşımaz.', 'وما لهم به من علم ان يتبعون الا الظن وان الظن لا يغني من الحق شيا'),
(4813, 53, 29, 'فَاَعْرِضْ عَنْ مَنْ تَوَلّٰى عَنْ ذِكْرِنَا وَلَمْ يُرِدْ اِلَّا الْحَيٰوةَ الدُّنْيَاۜ', 'Fe a\'rıd an men tevella an zikrina ve lem yurid illel hayated dunya.', 'Dünya hayatından başka bir şey istemeyen,  zikrimizden[1] yüz çevirenlerden sen de yüz çevir.[2]', 'فاعرض عن من تولي عن ذكرنا ولم يرد الا الحيوة الدنيا'),
(4814, 53, 30, 'ذٰلِكَ مَبْلَغُهُمْ مِنَ الْعِلْمِۜ  اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِمَنْ ضَلَّ عَنْ سَب۪يلِه۪ وَهُوَ اَعْلَمُ بِمَنِ اهْتَدٰى', 'Zalike mebleguhum minel ilm, inne rabbeke huve a\'lemu bi men dalle an sebilihi ve huve a\'lemu bi menihteda.', 'Onların bilgi düzeyi bu kadardır. Rabb\'in,  kimin kendi yolundan sapmış olduğunu en iyi bilendir ve O,  iletildiği doğru yolda olanı da en iyi bilendir.', 'ذلك مبلغهم من العلم ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بمن اهتدي'),
(4815, 53, 31, 'وَلِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۙ لِيَجْزِيَ الَّذ۪ينَ اَسَٓاؤُ۫ا بِمَا عَمِلُوا وَيَجْزِيَ الَّذ۪ينَ اَحْسَنُوا بِالْحُسْنٰىۚ', 'Ve lillahi ma fis semavati ve ma fil ardı li yecziyellezine esau bima amilu ve yecziyellezine ahsenu bil husna.', 'Göklerde ve yerde olan her şey Allah\'ındır. Bu,  kötülük yapanların cezalandırılması ve iyilik yapanların daha iyisiyle ödüllendirilmesi içindir.[1]', 'ولله ما في السموت وما في الارض ليجزي الذين اسوا بما عملوا ويجزي الذين احسنوا بالحسني'),
(4816, 53, 32, 'اَلَّذ۪ينَ يَجْتَنِبُونَ كَـبَٓائِرَ الْاِثْمِ وَالْفَوَاحِشَ اِلَّا اللَّمَمَۜ اِنَّ رَبَّكَ وَاسِعُ الْمَغْفِرَةِۜ هُوَ اَعْلَمُ بِكُمْ اِذْ اَنْشَاَكُمْ مِنَ الْاَرْضِ وَاِذْ اَنْتُمْ اَجِنَّةٌ ف۪ي بُطُونِ اُمَّهَاتِكُمْۚ فَلَا تُزَكُّٓوا اَنْفُسَكُمْۜ هُوَ اَعْلَمُ بِمَنِ اتَّقٰى۟', 'Ellezine yectenibune kebairel ismi vel fevahışe lemem, inne rabbeke vasiul magfireh, huve a\'lemu bikum iz enşeekum minel ardı ve iz entum e cinnetun fi butuni ummehatikum, fe la tuzekku enfusekum, huve a\'lemu bi menitteka.', 'Onlar,  ufak-tefek hatalara düşmek hariç,  büyük günahlardan ve aşırılıklardan kaçınırlar. Kuşkusuz Rabb\'in,  bağışlaması bol olandır. O,  sizi topraktan inşa ederken de annelerinizin karnında cenin halindeyken de ne olduğunuzu en iyi bilendir. O halde kendinizi temize çıkarmayın. O,  takva[1] sahibi olan kimseyi en iyi bilendir.', 'الذين يجتنبون كبير الاثم والفوحش الا اللمم ان ربك وسع المغفرة هو اعلم بكم اذ انشاكم من الارض واذ انتم اجنة في بطون امهتكم فلا تزكوا انفسكم هو اعلم بمن اتقي'),
(4817, 53, 33, 'اَفَرَاَيْتَ الَّذ۪ي تَوَلّٰىۙ', 'E fe re\'eytellezi tevella.', 'Peki,  yüz çevireni görüyor musun?', 'افريت الذي تولي'),
(4818, 53, 34, 'وَاَعْطٰى قَل۪يلاً وَاَكْدٰى', 'Ve a\'ta kalilen ve ekda.', 'Azıcık verip,  inatla cimrilik edeni?', 'واعطي قليلا واكدي'),
(4819, 53, 35, 'اَعِنْدَهُ عِلْمُ الْغَيْبِ فَهُوَ يَرٰى', 'E indehu ilmul gaybi fe huve yera.', 'Yoksa o gaybın bilgisine[1] sahip de onu mu görüyor?', 'اعنده علم الغيب فهو يري'),
(4820, 53, 36, 'اَمْ لَمْ يُنَبَّأْ بِمَا ف۪ي صُحُفِ مُوسٰىۙ', 'Em lem yunebbe\' bima fi suhufi musa.', 'Musa\'nın sayfalarında olanlar haber verilmedi mi?', 'ام لم ينبا بما في صحف موسي'),
(4821, 53, 37, 'وَاِبْرٰه۪يمَ الَّذ۪ي وَفّٰىۙ', 'Ve ibrahimellezi veffa.', 'Ve de çok vefalı İbrahim\'ın.', 'وابرهيم الذي وفي'),
(4822, 53, 38, 'اَلَّا تَزِرُ وَازِرَةٌ وِزْرَ اُخْرٰىۙ', 'Ella teziru vaziretun vizre uhra.', 'Gerçek şu ki,  hiçbir günahkar,  başka bir günahkarın yükünü yüklenemez.', 'الا تزر وازرة وزر اخري'),
(4823, 53, 39, 'وَاَنْ لَيْسَ لِلْاِنْسَانِ اِلَّا مَا سَعٰىۙ', 'Ve en leyse lil insani illa ma sea.', 'Ve gerçek şu ki,  insan için çalışmasından başka bir şey yoktur.', 'وان ليس للانسن الا ما سعي'),
(4824, 53, 40, 'وَاَنَّ سَعْيَهُ سَوْفَ يُرٰىۖ', 'Ve enne sa\'yehu sevfe yura.', 'Ve onun çalışması yakında görülecektir.', 'وان سعيه سوف يري'),
(4825, 53, 41, 'ثُمَّ يُجْزٰيهُ الْجَزَٓاءَ الْاَوْفٰىۙ', 'Summe yuczahul cezael evfa.', 'Sonra karşılığı kendisine eksiksiz olarak verilecektir.', 'ثم يجزيه الجزا الاوفي'),
(4826, 53, 42, 'وَاَنَّ اِلٰى رَبِّكَ الْمُنْتَهٰىۙ', 'Ve enne ila rabbikel munteha.', 'Sonunda dönüş yalnızca Rabb\'inedir.', 'وان الي ربك المنتهي'),
(4827, 53, 43, 'وَاَنَّهُ هُوَ اَضْحَكَ وَاَبْكٰىۙ', 'Ve ennehu huve adhake ve ebka.', 'Güldüren de ağlatan da O\'dur.', 'وانه هو اضحك وابكي'),
(4828, 53, 44, 'وَاَنَّهُ هُوَ اَمَاتَ وَاَحْيَاۙ', 'Ve ennehu huve emate ve ahya.', 'Öldüren de dirilten de O\'dur.', 'وانه هو امات واحيا'),
(4829, 53, 45, 'وَاَنَّهُ خَلَقَ الزَّوْجَيْنِ الذَّكَرَ وَالْاُنْثٰىۙ', 'Ve ennehu halakaz zevceyniz zekere vel unsa.', 'O,  erkek ve dişi çiftler yarattı.', 'وانه خلق الزوجين الذكر والانثي'),
(4830, 53, 46, 'مِنْ نُطْفَةٍ اِذَا تُمْنٰىۖ', 'Min nutfetin iza tumna.', 'Atıldığında,  nutfeden.[1]', 'من نطفة اذا تمني'),
(4831, 53, 47, 'وَاَنَّ عَلَيْهِ النَّشْاَةَ الْاُخْرٰىۙ', 'Ve enne aleyhin neş\'etel uhra.', 'Ve kuşkusuz bundan sonraki diriltme[1] de yalnızca O\'na aittir.', 'وان عليه النشاة الاخري'),
(4832, 53, 48, 'وَاَنَّهُ هُوَ اَغْنٰى وَاَقْنٰىۙ', 'Ve ennehu huve agna ve akna.', 'Zenginlik veren de O\'dur,  sınırlayan da.', 'وانه هو اغني واقني'),
(4833, 53, 49, 'وَاَنَّهُ هُوَ رَبُّ الشِّعْرٰىۙ', 'Ve ennehu huve rabbuş şı\'ra.', 'Şi\'ra\'nın[1] Rabb\'i de O\'dur.', 'وانه هو رب الشعري'),
(4834, 53, 50, 'وَاَنَّـهُٓ اَهْلَكَ عَاداًۨ الْاُو۫لٰىۙ', 'Ve ennehu ehleke adenil ula.', 'Önceki Âd\'ı[1] yok etti.', 'وانه اهلك عادا الاولي'),
(4835, 53, 51, 'وَثَمُودَا۬ فَمَٓا اَبْـقٰىۙ', 'Ve semude fema ebka.', 'Ve Semud\'u da. Geride kimseyi bırakmadı.', 'وثمودا فما ابقي'),
(4836, 53, 52, 'وَقَوْمَ نُوحٍ مِنْ قَبْلُۜ اِنَّهُمْ كَانُوا هُمْ اَظْلَمَ وَاَطْغٰىۜ', 'Ve kavme nuhın min kabl, innehum kanu hum azleme ve atga.', 'Daha önce de Nuh\'un halkını. Onlar,  daha zalim ve daha azgın olanlardı.', 'وقوم نوح من قبل انهم كانوا هم اظلم واطغي'),
(4837, 53, 53, 'وَالْمُؤْتَفِكَةَ اَهْوٰىۙ', 'Vel mu\'tefikete ehva.', 'Alt üst edilen beldeyi de yerin dibine geçirdi.', 'والموتفكة اهوي'),
(4838, 53, 54, 'فَغَشّٰيهَا مَا غَشّٰىۚ', 'Fe gaşşaha ma gaşşa.', 'Artık onu kaplayan şey kapladı.', 'فغشيها ما غشي'),
(4839, 53, 55, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكَ تَتَمَارٰى', 'Fe bi eyyi alai rabbike tetemara.', 'O halde Rabb\'inin hangi nimetinden kuşku duyuyorsun?', 'فباي الا ربك تتماري'),
(4840, 53, 56, 'هٰذَا نَذ۪يرٌ مِنَ النُّذُرِ الْاُو۫لٰى', 'Haza nezirun minen nuzuril ula.', 'Bu uyarıcı da ilk uyarıcılar gibi bir uyarıcıdır.', 'هذا نذير من النذر الاولي'),
(4841, 53, 57, 'اَزِفَتِ الْاٰزِفَةُۚ', 'Ezifetil azifeh.', 'Yaklaşan,  yaklaştı.[1]', 'ازفت الازفة'),
(4842, 53, 58, 'لَيْسَ لَهَا مِنْ دُونِ اللّٰهِ كَاشِفَةٌ', 'Leyse leha min dunillahi kaşifeh.', 'Onu,  Allah\'tan başkası çeviremez.', 'ليس لها من دون الله كاشفة'),
(4843, 53, 59, 'اَفَمِنْ هٰذَا الْحَد۪يثِ تَعْجَبُونَۙ', 'E fe min hazel hadisi ta\'cebun.', 'Bu hadislere[1] mi şaşırıyorsunuz?', 'افمن هذا الحديث تعجبون'),
(4844, 53, 60, 'وَتَضْحَكُونَ وَلَا تَبْكُونَۙ', 'Ve tedhakune ve la tebkun.', 'Ağlanacak halinize gülüyorsunuz.', 'وتضحكون ولا تبكون'),
(4845, 53, 61, 'وَاَنْتُمْ سَامِدُونَ', 'Ve entum samidun.', 'Ve siz gaflete dalanlarsınız![1]', 'وانتم سمدون'),
(4846, 53, 62, 'فَاسْجُدُوا لِلّٰهِ وَاعْبُدُوا', 'Fescudu lillahi va\'budu.', 'Artık bu gafletten kurtulup,  Allah\'a secde edin[1] ve O\'na kul[2] olun.', 'فاسجدوا لله واعبدوا'),
(4847, 54, 1, 'اِقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ', 'İkterebetis saatu ven şakkal kamer.', 'Sa\'at[1] yaklaştı ve Ay yarıldı.[2]', 'اقتربت الساعة وانشق القمر'),
(4848, 54, 2, 'وَاِنْ يَرَوْا اٰيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ', 'Ve in yerev ayeten yu\'ridu ve yekulu sihrun mustemirr.', 'Onlar,  bir ayet[1] görseler,  hemen yüz çevirirler.[1] Ve \"Bu süregelen bir büyüdür.\" derler.', 'وان يروا اية يعرضوا ويقولوا سحر مستمر'),
(4849, 54, 3, 'وَكَذَّبُوا وَاتَّبَعُٓوا اَهْوَٓاءَهُمْ وَكُلُّ اَمْرٍ مُسْتَقِرٌّ', 'Ve kezzebu vettebeu ehvaehum ve kullu emrin mustekırr.', 'Ve yalanladılar. Kendi tutkularına uydular. Oysa her şey kararlaştırılmıştır.', 'وكذبوا واتبعوا اهواهم وكل امر مستقر'),
(4850, 54, 4, 'وَلَقَدْ جَٓاءَهُمْ مِنَ الْاَنْـبَٓاءِ مَا ف۪يهِ مُزْدَجَرٌۙ', 'Ve lekad caehum minel enbai ma fihi muzdecer.', 'Ant olsun ki onlara,  yanılgılarını giderecek nice haberler geldi.', 'ولقد جاهم من الانبا ما فيه مزدجر'),
(4851, 54, 5, 'حِكْمَةٌ بَالِغَةٌ فَمَا تُغْنِ النُّذُرُۙ', 'Hikmetun baligatun fe ma tugnin nuzur.', 'Yüksek seviyede hikmetli haberler. Buna rağmen uyarıların bir yararı olmadı.', 'حكمة بلغة فما تغن النذر'),
(4852, 54, 6, 'فَتَوَلَّ عَنْهُمْۢ يَوْمَ يَدْعُ الدَّاعِ اِلٰى شَيْءٍ نُكُرٍۙ', 'Fe tevelle anhum, yevme yed\'ud dai ila şey\'in nukur.', 'O halde onlardan yüz çevir. O gün çağırıcı onları hiç hoşlanmayacakları şeye çağıracak.', 'فتول عنهم يوم يدع الداع الي شي نكر'),
(4853, 54, 7, 'خُشَّعاً اَبْصَارُهُمْ يَخْرُجُونَ مِنَ الْاَجْدَاثِ كَاَنَّهُمْ جَرَادٌ مُنْتَشِرٌۙ', 'Huşşe\'an ebsaruhum yahrucune minel ecdasi keennehum ceradun munteşir.', 'Kabirlerinden baygın gözlerle çıkarlar. Etrafa dağılmış çekirgeler gibidirler.', 'خشعا ابصرهم يخرجون من الاجداث كانهم جراد منتشر'),
(4854, 54, 8, 'مُهْطِع۪ينَ اِلَى الدَّاعِۜ يَقُولُ الْـكَافِرُونَ هٰذَا يَوْمٌ عَسِرٌ', 'Muhtıine iled dai, yekulul kafirune haza yevmun asir.', 'Çağırıcıya doğru koşan Kafirler: \"Bu,  çok zor bir gün.\" diyecekler.', 'مهطعين لي الداع يقول الكفرون هذا يوم عسر'),
(4855, 54, 9, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَـكَذَّبُوا عَبْدَنَا وَقَالُوا مَجْنُونٌ وَازْدُجِرَ', 'Kezzebet kablehum kavmu nuhın fe kezzebu abdena ve kalu mecnunun vezducir.', 'Onlardan önce Nuh\'un halkı da yalanladı. Kulumuzu,  \"O delinin biridir.\" diye yalanladılar. Kulumuz zorluk çıkarılarak engellendi.', 'كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر'),
(4856, 54, 10, 'فَدَعَا رَبَّهُٓ  اَنّ۪ي مَغْلُوبٌ فَانْتَصِرْ', 'Fe dea rabbehu enni maglubun fentasır.', 'Sonunda Rabb\'ine çağrıda bulundu: \"Doğrusu ben yenik düştüm,  bana yardım et.\"', 'فدعا ربه ني مغلوب فانتصر'),
(4857, 54, 11, 'فَفَتَحْنَٓا اَبْوَابَ السَّمَٓاءِ بِمَٓاءٍ مُنْهَمِرٍۘ', 'Fe fetahna ebvabes semai bi main munhemir.', 'Biz de hemen göğün kapılarını gürül gürül boşalan su ile açtık.', 'ففتحنا ابوب السما بما منهمر'),
(4858, 54, 12, 'وَفَجَّرْنَا الْاَرْضَ عُيُوناً فَالْتَقَى الْمَٓاءُ عَلٰٓى اَمْرٍ قَدْ قُدِرَۚ', 'Ve feccernel arda uyunen feltekalmau ala emrin kad kudir.', 'Yeryüzünde de kaynakları fışkırttık. Böylece sular kararlaştırılan amaç için birleşti.', 'وفجرنا الارض عيونا فالتقي الما علي امر قد قدر'),
(4859, 54, 13, 'وَحَمَلْنَاهُ عَلٰى ذَاتِ اَلْوَاحٍ وَدُسُرٍۙ', 'Ve hamelnahu ala zati elvahın ve dusur.', 'Onu ağaç lifi ile birbirine bağlanmış tahtalar üzerinde taşıdık.', 'وحملنه علي ذات الواح ودسر'),
(4860, 54, 14, 'تَجْر۪ي بِاَعْيُنِنَاۚ جَزَٓاءً لِمَنْ كَانَ كُفِرَ', 'Tecri bi a\'yunina, cezaen li men kane kufir.', 'Yalanlanan kimseye bir ödül olarak,  gözetimimiz altında yüzüp gidiyordu.', 'تجري باعيننا جزا لمن كان كفر'),
(4861, 54, 15, 'وَلَقَدْ تَرَكْنَاهَٓا اٰيَةً فَهَلْ مِنْ مُدَّكِرٍ', 'Ve lekad tereknaha ayeten fe hel min muddekir.', 'Ant olsun ki onu[1] bir ayet[2] olarak bıraktık. İbret alan yok mudur?', 'ولقد تركنها اية فهل من مدكر'),
(4862, 54, 16, 'فَـكَيْفَ كَانَ عَذَاب۪ي وَنُذُرِ', 'Fe keyfe kane azabi ve nuzur.', 'Ama azabım ve uyarılarım nasıl oldu?[1]', 'فكيف كان عذابي ونذر'),
(4863, 54, 17, 'وَلَقَدْ يَسَّرْنَا الْقُرْاٰنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ', 'Ve lekad yessernel kur\'ane liz zikri fe hel min muddekir.', 'Ant olsun Biz,  Kur\'an\'ı öğüt alınsın diye kolaylaştırdık. Var mı öğüt alıp düşünen?', 'ولقد يسرنا القران للذكر فهل من مدكر'),
(4864, 54, 18, 'كَذَّبَتْ عَادٌ فَـكَيْفَ كَانَ عَذَاب۪ي وَنُذُرِ', 'Kezzebet adun fe keyfe kane azabi ve nuzur.', 'Âd da yalanladı. Ama azabım ve uyarılarım nasıl oldu?', 'كذبت عاد فكيف كان عذابي ونذر'),
(4865, 54, 19, 'اِنَّٓا اَرْسَلْنَا عَلَيْهِمْ ر۪يحاً صَرْصَراً ف۪ي يَوْمِ نَحْسٍ مُسْتَمِرٍّۙ', 'İnna erselna aleyhim rihan sarsaren fi yevmi nahsin mustemirr.', 'Biz,  onların üzerine felaketleri gün boyu süren çok sarsıcı rüzgarı gönderdik.', 'انا ارسلنا عليهم ريحا صرصرا في يوم نحس مستمر'),
(4866, 54, 20, 'تَنْزِ عُ النَّاسَۙ كَاَنَّهُمْ اَعْجَازُ نَخْلٍ مُنْقَعِرٍ', 'Tenziun nase ke ennehum a\'cazu nahlin munkair.', 'İnsanları,  kökünden sökülmüş hurma kütükleri gibi savurup atıyordu.', 'تنزع الناس كانهم اعجاز نخل منقعر'),
(4867, 54, 21, 'فَـكَيْفَ كَانَ عَذَاب۪ي وَنُذُرِ', 'Fe keyfe kane azabi ve nuzur.', 'Ama azabım ve uyarılarım nasıl oldu?', 'فكيف كان عذابي ونذر'),
(4868, 54, 22, 'وَلَقَدْ يَسَّرْنَا الْقُرْاٰنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ۟', 'Ve lekad yessernel kur\'ane liz zikri fe hel min muddekir.', 'Ant olsun Biz,  Kur\'an\'ı öğüt alınsın diye kolaylaştırdık. Var mı öğüt alıp düşünen?', 'ولقد يسرنا القران للذكر فهل من مدكر'),
(4869, 54, 23, 'كَذَّبَتْ ثَمُودُ بِالنُّذُرِ', 'Kezzebet semudu bin nuzur.', 'Semud da uyarıcıları yalanladı.', 'كذبت ثمود بالنذر'),
(4870, 54, 24, 'فَقَالُٓوا اَبَشَراً مِنَّا وَاحِداً نَتَّبِعُهُٓۙ  اِنَّٓا اِذاً لَف۪ي ضَلَالٍ وَسُعُرٍ', 'Fe kalu ebeşeren minna vahiden nettebiuhu inna izen lefi dalalin ve suur.', 'Şöyle dediler: \"Bizden biri olan bir beşere mı biz ona mı uyacağız? Öyle yaparsak kesinlikle bir sapkınlık ve çılgınlık yapmış oluruz.', 'فقالوا ابشرا منا وحدا نتبعه انا اذا لفي ضلل وسعر'),
(4871, 54, 25, 'ءَاُلْقِيَ الذِّكْرُ عَلَيْهِ مِنْ بَيْنِنَا بَلْ هُوَ كَذَّابٌ اَشِرٌ', 'E ulkıyez zikru aleyhi min beynina bel huve kezzabun eşir.', 'Zikir[1],  aramızdan bula bula onu mu buldu? Hayır! O küstah bir yalancıdır.', 'القي الذكر عليه من بيننا بل هو كذاب اشر'),
(4872, 54, 26, 'سَيَعْلَمُونَ غَداً مَنِ الْـكَذَّابُ الْاَشِرُ', 'Se ya\'lemune gaden menil kezzabul eşir.', 'Onlar,  yarın[1] küstah yalancının kim olduğunu anlayacaklar!', 'سيعلمون غدا من الكذاب الاشر'),
(4873, 54, 27, 'اِنَّا مُرْسِلُوا النَّاقَةِ فِتْنَةً لَهُمْ فَارْتَقِبْهُمْ وَاصْطَبِرْۘ', 'İnna mursilun nakati fitneten lehum fertekıbhum vestabir.', 'Biz,  fitne[1] olsun diye onlara dişi deveyi[2] gönderdik. Artık onları gözetle ve sabret.', 'انا مرسلوا الناقة فتنة لهم فارتقبهم واصطبر'),
(4874, 54, 28, 'وَنَبِّئْهُمْ اَنَّ الْمَٓاءَ قِسْمَةٌ بَيْنَهُمْۚ  كُلُّ شِرْبٍ مُحْتَضَرٌ', 'Ve nebbi\'hum ennel mae kısmetun beynehum, kullu şirbin muhtedar.', 'Onlara,  suyun bölüşüldüğünü haber ver. Her içiş hazır kılınmıştır.', 'ونبيهم ان الما قسمة بينهم كل شرب محتضر'),
(4875, 54, 29, 'فَنَادَوْا صَاحِبَهُمْ فَتَعَاطٰى فَعَقَرَ', 'Fe nadev sahıbehum fe teata fe akar.', 'Derken arkadaşlarını çağırdılar[1],  o da bıçağa sarıldı ve kesti.', 'فنادوا صاحبهم فتعاطي فعقر'),
(4876, 54, 30, 'فَـكَيْفَ كَانَ عَذَاب۪ي وَنُذُرِ', 'Fe keyfe kane azabi ve nuzur.', 'Ama azabım ve uyarılarım nasıl oldu?', 'فكيف كان عذابي ونذر'),
(4877, 54, 31, 'اِنَّٓا اَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَاحِدَةً فَـكَانُوا كَـهَش۪يمِ الْمُحْتَظِرِ', 'İnna erselna aleyhim sayhaten vahıdeten fe kanu ke heşimil muhtezir.', 'Biz,  onların üzerlerine tek bir sayha gönderdik. Böylece ağıldaki ufalanmış kuru ot gibi oldular.', 'انا ارسلنا عليهم صيحة وحدة فكانوا كهشيم المحتظر'),
(4878, 54, 32, 'وَلَقَدْ يَسَّرْنَا الْقُرْاٰنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ', 'Ve lekad yessernel kur\'ane liz zikri fe hel min muddekir.', 'Ant olsun Biz,  Kur\'an\'ı öğüt alınsın diye kolaylaştırdık. Var mı öğüt alıp düşünen?', 'ولقد يسرنا القران للذكر فهل من مدكر'),
(4879, 54, 33, 'كَذَّبَتْ قَوْمُ لُوطٍ بِالنُّذُرِ', 'Kezzebet kavmu lutın bin nuzur.', 'Lut\'un halkı da uyarıcılarını yalanladı.', 'كذبت قوم لوط بالنذر'),
(4880, 54, 34, 'اِنَّٓا اَرْسَلْنَا عَلَيْهِمْ حَاصِباً اِلَّٓا اٰلَ لُوطٍۜ  نَجَّيْنَاهُمْ بِسَحَرٍۙ', 'İnna erselna aleyhim hasiben illa ale lut, necceynahum bi sehar.', 'Biz de onların üzerlerine yok edici kasırga[1] gönderdik. Lut\'un yanında yer alanlar bunun dışında tutuldu. Seher vakti onları kurtardık.', 'انا ارسلنا عليهم حاصبا الا ال لوط نجينهم بسحر'),
(4881, 54, 35, 'نِعْمَةً مِنْ عِنْدِنَاۜ   كَذٰلِكَ نَجْز۪ي مَنْ شَكَرَ', 'Ni\'meten min indina, kezalike neczi men şeker.', 'İşte şükredenleri katımızdan bir nimet olarak böyle ödüllendiririz.', 'نعمة من عندنا كذلك نجزي من شكر'),
(4882, 54, 36, 'وَلَقَدْ اَنْذَرَهُمْ بَطْشَتَنَا فَتَمَارَوْا بِالنُّذُرِ', 'Ve lekad enzerehum batşetena fe temarev bin nuzur.', 'Ant olsun ki yakalayıp tutuşumuza karşı onları uyarmıştı. Ne var ki onlar bu uyarıları kuşku ile karşıladılar.', 'ولقد انذرهم بطشتنا فتماروا بالنذر'),
(4883, 54, 37, 'وَلَقَدْ رَاوَدُوهُ عَنْ ضَيْفِه۪ فَطَمَسْنَٓا اَعْيُنَهُمْ فَذُوقُوا عَذَاب۪ي وَنُذُرِ', 'Ve lekad raveduhu an dayfihi fe tamesna a\'yunehum fe zuku azabi ve nuzur.', 'Ant olsun ki onun misafirlerinden cinsel yönden yararlanmak istediler. Bunun üzerine gözlerini sildik.[1] Azabımı ve uyarılarımı tadın.', 'ولقد رودوه عن ضيفه فطمسنا اعينهم فذوقوا عذابي ونذر'),
(4884, 54, 38, 'وَلَقَدْ صَبَّحَهُمْ بُكْرَةً عَذَابٌ مُسْتَقِرٌّۚ', 'Ve lekad sabbehahum bukreten azabun mustekırr.', 'Ant olsun ki,  onları sabahleyin kalıcı bir azap yakaladı.', 'ولقد صبحهم بكرة عذاب مستقر'),
(4885, 54, 39, 'فَذُوقُوا عَذَاب۪ي وَنُذُرِ', 'Fe zuku azabi ve nuzur.', 'Haydi! Tadın bakalım,  azabımı ve uyarılarımı!', 'فذوقوا عذابي ونذر'),
(4886, 54, 40, 'وَلَقَدْ يَسَّرْنَا الْقُرْاٰنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ۟', 'Ve lekad yessernel kur\'ane liz zikri fe hel min muddekir.', 'Ant olsun Biz,  Kur\'an\'ı öğüt alınsın diye kolaylaştırdık. Var mı öğüt alıp düşünen?', 'ولقد يسرنا القران للذكر فهل من مدكر'),
(4887, 54, 41, 'وَلَقَدْ جَٓاءَ اٰلَ فِرْعَوْنَ النُّذُرُۚ', 'Ve lekad cae ale fir\'avnen nuzur.', 'Ant olsun ki,  Firavun ailesine[1] de uyarıcılar gelmişti.', 'ولقد جا ال فرعون النذر'),
(4888, 54, 42, 'كَذَّبُوا بِاٰيَاتِنَا كُلِّهَا فَاَخَذْنَاهُمْ اَخْذَ عَز۪يزٍ مُقْتَدِرٍ', 'Kezzebu bi ayatina kulliha fe ehaznahum ahze azizin muktedir.', 'Ayetlerimizin tamamını yalanladılar. Biz de onları gücümüze,  üstünlüğümüze yaraşır bir yakalayışla yakalayıverdik.', 'كذبوا بايتنا كلها فاخذنهم اخذ عزيز مقتدر'),
(4889, 54, 43, 'اَكُفَّارُكُمْ خَيْرٌ مِنْ اُو۬لٰٓئِكُمْ اَمْ لَـكُمْ بَرَٓاءَةٌ فِي الزُّبُرِۚ', 'E kuffarukum hayrun min ulaikum em lekum beraetun fiz zubur.', 'Sizin[1] Kafirleriniz onlardan daha mı hayırlı; yoksa kitaplarda size dokunulmayacağına dair söz mü verildi?', 'اكفاركم خير من اوليكم ام لكم براة في الزبر'),
(4890, 54, 44, 'اَمْ يَقُولُونَ نَحْنُ جَم۪يعٌ مُنْتَصِرٌ', 'Em yekulune nahnu cemiun muntesir.', 'Yoksa: \"Biz,  güç birliği etmiş yenilmez bir toplumuz.\" mu diyorlar?', 'ام يقولون نحن جميع منتصر'),
(4891, 54, 45, 'سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ', 'Se yuhzemul cem\'u ve yuvelluned dubur.', 'Yakında o topluluk bozguna uğrayacak ve darmadağın olacaklar[1].', 'سيهزم الجمع ويولون الدبر'),
(4892, 54, 46, 'بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ اَدْهٰى وَاَمَرُّ', 'Belis saatu mev\'ıduhum ves sa\'atu edha ve emerr.', 'Hayır! Asıl onlara vaat edilen o Sa\'at\'tir.[1] Ve o Sa\'at,  daha korkunç daha dehşetlidir.', 'بل الساعة موعدهم والساعة ادهي وامر'),
(4893, 54, 47, 'اِنَّ الْمُجْرِم۪ينَ ف۪ي ضَلَالٍ وَسُعُرٍۢ', 'İnnel mucrimine fi dalalin ve suur.', 'Kuşkusuz,  mücrimler[1] sapkınlık ve çılgınlık içindedirler.', 'ان المجرمين في ضلل وسعر'),
(4894, 54, 48, 'يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلٰى وُجُوهِهِمْۜ ذُوقُوا مَسَّ سَقَرَ', 'Yevme yushabune fin nari ala vucuhihim, zuku messe sekar.', 'O gün yüz üstü sürülerek ateşe atılırlar. \"Cehennem ateşinin dokunuşunu tadın!\"', 'يوم يسحبون في النار علي وجوههم ذوقوا مس سقر'),
(4895, 54, 49, 'اِنَّا  كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ', 'İnna kulle şey\'in halaknahu bi kader.', 'Biz,  her şeyi bir yasayla yarattık.[1]', 'انا كل شي خلقنه بقدر'),
(4896, 54, 50, 'وَمَٓا اَمْرُنَٓا اِلَّا وَاحِدَةٌ  كَلَمْحٍ بِالْبَصَرِ', 'Ve ma emruna illa vahıdetun ke lemhın bil basar.', 'Ve buyruğumuz bir tek buyruktur. Gözün bir anlık bakışı gibidir.', 'وما امرنا الا وحدة كلمح بالبصر'),
(4897, 54, 51, 'وَلَقَدْ اَهْلَكْنَٓا اَشْيَاعَكُمْ فَهَلْ مِنْ مُدَّكِرٍ', 'Ve lekad ehlekna eşyaakum fe hel min muddekir.', 'Ant olsun ki size benzer nicelerini yok ettik. Buna rağmen düşünen mi var?', 'ولقد اهلكنا اشياعكم فهل من مدكر'),
(4898, 54, 52, 'وَكُلُّ شَيْءٍ فَعَلُوهُ فِي الزُّبُرِ', 'Ve kullu şey\'in fe aluhu fiz zubur.', 'Onların yaptığı her şey kitaplardadır.', 'وكل شي فعلوه في الزبر'),
(4899, 54, 53, 'وَكُلُّ صَغ۪يرٍ وَكَب۪يرٍ مُسْتَطَرٌ', 'Ve kullu sagirin ve kebirin mustetar.', 'Ve küçük büyük her şey yazılmıştır.', 'وكل صغير وكبير مستطر'),
(4900, 54, 54, 'اِنَّ الْمُتَّق۪ينَ ف۪ي جَنَّاتٍ وَنَهَرٍۙ', 'İnnel muttekine fi cennatin ve neher.', 'Takva sahipleri cennetlerde[1] ve nehir kenarlarındadır.', 'ان المتقين في جنت ونهر'),
(4901, 54, 55, 'ف۪ي مَقْعَدِ صِدْقٍ عِنْدَ مَل۪يكٍ مُقْتَدِرٍ', 'Fi mak\'adi sıdkın inde melikin muktedir.', 'Sonsuz Güç Sahibi yöneticinin katında,  sadakat makamındadırlar.[1]', 'في مقعد صدق عند مليك مقتدر'),
(4902, 55, 1, 'اَلرَّحْمٰنُۙ', 'Er rahman.', 'Rahman.[1]', 'الرحمن'),
(4903, 55, 2, 'عَلَّمَ الْقُرْاٰنَۜ', 'Allemel kur\'an.', 'Kur\'an\'ı öğretti.', 'علم القران'),
(4904, 55, 3, 'خَلَقَ الْاِنْسَانَۙ', 'Halakal insan.', 'İnsanı yarattı.', 'خلق الانسن'),
(4905, 55, 4, 'عَلَّمَهُ الْبَيَانَ', 'Allemehul beyan.', 'Ona beyanı[1] öğretti.', 'علمه البيان'),
(4906, 55, 5, 'اَلشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍۖ', 'Eş şemsu vel kameru bi husban.', 'Güneş ve Ay hesap iledir.[1]', 'الشمس والقمر بحسبان'),
(4907, 55, 6, 'وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ', 'Ven necmu veş şeceru yescudan.', 'Bitkiler[1] ve ağaçlar,  ikisi de secde[2] ederler.', 'والنجم والشجر يسجدان'),
(4908, 55, 7, 'وَالسَّمَٓاءَ رَفَعَهَا وَوَضَعَ الْم۪يزَانَۙ', 'Ves semae refeaha ve vedaal mizan.', 'Ve sema; onu yükseltti. Ve ölçüyü[1] koydu.', 'والسما رفعها ووضع الميزان'),
(4909, 55, 8, 'اَلَّا تَطْغَوْا فِي الْم۪يزَانِ', 'Ella tatgav fil mizan.', 'Ölçüyü çiğnemeyin.[1]', 'الا تطغوا في الميزان'),
(4910, 55, 9, 'وَاَق۪يمُوا الْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُوا الْم۪يزَانَ', 'Ve ekimul vezne bil kıstı ve la tuhsırul mizan.', 'Tartıyı hakkaniyetle[1] ayakta tutun[2]. Ölçüyü eksiltmeyin.[2]', 'واقيموا الوزن بالقسط ولا تخسروا الميزان'),
(4911, 55, 10, 'وَالْاَرْضَ وَضَعَهَا لِلْاَنَامِۙ', 'Vel arda vedaaha lil enam.', 'Ve yeryüzü; onu yaratıklar[1] için alçalttı.[2]', 'والارض وضعها للانام'),
(4912, 55, 11, 'ف۪يهَا فَاكِهَةٌۖ وَالنَّخْلُ ذَاتُ الْاَكْمَامِ', 'Fiha fakihetun vennahlu zatul ekmam.', 'Orada meyveler ve salkım salkım hurma ağaçları var.', 'فيها فكهة والنخل ذات الاكمام'),
(4913, 55, 12, 'وَالْحَبُّ ذُوالْعَصْفِ وَالرَّيْحَانُۚ', 'Vel habbu zul asfi ver reyhan.', 'Yapraklı taneler ve güzel kokulu bitkiler var.', 'والحب ذو العصف والريحان'),
(4914, 55, 13, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde ikiniz[1],  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4915, 55, 14, 'خَلَقَ الْاِنْسَانَ مِنْ صَلْصَالٍ كَالْفَخَّارِۙ', 'Halakal insane min salsalin kel fehhar.', 'İnsanı salsalinden[1],  çömlek gibi pişmiş kuru çamurdan yarattı.', 'خلق الانسن من صلصل كالفخار'),
(4916, 55, 15, 'وَخَلَقَ الْجَٓانَّ مِنْ مَارِجٍ مِنْ نَارٍۚ', 'Ve halakal canne min maricin min nar.', 'Ve cinleri dumanı olmayan ateşten yarattı.', 'وخلق الجان من مارج من نار'),
(4917, 55, 16, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4918, 55, 17, 'رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِۚ', 'Rabbul meşrikayni ve rabbul magribeyn.', 'İki doğunun ve iki batının Rabb\'idir.', 'رب المشرقين ورب المغربين'),
(4919, 55, 18, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4920, 55, 19, 'مَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِۙ', 'Merecel bahreyni yeltekıyan.', 'İki denizi birbirine kavuşmak üzere saldı.', 'مرج البحرين يلتقيان'),
(4921, 55, 20, 'بَيْنَهُمَا بَرْزَخٌ لَا يَبْغِيَانِۚ', 'Beynehuma berzehun la yebgıyan.', 'Aralarında bir engel var,  birbirlerinin sınırını geçip karışmıyorlar.', 'بينهما برزخ لا يبغيان'),
(4922, 55, 21, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4923, 55, 22, 'يَخْرُجُ مِنْهُمَا اللُّؤْلُؤُ۬ وَالْمَرْجَانُۚ', 'Yahrucu min humel luluu vel mercan.', 'İkisinden de inci ve mercan çıkar.', 'يخرج منهما اللولو والمرجان'),
(4924, 55, 23, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4925, 55, 24, 'وَلَهُ الْجَوَارِ الْمُنْشَاٰتُ فِي الْبَحْرِ كَالْاَعْلَامِۚ', 'Ve lehul cevaril munşeatu fil bahri kel alam.', 'Denizde akıp giden,  dağlar gibi yapılmış olan gemiler O\'nundur.[1]', 'وله الجوار المنشات في البحر كالاعلم'),
(4926, 55, 25, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ۟', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4927, 55, 26, 'كُلُّ مَنْ عَلَيْهَا فَانٍۚ', 'Kullu men aleyha fan.', 'Onun üzerindeki herkes yok olacaktır.', 'كل من عليها فان'),
(4928, 55, 27, 'وَيَبْقٰى وَجْهُ رَبِّكَ ذُوالْجَلَالِ وَالْاِكْرَامِۚ', 'Ve yebka vechu rabbike zul celali vel ikram.', 'Kalıcı olan yalnız celal[1] ve ikram[2] sahibi Rabb\'inin kendisidir.', 'ويبقي وجه ربك ذو الجلل والاكرام'),
(4929, 55, 28, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4930, 55, 29, 'يَسْـَٔلُهُ مَنْ فِي السَّمٰوَاتِ وَالْاَرْضِۜ كُلَّ يَوْمٍ هُوَ ف۪ي شَأْنٍۚ', 'Yes\' eluhu men fis semavati vel ard, kulle yevmin huve fi şe\'nin.', 'Göklerde ve yerde olanlar,  O\'ndan isterler. O,  her gün bir şan işindedir.[1]', 'يسله من في السموت والارض كل يوم هو في شان'),
(4931, 55, 30, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4932, 55, 31, 'سَنَفْرُغُ لَكُمْ اَيُّهَ الثَّقَلَانِۚ', 'Se nefrugu lekum eyyuhes sekalan.', 'Ey iki büyük grup! Yakında sizin hesabınıza bakacağız!', 'سنفرغ لكم ايه الثقلان'),
(4933, 55, 32, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4934, 55, 33, 'يَا مَعْشَرَ الْجِنِّ وَالْاِنْسِ اِنِ اسْتَطَعْتُمْ اَنْ تَنْفُذُوا مِنْ اَقْطَارِ السَّمٰوَاتِ وَالْاَرْضِ فَانْفُذُواۜ  لَا تَنْفُذُونَ اِلَّا بِسُلْطَانٍۚ', 'Ya ma\'şerel cinni vel insi inisteta\'tum en tenfuzu min aktaris semavati vel ardı fenfuz, la tenfuzune illa bi sultan.', 'Ey cin ve ins toplulukları![1] Eğer göklerin ve yerin ötesine geçmeye güç yettirebilirseniz[2],  haydi geçin. Ancak aşma yetkisi[3] verilmeden geçemezsiniz.', 'يمعشر الجن والانس ان استطعتم ان تنفذوا من اقطار السموت والارض فانفذوا لا تنفذون الا بسلطن'),
(4935, 55, 34, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4936, 55, 35, 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِنْ نَارٍ وَنُحَاسٌ فَلَا تَنْتَصِرَانِۚ', 'Yurselu aleykuma şuvazun min narin ve nuhasun fe la tentesıran.', 'İkinizin üzerine ateşten bir alev ve duman gönderilir ve siz yardımlaşamazsınız.[1]', 'يرسل عليكما شواظ من نار ونحاس فلا تنتصران'),
(4937, 55, 36, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4938, 55, 37, 'فَاِذَا انْشَقَّتِ السَّمَٓاءُ فَكَانَتْ وَرْدَةً كَالدِّهَانِۚ', 'Fe izen şakkatis semau fe kanet verdeten keddihan.', 'Gök parçalanıp kırmızı gül renginde yağ eriyiğine dönüştüğü zaman;', 'فاذا انشقت السما فكانت وردة كالدهان'),
(4939, 55, 38, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4940, 55, 39, 'فَيَوْمَئِذٍ لَا يُسْـَٔلُ عَنْ ذَنْبِه۪ٓ اِنْسٌ وَلَا جَٓانٌّۚ', 'Fe yevme izin la yus\'elu an zenbihi insun ve la cann.', 'İşte o gün,  ins[1] ve cine[1] suçları sorulmaz.', 'فيوميذ لا يسل عن ذنبه انس ولا جان'),
(4941, 55, 40, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4942, 55, 41, 'يُعْرَفُ الْمُجْرِمُونَ بِس۪يمٰيهُمْ فَيُؤْخَذُ بِالنَّوَاص۪ي وَالْاَقْدَامِۚ', 'Yu\'reful mucrımune bi simahum fe yu\'hazu bin nevasi vel akdam.', 'Suçlular simalarından tanınır. Alınlarından ve ayaklarından yakalanırlar.[1]', 'يعرف المجرمون بسيمهم فيوخذ بالنوصي والاقدام'),
(4943, 55, 42, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4944, 55, 43, 'هٰذِه۪ جَهَنَّمُ الَّت۪ي يُكَذِّبُ بِهَا الْمُجْرِمُونَۢ', 'Hazihi cehennemulleti yukezzibu bi hel mucrimun.', 'İşte bu,  suçluların yalanladığı Cehennem\'dir.', 'هذه جهنم التي يكذب بها المجرمون'),
(4945, 55, 44, 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَم۪يمٍ اٰنٍۚ', 'Yetufune beyneha ve beyne hamimin an.', 'Onunla kaynar su arasında dolaşır dururlar.', 'يطوفون بينها وبين حميم ان'),
(4946, 55, 45, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ۟', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4947, 55, 46, 'وَلِمَنْ خَافَ مَقَامَ رَبِّه۪ جَنَّتَانِۚ', 'Ve li men hafe makame rabbihi cennetan.', 'Rabb\'inin makamından korkanlar için iki cennet vardır.', 'ولمن خاف مقام ربه جنتان'),
(4948, 55, 47, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۙ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4949, 55, 48, 'ذَوَاتَٓا اَفْنَانٍۚ', 'Zevata efnan.', 'İkisinin de çeşit çeşit ağaçları vardır.', 'ذواتا افنان'),
(4950, 55, 49, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4951, 55, 50, 'ف۪يهِمَا عَيْنَانِ تَجْرِيَانِۚ', 'Fihi ma aynani tecriyan.', 'İkisinde de akıp giden iki pınar vardır.', 'فيهما عينان تجريان'),
(4952, 55, 51, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4953, 55, 52, 'ف۪يهِمَا مِنْ كُلِّ فَاكِهَةٍ زَوْجَانِۚ', 'Fihi ma min kulli fatihetin zevcan.', 'İkisinde de her meyveden çift çift vardır.', 'فيهما من كل فكهة زوجان'),
(4954, 55, 53, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4955, 55, 54, 'مُتَّكِـ۪ٔينَ عَلٰى فُرُشٍ بَطَٓائِنُهَا مِنْ اِسْتَبْرَقٍۜ وَجَنَا الْجَنَّتَيْنِ دَانٍۚ', 'Muttekiine ala furuşin betainuha min istebrak, ve cenel cenneteyni dan.', 'Astarları kalın ipekten minderlere yaslanırlar. İki Cennet\'in meyvesi alabilecek yakınlıktadır.', 'متكين علي فرش بطاينها من استبرق وجني الجنتين دان'),
(4956, 55, 55, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4957, 55, 56, 'ف۪يهِنَّ قَاصِرَاتُ الطَّرْفِۙ لَمْ يَطْمِثْهُنَّ اِنْسٌ قَبْلَهُمْ وَلَا جَٓانٌّۚ', 'Fihinne kasiratut tarfi lem yatmishunne insun kablehum ve la cann.', 'Onlarda daha önce ins[1] ve cinnin[1] dokunmadığı,  bakışlarını başkasından çekmiş eşler vardır.', 'فيهن قصرت الطرف لم يطمثهن انس قبلهم ولا جان'),
(4958, 55, 57, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4959, 55, 58, 'كَاَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُۚ', 'Ke enne hunnel yakutu vel mercan.', 'Onlar,  adeta yakut ve mercan gibidirler.', 'كانهن الياقوت والمرجان'),
(4960, 55, 59, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4961, 55, 60, 'هَلْ جَزَٓاءُ الْاِحْسَانِ اِلَّا الْاِحْسَانُۚ', 'Hel cezaul ihsani illel ihsan.', 'İyiliğin karşılığı,  iyilikten başka olabilir mi?', 'هل جزا الاحسن الا الاحسن'),
(4962, 55, 61, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4963, 55, 62, 'وَمِنْ دُونِهِمَا جَنَّتَانِۚ', 'Ve min dunihima cennetan.', 'Bu ikisinden başka iki Cennet daha var.', 'ومن دونهما جنتان'),
(4964, 55, 63, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۙ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4965, 55, 64, 'مُدْهَٓامَّتَانِۚ', 'Mud hammetan.', 'İkisi de yemyeşildir.', 'مدهامتان'),
(4966, 55, 65, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4967, 55, 66, 'ف۪يهِمَا عَيْنَانِ نَضَّاخَتَانِۚ', 'Fihi ma aynani neddahatan.', 'İkisinde de coşkun iki su kaynağı vardır.', 'فيهما عينان نضاختان'),
(4968, 55, 67, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4969, 55, 68, 'ف۪يهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌۚ', 'Fihi ma fakihetun ve nahlun ve rumman.', 'İkisinde de meyve,  hurma ve nar vardır.', 'فيهما فكهة ونخل ورمان'),
(4970, 55, 69, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4971, 55, 70, 'ف۪يهِنَّ خَيْرَاتٌ حِسَانٌۚ', 'Fihinne hayratun hisan.', 'Onlarda[1] hayırlar ve iyilikler vardır.[2]', 'فيهن خيرت حسان'),
(4972, 55, 71, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4973, 55, 72, 'حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِۚ', 'Hurun maksuratun fil hiyam.', 'Çadırlarda korunaklı huriler[1] vardır.', 'حور مقصورت في الخيام'),
(4974, 55, 73, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4975, 55, 74, 'لَمْ يَطْمِثْهُنَّ اِنْسٌ قَبْلَهُمْ وَلَا جَٓانٌّۚ', 'Lem yatmishunne insun kablehum ve la cann.', 'Onlara daha önce ins ve cin[1] dokunmadı.', 'لم يطمثهن انس قبلهم ولا جان'),
(4976, 55, 75, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِۚ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4977, 55, 76, 'مُتَّكِـ۪ٔينَ عَلٰى رَفْرَفٍ خُضْرٍ وَعَبْقَرِيٍّ حِسَانٍۚ', 'Muttekiine ala refrefin hudrin ve abkariyyin hisan.', 'En iyi döşeklerin üzerinde yeşil yastıklara yaslanırlar.', 'متكين علي رفرف خضر وعبقري حسان'),
(4978, 55, 77, 'فَبِاَيِّ اٰلَٓاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fe bi eyyi alai rabbikuma tukezziban.', 'O halde siz ikiniz,  Rabb\'inizin hangi nimetlerini yalanlayabilirsiniz?', 'فباي الا ربكما تكذبان'),
(4979, 55, 78, 'تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلَالِ وَالْاِكْرَامِ', 'Tebarekesmu rabbike zil celali vel ikram.', 'Celal[1] ve ikram[2] sahibi olan Rabb\'inin ismi ne yücedir.', 'تبرك اسم ربك ذي الجلل والاكرام'),
(4980, 56, 1, 'اِذَا وَقَعَتِ الْوَاقِعَةُۙ', 'İza ve kaatil vakıah.', 'Olacak olan o müthiş olay gerçekleştiği zaman.', 'اذا وقعت الواقعة'),
(4981, 56, 2, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌۢ', 'Leyse li vak\'atiha kazibeh.', 'Onun gerçekleşmesini yalanlayan kimse kalmayacak.', 'ليس لوقعتها كذبة'),
(4982, 56, 3, 'خَافِضَةٌ رَافِعَةٌۙ', 'Hafidatun rafiah.', 'Alçaltıcıdır,  yükselticidir.', 'خافضة رافعة'),
(4983, 56, 4, 'اِذَا رُجَّتِ الْاَرْضُ رَجاًّۙ', 'İza ruccetil ardu recca.', 'Yer sarsıldıkça sarsıldığı zaman.', 'اذا رجت الارض رجا'),
(4984, 56, 5, 'وَبُسَّتِ الْجِبَالُ بَساًّۙ', 'Ve bussetil cibalu bessa.', 'Dağlar parça parça olup,', 'وبست الجبال بسا'),
(4985, 56, 6, 'فَكَانَتْ هَبَٓاءً مُنْبَثاًّۙ', 'Fe kanet hebaen mun bessa.', 'Toz duman haline gelince,', 'فكانت هبا منبثا'),
(4986, 56, 7, 'وَكُنْتُمْ اَزْوَاجاً ثَلٰثَةًۜ', 'Ve kuntum ezvacen selaseh.', 'Siz o zaman üç sınıfa ayrılacaksınız.', 'وكنتم ازوجا ثلثة'),
(4987, 56, 8, 'فَاَصْحَابُ الْمَيْمَنَةِ مَٓا اَصْحَابُ الْمَيْمَنَةِۜ', 'Fe ashabul meymeneti ma ashabul meymeneti.', 'İşte ashabı meymene[1]! Nedir ashabı meymene?', 'فاصحب الميمنة ما اصحب الميمنة'),
(4988, 56, 9, 'وَاَصْحَابُ الْمَشْـَٔمَةِ مَٓا اَصْحَابُ الْمَشْـَٔمَةِۜ', 'Ve ashabul meş\'emeti ma ashabul meş\'emeti.', 'Ashabı meş\'eme[1]! Nedir ashabı meş\'eme?', 'واصحب المشمة ما اصحب المشمة'),
(4989, 56, 10, 'وَالسَّابِقُونَ السَّابِقُونَۙ', 'Ves sabikunes sabikun.', 'Ve sabikunlar da sabikunlardır.[1]', 'والسبقون السبقون'),
(4990, 56, 11, 'اُو۬لٰٓئِكَ الْمُقَرَّبُونَۚ', 'Ulaikel mukarrebun.', 'İşte onlar[1],  yaklaştırılanlardır.[2]', 'اوليك المقربون'),
(4991, 56, 12, 'ف۪ي جَنَّاتِ النَّع۪يمِ', 'Fi cennatin naim.', 'Naim[1] Cennetlerindedirler.[2]', 'في جنت النعيم'),
(4992, 56, 13, 'ثُلَّةٌ مِنَ الْاَوَّل۪ينَۙ', 'Sulletun minel evvelin.', 'Birçoğu öncekilerden.', 'ثلة من الاولين'),
(4993, 56, 14, 'وَقَل۪يلٌ مِنَ الْاٰخِر۪ينَۜ', 'Ve kalilun minel ahirin.', 'Birazı da sonrakilerden.[1]', 'وقليل من الاخرين'),
(4994, 56, 15, 'عَلٰى سُرُرٍ مَوْضُونَةٍۙ', 'Ala sururin mevdunetin.', 'İşlemeli tahtlar üzerinde.', 'علي سرر موضونة'),
(4995, 56, 16, 'مُتَّكِـ۪ٔينَ عَلَيْهَا مُتَقَابِل۪ينَ', 'Muttekiine aleyha mutekabilin.', 'Onların üzerinde karşılıklı yaslanırlar.', 'متكين عليها متقبلين'),
(4996, 56, 17, 'يَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُخَلَّدُونَۙ', 'Yetufu aleyhim vildanun muhalledun.', 'Yaşamları sürekli kılınmış gençler[1] çevrelerinde dolaşırlar.', 'يطوف عليهم ولدن مخلدون');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(4997, 56, 18, 'بِاَكْوَابٍ وَاَبَار۪يقَ وَكَأْسٍ مِنْ مَع۪ينٍۙ', 'Bi ekvabin ve ebarika ve ke\'sin min main.', 'Kaynağından doldurulmuş testiler,  ibrikler ve billur kadehler ile.', 'باكواب واباريق وكاس من معين'),
(4998, 56, 19, 'لَا يُصَدَّعُونَ عَنْهَا وَلَا يُنْزِفُونَۙ', 'La yusaddeune anha ve la yunzifun.', 'Ondan; başları ağrımaz ve sarhoş olmazlar.', 'لا يصدعون عنها ولا ينزفون'),
(4999, 56, 20, 'وَفَاكِهَةٍ مِمَّا يَتَخَيَّرُونَۙ', 'Ve fakihetin mimma yetehayyerun.', 'Ve beğendikleri meyveler,', 'وفكهة مما يتخيرون'),
(5000, 56, 21, 'وَلَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَۜ', 'Ve lahmi tayrin mimma yeştehun.', 'Ve canlarının çektiği kuş etleri,', 'ولحم طير مما يشتهون'),
(5001, 56, 22, 'وَحُورٌ ع۪ينٌۙ', 'Ve hurun inun.', 'Güzel bakışlı huriler.[1]', 'وحور عين'),
(5002, 56, 23, 'كَاَمْثَالِ اللُّؤْلُؤِ۬ الْمَكْنُونِۚ', 'Ke emsalil lu\'luil meknun.', 'Korunmuş inci gibi.', 'كامثل اللولو المكنون'),
(5003, 56, 24, 'جَزَٓاءً بِمَا كَانُوا يَعْمَلُونَ', 'Cezaen bi ma kanu ya\'melun.', 'Yaptıkları iyi şeylere karşılık olarak.', 'جزا بما كانوا يعملون'),
(5004, 56, 25, 'لَا يَسْمَعُونَ ف۪يهَا لَغْواً وَلَا تَأْث۪يماًۙ', 'La yesmeune fiha lagven ve la te\'sima.', 'Orada boş,  anlamsız ve günaha sokan şeyler duymazlar.', 'لا يسمعون فيها لغوا ولا تاثيما'),
(5005, 56, 26, 'اِلَّا ق۪يلاً سَلَاماً سَلَاماً', 'İlla kilen selamen selama.', 'Söz olarak yalnızca; selam,  selam[1] sözü söylenir.', 'الا قيلا سلما سلما'),
(5006, 56, 27, 'وَاَصْحَابُ الْيَم۪ينِ مَٓا اَصْحَابُ الْيَم۪ينِۜ', 'Ve ashabul yemini ma ashabul yemin.', 'Sağın adamları![1] Nedir sağın adamları?', 'واصحب اليمين ما اصحب اليمين'),
(5007, 56, 28, 'ف۪ي سِدْرٍ مَخْضُودٍۙ', 'Fi sidrin mahdud.', 'Dikensiz sedir ağaçları içindedirler.', 'في سدر مخضود'),
(5008, 56, 29, 'وَطَلْحٍ مَنْضُودٍۙ', 'Ve talhın mendud.', 'Salkım salkım muz ağaçları,', 'وطلح منضود'),
(5009, 56, 30, 'وَظِلٍّ مَمْدُودٍۙ', 'Ve zıllin memdud.', 'Uzamış gölgeler,', 'وظل ممدود'),
(5010, 56, 31, 'وَمَٓاءٍ مَسْكُوبٍۙ', 'Ve main meskub.', 'Ve çağlayan sular,', 'وما مسكوب'),
(5011, 56, 32, 'وَفَاكِهَةٍ كَث۪يرَةٍۙ', 'Ve fakihetin kesirah', 'Her türden meyveler,', 'وفكهة كثيرة'),
(5012, 56, 33, 'لَا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍۙ', 'La maktuatin ve la memnuah.', 'Tükenmeyen ve yasaklanmayan,', 'لا مقطوعة ولا ممنوعة'),
(5013, 56, 34, 'وَفُرُشٍ مَرْفُوعَةٍۜ', 'Ve furuşin merfuah.', 'Kabartılmış[1] döşeklerdedirler.', 'وفرش مرفوعة'),
(5014, 56, 35, 'اِنَّٓا اَنْشَأْنَاهُنَّ اِنْشَٓاءًۙ', 'İnna enşe\'na hunne inşaa.', 'Biz,  onları yeni bir düzenleme ile düzenledik.', 'انا انشانهن انشا'),
(5015, 56, 36, 'فَجَعَلْنَاهُنَّ اَبْكَاراًۙ', 'Fe cealna hunne ebkaran.', 'Onları dokunulmamışlar[1] yaptık.', 'فجعلنهن ابكارا'),
(5016, 56, 37, 'عُـرُباً اَتْـرَاباًۙ', 'Uruben etraba.', 'Sahibini yadırgamayan[1].', 'عربا اترابا'),
(5017, 56, 38, 'لِاَصْحَـابِ الْيَم۪ينِۜ ۟', 'Li ashabil yemin.', 'Sağın adamları için.', 'لاصحب اليمين'),
(5018, 56, 39, 'ثُلَّةٌ مِنَ الْاَوَّل۪ينَۙ', 'Sulletun minel evvelin.', 'Bir kısmı öncekilerdendir.', 'ثلة من الاولين'),
(5019, 56, 40, 'وَثُلَّةٌ مِنَ الْاٰخِر۪ينَۜ', 'Ve sulletun minel ahırin.', 'Bir kısmı sonrakilerdendir.', 'وثلة من الاخرين'),
(5020, 56, 41, 'وَاَصْحَابُ الشِّمَالِۙ مَٓا اَصْحَابُ الشِّمَالِۜ', 'Ve ashabuş şimali ma ashabuş şimal.', 'Ve solun adamları![1] Nedir solun adamları?', 'واصحب الشمال ما اصحب الشمال'),
(5021, 56, 42, 'ف۪ي سَمُومٍ وَحَم۪يمٍۙ', 'Fi semumin ve hamim.', 'Kavurucu bir azap ve kaynar su içindedirler.', 'في سموم وحميم'),
(5022, 56, 43, 'وَظِلٍّ مِنْ يَحْمُومٍۙ', 'Ve zıllin min yahmum.', 'Ve kara bir dumanın gölgesinde,', 'وظل من يحموم'),
(5023, 56, 44, 'لَا بَارِدٍ وَلَا كَر۪يمٍ', 'La baridin ve la kerim.', 'Serin olmayan,  faydası olamayan!', 'لا بارد ولا كريم'),
(5024, 56, 45, 'اِنَّهُمْ كَانُوا قَبْلَ ذٰلِكَ مُتْرَف۪ينَۚ', 'İnnehum kanu kable zalike mutrefin.', 'Çünkü onlar bundan önce varlık içinde zevklerine dalmışlardı.', 'انهم كانوا قبل ذلك مترفين'),
(5025, 56, 46, 'وَكَانُوا يُصِرُّونَ عَلَى الْحِنْثِ الْعَظ۪يمِۚ', 'Ve kanu yusirrune alel hınsil azim.', 'Büyük ihanette ısrar ediyorlardı.', 'وكانوا يصرون علي الحنث العظيم'),
(5026, 56, 47, 'وَكَانُوا يَقُولُونَ اَئِذَا مِتْنَا وَكُنَّا تُرَاباً وَعِظَاماً ءَاِنَّا لَمَبْعُوثُونَۙ', 'Ve kanu yekulune e iza mitna ve kunna turaben ve iza men e inna le meb\'usun.', 'Ve \"Biz ölüp,  toprak ve kemik yığını olduktan sonra mı yeniden diriltileceğiz?\" diyorlardı.', 'وكانوا يقولون ايذا متنا وكنا ترابا وعظما انا لمبعوثون'),
(5027, 56, 48, 'اَوَاٰبَٓاؤُ۬نَا الْاَوَّلُونَ', 'E ve abaunel evvelun.', 'Bizden önce ölmüş olan atalarımız da mı?', 'اواباونا الاولون'),
(5028, 56, 49, 'قُلْ اِنَّ الْاَوَّل۪ينَ وَالْاٰخِر۪ينَۙ', 'Kul innel evveline vel ahirin.', 'De ki: \"Öncekiler de sonrakiler de diriltilecekler.\"', 'قل ان الاولين والاخرين'),
(5029, 56, 50, 'لَمَجْمُوعُونَ اِلٰى م۪يقَاتِ يَوْمٍ مَعْلُومٍ', 'Le mecmuune ila mikati yevmin ma\'lum.', 'Bilinen günün belli olan zamanında kesinlikle toplanmış olacaklar.', 'لمجموعون الي ميقت يوم معلوم'),
(5030, 56, 51, 'ثُمَّ اِنَّكُمْ اَيُّهَا الضَّٓالُّونَ الْمُكَذِّبُونَۙ', 'Summe innekum eyyuhed dallunel mukezzibun.', 'Sonra siz,  ey gerçekten sapkınlıkta olan yalancılar!', 'ثم انكم ايها الضالون المكذبون'),
(5031, 56, 52, 'لَاٰكِلُونَ مِنْ شَجَرٍ مِنْ زَقُّومٍۙ', 'Le akilune min şecerin min zakkumin.', 'Kesinlikle zakkum ağacından yiyecek olanlarsınız!', 'لاكلون من شجر من زقوم'),
(5032, 56, 53, 'فَمَالِـؤُ۫نَ مِنْهَا الْبُطُونَۚ', 'Fe ma liune minhel butun.', 'Karınlarınızı onunla dolduracaksınız!', 'فمالون منها البطون'),
(5033, 56, 54, 'فَشَارِبُونَ عَلَيْهِ مِنَ الْحَم۪يمِۚ', 'Fe şaribune aleyhi minel hamim.', 'Sonra da onun üzerine kaynar sudan içeceksiniz.', 'فشربون عليه من الحميم'),
(5034, 56, 55, 'فَشَارِبُونَ شُرْبَ الْه۪يمِۜ', 'Fe şaribune şurbel him.', 'Hem de susuz kalmış develerin içişi gibi içeceksiniz.', 'فشربون شرب الهيم'),
(5035, 56, 56, 'هٰذَا نُزُلُهُمْ يَوْمَ الدّ۪ينِۜ', 'Haza nuzuluhum yevmed din.', 'İşte bu,  Din Günü\'nde[1] onların ziyafetleridir.', 'هذا نزلهم يوم الدين'),
(5036, 56, 57, 'نَحْنُ خَلَقْنَاكُمْ فَلَوْلَا تُصَدِّقُونَ۟', 'Nahnu halaknakum fe lev la tusaddikun.', 'Sizi Biz yarattık. Bu gerçeği hala kabul etmeyecek misiniz?', 'نحن خلقنكم فلولا تصدقون'),
(5037, 56, 58, 'اَفَرَاَيْتُمْ مَا تُمْنُونَۜ', 'E fe reeytum ma tumnun.', 'Öyleyse akıttığınız şeyin[1] ne olduğunu hiç düşündünüz mü?', 'افريتم ما تمنون'),
(5038, 56, 59, 'ءَاَنْتُمْ تَخْلُقُونَهُٓ اَمْ نَحْنُ الْخَالِقُونَ', 'E entum tahlukunehu em nahnul halikun.', 'Onu siz mi yaratıyorsunuz,  yoksa yaratan Biz miyiz?', 'انتم تخلقونه ام نحن الخلقون'),
(5039, 56, 60, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ الْمَوْتَ وَمَا نَحْنُ بِمَسْبُوق۪ينَۙ', 'Nahnu kadderna beynekumul mevte ve ma nahnu bi mes- bukin.', 'Aranızda ölümü Biz takdir ettik. Kimse Bizi engelleyemez.', 'نحن قدرنا بينكم الموت وما نحن بمسبوقين'),
(5040, 56, 61, 'عَلٰٓى اَنْ نُبَدِّلَ اَمْثَالَكُمْ وَنُنْشِئَكُمْ ف۪ي مَا لَا تَعْلَمُونَ', 'Ala en nubeddile emsalekum ve nunşiekum fi ma la ta\'lemun.', 'Yapınızı değiştirip,  sizi bilmediğiniz bir şekilde,  yeniden yapma gücünden yoksun değiliz.', 'علي ان نبدل امثلكم وننشيكم في ما لا تعلمون'),
(5041, 56, 62, 'وَلَقَدْ عَلِمْتُمُ النَّشْاَةَ الْاُو۫لٰى فَلَوْلَا تَذَكَّرُونَ', 'Ve lekad alimtumunneş etel ula fe lev la tezekkerun.', 'Ant olsun ki ilk meydana getirmeyi bildiniz. Düşünüp öğüt almanız gerekmez mi?', 'ولقد علمتم النشاة الاولي فلولا تذكرون'),
(5042, 56, 63, 'اَفَرَاَيْتُمْ مَا تَحْرُثُونَۜ', 'E fe reeytum ma tahrusun.', 'Ektiklerinizi görmüyor musunuz?', 'افريتم ما تحرثون'),
(5043, 56, 64, 'ءَاَنْتُمْ تَزْرَعُونَهُٓ  اَمْ نَحْنُ الزَّارِعُونَ', 'E entum tezre unehu em nahnuz zariun.', 'Onu siz mi yetiştiriyorsunuz,  yoksa Biz mi?', 'انتم تزرعونه ام نحن الزرعون'),
(5044, 56, 65, 'لَوْ نَشَٓاءُ لَجَعَلْنَاهُ حُطَاماً فَظَلْتُمْ تَفَكَّهُونَ', 'Lev neşau le cealnahu hutamen fe zaltum tefekkehun.', 'Dileseydik kesinlikle onu çer-çöp yapardık da siz şaşırıp kalırdınız.', 'لو نشا لجعلنه حطما فظلتم تفكهون'),
(5045, 56, 66, 'اِنَّا لَمُغْرَمُونَۙ', 'İnna le mugremun.', '\"Gerçekten borçlandık;\"', 'انا لمغرمون'),
(5046, 56, 67, 'بَلْ نَحْنُ مَحْرُومُونَ', 'Bel nahnu mahrumun.', '\"Doğrusu,  yoksun bırakıldık.\"', 'بل نحن محرومون'),
(5047, 56, 68, 'اَفَرَاَيْتُمُ الْمَٓاءَ الَّذ۪ي تَشْرَبُونَۜ', 'E fe reeytumul maellezi teşrebun.', 'Peki,  içtiğiniz suya hiç baktınız mı?[1]', 'افريتم الما الذي تشربون'),
(5048, 56, 69, 'ءَاَنْتُمْ اَنْزَلْتُمُوهُ مِنَ الْمُزْنِ اَمْ نَحْنُ الْمُنْزِلُونَ', 'E entum enzeltumuhu minel muzni em nahnul munzilun.', 'Onu bulutlardan indiren siz misiniz,  yoksa indiren Biz miyiz?', 'انتم انزلتموه من المزن ام نحن المنزلون'),
(5049, 56, 70, 'لَوْ نَشَٓاءُ جَعَلْنَاهُ اُجَاجاً فَلَوْلَا تَشْكُرُونَ', 'Lev neşau cealnahu ucacen fe levla teşkurun.', 'Eğer dileseydik onu tuzlu yapardık. Buna şükretmeniz gerekmez mi?', 'لو نشا جعلنه اجاجا فلولا تشكرون'),
(5050, 56, 71, 'اَفَرَاَيْتُمُ النَّارَ الَّت۪ي تُورُونَۜ', 'E fe reeytumun narelleti turun.', 'Yaktığınız o ateşe baktınız mı hiç?', 'افريتم النار التي تورون'),
(5051, 56, 72, 'ءَاَنْتُمْ اَنْشَأْتُمْ شَجَرَتَـهَٓا اَمْ نَحْنُ الْمُنْشِؤُ۫نَ', 'E entum enşe\'tum şecereteha em nahnul munşiun.', 'Onun ağacını siz mi yetiştirdiniz,  yoksa yetiştiren Biz miyiz?', 'انتم انشاتم شجرتها ام نحن المنشون'),
(5052, 56, 73, 'نَحْنُ جَعَلْنَاهَا تَذْكِرَةً وَمَتَاعاً لِلْمُقْو۪ينَۚ', 'Nahnu cealnaha tezkireten ve metaan lil mukvin.', 'Biz,  onu bir hatırlatma ve ihtiyaç sahipleri için bir yararlanma kaynağı yaptık.', 'نحن جعلنها تذكرة ومتعا للمقوين'),
(5053, 56, 74, 'فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظ۪يمِ۟', 'Fe sebbih bismi rabbikel azim.', 'O halde Azim[1] Rabb\'inin adını tesbih[2] et.', 'فسبح باسم ربك العظيم'),
(5054, 56, 75, 'فَلَٓا اُقْسِمُ بِمَوَاقِـعِ النُّجُومِۙ', 'Fe la uksimu bi mevakiin nucum.', 'Hayır,  yıldızların yerleri üzerine yemin ederim;', 'فلا اقسم بموقع النجوم'),
(5055, 56, 76, 'وَاِنَّهُ لَقَسَمٌ لَوْ تَعْلَمُونَ عَظ۪يمٌۙ', 'Ve innehu le kasemun lev ta\'lemune azim.', 'Eğer bilirseniz bu yüce bir yemindir.', 'وانه لقسم لو تعلمون عظيم'),
(5056, 56, 77, 'اِنَّهُ لَقُرْاٰنٌ كَر۪يمٌۙ', 'İnnehu le kur\'anun kerim.', 'Kuşkusuz o,  kesinlikle Kerim[1] bir Kur\'an\'dır.', 'انه لقران كريم'),
(5057, 56, 78, 'ف۪ي كِتَابٍ مَكْنُونٍۙ', 'Fi kitabin meknun.', 'Korunmuş bir kitaptadır.[1]', 'في كتب مكنون'),
(5058, 56, 79, 'لَا يَمَسُّهُٓ اِلَّا الْمُطَهَّرُونَۜ', 'La yemessuhu illel mutahherun.', 'Ona arındırılmış olanlardan başkası dokunamaz.[1]', 'لا يمسه الا المطهرون'),
(5059, 56, 80, 'تَنْز۪يلٌ مِنْ رَبِّ الْعَالَم۪ينَ', 'Tenzilun min rabbil alemin.', 'O,  alemlerin Rabb\'inden indirilmedir.', 'تنزيل من رب العلمين'),
(5060, 56, 81, 'اَفَبِهٰذَا الْحَد۪يثِ اَنْتُمْ مُدْهِنُونَۙ', 'E fe bi hazel hadisi entum mudhinun.', 'Böyle bir hadisi[1] mi hafife alıyorsunuz?', 'افبهذا الحديث انتم مدهنون'),
(5061, 56, 82, 'وَتَجْعَلُونَ رِزْقَـكُمْ اَنَّكُمْ تُكَذِّبُونَ', 'Ve tec\'alune rızkakum ennekum tukezzibun.', 'Verilen rızıklara yalanlayarak mı karşılık veriyorsunuz?', 'وتجعلون رزقكم انكم تكذبون'),
(5062, 56, 83, 'فَلَوْلَٓا اِذَا بَلَغَتِ الْحُلْقُومَۙ', 'Fe lev la iza belegatil hulkume.', 'Can boğaza dayandığı zaman;', 'فلولا اذا بلغت الحلقوم'),
(5063, 56, 84, 'وَاَنْتُمْ ح۪ينَئِذٍ تَنْظُرُونَۙ', 'Ve entum hine izin tenzurun.', 'O zaman bakınıp durursunuz.', 'وانتم حينيذ تنظرون'),
(5064, 56, 85, 'وَنَحْنُ اَقْرَبُ اِلَيْهِ مِنْكُمْ وَلٰـكِنْ لَا تُبْصِرُونَ', 'Ve nahnu akrabu ileyhi minkum ve lakin la tubsirun', 'Biz ona sizden daha yakınız fakat siz göremezsiniz.', 'ونحن اقرب اليه منكم ولكن لا تبصرون'),
(5065, 56, 86, 'فَلَوْلَٓا اِنْ كُنْتُمْ غَيْرَ مَد۪ين۪ينَۙ', 'Fe lev la in kuntum gayre medinin.', 'Mademki hesap sorulacak kimseler değilsiniz,', 'فلولا ان كنتم غير مدينين'),
(5066, 56, 87, 'تَرْجِعُونَـهَٓا اِنْ كُنْتُمْ صَادِق۪ينَ', 'Terciuneha in kuntum sadikin.', 'Eğer doğrulardansanız,  onu[1] geri çevirmeniz gerekmez mi?', 'ترجعونها ان كنتم صدقين'),
(5067, 56, 88, 'فَاَمَّٓا اِنْ كَانَ مِنَ الْمُقَرَّب۪ينَۙ', 'Fe emma in kane minel mukarrebine.', 'Fakat eğer o,  yaklaştırılanlardan ise,', 'فاما ان كان من المقربين'),
(5068, 56, 89, 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَع۪يمٍ', 'Fe revhun ve reyhanun ve cennetu naim.', 'O takdirde,  rahat bir hayat,  huzur,  güzel kokulu rızık ve nimetlerle dolu bir Cennet vardır.', 'فروح وريحان وجنت نعيم'),
(5069, 56, 90, 'وَاَمَّٓا اِنْ كَانَ مِنْ اَصْحَابِ الْيَم۪ينِۙ', 'Ve emma in kane min ashabil yemin.', 'Ve eğer o,  sağın adamlarından[1] ise,', 'واما ان كان من اصحب اليمين'),
(5070, 56, 91, 'فَسَلَامٌ لَكَ مِنْ اَصْحَابِ الْيَم۪ينِ', 'Fe selamun leke min ashabil yemin.', 'O zaman sağın adamlarından,  \"Sana selam olsun.\"', 'فسلم لك من اصحب اليمين'),
(5071, 56, 92, 'وَاَمَّٓا اِنْ كَانَ مِنَ الْمُكَذِّب۪ينَ الضَّٓالّ۪ينَۙ', 'Ve emma in kane minel mukezzibined dallin.', 'Ama sapkınlıkta olan yalanlayıcılardan ise,', 'واما ان كان من المكذبين الضالين'),
(5072, 56, 93, 'فَنُزُلٌ مِنْ حَم۪يمٍۙ', 'Fe nuzulun min hamim.', 'O zaman kaynar sudan bir ziyafet vardır!', 'فنزل من حميم'),
(5073, 56, 94, 'وَتَصْلِيَةُ جَح۪يمٍۙ', 'Ve tasliyetu cahim.', 'Ve Cehennem\'e atılma vardır.', 'وتصلية جحيم'),
(5074, 56, 95, 'اِنَّ هٰذَا لَهُوَ حَقُّ الْيَق۪ينِۚ', 'İnne haza le huve hakkul yakin.', 'Kuşkusuz bu bildirdiklerimiz kesin olarak gerçektir.', 'ان هذا لهو حق اليقين'),
(5075, 56, 96, 'فَسَبِّـحْ بِاسْمِ رَبِّكَ الْعَظ۪يمِ', 'Fe sebbih bismi rabbikel azim.', 'O halde Azim[1] Rabb\'inin adını tesbih[2] et.', 'فسبح باسم ربك العظيم'),
(5076, 57, 1, 'سَبَّحَ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۚ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Sebbeha lillahi ma fis semavati vel ard, ve huvel azizul hakim.', 'Göklerde ve yerde olanlar,  Allah\'ı tesbih[1] etmektedir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'سبح لله ما في السموت والارض وهو العزيز الحكيم'),
(5077, 57, 2, 'لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۚ يُحْـي۪ وَيُم۪يتُۚ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Lehu mulkus semavati vel ard, yuhyi ve yumit, ve huve ala kulli şey\'in kadir.', 'Göklerin ve yeryüzünün mülkü[1] yalnızca O\'nundur. O,  diriltir ve öldürür. O,  Her Şeye Güç Yetiren\'dir.', 'له ملك السموت والارض يحي ويميت وهو علي كل شي قدير'),
(5078, 57, 3, 'هُوَ الْاَوَّلُ وَالْاٰخِرُ وَالظَّاهِرُ وَالْبَاطِنُۚ وَهُوَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Huvel evvelu vel ahiru vez zahiru vel batın, ve huve bi kulli şey\'in alim.', 'O,  Evvel\'dir ve Âhir\'dir; Zahir\'dir,  Batın\'dır.[1] Ve O,  Her Şeyi En İyi Bilen\'dir.', 'هو الاول والاخر والظهر والباطن وهو بكل شي عليم'),
(5079, 57, 4, 'هُوَ الَّذ۪ي خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ ف۪ي سِتَّةِ اَيَّامٍ ثُمَّ اسْتَوٰى عَلَى الْعَرْشِۜ يَعْلَمُ مَا يَلِجُ فِي الْاَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنْزِلُ مِنَ السَّمَٓاءِ وَمَا يَعْرُجُ ف۪يهَاۜ وَهُوَ مَعَكُمْ اَيْنَ مَا كُنْتُمْۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Huvellezi halakas semavati vel ardafisitteti eyyamin summesteva alel arş, a\'lemu ma yelicu fil ardı ve ma yahrucu minha ve ma yenzilu mines semai ve ma ya\'rucu fiha, ve huve meakum eyne ma kuntum, vallahu bi ma ta\'melune basir.', 'O,  gökleri ve yeri altı günde[1] yarattı. Sonra arşa isteva etti.[2] O,  yere gireni ve ondan çıkanı,  gökten ineni ve ona yükseleni bilir. Ve nerede olursanız olun,  O,  sizinle beraberdir. Allah,  Yaptıklarınızı En İyi Gören\'dir.', 'هو الذي خلق السموت والارض في ستة ايام ثم استوي علي العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السما وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير'),
(5080, 57, 5, 'لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ وَاِلَى اللّٰهِ تُرْجَعُ الْاُمُورُ', 'Lehu mulkus semavati vel ard, ve ilallahi turceul umur.', 'Göklerin ve yeryüzünün mülkü[1] O\'nundur. Bütün işler yalnızca Allah\'a döndürülür.', 'له ملك السموت والارض والي الله ترجع الامور'),
(5081, 57, 6, 'يُولِجُ الَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي الَّيْلِۜ وَهُوَ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Yulicul leyle fin nehari ve yulicun nehare fil leyl ve huve alimun bi zatis sudur.', 'Geceyi gündüze katar,  gündüzü geceye katar. O,  göğüslerin özünü en iyi bilendir.', 'يولج اليل في النهار ويولج النهار في اليل وهو عليم بذات الصدور'),
(5082, 57, 7, 'اٰمِنُوا بِاللّٰهِ وَرَسُولِه۪ وَاَنْفِقُوا مِمَّا جَعَلَكُمْ مُسْتَخْلَف۪ينَ ف۪يهِۜ فَالَّذ۪ينَ اٰمَنُوا مِنْكُمْ وَاَنْفَقُوا لَهُمْ اَجْرٌ كَب۪يرٌ', 'Aminu billahi ve resulihi ve enfiku mimma cealekum mustahlefine fih, fellezine amenu minkum ve enfeku lehum ecrun kebir.', 'Allah\'a ve Resul\'üne inanın. Sizi sahip kıldığı şeylerden,  ihtiyaç sahiplerine yardım edin. Bilin ki sizden iman edip,  ihtiyaç sahiplerine yardım edenler için büyük ödül vardır.', 'امنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين امنوا منكم وانفقوا لهم اجر كبير'),
(5083, 57, 8, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِاللّٰهِۚ وَالرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا بِرَبِّكُمْ وَقَدْ اَخَذَ م۪يثَاقَكُمْ اِنْ كُنْتُمْ مُؤْمِن۪ينَ', 'Ve ma lekum la tu\'minune billah, ver resulu yed\'ukum li tu\'minu bi rabbikum ve kad e haze misakakum in kuntum mu\'minin.', 'Eğer gerçekten Mü\'minseniz,  size ne oluyor da Resul sizi Rabb\'inize güvenmeye[1] çağırdığı halde,  Allah\'a güvenmiyorsunuz? Oysa sizden kesin söz almıştı.[2]', 'وما لكم لا تومنون بالله والرسول يدعوكم لتومنوا بربكم وقد اخذ ميثقكم ان كنتم مومنين'),
(5084, 57, 9, 'هُوَ الَّذ۪ي يُنَزِّلُ عَلٰى عَبْدِه۪ٓ  اٰيَاتٍ بَيِّنَاتٍ لِيُخْرِجَكُمْ مِنَ الظُّلُمَاتِ اِلَى النُّورِۜ وَاِنَّ اللّٰهَ بِكُمْ لَرَؤُ۫فٌ رَح۪يمٌ', 'Huvellezi yunezzilu ala abdihi ayatin beyyinatin li yuhricekum minez zulumati ilen nur, ve innellahe bikum le raufun rahim.', 'Sizi karanlıklardan aydınlığa çıkarmak için kuluna kanıt içeren açıklayıcı ayetleri indiren O\'dur. Kuşkusuz Allah,  Çok Şefkatli\'dir,  Rahmeti Kesintisiz\'dir.', 'هو الذي ينزل علي عبده ايت بينت ليخرجكم من الظلمت الي النور وان الله بكم لروف رحيم'),
(5085, 57, 10, 'وَمَا لَكُمْ اَلَّا تُنْفِقُوا ف۪ي سَب۪يلِ اللّٰهِ وَلِلّٰهِ م۪يرَاثُ السَّمٰوَاتِ وَالْاَرْضِۜ لَا يَسْتَو۪ي مِنْكُمْ مَنْ اَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقَاتَلَۜ  اُو۬لٰٓئِكَ اَعْظَمُ دَرَجَةً مِنَ الَّذ۪ينَ اَنْفَقُوا مِنْ بَعْدُ وَقَاتَلُواۜ وَكُلاًّ وَعَدَ اللّٰهُ الْحُسْنٰىۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ۟', 'Ve ma lekum ella tunfiku fi sebilillahi, ve lillahi mirasus semavati vel ard, la yestevi minkum men enfeka min kablil fethi ve katel, ulaike a\'zamu dereceten minellezine enfeku min ba\'du ve katelu ve kullen ve adallahul husna, vallahu bi ma ta\'melune habir.', 'Size ne oluyor ki,  göklerin ve yerin son sahipliği Allah\'ın olduğu halde,  Allah\'ın yolunda harcamıyorsunuz? Sizden,  fetihten önce Allah yolunda harcayan ve savaşanla,  fetihten sonra harcayan ve savaşan bir değildir.[1] Onlar daha üstün derece sahibidirler. Allah,  hepsine \"en iyiyi\" söz verdi. Allah,  Yaptıklarınızdan En İyi Haberdar Olandır.', 'وما لكم الا تنفقوا في سبيل الله ولله ميرث السموت والارض لا يستوي منكم من انفق من قبل الفتح وقتل اوليك اعظم درجة من الذين انفقوا من بعد وقتلوا وكلا وعد الله الحسني والله بما تعملون خبير'),
(5086, 57, 11, 'مَنْ ذَا الَّذ۪ي يُقْرِضُ اللّٰهَ قَرْضاً حَسَناً فَيُضَاعِفَهُ لَهُ وَلَهُٓ  اَجْرٌ كَر۪يمٌۚ', 'Men zellezi yukridullahe kardan hasenen fe yudaifehu lehu ve lehu ecrun kerim.', 'Kim ki Allah\'a iyi bir ödünç verirse,  Allah,  ona karşılığını katlayarak verir. Ve onun için şerefli bir karşılık vardır.', 'من ذا الذي يقرض الله قرضا حسنا فيضعفه له وله اجر كريم'),
(5087, 57, 12, 'يَوْمَ تَرَى الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ يَسْعٰى نُورُهُمْ بَيْنَ اَيْد۪يهِمْ وَبِاَيْمَانِهِمْ بُشْرٰيكُمُ الْيَوْمَ جَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ ذٰلِكَ هُوَ الْفَوْزُ الْعَظ۪يمُۚ', 'Yevme terel mu\'minine vel mu\'minati yes\'a nuruhum beyne eydihim ve bi eymanihim buşrakumul yevme cennatun tecri min tahtihel enharu halidine fih, zalike huvel fevzul azim.', 'O gün,  mü\'min erkekleri ve mü\'min kadınları,  nurları[1] önlerinde ve sağlarında[2] olduğu halde koşarlarken göreceksin. \"Bugün müjdeniz; içinde sürekli kalacağınız,  içinden ırmaklar akan Cennetlerdir. İşte bu büyük kurtuluştur.\"', 'يوم تري المومنين والمومنت يسعي نورهم بين ايديهم وبايمنهم بشريكم اليوم جنت تجري من تحتها الانهر خلدين فيها ذلك هو الفوز العظيم'),
(5088, 57, 13, 'يَوْمَ يَقُولُ الْمُنَافِقُونَ وَالْمُنَافِقَاتُ لِلَّذ۪ينَ اٰمَنُوا انْظُرُونَا نَقْتَبِسْ مِنْ نُورِكُمْ ق۪يلَ ارْجِعُوا وَرَٓاءَكُمْ فَالْتَمِسُوا نُوراًۜ فَضُرِبَ بَيْنَهُمْ بِسُورٍ لَهُ بَابٌۜ بَاطِنُهُ ف۪يهِ الرَّحْمَةُ وَظَاهِرُهُ مِنْ قِبَلِهِ الْعَذَابُۜ', 'Yevme yekulul munafikune vel munafikatu lillezine amenunzuruna naktebis min nurikum, kilerci\'u veraekum fel temisu nura, fe duribe beynehum bi surin lehu bab, batınuhu fihir rahmetu ve zahiruhu min kıbelihil azab.', 'O gün münafık erkekler ve münafık kadınlar,  inanan kimselere: \"Bize bakın da nurunuzdan biraz yararlanalım.\" derler. Onlara: \"Arkanıza dönün de oradan nur[1] arayın.\" denir. O anda aralarına kapısı olan bir duvar çekilir; duvarın iç tarafı rahmet,  dış tarafında ise azap vardır.', 'يوم يقول المنفقون والمنفقت للذين امنوا انظرونا نقتبس من نوركم قيل ارجعوا وراكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظهره من قبله العذاب'),
(5089, 57, 14, 'يُنَادُونَهُمْ اَلَمْ نَكُنْ مَعَكُمْۜ قَالُوا بَلٰى وَلٰكِنَّكُمْ فَـتَنْتُمْ اَنْفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ الْاَمَانِيُّ حَتّٰى جَٓاءَ اَمْرُ اللّٰهِ وَغَرَّكُمْ بِاللّٰهِ الْغَرُورُ', 'Yunadunehum e lem nekun meakum, kalu bela ve lakinnekum fe tentum enfusekum ve terebbastum vertebtum ve garret kumul emaniyyu hatta cae emrullahi ve garrekum billahil garur.', 'İnananlara,  \"Biz sizinle beraber değil miydik?\" diye seslenirler. İnananlar,  \"Evet,  ama siz kendinizi fitneye düşürdünüz[1],  bekleyip,  kuşku duydunuz.[2] Allah\'ın emri gelinceye kadar[3] tutku ve kuruntularınız sizi aldattı. Ve o ğarur[4] da sizi Allah ile aldattı.\"[5] dediler.', 'ينادونهم الم نكن معكم قالوا بلي ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتي جا امر الله وغركم بالله الغرور'),
(5090, 57, 15, 'فَالْيَوْمَ لَا يُؤْخَذُ مِنْكُمْ فِدْيَةٌ وَلَا مِنَ الَّذ۪ينَ كَفَرُواۜ مَأْوٰيكُمُ النَّارُۜ هِيَ مَوْلٰيكُمْۜ وَبِئْسَ الْمَص۪يرُ', 'Fel yevme la yu\'hazu minkum fid yetun ve la minellezine keferu, me\'vakumun nar, hiye mevlakum, ve bi\'sel masir.', 'Bugün artık sizden kurtuluş fidyesi kabul edilmez ve Kafirlerden[1] de. Sizin varacağınız yer ateştir. Sizin mevlanız[2] odur. Ne kötü varış yeridir o.', 'فاليوم لا يوخذ منكم فدية ولا من الذين كفروا ماويكم النار هي موليكم وبيس المصير'),
(5091, 57, 16, 'اَلَمْ يَأْنِ لِلَّذ۪ينَ اٰمَنُٓوا اَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللّٰهِ وَمَا نَزَلَ مِنَ الْحَقِّۙ وَلَا يَكُونُوا كَالَّذ۪ينَ اُو۫تُوا الْكِتَابَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْاَمَدُ فَقَسَتْ قُلُوبُهُمْۜ وَكَث۪يرٌ مِنْهُمْ فَاسِقُونَ', 'E lem ye\'ni lillezine amenu en tahşea kulubuhum li zikrillahi ve ma nezele minel hakkı ve la yekunu kellezine utul kitabe min kablu fe tale aleyhimul emedu fe kaset kulubuhum, ve kesirun minhum fasikun.', 'İnananların; Allah\'ın öğütlerini dinleyip de Hakk\'tan gelen şeyle kalplerinin yumuşaması zamanı gelmedi mi? Daha önce kendilerine Kitap verilip,  üzerinden uzun zaman geçince kalpleri katılaşanlar gibi olmasınlar. Onların çoğu fasık kimselerdi.[1]', 'الم يان للذين امنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فسقون'),
(5092, 57, 17, 'اِعْلَمُٓوا اَنَّ اللّٰهَ يُحْـيِ الْاَرْضَ بَعْدَ مَوْتِهَاۜ  قَدْ بَيَّنَّا لَكُمُ الْاٰيَاتِ لَعَلَّكُمْ تَعْقِلُونَ', 'İ\'lemu ennellahe yuhyil arda ba\'de mevtiha, kad beyyenna lekumul ayati leallekum ta\'kılun.', 'Bilin ki yeryüzünü ölümünden sonra dirilten Allah\'tır. Aklınızı kullanırsınız diye ayetleri[1] sizin için açıkça ortaya koyduk.', 'اعلموا ان الله يحي الارض بعد موتها قد بينا لكم الايت لعلكم تعقلون'),
(5093, 57, 18, 'اِنَّ الْمُصَّدِّق۪ينَ وَالْمُصَّدِّقَاتِ وَاَقْرَضُوا اللّٰهَ قَرْضاً حَسَناً يُضَاعَفُ لَهُمْ وَلَهُمْ اَجْرٌ كَر۪يمٌ', 'İnnel mussaddikine vel mussaddikati ve akradullahe kardan hasenen yudaafu lehum ve lehum ecrun kerim.', 'Sadaka[1] veren erkeklerin,  sadaka veren kadınların ve Allah\'a iyi bir ödünç verenlerin,  verdikleri katlanarak geri ödenir. Ve ayrıca onlar için çok şerefli bir ödül vardır.', 'ان المصدقين والمصدقت واقرضوا الله قرضا حسنا يضعف لهم ولهم اجر كريم'),
(5094, 57, 19, 'وَالَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَرُسُلِـه۪ٓ اُو۬لٰٓئِكَ هُمُ الصِّدّ۪يقُونَۗ وَالشُّهَدَٓاءُ عِنْدَ رَبِّهِمْۜ لَهُمْ اَجْرُهُمْ وَنُورُهُمْۜ وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَٓا اُو۬لٰٓئِكَ اَصْحَابُ الْجَح۪يمِ۟', 'Vellezine amenu billahi ve rusulihi ulaike humus sıddikune veş şuhedau inde rabbihim, lehum ecruhum ve nuruhum, vellezine keferu ve kezzebu bi ayatina ulaike ashabul cahim.', 'Allah\'a ve Resullerine iman edenler; işte onlar Sıddıklardır.[1] Ve Rableri yanında şahitlerdir.[2] Onların ödülleri ve nurları[3] vardır. İnkar eden ve ayetlerimizi yalanlayanlar,  işte onlar Cehennem halkıdırlar.', 'والذين امنوا بالله ورسله اوليك هم الصديقون والشهدا عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا بايتنا اوليك اصحب الجحيم'),
(5095, 57, 20, 'اِعْلَمُٓوا اَنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَز۪ينَةٌ وَتَفَاخُرٌ بَيْنَكُمْ وَتَكَاثُرٌ فِي الْاَمْوَالِ وَالْاَوْلَادِۜ  كَمَثَلِ غَيْثٍ اَعْجَبَ الْكُفَّارَ نَبَاتُهُ ثُمَّ يَه۪يجُ فَتَرٰيهُ مُصْفَراًّ ثُمَّ يَكُونُ حُطَاماًۜ وَفِي الْاٰخِرَةِ عَذَابٌ شَد۪يدٌۙ وَمَغْفِرَةٌ مِنَ اللّٰهِ وَرِضْوَانٌۜ وَمَا الْحَيٰوةُ الدُّنْيَٓا اِلَّا مَتَاعُ الْغُرُورِ', 'İ\'lemu ennemel hayatud dunya leibun ve lehvun ve zinetun ve tefahurun beynekum ve tekasurun fil emvali vel evlad, ke meseli gaysin a\'cebel kuffare nebatuhu summe yehicu fe terahu musferren summe yekunu hutama, ve fil ahıreti azabun şedidun ve magfiretun minallahi ve rıdvan, ve mel hayatud dunya illa metaul gurur.', 'Bilin ki dünya hayatı bir oyundur,  bir oyalanmadır; aranızda bir ziynettir[1],  bir övünmedir,  mallarda ve çocuklarda çokluk yarışıdır. Onun durumu; bitirdiği bitkilerle Kafirlerin[2] hoşuna giden yağmur gibidir. Ardından o bitkileri kurur,  onları sararmış görürsün. Sonra da çer çöp olurlar. Ahirette,  şiddetli bir azap da Allah\'ın hoşnutluğu ve bağışlaması da vardır. Dünya hayatı ise aldatıcı bir metadan[3] başka bir şey değildir.', 'اعلموا انما الحيوة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الامول والاولد كمثل غيث اعجب الكفار نباته ثم يهيج فتريه مصفرا ثم يكون حطما وفي الاخرة عذاب شديد ومغفرة من الله ورضون وما الحيوة الدنيا الا متع الغرور'),
(5096, 57, 21, 'سَابِقُٓوا اِلٰى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَٓاءِ وَالْاَرْضِۙ اُعِدَّتْ لِلَّذ۪ينَ اٰمَنُوا بِاللّٰهِ وَرُسُلِه۪ۜ ذٰلِكَ فَضْلُ اللّٰهِ يُؤْت۪يهِ مَنْ يَشَٓاءُۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Sabiku ila magfiretin min rabbikum ve cennetin arduha keardıs semai vel ardı uıddet lillezine amenu billahi ve rusulih, zalike fadlullahi yu\'tihi men yeşau, vallahu zul fadlil azim.', 'Rabb\'inizin bağışlamasını,  Allah\'a ve Resullerine inananlar için hazırlanmış,  genişliği gökle yerin genişliği gibi olan Cennet\'i kazanmak için yarışın. İşte bu,  Allah\'ın lütfudur. Onu hak edene[1] verir. Ve Allah,  büyük lütuf sahibidir.', 'سابقوا الي مغفرة من ربكم وجنة عرضها كعرض السما والارض اعدت للذين امنوا بالله ورسله ذلك فضل الله يوتيه من يشا والله ذو الفضل العظيم'),
(5097, 57, 22, 'مَٓا اَصَابَ مِنْ مُص۪يبَةٍ فِي الْاَرْضِ وَلَا ف۪ٓي اَنْفُسِكُمْ اِلَّا ف۪ي كِتَابٍ مِنْ قَبْلِ اَنْ نَبْرَاَهَاۜ اِنَّ ذٰلِكَ عَلَى اللّٰهِ يَس۪يرٌۚ', 'Ma esabe min musibetin fil ardı ve la fi enfusikum illa fi kitabin min kabli en nebreeha, inne zalike alallahi yesir.', 'Ne yeryüzünde ne de kendinizde meydana gelen bir musibet[1] yoktur ki Biz onu gerçekleştirmeden[2] önce bir Kitap\'ta[3] yazılmamış olsun. Kuşkusuz bu Allah\'a kolaydır.', 'ما اصاب من مصيبة في الارض ولا في انفسكم الا في كتب من قبل ان نبراها ان ذلك علي الله يسير'),
(5098, 57, 23, 'لِكَيْلَا تَأْسَوْا عَلٰى مَا فَاتَكُمْ وَلَا تَفْرَحُوا بِمَٓا اٰتٰيكُمْۜ وَاللّٰهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍۙ', 'Li keyla te\'sev ala ma fatekum ve la tefrehu bi ma atakum, vallahu la yuhıbbu kulle muhtalin fehur.', 'Kaybettiklerinize üzülmemeniz,  Allah\'ın verdiği şeylerle şımarmamanız içindir. Allah,  kendisini beğenip böbürlenen hiç kimseyi sevmez.', 'لكيلا تاسوا علي ما فاتكم ولا تفرحوا بما اتيكم والله لا يحب كل مختال فخور'),
(5099, 57, 24, 'اَلَّذ۪ينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِۜ وَمَنْ يَتَوَلَّ فَاِنَّ اللّٰهَ هُوَ الْغَنِيُّ الْحَم۪يدُ', 'Ellezine yebhalune ve ye\'murunen nase bil buhl, ve men yetevelle feinnellahe huvel ganiyyul hamid.', 'Böyleleri cimrilik ederler ve insanlara da cimrilik yapmalarını tavsiye ederler. Kim yüz çevirirse[1] bilsin ki Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد'),
(5100, 57, 25, 'لَقَدْ اَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ وَاَنْزَلْنَا مَعَهُمُ الْكِتَابَ وَالْم۪يزَانَ لِيَقُومَ النَّاسُ بِالْقِسْطِۚ وَاَنْزَلْنَا الْحَد۪يدَ ف۪يهِ بَأْسٌ  شَد۪يدٌ  وَمَنَافِعُ  لِلنَّاسِ وَلِيَعْلَمَ اللّٰهُ  مَنْ  يَنْصُرُهُ وَرُسُلَهُ بِالْغَيْبِۜ اِنَّ اللّٰهَ قَوِيٌّ عَز۪يزٌ۟', 'Lekad erselna rusulena bil beyyinati ve enzelna meahumul kitabe vel mizane li yekumen nasu bil kıst, ve enzelnel hadide fihi be\'sun şedidun ve menafiu lin nasi ve li ya\'lemallahu men yensuruhu ve rusulehu bil gayb, innellahe kaviyyun aziz.', 'Ant olsun ki resullerimizi beyyinelerle[1] gönderdik. Ve insanlar haktan yana olsunlar diye resullerle birlikte Kitap\'ı ve mizanı[2] indirdik. Ayrıca kendisinde büyük bir güç ve insanlar için pek çok yararlar bulunan[3] demiri indirdik,  Kendisine[4] ve resullerine,  onların gıyabında[5] destek olan kimseler açıkça bilinsin! Kuşkusuz Allah,  Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'لقد ارسلنا رسلنا بالبينت وانزلنا معهم الكتب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنفع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز'),
(5101, 57, 26, 'وَلَقَدْ اَرْسَلْنَا نُوحاً وَاِبْرٰه۪يمَ وَجَعَلْنَا ف۪ي ذُرِّيَّتِهِمَا النُّبُوَّةَ وَالْكِتَابَ فَمِنْهُمْ مُهْتَدٍۚ وَكَث۪يرٌ مِنْهُمْ فَاسِقُونَ', 'Ve lekad erselna nuhan ve ibrahime ve cealna fi zurriyyetihimen nubuvvete vel kitabe fe minhum muhted, ve kesirun minhum fasikun.', 'Ant olsun ki Nuh\'u ve İbrahim\'i gönderdik. Onların soyundan nebiler kıldık ve onlara kitap verdik. Gönderildikleri halktan bir kısmı doğru yolu bulurken,  birçoğu da fasıktılar.[1]', 'ولقد ارسلنا نوحا وابرهيم وجعلنا في ذريتهما النبوة والكتب فمنهم مهتد وكثير منهم فسقون'),
(5102, 57, 27, 'ثُمَّ قَفَّيْنَا عَلٰٓى اٰثَارِهِمْ بِرُسُلِنَا وَقَفَّيْنَا بِع۪يسَى ابْنِ مَرْيَمَ وَاٰتَيْنَاهُ الْاِنْج۪يلَ وَجَعَلْنَا ف۪ي قُلُوبِ الَّذ۪ينَ اتَّبَعُوهُ رَأْفَةً  وَرَحْمَةًۜ  وَرَهْبَانِيَّةًۨ ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ اِلَّا ابْتِغَٓاءَ رِضْوَانِ اللّٰهِ فَمَا رَعَوْهَا حَقَّ رِعَايَـتِهَاۚ فَاٰتَيْنَا الَّذ۪ينَ اٰمَنُوا مِنْهُمْ اَجْرَهُمْۚ وَكَث۪يرٌ مِنْهُمْ فَاسِقُونَ', 'Summe kaffeyna ala asarihim bi rusulina ve kaffeyna bi\'isebni meryeme ve ateynahul incile ve cealna fi kulubillezinet tebeuhu re\'feten ve rahmeh, ve rahbaniyyetenibtedeuha ma ketebnaha aleyhim illebtigae rıdvanillahi fe ma reavha hakka riayetiha, fe ateynellezine amenu minhum ecrehum, ve kesirun minhum fasikun.', 'Sonra onların izleri üzerinde art arda resullerimizi gönderdik. Ve Meryem oğlu Îsa\'yı gönderdik ve ona İncil\'i verdik. Ona uyan kimselerin kalplerine şefkat ve merhamet koyduk. Allah\'ın rızasını kazanmak için uydurdukları ve fakat gereği gibi de uymadıkları ruhbanlık[1] Bizim buyruğumuzdan kaynaklanmış değildir. Onlardan iman edenlere ödüllerini verdik. Ne var ki onların çoğu doğru yoldan çıkmış kimselerdi.', 'ثم قفينا علي اثرهم برسلنا وقفينا بعيسي ابن مريم واتينه الانجيل وجعلنا في قلوب الذين اتبعوه رافة ورحمة ورهبانية ابتدعوها ما كتبنها عليهم الا ابتغا رضون الله فما رعوها حق رعايتها فاتينا الذين امنوا منهم اجرهم وكثير منهم فسقون'),
(5103, 57, 28, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَاٰمِنُوا بِرَسُولِه۪ يُؤْتِكُمْ كِفْلَيْنِ مِنْ رَحْمَتِه۪ وَيَجْعَلْ لَكُمْ نُوراً تَمْشُونَ بِه۪ وَيَغْفِرْ لَكُمْۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌۙ', 'Ya eyyuhellezine amenut tekullahe ve aminu bi resulihi yu\'tikum kifleyni min rahmetihi ve yec\'al lekum nuren temşune bihi ve yagfir lekum, vallahu gafurun rahim.', 'Ey inananlar! Allah için takvalı olun. O\'nun Resulüne inanın ki,  size rahmetinden iki pay versin. Ve size aydınlığında yürüyeceğiniz bir ışık yapsın. Sizi bağışlasın. Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها الذين امنوا اتقوا الله وامنوا برسوله يوتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم'),
(5104, 57, 29, 'لِئَلَّا يَعْلَمَ اَهْلُ الْكِتَابِ اَلَّا يَقْدِرُونَ عَلٰى شَيْءٍ مِنْ فَضْلِ اللّٰهِ وَاَنَّ الْفَضْلَ بِيَدِ اللّٰهِ يُؤْت۪يهِ مَنْ يَشَٓاءُۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Li ella ya\'leme ehlul kitabi ella yakdirune ala şey\'in min fadlillahi ve ennel fadle bi yedillahi yu\'tihi men yeşau, vallahu zul fadlil azim.', 'Kitap Ehli,  Allah\'ın lütfundan hiçbir şeye güçlerinin yetmeyeceğini; lütfun Allah\'ın elinde olduğunu ve onu hak edene vereceğini bilmezlik etmesin! Allah,  Büyük Lütuf Sahibi\'dir.', 'ليلا يعلم اهل الكتب الا يقدرون علي شي من فضل الله وان الفضل بيد الله يوتيه من يشا والله ذو الفضل العظيم'),
(5105, 58, 1, 'قَدْ سَمِعَ اللّٰهُ قَوْلَ الَّت۪ي تُجَادِلُكَ ف۪ي زَوْجِهَا وَتَشْتَك۪ٓي اِلَى اللّٰهِۗ وَاللّٰهُ يَسْمَعُ تَحَاوُرَكُمَاۜ اِنَّ اللّٰهَ سَم۪يعٌ بَص۪يرٌ', 'Kad semiallahu kavlelleti tucadiluke fi zevciha ve teşteki ilallahi vallahu yesmeu tehavurekuma, innellahe semi\'un basir.', 'Kocası hakkında seninle tartışan ve şikayette bulunan kadının sözünü Allah kesinlikle işitmiştir. Ve Allah,  konuşmalarınızı işitir. Kuşkusuz ki Allah,  Her Şeyi Duyan,  Her Şeyi Gören\'dir.', 'قد سمع الله قول التي تجدلك في زوجها وتشتكي الي الله والله يسمع تحاوركما ان الله سميع بصير'),
(5106, 58, 2, 'اَلَّذ۪ينَ يُظَاهِرُونَ مِنْكُمْ مِنْ نِسَٓائِهِمْ مَا هُنَّ اُمَّهَاتِهِمْۜ اِنْ اُمَّهَاتُهُمْ اِلَّا الّٰٓئ۪ وَلَدْنَهُمْۜ وَاِنَّهُمْ لَيَقُولُونَ مُنْكَراً مِنَ الْقَوْلِ وَزُوراًۜ وَاِنَّ اللّٰهَ لَعَفُوٌّ غَفُورٌ', 'Ellezine yuzahirune minkum min nisaihim ma hunne ummehatihim, in ummehatuhum illellai velednehum, ve innehum le yekulune munkeren minel kavli ve zura, ve innellahe le afuvvun gafur.', 'Sizden hanımlarına zihar[1] yapanlar bilsinler ki,  hanımları anneleri değildir. Anneleri yalnızca kendilerini doğuranlardır. Doğrusu onlar,  sözün çirkin ve asılsız olanını söylüyorlar. Kuşkusuz Allah,  Çok Affedici\'dir,  Çok Bağışlayıcı\'dır.', 'الذين يظهرون منكم من نسايهم ما هن امهتهم ان امهتهم الا الي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور'),
(5107, 58, 3, 'وَالَّذ۪ينَ يُظَاهِرُونَ مِنْ نِسَٓائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَـتَحْر۪يرُ رَقَـبَةٍ مِنْ قَبْلِ اَنْ يَتَمَٓاسَّاۜ ذٰلِكُمْ تُوعَظُونَ بِه۪ۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'Vellezine yuzahirune min nisaihim summe yeudune li ma kalu fe tahriru rekabetin min kabli en yetemassa, zalikum tuazune bih, vallahu bi ma ta\'melune habir.', 'Hanımlarına zihar yapıp sonra da kararlarından dönenlerin,  ilişkiye girmeden önce bir rekabeyi[1] özgürlüğüne kavuşturması gerekir. İşte size,  yapmanız gereken öğütleniyor. Allah,  yaptığınız her şeyden haberdardır.', 'والذين يظهرون من نسايهم ثم يعودون لما قالوا فتحرير رقبة من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير'),
(5108, 58, 4, 'فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِنْ قَبْلِ اَنْ يَتَمَٓاسَّاۚ فَمَنْ لَمْ يَسْتَطِعْ فَاِطْعَامُ سِتّ۪ينَ مِسْك۪يناًۜ ذٰلِكَ لِتُؤْمِنُوا بِاللّٰهِ وَرَسُولِه۪ۜ وَتِلْكَ حُدُودُ اللّٰهِۜ وَلِلْكَافِر۪ينَ عَذَابٌ اَل۪يمٌ', 'Fe men lem yecid fe siyamu şehreyni mutetabiayni min kabli en yetemassa, fe men lem yestetı\' fe ıt\'amu sittine miskina, zalike li tu\'minu billahi ve resulih, ve tilke hududullah, ve lil kafirine azabun elim.', 'Kim bulamazsa[1],  ilişkiye girmeden önce,  aralıksız olarak iki ay oruç tutmalıdır. Oruç tutmaya gücü yetmeyenler,  altmış yoksulu doyurmalıdır. Allah\'a ve Resul\'üne inanmanızın gereği olarak böyle yapın. Bunlar,  Allah\'ın sınırlarıdır. Kafirler için çok acıklı bir azap vardır.', 'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتومنوا بالله ورسوله وتلك حدود الله وللكفرين عذاب اليم'),
(5109, 58, 5, 'اِنَّ الَّذ۪ينَ يُحَٓادُّونَ اللّٰهَ وَرَسُولَهُ كُبِتُوا كَمَا كُبِتَ الَّذ۪ينَ مِنْ قَبْلِهِمْ وَقَدْ اَنْزَلْـنَٓا اٰيَاتٍ بَيِّنَاتٍۜ وَلِلْكَافِر۪ينَ عَذَابٌ مُه۪ينٌۚ', 'İnnelleziyne yuhadunellahe ve resulehu kubitu kema kubitellezine min kablihim ve kad enzelna ayatin beyyinat, ve lil kafirine azabun muhin.', 'Kanıt içeren açıklayıcı ayetler indirmiş olduğumuz halde,  Allah\'a ve Resul\'üne muhalefet edenler,  kendilerinden öncekilerin alçaltıldığı gibi alçaltılacaklardır. Kafirler[1] için alçaltıcı bir azap vardır.', 'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايت بينت وللكفرين عذاب مهين'),
(5110, 58, 6, 'يَوْمَ يَبْعَثُهُمُ اللّٰهُ جَم۪يعاً فَيُنَبِّئُهُمْ بِمَا عَمِلُواۜ  اَحْصٰيهُ اللّٰهُ وَنَسُوهُۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌ۟', 'Yevme yeb\'asu humullahu cemian fe yunebbiuhum bi ma amilu, ahsahullahu ve nesuh, vallahu ala kulli şey\'in şehid.', 'Allah,  onları dirilteceği gün,  kendilerine yaptıklarını haber verecektir. Allah,  onların unuttuklarını tek tek sayacak. Allah,  Her Şeye Tanıktır.', 'يوم يبعثهم الله جميعا فينبيهم بما عملوا احصيه الله ونسوه والله علي كل شي شهيد'),
(5111, 58, 7, 'اَلَمْ تَرَ اَنَّ اللّٰهَ يَعْلَمُ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۜ مَا يَكُونُ مِنْ نَجْوٰى ثَلٰثَةٍ اِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ اِلَّا هُوَ سَادِسُهُمْ وَلَٓا اَدْنٰى مِنْ ذٰلِكَ وَلَٓا اَكْثَرَ اِلَّا هُوَ مَعَهُمْ اَيْنَ مَا كَانُواۚ ثُمَّ يُنَبِّئُهُمْ بِمَا عَمِلُوا يَوْمَ الْقِيٰمَةِۜ اِنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'E lem tere ennellahe ya\'lemu ma fis semavati ve ma fil ard, ma yekunu min necva selasetin illa huve rabiuhum ve la hamsetin illa huve sadisuhum ve la edna min zalike ve la eksere illa huve me\'ahum eyne ma kanu, summe yunebbiuhum bi ma amilu yevmel kıyameh, innellahe bi kulli şey\'in alim.', 'Allah\'ın gökte ve yerde olan her şeyi bildiğinden haberin yok mu? Üç kişinin gizli konuştuğu yerde dördüncüleri kesinlikle O\'dur. Beş kişinin,  O altıncısıdır. Bundan az veya çok olsunlar ve nerede olurlarsa olsunlar O,  kesinlikle onlarla beraberdir. Sonra Kıyamet Günü,  yaptıkları şeyleri onlara haber verecektir. Kuşkusuz Allah,  Her Şeyi En İyi Bilen\'dir.', 'الم تر ان الله يعلم ما في السموت وما في الارض ما يكون من نجوي ثلثة الا هو رابعهم ولا خمسة الا هو سادسهم ولا ادني من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبيهم بما عملوا يوم القيمة ان الله بكل شي عليم'),
(5112, 58, 8, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ نُهُوا عَنِ النَّجْوٰى ثُمَّ يَعُودُونَ لِمَا نُهُوا عَنْهُ وَيَتَنَاجَوْنَ بِالْاِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِۘ وَاِذَا جَٓاؤُ۫كَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللّٰهُۙ وَيَقُولُونَ ف۪ٓي اَنْفُسِهِمْ لَوْلَا يُعَذِّبُنَا اللّٰهُ بِمَا نَقُولُۜ حَسْبُهُمْ جَهَنَّمُۚ يَصْلَوْنَهَاۚ فَبِئْسَ الْمَص۪يرُ', 'E lem tere ilellezine nuhu aninnecva summe yeudune li ma nuhu anhu ve yetenacevne bil ismi vel udvani ve ma\'siyetir resul, ve iza cauke hayyevke bi ma lem yuhayyike bihillahu, ve yekulune fi enfusihim lev la yuazzibunallahu bi ma nekul, hasbuhum cehennem, yaslevneha, febi\'sel masir.', 'Gizlilik içinde konuşmaktan[1] yasaklandıkları halde,  bu yasağa uymayarak günah,  düşmanlık ve Resul\'e karşı gelmek amacıyla gizlilik içinde bir araya gelenlerden haberin var mı? Sana geldikleri zaman,  Allah\'ın seni selamlamadığı şeyle seni selamlarlar.[2] Kendi aralarında da: \"Söylediğimiz şeylerden dolayı Allah bize azap etse ya!\"[3] diyorlar. Onlara Cehennem yeter. Ona yaslanacaklar. Orası ne kötü varış yeridir.', 'الم تر الي الذين نهوا عن النجوي ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت الرسول واذا جاوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبيس المصير'),
(5113, 58, 9, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا تَنَاجَيْتُمْ فَلَا تَتَنَاجَوْا بِالْاِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِ وَتَنَاجَوْا بِالْبِرِّ وَالتَّقْوٰىۜ وَاتَّقُوا اللّٰهَ الَّـذ۪ٓي اِلَيْهِ تُحْشَرُونَ', 'Ya eyyuhellezine amenu iza tenaceytum fe la tetenacev bil ismi vel udvani ve ma\'siyetir resuli ve tenacev bil birri vet takva, vettekullahellezi ileyhi tuhşerun.', 'Ey inananlar! Bir araya geldiğiniz zaman,  aranızda günah,  düşmanlık ve Resul\'e karşı gelmek amacıyla görüşme yapmayın. Görüşmelerinizi birr[1] ve takva[2] konusunda yapın. Huzurunda toplanacağınız Allah\'a karşı takva sahibi olun.', 'يايها الذين امنوا اذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت الرسول وتنجوا بالبر والتقوي واتقوا الله الذي اليه تحشرون'),
(5114, 58, 10, 'اِنَّمَا النَّجْوٰى مِنَ الشَّيْطَانِ لِيَحْزُنَ الَّذ۪ينَ اٰمَنُوا وَلَيْسَ بِضَٓارِّهِمْ شَيْـٔاً اِلَّا بِـاِذْنِ اللّٰهِۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'İnne men necva mineş şeytani li yahzunellezine amenu ve leyse bi darrihim şey\'en illa bi iznillah, ve alallahi fel yetevekkelil mu\'minun.', 'Kuşkusuz gizlilik içinde[1] yapılan görüşmeler,  inananları üzmek için şeytancadır[1]. Oysa şeytan,  Allah\'ın izni olmadıkça onlara bir sıkıntı verecek değildir. Öyleyse Mü\'minler Allah\'a tevekkül[3] etsinler.', 'انما النجوي من الشيطن ليحزن الذين امنوا وليس بضارهم شيا الا باذن الله وعلي الله فليتوكل المومنون'),
(5115, 58, 11, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا ق۪يلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ فَافْسَحُوا يَفْسَحِ اللّٰهُ لَكُمْۚ وَاِذَا ق۪يلَ انْشُزُوا فَانْشُزُوا يَرْفَعِ اللّٰهُ الَّذ۪ينَ اٰمَنُوا مِنْكُمْۙ وَالَّذ۪ينَ اُو۫تُوا الْعِلْمَ دَرَجَاتٍۜ وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'Ya eyyuhellezine amenu iza kile lekum tefessehu fil mecalisi fefsehu yefsehıllahu lekum, ve iza kilenşuzu fenşuzu yerfeillahullezine amenu minkum vellezine utul ilme derecat, vallahu bi ma ta\'melune habir.', 'Ey inananlar! Meclislerde size: \"Yer açın!\" denildiği zaman,  hemen yer açın. Allah da size yer açar. \"Dağılın!\" denildiği zaman da hemen dağılın! Allah,  sizden inananların ve ilim[1] verilmiş olanların derecelerini yükseltir. Allah,  yaptığınız Her Şeyden Haberdardır.', 'يايها الذين امنوا اذا قيل لكم تفسحوا في المجلس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجت والله بما تعملون خبير'),
(5116, 58, 12, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا نَاجَيْتُمُ الرَّسُولَ فَقَدِّمُوا بَيْنَ يَدَيْ نَجْوٰيكُمْ صَدَقَةًۜ ذٰلِكَ خَيْرٌ لَـكُمْ وَاَطْهَرُۜ فَاِنْ لَمْ تَجِدُوا فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Ya eyyuhellezine amenu iza naceytumur resule fe kaddimu beyne yedey necvakum sadakah, zalike hayrun lekum ve athar, fe in lem tecidu fe innellahe gafurun rahim.', 'Ey iman edenler! Resul\'le gizli[1] bir şey konuşacağınız zaman,  gizli bir şey konuşmanızdan önce sadaka verin.[2] Bu sizin için daha hayırlıdır ve daha temizdir. Ancak bir şey bulamazsanız,  bilin ki Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها الذين امنوا اذا نجيتم الرسول فقدموا بين يدي نجويكم صدقة ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم'),
(5117, 58, 13, 'ءَاَشْفَقْتُمْ اَنْ تُقَدِّمُوا بَيْنَ يَدَيْ نَجْوٰيكُمْ صَدَقَاتٍۜ فَاِذْ لَمْ تَفْعَلُوا وَتَابَ اللّٰهُ عَلَيْكُمْ فَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَط۪يعُوا اللّٰهَ وَرَسُولَهُۜ  وَاللّٰهُ خَب۪يرٌ بِمَا تَعْمَلُونَ۟', 'E eşfaktum en tukaddimu beyne yedey necvakum sadekat, fe iz lem tef\'alu ve taballahu aleykum, fe ekimus salate ve atuz zekate ve etiullahe ve resuleh, vallahu habirun bi ma ta\'melun.', 'Gizli bir şey konuşmadan önce sadaka vermek ağır geldi değil mi? Bunu yapamayınca Allah,  size tevbe etti.[1]. Artık salatı ikame edin,  zekatı yapın[2]; Allah\'a ve Resul\'üne itaat edin.[3] Allah yaptıklarınızdan haberdardır.', 'اشفقتم ان تقدموا بين يدي نجويكم صدقت فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلوة واتوا الزكوة واطيعوا الله ورسوله والله خبير بما تعملون'),
(5118, 58, 14, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ تَوَلَّوْا قَوْماً غَضِبَ اللّٰهُ عَلَيْهِمْۜ مَا هُمْ مِنْكُمْ وَلَا مِنْهُمْۙ وَيَحْلِفُونَ عَلَى الْـكَذِبِ وَهُمْ يَعْلَمُونَ', 'E lem tere ilellezine tevellev kavmen gadıballahu aleyhim, ma hum minkum ve la minhum ve yahlifune alel kezibi ve hum ya\'lemun.', 'Allah\'ın kendilerine gazap ettiği bir halka dönenleri[1] görüyor musun? Aslında onlar ne sizdendirler ne de onlardan. Bilerek yalan yere yemin ediyorlar.', 'الم تر الي الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون علي الكذب وهم يعلمون'),
(5119, 58, 15, 'اَعَدَّ اللّٰهُ لَهُمْ عَذَاباً شَد۪يداًۜ اِنَّهُمْ سَٓاءَ مَا كَانُوا يَعْمَلُونَ', 'E addallahu lehum azaben şedida, innehum sae ma kanu ya\'melun.', 'Allah,  onlara şiddetli bir azap hazırlamıştır. Onlar,  çok kötü şeyler yapıyorlar.', 'اعد الله لهم عذابا شديدا انهم سا ما كانوا يعملون'),
(5120, 58, 16, 'اِتَّخَذُٓوا اَيْمَانَهُمْ جُنَّةً فَصَدُّوا عَنْ سَب۪يلِ اللّٰهِ فَلَهُمْ عَذَابٌ مُه۪ينٌ', 'İttehazu eymanehum cunneten fe saddu an sebilillahi fe lehum azabun muhin.', 'Yeminlerini kullanarak insanları Allah\'ın yolundan çevirdiler. Artık onlar için alçaltıcı bir azap vardır.', 'اتخذوا ايمنهم جنة فصدوا عن سبيل الله فلهم عذاب مهين'),
(5121, 58, 17, 'لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَٓا اَوْلَادُهُمْ مِنَ اللّٰهِ شَيْـٔاًۜ اُو۬لٰٓئِكَ اَصْحَابُ النَّارِۚ هُمْ ف۪يهَا خَالِدُونَ', 'Len tugniye anhum emvaluhum ve la evladuhum min allahi şey\'a, ulaike ashabun nar, hum fiha halidun.', 'Onların malları ve evlatları,  Allah\'tan gelecek bir şeye karşı,  onlara asla yarar sağlamaz. İşte onlar,  ateşin halkıdırlar. Orada sürekli kalacak olanlardır.', 'لن تغني عنهم امولهم ولا اولدهم من الله شيا اوليك اصحب النار هم فيها خلدون'),
(5122, 58, 18, 'يَوْمَ يَبْعَثُهُمُ اللّٰهُ جَم۪يعاً فَيَحْلِفُونَ لَهُ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ اَنَّهُمْ عَلٰى شَيْءٍۜ  اَلَٓا اِنَّهُمْ هُمُ الْكَاذِبُونَ', 'Yevme yeb\'asuhumullahu cemian fe yahlifune lehu kema yahlifune lekum ve yahsebune ennehum ala şey\'in, e la innehum humul kazibun.', 'O gün Allah,  onların tamamını yeniden diriltecek. O zaman,  size yemin ettikleri gibi O\'na da yemin edecekler. Böylece bir şey elde edeceklerini sanacaklar. Dikkat edin! Onlar,  kesinlikle yalancıdırlar.', 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم علي شي الا انهم هم الكذبون'),
(5123, 58, 19, 'اِسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ فَاَنْسٰيهُمْ ذِكْرَ اللّٰهِۜ  اُو۬لٰٓئِكَ حِزْبُ الشَّيْطَانِۜ اَلَٓا اِنَّ حِزْبَ الشَّيْطَانِ هُمُ الْخَاسِرُونَ', 'İstahveze aleyhimuş şeytanu fe ensahum zikrallah, ulaike hizbuş şeytan, ela inne hizbeşşeytani humul hasirun.', 'Şeytan[1] onları kuşattı. Böylece Allah\'ın öğüdünü onlara unutturdu. Onlar,  şeytanın[1] taraftarlarıdır. Dikkat edin! Şeytanın taraftarları kesinlikle kaybedenlerdir.', 'استحوذ عليهم الشيطن فانسيهم ذكر الله اوليك حزب الشيطن الا ان حزب الشيطن هم الخسرون'),
(5124, 58, 20, 'اِنَّ الَّذ۪ينَ يُحَٓادُّونَ اللّٰهَ وَرَسُولَهُٓ  اُو۬لٰٓئِكَ فِي الْاَذَلّ۪ينَ', 'İnnellezine yuhaddunallahe ve resulehu ulaike fil ezellin.', 'Allah\'a ve O\'nun Resul\'üne karşı haddi aşanlar,  işte onlar zillet içindedirler.', 'ان الذين يحادون الله ورسوله اوليك في الاذلين'),
(5125, 58, 21, 'كَتَبَ اللّٰهُ لَاَغْلِبَنَّ اَنَا۬ وَرُسُل۪يۜ اِنَّ اللّٰهَ قَوِيٌّ عَز۪يزٌ', 'Keteballahu le aglibenne ene ve rusuli, innallahe kaviyyun aziz.', 'Allah: \"Ben ve Resul\'lerim kesinlikle galip geleceğiz.\" diye hükmetmiştir. Kuşkusuz Allah; Mutlak Güç Sahibi\'dir,  Mutlak Üstün Olan\'dır.', 'كتب الله لاغلبن انا ورسلي ان الله قوي عزيز'),
(5126, 58, 22, 'لَا تَجِدُ قَوْماً يُؤْمِنُونَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ يُوَٓادُّونَ مَنْ حَٓادَّ اللّٰهَ وَرَسُولَهُ وَلَوْ كَانُٓوا اٰبَٓاءَهُمْ اَوْ اَبْنَٓاءَهُمْ اَوْ اِخْوَانَهُمْ اَوْ عَش۪يرَتَهُمْۜ اُو۬لٰٓئِكَ كَتَبَ ف۪ي قُلُوبِهِمُ الْا۪يمَانَ وَاَيَّدَهُمْ بِرُوحٍ مِنْهُۜ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَاۜ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوا عَنْهُۜ اُو۬لٰٓئِكَ حِزْبُ اللّٰهِۜ اَلَٓا اِنَّ حِزْبَ اللّٰهِ هُمُ الْمُفْلِحُونَ', 'La tecidu kavmen yu\'munune billahi vel yevmil ahiri yuvaddune men haddallahe ve resulehu ve lev kanu abaehum ve ebnaehum ve ihvanehum ev aşiretehum, ulaike ketebe fi kulubihimul imane ve eyyedehum bi ruhin minh, ve yudhıluhum cennatin tecri min tahtihel enharu halidine fiha, radıyallahu anhum ve radu anh, ulaike hizbullah, e la inne hizbullahi humul muflihun.', 'Allah\'a ve Ahiret Günü\'ne iman eden bir halkın,  Allah\'a ve O\'nun Resul\'üne karşı haddi aşanlara karşı sevgi duyduklarına tanık olamazsın; isterse bunlar,  babaları,  çocukları,  kardeşleri veya akrabaları olsun. Onlar,  Allah\'ın kalplerine iman yazdığı ve kendilerini,  kendinden bir ruh[1] ile desteklediği kimselerdir. Allah,  onları içinden ırmaklar akan Cennetlere koyacaktır. Onlar,  orada sürekli kalacak olanlardır. Allah,  onlardan hoşnut oldu,  onlar da O\'ndan hoşnut oldular. İşte onlar,  Allah\'ın taraftarlarıdır. Dikkat edin! Doğrusu Allah\'ın taraftarları kurtuluşa erenlerdir.', 'لا تجد قوما يومنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباهم او ابناهم او اخونهم او عشيرتهم اوليك كتب في قلوبهم الايمن وايدهم بروح منه ويدخلهم جنت تجري من تحتها الانهر خلدين فيها رضي الله عنهم ورضوا عنه اوليك حزب الله الا ان حزب الله هم المفلحون'),
(5127, 59, 1, 'سَبَّحَ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۚ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Sebbeha lillahi ma fis semavati ve ma fil ard, ve huvel azizul hakim.', 'Göklerde ve yerde bulunanlar,  Allah\'ı tesbih etmektedir. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'سبح لله ما في السموت وما في الارض وهو العزيز الحكيم');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(5128, 59, 2, 'هُوَ الَّـذ۪ٓي اَخْرَجَ الَّذ۪ينَ كَفَرُوا مِنْ اَهْلِ الْكِتَابِ مِنْ دِيَارِهِمْ لِاَوَّلِ الْحَشْرِۜ مَا ظَنَنْتُمْ اَنْ يَخْرُجُوا وَظَنُّٓوا اَنَّهُمْ مَانِعَتُهُمْ حُصُونُهُمْ مِنَ اللّٰهِ فَاَتٰيهُمُ اللّٰهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا وَقَذَفَ ف۪ي قُلُوبِهِمُ الرُّعْبَ يُخْرِبُونَ بُيُوتَهُمْ بِاَيْد۪يهِمْ وَاَيْدِي الْمُؤْمِن۪ينَ فَاعْتَبِرُوا يَٓا اُو۬لِي الْاَبْصَارِ', 'Huvellezi ahrecellezine keferu min ehlil kitabi min diyarihim li evvelil haşr, ma zanentum en yahrucu ve zannu ennehum maniatuhum husunuhum minallahi fe etahumullahu min haysu lem yahtesibu ve kazefe fi kulubihimur ru\'be yuhribune buyutehum bi eydihim ve eydil mu\'minine fa\'tabiru ya ulil ebsar.', 'Kitap Ehli\'nden,  Kafirleri sürgün için yurtlarından çıkaran O\'dur. Siz,  onların yurtlarından çıkacaklarını sanmamıştınız. Ve onlar da kalelerinin,  kendilerini Allah\'tan[1] koruyacağına inandılar. Oysa Allah\'ın buyruğu onlara hesaba katmadıkları yerden geldi. Allah,  onların yüreklerine evlerinin kendi elleriyle ve inananların elleriyle harap edileceği korkusunu saldı. Ey basiret[2] sahipleri! Artık ibret alın.', 'هو الذي اخرج الذين كفروا من اهل الكتب من ديرهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتيهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المومنين فاعتبروا ياولي الابصر'),
(5129, 59, 3, 'وَلَوْلَٓا اَنْ كَتَبَ اللّٰهُ عَلَيْهِمُ الْجَلَٓاءَ لَعَذَّبَهُمْ فِي الدُّنْيَاۜ وَلَهُمْ فِي الْاٰخِرَةِ عَذَابُ النَّارِ', 'Ve lev la en keteballahu aleyhimul celae le azzebehum fid dunya, ve lehum fil ahıreti azabun nar.', 'Eğer Allah,  onlara sürgün takdirinde bulunmamış olsaydı,  kesinlikle dünyada azap verirdi. Onlara,  ahirette ateşin azabı vardır.', 'ولولا ان كتب الله عليهم الجلا لعذبهم في الدنيا ولهم في الاخرة عذاب النار'),
(5130, 59, 4, 'ذٰلِكَ بِاَنَّهُمْ شَٓاقُّوا اللّٰهَ وَرَسُولَهُۚ وَمَنْ يُشَٓاقِّ اللّٰهَ فَاِنَّ اللّٰهَ شَد۪يدُ الْعِقَابِ', 'Zalike bi ennehum şa akkullahe ve resuleh, ve men yuşa akkıllahe fe innallahe şedidul ikab.', 'İşte bu,  onların Allah\'a ve O\'nun Resul\'üne muhalefet etmeleri nedeniyledir. Kim Allah\'a muhalefet ederse bilsin ki Allah,  cezası çok şiddetli olandır.', 'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب'),
(5131, 59, 5, 'مَا قَطَعْتُمْ مِنْ ل۪ينَةٍ اَوْ تَرَكْتُمُوهَا قَٓائِمَةً عَلٰٓى اُصُولِهَا فَبِاِذْنِ اللّٰهِ وَلِيُخْزِيَ الْفَاسِق۪ينَ', 'Ma kata\'tum min linetin ev terektumuha kaimeten ala usuliha fe bi iznillahi ve li yuhziyel fasikin.', 'Taze hurmadan kestikleriniz veya kesmedikleriniz de ancak Allah\'ın izniyledir.[1] Bu,  fasıkların perişan olmaları içindir.', 'ما قطعتم من لينة او تركتموها قايمة علي اصولها فباذن الله وليخزي الفسقين'),
(5132, 59, 6, 'وَمَٓا اَفَٓاءَ اللّٰهُ عَلٰى رَسُولِه۪ مِنْهُمْ فَمَٓا اَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلٰكِنَّ اللّٰهَ يُسَلِّطُ رُسُلَهُ عَلٰى مَنْ يَشَٓاءُۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ve ma efa allahu ala resulihi minhum fe ma evceftum aleyhi min haylin ve la rikabin ve lakinnallahe yusallitu rusulehu ala men yeşau, vallahu ala kulli şey\'in kadir.', 'Allah\'ın Resul\'üne verdiği fey\'e[1] gelince,  siz onlar için ne at koşturdunuz ne de deve![2] Fakat Allah; Resul\'üne,  dilediği kimselere karşı üstünlük verir. Allah,  Her Şeye Güç Yetiren\'dir.', 'وما افا الله علي رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله علي من يشا والله علي كل شي قدير'),
(5133, 59, 7, 'مَٓا اَفَٓاءَ اللّٰهُ عَلٰى رَسُولِه۪ مِنْ اَهْلِ الْقُرٰى فَلِلّٰهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاك۪ينِ وَابْنِ السَّب۪يلِۙ  كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْاَغْنِيَٓاءِ مِنْكُمْۜ وَمَٓا اٰتٰيكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهٰيكُمْ عَنْهُ فَانْتَهُواۚ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ شَد۪يدُ الْعِقَابِۢ', 'Ma efa allahu ala resulihi min ehlil kura fe lillahi ve lir resuli ve lizil kurba vel yetama vel mesakini vebnis sebili key la yekune duleten beynel agniyai minkum, ve ma atakumur resulu fe huzuhu ve ma nehakum anhu fentehu, vettekullah, innallahe şedidul ikab.', 'Allah\'ın,  beldeler halkından,  Resul\'üne verdiği feyler;[1] aranızda zenginliğe neden olan,  elden ele dolaşan bir zenginlik olmasın diye; Allah,  Resul,  yakınlık sahipleri[2],  yetimler,  miskinler ve yol oğlu[3] içindir. Resul size ne verdiyse onu alın. Sizi neden alıkoyduysa ondan vazgeçin.[4] Allah\'a karşı takva sahibi olun. Kuşkusuz Allah,  Cezalandırması Çok Şiddetli Olan\'dır.', 'ما افا الله علي رسوله من اهل القري فلله وللرسول ولذي القربي واليتمي والمسكين وابن السبيل كي لا يكون دولة بين الاغنيا منكم وما اتيكم الرسول فخذوه وما نهيكم عنه فانتهوا واتقوا الله ان الله شديد العقاب'),
(5134, 59, 8, 'لِلْفُقَـرَٓاءِ الْمُهَاجِر۪ينَ الَّذ۪ينَ اُخْرِجُوا مِنْ دِيَارِهِمْ وَاَمْوَالِهِمْ يَبْتَغُونَ فَضْلاً مِنَ اللّٰهِ وَرِضْوَاناً وَيَنْصُرُونَ اللّٰهَ وَرَسُولَهُۜ  اُو۬لٰٓئِكَ هُمُ الصَّادِقُونَۚ', 'Lil fukarail muhacirinellezine uhricu min diyarihim ve emvalihim yebtegune fadlen minallahi ve rıdvanen ve yensurunallahe ve resuleh, ulaike humus sadikun.', 'Bu mallarda; Allah\'ın lütfu ve rızasını kazanmak arzusuyla,  Allah\'a[1] ve Resul\'üne yardım ettikleri için yurtlarından çıkarılan ve malları ellerinden alınan,  hicret etmiş olan yoksulların da hakkı vardır. Çünkü onlar özü sözü bir olanlardır.', 'للفقرا المهجرين الذين اخرجوا من ديرهم وامولهم يبتغون فضلا من الله ورضونا وينصرون الله ورسوله اوليك هم الصدقون'),
(5135, 59, 9, 'وَالَّذ۪ينَ تَبَوَّؤُ الدَّارَ وَالْا۪يمَانَ مِنْ قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ اِلَيْهِمْ وَلَا يَجِدُونَ ف۪ي صُدُورِهِمْ حَاجَةً مِمَّٓا اُو۫تُوا وَيُؤْثِرُونَ عَلٰٓى اَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌۜ وَمَنْ يُوقَ شُحَّ نَفْسِه۪ فَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَۚ', 'Vellezine tebevveud dare vel imane min kablihim yuhıbbune men hacere ileyhim ve la yecidune fi sudurihim haceten mimma utu ve yu\'sirune ala enfusihim ve lev kane bihim hasasah, ve men yuka şuhha nefsihi fe ulaike humul muflihun.', 'Onlardan önce Medine\'yi yurt edinen ve kalplerine iman yerleşmiş olanlar,  kendilerine hicret edenleri severler. Onlara verilen ganimetlerden dolayı,  -kendileri muhtaç olsa bile- kalplerinde bir kaygı,  kıskançlık duymazlar. Onları kendilerine tercih ederler. Kim,  kendisini cimrilikten korursa,  işte onlar kurtuluşa erenlerdir.', 'والذين تبو الدار والايمن من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجة مما اوتوا ويوثرون علي انفسهم ولو كان بهم خصاصة ومن يوق شح نفسه فاوليك هم المفلحون'),
(5136, 59, 10, 'وَالَّذ۪ينَ جَٓاؤُ۫ مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّـنَا اغْفِرْ لَنَا وَلِاِخْوَانِنَا الَّذ۪ينَ سَبَقُونَا بِالْا۪يمَانِ وَلَا تَجْعَلْ ف۪ي قُلُوبِنَا غِلاًّ لِلَّذ۪ينَ اٰمَنُوا رَبَّـنَٓا اِنَّكَ رَؤُ۫فٌ رَح۪يمٌ۟', 'Vellezine cau min ba\'dihim yekulune rabbenagfir lena ve li ihvaninellezine sebekuna bil imani ve la tec\'al fi kulubina gıllen lillezine amenu rabbena inneke raufun rahim.', 'Onlardan sonra gelenler: \"Rabb\'imiz! Bizi ve bizden önce iman ile göç etmiş kardeşlerimizi bağışla. Kalplerimizde iman edenlere karşı kin bırakma. Rabb\'imiz! Kuşkusuz Sen Çok Şefkatli,  Rahmeti Kesintisizsin.\" derler.', 'والذين جاو من بعدهم يقولون ربنا اغفر لنا ولاخوننا الذين سبقونا بالايمن ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك روف رحيم'),
(5137, 59, 11, 'اَلَمْ تَرَ اِلَى الَّذ۪ينَ نَافَقُوا يَقُولُونَ لِاِخْوَانِهِمُ الَّذ۪ينَ كَفَرُوا مِنْ اَهْلِ الْكِتَابِ لَئِنْ اُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُط۪يعُ ف۪يكُمْ اَحَداً اَبَداًۚ وَاِنْ قُوتِلْتُمْ لَنَنْصُرَنَّكُمْۜ وَاللّٰهُ يَشْهَدُ اِنَّهُمْ لَكَاذِبُونَ', 'E lem tere ilellezine nafeku yekulune li ihvanihimullezie keferu min ehlil kitabi le in uhrictum le nahrucenne me\'akum ve la nutiu fi kum ehaden ebeden ve in kutiltum le nensurennekum, vallahu yeşhedu innehum le kazibun.', 'Nifak[1] çıkaranları görmüyor musun? Kitap Ehli\'nden Kafir[2] yoldaşlarına: \"Eğer siz yurdunuzdan çıkarılacak olursanız,  kesinlikle biz de sizinle birlikte çıkarız. Sizin aleyhinize olan konularda kimseye boyun eğmeyiz. Eğer sizinle savaşırlarsa,  kesinlikle size yardım ederiz.\" derler. Allah,  tanıklık eder ki onlar gerçekten yalancıdırlar.', 'الم تر الي الذين نافقوا يقولون لاخونهم الذين كفروا من اهل الكتب لين اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكذبون'),
(5138, 59, 12, 'لَئِنْ اُخْرِجُوا لَا يَخْرُجُونَ مَعَهُمْۚ وَلَئِنْ قُوتِلُوا لَا يَنْصُرُونَهُمْۚ وَلَئِنْ نَصَرُوهُمْ لَيُوَلُّنَّ الْاَدْبَارَ۠  ثُمَّ لَا يُنْصَرُونَ', 'Le in uhricu la yahrucune me\'ahum ve le in kutılu la yensurunehum ve le in nesaruhum le yuvellunnel edbar, summe la yunsarun.', 'Eğer yurtlarından çıkarılsalar,  münafıklar kesinlikle onlarla birlikte çıkmazlar. Eğer savaşırlarsa,  kesinlikle onlara yardım da etmezler. Yardım etseler bile,  sıkışınca savaştan kaçarlar. Sonra onlara güvenenler de yardımsız kalırlar.', 'لين اخرجوا لا يخرجون معهم ولين قوتلوا لا ينصرونهم ولين نصروهم ليولن الادبار ثم لا ينصرون'),
(5139, 59, 13, 'لَاَنْتُمْ اَشَدُّ رَهْبَةً ف۪ي صُدُورِهِمْ مِنَ اللّٰهِۜ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَا يَفْقَهُونَ', 'Le entum eşeddu rehbeten fi sudurihim minallahi, zalike bi ennehum kavmun la yefkahun.', 'Onların yüreklerinde,  Allah\'a olan korkudan daha fazla size olan korku vardır. Bu onların,  gerçeği kavramayan bir halk olmalarındandır.', 'لانتم اشد رهبة في صدورهم من الله ذلك بانهم قوم لا يفقهون'),
(5140, 59, 14, 'لَا يُقَاتِلُونَكُمْ جَم۪يعاً اِلَّا ف۪ي قُرًى مُحَصَّنَةٍ اَوْ مِنْ وَرَٓاءِ جُدُرٍۜ بَأْسُهُمْ بَيْنَهُمْ شَد۪يدٌۜ تَحْسَبُهُمْ جَم۪يعاً وَقُلُوبُهُمْ شَتّٰىۜ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَا يَعْقِلُونَۚ', 'La yukatilunekum cemian illa fi kuren muhassanetin ev min verai cudur, be\'suhum beynehum şedid, tahsebuhum cemian ve kulubuhum şetta, zalike bi ennehum kavmun la ya\'kılun.', 'Onlar,  korunaklı şehirler içinde veya surlar arkasında olmadıkça,  sizinle,  toplu olarak karşı karşıya gelerek savaşmazlar. Kaldı ki kendi aralarında da derin ayrılıklar içindedirler. Sen,  onların birlik olduklarını sanırsın,  oysaki kalben farklı farklıdırlar. Bu,  onların akıllarını doğru kullanmayan bir halk olmaları nedeniyledir.', 'لا يقتلونكم جميعا الا في قري محصنة او من ورا جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتي ذلك بانهم قوم لا يعقلون'),
(5141, 59, 15, 'كَمَثَلِ الَّذ۪ينَ مِنْ قَبْلِهِمْ قَر۪يباً ذَاقُوا وَبَالَ اَمْرِهِمْۚ وَلَهُمْ عَذَابٌ اَل۪يمٌۚ', 'Kemeselillezine min kablihim kariben zaku ve bale emrihim ve lehum azabun elim.', 'Onların durumu,  kendilerinden yakın zaman öncesinde yaptıkları işlerin sonucunu tatmış olanların durumu gibidir. Ve onlar için acı bir azap vardır.', 'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم'),
(5142, 59, 16, 'كَمَثَلِ الشَّيْطَانِ اِذْ قَالَ لِلْاِنْسَانِ اكْفُرْۚ فَلَمَّا كَفَرَ قَالَ اِنّ۪ي بَر۪ٓيءٌ مِنْكَ اِنّ۪ٓي اَخَافُ اللّٰهَ رَبَّ الْعَالَم۪ينَ', 'Ke meseliş şeytani iz kale lil insanikfur, fe lemma kefere kale inni beriun minke inni ehafullahe rabbel alemin.', 'Onların[1] durumu tıpkı şeytanın[2] durumu gibidir.[3] İnsana: \"Kafir ol.\" der. Ne var ki insan kafir olunca da: \"Kesinlikle ben senden uzağım,  ben Âlemlerin Rabb\'i olan Allah\'tan korkarım.\" der.', 'كمثل الشيطن اذ قال للانسن اكفر فلما كفر قال اني بري منك اني اخاف الله رب العلمين'),
(5143, 59, 17, 'فَكَانَ عَاقِبَتَهُمَٓا اَنَّهُمَا فِي النَّارِ خَالِدَيْنِ ف۪يهَاۜ وَذٰلِكَ جَزٰٓؤُا الظَّالِم۪ينَ۟', 'Fe kane akıbetehuma ennehuma fin nari halideyni fiha, ve zalike cezauz zalimin.', 'Her ikisinin de sonu,  ateşin içinde sonsuza dek kalmaktır. İşte zalimlerin cezası budur.', 'فكان عقبتهما انهما في النار خلدين فيها وذلك جزو الظلمين'),
(5144, 59, 18, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا اتَّقُوا اللّٰهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍۚ وَاتَّقُوا اللّٰهَۜ اِنَّ اللّٰهَ خَب۪يرٌ بِمَا تَعْمَلُونَ', 'Ya eyyuhellezine amenuttekullahe vel tenzur nefsun ma kad demet ligad, vettekullah, innallahe habirun bi ma ta\'melun.', 'Ey inananlar! Allah\'a karşı takva sahibi olun! Herkes yarın için ne hazırladığına baksın! Allah\'a karşı takva sahibi olun. Kuşkusuz ki Allah,  yaptıklarınızdan haberdardır.', 'يايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون'),
(5145, 59, 19, 'وَلَا تَكُونُوا كَالَّذ۪ينَ نَسُوا اللّٰهَ فَاَنْسٰيهُمْ اَنْفُسَهُمْۜ اُو۬لٰٓئِكَ هُمُ الْفَاسِقُونَ', 'Ve la tekunu kellezine nesullahe fe ensahum enfusehum, ulaike humul fasikun.', 'Allah\'ı umursamayan,  böylece kendileri ile baş başa kalan kimseler gibi olmayın! İşte onlar fasıklardır.[1]', 'ولا تكونوا كالذين نسوا الله فانسيهم انفسهم اوليك هم الفسقون'),
(5146, 59, 20, 'لَا يَسْتَـو۪ٓي اَصْحَابُ النَّارِ وَاَصْحَابُ الْجَنَّةِۜ اَصْحَابُ الْجَنَّةِ هُمُ الْـفَٓائِزُونَ', 'La yestevi ashabun nari ve ashabul cenneh, ashabul cenneti humul faizun.', 'Cehennemlikler ile Cennetlikler bir değildir. Cennetlikler,  kurtuluşa eren kimselerdir.', 'لا يستوي اصحب النار واصحب الجنة اصحب الجنة هم الفايزون'),
(5147, 59, 21, 'لَوْ اَنْزَلْنَا هٰذَا الْقُرْاٰنَ عَلٰى جَبَلٍ لَرَاَيْتَهُ خَاشِعاً مُتَصَدِّعاً مِنْ خَشْيَةِ اللّٰهِۜ وَتِلْكَ الْاَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'Lev enzelna hazel kur\'ane ala cebelin le reeytehu haşian mutesaddian min haşyetillah, ve tilkel emsalu nadribuha lin nasi leallehum yetefekkerun.', 'Eğer Biz,  bu Kur\'an\'ı dağa indirseydik,  onu; huşu[1] duyarak,  Allah\'a olan huşudan parça parça olmuş görürdün.[2] Bu örnekleri insanlar için veriyoruz ki belki düşünüp gerçeği kavrarlar.', 'لو انزلنا هذا القران علي جبل لرايته خشعا متصدعا من خشية الله وتلك الامثل نضربها للناس لعلهم يتفكرون'),
(5148, 59, 22, 'هُوَ اللّٰهُ الَّذ۪ي لَٓا اِلٰهَ اِلَّا هُوَۚ عَالِمُ الْغَيْبِ وَالشَّهَادَةِۚ هُوَ الرَّحْمٰنُ الرَّح۪يمُ', 'Huvallahullezi la ilahe illa huve, alimul gaybi veş şehadeh, huver rahmanur rahim.', 'O,  kendisinden başka ilah olmayan Allah\'tır. Görünmeyeni ve görüneni bilendir. O,  Rahmeti Bol ve Kesintisiz olandır.', 'هو الله الذي لا اله الا هو علم الغيب والشهدة هو الرحمن الرحيم'),
(5149, 59, 23, 'هُوَ اللّٰهُ الَّذ۪ي لَٓا اِلٰهَ اِلَّا هُوَۚ اَلْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَز۪يزُ الْجَبَّارُ الْمُتَكَبِّرُۜ سُبْحَانَ اللّٰهِ عَمَّا يُشْرِكُونَ', 'Huvallahullezi la ilahe illa huve, elmelikul kuddusus selamul mu\'minul muheyminul azizul cebbarul mutekebbir, subhanallahi amma yuşrikun.', 'O Allah ki: O\'ndan başka ilah yoktur; Melik\'tir[1],  Kuddus\'tür[2],  Selam\'dır[3],  Mü\'min\'dir[4],  Muheymin\'dir[5],  Aziz\'dir[6],  Cebbar\'dır[7],  Mutekebbir\'dir.[8] Allah,  onların ortak koştukları şeylerden münezzehtir.[9]', 'هو الله الذي لا اله الا هو الملك القدوس السلم المومن المهيمن العزيز الجبار المتكبر سبحن الله عما يشركون'),
(5150, 59, 24, 'هُوَ اللّٰهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ لَهُ الْاَسْمَٓاءُ الْحُسْنٰىۜ يُسَبِّـحُ لَهُ مَا فِي السَّمٰوَاتِ وَالْاَرْضِۚ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Huvallahul halikul bariul musavviru lehul esmaul husna, yusebbihu lehu ma fis semavati vel ard ve huvel azizul hakim.', 'O Allah ki: Halik\'dır[1],  Bari\'dir[2],  Musavvir\'dir.[3] En iyi nitelikler O\'na aittir. Göklerde ve yeryüzünde olanlar,  O\'nu tesbih ederler. O,  Mutlak Üstün Olan\'dır,  En İyi Yasa Koyan\'dır.', 'هو الله الخلق الباري المصور له الاسما الحسني يسبح له ما في السموت والارض وهو العزيز الحكيم'),
(5151, 60, 1, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَّخِذُوا عَدُوّ۪ي وَعَدُوَّكُمْ اَوْلِيَٓاءَ تُلْقُونَ اِلَيْهِمْ بِالْمَوَدَّةِ وَقَدْ كَفَرُوا بِمَا جَٓاءَكُمْ مِنَ الْحَقِّۚ يُخْرِجُونَ الرَّسُولَ وَاِيَّاكُمْ اَنْ تُؤْمِنُوا بِاللّٰهِ رَبِّكُمْۜ اِنْ كُنْتُمْ خَرَجْتُمْ جِهَاداً ف۪ي سَب۪يل۪ي وَابْتِغَٓاءَ مَرْضَات۪ي تُسِرُّونَ اِلَيْهِمْ بِالْمَوَدَّةِۗ وَاَنَا۬ اَعْلَمُ بِمَٓا اَخْفَيْتُمْ وَمَٓا اَعْلَنْتُمْۜ وَمَنْ يَفْعَلْهُ مِنْكُمْ فَقَدْ ضَلَّ سَوَٓاءَ السَّب۪يلِ', 'Ya eyyuhellezine amenu la tettehızu aduvvi ve aduvvekum evliyae, tulkune ileyhim bil meveddeti ve kad keferu bi ma caekum minel hakk, yuhricuner resule ve iyyakum en tu\'minu billahi rabbikum, in kuntum harectum cihaden fi sebili vebtigae merdati tusirrune ileyhim bil meveddeti ve ene a\'lemu bi ma ahfeytum ve ma a\'lentum, ve men yef\'alhu minkum fe kad dalle sevaes sebil.', 'Ey inananlar! Benim ve sizin düşmanlarınızı evliya[1] edinmeyin. Onlar,  Hakk\'tan size geleni inkar ettikleri halde onlarla yakınlık kuruyorsunuz. Oysaki Rabb\'iniz olan Allah\'a inanmanızdan dolayı Resul\'ü ve sizi yurdunuzdan çıkardılar. Eğer Benim yolumda mücadele etmek ve rızamı kazanmak için yola çıktıysanız,  niçin onlara yakınlık kurup sır veriyorsunuz? Ben,  sizin gizli ve açık bütün yaptıklarınızı bilirim. Sizden kim bunu yaparsa o,  kesinlikle yolun ortasından sapmış olur.', 'يايها الذين امنوا لا تتخذوا عدوي وعدوكم اوليا تلقون اليهم بالمودة وقد كفروا بما جاكم من الحق يخرجون الرسول واياكم ان تومنوا بالله ربكم ان كنتم خرجتم جهدا في سبيلي وابتغا مرضاتي تسرون اليهم بالمودة وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سوا السبيل'),
(5152, 60, 2, 'اِنْ يَثْقَفُوكُمْ يَكُونُوا لَكُمْ اَعْدَٓاءً وَيَبْسُطُٓوا اِلَيْكُمْ اَيْدِيَهُمْ وَاَلْسِنَتَهُمْ بِالسُّٓوءِ وَوَدُّوا لَوْ تَكْفُرُونَۜ', 'İn yeskafukum yekunu lekum a\'daen ve yebsutu ileykum eydiyehum ve elsinetehum bis sui ve veddu lev tekfurun.', 'Eğer ellerine fırsat geçirirlerse size düşman kesilirler. Elleriyle ve dilleriyle size her türlü kötülüğü yaparlar. Tekrar küfre dönmenizi temenni ederler.', 'ان يثقفوكم يكونوا لكم اعدا ويبسطوا اليكم ايديهم والسنتهم بالسو وودوا لو تكفرون'),
(5153, 60, 3, 'لَنْ تَنْفَعَكُمْ اَرْحَامُكُمْ وَلَٓا اَوْلَادُكُمْۚۛ يَوْمَ الْقِيٰمَةِۚۛ يَفْصِلُ بَيْنَكُمْۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Len tenfeakum erhamukum ve la evladukum, yevmel kıyameh yefsılu beynekum, vallahu bi ma ta\'melune basir.', 'Kıyamet Günü akrabalarınız ve çocuklarınız size asla fayda sağlamazlar. Sizin aranızı ayıracaktır. Ve Allah,  yaptıklarınızı En İyi Gören\'dir.', 'لن تنفعكم ارحامكم ولا اولدكم يوم القيمة يفصل بينكم والله بما تعملون بصير'),
(5154, 60, 4, 'قَدْ كَانَتْ لَكُمْ اُسْوَةٌ حَسَنَةٌ ف۪ٓي اِبْرٰه۪يمَ وَالَّذ۪ينَ مَعَهُۚ اِذْ قَالُوا لِقَوْمِهِمْ اِنَّا بُرَءٰٓؤُ۬ا مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللّٰهِۘ   كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَٓاءُ اَبَداً حَتّٰى تُؤْمِنُوا بِاللّٰهِ وَحْدَهُٓ اِلَّا قَوْلَ اِبْرٰه۪يمَ لِاَب۪يهِ لَاَسْتَغْفِرَنَّ لَكَ وَمَٓا اَمْلِكُ لَكَ مِنَ اللّٰهِ مِنْ شَيْءٍۜ رَبَّـنَا عَلَيْكَ تَوَكَّلْنَا وَاِلَيْكَ اَنَبْنَا وَاِلَيْكَ الْمَص۪يرُ', 'Kad kanet lekum usvetun hasenetun fi ibrahime vellezine meah, iz kalu li kavmihim inna bureau minkum ve mimma ta\'budune min dunillahi keferna bikum, ve bedee beynena ve beynekumul adavetu vel bagdau ebeden hatta tu\'minu billahi vahdehu, illa kavle ibrahime li ebihi le estagfirenne leke ve ma emliku leke minallahi min şey\'İn, rabbena aleyke tevekkelna ve ileyke enebna ve ileykel masir.', 'Ancak İbrahim\'in babasına: \"Allah\'tan olacak olana gücüm yetmez,  fakat senin için bağışlanma dileyeceğim\" sözü hariç[1]. İbrahim\'de ve onunla birlikte bulunanlarda sizin için iyi bir örnek vardır. Onlar halklarına şöyle demişlerdi: \"Biz,  sizden ve sizin Allah\'ın yanı sıra kulluk[2] ettiğiniz şeylerden kesinlikle uzağız. Biz,  sizi reddediyoruz. Siz,  ilahın yalnızca Allah olduğuna inanıncaya kadar bizimle sizin aranızda düşmanlık ve buğz[3] devam edecektir. Rabb\'imiz! Yalnız Sana dayandık,  yalnız Sana yöneldik. Ve dönüş yalnızca Sana\'dır.\"', 'قد كانت لكم اسوة حسنة في ابرهيم والذين معه اذ قالوا لقومهم انا بروا منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضا ابدا حتي تومنوا بالله وحده الا قول ابرهيم لابيه لاستغفرن لك وما املك لك من الله من شي ربنا عليك توكلنا واليك انبنا واليك المصير'),
(5155, 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلَّذ۪ينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَاۚ اِنَّكَ اَنْتَ الْعَز۪يزُ الْحَك۪يمُ', 'Rabbena la tec\'alna fitneten lillezine keferu, vagfir lena rabbena, inneke entel azizul hakim.', '\"Rabb\'imiz! Bizi Kafirler için sınav konusu yapma. Bizi bağışla Rabb\'imiz! Kuşkusuz Sen,  Mutlak Üstün Olan\'sın,  En Doğru Karar Veren\'sin.\"', 'ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم'),
(5156, 60, 6, 'لَقَدْ  كَانَ لَـكُمْ ف۪يهِمْ اُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَۜ وَمَنْ يَتَوَلَّ فَاِنَّ اللّٰهَ هُوَ الْغَنِيُّ الْحَم۪يدُ۟', 'Lekad kane lekum fihim usvetun hasenetun li men kane yercullahe vel yevmel ahire ve men yetevelle fe innallahe huvel ganiyyul hamid.', 'Ant olsun ki,  onlar,  sizin için ve Ahiret Günü\'nü bekleyen kimseler için iyi bir örnektirler. Kim yüz çevirirse,  bilsin ki kuşkusuz Allah; Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'لقد كان لكم فيهم اسوة حسنة لمن كان يرجوا الله واليوم الاخر ومن يتول فان الله هو الغني الحميد'),
(5157, 60, 7, 'عَسَى اللّٰهُ اَنْ يَجْعَلَ بَيْنَكُمْ وَبَيْنَ الَّذ۪ينَ عَادَيْتُمْ مِنْهُمْ مَوَدَّةًۜ وَاللّٰهُ قَد۪يرٌۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Asallahu en yec\'ale beynekum ve beynellezine adeytum minhum meveddeh, vallahu kadir, vallahu gafurun rahim.', 'Belki Allah,  gün gelir sizinle,  onlardan düşmanlık beslediğiniz kimseler arasında bir sevgi oluşturur. Allah; Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'عسي الله ان يجعل بينكم وبين الذين عاديتم منهم مودة والله قدير والله غفور رحيم'),
(5158, 60, 8, 'لَا يَنْهٰيكُمُ اللّٰهُ عَنِ الَّذ۪ينَ لَمْ يُقَاتِلُوكُمْ فِي الدّ۪ينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ اَنْ تَـبَرُّوهُمْ وَتُقْسِطُٓوا اِلَيْهِمْۜ  اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِط۪ينَ', 'La yenhakumullahu anillezine lem yukatilukum fid dini ve lem yuhricukum min diyarikum en teberruhum ve tuksitu ileyhim, innallahe yuhıbbul muksitin.', 'Allah; sizi,  din konusunda sizinle savaşmayan ve sizi yurdunuzdan çıkarmayan kimselere iyilik yapmaktan,  onlara karşı hak neyse onu yapmaktan alıkoymaz. Kuşkusuz ki Allah,  haktan ve haklıdan yana olanları sever.', 'لا ينهيكم الله عن الذين لم يقتلوكم في الدين ولم يخرجوكم من ديركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين'),
(5159, 60, 9, 'اِنَّمَا يَنْهٰيكُمُ اللّٰهُ عَنِ الَّذ۪ينَ قَاتَلُوكُمْ فِي الدّ۪ينِ وَاَخْرَجُوكُمْ مِنْ دِيَارِكُمْ وَظَاهَرُوا عَلٰٓى اِخْرَاجِكُمْ اَنْ تَوَلَّوْهُمْۚ وَمَنْ يَتَوَلَّهُمْ فَاُو۬لٰٓئِكَ هُمُ الظَّالِمُونَ', 'İnnema yenhakumullahu anillezine katelukum fid dini ve ahrecukum min diyarikum ve zaheru ala ıhracikum en tevellevhum, ve men yetevellehum fe ulaike humuz zalimun.', 'Ancak Allah,  din konusunda sizinle savaşan,  sizi yurtlarınızdan çıkaran ve çıkarılmanız için yardımlaşan kimselerle yakınlık kurmanızı yasaklamıştır. Kim onlarla yakınlık kurarsa,  onlar zalimlerin ta kendileridir.', 'انما ينهيكم الله عن الذين قتلوكم في الدين واخرجوكم من ديركم وظهروا علي اخراجكم ان تولوهم ومن يتولهم فاوليك هم الظلمون'),
(5160, 60, 10, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا جَٓاءَكُمُ الْمُؤْمِنَاتُ مُهَاجِرَاتٍ فَامْتَحِنُوهُنَّۜ  اَللّٰهُ اَعْلَمُ بِا۪يمَانِهِنَّۚ  فَاِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَاتٍ فَلَا تَرْجِعُوهُنَّ اِلَى الْكُفَّارِۜ  لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّۜ وَاٰتُوهُمْ مَٓا اَنْفَقُواۜ وَلَا جُنَاحَ عَلَيْكُمْ اَنْ تَنْكِحُوهُنَّ اِذَٓا اٰتَيْتُمُوهُنَّ اُجُورَهُنَّۜ وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ وَسْـَٔلُوا مَٓا اَنْفَقْتُمْ وَلْيَسْـَٔلُوا مَٓا اَنْفَقُواۜ  ذٰلِكُمْ حُكْمُ اللّٰهِۜ  يَحْكُمُ بَيْنَكُمْۜ  وَاللّٰهُ عَل۪يمٌ حَك۪يمٌ', 'Ya eyyuhellezine amenu iza caekumul mu\'minatu muhaciratin femtehınu hunn, allahu a\'lemu bi imanihinn, fe in alimtimu hunne mu\'minatin fe la terciu hunne ilel kuffar, la hunne hıllun lehum ve la hum yehıllune le hunn, ve atuhum ma enfeku, ve la cunaha aleykum en tenkıhu hunne iza ateytumu hunne ucurehunn, ve la tumsiku bi isamil kevafiri ves\'elu ma enfaktum vel yes\'elu ma enfeku, zalikum hukmullah, yahkumu beynekum, vallahu alimun hakim.', 'Ey iman edenler! Sığınmak üzere size gelen Mü\'min[1] kadınların hicret nedenlerini sorgulayın. Allah,  onların gerçekten inanıp inanmadıklarını çok iyi bilmektedir. Eğer gerçekten Mü\'min olduklarını anlarsanız,  onları Kafirlere[2] geri göndermeyin. Onlar,  Kafir erkeklere helal değildir. Kafir erkekler de onlara helal değildir. Kafirlerin bu kadınlara verdiklerini[3] iade edin. Mehirlerini verdiğiniz takdirde onlarla nikahlanmanızda bir sakınca yoktur. Ve Kafir kadınları[4] nikahınızda tutmayın. Ve ne infak[5] ettiyseniz geri isteyin. Onlar da infak ettiklerini geri istesinler. İşte bu Allah\'ın aranızda verdiği hükmüdür. Allah; Her Şeyi Bilen\'dir,  En Doğru Karar Veren\'dir.', 'يايها الذين امنوا اذا جاكم المومنت مهجرت فامتحنوهن الله اعلم بايمنهن فان علمتموهن مومنت فلا ترجعوهن الي الكفار لا هن حل لهم ولا هم يحلون لهن واتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا اتيتموهن اجورهن ولا تمسكوا بعصم الكوافر وسلوا ما انفقتم وليسلوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم'),
(5161, 60, 11, 'وَاِنْ فَاتَكُمْ شَيْءٌ مِنْ اَزْوَاجِكُمْ اِلَى الْـكُفَّارِ فَعَاقَبْتُمْ فَاٰتُوا الَّذ۪ينَ ذَهَبَتْ اَزْوَاجُهُمْ مِثْلَ مَٓا اَنْفَقُواۜ وَاتَّقُوا اللّٰهَ الَّـذ۪ٓي اَنْتُمْ بِه۪ مُؤْمِنُونَ', 'Ve in fatekum şey\'un min ezvacikum ilel kuffari fe akabtum fe atullezine zehebet ezvacuhum misle ma enfeku, vettekullahellezi entum bihi mu\'minun.', 'Eğer eşlerinizden[1] dolayı,  bir şeyiniz Kafirlere geçtiyse,  sonra da ödeme sırası size geldiğinde[2],  o zaman eşleri gitmiş olanlara infak ettikleri kadar verin. Ve siz,  kendisine iman ettiğiniz Allah\'a karşı takva sahibi olun.', 'وان فاتكم شي من ازوجكم الي الكفار فعاقبتم فاتوا الذين ذهبت ازوجهم مثل ما انفقوا واتقوا الله الذي انتم به مومنون'),
(5162, 60, 12, 'يَٓا اَيُّهَا النَّبِيُّ اِذَا جَٓاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلٰٓى اَنْ لَا يُشْرِكْنَ بِاللّٰهِ شَيْـٔاً وَلَا يَسْرِقْنَ وَلَا يَزْن۪ينَ وَلَا يَقْتُلْنَ اَوْلَادَهُنَّ وَلَا يَأْت۪ينَ بِبُهْتَانٍ يَفْتَر۪ينَهُ بَيْنَ اَيْد۪يهِنَّ وَاَرْجُلِهِنَّ وَلَا يَعْص۪ينَكَ ف۪ي مَعْرُوفٍ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللّٰهَۜ اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Ya eyyuhen nebiyyu iza caekel mu\'minatu yubayi\'neke ala en la yuşrikne billahi şey\'en ve la yesrikne ve la yeznine ve la yaktulne evladehunne ve la ye\'tine bi buhtanin yefterinehu beyne eydihinne ve erculihinne ve la ya\'sineke fi ma\'rufin fe bayı\'hunne vestagfirlehunnallah innallahe gafurun rahim.', 'Ey Nebi! İnanan kadınlar; Allah\'a hiçbir şeyi ortak koşmamak,  hırsızlık yapmamak,  zina yapmamak,  çocuklarını öldürmemek elleri ve ayakları arasında bir iftira uydurup[1] getirmemek maruf[2] olan konularda sana asilik yapmamak koşuluyla sana bi\'at[3] ederlerse onların bi\'atlarını kabul et ve onlar için Allah\'tan bağışlanma dile. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها النبي اذا جاك المومنت يبايعنك علي ان لا يشركن بالله شيا ولا يسرقن ولا يزنين ولا يقتلن اولدهن ولا ياتين ببهتن يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم'),
(5163, 60, 13, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تَتَوَلَّوْا قَوْماً غَضِبَ اللّٰهُ عَلَيْهِمْ قَدْ يَـئِسُوا مِنَ الْاٰخِرَةِ كَمَا يَـئِسَ الْكُفَّارُ مِنْ اَصْحَابِ الْقُبُورِ', 'Ya eyyuhellezine amenu la tetevellev kavmen gadıballahu aleyhim kad yeisu minel ahireti kema yeisel kuffaru min ashabil kubur.', 'Ey iman edenler! Allah\'ın gazap ettiği halka dönmeyin.[1] Kafirlerin mezarlık halkından ümitlerini kestikleri gibi[2] onlar da ahiretten ümitlerini kesmişlerdir.', 'يايها الذين امنوا لا تتولوا قوما غضب الله عليهم قد ييسوا من الاخرة كما ييس الكفار من اصحب القبور'),
(5164, 61, 1, 'سَبَّحَ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۚ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Sebbeha lillahi ma fis semavati ve ma fil ard, ve huvel azizul hakim.', 'Göklerde ve yerde olanlar,  Allah\'ı tesbih ederler. O,  Mutlak Üstün Olan\'dır ve En Doğru Hüküm Veren\'dir.', 'سبح لله ما في السموت وما في الارض وهو العزيز الحكيم'),
(5165, 61, 2, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'Ya eyyuhellezine amenu lime tekulune ma la tef\'alun.', 'Ey iman edenler! Yapmayacağınız şeyi niçin söylüyorsunuz?', 'يايها الذين امنوا لم تقولون ما لا تفعلون'),
(5166, 61, 3, 'كَبُرَ مَقْتاً عِنْدَ اللّٰهِ اَنْ تَقُولُوا مَا لَا تَفْعَلُونَ', 'Kebure makten indallahi en tekulu ma la tef\'alun.', 'Yapmayacağınız şeyleri söylemeniz,  Allah\'ın yanında en nefret edilen şeydir.', 'كبر مقتا عند الله ان تقولوا ما لا تفعلون'),
(5167, 61, 4, 'اِنَّ اللّٰهَ يُحِبُّ الَّذ۪ينَ يُقَاتِلُونَ ف۪ي سَب۪يلِه۪ صَفاًّ كَاَنَّهُمْ بُنْيَانٌ مَرْصُوصٌ', 'İnnallahe yuhıbbullezine yukatilune fi sebilihi saffen ke ennehum bunyanun mersus.', 'Allah,  kendi yolunda bir duvarın taşları gibi kenetlenip saf tutarak savaşanları sever.', 'ان الله يحب الذين يقتلون في سبيله صفا كانهم بنين مرصوص'),
(5168, 61, 5, 'وَاِذْ قَالَ مُوسٰى لِقَوْمِه۪ يَا قَوْمِ لِمَ تُؤْذُونَن۪ي وَقَدْ تَعْلَمُونَ اَنّ۪ي رَسُولُ اللّٰهِ اِلَيْكُمْۜ فَلَمَّا زَاغُٓوا اَزَاغَ اللّٰهُ قُلُوبَهُمْۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الْفَاسِق۪ينَ', 'Ve iz kale musa li kavmihi ya kavmi lime tu\'zuneni ve kad ta\'lemune enni resulullahi ileykum, fe lemma zagu ezagallahu kulubehum, vallahu la yehdil kavmel fasikin.', 'Hani Musa,  halkına: \"Ey halkım! Benim,  size Allah tarafından gönderilen bir resul olduğumu bildiğiniz halde,  niçin bana eziyet ediyorsunuz?\" demişti. Ne zaman ki onlar eğrildiler,  Allah da onların kalplerini eğriltti. Allah,  fasıklar topluluğuna doğru yolu göstermez.', 'واذ قال موسي لقومه يقوم لم توذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفسقين'),
(5169, 61, 6, 'وَاِذْ قَالَ ع۪يسَى ابْنُ مَرْيَمَ يَا بَن۪ٓي اِسْرَٓائ۪لَ اِنّ۪ي رَسُولُ اللّٰهِ اِلَيْكُمْ مُصَدِّقاً لِمَا بَـيْنَ يَدَيَّ مِنَ التَّوْرٰيةِ وَمُبَشِّراً بِرَسُولٍ يَأْت۪ي مِنْ بَعْدِي اسْمُهُٓ اَحْمَدُۜ فَلَمَّا جَٓاءَهُمْ بِالْبَـيِّنَاتِ قَالُوا هٰذَا سِحْرٌ مُب۪ينٌ', 'Ve iz kale isebnu meryeme ya beni israile inni resulullahi ileykum musaddikan li ma beyne yedeyye minet tevrati ve mubeşşiren bi resulin ye\'ti min bagdismuhu ahmed, fe lemma caehum bil beyyinati kalu haza sihrun mubin.', 'Hani Meryem oğlu Îsa: \"Ey İsrailoğulları! Ben,  elinizdeki Tevrat\'ı doğrulayan ve benden sonra gelecek olan,  adı ahmed[1] olan bir resulü müjdeleyen Allah\'ın Resul\'üyüm.\" demişti. Fakat onlara beyyineler[2] getirince,  onlar: \"Bu,  apaçık bir büyüdür.\" dediler.', 'واذ قال عيسي ابن مريم يبني اسريل اني رسول الله اليكم مصدقا لما بين يدي من التورية ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاهم بالبينت قالوا هذا سحر مبين'),
(5170, 61, 7, 'وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ الْـكَذِبَ وَهُوَ يُدْعٰٓى اِلَى الْاِسْلَامِۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'Ve men azlemu mimmeniftera alallahil kezibe ve huve yud\'a ilel islam, vallahu la yehdil kavmez zalimin.', 'İslam\'a çağrıldığı halde,  uydurduğu yalanları Allah\'a isnat ederek,  iftira edenden daha zalim kim olabilir? Allah,  zalim topluma doğru yolu göstermez.', 'ومن اظلم ممن افتري علي الله الكذب وهو يدعي الي الاسلم والله لا يهدي القوم الظلمين'),
(5171, 61, 8, 'يُر۪يدُونَ لِيُطْفِؤُ۫ا نُورَ اللّٰهِ بِاَفْوَاهِهِمْ وَاللّٰهُ مُتِمُّ نُورِه۪ وَلَوْ كَرِهَ الْـكَافِرُونَ', 'Yuridune li utfiu nurallahi bi efvahihim vallahu mutimmu nurihi ve lev kerihel kafirun.', 'Onlar,  ağızları ile Allah\'ın nurunu söndürmek istiyorlar.[1] Ancak,  Kafirlerin hoşuna gitmese de Allah,  nurunu tamamlayacaktır.', 'يريدون ليطفوا نور الله بافوههم والله متم نوره ولو كره الكفرون'),
(5172, 61, 9, 'هُوَ الَّـذ۪ٓي اَرْسَلَ رَسُولَهُ بِالْهُدٰى وَد۪ينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدّ۪ينِ كُلِّه۪ وَلَوْ كَرِهَ الْمُشْرِكُونَ۟', 'Huvellezi ersele resulehu bil huda ve dinil hakkı li yuzhirehu aled dini kullihi ve lev kerihel muşriku.', 'Müşriklerin hoşuna gitmese de Resul\'ünü,  dinin tamamını bildirmek üzere doğru yolu gösteren rehberle ve Hakk Din ile gönderen O\'dur.', 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله ولو كره المشركون'),
(5173, 61, 10, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا هَلْ اَدُلُّكُمْ عَلٰى تِجَارَةٍ تُنْج۪يكُمْ مِنْ عَذَابٍ اَل۪يمٍ', 'Ya eyyuhellezine amenu hel edullukum ala ticaretin tuncikum min azabin elim.', 'Ey iman edenler! Size,  can yakıcı bir azaptan kurtaracak,  kazançlı bir ticaretin yolunu göstereyim mi?', 'يايها الذين امنوا هل ادلكم علي تجرة تنجيكم من عذاب اليم'),
(5174, 61, 11, 'تُـؤْمِنُونَ بِاللّٰهِ وَرَسُولِه۪ وَتُجَاهِدُونَ ف۪ي سَب۪يلِ اللّٰهِ بِاَمْوَالِكُمْ وَاَنْفُسِكُمْۜ ذٰلِكُمْ خَيْرٌ لَـكُمْ اِنْ كُنْتُمْ تَعْلَمُونَۙ', 'Tu\'minune billahi ve resulihi ve tucahidune fi sebilillahi bi emvalikum ve enfusikum, zalikum hayrun lekum in kuntum ta\'lemun.', 'Bu,  Allah\'a ve Resul\'üne iman etmeniz; Allah yolunda,  mallarınızla ve canlarınızla cihad[1] etmenizdir. İşte bu,  eğer bilirseniz sizin için hayırlı olandır.', 'تومنون بالله ورسوله وتجهدون في سبيل الله بامولكم وانفسكم ذلكم خير لكم ان كنتم تعلمون'),
(5175, 61, 12, 'يَغْفِرْ لَـكُمْ ذُنُوبَكُمْ وَيُدْخِلْـكُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ وَمَسَا‌كِنَ طَيِّبَةً ف۪ي جَنَّاتِ عَدْنٍۜ  ذٰلِكَ الْفَوْزُ الْعَظ۪يمُۙ', 'Yagfir lekum zunubekum ve yudhılkum cennatin tecri min tahtihel enharu ve mesakine tayyibeten fi cennati adn, zalikel fevzul azim.', 'Sizin suçlarınızı bağışlar ve sizi içinden nehirler akan Cennetlere koyar. Ve sizi,  Adn Cennetlerinde,  hoş meskenlere yerleştirir. İşte bu,  büyük kurtuluştur.', 'يغفر لكم ذنوبكم ويدخلكم جنت تجري من تحتها الانهر ومسكن طيبة في جنت عدن ذلك الفوز العظيم'),
(5176, 61, 13, 'وَاُخْرٰى تُحِبُّونَهَاۜ نَصْرٌ مِنَ اللّٰهِ وَفَتْحٌ قَر۪يبٌۜ وَبَشِّرِ الْمُؤْمِن۪ينَ', 'Ve uhra tuhıbbuneha, nasrun minallahi ve fethun karib, ve beşşiril mu\'minin.', 'Ayrıca seveceğiniz bir şey daha: Allah\'tan yardım ve yakın bir fetih. Mü\'minleri müjdele.', 'واخري تحبونها نصر من الله وفتح قريب وبشر المومنين'),
(5177, 61, 14, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا كُونُٓوا اَنْصَارَ اللّٰهِ كَمَا قَالَ ع۪يسَى ابْنُ مَرْيَمَ لِلْحَوَارِيّ۪نَ مَنْ اَنْصَار۪ٓي اِلَى اللّٰهِۜ  قَالَ الْحَوَارِيُّونَ نَحْنُ اَنْصَارُ اللّٰهِ فَاٰمَنَتْ طَٓائِفَةٌ مِنْ بَن۪ٓي اِسْرَٓائ۪لَ وَكَـفَرَتْ طَٓائِفَةٌۚ فَاَيَّدْنَا الَّذ۪ينَ اٰمَنُوا عَلٰى عَدُوِّهِمْ فَاَصْبَحُوا ظَاهِر۪ينَ', 'Ya eyyuhellezine amenu kunu ensarallahi kema kale isebnu meryeme lil havariyyine men ensari ilallah, kalel havariyune nahnu ensarullah, fe amenet taifetun min beni israile ve keferet taifeh, fe eyyednellezine amenu ala aduvvihim fe asbehu zahirin.', 'Ey iman edenler! Allah\'ın yardımcıları olun! Meryem Oğlu İsa\'nın havarilere: \"Allah yolunda benim yardımcılarım kimdir?\" dediği zaman,  havarilerin: \"Allah yolunun yardımcıları biziz.\" dedikleri gibi. Sonuçta,  İsrailoğulları\'nın bir kısmı inandı,  bir kısmı da inanmadı. Biz de iman edenleri,  düşmanlarına karşı destekledik. Böylece,  onlar üstün geldiler.', 'يايها الذين امنوا كونوا انصار الله كما قال عيسي ابن مريم للحوارين من انصاري الي الله قال الحواريون نحن انصار الله فامنت طايفة من بني اسريل وكفرت طايفة فايدنا الذين امنوا علي عدوهم فاصبحوا ظهرين'),
(5178, 62, 1, 'يُسَبِّـحُ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِ الْمَلِكِ الْقُدُّوسِ الْعَز۪يزِ الْحَك۪يمِ', 'Yusebbihu lillahi ma fis semavati ve ma fil ardıl melikil kuddusil azizil hakim.', 'Göklerde ve yerde bulunanların tamamı,  Melik[1],  Kuddus[2],  Mutlak Üstün Olan,  En İyi Hüküm Veren Allah\'ı tesbih[3] etmektedir.', 'يسبح لله ما في السموت وما في الارض الملك القدوس العزيز الحكيم'),
(5179, 62, 2, 'هُوَ الَّذ۪ي بَعَثَ فِي الْاُمِّيّ۪نَ رَسُولاً مِنْهُمْ يَتْلُوا عَلَيْهِمْ اٰيَاتِه۪ وَيُزَكّ۪يهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَۗ وَاِنْ كَانُوا مِنْ قَبْلُ لَف۪ي ضَلَالٍ مُب۪ينٍۙ', 'Huvellezi bease fil ummiyyine resulen minhum yetlu aleyhim ayatihi ve yuzekkihim ve yuallimuhumul kitabe vel hikmeh, ve in kanu min kablu le fi dalalin mubin.', 'Ümmilere[1],  kendilerinden olan; O\'nun ayetlerini okuyan,  onları arındıran,  onlara Kitap\'ı ve Hikmet\'i[2] öğreten bir resul görevlendiren O\'dur. Onlar,  bundan önce apaçık bir sapkınlık içindeydiler.', 'هو الذي بعث في الامين رسولا منهم يتلوا عليهم ايته ويزكيهم ويعلمهم الكتب والحكمة وان كانوا من قبل لفي ضلل مبين'),
(5180, 62, 3, 'وَاٰخَر۪ينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْۜ وَهُوَ الْعَز۪يزُ الْحَك۪يمُ', 'Ve aharine minhum lemma yelhaku bi him, ve huvel azizul hakim.', 'Onlardan,  henüz kendilerine katılmamış olan diğerlerine de. O,  Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'واخرين منهم لما يلحقوا بهم وهو العزيز الحكيم'),
(5181, 62, 4, 'ذٰلِكَ فَضْلُ اللّٰهِ يُؤْت۪يهِ مَنْ يَشَٓاءُۜ وَاللّٰهُ ذُوالْفَضْلِ الْعَظ۪يمِ', 'Zalike fadlullahi yu\'tihi men yeşau, vallahu zul fadlil azim.', 'İşte bu,  Allah\'ın hak eden[1] kimselere verdiği lütfudur. Allah,  büyük lütuf sahibidir.', 'ذلك فضل الله يوتيه من يشا والله ذو الفضل العظيم'),
(5182, 62, 5, 'مَثَلُ الَّذ۪ينَ حُمِّلُوا التَّوْرٰيةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ الْحِمَارِ يَحْمِلُ اَسْفَاراًۜ بِئْسَ مَثَلُ الْقَوْمِ الَّذ۪ينَ كَذَّبُوا بِاٰيَاتِ اللّٰهِۜ وَاللّٰهُ لَا يَهْدِي الْقَوْمَ الظَّالِم۪ينَ', 'Meselullezine hummilut tevrate summe lem yahmiluha ke meselil hımari yahmilu esfara, bi\'se meselul kavmillezine kezzebu bi ayatillah, vallahu la yehdil kavmez zalimin.', 'Tevrat\'a uymakla yükümlü kılınıp da yükümlülüğünü yerine getirmeyen kimselerin durumu,  ciltlerle kitap taşıyan eşeklerin durumu gibidir. Allah\'ın ayetlerini yalanlayan toplumun düştüğü durum ne kötüdür. Allah,  zalim[1] toplumu doğru yola iletmez.', 'مثل الذين حملوا التورية ثم لم يحملوها كمثل الحمار يحمل اسفارا بيس مثل القوم الذين كذبوا بايت الله والله لا يهدي القوم الظلمين'),
(5183, 62, 6, 'قُلْ يَٓا اَيُّهَا الَّذ۪ينَ هَادُٓوا اِنْ زَعَمْتُمْ اَنَّكُمْ اَوْلِيَٓاءُ لِلّٰهِ مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Kul ya eyyuhellezine hadu in zeamtum ennekum evliyau lillahi min dunin nasi fe temennevul mevte in kuntum sadikin.', 'De ki: \"Ey Yahudiler! Eğer diğer insanların değil de yalnızca kendinizin Allah\'ın velileri[1] olduğunuza inanıyorsanız ve bu iddianızda samimi iseniz,  haydi hemen ölümü isteyin.[2]\"', 'قل يايها الذين هادوا ان زعمتم انكم اوليا لله من دون الناس فتمنوا الموت ان كنتم صدقين'),
(5184, 62, 7, 'وَلَا يَتَمَنَّوْنَهُٓ اَبَداً بِمَا قَدَّمَتْ اَيْد۪يهِمْۜ وَاللّٰهُ عَل۪يمٌ بِالظَّالِم۪ينَ', 'Ve la yetemennevnehu ebeden bi ma kaddemet eydihim, vallahu alimun biz zalimin.', 'Yaptıkları şeyler nedeniyle,  hiçbir zaman ölümü temenni etmezler. Allah,  haksızlık edenleri en iyi bilendir.', 'ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظلمين'),
(5185, 62, 8, 'قُلْ اِنَّ الْمَوْتَ الَّذ۪ي تَفِرُّونَ مِنْهُ فَاِنَّهُ مُلَاق۪يكُمْ ثُمَّ تُرَدُّونَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ۟', 'Kul innel mevtellezi tefirrune minhu fe innehu mulakikum summe tureddune ila alimil gaybi veş şehadeti fe yunebbiukum bi ma kuntum ta\'melun.', 'De ki: Kendisinden kaçtığınız ölüm,  kesinlikle karşınıza çıkacaktır. Sonra,  görünmeyen ve görünen her şeyi bilene döndürüleceksiniz. O,  size yaptıklarınızı haber verecektir.', 'قل ان الموت الذي تفرون منه فانه ملقيكم ثم تردون الي علم الغيب والشهدة فينبيكم بما كنتم تعملون'),
(5186, 62, 9, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِذَا نُودِيَ لِلصَّلٰوةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا اِلٰى ذِكْرِ اللّٰهِ وَذَرُوا الْبَيْعَۜ ذٰلِكُمْ خَيْرٌ لَكُمْ اِنْ كُنْتُمْ تَعْلَمُونَ', 'Ya eyyuhellezine amenu iza nudiye lis salati min yevmil cumuati fes\'av ila zikrillahi ve zerul bey\'a, zalikum hayrun lekum in kuntum ta\'lemun.', 'Ey iman edenler! Cuma[1] günü salat[2] için seslenildiği zaman,  alışverişi[3] bırakıp,  hemen Allah\'ın öğüdüne koşun. Eğer bilirseniz,  bu,  sizin için hayırlı olandır.', 'يايها الذين امنوا اذا نودي للصلوة من يوم الجمعة فاسعوا الي ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون'),
(5187, 62, 10, 'فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوا فِي الْاَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللّٰهِ وَاذْكُرُوا اللّٰهَ كَث۪يراً لَعَلَّكُمْ تُفْلِحُونَ', 'Fe iza kudiyetıs salatu fenteşiru fil ardı vebtegu min fadlillahi vezkurullahe kesiren leallekum tuflihun.', 'Salatı kaza[1] ettikten sonra,  hemen yeryüzüne dağılın ve Allah\'ın lütfundan nasibinizi arayın. Allah\'ın öğütlerini hiç unutmayın. Umulur ki,  böylece kurtuluşa erersiniz.', 'فاذا قضيت الصلوة فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون'),
(5188, 62, 11, 'وَاِذَا رَاَوْا تِجَارَةً اَوْ لَهْواًۨ انْفَضُّٓوا اِلَيْهَا وَتَرَكُوكَ قَٓائِماًۜ قُلْ مَا عِنْدَ اللّٰهِ خَيْرٌ مِنَ اللَّهْوِ وَمِنَ التِّجَارَةِۜ وَاللّٰهُ خَيْرُ الرَّازِق۪ينَ', 'Ve iza reev ticareten ev lehveninfaddu ileyha ve terekuke kaima, kul ma indallahi hayrun minel lehvi ve minet ticareh, vallahu hayrur razıkin.', 'Bir kısım insanlar,  ticaret ve eğlence görünce,  seni bırakarak ona yönelip gittiler. De ki: \"Allah\'ın katında olanlar,  eğlenceden ve ticaretten daha hayırlıdır ve Allah,  rızık verenlerin en hayırlısıdır.\"', 'واذا راوا تجرة او لهوا انفضوا اليها وتركوك قايما قل ما عند الله خير من اللهو ومن التجرة والله خير الرزقين'),
(5189, 63, 1, 'اِذَا جَٓاءَكَ الْمُنَافِقُونَ قَالُوا نَشْهَدُ اِنَّكَ لَرَسُولُ اللّٰهِۢ وَاللّٰهُ يَعْلَمُ اِنَّكَ لَرَسُولُهُۜ وَاللّٰهُ يَشْهَدُ اِنَّ الْمُنَافِق۪ينَ لَـكَاذِبُونَۚ', 'İza caekel munafikune kalu neşhedu inneke le resulullah, vallahu ya\'lemu inneke le resuluh, vallahu yeşhedu innel munafikine le kazibun.', 'Münafıklar[1] sana geldiklerinde: \"Biz,  tanıklık ederiz ki,  kuşkusuz sen,  Allah\'ın Resul\'üsün.\" dediler. Elbette ki Allah,  senin,  Kendisinin Resul\'ü olduğunu biliyor. Fakat Allah tanıktır ki,  münafıklar,  kesinlikle yalancıdırlar.', 'اذا جاك المنفقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنفقين لكذبون'),
(5190, 63, 2, 'اِتَّخَذُٓوا اَيْمَانَهُمْ جُنَّةً فَصَدُّوا عَنْ سَب۪يلِ اللّٰهِۜ اِنَّهُمْ سَٓاءَ مَا كَانُوا يَعْمَلُونَ', 'İttehazu eymanehum cunneten fe saddu an sebilillah, innehum sae ma kanu ya\'melun.', 'Onlar,  yeminlerini kalkan yapıyorlar.[1] Böylece insanları,  Allah\'ın yolundan saptırıyorlar. Kuşkusuz,  yaptıkları şey çok kötüdür.', 'اتخذوا ايمنهم جنة فصدوا عن سبيل الله انهم سا ما كانوا يعملون'),
(5191, 63, 3, 'ذٰلِكَ بِاَنَّهُمْ اٰمَنُوا ثُمَّ كَفَرُوا فَطُبِعَ عَلٰى قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'Zalike bi ennehum amenu summe keferu fe tubia ala kulubihim fe hum la yefkahun.', 'Bu şundandır: onlar önce İman ettiler sonra küfrettiler. Bu nedenle,  onların kalpleri mühürlenmiştir. Artık onlar,  gerçeği kavrayamazlar.', 'ذلك بانهم امنوا ثم كفروا فطبع علي قلوبهم فهم لا يفقهون'),
(5192, 63, 4, 'وَاِذَا رَاَيْتَهُمْ تُعْجِبُكَ اَجْسَامُهُمْۜ وَاِنْ يَقُولُوا تَسْمَعْ لِقَوْلِهِمْۜ   كَاَنَّهُمْ خُشُبٌ مُسَنَّدَةٌۜ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْۜ هُمُ الْعَدُوُّ فَاحْذَرْهُمْۜ  قَاتَلَهُمُ اللّٰهُۘ  اَنّٰى يُؤْفَـكُونَ', 'Ve iza reeytehum tu\'cibuke ecsamuhum, ve in yekulu tesma\', li kavlihim, ke ennehum huşubun musennedeh, yahsebune kulle sayhatin aleyhim, humul aduvvu fahzerhum, katelehumullahu enna yu\'fekun.', 'Onlara baktığında,  dış görünüşleri itibariyle,  seni hayran bırakırlar. Konuştuklarında,  sözlerine itibar edersin. Aslında,  elbise giydirilmiş kütükler gibidirler. Her koşuşturmayı kendi aleyhlerine sanırlar. Onlar,  düşmandırlar,  onlara karşı dikkatli ol. Allah,  onların canlarını alsın! Nasıl da döndürülüyorlar!', 'واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسندة يحسبون كل صيحة عليهم هم العدو فاحذرهم قتلهم الله اني يوفكون'),
(5193, 63, 5, 'وَاِذَا ق۪يلَ لَهُمْ تَعَالَوْا يَسْتَغْفِرْ لَكُمْ رَسُولُ اللّٰهِ لَـوَّوْا رُؤُ۫سَهُمْ وَرَاَيْتَهُمْ يَصُدُّونَ وَهُمْ مُسْتَكْبِرُونَ', 'Ve iza kile lehum tealev yestagfir lekum resulullahi levvev ruusehum ve reeytehum yesuddune ve hum mustekbirun.', 'Ve onlara,  \"Gelin,  Allah\'ın Resul\'ü sizin için bağışlanma dilesin.\" dendiği zaman; tersleyerek,  büyüklük taslayıp,  çekip gittiklerini görürsün.', 'واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا روسهم ورايتهم يصدون وهم مستكبرون'),
(5194, 63, 6, 'سَوَٓاءٌ عَلَيْهِمْ اَسْتَغْفَرْتَ لَهُمْ اَمْ لَمْ تَسْتَغْفِرْ لَهُمْۜ لَنْ يَغْفِرَ اللّٰهُ لَهُمْۜ اِنَّ اللّٰهَ لَا يَهْدِي الْقَوْمَ الْفَاسِق۪ينَ', 'Sevaun aleyhim estagferte le hum em lem testagfir lehum, len yagfirallahu lehum, innallahe la yehdil kavmel fasikin.', 'Zaten onlar için bağışlanma dilesen de dilemesen de fark etmez. Allah,  onları asla bağışlamayacaktır. Çünkü Allah,  böyle fasık halkı asla doğru yola iletmez.', 'سوا عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفسقين'),
(5195, 63, 7, 'هُمُ الَّذ۪ينَ يَقُولُونَ لَا تُنْفِقُوا عَلٰى مَنْ عِنْدَ رَسُولِ اللّٰهِ حَتّٰى يَنْفَضُّواۜ وَلِلّٰهِ خَزَٓائِنُ السَّمٰوَاتِ وَالْاَرْضِ وَلٰكِنَّ الْمُنَافِق۪ينَ لَا يَفْقَهُونَ', 'Humullezine yekulune la tunfiku ala men inde resulillahi hatta yenfaddu, ve lillahi hazainus semavati vel ardı ve lakinnel munafikine la yefkahun.', 'Onlar,  Allah\'ın Resul\'ünün yanında bulunanlara,  \"Yardım etmeyin ki,  dağılıp gitsinler.\" diyenlerdir. Oysa göklerin ve yeryüzünün bütün hazineleri Allah\'ındır. Ancak,  münafıklar,  bu gerçeği kavrayamıyorlar.', 'هم الذين يقولون لا تنفقوا علي من عند رسول الله حتي ينفضوا ولله خزاين السموت والارض ولكن المنفقين لا يفقهون'),
(5196, 63, 8, 'يَقُولُونَ لَئِنْ رَجَعْنَٓا اِلَى الْمَد۪ينَةِ لَيُخْرِجَنَّ الْاَعَزُّ مِنْهَا الْاَذَلَّۜ وَلِلّٰهِ الْعِزَّةُ وَلِرَسُولِه۪ وَلِلْمُؤْمِن۪ينَ وَلٰكِنَّ الْمُنَافِق۪ينَ لَا يَعْلَمُونَ۟', 'Yekulune le in reca\'na ilel medineti le yuhricennel eazzu min hel ezell, ve lillahil izzetu ve li resulihi ve lil mu\'minine ve lakinnel munafikine la ya\'lemun.', '\"Eğer Medine\'ye dönecek olursak,  mutlaka daha güçlü olan,  güçsüz olanı,  oradan sürüp çıkarır.\" diyorlar. Oysa izzet; Allah\'ın,  O\'nun Resul\'ünün ve inananlarındır. Fakat münafıklar bu gerçeği bilmiyorlar.', 'يقولون لين رجعنا الي المدينة ليخرجن الاعز منها الاذل ولله العزة ولرسوله وللمومنين ولكن المنفقين لا يعلمون'),
(5197, 63, 9, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا لَا تُلْهِكُمْ اَمْوَالُكُمْ وَلَٓا اَوْلَادُكُمْ عَنْ ذِكْرِ اللّٰهِۚ وَمَنْ يَفْعَلْ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الْخَاسِرُونَ', 'Ya eyyuhellezine amenu la tulhikum emvalukum ve la evladukum an zikrillah, ve men yef\'al zalike fe ulaike humul hasirun.', 'Ey iman edenler! Mallarınız ve çocuklarınız,  sizi,  Allah\'ın öğütlerini dinlemekten alıkoymasın. Kimler bunu yaparsa,  bilsinler ki asıl kaybedenler onlardır.', 'يايها الذين امنوا لا تلهكم امولكم ولا اولدكم عن ذكر الله ومن يفعل ذلك فاوليك هم الخسرون'),
(5198, 63, 10, 'وَاَنْفِقُوا مِمَّا رَزَقْنَاكُمْ مِنْ قَبْلِ اَنْ يَأْتِيَ اَحَدَكُمُ الْمَوْتُ فَيَقُولَ رَبِّ لَوْلَٓا اَخَّرْتَـن۪ٓي اِلٰٓى اَجَلٍ قَر۪يبٍۙ فَاَصَّدَّقَ وَاَكُنْ مِنَ الصَّالِح۪ينَ', 'Ve enfiku mimma rezaknakum min kabli en ye\'tiye ehadekumul mevtu fe yekule rabbi lev la ahharteni ila ecelin karibin fe assaddeka ve ekun mines salihin.', 'Herhangi birinize ölüm gelip çatıp da \"Rabb\'im! Ölümümü yakın bir zamana kadar ertelesen de böylece ben de sadaka versem ve iyilerden olsam.\" demezden önce,  size rızık olarak verdiklerimizden karşılıksız yardımda bulunun.', 'وانفقوا من ما رزقنكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الي اجل قريب فاصدق واكن من الصلحين'),
(5199, 63, 11, 'وَلَنْ يُؤَخِّرَ اللّٰهُ نَفْساً اِذَا جَٓاءَ اَجَلُهَاۜ وَاللّٰهُ خَب۪يرٌ بِمَا تَعْمَلُونَ', 'Ve len yuahhırallahu nefsen iza cae eceluha, vallahu habirun bi ma ta\'melun.', 'Allah,  süresinin sonu gelmiş hiç kimseyi asla ertelemez. Allah,  yaptığınız her şeyden haberdardır.', 'ولن يوخر الله نفسا اذا جا اجلها والله خبير بما تعملون'),
(5200, 64, 1, 'يُسَبِّحُ لِلّٰهِ مَا فِي السَّمٰوَاتِ وَمَا فِي الْاَرْضِۚ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُۘ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Yusebbihu lillahi ma fis semavati ve ma fil ard, le hul mulku ve le hul hamdu ve huve ala kulli şey\'in kadir.', 'Göklerde ve yeryüzünde olan her şey Allah\'ı tesbih[1] eder. Mülk[2] yalnızca O\'nundur. Hamd[3] O\'nadır. O\'nun gücü her şeye yeter.', 'يسبح لله ما في السموت وما في الارض له الملك وله الحمد وهو علي كل شي قدير'),
(5201, 64, 2, 'هُوَ الَّذ۪ي خَلَقَكُمْ فَمِنْكُمْ  كَافِرٌ وَمِنْكُمْ مُؤْمِنٌۜ وَاللّٰهُ بِمَا تَعْمَلُونَ بَص۪يرٌ', 'Huvellezi halakakum fe minkum kafiru ve minkum mu\'min, vallahu bima ta\'melune basir.', 'Sizi yaratan O\'dur. Böyleyken; iman edeniniz var,  Kafir olanınız var. Allah,  yaptıklarınızı görmektedir.', 'هو الذي خلقكم فمنكم كافر ومنكم مومن والله بما تعملون بصير'),
(5202, 64, 3, 'خَلَقَ السَّمٰوَاتِ وَالْاَرْضَ بِالْحَقِّ وَصَوَّرَكُمْ فَاَحْسَنَ صُوَرَكُمْۚ وَاِلَيْهِ الْمَص۪يرُ', 'Halakas semavati vel arda bil hakkı ve savverekum fe ahsene suverekum ve ileyhil masir.', 'Gökleri ve yeri hakk ile yarattı. Size,  en iyi biçimle biçim verdi. Ve dönüş yalnızca O\'nadır.', 'خلق السموت والارض بالحق وصوركم فاحسن صوركم واليه المصير'),
(5203, 64, 4, 'يَعْلَمُ مَا فِي السَّمٰوَاتِ وَالْاَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَۜ وَاللّٰهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Ya\'lemu ma fis semavati vel ardı ve ya\'lemu ma tusirrune ve ma tu\'linun, vallahu alimun bi zatis sudur.', 'Göklerde ve yerde olanları bilir. Gizlediklerinizi de açığa vurduğunuzu da bilir. Allah,  göğüslerin özünü en iyi bilendir.', 'يعلم ما في السموت والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور'),
(5204, 64, 5, 'اَلَمْ يَأْتِكُمْ نَبَؤُا الَّذ۪ينَ كَـفَرُوا مِنْ قَبْلُۘ فَذَاقُوا وَبَالَ اَمْرِهِمْ وَلَهُمْ عَذَابٌ اَل۪يمٌ', 'E lem ye\'tikum nebeullezine keferu min kablu fe zaku ve bale emrihim ve lehum azabun elim.', 'Kafirlerin[1] yaptıkları şeylerin bedelini nasıl ödediklerinin haberi size gelmedi mi? Onlar için acı bir azap vardır.', 'الم ياتكم نبوا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم'),
(5205, 64, 6, 'ذٰلِكَ بِاَنَّهُ كَانَتْ تَأْت۪يهِمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَقَالُٓوا اَبَشَرٌ يَهْدُونَنَاۘ  فَكَفَرُوا وَتَوَلَّوْا وَاسْتَغْنَى اللّٰهُۜ  وَاللّٰهُ غَنِيٌّ حَم۪يدٌ', 'Zalike bi ennehu kanet te\'tihim rusuluhum bil beyyinati fe kalu e beşerun yehdunena fe keferu ve tevellev vestagnallah, vallahu ganiyyun hamid.', 'İşte bu,  resulleri kendilerine açık kanıt içeren bilgilerle geldiklerinde: \"Bir beşer mi bizi doğru yola iletecek?\" diyerek,  kabul etmeyerek yüz çevirmelerindendir. Allah\'ın onların inanmalarına ihtiyacı yoktur. Allah,  Hiçbir Şeye Muhtaç Olmayan\'dır,  Övgüye Değer Yegane Varlık\'tır.', 'ذلك بانه كانت تاتيهم رسلهم بالبينت فقالوا ابشر يهدوننا فكفروا وتولوا واستغني الله والله غني حميد');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(5206, 64, 7, 'زَعَمَ الَّذ۪ينَ كَفَرُٓوا اَنْ لَنْ يُبْعَثُواۜ  قُلْ بَلٰى وَرَبّ۪ي لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْۜ وَذٰلِكَ عَلَى اللّٰهِ يَس۪يرٌ', 'Zeamellezine keferu en len yub\'asu, kul bela ve rabbi le tub\'asunne summe le tunebbeunne bima amiltum, ve zalike alallahi yesir.', 'Kafirler kesinlikle tekrar diriltilmeyeceklerini iddia ettiler. De ki: \"Rabb\'ime ant olsun ki kesinlikle diriltileceksiniz. Sonra yaptıklarınızın tamamı size haber verilecektir. Ve bu,  Allah için çok kolaydır.', 'زعم الذين كفروا ان لن يبعثوا قل بلي وربي لتبعثن ثم لتنبون بما عملتم وذلك علي الله يسير'),
(5207, 64, 8, 'فَاٰمِنُوا بِاللّٰهِ وَرَسُولِه۪ وَالنُّورِ الَّـذ۪ٓي اَنْزَلْنَاۜ  وَاللّٰهُ بِمَا تَعْمَلُونَ خَب۪يرٌ', 'Fe amınu billahi ve resulihi ven nurillezi enzelna, vallahu bima ta\'melune habir.', 'O halde,  Allah\'a,  Resul\'üne ve indirdiğimiz nura[1] inanın. Allah,  yaptıklarınızdan haberdardır.', 'فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير'),
(5208, 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ ذٰلِكَ يَوْمُ التَّغَابُنِۜ وَمَنْ يُؤْمِنْ بِاللّٰهِ وَيَعْمَلْ صَالِحاً يُكَفِّرْ عَنْهُ سَيِّـَٔاتِه۪ وَيُدْخِلْهُ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ ذٰلِكَ الْفَوْزُ الْعَظ۪يمُ', 'Yevme yecmeukum li yevmil cem\'i zalike yevmut tegabun, ve men yu\'min billahi ve ya\'mel salihan yukeffir anhu seyyiatihi ve yudhılhu cennatin tecri min tahtihel enharu halidine fiha ebeda, zalikel fevzul azim.', 'Toplanma günü için sizi bir araya toplayacağı gün,  işte o gün aldanma[1] günüdür. Kim Allah\'a iman eder ve salihatı[2] yaparsa,  Allah onun kötülüklerini örter ve onu içinde kesintisiz olarak,  sürekli kalacağı,  içinden nehirler akan Cennetlere koyar. İşte bu,  büyük kurtuluştur.', 'يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يومن بالله ويعمل صلحا يكفر عنه سياته ويدخله جنت تجري من تحتها الانهر خلدين فيها ابدا ذلك الفوز العظيم'),
(5209, 64, 10, 'وَالَّذ۪ينَ كَفَرُوا وَكَذَّبُوا بِاٰيَاتِنَٓا اُو۬لٰٓئِكَ اَصْحَابُ النَّارِ خَالِد۪ينَ ف۪يهَاۜ وَبِئْسَ الْمَص۪يرُ۟', 'Vellezine keferu ve kezzebu bi ayatina ulaike ashabun nari halidine fiha ve bi\'sel masir.', 'Kafirlik eden ve ayetlerimizi yalanlayanlar; işte onlar,  ateş halkıdırlar ve orada sürekli kalacak olanlardır. O,  ne kötü bir varış yeridir.', 'والذين كفروا وكذبوا بايتنا اوليك اصحب النار خلدين فيها وبيس المصير'),
(5210, 64, 11, 'مَٓا اَصَابَ مِنْ مُص۪يبَةٍ اِلَّا بِاِذْنِ اللّٰهِۜ وَمَنْ يُؤْمِنْ بِاللّٰهِ يَهْدِ قَلْبَهُۜ وَاللّٰهُ بِكُلِّ شَيْءٍ عَل۪يمٌ', 'Ma esabe min musibetin illa bi iznillah, ve men yu\'min billahi yehdi kalbeh, vallahu bikulli şey\'in alim.', 'Allah\'ın izni[1] dışında hiçbir musibet isabet etmez. Kim Allah\'a iman ederse,  Allah,  onun kalbini doğruya yöneltir. Allah,  Her Şeyi En İyi Bilen\'dir.', 'ما اصاب من مصيبة الا باذن الله ومن يومن بالله يهد قلبه والله بكل شي عليم'),
(5211, 64, 12, 'وَاَط۪يعُوا اللّٰهَ وَاَط۪يعُوا الرَّسُولَۚ فَاِنْ تَوَلَّيْتُمْ فَاِنَّمَا عَلٰى رَسُولِنَا الْبَلَاغُ الْمُب۪ينُ', 'Ve etiullahe ve etiur resul, fe in tevelleytum fe innema ala resulinel belagul mubin.', 'Allah\'a itaat edin,  Resul\'e itaat edin.[1] Eğer yüz çevirirseniz,  bilin ki Resul\'ümüze düşen yalnızca açıkça tebliğ etmektir.[2]', 'واطيعوا الله واطيعوا الرسول فان توليتم فانما علي رسولنا البلغ المبين'),
(5212, 64, 13, 'اَللّٰهُ لَٓا اِلٰهَ اِلَّا هُوَۜ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', 'Allahu la ilahe illa huve, ve alallahi fel yetevekkelil mu\'minun.', 'Allah! Kendisinden başka ilah olmayandır. İman edenler,  yalnızca Allah\'a tevekkül[1] etsinler.', 'الله لا اله الا هو وعلي الله فليتوكل المومنون'),
(5213, 64, 14, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُٓوا اِنَّ مِنْ اَزْوَاجِكُمْ وَاَوْلَادِكُمْ عَدُواًّ لَكُمْ فَاحْذَرُوهُمْۚ وَاِنْ تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا فَاِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'Ya eyhuhellezine amenu inne min ezvacikum ve evladikum aduvven lekum fahzeruhum, ve in ta\'fu ve tasfehu ve tagfiru fe innallahe gafurun rahim.', 'Ey iman edenler: Doğrusu,  eşlerinizden ve çocuklarınızdan size düşmanlık edenler olabilir. Onlara karşı dikkatli olun. Eğer affeder,  kusurlarını görmezden gelirseniz ve bağışlarsanız,  bilin ki kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها الذين امنوا ان من ازوجكم واولدكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم'),
(5214, 64, 15, 'اِنَّـمَٓا اَمْوَالُكُمْ وَاَوْلَادُكُمْ فِتْنَةٌۜ وَاللّٰهُ عِنْدَهُٓ اَجْرٌ عَظ۪يمٌ', 'İnnema emvalukum ve evladukum fitneh, vallahu indehu ecrun azim.', 'Mallarınız ve çocuklarınız yalnızca bir fitnedir.[1] Büyük ödül,  Allah\'ın yanındadır.', 'انما امولكم واولدكم فتنة والله عنده اجر عظيم'),
(5215, 64, 16, 'فَاتَّقُوا اللّٰهَ مَا اسْتَطَعْتُمْ وَاسْمَعُوا وَاَط۪يعُوا وَاَنْفِقُوا خَيْراً لِاَنْفُسِكُمْۜ وَمَنْ يُوقَ شُحَّ نَفْسِه۪ فَاُو۬لٰٓئِكَ هُمُ الْمُفْلِحُونَ', 'Fettekullahe mesteta\'tum vesmeu ve etiu ve enfiku hayren li enfusikum, ve men yuka şuhha nefsihi fe ulaike humul muflihun.', 'Gücünüz yettiğince Allah karşı takva[1] sahibi olun. Dinleyin ve itaat edin. Kendi iyiliğiniz için infak edin.[2] Kim benliğinin cimriliğinden korunursa,  işte onlar kurtuluşa erenlerdir.', 'فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاوليك هم المفلحون'),
(5216, 64, 17, 'اِنْ تُقْرِضُوا اللّٰهَ قَرْضاً حَسَناً يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْۜ وَاللّٰهُ شَكُورٌ حَل۪يمٌۙ', 'İn tukridullahe kardan hasenen yudaıfhu lekum ve yagfir lekum, vallahu şekurun halim.', 'Eğer Allah\'a güzel bir ödünç verirseniz[1],  onu size kat kat fazlasıyla geri öder ve sizi bağışlar. Allah; Çok Şükreden\'dir[2],  Çok Hoşgörülü\'dür.', 'ان تقرضوا الله قرضا حسنا يضعفه لكم ويغفر لكم والله شكور حليم'),
(5217, 64, 18, 'عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَز۪يزُ الْحَك۪يمُ', 'Alimul gaybi veş şehadetil azizul hakim.', 'Görünmeyen ve görünen her şeyi bilendir. Mutlak Üstün Olan\'dır,  En İyi Hüküm Veren\'dir.', 'علم الغيب والشهدة العزيز الحكيم'),
(5218, 65, 1, 'يَٓا اَيُّهَا النَّبِيُّ اِذَا طَلَّقْتُمُ النِّسَٓاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَاَحْصُوا الْعِدَّةَۚ وَاتَّقُوا اللّٰهَ رَبَّكُمْۚ لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ اِلَّٓا اَنْ يَأْت۪ينَ بِفَاحِشَةٍ مُبَيِّنَةٍۜ وَتِلْكَ حُدُودُ اللّٰهِۜ وَمَنْ يَتَعَدَّ حُدُودَ اللّٰهِ فَقَدْ ظَلَمَ نَفْسَهُۜ  لَا تَدْر۪ي لَعَلَّ اللّٰهَ يُحْدِثُ بَعْدَ ذٰلِكَ اَمْراً', 'Ya eyyuhen nebiyyu iza tallaktumun nisae fe tallikuhunne li iddetihinne ve ahsul iddeh, vettekullahe rabbekum, la tuhricuhunne min buyutihinne ve la yahrucne illa en ye\'tine bi fahişetin mubeyyineh, ve tilke hududullah, ve men yeteadde hududallahi fe kad zaleme nefseh, la tedri leallallahe yuhdısu ba\'de zalike emra.', 'Ey Nebi! Kadınları boşayacağınız zaman,  iddet[1] sürelerini gözeterek boşayın ve iddetlerini sayın. Rabb\'iniz Allah\'a karşı takva sahibi olun. Açıkça fahşa[2] yapmadıkça onları evlerinden çıkarmayın; onlar da çıkmasınlar. Bunlar,  Allah\'ın sınırlarıdır. Kim Allah\'ın sınırlarını aşarsa,  kesinlikle kendisine haksızlık etmiş olur. Bilemezsin,  olur ki Allah bundan sonra yeni bir hadis[3] ortaya çıkarır.', 'يايها النبي اذا طلقتم النسا فطلقوهن لعدتهن واحصوا العدة واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفحشة مبينة وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا'),
(5219, 65, 2, 'فَاِذَا بَلَغْنَ اَجَلَهُنَّ فَاَمْسِكُوهُنَّ بِمَعْرُوفٍ اَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَاَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ وَاَق۪يمُوا الشَّهَادَةَ لِلّٰهِۜ  ذٰلِكُمْ يُوعَظُ بِه۪ مَنْ كَانَ يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۜ وَمَنْ يَتَّقِ اللّٰهَ يَجْعَلْ لَهُ مَخْرَجاًۙ', 'Fe iza belagne ecelehunne fe emsikuhunne bi ma\'rufin evfarikuhunne bi ma\'rufin ve eşhidu zevey adlin minkum ve ekimuş şehadete lillah, zalikum yuazu bihi men kane yu\'minu billahi vel yevmil ahir, ve men yettekıllahe yec\'al lehu mahreca.', 'Bekleme süreleri tamamlandığında onları ma\'rufa[1] uygun olarak tutun veya ma\'rufa uygun olarak onlardan ayrılın. Ve sizden adalet sahibi iki kişi tanık olsun. Tanıklığı,  Allah için yerine getirin. İşte Allah\'a ve Ahiret Günü\'ne inananlara verilen öğüt budur. Kim Allah için takva[2] sahibi olursa,  Allah,  ona bir çıkış yolu nasip eder.', 'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهدة لله ذلكم يوعظ به من كان يومن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا'),
(5220, 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُۜ وَمَنْ يَتَوَكَّلْ عَلَى اللّٰهِ فَهُوَ حَسْبُهُۜ اِنَّ اللّٰهَ بَالِغُ اَمْرِه۪ۜ قَدْ جَعَلَ اللّٰهُ لِكُلِّ شَيْءٍ قَدْراً', 'Ve yerzukhu min haysu la yahtesib, ve men yetevekkel alallahi fe huve hasbuh, innallahe baligu emrih, kad cealallahu li kulli şey\'in kadra.', 'Ve Allah,  ona ummadığı yerden rızık verir. Kim Allah\'a tevekkül[1] ederse,  O,  ona yeter. Kuşkusuz Allah,  buyruğunu yerine getirir. Allah,  her şey için bir ölçü belirlemiştir.', 'ويرزقه من حيث لا يحتسب ومن يتوكل علي الله فهو حسبه ان الله بلغ امره قد جعل الله لكل شي قدرا'),
(5221, 65, 4, 'وَالّٰٓئ۪ يَـئِسْنَ مِنَ الْمَح۪يضِ مِنْ نِسَٓائِكُمْ اِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلٰثَةُ اَشْهُرٍۙ وَالّٰٓئ۪ لَمْ يَحِضْنَۜ  وَاُو۬لَاتُ الْاَحْمَالِ اَجَلُهُنَّ اَنْ يَضَعْنَ حَمْلَهُنَّۜ  وَمَنْ يَتَّقِ اللّٰهَ يَجْعَلْ لَهُ مِنْ اَمْرِه۪ يُسْراً', 'Vellai yeisne minel mahidı min nisaikum inirtebtum fe iddetuhunne selasetu eşhurin vellai lem yahıdn, ve ulatul ahmali eceluhunne en yada\'ne hamlehunn, ve men yettekıllahe yec\'al lehu min emrihi yusra.', 'Kadınlarınızdan adet görmekten kesilenler ve adet görmeyenler hakkında[1] kuşku duyarsanız,  o zaman onların iddetleri[2] üç aydır. Hamile kadınların bekleme süresi ise doğum yapıncaya kadardır. Kim Allah için takva sahibi olursa,  Allah ona işinde kolaylık sağlar.', 'والي ييسن من المحيض من نسايكم ان ارتبتم فعدتهن ثلثة اشهر والي لم يحضن واولت الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا'),
(5222, 65, 5, 'ذٰلِكَ اَمْرُ اللّٰهِ اَنْزَلَهُٓ اِلَيْكُمْۜ وَمَنْ يَتَّقِ اللّٰهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِه۪ وَيُعْظِمْ لَـهُٓ اَجْراً', 'Zalike emrullahi enzelehu ileykum, ve men yettekıllahe yukeffir anhu seyyiatihi ve yu\'zım lehu ecra.', 'İşte bu,  Allah\'ın size indirdiği buyruğudur. Kim Allah için takva sahibi olursa,  onun kötülüklerine kafir[1] olur ve ona yüce,  üstün bir ödül verir.', 'ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سياته ويعظم له اجرا'),
(5223, 65, 6, 'اَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ وَلَا تُضَٓارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّۜ وَاِنْ كُنَّ اُو۬لَاتِ حَمْلٍ فَاَنْفِقُوا عَلَيْهِنَّ حَتّٰى يَضَعْنَ حَمْلَهُنَّۚ فَاِنْ اَرْضَعْنَ لَكُمْ فَاٰتُوهُنَّ اُجُورَهُنَّۚ وَأْتَمِرُوا بَيْنَكُمْ بِمَعْرُوفٍۚ وَاِنْ تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُٓ  اُخْرٰىۜ', 'Eskinu hunne min haysu sekentum min vucdikum ve la tudarruhunne li tudayyiku aleyhinn, ve in kunne ulati hamlin fe enfiku aleyhinne hatta yeda\'ne hamle hunn, fe in erda\'ne lekum fe atuhunne ucure hunn, ve\'temiru beynekum bi ma\'ruf, ve in teasertum fe se turdıu lehu uhra.', 'Oturduğunuz yerin bir bölümünde gücünüz yettiğince onları oturtun. Onları sıkıntıya sokmak için,  zarar verecek bir şey yapmayın. Eğer hamile iseler,  doğum yapıncaya kadar onlara karşılıksız yardımda bulunun. Sonra emzirirlerse ücretlerini verin. Aranızda konuşarak ma\'ruf bir şekilde anlaşın. Eğer bir zorlukla karşılaşırsanız o zaman emzirme işini başkasına yaptırın.', 'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولت حمل فانفقوا عليهن حتي يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخري'),
(5224, 65, 7, 'لِيُنْفِقْ ذُوسَعَةٍ مِنْ سَعَتِه۪ۜ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّٓا اٰتٰيهُ اللّٰهُۜ  لَا يُكَلِّفُ اللّٰهُ نَفْساً اِلَّا مَٓا اٰتٰيهَاۜ سَيَجْعَلُ اللّٰهُ بَعْدَ عُسْرٍ يُسْراً۟', 'Li yunfık zu seatin min seatih, ve men kudire aleyhi rızkuhu fel yunfik mimma atahullah, la yukellifullahu nefsen illa ma ataha, seyec\'alullahu ba\'de usrin yusra.', 'Varlık sahibi olanlar,  varlıklarına göre karşılıksız yardım etsinler. Durumu müsait olmayan da Allah ne verdiyse ondan versin. Allah,  bir kimseyi,  kendisine verdiğinden fazlasıyla sorumlu tutmaz. Allah,  zorluğun ardından bir kolaylık verecektir.', 'لينفق ذو سعة من سعته ومن قدر عليه رزقه فلينفق مما اتيه الله لا يكلف الله نفسا الا ما اتيها سيجعل الله بعد عسر يسرا'),
(5225, 65, 8, 'وَكَاَيِّنْ مِنْ قَرْيَةٍ عَتَتْ عَنْ اَمْرِ رَبِّهَا وَرُسُلِه۪ فَحَاسَبْنَاهَا حِسَاباً شَد۪يداً وَعَذَّبْنَاهَا عَذَاباً نُكْراً', 'Ve keeyyin min karyetin atet an emri rabbiha ve rusulihi fe hasebnaha hisaben şediden ve azzebnaha azaben nukra.', 'Nice kasaba halkı,  Rabb\'lerinin buyruğuna ve O\'nun Resullerine başkaldırdılar da Biz de onları şiddetli bir hesaba çektik ve onları korkunç bir azapla cezalandırdık.', 'وكاين من قرية عتت عن امر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا'),
(5226, 65, 9, 'فَذَاقَتْ وَبَالَ اَمْرِهَا وَكَانَ عَاقِبَةُ اَمْرِهَا خُسْراً', 'Fe zakat ve bale emriha ve kane akıbetu emriha husra.', 'Böylece işinin vebalini tattı. İşinin sonu da hüsran oldu.', 'فذاقت وبال امرها وكان عقبة امرها خسرا'),
(5227, 65, 10, 'اَعَدَّ اللّٰهُ لَهُمْ عَذَاباً شَد۪يداً فَاتَّقُوا اللّٰهَ يَٓا اُو۬لِي الْاَلْبَابِۚۛ اَلَّذ۪ينَ اٰمَنُواۚۛ قَدْ اَنْزَلَ اللّٰهُ اِلَيْكُمْ ذِكْراًۙ', 'E addallahu lehum azaben şediden fettekullahe ya ulil elbab, ellezine amenu, kad enzelallahu ileykum zikra.', 'Allah,  onlara şiddetli bir azap hazırladı. Ey iman eden sağlıklı düşünen akıl sahipleri,  Allah için takva sahibi olun. Allah,  size zikri[1] indirmiştir.', 'اعد الله لهم عذابا شديدا فاتقوا الله ياولي الالبب الذين امنوا قد انزل الله اليكم ذكرا'),
(5228, 65, 11, 'رَسُولاً يَتْلُوا عَلَيْكُمْ اٰيَاتِ اللّٰهِ مُبَيِّنَاتٍ لِيُخْرِجَ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنَ الظُّلُمَاتِ اِلَى النُّورِۜ  وَمَنْ يُؤْمِنْ بِاللّٰهِ وَيَعْمَلْ صَالِحاً يُدْخِلْهُ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ قَدْ اَحْسَنَ اللّٰهُ لَهُ رِزْقاً', 'Resulen yetlu aleykum ayatillahi mubeyyinatin li yuhricellezine amenu ve amilus salihati minez zulumati ilen nur, ve men yu\'min billahi ve ya\'mel salihan yudhilhu cennatin tecri min tahtihel enharu halidine fiha ebeda, kad ahsenallahu lehu rızka.', 'İman eden ve salihatı[1] yapan kimseleri,  karanlıklardan aydınlığa çıkarmak için,  Allah\'ın apaçık olan ayetlerini size okuyan bir Resul gönderdi. Kim,  Allah\'a iman eder ve salih[1] olanı yaparsa,  Allah onu,  içinden ırmaklar akan ve içinde kesintisiz olarak sürekli kalacakları Cennetlere koyar. Allah,  onu en iyi şekilde rızıklandıracaktır.', 'رسولا يتلوا عليكم ايت الله مبينت ليخرج الذين امنوا وعملوا الصلحت من الظلمت الي النور ومن يومن بالله ويعمل صلحا يدخله جنت تجري من تحتها الانهر خلدين فيها ابدا قد احسن الله له رزقا'),
(5229, 65, 12, 'اَللّٰهُ الَّذ۪ي خَلَقَ سَبْعَ سَمٰوَاتٍ وَمِنَ الْاَرْضِ مِثْلَهُنَّۜ يَتَنَزَّلُ الْاَمْرُ بَيْنَهُنَّ لِتَعْلَمُٓوا اَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌۙ وَاَنَّ اللّٰهَ قَدْ اَحَاطَ بِكُلِّ شَيْءٍ عِلْماً', 'Allahullezi halaka seb\'a semavatin ve minel ardı mislehunn, yetenezzelul emru beynehunne li ta\'lemu ennallahe ala kulli şey\'in kadirun ve ennallahe kad ehata bi kulli şey\'in ilma.', 'Allah,  yedi göğü ve benzer şekilde yeryüzünü yaratandır. Allah\'ın her şeye gücünün yettiğini,  Allah\'ın bilgisinin her şeyi kuşattığını bilesiniz diye,  buyruğu onlar arasında iner durur.[1]', 'الله الذي خلق سبع سموت ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله علي كل شي قدير وان الله قد احاط بكل شي علما'),
(5230, 66, 1, 'يَٓا اَيُّهَا النَّبِيُّ  لِمَ تُحَرِّمُ مَٓا اَحَلَّ اللّٰهُ لَكَۚ تَبْتَغ۪ي مَرْضَاتَ اَزْوَاجِكَۜ وَاللّٰهُ غَفُورٌ رَح۪يمٌ', 'Ya eyyuhen nebiyyu lime tuharrimu ma ehallallahu lek, tebtegi merdate ezvacik, vallahu gafurun rahim.', 'Ey Nebi! Eşlerinin hoşnutluğunu gözeterek,  Allah\'ın helal kıldığı şeyi niçin kendine haram kılıyorsun?[1] Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'يايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازوجك والله غفور رحيم'),
(5231, 66, 2, 'قَدْ فَرَضَ اللّٰهُ لَـكُمْ تَحِلَّةَ اَيْمَانِكُمْۚ وَاللّٰهُ مَوْلٰيكُمْۚ وَهُوَ الْعَل۪يمُ الْحَك۪يمُ', 'Kad faradallahu lekum tehillete eymanikum, vallahu mevlakum, ve huvel alimul hakim.', 'Allah,  yeminlerinizi,  kefaretini ödeyerek çözmeyi size farz[1] kılmıştır. Allah,  sizin mevlanızdır.[2] O; Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'قد فرض الله لكم تحلة ايمنكم والله موليكم وهو العليم الحكيم'),
(5232, 66, 3, 'وَاِذْ اَسَرَّ النَّبِيُّ اِلٰى بَعْضِ اَزْوَاجِه۪ حَد۪يثاًۚ فَلَمَّا نَبَّاَتْ بِه۪ وَاَظْهَرَهُ اللّٰهُ عَلَيْهِ عَرَّفَ بَعْضَهُ وَاَعْرَضَ عَنْ بَعْضٍۚ فَلَمَّا نَبَّاَهَا بِه۪ قَالَتْ مَنْ اَنْبَاَكَ هٰذَاۜ  قَالَ نَبَّاَنِيَ الْعَل۪يمُ الْخَب۪يرُ', 'Ve iz eserren nebiyyu ila ba\'dı ezvacihi hadisa, fe lemma nebbeet bihi ve azherehullahu aleyhi arrefe ba\'dahu ve a\'rada an ba\'d, fe lemma nebbeeha bihi kalet men enbeeke haza, kale nebbeeniyel alimul habir.', 'Hani Nebi,  eşlerinden birine aralarında kalmak üzere bir hadis[1] söylemişti. Fakat o eşi,  söylenen şeyi başkasına söyleyince,  Allah Nebi\'ye bunu izhar[2] etti. Nebi de bir kısmını açıklamış ve bir kısmından da vazgeçmişti. Eşine,  bundan haberdar olduğunu söyleyince,  eşi: \"Bunu sana kim haber verdi?\" deyince,  Nebi: \"Bana,  Her Şeyi Bilen,  Her Şeyden Haberdar Olan bildirdi.\" demişti.', 'واذ اسر النبي الي بعض ازوجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير'),
(5233, 66, 4, 'اِنْ تَتُوبَٓا اِلَى اللّٰهِ فَقَدْ صَغَتْ قُلُوبُكُمَاۚ وَاِنْ تَظَاهَرَا عَلَيْهِ فَاِنَّ اللّٰهَ هُوَ مَوْلٰيهُ وَجِبْر۪يلُ وَصَالِـحُ الْمُؤْمِن۪ينَۚ وَالْمَلٰٓئِكَةُ بَعْدَ ذٰلِكَ ظَه۪يرٌ', 'İn tetuba ilallahi fe kad sagat kulubukuma, ve in tezahera aleyhi fe innallahe huve mevlahu ve cibrilu ve salihul mu\'minin, vel melaiketu ba\'de zalike zahir.', 'Siz ikiniz Allah\'a tevbe etmelisiniz. Çünkü ikinizin de kalbi yanlış düşüncelere yöneldi. Eğer ona karşı dayanışmaya girerseniz hiç kuşkusuz Allah ona mevladır.[1] Cibril[2] ve iman edenlerin salihleri[3] ve bunlardan başka melekler de onun yanındadırlar.', 'ان تتوبا الي الله فقد صغت قلوبكما وان تظهرا عليه فان الله هو موليه وجبريل وصلح المومنين والمليكة بعد ذلك ظهير'),
(5234, 66, 5, 'عَسٰى رَبُّهُٓ اِنْ طَلَّقَكُنَّ اَنْ يُبْدِلَهُٓ  اَزْوَاجاً خَيْراً مِنْكُنَّ مُسْلِمَاتٍ مُؤْمِنَاتٍ قَانِتَاتٍ تَٓائِبَاتٍ عَابِدَاتٍ سَٓائِحَاتٍ ثَيِّبَاتٍ وَاَبْكَاراً', 'Asa rabbuhu in tallakakunne en yubdilehu ezvacen hayren min kunne muslimatin mu\'minatin kanitatin taibatin abidatin saihatin seyyibatin ve ebkara.', 'Eğer o sizi boşarsa,  Rabb\'inin ona sizden daha hayırlı olan; Allah\'a teslim olan,  inanan,  saygıda kusur etmeyen,  tevbe eden,  kulluk eden,  seyahat eden[1] dul ve bakire eşler vermesi umulur.', 'عسي ربه ان طلقكن ان يبدله ازوجا خيرا منكن مسلمت مومنت قنتت تيبت عبدت سيحت ثيبت وابكارا'),
(5235, 66, 6, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا قُٓوا اَنْفُسَكُمْ وَاَهْل۪يكُمْ نَاراً وَقُودُهَا النَّاسُ وَالْحِجَارَةُ عَلَيْهَا مَلٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَا يَعْصُونَ اللّٰهَ مَٓا اَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'Ya eyyuhellezine amenu ku enfusekum ve ehlikum naren vakuduhan nasu vel hicaretu aleyha melaiketun gılazun şidadun la ya\'sunallahe ma emerehum ve yef\'alune ma yu\'merune.', 'Ey iman edenler! Kendinizi ve yakınlarınızı,  yakıtı taşlar ve insanlar olan ateşten koruyun. Onun üzerinde,  Allah\'ın buyruklarına karşı gelmeyen ve buyrulan şeyi yapan çok güçlü ve acımasız melekler[1] vardır.', 'يايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجارة عليها مليكة غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يومرون'),
(5236, 66, 7, 'يَٓا اَيُّهَا الَّذ۪ينَ كَفَرُوا لَا تَعْتَذِرُوا الْيَوْمَۜ  اِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُونَ۟', 'Ya eyyuhellezine keferu la ta\'tezirul yevm, innema tuczevne ma kuntum ta\'melun.', 'Ey Kafirler! Bugün özür dilemeyin! Siz,  yalnızca yaptıklarınızın karşılığını görmektesiniz.', 'يايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون'),
(5237, 66, 8, 'يَٓا اَيُّهَا الَّذ۪ينَ اٰمَنُوا تُوبُٓوا اِلَى اللّٰهِ تَوْبَةً نَصُوحاًۜ عَسٰى رَبُّكُمْ اَنْ يُكَفِّرَ عَنْكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۙ يَوْمَ لَا يُخْزِي اللّٰهُ النَّبِيَّ وَالَّذ۪ينَ اٰمَنُوا مَعَهُۚ نُورُهُمْ يَسْعٰى بَيْنَ اَيْد۪يهِمْ وَبِاَيْمَانِهِمْ يَقُولُونَ رَبَّـنَٓا اَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَاۚ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌ', 'Ya eyyuhellezine amenu tubu ilallahi tevbeten nasuha, asa rabbukum en yukeffire ankum seyyiatikum ve yudhilekum cennatin tecri min tahtihel enharu, yevme la yuhzillahun nebiyye vellezine amenu meah, nuruhum yes\'a beyne eydihim ve bi eymanihim yekulune rabbena etmim lena nurena vagfir lena, inneke ala kulli şey\'in kadir.', 'Ey iman edenler! Öğüt veren bir tevbe[1] ile Allah\'a tevbe edin. Umulur ki Rabb\'iniz,  kötülüklerinizi örter ve sizi altından nehirler akan Cennetlere koyar. O gün Allah,  nebileri ve onlarla beraber olanları asla üzmeyecektir. Onların ışıkları önlerini ve yanlarını aydınlatır. \"Rabb\'imiz,  bizim ışığımızı tamamla ve bizi bağışla. Kuşkusuz Sen,  Her Şeye Güç Yetiren\'sin.\" derler.', 'يايها الذين امنوا توبوا الي الله توبة نصوحا عسي ربكم ان يكفر عنكم سياتكم ويدخلكم جنت تجري من تحتها الانهر يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعي بين ايديهم وبايمنهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك علي كل شي قدير'),
(5238, 66, 9, 'يَٓا اَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِق۪ينَ وَاغْلُظْ عَلَيْهِمْۜ وَمَأْوٰيهُمْ جَهَنَّمُۜ وَبِئْسَ الْمَص۪يرُ', 'Ya eyyuhen nebiyyu cahidil kuffare vel munafikine vagluz aleyhim, ve me\'vahum cehennem, ve bi\'sel masir.', 'Ey Nebi! Kafirlere ve münafıklara karşı mücadele et. Ve onlara kararlılık göster[1]. Onların barınacağı yer Cehennem\'dir. O ne kötü dönüş yeridir.', 'يايها النبي جهد الكفار والمنفقين واغلظ عليهم وماويهم جهنم وبيس المصير'),
(5239, 66, 10, 'ضَرَبَ اللّٰهُ مَثَلاً لِلَّذ۪ينَ كَفَرُوا امْرَاَتَ نُوحٍ وَامْرَاَتَ لُوطٍۜ  كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ اللّٰهِ شَيْـٔاً وَق۪يلَ ادْخُلَا النَّارَ مَعَ الدَّاخِل۪ينَ', 'Dareballahu meselen lillezine keferumreete nuhın vemreete lut, kaneta tahte abdeyni min ibadina salihayni fe hanetahuma fe lem yugniya anhuma minallahi şey\'en ve kiledhulen nare mead dahılin.', 'Allah,  Kafirlere Nuh\'un ve Lut\'un hanımlarını örnek verdi. İkisi de iyi kullarımızdan iki kulumuzla evliydiler. Fakat onlara hainlik ettiler. Bu yüzden Allah\'tan gelen şeye karşı,  kocalarının onlara bir faydası olmadı. Onlara: \"İkiniz de girenlerle birlikte ateşe girin.\" denildi.', 'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من الله شيا وقيل ادخلا النار مع الدخلين'),
(5240, 66, 11, 'وَضَرَبَ اللّٰهُ مَثَلاً لِلَّذ۪ينَ اٰمَنُوا امْرَاَتَ فِرْعَوْنَۢ اِذْ قَالَتْ رَبِّ ابْنِ ل۪ي عِنْدَكَ بَيْتاً فِي الْجَنَّةِ وَنَجِّن۪ي مِنْ فِرْعَوْنَ وَعَمَلِه۪ وَنَجِّن۪ي مِنَ الْقَوْمِ الظَّالِم۪ينَۙ', 'Ve dareballahu meselen lillezine amenumreete fir\'avn, iz kalet rabbibni li indeke beyten fil cenneti ve neccini min fir\'avne ve amelihi ve neccini minel kavmiz zalimin.', 'Allah,  inanan kimselere,  Firavun\'un hanımını örnek verdi. Hani o,  \"Rabb\'im! Katında,  benim için Cennet\'te bir ev yap. Beni Firavun ve yaptıklarından kurtar. Ve zalimler topluluğundan beni kurtar.\" demişti.', 'وضرب الله مثلا للذين امنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظلمين'),
(5241, 66, 12, 'وَمَرْيَمَ ابْنَتَ عِمْرٰنَ الَّت۪ٓي اَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا ف۪يهِ مِنْ رُوحِنَا وَصَدَّقَتْ بِكَلِمَاتِ رَبِّهَا وَكُتُبِه۪ وَكَانَتْ مِنَ الْقَانِت۪ينَ', 'Ve meryemebnete ımranelleti ahsanet ferceha fe nefahna fihi min ruhına ve saddekat bi kelimati rabbiha ve kutubihi ve kanet minel kanitin.', 'İmran kızı Meryem; ırzını korumuştu. Ona ruhumuzdan üfledik. O,  Rabb\'inin kelimelerini[1] ve kitaplarını[2] tasdik etti ve gönülden saygı gösterenlerden oldu.', 'ومريم ابنت عمرن التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من القنتين'),
(5242, 67, 1, 'تَبَارَكَ الَّذ۪ي بِيَدِهِ الْمُلْكُۘ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَد۪يرٌۙ', 'Tebarekellezi bi yedihil mulku ve huve ala kulli şey\'in kadir.', 'Mutlak egemenliği elinde bulunduran Allah,  ne kutludur! O,  Her Şeye Gücü Yeten\'dir.', 'تبرك الذي بيده الملك وهو علي كل شي قدير'),
(5243, 67, 2, 'اَلَّذ۪ي خَلَقَ الْمَوْتَ وَالْحَيٰوةَ لِيَبْلُوَكُمْ اَيُّكُمْ اَحْسَنُ عَمَلاًۜ وَهُوَ الْعَز۪يزُ الْغَفُورُۙ', 'Ellezi halakal mevte vel hayate li yebluvekum eyyukum ahsenu amela, ve huvel azi zul gafur.', 'Hanginizin daha iyi iş yapacağını sınamak için ölümü ve hayatı yaratan O\'dur. O,  Mutlak Üstün Olan\'dır,  Çok Bağışlayıcı\'dır.', 'الذي خلق الموت والحيوة ليبلوكم ايكم احسن عملا وهو العزيز الغفور'),
(5244, 67, 3, 'اَلَّذ۪ي خَلَقَ سَبْعَ سَمٰوَاتٍ طِبَاقاًۜ مَا تَرٰى ف۪ي خَلْقِ الرَّحْمٰنِ مِنْ تَفَاوُتٍۜ فَارْجِعِ الْبَصَرَۙ هَلْ تَرٰى مِنْ فُطُورٍ', 'Ellezi halaka seb\'a semavatin tibaka, ma tera fi halkır rahmani min tefavut, ferciıl basara hel tera min futur.', 'Gökleri yedi tabaka halinde yaratan O\'dur. Rahman\'ın yaratmasında bir düzensizlik göremezsin. Bak bakalım,  işleyiş yasalarında bir uygunsuzluk görebilecek misin?', 'الذي خلق سبع سموت طباقا ما تري في خلق الرحمن من تفوت فارجع البصر هل تري من فطور'),
(5245, 67, 4, 'ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ اِلَيْكَ الْبَصَرُ خَاسِئاً وَهُوَ حَس۪يرٌ', 'Summerciıl basara kerreteyni yenkalib ileykel basaru hasien ve huve hasir.', 'Sonra,  tekrar tekrar bir daha bak! Gözlerin,  bitkin ve aradığını bulamamış bir halde sana geri döner.', 'ثم ارجع البصر كرتين ينقلب اليك البصر خاسيا وهو حسير'),
(5246, 67, 5, 'وَلَقَدْ زَيَّنَّا السَّمَٓاءَ الدُّنْيَا بِمَصَاب۪يحَ وَجَعَلْنَاهَا رُجُوماً لِلشَّيَاط۪ينِ وَاَعْتَدْنَا لَهُمْ عَذَابَ السَّع۪يرِ', 'Ve lekad zeyyennes semaed dunya bi mesabiha ve cealnaha rucumen liş şeyatini ve a\'tedna lehum azabes sair.', 'Ant olsun ki Biz,  yakın gökyüzünü kandillerle süsledik. Onları,  şeytanlar[1] için asılsız şeyler söyleme malzemesi yaptık. Onlar için ateşin azabını hazırladık.', 'ولقد زينا السما الدنيا بمصبيح وجعلنها رجوما للشيطين واعتدنا لهم عذاب السعير'),
(5247, 67, 6, 'وَلِلَّذ۪ينَ كَفَرُوا بِرَبِّهِمْ عَذَابُ جَهَنَّمَۜ  وَبِئْسَ الْمَص۪يرُ', 'Ve lillezine keferu bi rabbihim azabu cehennem, ve bi\'sel masir.', 'Kafirler için Cehennem azabı vardır. Ve o,  ne kötü varış yeridir.', 'وللذين كفروا بربهم عذاب جهنم وبيس المصير'),
(5248, 67, 7, 'اِذَٓا اُلْقُوا ف۪يهَا سَمِعُوا لَهَا شَه۪يقاً وَهِيَ تَفُورُۙ', 'İza ulku fiha semiu leha şehikan ve hiye tefur.', 'Oraya atıldıklarında,  onun kaynayan korkunç sesini duyarlar', 'اذا القوا فيها سمعوا لها شهيقا وهي تفور'),
(5249, 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِۜ  كُلَّمَٓا اُلْقِيَ ف۪يهَا فَوْجٌ سَاَلَهُمْ خَزَنَتُهَٓا اَلَمْ يَأْتِكُمْ نَذ۪يرٌ', 'Tekadu temeyyezu minel gayz, kullema ulkıye fiha fevcun seelehum hazenetuha e lem ye\'tikum nezir.', 'Neredeyse öfkesinden çatlayacak gibi olur. Oraya her grup atıldığında,  onun bekçileri onlara: \"Size uyarıcı gelmedi mi?\" diye sorar.', 'تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير'),
(5250, 67, 9, 'قَالُوا بَلٰى قَدْ جَٓاءَنَا نَذ۪يرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللّٰهُ مِنْ شَيْءٍۚ اِنْ اَنْتُمْ اِلَّا ف۪ي ضَلَالٍ كَب۪يرٍ', 'Kalu bela kad caena nezirun fe kezzebna ve kulna ma nezzelallahu min şey\'in entum illa fi dalalin kebir.', 'Onlar,  \"Evet,  bize uyarıcı geldi,  fakat biz onu yalanladık. Allah,  hiçbir şey indirmemiştir,  siz büyük bir sapkınlık içindesiniz.\" dedik.', 'قالوا بلي قد جانا نذير فكذبنا وقلنا ما نزل الله من شي ان انتم الا في ضلل كبير'),
(5251, 67, 10, 'وَقَالُوا لَوْ كُنَّا نَسْمَعُ اَوْ نَعْقِلُ مَا كُنَّا ف۪ٓي اَصْحَابِ السَّع۪يرِ', 'Ve kalu lev kunna nesmeu ev na\'kılu ma kunna fi ashabis sair.', '\"Eğer dinlemiş veya düşünmüş olsaydık,  şimdi alevli ateşin halkı içinde olmazdık.\" dediler.', 'وقالوا لو كنا نسمع او نعقل ما كنا في اصحب السعير'),
(5252, 67, 11, 'فَاعْتَرَفُوا بِذَنْبِهِمْۚ فَسُحْقاً لِاَصْحَابِ السَّع۪يرِ', 'Fa\'terefu bi zenbihim, fe suhkan li ashabis sair.', 'Böylece suçlarını itiraf ettiler. Rahmetten uzak olsun Cehennemlikler.', 'فاعترفوا بذنبهم فسحقا لاصحب السعير'),
(5253, 67, 12, 'اِنَّ الَّذ۪ينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَغْفِرَةٌ وَاَجْرٌ كَب۪يرٌ', 'İnnellezine yahşevne rabbehum bil gaybi lehum magfiretun ve ecrun kebir.', 'Rabb\'lerine gizlide[1] içtenlikle saygı duyanlara ise bağışlanma ve büyük ödül vardır.', 'ان الذين يخشون ربهم بالغيب لهم مغفرة واجر كبير'),
(5254, 67, 13, 'وَاَسِرُّوا قَوْلَكُمْ اَوِ اجْهَرُوا بِه۪ۜ  اِنَّهُ عَل۪يمٌ بِذَاتِ الصُّدُورِ', 'Ve esirru kavlekum evicheru bih, innehu alimun bi zatis sudur.', 'Sözünüzü gizleseniz de açığa vursanız da fark etmez; O,  göğüslerde olanı En İyi Bilen\'dir.', 'واسروا قولكم او اجهروا به انه عليم بذات الصدور'),
(5255, 67, 14, 'اَلَا يَعْلَمُ مَنْ خَلَقَۜ وَهُوَ اللَّط۪يفُ الْخَب۪يرُ۟', 'Ela ya\'lemu men halak, ve huvel latiful habir.', 'Yaratan,  yarattığını bilmez mi? O,  Bütün Ayrıntıları Bilen\'dir,  Her Şeyden Haberdar\'dır.', 'الا يعلم من خلق وهو اللطيف الخبير'),
(5256, 67, 15, 'هُوَ الَّذ۪ي جَعَلَ لَكُمُ الْاَرْضَ ذَلُولاً فَامْشُوا ف۪ي مَنَاكِبِهَا وَكُلُوا مِنْ رِزْقِه۪ۜ  وَاِلَيْهِ النُّشُورُ', 'Huvellezi ceale lekumul arda zelulen femşu fi menakibiha ve kulu min rızkıh, ve ileyhin nuşur.', 'Yeryüzünü size boyun eğdiren O\'dur. Artık onun üzerinde dilediğinizce dolaşın ve O\'nun rızkından yiyin. Sonunda dönüş O\'nadır.', 'هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور'),
(5257, 67, 16, 'ءَاَمِنْتُمْ مَنْ فِي السَّمَٓاءِ اَنْ يَخْسِفَ بِكُمُ الْاَرْضَ فَاِذَا هِيَ تَمُورُۙ', 'E emintum men fis semai en yahsife bikumul arda fe iza hiye temur.', 'Gökte Olan\'ın, [1] sizi yerin dibine batırmayacağından emin mi oldunuz? Bir de bakmışsınız yer sarsılıyor!', 'امنتم من في السما ان يخسف بكم الارض فاذا هي تمور'),
(5258, 67, 17, 'اَمْ اَمِنْتُمْ مَنْ فِي السَّمَٓاءِ اَنْ يُرْسِلَ عَلَيْكُمْ حَاصِباًۜ فَسَتَعْلَمُونَ كَيْفَ نَذ۪يرِ', 'Em emintum men fis semai en yursile aleykum hasıba fe se ta\'lemune keyfe nezir.', 'Ya da gökte olanın üzerinize taş yağdırmayacağından emin misiniz? O halde,  uyarımın nasıl olduğunu yakında bileceksiniz.', 'ام امنتم من في السما ان يرسل عليكم حاصبا فستعلمون كيف نذير'),
(5259, 67, 18, 'وَلَقَدْ كَذَّبَ الَّذ۪ينَ مِنْ قَبْلِهِمْ فَكَيْفَ كَانَ نَك۪يرِ', 'Ve lekad kezzebellezine min kablihim fe keyfe kane nekir.', 'Ant olsun ki,  onlardan öncekiler de yalanladılar. İnkarım[1] nasılmış gördüler.', 'ولقد كذب الذين من قبلهم فكيف كان نكير'),
(5260, 67, 19, 'اَوَلَمْ يَرَوْا اِلَى الطَّيْرِ فَوْقَهُمْ صَٓافَّاتٍ وَيَقْبِضْنَۜ مَا يُمْسِكُهُنَّ اِلَّا الرَّحْمٰنُۜ اِنَّهُ بِكُلِّ شَيْءٍ بَص۪يرٌ', 'E ve lem yerev ilet tayri fevkahum saffatin ve yakbıdn, ma yumsikuhunne iller rahman, innehu bi kulli şey\'in basir.', 'Gökyüzünde sıra sıra süzülerek,  kanat çırparak uçanları görmüyorlar mı? Onları havada Rahman\'dan başkası tutmuyor. Kuşkusuz O,  Her Şeyi Gören\'dir.', 'اولم يروا الي الطير فوقهم صفت ويقبضن ما يمسكهن الا الرحمن انه بكل شي بصير'),
(5261, 67, 20, 'اَمَّنْ هٰذَا الَّذ۪ي هُوَ جُنْدٌ لَكُمْ يَنْصُرُكُمْ مِنْ دُونِ الرَّحْمٰنِۜ اِنِ الْكَافِرُونَ اِلَّا ف۪ي غُرُورٍۚ', 'Emmen hazellezi huve cundun lekum yensurukum min dunir rahman, inil kafirune illa fi gurur.', 'Yoksa Rahman\'dan başka,  size yardım edecek[1] ordunuz mu var? Kafirler yalnızca bir aldanış içindedirler.', 'امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكفرون الا في غرور'),
(5262, 67, 21, 'اَمَّنْ هٰذَا الَّذ۪ي يَرْزُقُكُمْ اِنْ اَمْسَكَ رِزْقَهُۚ بَلْ لَجُّوا ف۪ي عُتُوٍّ وَنُفُورٍ', 'Emmen hazellezi yerzukukum in emseke rızkah, bel leccu fi utuvvin ve nufur.', 'Veya O,  rızkınızı kesse,  size kim rızık verebilir? Bilakis,  onlar haddi aşmada ve nefrette ısrar ettiler.', 'امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور'),
(5263, 67, 22, 'اَفَمَنْ يَمْش۪ي مُكِباًّ عَلٰى وَجْهِه۪ٓ  اَهْدٰٓى اَمَّنْ يَمْش۪ي سَوِياًّ عَلٰى صِرَاطٍ مُسْتَق۪يمٍ', 'E fe men yemşi mukibben ala vechihi ehda emmen yemşi seviyyen ala sıratın mustekim.', 'O halde,  yüzüstü sürünerek giden mi,  yoksa dosdoğru yolda düzgün yürüyen mi hedefine varır?', 'افمن يمشي مكبا علي وجهه اهدي امن يمشي سويا علي صرط مستقيم'),
(5264, 67, 23, 'قُلْ هُوَ الَّـذ۪ٓي اَنْشَاَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٔدَةَۜ قَل۪يلاً مَا تَشْكُرُونَ', 'Kul huvellezi enşeekum ve ceale lekumus sem\'a vel ebsare vel ef\'ideh, kalilen ma teşkurun.', 'De ki: \"Sizi biçimlendiren; size işitme,  görme ve idrak etme gücü veren O\'dur. Ne kadar az şükrediyorsunuz?[1]', 'قل هو الذي انشاكم وجعل لكم السمع والابصر والافدة قليلا ما تشكرون'),
(5265, 67, 24, 'قُلْ هُوَ الَّذ۪ي ذَرَاَكُمْ فِي الْاَرْضِ وَاِلَيْهِ تُحْشَرُونَ', 'Kul huvellezi zereekum fil ardı ve ileyhi tuhşerun.', 'De ki: \"Sizi,  yeryüzünde çoğaltıp yayan O\'dur. Ve O\'na toplanıp götürüleceksiniz.\"', 'قل هو الذي ذراكم في الارض واليه تحشرون'),
(5266, 67, 25, 'وَيَقُولُونَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صَادِق۪ينَ', 'Ve yekulune meta hazel va\'du in kuntum sadikin.', '\"Eğer doğru söylüyorsanız,  yaptığınız bu uyarı ne zaman gerçekleşecek?\" diyorlar.', 'ويقولون متي هذا الوعد ان كنتم صدقين'),
(5267, 67, 26, 'قُلْ اِنَّمَا الْعِلْمُ عِنْدَ اللّٰهِۖ وَاِنَّمَٓا اَنَا۬ نَذ۪يرٌ مُب۪ينٌ', 'Kul innemel ilmu indallahi ve innema ene nezirun mubin.', 'De ki: \"Bunu yalnızca Allah bilmektedir. Ben,  sadece apaçık bir uyarıcıyım.\"', 'قل انما العلم عند الله وانما انا نذير مبين'),
(5268, 67, 27, 'فَلَمَّا رَاَوْهُ زُلْفَةً س۪ٓيـَٔتْ وُجُوهُ الَّذ۪ينَ كَفَرُوا وَق۪يلَ هٰذَا الَّذ۪ي كُنْتُمْ بِه۪ تَدَّعُونَ', 'Fe lemma reevhu zulfeten siet vucuhullezine keferu ve kile hazellezi kuntum bihi teddeun.', 'Onu yakından gördükleri zaman,  gerçeği yalanlayan nankörlerin yüzleri kötüleşti. Onlara: \"İşte bu,  sizin isteyip durduğunuz şey!\"[1] denildi.', 'فلما راوه زلفة سيت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون'),
(5269, 67, 28, 'قُلْ اَرَاَيْتُمْ اِنْ اَهْلَكَنِيَ اللّٰهُ وَمَنْ مَعِيَ اَوْ رَحِمَنَاۙ فَمَنْ يُج۪يرُ الْكَافِر۪ينَ مِنْ عَذَابٍ اَل۪يمٍ', 'Kul ereeytum in ehlekeniyallahu ve men maıye ev rahımena fe men yucirul kafirine min azabin elim.', 'De ki: \"Bakın,  Allah beni ve benimle birlikte olanları ister yok eder ister merhamet eder; peki,  Kafirleri[1] acıklı azaptan kim koruyacak?\"', 'قل اريتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكفرين من عذاب اليم'),
(5270, 67, 29, 'قُلْ هُوَ الرَّحْمٰنُ اٰمَنَّا بِه۪ وَعَلَيْهِ تَوَكَّلْنَاۚ فَسَتَعْلَمُونَ مَنْ هُوَ ف۪ي ضَلَالٍ مُب۪ينٍ', 'Kul huver rahmanu amenna bihi ve aleyhi tevekkelna, fe se ta\'lemune men huve fi dalalin mubin.', 'De ki: \"O,  rahmeti kesintisiz olandır. O\'na iman ettik ve O\'na tevekkül[1] ettik. Artık kimin apaçık bir sapkınlık içinde olduğunu yakında bileceksiniz.\"', 'قل هو الرحمن امنا به وعليه توكلنا فستعلمون من هو في ضلل مبين'),
(5271, 67, 30, 'قُلْ اَرَاَيْتُمْ اِنْ اَصْبَحَ مَٓاؤُ۬كُمْ غَوْراً فَمَنْ يَأْت۪يكُمْ بِمَٓاءٍ مَع۪ينٍ', 'Kul e re\'eytum in asbaha maukum gavren fe men ye\'tikum bi main main.', 'De ki: \"Düşünsenize,  şayet suyunuz yeraltına çekilse,  size akarsuyu kim getirebilir?\"', 'قل اريتم ان اصبح ماوكم غورا فمن ياتيكم بما معين'),
(5272, 68, 1, 'نٓ وَالْقَلَمِ وَمَا يَسْطُرُونَۙ', 'Nun vel kalemi ve ma yesturun.', 'Nun. Kaleme ve satır satır yazdıklarına ant olsun ki,', 'ن والقلم وما يسطرون'),
(5273, 68, 2, 'مَٓا اَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍۚ', 'Ma ente bi ni\'meti rabbike bi mecnun.', 'Rabb\'inin nimeti[1] ile sen mecnun[2] değilsin.', 'ما انت بنعمة ربك بمجنون'),
(5274, 68, 3, 'وَاِنَّ لَكَ لَاَجْراً غَيْرَ مَمْنُونٍۚ', 'Ve inne leke le ecren gayre memnun.', 'Senin için minnet altında bırakmayan bir ödül vardır.', 'وان لك لاجرا غير ممنون'),
(5275, 68, 4, 'وَاِنَّكَ لَعَلٰى خُلُقٍ عَظ۪يمٍ', 'Ve inneke le ala hulukın azim.', 'Sen,  kesinlikle büyük bir ahlak[1] üzerindesin.', 'وانك لعلي خلق عظيم'),
(5276, 68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَۙ', 'Fe se tubsıru ve yubsırun.', 'Yakında göreceksin,  onlar da görecekler!', 'فستبصر ويبصرون'),
(5277, 68, 6, 'بِاَيِّكُمُ الْمَفْتُونُ', 'Bi eyyikumul meftun.', 'Kimmiş meftun[1] olan.', 'باييكم المفتون'),
(5278, 68, 7, 'اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِمَنْ ضَلَّ عَنْ سَب۪يلِه۪ۖ وَهُوَ اَعْلَمُ بِالْمُهْتَد۪ينَ', 'İnne rabbeke huve a\'lemu bi men dalle an sebilihi ve huve a\'lemu bil muhtedin.', 'Kuşkusuz Rabb\'in,  kimin Kendi yolundan saptığını çok iyi bilir; doğru yolda olanları da en iyi O bilir.', 'ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين'),
(5279, 68, 8, 'فَلَا تُطِعِ الْمُكَذِّب۪ينَ', 'Fe la tutııl mukezzibin.', 'O halde yalanlayanlara boyun eğme.', 'فلا تطع المكذبين'),
(5280, 68, 9, 'وَدُّوا لَوْ تُدْهِنُ فَيُدْهِنُونَ', 'Veddu lev tudhinu fe yudhinun.', 'Onlar,  uzlaşmacı olmanı ve böylece de seninle uzlaşmayı isterler.', 'ودوا لو تدهن فيدهنون'),
(5281, 68, 10, 'وَلَا تُطِـعْ كُلَّ حَلَّافٍ مَه۪ينٍۙ', 'Ve la tutı\' kulle hallafin mehin.', 'Hiç durmadan yemin eden[1] düzenbazlara boyun eğme.', 'ولا تطع كل حلاف مهين'),
(5282, 68, 11, 'هَمَّازٍ مَشَّٓاءٍ بِنَم۪يمٍۙ', 'Hemmazin meşşain bi nemim.', 'Devamlı kusur arayıp laf taşıyan iftiracılara,', 'هماز مشا بنميم'),
(5283, 68, 12, 'مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ اَث۪يمٍۙ', 'Mennaın lil hayri mu\'tedin esim.', 'Sürekli iyi şeyleri engelleyip haddi aşan günahkarlara,', 'مناع للخير معتد اثيم'),
(5284, 68, 13, 'عُتُلٍّ بَعْدَ ذٰلِكَ زَن۪يمٍۙ', 'Utullin ba\'de zalike zenim.', 'Zorba,  kötü karakterli kimselere;', 'عتل بعد ذلك زنيم'),
(5285, 68, 14, 'اَنْ كَانَ ذَا مَالٍ وَبَن۪ينَۜ', 'En kane za malin ve benin.', 'Mal ve oğulları[1] var diye.', 'ان كان ذا مال وبنين'),
(5286, 68, 15, 'اِذَا تُتْلٰى عَلَيْهِ اٰيَاتُنَا قَالَ اَسَاط۪يرُ الْاَوَّل۪ينَ', 'İza tutla aleyhi ayatuna kale esatirul evvelin.', 'Ona ayetlerimiz okunduğu zaman: \"Bunlar evvelkilerin masalları.\" der.', 'اذا تتلي عليه ايتنا قال اسطير الاولين'),
(5287, 68, 16, 'سَنَسِمُهُ عَلَى الْخُرْطُومِ', 'Se nesimuhu alel hurtum.', 'Yakında hortumunun üzerine damga basacağız.[1]', 'سنسمه علي الخرطوم'),
(5288, 68, 17, 'اِنَّا بَلَوْنَاهُمْ  كَمَا بَلَوْنَٓا اَصْحَابَ الْجَنَّةِۚ  اِذْ اَقْسَمُوا لَيَصْرِمُنَّهَا مُصْبِح۪ينَۙ', 'İnna belevnahum ke ma belevna ashabel cenneh, iz aksemule yasri munneha musbihin.', 'Kuşkusuz Biz onları belalandırdık.[1] Tıpkı,  bahçelerinin ürünlerini sabah erkenden[2] toplayacaklarına dair sözleşen[3] bahçe sahiplerini belalandırdığımız gibi.', 'انا بلونهم كما بلونا اصحب الجنة اذ اقسموا ليصرمنها مصبحين'),
(5289, 68, 18, 'وَلَا يَسْتَثْنُونَ', 'Ve la yestesnun.', 'Bir istisna da yapmıyorlardı.', 'ولا يستثنون'),
(5290, 68, 19, 'فَطَافَ عَلَيْهَا طَٓائِفٌ مِنْ رَبِّكَ وَهُمْ نَٓائِمُونَ', 'Fe tafe aleyha taifun min rabbike ve hum naimun.', 'Fakat onlar daha uyanmadan,  Rabb\'in tarafından bir dolaşan onun üzerinde dolaştı.', 'فطاف عليها طايف من ربك وهم نايمون'),
(5291, 68, 20, 'فَاَصْبَحَتْ كَالصَّر۪يمِ', 'Fe asbahat kes sarim.', 'Böylece,  bahçeleri,  üzerinde hiç ekin olmayan kara toprak gibi oldu.', 'فاصبحت كالصريم'),
(5292, 68, 21, 'فَتَنَادَوْا مُصْبِح۪ينَۙ', 'Fe tenadev musbihin.', 'Sabah olunca birbirlerine seslendiler.', 'فتنادوا مصبحين'),
(5293, 68, 22, 'اَنِ اغْدُوا عَلٰى حَرْثِكُمْ اِنْ كُنْتُمْ صَارِم۪ينَ', 'Enıgdu ala harsikum in kuntum sarımin.', 'Eğer,  ürününüzü toplayacaksanız,  tarlanıza sabah erkenden gidin!', 'ان اغدوا علي حرثكم ان كنتم صرمين'),
(5294, 68, 23, 'فَانْطَلَقُوا وَهُمْ يَتَخَافَتُونَۙ', 'Fentaleku ve hum yetehafetun.', 'Hemen,  sessizce yola koyuldular.', 'فانطلقوا وهم يتخفتون'),
(5295, 68, 24, 'اَنْ لَا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِسْك۪ينٌ', 'En la yedhulennehel yevme aleykum miskin.', '\"Sakın ha! Bugün aranıza hiçbir ihtiyaç sahibi girmesin.\"', 'ان لا يدخلنها اليوم عليكم مسكين'),
(5296, 68, 25, 'وَغَدَوْا عَلٰى حَرْدٍ قَادِر۪ينَ', 'Ve gadev ala hardin kadirin.', 'İhtiyaç sahiplerini göz ardı ederek erkenden gittiler.', 'وغدوا علي حرد قدرين'),
(5297, 68, 26, 'فَلَمَّا رَاَوْهَا قَالُٓوا اِنَّا لَضَٓالُّونَۙ', 'Fe lemma reevha kalu inna le dallun.', 'Fakat onu gördüklerinde: \"Herhalde yanlış yere geldik!\" dediler.', 'فلما راوها قالوا انا لضالون'),
(5298, 68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ', 'Bel nahnu mahrumun.', '\"Hayır! Biz,  mahrum bırakılanlarız.\"', 'بل نحن محرومون'),
(5299, 68, 28, 'قَالَ اَوْسَطُهُمْ اَلَمْ اَقُلْ لَـكُمْ لَوْلَا تُسَبِّحُونَ', 'Kale evsatuhum e lem ekul lekum levla tusebbihun.', 'En makul düşünenleri: \"Ben,  size tesbih[1] etmeliyiz dememiş miydim?\" dedi.', 'قال اوسطهم الم اقل لكم لولا تسبحون'),
(5300, 68, 29, 'قَالُوا سُبْحَانَ رَبِّنَٓا اِنَّا كُنَّا ظَالِم۪ينَ', 'Kalu subhane rabbina inna kunna zalimin.', 'Onlar: \"Rabb\'imizi tesbih ederiz. Doğrusu bizler haksızlık edenlermişiz.\" dediler.', 'قالوا سبحن ربنا انا كنا ظلمين'),
(5301, 68, 30, 'فَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَتَلَاوَمُونَ', 'Fe akbele ba\'duhum ala ba\'dın yetelavemun.', 'Ardından birbirlerini suçlamaya başladılar.', 'فاقبل بعضهم علي بعض يتلومون'),
(5302, 68, 31, 'قَالُوا يَا وَيْلَنَٓا اِنَّا كُنَّا طَاغ۪ينَ', 'Kalu ya veylena inna kunna tagin.', '\"Yazıklar olsun bize! Biz,  gerçekten azgınlık eden kimselermişiz.\"', 'قالوا يويلنا انا كنا طغين'),
(5303, 68, 32, 'عَسٰى رَبُّنَٓا اَنْ يُبْدِلَنَا خَيْراً مِنْهَٓا اِنَّٓا اِلٰى رَبِّنَا رَاغِبُونَ', 'Asa rabbuna en yubdilena hayren minha inna ila rabbina ragıbun.', '\"Umarız ki,  Rabb\'imiz bize onun yerine daha hayırlısını verir. Ümitle Rabb\'imize yöneliyoruz.\"', 'عسي ربنا ان يبدلنا خيرا منها انا الي ربنا رغبون'),
(5304, 68, 33, 'كَذٰلِكَ الْعَذَابُۜ وَلَعَذَابُ الْاٰخِرَةِ اَكْبَرُۢ  لَوْ كَانُوا يَعْلَمُونَ۟', 'Kezalikel azab, ve le azabul ahıreti ekber, lev kanu ya\'lemun.', 'İşte azap böyledir. Âhiret azabı ise elbette daha büyüktür. Keşke bilenlerden olsalardı.', 'كذلك العذاب ولعذاب الاخرة اكبر لو كانوا يعلمون'),
(5305, 68, 34, 'اِنَّ لِلْمُتَّق۪ينَ عِنْدَ رَبِّهِمْ جَنَّاتِ النَّع۪يمِ', 'İnne lil muttekine ınde rabbihim cennatin naim.', 'Takva sahipleri için,  Rabb\'lerinin yanında,  nimeti bol Cennetler vardır.', 'ان للمتقين عند ربهم جنت النعيم'),
(5306, 68, 35, 'اَفَنَجْعَلُ الْمُسْلِم۪ينَ كَالْمُجْرِم۪ينَۜ', 'E fe necalul muslimine kel mucrimin.', 'İşte böyle,  hiç Allah\'a teslim olanları,  suçlularla bir tutar mıyız?', 'افنجعل المسلمين كالمجرمين'),
(5307, 68, 36, 'مَا لَـكُمْ۠   كَيْفَ تَحْكُمُونَۚ', 'Ma lekum, keyfe tahkumun.', 'Size ne oluyor? Nasıl hüküm veriyorsunuz?[1]', 'ما لكم كيف تحكمون'),
(5308, 68, 37, 'اَمْ لَـكُمْ  كِتَابٌ ف۪يهِ تَدْرُسُونَۙ', 'Em lekum kitabun fihi tedrusun.', 'Yoksa bir kitabınız var da bu bilgileri oradan mı öğreniyorsunuz?', 'ام لكم كتب فيه تدرسون'),
(5309, 68, 38, 'اِنَّ لَـكُمْ ف۪يهِ لَمَا تَخَيَّرُونَۚ', 'İnne lekum fihi lema tehayyerun.', 'İçinde,  \"Beğendiğiniz şeyler sizindir.\" yazan bir kitap.', 'ان لكم فيه لما تخيرون'),
(5310, 68, 39, 'اَمْ لَـكُمْ اَيْمَانٌ عَلَيْنَا بَالِغَةٌ اِلٰى يَوْمِ الْقِيٰمَةِۙ اِنَّ لَـكُمْ لَمَا تَحْكُمُونَۚ', 'Em lekum eymanun aleyna baligatun ila yevmil kıyameti inne lekum lema tahkumun.', 'Yoksa siz her ne hüküm verirseniz öyle olacak diye,  Kıyamet Günü\'ne kadar geçerli verilmiş bir sözümüz mü var?', 'ام لكم ايمن علينا بلغة الي يوم القيمة ان لكم لما تحكمون'),
(5311, 68, 40, 'سَلْهُمْ اَيُّهُمْ بِذٰلِكَ زَع۪يمٌۚۛ', 'Sel hum eyyuhum bi zalike zeim.', 'Onlara sor bakalım: \"Böyle bir şeye hangisi garanti verebilir?\"', 'سلهم ايهم بذلك زعيم'),
(5312, 68, 41, 'اَمْ لَهُمْ شُرَكَٓاءُۚۛ  فَلْيَأْتُوا بِشُرَكَٓائِهِمْ  اِنْ  كَانُوا صَادِق۪ينَ', 'Em lehum şurekau, fel ye\'tu bi şurekaihim in kanu sadikin.', 'Yoksa ortakları mı var? Eğer doğru söylüyorlarsa ortaklarını getirsinler!', 'ام لهم شركا فلياتوا بشركايهم ان كانوا صدقين'),
(5313, 68, 42, 'يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ اِلَى السُّجُودِ فَلَا يَسْتَط۪يعُونَۙ', 'Yevme yukşefu an sakın ve yud\'avne iles sucudi fe la yestetiun.', 'Gerçeklerin açığa çıktığı gün secde[1] etmeye çağrılacaklar,  ancak buna güçleri yetmez.', 'يوم يكشف عن ساق ويدعون الي السجود فلا يستطيعون'),
(5314, 68, 43, 'خَاشِعَةً اَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌۜ  وَقَدْ كَانُوا يُدْعَوْنَ اِلَى السُّجُودِ وَهُمْ سَالِمُونَ', 'Haşiaten ebsaruhum terhekuhum zilleh, ve kad kanu yud\'avne iles sucudi ve hum salimun.', 'O gün,  gözlerini umutsuzca endişe bürüyecek,  yüzlerini aşağılanmışlık duygusu kaplayacaktır. Oysaki onlar,  fırsat varken secdeye davet olunmuşlardı.', 'خشعة ابصرهم ترهقهم ذلة وقد كانوا يدعون الي السجود وهم سلمون'),
(5315, 68, 44, 'فَذَرْن۪ي وَمَنْ يُكَذِّبُ بِهٰذَا الْحَد۪يثِۜ سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَۙ', 'Fe zerni ve men yukezzibu bi hazel hadis, se nestedricuhum min haysu la ya\'lemun.', 'O halde bu hadisi[1] yalanlayanları Bana bırak. Onları bilmedikleri bir yerden yavaş yavaş yaklaştıracağız.', 'فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون'),
(5316, 68, 45, 'وَاُمْل۪ي لَهُمْۜ  اِنَّ كَيْد۪ي مَت۪ينٌ', 'Ve umli lehum, inne keydi metin.', 'Onlara süre tanıyorum. Kuşkusuz,  Benim planım çok sağlamdır.', 'واملي لهم ان كيدي متين'),
(5317, 68, 46, 'اَمْ تَسْـَٔلُهُمْ اَجْراً فَهُمْ مِنْ مَغْرَمٍ مُثْقَلُونَۚ', 'Em tes\'eluhum ecren fe hum min magremin muskalun.', 'Yoksa onlardan bir ücret istiyorsun da onlar ağır bir borca mı giriyorlar?', 'ام تسلهم اجر فهم من مغرم مثقلون'),
(5318, 68, 47, 'اَمْ عِنْدَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ', 'Em inde humul gaybu fehum yektubun.', 'Veya gaybın bilgisine sahipler de oradan mı yazıyorlar?', 'ام عندهم الغيب فهم يكتبون'),
(5319, 68, 48, 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُنْ كَصَاحِبِ الْحُوتِۢ اِذْ نَادٰى وَهُوَ مَكْظُومٌۜ', 'Fasbir li hukmi rabbike ve la tekun ke sahıbil hut, iz nada ve huve mekzum.', 'Artık Rabb\'inin hükmünü sabırla bekle. Balık sahibi[1] gibi olma. Hani o çok üzüntülü ve hüzünlü olarak seslenmişti.', 'فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادي وهو مكظوم'),
(5320, 68, 49, 'لَوْلَٓا اَنْ تَدَارَكَهُ نِعْمَةٌ مِنْ رَبِّه۪ لَنُبِذَ بِالْعَرَٓاءِ وَهُوَ مَذْمُومٌ', 'Levla en tedarekehu ni\'metun min rabbihi le nubize bil arai ve huve mezmum.', 'Eğer Rabb\'inden yeniden bir nimet ulaşmasaydı,  kınanmış olarak boş bir yere atılmış olacaktı.', 'لولا ان تدركه نعمة من ربه لنبذ بالعرا وهو مذموم'),
(5321, 68, 50, 'فَاجْتَبٰيهُ رَبُّهُ فَجَعَلَهُ مِنَ الصَّالِح۪ينَ', 'Fectebahu rabbuhu fe cealehu mines salihin.', 'Fakat Rabb\'i onu seçti ve iyilerden yaptı.', 'فاجتبه ربه فجعله من الصلحين'),
(5322, 68, 51, 'وَاِنْ يَكَادُ الَّذ۪ينَ كَفَرُوا لَيُزْلِقُونَكَ بِاَبْصَارِهِمْ لَمَّا سَمِعُوا الذِّكْرَ وَيَقُولُونَ اِنَّهُ لَمَجْنُونٌۢ', 'Ve in yekadullezine keferu le yuzlikuneke bi ebsarihim lemma semiuz zikra ve yekulune innehu le mecnun.', 'Gerçeği yalanlayan nankörler,  o öğüdü duydukları zaman,  neredeyse gözleriyle seni devireceklerdi. \"Kuşkusuz o bir delidir.\" diyorlardı.', 'وان يكاد الذين كفروا ليزلقونك بابصرهم لما سمعوا الذكر ويقولون انه لمجنون'),
(5323, 68, 52, 'وَمَا هُوَ اِلَّا ذِكْرٌ لِلْعَالَم۪ينَ', 'Ve ma huve illa zikrun lil alemin.', 'Oysaki o,  bütün insanlık için öğütten başka bir şey değildir.', 'وما هو الا ذكر للعلمين'),
(5324, 69, 1, 'اَلْحَٓاقَّةُۙ', 'El hakkah.', 'Gerçekleşeceği kesin olan![1]', 'الحاقة'),
(5325, 69, 2, 'مَا الْحَٓاقَّةُۚ', 'Mel hakkah.', 'Nedir gerçekleşeceği kesin olan?', 'ما الحاقة'),
(5326, 69, 3, 'وَمَٓا اَدْرٰيكَ مَا الْحَٓاقَّةُۜ', 'Ve ma edrake mel hakkah.', 'Gerçekleşeceği kesin olanın ne olduğunu,  nereden bileceksin?', 'وما ادريك ما الحاقة'),
(5327, 69, 4, 'كَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ', 'Kezzebet semudu ve adun bil kariah.', 'Semud ve Âd halkı Karia\'yı[1] yalanladılar.', 'كذبت ثمود وعاد بالقارعة'),
(5328, 69, 5, 'فَاَمَّا ثَمُودُ فَاُهْلِكُوا بِالطَّاغِيَةِ', 'Fe emma semudu fe uhliku bit tagıyeh.', 'Bu nedenle Semud halkı büyük bir yıkımla yok edildi.', 'فاما ثمود فاهلكوا بالطاغية'),
(5329, 69, 6, 'وَاَمَّا عَادٌ فَاُهْلِكُوا بِر۪يحٍ صَرْصَرٍ عَاتِيَةٍۙ', 'Ve emma adun fe uhliku bi rihın sarsarin atiyeh.', 'Âd halkı ise kasıp kavuran,  şiddetli bir fırtına ile yok edildi.', 'واما عاد فاهلكوا بريح صرصر عاتية'),
(5330, 69, 7, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَانِيَةَ اَيَّامٍۙ حُسُوماً فَتَرَى الْقَوْمَ ف۪يهَا صَرْعٰىۙ كَاَنَّهُمْ اَعْجَازُ نَخْلٍ خَاوِيَةٍۚ', 'Sehhareha aleyhim seb\'a leyalin ve semaniyete eyyamin husumen fe terel kavme fiha sar\'a ke ennehum a\'cazu nahlin haviyeh.', 'Onu,  yedi gece ve sekiz gün; hiç ara vermeden üzerlerine musallat etti. Öyle ki,  o halkı,  orada kökünden sökülmüş hurma ağacı kütükleri gibi yere serilmiş görürsün.', 'سخرها عليهم سبع ليال وثمنية ايام حسوما فتري القوم فيها صرعي كانهم اعجاز نخل خاوية'),
(5331, 69, 8, 'فَهَلْ تَرٰى لَهُمْ مِنْ بَاقِيَةٍ', 'Fe hel tera lehum min bakıyeh.', 'Artık onlara ait bir kalıntı görebiliyor musun?', 'فهل تري لهم من باقية'),
(5332, 69, 9, 'وَجَٓاءَ فِرْعَوْنُ وَمَنْ قَبْلَهُ وَالْمُؤْتَفِكَاتُ بِالْخَاطِئَةِۚ', 'Ve cae fir\'avnu ve men kablehu vel mu\'tefikatu bil hatıeh.', 'Firavun,  ondan öncekiler ve kentleri alt üst olanlar,  o yanlış ile geldiler.', 'وجا فرعون ومن قبله والموتفكت بالخاطية'),
(5333, 69, 10, 'فَعَصَوْا رَسُولَ رَبِّهِمْ فَاَخَذَهُمْ اَخْذَةً رَابِيَةً', 'Fe asav resule rabbihim fe ehazehum ahzeten rabiyeh.', 'Onlar,  Rabb\'lerinin Resul\'üne karşı geldiler. Bunun üzerine onları şiddetli bir yakalayışla yakaladı.', 'فعصوا رسول ربهم فاخذهم اخذة رابية'),
(5334, 69, 11, 'اِنَّا لَمَّا طَغَا الْمَٓاءُ حَمَلْنَاكُمْ فِي الْجَارِيَةِۙ', 'İnna lemma tagal mau hamelnakum fil cariyeh.', 'Suyun taştığı günde,  sizi o akıp gidende Biz taşıdık.', 'انا لما طغا الما حملنكم في الجارية'),
(5335, 69, 12, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَٓا اُذُنٌ وَاعِيَةٌ', 'Li nec\'aleha lekum tezkireten ve teıyeha uzunun vaıyeh.', 'Onu sizin için bir öğüt yapalım,  duyan kulaklar onu duysun diye.', 'لنجعلها لكم تذكرة وتعيها اذن وعية'),
(5336, 69, 13, 'فَاِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌۙ', 'Fe iza nufiha fis suri nefhatun vahıdeh.', 'Artık Sur\'a bir tek üfleyişle üflendiği zaman,', 'فاذا نفخ في الصور نفخة وحدة'),
(5337, 69, 14, 'وَحُمِلَتِ الْاَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةً وَاحِدَةً', 'Ve humiletil ardu vel cibalu fe dukketa dekketen vahıdeh.', 'Yeryüzü ve dağlar kaldırılıp,  bir tek çarpışla parçalandığı zaman,', 'وحملت الارض والجبال فدكتا دكة وحدة'),
(5338, 69, 15, 'فَيَوْمَئِذٍ وَقَعَتِ الْوَاقِعَةُۙ', 'Fe yevme izin vekaatil vakıah.', 'İzin Günü[1] gerçekleşecek olan gerçekleşir.', 'فيوميذ وقعت الواقعة'),
(5339, 69, 16, 'وَانْشَقَّتِ السَّمَٓاءُ فَهِيَ يَوْمَئِذٍ وَاهِيَةٌۙ', 'Ven şakkatis semau fe hiye yevme izin vahiyeh.', 'Gök yarılır. İzin günü[1],  o zayıftır artık.', 'وانشقت السما فهي يوميذ واهية');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(5340, 69, 17, 'وَالْمَلَكُ عَلٰٓى اَرْجَٓائِهَاۜ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌۜ', 'Vel meleku ala ercaiha, ve yahmilu arşe rabbike fevkahum yevme izin semaniyeh.', 'O melek[1],  onun çevresi üzerindedir. İzin günü Rabb\'inin Arş\'ını[2] yeni varlıklar[3] taşırlar.', 'والملك علي ارجايها ويحمل عرش ربك فوقهم يوميذ ثمنية'),
(5341, 69, 18, 'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفٰى مِنْكُمْ خَافِيَةٌ', 'Yevme izin tu\'radune la tahfa minkum hafiyeh.', 'İzin Günü[1],  arz olunacaksınız[2]. Gizli saklı hiçbir şeyiniz kalmaz.', 'يوميذ تعرضون لا تخفي منكم خافية'),
(5342, 69, 19, 'فَاَمَّا مَنْ اُو۫تِيَ كِتَابَهُ بِيَم۪ينِه۪ فَيَقُولُ هَٓاؤُ۬مُ اقْرَؤُ۫ا كِتَابِيَهْۚ', 'Fe emma men utiye kitabehu bi yeminihi fe yekulu haumukreu kitabiyeh.', 'Kitabı sağından verilen[1] kimse: \"Alın,  kitabımı okuyun.\" der.', 'فاما من اوتي كتبه بيمينه فيقول هاوم اقروا كتبيه'),
(5343, 69, 20, 'اِنّ۪ي ظَنَنْتُ اَنّ۪ي مُلَاقٍ حِسَابِيَهْۚ', 'İnni zanentu enniy mülakın hısabiyeh.', 'Doğrusu ben,  hesabımla karşılaşacağımı biliyordum.', 'اني ظننت اني ملق حسابيه'),
(5344, 69, 21, 'فَهُوَ ف۪ي ع۪يشَةٍ رَاضِيَةٍۙ', 'Fe huve fi işetin radıyeh.', 'Artık o,  hoşnut olacağı bir hayat yaşayacak.', 'فهو في عيشة راضية'),
(5345, 69, 22, 'ف۪ي جَنَّةٍ عَالِيَةٍۙ', 'Fi cennetin aliyeh.', 'Mükemmel bir bahçede;', 'في جنة عالية'),
(5346, 69, 23, 'قُطُوفُهَا دَانِيَةٌ', 'Kutufuha daniyeh.', 'Olgunlaşmış meyveleri dallarından sarkmış bir haldedir.', 'قطوفها دانية'),
(5347, 69, 24, 'كُلُوا وَاشْرَبُوا هَن۪ٓيـٔاً بِمَٓا اَسْلَفْتُمْ فِي الْاَيَّامِ الْخَالِيَةِ', 'Kulu veşrebu henien bima esleftum fil eyyamil haliyeh.', 'Dünyada yapmış olduğunuz şeylerin karşılığı olarak,  afiyetle yiyin ve için.', 'كلوا واشربوا هنيا بما اسلفتم في الايام الخالية'),
(5348, 69, 25, 'وَاَمَّا مَنْ اُو۫تِيَ كِتَابَهُ بِشِمَالِه۪ فَيَقُولُ يَا لَيْتَن۪ي لَمْ اُو۫تَ كِتَابِيَهْۚ', 'Ve emma men utiye kitabehu bi şimalihi fe yekulu ya leyteni lem ute kitabiyeh.', 'Kitabı solundan verilen[1] kimse ise: \"Keşke bana kitabım verilmeseydi.\" de;', 'واما من اوتي كتبه بشماله فيقول يليتني لم اوت كتبيه'),
(5349, 69, 26, 'وَلَمْ اَدْرِ مَا حِسَابِيَهْۚ', 'Ve lem edri ma hısabiyeh.', '\"Hesabımın ne olduğunu hiç bilmeseydim.\" der.', 'ولم ادر ما حسابيه'),
(5350, 69, 27, 'يَا لَيْتَهَا كَانَتِ الْقَاضِيَةَۚ', 'Ya leyteha kanetil kadiyeh.', '\"Keşke o[1] bitmiş olsaydı.\"', 'يليتها كانت القاضية'),
(5351, 69, 28, 'مَٓا اَغْنٰى عَنّ۪ي مَالِيَهْۚ', 'Ma agna anni maliyeh.', '\"Malım-gücüm bana hiçbir yarar sağlamadı.\"', 'ما اغني عني ماليه'),
(5352, 69, 29, 'هَلَكَ عَنّ۪ي سُلْطَانِيَهْۚ', 'Heleke anni sultaniyeh.', '\"Bütün saltanatım yok oldu.\"', 'هلك عني سلطنيه'),
(5353, 69, 30, 'خُذُوهُ فَغُلُّوهُۙ', 'Huzuhu fe gulluh.', '\"Onu tutun ve bağlayın.\"', 'خذوه فغلوه'),
(5354, 69, 31, 'ثُمَّ الْجَح۪يمَ صَلُّوهُۙ', 'Summel cahime salluh.', '\"Sonra onu Cehennem\'e atın.\"', 'ثم الجحيم صلوه'),
(5355, 69, 32, 'ثُمَّ ف۪ي سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعاً فَاسْلُكُوهُۜ', 'Summe fi silsiletin zer\'uha seb\'une ziraan feslukuh.', '\"Sonra onu yetmiş arşın uzunluğunda bir zincire bağlayın.\"', 'ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه'),
(5356, 69, 33, 'اِنَّهُ كَانَ لَا يُؤْمِنُ بِاللّٰهِ الْعَظ۪يمِۙ', 'İnnehu kane la yu\'minu billahil azim.', 'O,  yüce Allah\'a inanmıyordu.[1]', 'انه كان لا يومن بالله العظيم'),
(5357, 69, 34, 'وَلَا يَحُضُّ عَلٰى طَعَامِ الْمِسْك۪ينِۜ', 'Ve la yahuddu ala taamil miskin.', 'Miskinin yedirilmesini[1] teşvik etmiyordu.', 'ولا يحض علي طعام المسكين'),
(5358, 69, 35, 'فَلَيْسَ لَهُ الْيَوْمَ هٰهُنَا حَم۪يمٌۙ', 'Fe leyse lehul yevme hahuna hamim.', 'Artık bugün,  onun burada hiçbir koruyucusu yoktur.', 'فليس له اليوم ههنا حميم'),
(5359, 69, 36, 'وَلَا طَعَامٌ اِلَّا مِنْ غِسْل۪ينٍۙ', 'Ve la taamun illa min gıslin.', 'Ve gislinden[1] başka bir yiyecekleri yoktur.', 'ولا طعام الا من غسلين'),
(5360, 69, 37, 'لَا يَأْكُلُهُٓ اِلَّا الْخَاطِؤُ۫نَ۟', 'La ye\'kuluhu illel hatiun.', 'Onu,  yanlışlarında ısrar edenlerden başkası yemez.', 'لا ياكله الا الخطون'),
(5361, 69, 38, 'فَلَٓا اُقْسِمُ بِمَا تُبْصِرُونَۙ', 'Fe la uksımu bima tubsırun.', 'Hayır! Gördüğünüz şeylere yemin ederim;', 'فلا اقسم بما تبصرون'),
(5362, 69, 39, 'وَمَا لَا تُبْصِرُونَۙ', 'Ve ma la tubsırun.', 'Ve görmediklerinize.', 'وما لا تبصرون'),
(5363, 69, 40, 'اِنَّهُ لَقَوْلُ رَسُولٍ كَر۪يمٍۚ', 'İnnehu le kavlu resulun kerimin.', 'Kuşkusuz o,  şerefli bir Resul sözüdür.', 'انه لقول رسول كريم'),
(5364, 69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍۜ  قَل۪يلاً مَا تُـؤْمِنُونَۙ', 'Ve ma huve bi kavli şairin, kalilin ma tu\'minun.', 'O,  bir şair sözü değildir. Amma da inançsızsınız!', 'وما هو بقول شاعر قليلا ما تومنون'),
(5365, 69, 42, 'وَلَا بِقَوْلِ كَاهِنٍۜ  قَل۪يلاً مَا تَذَكَّرُونَۜ', 'Ve la bi kavli kahin, kalilen ma tezekkerun.', 'O,  bir kahin sözü de değildir. Hiç öğüt dinlemiyorsunuz!', 'ولا بقول كاهن قليلا ما تذكرون'),
(5366, 69, 43, 'تَنْز۪يلٌ مِنْ رَبِّ الْعَالَم۪ينَ', 'Tenzilun min rabbil alemin.', 'Âlemlerin Rabb\'inden indirilmedir.', 'تنزيل من رب العلمين'),
(5367, 69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ الْاَقَاو۪يلِۙ', 'Ve lev tekavvele aleyna ba\'dal ekavil.', 'Eğer Bizim adımıza bazı sözler uydurmuş olsaydı;', 'ولو تقول علينا بعض الاقاويل'),
(5368, 69, 45, 'لَاَخَذْنَا مِنْهُ بِالْيَم۪ينِۙ', 'Le ehazna minhu bil yemin.', 'Elbette onun bütün gücünü alırdık.', 'لاخذنا منه باليمين'),
(5369, 69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ الْوَت۪ينَۘ', 'Summe le kata\'na minhul vetin.', 'Sonra kesinlikle can damarını koparırdık.', 'ثم لقطعنا منه الوتين'),
(5370, 69, 47, 'فَمَا مِنْكُمْ مِنْ اَحَدٍ عَنْهُ حَاجِز۪ينَ', 'Fe ma minkum min ehadin anhu hacizin.', 'Hiçbiriniz buna engel olamazdınız.', 'فما منكم من احد عنه حجزين'),
(5371, 69, 48, 'وَاِنَّهُ لَتَذْكِرَةٌ لِلْمُتَّق۪ينَ', 'Ve innehu le tezkiretun lil muttekin.', 'O,  takva[1] sahipleri için bir öğüttür.', 'وانه لتذكرة للمتقين'),
(5372, 69, 49, 'وَاِنَّا لَنَعْلَمُ اَنَّ مِنْكُمْ مُكَذِّب۪ينَ', 'Ve inna le na\'lemu enne minkum mukezzibin.', 'Biz,  sizden onu yalanlayıcıları çok iyi biliyoruz.', 'وانا لنعلم ان منكم مكذبين'),
(5373, 69, 50, 'وَاِنَّهُ لَحَسْرَةٌ عَلَى الْـكَافِر۪ينَ', 'Ve innehu le hasretun alel kafirin.', 'O,  Kafirler için derin bir pişmanlıktır.[1]', 'وانه لحسرة علي الكفرين'),
(5374, 69, 51, 'وَاِنَّهُ لَحَقُّ الْيَق۪ينِ', 'Ve innehu le hakk\'ul yakin.', 'O,  kesinlikle gerçektir.[1]', 'وانه لحق اليقين'),
(5375, 69, 52, 'فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظ۪يمِ', 'Fe sebbıh bismi rabbikel azim.', 'O halde Azim Rabb\'inin adını tesbih et.', 'فسبح باسم ربك العظيم'),
(5376, 70, 1, 'سَاَلَ سَٓائِلٌ بِعَذَابٍ وَاقِعٍۙ', 'Se ele sailun bi azabin vakı\'n.', 'İsteyen,  gerçekleşecek olan azabı istedi.', 'سال سايل بعذاب واقع'),
(5377, 70, 2, 'لِلْـكَافِر۪ينَ لَيْسَ لَهُ دَافِعٌۙ', 'Lil kafirine leyse lehu dafi\'.', 'Kafirler[1] için engellenemez olan azabı.', 'للكفرين ليس له دافع'),
(5378, 70, 3, 'مِنَ اللّٰهِ ذِي الْمَعَارِجِۜ', 'Minallahi zil mearic.', 'Mearic[1] sahibi Allah tarafından.', 'من الله ذي المعارج'),
(5379, 70, 4, 'تَعْرُجُ الْمَلٰٓئِكَةُ وَالرُّوحُ اِلَيْهِ ف۪ي يَوْمٍ كَانَ مِقْدَارُهُ خَمْس۪ينَ اَلْفَ سَنَةٍۚ', 'Ta\'rucul melaiketu ver ruhu ileyhi fi yevmin kane mikdaruhu hamsine elfe seneh.', 'Melekler ve ruh,  miktarı elli bin yıl[1] olan bir günde O\'na yükselir. [2]', 'تعرج المليكة والروح اليه في يوم كان مقداره خمسين الف سنة'),
(5380, 70, 5, 'فَاصْبِرْ صَبْراً جَم۪يلاً', 'Fasbir sabren cemila.', 'O halde,  güzel bir sabır ile sabret.', 'فاصبر صبرا جميلا'),
(5381, 70, 6, 'اِنَّهُمْ يَرَوْنَهُ بَع۪يداًۙ', 'İnnehum yerevnehu baida.', 'Onlar onu[1] uzak olarak görüyorlar.', 'انهم يرونه بعيدا'),
(5382, 70, 7, 'وَنَرٰيهُ قَر۪يباًۜ', 'Ve nerahu kariba.', 'Biz,  onu yakın görüyoruz.', 'ونريه قريبا'),
(5383, 70, 8, 'يَوْمَ تَكُونُ السَّمَٓاءُ كَالْمُهْلِۙ', 'Yevme tekunus semau kel muhl.', 'O gün gökyüzü erimiş bir maden gibi olur.', 'يوم تكون السما كالمهل'),
(5384, 70, 9, 'وَتَكُونُ الْجِبَالُ كَالْعِهْنِۙ', 'Ve tekunul cibalu kel ıhn.', 'Ve dağlar renkli yün gibi olur.', 'وتكون الجبال كالعهن'),
(5385, 70, 10, 'وَلَا يَسْـَٔلُ حَم۪يمٌ حَم۪يماًۚ', 'Ve la yes\'elu hamimun hamima.', 'Ve hiçbir hamim[1],  başka bir hamimi sormaz.', 'ولا يسل حميم حميما'),
(5386, 70, 11, 'يُبَصَّرُونَهُمْۜ  يَوَدُّ الْمُجْرِمُ لَوْ يَفْتَد۪ي مِنْ عَذَابِ يَوْمِئِذٍ بِبَن۪يهِۙ', 'Yubassarunehum yeveddul mucrimu lev yeftedi min azabi yevmi izin bi benih.', 'Onlar,  birbirleriyle yüzleşecekler. Mücrim[1] olan,  İzin Günü\'nün[2] azabından kurtulmak için mümkün olsa oğullarını fidye olarak verebilmeyi ister;', 'يبصرونهم يود المجرم لو يفتدي من عذاب يوميذ ببنيه'),
(5387, 70, 12, 'وَصَاحِبَتِه۪ وَاَخ۪يهِۙ', 'Ve sahıbetihi ve ahih.', 'Eşini ve kardeşini,', 'وصحبته واخيه'),
(5388, 70, 13, 'وَفَص۪يلَتِهِ الَّت۪ي تُـْٔو۪يهِۙ', 'Ve fasiletihilleti tu\'vih.', 'Kendisini barındıran soyunu-sopunu;', 'وفصيلته التي تويه'),
(5389, 70, 14, 'وَمَنْ فِي الْاَرْضِ جَم۪يعاًۙ ثُمَّ يُنْج۪يهِۙ', 'Ve men fil ardı cemi\'an summe yuncih.', 'Yeryüzünde kimi varsa tamamını verip kendisini kurtarmak ister.', 'ومن في الارض جميعا ثم ينجيه'),
(5390, 70, 15, 'كَلَّاۜ اِنَّهَا لَظٰىۙ', 'Kella, inneha leza.', 'Hayır! Hayır! O alev alev yanan ateştir;', 'كلا انها لظي'),
(5391, 70, 16, 'نَزَّاعَةً لِلشَّوٰىۚ', 'Nezzaaten liş şeva.', 'Derileri kavurup soyan;', 'نزاعة للشوي'),
(5392, 70, 17, 'تَدْعُوا مَنْ اَدْبَرَ وَتَوَلّٰىۙ', 'Ted\'u men edbera ve tevella.', 'Haktan yüz çevirip,  arkasını dönen kimseyi kendisine çağıran;', 'تدعوا من ادبر وتولي'),
(5393, 70, 18, 'وَجَمَعَ فَاَوْعٰى', 'Ve cemea fe ev\'a.', 'Mal,  mülk edinip,  onu biriktireni.', 'وجمع فاوعي'),
(5394, 70, 19, 'اِنَّ الْاِنْسَانَ خُلِقَ هَلُوعاًۙ', 'İnnel insane hulika helua.', 'O insan[1] hırslı yaratıldı.[2]', 'ان الانسن خلق هلوعا'),
(5395, 70, 20, 'اِذَا مَسَّهُ الشَّرُّ جَزُوعاًۙ', 'İza messehuş şerru cezua.', 'Başına kötü bir şey geldiğinde sızlanmaya başlar.[1]', 'اذا مسه الشر جزوعا'),
(5396, 70, 21, 'وَاِذَا مَسَّهُ الْخَيْرُ مَنُوعاًۙ', 'Ve iza messehul hayru menua.', 'Mal-mülk sahibi olunca da ondan kimseyi yararlandırmaz.', 'واذا مسه الخير منوعا'),
(5397, 70, 22, 'اِلَّا الْمُصَلّ۪ينَۙ', 'İllel musallin.', 'Ancak \"musallin\"[1] olanlar hariç.', 'الا المصلين'),
(5398, 70, 23, 'اَلَّذ۪ينَ هُمْ عَلٰى صَلَاتِهِمْ دَٓائِمُونَۖ', 'Ellezine hum ala salatihim daimun.', 'Onlar,  salatlarında[1] devamlıdırlar.', 'الذين هم علي صلاتهم دايمون'),
(5399, 70, 24, 'وَالَّذ۪ينَ ف۪ٓي اَمْوَالِهِمْ حَقٌّ مَعْلُومٌۙ', 'Vellezine fi emvalihim hakkun ma\'lum.', 'Onlar,  mallarında belirli bir pay ayıranlardır;[1]', 'والذين في امولهم حق معلوم'),
(5400, 70, 25, 'لِلسَّٓائِلِ وَالْمَحْرُومِۖ', 'Lis saili vel mahrum.', 'İsteyenler ve yoksun olanlar için.', 'للسايل والمحروم'),
(5401, 70, 26, 'وَالَّذ۪ينَ يُصَدِّقُونَ بِيَوْمِ الدّ۪ينِۖ', 'Vellezine yusaddikune bi yevmid din.', 'Onlar,  Din Günü\'nü[1] tasdik ederler.', 'والذين يصدقون بيوم الدين'),
(5402, 70, 27, 'وَالَّذ۪ينَ هُمْ مِنْ عَذَابِ رَبِّهِمْ مُشْفِقُونَۚ', 'Vellezine hum min azabi rabbihim muşfikun.', 'Onlar,  Rabb\'lerinin azabından çekinirler.', 'والذين هم من عذاب ربهم مشفقون'),
(5403, 70, 28, 'اِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍۚ', 'İnne azabe rabbihim gayru me\'mun.', 'Rabb\'lerinin azabından kimse emin olamaz.', 'ان عذاب ربهم غير مامون'),
(5404, 70, 29, 'وَالَّذ۪ينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَۙ', 'Vellezine hum li furucihim hafizun.', 'Onlar,  ferçlerini[1] korurlar.', 'والذين هم لفروجهم حفظون'),
(5405, 70, 30, 'اِلَّا عَلٰٓى اَزْوَاجِهِمْ اَوْ مَا مَلَكَتْ اَيْمَانُهُمْ فَاِنَّهُمْ غَيْرُ مَلُوم۪ينَۚ', 'İlla ala ezvacihim ev ma meleket eymanuhum fe innehum gayru melumin.', 'Eşleri veya antlaşma yolu ile[1] sahip oldukları hariç. Şüphesiz onlar kınanmazlar.[2]', 'الا علي ازوجهم او ما ملكت ايمنهم فانهم غير ملومين'),
(5406, 70, 31, 'فَمَنِ ابْتَغٰى وَرَٓاءَ ذٰلِكَ فَاُو۬لٰٓئِكَ هُمُ الْعَادُونَۚ', 'Fe menibtega verae zalike fe ulaike humul adun.', 'Bunun ötesinde bir şey isteyenler,  haddi aşanlardır.', 'فمن ابتغي ورا ذلك فاوليك هم العادون'),
(5407, 70, 32, 'وَالَّذ۪ينَ هُمْ لِاَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَۖ', 'Vellezine hum li emanatihim ve ahdihim raun.', 'Onlar[1],  emanetlerini ve ahitlerini gözetirler.', 'والذين هم لامنتهم وعهدهم رعون'),
(5408, 70, 33, 'وَالَّذ۪ينَ هُمْ بِشَهَادَاتِهِمْ قَٓائِمُونَۖ', 'Vellezine hum bi şehadatihim kaimun.', 'Onlar,  tanıklıklarını dosdoğru yerine getirirler.', 'والذين هم بشهدتهم قايمون'),
(5409, 70, 34, 'وَالَّذ۪ينَ هُمْ عَلٰى صَلَاتِهِمْ يُحَافِظُونَۜ', 'Vellezine hum ala salatihim yuhafizun.', 'Onlar,  salatlarını[1] korurlar.', 'والذين هم علي صلاتهم يحافظون'),
(5410, 70, 35, 'اُو۬لٰٓئِكَ ف۪ي جَنَّاتٍ مُكْرَمُونَۜ ۟', 'Ulaike fi cennatin mukremun.', 'İşte onlar,  Cennetlerde ağırlanacak olanlardır.', 'اوليك في جنت مكرمون'),
(5411, 70, 36, 'فَمَالِ الَّذ۪ينَ كَفَرُوا قِبَلَكَ مُهْطِع۪ينَۙ', 'Fe ma lillezine keferu kıbeleke muhtıin.', 'Şimdi Kafirlere ne oluyor da sana doğru koşuşturuyorlar?', 'فمال الذين كفروا قبلك مهطعين'),
(5412, 70, 37, 'عَنِ الْيَم۪ينِۙ وَعَنِ الشِّمَالِ عِز۪ينَ', 'Anil yemini ve aniş şimali ızin.', 'Her yönden,  her yerden gruplar halinde.', 'عن اليمين وعن الشمال عزين'),
(5413, 70, 38, 'اَيَطْمَعُ كُلُّ امْرِئٍ مِنْهُمْ اَنْ يُدْخَلَ جَنَّةَ نَع۪يمٍۙ', 'E yatmeu kullumriin minhum en yudhale cennete naim.', 'Onların her biri Nimet Cennetine konulacağını mi umuyor?', 'ايطمع كل امري منهم ان يدخل جنة نعيم'),
(5414, 70, 39, 'كَلَّاۜ  اِنَّا خَلَقْنَاهُمْ مِمَّا يَعْلَمُونَ', 'Kella, inna halaknahum mimma ya\'lemun.', 'Hayır,  boşuna ummasınlar! Biz,  onları bildikleri şeyden yarattık.', 'كلا انا خلقنهم مما يعلمون'),
(5415, 70, 40, 'فَلَٓا اُقْسِمُ بِرَبِّ الْمَشَارِقِ وَالْمَغَارِبِ اِنَّا لَقَادِرُونَۙ', 'Fe la uksimu bi rabbil meşarikı vel megaribi inna le kadirun.', 'Hayır,  öyle değil! Doğuların ve batıların Rabb\'ine yemin ederim ki kesinlikle Bizim her şeye gücümüz yeter;', 'فلا اقسم برب المشرق والمغرب انا لقدرون'),
(5416, 70, 41, 'عَلٰٓى اَنْ نُبَدِّلَ خَيْراً مِنْهُمْۙ وَمَا نَحْنُ بِمَسْبُوق۪ينَ', 'Ala en nubeddile hayren minhum ve ma nahnu bi mesbukin.', 'Onların yerine,  kendilerinden daha hayırlısını getirmeye kesinlikle güç yetirenleriz. Bunu yapmamıza hiçbir güç engel olamaz.', 'علي ان نبدل خيرا منهم وما نحن بمسبوقين'),
(5417, 70, 42, 'فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتّٰى يُلَاقُوا يَوْمَهُمُ الَّذ۪ي يُوعَدُونَۙ', 'Fe zerhum yehudu ve yel\'abu hatta yulaku yevme humullezi yuadun.', 'Artık onları kendi hallerine bırak. Uyarıldıkları günleri gelip çatıncaya kadar gaflet içinde oyalanıp dursunlar.', 'فذرهم يخوضوا ويلعبوا حتي يلقوا يومهم الذي يوعدون'),
(5418, 70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ الْاَجْدَاثِ سِرَاعاً  كَاَنَّهُمْ اِلٰى نُصُبٍ يُوفِضُونَۙ', 'Yevme yahrucune minel ecdasi siraan ke ennehum ila nusubin yufidun.', 'O gün,  onlar kabirlerinden fırlayıp çıkarlar. Sanki bir hedefe koşuyor gibi;', 'يوم يخرجون من الاجداث سراعا كانهم الي نصب يوفضون'),
(5419, 70, 44, 'خَاشِعَةً اَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌۜ ذٰلِكَ الْيَوْمُ الَّذ۪ي كَانُوا يُوعَدُونَ', 'Haşi\'aten ebsaruhum terhekuhum zilleh, zalikel yevmullezi kanu yuadun.', 'Gözlerinde korku,  kendilerini zillet bürümüş halde. İşte bu,  onların uyarıldıkları gündür.', 'خشعة ابصرهم ترهقهم ذلة ذلك اليوم الذي كانوا يوعدون'),
(5420, 71, 1, 'اِنَّٓا اَرْسَلْنَا نُوحاً اِلٰى قَوْمِه۪ٓ اَنْ اَنْذِرْ قَوْمَكَ مِنْ قَبْلِ اَنْ يَأْتِيَهُمْ عَذَابٌ اَل۪يمٌ', 'İnna erselna nuhan ila kavmihi en enzir kavmeke min kabli en ye\'tiyehum azabun elim.', 'Biz Nuh\'u halkına,  kendilerine acı veren bir azap gelmezden önce onları uyarması için gönderdik.', 'انا ارسلنا نوحا الي قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم'),
(5421, 71, 2, 'قَالَ يَا قَوْمِ اِنّ۪ي لَـكُمْ نَذ۪يرٌ مُب۪ينٌۙ', 'Kale ya kavmi inni lekum nezirun mubin.', '\"Ey halkım! Ben,  sizin için apaçık bir uyarıcıyım.\" dedi.', 'قال يقوم اني لكم نذير مبين'),
(5422, 71, 3, 'اَنِ اعْبُدُوا اللّٰهَ وَاتَّقُوهُ وَاَط۪يعُونِۙ', 'Eni\'budullahe vettekuhu ve etiun.', '\"Allah\'a kulluk edin[1],  O\'nun için takva[1] sahibi olun ve bana itaat edin.\"', 'ان اعبدوا الله واتقوه واطيعون'),
(5423, 71, 4, 'يَغْفِرْ لَـكُمْ مِنْ ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ اِلٰٓى اَجَلٍ مُسَمًّىۜ اِنَّ اَجَلَ اللّٰهِ اِذَا جَٓاءَ لَا يُؤَخَّرُۢ  لَوْ كُنْتُمْ تَعْلَمُونَ', 'Yagfir lekum min zunubikum ve yuahhırkum ila ecelin musemma, inne ecelallahi iza cae la yuahhar, lev kuntum ta\'lemun.', '\"Ki Allah,  suçlarınızı bağışlasın ve size belirlenmiş bir sürenin sonuna kadar zaman versin. Kuşkusuz Allah\'ın belirlediği süre dolunca,  ertelenmez. Keşke bilenlerden olsaydınız.\"', 'يغفر لكم من ذنوبكم ويوخركم الي اجل مسمي ان اجل الله اذا جا لا يوخر لو كنتم تعلمون'),
(5424, 71, 5, 'قَالَ رَبِّ اِنّ۪ي دَعَوْتُ قَوْم۪ي لَيْلاً وَنَهَاراًۙ', 'Kale rabbi inni deavtu kavmi leylen ve nehara.', '\"Rabb\'im! Ben,  Halkıma gece gündüz çağrıda bulundum.\" dedi.', 'قال رب اني دعوت قومي ليلا ونهارا'),
(5425, 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَٓاء۪ٓي اِلَّا فِرَاراً', 'Fe lem yezidhum duai illa firara.', '\"Fakat benim çağrım,  onların kaçışlarını daha da artırdı.\"', 'فلم يزدهم دعاي الا فرارا'),
(5426, 71, 7, 'وَاِنّ۪ي كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُٓوا اَصَابِعَهُمْ ف۪ٓي اٰذَانِهِمْ وَاسْتَغْشَوْا ثِيَابَهُمْ وَاَصَرُّوا وَاسْتَكْبَرُوا اسْتِكْبَاراًۚ', 'Ve inni kullema deavtuhum li tagfire lehum cealu esabiahum fi azanihim vestagşev siyabehum ve esarru vestekberustikbara.', '\"Öyle ki onları ne zaman Senin bağışlayıcılığına çağırdıysam parmaklarını kulaklarına tıkadılar,  elbiselerine büründüler[1] ısrarla kibirlendikçe kibirlendiler.\"', 'واني كلما دعوتهم لتغفر لهم جعلوا اصبعهم في اذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا'),
(5427, 71, 8, 'ثُمَّ اِنّ۪ي دَعَوْتُهُمْ جِهَاراًۙ', 'Summe inni deavtuhum cihara.', '\"Sonra onlara açık açık her fırsatta çağrıda bulundum.\"', 'ثم اني دعوتهم جهارا'),
(5428, 71, 9, 'ثُمَّ اِنّ۪ٓي اَعْلَنْتُ لَهُمْ وَاَسْرَرْتُ لَهُمْ اِسْرَاراًۙ', 'Summe inni a\'lentu lehum ve esrartu lehum israra.', '\"Sonra onlara; çağrımı toplu olarak da bire bir görüşerek de ilettim.\"', 'ثم اني اعلنت لهم واسررت لهم اسرارا'),
(5429, 71, 10, 'فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ اِنَّهُ  كَانَ غَفَّاراًۙ', 'Fe kul tustagfıru rabbekum innehu kane gaffara.', '\"Rabb\'inizden bağışlanma dileyin. Kuşkusuz O,  çok bağışlayandır.\" dedim.', 'فقلت استغفروا ربكم انه كان غفارا'),
(5430, 71, 11, 'يُرْسِلِ السَّمَٓاءَ عَلَيْكُمْ مِدْرَاراًۙ', 'Yursilis semae aleykum midrara.', '\"Gökten üzerinize bol yağmur göndersin.\"', 'يرسل السما عليكم مدرارا'),
(5431, 71, 12, 'وَيُمْدِدْكُمْ بِاَمْوَالٍ وَبَن۪ينَ وَيَجْعَلْ لَكُمْ جَنَّاتٍ وَيَجْعَلْ لَكُمْ اَنْهَاراًۜ', 'Ve yumdidkum biemvalin ve benine ve yec\'al lekum cennatin ve yec\'al lekum enhara.', '\"Size mal mülk ve oğullarla[1] yardım etsin. Ve sizin için bahçeler yapsın,  nehirler akıtsın.\"', 'ويمددكم بامول وبنين ويجعل لكم جنت ويجعل لكم انهرا'),
(5432, 71, 13, 'مَا لَكُمْ لَا تَرْجُونَ لِلّٰهِ وَقَاراًۚ', 'Ma lekum la tercune lillahi vekara.', '\"Size ne oluyor ki Allah\'ın büyüklüğünü takdir etmiyorsunuz?\"', 'ما لكم لا ترجون لله وقارا'),
(5433, 71, 14, 'وَقَدْ خَلَقَكُمْ اَطْوَاراً', 'Ve kad halakakum etvara.', '\"Oysa O,  sizi çeşitli aşamalardan geçirerek yarattı.\"', 'وقد خلقكم اطوارا'),
(5434, 71, 15, 'اَلَمْ تَرَوْا كَيْفَ خَلَقَ اللّٰهُ سَبْعَ سَمٰوَاتٍ طِبَاقاًۙ', 'E lem terev keyfe halakallahu seb\'a semavatin tıbaka.', '\"Allah\'ın yedi göğü nasıl tabakalar halinde[1] yarattığını görmüyor musunuz?\"[2]', 'الم تروا كيف خلق الله سبع سموت طباقا'),
(5435, 71, 16, 'وَجَعَلَ الْقَمَرَ ف۪يهِنَّ نُوراً وَجَعَلَ الشَّمْسَ سِرَاجاً', 'Ve cealel kamere fihinne nuren ve cealeş şemse siraca.', '\"Ve Ay\'ı onların içinde bir nur,  Güneş\'i de kandil yaptı.\"', 'وجعل القمر فيهن نورا وجعل الشمس سراجا'),
(5436, 71, 17, 'وَاللّٰهُ اَنْبَتَكُمْ مِنَ الْاَرْضِ نَبَاتاًۙ', 'Vallahu enbetekum minel ardı nebata.', '\"Allah,  sizi yerden[1] bir bitki gibi bitirdi.\"', 'والله انبتكم من الارض نباتا'),
(5437, 71, 18, 'ثُمَّ يُع۪يدُكُمْ ف۪يهَا وَيُخْرِجُكُمْ اِخْرَاجاً', 'Summe yuidukum fiha ve yuhricukum ihraca.', '\"Sonra sizi toprağa döndürecek ve ardından bir çıkışla oradan çıkaracak.\"', 'ثم يعيدكم فيها ويخرجكم اخراجا'),
(5438, 71, 19, 'وَاللّٰهُ جَعَلَ لَـكُمُ الْاَرْضَ بِسَاطاًۙ', 'Vallahu ceale lekumul arda bisata.', '\"Allah,  yeryüzünü sizin için genişçe yaydı.\"', 'والله جعل لكم الارض بساطا'),
(5439, 71, 20, 'لِتَسْلُكُوا مِنْهَا سُبُلاً فِجَاجاً۟', 'Li tesluku minha subulen ficaca.', '\"Yolculuk etmeniz için orada geniş yollar yaptı.\"', 'لتسلكوا منها سبلا فجاجا'),
(5440, 71, 21, 'قَالَ نُوحٌ رَبِّ اِنَّهُمْ عَصَوْن۪ي وَاتَّبَعُوا مَنْ لَمْ يَزِدْهُ مَالُهُ وَوَلَدُهُٓ  اِلَّا خَسَاراًۚ', 'Kale nuhun rabbi innehum asavni vettebeu men lem yezidhu maluhu ve veleduhu illa hasara.', 'Nuh: \"Rabb\'im! Kuşkusuz onlar bana asi oldular. Malı ve evladı kendisine zarardan başka bir şey artırmayan kimseye uydular.\" dedi.', 'قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا'),
(5441, 71, 22, 'وَمَكَرُوا مَكْراً كُبَّاراًۚ', 'Ve mekeru mekren kubbara.', '\"Büyük tuzaklarla tuzak kurdular.\"', 'ومكروا مكرا كبارا'),
(5442, 71, 23, 'وَقَالُوا لَا تَذَرُنَّ اٰلِهَتَكُمْ وَلَا تَذَرُنَّ وَداًّ وَلَا سُوَاعاًۙ وَلَا يَغُوثَ وَيَعُوقَ وَنَسْراًۚ', 'Ve kalu la tezerunne alihetekum ve la tezerrunne vedden ve la suvaan ve la yeguse ve yeuka ve nesra.', '\"Sakın ilahlarınızı bırakmayın; sakın Vedd\'i[1],  Suva\'yı[2],  Yeğus\'u[3],  Yeuk\'u[4] ve Nesr\'i[5] bırakmayın.\" dediler.', 'وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا'),
(5443, 71, 24, 'وَقَدْ اَضَلُّوا كَث۪يراًۚ وَلَا تَزِدِ الظَّالِم۪ينَ اِلَّا ضَلَالاً', 'Ve kad edallu kesira, ve la tezidiz zalimine illa dalala.', '\"Pek çoğunu saptırdılar. Sen de bu zalimlerin şaşkınlıklarından başka bir şeylerini artırma!\"', 'وقد اضلوا كثيرا ولا تزد الظلمين الا ضللا'),
(5444, 71, 25, 'مِمَّا خَط۪ٓيـَٔاتِهِمْ اُغْرِقُوا فَاُدْخِلُوا نَاراً فَلَمْ يَجِدُوا لَهُمْ مِنْ دُونِ اللّٰهِ اَنْصَاراً', 'Mimma hatiatihim ugriku fe udhılu naran fe lem yecıdu lehum min dunillahi ensara.', 'Onlar,  yanlışları nedeniyle suda boğuldular. Sonra ateşe atıldılar. Kendilerine Allah\'tan başka yardımcı bulamadılar.[1]', 'مما خطيتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا'),
(5445, 71, 26, 'وَقَالَ نُوحٌ رَبِّ لَا تَذَرْ عَلَى الْاَرْضِ مِنَ الْكَافِر۪ينَ دَيَّاراً', 'Ve kale nuhun rabbi la tezer alel ardı minel kafirine deyyara.', 'Nuh: \"Rabb\'im! Gerçeği yalanlayan nankörlerden yeryüzünde hiç kimseyi bırakma.\" dedi.', 'وقال نوح رب لا تذر علي الارض من الكفرين ديارا'),
(5446, 71, 27, 'اِنَّكَ اِنْ تَذَرْهُمْ يُضِلُّوا عِبَادَكَ وَلَا يَلِدُٓوا اِلَّا فَاجِراً كَفَّاراً', 'İnneke in tezerhum yudıllu ıbadeke ve la yelidu illa faciren keffara.', '\"Çünkü onları bırakınca,  kullarını saptırıyorlar; yalnızca facir[1] ve Kafir[2] kimseler yetiştiriyorlar.\"', 'انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا'),
(5447, 71, 28, 'رَبِّ اغْفِرْ ل۪ي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِناً وَلِلْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِۜ وَلَا تَزِدِ الظَّالِم۪ينَ اِلَّا تَبَاراً', 'Rabbigfirli ve li valideyye ve li men dehale beytiye mu\'minen ve lil mu\'minine vel mu\'minat ve la tezidiz zalimine illa tebara.', '\"Rabbim! Beni,  annemi,  babamı ve mü\'min olarak evime girenleri ve mü\'min erkekleri ve mü\'min kadınları bağışla. Zalimlerin yalnızca tükenişlerini arttır.\"', 'رب اغفر لي ولولدي ولمن دخل بيتي مومنا وللمومنين والمومنت ولا تزد الظلمين الا تبارا'),
(5448, 72, 1, 'قُلْ اُو۫حِيَ اِلَيَّ اَنَّهُ اسْتَمَعَ نَفَرٌ مِنَ الْجِنِّ فَقَالُٓوا اِنَّا سَمِعْنَا قُرْاٰناً عَجَباًۙ', 'Kul uhıye ileyye ennehustemea neferun minel cinni fe kalu inna semi\'na kur\'anen aceba.', 'De ki: \"Bana,  cinlerden[1] bir topluluğun dinledikten sonra gidip; biz gerçekten hayranlık uyandıran bir kur\'an[2] dinledik,  dedikleri,  vahyolundu.\"', 'قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرانا عجبا'),
(5449, 72, 2, 'يَهْد۪ٓي اِلَى الرُّشْدِ فَاٰمَنَّا بِه۪ۜ وَلَنْ نُشْرِكَ بِرَبِّنَٓا اَحَداًۙ', 'Yehdi iler ruşdi fe amenna bih, ve len nuşrike bi rabbina ehada.', '\"Her konuda doğru yola iletiyor; ona iman ettik. Artık kesinlikle Rabb\'imize hiçbir şeyi ortak koşmayacağız.\"', 'يهدي الي الرشد فامنا به ولن نشرك بربنا احدا'),
(5450, 72, 3, 'وَاَنَّهُ تَعَالٰى جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَداًۙ', 'Ve ennehu teala ceddu rabbina mettehaze sahıbeten ve la veleda.', '\"Rabb\'imizin şanı çok yücedir. O,  asla eş ve çocuk edinmemiştir.\"', 'وانه تعلي جد ربنا ما اتخذ صحبة ولا ولدا'),
(5451, 72, 4, 'وَاَنَّهُ  كَانَ يَقُولُ سَف۪يهُنَا عَلَى اللّٰهِ شَطَطاًۙ', 'Ve ennehu kane yekulu sefihuna alallahi şetata.', '\"Meğer bizim \"beyinsiz, \"[1] Allah hakkında saçma şeyler söylüyormuş\"', 'وانه كان يقول سفيهنا علي الله شططا'),
(5452, 72, 5, 'وَاَنَّا ظَنَنَّٓا اَنْ لَنْ تَقُولَ الْاِنْسُ وَالْجِنُّ عَلَى اللّٰهِ كَذِباًۙ', 'Ve enna zanenna en len tekulel insu vel cinnu alallahi keziba.', '\"Doğrusu biz insin ve cinnin[1] Allah\'a karşı asla yalan söylemeyeceklerine inanıyorduk.\"', 'وانا ظننا ان لن تقول الانس والجن علي الله كذبا'),
(5453, 72, 6, 'وَاَنَّهُ كَانَ رِجَالٌ مِنَ الْاِنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقاًۙ', 'Ve ennehu kane ricalun minel insi yeuzune bi ricalin minel cinni fe zaduhum reheka.', 'Gerçekten de insten[1] bazı adamlar,  cinden[2] bazı adamlara[3] sığınıyorlardı. Böylece onların[4] azgınlıklarını,  beyinsizliklerini artırıyorlardı.', 'وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا'),
(5454, 72, 7, 'وَاَنَّهُمْ ظَنُّوا كَمَا ظَنَنْتُمْ اَنْ لَنْ يَبْعَثَ اللّٰهُ اَحَداًۙ', 'Ve ennehum zannu kema zanentum en len yeb\'asallahu ehada.', 'Gerçekten de onlar sizin sandığınız gibi,  Allah\'ın hiç kimseyi diriltmeyeceğini sanmışlardı.', 'وانهم ظنوا كما ظننتم ان لن يبعث الله احدا'),
(5455, 72, 8, 'وَاَنَّا لَمَسْنَا السَّمَٓاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَساً شَد۪يداً وَشُهُباًۙ', 'Ve enna le mesnes semae fe vecednaha muliet haresen şediden ve şuhuba.', '\"Gerçekten de biz göğe erişmek istedik,  fakat onun zorlu bekçiler ve ışınlarla doldurulmuş olduğunu gördük.\"', 'وانا لمسنا السما فوجدنها مليت حرسا شديدا وشهبا'),
(5456, 72, 9, 'وَاَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِۜ فَمَنْ يَسْتَمِعِ الْاٰنَ يَجِدْ لَهُ شِهَاباً رَصَداًۙ', 'Ve enna kunna nak\'udu minha mekaıde lis sem\'i fe men yestemiıl ane yecid lehu şihaben rasada.', '\"Biz,  dinlemek için oturma yerlerine otururduk. Fakat şimdi kim dinlemek isterse,  kendisini gözetleyen bir ışın buluyor.\"', 'وانا كنا نقعد منها مقعد للسمع فمن يستمع الان يجد له شهابا رصدا'),
(5457, 72, 10, 'وَاَنَّا لَا نَدْر۪ٓي اَشَرٌّ اُر۪يدَ بِمَنْ فِي الْاَرْضِ اَمْ اَرَادَ بِهِمْ رَبُّهُمْ رَشَداًۙ', 'Ve enna la nedri eşerrun uride bi men fil ardı em erade bi him rabbuhum reşeda.', '\"Gerçekten bilmiyoruz. Yeryüzünde olan kimselere kötülük mü istendi yoksa Rabb\'leri onlara bir iyilik mi istedi bilmiyoruz.\"', 'وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا'),
(5458, 72, 11, 'وَاَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذٰلِكَۜ كُنَّا طَرَٓائِقَ قِدَداًۙ', 'Ve enna minnes salihune ve minna dune zalik, kunna taraika kıdeda.', '\"Doğrusu bir kısmımız salihlerdeniz,  bir kısmımız da bunun dışındadır. Biz,  ayrı ayrı yollar tuttuk.\"', 'وانا منا الصلحون ومنا دون ذلك كنا طرايق قددا'),
(5459, 72, 12, 'وَاَنَّا ظَنَنَّٓا اَنْ لَنْ نُعْجِزَ اللّٰهَ فِي الْاَرْضِ وَلَنْ نُعْجِزَهُ هَرَباًۙ', 'Ve enna zanenna en len nu\'cizallahe fil ardı ve len nu\'cizehu hereba.', '\"Doğrusu biz,  Yeryüzünde Allah\'ı asla aciz bırakamayacağımızı; kaçmakla da O\'ndan asla kurtulamayacağımızı anladık.\"', 'وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا'),
(5460, 72, 13, 'وَاَنَّا لَمَّا سَمِعْنَا الْهُدٰٓى اٰمَنَّا بِه۪ۜ فَمَنْ يُؤْمِنْ بِرَبِّه۪ فَلَا يَخَافُ بَخْساً وَلَا رَهَقاًۙ', 'Ve enna lemma semi\'nel huda amenna bih, fe men yu\'min bi rabbihi fe la yehafu bahsen ve la reheka.', '\"Yol gösteren rehberi[1] dinlediğimizde ona inandık. Artık kim Rabb\'ine iman ederse,  bundan sonra hakkının verilmemesinden veya haksızlığa uğramaktan endişe etmez.\"', 'وانا لما سمعنا الهدي امنا به فمن يومن بربه فلا يخاف بخسا ولا رهقا'),
(5461, 72, 14, 'وَاَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَۜ  فَمَنْ اَسْلَمَ فَاُو۬لٰٓئِكَ تَحَرَّوْا رَشَداً', 'Ve enna minnel muslimune ve minnel kasitun, fe men esleme fe ulaike teharrev reşeda.', '\"Bizden,  Allah\'a teslim olanlar da var,  asilik edip kendilerine haksızlık yapanlar da. Allah\'a teslim olanlar,  gerçeği arayanlardır.\"', 'وانا منا المسلمون ومنا القسطون فمن اسلم فاوليك تحروا رشدا'),
(5462, 72, 15, 'وَاَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَباًۙ', 'Ve emmel kasitune fe kanu li cehenneme hataba.', 'Asilik edip kendilerine haksızlık yapanlar,  işte onlar Cehennem\'e odun oldular.', 'واما القسطون فكانوا لجهنم حطبا'),
(5463, 72, 16, 'وَاَنْ لَوِ اسْتَقَامُوا عَلَى الطَّر۪يقَةِ لَاَسْقَيْنَاهُمْ مَٓاءً غَدَقاًۙ', 'Ve en levistekamu alet tarikati le eskaynahum maen gadeka.', 'Eğer onlar,  yolda[1] dosdoğru gitselerdi,  onları kesinlikle bol su[2] ile sulardık ki;', 'والو - استقموا علي الطريقة لاسقينهم ما غدقا'),
(5464, 72, 17, 'لِنَفْتِنَهُمْ ف۪يهِۚ وَمَنْ يُعْرِضْ عَنْ ذِكْرِ رَبِّه۪ يَسْلُكْهُ عَذَاباً صَعَداًۙ', 'Li neftinehum fih, ve men yu\'rıd an zikri rabbihi yeslukhu azaben saada.', 'Onları bu nimetlerle sınardık. Kim Rabb\'inin öğüdünden yüz çevirirse,  O da onu çok şiddetli bir azaba uğratır.', 'لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا'),
(5465, 72, 18, 'وَاَنَّ الْمَسَاجِدَ لِلّٰهِ فَلَا تَدْعُوا مَعَ اللّٰهِ اَحَداًۙ', 'Ve ennel mesacide lillahi fe la ted\'u maallahi ehada.', 'Mescitler Allah içindir. O halde Allah\'ın yanı sıra başka bir kimseye çağrıda bulunmayın.[1]', 'وان المسجد لله فلا تدعوا مع الله احدا'),
(5466, 72, 19, 'وَاَنَّهُ لَمَّا قَامَ عَبْدُ اللّٰهِ يَدْعُوهُ كَادُوا يَكُونُونَ عَلَيْهِ لِبَداًۜ۟', 'Ve ennehu lemma kame abdullahi yeduhu kadu yekunune aleyhi libeda.', 'O Allah\'ın kulu[1],  O\'na çağrıda bulunmaya kalktığı zaman,  neredeyse çevresinde keçe gibi oluyorlardı.[2]', 'وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا'),
(5467, 72, 20, 'قُلْ اِنَّمَٓا اَدْعُوا رَبّ۪ي وَلَٓا اُشْرِكُ بِه۪ٓ اَحَداً', 'Kul innema ed\'u rabbi ve la uşriku bihi ehada.', 'De ki: \"Ben yalnızca Rabb\'ime dua ederim ve hiçbir şeyi O\'na şirk koşmam.\"', 'قل انما ادعوا ربي ولا اشرك به احدا'),
(5468, 72, 21, 'قُلْ اِنّ۪ي لَٓا اَمْلِكُ لَكُمْ ضَراًّ وَلَا رَشَداً', 'Kul inni la emliku lekum darren ve la reşeda.', 'De ki: \"Ben,  size bir zarar verme[1] ve sizi irşad[2] etme gücüne sahip değilim.\"', 'قل اني لا املك لكم ضرا ولا رشدا'),
(5469, 72, 22, 'قُلْ اِنّ۪ي لَنْ يُج۪يرَن۪ي مِنَ اللّٰهِ اَحَدٌ وَلَنْ اَجِدَ مِنْ دُونِه۪ مُلْتَحَداًۙ', 'Kul inni len yucireni minallahi ehadun ve len ecide min dunihi multehada.', 'De ki: \"Beni,  Allah\'a karşı hiç kimse koruyamaz ve ben asla O\'ndan başka sığınacak bir yer bulamam.\"', 'قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا'),
(5470, 72, 23, 'اِلَّا بَلَاغاً مِنَ اللّٰهِ وَرِسَالَاتِه۪ۜ وَمَنْ يَعْصِ اللّٰهَ وَرَسُولَهُ فَاِنَّ لَهُ نَارَ جَهَنَّمَ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ', 'İlla belagan minallahi ve risalatih, ve men ya\'sıllahe ve resulehu fe inne lehu nare cehenneme halidine fiha ebeda.', '\"Bana düşen sadece Allah\'tan aldığım vahyi size duyurmak ve gönderileni iletmektir. Kim Allah\'a ve O\'nun Resulüne[1] karşı gelirse,  bilsin ki onun için kesintisiz olarak sürekli içinde kalacağı Cehennem ateşi vardır.\"', 'الا بلغا من الله ورسلته ومن يعص الله ورسوله فان له نار جهنم خلدين فيها ابدا'),
(5471, 72, 24, 'حَتّٰٓى اِذَا رَاَوْا مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ اَضْعَفُ نَاصِراً وَاَقَلُّ عَدَداً', 'Hatta iza reev ma yuadune fe se ya\'lemune men ad\'afu nasıren ve ekallu adeda.', 'Uyarıldıkları şeyi gördükleri zaman,  kimin yardımcısının daha zayıf ve kimsesiz olduğunu bilecekler.', 'حتي اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا'),
(5472, 72, 25, 'قُلْ اِنْ اَدْر۪ٓي اَقَر۪يبٌ مَا تُوعَدُونَ اَمْ يَجْعَلُ لَهُ رَبّ۪ٓي اَمَداً', 'Kul in edri e karibun ma tuadune em yec\'alu lehu rabbi emeda.', 'De ki: \"Uyarıldığınız şey yakın mıdır,  yoksa Rabb\'im onun için uzun bir süre mi belirlemiştir,  bilmiyorum.\"', 'قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا'),
(5473, 72, 26, 'عَالِمُ الْغَيْبِ فَلَا يُظْهِرُ عَلٰى غَيْبِه۪ٓ اَحَداًۙ', 'Alimul gaybi fe la yuzhiru ala gaybihi ehada.', 'O,  gaybı bilendir. Ve O,  gaybını hiç kimseye bildirmez;', 'علم الغيب فلا يظهر علي غيبه احدا'),
(5474, 72, 27, 'اِلَّا مَنِ ارْتَضٰى مِنْ رَسُولٍ فَاِنَّهُ يَسْلُكُ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِه۪ رَصَداًۙ', 'İlla menirteda min resulin fe innehu yesluku min beyni yedeyhi ve min halfihi rasada.', 'Resullerden razı oldukları hariç.[1] O,  onların her tarafından gözetleyiciler gönderir;[2]', 'الا من ارتضي من رسول فانه يسلك من بين يديه ومن خلفه رصدا'),
(5475, 72, 28, 'لِيَعْلَمَ اَنْ قَدْ اَبْلَغُوا رِسَالَاتِ رَبِّهِمْ وَاَحَاطَ بِمَا لَدَيْهِمْ وَاَحْصٰى كُلَّ شَيْءٍ عَدَداً', 'Li ya\'leme en kad eblegu rısalati rabbihim ve ehata bima ledeyhim ve ahsa kulle şey\'in adeda.', 'Rabb\'lerinin mesajlarını tebliğ ettiklerini bilmek için.[1] Yanlarında olanları kuşatmış ve her şeyi kayıt altına almıştır.', 'ليعلم ان قد ابلغوا رسلت ربهم واحاط بما لديهم واحصي كل شي عددا'),
(5476, 73, 1, 'يَٓا اَيُّهَا الْمُزَّمِّلُۙ', 'Ya eyyuhel muzzemmil.', 'Ey örtüsüne bürünen![1]', 'يايها المزمل'),
(5477, 73, 2, 'قُمِ الَّيْلَ اِلَّا قَل۪يلاًۙ', 'Kumil leyle illa kalila.', 'Gecenin birazında kalk!', 'قم اليل الا قليلا'),
(5478, 73, 3, 'نِصْفَهُٓ  اَوِ انْقُصْ مِنْهُ قَل۪يلاًۙ', 'Nısfehu evinkus minhu kalila.', 'Gecenin yarısında veya ondan biraz önce.', 'نصفه او انقص منه قليلا'),
(5479, 73, 4, 'اَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْاٰنَ تَرْت۪يلاًۜ', 'Ey zid aleyhi ve rettilil kur\'ane tertila.', 'Veya gecenin yarısından[1] biraz sonra. Ve daveti düzgün bir şekilde[2] duyur.[3]', 'او زد عليه ورتل القران ترتيلا'),
(5480, 73, 5, 'اِنَّا سَنُلْق۪ي عَلَيْكَ قَوْلاً ثَق۪يلاًۜ', 'İnna se nulki aleyke kavlen sekila.', 'Biz,  sana ağır bir söz bırakacağız.[1]', 'انا سنلقي عليك قولا ثقيلا'),
(5481, 73, 6, 'اِنَّ نَاشِئَةَ الَّيْلِ هِيَ اَشَدُّ وَطْـٔاً وَاَقْوَمُ ق۪يلاًۜ', 'İnne naşietel leyli hiye eşeddu vat\'en ve akvemu kila.', 'Kuşkusuz gece,  bir oluşu gerçekleştirmek için söz[1] bakımından daha etkilidir.', 'ان ناشية اليل هي اشد وطا واقوم قيلا'),
(5482, 73, 7, 'اِنَّ لَكَ فِي النَّهَارِ سَبْحاً طَو۪يلاًۜ', 'İnne leke fin nehari sebhan tavila.', 'Gündüz,  uzun süre uğraşacağın işler var.', 'ان لك في النهار سبحا طويلا'),
(5483, 73, 8, 'وَاذْكُرِ اسْمَ رَبِّكَ وَتَبَتَّلْ اِلَيْهِ تَبْت۪يلاًۜ', 'Vezkurisme rabbike ve tebettel ileyhi tebtila.', 'Rabb\'inin adını an ve bütün benliğinle yalnızca O\'na yönel.', 'واذكر اسم ربك وتبتل اليه تبتيلا'),
(5484, 73, 9, 'رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ لَٓا اِلٰهَ اِلَّا هُوَ فَاتَّخِذْهُ وَك۪يلاً', 'Rabbul meşrıkı vel magribi la ilahe illa huve fettehızhu vekila.', 'Doğunun ve batının Rabb\'idir O. O\'ndan başka ilah yoktur. Öyleyse yalnız O\'nu vekil[1] edin.', 'رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا'),
(5485, 73, 10, 'وَاصْبِرْ عَلٰى مَا يَقُولُونَ وَاهْجُرْهُمْ هَجْراً جَم۪يلاً', 'Vasbir ala ma yekulune vehcurhum hecren cemila.', 'Onların söylediklerine sabret. Ve onlardan güzellikle uzak dur.', 'واصبر علي ما يقولون واهجرهم هجرا جميلا'),
(5486, 73, 11, 'وَذَرْن۪ي وَالْمُكَذِّب۪ينَ اُو۬لِي النَّعْمَةِ وَمَهِّلْهُمْ قَل۪يلاً', 'Ve zerni vel mukezzibine ulin na\'meti ve mehhilhum kalila.', 'Varlık sahibi,  yalanlayıcıları Bana bırak. Onlara biraz süre tanı.', 'وذرني والمكذبين اولي النعمة ومهلهم قليلا'),
(5487, 73, 12, 'اِنَّ لَدَيْنَٓا اَنْكَالاً وَجَح۪يماًۙ', 'İnne ledeyna enkalen ve cahima.', 'Bizim yanımızda prangalar ve Cehennem var.', 'ان لدينا انكالا وجحيما'),
(5488, 73, 13, 'وَطَعَاماً ذَا غُصَّةٍ وَعَذَاباً اَل۪يماً', 'Ve taamen za gussatin ve azaben elima.', 'Ve boğazı tıkayan yiyecek ve acı bir azap vardır.', 'وطعاما ذا غصة وعذابا اليما'),
(5489, 73, 14, 'يَوْمَ تَرْجُفُ الْاَرْضُ وَالْجِبَالُ وَكَانَتِ الْجِبَالُ كَث۪يباً مَه۪يلاً', 'Yevme tercuful ardu vel cibalu ve kanetil cibalu kesiben mehila.', 'O gün yeryüzü ve dağlar şiddetle sarsılır ve dağlar dağılmış kum yığınları gibi olur.', 'يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا'),
(5490, 73, 15, 'اِنَّٓا اَرْسَلْنَٓا اِلَيْكُمْ رَسُولاً شَاهِداً عَلَيْكُمْ كَمَٓا اَرْسَلْنَٓا اِلٰى فِرْعَوْنَ رَسُولاًۜ', 'İnna erselna ileykum resulen şahiden aleykum kema erselna ila fir\'avne resula.', 'Size tanıklık edecek bir resul gönderdik. Tıpkı Firavun\'a da bir resul gönderdiğimiz gibi.', 'انا ارسلنا اليكم رسولا شهدا عليكم كما ارسلنا الي فرعون رسولا'),
(5491, 73, 16, 'فَعَصٰى فِرْعَوْنُ الرَّسُولَ فَاَخَذْنَاهُ اَخْذاً وَب۪يلاً', 'Fe asa fir\'avnur resule fe ehaznahu ahzen vebila.', 'Firavun Resul\'e isyan etti. Bunun üzerine onu çok zorlu bir tutuşla tutuverdik.', 'فعصي فرعون الرسول فاخذنه اخذا وبيلا'),
(5492, 73, 17, 'فَـكَيْفَ تَتَّقُونَ اِنْ كَفَرْتُمْ يَوْماً يَجْعَلُ الْوِلْدَانَ ش۪يباًۗ', 'Fe keyfe tettekune in kefertum yevmen yec\'alul vildane şiba.', 'Eğer Kafirlerden olursanız,  çocukların saçlarını ağartan o günden kendinizi nasıl koruyacaksınız?', 'فكيف تتقون ان كفرتم يوما يجعل الولدن شيبا'),
(5493, 73, 18, 'اَلسَّمَٓاءُ مُنْفَطِرٌ بِه۪ۜ   كَانَ وَعْدُهُ مَفْعُولاً', 'Es semau munfatırun bih, kane va\'duhu mef\'ula.', 'Gök,  o günün şiddeti ile çatlayıp parçalanacak ve O\'nun uyarısı gerçekleşecektir.', 'السما منفطر به كان وعده مفعولا'),
(5494, 73, 19, 'اِنَّ هٰذِه۪ تَذْكِرَةٌۚ  فَمَنْ شَٓاءَ اتَّخَذَ اِلٰى رَبِّه۪ سَب۪يلاً۟', 'İnne hazihi tezkirah, fe men şaettehaze ila rabbihi sebila.', 'Bu bir öğüttür. Dileyen Rabb\'ine götüren bir yol edinir.', 'ان هذه تذكرة فمن شا اتخذ الي ربه سبيلا'),
(5495, 73, 20, 'اِنَّ رَبَّكَ يَعْلَمُ اَنَّكَ تَقُومُ اَدْنٰى مِنْ ثُلُثَيِ الَّيْلِ وَنِصْفَهُ وَثُلُثَهُ وَطَٓائِفَةٌ مِنَ الَّذ۪ينَ مَعَكَۜ وَاللّٰهُ يُقَدِّرُ الَّيْلَ وَالنَّهَارَۜ عَلِمَ اَنْ لَنْ تُحْصُوهُ فَتَابَ عَلَيْكُمْ فَاقْرَؤُ۫ا مَا تَيَسَّرَ مِنَ الْقُرْاٰنِۜ عَلِمَ اَنْ سَيَكُونُ مِنْكُمْ مَرْضٰىۙ وَاٰخَرُونَ يَضْرِبُونَ فِي الْاَرْضِ يَبْتَغُونَ مِنْ فَضْلِ اللّٰهِۙ وَاٰخَرُونَ يُقَاتِلُونَ ف۪ي سَب۪يلِ اللّٰهِۘ فَاقْرَؤُ۫ا مَا تَيَسَّرَ مِنْهُۙ وَاَق۪يمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَقْرِضُوا اللّٰهَ قَرْضاً حَسَناًۜ وَمَا تُقَدِّمُوا لِاَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللّٰهِ هُوَ خَيْراً وَاَعْظَمَ اَجْراًۜ وَاسْتَغْفِرُوا اللّٰهَۜ  اِنَّ اللّٰهَ غَفُورٌ رَح۪يمٌ', 'İnne rabbeke ya\'lemu enneke tekumu edna min suluseyil leyli ve nısfehu ve sulusehu ve taifetun minellezine meak, vallahu yukaddirul leyle ven nehar, alime en len tuhsuhu fe tabe aleykum, fakreu ma teyessere minel kur\'an, alime en seyekunu minkum merda ve aharune yadribune fil\'ardı yebtegune min fadlillahi ve aharune yukatilune fi sebilillahi fakreu ma teyessere minhu ve ekimus salate ve atuz zekate ve akridullahe kardan hasena, ve ma tukaddimu li enfusikum min hayrin teciduhu indallahi huve hayren ve a\'zame ecra, vestagfirullah, innellahe gafurun rahim.', 'Rabb\'in,  senin bazen gecenin üçte ikisinden daha az,  bazen yarısı,  bazen üçte bir kadar vakit geçirdiğini elbette biliyor. Seninle beraber bulunanlardan bir grubun da. Geceyi ve gündüzü takdir eden Allah\'tır.[1] Onu asla hesaplayamayacağınızı[2] bildi de tevbenizi[3] kabul etti. O halde ilahi mesajı gücünüz yettiğince insanlara ulaştırmaya çalışın.[4] Ayrıca Allah,  içinizden kimin hasta olduğunu bilmektedir. Kiminizin Allah\'ın lütfundan rızkını aramak için yeryüzünde çalışmaya,  kiminizin de kendisini Allah yolunda feda etmeye[5] çıktığını bilmektedir. O halde gücünüz yettiğince onu[6] nakletmeye,  duyurmaya çalışın.[7] Salatı ikame edin[8],  zekatı yapın.[8] İyi bir ödünçle Allah\'a ödünç verin. Kendiniz için hayır olarak ne verirseniz,  ödül olarak Allah\'ın katında onu daha hayırlısıyla ve daha büyüğüyle bulursunuz. Allah\'tan bağışlanma dileyin. Kuşkusuz Allah,  Çok Bağışlayıcı\'dır,  Rahmeti Kesintisiz\'dir.', 'ان ربك يعلم انك تقوم ادني من ثلثي اليل ونصفه وثلثه وطايفة من الذين معك والله يقدر اليل والنهار علم ان لن تحصوه فتاب عليكم فاقروا ما تيسر من القران علم ان سيكون منكم مرضي واخرون يضربون في الارض يبتغون من فضل الله واخرون يقتلون في سبيل الله فاقروا ما تيسر منه واقيموا الصلوة واتوا الزكوة واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم'),
(5496, 74, 1, 'يَٓا اَيُّهَا الْمُدَّثِّرُۙ', 'Ya eyyuhel muddessir.', 'Ey örtüye bürünmüş olan.[1]', 'يايها المدثر'),
(5497, 74, 2, 'قُمْ فَاَنْذِرْۙ', 'Kum fe enzir.', 'Kalk ve uyarmaya başla.', 'قم فانذر'),
(5498, 74, 3, 'وَرَبَّكَ فَـكَبِّرْۙ', 'Ve rabbeke fe kebbir.', 'Rabb\'ini tekbir[1] et!', 'وربك فكبر'),
(5499, 74, 4, 'وَثِيَابَكَ فَطَهِّرْۙ', 'Ve siyabeke fe tahhir.', 'Ve örtünü hemen temizle.[1]', 'وثيابك فطهر'),
(5500, 74, 5, 'وَالرُّجْزَ فَاهْجُرْۙ', 'Verrucze fehcur.', 'Kirlilikten kaçın.[1]', 'والرجز فاهجر'),
(5501, 74, 6, 'وَلَا تَمْنُنْ تَسْتَكْثِرُۙ', 'Ve la temnun testeksir.', 'Karşılık bekleyerek iyilik yapma.[1]', 'ولا تمنن تستكثر'),
(5502, 74, 7, 'وَلِرَبِّكَ فَاصْبِرْۜ', 'Ve li rabbike fasbir.', 'Rabb\'in için sabret.[1]', 'ولربك فاصبر'),
(5503, 74, 8, 'فَاِذَا نُقِرَ فِي النَّاقُورِۙ', 'Fe iza nukıre fin naku.', 'Nakur\'a[1] üflendiği zaman.', 'فاذا نقر في الناقور'),
(5504, 74, 9, 'فَذٰلِكَ يَوْمَئِذٍ يَوْمٌ عَس۪يرٌۙ', 'Fe zalike yevme izin yevmun asi.', 'İşte o İzin Günü[1],  çok zorlu bir gündür;', 'فذلك يوميذ يوم عسير'),
(5505, 74, 10, 'عَلَى الْـكَافِر۪ينَ غَيْرُ يَس۪يرٍ', 'Alel kafirine gayru yesir.', 'Kafirler[1] için kolay olmayan.', 'علي الكفرين غير يسير'),
(5506, 74, 11, 'ذَرْن۪ي وَمَنْ خَلَقْتُ وَح۪يداًۙ', 'Zerni ve men halaktu vahida.', 'Tek olarak yarattığım kişiyi Bana bırak.[1]', 'ذرني ومن خلقت وحيدا'),
(5507, 74, 12, 'وَجَعَلْتُ لَهُ مَالاً مَمْدُوداًۙ', 'Ve ce\'altu lehu malen memduda.', 'Ona hesapsız mal verdim;', 'وجعلت له مالا ممدودا'),
(5508, 74, 13, 'وَبَن۪ينَ شُهُوداًۙ', 'Ve benine şuhuda.', 'Ve her zaman yanında olan evlatlar.', 'وبنين شهودا'),
(5509, 74, 14, 'وَمَهَّدْتُ لَهُ تَمْه۪يداًۙ', 'Ve mehhedtu lehu temhida.', 'Ona,  geniş imkanlar sağladım.', 'ومهدت له تمهيدا'),
(5510, 74, 15, 'ثُمَّ يَطْمَعُ اَنْ اَز۪يدَۗ', 'Summe yatmau en ezid.', 'Sonra hırsla daha da artırmamı ister.', 'ثم يطمع ان ازيد'),
(5511, 74, 16, 'كَلَّاۜ اِنَّهُ كَانَ لِاٰيَاتِنَا عَن۪يداًۜ', 'Kella, innehu kane li ayatina anida.', 'Hayır,  asla! O Bizim ayetlerimize karşı inat etti.', 'كلا انه كان لايتنا عنيدا'),
(5512, 74, 17, 'سَاُرْهِقُهُ صَعُوداًۜ', 'Se urhikuhu sauda.', 'Onu sarp bir yokuşa sardıracağım.', 'سارهقه صعودا'),
(5513, 74, 18, 'اِنَّهُ فَـكَّرَ وَقَدَّرَۙ', 'İnnehu fekkere ve kadder.', 'Düşündü ve karar verdi.', 'انه فكر وقدر'),
(5514, 74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَۙ', 'Fe kutile keyfe kadder.', 'O mahvoldu,  nasıl bir karar verdi![1]', 'فقتل كيف قدر'),
(5515, 74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَۙ', 'Summe kutile keyfe kadder.', 'Yine o mahvoldu. Nasıl bir karar verdi![1]', 'ثم قتل كيف قدر'),
(5516, 74, 21, 'ثُمَّ نَظَرَۙ', 'Summe nazar.', 'Sonra baktı!', 'ثم نظر'),
(5517, 74, 22, 'ثُمَّ عَبَسَ وَبَسَرَۙ', 'Summe abese ve beser.', 'Sonra kaşlarını çatıp surat astı!', 'ثم عبس وبسر'),
(5518, 74, 23, 'ثُمَّ اَدْبَرَ وَاسْتَكْبَرَۙ', 'Summe edbere vestekber.', 'Sonra kibirlendi ve arkasını döndü!', 'ثم ادبر واستكبر'),
(5519, 74, 24, 'فَقَالَ اِنْ هٰذَٓا اِلَّا سِحْرٌ يُؤْثَرُۙ', 'Fe kale in haza illa sihrun yu\'ser.', '\"Bu,  rivayetle gelen bir büyüden başka bir şey değil.\" dedi.', 'فقال ان هذا الا سحر يوثر'),
(5520, 74, 25, 'اِنْ هٰذَٓا اِلَّا قَوْلُ الْبَشَرِۜ', 'İn haza illa kavlul beşer.', '\"Bu,  olsa olsa ancak bir beşer sözüdür!\"', 'ان هذا الا قول البشر'),
(5521, 74, 26, 'سَاُصْل۪يهِ سَقَرَ', 'Se uslihi sekar.', 'Onu Sakar\'a sokacağım.', 'ساصليه سقر'),
(5522, 74, 27, 'وَمَٓا اَدْرٰيكَ مَا سَقَرُۜ', 'Ve ma edrake ma sekar.', 'Sakar\'ın ne olduğunu sana bildiren nedir?', 'وما ادريك ما سقر'),
(5523, 74, 28, 'لَا تُبْق۪ي وَلَا تَذَرُۚ', 'La tubki ve la tezer.', 'O bırakmaz ve terk etmez!', 'لا تبقي ولا تذر'),
(5524, 74, 29, 'لَـوَّاحَةٌ لِلْبَشَرِۚ', 'Levvahatun lil beşer.', 'Beşeri yakıp kavurucudur!', 'لواحة للبشر'),
(5525, 74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَۜ', 'Aleyha tis\'ate aşer.', 'Onun üzerinedir on dokuz!', 'عليها تسعة عشر'),
(5526, 74, 31, 'وَمَا جَعَلْنَٓا اَصْحَابَ النَّارِ اِلَّا مَلٰٓئِكَةًۖ وَمَا جَعَلْنَا عِدَّتَهُمْ اِلَّا فِتْنَةً لِلَّذ۪ينَ كَـفَرُواۙ لِيَسْتَيْقِنَ الَّذ۪ينَ اُو۫تُوا الْـكِتَابَ وَيَزْدَادَ الَّذ۪ينَ اٰمَنُٓوا ا۪يمَاناً وَلَا يَرْتَابَ الَّذ۪ينَ اُو۫تُوا الْـكِتَابَ وَالْمُؤْمِنُونَۙ وَلِيَقُولَ الَّذ۪ينَ ف۪ي قُلُوبِهِمْ مَرَضٌ وَالْـكَافِرُونَ مَاذَٓا اَرَادَ اللّٰهُ بِهٰذَا مَثَلاًۜ   كَذٰلِكَ يُضِلُّ اللّٰهُ مَنْ يَشَٓاءُ وَيَـهْد۪ي مَنْ يَشَٓاءُۜ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ اِلَّا هُوَۜ  وَمَا هِيَ اِلَّا ذِكْرٰى لِلْبَشَرِ۟', 'Ve ma cealna ashaben nari illa melaiketen ve ma cealna ıddetehum illa fitneten lillezine keferu li yesteykınellezine utul kitabe ve yezdadellezine amenu imanen ve la yertabellezine utul kitabe vel mu\'minune, ve li yekulellezine fi kulubihim maradun vel kafirune maza eradallahu bi haza mesela, kezalike yudıllullahu men yeşau ve yehdi men yeşa, ve ma ya\'lemu cunude rabbike illa hu, ve ma hiye illa zikra lil beşer.', 'Cehennem ashabını[1] meleklerden[2] başkasını yapmadık. Onların sayılarını,  gerçeği yalanlayan nankörler için bir fitneden[3] başka bir şey yapmadık. Kendilerine kitap verilenler; kesin olarak bilsinler,  iman edenlerin imanları artsın. Kendilerine kitap verilmiş iman sahipleri kuşku duymasınlar. Kalplerinde hastalık olanlarla[4],  Kafirler de desinler ki: \"Allah,  bu örnekle ne demek istiyor şimdi?\" İşte böyle,  Allah,  hak edeni[5] dalalette bırakır,  hak edeni[5] doğru yolu gösterir. Rabb\'inin ordularını[6],  kendisinden başkası bilmez. Bu,  beşer için zikirden[7] başka bir şey değildir.', 'وما جعلنا اصحب النار الا مليكة وما جعلنا عدتهم الا فتنة للذين كفروا ليستيقن الذين اوتوا الكتب ويزداد الذين امنوا ايمنا ولا يرتاب الذين اوتوا الكتب والمومنون وليقول الذين في قلوبهم مرض والكفرون ماذا اراد الله بهذا مثلا كذلك يضل الله من يشا ويهدي من يشا وما يعلم جنود ربك الا هو وما هي الا ذكري للبشر'),
(5527, 74, 32, 'كَلَّا وَالْقَمَرِۙ', 'Kella vel kamer.', 'Hayır! Anlayan kim? Ay\'a ant olsun;', 'كلا والقمر'),
(5528, 74, 33, 'وَالَّيْلِ اِذْ اَدْبَرَۙ', 'Vel leyli iz edber.', 'Ve dönüp gelen geceye;', 'واليل اذ ادبر'),
(5529, 74, 34, 'وَالصُّبْحِ اِذَٓا اَسْفَرَۙ', 'Ves subhı iza esfer.', 'Ve aydınlatan sabaha.', 'والصبح اذا اسفر'),
(5530, 74, 35, 'اِنَّهَا لَاِحْدَى الْـكُبَرِۙ', 'İnneha le ıhdel kuber.', 'Kuşkusuz o en büyüklerden biridir.', 'انها لاحدي الكبر'),
(5531, 74, 36, 'نَذ۪يراً لِلْبَشَرِۙ', 'Neziren lil beşer.', 'Beşer[1] için uyarıcıdır;', 'نذيرا للبشر'),
(5532, 74, 37, 'لِمَنْ شَٓاءَ مِنْكُمْ اَنْ يَتَقَدَّمَ اَوْ يَتَاَخَّرَۜ', 'Li men şae minkum en yetekaddeme ev yeteahhar.', 'Sizden,  öne geçmek isteyen için de geride kalmak isteyen için de.[1]', 'لمن شا منكم ان يتقدم او يتاخر'),
(5533, 74, 38, 'كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَه۪ينَةٌۙ', 'Kullu nefsin bima kesebet rehineh.', 'Herkes kazancının karşılığında bir rehinedir.', 'كل نفس بما كسبت رهينة'),
(5534, 74, 39, 'اِلَّٓا اَصْحَابَ الْيَم۪ينِۜۛ', 'İlla ashabel yemin.', 'Ancak \"ashabı yemin\"[1] hariç.', 'الا اصحب اليمين'),
(5535, 74, 40, 'ف۪ي جَنَّاتٍۜۛ يَتَسَٓاءَلُونَۙ', 'Fi cennat, yetesaelun.', 'Cennetler içinde soracaklar;', 'في جنت يتسالون'),
(5536, 74, 41, 'عَنِ الْمُجْرِم۪ينَۙ', 'Anil mucrimin.', 'Suçlulardan,', 'عن المجرمين'),
(5537, 74, 42, 'مَا سَلَـكَكُمْ ف۪ي سَقَرَ', 'Ma selekekum fi sekar.', 'Sizi Sakar\'a[1] sürükleyen nedir?', 'ما سلككم في سقر'),
(5538, 74, 43, 'قَالُوا لَمْ نَكُ مِنَ الْمُصَلّ۪ينَۙ', 'Kalu lem neku minel musallin.', '\"Musallin\"[1]den olmadık.\" dediler.', 'قالوا لم نك من المصلين'),
(5539, 74, 44, 'وَلَمْ نَكُ نُطْعِمُ الْمِسْك۪ينَۙ', 'Ve lem neku nut\'ımul miskin.', '\"Miskine yediren değildik.\"', 'ولم نك نطعم المسكين'),
(5540, 74, 45, 'وَكُنَّا نَخُوضُ مَعَ الْخَٓائِض۪ينَۙ', 'Ve kunna nehudu maal haidin.', '\"Batıl inançlara dalanlarla beraber biz de dalardık.\"', 'وكنا نخوض مع الخايضين'),
(5541, 74, 46, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ الدّ۪ينِۙ', 'Ve kunna nukezzibu bi yevmid din.', '\"Din Günü\'nü[1] yalanlardık.\"', 'وكنا نكذب بيوم الدين'),
(5542, 74, 47, 'حَتّٰٓى اَتٰينَا الْيَق۪ينُۜ', 'Hatta etanel yakin.', '\"Bize yakin[1] gelene kadar.\"', 'حتي اتينا اليقين'),
(5543, 74, 48, 'فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِع۪ينَۜ', 'Fe ma tenfeuhum şefaatuş şafiin.', 'Artık şefaatçilerin[1] şefaati[2] onlara yarar sağlamaz.', 'فما تنفعهم شفعة الشفعين'),
(5544, 74, 49, 'فَمَا لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِض۪ينَۙ', 'Fe ma lehum anit tezkireti mu\'rıdin.', 'Onlara ne oluyor ki zikirden[1] yüz çeviriyorlar.', 'فما لهم عن التذكرة معرضين'),
(5545, 74, 50, 'كَاَنَّهُمْ حُمُرٌ مُسْتَنْفِرَةٌۙ', 'Ke ennehum humurun mustenfireth.', 'Sanki ürkmüş yabani eşekler gibidirler;', 'كانهم حمر مستنفرة'),
(5546, 74, 51, 'فَرَّتْ مِنْ قَسْوَرَةٍۜ', 'Ferret min kasvereh.', 'Aslandan kaçan.', 'فرت من قسورة'),
(5547, 74, 52, 'بَلْ يُر۪يدُ كُلُّ امْرِئٍ مِنْهُمْ اَنْ يُؤْتٰى صُحُفاً مُنَشَّرَةًۙ', 'Bel yuridu kullumriin minhum en yu\'ta suhufen muneşşereh .', 'Hayır! Onların tamamı,  kendileri için yazılmış sahifeler gelmesini ister.', 'بل يريد كل امري منهم ان يوتي صحفا منشرة'),
(5548, 74, 53, 'كَلَّاۜ  بَلْ لَا يَخَافُونَ الْاٰخِرَةَۜ', 'Kella, bel la yuhafunel ahıreh.', 'Hayır! Doğrusu onlar ahiretten korkmuyorlar.', 'كلا بل لا يخافون الاخرة'),
(5549, 74, 54, 'كَلَّٓا اِنَّهُ تَذْكِرَةٌۚ', 'Kella innehu tezkireh.', 'Hayır! Kuşkusuz,  o bir öğüttür.', 'كلا انه تذكرة'),
(5550, 74, 55, 'فَمَنْ شَٓاءَ ذَكَرَهُۜ', 'Fe men şae zekereh.', 'Dileyen ondan öğüt alır.', 'فمن شا ذكره'),
(5551, 74, 56, 'وَمَا يَذْكُرُونَ اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُۜ  هُوَ اَهْلُ التَّقْوٰى وَاَهْلُ الْمَغْفِرَةِ', 'Ve ma yezkurune illa en yeşaallah, huve ehlut takva ve ehlul magfireh.', 'Allah dilemedikçe[1] onlar öğüt almazlar. O,  takvaya ehildir[2] ve bağışlamaya ehildir.', 'وما يذكرون الا ان يشا الله هو اهل التقوي واهل المغفرة'),
(5552, 75, 1, 'لَٓا اُقْسِمُ بِيَوْمِ الْقِيٰمَةِۙ', 'La uksimu bi yevmil kıyameh.', 'Hayır,  Kıyamet Günü\'ne yemin ederim.', 'لا اقسم بيوم القيمة'),
(5553, 75, 2, 'وَلَٓا اُقْسِمُ بِالنَّفْسِ اللَّوَّامَةِ', 'Ve la uksimu bin nefsil levvameh.', 'Hayır,  çok kınayan benliğe[1] yemin ederim.', 'ولا اقسم بالنفس اللوامة'),
(5554, 75, 3, 'اَيَحْسَبُ الْاِنْسَانُ اَلَّنْ نَجْمَعَ عِظَامَهُۜ', 'E yahsebul insanu ellen necmea ıza meh.', 'O insan[1],  kemiklerini asla bir araya getiremeyeceğimizi mi sanıyor?', 'ايحسب الانسن الن نجمع عظامه'),
(5555, 75, 4, 'بَلٰى قَادِر۪ينَ عَلٰٓى اَنْ نُسَوِّيَ بَنَانَهُ', 'Bela kadirine ala en nusevviye bena neh.', 'Hayır,  hayır! Biz,  onu parmak uçlarına[1] varıncaya dek yeniden düzenlemeye gücü yetenleriz.', 'بلي قدرين علي ان نسوي بنانه');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(5556, 75, 5, 'بَلْ يُر۪يدُ الْاِنْسَانُ لِيَفْجُرَ اَمَامَهُۚ', 'Bel yuridul insanu li yefcure emameh.', 'Aslında o insan[1],  ömrünü[2] mücrim[3] olarak geçirmeyi ister.', 'بل يريد الانسن ليفجر امامه'),
(5557, 75, 6, 'يَسْـَٔلُ اَيَّانَ يَوْمُ الْقِيٰمَةِۜ', 'Yes\'elu eyyane yevmul kıyameh.', '\"Kıyamet Günü ne zamanmış?\" diye sorar.', 'يسل ايان يوم القيمة'),
(5558, 75, 7, 'فَاِذَا بَرِقَ الْبَصَرُۙ', 'Fe iza berikal basar.', 'Gözler,  dehşetle kamaştığında.', 'فاذا برق البصر'),
(5559, 75, 8, 'وَخَسَفَ الْقَمَرُۙ', 'Ve hasefel kamer.', 'Ay,  karardığında.', 'وخسف القمر'),
(5560, 75, 9, 'وَجُمِعَ الشَّمْسُ وَالْقَمَرُۙ', 'Ve cumiaş şemsu vel kamer.', 'Güneş ve Ay bir araya getirildiği zaman.', 'وجمع الشمس والقمر'),
(5561, 75, 10, 'يَقُولُ الْاِنْسَانُ يَوْمَئِذٍ اَيْنَ الْمَفَرُّۚ', 'Yekulul insanu yevme izin eynel meferr.', 'İzin Günü[1],  o insan, [2] \"Kaçacak yer var mı?\" diyecek.', 'يقول الانسن يوميذ اين المفر'),
(5562, 75, 11, 'كَلَّا لَا وَزَرَۚ', 'Kella la vezer.', 'Hayır! Kesinlikle sığınacak bir yer yoktur!', 'كلا لا وزر'),
(5563, 75, 12, 'اِلٰى رَبِّكَ يَوْمَئِذٍۨ الْمُسْتَقَرُّۜ', 'İla rabbike yevme izinil mustekar.', 'İzin Günü,  sığınılacak tek yer senin Rabb\'indir.', 'الي ربك يوميذ المستقر'),
(5564, 75, 13, 'يُنَبَّؤُا الْاِنْسَانُ يَوْمَئِذٍ بِمَا قَدَّمَ وَاَخَّرَۜ', 'Yunebbeul insanu yevme izin bima kaddeme ve ahhar.', 'İzin Günü,  o insan,  yaptıklarından da yapması gerektiği halde yapmadıklarından da bir bir haberdar edilir.', 'ينبوا الانسن يوميذ بما قدم واخر'),
(5565, 75, 14, 'بَلِ الْاِنْسَانُ عَلٰى نَفْسِه۪ بَص۪يرَةٌۙ', 'Belil insanu ala nefsihi basireth.', 'Hayır! Aslında o insan,  kendi aleyhine tanıktır.', 'بل الانسن علي نفسه بصيرة'),
(5566, 75, 15, 'وَلَوْ اَلْقٰى مَعَاذ۪يرَهُۜ', 'Ve lev elka meazireh.', 'Mazeretlerini ileri sürse bile.', 'ولو القي معاذيره'),
(5567, 75, 16, 'لَا تُحَرِّكْ بِه۪ لِسَانَكَ لِتَعْجَلَ بِه۪ۜ', 'La tuharrik bihi lisaneke li ta\'cele bihi.', 'Telaşla,  geçiştirmeye çalışarak,  dilini dolaştırıp durma![1]', 'لا تحرك به لسانك لتعجل به'),
(5568, 75, 17, 'اِنَّ عَلَيْنَا جَمْعَهُ وَقُرْاٰنَهُۚ', 'İnne aleyna cem\'ahu ve kur\'anehu.', 'Kuşkusuz,  onun toplanması ve okunması Bize aittir.[1]', 'ان علينا جمعه وقرانه'),
(5569, 75, 18, 'فَاِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْاٰنَهُۚ', 'Fe iza kara\'nahu fettebi\'kur\'anehu.', 'O halde onu okuduğumuz zaman,  onun okunuşuna tabi ol.[1]', 'فاذا قرانه فاتبع قرانه'),
(5570, 75, 19, 'ثُمَّ اِنَّ عَلَيْنَا بَيَانَهُۜ', 'Summe inne aleyna beyanehu.', 'Sonra,  onun beyanı yalnızca Bize aittir.[1]', 'ثم ان علينا بيانه'),
(5571, 75, 20, 'كَلَّا بَلْ تُحِبُّونَ الْعَاجِلَةَۙ', 'Kella bel tuhıbbunel acileh.', '\"Hayır! İşin doğrusu,  siz çabuk geçeni[1] seviyordunuz.\"', 'كلا بل تحبون العاجلة'),
(5572, 75, 21, 'وَتَذَرُونَ الْاٰخِرَةَۜ', 'Ve tezerunel ahıreh.', '\"Ahireti de umursamıyordunuz.\"', 'وتذرون الاخرة'),
(5573, 75, 22, 'وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌۙ', 'Vucuhun yevme izin nadıreh.', 'Birtakım yüzler İzin Günü[1] ışıl ışıldır.', 'وجوه يوميذ ناضرة'),
(5574, 75, 23, 'اِلٰى رَبِّهَا نَاظِرَةٌۚ', 'İla rabbiha nazıreh.', 'Rabb\'ine bakar.[1]', 'الي ربها ناظرة'),
(5575, 75, 24, 'وَوُجُوهٌ يَوْمَئِذٍ بَاسِرَةٌۙ', 'Ve vucuhun yevme izin basireth.', 'Birtakım yüzler İzin Günü asıktır.', 'ووجوه يوميذ باسرة'),
(5576, 75, 25, 'تَظُنُّ اَنْ يُفْعَلَ بِهَا فَاقِرَةٌۜ', 'Tezunnu en yuf\'ale biha fakıreh.', 'Belini bükecek bir felaketle karşı karşıya kaldığını anlar.', 'تظن ان يفعل بها فاقرة'),
(5577, 75, 26, 'كَلَّٓا اِذَا بَلَغَتِ التَّرَاقِيَۙ', 'Kella iza belegatit terakıy.', 'Hayır! Kesinlikle düşündükleri gibi değil. Köprücük kemiklerine dayandığı zaman;[1]', 'كلا اذا بلغت التراقي'),
(5578, 75, 27, 'وَق۪يلَ مَنْ۔ رَاقٍۙ', 'Ve kile men rak.', '\"Kurtaracak olan kimdir?\" denir.', 'وقيل من راق'),
(5579, 75, 28, 'وَظَنَّ اَنَّهُ الْفِرَاقُۙ', 'Ve zanne ennehul firak.', 'Bunun ayrılık anı[1] olduğunu anlar.', 'وظن انه الفراق'),
(5580, 75, 29, 'وَالْتَفَّتِ السَّاقُ بِالسَّاقِۙ', 'Velteffetis saku bis sak.', 'Ve ayakları birbirine dolaşır.', 'والتفت الساق بالساق'),
(5581, 75, 30, 'اِلٰى رَبِّكَ يَوْمَئِذٍۨ الْمَسَاقُۜ‌۟', 'İla rabbike yevme izinil mesak.', 'İzin Günü gidiş yalnızca Rabb\'inedir.', 'الي ربك يوميذ المساق'),
(5582, 75, 31, 'فَلَا صَدَّقَ وَلَا صَلّٰىۙ', 'Fe la saddeka ve la salla.', 'Fakat o,  ne onayladı ne de salla yaptı.[1]', 'فلا صدق ولا صلي'),
(5583, 75, 32, 'وَلٰـكِنْ كَذَّبَ وَتَوَلّٰىۙ', 'Ve lakin kezzebe ve tevella.', 'Fakat yalanladı ve köstekledi.[1]', 'ولكن كذب وتولي'),
(5584, 75, 33, 'ثُمَّ ذَهَبَ اِلٰٓى اَهْلِه۪ يَتَمَطّٰىۜ', 'Summe zehebe ila ehlihi yetemetta.', 'Sonra böbürlenerek yandaşlarına gitti.', 'ثم ذهب الي اهله يتمطي'),
(5585, 75, 34, 'اَوْلٰى لَكَ فَاَوْلٰىۙ', 'Evla leke fe evla.', 'Yazık sana yazık,  sen hak ettin!', 'اولي لك فاولي'),
(5586, 75, 35, 'ثُمَّ اَوْلٰى لَكَ فَاَوْلٰىۜ', 'Summe evla leke fe evla.', 'Evet,  yazık sana yazık,  sen hak ettin.', 'ثم اولي لك فاولي'),
(5587, 75, 36, 'اَيَحْسَبُ الْاِنْسَانُ اَنْ يُتْرَكَ سُدًىۜ', 'E yahsebul\'insanu en yutreke suda.', 'Yoksa o insan başıboş bırakılacağını mı sanıyor?', 'ايحسب الانسن ان يترك سدي'),
(5588, 75, 37, 'اَلَمْ يَكُ نُطْفَةً مِنْ مَنِيٍّ يُمْنٰىۙ', 'E lem yeku nutfeten min meni yin yumna.', 'Yoksa o,  bir nutfeden[1],  dökülen meniden ibaret değil miydi?', 'الم يك نطفة من مني يمني'),
(5589, 75, 38, 'ثُمَّ  كَانَ عَلَقَةً فَخَلَقَ فَسَوّٰىۙ', 'Summe kane alakaten fe halaka fe sevva.', 'Sonra bir \"alaka\"[1] oldu. Derken onu yarattı ve ona biçim verdi.', 'ثم كان علقة فخلق فسوي'),
(5590, 75, 39, 'فَجَعَلَ مِنْهُ الزَّوْجَيْنِ الذَّكَرَ وَالْاُنْثٰىۜ', 'Fe ceale minhuz zevceyniz zekere vel unsa.', 'Ondan erkek ve dişi iki cinsi meydana getirdi.', 'فجعل منه الزوجين الذكر والانثي'),
(5591, 75, 40, 'اَلَيْسَ ذٰلِكَ بِقَادِرٍ عَلٰٓى اَنْ يُحْيِيَ الْمَوْتٰى', 'E leyse zalike bi kadirin ala en yuhyiyel mevta.', 'İşte bütün bunları Yapanın,  ölüleri diriltmeye gücü yetmez mi?', 'اليس ذلك بقدر علي ان يحي الموتي'),
(5592, 76, 1, 'هَلْ اَتٰى عَلَى الْاِنْسَانِ ح۪ينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ شَيْـٔاً مَذْكُوراً', 'Hel eta alel insani hinun mined dehri lem yekun şey\'en mezkura.', 'Anılmaya değer bir şey değilken,  insanın üzerinden \"dehr\"[1] den bir zaman gelip geçmedi mi?', 'هل اتي علي الانسن حين من الدهر لم يكن شيا مذكورا'),
(5593, 76, 2, 'اِنَّا خَلَقْنَا الْاِنْسَانَ مِنْ نُطْفَةٍ  اَمْشَاجٍۗ  نَبْتَل۪يهِ فَجَعَلْنَاهُ سَم۪يعاً بَص۪يراً', 'İnna halaknel insane min nutfetin emşacin nebtelihi fe cealnahu semian basira.', 'İnsanı karışık bir nutfeden[1] yarattık. Onu sınava tabi tutacağız; bu nedenle onu duyan ve gören bir varlık yaptık.', 'انا خلقنا الانسن من نطفة امشاج نبتليه فجعلنه سميعا بصيرا'),
(5594, 76, 3, 'اِنَّا هَدَيْنَاهُ السَّب۪يلَ اِمَّا شَا‌كِراً وَاِمَّا كَفُوراً', 'İnna hedeynahus sebile imma şakiren ve imma kefura.', 'Ona doğru yolu gösterdik. Ama isterse şükreden,  isterse nankörlük eden biri olur.', 'انا هدينه السبيل اما شاكرا واما كفورا'),
(5595, 76, 4, 'اِنَّٓا اَعْتَدْنَا لِلْـكَافِر۪ينَ سَلَاسِلَا۬ وَاَغْلَالاً وَسَع۪يراً', 'İnna a\'tedna lil kafirine selasile ve ağlalen ve seira.', 'Kafirler için zincirler,  kelepçeler ve alevli ateş hazırladık.', 'انا اعتدنا للكفرين سلسلا واغللا وسعيرا'),
(5596, 76, 5, 'اِنَّ الْاَبْرَارَ يَشْرَبُونَ مِنْ كَأْسٍ كَانَ مِزَاجُهَا كَافُوراًۚ', 'İnnel ebrara yeşrebune min ke\'sin kane mizacuha kafura.', 'İyi olanlar ise içinde kafur bulunan bir kadehten içerler.', 'ان الابرار يشربون من كاس كان مزاجها كافورا'),
(5597, 76, 6, 'عَيْناً يَشْرَبُ بِهَا عِبَادُ اللّٰهِ يُفَجِّرُونَهَا تَفْج۪يراً', 'Aynen yeşrebu biha ibadullahi yufecciruneha tefcira.', 'Allah\'ın kullarının,  içtikleri ve diledikleri kadar yararlandıkları bir kaynak.', 'عينا يشرب بها عباد الله يفجرونها تفجيرا'),
(5598, 76, 7, 'يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْماً كَانَ شَرُّهُ مُسْتَط۪يراً', 'Yufune bin nezri ve yehafune yevmen kane şerruhu mustetira.', 'Verdikleri sözü yerine getirirler,  kötülüğü salgın bir günden korkarlar.', 'يوفون بالنذر ويخافون يوما كان شره مستطيرا'),
(5599, 76, 8, 'وَيُطْعِمُونَ الطَّعَامَ عَلٰى حُبِّه۪ مِسْك۪يناً وَيَت۪يماً وَاَس۪يراً', 'Ve yut\'imunet taame ala hubbihi miskinen ve yetimen ve esira', 'İhtiyaçları olmasına rağmen yiyeceği; yoksula,  öksüze ve tutsağa yedirirler.', 'ويطعمون الطعام علي حبه مسكينا ويتيما واسيرا'),
(5600, 76, 9, 'اِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللّٰهِ لَا نُر۪يدُ مِنْكُمْ جَزَٓاءً وَلَا شُكُوراً', 'İnnema nut\'imukum li vechillahi la nuridu minkum cezaen ve la şukura.', 'Biz,  sizi yalnızca Allah\'ın rızası için doyuruyoruz. Sizden bir karşılık veya bir teşekkür beklemiyoruz.', 'انما نطعمكم لوجه الله لا نريد منكم جزا ولا شكورا'),
(5601, 76, 10, 'اِنَّا نَخَافُ مِنْ رَبِّنَا يَوْماً عَبُوساً قَمْطَر۪يراً', 'İnna nehafu min rabbina yevmen abusen kamtarira.', 'Biz; yüzlerin asık olduğu,  belalı,  zor günde Rabb\'imizin azabından korkarız.', 'انا نخاف من ربنا يوما عبوسا قمطريرا'),
(5602, 76, 11, 'فَوَقٰيهُمُ اللّٰهُ شَرَّ ذٰلِكَ الْيَوْمِ وَلَقّٰيهُمْ نَضْرَةً وَسُرُوراًۚ', 'Fe vekahumullahu şerra zalikel yevmi ve lakkahum nadreten ve surura.', 'Allah da bu nedenle onları,  o günün kötülüğünden koruyacak. Ve onları,  mutluluk ve sevince kavuşturacak.', 'فوقيهم الله شر ذلك اليوم ولقيهم نضرة وسرورا'),
(5603, 76, 12, 'وَجَزٰيهُمْ بِمَا صَبَرُوا جَنَّةً وَحَر۪يراًۙ', 'Ve cezahum bima saberu cenneten ve harira.', 'Sabretmelerine[1] karşılık onları Cennet[2] ve ipek ile ödüllendirecektir.', 'وجزيهم بما صبروا جنة وحريرا'),
(5604, 76, 13, 'مُتَّكِـ۪ٔينَ ف۪يهَا عَلَى الْاَرَٓائِكِۚ لَا يَرَوْنَ ف۪يهَا شَمْساً وَلَا زَمْهَر۪يراًۚ', 'Muttekiine fiha alel eraik, la yeravne fiha şemsen ve la zemherira.', 'Orada,  tahtlara kurulacaklar. Orada ne şiddetli bir sıcak ne de dondurucu bir soğuk görecekler.', 'متكين فيها علي الارايك لا يرون فيها شمسا ولا زمهريرا'),
(5605, 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَالُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْل۪يلاً', 'Ve daniyeten aleyhim zılaluha ve zullilet kutufuha tezlila.', 'Meyve ağaçlarının gölgeleri üzerlerine sarkacak,  meyveleri yemeye hazır olarak yaklaştırılacak.', 'ودانية عليهم ظللها وذللت قطوفها تذليلا'),
(5606, 76, 15, 'وَيُطَافُ عَلَيْهِمْ بِاٰنِيَةٍ مِنْ فِضَّةٍ وَاَكْوَابٍ كَانَتْ قَوَار۪يرَاۙ', 'Ve yutafu aleyhim bi aniyetin min fıddatin ve ekvabin kanet kavarira.', 'Gümüşten kaplar ve billur kupalarla aralarında dolaşılır.', 'ويطاف عليهم بانية من فضة واكواب كانت قواريرا'),
(5607, 76, 16, 'قَوَار۪يرَ مِنْ فِضَّةٍ قَدَّرُوهَا تَقْد۪يراً', 'Kavarira min fıddatin kadderuha takdira.', 'Miktarını kendilerinin belirledikleri gümüşten billur kadehler,', 'قواريرا من فضة قدروها تقديرا'),
(5608, 76, 17, 'وَيُسْقَوْنَ ف۪يهَا كَأْساً كَانَ مِزَاجُهَا زَنْجَب۪يلاًۚ', 'Ve yuskavne fiha ke\'sen kane mizacuha zencebila.', 'Ve orada,  karışımı zencefil olan kadehler sunulur.', 'ويسقون فيها كاسا كان مزاجها زنجبيلا'),
(5609, 76, 18, 'عَيْناً ف۪يهَا تُسَمّٰى سَلْسَب۪يلاً', 'Aynen fiha tusemma selsebila.', 'Selsebil denilen bir pınardan.', 'عينا فيها تسمي سلسبيلا'),
(5610, 76, 19, 'وَيَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُخَلَّدُونَۚ اِذَا رَاَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤ۬اً مَنْثُوراً', 'Ve yetufu aleyhim vildanun muhalledun, iza reeytehum hasibtehum lu\'luen mensura.', 'Ölümsüz gençler aralarında dolaşırlar. Onları gördüğünde,  saçılmış inciler sanırsın.', 'ويطوف عليهم ولدن مخلدون اذا رايتهم حسبتهم لولوا منثورا'),
(5611, 76, 20, 'وَاِذَا رَاَيْتَ ثَمَّ رَاَيْتَ نَع۪يماً وَمُلْـكاً كَب۪يراً', 'Ve iza reeyte semme reeyte naimen ve mulken kebira.', 'Nereye baksan orada nimetler,  büyük bir mülk ve saltanat görürsün.', 'واذا رايت ثم رايت نعيما وملكا كبيرا'),
(5612, 76, 21, 'عَالِيَهُمْ ثِيَابُ سُنْدُسٍ خُضْرٌ وَاِسْتَبْرَقٌۘ وَحُلُّٓوا اَسَاوِرَ مِنْ فِضَّةٍۚ وَسَقٰيهُمْ رَبُّهُمْ شَرَاباً طَهُوراً', 'Aliyehum siyabu sundusin hudrun ve istebrakun ve hullu esavira min fıddah, ve sekahum rabbuhum şaraben tahura.', 'Üzerlerinde yeşil ince ipekten ve parlak atlastan elbiseler vardır. Gümüş bileziklerle süslenecekler. Rabb\'leri onlara tertemiz içecekler sunacak.', 'عليهم ثياب سندس خضر واستبرق وحلوا اساور من فضة وسقيهم ربهم شرابا طهورا'),
(5613, 76, 22, 'اِنَّ هٰذَا كَانَ لَـكُمْ جَزَٓاءً وَكَانَ سَعْيُكُمْ مَشْكُوراً۟', 'İnne haza kane lekum cezaen ve kane sa\'yukum meşkura.', 'Bu sizin ödülünüzdür. Çabalarınız bu karşılığı hak etti.', 'ان هذا كان لكم جزا وكان سعيكم مشكورا'),
(5614, 76, 23, 'اِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ الْقُرْاٰنَ تَنْز۪يلاًۚ', 'İnna nahnu nezzelna aleykel kur\'ane tenzila.', 'Kuşkusuz Biz,  Kur\'an\'ı sana parça parça indirdik.', 'انا نحن نزلنا عليك القران تنزيلا'),
(5615, 76, 24, 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ اٰثِماً اَوْ كَفُوراًۚ', 'Fasbir li hukmi rabbike ve la tutı\'minhum asimen ev kefura.', 'Artık Rabb\'inin hükmü için sabret. Onlardan,  günahkarlara ve gerçeği yalanlayan nankörlere uyma.', 'فاصبر لحكم ربك ولا تطع منهم اثما او كفورا'),
(5616, 76, 25, 'وَاذْكُرِ اسْمَ رَبِّكَ بُكْرَةً وَاَص۪يلاًۚ', 'Vezkurisme rabbike bukreten ve asila.', 'Sabah akşam[1] Rabb\'inin ismini an.', 'واذكر اسم ربك بكرة واصيلا'),
(5617, 76, 26, 'وَمِنَ الَّيْلِ فَاسْجُدْ لَهُ وَسَبِّحْهُ لَيْلاً طَو۪يلاً', 'Ve minel leyli fescud lehu ve sebbihhu leylen tavila.', 'Gecenin bir bölümünde O\'na secde[1] et. Ve gece uzunca O\'nu tesbih[2] et.', 'ومن اليل فاسجد له وسبحه ليلا طويلا'),
(5618, 76, 27, 'اِنَّ هٰٓؤُ۬لَٓاءِ يُحِبُّونَ الْعَاجِلَةَ وَيَذَرُونَ وَرَٓاءَهُمْ يَوْماً ثَق۪يلاً', 'İnne haulai yuhıbbunel acilete ve yezerune veraehum yevmen sekila.', 'Onlar çabuk geçen dünyayı seviyorlar,  zor günü umursamıyorlar.', 'ان هولا يحبون العاجلة ويذرون وراهم يوما ثقيلا'),
(5619, 76, 28, 'نَحْنُ خَلَقْنَاهُمْ وَشَدَدْنَٓا اَسْرَهُمْۚ وَاِذَا شِئْنَا بَدَّلْـنَٓا اَمْثَالَهُمْ تَبْد۪يلاً', 'Nahnu halaknahum ve şededna esrehum, ve iza şi\'na beddelna emsalehum tebdila.', 'Onları Biz yarattık. Yaratılışlarını sapasağlam yaptık. Dilersek onları yok eder,  yerlerine benzerlerini getiririz.', 'نحن خلقنهم وشددنا اسرهم واذا شينا بدلنا امثلهم تبديلا'),
(5620, 76, 29, 'اِنَّ هٰذِه۪ تَذْكِرَةٌۚ فَمَنْ شَٓاءَ اتَّخَذَ اِلٰى رَبِّه۪ سَب۪يلاً', 'İnne hazihi tezkireh, fe men şaettehaze ila rabbihi sebila.', 'Bu bir öğüttür. Artık dileyen onunla Rabb\'ine varan bir yol edinir.', 'ان هذه تذكرة فمن شا اتخذ الي ربه سبيلا'),
(5621, 76, 30, 'وَمَا تَشَٓاؤُ۫نَ اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُۜ اِنَّ اللّٰهَ  كَانَ عَل۪يماً حَك۪يماًۗ', 'Ve ma teşaune illa en yeşaallah, innallahe kane alimen hakima.', 'Allah dilemedikçe siz dileyemezsiniz.[1] Kuşkusuz Allah,  Her Şeyi Bilen\'dir,  En İyi Hüküm Veren\'dir.', 'وما تشاون الا ان يشا الله ان الله كان عليما حكيما'),
(5622, 76, 31, 'يُدْخِلُ مَنْ يَشَٓاءُ ف۪ي رَحْمَتِه۪ۜ وَالظَّالِم۪ينَ اَعَدَّ لَهُمْ عَذَاباً اَل۪يماً', 'Yudhilu men yeşau fi rahmetih, vez zalimine eadde lehum azaben elima.', 'Hak edeni[1] rahmetine alır. Zalimler için ise acıklı bir azap hazırladı.', 'يدخل من يشا في رحمته والظلمين اعد لهم عذابا اليما'),
(5623, 77, 1, 'وَالْمُرْسَلَاتِ عُرْفاًۙ', 'Vel murselati urfa.', 'Art arda gönderilenlere ant olsun.', 'والمرسلت عرفا'),
(5624, 77, 2, 'فَالْعَاصِفَاتِ عَصْفاًۙ', 'Fel asıfati asfa.', 'Ve şiddetle estikçe esenlere,', 'فالعصفت عصفا'),
(5625, 77, 3, 'وَالنَّاشِرَاتِ نَشْراًۙ', 'Vennaşirati neşren.', 'Yaydıkça yayanlara,', 'والنشرت نشرا'),
(5626, 77, 4, 'فَالْفَارِقَاتِ فَرْقاًۙ', 'Fel farikati ferka.', 'Ayırdıkça ayıranlara,', 'فالفرقت فرقا'),
(5627, 77, 5, 'فَالْمُلْقِيَاتِ ذِكْراًۙ', 'Fel mulkıyati zikra.', 'Ve de öğüdü ulaştıranlara,', 'فالملقيت ذكرا'),
(5628, 77, 6, 'عُذْراً اَوْ نُذْراًۙ', 'Uzren ev nuzra.', 'Özür veya uyarı için,', 'عذرا او نذرا'),
(5629, 77, 7, 'اِنَّمَا تُوعَدُونَ لَوَاقِعٌۜ', 'İnnema tuadune levakı\'.', 'Uyarıldığınız şey kesinlikle gerçekleşecektir.', 'انما توعدون لوقع'),
(5630, 77, 8, 'فَاِذَا النُّجُومُ طُمِسَتْۙ', 'Fe izen nucumu tumiset.', 'Yıldızlar silindiğinde.', 'فاذا النجوم طمست'),
(5631, 77, 9, 'وَاِذَا السَّمَٓاءُ فُرِجَتْۙ', 'Ve izes semau furicet.', 'Gök aralandığında.', 'واذا السما فرجت'),
(5632, 77, 10, 'وَاِذَا الْجِبَالُ نُسِفَتْۙ', 'Ve izel cibalu nusifet.', 'Dağlar ufalanıp savrulduğunda;', 'واذا الجبال نسفت'),
(5633, 77, 11, 'وَاِذَا الرُّسُلُ اُقِّتَتْۜ', 'Ve izer rusulu ukkıtet.', 'O resullere vakit belirlendiğinde;', 'واذا الرسل اقتت'),
(5634, 77, 12, 'لِاَيِّ يَوْمٍ اُجِّلَتْۜ', 'Li eyyi yevmin uccilet.', 'Bunlar hangi gün için ertelendi?', 'لاي يوم اجلت'),
(5635, 77, 13, 'لِيَوْمِ الْفَصْلِۚ', 'Li yevmil fasl.', 'Ayırt Etme[1] günü için.', 'ليوم الفصل'),
(5636, 77, 14, 'وَمَٓا اَدْرٰيكَ مَا يَوْمُ الْفَصْلِۜ', 'Ve ma edrake ma yevmul fasl.', 'Ayırt Etme gününün ne olduğunu biliyor musun?', 'وما ادريك ما يوم الفصل'),
(5637, 77, 15, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5638, 77, 16, 'اَلَمْ نُهْلِكِ الْاَوَّل۪ينَۜ', 'E lem nuhlikil evvelin.', 'Öncekileri yok etmedik mi?', 'الم نهلك الاولين'),
(5639, 77, 17, 'ثُمَّ نُتْبِعُهُمُ الْاٰخِر۪ينَ', 'Summe nutbiuhumul ahırin.', 'Sonra arkadan gelenleri de onlara katarız.', 'ثم نتبعهم الاخرين'),
(5640, 77, 18, 'كَذٰلِكَ نَفْعَلُ بِالْمُجْرِم۪ينَ', 'Kezalike nef\'alu bil mucrimin.', 'İşte suçlulara böyle yaparız.', 'كذلك نفعل بالمجرمين'),
(5641, 77, 19, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5642, 77, 20, 'اَلَمْ نَخْلُقْكُمْ مِنْ مَٓاءٍ مَه۪ينٍۙ', 'E lem nahlukkum min main mehin.', 'Sizi basit bir sudan yaratmadık mı?', 'الم نخلقكم من ما مهين'),
(5643, 77, 21, 'فَجَعَلْنَاهُ ف۪ي قَرَارٍ مَك۪ينٍۙ', 'Fe cealnahu fi kararin mekin.', 'Sonra onu korunaklı bir yere yerleştirdik.', 'فجعلنه في قرار مكين'),
(5644, 77, 22, 'اِلٰى قَدَرٍ مَعْلُومٍۙ', 'İla kaderin ma\'lum.', 'Belirlenen bir süreye kadar.', 'الي قدر معلوم'),
(5645, 77, 23, 'فَقَدَرْنَاۗ فَنِعْمَ الْقَادِرُونَ', 'Fe kaderna fe ni\'mel kadirun.', 'Sonra takdir ettik[1],  ne güzel takdir edenleriz.', 'فقدرنا فنعم القدرون'),
(5646, 77, 24, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5647, 77, 25, 'اَلَمْ نَجْعَلِ الْاَرْضَ كِفَاتاًۙ', 'E lem nec\'alil arda kifata.', 'Yeryüzünü toplanma yeri yapmadık mı?', 'الم نجعل الارض كفاتا'),
(5648, 77, 26, 'اَحْيَٓاءً وَاَمْوَاتاًۙ', 'Ahyaen ve emvata.', 'Diriler ve ölüler için.', 'احيا واموتا'),
(5649, 77, 27, 'وَجَعَلْنَا ف۪يهَا رَوَاسِيَ شَامِخَاتٍ وَاَسْقَيْنَاكُمْ مَٓاءً فُرَاتاًۜ', 'Ve cealna fiha revasiye şamihatin ve eskaynakum maen furata.', 'Orada oturaklı ağır baskılar yaptık. Size tatlı su içirdik.', 'وجعلنا فيها روسي شمخت واسقينكم ما فراتا'),
(5650, 77, 28, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5651, 77, 29, 'اِنْطَلِقُٓوا اِلٰى مَا كُنْتُمْ بِه۪ تُكَذِّبُونَۚ', 'İntaliku ila ma kuntum bihi tukezzibun.', 'Haydi,  kendisini yalanlamış olduğunuz şeye gidin bakalım!', 'انطلقوا الي ما كنتم به تكذبون'),
(5652, 77, 30, 'اِنْطَلِقُٓوا اِلٰى ظِلٍّ ذ۪ي ثَلٰثِ شُعَبٍۙ', 'İntaliku ila zıllin zi selasi şuab.', 'Üç çatal[1] sahibi gölgeye gidin;', 'انطلقوا الي ظل ذي ثلث شعب'),
(5653, 77, 31, 'لَا ظَل۪يلٍ وَلَا يُغْن۪ي مِنَ اللَّهَبِۜ', 'La zalilin ve la yugni minel leheb.', 'Gölge yapmayan ve alevden de korumayan.', 'لا ظليل ولا يغني من اللهب'),
(5654, 77, 32, 'اِنَّهَا تَرْم۪ي بِشَرَرٍ كَالْقَصْرِۚ', 'İnneha termi bi şerarin kel kasr.', 'O,  kocaman kütükler gibi kıvılcımlar saçar.', 'انها ترمي بشرر كالقصر'),
(5655, 77, 33, 'كَاَنَّهُ جِمَالَتٌ صُفْرٌۜ', 'Ke ennehu cimaletun sufr.', 'Sanki o sarı deve sürüsüdür.', 'كانه جملت صفر'),
(5656, 77, 34, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5657, 77, 35, 'هٰذَا يَوْمُ لَا يَنْطِقُونَۙ', 'Haza yevmu la yentıkun.', 'Bu,  konuşamayacakları gündür.', 'هذا يوم لا ينطقون'),
(5658, 77, 36, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 'Ve la yu\'zenu lehum fe ya\'tezirun.', 'Onlara izin verilmez ki,  özür dilesinler.', 'ولا يوذن لهم فيعتذرون'),
(5659, 77, 37, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5660, 77, 38, 'هٰذَا يَوْمُ الْفَصْلِۚ جَمَعْنَاكُمْ وَالْاَوَّل۪ينَ', 'Haza yevmul fasl, cema\'nakum vel evvelin.', 'Bu,  sizi ve öncekileri topladığımız,  Ayırma Günü\'dür.[1]', 'هذا يوم الفصل جمعنكم والاولين'),
(5661, 77, 39, 'فَاِنْ كَانَ لَكُمْ كَيْدٌ فَك۪يدُونِ', 'Fe in kane lekum keydun fe kidun.', 'Haydi! Eğer kurtulmak için bir planınız varsa,  Bana karşı hemen planınızı uygulayın!', 'فان كان لكم كيد فكيدون'),
(5662, 77, 40, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ۟', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5663, 77, 41, 'اِنَّ الْمُتَّق۪ينَ ف۪ي ظِلَالٍ وَعُيُونٍۙ', 'İnnel muttekine fi zılalin ve uyun.', 'Takva sahipleri[1] gölgelerde ve pınar başlarındadırlar.', 'ان المتقين في ظلل وعيون'),
(5664, 77, 42, 'وَفَوَاكِهَ مِمَّا يَشْتَهُونَۜ', 'Ve fevakihe mimma yeştehun.', 'Ve canlarının çektiği meyveler.', 'وفوكه مما يشتهون'),
(5665, 77, 43, 'كُلُوا وَاشْرَبُوا هَن۪ٓيـٔاً بِمَا كُنْتُمْ تَعْمَلُونَ', 'Kulu veşrebu henien bima kuntum ta\'melun.', 'Yaptıklarınıza karşılık afiyetle yiyin ve için.', 'كلوا واشربوا هنيا بما كنتم تعملون'),
(5666, 77, 44, 'اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِن۪ينَ', 'İnna kezalike neczil muhsinin.', 'İyi olanları işte böyle ödüllendiririz.', 'انا كذلك نجزي المحسنين'),
(5667, 77, 45, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5668, 77, 46, 'كُلُوا وَتَمَتَّعُوا قَل۪يلاً اِنَّكُمْ مُجْرِمُونَ', 'Kulu ve temetteu kalilen innekum mucrimun.', 'Yiyin ve yararlanın biraz. Siz suçlularsınız.[1]', 'كلوا وتمتعوا قليلا انكم مجرمون'),
(5669, 77, 47, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5670, 77, 48, 'وَاِذَا ق۪يلَ لَهُمُ ارْكَعُوا لَا يَرْكَعُونَ', 'Ve iza kile lehumurkeu la yerkeun.', 'Onlara,  \"Ruku[1] edin.\" denildiği zaman ruku etmezler.', 'واذا قيل لهم اركعوا لا يركعون'),
(5671, 77, 49, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5672, 77, 50, 'فَبِاَيِّ حَد۪يثٍ بَعْدَهُ يُؤْمِنُونَ', 'Fe bi eyyi hadisin ba\'dehu yu\'minun.', 'Artık bundan başka hangi hadise[1] inanacaklar?', 'فباي حديث بعده يومنون'),
(5673, 78, 1, 'عَمَّ يَتَسَٓاءَلُونَۚ', 'Amme yetesaelun.', 'Birbirlerine neyi soruyorlar?', 'عم يتسالون'),
(5674, 78, 2, 'عَنِ النَّبَأِ الْعَظ۪يمِۙ', 'Anin nebeil azim.', 'Büyük haberden mi?', 'عن النبا العظيم'),
(5675, 78, 3, 'اَلَّذ۪ي هُمْ ف۪يهِ مُخْتَلِفُونَۜ', 'Ellezi hum fihi muhtelifun.', 'Onlar,  onun hakkında anlaşmazlık içindeler.', 'الذي هم فيه مختلفون'),
(5676, 78, 4, 'كَلَّا سَيَعْلَمُونَۙ', 'Kella se ya\'lemun.', 'Hayır,  yakında bilecekler.', 'كلا سيعلمون'),
(5677, 78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 'Summe kella se ya\'lemun.', 'Yine hayır,  yakında bilecekler.', 'ثم كلا سيعلمون'),
(5678, 78, 6, 'اَلَمْ نَجْعَلِ الْاَرْضَ مِهَاداًۙ', 'E lem nec\'alil arda mihada.', 'Yeryüzünü bir döşek yapmadık mı?', 'الم نجعل الارض مهدا'),
(5679, 78, 7, 'وَالْجِبَالَ اَوْتَاداًۖ', 'Vel cibale evtada.', 'Ve dağları da birer kazık?', 'والجبال اوتادا'),
(5680, 78, 8, 'وَخَلَقْنَاكُمْ اَزْوَاجاًۙ', 'Ve halaknakum ezvaca.', 'Sizi çiftler halinde yarattık.', 'وخلقنكم ازوجا'),
(5681, 78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتاًۙ', 'Ve cealna nevmekum subata.', 'Uykunuzu dinlenme zamanı yaptık.', 'وجعلنا نومكم سباتا'),
(5682, 78, 10, 'وَجَعَلْنَا الَّيْلَ لِبَاساًۙ', 'Ve cealnel leyle libasa.', 'Ve geceyi bir elbise yaptık.', 'وجعلنا اليل لباسا'),
(5683, 78, 11, 'وَجَعَلْنَا النَّهَارَ مَعَاشاًۖ', 'Ve cealnen nehare meaşa.', 'Gündüzü geçim zamanı yaptık.', 'وجعلنا النهار معاشا'),
(5684, 78, 12, 'وَبَنَيْنَا فَوْقَـكُمْ سَبْعاً شِدَاداًۙ', 'Ve beneyna fevkakum seb\'an şidada.', 'Üstünüze yedi sağlamı bina ettik.', 'وبنينا فوقكم سبعا شدادا'),
(5685, 78, 13, 'وَجَعَلْنَا سِرَاجاً وَهَّاجاًۖ', 'Ve cealna siracen vehhaca.', 'Ve ışık saçan bir kandil[1].', 'وجعلنا سراجا وهاجا'),
(5686, 78, 14, 'وَاَنْزَلْنَا مِنَ الْمُعْصِرَاتِ مَٓاءً ثَجَّاجاًۙ', 'Ve enzelna minel mu\'sırati maen seccaca.', 'Ve sıkıştırılmış bulutlardan şırıl şırıl akan su indirdik.', 'وانزلنا من المعصرت ما ثجاجا'),
(5687, 78, 15, 'لِنُخْرِجَ بِه۪ حَباًّ وَنَبَاتاًۙ', 'Li nuhrice bihi habben ve nebata.', 'Onunla tahıl ve bitkiler yetiştirelim diye;', 'لنخرج به حبا ونباتا'),
(5688, 78, 16, 'وَجَنَّاتٍ اَلْفَافاًۜ', 'Ve cennatin elfafa.', 'İç içe girmiş bağlar bahçeler.', 'وجنت الفافا'),
(5689, 78, 17, 'اِنَّ يَوْمَ الْفَصْلِ كَانَ م۪يقَاتاًۙ', 'İnne yevmel faslı kane mikata.', 'Ayırma Günü belirlenmiş bir vakittir.', 'ان يوم الفصل كان ميقتا'),
(5690, 78, 18, 'يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ اَفْوَاجاًۙ', 'Yevme yunfehu fis suri fe te\'tune efvaca.', 'O gün Sur\'a üflenir,  bölükler halinde gelirsiniz.', 'يوم ينفخ في الصور فتاتون افواجا'),
(5691, 78, 19, 'وَفُتِحَتِ السَّمَٓاءُ فَـكَانَتْ اَبْوَاباًۙ', 'Ve futihatis semau fe kanet ebvaba.', 'Gökyüzü açılmış ve kapı kapı olmuştur.', 'وفتحت السما فكانت ابوابا'),
(5692, 78, 20, 'وَسُيِّرَتِ الْجِبَالُ فَـكَانَتْ سَرَاباًۜ', 'Ve suyyiretil cibalu fe kanet seraba.', 'Dağlar yürütülmüş,  bir serap olmuştur.', 'وسيرت الجبال فكانت سرابا'),
(5693, 78, 21, 'اِنَّ جَهَنَّمَ كَانَتْ مِرْصَاداًۙ', 'İnne cehenneme kanet mirsada.', 'Cehennem gözetleme yeri oldu;', 'ان جهنم كانت مرصادا'),
(5694, 78, 22, 'لِلطَّاغ۪ينَ مَاٰباًۙ', 'Lit tagine meaba.', 'Haddi aşanlar için varacakları yer olarak.', 'للطغين مابا'),
(5695, 78, 23, 'لَابِث۪ينَ ف۪يهَٓا اَحْقَاباًۚ', 'Labisine fiha ahkaba.', 'Orada \"ahkaben\"[1] kalacaklardır.', 'لبثين فيها احقابا'),
(5696, 78, 24, 'لَا يَذُوقُونَ ف۪يهَا بَرْداً وَلَا شَرَاباًۙ', 'La yezukune fiha berden ve la şeraba.', 'Orada ne bir serinlik tadacaklar ne de içecek bir şey.', 'لا يذوقون فيها بردا ولا شرابا'),
(5697, 78, 25, 'اِلَّا حَم۪يماً وَغَسَّاقاًۙ', 'İlla hamimen ve gassaka.', 'Yalnızca kaynar ve kokuşmuş su tadacaklar.', 'الا حميما وغساقا'),
(5698, 78, 26, 'جَزَٓاءً وِفَاقاً', 'Cezaen vifaka.', 'Yaptıklarına uygun bir karşılık olarak.', 'جزا وفاقا'),
(5699, 78, 27, 'اِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَاباًۙ', 'İnnehum kanu la yercune hısaba.', 'Onlar,  hesap görüleceğini ummuyorlardı.', 'انهم كانوا لا يرجون حسابا'),
(5700, 78, 28, 'وَكَذَّبُوا بِاٰيَاتِنَا كِذَّاباًۜ', 'Ve kezzebu bi ayatina kizzaba.', 'Ayetlerimizi yalanladıkça yalanladılar.', 'وكذبوا بايتنا كذابا'),
(5701, 78, 29, 'وَكُلَّ شَيْءٍ اَحْصَيْنَاهُ كِتَاباً', 'Ve kulle şey\'in ahsaynahu kitaba.', 'Oysa Biz,  her şeyi yazıp kaydettik.', 'وكل شي احصينه كتبا'),
(5702, 78, 30, 'فَذُوقُوا فَلَنْ نَز۪يدَكُمْ اِلَّا عَذَاباً۟', 'Fe zuku felen nezidekum illa azaba.', 'Şimdi azabı tadın bakalım! Artık size azaptan başka bir şey artırmayacağız.', 'فذوقوا فلن نزيدكم الا عذابا'),
(5703, 78, 31, 'اِنَّ لِلْمُتَّق۪ينَ مَفَازاًۙ', 'İnne lil muttekine mefaza.', 'Takva sahipleri için ödül vardır;', 'ان للمتقين مفازا'),
(5704, 78, 32, 'حَدَٓائِقَ وَاَعْنَاباًۙ', 'Hadaika ve a\'naba.', 'Bağlar ve bahçeler,', 'حدايق واعنبا'),
(5705, 78, 33, 'وَكَوَاعِبَ اَتْرَاباًۙ', 'Ve kevaıbe etraba.', 'Görkemli,  dengi dengine, [1](eşler)', 'وكواعب اترابا'),
(5706, 78, 34, 'وَكَأْساً دِهَاقاًۜ', 'Ve ke\'sen dihaka.', 'Ve dolu kaseler.', 'وكاسا دهاقا'),
(5707, 78, 35, 'لَا يَسْمَعُونَ ف۪يهَا لَغْواً وَلَا كِذَّاباًۚ', 'La yes\'meune fiha lagven ve la kizzaba.', 'Orada yalan da boş söz de duymazlar.', 'لا يسمعون فيها لغوا ولا كذبا'),
(5708, 78, 36, 'جَزَٓاءً مِنْ رَبِّكَ عَطَٓاءً حِسَاباًۙ', 'Cezaen min rabbike ataen hısaba.', 'Bunlar,  Rabb\'inden hesaba[1] karşılık verilen ödüldür.', 'جزا من ربك عطا حسابا'),
(5709, 78, 37, 'رَبِّ السَّمٰوَاتِ وَالْاَرْضِ وَمَا بَيْنَهُمَاۙ الرَّحْمٰنِ لَا يَمْلِكُونَ مِنْهُ خِطَاباًۙ', 'Rabbis semavati vel ardı ve ma beynehumer rahmani la yemlikune minhu hitaba.', 'O,  göklerin,  yerin ve ikisinin arasında bulunanların Rabb\'idir,  Rahman\'dır. Ondan bir hitaba[1],  hiç kimse güç yetiremez.', 'رب السموت والارض وما بينهما الرحمن لا يملكون منه خطابا'),
(5710, 78, 38, 'يَوْمَ يَقُومُ الرُّوحُ وَالْمَلٰٓئِكَةُ صَفاًّۜ  لَا يَتَكَلَّمُونَ اِلَّا مَنْ اَذِنَ لَهُ الرَّحْمٰنُ وَقَالَ صَوَاباً', 'Yevme yekumur ruhu vel melaiketu saffa, la yetekellemune illa men ezine lehur rahmanu ve kale sevaba.', 'O gün,  o ruh ve o melekler saflar halinde hazır bulunur. Rahman\'ın izin verdiklerinden başkası konuşamaz. İzin verilen de doğruyu söyler.', 'يوم يقوم الروح والمليكة صفا لا يتكلمون الا من اذن له الرحمن وقال صوابا'),
(5711, 78, 39, 'ذٰلِكَ الْيَوْمُ الْحَقُّۚ فَمَنْ شَٓاءَ اتَّخَذَ اِلٰى رَبِّه۪ مَاٰباً', 'Zalikel yevmul hakk, femen şaettehaze ila rabbihi meaba.', 'İşte bu Hakk gündür. Dileyen Rabb\'ine varan bir yol edinir.', 'ذلك اليوم الحق فمن شا اتخذ الي ربه مابا'),
(5712, 78, 40, 'اِنَّٓا اَنْذَرْنَا‌كُمْ عَذَاباً قَر۪يباًۚ يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْـكَافِرُ يَا لَيْتَن۪ي كُنْتُ تُرَاباً', 'İnna enzernakum azaben kariba, yevme yenzurul mer\'u ma kaddemet yedahu ve yekulul kafiru ya leyteni kuntu turaba.', 'Sizi yakın bir azapla uyardık. O gün kişi ellerinin yaptıklarıyla[1] karşı karşıya gelecek ve Kafir kimse: \"Keşke toprak olsaydım.\" diyecek.', 'انا انذرنكم عذابا قريبا يوم ينظر المر ما قدمت يداه ويقول الكافر يليتني كنت تربا'),
(5713, 79, 1, 'وَالنَّازِعَاتِ غَرْقاًۙ', 'Ven naziati garka.', 'Ant olsun şiddetle çekip alanlara.', 'والنزعت غرقا'),
(5714, 79, 2, 'وَالنَّاشِطَاتِ نَشْطاًۙ', 'Ven naşitati neşta.', 'Ant olsun kolayca çekip alanlara.', 'والنشطت نشطا'),
(5715, 79, 3, 'وَالسَّابِحَاتِ سَبْحاًۙ', 'Ves sabihati sebha.', 'Ant olsun yüzdükçe yüzenlere.', 'والسبحت سبحا'),
(5716, 79, 4, 'فَالسَّابِقَاتِ سَبْقاًۙ', 'Fes sabikati sebka.', 'Ve de yarıştıkça yarışanlara.', 'فالسبقت سبقا'),
(5717, 79, 5, 'فَالْمُدَبِّرَاتِ اَمْراًۢ', 'Fel mudebbirati emra.', 'Ve de işi yerine getirenlere.[1]', 'فالمدبرت امرا'),
(5718, 79, 6, 'يَوْمَ تَرْجُفُ الرَّاجِفَةُۙ', 'Yevme tercufur racifeh.', 'O gün sarsan sarsacak.', 'يوم ترجف الراجفة'),
(5719, 79, 7, 'تَتْبَعُهَا الرَّادِفَةُۜ', 'Tetbeuher radifeh.', 'Arkasından gelen onu izleyecek.', 'تتبعها الرادفة'),
(5720, 79, 8, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌۙ', 'Kulubun yevmeizin vacifeh.', 'İzin Günü kalpler endişe ile çarpar.', 'قلوب يوميذ واجفة'),
(5721, 79, 9, 'اَبْصَارُهَا خَاشِعَةٌۢ', 'Ebsaruha haşiah.', 'Bakışları korku içindedir.', 'ابصرها خشعة'),
(5722, 79, 10, 'يَقُولُونَ ءَاِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِۜ', 'Yekulune e inna le merdudune fil hafireh.', '\"Biz,  tekrar eski halimize mi döndürülecekmişiz?\" diyorlar;', 'يقولون انا لمردودون في الحافرة'),
(5723, 79, 11, 'ءَاِذَا كُنَّا عِظَاماً نَخِرَةًۜ', 'E iza kunna izamen nahıreh.', 'Çürümüş,  dağılmış kemikler olmuşken?', 'اذا كنا عظما نخرة'),
(5724, 79, 12, 'قَالُوا تِلْكَ اِذاً كَرَّةٌ خَاسِرَةٌۢ', 'Kalu tilke izen kerretun hasireh.', '\"Öyleyse,  bu hüsranlı bir dönüştür.\" dediler.', 'قالوا تلك اذا كرة خاسرة'),
(5725, 79, 13, 'فَاِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌۙ', 'Fe innema hiye zecretun vahıdeh.', 'Oysaki o,  tek bir haykırıştır!', 'فانما هي زجرة وحدة'),
(5726, 79, 14, 'فَاِذَا هُمْ بِالسَّاهِرَةِۜ', 'Fe iza hum bis sahireh.', 'Bir de bakmışsın meydandalar.[1]', 'فاذا هم بالساهرة'),
(5727, 79, 15, 'هَلْ اَتٰيكَ حَد۪يثُ مُوسٰىۢ', 'Hel etake hadisu musa.', 'Musa\'nın hadisi[1] sana geldi mi?', 'هل اتيك حديث موسي'),
(5728, 79, 16, 'اِذْ نَادٰيهُ رَبُّهُ بِالْوَادِ الْمُقَدَّسِ طُوًىۚ', 'İz nadahu rabbuhu bil vadil mukaddesi tuva.', 'Hani,  Rabb\'i ona kutsal vadi Tuva\'da seslenmişti!', 'اذ ناديه ربه بالواد المقدس طوي'),
(5729, 79, 17, 'اِذْهَبْ اِلٰى فِرْعَوْنَ اِنَّهُ طَغٰىۘ', 'İzheb ila fir\'avne innehu taga.', '\"Firavun\'a git. Kuşkusuz o azgınlaştı.\"', 'اذهب الي فرعون انه طغي'),
(5730, 79, 18, 'فَقُلْ هَلْ لَكَ اِلٰٓى اَنْ تَزَكّٰىۙ', 'Fe kul hel leke ila en tezekka.', '\"Git ona de ki: Arınmak ister misin?\"', 'فقل هل لك الي ان تزكي'),
(5731, 79, 19, 'وَاَهْدِيَكَ اِلٰى رَبِّكَ فَتَخْشٰىۚ', 'Ve ehdiyeke ila rabbike fe tahşa.', '\"Sana Rabb\'inin yolunu göstereyim de içtenlikle O\'na yönelmiş ol.', 'واهديك الي ربك فتخشي'),
(5732, 79, 20, 'فَاَرٰيهُ الْاٰيَةَ الْـكُبْرٰىۘ', 'Fe erahul ayetel kubra.', 'Sonra Musa,  Firavun\'a büyük ayeti[1] gösterdi.', 'فاريه الاية الكبري'),
(5733, 79, 21, 'فَـكَذَّبَ وَعَصٰىۘ', 'Fe kezzebe ve asa.', 'Fakat yalanladı ve karşı çıktı.', 'فكذب وعصي'),
(5734, 79, 22, 'ثُمَّ اَدْبَرَ يَسْعٰىۘ', 'Summe edbere yes\'a.', 'Sonra aleyhte çalışmaya koyuldu.', 'ثم ادبر يسعي'),
(5735, 79, 23, 'فَحَشَرَ فَنَادٰىۘ', 'Fehaşere fe nada.', 'Adamlarını toplayarak seslendi:', 'فحشر فنادي'),
(5736, 79, 24, 'فَقَالَ اَنَا۬ رَبُّكُمُ الْاَعْلٰىۘ', 'Fe kale ene rabbukumul a\'la.', '\"Ben sizin yüce rabbinizim.\" dedi.', 'فقال انا ربكم الاعلي'),
(5737, 79, 25, 'فَاَخَذَهُ اللّٰهُ نَكَالَ الْاٰخِرَةِ وَالْاُو۫لٰىۜ', 'Fe ehazehullahu nekalel ahıreti vel ula.', 'Allah da onu dünya ve ahiret azabıyla cezalandırdı.', 'فاخذه الله نكال الاخرة والاولي'),
(5738, 79, 26, 'اِنَّ ف۪ي ذٰلِكَ لَعِبْرَةً لِمَنْ يَخْشٰىۜ۟', 'İnne fi zalike le ıbreten li men yahşa.', 'Kuşkusuz bunda huşu[1] duyan kimse için ibret vardır.', 'ان في ذلك لعبرة لمن يخشي'),
(5739, 79, 27, 'ءَاَنْتُمْ اَشَدُّ خَلْقاً اَمِ السَّمَٓاءُۜ بَنٰيهَا۠', 'E entum eşeddu halkan emis sema\', benaha.', 'Sizi yaratmak mı daha zor,  yoksa göğü bina etmek mi?', 'انتم اشد خلقا ام السما بنيها'),
(5740, 79, 28, 'رَفَعَ سَمْكَهَا فَسَوّٰيهَاۙ', 'Refea semkeha fe sevvaha.', 'Onu yükseltti ve düzene koydu.', 'رفع سمكها فسويها'),
(5741, 79, 29, 'وَاَغْطَشَ لَيْلَهَا وَاَخْرَجَ ضُحٰيهَاۖ', 'Ve agtaşe leyleha ve ahrece duhaha.', 'Gecesini kararttı,  gündüzünü aydınlattı.', 'واغطش ليلها واخرج ضحيها'),
(5742, 79, 30, 'وَالْاَرْضَ بَعْدَ ذٰلِكَ دَحٰيهَاۜ', 'Vel arda ba\'de zalike dehaha.', 'Yeryüzünü yayıp yuvarlattı.[1]', 'والارض بعد ذلك دحيها'),
(5743, 79, 31, 'اَخْرَجَ مِنْهَا مَٓاءَهَا وَمَرْعٰيهَاۖ', 'Ahrece minha maeha ve mer\'aha.', 'Ondan suyunu ve yeşilliğini çıkardı.', 'اخرج منها ماها ومرعيها'),
(5744, 79, 32, 'وَالْجِبَالَ اَرْسٰيهَاۙ', 'Vel cibale ersaha.', 'Ona dağlar yerleştirdi.', 'والجبال ارسيها'),
(5745, 79, 33, 'مَتَاعاً لَكُمْ وَلِاَنْعَامِكُمْۜ', 'Metaan lekum ve li en amikum.', 'Sizin ve hayvanlarınızın geçimi için.', 'متعا لكم ولانعمكم'),
(5746, 79, 34, 'فَاِذَا جَٓاءَتِ الطَّٓامَّةُ الْكُبْرٰىۘ', 'Fe iza caetit tammetul kubra.', 'Fakat o en büyük olay[1] gerçekleştiği zaman.', 'فاذا جات الطامة الكبري'),
(5747, 79, 35, 'يَوْمَ يَتَذَكَّرُ الْاِنْسَانُ مَا سَعٰىۙ', 'Yevme yetezekkerul insanu ma sea.', 'O gün insan ne yaptığını hatırlar.', 'يوم يتذكر الانسن ما سعي'),
(5748, 79, 36, 'وَبُرِّزَتِ الْجَح۪يمُ لِمَنْ يَرٰى', 'Ve burrizetil cahimu li men yera.', 'Gören kimseler için Cehennem açıkça gösterilecek.', 'وبرزت الجحيم لمن يري'),
(5749, 79, 37, 'فَاَمَّا مَنْ طَغٰىۙ', 'Fe emma men taga.', 'Fakat kim azgınlaşmış,', 'فاما من طغي'),
(5750, 79, 38, 'وَاٰثَرَ الْحَيٰوةَ الدُّنْيَاۙ', 'Ve aserel hayated dunya.', 'Yalnızca dünya hayatını tercih etmişse,', 'واثر الحيوة الدنيا'),
(5751, 79, 39, 'فَاِنَّ الْجَح۪يمَ هِيَ الْمَأْوٰىۜ', 'Fe innel cahime hiyel me\'va.', 'Kuşkusuz Cehennem onun için barınaktır.', 'فان الجحيم هي الماوي'),
(5752, 79, 40, 'وَاَمَّا مَنْ خَافَ مَقَامَ رَبِّه۪ وَنَهَى النَّفْسَ عَنِ الْهَوٰىۙ', 'Ve emma men hafe makame rabbihi ve nehennefse anil heva.', 'Fakat Rabb\'inin huzurunda suçlu olmaktan korkarak,  kendisini hevasından[1] uzak tutana,', 'واما من خاف مقام ربه ونهي النفس عن الهوي'),
(5753, 79, 41, 'فَاِنَّ الْجَنَّةَ هِيَ الْمَأْوٰىۜ', 'Fe innel cennete hiyel me\'va.', 'Cennet onun için barınaktır.', 'فان الجنة هي الماوي'),
(5754, 79, 42, 'يَسْـَٔلُونَكَ عَنِ السَّاعَةِ اَيَّانَ مُرْسٰيهَاۜ', 'Yes\'eluneke anis saati eyyane mursaha.', 'Sana o Sa\'at\'ten[1] soruyorlar; ne zaman gelip çatacakmış diye.', 'يسلونك عن الساعة ايان مرسيها'),
(5755, 79, 43, 'ف۪يمَ اَنْتَ مِنْ ذِكْرٰيهَاۜ', 'Fime ente min zikraha.', 'Sen onun hakkında ne bilebilirsin ki?', 'فيم انت من ذكريها'),
(5756, 79, 44, 'اِلٰى رَبِّكَ مُنْتَهٰيهَاۜ', 'İla rabbike muntehaha.', 'Onun sonu Rabb\'inedir.[1]', 'الي ربك منتهيها'),
(5757, 79, 45, 'اِنَّمَٓا اَنْتَ مُنْذِرُ مَنْ يَخْشٰيهَاۜ', 'İnnema ente munziru men yahşaha.', 'Sen ancak ona huşu duyanlar için bir uyarıcısın.', 'انما انت منذر من يخشيها'),
(5758, 79, 46, 'كَاَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُٓوا اِلَّا عَشِيَّةً اَوْ ضُحٰيهَا', 'Ke ennehum yevme yerevneha lem yelbesu illa aşiyyeten ev duhaha.', 'Onlar onu[1] görecekleri gün,  dünyada bir akşam veya kuşluğundan[2] başka kalmamış sanacaklar.', 'كانهم يوم يرونها لم يلبثوا الا عشية او ضحيها'),
(5759, 80, 1, 'عَبَسَ وَتَوَلّٰىۙ', 'Abese ve tevella.', 'Surat astı ve yüz çevirdi.', 'عبس وتولي'),
(5760, 80, 2, 'اَنْ جَٓاءَهُ الْاَعْمٰىۜ', 'En caehul a\'ma.', 'O gözleri görmeyen geldi diye.', 'ان جاه الاعمي'),
(5761, 80, 3, 'وَمَا يُدْر۪يكَ لَعَلَّهُ يَزَّكّٰىۙ', 'Ve ma yudrike leallehu yezzekka.', 'Sen bilemezsin,  belki o tezkiye[1] olacak.', 'وما يدريك لعله يزكي'),
(5762, 80, 4, 'اَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرٰىۜ', 'Ev yezzekkeru fe tenfeahuz zikra.', 'Veya öğüt alır ve böylece öğüt ona yararlı olur.', 'او يذكر فتنفعه الذكري'),
(5763, 80, 5, 'اَمَّا مَنِ اسْتَغْنٰىۙ', 'Emma menistagna.', 'Fakat öğüt almayı gereksiz gören o kimseye gelince de;', 'اما من استغني'),
(5764, 80, 6, 'فَاَنْتَ لَهُ تَصَدّٰىۜ', 'Fe ente lehu tesadda.', 'Sen ona ilgi gösteriyorsun.', 'فانت له تصدي'),
(5765, 80, 7, 'وَمَا عَلَيْكَ اَلَّا يَزَّكّٰىۜ', 'Ve ma aleyke ella yezzekka.', 'Oysaki onun arınmak istememesinden sorumlu sen değilsin.', 'وما عليك الا يزكي'),
(5766, 80, 8, 'وَاَمَّا مَنْ جَٓاءَكَ يَسْعٰىۙ', 'Ve emma men caeke yes\'a.', 'Fakat sana koşarak gelen kimseye gelince;', 'واما من جاك يسعي'),
(5767, 80, 9, 'وَهُوَ يَخْشٰىۙ', 'Ve huve yahşa.', 'O huşu duyanla,', 'وهو يخشي'),
(5768, 80, 10, 'فَاَنْتَ عَنْهُ تَلَهّٰىۚ', 'Fe ente anhu telehha.', 'Sen onunla ilgilenmiyorsun.', 'فانت عنه تلهي'),
(5769, 80, 11, 'كَلَّٓا اِنَّهَا تَذْكِرَةٌۚ', 'Kella inneha tezkirah.', 'Hayır! Kuşkusuz o bir öğüttür.', 'كلا انها تذكرة'),
(5770, 80, 12, 'فَمَنْ شَٓاءَ ذَكَرَهُۢ', 'Fe men şae zekerah.', 'Dileyen kimse ondan öğüt alır.', 'فمن شا ذكره'),
(5771, 80, 13, 'ف۪ي صُحُفٍ مُكَرَّمَةٍۙ', 'Fi suhufin mukerrameh.', 'O şerefli sayfalardadır,', 'في صحف مكرمة'),
(5772, 80, 14, 'مَرْفُوعَةٍ مُطَهَّرَةٍۙ', 'Merfuatin mutahherah.', 'Yüceltilmiş,  temizlenmiş,', 'مرفوعة مطهرة'),
(5773, 80, 15, 'بِاَيْد۪ي سَفَرَةٍۙ', 'Bi eydi seferah.', 'Yazıcıların elleriyle,', 'بايدي سفرة'),
(5774, 80, 16, 'كِرَامٍ بَرَرَةٍۜ', 'Kiramin berarah.', 'Şerefli ve birr[1] sahiplerince.', 'كرام بررة'),
(5775, 80, 17, 'قُتِلَ الْاِنْسَانُ مَٓا اَكْفَرَهُۜ', 'Kutilel insanu ma ekferah.', 'O insan[1] kendisini mahvetti,  o ne kadar da nankördür.', 'قتل الانسن ما اكفره'),
(5776, 80, 18, 'مِنْ اَيِّ شَيْءٍ خَلَقَهُۜ', 'Min eyyi şey\'in halakah.', 'Onu hangi şeyden yarattı?', 'من اي شي خلقه'),
(5777, 80, 19, 'مِنْ نُطْفَةٍۜ خَلَقَهُ فَقَدَّرَهُۙ', 'Min nutfeh, halakahu fe kadderah.', 'Bir nutfeden yarattı. Sonra da ona kader takdir etti.[1]', 'من نطفة خلقه فقدره'),
(5778, 80, 20, 'ثُمَّ السَّب۪يلَ يَسَّرَهُۙ', 'Summes sebile yesserah.', 'Sonra hak yolu ona kolaylaştırdı.[1]', 'ثم السبيل يسره'),
(5779, 80, 21, 'ثُمَّ اَمَاتَهُ فَاَقْبَرَهُۙ', 'Summe ematehu fe akberah.', 'Sonra onu öldürdü ve kabre koydurdu.', 'ثم اماته فاقبره'),
(5780, 80, 22, 'ثُمَّ اِذَا شَٓاءَ اَنْشَرَهُۜ', 'Summe iza şae enşerah.', 'Sonra dilediği zaman onu diriltip ortaya çıkardı.', 'ثم اذا شا انشره'),
(5781, 80, 23, 'كَلَّا لَمَّا يَقْضِ مَٓا اَمَرَهُۜ', 'Kella lemma yakdı ma emerah.', 'Hayır! Ona buyurduğu şeyi yerine getirmedi.', 'كلا لما يقض ما امره'),
(5782, 80, 24, 'فَلْيَنْظُرِ الْاِنْسَانُ اِلٰى طَعَامِه۪ۙ', 'Felyanzuril insanu ila taamih.', 'O insan[1] yiyeceğine bir baksın!', 'فلينظر الانسن الي طعامه'),
(5783, 80, 25, 'اَنَّا صَبَبْنَا الْمَٓاءَ صَباًّۙ', 'Enna sabebnel mae sabba.', 'Suyu nasıl akıttıkça akıttık.', 'انا صببنا الما صبا'),
(5784, 80, 26, 'ثُمَّ شَقَقْنَا الْاَرْضَ شَقاًّۙ', 'Summe şekaknel arda şakka.', 'Sonra yeri yardıkça yardık.', 'ثم شققنا الارض شقا'),
(5785, 80, 27, 'فَاَنْبَتْنَا ف۪يهَا حَباًّۙ', 'Fe enbetna fiha habba.', 'Böylece orada taneler yetiştirdik;', 'فانبتنا فيها حبا'),
(5786, 80, 28, 'وَعِنَباً وَقَضْباًۙ', 'Ve ineben ve kadba.', 'Üzümler,  sebzeler,', 'وعنبا وقضبا'),
(5787, 80, 29, 'وَزَيْتُوناً وَنَخْلاًۙ', 'Ve zeytunen ve nahla.', 'Zeytinler,  hurmalar,', 'وزيتونا ونخلا'),
(5788, 80, 30, 'وَحَدَٓائِقَ غُلْباًۙ', 'Ve hadaika gulba.', 'Dalları iç içe girmiş bahçeler,', 'وحدايق غلبا'),
(5789, 80, 31, 'وَفَاكِهَةً وَاَباًّۙ', 'Ve fakiheten ve ebba.', 'Meyveler ve otlaklar.', 'وفكهة وابا'),
(5790, 80, 32, 'مَتَاعاً لَكُمْ وَلِاَنْعَامِكُمْۜ', 'Metaan lekum ve li en\'amikum.', 'Size ve hayvanlarınıza geçim olarak.', 'متعا لكم ولانعمكم'),
(5791, 80, 33, 'فَاِذَا جَٓاءَتِ الصَّٓاخَّةُۘ', 'Fe iza caetis sahhah.', 'Fakat o kulakları sağır edici ses geldiği zaman.', 'فاذا جات الصاخة'),
(5792, 80, 34, 'يَوْمَ يَفِرُّ الْمَرْءُ مِنْ اَخ۪يهِۙ', 'Yevme yefirrul mer\'u min ehih.', 'O gün insan kardeşinden kaçar;', 'يوم يفر المر من اخيه'),
(5793, 80, 35, 'وَاُمِّه۪ وَاَب۪يهِۙ', 'Ve ummihi ve ebih.', 'Annesinden ve babasından,', 'وامه وابيه'),
(5794, 80, 36, 'وَصَاحِبَتِه۪ وَبَن۪يهِۜ', 'Ve sahıbetihi ve benih.', 'Eşinden ve çocuklarından.', 'وصحبته وبنيه'),
(5795, 80, 37, 'لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْن۪يهِۜ', 'Li kullimriin minhum yevmeizin şe\'nun yugnih.', 'Onların hepsinin İzin Günü[1] başından aşkın uğraşısı vardır.', 'لكل امري منهم يوميذ شان يغنيه'),
(5796, 80, 38, 'وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌۙ', 'Vucuhun yevmeizin musfirah.', 'İzin Günü pırıl pırıl yüzler vardır;', 'وجوه يوميذ مسفرة'),
(5797, 80, 39, 'ضَاحِكَةٌ مُسْتَبْشِرَةٌۚ', 'Dahıketun mustebşirah.', 'Gülen,  sevinen.', 'ضاحكة مستبشرة'),
(5798, 80, 40, 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۙ', 'Ve vucuhun yevmeizin aleyha gaberah.', 'İzin Günü,  kimi yüzler de tozludur[1],', 'ووجوه يوميذ عليها غبرة'),
(5799, 80, 41, 'تَرْهَقُهَا قَتَرَةٌۜ', 'Terhekuha katerah.', 'Onu bir karanlık kaplar.[1]', 'ترهقها قترة'),
(5800, 80, 42, 'اُو۬لٰٓئِكَ هُـمُ الْكَفَرَةُ الْفَجَرَةُ', 'Ulaike humul keferetul fecerah.', 'İşte bunlar Kafirlerdir[1],  facirlerdir.[2]', 'اوليك هم الكفرة الفجرة'),
(5801, 81, 1, 'اِذَا الشَّمْسُ كُـوِّرَتْۙۖ', 'İzeş şemsu kuvviret.', 'Güneş köreltildiği zaman[1],', 'اذا الشمس كورت'),
(5802, 81, 2, 'وَاِذَا النُّجُومُ انْكَدَرَتْۙۖ', 'Ve izen nucumun kederet.', 'Yıldızlar bulanıklaştığı zaman,', 'واذا النجوم انكدرت'),
(5803, 81, 3, 'وَاِذَا الْجِبَالُ سُيِّرَتْۙۖ', 'Ve izelcibalu suyyiret.', 'Dağlar yürütüldüğü zaman,', 'واذا الجبال سيرت'),
(5804, 81, 4, 'وَاِذَا الْعِشَارُ عُطِّلَتْۙۖ', 'Ve izel ışaru uttılet.', 'Gebe develer başıboş bırakıldığı[1] zaman,', 'واذا العشار عطلت'),
(5805, 81, 5, 'وَاِذَا الْوُحُوشُ حُشِرَتْۙۖ', 'Ve izel vuhuşu huşiret.', 'Vahşi hayvanlar bir araya toplandıkları zaman[1],', 'واذا الوحوش حشرت'),
(5806, 81, 6, 'وَاِذَا الْبِحَارُ سُجِّرَتْۙۖ', 'Ve izel biharu succiret.', 'Denizler kaynatıldığı zaman,', 'واذا البحار سجرت'),
(5807, 81, 7, 'وَاِذَا النُّفُوسُ زُوِّجَتْۙۖ', 'Ve izen nufusu zuvvicet.', 'Nefisler eşleştirildiği[1] zaman,', 'واذا النفوس زوجت'),
(5808, 81, 8, 'وَاِذَا الْمَوْءُ۫دَةُ سُئِلَتْۙ', 'Ve izel mev\'udetu suilet.', 'O diri diri toprağa gömülen kıza sorulduğu zaman;', 'واذا المودة سيلت'),
(5809, 81, 9, 'بِاَيِّ ذَنْبٍ قُتِلَتْۚ', 'Bi eyyi zenbin kutilet.', 'Hangi suçtan dolayı öldürüldüğü!', 'باي ذنب قتلت'),
(5810, 81, 10, 'وَاِذَا الصُّحُفُ نُشِرَتْۙۖ', 'Ve izes suhufu nuşiret.', 'Defterler açıldığı zaman,', 'واذا الصحف نشرت'),
(5811, 81, 11, 'وَاِذَا السَّمَٓاءُ كُشِطَتْۙۖ', 'Ve izes semau kuşitat.', 'Gök soyulduğu[1] zaman,', 'واذا السما كشطت'),
(5812, 81, 12, 'وَاِذَا الْجَح۪يمُ سُعِّرَتْۙۖ', 'Ve izel cahimu su\'ıret.', 'Cehennem kızıştırıldığı zaman,', 'واذا الجحيم سعرت'),
(5813, 81, 13, 'وَاِذَا الْجَنَّةُ اُزْلِفَتْۙۖ', 'Ve izel cennetu uzlifet.', 'Cennet yaklaştırıldığı zaman,', 'واذا الجنة ازلفت'),
(5814, 81, 14, 'عَلِمَتْ نَفْسٌ مَٓا اَحْضَرَتْۜ', 'Alimet nefsün ma ahdaret.', 'İnsan,  kendisi ile ne getirdiğini görecektir.', 'علمت نفس ما احضرت'),
(5815, 81, 15, 'فَلَٓا اُقْسِمُ بِالْخُنَّسِۙ', 'Fe la uksimu bil hunnes.', 'Hayır,  ant olsun sinenlere[1],', 'فلا اقسم بالخنس'),
(5816, 81, 16, 'اَلْجَوَارِ الْكُنَّسِۙ', 'El cevaril kunnes.', 'Yörüngesinde dönenlere,', 'الجوار الكنس'),
(5817, 81, 17, 'وَالَّيْلِ اِذَا عَسْعَسَۙ', 'Vel leyli iza as\'as.', 'Kararmaya başladığı an geceye,', 'واليل اذا عسعس'),
(5818, 81, 18, 'وَالصُّبْحِ اِذَا تَنَفَّسَۙ', 'Ves subhı iza teneffes.', 'Soluk almaya başladığı zaman sabaha ant olsun ki,', 'والصبح اذا تنفس'),
(5819, 81, 19, 'اِنَّهُ لَقَوْلُ رَسُولٍ كَر۪يمٍۙ', 'İnnehu le kavlu resulin kerim.', 'Kuşkusuz o[1] çok şerefli bir resul sözüdür;[2]', 'انه لقول رسول كريم'),
(5820, 81, 20, 'ذ۪ي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَك۪ينٍۙ', 'Zi kuvvetin ınde zil arşi mekin.', 'Güç sahibi,  arşın sahibi yanında itibarlıdır.', 'ذي قوة عند ذي العرش مكين'),
(5821, 81, 21, 'مُطَاعٍ ثَمَّ اَم۪ينٍۜ', 'Mutaın semme emin.', 'Kendisine itaat edilen,  orada güvenilendir.', 'مطاع ثم امين'),
(5822, 81, 22, 'وَمَا صَاحِبُكُمْ بِمَجْنُونٍۚ', 'Ve ma sahıbukum bi mecnun.', 'Arkadaşınız mecnun[1] değildir.', 'وما صاحبكم بمجنون'),
(5823, 81, 23, 'وَلَقَدْ رَاٰهُ بِالْاُفُقِ الْمُب۪ينِۚ', 'Ve lekad reahu bil ufukıl mubin.', 'Ant olsun o,  onu açık ufukta gördü.[1]', 'ولقد راه بالافق المبين'),
(5824, 81, 24, 'وَمَا هُوَ عَلَى الْغَيْبِ بِضَن۪ينٍۚ', 'Ve ma huve alel gaybi bi danin.', 'O vahyi gizlemez.[1]', 'وما هو علي الغيب بضنين'),
(5825, 81, 25, 'وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَج۪يمٍۚ', 'Ve ma huve bi kavli şeytanin recim.', 'O,  taşlanmış şeytanın[1] sözü değildir.', 'وما هو بقول شيطن رجيم'),
(5826, 81, 26, 'فَاَيْنَ تَذْهَبُونَۜ', 'Fe eyne tezhebun.', 'O halde nereye gidiyorsunuz?[1]', 'فاين تذهبون'),
(5827, 81, 27, 'اِنْ هُوَ اِلَّا ذِكْرٌ لِلْعَالَم۪ينَۙ', 'İn huve illa zikrun lil alemin.', 'O alemler için zikirden[1] başka bir şey değildir.', 'ان هو الا ذكر للعلمين'),
(5828, 81, 28, 'لِمَنْ شَٓاءَ مِنْكُمْ اَنْ يَسْتَق۪يمَ', 'Li men şae minkum en yestekim.', 'Sizden doğru yoldan gitmek isteyenler için.', 'لمن شا منكم ان يستقيم'),
(5829, 81, 29, 'وَمَا تَشَٓاؤُ۫نَ اِلَّٓا اَنْ يَشَٓاءَ اللّٰهُ رَبُّ الْعَالَم۪ينَ', 'Ve ma teşaune illa en yeşaallahu rabbul alemin.', 'Âlemlerin Rabb\'i Allah dilemedikçe[1] siz dileyemezsiniz.', 'وما تشاون الا ان يشا الله رب العلمين'),
(5830, 82, 1, 'اِذَا السَّمَٓاءُ انْفَطَرَتْۙ', 'İzes semaunfetaret.', 'Göğün yasaları yeniden belirlendiği zaman,', 'اذا السما انفطرت'),
(5831, 82, 2, 'وَاِذَا الْـكَوَاكِبُ انْتَثَرَتْۙ', 'Ve izel kevakibunteseret.', 'Yıldızlar dağıldığı zaman,', 'واذا الكواكب انتثرت'),
(5832, 82, 3, 'وَاِذَا الْبِحَارُ فُجِّرَتْۙ', 'Ve izel biharu fucciret.', 'Denizler kabarıp taştığı zaman,', 'واذا البحار فجرت'),
(5833, 82, 4, 'وَاِذَا الْقُبُورُ بُعْثِرَتْۙ', 'Ve izel kuburu bu\'siret.', 'Kabirler alt üst edildiği zaman,', 'واذا القبور بعثرت'),
(5834, 82, 5, 'عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَاَخَّرَتْۜ', 'Alimet nefsun ma kaddemet ve ahharet.', 'Herkes yaptığını ve yapmadığını bilecek.', 'علمت نفس ما قدمت واخرت'),
(5835, 82, 6, 'يَٓا اَيُّهَا الْاِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْـكَر۪يمِۙ', 'Ya eyyuhel insanu ma garreke bi rabbikel kerim.', 'Ey insan! Kerim[1] olan Rabb\'ine karşı seni aldatan nedir?', 'يايها الانسن ما غرك بربك الكريم'),
(5836, 82, 7, 'اَلَّذ۪ي خَلَقَكَ فَسَوّٰيكَ فَعَدَلَكَۙ', 'Ellezi halakake fe sevvake fe adelek.', 'Seni yarattı,  sonra sana şekil verdi,  organlarını uyumlu ve dengeli yaptı.', 'الذي خلقك فسويك فعدلك'),
(5837, 82, 8, 'ف۪ٓي اَيِّ صُورَةٍ مَا شَٓاءَ رَكَّبَكَۜ', 'Fi eyyi suretin ma şae rekkebek.', 'Seni dilediği şekilde düzenledi.', 'في اي صورة ما شا ركبك'),
(5838, 82, 9, 'كَلَّا بَلْ تُكَذِّبُونَ بِالدّ۪ينِۙ', 'Kella bel tukezzibune bid din.', 'Hayır! Bilakis,  siz dini yalanlıyorsunuz!', 'كلا بل تكذبون بالدين'),
(5839, 82, 10, 'وَاِنَّ عَلَيْكُمْ لَحَافِظ۪ينَۙ', 'Ve inne aleykum le hafızin.', 'Sizin üzerinizde kesinlikle kaydediciler var,', 'وان عليكم لحفظين'),
(5840, 82, 11, 'كِرَاماً كَاتِب۪ينَۙ', 'Kiramen katibin.', 'Şerefli yazıcılar.', 'كراما كتبين'),
(5841, 82, 12, 'يَعْلَمُونَ مَا تَفْعَلُونَ', 'Ya\'lemune ma tef\'alun.', 'Yaptığınız her şeyi bilirler.', 'يعلمون ما تفعلون'),
(5842, 82, 13, 'اِنَّ الْاَبْرَارَ لَف۪ي نَع۪يمٍۚ', 'İnnel ebrare lefi naim.', 'Birr[1] olanlar nimet[2] içindedirler.', 'ان الابرار لفي نعيم'),
(5843, 82, 14, 'وَاِنَّ الْفُجَّارَ لَف۪ي جَح۪يمٍۚ', 'Ve innel fuccare lefi cahim.', 'Facirler[1] Cehennemdedirler.', 'وان الفجار لفي جحيم'),
(5844, 82, 15, 'يَصْلَوْنَهَا يَوْمَ الدّ۪ينِ', 'Yaslevneha yevmed din.', 'Din Günü[1] ona yaslanırlar.', 'يصلونها يوم الدين'),
(5845, 82, 16, 'وَمَا هُمْ عَنْهَا بِغَٓائِب۪ينَۜ', 'Ve ma hum anha bi gaibin.', 'Onlar,  onda yanıp bitecek değillerdir.', 'وما هم عنها بغايبين'),
(5846, 82, 17, 'وَمَٓا اَدْرٰيكَ مَا يَوْمُ الدّ۪ينِۙ', 'Ve ma edrake ma yevmud din.', 'Din Günü\'nün ne olduğunu sen nereden bileceksin?', 'وما ادريك ما يوم الدين'),
(5847, 82, 18, 'ثُمَّ مَٓا اَدْرٰيكَ مَا يَوْمُ الدّ۪ينِۜ', 'Summe ma edrake ma yevmud din.', 'Evet,  din gününün ne olduğunu sen nereden bileceksin?', 'ثم ما ادريك ما يوم الدين'),
(5848, 82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْـٔاًۜ وَالْاَمْرُ يَوْمَئِذٍ لِلّٰهِ', 'Yevme la temliku nefsun li nefsin şey\'a, vel emru yevmeizin lillah.', 'O,  kimsenin kimseye yardım etmeye gücünün yetmeyeceği bir gündür. İzin Günü,  karar vermek bütünüyle Allah\'a aittir.[1]', 'يوم لا تملك نفس لنفس شيا والامر يوميذ لله'),
(5849, 83, 1, 'وَيْلٌ لِلْمُطَفِّف۪ينَۙ', 'Veylun lil mutaffifin.', 'Hile[1] yapanların vay haline!', 'ويل للمطففين'),
(5850, 83, 2, 'اَلَّذ۪ينَ اِذَا ا‌كْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَۘ', 'Ellezine izektalu alen nasi yestevfun.', 'Onlar,  alırlarken tam olarak ölçer,  tartarlar.', 'الذين اذا اكتالوا علي الناس يستوفون'),
(5851, 83, 3, 'وَاِذَا كَالُوهُمْ اَوْ وَزَنُوهُمْ يُخْسِرُونَۜ', 'Ve iza kaluhum ev vezenuhum yuhsirun.', 'Satarlarken eksik ölçer,  tartarlar.', 'واذا كالوهم او وزنوهم يخسرون'),
(5852, 83, 4, 'اَلَا يَظُنُّ اُو۬لٰٓئِكَ اَنَّهُمْ مَبْعُوثُونَۙ', 'Ela yezunnu ulaike ennehum meb\'usun.', 'Onlar diriltileceklerini bilmiyorlar mı?[1]', 'الا يظن اوليك انهم مبعوثون'),
(5853, 83, 5, 'لِيَوْمٍ عَظ۪يمٍۙ', 'Li yevmin azim.', 'Büyük bir gün için.', 'ليوم عظيم'),
(5854, 83, 6, 'يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَم۪ينَۜ', 'Yevme yekumun nasu li rabbil alemin.', 'O gün insanlar alemlerin Rabb\'inin divanında duracaklar.', 'يوم يقوم الناس لرب العلمين'),
(5855, 83, 7, 'كَلَّٓا اِنَّ كِتَابَ الْفُجَّارِ لَف۪ي سِجّ۪ينٍۜ', 'Kella inne kitabel fuccari le fi siccin.', 'Hayır! Kötülerin kayıtları kesinlikle siccindedir.[1]', 'كلا ان كتب الفجار لفي سجين');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(5856, 83, 8, 'وَمَٓا اَدْرٰيكَ مَا سِجّ۪ينٌۜ', 'Ve ma edrake ma siccin.', 'Siccinin ne olduğunu sen ne bileceksin!', 'وما ادريك ما سجين'),
(5857, 83, 9, 'كِتَابٌ مَرْقُومٌۜ', 'Kitabun merkum.', 'Her şeyin tek tek yazıldığı bir kitaptır.', 'كتب مرقوم'),
(5858, 83, 10, 'وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّب۪ينَۙ', 'Veylun yevmeizin lil mukezzibin.', 'İzin Günü,  yalanlayanların vay haline!', 'ويل يوميذ للمكذبين'),
(5859, 83, 11, 'اَلَّذ۪ينَ يُكَذِّبُونَ بِيَوْمِ الدّ۪ينِۜ', 'Ellezine yukezzibune bi yevmiddin.', 'Onlar,  Din Günü\'nü[1] yalanlıyorlar.', 'الذين يكذبون بيوم الدين'),
(5860, 83, 12, 'وَمَا يُكَذِّبُ بِه۪ٓ اِلَّا كُلُّ مُعْتَدٍ اَث۪يمٍۙ', 'Ve ma yukezzıbu bihi illa kullu mu\'tedin esim.', 'Onu haddi aşan günahkardan başka kimse yalanlamaz.', 'وما يكذب به الا كل معتد اثيم'),
(5861, 83, 13, 'اِذَا تُتْلٰى عَلَيْهِ اٰيَاتُنَا قَالَ اَسَاط۪يرُ الْاَوَّل۪ينَۜ', 'İza tutla aleyhi ayatuna kale esatirul evvelin.', 'Ona ayetlerimiz okunduğu zaman,  \"Eskilerin masalları.\" der.', 'اذا تتلي عليه ايتنا قال اسطير الاولين'),
(5862, 83, 14, 'كَلَّا بَلْ۔ رَانَ عَلٰى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ', 'Kella bel rane ala kulubihim ma kanu yeksibun.', 'Hayır,  hayır! Bilakis,  onların yapıp ettikleri şeyler kalplerini kararttı.', 'كلا بل ران علي قلوبهم ما كانوا يكسبون'),
(5863, 83, 15, 'كَلَّٓا اِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَۜ', 'Kella innehum an rabbihim yevmeizin le mahcubun.', 'Hayır! Onlar,  İzin Günü Rabb\'lerinden perdelenmiş olanlardır.[1]', 'كلا انهم عن ربهم يوميذ لمحجوبون'),
(5864, 83, 16, 'ثُمَّ اِنَّهُمْ لَصَالُوا الْجَح۪يمِۜ', 'Summe innehum le salul cahim.', 'Sonra onlar,  Cehennem\'e girecekler.', 'ثم انهم لصالوا الجحيم'),
(5865, 83, 17, 'ثُمَّ يُقَالُ هٰذَا الَّذ۪ي كُنْتُمْ بِه۪ تُكَذِّبُونَۜ', 'Summe yukalu hazellezi kuntum bihi tukezzibun.', 'Sonra da: \"İşte bu yalanlayıp durduğunuz şeydir.\" denecek.', 'ثم يقال هذا الذي كنتم به تكذبون'),
(5866, 83, 18, 'كَلَّٓا اِنَّ كِتَابَ الْاَبْرَارِ لَف۪ي عِلِّيّ۪ينَۜ', 'Kella inne kitabel ebrari lefi illiyyin.', 'Hayır! Kuşkusuz ebrar[1] olanların kayıtları kesinlikle İlliyyin\'dedir.[2]', 'كلا ان كتب الابرار لفي عليين'),
(5867, 83, 19, 'وَمَٓا اَدْرٰيكَ مَا عِلِّيُّونَۜ', 'Ve ma edrake ma ılliyyun.', 'İlliyyin\'in ne olduğunu sen ne bileceksin?', 'وما ادريك ما عليون'),
(5868, 83, 20, 'كِتَابٌ مَرْقُومٌۙ', 'Kitabun merkum.', 'Her şeyin tek tek yazıldığı bir kitaptır.[1]', 'كتب مرقوم'),
(5869, 83, 21, 'يَشْهَدُهُ الْمُقَرَّبُونَۜ', 'Yeşheduhul mukarrebun.', 'Yaklaştırılmış olanlar[1] ona tanık olurlar.', 'يشهده المقربون'),
(5870, 83, 22, 'اِنَّ الْاَبْرَارَ لَف۪ي نَع۪يمٍۙ', 'İnnel ebrare le fi naim.', 'Ebrar kesinlikle nimetler içindedir,', 'ان الابرار لفي نعيم'),
(5871, 83, 23, 'عَلَى الْاَرَٓائِكِ يَنْظُرُونَۙ', 'Alel eraiki yenzurun.', 'Tahtlar üzerinde nimetleri seyre dalarlar.', 'علي الارايك ينظرون'),
(5872, 83, 24, 'تَعْرِفُ ف۪ي وُجُوهِهِمْ نَضْرَةَ النَّع۪يمِۚ', 'Ta\'rifu fi vucuhihim nadraten naim.', 'Nimetlerin sevincini yüzlerinden anlarsın.', 'تعرف في وجوههم نضرة النعيم'),
(5873, 83, 25, 'يُسْقَوْنَ مِنْ رَح۪يقٍ مَخْتُومٍۙ', 'Yuskavne min rahikın mahtum.', 'Onlara mühürlenmiş[1] en leziz,  en saf içecekler[2] içirilir.', 'يسقون من رحيق مختوم'),
(5874, 83, 26, 'خِتَامُهُ مِسْكٌۜ وَف۪ي ذٰلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَۜ', 'Hitamuhu misk. ve fi zalike fel yetenafesil mutenafisun.', 'Onun sonu misktir.[1] Yarışanlar bunun için yarışsınlar.', 'ختمه مسك وفي ذلك فليتنافس المتنافسون'),
(5875, 83, 27, 'وَمِزَاجُهُ مِنْ تَسْن۪يمٍۙ', 'Ve mizacuhu min tesnim.', 'Onun katkısı tesnimdir.[1]', 'ومزاجه من تسنيم'),
(5876, 83, 28, 'عَيْناً يَشْرَبُ بِهَا الْمُقَرَّبُونَۜ', 'Aynen yeşrebu bihel mukarrabun.', 'Bir pınardır,  yakınlaştırılmış[1] olanların içtiği.', 'عينا يشرب بها المقربون'),
(5877, 83, 29, 'اِنَّ الَّذ۪ينَ اَجْرَمُوا كَانُوا مِنَ الَّذ۪ينَ اٰمَنُوا يَضْحَكُونَۘ', 'İnnellezine ecremu kanu minellezine amenu yadhakun.', 'Suçlular,  dünyada iman edenlere gülüyorlardı.', 'ان الذين اجرموا كانوا من الذين امنوا يضحكون'),
(5878, 83, 30, 'وَاِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَۘ', 'Ve iza merru bihim yetegamezune.', 'İnananlar yanlarından geçerlerken,  birbirlerine kaş-göz ederek onlarla alay ediyorlardı.', 'واذا مروا بهم يتغامزون'),
(5879, 83, 31, 'وَاِذَا انْقَلَـبُٓوا اِلٰٓى اَهْلِهِمُ انْقَلَبُوا فَكِه۪ينَۘ', 'Ve izenkalebu ila ehlihimunkalebu fekihin.', 'Yandaşlarına döndükleri zaman da neşelenmiş olarak dönüyorlardı.', 'واذا انقلبوا الي اهلهم انقلبوا فكهين'),
(5880, 83, 32, 'وَاِذَا رَاَوْهُمْ قَالُٓوا اِنَّ هٰٓؤُ۬لَٓاءِ لَضَٓالُّونَۙ', 'Ve iza reevhum kalu inne haulai ledallun.', 'İnananları gördükleri zaman,  \"İşte bunlar,  kesinlikle sapkın olanlardır.\" diyorlardı.', 'واذا راوهم قالوا ان هولا لضالون'),
(5881, 83, 33, 'وَمَٓا اُرْسِلُوا عَلَيْهِمْ حَافِظ۪ينَۜ', 'Ve ma ursilu aleyhim hafızin.', 'İnananların üzerlerine gözetici olarak gönderilmediler.[1]', 'وما ارسلوا عليهم حفظين'),
(5882, 83, 34, 'فَالْيَوْمَ الَّذ۪ينَ اٰمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَۙ', 'Felyevmellezine amenu minel kuffarı yadhakun.', 'Artık bugün iman edenler,  Kafirlere gülüyorlar.', 'فاليوم الذين امنوا من الكفار يضحكون'),
(5883, 83, 35, 'عَلَى الْاَرَٓائِكِۙ يَنْظُرُونَۜ', 'Alel eraiki yanzurun.', 'Tahtlar üzerinde seyirdeler:', 'علي الارايك ينظرون'),
(5884, 83, 36, 'هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ', 'Hel suvvibel kuffaru ma kanu yef\'alun.', '\"Kafirler,  yaptıkları şeylerin karşılığını buldular mı?\" diye.', 'هل ثوب الكفار ما كانوا يفعلون'),
(5885, 84, 1, 'اِذَا السَّمَٓاءُ انْشَقَّتْۙ', 'İzes semaunşakkat.', 'Gök yarıldığı zaman,', 'اذا السما انشقت'),
(5886, 84, 2, 'وَاَذِنَتْ لِرَبِّهَا وَحُقَّتْۙ', 'Ve ezinet li rabbiha ve hukkat.', 'Rabb\'inin buyruğunu yerine getirdiği zaman,', 'واذنت لربها وحقت'),
(5887, 84, 3, 'وَاِذَا الْاَرْضُ مُدَّتْۙ', 'Ve izel ardu muddet.', 'Yeryüzü uzatıldığı[1] zaman,', 'واذا الارض مدت'),
(5888, 84, 4, 'وَاَلْقَتْ مَا ف۪يهَا وَتَخَلَّتْۙ', 'Ve elkat ma fiha ve tehallet.', 'İçinde ne varsa atıp boşaldığı zaman,', 'والقت ما فيها وتخلت'),
(5889, 84, 5, 'وَاَذِنَتْ لِرَبِّهَا وَحُقَّتْۜ', 'Ve ezinet li rabbiha ve hukkat.', 'Rabb\'inin buyruğunu yerine getirdiği zaman,', 'واذنت لربها وحقت'),
(5890, 84, 6, 'يَٓا اَيُّهَا الْاِنْسَانُ اِنَّكَ كَادِحٌ اِلٰى رَبِّكَ كَدْحاً فَمُلَاق۪يهِۚ', 'Ya eyyuhel insanu inneke kadihun ila rabbike kedhan fe mulakih.', 'Ey insan! Rabb\'ine kavuşuncaya kadar didinip duracak ve sonunda O\'na kavuşacaksın.[1]', 'يايها الانسن انك كادح الي ربك كدحا فملقيه'),
(5891, 84, 7, 'فَاَمَّا مَنْ اُو۫تِيَ كِتَابَهُ بِيَم۪ينِه۪ۙ', 'Fe emma men utiye kitabehu bi yeminih.', 'Kime kitabı sağından[1] verilirse,', 'فاما من اوتي كتبه بيمينه'),
(5892, 84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَاباً يَس۪يراًۙ', 'Fe sevfe yuhasebu hısaben yesira.', 'Hesabı çok kolay görülecek.', 'فسوف يحاسب حسابا يسيرا'),
(5893, 84, 9, 'وَيَنْقَلِبُ اِلٰٓى اَهْلِه۪ مَسْرُوراًۜ', 'Ve yenkalibu ila ehlihi mesrura.', 'Ve sevinç içinde yakınlarına dönecek.', 'وينقلب الي اهله مسرورا'),
(5894, 84, 10, 'وَاَمَّا مَنْ اُو۫تِيَ كِتَابَهُ وَرَٓاءَ ظَهْرِه۪ۙ', 'Ve emma men utiye kitabehu verae zahrih.', 'Fakat kime kitabı arkasından[1] verilirse,', 'واما من اوتي كتبه ورا ظهره'),
(5895, 84, 11, 'فَسَوْفَ يَدْعُوا ثُبُوراًۙ', 'Fe sevfe yed\'u subura.', 'Ölüp yok olmak isteyecek.', 'فسوف يدعوا ثبورا'),
(5896, 84, 12, 'وَيَصْلٰى سَع۪يراًۜ', 'Ve yasla saira.', 'Fakat alevli ateşe girecek.', 'ويصلي سعيرا'),
(5897, 84, 13, 'اِنَّهُ  كَانَ ف۪ٓي اَهْلِه۪ مَسْرُوراً', 'İnnehu kane fi ehlihi mesrura.', 'O,  dünyada yakınları içindeyken sevinçliydi.', 'انه كان في اهله مسرورا'),
(5898, 84, 14, 'اِنَّهُ ظَنَّ اَنْ لَنْ يَحُورَۚۛ', 'İnnehu zanne en len yahur.', 'O,  kesinlikle dönmeyeceğini[1] sanıyordu.', 'انه ظن ان لن يحور'),
(5899, 84, 15, 'بَلٰىۚۛ  اِنَّ رَبَّهُ  كَانَ بِه۪ بَص۪يراًۜ', 'Bela, inne rabbehu kane bihi basira.', 'Bilakis! Rabb\'i onu çok iyi görüyordu.', 'بلي ان ربه كان به بصيرا'),
(5900, 84, 16, 'فَلَٓا اُقْسِمُ بِالشَّفَقِۙ', 'Fe la uksimu biş şefak.', 'Şafak vaktine yemin ederim;', 'فلا اقسم بالشفق'),
(5901, 84, 17, 'وَالَّيْلِ وَمَا وَسَقَۙ', 'Vel leyli ve ma vesak.', 'Geceye ve barındırdıklarına,', 'واليل وما وسق'),
(5902, 84, 18, 'وَالْقَمَرِ اِذَا اتَّسَقَۙ', 'Vel kameri izet tesak.', 'Dolunay halindeki aya,', 'والقمر اذا اتسق'),
(5903, 84, 19, 'لَتَرْكَبُنَّ طَبَقاً عَنْ طَبَقٍۜ', 'Le terkebunne tabakan an tabakın.', 'Kesinlikle tabakadan tabakaya bineceksiniz.[1]', 'لتركبن طبقا عن طبق'),
(5904, 84, 20, 'فَمَا لَهُمْ لَا يُؤْمِنُونَۙ', 'Fe ma lehum la yu\'minun.', 'Onların nesi var ki inanmıyorlar?', 'فما لهم لا يومنون'),
(5905, 84, 21, 'وَاِذَا قُرِئَ عَلَيْهِمُ الْقُرْاٰنُ لَا يَسْجُدُونَۜ', 'Ve iza kurıe aleyhimul kur\'anu la yescudun.', 'Kendilerine Kur\'an okunduğu[1] zaman secde[2] etmiyorlar.', 'واذا قري عليهم القران لا يسجدون'),
(5906, 84, 22, 'بَلِ الَّذ۪ينَ كَفَرُوا يُكَذِّبُونَۘ', 'Belillezine keferu yukezzibun.', 'Aksine,  Kafirler yalanlıyorlar.', 'بل الذين كفروا يكذبون'),
(5907, 84, 23, 'وَاللّٰهُ اَعْلَمُ بِمَا يُوعُونَۘ', 'Vallahu a\'lemu bima yuun.', 'Allah,  onların içlerinde ne sakladıklarını en iyi bilendir.', 'والله اعلم بما يوعون'),
(5908, 84, 24, 'فَبَشِّرْهُمْ بِعَذَابٍ اَل۪يمٍۙ', 'Fe beşşirhum bi azabin elim.', 'O halde onları elem verici azapla haberdar et!', 'فبشرهم بعذاب اليم'),
(5909, 84, 25, 'اِلَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ اَجْرٌ غَيْرُ مَمْنُونٍ', 'İllellezine amenu ve amilus salihati lehum ecrun gayru memnun.', 'Ancak iman eden ve salihatı yapanlar[1] hariç. Onlar için minnet altında bırakmayan bir ödül vardır.', 'الا الذين امنوا وعملوا الصلحت لهم اجر غير ممنون'),
(5910, 85, 1, 'وَالسَّمَٓاءِ ذَاتِ الْبُرُوجِۙ', 'Ves semai zatil buruc.', 'Burçlar sahibi gökyüzüne ant olsun,', 'والسما ذات البروج'),
(5911, 85, 2, 'وَالْيَوْمِ الْمَوْعُودِۙ', 'Vel yevmil mev\'ud.', 'Söz verilen güne ant olsun,', 'واليوم الموعود'),
(5912, 85, 3, 'وَشَاهِدٍ وَمَشْهُودٍۜ', 'Ve şahidin ve meşhud.', 'Tanığa ve tanıklık edilene ant olsun,', 'وشاهد ومشهود'),
(5913, 85, 4, 'قُتِلَ اَصْحَابُ الْاُخْدُودِۙ', 'Kutile ashabul uhdud.', 'Uhdud\'un Ashab\'ı[1] kahroldu;', 'قتل اصحب الاخدود'),
(5914, 85, 5, 'اَلنَّارِ ذَاتِ الْوَقُودِۙ', 'Ennari zatil vekud.', 'O şiddetli ateşin sahipleri.', 'النار ذات الوقود'),
(5915, 85, 6, 'اِذْ هُمْ عَلَيْهَا قُعُودٌۙ', 'İzhum aleyha kuud.', 'Hani onlar,  onun başında oturmuşlardı.', 'اذ هم عليها قعود'),
(5916, 85, 7, 'وَهُمْ عَلٰى مَا يَفْعَلُونَ بِالْمُؤْمِن۪ينَ شُهُودٌۜ', 'Ve hum ala ma yef\'alune bil mu\'minine şuhud.', 'Mü\'minlere yaptıklarını izliyorlardı.', 'وهم علي ما يفعلون بالمومنين شهود'),
(5917, 85, 8, 'وَمَا نَقَمُوا مِنْهُمْ  اِلَّٓا اَنْ يُؤْمِنُوا بِاللّٰهِ الْعَز۪يزِ الْحَم۪يدِۙ', 'Ve ma nekamu minhum illa en yu\'minu billahil azizil hamid.', 'Bunu,  Mutlak Üstün Olan ve Övgüye Değer Yegane Varlık olan Allah\'a iman edenleri cezalandırmak için yapıyorlardı.', 'وما نقموا منهم الا ان يومنوا بالله العزيز الحميد'),
(5918, 85, 9, 'اَلَّذ۪ي لَهُ مُلْكُ السَّمٰوَاتِ وَالْاَرْضِۜ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ شَه۪يدٌۜ', 'Ellezi lehu mulkus semavati vel ard, vallahu ala kulli şey\'in şehid.', 'O Allah ki,  göklerin ve yerin mülkü[1] yalnızca O\'na aittir. Allah,  Her Şeye Tanık\'tır.', 'الذي له ملك السموت والارض والله علي كل شي شهيد'),
(5919, 85, 10, 'اِنَّ الَّذ۪ينَ فَتَنُوا الْمُؤْمِن۪ينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَر۪يقِۜ', 'İnnellezine fetenul mu\'minine vel mu\'minati summe lem yetubu fe lehum azabu cehenneme ve lehum azabul harik.', 'Mü\'min erkeklere ve kadınlara fitne[1] yapıp,  sonra da kesin olarak tevbe etmeyenler için Cehennem azabı vardır. Onlar için yakıcı bir azap vardır.', 'ان الذين فتنوا المومنين والمومنت ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق'),
(5920, 85, 11, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُۜ ذٰلِكَ الْفَوْزُ الْـكَب۪يرُۜ', 'İnnellezine amenu ve amilus salihati lehum cennatun tecri min tahtihel enhar, zalikel fevzul kebir.', 'İnanan ve salihatı[1] yapanlar için içinden nehirler akan Cennetler vardır. İşte bu,  büyük kurtuluştur.', 'ان الذين امنوا وعملوا الصلحت لهم جنت تجري من تحتها الانهر ذلك الفوز الكبير'),
(5921, 85, 12, 'اِنَّ بَطْشَ رَبِّكَ لَشَد۪يدٌۜ', 'İnne batşe rabbike le şedid.', 'Rabb\'inin yakalaması[1] kesinlikle çok şiddetlidir.', 'ان بطش ربك لشديد'),
(5922, 85, 13, 'اِنَّهُ هُوَ يُبْدِئُ وَيُع۪يدُۚ', 'İnnehu huve yubdiu ve yuid.', 'Kuşkusuz başlatan ve tekrarlayan[1] O\'dur.', 'انه هو يبدي ويعيد'),
(5923, 85, 14, 'وَهُوَ الْغَفُورُ الْوَدُودُۙ', 'Ve huvel gafurul vedud.', 'O,  Çok Bağışlayan\'dır,  Çok Seven\'dir.', 'وهو الغفور الودود'),
(5924, 85, 15, 'ذُوالْعَرْشِ الْمَج۪يدُۙ', 'Zul arşil mecid.', 'Şanı Yüce Arş\'ın Sahibi\'dir.', 'ذو العرش المجيد'),
(5925, 85, 16, 'فَعَّالٌ لِمَا يُر۪يدُۜ', 'Fa\'alun lima yurid.', 'Dilediğini yapandır.', 'فعال لما يريد'),
(5926, 85, 17, 'هَلْ اَتٰيكَ حَد۪يثُ الْجُنُودِۙ', 'Hel etake hadisul cunud.', 'O orduların hadisi[1] sana geldi mi?', 'هل اتيك حديث الجنود'),
(5927, 85, 18, 'فِرْعَوْنَ وَثَمُودَۜ', 'Fir\'avne ve semud.', 'Firavun ve Semud\'un.', 'فرعون وثمود'),
(5928, 85, 19, 'بَلِ الَّذ۪ينَ كَفَرُوا ف۪ي تَكْذ۪يبٍۙ', 'Belillezine keferu fi tekzib.', 'Doğrusu Kafirler[1] hala bir yalanlama içindedirler.', 'بل الذين كفروا في تكذيب'),
(5929, 85, 20, 'وَاللّٰهُ مِنْ وَرَٓائِهِمْ مُح۪يطٌۚ', 'Vallahu min veraihim muhit.', 'Allah,  onları arkalarından[1] kuşatmıştır.', 'والله من ورايهم محيط'),
(5930, 85, 21, 'بَلْ هُوَ قُرْاٰنٌ مَج۪يدٌۙ', 'Bel huve kur\'anun mecid.', 'Bilakis,  o şanı yüce şerefli bir Kur\'an\'dır,', 'بل هو قران مجيد'),
(5931, 85, 22, 'ف۪ي لَوْحٍ مَحْفُوظٍ', 'Fi levhın mahfuz.', 'Levh-i Mahfuz\'dadır.[1]', 'في لوح محفوظ'),
(5932, 86, 1, 'وَالسَّمَٓاءِ وَالطَّارِقِۙ', 'Ves semai vet tarık.', 'Sema\'ya[1] ve Tarık\'a ant olsun,', 'والسما والطارق'),
(5933, 86, 2, 'وَمَٓا اَدْرٰيكَ مَا الطَّارِقُۙ', 'Ve ma edrake met tarik.', 'Tarık\'ın ne olduğunu sen ne bileceksin?', 'وما ادريك ما الطارق'),
(5934, 86, 3, 'اَلنَّجْمُ الثَّاقِبُۙ', 'En necmus sakıb.', 'O,  delici[1] yıldızdır.', 'النجم الثاقب'),
(5935, 86, 4, 'اِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌۜ', 'İn kullu nefsin lemma aleyha hafız.', 'Hiçbir nefs[1] yoktur ki üzerinde koruyucu[2] bulunmasın.', 'ان كل نفس لما عليها حافظ'),
(5936, 86, 5, 'فَلْيَنْظُرِ الْاِنْسَانُ مِمَّ خُلِقَۜ', 'Fel yenzuril insanu mimme hulık.', 'İnsan neden yaratıldığına bir baksın.', 'فلينظر الانسن مم خلق'),
(5937, 86, 6, 'خُلِقَ مِنْ مَٓاءٍ دَافِقٍۙ', 'Hulika min main dafik.', 'Dökülen bir sıvıdan yaratıldı;', 'خلق من ما دافق'),
(5938, 86, 7, 'يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَٓائِبِۜ', 'Yahrucu min beynis sulbi vet teraib.', 'Omurga ile göğüs kemikleri arasından çıkan.[1]', 'يخرج من بين الصلب والترايب'),
(5939, 86, 8, 'اِنَّهُ عَلٰى رَجْعِه۪ لَقَادِرٌۜ', 'İnnehu ala rec\'ıhi le kadir.', 'Kuşkusuz O,  onu yeniden diriltmeye elbette kadirdir.', 'انه علي رجعه لقادر'),
(5940, 86, 9, 'يَوْمَ تُبْلَى السَّرَٓائِرُۙ', 'Yevme tubles serair.', 'Bütün gizliliklerin ortaya çıkarıldığı gün,', 'يوم تبلي السراير'),
(5941, 86, 10, 'فَمَا لَهُ مِنْ قُوَّةٍ وَلَا نَاصِرٍۜ', 'Fema lehu min kuvvetin ve la nasır.', 'Onun ne bir gücü ne de bir yardımcısı vardır.', 'فما له من قوة ولا ناصر'),
(5942, 86, 11, 'وَالسَّمَٓاءِ ذَاتِ الرَّجْعِۙ', 'Ves semai zatir rec\'.', 'Dönüş sahibi semaya ant olsun,', 'والسما ذات الرجع'),
(5943, 86, 12, 'وَالْاَرْضِ ذَاتِ الصَّدْعِۙ', 'Vel ardı zatis sad\'.', 'Yarılma sahibi yeryüzüne ant olsun', 'والارض ذات الصدع'),
(5944, 86, 13, 'اِنَّهُ لَقَوْلٌ فَصْلٌۙ', 'İnnehu le kavlun fasl.', 'Kuşkusuz O,  ayırt edici[1] bir sözdür.', 'انه لقول فصل'),
(5945, 86, 14, 'وَمَا هُوَ بِالْهَزْلِۜ', 'Ve ma huve bil hezl.', 'O,  sıradan bir söz değildir.', 'وما هو بالهزل'),
(5946, 86, 15, 'اِنَّهُمْ يَك۪يدُونَ كَيْداًۙ', 'İnnehum yekidune keyda.', 'Onlar,  planlar yapıyorlar[1],', 'انهم يكيدون كيدا'),
(5947, 86, 16, 'وَاَ‌ك۪يدُ كَيْداًۚ', 'Ve ekidu keyda.', 'Ben de plan yapıyorum.', 'واكيد كيدا'),
(5948, 86, 17, 'فَمَهِّلِ الْـكَافِر۪ينَ اَمْهِلْهُمْ رُوَيْداً', 'Fe mehhilil kafirine emhilhum ruveyda.', 'Kafirlere biraz daha süre tanı,  onları kendi hallerine bırak.', 'فمهل الكفرين امهلهم رويدا'),
(5949, 87, 1, 'سَبِّحِ اسْمَ رَبِّكَ الْاَعْلٰىۙ', 'Sebbihısme rabbikel a\'la.', 'Rabb\'inin yüce adını tesbih[1] et.', 'سبح اسم ربك الاعلي'),
(5950, 87, 2, 'اَلَّذ۪ي خَلَقَ فَسَوّٰىۙۖ', 'Ellezi halaka fesevva.', 'O ki yarattı ve düzene koydu.', 'الذي خلق فسوي'),
(5951, 87, 3, 'وَالَّذ۪ي قَدَّرَ فَهَدٰىۙۖ', 'Vellezi kaddere fe heda.', 'O ki takdir etti[1] ve yol gösterdi.', 'والذي قدر فهدي'),
(5952, 87, 4, 'وَالَّـذ۪ٓي اَخْرَجَ الْمَرْعٰىۙۖ', 'Vellezi ahrecel mer\'a.', 'O ki yerden bitkiler,  yeşillikler çıkardı.', 'والذي اخرج المرعي'),
(5953, 87, 5, 'فَجَعَلَهُ غُثَٓاءً اَحْوٰىۜ', 'Fe cealehu gusaen ahva.', 'Derken onu kuru,  kararmış çer çöp haline getirdi.', 'فجعله غثا احوي'),
(5954, 87, 6, 'سَنُقْرِئُكَ فَلَا تَنْسٰىۙ', 'Senukriuke fe la tensa.', 'Sana okutacağız[1]; bir daha unutmayacaksın;[2]', 'سنقريك فلا تنسي'),
(5955, 87, 7, 'اِلَّا مَا شَٓاءَ اللّٰهُۜ  اِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفٰىۜ', 'İlla ma şaallah, innehu ya\'lemul cehre ve ma yahfa.', 'Allah,  aksini dilemedikçe. Kuşkusuz O,  açık ve gizli olanı bilir.[1]', 'الا ما شا الله انه يعلم الجهر وما يخفي'),
(5956, 87, 8, 'وَنُيَسِّرُكَ لِلْيُسْرٰىۚ', 'Ve nuyessiruke lil yusra.', 'Kolay gelmesi için,  sana yeterince kolaylaştıracağız.[1]', 'ونيسرك لليسري'),
(5957, 87, 9, 'فَذَكِّرْ اِنْ نَفَعَتِ الذِّكْرٰىۜ', 'Fe zekkir in nefeatiz zikra.', 'O halde öğüt ver[1],  öğüt yararlı olacaksa!', 'فذكر ان نفعت الذكري'),
(5958, 87, 10, 'سَيَذَّكَّرُ مَنْ يَخْشٰىۙ', 'Seyezzekkeru men yahşa.', 'Huşu[1] duyan kimse öğüt alacaktır.', 'سيذكر من يخشي'),
(5959, 87, 11, 'وَيَتَجَنَّبُهَا الْاَشْقٰىۙ', 'Ve yetecennebuhel eşka.', 'Şaki[1] olan ondan kaçınır.', 'ويتجنبها الاشقي'),
(5960, 87, 12, 'اَلَّذ۪ي يَصْلَى النَّارَ الْـكُبْرٰىۚ', 'Ellezi yaslen narel kubra.', 'Ki o,  büyük ateşe atılacaktır.', 'الذي يصلي النار الكبري'),
(5961, 87, 13, 'ثُمَّ لَا يَمُوتُ ف۪يهَا وَلَا يَحْيٰىۜ', 'Summe la yemutu fiha ve la yahya.', 'Sonra orada ölüm de yok,  yaşam da.[1]', 'ثم لا يموت فيها ولا يحيي'),
(5962, 87, 14, 'قَدْ اَفْلَحَ مَنْ تَزَكّٰىۙ', 'Kad efleha men tezekka.', 'Doğrusu arınan kimse kurtuluşa ermiştir;', 'قد افلح من تزكي'),
(5963, 87, 15, 'وَذَكَرَ اسْمَ رَبِّه۪ فَصَلّٰىۜ', 'Ve zekeresme rabbihi fe salla.', 'Rabb\'inin adını anıp salla[1] eden.', 'وذكر اسم ربه فصلي'),
(5964, 87, 16, 'بَلْ تُؤْثِرُونَ الْحَيٰوةَ الدُّنْيَاۘ', 'Bel tu\'sırunel hayated dunya.', 'Ne var ki siz[1] dünya hayatını tercih ediyorsunuz.', 'بل توثرون الحيوة الدنيا'),
(5965, 87, 17, 'وَالْاٰخِرَةُ خَيْرٌ وَاَبْـقٰىۜ', 'Vel ahıretu hayrun ve ebka.', 'Oysaki ahiret hayatı daha hayırlı ve daha kalıcıdır.', 'والاخرة خير وابقي'),
(5966, 87, 18, 'اِنَّ هٰذَا لَفِي الصُّحُفِ الْاُو۫لٰىۙ', 'İnne haza le fis suhufil ula.', 'Bu,  önceki sahifelerde[1] de vardı.', 'ان هذا لفي الصحف الاولي'),
(5967, 87, 19, 'صُحُفِ اِبْرٰه۪يمَ وَمُوسٰى', 'Suhufi ibrahime ve musa.', 'İbrahim\'ın ve Musa\'nın.', 'صحف ابرهيم وموسي'),
(5968, 88, 1, 'هَلْ اَتٰيكَ حَد۪يثُ الْغَاشِيَةِۜ', 'Hel etake hadisul gaşiyeh.', 'Ğaşiyenin[1] hadisi[2] sana geldi mi?', 'هل اتيك حديث الغشية'),
(5969, 88, 2, 'وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌۙ', 'Vucuhun yevmeizin haşiah.', 'İzin Günü[1] birtakım yüzler öne düşüktür;[2]', 'وجوه يوميذ خشعة'),
(5970, 88, 3, 'عَامِلَةٌ نَاصِبَةٌۙ', 'Amiletun nasıbeh.', 'Bitmiş,  tükenmiş olarak.[1]', 'عاملة ناصبة'),
(5971, 88, 4, 'تَصْلٰى نَاراً حَامِيَةًۙ', 'Tesla naren hamiyeh.', 'Kızgın ateşe atılacaklar.', 'تصلي نارا حامية'),
(5972, 88, 5, 'تُسْقٰى مِنْ عَيْنٍ اٰنِيَةٍۜ', 'Tuska min aynin aniyeh.', 'Kaynar bir kaynaktan içirilirler.', 'تسقي من عين انية'),
(5973, 88, 6, 'لَيْسَ لَهُمْ طَعَامٌ اِلَّا مِنْ ضَر۪يعٍۙ', 'Leyse lehum taamun illa min dari\'.', 'Onlar için kuru dikenli bir bitkiden başka yiyecek yoktur;', 'ليس لهم طعام الا من ضريع'),
(5974, 88, 7, 'لَا يُسْمِنُ وَلَا يُغْن۪ي مِنْ جُوعٍۜ', 'La yusminu ve la yugni min cu\'.', 'O,  beslemez ve açlığı gidermez.', 'لا يسمن ولا يغني من جوع'),
(5975, 88, 8, 'وُجُوهٌ يَوْمَئِذٍ نَاعِمَةٌۙ', 'Vucuhun yevmeizin naımeh.', 'İzin Günü birtakım yüzler[1] nimetler içindedirler.', 'وجوه يوميذ ناعمة'),
(5976, 88, 9, 'لِسَعْيِهَا رَاضِيَةٌۙ', 'Li sa\'yiha radiyeh.', 'Yaptıklarından dolayı hoşnutturlar.', 'لسعيها راضية'),
(5977, 88, 10, 'ف۪ي جَنَّةٍ عَالِيَةٍۙ', 'Fi cennetin aliyeh.', 'Mükemmel bir bahçededirler.', 'في جنة عالية'),
(5978, 88, 11, 'لَا تَسْمَعُ ف۪يهَا لَاغِيَةًۜ', 'La tesmeu fiha lagıyeh.', 'Orada boş söz duymazlar.', 'لا تسمع فيها لغية'),
(5979, 88, 12, 'ف۪يهَا عَيْنٌ جَارِيَةٌۢ', 'Fiha aynun cariyeh.', 'Orada devamlı akan bir pınar vardır.', 'فيها عين جارية'),
(5980, 88, 13, 'ف۪يهَا سُرُرٌ مَرْفُوعَةٌۙ', 'Fiha sururun merfuah.', 'Yükseklere kurulmuş divanlar,', 'فيها سرر مرفوعة'),
(5981, 88, 14, 'وَاَكْوَابٌ مَوْضُوعَةٌۙ', 'Ve ekvabun mevduah.', 'İçime hazır içecekler,', 'واكواب موضوعة'),
(5982, 88, 15, 'وَنَمَارِقُ مَصْفُوفَةٌۙ', 'Ve nemarıku masfufeh.', 'Sıra sıra yastıklar,', 'ونمارق مصفوفة'),
(5983, 88, 16, 'وَزَرَابِيُّ مَبْثُوثَةٌۜ', 'Ve zerabiyyu mebsuseh.', 'Serilmiş halılar vardır.', 'وزرابي مبثوثة'),
(5984, 88, 17, 'اَفَلَا يَنْظُرُونَ اِلَى الْاِبِلِ كَيْفَ خُلِقَتْ۠', 'E fe la yanzurune ilel ibili keyfe hulikat.', 'Hiç mi deveye[1] bakmıyorlar,  nasıl yaratılmış?', 'افلا ينظرون الي الابل كيف خلقت'),
(5985, 88, 18, 'وَاِلَى السَّمَٓاءِ كَيْفَ رُفِعَتْ۠', 'Ve iles semai keyfe rufiat.', 'Ve gökyüzüne,  nasıl yükseltilmiş?', 'والي السما كيف رفعت'),
(5986, 88, 19, 'وَاِلَى الْجِبَالِ كَيْفَ نُصِبَتْ۠', 'Ve ilel cibali keyfe nusıbet.', 'Ve dağlara,  nasıl dikilmişler?', 'والي الجبال كيف نصبت'),
(5987, 88, 20, 'وَاِلَى الْاَرْضِ كَيْفَ سُطِحَتْ۠', 'Ve ilel ardı keyfe sutıhat.', 'Ve yeryüzüne,  nasıl yayılıp döşenmiş?', 'والي الارض كيف سطحت'),
(5988, 88, 21, 'فَذَكِّرْ اِنَّـمَٓا اَنْتَ مُذَكِّرٌۜ', 'Fezekkir innema ente muzekkir.', 'Öğüt ver; sen yalnızca öğüt vericisin.', 'فذكر انما انت مذكر'),
(5989, 88, 22, 'لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍۙ', 'Leste aleyhim bi musaytır.', 'Kimseyi zorla inandıracak değilsin.', 'لست عليهم بمصيطر'),
(5990, 88, 23, 'اِلَّا مَنْ تَوَلّٰى وَكَفَرَۙ', 'İlla men tevella ve kefer.', 'Ancak kim yüz çevirir ve Kafir olursa,', 'الا من تولي وكفر'),
(5991, 88, 24, 'فَيُعَذِّبُهُ اللّٰهُ الْعَذَابَ الْاَكْبَرَۜ', 'Fe yuazzibuhullahul azabel ekber.', 'Allah,  ona en büyük azapla azap eder.', 'فيعذبه الله العذاب الاكبر'),
(5992, 88, 25, 'اِنَّ اِلَيْنَٓا اِيَابَهُمْۙ', 'İnne ileyna iyabehum.', 'Kuşkusuz onların dönüşü Bizedir.', 'ان الينا ايابهم'),
(5993, 88, 26, 'ثُمَّ اِنَّ عَلَيْنَا حِسَابَهُمْ', 'Summe inne aleyna hisabehum.', 'Sonra,  kuşkusuz onların hesapları kesinlikle Bize aittir.', 'ثم ان علينا حسابهم'),
(5994, 89, 1, 'وَالْفَجْرِۙ', 'Vel fecr.', 'Fecre[1] ant olsun.', 'والفجر'),
(5995, 89, 2, 'وَلَيَالٍ عَشْرٍۙ', 'Ve leyalin aşr.', 'On geceye,', 'وليال عشر'),
(5996, 89, 3, 'وَالشَّفْعِ وَالْوَتْرِۙ', 'Veş şef\'ı vel vetr.', 'Çift ve tek olana,', 'والشفع والوتر'),
(5997, 89, 4, 'وَالَّيْلِ اِذَا يَسْرِۚ', 'Vel leyli iza yesr.', 'Geçip giden geceye.', 'واليل اذا يسر'),
(5998, 89, 5, 'هَلْ ف۪ي ذٰلِكَ قَسَمٌ لِذ۪ي حِجْرٍۜ', 'Hel fi zalike kasemun lizi hicr.', 'İşte bunlarda aklını kullanan kimse[1] için bir kasem[2] yok mu?', 'هل في ذلك قسم لذي حجر'),
(5999, 89, 6, 'اَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍۙۖ', 'E lem tere keyfe feale rabbuke bi ad.', 'Rabb\'inin Âd kavmine ne yaptığını biliyor musun?', 'الم تر كيف فعل ربك بعاد'),
(6000, 89, 7, 'اِرَمَ ذَاتِ الْعِمَادِۙۖ', 'İreme zatil ımad.', 'Sütunlara sahip İrem\'e!', 'ارم ذات العماد'),
(6001, 89, 8, 'اَلَّت۪ي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلَادِۙۖ', 'Elleti lem yuhlak misluha fil bilad.', 'Ki,  beldeler içinde onun bir eşi yaratılmadı;', 'التي لم يخلق مثلها في البلد'),
(6002, 89, 9, 'وَثَمُودَ الَّذ۪ينَ جَابُوا الصَّخْرَ بِالْوَادِۙۖ', 'Ve semudelleziyne cabussahre bil vad.', 'Ve vadide kayaları oyan Semud\'a,', 'وثمود الذين جابوا الصخر بالواد'),
(6003, 89, 10, 'وَفِرْعَوْنَ ذِي الْاَوْتَادِۙۖ', 'Ve fir avne zil evtad.', 'Ve kazıklar sahibi Firavun\'a;', 'وفرعون ذي الاوتاد'),
(6004, 89, 11, 'اَلَّذ۪ينَ طَغَوْا فِي الْبِلَادِۙۖ', 'Ellezine tagav fil bilad.', 'Onlar ki,  ülkelerde tağutlaşmışlardı[1],', 'الذين طغوا في البلد'),
(6005, 89, 12, 'فَاَكْثَرُوا ف۪يهَا الْفَسَادَۙۖ', 'Fe ekseru fihel fesad.', 'Böylece oralarda bozgunculuğu çoğaltmışlardı.', 'فاكثروا فيها الفساد'),
(6006, 89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍۙۖ', 'Fe sabbe aleyhim rabbuke sevta azab.', 'Bu yüzden Rabb\'in onları azap kırbacıyla kırbaçladı.', 'فصب عليهم ربك سوط عذاب'),
(6007, 89, 14, 'اِنَّ رَبَّكَ لَبِالْمِرْصَادِۜ', 'İnne rabbeke le bil mirsad.', 'Çünkü Rabb\'in olup-biteni görüp-gözlemektedir.', 'ان ربك لبالمرصاد'),
(6008, 89, 15, 'فَاَمَّا الْاِنْسَانُ اِذَا مَا ابْتَلٰيهُ رَبُّهُ فَاَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبّ۪ٓي اَكْرَمَنِۜ', 'Fe emmel insanu iza mebtelahu rabbuhu fe ekremehu ve na\'amehu fe yekulu rabbi ekremen.', 'Fakat o insan[1]; Rabb\'i ne zaman onu sınamak için ikramda bulunsa ve ona nimet verse,  \"Rabb\'im bana ikram etti.[2]\" der.', 'فاما الانسن اذا ما ابتليه ربه فاكرمه ونعمه فيقول ربي اكرمن'),
(6009, 89, 16, 'وَاَمَّٓا اِذَا مَا ابْتَلٰيهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبّ۪ٓي اَهَانَنِۚ', 'Ve emma iza mebtelahu fe kadere aleyhi rızkahu fe yekulu rabbi ehanen.', 'Fakat ne zaman ona sınamak için rızkını ölçülü verirse[1],  \"Rabb\'im beni alçaltı.[2]\" der.', 'واما اذا ما ابتليه فقدر عليه رزقه فيقول ربي اهنن'),
(6010, 89, 17, 'كَلَّا بَلْ لَا تُكْرِمُونَ الْيَت۪يمَۙ', 'Kella bel la tukrimunel yetim.', 'Hayır! Doğrusu siz yetime ikram etmiyorsunuz.', 'كلا بل لا تكرمون اليتيم'),
(6011, 89, 18, 'وَلَا تَحَٓاضُّونَ عَلٰى طَعَامِ الْمِسْك۪ينِۙ', 'Ve la tehaddune ala taamil miskin.', 'Yoksulu yedirmede birbirinizi teşvik etmiyorsunuz.', 'ولا تحضون علي طعام المسكين'),
(6012, 89, 19, 'وَتَأْكُلُونَ التُّرَاثَ اَكْلاً لَماًّۙ', 'Ve te\'kulunet turase eklen lemma.', 'Varis olduğunuz mirası ihtirasla yiyorsunuz[1].', 'وتاكلون التراث اكلا لما'),
(6013, 89, 20, 'وَتُحِبُّونَ الْمَالَ حُباًّ جَماًّۜ', 'Ve tuhıbbunel male hubben cemma.', 'Malı büyük bir sevgiyle,  çok seviyorsunuz.', 'وتحبون المال حبا جما'),
(6014, 89, 21, 'كَلَّٓا اِذَا دُكَّتِ الْاَرْضُ دَكاًّ دَكاًّۙ', 'Kella iza dukketil ardu dekken dekka.', 'Hayır,  hayır! Yer,  paramparça olup dağıldığı zaman,', 'كلا اذا دكت الارض دكا دكا'),
(6015, 89, 22, 'وَجَٓاءَ رَبُّكَ وَالْمَلَكُ صَفاًّ صَفاًّۚ', 'Ve cae rabbuke vel meleku saffen saffa.', 'Rabb\'in emri geldiği ve melekler saf saf dizildiği zaman,', 'وجا ربك والملك صفا صفا'),
(6016, 89, 23, 'وَج۪ٓيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْاِنْسَانُ وَاَنّٰى لَهُ الذِّكْرٰىۜ', 'Ve cie yevmeizin bi cehenneme yevmeizin yetezekkerul insanu ve enna lehuz zikra.', 'İzin Günü Cehennem ortaya getirilir. O gün insan neyin ne olduğunu anlar,  ancak bunun ona bir yararı olmaz.', 'وجاي يوميذ بجهنم يوميذ يتذكر الانسن واني له الذكري'),
(6017, 89, 24, 'يَقُولُ يَا لَيْتَن۪ي قَدَّمْتُ لِحَيَات۪يۚ', 'Yekulu ya leyteni kaddemtu li hayati.', '\"Ah keşke hayattayken,  ahiret hayatım için hazırlık yapmış olsaydım.\" der.', 'يقول يليتني قدمت لحياتي'),
(6018, 89, 25, 'فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُٓ  اَحَدٌۙ', 'Fe yevmeizin la yuazzibu azabehu ehad.', 'Artık İzin Günü,  O\'nun azabı hiç kimsenin azabına benzemez.', 'فيوميذ لا يعذب عذابه احد'),
(6019, 89, 26, 'وَلَا يُوثِقُ وَثَاقَهُٓ اَحَدٌۜ', 'Ve la yusiku ve sakahu ehad.', 'O\'nun vurduğu bağ,  hiç kimsenin vurduğu bağa benzemez.', 'ولا يوثق وثاقه احد'),
(6020, 89, 27, 'يَٓا اَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُۗ', 'Ya eyyetuhen nefsul mutmainneh.', '\"Ey mutmain nefs![1]', 'يايتها النفس المطمينة'),
(6021, 89, 28, 'اِرْجِع۪ٓي اِلٰى رَبِّكِ رَاضِيَةً مَرْضِيَّةًۚ', 'İrcii ila rabbiki radıyeten mardıyyeh.', 'Rızasını kazanarak,  razı olarak Rabb\'ine dön.[1]', 'ارجعي الي ربك راضية مرضية'),
(6022, 89, 29, 'فَادْخُل۪ي ف۪ي عِبَاد۪يۙ', 'Fedhuli fi ibadi.', 'Kullarıma katıl[1];', 'فادخلي في عبدي'),
(6023, 89, 30, 'وَادْخُل۪ي جَنَّت۪ي', 'Vedhuli cenneti.', 'Cennetime gir.\"', 'وادخلي جنتي'),
(6024, 90, 1, 'لَٓا اُقْسِمُ بِهٰذَا الْبَلَدِۙ', 'La uksimu bi hazel beled.', 'Hayır! Bu beldeye yemin ederim!', 'لا اقسم بهذا البلد'),
(6025, 90, 2, 'وَاَنْتَ حِلٌّ بِهٰذَا الْبَلَدِۙ', 'Ve ente hıllun bi hazel beled.', 'Senin de içinde yaşadığın beldeye,', 'وانت حل بهذا البلد'),
(6026, 90, 3, 'وَوَالِدٍ وَمَا وَلَدَۙ', 'Ve validin ve ma veled.', 'Ant olsun doğurana ve doğurduğuna!', 'ووالد وما ولد'),
(6027, 90, 4, 'لَقَدْ خَلَقْنَا الْاِنْسَانَ ف۪ي كَبَدٍۜ', 'Lekad halaknel insane fi kebed.', 'Biz insanı gerçekten zorluk arasında yarattık.', 'لقد خلقنا الانسن في كبد'),
(6028, 90, 5, 'اَيَحْسَبُ اَنْ لَنْ يَقْدِرَ عَلَيْهِ اَحَدٌۢ', 'E yahsebu en len yakdira aleyhi ehad.', 'Kendisine hiç kimsenin güç yetiremeyeceğini mi sanıyor?', 'ايحسب ان لن يقدر عليه احد'),
(6029, 90, 6, 'يَقُولُ اَهْلَكْتُ مَالاً لُبَداًۜ', 'Yekulu ehlektu malen lubeda.', '\"Yığınlarca mal harcadım.\" diyor.', 'يقول اهلكت مالا لبدا'),
(6030, 90, 7, 'اَيَحْسَبُ اَنْ لَمْ يَرَهُٓ  اَحَدٌۜ', 'E yahsebu en lem yerahu ehad.', 'Kendisini hiç kimsenin görmediğini mi sanıyor?', 'ايحسب ان لم يره احد'),
(6031, 90, 8, 'اَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِۙ', 'E lem nec\'al lehu ayneyn.', 'Ona iki gözü Biz vermedik mi?', 'الم نجعل له عينين'),
(6032, 90, 9, 'وَلِسَاناً وَشَفَتَيْنِۙ', 'Ve lisanen ve şefeteyn.', 'Bir dil ve iki dudak.', 'ولسانا وشفتين'),
(6033, 90, 10, 'وَهَدَيْنَاهُ النَّجْدَيْنِۚ', 'Ve hedeynahun necdeyn.', 'Ona iki yol[1] gösterdik.', 'وهدينه النجدين'),
(6034, 90, 11, 'فَلَا اقْتَحَمَ الْعَقَبَةَۘ', 'Fe laktehamel akabete.', 'Ne var ki o,  sarp yokuşu aşmayı göze alamadı.[1]', 'فلا اقتحم العقبة'),
(6035, 90, 12, 'وَمَٓا اَدْرٰيكَ مَا الْعَقَبَةُۜ', 'Ve ma edrake mel akabeh.', 'Bilir misin nedir sarp yokuş?', 'وما ادريك ما العقبة'),
(6036, 90, 13, 'فَكُّ رَقَبَةٍۙ', 'Fekku rekabetin.', 'Boynu çözmektir, [1]', 'فك رقبة'),
(6037, 90, 14, 'اَوْ اِطْعَامٌ ف۪ي يَوْمٍ ذ۪ي مَسْغَبَةٍۙ', 'Ev ıt\'amun fi yevmin zi mesgabeh.', 'Veya darlık ve yoklukta doyurmaktır;', 'او اطعم في يوم ذي مسغبة'),
(6038, 90, 15, 'يَت۪يماً ذَا مَقْرَبَةٍۙ', 'Yetimen za makrabeh.', 'Yakınlık sahibi olan yetimi, [1]', 'يتيما ذا مقربة'),
(6039, 90, 16, 'اَوْ مِسْك۪يناً ذَا مَتْرَبَةٍۜ', 'Ev miskinen za metrabeh.', 'Veya hiçbir şeyi olmayan miskini, [1]', 'او مسكينا ذا متربة'),
(6040, 90, 17, 'ثُمَّ كَانَ مِنَ الَّذ۪ينَ اٰمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِۜ', 'Summe kane minellezine amenu ve tevasav bis sabri ve tevasav bil merhame.', 'Sonra birbirlerine sabrı[1] ve merhameti tavsiye eden inananlardan olmaktır.', 'ثم كان من الذين امنوا وتواصوا بالصبر وتواصوا بالمرحمة'),
(6041, 90, 18, 'اُو۬لٰٓئِكَ اَصْحَابُ الْمَيْمَنَةِۜ', 'Ulaike ashabul meymeneh.', 'İşte onlar,  ashab-ı meymenedir.[1]', 'اوليك اصحب الميمنة'),
(6042, 90, 19, 'وَالَّذ۪ينَ كَفَرُوا بِاٰيَاتِنَا هُمْ اَصْحَابُ الْمَشْـَٔمَةِۜ', 'Vellezine keferu bi ayatina hum ashabul meş\'emeh.', 'Ayetlerimizi küfredenler ashab-ı meşemedir.[1]', 'والذين كفروا بايتنا هم اصحب المشمة'),
(6043, 90, 20, 'عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ', 'Aleyhim narun mu\'sadeh.', 'Onlara,  üzerlerine kapıları kapatılmış bir ateş vardır.', 'عليهم نار موصدة'),
(6044, 91, 1, 'وَالشَّمْسِ وَضُحٰيهَاۙۖ', 'Veş şemsi ve duhaha.', 'Güneş\'e ve onun aydınlığına ant olsun,', 'والشمس وضحيها'),
(6045, 91, 2, 'وَالْقَمَرِ اِذَا تَلٰيهَاۙۖ', 'Vel kameri iza telaha.', 'Ve onu izleyen Ay\'a,', 'والقمر اذا تليها'),
(6046, 91, 3, 'وَالنَّهَارِ اِذَا جَلّٰيهَاۙۖ', 'Ven nehari iza cellaha.', 'Ve onu ortaya çıkaran gündüze,', 'والنهار اذا جليها'),
(6047, 91, 4, 'وَالَّيْلِ اِذَا يَغْشٰيهَاۙۖ', 'Vel leyli iza yagşaha.', 'Ve onu örten geceye,', 'واليل اذا يغشيها'),
(6048, 91, 5, 'وَالسَّمَٓاءِ وَمَا بَنٰيهَاۙۖ', 'Ves semai ve ma benaha.', 'Ve göğe ve onu düzenleyene,', 'والسما وما بنيها'),
(6049, 91, 6, 'وَالْاَرْضِ وَمَا طَحٰيهَاۙۖ', 'Vel ardı ve ma tahaha.', 'Ve yere ve onu döşeyene,', 'والارض وما طحيها'),
(6050, 91, 7, 'وَنَفْسٍ وَمَا سَوّٰيهَاۙۖ', 'Ve nefsin ve ma sevvaha.', 'Ve nefse[1] ve onu biçimlendirene,', 'ونفس وما سويها'),
(6051, 91, 8, 'فَاَلْهَمَهَا فُجُورَهَا وَتَقْوٰيهَاۙۖ', 'Fe elhemeha fucureha ve takvaha.', 'Sonra ona fücurunu[1] ve takvasını[2] ilham[3] etti.', 'فالهمها فجورها وتقويها'),
(6052, 91, 9, 'قَدْ اَفْلَحَ مَنْ زَكّٰيهَاۙۖ', 'Kad efleha men zekkaha.', 'Elbette zekka[1] eden kurtuluşa ermiştir.', 'قد افلح من زكيها'),
(6053, 91, 10, 'وَقَدْ خَابَ مَنْ دَسّٰيهَاۜ', 'Ve kad habe men dessaha.', 'Elbette onu kirleten[1] de hüsrana uğramıştır.', 'وقد خاب من دسيها'),
(6054, 91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوٰيهَاۙۖ', 'Kezzebet semudu bi tagvaha.', 'Semud halkı tağutluğu[1] nedeniyle yalanladı.', 'كذبت ثمود بطغويها'),
(6055, 91, 12, 'اِذِ انْبَعَثَ اَشْقٰيهَاۙۖ', 'İzin baase eşkaha.', 'Onların en azgını ayaklandığı zaman,', 'اذ انبعث اشقيها'),
(6056, 91, 13, 'فَقَالَ لَهُمْ رَسُولُ اللّٰهِ نَاقَةَ اللّٰهِ وَسُقْيٰيهَا۠', 'Fe kale lehum resulullahi nakatallahi ve sukyaha.', 'Allah\'ın resulü Salih onlara,  \"O,  Allah\'ın dişi devesidir,  onun su içme hakkına dokunmayın.\" dedi.', 'فقال لهم رسول الله ناقة الله وسقيها'),
(6057, 91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَاۙۖ فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوّٰيهَاۙۖ', 'Fe kezzebuhu fe akaruha fe demdeme aleyhim rabbuhum bi zenbihim fe sevvaha.', 'Fakat onu yalanladılar. Sonra onu kestiler. Rabb\'leri suçları nedeniyle üzerlerini azapla kapladı. Orayı yerle bir etti.', 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسويها'),
(6058, 91, 15, 'وَلَا يَخَافُ عُقْبٰيهَا', 'Ve la yehafu ukbaha.', 'O cezalandırmasının sonucundan çekinmez.', 'ولا يخاف عقبها'),
(6059, 92, 1, 'وَالَّيْلِ اِذَا يَغْشٰىۙ', 'Vel leyli iza yagşa.', 'Örttüğü zaman geceye ant olsun.', 'واليل اذا يغشي'),
(6060, 92, 2, 'وَالنَّهَارِ اِذَا تَجَلّٰىۙ', 'Ven nehari iza tecella.', 'Ortaya çıktığı zaman gündüze,', 'والنهار اذا تجلي'),
(6061, 92, 3, 'وَمَا خَلَقَ الذَّكَرَ وَالْاُنْثٰىۙ', 'Ve ma halakaz zekera vel unsa.', 'Erkeği ve dişiyi yaratana,', 'وما خلق الذكر والانثي'),
(6062, 92, 4, 'اِنَّ سَعْيَكُمْ لَشَتّٰىۜ', 'İnne sa\'yekum le şetta.', 'Çabalarınız çeşit çeşittir.', 'ان سعيكم لشتي'),
(6063, 92, 5, 'فَاَمَّا مَنْ اَعْطٰى وَاتَّقٰىۙ', 'Fe emma men a\'ta vetteka.', 'Fakat kim verir ve takva[1] sahibi olursa,', 'فاما من اعطي واتقي'),
(6064, 92, 6, 'وَصَدَّقَ بِالْحُسْنٰىۙ', 'Ve saddeka bil husna.', 'En iyiyi doğrularsa,', 'وصدق بالحسني'),
(6065, 92, 7, 'فَسَنُيَسِّرُهُ لِلْيُسْرٰىۜ', 'Fe senuyessiruhu lil yusra.', 'Ona en kolayı[1] kolaylaştıracağız.', 'فسنيسره لليسري'),
(6066, 92, 8, 'وَاَمَّا مَنْ بَخِلَ وَاسْتَغْنٰىۙ', 'Ve emma men bahıle vestagna.', 'Fakat kim cimrilik eder de kendisini müstağni[1] görürse,', 'واما من بخل واستغني'),
(6067, 92, 9, 'وَكَذَّبَ بِالْحُسْنٰىۙ', 'Ve kezzebe bil husna.', 'En iyiyi yalanlarsa,', 'وكذب بالحسني'),
(6068, 92, 10, 'فَسَنُيَسِّرُهُ لِلْعُسْرٰىۜ', 'Fe senuyessiruhu lil usra.', 'Ona en zoru[1] kolaylaştıracağız.', 'فسنيسره للعسري'),
(6069, 92, 11, 'وَمَا يُغْن۪ي عَنْهُ مَالُـهُٓ اِذَا تَرَدّٰىۜ', 'Ve ma yugni anhu maluhu iza teredda.', 'Düştüğü[1] zaman malı ona yarar sağlamaz.', 'وما يغني عنه ماله اذا تردي'),
(6070, 92, 12, 'اِنَّ عَلَيْنَا لَلْهُدٰىۘ', 'İnne aleyna lel huda.', 'Kuşkusuz doğru yolu göstermek Bize aittir.', 'ان علينا للهدي'),
(6071, 92, 13, 'وَاِنَّ لَنَا لَلْاٰخِرَةَ وَالْاُو۫لٰى', 'Ve inne lena lel ahırete vel ula.', 'Kuşkusuz ilk[1] de son[1] da Bizimdir.', 'وان لنا للاخرة والاولي'),
(6072, 92, 14, 'فَاَنْذَرْتُكُمْ نَاراً تَلَظّٰىۚ', 'Fe enzertukum naren telezza.', 'Alev saçan bir ateşe karşı sizi uyardım.', 'فانذرتكم نارا تلظي'),
(6073, 92, 15, 'لَا يَصْلٰيهَٓا اِلَّا الْاَشْقٰىۙ', 'La yaslaha illel eşka.', 'Ona şaki[1] olandan başkası girmez.', 'لا يصليها الا الاشقي'),
(6074, 92, 16, 'اَلَّذ۪ي كَذَّبَ وَتَوَلّٰىۜ', 'Ellezi kezzebe ve tevella.', 'O ki yalanladı ve yüz çevirdi.', 'الذي كذب وتولي'),
(6075, 92, 17, 'وَسَيُجَنَّبُهَا الْاَتْقٰىۙ', 'Ve seyucennebuhel etka.', 'Takva sahibi olan,  ondan uzak tutulacak.', 'وسيجنبها الاتقي'),
(6076, 92, 18, 'اَلَّذ۪ي يُؤْت۪ي مَالَهُ يَتَزَكّٰىۚ', 'Ellezi yu\'ti ma lehu yetezekka.', 'O ki malını vererek arınır.', 'الذي يوتي ماله يتزكي'),
(6077, 92, 19, 'وَمَا لِاَحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزٰىۙ', 'Ve ma li ehadin indehu min ni\'metin tucza.', 'Bunu kimseden karşılık beklemeden yapar.', 'وما لاحد عنده من نعمة تجزي'),
(6078, 92, 20, 'اِلَّا ابْتِغَٓاءَ وَجْهِ رَبِّهِ الْاَعْلٰىۚ', 'İllebtigae vechi rabbihil a\'la.', 'İsteği yalnızca Yüce Rabb\'inin rızasını kazanmaktır.', 'الا ابتغا وجه ربه الاعلي'),
(6079, 92, 21, 'وَلَسَوْفَ يَرْضٰى', 'Ve le sevfe yerda.', 'Yakında mutlaka hoşnut olacaktır.', 'ولسوف يرضي'),
(6080, 93, 1, 'وَالضُّحٰىۙ', 'Ved duha.', 'Duha[1] vaktine ant olsun.', 'والضحي'),
(6081, 93, 2, 'وَالَّيْلِ اِذَا سَجٰىۙ', 'Vel leyli iza seca.', 'Gecenin karanlıktaki dinginliğine,', 'واليل اذا سجي'),
(6082, 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰىۜ', 'Ma veddeake rabbuke ve ma kala.', 'Rabb\'in seni bırakmadı ve sana darılmadı.', 'ما ودعك ربك وما قلي'),
(6083, 93, 4, 'وَلَلْاٰخِرَةُ خَيْرٌ لَكَ مِنَ الْاُو۫لٰىۜ', 'Ve lel ahıretu hayrun leke minel ula.', 'Senin için gelecek,  geçmişten hayırlı olacak.', 'وللاخرة خير لك من الاولي'),
(6084, 93, 5, 'وَلَسَوْفَ يُعْط۪يكَ رَبُّكَ فَتَـرْضٰىۜ', 'Ve le sevfe yu\'tike rabbuke fe terda.', 'Yakında Rabb\'in sana verecek,  sen de hoşnut olacaksın.', 'ولسوف يعطيك ربك فترضي'),
(6085, 93, 6, 'اَلَمْ يَجِدْكَ يَت۪ـيـماً فَاٰوٰىۖ', 'E lem yecidke yetimen fe ava.', 'Seni yetim bulup,  barındırmadı mı?', 'الم يجدك يتيما فاوي'),
(6086, 93, 7, 'وَوَجَدَكَ ضَٓالاًّ فَهَدٰىۖ', 'Ve vecedeke dallen fe heda.', 'Seni şaşırmış bulup,  doğru yolu göstermedi mi?', 'ووجدك ضالا فهدي'),
(6087, 93, 8, 'وَوَجَدَكَ عَٓائِلاً فَاَغْنٰىۜ', 'Ve vecedeke ailen fe agna.', 'Seni muhtaç durumda bulup ğına[1] etmedi mi?', 'ووجدك عايلا فاغني'),
(6088, 93, 9, 'فَاَمَّا الْيَت۪يمَ فَلَا تَقْهَرْۜ', 'Fe emmel yetime fe la takher.', 'Öyleyse sakın yetimi[1] hor görme.[2]', 'فاما اليتيم فلا تقهر'),
(6089, 93, 10, 'وَاَمَّا السَّٓائِلَ فَلَا تَنْهَرْۜ', 'Ve emmes saile fe la tenher.', 'Sakın isteyeni[1] geri çevirme.', 'واما السايل فلا تنهر'),
(6090, 93, 11, 'وَاَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 'Ve emma bi ni\'meti rabbike fe haddis.', 'Ve Rabb\'inin nimetini[1] her fırsatta hadis et.[2]', 'واما بنعمة ربك فحدث'),
(6091, 94, 1, 'اَلَمْ نَشْرَحْ لَكَ صَدْرَكَۙ', 'E lem neşrah leke sadrek.', 'Senin için göğsünü açmadık mı?[1]', 'الم نشرح لك صدرك'),
(6092, 94, 2, 'وَوَضَعْنَا عَنْكَ وِزْرَكَۙ', 'Ve vedagna anke vizrek.', 'Yükünü üzerinden atmadık mı?[1]', 'ووضعنا عنك وزرك'),
(6093, 94, 3, 'اَلَّـذ۪ٓي اَنْقَضَ ظَهْرَكَۙ', 'Ellezi enkada zahrek.', 'Belini büken yükünü?[1]', 'الذي انقض ظهرك'),
(6094, 94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَۜ', 'Ve refa\'na leke zikrek.', 'Senin zikrini yükseltmedik mi?[1]', 'ورفعنا لك ذكرك'),
(6095, 94, 5, 'فَاِنَّ مَعَ الْعُسْرِ يُسْراًۙ', 'Fe inne maal usri yusra.', 'Zira zorlukla beraber bir kolaylık vardır.', 'فان مع العسر يسرا'),
(6096, 94, 6, 'اِنَّ مَعَ الْعُسْرِ يُسْراًۜ', 'İnne maal usri yusra.', 'Elbette zorlukla beraber bir kolaylık vardır.', 'ان مع العسر يسرا'),
(6097, 94, 7, 'فَاِذَا فَرَغْتَ فَانْصَبْۙ', 'Fe iza feragte fensab.', 'O halde her fırsatta kararlılıkla yeni şeyler yapmaya giriş.', 'فاذا فرغت فانصب'),
(6098, 94, 8, 'وَاِلٰى رَبِّكَ فَارْغَبْ', 'Ve ila rabbike fergab.', 'Ve yalnızca Rabb\'ine yönel.[1]', 'والي ربك فارغب'),
(6099, 95, 1, 'وَالتّ۪ينِ وَالزَّيْتُونِۙ', 'Vet tini vez zeytun.', 'İncire ve zeytine ant olsun,', 'والتين والزيتون'),
(6100, 95, 2, 'وَطُورِ س۪ين۪ينَۙ', 'Ve turi sinin.', 'Ve Sina Dağı\'na[1],', 'وطور سينين'),
(6101, 95, 3, 'وَهٰذَا الْبَلَدِ الْاَم۪ينِۙ', 'Ve hazel beledil emin.', 'Ve bu güvenli kente.', 'وهذا البلد الامين'),
(6102, 95, 4, 'لَقَدْ خَلَقْنَا الْاِنْسَانَ ف۪ٓي اَحْسَنِ تَقْو۪يمٍۘ', 'Lekad halaknel insane fi ahseni takvim.', 'Ant olsun ki insanı en iyi biçimde yarattık.', 'لقد خلقنا الانسن في احسن تقويم'),
(6103, 95, 5, 'ثُمَّ رَدَدْنَاهُ اَسْفَلَ سَافِل۪ينَۙ', 'Summe redednahu esfele safilin.', 'Sonra onu aşağıların aşağısına indirdik.', 'ثم رددنه اسفل سفلين'),
(6104, 95, 6, 'اِلَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ اَجْرٌ غَيْرُ مَمْنُونٍۜ', 'İllellezine amenu ve amilus salihati fe lehum ecrun gayru memnun.', 'Ancak iman eden ve salihatı yapanlar[1] hariç. Onlar için minnet altında bırakmayan bir ödül vardır.', 'الا الذين امنوا وعملوا الصلحت فلهم اجر غير ممنون'),
(6105, 95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِالدّ۪ينِۜ', 'Fe ma yukezzibuke ba\'du bid din.', 'Hal böyleyken,  sana[1] dini[2] yalanlatan nedir?', 'فما يكذبك بعد بالدين'),
(6106, 95, 8, 'اَلَيْسَ اللّٰهُ بِاَحْكَمِ الْحَاكِم۪ينَ', 'E leysallahu bi ahkemil hakimin.', 'Allah; hüküm verenlerin,  en iyi hüküm vereni değil mi?', 'اليس الله باحكم الحكمين'),
(6107, 96, 1, 'اِقْرَأْ بِاسْمِ رَبِّكَ الَّذ۪ي خَلَقَۚ', 'Ikra\'bismi rabbikellezi halak.', 'Yaratan Rabb\'inin adıyla duyur.[1]', 'اقرا باسم ربك الذي خلق'),
(6108, 96, 2, 'خَلَقَ الْاِنْسَانَ مِنْ عَلَقٍۚ', 'Halakal insane min alak.', 'İnsanı alaktan[1] yarattı.', 'خلق الانسن من علق'),
(6109, 96, 3, 'اِقْرَأْ وَرَبُّكَ الْاَكْرَمُۙ', 'Ikra\' ve rabbukel ekrem.', 'Duyur,  senin Rabb\'in en büyük kerem[1] sahibidir.', 'اقرا وربك الاكرم'),
(6110, 96, 4, 'اَلَّذ۪ي عَلَّمَ بِالْقَلَمِۙ', 'Ellezi alleme bil kalem.', 'Kalemle öğretendir.', 'الذي علم بالقلم'),
(6111, 96, 5, 'عَلَّمَ الْاِنْسَانَ مَا لَمْ يَعْلَمْۜ', 'Allemel insane ma lem ya\'lem.', 'İnsana bilmediğini öğretti.', 'علم الانسن ما لم يعلم'),
(6112, 96, 6, 'كَلَّٓا اِنَّ الْاِنْسَانَ لَيَطْغٰىۙ', 'Kella innel insane le yatga.', 'Bu gerçeğe rağmen insan yine de tuğyan[1] eder.', 'كلا ان الانسن ليطغي'),
(6113, 96, 7, 'اَنْ رَاٰهُ اسْتَغْنٰىۜ', 'En reahustagna.', 'Kendisini yeterli gördüğü için.', 'ان راه استغني'),
(6114, 96, 8, 'اِنَّ اِلٰى رَبِّكَ الرُّجْعٰىۜ', 'İnne ila rabbiker ruc\'a.', 'Oysaki dönüş Rabb\'inedir.', 'ان الي ربك الرجعي'),
(6115, 96, 9, 'اَرَاَيْتَ الَّذ۪ي يَنْهٰىۙ', 'E reeytellezi yenha.', 'Gördün mü şu alıkoyanı?', 'اريت الذي ينهي'),
(6116, 96, 10, 'عَبْداً اِذَا صَلّٰىۜ', 'Abden iza salla.', 'Salla[1] ederken bir kulu!', 'عبدا اذا صلي'),
(6117, 96, 11, 'اَرَاَيْتَ اِنْ كَانَ عَلَى الْهُدٰىۙ', 'E reeyte in kane alel huda.', 'Gördün mü?[1] Ya o doğru yolda ise!', 'اريت ان كان علي الهدي'),
(6118, 96, 12, 'اَوْ اَمَرَ بِالتَّقْوٰىۜ', 'Ev emera bit takva.', 'Veya takvayı[1] buyuruyorsa?', 'او امر بالتقوي'),
(6119, 96, 13, 'اَرَاَيْتَ اِنْ كَذَّبَ وَتَوَلّٰىۜ', 'E reeyte in kezzebe ve tevella.', 'Gördün mü; ya yalanlayıp ve yüz çevirdi ise?[1]', 'اريت ان كذب وتولي'),
(6120, 96, 14, 'اَلَمْ يَعْلَمْ بِاَنَّ اللّٰهَ يَرٰىۜ', 'E lem ya\'lem bi ennellahe yera.', 'Allah\'ın kesinlikle her şeyi gördüğünü bilmiyor mu?', 'الم يعلم بان الله يري'),
(6121, 96, 15, 'كَلَّا لَئِنْ لَمْ يَنْتَهِ۬ لَنَسْفَعاً بِالنَّاصِيَةِۙ', 'Kella le in lem yentehi le nesfean bin nasıyeh.', 'Hayır,  kesinlikle öyle değil! Eğer gerçekten vazgeçmezse perçeminden[1] yakalarız.', 'كلا لين لم ينته لنسفعا بالناصية'),
(6122, 96, 16, 'نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍۚ', 'Nasiyetin kazibetin hatıeh.', 'Yalancı ve yanlış yapan perçeminden.', 'ناصية كذبة خاطية'),
(6123, 96, 17, 'فَلْيَدْعُ نَادِيَهُۙ', 'Felyed\'u nadiyeh.', 'Haydi,  yardımcılarını çağırsın.', 'فليدع ناديه'),
(6124, 96, 18, 'سَنَدْعُ الزَّبَانِيَةَۙ', 'Sened\'uz zebaniyeh.', 'Biz de zebanileri çağıracağız.', 'سندع الزبانية'),
(6125, 96, 19, 'كَلَّاۜ  لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ', 'Kella, la tutı\'hu vescud vakterib.', 'Hayır,  kesinlikle öyle değil! Ona boyun eğme; secde et ve yaklaş[1].', 'كلا لا تطعه واسجد واقترب'),
(6126, 97, 1, 'اِنَّٓا اَنْزَلْنَاهُ ف۪ي لَيْلَةِ الْقَدْرِۚ', 'İnna enzelnahu fi leyletil kadr.', 'Kuşkusuz Biz onu[1] kad\'r gecesinde[2] indirdik.', 'انا انزلنه في ليلة القدر'),
(6127, 97, 2, 'وَمَٓا اَدْرٰيكَ مَا لَيْلَةُ الْقَدْرِۜ', 'Ve ma edrake ma leyletul kadr.', 'Kad\'r gecesinin ne olduğunu sana bildiren nedir?', 'وما ادريك ما ليلة القدر'),
(6128, 97, 3, 'لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ اَلْفِ شَهْرٍۜ', 'Leyletul kadri hayrun min elfi şehr.', 'Kad\'r gecesi bin aydan daha hayırlıdır.[1]', 'ليلة القدر خير من الف شهر'),
(6129, 97, 4, 'تَنَزَّلُ الْمَلٰٓئِكَةُ وَالرُّوحُ ف۪يهَا بِاِذْنِ رَبِّهِمْۚ مِنْ كُلِّ اَمْرٍۙۛ', 'Tenezzelul melaiketu ver ruhu fiha bi izni rabbihim min kulli emrin.', 'Melekler[1] ve ruh[2],  onda Rabb\'lerinin izniyle[3] her bir emir için iner de iner.', 'تنزل المليكة والروح فيها باذن ربهم من كل امر'),
(6130, 97, 5, 'سَلَامٌ۠ۛ هِيَ حَتّٰى مَطْلَعِ الْفَجْرِ', 'Selamun, hiye hatta matlaıl fecr.', 'O,  fecrin ağarmasına[1] kadar selamdır.[2]', 'سلم هي حتي مطلع الفجر'),
(6131, 98, 1, 'لَمْ يَكُنِ الَّذ۪ينَ كَفَرُوا مِنْ اَهْلِ الْـكِتَابِ وَالْمُشْرِك۪ينَ مُنْفَكّ۪ينَ حَتّٰى تَأْتِيَهُمُ الْبَيِّنَةُۙ', 'Lem yekunillizine keferu min ehlil kitabi vel muşrikine munfekkine hatta te\'tiye humul beyyineh.', 'Kitap Ehli\'nden ve Müşriklerden Kafirler[1] kendilerine beyyine[2] gelmeden ayrılığa düşmüş değillerdi.', 'لم يكن الذين كفروا من اهل الكتب والمشركين منفكين حتي تاتيهم البينة'),
(6132, 98, 2, 'رَسُولٌ مِنَ اللّٰهِ يَتْلُوا صُحُفاً مُطَهَّرَةًۙ', 'Resulun minallahi yetlu suhufen mutahharah.', 'Allah\'tan gelen dokunulmamış sahifelerden okuyan bir resul.', 'رسول من الله يتلوا صحفا مطهرة'),
(6133, 98, 3, 'ف۪يهَا كُتُبٌ قَيِّمَةٌۜ', 'Fiha kutubun kayyimeh.', 'Onda değerli kitaplar[1] vardır.', 'فيها كتب قيمة'),
(6134, 98, 4, 'وَمَا تَفَرَّقَ الَّذ۪ينَ اُو۫تُوا الْـكِتَابَ اِلَّا مِنْ بَعْدِ مَا جَٓاءَتْهُمُ الْبَيِّنَةُۜ', 'Ve ma teferrekallezine utul kitabe illa min ba\'di ma caet humul beyyineh.', 'Kitap verilmiş olanlar,  kendilerine beyyine[1] geldikten sonra ayrılığa düştüler.[2]', 'وما تفرق الذين اوتوا الكتب الا من بعد ما جاتهم البينة'),
(6135, 98, 5, 'وَمَٓا اُمِرُٓوا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِص۪ينَ لَهُ الدّ۪ينَ حُنَفَٓاءَ وَيُق۪يمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ د۪ينُ الْقَيِّمَةِۜ', 'Ve ma umiru illa li ya\'budullahe muhlisine lehud dine hunefae ve yukimus salate ve yu\'tuz zekate ve zalike dinul kayyimeh.', 'Oysa Allah\'a kulluktan ve dini hanifler[1] olarak O\'na has kılmaktan ve salatı ikame etmekten[2],  zekatı yapmaktan[2] başka bir şeyle emrolunmadılar. İşte doğru din budur.', 'وما امروا الا ليعبدوا الله مخلصين له الدين حنفا ويقيموا الصلوة ويوتوا الزكوة وذلك دين القيمة'),
(6136, 98, 6, 'اِنَّ الَّذ۪ينَ كَفَرُوا مِنْ اَهْلِ الْـكِتَابِ وَالْمُشْرِك۪ينَ ف۪ي نَارِ جَهَنَّمَ خَالِد۪ينَ ف۪يهَاۜ  اُو۬لٰٓئِكَ هُمْ شَرُّ الْبَرِيَّةِۜ', 'İnnellezine keferu min ehlil kitabi velmuşrikine fi nari cehenneme halidine fiha, ulaike hum şerrul beriyeh.', 'Kitap Ehli\'nden gerçeği yalanlayan nankörler ve müşrikler,  içinde sürekli kalmak üzere Cehennem ateşindedirler. İşte onlar,  yaratılmışların şerlileridirler.', 'ان الذين كفروا من اهل الكتب والمشركين في نار جهنم خلدين فيها اوليك هم شر البرية'),
(6137, 98, 7, 'اِنَّ الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِۙ اُو۬لٰٓئِكَ هُمْ خَيْرُ الْبَرِيَّةِۜ', 'İnnellezine amenu ve amilus salihati ulaike hum hayrul beriyyeh.', 'İman eden ve salihatı yapan kimseler; işte onlar yaratılanların hayırlı olanlarıdır.', 'ان الذين امنوا وعملوا الصلحت اوليك هم خير البرية'),
(6138, 98, 8, 'جَزَٓاؤُ۬هُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْر۪ي مِنْ تَحْتِهَا الْاَنْهَارُ خَالِد۪ينَ ف۪يهَٓا اَبَداًۜ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوا عَنْهُۜ ذٰلِكَ لِمَنْ خَشِيَ رَبَّهُ', 'Cezauhum inde rabbihim cennatu adnin tecri min tahtihel enharu halidine fiha ebeda, radıyallahu anhum ve radu anh, zalike li men haşiye rabbeh.', 'Onların,  Rabb\'leri yanındaki ödülleri; onlar için içinden nehirlerin aktığı cennetler vardır. Orada süresiz kalacaklar. Allah onlardan,  onlar da O\'ndan razı olmuşlardır.  İşte bu,  Rabb\'ine huşu[1] duyan kimseler içindir.', 'جزاوهم عند ربهم جنت عدن تجري من تحتها الانهر خلدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه'),
(6139, 99, 1, 'اِذَا زُلْزِلَتِ الْاَرْضُ زِلْزَالَهَاۙ', 'İza zulziletil ardu zilzaleha.', 'Yeryüzü şiddetli sarsıntı ile sarsıldığı zaman,', 'اذا زلزلت الارض زلزالها'),
(6140, 99, 2, 'وَاَخْرَجَتِ الْاَرْضُ اَثْقَالَهَاۙ', 'Ve ahrecetil ardu eskaleha.', 'Yeryüzü ağırlıklarını çıkardığı;', 'واخرجت الارض اثقالها'),
(6141, 99, 3, 'وَقَالَ الْاِنْسَانُ مَا لَهَاۚ', 'Ve kalel insanu ma leha.', 'Ve insan,  \"Ona ne oluyor?\" dediği,', 'وقال الانسن ما لها'),
(6142, 99, 4, 'يَوْمَئِذٍ تُحَدِّثُ اَخْبَارَهَاۙ', 'Yevme izin tuhaddisu ahbareha.', 'İzin Günü[1],  hadislerini[2] anlatacak.[3]', 'يوميذ تحدث اخبارها'),
(6143, 99, 5, 'بِاَنَّ رَبَّكَ اَوْحٰى لَهَاۜ', 'Bi enne rabbeke evhaleha.', 'Çünkü Rabb\'in ona vahyetmiştir.[1]', 'بان ربك اوحي لها'),
(6144, 99, 6, 'يَوْمَئِذٍ يَصْدُرُ النَّاسُ اَشْتَاتاً لِيُرَوْا اَعْمَالَهُمْۜ', 'Yevme izin yasdurun nasu eştaten li yurev a\'malehum.', 'İzin Günü,  insanlar amelleri kendilerine gösterilsin diye grup grup ortaya çıkacaklar.', 'يوميذ يصدر الناس اشتاتا ليروا اعملهم'),
(6145, 99, 7, 'فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُۜ', 'Fe men ya\'mel miskale zerretin hayren yereh.', 'Artık kim zerre ağırlığınca iyilik yapmışsa onu görür.', 'فمن يعمل مثقال ذرة خيرا يره'),
(6146, 99, 8, 'وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَراًّ يَرَهُ', 'Ve men ya\'mel miskale zerretin şerren yereh.', 'Ve kim zerre ağırlığınca kötülük yapmışsa onu görür.', 'ومن يعمل مثقال ذرة شرا يره'),
(6147, 100, 1, 'وَالْعَـادِيَاتِ ضَبْـحاًۙ', 'Vel adiyati dabha.', 'Soluk soluğa koşanlara ant olsun,', 'والعديت ضبحا'),
(6148, 100, 2, 'فَالْمُـورِيَاتِ قَـدْحاًۙ', 'Fel muriyati kadha.', 'Çarparak ateş çıkaranlara,', 'فالموريت قدحا'),
(6149, 100, 3, 'فَالْمُغ۪يرَاتِ صُبْحاًۙ', 'Fel mugirati subha.', 'Sabahleyin akın edenlere,', 'فالمغيرت صبحا'),
(6150, 100, 4, 'فَاَثَرْنَ بِه۪ نَقْعاًۙ', 'Fe eserne bihi nak\'a.', 'Sonra toz koparanlara,', 'فاثرن به نقعا'),
(6151, 100, 5, 'فَوَسَطْنَ بِه۪ جَمْعاًۙ', 'Fe vesatne bihi cem\'a.', 'Sonra onunla bir topluluğa dalanlara ki,', 'فوسطن به جمعا'),
(6152, 100, 6, 'اِنَّ الْاِنْسَانَ لِرَبِّه۪ لَكَنُودٌۚ', 'İnnel insane li rabbihi le kenud.', 'Kuşkusuz o insan[1] Rabb\'ine karşı çok nankördür.', 'ان الانسن لربه لكنود'),
(6153, 100, 7, 'وَاِنَّهُ عَلٰى ذٰلِكَ لَشَه۪يدٌۚ', 'Ve innehu ala zalike le şehid.', 'Ve o[1] da buna tanıktır.[2]', 'وانه علي ذلك لشهيد'),
(6154, 100, 8, 'وَاِنَّهُ لِحُبِّ الْخَيْرِ لَشَد۪يدٌۜ', 'Ve innehu li hubbil hayri le şedid.', 'Doğrusu o hayrı[1] aşırı derecede sever.', 'وانه لحب الخير لشديد'),
(6155, 100, 9, 'اَفَلَا يَعْلَمُ اِذَا بُعْثِرَ مَا فِي الْقُبُورِۙ', 'E fe la ya\'lemu iza bu\'sirama fil kubur.', 'Bilmez mi kabirlerde olanlar çıkarıldığı zaman,', 'افلا يعلم اذا بعثر ما في القبور'),
(6156, 100, 10, 'وَحُصِّلَ مَا فِي الصُّدُورِۙ', 'Ve hussıle ma fis sudur.', 'Ve göğüslerde olanlar açığa çıkarıldığı zaman,', 'وحصل ما في الصدور'),
(6157, 100, 11, 'اِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَب۪يرٌ', 'İnne rabbehum bihim yevme izin le habir.', 'İzin Günü Rabb\'lerinin her şeylerinden haberdar olduğunu.', 'ان ربهم بهم يوميذ لخبير'),
(6158, 101, 1, 'اَلْقَارِعَةُۙ', 'El kariah.', 'Kari\'a.[1]', 'القارعة');
INSERT INTO `ayahs` (`id`, `surah_id`, `ayah_number`, `arabic_text`, `transcription`, `translation`, `mushaf_ayah`) VALUES
(6159, 101, 2, 'مَا الْقَارِعَةُۚ', 'Mel kariah.', 'Kari\'a nedir?', 'ما القارعة'),
(6160, 101, 3, 'وَمَٓا اَدْرٰيكَ مَا الْقَارِعَةُۜ', 'Ve ma edrake mel kariah.', 'Karia\'nın ne olduğunu sen nereden bileceksin?', 'وما ادريك ما القارعة'),
(6161, 101, 4, 'يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِۙ', 'Yevme yekunun nasu kel feraşil mebsus.', 'O gün insanlar sağa sola uçuşan pervaneler[1] gibi olurlar.', 'يوم يكون الناس كالفراش المبثوث'),
(6162, 101, 5, 'وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِۜ', 'Ve tekunul cibalu kel ıhnil menfuş.', 'Dağlar etrafa saçılmış renkli yün gibi olur.', 'وتكون الجبال كالعهن المنفوش'),
(6163, 101, 6, 'فَاَمَّا مَنْ ثَقُلَتْ مَوَاز۪ينُهُۙ', 'Fe emma men sekulet mevazinuh.', 'Kimin tartısı ağır gelirse, [1]', 'فاما من ثقلت موزينه'),
(6164, 101, 7, 'فَهُوَ ف۪ي ع۪يشَةٍ رَاضِيَةٍۜ', 'Fe huve fi işetin radiyeh.', 'O hoşnut edici bir yaşayış içindedir.', 'فهو في عيشة راضية'),
(6165, 101, 8, 'وَاَمَّا مَنْ خَفَّتْ مَوَاز۪ينُهُۙ', 'Ve emma men haffet mevazinuh.', 'Kimin tartısı hafif gelirse, [1]', 'واما من خفت موزينه'),
(6166, 101, 9, 'فَاُمُّهُ هَاوِيَةٌۜ', 'Fe ummuhu haviyeh.', 'Artık onun anası haviyedir.', 'فامه هاوية'),
(6167, 101, 10, 'وَمَٓا اَدْرٰيكَ مَا هِيَهْۜ', 'Ve ma edrake mahiyeh.', 'Onun ne olduğunu sen nereden bileceksin?', 'وما ادريك ما هيه'),
(6168, 101, 11, 'نَارٌ حَامِيَةٌ', 'Narun hamiyeh.', 'O,  kızgın bir ateştir.', 'نار حامية'),
(6169, 102, 1, 'اَلْهٰيكُمُ التَّكَاثُرُۙ', 'Elhakumut tekasur.', 'Çoğaltma isteği sizi oyaladı.[1]', 'الهيكم التكاثر'),
(6170, 102, 2, 'حَتّٰى زُرْتُمُ الْمَقَابِرَۜ', 'Hatta zurtumul mekabir.', 'Ta ki ölüp kabirlere girinceye kadar.', 'حتي زرتم المقابر'),
(6171, 102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَۙ', 'Kella sevfe ta\'lemun.', 'Hayır,  asla bildiğiniz gibi değil; yakında bileceksiniz.', 'كلا سوف تعلمون'),
(6172, 102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَۜ', 'Summe kella sevfe ta\'lemun.', 'Yine hayır,  bildiğiniz gibi değil; yakında bileceksiniz.', 'ثم كلا سوف تعلمون'),
(6173, 102, 5, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَق۪ينِۜ', 'Kella lev ta\'lemune ilmel yakin.', 'Hayır,  asla bildiğiniz gibi değil,  keşke kesin bilgi ile bilseydiniz.', 'كلا لو تعلمون علم اليقين'),
(6174, 102, 6, 'لَتَرَوُنَّ الْجَح۪يمَۙ', 'Le terevunnel cahim.', 'Bilesiniz ki kesinlikle alevli ateşle karşı karşıya kalacaksınız.', 'لترون الجحيم'),
(6175, 102, 7, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَق۪ينِۙ', 'Summe le terevunneha aynel yakin.', 'Sonra onu gözlerinizle kesin olarak göreceksiniz.', 'ثم لترونها عين اليقين'),
(6176, 102, 8, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ النَّع۪يمِ', 'Summe le tus\'elunne yevmeizin anin naim.', 'Sonra İzin Günü kesinlikle nimetten[1] sorulacaksınız.', 'ثم لتسلن يوميذ عن النعيم'),
(6177, 103, 1, 'وَالْعَصْرِۙ', 'Vel asr.', 'Asra[1] ant olsun,', 'والعصر'),
(6178, 103, 2, 'اِنَّ الْاِنْسَانَ لَف۪ي خُسْرٍۙ', 'İnnel insane le fi husr.', 'Kuşkusuz o insan kesinlikle hüsrandadır.', 'ان الانسن لفي خسر'),
(6179, 103, 3, 'اِلَّا الَّذ۪ينَ اٰمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ', 'İllellezine amenu ve amilus salihati ve tevasav bil hakkı ve tevasav bis sabr.', 'Ancak inananlar,  salihatı[1] yapanlar,  hakkı tavsiye edenler ve sabrı tavsiye edenler hariç.', 'الا الذين امنوا وعملوا الصلحت وتواصوا بالحق وتواصوا بالصبر'),
(6180, 104, 1, 'وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍۨۙ', 'Veylun li kulli humezetin lumezeh.', 'Arkadan çekiştirenlerin,  kaş göz hareketiyle alay edenlerin vay haline![1]', 'ويل لكل همزة لمزة'),
(6181, 104, 2, 'اَلَّذ۪ي جَمَعَ مَالاً وَعَدَّدَهُۙ', 'Ellezi cemea malen ve addedeh.', 'O ki malı toplayıp,  onun hesabını yapıp durur.', 'الذي جمع مالا وعدده'),
(6182, 104, 3, 'يَحْسَبُ اَنَّ مَالَهُٓ اَخْلَدَهُۚ', 'Yahsebu enne malehu ahledeh.', 'Malın kendisini sonsuza dek yaşatacağını sanıyor.', 'يحسب ان ماله اخلده'),
(6183, 104, 4, 'كَلَّا لَيُنْبَذَنَّ فِي الْحُطَمَةِۘ', 'Kella le yunbezenne fil hutameh.', 'Hayır,  kesinlikle bildiği gibi değil,  kesinlikle o hutameye atılacak.', 'كلا لينبذن في الحطمة'),
(6184, 104, 5, 'وَمَٓا اَدْرٰيكَ مَا الْحُطَمَةُۜ', 'Ve ma edrake mel hutameh.', 'Hutamenin ne olduğunu sen nereden bileceksin?', 'وما ادريك ما الحطمة'),
(6185, 104, 6, 'نَارُ اللّٰهِ الْمُوقَدَةُۙ', 'Narullahil mukadeh.', 'Allah\'ın tutuşturulmuş ateşidir.', 'نار الله الموقدة'),
(6186, 104, 7, 'اَلَّت۪ي تَطَّلِعُ عَلَى الْاَفْـِٔدَةِۜ', 'Elleti tettaliu alel ef\'ideh.', 'Yüreklere işleyen bir ateş.', 'التي تطلع علي الافدة'),
(6187, 104, 8, 'اِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌۙ', 'İnneha aleyhim mu\'sadeh.', 'Kuşkusuz o,  onların üzerine kapatılmıştır.', 'انها عليهم موصدة'),
(6188, 104, 9, 'ف۪ي عَمَدٍ مُمَدَّدَةٍ', 'Fi amedin mumeddedeh.', 'Uzatılmış sütunlar arasında.', 'في عمد ممددة'),
(6189, 105, 1, 'اَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِاَصْحَابِ الْف۪يلِۜ', 'E lem tere keyfe feale rabbuke bi ashabil fil.', 'Görmədinmi? Rəbb\'in fil sahiplərinə necə etdi?', 'الم تر كيف فعل ربك باصحب الفيل'),
(6190, 105, 2, 'اَلَمْ يَجْعَلْ كَيْدَهُمْ ف۪ي تَضْل۪يلٍۙ', 'E lem yec\'al keydehum fi tadlil.', 'Onların diləyini zəlil olmada təyin etmədimi?', 'الم يجعل كيدهم في تضليل'),
(6191, 105, 3, 'وَاَرْسَلَ عَلَيْهِمْ طَيْراً اَبَاب۪يلَۙ', 'Ve ersele aleyhim tayren ebabil.', 'Onların üzərlərində sürü-sürü quşlar göndərdi;', 'وارسل عليهم طيرا ابابيل'),
(6192, 105, 4, 'تَرْم۪يهِمْ بِحِجَارَةٍ مِنْ سِجّ۪يلٍۖۙ', 'Termihim bi hicaretin min siccil.', 'Onlara palçıqdan sərtləşmiş daşlar atır.', 'ترميهم بحجارة من سجيل'),
(6193, 105, 5, 'فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ', 'Fe cealehum keasfin me\'kul.', 'Beləcə onları yeyilən sovrulma kimi təyin etdi.', 'فجعلهم كعصف ماكول'),
(6194, 106, 1, 'لِا۪يلَافِ قُرَيْشٍۙ', 'Li ilafi kureyş.', 'Kureyş\'i alıştırdığı için[1];', 'لايلف قريش'),
(6195, 106, 2, 'ا۪يلَافِهِمْ رِحْلَةَ الشِّتَٓاءِ وَالصَّيْفِۚ', 'İlafihim rıhleteş şitai ves sayf.', 'Onları kış ve yaz yolculuğuna alıştırdığı[1] için;', 'الفهم رحلة الشتا والصيف'),
(6196, 106, 3, 'فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِۙ', 'Fel ya\'budu rabbe hazel beyt.', 'Bu evin[1] Rabb\'ine kulluk[1] etsinler.', 'فليعبدوا رب هذا البيت'),
(6197, 106, 4, 'اَلَّذ۪ٓي اَطْعَمَهُمْ مِنْ جُوعٍ وَاٰمَنَهُمْ مِنْ خَوْفٍ', 'Ellezi at\'amehum min cuın ve amenehum min havf.', 'Onları yedirip açlıktan korudu ve onları korkudan güvene kavuşturdu.', 'الذي اطعمهم من جوع وامنهم من خوف'),
(6198, 107, 1, 'اَرَاَيْتَ الَّذ۪ي يُكَذِّبُ بِالدّ۪ينِۜ', 'E raeytellezi yukezzibu bid din.', 'Dini[1] yalanlayanı görüyorsun değil mi?', 'اريت الذي يكذب بالدين'),
(6199, 107, 2, 'فَذٰلِكَ الَّذ۪ي يَدُعُّ الْيَت۪يمَۙ', ': Fe zalikellezi yedu\'ul yetim.', 'İşte o,  yetimi itip kakar.', 'فذلك الذي يدع اليتيم'),
(6200, 107, 3, 'وَلَا يَحُضُّ عَلٰى طَعَامِ الْمِسْك۪ينِۜ', 'Ve la yahuddu ala taamil miskin.', 'Miskini doyurmaya teşvik etmez.[1]', 'ولا يحض علي طعام المسكين'),
(6201, 107, 4, 'فَوَيْلٌ لِلْمُصَلّ۪ينَۙ', 'Fe veylun lil musallin.', 'Vay haline salat edenlerin![1]', 'فويل للمصلين'),
(6202, 107, 5, 'اَلَّذ۪ينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَۙ', 'Ellezine hum an salatihim sahun.', 'Onlar ki salatlarından[1] gafletteler.', 'الذين هم عن صلاتهم ساهون'),
(6203, 107, 6, 'اَلَّذ۪ينَ هُمْ يُرَٓاؤُ۫نَۙ', 'Ellezine hum yuraun.', 'Onlar gösteriş yapanlardır.', 'الذين هم يراون'),
(6204, 107, 7, 'وَيَمْنَعُونَ الْمَاعُونَ', 'Ve yemneunel maun.', 'Ve küçük,  basit,  sıradan yardımı bile esirgerler.', 'ويمنعون الماعون'),
(6205, 108, 1, 'اِنَّٓا اَعْطَيْنَاكَ الْـكَوْثَرَۜ', 'İnna a\'taynakel kevser.', 'Şübhəsiz biz sənə əta etdik kəvsəri', 'انا اعطينك الكوثر'),
(6206, 108, 2, 'فَصَلِّ لِرَبِّكَ وَانْحَرْۜ', 'Fe salli li rabbike venhar.', 'Elə isə rəbbin üçün salli et və nəhərə et', 'فصل لربك وانحر'),
(6207, 108, 3, 'اِنَّ شَانِئَكَ هُوَ الْاَبْتَرُ', 'İnne şanieke huvel ebter.', 'Şübhəsiz sənin nifrətçin o əbtərdir', 'ان شانيك هو الابتر'),
(6208, 109, 1, 'قُلْ يَٓا اَيُّهَا الْـكَافِرُونَۙ', 'Kul ya eyyuhel kafirun.', 'De ki: \"Ey kafirler.[1]\"', 'قل يايها الكفرون'),
(6209, 109, 2, 'لَٓا اَعْبُدُ مَا تَعْبُدُونَۙ', 'La a\'budu ma ta\'budun.', '\"Ben,  sizin kulluk[1] ettiğinize asla kulluk etmem.\"', 'لا اعبد ما تعبدون'),
(6210, 109, 3, 'وَلَٓا اَنْتُمْ عَابِدُونَ مَٓا اَعْبُدُۚ', 'Ve la entum abidune ma a\'bud.', '\"Siz de benim kulluk ettiğime kulluk etmezsiniz.\"', 'ولا انتم عبدون ما اعبد'),
(6211, 109, 4, 'وَلَٓا اَنَا۬ عَابِدٌ مَا عَبَدْتُمْۙ', 'Ve la ene abidun ma abedtum.', '\"Ben,  sizin kulluk ettiğinize asla kulluk edecek değilim.\"', 'ولا انا عابد ما عبدتم'),
(6212, 109, 5, 'وَلَٓا اَنْتُمْ عَابِدُونَ مَٓا اَعْبُدُۜ', 'Ve la entum abidune ma a\'bud.', '\"Siz de benim kulluk ettiğime kulluk edecek değilsiniz.\"', 'ولا انتم عبدون ما اعبد'),
(6213, 109, 6, 'لَـكُمْ د۪ينُكُمْ وَلِيَ د۪ينِ', 'Lekum dinukum ve liye din.', '\"Sizin dininiz[1] size,  benim dinim[1] de bana.\"', 'لكم دينكم ولي دين'),
(6214, 110, 1, 'اِذَا جَٓاءَ نَصْرُ اللّٰهِ وَالْفَتْحُۙ', 'İza cae nasrullahi vel feth.', 'Allah\'ın yardımı ve fetih geldiği zaman,', 'اذا جا نصر الله والفتح'),
(6215, 110, 2, 'وَرَاَيْتَ النَّاسَ يَدْخُلُونَ ف۪ي د۪ينِ اللّٰهِ اَفْوَاجاًۙ', 'Ve reeyten nase yedhulune fi dinillahi efvaca.', 'İnsanların Allah\'ın dinine dalga dalga girdiklerini gördüğün zaman,', 'ورايت الناس يدخلون في دين الله افواجا'),
(6216, 110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُۜ  اِنَّهُ  كَانَ تَوَّاباً', 'Fe sebbih bi hamdi rabbike vestagfirh, innehu kane tevvaba.', 'O zaman,  Rabb\'ini hamd[1] ile tesbih[2] et. Ve O\'ndan mağfiret[3] dile. Kuşkusuz O,  tevbeleri kabul edendir.', 'فسبح بحمد ربك واستغفره انه كان توابا'),
(6217, 111, 1, 'تَبَّتْ  يَدَٓا اَب۪ي لَهَبٍ وَتَبَّۜ', 'Tebbet yeda ebi lehebin ve tebb.', 'Ebu Leheb\'in iki eli[1] kurudu[2]. Ve kendisi de yok oldu[3].', 'تبت يدا ابي لهب وتب'),
(6218, 111, 2, 'مَٓا اَغْنٰى عَنْهُ مَالُهُ وَمَا كَسَبَۜ', 'Ma agna anhu maluhu ve ma keseb.', 'Malı da  kazandıkları da ona bir yarar sağlamadı.', 'ما اغني عنه ماله وما كسب'),
(6219, 111, 3, 'سَيَصْلٰى نَاراً ذَاتَ لَهَبٍۚ', 'Se yasla naren zate leheb.', 'Alevli ateşe atılacak.', 'سيصلي نارا ذات لهب'),
(6220, 111, 4, 'وَامْرَاَتُهُۜ  حَمَّالَةَ الْحَطَبِۚ', 'Vemreetuh, hammaletel hatab.', 'Odun hamalı karısı da.', 'وامراته حمالة الحطب'),
(6221, 111, 5, 'ف۪ي ج۪يدِهَا حَبْلٌ مِنْ مَسَدٍ', 'Fi cidiha hablun min mesed.', 'Boynunda liften bir urgan[1].', 'في جيدها حبل من مسد'),
(6222, 112, 1, 'قُلْ هُوَ اللّٰهُ اَحَدٌۚ', 'Kul huvallahu ehad.', 'De ki: \"O Allah[1] Ehad\'dır.[2]\"', 'قل هو الله احد'),
(6223, 112, 2, 'اَللّٰهُ الصَّمَدُۚ', 'Allahus samed.', '\"Allah Samed\'dir[1].\"', 'الله الصمد'),
(6224, 112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْۙ', 'Lem yelid ve lem yuled.', '\"Doğurmamış,  doğurulmamıştır.\"', 'لم يلد ولم يولد'),
(6225, 112, 4, 'وَلَمْ يَكُنْ لَهُ كُفُواً اَحَدٌ', 'Ve lem yekun lehu kufuven ehad.', '\"Hiçbir şey O\'nun dengi değildir[1].\"', 'ولم يكن له كفوا احد'),
(6226, 113, 1, 'قُلْ اَعُوذُ بِرَبِّ الْفَلَقِۙ', 'Kul euzu bi rabbil felak.', 'De ki: \"Felak\'ın[1] Rabb\'ine sığınırım.\"', 'قل اعوذ برب الفلق'),
(6227, 113, 2, 'مِنْ شَرِّ مَا خَلَقَۙ', 'Min şerri ma halak.', '\"Yarattığı şeylerin şerrinden, \"', 'من شر ما خلق'),
(6228, 113, 3, 'وَمِنْ شَرِّ غَاسِقٍ اِذَا وَقَبَۙ', 'Ve min şerri gasikın iza vekab.', '\"Ve çöktüğü zaman karanlığın[1] şerrinden, \"', 'ومن شر غاسق اذا وقب'),
(6229, 113, 4, 'وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِۙ', 'Ve min şerrin neffasati fil ukad.', '\"Düğümlere üfleyenlerin[1] şerrinden, \"', 'ومن شر النفثت في العقد'),
(6230, 113, 5, 'وَمِنْ شَرِّ حَاسِدٍ اِذَا حَسَدَ', 'Ve min şerri hasidin iza hased.', '\"Ve kıskandığı zaman,  kıskananın şerrinden.\"', 'ومن شر حاسد اذا حسد'),
(6231, 114, 1, 'قُلْ اَعُوذُ بِرَبِّ النَّاسِۙ', 'Qul euzu bi rabbin nas.', 'De: \"Nasların Rəbbinə sığınıram;\"', 'قل اعوذ برب الناس'),
(6232, 114, 2, 'مَلِكِ النَّاسِۙ', 'Melikin nas.', '\"Nasların məlikinə\"', 'ملك الناس'),
(6233, 114, 3, 'اِلٰهِ النَّاسِۙ', 'İlahin nas.', '\"Nasların İlahına.\"', 'اله الناس'),
(6234, 114, 4, 'مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِۙ', 'Min şerril vesvasil hannas.', '\"Hannasın vəsvəsəsinin şərrindən, \"', 'من شر الوسواس الخناس'),
(6235, 114, 5, 'اَلَّذ۪ي يُوَسْوِسُ ف۪ي صُدُورِ النَّاسِۙ', 'Ellezi yuvesvisu fi sudurin nas.', '\"O ki Nasların Sudurlarında vəsvəsə edir, \"', 'الذي يوسوس في صدور الناس'),
(6236, 114, 6, 'مِنَ الْجِنَّةِ وَالنَّاسِ', 'Minel cinneti ven nas.', '\"Cinlərdən və Naslardan.\"', 'من الجنة والناس');
